PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE preset_deck_levels (
  code TEXT PRIMARY KEY,
  list_code TEXT NOT NULL,
  label TEXT NOT NULL,
  description TEXT,
  position INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE preset_decks (
  code TEXT PRIMARY KEY,
  level_code TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  color TEXT NOT NULL,
  icon TEXT,
  position INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  FOREIGN KEY (level_code) REFERENCES preset_deck_levels(code)
);
CREATE TABLE preset_deck_cards (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  deck_code TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  english TEXT NOT NULL,
  vietnamese TEXT NOT NULL,
  part_of_speech TEXT,
  examples TEXT NOT NULL DEFAULT '[]',
  collocations TEXT NOT NULL DEFAULT '[]',
  notes TEXT, ipa TEXT, audio_src TEXT, image_url TEXT, image_attribution TEXT,
  UNIQUE (deck_code, english),
  FOREIGN KEY (deck_code) REFERENCES preset_decks(code)
);
