INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1,'ngsl-1-01',1,'say','nói; cho biết','verb','[{"en":"What did she say when you told her the news?","vi":"Cô ấy đã nói gì khi bạn báo tin cho cô ấy?","image_url":"https://images.pexels.com/photos/35467808/pexels-photo-35467808.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My doctor said I should drink more water.","vi":"Bác sĩ nói tôi nên uống nhiều nước hơn.","image_url":"https://images.pexels.com/photos/35232336/pexels-photo-35232336.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The sign says the museum is closed on Mondays.","vi":"Biển báo cho biết bảo tàng đóng cửa vào thứ Hai.","image_url":"https://images.pexels.com/photos/30253419/pexels-photo-30253419.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"say goodbye"},{"phrase":"say sorry"},{"phrase":"say something"},{"phrase":"say no"}]','say – said – said','/seɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/say/say__/say__us_1.mp3','https://images.pexels.com/photos/6037811/pexels-photo-6037811.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Brett Jordan","author_url":"https://www.pexels.com/@brettjordan","source_url":"https://www.pexels.com/photo/wooden-scrabbles-pieces-on-white-table-6037811/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2,'ngsl-1-01',2,'go','đi; diễn ra','verb','[{"en":"We usually go to the beach on weekends.","vi":"Chúng tôi thường đi biển vào cuối tuần.","image_url":"https://images.pexels.com/photos/10001094/pexels-photo-10001094.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She went home early because she felt tired.","vi":"Cô ấy về nhà sớm vì cảm thấy mệt.","image_url":"https://images.pexels.com/photos/17975075/pexels-photo-17975075.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"How did your job interview go yesterday?","vi":"Buổi phỏng vấn xin việc hôm qua của bạn diễn ra thế nào?","image_url":"https://images.pexels.com/photos/5922068/pexels-photo-5922068.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"go home"},{"phrase":"go to bed"},{"phrase":"go shopping"},{"phrase":"go to school"}]','go – went – gone','/ɡəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/go_/go__u/go__us_1.mp3','https://images.pexels.com/photos/5640497/pexels-photo-5640497.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Tima Miroshnichenko","author_url":"https://www.pexels.com/@tima-miroshnichenko","source_url":"https://www.pexels.com/photo/man-in-white-helmet-riding-on-go-kart-5640497/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3,'ngsl-1-01',3,'know','biết; quen biết','verb','[{"en":"Do you know where the nearest bus stop is?","vi":"Bạn có biết trạm xe buýt gần nhất ở đâu không?","image_url":"https://images.pexels.com/photos/16252896/pexels-photo-16252896.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She didn''t know the answer, so she asked her teacher.","vi":"Cô ấy không biết câu trả lời nên đã hỏi giáo viên.","image_url":"https://images.pexels.com/photos/4936021/pexels-photo-4936021.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I have known my best friend since elementary school.","vi":"Tôi quen người bạn thân nhất của mình từ hồi tiểu học.","image_url":"https://images.pexels.com/photos/5896631/pexels-photo-5896631.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"know the answer"},{"phrase":"get to know"},{"phrase":"let me know"}]','know – knew – known','/nəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kno/know_/know__us_1.mp3','https://images.pexels.com/photos/37549154/pexels-photo-37549154.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Giant Asparagus","author_url":"https://www.pexels.com/@giantasparagus","source_url":"https://www.pexels.com/photo/solar-powered-surveillance-camera-on-street-pole-37549154/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4,'ngsl-1-01',4,'more','nhiều hơn; thêm','determiner','[{"en":"We need more time to finish the project.","vi":"Chúng tôi cần thêm thời gian để hoàn thành dự án.","image_url":"https://images.pexels.com/photos/33266834/pexels-photo-33266834.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Could I have some more rice, please?","vi":"Cho tôi xin thêm một chút cơm được không?","image_url":"https://images.pexels.com/photos/13518953/pexels-photo-13518953.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"More people are working from home these days.","vi":"Dạo này có nhiều người làm việc tại nhà hơn.","image_url":"https://images.pexels.com/photos/11569938/pexels-photo-11569938.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"more time"},{"phrase":"more money"},{"phrase":"more than"},{"phrase":"once more"}]','so sánh hơn của many/much','/mɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/more_/more__us_1.mp3','https://images.pexels.com/photos/15387083/pexels-photo-15387083.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Ann H","author_url":"https://www.pexels.com/@ann-h-45017","source_url":"https://www.pexels.com/photo/letters-on-dice-15387083/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5,'ngsl-1-01',5,'get','nhận được; lấy; trở nên','verb','[{"en":"I got a message from my sister this morning.","vi":"Sáng nay tôi nhận được tin nhắn từ chị gái.","image_url":"https://images.pexels.com/photos/6669776/pexels-photo-6669776.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Can you get me a glass of water?","vi":"Bạn lấy giúp tôi một cốc nước được không?","image_url":"https://images.pexels.com/photos/5336940/pexels-photo-5336940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It gets dark very early in the winter.","vi":"Vào mùa đông, trời tối rất sớm.","image_url":"https://images.pexels.com/photos/9807696/pexels-photo-9807696.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"get a job"},{"phrase":"get home"},{"phrase":"get better"},{"phrase":"get ready"}]','get – got – got (Mỹ: gotten)','/ɡet/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/get/get__/get__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(6,'ngsl-1-01',6,'like','thích','verb','[{"en":"I like reading books before I go to bed.","vi":"Tôi thích đọc sách trước khi đi ngủ.","image_url":"https://images.pexels.com/photos/29171842/pexels-photo-29171842.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My kids don''t like vegetables very much.","vi":"Bọn trẻ nhà tôi không thích ăn rau lắm.","image_url":"https://images.pexels.com/photos/4721131/pexels-photo-4721131.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She really likes her new apartment near the park.","vi":"Cô ấy rất thích căn hộ mới gần công viên.","image_url":"https://images.pexels.com/photos/7322273/pexels-photo-7322273.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"really like"},{"phrase":"would like"},{"phrase":"like best"}]','would like = muốn (lịch sự)','/laɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lik/like_/like__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(7,'ngsl-1-01',7,'think','nghĩ; cho rằng','verb','[{"en":"I think it''s going to rain this afternoon.","vi":"Tôi nghĩ chiều nay trời sẽ mưa.","image_url":"https://images.pexels.com/photos/39275252/pexels-photo-39275252.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What do you think of the new teacher?","vi":"Bạn nghĩ gì về giáo viên mới?","image_url":"https://images.pexels.com/photos/39190904/pexels-photo-39190904.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"He is thinking about changing jobs next year.","vi":"Anh ấy đang nghĩ đến chuyện đổi việc vào năm sau.","image_url":"https://images.pexels.com/photos/5668885/pexels-photo-5668885.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"think about"},{"phrase":"think of"},{"phrase":"think so"},{"phrase":"think carefully"}]','think – thought – thought','/θɪŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/think/think__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(8,'ngsl-1-01',8,'make','làm; tạo ra; khiến','verb','[{"en":"My mom is making dinner in the kitchen.","vi":"Mẹ tôi đang làm bữa tối trong bếp.","image_url":"https://images.pexels.com/photos/5907924/pexels-photo-5907924.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This company makes furniture for schools and offices.","vi":"Công ty này sản xuất đồ nội thất cho trường học và văn phòng.","image_url":"https://images.pexels.com/photos/38816548/pexels-photo-38816548.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"That sad movie made everyone in the room cry.","vi":"Bộ phim buồn đó khiến mọi người trong phòng đều khóc.","image_url":"https://images.pexels.com/photos/9999344/pexels-photo-9999344.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"make a mistake"},{"phrase":"make a decision"},{"phrase":"make money"},{"phrase":"make friends"}]','make – made – made','/meɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mak/make_/make__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(9,'ngsl-1-01',9,'time','thời gian; lần; giờ','noun','[{"en":"I don''t have much free time during the week.","vi":"Trong tuần tôi không có nhiều thời gian rảnh.","image_url":"https://images.pexels.com/photos/1059381/pexels-photo-1059381.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I''ve called him three times, but he isn''t answering.","vi":"Tôi đã gọi cho anh ấy ba lần nhưng anh ấy không nghe máy.","image_url":"https://images.pexels.com/photos/8682791/pexels-photo-8682791.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What time does the next train leave?","vi":"Chuyến tàu tiếp theo khởi hành lúc mấy giờ?","image_url":"https://images.pexels.com/photos/5868296/pexels-photo-5868296.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"free time"},{"phrase":"spend time"},{"phrase":"on time"},{"phrase":"have a good time"}]',NULL,'/taɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tim/time_/time__us_1.mp3','https://images.pexels.com/photos/8573370/pexels-photo-8573370.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Towfiqu barbhuiya","author_url":"https://www.pexels.com/@towfiqu-barbhuiya-3440682","source_url":"https://www.pexels.com/photo/hourglass-8573370/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(10,'ngsl-1-01',10,'see','nhìn thấy; gặp; hiểu','verb','[{"en":"Did you see the rainbow after the rain?","vi":"Bạn có thấy cầu vồng sau cơn mưa không?","image_url":"https://images.pexels.com/photos/36798456/pexels-photo-36798456.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I''m going to see my grandparents this weekend.","vi":"Cuối tuần này tôi sẽ đi thăm ông bà.","image_url":"https://images.pexels.com/photos/8307601/pexels-photo-8307601.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I see what you mean now, thank you.","vi":"Giờ thì tôi hiểu ý bạn rồi, cảm ơn nhé.","image_url":"https://images.pexels.com/photos/791024/pexels-photo-791024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"see a doctor"},{"phrase":"see a movie"},{"phrase":"see you later"}]','see – saw – seen','/siː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/see__/see__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(11,'ngsl-1-01',11,'good','tốt; giỏi; hay','adjective','[{"en":"Eating fruit every day is good for your health.","vi":"Ăn trái cây mỗi ngày tốt cho sức khỏe.","image_url":"https://images.pexels.com/photos/36600220/pexels-photo-36600220.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She is very good at math and science.","vi":"Cô ấy rất giỏi toán và khoa học.","image_url":"https://images.pexels.com/photos/6256109/pexels-photo-6256109.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You should watch that movie because it''s really good.","vi":"Bạn nên xem bộ phim đó vì nó rất hay.","image_url":"https://images.pexels.com/photos/7234319/pexels-photo-7234319.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"good at"},{"phrase":"good for"},{"phrase":"good idea"},{"phrase":"good news"}]','good – better – best','/ɡʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/goo/good_/good__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(12,'ngsl-1-01',12,'people','người; mọi người','noun','[{"en":"Many people take the bus to work in this city.","vi":"Ở thành phố này, nhiều người đi làm bằng xe buýt.","image_url":"https://images.pexels.com/photos/205353/pexels-photo-205353.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"How many people are coming to your party?","vi":"Có bao nhiêu người sẽ đến bữa tiệc của bạn?","image_url":"https://images.pexels.com/photos/36071198/pexels-photo-36071198.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"People are usually very friendly in small towns.","vi":"Ở các thị trấn nhỏ, mọi người thường rất thân thiện.","image_url":"https://images.pexels.com/photos/36722684/pexels-photo-36722684.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"most people"},{"phrase":"young people"},{"phrase":"local people"},{"phrase":"many people"}]','số nhiều của person','/ˈpiːpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/peo/peopl/people__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(13,'ngsl-1-01',13,'year','năm; tuổi','noun','[{"en":"We moved to this city three years ago.","vi":"Chúng tôi chuyển đến thành phố này ba năm trước.","image_url":"https://images.pexels.com/photos/7971291/pexels-photo-7971291.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She travels abroad at least once a year.","vi":"Cô ấy đi du lịch nước ngoài ít nhất mỗi năm một lần.","image_url":"https://images.pexels.com/photos/36485537/pexels-photo-36485537.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My son will be seven years old next month.","vi":"Tháng sau con trai tôi sẽ tròn bảy tuổi.","image_url":"https://images.pexels.com/photos/27175710/pexels-photo-27175710.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"last year"},{"phrase":"next year"},{"phrase":"every year"},{"phrase":"years old"}]',NULL,'/jɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yea/year_/year__us_1.mp3','https://images.pexels.com/photos/6354023/pexels-photo-6354023.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Lisa Fotios","author_url":"https://www.pexels.com/@fotios-photos","source_url":"https://www.pexels.com/photo/a-man-holding-a-paper-with-message-6354023/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(14,'ngsl-1-01',14,'take','lấy; mang theo; mất (thời gian)','verb','[{"en":"She took a book from the shelf and started reading.","vi":"Cô ấy lấy một cuốn sách trên kệ và bắt đầu đọc.","image_url":"https://images.pexels.com/photos/17975078/pexels-photo-17975078.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Don''t forget to take an umbrella with you.","vi":"Đừng quên mang theo ô nhé.","image_url":"https://images.pexels.com/photos/6874991/pexels-photo-6874991.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It takes about twenty minutes to walk to school.","vi":"Đi bộ đến trường mất khoảng hai mươi phút.","image_url":"https://images.pexels.com/photos/4881154/pexels-photo-4881154.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"take a photo"},{"phrase":"take a break"},{"phrase":"take the bus"},{"phrase":"take time"}]','take – took – taken','/teɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tak/take_/take__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(15,'ngsl-1-01',15,'well','tốt; giỏi; kỹ','adverb','[{"en":"I didn''t sleep well last night because of the noise.","vi":"Đêm qua tôi ngủ không ngon vì tiếng ồn.","image_url":"https://images.pexels.com/photos/7556638/pexels-photo-7556638.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My brother can speak English and French very well.","vi":"Anh trai tôi nói tiếng Anh và tiếng Pháp rất giỏi.","image_url":"https://images.pexels.com/photos/39490137/pexels-photo-39490137.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Shake the bottle well before you use it.","vi":"Lắc kỹ chai trước khi dùng.","image_url":"https://images.pexels.com/photos/4812635/pexels-photo-4812635.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"very well"},{"phrase":"sleep well"},{"phrase":"do well"}]','good (tính từ) ≠ well (trạng từ)','/wel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/well_/well__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(16,'ngsl-1-01',16,'because','vì; bởi vì','conjunction','[{"en":"I stayed home because I had a bad cold.","vi":"Tôi ở nhà vì bị cảm nặng.","image_url":"https://images.pexels.com/photos/15508361/pexels-photo-15508361.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We took a taxi because it was raining heavily.","vi":"Chúng tôi đi taxi vì trời mưa to.","image_url":"https://images.pexels.com/photos/11891283/pexels-photo-11891283.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Because the store was closed, we went somewhere else.","vi":"Vì cửa hàng đã đóng cửa nên chúng tôi đi chỗ khác.","image_url":"https://images.pexels.com/photos/38514789/pexels-photo-38514789.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"because of"},{"phrase":"just because"},{"phrase":"only because"}]','because + mệnh đề; because of + danh từ','/bɪˈkəz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bec/becau/because__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(17,'ngsl-1-01',17,'come','đến; về','verb','[{"en":"Can you come to my birthday party on Saturday?","vi":"Thứ Bảy bạn đến dự tiệc sinh nhật của tôi được không?","image_url":"https://images.pexels.com/photos/36071198/pexels-photo-36071198.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My father usually comes home from work at six.","vi":"Bố tôi thường đi làm về lúc sáu giờ.","image_url":"https://images.pexels.com/photos/8949354/pexels-photo-8949354.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Where does your new roommate come from?","vi":"Bạn cùng phòng mới của bạn đến từ đâu?","image_url":"https://images.pexels.com/photos/23224972/pexels-photo-23224972.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"come home"},{"phrase":"come back"},{"phrase":"come in"},{"phrase":"come from"}]','come – came – come','/kʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/come_/come__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(18,'ngsl-1-01',18,'work','làm việc; hoạt động','verb','[{"en":"My mother works at a hospital in the city.","vi":"Mẹ tôi làm việc tại một bệnh viện trong thành phố.","image_url":"https://images.pexels.com/photos/18271838/pexels-photo-18271838.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I have to work late tonight to finish this report.","vi":"Tối nay tôi phải làm việc muộn để hoàn thành bản báo cáo này.","image_url":"https://images.pexels.com/photos/8370882/pexels-photo-8370882.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The printer in our office isn''t working again.","vi":"Máy in trong văn phòng chúng tôi lại không hoạt động rồi.","image_url":"https://images.pexels.com/photos/8297818/pexels-photo-8297818.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"work hard"},{"phrase":"work late"},{"phrase":"work from home"},{"phrase":"work together"}]',NULL,'/wɜːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/work_/work__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(19,'ngsl-1-01',19,'use','sử dụng; dùng','verb','[{"en":"Can I use your phone for a minute?","vi":"Cho tôi dùng điện thoại của bạn một lát được không?","image_url":"https://images.pexels.com/photos/4033675/pexels-photo-4033675.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We use this room for meetings and training.","vi":"Chúng tôi dùng phòng này để họp và đào tạo.","image_url":"https://images.pexels.com/photos/34221175/pexels-photo-34221175.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She used a knife to open the box.","vi":"Cô ấy dùng dao để mở chiếc hộp.","image_url":"https://images.pexels.com/photos/4506241/pexels-photo-4506241.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"use a computer"},{"phrase":"use the bathroom"},{"phrase":"easy to use"}]','used to + V = đã từng (khác với use)','/juːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/use/use__/use__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(20,'ngsl-1-01',20,'look','nhìn; trông','verb','[{"en":"Look at the beautiful sunset over the sea.","vi":"Nhìn hoàng hôn tuyệt đẹp trên biển kìa.","image_url":"https://images.pexels.com/photos/37200096/pexels-photo-37200096.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"He looked out of the window and saw the snow.","vi":"Anh ấy nhìn ra ngoài cửa sổ và thấy tuyết.","image_url":"https://images.pexels.com/photos/35356174/pexels-photo-35356174.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You look very tired after your long trip.","vi":"Trông bạn rất mệt sau chuyến đi dài.","image_url":"https://images.pexels.com/photos/30595796/pexels-photo-30595796.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"look at"},{"phrase":"look for"},{"phrase":"look after"},{"phrase":"look happy"}]','look at: nhìn vào; look for: tìm; look after: chăm sóc','/lʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loo/look_/look__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(21,'ngsl-1-01',21,'want','muốn','verb','[{"en":"I want to learn how to cook Italian food.","vi":"Tôi muốn học cách nấu món Ý.","image_url":"https://images.pexels.com/photos/6287488/pexels-photo-6287488.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What do you want for your birthday?","vi":"Bạn muốn được tặng gì vào dịp sinh nhật?","image_url":"https://images.pexels.com/photos/264771/pexels-photo-264771.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My parents wanted me to become a doctor.","vi":"Bố mẹ tôi đã muốn tôi trở thành bác sĩ.","image_url":"https://images.pexels.com/photos/7653094/pexels-photo-7653094.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"really want"},{"phrase":"want to know"},{"phrase":"want to go"}]',NULL,'/wɑːnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wan/want_/want__us_1_rr.mp3','https://images.pexels.com/photos/5737622/pexels-photo-5737622.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Tim Mossholder","author_url":"https://www.pexels.com/@timmossholder","source_url":"https://www.pexels.com/photo/help-wanted-sign-on-glass-5737622/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(22,'ngsl-1-01',22,'give','đưa; cho; tặng','verb','[{"en":"Please give this letter to your teacher.","vi":"Em hãy đưa lá thư này cho giáo viên của em nhé.","image_url":"https://images.pexels.com/photos/30945609/pexels-photo-30945609.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Could you give me some advice about buying a car?","vi":"Bạn có thể cho tôi vài lời khuyên về việc mua xe không?","image_url":"https://images.pexels.com/photos/6817009/pexels-photo-6817009.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My aunt gave me a watch for my birthday.","vi":"Dì tặng tôi một chiếc đồng hồ nhân dịp sinh nhật.","image_url":"https://images.pexels.com/photos/13018652/pexels-photo-13018652.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"give advice"},{"phrase":"give a speech"},{"phrase":"give up"}]','give – gave – given','/ɡɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/giv/give_/give__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(23,'ngsl-1-01',23,'first','đầu tiên; thứ nhất','adjective','[{"en":"I still remember my first day at school.","vi":"Tôi vẫn nhớ ngày đầu tiên đi học.","image_url":"https://images.pexels.com/photos/8421930/pexels-photo-8421930.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The first train leaves at five in the morning.","vi":"Chuyến tàu đầu tiên khởi hành lúc năm giờ sáng.","image_url":"https://images.pexels.com/photos/33816597/pexels-photo-33816597.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Take the first street on the left after the bank.","vi":"Rẽ vào con phố đầu tiên bên trái sau ngân hàng.","image_url":"https://images.pexels.com/photos/20414013/pexels-photo-20414013.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"first time"},{"phrase":"first day"},{"phrase":"first step"},{"phrase":"at first"}]',NULL,'/fɜːrst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/first/first__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(24,'ngsl-1-01',24,'new','mới','adjective','[{"en":"I bought a new laptop for my studies.","vi":"Tôi mua một chiếc máy tính xách tay mới để học.","image_url":"https://images.pexels.com/photos/20432893/pexels-photo-20432893.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Our new neighbors are very friendly and helpful.","vi":"Hàng xóm mới của chúng tôi rất thân thiện và hay giúp đỡ.","image_url":"https://images.pexels.com/photos/6647031/pexels-photo-6647031.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Is it hard to make new friends in a big city?","vi":"Kết bạn mới ở thành phố lớn có khó không?","image_url":"https://images.pexels.com/photos/21853992/pexels-photo-21853992.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"new job"},{"phrase":"brand new"},{"phrase":"new friends"},{"phrase":"something new"}]',NULL,'/nuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/new__/new__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(25,'ngsl-1-01',25,'way','cách; đường','noun','[{"en":"What is the best way to learn English?","vi":"Cách tốt nhất để học tiếng Anh là gì?","image_url":"https://images.pexels.com/photos/20875710/pexels-photo-20875710.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Excuse me, could you tell me the way to the station?","vi":"Xin lỗi, bạn có thể chỉ giúp tôi đường đến nhà ga không?","image_url":"https://images.pexels.com/photos/33629154/pexels-photo-33629154.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I bought some bread on my way home.","vi":"Tôi mua ít bánh mì trên đường về nhà.","image_url":"https://images.pexels.com/photos/7543099/pexels-photo-7543099.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"the best way"},{"phrase":"on the way"},{"phrase":"a long way"}]',NULL,'/weɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/way/way__/way__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(26,'ngsl-1-01',26,'find','tìm thấy; thấy','verb','[{"en":"I can''t find my car keys anywhere this morning.","vi":"Sáng nay tôi tìm khắp nơi mà không thấy chìa khóa xe.","image_url":"https://images.pexels.com/photos/2810140/pexels-photo-2810140.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She finally found a job at a local bank.","vi":"Cuối cùng cô ấy cũng tìm được việc ở một ngân hàng địa phương.","image_url":"https://images.pexels.com/photos/3869640/pexels-photo-3869640.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Most students find this exercise quite difficult.","vi":"Hầu hết học sinh thấy bài tập này khá khó.","image_url":"https://images.pexels.com/photos/37812834/pexels-photo-37812834.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"find a job"},{"phrase":"find out"},{"phrase":"find the answer"},{"phrase":"hard to find"}]','find – found – found','/faɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/find_/find__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(27,'ngsl-1-01',27,'day','ngày; ban ngày','noun','[{"en":"I drink two cups of coffee a day.","vi":"Tôi uống hai tách cà phê mỗi ngày.","image_url":"https://images.pexels.com/photos/35835482/pexels-photo-35835482.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We spent the whole day at the beach.","vi":"Chúng tôi ở bãi biển cả ngày.","image_url":"https://images.pexels.com/photos/29293836/pexels-photo-29293836.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My father works during the day and studies at night.","vi":"Bố tôi làm việc ban ngày và đi học vào buổi tối.","image_url":"https://images.pexels.com/photos/9345689/pexels-photo-9345689.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"every day"},{"phrase":"all day"},{"phrase":"the next day"},{"phrase":"during the day"}]',NULL,'/deɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/day/day__/day__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(28,'ngsl-1-01',28,'thing','đồ vật; điều; việc','noun','[{"en":"Put your things in the bag before we leave.","vi":"Cất đồ của bạn vào túi trước khi chúng ta đi nhé.","image_url":"https://images.pexels.com/photos/9185809/pexels-photo-9185809.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The most important thing is your health.","vi":"Điều quan trọng nhất là sức khỏe của bạn.","image_url":"https://images.pexels.com/photos/5080100/pexels-photo-5080100.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"I have a lot of things to do today.","vi":"Hôm nay tôi có rất nhiều việc phải làm.","image_url":"https://images.pexels.com/photos/7888981/pexels-photo-7888981.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"the only thing"},{"phrase":"the same thing"},{"phrase":"the most important thing"}]',NULL,'/θɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thing/thing__us_1.mp3','https://images.pexels.com/photos/6353770/pexels-photo-6353770.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Anete Lusina","author_url":"https://www.pexels.com/@anete-lusina","source_url":"https://www.pexels.com/photo/textbook-with-message-on-hardcover-against-window-6353770/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(29,'ngsl-1-01',29,'need','cần','verb','[{"en":"I need to buy some milk on the way home.","vi":"Tôi cần mua ít sữa trên đường về nhà.","image_url":"https://images.pexels.com/photos/8718885/pexels-photo-8718885.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Do you need any help with those bags?","vi":"Bạn có cần giúp mang mấy cái túi đó không?","image_url":"https://images.pexels.com/photos/9531993/pexels-photo-9531993.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Plants need water and sunlight to grow.","vi":"Cây cần nước và ánh nắng để phát triển.","image_url":"https://images.pexels.com/photos/4894621/pexels-photo-4894621.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"need help"},{"phrase":"need to know"},{"phrase":"really need"}]',NULL,'/niːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nee/need_/need__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(30,'ngsl-1-01',30,'right','đúng; bên phải','adjective','[{"en":"You''re right, the meeting starts at ten, not nine.","vi":"Bạn nói đúng, cuộc họp bắt đầu lúc mười giờ chứ không phải chín giờ.","image_url":"https://images.pexels.com/photos/30073743/pexels-photo-30073743.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Is this the right bus for the city center?","vi":"Đây có đúng là xe buýt đi vào trung tâm thành phố không?","image_url":"https://images.pexels.com/photos/26807015/pexels-photo-26807015.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She broke her right arm while playing basketball.","vi":"Cô ấy bị gãy tay phải khi chơi bóng rổ.","image_url":"https://images.pexels.com/photos/10396727/pexels-photo-10396727.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"the right answer"},{"phrase":"right hand"},{"phrase":"right side"},{"phrase":"exactly right"}]',NULL,'/raɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rig/right/right__us_1.mp3','https://images.pexels.com/photos/8834285/pexels-photo-8834285.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"cottonbro CG studio","author_url":"https://www.pexels.com/@cottonbro-cg-studio","source_url":"https://www.pexels.com/photo/an-animation-of-pointing-finger-on-a-black-background-8834285/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(31,'ngsl-1-02',1,'back','trở lại, quay lại; về phía sau','adverb','[{"en":"I''ll be back in about ten minutes.","vi":"Khoảng mười phút nữa tôi sẽ quay lại."},{"en":"She looked back and waved goodbye to us.","vi":"Cô ấy ngoảnh lại và vẫy tay chào tạm biệt chúng tôi."},{"en":"What time did you come back last night?","vi":"Tối qua mấy giờ bạn mới quay về?"}]','[{"phrase":"come back"},{"phrase":"go back"},{"phrase":"look back"},{"phrase":"give back"}]',NULL,'/bæk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bac/back_/back__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(32,'ngsl-1-02',2,'mean','có nghĩa là; ý muốn nói; cố ý, định','verb','[{"en":"What does this word mean in Vietnamese?","vi":"Từ này trong tiếng Việt có nghĩa là gì?"},{"en":"I know what you mean, but I don''t agree.","vi":"Tôi hiểu ý bạn, nhưng tôi không đồng ý."},{"en":"Sorry, I didn''t mean to wake you up.","vi":"Xin lỗi, tôi không cố ý đánh thức bạn."}]','[{"phrase":"what do you mean"},{"phrase":"mean to do something"},{"phrase":"mean a lot to someone"}]','mean – meant – meant','/miːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/mean_/mean__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(33,'ngsl-1-02',3,'even','ngay cả, thậm chí; còn (hơn nữa)','adverb','[{"en":"Even my little brother can use this phone.","vi":"Ngay cả em trai tôi cũng dùng được chiếc điện thoại này.","image_url":"https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"He didn''t even say goodbye before he left.","vi":"Anh ấy thậm chí còn không chào tạm biệt trước khi đi.","image_url":"https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The second test was even harder than the first one.","vi":"Bài kiểm tra thứ hai còn khó hơn bài đầu tiên.","image_url":"https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"even if"},{"phrase":"even though"},{"phrase":"even better"},{"phrase":"not even"}]',NULL,'/ˈiːvn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/even_/even__us_1.mp3','https://images.pexels.com/photos/36937024/pexels-photo-36937024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Max Kladitin","author_url":"https://www.pexels.com/@max-kladitin-456997122","source_url":"https://www.pexels.com/photo/historic-brick-architecture-in-berlin-street-scene-36937024/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(34,'ngsl-1-02',4,'last','cuối cùng; trước, vừa qua','adjective','[{"en":"This is the last bus to the city tonight.","vi":"Đây là chuyến xe buýt cuối cùng vào thành phố tối nay."},{"en":"We went to the beach last weekend.","vi":"Cuối tuần trước chúng tôi đã đi biển."},{"en":"When was the last time you saw a doctor?","vi":"Lần cuối bạn đi khám bác sĩ là khi nào?"}]','[{"phrase":"last week"},{"phrase":"last night"},{"phrase":"the last time"},{"phrase":"the last minute"}]',NULL,'/læst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/las/last_/last__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(35,'ngsl-1-02',5,'child','đứa trẻ, trẻ em; con (cái)','noun','[{"en":"Every child in the class got a small gift.","vi":"Mọi đứa trẻ trong lớp đều nhận được một món quà nhỏ.","image_url":"https://images.pexels.com/photos/14831686/pexels-photo-14831686.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"They have three children, two boys and a girl.","vi":"Họ có ba người con, hai trai một gái."},{"en":"As a child, I spent every summer at my grandmother''s house.","vi":"Hồi nhỏ, mùa hè nào tôi cũng ở nhà bà."}]','[{"phrase":"young children"},{"phrase":"an only child"},{"phrase":"have children"},{"phrase":"raise children"}]','số nhiều: children','/tʃaɪld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/child/child__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(36,'ngsl-1-02',6,'tell','nói (cho ai biết); kể; bảo','verb','[{"en":"Can you tell me where the train station is?","vi":"Bạn có thể cho tôi biết nhà ga ở đâu không?","image_url":"https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"My grandfather told us a funny story last night.","vi":"Tối qua ông tôi kể cho chúng tôi nghe một câu chuyện vui.","image_url":"https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The teacher told the students to turn off their phones.","vi":"Cô giáo bảo học sinh tắt điện thoại.","image_url":"https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"tell a story"},{"phrase":"tell the truth"},{"phrase":"tell a lie"},{"phrase":"tell someone to do something"}]','tell – told – told','/tel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tel/tell_/tell__us_1.mp3','https://images.pexels.com/photos/10767940/pexels-photo-10767940.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Brett Jordan","author_url":"https://www.pexels.com/@brettjordan","source_url":"https://www.pexels.com/photo/a-told-you-so-quote-on-wooden-scrabble-pieces-10767940/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(37,'ngsl-1-02',7,'really','thật sự, thực sự; rất','adverb','[{"en":"Do you really want to quit your job?","vi":"Bạn thật sự muốn nghỉ việc à?"},{"en":"We had a really good time at the party.","vi":"Chúng tôi đã rất vui ở bữa tiệc."},{"en":"I''m really sorry that I forgot your birthday.","vi":"Tôi thực sự xin lỗi vì đã quên sinh nhật của bạn."}]','[{"phrase":"really good"},{"phrase":"really want"},{"phrase":"really sorry"},{"phrase":"not really"}]',NULL,'/ˈriːəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reall/really__us_3_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(38,'ngsl-1-02',8,'call','gọi điện (cho); gọi, gọi là','verb','[{"en":"I''ll call you when I get home.","vi":"Khi về đến nhà tôi sẽ gọi cho bạn."},{"en":"Can you call me back in an hour?","vi":"Một tiếng nữa bạn gọi lại cho tôi được không?","image_url":"https://images.pexels.com/photos/41372/call-communication-contact-face-41372.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What do you call this dish in English?","vi":"Món này tiếng Anh gọi là gì?"}]','[{"phrase":"call someone back"},{"phrase":"call a taxi"},{"phrase":"call the police"}]',NULL,'/kɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cal/call_/call__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(39,'ngsl-1-02',9,'before','trước; trước khi; trước đây','preposition','[{"en":"We arrived just before the movie started.","vi":"Chúng tôi đến ngay trước khi phim bắt đầu."},{"en":"Always wash your hands before you eat.","vi":"Hãy luôn rửa tay trước khi ăn."},{"en":"I have never seen this movie before.","vi":"Tôi chưa bao giờ xem bộ phim này trước đây."}]','[{"phrase":"just before"},{"phrase":"the day before"},{"phrase":"before long"}]',NULL,'/bɪˈfɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bef/befor/before__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(40,'ngsl-1-02',10,'company','công ty; sự bầu bạn, sự có mặt (của ai)','noun','[{"en":"My sister works for a small software company.","vi":"Chị tôi làm việc cho một công ty phần mềm nhỏ."},{"en":"The company hired twenty new workers this year.","vi":"Năm nay công ty đã tuyển hai mươi nhân viên mới."},{"en":"I enjoy her company because she always makes me laugh.","vi":"Tôi thích ở bên cô ấy vì cô ấy luôn làm tôi cười.","image_url":"https://images.pexels.com/photos/4307787/pexels-photo-4307787.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"work for a company"},{"phrase":"a large company"},{"phrase":"start a company"},{"phrase":"keep someone company"}]',NULL,'/ˈkʌmpəni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/company__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(41,'ngsl-1-02',11,'show','cho xem; chỉ (cho); cho thấy','verb','[{"en":"She showed us photos from her trip to Japan.","vi":"Cô ấy cho chúng tôi xem ảnh chuyến đi Nhật Bản."},{"en":"Can you show me how to use this machine?","vi":"Bạn chỉ tôi cách dùng cái máy này được không?"},{"en":"The results show that more people are working from home.","vi":"Kết quả cho thấy có nhiều người làm việc tại nhà hơn."}]','[{"phrase":"show someone how to"},{"phrase":"show someone around"},{"phrase":"results show"}]','show – showed – shown','/ʃəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/show_/show__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(42,'ngsl-1-02',12,'life','cuộc sống; cuộc đời; sự sống','noun','[{"en":"Life in the city is busy and expensive.","vi":"Cuộc sống ở thành phố bận rộn và đắt đỏ."},{"en":"He spent his whole life in this small village.","vi":"Ông ấy sống cả đời ở ngôi làng nhỏ này."},{"en":"Scientists are still looking for life on other planets.","vi":"Các nhà khoa học vẫn đang tìm kiếm sự sống trên các hành tinh khác."}]','[{"phrase":"daily life"},{"phrase":"real life"},{"phrase":"your whole life"},{"phrase":"save someone''s life"}]','số nhiều: lives','/laɪf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lif/life_/life__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(43,'ngsl-1-02',13,'man','người đàn ông; đàn ông, nam giới','noun','[{"en":"A man in a blue jacket asked me for directions.","vi":"Một người đàn ông mặc áo khoác xanh hỏi đường tôi.","image_url":"https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The old man lives alone with his cat.","vi":"Ông cụ sống một mình với con mèo.","image_url":"https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Both men and women can apply for this job.","vi":"Cả nam và nữ đều có thể ứng tuyển công việc này.","image_url":"https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"a young man"},{"phrase":"an old man"},{"phrase":"a married man"},{"phrase":"men and women"}]','số nhiều: men','/mæn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/man__/man__us_1.mp3','https://images.pexels.com/photos/39373268/pexels-photo-39373268.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Ali Durmuş Cevlan","author_url":"https://www.pexels.com/@ali-durmus-cevlan-518867579","source_url":"https://www.pexels.com/photo/portrait-of-elderly-man-in-aksehir-turkiye-39373268/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(44,'ngsl-1-02',14,'change','thay đổi; đổi, thay','verb','[{"en":"You haven''t changed at all since high school.","vi":"Bạn chẳng thay đổi gì cả kể từ hồi cấp ba."},{"en":"We changed trains twice on the way to the coast.","vi":"Chúng tôi đã đổi tàu hai lần trên đường ra biển."},{"en":"Let me change my clothes before we go out.","vi":"Để tôi thay quần áo trước khi chúng ta ra ngoài."}]','[{"phrase":"change your mind"},{"phrase":"change clothes"},{"phrase":"change trains"},{"phrase":"change the subject"}]',NULL,'/tʃeɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chang/change__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(45,'ngsl-1-02',15,'place','nơi, chỗ; nhà (của ai); vị trí','noun','[{"en":"This is a great place to have lunch.","vi":"Đây là một chỗ ăn trưa rất tuyệt.","image_url":"https://images.pexels.com/photos/1545400/pexels-photo-1545400.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Let''s meet at my place after work.","vi":"Tan làm mình gặp nhau ở nhà tôi nhé."},{"en":"She finished in second place in the race.","vi":"Cô ấy về đích ở vị trí thứ hai trong cuộc đua."}]','[{"phrase":"take place"},{"phrase":"a great place to"},{"phrase":"first place"}]',NULL,'/pleɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/place/place__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(46,'ngsl-1-02',16,'long','dài; lâu','adjective','[{"en":"My sister has long black hair like our mother.","vi":"Chị tôi có mái tóc đen dài giống mẹ.","image_url":"https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It was a long day, so I went to bed early.","vi":"Hôm đó là một ngày dài nên tôi đi ngủ sớm.","image_url":"https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"How long does it take to get to the airport?","vi":"Đi đến sân bay mất bao lâu?","image_url":"https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"a long time"},{"phrase":"long hair"},{"phrase":"a long way"},{"phrase":"a long day"}]',NULL,'/lɔːŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lon/long_/long__us_8.mp3','https://images.pexels.com/photos/39525018/pexels-photo-39525018.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"German Suarez","author_url":"https://www.pexels.com/@german-suarez-2985952","source_url":"https://www.pexels.com/photo/elegant-borzoi-dog-lying-outdoors-in-park-39525018/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(47,'ngsl-1-02',17,'between','giữa, ở giữa','preposition','[{"en":"The bank is between the post office and the school.","vi":"Ngân hàng nằm giữa bưu điện và trường học."},{"en":"I usually have a snack between lunch and dinner.","vi":"Tôi thường ăn vặt giữa bữa trưa và bữa tối."},{"en":"What''s the difference between these two phones?","vi":"Hai chiếc điện thoại này khác nhau ở điểm nào?","image_url":"https://images.pexels.com/photos/33453407/pexels-photo-33453407.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"the difference between"},{"phrase":"in between"},{"phrase":"between A and B"}]',NULL,'/bɪˈtwiːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bet/betwe/between__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(48,'ngsl-1-02',18,'feel','cảm thấy; sờ thấy, có cảm giác','verb','[{"en":"I feel tired after a long day at work.","vi":"Tôi thấy mệt sau một ngày dài làm việc."},{"en":"How do you feel about moving to a new city?","vi":"Bạn cảm thấy thế nào về việc chuyển đến một thành phố mới?"},{"en":"The baby''s skin felt soft and warm.","vi":"Da em bé sờ vào thấy mềm và ấm."}]','[{"phrase":"feel tired"},{"phrase":"feel better"},{"phrase":"feel sorry for"},{"phrase":"feel like"}]','feel – felt – felt','/fiːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/feel_/feel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(49,'ngsl-1-02',19,'still','vẫn, vẫn còn','adverb','[{"en":"Are you still living in the same apartment?","vi":"Bạn vẫn sống ở căn hộ cũ à?"},{"en":"It''s almost noon, and he is still asleep.","vi":"Gần trưa rồi mà anh ấy vẫn còn ngủ."},{"en":"I studied hard, but I still failed the test.","vi":"Tôi đã học chăm chỉ nhưng vẫn trượt bài kiểm tra."}]','[{"phrase":"still waiting"},{"phrase":"still alive"},{"phrase":"still asleep"}]',NULL,'/stɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/still/still__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(50,'ngsl-1-02',20,'problem','vấn đề; rắc rối, trục trặc','noun','[{"en":"We''re having a problem with the kitchen sink again.","vi":"Bồn rửa trong bếp nhà chúng tôi lại bị trục trặc.","image_url":"https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Talking to a friend can help you solve a problem.","vi":"Trò chuyện với bạn bè có thể giúp bạn giải quyết vấn đề.","image_url":"https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"No problem, I can pick you up from the station.","vi":"Không sao, tôi có thể đón bạn ở nhà ga.","image_url":"https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"solve a problem"},{"phrase":"have a problem with"},{"phrase":"no problem"},{"phrase":"a serious problem"}]',NULL,'/ˈprɑːbləm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/probl/problem__us_1.mp3','https://images.pexels.com/photos/1888016/pexels-photo-1888016.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Ann H","author_url":"https://www.pexels.com/@ann-h-45017","source_url":"https://www.pexels.com/photo/yellow-letter-tiles-1888016/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(51,'ngsl-1-02',21,'write','viết','verb','[{"en":"Please write your name at the top of the page.","vi":"Hãy viết tên của bạn ở đầu trang."},{"en":"She wrote a long letter to her grandparents.","vi":"Cô ấy đã viết một lá thư dài cho ông bà."},{"en":"I have to write a report for my boss by Friday.","vi":"Tôi phải viết báo cáo cho sếp trước thứ Sáu."}]','[{"phrase":"write a letter"},{"phrase":"write a report"},{"phrase":"write down"},{"phrase":"write an email"}]','write – wrote – written','/raɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wri/write/write__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(52,'ngsl-1-02',22,'same','giống nhau, như nhau; cùng','adjective','[{"en":"We were born in the same year.","vi":"Chúng tôi sinh cùng một năm.","image_url":"https://images.pexels.com/photos/6224827/pexels-photo-6224827.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Your bag looks the same as mine.","vi":"Túi của bạn trông giống hệt túi của tôi."},{"en":"He orders the same thing every time we eat here.","vi":"Lần nào ăn ở đây anh ấy cũng gọi đúng một món đó."}]','[{"phrase":"the same as"},{"phrase":"at the same time"},{"phrase":"the same thing"},{"phrase":"exactly the same"}]','thường đi với the: the same','/seɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sam/same_/same__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(53,'ngsl-1-02',23,'lot','nhiều, rất nhiều','noun','[{"en":"There were a lot of people at the market today.","vi":"Hôm nay ở chợ có rất đông người."},{"en":"Thanks a lot for helping me move.","vi":"Cảm ơn bạn nhiều vì đã giúp tôi chuyển nhà."},{"en":"She has changed a lot since last year.","vi":"Cô ấy đã thay đổi nhiều kể từ năm ngoái."}]','[{"phrase":"a lot of"},{"phrase":"lots of"},{"phrase":"thanks a lot"},{"phrase":"quite a lot"}]','thường dùng: a lot of / lots of + danh từ','/lɑːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lot/lot__/lot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(54,'ngsl-1-02',24,'great','tuyệt vời; lớn, to lớn','adjective','[{"en":"We had a great time at the beach.","vi":"Chúng tôi đã có khoảng thời gian tuyệt vời ở biển."},{"en":"Your new apartment looks great with all those plants.","vi":"Căn hộ mới của bạn trông thật tuyệt với mấy chậu cây đó.","image_url":"https://images.pexels.com/photos/5825371/pexels-photo-5825371.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Our first charity event was a great success.","vi":"Sự kiện từ thiện đầu tiên của chúng tôi đã thành công lớn."}]','[{"phrase":"a great time"},{"phrase":"a great idea"},{"phrase":"a great deal"},{"phrase":"a great success"}]',NULL,'/ɡreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/great/great__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(55,'ngsl-1-02',25,'try','cố gắng; thử','verb','[{"en":"I''ll try to finish the report by tonight.","vi":"Tôi sẽ cố gắng hoàn thành báo cáo trước tối nay."},{"en":"Have you ever tried Vietnamese iced coffee?","vi":"Bạn đã bao giờ thử cà phê đá Việt Nam chưa?"},{"en":"Can I try on these shoes in a smaller size?","vi":"Tôi có thể thử đôi giày này cỡ nhỏ hơn không?"}]','[{"phrase":"try to do something"},{"phrase":"try hard"},{"phrase":"try on"},{"phrase":"try your best"}]',NULL,'/traɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/try/try__/try__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(56,'ngsl-1-02',26,'leave','rời đi, rời khỏi; để lại, bỏ quên','verb','[{"en":"What time does your train leave in the morning?","vi":"Buổi sáng tàu của bạn khởi hành lúc mấy giờ?"},{"en":"She leaves home at seven every morning.","vi":"Sáng nào cô ấy cũng ra khỏi nhà lúc bảy giờ."},{"en":"I left my umbrella on the bus.","vi":"Tôi để quên ô trên xe buýt.","image_url":"https://images.pexels.com/photos/19116710/pexels-photo-19116710.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"leave home"},{"phrase":"leave a message"},{"phrase":"leave school"},{"phrase":"leave for work"}]','leave – left – left','/liːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leave/leave__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(57,'ngsl-1-02',27,'number','số; số lượng','noun','[{"en":"Could you give me your phone number, please?","vi":"Bạn cho tôi xin số điện thoại được không?"},{"en":"The number of students in our class has grown.","vi":"Số lượng học sinh trong lớp chúng tôi đã tăng lên."},{"en":"A large number of tourists visit the old town every summer.","vi":"Mỗi mùa hè có rất nhiều du khách đến thăm phố cổ.","image_url":"https://images.pexels.com/photos/34128969/pexels-photo-34128969.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"phone number"},{"phrase":"the number of"},{"phrase":"a large number of"},{"phrase":"room number"}]',NULL,'/ˈnʌmbər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/num/numbe/number__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(58,'ngsl-1-02',28,'part','phần; bộ phận; vai (diễn)','noun','[{"en":"The best part of the trip was the food.","vi":"Phần tuyệt nhất của chuyến đi là đồ ăn."},{"en":"My car needs a new part, so it''s at the garage.","vi":"Xe tôi cần thay một bộ phận mới nên đang nằm ở gara."},{"en":"She got a small part in the school play.","vi":"Cô ấy được nhận một vai nhỏ trong vở kịch của trường."}]','[{"phrase":"take part in"},{"phrase":"an important part of"},{"phrase":"the best part"},{"phrase":"play a part"}]',NULL,'/pɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/part_/part__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(59,'ngsl-1-02',29,'point','điểm; ý, luận điểm; mục đích, ý nghĩa','noun','[{"en":"Our team won the game by two points.","vi":"Đội của chúng tôi thắng trận với cách biệt hai điểm.","image_url":"https://images.pexels.com/photos/4468119/pexels-photo-4468119.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You make a good point about the cost of the trip.","vi":"Bạn đã nêu ra một ý hay về chi phí của chuyến đi.","image_url":"https://images.pexels.com/photos/4468119/pexels-photo-4468119.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"What''s the point of buying a car if you never drive?","vi":"Mua ô tô thì có ích gì nếu bạn chẳng bao giờ lái?","image_url":"https://images.pexels.com/photos/4468119/pexels-photo-4468119.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"make a good point"},{"phrase":"what''s the point"},{"phrase":"at some point"}]',NULL,'/pɔɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poi/point/point__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(60,'ngsl-1-02',30,'little','nhỏ, bé; ít, một chút','adjective','[{"en":"We live in a little house near the river.","vi":"Chúng tôi sống trong một ngôi nhà nhỏ gần sông."},{"en":"My little sister is starting school this year.","vi":"Em gái tôi năm nay bắt đầu đi học."},{"en":"Could you speak a little more slowly, please?","vi":"Bạn nói chậm hơn một chút được không?"}]','[{"phrase":"a little bit"},{"phrase":"a little more"},{"phrase":"little by little"}]','a little = một ít; little = rất ít (gần như không)','/ˈlɪtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/littl/little__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(61,'awl-1-01',1,'analyse','phân tích','verb','[{"en":"Researchers analysed data from more than two thousand patients.","vi":"Các nhà nghiên cứu đã phân tích dữ liệu từ hơn hai nghìn bệnh nhân.","image_url":"https://images.pexels.com/photos/7578799/pexels-photo-7578799.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Before writing the report, we need to analyse the survey results carefully.","vi":"Trước khi viết báo cáo, chúng ta cần phân tích kỹ kết quả khảo sát.","image_url":"https://images.pexels.com/photos/669610/pexels-photo-669610.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The team is still analysing why sales fell last quarter.","vi":"Nhóm vẫn đang phân tích lý do doanh số giảm trong quý trước.","image_url":"https://images.pexels.com/photos/6016350/pexels-photo-6016350.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"analyse data"},{"phrase":"analyse results"},{"phrase":"carefully analyse"}]','Anh: analyse · Mỹ: analyze','/ˈænəlaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analy/analyse__us_2.mp3','https://images.pexels.com/photos/8442898/pexels-photo-8442898.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Pavel Danilyuk","author_url":"https://www.pexels.com/@pavel-danilyuk","source_url":"https://www.pexels.com/photo/close-up-photo-of-a-microscope-with-glass-slide-8442898/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(62,'awl-1-01',2,'approach','cách tiếp cận; phương pháp','noun','[{"en":"The school has taken a new approach to teaching reading.","vi":"Nhà trường đã áp dụng một cách tiếp cận mới trong việc dạy đọc.","image_url":"https://images.pexels.com/photos/8499566/pexels-photo-8499566.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This approach works well for small businesses but not for large ones.","vi":"Phương pháp này hiệu quả với doanh nghiệp nhỏ nhưng không hiệu quả với doanh nghiệp lớn.","image_url":"https://images.pexels.com/photos/36714292/pexels-photo-36714292.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Scientists are testing a different approach to treating the disease.","vi":"Các nhà khoa học đang thử nghiệm một phương pháp khác để điều trị căn bệnh này.","image_url":"https://images.pexels.com/photos/4149047/pexels-photo-4149047.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"take an approach"},{"phrase":"a new approach"},{"phrase":"different approach"},{"phrase":"approach to"}]','approach to + danh từ / V-ing','/əˈprəʊtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approach__us_1.mp3','https://images.pexels.com/photos/7688440/pexels-photo-7688440.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Kindel Media","author_url":"https://www.pexels.com/@kindelmedia","source_url":"https://www.pexels.com/photo/person-s-hand-on-white-paper-7688440/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(63,'awl-1-01',3,'area','khu vực; lĩnh vực; diện tích','noun','[{"en":"Many families have moved out of the city into rural areas.","vi":"Nhiều gia đình đã rời thành phố để chuyển về các vùng nông thôn.","image_url":"https://images.pexels.com/photos/16644802/pexels-photo-16644802.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Her main area of research is language development in children.","vi":"Lĩnh vực nghiên cứu chính của cô ấy là sự phát triển ngôn ngữ ở trẻ em.","image_url":"https://images.pexels.com/photos/8087867/pexels-photo-8087867.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The park covers an area of about fifty square kilometers.","vi":"Công viên có diện tích khoảng năm mươi ki-lô-mét vuông.","image_url":"https://images.pexels.com/photos/18368795/pexels-photo-18368795.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"rural area"},{"phrase":"urban area"},{"phrase":"area of research"},{"phrase":"cover an area"}]',NULL,'/ˈeriə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/are/area_/area__us_2.mp3','https://images.pexels.com/photos/19061849/pexels-photo-19061849.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"K","author_url":"https://www.pexels.com/@kelly","source_url":"https://www.pexels.com/photo/aerial-view-of-an-overpass-over-railway-tracks-19061849/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(64,'awl-1-01',4,'assess','đánh giá','verb','[{"en":"Teachers assess students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ.","image_url":"https://images.pexels.com/photos/8363162/pexels-photo-8363162.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It is too early to assess the impact of the new policy.","vi":"Còn quá sớm để đánh giá tác động của chính sách mới.","image_url":"https://images.pexels.com/photos/10341357/pexels-photo-10341357.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Experts were called in to assess the damage after the flood.","vi":"Các chuyên gia được mời đến để đánh giá thiệt hại sau trận lũ.","image_url":"https://images.pexels.com/photos/14000741/pexels-photo-14000741.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"assess the impact"},{"phrase":"assess the damage"},{"phrase":"assess progress"}]',NULL,'/əˈses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asses/assess__us_2.mp3','https://images.pexels.com/photos/8654753/pexels-photo-8654753.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Mikhail Nilov","author_url":"https://www.pexels.com/@mikhail-nilov","source_url":"https://www.pexels.com/photo/close-up-of-man-looking-at-a-document-with-an-autism-test-8654753/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(65,'awl-1-01',5,'assume','cho rằng; giả định; đảm nhận','verb','[{"en":"Many people assume that older workers cannot learn new skills.","vi":"Nhiều người cho rằng người lao động lớn tuổi không thể học kỹ năng mới.","image_url":"https://images.pexels.com/photos/7983575/pexels-photo-7983575.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"For this calculation, we assume that prices will stay the same.","vi":"Trong phép tính này, chúng tôi giả định rằng giá cả sẽ giữ nguyên.","image_url":"https://images.pexels.com/photos/262470/pexels-photo-262470.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She will assume responsibility for the project next month.","vi":"Tháng sau cô ấy sẽ đảm nhận trách nhiệm về dự án.","image_url":"https://images.pexels.com/photos/6732207/pexels-photo-6732207.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"reasonable to assume"},{"phrase":"widely assumed"},{"phrase":"assume responsibility"}]',NULL,'/əˈsuːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assum/assume__us_2.mp3','https://images.pexels.com/photos/8932407/pexels-photo-8932407.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Brett Sayles","author_url":"https://www.pexels.com/@brett-sayles","source_url":"https://www.pexels.com/photo/close-up-of-a-sentence-on-a-letter-board-8932407/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(66,'awl-1-01',6,'authority','chính quyền; thẩm quyền; chuyên gia','noun','[{"en":"Local authorities have closed the road for repairs.","vi":"Chính quyền địa phương đã đóng con đường để sửa chữa.","image_url":"https://images.pexels.com/photos/4134380/pexels-photo-4134380.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Only the manager has the authority to approve payments.","vi":"Chỉ người quản lý mới có thẩm quyền phê duyệt các khoản thanh toán.","image_url":"https://images.pexels.com/photos/7821463/pexels-photo-7821463.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"She is a leading authority on climate change.","vi":"Bà ấy là một chuyên gia hàng đầu về biến đổi khí hậu.","image_url":"https://images.pexels.com/photos/11939228/pexels-photo-11939228.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"local authorities"},{"phrase":"have the authority to"},{"phrase":"an authority on"},{"phrase":"health authorities"}]','the authorities: nhà chức trách','/əˈθɔːrəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autho/authority__us_1_rr.mp3','https://images.pexels.com/photos/684387/pexels-photo-684387.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Lukas Blazek","author_url":"https://www.pexels.com/@goumbik","source_url":"https://www.pexels.com/photo/close-up-photo-of-a-person-wearing-suit-jacket-684387/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(67,'awl-1-01',7,'available','có sẵn; rảnh','adjective','[{"en":"The full report is publicly available on the company website.","vi":"Bản báo cáo đầy đủ được công khai trên trang web của công ty.","image_url":"https://images.pexels.com/photos/5918191/pexels-photo-5918191.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Free parking is available for all visitors.","vi":"Có chỗ đỗ xe miễn phí cho tất cả khách đến thăm.","image_url":"https://images.pexels.com/photos/20018335/pexels-photo-20018335.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Is the manager available for a meeting this afternoon?","vi":"Chiều nay người quản lý có rảnh để họp không?","image_url":"https://images.pexels.com/photos/7504810/pexels-photo-7504810.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"readily available"},{"phrase":"widely available"},{"phrase":"publicly available"},{"phrase":"available for"}]',NULL,'/əˈveɪləbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ava/avail/available__us_1.mp3','https://images.pexels.com/photos/13257111/pexels-photo-13257111.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Quang Viet Nguyen","author_url":"https://www.pexels.com/@quang-viet-nguyen-107013384","source_url":"https://www.pexels.com/photo/grayscale-photo-of-a-wristwatch-13257111/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(68,'awl-1-01',8,'benefit','lợi ích; trợ cấp','noun','[{"en":"Regular exercise has many benefits for mental health.","vi":"Tập thể dục thường xuyên có nhiều lợi ích cho sức khỏe tinh thần.","image_url":"https://images.pexels.com/photos/36715612/pexels-photo-36715612.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The new system will bring clear benefits to small farmers.","vi":"Hệ thống mới sẽ mang lại lợi ích rõ rệt cho các nông hộ nhỏ.","image_url":"https://images.pexels.com/photos/17765487/pexels-photo-17765487.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"People who lose their jobs may apply for unemployment benefits.","vi":"Những người mất việc có thể nộp đơn xin trợ cấp thất nghiệp.","image_url":"https://images.pexels.com/photos/9830115/pexels-photo-9830115.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"health benefits"},{"phrase":"economic benefits"},{"phrase":"unemployment benefits"}]','Cũng là động từ: benefit from (được hưởng lợi từ)','/ˈbenɪfɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/benef/benefit__us_1.mp3','https://images.pexels.com/photos/1172019/pexels-photo-1172019.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Lisa Fotios","author_url":"https://www.pexels.com/@fotios-photos","source_url":"https://www.pexels.com/photo/strawberries-and-measuring-tape-1172019/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(69,'awl-1-01',9,'concept','khái niệm; ý tưởng','noun','[{"en":"Young children find the concept of time difficult to understand.","vi":"Trẻ nhỏ thấy khái niệm thời gian rất khó hiểu.","image_url":"https://images.pexels.com/photos/5303503/pexels-photo-5303503.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This chapter introduces the basic concepts of economics.","vi":"Chương này giới thiệu các khái niệm cơ bản của kinh tế học.","image_url":"https://images.pexels.com/photos/7873576/pexels-photo-7873576.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The designers came up with a fresh concept for the new store.","vi":"Các nhà thiết kế đã nghĩ ra một ý tưởng mới mẻ cho cửa hàng mới.","image_url":"https://images.pexels.com/photos/39364652/pexels-photo-39364652.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"basic concept"},{"phrase":"key concept"},{"phrase":"concept of"}]',NULL,'/ˈkɑːnsept/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcept__us_1.mp3','https://images.pexels.com/photos/7257156/pexels-photo-7257156.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Anete Lusina","author_url":"https://www.pexels.com/@anete-lusina","source_url":"https://www.pexels.com/photo/project-on-papers-7257156/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(70,'awl-1-01',10,'consist','gồm có, bao gồm','verb','[{"en":"The committee consists of twelve members from different departments.","vi":"Ủy ban gồm mười hai thành viên đến từ các phòng ban khác nhau.","image_url":"https://images.pexels.com/photos/32870073/pexels-photo-32870073.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The course consists of ten lectures and three written assignments.","vi":"Khóa học gồm mười bài giảng và ba bài tập viết.","image_url":"https://images.pexels.com/photos/7092339/pexels-photo-7092339.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Their diet consisted mainly of fish and rice.","vi":"Chế độ ăn của họ chủ yếu gồm cá và cơm.","image_url":"https://images.pexels.com/photos/36855860/pexels-photo-36855860.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"consist of"},{"phrase":"consist mainly of"},{"phrase":"consist entirely of"}]','consist of + danh từ; không dùng ở thể bị động','/kənˈsɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsist__us_1.mp3','https://images.pexels.com/photos/39441321/pexels-photo-39441321.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Jahra Tasfia Reza","author_url":"https://www.pexels.com/@jahratreza","source_url":"https://www.pexels.com/photo/pouring-syrup-into-spoon-outdoors-closeup-39441321/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(71,'awl-1-01',11,'constitute','cấu thành, tạo thành; chiếm; được coi là','verb','[{"en":"Women constitute nearly half of the country''s workforce.","vi":"Phụ nữ chiếm gần một nửa lực lượng lao động của cả nước.","image_url":"https://images.pexels.com/photos/4770610/pexels-photo-4770610.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Such behavior may constitute a serious threat to public safety.","vi":"Hành vi như vậy có thể được coi là mối đe dọa nghiêm trọng đối với an toàn công cộng.","image_url":"https://images.pexels.com/photos/38486967/pexels-photo-38486967.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"These ten principles constitute the basis of the new law.","vi":"Mười nguyên tắc này tạo thành nền tảng của bộ luật mới.","image_url":"https://images.pexels.com/photos/8850737/pexels-photo-8850737.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"constitute a threat"},{"phrase":"constitute a large proportion"},{"phrase":"constitute a breach"}]',NULL,'/ˈkɑːnstɪtuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstitute__us_1.mp3','https://images.pexels.com/photos/8850742/pexels-photo-8850742.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Tara Winstead","author_url":"https://www.pexels.com/@tara-winstead","source_url":"https://www.pexels.com/photo/close-up-shot-of-a-law-book-8850742/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(72,'awl-1-01',12,'context','bối cảnh; ngữ cảnh','noun','[{"en":"These events must be understood in their historical context.","vi":"Những sự kiện này phải được hiểu trong bối cảnh lịch sử của chúng.","image_url":"https://images.pexels.com/photos/36289771/pexels-photo-36289771.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"You can often guess the meaning of a word from the context.","vi":"Bạn thường có thể đoán nghĩa của một từ dựa vào ngữ cảnh.","image_url":"https://images.pexels.com/photos/159581/dictionary-reference-book-learning-meaning-159581.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The writer complained that her comments had been taken out of context.","vi":"Nhà văn phàn nàn rằng những nhận xét của bà đã bị trích dẫn tách khỏi ngữ cảnh.","image_url":"https://images.pexels.com/photos/684319/pexels-photo-684319.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"historical context"},{"phrase":"social context"},{"phrase":"in this context"},{"phrase":"out of context"}]',NULL,'/ˈkɑːntekst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontext__us_1.mp3','https://images.pexels.com/photos/16943785/pexels-photo-16943785.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Brett Jordan","author_url":"https://www.pexels.com/@brettjordan","source_url":"https://www.pexels.com/photo/atonement-sign-out-of-scrabble-tiles-16943785/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(73,'awl-1-01',13,'contract','hợp đồng','noun','[{"en":"Both companies signed a three-year contract last week.","vi":"Tuần trước, hai công ty đã ký một hợp đồng ba năm.","image_url":"https://images.pexels.com/photos/7841410/pexels-photo-7841410.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Many young people now work on short-term contracts.","vi":"Nhiều người trẻ hiện nay làm việc theo hợp đồng ngắn hạn.","image_url":"https://images.pexels.com/photos/8962686/pexels-photo-8962686.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"If the supplier breaks the contract, we can ask for our money back.","vi":"Nếu nhà cung cấp vi phạm hợp đồng, chúng ta có thể yêu cầu hoàn tiền.","image_url":"https://images.pexels.com/photos/38783384/pexels-photo-38783384.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"sign a contract"},{"phrase":"break a contract"},{"phrase":"short-term contract"},{"phrase":"renew a contract"}]','Động từ contract (nhấn âm 2): co lại','/ˈkɑːntrækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontract__us_1.mp3','https://images.pexels.com/photos/7841818/pexels-photo-7841818.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"RDNE Stock project","author_url":"https://www.pexels.com/@rdne","source_url":"https://www.pexels.com/photo/close-up-shot-of-a-document-on-a-wooden-table-7841818/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(74,'awl-1-01',14,'create','tạo ra; gây ra','verb','[{"en":"The new factory will create around five hundred jobs.","vi":"Nhà máy mới sẽ tạo ra khoảng năm trăm việc làm.","image_url":"https://images.pexels.com/photos/29141369/pexels-photo-29141369.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The students created a short video about saving water.","vi":"Các sinh viên đã tạo một video ngắn về việc tiết kiệm nước.","image_url":"https://images.pexels.com/photos/6990575/pexels-photo-6990575.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Poor planning can create serious problems later on.","vi":"Lập kế hoạch kém có thể gây ra những vấn đề nghiêm trọng về sau.","image_url":"https://images.pexels.com/photos/3771045/pexels-photo-3771045.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"create jobs"},{"phrase":"create opportunities"},{"phrase":"create problems"}]',NULL,'/kriˈeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/create__us_1.mp3','https://images.pexels.com/photos/4116518/pexels-photo-4116518.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Magda Ehlers","author_url":"https://www.pexels.com/@magda-ehlers-pexels","source_url":"https://www.pexels.com/photo/create-message-4116518/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(75,'awl-1-01',15,'data','dữ liệu; số liệu','noun','[{"en":"The data show a clear link between sleep and memory.","vi":"Dữ liệu cho thấy mối liên hệ rõ ràng giữa giấc ngủ và trí nhớ.","image_url":"https://images.pexels.com/photos/8919892/pexels-photo-8919892.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"We collected data from over three hundred schools.","vi":"Chúng tôi đã thu thập dữ liệu từ hơn ba trăm trường học.","image_url":"https://images.pexels.com/photos/6368842/pexels-photo-6368842.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The latest data on household spending will be published next week.","vi":"Số liệu mới nhất về chi tiêu hộ gia đình sẽ được công bố vào tuần tới.","image_url":"https://images.pexels.com/photos/4959907/pexels-photo-4959907.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"collect data"},{"phrase":"data analysis"},{"phrase":"reliable data"},{"phrase":"the latest data"}]','Số nhiều của datum; đi được với động từ số ít hoặc số nhiều','/ˈdeɪtə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/data_/data__us_3_rr.mp3','https://images.pexels.com/photos/17489163/pexels-photo-17489163.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"panumas nikhomkhai","author_url":"https://www.pexels.com/@cookiecutter","source_url":"https://www.pexels.com/photo/computer-server-in-data-center-room-17489163/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(76,'awl-1-01',16,'define','định nghĩa; xác định','verb','[{"en":"It is hard to define exactly what makes a good teacher.","vi":"Rất khó để định nghĩa chính xác thế nào là một giáo viên giỏi.","image_url":"https://images.pexels.com/photos/8197497/pexels-photo-8197497.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"In this study, poverty is defined as living on less than two dollars a day.","vi":"Trong nghiên cứu này, nghèo đói được định nghĩa là sống với dưới hai đô la mỗi ngày.","image_url":"https://images.pexels.com/photos/8719574/pexels-photo-8719574.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The contract clearly defines the duties of each partner.","vi":"Hợp đồng xác định rõ nghĩa vụ của mỗi bên.","image_url":"https://images.pexels.com/photos/5520297/pexels-photo-5520297.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"clearly define"},{"phrase":"be defined as"},{"phrase":"broadly defined"}]',NULL,'/dɪˈfaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/define__us_2.mp3','https://images.pexels.com/photos/18002046/pexels-photo-18002046.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Farhad Irani","author_url":"https://www.pexels.com/@farhadirani","source_url":"https://www.pexels.com/photo/muscular-model-posing-by-window-18002046/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(77,'awl-1-01',17,'derive','bắt nguồn (từ); có được, rút ra (từ)','verb','[{"en":"Many English words are derived from Latin or Greek.","vi":"Nhiều từ tiếng Anh có nguồn gốc từ tiếng La-tinh hoặc tiếng Hy Lạp.","image_url":"https://images.pexels.com/photos/256417/pexels-photo-256417.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The results were derived from a survey of 500 teachers.","vi":"Các kết quả này được rút ra từ một cuộc khảo sát 500 giáo viên.","image_url":"https://images.pexels.com/photos/6684373/pexels-photo-6684373.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Older people often derive great pleasure from gardening.","vi":"Người lớn tuổi thường tìm thấy niềm vui lớn từ việc làm vườn.","image_url":"https://images.pexels.com/photos/6787679/pexels-photo-6787679.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"derive from"},{"phrase":"be derived from"},{"phrase":"derive pleasure from"}]','derive from: bắt nguồn từ; derive sth from sth: có được cái gì từ','/dɪˈraɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/der/deriv/derive__us_1.mp3','https://images.pexels.com/photos/33367162/pexels-photo-33367162.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"César O''neill","author_url":"https://www.pexels.com/@cesar-o-neill-26650613","source_url":"https://www.pexels.com/photo/assortment-of-natural-clays-and-minerals-on-wooden-plates-33367162/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(78,'awl-1-01',18,'distribute','phân phối; phân phát; phân bổ','verb','[{"en":"Volunteers distributed food and water to families after the storm.","vi":"Các tình nguyện viên đã phát thực phẩm và nước cho các gia đình sau cơn bão.","image_url":"https://images.pexels.com/photos/6646878/pexels-photo-6646878.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The company distributes its products to over forty countries.","vi":"Công ty phân phối sản phẩm của mình tới hơn bốn mươi quốc gia.","image_url":"https://images.pexels.com/photos/32399796/pexels-photo-32399796.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Wealth is not evenly distributed across the population.","vi":"Của cải không được phân bổ đồng đều trong dân cư.","image_url":"https://images.pexels.com/photos/29675062/pexels-photo-29675062.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"distribute food"},{"phrase":"evenly distributed"},{"phrase":"widely distributed"}]',NULL,'/dɪˈstrɪbjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distr/distribute__us_1_rr.mp3','https://images.pexels.com/photos/6699395/pexels-photo-6699395.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Gustavo Fring","author_url":"https://www.pexels.com/@gustavo-fring","source_url":"https://www.pexels.com/photo/a-man-and-a-woman-holding-a-cardboard-box-6699395/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(79,'awl-1-01',19,'economy','nền kinh tế','noun','[{"en":"The global economy grew more slowly than expected last year.","vi":"Năm ngoái, nền kinh tế toàn cầu tăng trưởng chậm hơn dự kiến.","image_url":"https://images.pexels.com/photos/7412102/pexels-photo-7412102.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Tourism plays an important role in the local economy.","vi":"Du lịch đóng vai trò quan trọng trong nền kinh tế địa phương.","image_url":"https://images.pexels.com/photos/34835271/pexels-photo-34835271.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Experts believe the economy will recover by next spring.","vi":"Các chuyên gia tin rằng nền kinh tế sẽ phục hồi vào mùa xuân tới.","image_url":"https://images.pexels.com/photos/39121210/pexels-photo-39121210.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"global economy"},{"phrase":"local economy"},{"phrase":"boost the economy"}]',NULL,'/ɪˈkɑːnəmi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eco/econo/economy__us_1.mp3','https://images.pexels.com/photos/10531120/pexels-photo-10531120.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Zucker Pop","author_url":"https://www.pexels.com/@zucker-pop-140939669","source_url":"https://www.pexels.com/photo/stacks-of-silver-and-gold-coins-in-close-up-photography-10531120/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(80,'awl-1-01',20,'environment','môi trường; hoàn cảnh','noun','[{"en":"Plastic waste is causing serious damage to the environment.","vi":"Rác thải nhựa đang gây thiệt hại nghiêm trọng cho môi trường.","image_url":"https://images.pexels.com/photos/8770258/pexels-photo-8770258.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Children learn best in a safe and friendly environment.","vi":"Trẻ em học tốt nhất trong một môi trường an toàn và thân thiện.","image_url":"https://images.pexels.com/photos/6725335/pexels-photo-6725335.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Staff say the company offers a pleasant working environment.","vi":"Nhân viên cho biết công ty có môi trường làm việc dễ chịu.","image_url":"https://images.pexels.com/photos/13062477/pexels-photo-13062477.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"protect the environment"},{"phrase":"natural environment"},{"phrase":"working environment"},{"phrase":"learning environment"}]',NULL,'/ɪnˈvaɪrənmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envir/environment__us_2_rr.mp3','https://images.pexels.com/photos/4231781/pexels-photo-4231781.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Jorge Bilbao","author_url":"https://www.pexels.com/@bilbaojl","source_url":"https://www.pexels.com/photo/rippled-river-between-greenery-mountains-under-sky-4231781/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(81,'awl-1-01',21,'establish','thành lập; thiết lập; xác định','verb','[{"en":"The research center was established in 1998 to study ocean pollution.","vi":"Trung tâm nghiên cứu được thành lập năm 1998 để nghiên cứu ô nhiễm đại dương.","image_url":"https://images.pexels.com/photos/15304868/pexels-photo-15304868.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The two countries established trade links in the early 1990s.","vi":"Hai nước đã thiết lập quan hệ thương mại vào đầu những năm 1990.","image_url":"https://images.pexels.com/photos/9498282/pexels-photo-9498282.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Police are trying to establish the cause of the fire.","vi":"Cảnh sát đang cố gắng xác định nguyên nhân vụ cháy.","image_url":"https://images.pexels.com/photos/9739635/pexels-photo-9739635.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"establish a relationship"},{"phrase":"establish links"},{"phrase":"establish the cause"},{"phrase":"well established"}]',NULL,'/ɪˈstæblɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estab/establish__us_2.mp3','https://images.pexels.com/photos/7207643/pexels-photo-7207643.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"𝗛&𝗖𝗢 　","author_url":"https://www.pexels.com/@hngstrm","source_url":"https://www.pexels.com/photo/staff-only-signage-on-the-door-7207643/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(82,'awl-1-01',22,'estimate','ước tính','verb','[{"en":"Experts estimate that the project will cost two million dollars.","vi":"Các chuyên gia ước tính dự án sẽ tốn hai triệu đô la.","image_url":"https://images.pexels.com/photos/6590650/pexels-photo-6590650.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"It is difficult to estimate how many people use the service.","vi":"Rất khó ước tính có bao nhiêu người sử dụng dịch vụ này.","image_url":"https://images.pexels.com/photos/31467490/pexels-photo-31467490.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The city''s population is estimated at around 1.5 million.","vi":"Dân số của thành phố ước tính vào khoảng 1,5 triệu người.","image_url":"https://images.pexels.com/photos/3120002/pexels-photo-3120002.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"estimate the cost"},{"phrase":"be estimated at"},{"phrase":"it is estimated that"}]','Cũng là danh từ: a rough estimate (ước tính sơ bộ)','/ˈestɪmeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estim/estimate__us_2.mp3','https://images.pexels.com/photos/7491011/pexels-photo-7491011.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"RDNE Stock project","author_url":"https://www.pexels.com/@rdne","source_url":"https://www.pexels.com/photo/woman-uses-calculator-7491011/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(83,'awl-1-01',23,'evident','rõ ràng, hiển nhiên','adjective','[{"en":"It was evident that the students had not read the article.","vi":"Rõ ràng là các sinh viên đã không đọc bài báo đó.","image_url":"https://images.pexels.com/photos/5537507/pexels-photo-5537507.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The effects of climate change are already evident in many regions.","vi":"Tác động của biến đổi khí hậu đã hiện rõ ở nhiều khu vực.","image_url":"https://images.pexels.com/photos/35279538/pexels-photo-35279538.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Her love of science was evident from an early age.","vi":"Niềm yêu thích khoa học của cô ấy đã thể hiện rõ từ khi còn nhỏ.","image_url":"https://images.pexels.com/photos/30473621/pexels-photo-30473621.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"it is evident that"},{"phrase":"clearly evident"},{"phrase":"become evident"}]',NULL,'/ˈevɪdənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evi/evide/evident__us_1.mp3','https://images.pexels.com/photos/16954318/pexels-photo-16954318.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"TREEDEO.ST","author_url":"https://www.pexels.com/@treedeo","source_url":"https://www.pexels.com/photo/hand-putting-evidence-number-on-pavement-on-crime-scene-16954318/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(84,'awl-1-01',24,'export','hàng xuất khẩu; sự xuất khẩu','noun','[{"en":"Coffee is one of the country''s main exports.","vi":"Cà phê là một trong những mặt hàng xuất khẩu chính của đất nước.","image_url":"https://images.pexels.com/photos/17052668/pexels-photo-17052668.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Rice exports rose by ten percent last year.","vi":"Năm ngoái, xuất khẩu gạo tăng mười phần trăm.","image_url":"https://images.pexels.com/photos/37051981/pexels-photo-37051981.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The factory produces furniture mainly for export.","vi":"Nhà máy sản xuất đồ nội thất chủ yếu để xuất khẩu.","image_url":"https://images.pexels.com/photos/32399707/pexels-photo-32399707.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"main export"},{"phrase":"export market"},{"phrase":"for export"}]','Động từ export (nhấn âm 2): xuất khẩu','/ˈekspɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expor/export__us_2.mp3','https://images.pexels.com/photos/18874291/pexels-photo-18874291.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"TwoSix ZeroFive","author_url":"https://www.pexels.com/@twosix-zerofive-771736124","source_url":"https://www.pexels.com/photo/man-standing-in-container-with-bottles-18874291/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(85,'awl-1-01',25,'factor','yếu tố, nhân tố','noun','[{"en":"Cost is an important factor when choosing a university.","vi":"Chi phí là một yếu tố quan trọng khi chọn trường đại học.","image_url":"https://images.pexels.com/photos/7054368/pexels-photo-7054368.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Several factors led to the fall in sales.","vi":"Một số yếu tố đã dẫn đến sự sụt giảm doanh số.","image_url":"https://images.pexels.com/photos/7956393/pexels-photo-7956393.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Smoking is a major risk factor for heart disease.","vi":"Hút thuốc là một yếu tố nguy cơ chính gây bệnh tim.","image_url":"https://images.pexels.com/photos/5812982/pexels-photo-5812982.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"important factor"},{"phrase":"key factor"},{"phrase":"major factor"},{"phrase":"risk factor"}]',NULL,'/ˈfæktər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facto/factor__us_2.mp3','https://images.pexels.com/photos/38795663/pexels-photo-38795663.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Travel with  Lenses","author_url":"https://www.pexels.com/@travel-with-lenses-734723610","source_url":"https://www.pexels.com/photo/cyclists-racing-in-copenhagen-city-event-38795663/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(86,'awl-1-01',26,'finance','tài chính','noun','[{"en":"She has a degree in finance from a leading business school.","vi":"Cô ấy có bằng tài chính của một trường kinh doanh hàng đầu.","image_url":"https://images.pexels.com/photos/37846676/pexels-photo-37846676.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Many students struggle to manage their personal finances.","vi":"Nhiều sinh viên gặp khó khăn trong việc quản lý tài chính cá nhân.","image_url":"https://images.pexels.com/photos/10994723/pexels-photo-10994723.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The finance department will review the budget next week.","vi":"Phòng tài chính sẽ xem xét ngân sách vào tuần tới.","image_url":"https://images.pexels.com/photos/221174/pexels-photo-221174.png?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"personal finances"},{"phrase":"finance department"},{"phrase":"public finances"}]','Cũng là động từ: cấp vốn, tài trợ','/ˈfaɪnæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finan/finance__us_1_rr.mp3','https://images.pexels.com/photos/4968631/pexels-photo-4968631.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"https://kaboompics.com/","author_url":"https://www.pexels.com/@karola-g","source_url":"https://www.pexels.com/photo/counting-dollar-bills-4968631/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(87,'awl-1-01',27,'formula','công thức','noun','[{"en":"Students must learn the formula for the area of a circle.","vi":"Học sinh phải học công thức tính diện tích hình tròn.","image_url":"https://images.pexels.com/photos/39191014/pexels-photo-39191014.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"The chemical formula for water is H2O.","vi":"Công thức hóa học của nước là H2O.","image_url":"https://images.pexels.com/photos/3825468/pexels-photo-3825468.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"There is no simple formula for success in business.","vi":"Không có công thức đơn giản nào để thành công trong kinh doanh.","image_url":"https://images.pexels.com/photos/39191023/pexels-photo-39191023.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"mathematical formula"},{"phrase":"chemical formula"},{"phrase":"simple formula"},{"phrase":"formula for"}]','Số nhiều: formulas hoặc formulae','/ˈfɔːrmjələ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/formu/formula__us_1.mp3','https://images.pexels.com/photos/3781338/pexels-photo-3781338.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Jeswin  Thomas","author_url":"https://www.pexels.com/@jeswin","source_url":"https://www.pexels.com/photo/person-writing-on-white-board-3781338/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(88,'awl-1-01',28,'function','chức năng; hàm số','noun','[{"en":"The main function of the heart is to pump blood around the body.","vi":"Chức năng chính của tim là bơm máu đi khắp cơ thể.","image_url":"https://images.pexels.com/photos/5340267/pexels-photo-5340267.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"This app has a very useful search function.","vi":"Ứng dụng này có chức năng tìm kiếm rất hữu ích.","image_url":"https://images.pexels.com/photos/5807811/pexels-photo-5807811.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"In this lesson, we will learn how to draw the graph of a function.","vi":"Trong bài học này, chúng ta sẽ học cách vẽ đồ thị của một hàm số.","image_url":"https://images.pexels.com/photos/8482035/pexels-photo-8482035.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"main function"},{"phrase":"perform a function"},{"phrase":"brain function"}]','Cũng là động từ: hoạt động; function as: đóng vai trò là','/ˈfʌŋkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funct/function__us_4.mp3','https://images.pexels.com/photos/37911188/pexels-photo-37911188.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Shubham Dhage","author_url":"https://www.pexels.com/@shubhamdhage","source_url":"https://www.pexels.com/photo/colorful-geometric-boxes-with-mathematical-symbols-37911188/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(89,'awl-1-01',29,'identify','xác định; nhận ra, nhận diện','verb','[{"en":"The study identified three main causes of stress at work.","vi":"Nghiên cứu đã xác định ba nguyên nhân chính gây căng thẳng tại nơi làm việc.","image_url":"https://images.pexels.com/photos/5908779/pexels-photo-5908779.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Can you identify the bird in this picture?","vi":"Bạn có nhận diện được con chim trong bức ảnh này không?","image_url":"https://images.pexels.com/photos/8073783/pexels-photo-8073783.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Teachers need to identify students who need extra help early.","vi":"Giáo viên cần sớm nhận ra những học sinh cần được hỗ trợ thêm.","image_url":"https://images.pexels.com/photos/8363012/pexels-photo-8363012.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"identify the cause"},{"phrase":"identify problems"},{"phrase":"clearly identify"}]',NULL,'/aɪˈdentɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identify__us_3.mp3','https://images.pexels.com/photos/8382611/pexels-photo-8382611.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"cottonbro studio","author_url":"https://www.pexels.com/@cottonbro","source_url":"https://www.pexels.com/photo/close-up-photo-of-fingerpints-on-paper-8382611/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(90,'awl-1-01',30,'income','thu nhập','noun','[{"en":"Families with low incomes will receive extra support.","vi":"Các gia đình có thu nhập thấp sẽ được hỗ trợ thêm.","image_url":"https://images.pexels.com/photos/8297589/pexels-photo-8297589.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Tourism is the island''s main source of income.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo.","image_url":"https://images.pexels.com/photos/31421280/pexels-photo-31421280.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Her monthly income increased after she changed jobs.","vi":"Thu nhập hàng tháng của cô ấy tăng lên sau khi cô chuyển việc.","image_url":"https://images.pexels.com/photos/5900184/pexels-photo-5900184.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"low income"},{"phrase":"source of income"},{"phrase":"household income"},{"phrase":"annual income"}]',NULL,'/ˈɪnkʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incom/income__us_1_rr.mp3','https://images.pexels.com/photos/7654617/pexels-photo-7654617.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200','{"source":"pexels","author":"Pavel Danilyuk","author_url":"https://www.pexels.com/@pavel-danilyuk","source_url":"https://www.pexels.com/photo/woman-wearing-eyeglasses-while-sitting-on-office-chair-7654617/"}');
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(91,'awl-1-02',1,'indicate','cho thấy; chỉ ra; biểu thị','verb','[{"en":"The results indicate a strong link between sleep and memory.","vi":"Kết quả cho thấy mối liên hệ chặt chẽ giữa giấc ngủ và trí nhớ."},{"en":"Recent surveys indicate that most employees prefer flexible working hours.","vi":"Các khảo sát gần đây chỉ ra rằng phần lớn nhân viên thích giờ làm việc linh hoạt.","image_url":"https://images.pexels.com/photos/18955784/pexels-photo-18955784.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"A red light on the panel indicates a problem with the power supply.","vi":"Đèn đỏ trên bảng điều khiển biểu thị sự cố về nguồn điện."}]','[{"phrase":"results indicate"},{"phrase":"evidence indicates"},{"phrase":"clearly indicate"},{"phrase":"studies indicate"}]',NULL,'/ˈɪndɪkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indic/indicate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(92,'awl-1-02',2,'individual','cá nhân; riêng; từng (người, cái)','adjective','[{"en":"Teachers should pay attention to the individual needs of each student.","vi":"Giáo viên nên chú ý đến nhu cầu riêng của từng học sinh."},{"en":"The report looks at individual countries rather than the whole region.","vi":"Báo cáo xem xét từng quốc gia thay vì cả khu vực."},{"en":"The company rewards both team success and individual performance.","vi":"Công ty khen thưởng cả thành công của nhóm lẫn thành tích cá nhân."}]','[{"phrase":"individual needs"},{"phrase":"individual performance"},{"phrase":"individual rights"},{"phrase":"individual responsibility"}]','Cũng là danh từ: an individual (một cá nhân)','/ˌɪndɪˈvɪdʒuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indiv/individual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(93,'awl-1-02',3,'interpret','diễn giải; hiểu (là); phiên dịch','verb','[{"en":"Researchers must be careful when they interpret results from small samples.","vi":"Các nhà nghiên cứu phải cẩn trọng khi diễn giải kết quả từ các mẫu nhỏ."},{"en":"His silence was interpreted as agreement by the rest of the team.","vi":"Sự im lặng của anh ấy được những người còn lại trong nhóm hiểu là đồng ý."},{"en":"She interpreted for the visiting engineers during the factory tour.","vi":"Cô ấy phiên dịch cho các kỹ sư đến thăm trong chuyến tham quan nhà máy.","image_url":"https://images.pexels.com/photos/20684151/pexels-photo-20684151.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"interpret data"},{"phrase":"interpret results"},{"phrase":"interpret something as"},{"phrase":"correctly interpret"}]',NULL,'/ɪnˈtɜːrprət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interpret__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(94,'awl-1-02',4,'involve','bao gồm; đòi hỏi; cho tham gia','verb','[{"en":"The job involves a lot of travel within the region.","vi":"Công việc này đòi hỏi phải đi lại nhiều trong khu vực."},{"en":"The study involved more than two thousand adults from five countries.","vi":"Nghiên cứu có sự tham gia của hơn hai nghìn người trưởng thành từ năm quốc gia."},{"en":"Parents should be involved in decisions about their children''s education.","vi":"Cha mẹ nên được tham gia vào các quyết định về việc học của con cái."}]','[{"phrase":"be involved in"},{"phrase":"involve risk"},{"phrase":"directly involved"},{"phrase":"actively involve"}]','be involved in: tham gia vào, liên quan đến','/ɪnˈvɑːlv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invol/involve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(95,'awl-1-02',5,'issue','vấn đề; số (báo, tạp chí)','noun','[{"en":"Climate change is a major issue for coastal cities.","vi":"Biến đổi khí hậu là một vấn đề lớn đối với các thành phố ven biển."},{"en":"The committee will discuss the issue at its next meeting.","vi":"Ủy ban sẽ thảo luận vấn đề này tại cuộc họp tới."},{"en":"The article appeared in the latest issue of the journal.","vi":"Bài báo được đăng trong số mới nhất của tạp chí."}]','[{"phrase":"major issue"},{"phrase":"discuss an issue"},{"phrase":"raise an issue"},{"phrase":"address an issue"}]','Cũng là động từ: issue a statement (ra tuyên bố)','/ˈɪʃuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iss/issue/issue__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(96,'awl-1-02',6,'labour','lao động; nhân công','noun','[{"en":"The factory moved production abroad to reduce labour costs.","vi":"Nhà máy chuyển hoạt động sản xuất ra nước ngoài để giảm chi phí nhân công."},{"en":"Many farms rely on seasonal labour during the harvest.","vi":"Nhiều trang trại dựa vào lao động thời vụ trong mùa thu hoạch."},{"en":"The labour market has become more competitive for young graduates.","vi":"Thị trường lao động đã trở nên cạnh tranh hơn đối với sinh viên mới tốt nghiệp."}]','[{"phrase":"labour costs"},{"phrase":"labour market"},{"phrase":"skilled labour"},{"phrase":"cheap labour"}]','Anh: labour · Mỹ: labor; không đếm được','/ˈleɪbər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/labou/labour__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(97,'awl-1-02',7,'legal','hợp pháp; (thuộc) pháp luật, pháp lý','adjective','[{"en":"The company sought legal advice before signing the contract.","vi":"Công ty đã tìm tư vấn pháp lý trước khi ký hợp đồng."},{"en":"Is it legal to drive with a foreign license here?","vi":"Ở đây lái xe bằng giấy phép nước ngoài có hợp pháp không?"},{"en":"Every country has its own legal system and traditions.","vi":"Mỗi quốc gia đều có hệ thống pháp luật và truyền thống riêng."}]','[{"phrase":"legal advice"},{"phrase":"legal system"},{"phrase":"legal action"},{"phrase":"legal requirement"}]','Trái nghĩa: illegal (bất hợp pháp)','/ˈliːɡl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legal/legal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(98,'awl-1-02',8,'legislate','ban hành luật; lập pháp','verb','[{"en":"Many governments have begun to legislate against plastic waste.","vi":"Nhiều chính phủ đã bắt đầu ban hành luật chống rác thải nhựa."},{"en":"It is difficult to legislate for every possible situation.","vi":"Thật khó để ban hành luật cho mọi tình huống có thể xảy ra.","image_url":"https://images.pexels.com/photos/9755375/pexels-photo-9755375.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"Several states have legislated to protect workers'' personal data.","vi":"Một số bang đã ban hành luật để bảo vệ dữ liệu cá nhân của người lao động."}]','[{"phrase":"legislate against"},{"phrase":"legislate for"},{"phrase":"legislate to protect"}]','Danh từ: legislation (luật pháp; sự lập pháp)','/ˈledʒɪsleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legis/legislate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(99,'awl-1-02',9,'major','lớn; chính; quan trọng','adjective','[{"en":"Traffic is a major cause of air pollution in large cities.","vi":"Giao thông là nguyên nhân chính gây ô nhiễm không khí ở các thành phố lớn."},{"en":"The new policy led to major changes in how staff are trained.","vi":"Chính sách mới đã dẫn đến những thay đổi lớn trong cách đào tạo nhân viên."},{"en":"Researchers faced a major problem when their funding was cut.","vi":"Các nhà nghiên cứu gặp phải một vấn đề lớn khi kinh phí bị cắt giảm."}]','[{"phrase":"major cause"},{"phrase":"major change"},{"phrase":"major problem"},{"phrase":"major role"}]','Trái nghĩa: minor; (Mỹ, n) chuyên ngành chính ở đại học','/ˈmeɪdʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/maj/major/major__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(100,'awl-1-02',10,'method','phương pháp; cách thức','noun','[{"en":"This teaching method encourages students to work in small groups.","vi":"Phương pháp giảng dạy này khuyến khích học sinh làm việc theo nhóm nhỏ."},{"en":"Which method did you use to collect the data?","vi":"Bạn đã dùng phương pháp nào để thu thập dữ liệu?"},{"en":"Bank transfer is still the most common method of payment.","vi":"Chuyển khoản ngân hàng vẫn là phương thức thanh toán phổ biến nhất."}]','[{"phrase":"teaching method"},{"phrase":"research method"},{"phrase":"method of payment"},{"phrase":"effective method"}]',NULL,'/ˈmeθəd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/metho/method__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(101,'awl-1-02',11,'occur','xảy ra; xuất hiện; nảy ra (trong đầu)','verb','[{"en":"Most workplace accidents occur when safety rules are ignored.","vi":"Hầu hết tai nạn lao động xảy ra khi các quy định an toàn bị phớt lờ."},{"en":"The disease occurs mainly in tropical regions.","vi":"Căn bệnh này chủ yếu xuất hiện ở các vùng nhiệt đới."},{"en":"It never occurred to me that the data might be wrong.","vi":"Tôi chưa bao giờ nghĩ rằng dữ liệu có thể bị sai."}]','[{"phrase":"occur naturally"},{"phrase":"frequently occur"},{"phrase":"occur to someone"}]','occur – occurred – occurring (gấp đôi r)','/əˈkɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occur/occur__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(102,'awl-1-02',12,'percent','phần trăm','noun','[{"en":"Sales rose by 15 percent in the first quarter.","vi":"Doanh số tăng 15 phần trăm trong quý đầu tiên."},{"en":"Only 40 percent of the students completed the online survey.","vi":"Chỉ 40 phần trăm sinh viên hoàn thành bản khảo sát trực tuyến."},{"en":"About 70 percent of the Earth''s surface is covered by water.","vi":"Khoảng 70 phần trăm bề mặt Trái Đất được bao phủ bởi nước."}]','[{"phrase":"rise by 10 percent"},{"phrase":"percent of the population"},{"phrase":"a 5 percent increase"}]','Anh: per cent · Mỹ: percent; ký hiệu %','/pərˈsɛnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(103,'awl-1-02',13,'period','giai đoạn; thời kỳ; khoảng thời gian','noun','[{"en":"The project will be completed over a period of three years.","vi":"Dự án sẽ được hoàn thành trong khoảng thời gian ba năm."},{"en":"Prices remained fairly stable during this period of growth.","vi":"Giá cả vẫn khá ổn định trong suốt giai đoạn tăng trưởng này."},{"en":"New employees usually have a trial period of two months.","vi":"Nhân viên mới thường có thời gian thử việc hai tháng."}]','[{"phrase":"over a period of"},{"phrase":"a period of time"},{"phrase":"trial period"},{"phrase":"short period"}]',NULL,'/ˈpɪriəd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perio/period__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(104,'awl-1-02',14,'policy','chính sách; quy định','noun','[{"en":"The government introduced a new policy to support small businesses.","vi":"Chính phủ đã đưa ra một chính sách mới để hỗ trợ doanh nghiệp nhỏ."},{"en":"Our company has a strict policy on the use of personal phones.","vi":"Công ty chúng tôi có quy định nghiêm ngặt về việc sử dụng điện thoại cá nhân."},{"en":"Economic policy should focus on creating more stable jobs.","vi":"Chính sách kinh tế nên tập trung vào việc tạo ra nhiều việc làm ổn định hơn."}]','[{"phrase":"introduce a policy"},{"phrase":"government policy"},{"phrase":"economic policy"},{"phrase":"policy on"}]',NULL,'/ˈpɑːləsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polic/policy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(105,'awl-1-02',15,'principle','nguyên tắc; nguyên lý','noun','[{"en":"The course explains the basic principles of economics.","vi":"Khóa học giải thích những nguyên lý cơ bản của kinh tế học."},{"en":"Fairness is a key principle in our hiring process.","vi":"Công bằng là một nguyên tắc then chốt trong quy trình tuyển dụng của chúng tôi."},{"en":"In principle, the plan is good, but it may be too expensive.","vi":"Về nguyên tắc, kế hoạch này tốt, nhưng có thể quá tốn kém."}]','[{"phrase":"basic principle"},{"phrase":"key principle"},{"phrase":"general principle"},{"phrase":"in principle"}]','principle (nguyên tắc) ≠ principal (hiệu trưởng; chính)','/ˈprɪnsəpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(106,'awl-1-02',16,'proceed','tiếp tục; tiến hành; đi tới','verb','[{"en":"After a short break, the meeting proceeded as planned.","vi":"Sau giờ nghỉ ngắn, cuộc họp tiếp tục như dự kiến."},{"en":"The city council decided to proceed with the new housing project.","vi":"Hội đồng thành phố quyết định tiến hành dự án nhà ở mới."},{"en":"Passengers on the morning flight should proceed to gate 12.","vi":"Hành khách của chuyến bay buổi sáng vui lòng đi đến cổng số 12."}]','[{"phrase":"proceed with"},{"phrase":"proceed to"},{"phrase":"proceed as planned"}]','proceed with something: tiến hành việc gì','/prəʊˈsiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/proceed__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(107,'awl-1-02',17,'process','quá trình; quy trình','noun','[{"en":"Learning a language is a slow process that takes patience.","vi":"Học một ngôn ngữ là một quá trình chậm, cần sự kiên nhẫn."},{"en":"The company has simplified its application process for new customers.","vi":"Công ty đã đơn giản hóa quy trình đăng ký cho khách hàng mới."},{"en":"We are still in the process of reviewing your request.","vi":"Chúng tôi vẫn đang trong quá trình xem xét yêu cầu của bạn."}]','[{"phrase":"in the process of"},{"phrase":"application process"},{"phrase":"decision-making process"},{"phrase":"production process"}]','Cũng là động từ: process data (xử lý dữ liệu)','/ˈprɑːses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/process__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(108,'awl-1-02',18,'require','đòi hỏi; cần; yêu cầu','verb','[{"en":"Most jobs in this field require a university degree.","vi":"Hầu hết công việc trong lĩnh vực này đòi hỏi bằng đại học."},{"en":"All visitors are required to sign in at reception.","vi":"Tất cả khách đến thăm đều được yêu cầu đăng ký tại quầy lễ tân."},{"en":"The experiment requires careful planning and accurate measurement.","vi":"Thí nghiệm này cần được lên kế hoạch cẩn thận và đo đạc chính xác."}]','[{"phrase":"be required to"},{"phrase":"require careful planning"},{"phrase":"require attention"}]','be required to do something: được yêu cầu, bắt buộc phải làm gì','/rɪˈkwaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/requi/require__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(109,'awl-1-02',19,'research','nghiên cứu; sự nghiên cứu','noun','[{"en":"Recent research shows that regular exercise can improve memory.","vi":"Nghiên cứu gần đây cho thấy tập thể dục thường xuyên có thể cải thiện trí nhớ."},{"en":"She is doing research on renewable energy at the university.","vi":"Cô ấy đang nghiên cứu về năng lượng tái tạo tại trường đại học.","image_url":"https://images.pexels.com/photos/6208712/pexels-photo-6208712.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"},{"en":"More research is needed before the drug can be approved.","vi":"Cần thêm nghiên cứu trước khi loại thuốc này được phê duyệt."}]','[{"phrase":"do research"},{"phrase":"carry out research"},{"phrase":"research on"},{"phrase":"further research"}]','Không đếm được (không nói ''a research''); cũng là động từ','/ˈriːsɜːrtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resea/research__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(110,'awl-1-02',20,'respond','trả lời; phản hồi; phản ứng','verb','[{"en":"The company responded quickly to customer complaints.","vi":"Công ty đã phản hồi nhanh chóng trước khiếu nại của khách hàng."},{"en":"Please respond to this email by Friday.","vi":"Vui lòng trả lời email này trước thứ Sáu."},{"en":"Patients usually respond well to this kind of treatment.","vi":"Bệnh nhân thường đáp ứng tốt với phương pháp điều trị này."}]','[{"phrase":"respond to"},{"phrase":"respond quickly"},{"phrase":"respond well to"},{"phrase":"respond positively"}]','respond to something; danh từ: response','/rɪˈspɑːnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/respond__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(111,'awl-1-02',21,'role','vai trò; vai (diễn)','noun','[{"en":"Technology plays an important role in modern healthcare.","vi":"Công nghệ đóng vai trò quan trọng trong ngành y tế hiện đại."},{"en":"Her role in the project is to manage the budget.","vi":"Vai trò của cô ấy trong dự án là quản lý ngân sách."},{"en":"He was offered the leading role in the school play.","vi":"Cậu ấy được mời đóng vai chính trong vở kịch của trường."}]','[{"phrase":"play a role"},{"phrase":"important role"},{"phrase":"key role"},{"phrase":"leading role"}]','play a role in something: đóng vai trò trong việc gì','/rəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rol/role_/role__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(112,'awl-1-02',22,'section','phần; mục; khu (vực)','noun','[{"en":"Please read the first section of the report before the meeting.","vi":"Vui lòng đọc phần đầu tiên của báo cáo trước cuộc họp."},{"en":"The test has three sections: reading, writing, and listening.","vi":"Bài kiểm tra có ba phần: đọc, viết và nghe."},{"en":"The fruit and vegetable section is at the back of the store.","vi":"Khu rau củ quả nằm ở phía sau cửa hàng."}]','[{"phrase":"section of the report"},{"phrase":"the following section"},{"phrase":"the previous section"}]',NULL,'/ˈsekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secti/section__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(113,'awl-1-02',23,'sector','khu vực (kinh tế); lĩnh vực; ngành','noun','[{"en":"The public sector employs nearly a quarter of the workforce.","vi":"Khu vực công sử dụng gần một phần tư lực lượng lao động."},{"en":"Jobs in the technology sector are growing quickly.","vi":"Việc làm trong lĩnh vực công nghệ đang tăng nhanh."},{"en":"Tourism is the largest sector of the local economy.","vi":"Du lịch là ngành lớn nhất của nền kinh tế địa phương."}]','[{"phrase":"public sector"},{"phrase":"private sector"},{"phrase":"service sector"},{"phrase":"manufacturing sector"}]',NULL,'/ˈsektər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secto/sector__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(114,'awl-1-02',24,'significant','đáng kể; quan trọng; có ý nghĩa (thống kê)','adjective','[{"en":"There has been a significant increase in online shopping.","vi":"Mua sắm trực tuyến đã có sự gia tăng đáng kể."},{"en":"The study found no significant difference between the two groups.","vi":"Nghiên cứu không tìm thấy khác biệt có ý nghĩa giữa hai nhóm."},{"en":"This was a significant moment in the history of medicine.","vi":"Đây là một thời khắc quan trọng trong lịch sử y học."}]','[{"phrase":"significant increase"},{"phrase":"significant difference"},{"phrase":"statistically significant"},{"phrase":"significant role"}]','Danh từ: significance; trạng từ: significantly','/sɪɡˈnɪfɪkənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(115,'awl-1-02',25,'similar','tương tự; giống nhau','adjective','[{"en":"The two reports reached similar conclusions about the causes of the problem.","vi":"Hai báo cáo đưa ra những kết luận tương tự nhau về nguyên nhân của vấn đề."},{"en":"My new job is similar to my old one.","vi":"Công việc mới của tôi giống với công việc cũ."},{"en":"Similar results were found in studies in other countries.","vi":"Các nghiên cứu ở những nước khác cho ra kết quả tương tự."}]','[{"phrase":"similar to"},{"phrase":"very similar"},{"phrase":"similar results"},{"phrase":"remarkably similar"}]','similar to something: giống với cái gì','/ˈsɪmələr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simil/similar__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(116,'awl-1-02',26,'source','nguồn; nguồn gốc','noun','[{"en":"Fruit is a good source of vitamins and fiber.","vi":"Trái cây là một nguồn vitamin và chất xơ tốt."},{"en":"Always check your sources before you cite them in an essay.","vi":"Hãy luôn kiểm tra nguồn tài liệu trước khi trích dẫn chúng trong bài luận."},{"en":"Engineers are still trying to find the source of the leak.","vi":"Các kỹ sư vẫn đang cố tìm ra nguồn gốc của chỗ rò rỉ."}]','[{"phrase":"a good source of"},{"phrase":"main source of income"},{"phrase":"reliable source"},{"phrase":"energy source"}]',NULL,'/sɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/sourc/source__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(117,'awl-1-02',27,'specific','cụ thể; riêng; đặc thù','adjective','[{"en":"Can you give me a specific example of the problem?","vi":"Bạn có thể cho tôi một ví dụ cụ thể về vấn đề này không?"},{"en":"The training is designed for the specific needs of nurses.","vi":"Khóa đào tạo được thiết kế cho nhu cầu đặc thù của điều dưỡng."},{"en":"These plants grow only under very specific conditions.","vi":"Những loài cây này chỉ phát triển trong những điều kiện rất riêng biệt."}]','[{"phrase":"specific example"},{"phrase":"specific needs"},{"phrase":"specific to"},{"phrase":"specific conditions"}]','specific to something: đặc trưng cho, chỉ có ở','/spəˈsɪfɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specific__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(118,'awl-1-02',28,'structure','cấu trúc; cơ cấu; kết cấu','noun','[{"en":"The essay has a clear structure with an introduction and a conclusion.","vi":"Bài luận có cấu trúc rõ ràng với phần mở bài và phần kết luận."},{"en":"Scientists studied the structure of the cell in great detail.","vi":"Các nhà khoa học đã nghiên cứu rất chi tiết cấu trúc của tế bào."},{"en":"Last year, the company changed its management structure.","vi":"Năm ngoái, công ty đã thay đổi cơ cấu quản lý."}]','[{"phrase":"clear structure"},{"phrase":"basic structure"},{"phrase":"management structure"},{"phrase":"social structure"}]',NULL,'/ˈstrʌktʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/struc/structure__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(119,'awl-1-02',29,'theory','lý thuyết; học thuyết; giả thuyết','noun','[{"en":"Economic theory cannot always predict how people will behave.","vi":"Lý thuyết kinh tế không phải lúc nào cũng dự đoán được con người sẽ hành xử ra sao."},{"en":"The idea sounds good in theory, but it rarely works in practice.","vi":"Ý tưởng này nghe hay trên lý thuyết, nhưng hiếm khi hiệu quả trong thực tế."},{"en":"Scientists have developed a new theory to explain the data.","vi":"Các nhà khoa học đã xây dựng một lý thuyết mới để giải thích dữ liệu.","image_url":"https://images.pexels.com/photos/210804/pexels-photo-210804.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=627&w=1200"}]','[{"phrase":"in theory"},{"phrase":"develop a theory"},{"phrase":"economic theory"},{"phrase":"support a theory"}]',NULL,'/ˈθiːəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theor/theory__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(120,'awl-1-02',30,'vary','thay đổi; khác nhau; làm đa dạng','verb','[{"en":"Hotel prices vary greatly depending on the time of year.","vi":"Giá khách sạn thay đổi rất nhiều tùy theo thời điểm trong năm."},{"en":"Opinions on the new policy varied widely among staff.","vi":"Ý kiến của nhân viên về chính sách mới rất khác nhau."},{"en":"Try to vary your diet by eating different kinds of vegetables.","vi":"Hãy cố gắng đa dạng hóa chế độ ăn bằng cách ăn nhiều loại rau khác nhau."}]','[{"phrase":"vary greatly"},{"phrase":"vary widely"},{"phrase":"vary in size"},{"phrase":"vary depending on"}]','vary – varied – varies; tính từ: various, danh từ: variety','/ˈveri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/vary_/vary__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(121,'ngsl-1-03',1,'help','giúp; giúp đỡ','verb','[{"en":"My older brother helped me with my math homework.","vi":"Anh trai tôi đã giúp tôi làm bài tập toán."},{"en":"Neighbors should help each other in difficult times.","vi":"Hàng xóm nên giúp đỡ nhau những lúc khó khăn."},{"en":"A short walk after dinner helps me sleep better.","vi":"Đi bộ một chút sau bữa tối giúp tôi ngủ ngon hơn."}]','[{"phrase":"help each other"},{"phrase":"help with homework"},{"phrase":"help a lot"}]',NULL,'/help/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/help_/help__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(122,'ngsl-1-03',2,'ask','hỏi; yêu cầu; xin','verb','[{"en":"Can I ask a question about tomorrow''s test?","vi":"Tôi có thể hỏi một câu về bài kiểm tra ngày mai không?"},{"en":"The teacher asked us to turn off our phones.","vi":"Cô giáo yêu cầu chúng tôi tắt điện thoại."},{"en":"She asked her boss for a day off next week.","vi":"Cô ấy xin sếp cho nghỉ một ngày vào tuần sau."}]','[{"phrase":"ask a question"},{"phrase":"ask for help"},{"phrase":"ask for advice"}]',NULL,'/æsk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ask/ask__/ask__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(123,'ngsl-1-03',3,'meet','gặp; gặp gỡ; làm quen','verb','[{"en":"Let''s meet for coffee after work tomorrow.","vi":"Ngày mai tan làm chúng ta gặp nhau uống cà phê nhé."},{"en":"I met my wife when we were at university.","vi":"Tôi quen vợ mình khi chúng tôi còn học đại học."},{"en":"It was really nice to meet your parents last night.","vi":"Tối qua được gặp bố mẹ bạn thật là vui."}]','[{"phrase":"meet a friend"},{"phrase":"nice to meet you"},{"phrase":"meet for coffee"}]','meet – met – met','/miːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mee/meet_/meet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(124,'ngsl-1-03',4,'start','bắt đầu; khởi động','verb','[{"en":"The movie starts at eight, so don''t be late.","vi":"Phim bắt đầu lúc tám giờ, nên đừng đến muộn."},{"en":"She started a new job last month.","vi":"Cô ấy bắt đầu công việc mới vào tháng trước."},{"en":"My old car wouldn''t start this morning.","vi":"Sáng nay chiếc xe cũ của tôi không khởi động được."}]','[{"phrase":"start a new job"},{"phrase":"start a business"},{"phrase":"start work"}]',NULL,'/stɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/start/start__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(125,'ngsl-1-03',5,'talk','nói chuyện; trò chuyện; bàn bạc','verb','[{"en":"We talked on the phone for almost an hour.","vi":"Chúng tôi nói chuyện điện thoại gần một tiếng."},{"en":"Can I talk to you about something important?","vi":"Mình nói chuyện với bạn về một việc quan trọng được không?"},{"en":"My parents never talk about money in front of us.","vi":"Bố mẹ tôi không bao giờ bàn chuyện tiền bạc trước mặt chúng tôi."}]','[{"phrase":"talk about"},{"phrase":"talk to"},{"phrase":"talk on the phone"}]',NULL,'/tɔːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/talk_/talk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(126,'ngsl-1-03',6,'something','cái gì đó; điều gì đó; chuyện gì đó','pronoun','[{"en":"I have something important to tell you after class.","vi":"Tôi có chuyện quan trọng muốn nói với bạn sau giờ học."},{"en":"Would you like something to drink while you wait?","vi":"Bạn có muốn uống gì trong lúc chờ không?"},{"en":"There''s something wrong with my laptop again.","vi":"Máy tính xách tay của tôi lại có vấn đề gì đó rồi."}]','[{"phrase":"something else"},{"phrase":"something to drink"},{"phrase":"something wrong"}]',NULL,'/ˈsʌmθɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somet/something__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(127,'ngsl-1-03',7,'put','đặt; để; cho vào','verb','[{"en":"Please put the milk back in the fridge.","vi":"Làm ơn để sữa lại vào tủ lạnh."},{"en":"Did you put sugar in my coffee?","vi":"Bạn có cho đường vào cà phê của tôi không?"},{"en":"He put down his bag and sat on the sofa.","vi":"Anh ấy đặt túi xuống rồi ngồi lên ghế sofa."}]','[{"phrase":"put back"},{"phrase":"put down"},{"phrase":"put away"}]','put – put – put','/pʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/put/put__/put__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(128,'ngsl-1-03',8,'another','một… khác; thêm một','determiner','[{"en":"Could I have another cup of tea, please?","vi":"Cho tôi thêm một tách trà nữa được không?"},{"en":"Do you have this shirt in another color?","vi":"Bạn có chiếc áo này màu khác không?"},{"en":"I''m busy now, so let''s talk about it another time.","vi":"Giờ tôi đang bận, để lúc khác chúng ta nói chuyện nhé."}]','[{"phrase":"another time"},{"phrase":"another day"},{"phrase":"one another"}]',NULL,'/əˈnʌðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ano/anoth/another__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(129,'ngsl-1-03',9,'become','trở thành; trở nên','verb','[{"en":"She wants to become a doctor like her mother.","vi":"Cô ấy muốn trở thành bác sĩ giống mẹ mình."},{"en":"The weather became colder after the sun went down.","vi":"Trời trở nên lạnh hơn sau khi mặt trời lặn."},{"en":"They became good friends during their first year at college.","vi":"Họ trở thành bạn thân trong năm đầu đại học."}]','[{"phrase":"become friends"},{"phrase":"become popular"},{"phrase":"become clear"}]','become – became – become','/bɪˈkʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bec/becom/become__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(130,'ngsl-1-03',10,'interest','sự quan tâm; hứng thú; sở thích','noun','[{"en":"My son has shown a lot of interest in music lately.","vi":"Gần đây con trai tôi tỏ ra rất quan tâm đến âm nhạc."},{"en":"Reading and cooking are my main interests.","vi":"Đọc sách và nấu ăn là những sở thích chính của tôi."},{"en":"She lost interest in the game after a few minutes.","vi":"Cô bé mất hứng thú với trò chơi chỉ sau vài phút."}]','[{"phrase":"interest in"},{"phrase":"show interest"},{"phrase":"lose interest"}]','interest in something','/ˈɪntrəst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interest__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(131,'ngsl-1-03',11,'country','đất nước; quốc gia; vùng quê','noun','[{"en":"Have you ever lived in a foreign country?","vi":"Bạn đã bao giờ sống ở nước ngoài chưa?"},{"en":"Vietnam is a country with beautiful beaches and friendly people.","vi":"Việt Nam là một đất nước có những bãi biển đẹp và người dân thân thiện."},{"en":"My grandparents moved to the country after they retired.","vi":"Ông bà tôi chuyển về vùng quê sau khi nghỉ hưu."}]','[{"phrase":"foreign country"},{"phrase":"all over the country"},{"phrase":"developing country"}]',NULL,'/ˈkʌntri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/country__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(132,'ngsl-1-03',12,'old','già; cũ; (bao nhiêu) tuổi','adjective','[{"en":"My grandfather is old, but he still walks every day.","vi":"Ông tôi đã già nhưng vẫn đi bộ mỗi ngày."},{"en":"I gave my old clothes to my younger cousin.","vi":"Tôi đã cho em họ quần áo cũ của mình."},{"en":"How old was your daughter when she started school?","vi":"Con gái bạn bao nhiêu tuổi khi bắt đầu đi học?"}]','[{"phrase":"old friend"},{"phrase":"years old"},{"phrase":"old clothes"}]',NULL,'/əʊld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/old/old__/old__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(133,'ngsl-1-03',13,'school','trường học; việc học','noun','[{"en":"After school, the children usually play in the park.","vi":"Sau giờ học, bọn trẻ thường chơi ở công viên."},{"en":"Our school has a big library and a swimming pool.","vi":"Trường chúng tôi có một thư viện lớn và một hồ bơi."},{"en":"She left school at sixteen to help her parents.","vi":"Cô ấy nghỉ học năm mười sáu tuổi để phụ giúp bố mẹ."}]','[{"phrase":"after school"},{"phrase":"go to school"},{"phrase":"high school"}]',NULL,'/skuːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schoo/school__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(134,'ngsl-1-03',14,'late','muộn; trễ; cuối (giai đoạn)','adjective','[{"en":"I was late for work because my bus broke down.","vi":"Tôi đi làm muộn vì xe buýt bị hỏng."},{"en":"It''s too late to call her now.","vi":"Giờ đã quá muộn để gọi cho cô ấy."},{"en":"We usually go for a walk in the late afternoon.","vi":"Chúng tôi thường đi dạo vào cuối buổi chiều."}]','[{"phrase":"late for work"},{"phrase":"too late"},{"phrase":"late afternoon"}]',NULL,'/leɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lat/late_/late__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(135,'ngsl-1-03',15,'high','cao','adjective','[{"en":"The wall around the garden is too high to climb.","vi":"Bức tường quanh khu vườn cao quá, không trèo qua được."},{"en":"Prices in the city center are very high.","vi":"Giá cả ở trung tâm thành phố rất cao."},{"en":"She has a high fever, so she''s staying home today.","vi":"Cô bé bị sốt cao nên hôm nay ở nhà."}]','[{"phrase":"high prices"},{"phrase":"high fever"},{"phrase":"high quality"}]','người cao dùng tall, không dùng high','/haɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/high_/high__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(136,'ngsl-1-03',16,'different','khác; khác nhau','adjective','[{"en":"My sister and I look very different.","vi":"Tôi và chị gái trông rất khác nhau."},{"en":"This phone is different from the one I ordered.","vi":"Chiếc điện thoại này khác với cái tôi đã đặt."},{"en":"We tried three different restaurants during our trip.","vi":"Chúng tôi đã thử ba nhà hàng khác nhau trong chuyến đi."}]','[{"phrase":"different from"},{"phrase":"very different"},{"phrase":"completely different"}]','different from','/ˈdɪfrənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/different__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(137,'ngsl-1-03',17,'next','tiếp theo; sau; bên cạnh','adjective','[{"en":"The next train to the airport leaves in ten minutes.","vi":"Chuyến tàu tiếp theo ra sân bay sẽ chạy sau mười phút nữa."},{"en":"We''re going on vacation with my parents next month.","vi":"Tháng sau chúng tôi sẽ đi nghỉ cùng bố mẹ tôi."},{"en":"The people in the next room were very noisy last night.","vi":"Tối qua những người ở phòng bên cạnh rất ồn ào."}]','[{"phrase":"next week"},{"phrase":"next time"},{"phrase":"next month"}]',NULL,'/nekst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nex/next_/next__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(138,'ngsl-1-03',18,'end','phần cuối; kết thúc; đầu (mút)','noun','[{"en":"We''ll pay you at the end of the month.","vi":"Chúng tôi sẽ trả tiền cho bạn vào cuối tháng."},{"en":"I didn''t like the end of the movie.","vi":"Tôi không thích đoạn kết của bộ phim."},{"en":"Can you hold the other end of the rope?","vi":"Bạn giữ đầu kia của sợi dây giúp tôi được không?"}]','[{"phrase":"at the end of"},{"phrase":"in the end"},{"phrase":"come to an end"}]',NULL,'/end/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/end/end__/end__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(139,'ngsl-1-03',19,'live','sống; ở','verb','[{"en":"My grandmother lives alone in a small village.","vi":"Bà tôi sống một mình ở một ngôi làng nhỏ."},{"en":"Where did you live before you moved here?","vi":"Trước khi chuyển đến đây bạn sống ở đâu?"},{"en":"Most pet cats live for about fifteen years.","vi":"Phần lớn mèo nuôi sống được khoảng mười lăm năm."}]','[{"phrase":"live alone"},{"phrase":"live with"},{"phrase":"live together"}]',NULL,'/lɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/liv/live_/live__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(140,'ngsl-1-03',20,'while','trong khi; trong lúc; còn','conjunction','[{"en":"Someone called while you were in the shower.","vi":"Có người gọi điện trong lúc bạn đang tắm."},{"en":"Please don''t use your phone while driving.","vi":"Làm ơn đừng dùng điện thoại khi đang lái xe."},{"en":"My brother loves sports, while I prefer reading.","vi":"Anh trai tôi mê thể thao, còn tôi thích đọc sách hơn."}]','[{"phrase":"while driving"},{"phrase":"for a while"},{"phrase":"a while ago"}]','a while (danh từ) = một lúc, một thời gian','/waɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/while/while__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(141,'ngsl-1-03',21,'world','thế giới','noun','[{"en":"She dreams of traveling around the world one day.","vi":"Cô ấy mơ một ngày nào đó được đi du lịch vòng quanh thế giới."},{"en":"This is the best pizza in the world!","vi":"Đây là chiếc pizza ngon nhất thế giới!"},{"en":"English is spoken in many parts of the world.","vi":"Tiếng Anh được nói ở nhiều nơi trên thế giới."}]','[{"phrase":"around the world"},{"phrase":"in the world"},{"phrase":"all over the world"}]',NULL,'/wɜːrld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/world/world__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(142,'ngsl-1-03',22,'week','tuần','noun','[{"en":"I go to the gym three times a week.","vi":"Tôi đi tập gym ba lần một tuần."},{"en":"We''re moving to a new apartment next week.","vi":"Tuần sau chúng tôi chuyển đến căn hộ mới."},{"en":"She spent a week at the beach with her friends.","vi":"Cô ấy đã dành một tuần ở biển cùng bạn bè."}]','[{"phrase":"next week"},{"phrase":"last week"},{"phrase":"every week"}]',NULL,'/wiːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wee/week_/week__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(143,'ngsl-1-03',23,'play','chơi; thi đấu; đóng vai','verb','[{"en":"The kids are playing games in the garden.","vi":"Bọn trẻ đang chơi trò chơi trong vườn."},{"en":"We''re playing against the best team in the city tomorrow.","vi":"Ngày mai chúng tôi thi đấu với đội mạnh nhất thành phố."},{"en":"He played a doctor in his first movie.","vi":"Anh ấy đóng vai bác sĩ trong bộ phim đầu tiên của mình."}]','[{"phrase":"play games"},{"phrase":"play against"},{"phrase":"play a role"},{"phrase":"play the guitar"}]',NULL,'/pleɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/play_/play__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(144,'ngsl-1-03',24,'home','nhà; tổ ấm; quê nhà','noun','[{"en":"After a long day, it''s nice to be at home.","vi":"Sau một ngày dài, được ở nhà thật dễ chịu."},{"en":"They''re building a new home near the lake.","vi":"Họ đang xây một ngôi nhà mới gần hồ."},{"en":"This city has been my home for ten years.","vi":"Thành phố này đã là nhà của tôi suốt mười năm nay."}]','[{"phrase":"at home"},{"phrase":"go home"},{"phrase":"leave home"},{"phrase":"feel at home"}]','go home (không nói "go to home")','/həʊm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hom/home_/home__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(145,'ngsl-1-03',25,'never','không bao giờ; chưa bao giờ','adverb','[{"en":"I''ve never been on a plane before.","vi":"Tôi chưa bao giờ đi máy bay."},{"en":"She never drinks coffee in the afternoon because it keeps her awake.","vi":"Cô ấy không bao giờ uống cà phê vào buổi chiều vì sẽ bị mất ngủ."},{"en":"I''ll never forget the day my son was born.","vi":"Tôi sẽ không bao giờ quên ngày con trai tôi chào đời."}]','[{"phrase":"never forget"},{"phrase":"never mind"},{"phrase":"almost never"}]',NULL,'/ˈnevər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nev/never/never__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(146,'ngsl-1-03',26,'include','bao gồm; tính cả; đưa vào','verb','[{"en":"Does the room price include breakfast and free parking?","vi":"Giá phòng có bao gồm bữa sáng và chỗ đậu xe miễn phí không?"},{"en":"There were twelve people at dinner, including the kids.","vi":"Có mười hai người ăn tối, tính cả bọn trẻ."},{"en":"Please include your phone number in the email.","vi":"Vui lòng ghi kèm số điện thoại của bạn trong email."}]','[{"phrase":"price includes"},{"phrase":"include information"},{"phrase":"including tax"}]',NULL,'/ɪnˈkluːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/inclu/include__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(147,'ngsl-1-03',27,'course','khóa học; món ăn','noun','[{"en":"I''m taking an online course in cooking this summer.","vi":"Mùa hè này tôi đang học một khóa nấu ăn trực tuyến."},{"en":"For the main course, I''ll have the chicken.","vi":"Món chính thì tôi sẽ gọi món gà."},{"en":"She passed the course with very high marks.","vi":"Cô ấy đã hoàn thành khóa học với điểm rất cao."}]','[{"phrase":"take a course"},{"phrase":"online course"},{"phrase":"main course"}]','of course = tất nhiên','/kɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/cours/course__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(148,'ngsl-1-03',28,'house','ngôi nhà; nhà','noun','[{"en":"They bought a small house with a garden.","vi":"Họ đã mua một ngôi nhà nhỏ có vườn."},{"en":"Let''s have the party at my house on Saturday.","vi":"Thứ Bảy mình tổ chức bữa tiệc ở nhà mình nhé."},{"en":"We need to clean the whole house before the guests arrive.","vi":"Chúng tôi cần dọn dẹp cả nhà trước khi khách đến."}]','[{"phrase":"buy a house"},{"phrase":"clean the house"},{"phrase":"at my house"}]','house (ngôi nhà) ≠ home (nơi mình sống, tổ ấm)','/haʊs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hou/house/house__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(149,'ngsl-1-03',29,'report','bản báo cáo; bản tin','noun','[{"en":"I have to finish this report before Friday.","vi":"Tôi phải hoàn thành bản báo cáo này trước thứ Sáu."},{"en":"According to the weather report, it will rain tomorrow.","vi":"Theo bản tin thời tiết, ngày mai trời sẽ mưa."},{"en":"The manager asked me to write a short report on the meeting.","vi":"Quản lý yêu cầu tôi viết một bản báo cáo ngắn về cuộc họp."}]','[{"phrase":"write a report"},{"phrase":"weather report"},{"phrase":"news report"},{"phrase":"annual report"}]',NULL,'/rɪˈpɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repor/report__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(150,'ngsl-1-03',30,'group','nhóm','noun','[{"en":"We studied in small groups for the exam.","vi":"Chúng tôi học theo nhóm nhỏ để ôn thi."},{"en":"A group of tourists was taking photos outside the museum.","vi":"Một nhóm khách du lịch đang chụp ảnh bên ngoài bảo tàng."},{"en":"Children in this age group need about ten hours of sleep.","vi":"Trẻ em ở nhóm tuổi này cần ngủ khoảng mười tiếng."}]','[{"phrase":"a group of"},{"phrase":"small group"},{"phrase":"age group"}]',NULL,'/ɡruːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/group/group__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(151,'ngsl-1-04',1,'case','trường hợp; vụ án; hộp, vỏ đựng','noun','[{"en":"In that case, we should leave a little earlier.","vi":"Trong trường hợp đó, chúng ta nên đi sớm hơn một chút."},{"en":"The police are still working on the case.","vi":"Cảnh sát vẫn đang điều tra vụ án."},{"en":"I bought a new case for my phone yesterday.","vi":"Hôm qua tôi đã mua một cái vỏ mới cho điện thoại."}]','[{"phrase":"in that case"},{"phrase":"in any case"},{"phrase":"just in case"},{"phrase":"phone case"}]',NULL,'/keɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/case_/case__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(152,'ngsl-1-04',2,'woman','phụ nữ; người đàn bà','noun','[{"en":"The woman at the front desk gave us our room keys.","vi":"Người phụ nữ ở quầy lễ tân đưa chìa khóa phòng cho chúng tôi."},{"en":"Many women in my office work from home on Fridays.","vi":"Nhiều phụ nữ trong văn phòng tôi làm việc ở nhà vào thứ Sáu."},{"en":"She grew up to be a strong and kind woman.","vi":"Cô ấy lớn lên thành một người phụ nữ mạnh mẽ và tốt bụng."}]','[{"phrase":"young woman"},{"phrase":"old woman"},{"phrase":"married woman"}]','số nhiều: women','/ˈwʊmən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wom/woman/woman__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(153,'ngsl-1-04',3,'around','xung quanh; khắp; khoảng','preposition','[{"en":"We sat around the table and talked all evening.","vi":"Chúng tôi ngồi quanh bàn và trò chuyện suốt buổi tối."},{"en":"She has traveled around the world twice.","vi":"Cô ấy đã đi vòng quanh thế giới hai lần."},{"en":"I''ll meet you at around seven o''clock.","vi":"Tôi sẽ gặp bạn vào khoảng bảy giờ."}]','[{"phrase":"around the world"},{"phrase":"around the corner"},{"phrase":"look around"},{"phrase":"turn around"}]',NULL,'/əˈraʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aro/aroun/around__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(154,'ngsl-1-04',4,'book','sách; cuốn sách','noun','[{"en":"I''m reading a really good book about the ocean.","vi":"Tôi đang đọc một cuốn sách rất hay về đại dương."},{"en":"My son borrowed three books from the school library.","vi":"Con trai tôi mượn ba cuốn sách từ thư viện trường."},{"en":"She wrote her first book when she was twenty-five.","vi":"Cô ấy viết cuốn sách đầu tiên khi hai mươi lăm tuổi."}]','[{"phrase":"read a book"},{"phrase":"write a book"},{"phrase":"borrow a book"}]','(v) book: đặt chỗ, đặt vé','/bʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/book_/book__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(155,'ngsl-1-04',5,'family','gia đình; họ hàng','noun','[{"en":"My family usually has dinner together on Sundays.","vi":"Gia đình tôi thường ăn tối cùng nhau vào Chủ nhật."},{"en":"He moved to the city to support his family.","vi":"Anh ấy chuyển lên thành phố để nuôi gia đình."},{"en":"We have family in both Canada and Australia.","vi":"Chúng tôi có họ hàng ở cả Canada và Úc."}]','[{"phrase":"family member"},{"phrase":"support a family"},{"phrase":"start a family"}]',NULL,'/ˈfæməli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fam/famil/family__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(156,'ngsl-1-04',6,'seem','có vẻ; dường như','verb','[{"en":"You seem a little tired after your long trip.","vi":"Bạn có vẻ hơi mệt sau chuyến đi dài."},{"en":"It seems that nobody knows the answer to this question.","vi":"Dường như không ai biết câu trả lời cho câu hỏi này."},{"en":"The new manager seems very friendly and easy to talk to.","vi":"Người quản lý mới có vẻ rất thân thiện và dễ nói chuyện."}]','[{"phrase":"seem to be"},{"phrase":"it seems that"},{"phrase":"seem strange"}]',NULL,'/siːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seem_/seem__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(157,'ngsl-1-04',7,'let','để; cho phép','verb','[{"en":"My parents let me stay up late on weekends.","vi":"Bố mẹ cho phép tôi thức khuya vào cuối tuần."},{"en":"Let me help you carry those heavy bags.","vi":"Để tôi giúp bạn mang mấy cái túi nặng đó."},{"en":"Let''s go for a walk after lunch.","vi":"Chúng ta đi dạo sau bữa trưa nhé."}]','[{"phrase":"let me know"},{"phrase":"let go"},{"phrase":"let someone in"}]','let – let – let; let + người + V nguyên mẫu','/let/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/let/let__/let__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(158,'ngsl-1-04',8,'again','lại; lần nữa','adverb','[{"en":"Sorry, could you say that again a bit more slowly?","vi":"Xin lỗi, bạn có thể nói lại chậm hơn một chút được không?"},{"en":"I hope we can meet again next year.","vi":"Tôi hy vọng năm sau chúng ta có thể gặp lại nhau."},{"en":"He failed his driving test, so he''s taking it again next month.","vi":"Anh ấy trượt bài thi lái xe nên tháng sau sẽ thi lại lần nữa."}]','[{"phrase":"once again"},{"phrase":"try again"},{"phrase":"never again"}]',NULL,'/əˈɡen/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aga/again/again__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(159,'ngsl-1-04',9,'kind','loại; kiểu','noun','[{"en":"What kind of music do you like?","vi":"Bạn thích thể loại nhạc nào?"},{"en":"This kind of tree grows well in hot weather.","vi":"Loại cây này phát triển tốt khi thời tiết nóng."},{"en":"The market sells all kinds of fresh fruit.","vi":"Khu chợ bán đủ loại trái cây tươi."}]','[{"phrase":"all kinds of"},{"phrase":"what kind of"},{"phrase":"this kind of"}]','(adj) kind: tốt bụng, tử tế','/kaɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kin/kind_/kind__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(160,'ngsl-1-04',10,'keep','giữ; tiếp tục','verb','[{"en":"You can keep the book because I don''t need it anymore.","vi":"Bạn cứ giữ cuốn sách vì tôi không cần nó nữa."},{"en":"Keep walking until you see the post office.","vi":"Cứ đi tiếp cho đến khi bạn thấy bưu điện."},{"en":"Wear a hat to keep warm in the winter.","vi":"Hãy đội mũ để giữ ấm vào mùa đông."}]','[{"phrase":"keep a secret"},{"phrase":"keep warm"},{"phrase":"keep going"},{"phrase":"keep in touch"}]','keep – kept – kept; keep + V-ing: cứ tiếp tục làm gì','/kiːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kee/keep_/keep__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(161,'ngsl-1-04',11,'hear','nghe (thấy); nghe nói','verb','[{"en":"Can you hear me at the back of the room?","vi":"Bạn ở cuối phòng có nghe thấy tôi không?"},{"en":"I heard a strange noise outside last night.","vi":"Tối qua tôi nghe thấy một tiếng động lạ bên ngoài."},{"en":"Have you heard about the new café near the station?","vi":"Bạn đã nghe nói về quán cà phê mới gần nhà ga chưa?"}]','[{"phrase":"hear a noise"},{"phrase":"hear about"},{"phrase":"hear from"},{"phrase":"hear the news"}]','hear – heard – heard','/hɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/hear_/hear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(162,'ngsl-1-04',12,'system','hệ thống; chế độ','noun','[{"en":"Our office is installing a new computer system next week.","vi":"Tuần tới văn phòng chúng tôi sẽ lắp đặt hệ thống máy tính mới."},{"en":"The city has a cheap and reliable public transportation system.","vi":"Thành phố có hệ thống giao thông công cộng rẻ và đáng tin cậy."},{"en":"The education system in this country is changing quickly.","vi":"Hệ thống giáo dục ở nước này đang thay đổi nhanh chóng."}]','[{"phrase":"computer system"},{"phrase":"education system"},{"phrase":"operating system"}]',NULL,'/ˈsɪstəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sys/syste/system__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(163,'ngsl-1-04',13,'question','câu hỏi; vấn đề','noun','[{"en":"Can I ask you a question about the homework?","vi":"Cho tôi hỏi bạn một câu về bài tập về nhà được không?"},{"en":"She answered every question on the test correctly.","vi":"Cô ấy trả lời đúng mọi câu hỏi trong bài kiểm tra."},{"en":"The real question is whether we have enough money.","vi":"Vấn đề thật sự là liệu chúng ta có đủ tiền hay không."}]','[{"phrase":"ask a question"},{"phrase":"answer a question"},{"phrase":"good question"}]',NULL,'/ˈkwestʃən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/que/quest/question__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(164,'ngsl-1-04',14,'during','trong (suốt); trong lúc','preposition','[{"en":"Please turn off your phone during the movie.","vi":"Vui lòng tắt điện thoại trong suốt buổi chiếu phim."},{"en":"I worked at a café during summer vacation.","vi":"Tôi làm việc ở một quán cà phê trong kỳ nghỉ hè."},{"en":"Did anyone call during my meeting this afternoon?","vi":"Có ai gọi trong lúc tôi họp chiều nay không?"}]','[{"phrase":"during the day"},{"phrase":"during the night"},{"phrase":"during the week"}]','during + danh từ ≠ while + mệnh đề','/ˈdʊrɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dur/durin/during__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(165,'ngsl-1-04',15,'always','luôn luôn; lúc nào cũng','adverb','[{"en":"She always drinks a cup of coffee before work.","vi":"Cô ấy luôn uống một tách cà phê trước khi đi làm."},{"en":"My grandmother is always happy to see us.","vi":"Bà tôi lúc nào cũng vui khi gặp chúng tôi."},{"en":"I have always wanted to learn how to play the piano.","vi":"Tôi luôn muốn học chơi đàn piano."}]','[{"phrase":"almost always"},{"phrase":"not always"},{"phrase":"always remember"}]',NULL,'/ˈɔːlweɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alw/alway/always__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(166,'ngsl-1-04',16,'big','to, lớn; quan trọng','adjective','[{"en":"They live in a big house near the river.","vi":"Họ sống trong một ngôi nhà lớn gần con sông."},{"en":"These shoes are a little too big for my son.","vi":"Đôi giày này hơi to so với con trai tôi."},{"en":"Tomorrow is a big day for our whole team.","vi":"Ngày mai là một ngày quan trọng với cả đội chúng tôi."}]','[{"phrase":"big city"},{"phrase":"big problem"},{"phrase":"big day"},{"phrase":"big deal"}]',NULL,'/bɪɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/big/big__/big__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(167,'ngsl-1-04',17,'set','đặt; đặt ra; (mặt trời) lặn','verb','[{"en":"She set the plates on the table before dinner.","vi":"Cô ấy đặt đĩa lên bàn trước bữa tối."},{"en":"Our team has set a clear goal for next year.","vi":"Đội chúng tôi đã đặt ra một mục tiêu rõ ràng cho năm tới."},{"en":"We sat on the beach and watched the sun set.","vi":"Chúng tôi ngồi trên bãi biển và ngắm mặt trời lặn."}]','[{"phrase":"set a goal"},{"phrase":"set an alarm"},{"phrase":"set the table"},{"phrase":"set a record"}]','set – set – set','/set/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/set/set__/set__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(168,'ngsl-1-04',18,'small','nhỏ, bé','adjective','[{"en":"We rented a small apartment close to the city center.","vi":"Chúng tôi thuê một căn hộ nhỏ gần trung tâm thành phố."},{"en":"Could I have a small coffee with milk, please?","vi":"Cho tôi một ly cà phê sữa cỡ nhỏ nhé."},{"en":"She grew up in a small town in the mountains.","vi":"Cô ấy lớn lên ở một thị trấn nhỏ trên núi."}]','[{"phrase":"small town"},{"phrase":"small business"},{"phrase":"small amount"},{"phrase":"small group"}]',NULL,'/smɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sma/small/small__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(169,'ngsl-1-04',19,'study','học; nghiên cứu','verb','[{"en":"My older sister is studying to become a doctor.","vi":"Chị gái tôi đang học để trở thành bác sĩ."},{"en":"I need to study for my English exam tonight.","vi":"Tối nay tôi cần học để thi môn tiếng Anh."},{"en":"Scientists have studied these birds for many years.","vi":"Các nhà khoa học đã nghiên cứu những loài chim này trong nhiều năm."}]','[{"phrase":"study hard"},{"phrase":"study for an exam"},{"phrase":"study abroad"}]',NULL,'/ˈstʌdi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/study/study__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(170,'ngsl-1-04',20,'follow','đi theo; làm theo; theo dõi','verb','[{"en":"Follow me, and I''ll show you to your seat.","vi":"Đi theo tôi, tôi sẽ dẫn bạn đến chỗ ngồi."},{"en":"Please follow the instructions on the box carefully.","vi":"Vui lòng làm theo hướng dẫn trên hộp một cách cẩn thận."},{"en":"Do you follow any cooking channels on social media?","vi":"Bạn có theo dõi kênh nấu ăn nào trên mạng xã hội không?"}]','[{"phrase":"follow instructions"},{"phrase":"follow the rules"},{"phrase":"follow advice"}]',NULL,'/ˈfɑːləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fol/follo/follow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(171,'ngsl-1-04',21,'begin','bắt đầu','verb','[{"en":"The meeting will begin at nine o''clock sharp.","vi":"Cuộc họp sẽ bắt đầu đúng chín giờ."},{"en":"She began learning English when she was six.","vi":"Cô ấy bắt đầu học tiếng Anh khi lên sáu tuổi."},{"en":"It began to rain just as we left the house.","vi":"Trời bắt đầu mưa đúng lúc chúng tôi ra khỏi nhà."}]','[{"phrase":"begin with"},{"phrase":"begin work"},{"phrase":"begin again"}]','begin – began – begun','/bɪˈɡɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beg/begin/begin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(172,'ngsl-1-04',22,'important','quan trọng','adjective','[{"en":"I have an important meeting with my boss tomorrow.","vi":"Ngày mai tôi có một cuộc họp quan trọng với sếp."},{"en":"It''s important to drink enough water every day.","vi":"Uống đủ nước mỗi ngày là điều quan trọng."},{"en":"Good sleep is just as important as healthy food.","vi":"Giấc ngủ ngon cũng quan trọng như thức ăn lành mạnh."}]','[{"phrase":"very important"},{"phrase":"important decision"},{"phrase":"important role"}]',NULL,'/ɪmˈpɔːrtnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impor/important__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(173,'ngsl-1-04',23,'since','từ, kể từ (khi); vì','conjunction','[{"en":"We have lived in this house since 2015.","vi":"Chúng tôi đã sống trong ngôi nhà này từ năm 2015."},{"en":"I haven''t seen him since we finished high school.","vi":"Tôi chưa gặp lại anh ấy kể từ khi chúng tôi học xong cấp ba."},{"en":"Since it''s raining, let''s stay home and watch a movie.","vi":"Vì trời đang mưa nên chúng ta ở nhà xem phim đi."}]','[{"phrase":"ever since"},{"phrase":"since then"}]','since + mốc thời gian ≠ for + khoảng thời gian','/sɪns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/since/since__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(174,'ngsl-1-04',24,'run','chạy; điều hành, quản lý','verb','[{"en":"I run in the park every morning before work.","vi":"Tôi chạy bộ trong công viên mỗi sáng trước khi đi làm."},{"en":"We had to run to catch the last bus.","vi":"Chúng tôi phải chạy để kịp chuyến xe buýt cuối cùng."},{"en":"Her parents run a small restaurant in the city center.","vi":"Bố mẹ cô ấy quản lý một nhà hàng nhỏ ở trung tâm thành phố."}]','[{"phrase":"run a business"},{"phrase":"run away"},{"phrase":"run out of"}]','run – ran – run','/rʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/run/run__/run__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(175,'ngsl-1-04',25,'under','dưới; dưới (mức), ít hơn','preposition','[{"en":"The cat is sleeping under the kitchen table.","vi":"Con mèo đang ngủ dưới gầm bàn bếp."},{"en":"Children under five can travel on the train for free.","vi":"Trẻ em dưới năm tuổi được đi tàu miễn phí."},{"en":"I found my keys under a pile of papers.","vi":"Tôi tìm thấy chìa khóa dưới một đống giấy."}]','[{"phrase":"under the table"},{"phrase":"under pressure"},{"phrase":"under control"}]',NULL,'/ˈʌndər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/under__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(176,'ngsl-1-04',26,'turn','rẽ; quay (lại); chuyển sang, trở nên','verb','[{"en":"Turn left at the next traffic light.","vi":"Rẽ trái ở đèn giao thông tiếp theo."},{"en":"She turned and waved goodbye to us.","vi":"Cô ấy quay lại và vẫy tay chào tạm biệt chúng tôi."},{"en":"The leaves turn red and yellow in the fall.","vi":"Lá cây chuyển sang màu đỏ và vàng vào mùa thu."}]','[{"phrase":"turn left"},{"phrase":"turn around"},{"phrase":"turn on"},{"phrase":"turn off"}]',NULL,'/tɜːrn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tur/turn_/turn__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(177,'ngsl-1-04',27,'few','một vài; ít','determiner','[{"en":"I''ll be back in a few minutes.","vi":"Tôi sẽ quay lại trong vài phút nữa."},{"en":"We spent a few days at the beach last summer.","vi":"Mùa hè năm ngoái chúng tôi đã ở biển vài ngày."},{"en":"Very few people came to the meeting because of the storm.","vi":"Rất ít người đến buổi họp vì cơn bão."}]','[{"phrase":"a few"},{"phrase":"very few"},{"phrase":"quite a few"}]','a few: một vài ≠ few: rất ít','/fjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/few/few__/few__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(178,'ngsl-1-04',28,'bring','mang (đến), đem theo; dẫn theo','verb','[{"en":"Don''t forget to bring your passport to the airport.","vi":"Đừng quên mang theo hộ chiếu ra sân bay."},{"en":"Can I bring a friend to your party?","vi":"Tôi có thể dẫn một người bạn đến bữa tiệc của bạn không?"},{"en":"She brought us some snacks back from her trip.","vi":"Cô ấy mang về cho chúng tôi ít đồ ăn vặt từ chuyến đi."}]','[{"phrase":"bring back"},{"phrase":"bring a friend"},{"phrase":"bring together"}]','bring – brought – brought','/brɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/bring/bring__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(179,'ngsl-1-04',29,'early','sớm; đầu (giai đoạn)','adverb','[{"en":"I usually get up early on weekdays.","vi":"Tôi thường dậy sớm vào các ngày trong tuần."},{"en":"We arrived at the airport two hours early.","vi":"Chúng tôi đến sân bay sớm hai tiếng."},{"en":"This house was built in the early 1900s.","vi":"Ngôi nhà này được xây vào đầu những năm 1900."}]','[{"phrase":"get up early"},{"phrase":"early morning"},{"phrase":"too early"}]',NULL,'/ˈɜːrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/early/early__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(180,'ngsl-1-04',30,'hand','tay, bàn tay; sự giúp đỡ','noun','[{"en":"Please wash your hands before you sit down to eat.","vi":"Hãy rửa tay trước khi ngồi vào ăn."},{"en":"She was holding a cup of tea in her hand.","vi":"Cô ấy đang cầm một tách trà trong tay."},{"en":"Could you give me a hand with these boxes?","vi":"Bạn có thể giúp tôi một tay với mấy cái thùng này không?"}]','[{"phrase":"give someone a hand"},{"phrase":"shake hands"},{"phrase":"wash your hands"},{"phrase":"hold hands"}]',NULL,'/hænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/han/hand_/hand__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(181,'ngsl-1-05',1,'state','tình trạng; bang; nhà nước','noun','[{"en":"The old house was in a terrible state when we bought it.","vi":"Căn nhà cũ ở trong tình trạng tồi tệ khi chúng tôi mua nó."},{"en":"She moved to another state to start a new job.","vi":"Cô ấy chuyển đến một bang khác để bắt đầu công việc mới."},{"en":"Most hospitals here are run by the state.","vi":"Hầu hết bệnh viện ở đây do nhà nước điều hành."}]','[{"phrase":"in a terrible state"},{"phrase":"state of mind"},{"phrase":"state school"}]',NULL,'/steɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/state/state__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(182,'ngsl-1-05',2,'move','di chuyển; chuyển nhà','verb','[{"en":"Could you move your bag? I want to sit down.","vi":"Bạn có thể dời cái túi đi được không? Tôi muốn ngồi xuống."},{"en":"We moved to a bigger apartment last year.","vi":"Năm ngoái chúng tôi đã chuyển đến một căn hộ rộng hơn."},{"en":"The table is too heavy for one person to move.","vi":"Cái bàn quá nặng, một người không thể di chuyển được."}]','[{"phrase":"move to"},{"phrase":"move house"},{"phrase":"move in"}]',NULL,'/muːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mov/move_/move__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(183,'ngsl-1-05',3,'money','tiền','noun','[{"en":"I''m trying to save money for a new laptop.","vi":"Tôi đang cố gắng tiết kiệm tiền để mua máy tính xách tay mới."},{"en":"How much money did you spend on the trip?","vi":"Bạn đã tiêu bao nhiêu tiền cho chuyến đi?"},{"en":"He doesn''t earn much money, but he loves his job.","vi":"Anh ấy không kiếm được nhiều tiền nhưng rất yêu công việc của mình."}]','[{"phrase":"save money"},{"phrase":"spend money"},{"phrase":"earn money"},{"phrase":"make money"}]','không đếm được','/ˈmʌni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/money/money__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(184,'ngsl-1-05',4,'fact','sự thật; thực tế','noun','[{"en":"It''s a fact that exercise is good for your health.","vi":"Tập thể dục tốt cho sức khỏe là một sự thật."},{"en":"In fact, I''ve never been on a plane before.","vi":"Thực ra, tôi chưa bao giờ đi máy bay."},{"en":"I like the fact that my office is close to home.","vi":"Tôi thích việc văn phòng của mình ở gần nhà."}]','[{"phrase":"in fact"},{"phrase":"the fact that"},{"phrase":"an interesting fact"}]',NULL,'/fækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/fact_/fact__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(185,'ngsl-1-05',5,'however','tuy nhiên; dù thế nào','adverb','[{"en":"The hotel was expensive; however, the rooms were very clean.","vi":"Khách sạn khá đắt; tuy nhiên, phòng rất sạch sẽ."},{"en":"The food, however, was not as good as we expected.","vi":"Tuy nhiên, đồ ăn không ngon như chúng tôi mong đợi."},{"en":"However hard I try, I can''t wake up early.","vi":"Dù cố gắng thế nào, tôi cũng không thể dậy sớm."}]','[{"phrase":"however hard"},{"phrase":"however much"},{"phrase":"however long"}]',NULL,'/haʊˈevər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/how/howev/however__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(186,'ngsl-1-05',6,'area','khu vực; lĩnh vực','noun','[{"en":"There are a lot of good restaurants in this area.","vi":"Có rất nhiều nhà hàng ngon ở khu vực này."},{"en":"They live in a quiet area outside the city.","vi":"Họ sống ở một khu vực yên tĩnh ngoài thành phố."},{"en":"Customer service is an area where we need to improve.","vi":"Dịch vụ khách hàng là lĩnh vực mà chúng tôi cần cải thiện."}]','[{"phrase":"in the area"},{"phrase":"local area"},{"phrase":"quiet area"}]',NULL,'/ˈeriə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/are/area_/area__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(187,'ngsl-1-05',7,'provide','cung cấp; chu cấp','verb','[{"en":"The hotel provides free breakfast for all guests.","vi":"Khách sạn cung cấp bữa sáng miễn phí cho tất cả khách."},{"en":"Can you provide more information about the job?","vi":"Bạn có thể cung cấp thêm thông tin về công việc không?"},{"en":"Parents provide their children with food, clothes and love.","vi":"Cha mẹ chu cấp cho con cái thức ăn, quần áo và tình yêu thương."}]','[{"phrase":"provide information"},{"phrase":"provide a service"},{"phrase":"provide somebody with something"}]','provide sb with sth = provide sth for sb','/prəˈvaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/provi/provide__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(188,'ngsl-1-05',8,'name','tên','noun','[{"en":"What''s the name of that song you were singing?","vi":"Bài hát bạn vừa hát tên là gì vậy?"},{"en":"Please write your full name at the top of the page.","vi":"Vui lòng viết họ tên đầy đủ ở đầu trang."},{"en":"We haven''t chosen a name for the baby yet.","vi":"Chúng tôi vẫn chưa chọn được tên cho em bé."}]','[{"phrase":"full name"},{"phrase":"first name"},{"phrase":"last name"},{"phrase":"choose a name"}]',NULL,'/neɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nam/name_/name__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(189,'ngsl-1-05',9,'read','đọc','verb','[{"en":"I usually read a book before I go to sleep.","vi":"Tôi thường đọc sách trước khi đi ngủ."},{"en":"Have you read the email from your manager?","vi":"Bạn đã đọc email của quản lý chưa?"},{"en":"My son learned to read when he was five.","vi":"Con trai tôi biết đọc khi lên năm tuổi."}]','[{"phrase":"read a book"},{"phrase":"read the news"},{"phrase":"read aloud"},{"phrase":"read carefully"}]','read – read – read (quá khứ đọc là /red/)','/riːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/read_/read__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(190,'ngsl-1-05',10,'friend','bạn; bạn bè','noun','[{"en":"I''m meeting a friend for coffee this afternoon.","vi":"Chiều nay tôi đi uống cà phê với một người bạn."},{"en":"She made a lot of new friends at university.","vi":"Cô ấy đã kết được nhiều bạn mới ở trường đại học."},{"en":"My best friend and I have known each other for years.","vi":"Tôi và bạn thân đã quen nhau nhiều năm rồi."}]','[{"phrase":"best friend"},{"phrase":"make friends"},{"phrase":"close friend"},{"phrase":"old friend"}]',NULL,'/frend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frien/friend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(191,'ngsl-1-05',11,'month','tháng','noun','[{"en":"We''re going on vacation to the beach next month.","vi":"Tháng sau chúng tôi sẽ đi nghỉ ở biển."},{"en":"I pay my phone bill at the end of every month.","vi":"Tôi trả tiền điện thoại vào cuối mỗi tháng."},{"en":"She has been learning English for six months.","vi":"Cô ấy đã học tiếng Anh được sáu tháng."}]','[{"phrase":"next month"},{"phrase":"last month"},{"phrase":"every month"},{"phrase":"the end of the month"}]',NULL,'/mʌnθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/month/month__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(192,'ngsl-1-05',12,'large','lớn; rộng','adjective','[{"en":"They live in a large house near the park.","vi":"Họ sống trong một ngôi nhà lớn gần công viên."},{"en":"Would you like a small or large coffee?","vi":"Bạn muốn cà phê cỡ nhỏ hay cỡ lớn?"},{"en":"A large number of students took the exam this year.","vi":"Năm nay có một số lượng lớn học sinh tham gia kỳ thi."}]','[{"phrase":"a large number of"},{"phrase":"a large amount of"},{"phrase":"large family"}]',NULL,'/lɑːrdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lar/large/large__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(193,'ngsl-1-05',13,'business','kinh doanh; doanh nghiệp','noun','[{"en":"My parents run a small business selling flowers.","vi":"Bố mẹ tôi có một doanh nghiệp nhỏ chuyên bán hoa."},{"en":"He often travels to other countries on business.","vi":"Anh ấy thường đi công tác nước ngoài."},{"en":"She wants to study business at university.","vi":"Cô ấy muốn học ngành kinh doanh ở đại học."}]','[{"phrase":"run a business"},{"phrase":"small business"},{"phrase":"on business"},{"phrase":"business trip"}]',NULL,'/ˈbɪznəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bus/busin/business__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(194,'ngsl-1-05',14,'without','không có; mà không','preposition','[{"en":"I never drink coffee without milk and sugar.","vi":"Tôi không bao giờ uống cà phê mà không cho sữa và đường."},{"en":"She left the room without saying a word.","vi":"Cô ấy rời khỏi phòng mà không nói một lời."},{"en":"We couldn''t have finished the project without your help.","vi":"Nếu không có sự giúp đỡ của bạn, chúng tôi đã không thể hoàn thành dự án."}]','[{"phrase":"without saying a word"},{"phrase":"without a doubt"},{"phrase":"without warning"}]',NULL,'/wɪˈðaʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/witho/without__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(195,'ngsl-1-05',15,'information','thông tin','noun','[{"en":"You can find more information on our website.","vi":"Bạn có thể tìm thêm thông tin trên trang web của chúng tôi."},{"en":"Thanks for the useful information about the bus schedule.","vi":"Cảm ơn bạn vì thông tin hữu ích về lịch xe buýt."},{"en":"Please don''t share your personal information with strangers online.","vi":"Vui lòng không chia sẻ thông tin cá nhân với người lạ trên mạng."}]','[{"phrase":"more information"},{"phrase":"personal information"},{"phrase":"useful information"},{"phrase":"information about"}]','không đếm được','/ˌɪnfərˈmeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infor/information__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(196,'ngsl-1-05',16,'open','mở; mở cửa','verb','[{"en":"Could you open the window? It''s hot in here.","vi":"Bạn mở cửa sổ giúp tôi được không? Trong này nóng quá."},{"en":"The new library will open to the public next Monday.","vi":"Thư viện mới sẽ mở cửa đón mọi người vào thứ Hai tới."},{"en":"What time does the bank open on Saturdays?","vi":"Ngân hàng mở cửa lúc mấy giờ vào thứ Bảy?"}]','[{"phrase":"open the window"},{"phrase":"open the door"},{"phrase":"open an account"}]',NULL,'/ˈəʊpən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/open_/open__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(197,'ngsl-1-05',17,'order','thứ tự; đơn hàng; mệnh lệnh','noun','[{"en":"Put the photos in order from oldest to newest.","vi":"Hãy sắp xếp ảnh theo thứ tự từ cũ nhất đến mới nhất."},{"en":"Your order will arrive in three to five days.","vi":"Đơn hàng của bạn sẽ được giao trong ba đến năm ngày."},{"en":"The manager gave orders to close the store early.","vi":"Quản lý đã ra lệnh đóng cửa hàng sớm."}]','[{"phrase":"in order"},{"phrase":"place an order"},{"phrase":"give orders"}]',NULL,'/ˈɔːrdər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ord/order/order__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(198,'ngsl-1-05',18,'government','chính phủ; chính quyền','noun','[{"en":"The government is building a new hospital in our town.","vi":"Chính phủ đang xây một bệnh viện mới ở thị trấn của chúng tôi."},{"en":"She works for the local government as an engineer.","vi":"Cô ấy làm kỹ sư cho chính quyền địa phương."},{"en":"The government gives free school meals to young children.","vi":"Chính phủ cấp bữa ăn miễn phí ở trường cho trẻ nhỏ."}]','[{"phrase":"local government"},{"phrase":"central government"},{"phrase":"work for the government"}]',NULL,'/ˈɡʌvərnmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gov/gover/government__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(199,'ngsl-1-05',19,'word','từ; lời','noun','[{"en":"I don''t know what this word means in English.","vi":"Tôi không biết từ này trong tiếng Anh nghĩa là gì."},{"en":"Can I have a word with you after class?","vi":"Sau giờ học tôi nói chuyện với bạn một chút được không?"},{"en":"He promised to help, and he kept his word.","vi":"Anh ấy hứa sẽ giúp và anh ấy đã giữ lời."}]','[{"phrase":"in other words"},{"phrase":"have a word with"},{"phrase":"keep your word"}]',NULL,'/wɜːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/word_/word__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(200,'ngsl-1-05',20,'issue','vấn đề; số báo','noun','[{"en":"Money is a big issue for many students.","vi":"Tiền bạc là một vấn đề lớn với nhiều sinh viên."},{"en":"If you have any issues with the app, please contact us.","vi":"Nếu bạn gặp vấn đề gì với ứng dụng, vui lòng liên hệ với chúng tôi."},{"en":"Did you read the latest issue of the magazine?","vi":"Bạn đã đọc số mới nhất của tạp chí chưa?"}]','[{"phrase":"a big issue"},{"phrase":"deal with an issue"},{"phrase":"the latest issue"}]',NULL,'/ˈɪʃuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iss/issue/issue__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(201,'ngsl-1-05',21,'market','chợ; thị trường','noun','[{"en":"My grandmother buys fresh vegetables at the market every morning.","vi":"Bà tôi mua rau tươi ở chợ mỗi sáng."},{"en":"There''s a night market near our hotel.","vi":"Gần khách sạn của chúng tôi có một chợ đêm."},{"en":"The job market is very difficult for young people right now.","vi":"Hiện nay thị trường việc làm rất khó khăn với người trẻ."}]','[{"phrase":"go to the market"},{"phrase":"night market"},{"phrase":"job market"}]',NULL,'/ˈmɑːrkɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/marke/market__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(202,'ngsl-1-05',22,'pay','trả tiền; thanh toán','verb','[{"en":"Can I pay by credit card, or only in cash?","vi":"Tôi có thể thanh toán bằng thẻ tín dụng không, hay chỉ bằng tiền mặt?"},{"en":"I paid twenty dollars for this shirt.","vi":"Tôi đã trả hai mươi đô la cho chiếc áo này."},{"en":"Let me pay for dinner tonight, since you paid last time.","vi":"Tối nay để tôi trả tiền bữa tối nhé, vì lần trước bạn trả rồi."}]','[{"phrase":"pay for"},{"phrase":"pay by card"},{"phrase":"pay in cash"},{"phrase":"pay the bill"}]','pay – paid – paid','/peɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pay/pay__/pay__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(203,'ngsl-1-05',23,'build','xây; xây dựng','verb','[{"en":"My father built this house thirty years ago.","vi":"Bố tôi đã xây ngôi nhà này ba mươi năm trước."},{"en":"They''re building a new bridge across the river.","vi":"Họ đang xây một cây cầu mới bắc qua sông."},{"en":"It takes time to build trust with new customers.","vi":"Cần có thời gian để xây dựng lòng tin với khách hàng mới."}]','[{"phrase":"build a house"},{"phrase":"build a bridge"},{"phrase":"build trust"}]','build – built – built','/bɪld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bui/build/build__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(204,'ngsl-1-05',24,'hold','cầm; nắm; tổ chức','verb','[{"en":"Can you hold my bag for a minute?","vi":"Bạn cầm giúp tôi cái túi một lát được không?"},{"en":"The little girl held her mother''s hand tightly.","vi":"Cô bé nắm chặt tay mẹ."},{"en":"The school will hold a meeting for parents on Friday.","vi":"Nhà trường sẽ tổ chức một buổi họp phụ huynh vào thứ Sáu."}]','[{"phrase":"hold a meeting"},{"phrase":"hold somebody''s hand"},{"phrase":"hold the door"}]','hold – held – held','/həʊld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/hold_/hold__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(205,'ngsl-1-05',25,'service','dịch vụ; sự phục vụ','noun','[{"en":"The food was good, but the service was very slow.","vi":"Đồ ăn ngon nhưng phục vụ rất chậm."},{"en":"There is no bus service on public holidays.","vi":"Không có dịch vụ xe buýt vào các ngày lễ."},{"en":"Please call customer service if you have any problems.","vi":"Vui lòng gọi bộ phận chăm sóc khách hàng nếu bạn gặp bất kỳ vấn đề nào."}]','[{"phrase":"customer service"},{"phrase":"good service"},{"phrase":"bus service"},{"phrase":"provide a service"}]',NULL,'/ˈsɜːrvɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/servi/service__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(206,'ngsl-1-05',26,'against','phản đối; đấu với; dựa vào','preposition','[{"en":"We''re playing against a very strong team on Saturday.","vi":"Thứ Bảy này chúng tôi sẽ đấu với một đội rất mạnh."},{"en":"He leaned his bike against the wall.","vi":"Anh ấy dựa xe đạp vào tường."},{"en":"My parents were against the idea of me moving abroad.","vi":"Bố mẹ tôi phản đối việc tôi chuyển ra nước ngoài."}]','[{"phrase":"against the law"},{"phrase":"against the wall"},{"phrase":"play against"}]',NULL,'/əˈɡenst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aga/again/against__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(207,'ngsl-1-05',27,'believe','tin; tin rằng','verb','[{"en":"I can''t believe we''ve been living here for ten years.","vi":"Tôi không thể tin là chúng tôi đã sống ở đây mười năm rồi."},{"en":"Do you believe everything you read online?","vi":"Bạn có tin mọi thứ bạn đọc trên mạng không?"},{"en":"She believes that anyone can learn a new language.","vi":"Cô ấy tin rằng ai cũng có thể học một ngôn ngữ mới."}]','[{"phrase":"can''t believe"},{"phrase":"believe in"},{"phrase":"strongly believe"}]',NULL,'/bɪˈliːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belie/believe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(208,'ngsl-1-05',28,'second','thứ hai; giây','adjective','[{"en":"I''m visiting this city for the second time.","vi":"Đây là lần thứ hai tôi đến thăm thành phố này."},{"en":"She came second in the school running race.","vi":"Cô ấy về nhì trong cuộc thi chạy của trường."},{"en":"It only takes thirty seconds to heat the milk.","vi":"Chỉ mất ba mươi giây để hâm nóng sữa."}]','[{"phrase":"for the second time"},{"phrase":"a few seconds"},{"phrase":"wait a second"}]',NULL,'/ˈsekənd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secon/second__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(209,'ngsl-1-05',29,'though','mặc dù; tuy vậy','conjunction','[{"en":"Though it was raining, we still went for a walk.","vi":"Mặc dù trời mưa, chúng tôi vẫn đi dạo."},{"en":"She kept working even though she felt sick.","vi":"Cô ấy vẫn tiếp tục làm việc dù đang bị ốm."},{"en":"The room was small; it was very clean, though.","vi":"Căn phòng nhỏ, tuy vậy lại rất sạch sẽ."}]','[{"phrase":"even though"},{"phrase":"as though"}]',NULL,'/ðəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tho/thoug/though__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(210,'ngsl-1-05',30,'love','yêu; rất thích','verb','[{"en":"She loves her family more than anything.","vi":"Cô ấy yêu gia đình mình hơn bất cứ điều gì."},{"en":"My kids love playing in the snow.","vi":"Các con tôi rất thích chơi đùa trong tuyết."},{"en":"I''d love to come to your party on Saturday.","vi":"Tôi rất muốn đến dự bữa tiệc của bạn vào thứ Bảy."}]','[{"phrase":"would love to"},{"phrase":"love doing something"},{"phrase":"fall in love"}]',NULL,'/lʌv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lov/love_/love__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(211,'ngsl-1-06',1,'increase','tăng; làm tăng','verb','[{"en":"The café increased its prices last month.","vi":"Quán cà phê đã tăng giá vào tháng trước."},{"en":"Her salary increased by ten percent this year.","vi":"Lương của cô ấy đã tăng mười phần trăm trong năm nay."},{"en":"The number of students in my class has increased to forty.","vi":"Số học sinh trong lớp tôi đã tăng lên bốn mươi."}]','[{"phrase":"increase by"},{"phrase":"increase sharply"},{"phrase":"increase prices"},{"phrase":"increase the number of"}]',NULL,'/ɪnˈkriːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incre/increase__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(212,'ngsl-1-06',2,'job','công việc; việc làm','noun','[{"en":"My brother just got a new job at a hospital.","vi":"Anh trai tôi vừa có công việc mới ở một bệnh viện."},{"en":"She is looking for a part-time job near her school.","vi":"Cô ấy đang tìm một công việc bán thời gian gần trường."},{"en":"He lost his job when the factory closed.","vi":"Anh ấy mất việc khi nhà máy đóng cửa."}]','[{"phrase":"get a job"},{"phrase":"lose your job"},{"phrase":"part-time job"},{"phrase":"look for a job"}]',NULL,'/dʒɑːb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/job/job__/job__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(213,'ngsl-1-06',3,'plan','kế hoạch; dự định','noun','[{"en":"Do you have any plans for the weekend?","vi":"Bạn có kế hoạch gì cho cuối tuần không?"},{"en":"Our plan is to leave early and avoid the traffic.","vi":"Kế hoạch của chúng tôi là đi sớm để tránh kẹt xe."},{"en":"Everything at the wedding went according to plan.","vi":"Mọi việc trong đám cưới đều diễn ra đúng kế hoạch."}]','[{"phrase":"make plans"},{"phrase":"have plans"},{"phrase":"according to plan"},{"phrase":"change of plan"}]',NULL,'/plæn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plan_/plan__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(214,'ngsl-1-06',4,'result','kết quả','noun','[{"en":"We are still waiting for the results of the blood test.","vi":"Chúng tôi vẫn đang chờ kết quả xét nghiệm máu."},{"en":"As a result of the storm, all flights were canceled.","vi":"Do cơn bão, tất cả các chuyến bay đều bị hủy."},{"en":"She studied hard and got excellent results in her exams.","vi":"Cô ấy học chăm chỉ và đạt kết quả xuất sắc trong các kỳ thi."}]','[{"phrase":"as a result"},{"phrase":"exam results"},{"phrase":"get results"},{"phrase":"final result"}]',NULL,'/rɪˈzʌlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resul/result__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(215,'ngsl-1-06',5,'away','xa; đi khỏi; vắng nhà','adverb','[{"en":"The nearest supermarket is about two kilometers away from here.","vi":"Siêu thị gần nhất cách đây khoảng hai cây số."},{"en":"The dog ran away when it heard the loud noise.","vi":"Con chó bỏ chạy khi nghe thấy tiếng động lớn."},{"en":"My parents are away on vacation until next Friday.","vi":"Bố mẹ tôi đi nghỉ vắng nhà cho đến thứ Sáu tuần sau."}]','[{"phrase":"far away"},{"phrase":"go away"},{"phrase":"run away"},{"phrase":"put away"}]',NULL,'/əˈweɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/away_/away__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(216,'ngsl-1-06',6,'example','ví dụ; tấm gương','noun','[{"en":"Can you give me an example of how to use this word?","vi":"Bạn có thể cho tôi một ví dụ về cách dùng từ này không?"},{"en":"Many fruits, for example apples and oranges, are rich in vitamin C.","vi":"Nhiều loại trái cây, ví dụ như táo và cam, rất giàu vitamin C."},{"en":"Parents should set a good example for their children.","vi":"Cha mẹ nên làm gương tốt cho con cái."}]','[{"phrase":"for example"},{"phrase":"give an example"},{"phrase":"set an example"},{"phrase":"good example"}]',NULL,'/ɪɡˈzæmpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/examp/example__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(217,'ngsl-1-06',7,'happen','xảy ra; tình cờ','verb','[{"en":"Tell me exactly what happened at the party.","vi":"Kể cho tôi nghe chính xác chuyện gì đã xảy ra ở bữa tiệc."},{"en":"Accidents often happen when drivers are tired.","vi":"Tai nạn thường xảy ra khi tài xế mệt mỏi."},{"en":"I happened to meet my old teacher at the market.","vi":"Tôi tình cờ gặp lại thầy giáo cũ ở chợ."}]','[{"phrase":"what happened"},{"phrase":"happen again"},{"phrase":"happen to"}]',NULL,'/ˈhæpən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hap/happe/happen__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(218,'ngsl-1-06',8,'offer','đề nghị; mời; cung cấp','verb','[{"en":"My neighbor offered to help me move the sofa.","vi":"Người hàng xóm đề nghị giúp tôi chuyển chiếc ghế sofa."},{"en":"She offered me a cup of tea when I arrived.","vi":"Cô ấy mời tôi một tách trà khi tôi đến."},{"en":"The hotel offers free breakfast to all its guests.","vi":"Khách sạn cung cấp bữa sáng miễn phí cho tất cả khách lưu trú."}]','[{"phrase":"offer to help"},{"phrase":"offer advice"},{"phrase":"offer a job"}]','offer to do something: đề nghị làm gì','/ˈɔːfər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offer/offer__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(219,'ngsl-1-06',9,'young','trẻ; nhỏ tuổi','adjective','[{"en":"My grandmother was a teacher when she was young.","vi":"Bà tôi từng là giáo viên khi bà còn trẻ."},{"en":"The park is full of young families on Sundays.","vi":"Vào Chủ nhật, công viên có rất nhiều gia đình trẻ."},{"en":"He is still too young to drive a car.","vi":"Cậu bé vẫn còn quá nhỏ để lái ô tô."}]','[{"phrase":"young people"},{"phrase":"young children"},{"phrase":"young family"},{"phrase":"too young"}]',NULL,'/jʌŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/you/young/young__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(220,'ngsl-1-06',10,'close','đóng; đóng cửa; nhắm (mắt)','verb','[{"en":"Could you close the window because it''s getting cold?","vi":"Bạn đóng cửa sổ lại được không, vì trời đang trở lạnh?"},{"en":"The bank closes at four o''clock on Fridays.","vi":"Ngân hàng đóng cửa lúc bốn giờ vào các ngày thứ Sáu."},{"en":"Close your eyes and try to relax for a minute.","vi":"Hãy nhắm mắt lại và cố gắng thư giãn một chút."}]','[{"phrase":"close the door"},{"phrase":"close the window"},{"phrase":"close your eyes"}]','Tính từ close (đọc /kləʊs/) nghĩa là "gần"','/kləʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/close/close__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(221,'ngsl-1-06',11,'program','chương trình','noun','[{"en":"My favorite TV program starts at eight tonight.","vi":"Chương trình truyền hình yêu thích của tôi bắt đầu lúc tám giờ tối nay."},{"en":"She joined an exchange program in Japan last year.","vi":"Năm ngoái cô ấy tham gia một chương trình trao đổi ở Nhật Bản."},{"en":"You need to install this program on your computer first.","vi":"Trước tiên bạn cần cài đặt chương trình này trên máy tính."}]','[{"phrase":"TV program"},{"phrase":"exchange program"},{"phrase":"training program"},{"phrase":"computer program"}]','Anh: programme · Mỹ: program','/ˈprəʊɡræm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/progr/program__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(222,'ngsl-1-06',12,'lead','dẫn; dẫn đến; lãnh đạo','verb','[{"en":"This path leads directly to the beach.","vi":"Con đường này dẫn thẳng ra bãi biển."},{"en":"Eating too much sugar can lead to health problems.","vi":"Ăn quá nhiều đường có thể dẫn đến các vấn đề sức khỏe."},{"en":"She led a team of ten engineers on the project.","vi":"Cô ấy lãnh đạo một nhóm gồm mười kỹ sư trong dự án đó."}]','[{"phrase":"lead to"},{"phrase":"lead a team"},{"phrase":"lead the way"}]','lead – led – led','/liːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/lead_/lead__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(223,'ngsl-1-06',13,'buy','mua','verb','[{"en":"I bought a new pair of shoes for the party.","vi":"Tôi đã mua một đôi giày mới để đi dự tiệc."},{"en":"Where can I buy tickets for the concert?","vi":"Tôi có thể mua vé buổi hòa nhạc ở đâu?"},{"en":"They are saving money to buy a house next year.","vi":"Họ đang tiết kiệm tiền để mua nhà vào năm sau."}]','[{"phrase":"buy tickets"},{"phrase":"buy a house"},{"phrase":"buy a present"}]','buy – bought – bought','/baɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/buy/buy__/buy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(224,'ngsl-1-06',14,'understand','hiểu','verb','[{"en":"Sorry, I don''t understand what you mean.","vi":"Xin lỗi, tôi không hiểu ý bạn."},{"en":"My parents always understand how I feel.","vi":"Bố mẹ tôi luôn hiểu cảm giác của tôi."},{"en":"She understood the lesson after the teacher gave another example.","vi":"Cô ấy đã hiểu bài sau khi giáo viên đưa thêm một ví dụ nữa."}]','[{"phrase":"fully understand"},{"phrase":"easy to understand"},{"phrase":"understand what you mean"}]','understand – understood – understood','/ˌʌndərˈstænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/understand__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(225,'ngsl-1-06',15,'thank','cảm ơn','verb','[{"en":"I want to thank you for all your help.","vi":"Tôi muốn cảm ơn bạn vì mọi sự giúp đỡ."},{"en":"She thanked the driver and got off the bus.","vi":"Cô ấy cảm ơn tài xế rồi xuống xe buýt."},{"en":"Don''t forget to thank your grandmother for the gift.","vi":"Đừng quên cảm ơn bà về món quà nhé."}]','[{"phrase":"thank you"},{"phrase":"thank you for"},{"phrase":"thank you very much"}]','thank somebody for something','/θæŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tha/thank/thank__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(226,'ngsl-1-06',16,'far','xa','adverb','[{"en":"How far is the airport from the city center?","vi":"Sân bay cách trung tâm thành phố bao xa?"},{"en":"We didn''t walk very far because it started to rain.","vi":"Chúng tôi không đi bộ xa lắm vì trời bắt đầu mưa."},{"en":"My school isn''t far from my house.","vi":"Trường của tôi cách nhà không xa."}]','[{"phrase":"how far"},{"phrase":"far away"},{"phrase":"far from"},{"phrase":"so far"}]','far – farther/further – farthest/furthest','/fɑːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/far/far__/far__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(227,'ngsl-1-06',17,'today','hôm nay; ngày nay','adverb','[{"en":"I''ll call you back later today, after my meeting.","vi":"Hôm nay tôi sẽ gọi lại cho bạn sau khi họp xong."},{"en":"What are you doing today after work?","vi":"Hôm nay tan làm bạn định làm gì?"},{"en":"Young people today spend a lot of time on their phones.","vi":"Giới trẻ ngày nay dành nhiều thời gian cho điện thoại."}]','[{"phrase":"later today"},{"phrase":"earlier today"},{"phrase":"from today"}]',NULL,'/təˈdeɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tod/today/today__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(228,'ngsl-1-06',18,'hour','giờ; tiếng đồng hồ','noun','[{"en":"The flight to Hanoi takes about two hours.","vi":"Chuyến bay đến Hà Nội mất khoảng hai tiếng."},{"en":"I usually work eight hours a day.","vi":"Tôi thường làm việc tám tiếng mỗi ngày."},{"en":"The store''s opening hours are from nine to five.","vi":"Giờ mở cửa của cửa hàng là từ chín giờ đến năm giờ."}]','[{"phrase":"half an hour"},{"phrase":"opening hours"},{"phrase":"working hours"},{"phrase":"an hour ago"}]','h câm, nên nói "an hour"','/ˈaʊər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hou/hour_/hour__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(229,'ngsl-1-06',19,'student','học sinh; sinh viên','noun','[{"en":"There are thirty students in my English class.","vi":"Lớp tiếng Anh của tôi có ba mươi học sinh."},{"en":"My sister is a medical student in her third year.","vi":"Chị tôi là sinh viên y năm thứ ba."},{"en":"Students get a discount at this museum on weekdays.","vi":"Học sinh, sinh viên được giảm giá ở bảo tàng này vào các ngày trong tuần."}]','[{"phrase":"medical student"},{"phrase":"university student"},{"phrase":"student discount"},{"phrase":"exchange student"}]',NULL,'/ˈstuːdnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/stude/student__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(230,'ngsl-1-06',20,'face','mặt; khuôn mặt','noun','[{"en":"Go and wash your face before breakfast.","vi":"Con đi rửa mặt trước khi ăn sáng đi."},{"en":"She had a big smile on her face all day.","vi":"Cả ngày trên mặt cô ấy luôn nở một nụ cười thật tươi."},{"en":"I''ll never forget the look on his face.","vi":"Tôi sẽ không bao giờ quên vẻ mặt của anh ấy lúc đó."}]','[{"phrase":"wash your face"},{"phrase":"face to face"},{"phrase":"smile on your face"}]','Động từ face: đối mặt (face a problem)','/feɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/face_/face__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(231,'ngsl-1-06',21,'hope','hy vọng; mong','verb','[{"en":"I really hope you feel better soon.","vi":"Tôi thật lòng mong bạn sớm khỏe lại."},{"en":"We''re hoping to visit our grandparents this summer.","vi":"Chúng tôi hy vọng được về thăm ông bà vào mùa hè này."},{"en":"She hopes to become a doctor one day.","vi":"Cô ấy hy vọng một ngày nào đó sẽ trở thành bác sĩ."}]','[{"phrase":"I hope so"},{"phrase":"hope for the best"},{"phrase":"really hope"}]','hope to do something; hope (that) ...','/həʊp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hop/hope_/hope__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(232,'ngsl-1-06',22,'idea','ý tưởng; ý kiến','noun','[{"en":"That''s a great idea for a birthday present.","vi":"Đó là một ý tưởng tuyệt vời cho món quà sinh nhật."},{"en":"It was her idea to go camping this weekend.","vi":"Đi cắm trại cuối tuần này là ý của cô ấy."},{"en":"Do you think it''s a good idea to buy a car now?","vi":"Bạn có nghĩ bây giờ mua ô tô là ý hay không?"}]','[{"phrase":"good idea"},{"phrase":"great idea"},{"phrase":"have no idea"},{"phrase":"come up with an idea"}]',NULL,'/aɪˈdiːə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/idea_/idea__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(233,'ngsl-1-06',23,'cost','có giá; tốn','verb','[{"en":"How much did your new laptop cost?","vi":"Chiếc laptop mới của bạn giá bao nhiêu?"},{"en":"The trip cost us more than we expected.","vi":"Chuyến đi khiến chúng tôi tốn nhiều tiền hơn dự kiến."},{"en":"Fixing the roof will cost about five hundred dollars.","vi":"Sửa mái nhà sẽ tốn khoảng năm trăm đô la."}]','[{"phrase":"cost a lot"},{"phrase":"cost money"},{"phrase":"cost a fortune"}]','cost – cost – cost','/kɔːst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cos/cost_/cost__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(234,'ngsl-1-06',24,'less','ít hơn','determiner','[{"en":"You should eat less sugar and more vegetables.","vi":"Bạn nên ăn ít đường hơn và ăn nhiều rau hơn."},{"en":"I spend less time on my phone than I used to.","vi":"Bây giờ tôi dành ít thời gian cho điện thoại hơn trước."},{"en":"It took less than ten minutes to get there.","vi":"Mất chưa đầy mười phút để đến đó."}]','[{"phrase":"less than"},{"phrase":"less time"},{"phrase":"less money"},{"phrase":"more or less"}]','Dùng với danh từ không đếm được; danh từ đếm được dùng fewer','/les/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/les/less_/less__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(235,'ngsl-1-06',25,'room','phòng; chỗ trống','noun','[{"en":"My room is on the second floor.","vi":"Phòng của tôi ở tầng hai."},{"en":"We booked a double room at a small hotel by the beach.","vi":"Chúng tôi đã đặt một phòng đôi ở một khách sạn nhỏ gần biển."},{"en":"Is there enough room in the car for one more person?","vi":"Trong xe còn đủ chỗ cho thêm một người nữa không?"}]','[{"phrase":"living room"},{"phrase":"double room"},{"phrase":"book a room"},{"phrase":"make room for"}]','Nghĩa "chỗ trống" không đếm được','/ruːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roo/room_/room__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(236,'ngsl-1-06',26,'until','đến; cho đến khi','preposition','[{"en":"The library is open until nine o''clock tonight.","vi":"Thư viện mở cửa đến chín giờ tối nay."},{"en":"I lived with my parents until I was twenty-five.","vi":"Tôi sống cùng bố mẹ cho đến năm hai mươi lăm tuổi."},{"en":"Please wait here until the doctor calls your name.","vi":"Vui lòng chờ ở đây cho đến khi bác sĩ gọi tên bạn."}]','[{"phrase":"until now"},{"phrase":"until then"},{"phrase":"wait until"}]','not ... until: mãi đến ... mới','/ənˈtɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unt/until/until__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(237,'ngsl-1-06',27,'reason','lý do','noun','[{"en":"What was the reason for the delay?","vi":"Lý do của việc chậm trễ là gì?"},{"en":"She left the job for personal reasons.","vi":"Cô ấy nghỉ việc vì lý do cá nhân."},{"en":"There is no reason to worry about the exam.","vi":"Không có lý do gì phải lo lắng về kỳ thi."}]','[{"phrase":"reason for"},{"phrase":"for some reason"},{"phrase":"personal reasons"},{"phrase":"good reason"}]','reason for something','/ˈriːzn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reaso/reason__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(238,'ngsl-1-06',28,'form','mẫu đơn; hình thức; dạng','noun','[{"en":"Please fill out this form and give it to the receptionist.","vi":"Vui lòng điền vào mẫu đơn này và nộp cho lễ tân."},{"en":"Cycling is a cheap and healthy form of transportation.","vi":"Đi xe đạp là một hình thức đi lại rẻ và tốt cho sức khỏe."},{"en":"Write the correct form of the verb in each blank.","vi":"Hãy viết dạng đúng của động từ vào mỗi chỗ trống."}]','[{"phrase":"fill out a form"},{"phrase":"application form"},{"phrase":"a form of"}]',NULL,'/fɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/form_/form__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(239,'ngsl-1-06',29,'spend','tiêu; dành; trải qua','verb','[{"en":"She spends too much money on clothes.","vi":"Cô ấy tiêu quá nhiều tiền vào quần áo."},{"en":"We spent the whole weekend at my uncle''s farm.","vi":"Chúng tôi đã ở trang trại của chú tôi suốt cả cuối tuần."},{"en":"How much time do you spend on homework every day?","vi":"Mỗi ngày bạn dành bao nhiêu thời gian làm bài tập về nhà?"}]','[{"phrase":"spend money"},{"phrase":"spend time"},{"phrase":"spend the weekend"}]','spend – spent – spent; spend time/money on something','/spend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/spend/spend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(240,'ngsl-1-06',30,'head','đầu; người đứng đầu','noun','[{"en":"He hit his head on the door.","vi":"Anh ấy bị đập đầu vào cửa."},{"en":"My head hurts because I didn''t sleep well.","vi":"Tôi đau đầu vì ngủ không ngon."},{"en":"My aunt is the head of a small primary school.","vi":"Dì tôi là hiệu trưởng một trường tiểu học nhỏ."}]','[{"phrase":"shake your head"},{"phrase":"hit your head"},{"phrase":"head of"}]',NULL,'/hed/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/head_/head__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(241,'ngsl-1-07',1,'car','xe hơi; ô tô','noun','[{"en":"My brother drives his car to work every day.","vi":"Anh trai tôi lái xe hơi đi làm mỗi ngày."},{"en":"We rented a car for our trip to the mountains.","vi":"Chúng tôi thuê một chiếc ô tô cho chuyến đi lên núi."},{"en":"Could you help me carry these bags to the car?","vi":"Bạn có thể giúp tôi mang mấy cái túi này ra xe không?"}]','[{"phrase":"drive a car"},{"phrase":"rent a car"},{"phrase":"car accident"},{"phrase":"by car"}]',NULL,'/kɑːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/car__/car__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(242,'ngsl-1-07',2,'learn','học; biết được','verb','[{"en":"My daughter is learning to swim this summer.","vi":"Mùa hè này con gái tôi đang học bơi."},{"en":"I want to learn English so I can travel more easily.","vi":"Tôi muốn học tiếng Anh để có thể đi du lịch dễ dàng hơn."},{"en":"We only learned about the change the next morning.","vi":"Mãi đến sáng hôm sau chúng tôi mới biết về sự thay đổi đó."}]','[{"phrase":"learn English"},{"phrase":"learn to swim"},{"phrase":"learn from your mistakes"},{"phrase":"learn about"}]','Mỹ: learned · Anh: learned/learnt','/lɜːrn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/learn/learn__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(243,'ngsl-1-07',3,'level','mức; trình độ','noun','[{"en":"Stress levels are often high before exams.","vi":"Mức độ căng thẳng thường cao trước kỳ thi."},{"en":"What level of English do you need for this job?","vi":"Công việc này cần trình độ tiếng Anh ở mức nào?"},{"en":"The water level in the river rose after the heavy rain.","vi":"Mực nước sông dâng cao sau trận mưa lớn."}]','[{"phrase":"high level"},{"phrase":"water level"},{"phrase":"advanced level"}]',NULL,'/ˈlevl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lev/level/level__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(244,'ngsl-1-07',4,'person','người; cá nhân','noun','[{"en":"She is the kindest person I have ever met.","vi":"Cô ấy là người tốt bụng nhất mà tôi từng gặp."},{"en":"Tickets for the show cost ten dollars per person.","vi":"Vé xem buổi biểu diễn có giá mười đô la mỗi người."},{"en":"Every person in the class has to give a short talk.","vi":"Mỗi người trong lớp đều phải thuyết trình ngắn."}]','[{"phrase":"per person"},{"phrase":"in person"},{"phrase":"a nice person"}]','số nhiều thường dùng: people','/ˈpɜːrsn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/person__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(245,'ngsl-1-07',5,'experience','kinh nghiệm; trải nghiệm','noun','[{"en":"Do you have any experience working with children?","vi":"Bạn có kinh nghiệm làm việc với trẻ em không?"},{"en":"Living abroad was a great experience for me.","vi":"Sống ở nước ngoài là một trải nghiệm tuyệt vời đối với tôi."},{"en":"She has ten years of experience as a nurse.","vi":"Cô ấy có mười năm kinh nghiệm làm y tá."}]','[{"phrase":"work experience"},{"phrase":"years of experience"},{"phrase":"a great experience"}]','nghĩa "kinh nghiệm": không đếm được','/ɪkˈspɪriəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/experience__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(246,'ngsl-1-07',6,'once','một lần; đã từng','adverb','[{"en":"I go to the gym once a week.","vi":"Tôi đến phòng tập một lần mỗi tuần."},{"en":"We once lived in a small town near the sea.","vi":"Chúng tôi đã từng sống ở một thị trấn nhỏ gần biển."},{"en":"I have only been to Japan once.","vi":"Tôi mới chỉ đến Nhật Bản một lần."}]','[{"phrase":"once a week"},{"phrase":"once again"},{"phrase":"at once"}]',NULL,'/wʌns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/onc/once_/once__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(247,'ngsl-1-07',7,'member','thành viên; hội viên','noun','[{"en":"She is the youngest member of the team.","vi":"Cô ấy là thành viên trẻ nhất của đội."},{"en":"All family members came home for the holiday.","vi":"Tất cả thành viên trong gia đình đều về nhà dịp lễ."},{"en":"Members of the gym can use the pool for free.","vi":"Hội viên của phòng tập được dùng hồ bơi miễn phí."}]','[{"phrase":"family member"},{"phrase":"team member"},{"phrase":"become a member"}]',NULL,'/ˈmembər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mem/membe/member__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(248,'ngsl-1-07',8,'enough','đủ','determiner','[{"en":"We don''t have enough money to buy a new house.","vi":"Chúng tôi không có đủ tiền để mua nhà mới."},{"en":"Is there enough food for everyone at the party?","vi":"Có đủ đồ ăn cho mọi người ở bữa tiệc không?"},{"en":"He isn''t old enough to drive yet.","vi":"Cậu ấy chưa đủ tuổi để lái xe."}]','[{"phrase":"enough money"},{"phrase":"enough time"},{"phrase":"old enough"}]','đứng trước danh từ (enough time), sau tính từ (old enough)','/ɪˈnʌf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eno/enoug/enough__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(249,'ngsl-1-07',9,'bad','xấu; tệ; có hại','adjective','[{"en":"I had a really bad day at work today.","vi":"Hôm nay tôi đã có một ngày thật tệ ở chỗ làm."},{"en":"Eating too much sugar is bad for your teeth.","vi":"Ăn quá nhiều đường có hại cho răng."},{"en":"The weather was so bad that we stayed inside all day.","vi":"Thời tiết xấu đến mức chúng tôi ở trong nhà cả ngày."}]','[{"phrase":"bad weather"},{"phrase":"bad news"},{"phrase":"bad for your health"},{"phrase":"bad day"}]','bad – worse – worst','/bæd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bad/bad__/bad__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(250,'ngsl-1-07',10,'city','thành phố','noun','[{"en":"I grew up in a small village, but now I live in the city.","vi":"Tôi lớn lên ở một ngôi làng nhỏ, nhưng giờ tôi sống ở thành phố."},{"en":"The city center is always busy on weekends.","vi":"Trung tâm thành phố lúc nào cũng đông đúc vào cuối tuần."},{"en":"Which city would you most like to visit?","vi":"Bạn muốn đến thăm thành phố nào nhất?"}]','[{"phrase":"city center"},{"phrase":"big city"},{"phrase":"capital city"},{"phrase":"city life"}]',NULL,'/ˈsɪti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/city_/city__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(251,'ngsl-1-07',11,'night','đêm; buổi tối','noun','[{"en":"I couldn''t sleep last night because of the noise.","vi":"Đêm qua tôi không ngủ được vì tiếng ồn."},{"en":"She works at a hospital and often works at night.","vi":"Cô ấy làm ở bệnh viện và thường làm việc vào ban đêm."},{"en":"Let''s have a movie night at home on Friday.","vi":"Tối thứ Sáu mình cùng xem phim ở nhà nhé."}]','[{"phrase":"last night"},{"phrase":"at night"},{"phrase":"all night"},{"phrase":"good night"}]',NULL,'/naɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nig/night/night__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(252,'ngsl-1-07',12,'able','có thể; có khả năng','adjective','[{"en":"Will you be able to come to the meeting tomorrow?","vi":"Ngày mai bạn có thể đến dự cuộc họp không?"},{"en":"She was able to finish the report on time.","vi":"Cô ấy đã hoàn thành được bản báo cáo đúng hạn."},{"en":"After the operation, he wasn''t able to walk for a month.","vi":"Sau ca phẫu thuật, anh ấy không đi lại được trong một tháng."}]','[{"phrase":"be able to"},{"phrase":"no longer able to"}]','be able to + động từ nguyên mẫu','/ˈeɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abl/able_/able__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(253,'ngsl-1-07',13,'support','ủng hộ; hỗ trợ; nuôi (gia đình)','verb','[{"en":"My parents have always supported my decision to study abroad.","vi":"Bố mẹ tôi luôn ủng hộ quyết định đi du học của tôi."},{"en":"Our team supports customers by phone and email.","vi":"Nhóm của chúng tôi hỗ trợ khách hàng qua điện thoại và email."},{"en":"He works two jobs to support his family.","vi":"Anh ấy làm hai công việc để nuôi gia đình."}]','[{"phrase":"support a decision"},{"phrase":"support your family"},{"phrase":"strongly support"},{"phrase":"fully support"}]',NULL,'/səˈpɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppo/support__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(254,'ngsl-1-07',14,'whether','liệu; có... hay không','conjunction','[{"en":"I''m not sure whether she will come tonight.","vi":"Tôi không chắc liệu tối nay cô ấy có đến không."},{"en":"Can you check whether the store is open on Sunday?","vi":"Bạn kiểm tra giúp xem cửa hàng có mở cửa vào Chủ nhật không nhé?"},{"en":"We''ll go to the beach whether it rains or not.","vi":"Dù trời có mưa hay không, chúng tôi vẫn sẽ đi biển."}]','[{"phrase":"not sure whether"},{"phrase":"whether or not"},{"phrase":"decide whether"}]',NULL,'/ˈweðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/wheth/whether__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(255,'ngsl-1-07',15,'line','hàng; dòng; đường kẻ','noun','[{"en":"There was a long line outside the bakery this morning.","vi":"Sáng nay có một hàng dài người xếp trước tiệm bánh."},{"en":"Please read the first line of the poem aloud.","vi":"Hãy đọc to dòng đầu tiên của bài thơ."},{"en":"Draw a straight line across the page.","vi":"Hãy kẻ một đường thẳng ngang trang giấy."}]','[{"phrase":"long line"},{"phrase":"wait in line"},{"phrase":"straight line"},{"phrase":"first line"}]','hàng người xếp: Mỹ: line · Anh: queue','/laɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lin/line_/line__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(256,'ngsl-1-07',16,'present','món quà; hiện tại','noun','[{"en":"I need to buy a birthday present for my sister.","vi":"Tôi cần mua quà sinh nhật cho em gái."},{"en":"Thank you so much for the lovely present!","vi":"Cảm ơn bạn rất nhiều vì món quà dễ thương!"},{"en":"Try to forget the past and enjoy the present.","vi":"Hãy cố quên đi quá khứ và tận hưởng hiện tại."}]','[{"phrase":"birthday present"},{"phrase":"wedding present"},{"phrase":"at present"}]','danh từ nhấn âm đầu; động từ present (trình bày) nhấn âm sau','/ˈpreznt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/present__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(257,'ngsl-1-07',17,'side','bên; phía; mặt','noun','[{"en":"The bank is on the other side of the street.","vi":"Ngân hàng nằm ở phía bên kia đường."},{"en":"Which side are you on in this argument?","vi":"Trong cuộc tranh cãi này, bạn đứng về phía ai?"},{"en":"Write your answers on both sides of the paper.","vi":"Hãy viết câu trả lời lên cả hai mặt giấy."}]','[{"phrase":"the other side"},{"phrase":"both sides"},{"phrase":"left side"},{"phrase":"take sides"}]',NULL,'/saɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sid/side_/side__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(258,'ngsl-1-07',18,'quite','khá; hoàn toàn','adverb','[{"en":"The test was quite difficult, but I think I passed.","vi":"Bài kiểm tra khá khó, nhưng tôi nghĩ mình đã đậu."},{"en":"It''s quite cold today, so bring a jacket.","vi":"Hôm nay trời khá lạnh, nên hãy mang theo áo khoác."},{"en":"You''re quite right; I made a mistake.","vi":"Bạn hoàn toàn đúng; tôi đã nhầm."}]','[{"phrase":"quite good"},{"phrase":"quite a lot"},{"phrase":"quite right"},{"phrase":"not quite"}]',NULL,'/kwaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quite/quite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(259,'ngsl-1-07',19,'although','mặc dù','conjunction','[{"en":"Although it was raining, we went for a walk.","vi":"Mặc dù trời đang mưa, chúng tôi vẫn đi dạo."},{"en":"She went to work although she felt sick.","vi":"Cô ấy vẫn đi làm mặc dù cảm thấy không khỏe."},{"en":"I enjoyed the movie, although it was a bit long.","vi":"Tôi thích bộ phim, mặc dù nó hơi dài."}]','[{"phrase":"although it was"},{"phrase":"although not always"}]','không dùng although và but trong cùng một câu','/ɔːlˈðəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/altho/although__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(260,'ngsl-1-07',20,'sure','chắc chắn; chắc','adjective','[{"en":"Are you sure you locked the door?","vi":"Bạn có chắc là đã khóa cửa không?"},{"en":"I''m not sure what time the train leaves.","vi":"Tôi không chắc mấy giờ tàu chạy."},{"en":"Make sure you drink plenty of water during the hike.","vi":"Hãy nhớ uống nhiều nước trong suốt chuyến đi bộ đường dài."}]','[{"phrase":"make sure"},{"phrase":"not sure"},{"phrase":"for sure"},{"phrase":"sure about"}]',NULL,'/ʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/sure_/sure__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(261,'ngsl-1-07',21,'term','thuật ngữ; học kỳ; thời hạn','noun','[{"en":"Can you explain what this medical term means?","vi":"Bạn có thể giải thích thuật ngữ y khoa này nghĩa là gì không?"},{"en":"The new school term starts in September.","vi":"Học kỳ mới bắt đầu vào tháng Chín."},{"en":"In the long term, learning a language will help your career.","vi":"Về lâu dài, học một ngoại ngữ sẽ giúp ích cho sự nghiệp của bạn."}]','[{"phrase":"technical term"},{"phrase":"in the long term"},{"phrase":"school term"},{"phrase":"in terms of"}]','in terms of: xét về mặt','/tɜːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/term_/term__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(262,'ngsl-1-07',22,'least','ít nhất; tối thiểu','adverb','[{"en":"You should sleep at least seven hours a night.","vi":"Bạn nên ngủ ít nhất bảy tiếng mỗi đêm."},{"en":"The trip was expensive, but at least the food was good.","vi":"Chuyến đi tốn kém, nhưng ít ra đồ ăn cũng ngon."},{"en":"Math is the subject I like the least at school.","vi":"Toán là môn tôi ít thích nhất ở trường."}]','[{"phrase":"at least"},{"phrase":"the least"},{"phrase":"least expensive"}]','little – less – least','/liːst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/least/least__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(263,'ngsl-1-07',23,'age','tuổi; thời đại','noun','[{"en":"She started playing the piano at the age of five.","vi":"Cô ấy bắt đầu chơi piano từ khi mới năm tuổi."},{"en":"People of all ages enjoy this game.","vi":"Người ở mọi lứa tuổi đều thích trò chơi này."},{"en":"We live in the digital age, so most people shop online.","vi":"Chúng ta sống trong thời đại kỹ thuật số, nên hầu hết mọi người đều mua sắm trực tuyến."}]','[{"phrase":"at the age of"},{"phrase":"all ages"},{"phrase":"the same age"},{"phrase":"old age"}]',NULL,'/eɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/age__/age__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(264,'ngsl-1-07',24,'low','thấp; nhỏ','adjective','[{"en":"This chair is too low for the desk.","vi":"Cái ghế này quá thấp so với cái bàn."},{"en":"Prices at this market are very low.","vi":"Giá cả ở chợ này rất thấp."},{"en":"Please speak in a low voice; the baby is sleeping.","vi":"Làm ơn nói nhỏ thôi; em bé đang ngủ."}]','[{"phrase":"low price"},{"phrase":"low voice"},{"phrase":"low temperature"},{"phrase":"low income"}]',NULL,'/ləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/low/low__/low__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(265,'ngsl-1-07',25,'speak','nói; nói chuyện','verb','[{"en":"How many languages can your teacher speak?","vi":"Giáo viên của bạn nói được bao nhiêu thứ tiếng?"},{"en":"Could I speak to the manager, please?","vi":"Cho tôi nói chuyện với quản lý được không?"},{"en":"She spoke quietly so she wouldn''t wake the children.","vi":"Cô ấy nói khẽ để không làm bọn trẻ thức giấc."}]','[{"phrase":"speak English"},{"phrase":"speak to"},{"phrase":"speak quietly"},{"phrase":"speak clearly"}]','speak – spoke – spoken','/spiːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speak/speak__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(266,'ngsl-1-07',26,'within','trong vòng; bên trong','preposition','[{"en":"Please reply to this email within three days.","vi":"Vui lòng trả lời email này trong vòng ba ngày."},{"en":"The hotel is within walking distance of the beach.","vi":"Từ khách sạn có thể đi bộ ra bãi biển."},{"en":"Problems within the team need to be solved quickly.","vi":"Các vấn đề trong nội bộ nhóm cần được giải quyết nhanh chóng."}]','[{"phrase":"within walking distance"},{"phrase":"within a week"},{"phrase":"within reach"}]',NULL,'/wɪˈðɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/withi/within__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(267,'ngsl-1-07',27,'process','quá trình; quy trình','noun','[{"en":"Learning a new language is a slow process.","vi":"Học một ngôn ngữ mới là một quá trình chậm rãi."},{"en":"The application process takes about two weeks.","vi":"Quy trình nộp đơn mất khoảng hai tuần."},{"en":"We are in the process of moving to a new apartment.","vi":"Chúng tôi đang trong quá trình chuyển đến căn hộ mới."}]','[{"phrase":"in the process of"},{"phrase":"application process"},{"phrase":"a slow process"},{"phrase":"learning process"}]',NULL,'/ˈprɑːses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/process__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(268,'ngsl-1-07',28,'public','công cộng; công khai','adjective','[{"en":"Smoking is not allowed in public places.","vi":"Không được hút thuốc ở nơi công cộng."},{"en":"I usually take public transportation to work.","vi":"Tôi thường đi làm bằng phương tiện công cộng."},{"en":"The results will be made public next week.","vi":"Kết quả sẽ được công bố công khai vào tuần tới."}]','[{"phrase":"public transportation"},{"phrase":"public place"},{"phrase":"make public"},{"phrase":"in public"}]',NULL,'/ˈpʌblɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/public__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(269,'ngsl-1-07',29,'often','thường; hay','adverb','[{"en":"How often do you visit your grandparents?","vi":"Bạn có hay về thăm ông bà không?"},{"en":"I often forget where I put my keys.","vi":"Tôi hay quên mình để chìa khóa ở đâu."},{"en":"It doesn''t often snow here in winter.","vi":"Ở đây mùa đông ít khi có tuyết."}]','[{"phrase":"how often"},{"phrase":"quite often"},{"phrase":"very often"}]',NULL,'/ˈɔːfn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oft/often/often__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(270,'ngsl-1-07',30,'train','tàu hỏa; chuyến tàu','noun','[{"en":"We took the train from the city to the coast.","vi":"Chúng tôi đi tàu hỏa từ thành phố ra vùng biển."},{"en":"Hurry up, or we''ll miss the train!","vi":"Nhanh lên, không thì chúng ta sẽ lỡ chuyến tàu mất!"},{"en":"The next train to the airport leaves in ten minutes.","vi":"Chuyến tàu tiếp theo đi sân bay sẽ khởi hành sau mười phút nữa."}]','[{"phrase":"take the train"},{"phrase":"miss the train"},{"phrase":"by train"},{"phrase":"train station"}]',NULL,'/treɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/train/train__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(271,'ngsl-1-08',1,'possible','có thể; khả thi','adjective','[{"en":"Could you please send me the report as soon as possible?","vi":"Bạn có thể gửi cho tôi bản báo cáo sớm nhất có thể không?"},{"en":"Is it possible to change my flight to Friday?","vi":"Có thể đổi chuyến bay của tôi sang thứ Sáu không?"},{"en":"Without your help, this project would not have been possible.","vi":"Nếu không có sự giúp đỡ của bạn, dự án này đã không thể thực hiện được."}]','[{"phrase":"as soon as possible"},{"phrase":"if possible"},{"phrase":"possible solution"}]',NULL,'/ˈpɑːsəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/possi/possible__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(272,'ngsl-1-08',2,'actually','thật ra; thực sự','adverb','[{"en":"I thought the test would be hard, but it was actually easy.","vi":"Tôi tưởng bài kiểm tra sẽ khó, nhưng thật ra nó lại dễ."},{"en":"Nobody knows what actually happened at the party last night.","vi":"Không ai biết thực sự đã xảy ra chuyện gì ở bữa tiệc tối qua."},{"en":"Actually, I don''t think we have met before.","vi":"Thật ra, tôi không nghĩ là chúng ta đã gặp nhau trước đây."}]','[{"phrase":"what actually happened"},{"phrase":"actually happen"}]','actually = thật ra, KHÔNG có nghĩa là "hiện nay" (currently)','/ˈæktʃuəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actua/actually__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(273,'ngsl-1-08',3,'rather','khá; thà (… còn hơn); thay vì','adverb','[{"en":"I''d rather stay home tonight than go out in the rain.","vi":"Tối nay tôi thà ở nhà còn hơn ra ngoài dưới trời mưa."},{"en":"The hotel room was rather small, but it was clean.","vi":"Phòng khách sạn khá nhỏ, nhưng sạch sẽ."},{"en":"Let''s take the train rather than drive into the city.","vi":"Chúng ta hãy đi tàu thay vì lái xe vào thành phố."}]','[{"phrase":"would rather"},{"phrase":"rather than"},{"phrase":"rather difficult"}]','would rather + V nguyên mẫu; rather than = thay vì','/ˈræðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/rathe/rather__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(274,'ngsl-1-08',4,'view','quan điểm; quang cảnh, tầm nhìn','noun','[{"en":"Our room had a beautiful view of the sea.","vi":"Phòng của chúng tôi có tầm nhìn ra biển rất đẹp."},{"en":"In my view, children should spend less time on their phones.","vi":"Theo quan điểm của tôi, trẻ em nên dành ít thời gian cho điện thoại hơn."},{"en":"We have different views on how to raise our kids.","vi":"Chúng tôi có quan điểm khác nhau về cách nuôi dạy con cái."}]','[{"phrase":"point of view"},{"phrase":"in my view"},{"phrase":"beautiful view"}]',NULL,'/vjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vie/view_/view__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(275,'ngsl-1-08',5,'together','cùng nhau; với nhau','adverb','[{"en":"My sister and I work together at the same hospital.","vi":"Tôi và chị gái cùng làm việc ở một bệnh viện."},{"en":"Why don''t we have dinner together this weekend?","vi":"Sao chúng ta không cùng nhau ăn tối vào cuối tuần này nhỉ?"},{"en":"Mix the flour and sugar together in a large bowl.","vi":"Trộn bột mì và đường với nhau trong một cái bát lớn."}]','[{"phrase":"work together"},{"phrase":"get together"},{"phrase":"live together"}]',NULL,'/təˈɡeðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tog/toget/together__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(276,'ngsl-1-08',6,'consider','cân nhắc, xem xét; coi là','verb','[{"en":"We are considering moving to a bigger apartment.","vi":"Chúng tôi đang cân nhắc chuyển đến một căn hộ lớn hơn."},{"en":"Please consider all the options before you make a decision.","vi":"Hãy xem xét tất cả các lựa chọn trước khi đưa ra quyết định."},{"en":"Many people consider him the best teacher in our school.","vi":"Nhiều người coi thầy ấy là giáo viên giỏi nhất trường chúng tôi."}]','[{"phrase":"consider the options"},{"phrase":"seriously consider"},{"phrase":"consider carefully"}]','consider + V-ing (consider moving)','/kənˈsɪdər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsider__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(277,'ngsl-1-08',7,'price','giá, giá cả','noun','[{"en":"The price of fresh vegetables has gone up this month.","vi":"Giá rau tươi đã tăng trong tháng này."},{"en":"Excuse me, what is the price of this jacket?","vi":"Xin lỗi, chiếc áo khoác này giá bao nhiêu?"},{"en":"They sell good food at very reasonable prices.","vi":"Họ bán đồ ăn ngon với giá rất phải chăng."}]','[{"phrase":"reasonable price"},{"phrase":"high price"},{"phrase":"full price"}]',NULL,'/praɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/price/price__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(278,'ngsl-1-08',8,'parent','cha hoặc mẹ; bố mẹ; phụ huynh','noun','[{"en":"My parents live in a small village near the coast.","vi":"Bố mẹ tôi sống ở một ngôi làng nhỏ gần bờ biển."},{"en":"She raised three children as a single parent.","vi":"Cô ấy là mẹ đơn thân nuôi ba đứa con."},{"en":"The teacher called a meeting with parents after school.","vi":"Giáo viên đã mời phụ huynh đến họp sau giờ học."}]','[{"phrase":"single parent"},{"phrase":"working parents"},{"phrase":"new parents"}]',NULL,'/ˈperənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/paren/parent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(279,'ngsl-1-08',9,'hard','khó; cứng; vất vả, khó khăn','adjective','[{"en":"It''s hard to believe that summer is almost over.","vi":"Thật khó tin là mùa hè sắp hết rồi."},{"en":"This mattress is too hard for me to sleep on.","vi":"Tấm nệm này cứng quá, tôi nằm ngủ không được."},{"en":"It has been a hard year for our family.","vi":"Đây là một năm khó khăn đối với gia đình chúng tôi."}]','[{"phrase":"hard to believe"},{"phrase":"hard time"},{"phrase":"hard work"}]','work hard (chăm chỉ) ≠ hardly (hầu như không)','/hɑːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/har/hard_/hard__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(280,'ngsl-1-08',10,'party','bữa tiệc, buổi tiệc','noun','[{"en":"We''re having a birthday party for my son on Saturday.","vi":"Chúng tôi sẽ tổ chức tiệc sinh nhật cho con trai vào thứ Bảy."},{"en":"Are you going to the party after work tonight?","vi":"Tối nay bạn có đi dự tiệc sau giờ làm không?"},{"en":"Everyone had a great time at the party.","vi":"Mọi người đã rất vui ở bữa tiệc."}]','[{"phrase":"birthday party"},{"phrase":"have a party"},{"phrase":"throw a party"}]',NULL,'/ˈpɑːrti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/party/party__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(281,'ngsl-1-08',11,'local','(thuộc) địa phương; gần nhà','adjective','[{"en":"We buy our vegetables from the local market every morning.","vi":"Chúng tôi mua rau ở chợ gần nhà mỗi sáng."},{"en":"Many local people work in the hotels near the beach.","vi":"Nhiều người dân địa phương làm việc ở các khách sạn gần bãi biển."},{"en":"The accident was reported in the local newspaper.","vi":"Vụ tai nạn đã được đưa tin trên báo địa phương."}]','[{"phrase":"local people"},{"phrase":"local market"},{"phrase":"local newspaper"},{"phrase":"local time"}]',NULL,'/ˈləʊkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/local/local__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(282,'ngsl-1-08',12,'control','kiểm soát; điều khiển; kiềm chế','verb','[{"en":"She couldn''t control her anger and started shouting.","vi":"Cô ấy không kiềm chế được cơn giận và bắt đầu la hét."},{"en":"You can control the lights in the house with your phone.","vi":"Bạn có thể điều khiển đèn trong nhà bằng điện thoại."},{"en":"Regular exercise can help you control your weight.","vi":"Tập thể dục đều đặn có thể giúp bạn kiểm soát cân nặng."}]','[{"phrase":"control the situation"},{"phrase":"control costs"},{"phrase":"control your weight"}]','control – controlled – controlled (gấp đôi chữ l)','/kənˈtrəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrol__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(283,'ngsl-1-08',13,'already','đã … rồi; rồi','adverb','[{"en":"I''ve already eaten, but thanks for asking.","vi":"Tôi ăn rồi, nhưng cảm ơn bạn đã hỏi."},{"en":"By the time we arrived, the movie had already started.","vi":"Lúc chúng tôi đến thì phim đã bắt đầu rồi."},{"en":"It''s only March, but it already feels like summer.","vi":"Mới tháng Ba mà trời đã như mùa hè rồi."}]','[{"phrase":"already know"},{"phrase":"already started"},{"phrase":"already done"}]','already thường dùng trong câu khẳng định; câu phủ định dùng yet','/ɔːlˈredi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alr/alrea/already__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(284,'ngsl-1-08',14,'concern','mối lo ngại, sự lo lắng; mối quan tâm','noun','[{"en":"Safety is our main concern when choosing a car.","vi":"An toàn là mối quan tâm hàng đầu của chúng tôi khi chọn xe."},{"en":"Parents have raised concerns about the new school rules.","vi":"Phụ huynh đã bày tỏ lo ngại về nội quy mới của trường."},{"en":"There is growing concern about air pollution in big cities.","vi":"Mối lo ngại về ô nhiễm không khí ở các thành phố lớn ngày càng tăng."}]','[{"phrase":"main concern"},{"phrase":"raise concerns"},{"phrase":"growing concern"},{"phrase":"cause for concern"}]',NULL,'/kənˈsɜːrn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcern__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(285,'ngsl-1-08',15,'product','sản phẩm','noun','[{"en":"This shop sells only natural beauty products.","vi":"Cửa hàng này chỉ bán các sản phẩm làm đẹp tự nhiên."},{"en":"Our company is launching a new product next month.","vi":"Công ty chúng tôi sẽ ra mắt một sản phẩm mới vào tháng sau."},{"en":"If you''re not happy with the product, you can return it.","vi":"Nếu không hài lòng với sản phẩm, bạn có thể trả lại."}]','[{"phrase":"new product"},{"phrase":"launch a product"},{"phrase":"beauty products"}]',NULL,'/ˈprɑːdʌkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/product__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(286,'ngsl-1-08',16,'lose','mất, làm mất; thua; giảm (cân)','verb','[{"en":"I lost my keys somewhere on the way home.","vi":"Tôi đã làm mất chìa khóa ở đâu đó trên đường về nhà."},{"en":"Our team lost the match by two goals.","vi":"Đội chúng tôi đã thua trận với cách biệt hai bàn."},{"en":"He wants to lose weight before summer.","vi":"Anh ấy muốn giảm cân trước mùa hè."}]','[{"phrase":"lose weight"},{"phrase":"lose a game"},{"phrase":"lose your job"}]','lose – lost – lost; lose (v) ≠ loose (adj: lỏng)','/luːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/los/lose_/lose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(287,'ngsl-1-08',17,'story','câu chuyện; truyện','noun','[{"en":"My grandmother used to tell me stories before bed.","vi":"Bà tôi thường kể chuyện cho tôi nghe trước khi đi ngủ."},{"en":"It''s a long story, so I''ll tell you later.","vi":"Chuyện dài lắm, để sau tôi kể cho bạn nghe."},{"en":"She has written several short stories for children.","vi":"Cô ấy đã viết một vài truyện ngắn cho trẻ em."}]','[{"phrase":"tell a story"},{"phrase":"short story"},{"phrase":"long story"},{"phrase":"true story"}]',NULL,'/ˈstɔːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/story/story__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(288,'ngsl-1-08',18,'almost','gần như, hầu như; suýt','adverb','[{"en":"Dinner is almost ready, so please wash your hands.","vi":"Bữa tối gần xong rồi, mọi người đi rửa tay nhé."},{"en":"I almost missed the bus this morning.","vi":"Sáng nay tôi suýt lỡ chuyến xe buýt."},{"en":"Almost everyone in my class has a smartphone.","vi":"Hầu như ai trong lớp tôi cũng có điện thoại thông minh."}]','[{"phrase":"almost always"},{"phrase":"almost everyone"},{"phrase":"almost ready"}]',NULL,'/ˈɔːlməʊst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alm/almos/almost__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(289,'ngsl-1-08',19,'continue','tiếp tục','verb','[{"en":"After a short break, we continued our walk.","vi":"Sau khi nghỉ một lát, chúng tôi tiếp tục đi bộ."},{"en":"House prices in the city continue to rise every year.","vi":"Giá nhà ở thành phố tiếp tục tăng mỗi năm."},{"en":"If the rain continues, the game will be canceled.","vi":"Nếu trời tiếp tục mưa, trận đấu sẽ bị hủy."}]','[{"phrase":"continue to rise"},{"phrase":"continue working"},{"phrase":"continue your studies"}]','continue + to V / V-ing','/kənˈtɪnjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontinue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(290,'ngsl-1-08',20,'stand','đứng; chịu đựng','verb','[{"en":"We had to stand in line for an hour to buy tickets.","vi":"Chúng tôi phải đứng xếp hàng một tiếng để mua vé."},{"en":"Please stand up when the teacher comes in.","vi":"Hãy đứng dậy khi giáo viên bước vào."},{"en":"I can''t stand the noise from the construction site next door.","vi":"Tôi không chịu nổi tiếng ồn từ công trường bên cạnh."}]','[{"phrase":"stand up"},{"phrase":"stand in line"},{"phrase":"can''t stand"}]','stand – stood – stood','/stænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stand/stand__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(291,'ngsl-1-08',21,'whole','toàn bộ, cả','adjective','[{"en":"I spent the whole day cleaning the house.","vi":"Tôi dành cả ngày để dọn dẹp nhà cửa."},{"en":"The whole family went to the beach for the weekend.","vi":"Cả gia đình đã đi biển vào cuối tuần."},{"en":"He ate the whole pizza by himself.","vi":"Anh ấy ăn hết cả cái bánh pizza một mình."}]','[{"phrase":"the whole day"},{"phrase":"the whole family"},{"phrase":"the whole world"},{"phrase":"the whole time"}]','whole ≠ hole (cái lỗ), phát âm giống nhau','/həʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/who/whole/whole__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(292,'ngsl-1-08',22,'yet','chưa; vẫn chưa; tuy nhiên','adverb','[{"en":"Have you finished your homework yet, or do you need more time?","vi":"Con đã làm xong bài tập chưa, hay cần thêm thời gian?"},{"en":"I haven''t heard back from the company yet.","vi":"Tôi vẫn chưa nhận được phản hồi từ công ty."},{"en":"The hotel was cheap, yet it was clean and comfortable.","vi":"Khách sạn rẻ, tuy vậy lại sạch sẽ và thoải mái."}]','[{"phrase":"not yet"},{"phrase":"yet another"},{"phrase":"have yet to"}]','yet (chưa) thường dùng trong câu hỏi và câu phủ định','/jet/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yet/yet__/yet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(293,'ngsl-1-08',23,'rate','tỷ lệ; tốc độ; mức giá','noun','[{"en":"The birth rate has fallen in many countries.","vi":"Tỷ lệ sinh đã giảm ở nhiều quốc gia."},{"en":"The city is growing at a fast rate.","vi":"Thành phố đang phát triển với tốc độ nhanh."},{"en":"The hotel offers special rates for students.","vi":"Khách sạn có mức giá ưu đãi cho sinh viên."}]','[{"phrase":"birth rate"},{"phrase":"interest rate"},{"phrase":"exchange rate"},{"phrase":"heart rate"}]',NULL,'/reɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/rate_/rate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(294,'ngsl-1-08',24,'care','quan tâm; chăm sóc','verb','[{"en":"I don''t care what other people think of me.","vi":"Tôi không quan tâm người khác nghĩ gì về mình."},{"en":"She really cares about protecting the environment.","vi":"Cô ấy thực sự quan tâm đến việc bảo vệ môi trường."},{"en":"Nurses care for patients day and night.","vi":"Các y tá chăm sóc bệnh nhân cả ngày lẫn đêm."}]','[{"phrase":"care about"},{"phrase":"care for"},{"phrase":"don''t care"}]','care about (quan tâm) · care for (chăm sóc)','/ker/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/care_/care__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(295,'ngsl-1-08',25,'expect','mong đợi; dự kiến; chờ (ai đến)','verb','[{"en":"We expect the package to arrive by Friday.","vi":"Chúng tôi dự kiến gói hàng sẽ đến trước thứ Sáu."},{"en":"The trip cost much more than expected.","vi":"Chuyến đi tốn kém hơn nhiều so với dự kiến."},{"en":"Are you expecting any visitors this afternoon?","vi":"Chiều nay bạn có đang chờ khách nào không?"}]','[{"phrase":"than expected"},{"phrase":"as expected"},{"phrase":"expect a baby"}]',NULL,'/ɪkˈspekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expec/expect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(296,'ngsl-1-08',26,'effect','ảnh hưởng, tác động; tác dụng; hiệu lực','noun','[{"en":"Too much sugar has a bad effect on your teeth.","vi":"Quá nhiều đường có ảnh hưởng xấu đến răng của bạn."},{"en":"This medicine may have some side effects.","vi":"Thuốc này có thể có một số tác dụng phụ."},{"en":"The new rules will take effect next month.","vi":"Các quy định mới sẽ có hiệu lực từ tháng sau."}]','[{"phrase":"side effect"},{"phrase":"have an effect on"},{"phrase":"take effect"}]','effect (n) ≠ affect (v)','/ɪˈfekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effec/effect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(297,'ngsl-1-08',27,'sort','loại, kiểu','noun','[{"en":"What sort of music do you like?","vi":"Bạn thích loại nhạc nào?"},{"en":"This is the sort of place I''d love to live in.","vi":"Đây chính là kiểu nơi tôi rất muốn được sống."},{"en":"The shop sells all sorts of things for the kitchen.","vi":"Cửa hàng bán đủ loại đồ dùng cho nhà bếp."}]','[{"phrase":"what sort of"},{"phrase":"all sorts of"},{"phrase":"sort of"}]','sort of (thân mật) = hơi, kiểu như','/sɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sor/sort_/sort__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(298,'ngsl-1-08',28,'ever','từng, đã bao giờ; mãi mãi','adverb','[{"en":"Have you ever been abroad on your own?","vi":"Bạn đã bao giờ tự đi nước ngoài một mình chưa?"},{"en":"This is the best coffee I''ve ever had.","vi":"Đây là ly cà phê ngon nhất tôi từng uống."},{"en":"They got married and lived happily ever after.","vi":"Họ kết hôn và sống hạnh phúc mãi mãi về sau."}]','[{"phrase":"have you ever"},{"phrase":"ever since"},{"phrase":"than ever"}]',NULL,'/ˈevər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/ever_/ever__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(299,'ngsl-1-08',29,'anything','bất cứ thứ gì; (câu hỏi, phủ định) gì','pronoun','[{"en":"Is there anything else I can help you with?","vi":"Còn gì khác tôi có thể giúp bạn không?"},{"en":"I didn''t eat anything for breakfast this morning.","vi":"Sáng nay tôi không ăn sáng gì cả."},{"en":"You can order anything you like from the menu.","vi":"Bạn có thể gọi bất cứ món gì bạn thích trong thực đơn."}]','[{"phrase":"anything else"},{"phrase":"do anything"},{"phrase":"anything at all"}]','câu hỏi/phủ định: gì; câu khẳng định: bất cứ thứ gì','/ˈeniθɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anyth/anything__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(300,'ngsl-1-08',30,'cause','gây ra, làm cho','verb','[{"en":"Heavy rain caused flooding in several parts of the city.","vi":"Mưa lớn đã gây ngập lụt ở nhiều khu vực trong thành phố."},{"en":"I''m sorry for causing so much trouble.","vi":"Tôi xin lỗi vì đã gây ra nhiều rắc rối như vậy."},{"en":"Smoking can cause serious health problems later in life.","vi":"Hút thuốc có thể gây ra các vấn đề sức khỏe nghiêm trọng về sau."}]','[{"phrase":"cause problems"},{"phrase":"cause damage"},{"phrase":"cause trouble"}]',NULL,'/kɔːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cau/cause/cause__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(301,'ngsl-1-09',1,'fall','rơi; ngã; giảm','verb','[{"en":"Be careful on the stairs so you don''t fall.","vi":"Cẩn thận trên cầu thang kẻo bạn bị ngã."},{"en":"A lot of leaves fell from the trees last night.","vi":"Tối qua rất nhiều lá rơi khỏi cây."},{"en":"House prices have fallen a little this year.","vi":"Giá nhà năm nay đã giảm một chút."}]','[{"phrase":"fall asleep"},{"phrase":"fall down"},{"phrase":"fall off"},{"phrase":"prices fall"}]','fall – fell – fallen','/fɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fal/fall_/fall__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(302,'ngsl-1-09',2,'deal','thỏa thuận; giao dịch; món hời','noun','[{"en":"We finally made a deal with the new supplier.","vi":"Cuối cùng chúng tôi đã đạt được thỏa thuận với nhà cung cấp mới."},{"en":"I got a really good deal on this laptop.","vi":"Tôi mua được chiếc máy tính xách tay này với giá rất hời."},{"en":"The two companies signed a business deal last week.","vi":"Tuần trước hai công ty đã ký một thỏa thuận kinh doanh."}]','[{"phrase":"make a deal"},{"phrase":"good deal"},{"phrase":"business deal"},{"phrase":"sign a deal"}]','a great deal of = rất nhiều','/diːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/deal_/deal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(303,'ngsl-1-09',3,'water','nước','noun','[{"en":"Could I have a glass of water, please?","vi":"Cho tôi xin một cốc nước được không?"},{"en":"You should drink plenty of water on hot days.","vi":"Bạn nên uống nhiều nước vào những ngày nóng."},{"en":"The water in the lake was too cold for swimming.","vi":"Nước hồ quá lạnh để bơi."}]','[{"phrase":"glass of water"},{"phrase":"drink water"},{"phrase":"hot water"},{"phrase":"cold water"}]','không đếm được','/ˈwɔːtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wat/water/water__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(304,'ngsl-1-09',4,'send','gửi','verb','[{"en":"I''ll send you the photos from the trip tonight.","vi":"Tối nay tôi sẽ gửi cho bạn ảnh chuyến đi."},{"en":"She sent a birthday card to her grandmother.","vi":"Cô ấy đã gửi một tấm thiếp sinh nhật cho bà."},{"en":"Please send me an email when you arrive.","vi":"Khi nào đến nơi thì gửi email cho tôi nhé."}]','[{"phrase":"send an email"},{"phrase":"send a message"},{"phrase":"send a letter"}]','send – sent – sent','/send/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/send_/send__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(305,'ngsl-1-09',5,'allow','cho phép','verb','[{"en":"My parents didn''t allow me to stay out late.","vi":"Bố mẹ không cho phép tôi đi chơi về khuya."},{"en":"Smoking is not allowed inside the building.","vi":"Không được phép hút thuốc trong tòa nhà."},{"en":"The new app allows you to pay with your phone.","vi":"Ứng dụng mới cho phép bạn thanh toán bằng điện thoại."}]','[{"phrase":"allow someone to"},{"phrase":"be allowed to"},{"phrase":"not allowed"}]','allow sb to do sth','/əˈlaʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/allow/allow__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(306,'ngsl-1-09',6,'soon','sớm; chẳng bao lâu nữa','adverb','[{"en":"Dinner will be ready soon, so please wash your hands.","vi":"Bữa tối sắp xong rồi, nên đi rửa tay đi nhé."},{"en":"I really hope you feel better soon.","vi":"Mình thật sự mong bạn sớm khỏe lại."},{"en":"We left soon after the movie ended.","vi":"Chúng tôi ra về ngay sau khi phim kết thúc."}]','[{"phrase":"as soon as possible"},{"phrase":"see you soon"},{"phrase":"soon after"}]',NULL,'/suːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soo/soon_/soon__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(307,'ngsl-1-09',7,'watch','xem; theo dõi; trông chừng','verb','[{"en":"We watched a movie together after dinner.","vi":"Sau bữa tối chúng tôi cùng nhau xem một bộ phim."},{"en":"The kids love watching the birds in the garden.","vi":"Bọn trẻ rất thích ngắm chim trong vườn."},{"en":"Could you watch my bag while I buy a ticket?","vi":"Bạn trông giúp túi của tôi trong lúc tôi đi mua vé được không?"}]','[{"phrase":"watch TV"},{"phrase":"watch a movie"},{"phrase":"watch carefully"}]',NULL,'/wɑːtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wat/watch/watch__us_6.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(308,'ngsl-1-09',8,'base','dựa vào; đặt trụ sở','verb','[{"en":"The movie is based on a true story.","vi":"Bộ phim dựa trên một câu chuyện có thật."},{"en":"Our company is based in a small town near the coast.","vi":"Công ty chúng tôi đặt trụ sở ở một thị trấn nhỏ gần bờ biển."},{"en":"She based her decision on what her customers wanted.","vi":"Cô ấy đưa ra quyết định dựa vào những gì khách hàng muốn."}]','[{"phrase":"based on"},{"phrase":"be based in"},{"phrase":"base a decision on"}]','base sth on sth; be based in + nơi chốn','/beɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/base_/base__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(309,'ngsl-1-09',9,'probably','có lẽ; chắc là','adverb','[{"en":"It will probably rain this afternoon, so take an umbrella.","vi":"Có lẽ chiều nay trời sẽ mưa, nên hãy mang theo ô."},{"en":"She''s probably still at work right now.","vi":"Giờ này chắc cô ấy vẫn đang ở chỗ làm."},{"en":"That was probably the best meal I''ve ever had.","vi":"Đó có lẽ là bữa ăn ngon nhất tôi từng ăn."}]','[{"phrase":"will probably"},{"phrase":"most probably"},{"phrase":"probably not"}]',NULL,'/ˈprɑːbəbli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proba/probably__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(310,'ngsl-1-09',10,'suggest','gợi ý; đề nghị; cho thấy','verb','[{"en":"My friend suggested a good restaurant near the station.","vi":"Bạn tôi đã gợi ý một nhà hàng ngon gần nhà ga."},{"en":"I suggest leaving early to avoid the traffic.","vi":"Tôi đề nghị đi sớm để tránh kẹt xe."},{"en":"The results suggest that the plan is working.","vi":"Kết quả cho thấy kế hoạch đang có hiệu quả."}]','[{"phrase":"suggest an idea"},{"phrase":"strongly suggest"},{"phrase":"suggest that"}]','suggest + V-ing / suggest that…; không dùng suggest sb to do','/səˈdʒest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sug/sugge/suggest__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(311,'ngsl-1-09',11,'past','quá khứ','noun','[{"en":"In the past, people wrote letters instead of emails.","vi":"Ngày xưa, người ta viết thư tay thay vì gửi email."},{"en":"He doesn''t like to talk about his past.","vi":"Anh ấy không thích nói về quá khứ của mình."},{"en":"Let''s forget the past and start again.","vi":"Hãy quên quá khứ đi và bắt đầu lại."}]','[{"phrase":"in the past"},{"phrase":"the recent past"},{"phrase":"forget the past"}]',NULL,'/pæst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/past_/past__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(312,'ngsl-1-09',12,'power','quyền lực; năng lượng; điện','noun','[{"en":"Parents have a lot of power over their young children.","vi":"Cha mẹ có nhiều quyền lực đối với con cái còn nhỏ."},{"en":"More homes in the area now use solar power.","vi":"Giờ đây ngày càng nhiều nhà trong khu vực dùng năng lượng mặt trời."},{"en":"The power went out during the storm last night.","vi":"Tối qua bị mất điện trong lúc có bão."}]','[{"phrase":"solar power"},{"phrase":"power outage"},{"phrase":"have the power to"}]',NULL,'/ˈpaʊər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pow/power/power__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(313,'ngsl-1-09',13,'test','bài kiểm tra; kỳ thi; xét nghiệm','noun','[{"en":"I have a math test tomorrow morning.","vi":"Sáng mai tôi có bài kiểm tra toán."},{"en":"She passed her driving test on the first try.","vi":"Cô ấy đã thi đỗ bằng lái xe ngay lần đầu."},{"en":"The doctor wants me to have a blood test.","vi":"Bác sĩ muốn tôi đi xét nghiệm máu."}]','[{"phrase":"take a test"},{"phrase":"pass a test"},{"phrase":"driving test"},{"phrase":"blood test"}]',NULL,'/test/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tes/test_/test__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(314,'ngsl-1-09',14,'visit','thăm; đến thăm; tham quan','verb','[{"en":"We visit my grandparents every Sunday.","vi":"Chủ nhật nào chúng tôi cũng đi thăm ông bà."},{"en":"Millions of tourists visit the city each year.","vi":"Mỗi năm có hàng triệu du khách đến tham quan thành phố."},{"en":"Have you ever visited the old part of town?","vi":"Bạn đã từng đến khu phố cổ chưa?"}]','[{"phrase":"visit a friend"},{"phrase":"visit a museum"},{"phrase":"visit the doctor"}]',NULL,'/ˈvɪzɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visit/visit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(315,'ngsl-1-09',15,'center','trung tâm; chính giữa','noun','[{"en":"Our hotel is right in the city center.","vi":"Khách sạn của chúng tôi nằm ngay trung tâm thành phố."},{"en":"There''s a big shopping center near my office.","vi":"Gần văn phòng tôi có một trung tâm mua sắm lớn."},{"en":"Put the vase in the center of the table.","vi":"Đặt cái bình ở chính giữa bàn nhé."}]','[{"phrase":"city center"},{"phrase":"shopping center"},{"phrase":"in the center of"}]','Mỹ: center · Anh: centre','/ˈsentər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/centr/centre__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(316,'ngsl-1-09',16,'grow','lớn lên; trồng; tăng lên','verb','[{"en":"Children grow so fast at this age.","vi":"Ở tuổi này trẻ con lớn nhanh lắm."},{"en":"My mother grows tomatoes in the backyard.","vi":"Mẹ tôi trồng cà chua ở sân sau."},{"en":"The number of online shoppers has grown quickly.","vi":"Số người mua sắm trực tuyến đã tăng lên nhanh chóng."}]','[{"phrase":"grow up"},{"phrase":"grow vegetables"},{"phrase":"grow quickly"}]','grow – grew – grown','/ɡrəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/grow_/grow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(317,'ngsl-1-09',17,'nothing','không có gì; không cái gì','pronoun','[{"en":"There''s nothing in the fridge, so let''s order food.","vi":"Tủ lạnh chẳng có gì, nên mình gọi đồ ăn đi."},{"en":"I have nothing to do this weekend.","vi":"Cuối tuần này tôi không có việc gì làm."},{"en":"She said nothing about the problem at the meeting.","vi":"Trong cuộc họp cô ấy không nói gì về vấn đề đó."}]','[{"phrase":"nothing else"},{"phrase":"nothing special"},{"phrase":"have nothing to do"}]',NULL,'/ˈnʌθɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/nothi/nothing__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(318,'ngsl-1-09',18,'return','trở về; trả lại','verb','[{"en":"He returned home after three years abroad.","vi":"Anh ấy trở về nhà sau ba năm ở nước ngoài."},{"en":"Please return the books to the library by Friday.","vi":"Vui lòng trả sách cho thư viện trước thứ Sáu."},{"en":"I''ll return your call as soon as I can.","vi":"Tôi sẽ gọi lại cho bạn ngay khi có thể."}]','[{"phrase":"return home"},{"phrase":"return a call"},{"phrase":"return from"}]','không nói return back','/rɪˈtɜːrn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retur/return__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(319,'ngsl-1-09',19,'mother','mẹ','noun','[{"en":"My mother taught me how to cook.","vi":"Mẹ đã dạy tôi nấu ăn."},{"en":"She became a mother at the age of thirty.","vi":"Cô ấy làm mẹ ở tuổi ba mươi."},{"en":"Does your mother still live in the same house?","vi":"Mẹ bạn vẫn sống ở ngôi nhà cũ chứ?"}]','[{"phrase":"young mother"},{"phrase":"working mother"},{"phrase":"mother and father"}]',NULL,'/ˈmʌðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/mothe/mother__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(320,'ngsl-1-09',20,'walk','đi bộ; dắt đi dạo','verb','[{"en":"I usually walk to work when the weather is nice.","vi":"Khi trời đẹp tôi thường đi bộ đi làm."},{"en":"They walked along the beach for an hour.","vi":"Họ đi bộ dọc bãi biển suốt một tiếng."},{"en":"Can you walk the dog before dinner?","vi":"Bạn dắt chó đi dạo trước bữa tối được không?"}]','[{"phrase":"walk home"},{"phrase":"walk to work"},{"phrase":"walk the dog"}]',NULL,'/wɔːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wal/walk_/walk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(321,'ngsl-1-09',21,'matter','quan trọng; có ý nghĩa','verb','[{"en":"It doesn''t matter if you''re a few minutes late.","vi":"Bạn đến trễ vài phút cũng không sao."},{"en":"Your health matters more than your job.","vi":"Sức khỏe của bạn quan trọng hơn công việc."},{"en":"Does it really matter what other people think?","vi":"Người khác nghĩ gì thì có thực sự quan trọng không?"}]','[{"phrase":"it doesn''t matter"},{"phrase":"really matter"},{"phrase":"matter to someone"}]','What''s the matter? = Có chuyện gì vậy?','/ˈmætər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/matte/matter__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(322,'ngsl-1-09',22,'mind','tâm trí; đầu óc; ý định','noun','[{"en":"I was going to buy the red one, but I changed my mind.","vi":"Tôi định mua cái màu đỏ nhưng rồi đổi ý."},{"en":"A short walk helps me clear my mind.","vi":"Đi bộ một chút giúp đầu óc tôi thư thái."},{"en":"Keep in mind that the store closes early today.","vi":"Hãy nhớ rằng hôm nay cửa hàng đóng cửa sớm."}]','[{"phrase":"change your mind"},{"phrase":"make up your mind"},{"phrase":"keep in mind"}]','Do you mind…? = Bạn có phiền…?','/maɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/mind_/mind__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(323,'ngsl-1-09',23,'value','giá trị','noun','[{"en":"The value of the house has doubled in ten years.","vi":"Giá trị căn nhà đã tăng gấp đôi trong mười năm."},{"en":"This old watch has great value to my family.","vi":"Chiếc đồng hồ cũ này rất có giá trị với gia đình tôi."},{"en":"Parents try to teach their children good values.","vi":"Cha mẹ cố gắng dạy con những giá trị tốt đẹp."}]','[{"phrase":"the value of"},{"phrase":"great value"},{"phrase":"market value"}]',NULL,'/ˈvæljuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/value/value__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(324,'ngsl-1-09',24,'office','văn phòng','noun','[{"en":"I''ll be at the office until six today.","vi":"Hôm nay tôi ở văn phòng đến sáu giờ."},{"en":"Our office is on the fifth floor.","vi":"Văn phòng của chúng tôi ở tầng năm."},{"en":"She works in a small office downtown.","vi":"Cô ấy làm việc ở một văn phòng nhỏ trong trung tâm thành phố."}]','[{"phrase":"office building"},{"phrase":"head office"},{"phrase":"at the office"}]',NULL,'/ˈɑːfɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offic/office__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(325,'ngsl-1-09',25,'record','hồ sơ; bản ghi chép; kỷ lục','noun','[{"en":"The hospital keeps records of every patient.","vi":"Bệnh viện lưu hồ sơ của mọi bệnh nhân."},{"en":"Please keep a record of how much you spend.","vi":"Hãy ghi chép lại số tiền bạn đã tiêu."},{"en":"She broke the school record for the long jump.","vi":"Cô ấy đã phá kỷ lục nhảy xa của trường."}]','[{"phrase":"keep a record"},{"phrase":"break a record"},{"phrase":"medical records"},{"phrase":"world record"}]','danh từ nhấn âm đầu (RE-cord); động từ nhấn âm sau (re-CORD)','/ˈrekərd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recor/record__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(326,'ngsl-1-09',26,'stay','ở lại; lưu lại; giữ','verb','[{"en":"I stayed at home all day because of the rain.","vi":"Tôi ở nhà cả ngày vì trời mưa."},{"en":"We stayed in a small hotel near the beach.","vi":"Chúng tôi ở một khách sạn nhỏ gần bãi biển."},{"en":"Try to stay calm during the exam.","vi":"Hãy cố gắng giữ bình tĩnh trong lúc thi."}]','[{"phrase":"stay at home"},{"phrase":"stay in a hotel"},{"phrase":"stay calm"},{"phrase":"stay up late"}]',NULL,'/steɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stay_/stay__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(327,'ngsl-1-09',27,'force','buộc; ép','verb','[{"en":"Heavy rain forced us to cancel the picnic.","vi":"Mưa to buộc chúng tôi phải hủy buổi dã ngoại."},{"en":"Nobody forced you to take this job.","vi":"Không ai ép bạn nhận công việc này cả."},{"en":"The shop was forced to close after ten years.","vi":"Cửa hàng buộc phải đóng cửa sau mười năm."}]','[{"phrase":"force someone to"},{"phrase":"be forced to"}]','force sb to do sth','/fɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/force/force__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(328,'ngsl-1-09',28,'stop','dừng; ngừng','verb','[{"en":"The bus stops right in front of my house.","vi":"Xe buýt dừng ngay trước nhà tôi."},{"en":"Please stop talking and listen to me.","vi":"Làm ơn ngừng nói chuyện và nghe tôi nói."},{"en":"It finally stopped raining at around midnight.","vi":"Khoảng nửa đêm thì trời cuối cùng cũng tạnh mưa."}]','[{"phrase":"stop talking"},{"phrase":"stop working"},{"phrase":"stop raining"}]','stop + V-ing = ngừng làm; stop + to V = dừng lại để làm','/stɑːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stop_/stop__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(329,'ngsl-1-09',29,'several','vài; một số','determiner','[{"en":"I''ve been to that café several times.","vi":"Tôi đã đến quán cà phê đó vài lần."},{"en":"Several students were late for class this morning.","vi":"Sáng nay có một số học sinh đi học muộn."},{"en":"She lived in Japan for several years.","vi":"Cô ấy đã sống ở Nhật Bản vài năm."}]','[{"phrase":"several times"},{"phrase":"several years"},{"phrase":"several people"}]',NULL,'/ˈsevrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sev/sever/several__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(330,'ngsl-1-09',30,'light','ánh sáng; đèn','noun','[{"en":"Don''t forget to turn off the lights when you leave.","vi":"Đừng quên tắt đèn khi ra ngoài."},{"en":"This room gets a lot of light in the morning.","vi":"Buổi sáng căn phòng này có rất nhiều ánh sáng."},{"en":"Turn left at the next traffic light.","vi":"Rẽ trái ở cột đèn giao thông tiếp theo."}]','[{"phrase":"turn on the light"},{"phrase":"turn off the light"},{"phrase":"bright light"},{"phrase":"traffic light"}]',NULL,'/laɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lig/light/light__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(331,'ngsl-1-10',1,'develop','phát triển; xây dựng, tạo ra','verb','[{"en":"Children develop very quickly in their first few years.","vi":"Trẻ em phát triển rất nhanh trong vài năm đầu đời."},{"en":"Our team is developing a new app for students.","vi":"Nhóm chúng tôi đang xây dựng một ứng dụng mới cho sinh viên."},{"en":"She developed a strong interest in music at school.","vi":"Cô ấy dần có niềm đam mê lớn với âm nhạc khi còn đi học."}]','[{"phrase":"develop skills"},{"phrase":"develop a plan"},{"phrase":"develop a product"}]',NULL,'/dɪˈveləp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devel/develop__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(332,'ngsl-1-10',2,'remember','nhớ; ghi nhớ','verb','[{"en":"Do you remember the name of that restaurant?","vi":"Bạn có nhớ tên nhà hàng đó không?"},{"en":"I can''t remember where I put my keys.","vi":"Tôi không nhớ mình để chìa khóa ở đâu."},{"en":"Remember to lock the door when you leave.","vi":"Nhớ khóa cửa khi bạn ra ngoài nhé."}]','[{"phrase":"remember the name"},{"phrase":"can''t remember"},{"phrase":"remember clearly"}]','remember to do (nhớ để làm) ≠ remember doing (nhớ đã làm)','/rɪˈmembər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remem/remember__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(333,'ngsl-1-10',3,'bit','một chút; mẩu, miếng nhỏ','noun','[{"en":"I''m a bit tired after the long trip.","vi":"Tôi hơi mệt một chút sau chuyến đi dài."},{"en":"Let''s wait a bit longer for the rain to stop.","vi":"Mình đợi thêm một chút cho mưa tạnh đã."},{"en":"She gave the dog a bit of her sandwich.","vi":"Cô ấy cho con chó một mẩu bánh mì kẹp của mình."}]','[{"phrase":"a bit"},{"phrase":"a little bit"},{"phrase":"a bit of"},{"phrase":"bit by bit"}]',NULL,'/bɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bit/bit__/bit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(334,'ngsl-1-10',4,'share','chia sẻ; dùng chung','verb','[{"en":"I share a small apartment with two friends.","vi":"Tôi ở chung một căn hộ nhỏ với hai người bạn."},{"en":"Thanks for sharing your ideas at the meeting.","vi":"Cảm ơn bạn đã chia sẻ ý tưởng trong cuộc họp."},{"en":"We shared a pizza and watched a movie.","vi":"Chúng tôi ăn chung một chiếc pizza và xem phim."}]','[{"phrase":"share a room"},{"phrase":"share ideas"},{"phrase":"share information"},{"phrase":"share with"}]',NULL,'/ʃer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/share/share__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(335,'ngsl-1-10',5,'real','thật; thực sự','adjective','[{"en":"Is that a real diamond or just glass?","vi":"Đó là kim cương thật hay chỉ là thủy tinh?"},{"en":"The real problem is that we don''t have enough time.","vi":"Vấn đề thực sự là chúng ta không có đủ thời gian."},{"en":"He looks much younger in real life than on TV.","vi":"Ngoài đời thật, anh ấy trông trẻ hơn nhiều so với trên TV."}]','[{"phrase":"real life"},{"phrase":"the real world"},{"phrase":"real problem"}]',NULL,'/ˈriːəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/real_/real__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(336,'ngsl-1-10',6,'answer','câu trả lời; đáp án','noun','[{"en":"I asked him a question, but he didn''t give an answer.","vi":"Tôi hỏi anh ấy một câu, nhưng anh ấy không trả lời."},{"en":"Check your answers before you hand in the test.","vi":"Hãy kiểm tra lại các câu trả lời trước khi nộp bài kiểm tra."},{"en":"Nobody knows the answer to this problem yet.","vi":"Chưa ai biết lời giải cho vấn đề này."}]','[{"phrase":"the right answer"},{"phrase":"give an answer"},{"phrase":"answer to"}]',NULL,'/ˈænsər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ans/answe/answer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(337,'ngsl-1-10',7,'sit','ngồi','verb','[{"en":"Please sit down and make yourself comfortable.","vi":"Mời bạn ngồi xuống và cứ tự nhiên nhé."},{"en":"We sat by the window and watched the rain.","vi":"Chúng tôi ngồi cạnh cửa sổ và ngắm mưa."},{"en":"My grandfather likes sitting in the garden after lunch.","vi":"Ông tôi thích ngồi ngoài vườn sau bữa trưa."}]','[{"phrase":"sit down"},{"phrase":"sit next to"},{"phrase":"sit by the window"}]','sit – sat – sat','/sɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/sit__/sit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(338,'ngsl-1-10',8,'figure','con số, số liệu; nhân vật; bóng người, dáng người','noun','[{"en":"The sales figures for this month look much better.","vi":"Số liệu bán hàng tháng này trông khả quan hơn nhiều."},{"en":"She is an important figure in the local art world.","vi":"Bà ấy là một nhân vật quan trọng trong giới nghệ thuật địa phương."},{"en":"I saw a dark figure standing near the gate.","vi":"Tôi thấy một bóng người đứng gần cổng."}]','[{"phrase":"sales figures"},{"phrase":"key figure"},{"phrase":"official figures"}]',NULL,'/ˈfɪɡjər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fig/figur/figure__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(339,'ngsl-1-10',9,'letter','lá thư; chữ cái','noun','[{"en":"I got a letter from my old teacher today.","vi":"Hôm nay tôi nhận được thư của thầy giáo cũ."},{"en":"Please write your name in capital letters.","vi":"Vui lòng viết tên của bạn bằng chữ in hoa."},{"en":"My grandmother still writes letters to her friends.","vi":"Bà tôi vẫn viết thư cho bạn bè."}]','[{"phrase":"write a letter"},{"phrase":"receive a letter"},{"phrase":"capital letter"}]',NULL,'/ˈletər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/let/lette/letter__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(340,'ngsl-1-10',10,'decide','quyết định','verb','[{"en":"We decided to stay home because of the storm.","vi":"Chúng tôi quyết định ở nhà vì cơn bão."},{"en":"Have you decided what to order yet?","vi":"Bạn đã quyết định gọi món gì chưa?"},{"en":"It''s hard to decide between these two jobs.","vi":"Thật khó để quyết định chọn giữa hai công việc này."}]','[{"phrase":"decide to"},{"phrase":"decide between"},{"phrase":"finally decide"}]','decide to do something','/dɪˈsaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decid/decide__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(341,'ngsl-1-10',11,'language','ngôn ngữ','noun','[{"en":"How many languages can your sister speak?","vi":"Chị của bạn nói được bao nhiêu ngôn ngữ?"},{"en":"English is the main language used at our company.","vi":"Tiếng Anh là ngôn ngữ chính được dùng ở công ty chúng tôi."},{"en":"Body language can tell you a lot about someone''s feelings.","vi":"Ngôn ngữ cơ thể có thể cho bạn biết nhiều về cảm xúc của một người."}]','[{"phrase":"foreign language"},{"phrase":"body language"},{"phrase":"first language"},{"phrase":"speak a language"}]',NULL,'/ˈlæŋɡwɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lan/langu/language__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(342,'ngsl-1-10',12,'subject','môn học; chủ đề','noun','[{"en":"Math was always my favorite subject at school.","vi":"Toán luôn là môn học yêu thích của tôi ở trường."},{"en":"Let''s change the subject and talk about something else.","vi":"Mình đổi chủ đề và nói chuyện khác đi."},{"en":"She has written several books on the subject of health.","vi":"Cô ấy đã viết vài cuốn sách về chủ đề sức khỏe."}]','[{"phrase":"favorite subject"},{"phrase":"change the subject"},{"phrase":"on the subject of"}]',NULL,'/ˈsʌbdʒɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subje/subject__us_4_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(343,'ngsl-1-10',13,'class','lớp học; buổi học','noun','[{"en":"There are thirty students in my English class.","vi":"Lớp tiếng Anh của tôi có ba mươi học sinh."},{"en":"I have a yoga class every Tuesday evening.","vi":"Tôi có buổi học yoga vào mỗi tối thứ Ba."},{"en":"He missed class yesterday because he was sick.","vi":"Hôm qua anh ấy nghỉ học vì bị ốm."}]','[{"phrase":"take a class"},{"phrase":"miss class"},{"phrase":"in class"}]',NULL,'/klæs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/class__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(344,'ngsl-1-10',14,'development','sự phát triển','noun','[{"en":"Sleep is very important for a child''s development.","vi":"Giấc ngủ rất quan trọng đối với sự phát triển của trẻ."},{"en":"The development of the new software took two years.","vi":"Việc phát triển phần mềm mới mất hai năm."},{"en":"Our company spends a lot on research and development.","vi":"Công ty chúng tôi chi nhiều tiền cho nghiên cứu và phát triển."}]','[{"phrase":"economic development"},{"phrase":"child development"},{"phrase":"research and development"}]',NULL,'/dɪˈveləpmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devel/development__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(345,'ngsl-1-10',15,'town','thị trấn; thành phố, phố','noun','[{"en":"I grew up in a small town near the sea.","vi":"Tôi lớn lên ở một thị trấn nhỏ gần biển."},{"en":"We''re going into town to do some shopping.","vi":"Chúng tôi sẽ ra phố mua sắm một chút."},{"en":"The whole town came out to watch the parade.","vi":"Cả thị trấn kéo ra xem diễu hành."}]','[{"phrase":"small town"},{"phrase":"go into town"},{"phrase":"town center"}]',NULL,'/taʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tow/town_/town__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(346,'ngsl-1-10',16,'half','một nửa','noun','[{"en":"I''ve only read half of the book so far.","vi":"Đến giờ tôi mới đọc được một nửa cuốn sách."},{"en":"Cut the apple in half and share it with your brother.","vi":"Hãy cắt quả táo làm đôi và chia cho em trai con."},{"en":"We waited for half an hour at the station.","vi":"Chúng tôi đã đợi nửa tiếng ở nhà ga."}]','[{"phrase":"half an hour"},{"phrase":"in half"},{"phrase":"half of"}]','số nhiều: halves','/hæf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hal/half_/half__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(347,'ngsl-1-10',17,'minute','phút; một lát','noun','[{"en":"The next train leaves in about ten minutes.","vi":"Chuyến tàu tiếp theo sẽ khởi hành trong khoảng mười phút nữa."},{"en":"Can you wait a minute while I get my coat?","vi":"Bạn đợi một lát để tôi lấy áo khoác được không?"},{"en":"I walk for thirty minutes every morning.","vi":"Mỗi sáng tôi đi bộ ba mươi phút."}]','[{"phrase":"wait a minute"},{"phrase":"just a minute"},{"phrase":"last minute"}]',NULL,'/ˈmɪnɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minut/minute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(348,'ngsl-1-10',18,'food','thức ăn, đồ ăn','noun','[{"en":"We need to buy some food for the weekend.","vi":"Chúng ta cần mua ít đồ ăn cho cuối tuần."},{"en":"Street food in this city is cheap and delicious.","vi":"Đồ ăn đường phố ở thành phố này vừa rẻ vừa ngon."},{"en":"Healthy food doesn''t have to be expensive.","vi":"Đồ ăn lành mạnh không nhất thiết phải đắt."}]','[{"phrase":"fast food"},{"phrase":"healthy food"},{"phrase":"street food"},{"phrase":"spicy food"}]',NULL,'/fuːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/food_/food__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(349,'ngsl-1-10',19,'break','làm vỡ, làm gãy; vi phạm (luật, lời hứa)','verb','[{"en":"Be careful not to break those glasses.","vi":"Cẩn thận đừng làm vỡ mấy cái ly đó."},{"en":"He broke his arm when he fell off his bike.","vi":"Anh ấy bị gãy tay khi ngã xe đạp."},{"en":"You promised to call, so please don''t break your promise.","vi":"Bạn đã hứa sẽ gọi, nên đừng thất hứa nhé."}]','[{"phrase":"break a promise"},{"phrase":"break the rules"},{"phrase":"break the law"},{"phrase":"break a window"}]','break – broke – broken','/breɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/break/break__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(350,'ngsl-1-10',20,'clear','rõ ràng; trong, quang đãng','adjective','[{"en":"Are the instructions clear, or should I explain again?","vi":"Hướng dẫn đã rõ chưa, hay tôi nên giải thích lại?"},{"en":"It''s clear that she really enjoys her job.","vi":"Rõ ràng là cô ấy rất thích công việc của mình."},{"en":"On a clear day, you can see the mountains from here.","vi":"Vào ngày trời quang, bạn có thể nhìn thấy núi từ đây."}]','[{"phrase":"make it clear"},{"phrase":"clear instructions"},{"phrase":"clear sky"},{"phrase":"perfectly clear"}]',NULL,'/klɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cle/clear/clear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(351,'ngsl-1-10',21,'future','tương lai','noun','[{"en":"Nobody knows what will happen in the future.","vi":"Không ai biết điều gì sẽ xảy ra trong tương lai."},{"en":"What are your plans for the future?","vi":"Bạn có kế hoạch gì cho tương lai?"},{"en":"They are saving money for their children''s future.","vi":"Họ đang tiết kiệm tiền cho tương lai của con cái."}]','[{"phrase":"in the future"},{"phrase":"the near future"},{"phrase":"plans for the future"},{"phrase":"bright future"}]',NULL,'/ˈfjuːtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fut/futur/future__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(352,'ngsl-1-10',22,'either','hoặc (either … or); cũng (không)','conjunction','[{"en":"You can pay either by cash or by card.","vi":"Bạn có thể trả bằng tiền mặt hoặc bằng thẻ."},{"en":"We can meet either on Friday or on Saturday.","vi":"Chúng ta có thể gặp nhau vào thứ Sáu hoặc thứ Bảy."},{"en":"I don''t like coffee, and my wife doesn''t either.","vi":"Tôi không thích cà phê, và vợ tôi cũng không."}]','[{"phrase":"either … or"},{"phrase":"not … either"},{"phrase":"either way"},{"phrase":"either side"}]','either … or: hoặc … hoặc; either (cũng) dùng trong câu phủ định','/ˈiːðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eit/eithe/either__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(353,'ngsl-1-10',23,'ago','trước, cách đây','adverb','[{"en":"I moved to this city five years ago.","vi":"Tôi chuyển đến thành phố này cách đây năm năm."},{"en":"She left the office a few minutes ago.","vi":"Cô ấy rời văn phòng vài phút trước."},{"en":"How long ago did you start learning English?","vi":"Bạn bắt đầu học tiếng Anh cách đây bao lâu rồi?"}]','[{"phrase":"years ago"},{"phrase":"a long time ago"},{"phrase":"a few days ago"},{"phrase":"not long ago"}]','dùng với thì quá khứ đơn: two days ago','/əˈɡəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ago/ago__/ago__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(354,'ngsl-1-10',24,'per','mỗi','preposition','[{"en":"The hotel costs eighty dollars per night.","vi":"Khách sạn có giá tám mươi đô la mỗi đêm."},{"en":"The speed limit here is thirty miles per hour.","vi":"Tốc độ tối đa ở đây là ba mươi dặm mỗi giờ."},{"en":"Tickets for the show cost ten dollars per person.","vi":"Vé xem buổi diễn có giá mười đô la mỗi người."}]','[{"phrase":"per person"},{"phrase":"per hour"},{"phrase":"per night"},{"phrase":"per day"}]',NULL,'/pər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/per__/per__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(355,'ngsl-1-10',25,'remain','vẫn (ở trạng thái); còn lại; ở lại','verb','[{"en":"Please remain in your seats until the plane stops.","vi":"Xin quý khách vui lòng ngồi yên tại chỗ cho đến khi máy bay dừng hẳn."},{"en":"Many questions still remain about the accident.","vi":"Vẫn còn nhiều câu hỏi xoay quanh vụ tai nạn."},{"en":"The weather remained cold for the whole week.","vi":"Thời tiết vẫn lạnh suốt cả tuần."}]','[{"phrase":"remain calm"},{"phrase":"remain the same"},{"phrase":"remain open"}]',NULL,'/rɪˈmeɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remai/remain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(356,'ngsl-1-10',26,'top','đỉnh; phần trên cùng','noun','[{"en":"It took us two hours to climb to the top of the hill.","vi":"Chúng tôi mất hai tiếng để leo lên đỉnh đồi."},{"en":"Write your name at the top of the page.","vi":"Hãy viết tên của bạn ở đầu trang."},{"en":"She put the heavy books on top of the box.","vi":"Cô ấy đặt mấy cuốn sách nặng lên trên cái hộp."}]','[{"phrase":"the top of"},{"phrase":"on top of"},{"phrase":"reach the top"}]',NULL,'/tɑːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/top/top__/top__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(357,'ngsl-1-10',27,'among','giữa (nhiều người, vật); trong số','preposition','[{"en":"She felt happy and relaxed among her old friends.","vi":"Cô ấy thấy vui vẻ và thoải mái giữa những người bạn cũ."},{"en":"This song is very popular among young people.","vi":"Bài hát này rất được giới trẻ yêu thích."},{"en":"The money was shared among the three children.","vi":"Số tiền được chia cho ba đứa trẻ."}]','[{"phrase":"among friends"},{"phrase":"popular among"},{"phrase":"among others"}]','among (giữa nhiều) ≠ between (giữa hai)','/əˈmʌŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/amo/among/among__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(358,'ngsl-1-10',28,'win','thắng; giành được','verb','[{"en":"Our team won the game by two points.","vi":"Đội chúng tôi thắng trận đấu với cách biệt hai điểm."},{"en":"She won first prize in the singing contest.","vi":"Cô ấy giành giải nhất trong cuộc thi hát."},{"en":"Do you think we can win tomorrow''s match?","vi":"Bạn có nghĩ chúng ta có thể thắng trận đấu ngày mai không?"}]','[{"phrase":"win a game"},{"phrase":"win a prize"},{"phrase":"win an award"},{"phrase":"win a match"}]','win – won – won','/wɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/win__/win__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(359,'ngsl-1-10',29,'color','màu sắc','noun','[{"en":"What color would you like to paint the bedroom?","vi":"Bạn muốn sơn phòng ngủ màu gì?"},{"en":"The leaves change color in the fall.","vi":"Lá cây đổi màu vào mùa thu."},{"en":"This photo looks better in color than in black and white.","vi":"Bức ảnh này để màu trông đẹp hơn ảnh đen trắng."}]','[{"phrase":"favorite color"},{"phrase":"bright colors"},{"phrase":"change color"}]','Anh: colour · Mỹ: color','/ˈkʌlər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colou/colour__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(360,'ngsl-1-10',30,'involve','bao gồm, đòi hỏi; liên quan, tham gia vào','verb','[{"en":"The job involves a lot of travel.","vi":"Công việc này đòi hỏi phải đi lại nhiều."},{"en":"Parents should be involved in their children''s education.","vi":"Cha mẹ nên tham gia vào việc học của con cái."},{"en":"I don''t want to get involved in their argument.","vi":"Tôi không muốn dính vào cuộc cãi vã của họ."}]','[{"phrase":"be involved in"},{"phrase":"get involved"},{"phrase":"involve a lot of"}]','be/get involved in something','/ɪnˈvɑːlv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invol/involve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(361,'ngsl-1-11',1,'reach','đến, tới; đạt được; với tới','verb','[{"en":"We reached the hotel just before midnight.","vi":"Chúng tôi đến khách sạn ngay trước nửa đêm."},{"en":"The two sides finally reached an agreement after long talks.","vi":"Sau những cuộc đàm phán kéo dài, hai bên cuối cùng đã đạt được thỏa thuận."},{"en":"Can you reach the top shelf for me?","vi":"Bạn với tới cái kệ trên cùng giúp tôi được không?"}]','[{"phrase":"reach an agreement"},{"phrase":"reach a decision"},{"phrase":"reach the top"}]',NULL,'/riːtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reach/reach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(362,'ngsl-1-11',2,'social','(thuộc) xã hội; giao tiếp, giao du','adjective','[{"en":"Social media has changed the way young people communicate.","vi":"Mạng xã hội đã thay đổi cách giới trẻ giao tiếp."},{"en":"Poverty is one of the biggest social problems in the city.","vi":"Nghèo đói là một trong những vấn đề xã hội lớn nhất của thành phố."},{"en":"She has a busy social life and goes out most weekends.","vi":"Cô ấy có cuộc sống giao du bận rộn và hầu như cuối tuần nào cũng ra ngoài."}]','[{"phrase":"social media"},{"phrase":"social life"},{"phrase":"social problem"},{"phrase":"social skills"}]',NULL,'/ˈsəʊʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soc/socia/social__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(363,'ngsl-1-11',3,'period','giai đoạn, thời kỳ; khoảng thời gian; tiết học','noun','[{"en":"He lived in France for a short period after college.","vi":"Anh ấy sống ở Pháp một thời gian ngắn sau khi học xong đại học."},{"en":"The store is closed during the holiday period.","vi":"Cửa hàng đóng cửa trong thời gian nghỉ lễ."},{"en":"We have math in the first period on Tuesdays.","vi":"Vào thứ Ba, chúng tôi học toán tiết đầu tiên."}]','[{"phrase":"a period of time"},{"phrase":"a short period"},{"phrase":"the holiday period"},{"phrase":"trial period"}]',NULL,'/ˈpɪriəd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perio/period__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(364,'ngsl-1-11',4,'across','qua, băng qua; ở bên kia; khắp','preposition','[{"en":"Be careful when you walk across the street.","vi":"Hãy cẩn thận khi bạn đi bộ qua đường."},{"en":"There is a small café across the road from our office.","vi":"Có một quán cà phê nhỏ ở bên kia đường, đối diện văn phòng chúng tôi."},{"en":"The company has stores across the country.","vi":"Công ty có cửa hàng trên khắp cả nước."}]','[{"phrase":"across the street"},{"phrase":"across the road"},{"phrase":"across the country"},{"phrase":"walk across"}]',NULL,'/əˈkrɔːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acr/acros/across__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(365,'ngsl-1-11',5,'note','ghi chú; lời nhắn, mẩu giấy nhắn','noun','[{"en":"I took notes during the lecture so I could review them later.","vi":"Tôi ghi chép trong buổi giảng để có thể ôn lại sau."},{"en":"She left a note on the fridge saying she''d be late.","vi":"Cô ấy để lại mẩu giấy nhắn trên tủ lạnh, báo rằng sẽ về muộn."},{"en":"Please make a note of the meeting time.","vi":"Bạn hãy ghi lại giờ họp nhé."}]','[{"phrase":"take notes"},{"phrase":"leave a note"},{"phrase":"make a note of"}]',NULL,'/nəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/note_/note__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(366,'ngsl-1-11',6,'history','lịch sử; tiền sử, quá trình','noun','[{"en":"History was my favorite subject in high school.","vi":"Lịch sử là môn học yêu thích của tôi hồi cấp ba."},{"en":"This town has a long and interesting history.","vi":"Thị trấn này có một lịch sử lâu đời và thú vị."},{"en":"The doctor asked about my family''s medical history.","vi":"Bác sĩ hỏi về tiền sử bệnh của gia đình tôi."}]','[{"phrase":"long history"},{"phrase":"medical history"},{"phrase":"history lesson"}]',NULL,'/ˈhɪstri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/history__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(367,'ngsl-1-11',7,'create','tạo ra; sáng tạo','verb','[{"en":"The new factory will create hundreds of jobs.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm."},{"en":"You need to create a password for your account.","vi":"Bạn cần tạo mật khẩu cho tài khoản của mình."},{"en":"The children created beautiful paintings in art class.","vi":"Trong giờ mỹ thuật, bọn trẻ đã sáng tạo nên những bức tranh thật đẹp."}]','[{"phrase":"create jobs"},{"phrase":"create an account"},{"phrase":"create problems"},{"phrase":"create opportunities"}]',NULL,'/kriˈeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/create__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(368,'ngsl-1-11',8,'drive','lái (xe); chở (ai) bằng xe','verb','[{"en":"My father drives to work every morning.","vi":"Bố tôi lái xe đi làm mỗi sáng."},{"en":"Can you drive me to the airport tomorrow?","vi":"Ngày mai bạn chở tôi ra sân bay được không?"},{"en":"She learned to drive when she was eighteen.","vi":"Cô ấy học lái xe khi mười tám tuổi."}]','[{"phrase":"drive a car"},{"phrase":"drive to work"},{"phrase":"learn to drive"}]','drive – drove – driven','/draɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dri/drive/drive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(369,'ngsl-1-11',9,'along','dọc theo','preposition','[{"en":"We walked along the beach at sunset.","vi":"Chúng tôi đi dạo dọc bãi biển lúc hoàng hôn."},{"en":"There are many small shops along this street.","vi":"Có nhiều cửa hàng nhỏ dọc con phố này."},{"en":"Trees were planted along both sides of the river.","vi":"Cây được trồng dọc hai bên bờ sông."}]','[{"phrase":"walk along"},{"phrase":"along the road"},{"phrase":"along the river"},{"phrase":"along the beach"}]',NULL,'/əˈlɔːŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alo/along/along__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(370,'ngsl-1-11',10,'type','loại, kiểu','noun','[{"en":"What type of music do you like?","vi":"Bạn thích loại nhạc nào?"},{"en":"This type of plant needs a lot of sunlight.","vi":"Loại cây này cần nhiều ánh nắng."},{"en":"He''s not the type of person who gives up easily.","vi":"Anh ấy không phải kiểu người dễ bỏ cuộc."}]','[{"phrase":"type of person"},{"phrase":"blood type"},{"phrase":"different types"}]',NULL,'/taɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/typ/type_/type__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(371,'ngsl-1-11',11,'sound','âm thanh, tiếng, tiếng động','noun','[{"en":"I heard a strange sound coming from the kitchen.","vi":"Tôi nghe thấy một tiếng động lạ phát ra từ nhà bếp."},{"en":"Please turn the sound down because the baby is sleeping.","vi":"Làm ơn vặn nhỏ tiếng xuống vì em bé đang ngủ."},{"en":"I love the sound of rain on the roof.","vi":"Tôi thích tiếng mưa rơi trên mái nhà."}]','[{"phrase":"make a sound"},{"phrase":"strange sound"},{"phrase":"loud sound"},{"phrase":"the sound of"}]',NULL,'/saʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/sound/sound__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(372,'ngsl-1-11',12,'eye','mắt','noun','[{"en":"She has beautiful blue eyes, just like her mother.","vi":"Cô ấy có đôi mắt xanh rất đẹp, giống hệt mẹ mình."},{"en":"Close your eyes and try to relax.","vi":"Hãy nhắm mắt lại và cố gắng thư giãn."},{"en":"My eyes hurt after looking at the screen all day.","vi":"Mắt tôi bị đau sau khi nhìn màn hình cả ngày."}]','[{"phrase":"close your eyes"},{"phrase":"open your eyes"},{"phrase":"blue eyes"},{"phrase":"keep an eye on"}]',NULL,'/aɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eye/eye__/eye__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(373,'ngsl-1-11',13,'music','âm nhạc, nhạc','noun','[{"en":"I often listen to music while I study.","vi":"Tôi thường nghe nhạc trong lúc học bài."},{"en":"The music at the party was too loud.","vi":"Nhạc ở bữa tiệc quá to."},{"en":"He wants to study music at university.","vi":"Anh ấy muốn học âm nhạc ở đại học."}]','[{"phrase":"listen to music"},{"phrase":"play music"},{"phrase":"loud music"},{"phrase":"music lesson"}]','không đếm được','/ˈmjuːzɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/music/music__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(374,'ngsl-1-11',14,'game','trò chơi; trận đấu','noun','[{"en":"The kids played a board game after dinner.","vi":"Bọn trẻ chơi một trò chơi cờ bàn sau bữa tối."},{"en":"Did you watch the basketball game last night?","vi":"Tối qua bạn có xem trận bóng rổ không?"},{"en":"My brother spends too much time playing video games.","vi":"Em trai tôi dành quá nhiều thời gian chơi trò chơi điện tử."}]','[{"phrase":"play a game"},{"phrase":"video game"},{"phrase":"board game"},{"phrase":"win the game"}]',NULL,'/ɡeɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gam/game_/game__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(375,'ngsl-1-11',15,'political','(thuộc) chính trị','adjective','[{"en":"The country has two main political parties.","vi":"Đất nước này có hai đảng chính trị chính."},{"en":"They avoid political topics at family dinners.","vi":"Họ tránh các chủ đề chính trị trong những bữa ăn gia đình."},{"en":"She is studying political science at university.","vi":"Cô ấy đang học ngành khoa học chính trị ở đại học."}]','[{"phrase":"political party"},{"phrase":"political science"},{"phrase":"political issue"},{"phrase":"political system"}]',NULL,'/pəˈlɪtɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polit/political__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(376,'ngsl-1-11',16,'free','miễn phí; rảnh; tự do','adjective','[{"en":"Entry to the museum is free on Sundays.","vi":"Vào bảo tàng được miễn phí vào các ngày Chủ nhật."},{"en":"Are you free to have lunch with me tomorrow?","vi":"Ngày mai bạn có rảnh đi ăn trưa với tôi không?"},{"en":"The bird was finally set free from its cage.","vi":"Con chim cuối cùng cũng được thả tự do khỏi lồng."}]','[{"phrase":"free time"},{"phrase":"for free"},{"phrase":"free of charge"},{"phrase":"feel free"}]',NULL,'/friː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/free_/free__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(377,'ngsl-1-11',17,'receive','nhận, nhận được','verb','[{"en":"Did you receive my email this morning?","vi":"Sáng nay bạn có nhận được email của tôi không?"},{"en":"She received a lot of gifts on her birthday.","vi":"Cô ấy nhận được rất nhiều quà vào ngày sinh nhật."},{"en":"He received an award for his hard work.","vi":"Anh ấy nhận được giải thưởng nhờ sự làm việc chăm chỉ."}]','[{"phrase":"receive a letter"},{"phrase":"receive an email"},{"phrase":"receive an award"},{"phrase":"receive help"}]',NULL,'/rɪˈsiːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recei/receive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(378,'ngsl-1-11',18,'moment','lúc, khoảnh khắc; chốc lát','noun','[{"en":"Please wait a moment while I check your booking.","vi":"Xin vui lòng đợi một chút trong khi tôi kiểm tra đặt chỗ của bạn."},{"en":"She is busy at the moment, so please call back later.","vi":"Hiện giờ cô ấy đang bận, nên vui lòng gọi lại sau."},{"en":"Winning the race was the best moment of my life.","vi":"Chiến thắng cuộc đua là khoảnh khắc tuyệt vời nhất trong đời tôi."}]','[{"phrase":"at the moment"},{"phrase":"wait a moment"},{"phrase":"for a moment"},{"phrase":"the right moment"}]',NULL,'/ˈməʊmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mom/momen/moment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(379,'ngsl-1-11',19,'sale','sự bán; đợt giảm giá; doanh số (sales)','noun','[{"en":"The house next to ours is for sale.","vi":"Căn nhà bên cạnh nhà chúng tôi đang được rao bán."},{"en":"The store is having a big sale this weekend.","vi":"Cuối tuần này cửa hàng có đợt giảm giá lớn."},{"en":"Sales of electric bikes have grown quickly this year.","vi":"Doanh số xe đạp điện đã tăng nhanh trong năm nay."}]','[{"phrase":"for sale"},{"phrase":"on sale"},{"phrase":"big sale"},{"phrase":"sales figures"}]',NULL,'/seɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sal/sale_/sale__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(380,'ngsl-1-11',20,'policy','chính sách; quy định','noun','[{"en":"The company has a strict policy on working from home.","vi":"Công ty có quy định nghiêm ngặt về việc làm việc tại nhà."},{"en":"Our school has a no-phone policy during class.","vi":"Trường chúng tôi có quy định cấm dùng điện thoại trong giờ học."},{"en":"The government announced a new policy to support small businesses.","vi":"Chính phủ đã công bố một chính sách mới để hỗ trợ các doanh nghiệp nhỏ."}]','[{"phrase":"company policy"},{"phrase":"government policy"},{"phrase":"return policy"},{"phrase":"strict policy"}]',NULL,'/ˈpɑːləsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polic/policy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(381,'ngsl-1-11',21,'further','xa hơn; thêm, hơn nữa','adverb','[{"en":"The hotel was further from the beach than we expected.","vi":"Khách sạn cách bãi biển xa hơn chúng tôi nghĩ."},{"en":"I''m too tired to walk any further.","vi":"Tôi mệt quá, không thể đi xa hơn được nữa."},{"en":"We decided not to discuss the matter any further.","vi":"Chúng tôi quyết định không bàn thêm về vấn đề này nữa."}]','[{"phrase":"any further"},{"phrase":"go further"},{"phrase":"further information"}]','far – further – furthest','/ˈfɜːrðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furth/further__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(382,'ngsl-1-11',22,'body','cơ thể; thân thể','noun','[{"en":"Regular exercise keeps your body strong and healthy.","vi":"Tập thể dục đều đặn giúp cơ thể bạn khỏe mạnh."},{"en":"My whole body ached after the long hike.","vi":"Toàn thân tôi đau nhức sau chuyến đi bộ đường dài."},{"en":"Water makes up about sixty percent of the human body.","vi":"Nước chiếm khoảng sáu mươi phần trăm cơ thể người."}]','[{"phrase":"human body"},{"phrase":"whole body"},{"phrase":"body temperature"},{"phrase":"body language"}]',NULL,'/ˈbɑːdi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bod/body_/body__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(383,'ngsl-1-11',23,'require','đòi hỏi, cần; yêu cầu','verb','[{"en":"This job requires good communication skills and some experience.","vi":"Công việc này đòi hỏi kỹ năng giao tiếp tốt và một chút kinh nghiệm."},{"en":"All visitors are required to sign in at the front desk.","vi":"Tất cả khách đến thăm đều được yêu cầu đăng ký tại quầy lễ tân."},{"en":"Most houseplants require very little care.","vi":"Hầu hết các loại cây trồng trong nhà cần rất ít công chăm sóc."}]','[{"phrase":"be required to"},{"phrase":"require skills"},{"phrase":"require attention"}]',NULL,'/rɪˈkwaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/requi/require__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(384,'ngsl-1-11',24,'wait','chờ, đợi','verb','[{"en":"Please wait here until your name is called.","vi":"Vui lòng đợi ở đây cho đến khi được gọi tên."},{"en":"We waited for the bus for almost an hour.","vi":"Chúng tôi đã chờ xe buýt gần một tiếng."},{"en":"I can''t wait to see you again next month.","vi":"Tôi nóng lòng chờ được gặp lại bạn vào tháng sau."}]','[{"phrase":"wait for"},{"phrase":"wait a minute"},{"phrase":"can''t wait"},{"phrase":"wait in line"}]','wait for sb/sth: chờ ai/cái gì','/weɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wai/wait_/wait__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(385,'ngsl-1-11',25,'general','chung; tổng quát','adjective','[{"en":"In general, people here are very friendly.","vi":"Nhìn chung, người dân ở đây rất thân thiện."},{"en":"The book gives a general introduction to world history.","vi":"Cuốn sách giới thiệu tổng quát về lịch sử thế giới."},{"en":"Can you give me a general idea of the cost?","vi":"Bạn có thể cho tôi biết sơ qua về chi phí không?"}]','[{"phrase":"in general"},{"phrase":"general idea"},{"phrase":"general public"},{"phrase":"general knowledge"}]',NULL,'/ˈdʒenrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/general__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(386,'ngsl-1-11',26,'appear','xuất hiện; có vẻ','verb','[{"en":"A strange man suddenly appeared at the door.","vi":"Một người đàn ông lạ bỗng xuất hiện ở cửa."},{"en":"She appeared very nervous before her speech.","vi":"Cô ấy có vẻ rất lo lắng trước bài phát biểu."},{"en":"Her photo appeared in the local newspaper last week.","vi":"Ảnh của cô ấy xuất hiện trên tờ báo địa phương tuần trước."}]','[{"phrase":"suddenly appear"},{"phrase":"appear to be"},{"phrase":"appear on television"}]',NULL,'/əˈpɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appea/appear__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(387,'ngsl-1-11',27,'toward','về phía; đối với','preposition','[{"en":"The dog ran toward me, wagging its tail.","vi":"Con chó vừa chạy về phía tôi vừa vẫy đuôi."},{"en":"She walked toward the door without saying a word.","vi":"Cô ấy đi về phía cửa mà không nói một lời."},{"en":"His attitude toward his work has improved a lot.","vi":"Thái độ của anh ấy đối với công việc đã tiến bộ nhiều."}]','[{"phrase":"walk toward"},{"phrase":"attitude toward"},{"phrase":"toward the end"}]','Mỹ: toward · Anh: towards','/təˈwɔrd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(388,'ngsl-1-11',28,'team','đội, nhóm','noun','[{"en":"Our team won the match by two goals.","vi":"Đội chúng tôi thắng trận với cách biệt hai bàn."},{"en":"She works in a small team of designers.","vi":"Cô ấy làm việc trong một nhóm nhỏ gồm các nhà thiết kế."},{"en":"Do you want to join the school football team?","vi":"Bạn có muốn tham gia đội bóng đá của trường không?"}]','[{"phrase":"football team"},{"phrase":"join a team"},{"phrase":"team member"},{"phrase":"work as a team"}]',NULL,'/tiːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/team_/team__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(389,'ngsl-1-11',29,'easy','dễ, dễ dàng','adjective','[{"en":"The test was easier than I expected.","vi":"Bài kiểm tra dễ hơn tôi nghĩ."},{"en":"It isn''t easy to learn a new language.","vi":"Học một ngôn ngữ mới không hề dễ."},{"en":"This recipe is quick and easy to follow.","vi":"Công thức này nhanh gọn và dễ làm theo."}]','[{"phrase":"easy to use"},{"phrase":"easy question"},{"phrase":"take it easy"},{"phrase":"easy way"}]','easy – easier – easiest','/ˈiːzi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/easy_/easy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(390,'ngsl-1-11',30,'individual','riêng, cá nhân; từng (người, cái)','adjective','[{"en":"Each student receives individual attention from the teacher.","vi":"Mỗi học sinh đều được giáo viên quan tâm riêng."},{"en":"We try to meet the individual needs of every customer.","vi":"Chúng tôi cố gắng đáp ứng nhu cầu riêng của từng khách hàng."},{"en":"The price of each individual item is shown on the label.","vi":"Giá của từng món hàng được ghi trên nhãn."}]','[{"phrase":"individual needs"},{"phrase":"individual attention"},{"phrase":"individual differences"}]',NULL,'/ˌɪndɪˈvɪdʒuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indiv/individual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(391,'ngsl-1-12',1,'full','đầy; no','adjective','[{"en":"The bus was so full that we had to stand.","vi":"Xe buýt chật kín người đến mức chúng tôi phải đứng."},{"en":"No more water for me, please. My glass is still full.","vi":"Đừng rót thêm nước cho tôi nhé. Cốc của tôi vẫn còn đầy."},{"en":"No more rice for me, thanks. I''m really full.","vi":"Tôi không ăn thêm cơm nữa đâu, cảm ơn. Tôi no lắm rồi."}]','[{"phrase":"full of"},{"phrase":"completely full"},{"phrase":"full name"},{"phrase":"full time"}]','be full of: đầy thứ gì','/fʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/ful/full_/full__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(392,'ngsl-1-12',2,'black','đen; (cà phê) không sữa','adjective','[{"en":"He always wears a black jacket to work.","vi":"Anh ấy luôn mặc áo khoác đen đi làm."},{"en":"I drink my coffee black, without sugar.","vi":"Tôi uống cà phê đen, không đường."},{"en":"Her cat is completely black except for its white paws.","vi":"Con mèo của cô ấy đen tuyền, chỉ có bàn chân màu trắng."}]','[{"phrase":"black coffee"},{"phrase":"black hair"},{"phrase":"black and white"}]',NULL,'/blæk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bla/black/black__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(393,'ngsl-1-12',3,'sense','ý nghĩa; cảm giác; giác quan','noun','[{"en":"His explanation doesn''t make any sense to me.","vi":"Lời giải thích của anh ấy chẳng có nghĩa lý gì với tôi."},{"en":"Finishing the project gave her a real sense of pride.","vi":"Hoàn thành dự án mang lại cho cô ấy cảm giác thực sự tự hào."},{"en":"Dogs have a much better sense of smell than people.","vi":"Chó có khứu giác tốt hơn con người rất nhiều."}]','[{"phrase":"make sense"},{"phrase":"sense of humor"},{"phrase":"sense of smell"},{"phrase":"common sense"}]','make sense: hợp lý, dễ hiểu','/sens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/sense/sense__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(394,'ngsl-1-12',4,'perhaps','có lẽ; có thể','adverb','[{"en":"Perhaps we should leave early to avoid the traffic.","vi":"Có lẽ chúng ta nên đi sớm để tránh kẹt xe."},{"en":"She hasn''t called yet; perhaps she''s still at work.","vi":"Cô ấy vẫn chưa gọi; có lẽ cô ấy vẫn đang ở chỗ làm."},{"en":"The trip will take three hours, perhaps a little more.","vi":"Chuyến đi sẽ mất ba tiếng, có thể hơn một chút."}]','[{"phrase":"perhaps not"},{"phrase":"or perhaps"},{"phrase":"perhaps even"}]',NULL,'/pərˈhæps/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perha/perhaps__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(395,'ngsl-1-12',5,'add','thêm; cộng; nói thêm','verb','[{"en":"Add a little salt to the soup before serving.","vi":"Thêm một chút muối vào canh trước khi dọn ra."},{"en":"If you add five and seven, you get twelve.","vi":"Nếu cộng năm với bảy, bạn được mười hai."},{"en":"\"And please don''t be late again,\" my boss added.","vi":"\"Và làm ơn đừng đến muộn nữa,\" sếp tôi nói thêm."}]','[{"phrase":"add salt"},{"phrase":"add to"},{"phrase":"add up"},{"phrase":"add a comment"}]','add A to B: thêm A vào B','/æd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/add__/add__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(396,'ngsl-1-12',6,'rule','quy tắc; luật lệ','noun','[{"en":"Can you explain the rules of the game to me?","vi":"Bạn có thể giải thích luật chơi cho tôi không?"},{"en":"Students must follow the school rules at all times.","vi":"Học sinh phải luôn tuân thủ nội quy của trường."},{"en":"As a rule, I don''t check emails on weekends.","vi":"Thường thì tôi không kiểm tra email vào cuối tuần."}]','[{"phrase":"follow the rules"},{"phrase":"break the rules"},{"phrase":"as a rule"},{"phrase":"strict rules"}]',NULL,'/ruːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rul/rule_/rule__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(397,'ngsl-1-12',7,'pass','đi qua; vượt qua (kỳ thi); đưa, chuyền','verb','[{"en":"We passed a small café on the way to the station.","vi":"Trên đường ra ga, chúng tôi đi ngang qua một quán cà phê nhỏ."},{"en":"She studied hard and passed her driving test.","vi":"Cô ấy học chăm chỉ và đã thi đỗ bằng lái xe."},{"en":"Could you pass me the salt, please?","vi":"Bạn đưa giúp tôi lọ muối được không?"}]','[{"phrase":"pass an exam"},{"phrase":"pass a test"},{"phrase":"pass the salt"},{"phrase":"time passes"}]',NULL,'/pæs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/pass_/pass__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(398,'ngsl-1-12',8,'produce','sản xuất; tạo ra','verb','[{"en":"This factory produces over a thousand cars a week.","vi":"Nhà máy này sản xuất hơn một nghìn chiếc ô tô mỗi tuần."},{"en":"The region produces most of the country''s coffee.","vi":"Vùng này sản xuất phần lớn cà phê của cả nước."},{"en":"Our new plan has already produced good results.","vi":"Kế hoạch mới của chúng tôi đã tạo ra kết quả tốt."}]','[{"phrase":"produce results"},{"phrase":"produce food"},{"phrase":"produce energy"}]','produce (v) sản xuất ≠ produce (n) nông sản','/prəˈduːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/produce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(399,'ngsl-1-12',9,'sell','bán','verb','[{"en":"They sold their old house and moved to the city.","vi":"Họ đã bán ngôi nhà cũ và chuyển lên thành phố."},{"en":"Do you know if this shop sells phone chargers?","vi":"Bạn có biết cửa hàng này có bán sạc điện thoại không?"},{"en":"Tickets for the concert sold out in two hours.","vi":"Vé buổi hòa nhạc đã bán hết trong hai giờ."}]','[{"phrase":"sell out"},{"phrase":"sell a house"},{"phrase":"sell tickets"},{"phrase":"sell well"}]','sell – sold – sold','/sel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/sell_/sell__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(400,'ngsl-1-12',10,'short','ngắn; thấp','adjective','[{"en":"Let''s take a short break before the next meeting.","vi":"Chúng ta nghỉ giải lao ngắn trước cuộc họp tiếp theo nhé."},{"en":"My sister is short, but she plays basketball very well.","vi":"Chị tôi thấp nhưng chơi bóng rổ rất giỏi."},{"en":"She got her hair cut short for the summer.","vi":"Cô ấy đã cắt tóc ngắn cho mùa hè."}]','[{"phrase":"short break"},{"phrase":"short hair"},{"phrase":"short time"},{"phrase":"short of"}]','người thấp: short (không dùng low)','/ʃɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/short/short__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(401,'ngsl-1-12',11,'agree','đồng ý; nhất trí','verb','[{"en":"I agree with you about the new schedule.","vi":"Tôi đồng ý với bạn về lịch trình mới."},{"en":"My parents finally agreed to let me travel alone.","vi":"Cuối cùng bố mẹ cũng đồng ý cho tôi đi du lịch một mình."},{"en":"We couldn''t agree on a name for the baby.","vi":"Chúng tôi không thể thống nhất được tên cho em bé."}]','[{"phrase":"agree with"},{"phrase":"agree to"},{"phrase":"agree on"},{"phrase":"completely agree"}]','agree with (người/ý kiến) · agree to (đề nghị) · agree on (vấn đề)','/əˈɡriː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agr/agree/agree__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(402,'ngsl-1-12',12,'law','luật; pháp luật','noun','[{"en":"In many countries, wearing a seat belt is the law.","vi":"Ở nhiều nước, thắt dây an toàn là quy định của pháp luật."},{"en":"Everyone has to obey the law, even the police.","vi":"Ai cũng phải tuân thủ pháp luật, kể cả cảnh sát."},{"en":"My cousin is studying law at university.","vi":"Anh họ tôi đang học ngành luật ở trường đại học."}]','[{"phrase":"break the law"},{"phrase":"obey the law"},{"phrase":"against the law"},{"phrase":"study law"}]',NULL,'/lɔː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/law/law__/law__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(403,'ngsl-1-12',13,'everything','mọi thứ; tất cả','pronoun','[{"en":"Thank you for everything you''ve done for me.","vi":"Cảm ơn bạn vì tất cả những gì bạn đã làm cho tôi."},{"en":"Is everything ready for the party tonight?","vi":"Mọi thứ cho bữa tiệc tối nay đã sẵn sàng chưa?"},{"en":"Don''t worry so much, everything will be fine.","vi":"Đừng lo lắng quá, mọi chuyện sẽ ổn thôi."}]','[{"phrase":"everything else"},{"phrase":"everything is fine"},{"phrase":"thanks for everything"}]','everything + động từ số ít','/ˈevriθɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everything__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(404,'ngsl-1-12',14,'research','nghiên cứu; sự tìm hiểu','noun','[{"en":"She is doing research on children''s sleep habits.","vi":"Cô ấy đang nghiên cứu về thói quen ngủ của trẻ em."},{"en":"Recent research shows that walking is good for the brain.","vi":"Nghiên cứu gần đây cho thấy đi bộ tốt cho não."},{"en":"Do some research before you buy a used car.","vi":"Hãy tìm hiểu trước khi mua một chiếc ô tô cũ."}]','[{"phrase":"do research"},{"phrase":"research shows"},{"phrase":"carry out research"},{"phrase":"research on"}]','không đếm được: some research (không nói a research)','/ˈriːsɜːrtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resea/research__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(405,'ngsl-1-12',15,'cover','che, phủ; bao gồm; chi trả','verb','[{"en":"Cover the bowl and put it in the fridge.","vi":"Đậy cái bát lại và cho vào tủ lạnh."},{"en":"Today''s lesson will cover the past simple tense.","vi":"Bài học hôm nay sẽ bao gồm thì quá khứ đơn."},{"en":"Does your insurance cover the cost of the treatment?","vi":"Bảo hiểm của bạn có chi trả chi phí điều trị không?"}]','[{"phrase":"covered with"},{"phrase":"cover the cost"},{"phrase":"cover a topic"}]','be covered with/in: phủ đầy','/ˈkʌvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cov/cover/cover__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(406,'ngsl-1-12',16,'paper','giấy; tờ báo; giấy tờ','noun','[{"en":"Can I borrow a piece of paper and a pen?","vi":"Cho tôi mượn một tờ giấy và một cây bút được không?"},{"en":"My dad reads the paper every morning with his coffee.","vi":"Bố tôi đọc báo mỗi sáng cùng tách cà phê."},{"en":"Please bring your papers to the office on Monday.","vi":"Vui lòng mang giấy tờ của bạn đến văn phòng vào thứ Hai."}]','[{"phrase":"a piece of paper"},{"phrase":"sheet of paper"},{"phrase":"read the paper"},{"phrase":"paper bag"}]','giấy: không đếm được (a piece of paper); báo, giấy tờ: đếm được','/ˈpeɪpər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pap/paper/paper__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(407,'ngsl-1-12',17,'position','vị trí; chức vụ; tư thế','noun','[{"en":"Please move the chairs back to their original positions.","vi":"Vui lòng đặt ghế về lại vị trí ban đầu."},{"en":"He applied for a position at a bank.","vi":"Anh ấy đã nộp đơn ứng tuyển một vị trí ở ngân hàng."},{"en":"Try to sleep in a comfortable position.","vi":"Hãy cố gắng ngủ ở tư thế thoải mái."}]','[{"phrase":"apply for a position"},{"phrase":"comfortable position"},{"phrase":"in position"},{"phrase":"senior position"}]',NULL,'/pəˈzɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posit/position__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(408,'ngsl-1-12',18,'near','gần','preposition','[{"en":"We live near a park, so the kids play outside a lot.","vi":"Chúng tôi sống gần công viên nên bọn trẻ chơi ngoài trời nhiều."},{"en":"Excuse me, is there a pharmacy near here?","vi":"Xin lỗi, gần đây có hiệu thuốc nào không?"},{"en":"She sat near the window to get more light.","vi":"Cô ấy ngồi gần cửa sổ để có nhiều ánh sáng hơn."}]','[{"phrase":"near here"},{"phrase":"near the end"},{"phrase":"live near"},{"phrase":"near the window"}]','near (không có to) = close to','/nɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nea/near_/near__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(409,'ngsl-1-12',19,'human','(thuộc) con người; có tính người','adjective','[{"en":"The human body needs water to survive.","vi":"Cơ thể con người cần nước để sống."},{"en":"Don''t be so hard on yourself; it''s only human to make mistakes.","vi":"Đừng khắt khe với bản thân quá; mắc lỗi là chuyện thường tình của con người."},{"en":"Robots still can''t do many jobs that need human skills.","vi":"Robot vẫn chưa làm được nhiều công việc cần đến kỹ năng của con người."}]','[{"phrase":"human body"},{"phrase":"human being"},{"phrase":"human nature"},{"phrase":"human error"}]',NULL,'/ˈhjuːmən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hum/human/human__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(410,'ngsl-1-12',20,'computer','máy tính','noun','[{"en":"I spend most of my day working on a computer.","vi":"Tôi dành phần lớn thời gian trong ngày làm việc trên máy tính."},{"en":"Turn off the computer before you go to bed.","vi":"Tắt máy tính trước khi đi ngủ nhé."},{"en":"My grandmother is learning to use a computer.","vi":"Bà tôi đang học cách sử dụng máy tính."}]','[{"phrase":"use a computer"},{"phrase":"computer screen"},{"phrase":"computer game"},{"phrase":"turn off the computer"}]',NULL,'/kəmˈpjuːtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compu/computer__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(411,'ngsl-1-12',21,'situation','tình huống; tình hình','noun','[{"en":"What would you do in a situation like this?","vi":"Bạn sẽ làm gì trong tình huống như thế này?"},{"en":"The situation at work has improved a lot this year.","vi":"Tình hình ở chỗ làm đã cải thiện nhiều trong năm nay."},{"en":"She stayed calm and handled the difficult situation well.","vi":"Cô ấy giữ bình tĩnh và xử lý tốt tình huống khó khăn."}]','[{"phrase":"difficult situation"},{"phrase":"handle the situation"},{"phrase":"financial situation"},{"phrase":"in this situation"}]',NULL,'/ˌsɪtʃuˈeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/situa/situation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(412,'ngsl-1-12',22,'staff','nhân viên; đội ngũ nhân viên','noun','[{"en":"The hotel staff were very friendly and helpful.","vi":"Nhân viên khách sạn rất thân thiện và nhiệt tình."},{"en":"Our company has a staff of about fifty people.","vi":"Công ty chúng tôi có đội ngũ khoảng năm mươi nhân viên."},{"en":"All staff must attend the meeting on Friday.","vi":"Tất cả nhân viên phải tham dự cuộc họp vào thứ Sáu."}]','[{"phrase":"staff member"},{"phrase":"hotel staff"},{"phrase":"staff meeting"},{"phrase":"medical staff"}]','danh từ tập hợp; một người: a staff member','/stæf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/staff/staff__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(413,'ngsl-1-12',23,'activity','hoạt động','noun','[{"en":"Swimming is my favorite activity in the summer.","vi":"Bơi lội là hoạt động tôi thích nhất vào mùa hè."},{"en":"The school offers many activities after class.","vi":"Trường tổ chức nhiều hoạt động sau giờ học."},{"en":"Regular physical activity helps you sleep better.","vi":"Vận động thể chất thường xuyên giúp bạn ngủ ngon hơn."}]','[{"phrase":"physical activity"},{"phrase":"outdoor activities"},{"phrase":"after-school activities"},{"phrase":"daily activities"}]',NULL,'/ækˈtɪvəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/activ/activity__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(414,'ngsl-1-12',24,'film','phim','noun','[{"en":"Have you seen any good films lately?","vi":"Gần đây bạn có xem bộ phim nào hay không?"},{"en":"We watched an old film on TV last night.","vi":"Tối qua chúng tôi xem một bộ phim cũ trên TV."},{"en":"The film was so funny that we laughed from start to finish.","vi":"Bộ phim buồn cười đến mức chúng tôi cười từ đầu đến cuối."}]','[{"phrase":"watch a film"},{"phrase":"see a film"},{"phrase":"horror film"},{"phrase":"film star"}]','Anh: film · Mỹ: movie','/fɪlm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/film_/film__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(415,'ngsl-1-12',25,'morning','buổi sáng','noun','[{"en":"I usually go for a run early in the morning.","vi":"Tôi thường chạy bộ vào sáng sớm."},{"en":"The store opens at nine every morning.","vi":"Cửa hàng mở cửa lúc chín giờ mỗi sáng."},{"en":"What are you doing on Saturday morning?","vi":"Bạn làm gì vào sáng thứ Bảy?"}]','[{"phrase":"in the morning"},{"phrase":"every morning"},{"phrase":"early morning"},{"phrase":"good morning"}]','in the morning · on Monday morning','/ˈmɔːrnɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/morni/morning__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(416,'ngsl-1-12',26,'war','chiến tranh; cuộc chiến','noun','[{"en":"My grandfather rarely talked about his life during the war.","vi":"Ông tôi hiếm khi kể về cuộc sống của ông thời chiến tranh."},{"en":"We are reading a novel about two brothers after the war.","vi":"Chúng tôi đang đọc một cuốn tiểu thuyết về hai anh em sau chiến tranh."},{"en":"Both sides wanted to end the war as soon as possible.","vi":"Cả hai bên đều muốn chấm dứt chiến tranh càng sớm càng tốt."}]','[{"phrase":"end the war"},{"phrase":"during the war"},{"phrase":"after the war"},{"phrase":"civil war"}]',NULL,'/wɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/war/war__/war__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(417,'ngsl-1-12',27,'account','tài khoản; bản tường thuật','noun','[{"en":"I opened a bank account when I started my first job.","vi":"Tôi mở tài khoản ngân hàng khi bắt đầu công việc đầu tiên."},{"en":"You need an account to buy tickets on this website.","vi":"Bạn cần có tài khoản để mua vé trên trang web này."},{"en":"She gave the police a clear account of what happened.","vi":"Cô ấy đã kể lại rõ ràng với cảnh sát những gì đã xảy ra."}]','[{"phrase":"bank account"},{"phrase":"open an account"},{"phrase":"account of"},{"phrase":"take into account"}]','take something into account: tính đến điều gì','/əˈkaʊnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accou/account__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(418,'ngsl-1-12',28,'shop','cửa hàng; tiệm','noun','[{"en":"There''s a small coffee shop on the corner of our street.","vi":"Có một quán cà phê nhỏ ở góc phố nhà chúng tôi."},{"en":"Most shops in town close at eight in the evening.","vi":"Hầu hết cửa hàng trong thị trấn đóng cửa lúc tám giờ tối."},{"en":"I bought this bag at a little shop near the station.","vi":"Tôi mua chiếc túi này ở một tiệm nhỏ gần nhà ga."}]','[{"phrase":"coffee shop"},{"phrase":"gift shop"},{"phrase":"shop assistant"},{"phrase":"shop window"}]','Anh: shop · Mỹ thường dùng: store','/ʃɑːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shop_/shop__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(419,'ngsl-1-12',29,'major','lớn; chủ yếu, quan trọng','adjective','[{"en":"Traffic is a major problem in big cities.","vi":"Giao thông là một vấn đề lớn ở các thành phố lớn."},{"en":"The company made major changes to its website this year.","vi":"Năm nay công ty đã thay đổi lớn trang web của mình."},{"en":"Rice is the major crop in this part of the country.","vi":"Lúa là cây trồng chủ yếu ở vùng này của đất nước."}]','[{"phrase":"major problem"},{"phrase":"major role"},{"phrase":"major changes"},{"phrase":"major city"}]',NULL,'/ˈmeɪdʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/maj/major/major__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(420,'ngsl-1-12',30,'someone','ai đó; người nào đó','pronoun','[{"en":"Someone left their umbrella in the classroom.","vi":"Ai đó đã để quên ô trong lớp học."},{"en":"I need someone to help me move this sofa.","vi":"Tôi cần người nào đó giúp tôi chuyển cái ghế sofa này."},{"en":"I think there''s someone at the front door.","vi":"Hình như có ai đó ở cửa trước."}]','[{"phrase":"someone else"},{"phrase":"talk to someone"},{"phrase":"meet someone"}]','someone = somebody','/ˈsʌmwʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/someo/someone__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(421,'ngsl-1-13',1,'above','ở trên; trên, hơn','preposition','[{"en":"There is a small shelf above my desk for books.","vi":"Có một kệ sách nhỏ phía trên bàn làm việc của tôi."},{"en":"Her test scores are always above average.","vi":"Điểm kiểm tra của cô ấy luôn trên mức trung bình."},{"en":"We live in the apartment above the bakery.","vi":"Chúng tôi sống trong căn hộ phía trên tiệm bánh."}]','[{"phrase":"above average"},{"phrase":"above all"},{"phrase":"above sea level"}]',NULL,'/əˈbʌv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abo/above/above__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(422,'ngsl-1-13',2,'design','thiết kế; mẫu thiết kế','noun','[{"en":"I really like the design of your new kitchen.","vi":"Tôi rất thích thiết kế căn bếp mới của bạn."},{"en":"She studied graphic design at college for three years.","vi":"Cô ấy đã học thiết kế đồ họa ở trường đại học trong ba năm."},{"en":"The shirt comes in two different designs.","vi":"Chiếc áo sơ mi này có hai mẫu thiết kế khác nhau."}]','[{"phrase":"graphic design"},{"phrase":"interior design"},{"phrase":"a simple design"},{"phrase":"new design"}]',NULL,'/dɪˈzaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desig/design__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(423,'ngsl-1-13',3,'event','sự kiện','noun','[{"en":"The school is holding a special event for parents on Friday.","vi":"Trường sẽ tổ chức một sự kiện đặc biệt dành cho phụ huynh vào thứ Sáu."},{"en":"Getting married is one of the biggest events in life.","vi":"Kết hôn là một trong những sự kiện lớn nhất trong đời."},{"en":"We bought tickets for the event months in advance.","vi":"Chúng tôi đã mua vé cho sự kiện từ nhiều tháng trước."}]','[{"phrase":"hold an event"},{"phrase":"a special event"},{"phrase":"sporting event"},{"phrase":"major event"}]',NULL,'/ɪˈvent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/event/event__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(424,'ngsl-1-13',4,'special','đặc biệt; riêng','adjective','[{"en":"We only use these plates on special occasions.","vi":"Chúng tôi chỉ dùng những chiếc đĩa này vào những dịp đặc biệt."},{"en":"The restaurant has a special menu for children.","vi":"Nhà hàng có thực đơn riêng cho trẻ em."},{"en":"You don''t need any special tools to fix this.","vi":"Bạn không cần dụng cụ đặc biệt nào để sửa cái này."}]','[{"phrase":"special occasion"},{"phrase":"special offer"},{"phrase":"something special"},{"phrase":"special attention"}]',NULL,'/ˈspeʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/special__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(425,'ngsl-1-13',5,'sometimes','đôi khi; thỉnh thoảng','adverb','[{"en":"I sometimes walk to work when the weather is nice.","vi":"Thỉnh thoảng tôi đi bộ đi làm khi trời đẹp."},{"en":"Sometimes it''s better to say nothing at all.","vi":"Đôi khi tốt hơn hết là không nói gì cả."},{"en":"My little brother sometimes even forgets his own birthday.","vi":"Em trai tôi đôi khi còn quên cả sinh nhật của chính mình."}]','[{"phrase":"sometimes even"},{"phrase":"only sometimes"}]',NULL,'/ˈsʌmtaɪmz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somet/sometimes__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(426,'ngsl-1-13',6,'condition','tình trạng; điều kiện','noun','[{"en":"The old car is still in good condition.","vi":"Chiếc xe cũ vẫn còn trong tình trạng tốt."},{"en":"Many workers complained about their poor working conditions.","vi":"Nhiều công nhân phàn nàn về điều kiện làm việc tồi tệ của họ."},{"en":"You can borrow my laptop on one condition: be careful with it.","vi":"Bạn có thể mượn máy tính xách tay của tôi với một điều kiện: hãy cẩn thận với nó."}]','[{"phrase":"in good condition"},{"phrase":"working conditions"},{"phrase":"weather conditions"},{"phrase":"on one condition"}]',NULL,'/kənˈdɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcond/xcondition__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(427,'ngsl-1-13',7,'carry','mang, xách; chở','verb','[{"en":"Can you help me carry these bags upstairs?","vi":"Bạn có thể giúp tôi xách mấy cái túi này lên lầu không?"},{"en":"Do you always carry an umbrella in your bag?","vi":"Bạn có luôn mang theo ô trong túi không?"},{"en":"The bus can carry up to fifty passengers.","vi":"Chiếc xe buýt có thể chở tối đa năm mươi hành khách."}]','[{"phrase":"carry a bag"},{"phrase":"carry an umbrella"},{"phrase":"carry passengers"}]',NULL,'/ˈkæri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/carry/carry__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(428,'ngsl-1-13',8,'choose','chọn; quyết định','verb','[{"en":"It took me an hour to choose a birthday gift.","vi":"Tôi mất một tiếng để chọn một món quà sinh nhật."},{"en":"You can choose between tea and coffee.","vi":"Bạn có thể chọn giữa trà và cà phê."},{"en":"She chose to stay home instead of going out.","vi":"Cô ấy quyết định ở nhà thay vì ra ngoài."}]','[{"phrase":"choose between"},{"phrase":"choose carefully"},{"phrase":"free to choose"}]','choose – chose – chosen','/tʃuːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cho/choos/choose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(429,'ngsl-1-13',9,'father','bố, cha','noun','[{"en":"My father taught me how to ride a bike.","vi":"Bố tôi đã dạy tôi cách đi xe đạp."},{"en":"He''s excited to become a father next spring.","vi":"Anh ấy rất háo hức vì sắp được làm bố vào mùa xuân tới."},{"en":"Her father works as a nurse at the city hospital.","vi":"Bố cô ấy làm y tá ở bệnh viện thành phố."}]','[{"phrase":"become a father"},{"phrase":"father and son"},{"phrase":"a proud father"}]',NULL,'/ˈfɑːðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fat/fathe/father__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(430,'ngsl-1-13',10,'decision','quyết định','noun','[{"en":"Moving to a new city was a difficult decision.","vi":"Chuyển đến một thành phố mới là một quyết định khó khăn."},{"en":"We need to make a decision by Friday.","vi":"Chúng ta cần đưa ra quyết định trước thứ Sáu."},{"en":"I think you made the right decision.","vi":"Tôi nghĩ bạn đã đưa ra quyết định đúng đắn."}]','[{"phrase":"make a decision"},{"phrase":"the right decision"},{"phrase":"a difficult decision"},{"phrase":"final decision"}]',NULL,'/dɪˈsɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decis/decision__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(431,'ngsl-1-13',11,'table','cái bàn; bảng (số liệu)','noun','[{"en":"Please put the plates on the kitchen table.","vi":"Hãy đặt những cái đĩa lên bàn bếp."},{"en":"I booked a table for four at seven o''clock.","vi":"Tôi đã đặt một bàn cho bốn người lúc bảy giờ."},{"en":"The table below shows the prices for each room.","vi":"Bảng dưới đây cho thấy giá của từng phòng."}]','[{"phrase":"kitchen table"},{"phrase":"book a table"},{"phrase":"set the table"},{"phrase":"at the table"}]',NULL,'/ˈteɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tab/table/table__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(432,'ngsl-1-13',12,'certain','chắc chắn; nhất định','adjective','[{"en":"Are you certain that you locked the front door?","vi":"Bạn có chắc là mình đã khóa cửa trước không?"},{"en":"The store is only open on certain days of the week.","vi":"Cửa hàng chỉ mở cửa vào một số ngày nhất định trong tuần."},{"en":"It takes a certain amount of time to learn a new language.","vi":"Cần một khoảng thời gian nhất định để học một ngôn ngữ mới."}]','[{"phrase":"a certain amount"},{"phrase":"for certain"},{"phrase":"almost certain"}]',NULL,'/ˈsɜːrtn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cer/certa/certain__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(433,'ngsl-1-13',13,'forward','về phía trước; tới trước','adverb','[{"en":"She leaned forward to hear what he was saying.","vi":"Cô ấy nghiêng người về phía trước để nghe anh ấy đang nói gì."},{"en":"Please take one step forward when I call your name.","vi":"Khi tôi gọi tên, hãy bước lên phía trước một bước."},{"en":"The line moved forward slowly as the doors opened.","vi":"Hàng người chậm rãi tiến lên phía trước khi cửa mở ra."}]','[{"phrase":"step forward"},{"phrase":"move forward"},{"phrase":"lean forward"},{"phrase":"look forward to"}]','look forward to + V-ing: mong chờ','/ˈfɔːrwərd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forwa/forward__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(434,'ngsl-1-13',14,'main','chính; chủ yếu','adjective','[{"en":"The main entrance is on the other side of the building.","vi":"Lối vào chính ở phía bên kia tòa nhà."},{"en":"What is the main reason you want this job?","vi":"Lý do chính khiến bạn muốn công việc này là gì?"},{"en":"Chicken is the main ingredient in this soup.","vi":"Thịt gà là nguyên liệu chính của món súp này."}]','[{"phrase":"main reason"},{"phrase":"main road"},{"phrase":"main entrance"},{"phrase":"main course"}]',NULL,'/meɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/main_/main__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(435,'ngsl-1-13',15,'die','chết, qua đời; hết pin, tắt','verb','[{"en":"My grandfather died when I was ten years old.","vi":"Ông tôi qua đời khi tôi mười tuổi."},{"en":"All the plants died because nobody watered them.","vi":"Tất cả cây cối đều chết vì không ai tưới nước."},{"en":"My laptop battery died in the middle of the meeting.","vi":"Máy tính xách tay của tôi hết pin giữa buổi họp."}]','[{"phrase":"die of"},{"phrase":"die young"},{"phrase":"the battery died"}]','die – died – died; V-ing: dying','/daɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/die/die__/die__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(436,'ngsl-1-13',16,'bear','chịu đựng; chịu (chi phí, trách nhiệm)','verb','[{"en":"I can''t bear the noise from the building site next door.","vi":"Tôi không chịu nổi tiếng ồn từ công trường bên cạnh."},{"en":"She couldn''t bear to see her children so unhappy.","vi":"Cô ấy không chịu nổi khi thấy các con mình buồn như vậy."},{"en":"The company will bear the cost of your training.","vi":"Công ty sẽ chịu chi phí đào tạo cho bạn."}]','[{"phrase":"can''t bear"},{"phrase":"bear the cost"},{"phrase":"bear in mind"}]','bear – bore – borne; danh từ: con gấu','/ber/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/bear_/bear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(437,'ngsl-1-13',17,'cut','cắt; cắt giảm','verb','[{"en":"Can you cut the cake into eight pieces?","vi":"Bạn có thể cắt bánh thành tám miếng không?"},{"en":"I cut my finger while I was cooking dinner.","vi":"Tôi bị đứt tay khi đang nấu bữa tối."},{"en":"The company plans to cut costs next year.","vi":"Công ty dự định cắt giảm chi phí vào năm tới."}]','[{"phrase":"cut costs"},{"phrase":"cut in half"},{"phrase":"cut into pieces"}]','cut – cut – cut','/kʌt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cut/cut__/cut__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(438,'ngsl-1-13',18,'describe','mô tả, miêu tả','verb','[{"en":"Can you describe the man you saw last night?","vi":"Bạn có thể mô tả người đàn ông bạn thấy tối qua không?"},{"en":"She described her new job as busy but exciting.","vi":"Cô ấy mô tả công việc mới của mình là bận rộn nhưng thú vị."},{"en":"It''s hard to describe how beautiful the view was.","vi":"Thật khó để miêu tả khung cảnh đẹp đến mức nào."}]','[{"phrase":"describe in detail"},{"phrase":"hard to describe"},{"phrase":"accurately describe"}]',NULL,'/dɪˈskraɪb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/descr/describe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(439,'ngsl-1-13',19,'available','có sẵn; còn trống; rảnh','adjective','[{"en":"Tickets are available online or at the front desk.","vi":"Vé có bán trên mạng hoặc tại quầy lễ tân."},{"en":"Is the manager available to talk right now?","vi":"Quản lý có rảnh để nói chuyện bây giờ không?"},{"en":"Sorry, there are no rooms available this weekend.","vi":"Xin lỗi, cuối tuần này không còn phòng trống."}]','[{"phrase":"available online"},{"phrase":"widely available"},{"phrase":"freely available"},{"phrase":"readily available"}]',NULL,'/əˈveɪləbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ava/avail/available__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(440,'ngsl-1-13',20,'especially','đặc biệt là, nhất là; dành riêng','adverb','[{"en":"I love fruit, especially mangoes and bananas.","vi":"Tôi thích trái cây, nhất là xoài và chuối."},{"en":"The roads are very busy, especially in the morning.","vi":"Đường xá rất đông đúc, nhất là vào buổi sáng."},{"en":"This cake was made especially for your birthday.","vi":"Chiếc bánh này được làm riêng cho sinh nhật của bạn."}]','[{"phrase":"especially for"},{"phrase":"especially when"},{"phrase":"especially important"}]',NULL,'/ɪˈspeʃəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/esp/espec/especially__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(441,'ngsl-1-13',21,'strong','mạnh; khỏe; đậm','adjective','[{"en":"He''s strong enough to lift the sofa by himself.","vi":"Anh ấy đủ khỏe để tự mình nâng chiếc ghế sofa."},{"en":"A strong wind blew the leaves off the trees.","vi":"Một cơn gió mạnh thổi lá rụng khỏi cây."},{"en":"I like my coffee strong with no sugar.","vi":"Tôi thích cà phê đậm và không đường."}]','[{"phrase":"strong wind"},{"phrase":"strong coffee"},{"phrase":"a strong smell"},{"phrase":"strong enough"}]',NULL,'/strɔːŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stron/strong__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(442,'ngsl-1-13',22,'rise','tăng; mọc, bốc lên','verb','[{"en":"In summer, the sun rises before five o''clock.","vi":"Vào mùa hè, mặt trời mọc trước năm giờ sáng."},{"en":"House prices have risen quickly in the past few years.","vi":"Giá nhà đã tăng nhanh trong vài năm qua."},{"en":"We watched the smoke rise slowly into the sky.","vi":"Chúng tôi nhìn làn khói từ từ bốc lên trời."}]','[{"phrase":"the sun rises"},{"phrase":"prices rise"},{"phrase":"rise sharply"}]','rise – rose – risen','/raɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ris/rise_/rise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(443,'ngsl-1-13',23,'girl','cô gái; bé gái; con gái','noun','[{"en":"There are ten boys and twelve girls in my class.","vi":"Lớp tôi có mười bạn nam và mười hai bạn nữ."},{"en":"Their little girl just started school this year.","vi":"Con gái nhỏ của họ vừa mới bắt đầu đi học năm nay."},{"en":"The girl at the front desk gave us our room keys.","vi":"Cô gái ở quầy lễ tân đưa chìa khóa phòng cho chúng tôi."}]','[{"phrase":"little girl"},{"phrase":"young girl"},{"phrase":"baby girl"},{"phrase":"teenage girl"}]',NULL,'/ɡɜːrl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gir/girl_/girl__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(444,'ngsl-1-13',24,'maybe','có lẽ; có thể','adverb','[{"en":"Maybe we should take a taxi because it''s raining.","vi":"Có lẽ chúng ta nên đi taxi vì trời đang mưa."},{"en":"We could go to the beach, or maybe the park.","vi":"Chúng ta có thể đi biển, hoặc có lẽ đi công viên."},{"en":"She isn''t answering her phone, so maybe she''s asleep.","vi":"Cô ấy không nghe máy, nên có lẽ cô ấy đang ngủ."}]','[{"phrase":"or maybe"},{"phrase":"maybe not"},{"phrase":"maybe later"}]',NULL,'/ˈmeɪbi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/may/maybe/maybe__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(445,'ngsl-1-13',25,'community','cộng đồng','noun','[{"en":"Our community is raising money to build a new playground.","vi":"Cộng đồng chúng tôi đang quyên tiền để xây một sân chơi mới."},{"en":"She volunteers at the community center every Saturday.","vi":"Cô ấy làm tình nguyện ở trung tâm cộng đồng vào mỗi thứ Bảy."},{"en":"People in a small community usually know each other well.","vi":"Người dân trong một cộng đồng nhỏ thường biết rõ về nhau."}]','[{"phrase":"local community"},{"phrase":"community center"},{"phrase":"small community"},{"phrase":"community service"}]',NULL,'/kəˈmjuːnəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/community__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(446,'ngsl-1-13',26,'else','khác; nữa','adverb','[{"en":"Would you like anything else to drink?","vi":"Bạn có muốn uống gì nữa không?"},{"en":"Everyone else went home, but I stayed late.","vi":"Mọi người khác đều về nhà, nhưng tôi ở lại muộn."},{"en":"If this shop is closed, let''s try somewhere else.","vi":"Nếu cửa hàng này đóng cửa thì chúng ta thử chỗ khác nhé."}]','[{"phrase":"anything else"},{"phrase":"someone else"},{"phrase":"somewhere else"},{"phrase":"or else"}]',NULL,'/els/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/els/else_/else__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(447,'ngsl-1-13',27,'particular','cụ thể, riêng; đặc biệt','adjective','[{"en":"Is there a particular day that works best for you?","vi":"Có ngày cụ thể nào thuận tiện nhất cho bạn không?"},{"en":"I don''t like this particular brand of coffee.","vi":"Riêng nhãn hiệu cà phê này thì tôi không thích."},{"en":"Nothing in particular happened at work today.","vi":"Hôm nay ở chỗ làm không có gì đặc biệt xảy ra."}]','[{"phrase":"in particular"},{"phrase":"for no particular reason"},{"phrase":"pay particular attention"}]',NULL,'/pərˈtɪkjələr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/particular__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(448,'ngsl-1-13',28,'role','vai trò; vai diễn','noun','[{"en":"Parents play an important role in their children''s education.","vi":"Cha mẹ đóng vai trò quan trọng trong việc học của con cái."},{"en":"She got the main role in the school play.","vi":"Cô ấy được đóng vai chính trong vở kịch của trường."},{"en":"What is your role in the new project?","vi":"Vai trò của bạn trong dự án mới là gì?"}]','[{"phrase":"play a role"},{"phrase":"an important role"},{"phrase":"key role"},{"phrase":"leading role"}]',NULL,'/rəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rol/role_/role__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(449,'ngsl-1-13',29,'join','tham gia, gia nhập; cùng (ai)','verb','[{"en":"My sister joined a tennis club last month.","vi":"Chị tôi đã tham gia một câu lạc bộ quần vợt vào tháng trước."},{"en":"Would you like to join us for dinner tonight?","vi":"Tối nay bạn có muốn ăn tối cùng chúng tôi không?"},{"en":"He joined the company right after he finished college.","vi":"Anh ấy vào làm ở công ty ngay sau khi học xong đại học."}]','[{"phrase":"join a club"},{"phrase":"join us"},{"phrase":"join the team"},{"phrase":"join in"}]',NULL,'/dʒɔɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/joi/join_/join__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(450,'ngsl-1-13',30,'difficult','khó; khó khăn','adjective','[{"en":"The math test was more difficult than I expected.","vi":"Bài kiểm tra toán khó hơn tôi nghĩ."},{"en":"It''s difficult to find a cheap apartment in this city.","vi":"Rất khó tìm được một căn hộ giá rẻ ở thành phố này."},{"en":"Last year was a difficult time for our family.","vi":"Năm ngoái là khoảng thời gian khó khăn đối với gia đình tôi."}]','[{"phrase":"difficult time"},{"phrase":"difficult decision"},{"phrase":"difficult question"},{"phrase":"find it difficult"}]',NULL,'/ˈdɪfɪkəlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffi/difficult__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(451,'ngsl-1-14',1,'please','làm ơn; vui lòng','exclamation','[{"en":"Could you please turn the music down a little?","vi":"Bạn làm ơn vặn nhỏ nhạc một chút được không?"},{"en":"Please take off your shoes before you come inside.","vi":"Vui lòng cởi giày trước khi vào trong."},{"en":"Two coffees and a glass of water, please.","vi":"Làm ơn cho tôi hai cà phê và một ly nước."}]','[{"phrase":"yes, please"},{"phrase":"please sit down"},{"phrase":"please note"}]',NULL,'/pliːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/pleas/please__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(452,'ngsl-1-14',2,'detail','chi tiết','noun','[{"en":"Can you send me more details about the job?","vi":"Bạn có thể gửi cho tôi thêm thông tin chi tiết về công việc không?"},{"en":"She remembers every detail of her wedding day.","vi":"Cô ấy nhớ từng chi tiết của ngày cưới."},{"en":"We will explain the plan in detail at the meeting.","vi":"Chúng tôi sẽ giải thích kế hoạch một cách chi tiết trong buổi họp."}]','[{"phrase":"in detail"},{"phrase":"more details"},{"phrase":"contact details"},{"phrase":"attention to detail"}]',NULL,'/ˈdiːteɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/detai/detail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(453,'ngsl-1-14',3,'difference','sự khác biệt; sự chênh lệch','noun','[{"en":"Can you tell the difference between these two colors?","vi":"Bạn có nhận ra sự khác biệt giữa hai màu này không?"},{"en":"There is a big difference between living in a city and a village.","vi":"Có sự khác biệt lớn giữa việc sống ở thành phố và ở làng quê."},{"en":"The price difference between the two phones is about fifty dollars.","vi":"Chênh lệch giá giữa hai chiếc điện thoại là khoảng năm mươi đô la."}]','[{"phrase":"tell the difference"},{"phrase":"make a difference"},{"phrase":"big difference"},{"phrase":"difference between"}]',NULL,'/ˈdɪfrəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/difference__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(454,'ngsl-1-14',4,'action','hành động','noun','[{"en":"We need to take action before the problem gets worse.","vi":"Chúng ta cần hành động trước khi vấn đề trở nên tồi tệ hơn."},{"en":"Her quick action saved the little boy''s life.","vi":"Hành động nhanh chóng của cô ấy đã cứu sống cậu bé."},{"en":"My brother loves watching action movies on weekends.","vi":"Anh trai tôi thích xem phim hành động vào cuối tuần."}]','[{"phrase":"take action"},{"phrase":"quick action"},{"phrase":"action movie"}]',NULL,'/ˈækʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actio/action__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(455,'ngsl-1-14',5,'health','sức khỏe','noun','[{"en":"Smoking is very bad for your health.","vi":"Hút thuốc rất có hại cho sức khỏe của bạn."},{"en":"My grandmother is in good health for her age.","vi":"So với tuổi của mình, bà tôi vẫn có sức khỏe tốt."},{"en":"Regular exercise improves both your physical and mental health.","vi":"Tập thể dục đều đặn cải thiện cả sức khỏe thể chất lẫn tinh thần."}]','[{"phrase":"good health"},{"phrase":"mental health"},{"phrase":"health care"},{"phrase":"bad for your health"}]','không đếm được','/helθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/healt/health__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(456,'ngsl-1-14',6,'eat','ăn','verb','[{"en":"We usually eat dinner together at seven o''clock.","vi":"Chúng tôi thường ăn tối cùng nhau lúc bảy giờ."},{"en":"Have you eaten anything since breakfast this morning?","vi":"Bạn đã ăn gì từ bữa sáng nay chưa?"},{"en":"She ate too much cake and felt sick afterward.","vi":"Cô ấy ăn quá nhiều bánh và sau đó thấy khó chịu."}]','[{"phrase":"eat dinner"},{"phrase":"eat breakfast"},{"phrase":"eat out"},{"phrase":"eat well"}]','eat – ate – eaten','/iːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eat/eat__/eat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(457,'ngsl-1-14',7,'step','bước; bậc thềm','noun','[{"en":"Watch your step because the floor is wet.","vi":"Cẩn thận bước chân vì sàn nhà bị ướt."},{"en":"The first step is to fill out this form.","vi":"Bước đầu tiên là điền vào mẫu đơn này."},{"en":"The children sat on the front steps eating ice cream.","vi":"Bọn trẻ ngồi ăn kem trên bậc thềm trước nhà."}]','[{"phrase":"first step"},{"phrase":"next step"},{"phrase":"step by step"},{"phrase":"take a step"}]',NULL,'/step/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/step_/step__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(458,'ngsl-1-14',8,'true','đúng, thật; có thật; thật sự','adjective','[{"en":"Is it true that you''re moving to Canada next year?","vi":"Có thật là năm sau bạn sẽ chuyển đến Canada không?"},{"en":"The movie is based on a true story.","vi":"Bộ phim dựa trên một câu chuyện có thật."},{"en":"A true friend will help you when things are hard.","vi":"Một người bạn thật sự sẽ giúp bạn khi gặp khó khăn."}]','[{"phrase":"true story"},{"phrase":"come true"},{"phrase":"true friend"}]',NULL,'/truː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/true_/true__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(459,'ngsl-1-14',9,'phone','điện thoại','noun','[{"en":"Can I borrow your phone for a minute?","vi":"Cho tôi mượn điện thoại của bạn một phút được không?"},{"en":"My mom called me, but my phone was off.","vi":"Mẹ gọi cho tôi nhưng điện thoại của tôi đang tắt."},{"en":"She was on the phone with her sister for an hour.","vi":"Cô ấy nói chuyện điện thoại với chị gái suốt một tiếng."}]','[{"phrase":"phone number"},{"phrase":"phone call"},{"phrase":"on the phone"},{"phrase":"answer the phone"}]',NULL,'/fəʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pho/phone/phone__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(460,'ngsl-1-14',10,'draw','vẽ; kéo; thu hút','verb','[{"en":"My little sister loves to draw animals.","vi":"Em gái tôi rất thích vẽ động vật."},{"en":"She drew the curtains to keep the sunlight out.","vi":"Cô ấy kéo rèm lại để chắn ánh nắng."},{"en":"The street festival drew a large crowd this year.","vi":"Lễ hội đường phố năm nay đã thu hút rất đông người."}]','[{"phrase":"draw a picture"},{"phrase":"draw the curtains"},{"phrase":"draw attention"},{"phrase":"draw a crowd"}]','draw – drew – drawn','/drɔː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/draw_/draw__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(461,'ngsl-1-14',11,'white','trắng; màu trắng','adjective','[{"en":"She wore a white dress to the party.","vi":"Cô ấy mặc một chiếc váy trắng đến bữa tiệc."},{"en":"His hair turned white when he was only fifty.","vi":"Tóc ông ấy bạc trắng khi mới năm mươi tuổi."},{"en":"The walls in my bedroom are painted white.","vi":"Tường phòng ngủ của tôi được sơn màu trắng."}]','[{"phrase":"white shirt"},{"phrase":"white wine"},{"phrase":"black and white"},{"phrase":"turn white"}]',NULL,'/waɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/white/white__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(462,'ngsl-1-14',12,'date','ngày tháng; cuộc hẹn hò','noun','[{"en":"Please write today''s date at the top of the page.","vi":"Vui lòng ghi ngày hôm nay ở đầu trang."},{"en":"Have you set a date for the wedding yet?","vi":"Bạn đã chọn ngày tổ chức đám cưới chưa?"},{"en":"He asked her out on a date last Friday.","vi":"Thứ Sáu tuần trước anh ấy đã mời cô ấy đi hẹn hò."}]','[{"phrase":"date of birth"},{"phrase":"set a date"},{"phrase":"go on a date"}]',NULL,'/deɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/date_/date__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(463,'ngsl-1-14',13,'practice','sự luyện tập; thực tế','noun','[{"en":"Learning a new language takes a lot of practice.","vi":"Học một ngôn ngữ mới cần luyện tập rất nhiều."},{"en":"The team has soccer practice every Tuesday afternoon.","vi":"Đội có buổi tập bóng đá vào mỗi chiều thứ Ba."},{"en":"The idea sounds good, but it may not work in practice.","vi":"Ý tưởng nghe có vẻ hay nhưng trên thực tế có thể không hiệu quả."}]','[{"phrase":"a lot of practice"},{"phrase":"in practice"},{"phrase":"put into practice"}]','Anh: practise (động từ) · Mỹ: practice','/ˈpræktɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pract/practice__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(464,'ngsl-1-14',14,'model','mẫu, kiểu; người mẫu; mô hình','noun','[{"en":"This phone is an older model, but it still works well.","vi":"Chiếc điện thoại này là mẫu cũ nhưng vẫn dùng tốt."},{"en":"She worked as a fashion model before becoming a teacher.","vi":"Cô ấy từng làm người mẫu thời trang trước khi trở thành giáo viên."},{"en":"My son spent all weekend building a model plane.","vi":"Con trai tôi dành cả cuối tuần để lắp ráp một chiếc máy bay mô hình."}]','[{"phrase":"latest model"},{"phrase":"fashion model"},{"phrase":"role model"}]',NULL,'/ˈmɑːdl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/model/model__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(465,'ngsl-1-14',15,'raise','giơ lên, nâng lên; tăng; nuôi nấng','verb','[{"en":"Raise your hand if you have a question.","vi":"Hãy giơ tay nếu bạn có câu hỏi."},{"en":"The company plans to raise prices next month.","vi":"Công ty dự định tăng giá vào tháng tới."},{"en":"She raised three children on her own.","vi":"Cô ấy một mình nuôi ba đứa con."}]','[{"phrase":"raise your hand"},{"phrase":"raise prices"},{"phrase":"raise money"},{"phrase":"raise children"}]','raise + tân ngữ ≠ rise (không có tân ngữ)','/reɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rai/raise/raise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(466,'ngsl-1-14',16,'customer','khách hàng','noun','[{"en":"The store offers free delivery to its regular customers.","vi":"Cửa hàng giao hàng miễn phí cho khách hàng quen."},{"en":"She stayed polite even when the customer started shouting.","vi":"Cô ấy vẫn lịch sự ngay cả khi vị khách bắt đầu la hét."},{"en":"Please call customer service if the product arrives damaged.","vi":"Vui lòng gọi bộ phận chăm sóc khách hàng nếu sản phẩm bị hư hỏng khi đến nơi."}]','[{"phrase":"customer service"},{"phrase":"regular customer"},{"phrase":"new customers"}]',NULL,'/ˈkʌstəmər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cus/custo/customer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(467,'ngsl-1-14',17,'front','phía trước; mặt trước','noun','[{"en":"Let''s sit at the front so we can see better.","vi":"Chúng ta ngồi ở phía trước để nhìn rõ hơn nhé."},{"en":"There is a small garden in front of our house.","vi":"Có một khu vườn nhỏ ở phía trước nhà chúng tôi."},{"en":"Write your name on the front of the envelope.","vi":"Hãy viết tên bạn ở mặt trước phong bì."}]','[{"phrase":"in front of"},{"phrase":"at the front"},{"phrase":"front door"},{"phrase":"front seat"}]',NULL,'/frʌnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fro/front/front__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(468,'ngsl-1-14',18,'explain','giải thích','verb','[{"en":"Can you explain how this machine works?","vi":"Bạn có thể giải thích cái máy này hoạt động thế nào không?"},{"en":"The teacher explained the rules of the game again.","vi":"Giáo viên giải thích lại luật chơi một lần nữa."},{"en":"He never explained why he left the party so early.","vi":"Anh ấy chưa bao giờ giải thích tại sao anh ấy rời bữa tiệc sớm như vậy."}]','[{"phrase":"explain why"},{"phrase":"explain how"},{"phrase":"clearly explain"},{"phrase":"explain the reason"}]','explain something to someone (không nói: explain someone something)','/ɪkˈspleɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expla/explain__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(469,'ngsl-1-14',19,'door','cửa ra vào','noun','[{"en":"Please close the door when you leave.","vi":"Vui lòng đóng cửa khi bạn ra về."},{"en":"I think someone is knocking at the front door.","vi":"Hình như có ai đang gõ cửa trước."},{"en":"Our new neighbors live right next door.","vi":"Hàng xóm mới của chúng tôi sống ngay nhà bên cạnh."}]','[{"phrase":"open the door"},{"phrase":"close the door"},{"phrase":"front door"},{"phrase":"next door"}]',NULL,'/dɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doo/door_/door__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(470,'ngsl-1-14',20,'outside','bên ngoài; ra ngoài','adverb','[{"en":"The kids are playing outside in the garden.","vi":"Bọn trẻ đang chơi bên ngoài vườn."},{"en":"It''s too cold to go outside today.","vi":"Hôm nay trời quá lạnh để ra ngoài."},{"en":"Please wait outside until the doctor calls your name.","vi":"Vui lòng đợi bên ngoài cho đến khi bác sĩ gọi tên bạn."}]','[{"phrase":"go outside"},{"phrase":"wait outside"},{"phrase":"play outside"}]',NULL,'/ˌaʊtˈsaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outsi/outside__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(471,'ngsl-1-14',21,'behind','phía sau, đằng sau; tụt lại phía sau','preposition','[{"en":"The cat is hiding behind the sofa.","vi":"Con mèo đang trốn sau ghế sofa."},{"en":"There is a small park behind the school.","vi":"Có một công viên nhỏ phía sau trường học."},{"en":"She was sick for a week and fell behind in class.","vi":"Cô ấy bị ốm một tuần nên bị tụt lại so với cả lớp."}]','[{"phrase":"behind the house"},{"phrase":"right behind"},{"phrase":"fall behind"},{"phrase":"leave behind"}]',NULL,'/bɪˈhaɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beh/behin/behind__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(472,'ngsl-1-14',22,'economic','kinh tế','adjective','[{"en":"The country has seen strong economic growth this year.","vi":"Đất nước đã đạt mức tăng trưởng kinh tế mạnh mẽ trong năm nay."},{"en":"Many families are struggling because of the economic crisis.","vi":"Nhiều gia đình đang gặp khó khăn vì khủng hoảng kinh tế."},{"en":"The new factory will bring economic benefits to the town.","vi":"Nhà máy mới sẽ mang lại lợi ích kinh tế cho thị trấn."}]','[{"phrase":"economic growth"},{"phrase":"economic crisis"},{"phrase":"economic development"},{"phrase":"economic policy"}]','economic (kinh tế) ≠ economical (tiết kiệm)','/ˌiːkəˈnɑːmɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eco/econo/economic__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(473,'ngsl-1-14',23,'site','địa điểm, khu đất; công trường; trang web','noun','[{"en":"They chose a quiet site near the river for the new school.","vi":"Họ đã chọn một khu đất yên tĩnh gần sông để xây trường mới."},{"en":"Workers must wear helmets at the construction site.","vi":"Công nhân phải đội mũ bảo hộ tại công trường."},{"en":"You can find more information on the company''s site.","vi":"Bạn có thể tìm thêm thông tin trên trang web của công ty."}]','[{"phrase":"construction site"},{"phrase":"on site"},{"phrase":"historic site"}]',NULL,'/saɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/site_/site__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(474,'ngsl-1-14',24,'approach','cách tiếp cận, phương pháp; sự đến gần','noun','[{"en":"Her teacher has a very creative approach to teaching math.","vi":"Giáo viên của cô ấy có cách tiếp cận rất sáng tạo trong việc dạy toán."},{"en":"If this plan doesn''t work, we''ll try a different approach.","vi":"Nếu kế hoạch này không hiệu quả, chúng ta sẽ thử một cách tiếp cận khác."},{"en":"With the approach of winter, the days are getting shorter.","vi":"Khi mùa đông đến gần, ngày ngắn dần đi."}]','[{"phrase":"different approach"},{"phrase":"new approach"},{"phrase":"approach to"},{"phrase":"take an approach"}]','Động từ: approach (tiến lại gần)','/əˈprəʊtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(475,'ngsl-1-14',25,'teacher','giáo viên','noun','[{"en":"My English teacher gives us homework every day.","vi":"Giáo viên tiếng Anh của tôi giao bài tập về nhà mỗi ngày."},{"en":"She wants to become a teacher after she finishes college.","vi":"Cô ấy muốn trở thành giáo viên sau khi học xong đại học."},{"en":"Ask your teacher if you don''t understand the lesson.","vi":"Hãy hỏi giáo viên nếu bạn không hiểu bài."}]','[{"phrase":"English teacher"},{"phrase":"math teacher"},{"phrase":"good teacher"},{"phrase":"become a teacher"}]',NULL,'/ˈtiːtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/teach/teacher__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(476,'ngsl-1-14',26,'land','đất, đất đai; đất liền','noun','[{"en":"My grandparents own some land in the countryside.","vi":"Ông bà tôi có một mảnh đất ở quê."},{"en":"The land here is good for growing rice.","vi":"Đất ở đây rất tốt để trồng lúa."},{"en":"After two weeks at sea, the sailors were happy to see land.","vi":"Sau hai tuần trên biển, các thủy thủ vui mừng khi nhìn thấy đất liền."}]','[{"phrase":"piece of land"},{"phrase":"on land"},{"phrase":"buy land"}]','không đếm được · Động từ: land (hạ cánh)','/lænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lan/land_/land__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(477,'ngsl-1-14',27,'charge','phí; sự phụ trách','noun','[{"en":"There is no charge for children under five.","vi":"Trẻ em dưới năm tuổi được miễn phí."},{"en":"Who is in charge of this project while the manager is away?","vi":"Ai phụ trách dự án này khi quản lý đi vắng?"},{"en":"The hotel adds a small charge for late checkout.","vi":"Khách sạn tính thêm một khoản phí nhỏ nếu trả phòng muộn."}]','[{"phrase":"in charge of"},{"phrase":"free of charge"},{"phrase":"extra charge"},{"phrase":"service charge"}]','Động từ: charge (tính phí; sạc pin)','/tʃɑːrdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/charg/charge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(478,'ngsl-1-14',28,'finally','cuối cùng; sau cùng','adverb','[{"en":"After three hours of waiting, the bus finally arrived.","vi":"Sau ba tiếng chờ đợi, cuối cùng xe buýt cũng đến."},{"en":"I finally finished reading that long book last night.","vi":"Tối qua cuối cùng tôi cũng đọc xong cuốn sách dài đó."},{"en":"Finally, add some salt and serve the soup hot.","vi":"Sau cùng, thêm chút muối và dùng súp khi còn nóng."}]','[{"phrase":"finally arrive"},{"phrase":"finally decide"},{"phrase":"finally realize"}]',NULL,'/ˈfaɪnəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/final/finally__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(479,'ngsl-1-14',29,'sign','biển báo; dấu hiệu','noun','[{"en":"Follow the signs to the train station.","vi":"Hãy đi theo các biển chỉ dẫn đến ga tàu."},{"en":"A high fever can be a sign of a serious illness.","vi":"Sốt cao có thể là dấu hiệu của một căn bệnh nghiêm trọng."},{"en":"Dark clouds are often a sign that rain is coming.","vi":"Mây đen thường là dấu hiệu sắp có mưa."}]','[{"phrase":"road sign"},{"phrase":"warning sign"},{"phrase":"a sign of"},{"phrase":"follow the signs"}]','Động từ: sign (ký tên)','/saɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/sign_/sign__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(480,'ngsl-2-01',1,'claim','khẳng định, cho rằng; đòi, yêu cầu','verb','[{"en":"He claims that he saw a ghost in the old house.","vi":"Anh ấy khẳng định đã nhìn thấy ma trong ngôi nhà cũ."},{"en":"The company claims its new phone battery lasts two days.","vi":"Công ty cho rằng pin điện thoại mới của họ dùng được hai ngày."},{"en":"You can claim the cost of the taxi back from your company.","vi":"Bạn có thể đòi công ty hoàn lại tiền taxi."}]','[{"phrase":"claim that"},{"phrase":"claim to be"},{"phrase":"claim compensation"},{"phrase":"claim back"}]',NULL,'/kleɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/claim/claim__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(481,'ngsl-2-01',2,'relationship','mối quan hệ; mối tình','noun','[{"en":"She has a very close relationship with her grandmother.","vi":"Cô ấy có mối quan hệ rất gắn bó với bà của mình."},{"en":"Good communication is important in any relationship.","vi":"Giao tiếp tốt rất quan trọng trong bất kỳ mối quan hệ nào."},{"en":"Are you in a relationship, or are you still single?","vi":"Bạn đang có người yêu hay vẫn còn độc thân?"}]','[{"phrase":"close relationship"},{"phrase":"relationship with"},{"phrase":"in a relationship"},{"phrase":"build a relationship"}]',NULL,'/rɪˈleɪʃnʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relationship__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(482,'ngsl-2-01',3,'travel','đi du lịch; đi lại, di chuyển','verb','[{"en":"We love to travel abroad during the summer holidays.","vi":"Chúng tôi thích đi du lịch nước ngoài vào kỳ nghỉ hè."},{"en":"My father travels a lot for work.","vi":"Bố tôi đi công tác rất nhiều."},{"en":"It takes an hour to travel from my house to the city center.","vi":"Đi từ nhà tôi đến trung tâm thành phố mất một tiếng."}]','[{"phrase":"travel abroad"},{"phrase":"travel around the world"},{"phrase":"travel by train"},{"phrase":"travel a lot"}]','Anh: travelled · Mỹ: traveled','/ˈtrævl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trave/travel__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(483,'ngsl-2-01',4,'enjoy','thích, thưởng thức; tận hưởng','verb','[{"en":"I really enjoy cooking for my friends on weekends.","vi":"Tôi rất thích nấu ăn cho bạn bè vào cuối tuần."},{"en":"Did you enjoy the movie last night?","vi":"Tối qua bạn xem phim có thích không?"},{"en":"Enjoy your vacation, and send us some photos!","vi":"Chúc bạn tận hưởng kỳ nghỉ, nhớ gửi cho chúng tôi vài tấm ảnh nhé!"}]','[{"phrase":"enjoy yourself"},{"phrase":"really enjoy"},{"phrase":"enjoy doing something"},{"phrase":"enjoy your meal"}]','enjoy + V-ing (enjoy reading)','/ɪnˈdʒɔɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enj/enjoy/enjoy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(484,'ngsl-2-01',5,'death','cái chết; sự qua đời','noun','[{"en":"Smoking is a major cause of death in many countries.","vi":"Hút thuốc là một nguyên nhân gây tử vong hàng đầu ở nhiều nước."},{"en":"After his wife''s death, he moved closer to his children.","vi":"Sau khi vợ mất, ông ấy chuyển đến sống gần các con hơn."},{"en":"Nobody knows the exact date of the writer''s death.","vi":"Không ai biết chính xác ngày mất của nhà văn."}]','[{"phrase":"cause of death"},{"phrase":"life and death"},{"phrase":"sudden death"},{"phrase":"after his death"}]','die (v) – dead (adj) – death (n)','/deθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/death/death__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(485,'ngsl-2-01',6,'nice','đẹp, dễ chịu; tốt bụng, tử tế','adjective','[{"en":"It''s a nice day, so let''s have lunch outside.","vi":"Hôm nay trời đẹp, mình ăn trưa ngoài trời đi."},{"en":"Our new neighbors are really nice people.","vi":"Hàng xóm mới của chúng tôi là những người rất tốt bụng."},{"en":"It was nice of you to help me with my bags.","vi":"Bạn thật tử tế khi giúp tôi mang túi."}]','[{"phrase":"nice to meet you"},{"phrase":"have a nice day"},{"phrase":"nice of you"},{"phrase":"really nice"}]',NULL,'/naɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nic/nice_/nice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(486,'ngsl-2-01',7,'amount','lượng, số lượng; số tiền','noun','[{"en":"You should drink a large amount of water in hot weather.","vi":"Bạn nên uống nhiều nước khi trời nóng."},{"en":"The total amount on the bill was higher than we expected.","vi":"Tổng số tiền trên hóa đơn cao hơn chúng tôi dự tính."},{"en":"She spends a huge amount of time on her phone.","vi":"Cô ấy dành rất nhiều thời gian cho điện thoại."}]','[{"phrase":"a large amount of"},{"phrase":"a small amount of"},{"phrase":"total amount"},{"phrase":"amount of time"}]','amount of + danh từ không đếm được (money, time)','/əˈmaʊnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/amo/amoun/amount__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(487,'ngsl-2-01',8,'improve','cải thiện; tiến bộ','verb','[{"en":"I watch English movies to improve my listening skills.","vi":"Tôi xem phim tiếng Anh để cải thiện kỹ năng nghe."},{"en":"His health has improved a lot since he started exercising.","vi":"Sức khỏe của anh ấy đã cải thiện nhiều từ khi bắt đầu tập thể dục."},{"en":"Your writing is improving every week, so keep practicing.","vi":"Bài viết của bạn tiến bộ từng tuần, cứ tiếp tục luyện tập nhé."}]','[{"phrase":"improve skills"},{"phrase":"greatly improve"},{"phrase":"improve the quality"},{"phrase":"improve your English"}]',NULL,'/ɪmˈpruːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impro/improve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(488,'ngsl-2-01',9,'picture','bức tranh, bức ảnh; hình dung','noun','[{"en":"Can you take a picture of us in front of the lake?","vi":"Bạn chụp giúp chúng tôi một tấm ảnh trước hồ được không?"},{"en":"There is a beautiful picture of the sea on the wall.","vi":"Trên tường có một bức tranh biển rất đẹp."},{"en":"This book gives a clear picture of life in the countryside.","vi":"Cuốn sách này cho ta một hình dung rõ ràng về cuộc sống ở nông thôn."}]','[{"phrase":"take a picture"},{"phrase":"draw a picture"},{"phrase":"clear picture"},{"phrase":"paint a picture"}]',NULL,'/ˈpɪktʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pic/pictu/picture__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(489,'ngsl-2-01',10,'boy','cậu bé, con trai','noun','[{"en":"The little boy is playing with his dog in the yard.","vi":"Cậu bé đang chơi với con chó của mình ngoài sân."},{"en":"They have two boys and a girl.","vi":"Họ có hai con trai và một con gái."},{"en":"When I was a boy, I walked to school every day.","vi":"Hồi còn nhỏ, ngày nào tôi cũng đi bộ đến trường."}]','[{"phrase":"little boy"},{"phrase":"baby boy"},{"phrase":"teenage boy"},{"phrase":"boys and girls"}]',NULL,'/bɔɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boy/boy__/boy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(490,'ngsl-2-01',11,'regard','coi (là), xem (như); đánh giá','verb','[{"en":"Many people regard her as the best teacher in the school.","vi":"Nhiều người coi cô ấy là giáo viên giỏi nhất trường."},{"en":"This area was once regarded as unsafe at night.","vi":"Khu này từng bị xem là không an toàn vào ban đêm."},{"en":"My parents have always regarded education as very important.","vi":"Bố mẹ tôi luôn coi việc học là rất quan trọng."}]','[{"phrase":"regard as"},{"phrase":"widely regarded"},{"phrase":"highly regarded"},{"phrase":"with regard to"}]','regard somebody/something as ... (coi ai/cái gì là ...)','/rɪˈɡɑːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regar/regard__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(491,'ngsl-2-01',12,'organization','tổ chức; sự sắp xếp','noun','[{"en":"She works for an organization that helps homeless families.","vi":"Cô ấy làm việc cho một tổ chức giúp đỡ các gia đình vô gia cư."},{"en":"Many organizations offer free English classes for adults.","vi":"Nhiều tổ chức mở lớp tiếng Anh miễn phí cho người lớn."},{"en":"Good organization will help you finish the project on time.","vi":"Sắp xếp tốt sẽ giúp bạn hoàn thành dự án đúng hạn."}]','[{"phrase":"non-profit organization"},{"phrase":"international organization"},{"phrase":"charity organization"},{"phrase":"work for an organization"}]','Anh: organisation · Mỹ: organization','/ˌɔːrɡənəˈzeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/org/organ/organization__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(492,'ngsl-2-01',13,'happy','vui, hạnh phúc; hài lòng; sẵn lòng','adjective','[{"en":"The children were very happy to see their grandparents.","vi":"Bọn trẻ rất vui khi gặp ông bà."},{"en":"Are you happy with your new apartment?","vi":"Bạn có hài lòng với căn hộ mới không?"},{"en":"I''m happy to help if you need anything.","vi":"Nếu bạn cần gì, tôi sẵn lòng giúp."}]','[{"phrase":"happy birthday"},{"phrase":"happy with"},{"phrase":"happy to help"},{"phrase":"make someone happy"}]',NULL,'/ˈhæpi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hap/happy/happy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(493,'ngsl-2-01',14,'couple','cặp, đôi (vợ chồng, người yêu); vài','noun','[{"en":"A young couple just moved into the house next door.","vi":"Một cặp vợ chồng trẻ vừa chuyển đến ngôi nhà bên cạnh."},{"en":"Can you wait a couple of minutes?","vi":"Bạn đợi vài phút được không?"},{"en":"We went to the beach a couple of times last summer.","vi":"Mùa hè năm ngoái chúng tôi đi biển vài lần."}]','[{"phrase":"a couple of"},{"phrase":"young couple"},{"phrase":"married couple"},{"phrase":"elderly couple"}]','a couple of = hai hoặc vài','/ˈkʌpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/coupl/couple__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(494,'ngsl-2-01',15,'act','hành động; cư xử; đóng vai','verb','[{"en":"We need to act quickly before the problem gets worse.","vi":"Chúng ta cần hành động nhanh trước khi vấn đề trở nên tệ hơn."},{"en":"Stop acting like a child and listen to me.","vi":"Đừng cư xử như trẻ con nữa và nghe tôi nói đây."},{"en":"She acted in several school plays when she was young.","vi":"Hồi nhỏ cô ấy từng diễn trong vài vở kịch ở trường."}]','[{"phrase":"act quickly"},{"phrase":"act like"},{"phrase":"act as"},{"phrase":"act fast"}]',NULL,'/ækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/act__/act__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(495,'ngsl-2-01',16,'range','loạt, nhiều loại; phạm vi, khoảng','noun','[{"en":"The shop sells a wide range of shoes for children.","vi":"Cửa hàng bán rất nhiều loại giày cho trẻ em."},{"en":"This apartment is out of our price range.","vi":"Căn hộ này vượt quá khoảng giá chúng tôi có thể chi trả."},{"en":"Most of the students in this class are in the 12 to 15 age range.","vi":"Phần lớn học sinh lớp này ở độ tuổi từ 12 đến 15."}]','[{"phrase":"a wide range of"},{"phrase":"price range"},{"phrase":"age range"},{"phrase":"range of products"}]',NULL,'/reɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/range/range__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(496,'ngsl-2-01',17,'quality','chất lượng; phẩm chất','noun','[{"en":"The food here is cheap, but the quality is excellent.","vi":"Đồ ăn ở đây rẻ nhưng chất lượng rất tuyệt."},{"en":"Regular exercise can improve your quality of life.","vi":"Tập thể dục đều đặn có thể nâng cao chất lượng cuộc sống của bạn."},{"en":"Patience is an important quality for a teacher.","vi":"Sự kiên nhẫn là một phẩm chất quan trọng của giáo viên."}]','[{"phrase":"high quality"},{"phrase":"quality of life"},{"phrase":"good quality"},{"phrase":"poor quality"}]',NULL,'/ˈkwɑːləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/quality__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(497,'ngsl-2-01',18,'project','dự án; đề tài, bài tập lớn','noun','[{"en":"Our team is working on a new project this month.","vi":"Tháng này nhóm chúng tôi đang làm một dự án mới."},{"en":"The city started a project to build more parks.","vi":"Thành phố đã khởi động một dự án xây thêm công viên."},{"en":"I have to finish my science project by Friday.","vi":"Tôi phải hoàn thành bài tập lớn môn khoa học trước thứ Sáu."}]','[{"phrase":"work on a project"},{"phrase":"research project"},{"phrase":"school project"},{"phrase":"project manager"}]',NULL,'/ˈprɑːdʒekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proje/project__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(498,'ngsl-2-01',19,'round','vòng, hiệp; lượt, chầu; ván','noun','[{"en":"Our team won the first round of the competition.","vi":"Đội chúng tôi đã thắng vòng đầu tiên của cuộc thi."},{"en":"After the meal, he bought a round of drinks for everyone.","vi":"Sau bữa ăn, anh ấy mời mọi người một chầu đồ uống."},{"en":"We played another round of cards after dinner.","vi":"Sau bữa tối chúng tôi chơi thêm một ván bài."}]','[{"phrase":"first round"},{"phrase":"final round"},{"phrase":"a round of drinks"},{"phrase":"round of applause"}]','Cũng là tính từ: round (tròn) – a round table','/raʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/round/round__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(499,'ngsl-2-01',20,'opportunity','cơ hội, dịp','noun','[{"en":"Studying abroad is a great opportunity to learn a new language.","vi":"Du học là cơ hội tuyệt vời để học một ngôn ngữ mới."},{"en":"I''d like to take this opportunity to thank all of you.","vi":"Tôi muốn nhân dịp này cảm ơn tất cả các bạn."},{"en":"She never missed an opportunity to practice her English.","vi":"Cô ấy chưa bao giờ bỏ lỡ cơ hội luyện tiếng Anh."}]','[{"phrase":"take the opportunity"},{"phrase":"great opportunity"},{"phrase":"job opportunity"},{"phrase":"miss an opportunity"}]',NULL,'/ˌɑːpərˈtuːnəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppor/opportunity__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(500,'ngsl-2-01',21,'road','con đường, đường (xe chạy)','noun','[{"en":"Be careful when you cross the road.","vi":"Cẩn thận khi bạn băng qua đường nhé."},{"en":"The road to the village was narrow and full of holes.","vi":"Con đường vào làng hẹp và đầy ổ gà."},{"en":"We spent three days on the road during our trip.","vi":"Chúng tôi đã đi đường mất ba ngày trong chuyến đi."}]','[{"phrase":"cross the road"},{"phrase":"main road"},{"phrase":"on the road"},{"phrase":"road trip"}]',NULL,'/rəʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roa/road_/road__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(501,'ngsl-2-01',22,'accord','theo; tự nguyện','verb','[{"en":"According to the weather forecast, it will rain tomorrow.","vi":"Theo dự báo thời tiết, ngày mai trời sẽ mưa."},{"en":"Everything went according to plan, so we finished early.","vi":"Mọi việc diễn ra theo đúng kế hoạch nên chúng tôi xong sớm."},{"en":"Nobody asked him to leave; he left of his own accord.","vi":"Không ai bảo anh ấy đi cả; anh ấy tự nguyện rời đi."}]','[{"phrase":"according to"},{"phrase":"according to plan"},{"phrase":"of your own accord"}]','Thường gặp: according to (theo) · of your own accord (tự nguyện)','/əˈkɔːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accor/accord__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(502,'ngsl-2-01',23,'list','danh sách','noun','[{"en":"Don''t forget to bring the shopping list to the supermarket.","vi":"Đừng quên mang danh sách đồ cần mua đến siêu thị nhé."},{"en":"Is my name on the list for the trip?","vi":"Tên tôi có trong danh sách đi chuyến đi không?"},{"en":"She made a list of things to do before the wedding.","vi":"Cô ấy lập danh sách những việc cần làm trước đám cưới."}]','[{"phrase":"make a list"},{"phrase":"shopping list"},{"phrase":"on the list"},{"phrase":"waiting list"}]',NULL,'/lɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lis/list_/list__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(503,'ngsl-2-01',24,'wish','ước; chúc; muốn','verb','[{"en":"I wish I could speak English as well as you.","vi":"Ước gì tôi nói tiếng Anh giỏi được như bạn."},{"en":"We wish you a happy new year!","vi":"Chúc bạn năm mới vui vẻ!"},{"en":"You may leave early if you wish.","vi":"Nếu muốn, bạn có thể về sớm."}]','[{"phrase":"wish someone luck"},{"phrase":"make a wish"},{"phrase":"best wishes"},{"phrase":"if you wish"}]','I wish + quá khứ (ước điều không có thật ở hiện tại)','/wɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wis/wish_/wish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(504,'ngsl-2-01',25,'therefore','vì vậy, do đó','adverb','[{"en":"The bridge was closed, and therefore we had to take another road.","vi":"Cây cầu bị đóng nên chúng tôi phải đi đường khác."},{"en":"She is only sixteen and therefore cannot drive a car.","vi":"Cô ấy mới mười sáu tuổi, do đó chưa được lái ô tô."},{"en":"Prices went up last year; therefore, many families spent less.","vi":"Năm ngoái giá cả tăng, vì vậy nhiều gia đình đã chi tiêu ít hơn."}]','[{"phrase":"and therefore"},{"phrase":"is therefore"}]','Trang trọng hơn so; hay đứng sau dấu chấm phẩy hoặc and','/ˈðerfɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/there/therefore__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(505,'ngsl-2-01',26,'wear','mặc; đeo, đội; mang (giày)','verb','[{"en":"You should wear a coat because it''s cold outside.","vi":"Bạn nên mặc áo khoác vì bên ngoài trời lạnh."},{"en":"My brother has worn glasses since he was ten.","vi":"Anh trai tôi đeo kính từ năm mười tuổi."},{"en":"Everyone must wear a helmet when riding a motorbike.","vi":"Mọi người phải đội mũ bảo hiểm khi đi xe máy."}]','[{"phrase":"wear glasses"},{"phrase":"wear a helmet"},{"phrase":"wear a seat belt"},{"phrase":"wear makeup"}]','wear – wore – worn','/wer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/wear_/wear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(506,'ngsl-2-01',27,'fund','quỹ; tiền, kinh phí','noun','[{"en":"The school is raising funds to build a new library.","vi":"Trường đang gây quỹ để xây một thư viện mới."},{"en":"We started a fund to help families after the flood.","vi":"Chúng tôi lập một quỹ để giúp các gia đình sau trận lũ."},{"en":"The project stopped because it ran out of funds.","vi":"Dự án phải dừng lại vì hết kinh phí."}]','[{"phrase":"raise funds"},{"phrase":"run out of funds"},{"phrase":"set up a fund"},{"phrase":"public funds"}]','Nghĩa tiền/kinh phí thường dùng số nhiều: funds','/fʌnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/fund_/fund__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(507,'ngsl-2-01',28,'rest','sự nghỉ ngơi; phần còn lại','noun','[{"en":"You look tired, so why don''t you get some rest?","vi":"Trông bạn mệt đấy, sao không nghỉ ngơi một chút?"},{"en":"Let''s take a short rest before we climb the hill.","vi":"Mình nghỉ một lát trước khi leo đồi nhé."},{"en":"I''ll eat half now and save the rest for later.","vi":"Tôi sẽ ăn một nửa bây giờ và để dành phần còn lại cho lát nữa."}]','[{"phrase":"get some rest"},{"phrase":"take a rest"},{"phrase":"the rest of"},{"phrase":"rest of the day"}]',NULL,'/rest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/rest_/rest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(508,'ngsl-2-01',29,'kid','đứa trẻ; con (thân mật)','noun','[{"en":"The kids are playing football in the park.","vi":"Bọn trẻ đang đá bóng trong công viên."},{"en":"How many kids do you have?","vi":"Bạn có mấy đứa con?"},{"en":"When I was a kid, I wanted to be a pilot.","vi":"Hồi còn nhỏ, tôi muốn trở thành phi công."}]','[{"phrase":"have kids"},{"phrase":"little kid"},{"phrase":"school kids"},{"phrase":"when I was a kid"}]','Thân mật, dùng trong văn nói; trang trọng hơn: child','/kɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kid/kid__/kid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(509,'ngsl-2-02',1,'industry','ngành công nghiệp; ngành','noun','[{"en":"My father has worked in the car industry for twenty years.","vi":"Bố tôi đã làm trong ngành công nghiệp ô tô được hai mươi năm."},{"en":"Tourism is the most important industry on this island.","vi":"Du lịch là ngành quan trọng nhất trên hòn đảo này."},{"en":"She wants to find a job in the music industry.","vi":"Cô ấy muốn tìm việc trong ngành âm nhạc."}]','[{"phrase":"car industry"},{"phrase":"music industry"},{"phrase":"tourism industry"}]',NULL,'/ˈɪndəstri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indus/industry__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(510,'ngsl-2-02',2,'education','giáo dục; học vấn','noun','[{"en":"Many parents spend a lot of money on their children''s education.","vi":"Nhiều phụ huynh chi rất nhiều tiền cho việc học của con cái."},{"en":"She was the first person in her family to get a university education.","vi":"Cô ấy là người đầu tiên trong gia đình được học đại học."},{"en":"He left school at sixteen but continued his education later in life.","vi":"Anh ấy nghỉ học năm mười sáu tuổi nhưng sau này vẫn tiếp tục học lên."}]','[{"phrase":"higher education"},{"phrase":"university education"},{"phrase":"get an education"}]',NULL,'/ˌedʒuˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edu/educa/education__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(511,'ngsl-2-02',3,'measure','đo; đánh giá','verb','[{"en":"The nurse measured my height and weight.","vi":"Y tá đo chiều cao và cân nặng của tôi."},{"en":"Can you measure the window before we buy new curtains?","vi":"Bạn đo cửa sổ giúp mình trước khi chúng ta mua rèm mới được không?"},{"en":"It is hard to measure how much students really learn.","vi":"Rất khó đánh giá học sinh thực sự học được bao nhiêu."}]','[{"phrase":"measure the size"},{"phrase":"measure progress"},{"phrase":"measure success"}]',NULL,'/ˈmeʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/measu/measure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(512,'ngsl-2-02',4,'kill','giết; làm chết','verb','[{"en":"The cold winter killed most of the plants in our garden.","vi":"Mùa đông lạnh giá đã làm chết gần hết cây trong vườn nhà tôi."},{"en":"We played cards to kill time while waiting for the train.","vi":"Chúng tôi chơi bài để giết thời gian trong lúc chờ tàu."},{"en":"Our cat killed a mouse in the kitchen last night.","vi":"Tối qua con mèo nhà tôi đã giết một con chuột trong bếp."}]','[{"phrase":"kill time"},{"phrase":"be killed in an accident"},{"phrase":"kill insects"}]',NULL,'/kɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kil/kill_/kill__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(513,'ngsl-2-02',5,'serve','phục vụ; dọn (món ăn)','verb','[{"en":"The restaurant serves breakfast until eleven o''clock.","vi":"Nhà hàng phục vụ bữa sáng đến mười một giờ."},{"en":"Dinner will be served in the main hall at seven.","vi":"Bữa tối sẽ được dọn ra ở sảnh chính lúc bảy giờ."},{"en":"The waiter who served us was very friendly.","vi":"Anh bồi bàn phục vụ chúng tôi rất thân thiện."}]','[{"phrase":"serve breakfast"},{"phrase":"serve food"},{"phrase":"serve customers"}]',NULL,'/sɜːrv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serve/serve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(514,'ngsl-2-02',6,'likely','có khả năng; có thể xảy ra','adjective','[{"en":"It''s likely to rain this afternoon, so take an umbrella.","vi":"Chiều nay có khả năng mưa, nên hãy mang theo ô."},{"en":"Young drivers are more likely to have accidents.","vi":"Tài xế trẻ có nhiều khả năng gặp tai nạn hơn."},{"en":"It seems very likely that the shop will close next year.","vi":"Có vẻ rất có khả năng cửa hàng sẽ đóng cửa vào năm sau."}]','[{"phrase":"be likely to"},{"phrase":"more likely"},{"phrase":"very likely"}]','be likely to + V: có khả năng sẽ…','/ˈlaɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lik/likel/likely__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(515,'ngsl-2-02',7,'certainly','chắc chắn; tất nhiên','adverb','[{"en":"She will almost certainly pass the exam next week.","vi":"Gần như chắc chắn cô ấy sẽ đỗ kỳ thi vào tuần tới."},{"en":"You can certainly bring your sister to the party.","vi":"Tất nhiên bạn có thể dẫn em gái đến bữa tiệc."},{"en":"It was certainly the best meal I''ve had this year.","vi":"Đó chắc chắn là bữa ăn ngon nhất tôi được ăn trong năm nay."}]','[{"phrase":"almost certainly"},{"phrase":"certainly not"},{"phrase":"most certainly"}]',NULL,'/ˈsɜːrtnli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cer/certa/certainly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(516,'ngsl-2-02',8,'national','(thuộc) quốc gia; toàn quốc','adjective','[{"en":"Schools are closed today because it is a national holiday.","vi":"Hôm nay các trường học nghỉ vì là ngày lễ quốc gia."},{"en":"The story was reported on national television.","vi":"Câu chuyện được đưa tin trên truyền hình quốc gia."},{"en":"He was chosen to play for the national team at eighteen.","vi":"Anh ấy được chọn vào đội tuyển quốc gia khi mới mười tám tuổi."}]','[{"phrase":"national holiday"},{"phrase":"national team"},{"phrase":"national park"},{"phrase":"national television"}]',NULL,'/ˈnæʃnəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natio/national__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(517,'ngsl-2-02',9,'teach','dạy; giảng dạy','verb','[{"en":"My mother teaches math at a high school.","vi":"Mẹ tôi dạy toán ở một trường cấp ba."},{"en":"Who taught you to swim when you were little?","vi":"Ai đã dạy bạn bơi khi bạn còn nhỏ?"},{"en":"He has taught English in Vietnam for five years.","vi":"Anh ấy đã dạy tiếng Anh ở Việt Nam được năm năm."}]','[{"phrase":"teach English"},{"phrase":"teach children"},{"phrase":"teach a class"}]','teach – taught – taught','/tiːtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/teach/teach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(518,'ngsl-2-02',10,'field','cánh đồng; sân (thể thao); lĩnh vực','noun','[{"en":"Cows were eating grass in the field next to the road.","vi":"Những con bò đang ăn cỏ trên cánh đồng cạnh con đường."},{"en":"The players ran onto the field before the game started.","vi":"Các cầu thủ chạy ra sân trước khi trận đấu bắt đầu."},{"en":"She is an expert in the field of medicine.","vi":"Cô ấy là chuyên gia trong lĩnh vực y học."}]','[{"phrase":"football field"},{"phrase":"in the field of"},{"phrase":"field of study"}]',NULL,'/fiːld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fie/field/field__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(519,'ngsl-2-02',11,'security','an ninh; sự an toàn','noun','[{"en":"We had to go through security at the airport.","vi":"Chúng tôi phải qua cửa kiểm tra an ninh ở sân bay."},{"en":"The building has cameras at every door for extra security.","vi":"Tòa nhà có camera ở mọi cửa để tăng cường an ninh."},{"en":"A stable job gives my family a sense of security.","vi":"Một công việc ổn định mang lại cho gia đình tôi cảm giác an toàn."}]','[{"phrase":"airport security"},{"phrase":"security guard"},{"phrase":"job security"},{"phrase":"sense of security"}]','không đếm được','/sɪˈkjʊrəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secur/security__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(520,'ngsl-2-02',12,'air','không khí; không trung','noun','[{"en":"Let''s open the window to get some fresh air.","vi":"Mình mở cửa sổ cho có chút không khí trong lành nhé."},{"en":"The air in big cities is often very dirty.","vi":"Không khí ở các thành phố lớn thường rất bẩn."},{"en":"The children threw their hats into the air.","vi":"Bọn trẻ tung mũ lên không trung."}]','[{"phrase":"fresh air"},{"phrase":"air pollution"},{"phrase":"into the air"},{"phrase":"by air"}]','không đếm được','/er/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/air/air__/air__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(521,'ngsl-2-02',13,'benefit','lợi ích; phúc lợi','noun','[{"en":"Regular exercise has many benefits for your health.","vi":"Tập thể dục thường xuyên có nhiều lợi ích cho sức khỏe."},{"en":"One benefit of living here is the short walk to work.","vi":"Một lợi ích khi sống ở đây là chỉ cần đi bộ một đoạn ngắn là đến chỗ làm."},{"en":"The job offers good pay and health benefits.","vi":"Công việc này có lương tốt và phúc lợi y tế."}]','[{"phrase":"health benefits"},{"phrase":"many benefits"},{"phrase":"the benefit of"}]',NULL,'/ˈbenɪfɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/benef/benefit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(522,'ngsl-2-02',14,'trade','thương mại; sự buôn bán; nghề','noun','[{"en":"Trade between the two countries has grown quickly.","vi":"Thương mại giữa hai nước đã tăng trưởng nhanh chóng."},{"en":"The town grew rich from the fish trade.","vi":"Thị trấn trở nên giàu có nhờ nghề buôn bán cá."},{"en":"My uncle learned a trade instead of going to university.","vi":"Chú tôi đi học nghề thay vì vào đại học."}]','[{"phrase":"international trade"},{"phrase":"trade between"},{"phrase":"learn a trade"}]',NULL,'/treɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trade/trade__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(523,'ngsl-2-02',15,'risk','rủi ro; nguy cơ','noun','[{"en":"Smoking increases the risk of heart disease.","vi":"Hút thuốc làm tăng nguy cơ mắc bệnh tim."},{"en":"Starting your own business is always a big risk.","vi":"Tự mở doanh nghiệp riêng luôn là một rủi ro lớn."},{"en":"I don''t want to take any risks with my money.","vi":"Tôi không muốn chấp nhận bất kỳ rủi ro nào với tiền của mình."}]','[{"phrase":"take a risk"},{"phrase":"the risk of"},{"phrase":"high risk"},{"phrase":"at risk"}]',NULL,'/rɪsk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ris/risk_/risk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(524,'ngsl-2-02',16,'news','tin tức; tin','noun','[{"en":"I have some good news for you!","vi":"Mình có tin vui cho bạn đây!"},{"en":"My dad watches the news every evening after dinner.","vi":"Bố tôi xem thời sự mỗi tối sau bữa ăn."},{"en":"Have you heard the news about the new manager?","vi":"Bạn đã nghe tin về người quản lý mới chưa?"}]','[{"phrase":"good news"},{"phrase":"bad news"},{"phrase":"watch the news"},{"phrase":"hear the news"}]','không đếm được, dùng động từ số ít: The news is…','/nuːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/news_/news__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(525,'ngsl-2-02',17,'standard','tiêu chuẩn; mức, trình độ','noun','[{"en":"This restaurant has very high standards of service.","vi":"Nhà hàng này có tiêu chuẩn phục vụ rất cao."},{"en":"Her English is of a very high standard.","vi":"Tiếng Anh của cô ấy ở trình độ rất cao."},{"en":"The standard of living in the city has improved a lot.","vi":"Mức sống ở thành phố đã được cải thiện nhiều."}]','[{"phrase":"high standards"},{"phrase":"standard of living"},{"phrase":"safety standards"}]',NULL,'/ˈstændərd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stand/standard__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(526,'ngsl-2-02',18,'vote','bỏ phiếu; biểu quyết','verb','[{"en":"The students voted for a new class president.","vi":"Học sinh đã bỏ phiếu bầu lớp trưởng mới."},{"en":"Let''s vote on where to go for our team dinner.","vi":"Mình biểu quyết xem cả nhóm đi đâu ăn tối nhé."},{"en":"Most people in the club voted against changing the meeting time.","vi":"Phần lớn thành viên câu lạc bộ bỏ phiếu phản đối việc đổi giờ họp."}]','[{"phrase":"vote for"},{"phrase":"vote against"},{"phrase":"vote on"}]',NULL,'/vəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vot/vote_/vote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(527,'ngsl-2-02',19,'percent','phần trăm','noun','[{"en":"About ninety percent of the students passed the test.","vi":"Khoảng chín mươi phần trăm học sinh đã qua bài kiểm tra."},{"en":"The shop is offering twenty percent off all shoes this week.","vi":"Tuần này cửa hàng giảm hai mươi phần trăm cho tất cả giày dép."},{"en":"Prices have gone up by five percent since last year.","vi":"Giá cả đã tăng năm phần trăm kể từ năm ngoái."}]','[{"phrase":"percent of"},{"phrase":"twenty percent off"},{"phrase":"ninety percent"}]','Anh: per cent · Mỹ: percent','/pərˈsɛnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(528,'ngsl-2-02',20,'focus','tập trung','verb','[{"en":"I can''t focus on my work with all this noise.","vi":"Ồn ào thế này tôi không thể tập trung làm việc được."},{"en":"This year the company will focus on online sales.","vi":"Năm nay công ty sẽ tập trung vào bán hàng trực tuyến."},{"en":"Try to focus on the road when you are driving.","vi":"Khi lái xe, hãy cố tập trung nhìn đường."}]','[{"phrase":"focus on"},{"phrase":"focus attention on"},{"phrase":"stay focused"}]','focus on + N/V-ing','/ˈfəʊkəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foc/focus/focus__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(529,'ngsl-2-02',21,'stage','giai đoạn; sân khấu','noun','[{"en":"The project is still in its early stages.","vi":"Dự án vẫn đang ở giai đoạn đầu."},{"en":"At this stage, we don''t know the cause of the problem.","vi":"Ở giai đoạn này, chúng tôi chưa biết nguyên nhân của vấn đề."},{"en":"The band walked onto the stage and the crowd cheered.","vi":"Ban nhạc bước lên sân khấu và đám đông reo hò."}]','[{"phrase":"early stage"},{"phrase":"at this stage"},{"phrase":"on stage"},{"phrase":"final stage"}]',NULL,'/steɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stage/stage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(530,'ngsl-2-02',22,'space','chỗ trống; không gian; vũ trụ','noun','[{"en":"There isn''t enough space in the car for all our bags.","vi":"Trong xe không đủ chỗ cho tất cả túi đồ của chúng ta."},{"en":"Children need plenty of open space to play.","vi":"Trẻ em cần nhiều không gian rộng rãi để vui chơi."},{"en":"She dreams of traveling into space one day.","vi":"Cô ấy mơ một ngày nào đó được bay vào vũ trụ."}]','[{"phrase":"enough space"},{"phrase":"parking space"},{"phrase":"open space"},{"phrase":"outer space"}]',NULL,'/speɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spa/space/space__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(531,'ngsl-2-02',23,'instead','thay vào đó; thay vì','adverb','[{"en":"We didn''t have time to cook, so we ordered pizza instead.","vi":"Chúng tôi không có thời gian nấu ăn nên đã gọi pizza thay vào đó."},{"en":"Why don''t you walk to school instead of taking the bus?","vi":"Sao bạn không đi bộ đến trường thay vì đi xe buýt?"},{"en":"Instead of watching TV all evening, she read a book.","vi":"Thay vì xem TV cả buổi tối, cô ấy đọc một cuốn sách."}]','[{"phrase":"instead of"},{"phrase":"instead of taking"},{"phrase":"order something instead"}]','instead of + N/V-ing','/ɪnˈsted/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inste/instead__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(532,'ngsl-2-02',24,'realize','nhận ra; thực hiện (ước mơ)','verb','[{"en":"I didn''t realize how late it was until I checked my phone.","vi":"Mãi đến khi xem điện thoại tôi mới nhận ra đã muộn đến thế."},{"en":"She suddenly realized that she had left her keys at home.","vi":"Cô ấy chợt nhận ra mình đã để quên chìa khóa ở nhà."},{"en":"He worked hard for years to realize his dream of becoming a pilot.","vi":"Anh ấy đã làm việc chăm chỉ nhiều năm để thực hiện ước mơ trở thành phi công."}]','[{"phrase":"suddenly realize"},{"phrase":"realize a dream"},{"phrase":"come to realize"}]','Anh: realise · Mỹ: realize','/ˈriːəlaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reali/realize__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(533,'ngsl-2-02',25,'usually','thường; thông thường','adverb','[{"en":"I usually get up at six on weekdays.","vi":"Tôi thường dậy lúc sáu giờ vào các ngày trong tuần."},{"en":"The bus is usually late when it rains.","vi":"Xe buýt thường đến muộn khi trời mưa."},{"en":"What do you usually have for breakfast?","vi":"Bạn thường ăn gì vào bữa sáng?"}]','[{"phrase":"usually get up"},{"phrase":"don''t usually"},{"phrase":"usually have"}]',NULL,'/ˈjuːʒuəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/usu/usual/usually__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(534,'ngsl-2-02',26,'data','dữ liệu; số liệu','noun','[{"en":"We collected data from over five hundred students.","vi":"Chúng tôi đã thu thập dữ liệu từ hơn năm trăm sinh viên."},{"en":"Make sure you back up your data before updating your phone.","vi":"Hãy nhớ sao lưu dữ liệu trước khi cập nhật điện thoại."},{"en":"The data shows that more people are working from home.","vi":"Số liệu cho thấy ngày càng nhiều người làm việc tại nhà."}]','[{"phrase":"collect data"},{"phrase":"personal data"},{"phrase":"back up data"}]','thường dùng như danh từ không đếm được','/ˈdeɪtə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/data_/data__us_3_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(535,'ngsl-2-02',27,'single','một, duy nhất; độc thân; đơn','adjective','[{"en":"She didn''t make a single mistake on the test.","vi":"Cô ấy không mắc một lỗi nào trong bài kiểm tra."},{"en":"My brother is thirty and still single.","vi":"Anh trai tôi ba mươi tuổi mà vẫn còn độc thân."},{"en":"I''d like to book a single room for two nights.","vi":"Tôi muốn đặt một phòng đơn trong hai đêm."}]','[{"phrase":"single room"},{"phrase":"every single day"},{"phrase":"single parent"}]',NULL,'/ˈsɪŋɡl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/singl/single__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(536,'ngsl-2-02',28,'address','địa chỉ','noun','[{"en":"Can you write your address on this form?","vi":"Bạn có thể ghi địa chỉ của mình vào tờ đơn này không?"},{"en":"I sent the email to the wrong address.","vi":"Tôi đã gửi email nhầm địa chỉ."},{"en":"We moved last month, so here is our new address.","vi":"Chúng tôi đã chuyển nhà tháng trước, nên đây là địa chỉ mới."}]','[{"phrase":"email address"},{"phrase":"home address"},{"phrase":"new address"},{"phrase":"wrong address"}]',NULL,'/əˈdres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/addre/address__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(537,'ngsl-2-02',29,'performance','màn trình diễn; hiệu quả, thành tích','noun','[{"en":"The band gave an amazing performance last night.","vi":"Tối qua ban nhạc đã có một màn trình diễn tuyệt vời."},{"en":"Her performance at work has improved a lot this year.","vi":"Năm nay hiệu quả công việc của cô ấy đã tiến bộ nhiều."},{"en":"Poor sleep can hurt your performance at school.","vi":"Ngủ kém có thể làm giảm thành tích học tập của bạn."}]','[{"phrase":"give a performance"},{"phrase":"live performance"},{"phrase":"performance at work"}]',NULL,'/pərˈfɔːrməns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfo/performance__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(538,'ngsl-2-03',1,'chance','cơ hội; khả năng','noun','[{"en":"This trip is a great chance to practice your English.","vi":"Chuyến đi này là cơ hội tuyệt vời để luyện tiếng Anh của bạn."},{"en":"I didn''t get a chance to call you yesterday.","vi":"Hôm qua tôi không có dịp gọi cho bạn."},{"en":"There''s a good chance it will rain this afternoon.","vi":"Nhiều khả năng chiều nay trời sẽ mưa."}]','[{"phrase":"get a chance"},{"phrase":"a good chance"},{"phrase":"second chance"},{"phrase":"by chance"}]',NULL,'/tʃæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chanc/chance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(539,'ngsl-2-03',2,'accept','chấp nhận; nhận','verb','[{"en":"She accepted the job offer without a second thought.","vi":"Cô ấy nhận lời mời làm việc mà không chút do dự."},{"en":"Do you accept credit cards here?","vi":"Ở đây có nhận thẻ tín dụng không?"},{"en":"It took him a long time to accept the truth.","vi":"Anh ấy mất rất lâu mới chấp nhận được sự thật."}]','[{"phrase":"accept an offer"},{"phrase":"accept an invitation"},{"phrase":"accept responsibility"},{"phrase":"accept the truth"}]','accept (chấp nhận) ≠ except (ngoại trừ)','/əkˈsept/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accep/accept__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(540,'ngsl-2-03',3,'society','xã hội; hội, hiệp hội','noun','[{"en":"Teachers play an important role in our society.","vi":"Giáo viên đóng vai trò quan trọng trong xã hội chúng ta."},{"en":"Modern society depends heavily on the internet.","vi":"Xã hội hiện đại phụ thuộc rất nhiều vào internet."},{"en":"My grandfather joined the local history society last year.","vi":"Năm ngoái ông tôi đã tham gia hội lịch sử địa phương."}]','[{"phrase":"modern society"},{"phrase":"in society"},{"phrase":"role in society"},{"phrase":"member of society"}]',NULL,'/səˈsaɪəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soc/socie/society__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(541,'ngsl-2-03',4,'technology','công nghệ','noun','[{"en":"New technology has changed the way we work.","vi":"Công nghệ mới đã thay đổi cách chúng ta làm việc."},{"en":"My parents are not very comfortable with technology.","vi":"Bố mẹ tôi không rành công nghệ lắm."},{"en":"The school spends a lot of money on technology every year.","vi":"Mỗi năm trường chi rất nhiều tiền cho công nghệ."}]','[{"phrase":"new technology"},{"phrase":"modern technology"},{"phrase":"information technology"},{"phrase":"use technology"}]',NULL,'/tekˈnɑːlədʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technology__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(542,'ngsl-2-03',5,'mention','nhắc đến, đề cập','verb','[{"en":"She didn''t mention that she was moving to another city.","vi":"Cô ấy không nhắc đến chuyện mình sắp chuyển sang thành phố khác."},{"en":"As I mentioned earlier, the meeting starts at nine.","vi":"Như tôi đã đề cập lúc nãy, cuộc họp bắt đầu lúc chín giờ."},{"en":"Please don''t mention it to anyone else.","vi":"Làm ơn đừng nhắc chuyện này với ai khác nhé."}]','[{"phrase":"mention it"},{"phrase":"as mentioned"},{"phrase":"briefly mention"},{"phrase":"not to mention"}]','Không dùng "mention about" — nói "mention something"','/ˈmenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menti/mention__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(543,'ngsl-2-03',6,'choice','sự lựa chọn','noun','[{"en":"You made the right choice by staying at home.","vi":"Bạn đã lựa chọn đúng khi ở nhà."},{"en":"We had no choice but to wait for the next train.","vi":"Chúng tôi không còn cách nào khác ngoài việc đợi chuyến tàu tiếp theo."},{"en":"This café has a wide choice of cakes.","vi":"Quán cà phê này có rất nhiều loại bánh để lựa chọn."}]','[{"phrase":"make a choice"},{"phrase":"have no choice"},{"phrase":"the right choice"},{"phrase":"a wide choice"}]',NULL,'/tʃɔɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cho/choic/choice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(544,'ngsl-2-03',7,'save','tiết kiệm; cứu; lưu','verb','[{"en":"I''m saving money to buy a new laptop.","vi":"Tôi đang tiết kiệm tiền để mua một chiếc máy tính xách tay mới."},{"en":"The firefighters saved a little girl from the burning house.","vi":"Lính cứu hỏa đã cứu một bé gái khỏi ngôi nhà đang cháy."},{"en":"Don''t forget to save the file before you close it.","vi":"Đừng quên lưu tệp trước khi đóng nó."}]','[{"phrase":"save money"},{"phrase":"save time"},{"phrase":"save a life"},{"phrase":"save a file"}]',NULL,'/seɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sav/save_/save__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(545,'ngsl-2-03',8,'common','phổ biến, thông thường; chung','adjective','[{"en":"Headaches are very common among students during exams.","vi":"Đau đầu rất phổ biến ở học sinh trong mùa thi."},{"en":"It''s a common mistake, so don''t worry about it.","vi":"Đó là một lỗi thường gặp, nên đừng lo."},{"en":"My new roommate and I have a lot in common.","vi":"Tôi và bạn cùng phòng mới có nhiều điểm chung."}]','[{"phrase":"common mistake"},{"phrase":"common problem"},{"phrase":"in common"},{"phrase":"common sense"}]',NULL,'/ˈkɑːmən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commo/common__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(546,'ngsl-2-03',9,'culture','văn hóa','noun','[{"en":"I love learning about the food and culture of other countries.","vi":"Tôi thích tìm hiểu về ẩm thực và văn hóa của các nước khác."},{"en":"Living abroad helped her understand a different culture.","vi":"Sống ở nước ngoài đã giúp cô ấy hiểu một nền văn hóa khác."},{"en":"This company has a friendly and open work culture.","vi":"Công ty này có văn hóa làm việc thân thiện và cởi mở."}]','[{"phrase":"local culture"},{"phrase":"different cultures"},{"phrase":"popular culture"},{"phrase":"work culture"}]',NULL,'/ˈkʌltʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cul/cultu/culture__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(547,'ngsl-2-03',10,'total','tổng, tổng cộng; hoàn toàn','adjective','[{"en":"The total cost of the trip was about two thousand dollars.","vi":"Tổng chi phí của chuyến đi vào khoảng hai nghìn đô la."},{"en":"What is the total number of students in your class?","vi":"Tổng số học sinh trong lớp bạn là bao nhiêu?"},{"en":"The party was a total surprise to my mother.","vi":"Bữa tiệc hoàn toàn là một bất ngờ đối với mẹ tôi."}]','[{"phrase":"total cost"},{"phrase":"total number"},{"phrase":"total amount"},{"phrase":"in total"}]',NULL,'/ˈtəʊtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tot/total/total__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(548,'ngsl-2-03',11,'demand','nhu cầu; yêu cầu','noun','[{"en":"There is a high demand for nurses in big cities.","vi":"Nhu cầu về y tá ở các thành phố lớn rất cao."},{"en":"Demand for air conditioners goes up every summer.","vi":"Nhu cầu về máy lạnh tăng lên vào mỗi mùa hè."},{"en":"The workers stopped working until the company met their demands.","vi":"Công nhân ngừng làm việc cho đến khi công ty đáp ứng yêu cầu của họ."}]','[{"phrase":"high demand"},{"phrase":"demand for"},{"phrase":"in demand"},{"phrase":"meet demands"}]',NULL,'/dɪˈmænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/deman/demand__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(549,'ngsl-2-03',12,'material','vật liệu, chất liệu; tài liệu','noun','[{"en":"This jacket is made from a soft, warm material.","vi":"Chiếc áo khoác này được làm từ chất liệu mềm và ấm."},{"en":"They used recycled materials to build the new school.","vi":"Họ đã dùng vật liệu tái chế để xây ngôi trường mới."},{"en":"The teacher gave us some reading materials for the weekend.","vi":"Giáo viên đưa cho chúng tôi một số tài liệu đọc cho cuối tuần."}]','[{"phrase":"building materials"},{"phrase":"raw materials"},{"phrase":"teaching materials"},{"phrase":"reading materials"}]',NULL,'/məˈtɪriəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/mater/material__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(550,'ngsl-2-03',13,'limit','giới hạn','noun','[{"en":"The speed limit on this road is fifty kilometers per hour.","vi":"Tốc độ tối đa trên con đường này là năm mươi ki-lô-mét một giờ."},{"en":"Is there a limit to how many books I can borrow?","vi":"Số sách tôi được mượn có bị giới hạn không?"},{"en":"My patience has its limits, so please be on time.","vi":"Sự kiên nhẫn của tôi cũng có giới hạn, nên làm ơn đến đúng giờ."}]','[{"phrase":"speed limit"},{"phrase":"time limit"},{"phrase":"age limit"},{"phrase":"limit to"}]',NULL,'/ˈlɪmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lim/limit/limit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(551,'ngsl-2-03',14,'listen','nghe, lắng nghe','verb','[{"en":"I like to listen to music while I cook.","vi":"Tôi thích nghe nhạc trong lúc nấu ăn."},{"en":"Listen carefully, because I will only say this once.","vi":"Nghe kỹ nhé, vì tôi chỉ nói điều này một lần thôi."},{"en":"My son never listens when I tell him to clean his room.","vi":"Con trai tôi chẳng bao giờ nghe lời khi tôi bảo nó dọn phòng."}]','[{"phrase":"listen to music"},{"phrase":"listen carefully"},{"phrase":"listen to advice"}]','Dùng "listen to" + tân ngữ: listen to the radio','/ˈlɪsn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lis/liste/listen__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(552,'ngsl-2-03',15,'due','đến hạn; dự kiến (đến)','adjective','[{"en":"The rent is due on the first day of every month.","vi":"Tiền thuê nhà đến hạn phải trả vào ngày đầu tiên của mỗi tháng."},{"en":"Our homework is due next Friday.","vi":"Bài tập về nhà của chúng tôi phải nộp vào thứ Sáu tới."},{"en":"The next train is due in ten minutes.","vi":"Chuyến tàu tiếp theo dự kiến sẽ đến trong mười phút nữa."}]','[{"phrase":"due date"},{"phrase":"rent is due"},{"phrase":"due back"},{"phrase":"due to"}]','due to = do, bởi vì','/duː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/due/due__/due__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(553,'ngsl-2-03',16,'wrong','sai; có vấn đề, trục trặc','adjective','[{"en":"Sorry, I think you have the wrong number.","vi":"Xin lỗi, tôi nghĩ bạn gọi nhầm số rồi."},{"en":"Two of my answers on the test were wrong.","vi":"Hai câu trả lời trong bài kiểm tra của tôi bị sai."},{"en":"Something is wrong with my phone; it keeps turning off.","vi":"Điện thoại của tôi có vấn đề gì đó; nó cứ tự tắt."}]','[{"phrase":"wrong answer"},{"phrase":"wrong number"},{"phrase":"something wrong"},{"phrase":"go wrong"}]',NULL,'/rɔːŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wro/wrong/wrong__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(554,'ngsl-2-03',17,'foot','bàn chân; chân (đồi, núi)','noun','[{"en":"My feet hurt after walking around the city all day.","vi":"Chân tôi đau nhức sau khi đi bộ quanh thành phố cả ngày."},{"en":"We usually go to school on foot.","vi":"Chúng tôi thường đi bộ đến trường."},{"en":"There is a small café at the foot of the hill.","vi":"Có một quán cà phê nhỏ ở chân đồi."}]','[{"phrase":"on foot"},{"phrase":"left foot"},{"phrase":"bare feet"},{"phrase":"at the foot of"}]','Số nhiều bất quy tắc: foot – feet','/fʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/foot_/foot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(555,'ngsl-2-03',18,'effort','nỗ lực, cố gắng','noun','[{"en":"She made a real effort to be friendly to everyone.","vi":"Cô ấy thực sự cố gắng tỏ ra thân thiện với mọi người."},{"en":"Learning a new language takes a lot of time and effort.","vi":"Học một ngôn ngữ mới cần rất nhiều thời gian và công sức."},{"en":"Thanks for your effort, even though we didn''t win.","vi":"Cảm ơn sự nỗ lực của bạn, dù chúng ta đã không thắng."}]','[{"phrase":"make an effort"},{"phrase":"a lot of effort"},{"phrase":"time and effort"},{"phrase":"worth the effort"}]',NULL,'/ˈefərt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effor/effort__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(556,'ngsl-2-03',19,'attention','sự chú ý','noun','[{"en":"Please pay attention to the teacher.","vi":"Hãy chú ý nghe giáo viên."},{"en":"The bright red car caught everyone''s attention.","vi":"Chiếc xe màu đỏ rực đã thu hút sự chú ý của mọi người."},{"en":"Small children need a lot of attention from their parents.","vi":"Trẻ nhỏ cần được bố mẹ quan tâm rất nhiều."}]','[{"phrase":"pay attention to"},{"phrase":"attract attention"},{"phrase":"catch someone''s attention"},{"phrase":"draw attention to"}]','Không đếm được','/əˈtenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/atten/attention__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(557,'ngsl-2-03',20,'upon','trên; ngay khi, lúc','preposition','[{"en":"Once upon a time, there lived a poor farmer.","vi":"Ngày xửa ngày xưa, có một bác nông dân nghèo."},{"en":"Upon arrival, guests will receive a free drink.","vi":"Khi đến nơi, khách sẽ được nhận một đồ uống miễn phí."},{"en":"Snow fell upon the quiet village all night.","vi":"Tuyết rơi trên ngôi làng yên tĩnh suốt đêm."}]','[{"phrase":"once upon a time"},{"phrase":"depend upon"},{"phrase":"upon arrival"},{"phrase":"based upon"}]','Trang trọng hơn "on"','/əˈpɑːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/upo/upon_/upon__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(558,'ngsl-2-03',21,'check','kiểm tra','verb','[{"en":"Can you check if the door is locked?","vi":"Bạn có thể kiểm tra xem cửa đã khóa chưa?"},{"en":"I check my email every morning before work.","vi":"Sáng nào trước khi đi làm tôi cũng kiểm tra email."},{"en":"Always check your answers before you hand in the test.","vi":"Hãy luôn kiểm tra lại đáp án trước khi nộp bài."}]','[{"phrase":"check your email"},{"phrase":"check the answers"},{"phrase":"double-check"},{"phrase":"check carefully"}]',NULL,'/tʃek/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/check/check__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(559,'ngsl-2-03',22,'complete','hoàn thành; điền đầy đủ','verb','[{"en":"The new bridge will be completed next year.","vi":"Cây cầu mới sẽ được hoàn thành vào năm sau."},{"en":"She completed her degree while working full-time.","vi":"Cô ấy đã hoàn thành chương trình học trong khi vẫn đi làm toàn thời gian."},{"en":"Please complete this form and give it to the receptionist.","vi":"Vui lòng điền đầy đủ mẫu đơn này và đưa cho lễ tân."}]','[{"phrase":"complete a course"},{"phrase":"complete a form"},{"phrase":"complete a task"},{"phrase":"fully complete"}]',NULL,'/kəmˈpliːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complete__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(560,'ngsl-2-03',23,'lie','nằm; nói dối','verb','[{"en":"I just want to lie on the beach and relax.","vi":"Tôi chỉ muốn nằm trên bãi biển và thư giãn."},{"en":"The cat was lying in the sun all afternoon.","vi":"Con mèo nằm phơi nắng suốt cả buổi chiều."},{"en":"He lied to his parents about where he went.","vi":"Cậu ấy đã nói dối bố mẹ về chỗ mình đi."}]','[{"phrase":"lie down"},{"phrase":"lie in bed"},{"phrase":"lie to someone"},{"phrase":"tell a lie"}]','nằm: lie – lay – lain · nói dối: lie – lied – lied','/laɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lie/lie__/lie__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(561,'ngsl-2-03',24,'pick','chọn; hái','verb','[{"en":"You can pick any color you like.","vi":"Bạn có thể chọn bất kỳ màu nào bạn thích."},{"en":"We picked strawberries at a farm last weekend.","vi":"Cuối tuần trước chúng tôi đã hái dâu ở một trang trại."},{"en":"Our teacher picked me to read the poem aloud.","vi":"Cô giáo đã chọn tôi đọc to bài thơ."}]','[{"phrase":"pick a number"},{"phrase":"pick a team"},{"phrase":"pick fruit"},{"phrase":"pick flowers"}]','pick up = nhặt lên; đón (ai đó)','/pɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pic/pick_/pick__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(562,'ngsl-2-03',25,'reduce','giảm, làm giảm','verb','[{"en":"Walking every day can help reduce stress.","vi":"Đi bộ mỗi ngày có thể giúp giảm căng thẳng."},{"en":"The store has reduced the prices of all winter clothes.","vi":"Cửa hàng đã giảm giá tất cả quần áo mùa đông."},{"en":"We need to reduce the amount of plastic we use.","vi":"Chúng ta cần giảm lượng nhựa mà mình sử dụng."}]','[{"phrase":"reduce costs"},{"phrase":"reduce the risk"},{"phrase":"reduce stress"},{"phrase":"greatly reduce"}]',NULL,'/rɪˈduːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/red/reduc/reduce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(563,'ngsl-2-03',26,'personal','cá nhân, riêng tư','adjective','[{"en":"Please don''t ask me such personal questions.","vi":"Làm ơn đừng hỏi tôi những câu hỏi riêng tư như vậy."},{"en":"Keep your personal information safe when you shop online.","vi":"Hãy giữ an toàn thông tin cá nhân khi bạn mua sắm trực tuyến."},{"en":"In my personal opinion, the first movie was better.","vi":"Theo ý kiến cá nhân tôi, bộ phim đầu tiên hay hơn."}]','[{"phrase":"personal information"},{"phrase":"personal life"},{"phrase":"personal opinion"},{"phrase":"personal question"}]',NULL,'/ˈpɜːrsənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personal__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(564,'ngsl-2-03',27,'ground','mặt đất; sân, bãi','noun','[{"en":"The ground was still wet after the rain.","vi":"Mặt đất vẫn còn ướt sau cơn mưa."},{"en":"She dropped her keys on the ground.","vi":"Cô ấy làm rơi chìa khóa xuống đất."},{"en":"The children were playing football on the sports ground.","vi":"Bọn trẻ đang đá bóng trên sân thể thao."}]','[{"phrase":"on the ground"},{"phrase":"fall to the ground"},{"phrase":"wet ground"},{"phrase":"sports ground"}]',NULL,'/ɡraʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/groun/ground__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(565,'ngsl-2-03',28,'animal','động vật, con vật','noun','[{"en":"My daughter wants to work with animals when she grows up.","vi":"Con gái tôi muốn làm việc với động vật khi lớn lên."},{"en":"Many wild animals live in this forest.","vi":"Nhiều loài động vật hoang dã sống trong khu rừng này."},{"en":"Dogs are my favorite animal because they are so loyal.","vi":"Chó là con vật tôi thích nhất vì chúng rất trung thành."}]','[{"phrase":"wild animals"},{"phrase":"farm animals"},{"phrase":"animal lover"}]',NULL,'/ˈænɪml/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ani/anima/animal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(566,'ngsl-2-03',29,'arrive','đến, tới nơi','verb','[{"en":"What time does your flight arrive in Hanoi?","vi":"Chuyến bay của bạn hạ cánh ở Hà Nội lúc mấy giờ?"},{"en":"We arrived at the hotel late at night.","vi":"Chúng tôi đến khách sạn vào lúc đêm muộn."},{"en":"Your package should arrive within three days.","vi":"Bưu kiện của bạn sẽ đến trong vòng ba ngày."}]','[{"phrase":"arrive at"},{"phrase":"arrive in"},{"phrase":"arrive home"},{"phrase":"arrive late"}]','arrive at + địa điểm nhỏ (sân bay, khách sạn); arrive in + thành phố, quốc gia','/əˈraɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arriv/arrive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(567,'ngsl-2-04',1,'patient','bệnh nhân; kiên nhẫn','noun','[{"en":"The doctor sees about thirty patients every day.","vi":"Bác sĩ khám cho khoảng ba mươi bệnh nhân mỗi ngày."},{"en":"The nurse brought the patient a glass of water.","vi":"Y tá mang cho bệnh nhân một cốc nước."},{"en":"Please be patient, the bus will be here soon.","vi":"Xin hãy kiên nhẫn, xe buýt sẽ đến ngay thôi."}]','[{"phrase":"treat a patient"},{"phrase":"hospital patient"},{"phrase":"be patient with"}]','patient (n) bệnh nhân · patient (adj) kiên nhẫn','/ˈpeɪʃnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pat/patie/patient__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(568,'ngsl-2-04',2,'current','hiện tại; hiện hành; dòng chảy','adjective','[{"en":"What is your current address?","vi":"Địa chỉ hiện tại của bạn là gì?"},{"en":"I''m happy with my current job, so I''m not looking for another.","vi":"Tôi hài lòng với công việc hiện tại nên không tìm việc khác."},{"en":"The current was too strong for us to swim across the river.","vi":"Dòng nước chảy quá mạnh nên chúng tôi không thể bơi qua sông."}]','[{"phrase":"current situation"},{"phrase":"current address"},{"phrase":"current job"},{"phrase":"strong current"}]','current ≠ currant (quả lý chua)','/ˈkɜːrənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/current__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(569,'ngsl-2-04',3,'century','thế kỷ','noun','[{"en":"This church was built in the sixteenth century.","vi":"Nhà thờ này được xây vào thế kỷ mười sáu."},{"en":"Life has changed a lot over the last century.","vi":"Cuộc sống đã thay đổi rất nhiều trong thế kỷ qua."},{"en":"My grandmother''s house is almost a century old.","vi":"Ngôi nhà của bà tôi đã gần một trăm năm tuổi."}]','[{"phrase":"the 21st century"},{"phrase":"last century"},{"phrase":"a century ago"},{"phrase":"the next century"}]','số nhiều: centuries','/ˈsentʃəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/centu/century__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(570,'ngsl-2-04',4,'evidence','bằng chứng; chứng cứ','noun','[{"en":"There is no evidence that coffee is bad for you.","vi":"Không có bằng chứng nào cho thấy cà phê có hại cho bạn."},{"en":"The police found new evidence in the house.","vi":"Cảnh sát đã tìm thấy chứng cứ mới trong ngôi nhà."},{"en":"Can you give any evidence to support your idea?","vi":"Bạn có thể đưa ra bằng chứng nào để ủng hộ ý kiến của mình không?"}]','[{"phrase":"find evidence"},{"phrase":"evidence of"},{"phrase":"strong evidence"},{"phrase":"scientific evidence"}]','không đếm được: a piece of evidence','/ˈevɪdəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evi/evide/evidence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(571,'ngsl-2-04',5,'exist','tồn tại; có','verb','[{"en":"Do you think life exists on other planets?","vi":"Bạn có nghĩ sự sống tồn tại trên các hành tinh khác không?"},{"en":"This small village has existed for hundreds of years.","vi":"Ngôi làng nhỏ này đã tồn tại hàng trăm năm."},{"en":"Smartphones didn''t exist when my parents were young.","vi":"Hồi bố mẹ tôi còn trẻ thì chưa có điện thoại thông minh."}]','[{"phrase":"still exist"},{"phrase":"no longer exist"},{"phrase":"exist in"}]',NULL,'/ɪɡˈzɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exi/exist/exist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(572,'ngsl-2-04',6,'similar','tương tự; giống nhau','adjective','[{"en":"My sister and I have very similar tastes in music.","vi":"Chị tôi và tôi có gu âm nhạc rất giống nhau."},{"en":"Your bag is similar to the one I lost.","vi":"Túi của bạn giống cái túi tôi đã làm mất."},{"en":"We had a similar problem at work last year.","vi":"Năm ngoái ở chỗ làm chúng tôi cũng gặp một vấn đề tương tự."}]','[{"phrase":"similar to"},{"phrase":"very similar"},{"phrase":"similar problem"},{"phrase":"in a similar way"}]','đi với giới từ to: similar to','/ˈsɪmələr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simil/similar__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(573,'ngsl-2-04',7,'fight','đánh nhau; chiến đấu; đấu tranh','verb','[{"en":"The two boys were fighting over a football.","vi":"Hai cậu bé đang đánh nhau để giành một quả bóng."},{"en":"Doctors are working hard to fight the disease.","vi":"Các bác sĩ đang nỗ lực chống lại căn bệnh."},{"en":"Workers fought for better pay and shorter hours.","vi":"Công nhân đã đấu tranh đòi lương cao hơn và giờ làm ngắn hơn."}]','[{"phrase":"fight for"},{"phrase":"fight against"},{"phrase":"fight a disease"},{"phrase":"fight a fire"}]','fight – fought – fought','/faɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fig/fight/fight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(574,'ngsl-2-04',8,'leader','người lãnh đạo; người dẫn đầu','noun','[{"en":"She is a natural leader, and everyone listens to her.","vi":"Cô ấy là người lãnh đạo bẩm sinh, ai cũng nghe lời cô ấy."},{"en":"Our team leader holds a meeting every Monday morning.","vi":"Trưởng nhóm của chúng tôi họp vào mỗi sáng thứ Hai."},{"en":"After ten kilometers, he was still the leader of the race.","vi":"Sau mười cây số, anh ấy vẫn dẫn đầu cuộc đua."}]','[{"phrase":"team leader"},{"phrase":"natural leader"},{"phrase":"world leader"},{"phrase":"group leader"}]',NULL,'/ˈliːdər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leade/leader__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(575,'ngsl-2-04',9,'fine','ổn; khỏe; tốt; tiền phạt','adjective','[{"en":"I had a cold last week, but I''m fine now.","vi":"Tuần trước tôi bị cảm, nhưng giờ tôi khỏe rồi."},{"en":"Is it fine if I leave work a little early today?","vi":"Hôm nay tôi về sớm một chút có được không?"},{"en":"He had to pay a fine for parking in the wrong place.","vi":"Anh ấy phải nộp phạt vì đỗ xe sai chỗ."}]','[{"phrase":"feel fine"},{"phrase":"that''s fine"},{"phrase":"fine weather"},{"phrase":"pay a fine"}]',NULL,'/faɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/fine_/fine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(576,'ngsl-2-04',10,'street','đường phố; con phố','noun','[{"en":"There is a small bakery at the end of our street.","vi":"Có một tiệm bánh nhỏ ở cuối con phố nhà chúng tôi."},{"en":"Look both ways before you cross the street.","vi":"Hãy nhìn cả hai phía trước khi băng qua đường."},{"en":"The streets were full of people during the festival.","vi":"Đường phố chật kín người trong dịp lễ hội."}]','[{"phrase":"cross the street"},{"phrase":"main street"},{"phrase":"busy street"},{"phrase":"on the street"}]',NULL,'/striːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stree/street__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(577,'ngsl-2-04',11,'former','cũ; trước đây','adjective','[{"en":"I ran into my former teacher at the supermarket.","vi":"Tôi tình cờ gặp thầy giáo cũ ở siêu thị."},{"en":"Her former boss wrote her a great reference letter.","vi":"Sếp cũ của cô ấy đã viết cho cô ấy một thư giới thiệu rất tốt."},{"en":"This hotel is a former school building.","vi":"Khách sạn này trước đây là một tòa nhà trường học."}]','[{"phrase":"former boss"},{"phrase":"former student"},{"phrase":"former home"},{"phrase":"former colleague"}]','the former … the latter: cái trước … cái sau','/ˈfɔːrmər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forme/former__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(578,'ngsl-2-04',12,'contact','liên lạc; sự tiếp xúc','noun','[{"en":"We lost contact after she moved to another city.","vi":"Chúng tôi mất liên lạc sau khi cô ấy chuyển đến thành phố khác."},{"en":"I still keep in contact with my old classmates.","vi":"Tôi vẫn giữ liên lạc với các bạn học cũ."},{"en":"Avoid contact with the eyes when using this cream.","vi":"Tránh để kem tiếp xúc với mắt khi sử dụng."}]','[{"phrase":"keep in contact"},{"phrase":"lose contact"},{"phrase":"contact with"},{"phrase":"contact details"}]','contact sb (v): liên lạc với ai — không nói contact to sb','/ˈkɑːntækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontact__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(579,'ngsl-2-04',13,'particularly','đặc biệt là; nhất là','adverb','[{"en":"I love fruit, particularly mangoes and bananas.","vi":"Tôi thích trái cây, nhất là xoài và chuối."},{"en":"The roads are particularly busy on Friday evenings.","vi":"Đường sá đặc biệt đông vào các tối thứ Sáu."},{"en":"I''m not particularly hungry, so I''ll just have tea.","vi":"Tôi không đói lắm nên tôi chỉ uống trà thôi."}]','[{"phrase":"particularly important"},{"phrase":"particularly good"},{"phrase":"not particularly"}]',NULL,'/pərˈtɪkjələrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/particularly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(580,'ngsl-2-04',14,'wife','vợ','noun','[{"en":"My wife and I met at university.","vi":"Vợ tôi và tôi gặp nhau ở trường đại học."},{"en":"He called his wife to say he would be late.","vi":"Anh ấy gọi cho vợ để báo là mình sẽ về muộn."},{"en":"Their wives are planning a trip together next month.","vi":"Vợ của họ đang lên kế hoạch đi du lịch cùng nhau vào tháng tới."}]','[{"phrase":"husband and wife"},{"phrase":"my wife"},{"phrase":"his wife"}]','số nhiều: wives','/waɪf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wif/wife_/wife__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(581,'ngsl-2-04',15,'sport','thể thao; môn thể thao','noun','[{"en":"Football is the most popular sport in my country.","vi":"Bóng đá là môn thể thao phổ biến nhất ở nước tôi."},{"en":"Do you play any sports after school?","vi":"Bạn có chơi môn thể thao nào sau giờ học không?"},{"en":"My brother is good at team sports like basketball.","vi":"Anh tôi giỏi các môn thể thao đồng đội như bóng rổ."}]','[{"phrase":"play a sport"},{"phrase":"team sport"},{"phrase":"popular sport"},{"phrase":"sports club"}]',NULL,'/spɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spo/sport/sport__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(582,'ngsl-2-04',16,'prepare','chuẩn bị','verb','[{"en":"My mother is preparing dinner in the kitchen.","vi":"Mẹ tôi đang chuẩn bị bữa tối trong bếp."},{"en":"How are you preparing for your English exam?","vi":"Bạn đang chuẩn bị cho kỳ thi tiếng Anh như thế nào?"},{"en":"She prepared a short speech for the wedding.","vi":"Cô ấy đã chuẩn bị một bài phát biểu ngắn cho đám cưới."}]','[{"phrase":"prepare for"},{"phrase":"prepare a meal"},{"phrase":"prepare dinner"},{"phrase":"prepare a report"}]','prepare for sth: chuẩn bị cho việc gì','/prɪˈper/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prepa/prepare__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(583,'ngsl-2-04',17,'discuss','thảo luận; bàn bạc','verb','[{"en":"Let''s discuss this problem at the meeting tomorrow.","vi":"Hãy thảo luận vấn đề này trong cuộc họp ngày mai."},{"en":"We discussed where to go for our summer holiday.","vi":"Chúng tôi đã bàn bạc xem nên đi đâu vào kỳ nghỉ hè."},{"en":"I need to discuss my salary with my manager.","vi":"Tôi cần bàn về lương với quản lý của mình."}]','[{"phrase":"discuss a problem"},{"phrase":"discuss the matter"},{"phrase":"discuss something with"}]','discuss sth (không có about)','/dɪˈskʌs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discu/discuss__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(584,'ngsl-2-04',18,'response','phản hồi; câu trả lời; phản ứng','noun','[{"en":"I sent the email three days ago, but I haven''t had a response.","vi":"Tôi đã gửi email ba ngày trước nhưng vẫn chưa nhận được phản hồi."},{"en":"Her response to the question surprised everyone.","vi":"Câu trả lời của cô ấy cho câu hỏi khiến mọi người bất ngờ."},{"en":"The new product got a very positive response from customers.","vi":"Sản phẩm mới nhận được phản ứng rất tích cực từ khách hàng."}]','[{"phrase":"in response to"},{"phrase":"positive response"},{"phrase":"get a response"},{"phrase":"quick response"}]','in response to: để đáp lại','/rɪˈspɑːns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/response__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(585,'ngsl-2-04',19,'voice','giọng nói; tiếng nói','noun','[{"en":"She has a beautiful singing voice.","vi":"Cô ấy có giọng hát rất hay."},{"en":"Please lower your voice, the baby is sleeping.","vi":"Làm ơn nói nhỏ lại, em bé đang ngủ."},{"en":"I lost my voice after shouting at the football match.","vi":"Tôi bị mất giọng sau khi la hét ở trận bóng đá."}]','[{"phrase":"lose your voice"},{"phrase":"raise your voice"},{"phrase":"lower your voice"},{"phrase":"loud voice"}]',NULL,'/vɔɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/voi/voice/voice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(586,'ngsl-2-04',20,'piece','mẩu; miếng; mảnh','noun','[{"en":"Can I have another piece of cake, please?","vi":"Cho tôi thêm một miếng bánh nữa được không?"},{"en":"Write your name on a piece of paper.","vi":"Hãy viết tên bạn lên một mẩu giấy."},{"en":"The glass fell off the table and broke into pieces.","vi":"Cái cốc rơi khỏi bàn và vỡ thành từng mảnh."}]','[{"phrase":"a piece of paper"},{"phrase":"a piece of cake"},{"phrase":"a piece of advice"},{"phrase":"in pieces"}]','dùng để đếm danh từ không đếm được: a piece of advice','/piːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pie/piece/piece__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(587,'ngsl-2-04',21,'finish','hoàn thành; kết thúc','verb','[{"en":"Have you finished your homework yet?","vi":"Con đã làm xong bài tập về nhà chưa?"},{"en":"The movie finished just before midnight.","vi":"Bộ phim kết thúc ngay trước nửa đêm."},{"en":"I need to finish this report before I go home.","vi":"Tôi cần hoàn thành bản báo cáo này trước khi về nhà."}]','[{"phrase":"finish work"},{"phrase":"finish school"},{"phrase":"finish a meal"},{"phrase":"finish doing"}]','finish + V-ing: finish eating','/ˈfɪnɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finis/finish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(588,'ngsl-2-04',22,'suppose','cho rằng; nghĩ là; giả sử','verb','[{"en":"I suppose you''re tired after such a long trip.","vi":"Tôi nghĩ là bạn mệt sau một chuyến đi dài như vậy."},{"en":"Suppose you won a lot of money, what would you buy?","vi":"Giả sử bạn trúng được nhiều tiền, bạn sẽ mua gì?"},{"en":"You''re supposed to wear a helmet on a motorbike.","vi":"Bạn phải đội mũ bảo hiểm khi đi xe máy."}]','[{"phrase":"I suppose so"},{"phrase":"be supposed to"},{"phrase":"I don''t suppose"}]','be supposed to do: phải / đáng lẽ phải làm gì','/səˈpəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppo/suppose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(589,'ngsl-2-04',23,'apply','nộp đơn; áp dụng; bôi','verb','[{"en":"She applied for a job at the new hotel.","vi":"Cô ấy đã nộp đơn xin việc tại khách sạn mới."},{"en":"These rules apply to all students in the school.","vi":"Những quy định này áp dụng cho tất cả học sinh trong trường."},{"en":"Apply the cream twice a day to the dry skin.","vi":"Bôi kem lên vùng da khô hai lần mỗi ngày."}]','[{"phrase":"apply for a job"},{"phrase":"apply to"},{"phrase":"apply for a visa"},{"phrase":"apply cream"}]','apply for (xin) · apply to (áp dụng cho; nộp đơn vào)','/əˈplaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/apply/apply__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(590,'ngsl-2-04',24,'president','tổng thống; chủ tịch','noun','[{"en":"She was elected president of the student club.","vi":"Cô ấy được bầu làm chủ tịch câu lạc bộ sinh viên."},{"en":"The company president gave a speech at the party.","vi":"Chủ tịch công ty đã phát biểu tại bữa tiệc."},{"en":"In some countries, the president lives in a large official house.","vi":"Ở một số nước, tổng thống sống trong một dinh thự lớn."}]','[{"phrase":"vice president"},{"phrase":"elected president"},{"phrase":"company president"}]',NULL,'/ˈprezɪdənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presi/president__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(591,'ngsl-2-04',25,'fire','lửa; đám cháy; sa thải','noun','[{"en":"We sat around the fire and told stories.","vi":"Chúng tôi ngồi quanh đống lửa và kể chuyện."},{"en":"Firefighters quickly put out the fire in the kitchen.","vi":"Lính cứu hỏa nhanh chóng dập tắt đám cháy trong bếp."},{"en":"He was fired for being late to work every day.","vi":"Anh ấy bị sa thải vì ngày nào cũng đi làm muộn."}]','[{"phrase":"put out a fire"},{"phrase":"start a fire"},{"phrase":"catch fire"},{"phrase":"on fire"}]','fire (v) sa thải · catch fire: bắt lửa','/ˈfaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/fire_/fire__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(592,'ngsl-2-04',26,'compare','so sánh','verb','[{"en":"Always compare prices before you buy a new phone.","vi":"Hãy luôn so sánh giá trước khi mua điện thoại mới."},{"en":"Don''t compare yourself with other people.","vi":"Đừng so sánh bản thân với người khác."},{"en":"Compared to last year, this winter has been quite warm.","vi":"So với năm ngoái, mùa đông năm nay khá ấm."}]','[{"phrase":"compare prices"},{"phrase":"compare with"},{"phrase":"compared to"},{"phrase":"compare notes"}]','compare A with/to B','/kəmˈper/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/compare__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(593,'ngsl-2-04',27,'court','tòa án; sân (quần vợt, bóng rổ)','noun','[{"en":"The case will go to court next month.","vi":"Vụ việc sẽ được đưa ra tòa vào tháng tới."},{"en":"He had to appear in court as a witness.","vi":"Anh ấy phải ra tòa với tư cách nhân chứng."},{"en":"There are two tennis courts behind the hotel.","vi":"Có hai sân quần vợt phía sau khách sạn."}]','[{"phrase":"go to court"},{"phrase":"in court"},{"phrase":"tennis court"},{"phrase":"basketball court"}]',NULL,'/kɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/court/court__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(594,'ngsl-2-04',28,'police','cảnh sát; công an','noun','[{"en":"Someone stole my bike, so I called the police.","vi":"Có người lấy trộm xe đạp của tôi nên tôi đã gọi cảnh sát."},{"en":"The police are looking for the lost child.","vi":"Cảnh sát đang tìm kiếm đứa trẻ bị lạc."},{"en":"A police officer helped the old man cross the road.","vi":"Một viên cảnh sát đã giúp cụ già băng qua đường."}]','[{"phrase":"call the police"},{"phrase":"police officer"},{"phrase":"police station"},{"phrase":"tell the police"}]','police luôn đi với động từ số nhiều: the police are','/pəˈliːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polic/police__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(595,'ngsl-2-04',29,'store','cửa hàng; cất giữ; lưu trữ','noun','[{"en":"I''m going to the store to buy some milk.","vi":"Tôi ra cửa hàng mua ít sữa."},{"en":"The new department store opens on Saturday.","vi":"Cửa hàng bách hóa mới khai trương vào thứ Bảy."},{"en":"We store our winter clothes under the bed.","vi":"Chúng tôi cất quần áo mùa đông dưới gầm giường."}]','[{"phrase":"grocery store"},{"phrase":"department store"},{"phrase":"store data"},{"phrase":"go to the store"}]','Mỹ: store · Anh: shop','/stɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/store/store__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(596,'ngsl-2-05',1,'poor','nghèo; kém, tồi','adjective','[{"en":"His family was very poor when he was a child.","vi":"Gia đình anh ấy rất nghèo khi anh ấy còn nhỏ."},{"en":"Many poor families cannot afford to see a doctor.","vi":"Nhiều gia đình nghèo không đủ tiền đi khám bác sĩ."},{"en":"The hotel was cheap, but the food was of poor quality.","vi":"Khách sạn thì rẻ, nhưng đồ ăn chất lượng kém."}]','[{"phrase":"poor family"},{"phrase":"poor quality"},{"phrase":"poor health"}]',NULL,'/pʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poo/poor_/poor__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(597,'ngsl-2-05',2,'knowledge','kiến thức; sự hiểu biết','noun','[{"en":"I only have a basic knowledge of computers.","vi":"Tôi chỉ có kiến thức cơ bản về máy tính."},{"en":"You don''t need any special knowledge to use this app.","vi":"Bạn không cần hiểu biết gì đặc biệt để dùng ứng dụng này."},{"en":"Reading every day helped him build his knowledge of English.","vi":"Đọc sách mỗi ngày đã giúp anh ấy mở rộng kiến thức tiếng Anh."}]','[{"phrase":"basic knowledge"},{"phrase":"general knowledge"},{"phrase":"knowledge of"}]','không đếm được','/ˈnɑːlɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kno/knowl/knowledge__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(598,'ngsl-2-05',3,'laugh','cười (thành tiếng); cười nhạo','verb','[{"en":"Everyone laughed when he told the joke.","vi":"Mọi người đều cười khi anh ấy kể câu chuyện cười."},{"en":"My little brother always makes me laugh.","vi":"Em trai tôi lúc nào cũng làm tôi bật cười."},{"en":"Please don''t laugh at me, I''m trying my best.","vi":"Làm ơn đừng cười nhạo tôi, tôi đang cố hết sức rồi."}]','[{"phrase":"laugh at"},{"phrase":"make someone laugh"},{"phrase":"laugh out loud"}]','laugh at sb: cười nhạo ai','/læf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lau/laugh/laugh__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(599,'ngsl-2-05',4,'arm','cánh tay','noun','[{"en":"He came to school with a broken arm.","vi":"Cậu ấy đến trường với một cánh tay bị gãy."},{"en":"The father held the sleeping baby in his arms.","vi":"Người bố bế đứa bé đang ngủ trong tay."},{"en":"The old couple walked along the beach arm in arm.","vi":"Đôi vợ chồng già khoác tay nhau đi dọc bãi biển."}]','[{"phrase":"broken arm"},{"phrase":"arm in arm"},{"phrase":"in someone''s arms"}]',NULL,'/ɑːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arm/arm__/arm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(600,'ngsl-2-05',5,'heart','tim; trái tim, tấm lòng','noun','[{"en":"Eating too much salt can lead to heart disease.","vi":"Ăn quá nhiều muối có thể dẫn đến bệnh tim."},{"en":"My heart was beating fast before the exam.","vi":"Tim tôi đập nhanh trước giờ thi."},{"en":"She has a kind heart and always helps her neighbors.","vi":"Cô ấy có tấm lòng tốt và luôn giúp đỡ hàng xóm."}]','[{"phrase":"heart disease"},{"phrase":"heart attack"},{"phrase":"kind heart"}]',NULL,'/hɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heart/heart__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(601,'ngsl-2-05',6,'source','nguồn; nguồn gốc','noun','[{"en":"Fish is a good source of protein.","vi":"Cá là một nguồn cung cấp đạm tốt."},{"en":"Tourism is the island''s main source of income.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo."},{"en":"The mechanic couldn''t find the source of the noise.","vi":"Người thợ sửa xe không tìm ra nguồn gốc của tiếng ồn."}]','[{"phrase":"source of income"},{"phrase":"main source"},{"phrase":"energy source"}]',NULL,'/sɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/sourc/source__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(602,'ngsl-2-05',7,'employee','nhân viên, người lao động','noun','[{"en":"We hired three new employees this year.","vi":"Năm nay chúng tôi đã tuyển ba nhân viên mới."},{"en":"All employees must wear a name badge at work.","vi":"Tất cả nhân viên phải đeo thẻ tên khi làm việc."},{"en":"She was named employee of the month in March.","vi":"Cô ấy được bầu là nhân viên xuất sắc của tháng Ba."}]','[{"phrase":"new employee"},{"phrase":"full-time employee"},{"phrase":"employee of the month"}]',NULL,'/ɪmˈplɔɪiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employee__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(603,'ngsl-2-05',8,'manage','quản lý; xoay xở, làm được','verb','[{"en":"As a team leader, she has to manage ten people.","vi":"Là trưởng nhóm, cô ấy phải quản lý mười người."},{"en":"How did you manage to finish the work so quickly?","vi":"Làm sao bạn xoay xở hoàn thành công việc nhanh vậy?"},{"en":"Don''t worry, we''ll manage without a car for a week.","vi":"Đừng lo, chúng ta sẽ xoay xở được mà không cần xe một tuần."}]','[{"phrase":"manage to"},{"phrase":"manage a team"},{"phrase":"manage money"}]','manage to do sth: xoay xở làm được việc gì','/ˈmænɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manag/manage__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(604,'ngsl-2-05',9,'simply','chỉ, đơn giản là; một cách đơn giản','adverb','[{"en":"I didn''t call him back simply because I forgot.","vi":"Tôi không gọi lại cho anh ấy chỉ đơn giản vì tôi quên."},{"en":"Put simply, we don''t have enough money this year.","vi":"Nói đơn giản thì năm nay chúng ta không đủ tiền."},{"en":"The teacher explained the rules simply and clearly.","vi":"Cô giáo giải thích luật một cách đơn giản và rõ ràng."}]','[{"phrase":"simply because"},{"phrase":"put simply"},{"phrase":"quite simply"}]',NULL,'/ˈsɪmpli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simpl/simply__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(605,'ngsl-2-05',10,'bank','ngân hàng; bờ (sông, hồ)','noun','[{"en":"I need to go to the bank to take out some cash.","vi":"Tôi cần ra ngân hàng để rút ít tiền mặt."},{"en":"She opened a bank account when she started her first job.","vi":"Cô ấy mở tài khoản ngân hàng khi bắt đầu công việc đầu tiên."},{"en":"We had a picnic on the bank of the river.","vi":"Chúng tôi đi dã ngoại trên bờ sông."}]','[{"phrase":"bank account"},{"phrase":"go to the bank"},{"phrase":"bank loan"}]',NULL,'/bæŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ban/bank_/bank__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(606,'ngsl-2-05',11,'firm','công ty, hãng','noun','[{"en":"My uncle works for a law firm in the city.","vi":"Chú tôi làm việc cho một công ty luật trong thành phố."},{"en":"She started her own design firm last year.","vi":"Năm ngoái cô ấy đã mở công ty thiết kế riêng."},{"en":"Many small firms are struggling to find workers.","vi":"Nhiều công ty nhỏ đang chật vật tìm người làm."}]','[{"phrase":"law firm"},{"phrase":"small firm"},{"phrase":"accounting firm"}]','firm (adj): chắc, vững','/fɜːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/firm_/firm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(607,'ngsl-2-05',12,'cell','tế bào; điện thoại di động','noun','[{"en":"Red blood cells carry oxygen around the body.","vi":"Hồng cầu vận chuyển oxy đi khắp cơ thể."},{"en":"The human body is made up of trillions of cells.","vi":"Cơ thể con người được tạo nên từ hàng nghìn tỷ tế bào."},{"en":"You can reach me on my cell after six.","vi":"Sau sáu giờ bạn có thể gọi vào di động của tôi."}]','[{"phrase":"blood cell"},{"phrase":"brain cells"},{"phrase":"cell phone"}]','cell = cell phone (Mỹ); Anh: mobile phone','/sel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cel/cell_/cell__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(608,'ngsl-2-05',13,'article','bài báo, bài viết; mạo từ','noun','[{"en":"I read an interesting newspaper article about sleep this morning.","vi":"Sáng nay tôi đọc một bài báo thú vị về giấc ngủ."},{"en":"She was asked to write an article for the school magazine.","vi":"Cô ấy được nhờ viết một bài cho tạp chí của trường."},{"en":"In English, \"a\" and \"the\" are articles.","vi":"Trong tiếng Anh, \"a\" và \"the\" là mạo từ."}]','[{"phrase":"newspaper article"},{"phrase":"write an article"},{"phrase":"definite article"}]',NULL,'/ˈɑːrtɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/art/artic/article__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(609,'ngsl-2-05',14,'fast','nhanh','adjective','[{"en":"He''s a fast runner and often wins races at school.","vi":"Cậu ấy chạy nhanh và thường thắng các cuộc đua ở trường."},{"en":"We need a fast internet connection for online classes.","vi":"Chúng tôi cần kết nối mạng nhanh để học trực tuyến."},{"en":"Eating too much fast food is bad for your health.","vi":"Ăn quá nhiều đồ ăn nhanh không tốt cho sức khỏe."}]','[{"phrase":"fast food"},{"phrase":"fast runner"},{"phrase":"fast internet"}]','fast cũng là trạng từ: run fast (chạy nhanh)','/fæst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fas/fast_/fast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(610,'ngsl-2-05',15,'attack','cuộc tấn công; cơn (bệnh)','noun','[{"en":"My grandfather had a heart attack but is fine now.","vi":"Ông tôi từng bị nhồi máu cơ tim nhưng giờ đã ổn."},{"en":"The team scored after a quick attack in the second half.","vi":"Đội bóng ghi bàn sau một pha tấn công nhanh trong hiệp hai."},{"en":"Our team is strong in attack but weak in defense.","vi":"Đội chúng tôi tấn công mạnh nhưng phòng ngự yếu."}]','[{"phrase":"heart attack"},{"phrase":"under attack"},{"phrase":"launch an attack"}]',NULL,'/əˈtæk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attack__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(611,'ngsl-2-05',16,'foreign','(thuộc) nước ngoài','adjective','[{"en":"Learning a foreign language takes a lot of time and practice.","vi":"Học ngoại ngữ cần nhiều thời gian và luyện tập."},{"en":"The old town is always full of foreign tourists.","vi":"Phố cổ lúc nào cũng đông khách du lịch nước ngoài."},{"en":"He has worked for a foreign company for five years.","vi":"Anh ấy đã làm cho một công ty nước ngoài được năm năm."}]','[{"phrase":"foreign language"},{"phrase":"foreign tourists"},{"phrase":"foreign country"}]',NULL,'/ˈfɔːrən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forei/foreign__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(612,'ngsl-2-05',17,'surprise','sự ngạc nhiên; điều bất ngờ','noun','[{"en":"We''re planning a surprise party for Mom''s birthday.","vi":"Chúng tôi đang lên kế hoạch tổ chức tiệc bất ngờ cho sinh nhật mẹ."},{"en":"To my surprise, the exam was really easy.","vi":"Tôi ngạc nhiên vì bài thi thật sự rất dễ."},{"en":"What a nice surprise to see you here!","vi":"Gặp bạn ở đây thật là bất ngờ thú vị!"}]','[{"phrase":"surprise party"},{"phrase":"to my surprise"},{"phrase":"nice surprise"}]',NULL,'/sərˈpraɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surpr/surprise__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(613,'ngsl-2-05',18,'feature','đặc điểm, nét đặc trưng; tính năng','noun','[{"en":"The latest update adds a new feature for sharing photos.","vi":"Bản cập nhật mới nhất thêm một tính năng mới để chia sẻ ảnh."},{"en":"Big windows are the main feature of this house.","vi":"Những ô cửa sổ lớn là đặc điểm nổi bật của ngôi nhà này."},{"en":"One key feature of the city is its many green parks.","vi":"Một nét đặc trưng của thành phố là có nhiều công viên xanh."}]','[{"phrase":"new feature"},{"phrase":"main feature"},{"phrase":"key feature"}]',NULL,'/ˈfiːtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fea/featu/feature__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(614,'ngsl-2-05',19,'factor','yếu tố, nhân tố','noun','[{"en":"Price is an important factor when you buy a car.","vi":"Giá cả là một yếu tố quan trọng khi bạn mua xe hơi."},{"en":"Stress is often a major factor in poor sleep.","vi":"Căng thẳng thường là một yếu tố chính gây ngủ kém."},{"en":"Many factors affect how well children learn at school.","vi":"Nhiều yếu tố ảnh hưởng đến việc trẻ học tốt ra sao ở trường."}]','[{"phrase":"important factor"},{"phrase":"major factor"},{"phrase":"key factor"},{"phrase":"risk factor"}]',NULL,'/ˈfæktər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facto/factor__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(615,'ngsl-2-05',20,'pretty','khá, khá là; xinh, đẹp','adverb','[{"en":"The test was pretty easy, so I finished early.","vi":"Bài kiểm tra khá dễ nên tôi làm xong sớm."},{"en":"I''m pretty sure I left my keys at home.","vi":"Tôi khá chắc là mình để quên chìa khóa ở nhà."},{"en":"She looked really pretty in her new dress.","vi":"Cô ấy trông rất xinh trong chiếc váy mới."}]','[{"phrase":"pretty sure"},{"phrase":"pretty good"},{"phrase":"pretty much"}]','pretty (adj): xinh, đẹp','/ˈprɪti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prett/pretty__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(616,'ngsl-2-05',21,'recently','gần đây, mới đây','adverb','[{"en":"I''ve recently started going to the gym after work.","vi":"Gần đây tôi mới bắt đầu đi tập gym sau giờ làm."},{"en":"Have you seen any good movies recently?","vi":"Gần đây bạn có xem được phim nào hay không?"},{"en":"Until recently, she lived with her parents in the countryside.","vi":"Cho đến gần đây, cô ấy vẫn sống cùng bố mẹ ở quê."}]','[{"phrase":"until recently"},{"phrase":"only recently"},{"phrase":"most recently"}]',NULL,'/ˈriːsntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recen/recently__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(617,'ngsl-2-05',22,'affect','ảnh hưởng đến, tác động đến','verb','[{"en":"Lack of sleep can affect your mood and memory.","vi":"Thiếu ngủ có thể ảnh hưởng đến tâm trạng và trí nhớ của bạn."},{"en":"Hundreds of flights were badly affected by the storm.","vi":"Hàng trăm chuyến bay bị ảnh hưởng nặng nề bởi cơn bão."},{"en":"How will the new rules affect students?","vi":"Các quy định mới sẽ tác động đến học sinh như thế nào?"}]','[{"phrase":"badly affected"},{"phrase":"directly affect"},{"phrase":"seriously affect"}]','affect (v) ≠ effect (n)','/əˈfekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affec/affect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(618,'ngsl-2-05',23,'drop','làm rơi, đánh rơi; giảm; cho (ai) xuống xe','verb','[{"en":"Be careful not to drop the plates.","vi":"Cẩn thận đừng làm rơi mấy cái đĩa nhé."},{"en":"Prices tend to drop sharply after the holidays.","vi":"Giá cả thường giảm mạnh sau kỳ nghỉ lễ."},{"en":"Can you drop me off at the station on your way?","vi":"Tiện đường bạn cho tôi xuống ở nhà ga được không?"}]','[{"phrase":"drop sharply"},{"phrase":"drop off"},{"phrase":"drop something"}]','drop – dropped – dropped','/drɑːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dro/drop_/drop__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(619,'ngsl-2-05',24,'recent','gần đây, mới đây','adjective','[{"en":"In recent years, more people have started working from home.","vi":"Trong những năm gần đây, nhiều người đã bắt đầu làm việc tại nhà."},{"en":"This is a recent photo of my family.","vi":"Đây là một bức ảnh chụp gia đình tôi gần đây."},{"en":"Her most recent book is about traveling alone.","vi":"Cuốn sách mới nhất của cô ấy viết về chuyện đi du lịch một mình."}]','[{"phrase":"recent years"},{"phrase":"most recent"},{"phrase":"recent study"}]',NULL,'/ˈriːsnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recen/recent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(620,'ngsl-2-05',25,'relate','liên quan; đồng cảm, thấu hiểu','verb','[{"en":"Many health problems are closely related to stress.","vi":"Nhiều vấn đề sức khỏe có liên quan chặt chẽ đến căng thẳng."},{"en":"I can really relate to the main character in this movie.","vi":"Tôi thật sự đồng cảm với nhân vật chính trong bộ phim này."},{"en":"Please only ask questions that relate to today''s lesson.","vi":"Vui lòng chỉ đặt câu hỏi liên quan đến bài học hôm nay."}]','[{"phrase":"relate to"},{"phrase":"closely related"},{"phrase":"be related to"}]','relate to sth/sb','/rɪˈleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(621,'ngsl-2-05',26,'official','chính thức','adjective','[{"en":"The official results will be announced on Friday.","vi":"Kết quả chính thức sẽ được công bố vào thứ Sáu."},{"en":"You can buy tickets on the official website.","vi":"Bạn có thể mua vé trên trang web chính thức."},{"en":"Our country has two official languages, English and French.","vi":"Đất nước chúng tôi có hai ngôn ngữ chính thức là tiếng Anh và tiếng Pháp."}]','[{"phrase":"official website"},{"phrase":"official language"},{"phrase":"official results"}]','official (n): quan chức, viên chức','/əˈfɪʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offic/official__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(622,'ngsl-2-05',27,'financial','(thuộc) tài chính','adjective','[{"en":"The company has had financial problems this year.","vi":"Năm nay công ty gặp khó khăn về tài chính."},{"en":"She asked a financial advisor for help with her savings.","vi":"Cô ấy nhờ một chuyên gia tư vấn tài chính giúp về khoản tiết kiệm."},{"en":"Many students need financial support to go to college.","vi":"Nhiều sinh viên cần hỗ trợ tài chính để học đại học."}]','[{"phrase":"financial problems"},{"phrase":"financial support"},{"phrase":"financial advisor"}]',NULL,'/faɪˈnænʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finan/financial__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(623,'ngsl-2-05',28,'miss','nhớ (ai, cái gì); lỡ, trễ; bỏ lỡ','verb','[{"en":"I really miss my family when I''m working abroad.","vi":"Tôi rất nhớ gia đình khi đi làm ở nước ngoài."},{"en":"Hurry up or we''ll miss the bus!","vi":"Nhanh lên kẻo mình lỡ chuyến xe buýt bây giờ!"},{"en":"Don''t miss the chance to visit the old town.","vi":"Đừng bỏ lỡ cơ hội tham quan phố cổ."}]','[{"phrase":"miss the bus"},{"phrase":"miss the chance"},{"phrase":"miss school"}]',NULL,'/mɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mis/miss_/miss__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(624,'ngsl-2-05',29,'art','nghệ thuật; mỹ thuật','noun','[{"en":"The museum has a large collection of modern art.","vi":"Bảo tàng có một bộ sưu tập lớn về nghệ thuật hiện đại."},{"en":"My daughter loves her art class on Fridays.","vi":"Con gái tôi rất thích giờ học mỹ thuật vào thứ Sáu."},{"en":"She studied art in college and now works as a designer.","vi":"Cô ấy học mỹ thuật ở đại học và giờ làm nhà thiết kế."}]','[{"phrase":"modern art"},{"phrase":"art class"},{"phrase":"work of art"},{"phrase":"art gallery"}]',NULL,'/ɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/art/art__/art__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(625,'ngsl-2-06',1,'campaign','chiến dịch; cuộc vận động','noun','[{"en":"The company launched a new advertising campaign last month.","vi":"Công ty đã tung ra một chiến dịch quảng cáo mới vào tháng trước."},{"en":"Our school started a campaign to reduce plastic waste.","vi":"Trường chúng tôi đã phát động một cuộc vận động giảm rác thải nhựa."},{"en":"The campaign was a big success, and sales went up quickly.","vi":"Chiến dịch rất thành công và doanh số tăng nhanh."}]','[{"phrase":"advertising campaign"},{"phrase":"launch a campaign"},{"phrase":"marketing campaign"}]',NULL,'/kæmˈpeɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cam/campa/campaign__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(626,'ngsl-2-06',2,'private','riêng tư; tư nhân; riêng','adjective','[{"en":"Please don''t read my diary; it''s private.","vi":"Làm ơn đừng đọc nhật ký của tôi, đó là chuyện riêng tư."},{"en":"Her children go to a private school near the city center.","vi":"Các con cô ấy học ở một trường tư gần trung tâm thành phố."},{"en":"The hotel room had a private bathroom and a small balcony.","vi":"Phòng khách sạn có phòng tắm riêng và một ban công nhỏ."}]','[{"phrase":"private school"},{"phrase":"private life"},{"phrase":"private company"},{"phrase":"private bathroom"}]',NULL,'/ˈpraɪvət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/priva/private__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(627,'ngsl-2-06',3,'pause','tạm dừng; ngừng lại','verb','[{"en":"Can you pause the movie while I get some snacks?","vi":"Bạn có thể tạm dừng phim trong lúc tôi đi lấy đồ ăn vặt không?"},{"en":"She paused for a moment before answering the question.","vi":"Cô ấy ngừng lại một lúc trước khi trả lời câu hỏi."},{"en":"We paused at the top of the hill to enjoy the view.","vi":"Chúng tôi dừng lại trên đỉnh đồi để ngắm cảnh."}]','[{"phrase":"pause for a moment"},{"phrase":"pause the video"},{"phrase":"pause briefly"}]',NULL,'/pɔːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pau/pause/pause__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(628,'ngsl-2-06',4,'everyone','mọi người; ai cũng','pronoun','[{"en":"Everyone in my family loves my grandmother''s cooking.","vi":"Mọi người trong gia đình tôi đều thích món bà nấu."},{"en":"Good morning, everyone, and welcome to today''s lesson.","vi":"Chào buổi sáng mọi người, chào mừng đến với bài học hôm nay."},{"en":"Not everyone agrees with the new rules at work.","vi":"Không phải ai cũng đồng ý với các quy định mới ở chỗ làm."}]','[{"phrase":"everyone else"},{"phrase":"everyone knows"},{"phrase":"thank everyone"}]','everyone đi với động từ số ít: everyone is','/ˈevriwʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everyone__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(629,'ngsl-2-06',5,'forget','quên','verb','[{"en":"Don''t forget to lock the door when you leave.","vi":"Đừng quên khóa cửa khi bạn ra ngoài."},{"en":"I forgot my umbrella at the office yesterday.","vi":"Hôm qua tôi để quên ô ở văn phòng."},{"en":"Have you forgotten your sister''s birthday again?","vi":"Bạn lại quên sinh nhật em gái mình rồi à?"}]','[{"phrase":"forget to do"},{"phrase":"forget about"},{"phrase":"never forget"},{"phrase":"completely forget"}]','forget – forgot – forgotten','/fərˈɡet/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forge/forget__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(630,'ngsl-2-06',6,'page','trang','noun','[{"en":"Please open your books to page twenty.","vi":"Các em hãy mở sách ra trang hai mươi."},{"en":"The answers are on the last page of the book.","vi":"Đáp án nằm ở trang cuối của cuốn sách."},{"en":"I read a few pages every night before bed.","vi":"Tối nào trước khi ngủ tôi cũng đọc vài trang."}]','[{"phrase":"front page"},{"phrase":"turn the page"},{"phrase":"next page"},{"phrase":"web page"}]',NULL,'/peɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pag/page_/page__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(631,'ngsl-2-06',7,'worry','lo lắng; lo','verb','[{"en":"Don''t worry, I''ll be home before dark.","vi":"Đừng lo, tôi sẽ về nhà trước khi trời tối."},{"en":"My parents always worry about my health.","vi":"Bố mẹ tôi lúc nào cũng lo lắng về sức khỏe của tôi."},{"en":"She worried that she would miss the last train.","vi":"Cô ấy lo rằng mình sẽ lỡ chuyến tàu cuối."}]','[{"phrase":"worry about"},{"phrase":"don''t worry"},{"phrase":"worry too much"}]','worry about something','/ˈwɜːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/worry/worry__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(632,'ngsl-2-06',8,'summer','mùa hè','noun','[{"en":"We visit my grandparents in the countryside every summer.","vi":"Mùa hè nào chúng tôi cũng về quê thăm ông bà."},{"en":"It gets very hot here in the summer.","vi":"Ở đây vào mùa hè trời rất nóng."},{"en":"Are you taking any classes this summer?","vi":"Hè này bạn có học lớp nào không?"}]','[{"phrase":"summer holiday"},{"phrase":"last summer"},{"phrase":"summer vacation"},{"phrase":"in the summer"}]',NULL,'/ˈsʌmər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summe/summer__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(633,'ngsl-2-06',9,'drink','uống; đồ uống','verb','[{"en":"You should drink plenty of water when it''s hot.","vi":"Bạn nên uống nhiều nước khi trời nóng."},{"en":"He drank a cup of coffee before the meeting.","vi":"Anh ấy đã uống một tách cà phê trước cuộc họp."},{"en":"Would you like something to drink before dinner?","vi":"Bạn có muốn uống gì trước bữa tối không?"}]','[{"phrase":"drink water"},{"phrase":"drink coffee"},{"phrase":"something to drink"}]','drink – drank – drunk','/drɪŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dri/drink/drink__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(634,'ngsl-2-06',10,'opinion','ý kiến; quan điểm','noun','[{"en":"In my opinion, the book is better than the movie.","vi":"Theo ý kiến của tôi, cuốn sách hay hơn bộ phim."},{"en":"Everyone has a different opinion about the new park.","vi":"Mỗi người có một quan điểm khác nhau về công viên mới."},{"en":"Can I ask your opinion on this dress?","vi":"Tôi có thể hỏi ý kiến của bạn về chiếc váy này không?"}]','[{"phrase":"in my opinion"},{"phrase":"public opinion"},{"phrase":"ask someone''s opinion"},{"phrase":"express an opinion"}]',NULL,'/əˈpɪnjən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opi/opini/opinion__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(635,'ngsl-2-06',11,'park','công viên','noun','[{"en":"We often take the kids to the park on Sundays.","vi":"Chúng tôi thường đưa bọn trẻ ra công viên vào Chủ nhật."},{"en":"There is a small park right behind our apartment building.","vi":"Ngay phía sau tòa chung cư của chúng tôi có một công viên nhỏ."},{"en":"My dad goes jogging in the park every morning.","vi":"Bố tôi chạy bộ trong công viên mỗi sáng."}]','[{"phrase":"in the park"},{"phrase":"national park"},{"phrase":"theme park"},{"phrase":"walk in the park"}]','cũng là động từ: park a car (đỗ xe)','/pɑːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/park_/park__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(636,'ngsl-2-06',12,'represent','đại diện; tượng trưng','verb','[{"en":"She was chosen to represent our school in the competition.","vi":"Cô ấy được chọn để đại diện trường chúng tôi trong cuộc thi."},{"en":"A lawyer will represent him in court.","vi":"Một luật sư sẽ đại diện cho anh ấy trước tòa."},{"en":"On this map, the blue lines represent rivers.","vi":"Trên bản đồ này, các đường màu xanh tượng trưng cho sông."}]','[{"phrase":"represent the country"},{"phrase":"represent a client"},{"phrase":"represent the school"}]',NULL,'/ˌreprɪˈzent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repre/represent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(637,'ngsl-2-06',13,'key','chìa khóa; bí quyết; phím','noun','[{"en":"I can''t find my car keys anywhere.","vi":"Tôi tìm khắp nơi mà không thấy chìa khóa xe."},{"en":"Hard work is the key to success.","vi":"Chăm chỉ là bí quyết để thành công."},{"en":"Press any key on the keyboard to continue.","vi":"Nhấn phím bất kỳ trên bàn phím để tiếp tục."}]','[{"phrase":"car keys"},{"phrase":"the key to success"},{"phrase":"press a key"},{"phrase":"lose your keys"}]','the key to something','/kiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/key/key__/key__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(638,'ngsl-2-06',14,'inside','bên trong; ở trong','preposition','[{"en":"I left my phone inside the car.","vi":"Tôi để quên điện thoại trong xe."},{"en":"What''s inside the box you got for your birthday?","vi":"Trong chiếc hộp bạn nhận được vào sinh nhật có gì vậy?"},{"en":"It was much warmer inside the house than outside.","vi":"Bên trong nhà ấm hơn bên ngoài nhiều."}]','[{"phrase":"inside the house"},{"phrase":"inside the box"},{"phrase":"deep inside"}]','inside ≠ outside','/ˌɪnˈsaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insid/inside__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(639,'ngsl-2-06',15,'manager','người quản lý; giám đốc','noun','[{"en":"I''d like to speak to the manager, please.","vi":"Làm ơn cho tôi gặp người quản lý."},{"en":"She became a sales manager at twenty-eight.","vi":"Cô ấy trở thành giám đốc kinh doanh năm hai mươi tám tuổi."},{"en":"My manager lets me work from home on Fridays.","vi":"Quản lý cho tôi làm việc ở nhà vào các ngày thứ Sáu."}]','[{"phrase":"sales manager"},{"phrase":"general manager"},{"phrase":"project manager"},{"phrase":"store manager"}]',NULL,'/ˈmænɪdʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manag/manager__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(640,'ngsl-2-06',16,'international','quốc tế','adjective','[{"en":"Our flight leaves from the international terminal.","vi":"Chuyến bay của chúng tôi khởi hành từ nhà ga quốc tế."},{"en":"Many international students study at this university.","vi":"Nhiều sinh viên quốc tế học tại trường đại học này."},{"en":"He works for an international company in Singapore.","vi":"Anh ấy làm việc cho một công ty quốc tế ở Singapore."}]','[{"phrase":"international students"},{"phrase":"international airport"},{"phrase":"international company"},{"phrase":"international trade"}]',NULL,'/ˌɪntərˈnæʃnəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/international__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(641,'ngsl-2-06',17,'contain','chứa; bao gồm','verb','[{"en":"This drink contains a lot of sugar.","vi":"Loại đồ uống này chứa rất nhiều đường."},{"en":"The box contained old photos and letters.","vi":"Chiếc hộp chứa những bức ảnh và lá thư cũ."},{"en":"Does the final report contain any spelling mistakes?","vi":"Bản báo cáo cuối cùng có lỗi chính tả nào không?"}]','[{"phrase":"contain information"},{"phrase":"contain sugar"},{"phrase":"contain mistakes"}]','không dùng ở thì tiếp diễn','/kənˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(642,'ngsl-2-06',18,'notice','nhận thấy; để ý','verb','[{"en":"Did you notice that she cut her hair?","vi":"Bạn có để ý là cô ấy đã cắt tóc không?"},{"en":"I didn''t notice the mistake until I printed the letter.","vi":"Mãi đến khi in lá thư ra tôi mới nhận thấy lỗi sai."},{"en":"Nobody noticed when he left the party.","vi":"Không ai để ý khi anh ấy rời bữa tiệc."}]','[{"phrase":"notice a change"},{"phrase":"notice a difference"},{"phrase":"suddenly notice"}]','cũng là danh từ: thông báo','/ˈnəʊtɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notic/notice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(643,'ngsl-2-06',19,'wonder','tự hỏi; thắc mắc','verb','[{"en":"I wonder why she didn''t come to class today.","vi":"Tôi tự hỏi sao hôm nay cô ấy không đến lớp."},{"en":"We were wondering if you could help us move on Saturday.","vi":"Chúng tôi muốn hỏi liệu bạn có thể giúp chúng tôi chuyển nhà vào thứ Bảy không."},{"en":"He wondered what his old friends were doing now.","vi":"Anh ấy thắc mắc không biết giờ những người bạn cũ đang làm gì."}]','[{"phrase":"wonder why"},{"phrase":"wonder if"},{"phrase":"I wonder whether"}]','I was wondering if… = cách hỏi lịch sự','/ˈwʌndər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/won/wonde/wonder__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(644,'ngsl-2-06',20,'nature','thiên nhiên; bản chất; tính cách','noun','[{"en":"We love spending weekends in nature, away from the city.","vi":"Chúng tôi thích dành cuối tuần hòa mình vào thiên nhiên, tránh xa thành phố."},{"en":"It''s not in her nature to complain.","vi":"Phàn nàn không phải là tính cách của cô ấy."},{"en":"The teacher explained the nature of the problem clearly.","vi":"Giáo viên đã giải thích rõ bản chất của vấn đề."}]','[{"phrase":"human nature"},{"phrase":"nature of the problem"},{"phrase":"in nature"},{"phrase":"love of nature"}]','nghĩa thiên nhiên: không đếm được','/ˈneɪtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natur/nature__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(645,'ngsl-2-06',21,'structure','cấu trúc; kết cấu; công trình','noun','[{"en":"Our teacher explained the structure of a good essay.","vi":"Giáo viên đã giải thích cấu trúc của một bài luận hay."},{"en":"This sentence structure is common in spoken English.","vi":"Cấu trúc câu này rất phổ biến trong tiếng Anh nói."},{"en":"The old bridge is the tallest structure in the town.","vi":"Cây cầu cũ là công trình cao nhất trong thị trấn."}]','[{"phrase":"sentence structure"},{"phrase":"basic structure"},{"phrase":"social structure"}]',NULL,'/ˈstrʌktʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/struc/structure__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(646,'ngsl-2-06',22,'section','phần; mục; khu vực','noun','[{"en":"Please read the first section of the report before the meeting.","vi":"Hãy đọc phần đầu của bản báo cáo trước cuộc họp."},{"en":"You can find cookbooks in the food section of the bookstore.","vi":"Bạn có thể tìm sách nấu ăn ở khu ẩm thực của hiệu sách."},{"en":"I usually skip the sports section of the newspaper.","vi":"Tôi thường bỏ qua mục thể thao trên báo."}]','[{"phrase":"first section"},{"phrase":"sports section"},{"phrase":"section of the report"}]',NULL,'/ˈsekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secti/section__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(647,'ngsl-2-06',23,'exactly','chính xác; đúng','adverb','[{"en":"The train arrived at exactly nine o''clock.","vi":"Tàu đến đúng chín giờ."},{"en":"I don''t know exactly where he lives.","vi":"Tôi không biết chính xác anh ấy sống ở đâu."},{"en":"Your new bag looks exactly like the one my sister has.","vi":"Chiếc túi mới của bạn trông giống hệt chiếc túi của chị tôi."}]','[{"phrase":"exactly the same"},{"phrase":"not exactly"},{"phrase":"exactly what"},{"phrase":"know exactly"}]',NULL,'/ɪɡˈzæktli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exact/exactly__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(648,'ngsl-2-06',24,'plant','cây; nhà máy','noun','[{"en":"Don''t forget to water the plants while I''m away.","vi":"Đừng quên tưới cây khi tôi đi vắng nhé."},{"en":"She keeps a few small plants on her office desk.","vi":"Cô ấy để vài chậu cây nhỏ trên bàn làm việc."},{"en":"My uncle works at a power plant outside the city.","vi":"Chú tôi làm việc ở một nhà máy điện ngoài thành phố."}]','[{"phrase":"water the plants"},{"phrase":"power plant"},{"phrase":"house plant"}]','cũng là động từ: trồng (plant a tree)','/plænt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plant/plant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(649,'ngsl-2-06',25,'paint','sơn; vẽ (tranh)','verb','[{"en":"We painted the kitchen walls light yellow.","vi":"Chúng tôi đã sơn tường bếp màu vàng nhạt."},{"en":"My sister likes to paint flowers and trees.","vi":"Em gái tôi thích vẽ hoa và cây."},{"en":"Are you going to paint the fence this weekend?","vi":"Cuối tuần này bạn có định sơn hàng rào không?"}]','[{"phrase":"paint a picture"},{"phrase":"paint the walls"},{"phrase":"paint a room"}]','cũng là danh từ: sơn (wet paint)','/peɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pai/paint/paint__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(650,'ngsl-2-06',26,'worker','công nhân; người lao động','noun','[{"en":"The factory hired two hundred new workers this year.","vi":"Năm nay nhà máy đã tuyển hai trăm công nhân mới."},{"en":"She is a hard worker and never misses a deadline.","vi":"Cô ấy là người làm việc chăm chỉ và không bao giờ trễ hạn."},{"en":"Office workers often eat lunch at their desks.","vi":"Nhân viên văn phòng thường ăn trưa ngay tại bàn làm việc."}]','[{"phrase":"hard worker"},{"phrase":"office worker"},{"phrase":"factory worker"},{"phrase":"health workers"}]',NULL,'/ˈwɜːrkər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/worke/worker__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(651,'ngsl-2-06',27,'press','nhấn; ấn; ép','verb','[{"en":"Press the green button to start the machine.","vi":"Nhấn nút màu xanh để khởi động máy."},{"en":"She pressed her face against the window to see outside.","vi":"Cô ấy áp mặt vào cửa sổ để nhìn ra ngoài."},{"en":"He pressed the doorbell, but nobody answered.","vi":"Anh ấy bấm chuông cửa nhưng không ai trả lời."}]','[{"phrase":"press a button"},{"phrase":"press a key"},{"phrase":"press hard"}]','cũng là danh từ: the press (báo chí)','/pres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/press/press__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(652,'ngsl-2-06',28,'whatever','bất cứ thứ gì; dù thế nào','pronoun','[{"en":"You can order whatever you want from the menu.","vi":"Bạn có thể gọi bất cứ món gì bạn muốn trong thực đơn."},{"en":"Whatever happens, I''ll always be on your side.","vi":"Dù có chuyện gì xảy ra, tôi vẫn luôn ở bên bạn."},{"en":"She believes whatever her older brother tells her.","vi":"Anh trai nói gì cô ấy cũng tin."}]','[{"phrase":"whatever you want"},{"phrase":"whatever happens"},{"phrase":"whatever it takes"}]',NULL,'/wətˈevər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wha/whate/whatever__us_3_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(653,'ngsl-2-06',29,'necessary','cần thiết','adjective','[{"en":"Is it necessary to book a table in advance?","vi":"Có cần đặt bàn trước không?"},{"en":"Call me if necessary, even late at night.","vi":"Nếu cần thì gọi cho tôi, kể cả lúc khuya."},{"en":"The doctor said that surgery wasn''t necessary for my knee.","vi":"Bác sĩ nói đầu gối của tôi không cần thiết phải phẫu thuật."}]','[{"phrase":"absolutely necessary"},{"phrase":"if necessary"},{"phrase":"necessary to do"},{"phrase":"necessary for"}]',NULL,'/ˈnesəseri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nec/neces/necessary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(654,'ngsl-2-07',1,'region','vùng; khu vực','noun','[{"en":"This region is famous for its coffee and green hills.","vi":"Vùng này nổi tiếng với cà phê và những ngọn đồi xanh."},{"en":"Heavy rain is expected in the northern region tomorrow.","vi":"Dự báo ngày mai sẽ có mưa lớn ở khu vực phía bắc."},{"en":"Many people from rural regions move to big cities for work.","vi":"Nhiều người từ các vùng nông thôn chuyển lên thành phố lớn để làm việc."}]','[{"phrase":"northern region"},{"phrase":"rural region"},{"phrase":"in the region"}]',NULL,'/ˈriːdʒən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regio/region__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(655,'ngsl-2-07',2,'growth','sự tăng trưởng; sự phát triển','noun','[{"en":"The company has seen strong growth over the past two years.","vi":"Công ty đã tăng trưởng mạnh trong hai năm qua."},{"en":"Good sleep is important for a child''s growth.","vi":"Ngủ ngon rất quan trọng cho sự phát triển của trẻ."},{"en":"Population growth has made housing in the city more expensive.","vi":"Sự gia tăng dân số đã khiến nhà ở trong thành phố đắt đỏ hơn."}]','[{"phrase":"economic growth"},{"phrase":"strong growth"},{"phrase":"population growth"},{"phrase":"rapid growth"}]',NULL,'/ɡrəʊθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gro/growt/growth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(656,'ngsl-2-07',3,'evening','buổi tối','noun','[{"en":"I like to go for a walk in the evening.","vi":"Tôi thích đi dạo vào buổi tối."},{"en":"Are you free to meet for coffee on Friday evening?","vi":"Tối thứ Sáu bạn có rảnh đi uống cà phê không?"},{"en":"Thank you for a lovely evening with your family.","vi":"Cảm ơn bạn vì một buổi tối thật vui bên gia đình bạn."}]','[{"phrase":"in the evening"},{"phrase":"this evening"},{"phrase":"Friday evening"},{"phrase":"spend the evening"}]',NULL,'/ˈiːvnɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/eveni/evening__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(657,'ngsl-2-07',4,'influence','ảnh hưởng; tác động','noun','[{"en":"My grandmother had a big influence on my life.","vi":"Bà tôi có ảnh hưởng lớn đến cuộc đời tôi."},{"en":"Parents should be aware of the influence of social media on teenagers.","vi":"Cha mẹ nên nhận thức được tác động của mạng xã hội đối với thanh thiếu niên."},{"en":"Her teachers have been a positive influence on her.","vi":"Thầy cô đã có ảnh hưởng tích cực đến cô ấy."}]','[{"phrase":"have an influence on"},{"phrase":"strong influence"},{"phrase":"positive influence"}]','influence on sb/sth; cũng là động từ: influence sb','/ˈɪnfluəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/influ/influence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(658,'ngsl-2-07',5,'respect','sự tôn trọng; sự kính trọng','noun','[{"en":"Children should show respect for their teachers.","vi":"Trẻ em nên kính trọng thầy cô giáo."},{"en":"She earned the respect of her team by working hard.","vi":"Cô ấy nhận được sự tôn trọng của cả nhóm nhờ làm việc chăm chỉ."},{"en":"We need to treat each other with respect.","vi":"Chúng ta cần đối xử tôn trọng với nhau."}]','[{"phrase":"show respect"},{"phrase":"earn the respect"},{"phrase":"with respect"},{"phrase":"respect for"}]','respect for sb/sth; cũng là động từ: respect sb','/rɪˈspekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respe/respect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(659,'ngsl-2-07',6,'various','khác nhau; đa dạng','adjective','[{"en":"The shop sells various kinds of tea from around the world.","vi":"Cửa hàng bán nhiều loại trà khác nhau từ khắp nơi trên thế giới."},{"en":"I tried calling her at various times, but she never answered.","vi":"Tôi đã thử gọi cho cô ấy vào nhiều lúc khác nhau nhưng cô ấy không bao giờ nghe máy."},{"en":"Students can join various clubs after school.","vi":"Học sinh có thể tham gia nhiều câu lạc bộ khác nhau sau giờ học."}]','[{"phrase":"various kinds"},{"phrase":"various reasons"},{"phrase":"various ways"},{"phrase":"at various times"}]',NULL,'/ˈveriəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/vario/various__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(660,'ngsl-2-07',7,'catch','bắt; kịp (xe, tàu); mắc (bệnh)','verb','[{"en":"He caught the ball with one hand.","vi":"Anh ấy bắt quả bóng bằng một tay."},{"en":"We ran to catch the last bus home.","vi":"Chúng tôi chạy cho kịp chuyến xe buýt cuối cùng về nhà."},{"en":"I think I caught a cold from my little brother.","vi":"Tôi nghĩ mình bị lây cảm từ em trai."}]','[{"phrase":"catch a ball"},{"phrase":"catch a bus"},{"phrase":"catch a cold"},{"phrase":"catch fish"}]','catch – caught – caught','/kætʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/catch/catch__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(661,'ngsl-2-07',8,'thus','vì vậy; do đó','adverb','[{"en":"The train was delayed, and thus we missed the meeting.","vi":"Tàu bị trễ, do đó chúng tôi đã lỡ cuộc họp."},{"en":"She saved money every month and was thus able to buy a car.","vi":"Cô ấy tiết kiệm tiền hằng tháng, vì vậy đã mua được một chiếc xe hơi."},{"en":"The new system is faster and thus saves us a lot of time.","vi":"Hệ thống mới nhanh hơn và do đó giúp chúng tôi tiết kiệm nhiều thời gian."}]','[{"phrase":"and thus"},{"phrase":"thus far"}]','trang trọng, thường dùng trong văn viết','/ðʌs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thu/thus_/thus__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(662,'ngsl-2-07',9,'skill','kỹ năng','noun','[{"en":"Speaking in public is a skill you can learn.","vi":"Nói trước đám đông là một kỹ năng mà bạn có thể học được."},{"en":"This job requires good communication skills and a lot of patience.","vi":"Công việc này đòi hỏi kỹ năng giao tiếp tốt và rất nhiều kiên nhẫn."},{"en":"He wants to improve his cooking skills before moving out.","vi":"Anh ấy muốn cải thiện kỹ năng nấu ăn trước khi ra ở riêng."}]','[{"phrase":"communication skills"},{"phrase":"improve your skills"},{"phrase":"learn a skill"},{"phrase":"language skills"}]',NULL,'/skɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/skill/skill__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(663,'ngsl-2-07',10,'attempt','sự cố gắng; nỗ lực; lần thử','noun','[{"en":"She passed her driving test on the first attempt.","vi":"Cô ấy thi đỗ bằng lái ngay từ lần đầu."},{"en":"In an attempt to save money, we stopped eating out.","vi":"Để cố gắng tiết kiệm tiền, chúng tôi đã thôi ăn ở ngoài."},{"en":"His attempt to fix the old radio was not successful.","vi":"Nỗ lực sửa chiếc radio cũ của anh ấy đã không thành công."}]','[{"phrase":"make an attempt"},{"phrase":"first attempt"},{"phrase":"in an attempt to"},{"phrase":"failed attempt"}]','cũng là động từ: attempt to do sth','/əˈtempt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attem/attempt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(664,'ngsl-2-07',11,'son','con trai','noun','[{"en":"Their son is starting university next month.","vi":"Con trai họ sẽ bắt đầu học đại học vào tháng sau."},{"en":"My oldest son loves playing football with his friends.","vi":"Con trai lớn của tôi rất thích chơi bóng đá với bạn bè."},{"en":"They have two daughters and a son.","vi":"Họ có hai con gái và một con trai."}]','[{"phrase":"oldest son"},{"phrase":"only son"},{"phrase":"baby son"}]',NULL,'/sʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/son/son__/son__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(665,'ngsl-2-07',12,'simple','đơn giản; dễ','adjective','[{"en":"The instructions are simple, so anyone can follow them.","vi":"Hướng dẫn rất đơn giản nên ai cũng làm theo được."},{"en":"She prefers simple clothes in plain colors.","vi":"Cô ấy thích quần áo đơn giản, màu trơn."},{"en":"There is no simple answer to this question.","vi":"Câu hỏi này không có câu trả lời dễ dàng."}]','[{"phrase":"simple answer"},{"phrase":"simple question"},{"phrase":"keep it simple"}]',NULL,'/ˈsɪmpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simpl/simple__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(666,'ngsl-2-07',13,'medium','vừa; trung bình','adjective','[{"en":"Can I have a medium coffee with milk, please?","vi":"Cho tôi một ly cà phê sữa cỡ vừa nhé."},{"en":"Cook the onions over medium heat for five minutes.","vi":"Xào hành trên lửa vừa trong năm phút."},{"en":"He is a man of medium height with short dark hair.","vi":"Anh ấy là người đàn ông cao trung bình, tóc ngắn màu sẫm."}]','[{"phrase":"medium size"},{"phrase":"medium heat"},{"phrase":"medium height"}]','cũng là danh từ: phương tiện (truyền thông)','/ˈmiːdiəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/mediu/medium__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(667,'ngsl-2-07',14,'average','trung bình; bình thường','adjective','[{"en":"The average price of a house here has doubled.","vi":"Giá nhà trung bình ở đây đã tăng gấp đôi."},{"en":"She is taller than the average girl her age.","vi":"Cô bé cao hơn mức trung bình của các bạn gái cùng tuổi."},{"en":"It was just an average day at the office.","vi":"Đó chỉ là một ngày bình thường ở văn phòng."}]','[{"phrase":"average price"},{"phrase":"average age"},{"phrase":"average temperature"},{"phrase":"above average"}]',NULL,'/ˈævərɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ave/avera/average__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(668,'ngsl-2-07',15,'stock','hàng trong kho; cổ phiếu','noun','[{"en":"Sorry, those shoes are out of stock in your size.","vi":"Xin lỗi, đôi giày đó đã hết hàng cỡ của bạn."},{"en":"The shop keeps a large stock of winter coats.","vi":"Cửa hàng luôn có sẵn một lượng lớn áo khoác mùa đông."},{"en":"My uncle invested some of his savings in stocks.","vi":"Chú tôi đã đầu tư một phần tiền tiết kiệm vào cổ phiếu."}]','[{"phrase":"out of stock"},{"phrase":"in stock"},{"phrase":"stock market"}]',NULL,'/stɑːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stock/stock__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(669,'ngsl-2-07',16,'management','sự quản lý; ban quản lý','noun','[{"en":"Good time management helps students reduce stress.","vi":"Quản lý thời gian tốt giúp học sinh giảm căng thẳng."},{"en":"The hotel is now under new management.","vi":"Khách sạn giờ đã đổi sang ban quản lý mới."},{"en":"She wants to study business management at university.","vi":"Cô ấy muốn học quản trị kinh doanh ở đại học."}]','[{"phrase":"time management"},{"phrase":"under new management"},{"phrase":"business management"},{"phrase":"senior management"}]',NULL,'/ˈmænɪdʒmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manag/management__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(670,'ngsl-2-07',17,'character','tính cách; nhân vật','noun','[{"en":"My brother and I have very different characters.","vi":"Anh trai tôi và tôi có tính cách rất khác nhau."},{"en":"She has a strong character and never gives up easily.","vi":"Cô ấy có tính cách mạnh mẽ và không bao giờ dễ dàng bỏ cuộc."},{"en":"Who is your favorite character in the movie?","vi":"Nhân vật yêu thích của bạn trong bộ phim là ai?"}]','[{"phrase":"main character"},{"phrase":"strong character"},{"phrase":"favorite character"}]',NULL,'/ˈkærəktər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chara/character__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(671,'ngsl-2-07',18,'bed','giường','noun','[{"en":"I usually go to bed before eleven o''clock.","vi":"Tôi thường đi ngủ trước mười một giờ."},{"en":"Please make your bed before you leave for school.","vi":"Con hãy dọn giường trước khi đi học nhé."},{"en":"The hotel room has two single beds and a small desk.","vi":"Phòng khách sạn có hai giường đơn và một chiếc bàn nhỏ."}]','[{"phrase":"go to bed"},{"phrase":"make the bed"},{"phrase":"single bed"},{"phrase":"double bed"}]',NULL,'/bed/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bed/bed__/bed__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(672,'ngsl-2-07',19,'hit','đánh; va vào; đâm vào','verb','[{"en":"He hit the ball over the fence.","vi":"Anh ấy đánh quả bóng bay qua hàng rào."},{"en":"I hit my head on the kitchen cabinet this morning.","vi":"Sáng nay tôi bị đập đầu vào tủ bếp."},{"en":"The delivery truck hit our gate while it was turning around.","vi":"Xe tải giao hàng đã tông vào cổng nhà chúng tôi khi đang quay đầu."}]','[{"phrase":"hit the ball"},{"phrase":"hit your head"},{"phrase":"hit hard"}]','hit – hit – hit','/hɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hit/hit__/hit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(673,'ngsl-2-07',20,'establish','thành lập; thiết lập, tạo dựng','verb','[{"en":"The school was established more than a hundred years ago.","vi":"Ngôi trường được thành lập cách đây hơn một trăm năm."},{"en":"My grandfather established the family business in 1985.","vi":"Ông tôi thành lập doanh nghiệp gia đình vào năm 1985."},{"en":"It takes time to establish trust with new coworkers.","vi":"Cần có thời gian để tạo dựng lòng tin với đồng nghiệp mới."}]','[{"phrase":"establish a business"},{"phrase":"establish trust"},{"phrase":"establish a relationship"},{"phrase":"be established in"}]',NULL,'/ɪˈstæblɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estab/establish__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(674,'ngsl-2-07',21,'indeed','thật vậy; quả thật','adverb','[{"en":"It was indeed a very difficult decision for our family.","vi":"Đó quả thật là một quyết định rất khó khăn đối với gia đình chúng tôi."},{"en":"Thank you, the meal was very good indeed.","vi":"Cảm ơn bạn, bữa ăn thật sự rất ngon."},{"en":"Many people thought the test would be easy, and indeed it was.","vi":"Nhiều người nghĩ bài kiểm tra sẽ dễ, và quả thật là vậy."}]','[{"phrase":"very good indeed"},{"phrase":"yes, indeed"},{"phrase":"and indeed"}]','very + tính từ + indeed: nhấn mạnh','/ɪnˈdiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indee/indeed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(675,'ngsl-2-07',22,'final','cuối cùng; chung cuộc','adjective','[{"en":"This is your final chance to sign up for the trip.","vi":"Đây là cơ hội cuối cùng để bạn đăng ký chuyến đi."},{"en":"The final exam will be held on June 20.","vi":"Kỳ thi cuối kỳ sẽ được tổ chức vào ngày 20 tháng 6."},{"en":"The final score was two to one.","vi":"Tỷ số chung cuộc là 2–1."}]','[{"phrase":"final exam"},{"phrase":"final decision"},{"phrase":"final chance"},{"phrase":"final score"}]',NULL,'/ˈfaɪnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/final/final__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(676,'ngsl-2-07',23,'economy','nền kinh tế','noun','[{"en":"Tourism is very important to the local economy.","vi":"Du lịch rất quan trọng đối với nền kinh tế địa phương."},{"en":"The economy grew quickly over the last ten years.","vi":"Nền kinh tế đã tăng trưởng nhanh trong mười năm qua."},{"en":"Many small businesses closed when the economy slowed down.","vi":"Nhiều doanh nghiệp nhỏ đã đóng cửa khi nền kinh tế chững lại."}]','[{"phrase":"local economy"},{"phrase":"global economy"},{"phrase":"strong economy"}]',NULL,'/ɪˈkɑːnəmi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eco/econo/economy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(677,'ngsl-2-07',24,'fit','vừa; vừa với; sắp xếp được (thời gian)','verb','[{"en":"These jeans don''t fit me anymore, so I need new ones.","vi":"Chiếc quần jean này không còn vừa với tôi nữa nên tôi cần quần mới."},{"en":"Will all this luggage fit in the back of your car?","vi":"Chỗ hành lý này có để vừa phía sau xe của bạn không?"},{"en":"The doctor can fit you in at three o''clock tomorrow.","vi":"Bác sĩ có thể sắp xếp khám cho bạn lúc ba giờ ngày mai."}]','[{"phrase":"fit perfectly"},{"phrase":"fit in"},{"phrase":"fit into"},{"phrase":"fit well"}]','Mỹ: fit – fit – fit · Anh: fit – fitted – fitted','/fɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fit/fit__/fit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(678,'ngsl-2-07',25,'guy','anh chàng; gã','noun','[{"en":"The guy at the front desk was really helpful.","vi":"Anh chàng ở quầy lễ tân rất nhiệt tình giúp đỡ."},{"en":"He seems like a nice guy, but I don''t know him well.","vi":"Anh ấy có vẻ là người tốt, nhưng tôi không biết rõ về anh ấy."},{"en":"Are you guys coming to the party tonight?","vi":"Các bạn có đến bữa tiệc tối nay không?"}]','[{"phrase":"nice guy"},{"phrase":"good guy"},{"phrase":"you guys"}]','thân mật; you guys = các bạn','/ɡaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/guy/guy__/guy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(679,'ngsl-2-07',26,'function','chức năng','noun','[{"en":"This app has a useful function for tracking your spending.","vi":"Ứng dụng này có một chức năng hữu ích để theo dõi chi tiêu."},{"en":"The main function of the heart is to pump blood.","vi":"Chức năng chính của tim là bơm máu."},{"en":"Regular exercise helps improve brain function in older people.","vi":"Tập thể dục thường xuyên giúp cải thiện chức năng não ở người lớn tuổi."}]','[{"phrase":"main function"},{"phrase":"brain function"},{"phrase":"basic function"},{"phrase":"perform a function"}]',NULL,'/ˈfʌŋkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funct/function__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(680,'ngsl-2-07',27,'yesterday','hôm qua','adverb','[{"en":"I saw your sister at the supermarket yesterday morning.","vi":"Sáng hôm qua tôi gặp chị gái bạn ở siêu thị."},{"en":"Yesterday was the hottest day of the year so far.","vi":"Hôm qua là ngày nóng nhất trong năm tính đến nay."},{"en":"Did you finish the report I sent you yesterday?","vi":"Bạn đã làm xong bản báo cáo tôi gửi hôm qua chưa?"}]','[{"phrase":"yesterday morning"},{"phrase":"yesterday afternoon"},{"phrase":"the day before yesterday"}]',NULL,'/ˈjestərdeɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yes/yeste/yesterday__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(681,'ngsl-2-07',28,'image','hình ảnh; hình tượng','noun','[{"en":"The images on this website are very clear.","vi":"Hình ảnh trên trang web này rất rõ nét."},{"en":"The company wants to improve its public image.","vi":"Công ty muốn cải thiện hình ảnh trước công chúng."},{"en":"I still have a clear image of my first day at school.","vi":"Tôi vẫn nhớ rõ hình ảnh ngày đầu tiên đi học."}]','[{"phrase":"public image"},{"phrase":"clear image"},{"phrase":"digital image"}]',NULL,'/ˈɪmɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/image/image__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(682,'ngsl-2-07',29,'size','kích cỡ; cỡ','noun','[{"en":"Do you have these shoes in a bigger size?","vi":"Bạn có đôi giày này cỡ lớn hơn không?"},{"en":"Their new apartment is about twice the size of ours.","vi":"Căn hộ mới của họ rộng khoảng gấp đôi căn hộ của chúng tôi."},{"en":"The size of each class is limited to twenty students.","vi":"Sĩ số mỗi lớp được giới hạn ở hai mươi học sinh."}]','[{"phrase":"shoe size"},{"phrase":"bigger size"},{"phrase":"the size of"},{"phrase":"twice the size"}]',NULL,'/saɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/siz/size_/size__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(683,'ngsl-2-08',1,'behavior','hành vi; cách cư xử','noun','[{"en":"The teacher praised the children for their good behavior in class.","vi":"Cô giáo khen bọn trẻ vì đã cư xử ngoan trong lớp."},{"en":"I''m sorry about my behavior at the party last night.","vi":"Tôi xin lỗi về cách cư xử của mình ở bữa tiệc tối qua."},{"en":"Scientists study the behavior of animals in the wild.","vi":"Các nhà khoa học nghiên cứu hành vi của động vật trong tự nhiên."}]','[{"phrase":"good behavior"},{"phrase":"bad behavior"},{"phrase":"animal behavior"},{"phrase":"change behavior"}]','Anh: behaviour · Mỹ: behavior','/bɪˈheɪvjər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(684,'ngsl-2-08',2,'addition','sự thêm vào; phần bổ sung; phép cộng','noun','[{"en":"In addition to English, she speaks French and Japanese.","vi":"Ngoài tiếng Anh, cô ấy còn nói được tiếng Pháp và tiếng Nhật."},{"en":"The new kitchen is a great addition to our house.","vi":"Căn bếp mới là một phần bổ sung tuyệt vời cho ngôi nhà của chúng tôi."},{"en":"My son is learning addition and subtraction at school.","vi":"Con trai tôi đang học phép cộng và phép trừ ở trường."}]','[{"phrase":"in addition"},{"phrase":"in addition to"},{"phrase":"a welcome addition"},{"phrase":"a new addition"}]','in addition to + N/V-ing: ngoài … ra','/əˈdɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/addit/addition__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(685,'ngsl-2-08',3,'determine','xác định; quyết định','verb','[{"en":"Doctors are trying to determine the cause of her illness.","vi":"Các bác sĩ đang cố xác định nguyên nhân gây bệnh của cô ấy."},{"en":"Police have not yet determined how the fire started.","vi":"Cảnh sát vẫn chưa xác định được đám cháy bắt đầu như thế nào."},{"en":"Your grades will determine which university you can attend.","vi":"Điểm số của bạn sẽ quyết định bạn có thể vào trường đại học nào."}]','[{"phrase":"determine the cause"},{"phrase":"help determine"},{"phrase":"determine whether"}]',NULL,'/dɪˈtɜːrmɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/deter/determine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(686,'ngsl-2-08',4,'station','nhà ga; trạm; bến (xe)','noun','[{"en":"I''ll meet you at the train station at six o''clock.","vi":"Tôi sẽ gặp bạn ở ga tàu lúc sáu giờ."},{"en":"We stopped at a gas station to buy some snacks.","vi":"Chúng tôi dừng ở một trạm xăng để mua ít đồ ăn vặt."},{"en":"How far is the nearest bus station from here?","vi":"Bến xe buýt gần nhất cách đây bao xa?"}]','[{"phrase":"train station"},{"phrase":"bus station"},{"phrase":"gas station"},{"phrase":"police station"}]',NULL,'/ˈsteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stati/station__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(687,'ngsl-2-08',5,'population','dân số; dân cư','noun','[{"en":"The population of the city has doubled in twenty years.","vi":"Dân số của thành phố đã tăng gấp đôi trong hai mươi năm."},{"en":"Our town has a population of about fifty thousand.","vi":"Thị trấn của chúng tôi có dân số khoảng năm mươi nghìn người."},{"en":"Most of the population lives near the coast.","vi":"Phần lớn dân cư sống gần bờ biển."}]','[{"phrase":"large population"},{"phrase":"growing population"},{"phrase":"population growth"},{"phrase":"world population"}]',NULL,'/ˌpɑːpjuˈleɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pop/popul/population__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(688,'ngsl-2-08',6,'fail','thất bại; trượt (kỳ thi); không làm được','verb','[{"en":"He failed his driving test for the second time.","vi":"Anh ấy trượt bài thi lái xe lần thứ hai."},{"en":"Our first plan failed, so we tried something different.","vi":"Kế hoạch đầu tiên của chúng tôi thất bại, nên chúng tôi đã thử cách khác."},{"en":"The bus failed to arrive on time again this morning.","vi":"Sáng nay xe buýt lại không đến đúng giờ."}]','[{"phrase":"fail a test"},{"phrase":"fail an exam"},{"phrase":"fail completely"}]','fail to do sth: không làm được việc gì','/feɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/fail_/fail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(689,'ngsl-2-08',7,'environment','môi trường','noun','[{"en":"We should all do more to protect the environment.","vi":"Tất cả chúng ta nên làm nhiều hơn để bảo vệ môi trường."},{"en":"Children learn best in a safe and happy environment.","vi":"Trẻ em học tốt nhất trong một môi trường an toàn và vui vẻ."},{"en":"Plastic bags are really bad for the environment.","vi":"Túi ni lông thực sự có hại cho môi trường."}]','[{"phrase":"protect the environment"},{"phrase":"work environment"},{"phrase":"safe environment"},{"phrase":"natural environment"}]',NULL,'/ɪnˈvaɪrənmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envir/environment__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(690,'ngsl-2-08',8,'production','sự sản xuất; sản lượng','noun','[{"en":"The factory increased production to meet the high demand.","vi":"Nhà máy đã tăng sản lượng để đáp ứng nhu cầu cao."},{"en":"Rice production in the region fell because of the drought.","vi":"Sản lượng lúa gạo trong vùng giảm vì hạn hán."},{"en":"Production of the new phone will start next month.","vi":"Việc sản xuất mẫu điện thoại mới sẽ bắt đầu vào tháng sau."}]','[{"phrase":"increase production"},{"phrase":"food production"},{"phrase":"mass production"},{"phrase":"production costs"}]',NULL,'/prəˈdʌkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/production__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(691,'ngsl-2-08',9,'contract','hợp đồng','noun','[{"en":"She signed a two-year contract with a local company.","vi":"Cô ấy đã ký hợp đồng hai năm với một công ty địa phương."},{"en":"Please read the contract carefully before you sign it.","vi":"Vui lòng đọc kỹ hợp đồng trước khi ký."},{"en":"His contract ends in December, so he''s looking for a new job.","vi":"Hợp đồng của anh ấy hết hạn vào tháng Mười Hai, nên anh ấy đang tìm việc mới."}]','[{"phrase":"sign a contract"},{"phrase":"break a contract"},{"phrase":"employment contract"},{"phrase":"under contract"}]',NULL,'/ˈkɑːntrækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontract__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(692,'ngsl-2-08',10,'player','người chơi; cầu thủ','noun','[{"en":"He is the best player on our school''s soccer team.","vi":"Cậu ấy là cầu thủ giỏi nhất trong đội bóng đá của trường chúng tôi."},{"en":"This board game needs at least four players.","vi":"Trò chơi cờ bàn này cần ít nhất bốn người chơi."},{"en":"My sister is a talented piano player.","vi":"Chị tôi là một người chơi piano có tài."}]','[{"phrase":"soccer player"},{"phrase":"tennis player"},{"phrase":"key player"},{"phrase":"piano player"}]',NULL,'/ˈpleɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/playe/player__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(693,'ngsl-2-08',11,'comment','lời bình luận; lời nhận xét','noun','[{"en":"Thanks for your helpful comments on my essay.","vi":"Cảm ơn những nhận xét hữu ích của bạn về bài luận của tôi."},{"en":"She made a rude comment about my new haircut.","vi":"Cô ấy đưa ra một lời nhận xét bất lịch sự về kiểu tóc mới của tôi."},{"en":"Hundreds of people left comments under the video.","vi":"Hàng trăm người đã để lại bình luận dưới video."}]','[{"phrase":"make a comment"},{"phrase":"leave a comment"},{"phrase":"no comment"}]',NULL,'/ˈkɑːment/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/comment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(694,'ngsl-2-08',12,'enter','đi vào; nhập (dữ liệu); tham gia (cuộc thi)','verb','[{"en":"Please knock before you enter the room.","vi":"Vui lòng gõ cửa trước khi vào phòng."},{"en":"Enter your password and click the blue button.","vi":"Hãy nhập mật khẩu và nhấn vào nút màu xanh."},{"en":"She entered a cooking competition and won second prize.","vi":"Cô ấy tham gia một cuộc thi nấu ăn và giành giải nhì."}]','[{"phrase":"enter the room"},{"phrase":"enter a password"},{"phrase":"enter a competition"},{"phrase":"enter the country"}]','enter the room (không nói "enter into the room")','/ˈentər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/enter__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(695,'ngsl-2-08',13,'occur','xảy ra; nảy ra (trong đầu)','verb','[{"en":"The accident occurred on a busy road near the school.","vi":"Vụ tai nạn xảy ra trên một con đường đông đúc gần trường học."},{"en":"Please tell us if the problem occurs again.","vi":"Vui lòng báo cho chúng tôi nếu sự cố lại xảy ra."},{"en":"It never occurred to me that she might be lonely.","vi":"Tôi chưa bao giờ nghĩ đến việc cô ấy có thể đang cô đơn."}]','[{"phrase":"occur naturally"},{"phrase":"problems occur"},{"phrase":"it occurred to me"}]','occurred, occurring (gấp đôi r); occur to sb: chợt nghĩ ra','/əˈkɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occur/occur__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(696,'ngsl-2-08',14,'alone','một mình','adverb','[{"en":"My grandmother lives alone, so I visit her every weekend.","vi":"Bà tôi sống một mình, nên cuối tuần nào tôi cũng đến thăm bà."},{"en":"I don''t like being alone in the house at night.","vi":"Tôi không thích ở nhà một mình vào ban đêm."},{"en":"Is it safe for a woman to travel alone?","vi":"Phụ nữ đi du lịch một mình có an toàn không?"}]','[{"phrase":"live alone"},{"phrase":"travel alone"},{"phrase":"leave me alone"},{"phrase":"all alone"}]',NULL,'/əˈləʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alo/alone/alone__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(697,'ngsl-2-08',15,'significant','đáng kể; quan trọng','adjective','[{"en":"There has been a significant increase in house prices this year.","vi":"Năm nay giá nhà đã tăng đáng kể."},{"en":"Moving abroad was the most significant decision of my life.","vi":"Chuyển ra nước ngoài là quyết định quan trọng nhất trong đời tôi."},{"en":"The new medicine made a significant difference to his health.","vi":"Loại thuốc mới đã tạo ra sự khác biệt đáng kể cho sức khỏe của anh ấy."}]','[{"phrase":"significant increase"},{"phrase":"significant difference"},{"phrase":"significant change"},{"phrase":"significant role"}]',NULL,'/sɪɡˈnɪfɪkənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(698,'ngsl-2-08',16,'drug','thuốc; ma túy','noun','[{"en":"This drug helps to reduce pain and fever.","vi":"Loại thuốc này giúp giảm đau và hạ sốt."},{"en":"Scientists are developing a new drug to treat the disease.","vi":"Các nhà khoa học đang phát triển một loại thuốc mới để điều trị căn bệnh này."},{"en":"Taking drugs can seriously damage your health.","vi":"Sử dụng ma túy có thể gây hại nghiêm trọng cho sức khỏe của bạn."}]','[{"phrase":"take drugs"},{"phrase":"drug use"},{"phrase":"prescription drug"},{"phrase":"new drug"}]',NULL,'/drʌɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dru/drug_/drug__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(699,'ngsl-2-08',17,'wall','bức tường','noun','[{"en":"We hung a big family photo on the living room wall.","vi":"Chúng tôi treo một tấm ảnh gia đình lớn trên tường phòng khách."},{"en":"The children painted the walls of their bedroom bright blue.","vi":"Bọn trẻ sơn tường phòng ngủ của chúng màu xanh dương sáng."},{"en":"An old stone wall runs around the garden.","vi":"Một bức tường đá cũ bao quanh khu vườn."}]','[{"phrase":"on the wall"},{"phrase":"paint a wall"},{"phrase":"stone wall"},{"phrase":"brick wall"}]',NULL,'/wɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wal/wall_/wall__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(700,'ngsl-2-08',18,'series','loạt; chuỗi; phim dài tập','noun','[{"en":"We watched the whole TV series in one weekend.","vi":"Chúng tôi đã xem hết cả bộ phim truyền hình dài tập trong một cuối tuần."},{"en":"The company had a series of problems last year.","vi":"Năm ngoái công ty gặp phải một loạt vấn đề."},{"en":"She is giving a series of talks on healthy eating.","vi":"Cô ấy đang có một loạt bài nói chuyện về ăn uống lành mạnh."}]','[{"phrase":"a series of"},{"phrase":"TV series"},{"phrase":"a series of events"}]','số ít và số nhiều giống nhau: series','/ˈsɪriːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serie/series__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(701,'ngsl-2-08',19,'direct','trực tiếp; thẳng; thẳng thắn','adjective','[{"en":"Is there a direct flight from Hanoi to London?","vi":"Có chuyến bay thẳng từ Hà Nội đến Luân Đôn không?"},{"en":"Keep the plant out of direct sunlight.","vi":"Hãy để cây tránh ánh nắng trực tiếp."},{"en":"I''d prefer a direct answer, not a long explanation.","vi":"Tôi muốn một câu trả lời thẳng thắn, chứ không phải một lời giải thích dài dòng."}]','[{"phrase":"direct flight"},{"phrase":"direct sunlight"},{"phrase":"direct contact"}]',NULL,'/dəˈrekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/direct__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(702,'ngsl-2-08',20,'success','sự thành công','noun','[{"en":"The party was a great success, and everyone had fun.","vi":"Bữa tiệc rất thành công và mọi người đều vui vẻ."},{"en":"Hard work is the key to success.","vi":"Chăm chỉ là chìa khóa dẫn đến thành công."},{"en":"We wish you every success in your new job.","vi":"Chúc bạn mọi thành công trong công việc mới."}]','[{"phrase":"great success"},{"phrase":"key to success"},{"phrase":"achieve success"}]',NULL,'/səkˈses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/success__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(703,'ngsl-2-08',21,'tomorrow','ngày mai','adverb','[{"en":"I have an important meeting at nine tomorrow morning.","vi":"Tôi có một cuộc họp quan trọng lúc chín giờ sáng mai."},{"en":"Can we talk about this tomorrow when I''m less tired?","vi":"Mai chúng ta nói về chuyện này khi tôi đỡ mệt hơn được không?"},{"en":"Tomorrow will be sunny, so let''s go to the park.","vi":"Ngày mai trời sẽ nắng, vậy chúng ta đi công viên nhé."}]','[{"phrase":"tomorrow morning"},{"phrase":"tomorrow night"},{"phrase":"see you tomorrow"},{"phrase":"the day after tomorrow"}]',NULL,'/təˈmɑːrəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tom/tomor/tomorrow__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(704,'ngsl-2-08',22,'director','giám đốc; đạo diễn','noun','[{"en":"She was promoted to sales director last year.","vi":"Năm ngoái cô ấy được thăng chức làm giám đốc kinh doanh."},{"en":"The director of the film won several awards.","vi":"Đạo diễn của bộ phim đã giành được nhiều giải thưởng."},{"en":"You should send your report to the finance director.","vi":"Bạn nên gửi báo cáo cho giám đốc tài chính."}]','[{"phrase":"managing director"},{"phrase":"film director"},{"phrase":"sales director"},{"phrase":"board of directors"}]',NULL,'/dəˈrektər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/director__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(705,'ngsl-2-08',23,'clearly','rõ ràng; rõ','adverb','[{"en":"Please speak clearly so everyone can hear you.","vi":"Vui lòng nói rõ ràng để mọi người đều có thể nghe thấy bạn."},{"en":"Without my glasses, I can''t see clearly.","vi":"Không có kính, tôi không nhìn rõ được."},{"en":"She was clearly upset about the news.","vi":"Rõ ràng là cô ấy buồn vì tin đó."}]','[{"phrase":"speak clearly"},{"phrase":"see clearly"},{"phrase":"think clearly"},{"phrase":"clearly visible"}]',NULL,'/ˈklɪrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cle/clear/clearly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(706,'ngsl-2-08',24,'lack','sự thiếu; thiếu','noun','[{"en":"Lack of sleep can make it hard to concentrate.","vi":"Thiếu ngủ có thể khiến bạn khó tập trung."},{"en":"The project failed because of a lack of money.","vi":"Dự án thất bại vì thiếu tiền."},{"en":"He lacks confidence when he speaks in public.","vi":"Anh ấy thiếu tự tin khi nói trước đám đông."}]','[{"phrase":"lack of sleep"},{"phrase":"lack of money"},{"phrase":"lack of time"},{"phrase":"lack confidence"}]','danh từ: lack of + N; động từ: lack + N (không có "of")','/læk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lac/lack_/lack__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(707,'ngsl-2-08',25,'review','bài đánh giá; sự xem xét lại','noun','[{"en":"I always read online reviews before I book a hotel.","vi":"Tôi luôn đọc các bài đánh giá trên mạng trước khi đặt khách sạn."},{"en":"The movie got great reviews from critics.","vi":"Bộ phim nhận được những lời đánh giá rất tốt từ giới phê bình."},{"en":"The company is doing a review of its safety rules.","vi":"Công ty đang xem xét lại các quy định an toàn của mình."}]','[{"phrase":"write a review"},{"phrase":"good reviews"},{"phrase":"under review"}]',NULL,'/rɪˈvjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revie/review__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(708,'ngsl-2-08',26,'depend','phụ thuộc; dựa vào; trông cậy','verb','[{"en":"Whether we go to the beach depends on the weather.","vi":"Chúng tôi có đi biển hay không còn phụ thuộc vào thời tiết."},{"en":"Many old people depend on their children for help.","vi":"Nhiều người già dựa vào con cái để được giúp đỡ."},{"en":"You can always depend on me when you need a friend.","vi":"Bạn luôn có thể trông cậy vào tôi khi cần một người bạn."}]','[{"phrase":"depend on"},{"phrase":"it depends"},{"phrase":"depend heavily on"}]','depend on/upon sb/sth','/dɪˈpend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depen/depend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(709,'ngsl-2-08',27,'race','cuộc đua; cuộc chạy đua','noun','[{"en":"She came second in the 100-meter race.","vi":"Cô ấy về nhì trong cuộc đua 100 mét."},{"en":"My brother won his first bike race last Sunday.","vi":"Anh trai tôi đã thắng cuộc đua xe đạp đầu tiên vào Chủ nhật tuần trước."},{"en":"We''re in a race against time to finish the project.","vi":"Chúng tôi đang chạy đua với thời gian để hoàn thành dự án."}]','[{"phrase":"win a race"},{"phrase":"lose a race"},{"phrase":"horse race"},{"phrase":"a race against time"}]',NULL,'/reɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rac/race_/race__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(710,'ngsl-2-08',28,'recognize','nhận ra; công nhận','verb','[{"en":"I didn''t recognize you with your new haircut!","vi":"Tôi đã không nhận ra bạn với kiểu tóc mới!"},{"en":"Would you recognize the man if you saw him again?","vi":"Bạn có nhận ra người đàn ông đó nếu gặp lại anh ta không?"},{"en":"Her hard work was finally recognized with an award.","vi":"Sự chăm chỉ của cô ấy cuối cùng đã được công nhận bằng một giải thưởng."}]','[{"phrase":"recognize someone"},{"phrase":"immediately recognize"},{"phrase":"widely recognized"},{"phrase":"recognize the importance"}]','Anh: recognise · Mỹ: recognize','/ˈrekəɡnaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recog/recognize__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(711,'ngsl-2-08',29,'window','cửa sổ','noun','[{"en":"Do you mind if I open the window for some air?","vi":"Bạn có phiền không nếu tôi mở cửa sổ cho thoáng khí?"},{"en":"Our hotel room had a window with a view of the sea.","vi":"Phòng khách sạn của chúng tôi có cửa sổ nhìn ra biển."},{"en":"The kids broke the kitchen window while playing soccer.","vi":"Bọn trẻ làm vỡ cửa sổ nhà bếp khi đang chơi bóng đá."}]','[{"phrase":"open the window"},{"phrase":"close the window"},{"phrase":"look out the window"},{"phrase":"window seat"}]',NULL,'/ˈwɪndəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/windo/window__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(712,'ngsl-2-09',1,'purpose','mục đích','noun','[{"en":"What is the purpose of your visit to Vietnam?","vi":"Mục đích chuyến đi Việt Nam của bạn là gì?"},{"en":"I don''t think he broke the glass on purpose.","vi":"Tôi không nghĩ anh ấy cố ý làm vỡ cái ly."},{"en":"The main purpose of this meeting is to plan next month''s budget.","vi":"Mục đích chính của cuộc họp này là lên kế hoạch ngân sách cho tháng sau."}]','[{"phrase":"main purpose"},{"phrase":"on purpose"},{"phrase":"serve a purpose"}]','on purpose = cố ý','/ˈpɜːrpəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/purpo/purpose__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(713,'ngsl-2-09',2,'department','phòng, ban; khoa','noun','[{"en":"She works in the sales department of a large company.","vi":"Cô ấy làm việc ở phòng kinh doanh của một công ty lớn."},{"en":"My brother teaches in the history department at the university.","vi":"Anh trai tôi giảng dạy ở khoa lịch sử của trường đại học."},{"en":"Please send your questions to the human resources department by Friday.","vi":"Vui lòng gửi câu hỏi của bạn đến phòng nhân sự trước thứ Sáu."}]','[{"phrase":"sales department"},{"phrase":"head of department"},{"phrase":"department store"}]',NULL,'/dɪˈpɑːrtmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depar/department__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(714,'ngsl-2-09',3,'gain','có được, giành được; tăng (cân)','verb','[{"en":"She gained a lot of experience from her first job.","vi":"Cô ấy đã có được nhiều kinh nghiệm từ công việc đầu tiên."},{"en":"I gained five kilos during the holidays.","vi":"Tôi đã tăng năm ký trong kỳ nghỉ lễ."},{"en":"The new manager slowly gained the trust of her team.","vi":"Người quản lý mới dần dần giành được sự tin tưởng của nhóm mình."}]','[{"phrase":"gain experience"},{"phrase":"gain weight"},{"phrase":"gain confidence"}]',NULL,'/ɡeɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gai/gain_/gain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(715,'ngsl-2-09',4,'tree','cây','noun','[{"en":"The children are sitting in the shade of a big tree.","vi":"Bọn trẻ đang ngồi dưới bóng một cái cây lớn."},{"en":"We planted an apple tree in our garden last spring.","vi":"Chúng tôi đã trồng một cây táo trong vườn vào mùa xuân năm ngoái."},{"en":"A strong wind knocked down several trees near the school.","vi":"Một cơn gió mạnh đã quật đổ vài cái cây gần trường."}]','[{"phrase":"plant a tree"},{"phrase":"apple tree"},{"phrase":"climb a tree"}]',NULL,'/triː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/tree_/tree__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(716,'ngsl-2-09',5,'college','trường cao đẳng; đại học','noun','[{"en":"My sister wants to go to college and study medicine.","vi":"Em gái tôi muốn vào đại học để học ngành y."},{"en":"He met his wife when they were both in college.","vi":"Anh ấy gặp vợ mình khi cả hai còn đang học đại học."},{"en":"She is taking an evening course at the local community college.","vi":"Cô ấy đang học một khóa buổi tối tại trường cao đẳng cộng đồng ở địa phương."}]','[{"phrase":"go to college"},{"phrase":"college student"},{"phrase":"college degree"}]',NULL,'/ˈkɑːlɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/college__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(717,'ngsl-2-09',6,'argue','cãi nhau; lập luận, cho rằng','verb','[{"en":"My parents sometimes argue about money, but they never shout.","vi":"Bố mẹ tôi thỉnh thoảng cãi nhau về tiền bạc, nhưng họ không bao giờ quát tháo."},{"en":"Stop arguing with your brother and finish your dinner.","vi":"Đừng cãi nhau với anh con nữa, ăn nốt bữa tối đi."},{"en":"Some people argue that working from home makes us more productive.","vi":"Một số người cho rằng làm việc tại nhà giúp chúng ta làm việc hiệu quả hơn."}]','[{"phrase":"argue with"},{"phrase":"argue about"},{"phrase":"argue that"}]',NULL,'/ˈɑːrɡjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arg/argue/argue__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(718,'ngsl-2-09',7,'board','tấm bảng; ban, hội đồng','noun','[{"en":"The teacher wrote the new words on the board.","vi":"Giáo viên viết những từ mới lên bảng."},{"en":"Check the notice board for the new exam schedule.","vi":"Hãy xem bảng thông báo để biết lịch thi mới."},{"en":"The board of directors will meet next week to discuss the plan.","vi":"Hội đồng quản trị sẽ họp vào tuần tới để thảo luận kế hoạch."}]','[{"phrase":"notice board"},{"phrase":"board of directors"},{"phrase":"on board"}]',NULL,'/bɔːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boa/board/board__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(719,'ngsl-2-09',8,'holiday','kỳ nghỉ; ngày lễ','noun','[{"en":"We spent our summer holiday at the beach with my grandparents.","vi":"Chúng tôi đã dành kỳ nghỉ hè ở biển cùng ông bà."},{"en":"Banks and schools are closed on public holidays.","vi":"Ngân hàng và trường học đóng cửa vào các ngày lễ."},{"en":"My boss is on holiday until next Monday.","vi":"Sếp tôi đi nghỉ đến thứ Hai tuần sau."}]','[{"phrase":"summer holiday"},{"phrase":"public holiday"},{"phrase":"on holiday"},{"phrase":"go on holiday"}]','Anh: holiday · Mỹ: vacation (kỳ nghỉ)','/ˈhɑːlədeɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/holid/holiday__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(720,'ngsl-2-09',9,'mark','vết, dấu; điểm (bài thi)','noun','[{"en":"The hot cup left a mark on the wooden table.","vi":"Cái cốc nóng để lại một vết trên bàn gỗ."},{"en":"She got top marks in every subject this year.","vi":"Năm nay cô ấy đạt điểm cao nhất ở tất cả các môn."},{"en":"Put a question mark at the end of the sentence.","vi":"Hãy đặt dấu chấm hỏi ở cuối câu."}]','[{"phrase":"question mark"},{"phrase":"top marks"},{"phrase":"leave a mark"}]',NULL,'/mɑːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/mark_/mark__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(721,'ngsl-2-09',10,'church','nhà thờ','noun','[{"en":"There is an old stone church in the center of the village.","vi":"Có một nhà thờ cổ bằng đá ở trung tâm ngôi làng."},{"en":"They got married in a small church near the sea.","vi":"Họ đã kết hôn tại một nhà thờ nhỏ gần biển."},{"en":"We could hear the church bells from our hotel room.","vi":"Chúng tôi có thể nghe thấy tiếng chuông nhà thờ từ phòng khách sạn."}]','[{"phrase":"church bells"},{"phrase":"go to church"},{"phrase":"local church"}]',NULL,'/tʃɜːrtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chu/churc/church__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(722,'ngsl-2-09',11,'machine','máy, máy móc','noun','[{"en":"Our washing machine is broken, so I washed my clothes by hand.","vi":"Máy giặt nhà tôi bị hỏng nên tôi phải giặt quần áo bằng tay."},{"en":"You can buy a drink from the machine in the hall.","vi":"Bạn có thể mua đồ uống từ cái máy ở hành lang."},{"en":"Many factory jobs are now done by machines.","vi":"Nhiều công việc trong nhà máy giờ đây được làm bằng máy móc."}]','[{"phrase":"washing machine"},{"phrase":"coffee machine"},{"phrase":"operate a machine"}]',NULL,'/məˈʃiːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mac/machi/machine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(723,'ngsl-2-09',12,'achieve','đạt được','verb','[{"en":"She worked hard to achieve her goal of becoming a doctor.","vi":"Cô ấy đã làm việc chăm chỉ để đạt được mục tiêu trở thành bác sĩ."},{"en":"Our team achieved great results this year.","vi":"Năm nay đội chúng tôi đã đạt được kết quả rất tốt."},{"en":"You can achieve a lot if you believe in yourself.","vi":"Bạn có thể đạt được nhiều điều nếu tin vào bản thân."}]','[{"phrase":"achieve a goal"},{"phrase":"achieve success"},{"phrase":"achieve results"}]',NULL,'/əˈtʃiːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ach/achie/achieve__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(724,'ngsl-2-09',13,'item','món đồ; mục, khoản','noun','[{"en":"Please check each item on the list before you leave.","vi":"Vui lòng kiểm tra từng mục trong danh sách trước khi rời đi."},{"en":"The store gives a discount if you buy more than three items.","vi":"Cửa hàng giảm giá nếu bạn mua hơn ba món."},{"en":"Many household items can be recycled instead of thrown away.","vi":"Nhiều đồ gia dụng có thể được tái chế thay vì vứt đi."}]','[{"phrase":"household items"},{"phrase":"item on the list"},{"phrase":"personal items"}]',NULL,'/ˈaɪtəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ite/item_/item__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(725,'ngsl-2-09',14,'prove','chứng minh; hóa ra (là)','verb','[{"en":"Can you prove that you were at home last night?","vi":"Bạn có thể chứng minh tối qua bạn ở nhà không?"},{"en":"Scientists have proved that the new medicine is safe.","vi":"Các nhà khoa học đã chứng minh rằng loại thuốc mới là an toàn."},{"en":"The exam proved easier than we expected.","vi":"Bài thi hóa ra dễ hơn chúng tôi nghĩ."}]','[{"phrase":"prove that"},{"phrase":"prove someone wrong"},{"phrase":"prove useful"}]','prove – proved – proved/proven','/pruːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prove/prove__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(726,'ngsl-2-09',15,'cent','xu (đồng cent)','noun','[{"en":"This pen costs ninety cents at the corner shop.","vi":"Cây bút này giá chín mươi xu ở cửa hàng đầu phố."},{"en":"She saved every cent she earned from her summer job.","vi":"Cô ấy để dành từng xu kiếm được từ công việc làm thêm mùa hè."},{"en":"Bus fares went up by fifty cents this month.","vi":"Tháng này giá vé xe buýt đã tăng năm mươi xu."}]','[{"phrase":"every cent"},{"phrase":"a few cents"},{"phrase":"per cent"}]','100 cent = 1 đô la hoặc 1 euro','/sent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/cent_/cent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(727,'ngsl-2-09',16,'season','mùa','noun','[{"en":"Summer is the busiest season for hotels near the beach.","vi":"Mùa hè là mùa đông khách nhất của các khách sạn gần biển."},{"en":"The rainy season in the south usually starts in May.","vi":"Mùa mưa ở miền Nam thường bắt đầu vào tháng Năm."},{"en":"Which season do you like best, spring or autumn?","vi":"Bạn thích mùa nào nhất, mùa xuân hay mùa thu?"}]','[{"phrase":"rainy season"},{"phrase":"dry season"},{"phrase":"holiday season"}]',NULL,'/ˈsiːzn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/seaso/season__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(728,'ngsl-2-09',17,'floor','sàn nhà; tầng','noun','[{"en":"The kids are playing with toys on the kitchen floor.","vi":"Bọn trẻ đang chơi đồ chơi trên sàn bếp."},{"en":"Our apartment is on the fifth floor of the building.","vi":"Căn hộ của chúng tôi ở tầng năm của tòa nhà."},{"en":"Be careful, the floor is still wet.","vi":"Cẩn thận, sàn nhà vẫn còn ướt."}]','[{"phrase":"on the floor"},{"phrase":"ground floor"},{"phrase":"wooden floor"}]','Anh: ground floor · Mỹ: first floor (tầng trệt)','/flɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/floor/floor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(729,'ngsl-2-09',18,'stuff','đồ, đồ đạc; thứ, việc','noun','[{"en":"You can leave your stuff in my car while we eat.","vi":"Bạn có thể để đồ đạc trong xe tôi trong lúc chúng ta ăn."},{"en":"I have a lot of stuff to do before the trip.","vi":"Tôi có rất nhiều việc phải làm trước chuyến đi."},{"en":"What is this sticky stuff on the table?","vi":"Cái thứ dính dính trên bàn này là gì vậy?"}]','[{"phrase":"a lot of stuff"},{"phrase":"pack your stuff"},{"phrase":"that kind of stuff"}]','không đếm được; thường dùng trong văn nói','/stʌf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/stuff/stuff__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(730,'ngsl-2-09',19,'wide','rộng; nhiều, đa dạng','adjective','[{"en":"The river is too wide to swim across.","vi":"Con sông quá rộng để bơi qua."},{"en":"The shop sells a wide range of fresh fruit.","vi":"Cửa hàng bán rất nhiều loại trái cây tươi."},{"en":"The road is only three meters wide.","vi":"Con đường chỉ rộng ba mét."}]','[{"phrase":"a wide range of"},{"phrase":"a wide variety of"},{"phrase":"wide open"}]',NULL,'/waɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wid/wide_/wide__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(731,'ngsl-2-09',20,'anyone','bất cứ ai; ai (đó)','pronoun','[{"en":"Is anyone else coming to dinner tonight?","vi":"Tối nay còn ai khác đến ăn tối không?"},{"en":"Please don''t tell anyone about the surprise party.","vi":"Làm ơn đừng kể với ai về bữa tiệc bất ngờ nhé."},{"en":"Anyone can join the club, even complete beginners.","vi":"Bất cứ ai cũng có thể tham gia câu lạc bộ, kể cả người mới hoàn toàn."}]','[{"phrase":"anyone else"},{"phrase":"if anyone"},{"phrase":"hardly anyone"}]',NULL,'/ˈeniwʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anyon/anyone__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(732,'ngsl-2-09',21,'method','phương pháp, cách','noun','[{"en":"Our teacher uses a fun method to teach grammar.","vi":"Giáo viên của chúng tôi dùng một phương pháp thú vị để dạy ngữ pháp."},{"en":"What payment methods does this shop accept?","vi":"Cửa hàng này chấp nhận những phương thức thanh toán nào?"},{"en":"Scientists tested a new method for cleaning water.","vi":"Các nhà khoa học đã thử nghiệm một phương pháp mới để làm sạch nước."}]','[{"phrase":"teaching method"},{"phrase":"payment method"},{"phrase":"new method"}]',NULL,'/ˈmeθəd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/metho/method__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(733,'ngsl-2-09',22,'analysis','sự phân tích; bản phân tích','noun','[{"en":"The doctor sent a blood sample to the lab for analysis.","vi":"Bác sĩ gửi mẫu máu đến phòng xét nghiệm để phân tích."},{"en":"Her analysis of the sales data was clear and useful.","vi":"Bản phân tích dữ liệu bán hàng của cô ấy rõ ràng và hữu ích."},{"en":"After careful analysis, we decided to change our plan.","vi":"Sau khi phân tích kỹ lưỡng, chúng tôi quyết định thay đổi kế hoạch."}]','[{"phrase":"careful analysis"},{"phrase":"data analysis"},{"phrase":"analysis of"}]','số nhiều: analyses','/əˈnæləsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analy/analysis__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(734,'ngsl-2-09',23,'election','cuộc bầu cử','noun','[{"en":"The next election will be held in two years.","vi":"Cuộc bầu cử tiếp theo sẽ được tổ chức sau hai năm nữa."},{"en":"Our class held an election to choose a new class leader.","vi":"Lớp chúng tôi đã tổ chức bầu cử để chọn lớp trưởng mới."},{"en":"Young people should vote in local elections.","vi":"Người trẻ nên đi bỏ phiếu trong các cuộc bầu cử địa phương."}]','[{"phrase":"hold an election"},{"phrase":"win an election"},{"phrase":"local election"}]',NULL,'/ɪˈlekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/election__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(735,'ngsl-2-09',24,'military','(thuộc) quân sự, quân đội','adjective','[{"en":"My grandfather did two years of military service.","vi":"Ông tôi đã đi nghĩa vụ quân sự hai năm."},{"en":"The old military base is now a public park.","vi":"Căn cứ quân sự cũ nay đã trở thành công viên công cộng."},{"en":"Military planes flew over the city during the celebration.","vi":"Máy bay quân sự bay qua thành phố trong buổi lễ kỷ niệm."}]','[{"phrase":"military service"},{"phrase":"military base"},{"phrase":"military training"}]',NULL,'/ˈmɪləteri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/milit/military__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(736,'ngsl-2-09',25,'hotel','khách sạn','noun','[{"en":"We stayed at a small hotel near the beach.","vi":"Chúng tôi ở một khách sạn nhỏ gần biển."},{"en":"I booked a hotel room for two nights.","vi":"Tôi đã đặt một phòng khách sạn cho hai đêm."},{"en":"Is breakfast included in the price of the hotel?","vi":"Giá khách sạn có bao gồm bữa sáng không?"}]','[{"phrase":"stay at a hotel"},{"phrase":"hotel room"},{"phrase":"book a hotel"}]',NULL,'/həʊˈtel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hot/hotel/hotel__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(737,'ngsl-2-09',26,'club','câu lạc bộ; hộp đêm','noun','[{"en":"My son joined the school chess club this year.","vi":"Năm nay con trai tôi đã tham gia câu lạc bộ cờ vua của trường."},{"en":"The book club meets every Thursday evening at the library.","vi":"Câu lạc bộ sách họp vào tối thứ Năm hằng tuần ở thư viện."},{"en":"After dinner, they went dancing at a club downtown.","vi":"Sau bữa tối, họ đi nhảy ở một hộp đêm trong trung tâm thành phố."}]','[{"phrase":"join a club"},{"phrase":"book club"},{"phrase":"football club"}]',NULL,'/klʌb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clu/club_/club__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(738,'ngsl-2-09',27,'below','dưới, bên dưới','preposition','[{"en":"The temperature dropped below zero last night.","vi":"Đêm qua nhiệt độ đã xuống dưới 0 độ."},{"en":"His grades were below average this term.","vi":"Học kỳ này điểm của cậu ấy dưới mức trung bình."},{"en":"Please write your name in the box below.","vi":"Vui lòng viết tên bạn vào ô bên dưới."}]','[{"phrase":"below zero"},{"phrase":"below average"},{"phrase":"see below"}]',NULL,'/bɪˈləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/below/below__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(739,'ngsl-2-09',28,'movie','bộ phim','noun','[{"en":"Do you want to watch a movie tonight?","vi":"Tối nay bạn có muốn xem phim không?"},{"en":"We went to the movies after dinner on Saturday.","vi":"Thứ Bảy chúng tôi đi xem phim sau bữa tối."},{"en":"That movie was so boring that I fell asleep.","vi":"Bộ phim đó chán đến mức tôi ngủ quên."}]','[{"phrase":"watch a movie"},{"phrase":"go to the movies"},{"phrase":"movie theater"}]','Mỹ: movie · Anh: film','/ˈmuːvi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mov/movie/movie__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(740,'ngsl-2-09',29,'doctor','bác sĩ','noun','[{"en":"You should see a doctor if the pain gets worse.","vi":"Bạn nên đi khám bác sĩ nếu cơn đau nặng hơn."},{"en":"My aunt works as a doctor at the city hospital.","vi":"Dì tôi làm bác sĩ ở bệnh viện thành phố."},{"en":"The doctor told me to rest for a few days.","vi":"Bác sĩ bảo tôi nghỉ ngơi vài ngày."}]','[{"phrase":"see a doctor"},{"phrase":"go to the doctor"},{"phrase":"family doctor"}]',NULL,'/ˈdɑːktər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doc/docto/doctor__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(741,'ngsl-2-10',1,'discussion','cuộc thảo luận; sự bàn bạc','noun','[{"en":"We had a long discussion about where to go on vacation.","vi":"Chúng tôi đã thảo luận rất lâu về việc đi nghỉ ở đâu."},{"en":"After much discussion, they finally agreed on a name for the baby.","vi":"Sau nhiều lần bàn bạc, cuối cùng họ cũng thống nhất được tên cho em bé."},{"en":"Our teacher started a class discussion about staying safe online.","vi":"Cô giáo bắt đầu một buổi thảo luận trên lớp về cách giữ an toàn trên mạng."}]','[{"phrase":"have a discussion"},{"phrase":"group discussion"},{"phrase":"under discussion"},{"phrase":"discussion about"}]',NULL,'/dɪˈskʌʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discu/discussion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(742,'ngsl-2-10',2,'sorry','xin lỗi; lấy làm tiếc; thấy thương','adjective','[{"en":"I''m sorry I forgot to call you last night.","vi":"Xin lỗi, tối qua tôi quên gọi cho bạn."},{"en":"We were sorry to hear that your grandfather is ill.","vi":"Chúng tôi rất tiếc khi nghe tin ông của bạn bị ốm."},{"en":"I felt sorry for the little boy who lost his dog.","vi":"Tôi thấy thương cậu bé bị lạc mất con chó."}]','[{"phrase":"say sorry"},{"phrase":"sorry to hear"},{"phrase":"feel sorry for"},{"phrase":"sorry about"}]','feel sorry for sb: thấy thương ai','/ˈsɑːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sor/sorry/sorry__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(743,'ngsl-2-10',3,'challenge','thử thách; thách thức','noun','[{"en":"Learning a new language is a big challenge for adults.","vi":"Học một ngôn ngữ mới là một thử thách lớn đối với người lớn."},{"en":"She enjoys the challenge of running her own small business.","vi":"Cô ấy thích thử thách của việc tự điều hành doanh nghiệp nhỏ của mình."},{"en":"Our company is facing many new challenges this year.","vi":"Năm nay công ty chúng tôi đang phải đối mặt với nhiều thách thức mới."}]','[{"phrase":"face a challenge"},{"phrase":"big challenge"},{"phrase":"meet a challenge"},{"phrase":"rise to the challenge"}]',NULL,'/ˈtʃælɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chall/challenge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(744,'ngsl-2-10',4,'nation','quốc gia; dân tộc','noun','[{"en":"The whole nation watched the final match on TV.","vi":"Cả nước đã theo dõi trận chung kết trên TV."},{"en":"Athletes from over fifty nations took part in the competition.","vi":"Vận động viên từ hơn năm mươi quốc gia đã tham gia cuộc thi đấu."},{"en":"It is one of the richest nations in the world.","vi":"Đó là một trong những quốc gia giàu nhất thế giới."}]','[{"phrase":"the whole nation"},{"phrase":"developing nations"},{"phrase":"wealthy nations"}]',NULL,'/ˈneɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natio/nation__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(745,'ngsl-2-10',5,'nearly','gần như; suýt','adverb','[{"en":"It''s nearly ten o''clock, so we should go to bed.","vi":"Gần mười giờ rồi, chúng ta nên đi ngủ thôi."},{"en":"I nearly missed the bus this morning.","vi":"Sáng nay tôi suýt lỡ chuyến xe buýt."},{"en":"Nearly all of my classmates passed the final exam.","vi":"Gần như tất cả bạn cùng lớp của tôi đều đậu kỳ thi cuối kỳ."}]','[{"phrase":"nearly all"},{"phrase":"nearly always"},{"phrase":"nearly finished"},{"phrase":"nearly every"}]',NULL,'/ˈnɪrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nea/nearl/nearly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(746,'ngsl-2-10',6,'statement','lời tuyên bố, thông báo; lời khai; bản sao kê','noun','[{"en":"The company made a statement about the delay on its website.","vi":"Công ty đã đưa ra thông báo về việc chậm trễ trên trang web của mình."},{"en":"The police took a statement from the driver after the accident.","vi":"Cảnh sát đã lấy lời khai của tài xế sau vụ tai nạn."},{"en":"Check your bank statement carefully at the end of each month.","vi":"Hãy kiểm tra kỹ bản sao kê ngân hàng vào cuối mỗi tháng."}]','[{"phrase":"make a statement"},{"phrase":"issue a statement"},{"phrase":"official statement"},{"phrase":"bank statement"}]',NULL,'/ˈsteɪtmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/state/statement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(747,'ngsl-2-10',7,'link','mối liên hệ; đường liên kết (link); tuyến nối','noun','[{"en":"Scientists have found a link between sleep and memory.","vi":"Các nhà khoa học đã tìm ra mối liên hệ giữa giấc ngủ và trí nhớ."},{"en":"Click the link in the email to reset your password.","vi":"Hãy bấm vào đường link trong email để đặt lại mật khẩu."},{"en":"The new bridge is an important link between the two towns.","vi":"Cây cầu mới là tuyến nối quan trọng giữa hai thị trấn."}]','[{"phrase":"link between"},{"phrase":"close link"},{"phrase":"click on a link"},{"phrase":"strong link"}]',NULL,'/lɪŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lin/link_/link__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(748,'ngsl-2-10',8,'despite','mặc dù; bất chấp','preposition','[{"en":"We still went for a walk despite the rain.","vi":"Chúng tôi vẫn đi dạo mặc dù trời mưa."},{"en":"Despite being tired, she stayed up to finish her homework.","vi":"Dù mệt, cô ấy vẫn thức để làm xong bài tập về nhà."},{"en":"The team lost the game despite playing very well.","vi":"Đội đã thua trận dù chơi rất hay."}]','[{"phrase":"despite the fact that"},{"phrase":"despite this"},{"phrase":"despite the rain"}]','despite + danh từ/V-ing (không dùng ''despite of'')','/dɪˈspaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/despi/despite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(749,'ngsl-2-10',9,'introduce','giới thiệu; đưa vào áp dụng','verb','[{"en":"Let me introduce you to my parents.","vi":"Để tôi giới thiệu bạn với bố mẹ tôi."},{"en":"She stood up and introduced herself to the class.","vi":"Cô ấy đứng dậy và tự giới thiệu với cả lớp."},{"en":"The school introduced a new rule about mobile phones last year.","vi":"Năm ngoái trường đã áp dụng một quy định mới về điện thoại di động."}]','[{"phrase":"introduce yourself"},{"phrase":"introduce someone to"},{"phrase":"introduce a new law"}]',NULL,'/ˌɪntrəˈduːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intro/introduce__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(750,'ngsl-2-10',10,'advantage','lợi thế; ưu điểm','noun','[{"en":"One advantage of living in the city is good public transportation.","vi":"Một ưu điểm của việc sống ở thành phố là giao thông công cộng tốt."},{"en":"Her height gives her a big advantage in basketball.","vi":"Chiều cao mang lại cho cô ấy lợi thế lớn trong môn bóng rổ."},{"en":"You should take advantage of the sunny weather and go outside.","vi":"Bạn nên tận dụng thời tiết nắng đẹp để ra ngoài."}]','[{"phrase":"take advantage of"},{"phrase":"big advantage"},{"phrase":"advantages and disadvantages"},{"phrase":"an advantage over"}]','take advantage of: tận dụng; lợi dụng','/ədˈvæntɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advan/advantage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(751,'ngsl-2-10',11,'ready','sẵn sàng; (đã) xong','adjective','[{"en":"Are you ready to order, or do you need more time?","vi":"Bạn đã sẵn sàng gọi món chưa, hay cần thêm thời gian?"},{"en":"Dinner will be ready in about ten minutes.","vi":"Khoảng mười phút nữa bữa tối sẽ xong."},{"en":"It took her an hour to get ready for the party.","vi":"Cô ấy mất một tiếng để chuẩn bị đi dự tiệc."}]','[{"phrase":"get ready"},{"phrase":"ready to go"},{"phrase":"ready for"}]',NULL,'/ˈredi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/ready/ready__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(752,'ngsl-2-10',12,'marry','cưới; kết hôn (với)','verb','[{"en":"My sister is going to marry her boyfriend next spring.","vi":"Chị tôi sẽ cưới bạn trai vào mùa xuân tới."},{"en":"They got married on a beach in the summer.","vi":"Họ kết hôn trên một bãi biển vào mùa hè."},{"en":"My grandparents married young and have been together for sixty years.","vi":"Ông bà tôi cưới nhau từ khi còn trẻ và đã bên nhau sáu mươi năm."}]','[{"phrase":"get married"},{"phrase":"marry someone"},{"phrase":"be married to"}]','marry sb (không dùng ''marry with sb'')','/ˈmæri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/marry/marry__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(753,'ngsl-2-10',13,'strike','đánh, đập vào; (sét) đánh; đình công','verb','[{"en":"The house was struck by lightning during the storm.","vi":"Ngôi nhà bị sét đánh trong cơn bão."},{"en":"The ball struck him on the head, but he was fine.","vi":"Quả bóng đập vào đầu anh ấy, nhưng anh ấy không sao."},{"en":"Workers at the factory are striking for better pay.","vi":"Công nhân ở nhà máy đang đình công đòi tăng lương."}]','[{"phrase":"go on strike"},{"phrase":"lightning strikes"},{"phrase":"strike a match"},{"phrase":"strike a balance"}]','strike – struck – struck','/straɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strik/strike__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(754,'ngsl-2-10',14,'mile','dặm (≈ 1,6 km)','noun','[{"en":"My office is about two miles from my house.","vi":"Văn phòng tôi cách nhà khoảng hai dặm."},{"en":"We drove for miles without seeing a single gas station.","vi":"Chúng tôi lái xe hàng dặm mà không thấy một trạm xăng nào."},{"en":"She runs five miles every morning before work.","vi":"Mỗi sáng cô ấy chạy năm dặm trước khi đi làm."}]','[{"phrase":"miles away"},{"phrase":"for miles"},{"phrase":"miles per hour"},{"phrase":"a mile from"}]','1 dặm ≈ 1,6 km','/maɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/mile_/mile__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(755,'ngsl-2-10',15,'seek','tìm kiếm; xin (lời khuyên, sự giúp đỡ)','verb','[{"en":"Many young people move to the city to seek work.","vi":"Nhiều người trẻ chuyển lên thành phố để tìm việc làm."},{"en":"You should seek advice from a doctor before starting the diet.","vi":"Bạn nên xin lời khuyên của bác sĩ trước khi bắt đầu chế độ ăn kiêng."},{"en":"The family sought help from their neighbors after the flood.","vi":"Sau trận lũ, gia đình ấy đã tìm đến sự giúp đỡ của hàng xóm."}]','[{"phrase":"seek help"},{"phrase":"seek advice"},{"phrase":"seek work"},{"phrase":"seek to do"}]','seek – sought – sought','/siːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seek_/seek__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(756,'ngsl-2-10',16,'ability','khả năng; năng lực','noun','[{"en":"She has the ability to explain difficult ideas simply.","vi":"Cô ấy có khả năng giải thích những ý tưởng khó một cách đơn giản."},{"en":"Students of all abilities are welcome to join the art club.","vi":"Học sinh ở mọi trình độ đều được chào đón tham gia câu lạc bộ mỹ thuật."},{"en":"Stress can affect your ability to sleep well.","vi":"Căng thẳng có thể ảnh hưởng đến khả năng ngủ ngon của bạn."}]','[{"phrase":"have the ability to"},{"phrase":"natural ability"},{"phrase":"of all abilities"}]',NULL,'/əˈbɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abi/abili/ability__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(757,'ngsl-2-10',17,'unit','đơn vị; bài (trong sách); khoa, bộ phận','noun','[{"en":"A meter is a common unit for measuring length.","vi":"Mét là một đơn vị thông dụng để đo chiều dài."},{"en":"We will finish Unit 5 of the textbook next week.","vi":"Tuần sau chúng ta sẽ học xong Bài 5 trong sách giáo khoa."},{"en":"My uncle works in the hospital''s intensive care unit.","vi":"Chú tôi làm việc ở khoa hồi sức tích cực của bệnh viện."}]','[{"phrase":"unit of measurement"},{"phrase":"intensive care unit"},{"phrase":"family unit"}]',NULL,'/ˈjuːnɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unit_/unit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(758,'ngsl-2-10',18,'card','thẻ; tấm thiếp; lá bài','noun','[{"en":"Can I pay by card, or do you only take cash?","vi":"Tôi trả bằng thẻ được không, hay ở đây chỉ nhận tiền mặt?"},{"en":"We sent my grandmother a birthday card with a family photo.","vi":"Chúng tôi gửi bà một tấm thiếp sinh nhật kèm ảnh gia đình."},{"en":"My friends and I often play cards on rainy evenings.","vi":"Tôi và bạn bè thường chơi bài vào những buổi tối mưa."}]','[{"phrase":"credit card"},{"phrase":"birthday card"},{"phrase":"play cards"},{"phrase":"pay by card"}]',NULL,'/kɑːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/card_/card__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(759,'ngsl-2-10',19,'hospital','bệnh viện','noun','[{"en":"My mother works as a nurse at the local hospital.","vi":"Mẹ tôi làm y tá ở bệnh viện địa phương."},{"en":"He had to stay in the hospital for three days.","vi":"Anh ấy phải nằm viện ba ngày."},{"en":"We visited my uncle in the hospital after his surgery.","vi":"Chúng tôi vào bệnh viện thăm chú tôi sau ca phẫu thuật."}]','[{"phrase":"in the hospital"},{"phrase":"go to the hospital"},{"phrase":"leave the hospital"},{"phrase":"hospital bed"}]','Anh: in hospital · Mỹ: in the hospital','/ˈhɑːspɪtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hos/hospi/hospital__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(760,'ngsl-2-10',20,'quickly','nhanh; nhanh chóng','adverb','[{"en":"She quickly finished her breakfast and ran to school.","vi":"Cô ấy nhanh chóng ăn xong bữa sáng rồi chạy đến trường."},{"en":"Young children usually learn new languages very quickly.","vi":"Trẻ nhỏ thường học ngôn ngữ mới rất nhanh."},{"en":"The news spread quickly through the small village.","vi":"Tin tức lan nhanh khắp ngôi làng nhỏ."}]','[{"phrase":"very quickly"},{"phrase":"act quickly"},{"phrase":"spread quickly"},{"phrase":"move quickly"}]',NULL,'/ˈkwɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quick/quickly__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(761,'ngsl-2-10',21,'interview','cuộc phỏng vấn','noun','[{"en":"I have a job interview at a bank tomorrow morning.","vi":"Sáng mai tôi có buổi phỏng vấn xin việc ở một ngân hàng."},{"en":"She wore her best suit to the interview.","vi":"Cô ấy mặc bộ vest đẹp nhất đến buổi phỏng vấn."},{"en":"The singer gave an interview to a local newspaper.","vi":"Ca sĩ đó đã trả lời phỏng vấn cho một tờ báo địa phương."}]','[{"phrase":"job interview"},{"phrase":"give an interview"},{"phrase":"have an interview"},{"phrase":"interview with"}]',NULL,'/ˈɪntərvjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interview__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(762,'ngsl-2-10',22,'agreement','sự đồng ý; thỏa thuận; hợp đồng','noun','[{"en":"After a long talk, we finally reached an agreement.","vi":"Sau một cuộc nói chuyện dài, cuối cùng chúng tôi cũng đạt được thỏa thuận."},{"en":"Please read the rental agreement carefully before you sign it.","vi":"Hãy đọc kỹ hợp đồng thuê nhà trước khi ký."},{"en":"Everyone in the room nodded in agreement.","vi":"Mọi người trong phòng đều gật đầu đồng ý."}]','[{"phrase":"reach an agreement"},{"phrase":"sign an agreement"},{"phrase":"in agreement"},{"phrase":"come to an agreement"}]',NULL,'/əˈɡriːmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agr/agree/agreement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(763,'ngsl-2-10',23,'release','phát hành, ra mắt; thả ra; thải ra','verb','[{"en":"The band will release their new album next month.","vi":"Ban nhạc sẽ phát hành album mới vào tháng tới."},{"en":"We released the bird after its wing had healed.","vi":"Chúng tôi thả con chim đi sau khi cánh của nó đã lành."},{"en":"The factory was fined for releasing dirty water into the river.","vi":"Nhà máy bị phạt vì xả nước bẩn ra sông."}]','[{"phrase":"release an album"},{"phrase":"release a statement"},{"phrase":"release a report"}]',NULL,'/rɪˈliːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relea/release__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(764,'ngsl-2-10',24,'tax','thuế','noun','[{"en":"Prices in this store do not include tax.","vi":"Giá trong cửa hàng này chưa bao gồm thuế."},{"en":"How much tax do you pay on your salary?","vi":"Lương của bạn phải đóng bao nhiêu tiền thuế?"},{"en":"Many people think the new tax on sugary drinks is a good idea.","vi":"Nhiều người cho rằng thuế mới đánh vào đồ uống có đường là một ý hay."}]','[{"phrase":"pay tax"},{"phrase":"income tax"},{"phrase":"tax on"},{"phrase":"raise taxes"}]',NULL,'/tæks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tax/tax__/tax__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(765,'ngsl-2-10',25,'solution','giải pháp; lời giải','noun','[{"en":"We need to find a solution to the parking problem.","vi":"Chúng ta cần tìm ra giải pháp cho vấn đề đỗ xe."},{"en":"The solutions to the exercises are at the back of the book.","vi":"Lời giải của các bài tập nằm ở cuối sách."},{"en":"There is no easy solution to this problem.","vi":"Không có giải pháp dễ dàng nào cho vấn đề này."}]','[{"phrase":"find a solution"},{"phrase":"solution to"},{"phrase":"simple solution"},{"phrase":"possible solution"}]',NULL,'/səˈluːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solut/solution__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(766,'ngsl-2-10',26,'capital','thủ đô; vốn; chữ viết hoa','noun','[{"en":"Hanoi is the capital and the second largest city of Vietnam.","vi":"Hà Nội là thủ đô và là thành phố lớn thứ hai của Việt Nam."},{"en":"They need more capital to open a second restaurant.","vi":"Họ cần thêm vốn để mở nhà hàng thứ hai."},{"en":"Always start a sentence with a capital letter.","vi":"Luôn bắt đầu câu bằng chữ viết hoa."}]','[{"phrase":"capital city"},{"phrase":"the capital of"},{"phrase":"capital letter"},{"phrase":"raise capital"}]',NULL,'/ˈkæpɪtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capit/capital__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(767,'ngsl-2-10',27,'popular','phổ biến; được ưa chuộng, được yêu thích','adjective','[{"en":"Soccer is the most popular sport in my country.","vi":"Bóng đá là môn thể thao phổ biến nhất ở nước tôi."},{"en":"This beach is very popular with tourists in the summer.","vi":"Bãi biển này rất được khách du lịch ưa chuộng vào mùa hè."},{"en":"He was one of the most popular teachers at our school.","vi":"Thầy ấy là một trong những giáo viên được yêu thích nhất trường tôi."}]','[{"phrase":"popular with"},{"phrase":"very popular"},{"phrase":"most popular"},{"phrase":"popular music"}]',NULL,'/ˈpɑːpjələr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pop/popul/popular__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(768,'ngsl-2-10',28,'specific','cụ thể; riêng, nhất định','adjective','[{"en":"Can you give me a specific example?","vi":"Bạn có thể cho tôi một ví dụ cụ thể không?"},{"en":"The doctor gave me specific instructions about taking the medicine.","vi":"Bác sĩ đã hướng dẫn cụ thể cho tôi về cách uống thuốc."},{"en":"Each room in the house is designed for a specific purpose.","vi":"Mỗi phòng trong ngôi nhà được thiết kế cho một mục đích riêng."}]','[{"phrase":"specific example"},{"phrase":"specific purpose"},{"phrase":"specific instructions"},{"phrase":"be more specific"}]',NULL,'/spəˈsɪfɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specific__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(769,'ngsl-2-10',29,'beautiful','đẹp; tuyệt vời','adjective','[{"en":"What a beautiful view of the mountains from here!","vi":"Từ đây nhìn ra núi, cảnh đẹp quá!"},{"en":"She wore a beautiful red dress to the wedding.","vi":"Cô ấy mặc một chiếc váy đỏ rất đẹp đến dự đám cưới."},{"en":"We had a beautiful day for our picnic by the lake.","vi":"Chúng tôi có một ngày đẹp trời cho buổi dã ngoại bên hồ."}]','[{"phrase":"beautiful view"},{"phrase":"beautiful day"},{"phrase":"absolutely beautiful"},{"phrase":"beautiful woman"}]',NULL,'/ˈbjuːtɪfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beaut/beautiful__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(770,'ngsl-2-11',1,'fear','nỗi sợ; sự lo sợ','noun','[{"en":"Many young children have a fear of the dark.","vi":"Nhiều trẻ nhỏ sợ bóng tối."},{"en":"She finally overcame her fear of flying last year.","vi":"Năm ngoái, cuối cùng cô ấy đã vượt qua nỗi sợ đi máy bay."},{"en":"There is growing fear that prices will rise again.","vi":"Ngày càng có nhiều lo sợ rằng giá cả sẽ lại tăng."}]','[{"phrase":"fear of"},{"phrase":"overcome a fear"},{"phrase":"live in fear"}]',NULL,'/fɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fea/fear_/fear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(771,'ngsl-2-11',2,'aim','mục tiêu; mục đích','noun','[{"en":"Our main aim is to finish the project by June.","vi":"Mục tiêu chính của chúng tôi là hoàn thành dự án trước tháng Sáu."},{"en":"The aim of this course is to improve your speaking skills.","vi":"Mục đích của khóa học này là cải thiện kỹ năng nói của bạn."},{"en":"She moved to the city with the aim of finding a better job.","vi":"Cô ấy chuyển lên thành phố với mục đích tìm một công việc tốt hơn."}]','[{"phrase":"main aim"},{"phrase":"the aim of"},{"phrase":"with the aim of"},{"phrase":"achieve an aim"}]','aim (v) = nhắm tới: aim to do something','/eɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aim/aim__/aim__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(772,'ngsl-2-11',3,'television','tivi; truyền hình','noun','[{"en":"We watched an old movie on television last night.","vi":"Tối qua chúng tôi xem một bộ phim cũ trên tivi."},{"en":"My grandparents bought a new television for the living room.","vi":"Ông bà tôi đã mua một chiếc tivi mới cho phòng khách."},{"en":"She has worked in television as a news reporter for years.","vi":"Cô ấy đã làm phóng viên tin tức trong ngành truyền hình nhiều năm."}]','[{"phrase":"watch television"},{"phrase":"on television"},{"phrase":"television show"},{"phrase":"turn on the television"}]',NULL,'/ˈtelɪvɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tel/telev/television__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(773,'ngsl-2-11',4,'serious','nghiêm trọng; nghiêm túc','adjective','[{"en":"Pollution is a serious problem in many big cities.","vi":"Ô nhiễm là một vấn đề nghiêm trọng ở nhiều thành phố lớn."},{"en":"He suffered a serious injury while playing football.","vi":"Anh ấy bị chấn thương nghiêm trọng khi chơi bóng đá."},{"en":"Are you serious about quitting your job next month?","vi":"Bạn nghiêm túc về chuyện nghỉ việc vào tháng sau à?"}]','[{"phrase":"serious problem"},{"phrase":"serious injury"},{"phrase":"be serious about"}]',NULL,'/ˈsɪriəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serio/serious__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(774,'ngsl-2-11',5,'target','mục tiêu; chỉ tiêu','noun','[{"en":"The company met its sales target two months early.","vi":"Công ty đã đạt chỉ tiêu doanh số sớm hai tháng."},{"en":"We set a target of saving 500 dollars every month.","vi":"Chúng tôi đặt mục tiêu tiết kiệm 500 đô la mỗi tháng."},{"en":"He threw the ball hard but missed the target completely.","vi":"Anh ấy ném bóng thật mạnh nhưng trượt mục tiêu hoàn toàn."}]','[{"phrase":"sales target"},{"phrase":"set a target"},{"phrase":"meet a target"},{"phrase":"hit the target"}]',NULL,'/ˈtɑːrɡɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tar/targe/target__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(775,'ngsl-2-11',6,'degree','độ; bằng (đại học); mức độ','noun','[{"en":"It was over 35 degrees outside this afternoon.","vi":"Chiều nay ngoài trời hơn 35 độ."},{"en":"She has a degree in computer science from a good university.","vi":"Cô ấy có bằng ngành khoa học máy tính của một trường đại học tốt."},{"en":"I agree with what you said to some degree.","vi":"Ở một mức độ nào đó, tôi đồng ý với những gì bạn nói."}]','[{"phrase":"a degree in"},{"phrase":"university degree"},{"phrase":"to some degree"},{"phrase":"degrees Celsius"}]',NULL,'/dɪˈɡriː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deg/degre/degree__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(776,'ngsl-2-11',7,'pull','kéo; nhổ','verb','[{"en":"You need to pull hard because the door sometimes gets stuck.","vi":"Bạn cần kéo mạnh vì cửa đôi khi bị kẹt."},{"en":"My little sister pulled my arm and asked me to play.","vi":"Em gái tôi kéo tay tôi và rủ tôi chơi."},{"en":"I had a tooth pulled at the dentist yesterday.","vi":"Hôm qua tôi đi nha sĩ nhổ một chiếc răng."}]','[{"phrase":"pull hard"},{"phrase":"pull out"},{"phrase":"pull over"}]',NULL,'/pʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pul/pull_/pull__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(777,'ngsl-2-11',8,'red','đỏ','adjective','[{"en":"She wore a long red dress to the party.","vi":"Cô ấy mặc một chiếc váy dài màu đỏ đến bữa tiệc."},{"en":"Stop the car when the traffic light turns red.","vi":"Hãy dừng xe khi đèn giao thông chuyển sang đỏ."},{"en":"His face went red when everyone started laughing at him.","vi":"Mặt anh ấy đỏ bừng khi mọi người bắt đầu cười anh ấy."}]','[{"phrase":"turn red"},{"phrase":"go red"},{"phrase":"bright red"},{"phrase":"red wine"}]',NULL,'/red/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/red/red__/red__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(778,'ngsl-2-11',9,'husband','chồng','noun','[{"en":"Her husband works as a teacher at a local school.","vi":"Chồng cô ấy làm giáo viên ở một trường học địa phương."},{"en":"My husband and I met at university.","vi":"Tôi và chồng quen nhau ở trường đại học."},{"en":"She called her husband to say she would be late.","vi":"Cô ấy gọi cho chồng để báo rằng mình sẽ về muộn."}]','[{"phrase":"husband and wife"},{"phrase":"my husband and I"},{"phrase":"ex-husband"}]',NULL,'/ˈhʌzbənd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hus/husba/husband__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(779,'ngsl-2-11',10,'access','quyền truy cập; sự tiếp cận','noun','[{"en":"Students have free access to the library''s online books.","vi":"Sinh viên được truy cập miễn phí vào sách trực tuyến của thư viện."},{"en":"Many villages still have no access to clean water.","vi":"Nhiều ngôi làng vẫn chưa được tiếp cận với nước sạch."},{"en":"You need a password to get access to the system.","vi":"Bạn cần mật khẩu để truy cập vào hệ thống."}]','[{"phrase":"access to"},{"phrase":"have access to"},{"phrase":"internet access"},{"phrase":"free access"}]','access to + danh từ; access (v) không có "to": access the website','/ˈækses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/acces/access__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(780,'ngsl-2-11',11,'movement','chuyển động; cử động; phong trào','noun','[{"en":"She noticed a slight movement in the bushes outside.","vi":"Cô ấy nhận thấy có chuyển động nhẹ trong bụi cây bên ngoài."},{"en":"The doctor told me to avoid sudden movements of my neck.","vi":"Bác sĩ dặn tôi tránh cử động cổ đột ngột."},{"en":"The movement to protect the environment is growing among young people.","vi":"Phong trào bảo vệ môi trường đang lớn mạnh trong giới trẻ."}]','[{"phrase":"slight movement"},{"phrase":"sudden movement"},{"phrase":"environmental movement"}]',NULL,'/ˈmuːvmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mov/movem/movement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(781,'ngsl-2-11',12,'treat','đối xử; chữa trị; đãi','verb','[{"en":"My boss always treats everyone with respect.","vi":"Sếp tôi luôn đối xử tôn trọng với mọi người."},{"en":"The hospital treated dozens of people after the accident.","vi":"Bệnh viện đã chữa trị cho hàng chục người sau vụ tai nạn."},{"en":"Let me treat you to dinner for your birthday.","vi":"Để tôi đãi bạn bữa tối nhân dịp sinh nhật bạn nhé."}]','[{"phrase":"treat someone with respect"},{"phrase":"treat a patient"},{"phrase":"treat someone to something"},{"phrase":"treat badly"}]',NULL,'/triːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/treat/treat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(782,'ngsl-2-11',13,'identify','nhận ra; xác định','verb','[{"en":"Can you identify the man in this photo?","vi":"Bạn có nhận ra người đàn ông trong bức ảnh này không?"},{"en":"Scientists have identified the cause of the disease.","vi":"Các nhà khoa học đã xác định được nguyên nhân gây ra căn bệnh."},{"en":"We need to identify the problem before we can fix it.","vi":"Chúng ta cần xác định vấn đề trước khi có thể khắc phục nó."}]','[{"phrase":"identify the problem"},{"phrase":"identify the cause"},{"phrase":"clearly identify"}]',NULL,'/aɪˈdentɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identify__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(783,'ngsl-2-11',14,'loss','sự mất; sự thua lỗ','noun','[{"en":"Weight loss is not always easy after the age of forty.","vi":"Sau tuổi bốn mươi, giảm cân không phải lúc nào cũng dễ."},{"en":"The storm caused a loss of power across the whole town.","vi":"Cơn bão khiến cả thị trấn bị mất điện."},{"en":"The company reported a loss of two million dollars last year.","vi":"Năm ngoái công ty báo lỗ hai triệu đô la."}]','[{"phrase":"weight loss"},{"phrase":"loss of power"},{"phrase":"heavy losses"},{"phrase":"report a loss"}]',NULL,'/lɔːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/los/loss_/loss__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(784,'ngsl-2-11',15,'modern','hiện đại','adjective','[{"en":"They live in a modern apartment near the city center.","vi":"Họ sống trong một căn hộ hiện đại gần trung tâm thành phố."},{"en":"Smartphones have become an important part of modern life.","vi":"Điện thoại thông minh đã trở thành một phần quan trọng của cuộc sống hiện đại."},{"en":"The hospital uses some of the most modern equipment in the country.","vi":"Bệnh viện sử dụng một số thiết bị hiện đại nhất cả nước."}]','[{"phrase":"modern life"},{"phrase":"modern technology"},{"phrase":"modern art"}]',NULL,'/ˈmɑːdərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/moder/modern__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(785,'ngsl-2-11',16,'pressure','áp lực; áp suất','noun','[{"en":"Many students feel a lot of pressure before exams.","vi":"Nhiều học sinh cảm thấy rất áp lực trước kỳ thi."},{"en":"She stays calm and works well under pressure.","vi":"Cô ấy giữ bình tĩnh và làm việc tốt dưới áp lực."},{"en":"Check the tire pressure before you go on a long drive.","vi":"Hãy kiểm tra áp suất lốp trước khi lái xe đường dài."}]','[{"phrase":"under pressure"},{"phrase":"blood pressure"},{"phrase":"put pressure on"},{"phrase":"tire pressure"}]',NULL,'/ˈpreʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/press/pressure__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(786,'ngsl-2-11',17,'bus','xe buýt','noun','[{"en":"I usually take the bus to work in the morning.","vi":"Buổi sáng tôi thường đi xe buýt đi làm."},{"en":"We missed the last bus and had to walk home.","vi":"Chúng tôi lỡ chuyến xe buýt cuối cùng và phải đi bộ về nhà."},{"en":"The bus stop is just across the street from my house.","vi":"Trạm xe buýt ở ngay bên kia đường, đối diện nhà tôi."}]','[{"phrase":"take the bus"},{"phrase":"bus stop"},{"phrase":"miss the bus"},{"phrase":"by bus"}]',NULL,'/bʌs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bus/bus__/bus__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(787,'ngsl-2-11',18,'treatment','sự điều trị; sự đối xử','noun','[{"en":"He is receiving treatment for a back injury.","vi":"Anh ấy đang được điều trị chấn thương lưng."},{"en":"The new treatment helped her feel better within a week.","vi":"Phương pháp điều trị mới giúp cô ấy thấy khỏe hơn trong vòng một tuần."},{"en":"All workers should receive equal treatment, whatever their age.","vi":"Mọi người lao động đều nên được đối xử bình đẳng, bất kể tuổi tác."}]','[{"phrase":"receive treatment"},{"phrase":"medical treatment"},{"phrase":"treatment for"},{"phrase":"equal treatment"}]',NULL,'/ˈtriːtmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/treat/treatment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(788,'ngsl-2-11',19,'conference','hội nghị; hội thảo','noun','[{"en":"She is going to a business conference in Tokyo next week.","vi":"Tuần sau cô ấy sẽ đi dự một hội nghị kinh doanh ở Tokyo."},{"en":"More than five hundred teachers attended the conference this year.","vi":"Năm nay có hơn năm trăm giáo viên tham dự hội thảo."},{"en":"My manager is on a conference call until three o''clock.","vi":"Quản lý của tôi đang trong một cuộc gọi hội nghị đến ba giờ."}]','[{"phrase":"attend a conference"},{"phrase":"business conference"},{"phrase":"conference call"},{"phrase":"press conference"}]',NULL,'/ˈkɑːnfərəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconference__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(789,'ngsl-2-11',20,'supply','nguồn cung; đồ dùng, vật tư','noun','[{"en":"The city has a limited supply of fresh water in summer.","vi":"Vào mùa hè, thành phố có nguồn cung nước sạch hạn chế."},{"en":"We need to buy more office supplies before Monday.","vi":"Chúng ta cần mua thêm văn phòng phẩm trước thứ Hai."},{"en":"Fresh vegetables are in short supply during the winter months.","vi":"Rau tươi khan hiếm trong những tháng mùa đông."}]','[{"phrase":"supply of"},{"phrase":"office supplies"},{"phrase":"in short supply"},{"phrase":"water supply"}]','supply (v) = cung cấp: supply somebody with something','/səˈplaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supply__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(790,'ngsl-2-11',21,'village','làng','noun','[{"en":"My grandmother still lives in a small village near the mountains.","vi":"Bà tôi vẫn sống ở một ngôi làng nhỏ gần núi."},{"en":"The whole village came to their wedding.","vi":"Cả làng đã đến dự đám cưới của họ."},{"en":"We stayed in a fishing village during our summer trip.","vi":"Chúng tôi ở lại một làng chài trong chuyến đi mùa hè."}]','[{"phrase":"small village"},{"phrase":"fishing village"},{"phrase":"the whole village"},{"phrase":"village school"}]',NULL,'/ˈvɪlɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vil/villa/village__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(791,'ngsl-2-11',22,'worth','đáng giá; đáng (làm gì)','adjective','[{"en":"This old painting is worth thousands of dollars.","vi":"Bức tranh cũ này trị giá hàng nghìn đô la."},{"en":"The museum is definitely worth a visit if you have time.","vi":"Nếu có thời gian, bảo tàng đó chắc chắn đáng để ghé thăm."},{"en":"It was a long drive, but the view was worth it.","vi":"Lái xe đường dài thật, nhưng cảnh đẹp rất đáng công."}]','[{"phrase":"worth it"},{"phrase":"worth a visit"},{"phrase":"well worth"}]','be worth + V-ing: This book is worth reading.','/wɜːrθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wor/worth/worth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(792,'ngsl-2-11',23,'natural','tự nhiên; thiên nhiên','adjective','[{"en":"This shampoo is made from natural ingredients.","vi":"Loại dầu gội này được làm từ các thành phần tự nhiên."},{"en":"It''s natural to feel nervous before a job interview.","vi":"Cảm thấy hồi hộp trước buổi phỏng vấn xin việc là điều tự nhiên."},{"en":"The island is famous for its natural beauty.","vi":"Hòn đảo nổi tiếng với vẻ đẹp thiên nhiên."}]','[{"phrase":"natural beauty"},{"phrase":"natural ingredients"},{"phrase":"natural resources"},{"phrase":"perfectly natural"}]',NULL,'/ˈnætʃrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natur/natural__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(793,'ngsl-2-11',24,'express','bày tỏ; diễn đạt; thể hiện','verb','[{"en":"He finds it hard to express his feelings.","vi":"Anh ấy thấy khó bày tỏ cảm xúc của mình."},{"en":"I''m not sure how to express this idea in English.","vi":"Tôi không chắc phải diễn đạt ý này bằng tiếng Anh như thế nào."},{"en":"Young children often express themselves through drawing and play.","vi":"Trẻ nhỏ thường thể hiện bản thân qua việc vẽ và vui chơi."}]','[{"phrase":"express feelings"},{"phrase":"express yourself"},{"phrase":"express an opinion"},{"phrase":"express concern"}]',NULL,'/ɪkˈspres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expre/express__us_6.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(794,'ngsl-2-11',25,'indicate','cho thấy; chỉ ra; báo hiệu','verb','[{"en":"Recent studies indicate that most people don''t get enough sleep.","vi":"Các nghiên cứu gần đây cho thấy hầu hết mọi người không ngủ đủ giấc."},{"en":"She indicated the exit with a wave of her hand.","vi":"Cô ấy vẫy tay chỉ về phía lối ra."},{"en":"The red light indicates that the battery is low.","vi":"Đèn đỏ báo hiệu pin sắp hết."}]','[{"phrase":"studies indicate"},{"phrase":"results indicate"},{"phrase":"clearly indicate"}]',NULL,'/ˈɪndɪkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indic/indicate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(795,'ngsl-2-11',26,'attend','tham dự; theo học','verb','[{"en":"Over two hundred guests attended the wedding.","vi":"Hơn hai trăm khách đã tham dự đám cưới."},{"en":"All employees must attend the safety meeting on Friday.","vi":"Tất cả nhân viên phải tham dự cuộc họp về an toàn vào thứ Sáu."},{"en":"Both of my kids attend the same elementary school.","vi":"Cả hai con tôi đều học cùng một trường tiểu học."}]','[{"phrase":"attend a meeting"},{"phrase":"attend school"},{"phrase":"attend a conference"},{"phrase":"regularly attend"}]','attend + sự kiện/nơi chốn (không có "to"): attend a meeting','/əˈtend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/atten/attend__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(796,'ngsl-2-11',27,'brother','anh trai; em trai','noun','[{"en":"My older brother taught me how to ride a bike.","vi":"Anh trai tôi đã dạy tôi đi xe đạp."},{"en":"Do you have any brothers or sisters?","vi":"Bạn có anh chị em nào không?"},{"en":"Her little brother is starting school next month.","vi":"Em trai cô ấy sẽ bắt đầu đi học vào tháng tới."}]','[{"phrase":"older brother"},{"phrase":"younger brother"},{"phrase":"little brother"},{"phrase":"brothers and sisters"}]','anh trai = older brother; em trai = younger/little brother','/ˈbrʌðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/broth/brother__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(797,'ngsl-2-11',28,'investment','sự đầu tư; khoản đầu tư','noun','[{"en":"Buying a house can be a good long-term investment.","vi":"Mua nhà có thể là một khoản đầu tư dài hạn tốt."},{"en":"The town needs more investment in schools and roads.","vi":"Thị trấn cần được đầu tư nhiều hơn vào trường học và đường sá."},{"en":"Learning a second language is an investment in your future.","vi":"Học thêm một ngoại ngữ là sự đầu tư cho tương lai của bạn."}]','[{"phrase":"good investment"},{"phrase":"long-term investment"},{"phrase":"investment in"},{"phrase":"foreign investment"}]',NULL,'/ɪnˈvestmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(798,'ngsl-2-11',29,'score','tỷ số; điểm số','noun','[{"en":"What was the final score of the game last night?","vi":"Tỷ số chung cuộc của trận đấu tối qua là bao nhiêu?"},{"en":"She got a perfect score on her math test.","vi":"Cô ấy đạt điểm tuyệt đối trong bài kiểm tra toán."},{"en":"You need a high score to get into that university.","vi":"Bạn cần điểm cao để vào được trường đại học đó."}]','[{"phrase":"final score"},{"phrase":"high score"},{"phrase":"perfect score"},{"phrase":"test score"}]',NULL,'/skɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sco/score/score__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(799,'ngsl-2-12',1,'organize','tổ chức; sắp xếp','verb','[{"en":"Our class is organizing a trip to the museum next month.","vi":"Lớp chúng tôi đang tổ chức một chuyến đi tham quan bảo tàng vào tháng tới."},{"en":"She spent Sunday afternoon organizing her books and papers.","vi":"Cô ấy dành buổi chiều Chủ nhật để sắp xếp sách vở và giấy tờ."},{"en":"Who organized the party for Dad''s birthday?","vi":"Ai đã tổ chức bữa tiệc sinh nhật cho bố vậy?"}]','[{"phrase":"organize a trip"},{"phrase":"organize a party"},{"phrase":"organize an event"}]','Anh: organise · Mỹ: organize','/ˈɔːrɡənaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/org/organ/organize__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(800,'ngsl-2-12',2,'trip','chuyến đi','noun','[{"en":"We''re planning a trip to the mountains this summer.","vi":"Chúng tôi đang lên kế hoạch cho một chuyến đi lên núi vào mùa hè này."},{"en":"How was your business trip to Singapore last week?","vi":"Chuyến công tác Singapore tuần trước của bạn thế nào?"},{"en":"The kids were tired after the long trip home.","vi":"Bọn trẻ mệt lả sau chuyến đi dài về nhà."}]','[{"phrase":"business trip"},{"phrase":"school trip"},{"phrase":"day trip"},{"phrase":"take a trip"}]',NULL,'/trɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trip_/trip__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(801,'ngsl-2-12',3,'beyond','vượt quá; ngoài; ở bên kia','preposition','[{"en":"The price of that house is beyond what we can afford.","vi":"Giá căn nhà đó vượt quá khả năng chi trả của chúng tôi."},{"en":"We''re sorry, but the delay was beyond our control.","vi":"Chúng tôi xin lỗi, nhưng sự chậm trễ này nằm ngoài tầm kiểm soát của chúng tôi."},{"en":"There is a small village just beyond the river.","vi":"Có một ngôi làng nhỏ ngay bên kia con sông."}]','[{"phrase":"beyond our control"},{"phrase":"go beyond"},{"phrase":"far beyond"},{"phrase":"beyond doubt"}]',NULL,'/bɪˈjɑːnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bey/beyon/beyond__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(802,'ngsl-2-12',4,'sleep','ngủ; giấc ngủ','verb','[{"en":"I couldn''t sleep last night because of the noise.","vi":"Tối qua tôi không ngủ được vì tiếng ồn."},{"en":"Babies usually sleep for most of the day.","vi":"Trẻ sơ sinh thường ngủ gần như cả ngày."},{"en":"You need a good night''s sleep before the exam.","vi":"Bạn cần ngủ một giấc thật ngon trước kỳ thi."}]','[{"phrase":"go to sleep"},{"phrase":"sleep well"},{"phrase":"get some sleep"}]','sleep – slept – slept','/sliːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sle/sleep/sleep__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(803,'ngsl-2-12',5,'fish','cá','noun','[{"en":"We had grilled fish and rice for dinner.","vi":"Bữa tối chúng tôi ăn cá nướng với cơm."},{"en":"My brother caught three small fish in the lake.","vi":"Anh trai tôi bắt được ba con cá nhỏ ở hồ."},{"en":"How many fish do you keep in that tank?","vi":"Bạn nuôi bao nhiêu con cá trong bể đó?"}]','[{"phrase":"catch fish"},{"phrase":"fresh fish"},{"phrase":"fish market"},{"phrase":"fried fish"}]','Số nhiều thường vẫn là fish','/fɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fis/fish_/fish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(804,'ngsl-2-12',6,'promise','hứa; lời hứa','verb','[{"en":"I promise I''ll call you as soon as I arrive.","vi":"Tôi hứa sẽ gọi cho bạn ngay khi tôi đến nơi."},{"en":"He promised his mother he would study harder.","vi":"Cậu ấy đã hứa với mẹ là sẽ học chăm hơn."},{"en":"She always keeps her promises, so you can trust her.","vi":"Cô ấy luôn giữ lời hứa, nên bạn có thể tin cô ấy."}]','[{"phrase":"keep a promise"},{"phrase":"break a promise"},{"phrase":"make a promise"}]',NULL,'/ˈprɑːmɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promi/promise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(805,'ngsl-2-12',7,'potential','tiềm năng; có thể xảy ra','adjective','[{"en":"The company is looking for potential customers in Asia.","vi":"Công ty đang tìm kiếm khách hàng tiềm năng ở châu Á."},{"en":"We need to think about potential problems before we start.","vi":"Chúng ta cần nghĩ đến những vấn đề có thể xảy ra trước khi bắt đầu."},{"en":"She sees him as a potential leader of the team.","vi":"Cô ấy xem anh ấy là một trưởng nhóm tiềm năng."}]','[{"phrase":"potential customers"},{"phrase":"potential problems"},{"phrase":"potential risks"},{"phrase":"potential benefits"}]','Cũng là danh từ: tiềm năng (reach your potential)','/pəˈtenʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/poten/potential__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(806,'ngsl-2-12',8,'energy','năng lượng; sức lực','noun','[{"en":"I don''t have the energy to cook tonight.","vi":"Tối nay tôi không còn sức để nấu ăn."},{"en":"Solar panels help us save energy and money.","vi":"Tấm pin mặt trời giúp chúng ta tiết kiệm năng lượng và tiền bạc."},{"en":"Kids seem to have so much energy in the morning.","vi":"Bọn trẻ dường như tràn đầy năng lượng vào buổi sáng."}]','[{"phrase":"save energy"},{"phrase":"solar energy"},{"phrase":"full of energy"},{"phrase":"energy costs"}]','Thường không đếm được','/ˈenərdʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ene/energ/energy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(807,'ngsl-2-12',9,'trouble','rắc rối; khó khăn; sự phiền hà','noun','[{"en":"I had trouble finding your house in the dark.","vi":"Tôi gặp khó khăn khi tìm nhà bạn trong bóng tối."},{"en":"He got into trouble for being late again.","vi":"Cậu ấy lại gặp rắc rối vì đi muộn."},{"en":"Thanks for your help, and sorry for all the trouble.","vi":"Cảm ơn bạn đã giúp, và xin lỗi vì đã làm phiền bạn nhiều."}]','[{"phrase":"have trouble"},{"phrase":"get into trouble"},{"phrase":"in trouble"}]','have trouble + V-ing','/ˈtrʌbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tro/troub/trouble__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(808,'ngsl-2-12',10,'relation','mối quan hệ; sự liên quan','noun','[{"en":"The company has good relations with its customers.","vi":"Công ty có mối quan hệ tốt với khách hàng."},{"en":"This question has no relation to today''s topic.","vi":"Câu hỏi này không liên quan gì đến chủ đề hôm nay."},{"en":"In relation to your request, we will reply next week.","vi":"Liên quan đến yêu cầu của bạn, chúng tôi sẽ trả lời vào tuần sau."}]','[{"phrase":"in relation to"},{"phrase":"good relations"},{"phrase":"public relations"}]',NULL,'/rɪˈleɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relation__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(809,'ngsl-2-12',11,'touch','chạm; sờ; làm cảm động','verb','[{"en":"Please don''t touch the paintings in the gallery.","vi":"Vui lòng không chạm vào các bức tranh trong phòng trưng bày."},{"en":"The baby reached out and touched my face.","vi":"Em bé với tay ra và sờ lên mặt tôi."},{"en":"We were deeply touched by their kind words.","vi":"Chúng tôi rất cảm động trước những lời tử tế của họ."}]','[{"phrase":"touch the screen"},{"phrase":"deeply touched"},{"phrase":"keep in touch"},{"phrase":"get in touch"}]',NULL,'/tʌtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/touch/touch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(810,'ngsl-2-12',12,'file','tập tin; hồ sơ','noun','[{"en":"Can you send me the file by email?","vi":"Bạn gửi cho tôi tập tin đó qua email được không?"},{"en":"I accidentally deleted an important file from my laptop.","vi":"Tôi lỡ tay xóa một tập tin quan trọng khỏi máy tính xách tay."},{"en":"The doctor checked my file before asking any questions.","vi":"Bác sĩ xem hồ sơ của tôi trước khi hỏi bất cứ điều gì."}]','[{"phrase":"open a file"},{"phrase":"save a file"},{"phrase":"delete a file"},{"phrase":"send a file"}]',NULL,'/faɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/file_/file__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(811,'ngsl-2-12',13,'middle','giữa; phần giữa','noun','[{"en":"There''s a big table in the middle of the room.","vi":"Có một cái bàn lớn ở giữa phòng."},{"en":"My phone rang in the middle of the meeting.","vi":"Điện thoại của tôi đổ chuông giữa cuộc họp."},{"en":"He often wakes up in the middle of the night.","vi":"Anh ấy thường thức giấc giữa đêm."}]','[{"phrase":"in the middle of"},{"phrase":"middle of the night"},{"phrase":"right in the middle"}]',NULL,'/ˈmɪdl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mid/middl/middle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(812,'ngsl-2-12',14,'bar','quán bar; thanh; thỏi','noun','[{"en":"Let''s meet at the bar near the station after work.","vi":"Tan làm mình gặp nhau ở quán bar gần nhà ga nhé."},{"en":"She ate a chocolate bar on the way to school.","vi":"Cô ấy ăn một thanh sô-cô-la trên đường đến trường."},{"en":"The windows on the ground floor have metal bars.","vi":"Các cửa sổ ở tầng trệt có thanh sắt chắn."}]','[{"phrase":"chocolate bar"},{"phrase":"a bar of soap"},{"phrase":"go to a bar"}]',NULL,'/bɑːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bar/bar__/bar__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(813,'ngsl-2-12',15,'suffer','chịu đựng; bị (bệnh, đau); bị ảnh hưởng xấu','verb','[{"en":"My grandfather suffers from back pain in winter.","vi":"Ông tôi bị đau lưng vào mùa đông."},{"en":"Many farmers suffered during the long, dry summer.","vi":"Nhiều nông dân đã chịu khổ trong suốt mùa hè khô hạn kéo dài."},{"en":"Her grades suffered because she worked too many hours.","vi":"Điểm số của cô ấy bị sa sút vì cô ấy đi làm quá nhiều giờ."}]','[{"phrase":"suffer from"},{"phrase":"suffer pain"},{"phrase":"suffer a loss"},{"phrase":"suffer damage"}]','suffer from + bệnh/vấn đề','/ˈsʌfər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suf/suffe/suffer__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(814,'ngsl-2-12',16,'strategy','chiến lược','noun','[{"en":"Our team needs a new strategy to win more customers.","vi":"Nhóm chúng ta cần một chiến lược mới để thu hút thêm khách hàng."},{"en":"What''s your strategy for learning new words?","vi":"Chiến lược học từ mới của bạn là gì?"},{"en":"The company changed its marketing strategy last year.","vi":"Năm ngoái công ty đã thay đổi chiến lược tiếp thị."}]','[{"phrase":"develop a strategy"},{"phrase":"marketing strategy"},{"phrase":"business strategy"},{"phrase":"strategy for"}]',NULL,'/ˈstrætədʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strat/strategy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(815,'ngsl-2-12',17,'deep','sâu; (giấc ngủ) say','adjective','[{"en":"Be careful, because the water is very deep here.","vi":"Cẩn thận nhé, vì nước ở đây rất sâu."},{"en":"She took a deep breath and opened the door.","vi":"Cô ấy hít một hơi thật sâu rồi mở cửa."},{"en":"The baby fell into a deep sleep after lunch.","vi":"Em bé ngủ say sau bữa trưa."}]','[{"phrase":"deep water"},{"phrase":"deep breath"},{"phrase":"deep sleep"}]',NULL,'/diːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dee/deep_/deep__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(816,'ngsl-2-12',18,'except','ngoại trừ; trừ','preposition','[{"en":"The shop is open every day except Sunday.","vi":"Cửa hàng mở cửa mọi ngày trừ Chủ nhật."},{"en":"Everyone came to the party except my brother.","vi":"Mọi người đều đến dự tiệc ngoại trừ anh trai tôi."},{"en":"I''ve finished all my homework except the math questions.","vi":"Tôi đã làm xong hết bài tập về nhà trừ mấy câu toán."}]','[{"phrase":"except for"},{"phrase":"except that"},{"phrase":"every day except"}]',NULL,'/ɪkˈsept/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excep/except__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(817,'ngsl-2-12',19,'clean','sạch; sạch sẽ','adjective','[{"en":"Put on a clean shirt before we go out.","vi":"Mặc áo sơ mi sạch vào trước khi chúng ta ra ngoài nhé."},{"en":"The hotel room was clean and quiet.","vi":"Phòng khách sạn sạch sẽ và yên tĩnh."},{"en":"Is this water clean enough to drink?","vi":"Nước này có đủ sạch để uống không?"}]','[{"phrase":"clean water"},{"phrase":"clean clothes"},{"phrase":"keep clean"},{"phrase":"clean air"}]','Cũng là động từ: làm sạch, dọn dẹp (clean the room)','/kliːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cle/clean/clean__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(818,'ngsl-2-12',20,'tend','có xu hướng; thường hay','verb','[{"en":"I tend to eat more when I''m stressed.","vi":"Tôi thường hay ăn nhiều hơn khi bị căng thẳng."},{"en":"Prices tend to rise before the holidays.","vi":"Giá cả có xu hướng tăng trước các kỳ nghỉ lễ."},{"en":"Older people tend to go to bed earlier.","vi":"Người lớn tuổi thường có xu hướng đi ngủ sớm hơn."}]','[{"phrase":"tend to do"},{"phrase":"tend to be"},{"phrase":"tend to agree"}]','tend to + động từ nguyên mẫu','/tend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tend_/tend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(819,'ngsl-2-12',21,'advance','sự tiến bộ; trước (in advance)','noun','[{"en":"Please book your tickets at least two weeks in advance.","vi":"Vui lòng đặt vé trước ít nhất hai tuần."},{"en":"Recent advances in medicine have helped people live longer.","vi":"Những tiến bộ gần đây trong y học đã giúp con người sống lâu hơn."},{"en":"Thanks in advance for your help with this project.","vi":"Cảm ơn trước vì bạn đã giúp đỡ trong dự án này."}]','[{"phrase":"in advance"},{"phrase":"thanks in advance"},{"phrase":"advances in technology"}]',NULL,'/ədˈvæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advan/advance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(820,'ngsl-2-12',22,'fill','làm đầy; đổ đầy; điền','verb','[{"en":"Can you fill this bottle with cold water?","vi":"Bạn đổ đầy nước lạnh vào chai này giúp mình được không?"},{"en":"Please fill in the form and sign at the bottom.","vi":"Vui lòng điền vào mẫu đơn và ký tên ở phía dưới."},{"en":"The room filled with laughter when the kids arrived.","vi":"Căn phòng tràn ngập tiếng cười khi bọn trẻ đến."}]','[{"phrase":"fill in a form"},{"phrase":"fill a glass"},{"phrase":"fill with"},{"phrase":"fill up"}]',NULL,'/fɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/fill_/fill__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(821,'ngsl-2-12',23,'star','ngôi sao; sao (xếp hạng)','noun','[{"en":"We lay on the grass and looked at the stars.","vi":"Chúng tôi nằm trên cỏ và ngắm sao."},{"en":"She became a movie star at the age of twenty.","vi":"Cô ấy trở thành ngôi sao điện ảnh năm hai mươi tuổi."},{"en":"The hotel has four stars and a lovely pool.","vi":"Khách sạn này đạt bốn sao và có một hồ bơi rất đẹp."}]','[{"phrase":"movie star"},{"phrase":"bright star"},{"phrase":"pop star"},{"phrase":"five-star hotel"}]',NULL,'/stɑːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/star_/star__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(822,'ngsl-2-12',24,'network','mạng lưới; mạng (máy tính)','noun','[{"en":"The city has a good network of bus routes.","vi":"Thành phố có mạng lưới tuyến xe buýt tốt."},{"en":"I can''t connect to the office network from home.","vi":"Tôi không kết nối được với mạng của văn phòng khi ở nhà."},{"en":"A strong network of contacts can help you find a job.","vi":"Một mạng lưới quan hệ vững chắc có thể giúp bạn tìm được việc làm."}]','[{"phrase":"social network"},{"phrase":"computer network"},{"phrase":"road network"},{"phrase":"network of"}]',NULL,'/ˈnetwɜːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/net/netwo/network__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(823,'ngsl-2-12',25,'generally','nói chung; thường','adverb','[{"en":"I generally go to bed before eleven.","vi":"Tôi thường đi ngủ trước mười một giờ."},{"en":"The weather here is generally warm in spring.","vi":"Thời tiết ở đây vào mùa xuân nhìn chung là ấm áp."},{"en":"Generally speaking, kids learn languages faster than adults.","vi":"Nói chung, trẻ em học ngoại ngữ nhanh hơn người lớn."}]','[{"phrase":"generally speaking"},{"phrase":"generally accepted"},{"phrase":"generally agree"}]',NULL,'/ˈdʒenrəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generally__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(824,'ngsl-2-12',26,'operation','ca phẫu thuật; hoạt động; sự vận hành','noun','[{"en":"My father had an operation on his knee last month.","vi":"Tháng trước bố tôi đã phẫu thuật đầu gối."},{"en":"The new factory will be in operation by next year.","vi":"Nhà máy mới sẽ đi vào hoạt động chậm nhất là vào năm sau."},{"en":"The company''s operations in Asia are growing quickly.","vi":"Hoạt động của công ty ở châu Á đang phát triển nhanh chóng."}]','[{"phrase":"have an operation"},{"phrase":"in operation"},{"phrase":"business operations"}]',NULL,'/ˌɑːpəˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/operation__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(825,'ngsl-2-12',27,'match','trận đấu; que diêm','noun','[{"en":"Did you watch the football match last night?","vi":"Tối qua bạn có xem trận bóng đá không?"},{"en":"Our team lost the match by just one point.","vi":"Đội chúng tôi thua trận chỉ cách biệt một điểm."},{"en":"He lit the candle with a match.","vi":"Anh ấy châm nến bằng một que diêm."}]','[{"phrase":"football match"},{"phrase":"win a match"},{"phrase":"lose a match"},{"phrase":"box of matches"}]','Động từ: hợp, khớp (Your shoes match your bag.)','/mætʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/match/match__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(826,'ngsl-2-12',28,'avoid','tránh; né tránh','verb','[{"en":"Try to avoid eating too much sugar.","vi":"Cố gắng tránh ăn quá nhiều đường."},{"en":"We left early to avoid the traffic.","vi":"Chúng tôi đi sớm để tránh kẹt xe."},{"en":"She''s been avoiding me since our argument last week.","vi":"Cô ấy cứ né tránh tôi kể từ lần cãi nhau tuần trước."}]','[{"phrase":"avoid traffic"},{"phrase":"avoid mistakes"},{"phrase":"avoid problems"}]','avoid + V-ing','/əˈvɔɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/avo/avoid/avoid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(827,'ngsl-2-12',29,'seat','chỗ ngồi; ghế','noun','[{"en":"Is this seat free, or is someone sitting here?","vi":"Chỗ này còn trống không, hay đã có người ngồi rồi?"},{"en":"Please take a seat, and the doctor will see you soon.","vi":"Mời bạn ngồi, bác sĩ sẽ khám cho bạn ngay."},{"en":"I always ask for a window seat on long flights.","vi":"Tôi luôn xin ghế cạnh cửa sổ trên những chuyến bay dài."}]','[{"phrase":"take a seat"},{"phrase":"window seat"},{"phrase":"front seat"},{"phrase":"book a seat"}]',NULL,'/siːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/seat_/seat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(828,'ngsl-2-13',1,'throw','ném; vứt','verb','[{"en":"Can you throw the ball to me, please?","vi":"Bạn ném quả bóng cho tôi được không?"},{"en":"Don''t throw away your old clothes; give them to charity instead.","vi":"Đừng vứt quần áo cũ đi; thay vào đó hãy đem cho từ thiện."},{"en":"He threw his bag on the bed and lay down.","vi":"Anh ấy quăng cái túi lên giường rồi nằm xuống."}]','[{"phrase":"throw a ball"},{"phrase":"throw away"},{"phrase":"throw a party"}]','throw – threw – thrown','/θrəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/throw/throw__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(829,'ngsl-2-13',2,'task','nhiệm vụ; công việc','noun','[{"en":"My first task this morning is to answer all my emails.","vi":"Việc đầu tiên của tôi sáng nay là trả lời hết email."},{"en":"Cleaning the kitchen after a big party is not an easy task.","vi":"Dọn dẹp nhà bếp sau một bữa tiệc lớn không phải là việc dễ dàng."},{"en":"The teacher gave each group a different task.","vi":"Giáo viên giao cho mỗi nhóm một nhiệm vụ khác nhau."}]','[{"phrase":"easy task"},{"phrase":"difficult task"},{"phrase":"complete a task"}]',NULL,'/tæsk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tas/task_/task__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(830,'ngsl-2-13',3,'normal','bình thường','adjective','[{"en":"It''s normal to feel nervous before an important exam.","vi":"Cảm thấy lo lắng trước một kỳ thi quan trọng là chuyện bình thường."},{"en":"The train is running later than normal today.","vi":"Hôm nay tàu chạy trễ hơn bình thường."},{"en":"Her blood pressure is normal, so there''s nothing to worry about.","vi":"Huyết áp của cô ấy bình thường nên không có gì phải lo."}]','[{"phrase":"perfectly normal"},{"phrase":"normal life"},{"phrase":"back to normal"}]',NULL,'/ˈnɔːrml/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norma/normal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(831,'ngsl-2-13',4,'goal','mục tiêu; bàn thắng','noun','[{"en":"My goal is to speak English fluently by next year.","vi":"Mục tiêu của tôi là nói tiếng Anh trôi chảy vào năm sau."},{"en":"Setting small goals can help you stay motivated.","vi":"Đặt ra những mục tiêu nhỏ có thể giúp bạn giữ được động lực."},{"en":"He scored the winning goal in the last minute.","vi":"Anh ấy ghi bàn thắng quyết định ở phút cuối."}]','[{"phrase":"set a goal"},{"phrase":"achieve a goal"},{"phrase":"score a goal"},{"phrase":"main goal"}]',NULL,'/ɡəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/goa/goal_/goal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(832,'ngsl-2-13',5,'associate','liên tưởng; liên quan đến','verb','[{"en":"I always associate the smell of rain with my childhood.","vi":"Tôi luôn liên tưởng mùi mưa với tuổi thơ của mình."},{"en":"Many people associate summer with long vacations at the beach.","vi":"Nhiều người liên tưởng mùa hè với những kỳ nghỉ dài ở biển."},{"en":"Eating too much sugar is associated with many health problems.","vi":"Ăn quá nhiều đường có liên quan đến nhiều vấn đề sức khỏe."}]','[{"phrase":"associate with"},{"phrase":"be associated with"},{"phrase":"closely associated"}]','associate A with B: liên tưởng A với B','/əˈsəʊsieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assoc/associate__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(833,'ngsl-2-13',6,'blue','xanh dương; buồn','adjective','[{"en":"She was wearing a blue dress at the party.","vi":"Cô ấy mặc một chiếc váy màu xanh dương tại bữa tiệc."},{"en":"The sky was clear and blue all afternoon.","vi":"Bầu trời trong xanh suốt cả buổi chiều."},{"en":"I''ve been feeling a bit blue since my best friend moved away.","vi":"Tôi cảm thấy hơi buồn từ khi bạn thân chuyển đi."}]','[{"phrase":"dark blue"},{"phrase":"light blue"},{"phrase":"blue sky"},{"phrase":"feel blue"}]','''xanh'' có thể là blue (xanh dương) hoặc green (xanh lá)','/bluː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blu/blue_/blue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(834,'ngsl-2-13',7,'positive','tích cực; chắc chắn','adjective','[{"en":"Try to stay positive, even when things are difficult.","vi":"Hãy cố gắng giữ thái độ tích cực, kể cả khi mọi việc khó khăn."},{"en":"The new manager has had a positive effect on the team.","vi":"Người quản lý mới đã có ảnh hưởng tích cực đến cả nhóm."},{"en":"Are you positive that you locked the front door?","vi":"Bạn có chắc chắn là đã khóa cửa trước không?"}]','[{"phrase":"stay positive"},{"phrase":"positive effect"},{"phrase":"positive attitude"},{"phrase":"positive feedback"}]',NULL,'/ˈpɑːzətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posit/positive__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(835,'ngsl-2-13',8,'option','lựa chọn','noun','[{"en":"Taking a taxi is probably the best option tonight.","vi":"Đi taxi có lẽ là lựa chọn tốt nhất tối nay."},{"en":"We have two options: stay home or go out for dinner.","vi":"Chúng ta có hai lựa chọn: ở nhà hoặc ra ngoài ăn tối."},{"en":"The restaurant offers several vegetarian options on its menu.","vi":"Nhà hàng có một số lựa chọn món chay trong thực đơn."}]','[{"phrase":"the best option"},{"phrase":"have no option"},{"phrase":"a good option"}]',NULL,'/ˈɑːpʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opt/optio/option__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(836,'ngsl-2-13',9,'box','hộp; thùng; ô','noun','[{"en":"She keeps all her old photos in a shoe box.","vi":"Cô ấy cất tất cả ảnh cũ trong một hộp giày."},{"en":"We packed our books into boxes before moving.","vi":"Chúng tôi đóng sách vào thùng trước khi chuyển nhà."},{"en":"Please check the box if you agree to the terms.","vi":"Vui lòng đánh dấu vào ô nếu bạn đồng ý với các điều khoản."}]','[{"phrase":"cardboard box"},{"phrase":"shoe box"},{"phrase":"check the box"},{"phrase":"a box of chocolates"}]',NULL,'/bɑːks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/box/box__/box__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(837,'ngsl-2-13',10,'huge','rất lớn; khổng lồ','adjective','[{"en":"They live in a huge house near the lake.","vi":"Họ sống trong một ngôi nhà rất lớn gần hồ."},{"en":"Winning the scholarship was a huge surprise for her.","vi":"Giành được học bổng là một bất ngờ rất lớn đối với cô ấy."},{"en":"The school concert was a huge success this year.","vi":"Buổi hòa nhạc của trường năm nay đã thành công lớn."}]','[{"phrase":"huge success"},{"phrase":"huge amount"},{"phrase":"huge difference"}]',NULL,'/hjuːdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hug/huge_/huge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(838,'ngsl-2-13',11,'message','tin nhắn; lời nhắn; thông điệp','noun','[{"en":"I''ll send you a message when I get home.","vi":"Tôi sẽ gửi tin nhắn cho bạn khi về đến nhà."},{"en":"She''s not in right now, but can I take a message?","vi":"Cô ấy hiện không có ở đây, tôi ghi lại lời nhắn cho bạn nhé?"},{"en":"The movie has a simple message about being kind to others.","vi":"Bộ phim mang một thông điệp đơn giản về việc tử tế với người khác."}]','[{"phrase":"send a message"},{"phrase":"leave a message"},{"phrase":"take a message"},{"phrase":"text message"}]',NULL,'/ˈmesɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mes/messa/message__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(839,'ngsl-2-13',12,'instance','ví dụ; trường hợp','noun','[{"en":"There are many ways to save money, for instance cooking at home.","vi":"Có nhiều cách để tiết kiệm tiền, chẳng hạn như nấu ăn ở nhà."},{"en":"In this instance, I think you should ask your manager first.","vi":"Trong trường hợp này, tôi nghĩ bạn nên hỏi quản lý trước."},{"en":"The report describes several instances of students cheating on tests.","vi":"Bản báo cáo mô tả một số trường hợp học sinh gian lận khi làm bài kiểm tra."}]','[{"phrase":"for instance"},{"phrase":"in this instance"},{"phrase":"in some instances"}]','for instance = for example (chẳng hạn)','/ˈɪnstəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insta/instance__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(840,'ngsl-2-13',13,'style','phong cách; kiểu','noun','[{"en":"The students really enjoy their teacher''s relaxed teaching style.","vi":"Học sinh rất thích phong cách giảng dạy thoải mái của giáo viên mình."},{"en":"The hotel was built in an old French style.","vi":"Khách sạn được xây theo phong cách Pháp cổ."},{"en":"This style of shoe is very popular with teenagers.","vi":"Kiểu giày này rất được giới trẻ ưa chuộng."}]','[{"phrase":"teaching style"},{"phrase":"writing style"},{"phrase":"in style"}]',NULL,'/staɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sty/style/style__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(841,'ngsl-2-13',14,'refer','nhắc đến; ám chỉ; tham khảo','verb','[{"en":"In his speech, he referred to his years living abroad.","vi":"Trong bài phát biểu, anh ấy đã nhắc đến những năm sống ở nước ngoài."},{"en":"Who were you referring to when you said that?","vi":"Bạn đang ám chỉ ai khi nói điều đó?"},{"en":"She referred to her notes several times during her presentation.","vi":"Cô ấy đã xem ghi chú của mình vài lần trong bài thuyết trình."}]','[{"phrase":"refer to"},{"phrase":"refer back to"},{"phrase":"be referred to as"}]','refer to sth · refer – referred – referred','/rɪˈfɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refer/refer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(842,'ngsl-2-13',15,'cold','lạnh; lạnh lùng','adjective','[{"en":"It''s really cold outside, so wear a warm coat.","vi":"Ngoài trời rất lạnh, nên hãy mặc áo khoác ấm."},{"en":"Would you like a cold drink after your long walk?","vi":"Bạn có muốn uống gì lạnh sau chuyến đi bộ dài không?"},{"en":"He gave me a cold look and walked away.","vi":"Anh ấy nhìn tôi lạnh lùng rồi bỏ đi."}]','[{"phrase":"cold weather"},{"phrase":"cold water"},{"phrase":"cold drink"},{"phrase":"catch a cold"}]','Danh từ: catch a cold (bị cảm lạnh)','/kəʊld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/cold_/cold__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(843,'ngsl-2-13',16,'push','đẩy; ấn; thúc ép','verb','[{"en":"You need to push the door hard because it sometimes sticks.","vi":"Bạn cần đẩy cửa mạnh vì đôi khi nó bị kẹt."},{"en":"Push this button to turn on the machine.","vi":"Ấn nút này để bật máy."},{"en":"My parents never pushed me to study medicine.","vi":"Bố mẹ tôi chưa bao giờ ép tôi học ngành y."}]','[{"phrase":"push the door"},{"phrase":"push a button"},{"phrase":"push hard"}]',NULL,'/pʊʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pus/push_/push__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(844,'ngsl-2-13',17,'quarter','một phần tư; mười lăm phút; quý','noun','[{"en":"About a quarter of the students walk to school.","vi":"Khoảng một phần tư số học sinh đi bộ đến trường."},{"en":"The meeting starts at a quarter past nine.","vi":"Cuộc họp bắt đầu lúc chín giờ mười lăm."},{"en":"The company''s sales rose sharply in the third quarter.","vi":"Doanh số của công ty đã tăng mạnh trong quý ba."}]','[{"phrase":"a quarter of"},{"phrase":"quarter past"},{"phrase":"quarter to"},{"phrase":"third quarter"}]',NULL,'/ˈkwɔːrtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quart/quarter__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(845,'ngsl-2-13',18,'assume','cho rằng; giả sử','verb','[{"en":"I assumed you already knew about the party.","vi":"Tôi cứ tưởng bạn đã biết về bữa tiệc rồi."},{"en":"Don''t assume that everyone agrees with you.","vi":"Đừng cho rằng mọi người đều đồng ý với bạn."},{"en":"Let''s assume the flight leaves on time and plan from there.","vi":"Hãy giả sử chuyến bay cất cánh đúng giờ và lên kế hoạch từ đó."}]','[{"phrase":"assume that"},{"phrase":"safe to assume"},{"phrase":"wrongly assume"}]',NULL,'/əˈsuːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assum/assume__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(846,'ngsl-2-13',19,'baby','em bé','noun','[{"en":"The baby is sleeping, so please be quiet.","vi":"Em bé đang ngủ, nên làm ơn giữ yên lặng."},{"en":"My sister is going to have a baby in March.","vi":"Chị gái tôi sắp sinh em bé vào tháng Ba."},{"en":"They bought some new baby clothes for their son.","vi":"Họ đã mua vài bộ quần áo em bé mới cho con trai."}]','[{"phrase":"have a baby"},{"phrase":"newborn baby"},{"phrase":"baby clothes"},{"phrase":"baby boy"}]',NULL,'/ˈbeɪbi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bab/baby_/baby__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(847,'ngsl-2-13',20,'successful','thành công; thành đạt','adjective','[{"en":"Her new restaurant has been very successful.","vi":"Nhà hàng mới của cô ấy rất thành công."},{"en":"He is a successful businessman with three companies.","vi":"Anh ấy là một doanh nhân thành đạt với ba công ty."},{"en":"Were you successful in finding a new apartment?","vi":"Bạn tìm căn hộ mới có thành công không?"}]','[{"phrase":"highly successful"},{"phrase":"successful career"},{"phrase":"successful businessman"},{"phrase":"successful in"}]',NULL,'/səkˈsesfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/successful__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(848,'ngsl-2-13',21,'sing','hát','verb','[{"en":"She sings in the school choir every Friday.","vi":"Cô ấy hát trong dàn hợp xướng của trường vào mỗi thứ Sáu."},{"en":"My grandfather used to sing old songs to us at bedtime.","vi":"Ông tôi thường hát những bài hát cũ cho chúng tôi nghe trước giờ đi ngủ."},{"en":"Have you ever sung in front of a large audience?","vi":"Bạn đã bao giờ hát trước đông khán giả chưa?"}]','[{"phrase":"sing a song"},{"phrase":"sing along"},{"phrase":"sing in a choir"}]','sing – sang – sung','/sɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/sing_/sing__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(849,'ngsl-2-13',22,'doubt','nghi ngờ; không tin là','verb','[{"en":"I doubt that he will arrive on time.","vi":"Tôi không tin là anh ấy sẽ đến đúng giờ."},{"en":"She never doubted her decision to study abroad.","vi":"Cô ấy chưa bao giờ nghi ngờ quyết định đi du học của mình."},{"en":"Nobody doubts that she is the best player on the team.","vi":"Không ai nghi ngờ rằng cô ấy là cầu thủ giỏi nhất đội."}]','[{"phrase":"doubt that"},{"phrase":"seriously doubt"},{"phrase":"never doubt"}]','Danh từ: no doubt (chắc chắn, không nghi ngờ gì)','/daʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dou/doubt/doubt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(850,'ngsl-2-13',23,'competition','cuộc thi; sự cạnh tranh','noun','[{"en":"My son won first prize in a drawing competition.","vi":"Con trai tôi đã giành giải nhất trong một cuộc thi vẽ."},{"en":"There is strong competition between the two coffee shops.","vi":"Có sự cạnh tranh gay gắt giữa hai quán cà phê."},{"en":"Are you going to enter the singing competition next month?","vi":"Bạn có định tham gia cuộc thi hát vào tháng sau không?"}]','[{"phrase":"win a competition"},{"phrase":"enter a competition"},{"phrase":"strong competition"}]',NULL,'/ˌkɑːmpəˈtɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/competition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(851,'ngsl-2-13',24,'theory','lý thuyết; giả thuyết','noun','[{"en":"In theory, the plan should work, but it''s still risky.","vi":"Về lý thuyết, kế hoạch này sẽ hiệu quả, nhưng nó vẫn có rủi ro."},{"en":"Students need to learn both theory and practice in this course.","vi":"Sinh viên cần học cả lý thuyết lẫn thực hành trong khóa học này."},{"en":"I have a theory about why our cat keeps running away.","vi":"Tôi có một giả thuyết về lý do con mèo nhà tôi cứ bỏ đi."}]','[{"phrase":"in theory"},{"phrase":"theory and practice"},{"phrase":"develop a theory"}]',NULL,'/ˈθiːəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theor/theory__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(852,'ngsl-2-13',25,'propose','đề xuất; cầu hôn','verb','[{"en":"She proposed a new plan to reduce costs.","vi":"Cô ấy đã đề xuất một kế hoạch mới để giảm chi phí."},{"en":"I propose that we meet again next Monday.","vi":"Tôi đề nghị chúng ta gặp lại nhau vào thứ Hai tới."},{"en":"He proposed to his girlfriend on the beach at sunset.","vi":"Anh ấy đã cầu hôn bạn gái trên bãi biển lúc hoàng hôn."}]','[{"phrase":"propose a plan"},{"phrase":"propose changes"},{"phrase":"propose to"}]',NULL,'/prəˈpəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/propose__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(853,'ngsl-2-13',26,'reference','sự nhắc đến; sự tham khảo; thư giới thiệu','noun','[{"en":"She made no reference to the problem in her email.","vi":"Cô ấy không hề nhắc đến vấn đề đó trong email."},{"en":"Please keep this guide in a safe place for future reference.","vi":"Hãy cất cuốn hướng dẫn này ở nơi an toàn để tham khảo sau này."},{"en":"My former manager agreed to write me a reference.","vi":"Quản lý cũ của tôi đã đồng ý viết thư giới thiệu cho tôi."}]','[{"phrase":"make reference to"},{"phrase":"for future reference"},{"phrase":"reference book"},{"phrase":"letter of reference"}]',NULL,'/ˈrefrəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refer/reference__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(854,'ngsl-2-13',27,'argument','cuộc cãi vã; lý lẽ','noun','[{"en":"My brother and I had an argument about the TV remote.","vi":"Tôi và anh trai đã cãi nhau vì cái điều khiển tivi."},{"en":"They got into a big argument over money.","vi":"Họ đã cãi nhau to vì chuyện tiền bạc."},{"en":"She made a strong argument for learning a second language.","vi":"Cô ấy đưa ra một lý lẽ thuyết phục cho việc học ngoại ngữ thứ hai."}]','[{"phrase":"have an argument"},{"phrase":"strong argument"},{"phrase":"argument about"},{"phrase":"argument for"}]',NULL,'/ˈɑːrɡjumənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arg/argum/argument__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(855,'ngsl-2-13',28,'adult','người lớn; người trưởng thành','noun','[{"en":"Children must be with an adult to enter the pool.","vi":"Trẻ em phải đi cùng người lớn mới được vào hồ bơi."},{"en":"Tickets cost ten dollars for adults and five for children.","vi":"Vé có giá mười đô la cho người lớn và năm đô cho trẻ em."},{"en":"Now that you''re an adult, you need to make your own decisions.","vi":"Giờ bạn đã là người trưởng thành, bạn cần tự đưa ra quyết định."}]','[{"phrase":"young adult"},{"phrase":"adult life"},{"phrase":"adults and children"}]',NULL,'/əˈdʌlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adu/adult/adult__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(856,'ngsl-2-13',29,'fly','bay; đi máy bay','verb','[{"en":"Birds fly south when the weather gets cold.","vi":"Chim bay về phương nam khi trời trở lạnh."},{"en":"We flew to Da Nang for our summer vacation.","vi":"Chúng tôi đã bay ra Đà Nẵng trong kỳ nghỉ hè."},{"en":"Is it cheaper to fly or take the train?","vi":"Đi máy bay hay đi tàu thì rẻ hơn?"}]','[{"phrase":"fly to"},{"phrase":"fly home"},{"phrase":"fly away"},{"phrase":"fly a kite"}]','fly – flew – flown','/flaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fly/fly__/fly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(857,'ngsl-2-14',1,'document','tài liệu; văn bản; giấy tờ','noun','[{"en":"Please read the document carefully before you sign it.","vi":"Vui lòng đọc kỹ tài liệu trước khi ký."},{"en":"I saved the document on my laptop last night.","vi":"Tối qua tôi đã lưu văn bản đó trong máy tính xách tay."},{"en":"You will need to bring some important documents to the bank.","vi":"Bạn sẽ cần mang theo một số giấy tờ quan trọng đến ngân hàng."}]','[{"phrase":"sign a document"},{"phrase":"important document"},{"phrase":"legal document"},{"phrase":"official document"}]',NULL,'/ˈdɑːkjumənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doc/docum/document__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(858,'ngsl-2-14',2,'pattern','mẫu; hoa văn; quy luật','noun','[{"en":"She bought a dress with a pattern of small flowers.","vi":"Cô ấy mua một chiếc váy có hoa văn những bông hoa nhỏ."},{"en":"The doctor noticed a clear pattern in his sleeping habits.","vi":"Bác sĩ nhận thấy một quy luật rõ ràng trong thói quen ngủ của anh ấy."},{"en":"Children learn to speak by hearing the same sentence patterns many times.","vi":"Trẻ em học nói bằng cách nghe những mẫu câu giống nhau nhiều lần."}]','[{"phrase":"a clear pattern"},{"phrase":"follow a pattern"},{"phrase":"weather patterns"}]',NULL,'/ˈpætərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pat/patte/pattern__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(859,'ngsl-2-14',3,'application','đơn xin; ứng dụng','noun','[{"en":"I sent my job application to the company last week.","vi":"Tuần trước tôi đã gửi đơn xin việc đến công ty đó."},{"en":"Your visa application must be completed in English.","vi":"Đơn xin thị thực của bạn phải được điền bằng tiếng Anh."},{"en":"This application helps you track how much water you drink.","vi":"Ứng dụng này giúp bạn theo dõi lượng nước mình uống."}]','[{"phrase":"job application"},{"phrase":"application form"},{"phrase":"submit an application"},{"phrase":"mobile application"}]',NULL,'/ˌæplɪˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appli/application__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(860,'ngsl-2-14',4,'hot','nóng; cay','adjective','[{"en":"It''s too hot to go outside this afternoon.","vi":"Chiều nay trời quá nóng để ra ngoài."},{"en":"Be careful, the soup is still very hot.","vi":"Cẩn thận nhé, súp vẫn còn rất nóng."},{"en":"This curry is too hot for my children.","vi":"Món cà ri này quá cay đối với các con tôi."}]','[{"phrase":"hot weather"},{"phrase":"hot water"},{"phrase":"a hot day"}]',NULL,'/hɑːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hot/hot__/hot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(861,'ngsl-2-14',5,'obviously','rõ ràng; hiển nhiên','adverb','[{"en":"She was obviously upset when she heard the news.","vi":"Rõ ràng cô ấy rất buồn khi nghe tin đó."},{"en":"Obviously, you should never drive after drinking alcohol.","vi":"Hiển nhiên là bạn không bao giờ nên lái xe sau khi uống rượu."},{"en":"He was obviously tired after the long flight.","vi":"Rõ ràng anh ấy đã mệt sau chuyến bay dài."}]','[{"phrase":"obviously upset"},{"phrase":"quite obviously"},{"phrase":"obviously wrong"}]',NULL,'/ˈɑːbviəsli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obv/obvio/obviously__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(862,'ngsl-2-14',6,'unclear','không rõ; chưa rõ ràng','adjective','[{"en":"It is still unclear what caused the fire.","vi":"Vẫn chưa rõ nguyên nhân gây ra vụ cháy."},{"en":"The teacher''s instructions were unclear, so many students got confused.","vi":"Hướng dẫn của giáo viên không rõ ràng nên nhiều học sinh bị bối rối."},{"en":"I''m unclear about what time the meeting starts.","vi":"Tôi chưa rõ cuộc họp bắt đầu lúc mấy giờ."}]','[{"phrase":"it is unclear"},{"phrase":"still unclear"},{"phrase":"remain unclear"}]',NULL,'/ˌʌnˈklɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unc/uncle/unclear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(863,'ngsl-2-14',7,'bill','hóa đơn; tờ tiền','noun','[{"en":"Excuse me, could we have the bill, please?","vi":"Xin lỗi, cho chúng tôi xin hóa đơn được không?"},{"en":"We need to pay the electricity bill before Friday.","vi":"Chúng ta cần trả hóa đơn tiền điện trước thứ Sáu."},{"en":"He paid for lunch with a twenty-dollar bill.","vi":"Anh ấy trả tiền bữa trưa bằng một tờ hai mươi đô la."}]','[{"phrase":"pay the bill"},{"phrase":"electricity bill"},{"phrase":"phone bill"},{"phrase":"split the bill"}]',NULL,'/bɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bil/bill_/bill__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(864,'ngsl-2-14',8,'search','tìm kiếm; lục soát','verb','[{"en":"I searched everywhere for my keys but couldn''t find them.","vi":"Tôi đã tìm chìa khóa khắp nơi nhưng không thấy."},{"en":"You can search the internet for cheap flights.","vi":"Bạn có thể tìm vé máy bay giá rẻ trên mạng."},{"en":"Security guards searched our bags at the entrance.","vi":"Nhân viên bảo vệ đã lục soát túi của chúng tôi ở lối vào."}]','[{"phrase":"search for"},{"phrase":"search the internet"},{"phrase":"search everywhere"}]','search for sth: tìm cái gì; search a place/bag: lục soát','/sɜːrtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/searc/search__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(865,'ngsl-2-14',9,'separate','riêng; riêng biệt; tách biệt','adjective','[{"en":"When we were kids, my brother and I had separate bedrooms.","vi":"Hồi nhỏ, tôi và anh trai có phòng ngủ riêng."},{"en":"Please keep raw meat separate from other food.","vi":"Hãy để thịt sống tách biệt với các thực phẩm khác."},{"en":"Write each answer on a separate sheet of paper.","vi":"Hãy viết mỗi câu trả lời trên một tờ giấy riêng."}]','[{"phrase":"separate room"},{"phrase":"keep separate"},{"phrase":"a separate sheet"},{"phrase":"separate from"}]','separate (v): tách ra, chia ra','/ˈseprət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sep/separ/separate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(866,'ngsl-2-14',10,'central','trung tâm; chính, chủ yếu','adjective','[{"en":"We found a small hotel in a central location.","vi":"Chúng tôi tìm được một khách sạn nhỏ ở vị trí trung tâm."},{"en":"Family plays a central role in her life.","vi":"Gia đình giữ vai trò chính trong cuộc sống của cô ấy."},{"en":"The central station is only a ten-minute walk away.","vi":"Nhà ga trung tâm chỉ cách đây mười phút đi bộ."}]','[{"phrase":"central role"},{"phrase":"central location"},{"phrase":"central part"}]',NULL,'/ˈsentrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/centr/central__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(867,'ngsl-2-14',11,'career','sự nghiệp; nghề nghiệp','noun','[{"en":"She started her career as a nurse in a small hospital.","vi":"Cô ấy bắt đầu sự nghiệp là một y tá tại một bệnh viện nhỏ."},{"en":"What career do you want after you finish university?","vi":"Bạn muốn theo nghề gì sau khi học xong đại học?"},{"en":"He changed careers at forty and became a teacher.","vi":"Anh ấy đổi nghề ở tuổi bốn mươi và trở thành giáo viên."}]','[{"phrase":"start a career"},{"phrase":"change careers"},{"phrase":"career choice"},{"phrase":"a successful career"}]',NULL,'/kəˈrɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/caree/career__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(868,'ngsl-2-14',12,'anyway','dù sao; dù sao thì','adverb','[{"en":"It was raining, but we went for a walk anyway.","vi":"Trời mưa nhưng dù sao chúng tôi vẫn đi dạo."},{"en":"Anyway, I should go now because it''s getting late.","vi":"Dù sao thì tôi cũng nên đi bây giờ vì đã muộn rồi."},{"en":"I didn''t really want that job anyway.","vi":"Dù sao thì tôi cũng không thực sự muốn công việc đó."}]','[{"phrase":"thanks anyway"},{"phrase":"but anyway"}]',NULL,'/ˈeniweɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anywa/anyway__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(869,'ngsl-2-14',13,'speech','bài phát biểu; khả năng nói','noun','[{"en":"The manager gave a short speech at the party.","vi":"Người quản lý đã có một bài phát biểu ngắn tại bữa tiệc."},{"en":"I get nervous whenever I have to make a speech.","vi":"Tôi hay lo lắng mỗi khi phải phát biểu."},{"en":"Young children develop speech at very different ages.","vi":"Trẻ nhỏ phát triển khả năng nói ở những độ tuổi rất khác nhau."}]','[{"phrase":"give a speech"},{"phrase":"make a speech"},{"phrase":"short speech"},{"phrase":"wedding speech"}]',NULL,'/spiːtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speec/speech__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(870,'ngsl-2-14',14,'dog','con chó','noun','[{"en":"We take our dog for a walk every evening.","vi":"Chúng tôi dắt chó đi dạo mỗi tối."},{"en":"My neighbor''s dog barks loudly whenever someone walks past.","vi":"Con chó nhà hàng xóm sủa ầm lên mỗi khi có người đi ngang qua."},{"en":"Do you think dogs make better pets than cats?","vi":"Bạn có nghĩ chó là thú cưng tốt hơn mèo không?"}]','[{"phrase":"walk the dog"},{"phrase":"feed the dog"},{"phrase":"dog food"}]',NULL,'/dɔːɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dog/dog__/dog__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(871,'ngsl-2-14',15,'officer','sĩ quan; cảnh sát; nhân viên','noun','[{"en":"A police officer helped us find the way to the station.","vi":"Một cảnh sát đã giúp chúng tôi tìm đường đến nhà ga."},{"en":"She works as a customs officer at the airport.","vi":"Cô ấy làm nhân viên hải quan tại sân bay."},{"en":"Her father was an officer in the navy for twenty years.","vi":"Bố cô ấy làm sĩ quan hải quân suốt hai mươi năm."}]','[{"phrase":"police officer"},{"phrase":"customs officer"},{"phrase":"army officer"},{"phrase":"senior officer"}]',NULL,'/ˈɑːfɪsər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offic/officer__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(872,'ngsl-2-14',16,'throughout','suốt; khắp','preposition','[{"en":"It rained throughout the day, so we stayed inside.","vi":"Trời mưa suốt cả ngày nên chúng tôi ở trong nhà."},{"en":"The restaurant is famous throughout the country.","vi":"Nhà hàng này nổi tiếng khắp cả nước."},{"en":"She stayed calm and smiled throughout the whole interview.","vi":"Cô ấy giữ bình tĩnh và mỉm cười suốt buổi phỏng vấn."}]','[{"phrase":"throughout the day"},{"phrase":"throughout the year"},{"phrase":"throughout the world"},{"phrase":"throughout the country"}]',NULL,'/θruːˈaʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/throu/throughout__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(873,'ngsl-2-14',17,'oil','dầu','noun','[{"en":"Heat a little oil in the pan before adding the onions.","vi":"Đun nóng một ít dầu trong chảo trước khi cho hành vào."},{"en":"The mechanic said my car needs an oil change.","vi":"Thợ sửa xe nói xe của tôi cần thay dầu."},{"en":"Olive oil is a healthy choice for salads.","vi":"Dầu ô liu là lựa chọn tốt cho sức khỏe khi làm salad."}]','[{"phrase":"olive oil"},{"phrase":"cooking oil"},{"phrase":"oil change"},{"phrase":"oil price"}]','không đếm được','/ɔɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oil/oil__/oil__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(874,'ngsl-2-14',18,'dress','váy; váy liền','noun','[{"en":"She wore a long blue dress to the wedding.","vi":"Cô ấy mặc một chiếc váy dài màu xanh dương đến dự đám cưới."},{"en":"This dress is too small, so I need a bigger size.","vi":"Chiếc váy này chật quá nên tôi cần cỡ lớn hơn."},{"en":"My daughter wants a new dress for her birthday party.","vi":"Con gái tôi muốn có một chiếc váy mới cho tiệc sinh nhật."}]','[{"phrase":"wear a dress"},{"phrase":"wedding dress"},{"phrase":"long dress"},{"phrase":"summer dress"}]','dress (v): mặc quần áo; get dressed: mặc đồ','/dres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dre/dress/dress__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(875,'ngsl-2-14',19,'profit','lợi nhuận; tiền lãi','noun','[{"en":"The small shop made a good profit last year.","vi":"Năm ngoái cửa hàng nhỏ đó thu được lợi nhuận khá tốt."},{"en":"They sold the old house at a profit.","vi":"Họ đã bán căn nhà cũ và có lãi."},{"en":"Our company''s profits rose by ten percent this year.","vi":"Lợi nhuận của công ty chúng tôi tăng mười phần trăm trong năm nay."}]','[{"phrase":"make a profit"},{"phrase":"at a profit"},{"phrase":"profit margin"}]',NULL,'/ˈprɑːfɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profi/profit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(876,'ngsl-2-14',20,'guess','đoán; nghĩ là','verb','[{"en":"Can you guess how old my grandmother is?","vi":"Bạn có đoán được bà tôi bao nhiêu tuổi không?"},{"en":"I didn''t know the answer, so I just guessed.","vi":"Tôi không biết câu trả lời nên chỉ đoán thôi."},{"en":"I guess we should leave before the traffic gets bad.","vi":"Tôi nghĩ chúng ta nên đi trước khi đường bị kẹt xe."}]','[{"phrase":"guess the answer"},{"phrase":"take a guess"},{"phrase":"I guess so"}]',NULL,'/ɡes/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gue/guess/guess__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(877,'ngsl-2-14',21,'fun','niềm vui; sự vui vẻ','noun','[{"en":"We had a lot of fun at the beach yesterday.","vi":"Hôm qua chúng tôi đã rất vui ở bãi biển."},{"en":"Learning a new language can be great fun.","vi":"Học một ngôn ngữ mới có thể là niềm vui lớn."},{"en":"The kids played in the snow just for fun.","vi":"Bọn trẻ chơi trong tuyết chỉ để cho vui."}]','[{"phrase":"have fun"},{"phrase":"for fun"},{"phrase":"great fun"},{"phrase":"a lot of fun"}]','không đếm được; have fun: vui vẻ, chơi vui','/fʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/fun__/fun__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(878,'ngsl-2-14',22,'protect','bảo vệ; che chở','verb','[{"en":"Wear sunglasses to protect your eyes from the sun.","vi":"Hãy đeo kính râm để bảo vệ mắt khỏi ánh nắng."},{"en":"Parents always want to protect their children.","vi":"Cha mẹ luôn muốn che chở cho con cái."},{"en":"We must do more to protect the environment.","vi":"Chúng ta phải làm nhiều hơn nữa để bảo vệ môi trường."}]','[{"phrase":"protect from"},{"phrase":"protect the environment"},{"phrase":"protect yourself"}]','protect sb/sth from sth','/prəˈtekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(879,'ngsl-2-14',23,'resource','tài nguyên; nguồn lực; tài liệu','noun','[{"en":"Water is one of our most important natural resources.","vi":"Nước là một trong những tài nguyên thiên nhiên quan trọng nhất của chúng ta."},{"en":"The school doesn''t have enough resources to buy new computers.","vi":"Trường không có đủ nguồn lực để mua máy tính mới."},{"en":"The library has many useful resources for students learning English.","vi":"Thư viện có nhiều tài liệu hữu ích cho sinh viên học tiếng Anh."}]','[{"phrase":"natural resources"},{"phrase":"limited resources"},{"phrase":"learning resources"}]',NULL,'/ˈriːsɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resou/resource__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(880,'ngsl-2-14',24,'science','khoa học; môn khoa học','noun','[{"en":"Science was my favorite subject in high school.","vi":"Khoa học là môn học yêu thích của tôi hồi cấp ba."},{"en":"Modern science has helped people live longer.","vi":"Khoa học hiện đại đã giúp con người sống lâu hơn."},{"en":"She wants to study computer science at university.","vi":"Cô ấy muốn học ngành khoa học máy tính ở đại học."}]','[{"phrase":"computer science"},{"phrase":"science teacher"},{"phrase":"modern science"},{"phrase":"science fiction"}]',NULL,'/ˈsaɪəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sci/scien/science__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(881,'ngsl-2-14',25,'disease','bệnh; bệnh tật','noun','[{"en":"Washing your hands helps stop the spread of disease.","vi":"Rửa tay giúp ngăn chặn sự lây lan của bệnh tật."},{"en":"Eating too much sugar can increase the risk of heart disease.","vi":"Ăn quá nhiều đường có thể làm tăng nguy cơ mắc bệnh tim."},{"en":"Doctors are still learning about this rare disease.","vi":"Các bác sĩ vẫn đang tìm hiểu về căn bệnh hiếm gặp này."}]','[{"phrase":"heart disease"},{"phrase":"spread of disease"},{"phrase":"rare disease"},{"phrase":"infectious disease"}]',NULL,'/dɪˈziːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disea/disease__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(882,'ngsl-2-14',26,'balance','sự cân bằng; thăng bằng; số dư','noun','[{"en":"It''s hard to find a good balance between work and family.","vi":"Thật khó tìm được sự cân bằng tốt giữa công việc và gia đình."},{"en":"He lost his balance and fell off his bike.","vi":"Anh ấy mất thăng bằng và ngã khỏi xe đạp."},{"en":"You can check your account balance on the bank''s app.","vi":"Bạn có thể kiểm tra số dư tài khoản trên ứng dụng của ngân hàng."}]','[{"phrase":"lose your balance"},{"phrase":"keep your balance"},{"phrase":"work-life balance"},{"phrase":"account balance"}]',NULL,'/ˈbæləns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bal/balan/balance__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(883,'ngsl-2-14',27,'damage','sự hư hại; thiệt hại','noun','[{"en":"The storm caused serious damage to many homes.","vi":"Cơn bão gây thiệt hại nghiêm trọng cho nhiều ngôi nhà."},{"en":"Luckily, there was no damage to my car.","vi":"May mắn là xe của tôi không bị hư hại gì."},{"en":"Too much sun can do damage to your skin.","vi":"Phơi nắng quá nhiều có thể gây hại cho da của bạn."}]','[{"phrase":"cause damage"},{"phrase":"serious damage"},{"phrase":"damage to"},{"phrase":"do damage"}]','không đếm được; damage (v): làm hư hại','/ˈdæmɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dam/damag/damage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(884,'ngsl-2-14',28,'basis','cơ sở; nền tảng','noun','[{"en":"Trust is the basis of every good friendship.","vi":"Sự tin tưởng là nền tảng của mọi tình bạn tốt đẹp."},{"en":"Decisions should be made on the basis of facts.","vi":"Các quyết định nên được đưa ra dựa trên cơ sở sự thật."},{"en":"These notes will form the basis of my final report.","vi":"Những ghi chú này sẽ là cơ sở cho bản báo cáo cuối cùng của tôi."}]','[{"phrase":"on the basis of"},{"phrase":"form the basis"},{"phrase":"on a daily basis"},{"phrase":"on a regular basis"}]','số nhiều: bases; on a daily basis: hằng ngày','/ˈbeɪsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/basis/basis__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(885,'ngsl-2-14',29,'author','tác giả','noun','[{"en":"Who is the author of this book?","vi":"Ai là tác giả của cuốn sách này?"},{"en":"The author spent five years writing her first novel.","vi":"Tác giả đã dành năm năm để viết cuốn tiểu thuyết đầu tay của mình."},{"en":"My favorite author is visiting our local bookstore next week.","vi":"Tác giả yêu thích của tôi sẽ đến hiệu sách gần nhà chúng tôi vào tuần tới."}]','[{"phrase":"famous author"},{"phrase":"best-selling author"},{"phrase":"favorite author"}]',NULL,'/ˈɔːθər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autho/author__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(886,'ngsl-2-15',1,'basic','cơ bản; đơn giản, sơ sài','adjective','[{"en":"You only need basic computer skills for this job.","vi":"Bạn chỉ cần kỹ năng máy tính cơ bản cho công việc này."},{"en":"Everyone should learn some basic first aid.","vi":"Mọi người nên học một chút sơ cứu cơ bản."},{"en":"The hotel room was quite basic, but it was clean.","vi":"Phòng khách sạn khá đơn sơ nhưng sạch sẽ."}]','[{"phrase":"basic skills"},{"phrase":"basic knowledge"},{"phrase":"basic needs"}]',NULL,'/ˈbeɪsɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/basic/basic__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(887,'ngsl-2-15',2,'encourage','khuyến khích; động viên','verb','[{"en":"My parents always encouraged me to read books.","vi":"Bố mẹ tôi luôn khuyến khích tôi đọc sách."},{"en":"Teachers should encourage students to ask questions in class.","vi":"Giáo viên nên khuyến khích học sinh đặt câu hỏi trong lớp."},{"en":"Her friends encouraged her when she felt like giving up.","vi":"Bạn bè đã động viên cô ấy khi cô ấy muốn bỏ cuộc."}]','[{"phrase":"strongly encourage"},{"phrase":"encourage students"},{"phrase":"feel encouraged"}]',NULL,'/ɪnˈkɜːrɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enc/encou/encourage__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(888,'ngsl-2-15',3,'hair','tóc; lông','noun','[{"en":"She has long black hair and brown eyes.","vi":"Cô ấy có mái tóc đen dài và đôi mắt nâu."},{"en":"I need to get my hair cut before the wedding.","vi":"Tôi cần đi cắt tóc trước đám cưới."},{"en":"There is cat hair all over the sofa.","vi":"Lông mèo dính khắp ghế sofa."}]','[{"phrase":"long hair"},{"phrase":"short hair"},{"phrase":"wash your hair"},{"phrase":"brush your hair"}]','Chỉ tóc nói chung: không đếm được (her hair is long)','/her/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hai/hair_/hair__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(889,'ngsl-2-15',4,'male','nam; đực, trống','adjective','[{"en":"Only two male students joined the dance class.","vi":"Chỉ có hai nam sinh tham gia lớp học nhảy."},{"en":"Is your new puppy male or female?","vi":"Chú chó con mới của bạn là đực hay cái?"},{"en":"The male bird has brighter feathers than the female.","vi":"Chim trống có bộ lông sặc sỡ hơn chim mái."}]','[{"phrase":"male and female"},{"phrase":"male students"},{"phrase":"male friend"}]','male ≠ female (nữ; cái, mái)','/meɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mal/male_/male__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(890,'ngsl-2-15',5,'operate','vận hành, điều khiển; hoạt động; phẫu thuật','verb','[{"en":"Only trained staff are allowed to operate this machine.","vi":"Chỉ nhân viên đã được đào tạo mới được phép vận hành máy này."},{"en":"The company operates in more than twenty countries.","vi":"Công ty hoạt động tại hơn hai mươi quốc gia."},{"en":"The doctors had to operate on his knee last week.","vi":"Tuần trước các bác sĩ đã phải phẫu thuật đầu gối của anh ấy."}]','[{"phrase":"operate a machine"},{"phrase":"operate on"},{"phrase":"operate in"}]','operate on sb/sth: phẫu thuật cho ai/bộ phận nào','/ˈɑːpəreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/operate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(891,'ngsl-2-15',6,'reflect','phản ánh; phản chiếu; suy ngẫm','verb','[{"en":"Her choice of clothes reflects her personality.","vi":"Cách chọn quần áo của cô ấy phản ánh tính cách của cô ấy."},{"en":"The lake reflected the mountains like a mirror.","vi":"Mặt hồ phản chiếu những ngọn núi như một tấm gương."},{"en":"Take some time to reflect on what you have learned.","vi":"Hãy dành chút thời gian suy ngẫm về những gì bạn đã học."}]','[{"phrase":"reflect on"},{"phrase":"reflect light"},{"phrase":"clearly reflect"}]','reflect on sth: suy ngẫm về điều gì','/rɪˈflekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refle/reflect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(892,'ngsl-2-15',7,'exercise','sự tập thể dục; bài tập','noun','[{"en":"Regular exercise helps you sleep better at night.","vi":"Tập thể dục đều đặn giúp bạn ngủ ngon hơn vào ban đêm."},{"en":"I try to get some exercise every morning before work.","vi":"Tôi cố gắng tập thể dục mỗi sáng trước khi đi làm."},{"en":"For homework, please finish the grammar exercises on page ten.","vi":"Về nhà, các em hãy làm các bài tập ngữ pháp ở trang mười."}]','[{"phrase":"regular exercise"},{"phrase":"get some exercise"},{"phrase":"do exercises"},{"phrase":"grammar exercises"}]','Tập thể dục: không đếm được; bài tập: đếm được','/ˈeksərsaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exe/exerc/exercise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(893,'ngsl-2-15',8,'useful','có ích, hữu ích','adjective','[{"en":"Thank you, your advice was really useful.","vi":"Cảm ơn bạn, lời khuyên của bạn thật sự rất hữu ích."},{"en":"A dictionary is useful when you learn a new language.","vi":"Từ điển rất hữu ích khi bạn học một ngôn ngữ mới."},{"en":"She gave me some useful tips for the interview.","vi":"Cô ấy cho tôi vài mẹo hữu ích cho buổi phỏng vấn."}]','[{"phrase":"very useful"},{"phrase":"useful information"},{"phrase":"useful tips"},{"phrase":"useful for"}]',NULL,'/ˈjuːsfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/use/usefu/useful__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(894,'ngsl-2-15',9,'restaurant','nhà hàng','noun','[{"en":"We had dinner at a small Italian restaurant downtown.","vi":"Chúng tôi ăn tối ở một nhà hàng Ý nhỏ trong trung tâm thành phố."},{"en":"This restaurant is always busy on Friday nights.","vi":"Nhà hàng này lúc nào cũng đông khách vào tối thứ Sáu."},{"en":"Could you recommend a good restaurant near the hotel?","vi":"Bạn có thể giới thiệu một nhà hàng ngon gần khách sạn không?"}]','[{"phrase":"go to a restaurant"},{"phrase":"Italian restaurant"},{"phrase":"restaurant owner"}]',NULL,'/ˈrestrɑːnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resta/restaurant__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(895,'ngsl-2-15',10,'income','thu nhập','noun','[{"en":"Most of their income goes on rent and food.","vi":"Phần lớn thu nhập của họ dành cho tiền thuê nhà và thức ăn."},{"en":"She earns extra income by teaching English online.","vi":"Cô ấy kiếm thêm thu nhập bằng cách dạy tiếng Anh trực tuyến."},{"en":"Families on a low income can get help with school costs.","vi":"Các gia đình có thu nhập thấp có thể được hỗ trợ chi phí học tập."}]','[{"phrase":"low income"},{"phrase":"high income"},{"phrase":"extra income"},{"phrase":"monthly income"}]',NULL,'/ˈɪnkʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incom/income__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(896,'ngsl-2-15',11,'property','tài sản; bất động sản, nhà đất','noun','[{"en":"Students must not damage school property in any way.","vi":"Học sinh không được làm hư hại tài sản của trường dưới bất kỳ hình thức nào."},{"en":"Property prices in the city center have risen sharply.","vi":"Giá nhà đất ở trung tâm thành phố đã tăng mạnh."},{"en":"They bought a property near the beach last year.","vi":"Năm ngoái họ đã mua một bất động sản gần biển."}]','[{"phrase":"private property"},{"phrase":"property prices"},{"phrase":"buy a property"}]',NULL,'/ˈprɑːpərti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prope/property__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(897,'ngsl-2-15',12,'previous','trước, trước đó','adjective','[{"en":"In my previous job, I worked very long hours.","vi":"Ở công việc trước, tôi phải làm việc rất nhiều giờ."},{"en":"The previous owners of the house left a piano behind.","vi":"Những người chủ trước của ngôi nhà đã để lại một cây đàn piano."},{"en":"She had met him on a previous visit to the city.","vi":"Cô ấy đã gặp anh ấy trong một lần đến thành phố trước đó."}]','[{"phrase":"previous job"},{"phrase":"previous owner"},{"phrase":"previous year"},{"phrase":"previous experience"}]',NULL,'/ˈpriːviəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/previ/previous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(898,'ngsl-2-15',13,'dark','tối; sẫm, đậm (màu)','adjective','[{"en":"It gets dark very early in winter.","vi":"Vào mùa đông trời tối rất sớm."},{"en":"The room was so dark that I couldn''t see anything.","vi":"Căn phòng tối đến mức tôi không nhìn thấy gì."},{"en":"He wore a dark blue suit to the meeting.","vi":"Anh ấy mặc bộ vest màu xanh đậm đến cuộc họp."}]','[{"phrase":"get dark"},{"phrase":"dark blue"},{"phrase":"dark hair"}]',NULL,'/dɑːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dar/dark_/dark__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(899,'ngsl-2-15',14,'imagine','tưởng tượng; hình dung','verb','[{"en":"Imagine you are lying on a quiet beach.","vi":"Hãy tưởng tượng bạn đang nằm trên một bãi biển yên tĩnh."},{"en":"I can''t imagine living without my phone.","vi":"Tôi không thể tưởng tượng được cuộc sống không có điện thoại."},{"en":"The city was much bigger than I had imagined.","vi":"Thành phố lớn hơn nhiều so với những gì tôi đã hình dung."}]','[{"phrase":"can''t imagine"},{"phrase":"try to imagine"},{"phrase":"imagine life without"}]','imagine + V-ing (imagine living)','/ɪˈmædʒɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/imagi/imagine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(900,'ngsl-2-15',15,'earn','kiếm (tiền); xứng đáng có, giành được','verb','[{"en":"He earns about two thousand dollars a month.","vi":"Anh ấy kiếm được khoảng hai nghìn đô la mỗi tháng."},{"en":"Many students earn money by working part-time.","vi":"Nhiều sinh viên kiếm tiền bằng cách làm thêm."},{"en":"After working so hard, you''ve earned a good rest.","vi":"Sau khi làm việc chăm chỉ như vậy, bạn xứng đáng được nghỉ ngơi thật tốt."}]','[{"phrase":"earn money"},{"phrase":"earn a living"},{"phrase":"earn respect"}]',NULL,'/ɜːrn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/earn_/earn__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(901,'ngsl-2-15',16,'daughter','con gái','noun','[{"en":"They have two sons and a daughter.","vi":"Họ có hai con trai và một con gái."},{"en":"My daughter will start elementary school next September.","vi":"Con gái tôi sẽ vào tiểu học vào tháng Chín tới."},{"en":"She takes her daughter to piano lessons every Saturday.","vi":"Cô ấy đưa con gái đi học piano mỗi thứ Bảy."}]','[{"phrase":"only daughter"},{"phrase":"eldest daughter"},{"phrase":"youngest daughter"}]',NULL,'/ˈdɔːtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dau/daugh/daughter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(902,'ngsl-2-15',17,'post','đăng (lên mạng); gửi (thư) qua bưu điện','verb','[{"en":"She posted a photo of her new puppy online.","vi":"Cô ấy đã đăng ảnh chú chó con mới của mình lên mạng."},{"en":"The results will be posted on the school website tomorrow.","vi":"Kết quả sẽ được đăng trên trang web của trường vào ngày mai."},{"en":"I''ll post the letter on my way to work.","vi":"Tôi sẽ gửi lá thư trên đường đi làm."}]','[{"phrase":"post a photo"},{"phrase":"post online"},{"phrase":"post a comment"},{"phrase":"post a letter"}]','Gửi thư: Anh: post · Mỹ: mail','/pəʊst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/post_/post__1_us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(903,'ngsl-2-15',18,'newspaper','báo, tờ báo','noun','[{"en":"My grandfather reads the newspaper every morning with his coffee.","vi":"Ông tôi đọc báo mỗi sáng khi uống cà phê."},{"en":"I saw the job advertisement in a local newspaper.","vi":"Tôi thấy mẩu quảng cáo tuyển dụng trên một tờ báo địa phương."},{"en":"Her story appeared on the front page of the newspaper.","vi":"Câu chuyện của cô ấy xuất hiện trên trang nhất của tờ báo."}]','[{"phrase":"read the newspaper"},{"phrase":"local newspaper"},{"phrase":"newspaper article"},{"phrase":"daily newspaper"}]',NULL,'/ˈnuːzpeɪpər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/newsp/newspaper__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(904,'ngsl-2-15',19,'define','định nghĩa; xác định','verb','[{"en":"Can you define this word in simple English?","vi":"Bạn có thể định nghĩa từ này bằng tiếng Anh đơn giản không?"},{"en":"It is hard to define what happiness really is.","vi":"Thật khó để định nghĩa hạnh phúc thực sự là gì."},{"en":"First, we need to clearly define the goals of the project.","vi":"Trước hết, chúng ta cần xác định rõ mục tiêu của dự án."}]','[{"phrase":"clearly define"},{"phrase":"define a word"},{"phrase":"hard to define"}]',NULL,'/dɪˈfaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/define__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(905,'ngsl-2-15',20,'conclusion','kết luận; phần kết','noun','[{"en":"What conclusion did you reach after reading the report?","vi":"Bạn đã rút ra kết luận gì sau khi đọc bản báo cáo?"},{"en":"We came to the conclusion that the plan wouldn''t work.","vi":"Chúng tôi đi đến kết luận rằng kế hoạch đó sẽ không hiệu quả."},{"en":"Remember to write a short conclusion at the end of your essay.","vi":"Nhớ viết một đoạn kết ngắn ở cuối bài luận của bạn."}]','[{"phrase":"come to a conclusion"},{"phrase":"reach a conclusion"},{"phrase":"draw a conclusion"},{"phrase":"in conclusion"}]',NULL,'/kənˈkluːʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconclusion__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(906,'ngsl-2-15',21,'clock','đồng hồ (treo tường, để bàn)','noun','[{"en":"The clock on the kitchen wall is five minutes fast.","vi":"Chiếc đồng hồ trên tường bếp chạy nhanh năm phút."},{"en":"I set my alarm clock for six o''clock.","vi":"Tôi đặt đồng hồ báo thức lúc sáu giờ."},{"en":"She kept looking at the clock during the boring meeting.","vi":"Cô ấy cứ nhìn đồng hồ suốt cuộc họp nhàm chán."}]','[{"phrase":"alarm clock"},{"phrase":"look at the clock"},{"phrase":"wall clock"}]','clock (treo tường, để bàn) ≠ watch (đồng hồ đeo tay)','/klɑːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/clock/clock__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(907,'ngsl-2-15',22,'everybody','mọi người','pronoun','[{"en":"Everybody in my family loves spicy food.","vi":"Mọi người trong gia đình tôi đều thích đồ ăn cay."},{"en":"Can everybody hear me at the back of the room?","vi":"Mọi người ở cuối phòng có nghe thấy tôi không?"},{"en":"Not everybody agrees with the new rules at work.","vi":"Không phải ai cũng đồng ý với các quy định mới ở chỗ làm."}]','[{"phrase":"everybody else"},{"phrase":"everybody knows"},{"phrase":"not everybody"}]','Đi với động từ số ít: everybody knows','/ˈevribɑːdi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everybody__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(908,'ngsl-2-15',23,'weekend','cuối tuần','noun','[{"en":"What are you planning to do this weekend?","vi":"Bạn định làm gì vào cuối tuần này?"},{"en":"We spent the weekend at my grandparents'' farm.","vi":"Chúng tôi đã ở trang trại của ông bà tôi vào cuối tuần."},{"en":"The library is closed on weekends and public holidays.","vi":"Thư viện đóng cửa vào cuối tuần và các ngày lễ."}]','[{"phrase":"this weekend"},{"phrase":"last weekend"},{"phrase":"on weekends"},{"phrase":"spend the weekend"}]','Mỹ: on the weekend · Anh: at the weekend','/ˈwiːkend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wee/weeke/weekend__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(909,'ngsl-2-15',24,'perform','biểu diễn; thực hiện; làm (tốt, kém)','verb','[{"en":"The band will perform live in the park on Sunday.","vi":"Ban nhạc sẽ biểu diễn trực tiếp trong công viên vào Chủ nhật."},{"en":"This machine can perform several tasks at the same time.","vi":"Chiếc máy này có thể thực hiện nhiều việc cùng lúc."},{"en":"She performed very well in her final exams.","vi":"Cô ấy đã làm bài rất tốt trong các kỳ thi cuối kỳ."}]','[{"phrase":"perform live"},{"phrase":"perform a task"},{"phrase":"perform well"}]',NULL,'/pərˈfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfo/perform__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(910,'ngsl-2-15',25,'professional','chuyên nghiệp; chuyên môn','adjective','[{"en":"He wants to become a professional soccer player.","vi":"Anh ấy muốn trở thành cầu thủ bóng đá chuyên nghiệp."},{"en":"The staff at the hotel were friendly and very professional.","vi":"Nhân viên khách sạn thân thiện và rất chuyên nghiệp."},{"en":"You should get professional advice before buying a house.","vi":"Bạn nên xin tư vấn chuyên môn trước khi mua nhà."}]','[{"phrase":"professional advice"},{"phrase":"professional help"},{"phrase":"professional player"}]',NULL,'/prəˈfeʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/professional__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(911,'ngsl-2-15',26,'debate','cuộc tranh luận, tranh biện; sự tranh cãi','noun','[{"en":"The class had a lively debate about school uniforms.","vi":"Cả lớp đã có một cuộc tranh luận sôi nổi về đồng phục học sinh."},{"en":"Our team won the debate against the other school.","vi":"Đội chúng tôi đã thắng cuộc tranh biện với trường kia."},{"en":"There is a lot of debate about how much homework children need.","vi":"Có nhiều tranh cãi về việc trẻ em cần bao nhiêu bài tập về nhà."}]','[{"phrase":"lively debate"},{"phrase":"heated debate"},{"phrase":"public debate"},{"phrase":"win a debate"}]',NULL,'/dɪˈbeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deb/debat/debate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(912,'ngsl-2-15',27,'memory','trí nhớ; kỷ niệm','noun','[{"en":"My grandmother has a very good memory for names.","vi":"Bà tôi có trí nhớ rất tốt về tên người."},{"en":"I have a terrible memory, so I write everything down.","vi":"Trí nhớ của tôi rất tệ nên tôi ghi lại mọi thứ."},{"en":"I have happy memories of summers at the beach.","vi":"Tôi có những kỷ niệm vui về những mùa hè ở biển."}]','[{"phrase":"good memory"},{"phrase":"bad memory"},{"phrase":"happy memories"},{"phrase":"childhood memories"}]',NULL,'/ˈmeməri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mem/memor/memory__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(913,'ngsl-2-15',28,'green','xanh lá cây; thân thiện với môi trường','adjective','[{"en":"She was wearing a light green dress.","vi":"Cô ấy mặc một chiếc váy màu xanh lá nhạt."},{"en":"The hills are so green after the spring rain.","vi":"Những ngọn đồi thật xanh tươi sau cơn mưa xuân."},{"en":"The company is trying to be greener by using less plastic.","vi":"Công ty đang cố gắng thân thiện với môi trường hơn bằng cách dùng ít nhựa."}]','[{"phrase":"light green"},{"phrase":"dark green"},{"phrase":"green tea"}]',NULL,'/ɡriːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/green/green__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(914,'ngsl-2-15',29,'song','bài hát','noun','[{"en":"This is my favorite song from the album.","vi":"Đây là bài hát tôi thích nhất trong album."},{"en":"The children sang a song for their teacher''s birthday.","vi":"Bọn trẻ hát một bài hát mừng sinh nhật cô giáo."},{"en":"I can''t get that song out of my head.","vi":"Bài hát đó cứ vang mãi trong đầu tôi."}]','[{"phrase":"sing a song"},{"phrase":"favorite song"},{"phrase":"love song"},{"phrase":"pop song"}]',NULL,'/sɔːŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/son/song_/song_1_us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(915,'ngsl-2-16',1,'object','đồ vật, vật thể; mục đích','noun','[{"en":"She picked up a small metal object from the floor.","vi":"Cô ấy nhặt một vật nhỏ bằng kim loại lên từ sàn nhà."},{"en":"Nobody could identify the strange object in the sky.","vi":"Không ai có thể xác định được vật thể lạ trên bầu trời."},{"en":"The object of the game is to collect as many points as possible.","vi":"Mục đích của trò chơi là thu được càng nhiều điểm càng tốt."}]','[{"phrase":"small object"},{"phrase":"everyday objects"},{"phrase":"object of the game"}]',NULL,'/ˈɑːbdʒɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obj/objec/object__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(916,'ngsl-2-16',2,'maintain','duy trì, giữ; bảo dưỡng','verb','[{"en":"It is hard to maintain a healthy weight when you work long hours.","vi":"Thật khó duy trì cân nặng hợp lý khi bạn làm việc nhiều giờ."},{"en":"We try to maintain good relations with all our neighbors.","vi":"Chúng tôi cố gắng giữ quan hệ tốt với tất cả hàng xóm."},{"en":"The city spends a lot of money maintaining its roads.","vi":"Thành phố chi rất nhiều tiền để bảo dưỡng đường sá."}]','[{"phrase":"maintain good relations"},{"phrase":"maintain a healthy weight"},{"phrase":"well maintained"}]',NULL,'/meɪnˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/maint/maintain__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(917,'ngsl-2-16',3,'credit','tín dụng; sự ghi nhận công lao; tín chỉ','noun','[{"en":"Can I pay by credit card, or do you only take cash?","vi":"Tôi có thể trả bằng thẻ tín dụng không, hay bạn chỉ nhận tiền mặt?"},{"en":"She deserves credit for all the hard work she put in.","vi":"Cô ấy xứng đáng được ghi nhận vì tất cả công sức đã bỏ ra."},{"en":"You need 120 credits to graduate from this program.","vi":"Bạn cần 120 tín chỉ để tốt nghiệp chương trình này."}]','[{"phrase":"credit card"},{"phrase":"deserve credit"},{"phrase":"take credit for"}]',NULL,'/ˈkredɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/credi/credit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(918,'ngsl-2-16',4,'ring','reo, rung (chuông); gọi điện thoại','verb','[{"en":"The phone rang just as I was getting into the shower.","vi":"Điện thoại reo đúng lúc tôi vừa bước vào tắm."},{"en":"Please ring the bell if you need any help.","vi":"Vui lòng bấm chuông nếu bạn cần giúp đỡ."},{"en":"I''ll ring you tomorrow morning to confirm the time.","vi":"Sáng mai tôi sẽ gọi điện cho bạn để xác nhận giờ giấc."}]','[{"phrase":"phone rings"},{"phrase":"ring the bell"},{"phrase":"ring the doorbell"}]','ring – rang – rung','/rɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rin/ring_/ring__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(919,'ngsl-2-16',5,'discover','khám phá; phát hiện','verb','[{"en":"Scientists have discovered a new kind of fish in the river.","vi":"Các nhà khoa học đã phát hiện một loài cá mới ở con sông."},{"en":"We discovered a lovely little café near our hotel.","vi":"Chúng tôi đã khám phá ra một quán cà phê nhỏ xinh gần khách sạn."},{"en":"It took years for him to discover the truth about his family.","vi":"Anh ấy mất nhiều năm mới phát hiện ra sự thật về gia đình mình."}]','[{"phrase":"discover the truth"},{"phrase":"newly discovered"},{"phrase":"discover that"}]',NULL,'/dɪˈskʌvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disco/discover__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(920,'ngsl-2-16',6,'dead','chết; hết pin, không hoạt động','adjective','[{"en":"Remove the dead leaves so the plant can grow better.","vi":"Hãy bỏ những chiếc lá chết đi để cây phát triển tốt hơn."},{"en":"The car won''t start because of a dead battery.","vi":"Xe không khởi động được vì bình ắc quy hết điện."},{"en":"My phone is dead, so I can''t call a taxi.","vi":"Điện thoại tôi hết pin nên tôi không gọi taxi được."}]','[{"phrase":"dead leaves"},{"phrase":"dead battery"},{"phrase":"dead end"}]',NULL,'/ded/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/dead_/dead__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(921,'ngsl-2-16',7,'afternoon','buổi chiều','noun','[{"en":"I usually take a short nap in the afternoon.","vi":"Tôi thường chợp mắt một lát vào buổi chiều."},{"en":"Are you free on Friday afternoon for a quick meeting?","vi":"Chiều thứ Sáu bạn có rảnh để họp nhanh không?"},{"en":"We spent the whole afternoon walking around the old town.","vi":"Chúng tôi dành cả buổi chiều đi dạo quanh khu phố cổ."}]','[{"phrase":"in the afternoon"},{"phrase":"this afternoon"},{"phrase":"Friday afternoon"},{"phrase":"late afternoon"}]',NULL,'/ˌæftərˈnuːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aft/after/afternoon__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(922,'ngsl-2-16',8,'prefer','thích hơn','verb','[{"en":"I prefer tea to coffee in the morning.","vi":"Buổi sáng tôi thích uống trà hơn cà phê."},{"en":"I would prefer to stay home tonight, if you don''t mind.","vi":"Tối nay tôi muốn ở nhà hơn, nếu bạn không phiền."},{"en":"Most of our customers prefer paying by card.","vi":"Phần lớn khách hàng của chúng tôi thích trả bằng thẻ hơn."}]','[{"phrase":"would prefer"},{"phrase":"much prefer"},{"phrase":"prefer tea to coffee"}]','prefer A to B · preferred (gấp đôi r)','/prɪˈfɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prefe/prefer__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(923,'ngsl-2-16',9,'extend','kéo dài; gia hạn; mở rộng','verb','[{"en":"We decided to extend our stay in the city by three days.","vi":"Chúng tôi quyết định kéo dài thời gian ở lại thành phố thêm ba ngày."},{"en":"The teacher agreed to extend the deadline by one week.","vi":"Giáo viên đồng ý gia hạn thời hạn nộp bài thêm một tuần."},{"en":"The school plans to extend the library next year.","vi":"Nhà trường dự định mở rộng thư viện vào năm sau."}]','[{"phrase":"extend the deadline"},{"phrase":"extend your stay"},{"phrase":"extend a contract"}]',NULL,'/ɪkˈstend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extend__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(924,'ngsl-2-16',10,'possibility','khả năng; sự có thể','noun','[{"en":"There is a possibility that it will rain this afternoon.","vi":"Có khả năng chiều nay trời sẽ mưa."},{"en":"Have you considered the possibility of studying abroad?","vi":"Bạn đã tính đến khả năng đi du học chưa?"},{"en":"We can''t rule out the possibility of delays.","vi":"Chúng ta không thể loại trừ khả năng bị chậm trễ."}]','[{"phrase":"real possibility"},{"phrase":"strong possibility"},{"phrase":"rule out the possibility"},{"phrase":"consider the possibility"}]',NULL,'/ˌpɑːsəˈbɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/possi/possibility__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(925,'ngsl-2-16',11,'direction','hướng; sự chỉ dẫn','noun','[{"en":"Excuse me, which direction is the train station?","vi":"Xin lỗi, ga tàu ở hướng nào vậy?"},{"en":"We were walking in the wrong direction for twenty minutes.","vi":"Chúng tôi đã đi sai hướng suốt hai mươi phút."},{"en":"Follow the directions on the box carefully.","vi":"Hãy làm theo kỹ các chỉ dẫn trên hộp."}]','[{"phrase":"opposite direction"},{"phrase":"wrong direction"},{"phrase":"ask for directions"}]','directions (số nhiều) = lời chỉ đường, hướng dẫn','/dəˈrekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/direction__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(926,'ngsl-2-16',12,'facility','cơ sở vật chất; tiện nghi','noun','[{"en":"The hotel has excellent sports facilities, including a pool.","vi":"Khách sạn có cơ sở vật chất thể thao rất tốt, gồm cả hồ bơi."},{"en":"Our school recently opened a new research facility.","vi":"Trường chúng tôi vừa mở một cơ sở nghiên cứu mới."},{"en":"Are there any parking facilities near the hospital?","vi":"Gần bệnh viện có bãi đỗ xe nào không?"}]','[{"phrase":"sports facilities"},{"phrase":"research facility"},{"phrase":"parking facilities"},{"phrase":"medical facilities"}]','thường dùng số nhiều: facilities','/fəˈsɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facil/facility__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(927,'ngsl-2-16',13,'variety','sự đa dạng; loại, giống','noun','[{"en":"The market sells a wide variety of fresh fruit.","vi":"Chợ bán rất nhiều loại trái cây tươi."},{"en":"I like my job because it offers plenty of variety.","vi":"Tôi thích công việc của mình vì nó rất đa dạng."},{"en":"This variety of apple is sweet and very crunchy.","vi":"Giống táo này ngọt và rất giòn."}]','[{"phrase":"a wide variety of"},{"phrase":"a variety of"},{"phrase":"great variety"}]',NULL,'/vəˈraɪəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/varie/variety__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(928,'ngsl-2-16',14,'daily','hằng ngày','adjective','[{"en":"Exercise has become part of my daily routine.","vi":"Tập thể dục đã trở thành một phần thói quen hằng ngày của tôi."},{"en":"She writes about her daily life on a small blog.","vi":"Cô ấy viết về cuộc sống hằng ngày của mình trên một blog nhỏ."},{"en":"We check the equipment on a daily basis.","vi":"Chúng tôi kiểm tra thiết bị hằng ngày."}]','[{"phrase":"daily routine"},{"phrase":"daily life"},{"phrase":"on a daily basis"},{"phrase":"daily newspaper"}]',NULL,'/ˈdeɪli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dai/daily/daily__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(929,'ngsl-2-16',15,'clothes','quần áo','noun','[{"en":"I need to buy some new clothes for work.","vi":"Tôi cần mua vài bộ quần áo mới để đi làm."},{"en":"Take off your wet clothes before you catch a cold.","vi":"Cởi quần áo ướt ra kẻo bạn bị cảm lạnh."},{"en":"She always wears comfortable clothes when she travels.","vi":"Cô ấy luôn mặc quần áo thoải mái khi đi du lịch."}]','[{"phrase":"new clothes"},{"phrase":"wet clothes"},{"phrase":"change clothes"},{"phrase":"casual clothes"}]','luôn ở dạng số nhiều','/kləʊðz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/cloth/clothes__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(930,'ngsl-2-16',16,'screen','màn hình','noun','[{"en":"My phone screen cracked when I dropped it.","vi":"Màn hình điện thoại của tôi bị nứt khi tôi làm rơi nó."},{"en":"Doctors say children should have less screen time each day.","vi":"Bác sĩ khuyên trẻ em nên dành ít thời gian nhìn màn hình hơn mỗi ngày."},{"en":"Can you share your screen so we can all see the slides?","vi":"Bạn chia sẻ màn hình để mọi người cùng xem slide được không?"}]','[{"phrase":"computer screen"},{"phrase":"touch screen"},{"phrase":"screen time"},{"phrase":"share your screen"}]',NULL,'/skriːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/scr/scree/screen__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(931,'ngsl-2-16',17,'track','đường mòn; đường chạy; bài hát (trong album)','noun','[{"en":"We followed a narrow track through the forest.","vi":"Chúng tôi đi theo một con đường mòn hẹp xuyên qua khu rừng."},{"en":"The athletes ran four laps around the running track.","vi":"Các vận động viên chạy bốn vòng quanh đường chạy."},{"en":"This is my favorite track on the whole album.","vi":"Đây là bài hát tôi thích nhất trong cả album."}]','[{"phrase":"running track"},{"phrase":"dirt track"},{"phrase":"keep track of"}]',NULL,'/træk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/track/track__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(932,'ngsl-2-16',18,'dance','nhảy, khiêu vũ','verb','[{"en":"My grandparents still love to dance together at parties.","vi":"Ông bà tôi vẫn thích nhảy cùng nhau trong các bữa tiệc."},{"en":"We danced all night at my cousin''s wedding.","vi":"Chúng tôi đã nhảy suốt đêm ở đám cưới của anh họ tôi."},{"en":"Can you teach me how to dance the salsa?","vi":"Bạn có thể dạy tôi nhảy salsa không?"}]','[{"phrase":"dance together"},{"phrase":"dance to the music"},{"phrase":"learn to dance"}]',NULL,'/dæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dan/dance/dance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(933,'ngsl-2-16',19,'completely','hoàn toàn','adverb','[{"en":"I completely forgot about our meeting this morning.","vi":"Tôi hoàn toàn quên mất cuộc họp của chúng ta sáng nay."},{"en":"The new building is completely different from the old one.","vi":"Tòa nhà mới hoàn toàn khác với tòa nhà cũ."},{"en":"Make sure the paint is completely dry before you touch it.","vi":"Hãy đảm bảo sơn đã khô hoàn toàn trước khi bạn chạm vào."}]','[{"phrase":"completely different"},{"phrase":"completely forget"},{"phrase":"completely wrong"}]',NULL,'/kəmˈpliːtli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/completely__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(934,'ngsl-2-16',20,'female','nữ; (giống) cái','adjective','[{"en":"Most of the students in my class are female.","vi":"Phần lớn học sinh trong lớp tôi là nữ."},{"en":"The female bird sits on the eggs to keep them warm.","vi":"Chim mái nằm ấp trứng để giữ ấm cho trứng."},{"en":"The company wants to hire more female engineers.","vi":"Công ty muốn tuyển thêm nhiều kỹ sư nữ."}]','[{"phrase":"female students"},{"phrase":"female employees"},{"phrase":"female voice"}]',NULL,'/ˈfiːmeɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fem/femal/female__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(935,'ngsl-2-16',21,'responsibility','trách nhiệm','noun','[{"en":"Taking care of the dog is my brother''s responsibility.","vi":"Chăm sóc con chó là trách nhiệm của anh trai tôi."},{"en":"Parents have a responsibility to keep their children safe.","vi":"Cha mẹ có trách nhiệm giữ cho con cái được an toàn."},{"en":"She took full responsibility for the mistake.","vi":"Cô ấy nhận toàn bộ trách nhiệm về sai lầm đó."}]','[{"phrase":"take responsibility for"},{"phrase":"full responsibility"},{"phrase":"a sense of responsibility"}]','responsibility for sth','/rɪˌspɑːnsəˈbɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/responsibility__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(936,'ngsl-2-16',22,'original','ban đầu, gốc; độc đáo','adjective','[{"en":"The original plan was to leave on Monday.","vi":"Kế hoạch ban đầu là khởi hành vào thứ Hai."},{"en":"Please keep the original receipt in case you need a refund.","vi":"Vui lòng giữ hóa đơn gốc phòng khi bạn cần hoàn tiền."},{"en":"Her ideas are always fresh and original.","vi":"Ý tưởng của cô ấy luôn mới mẻ và độc đáo."}]','[{"phrase":"original plan"},{"phrase":"original version"},{"phrase":"original idea"}]',NULL,'/əˈrɪdʒənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/origi/original__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(937,'ngsl-2-16',23,'sister','chị gái; em gái','noun','[{"en":"My older sister lives in another city with her husband.","vi":"Chị gái tôi sống ở một thành phố khác cùng chồng."},{"en":"I share a bedroom with my little sister.","vi":"Tôi ở chung phòng ngủ với em gái."},{"en":"Do you have any brothers or sisters?","vi":"Bạn có anh chị em nào không?"}]','[{"phrase":"older sister"},{"phrase":"younger sister"},{"phrase":"little sister"},{"phrase":"big sister"}]','older sister = chị gái · younger sister = em gái','/ˈsɪstər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sis/siste/sister__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(938,'ngsl-2-16',24,'rock','đá, tảng đá; nhạc rock','noun','[{"en":"We sat on a large rock and watched the sunset.","vi":"Chúng tôi ngồi trên một tảng đá lớn ngắm hoàng hôn."},{"en":"Be careful, the rocks near the water are slippery.","vi":"Cẩn thận nhé, mấy tảng đá gần mép nước trơn lắm."},{"en":"My dad listens to rock music while he cooks.","vi":"Bố tôi nghe nhạc rock trong lúc nấu ăn."}]','[{"phrase":"rock music"},{"phrase":"rock band"},{"phrase":"large rock"}]',NULL,'/rɑːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roc/rock_/rock__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(939,'ngsl-2-16',25,'dream','giấc mơ; ước mơ','noun','[{"en":"I had a strange dream about flying last night.","vi":"Đêm qua tôi có một giấc mơ kỳ lạ về việc bay."},{"en":"Her dream is to open a small bakery one day.","vi":"Ước mơ của cô ấy là một ngày nào đó mở một tiệm bánh nhỏ."},{"en":"Working abroad was a dream come true for him.","vi":"Được làm việc ở nước ngoài là giấc mơ thành hiện thực của anh ấy."}]','[{"phrase":"have a dream"},{"phrase":"bad dream"},{"phrase":"dream come true"},{"phrase":"dream job"}]',NULL,'/driːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dre/dream/dream__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(940,'ngsl-2-16',26,'nor','cũng không','conjunction','[{"en":"Neither my brother nor I can swim very well.","vi":"Cả anh trai tôi và tôi đều không bơi giỏi lắm."},{"en":"He doesn''t eat meat, nor does he drink milk.","vi":"Anh ấy không ăn thịt, cũng không uống sữa."},{"en":"The hotel was neither cheap nor very comfortable.","vi":"Khách sạn không rẻ mà cũng chẳng thoải mái lắm."}]','[{"phrase":"neither ... nor"},{"phrase":"nor do I"}]','neither A nor B · nor đứng đầu mệnh đề thì đảo trợ động từ','/nɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/nor__/nor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(941,'ngsl-2-16',27,'university','trường đại học','noun','[{"en":"My cousin studies medicine at a large university.","vi":"Anh họ tôi học y ở một trường đại học lớn."},{"en":"She was the first in her family to go to university.","vi":"Cô ấy là người đầu tiên trong gia đình được học đại học."},{"en":"The university library stays open until midnight during exams.","vi":"Thư viện trường đại học mở cửa đến nửa đêm trong mùa thi."}]','[{"phrase":"go to university"},{"phrase":"university student"},{"phrase":"university degree"},{"phrase":"university library"}]',NULL,'/ˌjuːnɪˈvɜːrsəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unive/university__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(942,'ngsl-2-16',28,'easily','dễ dàng','adverb','[{"en":"He gets angry very easily when he is tired.","vi":"Anh ấy rất dễ nổi nóng khi mệt."},{"en":"She passed the exam easily and got the highest score.","vi":"Cô ấy dễ dàng vượt qua kỳ thi và đạt điểm cao nhất."},{"en":"You can easily make this dish at home in twenty minutes.","vi":"Bạn có thể dễ dàng làm món này ở nhà trong hai mươi phút."}]','[{"phrase":"can easily"},{"phrase":"very easily"},{"phrase":"easily accessible"}]',NULL,'/ˈiːzəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/easil/easily__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(943,'ngsl-2-16',29,'agency','đại lý; cơ quan','noun','[{"en":"We booked our trip through a travel agency.","vi":"Chúng tôi đặt chuyến đi qua một đại lý du lịch."},{"en":"She works for an advertising agency in the city center.","vi":"Cô ấy làm việc cho một công ty quảng cáo ở trung tâm thành phố."},{"en":"A government agency is checking the safety of the water.","vi":"Một cơ quan chính phủ đang kiểm tra độ an toàn của nguồn nước."}]','[{"phrase":"travel agency"},{"phrase":"advertising agency"},{"phrase":"government agency"},{"phrase":"employment agency"}]',NULL,'/ˈeɪdʒənsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/agenc/agency__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(944,'ngsl-2-17',1,'dollar','đô la','noun','[{"en":"This shirt only cost me ten dollars at the market.","vi":"Chiếc áo này tôi mua ở chợ chỉ mất mười đô la."},{"en":"Can you lend me twenty dollars until Friday?","vi":"Bạn cho tôi mượn hai mươi đô la đến thứ Sáu được không?"},{"en":"They spent millions of dollars on the new hospital.","vi":"Họ đã chi hàng triệu đô la cho bệnh viện mới."}]','[{"phrase":"ten dollars"},{"phrase":"a million dollars"},{"phrase":"the US dollar"}]',NULL,'/ˈdɑːlər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dol/dolla/dollar__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(945,'ngsl-2-17',2,'garden','vườn','noun','[{"en":"My grandmother grows tomatoes and herbs in her garden.","vi":"Bà tôi trồng cà chua và rau thơm trong vườn."},{"en":"The children love playing in the garden after school.","vi":"Bọn trẻ rất thích chơi trong vườn sau giờ học."},{"en":"We had lunch in a small garden behind the restaurant.","vi":"Chúng tôi ăn trưa trong một khu vườn nhỏ phía sau nhà hàng."}]','[{"phrase":"vegetable garden"},{"phrase":"flower garden"},{"phrase":"in the garden"}]',NULL,'/ˈɡɑːrdn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gar/garde/garden__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(946,'ngsl-2-17',3,'fix','sửa chữa; ấn định','verb','[{"en":"My brother fixed my bike in less than an hour.","vi":"Anh trai tôi sửa xe đạp cho tôi chưa đến một tiếng."},{"en":"Can someone fix the printer before the meeting starts?","vi":"Có ai sửa được máy in trước khi cuộc họp bắt đầu không?"},{"en":"Let''s fix a date for the next team meeting.","vi":"Chúng ta hãy ấn định ngày cho buổi họp nhóm tới nhé."}]','[{"phrase":"fix a problem"},{"phrase":"fix a date"},{"phrase":"fix a price"}]',NULL,'/fɪks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fix/fix__/fix__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(947,'ngsl-2-17',4,'ahead','phía trước; trước (thời gian)','adverb','[{"en":"Go straight ahead and turn left at the bank.","vi":"Đi thẳng về phía trước rồi rẽ trái ở ngân hàng."},{"en":"We need to plan ahead for the holiday season.","vi":"Chúng ta cần lên kế hoạch trước cho mùa lễ."},{"en":"Our team finished the project two days ahead of schedule.","vi":"Nhóm chúng tôi hoàn thành dự án sớm hơn kế hoạch hai ngày."}]','[{"phrase":"go ahead"},{"phrase":"plan ahead"},{"phrase":"ahead of schedule"},{"phrase":"straight ahead"}]',NULL,'/əˈhed/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ahe/ahead/ahead__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(948,'ngsl-2-17',5,'cross','băng qua; bắt chéo','verb','[{"en":"Always look both ways before you cross the street.","vi":"Luôn nhìn cả hai phía trước khi băng qua đường."},{"en":"It took us three hours to cross the border.","vi":"Chúng tôi mất ba tiếng để qua biên giới."},{"en":"He sat down on the sofa and crossed his legs.","vi":"Anh ấy ngồi xuống ghế sofa và bắt chéo chân."}]','[{"phrase":"cross the street"},{"phrase":"cross the road"},{"phrase":"cross the border"},{"phrase":"cross your legs"}]',NULL,'/krɔːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cro/cross/cross__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(949,'ngsl-2-17',6,'yeah','ừ; vâng','exclamation','[{"en":"Yeah, I think that''s a really good idea.","vi":"Ừ, tôi nghĩ đó là một ý rất hay."},{"en":"Yeah, I''ll be there around eight o''clock tonight.","vi":"Vâng, tối nay khoảng tám giờ tôi sẽ có mặt."},{"en":"Oh yeah, I forgot to tell you about the party.","vi":"À ừ, tôi quên kể với bạn về bữa tiệc."}]','[{"phrase":"oh yeah"},{"phrase":"yeah, sure"},{"phrase":"yeah, right"}]','Cách nói thân mật của "yes"','/jeə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yea/yeah_/yeah__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(950,'ngsl-2-17',7,'candidate','ứng viên; thí sinh','noun','[{"en":"We interviewed five candidates for the manager position.","vi":"Chúng tôi đã phỏng vấn năm ứng viên cho vị trí quản lý."},{"en":"She is the strongest candidate for the job.","vi":"Cô ấy là ứng viên sáng giá nhất cho công việc này."},{"en":"Candidates must answer all the questions on the exam paper.","vi":"Thí sinh phải trả lời tất cả các câu hỏi trong đề thi."}]','[{"phrase":"strong candidate"},{"phrase":"candidate for"},{"phrase":"suitable candidate"},{"phrase":"job candidate"}]',NULL,'/ˈkændɪdət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/can/candi/candidate__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(951,'ngsl-2-17',8,'weight','cân nặng; trọng lượng','noun','[{"en":"He has lost a lot of weight since last summer.","vi":"Anh ấy đã giảm cân nhiều từ mùa hè năm ngoái."},{"en":"What is the maximum weight for checked baggage?","vi":"Trọng lượng tối đa cho hành lý ký gửi là bao nhiêu?"},{"en":"Regular exercise can help you keep your weight under control.","vi":"Tập thể dục đều đặn có thể giúp bạn kiểm soát cân nặng."}]','[{"phrase":"lose weight"},{"phrase":"gain weight"},{"phrase":"put on weight"},{"phrase":"maximum weight"}]',NULL,'/weɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wei/weigh/weight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(952,'ngsl-2-17',9,'legal','hợp pháp; (thuộc) pháp lý','adjective','[{"en":"Is it legal to park on this side of the street?","vi":"Đỗ xe ở bên này đường có hợp pháp không?"},{"en":"The company hired a lawyer to get legal advice.","vi":"Công ty đã thuê luật sư để được tư vấn pháp lý."},{"en":"They decided to take legal action against the builder.","vi":"Họ quyết định khởi kiện người thợ xây."}]','[{"phrase":"legal advice"},{"phrase":"legal action"},{"phrase":"legal system"},{"phrase":"perfectly legal"}]','legal ≠ illegal (bất hợp pháp)','/ˈliːɡl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legal/legal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(953,'ngsl-2-17',10,'proposal','đề xuất; lời cầu hôn','noun','[{"en":"The manager accepted our proposal for a shorter workweek.","vi":"Quản lý đã chấp nhận đề xuất rút ngắn tuần làm việc của chúng tôi."},{"en":"Please send me your project proposal by Friday.","vi":"Vui lòng gửi cho tôi bản đề xuất dự án trước thứ Sáu."},{"en":"She said yes to his marriage proposal on the beach.","vi":"Cô ấy đã nhận lời cầu hôn của anh ấy trên bãi biển."}]','[{"phrase":"accept a proposal"},{"phrase":"reject a proposal"},{"phrase":"marriage proposal"},{"phrase":"proposal for"}]',NULL,'/prəˈpəʊzl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/proposal__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(954,'ngsl-2-17',11,'version','phiên bản','noun','[{"en":"Have you downloaded the latest version of the app?","vi":"Bạn đã tải phiên bản mới nhất của ứng dụng chưa?"},{"en":"I prefer the original version of this song.","vi":"Tôi thích phiên bản gốc của bài hát này hơn."},{"en":"My sister told me a different version of the story.","vi":"Chị tôi kể cho tôi một phiên bản khác của câu chuyện."}]','[{"phrase":"latest version"},{"phrase":"new version"},{"phrase":"original version"},{"phrase":"different version"}]',NULL,'/ˈvɜːrʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/versi/version__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(955,'ngsl-2-17',12,'conversation','cuộc trò chuyện; hội thoại','noun','[{"en":"We had a long conversation about our plans for the future.","vi":"Chúng tôi đã có một cuộc trò chuyện dài về dự định tương lai."},{"en":"She tried to start a conversation with the new student.","vi":"Cô ấy cố gắng bắt chuyện với bạn học sinh mới."},{"en":"Practicing conversation with friends improved my English a lot.","vi":"Luyện hội thoại với bạn bè đã giúp tiếng Anh của tôi tiến bộ nhiều."}]','[{"phrase":"have a conversation"},{"phrase":"start a conversation"},{"phrase":"phone conversation"},{"phrase":"conversation with"}]',NULL,'/ˌkɑːnvərˈseɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconversation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(956,'ngsl-2-17',13,'somebody','ai đó; người nào đó','pronoun','[{"en":"Somebody left their umbrella in the meeting room.","vi":"Ai đó đã để quên ô trong phòng họp."},{"en":"Can somebody help me carry these boxes upstairs?","vi":"Có ai giúp tôi mang mấy cái thùng này lên lầu không?"},{"en":"I need to talk to somebody about this problem.","vi":"Tôi cần nói chuyện với ai đó về vấn đề này."}]','[{"phrase":"somebody else"},{"phrase":"talk to somebody"},{"phrase":"somebody who"}]','= someone','/ˈsʌmbədi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/someb/somebody__us_3_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(957,'ngsl-2-17',14,'pound','bảng Anh; pao','noun','[{"en":"The train ticket to London cost me ten pounds.","vi":"Vé tàu đi London tốn của tôi mười bảng Anh."},{"en":"I bought two pounds of apples at the market.","vi":"Tôi đã mua hai pao táo ở chợ."},{"en":"The baby weighed seven pounds when she was born.","vi":"Em bé nặng bảy pao lúc mới sinh."}]','[{"phrase":"ten pounds"},{"phrase":"a pound of"},{"phrase":"the British pound"}]','1 pound (pao) ≈ 0,45 kg','/paʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pou/pound/pound__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(958,'ngsl-2-17',15,'magazine','tạp chí','noun','[{"en":"She buys a fashion magazine every month.","vi":"Tháng nào cô ấy cũng mua một cuốn tạp chí thời trang."},{"en":"My photo appeared on the cover of a travel magazine.","vi":"Ảnh của tôi xuất hiện trên bìa một tạp chí du lịch."},{"en":"There were some old magazines on the table in the waiting room.","vi":"Có vài cuốn tạp chí cũ trên bàn trong phòng chờ."}]','[{"phrase":"fashion magazine"},{"phrase":"magazine article"},{"phrase":"magazine cover"}]',NULL,'/ˈmæɡəziːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mag/magaz/magazine__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(959,'ngsl-2-17',16,'shape','hình dạng; thể trạng','noun','[{"en":"The cake was made in the shape of a heart.","vi":"Chiếc bánh được làm theo hình trái tim."},{"en":"What shape is the table, round or square?","vi":"Cái bàn có hình gì, tròn hay vuông?"},{"en":"My father is in good shape for his age.","vi":"Bố tôi có thể trạng tốt so với tuổi của ông."}]','[{"phrase":"in the shape of"},{"phrase":"in good shape"},{"phrase":"get in shape"},{"phrase":"round shape"}]',NULL,'/ʃeɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shape/shape__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(960,'ngsl-2-17',17,'sea','biển','noun','[{"en":"Our hotel room had a beautiful view of the sea.","vi":"Phòng khách sạn của chúng tôi nhìn ra biển rất đẹp."},{"en":"The children swam in the sea all afternoon.","vi":"Bọn trẻ bơi ở biển suốt cả buổi chiều."},{"en":"Most of the fish we eat comes from the sea.","vi":"Phần lớn cá chúng ta ăn đến từ biển."}]','[{"phrase":"by the sea"},{"phrase":"in the sea"},{"phrase":"sea level"},{"phrase":"at sea"}]',NULL,'/siː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/sea__/sea__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(961,'ngsl-2-17',18,'immediately','ngay lập tức','adverb','[{"en":"Please call me immediately if you have any problems.","vi":"Hãy gọi cho tôi ngay nếu bạn gặp bất kỳ vấn đề gì."},{"en":"She recognized her old teacher immediately when he walked in.","vi":"Cô ấy nhận ra thầy giáo cũ ngay khi thầy bước vào."},{"en":"The pain went away almost immediately after I took the medicine.","vi":"Cơn đau hết gần như ngay lập tức sau khi tôi uống thuốc."}]','[{"phrase":"almost immediately"},{"phrase":"immediately after"},{"phrase":"leave immediately"}]',NULL,'/ɪˈmiːdiətli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immed/immediately__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(962,'ngsl-2-17',19,'welcome','chào đón; hoan nghênh','verb','[{"en":"Our hosts warmly welcomed us with hot tea.","vi":"Chủ nhà nồng nhiệt chào đón chúng tôi bằng trà nóng."},{"en":"The school welcomes new students every September.","vi":"Trường chào đón học sinh mới vào mỗi tháng Chín."},{"en":"We welcome any ideas that can improve our service.","vi":"Chúng tôi hoan nghênh mọi ý tưởng giúp cải thiện dịch vụ."}]','[{"phrase":"warmly welcome"},{"phrase":"welcome guests"},{"phrase":"welcome the idea"}]','You''re welcome = Không có gì (đáp lời cảm ơn)','/ˈwelkəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/welco/welcome__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(963,'ngsl-2-17',20,'smile','mỉm cười','verb','[{"en":"The baby smiled when she saw her mother.","vi":"Em bé mỉm cười khi nhìn thấy mẹ."},{"en":"He always smiles at me when we meet in the hallway.","vi":"Anh ấy luôn mỉm cười với tôi khi chúng tôi gặp nhau ở hành lang."},{"en":"Try to smile more during your job interview.","vi":"Hãy cố gắng mỉm cười nhiều hơn trong buổi phỏng vấn xin việc."}]','[{"phrase":"smile at"},{"phrase":"smile back"},{"phrase":"smile broadly"}]',NULL,'/smaɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/smi/smile/smile__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(964,'ngsl-2-17',21,'communication','sự giao tiếp; liên lạc','noun','[{"en":"Good communication is important in any relationship.","vi":"Giao tiếp tốt rất quan trọng trong bất kỳ mối quan hệ nào."},{"en":"Our team uses email for most communication with clients.","vi":"Nhóm chúng tôi dùng email cho hầu hết việc liên lạc với khách hàng."},{"en":"Communication was difficult because nobody spoke the local language.","vi":"Việc giao tiếp rất khó khăn vì không ai nói được tiếng địa phương."}]','[{"phrase":"good communication"},{"phrase":"communication skills"},{"phrase":"lack of communication"},{"phrase":"means of communication"}]',NULL,'/kəˌmjuːnɪˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/communication__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(965,'ngsl-2-17',22,'agent','đại lý; người môi giới','noun','[{"en":"Our travel agent booked the flights and the hotel.","vi":"Đại lý du lịch đã đặt vé máy bay và khách sạn cho chúng tôi."},{"en":"We found this apartment through a real estate agent.","vi":"Chúng tôi tìm được căn hộ này qua một người môi giới bất động sản."},{"en":"The insurance agent explained every part of the contract to us.","vi":"Đại lý bảo hiểm đã giải thích cho chúng tôi từng phần của hợp đồng."}]','[{"phrase":"travel agent"},{"phrase":"real estate agent"},{"phrase":"insurance agent"}]',NULL,'/ˈeɪdʒənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/agent/agent__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(966,'ngsl-2-17',23,'traditional','truyền thống','adjective','[{"en":"We ate traditional food at the Lunar New Year festival.","vi":"Chúng tôi ăn các món truyền thống trong dịp Tết Nguyên đán."},{"en":"She wore a traditional dress to her sister''s wedding.","vi":"Cô ấy mặc trang phục truyền thống đến dự đám cưới của chị gái."},{"en":"Some parents still prefer traditional ways of teaching children.","vi":"Một số phụ huynh vẫn thích cách dạy con truyền thống hơn."}]','[{"phrase":"traditional food"},{"phrase":"traditional dress"},{"phrase":"traditional music"},{"phrase":"traditional way"}]',NULL,'/trəˈdɪʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/tradi/traditional__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(967,'ngsl-2-17',24,'replace','thay thế; thay','verb','[{"en":"I need to replace the battery in my watch.","vi":"Tôi cần thay pin cho đồng hồ."},{"en":"Many workers worry that machines will replace them.","vi":"Nhiều công nhân lo rằng máy móc sẽ thay thế họ."},{"en":"The old bridge was replaced by a new one.","vi":"Cây cầu cũ đã được thay bằng một cây cầu mới."}]','[{"phrase":"replace the battery"},{"phrase":"replace with"},{"phrase":"completely replace"}]','replace A with B = thay A bằng B','/rɪˈpleɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repla/replace__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(968,'ngsl-2-17',25,'judge','thẩm phán; giám khảo','noun','[{"en":"The judge listened carefully to both sides before deciding.","vi":"Thẩm phán lắng nghe kỹ cả hai bên trước khi quyết định."},{"en":"She was one of the judges in the singing competition.","vi":"Cô ấy là một trong những giám khảo của cuộc thi hát."},{"en":"A panel of judges will choose the winner next week.","vi":"Một hội đồng giám khảo sẽ chọn ra người chiến thắng vào tuần sau."}]','[{"phrase":"panel of judges"},{"phrase":"the judge''s decision"}]','Động từ judge = đánh giá, phán xét','/dʒʌdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jud/judge/judge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(969,'ngsl-2-17',26,'suddenly','đột nhiên; bỗng nhiên','adverb','[{"en":"Suddenly, all the lights in the building went out.","vi":"Đột nhiên, tất cả đèn trong tòa nhà đều tắt."},{"en":"It suddenly started raining while we were walking home.","vi":"Trời bỗng đổ mưa khi chúng tôi đang đi bộ về nhà."},{"en":"The car in front of us suddenly stopped.","vi":"Chiếc xe phía trước chúng tôi đột nhiên dừng lại."}]','[{"phrase":"suddenly stop"},{"phrase":"suddenly realize"},{"phrase":"suddenly appear"}]',NULL,'/ˈsʌdənli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sud/sudde/suddenly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(970,'ngsl-2-17',27,'generation','thế hệ','noun','[{"en":"Three generations of my family live in the same house.","vi":"Ba thế hệ trong gia đình tôi sống chung một nhà."},{"en":"The younger generation spends a lot of time online.","vi":"Thế hệ trẻ dành rất nhiều thời gian trên mạng."},{"en":"This recipe has been passed down from generation to generation.","vi":"Công thức này đã được truyền từ thế hệ này sang thế hệ khác."}]','[{"phrase":"younger generation"},{"phrase":"older generation"},{"phrase":"future generations"},{"phrase":"from generation to generation"}]',NULL,'/ˌdʒenəˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(971,'ngsl-2-17',28,'estimate','ước tính; ước lượng','verb','[{"en":"We estimate that the repairs will cost about five hundred dollars.","vi":"Chúng tôi ước tính việc sửa chữa sẽ tốn khoảng năm trăm đô la."},{"en":"Can you estimate the cost of painting the whole house?","vi":"Bạn có thể ước tính chi phí sơn cả ngôi nhà không?"},{"en":"Experts estimated the crowd at over ten thousand people.","vi":"Các chuyên gia ước tính đám đông có hơn mười nghìn người."}]','[{"phrase":"estimate the cost"},{"phrase":"roughly estimate"},{"phrase":"it is estimated that"}]','Cũng là danh từ: an estimate = con số ước tính','/ˈestɪmeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estim/estimate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(972,'ngsl-2-17',29,'favorite','yêu thích nhất','adjective','[{"en":"What is your favorite movie of all time?","vi":"Bộ phim bạn thích nhất mọi thời đại là phim gì?"},{"en":"Pizza has always been my son''s favorite food.","vi":"Pizza luôn là món ăn con trai tôi thích nhất."},{"en":"This little cafe is our favorite place to meet on weekends.","vi":"Quán cà phê nhỏ này là nơi chúng tôi thích gặp nhau nhất vào cuối tuần."}]','[{"phrase":"favorite food"},{"phrase":"favorite place"},{"phrase":"favorite movie"},{"phrase":"all-time favorite"}]','Anh: favourite · Mỹ: favorite','/ˈfeɪvərɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(973,'ngsl-3-01',1,'difficulty','khó khăn; sự khó khăn','noun','[{"en":"Many students have difficulty with English pronunciation at first.","vi":"Lúc đầu, nhiều học sinh gặp khó khăn với việc phát âm tiếng Anh."},{"en":"We found the hotel without any difficulty.","vi":"Chúng tôi tìm thấy khách sạn mà không gặp khó khăn gì."},{"en":"The company is having financial difficulties this year.","vi":"Năm nay công ty đang gặp khó khăn về tài chính."}]','[{"phrase":"have difficulty"},{"phrase":"without difficulty"},{"phrase":"financial difficulties"},{"phrase":"great difficulty"}]','have difficulty (in) doing sth: gặp khó khăn khi làm gì','/ˈdɪfɪkəlti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffi/difficulty__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(974,'ngsl-3-01',2,'purchase','mua; mua sắm','verb','[{"en":"You can purchase tickets online or at the station.","vi":"Bạn có thể mua vé trực tuyến hoặc tại nhà ga."},{"en":"They purchased their first home last year.","vi":"Năm ngoái họ đã mua căn nhà đầu tiên."},{"en":"Please keep your receipt after you purchase the item.","vi":"Vui lòng giữ lại hóa đơn sau khi mua hàng."}]','[{"phrase":"purchase tickets"},{"phrase":"purchase goods"},{"phrase":"purchase a home"}]','trang trọng hơn buy','/ˈpɜːrtʃəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/purch/purchase__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(975,'ngsl-3-01',3,'shoot','bắn; sút (bóng); quay (phim), chụp (ảnh)','verb','[{"en":"She shot an arrow and hit the center of the target.","vi":"Cô ấy bắn một mũi tên và trúng ngay giữa bia."},{"en":"He shot from far away and scored a great goal.","vi":"Anh ấy sút từ xa và ghi một bàn thắng đẹp."},{"en":"They shot the whole movie in just six weeks.","vi":"Họ quay toàn bộ bộ phim chỉ trong sáu tuần."}]','[{"phrase":"shoot a movie"},{"phrase":"shoot a video"},{"phrase":"shoot an arrow"}]','shoot – shot – shot','/ʃuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shoot/shoot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(976,'ngsl-3-01',4,'announce','thông báo; công bố','verb','[{"en":"The airline announced that the flight was delayed.","vi":"Hãng hàng không thông báo rằng chuyến bay bị hoãn."},{"en":"They will announce the winners on Friday evening.","vi":"Họ sẽ công bố những người thắng cuộc vào tối thứ Sáu."},{"en":"My sister announced her engagement at dinner last night.","vi":"Chị tôi thông báo tin đính hôn trong bữa tối hôm qua."}]','[{"phrase":"announce the winners"},{"phrase":"officially announce"},{"phrase":"announce plans"}]',NULL,'/əˈnaʊns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annou/announce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(977,'ngsl-3-01',5,'unless','trừ khi; nếu không','conjunction','[{"en":"You can''t enter the building unless you have a pass.","vi":"Bạn không thể vào tòa nhà trừ khi có thẻ ra vào."},{"en":"Unless it rains, we''ll have lunch in the park.","vi":"Nếu trời không mưa, chúng ta sẽ ăn trưa trong công viên."},{"en":"Don''t wake me up unless it''s really necessary.","vi":"Đừng đánh thức tôi dậy trừ khi thật sự cần thiết."}]','[{"phrase":"unless necessary"},{"phrase":"unless otherwise stated"}]','unless = if … not; không dùng will trong mệnh đề unless','/ənˈles/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unl/unles/unless__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(978,'ngsl-3-01',6,'independent','độc lập; tự lập','adjective','[{"en":"My grandmother is ninety but still very independent.","vi":"Bà tôi đã chín mươi tuổi nhưng vẫn rất tự lập."},{"en":"We asked an independent expert to check the report.","vi":"Chúng tôi nhờ một chuyên gia độc lập kiểm tra bản báo cáo."},{"en":"My son wants to be financially independent before he turns twenty-five.","vi":"Con trai tôi muốn tự lập về tài chính trước tuổi hai mươi lăm."}]','[{"phrase":"financially independent"},{"phrase":"independent of"},{"phrase":"completely independent"}]','independent of sb/sth: không phụ thuộc vào ai/cái gì','/ˌɪndɪˈpendənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indep/independent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(979,'ngsl-3-01',7,'recommend','giới thiệu; khuyên','verb','[{"en":"Can you recommend a good restaurant near the hotel?","vi":"Bạn có thể giới thiệu một nhà hàng ngon gần khách sạn không?"},{"en":"The doctor recommended that I get more sleep.","vi":"Bác sĩ khuyên tôi nên ngủ nhiều hơn."},{"en":"I highly recommend this book to anyone learning English.","vi":"Tôi rất muốn giới thiệu cuốn sách này cho bất kỳ ai đang học tiếng Anh."}]','[{"phrase":"highly recommend"},{"phrase":"strongly recommend"}]','recommend (that) sb do sth / recommend doing sth','/ˌrekəˈmend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recom/recommend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(980,'ngsl-3-01',8,'survey','cuộc khảo sát','noun','[{"en":"We carried out a survey of 500 customers last month.","vi":"Tháng trước chúng tôi đã thực hiện một cuộc khảo sát với 500 khách hàng."},{"en":"According to a recent survey, most people prefer working from home.","vi":"Theo một cuộc khảo sát gần đây, hầu hết mọi người thích làm việc tại nhà."},{"en":"Please take a few minutes to complete our survey.","vi":"Vui lòng dành vài phút để hoàn thành bản khảo sát của chúng tôi."}]','[{"phrase":"carry out a survey"},{"phrase":"recent survey"},{"phrase":"complete a survey"}]',NULL,'/ˈsɜːrveɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surve/survey__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(981,'ngsl-3-01',9,'majority','phần lớn; đa số','noun','[{"en":"The majority of students live near the campus.","vi":"Phần lớn sinh viên sống gần trường."},{"en":"The vast majority of our customers are very happy with the service.","vi":"Đại đa số khách hàng của chúng tôi rất hài lòng với dịch vụ."},{"en":"In our class, girls are in the majority.","vi":"Trong lớp chúng tôi, con gái chiếm đa số."}]','[{"phrase":"the majority of"},{"phrase":"vast majority"},{"phrase":"in the majority"}]','majority (đa số) ≠ minority (thiểu số)','/məˈdʒɔːrəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/maj/major/majority__us_3_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(982,'ngsl-3-01',10,'stick','dán; dính; bám theo (kế hoạch)','verb','[{"en":"She stuck a note on the fridge door.","vi":"Cô ấy dán một mẩu giấy nhắn lên cửa tủ lạnh."},{"en":"The rice stuck to the bottom of the pot.","vi":"Cơm bị dính vào đáy nồi."},{"en":"Let''s stick to the plan and leave at six.","vi":"Cứ theo đúng kế hoạch và đi lúc sáu giờ nhé."}]','[{"phrase":"stick to"},{"phrase":"stick to the plan"},{"phrase":"stick together"},{"phrase":"get stuck"}]','stick – stuck – stuck','/stɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/stick/stick__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(983,'ngsl-3-01',11,'request','yêu cầu; lời đề nghị','noun','[{"en":"The manager agreed to my request for a day off.","vi":"Quản lý đã đồng ý với đề nghị xin nghỉ một ngày của tôi."},{"en":"Free samples are available on request at the front desk.","vi":"Mẫu thử miễn phí được cung cấp tại quầy lễ tân khi có yêu cầu."},{"en":"We received hundreds of requests for more information.","vi":"Chúng tôi nhận được hàng trăm yêu cầu cung cấp thêm thông tin."}]','[{"phrase":"make a request"},{"phrase":"request for"},{"phrase":"on request"},{"phrase":"receive a request"}]','request for sth','/rɪˈkwest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/reque/request__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(984,'ngsl-3-01',12,'rich','giàu có; giàu (chất gì); phong phú','adjective','[{"en":"He dreamed of becoming rich and buying a big house.","vi":"Anh ấy mơ trở nên giàu có và mua một ngôi nhà lớn."},{"en":"Oranges and lemons are rich in vitamin C.","vi":"Cam và chanh giàu vitamin C."},{"en":"This city has a rich history and many old buildings.","vi":"Thành phố này có bề dày lịch sử và nhiều tòa nhà cổ."}]','[{"phrase":"rich in"},{"phrase":"rich history"},{"phrase":"get rich"}]',NULL,'/rɪtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ric/rich_/rich__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(985,'ngsl-3-01',13,'wind','gió','noun','[{"en":"The wind blew the leaves across the yard.","vi":"Gió thổi lá bay khắp sân."},{"en":"The wind was so cold that we went back inside.","vi":"Gió lạnh đến mức chúng tôi phải quay vào trong."},{"en":"Strong winds are expected along the coast tonight.","vi":"Dự báo tối nay sẽ có gió mạnh dọc bờ biển."}]','[{"phrase":"strong wind"},{"phrase":"cold wind"},{"phrase":"the wind blows"}]','wind (n) /wɪnd/ gió ≠ wind (v) /waɪnd/ quấn, lên dây','/wɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/wind_/wind__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(986,'ngsl-3-01',14,'none','không ai; không cái nào; không chút nào','pronoun','[{"en":"I bought three cakes, but there are none left now.","vi":"Tôi đã mua ba cái bánh, nhưng giờ chẳng còn cái nào."},{"en":"None of my friends could come to the party.","vi":"Không ai trong số bạn bè tôi đến dự bữa tiệc được."},{"en":"We needed more milk, but the shop had none.","vi":"Chúng tôi cần thêm sữa, nhưng cửa hàng lại hết sạch."}]','[{"phrase":"none of"},{"phrase":"none left"},{"phrase":"none at all"}]','none of + danh từ số nhiều / không đếm được','/nʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/non/none_/none__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(987,'ngsl-3-01',15,'exchange','trao đổi; đổi (tiền, hàng)','verb','[{"en":"We exchanged phone numbers before leaving the party.","vi":"Chúng tôi trao đổi số điện thoại trước khi rời bữa tiệc."},{"en":"Can I exchange this shirt for a smaller size?","vi":"Tôi có thể đổi chiếc áo này lấy cỡ nhỏ hơn không?"},{"en":"You can exchange money at the airport, but the rate is poor.","vi":"Bạn có thể đổi tiền ở sân bay, nhưng tỷ giá không tốt."}]','[{"phrase":"exchange money"},{"phrase":"exchange ideas"},{"phrase":"exchange information"},{"phrase":"exchange gifts"}]','exchange A for B: đổi A lấy B','/ɪksˈtʃeɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excha/exchange__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(988,'ngsl-3-01',16,'budget','ngân sách','noun','[{"en":"We''re planning a trip on a tight budget this summer.","vi":"Hè này chúng tôi dự định đi du lịch với ngân sách eo hẹp."},{"en":"The project went over budget by twenty percent.","vi":"Dự án đã vượt ngân sách hai mươi phần trăm."},{"en":"Our school has a small budget for new books.","vi":"Trường chúng tôi có một khoản ngân sách nhỏ để mua sách mới."}]','[{"phrase":"tight budget"},{"phrase":"over budget"},{"phrase":"on a budget"},{"phrase":"budget for"}]',NULL,'/ˈbʌdʒɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bud/budge/budget__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(989,'ngsl-3-01',17,'famous','nổi tiếng','adjective','[{"en":"This town is famous for its fresh seafood.","vi":"Thị trấn này nổi tiếng với hải sản tươi ngon."},{"en":"She wants to become a famous singer one day.","vi":"Cô ấy muốn một ngày nào đó trở thành ca sĩ nổi tiếng."},{"en":"We visited the famous bridge on our first day in the city.","vi":"Chúng tôi đã tham quan cây cầu nổi tiếng vào ngày đầu tiên ở thành phố."}]','[{"phrase":"famous for"},{"phrase":"world-famous"},{"phrase":"become famous"}]','famous for sth: nổi tiếng về cái gì','/ˈfeɪməs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fam/famou/famous__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(990,'ngsl-3-01',18,'blood','máu','noun','[{"en":"I have to go for a blood test tomorrow morning.","vi":"Sáng mai tôi phải đi xét nghiệm máu."},{"en":"Regular exercise can help lower your blood pressure.","vi":"Tập thể dục đều đặn có thể giúp giảm huyết áp."},{"en":"Hospitals always need more people to give blood.","vi":"Các bệnh viện luôn cần thêm người hiến máu."}]','[{"phrase":"blood test"},{"phrase":"blood pressure"},{"phrase":"give blood"},{"phrase":"blood type"}]','không đếm được','/blʌd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/blood/blood__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(991,'ngsl-3-01',19,'appropriate','phù hợp; thích hợp','adjective','[{"en":"Jeans are not appropriate for a job interview.","vi":"Quần jeans không phù hợp để mặc đi phỏng vấn xin việc."},{"en":"Please wait for an appropriate time to ask questions.","vi":"Vui lòng chờ thời điểm thích hợp để đặt câu hỏi."},{"en":"Is this movie appropriate for young children?","vi":"Bộ phim này có phù hợp với trẻ nhỏ không?"}]','[{"phrase":"appropriate for"},{"phrase":"appropriate time"},{"phrase":"appropriate action"}]','trái nghĩa: inappropriate','/əˈprəʊpriət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/appropriate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(992,'ngsl-3-01',20,'block','khối; tòa nhà; dãy nhà (giữa hai con phố)','noun','[{"en":"The post office is two blocks from here.","vi":"Bưu điện cách đây hai dãy nhà."},{"en":"They live in a tall apartment block near the river.","vi":"Họ sống trong một tòa chung cư cao tầng gần bờ sông."},{"en":"The children built a tower with wooden blocks.","vi":"Bọn trẻ xếp một tòa tháp bằng những khối gỗ."}]','[{"phrase":"apartment block"},{"phrase":"around the block"},{"phrase":"block of ice"}]',NULL,'/blɑːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/block/block__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(993,'ngsl-3-01',21,'warm','ấm; ấm áp; nồng nhiệt','adjective','[{"en":"Wear a warm coat because it''s cold outside.","vi":"Hãy mặc áo khoác ấm vì ngoài trời lạnh."},{"en":"The weather is warm enough to swim today.","vi":"Hôm nay thời tiết đủ ấm để đi bơi."},{"en":"Our hosts gave us a very warm welcome.","vi":"Chủ nhà đã chào đón chúng tôi rất nồng nhiệt."}]','[{"phrase":"warm weather"},{"phrase":"warm welcome"},{"phrase":"warm clothes"},{"phrase":"keep warm"}]',NULL,'/wɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/war/warm_/warm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(994,'ngsl-3-01',22,'count','đếm; tính; có giá trị, quan trọng','verb','[{"en":"My little son can already count to one hundred.","vi":"Con trai nhỏ của tôi đã biết đếm đến một trăm."},{"en":"She counted the money twice before paying.","vi":"Cô ấy đếm tiền hai lần trước khi trả."},{"en":"Every minute counts when you''re running late for a flight.","vi":"Từng phút đều quan trọng khi bạn sắp trễ chuyến bay."}]','[{"phrase":"count to ten"},{"phrase":"count money"},{"phrase":"count on"},{"phrase":"every minute counts"}]','count on sb: trông cậy vào ai','/kaʊnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/count__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(995,'ngsl-3-01',23,'scene','cảnh (phim, kịch); hiện trường; khung cảnh','noun','[{"en":"My favorite scene in the movie is at the very end.","vi":"Cảnh tôi thích nhất trong phim nằm ở ngay cuối."},{"en":"The police arrived at the scene within minutes.","vi":"Cảnh sát đã đến hiện trường chỉ trong vài phút."},{"en":"We sat on the hill and enjoyed the peaceful scene below.","vi":"Chúng tôi ngồi trên đồi và ngắm khung cảnh yên bình bên dưới."}]','[{"phrase":"at the scene"},{"phrase":"final scene"},{"phrase":"opening scene"},{"phrase":"behind the scenes"}]',NULL,'/siːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sce/scene/scene__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(996,'ngsl-3-01',24,'writer','nhà văn; người viết','noun','[{"en":"She is a successful writer of children''s books.","vi":"Cô ấy là một nhà văn thành công chuyên viết sách thiếu nhi."},{"en":"My brother wants to be a writer when he grows up.","vi":"Em trai tôi muốn trở thành nhà văn khi lớn lên."},{"en":"The writer of this article clearly knows a lot about cooking.","vi":"Người viết bài báo này rõ ràng rất am hiểu về nấu ăn."}]','[{"phrase":"famous writer"},{"phrase":"successful writer"},{"phrase":"children''s writer"}]',NULL,'/ˈraɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wri/write/writer__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(997,'ngsl-3-01',25,'content','nội dung','noun','[{"en":"The content of the course is useful for beginners.","vi":"Nội dung khóa học hữu ích cho người mới bắt đầu."},{"en":"Parents should check the content of the games their kids play.","vi":"Cha mẹ nên kiểm tra nội dung các trò chơi mà con mình chơi."},{"en":"The company creates video content for social media.","vi":"Công ty sản xuất nội dung video cho mạng xã hội."}]','[{"phrase":"the content of"},{"phrase":"online content"},{"phrase":"video content"}]','content (n) nội dung ≠ content (adj) hài lòng – khác trọng âm','/ˈkɑːntent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(998,'ngsl-3-01',26,'prevent','ngăn chặn; phòng ngừa','verb','[{"en":"Washing your hands often can prevent many illnesses.","vi":"Rửa tay thường xuyên có thể phòng ngừa nhiều bệnh."},{"en":"The heavy rain prevented us from going out.","vi":"Trận mưa lớn đã ngăn chúng tôi ra ngoài."},{"en":"They put up a fence to prevent the dog from escaping.","vi":"Họ dựng hàng rào để ngăn con chó chạy ra ngoài."}]','[{"phrase":"prevent disease"},{"phrase":"prevent accidents"},{"phrase":"help prevent"}]','prevent sb/sth from doing sth','/prɪˈvent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preve/prevent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(999,'ngsl-3-01',27,'safe','an toàn','adjective','[{"en":"Is it safe to swim in this river?","vi":"Bơi ở con sông này có an toàn không?"},{"en":"Keep your passport in a safe place.","vi":"Hãy cất hộ chiếu ở nơi an toàn."},{"en":"The children came home safe and sound after the long trip.","vi":"Bọn trẻ đã về nhà bình an vô sự sau chuyến đi dài."}]','[{"phrase":"safe place"},{"phrase":"safe and sound"},{"phrase":"feel safe"},{"phrase":"safe from"}]',NULL,'/seɪf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/saf/safe_/safe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1000,'ngsl-3-01',28,'invite','mời','verb','[{"en":"They invited us to their wedding in June.","vi":"Họ mời chúng tôi đến dự đám cưới của họ vào tháng Sáu."},{"en":"I''d like to invite you to dinner on Saturday.","vi":"Tôi muốn mời bạn đi ăn tối vào thứ Bảy."},{"en":"Visitors are invited to leave their comments in the book.","vi":"Khách tham quan được mời để lại cảm nghĩ trong cuốn sổ."}]','[{"phrase":"invite someone to dinner"},{"phrase":"invite guests"},{"phrase":"invite friends"}]','invite sb to sth / to do sth','/ɪnˈvaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invit/invite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1001,'ngsl-3-01',29,'mix','trộn; pha; hòa lẫn','verb','[{"en":"Mix the flour and sugar together in a large bowl.","vi":"Trộn đều bột mì và đường trong một cái tô lớn."},{"en":"You can''t mix oil and water, no matter how hard you try.","vi":"Bạn không thể hòa dầu với nước, dù có cố gắng đến đâu."},{"en":"She mixed blue and yellow paint to make green.","vi":"Cô ấy pha sơn xanh dương với vàng để tạo ra màu xanh lá."}]','[{"phrase":"mix together"},{"phrase":"mix with"},{"phrase":"mix well"}]',NULL,'/mɪks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mix/mix__/mix__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1002,'ngsl-3-01',30,'element','yếu tố; thành phần; nguyên tố (hóa học)','noun','[{"en":"Trust is an important element in any relationship.","vi":"Sự tin tưởng là yếu tố quan trọng trong mọi mối quan hệ."},{"en":"Humor is a key element of his teaching style.","vi":"Sự hài hước là yếu tố then chốt trong phong cách giảng dạy của anh ấy."},{"en":"Oxygen is one of the most common elements on Earth.","vi":"Oxy là một trong những nguyên tố phổ biến nhất trên Trái Đất."}]','[{"phrase":"key element"},{"phrase":"important element"},{"phrase":"chemical element"}]',NULL,'/ˈelɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/eleme/element__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1003,'ngsl-3-03',1,'expensive','đắt; đắt tiền','adjective','[{"en":"This restaurant is nice, but the food is too expensive for us.","vi":"Nhà hàng này đẹp nhưng đồ ăn quá đắt đối với chúng tôi."},{"en":"She bought an expensive watch for her father''s birthday.","vi":"Cô ấy đã mua một chiếc đồng hồ đắt tiền nhân dịp sinh nhật bố."},{"en":"Living in a big city can be very expensive.","vi":"Sống ở thành phố lớn có thể rất tốn kém."}]','[{"phrase":"very expensive"},{"phrase":"too expensive"},{"phrase":"expensive car"}]','expensive ≠ cheap (rẻ)','/ɪkˈspensɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expen/expensive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1004,'ngsl-3-03',2,'sample','mẫu; mẫu thử','noun','[{"en":"The nurse took a blood sample from my arm.","vi":"Y tá đã lấy mẫu máu từ cánh tay tôi."},{"en":"The shop was giving out free samples of cheese.","vi":"Cửa hàng đang phát các mẫu phô mai dùng thử miễn phí."},{"en":"Could you send us a sample of your work?","vi":"Bạn có thể gửi cho chúng tôi một mẫu sản phẩm bạn đã làm không?"}]','[{"phrase":"blood sample"},{"phrase":"free sample"},{"phrase":"take a sample"}]',NULL,'/ˈsæmpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sam/sampl/sample__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1005,'ngsl-3-03',3,'sex','giới tính','noun','[{"en":"Please write your name, age and sex on the form.","vi":"Vui lòng ghi tên, tuổi và giới tính vào tờ đơn."},{"en":"They decided not to find out the sex of their baby.","vi":"Họ quyết định không tìm hiểu giới tính của em bé."},{"en":"The survey asked people about their age, sex and income.","vi":"Cuộc khảo sát hỏi mọi người về tuổi, giới tính và thu nhập."}]','[{"phrase":"the opposite sex"},{"phrase":"age and sex"},{"phrase":"both sexes"}]',NULL,'/seks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sex/sex__/sex__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1006,'ngsl-3-03',4,'deliver','giao (hàng); phát biểu, trình bày','verb','[{"en":"The store will deliver your new sofa on Friday morning.","vi":"Cửa hàng sẽ giao chiếc ghế sofa mới cho bạn vào sáng thứ Sáu."},{"en":"Our pizza was delivered in less than thirty minutes.","vi":"Pizza của chúng tôi được giao chưa đến ba mươi phút."},{"en":"She delivered a short speech at her sister''s wedding.","vi":"Cô ấy đã phát biểu ngắn tại đám cưới của chị gái."}]','[{"phrase":"deliver a package"},{"phrase":"deliver a speech"},{"phrase":"deliver mail"}]',NULL,'/dɪˈlɪvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/deliv/deliver__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1007,'ngsl-3-03',5,'video','video; đoạn phim','noun','[{"en":"My son spends hours watching funny videos online.","vi":"Con trai tôi dành hàng giờ xem video hài trên mạng."},{"en":"Did you make a video of the concert last night?","vi":"Tối qua bạn có quay video buổi hòa nhạc không?"},{"en":"We had a video call with our grandparents on Sunday.","vi":"Chúng tôi đã gọi video với ông bà vào Chủ nhật."}]','[{"phrase":"watch a video"},{"phrase":"video call"},{"phrase":"make a video"},{"phrase":"music video"}]',NULL,'/ˈvɪdiəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vid/video/video__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1008,'ngsl-3-03',6,'connection','sự kết nối; mối liên hệ; chuyến nối tiếp','noun','[{"en":"The internet connection in this hotel is really slow.","vi":"Kết nối internet ở khách sạn này thật sự rất chậm."},{"en":"Police found no connection between the two cases.","vi":"Cảnh sát không tìm thấy mối liên hệ nào giữa hai vụ việc."},{"en":"Our first flight was late, so we missed our connection.","vi":"Chuyến bay đầu tiên bị trễ nên chúng tôi lỡ chuyến bay nối tiếp."}]','[{"phrase":"internet connection"},{"phrase":"connection between"},{"phrase":"in connection with"},{"phrase":"miss a connection"}]',NULL,'/kəˈnekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconn/xconnection__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1009,'ngsl-3-03',7,'primary','chính, chủ yếu; (thuộc) tiểu học','adjective','[{"en":"Our primary goal this year is to save money for a house.","vi":"Mục tiêu chính của chúng tôi năm nay là tiết kiệm tiền mua nhà."},{"en":"Safety is the primary concern when children play outside.","vi":"An toàn là mối quan tâm hàng đầu khi trẻ em chơi bên ngoài."},{"en":"My mother has taught at a primary school for twenty years.","vi":"Mẹ tôi đã dạy ở một trường tiểu học được hai mươi năm."}]','[{"phrase":"primary school"},{"phrase":"primary goal"},{"phrase":"primary reason"},{"phrase":"primary concern"}]',NULL,'/ˈpraɪmeri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prima/primary__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1010,'ngsl-3-03',8,'weather','thời tiết','noun','[{"en":"The weather was perfect for a picnic in the park.","vi":"Thời tiết thật lý tưởng cho một buổi dã ngoại trong công viên."},{"en":"What will the weather be like tomorrow?","vi":"Thời tiết ngày mai sẽ thế nào?"},{"en":"Our flight was canceled because of bad weather.","vi":"Chuyến bay của chúng tôi bị hủy vì thời tiết xấu."}]','[{"phrase":"bad weather"},{"phrase":"weather forecast"},{"phrase":"hot weather"},{"phrase":"cold weather"}]','không đếm được; weather ≠ whether (liệu)','/ˈweðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weath/weather__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1011,'ngsl-3-03',9,'collect','thu thập, sưu tầm; đón; lấy (đồ)','verb','[{"en":"My brother has collected old coins since he was ten.","vi":"Anh trai tôi sưu tầm tiền xu cổ từ năm mười tuổi."},{"en":"Can you collect the kids from school today?","vi":"Hôm nay bạn đón bọn trẻ ở trường được không?"},{"en":"The researchers collected data from over five hundred students.","vi":"Các nhà nghiên cứu đã thu thập dữ liệu từ hơn năm trăm sinh viên."}]','[{"phrase":"collect data"},{"phrase":"collect money"},{"phrase":"collect stamps"},{"phrase":"collect the children"}]',NULL,'/kəˈlekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/collect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1012,'ngsl-3-03',10,'inform','thông báo, báo cho biết','verb','[{"en":"Please inform your manager if you will be late.","vi":"Vui lòng báo cho quản lý biết nếu bạn sẽ đến muộn."},{"en":"We were informed that the meeting had been canceled.","vi":"Chúng tôi được thông báo rằng cuộc họp đã bị hủy."},{"en":"The school will inform parents of any changes by email.","vi":"Nhà trường sẽ thông báo cho phụ huynh mọi thay đổi qua email."}]','[{"phrase":"inform somebody of"},{"phrase":"keep somebody informed"},{"phrase":"inform the police"}]','inform somebody of/about something','/ɪnˈfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infor/inform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1013,'ngsl-3-03',11,'principle','nguyên tắc; nguyên lý','noun','[{"en":"Honesty is an important principle in our family.","vi":"Trung thực là một nguyên tắc quan trọng trong gia đình chúng tôi."},{"en":"I agree with your plan in principle, but it costs too much.","vi":"Về nguyên tắc tôi đồng ý với kế hoạch của bạn, nhưng nó quá tốn kém."},{"en":"The students learned the basic principles of physics this term.","vi":"Học kỳ này, học sinh đã học các nguyên lý cơ bản của vật lý."}]','[{"phrase":"basic principle"},{"phrase":"in principle"},{"phrase":"a matter of principle"}]','principle (nguyên tắc) ≠ principal (hiệu trưởng; chính)','/ˈprɪnsəpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1014,'ngsl-3-03',12,'straight','thẳng; ngay, trực tiếp','adverb','[{"en":"Go straight ahead and turn left at the bank.","vi":"Đi thẳng về phía trước rồi rẽ trái ở ngân hàng."},{"en":"I was so tired that I went straight to bed.","vi":"Tôi mệt đến mức đi ngủ ngay."},{"en":"Please stand up straight and look at the camera.","vi":"Vui lòng đứng thẳng lên và nhìn vào máy ảnh."}]','[{"phrase":"straight ahead"},{"phrase":"go straight"},{"phrase":"straight away"},{"phrase":"sit up straight"}]',NULL,'/streɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strai/straight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1015,'ngsl-3-03',13,'appeal','lời kêu gọi; sức hấp dẫn; kháng cáo','noun','[{"en":"The hospital made an appeal for more blood donors.","vi":"Bệnh viện đã kêu gọi thêm người hiến máu."},{"en":"I don''t understand the appeal of watching golf on TV.","vi":"Tôi không hiểu sức hấp dẫn của việc xem đánh golf trên TV."},{"en":"The company lost its appeal and had to pay the fine.","vi":"Công ty đã thua kháng cáo và phải nộp tiền phạt."}]','[{"phrase":"make an appeal"},{"phrase":"appeal for"},{"phrase":"wide appeal"},{"phrase":"lose an appeal"}]',NULL,'/əˈpiːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appea/appeal__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1016,'ngsl-3-03',14,'highly','rất, hết sức; đánh giá cao','adverb','[{"en":"It is highly unlikely that it will snow in April.","vi":"Rất khó có khả năng trời sẽ có tuyết vào tháng Tư."},{"en":"I highly recommend the soup at this restaurant.","vi":"Tôi rất khuyên bạn nên thử món súp ở nhà hàng này."},{"en":"Her boss thinks highly of her work.","vi":"Sếp của cô ấy đánh giá cao công việc của cô ấy."}]','[{"phrase":"highly recommend"},{"phrase":"highly unlikely"},{"phrase":"think highly of"},{"phrase":"highly skilled"}]','highly ≠ high (cao về độ cao)','/ˈhaɪli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/highl/highly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1017,'ngsl-3-03',15,'trust','tin tưởng, tin cậy','verb','[{"en":"You can trust him to keep a secret.","vi":"Bạn có thể tin tưởng anh ấy sẽ giữ bí mật."},{"en":"I don''t trust the weather forecast in the mountains.","vi":"Tôi không tin vào dự báo thời tiết ở vùng núi."},{"en":"She has always trusted her parents'' advice.","vi":"Cô ấy luôn tin tưởng lời khuyên của bố mẹ."}]','[{"phrase":"trust somebody"},{"phrase":"trust your instincts"},{"phrase":"completely trust"}]',NULL,'/trʌst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/trust/trust__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1018,'ngsl-3-03',16,'wonderful','tuyệt vời','adjective','[{"en":"Thank you for a wonderful evening, we really enjoyed it.","vi":"Cảm ơn bạn vì một buổi tối tuyệt vời, chúng tôi thật sự rất vui."},{"en":"The view from the top of the hill is wonderful.","vi":"Quang cảnh từ đỉnh đồi thật tuyệt vời."},{"en":"It''s wonderful to see you again after so many years.","vi":"Thật tuyệt khi được gặp lại bạn sau ngần ấy năm."}]','[{"phrase":"wonderful time"},{"phrase":"wonderful news"},{"phrase":"absolutely wonderful"}]',NULL,'/ˈwʌndərfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/won/wonde/wonderful__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1019,'ngsl-3-03',17,'flat','căn hộ; bằng phẳng; (lốp) xịt','noun','[{"en":"They rent a small flat near the city center.","vi":"Họ thuê một căn hộ nhỏ gần trung tâm thành phố."},{"en":"This part of the country is very flat, so it''s good for cycling.","vi":"Vùng này của đất nước rất bằng phẳng nên rất hợp để đạp xe."},{"en":"We were late because our car had a flat tire.","vi":"Chúng tôi đến muộn vì xe bị xịt lốp."}]','[{"phrase":"rent a flat"},{"phrase":"flat surface"},{"phrase":"flat tire"}]','flat (Anh) = apartment (Mỹ)','/flæt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fla/flat_/flat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1020,'ngsl-3-03',18,'absolutely','hoàn toàn; tuyệt đối; cực kỳ','adverb','[{"en":"You''re absolutely right, I should have called first.","vi":"Bạn hoàn toàn đúng, lẽ ra tôi nên gọi điện trước."},{"en":"There is absolutely nothing to eat in the fridge.","vi":"Trong tủ lạnh chẳng có gì để ăn cả."},{"en":"I absolutely love the new café on our street.","vi":"Tôi cực kỳ thích quán cà phê mới trên phố nhà mình."}]','[{"phrase":"absolutely right"},{"phrase":"absolutely nothing"},{"phrase":"absolutely sure"},{"phrase":"absolutely delicious"}]',NULL,'/ˈæbsəluːtli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/absol/absolutely__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1021,'ngsl-3-03',19,'flow','dòng chảy; luồng (giao thông, thông tin)','noun','[{"en":"The police officer was directing the flow of traffic.","vi":"Viên cảnh sát đang điều khiển luồng giao thông."},{"en":"Regular exercise improves the flow of blood to the brain.","vi":"Tập thể dục đều đặn giúp cải thiện lưu lượng máu lên não."},{"en":"Heavy rain increased the flow of water in the river.","vi":"Mưa lớn làm tăng dòng chảy của nước trên sông."}]','[{"phrase":"flow of traffic"},{"phrase":"blood flow"},{"phrase":"flow of information"},{"phrase":"cash flow"}]',NULL,'/fləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/flow_/flow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1022,'ngsl-3-03',20,'fair','công bằng; hợp lý; (tóc) vàng hoe, (da) sáng','adjective','[{"en":"It''s not fair that I always have to wash the dishes.","vi":"Thật không công bằng khi lúc nào tôi cũng phải rửa bát."},{"en":"I think fifty dollars is a fair price for this bike.","vi":"Tôi nghĩ năm mươi đô la là giá hợp lý cho chiếc xe đạp này."},{"en":"The baby has fair hair and blue eyes.","vi":"Em bé có mái tóc vàng hoe và đôi mắt xanh."}]','[{"phrase":"fair price"},{"phrase":"fair share"},{"phrase":"fair hair"},{"phrase":"not fair"}]',NULL,'/fer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/fair_/fair__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1023,'ngsl-3-03',21,'additional','thêm, bổ sung','adjective','[{"en":"There is an additional charge for extra luggage.","vi":"Có tính phí bổ sung cho hành lý quá cước."},{"en":"Please contact us if you need any additional information.","vi":"Vui lòng liên hệ với chúng tôi nếu bạn cần thêm thông tin."},{"en":"The school hired two additional teachers this year.","vi":"Năm nay trường đã tuyển thêm hai giáo viên."}]','[{"phrase":"additional information"},{"phrase":"additional cost"},{"phrase":"additional charge"}]',NULL,'/əˈdɪʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/addit/additional__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1024,'ngsl-3-03',22,'responsible','chịu trách nhiệm; có trách nhiệm','adjective','[{"en":"Who is responsible for cleaning the kitchen this week?","vi":"Tuần này ai chịu trách nhiệm dọn dẹp nhà bếp?"},{"en":"Parents are responsible for their children''s safety.","vi":"Cha mẹ chịu trách nhiệm về sự an toàn của con cái."},{"en":"She is a very responsible young woman.","vi":"Cô ấy là một cô gái trẻ rất có trách nhiệm."}]','[{"phrase":"responsible for"},{"phrase":"hold somebody responsible"},{"phrase":"feel responsible"}]','responsible for something','/rɪˈspɑːnsəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/responsible__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1025,'ngsl-3-03',23,'farm','nông trại, trang trại','noun','[{"en":"My grandparents live on a farm in the countryside.","vi":"Ông bà tôi sống ở một trang trại ở nông thôn."},{"en":"The children fed the animals when they visited the farm.","vi":"Bọn trẻ đã cho các con vật ăn khi đến thăm trang trại."},{"en":"He has worked on a dairy farm since he left school.","vi":"Anh ấy làm việc ở một trang trại bò sữa từ khi rời ghế nhà trường."}]','[{"phrase":"on a farm"},{"phrase":"farm animals"},{"phrase":"dairy farm"},{"phrase":"work on a farm"}]','sống/làm việc on a farm','/fɑːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/far/farm_/farm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1026,'ngsl-3-03',24,'collection','bộ sưu tập; sự thu gom','noun','[{"en":"My uncle has a huge collection of old records.","vi":"Chú tôi có một bộ sưu tập đĩa nhạc cũ rất lớn."},{"en":"The museum''s collection includes many paintings from Asia.","vi":"Bộ sưu tập của bảo tàng có nhiều bức tranh từ châu Á."},{"en":"Garbage collection on our street is on Tuesdays.","vi":"Việc thu gom rác ở phố chúng tôi diễn ra vào thứ Ba."}]','[{"phrase":"a collection of"},{"phrase":"large collection"},{"phrase":"art collection"},{"phrase":"garbage collection"}]',NULL,'/kəˈlekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/collection__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1027,'ngsl-3-03',25,'hang','treo; móc','verb','[{"en":"Can you help me hang this picture on the wall?","vi":"Bạn có thể giúp tôi treo bức tranh này lên tường không?"},{"en":"She hung her coat behind the door.","vi":"Cô ấy móc áo khoác sau cánh cửa."},{"en":"Colorful lights were hanging from the trees in the garden.","vi":"Những chiếc đèn nhiều màu được treo trên cây trong vườn."}]','[{"phrase":"hang a picture"},{"phrase":"hang on the wall"},{"phrase":"hang up"},{"phrase":"hang out"}]','hang – hung – hung','/hæŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/han/hang_/hang__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1028,'ngsl-3-03',26,'negative','tiêu cực; phủ định; âm tính','adjective','[{"en":"Too much screen time can have a negative effect on sleep.","vi":"Dùng màn hình quá nhiều có thể ảnh hưởng tiêu cực đến giấc ngủ."},{"en":"Try not to be so negative about your new job.","vi":"Cố gắng đừng quá tiêu cực về công việc mới của bạn."},{"en":"The good news is that the test results were negative.","vi":"Tin tốt là kết quả xét nghiệm âm tính."}]','[{"phrase":"negative effect"},{"phrase":"negative impact"},{"phrase":"negative attitude"},{"phrase":"test negative"}]','negative ≠ positive (tích cực; dương tính)','/ˈneɡətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negat/negative__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1029,'ngsl-3-03',27,'band','ban nhạc; dải, băng','noun','[{"en":"My brother plays the drums in a rock band.","vi":"Anh trai tôi chơi trống trong một ban nhạc rock."},{"en":"A local band played at their wedding party.","vi":"Một ban nhạc địa phương đã biểu diễn trong tiệc cưới của họ."},{"en":"She tied her hair back with a rubber band.","vi":"Cô ấy buộc tóc ra sau bằng một sợi dây thun."}]','[{"phrase":"rock band"},{"phrase":"play in a band"},{"phrase":"join a band"},{"phrase":"rubber band"}]',NULL,'/bænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ban/band_/band__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1030,'ngsl-3-03',28,'relative','họ hàng, người thân','noun','[{"en":"We visit our relatives in the countryside every New Year.","vi":"Mỗi dịp Tết, chúng tôi về quê thăm họ hàng."},{"en":"Only close relatives were invited to the small wedding.","vi":"Chỉ những người thân trong gia đình được mời đến đám cưới nhỏ."},{"en":"She is staying with a relative while she studies abroad.","vi":"Cô ấy đang ở nhà một người họ hàng trong thời gian du học."}]','[{"phrase":"close relative"},{"phrase":"distant relative"},{"phrase":"friends and relatives"},{"phrase":"visit relatives"}]',NULL,'/ˈrelətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relative__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1031,'ngsl-3-03',29,'tour','chuyến tham quan, chuyến du lịch; chuyến lưu diễn','noun','[{"en":"We took a guided tour of the old town.","vi":"Chúng tôi đã tham gia một chuyến tham quan phố cổ có hướng dẫn viên."},{"en":"The tour of the factory lasted about two hours.","vi":"Chuyến tham quan nhà máy kéo dài khoảng hai tiếng."},{"en":"The band is going on a world tour next year.","vi":"Ban nhạc sẽ đi lưu diễn vòng quanh thế giới vào năm tới."}]','[{"phrase":"guided tour"},{"phrase":"go on tour"},{"phrase":"world tour"},{"phrase":"tour guide"}]',NULL,'/tʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/tour_/tour__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1032,'ngsl-3-03',30,'alternative','sự lựa chọn khác, phương án thay thế','noun','[{"en":"The road is closed, so we need to find an alternative.","vi":"Con đường bị chặn nên chúng tôi cần tìm một phương án khác."},{"en":"Walking is a healthy alternative to driving to work.","vi":"Đi bộ là một lựa chọn lành mạnh thay cho việc lái xe đi làm."},{"en":"We had no alternative but to wait for the next train.","vi":"Chúng tôi không còn cách nào khác ngoài việc chờ chuyến tàu tiếp theo."}]','[{"phrase":"alternative to"},{"phrase":"no alternative"},{"phrase":"a good alternative"},{"phrase":"cheaper alternative"}]','an alternative to something','/ɔːlˈtɜːrnətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alternative__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1033,'ngsl-3-04',1,'software','phần mềm','noun','[{"en":"You need to install the new software before the meeting.","vi":"Bạn cần cài đặt phần mềm mới trước cuộc họp."},{"en":"My brother writes software for a small company in the city.","vi":"Anh trai tôi viết phần mềm cho một công ty nhỏ trong thành phố."},{"en":"Is this software free, or do we have to pay for it?","vi":"Phần mềm này miễn phí hay chúng ta phải trả tiền?"}]','[{"phrase":"install software"},{"phrase":"software company"},{"phrase":"computer software"},{"phrase":"update the software"}]','không đếm được','/ˈsɔːftwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sof/softw/software__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1034,'ngsl-3-04',2,'pair','đôi; cặp','noun','[{"en":"I bought a new pair of shoes for the wedding.","vi":"Tôi đã mua một đôi giày mới để đi dự đám cưới."},{"en":"The teacher asked us to work in pairs today.","vi":"Hôm nay giáo viên yêu cầu chúng tôi làm việc theo cặp."},{"en":"Can I borrow a pair of scissors from you?","vi":"Tôi có thể mượn bạn một cái kéo không?"}]','[{"phrase":"a pair of shoes"},{"phrase":"a pair of glasses"},{"phrase":"work in pairs"}]',NULL,'/per/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pai/pair_/pair__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1035,'ngsl-3-04',3,'ship','tàu thủy; con tàu','noun','[{"en":"We watched the big ship leave the port at sunset.","vi":"Chúng tôi nhìn con tàu lớn rời cảng lúc hoàng hôn."},{"en":"My grandfather worked on a cargo ship for twenty years.","vi":"Ông tôi đã làm việc trên một tàu chở hàng suốt hai mươi năm."},{"en":"They crossed the ocean by ship instead of flying.","vi":"Họ vượt đại dương bằng tàu thủy thay vì đi máy bay."}]','[{"phrase":"by ship"},{"phrase":"cargo ship"},{"phrase":"cruise ship"}]',NULL,'/ʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/ship_/ship__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1036,'ngsl-3-04',4,'attitude','thái độ; quan điểm','noun','[{"en":"She always has a positive attitude, even on bad days.","vi":"Cô ấy luôn có thái độ tích cực, kể cả vào những ngày tồi tệ."},{"en":"His attitude toward work has changed a lot this year.","vi":"Năm nay thái độ của anh ấy đối với công việc đã thay đổi nhiều."},{"en":"Young people''s attitudes to marriage are different from their parents''.","vi":"Quan điểm của giới trẻ về hôn nhân khác với cha mẹ họ."}]','[{"phrase":"positive attitude"},{"phrase":"attitude toward"},{"phrase":"change your attitude"},{"phrase":"bad attitude"}]','attitude to/toward(s) something','/ˈætɪtuːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attit/attitude__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1037,'ngsl-3-04',5,'cheap','rẻ; kém chất lượng','adjective','[{"en":"The food at this little restaurant is cheap and delicious.","vi":"Đồ ăn ở nhà hàng nhỏ này rẻ mà ngon."},{"en":"We found a cheap hotel near the train station.","vi":"Chúng tôi tìm được một khách sạn giá rẻ gần ga tàu."},{"en":"These cheap headphones broke after only two weeks.","vi":"Cái tai nghe rẻ tiền này hỏng chỉ sau hai tuần."}]','[{"phrase":"cheap hotel"},{"phrase":"relatively cheap"},{"phrase":"cheap flights"}]',NULL,'/tʃiːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/cheap/cheap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1038,'ngsl-3-04',6,'double','gấp đôi; đôi','adjective','[{"en":"I''d like to book a double room for three nights.","vi":"Tôi muốn đặt một phòng đôi trong ba đêm."},{"en":"Rent in the city center is almost double what we pay now.","vi":"Tiền thuê nhà ở trung tâm thành phố gần gấp đôi số chúng tôi đang trả."},{"en":"He ordered a double espresso to stay awake.","vi":"Anh ấy gọi một ly espresso đúp để giữ tỉnh táo."}]','[{"phrase":"double room"},{"phrase":"double bed"},{"phrase":"double the price"}]',NULL,'/ˈdʌbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dou/doubl/double__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1039,'ngsl-3-04',7,'leg','chân; chặng','noun','[{"en":"He broke his leg while playing soccer last winter.","vi":"Anh ấy bị gãy chân khi chơi bóng đá vào mùa đông năm ngoái."},{"en":"My legs were tired after walking around the city all day.","vi":"Chân tôi mỏi nhừ sau khi đi bộ quanh thành phố cả ngày."},{"en":"The first leg of our trip was a long train ride.","vi":"Chặng đầu tiên của chuyến đi là một chuyến tàu dài."}]','[{"phrase":"broken leg"},{"phrase":"break your leg"},{"phrase":"long legs"},{"phrase":"first leg"}]',NULL,'/leɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/leg__/leg__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1040,'ngsl-3-04',8,'observe','quan sát; tuân thủ','verb','[{"en":"The children observed the birds through a small window.","vi":"Bọn trẻ quan sát những con chim qua một ô cửa sổ nhỏ."},{"en":"Scientists observed the animals closely for several months.","vi":"Các nhà khoa học đã quan sát kỹ những con vật trong vài tháng."},{"en":"All drivers must observe the speed limit near schools.","vi":"Mọi tài xế phải tuân thủ giới hạn tốc độ gần trường học."}]','[{"phrase":"observe closely"},{"phrase":"carefully observe"},{"phrase":"observe the rules"}]',NULL,'/əbˈzɜːrv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obs/obser/observe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1041,'ngsl-3-04',9,'sentence','câu; bản án','noun','[{"en":"Please write a sentence using each new word.","vi":"Hãy viết một câu với mỗi từ mới."},{"en":"I didn''t understand the last sentence of the email.","vi":"Tôi không hiểu câu cuối cùng của email."},{"en":"The judge gave him a sentence of three years.","vi":"Thẩm phán tuyên cho anh ta bản án ba năm tù."}]','[{"phrase":"write a sentence"},{"phrase":"complete sentence"},{"phrase":"prison sentence"}]',NULL,'/ˈsentəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/sente/sentence__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1042,'ngsl-3-04',10,'print','in; in ra','verb','[{"en":"Could you print two copies of this report for me?","vi":"Bạn có thể in giúp tôi hai bản báo cáo này không?"},{"en":"I printed my boarding pass before leaving for the airport.","vi":"Tôi đã in thẻ lên máy bay trước khi ra sân bay."},{"en":"The printer in our office can''t print in color.","vi":"Máy in ở văn phòng chúng tôi không in màu được."}]','[{"phrase":"print a copy"},{"phrase":"print out"},{"phrase":"print in color"}]','print out = in ra','/prɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/print/print__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1043,'ngsl-3-04',11,'progress','sự tiến bộ; tiến triển','noun','[{"en":"You''ve made great progress with your English this year.","vi":"Năm nay bạn đã tiến bộ rất nhiều trong tiếng Anh."},{"en":"The manager wants a weekly update on our progress.","vi":"Quản lý muốn được cập nhật tiến độ của chúng tôi hằng tuần."},{"en":"There has been little progress in the talks so far.","vi":"Cho đến nay các cuộc đàm phán hầu như chưa có tiến triển."}]','[{"phrase":"make progress"},{"phrase":"great progress"},{"phrase":"slow progress"}]','không đếm được','/ˈprɑːɡres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/progr/progress__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1044,'ngsl-3-04',12,'truth','sự thật','noun','[{"en":"Just tell me the truth, and I won''t be angry.","vi":"Cứ nói thật với tôi đi, tôi sẽ không giận đâu."},{"en":"Nobody knows the truth about what happened that night.","vi":"Không ai biết sự thật về những gì đã xảy ra đêm hôm đó."},{"en":"There is some truth in what your mother said.","vi":"Những gì mẹ bạn nói cũng có phần sự thật."}]','[{"phrase":"tell the truth"},{"phrase":"the whole truth"},{"phrase":"find out the truth"}]',NULL,'/truːθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/truth/truth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1045,'ngsl-3-04',13,'nobody','không ai; không người nào','pronoun','[{"en":"I knocked on the door, but nobody answered.","vi":"Tôi gõ cửa nhưng không ai trả lời."},{"en":"Nobody in my family can cook as well as my grandmother.","vi":"Không ai trong gia đình tôi nấu ăn ngon bằng bà tôi."},{"en":"There was nobody at the office when I arrived.","vi":"Lúc tôi đến thì văn phòng không có ai."}]','[{"phrase":"nobody else"},{"phrase":"nobody knows"},{"phrase":"almost nobody"}]','Đi với động từ số ít: Nobody knows.','/ˈnəʊbədi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nob/nobod/nobody__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1046,'ngsl-3-04',14,'examine','kiểm tra; xem xét; khám (bệnh)','verb','[{"en":"The doctor examined my throat and said it was nothing serious.","vi":"Bác sĩ khám họng cho tôi và nói không có gì nghiêm trọng."},{"en":"Please examine the contract carefully before you sign it.","vi":"Hãy xem xét hợp đồng thật kỹ trước khi ký."},{"en":"The mechanic examined the engine but couldn''t find the problem.","vi":"Thợ máy kiểm tra động cơ nhưng không tìm ra lỗi."}]','[{"phrase":"examine carefully"},{"phrase":"examine a patient"},{"phrase":"closely examine"}]',NULL,'/ɪɡˈzæmɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exami/examine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1047,'ngsl-3-04',15,'lay','đặt; đặt nằm; đẻ (trứng)','verb','[{"en":"She laid the baby gently on the bed.","vi":"Cô ấy nhẹ nhàng đặt em bé nằm xuống giường."},{"en":"He laid his keys on the kitchen table and sat down.","vi":"Anh ấy đặt chùm chìa khóa lên bàn bếp rồi ngồi xuống."},{"en":"Our chickens lay about six eggs every morning.","vi":"Mấy con gà nhà chúng tôi đẻ khoảng sáu quả trứng mỗi sáng."}]','[{"phrase":"lay eggs"},{"phrase":"lay the table"},{"phrase":"lay something down"}]','lay – laid – laid; khác lie – lay – lain (nằm)','/leɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lay/lay__/lay__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1048,'ngsl-3-04',16,'speed','tốc độ','noun','[{"en":"The train travels at a speed of 300 kilometers an hour.","vi":"Đoàn tàu chạy với tốc độ 300 ki-lô-mét một giờ."},{"en":"Our internet speed is very slow in the evenings.","vi":"Tốc độ mạng nhà chúng tôi rất chậm vào buổi tối."},{"en":"He was driving at high speed when the police stopped him.","vi":"Anh ta đang lái xe với tốc độ cao thì bị cảnh sát chặn lại."}]','[{"phrase":"high speed"},{"phrase":"at full speed"},{"phrase":"speed limit"},{"phrase":"internet speed"}]',NULL,'/spiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speed/speed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1049,'ngsl-3-04',17,'politics','chính trị','noun','[{"en":"My father loves talking about politics at the dinner table.","vi":"Bố tôi rất thích bàn chuyện chính trị trong bữa ăn."},{"en":"She studied politics and economics at university.","vi":"Cô ấy học ngành chính trị và kinh tế ở đại học."},{"en":"I''ve never been very interested in politics.","vi":"Tôi chưa bao giờ quan tâm nhiều đến chính trị."}]','[{"phrase":"interested in politics"},{"phrase":"talk about politics"},{"phrase":"local politics"},{"phrase":"office politics"}]','politics (n) chính trị · political (adj) · politician (n) chính trị gia','/ˈpɑːlətɪks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polit/politics__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1050,'ngsl-3-04',18,'reply','trả lời; hồi âm','verb','[{"en":"Sorry, I forgot to reply to your message yesterday.","vi":"Xin lỗi, hôm qua tôi quên trả lời tin nhắn của bạn."},{"en":"When I asked her name, she smiled but didn''t reply.","vi":"Khi tôi hỏi tên, cô ấy mỉm cười nhưng không trả lời."},{"en":"The company replied to my email within an hour.","vi":"Công ty đã hồi âm email của tôi trong vòng một giờ."}]','[{"phrase":"reply to an email"},{"phrase":"reply to a message"},{"phrase":"reply quickly"}]','reply to something/somebody','/rɪˈplaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/reply/reply__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1051,'ngsl-3-04',19,'display','trưng bày; hiển thị','verb','[{"en":"The shop displays its newest clothes in the front window.","vi":"Cửa hàng trưng bày quần áo mới nhất ở cửa kính phía trước."},{"en":"Old family photos were displayed on the living room wall.","vi":"Những tấm ảnh gia đình cũ được trưng bày trên tường phòng khách."},{"en":"The screen displays the time and the temperature.","vi":"Màn hình hiển thị giờ và nhiệt độ."}]','[{"phrase":"display a message"},{"phrase":"proudly display"},{"phrase":"be displayed on the screen"}]',NULL,'/dɪˈspleɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/displ/display__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1052,'ngsl-3-04',20,'transfer','chuyển; chuyển khoản; chuyển công tác','verb','[{"en":"I''ll transfer the money to your account this afternoon.","vi":"Chiều nay tôi sẽ chuyển tiền vào tài khoản của bạn."},{"en":"He was transferred to our office in another city.","vi":"Anh ấy được chuyển công tác sang văn phòng của chúng tôi ở thành phố khác."},{"en":"How do I transfer photos from my phone to my laptop?","vi":"Làm sao để chuyển ảnh từ điện thoại sang máy tính xách tay?"}]','[{"phrase":"transfer money"},{"phrase":"transfer files"},{"phrase":"transfer to another school"}]','transfer – transferred – transferred','/trænsˈfɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transfer__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1053,'ngsl-3-04',21,'perfect','hoàn hảo; lý tưởng','adjective','[{"en":"Nobody is perfect, so don''t be too hard on yourself.","vi":"Không ai hoàn hảo cả, nên đừng quá khắt khe với bản thân."},{"en":"The weather was perfect for a picnic in the park.","vi":"Thời tiết thật lý tưởng cho một buổi dã ngoại trong công viên."},{"en":"Her English is almost perfect after living abroad for years.","vi":"Tiếng Anh của cô ấy gần như hoàn hảo sau nhiều năm sống ở nước ngoài."}]','[{"phrase":"perfect for"},{"phrase":"almost perfect"},{"phrase":"perfect example"},{"phrase":"perfect timing"}]',NULL,'/ˈpɜːrfɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfe/perfect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1054,'ngsl-3-04',22,'slightly','hơi; một chút','adverb','[{"en":"I feel slightly better than I did this morning.","vi":"Tôi thấy đỡ hơn một chút so với sáng nay."},{"en":"Prices are slightly higher at the shop near our house.","vi":"Giá ở cửa hàng gần nhà chúng tôi hơi cao hơn."},{"en":"The two jackets look the same, but this one is slightly bigger.","vi":"Hai chiếc áo khoác trông giống nhau, nhưng chiếc này hơi to hơn."}]','[{"phrase":"slightly different"},{"phrase":"slightly higher"},{"phrase":"only slightly"}]',NULL,'/ˈslaɪtli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/sligh/slightly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1055,'ngsl-3-04',23,'overall','tổng thể; chung; nhìn chung','adjective','[{"en":"The overall cost of the trip was lower than we expected.","vi":"Tổng chi phí của chuyến đi thấp hơn chúng tôi dự tính."},{"en":"My overall impression of the new school was very good.","vi":"Ấn tượng chung của tôi về ngôi trường mới rất tốt."},{"en":"There were a few problems, but overall it was a great weekend.","vi":"Có vài trục trặc, nhưng nhìn chung đó là một cuối tuần tuyệt vời."}]','[{"phrase":"overall cost"},{"phrase":"overall impression"},{"phrase":"overall result"}]','Cũng dùng như trạng từ: Overall, … (nhìn chung)','/ˌəʊvərˈɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overa/overall__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1056,'ngsl-3-04',24,'intend','dự định; có ý định','verb','[{"en":"I intend to finish this project before the end of the month.","vi":"Tôi dự định hoàn thành dự án này trước cuối tháng."},{"en":"Sorry, I didn''t intend to hurt your feelings.","vi":"Xin lỗi, tôi không có ý làm bạn tổn thương."},{"en":"How long do you intend to stay in the country?","vi":"Bạn dự định ở lại đất nước này bao lâu?"}]','[{"phrase":"intend to do"},{"phrase":"fully intend"},{"phrase":"never intended"}]','intend to do something','/ɪnˈtend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intend__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1057,'ngsl-3-04',25,'user','người dùng; người sử dụng','noun','[{"en":"The new app already has more than a million users.","vi":"Ứng dụng mới đã có hơn một triệu người dùng."},{"en":"Please enter your user name and password to continue.","vi":"Vui lòng nhập tên người dùng và mật khẩu để tiếp tục."},{"en":"Many phone users complain that the battery runs out too quickly.","vi":"Nhiều người dùng điện thoại phàn nàn rằng pin hết quá nhanh."}]','[{"phrase":"internet user"},{"phrase":"user name"},{"phrase":"new users"},{"phrase":"road users"}]',NULL,'/ˈjuːzər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/use/user_/user__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1058,'ngsl-3-04',26,'respond','phản hồi; trả lời; phản ứng','verb','[{"en":"The hotel responded to my complaint the very next day.","vi":"Khách sạn đã phản hồi lời phàn nàn của tôi ngay ngày hôm sau."},{"en":"I asked him a question, but he didn''t respond.","vi":"Tôi hỏi anh ấy một câu nhưng anh ấy không trả lời."},{"en":"How did your parents respond when you told them the news?","vi":"Bố mẹ bạn phản ứng thế nào khi bạn báo tin cho họ?"}]','[{"phrase":"respond to"},{"phrase":"respond quickly"},{"phrase":"fail to respond"}]','respond to something','/rɪˈspɑːnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/respond__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1059,'ngsl-3-04',27,'dinner','bữa tối','noun','[{"en":"What are we having for dinner tonight?","vi":"Tối nay chúng ta ăn gì?"},{"en":"My family always eats dinner together at seven o''clock.","vi":"Gia đình tôi luôn ăn tối cùng nhau lúc bảy giờ."},{"en":"He invited his new colleagues to dinner at his place.","vi":"Anh ấy mời các đồng nghiệp mới đến nhà mình ăn tối."}]','[{"phrase":"have dinner"},{"phrase":"cook dinner"},{"phrase":"for dinner"},{"phrase":"invite someone to dinner"}]',NULL,'/ˈdɪnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/din/dinne/dinner__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1060,'ngsl-3-04',28,'slow','chậm','adjective','[{"en":"The bus was so slow that I was late for work.","vi":"Xe buýt chạy chậm đến mức tôi bị muộn giờ làm."},{"en":"My laptop has become really slow since the last update.","vi":"Máy tính xách tay của tôi trở nên rất chậm từ lần cập nhật gần nhất."},{"en":"Learning a new language is a slow process.","vi":"Học một ngôn ngữ mới là một quá trình chậm."}]','[{"phrase":"slow progress"},{"phrase":"slow process"},{"phrase":"slow down"}]',NULL,'/sləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/slo/slow_/slow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1061,'ngsl-3-04',29,'regular','thường xuyên; đều đặn; thông thường','adjective','[{"en":"Regular exercise helps you sleep better at night.","vi":"Tập thể dục đều đặn giúp bạn ngủ ngon hơn vào ban đêm."},{"en":"She has been a regular customer here for ten years.","vi":"Cô ấy là khách quen ở đây đã mười năm rồi."},{"en":"I''d like a regular coffee with milk, please.","vi":"Cho tôi một ly cà phê sữa cỡ thường."}]','[{"phrase":"regular exercise"},{"phrase":"on a regular basis"},{"phrase":"regular customer"}]',NULL,'/ˈreɡjələr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regular__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1062,'ngsl-3-04',30,'physical','thể chất; vật chất','adjective','[{"en":"Physical activity is important for both your body and mind.","vi":"Hoạt động thể chất rất quan trọng cho cả cơ thể lẫn tinh thần."},{"en":"Farm work requires a lot of physical strength.","vi":"Công việc đồng áng đòi hỏi rất nhiều sức lực."},{"en":"I prefer physical books to reading on a screen.","vi":"Tôi thích sách giấy hơn là đọc trên màn hình."}]','[{"phrase":"physical activity"},{"phrase":"physical exercise"},{"phrase":"physical health"},{"phrase":"physical strength"}]',NULL,'/ˈfɪzɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phy/physi/physical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1063,'ngsl-3-02',1,'effective','hiệu quả; có hiệu lực','adjective','[{"en":"Walking every day is an effective way to stay healthy.","vi":"Đi bộ mỗi ngày là một cách hiệu quả để giữ sức khỏe."},{"en":"This medicine is very effective against headaches.","vi":"Thuốc này trị đau đầu rất hiệu quả."},{"en":"The new rules will become effective next month.","vi":"Các quy định mới sẽ có hiệu lực từ tháng sau."}]','[{"phrase":"effective way"},{"phrase":"highly effective"},{"phrase":"become effective"}]',NULL,'/ɪˈfektɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effec/effective__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1064,'ngsl-3-02',2,'correct','đúng; chính xác','adjective','[{"en":"Is this the correct address for the hotel?","vi":"Đây có phải là địa chỉ đúng của khách sạn không?"},{"en":"You''re correct that the meeting starts at nine.","vi":"Bạn nói đúng, cuộc họp bắt đầu lúc chín giờ."},{"en":"Please check that all your answers are correct before you finish.","vi":"Hãy kiểm tra xem mọi câu trả lời đã đúng chưa trước khi làm xong."}]','[{"phrase":"correct answer"},{"phrase":"absolutely correct"},{"phrase":"the correct way"}]','cũng là động từ: sửa (correct a mistake)','/kəˈrekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corre/correct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1065,'ngsl-3-02',3,'medical','(thuộc) y tế; y khoa','adjective','[{"en":"The injured driver needed medical help right away.","vi":"Người lái xe bị thương cần được hỗ trợ y tế ngay lập tức."},{"en":"My brother is in his second year of medical school.","vi":"Anh trai tôi đang học năm thứ hai trường y."},{"en":"All new employees must have a medical check-up before starting work.","vi":"Tất cả nhân viên mới phải khám sức khỏe trước khi bắt đầu làm việc."}]','[{"phrase":"medical care"},{"phrase":"medical school"},{"phrase":"medical treatment"}]',NULL,'/ˈmedɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/medic/medical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1066,'ngsl-3-02',4,'admit','thừa nhận; cho vào, nhận vào (bệnh viện, trường)','verb','[{"en":"He finally admitted that he had made a mistake.","vi":"Cuối cùng anh ấy cũng thừa nhận rằng mình đã mắc lỗi."},{"en":"I have to admit I was a little nervous.","vi":"Phải thừa nhận là tôi đã hơi lo lắng."},{"en":"She was admitted to the hospital with a high fever.","vi":"Cô ấy phải nhập viện vì sốt cao."}]','[{"phrase":"admit a mistake"},{"phrase":"admit defeat"},{"phrase":"admitted to the hospital"}]','admit – admitted – admitted','/ədˈmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adm/admit/admit__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1067,'ngsl-3-02',5,'beat','đánh bại, thắng; đập (tim); đánh (trứng)','verb','[{"en":"Our school team beat the best team in the city.","vi":"Đội của trường tôi đã đánh bại đội mạnh nhất thành phố."},{"en":"My heart was beating fast before the exam.","vi":"Tim tôi đập nhanh trước giờ thi."},{"en":"Beat the eggs and sugar together for two minutes.","vi":"Đánh trứng với đường trong hai phút."}]','[{"phrase":"beat eggs"},{"phrase":"beat the traffic"},{"phrase":"easily beat"}]','beat – beat – beaten','/biːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beat_/beat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1068,'ngsl-3-02',6,'telephone','điện thoại','noun','[{"en":"Please write your name and telephone number on the form.","vi":"Vui lòng ghi tên và số điện thoại của bạn vào mẫu đơn."},{"en":"The telephone rang just as we sat down to dinner.","vi":"Điện thoại reo đúng lúc chúng tôi ngồi xuống ăn tối."},{"en":"Most customers contact us by telephone or email.","vi":"Hầu hết khách hàng liên hệ với chúng tôi qua điện thoại hoặc email."}]','[{"phrase":"telephone number"},{"phrase":"by telephone"},{"phrase":"telephone call"},{"phrase":"answer the telephone"}]',NULL,'/ˈtelɪfəʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tel/telep/telephone__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1069,'ngsl-3-02',7,'copy','bản sao; bản, cuốn (sách, báo)','noun','[{"en":"Can you make a copy of this letter for me?","vi":"Bạn có thể sao giúp tôi một bản của lá thư này không?"},{"en":"Keep a copy of your passport in a safe place.","vi":"Hãy giữ một bản sao hộ chiếu ở nơi an toàn."},{"en":"The library has three copies of that book.","vi":"Thư viện có ba cuốn sách đó."}]','[{"phrase":"make a copy"},{"phrase":"keep a copy"},{"phrase":"hard copy"}]','cũng là động từ: sao chép, chép (copy a file)','/ˈkɑːpi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cop/copy_/copy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1070,'ngsl-3-02',8,'committee','ủy ban; ban','noun','[{"en":"She was asked to join the planning committee for the festival.","vi":"Cô ấy được mời tham gia ban kế hoạch của lễ hội."},{"en":"The committee meets once a month to discuss new ideas.","vi":"Ủy ban họp mỗi tháng một lần để thảo luận các ý tưởng mới."},{"en":"A small committee will decide who wins the prize.","vi":"Một ban nhỏ sẽ quyết định ai giành giải thưởng."}]','[{"phrase":"committee meeting"},{"phrase":"join a committee"},{"phrase":"planning committee"},{"phrase":"committee member"}]','chính tả: 2 m, 2 t, 2 e','/kəˈmɪti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/committee__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1071,'ngsl-3-02',9,'aware','biết; nhận thức được','adjective','[{"en":"Are you aware that the store closes early today?","vi":"Bạn có biết hôm nay cửa hàng đóng cửa sớm không?"},{"en":"I wasn''t aware of the problem until my boss told me.","vi":"Tôi không biết về vấn đề này cho đến khi sếp nói với tôi."},{"en":"Parents should be aware of what their children watch online.","vi":"Cha mẹ nên biết con mình xem gì trên mạng."}]','[{"phrase":"aware of"},{"phrase":"become aware"},{"phrase":"fully aware"},{"phrase":"well aware"}]','aware of sth / aware that…','/əˈwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/aware/aware__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1072,'ngsl-3-02',10,'advice','lời khuyên','noun','[{"en":"Can I ask you for some advice about my job?","vi":"Tôi có thể xin bạn vài lời khuyên về công việc của tôi không?"},{"en":"My grandmother always gives me good advice.","vi":"Bà tôi luôn cho tôi những lời khuyên hay."},{"en":"You should follow the doctor''s advice and rest for a few days.","vi":"Bạn nên làm theo lời khuyên của bác sĩ và nghỉ ngơi vài ngày."}]','[{"phrase":"give advice"},{"phrase":"ask for advice"},{"phrase":"follow advice"},{"phrase":"piece of advice"}]','không đếm được: a piece of advice · advice (n) ≠ advise (v)','/ədˈvaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advic/advice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1073,'ngsl-3-02',11,'handle','xử lý, giải quyết; cầm, cầm nắm','verb','[{"en":"She handled the angry customer very calmly.","vi":"Cô ấy xử lý vị khách đang tức giận rất bình tĩnh."},{"en":"I don''t know if I can handle all this work alone.","vi":"Tôi không biết liệu mình có thể một mình lo hết chỗ việc này không."},{"en":"Please handle these glasses carefully because they break easily.","vi":"Vui lòng cầm những chiếc ly này cẩn thận vì chúng rất dễ vỡ."}]','[{"phrase":"handle a situation"},{"phrase":"handle a problem"},{"phrase":"handle with care"}]','cũng là danh từ: tay cầm, tay nắm','/ˈhændl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/han/handl/handle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1074,'ngsl-3-02',12,'glass','ly, cốc; kính, thủy tinh','noun','[{"en":"Could I have a glass of water, please?","vi":"Cho tôi xin một cốc nước được không?"},{"en":"The table top is made of glass, so be careful.","vi":"Mặt bàn làm bằng kính nên hãy cẩn thận."},{"en":"He broke a glass while he was washing the dishes.","vi":"Anh ấy làm vỡ một cái ly khi đang rửa bát."}]','[{"phrase":"a glass of water"},{"phrase":"broken glass"},{"phrase":"wine glass"},{"phrase":"glass door"}]','glasses (số nhiều) còn có nghĩa là kính đeo mắt','/ɡlæs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gla/glass/glass__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1075,'ngsl-3-02',13,'trial','phiên tòa, sự xét xử; sự thử nghiệm, dùng thử','noun','[{"en":"The trial is expected to last about two weeks.","vi":"Phiên tòa dự kiến kéo dài khoảng hai tuần."},{"en":"The man went on trial for stealing a car.","vi":"Người đàn ông bị đưa ra xét xử vì tội trộm xe hơi."},{"en":"The app offers a free trial for the first month.","vi":"Ứng dụng này cho dùng thử miễn phí trong tháng đầu tiên."}]','[{"phrase":"free trial"},{"phrase":"on trial"},{"phrase":"clinical trial"},{"phrase":"trial period"}]',NULL,'/ˈtraɪəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trial/trial__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1076,'ngsl-3-02',14,'stress','căng thẳng; áp lực','noun','[{"en":"Too much stress can make it hard to sleep.","vi":"Căng thẳng quá mức có thể khiến bạn khó ngủ."},{"en":"She has been under a lot of stress at work lately.","vi":"Dạo này cô ấy chịu nhiều áp lực trong công việc."},{"en":"Going for a walk is a good way to reduce stress.","vi":"Đi dạo là một cách tốt để giảm căng thẳng."}]','[{"phrase":"under stress"},{"phrase":"reduce stress"},{"phrase":"stress levels"}]','cũng là động từ: nhấn mạnh (stress the importance of…)','/stres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stres/stress__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1077,'ngsl-3-02',15,'radio','đài, radio','noun','[{"en":"I heard the news on the radio this morning.","vi":"Tôi nghe tin đó trên đài sáng nay."},{"en":"My dad always listens to the radio while he drives.","vi":"Bố tôi luôn nghe đài khi lái xe."},{"en":"Can you turn the radio down a little?","vi":"Bạn vặn nhỏ đài một chút được không?"}]','[{"phrase":"listen to the radio"},{"phrase":"on the radio"},{"phrase":"radio station"},{"phrase":"turn on the radio"}]',NULL,'/ˈreɪdiəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rad/radio/radio__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1078,'ngsl-3-02',16,'administration','công tác hành chính, quản lý; ban quản lý','noun','[{"en":"She has worked in hospital administration for ten years.","vi":"Cô ấy đã làm công tác hành chính ở bệnh viện được mười năm."},{"en":"Teachers spend too much time on administration instead of teaching.","vi":"Giáo viên dành quá nhiều thời gian cho việc hành chính thay vì giảng dạy."},{"en":"The school administration decided to cancel classes because of the storm.","vi":"Ban giám hiệu nhà trường quyết định cho học sinh nghỉ học vì bão."}]','[{"phrase":"business administration"},{"phrase":"school administration"},{"phrase":"administration costs"}]',NULL,'/ədˌmɪnɪˈstreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adm/admin/administration__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1079,'ngsl-3-02',17,'complex','phức tạp','adjective','[{"en":"The instructions were too complex for most people to follow.","vi":"Hướng dẫn quá phức tạp nên hầu hết mọi người không làm theo được."},{"en":"Learning a language is a long and complex process.","vi":"Học một ngôn ngữ là một quá trình lâu dài và phức tạp."},{"en":"This is a complex problem with no easy answer.","vi":"Đây là một vấn đề phức tạp, không có lời giải dễ dàng."}]','[{"phrase":"complex issue"},{"phrase":"complex process"},{"phrase":"highly complex"},{"phrase":"complex system"}]','cũng là danh từ: khu phức hợp (sports complex)','/kəmˈpleks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complex__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1080,'ngsl-3-02',18,'text','văn bản, chữ; tin nhắn','noun','[{"en":"Send me a text when you get home.","vi":"Nhắn tin cho tôi khi bạn về đến nhà nhé."},{"en":"Read the text carefully and answer the questions below.","vi":"Đọc kỹ văn bản và trả lời các câu hỏi bên dưới."},{"en":"You can make the text bigger so it''s easier to read.","vi":"Bạn có thể phóng to chữ để dễ đọc hơn."}]','[{"phrase":"text message"},{"phrase":"send a text"},{"phrase":"read the text"}]','cũng là động từ: nhắn tin (text me)','/tekst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tex/text_/text__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1081,'ngsl-3-02',19,'context','ngữ cảnh; bối cảnh','noun','[{"en":"Try to guess the meaning of the word from the context.","vi":"Hãy thử đoán nghĩa của từ dựa vào ngữ cảnh."},{"en":"His words were taken out of context.","vi":"Lời anh ấy nói đã bị tách khỏi ngữ cảnh."},{"en":"You need some historical context to understand this story.","vi":"Bạn cần biết chút bối cảnh lịch sử để hiểu câu chuyện này."}]','[{"phrase":"in context"},{"phrase":"out of context"},{"phrase":"historical context"},{"phrase":"in this context"}]',NULL,'/ˈkɑːntekst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontext__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1082,'ngsl-3-02',20,'ride','đi (xe đạp, xe máy, tàu xe); cưỡi (ngựa)','verb','[{"en":"My daughter learned to ride a bike when she was five.","vi":"Con gái tôi học đi xe đạp khi lên năm tuổi."},{"en":"We rode the train all the way to the coast.","vi":"Chúng tôi đi tàu suốt đến tận vùng biển."},{"en":"Have you ever ridden a horse on the beach?","vi":"Bạn đã bao giờ cưỡi ngựa trên bãi biển chưa?"}]','[{"phrase":"ride a bike"},{"phrase":"ride a horse"},{"phrase":"ride a motorcycle"}]','ride – rode – ridden','/raɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rid/ride_/ride__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1083,'ngsl-3-02',21,'directly','trực tiếp; thẳng; ngay (đối diện)','adverb','[{"en":"You can contact the manager directly by email.","vi":"Bạn có thể liên hệ trực tiếp với quản lý qua email."},{"en":"The hotel is directly opposite the train station.","vi":"Khách sạn nằm ngay đối diện ga tàu."},{"en":"Never look directly at the sun, even with sunglasses.","vi":"Đừng bao giờ nhìn thẳng vào mặt trời, kể cả khi đeo kính râm."}]','[{"phrase":"directly involved"},{"phrase":"directly opposite"},{"phrase":"directly affect"}]',NULL,'/dəˈrektli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/directly__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1084,'ngsl-3-02',22,'heavy','nặng; (mưa, xe cộ) lớn, đông','adjective','[{"en":"This box is too heavy for me to lift.","vi":"Cái hộp này quá nặng, tôi không nhấc nổi."},{"en":"We were late because of heavy traffic on the highway.","vi":"Chúng tôi bị muộn vì xe cộ đông đúc trên đường cao tốc."},{"en":"Heavy rain is expected across the region tomorrow.","vi":"Ngày mai dự báo sẽ có mưa lớn trên khắp khu vực."}]','[{"phrase":"heavy rain"},{"phrase":"heavy traffic"},{"phrase":"heavy meal"}]',NULL,'/ˈhevi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heavy/heavy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1085,'ngsl-3-02',23,'remove','lấy đi, dọn đi; cởi, tháo; tẩy, loại bỏ','verb','[{"en":"Please remove your shoes before entering the house.","vi":"Vui lòng cởi giày trước khi vào nhà."},{"en":"Can this cleaner remove coffee stains from a white shirt?","vi":"Loại nước tẩy này có tẩy được vết cà phê trên áo sơ mi trắng không?"},{"en":"The waiter removed our plates after we finished eating.","vi":"Người phục vụ dọn đĩa đi sau khi chúng tôi ăn xong."}]','[{"phrase":"remove stains"},{"phrase":"remove from"},{"phrase":"completely remove"}]',NULL,'/rɪˈmuːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remov/remove__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1086,'ngsl-3-02',24,'conduct','tiến hành, thực hiện','verb','[{"en":"The company conducted a survey of its customers last year.","vi":"Năm ngoái công ty đã tiến hành khảo sát khách hàng của mình."},{"en":"Scientists are conducting tests on the new medicine.","vi":"Các nhà khoa học đang tiến hành thử nghiệm loại thuốc mới."},{"en":"The interviews will be conducted in English.","vi":"Các buổi phỏng vấn sẽ được thực hiện bằng tiếng Anh."}]','[{"phrase":"conduct a survey"},{"phrase":"conduct research"},{"phrase":"conduct an interview"},{"phrase":"conduct an experiment"}]','danh từ conduct (nhấn âm đầu): hạnh kiểm, cách cư xử','/kənˈdʌkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcond/xconduct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1087,'ngsl-3-02',25,'equipment','thiết bị, dụng cụ','noun','[{"en":"The gym has lots of modern equipment.","vi":"Phòng tập có rất nhiều thiết bị hiện đại."},{"en":"Don''t forget to bring your camping equipment.","vi":"Đừng quên mang theo dụng cụ cắm trại của bạn."},{"en":"All the office equipment was checked before the new staff arrived.","vi":"Toàn bộ thiết bị văn phòng đã được kiểm tra trước khi nhân viên mới đến."}]','[{"phrase":"office equipment"},{"phrase":"sports equipment"},{"phrase":"piece of equipment"},{"phrase":"medical equipment"}]','không đếm được: a piece of equipment','/ɪˈkwɪpmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equip/equipment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1088,'ngsl-3-02',26,'otherwise','nếu không thì; ngoài ra thì; khác đi','adverb','[{"en":"We should leave now; otherwise, we''ll miss the bus.","vi":"Chúng ta nên đi ngay, nếu không thì sẽ lỡ chuyến xe buýt."},{"en":"The soup was a bit salty, but otherwise the meal was great.","vi":"Món súp hơi mặn, nhưng ngoài ra thì bữa ăn rất ngon."},{"en":"Unless you tell me otherwise, I''ll meet you at six.","vi":"Nếu bạn không báo gì khác thì sáu giờ tôi sẽ gặp bạn."}]','[{"phrase":"think otherwise"},{"phrase":"unless otherwise stated"},{"phrase":"say otherwise"}]',NULL,'/ˈʌðərwaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oth/other/otherwise__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1089,'ngsl-3-02',27,'title','tên, tiêu đề (sách, phim, bài hát); danh hiệu','noun','[{"en":"What''s the title of the movie you watched last night?","vi":"Bộ phim bạn xem tối qua tên là gì?"},{"en":"I can''t remember the title of that song.","vi":"Tôi không nhớ tên bài hát đó."},{"en":"She won the national title for the second year in a row.","vi":"Cô ấy giành danh hiệu vô địch quốc gia năm thứ hai liên tiếp."}]','[{"phrase":"job title"},{"phrase":"win the title"},{"phrase":"the title of"}]',NULL,'/ˈtaɪtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tit/title/title__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1090,'ngsl-3-02',28,'extra','thêm; phụ, dư','adjective','[{"en":"Do you have an extra pen I could borrow?","vi":"Bạn có cây bút nào dư cho tôi mượn không?"},{"en":"The hotel charges an extra fee for breakfast.","vi":"Khách sạn tính thêm phí cho bữa sáng."},{"en":"I''m working extra hours this week to save money.","vi":"Tuần này tôi làm thêm giờ để tiết kiệm tiền."}]','[{"phrase":"extra money"},{"phrase":"extra time"},{"phrase":"extra charge"},{"phrase":"extra hours"}]',NULL,'/ˈekstrə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extra__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1091,'ngsl-3-02',29,'executive','giám đốc, người điều hành; ban lãnh đạo','noun','[{"en":"She is a senior executive at a large bank.","vi":"Bà ấy là giám đốc cấp cao ở một ngân hàng lớn."},{"en":"The company''s executives met to discuss the new plan.","vi":"Ban lãnh đạo công ty đã họp để thảo luận kế hoạch mới."},{"en":"My uncle became the chief executive of a small software company.","vi":"Chú tôi trở thành giám đốc điều hành của một công ty phần mềm nhỏ."}]','[{"phrase":"chief executive"},{"phrase":"senior executive"},{"phrase":"business executive"}]',NULL,'/ɪɡˈzekjətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exe/execu/executive__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1092,'ngsl-3-02',30,'chair','ghế; chủ tọa, chủ tịch (cuộc họp, ban)','noun','[{"en":"Please pull up a chair and join us.","vi":"Kéo ghế lại ngồi cùng chúng tôi nhé."},{"en":"This chair is so comfortable that I almost fell asleep.","vi":"Chiếc ghế này êm đến mức tôi suýt ngủ quên."},{"en":"Who is the chair of the parents'' committee this year?","vi":"Năm nay ai là chủ tịch ban phụ huynh?"}]','[{"phrase":"pull up a chair"},{"phrase":"office chair"},{"phrase":"sit in a chair"}]',NULL,'/tʃer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chair/chair__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1093,'ngsl-3-05',1,'apart','cách nhau; riêng ra; rời ra','adverb','[{"en":"Our houses are only about two miles apart.","vi":"Nhà chúng tôi chỉ cách nhau khoảng hai dặm."},{"en":"The twins have never lived apart until this year.","vi":"Cặp song sinh chưa bao giờ sống xa nhau cho đến năm nay."},{"en":"My old bike is starting to fall apart.","vi":"Chiếc xe đạp cũ của tôi bắt đầu hỏng rời ra từng mảnh."}]','[{"phrase":"fall apart"},{"phrase":"live apart"},{"phrase":"far apart"},{"phrase":"apart from"}]','apart from = ngoài ... ra; trừ ... ra','/əˈpɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/apa/apart/apart__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1094,'ngsl-3-05',2,'suit','bộ com-lê; hợp với; thuận tiện cho','noun','[{"en":"He wore a dark suit to the job interview.","vi":"Anh ấy mặc một bộ com-lê tối màu đi phỏng vấn xin việc."},{"en":"That shade of blue really suits you, so you should wear it more.","vi":"Màu xanh đó thật sự rất hợp với bạn, bạn nên mặc nhiều hơn."},{"en":"Does Friday afternoon suit you for the meeting?","vi":"Chiều thứ Sáu có tiện cho bạn để họp không?"}]','[{"phrase":"wear a suit"},{"phrase":"business suit"},{"phrase":"suit your needs"}]',NULL,'/suːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sui/suit_/suit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1095,'ngsl-3-05',3,'federal','(thuộc) liên bang','adjective','[{"en":"The new road was built with federal money.","vi":"Con đường mới được xây bằng tiền của liên bang."},{"en":"Federal law requires all workers to be paid fairly.","vi":"Luật liên bang yêu cầu mọi người lao động phải được trả lương công bằng."},{"en":"She got a job with the federal government after college.","vi":"Cô ấy có việc làm ở chính phủ liên bang sau khi tốt nghiệp đại học."}]','[{"phrase":"federal government"},{"phrase":"federal law"},{"phrase":"federal funding"}]',NULL,'/ˈfedərəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fed/feder/federal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1096,'ngsl-3-05',4,'reveal','tiết lộ; để lộ ra','verb','[{"en":"She finally revealed the secret to her best friend.","vi":"Cuối cùng cô ấy đã tiết lộ bí mật cho bạn thân."},{"en":"The study revealed that most students sleep too little.","vi":"Nghiên cứu cho thấy hầu hết sinh viên ngủ quá ít."},{"en":"When he smiled, he revealed a missing tooth.","vi":"Khi anh ấy cười, để lộ ra một chiếc răng bị mất."}]','[{"phrase":"reveal a secret"},{"phrase":"reveal the truth"},{"phrase":"reveal details"}]',NULL,'/rɪˈviːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revea/reveal__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1097,'ngsl-3-05',5,'percentage','tỷ lệ phần trăm','noun','[{"en":"What percentage of your salary do you save each month?","vi":"Mỗi tháng bạn tiết kiệm bao nhiêu phần trăm lương?"},{"en":"A small percentage of people work from home every day.","vi":"Một tỷ lệ nhỏ người làm việc tại nhà mỗi ngày."},{"en":"The percentage of students passing the exam rose this year.","vi":"Tỷ lệ học sinh thi đỗ đã tăng trong năm nay."}]','[{"phrase":"small percentage"},{"phrase":"high percentage"},{"phrase":"percentage of"}]',NULL,'/pərˈsentɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/percentage__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1098,'ngsl-3-05',6,'peace','hòa bình; sự yên bình','noun','[{"en":"Both countries have lived in peace for many years.","vi":"Hai nước đã sống trong hòa bình suốt nhiều năm."},{"en":"I just want some peace and quiet after work.","vi":"Tôi chỉ muốn được yên tĩnh một chút sau giờ làm."},{"en":"Walking by the lake gives me a sense of peace.","vi":"Đi dạo bên hồ mang lại cho tôi cảm giác yên bình."}]','[{"phrase":"peace and quiet"},{"phrase":"live in peace"},{"phrase":"peace of mind"},{"phrase":"world peace"}]','không đếm được','/piːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pea/peace/peace__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1099,'ngsl-3-05',7,'status','địa vị; tình trạng','noun','[{"en":"In some cultures, owning land gives you high social status.","vi":"Ở một số nền văn hóa, sở hữu đất đai mang lại địa vị xã hội cao."},{"en":"You can check the status of your order online.","vi":"Bạn có thể kiểm tra tình trạng đơn hàng trên mạng."},{"en":"Please fill in your name and marital status on the form.","vi":"Vui lòng điền tên và tình trạng hôn nhân của bạn vào mẫu đơn."}]','[{"phrase":"social status"},{"phrase":"marital status"},{"phrase":"check the status"}]',NULL,'/ˈsteɪtəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/statu/status__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1100,'ngsl-3-05',8,'crime','tội phạm; tội ác','noun','[{"en":"Crime in our neighborhood has dropped over the last few years.","vi":"Tội phạm ở khu phố chúng tôi đã giảm trong vài năm qua."},{"en":"He was sent to prison for a crime he didn''t commit.","vi":"Anh ta bị bỏ tù vì một tội mà anh ta không phạm."},{"en":"The police are still looking for witnesses to the crime.","vi":"Cảnh sát vẫn đang tìm nhân chứng của vụ phạm tội."}]','[{"phrase":"commit a crime"},{"phrase":"crime rate"},{"phrase":"serious crime"}]',NULL,'/kraɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/crime/crime__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1101,'ngsl-3-05',9,'decline','giảm sút; từ chối','verb','[{"en":"Sales of printed newspapers have declined sharply in recent years.","vi":"Doanh số báo in đã giảm mạnh trong những năm gần đây."},{"en":"His health began to decline after he turned eighty.","vi":"Sức khỏe của ông bắt đầu suy giảm sau khi ông bước sang tuổi tám mươi."},{"en":"She politely declined the invitation to the party.","vi":"Cô ấy lịch sự từ chối lời mời dự tiệc."}]','[{"phrase":"decline sharply"},{"phrase":"decline an invitation"},{"phrase":"decline an offer"}]',NULL,'/dɪˈklaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decli/decline__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1102,'ngsl-3-05',10,'decade','thập kỷ; mười năm','noun','[{"en":"The city has changed a lot over the past decade.","vi":"Thành phố đã thay đổi rất nhiều trong mười năm qua."},{"en":"They have been friends for more than three decades.","vi":"Họ đã là bạn của nhau hơn ba mươi năm."},{"en":"Prices will probably keep rising for the next decade.","vi":"Giá cả có lẽ sẽ tiếp tục tăng trong thập kỷ tới."}]','[{"phrase":"past decade"},{"phrase":"next decade"},{"phrase":"for decades"},{"phrase":"decades ago"}]',NULL,'/ˈdekeɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decad/decade__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1103,'ngsl-3-05',11,'launch','ra mắt; phát động; phóng','verb','[{"en":"The company will launch its new phone next month.","vi":"Công ty sẽ ra mắt điện thoại mới vào tháng sau."},{"en":"The school launched a campaign to reduce plastic waste.","vi":"Nhà trường đã phát động một chiến dịch giảm rác thải nhựa."},{"en":"The rocket was launched early on Sunday morning.","vi":"Tên lửa được phóng vào sáng sớm Chủ nhật."}]','[{"phrase":"launch a product"},{"phrase":"launch a campaign"},{"phrase":"launch a rocket"}]',NULL,'/lɔːntʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lau/launc/launch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1104,'ngsl-3-05',12,'warn','cảnh báo; dặn trước','verb','[{"en":"My mother warned me not to walk home alone at night.","vi":"Mẹ tôi đã dặn tôi không được đi bộ về nhà một mình vào ban đêm."},{"en":"Doctors warn that too much sugar can harm your teeth.","vi":"Các bác sĩ cảnh báo rằng quá nhiều đường có thể làm hại răng."},{"en":"I''m warning you, the roads are very icy this morning.","vi":"Tôi báo trước cho bạn nhé, sáng nay đường rất trơn vì băng."}]','[{"phrase":"warn somebody about"},{"phrase":"warn somebody not to"},{"phrase":"strongly warn"}]','warn sb (not) to do sth; warn sb about/of sth','/wɔːrn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/war/warn_/warn__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1105,'ngsl-3-05',13,'consumer','người tiêu dùng','noun','[{"en":"Consumers are spending less money on clothes this year.","vi":"Năm nay người tiêu dùng chi ít tiền hơn cho quần áo."},{"en":"The new law is meant to protect consumers from unsafe products.","vi":"Luật mới nhằm bảo vệ người tiêu dùng khỏi các sản phẩm không an toàn."},{"en":"Many consumers now prefer to shop online.","vi":"Nhiều người tiêu dùng hiện nay thích mua sắm trên mạng hơn."}]','[{"phrase":"consumer goods"},{"phrase":"consumer spending"},{"phrase":"consumer protection"}]',NULL,'/kənˈsuːmər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsumer__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1106,'ngsl-3-05',14,'favor','sự giúp đỡ; ân huệ; sự ủng hộ','noun','[{"en":"Could you do me a favor and close the window?","vi":"Bạn giúp tôi đóng cửa sổ được không?"},{"en":"I owe you a favor for helping me move last week.","vi":"Tôi nợ bạn một lần vì tuần trước đã giúp tôi chuyển nhà."},{"en":"Most of the staff are in favor of the new schedule.","vi":"Phần lớn nhân viên ủng hộ lịch làm việc mới."}]','[{"phrase":"do somebody a favor"},{"phrase":"ask a favor"},{"phrase":"owe somebody a favor"},{"phrase":"in favor of"}]','Mỹ: favor · Anh: favour','/ˈfeɪvər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1107,'ngsl-3-05',15,'dry','khô; khô ráo; hanh khô','adjective','[{"en":"Make sure your hair is dry before you go outside.","vi":"Hãy chắc chắn tóc bạn đã khô trước khi ra ngoài."},{"en":"The weather has been hot and dry all week.","vi":"Thời tiết nóng và khô suốt cả tuần."},{"en":"Keep the medicine in a cool, dry place.","vi":"Hãy bảo quản thuốc ở nơi khô ráo, thoáng mát."}]','[{"phrase":"dry skin"},{"phrase":"dry weather"},{"phrase":"keep dry"},{"phrase":"dry season"}]',NULL,'/draɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dry/dry__/dry__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1108,'ngsl-3-05',16,'partner','bạn đời; đối tác; bạn cùng nhóm','noun','[{"en":"She lives with her partner and their two dogs.","vi":"Cô ấy sống cùng bạn đời và hai con chó của họ."},{"en":"He became a partner in the law firm last year.","vi":"Năm ngoái anh ấy trở thành đối tác trong công ty luật."},{"en":"Find a partner and practice the dialogue together.","vi":"Hãy tìm một bạn cùng cặp và luyện đoạn hội thoại với nhau."}]','[{"phrase":"business partner"},{"phrase":"long-term partner"},{"phrase":"trading partner"}]',NULL,'/ˈpɑːrtnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partn/partner__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1109,'ngsl-3-05',17,'institution','tổ chức; cơ quan; viện','noun','[{"en":"She works for a large financial institution in the city.","vi":"Cô ấy làm việc cho một tổ chức tài chính lớn trong thành phố."},{"en":"Our university is one of the oldest institutions in the country.","vi":"Trường đại học của chúng tôi là một trong những cơ sở lâu đời nhất cả nước."},{"en":"People are losing trust in public institutions.","vi":"Người dân đang mất lòng tin vào các cơ quan nhà nước."}]','[{"phrase":"financial institution"},{"phrase":"educational institution"},{"phrase":"public institution"}]',NULL,'/ˌɪnstɪˈtuːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insti/institution__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1110,'ngsl-3-05',18,'spot','chỗ; điểm; vết đốm','noun','[{"en":"We found a nice spot by the river for our picnic.","vi":"Chúng tôi tìm được một chỗ đẹp bên sông để đi dã ngoại."},{"en":"This beach is a popular spot for tourists.","vi":"Bãi biển này là một điểm đến được du khách ưa thích."},{"en":"There''s a small red spot on the collar of your white shirt.","vi":"Có một vết đốm đỏ nhỏ trên cổ áo sơ mi trắng của bạn."}]','[{"phrase":"parking spot"},{"phrase":"popular spot"},{"phrase":"on the spot"}]','(v) spot = phát hiện, nhận ra','/spɑːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spo/spot_/spot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1111,'ngsl-3-05',19,'horse','con ngựa','noun','[{"en":"My daughter learned to ride a horse last summer.","vi":"Con gái tôi đã học cưỡi ngựa vào mùa hè năm ngoái."},{"en":"The farmer keeps three horses and a few cows.","vi":"Người nông dân nuôi ba con ngựa và vài con bò."},{"en":"We took a horse ride along the beach at sunset.","vi":"Chúng tôi cưỡi ngựa dọc bãi biển lúc hoàng hôn."}]','[{"phrase":"ride a horse"},{"phrase":"horse riding"},{"phrase":"horse race"}]',NULL,'/hɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hor/horse/horse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1112,'ngsl-3-05',20,'eventually','cuối cùng; rốt cuộc','adverb','[{"en":"After two hours of waiting, the bus eventually arrived.","vi":"Sau hai tiếng chờ đợi, cuối cùng xe buýt cũng đến."},{"en":"Don''t worry, you''ll eventually get used to the new job.","vi":"Đừng lo, rồi bạn sẽ quen với công việc mới thôi."},{"en":"They eventually decided to sell the house and move abroad.","vi":"Rốt cuộc họ quyết định bán nhà và chuyển ra nước ngoài."}]','[{"phrase":"eventually decide"},{"phrase":"eventually lead to"},{"phrase":"eventually become"}]','eventually ≠ actually (thực ra)','/ɪˈventʃuəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/event/eventually__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1113,'ngsl-3-05',21,'heat','hơi nóng; sức nóng; nhiệt','noun','[{"en":"I can''t sleep well in this summer heat.","vi":"Tôi không thể ngủ ngon trong cái nóng mùa hè này."},{"en":"Cook the onions over low heat for ten minutes.","vi":"Xào hành trên lửa nhỏ trong mười phút."},{"en":"The heat from the fire kept us warm all night.","vi":"Hơi nóng từ đống lửa giữ ấm cho chúng tôi suốt đêm."}]','[{"phrase":"intense heat"},{"phrase":"low heat"},{"phrase":"summer heat"},{"phrase":"heat wave"}]','không đếm được','/hiːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heat_/heat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1114,'ngsl-3-05',22,'excite','làm phấn khích; kích thích','verb','[{"en":"The idea of traveling to Japan really excites me.","vi":"Ý tưởng đi du lịch Nhật Bản thật sự khiến tôi phấn khích."},{"en":"Don''t excite the kids too much before bedtime.","vi":"Đừng làm bọn trẻ quá phấn khích trước giờ đi ngủ."},{"en":"The team''s new plan didn''t seem to excite anyone.","vi":"Kế hoạch mới của nhóm có vẻ không làm ai hứng thú."}]','[{"phrase":"excite interest"},{"phrase":"excite the imagination"}]','excited (người thấy phấn khích) ≠ exciting (gây phấn khích)','/ɪkˈsaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excit/excite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1115,'ngsl-3-05',23,'reader','người đọc; độc giả','noun','[{"en":"My son has always been a keen reader.","vi":"Con trai tôi luôn là một người rất thích đọc sách."},{"en":"The magazine asked its readers to send in their photos.","vi":"Tạp chí đã mời độc giả gửi ảnh của họ về."},{"en":"The writer uses simple language so young readers can follow.","vi":"Nhà văn dùng ngôn ngữ đơn giản để độc giả nhỏ tuổi có thể theo dõi."}]','[{"phrase":"keen reader"},{"phrase":"avid reader"},{"phrase":"young readers"}]',NULL,'/ˈriːdər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reade/reader__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1116,'ngsl-3-05',24,'importance','tầm quan trọng','noun','[{"en":"Teachers often talk about the importance of good sleep.","vi":"Giáo viên thường nói về tầm quan trọng của giấc ngủ ngon."},{"en":"This decision is of great importance to our company.","vi":"Quyết định này có tầm quan trọng lớn đối với công ty chúng tôi."},{"en":"My parents taught me the importance of saving money.","vi":"Bố mẹ dạy tôi về tầm quan trọng của việc tiết kiệm tiền."}]','[{"phrase":"the importance of"},{"phrase":"great importance"},{"phrase":"stress the importance"}]','không đếm được','/ɪmˈpɔːrtns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impor/importance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1117,'ngsl-3-05',25,'distance','khoảng cách; quãng đường','noun','[{"en":"What''s the distance between Hanoi and Da Nang?","vi":"Khoảng cách giữa Hà Nội và Đà Nẵng là bao xa?"},{"en":"The station is within walking distance of our hotel.","vi":"Nhà ga nằm cách khách sạn của chúng tôi một quãng đi bộ."},{"en":"We could see the mountains in the distance.","vi":"Chúng tôi có thể nhìn thấy những ngọn núi ở phía xa."}]','[{"phrase":"walking distance"},{"phrase":"long distance"},{"phrase":"in the distance"},{"phrase":"short distance"}]',NULL,'/ˈdɪstəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dista/distance__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1118,'ngsl-3-05',26,'guide','hướng dẫn viên; sách hướng dẫn; dẫn đường','noun','[{"en":"Our guide showed us around the old town.","vi":"Hướng dẫn viên dẫn chúng tôi đi tham quan khu phố cổ."},{"en":"I bought a travel guide before my trip to Thailand.","vi":"Tôi đã mua một cuốn sách hướng dẫn du lịch trước chuyến đi Thái Lan."},{"en":"A local farmer guided us through the forest.","vi":"Một người nông dân địa phương dẫn đường cho chúng tôi qua khu rừng."}]','[{"phrase":"tour guide"},{"phrase":"travel guide"},{"phrase":"user guide"}]',NULL,'/ɡaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guide/guide__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1119,'ngsl-3-05',27,'grant','cấp; cho phép; khoản trợ cấp','verb','[{"en":"The bank granted him a loan to start his business.","vi":"Ngân hàng đã cấp cho anh ấy một khoản vay để khởi nghiệp."},{"en":"Visitors are not granted access to this part of the building.","vi":"Khách không được phép vào khu vực này của tòa nhà."},{"en":"She received a government grant to study abroad.","vi":"Cô ấy nhận được một khoản trợ cấp của chính phủ để đi du học."}]','[{"phrase":"grant permission"},{"phrase":"grant access"},{"phrase":"grant a loan"},{"phrase":"take for granted"}]','take sth for granted = coi là đương nhiên','/ɡrænt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grant/grant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1120,'ngsl-3-05',28,'taxi','xe tắc xi','noun','[{"en":"It''s raining, so let''s take a taxi home.","vi":"Trời đang mưa, nên mình đi tắc xi về nhà nhé."},{"en":"Could you call a taxi for me, please?","vi":"Bạn gọi giúp tôi một chiếc tắc xi được không?"},{"en":"The taxi driver helped us carry our bags inside.","vi":"Bác tài xế tắc xi giúp chúng tôi mang hành lý vào trong."}]','[{"phrase":"take a taxi"},{"phrase":"call a taxi"},{"phrase":"taxi driver"},{"phrase":"taxi rank"}]',NULL,'/ˈtæksi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tax/taxi_/taxi__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1121,'ngsl-3-05',29,'feed','cho ăn; nuôi','verb','[{"en":"Can you feed the cat while I''m away?","vi":"Bạn có thể cho mèo ăn trong lúc tôi đi vắng không?"},{"en":"She works two jobs to feed her family.","vi":"Cô ấy làm hai công việc để nuôi gia đình."},{"en":"We fed the ducks with bread at the park.","vi":"Chúng tôi cho vịt ăn bánh mì ở công viên."}]','[{"phrase":"feed a family"},{"phrase":"feed the baby"},{"phrase":"feed the animals"}]','feed – fed – fed','/fiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/feed_/feed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1122,'ngsl-3-05',30,'pain','cơn đau; nỗi đau','noun','[{"en":"I''ve had a pain in my back since yesterday.","vi":"Tôi bị đau lưng từ hôm qua."},{"en":"Take this medicine if the pain gets worse.","vi":"Uống thuốc này nếu cơn đau nặng hơn."},{"en":"Nothing could ease the pain of losing her old dog.","vi":"Không gì có thể xoa dịu nỗi đau mất chú chó già của cô ấy."}]','[{"phrase":"back pain"},{"phrase":"feel pain"},{"phrase":"chest pain"},{"phrase":"ease the pain"}]',NULL,'/peɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pai/pain_/pain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1123,'ngsl-3-06',1,'sector','lĩnh vực; khu vực (kinh tế)','noun','[{"en":"She has worked in the public sector for over ten years.","vi":"Cô ấy đã làm việc trong khu vực công hơn mười năm."},{"en":"Jobs in the tech sector often pay very well.","vi":"Việc làm trong lĩnh vực công nghệ thường được trả lương rất cao."},{"en":"The private sector created thousands of new jobs last year.","vi":"Năm ngoái, khu vực tư nhân đã tạo ra hàng nghìn việc làm mới."}]','[{"phrase":"public sector"},{"phrase":"private sector"},{"phrase":"service sector"},{"phrase":"financial sector"}]',NULL,'/ˈsektər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secto/sector__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1124,'ngsl-3-06',2,'mistake','lỗi; sai lầm','noun','[{"en":"I made a few mistakes in my English homework.","vi":"Tôi đã mắc vài lỗi trong bài tập tiếng Anh."},{"en":"Leaving that job was the biggest mistake of my life.","vi":"Rời bỏ công việc đó là sai lầm lớn nhất đời tôi."},{"en":"Sorry, I took your umbrella by mistake.","vi":"Xin lỗi, tôi cầm nhầm ô của bạn."}]','[{"phrase":"make a mistake"},{"phrase":"big mistake"},{"phrase":"by mistake"},{"phrase":"learn from your mistakes"}]','make a mistake (không dùng do)','/mɪˈsteɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mis/mista/mistake__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1125,'ngsl-3-06',3,'ensure','đảm bảo','verb','[{"en":"Please ensure that all windows are closed before you leave.","vi":"Vui lòng đảm bảo tất cả cửa sổ đã được đóng trước khi bạn rời đi."},{"en":"We check every order carefully to ensure it arrives safely.","vi":"Chúng tôi kiểm tra kỹ từng đơn hàng để đảm bảo hàng đến nơi an toàn."},{"en":"Regular exercise helps ensure that you stay healthy as you age.","vi":"Tập thể dục thường xuyên giúp đảm bảo bạn vẫn khỏe mạnh khi có tuổi."}]','[{"phrase":"ensure that"},{"phrase":"help ensure"},{"phrase":"ensure safety"},{"phrase":"ensure quality"}]','ensure (đảm bảo) ≠ insure (mua bảo hiểm)','/ɪnˈʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ens/ensur/ensure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1126,'ngsl-3-06',4,'satisfy','làm hài lòng; đáp ứng','verb','[{"en":"It''s hard to satisfy every customer, but we always try.","vi":"Thật khó làm hài lòng mọi khách hàng, nhưng chúng tôi luôn cố gắng."},{"en":"Nothing I do ever seems to satisfy my boss.","vi":"Dường như chẳng việc gì tôi làm có thể khiến sếp hài lòng."},{"en":"Your application does not satisfy the requirements for this program.","vi":"Hồ sơ của bạn không đáp ứng các yêu cầu của chương trình này."}]','[{"phrase":"satisfy customers"},{"phrase":"satisfy the requirements"},{"phrase":"satisfy demand"},{"phrase":"satisfy your curiosity"}]',NULL,'/ˈsætɪsfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sat/satis/satisfy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1127,'ngsl-3-06',5,'chief','chính; chủ yếu; trưởng','adjective','[{"en":"Cost was our chief concern when we chose a new apartment.","vi":"Chi phí là mối lo chính của chúng tôi khi chọn căn hộ mới."},{"en":"Her chief reason for moving was to be near her parents.","vi":"Lý do chủ yếu khiến cô ấy chuyển nhà là để ở gần bố mẹ."},{"en":"He works as the chief engineer at a large factory.","vi":"Anh ấy làm kỹ sư trưởng tại một nhà máy lớn."}]','[{"phrase":"chief concern"},{"phrase":"chief reason"},{"phrase":"chief executive"}]',NULL,'/tʃiːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/chief/chief__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1128,'ngsl-3-06',6,'cool','mát; bình tĩnh; ngầu','adjective','[{"en":"It''s a bit cool this evening, so bring a jacket.","vi":"Tối nay trời hơi mát, nên hãy mang theo áo khoác."},{"en":"Try to stay cool, even when customers get angry.","vi":"Hãy cố giữ bình tĩnh, ngay cả khi khách hàng nổi giận."},{"en":"That''s a really cool bike you got for your birthday.","vi":"Chiếc xe đạp bạn được tặng dịp sinh nhật ngầu thật đấy."}]','[{"phrase":"cool weather"},{"phrase":"stay cool"},{"phrase":"cool breeze"},{"phrase":"cool water"}]',NULL,'/kuːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/cool_/cool__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1129,'ngsl-3-06',7,'expert','chuyên gia','noun','[{"en":"You should ask an expert before you buy an old house.","vi":"Bạn nên hỏi ý kiến chuyên gia trước khi mua một ngôi nhà cũ."},{"en":"She is an expert on children''s health.","vi":"Cô ấy là chuyên gia về sức khỏe trẻ em."},{"en":"Experts say we should sleep at least seven hours a night.","vi":"Các chuyên gia cho rằng chúng ta nên ngủ ít nhất bảy tiếng mỗi đêm."}]','[{"phrase":"expert on"},{"phrase":"expert in"},{"phrase":"health expert"},{"phrase":"expert advice"}]',NULL,'/ˈekspɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/expert__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1130,'ngsl-3-06',8,'wave','sóng; làn sóng; cái vẫy tay','noun','[{"en":"The children laughed as the waves hit their feet.","vi":"Bọn trẻ cười vang khi những con sóng vỗ vào chân."},{"en":"A new wave of tourists arrives in the city every summer.","vi":"Mỗi mùa hè, một làn sóng du khách mới lại đổ về thành phố."},{"en":"She gave me a friendly wave from across the street.","vi":"Cô ấy thân thiện vẫy tay chào tôi từ bên kia đường."}]','[{"phrase":"big waves"},{"phrase":"a wave of"},{"phrase":"give a wave"},{"phrase":"heat wave"}]',NULL,'/weɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wav/wave_/wave__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1131,'ngsl-3-06',9,'south','phía nam; miền nam; hướng nam','noun','[{"en":"My grandparents live in a small village in the south.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ ở miền nam."},{"en":"The wind is blowing from the south today.","vi":"Hôm nay gió thổi từ hướng nam."},{"en":"The hotel is about twenty kilometers to the south of town.","vi":"Khách sạn nằm cách thị trấn khoảng hai mươi cây số về phía nam."}]','[{"phrase":"in the south"},{"phrase":"to the south"},{"phrase":"from the south"},{"phrase":"south coast"}]',NULL,'/saʊθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/south/south__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1132,'ngsl-3-06',10,'labor','lao động; nhân công','noun','[{"en":"Labor costs have risen sharply in the last few years.","vi":"Chi phí nhân công đã tăng mạnh trong vài năm gần đây."},{"en":"The farm depends on cheap labor during the harvest season.","vi":"Trang trại phụ thuộc vào nhân công giá rẻ trong mùa thu hoạch."},{"en":"Farming still involves a lot of manual labor, even today.","vi":"Ngay cả ngày nay, làm nông vẫn đòi hỏi rất nhiều lao động chân tay."}]','[{"phrase":"labor costs"},{"phrase":"cheap labor"},{"phrase":"manual labor"},{"phrase":"labor market"}]','Mỹ: labor · Anh: labour','/ˈleɪbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1133,'ngsl-3-06',11,'surface','bề mặt; mặt nước; bề ngoài','noun','[{"en":"Clean the kitchen surfaces with warm, soapy water.","vi":"Lau các bề mặt trong bếp bằng nước ấm pha xà phòng."},{"en":"Leaves were floating on the surface of the lake.","vi":"Lá cây trôi nổi trên mặt hồ."},{"en":"On the surface, he seemed calm, but he was very nervous.","vi":"Bề ngoài anh ấy có vẻ bình tĩnh, nhưng thật ra rất lo lắng."}]','[{"phrase":"smooth surface"},{"phrase":"flat surface"},{"phrase":"on the surface"},{"phrase":"surface of the water"}]',NULL,'/ˈsɜːrfɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surfa/surface__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1134,'ngsl-3-06',12,'library','thư viện','noun','[{"en":"I borrowed three books from the library last week.","vi":"Tuần trước tôi đã mượn ba cuốn sách ở thư viện."},{"en":"The students often study in the library after class.","vi":"Sinh viên thường học ở thư viện sau giờ học."},{"en":"Our town is building a new public library near the park.","vi":"Thị trấn chúng tôi đang xây một thư viện công cộng mới gần công viên."}]','[{"phrase":"public library"},{"phrase":"school library"},{"phrase":"library book"},{"phrase":"library card"}]','library (thư viện) ≠ bookstore (hiệu sách)','/ˈlaɪbreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lib/libra/library__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1135,'ngsl-3-06',13,'excellent','xuất sắc; tuyệt vời','adjective','[{"en":"The food at that little restaurant is excellent.","vi":"Đồ ăn ở nhà hàng nhỏ đó thật tuyệt vời."},{"en":"She speaks excellent English after living abroad for years.","vi":"Sau nhiều năm sống ở nước ngoài, cô ấy nói tiếng Anh xuất sắc."},{"en":"You did an excellent job on the presentation today.","vi":"Hôm nay bạn đã làm bài thuyết trình rất xuất sắc."}]','[{"phrase":"excellent job"},{"phrase":"excellent condition"},{"phrase":"excellent opportunity"},{"phrase":"excellent food"}]',NULL,'/ˈeksələnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excel/excellent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1136,'ngsl-3-06',14,'edge','mép; rìa; cạnh','noun','[{"en":"Don''t put your glass so close to the edge of the table.","vi":"Đừng để cốc sát mép bàn như thế."},{"en":"They live in a quiet house on the edge of town.","vi":"Họ sống trong một ngôi nhà yên tĩnh ở rìa thị trấn."},{"en":"He cut his finger on the sharp edge of the paper.","vi":"Anh ấy bị đứt tay vì cạnh sắc của tờ giấy."}]','[{"phrase":"on the edge of"},{"phrase":"edge of the table"},{"phrase":"sharp edge"},{"phrase":"the water''s edge"}]',NULL,'/edʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edg/edge_/edge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1137,'ngsl-3-06',15,'camp','trại; khu cắm trại','noun','[{"en":"The kids are going to summer camp for two weeks.","vi":"Bọn trẻ sẽ đi trại hè trong hai tuần."},{"en":"We set up camp near the river before it got dark.","vi":"Chúng tôi dựng trại gần con sông trước khi trời tối."},{"en":"After a long hike, we finally returned to camp.","vi":"Sau một chuyến đi bộ đường dài, cuối cùng chúng tôi cũng về đến trại."}]','[{"phrase":"summer camp"},{"phrase":"set up camp"},{"phrase":"training camp"}]',NULL,'/kæmp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cam/camp_/camp_1_us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1138,'ngsl-3-06',16,'audience','khán giả; người xem; người nghe','noun','[{"en":"The audience clapped loudly at the end of the show.","vi":"Khán giả vỗ tay rất lớn khi buổi diễn kết thúc."},{"en":"She felt nervous speaking in front of such a large audience.","vi":"Cô ấy thấy hồi hộp khi phát biểu trước đông khán giả như vậy."},{"en":"This TV program is aimed at a young audience.","vi":"Chương trình truyền hình này hướng đến người xem trẻ tuổi."}]','[{"phrase":"large audience"},{"phrase":"live audience"},{"phrase":"target audience"},{"phrase":"young audience"}]',NULL,'/ˈɔːdiəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aud/audie/audience__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1139,'ngsl-3-06',17,'lift','nâng; nhấc lên','verb','[{"en":"Can you help me lift this heavy box onto the shelf?","vi":"Bạn giúp tôi nhấc cái hộp nặng này lên kệ được không?"},{"en":"She lifted the baby out of the car seat.","vi":"Cô ấy nhấc em bé ra khỏi ghế ngồi trên ô tô."},{"en":"My brother lifts weights at the gym three times a week.","vi":"Anh trai tôi tập tạ ở phòng gym ba lần một tuần."}]','[{"phrase":"lift weights"},{"phrase":"lift your head"},{"phrase":"lift something heavy"}]',NULL,'/lɪft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lif/lift_/lift__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1140,'ngsl-3-06',18,'procedure','thủ tục; quy trình','noun','[{"en":"Please follow the correct procedure when you report a problem.","vi":"Vui lòng làm đúng quy trình khi bạn báo cáo sự cố."},{"en":"The procedure for getting a visa can take several weeks.","vi":"Thủ tục xin thị thực có thể mất vài tuần."},{"en":"All staff must learn the safety procedures in case of fire.","vi":"Tất cả nhân viên phải nắm được các quy trình an toàn khi có hỏa hoạn."}]','[{"phrase":"follow the procedure"},{"phrase":"safety procedures"},{"phrase":"standard procedure"},{"phrase":"emergency procedure"}]',NULL,'/prəˈsiːdʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/procedure__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1141,'ngsl-3-06',19,'email','email; thư điện tử','noun','[{"en":"I''ll send you an email with all the details tonight.","vi":"Tối nay tôi sẽ gửi cho bạn một email có đầy đủ chi tiết."},{"en":"She checks her email every morning before breakfast.","vi":"Sáng nào cô ấy cũng kiểm tra email trước khi ăn sáng."},{"en":"Did you get my email about the meeting on Friday?","vi":"Bạn đã nhận được email của tôi về cuộc họp hôm thứ Sáu chưa?"}]','[{"phrase":"send an email"},{"phrase":"check your email"},{"phrase":"email address"},{"phrase":"reply to an email"}]',NULL,'/ˈiːmeɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ema/email/email__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1142,'ngsl-3-06',20,'global','toàn cầu','adjective','[{"en":"Climate change is a global problem that affects everyone.","vi":"Biến đổi khí hậu là vấn đề toàn cầu ảnh hưởng đến tất cả mọi người."},{"en":"The company now sells its products in the global market.","vi":"Công ty hiện bán sản phẩm của mình trên thị trường toàn cầu."},{"en":"Global demand for electric cars keeps growing every year.","vi":"Nhu cầu toàn cầu về ô tô điện tiếp tục tăng mỗi năm."}]','[{"phrase":"global market"},{"phrase":"global economy"},{"phrase":"global warming"},{"phrase":"global problem"}]',NULL,'/ˈɡləʊbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/glo/globa/global__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1143,'ngsl-3-06',21,'struggle','vật lộn; chật vật','verb','[{"en":"Many families struggle to pay their rent each month.","vi":"Nhiều gia đình chật vật để trả tiền thuê nhà mỗi tháng."},{"en":"I struggled with math when I was at school.","vi":"Hồi còn đi học, tôi rất chật vật với môn toán."},{"en":"The old man struggled to open the heavy door.","vi":"Ông cụ vật lộn mãi mới mở được cánh cửa nặng."}]','[{"phrase":"struggle to pay"},{"phrase":"struggle with"},{"phrase":"struggle to survive"}]',NULL,'/ˈstrʌɡl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strug/struggle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1144,'ngsl-3-06',22,'advertise','quảng cáo; đăng tin','verb','[{"en":"The shop advertises its sales in the local newspaper.","vi":"Cửa hàng quảng cáo các đợt giảm giá trên báo địa phương."},{"en":"They are advertising for a new cook on their website.","vi":"Họ đang đăng tin tuyển đầu bếp mới trên trang web của mình."},{"en":"We advertised our old car online and sold it in two days.","vi":"Chúng tôi đăng tin bán chiếc xe cũ trên mạng và bán được sau hai ngày."}]','[{"phrase":"advertise for"},{"phrase":"advertise online"},{"phrase":"advertise products"}]',NULL,'/ˈædvərtaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/adver/advertise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1145,'ngsl-3-06',23,'select','chọn; lựa chọn','verb','[{"en":"Select a language from the list and press Enter.","vi":"Chọn một ngôn ngữ trong danh sách rồi nhấn Enter."},{"en":"She was selected to play for the school team.","vi":"Cô ấy được chọn để chơi cho đội của trường."},{"en":"We carefully select the freshest fruit for our customers.","vi":"Chúng tôi cẩn thận lựa chọn trái cây tươi nhất cho khách hàng."}]','[{"phrase":"select from"},{"phrase":"carefully select"},{"phrase":"be selected for"}]',NULL,'/sɪˈlekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/selec/select__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1146,'ngsl-3-06',24,'surround','bao quanh; vây quanh','verb','[{"en":"The old house is surrounded by tall trees.","vi":"Ngôi nhà cũ được bao quanh bởi những hàng cây cao."},{"en":"Fans surrounded the singer as she left the hotel.","vi":"Người hâm mộ vây quanh nữ ca sĩ khi cô rời khách sạn."},{"en":"It''s important to surround yourself with people who support you.","vi":"Điều quan trọng là để bản thân được bao quanh bởi những người ủng hộ bạn."}]','[{"phrase":"surrounded by"},{"phrase":"surround yourself with"},{"phrase":"completely surrounded"}]',NULL,'/səˈraʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surro/surround__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1147,'ngsl-3-06',25,'extent','mức độ; phạm vi','noun','[{"en":"Doctors are still checking the extent of his injuries.","vi":"Các bác sĩ vẫn đang kiểm tra mức độ thương tích của anh ấy."},{"en":"I agree with you to some extent, but not completely.","vi":"Ở một mức độ nào đó tôi đồng ý với bạn, nhưng không hoàn toàn."},{"en":"We didn''t realize the full extent of the damage until morning.","vi":"Mãi đến sáng chúng tôi mới nhận ra hết mức độ thiệt hại."}]','[{"phrase":"to some extent"},{"phrase":"to a large extent"},{"phrase":"the full extent"},{"phrase":"extent of the damage"}]',NULL,'/ɪkˈstent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1148,'ngsl-3-06',26,'river','sông; dòng sông','noun','[{"en":"We walked along the river after dinner.","vi":"Chúng tôi đi dạo dọc bờ sông sau bữa tối."},{"en":"The children love swimming in the river in summer.","vi":"Bọn trẻ thích bơi ở sông vào mùa hè."},{"en":"A new bridge is being built across the river.","vi":"Một cây cầu mới đang được xây bắc qua sông."}]','[{"phrase":"along the river"},{"phrase":"across the river"},{"phrase":"cross the river"}]',NULL,'/ˈrɪvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/riv/river/river__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1149,'ngsl-3-06',27,'annual','hằng năm; thường niên','adjective','[{"en":"The company holds its annual meeting every March.","vi":"Công ty tổ chức cuộc họp thường niên vào tháng Ba hằng năm."},{"en":"Our town''s annual flower festival attracts lots of visitors.","vi":"Lễ hội hoa hằng năm của thị trấn chúng tôi thu hút rất nhiều du khách."},{"en":"My annual salary went up by ten percent this year.","vi":"Năm nay lương hằng năm của tôi tăng mười phần trăm."}]','[{"phrase":"annual meeting"},{"phrase":"annual salary"},{"phrase":"annual report"},{"phrase":"annual event"}]',NULL,'/ˈænjuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annua/annual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1150,'ngsl-3-06',28,'fully','hoàn toàn; đầy đủ','adverb','[{"en":"The hotel was fully booked for the holiday weekend.","vi":"Khách sạn đã kín hết phòng vào dịp nghỉ lễ cuối tuần."},{"en":"It takes about two hours to fully charge my phone.","vi":"Phải mất khoảng hai tiếng để sạc đầy điện thoại của tôi."},{"en":"I don''t fully understand what the teacher wants us to do.","vi":"Tôi chưa hoàn toàn hiểu thầy giáo muốn chúng tôi làm gì."}]','[{"phrase":"fully understand"},{"phrase":"fully booked"},{"phrase":"fully aware"},{"phrase":"fully charged"}]',NULL,'/ˈfʊli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/ful/fully/fully__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1151,'ngsl-3-06',29,'contrast','sự tương phản; sự trái ngược','noun','[{"en":"There is a sharp contrast between life in the city and the countryside.","vi":"Có sự trái ngược rõ rệt giữa cuộc sống ở thành phố và ở nông thôn."},{"en":"The weather was cold, in contrast to the warm week before.","vi":"Thời tiết lạnh, trái ngược với tuần ấm áp trước đó."},{"en":"I like the contrast between the white walls and the dark floor.","vi":"Tôi thích sự tương phản giữa tường trắng và sàn nhà tối màu."}]','[{"phrase":"in contrast"},{"phrase":"in contrast to"},{"phrase":"sharp contrast"},{"phrase":"contrast between"}]',NULL,'/ˈkɑːntræst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1152,'ngsl-3-06',30,'roll','lăn; cuộn','verb','[{"en":"The ball rolled under the car and I couldn''t reach it.","vi":"Quả bóng lăn xuống gầm xe và tôi không với tới được."},{"en":"Roll up the map carefully and put it back in the box.","vi":"Hãy cuộn tấm bản đồ lại cẩn thận rồi cất vào hộp."},{"en":"Tears rolled down her cheeks as she said goodbye.","vi":"Nước mắt lăn dài trên má cô ấy khi cô nói lời tạm biệt."}]','[{"phrase":"roll down"},{"phrase":"roll up"},{"phrase":"roll over"}]',NULL,'/rəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rol/roll_/roll__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1153,'ngsl-3-07',1,'reality','thực tế; hiện thực','noun','[{"en":"In reality, the job was much harder than I expected.","vi":"Trên thực tế, công việc khó hơn tôi nghĩ nhiều."},{"en":"Our dream of buying a house finally became a reality last year.","vi":"Giấc mơ mua nhà của chúng tôi cuối cùng đã thành hiện thực vào năm ngoái."},{"en":"Sometimes people watch movies to escape from reality for a while.","vi":"Đôi khi người ta xem phim để tạm thoát khỏi thực tế."}]','[{"phrase":"in reality"},{"phrase":"become a reality"},{"phrase":"escape from reality"},{"phrase":"face reality"}]',NULL,'/riˈæləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reali/reality__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1154,'ngsl-3-07',2,'photograph','bức ảnh','noun','[{"en":"She keeps an old photograph of her grandparents on her desk.","vi":"Cô ấy để một bức ảnh cũ của ông bà trên bàn làm việc."},{"en":"Could you take a photograph of us in front of the fountain?","vi":"Bạn có thể chụp giúp chúng tôi một bức ảnh trước đài phun nước không?"},{"en":"The photographs from our wedding are still in a box somewhere.","vi":"Những bức ảnh cưới của chúng tôi vẫn còn nằm trong một cái hộp ở đâu đó."}]','[{"phrase":"take a photograph"},{"phrase":"old photograph"},{"phrase":"family photograph"}]',NULL,'/ˈfəʊtəɡræf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pho/photo/photograph__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1155,'ngsl-3-07',3,'artist','nghệ sĩ; họa sĩ','noun','[{"en":"My sister is a talented artist who paints mostly landscapes.","vi":"Chị tôi là một họa sĩ tài năng, chủ yếu vẽ tranh phong cảnh."},{"en":"The festival brings together local artists and musicians every summer.","vi":"Lễ hội quy tụ các nghệ sĩ và nhạc sĩ địa phương vào mỗi mùa hè."},{"en":"Which artist painted the picture hanging in your living room?","vi":"Họa sĩ nào đã vẽ bức tranh treo trong phòng khách nhà bạn?"}]','[{"phrase":"talented artist"},{"phrase":"local artist"},{"phrase":"famous artist"}]',NULL,'/ˈɑːrtɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/art/artis/artist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1156,'ngsl-3-07',4,'conflict','xung đột; mâu thuẫn','noun','[{"en":"There is often conflict between work and family life.","vi":"Công việc và cuộc sống gia đình thường có mâu thuẫn với nhau."},{"en":"The two neighbors tried to settle their conflict without going to court.","vi":"Hai người hàng xóm cố gắng giải quyết mâu thuẫn mà không phải ra tòa."},{"en":"A good manager knows how to handle conflict within a team.","vi":"Một người quản lý giỏi biết cách xử lý xung đột trong nhóm."}]','[{"phrase":"resolve a conflict"},{"phrase":"conflict between"},{"phrase":"handle conflict"},{"phrase":"avoid conflict"}]',NULL,'/ˈkɑːnflɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconflict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1157,'ngsl-3-07',5,'entire','toàn bộ; cả','adjective','[{"en":"I spent the entire weekend cleaning the house.","vi":"Tôi dành cả cuối tuần để dọn dẹp nhà cửa."},{"en":"The entire class passed the final exam this year.","vi":"Năm nay cả lớp đều đỗ kỳ thi cuối kỳ."},{"en":"She read the entire book in just one evening.","vi":"Cô ấy đọc hết cả cuốn sách chỉ trong một buổi tối."}]','[{"phrase":"the entire day"},{"phrase":"the entire family"},{"phrase":"the entire class"}]',NULL,'/ɪnˈtaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entir/entire__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1158,'ngsl-3-07',6,'presence','sự có mặt; sự hiện diện','noun','[{"en":"Your presence at the meeting is very important to us.","vi":"Sự có mặt của bạn tại cuộc họp rất quan trọng đối với chúng tôi."},{"en":"The children behaved well in the presence of their teacher.","vi":"Bọn trẻ cư xử ngoan ngoãn khi có mặt giáo viên."},{"en":"Police increased their presence in the city center during the festival.","vi":"Cảnh sát tăng cường sự hiện diện ở trung tâm thành phố trong dịp lễ hội."}]','[{"phrase":"in the presence of"},{"phrase":"police presence"},{"phrase":"strong presence"}]',NULL,'/ˈprezns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/presence__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1159,'ngsl-3-07',7,'crowd','đám đông','noun','[{"en":"A large crowd gathered outside the stadium before the game.","vi":"Một đám đông lớn tụ tập bên ngoài sân vận động trước trận đấu."},{"en":"I lost sight of my son for a moment in the crowd.","vi":"Tôi mất dấu con trai một lúc giữa đám đông."},{"en":"We left early to avoid the crowds at the train station.","vi":"Chúng tôi đi sớm để tránh đám đông ở ga tàu."}]','[{"phrase":"large crowd"},{"phrase":"huge crowd"},{"phrase":"avoid the crowds"},{"phrase":"in the crowd"}]',NULL,'/kraʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cro/crowd/crowd__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1160,'ngsl-3-07',8,'corner','góc; góc phố','noun','[{"en":"There is a small bakery on the corner of our street.","vi":"Có một tiệm bánh nhỏ ở góc phố nhà chúng tôi."},{"en":"Put the plant in the corner near the window.","vi":"Hãy đặt chậu cây vào góc gần cửa sổ."},{"en":"Turn left at the next corner, and you will see the bank.","vi":"Rẽ trái ở góc đường tiếp theo, bạn sẽ thấy ngân hàng."}]','[{"phrase":"on the corner"},{"phrase":"in the corner"},{"phrase":"around the corner"},{"phrase":"street corner"}]',NULL,'/ˈkɔːrnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corne/corner__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1161,'ngsl-3-07',9,'gas','khí; khí đốt; xăng','noun','[{"en":"Plants take in a gas called carbon dioxide from the air.","vi":"Cây hấp thụ một loại khí gọi là carbon dioxide từ không khí."},{"en":"Please turn off the gas before you leave the kitchen.","vi":"Hãy tắt bếp ga trước khi rời khỏi bếp."},{"en":"We need to stop and get gas before the highway.","vi":"Chúng ta cần dừng lại đổ xăng trước khi lên đường cao tốc."}]','[{"phrase":"natural gas"},{"phrase":"gas stove"},{"phrase":"run out of gas"},{"phrase":"turn off the gas"}]','Mỹ: gas · Anh: petrol (xăng)','/ɡæs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gas/gas__/gas__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1162,'ngsl-3-07',10,'shift','ca làm việc; sự thay đổi','noun','[{"en":"My brother works the night shift at the hospital.","vi":"Anh tôi làm ca đêm ở bệnh viện."},{"en":"She starts her shift at six in the morning.","vi":"Cô ấy bắt đầu ca làm lúc sáu giờ sáng."},{"en":"There has been a shift in how people shop recently.","vi":"Gần đây đã có sự thay đổi trong cách mọi người mua sắm."}]','[{"phrase":"night shift"},{"phrase":"day shift"},{"phrase":"work a shift"},{"phrase":"a shift in"}]',NULL,'/ʃɪft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shift/shift__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1163,'ngsl-3-07',11,'net','lưới; mạng internet','noun','[{"en":"The fishermen pulled their nets out of the water at dawn.","vi":"Những người đánh cá kéo lưới lên khỏi mặt nước lúc bình minh."},{"en":"The ball hit the net and bounced back onto my side.","vi":"Quả bóng chạm lưới và bật ngược lại phía sân của tôi."},{"en":"My grandmother learned to surf the net at seventy.","vi":"Bà tôi học lướt mạng khi đã bảy mươi tuổi."}]','[{"phrase":"fishing net"},{"phrase":"surf the net"},{"phrase":"safety net"}]',NULL,'/net/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/net/net__/net__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1164,'ngsl-3-07',12,'category','loại; hạng mục','noun','[{"en":"The books are sorted into categories such as history and science.","vi":"Sách được sắp xếp thành các loại như lịch sử và khoa học."},{"en":"Which category does this product belong to?","vi":"Sản phẩm này thuộc loại nào?"},{"en":"She won the prize in the best new writer category.","vi":"Cô ấy đã giành giải ở hạng mục nhà văn mới xuất sắc nhất."}]','[{"phrase":"fall into a category"},{"phrase":"belong to a category"},{"phrase":"broad category"},{"phrase":"age category"}]',NULL,'/ˈkætəɡɔːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/categ/category__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1165,'ngsl-3-07',13,'secretary','thư ký','noun','[{"en":"Please leave a message with my secretary if I am out.","vi":"Nếu tôi đi vắng, vui lòng để lại lời nhắn cho thư ký của tôi."},{"en":"The secretary booked a meeting room for Friday afternoon.","vi":"Cô thư ký đã đặt một phòng họp cho chiều thứ Sáu."},{"en":"My mother worked as a school secretary for twenty years.","vi":"Mẹ tôi làm thư ký trường học trong hai mươi năm."}]','[{"phrase":"personal secretary"},{"phrase":"school secretary"},{"phrase":"work as a secretary"}]',NULL,'/ˈsekrəteri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secre/secretary__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1166,'ngsl-3-07',14,'defense','sự bảo vệ; sự phòng thủ; hàng phòng ngự','noun','[{"en":"Eating well is your body''s best defense against illness.","vi":"Ăn uống đầy đủ là cách tốt nhất để cơ thể bạn chống lại bệnh tật."},{"en":"He spoke in defense of his friend at the meeting.","vi":"Anh ấy lên tiếng bênh vực bạn mình tại cuộc họp."},{"en":"Our team needs a stronger defense to win this season.","vi":"Đội chúng tôi cần hàng phòng ngự mạnh hơn để giành chiến thắng mùa này."}]','[{"phrase":"in defense of"},{"phrase":"defense against"},{"phrase":"strong defense"},{"phrase":"self-defense"}]','Mỹ: defense · Anh: defence','/dɪˈfens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defen/defence__us_12.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1167,'ngsl-3-07',15,'quick','nhanh; ngắn, chóng vánh','adjective','[{"en":"Can I ask you a quick question before you go?","vi":"Tôi hỏi bạn một câu ngắn trước khi bạn đi được không?"},{"en":"We had a quick lunch and went back to work.","vi":"Chúng tôi ăn trưa vội rồi quay lại làm việc."},{"en":"She is a quick learner and picks up new skills easily.","vi":"Cô ấy học rất nhanh và dễ dàng tiếp thu kỹ năng mới."}]','[{"phrase":"quick question"},{"phrase":"quick lunch"},{"phrase":"quick learner"},{"phrase":"have a quick look"}]',NULL,'/kwɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quick/quick__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1168,'ngsl-3-07',16,'cook','nấu ăn; nấu','verb','[{"en":"My father cooks dinner for the family every Sunday.","vi":"Bố tôi nấu bữa tối cho cả nhà vào mỗi Chủ nhật."},{"en":"Cook the rice for about fifteen minutes.","vi":"Nấu cơm trong khoảng mười lăm phút."},{"en":"I never learned how to cook when I lived with my parents.","vi":"Hồi sống với bố mẹ, tôi chưa bao giờ học nấu ăn."}]','[{"phrase":"cook dinner"},{"phrase":"cook a meal"},{"phrase":"learn to cook"}]',NULL,'/kʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/cook_/cook__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1169,'ngsl-3-07',17,'spread','lan rộng; phết; trải ra','verb','[{"en":"The news spread quickly through the small town.","vi":"Tin tức lan nhanh khắp thị trấn nhỏ."},{"en":"She spread butter on her toast and poured some coffee.","vi":"Cô ấy phết bơ lên bánh mì nướng và rót một ít cà phê."},{"en":"We spread a blanket on the grass and had a picnic.","vi":"Chúng tôi trải một tấm chăn lên bãi cỏ rồi ngồi ăn dã ngoại."}]','[{"phrase":"spread quickly"},{"phrase":"spread butter"},{"phrase":"spread the word"}]','spread – spread – spread','/spred/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spr/sprea/spread__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1170,'ngsl-3-07',18,'nuclear','hạt nhân','adjective','[{"en":"The country gets much of its electricity from nuclear energy.","vi":"Đất nước này lấy phần lớn điện từ năng lượng hạt nhân."},{"en":"Many people worry about the safety of nuclear power plants.","vi":"Nhiều người lo ngại về độ an toàn của các nhà máy điện hạt nhân."},{"en":"In a nuclear family, children live with just their parents.","vi":"Trong gia đình hạt nhân, con cái chỉ sống cùng bố mẹ."}]','[{"phrase":"nuclear energy"},{"phrase":"nuclear power"},{"phrase":"nuclear power plant"},{"phrase":"nuclear family"}]',NULL,'/ˈnuːkliər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nuc/nucle/nuclear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1171,'ngsl-3-07',19,'scale','quy mô; thang đo; cái cân','noun','[{"en":"The company wants to produce the new phone on a large scale.","vi":"Công ty muốn sản xuất chiếc điện thoại mới trên quy mô lớn."},{"en":"On a scale of one to ten, how was the movie?","vi":"Theo thang điểm từ một đến mười, bộ phim thế nào?"},{"en":"I stepped on the bathroom scale and got a surprise.","vi":"Tôi bước lên cân trong phòng tắm và giật mình."}]','[{"phrase":"on a large scale"},{"phrase":"on a scale of"},{"phrase":"bathroom scale"},{"phrase":"the scale of the problem"}]',NULL,'/skeɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sca/scale/scale__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1172,'ngsl-3-07',20,'driver','tài xế; người lái xe','noun','[{"en":"The bus driver waited for the old man to sit down.","vi":"Tài xế xe buýt đợi ông cụ ngồi xuống."},{"en":"My sister is a careful driver and has never had an accident.","vi":"Chị tôi lái xe cẩn thận và chưa bao giờ gặp tai nạn."},{"en":"Ask the taxi driver to take you straight to the hotel.","vi":"Hãy bảo tài xế taxi đưa bạn thẳng đến khách sạn."}]','[{"phrase":"bus driver"},{"phrase":"taxi driver"},{"phrase":"careful driver"},{"phrase":"driver''s license"}]',NULL,'/ˈdraɪvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dri/drive/driver__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1173,'ngsl-3-07',21,'ball','quả bóng','noun','[{"en":"The kids are playing ball in the backyard.","vi":"Bọn trẻ đang chơi bóng ở sân sau."},{"en":"He kicked the ball over the fence by mistake.","vi":"Cậu ấy lỡ đá quả bóng bay qua hàng rào."},{"en":"Can you throw the ball to the dog, please?","vi":"Bạn ném quả bóng cho con chó được không?"}]','[{"phrase":"kick a ball"},{"phrase":"throw a ball"},{"phrase":"catch a ball"},{"phrase":"play ball"}]',NULL,'/bɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bal/ball_/ball__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1174,'ngsl-3-07',22,'cry','khóc; kêu to','verb','[{"en":"The baby started to cry as soon as we left.","vi":"Em bé bắt đầu khóc ngay khi chúng tôi rời đi."},{"en":"She cried with joy when she heard the good news.","vi":"Cô ấy khóc vì vui sướng khi nghe tin tốt."},{"en":"Someone was crying for help from the river.","vi":"Có ai đó đang kêu cứu từ dưới sông."}]','[{"phrase":"start to cry"},{"phrase":"cry for help"},{"phrase":"cry with joy"}]',NULL,'/kraɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cry/cry__/cry__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1175,'ngsl-3-07',23,'introduction','sự giới thiệu; phần mở đầu','noun','[{"en":"After a short introduction, the teacher started the lesson.","vi":"Sau phần giới thiệu ngắn, giáo viên bắt đầu bài học."},{"en":"Let me make the introductions before we start dinner.","vi":"Để tôi giới thiệu mọi người với nhau trước khi ăn tối nhé."},{"en":"Your essay needs a clearer introduction and conclusion.","vi":"Bài luận của bạn cần phần mở đầu và kết luận rõ ràng hơn."}]','[{"phrase":"short introduction"},{"phrase":"brief introduction"},{"phrase":"make the introductions"},{"phrase":"introduction to"}]',NULL,'/ˌɪntrəˈdʌkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intro/introduction__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1176,'ngsl-3-07',24,'requirement','yêu cầu; điều kiện','noun','[{"en":"A good level of English is a requirement for this job.","vi":"Trình độ tiếng Anh tốt là một yêu cầu của công việc này."},{"en":"Please check the entry requirements before you apply to the university.","vi":"Vui lòng kiểm tra điều kiện đầu vào trước khi nộp đơn vào trường đại học."},{"en":"Does the new building meet all the safety requirements?","vi":"Tòa nhà mới có đáp ứng tất cả các yêu cầu an toàn không?"}]','[{"phrase":"meet the requirements"},{"phrase":"entry requirements"},{"phrase":"safety requirements"},{"phrase":"minimum requirement"}]',NULL,'/rɪˈkwaɪərmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/requi/requirement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1177,'ngsl-3-07',25,'north','phía bắc; miền bắc','noun','[{"en":"My grandparents live in a small village in the north.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ ở miền Bắc."},{"en":"The wind is coming from the north today.","vi":"Hôm nay gió thổi từ phía bắc."},{"en":"The lake is about twenty miles north of the city.","vi":"Hồ nằm cách thành phố khoảng hai mươi dặm về phía bắc."}]','[{"phrase":"in the north"},{"phrase":"to the north"},{"phrase":"north of"},{"phrase":"the far north"}]',NULL,'/nɔːrθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/north/north__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1178,'ngsl-3-07',26,'confirm','xác nhận; khẳng định','verb','[{"en":"Please call the hotel to confirm our booking.","vi":"Làm ơn gọi cho khách sạn để xác nhận việc đặt phòng của chúng ta."},{"en":"The test results confirmed that he had a broken arm.","vi":"Kết quả kiểm tra khẳng định anh ấy bị gãy tay."},{"en":"Can you confirm the time of tomorrow''s meeting by email?","vi":"Bạn có thể xác nhận giờ họp ngày mai qua email không?"}]','[{"phrase":"confirm a booking"},{"phrase":"confirm a reservation"},{"phrase":"officially confirm"}]',NULL,'/kənˈfɜːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfirm__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1179,'ngsl-3-07',27,'senior','cấp cao; cao tuổi','adjective','[{"en":"She was promoted to a senior position last month.","vi":"Tháng trước cô ấy được thăng lên một vị trí cấp cao."},{"en":"My uncle is a senior manager at a large bank.","vi":"Chú tôi là quản lý cấp cao tại một ngân hàng lớn."},{"en":"Senior citizens can travel on the bus for free.","vi":"Người cao tuổi được đi xe buýt miễn phí."}]','[{"phrase":"senior manager"},{"phrase":"senior position"},{"phrase":"senior citizen"},{"phrase":"senior staff"}]',NULL,'/ˈsiːniər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/senio/senior__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1180,'ngsl-3-07',28,'photo','ảnh','noun','[{"en":"Let''s take a photo together before the sun goes down.","vi":"Mình chụp một tấm ảnh chung trước khi mặt trời lặn nhé."},{"en":"He posted a few photos from his trip online.","vi":"Anh ấy đăng vài tấm ảnh từ chuyến đi lên mạng."},{"en":"This photo of my dad was taken in 1990.","vi":"Tấm ảnh này của bố tôi được chụp vào năm 1990."}]','[{"phrase":"take a photo"},{"phrase":"post a photo"},{"phrase":"family photo"},{"phrase":"photo album"}]',NULL,'/ˈfəʊtəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pho/photo/photo__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1181,'ngsl-3-07',29,'refuse','từ chối; không chịu','verb','[{"en":"He refused to answer any questions about his private life.","vi":"Anh ấy từ chối trả lời mọi câu hỏi về đời tư."},{"en":"My little brother refuses to eat vegetables.","vi":"Em trai tôi không chịu ăn rau."},{"en":"They offered her the job, but she refused.","vi":"Họ mời cô ấy nhận công việc đó, nhưng cô ấy đã từ chối."}]','[{"phrase":"refuse to do something"},{"phrase":"refuse an offer"},{"phrase":"flatly refuse"}]',NULL,'/rɪˈfjuːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refus/refuse__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1182,'ngsl-3-07',30,'transport','giao thông vận tải; phương tiện đi lại','noun','[{"en":"The city has good public transport, so I rarely drive.","vi":"Thành phố có giao thông công cộng tốt nên tôi hiếm khi lái xe."},{"en":"Bikes are a cheap and healthy form of transport.","vi":"Xe đạp là một phương tiện đi lại rẻ và tốt cho sức khỏe."},{"en":"The price includes hotel, meals and transport to the airport.","vi":"Giá đã bao gồm khách sạn, bữa ăn và xe đưa đón ra sân bay."}]','[{"phrase":"public transport"},{"phrase":"form of transport"},{"phrase":"means of transport"},{"phrase":"transport costs"}]','Anh: public transport · Mỹ: public transportation','/ˈtrænspɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transport__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1183,'ngsl-3-08',1,'emerge','xuất hiện; hiện ra; lộ ra','verb','[{"en":"The sun finally emerged from behind the clouds in the afternoon.","vi":"Buổi chiều, mặt trời cuối cùng cũng ló ra từ sau những đám mây."},{"en":"A cat suddenly emerged from under the car and ran away.","vi":"Một con mèo bất ngờ chui ra từ gầm xe rồi chạy mất."},{"en":"New details about the accident emerged a few days later.","vi":"Vài ngày sau, những chi tiết mới về vụ tai nạn đã lộ ra."}]','[{"phrase":"emerge from"},{"phrase":"begin to emerge"},{"phrase":"new evidence emerged"}]','emerge from + nơi chốn','/ɪˈmɜːrdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eme/emerg/emerge__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1184,'ngsl-3-08',2,'map','bản đồ','noun','[{"en":"Can you show me where we are on the map?","vi":"Bạn có thể chỉ cho tôi chúng ta đang ở đâu trên bản đồ không?"},{"en":"I always check the map on my phone before I drive somewhere new.","vi":"Tôi luôn xem bản đồ trên điện thoại trước khi lái xe đến nơi mới."},{"en":"There is a large map of the world on the classroom wall.","vi":"Trên tường lớp học có một tấm bản đồ thế giới lớn."}]','[{"phrase":"on the map"},{"phrase":"read a map"},{"phrase":"a map of the world"},{"phrase":"street map"}]',NULL,'/mæp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/map/map__/map__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1185,'ngsl-3-08',3,'concept','khái niệm; ý tưởng','noun','[{"en":"Young children often find the concept of time hard to understand.","vi":"Trẻ nhỏ thường thấy khái niệm thời gian khó hiểu."},{"en":"The teacher used simple examples to explain a difficult concept.","vi":"Giáo viên dùng những ví dụ đơn giản để giải thích một khái niệm khó."},{"en":"Our team liked the concept, but the design still needs work.","vi":"Nhóm chúng tôi thích ý tưởng này, nhưng thiết kế vẫn cần chỉnh sửa thêm."}]','[{"phrase":"basic concept"},{"phrase":"the concept of"},{"phrase":"understand the concept"},{"phrase":"new concept"}]',NULL,'/ˈkɑːnsept/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcept__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1186,'ngsl-3-08',4,'island','hòn đảo; đảo','noun','[{"en":"We took a boat to a small island near the coast.","vi":"Chúng tôi đi thuyền ra một hòn đảo nhỏ gần bờ biển."},{"en":"Only a few hundred people live on the island all year.","vi":"Chỉ có vài trăm người sống trên đảo quanh năm."},{"en":"Have you ever spent a holiday on a tropical island?","vi":"Bạn đã bao giờ đi nghỉ ở một hòn đảo nhiệt đới chưa?"}]','[{"phrase":"on the island"},{"phrase":"small island"},{"phrase":"tropical island"},{"phrase":"desert island"}]','Chữ s trong island không đọc','/ˈaɪlənd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/isl/islan/island__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1187,'ngsl-3-08',5,'reform','cải cách; sự cải tổ','noun','[{"en":"Many teachers believe the school system needs serious reform.","vi":"Nhiều giáo viên cho rằng hệ thống trường học cần được cải cách nghiêm túc."},{"en":"The tax reform will make life easier for small businesses.","vi":"Cuộc cải cách thuế sẽ giúp các doanh nghiệp nhỏ dễ thở hơn."},{"en":"The city introduced several reforms to improve public transport.","vi":"Thành phố đã đưa ra một số cải cách để cải thiện giao thông công cộng."}]','[{"phrase":"economic reform"},{"phrase":"tax reform"},{"phrase":"education reform"},{"phrase":"introduce reforms"}]',NULL,'/rɪˈfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refor/reform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1188,'ngsl-3-08',6,'neither','không cái nào (trong hai); cũng không','determiner','[{"en":"Neither answer is correct, so please try again.","vi":"Cả hai câu trả lời đều không đúng, vậy hãy thử lại nhé."},{"en":"I tried two shirts, but neither of them fit me well.","vi":"Tôi đã thử hai chiếc áo, nhưng chẳng chiếc nào vừa với tôi."},{"en":"She doesn''t eat meat, and neither does her husband.","vi":"Cô ấy không ăn thịt, và chồng cô ấy cũng không."}]','[{"phrase":"neither of them"},{"phrase":"neither ... nor"},{"phrase":"neither do I"}]','neither A nor B = không A cũng không B','/ˈniːðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nei/neith/neither__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1189,'ngsl-3-08',7,'football','bóng đá; quả bóng đá','noun','[{"en":"My brother plays football with his friends every Saturday morning.","vi":"Anh trai tôi đá bóng với bạn bè vào mỗi sáng thứ Bảy."},{"en":"We watched the football match on TV last night.","vi":"Tối qua chúng tôi xem trận bóng đá trên TV."},{"en":"The kids kicked the football over the fence into the garden.","vi":"Bọn trẻ đá quả bóng qua hàng rào rơi vào khu vườn."}]','[{"phrase":"play football"},{"phrase":"football match"},{"phrase":"football team"},{"phrase":"football fan"}]','Ở Mỹ, football thường chỉ bóng bầu dục; bóng đá là soccer','/ˈfʊtbɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/footb/football__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1190,'ngsl-3-08',8,'survive','sống sót; tồn tại; vượt qua','verb','[{"en":"Everyone on the boat survived the storm without serious injuries.","vi":"Mọi người trên thuyền đều sống sót qua cơn bão mà không bị thương nặng."},{"en":"Plants cannot survive for long without water and light.","vi":"Cây cối không thể sống lâu nếu thiếu nước và ánh sáng."},{"en":"The small shop survived for fifty years in the same street.","vi":"Cửa hàng nhỏ đã tồn tại năm mươi năm trên cùng một con phố."}]','[{"phrase":"survive the accident"},{"phrase":"manage to survive"},{"phrase":"struggle to survive"},{"phrase":"survive on"}]',NULL,'/sərˈvaɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/survi/survive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1191,'ngsl-3-08',9,'flight','chuyến bay; sự bay','noun','[{"en":"Our flight to Singapore was delayed for two hours.","vi":"Chuyến bay của chúng tôi đến Singapore bị hoãn hai tiếng."},{"en":"I usually try to sleep during long flights.","vi":"Tôi thường cố gắng ngủ trong những chuyến bay dài."},{"en":"She booked a cheap flight home for the holidays.","vi":"Cô ấy đã đặt một chuyến bay giá rẻ về nhà dịp nghỉ lễ."}]','[{"phrase":"book a flight"},{"phrase":"catch a flight"},{"phrase":"long flight"},{"phrase":"flight attendant"}]',NULL,'/flaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fli/fligh/flight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1192,'ngsl-3-08',10,'left','bên trái; (phía) trái','adjective','[{"en":"He broke his left arm when he fell off his bike.","vi":"Anh ấy bị gãy tay trái khi ngã xe đạp."},{"en":"Turn left at the next corner, and the bank is on your right.","vi":"Rẽ trái ở góc đường tiếp theo, ngân hàng nằm bên tay phải bạn."},{"en":"The bathroom is the second door on the left.","vi":"Nhà vệ sinh là cánh cửa thứ hai bên trái."}]','[{"phrase":"turn left"},{"phrase":"on the left"},{"phrase":"left hand"},{"phrase":"left side"}]','left cũng là quá khứ của leave (rời đi)','/left/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lef/left_/left__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1193,'ngsl-3-08',11,'solve','giải quyết; giải (bài toán)','verb','[{"en":"We need to solve this problem before the customer calls again.","vi":"Chúng ta cần giải quyết vấn đề này trước khi khách hàng gọi lại."},{"en":"Talking openly can help solve many family arguments.","vi":"Nói chuyện cởi mở có thể giúp giải quyết nhiều cuộc cãi vã trong gia đình."},{"en":"My son solved all the math problems in ten minutes.","vi":"Con trai tôi đã giải hết các bài toán trong mười phút."}]','[{"phrase":"solve a problem"},{"phrase":"solve a puzzle"},{"phrase":"solve the mystery"},{"phrase":"help solve"}]',NULL,'/sɑːlv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solve/solve__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1194,'ngsl-3-08',12,'neighbor','hàng xóm; người láng giềng','noun','[{"en":"Our new neighbors invited us over for dinner on Sunday.","vi":"Hàng xóm mới mời chúng tôi sang ăn tối vào Chủ nhật."},{"en":"My neighbor waters my plants when I''m away on vacation.","vi":"Người hàng xóm tưới cây giúp tôi khi tôi đi nghỉ."},{"en":"The kids next door are always noisy, but they are good neighbors.","vi":"Lũ trẻ nhà bên lúc nào cũng ồn ào, nhưng họ là những người hàng xóm tốt."}]','[{"phrase":"next-door neighbor"},{"phrase":"good neighbor"},{"phrase":"new neighbors"},{"phrase":"close neighbor"}]','Anh: neighbour · Mỹ: neighbor','/ˈneɪbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1195,'ngsl-3-08',13,'background','lý lịch; xuất thân; nền (phía sau)','noun','[{"en":"Students in my class come from many different backgrounds.","vi":"Sinh viên trong lớp tôi đến từ nhiều hoàn cảnh xuất thân khác nhau."},{"en":"She has a strong background in science and engineering.","vi":"Cô ấy có nền tảng vững chắc về khoa học và kỹ thuật."},{"en":"In the photo, you can see the mountains in the background.","vi":"Trong bức ảnh, bạn có thể thấy những ngọn núi ở phía sau."}]','[{"phrase":"in the background"},{"phrase":"family background"},{"phrase":"different backgrounds"},{"phrase":"background music"}]',NULL,'/ˈbækɡraʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bac/backg/background__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1196,'ngsl-3-08',14,'technique','kỹ thuật; phương pháp','noun','[{"en":"The coach showed us a simple technique for breathing while swimming.","vi":"Huấn luyện viên chỉ cho chúng tôi một kỹ thuật thở đơn giản khi bơi."},{"en":"This cooking technique keeps the vegetables fresh and green.","vi":"Kỹ thuật nấu ăn này giữ cho rau tươi và xanh."},{"en":"Have you tried any new techniques for learning vocabulary?","vi":"Bạn đã thử phương pháp mới nào để học từ vựng chưa?"}]','[{"phrase":"use a technique"},{"phrase":"learn a technique"},{"phrase":"new technique"},{"phrase":"basic technique"}]',NULL,'/tekˈniːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technique__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1197,'ngsl-3-08',15,'traffic','giao thông; xe cộ lưu thông','noun','[{"en":"I was late for work because the traffic was terrible.","vi":"Tôi đi làm muộn vì giao thông quá tệ."},{"en":"There is always heavy traffic on this road in the morning.","vi":"Buổi sáng con đường này lúc nào cũng đông xe."},{"en":"We got stuck in traffic for an hour on the way home.","vi":"Trên đường về nhà, chúng tôi bị kẹt xe một tiếng."}]','[{"phrase":"heavy traffic"},{"phrase":"stuck in traffic"},{"phrase":"traffic jam"},{"phrase":"traffic lights"}]','không đếm được','/ˈtræfɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/traff/traffic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1198,'ngsl-3-08',16,'improvement','sự cải thiện; sự tiến bộ','noun','[{"en":"There has been a big improvement in your English this year.","vi":"Năm nay tiếng Anh của bạn đã tiến bộ rất nhiều."},{"en":"The new manager made several improvements to the office.","vi":"Người quản lý mới đã thực hiện một số cải thiện cho văn phòng."},{"en":"Doctors say there has been a slight improvement in his condition.","vi":"Các bác sĩ cho biết tình trạng của anh ấy đã cải thiện đôi chút."}]','[{"phrase":"big improvement"},{"phrase":"improvement in"},{"phrase":"room for improvement"},{"phrase":"make improvements"}]',NULL,'/ɪmˈpruːvmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impro/improvement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1199,'ngsl-3-08',17,'tool','dụng cụ; công cụ','noun','[{"en":"My father keeps all his tools in a box in the garage.","vi":"Bố tôi cất tất cả dụng cụ trong một chiếc hộp ở nhà để xe."},{"en":"You need the right tools to fix a bike properly.","vi":"Bạn cần đúng dụng cụ để sửa xe đạp cho tốt."},{"en":"The internet can be a useful tool for learning languages.","vi":"Internet có thể là một công cụ hữu ích để học ngoại ngữ."}]','[{"phrase":"useful tool"},{"phrase":"garden tools"},{"phrase":"power tools"},{"phrase":"a tool for"}]',NULL,'/tuːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/too/tool_/tool__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1200,'ngsl-3-08',18,'consequence','hậu quả; kết quả','noun','[{"en":"If you break the rules, you must accept the consequences.","vi":"Nếu bạn vi phạm nội quy, bạn phải chấp nhận hậu quả."},{"en":"Missing too many classes can have serious consequences for your grades.","vi":"Nghỉ học quá nhiều có thể gây hậu quả nghiêm trọng cho điểm số của bạn."},{"en":"He didn''t think about the consequences before he quit his job.","vi":"Anh ấy đã không nghĩ đến hậu quả trước khi nghỉ việc."}]','[{"phrase":"serious consequences"},{"phrase":"accept the consequences"},{"phrase":"as a consequence"},{"phrase":"consequences of"}]',NULL,'/ˈkɑːnsɪkwens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsequence__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1201,'ngsl-3-08',19,'circumstance','hoàn cảnh; tình huống','noun','[{"en":"Under normal circumstances, the train takes about three hours.","vi":"Trong điều kiện bình thường, tàu chạy mất khoảng ba tiếng."},{"en":"You should not open this door under any circumstances.","vi":"Bạn không được mở cánh cửa này trong bất kỳ trường hợp nào."},{"en":"Given the circumstances, I think you made the right decision.","vi":"Xét theo hoàn cảnh, tôi nghĩ bạn đã quyết định đúng."}]','[{"phrase":"under the circumstances"},{"phrase":"under no circumstances"},{"phrase":"in certain circumstances"},{"phrase":"personal circumstances"}]','Thường dùng số nhiều: circumstances','/ˈsɜːrkəmstæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cir/circu/circumstance__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1202,'ngsl-3-08',20,'smoke','khói','noun','[{"en":"We saw black smoke coming from the kitchen window.","vi":"Chúng tôi thấy khói đen bốc ra từ cửa sổ nhà bếp."},{"en":"The smoke from the fire made everyone''s eyes water.","vi":"Khói từ đám cháy làm mắt mọi người chảy nước."},{"en":"I opened all the windows to let the smoke out.","vi":"Tôi mở hết cửa sổ cho khói bay ra ngoài."}]','[{"phrase":"black smoke"},{"phrase":"cigarette smoke"},{"phrase":"smoke alarm"},{"phrase":"a cloud of smoke"}]','không đếm được; smoke (v) = hút thuốc','/sməʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/smo/smoke/smoke__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1203,'ngsl-3-08',21,'reaction','phản ứng','noun','[{"en":"What was your parents'' reaction when you told them the news?","vi":"Bố mẹ bạn phản ứng thế nào khi bạn báo tin cho họ?"},{"en":"Some people have an allergic reaction to nuts.","vi":"Một số người bị phản ứng dị ứng với các loại hạt."},{"en":"The new product got a very positive reaction from customers.","vi":"Sản phẩm mới nhận được phản ứng rất tích cực từ khách hàng."}]','[{"phrase":"reaction to"},{"phrase":"allergic reaction"},{"phrase":"positive reaction"},{"phrase":"first reaction"}]',NULL,'/riˈækʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/react/reaction__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1204,'ngsl-3-08',22,'rain','mưa; cơn mưa','noun','[{"en":"Don''t forget your umbrella, because heavy rain is expected today.","vi":"Đừng quên mang ô nhé, vì hôm nay dự báo có mưa to."},{"en":"We waited in a café until the rain stopped.","vi":"Chúng tôi ngồi đợi trong quán cà phê cho đến khi tạnh mưa."},{"en":"The kids love walking in the rain in their boots.","vi":"Bọn trẻ rất thích mang ủng đi dạo dưới mưa."}]','[{"phrase":"heavy rain"},{"phrase":"in the rain"},{"phrase":"the rain stops"},{"phrase":"light rain"}]',NULL,'/reɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rai/rain_/rain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1205,'ngsl-3-08',23,'busy','bận; đông đúc; (máy) bận','adjective','[{"en":"I''m too busy to go out for lunch today.","vi":"Hôm nay tôi bận quá không đi ăn trưa được."},{"en":"The market is always busy on weekend mornings.","vi":"Chợ lúc nào cũng đông đúc vào các buổi sáng cuối tuần."},{"en":"I called the office twice, but the line was busy.","vi":"Tôi đã gọi đến văn phòng hai lần nhưng máy đều bận."}]','[{"phrase":"busy day"},{"phrase":"busy street"},{"phrase":"keep busy"},{"phrase":"busy with"}]','busy + V-ing: bận làm gì','/ˈbɪzi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bus/busy_/busy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1206,'ngsl-3-08',24,'lesson','bài học; buổi học','noun','[{"en":"My daughter has piano lessons twice a week after school.","vi":"Con gái tôi học piano hai buổi mỗi tuần sau giờ học."},{"en":"Today''s lesson is about how to write a formal email.","vi":"Bài học hôm nay là về cách viết một email trang trọng."},{"en":"Losing my wallet taught me an important lesson.","vi":"Việc làm mất ví đã dạy cho tôi một bài học quan trọng."}]','[{"phrase":"take lessons"},{"phrase":"learn a lesson"},{"phrase":"driving lessons"},{"phrase":"teach someone a lesson"}]',NULL,'/ˈlesn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/les/lesso/lesson__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1207,'ngsl-3-08',25,'brain','não; bộ óc; trí tuệ','noun','[{"en":"Getting enough sleep is important for a healthy brain.","vi":"Ngủ đủ giấc rất quan trọng để có một bộ não khỏe mạnh."},{"en":"Reading every day keeps your brain active as you get older.","vi":"Đọc sách mỗi ngày giúp não bạn luôn hoạt động khi về già."},{"en":"She has the brains to become a great doctor.","vi":"Cô ấy đủ thông minh để trở thành một bác sĩ giỏi."}]','[{"phrase":"human brain"},{"phrase":"brain damage"},{"phrase":"use your brain"},{"phrase":"brain activity"}]',NULL,'/breɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bra/brain/brain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1208,'ngsl-3-08',26,'mass','khối; số đông; đại chúng','noun','[{"en":"A mass of dark clouds was moving toward the city.","vi":"Một khối mây đen đang tiến về phía thành phố."},{"en":"The singer''s songs were popular with the masses.","vi":"Những bài hát của ca sĩ đó được đông đảo quần chúng yêu thích."},{"en":"Mass tourism has changed life in many small beach towns.","vi":"Du lịch đại chúng đã làm thay đổi cuộc sống ở nhiều thị trấn biển nhỏ."}]','[{"phrase":"a mass of"},{"phrase":"the masses"},{"phrase":"mass production"},{"phrase":"mass media"}]',NULL,'/mæs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mas/mass_/mass__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1209,'ngsl-3-08',27,'funny','buồn cười; hài hước; kỳ lạ','adjective','[{"en":"My grandfather always tells funny stories at family dinners.","vi":"Ông tôi luôn kể những câu chuyện hài hước trong các bữa tối gia đình."},{"en":"We watched a really funny movie and laughed all night.","vi":"Chúng tôi xem một bộ phim rất buồn cười và cười suốt cả tối."},{"en":"The engine is making a funny noise, so I should check it.","vi":"Động cơ đang phát ra tiếng kêu lạ, nên tôi phải kiểm tra."}]','[{"phrase":"funny story"},{"phrase":"funny thing"},{"phrase":"funny feeling"},{"phrase":"look funny"}]',NULL,'/ˈfʌni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funny/funny__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1210,'ngsl-3-08',28,'contribute','đóng góp; góp phần','verb','[{"en":"Everyone contributed some money to buy a gift for the teacher.","vi":"Mọi người góp một ít tiền để mua quà tặng cô giáo."},{"en":"Lack of sleep can contribute to health problems.","vi":"Thiếu ngủ có thể góp phần gây ra các vấn đề sức khỏe."},{"en":"I hope I can contribute useful ideas at the meeting.","vi":"Tôi hy vọng có thể đóng góp những ý tưởng hữu ích trong cuộc họp."}]','[{"phrase":"contribute to"},{"phrase":"contribute money"},{"phrase":"contribute ideas"},{"phrase":"contribute significantly"}]','contribute to + danh từ/V-ing','/kənˈtrɪbjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontribute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1211,'ngsl-3-08',29,'failure','sự thất bại; sự hỏng hóc','noun','[{"en":"Don''t be afraid of failure, because everyone makes mistakes.","vi":"Đừng sợ thất bại, vì ai cũng mắc sai lầm."},{"en":"His first business was a failure, but he tried again.","vi":"Việc kinh doanh đầu tiên của anh ấy thất bại, nhưng anh ấy đã thử lại."},{"en":"The flight was canceled because of an engine failure.","vi":"Chuyến bay bị hủy do động cơ gặp sự cố."}]','[{"phrase":"fear of failure"},{"phrase":"end in failure"},{"phrase":"complete failure"},{"phrase":"engine failure"}]',NULL,'/ˈfeɪljər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/failu/failure__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1212,'ngsl-3-08',30,'schedule','lịch trình; thời gian biểu','noun','[{"en":"My work schedule is very busy this week.","vi":"Lịch làm việc của tôi tuần này rất dày đặc."},{"en":"The project is two weeks behind schedule.","vi":"Dự án đang chậm hai tuần so với tiến độ."},{"en":"Can you check the train schedule for Sunday morning?","vi":"Bạn xem giúp lịch tàu sáng Chủ nhật được không?"}]','[{"phrase":"busy schedule"},{"phrase":"on schedule"},{"phrase":"behind schedule"},{"phrase":"train schedule"}]',NULL,'/ˈskedʒuːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/sched/schedule__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1213,'ngsl-3-09',1,'speaker','người phát biểu, diễn giả; người nói (một ngôn ngữ); loa','noun','[{"en":"The guest speaker talked about her years working in Africa.","vi":"Diễn giả khách mời đã nói về những năm cô ấy làm việc ở châu Phi."},{"en":"He is a native speaker of Spanish, so ask him for help.","vi":"Anh ấy là người bản ngữ nói tiếng Tây Ban Nha, nên hãy nhờ anh ấy giúp."},{"en":"Can you turn down the speakers? The music is too loud.","vi":"Bạn vặn nhỏ loa được không? Nhạc to quá."}]','[{"phrase":"guest speaker"},{"phrase":"native speaker"},{"phrase":"public speaker"},{"phrase":"keynote speaker"}]',NULL,'/ˈspiːkər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speak/speaker__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1214,'ngsl-3-09',2,'bottom','đáy; phần dưới cùng, cuối','noun','[{"en":"I found my keys at the bottom of my bag.","vi":"Tôi tìm thấy chìa khóa ở dưới đáy túi."},{"en":"Please sign your name at the bottom of the page.","vi":"Vui lòng ký tên ở cuối trang."},{"en":"We waited at the bottom of the hill for the others.","vi":"Chúng tôi đợi những người khác ở chân đồi."}]','[{"phrase":"at the bottom of"},{"phrase":"the bottom of the page"},{"phrase":"bottom line"}]',NULL,'/ˈbɑːtəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bot/botto/bottom__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1215,'ngsl-3-09',3,'adopt','nhận nuôi; áp dụng','verb','[{"en":"They decided to adopt a little girl from another country.","vi":"Họ quyết định nhận nuôi một bé gái từ nước khác."},{"en":"We adopted a cat from the animal shelter last month.","vi":"Tháng trước chúng tôi đã nhận nuôi một con mèo từ trại cứu hộ động vật."},{"en":"The school has adopted a new approach to teaching reading.","vi":"Trường đã áp dụng một cách tiếp cận mới trong việc dạy đọc."}]','[{"phrase":"adopt a child"},{"phrase":"adopt an approach"},{"phrase":"adopt a policy"}]','adopt (nhận nuôi, áp dụng) ≠ adapt (thích nghi)','/əˈdɑːpt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ado/adopt/adopt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1216,'ngsl-3-09',4,'combine','kết hợp; phối hợp','verb','[{"en":"Combine the flour and sugar in a large bowl.","vi":"Trộn bột mì và đường trong một cái bát lớn."},{"en":"It''s hard to combine a full-time job with studying.","vi":"Thật khó để vừa làm việc toàn thời gian vừa đi học."},{"en":"Our team won because we combined our different skills.","vi":"Đội chúng tôi thắng vì đã kết hợp những kỹ năng khác nhau của mọi người."}]','[{"phrase":"combine with"},{"phrase":"combine work with family"},{"phrase":"combined effort"}]','combine A with B','/kəmˈbaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/combi/combine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1217,'ngsl-3-09',5,'mountain','núi','noun','[{"en":"We climbed the mountain and enjoyed the view from the top.","vi":"Chúng tôi leo lên núi và ngắm cảnh từ trên đỉnh."},{"en":"My grandparents live in a small village in the mountains.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ trên núi."},{"en":"Snow covers the mountains for most of the winter.","vi":"Tuyết phủ kín những ngọn núi gần như suốt mùa đông."}]','[{"phrase":"climb a mountain"},{"phrase":"in the mountains"},{"phrase":"mountain top"},{"phrase":"mountain range"}]',NULL,'/ˈmaʊntn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mount/mountain__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1218,'ngsl-3-09',6,'waste','lãng phí; rác thải','noun','[{"en":"That meeting was a complete waste of time.","vi":"Cuộc họp đó hoàn toàn là phí thời gian."},{"en":"Buying clothes you never wear is a waste of money.","vi":"Mua quần áo mà không bao giờ mặc là lãng phí tiền bạc."},{"en":"The city is trying to reduce the amount of food waste.","vi":"Thành phố đang cố gắng giảm lượng rác thải thực phẩm."}]','[{"phrase":"a waste of time"},{"phrase":"a waste of money"},{"phrase":"food waste"},{"phrase":"reduce waste"}]',NULL,'/weɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/was/waste/waste__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1219,'ngsl-3-09',7,'hide','trốn; giấu, che giấu','verb','[{"en":"The children hid behind the door when their father came home.","vi":"Bọn trẻ trốn sau cánh cửa khi bố chúng về nhà."},{"en":"She hid the birthday present under her bed.","vi":"Cô ấy giấu món quà sinh nhật dưới gầm giường."},{"en":"He tried to hide his feelings, but everyone could see he was upset.","vi":"Anh ấy cố che giấu cảm xúc, nhưng ai cũng thấy anh ấy đang buồn."}]','[{"phrase":"hide something from someone"},{"phrase":"hide behind"},{"phrase":"hide your feelings"},{"phrase":"hide the truth"}]','hide – hid – hidden','/haɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hid/hide_/hide__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1220,'ngsl-3-09',8,'marriage','hôn nhân; cuộc hôn nhân','noun','[{"en":"My parents have had a long and happy marriage.","vi":"Bố mẹ tôi đã có một cuộc hôn nhân lâu dài và hạnh phúc."},{"en":"She has two children from her first marriage.","vi":"Cô ấy có hai con từ cuộc hôn nhân đầu tiên."},{"en":"Good communication is important in any marriage.","vi":"Giao tiếp tốt rất quan trọng trong bất kỳ cuộc hôn nhân nào."}]','[{"phrase":"happy marriage"},{"phrase":"first marriage"},{"phrase":"marriage proposal"}]','marriage (n) – married (adj) – marry (v)','/ˈmærɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/marri/marriage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1221,'ngsl-3-09',9,'ticket','vé; giấy phạt','noun','[{"en":"I bought two tickets for the concert on Saturday.","vi":"Tôi đã mua hai vé xem buổi hòa nhạc vào thứ Bảy."},{"en":"How much is a round-trip ticket to the city center?","vi":"Vé khứ hồi vào trung tâm thành phố giá bao nhiêu?"},{"en":"He got a parking ticket because he stayed too long.","vi":"Anh ấy bị phạt đỗ xe vì đỗ quá lâu."}]','[{"phrase":"buy a ticket"},{"phrase":"train ticket"},{"phrase":"one-way ticket"},{"phrase":"parking ticket"}]',NULL,'/ˈtɪkɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tic/ticke/ticket__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1222,'ngsl-3-09',10,'meal','bữa ăn','noun','[{"en":"We usually eat our main meal in the evening.","vi":"Chúng tôi thường ăn bữa chính vào buổi tối."},{"en":"Thank you for the lovely meal last night.","vi":"Cảm ơn bạn vì bữa ăn tuyệt vời tối qua."},{"en":"Try not to snack between meals if you want to lose weight.","vi":"Nếu muốn giảm cân, hãy cố đừng ăn vặt giữa các bữa ăn."}]','[{"phrase":"main meal"},{"phrase":"have a meal"},{"phrase":"cook a meal"},{"phrase":"between meals"}]',NULL,'/miːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/meal_/meal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1223,'ngsl-3-09',11,'colleague','đồng nghiệp','noun','[{"en":"I often have lunch with my colleagues from the office.","vi":"Tôi thường ăn trưa với các đồng nghiệp ở văn phòng."},{"en":"A colleague helped me finish the report on time.","vi":"Một đồng nghiệp đã giúp tôi hoàn thành báo cáo đúng hạn."},{"en":"She gets along well with her new colleagues.","vi":"Cô ấy hòa hợp với các đồng nghiệp mới."}]','[{"phrase":"work colleague"},{"phrase":"former colleague"},{"phrase":"colleagues at work"}]',NULL,'/ˈkɑːliːɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/colleague__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1224,'ngsl-3-09',12,'bag','túi, bao; cặp','noun','[{"en":"Don''t forget to bring a bag when you go shopping.","vi":"Đừng quên mang theo túi khi đi mua sắm."},{"en":"She put her laptop in her bag and left for work.","vi":"Cô ấy cho máy tính xách tay vào túi rồi đi làm."},{"en":"Our bags didn''t arrive, so we waited at the airport.","vi":"Hành lý của chúng tôi không đến nên chúng tôi phải đợi ở sân bay."}]','[{"phrase":"plastic bag"},{"phrase":"shopping bag"},{"phrase":"pack your bags"},{"phrase":"school bag"}]',NULL,'/bæɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bag/bag__/bag__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1225,'ngsl-3-09',13,'repeat','lặp lại; nhắc lại','verb','[{"en":"Sorry, could you repeat the question, please?","vi":"Xin lỗi, bạn có thể nhắc lại câu hỏi được không?"},{"en":"Listen carefully and repeat each word after me.","vi":"Hãy nghe kỹ và lặp lại từng từ theo tôi."},{"en":"We don''t want to repeat the same mistakes as last year.","vi":"Chúng tôi không muốn lặp lại những sai lầm như năm ngoái."}]','[{"phrase":"repeat the question"},{"phrase":"repeat after me"},{"phrase":"repeat a mistake"}]',NULL,'/rɪˈpiːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repea/repeat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1226,'ngsl-3-09',14,'equal','bằng nhau; ngang hàng, bình đẳng','adjective','[{"en":"Cut the cake into eight equal pieces.","vi":"Cắt bánh thành tám miếng bằng nhau."},{"en":"Men and women should get equal pay for the same work.","vi":"Nam và nữ nên được trả lương ngang nhau cho cùng một công việc."},{"en":"All students have an equal chance to win the prize.","vi":"Tất cả học sinh đều có cơ hội giành giải như nhau."}]','[{"phrase":"equal pay"},{"phrase":"equal rights"},{"phrase":"equal chance"},{"phrase":"equal to"}]','be equal to something','/ˈiːkwəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equal/equal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1227,'ngsl-3-09',15,'expression','vẻ mặt, nét mặt; thành ngữ, cách diễn đạt; sự biểu lộ','noun','[{"en":"I could tell from her expression that she was worried.","vi":"Nhìn vẻ mặt cô ấy, tôi biết cô ấy đang lo lắng."},{"en":"What does the expression \"break the ice\" mean?","vi":"Thành ngữ \"break the ice\" có nghĩa là gì?"},{"en":"He sent her flowers as an expression of thanks.","vi":"Anh ấy gửi hoa cho cô ấy để bày tỏ lòng biết ơn."}]','[{"phrase":"facial expression"},{"phrase":"the expression on someone''s face"},{"phrase":"common expression"},{"phrase":"freedom of expression"}]',NULL,'/ɪkˈspreʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expre/expression__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1228,'ngsl-3-09',16,'plus','cộng; cộng thêm, thêm vào đó','preposition','[{"en":"Can you tell me what fifteen plus twenty-seven is?","vi":"Bạn có thể cho tôi biết mười lăm cộng hai mươi bảy bằng bao nhiêu không?"},{"en":"The room costs fifty dollars a night, plus tax.","vi":"Phòng giá năm mươi đô la một đêm, cộng thêm thuế."},{"en":"You''ll need your passport plus two recent photos.","vi":"Bạn sẽ cần hộ chiếu cùng với hai ảnh chụp gần đây."}]','[{"phrase":"plus tax"},{"phrase":"plus or minus"},{"phrase":"a big plus"}]',NULL,'/plʌs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/plu/plus_/plus__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1229,'ngsl-3-09',17,'extremely','cực kỳ, vô cùng','adverb','[{"en":"The exam was extremely difficult, but I think I passed.","vi":"Bài thi cực kỳ khó, nhưng tôi nghĩ mình đã đỗ."},{"en":"We are extremely grateful for all your help.","vi":"Chúng tôi vô cùng biết ơn mọi sự giúp đỡ của bạn."},{"en":"It gets extremely hot here in the summer.","vi":"Ở đây vào mùa hè trời cực kỳ nóng."}]','[{"phrase":"extremely difficult"},{"phrase":"extremely important"},{"phrase":"extremely grateful"},{"phrase":"extremely well"}]',NULL,'/ɪkˈstriːmli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extre/extremely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1230,'ngsl-3-09',18,'owner','chủ, người sở hữu','noun','[{"en":"The owner of the restaurant came to our table to say hello.","vi":"Chủ nhà hàng đến bàn chúng tôi để chào hỏi."},{"en":"Dog owners must keep their pets on a leash in the park.","vi":"Chủ chó phải xích thú cưng của mình khi ở trong công viên."},{"en":"Police are trying to find the owner of the car.","vi":"Cảnh sát đang cố tìm chủ của chiếc xe."}]','[{"phrase":"the owner of"},{"phrase":"business owner"},{"phrase":"property owner"},{"phrase":"dog owner"}]',NULL,'/ˈəʊnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/own/owner/owner__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1231,'ngsl-3-09',19,'plane','máy bay','noun','[{"en":"Our plane was delayed for two hours because of the weather.","vi":"Máy bay của chúng tôi bị hoãn hai tiếng vì thời tiết."},{"en":"It''s much faster to travel there by plane.","vi":"Đi đến đó bằng máy bay nhanh hơn nhiều."},{"en":"I always try to sleep on long plane journeys.","vi":"Tôi luôn cố ngủ trên những chuyến bay dài."}]','[{"phrase":"by plane"},{"phrase":"catch a plane"},{"phrase":"get on a plane"},{"phrase":"plane ticket"}]',NULL,'/pleɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plane/plane__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1232,'ngsl-3-09',20,'commercial','thương mại; mang tính thương mại','adjective','[{"en":"This area has many shops, offices and other commercial buildings.","vi":"Khu vực này có nhiều cửa hàng, văn phòng và các tòa nhà thương mại khác."},{"en":"The film was a big commercial success.","vi":"Bộ phim đã thành công lớn về mặt thương mại."},{"en":"He has worked as a commercial pilot for ten years.","vi":"Anh ấy đã làm phi công hàng không dân dụng được mười năm."}]','[{"phrase":"commercial success"},{"phrase":"commercial building"},{"phrase":"commercial use"}]','Danh từ: commercial = quảng cáo trên TV/radio','/kəˈmɜːrʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/commercial__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1233,'ngsl-3-09',21,'lady','quý bà, người phụ nữ; phu nhân','noun','[{"en":"An old lady asked me for directions to the station.","vi":"Một bà cụ hỏi tôi đường đến nhà ga."},{"en":"Good evening, ladies and gentlemen, and welcome to the show.","vi":"Chào buổi tối quý bà và quý ông, chào mừng đến với chương trình."},{"en":"The lady at the front desk gave us our room keys.","vi":"Người phụ nữ ở quầy lễ tân đưa chìa khóa phòng cho chúng tôi."}]','[{"phrase":"old lady"},{"phrase":"young lady"},{"phrase":"ladies and gentlemen"}]','Số nhiều: ladies','/ˈleɪdi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lad/lady_/lady__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1234,'ngsl-3-09',22,'duty','bổn phận, nghĩa vụ; nhiệm vụ; thuế','noun','[{"en":"I feel it''s my duty to take care of my parents.","vi":"Tôi cảm thấy chăm sóc bố mẹ là bổn phận của mình."},{"en":"Which doctor is on duty at the hospital tonight?","vi":"Tối nay bác sĩ nào trực ở bệnh viện?"},{"en":"Her duties include answering the phone and booking meetings.","vi":"Nhiệm vụ của cô ấy gồm nghe điện thoại và sắp xếp lịch họp."}]','[{"phrase":"on duty"},{"phrase":"off duty"},{"phrase":"sense of duty"},{"phrase":"duty to do something"}]',NULL,'/ˈduːti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dut/duty_/duty__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1235,'ngsl-3-09',23,'strength','sức mạnh, sức lực; điểm mạnh','noun','[{"en":"He didn''t have the strength to lift the heavy box.","vi":"Anh ấy không đủ sức nhấc cái hộp nặng đó."},{"en":"Swimming is a good way to build strength.","vi":"Bơi lội là một cách tốt để tăng cường sức lực."},{"en":"What do you think are your main strengths and weaknesses?","vi":"Bạn nghĩ điểm mạnh và điểm yếu chính của mình là gì?"}]','[{"phrase":"strengths and weaknesses"},{"phrase":"build strength"},{"phrase":"physical strength"},{"phrase":"inner strength"}]','strong (adj) – strength (n)','/streŋkθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stren/strength__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1236,'ngsl-3-09',24,'connect','kết nối; nối, liên kết','verb','[{"en":"I can''t connect to the internet in my room.","vi":"Tôi không kết nối được internet trong phòng."},{"en":"A long bridge connects the island to the mainland.","vi":"Một cây cầu dài nối hòn đảo với đất liền."},{"en":"Social media helps people connect with old friends.","vi":"Mạng xã hội giúp mọi người kết nối với bạn cũ."}]','[{"phrase":"connect to the internet"},{"phrase":"connect with"},{"phrase":"connect A to B"},{"phrase":"well connected"}]','connect to / with','/kəˈnekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconn/xconnect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1237,'ngsl-3-09',25,'cultural','(thuộc) văn hóa','adjective','[{"en":"The city has a rich cultural life with many museums and theaters.","vi":"Thành phố có đời sống văn hóa phong phú với nhiều bảo tàng và nhà hát."},{"en":"Living abroad taught me a lot about cultural differences.","vi":"Sống ở nước ngoài đã dạy tôi nhiều điều về sự khác biệt văn hóa."},{"en":"The festival is an important part of our cultural heritage.","vi":"Lễ hội là một phần quan trọng trong di sản văn hóa của chúng tôi."}]','[{"phrase":"cultural differences"},{"phrase":"cultural heritage"},{"phrase":"cultural events"},{"phrase":"cultural identity"}]','culture (n) – cultural (adj)','/ˈkʌltʃərəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cul/cultu/cultural__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1238,'ngsl-3-09',26,'arrange','sắp xếp; thu xếp, bố trí','verb','[{"en":"I''ve arranged a meeting with the manager for Friday.","vi":"Tôi đã sắp xếp một cuộc họp với quản lý vào thứ Sáu."},{"en":"She arranged the books on the shelf by color.","vi":"Cô ấy xếp sách trên kệ theo màu sắc."},{"en":"Can you arrange for someone to pick us up from the airport?","vi":"Bạn có thể thu xếp người đón chúng tôi ở sân bay không?"}]','[{"phrase":"arrange a meeting"},{"phrase":"arrange for someone to do something"},{"phrase":"arrange flowers"}]','arrange (v) – arrangement (n)','/əˈreɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arran/arrange__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1239,'ngsl-3-09',27,'scheme','kế hoạch, chương trình; mưu đồ','noun','[{"en":"The company has a scheme to help staff buy bikes.","vi":"Công ty có chương trình hỗ trợ nhân viên mua xe đạp."},{"en":"Over two thousand students joined the new training scheme.","vi":"Hơn hai nghìn sinh viên đã tham gia chương trình đào tạo mới."},{"en":"He lost all his savings in a scheme to get rich quickly.","vi":"Anh ấy mất hết tiền tiết kiệm vào một mưu đồ làm giàu nhanh."}]','[{"phrase":"training scheme"},{"phrase":"pension scheme"},{"phrase":"set up a scheme"},{"phrase":"get-rich-quick scheme"}]','Anh: scheme = chương trình (trung tính); Mỹ: thường mang nghĩa mưu đồ','/skiːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schem/scheme__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1240,'ngsl-3-09',28,'payment','sự thanh toán; khoản tiền trả','noun','[{"en":"We accept payment by card or cash.","vi":"Chúng tôi chấp nhận thanh toán bằng thẻ hoặc tiền mặt."},{"en":"I forgot to make the payment for my phone bill.","vi":"Tôi quên thanh toán hóa đơn điện thoại."},{"en":"They pay for the car in monthly payments of two hundred dollars.","vi":"Họ trả tiền mua xe theo từng khoản hàng tháng hai trăm đô la."}]','[{"phrase":"make a payment"},{"phrase":"monthly payment"},{"phrase":"late payment"},{"phrase":"payment by card"}]','pay (v) – payment (n)','/ˈpeɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pay/payme/payment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1241,'ngsl-3-09',29,'unfortunately','thật không may, đáng tiếc là','adverb','[{"en":"Unfortunately, the tickets had all been sold by the time we arrived.","vi":"Thật không may, lúc chúng tôi đến thì vé đã bán hết."},{"en":"I''d love to come, but unfortunately I have to work that day.","vi":"Tôi rất muốn đến, nhưng tiếc là hôm đó tôi phải làm việc."},{"en":"Unfortunately, it rained for most of our vacation.","vi":"Thật không may, trời mưa gần suốt kỳ nghỉ của chúng tôi."}]','[{"phrase":"but unfortunately"},{"phrase":"unfortunately for"}]',NULL,'/ʌnˈfɔːrtʃənətli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unf/unfor/unfortunately__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1242,'ngsl-3-09',30,'brief','ngắn gọn; ngắn, trong thời gian ngắn','adjective','[{"en":"Please keep your answers brief because we don''t have much time.","vi":"Hãy trả lời ngắn gọn vì chúng ta không có nhiều thời gian."},{"en":"She gave a brief description of the new project.","vi":"Cô ấy mô tả ngắn gọn về dự án mới."},{"en":"After a brief stop in the town, we drove on to the coast.","vi":"Sau một chặng dừng ngắn ở thị trấn, chúng tôi lái xe tiếp ra bờ biển."}]','[{"phrase":"brief description"},{"phrase":"brief visit"},{"phrase":"keep it brief"},{"phrase":"in brief"}]',NULL,'/briːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brief/brief__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1243,'ngsl-3-10',1,'bird','chim','noun','[{"en":"We could hear the birds singing outside our window.","vi":"Chúng tôi có thể nghe tiếng chim hót ngoài cửa sổ."},{"en":"A small bird built a nest in our garden.","vi":"Một chú chim nhỏ đã làm tổ trong vườn nhà chúng tôi."},{"en":"My grandfather feeds the birds in the park every morning.","vi":"Ông tôi cho chim ăn ở công viên mỗi sáng."}]','[{"phrase":"wild birds"},{"phrase":"feed the birds"},{"phrase":"birds sing"},{"phrase":"a flock of birds"}]',NULL,'/bɜːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bir/bird_/bird__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1244,'ngsl-3-10',2,'demonstrate','cho thấy, chứng minh; làm mẫu','verb','[{"en":"The results clearly demonstrate that the new method works.","vi":"Kết quả cho thấy rõ phương pháp mới có hiệu quả."},{"en":"She demonstrated her skills during her first week at work.","vi":"Cô ấy đã chứng minh năng lực của mình ngay trong tuần làm việc đầu tiên."},{"en":"The chef demonstrated how to make fresh pasta at home.","vi":"Đầu bếp làm mẫu cách làm mì Ý tươi tại nhà."}]','[{"phrase":"clearly demonstrate"},{"phrase":"demonstrate how to"},{"phrase":"demonstrate the importance of"}]',NULL,'/ˈdemənstreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/demon/demonstrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1245,'ngsl-3-10',3,'contribution','sự đóng góp; khoản đóng góp','noun','[{"en":"Thank you for your contribution to the project.","vi":"Cảm ơn bạn vì những đóng góp cho dự án."},{"en":"Everyone made an important contribution to the team''s success.","vi":"Mỗi người đều có đóng góp quan trọng vào thành công của cả đội."},{"en":"We made a small contribution to the school''s library fund.","vi":"Chúng tôi đã góp một khoản nhỏ vào quỹ thư viện của trường."}]','[{"phrase":"make a contribution"},{"phrase":"important contribution"},{"phrase":"contribution to"},{"phrase":"financial contribution"}]',NULL,'/ˌkɑːntrɪˈbjuːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontribution__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1246,'ngsl-3-10',4,'appreciate','cảm kích; trân trọng; hiểu rõ','verb','[{"en":"I''d really appreciate it if you could call me back.","vi":"Tôi sẽ rất cảm kích nếu bạn có thể gọi lại cho tôi."},{"en":"You learn to appreciate simple things when you travel.","vi":"Khi đi du lịch, bạn học được cách trân trọng những điều giản dị."},{"en":"I don''t think you appreciate how serious this problem is.","vi":"Tôi nghĩ bạn chưa hiểu rõ vấn đề này nghiêm trọng đến mức nào."}]','[{"phrase":"really appreciate"},{"phrase":"appreciate it"},{"phrase":"appreciate your help"},{"phrase":"greatly appreciate"}]',NULL,'/əˈpriːʃieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appre/appreciate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1247,'ngsl-3-10',5,'chapter','chương; giai đoạn','noun','[{"en":"I read one chapter of my book every night.","vi":"Mỗi tối tôi đọc một chương sách."},{"en":"The first chapter was a bit slow, but it gets better.","vi":"Chương đầu hơi chậm, nhưng càng về sau càng hay."},{"en":"Moving abroad was the start of a new chapter in her life.","vi":"Chuyển ra nước ngoài là khởi đầu một giai đoạn mới trong cuộc đời cô ấy."}]','[{"phrase":"first chapter"},{"phrase":"final chapter"},{"phrase":"a new chapter"},{"phrase":"read a chapter"}]',NULL,'/ˈtʃæptər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chapt/chapter__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1248,'ngsl-3-10',6,'secret','bí mật; bí quyết','noun','[{"en":"Can you keep a secret if I tell you something?","vi":"Nếu mình kể cho bạn một chuyện, bạn giữ bí mật được không?"},{"en":"She finally told her sister the secret she had kept for years.","vi":"Cuối cùng cô ấy đã kể với chị gái bí mật mà cô giữ suốt nhiều năm."},{"en":"What''s the secret to your delicious chicken soup?","vi":"Bí quyết nấu món súp gà ngon của bạn là gì?"}]','[{"phrase":"keep a secret"},{"phrase":"tell a secret"},{"phrase":"the secret to"},{"phrase":"an open secret"}]',NULL,'/ˈsiːkrət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secre/secret__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1249,'ngsl-3-10',7,'apparently','nghe nói; hình như','adverb','[{"en":"Apparently, the meeting has been moved to next Tuesday.","vi":"Nghe nói cuộc họp đã được dời sang thứ Ba tuần sau."},{"en":"She was apparently unaware of the problem until yesterday.","vi":"Hình như cô ấy không hề biết về vấn đề này cho đến hôm qua."},{"en":"Apparently it''s going to rain all weekend.","vi":"Nghe nói trời sẽ mưa suốt cuối tuần."}]','[{"phrase":"apparently unaware"},{"phrase":"apparently so"},{"phrase":"apparently not"}]',NULL,'/əˈpærəntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appar/apparently__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1250,'ngsl-3-10',8,'novel','tiểu thuyết','noun','[{"en":"She is writing her first novel about growing up in a small town.","vi":"Cô ấy đang viết cuốn tiểu thuyết đầu tay về tuổi thơ ở một thị trấn nhỏ."},{"en":"I stayed up all night to finish that novel.","vi":"Tôi thức cả đêm để đọc xong cuốn tiểu thuyết đó."},{"en":"His latest novel has been made into a movie.","vi":"Cuốn tiểu thuyết mới nhất của anh ấy đã được chuyển thể thành phim."}]','[{"phrase":"write a novel"},{"phrase":"first novel"},{"phrase":"latest novel"},{"phrase":"read a novel"}]',NULL,'/ˈnɑːvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nov/novel/novel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1251,'ngsl-3-10',9,'union','công đoàn; hội','noun','[{"en":"She joined the union when she started working at the factory.","vi":"Cô ấy gia nhập công đoàn khi bắt đầu làm việc ở nhà máy."},{"en":"The union is asking for better pay for nurses.","vi":"Công đoàn đang đòi mức lương tốt hơn cho các y tá."},{"en":"The student union organizes events for new students every year.","vi":"Hội sinh viên tổ chức các sự kiện cho tân sinh viên mỗi năm."}]','[{"phrase":"trade union"},{"phrase":"join a union"},{"phrase":"union members"},{"phrase":"student union"}]',NULL,'/ˈjuːniən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/union/union__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1252,'ngsl-3-10',10,'burn','đốt; làm cháy; làm bỏng','verb','[{"en":"Be careful not to burn your hand on the stove.","vi":"Cẩn thận kẻo bị bếp làm bỏng tay nhé."},{"en":"I burned the toast again this morning.","vi":"Sáng nay tôi lại làm cháy bánh mì nướng."},{"en":"They burned the dead leaves in the backyard.","vi":"Họ đốt đống lá khô ở sân sau."}]','[{"phrase":"burn your hand"},{"phrase":"burn down"},{"phrase":"burn calories"},{"phrase":"badly burned"}]','burn – burned/burnt – burned/burnt','/bɜːrn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/burn_/burn__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1253,'ngsl-3-10',11,'trend','xu hướng','noun','[{"en":"There is a growing trend toward working from home.","vi":"Xu hướng làm việc tại nhà đang ngày càng phổ biến."},{"en":"My daughter always follows the latest fashion trends.","vi":"Con gái tôi luôn chạy theo những xu hướng thời trang mới nhất."},{"en":"Prices have shown an upward trend over the past year.","vi":"Giá cả đã cho thấy xu hướng tăng trong suốt năm qua."}]','[{"phrase":"growing trend"},{"phrase":"latest trend"},{"phrase":"fashion trend"},{"phrase":"upward trend"}]',NULL,'/trend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/trend/trend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1254,'ngsl-3-10',12,'initial','ban đầu; đầu tiên','adjective','[{"en":"My initial reaction was surprise, but then I felt happy.","vi":"Phản ứng ban đầu của tôi là ngạc nhiên, nhưng sau đó tôi thấy vui."},{"en":"The initial plan was to leave at six in the morning.","vi":"Kế hoạch ban đầu là khởi hành lúc sáu giờ sáng."},{"en":"After some initial problems, the new system is working well.","vi":"Sau vài trục trặc ban đầu, hệ thống mới đang hoạt động tốt."}]','[{"phrase":"initial reaction"},{"phrase":"initial stages"},{"phrase":"initial plan"}]',NULL,'/ɪˈnɪʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1255,'ngsl-3-10',13,'pleasure','niềm vui; sự thích thú','noun','[{"en":"It was a real pleasure meeting you last night.","vi":"Được gặp bạn tối qua thật sự là một niềm vui."},{"en":"Reading in the garden is one of my greatest pleasures.","vi":"Đọc sách trong vườn là một trong những niềm vui lớn nhất của tôi."},{"en":"Are you traveling for business or for pleasure?","vi":"Bạn đi công tác hay đi chơi?"}]','[{"phrase":"great pleasure"},{"phrase":"for pleasure"},{"phrase":"take pleasure in"},{"phrase":"my pleasure"}]',NULL,'/ˈpleʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/pleas/pleasure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1256,'ngsl-3-10',14,'suggestion','gợi ý; đề xuất','noun','[{"en":"Do you have any suggestions for a good restaurant nearby?","vi":"Bạn có gợi ý nhà hàng nào ngon gần đây không?"},{"en":"My manager accepted my suggestion to start work earlier.","vi":"Quản lý đã chấp nhận đề xuất bắt đầu làm việc sớm hơn của tôi."},{"en":"At my friend''s suggestion, I started going to bed earlier.","vi":"Theo gợi ý của bạn tôi, tôi bắt đầu đi ngủ sớm hơn."}]','[{"phrase":"make a suggestion"},{"phrase":"accept a suggestion"},{"phrase":"helpful suggestion"}]',NULL,'/səˈdʒestʃən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sug/sugge/suggestion__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1257,'ngsl-3-10',15,'critical','cực kỳ quan trọng; chỉ trích','adjective','[{"en":"Getting enough sleep is critical for your health.","vi":"Ngủ đủ giấc cực kỳ quan trọng đối với sức khỏe của bạn."},{"en":"His parents were very critical of his decision to quit school.","vi":"Bố mẹ anh ấy đã chỉ trích nặng nề quyết định bỏ học của anh."},{"en":"This is a critical moment for our company.","vi":"Đây là thời điểm then chốt đối với công ty chúng tôi."}]','[{"phrase":"critical of"},{"phrase":"critical moment"},{"phrase":"critical role"},{"phrase":"highly critical"}]',NULL,'/ˈkrɪtɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/critical__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1258,'ngsl-3-10',16,'gather','tụ tập, tập hợp; thu thập','verb','[{"en":"The whole family gathers at my grandmother''s house every New Year.","vi":"Cả gia đình tụ họp ở nhà bà tôi mỗi dịp năm mới."},{"en":"A crowd gathered to watch the street musicians.","vi":"Một đám đông tụ tập để xem các nghệ sĩ đường phố biểu diễn."},{"en":"We need to gather more information before we decide.","vi":"Chúng ta cần thu thập thêm thông tin trước khi quyết định."}]','[{"phrase":"gather information"},{"phrase":"gather together"},{"phrase":"a crowd gathered"},{"phrase":"gather data"}]',NULL,'/ˈɡæðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gat/gathe/gather__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1259,'ngsl-3-10',17,'mostly','chủ yếu; phần lớn','adverb','[{"en":"The audience was mostly young people and students.","vi":"Khán giả chủ yếu là người trẻ và sinh viên."},{"en":"I mostly work from home these days.","vi":"Dạo này tôi chủ yếu làm việc ở nhà."},{"en":"The weather will be mostly sunny this weekend.","vi":"Cuối tuần này trời sẽ nắng là chủ yếu."}]','[{"phrase":"mostly sunny"},{"phrase":"mostly because"}]',NULL,'/ˈməʊstli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mos/mostl/mostly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1260,'ngsl-3-10',18,'earth','trái đất; đất','noun','[{"en":"The earth moves around the sun once a year.","vi":"Trái đất quay quanh mặt trời mỗi năm một vòng."},{"en":"Water covers most of the earth''s surface.","vi":"Nước bao phủ phần lớn bề mặt trái đất."},{"en":"Plant the seeds and cover them with a little earth.","vi":"Gieo hạt rồi phủ lên một ít đất."}]','[{"phrase":"the earth''s surface"},{"phrase":"life on earth"},{"phrase":"on earth"}]',NULL,'/ɜːrθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/earth/earth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1261,'ngsl-3-10',19,'pop','ghé qua; nổ bốp; chợt nảy ra','verb','[{"en":"I''ll pop into the store on my way home.","vi":"Trên đường về tôi sẽ ghé qua cửa hàng."},{"en":"The balloon popped and scared the baby.","vi":"Quả bóng bay nổ bốp làm em bé giật mình."},{"en":"A funny idea suddenly popped into my head.","vi":"Một ý tưởng buồn cười chợt nảy ra trong đầu tôi."}]','[{"phrase":"pop into"},{"phrase":"pop in"},{"phrase":"pop out"},{"phrase":"pop into your head"}]','pop – popped – popped','/pɑːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pop/pop__/pop__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1262,'ngsl-3-10',20,'essential','thiết yếu; rất cần thiết','adjective','[{"en":"Water is essential for all living things.","vi":"Nước rất cần thiết cho mọi sinh vật sống."},{"en":"A good map is essential when you hike in the mountains.","vi":"Một tấm bản đồ tốt là thứ thiết yếu khi bạn leo núi."},{"en":"It''s essential to book early during the holiday season.","vi":"Đặt chỗ sớm vào mùa lễ là điều rất cần thiết."}]','[{"phrase":"essential for"},{"phrase":"absolutely essential"},{"phrase":"essential part of"}]',NULL,'/ɪˈsenʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ess/essen/essential__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1263,'ngsl-3-10',21,'desire','mong muốn; khao khát','noun','[{"en":"She has a strong desire to study abroad.","vi":"Cô ấy có mong muốn mãnh liệt được đi du học."},{"en":"He had no desire to go back to his old job.","vi":"Anh ấy không hề muốn quay lại công việc cũ."},{"en":"Many young people share a desire for more freedom.","vi":"Nhiều người trẻ có chung khao khát được tự do hơn."}]','[{"phrase":"strong desire"},{"phrase":"no desire"},{"phrase":"desire to"},{"phrase":"desire for"}]',NULL,'/dɪˈzaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desir/desire__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1264,'ngsl-3-10',22,'promote','thăng chức; quảng bá; thúc đẩy','verb','[{"en":"She was promoted to manager after only two years.","vi":"Cô ấy được thăng chức lên quản lý chỉ sau hai năm."},{"en":"The band is touring to promote their new album.","vi":"Ban nhạc đang đi lưu diễn để quảng bá album mới."},{"en":"The city wants to promote the use of public transportation.","vi":"Thành phố muốn thúc đẩy việc sử dụng phương tiện giao thông công cộng."}]','[{"phrase":"be promoted to"},{"phrase":"promote a product"},{"phrase":"promote the use of"}]',NULL,'/prəˈməʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promo/promote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1265,'ngsl-3-10',23,'currently','hiện nay; hiện tại','adverb','[{"en":"I''m currently looking for a new apartment.","vi":"Hiện tôi đang tìm một căn hộ mới."},{"en":"The museum is currently closed for repairs.","vi":"Bảo tàng hiện đang đóng cửa để sửa chữa."},{"en":"How many people currently work at your company?","vi":"Hiện có bao nhiêu người làm việc ở công ty bạn?"}]','[{"phrase":"currently available"},{"phrase":"currently working on"},{"phrase":"currently looking for"}]',NULL,'/ˈkɜːrəntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/currently__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1266,'ngsl-3-10',24,'employ','thuê, tuyển dụng; sử dụng','verb','[{"en":"The factory employs more than five hundred workers.","vi":"Nhà máy thuê hơn năm trăm công nhân."},{"en":"She has been employed as a nurse for ten years.","vi":"Cô ấy được tuyển dụng làm y tá đã mười năm nay."},{"en":"Teachers employ different methods to keep students interested.","vi":"Giáo viên sử dụng nhiều phương pháp khác nhau để giữ cho học sinh hứng thú."}]','[{"phrase":"employ workers"},{"phrase":"be employed as"},{"phrase":"employ a method"}]',NULL,'/ɪmˈplɔɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employ__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1267,'ngsl-3-10',25,'path','lối đi; con đường','noun','[{"en":"We walked along a narrow path through the forest.","vi":"Chúng tôi đi dọc theo một lối mòn hẹp xuyên qua khu rừng."},{"en":"A fallen tree was blocking the path.","vi":"Một cái cây đổ đang chắn lối đi."},{"en":"He chose a different career path from his parents.","vi":"Anh ấy chọn một con đường sự nghiệp khác với bố mẹ."}]','[{"phrase":"narrow path"},{"phrase":"career path"},{"phrase":"block the path"},{"phrase":"follow a path"}]',NULL,'/pæθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pat/path_/path__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1268,'ngsl-3-10',26,'topic','chủ đề','noun','[{"en":"Let''s change the topic and talk about something fun.","vi":"Chúng ta đổi chủ đề và nói chuyện gì đó vui đi."},{"en":"The teacher asked us to choose a topic for our essays.","vi":"Giáo viên yêu cầu chúng tôi chọn một chủ đề cho bài luận."},{"en":"Money is a sensitive topic in many families.","vi":"Tiền bạc là chủ đề nhạy cảm trong nhiều gia đình."}]','[{"phrase":"change the topic"},{"phrase":"choose a topic"},{"phrase":"sensitive topic"},{"phrase":"topic of conversation"}]',NULL,'/ˈtɑːpɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/top/topic/topic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1269,'ngsl-3-10',27,'beach','bãi biển','noun','[{"en":"We spent the whole afternoon lying on the beach.","vi":"Chúng tôi dành cả buổi chiều nằm trên bãi biển."},{"en":"The hotel is only a five-minute walk from the beach.","vi":"Khách sạn chỉ cách bãi biển năm phút đi bộ."},{"en":"Let''s go to the beach if the weather is nice tomorrow.","vi":"Nếu mai trời đẹp thì mình đi biển nhé."}]','[{"phrase":"on the beach"},{"phrase":"go to the beach"},{"phrase":"sandy beach"},{"phrase":"beach house"}]',NULL,'/biːtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beach/beach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1270,'ngsl-3-10',28,'attract','thu hút; hấp dẫn','verb','[{"en":"The festival attracts thousands of visitors every summer.","vi":"Lễ hội thu hút hàng nghìn du khách mỗi mùa hè."},{"en":"Bright colors attract bees and butterflies to the flowers.","vi":"Màu sắc rực rỡ thu hút ong và bướm đến với những bông hoa."},{"en":"The company offers higher pay to attract new staff.","vi":"Công ty trả lương cao hơn để thu hút nhân viên mới."}]','[{"phrase":"attract visitors"},{"phrase":"attract attention"},{"phrase":"attract customers"},{"phrase":"be attracted to"}]',NULL,'/əˈtrækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attra/attract__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1271,'ngsl-3-10',29,'engage','tham gia; thu hút, lôi cuốn','verb','[{"en":"Students who engage in class discussions usually learn faster.","vi":"Những học sinh tham gia thảo luận trong lớp thường học nhanh hơn."},{"en":"The teacher uses games to engage young learners.","vi":"Giáo viên dùng trò chơi để lôi cuốn học sinh nhỏ tuổi."},{"en":"Many retired people engage in volunteer work.","vi":"Nhiều người đã nghỉ hưu tham gia công việc tình nguyện."}]','[{"phrase":"engage in"},{"phrase":"engage with"},{"phrase":"engage students"},{"phrase":"fully engage"}]','engage in sth: tham gia vào việc gì','/ɪnˈɡeɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eng/engag/engage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1272,'ngsl-3-10',30,'powerful','mạnh mẽ; có quyền lực','adjective','[{"en":"This new laptop is small but very powerful.","vi":"Chiếc laptop mới này nhỏ nhưng rất mạnh."},{"en":"She gave a powerful speech at the graduation ceremony.","vi":"Cô ấy đã có một bài phát biểu đầy sức lay động tại lễ tốt nghiệp."},{"en":"He comes from a rich and powerful family.","vi":"Anh ấy xuất thân từ một gia đình giàu có và quyền lực."}]','[{"phrase":"rich and powerful"},{"phrase":"very powerful"},{"phrase":"powerful speech"}]',NULL,'/ˈpaʊərfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pow/power/powerful__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1273,'ngsl-3-11',1,'flower','hoa; bông hoa','noun','[{"en":"She bought a bunch of flowers for her mother''s birthday.","vi":"Cô ấy mua một bó hoa tặng sinh nhật mẹ."},{"en":"The flowers in our garden bloom every spring.","vi":"Những bông hoa trong vườn nhà chúng tôi nở vào mỗi mùa xuân."},{"en":"Please don''t pick the flowers in the park.","vi":"Xin đừng hái hoa trong công viên."}]','[{"phrase":"bunch of flowers"},{"phrase":"pick flowers"},{"phrase":"fresh flowers"},{"phrase":"flower shop"}]',NULL,'/ˈflaʊər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/flowe/flower__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1274,'ngsl-3-11',2,'crisis','khủng hoảng','noun','[{"en":"The company is facing a serious financial crisis this year.","vi":"Năm nay công ty đang đối mặt với một cuộc khủng hoảng tài chính nghiêm trọng."},{"en":"Many families lost their homes during the economic crisis.","vi":"Nhiều gia đình đã mất nhà trong cuộc khủng hoảng kinh tế."},{"en":"She always stays calm and thinks clearly in a crisis.","vi":"Cô ấy luôn giữ bình tĩnh và suy nghĩ sáng suốt khi gặp khủng hoảng."}]','[{"phrase":"financial crisis"},{"phrase":"economic crisis"},{"phrase":"face a crisis"},{"phrase":"in a crisis"}]','số nhiều: crises','/ˈkraɪsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/crisi/crisis__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1275,'ngsl-3-11',3,'settle','giải quyết; định cư; ổn định','verb','[{"en":"They finally settled the argument after a long talk.","vi":"Cuối cùng họ đã giải quyết được cuộc tranh cãi sau một buổi nói chuyện dài."},{"en":"My grandparents settled in this town fifty years ago.","vi":"Ông bà tôi đã định cư ở thị trấn này từ năm mươi năm trước."},{"en":"It took the kids a few weeks to settle into their new school.","vi":"Bọn trẻ mất vài tuần để ổn định ở trường mới."}]','[{"phrase":"settle an argument"},{"phrase":"settle a dispute"},{"phrase":"settle down"},{"phrase":"settle in"}]',NULL,'/ˈsetl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/set/settl/settle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1276,'ngsl-3-11',4,'boat','thuyền','noun','[{"en":"We took a boat across the lake to the island.","vi":"Chúng tôi đi thuyền qua hồ để ra đảo."},{"en":"My uncle goes fishing in his small boat every morning.","vi":"Chú tôi đi câu cá bằng chiếc thuyền nhỏ của chú mỗi sáng."},{"en":"Have you ever been on a boat trip?","vi":"Bạn đã bao giờ đi chơi bằng thuyền chưa?"}]','[{"phrase":"by boat"},{"phrase":"boat trip"},{"phrase":"fishing boat"}]',NULL,'/bəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boa/boat_/boat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1277,'ngsl-3-11',5,'aid','viện trợ; sự hỗ trợ','noun','[{"en":"The government sent food aid to the flooded areas.","vi":"Chính phủ đã gửi lương thực viện trợ đến các vùng bị ngập lụt."},{"en":"Many students rely on financial aid to pay for college.","vi":"Nhiều sinh viên dựa vào hỗ trợ tài chính để trả tiền học đại học."},{"en":"He can only read small print with the aid of glasses.","vi":"Anh ấy chỉ đọc được chữ nhỏ khi có kính hỗ trợ."}]','[{"phrase":"food aid"},{"phrase":"financial aid"},{"phrase":"first aid"},{"phrase":"with the aid of"}]',NULL,'/eɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aid/aid__/aid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1278,'ngsl-3-11',6,'fan','người hâm mộ; quạt','noun','[{"en":"Thousands of fans waited outside the stadium for the players.","vi":"Hàng nghìn người hâm mộ chờ các cầu thủ bên ngoài sân vận động."},{"en":"I''ve been a big fan of her music since high school.","vi":"Tôi đã rất hâm mộ âm nhạc của cô ấy từ hồi cấp ba."},{"en":"It''s so hot in here; can you turn on the fan?","vi":"Trong này nóng quá, bạn bật quạt lên được không?"}]','[{"phrase":"big fan"},{"phrase":"football fan"},{"phrase":"turn on the fan"},{"phrase":"ceiling fan"}]',NULL,'/fæn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fan/fan__/fan__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1279,'ngsl-3-11',7,'kitchen','nhà bếp','noun','[{"en":"Mom is cooking dinner in the kitchen right now.","vi":"Mẹ đang nấu bữa tối trong bếp."},{"en":"We sat at the kitchen table and talked for hours.","vi":"Chúng tôi ngồi ở bàn bếp và nói chuyện hàng giờ liền."},{"en":"Their new apartment has a small but bright kitchen.","vi":"Căn hộ mới của họ có một gian bếp nhỏ nhưng sáng sủa."}]','[{"phrase":"in the kitchen"},{"phrase":"kitchen table"},{"phrase":"kitchen sink"}]',NULL,'/ˈkɪtʃɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kit/kitch/kitchen__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1280,'ngsl-3-11',8,'twice','hai lần; gấp đôi','adverb','[{"en":"I go to the gym twice a week.","vi":"Tôi đến phòng tập hai lần một tuần."},{"en":"She read the letter twice before she understood it.","vi":"Cô ấy đọc lá thư hai lần rồi mới hiểu."},{"en":"Their new house is twice as big as the old one.","vi":"Ngôi nhà mới của họ rộng gấp đôi ngôi nhà cũ."}]','[{"phrase":"twice a week"},{"phrase":"twice a day"},{"phrase":"twice as much"},{"phrase":"think twice"}]',NULL,'/twaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/twi/twice/twice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1281,'ngsl-3-11',9,'fresh','tươi; trong lành; mới','adjective','[{"en":"We buy fresh vegetables at the market every morning.","vi":"Chúng tôi mua rau tươi ở chợ mỗi sáng."},{"en":"Let''s open the window and get some fresh air.","vi":"Mình mở cửa sổ ra để đón chút không khí trong lành đi."},{"en":"After the holiday, I came back to work with fresh ideas.","vi":"Sau kỳ nghỉ, tôi quay lại làm việc với những ý tưởng mới."}]','[{"phrase":"fresh air"},{"phrase":"fresh fruit"},{"phrase":"fresh start"}]',NULL,'/freʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/fresh/fresh__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1282,'ngsl-3-11',10,'delay','trì hoãn; làm chậm trễ','verb','[{"en":"Our flight was delayed for three hours because of the storm.","vi":"Chuyến bay của chúng tôi bị trễ ba tiếng vì bão."},{"en":"Don''t delay seeing a doctor if the pain gets worse.","vi":"Đừng chần chừ đi khám bác sĩ nếu cơn đau nặng hơn."},{"en":"Heavy traffic delayed us, so we missed the start of the movie.","vi":"Kẹt xe làm chúng tôi bị trễ nên lỡ mất đoạn đầu bộ phim."}]','[{"phrase":"delay a decision"},{"phrase":"be delayed by"},{"phrase":"without delay"}]',NULL,'/dɪˈleɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/delay/delay__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1283,'ngsl-3-11',11,'safety','sự an toàn','noun','[{"en":"For your safety, please keep your seat belt fastened.","vi":"Vì sự an toàn của bạn, vui lòng luôn thắt dây an toàn."},{"en":"Parents always worry about their children''s safety online.","vi":"Cha mẹ luôn lo lắng về sự an toàn của con cái trên mạng."},{"en":"All workers must follow the safety rules on the construction site.","vi":"Tất cả công nhân phải tuân thủ các quy định an toàn ở công trường."}]','[{"phrase":"safety rules"},{"phrase":"road safety"},{"phrase":"food safety"},{"phrase":"for your safety"}]','không đếm được','/ˈseɪfti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/saf/safet/safety__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1284,'ngsl-3-11',12,'engineer','kỹ sư','noun','[{"en":"My brother works as an engineer for a car company.","vi":"Anh trai tôi làm kỹ sư cho một công ty ô tô."},{"en":"The engineers are checking the bridge for any damage.","vi":"Các kỹ sư đang kiểm tra xem cây cầu có hư hại gì không."},{"en":"She wants to become a software engineer after college.","vi":"Cô ấy muốn trở thành kỹ sư phần mềm sau khi học xong đại học."}]','[{"phrase":"software engineer"},{"phrase":"civil engineer"},{"phrase":"work as an engineer"}]',NULL,'/ˌendʒɪˈnɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eng/engin/engineer__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1285,'ngsl-3-11',13,'quiet','yên tĩnh; im lặng','adjective','[{"en":"The library is a quiet place to study.","vi":"Thư viện là một nơi yên tĩnh để học bài."},{"en":"Please be quiet; the baby is sleeping.","vi":"Làm ơn giữ im lặng, em bé đang ngủ."},{"en":"We live on a quiet street far from the city center.","vi":"Chúng tôi sống trên một con phố yên tĩnh, cách xa trung tâm thành phố."}]','[{"phrase":"be quiet"},{"phrase":"keep quiet"},{"phrase":"quiet place"},{"phrase":"quiet street"}]','quiet (yên tĩnh) ≠ quite (khá)','/ˈkwaɪət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quiet/quiet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1286,'ngsl-3-11',14,'insurance','bảo hiểm','noun','[{"en":"Does your new job come with health insurance?","vi":"Công việc mới của bạn có kèm bảo hiểm y tế không?"},{"en":"You need car insurance before you can drive on the road.","vi":"Bạn cần có bảo hiểm xe trước khi được lái xe ra đường."},{"en":"The insurance company paid for the damage after the fire.","vi":"Công ty bảo hiểm đã chi trả cho thiệt hại sau vụ cháy."}]','[{"phrase":"health insurance"},{"phrase":"car insurance"},{"phrase":"insurance company"},{"phrase":"travel insurance"}]','không đếm được','/ɪnˈʃʊrəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insur/insurance__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1287,'ngsl-3-11',15,'nurse','y tá','noun','[{"en":"The nurse checked my temperature and blood pressure.","vi":"Y tá đã đo nhiệt độ và huyết áp cho tôi."},{"en":"My aunt has worked as a nurse for twenty years.","vi":"Dì tôi đã làm y tá được hai mươi năm."},{"en":"Ask the nurse if you need more water or a blanket.","vi":"Hãy hỏi y tá nếu bạn cần thêm nước hoặc chăn."}]','[{"phrase":"work as a nurse"},{"phrase":"school nurse"},{"phrase":"night nurse"}]',NULL,'/nɜːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nur/nurse/nurse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1288,'ngsl-3-11',16,'divide','chia; phân chia','verb','[{"en":"Divide the cake into eight equal pieces.","vi":"Hãy chia chiếc bánh thành tám phần bằng nhau."},{"en":"The teacher divided the class into small groups.","vi":"Giáo viên chia lớp thành các nhóm nhỏ."},{"en":"If you divide twenty by four, you get five.","vi":"Nếu lấy hai mươi chia cho bốn, bạn được năm."}]','[{"phrase":"divide into"},{"phrase":"divide by"},{"phrase":"divide equally"}]','divide into (chia thành) · divide by (chia cho)','/dɪˈvaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/divid/divide__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1289,'ngsl-3-11',17,'length','chiều dài; độ dài','noun','[{"en":"Can you measure the length of this table for me?","vi":"Bạn đo giúp tôi chiều dài của cái bàn này được không?"},{"en":"The bridge has a total length of two kilometers.","vi":"Cây cầu có tổng chiều dài là hai ki-lô-mét."},{"en":"Your essay should be about 500 words in length.","vi":"Bài luận của bạn nên dài khoảng 500 từ."}]','[{"phrase":"the length of"},{"phrase":"in length"},{"phrase":"total length"}]',NULL,'/leŋkθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/len/lengt/length__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1290,'ngsl-3-11',18,'investigation','cuộc điều tra','noun','[{"en":"The police have started an investigation into the fire.","vi":"Cảnh sát đã bắt đầu một cuộc điều tra về vụ cháy."},{"en":"The cause of the accident is still under investigation.","vi":"Nguyên nhân vụ tai nạn vẫn đang được điều tra."},{"en":"After a long investigation, they found the missing money.","vi":"Sau một cuộc điều tra dài, họ đã tìm ra số tiền bị mất."}]','[{"phrase":"investigation into"},{"phrase":"under investigation"},{"phrase":"carry out an investigation"},{"phrase":"police investigation"}]',NULL,'/ɪnˌvestɪˈɡeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investigation__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1291,'ngsl-3-11',19,'package','gói hàng, bưu kiện; gói dịch vụ','noun','[{"en":"A package arrived for you while you were out.","vi":"Có một bưu kiện gửi đến cho bạn lúc bạn đi vắng."},{"en":"I need to send this package to my sister in Hanoi.","vi":"Tôi cần gửi gói hàng này cho chị gái tôi ở Hà Nội."},{"en":"The hotel offers a vacation package that includes meals and tours.","vi":"Khách sạn có gói nghỉ dưỡng bao gồm các bữa ăn và chuyến tham quan."}]','[{"phrase":"send a package"},{"phrase":"receive a package"},{"phrase":"vacation package"}]',NULL,'/ˈpækɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pac/packa/package__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1292,'ngsl-3-11',20,'somewhere','ở đâu đó; nơi nào đó','adverb','[{"en":"I left my keys somewhere in the house.","vi":"Tôi để quên chìa khóa ở đâu đó trong nhà."},{"en":"Let''s go somewhere quiet where we can talk.","vi":"Mình đi đâu đó yên tĩnh để có thể nói chuyện đi."},{"en":"She lives somewhere near the old train station.","vi":"Cô ấy sống ở đâu đó gần nhà ga cũ."}]','[{"phrase":"somewhere else"},{"phrase":"somewhere near"},{"phrase":"go somewhere"}]',NULL,'/ˈsʌmwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somew/somewhere__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1293,'ngsl-3-11',21,'expand','mở rộng; nở ra','verb','[{"en":"The company plans to expand into Asian markets next year.","vi":"Công ty dự định mở rộng sang các thị trường châu Á vào năm tới."},{"en":"The restaurant expanded its menu to include vegetarian dishes.","vi":"Nhà hàng đã mở rộng thực đơn để có thêm các món chay."},{"en":"Most metals expand when they are heated.","vi":"Hầu hết kim loại nở ra khi bị nung nóng."}]','[{"phrase":"expand rapidly"},{"phrase":"expand the business"},{"phrase":"expand into"}]',NULL,'/ɪkˈspænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expan/expand__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1294,'ngsl-3-11',22,'commit','phạm (tội, lỗi); cam kết','verb','[{"en":"The police believe he committed the crime alone.","vi":"Cảnh sát tin rằng anh ta đã gây án một mình."},{"en":"We are committed to giving our customers the best service.","vi":"Chúng tôi cam kết mang đến dịch vụ tốt nhất cho khách hàng."},{"en":"Before you commit to a two-year contract, read it carefully.","vi":"Trước khi cam kết với một hợp đồng hai năm, hãy đọc kỹ nó."}]','[{"phrase":"commit a crime"},{"phrase":"commit to"},{"phrase":"be committed to"},{"phrase":"fully committed"}]','commit to + V-ing: cam kết làm gì','/kəˈmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1295,'ngsl-3-11',23,'obvious','rõ ràng; hiển nhiên','adjective','[{"en":"It was obvious that she was nervous before the exam.","vi":"Rõ ràng là cô ấy đã lo lắng trước kỳ thi."},{"en":"The answer seems obvious now, but it wasn''t at first.","vi":"Giờ thì đáp án có vẻ hiển nhiên, nhưng lúc đầu thì không."},{"en":"For obvious reasons, we can''t talk about it in front of the kids.","vi":"Vì những lý do hiển nhiên, chúng ta không thể nói chuyện đó trước mặt bọn trẻ."}]','[{"phrase":"it is obvious that"},{"phrase":"for obvious reasons"},{"phrase":"obvious choice"}]',NULL,'/ˈɑːbviəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obv/obvio/obvious__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1296,'ngsl-3-11',24,'jump','nhảy; tăng vọt','verb','[{"en":"The kids love jumping into the swimming pool.","vi":"Bọn trẻ rất thích nhảy xuống hồ bơi."},{"en":"The cat jumped onto the table and knocked over my cup.","vi":"Con mèo nhảy lên bàn và làm đổ cốc của tôi."},{"en":"Prices jumped by twenty percent in just one month.","vi":"Giá cả tăng vọt hai mươi phần trăm chỉ trong một tháng."}]','[{"phrase":"jump into"},{"phrase":"jump over"},{"phrase":"jump up and down"}]',NULL,'/dʒʌmp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jum/jump_/jump__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1297,'ngsl-3-11',25,'weapon','vũ khí','noun','[{"en":"Security staff at the airport check bags for weapons.","vi":"Nhân viên an ninh sân bay kiểm tra túi xách xem có vũ khí không."},{"en":"In the past, soldiers used swords as their main weapons.","vi":"Ngày xưa, binh lính dùng kiếm làm vũ khí chính."},{"en":"Her smile is her secret weapon in job interviews.","vi":"Nụ cười là vũ khí bí mật của cô ấy trong các buổi phỏng vấn xin việc."}]','[{"phrase":"secret weapon"},{"phrase":"carry a weapon"}]',NULL,'/ˈwepən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weapo/weapon__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1298,'ngsl-3-11',26,'relatively','tương đối; khá','adverb','[{"en":"The exam was relatively easy compared to last year''s.","vi":"Kỳ thi tương đối dễ so với năm ngoái."},{"en":"Houses in this area are still relatively cheap.","vi":"Nhà ở khu vực này vẫn còn khá rẻ."},{"en":"She learned to drive in a relatively short time.","vi":"Cô ấy học lái xe trong một thời gian tương đối ngắn."}]','[{"phrase":"relatively easy"},{"phrase":"relatively small"},{"phrase":"relatively cheap"},{"phrase":"relatively short"}]',NULL,'/ˈrelətɪvli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relatively__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1299,'ngsl-3-11',27,'host','chủ nhà; người dẫn chương trình','noun','[{"en":"Our host welcomed us with tea and cakes.","vi":"Chủ nhà đón tiếp chúng tôi bằng trà và bánh."},{"en":"He is the host of a popular cooking show.","vi":"Anh ấy là người dẫn một chương trình nấu ăn được yêu thích."},{"en":"Remember to thank the host before you leave the party.","vi":"Nhớ cảm ơn chủ nhà trước khi rời bữa tiệc nhé."}]','[{"phrase":"host family"},{"phrase":"host country"},{"phrase":"talk show host"}]',NULL,'/həʊst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hos/host_/host__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1300,'ngsl-3-11',28,'winter','mùa đông','noun','[{"en":"It snows a lot here during the winter months.","vi":"Ở đây tuyết rơi nhiều vào những tháng mùa đông."},{"en":"We''re planning a ski trip this winter.","vi":"Chúng tôi đang lên kế hoạch đi trượt tuyết vào mùa đông năm nay."},{"en":"Don''t forget to bring a warm winter coat.","vi":"Đừng quên mang theo một chiếc áo khoác mùa đông thật ấm."}]','[{"phrase":"in winter"},{"phrase":"this winter"},{"phrase":"winter coat"},{"phrase":"cold winter"}]',NULL,'/ˈwɪntər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/winte/winter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1301,'ngsl-3-11',29,'district','quận, huyện; khu vực','noun','[{"en":"My office is in District 1, not far from the river.","vi":"Văn phòng của tôi ở Quận 1, cách sông không xa."},{"en":"This is the busiest shopping district in the city.","vi":"Đây là khu mua sắm sầm uất nhất thành phố."},{"en":"Most children in this district go to the same elementary school.","vi":"Hầu hết trẻ em trong quận này học cùng một trường tiểu học."}]','[{"phrase":"shopping district"},{"phrase":"business district"},{"phrase":"school district"}]',NULL,'/ˈdɪstrɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distr/district__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1302,'ngsl-3-11',30,'broad','rộng; bao quát','adjective','[{"en":"The river is very broad at this point.","vi":"Con sông rất rộng ở đoạn này."},{"en":"He has broad shoulders and a friendly smile.","vi":"Anh ấy có bờ vai rộng và nụ cười thân thiện."},{"en":"The course gives students a broad understanding of modern history.","vi":"Khóa học mang lại cho sinh viên hiểu biết bao quát về lịch sử hiện đại."}]','[{"phrase":"broad shoulders"},{"phrase":"a broad range of"},{"phrase":"broad smile"}]',NULL,'/brɔːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/broad/broad__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1303,'ngsl-3-12',1,'tire','lốp xe','noun','[{"en":"We got a flat tire on the way to the airport.","vi":"Chúng tôi bị xẹp lốp xe trên đường ra sân bay."},{"en":"You should check your tires before a long drive.","vi":"Bạn nên kiểm tra lốp xe trước một chuyến đi xa."},{"en":"My dad taught me how to change a tire.","vi":"Bố tôi đã dạy tôi cách thay lốp xe."}]','[{"phrase":"flat tire"},{"phrase":"change a tire"},{"phrase":"spare tire"},{"phrase":"front tire"}]','Anh: tyre · Mỹ: tire','/ˈtaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tir/tire_/tire__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1304,'ngsl-3-12',2,'spring','mùa xuân; lò xo','noun','[{"en":"The cherry trees on our street bloom every spring.","vi":"Những cây anh đào trên phố nhà tôi nở hoa mỗi mùa xuân."},{"en":"We are planning to move to a new apartment next spring.","vi":"Chúng tôi dự định chuyển đến một căn hộ mới vào mùa xuân tới."},{"en":"One of the springs in this old mattress is broken.","vi":"Một cái lò xo trong tấm nệm cũ này bị gãy."}]','[{"phrase":"in the spring"},{"phrase":"early spring"},{"phrase":"next spring"},{"phrase":"spring break"}]',NULL,'/sprɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spr/sprin/spring__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1305,'ngsl-3-12',3,'spirit','tinh thần; tâm trạng','noun','[{"en":"Our coach says team spirit matters more than talent.","vi":"Huấn luyện viên của chúng tôi nói tinh thần đồng đội quan trọng hơn tài năng."},{"en":"Her kind words really lifted my spirits.","vi":"Những lời tử tế của cô ấy thật sự làm tôi phấn chấn lên."},{"en":"Everyone was in high spirits after hearing the good news.","vi":"Mọi người đều rất phấn khởi sau khi nghe tin vui."}]','[{"phrase":"team spirit"},{"phrase":"in high spirits"},{"phrase":"lift your spirits"},{"phrase":"community spirit"}]',NULL,'/ˈspɪrɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spi/spiri/spirit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1306,'ngsl-3-12',4,'lunch','bữa trưa','noun','[{"en":"Let''s have lunch together at the new restaurant tomorrow.","vi":"Mai chúng ta cùng ăn trưa ở nhà hàng mới nhé."},{"en":"I usually bring my lunch to work to save money.","vi":"Tôi thường mang bữa trưa đi làm để tiết kiệm tiền."},{"en":"She was out for lunch when the manager called.","vi":"Cô ấy đang ra ngoài ăn trưa thì quản lý gọi đến."}]','[{"phrase":"have lunch"},{"phrase":"lunch break"},{"phrase":"eat lunch"},{"phrase":"pack a lunch"}]',NULL,'/lʌntʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lun/lunch/lunch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1307,'ngsl-3-12',5,'actual','thực tế; thật sự','adjective','[{"en":"The actual cost was much higher than we expected.","vi":"Chi phí thực tế cao hơn nhiều so với chúng tôi dự tính."},{"en":"The movie is based on actual events.","vi":"Bộ phim dựa trên những sự kiện có thật."},{"en":"We practiced a lot, but the actual test was easier.","vi":"Chúng tôi đã luyện tập nhiều, nhưng bài kiểm tra thật lại dễ hơn."}]','[{"phrase":"actual cost"},{"phrase":"actual number"},{"phrase":"the actual reason"}]',NULL,'/ˈæktʃuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actua/actual__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1308,'ngsl-3-12',6,'pool','hồ bơi','noun','[{"en":"The kids spent the whole afternoon in the pool.","vi":"Bọn trẻ ở dưới hồ bơi suốt cả buổi chiều."},{"en":"Our hotel has a large outdoor pool on the roof.","vi":"Khách sạn của chúng tôi có một hồ bơi ngoài trời lớn trên sân thượng."},{"en":"Is the swimming pool open to the public on weekends?","vi":"Hồ bơi có mở cửa cho mọi người vào cuối tuần không?"}]','[{"phrase":"swimming pool"},{"phrase":"outdoor pool"},{"phrase":"indoor pool"}]',NULL,'/puːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poo/pool_/pool__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1309,'ngsl-3-12',7,'battle','trận đánh; cuộc đấu tranh','noun','[{"en":"The castle was built near the site of a famous battle.","vi":"Lâu đài được xây gần nơi diễn ra một trận đánh nổi tiếng."},{"en":"Getting my son to eat vegetables is a daily battle.","vi":"Bắt con trai tôi ăn rau là một cuộc chiến mỗi ngày."},{"en":"After a long battle, the town finally saved its old library.","vi":"Sau một cuộc đấu tranh dài, thị trấn cuối cùng đã giữ được thư viện cũ."}]','[{"phrase":"win a battle"},{"phrase":"long battle"},{"phrase":"losing battle"}]',NULL,'/ˈbætl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bat/battl/battle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1310,'ngsl-3-12',8,'tradition','truyền thống','noun','[{"en":"It''s a family tradition to eat dinner together on Sundays.","vi":"Cùng nhau ăn tối vào Chủ nhật là một truyền thống của gia đình."},{"en":"The town has a long tradition of making pottery.","vi":"Thị trấn có truyền thống làm gốm lâu đời."},{"en":"Many young people no longer follow the old traditions.","vi":"Nhiều người trẻ không còn theo những truyền thống cũ nữa."}]','[{"phrase":"family tradition"},{"phrase":"long tradition"},{"phrase":"follow a tradition"}]',NULL,'/trəˈdɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/tradi/tradition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1311,'ngsl-3-12',9,'cash','tiền mặt','noun','[{"en":"Do you want to pay by card or in cash?","vi":"Bạn muốn trả bằng thẻ hay bằng tiền mặt?"},{"en":"I never carry much cash when I travel.","vi":"Tôi không bao giờ mang nhiều tiền mặt khi đi du lịch."},{"en":"The small shop on the corner only accepts cash.","vi":"Cửa hàng nhỏ ở góc phố chỉ nhận tiền mặt."}]','[{"phrase":"pay in cash"},{"phrase":"cash payment"},{"phrase":"short of cash"}]','không đếm được','/kæʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/cash_/cash__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1312,'ngsl-3-12',10,'hardly','hầu như không','adverb','[{"en":"I could hardly hear him because the music was so loud.","vi":"Tôi hầu như không nghe được anh ấy nói vì nhạc quá to."},{"en":"We have hardly ever seen each other since she moved away.","vi":"Từ khi cô ấy chuyển đi, chúng tôi hầu như chưa bao giờ gặp nhau."},{"en":"There was hardly any food left when we arrived.","vi":"Khi chúng tôi đến thì hầu như chẳng còn chút đồ ăn nào."}]','[{"phrase":"hardly ever"},{"phrase":"hardly any"},{"phrase":"can hardly"}]','hardly (hầu như không) ≠ hard (chăm chỉ, vất vả)','/ˈhɑːrdli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/har/hardl/hardly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1313,'ngsl-3-12',11,'award','giải thưởng','noun','[{"en":"She won an award for her work with local schools.","vi":"Cô ấy đã giành được một giải thưởng nhờ công việc với các trường học địa phương."},{"en":"The restaurant received an award for its excellent service.","vi":"Nhà hàng đã nhận được giải thưởng nhờ dịch vụ xuất sắc."},{"en":"The awards will be given out at the end of the evening.","vi":"Các giải thưởng sẽ được trao vào cuối buổi tối."}]','[{"phrase":"win an award"},{"phrase":"receive an award"},{"phrase":"award ceremony"}]',NULL,'/əˈwɔːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/award/award__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1314,'ngsl-3-12',12,'coach','huấn luyện viên; xe khách','noun','[{"en":"Our basketball coach makes us run before every practice.","vi":"Huấn luyện viên bóng rổ bắt chúng tôi chạy trước mỗi buổi tập."},{"en":"The coach told the players to stay calm.","vi":"Huấn luyện viên bảo các cầu thủ giữ bình tĩnh."},{"en":"We traveled from the airport to the city by coach.","vi":"Chúng tôi đi từ sân bay vào thành phố bằng xe khách."}]','[{"phrase":"head coach"},{"phrase":"football coach"},{"phrase":"by coach"}]',NULL,'/kəʊtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coach/coach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1315,'ngsl-3-12',13,'experiment','thí nghiệm; thử nghiệm','noun','[{"en":"The students did a simple experiment with water and salt.","vi":"Các học sinh làm một thí nghiệm đơn giản với nước và muối."},{"en":"The results of the experiment surprised the scientists.","vi":"Kết quả của thí nghiệm đã khiến các nhà khoa học bất ngờ."},{"en":"As an experiment, I stopped using my phone for a week.","vi":"Để thử nghiệm, tôi đã ngừng dùng điện thoại trong một tuần."}]','[{"phrase":"do an experiment"},{"phrase":"carry out an experiment"},{"phrase":"scientific experiment"}]',NULL,'/ɪkˈsperɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/experiment__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1316,'ngsl-3-12',14,'consideration','sự cân nhắc; sự quan tâm','noun','[{"en":"After careful consideration, we decided not to buy the house.","vi":"Sau khi cân nhắc kỹ, chúng tôi quyết định không mua căn nhà đó."},{"en":"Please take my age into consideration when planning the trip.","vi":"Hãy tính đến tuổi tác của tôi khi lên kế hoạch cho chuyến đi."},{"en":"He shows no consideration for his neighbors when he plays loud music.","vi":"Anh ta chẳng hề quan tâm đến hàng xóm khi mở nhạc ầm ĩ."}]','[{"phrase":"careful consideration"},{"phrase":"take into consideration"},{"phrase":"under consideration"}]',NULL,'/kənˌsɪdəˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsideration__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1317,'ngsl-3-12',15,'strange','lạ; kỳ lạ','adjective','[{"en":"I heard a strange noise coming from the kitchen last night.","vi":"Đêm qua tôi nghe thấy một tiếng động lạ phát ra từ nhà bếp."},{"en":"It felt strange to be back at my old school.","vi":"Quay lại trường cũ khiến tôi có cảm giác thật lạ."},{"en":"Isn''t it strange that nobody answered the phone?","vi":"Không ai nghe điện thoại, chẳng phải lạ lắm sao?"}]','[{"phrase":"strange noise"},{"phrase":"feel strange"},{"phrase":"strange feeling"}]',NULL,'/streɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stran/strange__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1318,'ngsl-3-12',16,'code','mã; bộ quy tắc','noun','[{"en":"Enter the code we sent to your phone.","vi":"Hãy nhập mã mà chúng tôi đã gửi đến điện thoại của bạn."},{"en":"My brother writes code for a small software company.","vi":"Anh trai tôi viết mã cho một công ty phần mềm nhỏ."},{"en":"The school has a strict dress code for students.","vi":"Trường có quy tắc ăn mặc nghiêm ngặt dành cho học sinh."}]','[{"phrase":"dress code"},{"phrase":"write code"},{"phrase":"security code"}]',NULL,'/kəʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cod/code_/code__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1319,'ngsl-3-12',17,'possibly','có thể; có lẽ','adverb','[{"en":"Could you possibly help me carry these boxes?","vi":"Bạn có thể giúp tôi khiêng mấy cái thùng này được không?"},{"en":"This is possibly the best pizza I have ever eaten.","vi":"Đây có lẽ là chiếc pizza ngon nhất tôi từng ăn."},{"en":"The package will arrive on Tuesday or possibly Wednesday.","vi":"Gói hàng sẽ đến vào thứ Ba hoặc có thể là thứ Tư."}]','[{"phrase":"could possibly"},{"phrase":"can''t possibly"},{"phrase":"quite possibly"}]',NULL,'/ˈpɑːsəbli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/possi/possibly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1320,'ngsl-3-12',18,'threat','mối đe dọa; lời đe dọa','noun','[{"en":"Strong winds are a serious threat to homes near the coast.","vi":"Gió mạnh là mối đe dọa nghiêm trọng đối với những ngôi nhà gần bờ biển."},{"en":"The manager''s threat to cancel the project worried everyone.","vi":"Lời đe dọa hủy dự án của người quản lý khiến mọi người lo lắng."},{"en":"Computer viruses are a constant threat to our office network.","vi":"Virus máy tính là mối đe dọa thường trực đối với mạng máy tính ở văn phòng chúng tôi."}]','[{"phrase":"serious threat"},{"phrase":"major threat"},{"phrase":"pose a threat"},{"phrase":"constant threat"}]',NULL,'/θret/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/threa/threat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1321,'ngsl-3-12',19,'accident','tai nạn; sự tình cờ','noun','[{"en":"She broke her arm in a bike accident last summer.","vi":"Cô ấy bị gãy tay trong một vụ tai nạn xe đạp mùa hè năm ngoái."},{"en":"Sorry, I deleted your file by accident.","vi":"Xin lỗi, tôi vô tình xóa mất tệp của bạn."},{"en":"We found this great little restaurant completely by accident.","vi":"Chúng tôi tìm thấy nhà hàng nhỏ tuyệt vời này hoàn toàn tình cờ."}]','[{"phrase":"car accident"},{"phrase":"by accident"},{"phrase":"have an accident"}]',NULL,'/ˈæksɪdənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accid/accident__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1322,'ngsl-3-12',20,'impossible','không thể','adjective','[{"en":"It''s impossible to sleep with all this noise outside.","vi":"Không thể nào ngủ được với chừng ấy tiếng ồn bên ngoài."},{"en":"Finding a cheap apartment downtown is almost impossible.","vi":"Tìm được một căn hộ rẻ ở trung tâm thành phố gần như là không thể."},{"en":"The instructions were impossible to understand without pictures.","vi":"Bản hướng dẫn không thể hiểu nổi nếu không có hình minh họa."}]','[{"phrase":"almost impossible"},{"phrase":"nearly impossible"},{"phrase":"impossible task"}]',NULL,'/ɪmˈpɑːsəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impos/impossible__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1323,'ngsl-3-12',21,'revenue','doanh thu','noun','[{"en":"The company''s revenue grew by ten percent last year.","vi":"Doanh thu của công ty đã tăng mười phần trăm vào năm ngoái."},{"en":"Tourism brings in most of the town''s revenue.","vi":"Du lịch mang lại phần lớn doanh thu cho thị trấn."},{"en":"We need to find new ways to increase revenue.","vi":"Chúng ta cần tìm những cách mới để tăng doanh thu."}]','[{"phrase":"increase revenue"},{"phrase":"annual revenue"},{"phrase":"generate revenue"},{"phrase":"tax revenue"}]',NULL,'/ˈrevənuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/reven/revenue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1324,'ngsl-3-12',22,'enable','cho phép; giúp có thể','verb','[{"en":"This app enables you to send money to friends instantly.","vi":"Ứng dụng này cho phép bạn chuyển tiền cho bạn bè ngay lập tức."},{"en":"The scholarship enabled her to study abroad for a year.","vi":"Học bổng đã giúp cô ấy có thể đi du học một năm."},{"en":"Good public transportation enables people to live without a car.","vi":"Giao thông công cộng tốt giúp mọi người có thể sống mà không cần ô tô."}]','[{"phrase":"enable people to"},{"phrase":"enable users to"}]','enable somebody to do something','/ɪˈneɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ena/enabl/enable__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1325,'ngsl-3-12',23,'afraid','sợ; e rằng','adjective','[{"en":"My little sister is afraid of the dark.","vi":"Em gái tôi sợ bóng tối."},{"en":"Don''t be afraid to ask questions in class.","vi":"Đừng sợ đặt câu hỏi trong lớp."},{"en":"I''m afraid we don''t have any rooms left tonight.","vi":"Tôi e rằng tối nay chúng tôi không còn phòng trống nào."}]','[{"phrase":"afraid of"},{"phrase":"I''m afraid"},{"phrase":"afraid to ask"}]','không dùng trước danh từ (không nói "an afraid child")','/əˈfreɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/afr/afrai/afraid__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1326,'ngsl-3-12',24,'active','năng động; tích cực; đang hoạt động','adjective','[{"en":"My grandmother stays active by walking every morning.","vi":"Bà tôi giữ cho mình năng động bằng cách đi bộ mỗi sáng."},{"en":"He takes an active part in the school''s music club.","vi":"Cậu ấy tham gia tích cực vào câu lạc bộ âm nhạc của trường."},{"en":"Your account stays active if you log in once a month.","vi":"Tài khoản của bạn vẫn hoạt động nếu bạn đăng nhập mỗi tháng một lần."}]','[{"phrase":"stay active"},{"phrase":"take an active part"},{"phrase":"active role"},{"phrase":"physically active"}]',NULL,'/ˈæktɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/activ/active__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1327,'ngsl-3-12',25,'conclude','kết luận; kết thúc','verb','[{"en":"The doctor concluded that the pain was caused by stress.","vi":"Bác sĩ kết luận rằng cơn đau là do căng thẳng gây ra."},{"en":"After reading the reviews, we concluded that the hotel wasn''t worth it.","vi":"Sau khi đọc các bài đánh giá, chúng tôi kết luận rằng khách sạn đó không đáng tiền."},{"en":"The meeting concluded with a short speech from the manager.","vi":"Cuộc họp kết thúc bằng một bài phát biểu ngắn của người quản lý."}]','[{"phrase":"conclude that"},{"phrase":"conclude with"},{"phrase":"the report concludes"}]',NULL,'/kənˈkluːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconclude__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1328,'ngsl-3-12',26,'religious','tôn giáo; sùng đạo','adjective','[{"en":"The old town has many beautiful religious buildings.","vi":"Khu phố cổ có nhiều công trình tôn giáo đẹp."},{"en":"Many shops close for a few days during religious holidays.","vi":"Nhiều cửa hàng đóng cửa vài ngày trong các dịp lễ tôn giáo."},{"en":"My grandparents are very religious, but my parents are not.","vi":"Ông bà tôi rất sùng đạo, nhưng bố mẹ tôi thì không."}]','[{"phrase":"religious holiday"},{"phrase":"religious beliefs"},{"phrase":"deeply religious"}]',NULL,'/rɪˈlɪdʒəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relig/religious__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1329,'ngsl-3-12',27,'cancer','bệnh ung thư','noun','[{"en":"Smoking greatly increases the risk of lung cancer.","vi":"Hút thuốc làm tăng đáng kể nguy cơ mắc ung thư phổi."},{"en":"Wearing sunscreen helps protect you from skin cancer.","vi":"Thoa kem chống nắng giúp bảo vệ bạn khỏi ung thư da."},{"en":"Scientists are developing new ways to treat cancer.","vi":"Các nhà khoa học đang phát triển những phương pháp mới để điều trị ung thư."}]','[{"phrase":"lung cancer"},{"phrase":"skin cancer"},{"phrase":"treat cancer"},{"phrase":"cancer research"}]',NULL,'/ˈkænsər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/can/cance/cancer__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1330,'ngsl-3-12',28,'convince','thuyết phục; làm cho tin','verb','[{"en":"I finally convinced my parents to let me get a dog.","vi":"Cuối cùng tôi cũng thuyết phục được bố mẹ cho tôi nuôi một con chó."},{"en":"She tried to convince him that the plan would work.","vi":"Cô ấy cố thuyết phục anh ấy rằng kế hoạch sẽ thành công."},{"en":"I''m not convinced that this is the right decision.","vi":"Tôi không tin chắc rằng đây là quyết định đúng đắn."}]','[{"phrase":"try to convince"},{"phrase":"fully convinced"},{"phrase":"not convinced"}]',NULL,'/kənˈvɪns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvince__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1331,'ngsl-3-12',29,'vary','thay đổi; khác nhau','verb','[{"en":"Prices vary depending on the time of year.","vi":"Giá cả thay đổi tùy theo thời điểm trong năm."},{"en":"The size of the rooms varies from floor to floor.","vi":"Kích thước các phòng khác nhau tùy từng tầng."},{"en":"Try to vary your meals and eat more vegetables.","vi":"Hãy cố gắng thay đổi món ăn thường xuyên và ăn nhiều rau hơn."}]','[{"phrase":"vary widely"},{"phrase":"vary greatly"},{"phrase":"vary in size"},{"phrase":"vary depending on"}]',NULL,'/ˈveri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/vary_/vary__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1332,'ngsl-3-12',30,'environmental','(thuộc) môi trường','adjective','[{"en":"Plastic waste is a huge environmental problem in many cities.","vi":"Rác thải nhựa là một vấn đề môi trường lớn ở nhiều thành phố."},{"en":"The company is trying to reduce its environmental impact.","vi":"Công ty đang cố gắng giảm tác động đến môi trường."},{"en":"She joined an environmental group at her university.","vi":"Cô ấy đã tham gia một nhóm hoạt động vì môi trường ở trường đại học."}]','[{"phrase":"environmental problem"},{"phrase":"environmental impact"},{"phrase":"environmental protection"},{"phrase":"environmental group"}]',NULL,'/ɪnˌvaɪrənˈmentl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envir/environmental__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1333,'ngsl-3-13',1,'sun','mặt trời; ánh nắng','noun','[{"en":"The sun rises earlier in summer than in winter.","vi":"Vào mùa hè, mặt trời mọc sớm hơn mùa đông."},{"en":"We sat in the sun and ate our lunch.","vi":"Chúng tôi ngồi dưới nắng và ăn trưa."},{"en":"Don''t forget to wear a hat when the sun is strong.","vi":"Đừng quên đội mũ khi trời nắng gắt."}]','[{"phrase":"the sun rises"},{"phrase":"the sun sets"},{"phrase":"in the sun"},{"phrase":"the sun shines"}]',NULL,'/sʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sun/sun__/sun__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1334,'ngsl-3-13',2,'healthy','khỏe mạnh; tốt cho sức khỏe','adjective','[{"en":"My grandmother is still very healthy at the age of eighty.","vi":"Bà tôi vẫn rất khỏe mạnh ở tuổi tám mươi."},{"en":"Try to eat a healthy breakfast before you go to school.","vi":"Hãy cố gắng ăn một bữa sáng tốt cho sức khỏe trước khi đến trường."},{"en":"Walking every day is one of the easiest ways to stay healthy.","vi":"Đi bộ mỗi ngày là một trong những cách dễ nhất để giữ sức khỏe."}]','[{"phrase":"healthy diet"},{"phrase":"healthy food"},{"phrase":"stay healthy"},{"phrase":"healthy lifestyle"}]',NULL,'/ˈhelθi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/healt/healthy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1335,'ngsl-3-13',3,'blow','thổi; bị gió thổi bay','verb','[{"en":"In winter, a cold wind blows from the north.","vi":"Vào mùa đông, gió lạnh thổi từ phía bắc."},{"en":"She blew out the candles on her birthday cake.","vi":"Cô ấy thổi tắt nến trên bánh sinh nhật."},{"en":"My hat blew away when we were standing on the bridge.","vi":"Mũ của tôi bị gió thổi bay khi chúng tôi đang đứng trên cầu."}]','[{"phrase":"wind blows"},{"phrase":"blow out the candles"},{"phrase":"blow your nose"}]','blow – blew – blown','/bləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/blow_/blow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1336,'ngsl-3-13',4,'volume','âm lượng; khối lượng, lượng; tập (sách)','noun','[{"en":"Could you turn down the volume a little, please?","vi":"Bạn có thể vặn nhỏ âm lượng một chút được không?"},{"en":"The volume of traffic increases sharply during the holidays.","vi":"Lượng xe cộ tăng mạnh vào những ngày lễ."},{"en":"The second volume of the series will come out next year.","vi":"Tập thứ hai của bộ sách sẽ ra mắt vào năm sau."}]','[{"phrase":"turn up the volume"},{"phrase":"turn down the volume"},{"phrase":"volume of traffic"},{"phrase":"large volume"}]',NULL,'/ˈvɑːljəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volum/volume__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1337,'ngsl-3-13',5,'location','vị trí; địa điểm','noun','[{"en":"The hotel is in a great location near the beach.","vi":"Khách sạn nằm ở vị trí rất đẹp gần bãi biển."},{"en":"Please send me the exact location of the restaurant.","vi":"Hãy gửi cho tôi vị trí chính xác của nhà hàng."},{"en":"They changed the location of the meeting at the last minute.","vi":"Họ đã đổi địa điểm cuộc họp vào phút chót."}]','[{"phrase":"exact location"},{"phrase":"central location"},{"phrase":"great location"}]',NULL,'/ləʊˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/locat/location__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1338,'ngsl-3-13',6,'invest','đầu tư','verb','[{"en":"My parents invested all their savings in a small shop.","vi":"Bố mẹ tôi đã đầu tư toàn bộ tiền tiết kiệm vào một cửa hàng nhỏ."},{"en":"The company plans to invest more money in training its staff.","vi":"Công ty dự định đầu tư thêm tiền vào việc đào tạo nhân viên."},{"en":"You should invest time in learning a new language.","vi":"Bạn nên đầu tư thời gian vào việc học một ngôn ngữ mới."}]','[{"phrase":"invest money"},{"phrase":"invest time"},{"phrase":"invest heavily in"}]','invest in something: đầu tư vào cái gì','/ɪnˈvest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/invest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1339,'ngsl-3-13',7,'proceed','tiến hành; tiếp tục; đi tới (nơi nào)','verb','[{"en":"After a short break, the meeting proceeded as planned.","vi":"Sau giờ nghỉ ngắn, cuộc họp tiếp tục diễn ra như kế hoạch."},{"en":"Passengers for the flight to Tokyo should proceed to gate 12.","vi":"Hành khách đi chuyến bay đến Tokyo xin vui lòng đến cửa số 12."},{"en":"We can proceed with the project once the budget is approved.","vi":"Chúng ta có thể tiến hành dự án khi ngân sách được duyệt."}]','[{"phrase":"proceed with"},{"phrase":"proceed to"},{"phrase":"proceed as planned"}]','proceed with something: tiến hành việc gì','/prəʊˈsiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/proceed__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1340,'ngsl-3-13',8,'wash','rửa; giặt','verb','[{"en":"Always wash your hands before you eat.","vi":"Luôn rửa tay trước khi ăn."},{"en":"I need to wash these clothes before our trip.","vi":"Tôi cần giặt chỗ quần áo này trước chuyến đi."},{"en":"Whose turn is it to wash the dishes tonight?","vi":"Tối nay đến lượt ai rửa bát?"}]','[{"phrase":"wash your hands"},{"phrase":"wash the dishes"},{"phrase":"wash clothes"},{"phrase":"wash your hair"}]',NULL,'/wɑːʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/was/wash_/wash__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1341,'ngsl-3-13',9,'actor','diễn viên','noun','[{"en":"He wanted to become an actor when he was a child.","vi":"Hồi nhỏ, anh ấy muốn trở thành diễn viên."},{"en":"The actors are practicing for the school play tonight.","vi":"Các diễn viên đang tập cho vở kịch của trường tối nay."},{"en":"She is one of the best young actors in the country.","vi":"Cô ấy là một trong những diễn viên trẻ giỏi nhất cả nước."}]','[{"phrase":"famous actor"},{"phrase":"young actor"},{"phrase":"leading actor"},{"phrase":"become an actor"}]','nữ diễn viên: actress','/ˈæktər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actor/actor__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1342,'ngsl-3-13',10,'glad','vui mừng; sẵn lòng','adjective','[{"en":"I''m glad you could come to my party.","vi":"Tôi rất vui vì bạn đã đến dự tiệc của tôi."},{"en":"We were glad to hear that your mother is feeling better.","vi":"Chúng tôi rất mừng khi nghe tin mẹ bạn đã khỏe hơn."},{"en":"I''d be glad to show you around the city this weekend.","vi":"Tôi sẵn lòng dẫn bạn đi tham quan thành phố vào cuối tuần này."}]','[{"phrase":"glad to hear"},{"phrase":"be glad to help"},{"phrase":"really glad"}]','chỉ đứng sau động từ (be glad), không đứng trước danh từ','/ɡlæd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gla/glad_/glad__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1343,'ngsl-3-13',11,'tape','băng dính; băng (ghi âm, ghi hình)','noun','[{"en":"I need some tape to close this box.","vi":"Tôi cần ít băng dính để dán cái hộp này lại."},{"en":"She fixed the torn page with a small piece of tape.","vi":"Cô ấy dán lại trang giấy bị rách bằng một miếng băng dính nhỏ."},{"en":"My dad still has old tapes of songs he recorded from the radio.","vi":"Bố tôi vẫn còn những cuộn băng cũ thu các bài hát từ đài phát thanh."}]','[{"phrase":"piece of tape"},{"phrase":"sticky tape"},{"phrase":"masking tape"}]',NULL,'/teɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tap/tape_/tape__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1344,'ngsl-3-13',12,'whereas','trong khi (đó); còn','conjunction','[{"en":"I love spicy food, whereas my brother can''t eat it at all.","vi":"Tôi rất thích đồ ăn cay, trong khi anh trai tôi hoàn toàn không ăn được."},{"en":"Some students learn quickly, whereas others need more time.","vi":"Một số học sinh học nhanh, còn những em khác cần nhiều thời gian hơn."},{"en":"Whereas the city is noisy and crowded, the village is peaceful.","vi":"Trong khi thành phố ồn ào và đông đúc thì ngôi làng lại yên bình."}]','[{"phrase":"whereas others"},{"phrase":"whereas in the past"}]','dùng để nêu hai ý trái ngược; trang trọng hơn while','/ˌwerˈæz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/whereas__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1345,'ngsl-3-13',13,'opposite','đối diện; trái ngược','adjective','[{"en":"They live in the house on the opposite side of the road.","vi":"Họ sống trong ngôi nhà ở phía bên kia đường."},{"en":"My sister and I have opposite opinions about almost everything.","vi":"Chị tôi và tôi có ý kiến trái ngược nhau về hầu hết mọi chuyện."},{"en":"The two cars were driving in opposite directions.","vi":"Hai chiếc xe đang chạy theo hai hướng ngược nhau."}]','[{"phrase":"opposite side"},{"phrase":"opposite direction"},{"phrase":"the exact opposite"}]','cũng là giới từ: opposite the station (đối diện nhà ga)','/ˈɑːpəzɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppos/opposite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1346,'ngsl-3-13',14,'stone','đá; hòn đá','noun','[{"en":"The old bridge is made of stone.","vi":"Cây cầu cổ được xây bằng đá."},{"en":"The children were throwing stones into the river.","vi":"Bọn trẻ đang ném đá xuống sông."},{"en":"I got a small stone in my shoe while we were hiking.","vi":"Tôi bị một viên đá nhỏ lọt vào giày khi chúng tôi đang đi bộ đường dài."}]','[{"phrase":"made of stone"},{"phrase":"stone wall"},{"phrase":"throw stones"}]','chất liệu đá: không đếm được; hòn đá: đếm được','/stəʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stone/stone__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1347,'ngsl-3-13',15,'sum','khoản tiền; tổng số','noun','[{"en":"They paid a large sum of money for the old house.","vi":"Họ đã trả một khoản tiền lớn cho ngôi nhà cũ."},{"en":"She saved a small sum every month for her trip.","vi":"Cô ấy tiết kiệm một khoản tiền nhỏ mỗi tháng cho chuyến đi."},{"en":"The sum of five and seven is twelve.","vi":"Tổng của năm và bảy là mười hai."}]','[{"phrase":"sum of money"},{"phrase":"large sum"},{"phrase":"small sum"}]','sum up: tóm tắt','/sʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/sum__/sum__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1348,'ngsl-3-13',16,'murder','vụ giết người, án mạng; tội giết người','noun','[{"en":"The police are still investigating the murder.","vi":"Cảnh sát vẫn đang điều tra vụ giết người."},{"en":"The film is about a detective trying to solve a murder.","vi":"Bộ phim kể về một thám tử đang cố gắng phá một vụ án mạng."},{"en":"I stayed up late reading a murder mystery novel.","vi":"Tôi thức khuya đọc một cuốn tiểu thuyết trinh thám về án mạng."}]','[{"phrase":"murder case"},{"phrase":"murder mystery"},{"phrase":"solve a murder"}]','cũng là động từ: giết (người) có chủ ý','/ˈmɜːrdər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mur/murde/murder__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1349,'ngsl-3-13',17,'monitor','theo dõi; giám sát','verb','[{"en":"Nurses monitor the patients carefully throughout the night.","vi":"Các y tá theo dõi bệnh nhân cẩn thận suốt đêm."},{"en":"This app helps you monitor how much you sleep.","vi":"Ứng dụng này giúp bạn theo dõi mình ngủ được bao nhiêu."},{"en":"Weekly tests help teachers monitor progress throughout the term.","vi":"Các bài kiểm tra hằng tuần giúp giáo viên theo dõi sự tiến bộ trong suốt học kỳ."}]','[{"phrase":"monitor progress"},{"phrase":"closely monitor"},{"phrase":"monitor the situation"}]','cũng là danh từ: màn hình (máy tính)','/ˈmɑːnɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/monit/monitor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1350,'ngsl-3-13',18,'soldier','người lính, binh sĩ','noun','[{"en":"Her grandfather was a soldier for twenty years.","vi":"Ông của cô ấy đã làm lính suốt hai mươi năm."},{"en":"The soldiers marched through the town during the parade.","vi":"Những người lính diễu hành qua thị trấn trong buổi diễu binh."},{"en":"My cousin wants to become a soldier after he finishes school.","vi":"Anh họ tôi muốn trở thành người lính sau khi học xong."}]','[{"phrase":"young soldier"},{"phrase":"become a soldier"},{"phrase":"former soldier"}]',NULL,'/ˈsəʊldʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/soldi/soldier__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1351,'ngsl-3-13',19,'finance','tài chính','noun','[{"en":"She wants to work in finance after she graduates.","vi":"Cô ấy muốn làm trong ngành tài chính sau khi tốt nghiệp."},{"en":"We need to talk about our family finances this month.","vi":"Tháng này chúng ta cần bàn về tình hình tài chính của gia đình."},{"en":"He is studying finance at a university in Singapore.","vi":"Anh ấy đang học ngành tài chính tại một trường đại học ở Singapore."}]','[{"phrase":"personal finance"},{"phrase":"finance department"},{"phrase":"work in finance"}]','finances (số nhiều): tình hình tiền bạc','/ˈfaɪnæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finan/finance__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1352,'ngsl-3-13',20,'hate','ghét','verb','[{"en":"I really hate getting up early on cold mornings.","vi":"Tôi rất ghét phải dậy sớm vào những buổi sáng lạnh."},{"en":"My little brother hates vegetables, especially carrots.","vi":"Em trai tôi ghét rau, nhất là cà rốt."},{"en":"She hated her first job, but she learned a lot from it.","vi":"Cô ấy ghét công việc đầu tiên, nhưng đã học được rất nhiều từ nó."}]','[{"phrase":"really hate"},{"phrase":"hate it when"},{"phrase":"hate to say"}]','hate + V-ing / to V','/heɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hat/hate_/hate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1353,'ngsl-3-13',21,'egg','trứng','noun','[{"en":"I usually have a fried egg and toast for breakfast.","vi":"Tôi thường ăn một quả trứng chiên với bánh mì nướng vào bữa sáng."},{"en":"Can you buy a dozen eggs on your way home?","vi":"Bạn mua giúp một tá trứng trên đường về nhé?"},{"en":"The bird laid three eggs in the nest.","vi":"Con chim đã đẻ ba quả trứng trong tổ."}]','[{"phrase":"fried egg"},{"phrase":"boiled egg"},{"phrase":"lay eggs"}]',NULL,'/eɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/egg/egg__/egg__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1354,'ngsl-3-13',22,'concert','buổi hòa nhạc','noun','[{"en":"We''re going to a rock concert on Saturday night.","vi":"Tối thứ Bảy chúng tôi sẽ đi xem một buổi hòa nhạc rock."},{"en":"The tickets for the concert sold out in an hour.","vi":"Vé của buổi hòa nhạc đã bán hết chỉ trong một giờ."},{"en":"My daughter will play the piano at the school concert.","vi":"Con gái tôi sẽ chơi piano trong buổi hòa nhạc của trường."}]','[{"phrase":"go to a concert"},{"phrase":"live concert"},{"phrase":"rock concert"},{"phrase":"concert tickets"}]',NULL,'/ˈkɑːnsərt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcert__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1355,'ngsl-3-13',23,'shock','cú sốc; sự bàng hoàng','noun','[{"en":"The news of the factory closing came as a shock to everyone.","vi":"Tin nhà máy đóng cửa là một cú sốc đối với mọi người."},{"en":"She was still in shock after the car accident.","vi":"Cô ấy vẫn còn bàng hoàng sau vụ tai nạn xe hơi."},{"en":"It was a real shock to see how expensive everything was.","vi":"Thật là sốc khi thấy mọi thứ đắt đỏ đến thế nào."}]','[{"phrase":"come as a shock"},{"phrase":"in shock"},{"phrase":"a real shock"}]',NULL,'/ʃɑːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shock/shock__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1356,'ngsl-3-13',24,'comfortable','thoải mái; dễ chịu','adjective','[{"en":"These shoes are really comfortable for long walks.","vi":"Đôi giày này đi bộ đường dài rất thoải mái."},{"en":"Please make yourself comfortable while I make some tea.","vi":"Bạn cứ tự nhiên nhé, để tôi đi pha ít trà."},{"en":"I don''t feel comfortable speaking in front of large groups.","vi":"Tôi không thấy thoải mái khi nói trước đông người."}]','[{"phrase":"make yourself comfortable"},{"phrase":"feel comfortable"},{"phrase":"comfortable shoes"},{"phrase":"comfortable chair"}]',NULL,'/ˈkʌmftəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comfo/comfortable__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1357,'ngsl-3-13',25,'usual','thường lệ; thông thường','adjective','[{"en":"Let''s meet at the usual place after work.","vi":"Sau giờ làm mình gặp nhau ở chỗ quen nhé."},{"en":"The bus was later than usual this morning.","vi":"Sáng nay xe buýt đến muộn hơn thường lệ."},{"en":"As usual, my brother forgot to call our mother on her birthday.","vi":"Như thường lệ, anh trai tôi lại quên gọi điện cho mẹ vào ngày sinh nhật của mẹ."}]','[{"phrase":"as usual"},{"phrase":"than usual"},{"phrase":"the usual place"}]',NULL,'/ˈjuːʒuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/usu/usual/usual__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1358,'ngsl-3-13',26,'carefully','cẩn thận; kỹ lưỡng','adverb','[{"en":"Please read the instructions carefully before you start.","vi":"Hãy đọc kỹ hướng dẫn trước khi bắt đầu."},{"en":"She carefully placed the glasses on the top shelf.","vi":"Cô ấy cẩn thận đặt những chiếc ly lên kệ trên cùng."},{"en":"You should drive carefully because the roads are icy tonight.","vi":"Bạn nên lái xe cẩn thận vì tối nay đường đóng băng."}]','[{"phrase":"read carefully"},{"phrase":"listen carefully"},{"phrase":"drive carefully"},{"phrase":"think carefully"}]',NULL,'/ˈkerfəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/caref/carefully__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1359,'ngsl-3-13',27,'pack','xếp đồ (vào vali, túi); đóng gói','verb','[{"en":"It only took me ten minutes to pack a bag for the weekend.","vi":"Tôi chỉ mất mười phút để xếp đồ vào túi cho chuyến đi cuối tuần."},{"en":"I always pack too many clothes when I travel.","vi":"Lúc nào đi du lịch tôi cũng xếp quá nhiều quần áo vào vali."},{"en":"Workers pack the fruit into boxes before it leaves the farm.","vi":"Công nhân đóng trái cây vào thùng trước khi chuyển ra khỏi trang trại."}]','[{"phrase":"pack a bag"},{"phrase":"pack a suitcase"},{"phrase":"pack up"},{"phrase":"pack your things"}]',NULL,'/pæk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pac/pack_/pack__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1360,'ngsl-3-13',28,'recall','nhớ lại','verb','[{"en":"I can''t recall the name of the hotel we stayed at.","vi":"Tôi không nhớ nổi tên khách sạn mà chúng tôi đã ở."},{"en":"She recalled meeting him at a friend''s wedding years ago.","vi":"Cô ấy nhớ lại đã gặp anh ấy ở đám cưới của một người bạn nhiều năm trước."},{"en":"As far as I can recall, the meeting started at nine.","vi":"Theo như tôi nhớ thì cuộc họp bắt đầu lúc chín giờ."}]','[{"phrase":"can''t recall"},{"phrase":"as far as I can recall"},{"phrase":"clearly recall"}]','recall + V-ing: nhớ lại đã làm gì','/rɪˈkɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recal/recall__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1361,'ngsl-3-13',29,'wine','rượu vang','noun','[{"en":"Would you like a glass of red wine with dinner?","vi":"Bạn có muốn một ly rượu vang đỏ trong bữa tối không?"},{"en":"This region is famous for its excellent wine.","vi":"Vùng này nổi tiếng với rượu vang hảo hạng."},{"en":"We bought a bottle of wine as a gift for our hosts.","vi":"Chúng tôi mua một chai rượu vang làm quà cho chủ nhà."}]','[{"phrase":"glass of wine"},{"phrase":"bottle of wine"},{"phrase":"red wine"},{"phrase":"white wine"}]',NULL,'/waɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/wine_/wine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1362,'ngsl-3-13',30,'camera','máy ảnh; camera','noun','[{"en":"I forgot to bring my camera on our vacation.","vi":"Tôi quên mang theo máy ảnh trong kỳ nghỉ của chúng tôi."},{"en":"There are security cameras at every door of the store.","vi":"Có camera an ninh ở mọi cửa ra vào của cửa hàng."},{"en":"She smiled at the camera when her father took a photo.","vi":"Cô bé mỉm cười nhìn vào máy ảnh khi bố chụp hình."}]','[{"phrase":"digital camera"},{"phrase":"security camera"},{"phrase":"smile at the camera"}]',NULL,'/ˈkæmrə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cam/camer/camera__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1363,'ngsl-3-14',1,'swim','bơi','verb','[{"en":"My little brother learned to swim when he was five.","vi":"Em trai tôi học bơi khi lên năm tuổi."},{"en":"We swam in the lake every morning during our vacation.","vi":"Chúng tôi bơi ở hồ mỗi sáng trong kỳ nghỉ."},{"en":"Do you want to go swimming after work today?","vi":"Hôm nay tan làm bạn có muốn đi bơi không?"}]','[{"phrase":"learn to swim"},{"phrase":"go swimming"},{"phrase":"swim in the sea"}]','swim – swam – swum','/swɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swi/swim_/swim__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1364,'ngsl-3-14',2,'manufacture','sản xuất; chế tạo','verb','[{"en":"This factory manufactures parts for cars and trucks.","vi":"Nhà máy này sản xuất phụ tùng cho ô tô và xe tải."},{"en":"Most of our phones are manufactured in Asia.","vi":"Phần lớn điện thoại của chúng tôi được sản xuất ở châu Á."},{"en":"The company started to manufacture its own furniture last year.","vi":"Năm ngoái công ty bắt đầu tự sản xuất đồ nội thất."}]','[{"phrase":"manufacture goods"},{"phrase":"manufacture products"},{"phrase":"locally manufactured"}]',NULL,'/ˌmænjuˈfæktʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manuf/manufacture__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1365,'ngsl-3-14',3,'theater','nhà hát; rạp chiếu phim','noun','[{"en":"We saw a wonderful play at the theater last night.","vi":"Tối qua chúng tôi xem một vở kịch tuyệt vời ở nhà hát."},{"en":"The new movie opens in theaters next Friday.","vi":"Bộ phim mới sẽ ra rạp vào thứ Sáu tới."},{"en":"Please turn off your phone before you enter the theater.","vi":"Vui lòng tắt điện thoại trước khi vào rạp."}]','[{"phrase":"go to the theater"},{"phrase":"movie theater"},{"phrase":"theater tickets"}]','Mỹ: theater · Anh: theatre','/ˈθiːətər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1366,'ngsl-3-14',4,'cycle','chu kỳ; chu trình; vòng','noun','[{"en":"The washing machine takes about an hour to finish one cycle.","vi":"Máy giặt mất khoảng một tiếng để chạy xong một chu trình."},{"en":"Children learn about the life cycle of a butterfly at school.","vi":"Trẻ em học về vòng đời của loài bướm ở trường."},{"en":"It''s hard to break the cycle of staying up late.","vi":"Thật khó để thoát khỏi vòng lặp thức khuya."}]','[{"phrase":"life cycle"},{"phrase":"break the cycle"},{"phrase":"vicious cycle"}]',NULL,'/ˈsaɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cyc/cycle/cycle__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1367,'ngsl-3-14',5,'coffee','cà phê','noun','[{"en":"I always have a cup of coffee before I start work.","vi":"Tôi luôn uống một tách cà phê trước khi bắt đầu làm việc."},{"en":"Would you like to get coffee with me this afternoon?","vi":"Chiều nay bạn có muốn đi uống cà phê với tôi không?"},{"en":"She drinks her coffee black, without any sugar or milk.","vi":"Cô ấy uống cà phê đen, không đường cũng không sữa."}]','[{"phrase":"a cup of coffee"},{"phrase":"black coffee"},{"phrase":"make coffee"},{"phrase":"coffee shop"}]',NULL,'/ˈkɔːfi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cof/coffe/coffee__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1368,'ngsl-3-14',6,'totally','hoàn toàn','adverb','[{"en":"I totally forgot about our meeting this morning.","vi":"Tôi quên hẳn cuộc họp của chúng ta sáng nay."},{"en":"The town looks totally different from ten years ago.","vi":"Thị trấn trông hoàn toàn khác so với mười năm trước."},{"en":"You''re totally right, we should leave a bit earlier.","vi":"Bạn hoàn toàn đúng, chúng ta nên đi sớm hơn một chút."}]','[{"phrase":"totally different"},{"phrase":"totally agree"},{"phrase":"totally forget"}]',NULL,'/ˈtəʊtəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tot/total/totally__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1369,'ngsl-3-14',7,'museum','bảo tàng','noun','[{"en":"We spent the whole afternoon at the art museum.","vi":"Chúng tôi dành cả buổi chiều ở bảo tàng nghệ thuật."},{"en":"The museum is free for students on Sundays.","vi":"Bảo tàng miễn phí cho sinh viên vào Chủ nhật."},{"en":"Have you ever visited the history museum in the city center?","vi":"Bạn đã bao giờ tham quan bảo tàng lịch sử ở trung tâm thành phố chưa?"}]','[{"phrase":"visit a museum"},{"phrase":"art museum"},{"phrase":"history museum"}]',NULL,'/mjuˈziːəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/museu/museum__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1370,'ngsl-3-14',8,'visitor','khách; du khách','noun','[{"en":"The park gets thousands of visitors every summer.","vi":"Công viên đón hàng nghìn du khách mỗi mùa hè."},{"en":"We don''t have many visitors since we moved to the country.","vi":"Từ khi chuyển về quê, chúng tôi không có nhiều khách đến chơi."},{"en":"All visitors must sign in at the front desk.","vi":"Tất cả khách phải đăng ký ở quầy lễ tân."}]','[{"phrase":"foreign visitors"},{"phrase":"attract visitors"},{"phrase":"regular visitor"}]',NULL,'/ˈvɪzɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visit/visitor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1371,'ngsl-3-14',9,'freedom','sự tự do','noun','[{"en":"Working from home gives me more freedom to plan my day.","vi":"Làm việc tại nhà cho tôi nhiều tự do hơn để sắp xếp ngày của mình."},{"en":"Teenagers often want more freedom from their parents.","vi":"Thanh thiếu niên thường muốn được bố mẹ cho tự do hơn."},{"en":"After leaving home, she finally enjoyed her freedom.","vi":"Sau khi rời nhà, cuối cùng cô ấy đã được tận hưởng sự tự do."}]','[{"phrase":"freedom to do something"},{"phrase":"enjoy freedom"},{"phrase":"personal freedom"}]','không đếm được','/ˈfriːdəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/freed/freedom__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1372,'ngsl-3-14',10,'construction','sự xây dựng; ngành xây dựng','noun','[{"en":"The new bridge is still under construction.","vi":"Cây cầu mới vẫn đang được xây dựng."},{"en":"My uncle has worked in construction for twenty years.","vi":"Chú tôi đã làm trong ngành xây dựng hai mươi năm."},{"en":"Construction of the hospital will begin next spring.","vi":"Việc xây dựng bệnh viện sẽ bắt đầu vào mùa xuân năm sau."}]','[{"phrase":"under construction"},{"phrase":"construction work"},{"phrase":"construction site"}]',NULL,'/kənˈstrʌkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstruction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1373,'ngsl-3-14',11,'dear','thân mến; thân yêu; quý giá','adjective','[{"en":"She started the letter with \"Dear Grandma.\"","vi":"Cô ấy mở đầu lá thư bằng \"Bà thân yêu\"."},{"en":"He has been a dear friend of mine since high school.","vi":"Anh ấy là bạn thân yêu của tôi từ hồi cấp ba."},{"en":"This old photo is very dear to me.","vi":"Bức ảnh cũ này rất quý giá với tôi."}]','[{"phrase":"dear friend"},{"phrase":"Dear Sir or Madam"},{"phrase":"dear to someone"}]',NULL,'/dɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/dear_/dear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1374,'ngsl-3-14',12,'objective','mục tiêu; khách quan','noun','[{"en":"Our main objective this year is to find more customers.","vi":"Mục tiêu chính của chúng tôi năm nay là tìm thêm khách hàng."},{"en":"The teacher explained the objectives of the course on the first day.","vi":"Thầy giáo giải thích các mục tiêu của khóa học vào ngày đầu tiên."},{"en":"It''s hard to stay objective when your family is involved.","vi":"Thật khó giữ khách quan khi chuyện liên quan đến gia đình mình."}]','[{"phrase":"main objective"},{"phrase":"achieve an objective"},{"phrase":"set objectives"}]',NULL,'/əbˈdʒektɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obj/objec/objective__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1375,'ngsl-3-14',13,'moreover','hơn nữa; ngoài ra','adverb','[{"en":"The hotel was cheap and, moreover, it was very close to the beach.","vi":"Khách sạn rẻ và hơn nữa còn rất gần bãi biển."},{"en":"The plan is too expensive; moreover, it would take years to finish.","vi":"Kế hoạch này quá tốn kém; ngoài ra, phải mất nhiều năm mới hoàn thành."},{"en":"Moreover, the new system will save us a lot of time.","vi":"Hơn nữa, hệ thống mới sẽ giúp chúng ta tiết kiệm rất nhiều thời gian."}]','[{"phrase":"and moreover"},{"phrase":"moreover, it"}]','Thường dùng trong văn viết trang trọng','/mɔːrˈəʊvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/moreo/moreover__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1376,'ngsl-3-14',14,'onto','lên trên; lên','preposition','[{"en":"The cat jumped onto the kitchen table.","vi":"Con mèo nhảy lên bàn bếp."},{"en":"Be careful when you step onto the train.","vi":"Hãy cẩn thận khi bước lên tàu."},{"en":"He poured some water onto the plants in the garden.","vi":"Anh ấy tưới một ít nước lên cây trong vườn."}]','[{"phrase":"jump onto"},{"phrase":"step onto"},{"phrase":"climb onto"},{"phrase":"hold onto"}]',NULL,'/ˈɑːntə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ont/onto_/onto__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1377,'ngsl-3-14',15,'historical','(thuộc) lịch sử','adjective','[{"en":"My father loves reading historical novels in the evening.","vi":"Bố tôi rất thích đọc tiểu thuyết lịch sử vào buổi tối."},{"en":"The old town has many important historical buildings.","vi":"Khu phố cổ có nhiều công trình lịch sử quan trọng."},{"en":"The film is based on real historical events.","vi":"Bộ phim dựa trên các sự kiện lịch sử có thật."}]','[{"phrase":"historical events"},{"phrase":"historical buildings"},{"phrase":"historical novel"},{"phrase":"historical site"}]','historical (liên quan đến lịch sử) ≠ historic (có ý nghĩa lịch sử)','/hɪˈstɔːrɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/historical__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1378,'ngsl-3-14',16,'oppose','phản đối; chống lại','verb','[{"en":"Many parents oppose the plan to close the school.","vi":"Nhiều phụ huynh phản đối kế hoạch đóng cửa trường."},{"en":"I''m strongly opposed to building a road through the park.","vi":"Tôi kịch liệt phản đối việc làm đường xuyên qua công viên."},{"en":"Local people opposed the new factory from the start.","vi":"Người dân địa phương đã phản đối nhà máy mới ngay từ đầu."}]','[{"phrase":"strongly oppose"},{"phrase":"oppose a plan"},{"phrase":"be opposed to"}]','be opposed to + V-ing','/əˈpəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppos/oppose__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1379,'ngsl-3-14',17,'branch','cành cây; chi nhánh','noun','[{"en":"A small bird was sitting on a branch outside my window.","vi":"Một chú chim nhỏ đang đậu trên cành cây ngoài cửa sổ của tôi."},{"en":"The bank has a branch near our office.","vi":"Ngân hàng có một chi nhánh gần văn phòng chúng tôi."},{"en":"She works at the company''s branch in Singapore.","vi":"Cô ấy làm việc tại chi nhánh của công ty ở Singapore."}]','[{"phrase":"tree branch"},{"phrase":"local branch"},{"phrase":"branch office"},{"phrase":"open a branch"}]',NULL,'/bræntʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bra/branc/branch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1380,'ngsl-3-14',18,'vehicle','xe cộ; phương tiện','noun','[{"en":"Please don''t leave your vehicle in front of the gate.","vi":"Vui lòng không để xe trước cổng."},{"en":"More people are buying electric vehicles these days.","vi":"Ngày nay ngày càng nhiều người mua xe điện."},{"en":"The road is closed to all vehicles on Sunday mornings.","vi":"Con đường cấm tất cả xe cộ vào sáng Chủ nhật."}]','[{"phrase":"electric vehicle"},{"phrase":"motor vehicle"},{"phrase":"drive a vehicle"}]',NULL,'/ˈviːəkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/veh/vehic/vehicle__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1381,'ngsl-3-14',19,'scientist','nhà khoa học','noun','[{"en":"My daughter wants to be a scientist when she grows up.","vi":"Con gái tôi muốn trở thành nhà khoa học khi lớn lên."},{"en":"Scientists have found a new kind of fish in the river.","vi":"Các nhà khoa học đã phát hiện một loài cá mới trên sông."},{"en":"A team of scientists is studying the effects of the hot weather.","vi":"Một nhóm nhà khoa học đang nghiên cứu ảnh hưởng của thời tiết nóng."}]','[{"phrase":"team of scientists"},{"phrase":"scientists believe"},{"phrase":"research scientist"}]',NULL,'/ˈsaɪəntɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sci/scien/scientist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1382,'ngsl-3-14',20,'route','tuyến đường; lộ trình','noun','[{"en":"What''s the fastest route to the airport from here?","vi":"Từ đây đến sân bay đi đường nào nhanh nhất?"},{"en":"This bus route goes past the university.","vi":"Tuyến xe buýt này đi ngang qua trường đại học."},{"en":"We took a different route home to avoid the traffic.","vi":"Chúng tôi đi đường khác về nhà để tránh kẹt xe."}]','[{"phrase":"bus route"},{"phrase":"take a route"},{"phrase":"the fastest route"}]',NULL,'/ruːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/route/route__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1383,'ngsl-3-14',21,'bind','buộc; ràng buộc; đóng (sách)','verb','[{"en":"She bound the old letters together with a piece of string.","vi":"Cô ấy buộc những lá thư cũ lại với nhau bằng một sợi dây."},{"en":"Both sides are bound by the terms of the contract.","vi":"Cả hai bên đều bị ràng buộc bởi các điều khoản của hợp đồng."},{"en":"The old book was bound in brown leather.","vi":"Cuốn sách cũ được đóng bìa bằng da màu nâu."}]','[{"phrase":"bind together"},{"phrase":"be bound by"},{"phrase":"legally binding"}]','bind – bound – bound','/baɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bin/bind_/bind__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1384,'ngsl-3-14',22,'belong','thuộc về; đúng chỗ','verb','[{"en":"Excuse me, does this umbrella belong to you?","vi":"Xin lỗi, cái ô này có phải của bạn không?"},{"en":"These books belong on the top shelf.","vi":"Mấy cuốn sách này phải để ở kệ trên cùng."},{"en":"After a few months, I really felt that I belonged here.","vi":"Sau vài tháng, tôi thật sự cảm thấy mình thuộc về nơi này."}]','[{"phrase":"belong to"},{"phrase":"a sense of belonging"},{"phrase":"belong together"}]','belong to + người/nhóm','/bɪˈlɔːŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belon/belong__us_6.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1385,'ngsl-3-14',23,'taste','vị; khẩu vị; gu','noun','[{"en":"I don''t like the taste of this medicine.","vi":"Tôi không thích vị của thuốc này."},{"en":"The soup has a slightly sweet taste.","vi":"Món súp có vị hơi ngọt."},{"en":"My sister has great taste in clothes.","vi":"Chị tôi rất có gu ăn mặc."}]','[{"phrase":"sweet taste"},{"phrase":"good taste"},{"phrase":"taste in music"}]',NULL,'/teɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tas/taste/taste__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1386,'ngsl-3-14',24,'tonight','tối nay; đêm nay','adverb','[{"en":"What do you want to have for dinner tonight?","vi":"Tối nay bạn muốn ăn gì?"},{"en":"I''m too tired to go out tonight.","vi":"Tối nay tôi mệt quá, không muốn ra ngoài."},{"en":"It''s going to be very cold tonight, so take a jacket.","vi":"Đêm nay trời sẽ rất lạnh, nên mang theo áo khoác nhé."}]','[{"phrase":"see you tonight"},{"phrase":"later tonight"},{"phrase":"go out tonight"}]',NULL,'/təˈnaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ton/tonig/tonight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1387,'ngsl-3-14',25,'fashion','thời trang; mốt','noun','[{"en":"She is very interested in fashion and design.","vi":"Cô ấy rất quan tâm đến thời trang và thiết kế."},{"en":"Long skirts are back in fashion this year.","vi":"Váy dài lại trở thành mốt trong năm nay."},{"en":"My brother never cares about the latest fashions.","vi":"Anh tôi chẳng bao giờ quan tâm đến mốt mới nhất."}]','[{"phrase":"in fashion"},{"phrase":"out of fashion"},{"phrase":"fashion show"},{"phrase":"latest fashion"}]',NULL,'/ˈfæʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fas/fashi/fashion__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1388,'ngsl-3-14',26,'danger','sự nguy hiểm; mối nguy; nguy cơ','noun','[{"en":"The doctors say he is now out of danger.","vi":"Các bác sĩ nói anh ấy giờ đã qua cơn nguy hiểm."},{"en":"Children don''t always understand the dangers of busy roads.","vi":"Trẻ em không phải lúc nào cũng hiểu mối nguy hiểm của những con đường đông xe."},{"en":"There is a danger that the river will flood this week.","vi":"Tuần này có nguy cơ sông sẽ bị lũ."}]','[{"phrase":"in danger"},{"phrase":"out of danger"},{"phrase":"danger of"},{"phrase":"serious danger"}]',NULL,'/ˈdeɪndʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dan/dange/danger__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1389,'ngsl-3-14',27,'bomb','quả bom','noun','[{"en":"Workers found an old bomb while digging near the river.","vi":"Công nhân tìm thấy một quả bom cũ khi đang đào gần bờ sông."},{"en":"The police closed the street after a bomb warning.","vi":"Cảnh sát đã phong tỏa con phố sau một cảnh báo có bom."},{"en":"Experts safely removed the bomb from the building site.","vi":"Các chuyên gia đã di dời quả bom khỏi công trường một cách an toàn."}]','[{"phrase":"bomb warning"},{"phrase":"bomb squad"},{"phrase":"drop a bomb"}]',NULL,'/bɑːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bom/bomb_/bomb__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1390,'ngsl-3-14',28,'army','quân đội','noun','[{"en":"My grandfather joined the army when he was eighteen.","vi":"Ông tôi nhập ngũ khi mười tám tuổi."},{"en":"The army helped people leave the flooded villages.","vi":"Quân đội đã giúp người dân rời khỏi những ngôi làng bị ngập lụt."},{"en":"Her brother is an officer in the army.","vi":"Anh trai cô ấy là sĩ quan trong quân đội."}]','[{"phrase":"join the army"},{"phrase":"in the army"},{"phrase":"army officer"}]',NULL,'/ˈɑːrmi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arm/army_/army__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1391,'ngsl-3-14',29,'dangerous','nguy hiểm','adjective','[{"en":"It''s dangerous to use your phone while driving.","vi":"Dùng điện thoại khi lái xe rất nguy hiểm."},{"en":"Some of the snakes in this area are very dangerous.","vi":"Một số loài rắn ở khu vực này rất nguy hiểm."},{"en":"The ice on the lake is thin and dangerous to walk on.","vi":"Băng trên hồ mỏng và đi lên rất nguy hiểm."}]','[{"phrase":"extremely dangerous"},{"phrase":"dangerous situation"},{"phrase":"dangerous to do something"}]',NULL,'/ˈdeɪndʒərəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dan/dange/dangerous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1392,'ngsl-3-14',30,'decrease','giảm; giảm bớt','verb','[{"en":"The number of students in the village school has decreased.","vi":"Số học sinh ở trường làng đã giảm."},{"en":"Regular exercise can decrease your risk of heart disease.","vi":"Tập thể dục đều đặn có thể giảm nguy cơ mắc bệnh tim."},{"en":"Sales decreased by ten percent last month.","vi":"Doanh số đã giảm mười phần trăm vào tháng trước."}]','[{"phrase":"decrease by"},{"phrase":"decrease the risk"},{"phrase":"sharply decrease"}]','decrease ≠ increase (tăng)','/dɪˈkriːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decre/decrease__us_4_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1393,'ngsl-3-15',1,'hurt','làm đau; bị đau; làm tổn thương','verb','[{"en":"I hurt my back while moving the sofa last week.","vi":"Tôi bị đau lưng khi chuyển chiếc ghế sofa tuần trước."},{"en":"My feet really hurt after walking around the city all day.","vi":"Chân tôi đau nhức sau khi đi bộ quanh thành phố cả ngày."},{"en":"It hurt her feelings when nobody remembered her birthday.","vi":"Việc không ai nhớ sinh nhật cô ấy đã làm cô ấy tổn thương."}]','[{"phrase":"hurt your back"},{"phrase":"get hurt"},{"phrase":"hurt someone''s feelings"}]','hurt – hurt – hurt','/hɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hur/hurt_/hurt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1394,'ngsl-3-15',2,'council','hội đồng','noun','[{"en":"The local council plans to build a new park near the school.","vi":"Hội đồng địa phương dự định xây một công viên mới gần trường học."},{"en":"She was elected to the city council last year.","vi":"Cô ấy được bầu vào hội đồng thành phố năm ngoái."},{"en":"The student council meets every Friday to discuss school events.","vi":"Hội đồng học sinh họp vào mỗi thứ Sáu để bàn về các sự kiện của trường."}]','[{"phrase":"city council"},{"phrase":"local council"},{"phrase":"student council"},{"phrase":"council meeting"}]',NULL,'/ˈkaʊnsl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/counc/council__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1395,'ngsl-3-15',3,'editor','biên tập viên; tổng biên tập','noun','[{"en":"My sister works as an editor at a small publishing company.","vi":"Chị tôi làm biên tập viên ở một công ty xuất bản nhỏ."},{"en":"The editor asked me to cut the article to 500 words.","vi":"Biên tập viên yêu cầu tôi cắt bài báo xuống còn 500 chữ."},{"en":"He became the editor of the school newspaper in his final year.","vi":"Anh ấy trở thành tổng biên tập tờ báo trường vào năm cuối."}]','[{"phrase":"newspaper editor"},{"phrase":"magazine editor"},{"phrase":"editor-in-chief"}]',NULL,'/ˈedɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/edito/editor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1396,'ngsl-3-15',4,'normally','thường thì; thông thường; bình thường','adverb','[{"en":"I normally get up at six, but today I woke up late.","vi":"Tôi thường dậy lúc sáu giờ, nhưng hôm nay tôi dậy muộn."},{"en":"Normally, the trip takes about two hours by train.","vi":"Thông thường, chuyến đi mất khoảng hai tiếng bằng tàu hỏa."},{"en":"The doctor checked that the baby was breathing normally.","vi":"Bác sĩ kiểm tra xem em bé có thở bình thường không."}]','[{"phrase":"breathe normally"},{"phrase":"function normally"},{"phrase":"behave normally"}]',NULL,'/ˈnɔːrməli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norma/normally__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1397,'ngsl-3-15',5,'sight','thị lực; cảnh tượng; tầm nhìn','noun','[{"en":"My grandfather''s sight is getting worse, so he can''t drive.","vi":"Thị lực của ông tôi ngày càng kém nên ông không thể lái xe."},{"en":"The sunset over the sea was a beautiful sight.","vi":"Hoàng hôn trên biển là một cảnh tượng tuyệt đẹp."},{"en":"The children waved until the boat was out of sight.","vi":"Bọn trẻ vẫy tay cho đến khi con thuyền khuất tầm mắt."}]','[{"phrase":"out of sight"},{"phrase":"at first sight"},{"phrase":"lose your sight"},{"phrase":"a beautiful sight"}]','sight (tầm nhìn) ≠ site (địa điểm)','/saɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/sight/sight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1398,'ngsl-3-15',6,'generate','tạo ra; sinh ra','verb','[{"en":"The new factory will generate hundreds of jobs for the town.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm cho thị trấn."},{"en":"Solar panels on the roof generate enough electricity for the house.","vi":"Các tấm pin mặt trời trên mái nhà tạo ra đủ điện cho cả ngôi nhà."},{"en":"Her idea generated a lot of interest at the meeting.","vi":"Ý tưởng của cô ấy đã thu hút nhiều sự quan tâm trong cuộc họp."}]','[{"phrase":"generate electricity"},{"phrase":"generate income"},{"phrase":"generate interest"},{"phrase":"generate jobs"}]',NULL,'/ˈdʒenəreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1399,'ngsl-3-15',7,'gift','quà tặng; năng khiếu','noun','[{"en":"Thank you so much for the lovely birthday gift.","vi":"Cảm ơn bạn rất nhiều vì món quà sinh nhật dễ thương."},{"en":"We bought a small gift for our neighbors before leaving.","vi":"Chúng tôi mua một món quà nhỏ tặng hàng xóm trước khi đi."},{"en":"She has a real gift for making people feel welcome.","vi":"Cô ấy thật sự có năng khiếu khiến mọi người cảm thấy được chào đón."}]','[{"phrase":"birthday gift"},{"phrase":"wedding gift"},{"phrase":"gift shop"},{"phrase":"have a gift for"}]',NULL,'/ɡɪft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gif/gift_/gift__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1400,'ngsl-3-15',8,'delivery','sự giao hàng; sự phát (thư)','noun','[{"en":"Delivery is free for orders over fifty dollars.","vi":"Miễn phí giao hàng cho đơn hàng trên năm mươi đô la."},{"en":"We''re still waiting for the delivery of our new fridge.","vi":"Chúng tôi vẫn đang chờ người ta giao chiếc tủ lạnh mới."},{"en":"The mail delivery was late because of the heavy snow.","vi":"Việc phát thư bị trễ do tuyết rơi dày."}]','[{"phrase":"free delivery"},{"phrase":"home delivery"},{"phrase":"delivery date"},{"phrase":"mail delivery"}]',NULL,'/dɪˈlɪvəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/deliv/delivery__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1401,'ngsl-3-15',9,'deny','phủ nhận; chối; từ chối (cho)','verb','[{"en":"He denied taking the money from the drawer.","vi":"Anh ta chối là đã lấy tiền trong ngăn kéo."},{"en":"The company strongly denies that its products are unsafe.","vi":"Công ty kiên quyết phủ nhận việc sản phẩm của họ không an toàn."},{"en":"She was denied entry because she had lost her passport.","vi":"Cô ấy bị từ chối cho nhập cảnh vì đã làm mất hộ chiếu."}]','[{"phrase":"strongly deny"},{"phrase":"deny responsibility"},{"phrase":"deny access to"},{"phrase":"deny entry"}]','deny + V-ing: chối đã làm gì','/dɪˈnaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/deny_/deny__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1402,'ngsl-3-15',10,'guest','khách; khách mời','noun','[{"en":"We have guests coming for dinner tonight, so please tidy up.","vi":"Tối nay nhà mình có khách đến ăn tối, nên hãy dọn dẹp đi nhé."},{"en":"The hotel has a pool that is open to all guests.","vi":"Khách sạn có hồ bơi dành cho tất cả khách lưu trú."},{"en":"She was a guest speaker at our graduation ceremony.","vi":"Cô ấy là diễn giả khách mời trong lễ tốt nghiệp của chúng tôi."}]','[{"phrase":"hotel guest"},{"phrase":"guest room"},{"phrase":"special guest"},{"phrase":"guest speaker"}]',NULL,'/ɡest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gue/guest/guest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1403,'ngsl-3-15',11,'anybody','bất kỳ ai; ai (đó)','pronoun','[{"en":"Is there anybody here who can speak Japanese?","vi":"Ở đây có ai nói được tiếng Nhật không?"},{"en":"I didn''t tell anybody about the surprise party.","vi":"Tôi không kể với ai về bữa tiệc bất ngờ."},{"en":"Anybody can learn to cook if they practice enough.","vi":"Bất kỳ ai cũng có thể học nấu ăn nếu luyện tập đủ nhiều."}]','[{"phrase":"anybody else"},{"phrase":"hardly anybody"},{"phrase":"if anybody"}]','= anyone','/ˈenibɑːdi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anybo/anybody__us_4_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1404,'ngsl-3-15',12,'bedroom','phòng ngủ','noun','[{"en":"Our apartment has two bedrooms and a small kitchen.","vi":"Căn hộ của chúng tôi có hai phòng ngủ và một căn bếp nhỏ."},{"en":"The kids are playing video games in their bedroom.","vi":"Bọn trẻ đang chơi trò chơi điện tử trong phòng ngủ."},{"en":"Can you close the bedroom window before you go to bed?","vi":"Bạn đóng cửa sổ phòng ngủ trước khi đi ngủ được không?"}]','[{"phrase":"master bedroom"},{"phrase":"spare bedroom"},{"phrase":"bedroom window"},{"phrase":"two-bedroom apartment"}]',NULL,'/ˈbedruːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bed/bedro/bedroom__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1405,'ngsl-3-15',13,'quote','trích dẫn; báo giá','verb','[{"en":"The article quotes a doctor who worked at the hospital.","vi":"Bài báo trích dẫn lời một bác sĩ từng làm việc tại bệnh viện."},{"en":"He often quotes lines from his favorite movies.","vi":"Anh ấy hay trích dẫn lời thoại trong những bộ phim mình yêu thích."},{"en":"The builder quoted us a price of two thousand dollars.","vi":"Người thợ xây báo giá cho chúng tôi hai nghìn đô la."}]','[{"phrase":"quote a price"},{"phrase":"quote from"},{"phrase":"widely quoted"}]',NULL,'/kwəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/quo/quote/quote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1406,'ngsl-3-15',14,'climb','leo; trèo; tăng lên','verb','[{"en":"We climbed to the top of the hill to watch the sunrise.","vi":"Chúng tôi leo lên đỉnh đồi để ngắm bình minh."},{"en":"The cat climbed up the tree and wouldn''t come down.","vi":"Con mèo trèo lên cây và không chịu xuống."},{"en":"House prices have climbed steadily over the past five years.","vi":"Giá nhà đã tăng đều đặn trong năm năm qua."}]','[{"phrase":"climb a mountain"},{"phrase":"climb the stairs"},{"phrase":"climb up"},{"phrase":"climb steadily"}]',NULL,'/klaɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/climb/climb__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1407,'ngsl-3-15',15,'basically','về cơ bản; nói chung; thực chất','adverb','[{"en":"Basically, we need more people to finish the project on time.","vi":"Về cơ bản, chúng ta cần thêm người để hoàn thành dự án đúng hạn."},{"en":"The two phones are basically the same, except for the color.","vi":"Hai chiếc điện thoại về cơ bản là giống nhau, chỉ khác màu sắc."},{"en":"He basically lives at his girlfriend''s place these days.","vi":"Dạo này thực chất anh ấy sống luôn ở nhà bạn gái."}]','[{"phrase":"basically the same"},{"phrase":"basically true"},{"phrase":"basically right"}]',NULL,'/ˈbeɪsɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/basic/basically__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1408,'ngsl-3-15',16,'violence','bạo lực','noun','[{"en":"There is too much violence in some children''s cartoons.","vi":"Có quá nhiều bạo lực trong một số phim hoạt hình dành cho trẻ em."},{"en":"The police are trying to stop the violence after the match.","vi":"Cảnh sát đang cố gắng ngăn chặn bạo lực sau trận đấu."},{"en":"Many schools teach students how to solve problems without violence.","vi":"Nhiều trường dạy học sinh cách giải quyết vấn đề mà không dùng bạo lực."}]','[{"phrase":"act of violence"},{"phrase":"use violence"},{"phrase":"domestic violence"}]','không đếm được','/ˈvaɪələns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vio/viole/violence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1409,'ngsl-3-15',17,'minister','bộ trưởng','noun','[{"en":"The minister visited the new hospital on Monday morning.","vi":"Bộ trưởng đã đến thăm bệnh viện mới vào sáng thứ Hai."},{"en":"She became the youngest education minister in the country''s history.","vi":"Bà ấy trở thành bộ trưởng giáo dục trẻ nhất trong lịch sử đất nước."},{"en":"The health minister announced a plan to build more clinics.","vi":"Bộ trưởng Bộ Y tế công bố kế hoạch xây thêm phòng khám."}]','[{"phrase":"prime minister"},{"phrase":"foreign minister"},{"phrase":"health minister"},{"phrase":"education minister"}]','prime minister: thủ tướng','/ˈmɪnɪstər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minis/minister__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1410,'ngsl-3-15',18,'mainly','chủ yếu; phần lớn','adverb','[{"en":"The people who come to this café are mainly students.","vi":"Những người đến quán cà phê này chủ yếu là sinh viên."},{"en":"I chose this apartment mainly because it''s close to work.","vi":"Tôi chọn căn hộ này chủ yếu vì nó gần chỗ làm."},{"en":"The weather will be mainly dry, with some rain in the evening.","vi":"Thời tiết phần lớn sẽ khô ráo, có một chút mưa vào buổi tối."}]','[{"phrase":"mainly because"},{"phrase":"mainly due to"},{"phrase":"consist mainly of"}]',NULL,'/ˈmeɪnli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/mainl/mainly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1411,'ngsl-3-15',19,'mouth','miệng; cửa (sông)','noun','[{"en":"Don''t talk with your mouth full, please.","vi":"Đừng nói chuyện khi miệng đang đầy thức ăn nhé."},{"en":"Open your mouth wide so I can look at your teeth.","vi":"Há miệng thật to để tôi xem răng của bạn nào."},{"en":"The town is at the mouth of the river.","vi":"Thị trấn nằm ở cửa sông."}]','[{"phrase":"open your mouth"},{"phrase":"with your mouth full"},{"phrase":"mouth of the river"},{"phrase":"keep your mouth shut"}]',NULL,'/maʊθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mouth/mouth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1412,'ngsl-3-15',20,'noise','tiếng ồn; tiếng động','noun','[{"en":"I couldn''t sleep because of the noise from the street.","vi":"Tôi không ngủ được vì tiếng ồn ngoài đường."},{"en":"Please try not to make any noise; the baby is sleeping.","vi":"Cố gắng đừng gây tiếng động nhé, em bé đang ngủ."},{"en":"Did you hear that strange noise coming from the kitchen?","vi":"Bạn có nghe thấy tiếng động lạ phát ra từ trong bếp không?"}]','[{"phrase":"make a noise"},{"phrase":"loud noise"},{"phrase":"background noise"},{"phrase":"strange noise"}]',NULL,'/nɔɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/noi/noise/noise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1413,'ngsl-3-15',21,'manner','cách; thái độ; phép lịch sự','noun','[{"en":"She answered the questions in a calm and friendly manner.","vi":"Cô ấy trả lời các câu hỏi một cách bình tĩnh và thân thiện."},{"en":"I didn''t like his manner; he seemed rude and impatient.","vi":"Tôi không thích thái độ của anh ta; anh ta có vẻ thô lỗ và thiếu kiên nhẫn."},{"en":"It''s bad manners to check your phone during dinner.","vi":"Xem điện thoại trong bữa tối là thiếu lịch sự."}]','[{"phrase":"in a friendly manner"},{"phrase":"good manners"},{"phrase":"bad manners"}]','manners (số nhiều): phép lịch sự','/ˈmænər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manne/manner__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1414,'ngsl-3-15',22,'gun','súng','noun','[{"en":"The police officer carried a gun on his belt.","vi":"Viên cảnh sát đeo một khẩu súng bên thắt lưng."},{"en":"The kids had a water gun fight in the backyard.","vi":"Bọn trẻ đấu súng nước ở sân sau."},{"en":"The runners started as soon as they heard the gun.","vi":"Các vận động viên xuất phát ngay khi nghe tiếng súng."}]','[{"phrase":"carry a gun"},{"phrase":"fire a gun"},{"phrase":"water gun"}]',NULL,'/ɡʌn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gun/gun__/gun__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1415,'ngsl-3-15',23,'square','quảng trường; hình vuông','noun','[{"en":"There is a small market in the town square every Saturday.","vi":"Có một phiên chợ nhỏ ở quảng trường thị trấn vào mỗi thứ Bảy."},{"en":"Cut the bread into small squares before serving.","vi":"Cắt bánh mì thành những miếng vuông nhỏ trước khi dọn ra."},{"en":"Draw a square and then divide it into four triangles.","vi":"Vẽ một hình vuông rồi chia nó thành bốn hình tam giác."}]','[{"phrase":"town square"},{"phrase":"main square"},{"phrase":"draw a square"}]',NULL,'/skwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/squ/squar/square__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1416,'ngsl-3-15',24,'occasion','dịp; lần','noun','[{"en":"We save this wine for special occasions like birthdays.","vi":"Chúng tôi để dành chai rượu vang này cho những dịp đặc biệt như sinh nhật."},{"en":"I''ve met her on several occasions, but we rarely talk.","vi":"Tôi đã gặp cô ấy vài lần, nhưng chúng tôi hiếm khi nói chuyện."},{"en":"The wedding was a happy occasion for the whole family.","vi":"Đám cưới là một dịp vui của cả gia đình."}]','[{"phrase":"special occasion"},{"phrase":"on several occasions"},{"phrase":"on this occasion"}]',NULL,'/əˈkeɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occas/occasion__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1417,'ngsl-3-15',25,'familiar','quen thuộc; am hiểu, rành','adjective','[{"en":"Her face looks familiar, but I can''t remember her name.","vi":"Khuôn mặt cô ấy trông quen quen, nhưng tôi không nhớ tên cô ấy."},{"en":"Are you familiar with this part of the city?","vi":"Bạn có rành khu vực này của thành phố không?"},{"en":"It was nice to hear a familiar voice on the phone.","vi":"Thật vui khi nghe thấy một giọng nói quen thuộc qua điện thoại."}]','[{"phrase":"look familiar"},{"phrase":"sound familiar"},{"phrase":"familiar face"},{"phrase":"familiar with"}]','be familiar with sth: quen / rành cái gì','/fəˈmɪliər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fam/famil/familiar__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1418,'ngsl-3-15',26,'ignore','phớt lờ; lờ đi; bỏ qua','verb','[{"en":"She saw me wave but ignored me completely.","vi":"Cô ấy thấy tôi vẫy tay nhưng hoàn toàn phớt lờ tôi."},{"en":"You shouldn''t ignore the pain in your knee.","vi":"Bạn không nên bỏ qua cơn đau ở đầu gối."},{"en":"Just ignore him; he''s only trying to annoy you.","vi":"Cứ lờ anh ta đi, anh ta chỉ đang cố chọc tức bạn thôi."}]','[{"phrase":"completely ignore"},{"phrase":"ignore advice"},{"phrase":"ignore a warning"},{"phrase":"ignore the problem"}]',NULL,'/ɪɡˈnɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ign/ignor/ignore__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1419,'ngsl-3-15',27,'destroy','phá hủy; tàn phá; hủy hoại','verb','[{"en":"A fire destroyed three houses on our street last night.","vi":"Đêm qua một vụ cháy đã thiêu rụi ba ngôi nhà trên phố chúng tôi."},{"en":"The storm completely destroyed the old wooden bridge.","vi":"Cơn bão đã phá hủy hoàn toàn cây cầu gỗ cũ."},{"en":"One bad review can destroy a small restaurant''s reputation.","vi":"Một đánh giá tệ có thể hủy hoại danh tiếng của một nhà hàng nhỏ."}]','[{"phrase":"completely destroy"},{"phrase":"destroyed by fire"},{"phrase":"destroy the environment"}]',NULL,'/dɪˈstrɔɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/destr/destroy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1420,'ngsl-3-15',28,'affair','việc; chuyện; sự kiện','noun','[{"en":"How I spend my money is my own affair.","vi":"Tôi tiêu tiền thế nào là việc riêng của tôi."},{"en":"She enjoys reading about current affairs in the morning paper.","vi":"Cô ấy thích đọc tin thời sự trên báo buổi sáng."},{"en":"Their wedding was a small family affair in the garden.","vi":"Đám cưới của họ là một sự kiện nhỏ trong gia đình, tổ chức ngoài vườn."}]','[{"phrase":"current affairs"},{"phrase":"foreign affairs"},{"phrase":"family affair"},{"phrase":"private affair"}]','current affairs: thời sự','/əˈfer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affai/affair__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1421,'ngsl-3-15',29,'civil','dân sự; công dân; lịch sự','adjective','[{"en":"Every citizen should understand their basic civil rights.","vi":"Mọi công dân nên hiểu các quyền công dân cơ bản của mình."},{"en":"My father worked as a civil servant for thirty years.","vi":"Bố tôi làm công chức nhà nước suốt ba mươi năm."},{"en":"Even when they argue, they stay civil to each other.","vi":"Ngay cả khi cãi nhau, họ vẫn lịch sự với nhau."}]','[{"phrase":"civil rights"},{"phrase":"civil servant"},{"phrase":"civil engineer"}]','civil servant: công chức','/ˈsɪvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/civ/civil/civil__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1422,'ngsl-3-15',30,'locate','xác định vị trí; đặt ở','verb','[{"en":"Our office is located on the third floor of the building.","vi":"Văn phòng của chúng tôi nằm ở tầng ba của tòa nhà."},{"en":"The hotel is conveniently located near the train station.","vi":"Khách sạn nằm ở vị trí thuận tiện gần ga tàu."},{"en":"This app helps you locate your phone if you lose it.","vi":"Ứng dụng này giúp bạn xác định vị trí điện thoại nếu bị mất."}]','[{"phrase":"be located in"},{"phrase":"conveniently located"},{"phrase":"centrally located"}]','be located in/on/near: nằm ở','/ˈləʊkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/locat/locate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1423,'ngsl-3-16',1,'citizen','công dân','noun','[{"en":"She became a citizen of Canada after living there for ten years.","vi":"Cô ấy trở thành công dân Canada sau khi sống ở đó mười năm."},{"en":"Every citizen has the right to vote in local elections.","vi":"Mọi công dân đều có quyền bỏ phiếu trong các cuộc bầu cử địa phương."},{"en":"Senior citizens can travel on city buses for free.","vi":"Người cao tuổi được đi xe buýt thành phố miễn phí."}]','[{"phrase":"senior citizen"},{"phrase":"citizen of"},{"phrase":"ordinary citizens"},{"phrase":"fellow citizens"}]',NULL,'/ˈsɪtɪzn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/citiz/citizen__us_7.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1424,'ngsl-3-16',2,'temperature','nhiệt độ','noun','[{"en":"The temperature dropped below zero last night.","vi":"Đêm qua nhiệt độ đã xuống dưới không độ."},{"en":"The nurse took my temperature and said I had a slight fever.","vi":"Y tá đo nhiệt độ cho tôi và nói tôi hơi sốt."},{"en":"Bake the cake at a low temperature for about forty minutes.","vi":"Nướng bánh ở nhiệt độ thấp trong khoảng bốn mươi phút."}]','[{"phrase":"high temperature"},{"phrase":"low temperature"},{"phrase":"room temperature"},{"phrase":"take someone''s temperature"}]',NULL,'/ˈtemprətʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tem/tempe/temperature__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1425,'ngsl-3-16',3,'gold','vàng','noun','[{"en":"She wore a thin chain made of gold.","vi":"Cô ấy đeo một sợi dây chuyền mảnh làm bằng vàng."},{"en":"The price of gold has risen sharply this year.","vi":"Giá vàng đã tăng mạnh trong năm nay."},{"en":"Our team won the gold medal in the relay race.","vi":"Đội chúng tôi đã giành huy chương vàng ở môn chạy tiếp sức."}]','[{"phrase":"made of gold"},{"phrase":"price of gold"},{"phrase":"gold medal"},{"phrase":"solid gold"}]','không đếm được','/ɡəʊld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gol/gold_/gold__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1426,'ngsl-3-16',4,'domestic','trong nước, nội địa; (thuộc) gia đình','adjective','[{"en":"Domestic flights are usually cheaper than international ones.","vi":"Các chuyến bay nội địa thường rẻ hơn các chuyến bay quốc tế."},{"en":"The company sells most of its products in the domestic market.","vi":"Công ty bán phần lớn sản phẩm của mình ở thị trường trong nước."},{"en":"My parents shared domestic tasks like cooking and cleaning.","vi":"Bố mẹ tôi chia nhau làm việc nhà như nấu ăn và dọn dẹp."}]','[{"phrase":"domestic flights"},{"phrase":"domestic market"},{"phrase":"domestic animals"}]',NULL,'/dəˈmestɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domes/domestic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1427,'ngsl-3-16',5,'load','hàng chở; khối lượng (công việc)','noun','[{"en":"The small boat could not carry such a heavy load.","vi":"Chiếc thuyền nhỏ không thể chở hàng nặng như vậy."},{"en":"The workers took turns carrying loads of sand up the hill.","vi":"Các công nhân thay phiên nhau khuân những bao cát lên đồi."},{"en":"She has a heavy teaching load this semester.","vi":"Học kỳ này cô ấy có khối lượng giảng dạy nặng."}]','[{"phrase":"heavy load"},{"phrase":"carry a load"},{"phrase":"teaching load"}]',NULL,'/ləʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loa/load_/load__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1428,'ngsl-3-16',6,'belief','niềm tin; quan niệm','noun','[{"en":"They have a strong belief in the value of education.","vi":"Họ có niềm tin mạnh mẽ vào giá trị của giáo dục."},{"en":"It is a common belief that carrots improve your eyesight.","vi":"Nhiều người vẫn tin rằng cà rốt giúp mắt nhìn tốt hơn."},{"en":"Contrary to popular belief, bats are not blind.","vi":"Trái với quan niệm phổ biến, loài dơi không hề bị mù."}]','[{"phrase":"strong belief"},{"phrase":"belief in"},{"phrase":"common belief"},{"phrase":"popular belief"}]',NULL,'/bɪˈliːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belie/belief__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1429,'ngsl-3-16',7,'troop','quân lính; đoàn, nhóm','noun','[{"en":"The army sent troops to help people after the flood.","vi":"Quân đội đã điều binh lính đến giúp người dân sau trận lụt."},{"en":"Hundreds of troops helped clear the roads after the storm.","vi":"Hàng trăm binh lính đã giúp dọn đường sau cơn bão."},{"en":"A troop of scouts camped by the lake last weekend.","vi":"Một đoàn hướng đạo sinh đã cắm trại bên hồ vào cuối tuần trước."}]','[{"phrase":"send troops"},{"phrase":"a troop of"}]','thường dùng số nhiều: troops (quân lính)','/truːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tro/troop/troop__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1430,'ngsl-3-16',8,'technical','(thuộc) kỹ thuật; chuyên môn','adjective','[{"en":"Please call our support team if you have any technical problems.","vi":"Vui lòng gọi cho đội hỗ trợ nếu bạn gặp bất kỳ sự cố kỹ thuật nào."},{"en":"He studied at a technical college before becoming an engineer.","vi":"Anh ấy học ở một trường cao đẳng kỹ thuật trước khi trở thành kỹ sư."},{"en":"The article was too technical for most readers to understand.","vi":"Bài báo quá nặng chuyên môn nên hầu hết người đọc không hiểu được."}]','[{"phrase":"technical problems"},{"phrase":"technical support"},{"phrase":"technical skills"},{"phrase":"technical terms"}]',NULL,'/ˈteknɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1431,'ngsl-3-16',9,'remind','nhắc nhở; gợi nhớ','verb','[{"en":"Can you remind me to call my mother tonight?","vi":"Bạn nhắc tôi gọi cho mẹ tối nay được không?"},{"en":"The teacher reminded the students that the test was on Friday.","vi":"Cô giáo nhắc học sinh rằng bài kiểm tra vào thứ Sáu."},{"en":"This song always reminds me of our trip to the beach.","vi":"Bài hát này luôn gợi cho tôi nhớ về chuyến đi biển của chúng ta."}]','[{"phrase":"remind someone to"},{"phrase":"remind someone of"},{"phrase":"remind me"}]','remind sb to do sth (nhắc) · remind sb of sth (gợi nhớ)','/rɪˈmaɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remin/remind__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1432,'ngsl-3-16',10,'arrangement','sự sắp xếp; sự chuẩn bị; sự thỏa thuận','noun','[{"en":"She liked the new arrangement of furniture in the living room.","vi":"Cô ấy thích cách sắp xếp đồ đạc mới trong phòng khách."},{"en":"We need to make arrangements for the wedding soon.","vi":"Chúng tôi cần sớm lo chuẩn bị cho đám cưới."},{"en":"They have an arrangement to share the car on weekdays.","vi":"Họ có thỏa thuận dùng chung xe vào các ngày trong tuần."}]','[{"phrase":"make arrangements"},{"phrase":"travel arrangements"},{"phrase":"flower arrangement"}]',NULL,'/əˈreɪndʒmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arran/arrangement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1433,'ngsl-3-16',11,'skin','da; vỏ','noun','[{"en":"This cream helps keep dry skin soft in cold weather.","vi":"Loại kem này giúp da khô luôn mềm mại khi trời lạnh."},{"en":"Wear sunscreen to protect your skin from the sun.","vi":"Hãy bôi kem chống nắng để bảo vệ da khỏi ánh nắng."},{"en":"Peel the skin off the potatoes before you boil them.","vi":"Gọt vỏ khoai tây trước khi luộc."}]','[{"phrase":"dry skin"},{"phrase":"sensitive skin"},{"phrase":"skin care"}]',NULL,'/skɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/skin_/skin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1434,'ngsl-3-16',12,'prison','nhà tù','noun','[{"en":"He spent two years in prison for stealing cars.","vi":"Anh ta đã ngồi tù hai năm vì tội trộm xe hơi."},{"en":"The old prison has been turned into a museum.","vi":"Nhà tù cũ đã được biến thành bảo tàng."},{"en":"The judge sent him to prison for five years.","vi":"Thẩm phán đã kết án anh ta năm năm tù."}]','[{"phrase":"in prison"},{"phrase":"go to prison"},{"phrase":"prison sentence"},{"phrase":"send someone to prison"}]',NULL,'/ˈprɪzn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/priso/prison__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1435,'ngsl-3-16',13,'switch','chuyển, đổi; bật, tắt','verb','[{"en":"I switched to a new phone company because it was cheaper.","vi":"Tôi đã chuyển sang nhà mạng mới vì giá rẻ hơn."},{"en":"Can we switch seats so I can sit by the window?","vi":"Chúng ta đổi chỗ được không để tôi ngồi cạnh cửa sổ?"},{"en":"Please switch off the lights when you leave the room.","vi":"Vui lòng tắt đèn khi rời khỏi phòng."}]','[{"phrase":"switch off"},{"phrase":"switch on"},{"phrase":"switch to"}]','switch on = bật · switch off = tắt','/swɪtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swi/switc/switch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1436,'ngsl-3-16',14,'acquire','có được, tiếp thu; mua lại','verb','[{"en":"Students acquire knowledge best when they enjoy what they learn.","vi":"Học sinh tiếp thu kiến thức tốt nhất khi các em thích điều mình học."},{"en":"Children acquire language quickly by listening to people around them.","vi":"Trẻ em tiếp thu ngôn ngữ nhanh nhờ lắng nghe những người xung quanh."},{"en":"The large company acquired a small software firm last year.","vi":"Năm ngoái, công ty lớn đó đã mua lại một công ty phần mềm nhỏ."}]','[{"phrase":"acquire knowledge"},{"phrase":"acquire skills"},{"phrase":"acquire a company"}]',NULL,'/əˈkwaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acq/acqui/acquire__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1437,'ngsl-3-16',15,'corporate','(thuộc) công ty, doanh nghiệp','adjective','[{"en":"He left the corporate world to open a small café.","vi":"Anh ấy rời bỏ môi trường doanh nghiệp để mở một quán cà phê nhỏ."},{"en":"Our corporate office is located in the city center.","vi":"Trụ sở công ty chúng tôi nằm ở trung tâm thành phố."},{"en":"Many banks offer special accounts for corporate customers.","vi":"Nhiều ngân hàng có tài khoản đặc biệt dành cho khách hàng doanh nghiệp."}]','[{"phrase":"corporate world"},{"phrase":"corporate culture"},{"phrase":"corporate clients"}]',NULL,'/ˈkɔːrpərət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corpo/corporate__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1438,'ngsl-3-16',16,'fairly','khá; một cách công bằng','adverb','[{"en":"The hotel room was fairly small but very clean.","vi":"Phòng khách sạn khá nhỏ nhưng rất sạch sẽ."},{"en":"I speak French fairly well, but my writing is poor.","vi":"Tôi nói tiếng Pháp khá tốt, nhưng viết thì kém."},{"en":"The manager promised to treat all workers fairly.","vi":"Người quản lý hứa sẽ đối xử công bằng với tất cả nhân viên."}]','[{"phrase":"fairly well"},{"phrase":"fairly easy"},{"phrase":"fairly common"},{"phrase":"treat someone fairly"}]',NULL,'/ˈferli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/fairl/fairly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1439,'ngsl-3-16',17,'wood','gỗ; rừng (the woods)','noun','[{"en":"The table is made of solid wood.","vi":"Chiếc bàn được làm bằng gỗ nguyên khối."},{"en":"We collected wood to make a fire at the campsite.","vi":"Chúng tôi nhặt củi để nhóm lửa ở khu cắm trại."},{"en":"They went for a walk in the woods behind their house.","vi":"Họ đi dạo trong khu rừng phía sau nhà."}]','[{"phrase":"made of wood"},{"phrase":"piece of wood"},{"phrase":"in the woods"}]','the woods = khu rừng nhỏ','/wʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/woo/wood_/wood__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1440,'ngsl-3-16',18,'participate','tham gia','verb','[{"en":"All students are expected to participate in class discussions.","vi":"Tất cả học sinh đều được yêu cầu tham gia thảo luận trên lớp."},{"en":"More than fifty companies participated in the job fair.","vi":"Hơn năm mươi công ty đã tham gia hội chợ việc làm."},{"en":"Would you like to participate in our short online survey?","vi":"Bạn có muốn tham gia khảo sát trực tuyến ngắn của chúng tôi không?"}]','[{"phrase":"participate in"},{"phrase":"actively participate"},{"phrase":"participate fully"}]','participate in sth','/pɑːrˈtɪsɪpeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1441,'ngsl-3-16',19,'tough','khó khăn; cứng rắn; dai','adjective','[{"en":"It was a tough decision, but we chose to move abroad.","vi":"Đó là một quyết định khó khăn, nhưng chúng tôi đã chọn ra nước ngoài sống."},{"en":"My boss is tough but always fair to everyone.","vi":"Sếp tôi nghiêm khắc nhưng luôn công bằng với mọi người."},{"en":"The steak was too tough to cut with a normal knife.","vi":"Miếng bít tết dai quá, không cắt được bằng dao thường."}]','[{"phrase":"tough decision"},{"phrase":"tough time"},{"phrase":"tough question"}]',NULL,'/tʌf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/tough/tough__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1442,'ngsl-3-16',20,'tear','nước mắt','noun','[{"en":"Tears ran down her face as she read the letter.","vi":"Nước mắt lăn dài trên má cô ấy khi đọc lá thư."},{"en":"The little boy burst into tears when he dropped his ice cream.","vi":"Cậu bé òa khóc khi làm rơi cây kem."},{"en":"By the end of the movie, we were all in tears.","vi":"Đến cuối phim, tất cả chúng tôi đều rơi nước mắt."}]','[{"phrase":"burst into tears"},{"phrase":"in tears"},{"phrase":"tears of joy"},{"phrase":"hold back tears"}]','tear (n) /tɪə/ nước mắt ≠ tear (v) /teə/ xé','/ter/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/tear_/tear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1443,'ngsl-3-16',21,'representative','người đại diện; đại biểu','noun','[{"en":"Each class chose a representative to attend the school meeting.","vi":"Mỗi lớp chọn một người đại diện để dự cuộc họp của trường."},{"en":"A representative from the bank will call you tomorrow.","vi":"Ngày mai một người đại diện của ngân hàng sẽ gọi cho bạn."},{"en":"She was elected student representative for her university.","vi":"Cô ấy được bầu làm đại diện sinh viên của trường đại học."}]','[{"phrase":"sales representative"},{"phrase":"elected representative"},{"phrase":"representative from"}]',NULL,'/ˌreprɪˈzentətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repre/representative__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1444,'ngsl-3-16',22,'capacity','sức chứa; khả năng, năng lực','noun','[{"en":"The stadium has a capacity of fifty thousand people.","vi":"Sân vận động có sức chứa năm mươi nghìn người."},{"en":"The concert hall was filled to capacity last night.","vi":"Tối qua phòng hòa nhạc chật kín người."},{"en":"Some children have a great capacity for learning languages.","vi":"Một số trẻ có khả năng học ngoại ngữ rất tốt."}]','[{"phrase":"filled to capacity"},{"phrase":"full capacity"},{"phrase":"seating capacity"},{"phrase":"capacity for"}]',NULL,'/kəˈpæsəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capac/capacity__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1445,'ngsl-3-16',23,'border','biên giới; đường viền','noun','[{"en":"You need a passport to cross the border.","vi":"Bạn cần hộ chiếu để qua biên giới."},{"en":"The town is just a few kilometers from the border.","vi":"Thị trấn chỉ cách biên giới vài ki-lô-mét."},{"en":"The white plate has a thin blue border around the edge.","vi":"Chiếc đĩa trắng có một đường viền xanh mảnh quanh mép."}]','[{"phrase":"cross the border"},{"phrase":"border crossing"},{"phrase":"along the border"}]',NULL,'/ˈbɔːrdər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bor/borde/border__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1446,'ngsl-3-16',24,'shake','lắc; rung; bắt tay (shake hands)','verb','[{"en":"Don''t just shake your head; tell me what you think.","vi":"Đừng chỉ lắc đầu, hãy nói cho tôi biết bạn nghĩ gì."},{"en":"The windows shook when the big truck drove past.","vi":"Cửa sổ rung lên khi chiếc xe tải lớn chạy qua."},{"en":"They shook hands and agreed to work together.","vi":"Họ bắt tay và đồng ý hợp tác với nhau."}]','[{"phrase":"shake your head"},{"phrase":"shake hands"},{"phrase":"shake well"}]','shake – shook – shaken','/ʃeɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shake/shake__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1447,'ngsl-3-16',25,'assessment','sự đánh giá','noun','[{"en":"The final assessment will be based on your project and exam.","vi":"Kết quả đánh giá cuối kỳ sẽ dựa trên dự án và bài thi của bạn."},{"en":"Doctors made a careful assessment of her health before surgery.","vi":"Các bác sĩ đã đánh giá kỹ sức khỏe của cô ấy trước ca phẫu thuật."},{"en":"The bank carried out a risk assessment before lending the money.","vi":"Ngân hàng đã tiến hành đánh giá rủi ro trước khi cho vay tiền."}]','[{"phrase":"risk assessment"},{"phrase":"careful assessment"},{"phrase":"carry out an assessment"}]',NULL,'/əˈsesmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asses/assessment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1448,'ngsl-3-16',26,'shoe','giày','noun','[{"en":"I need a new pair of shoes for work.","vi":"Tôi cần một đôi giày mới để đi làm."},{"en":"Please take off your shoes before you enter the house.","vi":"Vui lòng cởi giày trước khi vào nhà."},{"en":"These running shoes are very comfortable for long walks.","vi":"Đôi giày chạy bộ này rất thoải mái khi đi bộ đường dài."}]','[{"phrase":"pair of shoes"},{"phrase":"running shoes"},{"phrase":"take off your shoes"}]',NULL,'/ʃuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shoe_/shoe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1449,'ngsl-3-16',27,'ought','nên; lẽ ra phải','verb','[{"en":"You ought to see a doctor about that cough.","vi":"Bạn nên đi khám bác sĩ về cơn ho đó."},{"en":"We ought to leave now or we will miss the train.","vi":"Chúng ta nên đi ngay bây giờ, không thì sẽ lỡ tàu."},{"en":"They ought to have told us about the change earlier.","vi":"Lẽ ra họ phải báo cho chúng tôi về sự thay đổi sớm hơn."}]','[{"phrase":"ought to"},{"phrase":"ought not to"},{"phrase":"ought to have"}]','luôn đi với to: ought to + V nguyên mẫu','/ˈɔt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1450,'ngsl-3-16',28,'ad','quảng cáo','noun','[{"en":"I saw an ad for a cheap apartment online.","vi":"Tôi thấy trên mạng một quảng cáo về căn hộ giá rẻ."},{"en":"The company spent a lot of money on TV ads.","vi":"Công ty đã chi rất nhiều tiền cho quảng cáo trên truyền hình."},{"en":"She put an ad in the newspaper to sell her old bike.","vi":"Cô ấy đăng quảng cáo trên báo để bán chiếc xe đạp cũ."}]','[{"phrase":"TV ad"},{"phrase":"online ad"},{"phrase":"put an ad in"}]','viết tắt của advertisement','/æd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ad_/ad__u/ad__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1451,'ngsl-3-16',29,'fee','phí, lệ phí','noun','[{"en":"School fees at private schools rise every year.","vi":"Học phí ở các trường tư tăng mỗi năm."},{"en":"There is no entrance fee for children under six.","vi":"Trẻ em dưới sáu tuổi được miễn phí vào cửa."},{"en":"The bank charges a small fee for each transfer.","vi":"Ngân hàng thu một khoản phí nhỏ cho mỗi lần chuyển tiền."}]','[{"phrase":"school fees"},{"phrase":"entrance fee"},{"phrase":"charge a fee"},{"phrase":"membership fee"}]',NULL,'/fiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/fee__/fee__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1452,'ngsl-3-16',30,'hall','hội trường; hành lang','noun','[{"en":"The wedding reception was held in a large hall.","vi":"Tiệc cưới được tổ chức trong một hội trường lớn."},{"en":"The students gathered in the school hall for the meeting.","vi":"Học sinh tập trung ở hội trường của trường để dự buổi họp."},{"en":"Her office is at the end of the hall on the left.","vi":"Văn phòng của cô ấy ở cuối hành lang, bên trái."}]','[{"phrase":"concert hall"},{"phrase":"town hall"},{"phrase":"school hall"},{"phrase":"sports hall"}]',NULL,'/hɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hal/hall_/hall__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1453,'ngsl-3-17',1,'regulation','quy định; điều lệ','noun','[{"en":"Safety regulations require all workers to wear helmets on site.","vi":"Các quy định an toàn yêu cầu mọi công nhân phải đội mũ bảo hộ tại công trường."},{"en":"The company broke several regulations and had to pay a fine.","vi":"Công ty đã vi phạm một số quy định và phải nộp phạt."},{"en":"New regulations on smoking in public places start next month.","vi":"Các quy định mới về hút thuốc ở nơi công cộng sẽ bắt đầu áp dụng từ tháng sau."}]','[{"phrase":"safety regulations"},{"phrase":"new regulations"},{"phrase":"follow regulations"},{"phrase":"strict regulations"}]',NULL,'/ˌreɡjuˈleɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regulation__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1454,'ngsl-3-17',2,'escape','thoát khỏi; trốn thoát','verb','[{"en":"The bird escaped from its cage when I opened the door.","vi":"Con chim đã thoát khỏi lồng khi tôi mở cửa."},{"en":"Two prisoners escaped from the prison last night.","vi":"Hai tù nhân đã trốn khỏi nhà tù tối qua."},{"en":"We went to the countryside to escape the noise of the city.","vi":"Chúng tôi về vùng quê để thoát khỏi sự ồn ào của thành phố."}]','[{"phrase":"escape from prison"},{"phrase":"try to escape"},{"phrase":"narrowly escape"}]',NULL,'/ɪˈskeɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/esc/escap/escape__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1455,'ngsl-3-17',3,'studio','phòng thu; xưởng vẽ; căn hộ một phòng','noun','[{"en":"The band spent three months recording the album in a studio.","vi":"Ban nhạc đã dành ba tháng thu âm album trong phòng thu."},{"en":"My aunt paints in a small studio behind her house.","vi":"Dì tôi vẽ tranh trong một xưởng vẽ nhỏ phía sau nhà."},{"en":"He rents a studio apartment near the university.","vi":"Anh ấy thuê một căn hộ một phòng gần trường đại học."}]','[{"phrase":"recording studio"},{"phrase":"television studio"},{"phrase":"studio apartment"}]',NULL,'/ˈstuːdiəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/studi/studio__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1456,'ngsl-3-17',4,'proper','đúng; thích hợp; tử tế, ra hồn','adjective','[{"en":"Please put the books back in their proper place.","vi":"Vui lòng để sách lại đúng chỗ của chúng."},{"en":"You need proper shoes for walking in the mountains.","vi":"Bạn cần giày thích hợp để đi bộ trên núi."},{"en":"I haven''t had a proper meal all day.","vi":"Cả ngày nay tôi chưa được ăn một bữa ra hồn."}]','[{"phrase":"proper place"},{"phrase":"proper training"},{"phrase":"proper meal"},{"phrase":"the proper way"}]',NULL,'/ˈprɑːpər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prope/proper__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1457,'ngsl-3-17',5,'relax','thư giãn; thả lỏng','verb','[{"en":"I like to relax with a good book after work.","vi":"Tôi thích thư giãn với một cuốn sách hay sau giờ làm."},{"en":"Just relax and take a deep breath before you start.","vi":"Cứ thả lỏng và hít một hơi thật sâu trước khi bắt đầu."},{"en":"We relaxed on the beach for the whole afternoon.","vi":"Chúng tôi thư giãn trên bãi biển suốt cả buổi chiều."}]','[{"phrase":"try to relax"},{"phrase":"relax at home"},{"phrase":"relax your muscles"}]',NULL,'/rɪˈlæks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relax/relax__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1458,'ngsl-3-17',6,'tourist','khách du lịch, du khách','noun','[{"en":"The old town is full of tourists in the summer.","vi":"Vào mùa hè, phố cổ đông nghịt khách du lịch."},{"en":"A tourist asked me for directions to the train station.","vi":"Một du khách hỏi tôi đường đến ga tàu."},{"en":"The waterfall has become a popular tourist attraction.","vi":"Thác nước đã trở thành một điểm du lịch được nhiều người yêu thích."}]','[{"phrase":"tourist attraction"},{"phrase":"foreign tourists"},{"phrase":"tourist information"}]',NULL,'/ˈtʊrɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/touri/tourist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1459,'ngsl-3-17',7,'component','thành phần; linh kiện, bộ phận','noun','[{"en":"The factory makes components for cars and trucks.","vi":"Nhà máy sản xuất linh kiện cho ô tô và xe tải."},{"en":"Trust is an important component of any relationship.","vi":"Sự tin tưởng là một thành phần quan trọng của mọi mối quan hệ."},{"en":"One broken component can stop the whole machine from working.","vi":"Chỉ một bộ phận bị hỏng cũng có thể khiến cả cỗ máy ngừng hoạt động."}]','[{"phrase":"key component"},{"phrase":"important component"},{"phrase":"electronic components"}]',NULL,'/kəmˈpəʊnənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/component__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1460,'ngsl-3-17',8,'afford','có đủ tiền (mua, trả); đủ sức (làm gì)','verb','[{"en":"We can''t afford a new car this year.","vi":"Năm nay chúng tôi không có đủ tiền mua xe mới."},{"en":"She couldn''t afford to lose her job right now.","vi":"Lúc này cô ấy không thể để mất việc được."},{"en":"Many young people can hardly afford the rent in big cities.","vi":"Nhiều người trẻ khó mà trả nổi tiền thuê nhà ở các thành phố lớn."}]','[{"phrase":"can''t afford"},{"phrase":"afford to pay"},{"phrase":"afford to lose"}]','thường đi với can/could: can’t afford (to do) sth','/əˈfɔːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affor/afford__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1461,'ngsl-3-17',9,'lawyer','luật sư','noun','[{"en":"You should talk to a lawyer before signing the contract.","vi":"Bạn nên nói chuyện với luật sư trước khi ký hợp đồng."},{"en":"Her father has worked as a lawyer for twenty years.","vi":"Bố cô ấy đã làm luật sư được hai mươi năm."},{"en":"My lawyer said we had a good chance of winning.","vi":"Luật sư của tôi nói chúng tôi có nhiều khả năng thắng."}]','[{"phrase":"hire a lawyer"},{"phrase":"consult a lawyer"},{"phrase":"defense lawyer"}]',NULL,'/ˈlɔɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/law/lawye/lawyer__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1462,'ngsl-3-17',10,'suspect','nghi ngờ; ngờ rằng','verb','[{"en":"I suspect he forgot about our meeting again.","vi":"Tôi ngờ là anh ấy lại quên cuộc họp của chúng ta rồi."},{"en":"Police suspect that the fire was started on purpose.","vi":"Cảnh sát nghi ngờ vụ cháy là do có người cố ý gây ra."},{"en":"Nobody suspected the quiet neighbor of stealing the money.","vi":"Không ai nghi ngờ người hàng xóm ít nói đã lấy trộm tiền."}]','[{"phrase":"strongly suspect"},{"phrase":"suspect somebody of something"}]','suspect sb of sth: nghi ai làm gì · (n) suspect: nghi phạm','/səˈspekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/suspe/suspect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1463,'ngsl-3-17',11,'cup','tách, cốc; cúp (giải thưởng)','noun','[{"en":"Would you like a cup of tea before we start?","vi":"Bạn có muốn uống một tách trà trước khi chúng ta bắt đầu không?"},{"en":"She drinks two cups of coffee every morning.","vi":"Sáng nào cô ấy cũng uống hai tách cà phê."},{"en":"Our school team won the cup for the first time.","vi":"Đội của trường chúng tôi lần đầu tiên giành được cúp."}]','[{"phrase":"cup of tea"},{"phrase":"cup of coffee"},{"phrase":"paper cup"},{"phrase":"win the cup"}]',NULL,'/kʌp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cup/cup__/cup__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1464,'ngsl-3-17',12,'description','sự mô tả; bản mô tả','noun','[{"en":"Can you give me a description of the man you saw?","vi":"Bạn có thể mô tả cho tôi người đàn ông mà bạn đã thấy không?"},{"en":"The job description says you need two years of experience.","vi":"Bản mô tả công việc ghi rằng bạn cần có hai năm kinh nghiệm."},{"en":"The hotel looked exactly like the description on the website.","vi":"Khách sạn trông đúng y như phần mô tả trên trang web."}]','[{"phrase":"give a description"},{"phrase":"job description"},{"phrase":"detailed description"},{"phrase":"brief description"}]',NULL,'/dɪˈskrɪpʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/descr/description__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1465,'ngsl-3-17',13,'confidence','sự tự tin; sự tin tưởng','noun','[{"en":"Speaking in front of the class helped her build confidence.","vi":"Việc phát biểu trước lớp đã giúp cô ấy rèn luyện sự tự tin."},{"en":"He answered every question in the interview with confidence.","vi":"Anh ấy tự tin trả lời mọi câu hỏi trong buổi phỏng vấn."},{"en":"I have complete confidence in my team.","vi":"Tôi hoàn toàn tin tưởng vào đội của mình."}]','[{"phrase":"build confidence"},{"phrase":"lack of confidence"},{"phrase":"have confidence in"},{"phrase":"lose confidence"}]','confidence in sb/sth: tin tưởng vào ai/cái gì','/ˈkɑːnfɪdəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfidence__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1466,'ngsl-3-17',14,'industrial','(thuộc) công nghiệp','adjective','[{"en":"There is a large industrial area just outside the town.","vi":"Có một khu công nghiệp lớn ngay bên ngoài thị trấn."},{"en":"Industrial waste has polluted the river for many years.","vi":"Chất thải công nghiệp đã làm ô nhiễm dòng sông trong nhiều năm."},{"en":"They turned an old industrial building into a coffee shop.","vi":"Họ đã biến một nhà xưởng cũ thành quán cà phê."}]','[{"phrase":"industrial area"},{"phrase":"industrial waste"},{"phrase":"industrial production"}]',NULL,'/ɪnˈdʌstriəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indus/industrial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1467,'ngsl-3-17',15,'complain','phàn nàn, than phiền; khiếu nại','verb','[{"en":"My neighbors complained about the noise from our party.","vi":"Hàng xóm đã phàn nàn về tiếng ồn từ bữa tiệc của chúng tôi."},{"en":"He''s always complaining that he has too much work.","vi":"Anh ấy lúc nào cũng than phiền rằng mình có quá nhiều việc."},{"en":"If the food is cold, you should complain to the manager.","vi":"Nếu đồ ăn bị nguội, bạn nên khiếu nại với quản lý."}]','[{"phrase":"complain about"},{"phrase":"complain to somebody"},{"phrase":"constantly complain"}]','complain about sth / to sb','/kəmˈpleɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complain__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1468,'ngsl-3-17',16,'perspective','góc nhìn; quan điểm','noun','[{"en":"Living abroad gave me a new perspective on my own culture.","vi":"Sống ở nước ngoài đã cho tôi một góc nhìn mới về văn hóa của chính mình."},{"en":"Try to see the problem from your customer''s perspective.","vi":"Hãy thử nhìn vấn đề từ góc nhìn của khách hàng."},{"en":"Talking to friends helped me put my worries into perspective.","vi":"Nói chuyện với bạn bè giúp tôi nhìn nhận những lo lắng của mình một cách đúng mức hơn."}]','[{"phrase":"new perspective"},{"phrase":"from a different perspective"},{"phrase":"put things into perspective"}]',NULL,'/pərˈspektɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persp/perspective__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1469,'ngsl-3-17',17,'error','lỗi; sai sót','noun','[{"en":"There are a few spelling errors in your report.","vi":"Có vài lỗi chính tả trong bản báo cáo của bạn."},{"en":"The accident was caused by human error.","vi":"Vụ tai nạn là do lỗi của con người."},{"en":"I made an error when I added up the bill.","vi":"Tôi đã mắc sai sót khi cộng tiền hóa đơn."}]','[{"phrase":"make an error"},{"phrase":"human error"},{"phrase":"spelling error"},{"phrase":"error message"}]',NULL,'/ˈerər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/err/error/error__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1470,'ngsl-3-17',18,'arrest','bắt giữ','verb','[{"en":"Police arrested two men outside the bank last night.","vi":"Tối qua cảnh sát đã bắt giữ hai người đàn ông bên ngoài ngân hàng."},{"en":"He was arrested for driving without a license.","vi":"Anh ta bị bắt vì lái xe không có bằng."},{"en":"The thief was arrested a few hours after the robbery.","vi":"Tên trộm đã bị bắt vài giờ sau vụ cướp."}]','[{"phrase":"arrest a suspect"},{"phrase":"be arrested for"},{"phrase":"under arrest"}]','arrest sb for sth · (n) under arrest: bị bắt giữ','/əˈrest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arres/arrest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1471,'ngsl-3-17',19,'assess','đánh giá','verb','[{"en":"Teachers assess students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ."},{"en":"Doctors need to assess how serious the injury is.","vi":"Các bác sĩ cần đánh giá mức độ nghiêm trọng của vết thương."},{"en":"It''s hard to assess the damage until the water goes down.","vi":"Khó mà đánh giá được thiệt hại cho đến khi nước rút."}]','[{"phrase":"assess the damage"},{"phrase":"assess the situation"},{"phrase":"carefully assess"}]',NULL,'/əˈses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asses/assess__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1472,'ngsl-3-17',20,'register','đăng ký','verb','[{"en":"You need to register online before the course begins.","vi":"Bạn cần đăng ký trực tuyến trước khi khóa học bắt đầu."},{"en":"Have you registered your new car yet?","vi":"Bạn đã đăng ký chiếc xe mới của mình chưa?"},{"en":"More than two hundred people registered for the conference.","vi":"Hơn hai trăm người đã đăng ký tham dự hội nghị."}]','[{"phrase":"register for a course"},{"phrase":"register online"},{"phrase":"register a birth"}]',NULL,'/ˈredʒɪstər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regis/register__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1473,'ngsl-4-01',1,'asset','tài sản; lợi thế, người/vật có giá trị','noun','[{"en":"The company sold some of its assets to pay its debts.","vi":"Công ty đã bán một số tài sản để trả nợ."},{"en":"Their house is the most valuable asset they own.","vi":"Ngôi nhà là tài sản có giá trị nhất mà họ sở hữu."},{"en":"Her friendly personality is a real asset in this job.","vi":"Tính cách thân thiện của cô ấy là một lợi thế thực sự trong công việc này."}]','[{"phrase":"valuable asset"},{"phrase":"financial assets"},{"phrase":"a great asset"},{"phrase":"an asset to the team"}]',NULL,'/ˈæset/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asset/asset__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1474,'ngsl-4-01',2,'signal','tín hiệu; dấu hiệu','noun','[{"en":"I can''t call you because there''s no signal here.","vi":"Tôi không gọi cho bạn được vì ở đây không có sóng."},{"en":"The teacher gave us a signal to start writing.","vi":"Cô giáo ra hiệu cho chúng tôi bắt đầu viết."},{"en":"Feeling tired all the time can be a warning signal.","vi":"Lúc nào cũng thấy mệt có thể là một dấu hiệu cảnh báo."}]','[{"phrase":"give a signal"},{"phrase":"warning signal"},{"phrase":"phone signal"},{"phrase":"send a signal"}]',NULL,'/ˈsɪɡnəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signa/signal__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1475,'ngsl-4-01',3,'finger','ngón tay','noun','[{"en":"She cut her finger while she was chopping vegetables.","vi":"Cô ấy bị đứt tay khi đang thái rau."},{"en":"He wears a silver ring on his little finger.","vi":"Anh ấy đeo một chiếc nhẫn bạc ở ngón út."},{"en":"Please don''t point your finger at people in public.","vi":"Xin đừng chỉ tay vào người khác ở nơi công cộng."}]','[{"phrase":"little finger"},{"phrase":"point a finger"},{"phrase":"cross your fingers"},{"phrase":"cut your finger"}]','ngón cái thường gọi là thumb; ngón chân là toe','/ˈfɪŋɡər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finge/finger__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1476,'ngsl-4-01',4,'relevant','liên quan; thích hợp','adjective','[{"en":"Please only include information that is relevant to the question.","vi":"Vui lòng chỉ đưa vào những thông tin liên quan đến câu hỏi."},{"en":"Do you have any relevant experience for this job?","vi":"Bạn có kinh nghiệm nào phù hợp với công việc này không?"},{"en":"His advice is still relevant to young people today.","vi":"Lời khuyên của ông ấy vẫn còn phù hợp với giới trẻ ngày nay."}]','[{"phrase":"relevant information"},{"phrase":"relevant experience"},{"phrase":"relevant to"}]','relevant to sth; trái nghĩa: irrelevant','/ˈreləvənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relev/relevant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1477,'ngsl-4-01',5,'explore','khám phá, thám hiểm; tìm hiểu, xem xét','verb','[{"en":"We spent the afternoon exploring the old part of the city.","vi":"Chúng tôi dành cả buổi chiều khám phá khu phố cổ của thành phố."},{"en":"Children love to explore the world around them.","vi":"Trẻ em thích khám phá thế giới xung quanh."},{"en":"The team is exploring new ways to save money.","vi":"Nhóm đang tìm hiểu những cách mới để tiết kiệm tiền."}]','[{"phrase":"explore the area"},{"phrase":"explore ways"},{"phrase":"explore the possibility"},{"phrase":"explore options"}]',NULL,'/ɪkˈsplɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/explo/explore__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1478,'ngsl-4-01',6,'leadership','sự lãnh đạo; khả năng lãnh đạo','noun','[{"en":"Under her leadership, the company grew very quickly.","vi":"Dưới sự lãnh đạo của bà ấy, công ty phát triển rất nhanh."},{"en":"He showed strong leadership during the difficult months.","vi":"Anh ấy đã thể hiện khả năng lãnh đạo mạnh mẽ trong những tháng khó khăn."},{"en":"Our school offers a leadership course for older students.","vi":"Trường chúng tôi có một khóa học kỹ năng lãnh đạo cho học sinh lớn."}]','[{"phrase":"strong leadership"},{"phrase":"leadership skills"},{"phrase":"under the leadership of"},{"phrase":"show leadership"}]',NULL,'/ˈliːdərʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leade/leadership__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1479,'ngsl-4-01',7,'commitment','sự cam kết, tận tâm; nghĩa vụ, việc phải làm','noun','[{"en":"Learning a language takes time and real commitment.","vi":"Học một ngôn ngữ cần thời gian và sự quyết tâm thực sự."},{"en":"The company made a commitment to reduce its waste.","vi":"Công ty đã cam kết giảm lượng rác thải của mình."},{"en":"I can''t join you tonight because of family commitments.","vi":"Tối nay tôi không đi cùng bạn được vì có việc gia đình."}]','[{"phrase":"make a commitment"},{"phrase":"strong commitment"},{"phrase":"commitment to"},{"phrase":"family commitments"}]','commitment to sth / to doing sth','/kəˈmɪtmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commitment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1480,'ngsl-4-01',8,'wake','thức dậy; đánh thức','verb','[{"en":"I usually wake up at six o''clock on weekdays.","vi":"Ngày thường tôi hay thức dậy lúc sáu giờ."},{"en":"Please be quiet or you''ll wake the baby.","vi":"Làm ơn giữ yên lặng, không thì bạn sẽ đánh thức em bé đấy."},{"en":"She woke early and went for a walk by the river.","vi":"Cô ấy dậy sớm và đi dạo bên bờ sông."}]','[{"phrase":"wake up"},{"phrase":"wake up early"},{"phrase":"wake the baby"}]','wake – woke – woken','/weɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wak/wake_/wake__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1481,'ngsl-4-01',9,'necessarily','nhất thiết, tất yếu','adverb','[{"en":"Expensive food is not necessarily better than cheap food.","vi":"Đồ ăn đắt tiền chưa chắc đã ngon hơn đồ ăn rẻ."},{"en":"You don''t necessarily need a car to live here.","vi":"Sống ở đây bạn không nhất thiết phải có ô tô."},{"en":"A good student doesn''t necessarily become a good teacher.","vi":"Một học sinh giỏi không nhất thiết sẽ trở thành một giáo viên giỏi."}]','[{"phrase":"not necessarily"},{"phrase":"doesn''t necessarily mean"}]','thường dùng với phủ định: not necessarily = chưa chắc, không hẳn','/ˌnesəˈserəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nec/neces/necessarily__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1482,'ngsl-4-01',10,'bright','sáng, chói; tươi (màu); thông minh','adjective','[{"en":"The sun was so bright that I had to close my eyes.","vi":"Mặt trời chói đến mức tôi phải nhắm mắt lại."},{"en":"She painted her bedroom a bright yellow color.","vi":"Cô ấy sơn phòng ngủ màu vàng tươi."},{"en":"He''s a bright student who learns things very quickly.","vi":"Cậu ấy là một học sinh thông minh, học gì cũng rất nhanh."}]','[{"phrase":"bright light"},{"phrase":"bright colors"},{"phrase":"bright student"},{"phrase":"bright future"}]',NULL,'/braɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brigh/bright_1_us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1483,'ngsl-4-01',11,'frame','khung; gọng (kính)','noun','[{"en":"I bought a wooden frame for our wedding photo.","vi":"Tôi đã mua một chiếc khung gỗ cho tấm ảnh cưới của chúng tôi."},{"en":"The window frame is old and needs to be painted.","vi":"Khung cửa sổ đã cũ và cần được sơn lại."},{"en":"He chose glasses with thin black frames.","vi":"Anh ấy chọn một cặp kính gọng đen mảnh."}]','[{"phrase":"picture frame"},{"phrase":"window frame"},{"phrase":"door frame"},{"phrase":"metal frame"}]',NULL,'/freɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/frame/frame__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1484,'ngsl-4-01',12,'slowly','chậm, chậm rãi; dần dần','adverb','[{"en":"Could you speak more slowly, please? I don''t understand.","vi":"Bạn nói chậm hơn được không? Tôi không hiểu."},{"en":"The old man walked slowly down the street.","vi":"Ông cụ chậm rãi đi xuống phố."},{"en":"My English is slowly getting better every month.","vi":"Tiếng Anh của tôi đang dần dần khá lên mỗi tháng."}]','[{"phrase":"walk slowly"},{"phrase":"speak slowly"},{"phrase":"move slowly"},{"phrase":"slowly but surely"}]',NULL,'/ˈsləʊli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/slo/slowl/slowly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1485,'ngsl-4-01',13,'bond','mối quan hệ gắn bó; trái phiếu','noun','[{"en":"There is a strong bond between the two sisters.","vi":"Hai chị em có mối gắn bó rất bền chặt."},{"en":"Playing sports together helped build a bond within the team.","vi":"Cùng chơi thể thao đã giúp gắn kết cả đội."},{"en":"Some people prefer to invest their savings in government bonds.","vi":"Một số người thích đầu tư tiền tiết kiệm vào trái phiếu chính phủ."}]','[{"phrase":"strong bond"},{"phrase":"close bond"},{"phrase":"bond between"},{"phrase":"government bonds"}]',NULL,'/bɑːnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bon/bond_/bond__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1486,'ngsl-4-01',14,'hire','thuê, tuyển (người)','verb','[{"en":"The restaurant is hiring new staff for the summer.","vi":"Nhà hàng đang tuyển thêm nhân viên cho mùa hè."},{"en":"We hired a guide to show us around the mountains.","vi":"Chúng tôi thuê một hướng dẫn viên dẫn đi tham quan vùng núi."},{"en":"They hired a lawyer to help them buy the house.","vi":"Họ thuê một luật sư để giúp họ mua căn nhà."}]','[{"phrase":"hire staff"},{"phrase":"hire a lawyer"},{"phrase":"hire new employees"}]','Anh: hire a car · Mỹ: rent a car','/ˈhaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hir/hire_/hire__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1487,'ngsl-4-01',15,'hole','lỗ, hố','noun','[{"en":"There''s a big hole in my sock.","vi":"Chiếc tất của tôi bị thủng một lỗ to."},{"en":"The dog dug a hole in the garden to hide its bone.","vi":"Con chó đào một cái hố trong vườn để giấu khúc xương."},{"en":"Be careful, there are lots of holes in this road.","vi":"Cẩn thận nhé, con đường này có nhiều ổ gà lắm."}]','[{"phrase":"dig a hole"},{"phrase":"a hole in"},{"phrase":"big hole"},{"phrase":"small hole"}]',NULL,'/həʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/hole_/hole__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1488,'ngsl-4-01',16,'tie','buộc, thắt; hòa (trận đấu)','verb','[{"en":"Can you help me tie my shoes, Dad?","vi":"Bố giúp con buộc dây giày được không ạ?"},{"en":"She tied her hair back before she started cooking.","vi":"Cô ấy buộc tóc ra sau trước khi bắt đầu nấu ăn."},{"en":"Our team tied with the other school in yesterday''s game.","vi":"Đội chúng tôi hòa với trường kia trong trận đấu hôm qua."}]','[{"phrase":"tie a knot"},{"phrase":"tie your shoes"},{"phrase":"tie up"},{"phrase":"tie back your hair"}]','tie – tied – tied; tying','/taɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tie/tie__/tie__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1489,'ngsl-4-01',17,'internal','bên trong, nội bộ','adjective','[{"en":"The company is holding an internal meeting this afternoon.","vi":"Chiều nay công ty tổ chức một cuộc họp nội bộ."},{"en":"After the accident, doctors checked him for internal injuries.","vi":"Sau tai nạn, các bác sĩ kiểm tra xem anh ấy có bị chấn thương bên trong không."},{"en":"This report is for internal use only.","vi":"Báo cáo này chỉ dùng trong nội bộ."}]','[{"phrase":"internal meeting"},{"phrase":"internal injuries"},{"phrase":"internal affairs"},{"phrase":"for internal use"}]','trái nghĩa: external','/ɪnˈtɜːrnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/internal__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1490,'ngsl-4-01',18,'chain','dây xích, dây chuyền; chuỗi (cửa hàng)','noun','[{"en":"She wore a gold chain around her neck.","vi":"Cô ấy đeo một sợi dây chuyền vàng quanh cổ."},{"en":"I need to fix the chain on my bike.","vi":"Tôi cần sửa lại sợi xích xe đạp."},{"en":"He works for a large chain of hotels in Asia.","vi":"Anh ấy làm việc cho một chuỗi khách sạn lớn ở châu Á."}]','[{"phrase":"gold chain"},{"phrase":"bike chain"},{"phrase":"chain of stores"},{"phrase":"hotel chain"}]',NULL,'/tʃeɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chain/chain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1491,'ngsl-4-01',19,'literature','văn học; tài liệu (về một chủ đề)','noun','[{"en":"She decided to study English literature at university.","vi":"Cô ấy quyết định học văn học Anh ở trường đại học."},{"en":"Reading classic literature can improve your vocabulary a lot.","vi":"Đọc văn học kinh điển có thể giúp bạn cải thiện vốn từ rất nhiều."},{"en":"The doctor gave me some literature about healthy eating.","vi":"Bác sĩ đưa cho tôi vài tài liệu về chế độ ăn uống lành mạnh."}]','[{"phrase":"English literature"},{"phrase":"classic literature"},{"phrase":"modern literature"},{"phrase":"study literature"}]','không đếm được','/ˈlɪtrətʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/liter/literature__us_7.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1492,'ngsl-4-01',20,'victim','nạn nhân','noun','[{"en":"The victims of the flood received food and clean water.","vi":"Các nạn nhân của trận lũ đã được nhận thức ăn và nước sạch."},{"en":"He was the victim of an online scam last year.","vi":"Năm ngoái anh ấy là nạn nhân của một vụ lừa đảo trên mạng."},{"en":"Don''t let yourself become a victim of bad habits.","vi":"Đừng để bản thân trở thành nạn nhân của những thói quen xấu."}]','[{"phrase":"victim of"},{"phrase":"become a victim"},{"phrase":"fall victim to"},{"phrase":"flood victims"}]',NULL,'/ˈvɪktɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vic/victi/victim__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1493,'ngsl-4-01',21,'threaten','đe dọa; có nguy cơ','verb','[{"en":"The boss threatened to fire him if he was late again.","vi":"Sếp dọa sẽ đuổi việc anh ta nếu còn đi muộn lần nữa."},{"en":"Pollution threatens the health of people living near the factory.","vi":"Ô nhiễm đe dọa sức khỏe của người dân sống gần nhà máy."},{"en":"The heavy rain threatened to ruin our weekend plans.","vi":"Cơn mưa lớn có nguy cơ phá hỏng kế hoạch cuối tuần của chúng tôi."}]','[{"phrase":"threaten to"},{"phrase":"threaten someone"},{"phrase":"threaten the future"}]','threaten to do sth','/ˈθretn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/threa/threaten__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1494,'ngsl-4-01',22,'division','sự phân chia; phòng, ban, bộ phận; phép chia','noun','[{"en":"She works in the sales division of a large company.","vi":"Cô ấy làm việc ở bộ phận kinh doanh của một công ty lớn."},{"en":"There was an unfair division of work in our group.","vi":"Việc phân chia công việc trong nhóm chúng tôi không công bằng."},{"en":"My son is learning multiplication and division at school.","vi":"Con trai tôi đang học phép nhân và phép chia ở trường."}]','[{"phrase":"sales division"},{"phrase":"division of labor"},{"phrase":"division between"},{"phrase":"multiplication and division"}]',NULL,'/dɪˈvɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/divis/division__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1495,'ngsl-4-01',23,'secure','an toàn; chắc chắn, ổn định','adjective','[{"en":"Keep your passport in a secure place when you travel.","vi":"Hãy cất hộ chiếu ở nơi an toàn khi đi du lịch."},{"en":"Children need to feel safe and secure at home.","vi":"Trẻ em cần cảm thấy an toàn và yên tâm khi ở nhà."},{"en":"He left his secure job to start his own business.","vi":"Anh ấy bỏ công việc ổn định để tự mở công ty riêng."}]','[{"phrase":"secure place"},{"phrase":"secure job"},{"phrase":"feel secure"},{"phrase":"secure password"}]',NULL,'/sɪˈkjʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secur/secure__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1496,'ngsl-4-01',24,'amaze','làm kinh ngạc, làm sửng sốt','verb','[{"en":"It amazes me how fast children learn new languages.","vi":"Tôi thấy kinh ngạc khi trẻ em học ngôn ngữ mới nhanh đến vậy."},{"en":"The view from the top of the mountain amazed us.","vi":"Quang cảnh từ trên đỉnh núi khiến chúng tôi sửng sốt."},{"en":"Her piano playing never fails to amaze her teachers.","vi":"Tiếng đàn piano của cô ấy lúc nào cũng khiến các thầy cô kinh ngạc."}]','[{"phrase":"never fails to amaze"},{"phrase":"be amazed at"},{"phrase":"be amazed by"},{"phrase":"amaze everyone"}]','amazed (cảm thấy kinh ngạc) ≠ amazing (tuyệt vời, đáng kinh ngạc)','/əˈmeɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ama/amaze/amaze__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1497,'ngsl-4-01',25,'device','thiết bị, dụng cụ','noun','[{"en":"Please turn off all electronic devices during the flight.","vi":"Vui lòng tắt tất cả thiết bị điện tử trong suốt chuyến bay."},{"en":"You can watch the course videos on any device.","vi":"Bạn có thể xem video bài học trên bất kỳ thiết bị nào."},{"en":"This small device measures how many steps you take.","vi":"Thiết bị nhỏ này đo số bước chân bạn đi."}]','[{"phrase":"electronic device"},{"phrase":"mobile device"},{"phrase":"safety device"}]','device (n) ≠ devise (v: nghĩ ra)','/dɪˈvaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devic/device__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1498,'ngsl-4-01',26,'birth','sự ra đời, sự sinh đẻ','noun','[{"en":"Please write your name and date of birth on the form.","vi":"Vui lòng ghi họ tên và ngày sinh vào mẫu đơn."},{"en":"My sister gave birth to a healthy baby boy last night.","vi":"Tối qua chị tôi đã sinh một bé trai khỏe mạnh."},{"en":"They moved to the city soon after the birth of their daughter.","vi":"Họ chuyển lên thành phố ngay sau khi con gái chào đời."}]','[{"phrase":"give birth to"},{"phrase":"date of birth"},{"phrase":"place of birth"},{"phrase":"birth of a baby"}]',NULL,'/bɜːrθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bir/birth/birth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1499,'ngsl-4-01',27,'forest','rừng','noun','[{"en":"We got lost while walking through the forest.","vi":"Chúng tôi bị lạc khi đi bộ xuyên qua khu rừng."},{"en":"Many animals lose their homes when forests are cut down.","vi":"Nhiều loài động vật mất nơi sống khi rừng bị chặt phá."},{"en":"There is a small forest behind my grandparents'' village.","vi":"Có một khu rừng nhỏ phía sau làng của ông bà tôi."}]','[{"phrase":"tropical forest"},{"phrase":"dense forest"},{"phrase":"forest fire"},{"phrase":"in the forest"}]',NULL,'/ˈfɔːrɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/fores/forest__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1500,'ngsl-4-01',28,'label','nhãn, nhãn mác','noun','[{"en":"Always read the label before you take any medicine.","vi":"Hãy luôn đọc nhãn trước khi uống bất kỳ loại thuốc nào."},{"en":"I put a label with my name on my lunch box.","vi":"Tôi dán một cái nhãn ghi tên mình lên hộp cơm."},{"en":"The label says this shirt should be washed in cold water.","vi":"Nhãn ghi chiếc áo này nên được giặt bằng nước lạnh."}]','[{"phrase":"read the label"},{"phrase":"price label"},{"phrase":"food label"},{"phrase":"put a label on"}]',NULL,'/ˈleɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/label/label__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1501,'ngsl-4-01',29,'root','rễ (cây); gốc rễ, nguồn gốc','noun','[{"en":"The roots of this old tree go deep into the ground.","vi":"Rễ của cây cổ thụ này ăn sâu xuống lòng đất."},{"en":"We need to find the root of the problem first.","vi":"Trước tiên chúng ta cần tìm ra gốc rễ của vấn đề."},{"en":"Although he lives abroad, he has never forgotten his roots.","vi":"Dù sống ở nước ngoài, anh ấy chưa bao giờ quên cội nguồn của mình."}]','[{"phrase":"root of the problem"},{"phrase":"tree roots"},{"phrase":"the root cause"},{"phrase":"take root"}]',NULL,'/ruːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roo/root_/root__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1502,'ngsl-4-01',30,'factory','nhà máy, xí nghiệp','noun','[{"en":"My father has worked in a car factory for twenty years.","vi":"Bố tôi đã làm việc ở một nhà máy ô tô được hai mươi năm."},{"en":"The new factory will create hundreds of jobs for local people.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm cho người dân địa phương."},{"en":"Most of these shoes are made in factories overseas.","vi":"Phần lớn những đôi giày này được sản xuất tại các nhà máy ở nước ngoài."}]','[{"phrase":"factory worker"},{"phrase":"car factory"},{"phrase":"work in a factory"},{"phrase":"build a factory"}]',NULL,'/ˈfæktri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facto/factory__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1503,'ngsl-4-02',1,'expense','chi phí; phí tổn','noun','[{"en":"Rent is our biggest expense every month.","vi":"Tiền thuê nhà là khoản chi phí lớn nhất của chúng tôi mỗi tháng."},{"en":"The company will cover all your travel expenses.","vi":"Công ty sẽ chi trả toàn bộ chi phí đi lại của bạn."},{"en":"We had to cut our living expenses after I lost my job.","vi":"Chúng tôi phải cắt giảm chi phí sinh hoạt sau khi tôi mất việc."}]','[{"phrase":"travel expenses"},{"phrase":"living expenses"},{"phrase":"cover the expense"},{"phrase":"at the expense of"}]',NULL,'/ɪkˈspens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expen/expense__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1504,'ngsl-4-02',2,'channel','kênh (truyền hình); kênh (liên lạc, phân phối)','noun','[{"en":"What channel is the football game on tonight?","vi":"Tối nay trận bóng đá chiếu trên kênh nào?"},{"en":"My dad keeps changing the channel during the ads.","vi":"Bố tôi cứ chuyển kênh mỗi khi có quảng cáo."},{"en":"Customers can contact us through several channels, including email and online chat.","vi":"Khách hàng có thể liên hệ với chúng tôi qua nhiều kênh, trong đó có email và trò chuyện trực tuyến."}]','[{"phrase":"change the channel"},{"phrase":"TV channel"},{"phrase":"news channel"},{"phrase":"communication channels"}]',NULL,'/ˈtʃænl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chann/channel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1505,'ngsl-4-02',3,'investigate','điều tra; nghiên cứu, tìm hiểu','verb','[{"en":"The police are investigating the cause of the fire.","vi":"Cảnh sát đang điều tra nguyên nhân vụ cháy."},{"en":"Scientists want to investigate how sleep affects memory.","vi":"Các nhà khoa học muốn nghiên cứu xem giấc ngủ ảnh hưởng đến trí nhớ như thế nào."},{"en":"I heard a strange noise, so I went downstairs to investigate.","vi":"Tôi nghe thấy một tiếng động lạ nên đi xuống nhà để tìm hiểu."}]','[{"phrase":"investigate the cause"},{"phrase":"fully investigate"},{"phrase":"investigate a complaint"}]',NULL,'/ɪnˈvestɪɡeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investigate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1506,'ngsl-4-02',4,'recommendation','lời gợi ý, đề xuất; sự giới thiệu','noun','[{"en":"Do you have any recommendations for a good restaurant nearby?","vi":"Bạn có gợi ý nhà hàng nào ngon gần đây không?"},{"en":"The report makes several recommendations to improve safety at work.","vi":"Bản báo cáo đưa ra một số đề xuất nhằm cải thiện an toàn lao động."},{"en":"I bought this book on my teacher''s recommendation.","vi":"Tôi mua cuốn sách này theo lời giới thiệu của thầy giáo."}]','[{"phrase":"make a recommendation"},{"phrase":"strong recommendation"},{"phrase":"letter of recommendation"},{"phrase":"on someone''s recommendation"}]',NULL,'/ˌrekəmenˈdeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recom/recommendation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1507,'ngsl-4-02',5,'rank','xếp hạng; đứng (ở vị trí, thứ hạng)','verb','[{"en":"The city is ranked among the safest places to live.","vi":"Thành phố này được xếp vào hàng những nơi an toàn nhất để sinh sống."},{"en":"Our university ranks third in the country for engineering.","vi":"Trường đại học của chúng tôi đứng thứ ba cả nước về ngành kỹ thuật."},{"en":"Please rank these five tasks from most to least important.","vi":"Hãy xếp năm nhiệm vụ này theo thứ tự từ quan trọng nhất đến ít quan trọng nhất."}]','[{"phrase":"rank highly"},{"phrase":"rank first"},{"phrase":"rank among"}]','danh từ: rank = cấp bậc, thứ hạng','/ræŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/rank_/rank__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1508,'ngsl-4-02',6,'typical','điển hình; đặc trưng; thường thấy','adjective','[{"en":"A typical day for me starts at six in the morning.","vi":"Một ngày điển hình của tôi bắt đầu lúc sáu giờ sáng."},{"en":"This hot, rainy weather is typical of the south in summer.","vi":"Thời tiết nóng và mưa nhiều thế này là đặc trưng của miền Nam vào mùa hè."},{"en":"It''s typical of him to arrive late and blame the traffic.","vi":"Đến muộn rồi đổ lỗi cho giao thông là chuyện thường thấy ở anh ta."}]','[{"phrase":"typical example"},{"phrase":"typical day"},{"phrase":"typical of"},{"phrase":"fairly typical"}]','typical of sb/sth','/ˈtɪpɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/typ/typic/typical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1509,'ngsl-4-02',7,'west','phía tây; hướng tây','noun','[{"en":"The sun rises in the east and sets in the west.","vi":"Mặt trời mọc ở hướng đông và lặn ở hướng tây."},{"en":"My grandparents live in a small village in the west of the country.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ phía tây đất nước."},{"en":"We drove west for three hours before stopping for lunch.","vi":"Chúng tôi lái xe về hướng tây ba tiếng rồi mới dừng lại ăn trưa."}]','[{"phrase":"in the west"},{"phrase":"to the west of"},{"phrase":"head west"},{"phrase":"west coast"}]',NULL,'/west/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wes/west_/west__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1510,'ngsl-4-02',8,'friendly','thân thiện; thân thiết','adjective','[{"en":"The staff at the hotel were very friendly and helpful.","vi":"Nhân viên khách sạn rất thân thiện và nhiệt tình."},{"en":"She gave me a friendly smile when I walked in.","vi":"Cô ấy nở một nụ cười thân thiện với tôi khi tôi bước vào."},{"en":"We''ve been friendly with our neighbors for many years.","vi":"Chúng tôi đã thân thiết với hàng xóm nhiều năm nay."}]','[{"phrase":"friendly smile"},{"phrase":"friendly staff"},{"phrase":"be friendly with"},{"phrase":"environmentally friendly"}]','friendly là tính từ, không phải trạng từ','/ˈfrendli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frien/friendly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1511,'ngsl-4-02',9,'resident','cư dân; người sinh sống (ở một nơi)','noun','[{"en":"Local residents are complaining about the noise from the new bar.","vi":"Cư dân địa phương đang phàn nàn về tiếng ồn từ quán bar mới."},{"en":"Parking on this street is for residents only.","vi":"Chỗ đỗ xe trên con phố này chỉ dành cho cư dân."},{"en":"She has been a resident of this town for twenty years.","vi":"Bà ấy đã sinh sống ở thị trấn này được hai mươi năm."}]','[{"phrase":"local residents"},{"phrase":"resident of"},{"phrase":"permanent resident"}]',NULL,'/ˈrezɪdənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resid/resident__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1512,'ngsl-4-02',10,'provision','sự cung cấp; điều khoản; lương thực dự trữ','noun','[{"en":"The government is responsible for the provision of clean water.","vi":"Chính phủ chịu trách nhiệm về việc cung cấp nước sạch."},{"en":"The contract includes a provision for extra pay on holidays.","vi":"Hợp đồng có một điều khoản về việc trả thêm lương vào ngày lễ."},{"en":"The hikers carried enough provisions for a week in the mountains.","vi":"Những người leo núi mang đủ lương thực cho một tuần ở trên núi."}]','[{"phrase":"provision of services"},{"phrase":"make provision for"},{"phrase":"legal provision"}]','nghĩa lương thực dự trữ thường dùng ở số nhiều: provisions','/prəˈvɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/provi/provision__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1513,'ngsl-4-02',11,'concentrate','tập trung','verb','[{"en":"I can''t concentrate with all this noise outside.","vi":"Bên ngoài ồn ào thế này tôi không thể tập trung được."},{"en":"You should concentrate on your studies before the exam.","vi":"Bạn nên tập trung vào việc học trước kỳ thi."},{"en":"Most of the country''s population is concentrated in big cities.","vi":"Phần lớn dân số của đất nước tập trung ở các thành phố lớn."}]','[{"phrase":"concentrate on"},{"phrase":"concentrate hard"},{"phrase":"find it hard to concentrate"}]','concentrate on sth','/ˈkɑːnsntreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcentrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1514,'ngsl-4-02',12,'plenty','nhiều; dư dả','pronoun','[{"en":"Don''t worry, we have plenty of time before the train leaves.","vi":"Đừng lo, chúng ta còn nhiều thời gian trước khi tàu chạy."},{"en":"Make sure you drink plenty of water in hot weather.","vi":"Nhớ uống thật nhiều nước khi trời nóng nhé."},{"en":"There''s no need to buy more eggs; we''ve got plenty.","vi":"Không cần mua thêm trứng đâu, nhà mình còn nhiều rồi."}]','[{"phrase":"plenty of time"},{"phrase":"plenty of room"},{"phrase":"plenty of opportunities"}]','plenty of + danh từ đếm được hoặc không đếm được','/ˈplenti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/plent/plenty__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1515,'ngsl-4-02',13,'export','xuất khẩu; xuất (tệp, dữ liệu)','verb','[{"en":"Vietnam exports large amounts of rice and coffee every year.","vi":"Việt Nam xuất khẩu một lượng lớn gạo và cà phê mỗi năm."},{"en":"The factory exports most of its furniture to Europe.","vi":"Nhà máy xuất khẩu phần lớn đồ nội thất sang châu Âu."},{"en":"You can export the file as a PDF before sending it.","vi":"Bạn có thể xuất tệp sang định dạng PDF trước khi gửi đi."}]','[{"phrase":"export goods"},{"phrase":"export to"},{"phrase":"export data"}]','export ≠ import (nhập khẩu)','/ˈekspɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expor/export__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1516,'ngsl-4-02',14,'entirely','hoàn toàn','adverb','[{"en":"I''m not entirely sure what time the meeting starts.","vi":"Tôi không hoàn toàn chắc cuộc họp bắt đầu lúc mấy giờ."},{"en":"The accident was entirely my fault, not the other driver''s.","vi":"Vụ tai nạn hoàn toàn là lỗi của tôi, không phải của người lái xe kia."},{"en":"The house is built almost entirely of wood.","vi":"Ngôi nhà được xây gần như hoàn toàn bằng gỗ."}]','[{"phrase":"entirely different"},{"phrase":"not entirely sure"},{"phrase":"almost entirely"},{"phrase":"entirely possible"}]',NULL,'/ɪnˈtaɪərli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entir/entirely__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1517,'ngsl-4-02',15,'strongly','mạnh mẽ; kiên quyết; nồng (mùi)','adverb','[{"en":"I strongly recommend booking your tickets as early as possible.","vi":"Tôi thực sự khuyên bạn nên đặt vé càng sớm càng tốt."},{"en":"Many parents feel strongly about the new school rules.","vi":"Nhiều phụ huynh có quan điểm rất mạnh mẽ về nội quy mới của trường."},{"en":"The kitchen smelled strongly of garlic and onions.","vi":"Nhà bếp nồng nặc mùi tỏi và hành."}]','[{"phrase":"strongly recommend"},{"phrase":"strongly believe"},{"phrase":"feel strongly about"},{"phrase":"strongly disagree"}]',NULL,'/ˈstrɔːŋli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stron/strongly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1518,'ngsl-4-02',16,'bridge','cây cầu; cầu nối','noun','[{"en":"They are building a new bridge across the river.","vi":"Người ta đang xây một cây cầu mới bắc qua sông."},{"en":"We walked over the bridge to the old part of town.","vi":"Chúng tôi đi bộ qua cầu sang khu phố cổ."},{"en":"Music can act as a bridge between different cultures.","vi":"Âm nhạc có thể là cầu nối giữa các nền văn hóa khác nhau."}]','[{"phrase":"cross the bridge"},{"phrase":"build a bridge"},{"phrase":"bridge over"},{"phrase":"bridge between"}]',NULL,'/brɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/bridg/bridge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1519,'ngsl-4-02',17,'consist','gồm có, bao gồm','verb','[{"en":"The team consists of five designers and two engineers.","vi":"Nhóm gồm có năm nhà thiết kế và hai kỹ sư."},{"en":"Breakfast consisted of bread, eggs and a cup of tea.","vi":"Bữa sáng gồm bánh mì, trứng và một tách trà."},{"en":"The test consists mainly of multiple-choice questions.","vi":"Bài kiểm tra chủ yếu gồm các câu hỏi trắc nghiệm."}]','[{"phrase":"consist of"},{"phrase":"consist mainly of"},{"phrase":"consist largely of"}]','consist of sth; không dùng ở thể bị động hay tiếp diễn','/kənˈsɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1520,'ngsl-4-02',18,'graduate','tốt nghiệp','verb','[{"en":"My sister graduated from university last summer.","vi":"Chị tôi tốt nghiệp đại học vào mùa hè năm ngoái."},{"en":"After he graduates, he wants to work abroad for a year.","vi":"Sau khi tốt nghiệp, anh ấy muốn ra nước ngoài làm việc một năm."},{"en":"She graduated with a degree in computer science.","vi":"Cô ấy tốt nghiệp với tấm bằng ngành khoa học máy tính."}]','[{"phrase":"graduate from"},{"phrase":"graduate with a degree"},{"phrase":"graduate from high school"}]','graduate from + trường; danh từ: graduate = người đã tốt nghiệp','/ˈɡrædʒuət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gradu/graduate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1521,'ngsl-4-02',19,'brand','nhãn hiệu; thương hiệu','noun','[{"en":"Which brand of coffee do you usually buy?","vi":"Bạn thường mua cà phê của hiệu nào?"},{"en":"The company spent millions building its brand in Asia.","vi":"Công ty đã chi hàng triệu đô la để xây dựng thương hiệu ở châu Á."},{"en":"Supermarket brands are often just as good as the famous ones.","vi":"Hàng mang nhãn hiệu của siêu thị thường tốt không kém các hãng nổi tiếng."}]','[{"phrase":"brand name"},{"phrase":"brand of"},{"phrase":"leading brand"},{"phrase":"brand image"}]',NULL,'/brænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bra/brand/brand__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1522,'ngsl-4-02',20,'moral','(thuộc) đạo đức','adjective','[{"en":"Parents have a moral duty to take care of their children.","vi":"Cha mẹ có trách nhiệm về mặt đạo đức phải chăm sóc con cái."},{"en":"Doctors often face difficult moral questions in their work.","vi":"Các bác sĩ thường phải đối mặt với những câu hỏi khó về đạo đức trong công việc."},{"en":"She has strong moral values and always tells the truth.","vi":"Cô ấy có những giá trị đạo đức vững vàng và luôn nói thật."}]','[{"phrase":"moral duty"},{"phrase":"moral values"},{"phrase":"moral issue"}]','danh từ: the moral = bài học rút ra (từ câu chuyện)','/ˈmɔːrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/moral/moral__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1523,'ngsl-4-02',21,'insist','nhất quyết; khăng khăng','verb','[{"en":"My mother insisted that I wear a warm coat.","vi":"Mẹ tôi nhất quyết bắt tôi mặc áo khoác ấm."},{"en":"He insists on paying whenever we eat out together.","vi":"Lần nào chúng tôi đi ăn cùng nhau anh ấy cũng nhất quyết đòi trả tiền."},{"en":"She insisted she had never seen the man before.","vi":"Cô ấy khăng khăng rằng mình chưa từng gặp người đàn ông đó."}]','[{"phrase":"insist on"},{"phrase":"insist that"},{"phrase":"insist on paying"}]','insist on + V-ing; insist that + mệnh đề','/ɪnˈsɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insis/insist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1524,'ngsl-4-02',22,'combination','sự kết hợp; mã số (khóa)','noun','[{"en":"Success usually comes from a combination of talent and hard work.","vi":"Thành công thường đến từ sự kết hợp giữa tài năng và sự chăm chỉ."},{"en":"Red and green is an unusual color combination for a kitchen.","vi":"Đỏ và xanh lá là một sự kết hợp màu lạ cho căn bếp."},{"en":"I forgot the combination to my bike lock.","vi":"Tôi quên mất mã số khóa xe đạp của mình."}]','[{"phrase":"a combination of"},{"phrase":"in combination with"},{"phrase":"color combination"},{"phrase":"unique combination"}]',NULL,'/ˌkɑːmbɪˈneɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/combi/combination__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1525,'ngsl-4-02',23,'abuse','sự lạm dụng; lời lăng mạ','noun','[{"en":"The new law aims to prevent the abuse of power.","vi":"Luật mới nhằm ngăn chặn tình trạng lạm dụng quyền lực."},{"en":"Alcohol abuse can cause serious health problems.","vi":"Lạm dụng rượu bia có thể gây ra những vấn đề sức khỏe nghiêm trọng."},{"en":"Shop staff should not have to put up with abuse from customers.","vi":"Nhân viên cửa hàng không đáng phải chịu những lời lăng mạ từ khách hàng."}]','[{"phrase":"abuse of power"},{"phrase":"alcohol abuse"},{"phrase":"verbal abuse"}]','động từ: abuse /əˈbjuːz/; danh từ: abuse /əˈbjuːs/','/əˈbjuːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abu/abuse/abuse__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1526,'ngsl-4-02',24,'ice','nước đá; băng','noun','[{"en":"Would you like some ice in your drink?","vi":"Bạn có muốn cho thêm đá vào đồ uống không?"},{"en":"Be careful, the roads are covered in ice this morning.","vi":"Cẩn thận nhé, sáng nay đường phủ đầy băng."},{"en":"The children went skating on the ice after school.","vi":"Sau giờ học, bọn trẻ đi trượt trên mặt băng."}]','[{"phrase":"ice cube"},{"phrase":"thin ice"},{"phrase":"covered in ice"}]','không đếm được','/aɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ice/ice__/ice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1527,'ngsl-4-02',25,'principal','chính, chủ yếu','adjective','[{"en":"Tourism is the principal source of income for the island.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo."},{"en":"Our principal concern is the safety of the children.","vi":"Mối quan tâm chính của chúng tôi là sự an toàn của bọn trẻ."},{"en":"The principal reason for the delay was bad weather.","vi":"Lý do chính của sự chậm trễ là thời tiết xấu."}]','[{"phrase":"principal reason"},{"phrase":"principal source"},{"phrase":"principal aim"}]','danh từ (Mỹ): hiệu trưởng; principal ≠ principle (nguyên tắc)','/ˈprɪnsəpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1528,'ngsl-4-02',26,'master','thành thạo; nắm vững','verb','[{"en":"It takes years to master a foreign language.","vi":"Phải mất nhiều năm mới thành thạo được một ngoại ngữ."},{"en":"Once you master the basic steps, the dance is easy.","vi":"Một khi đã nắm vững các bước cơ bản thì điệu nhảy này dễ thôi."},{"en":"She mastered the guitar in less than two years.","vi":"Cô ấy chơi thành thạo đàn guitar chỉ trong chưa đầy hai năm."}]','[{"phrase":"master a skill"},{"phrase":"master a language"},{"phrase":"master the basics"}]','danh từ: master = bậc thầy; chủ nhân','/ˈmæstər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mas/maste/master__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1529,'ngsl-4-02',27,'definitely','chắc chắn; nhất định','adverb','[{"en":"I''ll definitely call you when I get home.","vi":"Về đến nhà tôi nhất định sẽ gọi cho bạn."},{"en":"This is definitely the best pizza I''ve ever had.","vi":"Đây chắc chắn là chiếc pizza ngon nhất tôi từng ăn."},{"en":"We''re definitely going to need a bigger car next year.","vi":"Năm sau chắc chắn chúng tôi sẽ cần một chiếc xe lớn hơn."}]','[{"phrase":"definitely not"},{"phrase":"most definitely"},{"phrase":"definitely worth"}]',NULL,'/ˈdefɪnətli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/definitely__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1530,'ngsl-4-02',28,'session','buổi (học, tập); phiên (họp)','noun','[{"en":"I have a training session at the gym every Tuesday.","vi":"Tôi có một buổi tập ở phòng gym vào mỗi thứ Ba."},{"en":"The first session of the conference starts at nine.","vi":"Phiên họp đầu tiên của hội nghị bắt đầu lúc chín giờ."},{"en":"After each session, the teacher gives us some homework.","vi":"Sau mỗi buổi học, giáo viên giao cho chúng tôi một ít bài tập về nhà."}]','[{"phrase":"training session"},{"phrase":"practice session"},{"phrase":"question-and-answer session"}]',NULL,'/ˈseʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ses/sessi/session__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1531,'ngsl-4-02',29,'grade','điểm (số); lớp (ở trường); loại, hạng','noun','[{"en":"She got good grades in math and science this year.","vi":"Năm nay cô ấy được điểm cao môn toán và khoa học."},{"en":"My son is in the fourth grade at a local school.","vi":"Con trai tôi đang học lớp bốn ở một trường gần nhà."},{"en":"Eggs are sorted into different grades according to their size.","vi":"Trứng được phân thành các loại khác nhau theo kích cỡ."}]','[{"phrase":"good grades"},{"phrase":"get a grade"},{"phrase":"high grade"}]',NULL,'/ɡreɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grade/grade__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1532,'ngsl-4-02',30,'nevertheless','tuy nhiên; dù vậy','adverb','[{"en":"The weather was terrible; nevertheless, we enjoyed our trip.","vi":"Thời tiết rất tệ, tuy nhiên chúng tôi vẫn rất thích chuyến đi."},{"en":"It was a hard decision, but nevertheless the right one.","vi":"Đó là một quyết định khó khăn, nhưng dù vậy vẫn là quyết định đúng đắn."},{"en":"He knew the risks but decided to go ahead nevertheless.","vi":"Anh ấy biết rõ rủi ro nhưng dù vậy vẫn quyết định làm tiếp."}]','[{"phrase":"but nevertheless"},{"phrase":"nevertheless true"},{"phrase":"nevertheless important"}]',NULL,'/ˌnevərðəˈles/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nev/never/nevertheless__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1533,'ngsl-4-03',1,'predict','dự đoán','verb','[{"en":"Nobody can predict exactly what the weather will do next week.","vi":"Không ai có thể dự đoán chính xác thời tiết tuần sau sẽ thế nào."},{"en":"Experts predict that house prices will rise again this year.","vi":"Các chuyên gia dự đoán giá nhà sẽ lại tăng trong năm nay."},{"en":"The ending of the movie was easy to predict.","vi":"Cái kết của bộ phim rất dễ đoán."}]','[{"phrase":"predict the future"},{"phrase":"accurately predict"},{"phrase":"difficult to predict"}]',NULL,'/prɪˈdɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/predi/predict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1534,'ngsl-4-03',2,'previously','trước đây; trước đó','adverb','[{"en":"I had previously worked as a teacher in a small town.","vi":"Trước đây tôi từng làm giáo viên ở một thị trấn nhỏ."},{"en":"The shop was previously a bakery, but now it sells clothes.","vi":"Cửa hàng này trước đây là tiệm bánh, nhưng giờ bán quần áo."},{"en":"As I mentioned previously, the meeting starts at nine.","vi":"Như tôi đã nói trước đó, cuộc họp bắt đầu lúc chín giờ."}]','[{"phrase":"previously mentioned"},{"phrase":"as previously stated"},{"phrase":"previously unknown"}]',NULL,'/ˈpriːviəsli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/previ/previously__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1535,'ngsl-4-03',3,'protection','sự bảo vệ','noun','[{"en":"Wear sunglasses for protection against the strong summer sun.","vi":"Hãy đeo kính râm để bảo vệ mắt khỏi nắng hè gay gắt."},{"en":"These gloves offer good protection from the cold.","vi":"Đôi găng tay này giúp bảo vệ tốt khỏi cái lạnh."},{"en":"The new law gives better protection to workers.","vi":"Luật mới bảo vệ người lao động tốt hơn."}]','[{"phrase":"protection against"},{"phrase":"protection from"},{"phrase":"provide protection"},{"phrase":"environmental protection"}]','protection against/from sth','/prəˈtekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protection__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1536,'ngsl-4-03',4,'largely','phần lớn; chủ yếu','adverb','[{"en":"The success of the town is largely due to tourism.","vi":"Sự thành công của thị trấn chủ yếu là nhờ du lịch."},{"en":"These days her work is largely done from home.","vi":"Dạo này công việc của cô ấy phần lớn được làm ở nhà."},{"en":"My advice was largely ignored by the rest of the team.","vi":"Lời khuyên của tôi phần lớn bị những người còn lại trong nhóm phớt lờ."}]','[{"phrase":"largely due to"},{"phrase":"largely because"},{"phrase":"largely ignored"}]',NULL,'/ˈlɑːrdʒli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lar/large/largely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1537,'ngsl-4-03',5,'wed','kết hôn; cưới','verb','[{"en":"They wed in a small garden ceremony last spring.","vi":"Họ kết hôn trong một buổi lễ nhỏ ngoài vườn vào mùa xuân năm ngoái."},{"en":"My sister and her boyfriend plan to get wed next year.","vi":"Chị tôi và bạn trai dự định cưới nhau vào năm sau."},{"en":"The couple were wed on a beach near their hometown.","vi":"Cặp đôi đã cưới nhau trên một bãi biển gần quê nhà."}]','[{"phrase":"get wed"},{"phrase":"newly wed"}]','wed – wed/wedded – wed/wedded; hay dùng trong báo chí','/wed/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wed/wed__/wed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1538,'ngsl-4-03',6,'rent','thuê; cho thuê','verb','[{"en":"We rented a small car for our trip to the coast.","vi":"Chúng tôi đã thuê một chiếc xe nhỏ cho chuyến đi biển."},{"en":"They rent a two-bedroom apartment near the city center.","vi":"Họ thuê một căn hộ hai phòng ngủ gần trung tâm thành phố."},{"en":"My uncle rents his old house to students.","vi":"Chú tôi cho sinh viên thuê căn nhà cũ của chú."}]','[{"phrase":"rent an apartment"},{"phrase":"rent a car"},{"phrase":"rent out"}]','danh từ: tiền thuê (pay the rent)','/rent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ren/rent_/rent__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1539,'ngsl-4-03',7,'shot','cú sút; bức ảnh; mũi tiêm','noun','[{"en":"His shot hit the post in the last minute of the game.","vi":"Cú sút của anh ấy trúng cột dọc ở phút cuối trận."},{"en":"She took a beautiful shot of the sunset from the balcony.","vi":"Cô ấy chụp được một bức ảnh hoàng hôn rất đẹp từ ban công."},{"en":"The nurse said the flu shot would not hurt much.","vi":"Y tá nói mũi tiêm phòng cúm sẽ không đau lắm."}]','[{"phrase":"take a shot"},{"phrase":"flu shot"},{"phrase":"good shot"}]',NULL,'/ʃɑːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shot_/shot__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1540,'ngsl-4-03',8,'appearance','vẻ bề ngoài; sự xuất hiện','noun','[{"en":"He cares a lot about his appearance.","vi":"Anh ấy rất quan tâm đến vẻ bề ngoài của mình."},{"en":"She changed her appearance completely by cutting her hair short.","vi":"Cô ấy thay đổi hoàn toàn vẻ ngoài bằng cách cắt tóc ngắn."},{"en":"The singer made a short appearance at the end of the show.","vi":"Ca sĩ xuất hiện chớp nhoáng vào cuối chương trình."}]','[{"phrase":"physical appearance"},{"phrase":"make an appearance"},{"phrase":"sudden appearance"}]',NULL,'/əˈpɪrəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appea/appearance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1541,'ngsl-4-03',9,'reasonable','hợp lý; phải chăng','adjective','[{"en":"The hotel was clean and the prices were very reasonable.","vi":"Khách sạn sạch sẽ và giá cả rất phải chăng."},{"en":"That sounds like a reasonable plan to me.","vi":"Tôi thấy đó có vẻ là một kế hoạch hợp lý."},{"en":"We need a reasonable amount of time to finish the job.","vi":"Chúng tôi cần một khoảng thời gian hợp lý để hoàn thành công việc."}]','[{"phrase":"reasonable price"},{"phrase":"reasonable explanation"},{"phrase":"perfectly reasonable"}]',NULL,'/ˈriːznəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reaso/reasonable__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1542,'ngsl-4-03',10,'guarantee','đảm bảo; cam kết','verb','[{"en":"Hard work does not guarantee success, but it certainly helps.","vi":"Làm việc chăm chỉ không đảm bảo thành công, nhưng chắc chắn là có ích."},{"en":"We guarantee delivery within three working days.","vi":"Chúng tôi cam kết giao hàng trong vòng ba ngày làm việc."},{"en":"I cannot guarantee that the train will be on time.","vi":"Tôi không thể đảm bảo tàu sẽ đến đúng giờ."}]','[{"phrase":"guarantee success"},{"phrase":"cannot guarantee"},{"phrase":"money-back guarantee"}]','danh từ: sự bảo đảm; giấy bảo hành','/ˌɡærənˈtiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gua/guara/guarantee__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1543,'ngsl-4-03',11,'till','cho đến; đến tận','preposition','[{"en":"I worked till midnight to finish my report.","vi":"Tôi làm việc đến tận nửa đêm để hoàn thành báo cáo."},{"en":"We stayed at the beach till sunset.","vi":"Chúng tôi ở lại bãi biển cho đến lúc hoàng hôn."},{"en":"The store is open till ten o''clock tonight.","vi":"Cửa hàng mở cửa đến mười giờ tối nay."}]','[{"phrase":"till now"},{"phrase":"till then"},{"phrase":"from morning till night"}]','thân mật, nghĩa như until','/tɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/til/till_/till__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1544,'ngsl-4-03',12,'theme','chủ đề','noun','[{"en":"The main theme of the book is friendship.","vi":"Chủ đề chính của cuốn sách là tình bạn."},{"en":"Love and loss are common themes in her songs.","vi":"Tình yêu và mất mát là những chủ đề thường gặp trong các bài hát của cô ấy."},{"en":"Our party had a movie theme, so everyone dressed up.","vi":"Bữa tiệc của chúng tôi có chủ đề phim ảnh, nên ai cũng hóa trang."}]','[{"phrase":"main theme"},{"phrase":"common theme"},{"phrase":"central theme"},{"phrase":"theme park"}]',NULL,'/θiːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theme/theme__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1545,'ngsl-4-03',13,'judgment','sự phán đoán; óc suy xét','noun','[{"en":"I trust your judgment on this matter.","vi":"Tôi tin vào sự phán đoán của bạn trong chuyện này."},{"en":"Try not to make quick judgments about people you have just met.","vi":"Cố đừng vội đánh giá những người bạn mới gặp."},{"en":"Being very tired can affect your judgment when you drive.","vi":"Quá mệt có thể ảnh hưởng đến khả năng phán đoán khi bạn lái xe."}]','[{"phrase":"good judgment"},{"phrase":"poor judgment"},{"phrase":"make a judgment"},{"phrase":"trust your judgment"}]','Mỹ: judgment · Anh: judgement','/ˈdʒʌdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1546,'ngsl-4-03',14,'odd','kỳ lạ; lẻ','adjective','[{"en":"It is odd that he has not called me back yet.","vi":"Thật lạ là anh ấy vẫn chưa gọi lại cho tôi."},{"en":"My new neighbor seems a bit odd, but he is friendly.","vi":"Người hàng xóm mới của tôi có vẻ hơi kỳ lạ, nhưng anh ấy thân thiện."},{"en":"Three, five and seven are all odd numbers.","vi":"Ba, năm và bảy đều là số lẻ."}]','[{"phrase":"odd number"},{"phrase":"a bit odd"},{"phrase":"seem odd"}]',NULL,'/ɑːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/odd/odd__/odd__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1547,'ngsl-4-03',15,'approve','chấp thuận; tán thành','verb','[{"en":"The manager approved my request for a week off.","vi":"Quản lý đã chấp thuận đơn xin nghỉ một tuần của tôi."},{"en":"My parents did not approve of my decision to quit my job.","vi":"Bố mẹ tôi không tán thành quyết định nghỉ việc của tôi."},{"en":"The city has approved plans for a new park.","vi":"Thành phố đã chấp thuận kế hoạch xây một công viên mới."}]','[{"phrase":"approve of"},{"phrase":"approve a plan"},{"phrase":"approve a request"}]','approve of sth: tán thành điều gì','/əˈpruːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approve__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1548,'ngsl-4-03',16,'loan','khoản vay; sự cho vay','noun','[{"en":"She took out a loan to buy her first car.","vi":"Cô ấy đã vay tiền để mua chiếc ô tô đầu tiên."},{"en":"The bank refused to give him a loan.","vi":"Ngân hàng từ chối cho anh ấy vay tiền."},{"en":"It will take us ten years to pay back the loan.","vi":"Chúng tôi sẽ mất mười năm để trả hết khoản vay."}]','[{"phrase":"take out a loan"},{"phrase":"bank loan"},{"phrase":"student loan"},{"phrase":"pay back a loan"}]',NULL,'/ləʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loa/loan_/loan__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1549,'ngsl-4-03',17,'definition','định nghĩa','noun','[{"en":"Look up the definition of this word in your dictionary.","vi":"Hãy tra định nghĩa của từ này trong từ điển của bạn."},{"en":"Everyone has their own definition of success.","vi":"Mỗi người có một định nghĩa riêng về thành công."},{"en":"Can you give me a clear definition of the term?","vi":"Bạn có thể cho tôi một định nghĩa rõ ràng về thuật ngữ này không?"}]','[{"phrase":"clear definition"},{"phrase":"by definition"},{"phrase":"dictionary definition"}]',NULL,'/ˌdefɪˈnɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/definition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1550,'ngsl-4-03',18,'elect','bầu; bầu chọn','verb','[{"en":"The students elected a new class president this morning.","vi":"Sáng nay học sinh đã bầu lớp trưởng mới."},{"en":"Club members elect a new chairman every year.","vi":"Các thành viên câu lạc bộ bầu chủ tịch mới mỗi năm."},{"en":"He was elected captain of the football team.","vi":"Anh ấy được bầu làm đội trưởng đội bóng đá."}]','[{"phrase":"be elected"},{"phrase":"newly elected"},{"phrase":"elect a leader"}]',NULL,'/ɪˈlekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/elect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1551,'ngsl-4-03',19,'atmosphere','bầu không khí; khí quyển','noun','[{"en":"The restaurant has a warm and friendly atmosphere.","vi":"Nhà hàng có bầu không khí ấm cúng và thân thiện."},{"en":"There was a tense atmosphere in the office after the meeting.","vi":"Không khí trong văn phòng rất căng thẳng sau cuộc họp."},{"en":"Cars release harmful gases into the atmosphere every day.","vi":"Ô tô thải khí độc hại vào khí quyển mỗi ngày."}]','[{"phrase":"friendly atmosphere"},{"phrase":"relaxed atmosphere"},{"phrase":"the earth''s atmosphere"}]',NULL,'/ˈætməsfɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/atm/atmos/atmosphere__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1552,'ngsl-4-03',20,'farmer','nông dân','noun','[{"en":"The farmer gets up at five to feed his cows.","vi":"Người nông dân dậy lúc năm giờ để cho bò ăn."},{"en":"Many farmers grow rice and vegetables in this area.","vi":"Nhiều nông dân trồng lúa và rau ở vùng này."},{"en":"We buy fresh eggs from a local farmer every week.","vi":"Chúng tôi mua trứng tươi của một bác nông dân địa phương mỗi tuần."}]','[{"phrase":"local farmer"},{"phrase":"rice farmer"},{"phrase":"dairy farmer"}]',NULL,'/ˈfɑːrmər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/far/farme/farmer__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1553,'ngsl-4-03',21,'comparison','sự so sánh','noun','[{"en":"Sales this year are low in comparison with last year.","vi":"Doanh số năm nay thấp so với năm ngoái."},{"en":"It is hard to make a comparison between the two cities.","vi":"Thật khó để so sánh hai thành phố này."},{"en":"My new laptop is fast, and my old one seems slow by comparison.","vi":"Máy tính mới của tôi rất nhanh, so ra thì máy cũ có vẻ chậm."}]','[{"phrase":"in comparison with"},{"phrase":"make a comparison"},{"phrase":"by comparison"}]',NULL,'/kəmˈpærɪsn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/comparison__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1554,'ngsl-4-03',22,'characteristic','đặc điểm; đặc trưng','noun','[{"en":"Patience is an important characteristic of a good teacher.","vi":"Kiên nhẫn là một đặc điểm quan trọng của một giáo viên giỏi."},{"en":"The two cats share many physical characteristics.","vi":"Hai con mèo có nhiều đặc điểm ngoại hình giống nhau."},{"en":"What are the main characteristics of this style of painting?","vi":"Những đặc trưng chính của phong cách hội họa này là gì?"}]','[{"phrase":"physical characteristics"},{"phrase":"main characteristic"},{"phrase":"common characteristic"}]','cũng là tính từ: đặc trưng, tiêu biểu','/ˌkærəktəˈrɪstɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chara/characteristic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1555,'ngsl-4-03',23,'license','giấy phép; bằng lái','noun','[{"en":"You need a license to open a restaurant here.","vi":"Bạn cần có giấy phép để mở nhà hàng ở đây."},{"en":"He finally got his driver''s license at the age of twenty.","vi":"Cuối cùng anh ấy cũng lấy được bằng lái xe năm hai mươi tuổi."},{"en":"The police officer asked to see my license.","vi":"Viên cảnh sát yêu cầu xem bằng lái của tôi."}]','[{"phrase":"driver''s license"},{"phrase":"get a license"},{"phrase":"business license"}]','Mỹ: license · Anh: licence (danh từ)','/ˈlaɪsns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lic/licen/license__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1556,'ngsl-4-03',24,'rely','dựa vào; tin cậy','verb','[{"en":"Many students rely on their parents for money.","vi":"Nhiều sinh viên dựa vào bố mẹ về tiền bạc."},{"en":"You can always rely on her to tell the truth.","vi":"Bạn luôn có thể tin cô ấy sẽ nói thật."},{"en":"We should not rely too much on our phones.","vi":"Chúng ta không nên dựa dẫm quá nhiều vào điện thoại."}]','[{"phrase":"rely on"},{"phrase":"rely heavily on"},{"phrase":"can rely on"}]','rely on/upon sb/sth','/rɪˈlaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/rely_/rely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1557,'ngsl-4-03',25,'narrow','hẹp; sít sao','adjective','[{"en":"The streets in the old town are very narrow.","vi":"Đường phố ở khu phố cổ rất hẹp."},{"en":"We walked along a narrow path by the river.","vi":"Chúng tôi đi bộ dọc theo một con đường hẹp bên sông."},{"en":"Our team won a narrow victory in the final game.","vi":"Đội chúng tôi giành chiến thắng sít sao trong trận cuối cùng."}]','[{"phrase":"narrow street"},{"phrase":"narrow path"},{"phrase":"narrow victory"},{"phrase":"narrow escape"}]',NULL,'/ˈnærəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nar/narro/narrow__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1558,'ngsl-4-03',26,'succeed','thành công','verb','[{"en":"If you keep working hard, you will succeed.","vi":"Nếu bạn tiếp tục chăm chỉ, bạn sẽ thành công."},{"en":"She succeeded in passing the exam on her first try.","vi":"Cô ấy đã thành công vượt qua kỳ thi ngay lần đầu."},{"en":"After many months, our plan to save money finally succeeded.","vi":"Sau nhiều tháng, kế hoạch tiết kiệm tiền của chúng tôi cuối cùng đã thành công."}]','[{"phrase":"succeed in"},{"phrase":"finally succeed"},{"phrase":"succeed in business"}]','succeed in doing sth','/səkˈsiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/succeed__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1559,'ngsl-4-03',27,'identity','danh tính; bản sắc','noun','[{"en":"Please bring a document that proves your identity.","vi":"Vui lòng mang theo giấy tờ chứng minh danh tính của bạn."},{"en":"The identity of the winner will be announced tomorrow.","vi":"Danh tính người chiến thắng sẽ được công bố vào ngày mai."},{"en":"Language is an important part of a country''s cultural identity.","vi":"Ngôn ngữ là một phần quan trọng trong bản sắc văn hóa của một quốc gia."}]','[{"phrase":"identity card"},{"phrase":"cultural identity"},{"phrase":"national identity"},{"phrase":"prove your identity"}]',NULL,'/aɪˈdentəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identity__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1560,'ngsl-4-03',28,'desk','bàn làm việc; bàn học; quầy','noun','[{"en":"I keep a small plant on my desk at work.","vi":"Tôi để một chậu cây nhỏ trên bàn làm việc ở công ty."},{"en":"Please leave your key at the front desk.","vi":"Vui lòng để lại chìa khóa ở quầy lễ tân."},{"en":"The kids did their homework at the desk in their room.","vi":"Bọn trẻ làm bài tập ở bàn học trong phòng."}]','[{"phrase":"front desk"},{"phrase":"office desk"},{"phrase":"desk job"},{"phrase":"sit at a desk"}]',NULL,'/desk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desk_/desk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1561,'ngsl-4-03',29,'permit','cho phép','verb','[{"en":"Smoking is not permitted inside the building.","vi":"Không được phép hút thuốc bên trong tòa nhà."},{"en":"The library rules permit each student to borrow five books.","vi":"Nội quy thư viện cho phép mỗi học sinh mượn năm cuốn sách."},{"en":"We will have a picnic tomorrow, weather permitting.","vi":"Nếu thời tiết cho phép, ngày mai chúng tôi sẽ đi dã ngoại."}]','[{"phrase":"weather permitting"},{"phrase":"be permitted to"},{"phrase":"permit someone to"}]','permit – permitted – permitted; danh từ: giấy phép','/pərˈmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/permi/permit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1562,'ngsl-4-03',30,'seriously','nghiêm túc; nghiêm trọng','adverb','[{"en":"You should take your health more seriously.","vi":"Bạn nên coi trọng sức khỏe của mình hơn."},{"en":"The old house was seriously damaged by the storm.","vi":"Ngôi nhà cũ bị cơn bão làm hư hại nghiêm trọng."},{"en":"Are you seriously thinking about moving abroad?","vi":"Bạn đang nghiêm túc tính chuyện ra nước ngoài sống à?"}]','[{"phrase":"take seriously"},{"phrase":"seriously damaged"},{"phrase":"seriously consider"}]',NULL,'/ˈsɪriəsli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serio/seriously__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1563,'ngsl-4-04',1,'wild','hoang dã; cuồng nhiệt, điên cuồng','adjective','[{"en":"We saw wild elephants during our trip to the national park.","vi":"Chúng tôi đã thấy voi hoang dã trong chuyến đi đến vườn quốc gia."},{"en":"These wild flowers grow everywhere along the river in spring.","vi":"Những bông hoa dại này mọc khắp nơi dọc bờ sông vào mùa xuân."},{"en":"The crowd went wild when the band came on stage.","vi":"Đám đông trở nên cuồng nhiệt khi ban nhạc bước lên sân khấu."}]','[{"phrase":"wild animals"},{"phrase":"wild flowers"},{"phrase":"go wild"},{"phrase":"wild guess"}]',NULL,'/waɪld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wil/wild_/wild__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1564,'ngsl-4-04',2,'empty','trống, rỗng; vắng vẻ','adjective','[{"en":"Please put the empty bottles in the recycling bin.","vi":"Vui lòng bỏ những chai rỗng vào thùng tái chế."},{"en":"The streets were completely empty early on Sunday morning.","vi":"Đường phố hoàn toàn vắng vẻ vào sáng sớm Chủ nhật."},{"en":"Is this seat empty, or is someone sitting here?","vi":"Ghế này còn trống không, hay đã có người ngồi rồi?"}]','[{"phrase":"empty bottle"},{"phrase":"empty room"},{"phrase":"completely empty"},{"phrase":"empty seat"}]',NULL,'/ˈempti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empty/empty__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1565,'ngsl-4-04',3,'commission','ủy ban; tiền hoa hồng','noun','[{"en":"The government set up a commission to study the problem.","vi":"Chính phủ đã thành lập một ủy ban để nghiên cứu vấn đề này."},{"en":"She earns a commission on every house she sells.","vi":"Cô ấy nhận tiền hoa hồng cho mỗi căn nhà cô ấy bán được."},{"en":"Salespeople in this shop are paid mostly on commission.","vi":"Nhân viên bán hàng ở cửa hàng này chủ yếu được trả lương theo hoa hồng."}]','[{"phrase":"set up a commission"},{"phrase":"earn a commission"},{"phrase":"on commission"}]','on commission: hưởng theo hoa hồng','/kəˈmɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commission__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1566,'ngsl-4-04',4,'unique','độc nhất, duy nhất; độc đáo','adjective','[{"en":"Every person has a unique set of fingerprints.","vi":"Mỗi người đều có một bộ dấu vân tay độc nhất."},{"en":"This small town has a unique style of cooking.","vi":"Thị trấn nhỏ này có một phong cách nấu ăn độc đáo."},{"en":"This problem is not unique to our school.","vi":"Vấn đề này không chỉ riêng trường chúng ta mới có."}]','[{"phrase":"unique opportunity"},{"phrase":"unique to"},{"phrase":"truly unique"},{"phrase":"unique style"}]','unique to sth: chỉ riêng có ở','/juˈniːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/uniqu/unique__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1567,'ngsl-4-04',5,'association','hiệp hội; mối liên hệ, sự liên kết','noun','[{"en":"My father is a member of the local football association.","vi":"Bố tôi là thành viên của hiệp hội bóng đá địa phương."},{"en":"The teachers formed an association to protect their rights.","vi":"Các giáo viên đã thành lập một hiệp hội để bảo vệ quyền lợi của mình."},{"en":"Scientists found a strong association between smoking and heart disease.","vi":"Các nhà khoa học tìm thấy mối liên hệ chặt chẽ giữa hút thuốc và bệnh tim."}]','[{"phrase":"in association with"},{"phrase":"association between"},{"phrase":"form an association"},{"phrase":"strong association"}]',NULL,'/əˌsəʊsiˈeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assoc/association__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1568,'ngsl-4-04',6,'instrument','nhạc cụ; dụng cụ','noun','[{"en":"Can you play any musical instruments, like the guitar?","vi":"Bạn có chơi được nhạc cụ nào không, chẳng hạn như đàn guitar?"},{"en":"The piano was the first instrument she learned to play.","vi":"Đàn piano là nhạc cụ đầu tiên cô ấy học chơi."},{"en":"The nurse cleaned all the instruments before the operation.","vi":"Y tá đã làm sạch tất cả dụng cụ trước ca mổ."}]','[{"phrase":"musical instrument"},{"phrase":"play an instrument"},{"phrase":"medical instruments"}]',NULL,'/ˈɪnstrəmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/instr/instrument__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1569,'ngsl-4-04',7,'investor','nhà đầu tư','noun','[{"en":"The company is looking for investors to help it grow.","vi":"Công ty đang tìm kiếm nhà đầu tư để giúp mình phát triển."},{"en":"Many small investors lost money when prices fell.","vi":"Nhiều nhà đầu tư nhỏ lẻ đã mất tiền khi giá giảm."},{"en":"Foreign investors are showing more interest in the city.","vi":"Các nhà đầu tư nước ngoài đang quan tâm nhiều hơn đến thành phố này."}]','[{"phrase":"foreign investors"},{"phrase":"small investors"},{"phrase":"attract investors"},{"phrase":"private investor"}]',NULL,'/ɪnˈvestər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1570,'ngsl-4-04',8,'practical','thực tế; thiết thực, tiện dụng','adjective','[{"en":"The course gives students practical experience in real companies.","vi":"Khóa học mang lại cho sinh viên kinh nghiệm thực tế tại các công ty thật."},{"en":"These shoes are not very pretty, but they are practical.","vi":"Đôi giày này không đẹp lắm, nhưng rất tiện dụng."},{"en":"We need a practical solution, not just good ideas.","vi":"Chúng ta cần một giải pháp thiết thực, chứ không chỉ là ý tưởng hay."}]','[{"phrase":"practical experience"},{"phrase":"practical solution"},{"phrase":"practical advice"},{"phrase":"practical skills"}]',NULL,'/ˈpræktɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pract/practical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1571,'ngsl-4-04',9,'tea','trà','noun','[{"en":"Would you like a cup of tea?","vi":"Bạn có muốn một tách trà không?"},{"en":"My grandmother drinks green tea every morning after breakfast.","vi":"Bà tôi uống trà xanh mỗi sáng sau bữa sáng."},{"en":"I made some tea while we waited for the rain to stop.","vi":"Tôi pha một ít trà trong lúc chúng tôi chờ mưa tạnh."}]','[{"phrase":"cup of tea"},{"phrase":"green tea"},{"phrase":"make tea"},{"phrase":"drink tea"}]',NULL,'/tiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/tea__/tea__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1572,'ngsl-4-04',10,'lovely','đẹp, đáng yêu; rất dễ chịu, tuyệt','adjective','[{"en":"You have a lovely garden with so many flowers.","vi":"Bạn có một khu vườn thật đẹp với rất nhiều hoa."},{"en":"We had a lovely time at the beach last weekend.","vi":"Cuối tuần trước chúng tôi đã có khoảng thời gian thật tuyệt ở bãi biển."},{"en":"It would be lovely to see you again soon.","vi":"Thật tuyệt nếu sớm được gặp lại bạn."}]','[{"phrase":"lovely day"},{"phrase":"have a lovely time"},{"phrase":"lovely to see you"},{"phrase":"absolutely lovely"}]',NULL,'/ˈlʌvli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lov/lovel/lovely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1573,'ngsl-4-04',11,'soft','mềm; nhẹ nhàng, dịu','adjective','[{"en":"This pillow is too soft for me.","vi":"Cái gối này quá mềm đối với tôi."},{"en":"The baby has soft skin and tiny fingers.","vi":"Em bé có làn da mềm mại và những ngón tay nhỏ xíu."},{"en":"She spoke in a soft voice so she would not wake anyone.","vi":"Cô ấy nói bằng giọng nhẹ nhàng để không đánh thức ai."}]','[{"phrase":"soft voice"},{"phrase":"soft music"},{"phrase":"soft drink"},{"phrase":"soft skin"}]',NULL,'/sɔːft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sof/soft_/soft__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1574,'ngsl-4-04',12,'row','hàng, dãy','noun','[{"en":"We sat in the front row at the concert.","vi":"Chúng tôi ngồi ở hàng ghế đầu trong buổi hòa nhạc."},{"en":"There is a row of small shops along this street.","vi":"Có một dãy cửa hàng nhỏ dọc con phố này."},{"en":"Our team has won five games in a row.","vi":"Đội chúng tôi đã thắng năm trận liên tiếp."}]','[{"phrase":"front row"},{"phrase":"in a row"},{"phrase":"row of houses"},{"phrase":"back row"}]','in a row: liên tiếp','/ˈroʊ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1575,'ngsl-4-04',13,'youth','tuổi trẻ; thanh thiếu niên','noun','[{"en":"He spent most of his youth in a small village.","vi":"Anh ấy đã trải qua phần lớn tuổi trẻ ở một ngôi làng nhỏ."},{"en":"In her youth, she was a very fast runner.","vi":"Thời trẻ, cô ấy chạy rất nhanh."},{"en":"The city opened a new youth center for local teenagers.","vi":"Thành phố đã mở một trung tâm thanh thiếu niên mới cho các bạn trẻ địa phương."}]','[{"phrase":"in your youth"},{"phrase":"youth club"},{"phrase":"youth center"}]',NULL,'/juːθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/you/youth/youth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1576,'ngsl-4-04',14,'lock','khóa','verb','[{"en":"Did you lock the front door before we left?","vi":"Bạn đã khóa cửa trước trước khi chúng ta đi chưa?"},{"en":"Always lock your bike when you leave it outside.","vi":"Luôn khóa xe đạp khi bạn để nó ở bên ngoài."},{"en":"The office is locked at night, so nobody can get in.","vi":"Văn phòng được khóa vào ban đêm nên không ai vào được."}]','[{"phrase":"lock the door"},{"phrase":"lock up"},{"phrase":"keep something locked"}]',NULL,'/lɑːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/lock_/lock__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1577,'ngsl-4-04',15,'fuel','nhiên liệu','noun','[{"en":"The price of fuel has gone up again this month.","vi":"Giá nhiên liệu lại tăng trong tháng này."},{"en":"Our car ran out of fuel on the way home.","vi":"Xe của chúng tôi hết nhiên liệu trên đường về nhà."},{"en":"Bigger cars usually use more fuel than small ones.","vi":"Xe lớn thường tốn nhiều nhiên liệu hơn xe nhỏ."}]','[{"phrase":"fuel prices"},{"phrase":"run out of fuel"},{"phrase":"use fuel"},{"phrase":"fossil fuels"}]',NULL,'/ˈfjuːəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fue/fuel_/fuel__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1578,'ngsl-4-04',16,'expectation','sự mong đợi, kỳ vọng','noun','[{"en":"Her parents have very high expectations for her.","vi":"Bố mẹ cô ấy đặt kỳ vọng rất cao vào cô ấy."},{"en":"The hotel was much better than our expectations.","vi":"Khách sạn tốt hơn nhiều so với mong đợi của chúng tôi."},{"en":"The new phone did not meet customers’ expectations.","vi":"Chiếc điện thoại mới đã không đáp ứng được kỳ vọng của khách hàng."}]','[{"phrase":"high expectations"},{"phrase":"meet expectations"},{"phrase":"beyond expectations"},{"phrase":"live up to expectations"}]',NULL,'/ˌekspekˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expec/expectation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1579,'ngsl-4-04',17,'employment','việc làm; sự tuyển dụng','noun','[{"en":"Many young people move to cities to find employment.","vi":"Nhiều người trẻ chuyển lên thành phố để tìm việc làm."},{"en":"The new factory will create employment for hundreds of workers.","vi":"Nhà máy mới sẽ tạo việc làm cho hàng trăm công nhân."},{"en":"Please read your employment contract carefully before signing it.","vi":"Vui lòng đọc kỹ hợp đồng lao động trước khi ký."}]','[{"phrase":"find employment"},{"phrase":"employment contract"},{"phrase":"full-time employment"},{"phrase":"create employment"}]','không đếm được','/ɪmˈplɔɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1580,'ngsl-4-04',18,'celebrate','ăn mừng; kỷ niệm','verb','[{"en":"We went out for dinner to celebrate her new job.","vi":"Chúng tôi đi ăn tối để ăn mừng việc cô ấy có công việc mới."},{"en":"My parents are celebrating their 30th wedding anniversary this year.","vi":"Năm nay bố mẹ tôi kỷ niệm 30 năm ngày cưới."},{"en":"How do people in your country celebrate the New Year?","vi":"Người dân ở nước bạn ăn mừng năm mới như thế nào?"}]','[{"phrase":"celebrate a birthday"},{"phrase":"celebrate an anniversary"},{"phrase":"celebrate success"}]',NULL,'/ˈselɪbreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cel/celeb/celebrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1581,'ngsl-4-04',19,'sexual','(thuộc) tình dục; (thuộc) giới tính','adjective','[{"en":"The clinic gives young people free advice about sexual health.","vi":"Phòng khám tư vấn miễn phí cho người trẻ về sức khỏe tình dục."},{"en":"The company has clear rules against sexual harassment at work.","vi":"Công ty có quy định rõ ràng chống quấy rối tình dục nơi làm việc."},{"en":"In biology class, we learned how sexual reproduction works in plants.","vi":"Trong giờ sinh học, chúng tôi đã học về cách sinh sản hữu tính diễn ra ở thực vật."}]','[{"phrase":"sexual health"},{"phrase":"sexual harassment"},{"phrase":"sexual reproduction"}]',NULL,'/ˈsekʃuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sex/sexua/sexual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1582,'ngsl-4-04',20,'shoulder','vai','noun','[{"en":"She put her hand on my shoulder and smiled.","vi":"Cô ấy đặt tay lên vai tôi và mỉm cười."},{"en":"My shoulders hurt after carrying that heavy bag all day.","vi":"Vai tôi đau sau khi mang cái túi nặng đó cả ngày."},{"en":"He looked over his shoulder to see who was there.","vi":"Anh ấy ngoái lại phía sau để xem ai ở đó."}]','[{"phrase":"over your shoulder"},{"phrase":"shoulder pain"},{"phrase":"shrug your shoulders"}]',NULL,'/ˈʃəʊldər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shoul/shoulder__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1583,'ngsl-4-04',21,'breath','hơi thở','noun','[{"en":"Take a deep breath and try to relax.","vi":"Hãy hít một hơi thật sâu và cố gắng thư giãn."},{"en":"I was out of breath after running up the stairs.","vi":"Tôi hụt hơi sau khi chạy lên cầu thang."},{"en":"She held her breath as she opened the letter.","vi":"Cô ấy nín thở khi mở lá thư."}]','[{"phrase":"take a deep breath"},{"phrase":"out of breath"},{"phrase":"hold your breath"}]','breath (n) ≠ breathe (v)','/breθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breat/breath__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1584,'ngsl-4-04',22,'increasingly','ngày càng','adverb','[{"en":"Online shopping is becoming increasingly popular with older people.","vi":"Mua sắm trực tuyến ngày càng phổ biến với người lớn tuổi."},{"en":"It is increasingly difficult to find a cheap apartment here.","vi":"Ngày càng khó tìm được một căn hộ giá rẻ ở đây."},{"en":"As the weeks passed, he became increasingly worried about his exam.","vi":"Nhiều tuần trôi qua, anh ấy ngày càng lo lắng về kỳ thi."}]','[{"phrase":"increasingly popular"},{"phrase":"increasingly difficult"},{"phrase":"increasingly important"}]',NULL,'/ɪnˈkriːsɪŋli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incre/increasingly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1585,'ngsl-4-04',23,'import','nhập khẩu','verb','[{"en":"Our country imports most of its oil from abroad.","vi":"Nước ta nhập khẩu phần lớn dầu mỏ từ nước ngoài."},{"en":"This shop sells cheese imported from France.","vi":"Cửa hàng này bán phô mai nhập khẩu từ Pháp."},{"en":"The company plans to import cars from Japan next year.","vi":"Công ty dự định nhập khẩu ô tô từ Nhật Bản vào năm tới."}]','[{"phrase":"import goods"},{"phrase":"import from"},{"phrase":"imported products"}]','import (nhập khẩu) ≠ export (xuất khẩu)','/ˈɪmpɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impor/import__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1586,'ngsl-4-04',24,'bottle','chai, lọ; bình (sữa)','noun','[{"en":"Can you bring me a bottle of water, please?","vi":"Bạn có thể mang cho tôi một chai nước được không?"},{"en":"We opened a bottle of wine to celebrate.","vi":"Chúng tôi đã mở một chai rượu vang để ăn mừng."},{"en":"Babies usually drink milk from a bottle at night.","vi":"Em bé thường uống sữa bằng bình vào ban đêm."}]','[{"phrase":"bottle of water"},{"phrase":"plastic bottle"},{"phrase":"open a bottle"},{"phrase":"empty bottle"}]',NULL,'/ˈbɑːtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bot/bottl/bottle__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1587,'ngsl-4-04',25,'sheet','tờ (giấy); ga trải giường','noun','[{"en":"Write your name at the top of the sheet.","vi":"Hãy viết tên của bạn ở đầu tờ giấy."},{"en":"Could you give me a few sheets of paper?","vi":"Bạn có thể đưa cho tôi vài tờ giấy không?"},{"en":"I change the sheets on my bed every week.","vi":"Tôi thay ga trải giường mỗi tuần."}]','[{"phrase":"sheet of paper"},{"phrase":"change the sheets"},{"phrase":"clean sheets"}]',NULL,'/ʃiːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/sheet/sheet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1588,'ngsl-4-04',26,'engine','động cơ','noun','[{"en":"The engine would not start on such a cold morning.","vi":"Động cơ không chịu khởi động vào buổi sáng lạnh như vậy."},{"en":"He turned off the engine and got out of the car.","vi":"Anh ấy tắt động cơ rồi bước ra khỏi xe."},{"en":"My uncle knows a lot about fixing car engines.","vi":"Chú tôi biết rất nhiều về sửa động cơ ô tô."}]','[{"phrase":"start the engine"},{"phrase":"turn off the engine"},{"phrase":"car engine"},{"phrase":"engine trouble"}]',NULL,'/ˈendʒɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eng/engin/engine__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1589,'ngsl-4-04',27,'cast','dàn diễn viên; bó bột','noun','[{"en":"The whole cast came back on stage at the end.","vi":"Toàn bộ dàn diễn viên trở lại sân khấu vào cuối buổi diễn."},{"en":"The film has a great cast of young actors.","vi":"Bộ phim có một dàn diễn viên trẻ rất xuất sắc."},{"en":"She broke her arm and had it in a cast for weeks.","vi":"Cô ấy bị gãy tay và phải bó bột trong nhiều tuần."}]','[{"phrase":"the whole cast"},{"phrase":"cast member"},{"phrase":"in a cast"},{"phrase":"plaster cast"}]','động từ: cast – cast – cast','/kæst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/cast_/cast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1590,'ngsl-4-04',28,'notion','khái niệm; quan niệm, ý niệm','noun','[{"en":"Many people still hold the notion that money brings happiness.","vi":"Nhiều người vẫn giữ quan niệm rằng tiền bạc mang lại hạnh phúc."},{"en":"Young children have no notion of time.","vi":"Trẻ nhỏ không có khái niệm về thời gian."},{"en":"I reject the notion that girls are bad at math.","vi":"Tôi bác bỏ quan niệm rằng con gái học toán kém."}]','[{"phrase":"the notion that"},{"phrase":"no notion of"},{"phrase":"reject the notion"}]',NULL,'/ˈnəʊʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notio/notion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1591,'ngsl-4-04',29,'conservative','bảo thủ; thận trọng','adjective','[{"en":"My grandparents have quite conservative ideas about marriage.","vi":"Ông bà tôi có quan điểm khá bảo thủ về hôn nhân."},{"en":"Older people are often more conservative about spending money.","vi":"Người lớn tuổi thường thận trọng hơn trong việc tiêu tiền."},{"en":"Even by a conservative estimate, the repairs will cost a lot.","vi":"Ngay cả theo ước tính thận trọng, việc sửa chữa cũng sẽ tốn nhiều tiền."}]','[{"phrase":"conservative estimate"},{"phrase":"conservative views"},{"phrase":"deeply conservative"}]',NULL,'/kənˈsɜːrvətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconservative__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1592,'ngsl-4-04',30,'journey','chuyến đi, hành trình','noun','[{"en":"The journey from Hanoi to Hue takes about twelve hours by train.","vi":"Chuyến đi từ Hà Nội đến Huế mất khoảng mười hai tiếng bằng tàu hỏa."},{"en":"We wished them a safe journey before they left.","vi":"Chúng tôi chúc họ thượng lộ bình an trước khi họ lên đường."},{"en":"Learning a new language is a long journey.","vi":"Học một ngôn ngữ mới là một hành trình dài."}]','[{"phrase":"long journey"},{"phrase":"safe journey"},{"phrase":"make a journey"},{"phrase":"journey home"}]',NULL,'/ˈdʒɜːrni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journey__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1593,'ngsl-4-05',1,'opposition','sự phản đối; đối thủ','noun','[{"en":"There was strong opposition to the new parking rules.","vi":"Có sự phản đối mạnh mẽ đối với quy định đỗ xe mới."},{"en":"Many parents expressed opposition to the plan to close the school.","vi":"Nhiều phụ huynh bày tỏ sự phản đối kế hoạch đóng cửa trường học."},{"en":"Our team faced tough opposition in the final match.","vi":"Đội chúng tôi gặp đối thủ khó chơi trong trận chung kết."}]','[{"phrase":"strong opposition"},{"phrase":"opposition to"},{"phrase":"face opposition"}]',NULL,'/ˌɑːpəˈzɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppos/opposition__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1594,'ngsl-4-05',2,'relief','sự nhẹ nhõm; sự cứu trợ','noun','[{"en":"It was a huge relief to hear that everyone was safe.","vi":"Thật nhẹ nhõm khi nghe tin mọi người đều an toàn."},{"en":"She breathed a sigh of relief when the exam was over.","vi":"Cô ấy thở phào nhẹ nhõm khi kỳ thi kết thúc."},{"en":"Volunteers delivered relief supplies to families after the flood.","vi":"Các tình nguyện viên đã chuyển hàng cứu trợ đến các gia đình sau trận lũ."}]','[{"phrase":"sigh of relief"},{"phrase":"huge relief"},{"phrase":"relief supplies"},{"phrase":"pain relief"}]',NULL,'/rɪˈliːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relie/relief__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1595,'ngsl-4-05',3,'debt','nợ; khoản nợ','noun','[{"en":"He worked two jobs to pay off his debt.","vi":"Anh ấy làm hai công việc để trả hết nợ."},{"en":"Many students are in debt when they finish college.","vi":"Nhiều sinh viên đang mắc nợ khi học xong đại học."},{"en":"It is easy to get into debt with a credit card.","vi":"Rất dễ mắc nợ khi dùng thẻ tín dụng."}]','[{"phrase":"pay off a debt"},{"phrase":"in debt"},{"phrase":"get into debt"}]','chữ b không phát âm: /det/','/det/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deb/debt_/debt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1596,'ngsl-4-05',4,'honor','vinh dự; danh dự','noun','[{"en":"It is a great honor to meet you.","vi":"Thật là một vinh dự lớn khi được gặp bạn."},{"en":"Keeping your promises is a matter of honor.","vi":"Giữ lời hứa là vấn đề danh dự."},{"en":"The hotel held a dinner in honor of its oldest employee.","vi":"Khách sạn tổ chức một bữa tối để vinh danh nhân viên lớn tuổi nhất."}]','[{"phrase":"great honor"},{"phrase":"in honor of"},{"phrase":"matter of honor"}]','Anh: honour · Mỹ: honor','/ˈɑːnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hon/honou/honour__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1597,'ngsl-4-05',5,'outcome','kết quả','noun','[{"en":"We are still waiting for the outcome of the meeting.","vi":"Chúng tôi vẫn đang chờ kết quả của cuộc họp."},{"en":"Both teams were happy with the final outcome.","vi":"Cả hai đội đều hài lòng với kết quả cuối cùng."},{"en":"Careful planning can lead to a better outcome.","vi":"Lên kế hoạch cẩn thận có thể mang lại kết quả tốt hơn."}]','[{"phrase":"final outcome"},{"phrase":"outcome of"},{"phrase":"positive outcome"},{"phrase":"successful outcome"}]',NULL,'/ˈaʊtkʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outco/outcome__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1598,'ngsl-4-05',6,'blame','đổ lỗi; trách','verb','[{"en":"Don''t blame me for your own mistakes.","vi":"Đừng đổ lỗi cho tôi vì những sai lầm của chính bạn."},{"en":"She blamed the heavy traffic for being late.","vi":"Cô ấy đổ lỗi cho tình trạng kẹt xe vì đã đến muộn."},{"en":"I don''t blame you for feeling upset about it.","vi":"Tôi không trách bạn khi thấy buồn về chuyện đó."}]','[{"phrase":"blame someone for"},{"phrase":"be to blame"},{"phrase":"blame yourself"}]',NULL,'/bleɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bla/blame/blame__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1599,'ngsl-4-05',7,'explanation','lời giải thích','noun','[{"en":"The teacher gave a clear explanation of the grammar rule.","vi":"Giáo viên đưa ra lời giải thích rõ ràng về quy tắc ngữ pháp."},{"en":"Is there any explanation for why the train was late?","vi":"Có lời giải thích nào cho việc tàu đến muộn không?"},{"en":"He left the room without a word of explanation.","vi":"Anh ấy rời khỏi phòng mà không một lời giải thích."}]','[{"phrase":"clear explanation"},{"phrase":"give an explanation"},{"phrase":"explanation for"},{"phrase":"explanation of"}]',NULL,'/ˌekspləˈneɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expla/explanation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1600,'ngsl-4-05',8,'arise','nảy sinh; phát sinh','verb','[{"en":"Problems may arise if you don''t read the instructions.","vi":"Vấn đề có thể nảy sinh nếu bạn không đọc hướng dẫn."},{"en":"Call me if any questions arise during the trip.","vi":"Hãy gọi cho tôi nếu có thắc mắc nào phát sinh trong chuyến đi."},{"en":"A problem arose when we tried to book the hotel.","vi":"Một vấn đề đã phát sinh khi chúng tôi đặt phòng khách sạn."}]','[{"phrase":"problems arise"},{"phrase":"questions arise"},{"phrase":"if the need arises"}]','arise – arose – arisen','/əˈraɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ari/arise/arise__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1601,'ngsl-4-05',9,'musical','thuộc về âm nhạc; có năng khiếu âm nhạc','adjective','[{"en":"Do you play any musical instruments, such as the piano?","vi":"Bạn có chơi nhạc cụ nào không, chẳng hạn như piano?"},{"en":"Everyone in her family is very musical.","vi":"Mọi người trong gia đình cô ấy đều rất có năng khiếu âm nhạc."},{"en":"His musical talent was clear from a young age.","vi":"Tài năng âm nhạc của cậu ấy đã bộc lộ từ khi còn nhỏ."}]','[{"phrase":"musical instrument"},{"phrase":"musical talent"},{"phrase":"musical ability"}]',NULL,'/ˈmjuːzɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/music/musical__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1602,'ngsl-4-05',10,'recover','hồi phục; tìm lại được','verb','[{"en":"It took him three months to recover from the accident.","vi":"Anh ấy mất ba tháng để hồi phục sau tai nạn."},{"en":"I hope you recover quickly from your cold.","vi":"Mong bạn mau khỏi cảm."},{"en":"The police recovered the stolen bike two days later.","vi":"Hai ngày sau, cảnh sát đã tìm lại được chiếc xe đạp bị đánh cắp."}]','[{"phrase":"recover from"},{"phrase":"fully recover"},{"phrase":"recover quickly"}]',NULL,'/rɪˈkʌvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recov/recover__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1603,'ngsl-4-05',11,'dad','bố; ba','noun','[{"en":"My dad taught me how to ride a bike.","vi":"Bố tôi đã dạy tôi đi xe đạp."},{"en":"Dad, can you pick me up after school today?","vi":"Bố ơi, hôm nay bố đón con sau giờ học được không?"},{"en":"She calls her dad every Sunday evening.","vi":"Cô ấy gọi điện cho bố vào mỗi tối Chủ nhật."}]','[{"phrase":"my dad"},{"phrase":"mom and dad"}]',NULL,'/dæd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dad/dad__/dad__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1604,'ngsl-4-05',12,'stretch','duỗi; vươn mình; kéo giãn','verb','[{"en":"Always stretch your legs before you go running.","vi":"Hãy luôn giãn cơ chân trước khi chạy bộ."},{"en":"The cat woke up and stretched in the sun.","vi":"Con mèo thức dậy và vươn mình dưới nắng."},{"en":"Don''t stretch my sweater, or it will lose its shape.","vi":"Đừng kéo giãn áo len của tôi, không thì nó sẽ bị mất dáng."}]','[{"phrase":"stretch your legs"},{"phrase":"stretch out"},{"phrase":"stretch your arms"}]',NULL,'/stretʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stret/stretch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1605,'ngsl-4-05',13,'declare','tuyên bố; khai báo','verb','[{"en":"The judges declared her the winner of the competition.","vi":"Ban giám khảo tuyên bố cô ấy là người chiến thắng cuộc thi."},{"en":"I had nothing to declare, so I walked through customs.","vi":"Tôi không có gì cần khai báo nên đi thẳng qua hải quan."},{"en":"He declared that he would never smoke again.","vi":"Anh ấy tuyên bố sẽ không bao giờ hút thuốc nữa."}]','[{"phrase":"officially declare"},{"phrase":"declare income"},{"phrase":"nothing to declare"}]',NULL,'/dɪˈkler/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decla/declare__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1606,'ngsl-4-05',14,'retire','nghỉ hưu','verb','[{"en":"My grandfather retired at the age of sixty-five.","vi":"Ông tôi nghỉ hưu năm sáu mươi lăm tuổi."},{"en":"She plans to retire early and move to the countryside.","vi":"Bà ấy dự định nghỉ hưu sớm và chuyển về vùng quê."},{"en":"After he retires, he wants to travel around the world.","vi":"Sau khi nghỉ hưu, ông ấy muốn đi du lịch vòng quanh thế giới."}]','[{"phrase":"retire early"},{"phrase":"retire from"},{"phrase":"retire at"}]',NULL,'/rɪˈtaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retir/retire__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1607,'ngsl-4-05',15,'tiny','rất nhỏ; bé xíu','adjective','[{"en":"They live in a tiny apartment in the city center.","vi":"Họ sống trong một căn hộ rất nhỏ ở trung tâm thành phố."},{"en":"The baby grabbed my finger with her tiny hand.","vi":"Em bé nắm lấy ngón tay tôi bằng bàn tay bé xíu."},{"en":"There is only a tiny difference between the two photos.","vi":"Chỉ có một khác biệt rất nhỏ giữa hai bức ảnh."}]','[{"phrase":"a tiny bit"},{"phrase":"tiny amount"},{"phrase":"tiny apartment"}]',NULL,'/ˈtaɪni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tin/tiny_/tiny__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1608,'ngsl-4-05',16,'careful','cẩn thận; kỹ lưỡng','adjective','[{"en":"Be careful when you cross the street.","vi":"Hãy cẩn thận khi bạn băng qua đường."},{"en":"She is very careful with her money.","vi":"Cô ấy rất cẩn thận trong chuyện tiền bạc."},{"en":"After careful thought, we decided not to buy the house.","vi":"Sau khi suy nghĩ kỹ lưỡng, chúng tôi quyết định không mua căn nhà."}]','[{"phrase":"be careful"},{"phrase":"careful with"},{"phrase":"careful thought"},{"phrase":"careful planning"}]',NULL,'/ˈkerfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/caref/careful__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1609,'ngsl-4-05',17,'suitable','phù hợp; thích hợp','adjective','[{"en":"This movie is not suitable for young children.","vi":"Bộ phim này không phù hợp với trẻ nhỏ."},{"en":"We are looking for a suitable place to have the party.","vi":"Chúng tôi đang tìm một địa điểm phù hợp để tổ chức bữa tiệc."},{"en":"Please wear suitable shoes for the long walk.","vi":"Hãy mang giày thích hợp cho chuyến đi bộ dài."}]','[{"phrase":"suitable for"},{"phrase":"suitable place"},{"phrase":"suitable time"}]',NULL,'/ˈsuːtəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sui/suita/suitable__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1610,'ngsl-4-05',18,'native','bản xứ; bản địa; thuộc nơi sinh ra','adjective','[{"en":"She is a native speaker of Spanish.","vi":"Cô ấy là người bản xứ nói tiếng Tây Ban Nha."},{"en":"He returned to his native country after ten years abroad.","vi":"Anh ấy trở về quê hương sau mười năm sống ở nước ngoài."},{"en":"These flowers are native to South America.","vi":"Những loài hoa này có nguồn gốc từ Nam Mỹ."}]','[{"phrase":"native speaker"},{"phrase":"native language"},{"phrase":"native country"},{"phrase":"native to"}]',NULL,'/ˈneɪtɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/nativ/native__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1611,'ngsl-4-05',19,'fruit','trái cây; hoa quả','noun','[{"en":"You should eat more fresh fruit and vegetables.","vi":"Bạn nên ăn nhiều trái cây tươi và rau hơn."},{"en":"We bought some fruit at the market this morning.","vi":"Sáng nay chúng tôi đã mua ít trái cây ở chợ."},{"en":"Which fruit do you like best, apples or oranges?","vi":"Bạn thích loại quả nào nhất, táo hay cam?"}]','[{"phrase":"fresh fruit"},{"phrase":"fruit juice"},{"phrase":"piece of fruit"}]','thường không đếm được: some fruit','/fruːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fru/fruit/fruit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1612,'ngsl-4-05',20,'analyze','phân tích','verb','[{"en":"Scientists analyzed the water to see if it was safe.","vi":"Các nhà khoa học đã phân tích nước để xem nó có an toàn không."},{"en":"Let''s analyze why our sales dropped last month.","vi":"Hãy phân tích lý do doanh số giảm vào tháng trước."},{"en":"It takes time to analyze all this data carefully.","vi":"Cần có thời gian để phân tích kỹ tất cả dữ liệu này."}]','[{"phrase":"analyze data"},{"phrase":"carefully analyze"},{"phrase":"analyze the results"}]','Anh: analyse · Mỹ: analyze','/ˈænəˌlaɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1613,'ngsl-4-05',21,'witness','nhân chứng; người chứng kiến','noun','[{"en":"The police are looking for witnesses to the accident.","vi":"Cảnh sát đang tìm nhân chứng của vụ tai nạn."},{"en":"A witness said the car was going very fast.","vi":"Một nhân chứng nói rằng chiếc xe chạy rất nhanh."},{"en":"She was the only witness when the window broke.","vi":"Cô ấy là người chứng kiến duy nhất khi cửa sổ bị vỡ."}]','[{"phrase":"key witness"},{"phrase":"witness to"},{"phrase":"the only witness"}]',NULL,'/ˈwɪtnəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/witne/witness__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1614,'ngsl-4-05',22,'mail','thư từ; bưu phẩm','noun','[{"en":"Did any mail come for me today?","vi":"Hôm nay có thư nào gửi cho tôi không?"},{"en":"I check my mail every morning before work.","vi":"Tôi kiểm tra thư mỗi sáng trước khi đi làm."},{"en":"The package should arrive in the mail next week.","vi":"Gói hàng chắc sẽ đến qua đường bưu điện vào tuần sau."}]','[{"phrase":"check your mail"},{"phrase":"in the mail"},{"phrase":"junk mail"}]','không đếm được','/meɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/mail_/mail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1615,'ngsl-4-05',23,'terrible','kinh khủng; tồi tệ','adjective','[{"en":"The food at that restaurant was terrible.","vi":"Đồ ăn ở nhà hàng đó thật tồi tệ."},{"en":"I have a terrible headache this morning.","vi":"Sáng nay tôi bị đau đầu kinh khủng."},{"en":"I feel terrible about forgetting your birthday.","vi":"Tôi thấy thật tệ vì đã quên sinh nhật bạn."}]','[{"phrase":"feel terrible"},{"phrase":"terrible mistake"},{"phrase":"terrible weather"}]',NULL,'/ˈterəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/terri/terrible__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1616,'ngsl-4-05',24,'researcher','nhà nghiên cứu','noun','[{"en":"The researchers asked five hundred people about their sleeping habits.","vi":"Các nhà nghiên cứu đã hỏi năm trăm người về thói quen ngủ của họ."},{"en":"My sister works as a medical researcher at a university.","vi":"Chị tôi làm nhà nghiên cứu y khoa tại một trường đại học."},{"en":"Researchers have found that walking every day is good for your heart.","vi":"Các nhà nghiên cứu đã phát hiện rằng đi bộ mỗi ngày tốt cho tim."}]','[{"phrase":"medical researcher"},{"phrase":"team of researchers"},{"phrase":"market researcher"}]',NULL,'/ˈriːsɜːrtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resea/researcher__us_6.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1617,'ngsl-4-05',25,'ordinary','bình thường; thông thường','adjective','[{"en":"It was just an ordinary day at the office.","vi":"Đó chỉ là một ngày bình thường ở văn phòng."},{"en":"Ordinary people can''t afford such expensive houses.","vi":"Người bình thường không đủ tiền mua những ngôi nhà đắt như vậy."},{"en":"The hotel room looked quite ordinary, but the view was amazing.","vi":"Phòng khách sạn trông khá bình thường, nhưng cảnh nhìn ra thì tuyệt vời."}]','[{"phrase":"ordinary people"},{"phrase":"ordinary life"},{"phrase":"out of the ordinary"}]',NULL,'/ˈɔːrdneri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ord/ordin/ordinary__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1618,'ngsl-4-05',26,'selection','sự lựa chọn; sự tuyển chọn','noun','[{"en":"The market has a wide selection of fresh vegetables.","vi":"Chợ có rất nhiều loại rau tươi để lựa chọn."},{"en":"Her selection for the national team made her parents proud.","vi":"Việc cô ấy được chọn vào đội tuyển quốc gia khiến bố mẹ tự hào."},{"en":"The final selection of players will be announced on Friday.","vi":"Danh sách cầu thủ được chọn cuối cùng sẽ được công bố vào thứ Sáu."}]','[{"phrase":"wide selection"},{"phrase":"selection of"},{"phrase":"final selection"},{"phrase":"selection process"}]',NULL,'/sɪˈlekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/selec/selection__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1619,'ngsl-4-05',27,'anywhere','bất cứ đâu; (ở) đâu đó','adverb','[{"en":"You can sit anywhere you like in the classroom.","vi":"Bạn có thể ngồi bất cứ chỗ nào bạn thích trong lớp học."},{"en":"I can''t find my phone anywhere in the house.","vi":"Tôi không tìm thấy điện thoại ở đâu trong nhà cả."},{"en":"Are you going anywhere nice for the holidays this year?","vi":"Kỳ nghỉ năm nay bạn có đi đâu thú vị không?"}]','[{"phrase":"anywhere else"},{"phrase":"go anywhere"},{"phrase":"anywhere you like"}]',NULL,'/ˈeniwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anywh/anywhere__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1620,'ngsl-4-05',28,'mental','thuộc về tinh thần; trí óc','adjective','[{"en":"Exercise is good for both physical and mental health.","vi":"Tập thể dục tốt cho cả sức khỏe thể chất lẫn tinh thần."},{"en":"Try to do some simple mental math without a calculator.","vi":"Hãy thử tính nhẩm vài phép đơn giản mà không dùng máy tính."},{"en":"Working long hours can cause a lot of mental stress.","vi":"Làm việc nhiều giờ liền có thể gây ra nhiều căng thẳng tinh thần."}]','[{"phrase":"mental health"},{"phrase":"mental stress"},{"phrase":"mental math"}]',NULL,'/ˈmentl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menta/mental__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1621,'ngsl-4-05',29,'participant','người tham gia','noun','[{"en":"Each participant will receive a free T-shirt.","vi":"Mỗi người tham gia sẽ nhận được một chiếc áo phông miễn phí."},{"en":"She was an active participant in every class discussion.","vi":"Cô ấy là người tham gia tích cực trong mọi buổi thảo luận trên lớp."},{"en":"All participants must register before the race starts.","vi":"Tất cả người tham gia phải đăng ký trước khi cuộc đua bắt đầu."}]','[{"phrase":"active participant"},{"phrase":"participant in"},{"phrase":"all participants"}]',NULL,'/pɑːrˈtɪsɪpənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1622,'ngsl-4-05',30,'vision','thị lực; tầm nhìn','noun','[{"en":"My vision is getting worse, so I need new glasses.","vi":"Thị lực của tôi đang kém đi nên tôi cần kính mới."},{"en":"The eye doctor tested my vision this morning.","vi":"Sáng nay bác sĩ mắt đã kiểm tra thị lực của tôi."},{"en":"The new manager has a clear vision for the company''s future.","vi":"Người quản lý mới có tầm nhìn rõ ràng cho tương lai của công ty."}]','[{"phrase":"clear vision"},{"phrase":"poor vision"},{"phrase":"vision for the future"}]',NULL,'/ˈvɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visio/vision__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1623,'ngsl-4-06',1,'personality','tính cách; cá tính','noun','[{"en":"She has a warm personality and makes friends easily.","vi":"Cô ấy có tính cách ấm áp và dễ kết bạn."},{"en":"His personality changed a lot after he started university.","vi":"Tính cách của anh ấy đã thay đổi nhiều sau khi vào đại học."},{"en":"It''s important to find a job that suits your personality.","vi":"Điều quan trọng là tìm được công việc phù hợp với tính cách của bạn."}]','[{"phrase":"warm personality"},{"phrase":"strong personality"},{"phrase":"personality trait"}]',NULL,'/ˌpɜːrsəˈnæləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personality__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1624,'ngsl-4-06',2,'specifically','cụ thể; riêng (cho)','adverb','[{"en":"The course was designed specifically for beginners.","vi":"Khóa học được thiết kế riêng cho người mới bắt đầu."},{"en":"I specifically asked you not to tell anyone.","vi":"Tôi đã dặn rõ là bạn không được kể với ai."},{"en":"More specifically, we need someone who can speak Japanese.","vi":"Cụ thể hơn, chúng tôi cần một người nói được tiếng Nhật."}]','[{"phrase":"designed specifically for"},{"phrase":"more specifically"},{"phrase":"specifically mention"}]',NULL,'/spəˈsɪfɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specifically__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1625,'ngsl-4-06',3,'fat','béo, mập; dày','adjective','[{"en":"Our cat got fat because we fed her too much.","vi":"Con mèo nhà chúng tôi béo lên vì chúng tôi cho nó ăn quá nhiều."},{"en":"He was worried that he was getting fat.","vi":"Anh ấy lo rằng mình đang béo lên."},{"en":"She handed me a fat envelope full of old photos.","vi":"Cô ấy đưa tôi một phong bì dày cộp đầy ảnh cũ."}]','[{"phrase":"get fat"},{"phrase":"grow fat"}]','fat – fatter – fattest; nói về người có thể bị coi là bất lịch sự','/fæt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fat/fat__/fat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1626,'ngsl-4-06',4,'entry','sự vào, quyền vào; mục ghi; bài dự thi','noun','[{"en":"Entry to the museum is free on Sundays.","vi":"Vào cửa bảo tàng được miễn phí vào các ngày Chủ nhật."},{"en":"I wrote a short diary entry before bed.","vi":"Tôi viết một trang nhật ký ngắn trước khi đi ngủ."},{"en":"The winning entry was a photo of a sleeping child.","vi":"Bài dự thi đoạt giải là bức ảnh một đứa trẻ đang ngủ."}]','[{"phrase":"free entry"},{"phrase":"entry fee"},{"phrase":"diary entry"},{"phrase":"winning entry"}]',NULL,'/ˈentri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entry/entry__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1627,'ngsl-4-06',5,'fellow','đồng (nghiệp, học…); cùng cảnh','adjective','[{"en":"She gets along well with her fellow students.","vi":"Cô ấy hòa hợp với các bạn cùng học."},{"en":"He shared his lunch with a fellow passenger on the train.","vi":"Anh ấy chia bữa trưa với một hành khách đi cùng trên tàu."},{"en":"My fellow workers threw me a party on my last day.","vi":"Các đồng nghiệp đã tổ chức tiệc cho tôi vào ngày làm việc cuối cùng."}]','[{"phrase":"fellow students"},{"phrase":"fellow passengers"},{"phrase":"fellow citizens"}]','chỉ đứng trước danh từ; (n) gã, anh chàng','/ˈfeləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fel/fello/fellow__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1628,'ngsl-4-06',6,'chemical','hóa chất; chất hóa học','noun','[{"en":"Wear gloves when you use strong cleaning chemicals.","vi":"Hãy đeo găng tay khi dùng các hóa chất tẩy rửa mạnh."},{"en":"The factory was fined for dumping chemicals into the river.","vi":"Nhà máy bị phạt vì xả hóa chất xuống sông."},{"en":"These vegetables are grown without any harmful chemicals.","vi":"Những loại rau này được trồng mà không dùng hóa chất độc hại nào."}]','[{"phrase":"harmful chemicals"},{"phrase":"toxic chemicals"},{"phrase":"cleaning chemicals"}]','(adj) thuộc hóa học: chemical reaction','/ˈkemɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chemi/chemical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1629,'ngsl-4-06',7,'capture','bắt giữ; ghi lại (hình ảnh); thu hút','verb','[{"en":"Zoo workers captured the escaped monkey near the river.","vi":"Nhân viên sở thú đã bắt được con khỉ xổng chuồng gần bờ sông."},{"en":"This photo really captures the beauty of the old town.","vi":"Bức ảnh này thực sự ghi lại được vẻ đẹp của phố cổ."},{"en":"The story captured the attention of readers all over the country.","vi":"Câu chuyện đã thu hút sự chú ý của độc giả khắp cả nước."}]','[{"phrase":"capture attention"},{"phrase":"capture the moment"},{"phrase":"capture the imagination"}]',NULL,'/ˈkæptʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/captu/capture__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1630,'ngsl-4-06',8,'tip','tiền boa; lời khuyên, mẹo; đầu, chóp','noun','[{"en":"We left a generous tip because the service was excellent.","vi":"Chúng tôi để lại tiền boa hậu hĩnh vì phục vụ rất tốt."},{"en":"Can you give me some tips for my first job interview?","vi":"Bạn có thể cho tôi vài lời khuyên cho buổi phỏng vấn xin việc đầu tiên không?"},{"en":"I burned the tip of my tongue on the hot soup.","vi":"Tôi bị bỏng đầu lưỡi vì món súp nóng."}]','[{"phrase":"leave a tip"},{"phrase":"generous tip"},{"phrase":"useful tips"}]',NULL,'/tɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tip/tip__/tip__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1631,'ngsl-4-06',9,'discount','sự giảm giá; khoản chiết khấu','noun','[{"en":"Students get a ten percent discount at this bookstore.","vi":"Sinh viên được giảm giá mười phần trăm ở hiệu sách này."},{"en":"Is there a discount if we buy two tickets?","vi":"Nếu mua hai vé thì có được giảm giá không?"},{"en":"She bought the shoes at a big discount during the sale.","vi":"Cô ấy mua đôi giày với giá giảm mạnh trong đợt khuyến mãi."}]','[{"phrase":"get a discount"},{"phrase":"offer a discount"},{"phrase":"student discount"},{"phrase":"big discount"}]',NULL,'/ˈdɪskaʊnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disco/discount__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1632,'ngsl-4-06',10,'peak','đỉnh (núi); đỉnh điểm, cao điểm','noun','[{"en":"We finally reached the peak just before sunset.","vi":"Cuối cùng chúng tôi cũng lên tới đỉnh núi ngay trước hoàng hôn."},{"en":"The heat was at its peak around two in the afternoon.","vi":"Cái nóng lên đến đỉnh điểm vào khoảng hai giờ chiều."},{"en":"She was at the peak of her career in her forties.","vi":"Bà ấy ở đỉnh cao sự nghiệp khi ngoài bốn mươi tuổi."}]','[{"phrase":"at its peak"},{"phrase":"mountain peak"},{"phrase":"peak hours"},{"phrase":"peak season"}]',NULL,'/piːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pea/peak_/peak__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1633,'ngsl-4-06',11,'chairman','chủ tịch','noun','[{"en":"The chairman opened the meeting with a short speech.","vi":"Chủ tịch khai mạc cuộc họp bằng một bài phát biểu ngắn."},{"en":"He was elected chairman of the club last year.","vi":"Ông ấy được bầu làm chủ tịch câu lạc bộ vào năm ngoái."},{"en":"My uncle has been chairman of the company for ten years.","vi":"Chú tôi đã làm chủ tịch công ty được mười năm."}]','[{"phrase":"company chairman"},{"phrase":"elected chairman"},{"phrase":"chairman of the board"}]','số nhiều: chairmen','/ˈtʃermən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chair/chairman__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1634,'ngsl-4-06',12,'proportion','tỷ lệ; phần','noun','[{"en":"A large proportion of our customers are young people.","vi":"Một phần lớn khách hàng của chúng tôi là người trẻ."},{"en":"The proportion of women in the company has increased.","vi":"Tỷ lệ phụ nữ trong công ty đã tăng lên."},{"en":"Mix the flour and water in the right proportions.","vi":"Trộn bột và nước theo đúng tỷ lệ."}]','[{"phrase":"large proportion"},{"phrase":"high proportion"},{"phrase":"in proportion to"}]',NULL,'/prəˈpɔːrʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/proportion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1635,'ngsl-4-06',13,'ear','tai','noun','[{"en":"She whispered something in my ear during the movie.","vi":"Cô ấy thì thầm gì đó vào tai tôi trong lúc xem phim."},{"en":"The loud music at the concert hurt my ears.","vi":"Tiếng nhạc lớn ở buổi hòa nhạc làm tôi đau tai."},{"en":"My daughter wants to get her ears pierced for her birthday.","vi":"Con gái tôi muốn đi bấm lỗ tai nhân dịp sinh nhật."}]','[{"phrase":"whisper in someone''s ear"},{"phrase":"ear infection"},{"phrase":"pierced ears"}]',NULL,'/ɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/ear__/ear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1636,'ngsl-4-06',14,'disappear','biến mất; mất tích','verb','[{"en":"The sun slowly disappeared behind the dark clouds.","vi":"Mặt trời từ từ biến mất sau những đám mây đen."},{"en":"My keys seem to disappear every time I''m in a hurry.","vi":"Chìa khóa của tôi dường như biến mất mỗi khi tôi vội."},{"en":"Many small shops have disappeared from this street.","vi":"Nhiều cửa hàng nhỏ đã biến mất khỏi con phố này."}]','[{"phrase":"disappear completely"},{"phrase":"suddenly disappear"},{"phrase":"disappear from view"}]',NULL,'/ˌdɪsəˈpɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disap/disappear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1637,'ngsl-4-06',15,'shout','hét, la to; quát','verb','[{"en":"Please don''t shout, because the baby is sleeping.","vi":"Làm ơn đừng hét, em bé đang ngủ."},{"en":"He shouted at his brother for breaking his phone.","vi":"Anh ấy quát em trai vì làm vỡ điện thoại của mình."},{"en":"We had to shout to be heard over the music.","vi":"Chúng tôi phải hét to mới át được tiếng nhạc."}]','[{"phrase":"shout at someone"},{"phrase":"shout for help"},{"phrase":"shout loudly"}]',NULL,'/ʃaʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shout/shout__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1638,'ngsl-4-06',16,'yard','sân (nhà); thước Anh (≈ 0,9 m)','noun','[{"en":"The kids are playing soccer in the yard.","vi":"Bọn trẻ đang chơi bóng đá ngoài sân."},{"en":"We have a small yard behind our house.","vi":"Nhà chúng tôi có một khoảng sân nhỏ phía sau."},{"en":"The bus stop is only a hundred yards from here.","vi":"Trạm xe buýt chỉ cách đây một trăm thước Anh."}]','[{"phrase":"front yard"},{"phrase":"back yard"},{"phrase":"a few yards"}]',NULL,'/jɑːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yar/yard_/yard__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1639,'ngsl-4-06',17,'constant','liên tục, không ngừng; không đổi','adjective','[{"en":"The constant noise from the street kept me awake.","vi":"Tiếng ồn liên tục ngoài đường khiến tôi không ngủ được."},{"en":"Young babies need constant care and attention from their parents.","vi":"Trẻ sơ sinh cần được cha mẹ chăm sóc và quan tâm liên tục."},{"en":"Keep the oven at a constant temperature while baking.","vi":"Giữ lò ở nhiệt độ không đổi trong khi nướng bánh."}]','[{"phrase":"constant noise"},{"phrase":"constant attention"},{"phrase":"constant temperature"}]',NULL,'/ˈkɑːnstənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1640,'ngsl-4-06',18,'significantly','đáng kể','adverb','[{"en":"Prices have risen significantly over the past year.","vi":"Giá cả đã tăng đáng kể trong năm qua."},{"en":"Regular exercise can significantly improve your sleep.","vi":"Tập thể dục đều đặn có thể cải thiện đáng kể giấc ngủ của bạn."},{"en":"This phone is significantly cheaper than the one I bought.","vi":"Chiếc điện thoại này rẻ hơn đáng kể so với chiếc tôi đã mua."}]','[{"phrase":"increase significantly"},{"phrase":"significantly improve"},{"phrase":"significantly different"}]',NULL,'/sɪɡˈnɪfɪkəntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significantly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1641,'ngsl-4-06',19,'hill','đồi; dốc','noun','[{"en":"Our house is at the top of a steep hill.","vi":"Nhà chúng tôi nằm trên đỉnh một con dốc cao."},{"en":"We walked up the hill to watch the sunrise.","vi":"Chúng tôi đi bộ lên đồi để ngắm bình minh."},{"en":"The village is surrounded by green hills and rice fields.","vi":"Ngôi làng được bao quanh bởi những ngọn đồi xanh và cánh đồng lúa."}]','[{"phrase":"steep hill"},{"phrase":"top of the hill"},{"phrase":"up the hill"}]',NULL,'/hɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hil/hill_/hill__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1642,'ngsl-4-06',20,'considerable','đáng kể, khá lớn','adjective','[{"en":"Learning a new language takes a considerable amount of time.","vi":"Học một ngôn ngữ mới cần một lượng thời gian đáng kể."},{"en":"The storm caused considerable damage to homes along the coast.","vi":"Cơn bão gây thiệt hại đáng kể cho nhà cửa dọc bờ biển."},{"en":"She has considerable experience in teaching young children.","vi":"Cô ấy có khá nhiều kinh nghiệm dạy trẻ nhỏ."}]','[{"phrase":"considerable amount"},{"phrase":"considerable damage"},{"phrase":"considerable experience"}]',NULL,'/kənˈsɪdərəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsiderable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1643,'ngsl-4-06',21,'instruction','hướng dẫn; chỉ dẫn, chỉ thị','noun','[{"en":"Read the instructions carefully before you start the exam.","vi":"Hãy đọc kỹ hướng dẫn trước khi bắt đầu làm bài thi."},{"en":"If you follow the instructions, the machine is easy to use.","vi":"Nếu làm theo hướng dẫn thì chiếc máy này rất dễ dùng."},{"en":"The manager gave clear instructions to all new staff.","vi":"Quản lý đã đưa ra chỉ dẫn rõ ràng cho tất cả nhân viên mới."}]','[{"phrase":"follow instructions"},{"phrase":"clear instructions"},{"phrase":"give instructions"}]','thường dùng số nhiều: instructions','/ɪnˈstrʌkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/instr/instruction__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1644,'ngsl-4-06',22,'intelligence','trí thông minh; tình báo','noun','[{"en":"Dolphins are known for their high intelligence.","vi":"Cá heo nổi tiếng là có trí thông minh cao."},{"en":"It takes intelligence and patience to solve this puzzle.","vi":"Cần có trí thông minh và sự kiên nhẫn để giải câu đố này."},{"en":"He worked for military intelligence before becoming a teacher.","vi":"Ông ấy từng làm cho cơ quan tình báo quân đội trước khi trở thành giáo viên."}]','[{"phrase":"high intelligence"},{"phrase":"artificial intelligence"},{"phrase":"military intelligence"}]',NULL,'/ɪnˈtelɪdʒəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intel/intelligence__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1645,'ngsl-4-06',23,'ideal','lý tưởng','adjective','[{"en":"This quiet beach is ideal for a family vacation.","vi":"Bãi biển yên tĩnh này rất lý tưởng cho kỳ nghỉ gia đình."},{"en":"In an ideal world, everyone would have a job they love.","vi":"Trong một thế giới lý tưởng, ai cũng sẽ có công việc mình yêu thích."},{"en":"The weather was ideal for a long bike ride.","vi":"Thời tiết rất lý tưởng cho một chuyến đạp xe dài."}]','[{"phrase":"ideal for"},{"phrase":"ideal world"},{"phrase":"ideal place"},{"phrase":"ideal solution"}]',NULL,'/aɪˈdiːəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ideal/ideal__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1646,'ngsl-4-06',24,'folk','người, dân; dân gian','noun','[{"en":"Country folk are often friendlier than people in big cities.","vi":"Người dân quê thường thân thiện hơn người ở thành phố lớn."},{"en":"My folks live in a small town near the coast.","vi":"Bố mẹ tôi sống ở một thị trấn nhỏ gần biển."},{"en":"She loves listening to traditional folk songs from her hometown.","vi":"Cô ấy thích nghe những bài dân ca truyền thống của quê mình."}]','[{"phrase":"folk music"},{"phrase":"folk song"},{"phrase":"country folk"},{"phrase":"old folks"}]','folks (thân mật): mọi người; bố mẹ','/fəʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fol/folk_/folk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1647,'ngsl-4-06',25,'surely','chắc chắn; chắc hẳn, lẽ nào','adverb','[{"en":"Surely you don''t expect me to finish this by tomorrow?","vi":"Lẽ nào bạn muốn tôi làm xong việc này trước ngày mai sao?"},{"en":"The work is going slowly but surely, so we''ll finish soon.","vi":"Công việc tiến triển chậm mà chắc, nên chúng tôi sẽ sớm xong."},{"en":"Surely someone in the office knows how to fix this printer.","vi":"Chắc hẳn ai đó trong văn phòng biết cách sửa cái máy in này."}]','[{"phrase":"slowly but surely"},{"phrase":"surely not"}]',NULL,'/ˈʃʊrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surel/surely__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1648,'ngsl-4-06',26,'guard','người bảo vệ, lính gác; sự canh gác','noun','[{"en":"A security guard checked our bags at the entrance.","vi":"Một nhân viên bảo vệ đã kiểm tra túi của chúng tôi ở lối vào."},{"en":"The guards at the gate asked to see our passports.","vi":"Lính gác ở cổng yêu cầu xem hộ chiếu của chúng tôi."},{"en":"Two soldiers stood guard outside the old palace.","vi":"Hai người lính đứng canh gác bên ngoài cung điện cũ."}]','[{"phrase":"security guard"},{"phrase":"stand guard"},{"phrase":"border guard"}]','(v) canh gác, bảo vệ','/ɡɑːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gua/guard/guard__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1649,'ngsl-4-06',27,'cat','con mèo','noun','[{"en":"Our cat sleeps on the sofa most of the day.","vi":"Con mèo nhà tôi ngủ trên ghế sofa gần như cả ngày."},{"en":"She feeds the stray cats in her neighborhood every evening.","vi":"Tối nào cô ấy cũng cho những con mèo hoang trong khu phố ăn."},{"en":"Do you prefer cats or dogs as pets?","vi":"Bạn thích nuôi mèo hay chó hơn?"}]','[{"phrase":"pet cat"},{"phrase":"stray cat"},{"phrase":"feed the cat"}]',NULL,'/kæt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/cat__/cat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1650,'ngsl-4-06',28,'somewhat','hơi, có phần; phần nào','adverb','[{"en":"I was somewhat surprised by her answer.","vi":"Tôi hơi ngạc nhiên trước câu trả lời của cô ấy."},{"en":"The situation has improved somewhat since last month.","vi":"Tình hình đã cải thiện phần nào kể từ tháng trước."},{"en":"The movie was somewhat longer than I had expected.","vi":"Bộ phim dài hơn tôi nghĩ một chút."}]','[{"phrase":"somewhat surprised"},{"phrase":"somewhat different"},{"phrase":"improve somewhat"}]',NULL,'/ˈsʌmwʌt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somew/somewhat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1651,'ngsl-4-06',29,'kiss','hôn','verb','[{"en":"She kissed her son goodbye at the school gate.","vi":"Cô ấy hôn tạm biệt con trai ở cổng trường."},{"en":"My grandmother always kisses me on the cheek.","vi":"Bà tôi lúc nào cũng hôn lên má tôi."},{"en":"The couple kissed when the clock struck midnight.","vi":"Cặp đôi hôn nhau khi đồng hồ điểm nửa đêm."}]','[{"phrase":"kiss goodbye"},{"phrase":"kiss someone on the cheek"},{"phrase":"kiss each other"}]','(n) nụ hôn','/kɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kis/kiss_/kiss__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1652,'ngsl-4-06',30,'presentation','bài thuyết trình; sự trình bày','noun','[{"en":"I have to give a presentation to the whole class tomorrow.","vi":"Ngày mai tôi phải thuyết trình trước cả lớp."},{"en":"Her presentation on healthy eating was clear and interesting.","vi":"Bài thuyết trình của cô ấy về ăn uống lành mạnh rất rõ ràng và thú vị."},{"en":"At a restaurant, the presentation of the food matters too.","vi":"Ở nhà hàng, cách trình bày món ăn cũng quan trọng."}]','[{"phrase":"give a presentation"},{"phrase":"make a presentation"},{"phrase":"presentation skills"}]',NULL,'/ˌpriːznˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/presentation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1653,'ngsl-4-07',1,'joint','chung; phối hợp','adjective','[{"en":"My wife and I opened a joint bank account last year.","vi":"Vợ tôi và tôi đã mở một tài khoản ngân hàng chung vào năm ngoái."},{"en":"The two schools organized a joint event for parents.","vi":"Hai trường đã tổ chức một sự kiện chung dành cho phụ huynh."},{"en":"The report was a joint effort by the whole team.","vi":"Bản báo cáo là nỗ lực chung của cả nhóm."}]','[{"phrase":"joint account"},{"phrase":"joint effort"},{"phrase":"joint decision"},{"phrase":"joint venture"}]',NULL,'/dʒɔɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/joi/joint/joint__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1654,'ngsl-4-07',2,'compete','cạnh tranh; thi đấu','verb','[{"en":"Small shops find it hard to compete with big supermarkets.","vi":"Các cửa hàng nhỏ thấy khó cạnh tranh với những siêu thị lớn."},{"en":"Over fifty students competed for just three scholarships.","vi":"Hơn năm mươi sinh viên cạnh tranh để giành chỉ ba suất học bổng."},{"en":"My brother will compete in the city swimming race next month.","vi":"Anh trai tôi sẽ thi đấu trong cuộc thi bơi của thành phố vào tháng tới."}]','[{"phrase":"compete with"},{"phrase":"compete for"},{"phrase":"compete in"},{"phrase":"compete against"}]','compete with/against sb; compete for sth','/kəmˈpiːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/compete__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1655,'ngsl-4-07',3,'poll','cuộc thăm dò ý kiến','noun','[{"en":"A recent poll shows that most people want more parks.","vi":"Một cuộc thăm dò gần đây cho thấy phần lớn mọi người muốn có thêm công viên."},{"en":"We ran a quick poll to choose the date for the party.","vi":"Chúng tôi đã làm một cuộc thăm dò nhanh để chọn ngày tổ chức bữa tiệc."},{"en":"According to the poll, young people read fewer books than before.","vi":"Theo cuộc thăm dò, người trẻ đọc ít sách hơn trước."}]','[{"phrase":"opinion poll"},{"phrase":"recent poll"},{"phrase":"conduct a poll"},{"phrase":"according to the poll"}]',NULL,'/pəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/poll_/poll__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1656,'ngsl-4-07',4,'weak','yếu; kém','adjective','[{"en":"I still felt weak after being sick for a week.","vi":"Tôi vẫn thấy yếu sau khi bị ốm một tuần."},{"en":"Math has always been my weakest subject at school.","vi":"Toán luôn là môn yếu nhất của tôi ở trường."},{"en":"The signal is too weak to make a video call here.","vi":"Ở đây tín hiệu quá yếu để gọi video."}]','[{"phrase":"feel weak"},{"phrase":"weak point"},{"phrase":"weak signal"}]',NULL,'/wiːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weak_/weak__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1657,'ngsl-4-07',5,'faith','niềm tin; sự tin tưởng','noun','[{"en":"I have complete faith in my doctor''s advice.","vi":"Tôi hoàn toàn tin tưởng lời khuyên của bác sĩ."},{"en":"Don''t lose faith; you will find a job soon.","vi":"Đừng mất niềm tin; bạn sẽ sớm tìm được việc thôi."},{"en":"Her parents always had faith that she would succeed.","vi":"Bố mẹ cô ấy luôn tin rằng cô ấy sẽ thành công."}]','[{"phrase":"have faith in"},{"phrase":"lose faith"},{"phrase":"complete faith"}]','have faith in sb/sth: tin tưởng vào ai/điều gì','/feɪθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/faith/faith__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1658,'ngsl-4-07',6,'reduction','sự giảm; mức giảm','noun','[{"en":"The new rules led to a big reduction in traffic accidents.","vi":"Các quy định mới đã giúp giảm mạnh số vụ tai nạn giao thông."},{"en":"Customers can get a ten percent price reduction this week.","vi":"Tuần này khách hàng được giảm giá mười phần trăm."},{"en":"We are hoping for a reduction in our electricity bill.","vi":"Chúng tôi đang hy vọng hóa đơn tiền điện sẽ giảm."}]','[{"phrase":"reduction in"},{"phrase":"price reduction"},{"phrase":"significant reduction"},{"phrase":"cost reduction"}]','a reduction in sth: sự giảm về cái gì','/rɪˈdʌkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/red/reduc/reduction__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1659,'ngsl-4-07',7,'reserve','đặt trước; dành riêng','verb','[{"en":"I''ve reserved a table for four at seven o''clock.","vi":"Tôi đã đặt trước một bàn cho bốn người lúc bảy giờ."},{"en":"These front seats are reserved for elderly passengers.","vi":"Những ghế phía trước này dành riêng cho hành khách lớn tuổi."},{"en":"You should reserve your hotel room early during the holidays.","vi":"Bạn nên đặt phòng khách sạn sớm vào dịp lễ."}]','[{"phrase":"reserve a table"},{"phrase":"reserve a room"},{"phrase":"reserved for"},{"phrase":"reserve the right"}]',NULL,'/rɪˈzɜːrv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/reser/reserve__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1660,'ngsl-4-07',8,'complaint','lời phàn nàn; đơn khiếu nại','noun','[{"en":"The hotel received many complaints about the noisy air conditioning.","vi":"Khách sạn nhận được nhiều lời phàn nàn về máy lạnh ồn ào."},{"en":"I would like to make a complaint about the service.","vi":"Tôi muốn khiếu nại về chất lượng phục vụ."},{"en":"If you have any complaints, please call our customer service team.","vi":"Nếu bạn có bất kỳ phàn nàn nào, vui lòng gọi cho bộ phận chăm sóc khách hàng."}]','[{"phrase":"make a complaint"},{"phrase":"complaints about"},{"phrase":"receive a complaint"},{"phrase":"file a complaint"}]',NULL,'/kəmˈpleɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complaint__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1661,'ngsl-4-07',9,'bore','làm chán','verb','[{"en":"I won''t bore you with all the details of my trip.","vi":"Mình sẽ không làm bạn chán với đủ thứ chi tiết về chuyến đi đâu."},{"en":"Long meetings always bore me to death.","vi":"Những cuộc họp dài lúc nào cũng làm tôi chán muốn chết."},{"en":"Did the movie bore the kids, or did they enjoy it?","vi":"Bộ phim có làm bọn trẻ thấy chán không, hay chúng thích nó?"}]','[{"phrase":"bore you with"},{"phrase":"bore me to death"},{"phrase":"bore someone to tears"}]','bored (thấy chán) ≠ boring (gây chán)','/bɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bor/bore_/bore__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1662,'ngsl-4-07',10,'mission','nhiệm vụ; sứ mệnh','noun','[{"en":"The rescue mission lasted two days in heavy rain.","vi":"Nhiệm vụ cứu hộ kéo dài hai ngày dưới mưa lớn."},{"en":"Our company''s mission is to make healthy food affordable.","vi":"Sứ mệnh của công ty chúng tôi là làm cho thực phẩm lành mạnh có giá phải chăng."},{"en":"My mission today is to clean the whole garage.","vi":"Nhiệm vụ của tôi hôm nay là dọn sạch cả nhà để xe."}]','[{"phrase":"rescue mission"},{"phrase":"mission statement"},{"phrase":"on a mission"},{"phrase":"complete a mission"}]',NULL,'/ˈmɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mis/missi/mission__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1663,'ngsl-4-07',11,'somehow','bằng cách nào đó; không hiểu sao','adverb','[{"en":"She somehow managed to finish the project on time.","vi":"Bằng cách nào đó cô ấy đã xoay xở hoàn thành dự án đúng hạn."},{"en":"I left early, but somehow I still missed the bus.","vi":"Tôi đã đi sớm, nhưng không hiểu sao vẫn lỡ chuyến xe buýt."},{"en":"The house felt different somehow after the kids moved out.","vi":"Không hiểu sao căn nhà có cảm giác khác đi sau khi bọn trẻ dọn ra ở riêng."}]','[{"phrase":"somehow managed to"},{"phrase":"but somehow"},{"phrase":"somehow or other"}]',NULL,'/ˈsʌmhaʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/someh/somehow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1664,'ngsl-4-07',12,'tone','giọng điệu; tông màu','noun','[{"en":"I didn''t like the angry tone of his email.","vi":"Tôi không thích giọng điệu giận dữ trong email của anh ấy."},{"en":"Please don''t use that tone of voice with me.","vi":"Làm ơn đừng nói với tôi bằng giọng điệu đó."},{"en":"We painted the bedroom in soft, warm tones.","vi":"Chúng tôi sơn phòng ngủ bằng những tông màu ấm và dịu."}]','[{"phrase":"tone of voice"},{"phrase":"angry tone"},{"phrase":"friendly tone"},{"phrase":"set the tone"}]',NULL,'/təʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ton/tone_/tone__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1665,'ngsl-4-07',13,'neighborhood','khu phố; khu dân cư','noun','[{"en":"We live in a quiet neighborhood near the river.","vi":"Chúng tôi sống ở một khu phố yên tĩnh gần con sông."},{"en":"There are three good restaurants in my neighborhood.","vi":"Khu tôi ở có ba nhà hàng ngon."},{"en":"The whole neighborhood came out to help after the storm.","vi":"Cả khu phố đã ra giúp đỡ sau cơn bão."}]','[{"phrase":"quiet neighborhood"},{"phrase":"in my neighborhood"},{"phrase":"safe neighborhood"},{"phrase":"whole neighborhood"}]','Anh: neighbourhood · Mỹ: neighborhood','/ˈneɪbərˌhʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1666,'ngsl-4-07',14,'passenger','hành khách','noun','[{"en":"All passengers must wear seat belts during the flight.","vi":"Tất cả hành khách phải thắt dây an toàn trong suốt chuyến bay."},{"en":"The bus was full, so some passengers had to stand.","vi":"Xe buýt đã đầy nên một số hành khách phải đứng."},{"en":"My sister sat in the passenger seat and read the map.","vi":"Chị tôi ngồi ở ghế phụ và xem bản đồ."}]','[{"phrase":"passenger seat"},{"phrase":"bus passengers"},{"phrase":"passenger train"},{"phrase":"airline passengers"}]',NULL,'/ˈpæsɪndʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passe/passenger__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1667,'ngsl-4-07',15,'justice','công lý; sự công bằng','noun','[{"en":"The court''s decision was a victory for justice.","vi":"Phán quyết của tòa án là một chiến thắng của công lý."},{"en":"Children have a strong sense of justice and hate unfair rules.","vi":"Trẻ em có ý thức mạnh mẽ về sự công bằng và ghét những quy định bất công."},{"en":"The family finally got justice after a long legal fight.","vi":"Cuối cùng gia đình ấy cũng đòi được công lý sau một cuộc chiến pháp lý dài."}]','[{"phrase":"sense of justice"},{"phrase":"social justice"},{"phrase":"get justice"},{"phrase":"bring to justice"}]','không đếm được','/ˈdʒʌstɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jus/justi/justice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1668,'ngsl-4-07',16,'phase','giai đoạn','noun','[{"en":"The first phase of the project will finish in March.","vi":"Giai đoạn đầu của dự án sẽ hoàn thành vào tháng Ba."},{"en":"Many teenagers go through a phase of wanting to be alone.","vi":"Nhiều thanh thiếu niên trải qua một giai đoạn chỉ muốn ở một mình."},{"en":"Our city is entering a new phase of development.","vi":"Thành phố của chúng tôi đang bước vào một giai đoạn phát triển mới."}]','[{"phrase":"first phase"},{"phrase":"new phase"},{"phrase":"final phase"},{"phrase":"go through a phase"}]',NULL,'/feɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pha/phase/phase__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1669,'ngsl-4-07',17,'thin','mỏng; gầy','adjective','[{"en":"Cut the tomatoes into thin slices for the sandwich.","vi":"Hãy cắt cà chua thành những lát mỏng để làm bánh mì kẹp."},{"en":"He looked very thin after his long illness.","vi":"Anh ấy trông rất gầy sau trận ốm dài."},{"en":"This jacket is too thin for winter in the mountains.","vi":"Chiếc áo khoác này quá mỏng để mặc mùa đông trên núi."}]','[{"phrase":"thin slices"},{"phrase":"thin layer"},{"phrase":"tall and thin"},{"phrase":"very thin"}]',NULL,'/θɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thin_/thin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1670,'ngsl-4-07',18,'rush','vội vàng; lao đi','verb','[{"en":"Don''t rush; we still have plenty of time.","vi":"Đừng vội; chúng ta vẫn còn nhiều thời gian."},{"en":"She rushed to the hospital when she heard the news.","vi":"Cô ấy vội vã chạy đến bệnh viện khi nghe tin."},{"en":"I had to rush my lunch to get back to work.","vi":"Tôi phải ăn trưa vội vàng để kịp quay lại làm việc."}]','[{"phrase":"rush to"},{"phrase":"rush into"},{"phrase":"rush out"},{"phrase":"rush hour"}]',NULL,'/rʌʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rus/rush_/rush__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1671,'ngsl-4-07',19,'formal','trang trọng; chính thức','adjective','[{"en":"You should wear formal clothes to the wedding dinner.","vi":"Bạn nên mặc trang phục trang trọng khi đến dự tiệc cưới."},{"en":"Use formal language when you write to your manager.","vi":"Hãy dùng ngôn ngữ trang trọng khi viết thư cho quản lý của bạn."},{"en":"We haven''t received a formal offer from the company yet.","vi":"Chúng tôi vẫn chưa nhận được lời mời làm việc chính thức từ công ty."}]','[{"phrase":"formal clothes"},{"phrase":"formal language"},{"phrase":"formal offer"},{"phrase":"formal education"}]','formal ≠ informal (thân mật, không trang trọng)','/ˈfɔːrml/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/formal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1672,'ngsl-4-07',20,'religion','tôn giáo','noun','[{"en":"The course teaches students about different cultures and religions.","vi":"Khóa học dạy sinh viên về các nền văn hóa và tôn giáo khác nhau."},{"en":"The role of religion in daily life differs from country to country.","vi":"Vai trò của tôn giáo trong đời sống hằng ngày khác nhau giữa các quốc gia."},{"en":"At work, we try not to talk about politics or religion.","vi":"Ở chỗ làm, chúng tôi cố không nói chuyện chính trị hay tôn giáo."}]','[{"phrase":"role of religion"},{"phrase":"freedom of religion"},{"phrase":"world religions"}]',NULL,'/rɪˈlɪdʒən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relig/religion__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1673,'ngsl-4-07',21,'employer','chủ lao động; nhà tuyển dụng','noun','[{"en":"My employer pays for my English classes after work.","vi":"Công ty tôi làm trả tiền cho các lớp tiếng Anh sau giờ làm của tôi."},{"en":"Employers often look for people with good communication skills.","vi":"Nhà tuyển dụng thường tìm những người có kỹ năng giao tiếp tốt."},{"en":"The hospital is the largest employer in our town.","vi":"Bệnh viện là nơi sử dụng nhiều lao động nhất ở thị trấn chúng tôi."}]','[{"phrase":"largest employer"},{"phrase":"former employer"},{"phrase":"potential employer"}]','employer (chủ) ≠ employee (nhân viên)','/ɪmˈplɔɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/emplo/employer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1674,'ngsl-4-07',22,'reject','từ chối; bác bỏ','verb','[{"en":"The bank rejected my application for a loan last month.","vi":"Tháng trước ngân hàng đã từ chối đơn xin vay của tôi."},{"en":"She rejected his offer to drive her home.","vi":"Cô ấy từ chối lời đề nghị chở cô về nhà của anh ta."},{"en":"The manager rejected the idea because it cost too much.","vi":"Quản lý bác bỏ ý tưởng đó vì nó quá tốn kém."}]','[{"phrase":"reject an offer"},{"phrase":"reject an idea"},{"phrase":"reject an application"},{"phrase":"reject a proposal"}]',NULL,'/rɪˈdʒekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rej/rejec/reject__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1675,'ngsl-4-07',23,'latter','cái sau; người sau','noun','[{"en":"We could take the bus or the train, but I prefer the latter.","vi":"Chúng ta có thể đi xe buýt hoặc tàu hỏa, nhưng tôi thích đi tàu hơn."},{"en":"My uncle and aunt both applied, but only the latter got the job.","vi":"Chú và cô tôi đều nộp đơn, nhưng chỉ có cô tôi được nhận."},{"en":"Between cats and dogs, most children in my class choose the latter.","vi":"Giữa mèo và chó, hầu hết trẻ em trong lớp tôi chọn chó."}]','[{"phrase":"the latter"},{"phrase":"the former and the latter"},{"phrase":"the latter half"}]','the former (cái trước) ≠ the latter (cái sau)','/ˈlætər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lat/latte/latter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1676,'ngsl-4-07',24,'plate','cái đĩa','noun','[{"en":"Could you put the plates on the table, please?","vi":"Bạn đặt đĩa lên bàn giúp mình được không?"},{"en":"I''d like a plate of fried rice, please.","vi":"Cho tôi một đĩa cơm chiên nhé."},{"en":"Please wash your plate when you finish eating.","vi":"Ăn xong thì vui lòng rửa đĩa của bạn."}]','[{"phrase":"a plate of"},{"phrase":"dinner plate"},{"phrase":"paper plate"},{"phrase":"clean plate"}]',NULL,'/pleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plate/plate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1677,'ngsl-4-07',25,'ban','cấm','verb','[{"en":"Smoking is banned in all restaurants in the city.","vi":"Hút thuốc bị cấm ở tất cả nhà hàng trong thành phố."},{"en":"The school banned phones in classrooms last year.","vi":"Năm ngoái nhà trường đã cấm dùng điện thoại trong lớp học."},{"en":"He was banned from driving for six months.","vi":"Anh ta bị cấm lái xe trong sáu tháng."}]','[{"phrase":"banned from"},{"phrase":"ban smoking"},{"phrase":"completely ban"}]','ban – banned – banned; be banned from doing sth','/bæn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ban/ban__/ban__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1678,'ngsl-4-07',26,'steal','ăn cắp; lấy trộm','verb','[{"en":"Someone stole my bike from outside the library.","vi":"Có ai đó đã lấy trộm xe đạp của tôi ở bên ngoài thư viện."},{"en":"Keep your bag close because thieves often steal from tourists.","vi":"Hãy giữ túi sát người vì kẻ trộm thường ăn cắp đồ của khách du lịch."},{"en":"He was caught stealing money from the shop.","vi":"Anh ta bị bắt quả tang ăn cắp tiền của cửa hàng."}]','[{"phrase":"steal money"},{"phrase":"steal from"},{"phrase":"steal a car"}]','steal – stole – stolen','/stiːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/steal/steal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1679,'ngsl-4-07',27,'protest','cuộc biểu tình; sự phản đối','noun','[{"en":"Parents held a protest outside the school about the new fees.","vi":"Phụ huynh đã tổ chức một cuộc biểu tình trước cổng trường để phản đối khoản phí mới."},{"en":"Several customers left the shop in protest.","vi":"Vài khách hàng đã bỏ ra khỏi cửa hàng để phản đối."},{"en":"The plan went ahead despite strong protests from local residents.","vi":"Kế hoạch vẫn được tiến hành bất chấp sự phản đối mạnh mẽ của người dân địa phương."}]','[{"phrase":"in protest"},{"phrase":"hold a protest"},{"phrase":"strong protest"},{"phrase":"protest against"}]',NULL,'/ˈprəʊtest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protest__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1680,'ngsl-4-07',28,'index','bảng tra cứu; chỉ số','noun','[{"en":"Check the index at the back of the book for that topic.","vi":"Hãy xem bảng tra cứu ở cuối sách để tìm chủ đề đó."},{"en":"The price index rose by two percent last month.","vi":"Chỉ số giá đã tăng hai phần trăm vào tháng trước."},{"en":"The book has a detailed index, so finding recipes is easy.","vi":"Cuốn sách có bảng tra cứu chi tiết nên tìm công thức nấu ăn rất dễ."}]','[{"phrase":"price index"},{"phrase":"detailed index"},{"phrase":"index card"}]','số nhiều: indexes hoặc indices','/ˈɪndeks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/index/index__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1681,'ngsl-4-07',29,'sad','buồn','adjective','[{"en":"I felt sad when my best friend moved away.","vi":"Tôi thấy buồn khi bạn thân của tôi chuyển đi nơi khác."},{"en":"It''s sad that the old cinema is closing down.","vi":"Thật đáng buồn khi rạp chiếu phim cũ sắp đóng cửa."},{"en":"She watched a sad movie and cried at the end.","vi":"Cô ấy xem một bộ phim buồn và khóc ở đoạn cuối."}]','[{"phrase":"feel sad"},{"phrase":"sad movie"},{"phrase":"sad news"},{"phrase":"look sad"}]',NULL,'/sæd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sad/sad__/sad__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1682,'ngsl-4-07',30,'frequently','thường xuyên','adverb','[{"en":"Buses run frequently between the airport and the city center.","vi":"Xe buýt chạy thường xuyên giữa sân bay và trung tâm thành phố."},{"en":"I frequently forget where I left my glasses.","vi":"Tôi thường xuyên quên mình để kính ở đâu."},{"en":"This is one of our most frequently asked questions.","vi":"Đây là một trong những câu hỏi thường gặp nhất của chúng tôi."}]','[{"phrase":"frequently asked questions"},{"phrase":"run frequently"},{"phrase":"frequently used"}]',NULL,'/ˈfriːkwəntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/frequ/frequently__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1683,'ngsl-4-08',1,'circle','hình tròn; vòng tròn; nhóm (bạn bè)','noun','[{"en":"The teacher asked the children to sit in a circle.","vi":"Cô giáo bảo các em ngồi thành vòng tròn."},{"en":"Draw a circle around the correct answer.","vi":"Hãy khoanh tròn đáp án đúng."},{"en":"She has a small circle of close friends.","vi":"Cô ấy có một nhóm nhỏ bạn thân."}]','[{"phrase":"draw a circle"},{"phrase":"sit in a circle"},{"phrase":"circle of friends"}]',NULL,'/ˈsɜːrkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cir/circl/circle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1684,'ngsl-4-08',2,'helpful','hữu ích; sẵn lòng giúp đỡ','adjective','[{"en":"Thanks for your advice, it was really helpful.","vi":"Cảm ơn lời khuyên của bạn, nó thật sự rất hữu ích."},{"en":"The staff at the hotel were friendly and helpful.","vi":"Nhân viên khách sạn thân thiện và nhiệt tình giúp đỡ."},{"en":"It might be helpful to write down your questions before the meeting.","vi":"Viết ra các câu hỏi trước buổi họp có thể sẽ hữu ích."}]','[{"phrase":"very helpful"},{"phrase":"helpful advice"},{"phrase":"helpful staff"}]',NULL,'/ˈhelpfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/helpf/helpful__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1685,'ngsl-4-08',3,'command','mệnh lệnh; lệnh (máy tính); sự thành thạo','noun','[{"en":"The soldiers waited for the command to move forward.","vi":"Những người lính chờ lệnh tiến lên."},{"en":"Type this command to restart the program.","vi":"Hãy gõ lệnh này để khởi động lại chương trình."},{"en":"After two years abroad, she has a good command of English.","vi":"Sau hai năm ở nước ngoài, cô ấy sử dụng tiếng Anh thành thạo."}]','[{"phrase":"give a command"},{"phrase":"follow a command"},{"phrase":"command of English"}]','have a good command of + ngôn ngữ = thành thạo','/kəˈmænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comma/command__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1686,'ngsl-4-08',4,'attractive','hấp dẫn; thu hút; ưa nhìn','adjective','[{"en":"He thinks she is the most attractive woman in the room.","vi":"Anh ấy nghĩ cô ấy là người phụ nữ cuốn hút nhất trong phòng."},{"en":"The company offered me a very attractive salary.","vi":"Công ty đã đề nghị cho tôi một mức lương rất hấp dẫn."},{"en":"Low prices make the city attractive to young travelers.","vi":"Giá cả thấp khiến thành phố này hấp dẫn với du khách trẻ."}]','[{"phrase":"attractive offer"},{"phrase":"attractive to"},{"phrase":"highly attractive"},{"phrase":"physically attractive"}]',NULL,'/əˈtræktɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attra/attractive__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1687,'ngsl-4-08',5,'sick','ốm, bệnh; buồn nôn; chán ngấy','adjective','[{"en":"I can''t come to work today because I''m sick.","vi":"Hôm nay tôi không đi làm được vì tôi bị ốm."},{"en":"Reading in the car always makes me feel sick.","vi":"Đọc sách trên ô tô lúc nào cũng làm tôi buồn nôn."},{"en":"I''m sick of eating noodles every night.","vi":"Tôi chán ngấy việc tối nào cũng ăn mì rồi."}]','[{"phrase":"feel sick"},{"phrase":"get sick"},{"phrase":"sick of"},{"phrase":"call in sick"}]','be sick of sth = chán ngấy cái gì','/sɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sic/sick_/sick__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1688,'ngsl-4-08',6,'impression','ấn tượng; cảm tưởng','noun','[{"en":"Wear something smart to make a good first impression.","vi":"Hãy mặc gì đó lịch sự để tạo ấn tượng tốt ban đầu."},{"en":"I got the impression that he didn''t like the idea.","vi":"Tôi có cảm giác là anh ấy không thích ý tưởng đó."},{"en":"What was your first impression of the new office?","vi":"Ấn tượng đầu tiên của bạn về văn phòng mới là gì?"}]','[{"phrase":"make a good impression"},{"phrase":"first impression"},{"phrase":"get the impression"},{"phrase":"impression of"}]',NULL,'/ɪmˈpreʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impre/impression__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1689,'ngsl-4-08',7,'unable','không thể; không có khả năng','adjective','[{"en":"We were unable to find a hotel near the station.","vi":"Chúng tôi không thể tìm được khách sạn nào gần nhà ga."},{"en":"She was unable to sleep because of the noise.","vi":"Cô ấy không ngủ được vì tiếng ồn."},{"en":"I''m sorry, but the manager is unable to see you today.","vi":"Xin lỗi, hôm nay quản lý không thể gặp bạn được."}]','[{"phrase":"unable to do"},{"phrase":"unable to find"},{"phrase":"unable to attend"}]','be unable to + V nguyên mẫu','/ʌnˈeɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/una/unabl/unable__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1690,'ngsl-4-08',8,'joke','chuyện cười; trò đùa','noun','[{"en":"My dad told a joke and everyone laughed.","vi":"Bố tôi kể một chuyện cười và mọi người đều bật cười."},{"en":"Don''t be angry, it was only a joke.","vi":"Đừng giận, đó chỉ là một trò đùa thôi."},{"en":"I didn''t get the joke, so could you explain it?","vi":"Tôi không hiểu câu đùa, bạn giải thích được không?"}]','[{"phrase":"tell a joke"},{"phrase":"just a joke"},{"phrase":"get the joke"},{"phrase":"make a joke"}]',NULL,'/dʒəʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jok/joke_/joke__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1691,'ngsl-4-08',9,'sky','bầu trời','noun','[{"en":"There wasn''t a single cloud in the sky this morning.","vi":"Sáng nay trên bầu trời không có lấy một gợn mây."},{"en":"The sky turned dark just before the storm.","vi":"Bầu trời tối sầm lại ngay trước cơn bão."},{"en":"We lay on the grass and looked up at the night sky.","vi":"Chúng tôi nằm trên bãi cỏ và ngắm nhìn bầu trời đêm."}]','[{"phrase":"blue sky"},{"phrase":"clear sky"},{"phrase":"night sky"},{"phrase":"in the sky"}]',NULL,'/skaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sky/sky__/sky__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1692,'ngsl-4-08',10,'column','cột (trong bảng); cột trụ; chuyên mục (báo)','noun','[{"en":"Write the prices in the second column of the table.","vi":"Hãy ghi giá vào cột thứ hai của bảng."},{"en":"The old building has tall stone columns at the front.","vi":"Tòa nhà cũ có những cột đá cao ở mặt trước."},{"en":"She writes a weekly column about food for a local newspaper.","vi":"Cô ấy viết một chuyên mục ẩm thực hằng tuần cho một tờ báo địa phương."}]','[{"phrase":"first column"},{"phrase":"stone column"},{"phrase":"weekly column"},{"phrase":"newspaper column"}]',NULL,'/ˈkɑːləm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colum/column__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1693,'ngsl-4-08',11,'electronic','(thuộc) điện tử','adjective','[{"en":"Please turn off all electronic devices during the flight.","vi":"Vui lòng tắt tất cả thiết bị điện tử trong suốt chuyến bay."},{"en":"You can pay the bill by electronic transfer.","vi":"Bạn có thể thanh toán hóa đơn bằng chuyển khoản điện tử."},{"en":"The library now keeps most of its records in electronic form.","vi":"Thư viện hiện lưu phần lớn hồ sơ dưới dạng điện tử."}]','[{"phrase":"electronic device"},{"phrase":"electronic equipment"},{"phrase":"electronic form"}]','electronic (adj) ≠ electronics (n): ngành/đồ điện tử','/ɪˌlekˈtrɑːnɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/electronic__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1694,'ngsl-4-08',12,'impose','áp đặt; áp (thuế, phạt, lệnh cấm)','verb','[{"en":"The city has imposed a ban on smoking in parks.","vi":"Thành phố đã áp lệnh cấm hút thuốc trong công viên."},{"en":"Parents shouldn''t impose their own dreams on their children.","vi":"Cha mẹ không nên áp đặt ước mơ của mình lên con cái."},{"en":"The government plans to impose a new tax on sugary drinks.","vi":"Chính phủ dự định áp một loại thuế mới lên đồ uống có đường."}]','[{"phrase":"impose a ban"},{"phrase":"impose a tax"},{"phrase":"impose a fine"},{"phrase":"impose on"}]','impose sth on sb/sth','/ɪmˈpəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impos/impose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1695,'ngsl-4-08',13,'criminal','tội phạm; kẻ phạm tội','noun','[{"en":"The police are still looking for the criminals who robbed the bank.","vi":"Cảnh sát vẫn đang truy tìm những tên tội phạm đã cướp ngân hàng."},{"en":"He was treated like a criminal for a small mistake.","vi":"Anh ấy bị đối xử như tội phạm chỉ vì một lỗi nhỏ."},{"en":"Dangerous criminals are kept in this prison.","vi":"Những tội phạm nguy hiểm bị giam ở nhà tù này."}]','[{"phrase":"dangerous criminal"},{"phrase":"convicted criminal"},{"phrase":"catch a criminal"}]','Cũng là tính từ: criminal record = tiền án','/ˈkrɪmɪnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/crimi/criminal__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1696,'ngsl-4-08',14,'besides','ngoài ra; bên cạnh; hơn nữa','preposition','[{"en":"Besides English, she can also speak French and Japanese.","vi":"Ngoài tiếng Anh, cô ấy còn nói được tiếng Pháp và tiếng Nhật."},{"en":"Who else was at the party besides your cousins?","vi":"Ngoài anh chị em họ của bạn ra, còn ai ở bữa tiệc nữa?"},{"en":"I don''t want to go out tonight, and besides, it''s raining.","vi":"Tối nay tôi không muốn ra ngoài, hơn nữa trời đang mưa."}]','[{"phrase":"besides that"},{"phrase":"anyone besides"},{"phrase":"and besides"}]','besides (ngoài ra) ≠ beside (bên cạnh, về vị trí)','/bɪˈsaɪdz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bes/besid/besides__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1697,'ngsl-4-08',15,'properly','đúng cách; cẩn thận, tử tế','adverb','[{"en":"Make sure the door is properly locked before you leave.","vi":"Hãy chắc chắn cửa đã được khóa cẩn thận trước khi bạn đi."},{"en":"My laptop hasn''t been working properly since I dropped it.","vi":"Từ hôm tôi làm rơi, máy tính xách tay không chạy bình thường nữa."},{"en":"I was so worried that I couldn''t eat properly for days.","vi":"Tôi lo đến mức mấy ngày liền không ăn uống tử tế được."}]','[{"phrase":"work properly"},{"phrase":"properly trained"},{"phrase":"eat properly"},{"phrase":"done properly"}]',NULL,'/ˈprɑːpərli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prope/properly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1698,'ngsl-4-08',16,'ancient','cổ xưa; cổ đại','adjective','[{"en":"We visited an ancient temple on our trip last summer.","vi":"Chúng tôi đã đến thăm một ngôi đền cổ trong chuyến đi hè năm ngoái."},{"en":"My son loves reading stories about ancient Egypt.","vi":"Con trai tôi rất thích đọc truyện về Ai Cập cổ đại."},{"en":"People have used this ancient road for thousands of years.","vi":"Con người đã dùng con đường cổ này suốt hàng nghìn năm."}]','[{"phrase":"ancient history"},{"phrase":"ancient times"},{"phrase":"ancient city"},{"phrase":"ancient Greece"}]',NULL,'/ˈeɪnʃənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/anc/ancie/ancient__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1699,'ngsl-4-08',17,'coast','bờ biển; vùng ven biển','noun','[{"en":"We spent a week driving along the coast.","vi":"Chúng tôi dành một tuần lái xe dọc bờ biển."},{"en":"My grandparents live in a small town on the east coast.","vi":"Ông bà tôi sống ở một thị trấn nhỏ trên bờ biển phía đông."},{"en":"The storm is expected to hit the coast tomorrow night.","vi":"Cơn bão dự kiến sẽ đổ bộ vào bờ biển tối mai."}]','[{"phrase":"along the coast"},{"phrase":"on the coast"},{"phrase":"east coast"},{"phrase":"off the coast"}]',NULL,'/kəʊst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coast/coast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1700,'ngsl-4-08',18,'ill','ốm, bệnh','adjective','[{"en":"She stayed home from school because she was ill.","vi":"Cô bé nghỉ học ở nhà vì bị ốm."},{"en":"My grandfather has been seriously ill for several months.","vi":"Ông tôi đã bị bệnh nặng mấy tháng nay."},{"en":"I felt ill after eating the seafood last night.","vi":"Tôi thấy khó chịu trong người sau khi ăn hải sản tối qua."}]','[{"phrase":"seriously ill"},{"phrase":"fall ill"},{"phrase":"feel ill"},{"phrase":"mentally ill"}]','ill thường đứng sau động từ (be/feel ill); trước danh từ dùng sick: a sick child','/ɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/ill__/ill__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1701,'ngsl-4-08',19,'kick','đá','verb','[{"en":"The boy kicked the ball over the fence.","vi":"Cậu bé đá quả bóng bay qua hàng rào."},{"en":"Stop kicking the back of my seat, please.","vi":"Làm ơn đừng đá vào lưng ghế của tôi nữa."},{"en":"The horse kicked him when he walked behind it.","vi":"Con ngựa đá anh ấy khi anh ấy đi phía sau nó."}]','[{"phrase":"kick a ball"},{"phrase":"kick the door"},{"phrase":"kick off"}]',NULL,'/kɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kic/kick_/kick__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1702,'ngsl-4-08',20,'closely','chặt chẽ; sát sao; kỹ lưỡng','adverb','[{"en":"Our team works closely with the design department.","vi":"Nhóm chúng tôi làm việc chặt chẽ với phòng thiết kế."},{"en":"If you look closely, you can see a small crack.","vi":"Nếu nhìn kỹ, bạn có thể thấy một vết nứt nhỏ."},{"en":"The doctors are watching his condition closely after the surgery.","vi":"Các bác sĩ đang theo dõi sát sao tình trạng của anh ấy sau ca phẫu thuật."}]','[{"phrase":"work closely with"},{"phrase":"look closely"},{"phrase":"watch closely"},{"phrase":"closely related"}]',NULL,'/ˈkləʊsli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/close/closely__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1703,'ngsl-4-08',21,'multiple','nhiều; đa dạng','adjective','[{"en":"The test has twenty multiple choice questions.","vi":"Bài kiểm tra có hai mươi câu hỏi trắc nghiệm."},{"en":"I''ve tried calling her multiple times, but she never answers.","vi":"Tôi đã gọi cho cô ấy nhiều lần nhưng cô ấy không bao giờ nghe máy."},{"en":"You can open multiple windows on the screen at once.","vi":"Bạn có thể mở nhiều cửa sổ trên màn hình cùng lúc."}]','[{"phrase":"multiple times"},{"phrase":"multiple choice"},{"phrase":"multiple copies"}]','multiple choice = trắc nghiệm','/ˈmʌltɪpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mul/multi/multiple__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1704,'ngsl-4-08',22,'yield','mang lại, sinh ra; nhường (đường)','verb','[{"en":"Our search yielded some useful information about the house.","vi":"Cuộc tìm kiếm của chúng tôi đã mang lại vài thông tin hữu ích về ngôi nhà."},{"en":"These trees yield a lot of fruit every summer.","vi":"Mấy cây này cho rất nhiều quả vào mỗi mùa hè."},{"en":"Drivers must yield to people crossing the street.","vi":"Tài xế phải nhường đường cho người đi bộ qua đường."}]','[{"phrase":"yield results"},{"phrase":"yield information"},{"phrase":"yield to"}]','Danh từ: yield = sản lượng, lợi suất','/jiːld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yie/yield/yield__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1705,'ngsl-4-08',23,'via','qua, thông qua; đi qua (nơi nào)','preposition','[{"en":"We flew to London via Dubai because it was much cheaper.","vi":"Chúng tôi bay đến Luân Đôn qua Dubai vì rẻ hơn nhiều."},{"en":"I''ll send you the photos via email tonight.","vi":"Tối nay tôi sẽ gửi ảnh cho bạn qua email."},{"en":"Students can join the class via video call if they are sick.","vi":"Học sinh có thể tham gia lớp học qua gọi video nếu bị ốm."}]','[{"phrase":"via email"},{"phrase":"via the internet"},{"phrase":"via satellite"}]',NULL,'/ˈvaɪə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/via/via__/via__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1706,'ngsl-4-08',24,'legislation','luật pháp; việc lập pháp','noun','[{"en":"New legislation will make it illegal to use a phone while driving.","vi":"Luật mới sẽ khiến việc dùng điện thoại khi lái xe trở thành phạm pháp."},{"en":"The country has strict legislation to protect the environment.","vi":"Đất nước này có luật pháp nghiêm ngặt để bảo vệ môi trường."},{"en":"Many workers support the legislation on a higher minimum wage.","vi":"Nhiều người lao động ủng hộ luật về mức lương tối thiểu cao hơn."}]','[{"phrase":"new legislation"},{"phrase":"introduce legislation"},{"phrase":"pass legislation"},{"phrase":"legislation on"}]','không đếm được','/ˌledʒɪsˈleɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legis/legislation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1707,'ngsl-4-08',25,'county','hạt (đơn vị hành chính ở Anh, Mỹ); quận, huyện','noun','[{"en":"My aunt works as a nurse at the county hospital.","vi":"Dì tôi làm y tá ở bệnh viện của hạt."},{"en":"It is one of the smallest counties in the state.","vi":"Đó là một trong những hạt nhỏ nhất của bang."},{"en":"Farmers from across the county bring their animals to the fair.","vi":"Nông dân khắp hạt mang vật nuôi của mình đến hội chợ."}]','[{"phrase":"county council"},{"phrase":"county hospital"},{"phrase":"county fair"},{"phrase":"across the county"}]',NULL,'/ˈkaʊnti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/county__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1708,'ngsl-4-08',26,'unlike','không giống; khác với','preposition','[{"en":"Unlike his older brother, my husband really enjoys cooking.","vi":"Không giống anh trai mình, chồng tôi rất thích nấu ăn."},{"en":"The weather here is unlike anything I''ve experienced before.","vi":"Thời tiết ở đây khác hẳn mọi thứ tôi từng trải qua."},{"en":"It''s unlike her to be late, so I''m a little worried.","vi":"Cô ấy vốn không hay đến muộn, nên tôi hơi lo."}]','[{"phrase":"unlike most"},{"phrase":"unlike anything"},{"phrase":"quite unlike"}]','It''s unlike sb to do sth = không giống tính ai khi làm gì','/ˌʌnˈlaɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unl/unlik/unlike__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1709,'ngsl-4-08',27,'mobile','di động; lưu động; điện thoại di động','adjective','[{"en":"Please turn your mobile phone to silent during the film.","vi":"Vui lòng để điện thoại di động ở chế độ im lặng trong khi xem phim."},{"en":"A mobile library visits our village every Tuesday.","vi":"Một thư viện lưu động đến làng chúng tôi vào mỗi thứ Ba."},{"en":"After the operation, she was mobile again within a week.","vi":"Sau ca phẫu thuật, cô ấy đi lại được trong vòng một tuần."}]','[{"phrase":"mobile phone"},{"phrase":"mobile device"},{"phrase":"mobile app"}]','Anh: mobile (phone) · Mỹ: cell phone','/ˈməʊbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mob/mobil/mobile__us_7.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1710,'ngsl-4-08',28,'assistant','trợ lý; người phụ tá','noun','[{"en":"My assistant will send you the details this afternoon.","vi":"Trợ lý của tôi sẽ gửi thông tin chi tiết cho bạn chiều nay."},{"en":"She works as a teaching assistant at a primary school.","vi":"Cô ấy làm trợ giảng ở một trường tiểu học."},{"en":"Ask the shop assistant if they have this shirt in blue.","vi":"Hãy hỏi nhân viên bán hàng xem họ có chiếc áo này màu xanh không."}]','[{"phrase":"personal assistant"},{"phrase":"shop assistant"},{"phrase":"teaching assistant"},{"phrase":"research assistant"}]',NULL,'/əˈsɪstənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assistant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1711,'ngsl-4-08',29,'implement','thực hiện; triển khai; thi hành','verb','[{"en":"The school will implement the new rules next month.","vi":"Nhà trường sẽ áp dụng các quy định mới vào tháng tới."},{"en":"It took us two years to implement the plan.","vi":"Chúng tôi mất hai năm để thực hiện kế hoạch đó."},{"en":"The changes have not been implemented yet.","vi":"Những thay đổi này vẫn chưa được triển khai."}]','[{"phrase":"implement a plan"},{"phrase":"implement changes"},{"phrase":"implement a policy"},{"phrase":"fully implement"}]',NULL,'/ˈɪmplɪment/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imple/implement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1712,'ngsl-4-08',30,'chart','biểu đồ; bảng xếp hạng (âm nhạc)','noun','[{"en":"This chart shows how our sales have grown this year.","vi":"Biểu đồ này cho thấy doanh số của chúng ta đã tăng thế nào trong năm nay."},{"en":"Can you put these numbers into a simple chart?","vi":"Bạn có thể đưa những con số này vào một biểu đồ đơn giản không?"},{"en":"Their new song went straight to the top of the charts.","vi":"Bài hát mới của họ lập tức đứng đầu bảng xếp hạng."}]','[{"phrase":"pie chart"},{"phrase":"bar chart"},{"phrase":"top of the charts"},{"phrase":"chart shows"}]',NULL,'/tʃɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chart/chart__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1713,'ngsl-4-11',1,'vast','rộng lớn, bao la; rất nhiều, khổng lồ','adjective','[{"en":"From the plane, we could see the vast ocean below us.","vi":"Từ trên máy bay, chúng tôi có thể nhìn thấy đại dương bao la bên dưới."},{"en":"The vast majority of students passed the final exam.","vi":"Phần lớn sinh viên đã vượt qua kỳ thi cuối kỳ."},{"en":"She spent a vast amount of money on her new house.","vi":"Cô ấy đã tiêu một số tiền khổng lồ cho ngôi nhà mới."}]','[{"phrase":"vast majority"},{"phrase":"vast amount"},{"phrase":"vast area"}]',NULL,'/væst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vas/vast_/vast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1714,'ngsl-4-11',2,'exhibition','cuộc triển lãm; sự trưng bày','noun','[{"en":"We went to a photo exhibition at the city museum.","vi":"Chúng tôi đã đi xem một cuộc triển lãm ảnh ở bảo tàng thành phố."},{"en":"The gallery is holding an exhibition of work by local artists.","vi":"Phòng tranh đang tổ chức một cuộc triển lãm tác phẩm của các nghệ sĩ địa phương."},{"en":"Did you see the science exhibition at school last week?","vi":"Bạn có xem triển lãm khoa học ở trường tuần trước không?"}]','[{"phrase":"art exhibition"},{"phrase":"hold an exhibition"},{"phrase":"exhibition of"}]',NULL,'/ˌeksɪˈbɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhib/exhibition__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1715,'ngsl-4-11',3,'producer','nhà sản xuất (phim, nhạc); nơi sản xuất','noun','[{"en":"My uncle works as a TV producer in the capital.","vi":"Chú tôi làm nhà sản xuất chương trình truyền hình ở thủ đô."},{"en":"The film''s producer wanted a happier ending.","vi":"Nhà sản xuất của bộ phim muốn một cái kết vui hơn."},{"en":"This region is a major producer of rice and fruit.","vi":"Vùng này là nơi sản xuất lúa gạo và trái cây lớn."}]','[{"phrase":"film producer"},{"phrase":"record producer"},{"phrase":"major producer"}]',NULL,'/prəˈduːsər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/produ/producer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1716,'ngsl-4-11',4,'regional','(thuộc) vùng, khu vực','adjective','[{"en":"She works in the company''s regional office in the north.","vi":"Cô ấy làm việc ở văn phòng khu vực phía bắc của công ty."},{"en":"Our team won the regional championship last year.","vi":"Đội chúng tôi đã vô địch giải khu vực năm ngoái."},{"en":"Each regional dish has its own special flavor.","vi":"Mỗi món ăn vùng miền đều có hương vị đặc trưng riêng."}]','[{"phrase":"regional office"},{"phrase":"regional news"},{"phrase":"regional development"}]',NULL,'/ˈriːdʒənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regio/regional__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1717,'ngsl-4-11',5,'immediate','ngay lập tức; trước mắt; gần nhất, trực tiếp','adjective','[{"en":"The new medicine had an immediate effect on her pain.","vi":"Thuốc mới có tác dụng giảm đau cho cô ấy ngay lập tức."},{"en":"We need an immediate answer, so please call us today.","vi":"Chúng tôi cần câu trả lời ngay, vì vậy vui lòng gọi cho chúng tôi hôm nay."},{"en":"Only my immediate family came to the small wedding.","vi":"Chỉ có gia đình ruột thịt của tôi đến dự đám cưới nhỏ."}]','[{"phrase":"immediate effect"},{"phrase":"immediate action"},{"phrase":"immediate family"},{"phrase":"immediate future"}]',NULL,'/ɪˈmiːdiət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immed/immediate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1718,'ngsl-4-11',6,'incident','vụ việc; sự cố','noun','[{"en":"Police are investigating an incident at the train station.","vi":"Cảnh sát đang điều tra một vụ việc ở nhà ga."},{"en":"Nobody was hurt in the incident, but the car was badly damaged.","vi":"Không ai bị thương trong vụ việc, nhưng chiếc xe bị hư hỏng nặng."},{"en":"Please report any serious incident to your manager right away.","vi":"Vui lòng báo ngay cho quản lý về bất kỳ sự cố nghiêm trọng nào."}]','[{"phrase":"serious incident"},{"phrase":"report an incident"},{"phrase":"without incident"}]',NULL,'/ˈɪnsɪdənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incid/incident__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1719,'ngsl-4-11',7,'childhood','thời thơ ấu, tuổi thơ','noun','[{"en":"I spent most of my childhood in a small village.","vi":"Tôi đã trải qua phần lớn tuổi thơ ở một ngôi làng nhỏ."},{"en":"She has been my best friend since childhood.","vi":"Cô ấy là bạn thân nhất của tôi từ thuở nhỏ."},{"en":"These old songs bring back happy childhood memories.","vi":"Những bài hát cũ này gợi lại những kỷ niệm tuổi thơ vui vẻ."}]','[{"phrase":"happy childhood"},{"phrase":"early childhood"},{"phrase":"childhood memories"},{"phrase":"since childhood"}]',NULL,'/ˈtʃaɪldhʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/child/childhood__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1720,'ngsl-4-11',8,'draft','bản nháp; bản thảo','noun','[{"en":"Please send me the first draft of your report by Friday.","vi":"Vui lòng gửi cho tôi bản nháp đầu tiên của báo cáo trước thứ Sáu."},{"en":"I wrote three drafts before I was happy with the letter.","vi":"Tôi đã viết ba bản nháp rồi mới hài lòng với lá thư."},{"en":"The final draft looks much better than the earlier one.","vi":"Bản thảo cuối cùng trông tốt hơn nhiều so với bản trước."}]','[{"phrase":"first draft"},{"phrase":"final draft"},{"phrase":"rough draft"}]',NULL,'/dræft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/draft/draft__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1721,'ngsl-4-11',9,'slip','trượt, trượt chân; lẻn, lặng lẽ đi','verb','[{"en":"Be careful not to slip on the wet floor.","vi":"Cẩn thận kẻo trượt chân trên sàn ướt."},{"en":"She slipped on the ice and hurt her knee.","vi":"Cô ấy trượt chân trên băng và bị đau đầu gối."},{"en":"He slipped out of the meeting to answer a phone call.","vi":"Anh ấy lặng lẽ rời cuộc họp để nghe điện thoại."}]','[{"phrase":"slip on"},{"phrase":"slip and fall"},{"phrase":"slip out"},{"phrase":"slip away"}]','slip – slipped – slipped','/slɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/slip_/slip__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1722,'ngsl-4-11',10,'accompany','đi cùng, đi kèm; đệm nhạc','verb','[{"en":"Children under 12 must be accompanied by an adult.","vi":"Trẻ em dưới 12 tuổi phải có người lớn đi cùng."},{"en":"My mother accompanied me to the hospital yesterday.","vi":"Hôm qua mẹ tôi đã đi cùng tôi đến bệnh viện."},{"en":"She sang while her brother accompanied her on the piano.","vi":"Cô ấy hát trong khi anh trai đệm đàn piano cho cô."}]','[{"phrase":"be accompanied by"},{"phrase":"accompany someone to"}]','accompany – accompanied – accompanied','/əˈkʌmpəni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accompany__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1723,'ngsl-4-11',11,'politician','chính trị gia, chính khách','noun','[{"en":"Her father was a local politician for many years.","vi":"Bố cô ấy là một chính trị gia địa phương trong nhiều năm."},{"en":"The politician gave a short speech at the school opening.","vi":"Vị chính khách đã có bài phát biểu ngắn tại lễ khai trương trường."},{"en":"He wants to become a politician when he grows up.","vi":"Cậu ấy muốn trở thành chính trị gia khi lớn lên."}]','[{"phrase":"local politician"},{"phrase":"senior politician"},{"phrase":"leading politician"}]',NULL,'/ˌpɑːləˈtɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polit/politician__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1724,'ngsl-4-11',12,'angry','tức giận, giận dữ','adjective','[{"en":"My mom gets angry when I come home late.","vi":"Mẹ tôi nổi giận khi tôi về nhà muộn."},{"en":"Why are you so angry with me about this?","vi":"Sao bạn lại giận tôi vì chuyện này đến vậy?"},{"en":"Customers were angry about the long delay at the airport.","vi":"Khách hàng tức giận vì sự chậm trễ kéo dài ở sân bay."}]','[{"phrase":"get angry"},{"phrase":"angry with"},{"phrase":"angry about"}]','angry with + người · angry about + sự việc','/ˈæŋɡri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ang/angry/angry__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1725,'ngsl-4-11',13,'knock','gõ (cửa); đụng, làm đổ','verb','[{"en":"Please knock before you come into my room.","vi":"Làm ơn gõ cửa trước khi vào phòng tôi."},{"en":"Can you see who is knocking at the door?","vi":"Bạn xem ai đang gõ cửa được không?"},{"en":"The dog knocked over my cup of coffee this morning.","vi":"Sáng nay con chó làm đổ cốc cà phê của tôi."}]','[{"phrase":"knock on the door"},{"phrase":"knock at the door"},{"phrase":"knock over"}]',NULL,'/nɑːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kno/knock/knock__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1726,'ngsl-4-11',14,'seed','hạt giống; hạt','noun','[{"en":"We planted tomato seeds in the garden this spring.","vi":"Mùa xuân này chúng tôi đã gieo hạt cà chua trong vườn."},{"en":"These seeds need plenty of water and sunlight to grow.","vi":"Những hạt giống này cần nhiều nước và ánh nắng để phát triển."},{"en":"This watermelon has almost no seeds, so the kids love it.","vi":"Quả dưa hấu này gần như không có hạt nên bọn trẻ rất thích."}]','[{"phrase":"plant seeds"},{"phrase":"sow seeds"},{"phrase":"sunflower seeds"}]',NULL,'/siːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seed_/seed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1727,'ngsl-4-11',15,'salary','lương, tiền lương','noun','[{"en":"She earns a good salary as a nurse.","vi":"Cô ấy nhận mức lương khá khi làm y tá."},{"en":"Our salaries are paid at the end of each month.","vi":"Lương của chúng tôi được trả vào cuối mỗi tháng."},{"en":"He asked for a higher salary after working there for two years.","vi":"Anh ấy đề nghị tăng lương sau khi làm việc ở đó hai năm."}]','[{"phrase":"good salary"},{"phrase":"annual salary"},{"phrase":"earn a salary"},{"phrase":"salary increase"}]',NULL,'/ˈsæləri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sal/salar/salary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1728,'ngsl-4-11',16,'illustrate','minh họa; làm rõ, cho thấy','verb','[{"en":"The teacher used a simple story to illustrate her point.","vi":"Cô giáo dùng một câu chuyện đơn giản để minh họa cho ý của mình."},{"en":"This chart illustrates how prices have changed over time.","vi":"Biểu đồ này cho thấy giá cả đã thay đổi thế nào theo thời gian."},{"en":"She illustrates children''s books for a living.","vi":"Cô ấy kiếm sống bằng nghề vẽ minh họa sách thiếu nhi."}]','[{"phrase":"illustrate a point"},{"phrase":"clearly illustrate"},{"phrase":"illustrated book"}]',NULL,'/ˈɪləstreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illus/illustrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1729,'ngsl-4-11',17,'imply','ngụ ý, hàm ý','verb','[{"en":"Are you implying that I made a mistake?","vi":"Bạn đang ngụ ý rằng tôi đã mắc lỗi à?"},{"en":"His silence implied that he did not agree with us.","vi":"Sự im lặng của anh ấy hàm ý rằng anh ấy không đồng ý với chúng tôi."},{"en":"The report implies that the company is losing money.","vi":"Bản báo cáo ngụ ý rằng công ty đang lỗ."}]','[{"phrase":"imply that"},{"phrase":"clearly imply"},{"phrase":"strongly imply"}]','imply (người nói ngụ ý) ≠ infer (người nghe suy ra)','/ɪmˈplaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imply/imply__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1730,'ngsl-4-11',18,'breakfast','bữa sáng','noun','[{"en":"I usually have breakfast at seven before I go to work.","vi":"Tôi thường ăn sáng lúc bảy giờ trước khi đi làm."},{"en":"What did you eat for breakfast this morning?","vi":"Sáng nay bạn ăn gì vào bữa sáng?"},{"en":"She never skips breakfast, even when she is busy.","vi":"Cô ấy không bao giờ bỏ bữa sáng, kể cả khi bận rộn."}]','[{"phrase":"have breakfast"},{"phrase":"for breakfast"},{"phrase":"skip breakfast"}]',NULL,'/ˈbrekfəst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/break/breakfast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1731,'ngsl-4-11',19,'temporary','tạm thời','adjective','[{"en":"He found a temporary job during his summer vacation.","vi":"Anh ấy tìm được một công việc tạm thời trong kỳ nghỉ hè."},{"en":"The road is closed, but the problem is only temporary.","vi":"Con đường đang bị chặn, nhưng vấn đề này chỉ là tạm thời."},{"en":"We are living in a temporary apartment until our house is ready.","vi":"Chúng tôi đang ở một căn hộ tạm cho đến khi nhà xây xong."}]','[{"phrase":"temporary job"},{"phrase":"temporary solution"},{"phrase":"temporary work"}]',NULL,'/ˈtempəreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tem/tempo/temporary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1732,'ngsl-4-11',20,'liberal','cởi mở, phóng khoáng; hào phóng','adjective','[{"en":"My grandparents are surprisingly liberal about many modern ideas.","vi":"Ông bà tôi cởi mở một cách đáng ngạc nhiên với nhiều quan niệm hiện đại."},{"en":"The school has a fairly liberal attitude toward uniforms.","vi":"Nhà trường có thái độ khá thoải mái về chuyện đồng phục."},{"en":"She was always liberal with her praise for her students.","vi":"Cô ấy luôn hào phóng lời khen dành cho học trò."}]','[{"phrase":"liberal attitude"},{"phrase":"liberal views"},{"phrase":"liberal arts"}]',NULL,'/ˈlɪbərəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lib/liber/liberal__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1733,'ngsl-4-11',21,'lake','hồ','noun','[{"en":"We went swimming in the lake last summer.","vi":"Mùa hè năm ngoái chúng tôi đã đi bơi ở hồ."},{"en":"There is a small lake behind our village.","vi":"Có một cái hồ nhỏ phía sau làng chúng tôi."},{"en":"Our hotel room had a beautiful view of the lake.","vi":"Phòng khách sạn của chúng tôi có tầm nhìn đẹp ra hồ."}]','[{"phrase":"swim in the lake"},{"phrase":"by the lake"},{"phrase":"frozen lake"}]',NULL,'/leɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lak/lake_/lake__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1734,'ngsl-4-11',22,'qualify','đủ điều kiện; có đủ bằng cấp (hành nghề); giành quyền vào (vòng sau)','verb','[{"en":"You may qualify for a discount if you are a student.","vi":"Nếu là sinh viên, bạn có thể đủ điều kiện được giảm giá."},{"en":"She qualified as a doctor after seven years of study.","vi":"Cô ấy có đủ bằng cấp hành nghề bác sĩ sau bảy năm học."},{"en":"Our team qualified for the final after winning today''s match.","vi":"Đội chúng tôi giành quyền vào chung kết sau khi thắng trận hôm nay."}]','[{"phrase":"qualify for"},{"phrase":"qualify as"},{"phrase":"fully qualified"}]','qualify for + cái gì · qualify as + nghề','/ˈkwɑːlɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/qualify__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1735,'ngsl-4-11',23,'competitive','cạnh tranh; thích ganh đua','adjective','[{"en":"The job market is very competitive for new graduates.","vi":"Thị trường việc làm rất cạnh tranh đối với sinh viên mới tốt nghiệp."},{"en":"This shop offers competitive prices on all its products.","vi":"Cửa hàng này có giá cả cạnh tranh cho mọi sản phẩm."},{"en":"My brother is so competitive that he hates losing at cards.","vi":"Anh tôi thích ganh đua đến mức rất ghét thua khi chơi bài."}]','[{"phrase":"competitive prices"},{"phrase":"highly competitive"},{"phrase":"competitive market"}]',NULL,'/kəmˈpetətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/competitive__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1736,'ngsl-4-11',24,'truly','thật sự; thực lòng','adverb','[{"en":"I am truly sorry for what I said yesterday.","vi":"Tôi thực lòng xin lỗi vì những gì mình nói hôm qua."},{"en":"It was a truly beautiful day at the beach.","vi":"Đó thật sự là một ngày đẹp trời ở bãi biển."},{"en":"Do you truly believe that he is telling the truth?","vi":"Bạn có thật sự tin rằng anh ta đang nói thật không?"}]','[{"phrase":"truly sorry"},{"phrase":"truly believe"},{"phrase":"truly amazing"}]',NULL,'/ˈtruːli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/truly/truly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1737,'ngsl-4-11',25,'hi','chào, xin chào','exclamation','[{"en":"Hi, I''m your new neighbor from next door.","vi":"Chào bạn, tôi là hàng xóm mới ở nhà bên cạnh."},{"en":"Please say hi to your parents for me.","vi":"Cho tôi gửi lời chào đến bố mẹ bạn nhé."},{"en":"She smiled and said hi as she walked past.","vi":"Cô ấy mỉm cười và chào khi đi ngang qua."}]','[{"phrase":"say hi"},{"phrase":"say hi to"},{"phrase":"hi there"}]','thân mật, dùng trong giao tiếp hằng ngày','/haɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hi_/hi__u/hi__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1738,'ngsl-4-11',26,'yellow','(màu) vàng','adjective','[{"en":"She wore a bright yellow dress to the party.","vi":"Cô ấy mặc một chiếc váy màu vàng tươi đến bữa tiệc."},{"en":"The leaves turn yellow before they fall from the trees.","vi":"Lá chuyển sang màu vàng trước khi rụng khỏi cây."},{"en":"Slow down when the traffic light turns yellow.","vi":"Hãy giảm tốc độ khi đèn giao thông chuyển sang vàng."}]','[{"phrase":"bright yellow"},{"phrase":"pale yellow"},{"phrase":"turn yellow"}]',NULL,'/ˈjeləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yel/yello/yellow__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1739,'ngsl-4-11',27,'habit','thói quen','noun','[{"en":"Smoking is a bad habit that is hard to break.","vi":"Hút thuốc là một thói quen xấu khó bỏ."},{"en":"I''m trying to get into the habit of reading every night.","vi":"Tôi đang cố tạo thói quen đọc sách mỗi tối."},{"en":"He has a habit of biting his nails when he is nervous.","vi":"Anh ấy có thói quen cắn móng tay khi lo lắng."}]','[{"phrase":"bad habit"},{"phrase":"break a habit"},{"phrase":"habit of"},{"phrase":"eating habits"}]',NULL,'/ˈhæbɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hab/habit/habit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1740,'ngsl-4-11',28,'disk','đĩa, ổ đĩa (máy tính); vật hình đĩa','noun','[{"en":"My computer is slow because the hard disk is almost full.","vi":"Máy tính của tôi chạy chậm vì ổ cứng gần đầy."},{"en":"The game came on a disk, but now you can download it.","vi":"Trò chơi này từng được bán trên đĩa, nhưng giờ bạn có thể tải về."},{"en":"The moon looked like a silver disk in the night sky.","vi":"Mặt trăng trông như một chiếc đĩa bạc trên bầu trời đêm."}]','[{"phrase":"hard disk"},{"phrase":"disk space"},{"phrase":"disk drive"}]','Mỹ: disk · Anh: disc (máy tính thường viết disk)','/dɪsk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disk_/disk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1741,'ngsl-4-11',29,'core','cốt lõi, trọng tâm; lõi','noun','[{"en":"Honesty is at the core of a good friendship.","vi":"Sự trung thực là cốt lõi của một tình bạn đẹp."},{"en":"The core of the problem is a lack of money.","vi":"Mấu chốt của vấn đề là thiếu tiền."},{"en":"Please throw the apple core in the trash.","vi":"Làm ơn vứt lõi táo vào thùng rác."}]','[{"phrase":"at the core of"},{"phrase":"the core of the problem"},{"phrase":"apple core"}]',NULL,'/kɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/core_/core__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1742,'ngsl-4-11',30,'emotional','(thuộc) cảm xúc, tình cảm; xúc động','adjective','[{"en":"She became very emotional when she said goodbye to her class.","vi":"Cô ấy rất xúc động khi chia tay lớp học của mình."},{"en":"Children need emotional support as well as good food.","vi":"Trẻ em cần sự hỗ trợ về mặt tình cảm cũng như thức ăn tốt."},{"en":"The movie has a very emotional ending.","vi":"Bộ phim có một cái kết rất xúc động."}]','[{"phrase":"emotional support"},{"phrase":"emotional health"},{"phrase":"get emotional"}]',NULL,'/ɪˈməʊʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emo/emoti/emotional__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1743,'ngsl-4-12',1,'aircraft','máy bay; phi cơ','noun','[{"en":"The aircraft landed safely despite the strong wind.","vi":"Chiếc máy bay đã hạ cánh an toàn dù gió mạnh."},{"en":"All passengers must stay seated until the aircraft stops completely.","vi":"Tất cả hành khách phải ngồi yên cho đến khi máy bay dừng hẳn."},{"en":"My uncle has repaired military aircraft for over twenty years.","vi":"Chú tôi đã sửa chữa máy bay quân sự hơn hai mươi năm."}]','[{"phrase":"military aircraft"},{"phrase":"board an aircraft"},{"phrase":"aircraft carrier"}]','Số nhiều không đổi: one aircraft – two aircraft','/ˈerkræft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/air/aircr/aircraft__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1744,'ngsl-4-12',2,'self','bản thân; con người (của ai)','noun','[{"en":"After a good night''s sleep, she felt like her old self again.","vi":"Sau một đêm ngủ ngon, cô ấy lại thấy mình như trước đây."},{"en":"With close friends, she finally feels free to show her true self.","vi":"Khi ở bên bạn thân, cô ấy cuối cùng cũng thấy thoải mái thể hiện con người thật của mình."},{"en":"He seemed tired and was not his usual cheerful self.","vi":"Anh ấy có vẻ mệt và không vui vẻ như thường ngày."}]','[{"phrase":"sense of self"},{"phrase":"your old self"},{"phrase":"your true self"}]','Số nhiều: selves','/self/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/self_/self__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1745,'ngsl-4-12',3,'metal','kim loại','noun','[{"en":"Gold and silver are both expensive metals.","vi":"Vàng và bạc đều là những kim loại đắt tiền."},{"en":"The chairs in the garden are made of metal.","vi":"Những chiếc ghế trong vườn được làm bằng kim loại."},{"en":"Don''t put metal dishes in the microwave.","vi":"Đừng cho bát đĩa bằng kim loại vào lò vi sóng."}]','[{"phrase":"made of metal"},{"phrase":"precious metal"},{"phrase":"sheet of metal"},{"phrase":"metal box"}]',NULL,'/ˈmetl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/metal/metal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1746,'ngsl-4-12',4,'existence','sự tồn tại; cuộc sống','noun','[{"en":"Many people still doubt the existence of life on other planets.","vi":"Nhiều người vẫn nghi ngờ sự tồn tại của sự sống trên các hành tinh khác."},{"en":"This small bakery has been in existence for over fifty years.","vi":"Tiệm bánh nhỏ này đã tồn tại hơn năm mươi năm."},{"en":"My grandparents lived a quiet, simple existence in the village.","vi":"Ông bà tôi sống một cuộc sống yên bình, giản dị ở làng quê."}]','[{"phrase":"in existence"},{"phrase":"come into existence"},{"phrase":"the existence of"}]',NULL,'/ɪɡˈzɪstəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exi/exist/existence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1747,'ngsl-4-12',5,'bone','xương','noun','[{"en":"He broke a bone in his foot while playing football.","vi":"Anh ấy bị gãy một chiếc xương ở bàn chân khi chơi bóng đá."},{"en":"Be careful, this fish still has a lot of small bones.","vi":"Cẩn thận nhé, con cá này vẫn còn nhiều xương nhỏ."},{"en":"Our dog buried a bone somewhere in the backyard.","vi":"Con chó nhà tôi đã chôn một khúc xương đâu đó ở sân sau."}]','[{"phrase":"break a bone"},{"phrase":"broken bone"},{"phrase":"fish bone"}]',NULL,'/bəʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bon/bone_/bone__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1748,'ngsl-4-12',6,'panel','ban, nhóm (chuyên gia); tấm (ván, kính); bảng điều khiển','noun','[{"en":"A panel of experts will choose the winner of the contest.","vi":"Một ban chuyên gia sẽ chọn ra người thắng cuộc thi."},{"en":"We installed solar panels on the roof last summer.","vi":"Mùa hè năm ngoái chúng tôi đã lắp tấm pin mặt trời trên mái nhà."},{"en":"A red light started flashing on the control panel.","vi":"Một đèn đỏ bắt đầu nhấp nháy trên bảng điều khiển."}]','[{"phrase":"panel of experts"},{"phrase":"solar panel"},{"phrase":"control panel"},{"phrase":"panel discussion"}]',NULL,'/ˈpænl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pan/panel/panel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1749,'ngsl-4-12',7,'prime','chính, hàng đầu; tốt nhất','adjective','[{"en":"Cost was our prime concern when choosing a new apartment.","vi":"Chi phí là mối quan tâm hàng đầu của chúng tôi khi chọn căn hộ mới."},{"en":"The hotel is in a prime location near the beach.","vi":"Khách sạn nằm ở vị trí đắc địa gần bãi biển."},{"en":"Poor diet is a prime cause of many health problems.","vi":"Chế độ ăn uống kém là nguyên nhân chính của nhiều vấn đề sức khỏe."}]','[{"phrase":"prime minister"},{"phrase":"prime location"},{"phrase":"prime example"},{"phrase":"prime concern"}]',NULL,'/praɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prime/prime__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1750,'ngsl-4-12',8,'appointment','cuộc hẹn; sự bổ nhiệm','noun','[{"en":"I have a dentist appointment at three this afternoon.","vi":"Chiều nay lúc ba giờ tôi có hẹn với nha sĩ."},{"en":"Please call ahead to make an appointment with the doctor.","vi":"Vui lòng gọi trước để đặt lịch hẹn với bác sĩ."},{"en":"Everyone was happy about her appointment as team leader.","vi":"Mọi người đều vui vì cô ấy được bổ nhiệm làm trưởng nhóm."}]','[{"phrase":"make an appointment"},{"phrase":"cancel an appointment"},{"phrase":"doctor''s appointment"},{"phrase":"by appointment"}]',NULL,'/əˈpɔɪntmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appoi/appointment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1751,'ngsl-4-12',9,'emphasize','nhấn mạnh','verb','[{"en":"The teacher emphasized the importance of reading every day.","vi":"Giáo viên nhấn mạnh tầm quan trọng của việc đọc mỗi ngày."},{"en":"I want to emphasize that this offer ends on Friday.","vi":"Tôi muốn nhấn mạnh rằng ưu đãi này kết thúc vào thứ Sáu."},{"en":"She wore a belt to emphasize her small waist.","vi":"Cô ấy thắt dây lưng để làm nổi bật vòng eo nhỏ."}]','[{"phrase":"emphasize the importance of"},{"phrase":"emphasize that"},{"phrase":"strongly emphasize"}]','Anh: emphasise · Mỹ: emphasize','/ˈemfəsaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empha/emphasize__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1752,'ngsl-4-12',10,'maximum','mức tối đa; tối đa','noun','[{"en":"The maximum speed on this road is sixty kilometers an hour.","vi":"Tốc độ tối đa trên con đường này là sáu mươi ki-lô-mét một giờ."},{"en":"Each passenger can bring a maximum of two bags.","vi":"Mỗi hành khách được mang tối đa hai túi."},{"en":"Turn the volume up to maximum so everyone can hear.","vi":"Hãy vặn âm lượng lên mức tối đa để mọi người đều nghe được."}]','[{"phrase":"maximum speed"},{"phrase":"a maximum of"},{"phrase":"maximum number"},{"phrase":"maximum temperature"}]','Trái nghĩa: minimum','/ˈmæksɪməm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/max/maxim/maximum__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1753,'ngsl-4-12',11,'effectively','một cách hiệu quả; thực tế là','adverb','[{"en":"Good managers know how to communicate effectively with their teams.","vi":"Người quản lý giỏi biết cách giao tiếp hiệu quả với đội của mình."},{"en":"This cream works effectively against dry skin.","vi":"Loại kem này có tác dụng hiệu quả với da khô."},{"en":"The road was closed, so the village was effectively cut off.","vi":"Con đường bị đóng, nên thực tế là ngôi làng bị cô lập."}]','[{"phrase":"work effectively"},{"phrase":"communicate effectively"},{"phrase":"use something effectively"}]',NULL,'/ɪˈfektɪvli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effec/effectively__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1754,'ngsl-4-12',12,'elsewhere','ở nơi khác; đến nơi khác','adverb','[{"en":"This shop is too expensive, so let''s look elsewhere.","vi":"Cửa hàng này đắt quá, mình tìm chỗ khác đi."},{"en":"Prices here are lower than elsewhere in the city.","vi":"Giá ở đây rẻ hơn những nơi khác trong thành phố."},{"en":"If you are not happy, you can take your business elsewhere.","vi":"Nếu không hài lòng, bạn có thể đi mua ở nơi khác."}]','[{"phrase":"look elsewhere"},{"phrase":"go elsewhere"},{"phrase":"elsewhere in the world"}]',NULL,'/ˌelsˈwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/els/elsew/elsewhere__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1755,'ngsl-4-12',13,'bother','làm phiền; bận tâm, mất công','verb','[{"en":"Sorry to bother you, but could you help me with this?","vi":"Xin lỗi đã làm phiền bạn, nhưng bạn có thể giúp tôi việc này không?"},{"en":"Does the noise from the street bother you at night?","vi":"Tiếng ồn ngoài đường có làm bạn khó chịu vào ban đêm không?"},{"en":"He didn''t even bother to say goodbye before he left.","vi":"Anh ta thậm chí chẳng buồn chào tạm biệt trước khi đi."}]','[{"phrase":"sorry to bother you"},{"phrase":"don''t bother"},{"phrase":"bother to do something"}]',NULL,'/ˈbɑːðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bot/bothe/bother__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1756,'ngsl-4-12',14,'initiative','sáng kiến; tính chủ động','noun','[{"en":"The city launched a new initiative to plant more trees.","vi":"Thành phố đã khởi động một sáng kiến mới để trồng thêm cây xanh."},{"en":"She took the initiative and organized the team meeting herself.","vi":"Cô ấy đã chủ động tự tổ chức buổi họp nhóm."},{"en":"Our boss wants staff who show initiative at work.","vi":"Sếp chúng tôi muốn những nhân viên thể hiện tính chủ động trong công việc."}]','[{"phrase":"take the initiative"},{"phrase":"show initiative"},{"phrase":"new initiative"},{"phrase":"on your own initiative"}]',NULL,'/ɪˈnɪʃətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initiative__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1757,'ngsl-4-12',15,'sharp','sắc, nhọn; đột ngột; thông minh','adjective','[{"en":"Be careful, that kitchen knife is very sharp.","vi":"Cẩn thận nhé, con dao làm bếp đó rất sắc."},{"en":"There has been a sharp rise in house prices this year.","vi":"Năm nay giá nhà đã tăng mạnh đột ngột."},{"en":"My grandmother is ninety, but her mind is still sharp.","vi":"Bà tôi đã chín mươi tuổi nhưng đầu óc vẫn còn minh mẫn."}]','[{"phrase":"sharp knife"},{"phrase":"sharp rise"},{"phrase":"sharp pain"},{"phrase":"sharp mind"}]','at six o''clock sharp = đúng sáu giờ','/ʃɑːrp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/sharp/sharp__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1758,'ngsl-4-12',16,'diet','chế độ ăn uống; chế độ ăn kiêng','noun','[{"en":"A healthy diet includes plenty of fruit and vegetables.","vi":"Một chế độ ăn uống lành mạnh gồm nhiều trái cây và rau củ."},{"en":"I''m on a diet, so no cake for me, thanks.","vi":"Tôi đang ăn kiêng, nên cho tôi xin không ăn bánh nhé."},{"en":"The doctor told him to change his diet and exercise more.","vi":"Bác sĩ bảo anh ấy thay đổi chế độ ăn và tập thể dục nhiều hơn."}]','[{"phrase":"healthy diet"},{"phrase":"balanced diet"},{"phrase":"on a diet"},{"phrase":"go on a diet"}]',NULL,'/ˈdaɪət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/die/diet_/diet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1759,'ngsl-4-12',17,'motion','sự chuyển động; cử chỉ; kiến nghị','noun','[{"en":"Do not open the door while the train is in motion.","vi":"Không được mở cửa khi tàu đang chạy."},{"en":"The motion of the boat made me feel sick.","vi":"Sự chòng chành của con thuyền làm tôi thấy buồn nôn."},{"en":"The committee voted in favor of the motion.","vi":"Ủy ban đã bỏ phiếu tán thành bản kiến nghị."}]','[{"phrase":"in motion"},{"phrase":"slow motion"},{"phrase":"motion sickness"},{"phrase":"set something in motion"}]',NULL,'/ˈməʊʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motio/motion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1760,'ngsl-4-12',18,'gray','(màu) xám; (tóc) bạc','adjective','[{"en":"The sky turned gray, and it started to rain.","vi":"Bầu trời chuyển sang màu xám, rồi trời bắt đầu mưa."},{"en":"My father''s hair went gray when he was only forty.","vi":"Tóc bố tôi đã bạc khi ông mới bốn mươi tuổi."},{"en":"She bought a dark gray coat for the winter.","vi":"Cô ấy mua một chiếc áo khoác màu xám đậm cho mùa đông."}]','[{"phrase":"gray hair"},{"phrase":"go gray"},{"phrase":"dark gray"},{"phrase":"gray sky"}]','Mỹ: gray · Anh: grey','/ɡreɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gray_/gray__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1761,'ngsl-4-12',19,'plastic','nhựa; (bằng) nhựa','noun','[{"en":"Many countries are trying to use less plastic.","vi":"Nhiều quốc gia đang cố gắng dùng ít nhựa hơn."},{"en":"Please bring your own bag instead of taking a plastic one.","vi":"Vui lòng mang túi riêng thay vì lấy túi nhựa."},{"en":"These toys are made of plastic, so they won''t break easily.","vi":"Những món đồ chơi này làm bằng nhựa nên không dễ vỡ."}]','[{"phrase":"plastic bag"},{"phrase":"plastic bottle"},{"phrase":"made of plastic"},{"phrase":"plastic waste"}]',NULL,'/ˈplæstɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plast/plastic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1762,'ngsl-4-12',20,'complicate','làm phức tạp','verb','[{"en":"Let''s not complicate things by adding more rules.","vi":"Chúng ta đừng làm mọi chuyện phức tạp bằng cách thêm quy định."},{"en":"The bad weather complicated our travel plans.","vi":"Thời tiết xấu đã làm kế hoạch đi du lịch của chúng tôi thêm phức tạp."},{"en":"His illness was complicated by a serious infection.","vi":"Bệnh của anh ấy trở nên phức tạp hơn do một ca nhiễm trùng nặng."}]','[{"phrase":"complicate matters"},{"phrase":"complicate things"},{"phrase":"further complicate"}]',NULL,'/ˈkɑːmplɪkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complicate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1763,'ngsl-4-12',21,'discipline','kỷ luật; sự rèn luyện','noun','[{"en":"Learning a language takes time and a lot of discipline.","vi":"Học một ngôn ngữ cần thời gian và rất nhiều kỷ luật."},{"en":"The new teacher had trouble keeping discipline in the classroom.","vi":"Giáo viên mới gặp khó khăn trong việc giữ kỷ luật trong lớp."},{"en":"Some parents believe discipline should start at a very young age.","vi":"Một số bậc cha mẹ tin rằng việc rèn kỷ luật nên bắt đầu từ khi còn rất nhỏ."}]','[{"phrase":"self-discipline"},{"phrase":"strict discipline"},{"phrase":"maintain discipline"},{"phrase":"lack of discipline"}]',NULL,'/ˈdɪsəplɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disci/discipline__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1764,'ngsl-4-12',22,'disappoint','làm thất vọng','verb','[{"en":"I''m sorry to disappoint you, but the tickets are sold out.","vi":"Rất tiếc phải làm bạn thất vọng, nhưng vé đã bán hết rồi."},{"en":"The movie was good, but the ending disappointed me.","vi":"Bộ phim hay, nhưng cái kết làm tôi thất vọng."},{"en":"She worked hard because she didn''t want to disappoint her parents.","vi":"Cô ấy học hành chăm chỉ vì không muốn làm bố mẹ thất vọng."}]','[{"phrase":"sorry to disappoint you"},{"phrase":"disappoint your parents"},{"phrase":"won''t disappoint"}]',NULL,'/ˌdɪsəˈpɔɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disap/disappoint__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1765,'ngsl-4-12',23,'boss','sếp; ông chủ','noun','[{"en":"I need to ask my boss for a day off.","vi":"Tôi cần xin sếp cho nghỉ một ngày."},{"en":"Her new boss is friendly and easy to talk to.","vi":"Sếp mới của cô ấy thân thiện và dễ nói chuyện."},{"en":"He wants to start his own company and be his own boss.","vi":"Anh ấy muốn mở công ty riêng và tự làm chủ."}]','[{"phrase":"your boss"},{"phrase":"new boss"},{"phrase":"be your own boss"}]',NULL,'/bɔːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bos/boss_/boss__us_8.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1766,'ngsl-4-12',24,'assumption','giả định; sự cho rằng','noun','[{"en":"Don''t make assumptions about people based on how they look.","vi":"Đừng phỏng đoán về người khác dựa trên vẻ ngoài của họ."},{"en":"We planned the budget on the assumption that prices would stay the same.","vi":"Chúng tôi lập ngân sách với giả định rằng giá cả sẽ giữ nguyên."},{"en":"My assumption was wrong, and the store was open after all.","vi":"Tôi đã đoán sai, hóa ra cửa hàng vẫn mở."}]','[{"phrase":"make an assumption"},{"phrase":"on the assumption that"},{"phrase":"wrong assumption"},{"phrase":"basic assumption"}]',NULL,'/əˈsʌmpʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assum/assumption__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1767,'ngsl-4-12',25,'freeze','đóng băng; đông lạnh; đứng sững lại','verb','[{"en":"It was so cold last night that the lake froze over.","vi":"Đêm qua trời lạnh đến mức mặt hồ đóng băng hết."},{"en":"You can freeze the leftover soup and eat it next week.","vi":"Bạn có thể cấp đông phần súp còn thừa và ăn vào tuần sau."},{"en":"She froze when she heard a strange noise downstairs.","vi":"Cô ấy đứng sững lại khi nghe thấy tiếng động lạ dưới nhà."}]','[{"phrase":"freeze to death"},{"phrase":"freeze food"},{"phrase":"freeze prices"}]','freeze – froze – frozen','/friːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/freez/freeze__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1768,'ngsl-4-12',26,'extreme','cực độ, khắc nghiệt; quá khích','adjective','[{"en":"Plants in the desert can survive extreme heat.","vi":"Thực vật ở sa mạc có thể sống sót trong cái nóng khắc nghiệt."},{"en":"Please drive with extreme care on icy roads.","vi":"Vui lòng lái xe hết sức cẩn thận trên đường đóng băng."},{"en":"I think his views on money are a bit extreme.","vi":"Tôi nghĩ quan điểm của anh ấy về tiền bạc hơi cực đoan."}]','[{"phrase":"extreme heat"},{"phrase":"extreme weather"},{"phrase":"extreme care"},{"phrase":"extreme case"}]',NULL,'/ɪkˈstriːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extre/extreme__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1769,'ngsl-4-12',27,'passage','đoạn văn; lối đi, hành lang','noun','[{"en":"Read the passage and answer the questions below.","vi":"Hãy đọc đoạn văn và trả lời các câu hỏi bên dưới."},{"en":"The teacher asked me to read a short passage aloud.","vi":"Cô giáo bảo tôi đọc to một đoạn văn ngắn."},{"en":"A narrow passage leads from the kitchen to the garden.","vi":"Một lối đi hẹp dẫn từ nhà bếp ra vườn."}]','[{"phrase":"reading passage"},{"phrase":"short passage"},{"phrase":"narrow passage"},{"phrase":"read a passage"}]',NULL,'/ˈpæsɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passa/passage__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1770,'ngsl-4-12',28,'reputation','danh tiếng, tiếng tăm','noun','[{"en":"This restaurant has a good reputation for fresh seafood.","vi":"Nhà hàng này nổi tiếng về hải sản tươi ngon."},{"en":"One bad review can damage a small company''s reputation.","vi":"Một đánh giá xấu có thể làm tổn hại danh tiếng của một công ty nhỏ."},{"en":"She has built a reputation as a reliable and honest worker.","vi":"Cô ấy đã gây dựng được tiếng là một nhân viên đáng tin cậy và trung thực."}]','[{"phrase":"good reputation"},{"phrase":"reputation for"},{"phrase":"damage your reputation"},{"phrase":"build a reputation"}]',NULL,'/ˌrepjuˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/reput/reputation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1771,'ngsl-4-12',29,'forth','về phía trước, qua lại; trở đi','adverb','[{"en":"He walked back and forth while waiting for the phone call.","vi":"Anh ấy đi đi lại lại trong lúc chờ cuộc điện thoại."},{"en":"We need pens, paper, folders and so forth for the office.","vi":"Văn phòng cần bút, giấy, bìa hồ sơ, v.v."},{"en":"From that day forth, she never missed a single class.","vi":"Từ ngày đó trở đi, cô ấy không bỏ một buổi học nào."}]','[{"phrase":"back and forth"},{"phrase":"and so forth"},{"phrase":"from that day forth"},{"phrase":"set forth"}]',NULL,'/fɔːrθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forth/forth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1772,'ngsl-4-12',30,'negotiation','sự đàm phán, thương lượng','noun','[{"en":"After long negotiations, the two companies finally signed the deal.","vi":"Sau những cuộc đàm phán kéo dài, hai công ty cuối cùng đã ký hợp đồng."},{"en":"The price of the car is open to negotiation.","vi":"Giá của chiếc xe này có thể thương lượng."},{"en":"Good negotiation skills are useful when you ask for a raise.","vi":"Kỹ năng đàm phán tốt rất hữu ích khi bạn xin tăng lương."}]','[{"phrase":"open to negotiation"},{"phrase":"negotiation skills"},{"phrase":"under negotiation"},{"phrase":"enter into negotiations"}]',NULL,'/nɪˌɡəʊʃiˈeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negot/negotiation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1773,'ngsl-4-09',1,'attach','gắn; đính kèm','verb','[{"en":"Please attach a recent photo to your application form.","vi":"Vui lòng đính kèm một ảnh gần đây vào đơn đăng ký."},{"en":"I forgot to attach the file to my email.","vi":"Tôi quên đính kèm tệp vào email."},{"en":"The shelf is attached to the wall with four screws.","vi":"Cái kệ được gắn vào tường bằng bốn con vít."}]','[{"phrase":"attach a file"},{"phrase":"attach a photo"},{"phrase":"attach importance to"}]','attach sth to sth','/əˈtætʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1774,'ngsl-4-09',2,'hell','địa ngục; cực hình','noun','[{"en":"Driving in rush hour traffic is pure hell.","vi":"Lái xe vào giờ cao điểm đúng là cực hình."},{"en":"She went through hell when her company closed down.","vi":"Cô ấy đã trải qua một thời gian cực khổ khi công ty đóng cửa."},{"en":"We had a hell of a time finding a parking space.","vi":"Chúng tôi đã rất vất vả mới tìm được chỗ đậu xe."}]','[{"phrase":"pure hell"},{"phrase":"go through hell"},{"phrase":"a hell of a"}]','Khẩu ngữ, chỉ dùng trong tình huống thân mật','/hel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/hell_/hell__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1775,'ngsl-4-09',3,'everywhere','khắp nơi; ở mọi nơi','adverb','[{"en":"I''ve looked everywhere, but I can''t find my keys.","vi":"Tôi đã tìm khắp nơi mà không thấy chìa khóa đâu."},{"en":"There were people everywhere at the night market.","vi":"Ở chợ đêm, đâu đâu cũng có người."},{"en":"You can buy this kind of phone charger almost everywhere.","vi":"Bạn có thể mua loại sạc điện thoại này ở hầu như mọi nơi."}]','[{"phrase":"look everywhere"},{"phrase":"almost everywhere"},{"phrase":"everywhere else"}]',NULL,'/ˈevriwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everywhere__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1776,'ngsl-4-09',4,'advise','khuyên; tư vấn','verb','[{"en":"The doctor advised me to get more sleep.","vi":"Bác sĩ khuyên tôi nên ngủ nhiều hơn."},{"en":"I would advise you not to drive in this weather.","vi":"Tôi khuyên bạn không nên lái xe trong thời tiết thế này."},{"en":"Our teacher advises students on which courses to take.","vi":"Thầy giáo tư vấn cho sinh viên nên chọn học những môn nào."}]','[{"phrase":"advise sb to do sth"},{"phrase":"strongly advise"},{"phrase":"advise on"}]','advise (v) ≠ advice (n)','/ədˈvaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advis/advise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1777,'ngsl-4-09',5,'household','hộ gia đình; gia đình','noun','[{"en":"Almost every household in the village has a motorbike.","vi":"Hầu như hộ gia đình nào trong làng cũng có xe máy."},{"en":"Who does the cooking in your household?","vi":"Trong gia đình bạn, ai là người nấu ăn?"},{"en":"The average household income in the city has risen this year.","vi":"Thu nhập trung bình của các hộ gia đình trong thành phố đã tăng trong năm nay."}]','[{"phrase":"household income"},{"phrase":"household chores"},{"phrase":"head of the household"}]',NULL,'/ˈhaʊshəʊld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hou/house/household__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1778,'ngsl-4-09',6,'acknowledge','thừa nhận; xác nhận','verb','[{"en":"He finally acknowledged that he had made a mistake.","vi":"Cuối cùng anh ấy cũng thừa nhận mình đã mắc lỗi."},{"en":"The company acknowledged the problem and apologized to its customers.","vi":"Công ty đã thừa nhận vấn đề và xin lỗi khách hàng."},{"en":"Please acknowledge receipt of this email as soon as possible.","vi":"Vui lòng xác nhận đã nhận được email này càng sớm càng tốt."}]','[{"phrase":"acknowledge receipt of"},{"phrase":"acknowledge the problem"},{"phrase":"publicly acknowledge"}]',NULL,'/əkˈnɑːlɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ack/ackno/acknowledge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1779,'ngsl-4-09',7,'reward','phần thưởng; tiền thưởng','noun','[{"en":"The children got ice cream as a reward for being good.","vi":"Bọn trẻ được ăn kem như một phần thưởng vì đã ngoan."},{"en":"The owner is offering a reward for finding her lost dog.","vi":"Cô chủ đang treo thưởng cho ai tìm thấy chú chó bị lạc của mình."},{"en":"Seeing my students succeed is the greatest reward of teaching.","vi":"Thấy học trò thành công là phần thưởng lớn nhất của nghề dạy học."}]','[{"phrase":"as a reward"},{"phrase":"offer a reward"},{"phrase":"reward for"}]','Cũng là động từ: reward sb for sth (thưởng)','/rɪˈwɔːrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rew/rewar/reward__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1780,'ngsl-4-09',8,'east','phía đông; hướng đông','noun','[{"en":"The sun rises in the east and sets in the west.","vi":"Mặt trời mọc ở phía đông và lặn ở phía tây."},{"en":"Their farm is about ten kilometers to the east of town.","vi":"Trang trại của họ cách thị trấn khoảng mười cây số về phía đông."},{"en":"A cold wind is blowing from the east today.","vi":"Hôm nay có gió lạnh thổi từ hướng đông."}]','[{"phrase":"in the east"},{"phrase":"to the east of"},{"phrase":"from the east"}]',NULL,'/iːst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/east_/east__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1781,'ngsl-4-09',9,'hat','mũ; nón','noun','[{"en":"Don''t forget to wear a hat in the sun.","vi":"Đừng quên đội mũ khi ra nắng."},{"en":"He took off his hat when he walked into the room.","vi":"Anh ấy bỏ mũ ra khi bước vào phòng."},{"en":"My grandmother bought me a warm wool hat for winter.","vi":"Bà mua cho tôi một chiếc mũ len ấm để đội vào mùa đông."}]','[{"phrase":"wear a hat"},{"phrase":"take off your hat"},{"phrase":"wool hat"},{"phrase":"straw hat"}]',NULL,'/hæt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hat/hat__/hat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1782,'ngsl-4-09',10,'academic','(thuộc) học thuật; (thuộc) học tập','adjective','[{"en":"She has always had excellent academic results.","vi":"Cô ấy luôn có kết quả học tập xuất sắc."},{"en":"The new academic year starts in early September.","vi":"Năm học mới bắt đầu vào đầu tháng Chín."},{"en":"Writing an academic paper takes a lot of time and research.","vi":"Viết một bài báo học thuật cần nhiều thời gian và nghiên cứu."}]','[{"phrase":"academic year"},{"phrase":"academic performance"},{"phrase":"academic writing"}]',NULL,'/ˌækəˈdemɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aca/acade/academic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1783,'ngsl-4-09',11,'voter','cử tri; người bỏ phiếu','noun','[{"en":"Every voter must show an ID card at the polling station.","vi":"Mỗi cử tri phải xuất trình thẻ căn cước tại điểm bỏ phiếu."},{"en":"More young voters took part in the election this year.","vi":"Năm nay có nhiều cử tri trẻ tham gia bầu cử hơn."},{"en":"The team captain was chosen by a small group of voters.","vi":"Đội trưởng được một nhóm nhỏ người bỏ phiếu lựa chọn."}]','[{"phrase":"young voters"},{"phrase":"first-time voters"},{"phrase":"voter turnout"}]',NULL,'/ˈvəʊtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vot/voter/voter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1784,'ngsl-4-09',12,'meanwhile','trong khi đó; trong lúc chờ đợi','adverb','[{"en":"Dinner will be ready soon; meanwhile, you can set the table.","vi":"Bữa tối sắp xong rồi; trong lúc chờ, bạn dọn bàn ăn nhé."},{"en":"I cooked dinner, and meanwhile my husband gave the kids a bath.","vi":"Tôi nấu bữa tối, còn trong khi đó chồng tôi tắm cho bọn trẻ."},{"en":"Prices keep rising; meanwhile, wages have stayed the same.","vi":"Giá cả liên tục tăng; trong khi đó, lương vẫn giữ nguyên."}]','[{"phrase":"in the meanwhile"},{"phrase":"and meanwhile"}]',NULL,'/ˈmiːnwaɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/meanw/meanwhile__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1785,'ngsl-4-09',13,'furthermore','hơn nữa; ngoài ra','adverb','[{"en":"The hotel is cheap; furthermore, it is close to the beach.","vi":"Khách sạn này rẻ; hơn nữa, nó lại gần biển."},{"en":"Furthermore, the new system will save staff a lot of time.","vi":"Hơn nữa, hệ thống mới sẽ giúp nhân viên tiết kiệm nhiều thời gian."},{"en":"The course is free, and furthermore, you get a certificate at the end.","vi":"Khóa học miễn phí, và ngoài ra bạn còn được nhận chứng chỉ khi kết thúc."}]','[{"phrase":"and furthermore"},{"phrase":"furthermore, it is"}]','Trang trọng, thường dùng trong văn viết','/ˌfɜːrðərˈmɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furth/furthermore__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1786,'ngsl-4-09',14,'accuse','buộc tội; cáo buộc','verb','[{"en":"She accused me of reading her diary.","vi":"Cô ấy buộc tội tôi đã đọc nhật ký của cô ấy."},{"en":"Are you accusing me of lying to you about the money?","vi":"Bạn đang buộc tội tôi nói dối bạn về chuyện tiền bạc à?"},{"en":"The company was accused of paying its workers too little.","vi":"Công ty bị cáo buộc trả lương quá thấp cho công nhân."}]','[{"phrase":"accuse sb of"},{"phrase":"be accused of"},{"phrase":"falsely accuse"}]','accuse sb of (doing) sth','/əˈkjuːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accus/accuse__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1787,'ngsl-4-09',15,'scientific','(thuộc) khoa học; có tính khoa học','adjective','[{"en":"There is no scientific evidence that this tea helps you lose weight.","vi":"Không có bằng chứng khoa học nào cho thấy loại trà này giúp giảm cân."},{"en":"Scientific research often takes many years and a lot of money.","vi":"Nghiên cứu khoa học thường mất nhiều năm và tốn nhiều tiền."},{"en":"We need a more scientific approach to solving this problem.","vi":"Chúng ta cần một cách tiếp cận khoa học hơn để giải quyết vấn đề này."}]','[{"phrase":"scientific evidence"},{"phrase":"scientific research"},{"phrase":"scientific approach"}]',NULL,'/ˌsaɪənˈtɪfɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sci/scien/scientific__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1788,'ngsl-4-09',16,'wage','tiền lương; tiền công','noun','[{"en":"The minimum wage will go up again next year.","vi":"Mức lương tối thiểu sẽ lại tăng vào năm sau."},{"en":"Workers at the factory are asking for higher wages.","vi":"Công nhân ở nhà máy đang đòi được trả lương cao hơn."},{"en":"He earns a good wage working in a hotel kitchen.","vi":"Anh ấy kiếm được mức lương khá khi làm trong bếp của một khách sạn."}]','[{"phrase":"minimum wage"},{"phrase":"higher wages"},{"phrase":"earn a wage"}]','wage: lương theo giờ/tuần ≠ salary: lương tháng/năm','/weɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wag/wage_/wage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1789,'ngsl-4-09',17,'absence','sự vắng mặt; sự thiếu','noun','[{"en":"Nobody noticed his absence from the meeting.","vi":"Không ai để ý anh ấy vắng mặt trong cuộc họp."},{"en":"My neighbor fed my cat during my absence.","vi":"Hàng xóm cho mèo của tôi ăn trong thời gian tôi vắng nhà."},{"en":"The absence of clear rules caused a lot of confusion.","vi":"Việc thiếu quy định rõ ràng đã gây ra nhiều nhầm lẫn."}]','[{"phrase":"absence from"},{"phrase":"in the absence of"},{"phrase":"long absence"}]',NULL,'/ˈæbsəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/absen/absence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1790,'ngsl-4-09',18,'construct','xây dựng; tạo dựng; đặt (câu)','verb','[{"en":"The bridge was constructed more than a hundred years ago.","vi":"Cây cầu được xây dựng cách đây hơn một trăm năm."},{"en":"The city plans to construct a new hospital near the river.","vi":"Thành phố dự định xây một bệnh viện mới gần sông."},{"en":"Can you construct a sentence using this new word?","vi":"Bạn có thể đặt một câu với từ mới này không?"}]','[{"phrase":"construct a building"},{"phrase":"construct a bridge"},{"phrase":"construct a sentence"}]',NULL,'/kənˈstrʌkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstruct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1791,'ngsl-4-09',19,'remark','lời nhận xét; lời bình luận','noun','[{"en":"His rude remark about her cooking really upset her.","vi":"Lời nhận xét khiếm nhã của anh ấy về tài nấu ăn của cô ấy khiến cô rất buồn."},{"en":"She made a few remarks about the weather and then left.","vi":"Cô ấy bình luận vài câu về thời tiết rồi rời đi."},{"en":"Don''t take his remark seriously; he was only joking.","vi":"Đừng để bụng lời nhận xét của anh ấy; anh ấy chỉ đùa thôi."}]','[{"phrase":"make a remark"},{"phrase":"rude remark"},{"phrase":"passing remark"}]','Cũng là động từ: remark on sth (nhận xét về)','/rɪˈmɑːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remar/remark__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1792,'ngsl-4-09',20,'medicine','thuốc; y học','noun','[{"en":"Take this medicine three times a day after meals.","vi":"Uống thuốc này ba lần một ngày sau bữa ăn."},{"en":"Keep all medicine out of the reach of small children.","vi":"Hãy để tất cả thuốc xa tầm tay trẻ nhỏ."},{"en":"My sister is studying medicine at university.","vi":"Chị tôi đang học ngành y ở đại học."}]','[{"phrase":"take medicine"},{"phrase":"study medicine"},{"phrase":"modern medicine"}]','take medicine = uống thuốc','/ˈmedɪsn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/medic/medicine__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1793,'ngsl-4-09',21,'professor','giáo sư; giảng viên đại học','noun','[{"en":"My professor gave me some useful advice about my thesis.","vi":"Giáo sư của tôi đã cho tôi vài lời khuyên hữu ích về luận văn."},{"en":"She became a professor of chemistry at the age of forty.","vi":"Bà ấy trở thành giáo sư hóa học ở tuổi bốn mươi."},{"en":"Our history professor always tells funny stories in class.","vi":"Giảng viên môn lịch sử của chúng tôi luôn kể chuyện vui trong giờ học."}]','[{"phrase":"professor of"},{"phrase":"university professor"},{"phrase":"history professor"}]','Ở Mỹ, professor thường dùng chung cho giảng viên đại học','/prəˈfesər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/professor__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1794,'ngsl-4-09',22,'rare','hiếm; hiếm có; (thịt) tái','adjective','[{"en":"This plant is very rare and only grows in the mountains.","vi":"Loài cây này rất hiếm và chỉ mọc trên núi."},{"en":"It is rare for him to be late for work.","vi":"Hiếm khi anh ấy đi làm muộn."},{"en":"Could I have my steak rare, please?","vi":"Cho tôi món bít tết tái nhé."}]','[{"phrase":"extremely rare"},{"phrase":"rare species"},{"phrase":"it is rare for"}]',NULL,'/rer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rar/rare_/rare__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1795,'ngsl-4-09',23,'intention','ý định; dự định','noun','[{"en":"I have no intention of leaving my job right now.","vi":"Tôi không có ý định nghỉ việc lúc này."},{"en":"Her intention was to help, not to cause trouble.","vi":"Ý định của cô ấy là giúp đỡ, chứ không phải gây rắc rối."},{"en":"He announced his intention to study abroad next year.","vi":"Anh ấy thông báo dự định đi du học vào năm sau."}]','[{"phrase":"have no intention of"},{"phrase":"announce your intention"},{"phrase":"good intentions"}]','intention of doing / intention to do','/ɪnˈtenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intention__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1796,'ngsl-4-09',24,'dozen','tá (mười hai); hàng chục','noun','[{"en":"I bought a dozen eggs at the market this morning.","vi":"Sáng nay tôi mua một tá trứng ở chợ."},{"en":"There were dozens of people waiting outside the shop.","vi":"Có hàng chục người đang đợi bên ngoài cửa hàng."},{"en":"I''ve told you a dozen times to close the door.","vi":"Tôi đã bảo bạn cả chục lần là phải đóng cửa rồi."}]','[{"phrase":"a dozen eggs"},{"phrase":"dozens of"},{"phrase":"half a dozen"}]','a dozen eggs (không có ''of'') · dozens of people','/ˈdʌzn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doz/dozen/dozen__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1797,'ngsl-4-09',25,'settlement','sự thỏa thuận; sự dàn xếp; khu định cư','noun','[{"en":"The two companies finally reached a settlement after months of talks.","vi":"Hai công ty cuối cùng đã đạt được thỏa thuận sau nhiều tháng đàm phán."},{"en":"People built a small settlement beside the river long ago.","vi":"Từ rất lâu, người ta đã lập một khu định cư nhỏ bên sông."},{"en":"The fishing settlement slowly grew into a busy port town.","vi":"Khu định cư của dân chài dần phát triển thành một thị trấn cảng nhộn nhịp."}]','[{"phrase":"reach a settlement"},{"phrase":"out-of-court settlement"},{"phrase":"small settlement"}]',NULL,'/ˈsetlmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/set/settl/settlement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1798,'ngsl-4-09',26,'gap','khe hở; khoảng trống; khoảng cách','noun','[{"en":"The cat got out through a gap in the fence.","vi":"Con mèo chui ra ngoài qua một khe hở ở hàng rào."},{"en":"There is a big age gap between me and my brother.","vi":"Giữa tôi và anh trai có khoảng cách tuổi tác lớn."},{"en":"The gap between rich and poor is getting wider.","vi":"Khoảng cách giàu nghèo đang ngày càng lớn."}]','[{"phrase":"a gap in"},{"phrase":"age gap"},{"phrase":"gap between"},{"phrase":"fill the gap"}]',NULL,'/ɡæp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gap/gap__/gap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1799,'ngsl-4-09',27,'widely','rộng rãi; nhiều','adverb','[{"en":"English is widely spoken in this part of the city.","vi":"Tiếng Anh được sử dụng rộng rãi ở khu vực này của thành phố."},{"en":"This book is widely read by high school students.","vi":"Cuốn sách này được rất nhiều học sinh cấp ba đọc."},{"en":"Prices vary widely from one shop to another.","vi":"Giá cả chênh lệch nhiều giữa các cửa hàng."}]','[{"phrase":"widely used"},{"phrase":"widely available"},{"phrase":"vary widely"}]',NULL,'/ˈwaɪdli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wid/widel/widely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1800,'ngsl-4-09',28,'minimum','mức tối thiểu','noun','[{"en":"You need a minimum of three people to play this game.","vi":"Cần tối thiểu ba người để chơi trò này."},{"en":"Please keep the noise to a minimum; the baby is sleeping.","vi":"Hãy giữ tiếng ồn ở mức tối thiểu nhé; em bé đang ngủ."},{"en":"The course takes a minimum of two years to finish.","vi":"Khóa học cần tối thiểu hai năm để hoàn thành."}]','[{"phrase":"a minimum of"},{"phrase":"keep to a minimum"},{"phrase":"bare minimum"}]','minimum ≠ maximum (mức tối đa)','/ˈmɪnɪməm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minim/minimum__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1801,'ngsl-4-09',29,'northern','(thuộc) phía bắc; miền Bắc','adjective','[{"en":"They live in a small town in northern Vietnam.","vi":"Họ sống ở một thị trấn nhỏ ở miền Bắc Việt Nam."},{"en":"Winters in the northern part of the country are very cold.","vi":"Mùa đông ở phía bắc đất nước rất lạnh."},{"en":"We stayed at a hotel on the northern edge of the lake.","vi":"Chúng tôi ở một khách sạn nằm ở rìa phía bắc của hồ."}]','[{"phrase":"northern part"},{"phrase":"northern edge"},{"phrase":"northern border"}]',NULL,'/ˈnɔːrðərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/north/northern__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1802,'ngsl-4-09',30,'estate','bất động sản; điền trang; tài sản','noun','[{"en":"My uncle works in real estate in the city center.","vi":"Chú tôi làm trong ngành bất động sản ở trung tâm thành phố."},{"en":"The family owns a large tea estate in the hills.","vi":"Gia đình ấy sở hữu một đồn điền chè lớn trên đồi."},{"en":"Her grandfather left his whole estate to the local school.","vi":"Ông của cô ấy để lại toàn bộ tài sản cho trường học địa phương."}]','[{"phrase":"real estate"},{"phrase":"real estate agent"},{"phrase":"country estate"}]','real estate (Mỹ) = property (Anh): bất động sản','/ɪˈsteɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estat/estate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1803,'ngsl-4-10',1,'equally','như nhau; đều; bằng nhau','adverb','[{"en":"Please divide the cake equally between the four children.","vi":"Hãy chia đều chiếc bánh cho bốn đứa trẻ."},{"en":"Both teams played equally well in the second half.","vi":"Cả hai đội đều chơi hay như nhau trong hiệp hai."},{"en":"Sleep is equally important for adults and children.","vi":"Giấc ngủ quan trọng như nhau đối với người lớn và trẻ em."}]','[{"phrase":"equally important"},{"phrase":"equally well"},{"phrase":"divide equally"},{"phrase":"share equally"}]',NULL,'/ˈiːkwəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equal/equally__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1804,'ngsl-4-10',2,'expose','phơi ra; để lộ; vạch trần','verb','[{"en":"Babies shouldn''t be exposed to the sun for too long.","vi":"Không nên để trẻ sơ sinh phơi nắng quá lâu."},{"en":"Removing the old paint exposed the beautiful wood underneath.","vi":"Việc cạo lớp sơn cũ đã để lộ phần gỗ đẹp bên dưới."},{"en":"A young reporter exposed the company''s secret plan.","vi":"Một phóng viên trẻ đã vạch trần kế hoạch bí mật của công ty."}]','[{"phrase":"be exposed to"},{"phrase":"expose the truth"},{"phrase":"expose a secret"}]',NULL,'/ɪkˈspəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expos/expose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1805,'ngsl-4-10',3,'alive','còn sống; sôi động','adjective','[{"en":"My grandmother is still alive and very healthy at ninety.","vi":"Bà tôi vẫn còn sống và rất khỏe mạnh ở tuổi chín mươi."},{"en":"We need to water these plants to keep them alive.","vi":"Chúng ta cần tưới những cái cây này để giữ cho chúng sống."},{"en":"The city really comes alive at night.","vi":"Thành phố thực sự trở nên sôi động vào ban đêm."}]','[{"phrase":"still alive"},{"phrase":"stay alive"},{"phrase":"keep alive"},{"phrase":"come alive"}]','không đứng trước danh từ (dùng living: a living animal)','/əˈlaɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ali/alive/alive__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1806,'ngsl-4-10',4,'shut','đóng; nhắm lại; đóng cửa','verb','[{"en":"Please shut the door when you leave.","vi":"Làm ơn đóng cửa lại khi bạn ra ngoài."},{"en":"She shut her eyes and tried to sleep.","vi":"Cô ấy nhắm mắt lại và cố ngủ."},{"en":"Many small shops shut early on Sundays.","vi":"Nhiều cửa hàng nhỏ đóng cửa sớm vào Chủ nhật."}]','[{"phrase":"shut the door"},{"phrase":"shut your eyes"},{"phrase":"shut down"}]','shut – shut – shut','/ʃʌt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shu/shut_/shut__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1807,'ngsl-4-10',5,'victory','chiến thắng; thắng lợi','noun','[{"en":"The team celebrated their victory with a big dinner.","vi":"Cả đội ăn mừng chiến thắng bằng một bữa tối thịnh soạn."},{"en":"It was an easy victory for our school''s basketball team.","vi":"Đó là một chiến thắng dễ dàng cho đội bóng rổ của trường chúng tôi."},{"en":"After years of hard work, passing the exam felt like a real victory.","vi":"Sau nhiều năm nỗ lực, việc thi đỗ giống như một thắng lợi thật sự."}]','[{"phrase":"easy victory"},{"phrase":"win a victory"},{"phrase":"victory over"},{"phrase":"celebrate a victory"}]',NULL,'/ˈvɪktəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vic/victo/victory__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1808,'ngsl-4-10',6,'resolve','giải quyết; quyết tâm','verb','[{"en":"We need to resolve this problem before the end of the week.","vi":"Chúng ta cần giải quyết vấn đề này trước cuối tuần."},{"en":"The two neighbors finally resolved their argument about the fence.","vi":"Hai người hàng xóm cuối cùng đã giải quyết xong cuộc tranh cãi về hàng rào."},{"en":"She resolved to exercise every morning this year.","vi":"Cô ấy quyết tâm tập thể dục mỗi sáng trong năm nay."}]','[{"phrase":"resolve a problem"},{"phrase":"resolve an issue"},{"phrase":"resolve a dispute"},{"phrase":"resolve to do something"}]',NULL,'/rɪˈzɑːlv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resol/resolve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1809,'ngsl-4-10',7,'critic','nhà phê bình; người chỉ trích','noun','[{"en":"The film received excellent reviews from critics.","vi":"Bộ phim nhận được những lời đánh giá rất tốt từ các nhà phê bình."},{"en":"My brother is a food critic for a local newspaper.","vi":"Anh trai tôi là nhà phê bình ẩm thực cho một tờ báo địa phương."},{"en":"Critics of the plan say it will cost too much.","vi":"Những người chỉ trích kế hoạch nói rằng nó sẽ quá tốn kém."}]','[{"phrase":"food critic"},{"phrase":"film critic"},{"phrase":"harsh critic"},{"phrase":"critics say"}]','critic (người) ≠ criticism (lời phê bình)','/ˈkrɪtɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/critic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1810,'ngsl-4-10',8,'variable','hay thay đổi; không cố định; thất thường','adjective','[{"en":"The weather in the mountains is highly variable.","vi":"Thời tiết ở vùng núi rất hay thay đổi."},{"en":"Hotel prices are variable and depend on the season.","vi":"Giá khách sạn không cố định và phụ thuộc vào mùa."},{"en":"The quality of the food there is quite variable.","vi":"Chất lượng đồ ăn ở đó khá thất thường."}]','[{"phrase":"highly variable"},{"phrase":"variable costs"},{"phrase":"variable rate"}]',NULL,'/ˈveriəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/varia/variable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1811,'ngsl-4-10',9,'enormous','rất lớn; khổng lồ','adjective','[{"en":"They live in an enormous house near the river.","vi":"Họ sống trong một ngôi nhà rất lớn gần sông."},{"en":"Moving to a new country made an enormous difference to her life.","vi":"Chuyển đến một đất nước mới đã tạo ra thay đổi rất lớn trong cuộc sống của cô ấy."},{"en":"The waiter brought us an enormous plate of noodles.","vi":"Người phục vụ mang cho chúng tôi một đĩa mì khổng lồ."}]','[{"phrase":"enormous amount"},{"phrase":"enormous number"},{"phrase":"enormous difference"}]',NULL,'/ɪˈnɔːrməs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eno/enorm/enormous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1812,'ngsl-4-10',10,'sweet','ngọt; dễ thương','adjective','[{"en":"This cake is too sweet for me.","vi":"Cái bánh này quá ngọt đối với tôi."},{"en":"Ripe mangoes have a sweet taste and a lovely smell.","vi":"Xoài chín có vị ngọt và mùi thơm dễ chịu."},{"en":"It was really sweet of you to bring me flowers.","vi":"Bạn thật dễ thương khi mang hoa đến cho tôi."}]','[{"phrase":"sweet taste"},{"phrase":"sweet smell"},{"phrase":"have a sweet tooth"}]',NULL,'/swiːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swe/sweet/sweet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1813,'ngsl-4-10',11,'permanent','lâu dài; cố định; vĩnh viễn','adjective','[{"en":"After two years, she finally got a permanent job.","vi":"Sau hai năm, cuối cùng cô ấy cũng có được một công việc lâu dài."},{"en":"Are you looking for a temporary or permanent place to live?","vi":"Bạn đang tìm chỗ ở tạm thời hay lâu dài?"},{"en":"Coffee can leave a permanent stain on a white shirt.","vi":"Cà phê có thể để lại vết bẩn vĩnh viễn trên áo sơ mi trắng."}]','[{"phrase":"permanent job"},{"phrase":"permanent address"},{"phrase":"permanent damage"},{"phrase":"permanent resident"}]',NULL,'/ˈpɜːrmənənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perma/permanent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1814,'ngsl-4-10',12,'emotion','cảm xúc; sự xúc động','noun','[{"en":"He finds it hard to show his emotions.","vi":"Anh ấy thấy khó thể hiện cảm xúc của mình."},{"en":"Her voice was full of emotion when she thanked everyone.","vi":"Giọng cô ấy đầy xúc động khi cảm ơn mọi người."},{"en":"Try not to let your emotions control your decisions.","vi":"Cố gắng đừng để cảm xúc chi phối các quyết định của bạn."}]','[{"phrase":"full of emotion"},{"phrase":"show emotion"},{"phrase":"express emotions"},{"phrase":"strong emotions"}]',NULL,'/ɪˈməʊʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emo/emoti/emotion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1815,'ngsl-4-10',13,'pursue','theo đuổi; đuổi theo','verb','[{"en":"She left her office job to pursue a career in music.","vi":"Cô ấy bỏ công việc văn phòng để theo đuổi sự nghiệp âm nhạc."},{"en":"You should pursue your dreams while you are young.","vi":"Bạn nên theo đuổi ước mơ khi còn trẻ."},{"en":"The police pursued the stolen car through the city streets.","vi":"Cảnh sát đuổi theo chiếc xe bị đánh cắp qua các con phố trong thành phố."}]','[{"phrase":"pursue a career"},{"phrase":"pursue a dream"},{"phrase":"pursue a goal"}]',NULL,'/pərˈsuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/pursu/pursue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1816,'ngsl-4-10',14,'tall','cao','adjective','[{"en":"My son is already taller than me.","vi":"Con trai tôi đã cao hơn tôi rồi."},{"en":"How tall was your brother when he finished high school?","vi":"Anh trai bạn cao bao nhiêu khi học xong trung học?"},{"en":"There are many tall buildings in the city center.","vi":"Có nhiều tòa nhà cao tầng ở trung tâm thành phố."}]','[{"phrase":"tall building"},{"phrase":"tall tree"},{"phrase":"grow tall"},{"phrase":"tall and thin"}]','tall (người, cây, nhà cao) ≠ high (núi, tường, giá cả)','/tɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/tall_/tall__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1817,'ngsl-4-10',15,'urge','thúc giục; kêu gọi; khuyên','verb','[{"en":"My doctor urged me to stop drinking so much coffee.","vi":"Bác sĩ khuyên tôi ngừng uống nhiều cà phê như vậy."},{"en":"Teachers urged students to start studying early for the exam.","vi":"Giáo viên thúc giục học sinh bắt đầu ôn thi sớm."},{"en":"Local officials are urging people to save water this summer.","vi":"Chính quyền địa phương đang kêu gọi người dân tiết kiệm nước vào mùa hè này."}]','[{"phrase":"urge people to"},{"phrase":"strongly urge"},{"phrase":"urge caution"}]','urge somebody to do something','/ɜːrdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/urg/urge_/urge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1818,'ngsl-4-10',16,'enemy','kẻ thù; kẻ địch','noun','[{"en":"They were best friends, but now they are enemies.","vi":"Họ từng là bạn thân, nhưng giờ lại là kẻ thù."},{"en":"Sugar is the enemy of healthy teeth.","vi":"Đường là kẻ thù của hàm răng khỏe mạnh."},{"en":"Don''t make enemies at work; you may need their help later.","vi":"Đừng gây thù oán ở nơi làm việc; sau này bạn có thể cần họ giúp đỡ."}]','[{"phrase":"make enemies"},{"phrase":"worst enemy"},{"phrase":"old enemy"},{"phrase":"enemy of"}]',NULL,'/ˈenəmi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ene/enemy/enemy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1819,'ngsl-4-10',17,'appoint','bổ nhiệm; chỉ định','verb','[{"en":"The company appointed a new manager last month.","vi":"Công ty đã bổ nhiệm một quản lý mới vào tháng trước."},{"en":"She was appointed head of the science department.","vi":"Cô ấy được bổ nhiệm làm trưởng bộ môn khoa học."},{"en":"The school will appoint two teachers to organize the trip.","vi":"Nhà trường sẽ chỉ định hai giáo viên tổ chức chuyến đi."}]','[{"phrase":"appoint a new manager"},{"phrase":"newly appointed"},{"phrase":"appoint a committee"}]',NULL,'/əˈpɔɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appoi/appoint__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1820,'ngsl-4-10',18,'milk','sữa','noun','[{"en":"Could you buy some milk on your way home?","vi":"Bạn mua giúp ít sữa trên đường về nhà được không?"},{"en":"I always have a glass of warm milk before bed.","vi":"Tôi luôn uống một ly sữa ấm trước khi đi ngủ."},{"en":"Do you take milk and sugar in your coffee?","vi":"Bạn có cho sữa và đường vào cà phê không?"}]','[{"phrase":"warm milk"},{"phrase":"fresh milk"},{"phrase":"a glass of milk"},{"phrase":"a carton of milk"}]','không đếm được','/mɪlk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/milk_/milk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1821,'ngsl-4-10',19,'talent','tài năng; năng khiếu; người tài','noun','[{"en":"She has a real talent for drawing.","vi":"Cô ấy thật sự có năng khiếu vẽ."},{"en":"The show gives young people a chance to show their talents.","vi":"Chương trình cho người trẻ cơ hội thể hiện tài năng của mình."},{"en":"Our company is always looking for new talent.","vi":"Công ty chúng tôi luôn tìm kiếm nhân tài mới."}]','[{"phrase":"talent for"},{"phrase":"natural talent"},{"phrase":"hidden talent"},{"phrase":"young talent"}]',NULL,'/ˈtælənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/talen/talent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1822,'ngsl-4-10',20,'smell','ngửi thấy; có mùi','verb','[{"en":"The kitchen smells wonderful when my mother bakes bread.","vi":"Căn bếp thơm phức mỗi khi mẹ tôi nướng bánh mì."},{"en":"Can you smell something burning in here?","vi":"Bạn có ngửi thấy mùi gì đang cháy ở đây không?"},{"en":"These old shoes smell terrible, so please throw them away.","vi":"Đôi giày cũ này bốc mùi kinh khủng, nên làm ơn vứt chúng đi."}]','[{"phrase":"smell good"},{"phrase":"smell bad"},{"phrase":"smell something burning"},{"phrase":"smell of"}]','smell + tính từ: smell good (không dùng trạng từ)','/smel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sme/smell/smell__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1823,'ngsl-4-10',21,'prior','trước; có trước','adjective','[{"en":"No prior experience is needed for this job.","vi":"Công việc này không yêu cầu kinh nghiệm trước đó."},{"en":"Please arrive at the airport two hours prior to departure.","vi":"Vui lòng có mặt ở sân bay hai tiếng trước giờ khởi hành."},{"en":"She had no prior knowledge of the surprise party.","vi":"Cô ấy hoàn toàn không biết trước về bữa tiệc bất ngờ."}]','[{"phrase":"prior to"},{"phrase":"prior experience"},{"phrase":"prior knowledge"},{"phrase":"prior notice"}]','prior to = before (trang trọng hơn)','/ˈpraɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/prior__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1824,'ngsl-4-10',22,'priority','sự ưu tiên; điều ưu tiên','noun','[{"en":"My family has always been my top priority.","vi":"Gia đình luôn là ưu tiên hàng đầu của tôi."},{"en":"Safety is our first priority on every trip.","vi":"An toàn là ưu tiên số một của chúng tôi trong mọi chuyến đi."},{"en":"Older passengers are given priority when getting on the bus.","vi":"Hành khách lớn tuổi được ưu tiên khi lên xe buýt."}]','[{"phrase":"top priority"},{"phrase":"first priority"},{"phrase":"give priority to"},{"phrase":"high priority"}]',NULL,'/praɪˈɔːrəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/priority__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1825,'ngsl-4-10',23,'online','trực tuyến; trên mạng','adjective','[{"en":"Online shopping saves me a lot of time.","vi":"Mua sắm trực tuyến giúp tôi tiết kiệm nhiều thời gian."},{"en":"My daughter is taking an online English course this summer.","vi":"Con gái tôi đang học một khóa tiếng Anh trực tuyến vào mùa hè này."},{"en":"Most banks now offer online services to their customers.","vi":"Hầu hết ngân hàng hiện nay đều cung cấp dịch vụ trực tuyến cho khách hàng."}]','[{"phrase":"online shopping"},{"phrase":"online course"},{"phrase":"online services"},{"phrase":"go online"}]',NULL,'/ˌɑːnˈlaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/onl/onlin/online__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1826,'ngsl-4-10',24,'phrase','cụm từ; câu nói','noun','[{"en":"Write down any new words and phrases you hear in class.","vi":"Hãy ghi lại những từ và cụm từ mới bạn nghe được trong lớp."},{"en":"Can you explain what this phrase means?","vi":"Bạn có thể giải thích cụm từ này nghĩa là gì không?"},{"en":"Before the trip, I learned a few useful phrases in Japanese.","vi":"Trước chuyến đi, tôi đã học vài câu tiếng Nhật hữu ích."}]','[{"phrase":"useful phrase"},{"phrase":"common phrase"},{"phrase":"key phrase"}]',NULL,'/freɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phr/phras/phrase__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1827,'ngsl-4-10',25,'pilot','phi công','noun','[{"en":"My uncle has been an airline pilot for twenty years.","vi":"Chú tôi đã làm phi công hãng hàng không được hai mươi năm."},{"en":"The pilot told us to fasten our seat belts.","vi":"Phi công bảo chúng tôi thắt dây an toàn."},{"en":"She dreamed of becoming a pilot when she was a child.","vi":"Hồi nhỏ cô ấy mơ ước trở thành phi công."}]','[{"phrase":"airline pilot"},{"phrase":"helicopter pilot"},{"phrase":"become a pilot"}]',NULL,'/ˈpaɪlət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pil/pilot/pilot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1828,'ngsl-4-10',26,'stable','ổn định; vững chắc','adjective','[{"en":"After a few difficult years, he finally has a stable job.","vi":"Sau vài năm khó khăn, cuối cùng anh ấy đã có một công việc ổn định."},{"en":"Make sure the ladder is stable before you climb it.","vi":"Hãy chắc chắn cái thang đã vững trước khi bạn trèo lên."},{"en":"Children need a stable home where they feel safe.","vi":"Trẻ em cần một mái ấm ổn định, nơi chúng cảm thấy an toàn."}]','[{"phrase":"stable job"},{"phrase":"remain stable"},{"phrase":"stable condition"},{"phrase":"stable relationship"}]',NULL,'/ˈsteɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stabl/stable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1829,'ngsl-4-10',27,'merely','chỉ; chỉ là','adverb','[{"en":"I was merely asking a question; I didn''t mean to upset you.","vi":"Tôi chỉ hỏi một câu thôi; tôi không có ý làm bạn buồn."},{"en":"The trip is not merely a holiday but also a chance to learn.","vi":"Chuyến đi không chỉ là một kỳ nghỉ mà còn là cơ hội để học hỏi."},{"en":"It was merely a small mistake, so don''t worry about it.","vi":"Đó chỉ là một lỗi nhỏ thôi, nên đừng lo lắng về nó."}]','[{"phrase":"not merely"},{"phrase":"merely because"},{"phrase":"merely a matter of"}]','merely = only (trang trọng hơn)','/ˈmɪrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mer/merel/merely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1830,'ngsl-4-10',28,'resolution','quyết tâm; sự giải quyết; độ phân giải','noun','[{"en":"My New Year''s resolution is to read one book every month.","vi":"Quyết tâm năm mới của tôi là đọc một cuốn sách mỗi tháng."},{"en":"Both sides are hoping for a quick resolution to the problem.","vi":"Cả hai bên đều mong vấn đề sớm được giải quyết."},{"en":"This new phone takes photos with very high resolution.","vi":"Chiếc điện thoại mới này chụp ảnh với độ phân giải rất cao."}]','[{"phrase":"New Year''s resolution"},{"phrase":"make a resolution"},{"phrase":"high resolution"}]',NULL,'/ˌrezəˈluːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resol/resolution__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1831,'ngsl-4-10',29,'communicate','giao tiếp; truyền đạt; liên lạc','verb','[{"en":"We mostly communicate by email because we live in different countries.","vi":"Chúng tôi chủ yếu liên lạc qua email vì sống ở những nước khác nhau."},{"en":"Good managers communicate their ideas clearly to the team.","vi":"Những người quản lý giỏi truyền đạt ý tưởng của mình rõ ràng cho cả nhóm."},{"en":"Babies communicate with their parents by crying and smiling.","vi":"Trẻ sơ sinh giao tiếp với bố mẹ bằng cách khóc và cười."}]','[{"phrase":"communicate with"},{"phrase":"communicate clearly"},{"phrase":"communicate effectively"}]',NULL,'/kəˈmjuːnɪkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/communicate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1832,'ngsl-4-10',30,'injury','chấn thương; vết thương','noun','[{"en":"He missed three games because of a knee injury.","vi":"Anh ấy vắng mặt ba trận đấu vì chấn thương đầu gối."},{"en":"Luckily, nobody suffered serious injuries in the accident.","vi":"May mắn là không ai bị thương nặng trong vụ tai nạn."},{"en":"Always warm up before running to avoid injury.","vi":"Luôn khởi động trước khi chạy để tránh chấn thương."}]','[{"phrase":"serious injury"},{"phrase":"knee injury"},{"phrase":"suffer an injury"},{"phrase":"avoid injury"}]',NULL,'/ˈɪndʒəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inj/injur/injury__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1833,'ngsl-4-13',1,'mechanism','cơ chế; bộ phận máy','noun','[{"en":"The company has no mechanism for dealing with customer complaints.","vi":"Công ty không có cơ chế nào để xử lý khiếu nại của khách hàng."},{"en":"Scientists are still studying the mechanism that controls our sleep.","vi":"Các nhà khoa học vẫn đang nghiên cứu cơ chế điều khiển giấc ngủ của chúng ta."},{"en":"The locking mechanism on this door is broken again.","vi":"Bộ phận khóa của cánh cửa này lại bị hỏng rồi."}]','[{"phrase":"mechanism for"},{"phrase":"locking mechanism"},{"phrase":"control mechanism"}]',NULL,'/ˈmekənɪzəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mec/mecha/mechanism__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1834,'ngsl-4-13',2,'coat','áo khoác; lớp (sơn)','noun','[{"en":"Put on your coat, because it''s freezing outside.","vi":"Mặc áo khoác vào đi, vì ngoài trời lạnh cóng."},{"en":"She hung her wet coat on the hook by the door.","vi":"Cô ấy treo chiếc áo khoác ướt lên móc cạnh cửa."},{"en":"The fence needs another coat of paint before winter.","vi":"Hàng rào cần sơn thêm một lớp nữa trước mùa đông."}]','[{"phrase":"winter coat"},{"phrase":"put on a coat"},{"phrase":"coat of paint"}]',NULL,'/kəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coat_/coat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1835,'ngsl-4-13',3,'democracy','nền dân chủ; chế độ dân chủ','noun','[{"en":"Free elections are an important part of any democracy.","vi":"Bầu cử tự do là một phần quan trọng của bất kỳ nền dân chủ nào."},{"en":"Our history teacher explained how democracy began in ancient Greece.","vi":"Thầy dạy sử của chúng tôi giải thích nền dân chủ đã ra đời như thế nào ở Hy Lạp cổ đại."},{"en":"Many people believe that democracy works best when citizens are well informed.","vi":"Nhiều người tin rằng chế độ dân chủ vận hành tốt nhất khi người dân được cung cấp đầy đủ thông tin."}]','[{"phrase":"modern democracy"},{"phrase":"parliamentary democracy"},{"phrase":"democracy works"}]',NULL,'/dɪˈmɑːkrəsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/democ/democracy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1836,'ngsl-4-13',4,'pocket','túi (quần, áo)','noun','[{"en":"I found some old coins in my jacket pocket.","vi":"Tôi tìm thấy vài đồng xu cũ trong túi áo khoác."},{"en":"He just stood there with his hands in his pockets.","vi":"Anh ấy chỉ đứng đó, hai tay đút túi quần."},{"en":"Don''t keep your phone in your back pocket on the bus.","vi":"Đừng để điện thoại trong túi quần sau khi đi xe buýt."}]','[{"phrase":"back pocket"},{"phrase":"jacket pocket"},{"phrase":"hands in your pockets"}]',NULL,'/ˈpɑːkɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poc/pocke/pocket__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1837,'ngsl-4-13',5,'lucky','may mắn','adjective','[{"en":"We were lucky to find a parking space so close.","vi":"Chúng tôi thật may mắn khi tìm được chỗ đậu xe gần như vậy."},{"en":"Seven has always been my lucky number, so I chose it.","vi":"Số bảy luôn là con số may mắn của tôi, nên tôi đã chọn nó."},{"en":"You''re lucky that nobody was hurt in the accident.","vi":"Bạn may mắn là không ai bị thương trong vụ tai nạn."}]','[{"phrase":"lucky number"},{"phrase":"feel lucky"},{"phrase":"get lucky"},{"phrase":"lucky to"}]',NULL,'/ˈlʌki/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/luc/lucky/lucky__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1838,'ngsl-4-13',6,'crash','vụ va chạm, tai nạn (xe, máy bay); sự sập (máy tính)','noun','[{"en":"Two people were injured in a car crash last night.","vi":"Hai người bị thương trong một vụ tai nạn ô tô tối qua."},{"en":"Luckily, the driver walked away from the crash without a scratch.","vi":"May mắn thay, người lái xe thoát khỏi vụ va chạm mà không bị trầy xước gì."},{"en":"I lost my whole essay after a computer crash.","vi":"Tôi mất toàn bộ bài luận sau khi máy tính bị sập."}]','[{"phrase":"car crash"},{"phrase":"plane crash"},{"phrase":"computer crash"}]',NULL,'/kræʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/crash/crash__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1839,'ngsl-4-13',7,'observation','sự quan sát, theo dõi; nhận xét','noun','[{"en":"The patient stayed in the hospital overnight for observation.","vi":"Bệnh nhân ở lại bệnh viện qua đêm để theo dõi."},{"en":"Children learn a lot through careful observation of adults.","vi":"Trẻ em học được nhiều điều nhờ quan sát kỹ người lớn."},{"en":"She made an interesting observation about the new office layout.","vi":"Cô ấy đưa ra một nhận xét thú vị về cách bố trí văn phòng mới."}]','[{"phrase":"make an observation"},{"phrase":"careful observation"},{"phrase":"under observation"}]',NULL,'/ˌɑːbzərˈveɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obs/obser/observation__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1840,'ngsl-4-13',8,'meat','thịt','noun','[{"en":"I don''t eat much meat, but I love fish.","vi":"Tôi không ăn nhiều thịt, nhưng tôi rất thích cá."},{"en":"Cook the meat slowly over low heat until it''s soft.","vi":"Nấu thịt từ từ ở lửa nhỏ cho đến khi mềm."},{"en":"Fresh meat is sold at the market every morning.","vi":"Thịt tươi được bán ở chợ mỗi sáng."}]','[{"phrase":"red meat"},{"phrase":"fresh meat"},{"phrase":"eat meat"}]','Thường không đếm được','/miːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/meat_/meat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1841,'ngsl-4-13',9,'concentration','sự tập trung; nồng độ','noun','[{"en":"I lost concentration for a moment and missed the turn.","vi":"Tôi mất tập trung một chút và đi lỡ chỗ rẽ."},{"en":"This job requires a lot of patience and concentration.","vi":"Công việc này đòi hỏi nhiều sự kiên nhẫn và tập trung."},{"en":"The water in this lake has a high concentration of salt.","vi":"Nước trong hồ này có nồng độ muối cao."}]','[{"phrase":"lose concentration"},{"phrase":"high concentration"},{"phrase":"powers of concentration"}]',NULL,'/ˌkɑːnsnˈtreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcentration__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1842,'ngsl-4-13',10,'implication','hệ quả, tác động (có thể xảy ra); hàm ý','noun','[{"en":"We need to think about the implications of this decision.","vi":"Chúng ta cần nghĩ đến những hệ quả của quyết định này."},{"en":"The new law will have serious implications for small businesses.","vi":"Luật mới sẽ có tác động nghiêm trọng đến các doanh nghiệp nhỏ."},{"en":"I didn''t like the implication that I was lying.","vi":"Tôi không thích cái hàm ý rằng tôi đang nói dối."}]','[{"phrase":"serious implications"},{"phrase":"implications for"},{"phrase":"financial implications"}]','Thường dùng số nhiều: implications','/ˌɪmplɪˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impli/implication__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1843,'ngsl-4-13',11,'deserve','xứng đáng; đáng được','verb','[{"en":"You worked really hard, so you deserve a break.","vi":"Bạn đã làm việc rất chăm chỉ nên bạn xứng đáng được nghỉ ngơi."},{"en":"I think everyone deserves a second chance to get it right.","vi":"Tôi nghĩ ai cũng đáng được có cơ hội thứ hai để làm cho đúng."},{"en":"The team played well and deserved to win the game.","vi":"Đội đã chơi tốt và xứng đáng giành chiến thắng."}]','[{"phrase":"deserve a break"},{"phrase":"deserve a chance"},{"phrase":"deserve to win"},{"phrase":"deserve better"}]',NULL,'/dɪˈzɜːrv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/deser/deserve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1844,'ngsl-4-13',12,'unusual','bất thường; khác thường, lạ','adjective','[{"en":"It''s unusual for him to be late for work.","vi":"Việc anh ấy đi làm muộn là điều bất thường."},{"en":"People often ask me about my unusual name.","vi":"Mọi người thường hỏi tôi về cái tên lạ của tôi."},{"en":"The weather has been unusual this year, with very little rain.","vi":"Thời tiết năm nay thật bất thường, rất ít mưa."}]','[{"phrase":"unusual for"},{"phrase":"highly unusual"},{"phrase":"nothing unusual"}]',NULL,'/ʌnˈjuːʒuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unu/unusu/unusual__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1845,'ngsl-4-13',13,'defend','bảo vệ; bênh vực; phòng thủ','verb','[{"en":"Mother birds will defend their nests against larger animals.","vi":"Chim mẹ sẽ bảo vệ tổ của mình trước những con vật lớn hơn."},{"en":"He always defends his little sister when other kids tease her.","vi":"Cậu ấy luôn bênh vực em gái khi bọn trẻ khác trêu chọc cô bé."},{"en":"Our team needs to defend better in the second half.","vi":"Đội chúng ta cần phòng ngự tốt hơn trong hiệp hai."}]','[{"phrase":"defend yourself"},{"phrase":"defend against"},{"phrase":"defend a decision"}]',NULL,'/dɪˈfend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defen/defend__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1846,'ngsl-4-13',14,'classic','kinh điển; điển hình; cổ điển (kiểu dáng)','adjective','[{"en":"We watched a classic film from the 1950s last night.","vi":"Tối qua chúng tôi xem một bộ phim kinh điển từ thập niên 1950."},{"en":"That''s a classic example of poor planning.","vi":"Đó là một ví dụ điển hình của việc lên kế hoạch kém."},{"en":"She prefers classic clothes that never go out of style.","vi":"Cô ấy thích quần áo kiểu dáng cổ điển, không bao giờ lỗi mốt."}]','[{"phrase":"classic example"},{"phrase":"classic film"},{"phrase":"classic case"}]','classic ≠ classical (nhạc cổ điển: classical music)','/ˈklæsɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/classic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1847,'ngsl-4-13',15,'king','vua','noun','[{"en":"The king lived in a huge castle by the sea.","vi":"Nhà vua sống trong một lâu đài rộng lớn bên bờ biển."},{"en":"In chess, you win by trapping the other player''s king.","vi":"Trong cờ vua, bạn thắng bằng cách vây bắt quân vua của đối phương."},{"en":"My son loves stories about brave kings and queens.","vi":"Con trai tôi rất thích những câu chuyện về các vị vua và nữ hoàng dũng cảm."}]','[{"phrase":"king and queen"},{"phrase":"become king"},{"phrase":"the King of"}]',NULL,'/kɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kin/king_/king__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1848,'ngsl-4-13',16,'interaction','sự tương tác; sự giao tiếp','noun','[{"en":"Online classes offer less interaction between teachers and students.","vi":"Các lớp học trực tuyến có ít sự tương tác giữa giáo viên và học sinh hơn."},{"en":"Young children need daily interaction with other kids their age.","vi":"Trẻ nhỏ cần được giao tiếp hằng ngày với những đứa trẻ cùng tuổi."},{"en":"Your doctor will check for interactions between different medicines.","vi":"Bác sĩ sẽ kiểm tra sự tương tác giữa các loại thuốc khác nhau."}]','[{"phrase":"social interaction"},{"phrase":"interaction between"},{"phrase":"interaction with"},{"phrase":"face-to-face interaction"}]',NULL,'/ˌɪntərˈækʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interaction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1849,'ngsl-4-13',17,'repair','sửa chữa','verb','[{"en":"How much will it cost to repair the roof?","vi":"Sửa mái nhà sẽ tốn bao nhiêu tiền?"},{"en":"My dad repaired my bike in less than an hour.","vi":"Bố tôi sửa xe đạp cho tôi chưa đến một tiếng."},{"en":"The road is closed while workers repair the bridge.","vi":"Con đường bị phong tỏa trong lúc công nhân sửa cây cầu."}]','[{"phrase":"repair damage"},{"phrase":"repair the roof"},{"phrase":"get something repaired"}]',NULL,'/rɪˈper/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repai/repair__us_7.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1850,'ngsl-4-13',18,'collapse','sụp đổ, đổ sập; ngã quỵ','verb','[{"en":"The old bridge collapsed during the storm last night.","vi":"Cây cầu cũ bị sập trong cơn bão tối qua."},{"en":"After the long race, he collapsed onto the grass.","vi":"Sau cuộc đua dài, anh ấy ngã quỵ xuống bãi cỏ."},{"en":"Their small business collapsed after only two years.","vi":"Công việc kinh doanh nhỏ của họ sụp đổ chỉ sau hai năm."}]','[{"phrase":"collapse completely"},{"phrase":"roof collapsed"},{"phrase":"business collapsed"}]',NULL,'/kəˈlæps/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colla/collapse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1851,'ngsl-4-13',19,'borrow','mượn; vay','verb','[{"en":"Can I borrow your pen for a minute?","vi":"Mình mượn bút của bạn một lát được không?"},{"en":"We had to borrow money from the bank to buy the house.","vi":"Chúng tôi đã phải vay tiền ngân hàng để mua nhà."},{"en":"She borrowed three books from the library last week.","vi":"Tuần trước cô ấy đã mượn ba cuốn sách ở thư viện."}]','[{"phrase":"borrow money"},{"phrase":"borrow from"},{"phrase":"borrow a book"}]','borrow (mượn) ≠ lend (cho mượn)','/ˈbɔːrəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bor/borro/borrow__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1852,'ngsl-4-13',20,'fundamental','cơ bản, căn bản; nền tảng','adjective','[{"en":"Clean water is a fundamental human need.","vi":"Nước sạch là một nhu cầu cơ bản của con người."},{"en":"There is a fundamental difference between our two plans.","vi":"Có một sự khác biệt căn bản giữa hai kế hoạch của chúng ta."},{"en":"Reading is fundamental to success in every subject at school.","vi":"Việc đọc là nền tảng để học tốt mọi môn ở trường."}]','[{"phrase":"fundamental difference"},{"phrase":"fundamental change"},{"phrase":"fundamental to"},{"phrase":"fundamental rights"}]',NULL,'/ˌfʌndəˈmentl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funda/fundamental__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1853,'ngsl-4-13',21,'dish','món ăn; đĩa, bát đĩa','noun','[{"en":"Pho is probably the most famous Vietnamese dish.","vi":"Phở có lẽ là món ăn Việt Nam nổi tiếng nhất."},{"en":"Whose turn is it to wash the dishes tonight?","vi":"Tối nay đến lượt ai rửa bát đĩa?"},{"en":"Put the salad in a large dish and serve it cold.","vi":"Cho món salad vào một chiếc đĩa lớn và dùng lạnh."}]','[{"phrase":"wash the dishes"},{"phrase":"do the dishes"},{"phrase":"main dish"},{"phrase":"side dish"}]',NULL,'/dɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dish_/dish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1854,'ngsl-4-13',22,'abroad','ở nước ngoài; ra nước ngoài','adverb','[{"en":"My sister is planning to study abroad next year.","vi":"Chị gái tôi đang dự định đi du học vào năm tới."},{"en":"Have you ever traveled abroad on your own?","vi":"Bạn đã bao giờ tự mình đi nước ngoài chưa?"},{"en":"Many young people go abroad to find better jobs.","vi":"Nhiều người trẻ ra nước ngoài để tìm việc làm tốt hơn."}]','[{"phrase":"study abroad"},{"phrase":"travel abroad"},{"phrase":"go abroad"},{"phrase":"live abroad"}]','Không dùng "to": go abroad (không nói go to abroad)','/əˈbrɔːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abr/abroa/abroad__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1855,'ngsl-4-13',23,'soul','tâm hồn; linh hồn; người (không một ai)','noun','[{"en":"A quiet walk in nature is good for the soul.","vi":"Một buổi đi dạo yên tĩnh giữa thiên nhiên rất tốt cho tâm hồn."},{"en":"She puts her heart and soul into everything she does.","vi":"Cô ấy dồn hết tâm huyết vào mọi việc mình làm."},{"en":"It was so late that there wasn''t a soul on the street.","vi":"Trời đã khuya đến mức trên phố không có một bóng người."}]','[{"phrase":"heart and soul"},{"phrase":"not a soul"},{"phrase":"good for the soul"}]',NULL,'/səʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/soul_/soul__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1856,'ngsl-4-13',24,'capable','có khả năng; có năng lực, giỏi','adjective','[{"en":"I''m sure you''re capable of doing this job well.","vi":"Tôi chắc chắn bạn có đủ khả năng làm tốt công việc này."},{"en":"She is a very capable manager, and everyone trusts her.","vi":"Cô ấy là một người quản lý rất có năng lực, và ai cũng tin tưởng cô ấy."},{"en":"This car is capable of reaching very high speeds.","vi":"Chiếc xe này có thể đạt tốc độ rất cao."}]','[{"phrase":"capable of"},{"phrase":"highly capable"},{"phrase":"perfectly capable"}]','capable of + V-ing','/ˈkeɪpəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capab/capable__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1857,'ngsl-4-13',25,'defeat','đánh bại; thắng','verb','[{"en":"Our school team defeated last year''s champions in the final.","vi":"Đội trường chúng tôi đã đánh bại nhà vô địch năm ngoái trong trận chung kết."},{"en":"She defeated all the other players in the chess competition.","vi":"Cô ấy đã thắng tất cả những người chơi khác trong cuộc thi cờ vua."},{"en":"They were defeated three times before they finally won a game.","vi":"Họ đã bị đánh bại ba lần trước khi cuối cùng thắng được một trận."}]','[{"phrase":"defeat an opponent"},{"phrase":"easily defeat"},{"phrase":"narrowly defeated"}]',NULL,'/dɪˈfiːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defea/defeat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1858,'ngsl-4-13',26,'presidential','(thuộc) tổng thống','adjective','[{"en":"The presidential election takes place every four years.","vi":"Cuộc bầu cử tổng thống diễn ra bốn năm một lần."},{"en":"Crowds gathered outside the presidential palace to watch the ceremony.","vi":"Đám đông tụ tập bên ngoài dinh tổng thống để xem buổi lễ."},{"en":"Both presidential candidates will appear on TV tonight.","vi":"Cả hai ứng cử viên tổng thống sẽ xuất hiện trên truyền hình tối nay."}]','[{"phrase":"presidential election"},{"phrase":"presidential candidate"},{"phrase":"presidential campaign"}]',NULL,'/ˌprezɪˈdenʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presi/presidential__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1859,'ngsl-4-13',27,'perfectly','hoàn hảo; hoàn toàn','adverb','[{"en":"These shoes fit me perfectly, so I bought two pairs.","vi":"Đôi giày này vừa khít với chân tôi nên tôi đã mua hai đôi."},{"en":"It''s perfectly normal to feel nervous before an exam.","vi":"Cảm thấy lo lắng trước kỳ thi là hoàn toàn bình thường."},{"en":"He speaks English perfectly, but he has never lived abroad.","vi":"Anh ấy nói tiếng Anh hoàn hảo, dù chưa từng sống ở nước ngoài."}]','[{"phrase":"perfectly normal"},{"phrase":"fit perfectly"},{"phrase":"perfectly clear"},{"phrase":"work perfectly"}]',NULL,'/ˈpɜːrfɪktli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfe/perfectly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1860,'ngsl-4-13',28,'enhance','nâng cao; làm tăng (chất lượng, giá trị)','verb','[{"en":"A little lemon juice will enhance the flavor of the fish.","vi":"Một chút nước cốt chanh sẽ làm tăng hương vị của món cá."},{"en":"Taking this course could enhance your chances of getting a job.","vi":"Tham gia khóa học này có thể nâng cao cơ hội tìm được việc làm của bạn."},{"en":"Good lighting can greatly enhance the look of a room.","vi":"Ánh sáng tốt có thể làm căn phòng trông đẹp hơn rất nhiều."}]','[{"phrase":"greatly enhance"},{"phrase":"enhance the quality"},{"phrase":"enhance performance"},{"phrase":"enhance your chances"}]',NULL,'/ɪnˈhæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enh/enhan/enhance__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1861,'ngsl-4-13',29,'proud','tự hào; kiêu hãnh','adjective','[{"en":"My parents were very proud of me when I graduated.","vi":"Bố mẹ tôi rất tự hào về tôi khi tôi tốt nghiệp."},{"en":"You should be proud of what you''ve achieved this year.","vi":"Bạn nên tự hào về những gì mình đã đạt được trong năm nay."},{"en":"He was too proud to ask anyone for help.","vi":"Anh ấy quá kiêu hãnh nên không chịu nhờ ai giúp đỡ."}]','[{"phrase":"proud of"},{"phrase":"feel proud"},{"phrase":"proud moment"}]','be proud of sb/sth','/praʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proud/proud__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1862,'ngsl-4-13',30,'emergency','tình trạng khẩn cấp; trường hợp cấp cứu','noun','[{"en":"In an emergency, call this number right away.","vi":"Trong trường hợp khẩn cấp, hãy gọi ngay số này."},{"en":"The plane had to make an emergency landing in a field.","vi":"Chiếc máy bay đã phải hạ cánh khẩn cấp xuống một cánh đồng."},{"en":"She was taken to the emergency room after falling off her bike.","vi":"Cô ấy được đưa vào phòng cấp cứu sau khi ngã xe đạp."}]','[{"phrase":"in an emergency"},{"phrase":"emergency room"},{"phrase":"emergency exit"},{"phrase":"medical emergency"}]',NULL,'/ɪˈmɜːrdʒənsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eme/emerg/emergency__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1863,'ngsl-4-14',1,'educational','mang tính giáo dục; (thuộc) giáo dục','adjective','[{"en":"My kids watch an educational show about animals every morning.","vi":"Các con tôi xem một chương trình giáo dục về động vật mỗi sáng."},{"en":"The trip to the science museum was fun and very educational.","vi":"Chuyến đi đến bảo tàng khoa học vừa vui vừa rất bổ ích."},{"en":"She works for an educational organization that helps poor children.","vi":"Cô ấy làm việc cho một tổ chức giáo dục giúp đỡ trẻ em nghèo."}]','[{"phrase":"educational system"},{"phrase":"educational games"},{"phrase":"educational value"},{"phrase":"educational background"}]',NULL,'/ˌedʒuˈkeɪʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edu/educa/educational__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1864,'ngsl-4-14',2,'distinguish','phân biệt; nhận ra','verb','[{"en":"Young children often can''t distinguish between right and wrong.","vi":"Trẻ nhỏ thường không phân biệt được đúng và sai."},{"en":"It''s hard to distinguish the twins because they look so alike.","vi":"Thật khó phân biệt hai đứa sinh đôi vì chúng trông rất giống nhau."},{"en":"In the dark, I could barely distinguish the shape of the house.","vi":"Trong bóng tối, tôi hầu như không nhận ra được hình dáng ngôi nhà."}]','[{"phrase":"distinguish between"},{"phrase":"distinguish something from something"},{"phrase":"clearly distinguish"}]','distinguish A from B / distinguish between A and B','/dɪˈstɪŋɡwɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinguish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1865,'ngsl-4-14',3,'substantial','đáng kể; lớn','adjective','[{"en":"He received a substantial pay raise after his first year.","vi":"Anh ấy được tăng lương đáng kể sau năm đầu tiên."},{"en":"The storm caused substantial damage to homes along the coast.","vi":"Cơn bão gây thiệt hại đáng kể cho nhà cửa dọc bờ biển."},{"en":"We need a substantial amount of money to fix the roof.","vi":"Chúng tôi cần một khoản tiền lớn để sửa mái nhà."}]','[{"phrase":"substantial amount"},{"phrase":"substantial increase"},{"phrase":"substantial damage"},{"phrase":"substantial number"}]',NULL,'/səbˈstænʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substantial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1866,'ngsl-4-14',4,'nearby','gần đó; ở gần','adjective','[{"en":"We had lunch at a nearby café before the movie.","vi":"Chúng tôi ăn trưa ở một quán cà phê gần đó trước khi xem phim."},{"en":"Is there a pharmacy nearby where I can buy some medicine?","vi":"Có hiệu thuốc nào ở gần đây để tôi mua thuốc không?"},{"en":"Students from nearby towns take the bus to this school.","vi":"Học sinh từ các thị trấn lân cận đi xe buýt đến trường này."}]','[{"phrase":"nearby town"},{"phrase":"nearby village"},{"phrase":"live nearby"}]','Cũng dùng làm trạng từ: live nearby','/ˌnɪrˈbaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nea/nearb/nearby__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1867,'ngsl-4-14',5,'manufacturer','nhà sản xuất; hãng sản xuất','noun','[{"en":"If the phone breaks, send it back to the manufacturer.","vi":"Nếu điện thoại bị hỏng, hãy gửi nó lại cho nhà sản xuất."},{"en":"My uncle works for a large car manufacturer in Japan.","vi":"Chú tôi làm việc cho một hãng sản xuất ô tô lớn ở Nhật Bản."},{"en":"Always follow the manufacturer''s instructions when using this machine.","vi":"Luôn làm theo hướng dẫn của nhà sản xuất khi sử dụng máy này."}]','[{"phrase":"car manufacturer"},{"phrase":"leading manufacturer"},{"phrase":"manufacturer''s instructions"}]',NULL,'/ˌmænjuˈfæktʃərər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manuf/manufacturer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1868,'ngsl-4-14',6,'slide','trượt; lướt; luồn','verb','[{"en":"The kids love to slide down the snowy hill on plastic bags.","vi":"Bọn trẻ rất thích trượt xuống đồi tuyết trên những chiếc túi nhựa."},{"en":"She slid the letter under the door and walked away.","vi":"Cô ấy luồn lá thư qua khe cửa rồi bỏ đi."},{"en":"The door slides open when you step in front of it.","vi":"Cánh cửa tự trượt mở khi bạn bước tới trước nó."}]','[{"phrase":"slide down"},{"phrase":"slide open"},{"phrase":"slide into"},{"phrase":"sliding door"}]','slide – slid – slid','/slaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/slide/slide__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1869,'ngsl-4-14',7,'valuable','có giá trị; quý giá','adjective','[{"en":"Don''t leave anything valuable in your car overnight.","vi":"Đừng để bất cứ thứ gì có giá trị trong xe qua đêm."},{"en":"Working in a hotel gave me valuable experience with customers.","vi":"Làm việc ở khách sạn đã cho tôi kinh nghiệm quý giá khi tiếp xúc với khách hàng."},{"en":"Thank you for your time; I know it''s very valuable.","vi":"Cảm ơn bạn đã dành thời gian; tôi biết thời gian của bạn rất quý."}]','[{"phrase":"valuable experience"},{"phrase":"valuable information"},{"phrase":"valuable time"},{"phrase":"extremely valuable"}]',NULL,'/ˈvæljuəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/valua/valuable__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1870,'ngsl-4-14',8,'personally','về phần cá nhân; đích thân; trực tiếp','adverb','[{"en":"Personally, I prefer the beach to the mountains.","vi":"Cá nhân tôi thì thích biển hơn núi."},{"en":"The manager came personally to apologize for the mistake.","vi":"Người quản lý đã đích thân đến xin lỗi về sai sót đó."},{"en":"I''ve never met her personally, but we often talk online.","vi":"Tôi chưa bao giờ gặp trực tiếp cô ấy, nhưng chúng tôi hay nói chuyện trên mạng."}]','[{"phrase":"personally responsible"},{"phrase":"know someone personally"},{"phrase":"take it personally"}]','take something personally: để bụng, cho là nhắm vào mình','/ˈpɜːrsənəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personally__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1871,'ngsl-4-14',9,'breast','ngực; vú; ức (gà)','noun','[{"en":"I bought some chicken breast to make a salad for dinner.","vi":"Tôi mua một ít ức gà để làm món salad cho bữa tối."},{"en":"Doctors say breast milk is the best food for babies.","vi":"Các bác sĩ nói sữa mẹ là thức ăn tốt nhất cho trẻ sơ sinh."},{"en":"The small bird had a bright red breast and gray wings.","vi":"Con chim nhỏ có phần ngực màu đỏ tươi và đôi cánh màu xám."}]','[{"phrase":"chicken breast"},{"phrase":"breast milk"},{"phrase":"breast pocket"}]',NULL,'/brest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breas/breast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1872,'ngsl-4-14',10,'cope','đối phó; đương đầu; xoay xở','verb','[{"en":"How do you cope with stress when work gets busy?","vi":"Bạn đối phó với căng thẳng thế nào khi công việc bận rộn?"},{"en":"Living alone in a new country was hard, but she learned to cope.","vi":"Sống một mình ở đất nước mới rất vất vả, nhưng cô ấy đã học được cách xoay xở."},{"en":"The small hospital couldn''t cope with so many patients.","vi":"Bệnh viện nhỏ không thể xoay xở nổi với quá nhiều bệnh nhân."}]','[{"phrase":"cope with stress"},{"phrase":"cope with pressure"},{"phrase":"learn to cope"},{"phrase":"struggle to cope"}]','cope with something','/kəʊp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cop/cope_/cope__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1873,'ngsl-4-14',11,'approximately','khoảng; xấp xỉ','adverb','[{"en":"The flight takes approximately three hours from here.","vi":"Chuyến bay từ đây mất khoảng ba tiếng."},{"en":"Approximately half of the students live in the city.","vi":"Xấp xỉ một nửa số sinh viên sống trong thành phố."},{"en":"The house was built approximately one hundred years ago.","vi":"Ngôi nhà được xây dựng cách đây khoảng một trăm năm."}]','[{"phrase":"approximately equal"},{"phrase":"approximately half"},{"phrase":"at approximately"}]',NULL,'/əˈprɑːksɪmətli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approximately__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1874,'ngsl-4-14',12,'accommodation','chỗ ở; nơi ăn ở','noun','[{"en":"The price of the tour includes flights and accommodation.","vi":"Giá tour đã bao gồm vé máy bay và chỗ ở."},{"en":"Finding cheap accommodation near the university is not easy.","vi":"Tìm chỗ ở giá rẻ gần trường đại học không hề dễ."},{"en":"We booked our accommodation online two months before the trip.","vi":"Chúng tôi đặt chỗ ở trên mạng hai tháng trước chuyến đi."}]','[{"phrase":"find accommodation"},{"phrase":"cheap accommodation"},{"phrase":"hotel accommodation"},{"phrase":"book accommodation"}]','Anh: không đếm được (accommodation) · Mỹ: thường dùng accommodations','/əˌkɑːməˈdeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accommodation__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1875,'ngsl-4-14',13,'highlight','làm nổi bật; nhấn mạnh; tô sáng','verb','[{"en":"The report highlights the need for more teachers in rural areas.","vi":"Bản báo cáo nhấn mạnh nhu cầu cần thêm giáo viên ở vùng nông thôn."},{"en":"Please highlight the important words in yellow.","vi":"Hãy tô sáng những từ quan trọng bằng màu vàng."},{"en":"Her speech highlighted the problems that young workers face today.","vi":"Bài phát biểu của cô ấy làm nổi bật những vấn đề người lao động trẻ gặp phải ngày nay."}]','[{"phrase":"highlight the need"},{"phrase":"highlight the importance"},{"phrase":"highlight the problem"}]','Danh từ: highlight = điểm nổi bật (the highlight of the trip)','/ˈhaɪlaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/highl/highlight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1876,'ngsl-4-14',14,'reporter','phóng viên','noun','[{"en":"A reporter asked the mayor about the new bridge.","vi":"Một phóng viên đã hỏi thị trưởng về cây cầu mới."},{"en":"She worked as a sports reporter for a local newspaper.","vi":"Cô ấy từng làm phóng viên thể thao cho một tờ báo địa phương."},{"en":"Reporters were waiting outside the hospital all night.","vi":"Các phóng viên đã chờ bên ngoài bệnh viện suốt đêm."}]','[{"phrase":"newspaper reporter"},{"phrase":"TV reporter"},{"phrase":"sports reporter"},{"phrase":"tell reporters"}]',NULL,'/rɪˈpɔːrtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repor/reporter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1877,'ngsl-4-14',15,'climate','khí hậu; tình hình','noun','[{"en":"My grandparents moved south because they wanted a warmer climate.","vi":"Ông bà tôi chuyển xuống phía nam vì muốn sống ở nơi khí hậu ấm hơn."},{"en":"Climate change is making summers hotter every year.","vi":"Biến đổi khí hậu đang khiến mùa hè mỗi năm một nóng hơn."},{"en":"In the current economic climate, many people are afraid to spend money.","vi":"Trong tình hình kinh tế hiện nay, nhiều người ngại tiêu tiền."}]','[{"phrase":"climate change"},{"phrase":"warm climate"},{"phrase":"economic climate"},{"phrase":"tropical climate"}]',NULL,'/ˈklaɪmət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/clima/climate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1878,'ngsl-4-14',16,'shirt','áo sơ mi; áo','noun','[{"en":"He wore a white shirt and a tie to the interview.","vi":"Anh ấy mặc áo sơ mi trắng và thắt cà vạt đi phỏng vấn."},{"en":"Can you iron my shirt while I take a shower?","vi":"Bạn ủi giúp tôi cái áo sơ mi trong lúc tôi tắm được không?"},{"en":"I spilled coffee on my shirt this morning.","vi":"Sáng nay tôi làm đổ cà phê lên áo."}]','[{"phrase":"wear a shirt"},{"phrase":"white shirt"},{"phrase":"iron a shirt"},{"phrase":"long-sleeved shirt"}]',NULL,'/ʃɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shirt/shirt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1879,'ngsl-4-14',17,'exception','ngoại lệ; trường hợp ngoại lệ','noun','[{"en":"Everyone must arrive by eight, and there are no exceptions.","vi":"Mọi người phải có mặt trước tám giờ, không có ngoại lệ."},{"en":"With the exception of two students, the whole class passed the test.","vi":"Ngoại trừ hai học sinh, cả lớp đều qua bài kiểm tra."},{"en":"We don''t usually allow pets, but we''ll make an exception for you.","vi":"Chúng tôi thường không cho mang thú cưng, nhưng sẽ ngoại lệ cho bạn."}]','[{"phrase":"make an exception"},{"phrase":"with the exception of"},{"phrase":"no exception"},{"phrase":"exception to the rule"}]',NULL,'/ɪkˈsepʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excep/exception__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1880,'ngsl-4-14',18,'corporation','tập đoàn; công ty lớn','noun','[{"en":"My father worked for a large corporation for thirty years.","vi":"Bố tôi làm việc cho một tập đoàn lớn suốt ba mươi năm."},{"en":"Some people think big corporations should pay more tax.","vi":"Một số người cho rằng các tập đoàn lớn nên đóng thuế nhiều hơn."},{"en":"The corporation plans to open two new factories next year.","vi":"Tập đoàn dự định mở hai nhà máy mới vào năm tới."}]','[{"phrase":"large corporation"},{"phrase":"multinational corporation"},{"phrase":"big corporations"}]',NULL,'/ˌkɔːrpəˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corpo/corporation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1881,'ngsl-4-14',19,'chip','khoai tây chiên; con chip (điện tử); vết mẻ','noun','[{"en":"We ate fish and chips by the sea.","vi":"Chúng tôi ăn cá và khoai tây chiên bên bờ biển."},{"en":"Every new phone has a tiny computer chip inside it.","vi":"Mỗi chiếc điện thoại mới đều có một con chip máy tính nhỏ xíu bên trong."},{"en":"There''s a small chip on the edge of this cup.","vi":"Có một vết mẻ nhỏ trên miệng chiếc cốc này."}]','[{"phrase":"fish and chips"},{"phrase":"potato chips"},{"phrase":"computer chip"},{"phrase":"chocolate chip"}]','Anh: chips = khoai tây chiên que · Mỹ: chips = khoai tây chiên lát mỏng (Anh gọi crisps)','/tʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/chip_/chip__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1882,'ngsl-4-14',20,'winner','người chiến thắng; người đoạt giải','noun','[{"en":"The winner of the race will get a gold medal.","vi":"Người chiến thắng cuộc đua sẽ nhận được huy chương vàng."},{"en":"They will announce the winners at the end of the evening.","vi":"Họ sẽ công bố những người đoạt giải vào cuối buổi tối."},{"en":"My sister was the lucky winner of a free trip to Paris.","vi":"Chị tôi là người may mắn trúng một chuyến du lịch miễn phí đến Paris."}]','[{"phrase":"the winner of"},{"phrase":"announce the winner"},{"phrase":"lucky winner"},{"phrase":"prize winner"}]',NULL,'/ˈwɪnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/winne/winner__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1883,'ngsl-4-14',21,'encounter','gặp phải; bắt gặp; cuộc chạm trán','verb','[{"en":"We encountered a few problems when we moved to a new house.","vi":"Chúng tôi gặp phải một vài vấn đề khi chuyển sang nhà mới."},{"en":"Call me if you encounter any difficulties with the software.","vi":"Gọi cho tôi nếu bạn gặp bất kỳ khó khăn nào với phần mềm."},{"en":"I had a strange encounter with a stranger on the train.","vi":"Tôi đã có một cuộc gặp gỡ kỳ lạ với một người lạ trên tàu."}]','[{"phrase":"encounter problems"},{"phrase":"encounter difficulties"},{"phrase":"chance encounter"}]',NULL,'/ɪnˈkaʊntər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enc/encou/encounter__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1884,'ngsl-4-14',22,'brown','màu nâu; nâu','adjective','[{"en":"She has long brown hair and green eyes.","vi":"Cô ấy có mái tóc dài màu nâu và đôi mắt xanh lục."},{"en":"I usually eat brown rice because it''s healthier.","vi":"Tôi thường ăn gạo lứt vì nó tốt cho sức khỏe hơn."},{"en":"The leaves turn brown and fall in autumn.","vi":"Lá cây chuyển sang màu nâu và rụng vào mùa thu."}]','[{"phrase":"brown hair"},{"phrase":"brown eyes"},{"phrase":"brown rice"},{"phrase":"turn brown"}]','brown rice: gạo lứt; brown bread: bánh mì nâu (nguyên cám)','/braʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/brown/brown__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1885,'ngsl-4-14',23,'breathe','thở; hít thở','verb','[{"en":"Close your eyes and breathe slowly to relax.","vi":"Hãy nhắm mắt lại và thở chậm để thư giãn."},{"en":"It was so smoky in the kitchen that I couldn''t breathe.","vi":"Trong bếp nhiều khói đến mức tôi không thở được."},{"en":"I love breathing the fresh air in the mountains.","vi":"Tôi thích hít thở không khí trong lành trên núi."}]','[{"phrase":"breathe deeply"},{"phrase":"breathe in"},{"phrase":"breathe out"},{"phrase":"breathe fresh air"}]','breathe (v) ≠ breath (n): hơi thở','/briːð/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breat/breathe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1886,'ngsl-4-14',24,'excuse','lời bào chữa; cái cớ; lý do','noun','[{"en":"He always has an excuse for being late to work.","vi":"Anh ta lúc nào cũng có cớ cho việc đi làm muộn."},{"en":"Being tired is no excuse for being rude to people.","vi":"Mệt mỏi không phải là lý do để thô lỗ với người khác."},{"en":"She made an excuse and left the party early.","vi":"Cô ấy viện cớ rồi rời bữa tiệc sớm."}]','[{"phrase":"make an excuse"},{"phrase":"good excuse"},{"phrase":"no excuse for"},{"phrase":"excuse me"}]','Danh từ /ɪkˈskjuːs/ · động từ /ɪkˈskjuːz/','/ɪkˈskjuːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excus/excuse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1887,'ngsl-4-14',25,'partly','một phần; phần nào','adverb','[{"en":"The accident was partly my fault, and I''m sorry.","vi":"Vụ tai nạn một phần là lỗi của tôi, và tôi xin lỗi."},{"en":"Tomorrow will be partly cloudy with a chance of rain.","vi":"Ngày mai trời có mây rải rác và có khả năng mưa."},{"en":"I moved to the city partly because of my job.","vi":"Tôi chuyển lên thành phố một phần là vì công việc."}]','[{"phrase":"partly because"},{"phrase":"partly responsible"},{"phrase":"partly cloudy"},{"phrase":"partly due to"}]',NULL,'/ˈpɑːrtli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partl/partly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1888,'ngsl-4-14',26,'tennis','quần vợt; tennis','noun','[{"en":"My brother and I play tennis every Saturday morning.","vi":"Anh trai tôi và tôi chơi quần vợt vào mỗi sáng thứ Bảy."},{"en":"The hotel has a pool and two tennis courts.","vi":"Khách sạn có một hồ bơi và hai sân quần vợt."},{"en":"She started taking tennis lessons when she was six.","vi":"Cô ấy bắt đầu học quần vợt từ năm sáu tuổi."}]','[{"phrase":"play tennis"},{"phrase":"tennis court"},{"phrase":"tennis player"},{"phrase":"tennis match"}]','play tennis (không dùng the)','/ˈtenɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tenni/tennis__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1889,'ngsl-4-14',27,'urban','(thuộc) đô thị; thành thị','adjective','[{"en":"More and more people are moving from villages to urban areas.","vi":"Ngày càng nhiều người chuyển từ làng quê ra các khu đô thị."},{"en":"Traffic is one of the biggest problems of urban life.","vi":"Giao thông là một trong những vấn đề lớn nhất của cuộc sống đô thị."},{"en":"Urban families often live in small apartments.","vi":"Các gia đình ở thành thị thường sống trong những căn hộ nhỏ."}]','[{"phrase":"urban areas"},{"phrase":"urban life"},{"phrase":"urban population"},{"phrase":"urban development"}]','urban ≠ rural (nông thôn)','/ˈɜːrbən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/urb/urban/urban__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1890,'ngsl-4-14',28,'confuse','làm bối rối; nhầm lẫn','verb','[{"en":"The new instructions only confused me more.","vi":"Hướng dẫn mới chỉ càng làm tôi bối rối hơn."},{"en":"People often confuse me with my twin sister.","vi":"Mọi người hay nhầm tôi với chị em sinh đôi của tôi."},{"en":"Don''t confuse the words ''desert'' and ''dessert'' in your essay.","vi":"Đừng nhầm lẫn hai từ ''desert'' và ''dessert'' trong bài luận của bạn."}]','[{"phrase":"confuse A with B"},{"phrase":"get confused"},{"phrase":"confuse the issue"}]','confuse A with B: nhầm A với B','/kənˈfjuːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfuse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1891,'ngsl-4-14',29,'southern','(thuộc) phía nam; miền Nam','adjective','[{"en":"We spent our holiday on a beach in southern Thailand.","vi":"Chúng tôi đã nghỉ lễ ở một bãi biển phía nam Thái Lan."},{"en":"The southern part of the country is hot all year.","vi":"Phần phía nam của đất nước nóng quanh năm."},{"en":"My friend speaks with a strong southern accent.","vi":"Bạn tôi nói giọng miền Nam rất đặc trưng."}]','[{"phrase":"southern part"},{"phrase":"southern coast"},{"phrase":"southern accent"},{"phrase":"southern border"}]',NULL,'/ˈsʌðərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sou/south/southern__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1892,'ngsl-4-14',30,'output','sản lượng; đầu ra','noun','[{"en":"The factory''s output has doubled since last year.","vi":"Sản lượng của nhà máy đã tăng gấp đôi kể từ năm ngoái."},{"en":"Rice output was low this year because of the dry weather.","vi":"Sản lượng lúa năm nay thấp do thời tiết khô hạn."},{"en":"Check the output of the program to see if there are any errors.","vi":"Hãy kiểm tra đầu ra của chương trình để xem có lỗi nào không."}]','[{"phrase":"increase output"},{"phrase":"total output"},{"phrase":"industrial output"},{"phrase":"power output"}]',NULL,'/ˈaʊtpʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outpu/output__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1893,'ngsl-4-15',1,'beauty','vẻ đẹp; cái đẹp','noun','[{"en":"We stopped the car to enjoy the beauty of the mountains.","vi":"Chúng tôi dừng xe để ngắm vẻ đẹp của núi non."},{"en":"Her paintings capture the simple beauty of everyday life.","vi":"Những bức tranh của cô ấy ghi lại vẻ đẹp giản dị của cuộc sống thường ngày."},{"en":"This old town is famous for its natural beauty and quiet streets.","vi":"Thị trấn cổ này nổi tiếng với vẻ đẹp tự nhiên và những con phố yên tĩnh."}]','[{"phrase":"natural beauty"},{"phrase":"great beauty"},{"phrase":"the beauty of"}]',NULL,'/ˈbjuːti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bea/beaut/beauty__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1894,'ngsl-4-15',2,'massive','to lớn; đồ sộ','adjective','[{"en":"A massive tree fell across the road during the storm.","vi":"Một cái cây to lớn đổ chắn ngang đường trong cơn bão."},{"en":"The new shopping center is massive, so wear comfortable shoes.","vi":"Trung tâm mua sắm mới rất đồ sộ, nên hãy mang giày thoải mái."},{"en":"Moving to another country was a massive change for our family.","vi":"Chuyển sang nước khác là một thay đổi to lớn đối với gia đình chúng tôi."}]','[{"phrase":"massive amount"},{"phrase":"massive change"},{"phrase":"massive building"}]',NULL,'/ˈmæsɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mas/massi/massive__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1895,'ngsl-4-15',3,'install','lắp đặt; cài đặt','verb','[{"en":"We''re having a new air conditioner installed next week.","vi":"Tuần sau chúng tôi sẽ cho lắp đặt một máy điều hòa mới."},{"en":"You need to install the app before you can join the meeting.","vi":"Bạn cần cài đặt ứng dụng trước khi có thể tham gia cuộc họp."},{"en":"My dad installed a small camera above the front door.","vi":"Bố tôi đã lắp một chiếc camera nhỏ phía trên cửa trước."}]','[{"phrase":"install software"},{"phrase":"install an app"},{"phrase":"install a system"}]',NULL,'/ɪnˈstɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insta/install__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1896,'ngsl-4-15',4,'calculate','tính toán; tính','verb','[{"en":"Can you calculate how much we spent on food this month?","vi":"Bạn có thể tính xem tháng này chúng ta đã tiêu bao nhiêu tiền ăn không?"},{"en":"The app calculates the distance you walk every day.","vi":"Ứng dụng tính quãng đường bạn đi bộ mỗi ngày."},{"en":"She carefully calculated the cost before booking the trip.","vi":"Cô ấy đã tính toán kỹ chi phí trước khi đặt chuyến đi."}]','[{"phrase":"calculate the cost"},{"phrase":"calculate the distance"},{"phrase":"carefully calculate"}]',NULL,'/ˈkælkjuleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cal/calcu/calculate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1897,'ngsl-4-15',5,'mouse','con chuột; chuột máy tính','noun','[{"en":"My little sister screamed when she saw a mouse in the kitchen.","vi":"Em gái tôi hét lên khi thấy một con chuột trong bếp."},{"en":"Our cat caught two mice in the garden yesterday.","vi":"Hôm qua con mèo nhà tôi bắt được hai con chuột trong vườn."},{"en":"Click the right mouse button to open the menu.","vi":"Nhấp chuột phải để mở menu."}]','[{"phrase":"computer mouse"},{"phrase":"mouse button"},{"phrase":"click the mouse"}]','số nhiều: mice','/maʊs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mouse/mouse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1898,'ngsl-4-15',6,'mathematics','toán học','noun','[{"en":"He studied mathematics at university and now teaches at a high school.","vi":"Anh ấy học toán ở đại học và giờ dạy ở một trường cấp ba."},{"en":"Mathematics was always my favorite subject at school.","vi":"Toán luôn là môn học yêu thích của tôi ở trường."},{"en":"You need basic mathematics to manage your money well.","vi":"Bạn cần kiến thức toán học cơ bản để quản lý tiền bạc tốt."}]','[{"phrase":"study mathematics"},{"phrase":"basic mathematics"},{"phrase":"mathematics teacher"}]','không đếm được; viết tắt: math (Mỹ), maths (Anh)','/ˌmæθəˈmætɪks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/mathe/mathematics__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1899,'ngsl-4-15',7,'upper','phía trên; cao hơn','adjective','[{"en":"Our apartment is on the upper floor, so it''s quite quiet.","vi":"Căn hộ của chúng tôi ở tầng trên nên khá yên tĩnh."},{"en":"He hurt his upper arm while playing basketball.","vi":"Anh ấy bị đau phần cánh tay trên khi chơi bóng rổ."},{"en":"Please write your name in the upper corner of the page.","vi":"Hãy viết tên bạn ở góc trên của trang giấy."}]','[{"phrase":"upper floor"},{"phrase":"upper arm"},{"phrase":"upper body"},{"phrase":"upper class"}]',NULL,'/ˈʌpər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/upp/upper/upper__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1900,'ngsl-4-15',8,'creation','sự tạo ra; tác phẩm','noun','[{"en":"The new factory will lead to the creation of hundreds of jobs.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm."},{"en":"This cake is the chef''s latest creation.","vi":"Chiếc bánh này là tác phẩm mới nhất của đầu bếp."},{"en":"She has been involved in the creation of the website from the start.","vi":"Cô ấy đã tham gia xây dựng trang web ngay từ đầu."}]','[{"phrase":"job creation"},{"phrase":"the creation of"},{"phrase":"latest creation"}]',NULL,'/kriˈeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/creation__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1901,'ngsl-4-15',9,'occupy','chiếm; sử dụng; làm bận rộn','verb','[{"en":"All the seats near the window were already occupied.","vi":"Tất cả chỗ ngồi gần cửa sổ đều đã có người ngồi."},{"en":"Our office occupies the second floor of the building.","vi":"Văn phòng của chúng tôi chiếm tầng hai của tòa nhà."},{"en":"I bring a few books to keep the kids occupied on long trips.","vi":"Tôi mang theo vài cuốn sách để bọn trẻ có việc làm trong những chuyến đi dài."}]','[{"phrase":"occupy a seat"},{"phrase":"occupy a building"},{"phrase":"keep someone occupied"}]',NULL,'/ˈɑːkjupaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occup/occupy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1902,'ngsl-4-15',10,'outline','dàn ý; nét chính; đường nét','noun','[{"en":"Write a short outline before you start your essay.","vi":"Hãy viết một dàn ý ngắn trước khi bắt đầu bài luận."},{"en":"The manager gave us a brief outline of the new plan.","vi":"Người quản lý đã trình bày ngắn gọn những nét chính của kế hoạch mới."},{"en":"In the fog, we could only see the outline of the bridge.","vi":"Trong sương mù, chúng tôi chỉ nhìn thấy đường nét của cây cầu."}]','[{"phrase":"brief outline"},{"phrase":"rough outline"},{"phrase":"the outline of"}]',NULL,'/ˈaʊtlaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outli/outline__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1903,'ngsl-4-15',11,'sufficient','đủ','adjective','[{"en":"We don''t have sufficient time to finish the project this week.","vi":"Chúng tôi không có đủ thời gian để hoàn thành dự án trong tuần này."},{"en":"Two hours of practice a day should be sufficient.","vi":"Mỗi ngày luyện tập hai tiếng là đủ."},{"en":"The hotel room was small but sufficient for a short stay.","vi":"Phòng khách sạn nhỏ nhưng đủ cho một kỳ nghỉ ngắn."}]','[{"phrase":"sufficient time"},{"phrase":"sufficient money"},{"phrase":"sufficient evidence"}]',NULL,'/səˈfɪʃnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suf/suffi/sufficient__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1904,'ngsl-4-15',12,'update','cập nhật; báo tin mới','verb','[{"en":"Please update your phone to the latest version.","vi":"Vui lòng cập nhật điện thoại của bạn lên phiên bản mới nhất."},{"en":"I''ll update you when I hear back from the doctor.","vi":"Tôi sẽ báo tin cho bạn khi có hồi âm từ bác sĩ."},{"en":"The company updates its website almost every day.","vi":"Công ty cập nhật trang web gần như mỗi ngày."}]','[{"phrase":"update software"},{"phrase":"update a website"},{"phrase":"keep someone updated"}]',NULL,'/ˌʌpˈdeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/upd/updat/update__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1905,'ngsl-4-15',13,'luck','may mắn; vận may','noun','[{"en":"Good luck with your big exam tomorrow morning!","vi":"Chúc bạn may mắn trong kỳ thi quan trọng sáng mai!"},{"en":"We had some bad luck with the weather on our holiday.","vi":"Chúng tôi gặp chút xui xẻo về thời tiết trong kỳ nghỉ."},{"en":"It was pure luck that I found my keys in the park.","vi":"Tôi tìm thấy chìa khóa trong công viên hoàn toàn là nhờ may mắn."}]','[{"phrase":"good luck"},{"phrase":"bad luck"},{"phrase":"pure luck"},{"phrase":"wish someone luck"}]','không đếm được','/lʌk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/luc/luck_/luck__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1906,'ngsl-4-15',14,'preserve','giữ gìn; bảo tồn; bảo quản','verb','[{"en":"The town has worked hard to preserve its old buildings.","vi":"Thị trấn đã nỗ lực rất nhiều để bảo tồn những tòa nhà cổ."},{"en":"Salt was used to preserve fish before people had fridges.","vi":"Muối được dùng để bảo quản cá trước khi người ta có tủ lạnh."},{"en":"It''s important to preserve our traditions for future generations.","vi":"Việc giữ gìn truyền thống cho các thế hệ tương lai là rất quan trọng."}]','[{"phrase":"preserve the environment"},{"phrase":"preserve traditions"},{"phrase":"preserve food"}]',NULL,'/prɪˈzɜːrv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prese/preserve__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1907,'ngsl-4-15',15,'split','chia; tách ra','verb','[{"en":"Let''s split the bill between the four of us.","vi":"Hãy chia hóa đơn cho cả bốn người chúng ta."},{"en":"The teacher split the class into small groups.","vi":"Giáo viên chia lớp thành các nhóm nhỏ."},{"en":"He splits his time between work and caring for his mother.","vi":"Anh ấy chia thời gian giữa công việc và việc chăm sóc mẹ."}]','[{"phrase":"split the bill"},{"phrase":"split into groups"},{"phrase":"split the cost"}]','split – split – split','/splɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spl/split/split__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1908,'ngsl-4-15',16,'swing','đung đưa; đu; xoay mạnh','verb','[{"en":"The children were swinging on a rope by the river.","vi":"Bọn trẻ đang đu dây bên bờ sông."},{"en":"She sat on the edge of the table, swinging her legs.","vi":"Cô ấy ngồi ở mép bàn, đung đưa hai chân."},{"en":"The door swung open and a cold wind blew in.","vi":"Cánh cửa bật mở và một cơn gió lạnh thổi vào."}]','[{"phrase":"swing open"},{"phrase":"swing back and forth"},{"phrase":"swing your arms"}]','swing – swung – swung','/swɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swi/swing/swing__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1909,'ngsl-4-15',17,'illness','bệnh; sự đau ốm','noun','[{"en":"My grandfather recovered quickly from his illness.","vi":"Ông tôi đã hồi phục nhanh sau trận ốm."},{"en":"She missed two weeks of school because of illness.","vi":"Cô bé nghỉ học hai tuần vì bị ốm."},{"en":"Regular exercise can help protect you from serious illness.","vi":"Tập thể dục đều đặn có thể giúp bạn phòng tránh bệnh nặng."}]','[{"phrase":"serious illness"},{"phrase":"long illness"},{"phrase":"recover from an illness"}]',NULL,'/ˈɪlnəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illne/illness__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1910,'ngsl-4-15',18,'journalist','nhà báo','noun','[{"en":"My cousin works as a journalist for a local newspaper.","vi":"Anh họ tôi làm nhà báo cho một tờ báo địa phương."},{"en":"Several journalists were waiting outside the hospital.","vi":"Vài nhà báo đang chờ bên ngoài bệnh viện."},{"en":"She dreamed of becoming a journalist and traveling the world.","vi":"Cô ấy mơ ước trở thành nhà báo và đi khắp thế giới."}]','[{"phrase":"young journalist"},{"phrase":"local journalist"},{"phrase":"become a journalist"}]',NULL,'/ˈdʒɜːrnəlɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journalist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1911,'ngsl-4-15',19,'sudden','đột ngột; bất ngờ','adjective','[{"en":"The sudden noise woke the baby up.","vi":"Tiếng động đột ngột làm em bé thức giấc."},{"en":"There was a sudden change in the weather this afternoon.","vi":"Chiều nay thời tiết thay đổi đột ngột."},{"en":"All of a sudden, the lights in the whole house went out.","vi":"Đột nhiên đèn trong cả nhà tắt phụt."}]','[{"phrase":"sudden change"},{"phrase":"sudden noise"},{"phrase":"all of a sudden"}]','all of a sudden = đột nhiên','/ˈsʌdn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sud/sudde/sudden__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1912,'ngsl-4-15',20,'advertisement','quảng cáo','noun','[{"en":"I saw an advertisement for a cheap apartment near the station.","vi":"Tôi thấy một quảng cáo cho thuê căn hộ giá rẻ gần nhà ga."},{"en":"The company put an advertisement in the newspaper for new staff.","vi":"Công ty đăng quảng cáo trên báo để tuyển nhân viên mới."},{"en":"There are too many advertisements before this video starts.","vi":"Có quá nhiều quảng cáo trước khi video này bắt đầu."}]','[{"phrase":"job advertisement"},{"phrase":"newspaper advertisement"},{"phrase":"place an advertisement"}]','viết tắt: ad (Mỹ), advert (Anh)','/ˌædvərˈtaɪzmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/adver/advertisement__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1913,'ngsl-4-15',21,'consistent','nhất quán; đều đặn; ổn định','adjective','[{"en":"Parents need to be consistent when setting rules for children.","vi":"Cha mẹ cần nhất quán khi đặt ra quy tắc cho con cái."},{"en":"She has been a consistent player throughout the season.","vi":"Cô ấy là một cầu thủ thi đấu ổn định suốt mùa giải."},{"en":"Consistent practice is the key to learning a language.","vi":"Luyện tập đều đặn là chìa khóa để học một ngôn ngữ."}]','[{"phrase":"consistent with"},{"phrase":"consistent quality"},{"phrase":"remain consistent"}]','consistent with sth = phù hợp với','/kənˈsɪstənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsistent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1914,'ngsl-4-15',22,'originally','ban đầu; lúc đầu; vốn','adverb','[{"en":"The meeting was originally planned for Monday.","vi":"Cuộc họp ban đầu được lên kế hoạch vào thứ Hai."},{"en":"My family is originally from a small village in the north.","vi":"Gia đình tôi vốn gốc ở một ngôi làng nhỏ ở miền Bắc."},{"en":"This building was originally a school, but now it''s a hotel.","vi":"Tòa nhà này lúc đầu là trường học, nhưng giờ là khách sạn."}]','[{"phrase":"originally planned"},{"phrase":"originally from"},{"phrase":"originally built"}]',NULL,'/əˈrɪdʒənəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/origi/originally__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1915,'ngsl-4-15',23,'aside','sang một bên; để dành','adverb','[{"en":"He stepped aside to let the old woman pass.","vi":"Anh ấy bước sang một bên để bà cụ đi qua."},{"en":"I try to put aside some money every month.","vi":"Tôi cố gắng để dành một ít tiền mỗi tháng."},{"en":"Let''s leave that problem aside for now and discuss the budget.","vi":"Tạm gác vấn đề đó sang một bên và bàn về ngân sách nhé."}]','[{"phrase":"put aside"},{"phrase":"step aside"},{"phrase":"set aside"},{"phrase":"aside from"}]','aside from = ngoài ra; trừ','/əˈsaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/asi/aside/aside__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1916,'ngsl-4-15',24,'comfort','sự thoải mái; sự an ủi','noun','[{"en":"These shoes are designed for comfort, not style.","vi":"Đôi giày này được thiết kế cho sự thoải mái, không phải cho kiểu dáng."},{"en":"Now you can shop from the comfort of your own home.","vi":"Giờ đây bạn có thể mua sắm thoải mái ngay tại nhà mình."},{"en":"Her friends were a great comfort to her after the accident.","vi":"Bạn bè là nguồn an ủi lớn đối với cô ấy sau tai nạn."}]','[{"phrase":"in comfort"},{"phrase":"great comfort"},{"phrase":"the comfort of your own home"}]',NULL,'/ˈkʌmfərt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comfo/comfort__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1917,'ngsl-4-15',25,'secondly','thứ hai là','adverb','[{"en":"Firstly, the room is too small, and secondly, it''s too expensive.","vi":"Thứ nhất, căn phòng quá nhỏ, và thứ hai, nó quá đắt."},{"en":"Secondly, we need to find a cheaper place for the party.","vi":"Thứ hai, chúng ta cần tìm một chỗ rẻ hơn để tổ chức tiệc."},{"en":"I chose this job firstly because it''s close to home and secondly because it pays well.","vi":"Tôi chọn công việc này, thứ nhất vì nó gần nhà và thứ hai vì lương tốt."}]','[{"phrase":"and secondly"},{"phrase":"firstly, secondly"}]',NULL,'/ˈsekəndli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secon/secondly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1918,'ngsl-4-15',26,'severe','nghiêm trọng; dữ dội; khắc nghiệt','adjective','[{"en":"He was taken to hospital with severe pain in his stomach.","vi":"Anh ấy được đưa vào viện vì đau bụng dữ dội."},{"en":"The severe weather closed many roads in the mountains.","vi":"Thời tiết khắc nghiệt đã khiến nhiều con đường trên núi bị đóng."},{"en":"The city is facing a severe shortage of clean water.","vi":"Thành phố đang đối mặt với tình trạng thiếu nước sạch nghiêm trọng."}]','[{"phrase":"severe pain"},{"phrase":"severe weather"},{"phrase":"severe shortage"},{"phrase":"severe damage"}]',NULL,'/sɪˈvɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sev/sever/severe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1919,'ngsl-4-15',27,'gene','gen','noun','[{"en":"Scientists have found a gene linked to heart disease.","vi":"Các nhà khoa học đã tìm ra một gen liên quan đến bệnh tim."},{"en":"Your eye color depends on the genes you get from your parents.","vi":"Màu mắt của bạn phụ thuộc vào gen bạn thừa hưởng từ cha mẹ."},{"en":"Some people have genes that help them live longer.","vi":"Một số người có gen giúp họ sống lâu hơn."}]','[{"phrase":"gene for"},{"phrase":"human gene"},{"phrase":"carry a gene"}]',NULL,'/dʒiːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gene_/gene_1_us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1920,'ngsl-4-15',28,'prospect','triển vọng; khả năng; viễn cảnh','noun','[{"en":"There is little prospect of the rain stopping today.","vi":"Hầu như không có khả năng hôm nay trời tạnh mưa."},{"en":"Learning English can improve your job prospects.","vi":"Học tiếng Anh có thể cải thiện triển vọng việc làm của bạn."},{"en":"The prospect of moving abroad made her a little nervous.","vi":"Viễn cảnh chuyển ra nước ngoài khiến cô ấy hơi lo lắng."}]','[{"phrase":"job prospects"},{"phrase":"career prospects"},{"phrase":"the prospect of"}]',NULL,'/ˈprɑːspekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prosp/prospect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1921,'ngsl-4-15',29,'snow','tuyết','noun','[{"en":"The children played in the snow all afternoon.","vi":"Bọn trẻ chơi đùa trên tuyết suốt cả buổi chiều."},{"en":"We had so much snow last night that the school closed.","vi":"Đêm qua tuyết rơi nhiều đến mức trường phải đóng cửa."},{"en":"I''ve never seen snow because it''s too hot in my hometown.","vi":"Tôi chưa bao giờ thấy tuyết vì quê tôi quá nóng."}]','[{"phrase":"heavy snow"},{"phrase":"in the snow"},{"phrase":"covered in snow"}]','không đếm được','/snəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sno/snow_/snow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1922,'ngsl-4-15',30,'plot','cốt truyện; mảnh đất','noun','[{"en":"The movie has a simple plot but great acting.","vi":"Bộ phim có cốt truyện đơn giản nhưng diễn xuất rất hay."},{"en":"I didn''t understand the plot of the book at first.","vi":"Lúc đầu tôi không hiểu cốt truyện của cuốn sách."},{"en":"My parents bought a small plot of land to grow vegetables.","vi":"Bố mẹ tôi đã mua một mảnh đất nhỏ để trồng rau."}]','[{"phrase":"the plot of"},{"phrase":"main plot"},{"phrase":"plot of land"}]',NULL,'/plɑːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/plo/plot_/plot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1923,'ngsl-4-16',1,'neck','cổ','noun','[{"en":"I slept in a strange position and now my neck hurts.","vi":"Tôi ngủ sai tư thế nên bây giờ bị đau cổ."},{"en":"She wore a thin gold chain around her neck.","vi":"Cô ấy đeo một sợi dây chuyền vàng mảnh quanh cổ."},{"en":"Giraffes use their long necks to reach leaves high in the trees.","vi":"Hươu cao cổ dùng chiếc cổ dài để với tới lá trên cao."}]','[{"phrase":"long neck"},{"phrase":"stiff neck"},{"phrase":"around your neck"},{"phrase":"neck pain"}]',NULL,'/nek/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nec/neck_/neck__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1924,'ngsl-4-16',2,'criteria','tiêu chí; tiêu chuẩn','noun','[{"en":"What criteria do you use when choosing a new employee?","vi":"Bạn dùng những tiêu chí nào khi chọn một nhân viên mới?"},{"en":"Only three students met all the criteria for the scholarship.","vi":"Chỉ có ba học sinh đáp ứng tất cả tiêu chuẩn để nhận học bổng."},{"en":"The judges explained the criteria before the competition started.","vi":"Ban giám khảo giải thích các tiêu chí trước khi cuộc thi bắt đầu."}]','[{"phrase":"meet the criteria"},{"phrase":"selection criteria"},{"phrase":"strict criteria"},{"phrase":"criteria for"}]','số nhiều của criterion','/kraɪˈtɪriːə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1925,'ngsl-4-16',3,'primarily','chủ yếu; trước hết','adverb','[{"en":"This app is designed primarily for young children.","vi":"Ứng dụng này được thiết kế chủ yếu cho trẻ nhỏ."},{"en":"Our customers are primarily small businesses in the city.","vi":"Khách hàng của chúng tôi chủ yếu là các doanh nghiệp nhỏ trong thành phố."},{"en":"He moved abroad primarily to be closer to his daughter.","vi":"Anh ấy chuyển ra nước ngoài trước hết là để được gần con gái hơn."}]','[{"phrase":"primarily responsible"},{"phrase":"primarily because"},{"phrase":"primarily designed for"},{"phrase":"primarily used"}]',NULL,'/praɪˈmerəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prima/primarily__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1926,'ngsl-4-16',4,'integrate','hòa nhập; tích hợp','verb','[{"en":"It took the new students a few weeks to integrate into the class.","vi":"Các học sinh mới mất vài tuần để hòa nhập với lớp."},{"en":"The new camera is fully integrated into the phone''s software.","vi":"Máy ảnh mới được tích hợp hoàn toàn vào phần mềm của điện thoại."},{"en":"We need to integrate these two systems before the end of the year.","vi":"Chúng ta cần tích hợp hai hệ thống này trước cuối năm."}]','[{"phrase":"integrate into"},{"phrase":"integrate with"},{"phrase":"fully integrated"}]','integrate into/with','/ˈɪntɪɡreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1927,'ngsl-4-16',5,'criticism','sự chỉ trích; lời phê bình','noun','[{"en":"The new rules have received a lot of criticism from parents.","vi":"Các quy định mới đã nhận nhiều chỉ trích từ phụ huynh."},{"en":"She is good at accepting criticism and learning from it.","vi":"Cô ấy giỏi tiếp nhận lời phê bình và học hỏi từ đó."},{"en":"My teacher always gives helpful criticism of my essays.","vi":"Thầy giáo tôi luôn đưa ra những lời phê bình hữu ích về bài luận của tôi."}]','[{"phrase":"receive criticism"},{"phrase":"accept criticism"},{"phrase":"constructive criticism"},{"phrase":"criticism of"}]',NULL,'/ˈkrɪtɪsɪzəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/criticism__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1928,'ngsl-4-16',6,'convention','hội nghị; quy ước, tục lệ','noun','[{"en":"Thousands of teachers attended the national convention in the capital.","vi":"Hàng nghìn giáo viên đã tham dự hội nghị toàn quốc ở thủ đô."},{"en":"By convention, the bride''s family pays for the wedding.","vi":"Theo tục lệ, nhà gái chi trả cho đám cưới."},{"en":"In many countries, it is a convention to shake hands when meeting.","vi":"Ở nhiều nước, bắt tay khi gặp nhau là một quy ước."}]','[{"phrase":"annual convention"},{"phrase":"national convention"},{"phrase":"by convention"},{"phrase":"social convention"}]',NULL,'/kənˈvenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvention__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1929,'ngsl-4-16',7,'bet','cá cược; dám chắc','verb','[{"en":"He bet twenty dollars that his team would win.","vi":"Anh ấy cược hai mươi đô la rằng đội của mình sẽ thắng."},{"en":"I bet you''re tired after such a long flight.","vi":"Tôi dám chắc bạn mệt sau một chuyến bay dài như vậy."},{"en":"My uncle never bets money on football games.","vi":"Chú tôi không bao giờ cá tiền vào các trận bóng đá."}]','[{"phrase":"bet money"},{"phrase":"bet on"},{"phrase":"I bet"},{"phrase":"you bet"}]','bet – bet – bet','/bet/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bet/bet__/bet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1930,'ngsl-4-16',8,'retain','giữ lại; duy trì','verb','[{"en":"The company offers good pay to retain its best workers.","vi":"Công ty trả lương tốt để giữ chân những nhân viên giỏi nhất."},{"en":"Please retain your receipt in case you need to return the item.","vi":"Vui lòng giữ lại hóa đơn phòng khi bạn cần trả hàng."},{"en":"The old town has retained much of its traditional charm.","vi":"Khu phố cổ vẫn duy trì được phần lớn nét duyên truyền thống."}]','[{"phrase":"retain staff"},{"phrase":"retain control"},{"phrase":"retain information"},{"phrase":"retain heat"}]',NULL,'/rɪˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retai/retain__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1931,'ngsl-4-16',9,'sequence','trình tự; chuỗi','noun','[{"en":"Put these pictures in the correct sequence to tell the story.","vi":"Hãy xếp những bức tranh này theo đúng trình tự để kể câu chuyện."},{"en":"The opening sequence of the film was really exciting.","vi":"Chuỗi cảnh mở đầu của bộ phim thật sự hấp dẫn."},{"en":"A strange sequence of events led to their first meeting.","vi":"Một chuỗi sự việc kỳ lạ đã dẫn đến lần gặp đầu tiên của họ."}]','[{"phrase":"sequence of events"},{"phrase":"in sequence"},{"phrase":"correct sequence"},{"phrase":"opening sequence"}]',NULL,'/ˈsiːkwəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/seq/seque/sequence__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1932,'ngsl-4-16',10,'plain','đơn giản, trơn; rõ ràng','adjective','[{"en":"She prefers plain white shirts to colorful ones.","vi":"Cô ấy thích áo sơ mi trắng trơn hơn áo sặc sỡ."},{"en":"It was plain that he didn''t want to talk about it.","vi":"Rõ ràng là anh ấy không muốn nói về chuyện đó."},{"en":"Could you explain the contract in plain English, please?","vi":"Bạn có thể giải thích hợp đồng bằng tiếng Anh dễ hiểu được không?"}]','[{"phrase":"plain English"},{"phrase":"plain white"},{"phrase":"make it plain"},{"phrase":"plain yogurt"}]',NULL,'/pleɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plain/plain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1933,'ngsl-4-16',11,'volunteer','tình nguyện viên','noun','[{"en":"The festival is run entirely by volunteers from the town.","vi":"Lễ hội hoàn toàn do các tình nguyện viên trong thị trấn tổ chức."},{"en":"My sister works as a volunteer at the animal shelter.","vi":"Chị tôi làm tình nguyện viên ở trại cứu hộ động vật."},{"en":"We still need a few more volunteers to clean the beach.","vi":"Chúng tôi vẫn cần thêm vài tình nguyện viên để dọn dẹp bãi biển."}]','[{"phrase":"volunteer work"},{"phrase":"work as a volunteer"},{"phrase":"need volunteers"}]','cũng là động từ: volunteer to do sth (tình nguyện làm gì)','/ˌvɑːlənˈtɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volun/volunteer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1934,'ngsl-4-16',12,'rural','(thuộc) nông thôn','adjective','[{"en":"My grandparents still live in a small rural village.","vi":"Ông bà tôi vẫn sống ở một ngôi làng nhỏ vùng nông thôn."},{"en":"Many young people leave rural areas to find work in cities.","vi":"Nhiều người trẻ rời vùng nông thôn để tìm việc ở thành phố."},{"en":"Life in rural communities is often quieter and slower.","vi":"Cuộc sống ở các cộng đồng nông thôn thường yên tĩnh và chậm rãi hơn."}]','[{"phrase":"rural area"},{"phrase":"rural village"},{"phrase":"rural community"},{"phrase":"rural life"}]','rural ≠ urban (thành thị)','/ˈrʊrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rur/rural/rural__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1935,'ngsl-4-16',13,'calm','bình tĩnh; yên tĩnh, êm','adjective','[{"en":"Try to stay calm and answer the questions slowly.","vi":"Hãy cố giữ bình tĩnh và trả lời các câu hỏi thật chậm rãi."},{"en":"The sea was calm, so we went out in a small boat.","vi":"Biển êm nên chúng tôi ra khơi trên một chiếc thuyền nhỏ."},{"en":"She spoke in a calm voice even though she was angry.","vi":"Cô ấy nói bằng giọng bình tĩnh dù đang tức giận."}]','[{"phrase":"stay calm"},{"phrase":"keep calm"},{"phrase":"calm voice"},{"phrase":"calm sea"}]',NULL,'/kɑːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cal/calm_/calm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1936,'ngsl-4-16',14,'abandon','bỏ rơi; từ bỏ','verb','[{"en":"Someone abandoned a tiny puppy outside our building last night.","vi":"Tối qua ai đó đã bỏ rơi một chú cún nhỏ trước tòa nhà chúng tôi."},{"en":"They had to abandon the game because of heavy rain.","vi":"Họ phải bỏ dở trận đấu vì mưa lớn."},{"en":"He never abandoned his dream of becoming a doctor.","vi":"Anh ấy chưa bao giờ từ bỏ ước mơ trở thành bác sĩ."}]','[{"phrase":"abandon a plan"},{"phrase":"abandon hope"},{"phrase":"abandoned car"},{"phrase":"abandon a project"}]',NULL,'/əˈbændən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aba/aband/abandon__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1937,'ngsl-4-16',15,'examination','kỳ thi; sự kiểm tra, khám','noun','[{"en":"All students must pass the final examination to graduate.","vi":"Tất cả học sinh phải vượt qua kỳ thi cuối cùng để tốt nghiệp."},{"en":"The doctor did a quick examination of my injured knee.","vi":"Bác sĩ khám nhanh đầu gối bị thương của tôi."},{"en":"After careful examination, the police found no evidence.","vi":"Sau khi kiểm tra kỹ lưỡng, cảnh sát không tìm thấy bằng chứng nào."}]','[{"phrase":"pass an examination"},{"phrase":"medical examination"},{"phrase":"careful examination"},{"phrase":"final examination"}]','thường nói tắt: exam','/ɪɡˌzæmɪˈneɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exami/examination__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1938,'ngsl-4-16',16,'silence','sự im lặng','noun','[{"en":"There was a long silence after she asked the question.","vi":"Có một khoảng im lặng dài sau khi cô ấy đặt câu hỏi."},{"en":"We ate our dinner in silence, too tired to talk.","vi":"Chúng tôi ăn tối trong im lặng, mệt đến mức không muốn nói."},{"en":"The sudden noise broke the silence of the library.","vi":"Tiếng động bất ngờ đã phá vỡ sự im lặng của thư viện."}]','[{"phrase":"in silence"},{"phrase":"break the silence"},{"phrase":"long silence"},{"phrase":"complete silence"}]',NULL,'/ˈsaɪləns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silen/silence__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1939,'ngsl-4-16',17,'rapidly','nhanh chóng','adverb','[{"en":"The city has grown rapidly over the last ten years.","vi":"Thành phố đã phát triển nhanh chóng trong mười năm qua."},{"en":"Prices are rising rapidly, so we should buy now.","vi":"Giá cả đang tăng nhanh chóng nên chúng ta nên mua ngay."},{"en":"Her English improved rapidly after she moved abroad.","vi":"Tiếng Anh của cô ấy tiến bộ nhanh chóng sau khi chuyển ra nước ngoài."}]','[{"phrase":"grow rapidly"},{"phrase":"change rapidly"},{"phrase":"rapidly increasing"},{"phrase":"move rapidly"}]',NULL,'/ˈræpɪdli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rap/rapid/rapidly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1940,'ngsl-4-16',18,'efficient','hiệu quả; làm việc năng suất','adjective','[{"en":"Trains are a fast and efficient way to travel.","vi":"Tàu hỏa là cách di chuyển nhanh và hiệu quả."},{"en":"Our new manager is very efficient and well organized.","vi":"Quản lý mới của chúng tôi làm việc rất năng suất và ngăn nắp."},{"en":"This fridge is more energy efficient than our old one.","vi":"Chiếc tủ lạnh này tiết kiệm năng lượng hơn chiếc cũ của chúng tôi."}]','[{"phrase":"energy efficient"},{"phrase":"highly efficient"},{"phrase":"efficient way"},{"phrase":"more efficient"}]','efficient (ít lãng phí) ≠ effective (đạt kết quả)','/ɪˈfɪʃnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effic/efficient__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1941,'ngsl-4-16',19,'revolution','cuộc cách mạng','noun','[{"en":"The internet started a revolution in the way we communicate.","vi":"Internet đã mở ra một cuộc cách mạng trong cách chúng ta giao tiếp."},{"en":"We learned about the Industrial Revolution in history class.","vi":"Chúng tôi đã học về Cách mạng Công nghiệp trong giờ lịch sử."},{"en":"Smartphones brought about a revolution in photography.","vi":"Điện thoại thông minh đã tạo ra một cuộc cách mạng trong nhiếp ảnh."}]','[{"phrase":"industrial revolution"},{"phrase":"technological revolution"},{"phrase":"revolution in"},{"phrase":"digital revolution"}]',NULL,'/ˌrevəˈluːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revol/revolution__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1942,'ngsl-4-16',20,'delight','niềm vui sướng; điều thú vị','noun','[{"en":"The children shouted with delight when they saw the snow.","vi":"Bọn trẻ reo lên vui sướng khi nhìn thấy tuyết."},{"en":"To my delight, my old friend came to visit me.","vi":"Tôi rất vui mừng khi người bạn cũ đến thăm mình."},{"en":"This little café is a real delight for coffee lovers.","vi":"Quán cà phê nhỏ này thật sự là một điều thú vị với người mê cà phê."}]','[{"phrase":"with delight"},{"phrase":"to my delight"},{"phrase":"take delight in"},{"phrase":"real delight"}]',NULL,'/dɪˈlaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/delig/delight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1943,'ngsl-4-16',21,'spell','đánh vần; viết đúng chính tả','verb','[{"en":"Could you spell your last name for me, please?","vi":"Bạn có thể đánh vần họ của bạn cho tôi được không?"},{"en":"I always forget how to spell this word correctly.","vi":"Tôi luôn quên cách viết đúng chính tả của từ này."},{"en":"My little brother can already spell his own name.","vi":"Em trai nhỏ của tôi đã biết đánh vần tên của mình."}]','[{"phrase":"spell your name"},{"phrase":"spell correctly"},{"phrase":"how to spell"}]','Mỹ: spelled · Anh: spelt','/spel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/spell/spell__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1944,'ngsl-4-16',22,'premise','tiền đề; ý tưởng cơ sở','noun','[{"en":"The whole plan is based on a false premise.","vi":"Toàn bộ kế hoạch dựa trên một tiền đề sai."},{"en":"The basic premise of the movie is simple but clever.","vi":"Ý tưởng cơ sở của bộ phim đơn giản nhưng thông minh."},{"en":"We started from the premise that everyone wants to learn.","vi":"Chúng tôi bắt đầu từ tiền đề rằng ai cũng muốn học."}]','[{"phrase":"basic premise"},{"phrase":"false premise"},{"phrase":"based on the premise"},{"phrase":"premise of"}]','premises (số nhiều) = khuôn viên, cơ sở (nhà, đất)','/ˈpremɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/premi/premise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1945,'ngsl-4-16',23,'lean','dựa, tựa; nghiêng người','verb','[{"en":"He leaned against the wall and waited for the bus.","vi":"Anh ấy tựa vào tường và chờ xe buýt."},{"en":"Don''t lean out of the window while the train is moving.","vi":"Đừng nhoài người ra ngoài cửa sổ khi tàu đang chạy."},{"en":"She leaned forward to hear what the teacher was saying.","vi":"Cô ấy nghiêng người về phía trước để nghe thầy giáo nói gì."}]','[{"phrase":"lean against"},{"phrase":"lean forward"},{"phrase":"lean back"},{"phrase":"lean on"}]','Mỹ: leaned · Anh: leaned/leant','/liːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/lean_/lean__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1946,'ngsl-4-16',24,'dramatic','đột ngột, mạnh mẽ; kịch tính','adjective','[{"en":"There has been a dramatic increase in house prices this year.","vi":"Năm nay giá nhà đã tăng mạnh."},{"en":"The game had a dramatic ending in the final minute.","vi":"Trận đấu có một kết thúc đầy kịch tính ở phút cuối cùng."},{"en":"Moving to a new country was a dramatic change for our family.","vi":"Chuyển đến một đất nước mới là một thay đổi lớn đối với gia đình tôi."}]','[{"phrase":"dramatic change"},{"phrase":"dramatic increase"},{"phrase":"dramatic effect"},{"phrase":"dramatic ending"}]',NULL,'/drəˈmætɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/dramatic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1947,'ngsl-4-16',25,'differ','khác nhau; bất đồng','verb','[{"en":"Prices differ a lot from one shop to another.","vi":"Giá cả khác nhau rất nhiều giữa các cửa hàng."},{"en":"How does this phone differ from the older model?","vi":"Chiếc điện thoại này khác mẫu cũ ở điểm nào?"},{"en":"My parents often differ on how to spend money.","vi":"Bố mẹ tôi thường bất đồng về cách tiêu tiền."}]','[{"phrase":"differ from"},{"phrase":"differ greatly"},{"phrase":"differ in"},{"phrase":"opinions differ"}]','differ from (khác với)','/ˈdɪfər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/differ__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1948,'ngsl-4-16',26,'grateful','biết ơn','adjective','[{"en":"I''m really grateful for all your help this week.","vi":"Tôi thật sự biết ơn tất cả sự giúp đỡ của bạn tuần này."},{"en":"We would be grateful if you could reply soon.","vi":"Chúng tôi sẽ rất biết ơn nếu bạn có thể sớm trả lời."},{"en":"She was grateful to her teacher for believing in her.","vi":"Cô ấy biết ơn thầy giáo vì đã tin tưởng mình."}]','[{"phrase":"grateful for"},{"phrase":"grateful to"},{"phrase":"deeply grateful"},{"phrase":"would be grateful"}]','grateful to sb for sth','/ˈɡreɪtfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grate/grateful__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1949,'ngsl-4-16',27,'protein','chất đạm, protein','noun','[{"en":"Eggs and beans are cheap sources of protein.","vi":"Trứng và đậu là những nguồn chất đạm rẻ tiền."},{"en":"Athletes often need more protein than other people.","vi":"Vận động viên thường cần nhiều chất đạm hơn người khác."},{"en":"My doctor told me to eat more protein and less sugar.","vi":"Bác sĩ bảo tôi ăn nhiều chất đạm hơn và ít đường hơn."}]','[{"phrase":"source of protein"},{"phrase":"high in protein"},{"phrase":"protein intake"}]',NULL,'/ˈprəʊtiːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protein__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1950,'ngsl-4-16',28,'bike','xe đạp','noun','[{"en":"I ride my bike to school every morning.","vi":"Sáng nào tôi cũng đạp xe đến trường."},{"en":"Someone stole my bike while I was in the store.","vi":"Ai đó đã lấy trộm xe đạp của tôi khi tôi đang ở trong cửa hàng."},{"en":"Let''s go for a bike ride along the river this afternoon.","vi":"Chiều nay mình đi đạp xe dọc bờ sông nhé."}]','[{"phrase":"ride a bike"},{"phrase":"bike ride"},{"phrase":"by bike"},{"phrase":"bike lane"}]','trong văn nói, bike cũng có thể chỉ xe máy','/baɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bik/bike_/bike__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1951,'ngsl-4-16',29,'distribute','phân phát; phân phối','verb','[{"en":"Volunteers distributed food and water to the families.","vi":"Các tình nguyện viên đã phân phát thức ăn và nước uống cho các gia đình."},{"en":"The teacher distributed the test papers to the class.","vi":"Giáo viên phát bài kiểm tra cho cả lớp."},{"en":"This company distributes its products to shops across the country.","vi":"Công ty này phân phối sản phẩm đến các cửa hàng trên cả nước."}]','[{"phrase":"distribute food"},{"phrase":"widely distributed"},{"phrase":"distribute to"},{"phrase":"distribute products"}]',NULL,'/dɪˈstrɪbjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distr/distribute__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1952,'ngsl-4-16',30,'intellectual','(thuộc) trí tuệ','adjective','[{"en":"Reading and puzzles are good for a child''s intellectual development.","vi":"Đọc sách và giải đố tốt cho sự phát triển trí tuệ của trẻ."},{"en":"The course was an intellectual challenge even for the best students.","vi":"Khóa học là một thử thách trí tuệ ngay cả với những sinh viên giỏi nhất."},{"en":"They enjoy intellectual conversations about books, art and history.","vi":"Họ thích những cuộc trò chuyện mang tính trí tuệ về sách, nghệ thuật và lịch sử."}]','[{"phrase":"intellectual development"},{"phrase":"intellectual property"},{"phrase":"intellectual ability"},{"phrase":"intellectual challenge"}]',NULL,'/ˌɪntəˈlektʃuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intel/intellectual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1953,'ngsl-4-17',1,'derive','bắt nguồn từ; có được, lấy được (từ)','verb','[{"en":"Many English words are derived from Latin or Greek.","vi":"Nhiều từ tiếng Anh bắt nguồn từ tiếng Latin hoặc tiếng Hy Lạp."},{"en":"She derives great pleasure from working in her garden.","vi":"Cô ấy có được niềm vui lớn từ việc làm vườn."},{"en":"This medicine is derived from a plant that grows in the rainforest.","vi":"Loại thuốc này được chiết xuất từ một loài cây mọc trong rừng mưa nhiệt đới."}]','[{"phrase":"derive from"},{"phrase":"be derived from"},{"phrase":"derive pleasure from"}]','derive from: bắt nguồn từ','/dɪˈraɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/der/deriv/derive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1954,'ngsl-4-17',2,'crucial','rất quan trọng; then chốt','adjective','[{"en":"Getting enough sleep is crucial for your health.","vi":"Ngủ đủ giấc rất quan trọng đối với sức khỏe của bạn."},{"en":"The next few days will be crucial for the team.","vi":"Vài ngày tới sẽ mang tính then chốt đối với đội."},{"en":"She played a crucial role in the success of the project.","vi":"Cô ấy đóng vai trò then chốt trong thành công của dự án."}]','[{"phrase":"crucial role"},{"phrase":"crucial for"},{"phrase":"absolutely crucial"}]',NULL,'/ˈkruːʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cru/cruci/crucial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1955,'ngsl-4-17',3,'unemployment','sự thất nghiệp; tình trạng thất nghiệp','noun','[{"en":"The unemployment rate has risen sharply in the past year.","vi":"Tỷ lệ thất nghiệp đã tăng mạnh trong năm qua."},{"en":"Many young people in the town struggle with unemployment.","vi":"Nhiều người trẻ trong thị trấn phải vật lộn với cảnh thất nghiệp."},{"en":"After losing his job, he received unemployment benefits for six months.","vi":"Sau khi mất việc, anh ấy nhận trợ cấp thất nghiệp trong sáu tháng."}]','[{"phrase":"unemployment rate"},{"phrase":"high unemployment"},{"phrase":"unemployment benefits"},{"phrase":"youth unemployment"}]','không đếm được','/ˌʌnɪmˈplɔɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/une/unemp/unemployment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1956,'ngsl-4-17',4,'wheel','bánh xe; vô lăng','noun','[{"en":"Can you help me put the front wheel back on my bike?","vi":"Bạn giúp tôi lắp lại bánh trước vào xe đạp được không?"},{"en":"One of the wheels on my suitcase broke at the airport.","vi":"Vali của tôi bị gãy một bánh xe ở sân bay."},{"en":"Keep both hands on the wheel when you drive.","vi":"Hãy giữ cả hai tay trên vô lăng khi lái xe."}]','[{"phrase":"front wheel"},{"phrase":"back wheel"},{"phrase":"steering wheel"},{"phrase":"behind the wheel"}]',NULL,'/wiːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/wheel/wheel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1957,'ngsl-4-17',5,'crop','cây trồng; vụ mùa','noun','[{"en":"Rice is the main crop in this part of the country.","vi":"Lúa là cây trồng chính ở vùng này của đất nước."},{"en":"Farmers are worried that the dry weather will damage their crops.","vi":"Nông dân lo rằng thời tiết khô hạn sẽ gây hại cho cây trồng của họ."},{"en":"We had a good crop of apples this year.","vi":"Năm nay chúng tôi được mùa táo."}]','[{"phrase":"grow crops"},{"phrase":"main crop"},{"phrase":"good crop"},{"phrase":"crop failure"}]',NULL,'/krɑːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cro/crop_/crop__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1958,'ngsl-4-17',6,'minority','thiểu số; nhóm thiểu số','noun','[{"en":"Only a minority of students chose to study abroad.","vi":"Chỉ một số ít sinh viên chọn đi du học."},{"en":"People who cycle to work are still in the minority here.","vi":"Ở đây, những người đạp xe đi làm vẫn là thiểu số."},{"en":"The school offers extra support for children from ethnic minorities.","vi":"Trường có hỗ trợ thêm cho trẻ em thuộc các dân tộc thiểu số."}]','[{"phrase":"a minority of"},{"phrase":"in the minority"},{"phrase":"ethnic minority"},{"phrase":"small minority"}]',NULL,'/maɪˈnɔːrəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minor/minority__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1959,'ngsl-4-17',7,'origin','nguồn gốc; xuất xứ','noun','[{"en":"Nobody knows the true origin of this old song.","vi":"Không ai biết nguồn gốc thật sự của bài hát cổ này."},{"en":"The country of origin is printed on the label.","vi":"Nước xuất xứ được in trên nhãn."},{"en":"The festival has its origins in an ancient farming tradition.","vi":"Lễ hội này có nguồn gốc từ một truyền thống nông nghiệp cổ xưa."}]','[{"phrase":"country of origin"},{"phrase":"have its origins in"},{"phrase":"the origin of"}]',NULL,'/ˈɔːrɪdʒɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/origi/origin__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1960,'ngsl-4-17',8,'interpretation','cách hiểu, sự giải thích; cách thể hiện','noun','[{"en":"Each student gave a different interpretation of the poem.","vi":"Mỗi học sinh đưa ra một cách hiểu khác nhau về bài thơ."},{"en":"The rules are clear and leave little room for interpretation.","vi":"Các quy định rất rõ ràng và hầu như không có chỗ cho cách hiểu khác."},{"en":"I loved her fresh interpretation of this famous piano piece.","vi":"Tôi rất thích cách thể hiện mới mẻ của cô ấy với bản nhạc piano nổi tiếng này."}]','[{"phrase":"interpretation of"},{"phrase":"different interpretation"},{"phrase":"open to interpretation"},{"phrase":"room for interpretation"}]',NULL,'/ɪnˌtɜːrprəˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interpretation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1961,'ngsl-4-17',9,'gentleman','quý ông; người đàn ông lịch thiệp','noun','[{"en":"Could you show this gentleman to his table, please?","vi":"Bạn vui lòng dẫn quý ông này đến bàn của ông ấy nhé?"},{"en":"Good evening, ladies and gentlemen, and welcome to the show.","vi":"Xin chào quý vị, chào mừng quý vị đến với chương trình."},{"en":"My grandfather was a true gentleman who was kind to everyone.","vi":"Ông tôi là một quý ông thực thụ, luôn tử tế với mọi người."}]','[{"phrase":"ladies and gentlemen"},{"phrase":"true gentleman"},{"phrase":"old gentleman"}]','số nhiều: gentlemen','/ˈdʒentlmən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gentl/gentleman__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1962,'ngsl-4-17',10,'drama','kịch, sân khấu; phim truyền hình; chuyện lùm xùm','noun','[{"en":"She studied drama at college and now works in theater.","vi":"Cô ấy học ngành kịch ở đại học và giờ làm việc trong lĩnh vực sân khấu."},{"en":"We watched a new crime drama on TV last night.","vi":"Tối qua chúng tôi xem một bộ phim truyền hình hình sự mới."},{"en":"I just want a quiet weekend without any family drama.","vi":"Tôi chỉ muốn một cuối tuần yên tĩnh, không có chuyện lùm xùm gì trong gia đình."}]','[{"phrase":"study drama"},{"phrase":"TV drama"},{"phrase":"crime drama"},{"phrase":"drama school"}]',NULL,'/ˈdrɑːmə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/drama__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1963,'ngsl-4-17',11,'landscape','phong cảnh; cảnh quan','noun','[{"en":"The landscape around the lake is beautiful in autumn.","vi":"Phong cảnh quanh hồ rất đẹp vào mùa thu."},{"en":"We drove for hours through a flat, empty landscape.","vi":"Chúng tôi lái xe hàng giờ qua một vùng cảnh quan bằng phẳng và trống trải."},{"en":"He loves painting landscapes more than people.","vi":"Anh ấy thích vẽ phong cảnh hơn là vẽ người."}]','[{"phrase":"beautiful landscape"},{"phrase":"rural landscape"},{"phrase":"landscape painting"}]',NULL,'/ˈlændskeɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lan/lands/landscape__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1964,'ngsl-4-17',12,'educate','giáo dục; cho đi học; nâng cao hiểu biết','verb','[{"en":"Both of their children were educated at local schools.","vi":"Cả hai người con của họ đều được học ở các trường địa phương."},{"en":"The campaign aims to educate people about healthy eating.","vi":"Chiến dịch nhằm nâng cao hiểu biết của mọi người về ăn uống lành mạnh."},{"en":"Parents play a big part in educating their children.","vi":"Cha mẹ đóng vai trò lớn trong việc giáo dục con cái."}]','[{"phrase":"educate people about"},{"phrase":"educate the public"},{"phrase":"well educated"}]',NULL,'/ˈedʒukeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edu/educa/educate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1965,'ngsl-4-17',13,'toy','đồ chơi','noun','[{"en":"Please put your toys away before dinner.","vi":"Con hãy cất đồ chơi đi trước bữa tối nhé."},{"en":"He bought his son a toy car for his birthday.","vi":"Anh ấy mua cho con trai một chiếc ô tô đồ chơi nhân dịp sinh nhật."},{"en":"The dog loves chewing on its old rubber toy.","vi":"Con chó thích gặm món đồ chơi cao su cũ của nó."}]','[{"phrase":"toy car"},{"phrase":"play with toys"},{"phrase":"toy store"}]',NULL,'/tɔɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/toy/toy__/toy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1966,'ngsl-4-17',14,'fault','lỗi (trách nhiệm); khuyết điểm; chỗ hỏng','noun','[{"en":"It''s not your fault that the train was late.","vi":"Tàu đến muộn đâu phải lỗi của bạn."},{"en":"He has his faults, but he''s a loyal friend.","vi":"Anh ấy có những khuyết điểm, nhưng là một người bạn trung thành."},{"en":"The engineers found a fault in the electrical system.","vi":"Các kỹ sư đã phát hiện một chỗ hỏng trong hệ thống điện."}]','[{"phrase":"your fault"},{"phrase":"at fault"},{"phrase":"find fault with"}]',NULL,'/fɔːlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fau/fault/fault__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1967,'ngsl-4-17',15,'exhibit','trưng bày, triển lãm; thể hiện','verb','[{"en":"Her paintings are being exhibited at a gallery downtown.","vi":"Các bức tranh của cô ấy đang được trưng bày tại một phòng tranh ở trung tâm thành phố."},{"en":"The museum will exhibit old photos of the city next month.","vi":"Tháng tới, bảo tàng sẽ trưng bày những bức ảnh cũ về thành phố."},{"en":"The young player exhibited great confidence throughout the match.","vi":"Cầu thủ trẻ đã thể hiện sự tự tin tuyệt vời trong suốt trận đấu."}]','[{"phrase":"exhibit work"},{"phrase":"exhibit paintings"},{"phrase":"exhibit signs of"}]',NULL,'/ɪɡˈzɪbɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhib/exhibit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1968,'ngsl-4-17',16,'minor','nhỏ, không quan trọng; nhẹ (không nghiêm trọng)','adjective','[{"en":"We made a few minor changes to the plan.","vi":"Chúng tôi đã thực hiện vài thay đổi nhỏ trong kế hoạch."},{"en":"Luckily, she only had minor injuries after falling off her bike.","vi":"May mắn là cô ấy chỉ bị thương nhẹ sau khi ngã xe đạp."},{"en":"Don''t worry about it; it''s only a minor problem.","vi":"Đừng lo, đó chỉ là một vấn đề nhỏ thôi."}]','[{"phrase":"minor changes"},{"phrase":"minor injuries"},{"phrase":"minor problem"},{"phrase":"minor role"}]',NULL,'/ˈmaɪnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minor/minor__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1969,'ngsl-4-17',17,'hunt','săn, săn bắt; lùng tìm','verb','[{"en":"Owls usually hunt for mice and other small animals at night.","vi":"Cú thường săn chuột và các loài vật nhỏ khác vào ban đêm."},{"en":"I hunted everywhere for my keys but couldn''t find them.","vi":"Tôi đã lục tìm chìa khóa khắp nơi nhưng không thấy."},{"en":"They are hunting for a cheap apartment near the university.","vi":"Họ đang lùng tìm một căn hộ giá rẻ gần trường đại học."}]','[{"phrase":"hunt for"},{"phrase":"go hunting"},{"phrase":"hunt down"}]',NULL,'/hʌnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hun/hunt_/hunt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1970,'ngsl-4-17',18,'storm','cơn bão; giông bão','noun','[{"en":"The storm knocked down several trees on our street.","vi":"Cơn bão đã quật đổ nhiều cây trên phố chúng tôi."},{"en":"All flights were canceled because of the storm.","vi":"Tất cả các chuyến bay đều bị hủy vì bão."},{"en":"It looks like a storm is coming, so let''s go inside.","vi":"Có vẻ sắp có bão, chúng ta vào trong thôi."}]','[{"phrase":"severe storm"},{"phrase":"tropical storm"},{"phrase":"a storm is coming"}]',NULL,'/stɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/storm/storm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1971,'ngsl-4-17',19,'thick','dày; đặc','adjective','[{"en":"She wore a thick sweater because it was cold outside.","vi":"Cô ấy mặc một chiếc áo len dày vì ngoài trời lạnh."},{"en":"Stir the soup until it becomes thick and smooth.","vi":"Khuấy súp cho đến khi súp sánh đặc và mịn."},{"en":"It was hard to see the road through the thick fog.","vi":"Rất khó nhìn thấy đường qua lớp sương mù dày đặc."}]','[{"phrase":"thick fog"},{"phrase":"thick hair"},{"phrase":"thick layer"},{"phrase":"thick smoke"}]',NULL,'/θɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thick/thick__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1972,'ngsl-5-01',1,'achievement','thành tích; thành tựu','noun','[{"en":"Winning the scholarship was the greatest achievement of her school years.","vi":"Giành được học bổng là thành tích lớn nhất trong những năm đi học của cô ấy."},{"en":"Learning to swim at sixty is a great achievement.","vi":"Học bơi ở tuổi sáu mươi là một thành tựu lớn."},{"en":"Finishing my first marathon gave me a real sense of achievement.","vi":"Hoàn thành cuộc chạy marathon đầu tiên mang lại cho tôi cảm giác thành tựu thực sự."}]','[{"phrase":"great achievement"},{"phrase":"sense of achievement"},{"phrase":"academic achievement"}]',NULL,'/əˈtʃiːvmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ach/achie/achievement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1973,'ngsl-5-01',2,'negotiate','đàm phán; thương lượng','verb','[{"en":"We negotiated a lower rent with our landlord last month.","vi":"Tháng trước chúng tôi đã thương lượng được mức tiền thuê nhà thấp hơn với chủ nhà."},{"en":"The two companies are still trying to negotiate a deal.","vi":"Hai công ty vẫn đang cố gắng đàm phán một thỏa thuận."},{"en":"Don''t be afraid to negotiate your salary when you get a job offer.","vi":"Đừng ngại thương lượng mức lương khi bạn nhận được lời mời làm việc."}]','[{"phrase":"negotiate a deal"},{"phrase":"negotiate a contract"},{"phrase":"negotiate with"}]',NULL,'/nɪˈɡəʊʃieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negot/negotiate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1974,'ngsl-5-01',3,'dominate','chiếm ưu thế; chi phối; thống trị','verb','[{"en":"Our team dominated the game from start to finish.","vi":"Đội chúng tôi chiếm ưu thế trong trận đấu từ đầu đến cuối."},{"en":"Money worries dominated his life after he lost his job.","vi":"Nỗi lo tiền bạc chi phối cuộc sống của anh ấy sau khi mất việc."},{"en":"A few large companies dominate the market for mobile phones.","vi":"Một vài công ty lớn thống trị thị trường điện thoại di động."}]','[{"phrase":"dominate the market"},{"phrase":"dominate the conversation"},{"phrase":"dominate the news"}]',NULL,'/ˈdɑːmɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domin/dominate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1975,'ngsl-5-01',4,'supplier','nhà cung cấp','noun','[{"en":"We found a cheaper supplier for our office paper.","vi":"Chúng tôi đã tìm được một nhà cung cấp giấy văn phòng rẻ hơn."},{"en":"The restaurant buys fresh vegetables from a local supplier every morning.","vi":"Nhà hàng mua rau tươi từ một nhà cung cấp địa phương mỗi sáng."},{"en":"If our supplier delivers late again, we will have to find another one.","vi":"Nếu nhà cung cấp lại giao hàng trễ, chúng ta sẽ phải tìm nhà cung cấp khác."}]','[{"phrase":"local supplier"},{"phrase":"main supplier"},{"phrase":"energy supplier"}]',NULL,'/səˈplaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supplier__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1976,'ngsl-5-01',5,'prize','giải thưởng; phần thưởng','noun','[{"en":"She won first prize in the school drawing contest.","vi":"Cô ấy đã giành giải nhất trong cuộc thi vẽ của trường."},{"en":"The prize for the winning team is a trip to the beach.","vi":"Giải thưởng cho đội chiến thắng là một chuyến đi biển."},{"en":"Everyone who finishes the race will get a small prize.","vi":"Tất cả những ai hoàn thành cuộc đua sẽ nhận được một phần thưởng nhỏ."}]','[{"phrase":"win a prize"},{"phrase":"first prize"},{"phrase":"prize money"}]',NULL,'/praɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prize/prize__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1977,'ngsl-5-01',6,'typically','thường; thông thường; một cách điển hình','adverb','[{"en":"The trip typically takes about three hours by train.","vi":"Chuyến đi bằng tàu hỏa thường mất khoảng ba tiếng."},{"en":"Typically, we have dinner together at seven o''clock.","vi":"Thông thường, chúng tôi ăn tối cùng nhau lúc bảy giờ."},{"en":"The weather was typically cold and wet for November.","vi":"Thời tiết lạnh và ẩm ướt, đúng kiểu điển hình của tháng Mười Một."}]','[{"phrase":"typically take"},{"phrase":"typically include"},{"phrase":"typically used"}]',NULL,'/ˈtɪpɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/typ/typic/typically__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1978,'ngsl-5-01',7,'peer','bạn đồng trang lứa; người ngang hàng; đồng nghiệp','noun','[{"en":"Teenagers often care a lot about what their peers think.","vi":"Thanh thiếu niên thường rất quan tâm đến suy nghĩ của bạn bè đồng trang lứa."},{"en":"Peer pressure can make children do things they don''t want to do.","vi":"Áp lực từ bạn bè có thể khiến trẻ làm những việc mà chúng không muốn làm."},{"en":"New staff are trained by their peers during the first week.","vi":"Nhân viên mới được các đồng nghiệp đào tạo trong tuần đầu tiên."}]','[{"phrase":"peer pressure"},{"phrase":"peer group"},{"phrase":"peer support"}]',NULL,'/pɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pee/peer_/peer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1979,'ngsl-5-01',8,'pension','lương hưu','noun','[{"en":"My grandfather lives on a small pension.","vi":"Ông tôi sống bằng một khoản lương hưu nhỏ."},{"en":"She will start receiving her pension when she turns sixty.","vi":"Bà ấy sẽ bắt đầu nhận lương hưu khi tròn sáu mươi tuổi."},{"en":"Many workers pay into a pension plan through their company.","vi":"Nhiều người lao động đóng tiền vào chương trình hưu trí thông qua công ty của họ."}]','[{"phrase":"pension plan"},{"phrase":"receive a pension"},{"phrase":"pension fund"}]',NULL,'/ˈpɛnʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1980,'ngsl-5-01',9,'wing','cánh (chim, máy bay); dãy nhà','noun','[{"en":"The bird hurt its wing and could not fly.","vi":"Con chim bị thương ở cánh và không thể bay."},{"en":"From my window seat, I could only see the plane''s wing.","vi":"Từ ghế cạnh cửa sổ, tôi chỉ có thể nhìn thấy cánh máy bay."},{"en":"The children''s ward is in the east wing of the hospital.","vi":"Khoa nhi nằm ở dãy nhà phía đông của bệnh viện."}]','[{"phrase":"east wing"},{"phrase":"chicken wings"},{"phrase":"spread its wings"}]',NULL,'/wɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/wing_/wing__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1981,'ngsl-5-01',10,'acquisition','sự mua lại; sự tiếp thu; vật mới mua được','noun','[{"en":"The acquisition of the smaller company took almost a year.","vi":"Việc mua lại công ty nhỏ hơn mất gần một năm."},{"en":"Language acquisition is much faster in young children than in adults.","vi":"Việc tiếp thu ngôn ngữ ở trẻ nhỏ nhanh hơn nhiều so với ở người lớn."},{"en":"The museum''s latest acquisition is a painting from the 1800s.","vi":"Hiện vật mới nhất mà bảo tàng mua về là một bức tranh từ thế kỷ 19."}]','[{"phrase":"language acquisition"},{"phrase":"acquisition of"},{"phrase":"recent acquisition"}]',NULL,'/ˌækwɪˈzɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acq/acqui/acquisition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1982,'ngsl-5-01',11,'laughter','tiếng cười; sự cười đùa','noun','[{"en":"We could hear laughter coming from the kitchen.","vi":"Chúng tôi có thể nghe thấy tiếng cười vọng ra từ nhà bếp."},{"en":"The whole audience burst into laughter at his joke.","vi":"Cả khán giả bật cười trước câu đùa của anh ấy."},{"en":"They say laughter is the best medicine.","vi":"Người ta nói tiếng cười là liều thuốc tốt nhất."}]','[{"phrase":"burst into laughter"},{"phrase":"loud laughter"},{"phrase":"full of laughter"}]','không đếm được','/ˈlæftər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lau/laugh/laughter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1983,'ngsl-5-01',12,'deeply','vô cùng; sâu sắc; sâu','adverb','[{"en":"I was deeply moved by her kind letter.","vi":"Tôi vô cùng xúc động trước lá thư đầy tử tế của cô ấy."},{"en":"He is deeply sorry for what he said.","vi":"Anh ấy vô cùng hối hận về những gì mình đã nói."},{"en":"Take a moment to breathe deeply before you start speaking.","vi":"Hãy dành chút thời gian hít thở sâu trước khi bắt đầu nói."}]','[{"phrase":"deeply moved"},{"phrase":"breathe deeply"},{"phrase":"deeply concerned"}]',NULL,'/ˈdiːpli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dee/deepl/deeply__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1984,'ngsl-5-01',13,'recognition','sự công nhận; sự nhận ra','noun','[{"en":"She finally received recognition for her years of hard work.","vi":"Cuối cùng cô ấy cũng được công nhận cho nhiều năm làm việc chăm chỉ."},{"en":"He was given an award in recognition of his service.","vi":"Ông ấy được trao giải thưởng để ghi nhận những cống hiến của mình."},{"en":"The town has changed beyond recognition since I was a child.","vi":"Thị trấn đã thay đổi đến mức không thể nhận ra kể từ khi tôi còn nhỏ."}]','[{"phrase":"in recognition of"},{"phrase":"receive recognition"},{"phrase":"beyond recognition"}]',NULL,'/ˌrekəɡˈnɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recog/recognition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1985,'ngsl-5-01',14,'electricity','điện','noun','[{"en":"The storm left the whole village without electricity for two days.","vi":"Cơn bão khiến cả làng bị mất điện suốt hai ngày."},{"en":"Turn off the lights when you leave to save electricity.","vi":"Hãy tắt đèn khi ra ngoài để tiết kiệm điện."},{"en":"Our electricity bill is much higher in the summer.","vi":"Hóa đơn tiền điện của chúng tôi cao hơn nhiều vào mùa hè."}]','[{"phrase":"electricity bill"},{"phrase":"save electricity"},{"phrase":"generate electricity"}]','không đếm được','/ɪˌlekˈtrɪsəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/electricity__us_6.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1986,'ngsl-5-01',15,'assistance','sự giúp đỡ; sự hỗ trợ','noun','[{"en":"Please call the front desk if you need any assistance.","vi":"Vui lòng gọi cho quầy lễ tân nếu bạn cần hỗ trợ."},{"en":"The school offers financial assistance to students from poor families.","vi":"Nhà trường hỗ trợ tài chính cho học sinh từ các gia đình nghèo."},{"en":"With the assistance of a neighbor, she moved the heavy sofa.","vi":"Nhờ sự giúp đỡ của một người hàng xóm, cô ấy đã chuyển được chiếc ghế sofa nặng."}]','[{"phrase":"financial assistance"},{"phrase":"with the assistance of"},{"phrase":"provide assistance"}]','không đếm được','/əˈsɪstəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assistance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1987,'ngsl-5-01',16,'roof','mái nhà','noun','[{"en":"The roof leaks every time it rains heavily.","vi":"Mái nhà bị dột mỗi khi trời mưa to."},{"en":"We climbed onto the roof to watch the fireworks.","vi":"Chúng tôi trèo lên mái nhà để xem pháo hoa."},{"en":"My cousin and I grew up under the same roof.","vi":"Tôi và anh họ lớn lên dưới cùng một mái nhà."}]','[{"phrase":"on the roof"},{"phrase":"under the same roof"},{"phrase":"leaking roof"}]',NULL,'/ruːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roo/roof_/roof__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1988,'ngsl-5-01',17,'retirement','sự nghỉ hưu; tuổi nghỉ hưu','noun','[{"en":"My parents are planning to travel a lot in retirement.","vi":"Bố mẹ tôi dự định sẽ đi du lịch nhiều khi nghỉ hưu."},{"en":"She announced her retirement after thirty years of teaching.","vi":"Bà ấy tuyên bố nghỉ hưu sau ba mươi năm dạy học."},{"en":"It is never too early to start saving for retirement.","vi":"Không bao giờ là quá sớm để bắt đầu tiết kiệm cho tuổi nghỉ hưu."}]','[{"phrase":"early retirement"},{"phrase":"retirement age"},{"phrase":"in retirement"}]',NULL,'/rɪˈtaɪərmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retir/retirement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1989,'ngsl-5-01',18,'respectively','lần lượt; tương ứng','adverb','[{"en":"My two sons are six and nine years old, respectively.","vi":"Hai con trai tôi lần lượt sáu và chín tuổi."},{"en":"Coffee and tea cost three and two dollars, respectively.","vi":"Cà phê và trà có giá lần lượt là ba và hai đô la."},{"en":"The morning and evening classes start at eight and six, respectively.","vi":"Lớp buổi sáng và buổi tối lần lượt bắt đầu lúc tám giờ và sáu giờ."}]','[{"phrase":"A and B, respectively"},{"phrase":"rose by 5% and 8%, respectively"}]','Thường đứng cuối câu, sau các mục liệt kê theo thứ tự','/rɪˈspektɪvli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respe/respectively__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1990,'ngsl-5-01',19,'variation','sự thay đổi; sự khác biệt; biến thể','noun','[{"en":"There is little variation in temperature here throughout the year.","vi":"Ở đây nhiệt độ ít thay đổi trong suốt cả năm."},{"en":"This recipe is a variation on a traditional family dish.","vi":"Công thức này là một biến thể của một món ăn truyền thống trong gia đình."},{"en":"Prices show a lot of variation from one shop to another.","vi":"Giá cả khác biệt khá nhiều giữa cửa hàng này với cửa hàng khác."}]','[{"phrase":"variation in"},{"phrase":"variation on"},{"phrase":"wide variation"}]',NULL,'/ˌveriˈeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/varia/variation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1991,'ngsl-5-01',20,'ultimately','cuối cùng; rốt cuộc','adverb','[{"en":"Ultimately, the decision is yours to make.","vi":"Rốt cuộc thì quyết định vẫn là ở bạn."},{"en":"We tried several plans, but ultimately we had to cancel the trip.","vi":"Chúng tôi đã thử vài kế hoạch, nhưng cuối cùng vẫn phải hủy chuyến đi."},{"en":"Hard work will ultimately lead to success.","vi":"Làm việc chăm chỉ cuối cùng sẽ dẫn đến thành công."}]','[{"phrase":"ultimately responsible"},{"phrase":"ultimately lead to"},{"phrase":"ultimately decide"}]',NULL,'/ˈʌltɪmətli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ult/ultim/ultimately__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1992,'ngsl-5-01',21,'proof','bằng chứng; giấy tờ chứng minh','noun','[{"en":"You need proof of address to open a bank account.","vi":"Bạn cần giấy tờ chứng minh địa chỉ để mở tài khoản ngân hàng."},{"en":"There is no proof that he took the money.","vi":"Không có bằng chứng nào cho thấy anh ta đã lấy tiền."},{"en":"Keep your receipt as proof of purchase.","vi":"Hãy giữ hóa đơn làm bằng chứng mua hàng."}]','[{"phrase":"proof of purchase"},{"phrase":"proof of identity"},{"phrase":"no proof"}]',NULL,'/pruːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proof/proof__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1993,'ngsl-5-01',22,'soil','đất; đất trồng','noun','[{"en":"Carrots grow well in soft, sandy soil.","vi":"Cà rốt phát triển tốt trong đất cát tơi xốp."},{"en":"The soil in our garden is too dry for roses.","vi":"Đất trong vườn nhà chúng tôi quá khô để trồng hoa hồng."},{"en":"Push the seeds gently into the soil and water them.","vi":"Nhẹ nhàng ấn hạt giống xuống đất rồi tưới nước."}]','[{"phrase":"rich soil"},{"phrase":"sandy soil"},{"phrase":"dry soil"}]',NULL,'/sɔɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/soi/soil_/soil__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1994,'ngsl-5-01',23,'smart','thông minh; khôn ngoan; bảnh bao','adjective','[{"en":"She is a smart student who learns new things quickly.","vi":"Cô ấy là một học sinh thông minh, học điều mới rất nhanh."},{"en":"Bringing an umbrella today was a smart move.","vi":"Mang theo ô hôm nay là một quyết định khôn ngoan."},{"en":"He looked very smart in his new suit.","vi":"Anh ấy trông rất bảnh bao trong bộ vest mới."}]','[{"phrase":"smart move"},{"phrase":"smart choice"},{"phrase":"look smart"}]',NULL,'/smɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sma/smart/smart__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1995,'ngsl-5-01',24,'layer','lớp; tầng','noun','[{"en":"A thin layer of dust covered the old piano.","vi":"Một lớp bụi mỏng phủ lên chiếc đàn piano cũ."},{"en":"Wear several layers of clothing when you go hiking in winter.","vi":"Hãy mặc nhiều lớp quần áo khi đi bộ đường dài vào mùa đông."},{"en":"The cake has three layers with cream between them.","vi":"Chiếc bánh có ba tầng với kem ở giữa."}]','[{"phrase":"thin layer"},{"phrase":"layer of dust"},{"phrase":"outer layer"},{"phrase":"top layer"}]',NULL,'/ˈleɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lay/layer/layer__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1996,'ngsl-5-01',25,'upset','buồn bực; khó chịu; lo lắng','adjective','[{"en":"She was upset because nobody remembered her birthday.","vi":"Cô ấy buồn vì không ai nhớ sinh nhật mình."},{"en":"Don''t get upset about such a small mistake.","vi":"Đừng bực mình vì một lỗi nhỏ như vậy."},{"en":"My little brother gets upset whenever he loses a game.","vi":"Em trai tôi hay khó chịu mỗi khi thua một trò chơi."}]','[{"phrase":"get upset"},{"phrase":"upset about"},{"phrase":"upset stomach"}]','Động từ: upset – upset – upset','/ˌʌpˈset/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ups/upset/upset__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1997,'ngsl-5-01',26,'tooth','răng','noun','[{"en":"I broke a tooth while eating hard candy.","vi":"Tôi bị gãy một chiếc răng khi ăn kẹo cứng."},{"en":"Remember to brush your teeth before going to bed.","vi":"Hãy nhớ đánh răng trước khi đi ngủ."},{"en":"My daughter lost her first baby tooth last night.","vi":"Con gái tôi bị rụng chiếc răng sữa đầu tiên tối qua."}]','[{"phrase":"brush your teeth"},{"phrase":"baby tooth"},{"phrase":"wisdom tooth"},{"phrase":"sweet tooth"}]','Số nhiều: teeth','/tuːθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/too/tooth/tooth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1998,'ngsl-5-01',27,'representation','sự đại diện; sự thể hiện','noun','[{"en":"The workers asked for fair representation in talks with management.","vi":"Công nhân yêu cầu được đại diện công bằng trong các cuộc đàm phán với ban quản lý."},{"en":"The painting is a representation of life in a small village.","vi":"Bức tranh là sự thể hiện cuộc sống ở một ngôi làng nhỏ."},{"en":"This map gives a simple representation of the city''s bus routes.","vi":"Bản đồ này thể hiện một cách đơn giản các tuyến xe buýt của thành phố."}]','[{"phrase":"fair representation"},{"phrase":"legal representation"},{"phrase":"visual representation"}]',NULL,'/ˌreprɪzenˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repre/representation__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(1999,'ngsl-5-01',28,'preparation','sự chuẩn bị','noun','[{"en":"The wedding took months of careful preparation.","vi":"Đám cưới mất nhiều tháng chuẩn bị kỹ lưỡng."},{"en":"We bought extra water in preparation for the storm.","vi":"Chúng tôi mua thêm nước để chuẩn bị cho cơn bão."},{"en":"Good preparation is the key to passing any exam.","vi":"Chuẩn bị tốt là chìa khóa để vượt qua bất kỳ kỳ thi nào."}]','[{"phrase":"in preparation for"},{"phrase":"careful preparation"},{"phrase":"exam preparation"}]',NULL,'/ˌprepəˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prepa/preparation__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2000,'ngsl-5-01',29,'dispute','cuộc tranh chấp; sự bất đồng','noun','[{"en":"The two neighbors had a long dispute over the fence.","vi":"Hai người hàng xóm đã có một cuộc tranh chấp kéo dài về hàng rào."},{"en":"The company settled the dispute with its workers last week.","vi":"Tuần trước công ty đã giải quyết xong tranh chấp với công nhân."},{"en":"The ownership of the house is still in dispute.","vi":"Quyền sở hữu ngôi nhà vẫn đang bị tranh chấp."}]','[{"phrase":"settle a dispute"},{"phrase":"dispute over"},{"phrase":"in dispute"},{"phrase":"legal dispute"}]',NULL,'/dɪˈspjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dispu/dispute__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2001,'ngsl-5-01',30,'agenda','chương trình họp; chương trình nghị sự; ưu tiên cần làm','noun','[{"en":"What''s the first item on the agenda for today''s meeting?","vi":"Mục đầu tiên trong chương trình họp hôm nay là gì?"},{"en":"Please send me the agenda before the meeting starts.","vi":"Vui lòng gửi cho tôi chương trình họp trước khi cuộc họp bắt đầu."},{"en":"Saving money is high on my agenda this year.","vi":"Tiết kiệm tiền là ưu tiên hàng đầu của tôi trong năm nay."}]','[{"phrase":"on the agenda"},{"phrase":"set the agenda"},{"phrase":"item on the agenda"}]',NULL,'/əˈdʒendə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/agend/agenda__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2002,'ngsl-5-02',1,'emphasis','sự nhấn mạnh; sự chú trọng','noun','[{"en":"Our school puts a strong emphasis on reading every day.","vi":"Trường chúng tôi rất chú trọng việc đọc sách mỗi ngày."},{"en":"The new manager places more emphasis on teamwork than before.","vi":"Quản lý mới coi trọng tinh thần làm việc nhóm hơn trước."},{"en":"She said the last word with extra emphasis.","vi":"Cô ấy nhấn mạnh hơn ở từ cuối cùng."}]','[{"phrase":"put emphasis on"},{"phrase":"place emphasis on"},{"phrase":"strong emphasis"},{"phrase":"special emphasis"}]','emphasis on sth; số nhiều: emphases','/ˈemfəsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empha/emphasis__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2003,'ngsl-5-02',2,'edition','ấn bản; số (báo)','noun','[{"en":"I bought the latest edition of the travel guide before my trip.","vi":"Tôi đã mua ấn bản mới nhất của cuốn sách hướng dẫn du lịch trước chuyến đi."},{"en":"This book is a first edition, so it is worth a lot.","vi":"Cuốn sách này là ấn bản đầu tiên nên rất có giá trị."},{"en":"The story appeared in the Sunday edition of the local newspaper.","vi":"Câu chuyện được đăng trên số Chủ nhật của tờ báo địa phương."}]','[{"phrase":"new edition"},{"phrase":"latest edition"},{"phrase":"first edition"},{"phrase":"limited edition"}]','edition (ấn bản) ≠ addition (sự thêm vào)','/ɪˈdɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/editi/edition__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2004,'ngsl-5-02',3,'silver','bạc; màu bạc','noun','[{"en":"My grandmother gave me a small ring made of silver.","vi":"Bà tặng tôi một chiếc nhẫn nhỏ làm bằng bạc."},{"en":"He won a silver medal in the swimming race.","vi":"Anh ấy giành huy chương bạc ở cuộc thi bơi."},{"en":"She painted the old door silver to make it look modern.","vi":"Cô ấy sơn cánh cửa cũ màu bạc cho trông hiện đại."}]','[{"phrase":"silver medal"},{"phrase":"silver ring"},{"phrase":"solid silver"}]',NULL,'/ˈsɪlvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silve/silver__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2005,'ngsl-5-02',4,'entertainment','sự giải trí; chương trình giải trí','noun','[{"en":"There isn''t much entertainment for young people in this small town.","vi":"Ở thị trấn nhỏ này không có nhiều hoạt động giải trí cho giới trẻ."},{"en":"The hotel offers live entertainment every Friday and Saturday night.","vi":"Khách sạn có chương trình biểu diễn trực tiếp vào mỗi tối thứ Sáu và thứ Bảy."},{"en":"We watched a few old movies for entertainment during the long flight.","vi":"Chúng tôi xem vài bộ phim cũ để giải trí trong chuyến bay dài."}]','[{"phrase":"live entertainment"},{"phrase":"entertainment industry"},{"phrase":"for entertainment"}]','không đếm được','/ˌentərˈteɪnmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/entertainment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2006,'ngsl-5-02',5,'honest','trung thực; thẳng thắn','adjective','[{"en":"Please be honest with me and tell me what you really think.","vi":"Hãy thẳng thắn với tôi và cho tôi biết bạn thực sự nghĩ gì."},{"en":"He is an honest man who always pays his debts on time.","vi":"Anh ấy là người trung thực, luôn trả nợ đúng hạn."},{"en":"To be honest, I didn''t enjoy the movie very much.","vi":"Thành thật mà nói, tôi không thích bộ phim đó lắm."}]','[{"phrase":"be honest with"},{"phrase":"to be honest"},{"phrase":"honest answer"},{"phrase":"honest opinion"}]','chữ h câm: an honest man','/ˈɑːnɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hon/hones/honest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2007,'ngsl-5-02',6,'undertake','đảm nhận; tiến hành','verb','[{"en":"The city plans to undertake major repairs on the old bridge next year.","vi":"Thành phố dự định tiến hành sửa chữa lớn cây cầu cũ vào năm tới."},{"en":"She undertook the task of organizing the whole event by herself.","vi":"Cô ấy đã tự mình đảm nhận việc tổ chức toàn bộ sự kiện."},{"en":"Few students are willing to undertake such a difficult research project.","vi":"Rất ít sinh viên sẵn sàng thực hiện một dự án nghiên cứu khó như vậy."}]','[{"phrase":"undertake a task"},{"phrase":"undertake research"},{"phrase":"undertake a project"},{"phrase":"undertake a study"}]','undertake – undertook – undertaken','/ˌʌndərˈteɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undertake__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2008,'ngsl-5-02',7,'retail','bán lẻ; ngành bán lẻ','noun','[{"en":"My sister has worked in retail for almost ten years.","vi":"Chị tôi đã làm trong ngành bán lẻ gần mười năm."},{"en":"Online shopping has changed the way retail works in small towns.","vi":"Mua sắm trực tuyến đã thay đổi cách ngành bán lẻ vận hành ở các thị trấn nhỏ."},{"en":"The shop sells these jackets at half the normal retail price.","vi":"Cửa hàng bán những chiếc áo khoác này với giá bằng một nửa giá bán lẻ thông thường."}]','[{"phrase":"retail price"},{"phrase":"retail store"},{"phrase":"work in retail"},{"phrase":"retail sales"}]','retail (bán lẻ) ≠ wholesale (bán buôn)','/ˈriːteɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retai/retail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2009,'ngsl-5-02',8,'wire','dây điện; dây kim loại','noun','[{"en":"Be careful not to touch that loose wire behind the TV.","vi":"Cẩn thận đừng chạm vào sợi dây điện bị lỏng phía sau tivi."},{"en":"He fixed the broken fence with a piece of wire.","vi":"Anh ấy sửa hàng rào bị hỏng bằng một đoạn dây thép."},{"en":"The electrician replaced all the old wires in our kitchen.","vi":"Thợ điện đã thay toàn bộ dây điện cũ trong bếp nhà tôi."}]','[{"phrase":"electrical wire"},{"phrase":"copper wire"},{"phrase":"barbed wire"},{"phrase":"loose wire"}]',NULL,'/ˈwaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wir/wire_/wire__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2010,'ngsl-5-02',9,'unlikely','khó xảy ra; không chắc','adjective','[{"en":"It is unlikely to rain today, so leave your umbrella at home.","vi":"Hôm nay khó có mưa, nên cứ để ô ở nhà."},{"en":"She is unlikely to finish the report before Friday.","vi":"Cô ấy khó có thể hoàn thành bản báo cáo trước thứ Sáu."},{"en":"In the unlikely event of a fire, please use the stairs.","vi":"Trong trường hợp hiếm hoi xảy ra hỏa hoạn, vui lòng đi cầu thang bộ."}]','[{"phrase":"highly unlikely"},{"phrase":"very unlikely"},{"phrase":"unlikely to happen"},{"phrase":"in the unlikely event"}]','be unlikely to + V','/ʌnˈlaɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unl/unlik/unlikely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2011,'ngsl-5-02',10,'gay','đồng tính; đồng tính nam','adjective','[{"en":"My brother told our parents that he is gay.","vi":"Anh trai tôi đã nói với bố mẹ rằng anh ấy là người đồng tính."},{"en":"My two uncles are a gay couple who have been together for years.","vi":"Hai chú của tôi là một cặp đồng tính đã bên nhau nhiều năm."},{"en":"Many gay and lesbian students feel welcome at this university.","vi":"Nhiều sinh viên đồng tính nam và nữ cảm thấy được chào đón ở trường đại học này."}]','[{"phrase":"gay couple"},{"phrase":"gay man"},{"phrase":"gay community"}]','Nghĩa cũ ''vui vẻ'' nay rất ít dùng','/ɡeɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gay/gay__/gay__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2012,'ngsl-5-02',11,'publication','sự xuất bản; ấn phẩm','noun','[{"en":"Her first novel will be ready for publication next spring.","vi":"Cuốn tiểu thuyết đầu tay của cô ấy sẽ sẵn sàng xuất bản vào mùa xuân tới."},{"en":"The date of publication is printed on the first page.","vi":"Ngày xuất bản được in ở trang đầu tiên."},{"en":"Our company produces a monthly publication for its customers.","vi":"Công ty chúng tôi phát hành một ấn phẩm hằng tháng cho khách hàng."}]','[{"phrase":"date of publication"},{"phrase":"publication date"},{"phrase":"monthly publication"},{"phrase":"ready for publication"}]',NULL,'/ˌpʌblɪˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publication__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2013,'ngsl-5-02',12,'slight','nhẹ; nhỏ, không đáng kể','adjective','[{"en":"I have a slight headache, but I can still go to work.","vi":"Tôi hơi đau đầu, nhưng vẫn đi làm được."},{"en":"There has been a slight change in the plan.","vi":"Kế hoạch có một chút thay đổi."},{"en":"She speaks English with a slight French accent.","vi":"Cô ấy nói tiếng Anh hơi pha giọng Pháp."}]','[{"phrase":"slight change"},{"phrase":"slight increase"},{"phrase":"slight problem"},{"phrase":"slight accent"}]','not the slightest idea: hoàn toàn không biết','/slaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/sligh/slight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2014,'ngsl-5-02',13,'unknown','không rõ; không được biết đến','adjective','[{"en":"The cause of the fire is still unknown.","vi":"Nguyên nhân vụ cháy vẫn chưa rõ."},{"en":"The band was completely unknown until their song went viral online.","vi":"Ban nhạc hoàn toàn vô danh cho đến khi bài hát của họ gây sốt trên mạng."},{"en":"For unknown reasons, the train stopped in the middle of nowhere.","vi":"Không rõ vì lý do gì, đoàn tàu dừng lại giữa nơi đồng không mông quạnh."}]','[{"phrase":"for unknown reasons"},{"phrase":"completely unknown"},{"phrase":"relatively unknown"},{"phrase":"still unknown"}]',NULL,'/ˌʌnˈnəʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unk/unkno/unknown__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2015,'ngsl-5-02',14,'framework','khuôn khổ; bộ khung','noun','[{"en":"The report gives us a clear framework for making decisions.","vi":"Bản báo cáo cho chúng tôi một khuôn khổ rõ ràng để đưa ra quyết định."},{"en":"The workers built a wooden framework before adding the walls.","vi":"Các công nhân dựng một bộ khung gỗ trước khi làm tường."},{"en":"All new rules must work within the existing legal framework.","vi":"Mọi quy định mới phải nằm trong khuôn khổ pháp lý hiện hành."}]','[{"phrase":"legal framework"},{"phrase":"within the framework of"},{"phrase":"provide a framework"},{"phrase":"basic framework"}]',NULL,'/ˈfreɪmwɜːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/frame/framework__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2016,'ngsl-5-02',15,'zone','khu vực; vùng','noun','[{"en":"You can''t park here because it''s a no-parking zone.","vi":"Bạn không được đỗ xe ở đây vì đây là khu vực cấm đỗ."},{"en":"My parents live in a different time zone, so calling is hard.","vi":"Bố mẹ tôi sống ở múi giờ khác nên gọi điện khá khó khăn."},{"en":"Drivers must slow down in school zones.","vi":"Tài xế phải giảm tốc độ ở khu vực trường học."}]','[{"phrase":"time zone"},{"phrase":"school zone"},{"phrase":"no-parking zone"},{"phrase":"comfort zone"}]','time zone: múi giờ','/zəʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/z/zon/zone_/zone__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2017,'ngsl-5-02',16,'restrict','hạn chế; giới hạn','verb','[{"en":"The doctor told him to restrict the amount of salt he eats.","vi":"Bác sĩ bảo anh ấy hạn chế lượng muối ăn vào."},{"en":"Parking in this area is restricted to residents only.","vi":"Việc đỗ xe ở khu vực này chỉ giới hạn cho cư dân."},{"en":"Many parents restrict how much time their children spend online.","vi":"Nhiều bố mẹ giới hạn thời gian con cái dùng mạng."}]','[{"phrase":"restrict access to"},{"phrase":"restrict the use of"},{"phrase":"be restricted to"}]','restrict sth to sth','/rɪˈstrɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restrict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2018,'ngsl-5-02',17,'trace','dấu vết; một chút','noun','[{"en":"We searched the whole house, but there was no trace of my keys.","vi":"Chúng tôi lục khắp nhà nhưng không thấy tăm hơi chùm chìa khóa của tôi đâu."},{"en":"There were traces of mud on his shoes.","vi":"Có dấu vết bùn trên giày của anh ấy."},{"en":"I could hear a trace of sadness in her voice.","vi":"Tôi nghe thấy một chút buồn bã trong giọng nói của cô ấy."}]','[{"phrase":"without a trace"},{"phrase":"no trace of"},{"phrase":"leave a trace"}]','Động từ trace: lần theo, truy tìm','/treɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trace/trace__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2019,'ngsl-5-02',18,'inch','inch (2,54 cm); một khoảng rất nhỏ','noun','[{"en":"My son has grown two inches since last summer.","vi":"Con trai tôi đã cao thêm hai inch kể từ mùa hè năm ngoái."},{"en":"Cut the cake into small squares, about two inches wide.","vi":"Cắt bánh thành những miếng vuông nhỏ, rộng khoảng hai inch."},{"en":"The car stopped just inches from the little dog.","vi":"Chiếc xe dừng lại chỉ cách chú chó nhỏ trong gang tấc."}]','[{"phrase":"inch by inch"},{"phrase":"every inch of"},{"phrase":"inches away"}]','1 inch = 2,54 cm','/ɪntʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/inch_/inch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2020,'ngsl-5-02',19,'equivalent','tương đương','adjective','[{"en":"One cup is roughly equivalent to 240 milliliters.","vi":"Một cốc tương đương khoảng 240 mi-li-lít."},{"en":"Her weekly pay is equivalent to what I earn in a month.","vi":"Tiền lương một tuần của cô ấy tương đương số tiền tôi kiếm được trong một tháng."},{"en":"Is there an equivalent word for this in Vietnamese?","vi":"Trong tiếng Việt có từ nào tương đương với từ này không?"}]','[{"phrase":"equivalent to"},{"phrase":"roughly equivalent"},{"phrase":"the equivalent of"}]','be equivalent to sth','/ɪˈkwɪvələnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equiv/equivalent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2021,'ngsl-5-02',20,'solid','rắn, đặc; chắc chắn, vững chắc','adjective','[{"en":"Water becomes solid when the temperature drops below zero.","vi":"Nước trở thành thể rắn khi nhiệt độ xuống dưới không độ."},{"en":"This table is made of solid wood, so it will last.","vi":"Chiếc bàn này làm bằng gỗ nguyên khối nên sẽ bền."},{"en":"You need solid evidence before you accuse anyone of lying.","vi":"Bạn cần bằng chứng xác đáng trước khi buộc tội ai đó nói dối."}]','[{"phrase":"solid wood"},{"phrase":"solid food"},{"phrase":"solid evidence"},{"phrase":"solid foundation"}]',NULL,'/ˈsɑːlɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solid/solid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2022,'ngsl-5-02',21,'enterprise','doanh nghiệp; công việc kinh doanh','noun','[{"en":"The government offers loans to help small enterprises grow.","vi":"Chính phủ cho vay vốn để giúp các doanh nghiệp nhỏ phát triển."},{"en":"Her family runs a successful farming enterprise in the countryside.","vi":"Gia đình cô ấy điều hành một doanh nghiệp nông nghiệp thành công ở nông thôn."},{"en":"Starting a new enterprise always involves some risk.","vi":"Khởi sự một công việc kinh doanh mới luôn có rủi ro nhất định."}]','[{"phrase":"small enterprise"},{"phrase":"private enterprise"},{"phrase":"state enterprise"}]',NULL,'/ˈentərpraɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/enterprise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2023,'ngsl-5-02',22,'elderly','cao tuổi, lớn tuổi','adjective','[{"en":"He helps his elderly neighbor carry her shopping upstairs.","vi":"Anh ấy giúp bà hàng xóm lớn tuổi mang đồ đi chợ lên lầu."},{"en":"Please give your seat to elderly passengers on the bus.","vi":"Hãy nhường ghế cho hành khách cao tuổi trên xe buýt."},{"en":"The center provides free meals for the elderly in the area.","vi":"Trung tâm cung cấp bữa ăn miễn phí cho người cao tuổi trong khu vực."}]','[{"phrase":"elderly people"},{"phrase":"elderly parents"},{"phrase":"the elderly"},{"phrase":"elderly relatives"}]','the elderly: người cao tuổi; lịch sự hơn old','/ˈeldərli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eld/elder/elderly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2024,'ngsl-5-02',23,'owe','nợ; có được là nhờ','verb','[{"en":"I still owe my brother fifty dollars from last month.","vi":"Tôi vẫn còn nợ anh trai năm mươi đô la từ tháng trước."},{"en":"How much do I owe you for the coffee?","vi":"Tôi phải trả bạn bao nhiêu tiền cà phê?"},{"en":"She owes her success to her parents'' support.","vi":"Cô ấy có được thành công là nhờ sự ủng hộ của bố mẹ."}]','[{"phrase":"owe money"},{"phrase":"owe somebody a favor"},{"phrase":"owe an apology"},{"phrase":"owe something to"}]','owe sb sth / owe sth to sb','/əʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/owe/owe__/owe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2025,'ngsl-5-02',24,'governor','thống đốc; tỉnh trưởng','noun','[{"en":"The governor opened the new hospital on Monday morning.","vi":"Thống đốc đã khánh thành bệnh viện mới vào sáng thứ Hai."},{"en":"The central bank governor announced that interest rates would stay the same.","vi":"Thống đốc ngân hàng trung ương thông báo lãi suất sẽ giữ nguyên."},{"en":"He was elected governor of the state last year.","vi":"Ông ấy được bầu làm thống đốc bang vào năm ngoái."}]','[{"phrase":"state governor"},{"phrase":"central bank governor"},{"phrase":"provincial governor"}]',NULL,'/ˈɡʌvərnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gov/gover/governor__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2026,'ngsl-5-02',25,'uniform','đồng phục','noun','[{"en":"All students must wear a uniform to school.","vi":"Tất cả học sinh phải mặc đồng phục đến trường."},{"en":"The nurses changed out of their uniforms after work.","vi":"Các y tá thay đồng phục ra sau giờ làm."},{"en":"He looked very smart in his new police uniform.","vi":"Anh ấy trông rất bảnh bao trong bộ đồng phục cảnh sát mới."}]','[{"phrase":"school uniform"},{"phrase":"wear a uniform"},{"phrase":"police uniform"},{"phrase":"in uniform"}]',NULL,'/ˈjuːnɪfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unifo/uniform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2027,'ngsl-5-02',26,'port','cảng; thành phố cảng','noun','[{"en":"The ship will arrive at the port early tomorrow morning.","vi":"Con tàu sẽ cập cảng vào sáng sớm mai."},{"en":"Hai Phong is a busy port in northern Vietnam.","vi":"Hải Phòng là một thành phố cảng sầm uất ở miền Bắc Việt Nam."},{"en":"Our cruise stopped at three small ports along the coast.","vi":"Chuyến du thuyền của chúng tôi dừng ở ba cảng nhỏ dọc bờ biển."}]','[{"phrase":"busy port"},{"phrase":"fishing port"},{"phrase":"port city"},{"phrase":"arrive in port"}]','Cũng có nghĩa: cổng kết nối (USB port)','/pɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/port_/port__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2028,'ngsl-5-02',27,'pitch','sân (thi đấu); độ cao (âm thanh); lời chào hàng','noun','[{"en":"The players walked onto the pitch as the crowd cheered.","vi":"Các cầu thủ bước ra sân trong tiếng reo hò của khán giả."},{"en":"Her voice rises to a higher pitch when she gets excited.","vi":"Giọng cô ấy cao vút lên mỗi khi phấn khích."},{"en":"He gave a short sales pitch to every customer who walked in.","vi":"Anh ấy chào hàng ngắn gọn với mọi vị khách bước vào."}]','[{"phrase":"football pitch"},{"phrase":"sales pitch"},{"phrase":"high pitch"},{"phrase":"on the pitch"}]','pitch (sân) chủ yếu dùng ở Anh; Mỹ: field','/pɪtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pit/pitch/pitch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2029,'ngsl-5-02',28,'arrival','sự đến; người/vật mới đến','noun','[{"en":"Please check in at the front desk on arrival.","vi":"Vui lòng làm thủ tục ở quầy lễ tân khi đến nơi."},{"en":"The flight''s arrival was delayed by two hours because of fog.","vi":"Chuyến bay đến muộn hai tiếng vì sương mù."},{"en":"The whole family was excited about the arrival of the new baby.","vi":"Cả gia đình háo hức chờ đón em bé mới chào đời."}]','[{"phrase":"on arrival"},{"phrase":"arrival time"},{"phrase":"new arrival"},{"phrase":"arrival of"}]','arrive (v) → arrival (n)','/əˈraɪvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arriv/arrival__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2030,'ngsl-5-02',29,'contemporary','đương đại, hiện đại; cùng thời','adjective','[{"en":"The museum has a large collection of contemporary art.","vi":"Bảo tàng có một bộ sưu tập lớn về nghệ thuật đương đại."},{"en":"I prefer contemporary furniture to old-fashioned styles.","vi":"Tôi thích đồ nội thất hiện đại hơn đồ kiểu cổ."},{"en":"The writer''s letters give us a contemporary account of life in the 1800s.","vi":"Những lá thư của nhà văn cho chúng ta lời kể của người cùng thời về cuộc sống thế kỷ 19."}]','[{"phrase":"contemporary art"},{"phrase":"contemporary music"},{"phrase":"contemporary literature"},{"phrase":"contemporary design"}]',NULL,'/kənˈtempəreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontemporary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2031,'ngsl-5-02',30,'gate','cổng; cửa ra máy bay','noun','[{"en":"Please close the gate so the dog doesn''t run out.","vi":"Làm ơn đóng cổng lại để con chó không chạy ra ngoài."},{"en":"Passengers for the flight to Tokyo should go to gate 12.","vi":"Hành khách đi Tokyo vui lòng đến cửa số 12."},{"en":"The children waited for their parents at the school gate.","vi":"Bọn trẻ đợi bố mẹ ở cổng trường."}]','[{"phrase":"front gate"},{"phrase":"school gate"},{"phrase":"garden gate"},{"phrase":"boarding gate"}]',NULL,'/ɡeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gat/gate_/gate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2032,'ngsl-5-03',1,'ease','sự dễ dàng; sự thoải mái','noun','[{"en":"She passed her driving test with ease on the first try.","vi":"Cô ấy đã dễ dàng vượt qua bài thi lái xe ngay lần đầu."},{"en":"This phone is popular because of its ease of use.","vi":"Chiếc điện thoại này được ưa chuộng vì dễ sử dụng."},{"en":"I felt at ease as soon as I met her family.","vi":"Tôi cảm thấy thoải mái ngay khi gặp gia đình cô ấy."}]','[{"phrase":"with ease"},{"phrase":"ease of use"},{"phrase":"at ease"},{"phrase":"feel at ease"}]',NULL,'/iːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/ease_/ease__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2033,'ngsl-5-03',2,'beer','bia','noun','[{"en":"Would you like a cold beer after work?","vi":"Bạn có muốn uống một cốc bia lạnh sau giờ làm không?"},{"en":"My father has a glass of beer with dinner on Fridays.","vi":"Bố tôi uống một cốc bia trong bữa tối vào các thứ Sáu."},{"en":"They ordered two beers and a plate of fries.","vi":"Họ gọi hai cốc bia và một đĩa khoai tây chiên."}]','[{"phrase":"cold beer"},{"phrase":"a glass of beer"},{"phrase":"drink beer"},{"phrase":"a bottle of beer"}]',NULL,'/bɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bee/beer_/beer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2034,'ngsl-5-03',3,'specialist','chuyên gia; bác sĩ chuyên khoa','noun','[{"en":"My doctor sent me to a heart specialist for more tests.","vi":"Bác sĩ chuyển tôi đến một bác sĩ chuyên khoa tim để làm thêm xét nghiệm."},{"en":"She works as a computer specialist at a large bank.","vi":"Cô ấy làm chuyên gia máy tính tại một ngân hàng lớn."},{"en":"We asked a specialist to check the old roof.","vi":"Chúng tôi đã nhờ một chuyên gia kiểm tra mái nhà cũ."}]','[{"phrase":"see a specialist"},{"phrase":"heart specialist"},{"phrase":"medical specialist"}]',NULL,'/ˈspeʃəlɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specialist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2035,'ngsl-5-03',4,'assure','cam đoan; đảm bảo (với ai)','verb','[{"en":"I can assure you that your bag will be safe here.","vi":"Tôi có thể cam đoan với bạn rằng túi của bạn để ở đây sẽ an toàn."},{"en":"The doctor assured us that the surgery went well.","vi":"Bác sĩ đảm bảo với chúng tôi rằng ca phẫu thuật đã diễn ra tốt đẹp."},{"en":"She assured her parents that she would call every week.","vi":"Cô ấy cam đoan với bố mẹ rằng sẽ gọi điện về mỗi tuần."}]','[{"phrase":"I can assure you"},{"phrase":"assure somebody that"},{"phrase":"rest assured"}]','assure (cam đoan với ai) ≠ ensure (đảm bảo việc gì xảy ra)','/əˈʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assur/assure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2036,'ngsl-5-03',5,'profile','hồ sơ; trang cá nhân; mặt nghiêng','noun','[{"en":"Please update your profile with your new phone number.","vi":"Vui lòng cập nhật số điện thoại mới vào trang cá nhân của bạn."},{"en":"The company keeps a detailed profile of each customer.","vi":"Công ty lưu một hồ sơ chi tiết về từng khách hàng."},{"en":"The photo shows the old man''s face in profile.","vi":"Bức ảnh chụp nghiêng khuôn mặt của ông lão."}]','[{"phrase":"update your profile"},{"phrase":"profile picture"},{"phrase":"in profile"}]',NULL,'/ˈprəʊfaɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profi/profile__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2037,'ngsl-5-03',6,'mood','tâm trạng; không khí','noun','[{"en":"I''m not in the mood to cook tonight.","vi":"Tối nay tôi không có tâm trạng nấu ăn."},{"en":"She was in a good mood after the long weekend.","vi":"Cô ấy có tâm trạng tốt sau kỳ nghỉ cuối tuần dài."},{"en":"The mood at the party changed when the music stopped.","vi":"Không khí bữa tiệc thay đổi khi nhạc tắt."}]','[{"phrase":"in a good mood"},{"phrase":"in a bad mood"},{"phrase":"in the mood for"}]',NULL,'/muːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/moo/mood_/mood__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2038,'ngsl-5-03',7,'episode','tập (phim); giai đoạn, sự việc','noun','[{"en":"We watched three episodes of the show last night.","vi":"Tối qua chúng tôi đã xem ba tập của chương trình đó."},{"en":"I missed the final episode, so please don''t tell me the ending.","vi":"Tôi đã bỏ lỡ tập cuối, nên đừng kể cho tôi đoạn kết nhé."},{"en":"He doesn''t like to talk about that difficult episode in his life.","vi":"Anh ấy không thích nhắc đến giai đoạn khó khăn đó trong đời mình."}]','[{"phrase":"final episode"},{"phrase":"latest episode"},{"phrase":"next episode"}]',NULL,'/ˈepɪsəʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/epi/episo/episode__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2039,'ngsl-5-03',8,'crack','nứt; làm nứt; đập (trứng)','verb','[{"en":"The glass cracked when I poured hot water into it.","vi":"Chiếc cốc bị nứt khi tôi rót nước nóng vào."},{"en":"Crack two eggs into a bowl and mix them well.","vi":"Đập hai quả trứng vào bát rồi trộn đều."},{"en":"He fell off his bike and cracked a bone in his arm.","vi":"Anh ấy ngã xe đạp và bị rạn xương tay."}]','[{"phrase":"crack an egg"},{"phrase":"crack a joke"},{"phrase":"crack open"}]',NULL,'/kræk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/crack/crack__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2040,'ngsl-5-03',9,'numerous','nhiều; vô số','adjective','[{"en":"I have called the company numerous times this week.","vi":"Tuần này tôi đã gọi cho công ty rất nhiều lần."},{"en":"The city has numerous parks where families can relax.","vi":"Thành phố có rất nhiều công viên để các gia đình thư giãn."},{"en":"She has won numerous awards for her children''s books.","vi":"Cô ấy đã giành được vô số giải thưởng cho sách thiếu nhi của mình."}]','[{"phrase":"numerous times"},{"phrase":"on numerous occasions"},{"phrase":"numerous examples"}]',NULL,'/ˈnuːmərəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/num/numer/numerous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2041,'ngsl-5-03',10,'submit','nộp; đệ trình','verb','[{"en":"Please submit your homework by Friday morning.","vi":"Vui lòng nộp bài tập về nhà trước sáng thứ Sáu."},{"en":"I need to submit an application for the job by Monday.","vi":"Tôi cần nộp đơn xin công việc đó trước thứ Hai."},{"en":"All reports must be submitted to the manager before the meeting.","vi":"Tất cả báo cáo phải được nộp cho quản lý trước cuộc họp."}]','[{"phrase":"submit an application"},{"phrase":"submit a report"},{"phrase":"submit a proposal"}]',NULL,'/səbˈmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/submi/submit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2042,'ngsl-5-03',11,'symptom','triệu chứng; dấu hiệu','noun','[{"en":"Fever and a sore throat are common symptoms of the flu.","vi":"Sốt và đau họng là những triệu chứng thường gặp của bệnh cúm."},{"en":"Call your doctor if the symptoms get worse.","vi":"Hãy gọi cho bác sĩ nếu các triệu chứng nặng hơn."},{"en":"Feeling tired all the time can be a symptom of stress.","vi":"Lúc nào cũng thấy mệt mỏi có thể là dấu hiệu của căng thẳng."}]','[{"phrase":"common symptoms"},{"phrase":"mild symptoms"},{"phrase":"symptoms get worse"}]',NULL,'/ˈsɪmptəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sym/sympt/symptom__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2043,'ngsl-5-03',12,'virtually','hầu như; gần như','adverb','[{"en":"Virtually everyone in my class has a smartphone.","vi":"Hầu như ai trong lớp tôi cũng có điện thoại thông minh."},{"en":"It is virtually impossible to find a parking space here.","vi":"Gần như không thể tìm được chỗ đậu xe ở đây."},{"en":"The town was virtually empty during the holiday.","vi":"Thị trấn gần như vắng tanh trong kỳ nghỉ lễ."}]','[{"phrase":"virtually impossible"},{"phrase":"virtually everyone"},{"phrase":"virtually all"}]',NULL,'/ˈvɜːrtʃuəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vir/virtu/virtually__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2044,'ngsl-5-03',13,'era','kỷ nguyên; thời đại','noun','[{"en":"In the digital era, people rarely write letters by hand.","vi":"Trong thời đại kỹ thuật số, người ta hiếm khi viết thư tay."},{"en":"My grandparents grew up in an era without television.","vi":"Ông bà tôi lớn lên trong một thời đại chưa có tivi."},{"en":"The internet started a new era in the way people communicate.","vi":"Internet đã mở ra một kỷ nguyên mới trong cách con người giao tiếp."}]','[{"phrase":"a new era"},{"phrase":"the digital era"},{"phrase":"the end of an era"}]',NULL,'/ˈɪrə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/era/era__/era__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2045,'ngsl-5-03',14,'coverage','việc đưa tin; vùng phủ sóng; phạm vi bảo hiểm','noun','[{"en":"The news coverage of the storm lasted all evening.","vi":"Việc đưa tin về cơn bão kéo dài suốt buổi tối."},{"en":"Our phone company has poor coverage in the mountains.","vi":"Nhà mạng của chúng tôi phủ sóng kém ở vùng núi."},{"en":"Does your health insurance include coverage for dental care?","vi":"Bảo hiểm y tế của bạn có chi trả cho việc chăm sóc răng không?"}]','[{"phrase":"news coverage"},{"phrase":"media coverage"},{"phrase":"live coverage"},{"phrase":"insurance coverage"}]','không đếm được','/ˈkʌvərɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cov/cover/coverage__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2046,'ngsl-5-03',15,'tension','sự căng thẳng; độ căng','noun','[{"en":"You could feel the tension in the room during the meeting.","vi":"Bạn có thể cảm nhận sự căng thẳng trong phòng suốt cuộc họp."},{"en":"A hot bath helps reduce the tension in my shoulders.","vi":"Tắm nước nóng giúp giảm độ căng cứng ở vai tôi."},{"en":"There is some tension between the two brothers these days.","vi":"Dạo này giữa hai anh em có chút căng thẳng."}]','[{"phrase":"tension between"},{"phrase":"reduce tension"},{"phrase":"muscle tension"}]',NULL,'/ˈtenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tensi/tension__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2047,'ngsl-5-03',16,'cable','dây cáp; truyền hình cáp','noun','[{"en":"I need a longer charging cable for my phone.","vi":"Tôi cần một sợi cáp sạc dài hơn cho điện thoại."},{"en":"Can you plug this cable into the back of the TV?","vi":"Bạn cắm sợi cáp này vào phía sau tivi giúp tôi được không?"},{"en":"We stopped paying for cable because we watch everything online.","vi":"Chúng tôi ngừng trả tiền truyền hình cáp vì xem mọi thứ trên mạng."}]','[{"phrase":"charging cable"},{"phrase":"power cable"},{"phrase":"cable TV"}]',NULL,'/ˈkeɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cab/cable/cable__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2048,'ngsl-5-03',17,'sensitive','nhạy cảm; dễ bị tổn thương','adjective','[{"en":"My teeth are sensitive to cold drinks.","vi":"Răng tôi nhạy cảm với đồ uống lạnh."},{"en":"He is very sensitive, so be careful what you say.","vi":"Anh ấy rất dễ bị tổn thương, nên hãy cẩn thận khi nói."},{"en":"Money is a sensitive topic in many families.","vi":"Tiền bạc là một chủ đề nhạy cảm trong nhiều gia đình."}]','[{"phrase":"sensitive skin"},{"phrase":"sensitive to"},{"phrase":"sensitive topic"},{"phrase":"sensitive issue"}]',NULL,'/ˈsensətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/sensi/sensitive__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2049,'ngsl-5-03',18,'nervous','lo lắng; hồi hộp','adjective','[{"en":"I always feel nervous before a job interview.","vi":"Tôi luôn cảm thấy hồi hộp trước buổi phỏng vấn xin việc."},{"en":"She was too nervous to speak in front of the class.","vi":"Cô ấy quá lo lắng nên không dám nói trước lớp."},{"en":"Driving on busy roads makes my mother nervous.","vi":"Lái xe trên những con đường đông đúc khiến mẹ tôi lo lắng."}]','[{"phrase":"feel nervous"},{"phrase":"nervous about"},{"phrase":"get nervous"}]',NULL,'/ˈnɜːrvəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/ner/nervo/nervous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2050,'ngsl-5-03',19,'input','ý kiến đóng góp; dữ liệu đầu vào','noun','[{"en":"Thanks for your input on the new website design.","vi":"Cảm ơn ý kiến đóng góp của bạn về thiết kế trang web mới."},{"en":"We want some input from parents before we change the school rules.","vi":"Chúng tôi muốn nghe một số ý kiến từ phụ huynh trước khi thay đổi nội quy trường."},{"en":"The program checks the user''s input before saving it.","vi":"Chương trình kiểm tra dữ liệu người dùng nhập vào trước khi lưu."}]','[{"phrase":"input from"},{"phrase":"valuable input"},{"phrase":"user input"}]',NULL,'/ˈɪnpʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inp/input/input__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2051,'ngsl-5-03',20,'isolate','cô lập; cách ly','verb','[{"en":"Doctors isolated the sick child to protect the other patients.","vi":"Các bác sĩ đã cách ly đứa trẻ bị bệnh để bảo vệ những bệnh nhân khác."},{"en":"The heavy snow isolated the village for a week.","vi":"Tuyết rơi dày đã cô lập ngôi làng suốt một tuần."},{"en":"Working from home can make some people feel isolated.","vi":"Làm việc ở nhà có thể khiến một số người cảm thấy bị cô lập."}]','[{"phrase":"feel isolated"},{"phrase":"socially isolated"},{"phrase":"isolate from"}]',NULL,'/ˈaɪsəleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iso/isola/isolate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2052,'ngsl-5-03',21,'prisoner','tù nhân','noun','[{"en":"The prisoner was released after ten years in jail.","vi":"Người tù được thả sau mười năm ngồi tù."},{"en":"Visitors can only see prisoners on Sunday afternoons.","vi":"Khách thăm chỉ được gặp tù nhân vào chiều Chủ nhật."},{"en":"Police are still looking for the two prisoners who escaped.","vi":"Cảnh sát vẫn đang truy tìm hai tù nhân đã vượt ngục."}]','[{"phrase":"release a prisoner"},{"phrase":"escaped prisoner"},{"phrase":"prisoner of war"}]',NULL,'/ˈprɪznər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/priso/prisoner__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2053,'ngsl-5-03',22,'eliminate','loại bỏ; loại (khỏi cuộc thi)','verb','[{"en":"Good planning can eliminate the need for extra meetings.","vi":"Lên kế hoạch tốt có thể giúp không cần đến những cuộc họp thêm."},{"en":"Our team was eliminated in the first round of the tournament.","vi":"Đội chúng tôi đã bị loại ngay vòng đầu của giải đấu."},{"en":"Try to eliminate sugar from your diet for a month.","vi":"Hãy thử loại bỏ đường khỏi chế độ ăn của bạn trong một tháng."}]','[{"phrase":"eliminate the need"},{"phrase":"completely eliminate"},{"phrase":"be eliminated from"}]',NULL,'/ɪˈlɪmɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eli/elimi/eliminate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2054,'ngsl-5-03',23,'tight','chật; chặt; eo hẹp','adjective','[{"en":"These jeans feel too tight after the holidays.","vi":"Chiếc quần jean này mặc thấy chật quá sau kỳ nghỉ lễ."},{"en":"Make sure the lid is tight before you shake the bottle.","vi":"Hãy chắc chắn nắp đã được đậy chặt trước khi lắc chai."},{"en":"Money is tight, so we''re not going on vacation this year.","vi":"Tiền bạc eo hẹp nên năm nay chúng tôi sẽ không đi du lịch."}]','[{"phrase":"too tight"},{"phrase":"tight schedule"},{"phrase":"tight budget"},{"phrase":"money is tight"}]',NULL,'/taɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tig/tight/tight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2055,'ngsl-5-03',24,'wet','ướt; có mưa','adjective','[{"en":"Take off your wet shoes before you come inside.","vi":"Hãy cởi đôi giày ướt ra trước khi vào nhà."},{"en":"We all got wet because we forgot our umbrellas.","vi":"Tất cả chúng tôi đều bị ướt vì quên mang ô."},{"en":"It was a cold and wet day, so we stayed home.","vi":"Hôm đó trời lạnh và mưa nên chúng tôi ở nhà."}]','[{"phrase":"get wet"},{"phrase":"wet weather"},{"phrase":"soaking wet"}]',NULL,'/wet/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wet/wet__/wet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2056,'ngsl-5-03',25,'secondary','thứ yếu; (thuộc) trung học','adjective','[{"en":"For me, the salary is secondary to the people I work with.","vi":"Với tôi, mức lương là thứ yếu so với những người làm việc cùng mình."},{"en":"My sister teaches math at a secondary school.","vi":"Chị tôi dạy toán ở một trường trung học."},{"en":"Price was a secondary concern when we chose the hotel.","vi":"Giá cả chỉ là mối quan tâm thứ yếu khi chúng tôi chọn khách sạn."}]','[{"phrase":"secondary school"},{"phrase":"secondary education"},{"phrase":"secondary to"}]',NULL,'/ˈsekənderi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secon/secondary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2057,'ngsl-5-03',26,'welfare','phúc lợi; sự khỏe mạnh và an toàn','noun','[{"en":"Our manager really cares about staff welfare.","vi":"Quản lý của chúng tôi thực sự quan tâm đến phúc lợi của nhân viên."},{"en":"Animal welfare groups found new homes for the dogs.","vi":"Các tổ chức bảo vệ quyền lợi động vật đã tìm nhà mới cho những chú chó."},{"en":"Parents are responsible for the welfare of their children.","vi":"Cha mẹ có trách nhiệm chăm lo sức khỏe và sự an toàn của con cái."}]','[{"phrase":"animal welfare"},{"phrase":"child welfare"},{"phrase":"staff welfare"},{"phrase":"social welfare"}]','không đếm được','/ˈwelfer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/welfa/welfare__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2058,'ngsl-5-03',27,'recruit','tuyển; tuyển dụng','verb','[{"en":"The company plans to recruit fifty new workers this year.","vi":"Công ty dự định tuyển năm mươi công nhân mới trong năm nay."},{"en":"We need to recruit volunteers for the school fair.","vi":"Chúng tôi cần tuyển tình nguyện viên cho hội chợ của trường."},{"en":"She was recruited by a large bank straight after university.","vi":"Cô ấy được một ngân hàng lớn tuyển dụng ngay khi vừa tốt nghiệp đại học."}]','[{"phrase":"recruit staff"},{"phrase":"recruit volunteers"},{"phrase":"recruit new members"}]',NULL,'/rɪˈkruːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recru/recruit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2059,'ngsl-5-03',28,'exclude','loại trừ; không bao gồm; không cho tham gia','verb','[{"en":"The price of the tour excludes meals and drinks.","vi":"Giá tour không bao gồm đồ ăn và thức uống."},{"en":"The other kids excluded him from their games.","vi":"Những đứa trẻ khác không cho cậu ấy chơi cùng."},{"en":"We can''t exclude the possibility that the flight will be late.","vi":"Chúng ta không thể loại trừ khả năng chuyến bay sẽ bị trễ."}]','[{"phrase":"exclude from"},{"phrase":"exclude the possibility"},{"phrase":"feel excluded"}]',NULL,'/ɪkˈskluːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/exclu/exclude__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2060,'ngsl-5-03',29,'string','dây; dây đàn; chuỗi','noun','[{"en":"She tied the box with a piece of string.","vi":"Cô ấy buộc chiếc hộp bằng một sợi dây."},{"en":"One of the strings on my guitar broke last night.","vi":"Tối qua một dây đàn guitar của tôi bị đứt."},{"en":"Our team had a string of wins this season.","vi":"Mùa giải này đội chúng tôi đã có một chuỗi trận thắng."}]','[{"phrase":"a piece of string"},{"phrase":"guitar string"},{"phrase":"a string of"}]','Nghĩa "dây buộc" không đếm được: a piece of string','/strɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strin/string__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2061,'ngsl-5-03',30,'cloud','mây; đám (khói, bụi)','noun','[{"en":"There wasn''t a cloud in the sky all day.","vi":"Cả ngày trên trời không có một gợn mây."},{"en":"Dark clouds are coming, so bring your umbrella.","vi":"Mây đen đang kéo đến, nên hãy mang theo ô."},{"en":"A cloud of dust rose behind the truck.","vi":"Một đám bụi bốc lên phía sau chiếc xe tải."}]','[{"phrase":"dark clouds"},{"phrase":"a cloud of dust"},{"phrase":"a cloud of smoke"}]',NULL,'/klaʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/cloud/cloud__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2062,'ngsl-5-04',1,'persuade','thuyết phục','verb','[{"en":"She finally persuaded her parents to let her study abroad.","vi":"Cuối cùng cô ấy đã thuyết phục được bố mẹ cho mình đi du học."},{"en":"I tried to persuade him to stay, but he left anyway.","vi":"Tôi đã cố thuyết phục anh ấy ở lại, nhưng anh ấy vẫn đi."},{"en":"It took a long time to persuade my boss that the plan would work.","vi":"Phải mất rất lâu tôi mới thuyết phục được sếp rằng kế hoạch sẽ thành công."}]','[{"phrase":"try to persuade"},{"phrase":"persuade someone to do something"},{"phrase":"finally persuade"}]','persuade sb to do sth','/pərˈsweɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persu/persuade__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2063,'ngsl-5-04',2,'inspire','truyền cảm hứng; khơi dậy','verb','[{"en":"Her story inspired me to start running again.","vi":"Câu chuyện của cô ấy đã truyền cảm hứng cho tôi bắt đầu chạy bộ trở lại."},{"en":"A good teacher can inspire students to love learning.","vi":"Một giáo viên giỏi có thể truyền cảm hứng để học sinh yêu thích việc học."},{"en":"His calm words inspired confidence in the whole team.","vi":"Những lời nói điềm tĩnh của anh ấy đã khơi dậy niềm tin trong cả đội."}]','[{"phrase":"inspire confidence"},{"phrase":"inspired by"},{"phrase":"inspire someone to do something"}]',NULL,'/ɪnˈspaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inspi/inspire__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2064,'ngsl-5-04',3,'grand','lộng lẫy, tráng lệ; lớn lao','adjective','[{"en":"They stayed in a grand old hotel near the river.","vi":"Họ ở trong một khách sạn cổ tráng lệ gần bờ sông."},{"en":"The wedding was held in a grand hall with huge windows.","vi":"Đám cưới được tổ chức trong một hội trường lộng lẫy với những ô cửa sổ lớn."},{"en":"He has grand plans to open his own restaurant one day.","vi":"Anh ấy có kế hoạch lớn là một ngày nào đó sẽ mở nhà hàng riêng."}]','[{"phrase":"grand hotel"},{"phrase":"grand plans"},{"phrase":"grand opening"}]',NULL,'/ɡrænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grand/grand__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2065,'ngsl-5-04',4,'hence','vì vậy, do đó','adverb','[{"en":"The roads were icy this morning, hence the long delays.","vi":"Sáng nay đường đóng băng, vì vậy mới bị chậm trễ lâu như thế."},{"en":"The flights were cheap and hence very popular with students.","vi":"Các chuyến bay rẻ, do đó rất được sinh viên ưa chuộng."},{"en":"The shop is right next to the station, and hence always busy.","vi":"Cửa hàng nằm ngay cạnh nhà ga, do đó lúc nào cũng đông khách."}]','[{"phrase":"and hence"},{"phrase":"hence the name"},{"phrase":"hence the need"}]','Trang trọng, thường dùng trong văn viết','/hens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hen/hence/hence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2066,'ngsl-5-04',5,'crew','phi hành đoàn, thủy thủ đoàn; đội, nhóm (làm việc)','noun','[{"en":"The flight crew asked everyone to fasten their seat belts.","vi":"Phi hành đoàn yêu cầu mọi người thắt dây an toàn."},{"en":"The fishing boat had a crew of twelve men.","vi":"Chiếc thuyền đánh cá có thủy thủ đoàn gồm mười hai người."},{"en":"A film crew was working on our street all day.","vi":"Một đoàn làm phim đã làm việc trên phố nhà tôi cả ngày."}]','[{"phrase":"flight crew"},{"phrase":"film crew"},{"phrase":"crew member"},{"phrase":"cabin crew"}]',NULL,'/kruː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/crew_/crew__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2067,'ngsl-5-04',6,'phenomenon','hiện tượng','noun','[{"en":"Snow in this part of the country is a rare phenomenon.","vi":"Tuyết ở vùng này của đất nước là một hiện tượng hiếm gặp."},{"en":"Working from home has become a common phenomenon in recent years.","vi":"Làm việc tại nhà đã trở thành một hiện tượng phổ biến trong những năm gần đây."},{"en":"Scientists are still trying to explain this strange natural phenomenon.","vi":"Các nhà khoa học vẫn đang cố giải thích hiện tượng tự nhiên kỳ lạ này."}]','[{"phrase":"natural phenomenon"},{"phrase":"rare phenomenon"},{"phrase":"common phenomenon"},{"phrase":"social phenomenon"}]','Số nhiều: phenomena','/fəˈnɑːmɪnən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phe/pheno/phenomenon__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2068,'ngsl-5-04',7,'pupil','học sinh; con ngươi','noun','[{"en":"Our village school has about two hundred pupils.","vi":"Trường làng chúng tôi có khoảng hai trăm học sinh."},{"en":"Each pupil must bring a packed lunch on Friday.","vi":"Mỗi học sinh phải mang theo cơm trưa vào thứ Sáu."},{"en":"In bright light, the pupils of your eyes get smaller.","vi":"Dưới ánh sáng mạnh, con ngươi của mắt sẽ nhỏ lại."}]','[{"phrase":"primary school pupil"},{"phrase":"former pupil"},{"phrase":"pupils and teachers"}]','Hay dùng trong tiếng Anh-Anh; tiếng Mỹ thường dùng student','/ˈpjuːpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pup/pupil/pupil__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2069,'ngsl-5-04',8,'false','sai; giả, không thật','adjective','[{"en":"Decide whether each of these sentences is true or false.","vi":"Hãy xác định mỗi câu sau đây là đúng hay sai."},{"en":"He gave the police a false name and address.","vi":"Anh ta khai tên và địa chỉ giả với cảnh sát."},{"en":"The doctor didn''t want to give the family false hope.","vi":"Bác sĩ không muốn mang lại hy vọng hão huyền cho gia đình."}]','[{"phrase":"true or false"},{"phrase":"false name"},{"phrase":"false hope"},{"phrase":"false alarm"}]',NULL,'/fɔːls/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fal/false/false__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2070,'ngsl-5-04',9,'assist','hỗ trợ, giúp đỡ','verb','[{"en":"Two nurses assisted the doctor during the operation.","vi":"Hai y tá đã hỗ trợ bác sĩ trong ca phẫu thuật."},{"en":"Our staff will be happy to assist you with your luggage.","vi":"Nhân viên của chúng tôi rất sẵn lòng giúp bạn mang hành lý."},{"en":"She was hired to assist the manager with daily tasks.","vi":"Cô ấy được tuyển để hỗ trợ quản lý trong các công việc hằng ngày."}]','[{"phrase":"assist with"},{"phrase":"assist in"},{"phrase":"assist someone"}]','assist sb with/in sth','/əˈsɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2071,'ngsl-5-04',10,'restore','khôi phục; phục hồi, trùng tu','verb','[{"en":"It took three hours to restore power after the storm.","vi":"Phải mất ba tiếng mới khôi phục được điện sau cơn bão."},{"en":"They spent two years restoring the old farmhouse.","vi":"Họ đã mất hai năm để trùng tu ngôi nhà trang trại cũ."},{"en":"The new manager helped restore trust between staff and customers.","vi":"Người quản lý mới đã giúp khôi phục lòng tin giữa nhân viên và khách hàng."}]','[{"phrase":"restore power"},{"phrase":"restore trust"},{"phrase":"restore order"},{"phrase":"fully restored"}]',NULL,'/rɪˈstɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resto/restore__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2072,'ngsl-5-04',11,'formula','công thức; sữa công thức','noun','[{"en":"Can you remember the formula for the area of a circle?","vi":"Bạn có nhớ công thức tính diện tích hình tròn không?"},{"en":"There is no simple formula for a happy marriage.","vi":"Không có công thức đơn giản nào cho một cuộc hôn nhân hạnh phúc."},{"en":"She mixed the baby''s formula with warm water.","vi":"Cô ấy pha sữa công thức cho em bé bằng nước ấm."}]','[{"phrase":"mathematical formula"},{"phrase":"a formula for"},{"phrase":"simple formula"},{"phrase":"baby formula"}]','Số nhiều: formulas hoặc formulae','/ˈfɔːrmjələ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/formu/formula__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2073,'ngsl-5-04',12,'alter','thay đổi; sửa (quần áo)','verb','[{"en":"We had to alter our travel plans because of the rain.","vi":"Chúng tôi phải thay đổi kế hoạch du lịch vì trời mưa."},{"en":"Moving to the city completely altered her way of life.","vi":"Việc chuyển lên thành phố đã thay đổi hoàn toàn lối sống của cô ấy."},{"en":"I need to have these trousers altered before the wedding.","vi":"Tôi cần mang chiếc quần này đi sửa trước đám cưới."}]','[{"phrase":"alter plans"},{"phrase":"completely alter"},{"phrase":"significantly alter"}]','alter (thay đổi) ≠ altar (bàn thờ)','/ˈɔːltər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alter__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2074,'ngsl-5-04',13,'perceive','nhìn nhận, coi là; nhận thấy','verb','[{"en":"Many people perceive him as shy, but he''s actually very friendly.","vi":"Nhiều người coi anh ấy là người nhút nhát, nhưng thực ra anh ấy rất thân thiện."},{"en":"How is our company perceived by young customers?","vi":"Công ty chúng ta được khách hàng trẻ nhìn nhận như thế nào?"},{"en":"Children often perceive small changes that adults don''t notice.","vi":"Trẻ em thường nhận thấy những thay đổi nhỏ mà người lớn không để ý."}]','[{"phrase":"perceive something as"},{"phrase":"widely perceived"},{"phrase":"perceive a change"}]','perceive sb/sth as ...','/pərˈsiːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/perceive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2075,'ngsl-5-04',14,'routine','thói quen hằng ngày; nếp sinh hoạt','noun','[{"en":"Exercise is an important part of my morning routine.","vi":"Tập thể dục là một phần quan trọng trong thói quen buổi sáng của tôi."},{"en":"Having a new baby completely changed our daily routine.","vi":"Có thêm em bé đã thay đổi hoàn toàn nếp sinh hoạt hằng ngày của chúng tôi."},{"en":"I''m tired of doing the same boring routine every week.","vi":"Tôi chán phải lặp lại những việc nhàm chán y như nhau mỗi tuần."}]','[{"phrase":"daily routine"},{"phrase":"morning routine"},{"phrase":"normal routine"}]',NULL,'/ruːˈtiːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/routi/routine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2076,'ngsl-5-04',15,'sink','chìm; lún xuống; (mặt trời) lặn','verb','[{"en":"The small boat hit a rock and sank within minutes.","vi":"Chiếc thuyền nhỏ đâm vào đá và chìm chỉ trong vài phút."},{"en":"My feet sank into the soft, wet sand.","vi":"Chân tôi lún xuống lớp cát ướt và mềm."},{"en":"The sun was sinking behind the hills when we got home.","vi":"Mặt trời đang lặn dần sau những ngọn đồi khi chúng tôi về đến nhà."}]','[{"phrase":"sink to the bottom"},{"phrase":"sink into"},{"phrase":"slowly sink"}]','sink – sank – sunk','/sɪŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/sink_/sink__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2077,'ngsl-5-04',16,'stare','nhìn chằm chằm','verb','[{"en":"Why is that man over there staring at us?","vi":"Sao người đàn ông đằng kia cứ nhìn chằm chằm vào chúng ta vậy?"},{"en":"She stared out of the window, lost in thought.","vi":"Cô ấy nhìn đăm đăm ra ngoài cửa sổ, chìm trong suy nghĩ."},{"en":"It''s rude to stare at people on the bus.","vi":"Nhìn chằm chằm người khác trên xe buýt là bất lịch sự."}]','[{"phrase":"stare at"},{"phrase":"stare out of the window"},{"phrase":"stare into space"}]','stare at sb/sth','/ster/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stare/stare__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2078,'ngsl-5-04',17,'anymore','nữa (không … nữa)','adverb','[{"en":"I don''t live in that apartment anymore.","vi":"Tôi không còn sống ở căn hộ đó nữa."},{"en":"My kids don''t want to watch cartoons anymore.","vi":"Bọn trẻ nhà tôi không muốn xem phim hoạt hình nữa."},{"en":"We can''t afford to eat out every weekend anymore.","vi":"Chúng tôi không còn đủ tiền đi ăn ngoài mỗi cuối tuần nữa."}]','[{"phrase":"not anymore"},{"phrase":"don''t care anymore"},{"phrase":"not ... anymore"}]','Dùng trong câu phủ định/nghi vấn; Anh: any more · Mỹ: anymore','/ˌɛniːˈmɔr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2079,'ngsl-5-04',18,'hero','anh hùng, người hùng; nhân vật chính','noun','[{"en":"The firefighter became a local hero after saving the child.","vi":"Người lính cứu hỏa trở thành người hùng của địa phương sau khi cứu đứa bé."},{"en":"My father has always been my hero.","vi":"Bố luôn là người hùng của tôi."},{"en":"The hero of the story is a young farmer.","vi":"Nhân vật chính của câu chuyện là một chàng nông dân trẻ."}]','[{"phrase":"national hero"},{"phrase":"local hero"},{"phrase":"true hero"}]','Số nhiều: heroes','/ˈhɪrəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/her/hero_/hero__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2080,'ngsl-5-04',19,'supporter','người ủng hộ; cổ động viên','noun','[{"en":"Thousands of supporters came to watch the final match.","vi":"Hàng nghìn cổ động viên đã đến xem trận chung kết."},{"en":"My wife has always been my biggest supporter.","vi":"Vợ tôi luôn là người ủng hộ tôi nhiều nhất."},{"en":"Supporters of the new park say it will help local families.","vi":"Những người ủng hộ công viên mới cho rằng nó sẽ giúp ích cho các gia đình trong vùng."}]','[{"phrase":"strong supporter"},{"phrase":"biggest supporter"},{"phrase":"loyal supporter"},{"phrase":"football supporter"}]',NULL,'/səˈpɔːrtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppo/supporter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2081,'ngsl-5-04',20,'convert','chuyển đổi, quy đổi; cải tạo','verb','[{"en":"They converted the garage into a small office.","vi":"Họ đã cải tạo nhà để xe thành một văn phòng nhỏ."},{"en":"Can you convert these prices from dollars to euros?","vi":"Bạn có thể quy đổi các mức giá này từ đô la sang euro không?"},{"en":"Solar panels convert sunlight into electricity for the whole building.","vi":"Các tấm pin mặt trời chuyển ánh sáng mặt trời thành điện cho cả tòa nhà."}]','[{"phrase":"convert into"},{"phrase":"convert to"},{"phrase":"convert a file"}]','convert sth into/to sth','/kənˈvɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvert__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2082,'ngsl-5-04',21,'steady','đều đặn, ổn định; vững','adjective','[{"en":"Prices have seen a steady rise over the past year.","vi":"Giá cả đã tăng đều đặn trong năm qua."},{"en":"She has a steady job with a good salary.","vi":"Cô ấy có một công việc ổn định với mức lương tốt."},{"en":"Hold the ladder steady while I climb up.","vi":"Giữ thang cho vững trong khi tôi trèo lên."}]','[{"phrase":"steady job"},{"phrase":"steady rise"},{"phrase":"steady pace"},{"phrase":"steady growth"}]',NULL,'/ˈstedi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/stead/steady__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2083,'ngsl-5-04',22,'meter','mét; đồng hồ đo','noun','[{"en":"The swimming pool at our school is twenty-five meters long.","vi":"Hồ bơi ở trường chúng tôi dài hai mươi lăm mét."},{"en":"The tree in our yard is almost ten meters tall.","vi":"Cái cây trong sân nhà tôi cao gần mười mét."},{"en":"A man from the water company came to read the meter.","vi":"Một người của công ty cấp nước đã đến ghi chỉ số đồng hồ."}]','[{"phrase":"square meter"},{"phrase":"read the meter"},{"phrase":"parking meter"},{"phrase":"gas meter"}]','Anh: metre · Mỹ: meter','/ˈmiːtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/met/meter/meter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2084,'ngsl-5-04',23,'truck','xe tải','noun','[{"en":"A big truck was blocking the road this morning.","vi":"Sáng nay có một chiếc xe tải lớn chắn ngang đường."},{"en":"My uncle drives a delivery truck for a living.","vi":"Chú tôi lái xe tải giao hàng để kiếm sống."},{"en":"We rented a truck to move our furniture to the new house.","vi":"Chúng tôi thuê một chiếc xe tải để chuyển đồ đạc sang nhà mới."}]','[{"phrase":"truck driver"},{"phrase":"delivery truck"},{"phrase":"fire truck"},{"phrase":"drive a truck"}]','Anh: lorry · Mỹ: truck','/trʌk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/truck/truck__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2085,'ngsl-5-04',24,'nose','mũi','noun','[{"en":"My nose is running because I have a cold.","vi":"Tôi bị sổ mũi vì cảm lạnh."},{"en":"Please cover your nose and mouth when you sneeze.","vi":"Hãy che mũi và miệng khi bạn hắt hơi."},{"en":"He fell off his bike and broke his nose.","vi":"Anh ấy ngã xe đạp và bị gãy mũi."}]','[{"phrase":"runny nose"},{"phrase":"blow your nose"},{"phrase":"broken nose"}]',NULL,'/nəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nos/nose_/nose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2086,'ngsl-5-04',25,'beside','bên cạnh','preposition','[{"en":"Come and sit beside me on the sofa.","vi":"Lại đây ngồi cạnh tôi trên ghế sofa."},{"en":"There''s a small coffee shop beside the train station.","vi":"Có một quán cà phê nhỏ bên cạnh ga tàu."},{"en":"She always keeps a glass of water beside her bed.","vi":"Cô ấy luôn để một cốc nước bên cạnh giường."}]','[{"phrase":"sit beside"},{"phrase":"beside the road"},{"phrase":"beside the river"}]','beside (bên cạnh) ≠ besides (ngoài ra)','/bɪˈsaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bes/besid/beside__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2087,'ngsl-5-04',26,'sail','đi thuyền (buồm); (tàu) khởi hành','verb','[{"en":"We sailed around the islands for a whole week.","vi":"Chúng tôi đi thuyền vòng quanh các hòn đảo suốt một tuần."},{"en":"My grandfather taught me how to sail when I was ten.","vi":"Ông dạy tôi lái thuyền buồm khi tôi mười tuổi."},{"en":"The ship sails at six o''clock tomorrow morning.","vi":"Con tàu sẽ khởi hành lúc sáu giờ sáng mai."}]','[{"phrase":"go sailing"},{"phrase":"set sail"},{"phrase":"sail across"}]',NULL,'/seɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sai/sail_/sail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2088,'ngsl-5-04',27,'disaster','thảm họa; chuyện thất bại, tệ hại','noun','[{"en":"The flood was the worst natural disaster in the region''s history.","vi":"Trận lũ là thảm họa thiên nhiên tồi tệ nhất trong lịch sử khu vực."},{"en":"Our first camping trip was a complete disaster.","vi":"Chuyến cắm trại đầu tiên của chúng tôi là một thất bại hoàn toàn."},{"en":"Check the weather first, or the picnic could end in disaster.","vi":"Hãy xem thời tiết trước, không thì buổi dã ngoại có thể kết thúc tệ hại."}]','[{"phrase":"natural disaster"},{"phrase":"complete disaster"},{"phrase":"end in disaster"}]',NULL,'/dɪˈzæstər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disas/disaster__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2089,'ngsl-5-04',28,'pace','tốc độ, nhịp độ','noun','[{"en":"He walks at such a fast pace that it''s hard to keep up.","vi":"Anh ấy đi nhanh đến mức rất khó theo kịp."},{"en":"I prefer the slower pace of life in the countryside.","vi":"Tôi thích nhịp sống chậm rãi hơn ở vùng quê."},{"en":"With online courses, students can learn at their own pace.","vi":"Với các khóa học trực tuyến, học sinh có thể học theo tốc độ của riêng mình."}]','[{"phrase":"pace of life"},{"phrase":"at your own pace"},{"phrase":"fast pace"},{"phrase":"keep pace with"}]',NULL,'/peɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pac/pace_/pace__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2090,'ngsl-5-04',29,'heavily','(mưa) to, nặng hạt; nhiều, nặng nề','adverb','[{"en":"It rained heavily all night, so the streets flooded.","vi":"Trời mưa to suốt đêm nên đường phố bị ngập."},{"en":"He was breathing heavily after running up the stairs.","vi":"Anh ấy thở nặng nhọc sau khi chạy lên cầu thang."},{"en":"The town depends heavily on tourism for jobs.","vi":"Thị trấn phụ thuộc nhiều vào du lịch để tạo việc làm."}]','[{"phrase":"rain heavily"},{"phrase":"depend heavily on"},{"phrase":"breathe heavily"},{"phrase":"heavily influenced"}]',NULL,'/ˈhevɪli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/heavi/heavily__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2091,'ngsl-5-04',30,'devote','cống hiến; dành (thời gian, công sức)','verb','[{"en":"She devoted her whole life to helping poor children.","vi":"Bà ấy đã cống hiến cả cuộc đời để giúp đỡ trẻ em nghèo."},{"en":"I devote an hour every evening to learning English.","vi":"Mỗi tối tôi dành một tiếng để học tiếng Anh."},{"en":"The whole meeting was devoted to planning next year''s budget.","vi":"Cả cuộc họp được dành để lên kế hoạch ngân sách cho năm tới."}]','[{"phrase":"devote time to"},{"phrase":"devote your life to"},{"phrase":"devote attention to"}]','devote sth to sth/doing sth','/dɪˈvəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devot/devote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2092,'ngsl-5-05',1,'terrorist','kẻ khủng bố','noun','[{"en":"Police arrested two terrorists before they could carry out an attack.","vi":"Cảnh sát đã bắt giữ hai kẻ khủng bố trước khi chúng kịp thực hiện một vụ tấn công."},{"en":"The airport increased security after warnings about a possible terrorist threat.","vi":"Sân bay đã tăng cường an ninh sau những cảnh báo về mối đe dọa khủng bố có thể xảy ra."},{"en":"The film is about a spy who tries to stop a group of terrorists.","vi":"Bộ phim kể về một điệp viên tìm cách ngăn chặn một nhóm khủng bố."}]','[{"phrase":"terrorist attack"},{"phrase":"terrorist group"},{"phrase":"terrorist threat"}]',NULL,'/ˈterərɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/terro/terrorist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2093,'ngsl-5-05',2,'justify','biện minh; chứng minh là hợp lý','verb','[{"en":"How can you justify spending so much money on a new phone?","vi":"Làm sao bạn biện minh được cho việc tiêu nhiều tiền như vậy vào một chiếc điện thoại mới?"},{"en":"The excellent results justified all our hard work on the project.","vi":"Kết quả xuất sắc đã cho thấy mọi công sức vất vả của chúng tôi cho dự án là xứng đáng."},{"en":"You don''t need to justify your decision to anyone.","vi":"Bạn không cần phải biện minh cho quyết định của mình với bất kỳ ai."}]','[{"phrase":"justify a decision"},{"phrase":"justify the cost"},{"phrase":"difficult to justify"}]',NULL,'/ˈdʒʌstɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jus/justi/justify__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2094,'ngsl-5-05',3,'vital','rất quan trọng, thiết yếu','adjective','[{"en":"Regular exercise is vital for good health.","vi":"Tập thể dục thường xuyên rất quan trọng đối với sức khỏe."},{"en":"It is vital that you arrive on time for the exam.","vi":"Việc bạn đến đúng giờ dự thi là cực kỳ quan trọng."},{"en":"Water is vital to all living things on Earth.","vi":"Nước là thiết yếu đối với mọi sinh vật trên Trái Đất."}]','[{"phrase":"vital role"},{"phrase":"vital importance"},{"phrase":"absolutely vital"},{"phrase":"vital information"}]',NULL,'/ˈvaɪtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vit/vital/vital__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2095,'ngsl-5-05',4,'fascinate','làm say mê; thu hút','verb','[{"en":"Space has always fascinated my younger brother.","vi":"Vũ trụ luôn khiến em trai tôi say mê."},{"en":"The old stories about the city fascinate tourists from all over the world.","vi":"Những câu chuyện xưa về thành phố thu hút du khách từ khắp nơi trên thế giới."},{"en":"It fascinates me how quickly young children learn new languages.","vi":"Tôi thấy thật lý thú khi trẻ nhỏ học ngôn ngữ mới nhanh đến vậy."}]','[{"phrase":"be fascinated by"},{"phrase":"continue to fascinate"}]','Tính từ: fascinating (hấp dẫn), fascinated (bị cuốn hút)','/ˈfæsɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fas/fasci/fascinate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2096,'ngsl-5-05',5,'external','bên ngoài','adjective','[{"en":"The company hired an external expert to review its accounts.","vi":"Công ty đã thuê một chuyên gia bên ngoài để kiểm tra sổ sách kế toán."},{"en":"This cream is for external use only.","vi":"Loại kem này chỉ dùng ngoài da."},{"en":"Connect the external hard drive to your laptop to save the files.","vi":"Hãy kết nối ổ cứng gắn ngoài với máy tính xách tay để lưu các tệp."}]','[{"phrase":"external hard drive"},{"phrase":"external factors"},{"phrase":"for external use"},{"phrase":"external walls"}]','Trái nghĩa: internal (bên trong)','/ɪkˈstɜːrnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exter/external__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2097,'ngsl-5-05',6,'spare','dự phòng, dư; rảnh rỗi','adjective','[{"en":"What do you like doing in your spare time?","vi":"Bạn thích làm gì vào thời gian rảnh?"},{"en":"We keep a spare key under the flowerpot by the door.","vi":"Chúng tôi để một chiếc chìa khóa dự phòng dưới chậu hoa cạnh cửa."},{"en":"You can sleep in the spare room tonight.","vi":"Tối nay bạn có thể ngủ ở phòng trống."}]','[{"phrase":"spare time"},{"phrase":"spare key"},{"phrase":"spare room"},{"phrase":"spare parts"}]',NULL,'/sper/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spa/spare/spare__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2098,'ngsl-5-05',7,'whenever','bất cứ khi nào; mỗi khi','conjunction','[{"en":"Call me whenever you need help with your homework.","vi":"Hãy gọi cho tôi bất cứ khi nào bạn cần giúp làm bài tập."},{"en":"Whenever I visit my grandmother, she cooks my favorite soup.","vi":"Mỗi khi tôi đến thăm bà, bà lại nấu món súp tôi thích nhất."},{"en":"You can start the course whenever you are ready.","vi":"Bạn có thể bắt đầu khóa học bất cứ khi nào bạn sẵn sàng."}]','[{"phrase":"whenever possible"},{"phrase":"whenever you like"},{"phrase":"whenever you want"}]',NULL,'/wenˈevər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/whene/whenever__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2099,'ngsl-5-05',8,'depression','bệnh trầm cảm; suy thoái kinh tế','noun','[{"en":"After losing his job, he suffered from depression for months.","vi":"Sau khi mất việc, anh ấy bị trầm cảm suốt nhiều tháng."},{"en":"Talking to a doctor can help people who are dealing with depression.","vi":"Nói chuyện với bác sĩ có thể giúp những người đang phải đối mặt với chứng trầm cảm."},{"en":"Many families lost their homes during the depression of the 1930s.","vi":"Nhiều gia đình đã mất nhà trong cuộc suy thoái kinh tế những năm 1930."}]','[{"phrase":"suffer from depression"},{"phrase":"severe depression"},{"phrase":"economic depression"}]',NULL,'/dɪˈpreʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depre/depression__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2100,'ngsl-5-05',9,'guilty','có lỗi, áy náy; có tội','adjective','[{"en":"I feel guilty about forgetting my best friend''s birthday.","vi":"Tôi thấy có lỗi vì đã quên sinh nhật của bạn thân."},{"en":"The court found him guilty of stealing a car.","vi":"Tòa án tuyên anh ta phạm tội trộm xe hơi."},{"en":"Don''t feel guilty about taking a day off when you''re sick.","vi":"Đừng cảm thấy áy náy khi nghỉ một ngày lúc bạn bị ốm."}]','[{"phrase":"feel guilty"},{"phrase":"found guilty"},{"phrase":"guilty of"},{"phrase":"guilty conscience"}]','guilty of + danh từ/V-ing','/ˈɡɪlti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guilt/guilty__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2101,'ngsl-5-05',10,'underlie','làm nền tảng cho; là nguyên nhân sâu xa của','verb','[{"en":"Poor sleep often underlies problems with memory and focus.","vi":"Ngủ kém thường là nguyên nhân sâu xa của các vấn đề về trí nhớ và sự tập trung."},{"en":"The same simple idea underlies all of her stories.","vi":"Cùng một ý tưởng đơn giản làm nền tảng cho tất cả các câu chuyện của cô ấy."},{"en":"Doctors are still trying to find the cause that underlies her headaches.","vi":"Các bác sĩ vẫn đang cố tìm ra nguyên nhân sâu xa gây ra những cơn đau đầu của cô ấy."}]','[{"phrase":"underlying cause"},{"phrase":"underlying problem"},{"phrase":"underlying reason"}]','underlie – underlay – underlain; hay gặp dạng underlying (tiềm ẩn, cơ bản)','/ˌʌndərˈlaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/underlie__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2102,'ngsl-5-05',11,'mom','mẹ','noun','[{"en":"My mom always makes pancakes on Sunday mornings.","vi":"Mẹ tôi luôn làm bánh kếp vào sáng Chủ nhật."},{"en":"Can I go to the park with my friends, Mom?","vi":"Mẹ ơi, con đi công viên với các bạn được không ạ?"},{"en":"Please tell your mom thanks for the delicious dinner.","vi":"Nhờ bạn cảm ơn mẹ bạn giúp mình vì bữa tối ngon miệng nhé."}]','[{"phrase":"my mom"},{"phrase":"single mom"},{"phrase":"stay-at-home mom"},{"phrase":"working mom"}]','Anh: mum · Mỹ: mom','/mɑːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mom/mom__/mom__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2103,'ngsl-5-05',12,'distinction','sự phân biệt, khác biệt; loại xuất sắc','noun','[{"en":"It''s important to make a clear distinction between facts and opinions.","vi":"Điều quan trọng là phải phân biệt rõ ràng giữa sự thật và ý kiến."},{"en":"Young children slowly learn the distinction between right and wrong.","vi":"Trẻ nhỏ dần dần học được sự khác biệt giữa đúng và sai."},{"en":"She graduated with distinction from a top music school.","vi":"Cô ấy tốt nghiệp loại xuất sắc từ một trường âm nhạc hàng đầu."}]','[{"phrase":"make a distinction"},{"phrase":"clear distinction"},{"phrase":"distinction between"},{"phrase":"with distinction"}]',NULL,'/dɪˈstɪŋkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2104,'ngsl-5-05',13,'satisfaction','sự hài lòng, thỏa mãn','noun','[{"en":"At our hotel, customer satisfaction is always our top priority.","vi":"Tại khách sạn của chúng tôi, sự hài lòng của khách hàng luôn là ưu tiên hàng đầu."},{"en":"She felt a deep sense of satisfaction when she finished the marathon.","vi":"Cô ấy cảm thấy vô cùng mãn nguyện khi hoàn thành cuộc chạy marathon."},{"en":"Many workers say job satisfaction matters more to them than money.","vi":"Nhiều người lao động nói rằng sự hài lòng trong công việc quan trọng với họ hơn tiền bạc."}]','[{"phrase":"customer satisfaction"},{"phrase":"job satisfaction"},{"phrase":"sense of satisfaction"}]',NULL,'/ˌsætɪsˈfækʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sat/satis/satisfaction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2105,'ngsl-5-05',14,'incorporate','kết hợp, đưa vào','verb','[{"en":"We incorporated your suggestions into the final plan.","vi":"Chúng tôi đã đưa các đề xuất của bạn vào bản kế hoạch cuối cùng."},{"en":"Try to incorporate more vegetables into your daily meals.","vi":"Hãy cố gắng đưa thêm nhiều rau vào các bữa ăn hằng ngày."},{"en":"The new building incorporates many ideas for saving energy.","vi":"Tòa nhà mới kết hợp nhiều ý tưởng tiết kiệm năng lượng."}]','[{"phrase":"incorporate into"},{"phrase":"incorporate ideas"},{"phrase":"incorporate changes"}]','incorporate something into something','/ɪnˈkɔːrpəreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incor/incorporate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2106,'ngsl-5-05',15,'pour','rót, đổ; mưa như trút','verb','[{"en":"Could you pour me a glass of water, please?","vi":"Bạn rót giúp tôi một cốc nước được không?"},{"en":"Pour the milk into the bowl and stir gently.","vi":"Đổ sữa vào bát rồi khuấy nhẹ."},{"en":"It poured all afternoon, so we stayed inside and played games.","vi":"Trời mưa như trút cả buổi chiều nên chúng tôi ở trong nhà chơi trò chơi."}]','[{"phrase":"pour a drink"},{"phrase":"pour into"},{"phrase":"pouring rain"}]',NULL,'/pɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pou/pour_/pour__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2107,'ngsl-5-05',16,'sweep','quét; quét qua, tràn qua','verb','[{"en":"Can you sweep the kitchen floor after dinner?","vi":"Bạn quét sàn bếp sau bữa tối được không?"},{"en":"He swept the leaves off the front steps.","vi":"Anh ấy quét lá khỏi bậc thềm trước nhà."},{"en":"A strong wind swept through the town last night.","vi":"Đêm qua một cơn gió mạnh đã quét qua thị trấn."}]','[{"phrase":"sweep the floor"},{"phrase":"sweep away"},{"phrase":"sweep through"}]','sweep – swept – swept','/swiːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swe/sweep/sweep__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2108,'ngsl-5-05',17,'obligation','nghĩa vụ, bổn phận','noun','[{"en":"Parents have an obligation to keep their children safe.","vi":"Cha mẹ có bổn phận giữ an toàn cho con cái."},{"en":"You are under no obligation to buy anything today.","vi":"Hôm nay bạn không bắt buộc phải mua gì cả."},{"en":"She felt an obligation to help her neighbors after the flood.","vi":"Cô ấy cảm thấy có nghĩa vụ giúp đỡ hàng xóm sau trận lũ."}]','[{"phrase":"legal obligation"},{"phrase":"moral obligation"},{"phrase":"under no obligation"},{"phrase":"sense of obligation"}]',NULL,'/ˌɑːblɪˈɡeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obl/oblig/obligation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2109,'ngsl-5-05',18,'sir','thưa ông, thưa ngài','noun','[{"en":"Excuse me, sir, you just dropped your wallet.","vi":"Xin lỗi ông, ông vừa làm rơi ví."},{"en":"Can I help you find something, sir?","vi":"Thưa ông, tôi có thể giúp ông tìm gì không ạ?"},{"en":"Yes, sir, your table will be ready in five minutes.","vi":"Vâng thưa ông, bàn của ông sẽ sẵn sàng trong năm phút nữa."}]','[{"phrase":"yes, sir"},{"phrase":"excuse me, sir"},{"phrase":"Dear Sir"}]','Cách gọi lịch sự với nam giới; với nữ giới dùng madam','/sɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sir/sir__/sir__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2110,'ngsl-5-05',19,'evaluate','đánh giá','verb','[{"en":"Teachers evaluate students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ."},{"en":"We need more time to evaluate the results of the survey.","vi":"Chúng ta cần thêm thời gian để đánh giá kết quả của cuộc khảo sát."},{"en":"How do you evaluate whether a website is reliable?","vi":"Bạn đánh giá thế nào để biết một trang web có đáng tin cậy không?"}]','[{"phrase":"evaluate the results"},{"phrase":"evaluate performance"},{"phrase":"carefully evaluate"}]',NULL,'/ɪˈvæljueɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eva/evalu/evaluate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2111,'ngsl-5-05',20,'anger','sự tức giận, cơn giận','noun','[{"en":"He couldn''t hide his anger when the flight was canceled again.","vi":"Anh ấy không giấu được cơn giận khi chuyến bay lại bị hủy."},{"en":"Try to count to ten before you react in anger.","vi":"Hãy thử đếm đến mười trước khi phản ứng trong cơn giận."},{"en":"There was a lot of anger about the new parking rules.","vi":"Quy định đỗ xe mới đã khiến nhiều người rất tức giận."}]','[{"phrase":"in anger"},{"phrase":"express anger"},{"phrase":"control your anger"}]',NULL,'/ˈæŋɡər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ang/anger/anger__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2112,'ngsl-5-05',21,'pub','quán rượu (kiểu Anh)','noun','[{"en":"Let''s meet at the pub after work on Friday.","vi":"Thứ Sáu tan làm mình gặp nhau ở quán rượu nhé."},{"en":"The village pub serves great food on Sundays.","vi":"Quán rượu trong làng phục vụ đồ ăn rất ngon vào Chủ nhật."},{"en":"We watched the big game at a local pub.","vi":"Chúng tôi xem trận đấu lớn ở một quán rượu gần nhà."}]','[{"phrase":"go to the pub"},{"phrase":"local pub"},{"phrase":"village pub"},{"phrase":"pub quiz"}]',NULL,'/pʌb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/pub__/pub__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2113,'ngsl-5-05',22,'perception','cách nhìn nhận, nhận thức; sự cảm nhận','noun','[{"en":"Social media can change our perception of what is normal.","vi":"Mạng xã hội có thể thay đổi cách chúng ta nhìn nhận điều gì là bình thường."},{"en":"There is a common perception that city life is more stressful.","vi":"Có một quan niệm phổ biến rằng cuộc sống ở thành phố căng thẳng hơn."},{"en":"Being very tired can affect your perception of time.","vi":"Quá mệt mỏi có thể ảnh hưởng đến cảm nhận của bạn về thời gian."}]','[{"phrase":"public perception"},{"phrase":"common perception"},{"phrase":"perception of"},{"phrase":"change perceptions"}]',NULL,'/pərˈsepʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/perception__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2114,'ngsl-5-05',23,'naturally','một cách tự nhiên; dĩ nhiên; bẩm sinh','adverb','[{"en":"Try to relax and speak naturally during the interview.","vi":"Hãy cố thư giãn và nói chuyện tự nhiên trong buổi phỏng vấn."},{"en":"Naturally, we were disappointed when the concert was canceled.","vi":"Dĩ nhiên là chúng tôi thất vọng khi buổi hòa nhạc bị hủy."},{"en":"Some people are naturally good at making new friends.","vi":"Có những người bẩm sinh đã giỏi kết bạn mới."}]','[{"phrase":"come naturally"},{"phrase":"naturally occurring"},{"phrase":"speak naturally"}]',NULL,'/ˈnætʃrəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nat/natur/naturally__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2115,'ngsl-5-05',24,'currency','tiền tệ','noun','[{"en":"You can exchange currency at the airport, but the rates are poor.","vi":"Bạn có thể đổi ngoại tệ ở sân bay, nhưng tỷ giá không tốt."},{"en":"The euro is the currency used in many European countries.","vi":"Đồng euro là đơn vị tiền tệ được dùng ở nhiều nước châu Âu."},{"en":"What is the local currency in Thailand?","vi":"Tiền tệ địa phương ở Thái Lan là gì?"}]','[{"phrase":"foreign currency"},{"phrase":"local currency"},{"phrase":"exchange currency"},{"phrase":"currency exchange"}]',NULL,'/ˈkɜːrənsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/currency__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2116,'ngsl-5-05',25,'database','cơ sở dữ liệu','noun','[{"en":"All customer details are stored in a secure database.","vi":"Mọi thông tin khách hàng đều được lưu trong một cơ sở dữ liệu an toàn."},{"en":"Search the library database to find articles for your essay.","vi":"Hãy tra cơ sở dữ liệu của thư viện để tìm bài viết cho bài luận của bạn."},{"en":"We need to update the database with the new phone numbers.","vi":"Chúng ta cần cập nhật số điện thoại mới vào cơ sở dữ liệu."}]','[{"phrase":"online database"},{"phrase":"update the database"},{"phrase":"search the database"}]',NULL,'/ˈdeɪtəbeɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dat/datab/database__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2117,'ngsl-5-05',26,'initially','ban đầu, lúc đầu','adverb','[{"en":"Initially, I found the job hard, but now I enjoy it.","vi":"Lúc đầu tôi thấy công việc khó, nhưng giờ tôi rất thích nó."},{"en":"The trip was initially planned for June but was moved to August.","vi":"Chuyến đi ban đầu dự định vào tháng Sáu nhưng đã được dời sang tháng Tám."},{"en":"She initially said no, but later changed her mind.","vi":"Ban đầu cô ấy từ chối, nhưng sau đó đã đổi ý."}]','[{"phrase":"initially planned"},{"phrase":"initially thought"},{"phrase":"initially reluctant"}]',NULL,'/ɪˈnɪʃəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initially__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2118,'ngsl-5-05',27,'territory','lãnh thổ; địa bàn; lĩnh vực','noun','[{"en":"Lions will fight to protect their territory from other lions.","vi":"Sư tử sẽ chiến đấu để bảo vệ lãnh thổ của chúng khỏi những con sư tử khác."},{"en":"Our sales team covers a large territory in the north.","vi":"Đội bán hàng của chúng tôi phụ trách một địa bàn rộng lớn ở phía bắc."},{"en":"Starting my own business was completely new territory for me.","vi":"Việc tự kinh doanh là một lĩnh vực hoàn toàn mới mẻ đối với tôi."}]','[{"phrase":"mark its territory"},{"phrase":"new territory"},{"phrase":"sales territory"},{"phrase":"enemy territory"}]',NULL,'/ˈterətɔːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/terri/territory__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2119,'ngsl-5-05',28,'stream','dòng suối; dòng (người, xe…) liên tục','noun','[{"en":"We had a picnic next to a small stream in the forest.","vi":"Chúng tôi đi dã ngoại bên một con suối nhỏ trong rừng."},{"en":"A steady stream of customers came into the shop all morning.","vi":"Khách hàng nối tiếp nhau vào cửa hàng suốt cả buổi sáng."},{"en":"The children crossed the stream by jumping from rock to rock.","vi":"Bọn trẻ vượt suối bằng cách nhảy từ tảng đá này sang tảng đá khác."}]','[{"phrase":"mountain stream"},{"phrase":"steady stream"},{"phrase":"constant stream"},{"phrase":"stream of traffic"}]',NULL,'/striːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strea/stream__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2120,'ngsl-5-05',29,'rarely','hiếm khi','adverb','[{"en":"My dad rarely watches TV in the evening.","vi":"Bố tôi hiếm khi xem TV vào buổi tối."},{"en":"It rarely snows in this part of the country.","vi":"Ở vùng này của đất nước hiếm khi có tuyết."},{"en":"We rarely see each other now that she lives abroad.","vi":"Giờ cô ấy sống ở nước ngoài nên chúng tôi hiếm khi gặp nhau."}]','[{"phrase":"very rarely"},{"phrase":"only rarely"},{"phrase":"rarely, if ever"}]',NULL,'/ˈrerli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rar/rarel/rarely__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2121,'ngsl-5-05',30,'height','chiều cao; độ cao; lúc cao điểm','noun','[{"en":"The nurse measured my height and weight during the checkup.","vi":"Y tá đo chiều cao và cân nặng của tôi trong buổi khám sức khỏe."},{"en":"The plane is now flying at a height of 10,000 meters.","vi":"Máy bay hiện đang bay ở độ cao 10.000 mét."},{"en":"The beach is always crowded at the height of summer.","vi":"Bãi biển lúc nào cũng đông đúc vào giữa mùa hè cao điểm."}]','[{"phrase":"average height"},{"phrase":"at a height of"},{"phrase":"at the height of"},{"phrase":"fear of heights"}]','Tính từ: high (cao)','/haɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hei/heigh/height__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2122,'ngsl-5-06',1,'apparent','rõ ràng; có vẻ như','adjective','[{"en":"It soon became apparent that nobody had read the instructions.","vi":"Chẳng bao lâu sau, rõ ràng là không ai đã đọc hướng dẫn."},{"en":"The problem was apparent as soon as we opened the box.","vi":"Vấn đề hiện rõ ngay khi chúng tôi mở hộp ra."},{"en":"Despite her apparent calm, she was very nervous before the exam.","vi":"Dù có vẻ bình tĩnh, cô ấy rất lo lắng trước kỳ thi."}]','[{"phrase":"become apparent"},{"phrase":"apparent reason"},{"phrase":"for no apparent reason"},{"phrase":"immediately apparent"}]',NULL,'/əˈpærənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appar/apparent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2123,'ngsl-5-06',2,'western','(thuộc) phương Tây; phía tây','adjective','[{"en":"Many young people in the city enjoy Western food and music.","vi":"Nhiều bạn trẻ trong thành phố thích đồ ăn và âm nhạc phương Tây."},{"en":"We spent a week traveling along the western coast.","vi":"Chúng tôi dành một tuần du lịch dọc bờ biển phía tây."},{"en":"Rain is expected in western parts of the country tomorrow.","vi":"Ngày mai dự báo có mưa ở các vùng phía tây của đất nước."}]','[{"phrase":"Western countries"},{"phrase":"Western culture"},{"phrase":"western coast"},{"phrase":"western part"}]','Viết hoa khi chỉ phương Tây (Western culture)','/ˈwestərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wes/weste/western__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2124,'ngsl-5-06',3,'expansion','sự mở rộng; sự phát triển','noun','[{"en":"The company is planning a major expansion into Asian markets.","vi":"Công ty đang lên kế hoạch mở rộng lớn sang các thị trường châu Á."},{"en":"The airport expansion will create hundreds of new jobs.","vi":"Việc mở rộng sân bay sẽ tạo ra hàng trăm việc làm mới."},{"en":"Rapid expansion of the city has made traffic much worse.","vi":"Sự phát triển nhanh của thành phố đã khiến giao thông tệ hơn nhiều."}]','[{"phrase":"rapid expansion"},{"phrase":"economic expansion"},{"phrase":"expansion plans"},{"phrase":"expansion into"}]',NULL,'/ɪkˈspænʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expan/expansion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2125,'ngsl-5-06',4,'constantly','liên tục; luôn luôn','adverb','[{"en":"My little brother is constantly asking for snacks.","vi":"Em trai tôi lúc nào cũng đòi ăn vặt."},{"en":"Prices have been constantly rising over the past few months.","vi":"Giá cả đã liên tục tăng trong vài tháng qua."},{"en":"She checks her phone constantly, even during dinner.","vi":"Cô ấy liên tục kiểm tra điện thoại, ngay cả trong bữa tối."}]','[{"phrase":"constantly changing"},{"phrase":"constantly complain"},{"phrase":"constantly worry"},{"phrase":"constantly check"}]',NULL,'/ˈkɑːnstəntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstantly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2126,'ngsl-5-06',5,'muscle','cơ; cơ bắp','noun','[{"en":"Swimming is a great way to build muscle without hurting your joints.","vi":"Bơi lội là cách tuyệt vời để tăng cơ mà không hại khớp."},{"en":"I pulled a muscle in my back while lifting a heavy box.","vi":"Tôi bị căng cơ lưng khi nâng một chiếc hộp nặng."},{"en":"My leg muscles were sore after the long hike.","vi":"Cơ chân tôi bị đau nhức sau chuyến đi bộ đường dài."}]','[{"phrase":"build muscle"},{"phrase":"pull a muscle"},{"phrase":"muscle pain"},{"phrase":"leg muscles"}]',NULL,'/ˈmʌsl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/muscl/muscle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2127,'ngsl-5-06',6,'scare','làm sợ; dọa','verb','[{"en":"You really scared me when you walked in so quietly.","vi":"Bạn đi vào nhẹ nhàng quá làm tôi giật cả mình."},{"en":"Loud thunder always scares our dog, so he hides under the bed.","vi":"Tiếng sấm to luôn làm con chó nhà tôi sợ, nên nó trốn dưới gầm giường."},{"en":"Don''t let one bad experience scare you away from traveling.","vi":"Đừng để một trải nghiệm tồi tệ khiến bạn sợ không dám đi du lịch nữa."}]','[{"phrase":"scare someone"},{"phrase":"scare away"},{"phrase":"scare off"},{"phrase":"easily scared"}]','be scared of = sợ cái gì','/sker/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sca/scare/scare__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2128,'ngsl-5-06',7,'badly','tệ; nặng; rất (cần)','adverb','[{"en":"I did badly on the math test because I didn''t study.","vi":"Tôi làm bài kiểm tra toán rất tệ vì đã không học bài."},{"en":"Many trees were badly damaged in the storm last night.","vi":"Nhiều cây cối bị hư hại nặng trong cơn bão tối qua."},{"en":"This old house badly needs a new roof.","vi":"Căn nhà cũ này rất cần một mái nhà mới."}]','[{"phrase":"badly injured"},{"phrase":"badly damaged"},{"phrase":"badly need"},{"phrase":"go badly"}]','badly – worse – worst','/ˈbædli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bad/badly/badly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2129,'ngsl-5-06',8,'everyday','hằng ngày; thường ngày','adjective','[{"en":"Smartphones have become an important part of everyday life.","vi":"Điện thoại thông minh đã trở thành một phần quan trọng của cuộc sống hằng ngày."},{"en":"These simple tips can help you save money on everyday items.","vi":"Những mẹo đơn giản này giúp bạn tiết kiệm tiền cho các món đồ dùng hằng ngày."},{"en":"He wore his everyday clothes to the party.","vi":"Anh ấy mặc quần áo thường ngày đến bữa tiệc."}]','[{"phrase":"everyday life"},{"phrase":"everyday use"},{"phrase":"everyday items"},{"phrase":"everyday language"}]','everyday (tính từ) ≠ every day (mỗi ngày)','/ˈevrideɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everyday__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2130,'ngsl-5-06',9,'boundary','ranh giới; giới hạn','noun','[{"en":"The river forms the boundary between the two towns.","vi":"Con sông tạo thành ranh giới giữa hai thị trấn."},{"en":"It''s important to set clear boundaries with your coworkers.","vi":"Việc đặt ra giới hạn rõ ràng với đồng nghiệp là rất quan trọng."},{"en":"A small fence marks the boundary of our garden.","vi":"Một hàng rào nhỏ đánh dấu ranh giới khu vườn nhà chúng tôi."}]','[{"phrase":"set boundaries"},{"phrase":"boundary between"},{"phrase":"mark the boundary"},{"phrase":"cross the boundary"}]',NULL,'/ˈbaʊndri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bou/bound/boundary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2131,'ngsl-5-06',10,'ratio','tỉ lệ; tỉ số','noun','[{"en":"The ratio of students to teachers in this school is twenty to one.","vi":"Tỉ lệ học sinh trên giáo viên ở trường này là hai mươi trên một."},{"en":"Mix the rice and water in a ratio of one to two.","vi":"Trộn gạo và nước theo tỉ lệ một phần gạo, hai phần nước."},{"en":"Our class has a high ratio of girls to boys.","vi":"Lớp chúng tôi có tỉ lệ nữ so với nam cao."}]','[{"phrase":"ratio of"},{"phrase":"high ratio"},{"phrase":"in a ratio of"},{"phrase":"student-teacher ratio"}]',NULL,'/ˈreɪʃiəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/ratio/ratio__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2132,'ngsl-5-06',11,'essay','bài luận; bài tiểu luận','noun','[{"en":"I have to write a two-page essay about my hometown.","vi":"Tôi phải viết một bài luận dài hai trang về quê hương mình."},{"en":"Did you hand in your history essay on time?","vi":"Bạn đã nộp bài luận môn lịch sử đúng hạn chưa?"},{"en":"Her essay won first prize in the school competition.","vi":"Bài luận của cô ấy đã đoạt giải nhất trong cuộc thi của trường."}]','[{"phrase":"write an essay"},{"phrase":"hand in an essay"},{"phrase":"essay about"},{"phrase":"short essay"}]',NULL,'/ˈeseɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ess/essay/essay__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2133,'ngsl-5-06',12,'scream','hét lên; la hét','verb','[{"en":"The kids screamed with excitement on the roller coaster.","vi":"Bọn trẻ hét lên vì phấn khích trên tàu lượn siêu tốc."},{"en":"She screamed when she saw a snake in the kitchen.","vi":"Cô ấy hét lên khi nhìn thấy một con rắn trong bếp."},{"en":"Please stop screaming at each other and talk calmly.","vi":"Làm ơn đừng hét vào mặt nhau nữa và hãy nói chuyện bình tĩnh."}]','[{"phrase":"scream at"},{"phrase":"scream for help"},{"phrase":"scream with excitement"},{"phrase":"scream in pain"}]',NULL,'/skriːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/scr/screa/scream__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2134,'ngsl-5-06',13,'withdraw','rút (tiền); rút lui; rút khỏi','verb','[{"en":"I need to withdraw some cash before we go to the market.","vi":"Tôi cần rút ít tiền mặt trước khi chúng ta đi chợ."},{"en":"He withdrew from the race because of a knee injury.","vi":"Anh ấy rút khỏi cuộc đua vì chấn thương đầu gối."},{"en":"The company decided to withdraw its offer after the meeting.","vi":"Công ty quyết định rút lại lời đề nghị sau cuộc họp."}]','[{"phrase":"withdraw money"},{"phrase":"withdraw cash"},{"phrase":"withdraw from"},{"phrase":"withdraw an offer"}]','withdraw – withdrew – withdrawn','/wɪðˈdrɔː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wit/withd/withdraw__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2135,'ngsl-5-06',14,'pollution','sự ô nhiễm','noun','[{"en":"Air pollution in big cities is getting worse every year.","vi":"Ô nhiễm không khí ở các thành phố lớn ngày càng tệ hơn mỗi năm."},{"en":"We can reduce pollution by taking the bus instead of driving.","vi":"Chúng ta có thể giảm ô nhiễm bằng cách đi xe buýt thay vì lái xe."},{"en":"Plastic pollution is a serious problem for sea animals.","vi":"Ô nhiễm nhựa là một vấn đề nghiêm trọng đối với động vật biển."}]','[{"phrase":"air pollution"},{"phrase":"water pollution"},{"phrase":"reduce pollution"},{"phrase":"noise pollution"}]','Không đếm được','/pəˈluːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/pollu/pollution__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2136,'ngsl-5-06',15,'disorder','chứng rối loạn; sự lộn xộn','noun','[{"en":"She was diagnosed with a sleep disorder last year.","vi":"Năm ngoái cô ấy được chẩn đoán mắc chứng rối loạn giấc ngủ."},{"en":"The doctor said my skin disorder was not serious.","vi":"Bác sĩ nói chứng rối loạn da của tôi không nghiêm trọng."},{"en":"After the party, the whole house was in complete disorder.","vi":"Sau bữa tiệc, cả căn nhà hoàn toàn lộn xộn."}]','[{"phrase":"sleep disorder"},{"phrase":"skin disorder"},{"phrase":"mental disorder"},{"phrase":"in disorder"}]',NULL,'/dɪsˈɔːrdər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disor/disorder__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2137,'ngsl-5-06',16,'furniture','đồ nội thất; đồ đạc','noun','[{"en":"We bought some new furniture for the living room.","vi":"Chúng tôi đã mua ít đồ nội thất mới cho phòng khách."},{"en":"Can you help me move this heavy furniture upstairs?","vi":"Bạn có thể giúp tôi chuyển đống đồ đạc nặng này lên lầu không?"},{"en":"The only piece of furniture in the room was an old bed.","vi":"Món đồ nội thất duy nhất trong phòng là một chiếc giường cũ."}]','[{"phrase":"piece of furniture"},{"phrase":"move furniture"},{"phrase":"office furniture"},{"phrase":"new furniture"}]','Không đếm được: a piece of furniture','/ˈfɜːrnɪtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furni/furniture__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2138,'ngsl-5-06',17,'symbol','biểu tượng; ký hiệu','noun','[{"en":"The dove is often used as a symbol of peace.","vi":"Chim bồ câu thường được dùng làm biểu tượng của hòa bình."},{"en":"What does this small symbol on the washing machine mean?","vi":"Ký hiệu nhỏ này trên máy giặt có nghĩa là gì?"},{"en":"For many families, a big house is a symbol of success.","vi":"Với nhiều gia đình, một ngôi nhà lớn là biểu tượng của thành công."}]','[{"phrase":"symbol of"},{"phrase":"national symbol"},{"phrase":"status symbol"},{"phrase":"chemical symbol"}]',NULL,'/ˈsɪmbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sym/symbo/symbol__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2139,'ngsl-5-06',18,'apartment','căn hộ','noun','[{"en":"They rent a small apartment near the city center.","vi":"Họ thuê một căn hộ nhỏ gần trung tâm thành phố."},{"en":"Our apartment is on the fifth floor, and there''s no elevator.","vi":"Căn hộ của chúng tôi ở tầng năm, và không có thang máy."},{"en":"I''m looking for a two-bedroom apartment with a balcony.","vi":"Tôi đang tìm một căn hộ hai phòng ngủ có ban công."}]','[{"phrase":"rent an apartment"},{"phrase":"apartment building"},{"phrase":"two-bedroom apartment"},{"phrase":"small apartment"}]','Anh: flat · Mỹ: apartment','/əˈpɑːrtmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/apa/apart/apartment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2140,'ngsl-5-06',19,'demonstration','cuộc biểu tình; sự trình diễn, minh họa','noun','[{"en":"Thousands of people joined the demonstration in the main square.","vi":"Hàng nghìn người đã tham gia cuộc biểu tình ở quảng trường chính."},{"en":"The salesperson gave us a quick demonstration of the new vacuum cleaner.","vi":"Nhân viên bán hàng đã trình diễn nhanh cho chúng tôi cách dùng chiếc máy hút bụi mới."},{"en":"After a short demonstration, the students tried the experiment themselves.","vi":"Sau một phần minh họa ngắn, học sinh tự làm thí nghiệm."}]','[{"phrase":"give a demonstration"},{"phrase":"hold a demonstration"},{"phrase":"peaceful demonstration"},{"phrase":"demonstration of"}]',NULL,'/ˌdemənˈstreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/demon/demonstration__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2141,'ngsl-5-06',20,'analyst','nhà phân tích; chuyên viên phân tích','noun','[{"en":"My sister works as a financial analyst at a large bank.","vi":"Chị tôi làm chuyên viên phân tích tài chính ở một ngân hàng lớn."},{"en":"Analysts expect house prices to fall slightly next year.","vi":"Các nhà phân tích dự đoán giá nhà sẽ giảm nhẹ vào năm tới."},{"en":"The company hired a data analyst to study customer behavior.","vi":"Công ty đã thuê một chuyên viên phân tích dữ liệu để nghiên cứu hành vi khách hàng."}]','[{"phrase":"financial analyst"},{"phrase":"data analyst"},{"phrase":"market analyst"},{"phrase":"analysts expect"}]',NULL,'/ˈænəlɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analy/analyst__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2142,'ngsl-5-06',21,'platform','sân ga; nền tảng; bục','noun','[{"en":"The train to the airport leaves from platform three.","vi":"Tàu đi sân bay khởi hành từ sân ga số ba."},{"en":"Many small businesses sell their products on online platforms.","vi":"Nhiều doanh nghiệp nhỏ bán sản phẩm trên các nền tảng trực tuyến."},{"en":"The speaker walked onto the platform and thanked the audience.","vi":"Diễn giả bước lên bục và cảm ơn khán giả."}]','[{"phrase":"train platform"},{"phrase":"online platform"},{"phrase":"social media platform"},{"phrase":"on the platform"}]',NULL,'/ˈplætfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/platf/platform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2143,'ngsl-5-06',22,'steel','thép','noun','[{"en":"The bridge is made of steel and concrete.","vi":"Cây cầu được làm bằng thép và bê tông."},{"en":"I prefer stainless steel pans because they last longer.","vi":"Tôi thích chảo bằng thép không gỉ hơn vì chúng bền hơn."},{"en":"My grandfather worked in a steel factory for thirty years.","vi":"Ông tôi đã làm việc ở một nhà máy thép suốt ba mươi năm."}]','[{"phrase":"stainless steel"},{"phrase":"made of steel"},{"phrase":"steel industry"},{"phrase":"steel frame"}]','Không đếm được','/stiːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/steel/steel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2144,'ngsl-5-06',23,'cake','bánh ngọt; bánh kem','noun','[{"en":"Mom baked a chocolate cake for my birthday.","vi":"Mẹ đã nướng một chiếc bánh sô-cô-la cho sinh nhật tôi."},{"en":"Would you like another piece of cake with your tea?","vi":"Bạn có muốn thêm một miếng bánh ngọt để ăn cùng trà không?"},{"en":"We ordered a big wedding cake from a local bakery.","vi":"Chúng tôi đã đặt một chiếc bánh cưới lớn ở một tiệm bánh gần nhà."}]','[{"phrase":"bake a cake"},{"phrase":"birthday cake"},{"phrase":"piece of cake"},{"phrase":"chocolate cake"}]','a piece of cake (thành ngữ) = dễ ợt','/keɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cak/cake_/cake__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2145,'ngsl-5-06',24,'transform','biến đổi; thay đổi hoàn toàn','verb','[{"en":"The internet has transformed the way we work and study.","vi":"Internet đã thay đổi hoàn toàn cách chúng ta làm việc và học tập."},{"en":"They transformed an old warehouse into a modern café.","vi":"Họ đã biến một nhà kho cũ thành một quán cà phê hiện đại."},{"en":"A little paint can completely transform a small room.","vi":"Một chút sơn có thể làm căn phòng nhỏ thay đổi hoàn toàn."}]','[{"phrase":"transform into"},{"phrase":"completely transform"},{"phrase":"transform the way"},{"phrase":"transform lives"}]','transform A into B = biến A thành B','/trænsˈfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2146,'ngsl-5-06',25,'wound','vết thương','noun','[{"en":"The nurse cleaned the wound and put on a bandage.","vi":"Y tá đã rửa vết thương và băng lại."},{"en":"It took several weeks for the wound on his leg to heal.","vi":"Phải mất vài tuần vết thương ở chân anh ấy mới lành."},{"en":"Keep the wound dry and change the bandage every day.","vi":"Hãy giữ vết thương khô ráo và thay băng mỗi ngày."}]','[{"phrase":"clean a wound"},{"phrase":"the wound heals"},{"phrase":"deep wound"},{"phrase":"keep the wound dry"}]','wound /wuːnd/ (vết thương) ≠ wound /waʊnd/ (quá khứ của wind)','/ˈwaʊnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2147,'ngsl-5-06',26,'restriction','sự hạn chế; quy định hạn chế','noun','[{"en":"There are strict restrictions on what you can take on a plane.","vi":"Có những quy định hạn chế nghiêm ngặt về đồ được mang lên máy bay."},{"en":"The city introduced new parking restrictions in the downtown area.","vi":"Thành phố đã đưa ra các quy định hạn chế đỗ xe mới ở khu trung tâm."},{"en":"Most travel restrictions were lifted at the end of the year.","vi":"Hầu hết các hạn chế đi lại đã được dỡ bỏ vào cuối năm."}]','[{"phrase":"strict restrictions"},{"phrase":"restrictions on"},{"phrase":"lift restrictions"},{"phrase":"travel restrictions"}]','restriction on sth','/rɪˈstrɪkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restriction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2148,'ngsl-5-06',27,'foundation','nền tảng; móng (nhà); quỹ','noun','[{"en":"Good habits in childhood lay the foundation for a healthy life.","vi":"Thói quen tốt từ nhỏ đặt nền tảng cho một cuộc sống khỏe mạnh."},{"en":"Workers are pouring the foundation for the new school building.","vi":"Công nhân đang đổ móng cho tòa nhà trường học mới."},{"en":"The foundation gives scholarships to students from poor families.","vi":"Quỹ này trao học bổng cho sinh viên từ các gia đình nghèo."}]','[{"phrase":"lay the foundation"},{"phrase":"strong foundation"},{"phrase":"foundation for"},{"phrase":"charitable foundation"}]',NULL,'/faʊnˈdeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/foundation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2149,'ngsl-5-06',28,'designer','nhà thiết kế','noun','[{"en":"She dreams of becoming a famous fashion designer.","vi":"Cô ấy mơ trở thành một nhà thiết kế thời trang nổi tiếng."},{"en":"We hired a designer to create a new logo for our shop.","vi":"Chúng tôi đã thuê một nhà thiết kế để làm logo mới cho cửa hàng."},{"en":"The game designers spent two years working on this project.","vi":"Các nhà thiết kế trò chơi đã dành hai năm cho dự án này."}]','[{"phrase":"fashion designer"},{"phrase":"graphic designer"},{"phrase":"interior designer"},{"phrase":"game designer"}]',NULL,'/dɪˈzaɪnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desig/designer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2150,'ngsl-5-06',29,'strain','sự căng thẳng; áp lực','noun','[{"en":"Working two jobs put a lot of strain on his health.","vi":"Làm hai công việc đã gây nhiều áp lực lên sức khỏe của anh ấy."},{"en":"Looking at a screen all day can cause eye strain.","vi":"Nhìn màn hình cả ngày có thể gây mỏi mắt."},{"en":"Money problems can put a strain on any marriage.","vi":"Chuyện tiền bạc có thể gây căng thẳng cho bất kỳ cuộc hôn nhân nào."}]','[{"phrase":"put a strain on"},{"phrase":"under strain"},{"phrase":"eye strain"},{"phrase":"financial strain"}]',NULL,'/streɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strai/strain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2151,'ngsl-5-06',30,'innovation','sự đổi mới; sáng kiến','noun','[{"en":"The company encourages innovation by letting staff test their own ideas.","vi":"Công ty khuyến khích sự đổi mới bằng cách cho nhân viên thử nghiệm ý tưởng của riêng họ."},{"en":"Online banking was a major innovation for many customers.","vi":"Ngân hàng trực tuyến là một sáng kiến lớn đối với nhiều khách hàng."},{"en":"Our city needs more innovation in public transportation.","vi":"Thành phố chúng ta cần đổi mới nhiều hơn trong giao thông công cộng."}]','[{"phrase":"technological innovation"},{"phrase":"encourage innovation"},{"phrase":"innovation in"},{"phrase":"major innovation"}]',NULL,'/ˌɪnəˈveɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/innov/innovation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2152,'ngsl-5-07',1,'album','album nhạc; cuốn album ảnh','noun','[{"en":"The band is releasing a new album next month.","vi":"Ban nhạc sẽ phát hành album mới vào tháng sau."},{"en":"I listened to her first album all the way home.","vi":"Tôi đã nghe album đầu tiên của cô ấy suốt đường về nhà."},{"en":"My grandmother keeps old family photos in a big album.","vi":"Bà tôi cất những tấm ảnh gia đình cũ trong một cuốn album lớn."}]','[{"phrase":"new album"},{"phrase":"release an album"},{"phrase":"photo album"},{"phrase":"debut album"}]',NULL,'/ˈælbəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alb/album/album__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2153,'ngsl-5-07',2,'singer','ca sĩ; người hát','noun','[{"en":"She dreamed of becoming a famous singer when she was young.","vi":"Hồi nhỏ cô ấy mơ trở thành một ca sĩ nổi tiếng."},{"en":"The lead singer thanked the crowd after the last song.","vi":"Ca sĩ hát chính cảm ơn khán giả sau bài hát cuối cùng."},{"en":"My brother isn''t a great singer, but he loves karaoke.","vi":"Anh tôi hát không hay lắm, nhưng anh ấy rất thích karaoke."}]','[{"phrase":"lead singer"},{"phrase":"famous singer"},{"phrase":"pop singer"},{"phrase":"opera singer"}]',NULL,'/ˈsɪŋər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/singe/singer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2154,'ngsl-5-07',3,'trail','đường mòn; dấu vết','noun','[{"en":"We followed a narrow trail up the side of the mountain.","vi":"Chúng tôi đi theo một con đường mòn hẹp lên sườn núi."},{"en":"This hiking trail is closed during the rainy season.","vi":"Đường mòn đi bộ này bị đóng vào mùa mưa."},{"en":"The dog left a trail of muddy footprints across the kitchen.","vi":"Con chó để lại một vệt dấu chân lấm bùn khắp nhà bếp."}]','[{"phrase":"hiking trail"},{"phrase":"follow a trail"},{"phrase":"mountain trail"},{"phrase":"a trail of"}]',NULL,'/treɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trail/trail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2155,'ngsl-5-07',4,'trap','cái bẫy; cạm bẫy','noun','[{"en":"We set a trap to catch the mouse in the kitchen.","vi":"Chúng tôi đặt một cái bẫy để bắt con chuột trong bếp."},{"en":"Don''t fall into the trap of spending more than you earn.","vi":"Đừng rơi vào cái bẫy tiêu nhiều hơn số tiền mình kiếm được."},{"en":"She realized too late that the cheap offer was a trap.","vi":"Cô ấy nhận ra quá muộn rằng lời mời chào giá rẻ đó là một cái bẫy."}]','[{"phrase":"set a trap"},{"phrase":"fall into the trap"},{"phrase":"caught in a trap"},{"phrase":"tourist trap"}]',NULL,'/træp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trap_/trap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2156,'ngsl-5-07',5,'loose','lỏng; lung lay; rộng (quần áo)','adjective','[{"en":"One of the screws on this chair is loose.","vi":"Một con ốc trên chiếc ghế này bị lỏng."},{"en":"She prefers to wear loose clothes when the weather is hot.","vi":"Cô ấy thích mặc quần áo rộng khi trời nóng."},{"en":"My little son has a loose tooth and keeps touching it.","vi":"Con trai nhỏ của tôi có một cái răng lung lay và cứ sờ vào nó."}]','[{"phrase":"loose clothes"},{"phrase":"come loose"},{"phrase":"loose tooth"},{"phrase":"break loose"}]','loose (lỏng) ≠ lose (mất)','/luːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loo/loose/loose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2157,'ngsl-5-07',6,'extension','sự gia hạn; phần mở rộng; số máy lẻ','noun','[{"en":"I asked my teacher for an extension on the essay.","vi":"Tôi xin cô giáo gia hạn nộp bài luận."},{"en":"They are building an extension at the back of their house.","vi":"Họ đang xây phần nhà mở rộng ở phía sau nhà mình."},{"en":"You can reach me at extension 214 during office hours.","vi":"Bạn có thể gọi cho tôi qua số máy lẻ 214 trong giờ hành chính."}]','[{"phrase":"ask for an extension"},{"phrase":"get an extension"},{"phrase":"extension cord"},{"phrase":"build an extension"}]',NULL,'/ɪkˈstenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extension__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2158,'ngsl-5-07',7,'wealth','sự giàu có; của cải; sự phong phú','noun','[{"en":"Money and wealth do not always bring happiness.","vi":"Tiền bạc và sự giàu có không phải lúc nào cũng mang lại hạnh phúc."},{"en":"Most of his wealth came from the family business.","vi":"Phần lớn của cải của ông ấy đến từ công việc kinh doanh của gia đình."},{"en":"Our new manager brings a wealth of experience to the team.","vi":"Người quản lý mới mang đến cho nhóm rất nhiều kinh nghiệm."}]','[{"phrase":"a wealth of"},{"phrase":"great wealth"},{"phrase":"create wealth"},{"phrase":"wealth and power"}]','không đếm được','/welθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/wealt/wealth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2159,'ngsl-5-07',8,'gradually','dần dần; từ từ','adverb','[{"en":"The weather gradually got warmer as spring arrived.","vi":"Thời tiết ấm dần lên khi mùa xuân đến."},{"en":"Her English improved gradually after she moved to London.","vi":"Tiếng Anh của cô ấy dần dần tiến bộ sau khi chuyển đến London."},{"en":"Add the sugar gradually and keep stirring the mixture.","vi":"Cho đường vào từ từ và tiếp tục khuấy hỗn hợp."}]','[{"phrase":"gradually increase"},{"phrase":"gradually improve"},{"phrase":"gradually become"}]',NULL,'/ˈɡrædʒuəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gradu/gradually__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2160,'ngsl-5-07',9,'tank','bể chứa; bình (xăng, nước); xe tăng','noun','[{"en":"We need to fill the tank before the long drive.","vi":"Chúng ta cần đổ đầy bình xăng trước chuyến đi dài."},{"en":"My kids feed the fish in the tank every morning.","vi":"Các con tôi cho cá trong bể ăn mỗi sáng."},{"en":"An old army tank stands outside the war museum.","vi":"Một chiếc xe tăng quân đội cũ đặt bên ngoài bảo tàng chiến tranh."}]','[{"phrase":"fuel tank"},{"phrase":"fish tank"},{"phrase":"water tank"},{"phrase":"fill the tank"}]',NULL,'/tæŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tan/tank_/tank__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2161,'ngsl-5-07',10,'evil','độc ác; xấu xa','adjective','[{"en":"In the movie, an evil queen tries to kill the princess.","vi":"Trong phim, một mụ hoàng hậu độc ác tìm cách giết công chúa."},{"en":"The story is about a brave boy who fights an evil wizard.","vi":"Câu chuyện kể về một cậu bé dũng cảm chiến đấu với một phù thủy độc ác."},{"en":"He isn''t evil; he just made some bad choices.","vi":"Anh ta không xấu xa; anh ta chỉ đưa ra vài lựa chọn sai lầm."}]','[{"phrase":"evil spirit"},{"phrase":"evil queen"},{"phrase":"good and evil"},{"phrase":"pure evil"}]',NULL,'/ˈiːvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evi/evil_/evil__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2162,'ngsl-5-07',11,'remarkable','đáng chú ý; đáng kinh ngạc; phi thường','adjective','[{"en":"She made a remarkable recovery after the accident.","vi":"Cô ấy đã hồi phục đáng kinh ngạc sau vụ tai nạn."},{"en":"It''s remarkable how quickly children learn new languages.","vi":"Thật đáng kinh ngạc khi trẻ em học ngôn ngữ mới nhanh đến vậy."},{"en":"Our team has achieved remarkable results this year.","vi":"Năm nay nhóm chúng tôi đã đạt được những kết quả phi thường."}]','[{"phrase":"remarkable achievement"},{"phrase":"remarkable recovery"},{"phrase":"truly remarkable"},{"phrase":"remarkable results"}]',NULL,'/rɪˈmɑːrkəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remar/remarkable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2163,'ngsl-5-07',12,'tune','giai điệu; điệu nhạc','noun','[{"en":"He was whistling a happy tune while he cooked dinner.","vi":"Anh ấy vừa nấu bữa tối vừa huýt sáo một giai điệu vui tươi."},{"en":"I can remember the tune, but I''ve forgotten the words.","vi":"Tôi nhớ được giai điệu nhưng đã quên lời bài hát."},{"en":"That catchy tune has been stuck in my head all day.","vi":"Giai điệu dễ nhớ đó cứ lởn vởn trong đầu tôi cả ngày."}]','[{"phrase":"catchy tune"},{"phrase":"out of tune"},{"phrase":"hum a tune"},{"phrase":"play a tune"}]',NULL,'/tuːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tun/tune_/tune__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2164,'ngsl-5-07',13,'grass','cỏ; bãi cỏ','noun','[{"en":"The children were sitting on the grass eating sandwiches.","vi":"Bọn trẻ đang ngồi trên bãi cỏ ăn bánh mì kẹp."},{"en":"My father cuts the grass in our garden every Sunday.","vi":"Bố tôi cắt cỏ trong vườn nhà vào mỗi Chủ nhật."},{"en":"Please keep off the grass while it is still wet.","vi":"Vui lòng không giẫm lên cỏ khi cỏ vẫn còn ướt."}]','[{"phrase":"cut the grass"},{"phrase":"green grass"},{"phrase":"long grass"},{"phrase":"on the grass"}]',NULL,'/ɡræs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grass/grass__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2165,'ngsl-5-07',14,'invitation','lời mời; thiệp mời','noun','[{"en":"Thank you for the invitation to your birthday party.","vi":"Cảm ơn bạn đã mời tôi đến dự tiệc sinh nhật của bạn."},{"en":"We received a wedding invitation from our old neighbors.","vi":"Chúng tôi nhận được thiệp mời đám cưới từ những người hàng xóm cũ."},{"en":"She politely turned down his invitation to dinner.","vi":"Cô ấy lịch sự từ chối lời mời đi ăn tối của anh ấy."}]','[{"phrase":"accept an invitation"},{"phrase":"wedding invitation"},{"phrase":"send an invitation"},{"phrase":"turn down an invitation"}]','invitation to sth','/ˌɪnvɪˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invit/invitation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2166,'ngsl-5-07',15,'transition','sự chuyển tiếp; sự chuyển đổi','noun','[{"en":"The transition from school to work can be difficult.","vi":"Việc chuyển từ trường học sang đi làm có thể rất khó khăn."},{"en":"Our company is going through a period of transition.","vi":"Công ty chúng tôi đang trải qua một giai đoạn chuyển đổi."},{"en":"She made a smooth transition to her new role as manager.","vi":"Cô ấy đã chuyển sang vai trò quản lý mới một cách suôn sẻ."}]','[{"phrase":"smooth transition"},{"phrase":"transition to"},{"phrase":"period of transition"},{"phrase":"make the transition"}]',NULL,'/trænˈzɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2167,'ngsl-5-07',16,'frighten','làm hoảng sợ; dọa','verb','[{"en":"The loud thunder frightened the baby, and she started crying.","vi":"Tiếng sấm to làm em bé hoảng sợ và bé bắt đầu khóc."},{"en":"Don''t shout, or you''ll frighten the birds away.","vi":"Đừng hét lên, không thì bạn sẽ làm lũ chim sợ bay mất."},{"en":"Horror movies don''t frighten me, but spiders do.","vi":"Phim kinh dị không làm tôi sợ, nhưng nhện thì có."}]','[{"phrase":"frighten away"},{"phrase":"frighten somebody to death"},{"phrase":"easily frightened"}]',NULL,'/ˈfraɪtn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frigh/frighten__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2168,'ngsl-5-07',17,'bid','sự trả giá; sự dự thầu; nỗ lực (để đạt được)','noun','[{"en":"He made a bid of two hundred dollars for the old clock.","vi":"Anh ấy trả giá hai trăm đô la cho chiếc đồng hồ cũ."},{"en":"Three companies put in a bid to build the new bridge.","vi":"Ba công ty đã nộp hồ sơ dự thầu xây cây cầu mới."},{"en":"The city failed in its bid to host the Olympic Games.","vi":"Thành phố đã thất bại trong nỗ lực đăng cai Thế vận hội."}]','[{"phrase":"make a bid"},{"phrase":"winning bid"},{"phrase":"bid for"},{"phrase":"in a bid to"}]',NULL,'/ˈbɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2169,'ngsl-5-07',18,'breed','giống (vật nuôi); nhân giống, gây giống','noun','[{"en":"What breed of dog is good for a small apartment?","vi":"Giống chó nào phù hợp với một căn hộ nhỏ?"},{"en":"This rare breed of cattle comes from the north.","vi":"Giống bò hiếm này có nguồn gốc từ miền Bắc."},{"en":"My uncle breeds horses on his farm in the countryside.","vi":"Chú tôi nuôi và nhân giống ngựa ở trang trại dưới quê."}]','[{"phrase":"breed of dog"},{"phrase":"rare breed"},{"phrase":"breed horses"},{"phrase":"different breeds"}]','breed – bred – bred','/briːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/breed/breed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2170,'ngsl-5-07',19,'extraordinary','phi thường; khác thường','adjective','[{"en":"She has an extraordinary talent for music.","vi":"Cô ấy có năng khiếu âm nhạc phi thường."},{"en":"It was an extraordinary experience to see whales so close.","vi":"Được nhìn cá voi ở gần như vậy là một trải nghiệm phi thường."},{"en":"He wore an extraordinary hat covered in plastic flowers.","vi":"Anh ấy đội một chiếc mũ khác thường phủ đầy hoa nhựa."}]','[{"phrase":"extraordinary talent"},{"phrase":"extraordinary experience"},{"phrase":"quite extraordinary"},{"phrase":"extraordinary story"}]',NULL,'/ɪkˈstrɔːrdəneri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extraordinary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2171,'ngsl-5-07',20,'brilliant','xuất sắc; tuyệt vời; rực rỡ','adjective','[{"en":"What a brilliant idea for your sister''s birthday present!","vi":"Thật là một ý tưởng tuyệt vời cho món quà sinh nhật của chị bạn!"},{"en":"Our new math teacher is a brilliant young scientist.","vi":"Thầy dạy toán mới của chúng tôi là một nhà khoa học trẻ xuất sắc."},{"en":"We woke up to brilliant sunshine on the first day of our trip.","vi":"Chúng tôi thức dậy trong ánh nắng rực rỡ vào ngày đầu của chuyến đi."}]','[{"phrase":"brilliant idea"},{"phrase":"brilliant career"},{"phrase":"brilliant sunshine"},{"phrase":"absolutely brilliant"}]',NULL,'/ˈbrɪliənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brill/brilliant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2172,'ngsl-5-07',21,'adviser','cố vấn; người tư vấn','noun','[{"en":"I talked to a financial adviser before buying the house.","vi":"Tôi đã nói chuyện với một chuyên viên tư vấn tài chính trước khi mua nhà."},{"en":"My academic adviser helped me choose the right courses.","vi":"Cố vấn học tập đã giúp tôi chọn đúng các môn học."},{"en":"She works as a senior adviser to the company''s director.","vi":"Cô ấy làm cố vấn cấp cao cho giám đốc công ty."}]','[{"phrase":"financial adviser"},{"phrase":"legal adviser"},{"phrase":"senior adviser"},{"phrase":"adviser to"}]','cũng viết: advisor','/ədˈvaɪzər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advis/adviser__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2173,'ngsl-5-07',22,'stem','thân cây; cuống (hoa, lá)','noun','[{"en":"Cut the flower stems before you put them in water.","vi":"Cắt bớt cuống hoa trước khi cắm vào nước."},{"en":"This plant has a thin green stem and small leaves.","vi":"Cây này có thân mảnh màu xanh và lá nhỏ."},{"en":"Hold the wine glass by its stem, not the bowl.","vi":"Hãy cầm ly rượu ở phần chân ly, đừng cầm vào bầu ly."}]','[{"phrase":"flower stem"},{"phrase":"long stem"},{"phrase":"thin stem"}]','stem from: bắt nguồn từ','/stem/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ste/stem_/stem__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2174,'ngsl-5-07',23,'reverse','đảo ngược; hủy bỏ (quyết định)','verb','[{"en":"The manager agreed to reverse his decision after the meeting.","vi":"Sau cuộc họp, quản lý đã đồng ý hủy bỏ quyết định của mình."},{"en":"It may be too late to reverse the damage to the forest.","vi":"Có lẽ đã quá muộn để đảo ngược thiệt hại cho khu rừng."},{"en":"Try reversing the order of the last two sentences.","vi":"Hãy thử đảo ngược thứ tự của hai câu cuối."}]','[{"phrase":"reverse a decision"},{"phrase":"reverse the trend"},{"phrase":"reverse the damage"},{"phrase":"reverse the order"}]','in reverse: theo chiều ngược lại','/rɪˈvɜːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/rever/reverse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2175,'ngsl-5-07',24,'mode','chế độ; phương thức; cách thức','noun','[{"en":"Please switch your phones to silent mode during the exam.","vi":"Vui lòng chuyển điện thoại sang chế độ im lặng trong giờ thi."},{"en":"For many students, the bicycle is the main mode of transport.","vi":"Với nhiều sinh viên, xe đạp là phương tiện đi lại chính."},{"en":"The camera has a special mode for taking photos at night.","vi":"Chiếc máy ảnh có một chế độ đặc biệt để chụp ảnh ban đêm."}]','[{"phrase":"silent mode"},{"phrase":"mode of transport"},{"phrase":"night mode"},{"phrase":"sleep mode"}]',NULL,'/məʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/mode_/mode__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2176,'ngsl-5-07',25,'mirror','gương; gương chiếu hậu','noun','[{"en":"She checked her hair in the mirror before leaving.","vi":"Cô ấy soi gương xem lại tóc trước khi ra ngoài."},{"en":"There''s a large mirror on the wall of the bathroom.","vi":"Có một chiếc gương lớn trên tường phòng tắm."},{"en":"Always look in your mirror before you change lanes.","vi":"Luôn nhìn gương chiếu hậu trước khi chuyển làn."}]','[{"phrase":"look in the mirror"},{"phrase":"bathroom mirror"},{"phrase":"rear-view mirror"},{"phrase":"full-length mirror"}]',NULL,'/ˈmɪrər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mir/mirro/mirror__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2177,'ngsl-5-07',26,'awful','tồi tệ; kinh khủng','adjective','[{"en":"The food at that hotel was absolutely awful.","vi":"Đồ ăn ở khách sạn đó thật sự tồi tệ."},{"en":"I feel awful about forgetting your birthday.","vi":"Tôi thấy thật tệ vì đã quên sinh nhật của bạn."},{"en":"We had awful weather for the whole week of our vacation.","vi":"Suốt cả tuần nghỉ lễ, thời tiết chỗ chúng tôi thật kinh khủng."}]','[{"phrase":"feel awful"},{"phrase":"awful weather"},{"phrase":"absolutely awful"},{"phrase":"look awful"}]',NULL,'/ˈɔːfl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awf/awful/awful__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2178,'ngsl-5-07',27,'pose','gây ra (mối đe dọa, vấn đề); đặt ra (câu hỏi); tạo dáng','verb','[{"en":"Smoking poses a serious risk to your health.","vi":"Hút thuốc gây ra mối nguy hiểm nghiêm trọng cho sức khỏe của bạn."},{"en":"The new rules pose a problem for small businesses.","vi":"Các quy định mới đặt ra một vấn đề cho các doanh nghiệp nhỏ."},{"en":"The whole family posed for a photo in front of the lake.","vi":"Cả gia đình tạo dáng chụp ảnh trước hồ."}]','[{"phrase":"pose a threat"},{"phrase":"pose a risk"},{"phrase":"pose a question"},{"phrase":"pose for a photo"}]',NULL,'/pəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/pose_/pose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2179,'ngsl-5-07',28,'adjust','điều chỉnh; thích nghi','verb','[{"en":"You can adjust the height of this chair with the lever.","vi":"Bạn có thể điều chỉnh độ cao của chiếc ghế này bằng cần gạt."},{"en":"It took me a few weeks to adjust to my new school.","vi":"Tôi mất vài tuần để thích nghi với trường mới."},{"en":"Let your eyes adjust to the dark before you move.","vi":"Hãy để mắt quen với bóng tối trước khi bạn di chuyển."}]','[{"phrase":"adjust to"},{"phrase":"adjust the temperature"},{"phrase":"adjust the settings"},{"phrase":"quickly adjust"}]','adjust to sth: thích nghi với','/əˈdʒʌst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjus/adjust__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2180,'ngsl-5-07',29,'creative','sáng tạo','adjective','[{"en":"My sister is very creative and loves painting and writing.","vi":"Chị tôi rất sáng tạo và thích vẽ tranh lẫn viết lách."},{"en":"We need a creative way to solve this problem.","vi":"Chúng ta cần một cách sáng tạo để giải quyết vấn đề này."},{"en":"The course helps students develop their creative skills.","vi":"Khóa học giúp học viên phát triển các kỹ năng sáng tạo."}]','[{"phrase":"creative thinking"},{"phrase":"creative writing"},{"phrase":"creative ideas"},{"phrase":"highly creative"}]',NULL,'/kriˈeɪtɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/creative__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2181,'ngsl-5-07',30,'nowadays','ngày nay; thời nay','adverb','[{"en":"Nowadays, most people pay for things with their phones.","vi":"Ngày nay, hầu hết mọi người thanh toán bằng điện thoại."},{"en":"Children spend much more time indoors nowadays.","vi":"Thời nay trẻ em dành nhiều thời gian ở trong nhà hơn hẳn."},{"en":"Do you still play tennis nowadays, or have you stopped?","vi":"Dạo này bạn còn chơi quần vợt không, hay đã nghỉ rồi?"}]','[{"phrase":"especially nowadays"},{"phrase":"nowadays, most people"}]',NULL,'/ˈnaʊədeɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/now/nowad/nowadays__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2182,'ngsl-5-08',1,'poem','bài thơ','noun','[{"en":"My daughter wrote a short poem about her grandmother.","vi":"Con gái tôi đã viết một bài thơ ngắn về bà của cháu."},{"en":"Can you read the poem aloud to the class?","vi":"Em có thể đọc to bài thơ cho cả lớp nghe không?"},{"en":"We had to learn three poems by heart for the exam.","vi":"Chúng tôi phải học thuộc lòng ba bài thơ cho kỳ thi."}]','[{"phrase":"write a poem"},{"phrase":"read a poem"},{"phrase":"love poem"},{"phrase":"short poem"}]',NULL,'/ˈpəʊəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poe/poem_/poem__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2183,'ngsl-5-08',2,'agricultural','(thuộc) nông nghiệp','adjective','[{"en":"Most of the land around our village is used for agricultural purposes.","vi":"Phần lớn đất quanh làng tôi được dùng vào mục đích nông nghiệp."},{"en":"Rice is the country''s most important agricultural product.","vi":"Lúa gạo là nông sản quan trọng nhất của đất nước."},{"en":"He studied agricultural science before returning to run the family farm.","vi":"Anh ấy học ngành khoa học nông nghiệp trước khi về quản lý trang trại của gia đình."}]','[{"phrase":"agricultural land"},{"phrase":"agricultural products"},{"phrase":"agricultural production"},{"phrase":"agricultural sector"}]',NULL,'/ˌæɡrɪˈkʌltʃərəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agr/agric/agricultural__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2184,'ngsl-5-08',3,'competitor','đối thủ cạnh tranh; đấu thủ','noun','[{"en":"Our prices are lower than those of our main competitors.","vi":"Giá của chúng tôi thấp hơn giá của các đối thủ cạnh tranh chính."},{"en":"The company lost many customers to a new competitor last year.","vi":"Năm ngoái công ty đã mất nhiều khách hàng vào tay một đối thủ mới."},{"en":"More than two hundred competitors took part in the race.","vi":"Hơn hai trăm đấu thủ đã tham gia cuộc đua."}]','[{"phrase":"main competitor"},{"phrase":"major competitor"},{"phrase":"direct competitor"}]',NULL,'/kəmˈpetɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/competitor__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2185,'ngsl-5-08',4,'alcohol','rượu bia; cồn','noun','[{"en":"My father stopped drinking alcohol after his heart problems.","vi":"Bố tôi đã bỏ rượu bia sau khi bị bệnh tim."},{"en":"You shouldn''t drive if you have had any alcohol.","vi":"Bạn không nên lái xe nếu đã uống chút rượu bia nào."},{"en":"Clean the cut with a little alcohol before putting on a bandage.","vi":"Hãy lau vết cắt bằng một chút cồn trước khi băng lại."}]','[{"phrase":"drink alcohol"},{"phrase":"alcohol consumption"},{"phrase":"alcohol-free"}]','không đếm được','/ˈælkəhɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alc/alcoh/alcohol__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2186,'ngsl-5-08',5,'festival','lễ hội; liên hoan','noun','[{"en":"Thousands of people come to the town for the summer music festival.","vi":"Hàng nghìn người đến thị trấn dự lễ hội âm nhạc mùa hè."},{"en":"Children carry colorful lanterns during the Mid-Autumn Festival.","vi":"Trẻ em rước những chiếc đèn lồng đầy màu sắc trong dịp Tết Trung thu."},{"en":"Her short film won a prize at an international film festival.","vi":"Phim ngắn của cô ấy đã đoạt giải tại một liên hoan phim quốc tế."}]','[{"phrase":"music festival"},{"phrase":"film festival"},{"phrase":"hold a festival"}]',NULL,'/ˈfestɪvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fes/festi/festival__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2187,'ngsl-5-08',6,'vegetable','rau; rau củ','noun','[{"en":"Try to eat more fresh fruit and vegetables every day.","vi":"Hãy cố gắng ăn nhiều trái cây và rau tươi hơn mỗi ngày."},{"en":"My grandmother grows vegetables in a small garden behind her house.","vi":"Bà tôi trồng rau trong một mảnh vườn nhỏ sau nhà."},{"en":"Is this soup made with any meat, or only vegetables?","vi":"Món súp này có nấu với thịt không, hay chỉ có rau củ?"}]','[{"phrase":"fresh vegetables"},{"phrase":"grow vegetables"},{"phrase":"fruit and vegetables"},{"phrase":"vegetable soup"}]',NULL,'/ˈvedʒtəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/veg/veget/vegetable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2188,'ngsl-5-08',7,'van','xe tải nhỏ; xe van','noun','[{"en":"We rented a van to move our furniture to the new apartment.","vi":"Chúng tôi đã thuê một chiếc xe tải nhỏ để chuyển đồ đạc sang căn hộ mới."},{"en":"A delivery van is parked in front of the building.","vi":"Một chiếc xe giao hàng đang đậu trước tòa nhà."},{"en":"He drives a van for a small bakery in town.","vi":"Anh ấy lái xe van cho một tiệm bánh nhỏ trong thị trấn."}]','[{"phrase":"delivery van"},{"phrase":"drive a van"},{"phrase":"police van"}]',NULL,'/væn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/van/van__/van__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2189,'ngsl-5-08',8,'confident','tự tin; tin chắc','adjective','[{"en":"She felt much more confident after practicing her speech several times.","vi":"Cô ấy cảm thấy tự tin hơn nhiều sau khi tập bài phát biểu vài lần."},{"en":"I''m confident that we will finish the project on time.","vi":"Tôi tin chắc rằng chúng ta sẽ hoàn thành dự án đúng hạn."},{"en":"Are you confident enough to speak English with foreign customers?","vi":"Bạn có đủ tự tin để nói tiếng Anh với khách nước ngoài không?"}]','[{"phrase":"feel confident"},{"phrase":"confident that"},{"phrase":"confident about"}]',NULL,'/ˈkɑːnfɪdənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfident__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2190,'ngsl-5-08',9,'planet','hành tinh; Trái Đất','noun','[{"en":"Mars is the fourth planet from the sun.","vi":"Sao Hỏa là hành tinh thứ tư tính từ Mặt Trời."},{"en":"We all need to do more to protect the planet.","vi":"Tất cả chúng ta cần làm nhiều hơn để bảo vệ Trái Đất."},{"en":"Scientists have discovered a new planet far outside our solar system.","vi":"Các nhà khoa học đã phát hiện một hành tinh mới ở rất xa ngoài hệ Mặt Trời."}]','[{"phrase":"save the planet"},{"phrase":"protect the planet"},{"phrase":"distant planet"}]',NULL,'/ˈplænɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pla/plane/planet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2191,'ngsl-5-08',10,'curve','đường cong; khúc cua','noun','[{"en":"The river makes a wide curve around the old town.","vi":"Dòng sông uốn một đường cong rộng quanh khu phố cổ."},{"en":"Slow down, there''s a sharp curve in the road ahead.","vi":"Chậm lại đi, phía trước có một khúc cua gấp."},{"en":"The bus took the curve too fast and almost left the road.","vi":"Chiếc xe buýt vào cua quá nhanh và suýt lao ra khỏi đường."}]','[{"phrase":"sharp curve"},{"phrase":"gentle curve"},{"phrase":"learning curve"}]',NULL,'/kɜːrv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curve/curve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2192,'ngsl-5-08',11,'knee','đầu gối','noun','[{"en":"He hurt his knee while playing football on Saturday.","vi":"Anh ấy bị đau đầu gối khi chơi bóng đá hôm thứ Bảy."},{"en":"The little boy sat on his father''s knee and listened to the story.","vi":"Cậu bé ngồi trên đầu gối bố và nghe kể chuyện."},{"en":"My knees start to ache when I walk up too many stairs.","vi":"Đầu gối tôi bắt đầu đau nhức khi leo quá nhiều bậc thang."}]','[{"phrase":"knee injury"},{"phrase":"bend your knees"},{"phrase":"on your knees"}]',NULL,'/niː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kne/knee_/knee__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2193,'ngsl-5-08',12,'overcome','vượt qua; khắc phục','verb','[{"en":"She worked hard to overcome her fear of speaking in public.","vi":"Cô ấy đã rất cố gắng để vượt qua nỗi sợ nói trước đám đông."},{"en":"Together we can overcome any difficulties that come our way.","vi":"Cùng nhau, chúng ta có thể vượt qua mọi khó khăn gặp phải."},{"en":"The team overcame several technical problems to launch the app on time.","vi":"Nhóm đã khắc phục một số sự cố kỹ thuật để ra mắt ứng dụng đúng hạn."}]','[{"phrase":"overcome a problem"},{"phrase":"overcome difficulties"},{"phrase":"overcome fear"},{"phrase":"overcome obstacles"}]','overcome – overcame – overcome','/ˌəʊvərˈkʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overc/overcome__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2194,'ngsl-5-08',13,'web','mạng (Internet); mạng nhện','noun','[{"en":"You can find the train timetable on the web.","vi":"Bạn có thể tìm lịch tàu chạy trên mạng."},{"en":"My brother designs web pages for small businesses.","vi":"Anh tôi thiết kế trang web cho các doanh nghiệp nhỏ."},{"en":"A large spider had built a web in the corner of the window.","vi":"Một con nhện lớn đã giăng mạng ở góc cửa sổ."}]','[{"phrase":"on the web"},{"phrase":"web page"},{"phrase":"web browser"},{"phrase":"spider''s web"}]',NULL,'/web/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/web/web__/web__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2195,'ngsl-5-08',14,'depth','độ sâu; chiều sâu','noun','[{"en":"The lake reaches a depth of about thirty meters in the middle.","vi":"Ở giữa, hồ có độ sâu khoảng ba mươi mét."},{"en":"Measure the height, width and depth of the box before you order it.","vi":"Hãy đo chiều cao, chiều rộng và chiều sâu của chiếc hộp trước khi đặt mua."},{"en":"We need to discuss this issue in more depth at the next meeting.","vi":"Chúng ta cần thảo luận vấn đề này sâu hơn trong buổi họp tới."}]','[{"phrase":"in depth"},{"phrase":"a depth of"},{"phrase":"depth of knowledge"}]',NULL,'/depθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depth/depth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2196,'ngsl-5-08',15,'entrance','lối vào; sự vào, sự nhập học','noun','[{"en":"I''ll wait for you at the main entrance of the hospital.","vi":"Mình sẽ đợi bạn ở lối vào chính của bệnh viện."},{"en":"The entrance to the museum is on the other side of the street.","vi":"Lối vào bảo tàng ở phía bên kia đường."},{"en":"He studied very hard to pass the university entrance exam.","vi":"Cậu ấy đã học rất chăm để thi đỗ kỳ thi tuyển sinh đại học."}]','[{"phrase":"main entrance"},{"phrase":"front entrance"},{"phrase":"entrance to"},{"phrase":"entrance exam"}]',NULL,'/ˈɛntrəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2197,'ngsl-5-08',16,'log','khúc gỗ; nhật ký (ghi chép)','noun','[{"en":"We sat on a log and warmed our hands by the fire.","vi":"Chúng tôi ngồi trên một khúc gỗ và hơ tay bên đống lửa."},{"en":"He put another log on the fire before going to bed.","vi":"Anh ấy cho thêm một khúc gỗ vào lửa trước khi đi ngủ."},{"en":"Drivers must keep a log of every trip they make.","vi":"Tài xế phải ghi nhật ký mọi chuyến đi của mình."}]','[{"phrase":"keep a log"},{"phrase":"log fire"},{"phrase":"fallen log"}]','cụm động từ: log in / log out (đăng nhập / đăng xuất)','/lɔːɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/log/log__/log__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2198,'ngsl-5-08',17,'giant','khổng lồ; to lớn','adjective','[{"en":"A giant screen showed the football match in the town square.","vi":"Một màn hình khổng lồ chiếu trận bóng đá ở quảng trường thị trấn."},{"en":"The kids were amazed by the giant turtles at the zoo.","vi":"Bọn trẻ thích thú với những con rùa khổng lồ ở sở thú."},{"en":"Moving to another country was a giant step for our family.","vi":"Chuyển sang nước khác sống là một bước tiến lớn đối với gia đình tôi."}]','[{"phrase":"giant screen"},{"phrase":"giant step"},{"phrase":"giant panda"}]','cũng là danh từ: người khổng lồ; tập đoàn lớn (tech giant)','/ˈdʒaɪənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gia/giant/giant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2199,'ngsl-5-08',18,'god','thần; vị thần','noun','[{"en":"In the old story, the god of the sea was very angry.","vi":"Trong câu chuyện xưa, thần biển đã rất tức giận."},{"en":"The ancient Greeks believed that many gods lived on a high mountain.","vi":"Người Hy Lạp cổ đại tin rằng nhiều vị thần sống trên một ngọn núi cao."},{"en":"The children read a book of myths about gods and heroes.","vi":"Bọn trẻ đọc một cuốn sách thần thoại về các vị thần và anh hùng."}]','[{"phrase":"the god of"},{"phrase":"ancient gods"},{"phrase":"gods and goddesses"}]','God (viết hoa) = Chúa, Thượng đế','/ɡɑːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/god/god__/god__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2200,'ngsl-5-08',19,'portion','phần; suất (ăn)','noun','[{"en":"The portions at that restaurant are big enough for two people.","vi":"Suất ăn ở nhà hàng đó đủ lớn cho hai người."},{"en":"A large portion of my salary goes on rent.","vi":"Một phần lớn tiền lương của tôi dùng để trả tiền nhà."},{"en":"Only a small portion of the road was damaged by the storm.","vi":"Chỉ một phần nhỏ con đường bị bão làm hư hại."}]','[{"phrase":"large portion"},{"phrase":"small portion"},{"phrase":"portion of"},{"phrase":"portion size"}]',NULL,'/ˈpɔːrʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/porti/portion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2201,'ngsl-5-08',20,'substance','chất; thực chất, nội dung','noun','[{"en":"Keep dangerous substances out of the reach of children.","vi":"Hãy để các chất nguy hiểm xa tầm tay trẻ em."},{"en":"The scientists found a strange white substance on the rocks.","vi":"Các nhà khoa học tìm thấy một chất màu trắng lạ trên những tảng đá."},{"en":"His speech sounded good but had very little substance.","vi":"Bài phát biểu của anh ta nghe hay nhưng có rất ít nội dung thực chất."}]','[{"phrase":"dangerous substance"},{"phrase":"chemical substance"},{"phrase":"harmful substances"}]',NULL,'/ˈsʌbstəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substance__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2202,'ngsl-5-08',21,'extensive','rộng lớn; sâu rộng, nhiều','adjective','[{"en":"The hotel has extensive gardens with a pool and tennis courts.","vi":"Khách sạn có khu vườn rộng lớn với hồ bơi và sân quần vợt."},{"en":"She has extensive experience in teaching young children.","vi":"Cô ấy có nhiều kinh nghiệm dạy trẻ nhỏ."},{"en":"The storm caused extensive damage to houses along the coast.","vi":"Cơn bão đã gây thiệt hại trên diện rộng cho nhà cửa dọc bờ biển."}]','[{"phrase":"extensive experience"},{"phrase":"extensive damage"},{"phrase":"extensive research"},{"phrase":"extensive knowledge"}]',NULL,'/ɪkˈstensɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extensive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2203,'ngsl-5-08',22,'interpret','hiểu, giải thích; phiên dịch','verb','[{"en":"I really didn''t know how to interpret his silence.","vi":"Tôi thật sự không biết phải hiểu sự im lặng của anh ấy thế nào."},{"en":"Doctors are trained to interpret the results of blood tests.","vi":"Bác sĩ được đào tạo để giải thích kết quả xét nghiệm máu."},{"en":"My cousin interpreted for us when we went shopping in Japan.","vi":"Anh họ tôi phiên dịch giúp chúng tôi khi đi mua sắm ở Nhật."}]','[{"phrase":"interpret data"},{"phrase":"interpret the results"},{"phrase":"interpret as"}]',NULL,'/ɪnˈtɜːrprət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interpret__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2204,'ngsl-5-08',23,'independence','sự độc lập; sự tự lập','noun','[{"en":"Getting my first job gave me a real sense of independence.","vi":"Có công việc đầu tiên mang lại cho tôi cảm giác tự lập thực sự."},{"en":"Many teenagers want more independence from their parents.","vi":"Nhiều thanh thiếu niên muốn được độc lập hơn với bố mẹ."},{"en":"Moving out helped her gain financial independence at a young age.","vi":"Ra ở riêng đã giúp cô ấy độc lập về tài chính từ khi còn trẻ."}]','[{"phrase":"financial independence"},{"phrase":"sense of independence"},{"phrase":"gain independence"},{"phrase":"independence from"}]',NULL,'/ˌɪndɪˈpendəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indep/independence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2205,'ngsl-5-08',24,'sugar','đường','noun','[{"en":"Do you take sugar in your coffee or tea?","vi":"Bạn có cho đường vào cà phê hay trà không?"},{"en":"Mix the butter and sugar together until the mixture is soft.","vi":"Trộn bơ với đường cho đến khi hỗn hợp mềm."},{"en":"The doctor told me to cut down on sugar and salt.","vi":"Bác sĩ bảo tôi nên ăn bớt đường và muối."}]','[{"phrase":"brown sugar"},{"phrase":"add sugar"},{"phrase":"cut down on sugar"}]','không đếm được (a spoonful of sugar)','/ˈʃʊɡər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sug/sugar/sugar__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2206,'ngsl-5-08',25,'inner','bên trong; nội tâm','adjective','[{"en":"Put your wallet in the inner pocket of your jacket.","vi":"Hãy cất ví vào túi trong của áo khoác."},{"en":"The inner walls of the old house were painted white.","vi":"Các bức tường bên trong ngôi nhà cũ được sơn màu trắng."},{"en":"Yoga helps me find inner peace after a busy day.","vi":"Yoga giúp tôi tìm lại sự bình yên trong tâm hồn sau một ngày bận rộn."}]','[{"phrase":"inner city"},{"phrase":"inner peace"},{"phrase":"inner pocket"},{"phrase":"inner circle"}]','inner ≠ outer (bên ngoài)','/ˈɪnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/inner/inner__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2207,'ngsl-5-08',26,'harm','sự tổn hại; điều có hại','noun','[{"en":"A little extra rest won''t do you any harm.","vi":"Nghỉ ngơi thêm một chút cũng chẳng hại gì cho bạn."},{"en":"Too much sun can cause serious harm to your skin.","vi":"Phơi nắng quá nhiều có thể gây hại nghiêm trọng cho da."},{"en":"Don''t worry, the dog is friendly and means no harm.","vi":"Đừng lo, con chó thân thiện và không có ý làm hại ai đâu."}]','[{"phrase":"do harm"},{"phrase":"cause harm"},{"phrase":"no harm done"},{"phrase":"mean no harm"}]','cũng là động từ: harm (làm hại)','/hɑːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/har/harm_/harm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2208,'ngsl-5-08',27,'consult','hỏi ý kiến; tra cứu','verb','[{"en":"You should consult a doctor if the pain doesn''t go away.","vi":"Bạn nên hỏi ý kiến bác sĩ nếu cơn đau không hết."},{"en":"My boss made the decision without consulting anyone on the team.","vi":"Sếp tôi đã quyết định mà không hỏi ý kiến ai trong nhóm."},{"en":"She consulted the map to find the quickest way home.","vi":"Cô ấy tra bản đồ để tìm đường về nhà nhanh nhất."}]','[{"phrase":"consult a doctor"},{"phrase":"consult a lawyer"},{"phrase":"consult with"},{"phrase":"consult a dictionary"}]',NULL,'/kənˈsʌlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsult__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2209,'ngsl-5-08',28,'pink','(màu) hồng','adjective','[{"en":"My little sister wants to paint her bedroom walls pink.","vi":"Em gái tôi muốn sơn tường phòng ngủ màu hồng."},{"en":"She wore a pale pink dress to her friend''s wedding.","vi":"Cô ấy mặc một chiếc váy hồng nhạt đến đám cưới bạn."},{"en":"The sky turned pink as the sun went down.","vi":"Bầu trời chuyển sang màu hồng khi mặt trời lặn."}]','[{"phrase":"pale pink"},{"phrase":"bright pink"},{"phrase":"turn pink"},{"phrase":"light pink"}]',NULL,'/pɪŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pin/pink_/pink__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2210,'ngsl-5-08',29,'shadow','bóng; bóng tối','noun','[{"en":"In the late afternoon, the trees cast long shadows across the grass.","vi":"Vào cuối chiều, cây cối đổ những chiếc bóng dài trên bãi cỏ."},{"en":"The cat was hiding in the shadows under the car.","vi":"Con mèo đang nấp trong bóng tối dưới gầm xe."},{"en":"My son is scared of his own shadow on the wall at night.","vi":"Con trai tôi sợ chính cái bóng của mình trên tường vào ban đêm."}]','[{"phrase":"cast a shadow"},{"phrase":"long shadows"},{"phrase":"in the shadows"},{"phrase":"dark shadow"}]',NULL,'/ˈʃædəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shado/shadow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2211,'ngsl-5-08',30,'strip','dải; mảnh dài','noun','[{"en":"Cut the chicken into thin strips before you fry it.","vi":"Thái thịt gà thành từng dải mỏng trước khi chiên."},{"en":"There is a narrow strip of sand between the hotel and the sea.","vi":"Có một dải cát hẹp giữa khách sạn và biển."},{"en":"He tied the top of the bag with a strip of cloth.","vi":"Anh ấy buộc miệng túi bằng một mảnh vải dài."}]','[{"phrase":"thin strip"},{"phrase":"narrow strip"},{"phrase":"strip of land"},{"phrase":"strip of paper"}]','cũng là động từ: strip (lột, cởi bỏ)','/strɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strip/strip__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2212,'ngsl-5-09',1,'smooth','nhẵn, mịn; suôn sẻ','adjective','[{"en":"Her skin felt smooth after she used the new cream.","vi":"Da cô ấy trở nên mịn màng sau khi dùng loại kem mới."},{"en":"The road was smooth, so the drive was very comfortable.","vi":"Mặt đường bằng phẳng nên lái xe rất êm."},{"en":"The new manager helped ensure a smooth transition for the team.","vi":"Người quản lý mới đã giúp cả nhóm chuyển giao suôn sẻ."}]','[{"phrase":"smooth surface"},{"phrase":"smooth skin"},{"phrase":"smooth transition"}]',NULL,'/smuːð/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/smo/smoot/smooth__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2213,'ngsl-5-09',2,'intervention','sự can thiệp','noun','[{"en":"Early intervention can stop a small health problem from getting worse.","vi":"Can thiệp sớm có thể ngăn một vấn đề sức khỏe nhỏ trở nên nặng hơn."},{"en":"The fight ended without any intervention from the teachers.","vi":"Cuộc ẩu đả kết thúc mà không cần giáo viên can thiệp."},{"en":"The patient recovered quickly after surgical intervention.","vi":"Bệnh nhân hồi phục nhanh sau khi được can thiệp phẫu thuật."}]','[{"phrase":"early intervention"},{"phrase":"government intervention"},{"phrase":"surgical intervention"}]',NULL,'/ˌɪntərˈvenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/intervention__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2214,'ngsl-5-09',3,'impress','gây ấn tượng; làm thán phục','verb','[{"en":"She wore a suit to impress the interviewers.","vi":"Cô ấy mặc vest để gây ấn tượng với những người phỏng vấn."},{"en":"I was really impressed by how clean the hotel was.","vi":"Tôi thực sự ấn tượng vì khách sạn rất sạch sẽ."},{"en":"His cooking skills never fail to impress his friends.","vi":"Tài nấu ăn của anh ấy luôn khiến bạn bè thán phục."}]','[{"phrase":"try to impress"},{"phrase":"impressed by"},{"phrase":"fail to impress"}]','be impressed by/with: ấn tượng với','/ɪmˈpres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impre/impress__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2215,'ngsl-5-09',4,'exam','kỳ thi; bài thi','noun','[{"en":"I have to study hard for my math exam tomorrow.","vi":"Tôi phải học chăm chỉ cho bài thi toán ngày mai."},{"en":"Did you pass your driving exam on your first try?","vi":"Bạn có đậu kỳ thi lái xe ngay lần đầu không?"},{"en":"Students are not allowed to use phones during the exam.","vi":"Học sinh không được dùng điện thoại trong lúc làm bài thi."}]','[{"phrase":"pass an exam"},{"phrase":"final exam"},{"phrase":"driving exam"},{"phrase":"exam results"}]',NULL,'/ɪɡˈzæm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exam_/exam__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2216,'ngsl-5-09',5,'vice','thói xấu; tật xấu','noun','[{"en":"Chocolate is my only vice, and I eat it every day.","vi":"Sô-cô-la là thói xấu duy nhất của tôi, và ngày nào tôi cũng ăn."},{"en":"Smoking was his worst vice, but he finally quit.","vi":"Hút thuốc là tật xấu tệ nhất của anh ấy, nhưng cuối cùng anh ấy đã bỏ được."},{"en":"Laziness is a vice that can hurt your career.","vi":"Lười biếng là một thói xấu có thể ảnh hưởng đến sự nghiệp của bạn."}]','[{"phrase":"my only vice"},{"phrase":"virtue and vice"}]','vice- (tiền tố) = phó: vice president (phó chủ tịch)','/vaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vic/vice_/vice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2217,'ngsl-5-09',6,'radical','triệt để, căn bản; cấp tiến','adjective','[{"en":"The company needs radical changes to survive.","vi":"Công ty cần những thay đổi triệt để để tồn tại."},{"en":"The new teacher took a radical approach to homework.","vi":"Thầy giáo mới có cách tiếp cận hoàn toàn mới đối với bài tập về nhà."},{"en":"Some of his radical ideas surprised the older staff.","vi":"Một số ý tưởng cấp tiến của anh ấy khiến các nhân viên lớn tuổi bất ngờ."}]','[{"phrase":"radical change"},{"phrase":"radical idea"},{"phrase":"radical approach"},{"phrase":"radical reform"}]',NULL,'/ˈrædɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rad/radic/radical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2218,'ngsl-5-09',7,'similarly','tương tự; giống nhau','adverb','[{"en":"The two sisters dress similarly and often look like twins.","vi":"Hai chị em ăn mặc giống nhau và thường trông như sinh đôi."},{"en":"Prices rose last year, and similarly, rents went up sharply.","vi":"Giá cả tăng vào năm ngoái, và tương tự, tiền thuê nhà cũng tăng mạnh."},{"en":"Cats and dogs sometimes behave similarly when they feel afraid.","vi":"Mèo và chó đôi khi cư xử giống nhau khi cảm thấy sợ."}]','[{"phrase":"behave similarly"},{"phrase":"similarly dressed"}]',NULL,'/ˈsɪmələrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simil/similarly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2219,'ngsl-5-09',8,'behave','cư xử; hành xử','verb','[{"en":"The children behaved very well at the restaurant.","vi":"Bọn trẻ cư xử rất ngoan ở nhà hàng."},{"en":"Please behave yourself when your grandparents visit.","vi":"Con hãy ngoan ngoãn khi ông bà đến chơi nhé."},{"en":"He behaved badly at the party and later apologized.","vi":"Anh ấy cư xử tệ ở bữa tiệc và sau đó đã xin lỗi."}]','[{"phrase":"behave well"},{"phrase":"behave badly"},{"phrase":"behave yourself"}]',NULL,'/bɪˈheɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beh/behav/behave__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2220,'ngsl-5-09',9,'loud','to, lớn (âm thanh); ồn ào','adjective','[{"en":"The music at the party was too loud for me.","vi":"Nhạc ở bữa tiệc quá to đối với tôi."},{"en":"We heard a loud noise coming from the kitchen.","vi":"Chúng tôi nghe thấy một tiếng động lớn phát ra từ nhà bếp."},{"en":"Our neighbors are very loud late at night.","vi":"Hàng xóm nhà tôi rất ồn ào vào đêm khuya."}]','[{"phrase":"loud noise"},{"phrase":"loud music"},{"phrase":"loud voice"},{"phrase":"out loud"}]','read out loud: đọc to','/laʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lou/loud_/loud__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2221,'ngsl-5-09',10,'dimension','kích thước; khía cạnh; chiều','noun','[{"en":"Please measure the dimensions of the room before buying a sofa.","vi":"Hãy đo kích thước căn phòng trước khi mua ghế sofa."},{"en":"Having a baby added a new dimension to their lives.","vi":"Việc có con đã mang lại một khía cạnh mới cho cuộc sống của họ."},{"en":"The film looks amazing in three dimensions.","vi":"Bộ phim trông tuyệt vời khi xem ở dạng ba chiều."}]','[{"phrase":"new dimension"},{"phrase":"three dimensions"},{"phrase":"exact dimensions"}]',NULL,'/daɪˈmenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dim/dimen/dimension__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2222,'ngsl-5-09',11,'subsequent','sau đó; tiếp theo','adjective','[{"en":"The shop did well in its first year and in subsequent years.","vi":"Cửa hàng làm ăn tốt trong năm đầu và cả những năm sau đó."},{"en":"Subsequent events proved that she had made the right choice.","vi":"Những sự việc sau đó chứng minh rằng cô ấy đã lựa chọn đúng."},{"en":"The report and the subsequent discussion took most of the meeting.","vi":"Bản báo cáo và cuộc thảo luận sau đó chiếm gần hết buổi họp."}]','[{"phrase":"subsequent years"},{"phrase":"subsequent events"},{"phrase":"subsequent to"}]','subsequent to = sau khi','/ˈsʌbsɪkwənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subse/subsequent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2223,'ngsl-5-09',12,'infection','sự nhiễm trùng; bệnh nhiễm trùng','noun','[{"en":"Wash the cut carefully to prevent infection.","vi":"Hãy rửa vết cắt thật kỹ để tránh nhiễm trùng."},{"en":"She missed a week of school because of an ear infection.","vi":"Cô bé nghỉ học một tuần vì bị viêm tai."},{"en":"Hand washing lowers the risk of infection in hospitals.","vi":"Rửa tay giúp giảm nguy cơ nhiễm trùng trong bệnh viện."}]','[{"phrase":"ear infection"},{"phrase":"risk of infection"},{"phrase":"prevent infection"},{"phrase":"viral infection"}]',NULL,'/ɪnˈfekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infec/infection__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2224,'ngsl-5-09',13,'jacket','áo khoác','noun','[{"en":"Take a jacket because it gets cold in the evening.","vi":"Mang theo áo khoác đi vì buổi tối trời sẽ lạnh."},{"en":"He bought a leather jacket at the market.","vi":"Anh ấy mua một chiếc áo khoác da ở chợ."},{"en":"She took off her jacket and hung it by the door.","vi":"Cô ấy cởi áo khoác và treo nó cạnh cửa."}]','[{"phrase":"leather jacket"},{"phrase":"put on a jacket"},{"phrase":"life jacket"}]','life jacket: áo phao','/ˈdʒækɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jac/jacke/jacket__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2225,'ngsl-5-09',14,'efficiency','hiệu quả; hiệu suất','noun','[{"en":"The new software has improved the efficiency of our office.","vi":"Phần mềm mới đã nâng cao hiệu quả làm việc của văn phòng chúng tôi."},{"en":"This fridge is known for its high energy efficiency.","vi":"Chiếc tủ lạnh này nổi tiếng vì hiệu suất năng lượng cao."},{"en":"She works with great speed and efficiency.","vi":"Cô ấy làm việc rất nhanh và hiệu quả."}]','[{"phrase":"energy efficiency"},{"phrase":"improve efficiency"},{"phrase":"fuel efficiency"}]','không đếm được','/ɪˈfɪʃnsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eff/effic/efficiency__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2226,'ngsl-5-09',15,'dirty','bẩn','adjective','[{"en":"Put your dirty clothes in the washing machine.","vi":"Hãy bỏ quần áo bẩn vào máy giặt."},{"en":"The kids came home with dirty hands and muddy shoes.","vi":"Bọn trẻ về nhà với đôi tay bẩn và giày dính đầy bùn."},{"en":"Nobody wants to wash the dirty dishes after dinner.","vi":"Chẳng ai muốn rửa bát đĩa bẩn sau bữa tối."}]','[{"phrase":"dirty clothes"},{"phrase":"dirty dishes"},{"phrase":"dirty water"},{"phrase":"get dirty"}]',NULL,'/ˈdɜːrti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/dirty/dirty__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2227,'ngsl-5-09',16,'statistic','số liệu thống kê','noun','[{"en":"Statistics show that more people are working from home.","vi":"Số liệu thống kê cho thấy ngày càng nhiều người làm việc tại nhà."},{"en":"One surprising statistic is that most accidents happen near home.","vi":"Một số liệu đáng ngạc nhiên là phần lớn tai nạn xảy ra gần nhà."},{"en":"The report includes the latest statistics on tourism in the region.","vi":"Bản báo cáo có các số liệu thống kê mới nhất về du lịch trong khu vực."}]','[{"phrase":"statistics show"},{"phrase":"official statistics"},{"phrase":"latest statistics"}]','thường dùng số nhiều: statistics','/stəˈtɪstɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stati/statistic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2228,'ngsl-5-09',17,'regularly','thường xuyên; đều đặn','adverb','[{"en":"You should exercise regularly to stay healthy.","vi":"Bạn nên tập thể dục đều đặn để giữ sức khỏe."},{"en":"We regularly visit our grandparents on Sundays.","vi":"Chúng tôi thường xuyên đến thăm ông bà vào Chủ nhật."},{"en":"Remember to check the oil in your car regularly.","vi":"Hãy nhớ kiểm tra dầu xe ô tô thường xuyên."}]','[{"phrase":"exercise regularly"},{"phrase":"meet regularly"},{"phrase":"regularly visit"}]',NULL,'/ˈreɡjələrli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regularly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2229,'ngsl-5-09',18,'resort','khu nghỉ dưỡng; giải pháp (cuối cùng)','noun','[{"en":"We stayed at a beach resort for our honeymoon.","vi":"Chúng tôi ở một khu nghỉ dưỡng ven biển trong tuần trăng mật."},{"en":"The ski resort is busiest in January and February.","vi":"Khu nghỉ dưỡng trượt tuyết đông khách nhất vào tháng Một và tháng Hai."},{"en":"Borrowing money from my parents is a last resort.","vi":"Vay tiền bố mẹ là giải pháp cuối cùng của tôi."}]','[{"phrase":"beach resort"},{"phrase":"ski resort"},{"phrase":"holiday resort"},{"phrase":"last resort"}]','resort to sth (v): buộc phải dùng đến','/rɪˈzɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resor/resort__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2230,'ngsl-5-09',19,'iron','sắt; bàn là','noun','[{"en":"Spinach and red meat are rich in iron.","vi":"Rau chân vịt và thịt đỏ rất giàu chất sắt."},{"en":"The old gate is made of iron and is very heavy.","vi":"Chiếc cổng cũ được làm bằng sắt và rất nặng."},{"en":"Be careful, because the iron is still hot.","vi":"Cẩn thận nhé, vì bàn là vẫn còn nóng."}]','[{"phrase":"rich in iron"},{"phrase":"cast iron"},{"phrase":"steam iron"}]','iron (v): là, ủi quần áo','/ˈaɪərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iro/iron_/iron__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2231,'ngsl-5-09',20,'broadcast','phát sóng; truyền hình, phát thanh','verb','[{"en":"The final match will be broadcast live on TV.","vi":"Trận chung kết sẽ được phát sóng trực tiếp trên TV."},{"en":"The radio station broadcasts news every hour.","vi":"Đài phát thanh phát tin tức mỗi giờ."},{"en":"They broadcast the concert on the internet last night.","vi":"Tối qua họ đã phát sóng buổi hòa nhạc trên mạng."}]','[{"phrase":"broadcast live"},{"phrase":"broadcast news"},{"phrase":"broadcast on television"}]','broadcast – broadcast – broadcast','/ˈbrɔːdkæst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bro/broad/broadcast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2232,'ngsl-5-09',21,'membership','tư cách thành viên; hội viên','noun','[{"en":"My gym membership costs thirty dollars a month.","vi":"Phí hội viên phòng gym của tôi là ba mươi đô la mỗi tháng."},{"en":"She renewed her library membership last week.","vi":"Tuần trước cô ấy đã gia hạn thẻ thành viên thư viện."},{"en":"Membership in the club is open to anyone over eighteen.","vi":"Bất kỳ ai trên mười tám tuổi đều có thể trở thành thành viên câu lạc bộ."}]','[{"phrase":"gym membership"},{"phrase":"membership fee"},{"phrase":"membership card"}]',NULL,'/ˈmembərʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mem/membe/membership__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2233,'ngsl-5-09',22,'bread','bánh mì','noun','[{"en":"I buy fresh bread from the bakery every morning.","vi":"Sáng nào tôi cũng mua bánh mì tươi ở tiệm bánh."},{"en":"Could you pass me a slice of bread, please?","vi":"Bạn đưa giúp tôi một lát bánh mì được không?"},{"en":"My grandmother used to bake bread at home.","vi":"Bà tôi từng tự nướng bánh mì ở nhà."}]','[{"phrase":"fresh bread"},{"phrase":"slice of bread"},{"phrase":"loaf of bread"},{"phrase":"bake bread"}]','không đếm được: a slice/loaf of bread','/bred/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bre/bread/bread__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2234,'ngsl-5-09',23,'blind','mù; không nhận ra','adjective','[{"en":"The blind man crossed the street with his guide dog.","vi":"Người đàn ông khiếm thị băng qua đường cùng chú chó dẫn đường."},{"en":"My grandfather is blind in one eye.","vi":"Ông tôi bị mù một bên mắt."},{"en":"She was blind to her son''s faults.","vi":"Bà ấy không nhận ra lỗi lầm của con trai mình."}]','[{"phrase":"go blind"},{"phrase":"blind in one eye"},{"phrase":"blind to"}]','blind (n): rèm cửa sổ','/blaɪnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bli/blind/blind__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2235,'ngsl-5-09',24,'pure','nguyên chất, tinh khiết; hoàn toàn','adjective','[{"en":"This sweater is made of pure wool.","vi":"Chiếc áo len này làm từ len nguyên chất."},{"en":"The water from the mountain spring is clean and pure.","vi":"Nước từ suối trên núi sạch và tinh khiết."},{"en":"We met again at the airport by pure chance.","vi":"Chúng tôi gặp lại nhau ở sân bay hoàn toàn tình cờ."}]','[{"phrase":"pure water"},{"phrase":"pure gold"},{"phrase":"pure chance"},{"phrase":"pure luck"}]',NULL,'/pjʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/pure_/pure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2236,'ngsl-5-09',25,'bloody','chảy máu, dính máu; (Anh, khẩu ngữ) chết tiệt','adjective','[{"en":"He got a bloody nose playing football at school.","vi":"Cậu ấy bị chảy máu mũi khi chơi bóng đá ở trường."},{"en":"The nurse cleaned the bloody cut on her knee.","vi":"Y tá lau sạch vết cắt đang chảy máu trên đầu gối cô ấy."},{"en":"This bloody printer has stopped working again!","vi":"Cái máy in chết tiệt này lại hỏng nữa rồi!"}]','[{"phrase":"bloody nose"},{"phrase":"bloody battle"}]','Nghĩa ''chết tiệt'' là tiếng lóng Anh, khá thô – nên tránh dùng','/ˈblʌdiː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2237,'ngsl-5-09',26,'ally','đồng minh; người ủng hộ','noun','[{"en":"She has always been my closest ally at work.","vi":"Cô ấy luôn là đồng minh thân thiết nhất của tôi ở chỗ làm."},{"en":"The two countries have been allies for many years.","vi":"Hai nước đã là đồng minh của nhau trong nhiều năm."},{"en":"Try to find an ally before you share your idea at the meeting.","vi":"Hãy tìm một người ủng hộ trước khi trình bày ý tưởng trong cuộc họp."}]','[{"phrase":"close ally"},{"phrase":"key ally"},{"phrase":"find an ally"}]',NULL,'/ˈælaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/ally_/ally__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2238,'ngsl-5-09',27,'quantity','số lượng; lượng','noun','[{"en":"The shop sells rice in large quantities.","vi":"Cửa hàng bán gạo với số lượng lớn."},{"en":"In my opinion, quality is more important than quantity.","vi":"Theo tôi, chất lượng quan trọng hơn số lượng."},{"en":"Add a small quantity of salt to the soup.","vi":"Cho một lượng muối nhỏ vào súp."}]','[{"phrase":"in large quantities"},{"phrase":"small quantity"},{"phrase":"quality and quantity"}]',NULL,'/ˈkwɑːntəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quant/quantity__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2239,'ngsl-5-09',28,'bend','uốn cong; cúi xuống','verb','[{"en":"Bend your knees when you lift heavy boxes.","vi":"Hãy gập đầu gối khi nhấc những thùng hàng nặng."},{"en":"She bent down to pick up the coins.","vi":"Cô ấy cúi xuống nhặt những đồng xu."},{"en":"Don''t bend the photos, or they will get damaged.","vi":"Đừng làm cong mấy tấm ảnh, kẻo chúng bị hỏng."}]','[{"phrase":"bend down"},{"phrase":"bend your knees"},{"phrase":"bend over"},{"phrase":"bend the rules"}]','bend – bent – bent','/bend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/bend_/bend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2240,'ngsl-5-09',29,'mature','trưởng thành; chín chắn','adjective','[{"en":"She is very mature for her age.","vi":"Cô bé rất chín chắn so với tuổi."},{"en":"It wasn''t very mature of you to shout at him.","vi":"Bạn hét vào mặt anh ấy như vậy là không chín chắn lắm."},{"en":"Mature trees provide shade in the park during summer.","vi":"Những cây trưởng thành tạo bóng mát trong công viên vào mùa hè."}]','[{"phrase":"mature for her age"},{"phrase":"mature attitude"},{"phrase":"emotionally mature"}]',NULL,'/məˈtʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/matur/mature__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2241,'ngsl-5-09',30,'briefly','ngắn gọn; trong chốc lát','adverb','[{"en":"Could you briefly explain the plan to the new staff?","vi":"Bạn có thể giải thích ngắn gọn kế hoạch cho nhân viên mới không?"},{"en":"He stopped briefly to talk to a neighbor.","vi":"Anh ấy dừng lại một lát để nói chuyện với hàng xóm."},{"en":"We met briefly at a friend''s wedding last year.","vi":"Năm ngoái chúng tôi đã gặp nhau thoáng qua ở đám cưới của một người bạn."}]','[{"phrase":"briefly explain"},{"phrase":"briefly describe"},{"phrase":"pause briefly"}]',NULL,'/ˈbriːfli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brief/briefly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2242,'ngsl-5-10',1,'alarm','đồng hồ báo thức; chuông báo động; sự lo lắng','noun','[{"en":"I set my alarm for six o''clock every morning.","vi":"Tôi đặt báo thức lúc sáu giờ mỗi sáng."},{"en":"The fire alarm went off during our English class.","vi":"Chuông báo cháy reo lên trong giờ học tiếng Anh của chúng tôi."},{"en":"Her sudden weight loss caused alarm in her family.","vi":"Việc cô ấy sụt cân đột ngột khiến gia đình lo lắng."}]','[{"phrase":"set the alarm"},{"phrase":"fire alarm"},{"phrase":"alarm clock"},{"phrase":"cause alarm"}]',NULL,'/əˈlɑːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ala/alarm/alarm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2243,'ngsl-5-10',2,'disturb','làm phiền; quấy rầy; làm xáo trộn','verb','[{"en":"Please don''t disturb me while I''m working.","vi":"Làm ơn đừng làm phiền tôi khi tôi đang làm việc."},{"en":"Sorry to disturb you, but can I ask a quick question?","vi":"Xin lỗi đã làm phiền, nhưng tôi hỏi nhanh một câu được không?"},{"en":"The noise from the street disturbed our sleep all night.","vi":"Tiếng ồn ngoài đường quấy rầy giấc ngủ của chúng tôi suốt đêm."}]','[{"phrase":"sorry to disturb you"},{"phrase":"do not disturb"},{"phrase":"disturb someone''s sleep"}]',NULL,'/dɪˈstɜːrb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/distu/disturb__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2244,'ngsl-5-10',3,'sustain','duy trì; chịu (thương tích, thiệt hại)','verb','[{"en":"It is hard to sustain this level of growth for long.","vi":"Rất khó để duy trì mức tăng trưởng này trong thời gian dài."},{"en":"We need more money to sustain the project next year.","vi":"Chúng tôi cần thêm tiền để duy trì dự án vào năm sau."},{"en":"The driver sustained serious injuries in the accident.","vi":"Người lái xe bị thương nặng trong vụ tai nạn."}]','[{"phrase":"sustain growth"},{"phrase":"sustain injuries"},{"phrase":"sustain damage"},{"phrase":"sustain interest"}]',NULL,'/səˈsteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/susta/sustain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2245,'ngsl-5-10',4,'flood','lũ lụt; sự tràn ngập, dòng ồ ạt','noun','[{"en":"The flood destroyed hundreds of homes in the valley.","vi":"Trận lũ đã phá hủy hàng trăm ngôi nhà trong thung lũng."},{"en":"Many farmers lost their crops in last year''s floods.","vi":"Nhiều nông dân mất mùa vì những trận lũ năm ngoái."},{"en":"After the article appeared, the office received a flood of emails.","vi":"Sau khi bài báo được đăng, văn phòng nhận được vô số email."}]','[{"phrase":"flood warning"},{"phrase":"flash flood"},{"phrase":"a flood of"},{"phrase":"flood damage"}]','cũng là động từ: làm ngập, tràn vào','/flʌd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/flood/flood__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2246,'ngsl-5-10',5,'poverty','sự nghèo đói; cảnh nghèo khó','noun','[{"en":"Millions of children around the world still live in poverty.","vi":"Hàng triệu trẻ em trên thế giới vẫn sống trong cảnh nghèo đói."},{"en":"He grew up in poverty but worked hard to succeed.","vi":"Anh ấy lớn lên trong nghèo khó nhưng đã làm việc chăm chỉ để thành công."},{"en":"Education is one of the best ways out of poverty.","vi":"Giáo dục là một trong những con đường tốt nhất để thoát nghèo."}]','[{"phrase":"live in poverty"},{"phrase":"extreme poverty"},{"phrase":"poverty line"},{"phrase":"reduce poverty"}]','không đếm được','/ˈpɑːvərti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pov/pover/poverty__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2247,'ngsl-5-10',6,'crazy','điên; điên rồ; mê (cái gì)','adjective','[{"en":"It''s crazy to drive that fast in the rain.","vi":"Lái xe nhanh như vậy dưới trời mưa thật là điên rồ."},{"en":"The noise from next door is driving me crazy.","vi":"Tiếng ồn từ nhà bên cạnh làm tôi phát điên."},{"en":"My little brother is crazy about football.","vi":"Em trai tôi mê bóng đá lắm."}]','[{"phrase":"go crazy"},{"phrase":"drive someone crazy"},{"phrase":"crazy about"},{"phrase":"crazy idea"}]',NULL,'/ˈkreɪzi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/crazy/crazy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2248,'ngsl-5-10',7,'cite','trích dẫn; viện dẫn, nêu ra','verb','[{"en":"You must cite all your sources at the end of the essay.","vi":"Bạn phải trích dẫn tất cả các nguồn ở cuối bài luận."},{"en":"The article cites a study from a well-known university.","vi":"Bài báo trích dẫn một nghiên cứu của một trường đại học nổi tiếng."},{"en":"She cited family reasons for leaving her job.","vi":"Cô ấy viện lý do gia đình khi nghỉ việc."}]','[{"phrase":"cite a source"},{"phrase":"cite an example"},{"phrase":"cite reasons"},{"phrase":"widely cited"}]',NULL,'/saɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/cite_/cite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2249,'ngsl-5-10',8,'newly','mới, vừa mới','adverb','[{"en":"The newly built library opens to the public next week.","vi":"Thư viện mới xây sẽ mở cửa cho công chúng vào tuần tới."},{"en":"We met a newly married couple on our trip.","vi":"Chúng tôi gặp một cặp vợ chồng mới cưới trong chuyến đi."},{"en":"Newly arrived students can get help from the student center.","vi":"Sinh viên mới đến có thể nhờ trung tâm sinh viên hỗ trợ."}]','[{"phrase":"newly built"},{"phrase":"newly married"},{"phrase":"newly arrived"},{"phrase":"newly elected"}]',NULL,'/ˈnuːli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/newly/newly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2250,'ngsl-5-10',9,'parallel','song song; tương tự','adjective','[{"en":"Draw two parallel lines on your paper.","vi":"Hãy vẽ hai đường thẳng song song trên giấy."},{"en":"The road runs parallel to the river for several miles.","vi":"Con đường chạy song song với dòng sông suốt vài dặm."},{"en":"The two cities went through parallel changes during the same period.","vi":"Hai thành phố đã trải qua những thay đổi tương tự trong cùng thời kỳ."}]','[{"phrase":"parallel lines"},{"phrase":"parallel to"},{"phrase":"run parallel"}]',NULL,'/ˈpærəlel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/paral/parallel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2251,'ngsl-5-10',10,'gender','giới tính; giới','noun','[{"en":"Everyone should get equal pay regardless of gender.","vi":"Mọi người nên được trả lương ngang nhau bất kể giới tính."},{"en":"The form asks for your name, age and gender.","vi":"Mẫu đơn hỏi tên, tuổi và giới tính của bạn."},{"en":"Gender equality is an important goal for many companies.","vi":"Bình đẳng giới là mục tiêu quan trọng của nhiều công ty."}]','[{"phrase":"gender equality"},{"phrase":"gender gap"},{"phrase":"regardless of gender"},{"phrase":"gender roles"}]',NULL,'/ˈdʒendər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gende/gender__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2252,'ngsl-5-10',11,'sponsor','nhà tài trợ','noun','[{"en":"The team is looking for a new sponsor for next season.","vi":"Đội bóng đang tìm nhà tài trợ mới cho mùa giải tới."},{"en":"A local bank is the main sponsor of the festival.","vi":"Một ngân hàng địa phương là nhà tài trợ chính của lễ hội."},{"en":"Our school found sponsors to pay for the concert.","vi":"Trường chúng tôi đã tìm được nhà tài trợ để chi trả cho buổi hòa nhạc."}]','[{"phrase":"main sponsor"},{"phrase":"corporate sponsor"},{"phrase":"find a sponsor"},{"phrase":"official sponsor"}]','cũng là động từ: sponsor an event (tài trợ một sự kiện)','/ˈspɑːnsər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spo/spons/sponsor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2253,'ngsl-5-10',12,'boot','giày ống, bốt, ủng; cốp xe','noun','[{"en":"Wear your boots because the path will be muddy.","vi":"Hãy mang ủng vì con đường sẽ lầy lội."},{"en":"She bought a pair of leather boots for winter.","vi":"Cô ấy đã mua một đôi bốt da cho mùa đông."},{"en":"Can you put the suitcases in the boot, please?","vi":"Bạn để mấy cái vali vào cốp xe giúp tôi nhé?"}]','[{"phrase":"a pair of boots"},{"phrase":"leather boots"},{"phrase":"hiking boots"},{"phrase":"car boot"}]','cốp xe: Anh boot · Mỹ trunk','/buːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/boot_/boot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2254,'ngsl-5-10',13,'accurate','chính xác','adjective','[{"en":"The weather forecast was surprisingly accurate this week.","vi":"Dự báo thời tiết tuần này chính xác đến bất ngờ."},{"en":"Please make sure all the information on the form is accurate.","vi":"Hãy đảm bảo mọi thông tin trong mẫu đơn đều chính xác."},{"en":"It is difficult to give an accurate number right now.","vi":"Hiện giờ rất khó đưa ra một con số chính xác."}]','[{"phrase":"accurate information"},{"phrase":"highly accurate"},{"phrase":"accurate description"},{"phrase":"fairly accurate"}]',NULL,'/ˈækjərət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accur/accurate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2255,'ngsl-5-10',14,'dealer','đại lý; người buôn bán','noun','[{"en":"We bought our car from a dealer near the city center.","vi":"Chúng tôi mua xe ở một đại lý gần trung tâm thành phố."},{"en":"My uncle is an antique dealer in a small town.","vi":"Chú tôi là người buôn đồ cổ ở một thị trấn nhỏ."},{"en":"The dealer offered us a good price for our old car.","vi":"Đại lý trả cho chúng tôi một giá tốt để mua lại chiếc xe cũ."}]','[{"phrase":"car dealer"},{"phrase":"antique dealer"},{"phrase":"art dealer"}]',NULL,'/ˈdiːlər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/deale/dealer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2256,'ngsl-5-10',15,'button','nút bấm; cúc áo','noun','[{"en":"Press the green button to start the machine.","vi":"Nhấn nút màu xanh lá để khởi động máy."},{"en":"Click the button below to download the file.","vi":"Nhấp vào nút bên dưới để tải tệp xuống."},{"en":"One of the buttons on my shirt fell off.","vi":"Một chiếc cúc trên áo sơ mi của tôi bị bung ra."}]','[{"phrase":"press a button"},{"phrase":"click the button"},{"phrase":"push a button"},{"phrase":"sew on a button"}]',NULL,'/ˈbʌtn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/but/butto/button__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2257,'ngsl-5-10',16,'burden','gánh nặng','noun','[{"en":"I don''t want to be a burden to my children.","vi":"Tôi không muốn trở thành gánh nặng cho con cái."},{"en":"The new tax will put a heavy burden on small businesses.","vi":"Thuế mới sẽ đặt gánh nặng lớn lên các doanh nghiệp nhỏ."},{"en":"She carried the burden of her family''s debts for years.","vi":"Cô ấy đã gánh khoản nợ của gia đình suốt nhiều năm."}]','[{"phrase":"heavy burden"},{"phrase":"a burden on"},{"phrase":"financial burden"},{"phrase":"reduce the burden"}]',NULL,'/ˈbɜːrdn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/burde/burden__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2258,'ngsl-5-10',17,'desert','sa mạc','noun','[{"en":"Very little rain falls in the desert.","vi":"Ở sa mạc rất ít khi có mưa."},{"en":"We rode camels across the desert at sunset.","vi":"Chúng tôi cưỡi lạc đà băng qua sa mạc lúc hoàng hôn."},{"en":"It gets surprisingly cold in the desert at night.","vi":"Ban đêm ở sa mạc trời lạnh đến bất ngờ."}]','[{"phrase":"in the desert"},{"phrase":"across the desert"},{"phrase":"desert island"}]','desert (sa mạc) ≠ dessert (món tráng miệng)','/ˈdezərt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/deser/desert__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2259,'ngsl-5-10',18,'mate','bạn, bạn bè (thân mật); bạn tình (động vật)','noun','[{"en":"He went on vacation with his best mate from school.","vi":"Anh ấy đi nghỉ với người bạn thân nhất thời đi học."},{"en":"Thanks, mate, I really appreciate your help.","vi":"Cảm ơn nhé bạn, mình thật sự biết ơn sự giúp đỡ của bạn."},{"en":"Male birds sing loudly to attract a mate.","vi":"Chim trống hót to để thu hút bạn tình."}]','[{"phrase":"best mate"},{"phrase":"old mate"},{"phrase":"attract a mate"},{"phrase":"find a mate"}]','nghĩa ''bạn'' là thân mật, phổ biến ở Anh và Úc','/meɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/mate_/mate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2260,'ngsl-5-10',19,'occasionally','thỉnh thoảng, đôi khi','adverb','[{"en":"I occasionally work from home on Fridays.","vi":"Thỉnh thoảng tôi làm việc ở nhà vào thứ Sáu."},{"en":"We still see each other occasionally, but not very often.","vi":"Chúng tôi vẫn thỉnh thoảng gặp nhau, nhưng không thường xuyên lắm."},{"en":"My father only occasionally drinks coffee after dinner.","vi":"Bố tôi chỉ thỉnh thoảng uống cà phê sau bữa tối."}]','[{"phrase":"only occasionally"},{"phrase":"very occasionally"},{"phrase":"occasionally visit"}]',NULL,'/əˈkeɪʒnəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occas/occasionally__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2261,'ngsl-5-10',20,'shareholder','cổ đông','noun','[{"en":"The company made a big profit for its shareholders this year.","vi":"Năm nay công ty đã mang lại lợi nhuận lớn cho các cổ đông."},{"en":"Shareholders will vote on the new plan next month.","vi":"Các cổ đông sẽ bỏ phiếu về kế hoạch mới vào tháng tới."},{"en":"She became the largest shareholder after buying more shares.","vi":"Cô ấy trở thành cổ đông lớn nhất sau khi mua thêm cổ phần."}]','[{"phrase":"major shareholder"},{"phrase":"largest shareholder"},{"phrase":"shareholder value"}]',NULL,'/ˈʃerhəʊldər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/share/shareholder__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2262,'ngsl-5-10',21,'bowl','cái bát, cái tô','noun','[{"en":"I usually have a bowl of cereal for breakfast.","vi":"Tôi thường ăn một bát ngũ cốc vào bữa sáng."},{"en":"Put the eggs and sugar in a large bowl.","vi":"Cho trứng và đường vào một cái tô lớn."},{"en":"Don''t forget to fill the dog''s water bowl.","vi":"Đừng quên đổ đầy bát nước của con chó."}]','[{"phrase":"a bowl of"},{"phrase":"soup bowl"},{"phrase":"mixing bowl"},{"phrase":"salad bowl"}]',NULL,'/bəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bow/bowl_/bowl__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2263,'ngsl-5-10',22,'discovery','sự khám phá; phát hiện','noun','[{"en":"Scientists made an important discovery about the ocean floor.","vi":"Các nhà khoa học đã có một phát hiện quan trọng về đáy đại dương."},{"en":"The discovery of old coins surprised everyone in the village.","vi":"Việc phát hiện những đồng xu cổ khiến cả làng ngạc nhiên."},{"en":"The children were excited about their discovery in the garden.","vi":"Bọn trẻ rất hào hứng với thứ chúng phát hiện ra trong vườn."}]','[{"phrase":"make a discovery"},{"phrase":"important discovery"},{"phrase":"scientific discovery"}]',NULL,'/dɪˈskʌvəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disco/discovery__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2264,'ngsl-5-10',23,'resistance','sự phản đối, kháng cự; sức đề kháng','noun','[{"en":"The plan met strong resistance from local residents.","vi":"Kế hoạch vấp phải sự phản đối mạnh mẽ từ người dân địa phương."},{"en":"People often show resistance to change at work.","vi":"Ở nơi làm việc, người ta thường chống lại sự thay đổi."},{"en":"Eating well can improve your body''s resistance to disease.","vi":"Ăn uống tốt có thể tăng sức đề kháng của cơ thể trước bệnh tật."}]','[{"phrase":"strong resistance"},{"phrase":"resistance to change"},{"phrase":"meet resistance"}]',NULL,'/rɪˈzɪstəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resis/resistance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2265,'ngsl-5-10',24,'bath','sự tắm (trong bồn); bồn tắm','noun','[{"en":"I like to take a hot bath after a long day.","vi":"Tôi thích tắm nước nóng sau một ngày dài."},{"en":"It''s time to give the baby a bath.","vi":"Đến giờ tắm cho em bé rồi."},{"en":"The bath in our hotel room was very small.","vi":"Bồn tắm trong phòng khách sạn của chúng tôi rất nhỏ."}]','[{"phrase":"take a bath"},{"phrase":"have a bath"},{"phrase":"hot bath"},{"phrase":"run a bath"}]','bồn tắm: Anh bath · Mỹ bathtub','/bæθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bat/bath_/bath__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2266,'ngsl-5-10',25,'frequency','tần suất; tần số','noun','[{"en":"The frequency of heavy storms has increased in recent years.","vi":"Tần suất các cơn bão lớn đã tăng lên trong những năm gần đây."},{"en":"The app lets you choose the frequency of notifications.","vi":"Ứng dụng cho phép bạn chọn tần suất nhận thông báo."},{"en":"Dogs can hear sounds at a much higher frequency than humans.","vi":"Chó có thể nghe được âm thanh ở tần số cao hơn nhiều so với con người."}]','[{"phrase":"high frequency"},{"phrase":"low frequency"},{"phrase":"radio frequency"},{"phrase":"increase in frequency"}]',NULL,'/ˈfriːkwənsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/frequ/frequency__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2267,'ngsl-5-10',26,'criticize','chỉ trích; phê bình, chê','verb','[{"en":"The new movie was heavily criticized for being too long.","vi":"Bộ phim mới bị chỉ trích nặng nề vì quá dài."},{"en":"My boss criticized me for missing the deadline.","vi":"Sếp phê bình tôi vì trễ hạn."},{"en":"Please don''t criticize my cooking in front of our guests.","vi":"Làm ơn đừng chê món tôi nấu trước mặt khách."}]','[{"phrase":"criticize someone for"},{"phrase":"heavily criticized"},{"phrase":"widely criticized"},{"phrase":"strongly criticize"}]','Anh: criticise · Mỹ: criticize','/ˈkrɪtɪsaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cri/criti/criticize__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2268,'ngsl-5-10',27,'tap','gõ nhẹ, vỗ nhẹ; chạm (màn hình)','verb','[{"en":"Someone tapped me on the shoulder at the bus stop.","vi":"Có người vỗ nhẹ vào vai tôi ở trạm xe buýt."},{"en":"She tapped on the window to get my attention.","vi":"Cô ấy gõ nhẹ vào cửa sổ để thu hút sự chú ý của tôi."},{"en":"Tap the icon to open the app.","vi":"Chạm vào biểu tượng để mở ứng dụng."}]','[{"phrase":"tap someone on the shoulder"},{"phrase":"tap the screen"},{"phrase":"tap your foot"},{"phrase":"tap on the door"}]','tap – tapped; danh từ: vòi nước (Mỹ: faucet)','/tæp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tap/tap__/tap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2269,'ngsl-5-10',28,'philosophy','triết học; triết lý','noun','[{"en":"She studied philosophy at university before becoming a teacher.","vi":"Cô ấy học triết học ở đại học trước khi trở thành giáo viên."},{"en":"My philosophy is to enjoy every day as it comes.","vi":"Triết lý của tôi là tận hưởng từng ngày trôi qua."},{"en":"The company''s philosophy is to put customers first.","vi":"Triết lý của công ty là đặt khách hàng lên hàng đầu."}]','[{"phrase":"study philosophy"},{"phrase":"philosophy of life"},{"phrase":"business philosophy"}]',NULL,'/fəˈlɑːsəfi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phi/philo/philosophy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2270,'ngsl-5-10',29,'lip','môi','noun','[{"en":"Her lips were dry from the cold wind.","vi":"Môi cô ấy bị khô vì gió lạnh."},{"en":"He bit his lip to stop himself from laughing.","vi":"Anh ấy cắn môi để nhịn cười."},{"en":"She put a finger to her lips to tell us to be quiet.","vi":"Cô ấy đặt ngón tay lên môi để bảo chúng tôi im lặng."}]','[{"phrase":"bite your lip"},{"phrase":"upper lip"},{"phrase":"lower lip"},{"phrase":"dry lips"}]',NULL,'/lɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lip/lip__/lip__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2271,'ngsl-5-10',30,'attribute','cho là do; quy cho (là của ai)','verb','[{"en":"She attributes her success to years of hard work.","vi":"Cô ấy cho rằng thành công của mình là nhờ nhiều năm làm việc chăm chỉ."},{"en":"The delay was attributed to bad weather.","vi":"Sự chậm trễ được cho là do thời tiết xấu."},{"en":"This painting is often attributed to a famous Italian artist.","vi":"Bức tranh này thường được cho là của một họa sĩ nổi tiếng người Ý."}]','[{"phrase":"attribute something to"},{"phrase":"be attributed to"},{"phrase":"largely attributed to"}]','attribute to sth · danh từ: thuộc tính, phẩm chất','/əˈtrɪbjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attri/attribute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2272,'ngsl-5-11',1,'apologize','xin lỗi','verb','[{"en":"I apologized to my sister for forgetting her birthday.","vi":"Tôi đã xin lỗi em gái vì quên sinh nhật của em ấy."},{"en":"You should apologize for being so rude to him.","vi":"Bạn nên xin lỗi vì đã quá thô lỗ với anh ấy."},{"en":"We apologize for the delay and thank you for waiting.","vi":"Chúng tôi xin lỗi vì sự chậm trễ và cảm ơn bạn đã chờ đợi."}]','[{"phrase":"apologize for the delay"},{"phrase":"apologize to someone"},{"phrase":"sincerely apologize"}]','apologize to sb for sth · Anh: apologise','/əˈpɑːlədʒaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/apo/apolo/apologize__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2273,'ngsl-5-11',2,'approval','sự chấp thuận; sự tán thành','noun','[{"en":"The plan still needs approval from the manager.","vi":"Kế hoạch vẫn cần sự chấp thuận của người quản lý."},{"en":"We finally got approval to build a new garage.","vi":"Cuối cùng chúng tôi cũng được chấp thuận xây một nhà để xe mới."},{"en":"As a boy, he always wanted his father''s approval.","vi":"Hồi nhỏ, cậu ấy luôn mong nhận được sự tán thành của bố."}]','[{"phrase":"need approval"},{"phrase":"get approval"},{"phrase":"final approval"}]',NULL,'/əˈpruːvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approval__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2274,'ngsl-5-11',3,'grab','chộp lấy; túm lấy; ăn/uống vội','verb','[{"en":"She grabbed her bag and ran out the door.","vi":"Cô ấy chộp lấy túi xách và chạy ra khỏi cửa."},{"en":"He grabbed my arm to stop me from falling.","vi":"Anh ấy túm lấy tay tôi để tôi không bị ngã."},{"en":"Let''s grab a coffee before the meeting starts.","vi":"Mình tranh thủ uống cà phê trước khi cuộc họp bắt đầu nhé."}]','[{"phrase":"grab a coffee"},{"phrase":"grab a bite"},{"phrase":"grab someone''s arm"},{"phrase":"grab attention"}]',NULL,'/ɡræb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grab_/grab__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2275,'ngsl-5-11',4,'entitle','cho quyền; đặt tựa đề','verb','[{"en":"This ticket entitles you to one free drink.","vi":"Vé này cho bạn quyền nhận một đồ uống miễn phí."},{"en":"All workers are entitled to paid holidays.","vi":"Tất cả công nhân đều có quyền được nghỉ lễ có lương."},{"en":"Her first novel was entitled ''Summer by the Sea''.","vi":"Cuốn tiểu thuyết đầu tay của cô ấy có tựa đề ''Summer by the Sea''."}]','[{"phrase":"be entitled to"},{"phrase":"entitle someone to something"},{"phrase":"fully entitled"}]','be entitled to + N/V: có quyền (làm/nhận) gì','/ɪnˈtaɪtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entit/entitle__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2276,'ngsl-5-11',5,'lend','cho mượn; cho vay','verb','[{"en":"Could you lend me your pen for a minute?","vi":"Bạn có thể cho mình mượn cây bút một lát không?"},{"en":"My brother lent me some money to buy a car.","vi":"Anh trai đã cho tôi vay một ít tiền để mua xe."},{"en":"The bank refused to lend us any more money.","vi":"Ngân hàng từ chối cho chúng tôi vay thêm tiền."}]','[{"phrase":"lend money"},{"phrase":"lend a hand"},{"phrase":"lend someone something"}]','lend – lent – lent · lend (cho mượn) ≠ borrow (mượn)','/lend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/len/lend_/lend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2277,'ngsl-5-11',6,'involvement','sự tham gia; sự dính líu','noun','[{"en":"Parents'' involvement in school activities helps children learn better.","vi":"Sự tham gia của phụ huynh vào các hoạt động ở trường giúp trẻ học tốt hơn."},{"en":"Thank you for your involvement in this project.","vi":"Cảm ơn bạn đã tham gia vào dự án này."},{"en":"The manager denied any involvement in the decision.","vi":"Người quản lý phủ nhận mọi dính líu đến quyết định đó."}]','[{"phrase":"involvement in"},{"phrase":"active involvement"},{"phrase":"deny any involvement"},{"phrase":"parental involvement"}]',NULL,'/ɪnˈvɑːlvmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invol/involvement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2278,'ngsl-5-11',7,'exposure','sự tiếp xúc; sự xuất hiện trước công chúng','noun','[{"en":"Too much exposure to the sun can damage your skin.","vi":"Tiếp xúc quá nhiều với ánh nắng có thể làm hại da của bạn."},{"en":"Living abroad gave her daily exposure to English.","vi":"Sống ở nước ngoài giúp cô ấy được tiếp xúc với tiếng Anh hằng ngày."},{"en":"The small band got a lot of exposure on social media.","vi":"Ban nhạc nhỏ được xuất hiện rất nhiều trên mạng xã hội."}]','[{"phrase":"exposure to"},{"phrase":"sun exposure"},{"phrase":"media exposure"},{"phrase":"long-term exposure"}]',NULL,'/ɪkˈspəʊʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expos/exposure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2279,'ngsl-5-11',8,'conventional','thông thường; truyền thống','adjective','[{"en":"Electric cars are much quieter than conventional cars.","vi":"Xe điện chạy êm hơn nhiều so với xe thông thường."},{"en":"My parents have very conventional ideas about marriage.","vi":"Bố mẹ tôi có những quan niệm rất truyền thống về hôn nhân."},{"en":"Our teacher does not like conventional teaching methods.","vi":"Giáo viên của chúng tôi không thích các phương pháp giảng dạy truyền thống."}]','[{"phrase":"conventional methods"},{"phrase":"conventional wisdom"},{"phrase":"conventional medicine"}]',NULL,'/kənˈvenʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconventional__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2280,'ngsl-5-11',9,'digital','kỹ thuật số; số','adjective','[{"en":"My grandfather finally bought a digital camera last year.","vi":"Năm ngoái cuối cùng ông tôi cũng mua một chiếc máy ảnh kỹ thuật số."},{"en":"The library offers a large collection of digital books.","vi":"Thư viện có một bộ sưu tập lớn sách điện tử."},{"en":"Children today are growing up in a digital world.","vi":"Trẻ em ngày nay đang lớn lên trong một thế giới số."}]','[{"phrase":"digital camera"},{"phrase":"digital technology"},{"phrase":"digital age"},{"phrase":"digital world"}]',NULL,'/ˈdɪdʒɪtl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dig/digit/digital__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2281,'ngsl-5-11',10,'translate','dịch; chuyển thành','verb','[{"en":"Can you translate this letter into English for me?","vi":"Bạn có thể dịch bức thư này sang tiếng Anh giúp tôi không?"},{"en":"Her books have been translated into twenty languages.","vi":"Sách của cô ấy đã được dịch ra hai mươi thứ tiếng."},{"en":"Good ideas do not always translate into success.","vi":"Ý tưởng hay không phải lúc nào cũng mang lại thành công."}]','[{"phrase":"translate into"},{"phrase":"translate from"},{"phrase":"translate a book"},{"phrase":"roughly translate"}]',NULL,'/trænzˈleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/translate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2282,'ngsl-5-11',11,'edit','chỉnh sửa; biên tập','verb','[{"en":"I need to edit this video before I post it.","vi":"Tôi cần chỉnh sửa video này trước khi đăng lên."},{"en":"She edits a small magazine about gardening.","vi":"Cô ấy biên tập một tạp chí nhỏ về làm vườn."},{"en":"Could you edit my essay and check the grammar?","vi":"Bạn có thể chỉnh sửa bài luận và kiểm tra ngữ pháp giúp tôi không?"}]','[{"phrase":"edit a video"},{"phrase":"edit photos"},{"phrase":"edit a book"}]',NULL,'/ˈedɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/edit_/edit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2283,'ngsl-5-11',12,'formation','sự hình thành; đội hình','noun','[{"en":"The teacher explained the formation of clouds in simple words.","vi":"Giáo viên giải thích sự hình thành của mây bằng những từ ngữ đơn giản."},{"en":"Cold air can lead to the formation of ice on roads.","vi":"Không khí lạnh có thể khiến băng hình thành trên đường."},{"en":"The birds flew south in a V formation.","vi":"Đàn chim bay về phía nam theo đội hình chữ V."}]','[{"phrase":"the formation of"},{"phrase":"in formation"},{"phrase":"rock formation"}]',NULL,'/fɔːrˈmeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/formation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2284,'ngsl-5-11',13,'deposit','tiền đặt cọc; tiền gửi (ngân hàng)','noun','[{"en":"We paid a deposit of two hundred dollars for the apartment.","vi":"Chúng tôi đã trả hai trăm đô la tiền đặt cọc cho căn hộ."},{"en":"You will get your deposit back when you return the bike.","vi":"Bạn sẽ được nhận lại tiền cọc khi trả xe đạp."},{"en":"She made a deposit at the bank this morning.","vi":"Sáng nay cô ấy đã gửi tiền vào ngân hàng."}]','[{"phrase":"pay a deposit"},{"phrase":"make a deposit"},{"phrase":"security deposit"}]',NULL,'/dɪˈpɑːzɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depos/deposit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2285,'ngsl-5-11',14,'pleasant','dễ chịu; vui vẻ; dễ mến','adjective','[{"en":"We had a pleasant evening with our neighbors.","vi":"Chúng tôi đã có một buổi tối vui vẻ với hàng xóm."},{"en":"The weather was warm and pleasant all week.","vi":"Thời tiết ấm áp và dễ chịu suốt cả tuần."},{"en":"The woman at the front desk was very pleasant.","vi":"Người phụ nữ ở quầy lễ tân rất dễ mến."}]','[{"phrase":"pleasant surprise"},{"phrase":"pleasant evening"},{"phrase":"pleasant weather"}]',NULL,'/ˈpleznt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/ple/pleas/pleasant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2286,'ngsl-5-11',15,'overseas','ở nước ngoài; ra nước ngoài','adverb','[{"en":"My cousin has been working overseas for five years.","vi":"Anh họ tôi đã làm việc ở nước ngoài được năm năm."},{"en":"Many students want to study overseas after high school.","vi":"Nhiều học sinh muốn đi học ở nước ngoài sau khi học xong cấp ba."},{"en":"The company sells most of its products overseas.","vi":"Công ty bán phần lớn sản phẩm của mình ra nước ngoài."}]','[{"phrase":"work overseas"},{"phrase":"study overseas"},{"phrase":"travel overseas"},{"phrase":"overseas students"}]','cũng là tính từ: overseas students = sinh viên nước ngoài','/ˌəʊvərˈsiːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overs/overseas__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2287,'ngsl-5-11',16,'advocate','ủng hộ; chủ trương','verb','[{"en":"Many doctors advocate a diet low in sugar.","vi":"Nhiều bác sĩ ủng hộ chế độ ăn ít đường."},{"en":"The group advocates more bike lanes in the city.","vi":"Nhóm này ủng hộ việc có thêm làn đường dành cho xe đạp trong thành phố."},{"en":"Our teacher strongly advocates reading for pleasure every day.","vi":"Giáo viên của chúng tôi rất ủng hộ việc đọc sách để giải trí mỗi ngày."}]','[{"phrase":"strongly advocate"},{"phrase":"advocate the use of"},{"phrase":"advocate change"}]','danh từ: advocate = người ủng hộ; luật sư bào chữa','/ˈædvəkət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advoc/advocate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2288,'ngsl-5-11',17,'establishment','sự thành lập; cơ sở (kinh doanh)','noun','[{"en":"The establishment of the new hospital took three years.","vi":"Việc thành lập bệnh viện mới mất ba năm."},{"en":"Since its establishment, the school has trained thousands of nurses.","vi":"Kể từ khi thành lập, trường đã đào tạo hàng nghìn y tá."},{"en":"This restaurant is one of the oldest establishments in town.","vi":"Nhà hàng này là một trong những cơ sở lâu đời nhất trong thị trấn."}]','[{"phrase":"the establishment of"},{"phrase":"business establishment"},{"phrase":"educational establishment"}]',NULL,'/ɪˈstæblɪʃmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estab/establishment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2289,'ngsl-5-11',18,'summary','bản tóm tắt','noun','[{"en":"Please write a short summary of the article.","vi":"Hãy viết một bản tóm tắt ngắn về bài báo."},{"en":"Here is a summary of what we discussed today.","vi":"Đây là bản tóm tắt những gì chúng ta đã thảo luận hôm nay."},{"en":"In summary, the trip was a great success.","vi":"Tóm lại, chuyến đi rất thành công."}]','[{"phrase":"short summary"},{"phrase":"brief summary"},{"phrase":"in summary"},{"phrase":"summary of"}]',NULL,'/ˈsʌməri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summa/summary__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2290,'ngsl-5-11',19,'rough','thô ráp; phỏng chừng; vất vả','adjective','[{"en":"The skin on his hands was rough from years of work.","vi":"Da tay anh ấy thô ráp sau nhiều năm lao động."},{"en":"Can you give me a rough idea of the cost?","vi":"Bạn có thể cho tôi biết sơ bộ chi phí khoảng bao nhiêu không?"},{"en":"She has had a rough week at work.","vi":"Cô ấy vừa trải qua một tuần làm việc vất vả."}]','[{"phrase":"rough idea"},{"phrase":"rough estimate"},{"phrase":"rough surface"},{"phrase":"rough day"}]',NULL,'/rʌf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/rough/rough__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2291,'ngsl-5-11',20,'pen','bút; bút mực','noun','[{"en":"Do you have a pen I could borrow?","vi":"Bạn có cây bút nào cho mình mượn không?"},{"en":"Please fill in the form with a black pen.","vi":"Vui lòng điền vào mẫu đơn bằng bút mực đen."},{"en":"My pen ran out of ink during the exam.","vi":"Bút của tôi hết mực trong lúc thi."}]','[{"phrase":"black pen"},{"phrase":"ballpoint pen"},{"phrase":"pen and paper"}]',NULL,'/pen/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pen/pen__/pen__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2292,'ngsl-5-11',21,'recovery','sự hồi phục; sự phục hồi','noun','[{"en":"She made a quick recovery after the operation.","vi":"Cô ấy hồi phục nhanh chóng sau ca phẫu thuật."},{"en":"We all wish you a speedy recovery, Grandma.","vi":"Cả nhà chúc bà mau chóng hồi phục ạ."},{"en":"The town''s economy is showing signs of recovery.","vi":"Nền kinh tế của thị trấn đang có dấu hiệu phục hồi."}]','[{"phrase":"make a recovery"},{"phrase":"speedy recovery"},{"phrase":"full recovery"},{"phrase":"economic recovery"}]',NULL,'/rɪˈkʌvəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recov/recovery__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2293,'ngsl-5-11',22,'seal','dán kín; đóng kín; niêm phong','verb','[{"en":"She sealed the envelope and put a stamp on it.","vi":"Cô ấy dán kín phong bì rồi dán tem lên."},{"en":"Keep the cookies in a tightly sealed box.","vi":"Hãy để bánh quy trong hộp được đậy thật kín."},{"en":"Seal the bag well so the food stays fresh.","vi":"Hãy đóng kín túi để thức ăn luôn tươi."}]','[{"phrase":"seal an envelope"},{"phrase":"tightly sealed"},{"phrase":"seal off"}]','danh từ: seal = con hải cẩu; con dấu','/siːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/seal_/seal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2294,'ngsl-5-11',23,'tube','ống; tuýp','noun','[{"en":"I need to buy a new tube of toothpaste.","vi":"Tôi cần mua một tuýp kem đánh răng mới."},{"en":"Water flows through this plastic tube into the tank.","vi":"Nước chảy qua ống nhựa này vào bể."},{"en":"She squeezed the last bit of paint out of the tube.","vi":"Cô ấy nặn chút màu vẽ cuối cùng ra khỏi tuýp."}]','[{"phrase":"tube of toothpaste"},{"phrase":"plastic tube"},{"phrase":"rubber tube"},{"phrase":"test tube"}]',NULL,'/tuːb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tub/tube_/tube__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2295,'ngsl-5-11',24,'tower','tháp; tòa nhà cao tầng','noun','[{"en":"From the top of the tower, you can see the whole city.","vi":"Từ đỉnh tháp, bạn có thể nhìn thấy toàn bộ thành phố."},{"en":"The old clock tower in the square still keeps perfect time.","vi":"Tháp đồng hồ cũ ở quảng trường vẫn chạy rất đúng giờ."},{"en":"Our office is in that tall glass tower downtown.","vi":"Văn phòng của chúng tôi nằm trong tòa nhà kính cao tầng ở trung tâm thành phố."}]','[{"phrase":"clock tower"},{"phrase":"office tower"},{"phrase":"water tower"},{"phrase":"top of the tower"}]',NULL,'/ˈtaʊər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tow/tower/tower__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2296,'ngsl-5-11',25,'characterize','mô tả đặc điểm; là đặc điểm của','verb','[{"en":"The region is characterized by hot summers and cold winters.","vi":"Vùng này có đặc điểm là mùa hè nóng và mùa đông lạnh."},{"en":"His paintings are characterized by bright colors.","vi":"Tranh của anh ấy có đặc điểm là màu sắc tươi sáng."},{"en":"How would you characterize your relationship with your boss?","vi":"Bạn sẽ mô tả mối quan hệ giữa bạn và sếp như thế nào?"}]','[{"phrase":"be characterized by"},{"phrase":"characterize as"},{"phrase":"generally characterized"}]','be characterized by: có đặc điểm là · Anh: characterise','/ˈkærəktəraɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chara/characterize__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2297,'ngsl-5-11',26,'specify','ghi rõ; nêu cụ thể','verb','[{"en":"Please specify your size when you order the shirt.","vi":"Vui lòng ghi rõ cỡ áo khi bạn đặt mua."},{"en":"The rules do not specify how long the break should be.","vi":"Quy định không nêu rõ giờ nghỉ nên kéo dài bao lâu."},{"en":"Unless otherwise specified, all prices include tax.","vi":"Trừ khi có ghi chú khác, tất cả giá đều đã bao gồm thuế."}]','[{"phrase":"clearly specify"},{"phrase":"unless otherwise specified"},{"phrase":"specify the size"}]',NULL,'/ˈspesɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specify__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2298,'ngsl-5-11',27,'exact','chính xác; đúng; giống hệt','adjective','[{"en":"What is the exact time of your flight?","vi":"Giờ bay chính xác của bạn là mấy giờ?"},{"en":"I can''t remember the exact words she used.","vi":"Tôi không nhớ chính xác những từ cô ấy đã dùng."},{"en":"The twins wore the exact same dress to the party.","vi":"Hai chị em sinh đôi mặc chiếc váy giống hệt nhau đến bữa tiệc."}]','[{"phrase":"exact time"},{"phrase":"exact words"},{"phrase":"exact same"},{"phrase":"exact amount"}]',NULL,'/ɪɡˈzækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exact/exact__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2299,'ngsl-5-11',28,'spin','quay tròn; quay cuồng','verb','[{"en":"The children spun around until they felt dizzy.","vi":"Bọn trẻ quay vòng vòng cho đến khi thấy chóng mặt."},{"en":"The wheels kept spinning in the deep mud.","vi":"Bánh xe cứ quay tít trong bùn sâu."},{"en":"My head is spinning after that long meeting.","vi":"Đầu tôi quay cuồng sau cuộc họp dài đó."}]','[{"phrase":"spin around"},{"phrase":"head is spinning"},{"phrase":"spin the wheel"}]','spin – spun – spun','/spɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spi/spin_/spin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2300,'ngsl-5-11',29,'operator','người vận hành; tổng đài viên; công ty điều hành','noun','[{"en":"The operator put my call through to the right department.","vi":"Tổng đài viên đã nối máy cho tôi đến đúng phòng ban."},{"en":"He works as a machine operator in a factory.","vi":"Anh ấy làm công nhân vận hành máy trong một nhà máy."},{"en":"We booked our trip through a local tour operator.","vi":"Chúng tôi đặt chuyến đi qua một công ty du lịch địa phương."}]','[{"phrase":"tour operator"},{"phrase":"machine operator"},{"phrase":"telephone operator"}]',NULL,'/ˈɑːpəreɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/operator__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2301,'ngsl-5-11',30,'infant','trẻ sơ sinh; em bé','noun','[{"en":"The nurse showed us how to hold an infant safely.","vi":"Y tá hướng dẫn chúng tôi cách bế trẻ sơ sinh an toàn."},{"en":"This car seat is designed for infants under one year old.","vi":"Ghế ô tô này được thiết kế cho em bé dưới một tuổi."},{"en":"She has a lot of experience caring for infants.","vi":"Cô ấy có nhiều kinh nghiệm chăm sóc trẻ sơ sinh."}]','[{"phrase":"newborn infant"},{"phrase":"infant care"},{"phrase":"young infant"}]',NULL,'/ˈɪnfənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infan/infant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2302,'ngsl-5-12',1,'dig','đào; bới','verb','[{"en":"The kids spent all afternoon digging holes in the sand.","vi":"Bọn trẻ dành cả buổi chiều đào hố trên cát."},{"en":"We need to dig a small hole for this tree.","vi":"Chúng ta cần đào một cái hố nhỏ để trồng cây này."},{"en":"Our dog dug up all the flowers in the garden again.","vi":"Con chó nhà tôi lại bới hết hoa trong vườn lên."}]','[{"phrase":"dig a hole"},{"phrase":"dig up"},{"phrase":"dig deep"}]','dig – dug – dug','/dɪɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dig/dig__/dig__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2303,'ngsl-5-12',2,'drag','kéo lê; lôi; kéo (chuột)','verb','[{"en":"He dragged his heavy suitcase up the stairs to his room.","vi":"Anh ấy kéo lê chiếc vali nặng lên cầu thang về phòng."},{"en":"My friends dragged me to a party I didn''t want to attend.","vi":"Bạn bè lôi tôi đến một bữa tiệc mà tôi không muốn đi."},{"en":"Just drag the file into this folder and drop it.","vi":"Bạn chỉ cần kéo tệp vào thư mục này rồi thả ra."}]','[{"phrase":"drag and drop"},{"phrase":"drag a chair"},{"phrase":"drag a suitcase"}]',NULL,'/dræɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drag_/drag__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2304,'ngsl-5-12',3,'mount','tăng dần; gắn (lên tường); lên (ngựa, xe)','verb','[{"en":"Pressure is mounting on the team to finish the project.","vi":"Áp lực đối với nhóm để hoàn thành dự án đang tăng dần."},{"en":"We mounted the TV on the wall above the fireplace.","vi":"Chúng tôi gắn tivi lên tường phía trên lò sưởi."},{"en":"She mounted her bike and rode off down the street.","vi":"Cô ấy lên xe đạp rồi đạp đi dọc con phố."}]','[{"phrase":"mounting pressure"},{"phrase":"mount a TV"},{"phrase":"mount a bike"}]',NULL,'/maʊnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mount/mount__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2305,'ngsl-5-12',4,'wrap','gói; quấn','verb','[{"en":"I still need to wrap the presents before the party tonight.","vi":"Tôi vẫn cần gói quà trước bữa tiệc tối nay."},{"en":"She wrapped a warm scarf around her neck and went outside.","vi":"Cô ấy quấn một chiếc khăn ấm quanh cổ rồi ra ngoài."},{"en":"Wrap the sandwiches in paper so they stay fresh.","vi":"Hãy gói bánh mì kẹp trong giấy để chúng luôn tươi."}]','[{"phrase":"wrap a present"},{"phrase":"wrap something in paper"},{"phrase":"wrap up"}]',NULL,'/ræp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wra/wrap_/wrap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2306,'ngsl-5-12',5,'anticipate','lường trước; dự đoán','verb','[{"en":"We didn''t anticipate so many people coming to the event.","vi":"Chúng tôi không lường trước có nhiều người đến sự kiện như vậy."},{"en":"Good teachers anticipate the questions their students might ask.","vi":"Giáo viên giỏi lường trước những câu hỏi học sinh có thể đặt ra."},{"en":"The trip took longer than we had anticipated.","vi":"Chuyến đi mất nhiều thời gian hơn chúng tôi đã dự đoán."}]','[{"phrase":"anticipate problems"},{"phrase":"than anticipated"},{"phrase":"anticipate demand"}]',NULL,'/ænˈtɪsɪpeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ant/antic/anticipate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2307,'ngsl-5-12',6,'dependent','phụ thuộc; lệ thuộc','adjective','[{"en":"Many students are still financially dependent on their parents.","vi":"Nhiều sinh viên vẫn còn phụ thuộc vào bố mẹ về tài chính."},{"en":"The town''s economy is heavily dependent on tourism.","vi":"Nền kinh tế của thị trấn phụ thuộc nhiều vào du lịch."},{"en":"Try not to become too dependent on your phone.","vi":"Cố gắng đừng quá lệ thuộc vào điện thoại của bạn."}]','[{"phrase":"dependent on"},{"phrase":"heavily dependent"},{"phrase":"financially dependent"}]','dependent on (sth) · trái nghĩa: independent','/dɪˈpendənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depen/dependent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2308,'ngsl-5-12',7,'specialize','chuyên về; chuyên sâu','verb','[{"en":"This restaurant specializes in fresh seafood from the coast.","vi":"Nhà hàng này chuyên về hải sản tươi từ vùng biển."},{"en":"She wants to specialize in children''s health after medical school.","vi":"Cô ấy muốn chuyên sâu về sức khỏe trẻ em sau khi học xong trường y."},{"en":"My uncle is a lawyer who specializes in family law.","vi":"Chú tôi là luật sư chuyên về luật gia đình."}]','[{"phrase":"specialize in"},{"phrase":"highly specialized"}]','specialize in · Mỹ: specialize · Anh: specialise','/ˈspeʃəlaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specialize__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2309,'ngsl-5-12',8,'angle','góc; góc độ','noun','[{"en":"Take the photo from a different angle to get better light.","vi":"Hãy chụp ảnh từ một góc khác để có ánh sáng đẹp hơn."},{"en":"The ladder was leaning against the wall at a steep angle.","vi":"Chiếc thang dựa vào tường ở một góc rất dốc."},{"en":"Let''s look at this problem from a new angle.","vi":"Chúng ta hãy nhìn vấn đề này từ một góc độ mới."}]','[{"phrase":"from a different angle"},{"phrase":"at an angle"},{"phrase":"camera angle"}]',NULL,'/ˈæŋɡl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ang/angle/angle__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2310,'ngsl-5-12',9,'chicken','gà; thịt gà','noun','[{"en":"My grandmother keeps a few chickens in her backyard.","vi":"Bà tôi nuôi vài con gà ở sân sau."},{"en":"We''re having grilled chicken and rice for dinner tonight.","vi":"Tối nay chúng ta ăn gà nướng và cơm."},{"en":"Could you buy some chicken on your way home?","vi":"Bạn có thể mua ít thịt gà trên đường về nhà không?"}]','[{"phrase":"fried chicken"},{"phrase":"chicken soup"},{"phrase":"roast chicken"}]','thịt gà: không đếm được (some chicken)','/ˈtʃɪkɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/chi/chick/chicken__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2311,'ngsl-5-12',10,'anxiety','sự lo lắng; sự lo âu','noun','[{"en":"Many students feel a lot of anxiety before their exams.","vi":"Nhiều học sinh cảm thấy rất lo lắng trước kỳ thi."},{"en":"Regular exercise can help reduce stress and anxiety.","vi":"Tập thể dục đều đặn có thể giúp giảm căng thẳng và lo âu."},{"en":"She hid her anxiety and smiled at the interviewer.","vi":"Cô ấy giấu đi sự lo lắng và mỉm cười với người phỏng vấn."}]','[{"phrase":"feel anxiety"},{"phrase":"reduce anxiety"},{"phrase":"stress and anxiety"}]','tính từ: anxious','/æŋˈzaɪəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/anx/anxie/anxiety__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2312,'ngsl-5-12',11,'virus','vi-rút; vi-rút máy tính','noun','[{"en":"The doctor said my cold was caused by a virus.","vi":"Bác sĩ nói bệnh cảm của tôi là do một loại vi-rút gây ra."},{"en":"Wash your hands often to stop the virus from spreading.","vi":"Hãy rửa tay thường xuyên để ngăn vi-rút lây lan."},{"en":"Don''t open that email, because it might contain a virus.","vi":"Đừng mở email đó, vì nó có thể chứa vi-rút."}]','[{"phrase":"catch a virus"},{"phrase":"the virus spreads"},{"phrase":"computer virus"}]','số nhiều: viruses','/ˈvaɪrəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vir/virus/virus__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2313,'ngsl-5-12',12,'precisely','chính xác; đúng','adverb','[{"en":"The train left at precisely nine o''clock this morning.","vi":"Tàu rời ga lúc đúng chín giờ sáng nay."},{"en":"It''s hard to say precisely how many people came.","vi":"Thật khó nói chính xác có bao nhiêu người đã đến."},{"en":"That is precisely the reason I wanted to talk to you.","vi":"Đó chính là lý do tôi muốn nói chuyện với bạn."}]','[{"phrase":"precisely because"},{"phrase":"at precisely"},{"phrase":"know precisely"}]',NULL,'/prɪˈsaɪsli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preci/precisely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2314,'ngsl-5-12',13,'rival','đối thủ; đối thủ cạnh tranh','noun','[{"en":"Our team finally beat our biggest rival last weekend.","vi":"Cuối tuần trước đội chúng tôi cuối cùng đã đánh bại đối thủ lớn nhất."},{"en":"The two companies have been rivals for many years.","vi":"Hai công ty đó đã là đối thủ cạnh tranh trong nhiều năm."},{"en":"She works harder than any of her rivals at school.","vi":"Cô ấy chăm chỉ hơn bất kỳ đối thủ nào của mình ở trường."}]','[{"phrase":"main rival"},{"phrase":"close rival"},{"phrase":"rival team"}]',NULL,'/ˈraɪvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/riv/rival/rival__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2315,'ngsl-5-12',14,'offense','tội; sự xúc phạm','noun','[{"en":"Driving without a license is a serious offense in most countries.","vi":"Lái xe không có bằng là một tội nghiêm trọng ở hầu hết các nước."},{"en":"It was his first offense, so he only paid a fine.","vi":"Đó là lần phạm tội đầu tiên của anh ấy nên anh ấy chỉ bị phạt tiền."},{"en":"No offense, but I don''t really like your new haircut.","vi":"Không có ý xúc phạm đâu, nhưng tôi không thích kiểu tóc mới của bạn lắm."}]','[{"phrase":"serious offense"},{"phrase":"commit an offense"},{"phrase":"take offense"},{"phrase":"no offense"}]','Mỹ: offense · Anh: offence','/əˈfens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offen/offense__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2316,'ngsl-5-12',15,'detect','phát hiện; nhận ra','verb','[{"en":"This test can detect the disease at a very early stage.","vi":"Xét nghiệm này có thể phát hiện bệnh ở giai đoạn rất sớm."},{"en":"The alarm goes off when it detects smoke in the kitchen.","vi":"Chuông báo kêu khi phát hiện có khói trong bếp."},{"en":"I detected a hint of worry in her voice.","vi":"Tôi nhận ra một chút lo lắng trong giọng nói của cô ấy."}]','[{"phrase":"detect smoke"},{"phrase":"detect a problem"},{"phrase":"difficult to detect"}]',NULL,'/dɪˈtekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/detec/detect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2317,'ngsl-5-12',16,'teenager','thanh thiếu niên; tuổi mới lớn','noun','[{"en":"Most teenagers spend several hours a day on their phones.","vi":"Hầu hết thanh thiếu niên dành vài giờ mỗi ngày cho điện thoại."},{"en":"When I was a teenager, I worked in a café every summer.","vi":"Hồi tuổi mới lớn, mùa hè nào tôi cũng làm ở một quán cà phê."},{"en":"Their two teenagers help a lot with the housework.","vi":"Hai đứa con tuổi mới lớn của họ giúp việc nhà rất nhiều."}]','[{"phrase":"young teenager"},{"phrase":"as a teenager"},{"phrase":"typical teenager"}]','tuổi 13–19','/ˈtiːneɪdʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tee/teena/teenager__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2318,'ngsl-5-12',17,'admire','ngưỡng mộ; chiêm ngưỡng','verb','[{"en":"I really admire people who can speak several languages.","vi":"Tôi thực sự ngưỡng mộ những người nói được nhiều thứ tiếng."},{"en":"We stopped on the bridge to admire the view.","vi":"Chúng tôi dừng lại trên cầu để chiêm ngưỡng quang cảnh."},{"en":"She has always admired her mother for her courage.","vi":"Cô ấy luôn ngưỡng mộ mẹ mình vì lòng dũng cảm của bà."}]','[{"phrase":"admire the view"},{"phrase":"admire someone for"},{"phrase":"greatly admire"}]','admire sb for sth','/ədˈmaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adm/admir/admire__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2319,'ngsl-5-12',18,'moderate','vừa phải; ôn hòa','adjective','[{"en":"Doctors recommend at least thirty minutes of moderate exercise a day.","vi":"Bác sĩ khuyên nên tập thể dục vừa phải ít nhất ba mươi phút mỗi ngày."},{"en":"Drinking moderate amounts of coffee is usually fine for most adults.","vi":"Uống cà phê ở mức vừa phải thường không sao đối với hầu hết người lớn."},{"en":"He has fairly moderate views and rarely argues with anyone.","vi":"Anh ấy có quan điểm khá ôn hòa và hiếm khi tranh cãi với ai."}]','[{"phrase":"moderate exercise"},{"phrase":"moderate amounts"},{"phrase":"moderate views"}]',NULL,'/ˈmɑːdərət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/moder/moderate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2320,'ngsl-5-12',19,'surgery','phẫu thuật; ca mổ','noun','[{"en":"My dad had knee surgery last month and is recovering well.","vi":"Bố tôi đã phẫu thuật đầu gối tháng trước và đang hồi phục tốt."},{"en":"The surgery on her back took about three hours.","vi":"Ca mổ lưng của cô ấy kéo dài khoảng ba tiếng."},{"en":"She will need surgery to fix her broken arm.","vi":"Cô ấy sẽ cần phẫu thuật để chữa cánh tay bị gãy."}]','[{"phrase":"have surgery"},{"phrase":"undergo surgery"},{"phrase":"knee surgery"},{"phrase":"need surgery"}]',NULL,'/ˈsɜːrdʒəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surge/surgery__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2321,'ngsl-5-12',20,'musician','nhạc sĩ; nhạc công','noun','[{"en":"A local musician played the guitar at our wedding.","vi":"Một nhạc công địa phương đã chơi ghi-ta ở đám cưới của chúng tôi."},{"en":"My brother wants to become a professional musician one day.","vi":"Anh trai tôi muốn một ngày nào đó trở thành nhạc sĩ chuyên nghiệp."},{"en":"Street musicians often perform in the park on Sundays.","vi":"Các nhạc công đường phố thường biểu diễn trong công viên vào Chủ nhật."}]','[{"phrase":"professional musician"},{"phrase":"talented musician"},{"phrase":"street musician"}]',NULL,'/mjuˈzɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/music/musician__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2322,'ngsl-5-12',21,'significance','tầm quan trọng; ý nghĩa','noun','[{"en":"At the time, nobody understood the significance of his discovery.","vi":"Vào lúc đó, không ai hiểu được tầm quan trọng của phát hiện của anh ấy."},{"en":"This old temple has great historical significance for the town.","vi":"Ngôi đền cổ này có ý nghĩa lịch sử to lớn đối với thị trấn."},{"en":"The color red has a special significance in many cultures.","vi":"Màu đỏ có ý nghĩa đặc biệt trong nhiều nền văn hóa."}]','[{"phrase":"historical significance"},{"phrase":"great significance"},{"phrase":"understand the significance"}]','tính từ: significant','/sɪɡˈnɪfɪkəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signi/significance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2323,'ngsl-5-12',22,'shower','vòi sen; việc tắm vòi sen; mưa rào','noun','[{"en":"I always take a quick shower after going to the gym.","vi":"Tôi luôn tắm nhanh bằng vòi sen sau khi đi tập gym."},{"en":"The shower in our hotel room didn''t have any hot water.","vi":"Vòi sen trong phòng khách sạn của chúng tôi không có nước nóng."},{"en":"There will be a few light showers this afternoon.","vi":"Chiều nay sẽ có vài cơn mưa rào nhẹ."}]','[{"phrase":"take a shower"},{"phrase":"hot shower"},{"phrase":"light showers"}]',NULL,'/ˈʃaʊər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/showe/shower__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2324,'ngsl-5-12',23,'illegal','bất hợp pháp; trái phép','adjective','[{"en":"It is illegal to park your car in front of a hospital entrance.","vi":"Đỗ xe trước lối vào bệnh viện là bất hợp pháp."},{"en":"The police found illegal copies of movies in the shop.","vi":"Cảnh sát tìm thấy các bản sao phim trái phép trong cửa hàng."},{"en":"Selling alcohol to children is illegal in this country.","vi":"Bán rượu cho trẻ em là bất hợp pháp ở nước này."}]','[{"phrase":"it is illegal to"},{"phrase":"illegal parking"},{"phrase":"illegal activity"}]','trái nghĩa: legal','/ɪˈliːɡl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illeg/illegal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2325,'ngsl-5-12',24,'charity','tổ chức từ thiện; việc từ thiện','noun','[{"en":"She works for a charity that helps homeless animals.","vi":"Cô ấy làm việc cho một tổ chức từ thiện giúp đỡ động vật vô gia cư."},{"en":"We gave all our old clothes to charity last week.","vi":"Tuần trước chúng tôi đã đem hết quần áo cũ đi làm từ thiện."},{"en":"The school is organizing a charity run next Saturday.","vi":"Trường đang tổ chức một cuộc chạy từ thiện vào thứ Bảy tới."}]','[{"phrase":"give to charity"},{"phrase":"charity event"},{"phrase":"local charity"},{"phrase":"raise money for charity"}]',NULL,'/ˈtʃærəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chari/charity__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2326,'ngsl-5-12',25,'universal','phổ biến; phổ quát; chung cho mọi người','adjective','[{"en":"Music is a universal language that everyone can enjoy.","vi":"Âm nhạc là ngôn ngữ chung mà ai cũng có thể thưởng thức."},{"en":"The new plan received almost universal support from the staff.","vi":"Kế hoạch mới nhận được sự ủng hộ gần như từ tất cả nhân viên."},{"en":"The desire to be happy is universal.","vi":"Mong muốn được hạnh phúc là điều phổ quát ở mọi người."}]','[{"phrase":"universal language"},{"phrase":"universal appeal"},{"phrase":"universal support"}]',NULL,'/ˌjuːnɪˈvɜːrsl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unive/universal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2327,'ngsl-5-12',26,'cigarette','điếu thuốc lá; thuốc lá','noun','[{"en":"My uncle finally stopped smoking cigarettes after twenty years.","vi":"Chú tôi cuối cùng đã bỏ hút thuốc lá sau hai mươi năm."},{"en":"Please don''t throw your cigarette on the beach.","vi":"Làm ơn đừng vứt điếu thuốc trên bãi biển."},{"en":"The price of cigarettes has gone up again this year.","vi":"Giá thuốc lá lại tăng trong năm nay."}]','[{"phrase":"smoke a cigarette"},{"phrase":"light a cigarette"},{"phrase":"packet of cigarettes"}]',NULL,'/ˈsɪɡəret/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cig/cigar/cigarette__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2328,'ngsl-5-12',27,'constitute','cấu thành; chiếm; được coi là','verb','[{"en":"Women constitute more than half of the company''s workforce.","vi":"Phụ nữ chiếm hơn một nửa lực lượng lao động của công ty."},{"en":"Twelve short chapters constitute the first part of the book.","vi":"Mười hai chương ngắn tạo thành phần đầu của cuốn sách."},{"en":"Being late once does not constitute a serious problem.","vi":"Đi muộn một lần không được coi là vấn đề nghiêm trọng."}]','[{"phrase":"constitute a threat"},{"phrase":"constitute a problem"},{"phrase":"constitute a majority"}]',NULL,'/ˈkɑːnstɪtuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstitute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2329,'ngsl-5-12',28,'adequate','đủ; thỏa đáng','adjective','[{"en":"Make sure you get adequate sleep before the big exam.","vi":"Hãy chắc chắn rằng bạn ngủ đủ giấc trước kỳ thi quan trọng."},{"en":"The room was small but perfectly adequate for two people.","vi":"Căn phòng nhỏ nhưng hoàn toàn đủ cho hai người."},{"en":"He couldn''t give an adequate explanation for his mistake.","vi":"Anh ấy không thể đưa ra lời giải thích thỏa đáng cho sai lầm của mình."}]','[{"phrase":"adequate sleep"},{"phrase":"adequate explanation"},{"phrase":"perfectly adequate"}]','trái nghĩa: inadequate','/ˈædɪkwət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ade/adequ/adequate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2330,'ngsl-5-12',29,'consultant','chuyên gia tư vấn; cố vấn','noun','[{"en":"The company hired a consultant to improve its sales.","vi":"Công ty đã thuê một chuyên gia tư vấn để cải thiện doanh số."},{"en":"My sister works as a marketing consultant for small businesses.","vi":"Chị gái tôi làm cố vấn tiếp thị cho các doanh nghiệp nhỏ."},{"en":"We should ask a financial consultant before buying the house.","vi":"Chúng ta nên hỏi ý kiến một chuyên gia tư vấn tài chính trước khi mua nhà."}]','[{"phrase":"hire a consultant"},{"phrase":"financial consultant"},{"phrase":"management consultant"}]',NULL,'/kənˈsʌltənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsultant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2331,'ngsl-5-12',30,'historian','nhà sử học','noun','[{"en":"Historians still disagree about when the old city was built.","vi":"Các nhà sử học vẫn chưa thống nhất về thời điểm thành phố cổ được xây dựng."},{"en":"A local historian gave us a tour of the castle.","vi":"Một nhà sử học địa phương đã dẫn chúng tôi tham quan lâu đài."},{"en":"She studied for many years to become a historian.","vi":"Cô ấy đã học nhiều năm để trở thành nhà sử học."}]','[{"phrase":"art historian"},{"phrase":"local historian"},{"phrase":"historians believe"}]',NULL,'/hɪˈstɔːriən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/historian__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2332,'ngsl-5-13',1,'cousin','anh chị em họ','noun','[{"en":"My cousin is getting married in Hanoi next month.","vi":"Anh họ tôi sẽ cưới vợ ở Hà Nội vào tháng sau."},{"en":"We stayed with our cousins over summer vacation.","vi":"Chúng tôi ở nhà anh chị em họ trong kỳ nghỉ hè."},{"en":"He is a distant cousin on my mother''s side.","vi":"Anh ấy là anh họ xa bên ngoại của tôi."}]','[{"phrase":"first cousin"},{"phrase":"distant cousin"},{"phrase":"older cousin"}]',NULL,'/ˈkʌzn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/cousi/cousin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2333,'ngsl-5-13',2,'visual','thuộc thị giác; trực quan; hình ảnh','adjective','[{"en":"Children often learn better with visual aids like pictures.","vi":"Trẻ em thường học tốt hơn với đồ dùng trực quan như tranh ảnh."},{"en":"The movie has amazing visual effects but a weak story.","vi":"Bộ phim có kỹ xảo hình ảnh tuyệt vời nhưng cốt truyện yếu."},{"en":"Some people have a very good visual memory for faces.","vi":"Một số người có trí nhớ hình ảnh rất tốt đối với khuôn mặt."}]','[{"phrase":"visual aids"},{"phrase":"visual effects"},{"phrase":"visual memory"},{"phrase":"visual arts"}]',NULL,'/ˈvɪʒuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visua/visual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2334,'ngsl-5-13',3,'stupid','ngu ngốc; ngớ ngẩn','adjective','[{"en":"I made a stupid mistake on my math test.","vi":"Tôi đã mắc một lỗi ngớ ngẩn trong bài kiểm tra toán."},{"en":"It was stupid of me to leave my keys in the car.","vi":"Tôi thật ngốc khi để quên chìa khóa trong xe."},{"en":"There''s no such thing as a stupid question in this class.","vi":"Trong lớp này không có câu hỏi nào là ngớ ngẩn cả."}]','[{"phrase":"stupid mistake"},{"phrase":"stupid question"},{"phrase":"feel stupid"}]',NULL,'/ˈstuːpɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/stupi/stupid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2335,'ngsl-5-13',4,'keen','háo hức; say mê; nhạy bén','adjective','[{"en":"She is very keen on learning Japanese.","vi":"Cô ấy rất say mê học tiếng Nhật."},{"en":"The new staff are keen to learn and ask lots of questions.","vi":"Các nhân viên mới rất háo hức học hỏi và đặt nhiều câu hỏi."},{"en":"Dogs have a very keen sense of smell.","vi":"Chó có khứu giác rất nhạy bén."}]','[{"phrase":"keen on"},{"phrase":"keen to learn"},{"phrase":"keen interest"},{"phrase":"keen sense of smell"}]','keen on + N/V-ing: thích, say mê','/kiːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kee/keen_/keen__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2336,'ngsl-5-13',5,'ethnic','thuộc dân tộc; sắc tộc','adjective','[{"en":"Vietnam has fifty-four officially recognized ethnic groups.","vi":"Việt Nam có 54 dân tộc được công nhận chính thức."},{"en":"The museum displays traditional clothes from many ethnic minorities.","vi":"Bảo tàng trưng bày trang phục truyền thống của nhiều dân tộc thiểu số."},{"en":"Students from different ethnic backgrounds study together at this school.","vi":"Học sinh thuộc nhiều dân tộc khác nhau cùng học ở trường này."}]','[{"phrase":"ethnic group"},{"phrase":"ethnic minority"},{"phrase":"ethnic background"}]',NULL,'/ˈeθnɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eth/ethni/ethnic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2337,'ngsl-5-13',6,'twin','trẻ sinh đôi; song sinh','noun','[{"en":"My sister just gave birth to twins.","vi":"Chị tôi vừa sinh đôi."},{"en":"Even their parents can''t tell the twins apart.","vi":"Ngay cả bố mẹ cũng không phân biệt được hai đứa sinh đôi."},{"en":"He has a twin brother who lives in Australia.","vi":"Anh ấy có một người anh em song sinh sống ở Úc."}]','[{"phrase":"twin brother"},{"phrase":"twin sister"},{"phrase":"identical twins"}]',NULL,'/twɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/twi/twin_/twin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2338,'ngsl-5-13',7,'clinical','lâm sàng','adjective','[{"en":"The new drug is still in clinical trials.","vi":"Loại thuốc mới vẫn đang được thử nghiệm lâm sàng."},{"en":"Medical students gain clinical experience by working in hospitals.","vi":"Sinh viên y tích lũy kinh nghiệm lâm sàng bằng cách làm việc ở bệnh viện."},{"en":"She works as a clinical psychologist at a children''s hospital.","vi":"Cô ấy là nhà tâm lý học lâm sàng tại một bệnh viện nhi."}]','[{"phrase":"clinical trial"},{"phrase":"clinical experience"},{"phrase":"clinical practice"}]',NULL,'/ˈklɪnɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/clini/clinical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2339,'ngsl-5-13',8,'eastern','(thuộc) phía đông; phương Đông','adjective','[{"en":"Heavy rain is expected in eastern parts of the country.","vi":"Dự kiến sẽ có mưa lớn ở các vùng phía đông của đất nước."},{"en":"They spent two weeks traveling around Eastern Europe.","vi":"Họ đã dành hai tuần đi du lịch vòng quanh Đông Âu."},{"en":"Many Western visitors are interested in Eastern culture and food.","vi":"Nhiều du khách phương Tây quan tâm đến văn hóa và ẩm thực phương Đông."}]','[{"phrase":"eastern part"},{"phrase":"Eastern Europe"},{"phrase":"eastern coast"}]',NULL,'/ˈiːstərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/easte/eastern__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2340,'ngsl-5-13',9,'forecast','dự báo','noun','[{"en":"The weather forecast says it will rain this afternoon.","vi":"Dự báo thời tiết nói chiều nay trời sẽ mưa."},{"en":"Did you check the forecast before planning the picnic?","vi":"Bạn đã xem dự báo trước khi lên kế hoạch đi dã ngoại chưa?"},{"en":"The company''s sales forecast for next year looks very positive.","vi":"Dự báo doanh số năm tới của công ty trông rất khả quan."}]','[{"phrase":"weather forecast"},{"phrase":"sales forecast"},{"phrase":"economic forecast"}]','động từ: forecast – forecast – forecast','/ˈfɔːrkæst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forec/forecast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2341,'ngsl-5-13',10,'segment','phần; đoạn; phân khúc','noun','[{"en":"Peel the orange and divide it into segments.","vi":"Bóc vỏ quả cam rồi tách thành từng múi."},{"en":"The show''s final segment is about healthy cooking.","vi":"Phần cuối của chương trình nói về cách nấu ăn lành mạnh."},{"en":"Young people are the fastest-growing segment of the market.","vi":"Giới trẻ là phân khúc tăng trưởng nhanh nhất của thị trường."}]','[{"phrase":"market segment"},{"phrase":"small segment"},{"phrase":"divide into segments"}]',NULL,'/ˈseɡmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/seg/segme/segment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2342,'ngsl-5-13',11,'custom','phong tục; tập quán','noun','[{"en":"It is the custom in Vietnam to give children lucky money at Tet.","vi":"Ở Việt Nam có phong tục lì xì cho trẻ em vào dịp Tết."},{"en":"Visitors should learn about local customs before traveling abroad.","vi":"Du khách nên tìm hiểu phong tục địa phương trước khi ra nước ngoài."},{"en":"Taking off your shoes before entering a home is an old custom.","vi":"Cởi giày trước khi vào nhà là một phong tục lâu đời."}]','[{"phrase":"local customs"},{"phrase":"old custom"},{"phrase":"follow a custom"}]','customs (số nhiều) còn có nghĩa: hải quan','/ˈkʌstəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cus/custo/custom__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2343,'ngsl-5-13',12,'adapt','thích nghi; điều chỉnh; chuyển thể','verb','[{"en":"It took me months to adapt to life in a new country.","vi":"Tôi mất nhiều tháng để thích nghi với cuộc sống ở một đất nước mới."},{"en":"Teachers often adapt their lessons for students with different needs.","vi":"Giáo viên thường điều chỉnh bài giảng cho học sinh có nhu cầu khác nhau."},{"en":"The novel was adapted into a popular TV series.","vi":"Cuốn tiểu thuyết đã được chuyển thể thành một bộ phim truyền hình ăn khách."}]','[{"phrase":"adapt to change"},{"phrase":"adapt quickly"},{"phrase":"adapted from a novel"}]','adapt (thích nghi) ≠ adopt (nhận nuôi; áp dụng)','/əˈdæpt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ada/adapt/adapt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2344,'ngsl-5-13',13,'sand','cát','noun','[{"en":"The children spent all afternoon building castles in the sand.","vi":"Bọn trẻ dành cả buổi chiều xây lâu đài trên cát."},{"en":"The sand gets very hot at noon, so wear sandals.","vi":"Cát rất nóng vào buổi trưa, nên hãy đi dép."},{"en":"I still have sand in my shoes from the beach.","vi":"Giày tôi vẫn còn cát từ bãi biển."}]','[{"phrase":"white sand"},{"phrase":"soft sand"},{"phrase":"grain of sand"}]','không đếm được','/sænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/san/sand_/sand__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2345,'ngsl-5-13',14,'cap','mũ lưỡi trai; nắp','noun','[{"en":"He always wears a baseball cap when he goes running.","vi":"Anh ấy luôn đội mũ lưỡi trai khi đi chạy bộ."},{"en":"Please put the cap back on the pen when you''re done.","vi":"Dùng xong thì bạn nhớ đậy nắp bút lại nhé."},{"en":"I can''t open this bottle because the cap is too tight.","vi":"Tôi không mở được chai này vì nắp chặt quá."}]','[{"phrase":"baseball cap"},{"phrase":"bottle cap"},{"phrase":"wear a cap"}]',NULL,'/kæp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/cap__/cap__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2346,'ngsl-5-13',15,'prompt','thúc đẩy; khiến; nhắc','verb','[{"en":"Rising prices prompted many families to cook at home more.","vi":"Giá cả tăng khiến nhiều gia đình nấu ăn ở nhà nhiều hơn."},{"en":"What prompted you to change your career?","vi":"Điều gì đã thúc đẩy bạn thay đổi nghề nghiệp?"},{"en":"The app will prompt you to enter your password again.","vi":"Ứng dụng sẽ nhắc bạn nhập lại mật khẩu."}]','[{"phrase":"prompt a response"},{"phrase":"prompt concern"},{"phrase":"prompted by"}]','tính từ: nhanh chóng, kịp thời (a prompt reply)','/prɑːmpt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promp/prompt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2347,'ngsl-5-13',16,'charm','sức quyến rũ; nét duyên; bùa may','noun','[{"en":"The old town has kept much of its original charm.","vi":"Khu phố cổ vẫn giữ được phần lớn nét duyên vốn có."},{"en":"He used all his charm to get a better price.","vi":"Anh ấy dùng hết sức quyến rũ của mình để được giá tốt hơn."},{"en":"She wears a small silver charm for good luck.","vi":"Cô ấy đeo một chiếc bùa nhỏ bằng bạc để cầu may."}]','[{"phrase":"lucky charm"},{"phrase":"natural charm"},{"phrase":"lose its charm"},{"phrase":"full of charm"}]',NULL,'/tʃɑːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/charm/charm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2348,'ngsl-5-13',17,'react','phản ứng','verb','[{"en":"How did your parents react when you told them?","vi":"Bố mẹ bạn đã phản ứng thế nào khi bạn nói với họ?"},{"en":"Drivers need to react quickly when a child runs into the road.","vi":"Tài xế cần phản ứng nhanh khi có trẻ em chạy ra đường."},{"en":"Some people react badly to certain kinds of medicine.","vi":"Một số người phản ứng xấu với một vài loại thuốc."}]','[{"phrase":"react to"},{"phrase":"react quickly"},{"phrase":"react badly"}]','react to something: phản ứng với điều gì','/riˈækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/react/react__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2349,'ngsl-5-13',18,'lecture','bài giảng; buổi diễn thuyết; lời răn dạy','noun','[{"en":"I missed the morning lecture because my bus was late.","vi":"Tôi lỡ buổi giảng sáng vì xe buýt đến muộn."},{"en":"The professor gave an interesting lecture on climate change.","vi":"Giáo sư đã có một bài giảng thú vị về biến đổi khí hậu."},{"en":"My dad gave me a long lecture about saving money.","vi":"Bố tôi giảng cho tôi một bài dài về việc tiết kiệm tiền."}]','[{"phrase":"give a lecture"},{"phrase":"attend a lecture"},{"phrase":"lecture hall"}]',NULL,'/ˈlektʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lec/lectu/lecture__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2350,'ngsl-5-13',19,'venture','dự án kinh doanh; liên doanh; việc mạo hiểm','noun','[{"en":"Opening a café was her first business venture.","vi":"Mở quán cà phê là dự án kinh doanh đầu tiên của cô ấy."},{"en":"The two companies formed a joint venture to build electric cars.","vi":"Hai công ty đã lập liên doanh để sản xuất ô tô điện."},{"en":"His new venture failed after only six months.","vi":"Việc kinh doanh mới của anh ấy thất bại chỉ sau sáu tháng."}]','[{"phrase":"business venture"},{"phrase":"joint venture"},{"phrase":"new venture"}]',NULL,'/ˈventʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ven/ventu/venture__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2351,'ngsl-5-13',20,'compound','hợp chất; từ ghép','noun','[{"en":"Water is a compound of hydrogen and oxygen.","vi":"Nước là hợp chất của hydro và oxy."},{"en":"Scientists found a new compound that may kill harmful bacteria.","vi":"Các nhà khoa học tìm ra một hợp chất mới có thể tiêu diệt vi khuẩn có hại."},{"en":"The English word \"sunflower\" is a compound of \"sun\" and \"flower\".","vi":"Từ tiếng Anh \"sunflower\" là từ ghép của \"sun\" và \"flower\"."}]','[{"phrase":"chemical compound"},{"phrase":"organic compound"},{"phrase":"compound word"}]',NULL,'/ˈkɑːmpaʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/compound__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2352,'ngsl-5-13',21,'rescue','cứu; giải cứu','verb','[{"en":"Firefighters rescued two children from the burning house.","vi":"Lính cứu hỏa đã cứu hai đứa trẻ khỏi ngôi nhà đang cháy."},{"en":"The fishermen were rescued after two days at sea.","vi":"Những ngư dân đã được cứu sau hai ngày lênh đênh trên biển."},{"en":"She rescued a small dog she found on the street.","vi":"Cô ấy đã cứu một chú chó nhỏ mà cô tìm thấy ngoài đường."}]','[{"phrase":"rescue someone from"},{"phrase":"rescue team"},{"phrase":"come to the rescue"}]',NULL,'/ˈreskjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/rescu/rescue__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2353,'ngsl-5-13',22,'mess','sự bừa bộn; tình trạng rối ren','noun','[{"en":"Your room is a mess, so please clean it up.","vi":"Phòng con bừa bộn quá, con dọn dẹp đi nhé."},{"en":"The kids made a huge mess in the kitchen.","vi":"Bọn trẻ bày bừa khắp nhà bếp."},{"en":"My life was a mess after I lost my job.","vi":"Cuộc sống của tôi rối tung sau khi mất việc."}]','[{"phrase":"make a mess"},{"phrase":"clean up the mess"},{"phrase":"a complete mess"}]',NULL,'/mes/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mes/mess_/mess__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2354,'ngsl-5-13',23,'preference','sự ưa thích hơn; sở thích','noun','[{"en":"Do you have a preference for window or aisle seats?","vi":"Bạn thích ghế cạnh cửa sổ hay ghế cạnh lối đi hơn?"},{"en":"We can order pizza or noodles; I have no preference.","vi":"Mình có thể gọi pizza hoặc mì, món nào tôi cũng được."},{"en":"Customers'' preferences change quickly, so we update the menu often.","vi":"Sở thích của khách hàng thay đổi nhanh, nên chúng tôi thường xuyên cập nhật thực đơn."}]','[{"phrase":"preference for"},{"phrase":"personal preference"},{"phrase":"strong preference"},{"phrase":"have a preference"}]',NULL,'/ˈprefrəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prefe/preference__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2355,'ngsl-5-13',24,'comprehensive','toàn diện; đầy đủ','adjective','[{"en":"This guidebook gives a comprehensive list of hotels in the city.","vi":"Cuốn sách hướng dẫn này có danh sách đầy đủ các khách sạn trong thành phố."},{"en":"The doctor ordered a comprehensive health check for my father.","vi":"Bác sĩ chỉ định khám sức khỏe toàn diện cho bố tôi."},{"en":"The report offers a comprehensive review of the city''s traffic problems.","vi":"Bản báo cáo đưa ra đánh giá toàn diện về các vấn đề giao thông của thành phố."}]','[{"phrase":"comprehensive list"},{"phrase":"comprehensive review"},{"phrase":"comprehensive guide"}]',NULL,'/ˌkɑːmprɪˈhensɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprehensive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2356,'ngsl-5-13',25,'incentive','động lực; sự khuyến khích; ưu đãi','noun','[{"en":"The company offers bonuses as an incentive for hard work.","vi":"Công ty trả tiền thưởng để khuyến khích làm việc chăm chỉ."},{"en":"There is little incentive to save when interest rates are low.","vi":"Khi lãi suất thấp, người ta có ít động lực để tiết kiệm."},{"en":"Free parking is a good incentive for shoppers to visit the mall.","vi":"Bãi đỗ xe miễn phí là ưu đãi tốt để thu hút người mua sắm đến trung tâm thương mại."}]','[{"phrase":"financial incentive"},{"phrase":"tax incentive"},{"phrase":"strong incentive"},{"phrase":"provide an incentive"}]',NULL,'/ɪnˈsentɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incen/incentive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2357,'ngsl-5-13',26,'league','giải đấu; liên đoàn; đẳng cấp','noun','[{"en":"Our team finished second in the league this season.","vi":"Đội chúng tôi xếp thứ hai trong giải đấu mùa này."},{"en":"He plays in a local basketball league on weekends.","vi":"Anh ấy chơi trong một giải bóng rổ địa phương vào cuối tuần."},{"en":"As a cook, she is not in the same league as her mother.","vi":"Về khoản nấu ăn, cô ấy không cùng đẳng cấp với mẹ mình."}]','[{"phrase":"win the league"},{"phrase":"league title"},{"phrase":"in the same league"}]',NULL,'/liːɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leagu/league__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2358,'ngsl-5-13',27,'dialog','đoạn hội thoại; lời thoại; hộp thoại','noun','[{"en":"Read the dialog aloud with your partner.","vi":"Hãy đọc to đoạn hội thoại cùng bạn của em."},{"en":"The movie has great action scenes but terrible dialog.","vi":"Bộ phim có những cảnh hành động tuyệt vời nhưng lời thoại dở tệ."},{"en":"Click \"OK\" when the dialog box appears on the screen.","vi":"Nhấn \"OK\" khi hộp thoại hiện lên trên màn hình."}]','[{"phrase":"dialog box"},{"phrase":"dialog between"}]','Mỹ: dialog · Anh: dialogue','/ˈdaɪəlɔɡ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2359,'ngsl-5-13',28,'cream','kem sữa; kem bôi','noun','[{"en":"Do you take cream and sugar in your coffee?","vi":"Bạn có cho kem sữa và đường vào cà phê không?"},{"en":"She served the strawberries with fresh whipped cream.","vi":"Cô ấy dọn dâu tây kèm kem tươi đánh bông."},{"en":"Apply this cream to your skin twice a day.","vi":"Thoa loại kem này lên da hai lần mỗi ngày."}]','[{"phrase":"whipped cream"},{"phrase":"sour cream"},{"phrase":"face cream"},{"phrase":"hand cream"}]','ice cream = kem (để ăn)','/kriːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/cream/cream__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2360,'ngsl-5-13',29,'rapid','nhanh; nhanh chóng','adjective','[{"en":"The city has seen rapid growth over the past ten years.","vi":"Thành phố đã phát triển nhanh chóng trong mười năm qua."},{"en":"Technology is changing at a rapid pace these days.","vi":"Ngày nay công nghệ đang thay đổi với tốc độ nhanh."},{"en":"The patient made a rapid recovery after the surgery.","vi":"Bệnh nhân hồi phục nhanh chóng sau ca phẫu thuật."}]','[{"phrase":"rapid growth"},{"phrase":"rapid change"},{"phrase":"rapid pace"},{"phrase":"rapid recovery"}]',NULL,'/ˈræpɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rap/rapid/rapid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2361,'ngsl-5-13',30,'cancel','hủy; hủy bỏ','verb','[{"en":"Our flight was canceled because of the storm.","vi":"Chuyến bay của chúng tôi bị hủy vì bão."},{"en":"I need to cancel my dentist appointment tomorrow.","vi":"Tôi cần hủy lịch hẹn với nha sĩ ngày mai."},{"en":"If you cancel within 24 hours, you''ll get a full refund.","vi":"Nếu hủy trong vòng 24 giờ, bạn sẽ được hoàn tiền đầy đủ."}]','[{"phrase":"cancel a flight"},{"phrase":"cancel an appointment"},{"phrase":"cancel a meeting"},{"phrase":"cancel an order"}]','Mỹ: canceled · Anh: cancelled','/ˈkænsl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/can/cance/cancel__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2362,'ngsl-5-14',1,'regret','hối tiếc; lấy làm tiếc','verb','[{"en":"I really regret not studying harder when I was at school.","vi":"Tôi thật sự hối tiếc vì đã không học chăm hơn khi còn đi học."},{"en":"I promise you won''t regret taking this job.","vi":"Tôi hứa bạn sẽ không hối tiếc khi nhận công việc này."},{"en":"We regret to inform you that the concert has been canceled.","vi":"Chúng tôi rất tiếc phải thông báo rằng buổi hòa nhạc đã bị hủy."}]','[{"phrase":"deeply regret"},{"phrase":"regret a decision"},{"phrase":"regret to inform"}]','regret + V-ing: hối tiếc đã làm · regret to + V: lấy làm tiếc phải làm','/rɪˈɡret/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regre/regret__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2363,'ngsl-5-14',2,'dismiss','gạt bỏ, bác bỏ; sa thải; cho về','verb','[{"en":"She quickly dismissed the idea because it was too expensive.","vi":"Cô ấy nhanh chóng gạt bỏ ý tưởng đó vì nó quá tốn kém."},{"en":"He was dismissed from his job for being late every day.","vi":"Anh ấy bị sa thải vì ngày nào cũng đi làm muộn."},{"en":"The teacher dismissed the class ten minutes early on Friday.","vi":"Thứ Sáu, giáo viên cho cả lớp về sớm mười phút."}]','[{"phrase":"dismiss an idea"},{"phrase":"dismiss the possibility"},{"phrase":"be dismissed from a job"}]',NULL,'/dɪsˈmɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dismi/dismiss__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2364,'ngsl-5-14',3,'margin','lề (trang giấy); cách biệt, chênh lệch; biên lợi nhuận','noun','[{"en":"Please write your name in the left margin of the page.","vi":"Vui lòng viết tên của bạn vào lề trái của trang giấy."},{"en":"Our team won the game by a narrow margin.","vi":"Đội chúng tôi thắng trận với cách biệt sít sao."},{"en":"The shop sells cheap goods, so its profit margins are small.","vi":"Cửa hàng bán hàng giá rẻ nên biên lợi nhuận thấp."}]','[{"phrase":"narrow margin"},{"phrase":"wide margin"},{"phrase":"profit margin"},{"phrase":"in the margin"}]',NULL,'/ˈmɑːrdʒɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/margi/margin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2365,'ngsl-5-14',4,'beneath','bên dưới, ở dưới; ẩn sau','preposition','[{"en":"We found the missing keys beneath a pile of old newspapers.","vi":"Chúng tôi tìm thấy chùm chìa khóa bị mất dưới một đống báo cũ."},{"en":"The ice was thin, and we could see dark water just beneath it.","vi":"Lớp băng mỏng, và chúng tôi có thể thấy làn nước tối màu ngay bên dưới."},{"en":"Beneath her smile, she was actually very worried.","vi":"Ẩn sau nụ cười, thật ra cô ấy rất lo lắng."}]','[{"phrase":"beneath the surface"},{"phrase":"just beneath"},{"phrase":"deep beneath"}]',NULL,'/bɪˈniːθ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ben/benea/beneath__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2366,'ngsl-5-14',5,'opponent','đối thủ; người phản đối','noun','[{"en":"She shook hands with her opponent before the match started.","vi":"Cô ấy bắt tay đối thủ trước khi trận đấu bắt đầu."},{"en":"He is a good chess player, but his opponent is even stronger.","vi":"Anh ấy chơi cờ vua giỏi, nhưng đối thủ của anh ấy còn mạnh hơn."},{"en":"Opponents of the new road say it will destroy the forest.","vi":"Những người phản đối con đường mới nói rằng nó sẽ phá hủy khu rừng."}]','[{"phrase":"strong opponent"},{"phrase":"beat an opponent"},{"phrase":"face an opponent"}]',NULL,'/əˈpəʊnənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppon/opponent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2367,'ngsl-5-14',6,'resist','cưỡng lại; chống lại; chịu được','verb','[{"en":"I couldn''t resist eating another piece of chocolate cake.","vi":"Tôi không cưỡng lại được, lại ăn thêm một miếng bánh sô-cô-la."},{"en":"Many workers resisted the changes to their working hours.","vi":"Nhiều công nhân chống lại những thay đổi về giờ làm việc của họ."},{"en":"This jacket is designed to resist wind and rain.","vi":"Chiếc áo khoác này được thiết kế để chống gió và mưa."}]','[{"phrase":"resist temptation"},{"phrase":"can''t resist"},{"phrase":"resist change"}]','resist + V-ing: cưỡng lại việc làm gì','/rɪˈzɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resis/resist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2368,'ngsl-5-14',7,'capability','khả năng, năng lực','noun','[{"en":"This phone has the capability to take very clear photos at night.","vi":"Chiếc điện thoại này có khả năng chụp ảnh rất rõ vào ban đêm."},{"en":"Running a marathon is beyond my capabilities right now.","vi":"Chạy marathon hiện đang vượt quá khả năng của tôi."},{"en":"The company wants to improve its production capabilities next year.","vi":"Công ty muốn nâng cao năng lực sản xuất vào năm tới."}]','[{"phrase":"have the capability to"},{"phrase":"beyond your capabilities"},{"phrase":"technical capability"}]',NULL,'/ˌkeɪpəˈbɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capab/capability__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2369,'ngsl-5-14',8,'absolute','tuyệt đối; hoàn toàn','adjective','[{"en":"I have absolute trust in my doctor.","vi":"Tôi tin tưởng tuyệt đối vào bác sĩ của mình."},{"en":"The party was an absolute disaster from start to finish.","vi":"Bữa tiệc hoàn toàn là một thảm họa từ đầu đến cuối."},{"en":"Absolute silence is required during the exam.","vi":"Trong giờ thi phải giữ im lặng tuyệt đối."}]','[{"phrase":"absolute silence"},{"phrase":"absolute disaster"},{"phrase":"absolute confidence"},{"phrase":"absolute truth"}]',NULL,'/ˈæbsəluːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/absol/absolute__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2370,'ngsl-5-14',9,'correspond','tương ứng; khớp với; trao đổi thư từ','verb','[{"en":"The numbers on the map correspond to the hotels listed below.","vi":"Các con số trên bản đồ tương ứng với những khách sạn được liệt kê bên dưới."},{"en":"His story doesn''t correspond with what his sister told us.","vi":"Câu chuyện của anh ấy không khớp với những gì em gái anh ấy kể với chúng tôi."},{"en":"We corresponded by email for a year before we finally met.","vi":"Chúng tôi viết email qua lại suốt một năm trước khi cuối cùng cũng gặp nhau."}]','[{"phrase":"correspond to"},{"phrase":"correspond with"},{"phrase":"closely correspond"}]','correspond to/with sth: tương ứng, khớp với cái gì','/ˌkɔːrəˈspɑːnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corre/correspond__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2371,'ngsl-5-14',10,'stroke','đột quỵ; nét (bút, cọ); cú đánh','noun','[{"en":"My grandfather had a stroke last year, but he''s recovering well.","vi":"Ông tôi bị đột quỵ năm ngoái, nhưng ông đang hồi phục tốt."},{"en":"She painted the sky with a few quick strokes of her brush.","vi":"Cô ấy vẽ bầu trời chỉ bằng vài nét cọ nhanh."},{"en":"It took her only three strokes to get the ball into the hole.","vi":"Cô ấy chỉ mất ba cú đánh để đưa bóng vào lỗ."}]','[{"phrase":"have a stroke"},{"phrase":"brush stroke"},{"phrase":"stroke of luck"}]','a stroke of luck: một dịp may bất ngờ','/strəʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strok/stroke__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2372,'ngsl-5-14',11,'dare','dám; thách','verb','[{"en":"I didn''t dare tell my parents that I had failed the test.","vi":"Tôi không dám nói với bố mẹ rằng mình đã trượt bài kiểm tra."},{"en":"How dare you read my messages without asking!","vi":"Sao bạn dám đọc tin nhắn của tôi mà không hỏi!"},{"en":"My friends dared me to jump into the cold lake.","vi":"Bạn bè thách tôi nhảy xuống cái hồ lạnh."}]','[{"phrase":"how dare you"},{"phrase":"wouldn''t dare"},{"phrase":"dare to ask"}]','dare (to) + V: dám làm gì · dare sb to + V: thách ai làm gì','/der/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dar/dare_/dare__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2373,'ngsl-5-14',12,'barrier','rào chắn; rào cản','noun','[{"en":"Police put up barriers to keep the crowd off the road.","vi":"Cảnh sát dựng rào chắn để đám đông không tràn xuống đường."},{"en":"The language barrier was hard for us when we first moved abroad.","vi":"Rào cản ngôn ngữ rất khó khăn với chúng tôi khi mới chuyển ra nước ngoài."},{"en":"Cost is still the main barrier to college for many families.","vi":"Chi phí vẫn là rào cản chính để vào đại học đối với nhiều gia đình."}]','[{"phrase":"language barrier"},{"phrase":"barrier to"},{"phrase":"put up a barrier"},{"phrase":"break down barriers"}]',NULL,'/ˈbæriər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bar/barri/barrier__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2374,'ngsl-5-14',13,'rid','loại bỏ, vứt bỏ; thoát khỏi','verb','[{"en":"We need to get rid of these old clothes before we move.","vi":"Chúng ta cần bỏ bớt mấy bộ quần áo cũ này trước khi chuyển nhà."},{"en":"I just can''t get rid of this terrible headache.","vi":"Tôi không sao dứt được cơn đau đầu khủng khiếp này."},{"en":"The city is working hard to rid the streets of trash.","vi":"Thành phố đang nỗ lực dọn sạch rác trên các con phố."}]','[{"phrase":"get rid of"},{"phrase":"be rid of"},{"phrase":"rid somebody of"}]','rid – rid – rid; thường gặp nhất: get rid of','/rɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rid/rid__/rid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2375,'ngsl-5-14',14,'divorce','sự ly hôn','noun','[{"en":"Her parents got a divorce when she was ten.","vi":"Bố mẹ cô ấy ly hôn khi cô ấy mười tuổi."},{"en":"After the divorce, he moved to a small apartment downtown.","vi":"Sau khi ly hôn, anh ấy chuyển đến một căn hộ nhỏ ở trung tâm thành phố."},{"en":"Their marriage ended in divorce after twenty years.","vi":"Cuộc hôn nhân của họ kết thúc bằng việc ly hôn sau hai mươi năm."}]','[{"phrase":"get a divorce"},{"phrase":"end in divorce"},{"phrase":"file for divorce"},{"phrase":"divorce rate"}]','Cũng là động từ: divorce sb (ly hôn với ai)','/dɪˈvɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/divor/divorce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2376,'ngsl-5-14',15,'ruin','làm hỏng, phá hỏng; tàn phá','verb','[{"en":"The heavy rain completely ruined our picnic in the park.","vi":"Cơn mưa lớn đã phá hỏng hoàn toàn buổi dã ngoại của chúng tôi trong công viên."},{"en":"Please don''t tell me the ending, or you''ll ruin the movie.","vi":"Làm ơn đừng kể cái kết, nếu không bạn sẽ làm hỏng bộ phim mất."},{"en":"My little brother ruined the surprise by telling Mom about the party.","vi":"Em trai tôi đã làm hỏng sự bất ngờ khi kể cho mẹ về bữa tiệc."}]','[{"phrase":"completely ruin"},{"phrase":"ruin the surprise"},{"phrase":"ruin somebody''s day"}]',NULL,'/ˈruːɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rui/ruin_/ruin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2377,'ngsl-5-14',16,'bury','chôn, chôn cất; vùi','verb','[{"en":"Our dog likes to bury bones in the backyard.","vi":"Con chó nhà tôi thích chôn xương ở sân sau."},{"en":"My grandmother is buried in the small village where she was born.","vi":"Bà tôi được chôn cất ở ngôi làng nhỏ nơi bà sinh ra."},{"en":"She buried her face in her hands and started to cry.","vi":"Cô ấy vùi mặt vào hai bàn tay và bắt đầu khóc."}]','[{"phrase":"be buried in"},{"phrase":"buried treasure"},{"phrase":"bury your face in your hands"}]','bury – buried – buried','/ˈberi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/bury_/bury__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2378,'ngsl-5-14',17,'counsel','tư vấn; khuyên','verb','[{"en":"She counsels students who are having problems at school.","vi":"Cô ấy tư vấn cho những học sinh đang gặp khó khăn ở trường."},{"en":"Most experts counsel against buying a house in a hurry.","vi":"Hầu hết các chuyên gia khuyên không nên mua nhà một cách vội vàng."},{"en":"He has counseled many couples through difficult times.","vi":"Anh ấy đã tư vấn cho nhiều cặp vợ chồng vượt qua những giai đoạn khó khăn."}]','[{"phrase":"counsel against"},{"phrase":"counsel patients"},{"phrase":"legal counsel"}]','Anh: counselled · Mỹ: counseled','/ˈkaʊnsl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/couns/counsel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2379,'ngsl-5-14',18,'tendency','xu hướng, khuynh hướng; thói quen','noun','[{"en":"He has a tendency to talk too much when he''s nervous.","vi":"Anh ấy có xu hướng nói quá nhiều khi lo lắng."},{"en":"There is a growing tendency for young people to live alone.","vi":"Người trẻ ngày càng có xu hướng sống một mình."},{"en":"My sister''s tendency to arrive late drives everyone crazy.","vi":"Thói quen hay đến muộn của em gái tôi khiến mọi người phát điên."}]','[{"phrase":"have a tendency to"},{"phrase":"growing tendency"},{"phrase":"natural tendency"}]',NULL,'/ˈtendənsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tende/tendency__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2380,'ngsl-5-14',19,'frequent','thường xuyên','adjective','[{"en":"She is a frequent visitor to our restaurant.","vi":"Cô ấy là khách thường xuyên của nhà hàng chúng tôi."},{"en":"Buses to the airport are frequent, so you won''t wait long.","vi":"Xe buýt ra sân bay chạy thường xuyên nên bạn sẽ không phải chờ lâu."},{"en":"He made frequent trips to the city for work last year.","vi":"Năm ngoái anh ấy thường xuyên lên thành phố công tác."}]','[{"phrase":"frequent visitor"},{"phrase":"frequent trips"},{"phrase":"frequent use"}]',NULL,'/ˈfriːkwənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/frequ/frequent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2381,'ngsl-5-14',20,'motor','động cơ, mô-tơ','noun','[{"en":"The boat has a small electric motor at the back.","vi":"Chiếc thuyền có một động cơ điện nhỏ ở phía sau."},{"en":"My washing machine stopped working because the motor burned out.","vi":"Máy giặt của tôi ngừng chạy vì mô-tơ bị cháy."},{"en":"The fan makes a strange noise, so the motor might be broken.","vi":"Cái quạt kêu lạ nên có lẽ mô-tơ bị hỏng rồi."}]','[{"phrase":"electric motor"},{"phrase":"small motor"},{"phrase":"motor vehicle"}]',NULL,'/ˈməʊtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motor/motor__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2382,'ngsl-5-14',21,'survival','sự sống sót; sự tồn tại','noun','[{"en":"Water is essential for survival in the desert.","vi":"Nước rất cần thiết để sống sót trong sa mạc."},{"en":"The doctors said his chances of survival were very good.","vi":"Các bác sĩ nói cơ hội sống sót của anh ấy rất cao."},{"en":"Many small shops are fighting for survival in this economy.","vi":"Nhiều cửa hàng nhỏ đang vật lộn để tồn tại trong nền kinh tế hiện nay."}]','[{"phrase":"chance of survival"},{"phrase":"fight for survival"},{"phrase":"survival rate"}]',NULL,'/sərˈvaɪvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/survi/survival__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2383,'ngsl-5-14',22,'counter','quầy; mặt bàn bếp','noun','[{"en":"Please pay for your items at the counter.","vi":"Vui lòng thanh toán các món hàng tại quầy."},{"en":"The woman behind the counter gave me the wrong change.","vi":"Người phụ nữ đứng sau quầy thối nhầm tiền cho tôi."},{"en":"She left her keys on the kitchen counter this morning.","vi":"Sáng nay cô ấy để quên chìa khóa trên mặt bàn bếp."}]','[{"phrase":"behind the counter"},{"phrase":"kitchen counter"},{"phrase":"check-in counter"}]',NULL,'/ˈkaʊntər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/counter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2384,'ngsl-5-14',23,'possess','sở hữu; có (phẩm chất, khả năng)','verb','[{"en":"He possesses a large collection of old coins.","vi":"Ông ấy sở hữu một bộ sưu tập tiền xu cổ lớn."},{"en":"Very few people possess the ability to stay calm in an emergency.","vi":"Rất ít người có khả năng giữ bình tĩnh trong tình huống khẩn cấp."},{"en":"He sold almost everything he possessed and traveled the world.","vi":"Anh ấy bán gần như mọi thứ mình sở hữu rồi đi du lịch khắp thế giới."}]','[{"phrase":"possess the ability"},{"phrase":"possess skills"},{"phrase":"possess a quality"}]',NULL,'/pəˈzes/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posse/possess__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2385,'ngsl-5-14',24,'permission','sự cho phép','noun','[{"en":"You need permission from your parents to go on the trip.","vi":"Bạn cần được bố mẹ cho phép thì mới được tham gia chuyến đi."},{"en":"Did you ask permission before you took his car?","vi":"Bạn đã xin phép trước khi lấy xe của anh ấy chưa?"},{"en":"The company gave us permission to work from home on Fridays.","vi":"Công ty cho phép chúng tôi làm việc tại nhà vào các ngày thứ Sáu."}]','[{"phrase":"ask permission"},{"phrase":"give permission"},{"phrase":"without permission"},{"phrase":"get permission"}]','Không đếm được','/pərˈmɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/permi/permission__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2386,'ngsl-5-14',25,'valley','thung lũng','noun','[{"en":"Their small village lies in a green valley between two mountains.","vi":"Ngôi làng nhỏ của họ nằm trong một thung lũng xanh giữa hai ngọn núi."},{"en":"From the top of the hill, we could see the whole valley.","vi":"Từ đỉnh đồi, chúng tôi có thể nhìn thấy toàn bộ thung lũng."},{"en":"A river runs through the valley and into the sea.","vi":"Một con sông chảy qua thung lũng rồi đổ ra biển."}]','[{"phrase":"deep valley"},{"phrase":"river valley"},{"phrase":"green valley"}]',NULL,'/ˈvæli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/valle/valley__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2387,'ngsl-5-14',26,'float','nổi; trôi','verb','[{"en":"Wood floats on water, but most stones sink.","vi":"Gỗ nổi trên mặt nước, còn phần lớn đá thì chìm."},{"en":"We watched the clouds float slowly across the sky.","vi":"Chúng tôi ngắm những đám mây trôi chầm chậm trên bầu trời."},{"en":"The kids lay on their backs and floated in the pool.","vi":"Bọn trẻ nằm ngửa và thả nổi trong hồ bơi."}]','[{"phrase":"float on water"},{"phrase":"float away"},{"phrase":"float in the air"}]',NULL,'/fləʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/float/float__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2388,'ngsl-5-14',27,'mad','tức giận; điên rồ; mê (cái gì)','adjective','[{"en":"My mom will be mad at me if I come home late.","vi":"Mẹ sẽ giận tôi nếu tôi về nhà muộn."},{"en":"You must be mad to swim in the sea in winter!","vi":"Bạn chắc phải điên mới đi bơi biển vào mùa đông!"},{"en":"My little brother is mad about soccer and plays every day.","vi":"Em trai tôi mê bóng đá và ngày nào cũng chơi."}]','[{"phrase":"mad at"},{"phrase":"mad about"},{"phrase":"go mad"},{"phrase":"drive somebody mad"}]','mad at sb: giận ai · mad about sth: mê cái gì','/mæd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mad/mad__/mad__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2389,'ngsl-5-14',28,'greatly','rất nhiều, rất','adverb','[{"en":"Thank you for your help; it is greatly appreciated.","vi":"Cảm ơn bạn đã giúp đỡ, chúng tôi vô cùng biết ơn."},{"en":"Prices vary greatly from one shop to another.","vi":"Giá cả chênh lệch rất nhiều giữa các cửa hàng."},{"en":"Her English has improved greatly since she started working abroad.","vi":"Tiếng Anh của cô ấy đã tiến bộ rất nhiều từ khi cô ấy làm việc ở nước ngoài."}]','[{"phrase":"greatly appreciated"},{"phrase":"vary greatly"},{"phrase":"greatly improve"},{"phrase":"greatly reduce"}]',NULL,'/ˈɡreɪtli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/great/greatly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2390,'ngsl-5-14',29,'visible','có thể nhìn thấy; rõ rệt','adjective','[{"en":"The mountains are visible from our hotel window on clear days.","vi":"Vào những ngày trời quang, có thể nhìn thấy núi từ cửa sổ khách sạn của chúng tôi."},{"en":"The stars are barely visible in big cities because of the lights.","vi":"Ở các thành phố lớn, hầu như không nhìn thấy sao vì ánh đèn."},{"en":"There has been a visible improvement in his work this month.","vi":"Tháng này, công việc của anh ấy có sự tiến bộ rõ rệt."}]','[{"phrase":"clearly visible"},{"phrase":"barely visible"},{"phrase":"visible from"}]',NULL,'/ˈvɪzəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visib/visible__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2391,'ngsl-5-14',30,'electric','(chạy bằng) điện; sôi động','adjective','[{"en":"We''re thinking about buying an electric car next year.","vi":"Chúng tôi đang tính mua một chiếc ô tô điện vào năm sau."},{"en":"Be careful, that old electric heater gets very hot.","vi":"Cẩn thận nhé, cái máy sưởi điện cũ đó nóng lắm."},{"en":"The atmosphere at the concert last night was electric.","vi":"Bầu không khí tại buổi hòa nhạc tối qua vô cùng sôi động."}]','[{"phrase":"electric car"},{"phrase":"electric guitar"},{"phrase":"electric shock"}]','electric (chạy bằng điện) ≠ electrical (thuộc về điện nói chung)','/ɪˈlektrɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/elect/electric__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2392,'ngsl-5-15',1,'impressive','ấn tượng; gây ấn tượng mạnh','adjective','[{"en":"Your English has improved a lot; it''s really impressive.","vi":"Tiếng Anh của bạn tiến bộ nhiều lắm, thật sự rất ấn tượng."},{"en":"The hotel had an impressive view of the old city.","vi":"Khách sạn có tầm nhìn ấn tượng ra khu phố cổ."},{"en":"She gave an impressive performance at her first concert.","vi":"Cô ấy đã có một màn trình diễn ấn tượng trong buổi hòa nhạc đầu tiên."}]','[{"phrase":"very impressive"},{"phrase":"impressive performance"},{"phrase":"impressive results"},{"phrase":"impressive view"}]',NULL,'/ɪmˈpresɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impre/impressive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2393,'ngsl-5-15',2,'evolution','sự tiến hóa; sự phát triển','noun','[{"en":"Our teacher explained the theory of evolution in a simple way.","vi":"Thầy giáo giải thích thuyết tiến hóa một cách đơn giản."},{"en":"Scientists study the evolution of birds from small dinosaurs.","vi":"Các nhà khoa học nghiên cứu sự tiến hóa của loài chim từ những con khủng long nhỏ."},{"en":"The museum shows the evolution of the telephone over a hundred years.","vi":"Bảo tàng giới thiệu sự phát triển của chiếc điện thoại qua một trăm năm."}]','[{"phrase":"theory of evolution"},{"phrase":"human evolution"},{"phrase":"evolution of"}]',NULL,'/ˌevəˈluːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evo/evolu/evolution__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2394,'ngsl-5-15',3,'awareness','nhận thức; sự hiểu biết','noun','[{"en":"The campaign aims to raise awareness of the dangers of smoking.","vi":"Chiến dịch nhằm nâng cao nhận thức về tác hại của việc hút thuốc."},{"en":"There is growing awareness that sleep is important for health.","vi":"Ngày càng có nhiều người nhận thức rằng giấc ngủ quan trọng đối với sức khỏe."},{"en":"Children need more awareness of road safety when they walk to school.","vi":"Trẻ em cần hiểu biết hơn về an toàn giao thông khi đi bộ đến trường."}]','[{"phrase":"raise awareness"},{"phrase":"public awareness"},{"phrase":"growing awareness"},{"phrase":"awareness of"}]','awareness of sth','/əˈwernəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/aware/awareness__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2395,'ngsl-5-15',4,'violent','bạo lực; dữ dội','adjective','[{"en":"Parents worry that some video games are too violent for kids.","vi":"Cha mẹ lo rằng một số trò chơi điện tử quá bạo lực đối với trẻ em."},{"en":"A violent storm knocked down trees across the town last night.","vi":"Tối qua một cơn bão dữ dội đã quật đổ cây cối khắp thị trấn."},{"en":"I don''t like watching violent movies before I go to bed.","vi":"Tôi không thích xem phim bạo lực trước khi đi ngủ."}]','[{"phrase":"violent storm"},{"phrase":"violent crime"},{"phrase":"violent behavior"}]',NULL,'/ˈvaɪələnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vio/viole/violent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2396,'ngsl-5-15',5,'slave','nô lệ','noun','[{"en":"The old house was built by slaves more than two hundred years ago.","vi":"Ngôi nhà cổ này được những người nô lệ xây dựng cách đây hơn hai trăm năm."},{"en":"In the story, the young slave finally wins his freedom.","vi":"Trong câu chuyện, người nô lệ trẻ cuối cùng cũng giành được tự do."},{"en":"Don''t become a slave to your phone; put it away sometimes.","vi":"Đừng trở thành nô lệ của điện thoại; thỉnh thoảng hãy cất nó đi."}]','[{"phrase":"slave trade"},{"phrase":"former slave"},{"phrase":"slave to"}]',NULL,'/sleɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sla/slave/slave__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2397,'ngsl-5-15',6,'wealthy','giàu có','adjective','[{"en":"Her grandparents were wealthy farmers who owned a lot of land.","vi":"Ông bà cô ấy là những nông dân giàu có sở hữu rất nhiều đất."},{"en":"Only wealthy families could send their children to study abroad back then.","vi":"Hồi đó chỉ những gia đình giàu có mới có thể cho con đi du học."},{"en":"He became wealthy after selling his small company.","vi":"Ông ấy trở nên giàu có sau khi bán công ty nhỏ của mình."}]','[{"phrase":"wealthy family"},{"phrase":"wealthy people"},{"phrase":"become wealthy"}]',NULL,'/ˈwelθi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/wealt/wealthy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2398,'ngsl-5-15',7,'architecture','kiến trúc; ngành kiến trúc','noun','[{"en":"We walked around the old town admiring the beautiful architecture.","vi":"Chúng tôi đi dạo quanh phố cổ, ngắm nhìn kiến trúc tuyệt đẹp."},{"en":"My sister is studying architecture at university.","vi":"Chị tôi đang học ngành kiến trúc ở trường đại học."},{"en":"The city is famous for its modern architecture and wide streets.","vi":"Thành phố nổi tiếng với kiến trúc hiện đại và những con phố rộng."}]','[{"phrase":"modern architecture"},{"phrase":"study architecture"},{"phrase":"school of architecture"}]','không đếm được','/ˈɑːrkɪtektʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arc/archi/architecture__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2399,'ngsl-5-15',8,'acceptable','chấp nhận được; tạm được','adjective','[{"en":"Is it acceptable to wear jeans to the office?","vi":"Mặc quần jean đến văn phòng có được chấp nhận không?"},{"en":"The food was acceptable, but nothing special.","vi":"Đồ ăn tạm được, nhưng không có gì đặc biệt."},{"en":"Shouting at your coworkers is not acceptable behavior.","vi":"La hét với đồng nghiệp là hành vi không thể chấp nhận được."}]','[{"phrase":"perfectly acceptable"},{"phrase":"socially acceptable"},{"phrase":"acceptable behavior"},{"phrase":"acceptable to"}]',NULL,'/əkˈseptəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accep/acceptable__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2400,'ngsl-5-15',9,'journal','tạp chí (chuyên ngành); nhật ký','noun','[{"en":"Her research was published in a medical journal last year.","vi":"Nghiên cứu của cô ấy được đăng trên một tạp chí y khoa vào năm ngoái."},{"en":"I keep a journal and write in it every night.","vi":"Tôi có một cuốn nhật ký và viết vào đó mỗi tối."},{"en":"The professor asked us to read two articles from a science journal.","vi":"Giáo sư yêu cầu chúng tôi đọc hai bài báo trên một tạp chí khoa học."}]','[{"phrase":"keep a journal"},{"phrase":"medical journal"},{"phrase":"academic journal"}]',NULL,'/ˈdʒɜːrnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2401,'ngsl-5-15',10,'coal','than đá','noun','[{"en":"The town grew rich from its coal mines.","vi":"Thị trấn trở nên giàu có nhờ các mỏ than."},{"en":"Many power plants still burn coal to make electricity.","vi":"Nhiều nhà máy điện vẫn đốt than để sản xuất điện."},{"en":"My grandfather used to cook on a small coal stove.","vi":"Ngày xưa ông tôi từng nấu ăn bằng một cái bếp than nhỏ."}]','[{"phrase":"coal mine"},{"phrase":"burn coal"},{"phrase":"coal miner"},{"phrase":"coal industry"}]','không đếm được','/kəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coal_/coal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2402,'ngsl-5-15',11,'measurement','sự đo lường; số đo; kích thước','noun','[{"en":"The tailor took my measurements for the new suit.","vi":"Người thợ may lấy số đo của tôi để may bộ vest mới."},{"en":"Accurate measurement is very important in science experiments.","vi":"Việc đo lường chính xác rất quan trọng trong các thí nghiệm khoa học."},{"en":"Check the measurements of the room before you buy a sofa.","vi":"Hãy kiểm tra kích thước căn phòng trước khi mua ghế sofa."}]','[{"phrase":"take measurements"},{"phrase":"accurate measurement"},{"phrase":"unit of measurement"}]',NULL,'/ˈmeʒərmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mea/measu/measurement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2403,'ngsl-5-15',12,'random','ngẫu nhiên; tùy tiện','adjective','[{"en":"The computer picks a random number between one and ten.","vi":"Máy tính chọn một số ngẫu nhiên từ một đến mười."},{"en":"We asked random people on the street about their favorite food.","vi":"Chúng tôi hỏi ngẫu nhiên những người trên phố về món ăn yêu thích của họ."},{"en":"The winners will be chosen at random next Friday.","vi":"Người thắng cuộc sẽ được chọn ngẫu nhiên vào thứ Sáu tới."}]','[{"phrase":"at random"},{"phrase":"random number"},{"phrase":"random sample"},{"phrase":"completely random"}]',NULL,'/ˈrændəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/rando/random__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2404,'ngsl-5-15',13,'successfully','thành công; một cách thành công','adverb','[{"en":"She successfully passed her driving test on the first try.","vi":"Cô ấy đã vượt qua kỳ thi lái xe thành công ngay lần đầu tiên."},{"en":"The doctors successfully completed the operation in three hours.","vi":"Các bác sĩ đã hoàn thành ca phẫu thuật thành công trong ba giờ."},{"en":"Our team successfully launched the new website last month.","vi":"Nhóm chúng tôi đã ra mắt trang web mới thành công vào tháng trước."}]','[{"phrase":"successfully complete"},{"phrase":"successfully launch"},{"phrase":"successfully pass"}]',NULL,'/səkˈsesfəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/successfully__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2405,'ngsl-5-15',14,'depress','làm chán nản; làm buồn; làm giảm (giá, lương)','verb','[{"en":"Rainy weather in the winter always depresses me.","vi":"Thời tiết mưa vào mùa đông luôn làm tôi thấy chán nản."},{"en":"It depresses me to see so much trash on the beach.","vi":"Tôi thấy buồn khi nhìn thấy quá nhiều rác trên bãi biển."},{"en":"Rising unemployment can depress wages across the whole country.","vi":"Tỷ lệ thất nghiệp tăng có thể làm giảm tiền lương trên cả nước."}]','[{"phrase":"depress prices"},{"phrase":"depress wages"},{"phrase":"depress demand"}]','hay gặp: depressed (buồn chán), depressing (gây buồn chán)','/dɪˈpres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depre/depress__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2406,'ngsl-5-15',15,'illustration','hình minh họa; ví dụ minh họa','noun','[{"en":"The children''s book has colorful illustrations on every page.","vi":"Cuốn sách thiếu nhi có hình minh họa đầy màu sắc trên mỗi trang."},{"en":"Let me give you a simple illustration of how this works.","vi":"Để tôi đưa ra một ví dụ minh họa đơn giản về cách việc này hoạt động."},{"en":"She earns money by drawing illustrations for magazines.","vi":"Cô ấy kiếm tiền bằng cách vẽ tranh minh họa cho các tạp chí."}]','[{"phrase":"colorful illustrations"},{"phrase":"clear illustration"},{"phrase":"illustration of"}]',NULL,'/ˌɪləˈstreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illus/illustration__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2407,'ngsl-5-15',16,'burst','vỡ; nổ; bật (khóc, cười)','verb','[{"en":"The balloon burst when my little brother sat on it.","vi":"Quả bóng bay nổ khi em trai tôi ngồi lên nó."},{"en":"A water pipe burst in our kitchen last night.","vi":"Tối qua một ống nước trong bếp nhà tôi bị vỡ."},{"en":"She burst into tears when she heard the good news.","vi":"Cô ấy bật khóc khi nghe tin vui."}]','[{"phrase":"burst into tears"},{"phrase":"burst out laughing"},{"phrase":"burst pipe"}]','burst – burst – burst','/bɜːrst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bur/burst/burst__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2408,'ngsl-5-15',17,'privilege','đặc quyền; quyền lợi đặc biệt; vinh dự','noun','[{"en":"It was a privilege to work with such talented people.","vi":"Được làm việc với những người tài năng như vậy là một vinh dự."},{"en":"Senior staff enjoy special privileges like free parking.","vi":"Nhân viên cấp cao được hưởng những quyền lợi đặc biệt như đỗ xe miễn phí."},{"en":"Education should be a right, not a privilege.","vi":"Giáo dục nên là một quyền, không phải một đặc quyền."}]','[{"phrase":"great privilege"},{"phrase":"special privileges"},{"phrase":"have the privilege of"}]',NULL,'/ˈprɪvəlɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/privi/privilege__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2409,'ngsl-5-15',18,'buyer','người mua','noun','[{"en":"We finally found a buyer for our old car.","vi":"Cuối cùng chúng tôi cũng tìm được người mua chiếc xe cũ."},{"en":"First-time home buyers often need help from their parents.","vi":"Những người lần đầu mua nhà thường cần bố mẹ giúp đỡ."},{"en":"The buyer asked for a lower price before signing.","vi":"Người mua đề nghị giảm giá trước khi ký."}]','[{"phrase":"find a buyer"},{"phrase":"first-time buyer"},{"phrase":"potential buyer"},{"phrase":"home buyer"}]',NULL,'/ˈbaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/buy/buyer/buyer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2410,'ngsl-5-15',19,'mutual','lẫn nhau; chung','adjective','[{"en":"We met through a mutual friend at a party.","vi":"Chúng tôi quen nhau qua một người bạn chung trong một bữa tiệc."},{"en":"A good marriage is built on mutual respect.","vi":"Một cuộc hôn nhân tốt đẹp được xây dựng trên sự tôn trọng lẫn nhau."},{"en":"The decision to end the partnership was mutual.","vi":"Việc chấm dứt hợp tác là quyết định chung của cả hai bên."}]','[{"phrase":"mutual friend"},{"phrase":"mutual respect"},{"phrase":"mutual understanding"},{"phrase":"mutual benefit"}]',NULL,'/ˈmjuːtʃuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mut/mutua/mutual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2411,'ngsl-5-15',20,'rail','đường sắt; tay vịn; thanh ray','noun','[{"en":"Traveling by rail is cheaper than flying in this country.","vi":"Ở nước này, đi bằng tàu hỏa rẻ hơn đi máy bay."},{"en":"Hold on to the rail when you go down the stairs.","vi":"Hãy bám vào tay vịn khi đi xuống cầu thang."},{"en":"The city plans to build a new rail line to the airport.","vi":"Thành phố dự định xây một tuyến đường sắt mới đến sân bay."}]','[{"phrase":"by rail"},{"phrase":"rail line"},{"phrase":"rail network"},{"phrase":"rail travel"}]',NULL,'/reɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rai/rail_/rail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2412,'ngsl-5-15',21,'motivate','thúc đẩy; tạo động lực','verb','[{"en":"A good teacher knows how to motivate students.","vi":"Một giáo viên giỏi biết cách tạo động lực cho học sinh."},{"en":"What motivated you to start learning English?","vi":"Điều gì đã thúc đẩy bạn bắt đầu học tiếng Anh?"},{"en":"She is highly motivated to finish her degree this year.","vi":"Cô ấy rất có động lực để hoàn thành chương trình học trong năm nay."}]','[{"phrase":"motivate students"},{"phrase":"motivate employees"},{"phrase":"highly motivated"}]',NULL,'/ˈməʊtɪveɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motiv/motivate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2413,'ngsl-5-15',22,'laboratory','phòng thí nghiệm; phòng xét nghiệm','noun','[{"en":"The samples were sent to a laboratory for testing.","vi":"Các mẫu được gửi đến phòng thí nghiệm để xét nghiệm."},{"en":"Students must wear safety glasses in the chemistry laboratory.","vi":"Học sinh phải đeo kính bảo hộ trong phòng thí nghiệm hóa học."},{"en":"My mother works in a hospital laboratory.","vi":"Mẹ tôi làm việc trong phòng xét nghiệm của một bệnh viện."}]','[{"phrase":"research laboratory"},{"phrase":"science laboratory"},{"phrase":"laboratory test"}]','viết tắt: lab','/ˈlæbrətɔːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/labor/laboratory__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2414,'ngsl-5-15',23,'mortgage','khoản vay thế chấp (mua nhà)','noun','[{"en":"They took out a mortgage to buy their first home.","vi":"Họ vay thế chấp để mua ngôi nhà đầu tiên."},{"en":"We pay our mortgage on the first day of each month.","vi":"Chúng tôi trả tiền vay mua nhà vào ngày đầu tiên của mỗi tháng."},{"en":"It will take us twenty years to pay off the mortgage.","vi":"Chúng tôi sẽ mất hai mươi năm để trả hết khoản vay thế chấp."}]','[{"phrase":"take out a mortgage"},{"phrase":"pay off a mortgage"},{"phrase":"mortgage payment"},{"phrase":"mortgage rate"}]',NULL,'/ˈmɔːrɡɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/mortg/mortgage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2415,'ngsl-5-15',24,'promotion','sự thăng chức; khuyến mãi; sự quảng bá','noun','[{"en":"He got a promotion after working here for three years.","vi":"Anh ấy được thăng chức sau ba năm làm việc ở đây."},{"en":"The store is running a special promotion on summer clothes.","vi":"Cửa hàng đang có chương trình khuyến mãi đặc biệt cho quần áo mùa hè."},{"en":"Social media is useful for the promotion of small businesses.","vi":"Mạng xã hội rất hữu ích cho việc quảng bá các doanh nghiệp nhỏ."}]','[{"phrase":"get a promotion"},{"phrase":"sales promotion"},{"phrase":"special promotion"}]',NULL,'/prəˈməʊʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promo/promotion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2416,'ngsl-5-15',25,'passion','niềm đam mê; tình cảm mãnh liệt','noun','[{"en":"Cooking has been my passion since I was a child.","vi":"Nấu ăn là niềm đam mê của tôi từ khi còn nhỏ."},{"en":"He talks about music with real passion.","vi":"Anh ấy nói về âm nhạc với niềm đam mê thật sự."},{"en":"She has a passion for helping animals in need.","vi":"Cô ấy có niềm đam mê giúp đỡ những con vật gặp khó khăn."}]','[{"phrase":"passion for"},{"phrase":"real passion"},{"phrase":"follow your passion"},{"phrase":"share a passion"}]','passion for sth','/ˈpæʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passi/passion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2417,'ngsl-5-15',26,'champion','nhà vô địch; người đấu tranh (cho điều gì)','noun','[{"en":"Our school team became the national champion last year.","vi":"Năm ngoái đội trường chúng tôi đã trở thành nhà vô địch quốc gia."},{"en":"The world champion will defend her title next month.","vi":"Nhà vô địch thế giới sẽ bảo vệ danh hiệu của mình vào tháng tới."},{"en":"She has long been a champion of children''s education.","vi":"Bà ấy từ lâu đã là người đấu tranh cho giáo dục trẻ em."}]','[{"phrase":"world champion"},{"phrase":"national champion"},{"phrase":"defending champion"},{"phrase":"champion of"}]',NULL,'/ˈtʃæmpiən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/champ/champion__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2418,'ngsl-5-15',27,'fulfill','thực hiện (ước mơ, lời hứa); đáp ứng','verb','[{"en":"He finally fulfilled his dream of visiting Japan.","vi":"Cuối cùng anh ấy đã thực hiện được ước mơ đến thăm Nhật Bản."},{"en":"Always fulfill your promises, even the small ones.","vi":"Hãy luôn thực hiện lời hứa của mình, kể cả những lời hứa nhỏ."},{"en":"The new building does not fulfill the safety requirements.","vi":"Tòa nhà mới không đáp ứng các yêu cầu về an toàn."}]','[{"phrase":"fulfill a dream"},{"phrase":"fulfill a promise"},{"phrase":"fulfill requirements"},{"phrase":"fulfill a need"}]','Mỹ: fulfill · Anh: fulfil','/fʊˈlfɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2419,'ngsl-5-15',28,'dust','bụi','noun','[{"en":"The old books on the shelf were covered in dust.","vi":"Những cuốn sách cũ trên kệ phủ đầy bụi."},{"en":"I''m allergic to dust, so I clean my room often.","vi":"Tôi bị dị ứng với bụi nên thường xuyên dọn phòng."},{"en":"A cloud of dust rose behind the truck on the dirt road.","vi":"Một đám bụi bốc lên phía sau chiếc xe tải trên con đường đất."}]','[{"phrase":"covered in dust"},{"phrase":"cloud of dust"},{"phrase":"dust allergy"}]','không đếm được','/dʌst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dus/dust_/dust__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2420,'ngsl-5-15',29,'dedicate','cống hiến; dành (cho); đề tặng','verb','[{"en":"She dedicated her life to helping poor children.","vi":"Bà ấy đã cống hiến cả cuộc đời để giúp đỡ trẻ em nghèo."},{"en":"The company dedicates one day a month to staff training.","vi":"Công ty dành một ngày mỗi tháng cho việc đào tạo nhân viên."},{"en":"I would like to dedicate this song to my mother.","vi":"Tôi xin dành tặng bài hát này cho mẹ tôi."}]','[{"phrase":"dedicate your life to"},{"phrase":"dedicate time to"},{"phrase":"dedicate a song to"}]','dedicate sth to sb/sth','/ˈdedɪkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/ded/dedic/dedicate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2421,'ngsl-5-15',30,'roughly','khoảng, xấp xỉ; thô bạo, mạnh tay','adverb','[{"en":"The trip takes roughly two hours by car.","vi":"Chuyến đi mất khoảng hai tiếng bằng ô tô."},{"en":"Roughly half of the students live on campus.","vi":"Khoảng một nửa số sinh viên sống trong khuôn viên trường."},{"en":"Please don''t handle the boxes roughly; there are glasses inside.","vi":"Xin đừng mạnh tay với các thùng hàng; bên trong có ly thủy tinh."}]','[{"phrase":"roughly speaking"},{"phrase":"roughly half"},{"phrase":"roughly the same"},{"phrase":"treat someone roughly"}]',NULL,'/ˈrʌfli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/rough/roughly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2422,'ngsl-5-16',1,'skirt','váy; chân váy','noun','[{"en":"She bought a long blue skirt for the summer party.","vi":"Cô ấy mua một chiếc váy dài màu xanh để đi dự tiệc mùa hè."},{"en":"This skirt is too short for a job interview.","vi":"Chiếc chân váy này quá ngắn để đi phỏng vấn xin việc."},{"en":"My sister wears a skirt to work most days.","vi":"Hầu như ngày nào chị tôi cũng mặc váy đi làm."}]','[{"phrase":"long skirt"},{"phrase":"short skirt"},{"phrase":"wear a skirt"}]',NULL,'/skɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/skirt/skirt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2423,'ngsl-5-16',2,'province','tỉnh','noun','[{"en":"My grandparents live in a small village in the north of the province.","vi":"Ông bà tôi sống ở một ngôi làng nhỏ phía bắc tỉnh."},{"en":"Canada has ten provinces and three territories.","vi":"Canada có mười tỉnh bang và ba vùng lãnh thổ."},{"en":"The new highway connects our province to the capital.","vi":"Đường cao tốc mới nối tỉnh chúng tôi với thủ đô."}]','[{"phrase":"in the province"},{"phrase":"northern province"},{"phrase":"coastal province"}]',NULL,'/ˈprɑːvɪns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/provi/province__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2424,'ngsl-5-16',3,'march','diễu hành; hành quân','verb','[{"en":"The band marched through the town on the holiday.","vi":"Ban nhạc diễu hành qua thị trấn vào ngày lễ."},{"en":"The soldiers marched for hours in the heavy rain.","vi":"Những người lính hành quân hàng giờ dưới mưa lớn."},{"en":"The students marched into the hall in two neat lines.","vi":"Học sinh xếp thành hai hàng ngay ngắn tiến vào hội trường."}]','[{"phrase":"march through"},{"phrase":"march into"},{"phrase":"march down the street"}]','Viết hoa March = tháng Ba','/mɑːrtʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/march/march__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2425,'ngsl-5-16',4,'evaluation','sự đánh giá','noun','[{"en":"Every employee gets a performance evaluation at the end of the year.","vi":"Mỗi nhân viên đều được đánh giá hiệu quả công việc vào cuối năm."},{"en":"The teacher''s evaluation of my essay was very helpful.","vi":"Lời đánh giá của cô giáo về bài luận của tôi rất hữu ích."},{"en":"We need a careful evaluation of the costs before we decide.","vi":"Chúng ta cần đánh giá kỹ các chi phí trước khi quyết định."}]','[{"phrase":"performance evaluation"},{"phrase":"careful evaluation"},{"phrase":"evaluation of"}]',NULL,'/ɪˌvæljuˈeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eva/evalu/evaluation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2426,'ngsl-5-16',5,'compromise','sự thỏa hiệp; sự nhượng bộ','noun','[{"en":"After a long discussion, we finally reached a compromise.","vi":"Sau một cuộc thảo luận dài, cuối cùng chúng tôi đã đi đến thỏa hiệp."},{"en":"Eating at home on Saturday was a fair compromise for both of us.","vi":"Ăn ở nhà vào thứ Bảy là một sự thỏa hiệp hợp lý cho cả hai chúng tôi."},{"en":"Every good marriage needs some compromise from both sides.","vi":"Cuộc hôn nhân tốt nào cũng cần sự nhượng bộ từ cả hai phía."}]','[{"phrase":"reach a compromise"},{"phrase":"make compromises"},{"phrase":"fair compromise"}]',NULL,'/ˈkɑːmprəmaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/compromise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2427,'ngsl-5-16',6,'accomplish','hoàn thành; đạt được','verb','[{"en":"We accomplished a lot at work this week.","vi":"Tuần này chúng tôi đã hoàn thành được nhiều việc ở công ty."},{"en":"She finally accomplished her goal of running a marathon.","vi":"Cuối cùng cô ấy đã đạt được mục tiêu chạy một cuộc marathon."},{"en":"What do you hope to accomplish in your first year of college?","vi":"Bạn hy vọng đạt được điều gì trong năm đầu đại học?"}]','[{"phrase":"accomplish a goal"},{"phrase":"accomplish a task"},{"phrase":"accomplish a lot"}]',NULL,'/əˈkɑːmplɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accomplish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2428,'ngsl-5-16',7,'weakness','điểm yếu; sự yếu ớt','noun','[{"en":"Everyone has strengths and weaknesses, so don''t be too hard on yourself.","vi":"Ai cũng có điểm mạnh và điểm yếu, nên đừng quá khắt khe với bản thân."},{"en":"My biggest weakness is that I talk too much in meetings.","vi":"Điểm yếu lớn nhất của tôi là nói quá nhiều trong các cuộc họp."},{"en":"After the fever, he felt a strange weakness in his legs.","vi":"Sau cơn sốt, anh ấy thấy chân yếu đi một cách lạ thường."}]','[{"phrase":"strengths and weaknesses"},{"phrase":"biggest weakness"},{"phrase":"have a weakness for"}]',NULL,'/ˈwiːknəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weakn/weakness__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2429,'ngsl-5-16',8,'announcement','thông báo; lời công bố','noun','[{"en":"Please listen carefully to the announcement about the train delay.","vi":"Xin hãy nghe kỹ thông báo về việc tàu bị trễ."},{"en":"The company made an announcement about new working hours.","vi":"Công ty đã ra thông báo về giờ làm việc mới."},{"en":"Their wedding announcement surprised all of their friends.","vi":"Việc họ công bố đám cưới khiến tất cả bạn bè bất ngờ."}]','[{"phrase":"make an announcement"},{"phrase":"official announcement"},{"phrase":"announcement about"}]',NULL,'/əˈnaʊnsmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annou/announcement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2430,'ngsl-5-16',9,'salt','muối','noun','[{"en":"Could you pass me the salt, please?","vi":"Bạn đưa giúp tôi lọ muối được không?"},{"en":"Add a pinch of salt to the boiling water.","vi":"Cho một nhúm muối vào nước đang sôi."},{"en":"Eating too much salt is bad for your heart.","vi":"Ăn quá nhiều muối có hại cho tim."}]','[{"phrase":"a pinch of salt"},{"phrase":"salt and pepper"},{"phrase":"sea salt"}]','không đếm được','/sɔːlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sal/salt_/salt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2431,'ngsl-5-16',10,'glance','liếc nhìn; nhìn lướt qua','verb','[{"en":"She glanced at her watch and hurried out of the room.","vi":"Cô ấy liếc nhìn đồng hồ rồi vội vã ra khỏi phòng."},{"en":"He glanced through the menu and ordered a coffee.","vi":"Anh ấy nhìn lướt qua thực đơn rồi gọi một ly cà phê."},{"en":"I glanced back and saw my dog following me.","vi":"Tôi liếc nhìn lại phía sau và thấy con chó đang đi theo mình."}]','[{"phrase":"glance at"},{"phrase":"glance through"},{"phrase":"glance back"}]',NULL,'/ɡlæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gla/glanc/glance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2432,'ngsl-5-16',11,'opera','nhạc kịch opera','noun','[{"en":"My parents love going to the opera on special occasions.","vi":"Bố mẹ tôi thích đi xem opera vào những dịp đặc biệt."},{"en":"She has sung in several famous operas around the world.","vi":"Cô ấy đã hát trong nhiều vở opera nổi tiếng trên khắp thế giới."},{"en":"The opera house in our city is beautiful at night.","vi":"Nhà hát opera ở thành phố chúng tôi về đêm rất đẹp."}]','[{"phrase":"opera house"},{"phrase":"opera singer"},{"phrase":"go to the opera"}]',NULL,'/ˈɑːprə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/opera__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2433,'ngsl-5-16',12,'contest','cuộc thi','noun','[{"en":"My daughter won first prize in a singing contest.","vi":"Con gái tôi đã đoạt giải nhất trong một cuộc thi hát."},{"en":"The school holds a writing contest every spring.","vi":"Mùa xuân nào trường cũng tổ chức một cuộc thi viết."},{"en":"He entered the photo contest but didn''t win anything.","vi":"Anh ấy tham gia cuộc thi ảnh nhưng không đoạt giải nào."}]','[{"phrase":"win a contest"},{"phrase":"enter a contest"},{"phrase":"singing contest"}]',NULL,'/ˈkɑːntest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2434,'ngsl-5-16',13,'brush','chải; đánh (răng); phủi','verb','[{"en":"Don''t forget to brush your teeth before bed.","vi":"Đừng quên đánh răng trước khi đi ngủ."},{"en":"She brushed her daughter''s hair every morning before school.","vi":"Sáng nào cô ấy cũng chải tóc cho con gái trước khi đi học."},{"en":"He brushed the snow off his car and drove to work.","vi":"Anh ấy phủi tuyết khỏi xe rồi lái xe đi làm."}]','[{"phrase":"brush your teeth"},{"phrase":"brush your hair"},{"phrase":"brush off"}]','Cũng là danh từ: bàn chải; cái cọ','/brʌʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bru/brush/brush__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2435,'ngsl-5-16',14,'embarrass','làm xấu hổ; làm ngượng','verb','[{"en":"Please don''t embarrass me in front of my friends.","vi":"Làm ơn đừng làm tôi xấu hổ trước mặt bạn bè."},{"en":"It embarrassed him that he couldn''t remember her name.","vi":"Anh ấy thấy ngượng vì không nhớ nổi tên cô ấy."},{"en":"I was afraid I would embarrass myself during the speech.","vi":"Tôi sợ mình sẽ bị bẽ mặt trong lúc phát biểu."}]','[{"phrase":"embarrass someone"},{"phrase":"embarrass yourself"}]','embarrassed (adj): thấy ngượng · embarrassing (adj): gây ngượng','/ɪmˈbærəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emb/embar/embarrass__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2436,'ngsl-5-16',15,'gallery','phòng trưng bày (tranh, ảnh)','noun','[{"en":"We spent the afternoon at a small art gallery downtown.","vi":"Chúng tôi dành cả buổi chiều ở một phòng tranh nhỏ trong trung tâm."},{"en":"Her paintings are now shown in a gallery in the city center.","vi":"Tranh của cô ấy hiện được trưng bày tại một phòng tranh ở trung tâm thành phố."},{"en":"The museum''s new gallery is full of old photographs.","vi":"Phòng trưng bày mới của bảo tàng có rất nhiều ảnh cũ."}]','[{"phrase":"art gallery"},{"phrase":"gallery owner"},{"phrase":"photo gallery"}]',NULL,'/ˈɡæləri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gal/galle/gallery__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2437,'ngsl-5-16',16,'genetic','(thuộc) di truyền; (thuộc) gen','adjective','[{"en":"The doctor suggested genetic testing because the disease runs in the family.","vi":"Bác sĩ đề nghị xét nghiệm gen vì căn bệnh này có tính di truyền trong gia đình."},{"en":"Eye color mostly depends on genetic factors.","vi":"Màu mắt chủ yếu phụ thuộc vào yếu tố di truyền."},{"en":"Scientists are studying the genetic differences between these two plants.","vi":"Các nhà khoa học đang nghiên cứu sự khác biệt về gen giữa hai loài cây này."}]','[{"phrase":"genetic testing"},{"phrase":"genetic factors"},{"phrase":"genetic disease"}]',NULL,'/dʒəˈnetɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/genet/genetic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2438,'ngsl-5-16',17,'aggressive','hung hăng; quyết liệt','adjective','[{"en":"Our neighbor''s dog becomes aggressive when strangers come near the gate.","vi":"Con chó nhà hàng xóm trở nên hung hăng khi người lạ đến gần cổng."},{"en":"He became aggressive and started shouting at the waiter.","vi":"Anh ta trở nên hung hăng và bắt đầu quát tháo người phục vụ."},{"en":"The company is using aggressive marketing to attract young customers.","vi":"Công ty đang tiếp thị quyết liệt để thu hút khách hàng trẻ."}]','[{"phrase":"aggressive behavior"},{"phrase":"become aggressive"},{"phrase":"aggressive marketing"}]',NULL,'/əˈɡresɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agg/aggre/aggressive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2439,'ngsl-5-16',18,'chest','ngực; cái rương','noun','[{"en":"He felt a sharp pain in his chest while running.","vi":"Anh ấy thấy đau nhói ở ngực khi đang chạy."},{"en":"She held the baby close to her chest.","vi":"Cô ấy ôm đứa bé sát vào ngực."},{"en":"We found old letters in a wooden chest in the attic.","vi":"Chúng tôi tìm thấy những lá thư cũ trong một chiếc rương gỗ trên gác mái."}]','[{"phrase":"chest pain"},{"phrase":"wooden chest"},{"phrase":"treasure chest"}]',NULL,'/tʃest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chest/chest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2440,'ngsl-5-16',19,'format','định dạng; hình thức','noun','[{"en":"Please send the report in PDF format by Friday.","vi":"Vui lòng gửi báo cáo ở định dạng PDF trước thứ Sáu."},{"en":"My old laptop can''t open this file format.","vi":"Máy tính xách tay cũ của tôi không mở được định dạng tệp này."},{"en":"The show has a new format this season with fewer guests.","vi":"Mùa này chương trình có hình thức mới với ít khách mời hơn."}]','[{"phrase":"file format"},{"phrase":"digital format"},{"phrase":"new format"}]',NULL,'/ˈfɔːrmæt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/format__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2441,'ngsl-5-16',20,'literary','(thuộc) văn học','adjective','[{"en":"She writes for a small literary magazine in her free time.","vi":"Lúc rảnh cô ấy viết bài cho một tạp chí văn học nhỏ."},{"en":"The novel won a major literary prize last year.","vi":"Cuốn tiểu thuyết đã đoạt một giải thưởng văn học lớn vào năm ngoái."},{"en":"The writer is famous for her simple literary style.","vi":"Nhà văn ấy nổi tiếng với lối văn giản dị."}]','[{"phrase":"literary magazine"},{"phrase":"literary prize"},{"phrase":"literary style"}]',NULL,'/ˈlɪtəreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/liter/literary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2442,'ngsl-5-16',21,'govern','cai trị; quản lý; chi phối','verb','[{"en":"The king governed the country fairly for forty years.","vi":"Nhà vua đã cai trị đất nước một cách công bằng suốt bốn mươi năm."},{"en":"A board of five members governs the city library.","vi":"Một hội đồng gồm năm thành viên quản lý thư viện thành phố."},{"en":"Strict rules govern the use of the school laboratory.","vi":"Việc sử dụng phòng thí nghiệm của trường chịu sự chi phối của các quy định nghiêm ngặt."}]','[{"phrase":"govern the country"},{"phrase":"rules governing"},{"phrase":"laws governing"}]',NULL,'/ˈɡʌvərn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gov/gover/govern__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2443,'ngsl-5-16',22,'embrace','ôm; đón nhận','verb','[{"en":"She embraced her son warmly at the airport.","vi":"Cô ấy ôm chầm lấy con trai một cách trìu mến ở sân bay."},{"en":"Our school quickly embraced the new online learning system.","vi":"Trường chúng tôi nhanh chóng đón nhận hệ thống học trực tuyến mới."},{"en":"Older workers are sometimes slow to embrace change.","vi":"Những người lao động lớn tuổi đôi khi chậm đón nhận sự thay đổi."}]','[{"phrase":"embrace warmly"},{"phrase":"embrace change"},{"phrase":"embrace new ideas"}]',NULL,'/ɪmˈbreɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emb/embra/embrace__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2444,'ngsl-5-16',23,'praise','khen ngợi; ca ngợi','verb','[{"en":"The teacher praised her for her hard work.","vi":"Cô giáo khen ngợi bạn ấy vì sự chăm chỉ."},{"en":"Parents should praise their children when they try their best.","vi":"Cha mẹ nên khen con khi chúng cố gắng hết sức."},{"en":"The new restaurant has been highly praised by local food writers.","vi":"Nhà hàng mới được các cây bút ẩm thực địa phương hết lời ca ngợi."}]','[{"phrase":"praise someone for"},{"phrase":"highly praised"},{"phrase":"widely praised"}]','Cũng là danh từ (không đếm được): lời khen','/preɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/prais/praise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2445,'ngsl-5-16',24,'silent','im lặng; yên tĩnh','adjective','[{"en":"Everyone went silent when the teacher walked in.","vi":"Mọi người im bặt khi thầy giáo bước vào."},{"en":"The house was completely silent after the children went to bed.","vi":"Ngôi nhà hoàn toàn yên tĩnh sau khi bọn trẻ đi ngủ."},{"en":"He stayed silent and didn''t answer my question.","vi":"Anh ấy im lặng và không trả lời câu hỏi của tôi."}]','[{"phrase":"remain silent"},{"phrase":"go silent"},{"phrase":"completely silent"}]',NULL,'/ˈsaɪlənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silen/silent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2446,'ngsl-5-16',25,'pump','máy bơm; cái bơm','noun','[{"en":"I borrowed a pump from my neighbor to fill my bike tires.","vi":"Tôi mượn hàng xóm cái bơm để bơm lốp xe đạp."},{"en":"The water pump in our building broke again last night.","vi":"Máy bơm nước trong tòa nhà chúng tôi lại hỏng tối qua."},{"en":"He stopped at the gas pump to fill up his car.","vi":"Anh ấy dừng lại ở trụ bơm xăng để đổ đầy xăng cho xe."}]','[{"phrase":"water pump"},{"phrase":"bicycle pump"},{"phrase":"gas pump"}]','Cũng là động từ: bơm','/pʌmp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pum/pump_/pump__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2447,'ngsl-5-16',26,'publisher','nhà xuất bản','noun','[{"en":"She finally found a publisher for her first novel.","vi":"Cuối cùng cô ấy cũng tìm được nhà xuất bản cho cuốn tiểu thuyết đầu tay."},{"en":"The publisher plans to print ten thousand copies of the book.","vi":"Nhà xuất bản dự định in mười nghìn bản cuốn sách này."},{"en":"He works as an editor at a children''s book publisher.","vi":"Anh ấy làm biên tập viên ở một nhà xuất bản sách thiếu nhi."}]','[{"phrase":"find a publisher"},{"phrase":"book publisher"},{"phrase":"major publisher"}]',NULL,'/ˈpʌblɪʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publisher__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2448,'ngsl-5-16',27,'celebration','lễ kỷ niệm; sự ăn mừng','noun','[{"en":"We had a small celebration for my grandmother''s eightieth birthday.","vi":"Chúng tôi tổ chức một buổi lễ nhỏ mừng sinh nhật lần thứ tám mươi của bà."},{"en":"The whole town joined the New Year celebrations in the square.","vi":"Cả thị trấn cùng tham gia lễ mừng năm mới ở quảng trường."},{"en":"Passing all your exams is definitely a cause for celebration.","vi":"Đỗ tất cả các kỳ thi chắc chắn là chuyện đáng để ăn mừng."}]','[{"phrase":"birthday celebration"},{"phrase":"cause for celebration"},{"phrase":"in celebration of"}]',NULL,'/ˌselɪˈbreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cel/celeb/celebration__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2449,'ngsl-5-16',28,'golf','môn đánh gôn','noun','[{"en":"My father plays golf with his friends every Sunday morning.","vi":"Sáng Chủ nhật nào bố tôi cũng chơi gôn với bạn bè."},{"en":"They built a new golf course near the lake.","vi":"Họ đã xây một sân gôn mới gần hồ."},{"en":"She took golf lessons during her summer vacation.","vi":"Cô ấy đã học chơi gôn trong kỳ nghỉ hè."}]','[{"phrase":"play golf"},{"phrase":"golf course"},{"phrase":"golf club"}]','không đếm được','/ɡɑːlf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gol/golf_/golf__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2450,'ngsl-5-16',29,'compensation','tiền bồi thường; sự đền bù; thù lao','noun','[{"en":"The airline offered us compensation for the long delay.","vi":"Hãng hàng không đề nghị bồi thường cho chúng tôi vì chuyến bay trễ lâu."},{"en":"Workers injured on the job can ask for compensation.","vi":"Người lao động bị thương khi làm việc có thể yêu cầu được đền bù."},{"en":"The job offers good compensation and flexible hours.","vi":"Công việc này có thù lao tốt và giờ giấc linh hoạt."}]','[{"phrase":"compensation for"},{"phrase":"receive compensation"},{"phrase":"pay compensation"}]','không đếm được','/ˌkɑːmpenˈseɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/compensation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2451,'ngsl-5-16',30,'classical','cổ điển','adjective','[{"en":"My mother listens to classical music while she cooks.","vi":"Mẹ tôi nghe nhạc cổ điển trong lúc nấu ăn."},{"en":"He studied classical ballet for ten years.","vi":"Anh ấy đã học múa ba lê cổ điển suốt mười năm."},{"en":"The building is designed in a classical style with tall columns.","vi":"Tòa nhà được thiết kế theo phong cách cổ điển với những cột cao."}]','[{"phrase":"classical music"},{"phrase":"classical ballet"},{"phrase":"classical style"}]','classical (cổ điển) ≠ classic (kinh điển)','/ˈklæsɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/classical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2452,'ngsl-5-17',1,'weigh','cân; nặng (bao nhiêu); cân nhắc','verb','[{"en":"How much does your suitcase weigh after packing all the gifts?","vi":"Vali của bạn nặng bao nhiêu sau khi xếp hết quà vào?"},{"en":"The nurse weighed the baby and wrote the number down.","vi":"Y tá cân em bé rồi ghi lại con số."},{"en":"You should weigh the pros and cons before changing jobs.","vi":"Bạn nên cân nhắc ưu và nhược điểm trước khi đổi việc."}]','[{"phrase":"weigh the pros and cons"},{"phrase":"weigh the options"},{"phrase":"carefully weigh"}]',NULL,'/weɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wei/weigh/weigh__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2453,'ngsl-5-17',2,'versus','đấu với; so với','preposition','[{"en":"Tonight''s match is our school versus the team from the next town.","vi":"Trận đấu tối nay là trường mình đấu với đội đến từ thị trấn bên cạnh."},{"en":"We compared the cost of renting versus buying a home.","vi":"Chúng tôi đã so sánh chi phí giữa việc thuê nhà và mua nhà."},{"en":"For me, it''s always a question of quality versus quantity.","vi":"Với tôi, vấn đề luôn là chất lượng so với số lượng."}]','[{"phrase":"quality versus quantity"},{"phrase":"cost versus benefit"}]','viết tắt: vs.','/ˈvɜːrsəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/versu/versus__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2454,'ngsl-5-17',3,'deficit','thâm hụt; khoản thiếu hụt','noun','[{"en":"The company ran a deficit for the second year in a row.","vi":"Công ty bị thâm hụt năm thứ hai liên tiếp."},{"en":"The government plans to reduce the budget deficit next year.","vi":"Chính phủ dự định giảm thâm hụt ngân sách vào năm sau."},{"en":"The country has a large trade deficit with its neighbors.","vi":"Nước này bị thâm hụt thương mại lớn với các nước láng giềng."}]','[{"phrase":"budget deficit"},{"phrase":"trade deficit"},{"phrase":"reduce the deficit"}]',NULL,'/ˈdefɪsɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defic/deficit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2455,'ngsl-5-17',4,'modify','sửa đổi; điều chỉnh','verb','[{"en":"We slightly modified the recipe to make it less sweet.","vi":"Chúng tôi đã điều chỉnh công thức một chút để món ăn bớt ngọt."},{"en":"You can modify your booking online up to 24 hours before arrival.","vi":"Bạn có thể sửa đổi thông tin đặt chỗ trên mạng chậm nhất 24 giờ trước khi đến."},{"en":"The car was modified to run on electricity.","vi":"Chiếc xe đã được sửa đổi để chạy bằng điện."}]','[{"phrase":"slightly modify"},{"phrase":"modify the design"},{"phrase":"modify the rules"}]',NULL,'/ˈmɑːdɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/modif/modify__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2456,'ngsl-5-17',5,'flash','lóe lên; nháy (đèn)','verb','[{"en":"Lightning flashed across the sky before the rain started.","vi":"Tia chớp lóe lên trên bầu trời trước khi trời đổ mưa."},{"en":"The driver behind us kept flashing his headlights.","vi":"Tài xế phía sau cứ nháy đèn pha với chúng tôi."},{"en":"An idea suddenly flashed through my mind during the meeting.","vi":"Một ý tưởng chợt lóe lên trong đầu tôi lúc đang họp."}]','[{"phrase":"lights flash"},{"phrase":"flash your headlights"},{"phrase":"flash through your mind"}]',NULL,'/flæʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fla/flash/flash__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2457,'ngsl-5-17',6,'friendship','tình bạn','noun','[{"en":"Their close friendship began on the first day of college.","vi":"Tình bạn thân thiết của họ bắt đầu từ ngày đầu tiên học đại học."},{"en":"I value our friendship more than anything else.","vi":"Tôi trân trọng tình bạn của chúng ta hơn bất cứ điều gì."},{"en":"Can a friendship survive when you live in different countries?","vi":"Tình bạn có thể bền lâu không khi mỗi người sống ở một nước khác?"}]','[{"phrase":"close friendship"},{"phrase":"lifelong friendship"},{"phrase":"value friendship"}]',NULL,'/ˈfrendʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fri/frien/friendship__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2458,'ngsl-5-17',7,'profession','nghề nghiệp; ngành nghề','noun','[{"en":"Nursing is a demanding profession, but she loves it.","vi":"Điều dưỡng là một nghề vất vả, nhưng cô ấy rất yêu nghề."},{"en":"What made you decide to join the medical profession?","vi":"Điều gì khiến bạn quyết định theo ngành y?"},{"en":"He is a lawyer by profession, but he writes novels too.","vi":"Nghề chính của anh ấy là luật sư, nhưng anh ấy cũng viết tiểu thuyết."}]','[{"phrase":"medical profession"},{"phrase":"teaching profession"},{"phrase":"by profession"}]',NULL,'/prəˈfeʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/profession__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2459,'ngsl-5-17',8,'literally','theo nghĩa đen; thật sự','adverb','[{"en":"Don''t take his joke literally; he was only teasing you.","vi":"Đừng hiểu câu đùa của anh ấy theo nghĩa đen, anh ấy chỉ trêu bạn thôi."},{"en":"I was so busy that I literally had no time to eat.","vi":"Tôi bận đến mức thật sự không có thời gian ăn."},{"en":"The hotel is literally five minutes from the beach.","vi":"Khách sạn thật sự chỉ cách bãi biển năm phút."}]','[{"phrase":"take something literally"},{"phrase":"quite literally"},{"phrase":"translate literally"}]',NULL,'/ˈlɪtərəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/liter/literally__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2460,'ngsl-5-17',9,'equation','phương trình; vấn đề cần cân nhắc','noun','[{"en":"Can you help me solve this equation for my math homework?","vi":"Bạn giúp mình giải phương trình này trong bài tập toán được không?"},{"en":"The teacher wrote a long equation on the board.","vi":"Giáo viên viết một phương trình dài lên bảng."},{"en":"When choosing a job, salary is only one part of the equation.","vi":"Khi chọn việc, lương chỉ là một phần trong những điều cần cân nhắc."}]','[{"phrase":"solve an equation"},{"phrase":"simple equation"},{"phrase":"part of the equation"}]',NULL,'/ɪˈkweɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equat/equation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2461,'ngsl-5-17',10,'gesture','cử chỉ; nghĩa cử','noun','[{"en":"She made a gesture for me to sit down.","vi":"Cô ấy ra dấu bảo tôi ngồi xuống."},{"en":"Sending flowers to your new neighbors is a nice gesture.","vi":"Gửi hoa tặng hàng xóm mới là một cử chỉ đẹp."},{"en":"In some cultures, this hand gesture is considered rude.","vi":"Ở một số nền văn hóa, cử chỉ tay này bị coi là bất lịch sự."}]','[{"phrase":"make a gesture"},{"phrase":"nice gesture"},{"phrase":"hand gesture"}]',NULL,'/ˈdʒestʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/ges/gestu/gesture__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2462,'ngsl-5-17',11,'entertain','giải trí; mua vui; tiếp đãi (khách)','verb','[{"en":"The clown entertained the children for over an hour.","vi":"Chú hề mua vui cho bọn trẻ suốt hơn một tiếng."},{"en":"We love entertaining guests at home on weekends.","vi":"Chúng tôi thích tiếp đãi khách tại nhà vào cuối tuần."},{"en":"This book will keep you entertained on a long flight.","vi":"Cuốn sách này sẽ giúp bạn giải trí trên chuyến bay dài."}]','[{"phrase":"entertain guests"},{"phrase":"keep someone entertained"},{"phrase":"entertain the crowd"}]',NULL,'/ˌentərˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/enter/entertain__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2463,'ngsl-5-17',12,'fantastic','tuyệt vời; tuyệt diệu','adjective','[{"en":"We had a fantastic time at your wedding last weekend.","vi":"Chúng tôi đã có khoảng thời gian tuyệt vời ở đám cưới của bạn cuối tuần trước."},{"en":"You look fantastic in that blue dress!","vi":"Bạn mặc chiếc váy xanh dương đó trông tuyệt lắm!"},{"en":"The view from the top of the mountain was absolutely fantastic.","vi":"Quang cảnh từ đỉnh núi thật sự tuyệt vời."}]','[{"phrase":"fantastic time"},{"phrase":"fantastic opportunity"},{"phrase":"absolutely fantastic"},{"phrase":"look fantastic"}]',NULL,'/fænˈtæstɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fan/fanta/fantastic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2464,'ngsl-5-17',13,'assign','giao (việc); phân công; chỉ định','verb','[{"en":"Our teacher assigned us a lot of homework over the holiday.","vi":"Cô giáo giao cho chúng tôi rất nhiều bài tập về nhà trong kỳ nghỉ."},{"en":"The manager assigned three people to work on the new project.","vi":"Quản lý đã phân công ba người làm dự án mới."},{"en":"You will be assigned a seat when you check in.","vi":"Bạn sẽ được chỉ định chỗ ngồi khi làm thủ tục."}]','[{"phrase":"assign homework"},{"phrase":"assign a task"},{"phrase":"assign someone to a project"}]',NULL,'/əˈsaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assig/assign__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2465,'ngsl-5-17',14,'inflation','lạm phát','noun','[{"en":"Inflation has made groceries much more expensive this year.","vi":"Lạm phát khiến thực phẩm năm nay đắt hơn nhiều."},{"en":"Our salaries haven''t kept up with inflation.","vi":"Lương của chúng tôi không theo kịp lạm phát."},{"en":"The bank expects the inflation rate to fall next year.","vi":"Ngân hàng dự đoán tỷ lệ lạm phát sẽ giảm vào năm sau."}]','[{"phrase":"inflation rate"},{"phrase":"high inflation"},{"phrase":"keep up with inflation"}]','không đếm được','/ɪnˈfleɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infla/inflation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2466,'ngsl-5-17',15,'historic','có ý nghĩa lịch sử; cổ kính','adjective','[{"en":"We walked around the historic center of the town.","vi":"Chúng tôi đi dạo quanh khu trung tâm cổ kính của thị trấn."},{"en":"Winning the cup was a historic moment for our small club.","vi":"Giành cúp là một khoảnh khắc lịch sử đối với câu lạc bộ nhỏ của chúng tôi."},{"en":"This historic building is over three hundred years old.","vi":"Tòa nhà cổ kính này đã hơn ba trăm năm tuổi."}]','[{"phrase":"historic building"},{"phrase":"historic moment"},{"phrase":"historic site"}]','historic (có ý nghĩa lịch sử) ≠ historical (thuộc về lịch sử)','/hɪˈstɔːrɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/historic__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2467,'ngsl-5-17',16,'injure','làm bị thương; gây chấn thương','verb','[{"en":"She injured her knee while playing basketball with friends.","vi":"Cô ấy bị chấn thương đầu gối khi chơi bóng rổ với bạn bè."},{"en":"Be careful not to injure yourself when lifting heavy boxes.","vi":"Cẩn thận kẻo bị thương khi nâng những thùng nặng."},{"en":"Luckily, nobody was seriously injured in the accident.","vi":"May mắn là không ai bị thương nặng trong vụ tai nạn."}]','[{"phrase":"seriously injured"},{"phrase":"badly injured"},{"phrase":"injure yourself"}]',NULL,'/ˈɪndʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inj/injur/injure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2468,'ngsl-5-17',17,'remote','xa xôi; hẻo lánh; từ xa','adjective','[{"en":"They live in a remote village high in the mountains.","vi":"Họ sống ở một ngôi làng hẻo lánh trên núi cao."},{"en":"Many companies now allow remote work a few days a week.","vi":"Hiện nay nhiều công ty cho phép làm việc từ xa vài ngày mỗi tuần."},{"en":"Where did you put the remote control for the TV?","vi":"Bạn để cái điều khiển từ xa của TV ở đâu rồi?"}]','[{"phrase":"remote area"},{"phrase":"remote village"},{"phrase":"remote work"},{"phrase":"remote control"}]',NULL,'/rɪˈməʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remot/remote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2469,'ngsl-5-17',18,'therapy','liệu pháp; trị liệu','noun','[{"en":"After the accident, he needed months of physical therapy.","vi":"Sau tai nạn, anh ấy cần vật lý trị liệu trong nhiều tháng."},{"en":"Music therapy can help children who often feel anxious.","vi":"Liệu pháp âm nhạc có thể giúp những trẻ hay lo âu."},{"en":"Going to therapy helped me handle stress at work.","vi":"Đi trị liệu tâm lý đã giúp tôi đối phó với căng thẳng trong công việc."}]','[{"phrase":"physical therapy"},{"phrase":"music therapy"},{"phrase":"speech therapy"}]',NULL,'/ˈθerəpi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/thera/therapy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2470,'ngsl-5-17',19,'orange','quả cam; màu cam','noun','[{"en":"I drink a glass of fresh orange juice every morning.","vi":"Mỗi sáng tôi uống một ly nước cam tươi."},{"en":"Could you peel an orange for your little brother?","vi":"Con bóc một quả cam cho em trai được không?"},{"en":"The sky turned a beautiful orange as the sun went down.","vi":"Bầu trời chuyển sang màu cam tuyệt đẹp khi mặt trời lặn."}]','[{"phrase":"orange juice"},{"phrase":"peel an orange"},{"phrase":"bright orange"}]',NULL,'/ˈɔːrɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ora/orang/orange__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2471,'ngsl-5-17',20,'twist','vặn; xoắn; trẹo (chân, tay)','verb','[{"en":"Twist the lid to the left to open the jar.","vi":"Vặn nắp sang trái để mở lọ."},{"en":"I twisted my ankle while running down the stairs.","vi":"Tôi bị trẹo mắt cá chân khi chạy xuống cầu thang."},{"en":"He twisted the two wires together to fix the lamp.","vi":"Anh ấy xoắn hai sợi dây điện lại với nhau để sửa đèn."}]','[{"phrase":"twist your ankle"},{"phrase":"twist the lid"},{"phrase":"twist and turn"}]',NULL,'/twɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/twi/twist/twist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2472,'ngsl-6-01',1,'personnel','nhân sự; nhân viên','noun','[{"en":"All personnel must wear a badge inside the building.","vi":"Tất cả nhân viên phải đeo thẻ khi ở trong tòa nhà."},{"en":"The company plans to cut personnel costs next year.","vi":"Công ty dự định cắt giảm chi phí nhân sự vào năm tới."},{"en":"Medical personnel arrived at the scene within minutes.","vi":"Nhân viên y tế đã có mặt tại hiện trường chỉ trong vài phút."}]','[{"phrase":"medical personnel"},{"phrase":"military personnel"},{"phrase":"personnel costs"},{"phrase":"key personnel"}]','Thường dùng với động từ số nhiều; ≠ personal (adj): cá nhân','/ˌpɜːrsəˈnel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perso/personnel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2473,'ngsl-6-01',2,'imagination','trí tưởng tượng; óc sáng tạo','noun','[{"en":"Children have a wonderful imagination and love telling stories.","vi":"Trẻ em có trí tưởng tượng tuyệt vời và rất thích kể chuyện."},{"en":"Use your imagination and draw whatever you like.","vi":"Hãy dùng trí tưởng tượng của bạn và vẽ bất cứ thứ gì bạn thích."},{"en":"This job requires imagination and a lot of hard work.","vi":"Công việc này đòi hỏi óc sáng tạo và rất nhiều sự chăm chỉ."}]','[{"phrase":"use your imagination"},{"phrase":"vivid imagination"},{"phrase":"capture the imagination"}]',NULL,'/ɪˌmædʒɪˈneɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/imagi/imagination__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2474,'ngsl-6-01',3,'disagree','không đồng ý; bất đồng','verb','[{"en":"I disagree with you about the price of the house.","vi":"Tôi không đồng ý với bạn về giá của căn nhà."},{"en":"My parents often disagree about where to go on vacation.","vi":"Bố mẹ tôi thường bất đồng về việc đi nghỉ ở đâu."},{"en":"Few people would disagree that exercise is good for you.","vi":"Ít ai lại không đồng ý rằng tập thể dục tốt cho sức khỏe."}]','[{"phrase":"disagree with"},{"phrase":"strongly disagree"},{"phrase":"disagree about"}]','disagree with sb / about sth','/ˌdɪsəˈɡriː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disag/disagree__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2475,'ngsl-6-01',4,'throat','cổ họng','noun','[{"en":"I have a sore throat and a slight fever.","vi":"Tôi bị đau họng và hơi sốt."},{"en":"She cleared her throat before she began to speak.","vi":"Cô ấy hắng giọng trước khi bắt đầu nói."},{"en":"A small fish bone got stuck in his throat.","vi":"Một cái xương cá nhỏ bị mắc trong cổ họng anh ấy."}]','[{"phrase":"sore throat"},{"phrase":"clear your throat"},{"phrase":"dry throat"}]',NULL,'/θrəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/throa/throat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2476,'ngsl-6-01',5,'insight','sự hiểu biết sâu sắc; cái nhìn sâu sắc','noun','[{"en":"This book gives us an insight into life in the 1800s.","vi":"Cuốn sách này cho chúng ta cái nhìn sâu sắc về cuộc sống vào thế kỷ 19."},{"en":"Her comments offered some useful insights into the problem.","vi":"Những nhận xét của cô ấy mang lại vài hiểu biết hữu ích về vấn đề này."},{"en":"Talking to customers gave us valuable insight into what they want.","vi":"Trò chuyện với khách hàng giúp chúng tôi hiểu sâu sắc hơn về những gì họ muốn."}]','[{"phrase":"insight into"},{"phrase":"valuable insight"},{"phrase":"gain insight"},{"phrase":"provide insight"}]','insight into sth','/ˈɪnsaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insig/insight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2477,'ngsl-6-01',6,'tackle','giải quyết; xử lý','verb','[{"en":"We need to tackle the problem before it gets worse.","vi":"Chúng ta cần giải quyết vấn đề trước khi nó trở nên tệ hơn."},{"en":"How should I tackle a big project with a short deadline?","vi":"Tôi nên xử lý một dự án lớn có thời hạn ngắn như thế nào?"},{"en":"The city is tackling traffic by building more bike lanes.","vi":"Thành phố đang giải quyết nạn kẹt xe bằng cách làm thêm làn đường cho xe đạp."}]','[{"phrase":"tackle the problem"},{"phrase":"tackle an issue"},{"phrase":"tackle crime"}]',NULL,'/ˈtækl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tac/tackl/tackle__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2478,'ngsl-6-01',7,'forever','mãi mãi; rất lâu','adverb','[{"en":"I will remember this special day forever.","vi":"Tôi sẽ nhớ mãi ngày đặc biệt này."},{"en":"Nothing lasts forever, so enjoy the good times.","vi":"Không có gì tồn tại mãi mãi, vì vậy hãy tận hưởng những lúc tốt đẹp."},{"en":"The bus took forever to arrive this morning.","vi":"Sáng nay phải chờ rất lâu xe buýt mới đến."}]','[{"phrase":"last forever"},{"phrase":"take forever"},{"phrase":"live forever"}]','take forever (khẩu ngữ): mất rất nhiều thời gian','/fərˈevər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forev/forever__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2479,'ngsl-6-01',8,'exceed','vượt quá; vượt','verb','[{"en":"Drivers who exceed the speed limit will be fined.","vi":"Tài xế nào chạy quá tốc độ cho phép sẽ bị phạt."},{"en":"The final cost exceeded our budget by ten percent.","vi":"Chi phí cuối cùng vượt quá ngân sách của chúng tôi mười phần trăm."},{"en":"The hotel was lovely and exceeded all our expectations.","vi":"Khách sạn rất đẹp và vượt xa mọi kỳ vọng của chúng tôi."}]','[{"phrase":"exceed the speed limit"},{"phrase":"exceed expectations"},{"phrase":"exceed the budget"}]',NULL,'/ɪkˈsiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excee/exceed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2480,'ngsl-6-01',9,'expenditure','chi tiêu; khoản chi','noun','[{"en":"Our monthly expenditure on food has gone up a lot.","vi":"Chi tiêu hằng tháng cho thực phẩm của chúng tôi đã tăng lên nhiều."},{"en":"The school wants to reduce its expenditure on electricity.","vi":"Nhà trường muốn cắt giảm khoản chi cho tiền điện."},{"en":"Public expenditure on health care rose again last year.","vi":"Chi tiêu công cho y tế lại tăng vào năm ngoái."}]','[{"phrase":"public expenditure"},{"phrase":"expenditure on"},{"phrase":"reduce expenditure"},{"phrase":"government expenditure"}]','expenditure on sth','/ɪkˈspendɪtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expen/expenditure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2481,'ngsl-6-01',10,'joy','niềm vui; nỗi vui sướng','noun','[{"en":"The children jumped for joy when they saw the snow.","vi":"Bọn trẻ nhảy cẫng lên vì vui sướng khi nhìn thấy tuyết."},{"en":"Holding her baby for the first time filled her with joy.","vi":"Lần đầu được bế con khiến cô ấy tràn ngập niềm vui."},{"en":"Cooking for friends is one of my greatest joys.","vi":"Nấu ăn cho bạn bè là một trong những niềm vui lớn nhất của tôi."}]','[{"phrase":"jump for joy"},{"phrase":"tears of joy"},{"phrase":"great joy"}]',NULL,'/dʒɔɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/joy/joy__/joy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2482,'ngsl-6-01',11,'pregnant','có thai; mang bầu','adjective','[{"en":"My sister is pregnant with her second child.","vi":"Chị gái tôi đang mang thai đứa con thứ hai."},{"en":"She was seven months pregnant when she stopped working.","vi":"Cô ấy nghỉ làm khi đang mang thai được bảy tháng."},{"en":"Pregnant women are advised not to drink any alcohol.","vi":"Phụ nữ mang thai được khuyên không nên uống rượu bia."}]','[{"phrase":"get pregnant"},{"phrase":"pregnant women"},{"phrase":"months pregnant"}]',NULL,'/ˈpreɡnənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/pregn/pregnant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2483,'ngsl-6-01',12,'reliable','đáng tin cậy','adjective','[{"en":"I need a reliable car for my daily trip to work.","vi":"Tôi cần một chiếc xe đáng tin cậy để đi làm hằng ngày."},{"en":"Is this website a reliable source of information?","vi":"Trang web này có phải là nguồn thông tin đáng tin cậy không?"},{"en":"She''s always on time and very reliable.","vi":"Cô ấy luôn đúng giờ và rất đáng tin cậy."}]','[{"phrase":"reliable source"},{"phrase":"reliable information"},{"phrase":"highly reliable"}]',NULL,'/rɪˈlaɪəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relia/reliable__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2484,'ngsl-6-01',13,'gear','đồ nghề; thiết bị; số (xe)','noun','[{"en":"Don''t forget to pack your camping gear.","vi":"Đừng quên xếp đồ cắm trại của bạn vào túi nhé."},{"en":"Cyclists should always wear the right safety gear.","vi":"Người đi xe đạp nên luôn mang đồ bảo hộ phù hợp."},{"en":"Put the car in first gear and slowly drive forward.","vi":"Hãy vào số một rồi từ từ cho xe chạy lên phía trước."}]','[{"phrase":"camping gear"},{"phrase":"safety gear"},{"phrase":"first gear"}]','Nghĩa đồ nghề, thiết bị: không đếm được','/ɡɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gea/gear_/gear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2485,'ngsl-6-01',14,'click','nhấp (chuột); bấm','verb','[{"en":"Click the link below to download the file.","vi":"Nhấp vào đường liên kết bên dưới để tải tệp xuống."},{"en":"I clicked on the photo to make it bigger.","vi":"Tôi nhấp vào bức ảnh để phóng to nó."},{"en":"Click the Save button before you close the document.","vi":"Hãy bấm nút Lưu trước khi đóng tài liệu."}]','[{"phrase":"click on"},{"phrase":"click the link"},{"phrase":"click the button"}]','click (on) sth','/klɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/click/click__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2486,'ngsl-6-01',15,'poet','nhà thơ','noun','[{"en":"My grandfather was a poet and wrote about nature.","vi":"Ông tôi là một nhà thơ và viết về thiên nhiên."},{"en":"The poet read several of his poems to the students.","vi":"Nhà thơ đọc một vài bài thơ của mình cho các học sinh nghe."},{"en":"She dreamed of becoming a famous poet one day.","vi":"Cô ấy mơ ước một ngày nào đó trở thành nhà thơ nổi tiếng."}]','[{"phrase":"famous poet"},{"phrase":"great poet"},{"phrase":"young poet"}]',NULL,'/ˈpəʊət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poe/poet_/poet__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2487,'ngsl-6-01',16,'fortune','gia tài; khoản tiền lớn; vận may','noun','[{"en":"He made a fortune selling houses in the city.","vi":"Anh ấy kiếm được cả gia tài nhờ bán nhà ở thành phố."},{"en":"That new phone must have cost a fortune.","vi":"Chiếc điện thoại mới đó chắc hẳn tốn cả đống tiền."},{"en":"We had the good fortune to meet a kind local guide.","vi":"Chúng tôi may mắn gặp được một hướng dẫn viên địa phương tốt bụng."}]','[{"phrase":"make a fortune"},{"phrase":"cost a fortune"},{"phrase":"good fortune"},{"phrase":"small fortune"}]',NULL,'/ˈfɔːrtʃən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/fortu/fortune__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2488,'ngsl-6-01',17,'ceremony','buổi lễ; nghi lễ','noun','[{"en":"The wedding ceremony will take place in the garden.","vi":"Lễ cưới sẽ được tổ chức trong khu vườn."},{"en":"Hundreds of parents attended the graduation ceremony.","vi":"Hàng trăm phụ huynh đã tham dự lễ tốt nghiệp."},{"en":"An opening ceremony was held for the new bridge.","vi":"Một buổi lễ khánh thành đã được tổ chức cho cây cầu mới."}]','[{"phrase":"wedding ceremony"},{"phrase":"opening ceremony"},{"phrase":"graduation ceremony"},{"phrase":"attend a ceremony"}]',NULL,'/ˈserəməʊni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cer/cerem/ceremony__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2489,'ngsl-6-01',18,'pile','đống; chồng','noun','[{"en":"There''s a pile of dirty clothes on the bedroom floor.","vi":"Có một đống quần áo bẩn trên sàn phòng ngủ."},{"en":"She put the letters in a neat pile on my desk.","vi":"Cô ấy xếp các lá thư thành một chồng gọn gàng trên bàn tôi."},{"en":"I have piles of homework to finish this weekend.","vi":"Cuối tuần này tôi có hàng đống bài tập về nhà phải làm xong."}]','[{"phrase":"a pile of"},{"phrase":"piles of"},{"phrase":"neat pile"}]',NULL,'/paɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pil/pile_/pile__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2490,'ngsl-6-01',19,'pig','con lợn; con heo','noun','[{"en":"My uncle keeps pigs and chickens on his farm.","vi":"Chú tôi nuôi lợn và gà ở trang trại của chú."},{"en":"The little pig was rolling happily in the mud.","vi":"Chú lợn con đang lăn lộn vui vẻ trong bùn."},{"en":"Pigs are actually very clever and clean animals.","vi":"Lợn thực ra là loài vật rất thông minh và sạch sẽ."}]','[{"phrase":"keep pigs"},{"phrase":"pig farm"},{"phrase":"pig farmer"}]',NULL,'/pɪɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pig/pig__/pig__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2491,'ngsl-6-01',20,'mixture','hỗn hợp; sự pha trộn','noun','[{"en":"Pour the mixture into a pan and bake for 30 minutes.","vi":"Đổ hỗn hợp vào khuôn và nướng trong 30 phút."},{"en":"Stir the flour and milk until the mixture is smooth.","vi":"Khuấy bột mì và sữa cho đến khi hỗn hợp mịn."},{"en":"I felt a strange mixture of excitement and fear.","vi":"Tôi cảm thấy một sự pha trộn kỳ lạ giữa háo hức và sợ hãi."}]','[{"phrase":"a mixture of"},{"phrase":"strange mixture"},{"phrase":"cake mixture"}]',NULL,'/ˈmɪkstʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mix/mixtu/mixture__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2492,'ngsl-6-01',21,'automatically','tự động; theo phản xạ','adverb','[{"en":"The lights turn on automatically when someone enters the room.","vi":"Đèn tự động bật khi có người bước vào phòng."},{"en":"Your changes will be saved automatically every five minutes.","vi":"Các thay đổi của bạn sẽ được tự động lưu sau mỗi năm phút."},{"en":"When the phone rang, I automatically reached for it.","vi":"Khi điện thoại reo, tôi theo phản xạ với tay lấy nó."}]','[{"phrase":"turn on automatically"},{"phrase":"happen automatically"},{"phrase":"automatically update"}]',NULL,'/ˌɔːtəˈmætɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autom/automatically__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2493,'ngsl-6-01',22,'scholar','học giả','noun','[{"en":"She is a respected scholar of Asian history.","vi":"Bà ấy là một học giả uy tín về lịch sử châu Á."},{"en":"Scholars have studied this old book for many years.","vi":"Các học giả đã nghiên cứu cuốn sách cổ này trong nhiều năm."},{"en":"The university invited a visiting scholar to give a talk.","vi":"Trường đại học đã mời một học giả thỉnh giảng đến nói chuyện."}]','[{"phrase":"visiting scholar"},{"phrase":"leading scholar"},{"phrase":"respected scholar"}]',NULL,'/ˈskɑːlər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schol/scholar__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2494,'ngsl-6-01',23,'psychological','thuộc về tâm lý; tinh thần','adjective','[{"en":"Losing a job can have serious psychological effects.","vi":"Mất việc có thể gây ra những ảnh hưởng tâm lý nghiêm trọng."},{"en":"The problem is psychological rather than physical.","vi":"Vấn đề nằm ở tâm lý chứ không phải ở thể chất."},{"en":"Athletes need psychological strength as well as physical training.","vi":"Vận động viên cần sức mạnh tinh thần cũng như sự rèn luyện thể chất."}]','[{"phrase":"psychological effects"},{"phrase":"psychological problems"},{"phrase":"psychological pressure"},{"phrase":"psychological support"}]',NULL,'/ˌsaɪkəˈlɑːdʒɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/psy/psych/psychological__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2495,'ngsl-6-01',24,'dramatically','đáng kể; mạnh mẽ; đột ngột','adverb','[{"en":"House prices have risen dramatically in the last few years.","vi":"Giá nhà đã tăng mạnh trong vài năm qua."},{"en":"Her English improved dramatically after a year abroad.","vi":"Tiếng Anh của cô ấy tiến bộ vượt bậc sau một năm ở nước ngoài."},{"en":"The weather changed dramatically, and it started to snow.","vi":"Thời tiết thay đổi đột ngột và trời bắt đầu có tuyết."}]','[{"phrase":"change dramatically"},{"phrase":"increase dramatically"},{"phrase":"rise dramatically"},{"phrase":"improve dramatically"}]',NULL,'/drəˈmætɪkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/dramatically__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2496,'ngsl-6-01',25,'stake','cổ phần; điều được mất','noun','[{"en":"The company bought a 20 percent stake in the hotel.","vi":"Công ty đã mua 20% cổ phần của khách sạn."},{"en":"Our jobs are at stake if the project fails.","vi":"Công việc của chúng tôi sẽ bị đe dọa nếu dự án thất bại."},{"en":"With so much money at stake, everyone felt nervous.","vi":"Có quá nhiều tiền có nguy cơ mất trắng nên ai cũng thấy lo lắng."}]','[{"phrase":"at stake"},{"phrase":"a stake in"},{"phrase":"high stakes"},{"phrase":"majority stake"}]','at stake: đang bị đe dọa, có nguy cơ mất','/steɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stake/stake__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2497,'ngsl-6-01',26,'creature','sinh vật; loài vật','noun','[{"en":"Many strange creatures live at the bottom of the sea.","vi":"Nhiều sinh vật kỳ lạ sống dưới đáy biển."},{"en":"Dogs are loyal creatures that need love and attention.","vi":"Chó là loài vật trung thành, cần được yêu thương và quan tâm."},{"en":"The movie is about a creature from another planet.","vi":"Bộ phim kể về một sinh vật đến từ hành tinh khác."}]','[{"phrase":"living creature"},{"phrase":"strange creature"},{"phrase":"sea creature"}]',NULL,'/ˈkriːtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/creat/creature__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2498,'ngsl-6-01',27,'partnership','sự hợp tác; quan hệ đối tác','noun','[{"en":"The two schools have formed a partnership to share resources.","vi":"Hai trường đã thiết lập quan hệ hợp tác để chia sẻ nguồn lực."},{"en":"Our company works in partnership with local farmers.","vi":"Công ty chúng tôi hợp tác với nông dân địa phương."},{"en":"Their business partnership lasted for more than twenty years.","vi":"Mối quan hệ đối tác kinh doanh của họ kéo dài hơn hai mươi năm."}]','[{"phrase":"in partnership with"},{"phrase":"form a partnership"},{"phrase":"business partnership"}]',NULL,'/ˈpɑːrtnərʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partn/partnership__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2499,'ngsl-6-01',28,'participation','sự tham gia','noun','[{"en":"Thank you for your participation in our survey.","vi":"Cảm ơn bạn đã tham gia khảo sát của chúng tôi."},{"en":"Student participation in class is part of the final grade.","vi":"Mức độ tham gia của sinh viên trên lớp được tính vào điểm tổng kết."},{"en":"The event encourages the participation of the whole community.","vi":"Sự kiện này khuyến khích sự tham gia của cả cộng đồng."}]','[{"phrase":"participation in"},{"phrase":"active participation"},{"phrase":"encourage participation"},{"phrase":"public participation"}]','participation in sth','/pɑːrˌtɪsɪˈpeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2500,'ngsl-6-01',29,'clause','điều khoản; mệnh đề','noun','[{"en":"Read every clause of the contract before you sign it.","vi":"Hãy đọc từng điều khoản trong hợp đồng trước khi ký."},{"en":"There is a clause that lets you cancel within 14 days.","vi":"Có một điều khoản cho phép bạn hủy trong vòng 14 ngày."},{"en":"A main clause can stand alone as a complete sentence.","vi":"Mệnh đề chính có thể đứng riêng như một câu hoàn chỉnh."}]','[{"phrase":"contract clause"},{"phrase":"main clause"},{"phrase":"relative clause"}]',NULL,'/klɔːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/claus/clause__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2501,'ngsl-6-02',1,'penalty','hình phạt; tiền phạt; quả phạt đền','noun','[{"en":"You will have to pay a penalty if you return the book late.","vi":"Bạn sẽ phải nộp tiền phạt nếu trả sách muộn."},{"en":"The penalty for cheating on the exam is very serious.","vi":"Hình phạt cho việc gian lận trong kỳ thi rất nặng."},{"en":"He scored from a penalty in the last minute of the game.","vi":"Anh ấy ghi bàn từ quả phạt đền ở phút cuối trận đấu."}]','[{"phrase":"pay a penalty"},{"phrase":"heavy penalty"},{"phrase":"penalty kick"}]',NULL,'/ˈpenəlti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pen/penal/penalty__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2502,'ngsl-6-02',2,'chamber','phòng; buồng; khoang','noun','[{"en":"The meeting was held in the council chamber downstairs.","vi":"Cuộc họp được tổ chức ở phòng họp hội đồng dưới tầng."},{"en":"The heart has four chambers that pump blood around the body.","vi":"Tim có bốn buồng bơm máu đi khắp cơ thể."},{"en":"Tourists can visit the old burial chamber inside the pyramid.","vi":"Du khách có thể tham quan phòng mộ cổ bên trong kim tự tháp."}]','[{"phrase":"council chamber"},{"phrase":"burial chamber"},{"phrase":"chamber of commerce"}]',NULL,'/ˈtʃeɪmbər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chamb/chamber__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2503,'ngsl-6-02',3,'fancy','sang trọng; cầu kỳ, kiểu cách','adjective','[{"en":"We went to a fancy restaurant for our wedding anniversary.","vi":"Chúng tôi đi ăn ở một nhà hàng sang trọng nhân dịp kỷ niệm ngày cưới."},{"en":"I don''t need a fancy phone, just one that works well.","vi":"Tôi không cần một chiếc điện thoại xịn, chỉ cần nó dùng tốt."},{"en":"Her dress was too fancy for a simple picnic in the park.","vi":"Chiếc váy của cô ấy quá cầu kỳ cho một buổi dã ngoại đơn giản trong công viên."}]','[{"phrase":"fancy restaurant"},{"phrase":"fancy hotel"},{"phrase":"nothing fancy"}]','Anh-Anh còn dùng làm động từ: fancy = thích, muốn','/ˈfænsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fan/fancy/fancy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2504,'ngsl-6-02',4,'poetry','thơ; thơ ca','noun','[{"en":"She has been writing poetry since she was a teenager.","vi":"Cô ấy đã làm thơ từ khi còn là thiếu niên."},{"en":"We read some Vietnamese poetry in class today.","vi":"Hôm nay chúng tôi đọc một số bài thơ Việt Nam trên lớp."},{"en":"His poetry is simple but full of feeling.","vi":"Thơ của anh ấy giản dị nhưng giàu cảm xúc."}]','[{"phrase":"write poetry"},{"phrase":"read poetry"},{"phrase":"love poetry"},{"phrase":"modern poetry"}]','không đếm được; một bài thơ = a poem','/ˈpəʊətri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poe/poetr/poetry__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2505,'ngsl-6-02',5,'chat','trò chuyện; nhắn tin trò chuyện (trên mạng)','verb','[{"en":"We chatted for hours about our school days.","vi":"Chúng tôi trò chuyện hàng giờ liền về thời đi học."},{"en":"I often chat online with my cousins in the evening.","vi":"Buổi tối tôi thường nhắn tin trò chuyện với anh chị em họ trên mạng."},{"en":"Can we chat after the meeting instead of right now?","vi":"Chúng ta nói chuyện sau cuộc họp thay vì bây giờ được không?"}]','[{"phrase":"chat with friends"},{"phrase":"chat online"},{"phrase":"have a chat"}]',NULL,'/tʃæt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chat_/chat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2506,'ngsl-6-02',6,'clothing','quần áo; trang phục','noun','[{"en":"Please bring warm clothing because it gets cold at night.","vi":"Hãy mang theo quần áo ấm vì ban đêm trời trở lạnh."},{"en":"This store sells clothing for children and teenagers.","vi":"Cửa hàng này bán quần áo cho trẻ em và thanh thiếu niên."},{"en":"Workers must wear protective clothing in the factory.","vi":"Công nhân phải mặc đồ bảo hộ trong nhà máy."}]','[{"phrase":"warm clothing"},{"phrase":"protective clothing"},{"phrase":"piece of clothing"},{"phrase":"clothing store"}]','không đếm được; một món đồ = a piece of clothing','/ˈkləʊðɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/cloth/clothing__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2507,'ngsl-6-02',7,'evolve','tiến hóa; phát triển dần','verb','[{"en":"Scientists believe that birds evolved from small dinosaurs.","vi":"Các nhà khoa học tin rằng chim tiến hóa từ những loài khủng long nhỏ."},{"en":"The small shop has slowly evolved into a large company.","vi":"Cửa hàng nhỏ ấy đã dần phát triển thành một công ty lớn."},{"en":"Language is always evolving as people find new ways to speak.","vi":"Ngôn ngữ luôn phát triển khi con người tìm ra những cách nói mới."}]','[{"phrase":"evolve from"},{"phrase":"evolve into"},{"phrase":"evolve over time"}]',NULL,'/ɪˈvɑːlv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evo/evolv/evolve__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2508,'ngsl-6-02',8,'sake','vì (lợi ích của ai/cái gì)','noun','[{"en":"She gave up sugar for the sake of her health.","vi":"Cô ấy bỏ đường vì sức khỏe của mình."},{"en":"Please be quiet for the baby''s sake; she''s finally asleep.","vi":"Làm ơn giữ yên lặng vì em bé, cuối cùng bé cũng ngủ rồi."},{"en":"Don''t change your plans just for my sake.","vi":"Đừng thay đổi kế hoạch chỉ vì tôi."}]','[{"phrase":"for the sake of"},{"phrase":"for your own sake"},{"phrase":"for safety''s sake"}]','thường dùng trong cụm for the sake of / for someone''s sake','/ˈseɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2509,'ngsl-6-02',9,'shelf','kệ; giá (để đồ)','noun','[{"en":"Put the books back on the shelf when you finish.","vi":"Hãy đặt sách lại lên kệ khi bạn đọc xong."},{"en":"The top shelf is too high for me to reach.","vi":"Kệ trên cùng cao quá, tôi với không tới."},{"en":"The store''s shelves were empty before the big storm.","vi":"Các kệ hàng của cửa hàng trống trơn trước cơn bão lớn."}]','[{"phrase":"top shelf"},{"phrase":"on the shelf"},{"phrase":"bottom shelf"}]','số nhiều: shelves','/ʃelf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/shelf/shelf__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2510,'ngsl-6-02',10,'boost','thúc đẩy; làm tăng, nâng cao','verb','[{"en":"A short walk can boost your energy in the afternoon.","vi":"Đi bộ một chút có thể giúp bạn tăng năng lượng vào buổi chiều."},{"en":"The new park has boosted tourism in our town.","vi":"Công viên mới đã thúc đẩy du lịch ở thị trấn chúng tôi."},{"en":"Winning the prize really boosted her confidence.","vi":"Việc giành giải thực sự đã nâng cao sự tự tin của cô ấy."}]','[{"phrase":"boost confidence"},{"phrase":"boost sales"},{"phrase":"boost the economy"}]',NULL,'/buːst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/boost/boost__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2511,'ngsl-6-02',11,'tail','đuôi; phần đuôi','noun','[{"en":"The dog wagged its tail when we came home.","vi":"Con chó vẫy đuôi khi chúng tôi về nhà."},{"en":"Monkeys use their long tails to hold on to branches.","vi":"Khỉ dùng chiếc đuôi dài để bám vào cành cây."},{"en":"The tail of the plane was painted bright red.","vi":"Phần đuôi máy bay được sơn màu đỏ tươi."}]','[{"phrase":"wag its tail"},{"phrase":"long tail"},{"phrase":"heads or tails"}]',NULL,'/teɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tai/tail_/tail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2512,'ngsl-6-02',12,'possession','đồ đạc, tài sản; sự sở hữu','noun','[{"en":"She packed all her possessions into two small bags.","vi":"Cô ấy xếp toàn bộ đồ đạc của mình vào hai chiếc túi nhỏ."},{"en":"This old watch is my most treasured possession.","vi":"Chiếc đồng hồ cũ này là món đồ quý giá nhất của tôi."},{"en":"Visitors must have their passports in their possession at all times.","vi":"Du khách phải luôn mang theo hộ chiếu bên mình."}]','[{"phrase":"personal possessions"},{"phrase":"prized possession"},{"phrase":"in possession of"}]',NULL,'/pəˈzeʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posse/possession__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2513,'ngsl-6-02',13,'abortion','sự phá thai','noun','[{"en":"The doctor explained the risks of abortion to the patient.","vi":"Bác sĩ giải thích cho bệnh nhân những rủi ro của việc phá thai."},{"en":"Abortion laws are different from one country to another.","vi":"Luật về phá thai khác nhau giữa các quốc gia."},{"en":"Many hospitals give advice to women who are considering an abortion.","vi":"Nhiều bệnh viện tư vấn cho những phụ nữ đang cân nhắc việc phá thai."}]','[{"phrase":"have an abortion"},{"phrase":"abortion law"}]',NULL,'/əˈbɔːrʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abo/abort/abortion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2514,'ngsl-6-02',14,'curious','tò mò; lạ, kỳ lạ','adjective','[{"en":"Children are naturally curious about the world around them.","vi":"Trẻ em vốn tò mò về thế giới xung quanh."},{"en":"I''m curious to know what happened at the party.","vi":"Tôi tò mò muốn biết chuyện gì đã xảy ra ở bữa tiệc."},{"en":"There was a curious smell coming from the kitchen.","vi":"Có một mùi lạ bốc ra từ nhà bếp."}]','[{"phrase":"curious about"},{"phrase":"curious to know"},{"phrase":"naturally curious"}]',NULL,'/ˈkjʊriəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curio/curious__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2515,'ngsl-6-02',15,'wooden','bằng gỗ','adjective','[{"en":"We sat on a wooden bench near the lake.","vi":"Chúng tôi ngồi trên một chiếc ghế dài bằng gỗ gần hồ."},{"en":"My grandfather made this wooden box by hand.","vi":"Ông tôi đã tự tay làm chiếc hộp gỗ này."},{"en":"The children played with wooden toys in the garden.","vi":"Bọn trẻ chơi đồ chơi bằng gỗ trong vườn."}]','[{"phrase":"wooden table"},{"phrase":"wooden floor"},{"phrase":"wooden box"},{"phrase":"wooden spoon"}]',NULL,'/ˈwʊdn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/woo/woode/wooden__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2516,'ngsl-6-02',16,'boom','sự bùng nổ, phát triển nhanh; tiếng nổ ầm','noun','[{"en":"The town grew quickly during the tourism boom.","vi":"Thị trấn phát triển nhanh trong thời kỳ bùng nổ du lịch."},{"en":"There has been a boom in online shopping recently.","vi":"Gần đây mua sắm trực tuyến đã bùng nổ."},{"en":"A loud boom of thunder woke the baby up.","vi":"Một tiếng sấm nổ ầm làm em bé thức giấc."}]','[{"phrase":"economic boom"},{"phrase":"baby boom"},{"phrase":"loud boom"}]',NULL,'/buːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/boo/boom_/boom__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2517,'ngsl-6-02',17,'tale','câu chuyện; truyện kể','noun','[{"en":"My grandmother used to tell us tales about her childhood.","vi":"Bà tôi thường kể cho chúng tôi nghe những câu chuyện về thời thơ ấu của bà."},{"en":"Every child in the village knows this old fairy tale.","vi":"Mọi đứa trẻ trong làng đều biết câu chuyện cổ tích xưa này."},{"en":"He came back from his trip with exciting tales of adventure.","vi":"Anh ấy trở về sau chuyến đi với những câu chuyện phiêu lưu thú vị."}]','[{"phrase":"fairy tale"},{"phrase":"folk tale"},{"phrase":"tell a tale"}]',NULL,'/teɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tal/tale_/tale__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2518,'ngsl-6-02',18,'democratic','dân chủ','adjective','[{"en":"The club makes all its decisions in a democratic way.","vi":"Câu lạc bộ đưa ra mọi quyết định một cách dân chủ."},{"en":"Our class chose its leader through a democratic vote.","vi":"Lớp chúng tôi chọn lớp trưởng qua một cuộc bỏ phiếu dân chủ."},{"en":"Free elections are an important part of a democratic society.","vi":"Bầu cử tự do là một phần quan trọng của xã hội dân chủ."}]','[{"phrase":"democratic society"},{"phrase":"democratic process"},{"phrase":"democratic country"}]',NULL,'/ˌdeməˈkrætɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/democ/democratic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2519,'ngsl-6-02',19,'maintenance','sự bảo trì; sự bảo dưỡng','noun','[{"en":"The elevator is closed for maintenance until Friday.","vi":"Thang máy tạm ngừng hoạt động để bảo trì đến thứ Sáu."},{"en":"Old cars usually need more maintenance than new ones.","vi":"Xe cũ thường cần bảo dưỡng nhiều hơn xe mới."},{"en":"The maintenance team fixes any problems in the building.","vi":"Đội bảo trì sửa mọi sự cố trong tòa nhà."}]','[{"phrase":"regular maintenance"},{"phrase":"routine maintenance"},{"phrase":"maintenance costs"}]','không đếm được','/ˈmeɪntənəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/maint/maintenance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2520,'ngsl-6-02',20,'consequently','do đó; vì vậy','adverb','[{"en":"He missed the bus and consequently arrived late for work.","vi":"Anh ấy lỡ chuyến xe buýt và vì vậy đến chỗ làm muộn."},{"en":"She studied hard and consequently passed all her exams.","vi":"Cô ấy học chăm chỉ và do đó đã đỗ tất cả các kỳ thi."},{"en":"Prices went up; consequently, fewer people bought new cars.","vi":"Giá cả tăng lên, do đó ít người mua ô tô mới hơn."}]','[{"phrase":"and consequently"},{"phrase":"is consequently"}]',NULL,'/ˈkɑːnsɪkwentli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsequently__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2521,'ngsl-6-02',21,'pot','nồi; chậu (cây); bình (trà, cà phê)','noun','[{"en":"She cooked a big pot of soup for the whole family.","vi":"Cô ấy nấu một nồi súp lớn cho cả nhà."},{"en":"I planted some tomatoes in a pot on the balcony.","vi":"Tôi trồng vài cây cà chua trong chậu ngoài ban công."},{"en":"Let me make a fresh pot of coffee for our guests.","vi":"Để tôi pha một bình cà phê mới cho khách."}]','[{"phrase":"pot of coffee"},{"phrase":"flower pot"},{"phrase":"cooking pot"}]',NULL,'/pɑːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/pot__/pot__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2522,'ngsl-6-02',22,'cow','con bò (cái)','noun','[{"en":"The farmer milks his cows early every morning.","vi":"Người nông dân vắt sữa bò vào sáng sớm mỗi ngày."},{"en":"We saw cows eating grass beside the road.","vi":"Chúng tôi thấy những con bò đang gặm cỏ bên đường."},{"en":"This cheese is made from cow''s milk.","vi":"Loại phô mai này được làm từ sữa bò."}]','[{"phrase":"milk a cow"},{"phrase":"dairy cow"},{"phrase":"cow''s milk"}]',NULL,'/kaʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cow/cow__/cow__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2523,'ngsl-6-02',23,'strengthen','làm mạnh thêm; củng cố, tăng cường','verb','[{"en":"Swimming is a great way to strengthen your back muscles.","vi":"Bơi lội là cách tuyệt vời để làm khỏe cơ lưng."},{"en":"The trip helped strengthen the friendship between our two families.","vi":"Chuyến đi đã giúp củng cố tình bạn giữa hai gia đình chúng tôi."},{"en":"Workers strengthened the old bridge before the rainy season.","vi":"Công nhân đã gia cố cây cầu cũ trước mùa mưa."}]','[{"phrase":"strengthen muscles"},{"phrase":"strengthen relationships"},{"phrase":"strengthen ties"}]',NULL,'/ˈstreŋkθn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stren/strengthen__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2524,'ngsl-6-02',24,'whilst','trong khi; trong khi đó (đối lập)','conjunction','[{"en":"Please wait here whilst I go and get the car.","vi":"Vui lòng đợi ở đây trong khi tôi đi lấy xe."},{"en":"She listened to music whilst doing her homework.","vi":"Cô ấy nghe nhạc trong khi làm bài tập về nhà."},{"en":"Some students prefer to study alone, whilst others like working in groups.","vi":"Một số sinh viên thích học một mình, trong khi những người khác thích học nhóm."}]','[{"phrase":"whilst others"},{"phrase":"whilst waiting"}]','Anh-Anh, trang trọng hơn; Mỹ thường dùng while','/waɪlst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/whils/whilst__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2525,'ngsl-6-02',25,'constraint','sự hạn chế; sự ràng buộc','noun','[{"en":"Because of time constraints, we can only answer three questions.","vi":"Vì hạn chế về thời gian, chúng tôi chỉ có thể trả lời ba câu hỏi."},{"en":"Budget constraints forced the school to cancel the trip.","vi":"Hạn chế về ngân sách buộc nhà trường phải hủy chuyến đi."},{"en":"Artists should be free to work without constraints.","vi":"Nghệ sĩ nên được tự do sáng tác mà không bị ràng buộc."}]','[{"phrase":"time constraints"},{"phrase":"budget constraints"},{"phrase":"financial constraints"}]',NULL,'/kənˈstreɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstraint__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2526,'ngsl-6-02',26,'fold','gấp, gập; khoanh (tay)','verb','[{"en":"Please fold the towels and put them in the drawer.","vi":"Làm ơn gấp khăn rồi cất vào ngăn kéo."},{"en":"She folded the letter carefully and put it in an envelope.","vi":"Cô ấy cẩn thận gấp lá thư lại rồi cho vào phong bì."},{"en":"He stood by the door with his arms folded.","vi":"Anh ấy khoanh tay đứng cạnh cửa."}]','[{"phrase":"fold clothes"},{"phrase":"fold your arms"},{"phrase":"fold in half"}]',NULL,'/fəʊld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fol/fold_/fold__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2527,'ngsl-6-02',27,'bin','thùng rác; thùng (đựng đồ)','noun','[{"en":"Please throw your empty bottles in the recycling bin.","vi":"Vui lòng bỏ chai rỗng vào thùng rác tái chế."},{"en":"I forgot to take the bins out last night.","vi":"Tối qua tôi quên mang thùng rác ra ngoài."},{"en":"We keep rice in a large plastic bin in the kitchen.","vi":"Chúng tôi đựng gạo trong một cái thùng nhựa lớn ở bếp."}]','[{"phrase":"recycling bin"},{"phrase":"rubbish bin"},{"phrase":"take the bins out"}]','Mỹ thường dùng trash can cho thùng rác','/bɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bin/bin__/bin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2528,'ngsl-6-02',28,'undergo','trải qua (thay đổi, phẫu thuật, kiểm tra)','verb','[{"en":"My father underwent surgery on his knee last month.","vi":"Tháng trước bố tôi đã trải qua ca phẫu thuật đầu gối."},{"en":"The city center is undergoing major changes this year.","vi":"Trung tâm thành phố đang trải qua những thay đổi lớn trong năm nay."},{"en":"All new cars must undergo strict safety tests.","vi":"Mọi ô tô mới đều phải trải qua các cuộc kiểm tra an toàn nghiêm ngặt."}]','[{"phrase":"undergo surgery"},{"phrase":"undergo changes"},{"phrase":"undergo tests"},{"phrase":"undergo training"}]','undergo – underwent – undergone','/ˌʌndərˈɡəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undergo__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2529,'ngsl-6-02',29,'potentially','có khả năng; có tiềm năng','adverb','[{"en":"This new medicine could potentially help millions of people.","vi":"Loại thuốc mới này có khả năng giúp được hàng triệu người."},{"en":"Driving in this weather is potentially dangerous.","vi":"Lái xe trong thời tiết này có thể gây nguy hiểm."},{"en":"The problem is small now but is potentially very serious.","vi":"Vấn đề hiện còn nhỏ nhưng có khả năng trở nên rất nghiêm trọng."}]','[{"phrase":"potentially dangerous"},{"phrase":"potentially serious"},{"phrase":"potentially useful"}]',NULL,'/pəˈtenʃəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/poten/potentially__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2530,'ngsl-6-03',1,'scope','phạm vi; cơ hội (để làm gì)','noun','[{"en":"The project was much bigger in scope than we first expected.","vi":"Dự án có phạm vi lớn hơn nhiều so với dự tính ban đầu của chúng tôi."},{"en":"That question is outside the scope of today''s meeting.","vi":"Câu hỏi đó nằm ngoài phạm vi của cuộc họp hôm nay."},{"en":"There is still plenty of scope for improvement in your writing.","vi":"Bài viết của bạn vẫn còn nhiều chỗ để cải thiện."}]','[{"phrase":"outside the scope of"},{"phrase":"beyond the scope of"},{"phrase":"scope for improvement"},{"phrase":"limited scope"}]',NULL,'/skəʊp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sco/scope/scope__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2531,'ngsl-6-03',2,'pretend','giả vờ; giả làm','verb','[{"en":"He pretended to be asleep when his mother came in.","vi":"Cậu ấy giả vờ ngủ khi mẹ bước vào."},{"en":"Please don''t pretend that you didn''t hear what I just said.","vi":"Làm ơn đừng giả vờ là bạn không nghe thấy những gì tôi vừa nói."},{"en":"The kids like to pretend they are pirates on a big ship.","vi":"Bọn trẻ thích giả làm cướp biển trên một con tàu lớn."}]','[{"phrase":"pretend to be"},{"phrase":"pretend not to notice"},{"phrase":"just pretend"}]',NULL,'/prɪˈtend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prete/pretend__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2532,'ngsl-6-03',3,'diversity','sự đa dạng','noun','[{"en":"The city is known for its cultural diversity and great food.","vi":"Thành phố này nổi tiếng với sự đa dạng văn hóa và đồ ăn ngon."},{"en":"We need more diversity in the team that makes these decisions.","vi":"Chúng ta cần sự đa dạng hơn trong nhóm đưa ra những quyết định này."},{"en":"This forest has an amazing diversity of plants and animals.","vi":"Khu rừng này có sự đa dạng đáng kinh ngạc về thực vật và động vật."}]','[{"phrase":"cultural diversity"},{"phrase":"biological diversity"},{"phrase":"a diversity of"}]',NULL,'/daɪˈvɜːrsəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/diver/diversity__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2533,'ngsl-6-03',4,'allege','cáo buộc; cho rằng (chưa có bằng chứng)','verb','[{"en":"The report alleges that the company ignored basic safety rules.","vi":"Bản báo cáo cáo buộc rằng công ty đã phớt lờ các quy định an toàn cơ bản."},{"en":"She alleged that her manager had treated her unfairly.","vi":"Cô ấy cáo buộc rằng quản lý đã đối xử bất công với mình."},{"en":"He is alleged to have taken money from the club.","vi":"Anh ta bị cho là đã lấy tiền của câu lạc bộ."}]','[{"phrase":"allege that"},{"phrase":"be alleged to have"}]','danh từ: allegation (lời cáo buộc)','/əˈledʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/alleg/allege__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2534,'ngsl-6-03',5,'pride','niềm tự hào; lòng tự trọng','noun','[{"en":"She spoke about her children with obvious pride.","vi":"Bà ấy nói về các con với niềm tự hào lộ rõ."},{"en":"He takes great pride in keeping his garden tidy.","vi":"Ông ấy rất tự hào về việc giữ khu vườn luôn gọn gàng."},{"en":"His pride stopped him from asking his friends for help.","vi":"Lòng tự trọng khiến anh ấy không chịu nhờ bạn bè giúp đỡ."}]','[{"phrase":"take pride in"},{"phrase":"great pride"},{"phrase":"a sense of pride"}]','tính từ: proud (tự hào)','/praɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/pride/pride__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2535,'ngsl-6-03',6,'intense','dữ dội, mãnh liệt; căng thẳng','adjective','[{"en":"The heat in the desert was so intense that we stayed inside.","vi":"Cái nóng ở sa mạc gay gắt đến mức chúng tôi phải ở trong nhà."},{"en":"After weeks of intense training, she was ready for the race.","vi":"Sau nhiều tuần tập luyện cường độ cao, cô ấy đã sẵn sàng cho cuộc đua."},{"en":"The final minutes of the game were really intense.","vi":"Những phút cuối của trận đấu thật sự rất căng thẳng."}]','[{"phrase":"intense heat"},{"phrase":"intense pressure"},{"phrase":"intense competition"},{"phrase":"intense training"}]',NULL,'/ɪnˈtens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intense__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2536,'ngsl-6-03',7,'inquiry','cuộc điều tra; câu hỏi, yêu cầu thông tin','noun','[{"en":"The airport has launched an inquiry into last week''s long delays.","vi":"Sân bay đã mở cuộc điều tra về tình trạng chậm trễ kéo dài vào tuần trước."},{"en":"The hotel received hundreds of inquiries about its summer offer.","vi":"Khách sạn nhận được hàng trăm yêu cầu hỏi thông tin về ưu đãi mùa hè."},{"en":"For further inquiries, please contact our customer service team.","vi":"Nếu có thắc mắc thêm, vui lòng liên hệ bộ phận chăm sóc khách hàng."}]','[{"phrase":"launch an inquiry"},{"phrase":"an inquiry into"},{"phrase":"make inquiries"},{"phrase":"public inquiry"}]','Anh thường viết: enquiry','/ˈɪnkwəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enq/enqui/enquiry__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2537,'ngsl-6-03',8,'resign','từ chức; xin nghỉ việc','verb','[{"en":"She resigned from her job to start her own business.","vi":"Cô ấy xin nghỉ việc để tự kinh doanh."},{"en":"The team''s coach resigned after a very poor season.","vi":"Huấn luyện viên của đội đã từ chức sau một mùa giải rất tệ."},{"en":"He decided to resign as president of the tennis club.","vi":"Ông ấy quyết định từ chức chủ tịch câu lạc bộ quần vợt."}]','[{"phrase":"resign from a job"},{"phrase":"resign as"},{"phrase":"decide to resign"}]','resign from + công việc; resign as + chức vụ','/rɪˈzaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resig/resign__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2538,'ngsl-6-03',9,'craft','nghề thủ công; tay nghề','noun','[{"en":"The village is famous for traditional crafts like weaving and pottery.","vi":"Ngôi làng nổi tiếng với các nghề thủ công truyền thống như dệt vải và làm gốm."},{"en":"My daughter loves arts and crafts, especially painting.","vi":"Con gái tôi rất thích thủ công mỹ thuật, nhất là vẽ tranh."},{"en":"Every good writer spends years improving their craft.","vi":"Nhà văn giỏi nào cũng dành nhiều năm để trau dồi tay nghề của mình."}]','[{"phrase":"traditional crafts"},{"phrase":"arts and crafts"},{"phrase":"craft fair"}]',NULL,'/kræft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cra/craft/craft__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2539,'ngsl-6-03',10,'strict','nghiêm khắc; nghiêm ngặt','adjective','[{"en":"My parents were very strict about bedtime when I was young.","vi":"Hồi tôi còn nhỏ, bố mẹ rất nghiêm khắc về giờ đi ngủ."},{"en":"The school has strict rules about using phones in class.","vi":"Trường có quy định nghiêm ngặt về việc dùng điện thoại trong lớp."},{"en":"She follows a strict diet before every competition.","vi":"Cô ấy theo một chế độ ăn kiêng nghiêm ngặt trước mỗi cuộc thi."}]','[{"phrase":"strict rules"},{"phrase":"strict parents"},{"phrase":"strict diet"},{"phrase":"be strict about"}]',NULL,'/strɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stric/strict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2540,'ngsl-6-03',11,'concrete','cụ thể; bằng bê tông','adjective','[{"en":"Can you give me a concrete example of what you mean?","vi":"Bạn có thể cho tôi một ví dụ cụ thể về ý bạn muốn nói không?"},{"en":"The meeting ended without any concrete plans for next year.","vi":"Cuộc họp kết thúc mà không có kế hoạch cụ thể nào cho năm sau."},{"en":"The kids sat on the concrete steps outside the library.","vi":"Bọn trẻ ngồi trên những bậc thềm bê tông bên ngoài thư viện."}]','[{"phrase":"concrete example"},{"phrase":"concrete evidence"},{"phrase":"concrete plans"},{"phrase":"concrete floor"}]','danh từ: concrete (bê tông)','/ˈkɑːnkriːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcrete__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2541,'ngsl-6-03',12,'shell','vỏ (sò, trứng, hạt); mai (rùa)','noun','[{"en":"We collected shells on the beach all afternoon.","vi":"Chúng tôi nhặt vỏ sò trên bãi biển cả buổi chiều."},{"en":"Crack the eggs gently so that no shell falls into the bowl.","vi":"Đập trứng nhẹ tay để vỏ không rơi vào bát."},{"en":"The turtle pulled its head back into its shell.","vi":"Con rùa rụt đầu vào trong mai."}]','[{"phrase":"collect shells"},{"phrase":"hard shell"},{"phrase":"come out of your shell"}]',NULL,'/ʃel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/shell/shell__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2542,'ngsl-6-03',13,'damn','chết tiệt; (nhấn mạnh) cực kỳ','exclamation','[{"en":"Damn, I left my keys at the office again!","vi":"Chết tiệt, tôi lại để quên chìa khóa ở văn phòng rồi!"},{"en":"That was a damn good meal, thank you.","vi":"Bữa ăn đó ngon cực kỳ, cảm ơn bạn."},{"en":"Damn, we just missed the last bus home.","vi":"Chết tiệt, chúng ta vừa lỡ chuyến xe buýt cuối cùng về nhà rồi."}]','[{"phrase":"damn it"},{"phrase":"damn good"},{"phrase":"not give a damn"}]','từ thông tục, hơi thô – tránh dùng khi trang trọng','/dæm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dam/damn_/damn__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2543,'ngsl-6-03',14,'distinct','khác biệt, riêng biệt; rõ rệt','adjective','[{"en":"Their new album is quite distinct from their earlier work.","vi":"Album mới của họ khá khác biệt so với các sản phẩm trước đây."},{"en":"There was a distinct smell of smoke in the kitchen.","vi":"Trong bếp có mùi khói rõ rệt."},{"en":"Each region of the country has its own distinct style of cooking.","vi":"Mỗi vùng của đất nước có phong cách nấu ăn riêng biệt."}]','[{"phrase":"distinct from"},{"phrase":"a distinct possibility"},{"phrase":"a distinct advantage"}]',NULL,'/dɪˈstɪŋkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2544,'ngsl-6-03',15,'humor','sự hài hước','noun','[{"en":"My grandfather has a great sense of humor.","vi":"Ông tôi rất có khiếu hài hước."},{"en":"She used humor to help the nervous students relax.","vi":"Cô ấy dùng sự hài hước để giúp các học sinh đang lo lắng thấy thoải mái."},{"en":"I didn''t understand the humor in his jokes at all.","vi":"Tôi hoàn toàn không hiểu những câu đùa của anh ấy hài hước ở chỗ nào."}]','[{"phrase":"sense of humor"},{"phrase":"good humor"},{"phrase":"dry humor"}]','Mỹ: humor · Anh: humour','/ˈhjuːmər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hum/humou/humour__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2545,'ngsl-6-03',16,'limitation','sự hạn chế; giới hạn','noun','[{"en":"Every method has its limitations, so choose carefully.","vi":"Phương pháp nào cũng có những hạn chế, nên hãy chọn cẩn thận."},{"en":"It''s important to know your own limitations.","vi":"Điều quan trọng là phải biết giới hạn của bản thân."},{"en":"Because of time limitations, we couldn''t visit every museum in the city.","vi":"Vì hạn chế về thời gian, chúng tôi không thể tham quan mọi bảo tàng trong thành phố."}]','[{"phrase":"have limitations"},{"phrase":"time limitations"},{"phrase":"know your limitations"},{"phrase":"physical limitations"}]',NULL,'/ˌlɪmɪˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lim/limit/limitation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2546,'ngsl-6-03',17,'indication','dấu hiệu','noun','[{"en":"There is no indication that the weather will improve soon.","vi":"Không có dấu hiệu nào cho thấy thời tiết sẽ sớm tốt lên."},{"en":"His smile was a clear indication that he liked the gift.","vi":"Nụ cười của anh ấy là dấu hiệu rõ ràng cho thấy anh ấy thích món quà."},{"en":"Did she give any indication of when she would be back?","vi":"Cô ấy có cho biết khi nào sẽ quay lại không?"}]','[{"phrase":"a clear indication"},{"phrase":"give an indication"},{"phrase":"no indication that"},{"phrase":"an indication of"}]',NULL,'/ˌɪndɪˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indic/indication__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2547,'ngsl-6-03',18,'stability','sự ổn định; sự vững chắc','noun','[{"en":"Children need stability and routine to feel safe.","vi":"Trẻ em cần sự ổn định và nề nếp để cảm thấy an toàn."},{"en":"After years of moving around, she finally found financial stability.","vi":"Sau nhiều năm chuyển chỗ liên tục, cuối cùng cô ấy cũng ổn định được về tài chính."},{"en":"Wider tires give the bike more stability on rough roads.","vi":"Lốp rộng hơn giúp xe đạp vững hơn trên đường gồ ghề."}]','[{"phrase":"financial stability"},{"phrase":"economic stability"},{"phrase":"emotional stability"}]',NULL,'/stəˈbɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stabi/stability__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2548,'ngsl-6-03',19,'wise','khôn ngoan, sáng suốt; thông thái','adjective','[{"en":"My grandmother was a wise woman who always gave good advice.","vi":"Bà tôi là một người phụ nữ thông thái, luôn đưa ra những lời khuyên hay."},{"en":"It would be wise to book your tickets early.","vi":"Đặt vé sớm sẽ là điều khôn ngoan."},{"en":"I think you made a wise decision to change jobs.","vi":"Tôi nghĩ bạn đã quyết định sáng suốt khi đổi việc."}]','[{"phrase":"a wise decision"},{"phrase":"a wise choice"},{"phrase":"it would be wise to"},{"phrase":"wise words"}]',NULL,'/waɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wis/wise_/wise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2549,'ngsl-6-03',20,'neglect','bỏ bê, sao nhãng; lơ là','verb','[{"en":"He was so busy with work that he neglected his health.","vi":"Anh ấy bận công việc đến mức bỏ bê sức khỏe."},{"en":"The old house had been neglected for many years.","vi":"Ngôi nhà cũ đã bị bỏ mặc không ai chăm sóc suốt nhiều năm."},{"en":"Don''t neglect your studies just because the exams are far away.","vi":"Đừng lơ là việc học chỉ vì kỳ thi còn xa."}]','[{"phrase":"neglect your health"},{"phrase":"badly neglected"},{"phrase":"neglect your duties"}]',NULL,'/nɪˈɡlekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negle/neglect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2550,'ngsl-6-03',21,'compose','sáng tác; soạn (thư, email); gồm có','verb','[{"en":"She composed her first song when she was only twelve.","vi":"Cô ấy sáng tác bài hát đầu tiên khi mới mười hai tuổi."},{"en":"I spent an hour composing a polite email to my landlord.","vi":"Tôi mất một tiếng để soạn một email lịch sự gửi chủ nhà."},{"en":"The team is composed of students from five different countries.","vi":"Đội gồm các sinh viên đến từ năm quốc gia khác nhau."}]','[{"phrase":"compose music"},{"phrase":"compose a letter"},{"phrase":"be composed of"}]','be composed of = consist of: gồm có','/kəmˈpəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/compose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2551,'ngsl-6-03',22,'jail','nhà tù','noun','[{"en":"He spent two years in jail for stealing cars.","vi":"Anh ta đã ngồi tù hai năm vì tội trộm xe hơi."},{"en":"The movie is about a man who escapes from jail.","vi":"Bộ phim kể về một người đàn ông vượt ngục."},{"en":"The judge sent him to jail for six months.","vi":"Thẩm phán đã tuyên phạt anh ta sáu tháng tù."}]','[{"phrase":"go to jail"},{"phrase":"in jail"},{"phrase":"escape from jail"},{"phrase":"send someone to jail"}]',NULL,'/dʒeɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jai/jail_/jail__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2552,'ngsl-6-03',23,'shelter','nơi trú ẩn; chỗ ở','noun','[{"en":"We took shelter under a tree when the rain started.","vi":"Chúng tôi trú dưới một gốc cây khi trời bắt đầu mưa."},{"en":"She adopted her cat from an animal shelter.","vi":"Cô ấy nhận nuôi con mèo từ một trại cứu hộ động vật."},{"en":"Food, water and shelter are basic human needs.","vi":"Thức ăn, nước uống và chỗ ở là những nhu cầu cơ bản của con người."}]','[{"phrase":"take shelter"},{"phrase":"animal shelter"},{"phrase":"seek shelter"},{"phrase":"food and shelter"}]',NULL,'/ˈʃeltər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/shelt/shelter__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2553,'ngsl-6-03',24,'mere','chỉ, chỉ là','adjective','[{"en":"The shop is a mere five minutes from our house.","vi":"Cửa hàng chỉ cách nhà chúng tôi năm phút."},{"en":"The mere thought of flying makes me nervous.","vi":"Chỉ nghĩ đến việc đi máy bay thôi là tôi đã thấy lo."},{"en":"He was a mere child when he moved abroad.","vi":"Cậu ấy chỉ là một đứa trẻ khi chuyển ra nước ngoài."}]','[{"phrase":"the mere thought of"},{"phrase":"a mere formality"},{"phrase":"a mere fraction"}]','chỉ đứng trước danh từ; trạng từ: merely','/mɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mer/mere_/mere__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2554,'ngsl-6-03',25,'carbon','cacbon','noun','[{"en":"Planting trees helps remove carbon from the air.","vi":"Trồng cây giúp loại bỏ cacbon khỏi không khí."},{"en":"Our company wants to reduce its carbon emissions by half.","vi":"Công ty chúng tôi muốn giảm một nửa lượng khí thải cacbon."},{"en":"Did you know that diamonds are made almost entirely of carbon?","vi":"Bạn có biết kim cương được tạo thành gần như hoàn toàn từ cacbon không?"}]','[{"phrase":"carbon dioxide"},{"phrase":"carbon emissions"},{"phrase":"carbon footprint"}]',NULL,'/ˈkɑːrbən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/carbo/carbon__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2555,'ngsl-6-03',26,'regulate','điều chỉnh; quản lý (bằng quy định)','verb','[{"en":"This device regulates the temperature in the room.","vi":"Thiết bị này điều chỉnh nhiệt độ trong phòng."},{"en":"The city strictly regulates where people are allowed to park.","vi":"Thành phố quy định chặt chẽ những nơi người dân được phép đỗ xe."},{"en":"Banks are closely regulated to protect their customers'' money.","vi":"Các ngân hàng được quản lý chặt chẽ để bảo vệ tiền của khách hàng."}]','[{"phrase":"regulate temperature"},{"phrase":"strictly regulate"},{"phrase":"closely regulated"}]',NULL,'/ˈreɡjuleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regulate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2556,'ngsl-6-03',27,'cheese','phô mai','noun','[{"en":"Would you like some cheese on your pasta?","vi":"Bạn có muốn thêm ít phô mai lên mì Ý không?"},{"en":"This shop sells more than fifty kinds of cheese.","vi":"Cửa hàng này bán hơn năm mươi loại phô mai."},{"en":"I made a cheese sandwich for lunch today.","vi":"Hôm nay tôi làm một chiếc bánh mì kẹp phô mai cho bữa trưa."}]','[{"phrase":"cheese sandwich"},{"phrase":"grated cheese"},{"phrase":"a slice of cheese"},{"phrase":"cream cheese"}]','thường không đếm được: some cheese, a slice of cheese','/tʃiːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chees/cheese__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2557,'ngsl-6-03',28,'trigger','gây ra; kích hoạt','verb','[{"en":"Strong smells can trigger headaches in some people.","vi":"Mùi nồng có thể gây đau đầu ở một số người."},{"en":"Someone opened a window and triggered the alarm.","vi":"Ai đó đã mở cửa sổ và làm kích hoạt chuông báo động."},{"en":"His comment triggered a long argument between the two teams.","vi":"Lời nhận xét của anh ấy đã gây ra một cuộc tranh cãi dài giữa hai đội."}]','[{"phrase":"trigger an alarm"},{"phrase":"trigger a reaction"},{"phrase":"trigger memories"}]',NULL,'/ˈtrɪɡər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trigg/trigger__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2558,'ngsl-6-03',29,'pipe','ống (nước, khí); tẩu thuốc','noun','[{"en":"A pipe burst in the kitchen and flooded the floor.","vi":"Một đường ống trong bếp bị vỡ khiến sàn nhà ngập nước."},{"en":"Water flows through these pipes to every house in the village.","vi":"Nước chảy qua những đường ống này đến từng ngôi nhà trong làng."},{"en":"My grandfather used to smoke a pipe after dinner.","vi":"Ông tôi từng hút tẩu sau bữa tối."}]','[{"phrase":"water pipe"},{"phrase":"burst pipe"},{"phrase":"gas pipe"},{"phrase":"smoke a pipe"}]',NULL,'/paɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pip/pipe_/pipe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2559,'ngsl-6-04',1,'destruction','sự phá hủy; sự tàn phá','noun','[{"en":"The storm caused terrible destruction along the coast last year.","vi":"Cơn bão năm ngoái đã gây ra sự tàn phá khủng khiếp dọc bờ biển."},{"en":"Many animals are losing their homes because of the destruction of forests.","vi":"Nhiều loài động vật đang mất nơi sống vì rừng bị phá hủy."},{"en":"We watched a film about the destruction of an ancient city.","vi":"Chúng tôi đã xem một bộ phim về sự hủy diệt của một thành phố cổ."}]','[{"phrase":"cause destruction"},{"phrase":"the destruction of"},{"phrase":"widespread destruction"},{"phrase":"environmental destruction"}]','không đếm được','/dɪˈstrʌkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/destr/destruction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2560,'ngsl-6-04',2,'guitar','đàn ghi-ta','noun','[{"en":"My brother taught himself to play the guitar last summer.","vi":"Anh trai tôi đã tự học chơi ghi-ta vào mùa hè năm ngoái."},{"en":"She sat by the fire and played her guitar for us.","vi":"Cô ấy ngồi cạnh đống lửa và chơi ghi-ta cho chúng tôi nghe."},{"en":"Do you know where I can buy a cheap guitar?","vi":"Bạn có biết chỗ nào mua được đàn ghi-ta rẻ không?"}]','[{"phrase":"play the guitar"},{"phrase":"electric guitar"},{"phrase":"acoustic guitar"},{"phrase":"guitar lesson"}]',NULL,'/ɡɪˈtɑːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guita/guitar__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2561,'ngsl-6-04',3,'flag','lá cờ','noun','[{"en":"The children waved small flags as the runners went past.","vi":"Bọn trẻ vẫy những lá cờ nhỏ khi các vận động viên chạy ngang qua."},{"en":"A red flag on the beach means it is not safe to swim.","vi":"Cờ đỏ trên bãi biển nghĩa là bơi không an toàn."},{"en":"Every morning they raise the flag in front of the school.","vi":"Mỗi sáng họ kéo cờ trước cổng trường."}]','[{"phrase":"national flag"},{"phrase":"wave a flag"},{"phrase":"raise a flag"},{"phrase":"red flag"}]',NULL,'/flæɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fla/flag_/flag__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2562,'ngsl-6-04',4,'piano','đàn piano; dương cầm','noun','[{"en":"My daughter has been learning to play the piano for three years.","vi":"Con gái tôi đã học chơi piano được ba năm."},{"en":"There is an old piano in the corner of the living room.","vi":"Có một cây đàn piano cũ ở góc phòng khách."},{"en":"He practices the piano for an hour every evening after dinner.","vi":"Mỗi tối sau bữa ăn, anh ấy tập đàn piano một tiếng."}]','[{"phrase":"play the piano"},{"phrase":"piano lesson"},{"phrase":"piano teacher"},{"phrase":"grand piano"}]',NULL,'/piˈænəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pia/piano/piano__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2563,'ngsl-6-04',5,'magic','phép thuật; ảo thuật; sự kỳ diệu','noun','[{"en":"In the story, the old woman uses magic to turn him into a frog.","vi":"Trong câu chuyện, bà lão dùng phép thuật biến anh ta thành một con ếch."},{"en":"My uncle did a few magic tricks at the birthday party.","vi":"Chú tôi đã biểu diễn vài trò ảo thuật ở bữa tiệc sinh nhật."},{"en":"Nobody can forget the magic of seeing snow for the first time.","vi":"Không ai quên được sự kỳ diệu của lần đầu tiên nhìn thấy tuyết."}]','[{"phrase":"magic trick"},{"phrase":"black magic"},{"phrase":"like magic"},{"phrase":"the magic of"}]','không đếm được','/ˈmædʒɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mag/magic/magic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2564,'ngsl-6-04',6,'mystery','điều bí ẩn; truyện trinh thám','noun','[{"en":"Where my keys went is still a complete mystery to me.","vi":"Chìa khóa của tôi biến đi đâu vẫn là một điều hoàn toàn bí ẩn với tôi."},{"en":"Scientists are trying to solve the mystery of how the lake formed.","vi":"Các nhà khoa học đang cố giải đáp bí ẩn về việc hồ này hình thành như thế nào."},{"en":"She likes to read a good mystery before going to bed.","vi":"Cô ấy thích đọc một cuốn truyện trinh thám hay trước khi đi ngủ."}]','[{"phrase":"solve a mystery"},{"phrase":"remain a mystery"},{"phrase":"complete mystery"},{"phrase":"mystery novel"}]',NULL,'/ˈmɪstəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mys/myste/mystery__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2565,'ngsl-6-04',7,'ski','trượt tuyết','verb','[{"en":"We go skiing in the mountains every winter with our cousins.","vi":"Mùa đông nào chúng tôi cũng đi trượt tuyết trên núi cùng anh em họ."},{"en":"I learned to ski when I was about ten years old.","vi":"Tôi học trượt tuyết khi khoảng mười tuổi."},{"en":"She skied down the hill much faster than the rest of us.","vi":"Cô ấy trượt tuyết xuống đồi nhanh hơn hẳn những người còn lại."}]','[{"phrase":"go skiing"},{"phrase":"learn to ski"},{"phrase":"ski resort"},{"phrase":"ski slope"}]',NULL,'/skiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/ski__/ski__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2566,'ngsl-6-04',8,'whisper','thì thầm; nói nhỏ','verb','[{"en":"She leaned over and whispered something in my ear.","vi":"Cô ấy nghiêng người sang và thì thầm điều gì đó vào tai tôi."},{"en":"Please whisper if you need to talk during the movie.","vi":"Nếu cần nói chuyện trong lúc xem phim thì làm ơn nói nhỏ thôi."},{"en":"The two girls were whispering and laughing at the back of the class.","vi":"Hai cô bé đang thì thầm và cười khúc khích ở cuối lớp."}]','[{"phrase":"whisper in someone''s ear"},{"phrase":"whisper softly"},{"phrase":"whisper to someone"}]',NULL,'/ˈwɪspər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whi/whisp/whisper__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2567,'ngsl-6-04',9,'rear','phía sau; đằng sau','noun','[{"en":"Passengers should leave the bus through the door at the rear.","vi":"Hành khách nên xuống xe buýt bằng cửa phía sau."},{"en":"There is a small garden at the rear of the house.","vi":"Có một khu vườn nhỏ ở phía sau ngôi nhà."},{"en":"Someone hit the rear of my car while I was parked.","vi":"Có người đã tông vào đuôi xe tôi khi tôi đang đỗ xe."}]','[{"phrase":"at the rear"},{"phrase":"the rear of"},{"phrase":"rear window"},{"phrase":"rear seat"}]','Cũng là tính từ: rear door (cửa sau)','/rɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/rear_/rear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2568,'ngsl-6-04',10,'menu','thực đơn; menu (máy tính)','noun','[{"en":"Could we have a look at the menu, please?","vi":"Cho chúng tôi xem thực đơn được không ạ?"},{"en":"There are several vegetarian dishes on the menu tonight.","vi":"Tối nay trong thực đơn có vài món chay."},{"en":"Click the menu at the top of the screen to save your file.","vi":"Nhấp vào menu ở đầu màn hình để lưu tệp của bạn."}]','[{"phrase":"on the menu"},{"phrase":"look at the menu"},{"phrase":"set menu"},{"phrase":"main menu"}]',NULL,'/ˈmenjuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menu_/menu__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2569,'ngsl-6-04',11,'species','loài','noun','[{"en":"Many species of birds live in this part of the forest.","vi":"Nhiều loài chim sống ở khu vực này của khu rừng."},{"en":"Scientists have discovered a new species of frog in the mountains.","vi":"Các nhà khoa học đã phát hiện một loài ếch mới trên núi."},{"en":"Some plant species are disappearing because the climate is changing.","vi":"Một số loài thực vật đang biến mất vì khí hậu đang thay đổi."}]','[{"phrase":"endangered species"},{"phrase":"species of"},{"phrase":"animal species"},{"phrase":"new species"}]','Số ít và số nhiều giống nhau: species','/ˈspiːʃiːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/species__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2570,'ngsl-6-04',12,'moon','mặt trăng','noun','[{"en":"The moon was so bright that we could see the path clearly.","vi":"Mặt trăng sáng đến mức chúng tôi nhìn rõ con đường."},{"en":"Tonight there will be a full moon over the city.","vi":"Tối nay sẽ có trăng tròn trên bầu trời thành phố."},{"en":"Do you remember when people first walked on the moon?","vi":"Bạn có nhớ lần đầu tiên con người đặt chân lên mặt trăng không?"}]','[{"phrase":"full moon"},{"phrase":"new moon"},{"phrase":"the moon rises"},{"phrase":"on the moon"}]',NULL,'/muːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/moo/moon_/moon__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2571,'ngsl-6-04',13,'presumably','có lẽ; chắc là','adverb','[{"en":"The office is dark, so presumably everyone has already gone home.","vi":"Văn phòng tối om, nên chắc là mọi người đã về nhà cả rồi."},{"en":"Presumably the train is late because of the heavy snow.","vi":"Có lẽ tàu bị trễ vì tuyết rơi dày."},{"en":"He didn''t answer, presumably because he was still asleep.","vi":"Anh ấy không trả lời, có lẽ vì vẫn còn đang ngủ."}]','[{"phrase":"presumably because"},{"phrase":"presumably not"}]',NULL,'/prɪˈzuːməbli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presu/presumably__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2572,'ngsl-6-04',14,'bless','ban phước; phù hộ; may mắn có (be blessed with)','verb','[{"en":"\"Bless you!\" she said when I sneezed for the third time.","vi":"Khi tôi hắt xì lần thứ ba, cô ấy nói: \"Bless you!\" (chúc sức khỏe)."},{"en":"We feel truly blessed to have such kind and helpful neighbors.","vi":"Chúng tôi cảm thấy thật may mắn khi có những người hàng xóm tốt bụng và hay giúp đỡ như vậy."},{"en":"My grandfather was blessed with good health until his nineties.","vi":"Ông tôi may mắn có sức khỏe tốt cho đến tận tuổi chín mươi."}]','[{"phrase":"bless you"},{"phrase":"be blessed with"},{"phrase":"feel blessed"}]','Nói "Bless you!" khi ai đó hắt xì','/bles/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ble/bless/bless__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2573,'ngsl-6-04',15,'airline','hãng hàng không','noun','[{"en":"Which airline are you flying with to Singapore next week?","vi":"Tuần sau bạn bay đi Singapore bằng hãng hàng không nào?"},{"en":"The airline lost my suitcase, so I had no clean clothes.","vi":"Hãng hàng không làm thất lạc vali của tôi nên tôi không có quần áo sạch."},{"en":"My sister works as a pilot for a small airline.","vi":"Chị gái tôi làm phi công cho một hãng hàng không nhỏ."}]','[{"phrase":"airline ticket"},{"phrase":"budget airline"},{"phrase":"airline industry"},{"phrase":"airline passenger"}]',NULL,'/ˈerlaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/air/airli/airline__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2574,'ngsl-6-04',16,'amendment','sự sửa đổi; bản sửa đổi (luật, văn bản)','noun','[{"en":"The committee made a small amendment to the contract before signing it.","vi":"Ủy ban đã sửa đổi nhỏ bản hợp đồng trước khi ký."},{"en":"Parliament voted to pass the amendment after a long debate.","vi":"Quốc hội đã bỏ phiếu thông qua bản sửa đổi sau một cuộc tranh luận dài."},{"en":"Please send any amendments to the report by Friday.","vi":"Vui lòng gửi mọi chỉnh sửa cho bản báo cáo trước thứ Sáu."}]','[{"phrase":"make an amendment"},{"phrase":"pass an amendment"},{"phrase":"propose an amendment"},{"phrase":"amendment to"}]',NULL,'/əˈmendmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ame/amend/amendment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2575,'ngsl-6-04',17,'grandmother','bà (nội, ngoại)','noun','[{"en":"My grandmother taught me how to cook this soup.","vi":"Bà tôi đã dạy tôi cách nấu món canh này."},{"en":"We visit our grandmother in the countryside every summer.","vi":"Mùa hè nào chúng tôi cũng về quê thăm bà."},{"en":"Her grandmother is ninety but still walks to the market every day.","vi":"Bà của cô ấy đã chín mươi tuổi nhưng ngày nào cũng vẫn đi bộ ra chợ."}]','[{"phrase":"visit your grandmother"},{"phrase":"great-grandmother"},{"phrase":"grandmother''s house"}]',NULL,'/ˈɡrænmʌðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grand/grandmother__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2576,'ngsl-6-04',18,'jury','bồi thẩm đoàn; ban giám khảo','noun','[{"en":"After two days, the jury found the man not guilty.","vi":"Sau hai ngày, bồi thẩm đoàn tuyên bố người đàn ông vô tội."},{"en":"The jury took several hours to reach a decision.","vi":"Bồi thẩm đoàn mất vài tiếng để đưa ra quyết định."},{"en":"A jury of famous chefs chose the best dish in the competition.","vi":"Một ban giám khảo gồm các đầu bếp nổi tiếng đã chọn ra món ăn ngon nhất cuộc thi."}]','[{"phrase":"jury trial"},{"phrase":"serve on a jury"},{"phrase":"the jury found"},{"phrase":"jury member"}]',NULL,'/ˈdʒʊri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jur/jury_/jury__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2577,'ngsl-6-04',19,'cooperation','sự hợp tác','noun','[{"en":"Thank you for your cooperation during the building repairs.","vi":"Cảm ơn sự hợp tác của quý vị trong thời gian sửa chữa tòa nhà."},{"en":"The project was a success thanks to close cooperation between the two teams.","vi":"Dự án thành công nhờ sự hợp tác chặt chẽ giữa hai nhóm."},{"en":"Both countries have agreed to increase cooperation on trade.","vi":"Hai nước đã đồng ý tăng cường hợp tác về thương mại."}]','[{"phrase":"close cooperation"},{"phrase":"cooperation between"},{"phrase":"in cooperation with"},{"phrase":"international cooperation"}]','không đếm được','/kəʊˌɑːpəˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/coope/cooperation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2578,'ngsl-6-04',20,'civilian','thường dân; dân thường','noun','[{"en":"The new sports center is open to both soldiers and civilians.","vi":"Trung tâm thể thao mới mở cửa cho cả quân nhân lẫn dân thường."},{"en":"My father was a soldier, but he became a civilian again at forty.","vi":"Bố tôi từng là quân nhân, nhưng ông trở lại làm dân thường ở tuổi bốn mươi."},{"en":"Civilians are not allowed to enter the military base without a pass.","vi":"Dân thường không được vào căn cứ quân sự nếu không có giấy phép."}]','[{"phrase":"civilian life"},{"phrase":"civilian population"},{"phrase":"protect civilians"}]',NULL,'/səˈvɪliən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/civ/civil/civilian__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2579,'ngsl-6-04',21,'composition','thành phần; bản nhạc, sáng tác; bài luận','noun','[{"en":"The composition of the team has changed a lot this year.","vi":"Thành phần của đội đã thay đổi nhiều trong năm nay."},{"en":"She played one of her own compositions at the concert.","vi":"Cô ấy đã chơi một trong những sáng tác của chính mình tại buổi hòa nhạc."},{"en":"Our teacher asked us to write a short composition about our summer.","vi":"Cô giáo yêu cầu chúng tôi viết một bài luận ngắn về mùa hè của mình."}]','[{"phrase":"the composition of"},{"phrase":"musical composition"},{"phrase":"chemical composition"},{"phrase":"write a composition"}]',NULL,'/ˌkɑːmpəˈzɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/composition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2580,'ngsl-6-04',22,'coin','đồng xu','noun','[{"en":"I need some coins for the parking machine.","vi":"Tôi cần vài đồng xu để trả tiền ở máy đỗ xe."},{"en":"Let''s toss a coin to decide who goes first.","vi":"Mình tung đồng xu để quyết định ai đi trước nhé."},{"en":"My grandfather has collected old coins for most of his life.","vi":"Ông tôi đã sưu tầm tiền xu cổ gần như cả đời."}]','[{"phrase":"toss a coin"},{"phrase":"gold coin"},{"phrase":"collect coins"},{"phrase":"coin collection"}]',NULL,'/kɔɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coi/coin_/coin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2581,'ngsl-6-04',23,'regardless','bất kể; dù sao đi nữa','adverb','[{"en":"Everyone can join the club regardless of age.","vi":"Ai cũng có thể tham gia câu lạc bộ, bất kể tuổi tác."},{"en":"It was raining hard, but we went for our walk regardless.","vi":"Trời mưa to nhưng dù sao chúng tôi vẫn đi dạo."},{"en":"Regardless of what happens, I will always support you.","vi":"Dù có chuyện gì xảy ra, tôi vẫn luôn ủng hộ bạn."}]','[{"phrase":"regardless of"},{"phrase":"regardless of age"},{"phrase":"regardless of cost"}]','Thường đi với giới từ: regardless of + danh từ','/rɪˈɡɑːrdləs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regar/regardless__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2582,'ngsl-6-04',24,'scan','quét (máy); đọc lướt; nhìn kỹ khắp lượt','verb','[{"en":"Could you scan these documents and email them to me?","vi":"Bạn có thể scan những tài liệu này rồi gửi email cho tôi không?"},{"en":"I quickly scanned the newspaper for news about the match.","vi":"Tôi đọc lướt nhanh tờ báo để tìm tin về trận đấu."},{"en":"She scanned the crowd, looking for her friend''s face.","vi":"Cô ấy đưa mắt nhìn khắp đám đông, tìm khuôn mặt của người bạn."}]','[{"phrase":"scan a document"},{"phrase":"scan the horizon"},{"phrase":"scan the crowd"},{"phrase":"quickly scan"}]','scan – scanned – scanned','/skæn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sca/scan_/scan__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2583,'ngsl-6-04',25,'bunch','chùm; bó; nhóm (người)','noun','[{"en":"He bought a bunch of flowers for his wife''s birthday.","vi":"Anh ấy mua một bó hoa nhân sinh nhật vợ."},{"en":"Could you get a bunch of bananas on your way home?","vi":"Trên đường về bạn mua giúp một nải chuối được không?"},{"en":"My new classmates are a really friendly bunch.","vi":"Các bạn cùng lớp mới của tôi là một nhóm người rất thân thiện."}]','[{"phrase":"a bunch of flowers"},{"phrase":"a bunch of keys"},{"phrase":"a bunch of grapes"},{"phrase":"a whole bunch of"}]','Văn nói: a bunch of = nhiều','/bʌntʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bun/bunch/bunch__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2584,'ngsl-6-04',26,'racial','(thuộc) chủng tộc','adjective','[{"en":"The school welcomes students from many different racial backgrounds.","vi":"Trường chào đón học sinh đến từ nhiều nguồn gốc chủng tộc khác nhau."},{"en":"Racial discrimination at work is against the law in many countries.","vi":"Ở nhiều nước, phân biệt chủng tộc nơi làm việc là vi phạm pháp luật."},{"en":"The company wants to improve racial equality in its hiring.","vi":"Công ty muốn cải thiện sự bình đẳng chủng tộc trong việc tuyển dụng."}]','[{"phrase":"racial discrimination"},{"phrase":"racial equality"},{"phrase":"racial background"},{"phrase":"racial groups"}]',NULL,'/ˈreɪʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rac/racia/racial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2585,'ngsl-6-04',27,'greet','chào; đón chào','verb','[{"en":"The hotel manager greeted us warmly at the front door.","vi":"Quản lý khách sạn đã niềm nở chào đón chúng tôi ở cửa chính."},{"en":"Our dog always greets me when I get home from work.","vi":"Con chó nhà tôi lúc nào cũng ra chào khi tôi đi làm về."},{"en":"In some countries, people greet each other with a kiss on the cheek.","vi":"Ở một số nước, mọi người chào nhau bằng một nụ hôn lên má."}]','[{"phrase":"greet someone warmly"},{"phrase":"greet each other"},{"phrase":"greet guests"},{"phrase":"be greeted with"}]',NULL,'/ɡriːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/greet/greet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2586,'ngsl-6-04',28,'hopefully','hy vọng là; mong là','adverb','[{"en":"Hopefully the weather will be better tomorrow.","vi":"Hy vọng là ngày mai thời tiết sẽ đẹp hơn."},{"en":"I''m leaving now, so hopefully I''ll be there by six.","vi":"Tôi đi bây giờ đây, nên mong là sẽ tới đó trước sáu giờ."},{"en":"We''ve fixed the problem, and hopefully it won''t happen again.","vi":"Chúng tôi đã khắc phục sự cố, và hy vọng là nó sẽ không xảy ra nữa."}]','[{"phrase":"hopefully not"},{"phrase":"hopefully soon"}]',NULL,'/ˈhəʊpfəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hop/hopef/hopefully__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2587,'ngsl-6-04',29,'sanction','lệnh trừng phạt; sự cho phép','noun','[{"en":"Several countries have placed economic sanctions on the government.","vi":"Một số quốc gia đã áp đặt các lệnh trừng phạt kinh tế lên chính phủ này."},{"en":"The sanctions will be lifted if both sides reach an agreement.","vi":"Các lệnh trừng phạt sẽ được dỡ bỏ nếu hai bên đạt được thỏa thuận."},{"en":"Nobody may use the hall without the official sanction of the school.","vi":"Không ai được sử dụng hội trường khi chưa có sự cho phép chính thức của nhà trường."}]','[{"phrase":"impose sanctions"},{"phrase":"economic sanctions"},{"phrase":"lift sanctions"},{"phrase":"trade sanctions"}]','Nghĩa "trừng phạt" thường dùng số nhiều: sanctions','/ˈsæŋkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/san/sanct/sanction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2588,'ngsl-6-05',1,'trick','trò lừa; mẹo; trò ảo thuật','noun','[{"en":"Don''t believe him; it''s just a trick to get your money.","vi":"Đừng tin anh ta; đó chỉ là trò lừa để lấy tiền của bạn."},{"en":"Is there a trick to opening this jar?","vi":"Có mẹo nào để mở cái lọ này không?"},{"en":"My grandfather showed us a card trick after dinner.","vi":"Ông tôi cho chúng tôi xem một trò ảo thuật với bài sau bữa tối."}]','[{"phrase":"play a trick on"},{"phrase":"magic trick"},{"phrase":"card trick"},{"phrase":"the trick is"}]',NULL,'/trɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trick/trick__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2589,'ngsl-6-05',2,'paragraph','đoạn văn','noun','[{"en":"Please read the first paragraph out loud.","vi":"Hãy đọc to đoạn văn đầu tiên."},{"en":"Your essay should have at least five paragraphs.","vi":"Bài luận của bạn nên có ít nhất năm đoạn văn."},{"en":"I rewrote the last paragraph of my cover letter twice.","vi":"Tôi đã viết lại đoạn cuối của thư xin việc hai lần."}]','[{"phrase":"first paragraph"},{"phrase":"opening paragraph"},{"phrase":"short paragraph"},{"phrase":"write a paragraph"}]',NULL,'/ˈpærəɡræf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parag/paragraph__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2590,'ngsl-6-05',3,'maker','hãng sản xuất; người làm ra; máy pha, máy làm','noun','[{"en":"The phone maker plans to open a new factory next year.","vi":"Hãng sản xuất điện thoại dự định mở một nhà máy mới vào năm sau."},{"en":"My uncle is a furniture maker in a small village.","vi":"Chú tôi là thợ làm đồ gỗ ở một ngôi làng nhỏ."},{"en":"My sister bought a new coffee maker for her office.","vi":"Chị tôi đã mua một chiếc máy pha cà phê mới cho văn phòng."}]','[{"phrase":"coffee maker"},{"phrase":"car maker"},{"phrase":"decision maker"},{"phrase":"furniture maker"}]',NULL,'/ˈmeɪkər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mak/maker/maker__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2591,'ngsl-6-05',4,'chocolate','sô-cô-la','noun','[{"en":"Would you like a cup of hot chocolate?","vi":"Bạn có muốn một cốc sô-cô-la nóng không?"},{"en":"She gave me a box of chocolates for my birthday.","vi":"Cô ấy tặng tôi một hộp sô-cô-la nhân dịp sinh nhật."},{"en":"The kids ate all the dark chocolate I bought.","vi":"Bọn trẻ đã ăn hết chỗ sô-cô-la đen tôi mua."}]','[{"phrase":"hot chocolate"},{"phrase":"dark chocolate"},{"phrase":"box of chocolates"},{"phrase":"chocolate cake"}]',NULL,'/ˈtʃɔːklət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cho/choco/chocolate__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2592,'ngsl-6-05',5,'stimulate','kích thích; thúc đẩy; khơi gợi','verb','[{"en":"The government lowered taxes to stimulate the economy.","vi":"Chính phủ giảm thuế để kích thích nền kinh tế."},{"en":"Colorful pictures can stimulate children''s interest in reading.","vi":"Tranh ảnh nhiều màu sắc có thể khơi gợi hứng thú đọc sách của trẻ."},{"en":"Coffee stimulates the brain and helps you stay awake.","vi":"Cà phê kích thích não bộ và giúp bạn tỉnh táo."}]','[{"phrase":"stimulate the economy"},{"phrase":"stimulate growth"},{"phrase":"stimulate interest"},{"phrase":"stimulate demand"}]',NULL,'/ˈstɪmjuleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/stimu/stimulate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2593,'ngsl-6-05',6,'belt','thắt lưng; dây đai; băng chuyền','noun','[{"en":"These jeans are too big, so I need a belt.","vi":"Chiếc quần jean này rộng quá nên tôi cần một cái thắt lưng."},{"en":"Please fasten your seat belt before we start driving.","vi":"Hãy thắt dây an toàn trước khi chúng ta bắt đầu lái xe."},{"en":"Your bags will come out on that belt over there.","vi":"Hành lý của bạn sẽ ra trên băng chuyền đằng kia."}]','[{"phrase":"seat belt"},{"phrase":"leather belt"},{"phrase":"conveyor belt"},{"phrase":"wear a belt"}]','seat belt: dây an toàn','/belt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belt_/belt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2594,'ngsl-6-05',7,'potato','khoai tây','noun','[{"en":"Could you peel the potatoes while I cook the fish?","vi":"Bạn gọt khoai tây giúp tôi trong lúc tôi nấu cá được không?"},{"en":"We had baked potatoes with cheese for lunch.","vi":"Bữa trưa chúng tôi ăn khoai tây nướng với phô mai."},{"en":"My grandmother grows potatoes and onions in her garden.","vi":"Bà tôi trồng khoai tây và hành trong vườn."}]','[{"phrase":"baked potato"},{"phrase":"mashed potatoes"},{"phrase":"sweet potato"},{"phrase":"peel potatoes"}]','số nhiều: potatoes','/pəˈteɪtəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/potat/potato__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2595,'ngsl-6-05',8,'narrative','câu chuyện; lời kể; bài văn tự sự','noun','[{"en":"The narrative of the novel moves between the past and the present.","vi":"Câu chuyện trong cuốn tiểu thuyết đan xen giữa quá khứ và hiện tại."},{"en":"Her narrative of the trip was clear and full of detail.","vi":"Lời kể của cô ấy về chuyến đi rất rõ ràng và đầy chi tiết."},{"en":"Each student wrote a short personal narrative about their summer.","vi":"Mỗi học sinh viết một bài văn tự sự ngắn về mùa hè của mình."}]','[{"phrase":"personal narrative"},{"phrase":"historical narrative"},{"phrase":"a clear narrative"}]',NULL,'/ˈnærətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nar/narra/narrative__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2596,'ngsl-6-05',9,'tissue','khăn giấy; mô (cơ thể)','noun','[{"en":"She handed me a tissue when I started to cry.","vi":"Cô ấy đưa tôi một tờ khăn giấy khi tôi bắt đầu khóc."},{"en":"Please put a box of tissues on each table.","vi":"Vui lòng đặt một hộp khăn giấy trên mỗi bàn."},{"en":"Regular exercise helps your body build strong muscle tissue.","vi":"Tập thể dục đều đặn giúp cơ thể xây dựng mô cơ khỏe mạnh."}]','[{"phrase":"box of tissues"},{"phrase":"muscle tissue"},{"phrase":"soft tissue"}]',NULL,'/ˈtɪʃuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tis/tissu/tissue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2597,'ngsl-6-05',10,'barely','hầu như không; vừa đủ','adverb','[{"en":"I could barely hear her over the loud music.","vi":"Tôi gần như không nghe thấy cô ấy nói vì tiếng nhạc quá to."},{"en":"We barely had enough time to catch the train.","vi":"Chúng tôi chỉ vừa đủ thời gian để kịp chuyến tàu."},{"en":"He was so tired that he barely spoke at dinner.","vi":"Anh ấy mệt đến mức hầu như không nói gì trong bữa tối."}]','[{"phrase":"barely enough"},{"phrase":"can barely"},{"phrase":"barely notice"}]',NULL,'/ˈberli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bar/barel/barely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2598,'ngsl-6-05',11,'invent','phát minh; nghĩ ra; bịa ra','verb','[{"en":"Nobody knows exactly who invented the first bicycle.","vi":"Không ai biết chính xác ai đã phát minh ra chiếc xe đạp đầu tiên."},{"en":"My son loves to invent new games with his friends.","vi":"Con trai tôi thích nghĩ ra trò chơi mới cùng bạn bè."},{"en":"He invented an excuse for being late to work.","vi":"Anh ấy bịa ra một lý do cho việc đi làm muộn."}]','[{"phrase":"invent an excuse"},{"phrase":"invent a story"},{"phrase":"invent a new way"}]',NULL,'/ɪnˈvent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inven/invent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2599,'ngsl-6-05',12,'tourism','du lịch; ngành du lịch','noun','[{"en":"The tourism industry creates thousands of jobs on the island.","vi":"Ngành du lịch tạo ra hàng nghìn việc làm trên hòn đảo."},{"en":"The new airport has helped tourism grow in the region.","vi":"Sân bay mới đã giúp du lịch trong vùng phát triển."},{"en":"She works in tourism and speaks four languages.","vi":"Cô ấy làm trong ngành du lịch và nói được bốn thứ tiếng."}]','[{"phrase":"tourism industry"},{"phrase":"boost tourism"},{"phrase":"mass tourism"}]','không đếm được','/ˈtʊrɪzəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/touri/tourism__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2600,'ngsl-6-05',13,'pro','dân chuyên nghiệp; người thành thạo; ưu điểm','noun','[{"en":"My brother wants to turn pro after finishing college.","vi":"Anh trai tôi muốn trở thành vận động viên chuyên nghiệp sau khi học xong đại học."},{"en":"After ten years of cooking, he''s a real pro in the kitchen.","vi":"Sau mười năm nấu nướng, anh ấy là một tay lão luyện thực thụ trong bếp."},{"en":"Let''s write down the pros and cons before we decide.","vi":"Hãy viết ra những ưu và nhược điểm trước khi chúng ta quyết định."}]','[{"phrase":"pros and cons"},{"phrase":"turn pro"},{"phrase":"like a pro"},{"phrase":"a real pro"}]','viết tắt của professional; pros and cons: ưu và nhược điểm','/prəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/pro__/pro__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2601,'ngsl-6-05',14,'stair','bậc thang; cầu thang','noun','[{"en":"He sat on the bottom stair to tie his shoes.","vi":"Anh ấy ngồi ở bậc thang dưới cùng để buộc dây giày."},{"en":"Take the stairs if the elevator is too slow.","vi":"Hãy đi cầu thang bộ nếu thang máy quá chậm."},{"en":"I heard someone running up the stairs.","vi":"Tôi nghe thấy ai đó chạy lên cầu thang."}]','[{"phrase":"take the stairs"},{"phrase":"climb the stairs"},{"phrase":"flight of stairs"},{"phrase":"bottom stair"}]','thường dùng số nhiều: stairs (cầu thang)','/ster/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stair/stair__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2602,'ngsl-6-05',15,'hesitate','do dự; ngần ngại','verb','[{"en":"Don''t hesitate to call me if you need help.","vi":"Đừng ngần ngại gọi cho tôi nếu bạn cần giúp đỡ."},{"en":"She hesitated for a moment before opening the door.","vi":"Cô ấy do dự một lúc trước khi mở cửa."},{"en":"When they offered him the job, he didn''t hesitate.","vi":"Khi họ mời anh ấy nhận việc, anh ấy không hề do dự."}]','[{"phrase":"don''t hesitate to"},{"phrase":"hesitate for a moment"},{"phrase":"hesitate before"}]',NULL,'/ˈhezɪteɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hes/hesit/hesitate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2603,'ngsl-6-05',16,'shine','chiếu sáng; tỏa sáng; sáng lên','verb','[{"en":"The sun was shining when we arrived at the beach.","vi":"Mặt trời đang chiếu sáng rực rỡ khi chúng tôi đến bãi biển."},{"en":"Her eyes shone with excitement when she opened the gift.","vi":"Mắt cô ấy sáng lên vì háo hức khi mở món quà."},{"en":"He really shines when he talks about music.","vi":"Anh ấy thực sự tỏa sáng khi nói về âm nhạc."}]','[{"phrase":"the sun shines"},{"phrase":"shine brightly"},{"phrase":"shine a light"},{"phrase":"eyes shine"}]','shine – shone – shone','/ʃaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shine/shine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2604,'ngsl-6-05',17,'motivation','động lực; sự thúc đẩy','noun','[{"en":"I lost my motivation to study after failing the test.","vi":"Tôi mất động lực học sau khi thi trượt."},{"en":"Money isn''t his only motivation for working so hard.","vi":"Tiền không phải là động lực duy nhất khiến anh ấy làm việc chăm chỉ như vậy."},{"en":"Good managers know how to keep their team''s motivation high.","vi":"Người quản lý giỏi biết cách giữ cho đội ngũ luôn có động lực cao."}]','[{"phrase":"motivation to"},{"phrase":"lack of motivation"},{"phrase":"lose motivation"},{"phrase":"high motivation"}]',NULL,'/ˌməʊtɪˈveɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motiv/motivation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2605,'ngsl-6-05',18,'romantic','lãng mạn','adjective','[{"en":"We had a romantic dinner by the river.","vi":"Chúng tôi đã có một bữa tối lãng mạn bên bờ sông."},{"en":"My husband isn''t very romantic, but he''s very kind.","vi":"Chồng tôi không lãng mạn lắm, nhưng anh ấy rất tốt bụng."},{"en":"She loves watching romantic comedies on Friday nights.","vi":"Cô ấy thích xem phim hài lãng mạn vào các tối thứ Sáu."}]','[{"phrase":"romantic dinner"},{"phrase":"romantic comedy"},{"phrase":"romantic relationship"},{"phrase":"romantic evening"}]',NULL,'/rəʊˈmæntɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rom/roman/romantic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2606,'ngsl-6-05',19,'firmly','chặt; kiên quyết; vững chắc','adverb','[{"en":"Hold the ladder firmly while I climb up.","vi":"Hãy giữ chặt cái thang trong khi tôi trèo lên."},{"en":"She said no firmly and walked away.","vi":"Cô ấy kiên quyết nói không rồi bỏ đi."},{"en":"I firmly believe that everyone deserves a second chance.","vi":"Tôi tin chắc rằng ai cũng xứng đáng có cơ hội thứ hai."}]','[{"phrase":"firmly believe"},{"phrase":"hold firmly"},{"phrase":"firmly established"}]',NULL,'/ˈfɜːrmli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/firml/firmly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2607,'ngsl-6-05',20,'interior','nội thất; phần bên trong','noun','[{"en":"The interior of the house is much bigger than it looks.","vi":"Bên trong ngôi nhà rộng hơn nhiều so với vẻ bề ngoài."},{"en":"The car''s interior smells like new leather.","vi":"Nội thất của chiếc xe có mùi da mới."},{"en":"My cousin studied interior design and now decorates hotels.","vi":"Em họ tôi học thiết kế nội thất và giờ đi trang trí khách sạn."}]','[{"phrase":"interior design"},{"phrase":"the interior of"},{"phrase":"car interior"}]',NULL,'/ɪnˈtɪriər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interior__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2608,'ngsl-6-05',21,'stomach','dạ dày; bụng','noun','[{"en":"I''ve had a stomach ache since this morning.","vi":"Tôi bị đau bụng từ sáng nay."},{"en":"Try not to go swimming on a full stomach.","vi":"Cố đừng đi bơi khi vừa ăn no."},{"en":"He lay on his stomach and read a book.","vi":"Anh ấy nằm sấp và đọc sách."}]','[{"phrase":"stomach ache"},{"phrase":"empty stomach"},{"phrase":"full stomach"},{"phrase":"upset stomach"}]','on an empty stomach: lúc bụng đói','/ˈstʌmək/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stoma/stomach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2609,'ngsl-6-05',22,'nowhere','không nơi nào; không đâu','adverb','[{"en":"There''s nowhere to park near the stadium.","vi":"Gần sân vận động không có chỗ nào để đỗ xe."},{"en":"We looked everywhere, but the cat was nowhere to be found.","vi":"Chúng tôi tìm khắp nơi nhưng không thấy con mèo ở đâu cả."},{"en":"Arguing with your boss will get you nowhere.","vi":"Cãi nhau với sếp sẽ chẳng đưa bạn đến đâu cả."}]','[{"phrase":"nowhere to go"},{"phrase":"nowhere to be found"},{"phrase":"get nowhere"},{"phrase":"in the middle of nowhere"}]',NULL,'/ˈnəʊwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/now/nowhe/nowhere__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2610,'ngsl-6-05',23,'pray','cầu nguyện; cầu mong','verb','[{"en":"We''re all praying for good weather on the wedding day.","vi":"Tất cả chúng tôi đều cầu mong trời đẹp vào ngày cưới."},{"en":"She prayed that her son would get home safely.","vi":"Cô ấy cầu mong con trai về nhà an toàn."},{"en":"My grandmother prays every morning before breakfast.","vi":"Bà tôi cầu nguyện mỗi sáng trước khi ăn sáng."}]','[{"phrase":"pray for"},{"phrase":"pray that"}]',NULL,'/preɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pray_/pray__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2611,'ngsl-6-05',24,'championship','giải vô địch; chức vô địch','noun','[{"en":"Our school team won the basketball championship this year.","vi":"Đội của trường chúng tôi đã vô địch giải bóng rổ năm nay."},{"en":"She''s training hard for the world championships next month.","vi":"Cô ấy đang tập luyện chăm chỉ cho giải vô địch thế giới vào tháng tới."},{"en":"The last game of the season will decide the championship.","vi":"Trận đấu cuối cùng của mùa giải sẽ quyết định chức vô địch."}]','[{"phrase":"win the championship"},{"phrase":"world championship"},{"phrase":"national championship"}]',NULL,'/ˈtʃæmpiənʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/champ/championship__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2612,'ngsl-6-05',25,'servant','người hầu; người phục vụ','noun','[{"en":"In the story, a loyal servant saves the young prince.","vi":"Trong câu chuyện, một người hầu trung thành đã cứu hoàng tử trẻ."},{"en":"The old house had small rooms upstairs for the servants.","vi":"Ngôi nhà cổ có những phòng nhỏ trên lầu dành cho người hầu."},{"en":"The rich family had three servants to cook and clean.","vi":"Gia đình giàu có đó có ba người hầu để nấu nướng và dọn dẹp."}]','[{"phrase":"loyal servant"},{"phrase":"civil servant"},{"phrase":"public servant"}]','civil servant: công chức','/ˈsɜːrvənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serva/servant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2613,'ngsl-6-05',26,'immigrant','người nhập cư','noun','[{"en":"Many immigrants came to the city looking for work.","vi":"Nhiều người nhập cư đã đến thành phố để tìm việc làm."},{"en":"My grandparents were immigrants who opened a small bakery.","vi":"Ông bà tôi là người nhập cư và đã mở một tiệm bánh nhỏ."},{"en":"The school offers free English classes for new immigrants.","vi":"Trường có các lớp tiếng Anh miễn phí dành cho người mới nhập cư."}]','[{"phrase":"new immigrants"},{"phrase":"immigrant family"},{"phrase":"immigrant workers"}]','immigrant (người nhập cư) ≠ emigrant (người di cư ra nước ngoài)','/ˈɪmɪɡrənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immig/immigrant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2614,'ngsl-6-05',27,'excess','sự dư thừa; phần thừa; sự vượt quá','noun','[{"en":"Eating sugar in excess is bad for your teeth.","vi":"Ăn quá nhiều đường không tốt cho răng."},{"en":"After gluing the edges, wipe off the excess with a cloth.","vi":"Sau khi dán các mép, hãy dùng khăn lau sạch phần keo thừa."},{"en":"This bridge can''t carry loads in excess of ten tons.","vi":"Cây cầu này không chịu được tải trọng vượt quá mười tấn."}]','[{"phrase":"in excess"},{"phrase":"in excess of"},{"phrase":"an excess of"},{"phrase":"excess baggage"}]',NULL,'/ɪkˈses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/exces/excess__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2615,'ngsl-6-05',28,'complexity','sự phức tạp; tính phức tạp','noun','[{"en":"Few people understand the complexity of the tax system.","vi":"Ít người hiểu được sự phức tạp của hệ thống thuế."},{"en":"The project grew in complexity as more people joined.","vi":"Dự án ngày càng phức tạp khi có thêm nhiều người tham gia."},{"en":"Many parents are surprised by the complexity of raising a teenager.","vi":"Nhiều bậc cha mẹ bất ngờ trước sự phức tạp của việc nuôi dạy con tuổi mới lớn."}]','[{"phrase":"the complexity of"},{"phrase":"grow in complexity"},{"phrase":"increasing complexity"},{"phrase":"great complexity"}]',NULL,'/kəmˈpleksəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complexity__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2616,'ngsl-6-05',29,'liability','trách nhiệm pháp lý; khoản nợ; gánh nặng','noun','[{"en":"The company accepted liability for the damage to our car.","vi":"Công ty đã nhận trách nhiệm pháp lý về thiệt hại cho xe của chúng tôi."},{"en":"The small shop closed because its liabilities grew too large.","vi":"Cửa hàng nhỏ phải đóng cửa vì các khoản nợ trở nên quá lớn."},{"en":"His bad temper has become a liability for the team.","vi":"Tính nóng nảy của anh ấy đã trở thành gánh nặng cho cả đội."}]','[{"phrase":"accept liability"},{"phrase":"legal liability"},{"phrase":"limited liability"},{"phrase":"deny liability"}]',NULL,'/ˌlaɪəˈbɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lia/liabi/liability__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2617,'ngsl-6-06',1,'surprisingly','một cách đáng ngạc nhiên; bất ngờ thay','adverb','[{"en":"The test was surprisingly easy, so everyone finished early.","vi":"Bài kiểm tra dễ một cách đáng ngạc nhiên, nên ai cũng làm xong sớm."},{"en":"Not surprisingly, the kids were tired after the long trip.","vi":"Chẳng có gì ngạc nhiên khi bọn trẻ mệt sau chuyến đi dài."},{"en":"Surprisingly, nobody in the office noticed that the lights were off.","vi":"Bất ngờ thay, không ai trong văn phòng để ý rằng đèn đã tắt."}]','[{"phrase":"not surprisingly"},{"phrase":"surprisingly good"},{"phrase":"surprisingly easy"},{"phrase":"surprisingly few"}]',NULL,'/sərˈpraɪzɪŋli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surpr/surprisingly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2618,'ngsl-6-06',2,'extract','chiết xuất; lấy ra; nhổ (răng)','verb','[{"en":"The oil is extracted from the seeds of the plant.","vi":"Dầu được chiết xuất từ hạt của loại cây này."},{"en":"The app can extract text from a photo in seconds.","vi":"Ứng dụng có thể lấy chữ ra từ một bức ảnh chỉ trong vài giây."},{"en":"The dentist had to extract two of my teeth last month.","vi":"Tháng trước nha sĩ phải nhổ hai cái răng của tôi."}]','[{"phrase":"extract information"},{"phrase":"extract data"},{"phrase":"extract oil"},{"phrase":"extract a tooth"}]','extract sth from sth','/ˈekstrækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extract__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2619,'ngsl-6-06',3,'implementation','sự thực hiện; sự triển khai','noun','[{"en":"The implementation of the new rules will begin next month.","vi":"Việc thực hiện các quy định mới sẽ bắt đầu vào tháng sau."},{"en":"We need more staff for the implementation of this project.","vi":"Chúng tôi cần thêm nhân viên để triển khai dự án này."},{"en":"Good ideas often fail because of poor implementation.","vi":"Ý tưởng hay thường thất bại vì triển khai kém."}]','[{"phrase":"implementation of"},{"phrase":"full implementation"},{"phrase":"successful implementation"},{"phrase":"policy implementation"}]',NULL,'/ˌɪmplɪmenˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imple/implementation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2620,'ngsl-6-06',4,'bias','sự thiên vị; thành kiến','noun','[{"en":"The teacher tried hard to grade every student without bias.","vi":"Giáo viên đã cố gắng chấm điểm mọi học sinh mà không thiên vị."},{"en":"Many people have a bias against workers who are older.","vi":"Nhiều người có thành kiến với những người lao động lớn tuổi hơn."},{"en":"Does this news report show a clear bias?","vi":"Bản tin này có thể hiện sự thiên vị rõ ràng không?"}]','[{"phrase":"bias against"},{"phrase":"bias toward"},{"phrase":"political bias"},{"phrase":"without bias"}]',NULL,'/ˈbaɪəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bia/bias_/bias__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2621,'ngsl-6-06',5,'differently','khác; theo cách khác','adverb','[{"en":"My brother and I see things very differently.","vi":"Anh trai tôi và tôi nhìn nhận mọi việc rất khác nhau."},{"en":"If I could start again, I would do it differently.","vi":"Nếu được bắt đầu lại, tôi sẽ làm theo cách khác."},{"en":"Children often behave differently when their parents are not around.","vi":"Trẻ con thường cư xử khác đi khi bố mẹ không ở bên cạnh."}]','[{"phrase":"think differently"},{"phrase":"do things differently"},{"phrase":"treat differently"},{"phrase":"see things differently"}]',NULL,'/ˈdɪfrəntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/differently__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2622,'ngsl-6-06',6,'catalog','danh mục; catalô (sách giới thiệu sản phẩm)','noun','[{"en":"I found this lamp in an online catalog last week.","vi":"Tôi tìm thấy cái đèn này trong một danh mục trực tuyến tuần trước."},{"en":"The store sends us a new catalog every spring.","vi":"Cửa hàng gửi cho chúng tôi một cuốn catalô mới vào mỗi mùa xuân."},{"en":"You can search the library catalog to see if the book is available.","vi":"Bạn có thể tra danh mục thư viện để xem cuốn sách có sẵn không."}]','[{"phrase":"online catalog"},{"phrase":"library catalog"},{"phrase":"product catalog"},{"phrase":"mail-order catalog"}]','Mỹ: catalog · Anh: catalogue','/ˈkætəlɔɡ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2623,'ngsl-6-06',7,'continuous','liên tục; không ngừng','adjective','[{"en":"The baby needs continuous care during the first few weeks.","vi":"Em bé cần được chăm sóc liên tục trong vài tuần đầu."},{"en":"We had three days of continuous rain last week.","vi":"Tuần trước trời mưa liên tục ba ngày."},{"en":"The factory runs a continuous process, day and night.","vi":"Nhà máy vận hành một quy trình liên tục, cả ngày lẫn đêm."}]','[{"phrase":"continuous process"},{"phrase":"continuous improvement"},{"phrase":"continuous flow"},{"phrase":"continuous use"}]','continuous (liên tục không gián đoạn) ≠ continual (lặp đi lặp lại)','/kənˈtɪnjuəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontinuous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2624,'ngsl-6-06',8,'golden','(màu) vàng óng; bằng vàng; quý giá','adjective','[{"en":"Bake the bread until the top is golden brown.","vi":"Nướng bánh mì cho đến khi mặt trên có màu vàng nâu."},{"en":"She wore a small golden ring on her left hand.","vi":"Cô ấy đeo một chiếc nhẫn vàng nhỏ ở tay trái."},{"en":"This job offer is a golden opportunity, so don''t miss it.","vi":"Lời mời làm việc này là một cơ hội vàng, đừng bỏ lỡ nhé."}]','[{"phrase":"golden brown"},{"phrase":"golden opportunity"},{"phrase":"golden hair"},{"phrase":"golden rule"}]',NULL,'/ˈɡəʊldən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gol/golde/golden__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2625,'ngsl-6-06',9,'stamp','tem (thư); con dấu','noun','[{"en":"Don''t forget to put a stamp on the letter.","vi":"Đừng quên dán tem lên lá thư nhé."},{"en":"My grandfather has collected stamps from many countries.","vi":"Ông tôi đã sưu tầm tem của nhiều nước."},{"en":"The officer put a stamp in my passport at the airport.","vi":"Nhân viên đóng dấu vào hộ chiếu của tôi ở sân bay."}]','[{"phrase":"postage stamp"},{"phrase":"stamp collection"},{"phrase":"put a stamp on"},{"phrase":"rubber stamp"}]',NULL,'/stæmp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stamp/stamp__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2626,'ngsl-6-06',10,'guideline','hướng dẫn; nguyên tắc chỉ đạo','noun','[{"en":"Please read the safety guidelines before using the machine.","vi":"Vui lòng đọc hướng dẫn an toàn trước khi sử dụng máy."},{"en":"The school has published new guidelines for online classes.","vi":"Nhà trường đã ban hành hướng dẫn mới cho các lớp học trực tuyến."},{"en":"All staff must follow these guidelines when talking to customers.","vi":"Mọi nhân viên phải tuân theo các nguyên tắc này khi nói chuyện với khách hàng."}]','[{"phrase":"follow guidelines"},{"phrase":"safety guidelines"},{"phrase":"clear guidelines"},{"phrase":"issue guidelines"}]','Thường dùng ở số nhiều: guidelines','/ˈɡaɪdlaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guide/guideline__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2627,'ngsl-6-06',11,'envelope','phong bì','noun','[{"en":"She put the card in an envelope and sealed it.","vi":"Cô ấy bỏ tấm thiếp vào phong bì rồi dán lại."},{"en":"Write your address clearly on the front of the envelope.","vi":"Hãy viết rõ địa chỉ của bạn ở mặt trước phong bì."},{"en":"My grandmother gave each of us an envelope with some money inside.","vi":"Bà tôi cho mỗi đứa chúng tôi một phong bì có ít tiền bên trong."}]','[{"phrase":"open an envelope"},{"phrase":"seal an envelope"},{"phrase":"brown envelope"},{"phrase":"stamped envelope"}]',NULL,'/ˈenvələʊp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envel/envelope__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2628,'ngsl-6-06',12,'knife','con dao','noun','[{"en":"Be careful, that knife is very sharp.","vi":"Cẩn thận nhé, con dao đó rất sắc."},{"en":"He cut the cake into eight pieces with a large knife.","vi":"Anh ấy dùng một con dao lớn cắt bánh thành tám miếng."},{"en":"Could you pass me a knife and fork, please?","vi":"Bạn đưa giúp tôi một bộ dao nĩa được không?"}]','[{"phrase":"sharp knife"},{"phrase":"kitchen knife"},{"phrase":"knife and fork"},{"phrase":"bread knife"}]','Số nhiều: knives','/naɪf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/k/kni/knife/knife__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2629,'ngsl-6-06',13,'biological','(thuộc) sinh học; ruột thịt (cha mẹ)','adjective','[{"en":"Sleep is a basic biological need for all humans.","vi":"Ngủ là một nhu cầu sinh học cơ bản của mọi người."},{"en":"The scientists are studying the biological effects of the new drug.","vi":"Các nhà khoa học đang nghiên cứu tác động sinh học của loại thuốc mới."},{"en":"He was adopted and never met his biological parents.","vi":"Anh ấy là con nuôi và chưa bao giờ gặp cha mẹ ruột của mình."}]','[{"phrase":"biological parents"},{"phrase":"biological process"},{"phrase":"biological clock"},{"phrase":"biological need"}]',NULL,'/ˌbaɪəˈlɑːdʒɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bio/biolo/biological__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2630,'ngsl-6-06',14,'consume','tiêu thụ; tiêu tốn; ăn, uống','verb','[{"en":"Old fridges consume a lot more electricity than new ones.","vi":"Tủ lạnh cũ tiêu thụ nhiều điện hơn hẳn tủ lạnh mới."},{"en":"This task consumed most of my time last week.","vi":"Công việc này đã tiêu tốn phần lớn thời gian của tôi tuần trước."},{"en":"Most people consume too much sugar without realizing it.","vi":"Hầu hết mọi người ăn quá nhiều đường mà không nhận ra."}]','[{"phrase":"consume energy"},{"phrase":"consume food"},{"phrase":"consume alcohol"},{"phrase":"consume calories"}]',NULL,'/kənˈsuːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsume__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2631,'ngsl-6-06',15,'luxury','sự xa xỉ; đồ xa xỉ; sang trọng','noun','[{"en":"They stayed in a luxury hotel for their honeymoon.","vi":"Họ ở một khách sạn sang trọng trong tuần trăng mật."},{"en":"For many students, eating out is a luxury.","vi":"Với nhiều sinh viên, ăn ngoài là một thứ xa xỉ."},{"en":"After the war, they could not afford any luxuries.","vi":"Sau chiến tranh, họ không thể mua nổi bất kỳ món đồ xa xỉ nào."}]','[{"phrase":"luxury hotel"},{"phrase":"luxury goods"},{"phrase":"a life of luxury"},{"phrase":"afford the luxury of"}]',NULL,'/ˈlʌkʃəri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lux/luxur/luxury__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2632,'ngsl-6-06',16,'weekly','hằng tuần','adjective','[{"en":"Our team has a weekly meeting every Monday morning.","vi":"Nhóm chúng tôi có buổi họp hằng tuần vào mỗi sáng thứ Hai."},{"en":"I do the weekly shopping at the market on Saturdays.","vi":"Tôi đi chợ mua đồ cho cả tuần vào các ngày thứ Bảy."},{"en":"The magazine is published weekly and costs three dollars.","vi":"Tạp chí này ra hằng tuần và có giá ba đô la."}]','[{"phrase":"weekly meeting"},{"phrase":"weekly basis"},{"phrase":"weekly shopping"},{"phrase":"twice weekly"}]',NULL,'/ˈwiːkli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wee/weekl/weekly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2633,'ngsl-6-06',17,'wherever','bất cứ nơi đâu; ở đâu cũng','conjunction','[{"en":"You can sit wherever you like in the classroom.","vi":"Em có thể ngồi bất cứ chỗ nào em thích trong lớp."},{"en":"My dog follows me wherever I go.","vi":"Con chó của tôi theo tôi đi bất cứ nơi đâu."},{"en":"Wherever you are in the city, you can see the tower.","vi":"Dù bạn ở đâu trong thành phố, bạn cũng có thể nhìn thấy ngọn tháp."}]','[{"phrase":"wherever you go"},{"phrase":"wherever possible"},{"phrase":"wherever you like"},{"phrase":"wherever you are"}]',NULL,'/werˈevər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/wherever__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2634,'ngsl-6-06',18,'bite','cắn; (côn trùng) đốt','verb','[{"en":"Don''t worry, our dog has never bitten anyone.","vi":"Đừng lo, con chó nhà tôi chưa bao giờ cắn ai cả."},{"en":"I got bitten by mosquitoes all night at the campsite.","vi":"Tôi bị muỗi đốt suốt đêm ở khu cắm trại."},{"en":"Try not to bite your nails when you feel nervous.","vi":"Cố gắng đừng cắn móng tay khi bạn thấy lo lắng."}]','[{"phrase":"bite your nails"},{"phrase":"bite into"},{"phrase":"bite your lip"},{"phrase":"get bitten"}]','bite – bit – bitten','/baɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bit/bite_/bite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2635,'ngsl-6-06',19,'printer','máy in','noun','[{"en":"The printer in our office has run out of paper again.","vi":"Máy in ở văn phòng chúng tôi lại hết giấy rồi."},{"en":"Can I use your printer to print my plane ticket?","vi":"Tôi dùng máy in của bạn để in vé máy bay được không?"},{"en":"We bought a cheap printer, but the ink is really expensive.","vi":"Chúng tôi mua một cái máy in rẻ, nhưng mực thì đắt thật."}]','[{"phrase":"laser printer"},{"phrase":"printer ink"},{"phrase":"color printer"},{"phrase":"printer paper"}]',NULL,'/ˈprɪntər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/print/printer__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2636,'ngsl-6-06',20,'firstly','thứ nhất; trước hết','adverb','[{"en":"Firstly, I would like to thank everyone for coming today.","vi":"Trước hết, tôi xin cảm ơn mọi người đã đến hôm nay."},{"en":"I can''t go, firstly because I''m busy and secondly because it''s expensive.","vi":"Tôi không đi được, thứ nhất vì tôi bận và thứ hai vì nó đắt."},{"en":"Firstly, turn off the power before you clean the machine.","vi":"Trước hết, hãy tắt nguồn trước khi lau chùi máy."}]','[{"phrase":"firstly, secondly"},{"phrase":"firstly because"}]','Dùng để liệt kê ý: firstly, secondly, finally','/ˈfɜːrstli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fir/first/firstly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2637,'ngsl-6-06',21,'anxious','lo lắng; nóng lòng, mong muốn','adjective','[{"en":"She always feels anxious before a big exam.","vi":"Cô ấy luôn cảm thấy lo lắng trước một kỳ thi quan trọng."},{"en":"My parents were anxious about my long trip alone.","vi":"Bố mẹ tôi lo lắng về chuyến đi dài một mình của tôi."},{"en":"We are anxious to hear your answer as soon as possible.","vi":"Chúng tôi nóng lòng muốn nghe câu trả lời của bạn càng sớm càng tốt."}]','[{"phrase":"anxious about"},{"phrase":"feel anxious"},{"phrase":"anxious to do"},{"phrase":"increasingly anxious"}]','anxious about sth · anxious to do sth','/ˈæŋkʃəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/anx/anxio/anxious__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2638,'ngsl-6-06',22,'adventure','cuộc phiêu lưu; sự mạo hiểm','noun','[{"en":"Our trip through the mountains was a real adventure.","vi":"Chuyến đi xuyên qua núi của chúng tôi là một cuộc phiêu lưu thực sự."},{"en":"The children love reading adventure stories before bed.","vi":"Bọn trẻ thích đọc truyện phiêu lưu trước khi đi ngủ."},{"en":"He quit his job because he wanted more adventure in his life.","vi":"Anh ấy bỏ việc vì muốn cuộc sống có thêm nhiều trải nghiệm mạo hiểm."}]','[{"phrase":"a real adventure"},{"phrase":"adventure story"},{"phrase":"sense of adventure"},{"phrase":"adventure travel"}]',NULL,'/ədˈventʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/adven/adventure__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2639,'ngsl-6-06',23,'fence','hàng rào','noun','[{"en":"We built a wooden fence around the garden.","vi":"Chúng tôi dựng một hàng rào gỗ quanh khu vườn."},{"en":"The cat jumped over the fence and ran away.","vi":"Con mèo nhảy qua hàng rào rồi chạy mất."},{"en":"There is a tall fence between our house and the road.","vi":"Có một hàng rào cao giữa nhà chúng tôi và con đường."}]','[{"phrase":"wooden fence"},{"phrase":"build a fence"},{"phrase":"over the fence"},{"phrase":"electric fence"}]',NULL,'/fens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fen/fence/fence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2640,'ngsl-6-06',24,'exhaust','làm kiệt sức; dùng cạn; khí thải','verb','[{"en":"The long walk in the heat completely exhausted me.","vi":"Chuyến đi bộ dài dưới trời nóng khiến tôi hoàn toàn kiệt sức."},{"en":"We have exhausted all our options, so we need a new plan.","vi":"Chúng ta đã dùng hết mọi phương án, nên cần một kế hoạch mới."},{"en":"The city is trying to reduce exhaust from cars and buses.","vi":"Thành phố đang cố gắng giảm khí thải từ ô tô và xe buýt."}]','[{"phrase":"exhaust fumes"},{"phrase":"exhaust pipe"},{"phrase":"exhaust all options"},{"phrase":"exhaust resources"}]','Tính từ: exhausted (kiệt sức), exhausting (gây mệt mỏi)','/ɪɡˈzɔːst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhau/exhaust__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2641,'ngsl-6-06',25,'attraction','điểm tham quan; sự thu hút; sức hấp dẫn','noun','[{"en":"The old bridge is the main tourist attraction in our town.","vi":"Cây cầu cổ là điểm tham quan chính của thị trấn chúng tôi."},{"en":"The beach is the biggest attraction of this hotel.","vi":"Bãi biển là điểm thu hút lớn nhất của khách sạn này."},{"en":"I don''t understand the attraction of watching TV all day.","vi":"Tôi không hiểu việc xem TV cả ngày có gì hấp dẫn."}]','[{"phrase":"tourist attraction"},{"phrase":"main attraction"},{"phrase":"major attraction"},{"phrase":"attraction of"}]',NULL,'/əˈtrækʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attra/attraction__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2642,'ngsl-6-06',26,'ocean','đại dương; biển','noun','[{"en":"We rented a small house with a view of the ocean.","vi":"Chúng tôi thuê một căn nhà nhỏ nhìn ra biển."},{"en":"Plastic waste is a serious problem for the world''s oceans.","vi":"Rác thải nhựa là một vấn đề nghiêm trọng đối với các đại dương trên thế giới."},{"en":"Have you ever swum in the ocean at night?","vi":"Bạn đã bao giờ bơi ở biển vào ban đêm chưa?"}]','[{"phrase":"Pacific Ocean"},{"phrase":"ocean floor"},{"phrase":"across the ocean"},{"phrase":"ocean view"}]',NULL,'/ˈəʊʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oce/ocean/ocean__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2643,'ngsl-6-06',27,'quietly','một cách lặng lẽ; khẽ, nhỏ nhẹ','adverb','[{"en":"Please talk quietly because the baby is asleep.","vi":"Làm ơn nói nhỏ thôi vì em bé đang ngủ."},{"en":"He quietly closed the door and left the room.","vi":"Anh ấy lặng lẽ đóng cửa và rời khỏi phòng."},{"en":"The students sat quietly and waited for the test to begin.","vi":"Học sinh ngồi yên lặng và chờ bài kiểm tra bắt đầu."}]','[{"phrase":"speak quietly"},{"phrase":"sit quietly"},{"phrase":"work quietly"},{"phrase":"quietly confident"}]',NULL,'/ˈkwaɪətli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qui/quiet/quietly__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2644,'ngsl-6-06',28,'castle','lâu đài','noun','[{"en":"We visited an old castle on a hill near the river.","vi":"Chúng tôi đã tham quan một lâu đài cổ trên đồi gần con sông."},{"en":"The kids spent the afternoon building sand castles on the beach.","vi":"Bọn trẻ dành cả buổi chiều xây lâu đài cát trên bãi biển."},{"en":"This castle was built more than seven hundred years ago.","vi":"Lâu đài này được xây dựng cách đây hơn bảy trăm năm."}]','[{"phrase":"old castle"},{"phrase":"sand castle"},{"phrase":"castle walls"},{"phrase":"medieval castle"}]',NULL,'/ˈkæsl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/castl/castle__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2645,'ngsl-6-06',29,'veteran','cựu chiến binh; người kỳ cựu, lão luyện','noun','[{"en":"My grandfather is a veteran and often talks about his army days.","vi":"Ông tôi là cựu chiến binh và thường kể về những ngày trong quân đội."},{"en":"The town held a special lunch for local veterans.","vi":"Thị trấn tổ chức một bữa trưa đặc biệt dành cho các cựu chiến binh địa phương."},{"en":"She is a veteran of the hotel business with thirty years of experience.","vi":"Bà ấy là người kỳ cựu trong ngành khách sạn với ba mươi năm kinh nghiệm."}]','[{"phrase":"war veteran"},{"phrase":"army veteran"},{"phrase":"veteran of"},{"phrase":"veteran player"}]',NULL,'/ˈvetərən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vet/veter/veteran__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2646,'ngsl-6-11',1,'faithfully','trung thành; tận tụy; sát, chính xác','adverb','[{"en":"Our dog waited faithfully by the door until we came home.","vi":"Chú chó của chúng tôi trung thành chờ bên cửa cho đến khi chúng tôi về nhà."},{"en":"He faithfully visited his grandmother every Sunday for ten years.","vi":"Suốt mười năm, anh ấy tận tụy đến thăm bà vào mỗi Chủ nhật."},{"en":"The movie faithfully follows the story in the original book.","vi":"Bộ phim bám sát câu chuyện trong cuốn sách gốc."}]','[{"phrase":"Yours faithfully"},{"phrase":"serve faithfully"},{"phrase":"faithfully follow"}]','Yours faithfully: câu kết thư trang trọng khi không biết tên người nhận','/ˈfeɪθfəli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/faith/faithfully__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2647,'ngsl-6-11',2,'autumn','mùa thu','noun','[{"en":"The leaves on these trees turn red in autumn.","vi":"Lá của những cây này chuyển sang màu đỏ vào mùa thu."},{"en":"We are planning a trip to the mountains next autumn.","vi":"Chúng tôi đang lên kế hoạch đi núi vào mùa thu năm sau."},{"en":"Autumn is my favorite season because the weather is cool.","vi":"Mùa thu là mùa tôi thích nhất vì thời tiết mát mẻ."}]','[{"phrase":"in autumn"},{"phrase":"next autumn"},{"phrase":"last autumn"},{"phrase":"autumn leaves"}]','Anh: autumn · Mỹ: fall','/ˈɔːtəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autum/autumn__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2648,'ngsl-6-11',3,'cheek','má','noun','[{"en":"She kissed her grandson on the cheek and said goodbye.","vi":"Bà hôn lên má cháu trai rồi chào tạm biệt."},{"en":"Tears were running down his cheeks as he read the letter.","vi":"Nước mắt chảy dài trên má anh ấy khi anh đọc bức thư."},{"en":"The baby has round, pink cheeks and a big smile.","vi":"Em bé có đôi má tròn, hồng hào và nụ cười thật tươi."}]','[{"phrase":"on the cheek"},{"phrase":"rosy cheeks"},{"phrase":"down his cheeks"}]',NULL,'/tʃiːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/cheek/cheek__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2649,'ngsl-6-11',4,'attachment','tệp đính kèm; sự gắn bó','noun','[{"en":"I sent you the report as an attachment this morning.","vi":"Sáng nay tôi đã gửi cho bạn bản báo cáo dưới dạng tệp đính kèm."},{"en":"Please don''t open email attachments from people you don''t know.","vi":"Vui lòng đừng mở tệp đính kèm trong email từ những người bạn không quen biết."},{"en":"Children often form a strong attachment to their first teacher.","vi":"Trẻ em thường rất gắn bó với giáo viên đầu tiên của mình."}]','[{"phrase":"email attachment"},{"phrase":"send an attachment"},{"phrase":"strong attachment"},{"phrase":"attachment to"}]',NULL,'/əˈtætʃmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attachment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2650,'ngsl-6-11',5,'holder','người giữ, người sở hữu; giá đỡ, đồ đựng','noun','[{"en":"Only ticket holders can enter the stadium after six o''clock.","vi":"Sau sáu giờ, chỉ những người có vé mới được vào sân vận động."},{"en":"She is the current holder of the national swimming record.","vi":"Cô ấy là người đang giữ kỷ lục bơi lội quốc gia."},{"en":"I use a phone holder in the car so I can see the map.","vi":"Tôi dùng giá đỡ điện thoại trên xe để có thể xem bản đồ."}]','[{"phrase":"ticket holder"},{"phrase":"record holder"},{"phrase":"card holder"},{"phrase":"phone holder"}]',NULL,'/ˈhəʊldər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/holde/holder__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2651,'ngsl-6-11',6,'solar','(thuộc) mặt trời','adjective','[{"en":"We put solar panels on our roof to save money.","vi":"Chúng tôi lắp tấm pin mặt trời trên mái nhà để tiết kiệm tiền."},{"en":"Solar energy is becoming cheaper and more popular every year.","vi":"Năng lượng mặt trời ngày càng rẻ hơn và phổ biến hơn mỗi năm."},{"en":"Our class made a model of the solar system for the science fair.","vi":"Lớp chúng tôi đã làm mô hình hệ Mặt Trời cho hội chợ khoa học."}]','[{"phrase":"solar energy"},{"phrase":"solar power"},{"phrase":"solar panel"},{"phrase":"solar system"}]',NULL,'/ˈsəʊlər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/solar/solar__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2652,'ngsl-6-11',7,'grin','cười toe toét, cười nhe răng','verb','[{"en":"He grinned when he saw his exam results.","vi":"Cậu ấy cười toe toét khi thấy kết quả thi."},{"en":"The children were grinning from ear to ear at the party.","vi":"Bọn trẻ cười ngoác cả miệng ở bữa tiệc."},{"en":"Why are you grinning at me like that?","vi":"Sao bạn cứ nhe răng cười với tôi như thế?"}]','[{"phrase":"grin from ear to ear"},{"phrase":"grin at"},{"phrase":"grin broadly"}]','grin – grinned – grinned','/ɡrɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gri/grin_/grin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2653,'ngsl-6-11',8,'rose','hoa hồng','noun','[{"en":"He gave his wife a dozen red roses on her birthday.","vi":"Anh ấy tặng vợ mười hai bông hồng đỏ vào ngày sinh nhật cô ấy."},{"en":"My grandmother grows beautiful roses in her small garden.","vi":"Bà tôi trồng những bông hồng rất đẹp trong khu vườn nhỏ của bà."},{"en":"A single white rose stood in a glass vase on the table.","vi":"Một bông hồng trắng được cắm trong chiếc bình thủy tinh trên bàn."}]','[{"phrase":"red roses"},{"phrase":"grow roses"},{"phrase":"a bunch of roses"},{"phrase":"rose garden"}]','rose cũng là quá khứ của rise (rise – rose – risen)','/rəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ros/rose_/rose__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2654,'ngsl-6-11',9,'noun','danh từ','noun','[{"en":"In English, we usually add s to a noun to make it plural.","vi":"Trong tiếng Anh, chúng ta thường thêm s vào danh từ để tạo dạng số nhiều."},{"en":"Can you find all the nouns in this sentence?","vi":"Bạn có thể tìm tất cả các danh từ trong câu này không?"},{"en":"Information is an uncountable noun, so it has no plural form.","vi":"Information là danh từ không đếm được nên không có dạng số nhiều."}]','[{"phrase":"countable noun"},{"phrase":"uncountable noun"},{"phrase":"plural noun"},{"phrase":"proper noun"}]',NULL,'/naʊn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nou/noun_/noun__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2655,'ngsl-6-11',10,'fortunate','may mắn','adjective','[{"en":"We were fortunate to find a hotel room so late at night.","vi":"Chúng tôi may mắn tìm được phòng khách sạn vào lúc đêm muộn như vậy."},{"en":"I feel very fortunate to have such kind friends.","vi":"Tôi cảm thấy rất may mắn khi có những người bạn tốt bụng như vậy."},{"en":"It was fortunate that nobody was hurt in the accident.","vi":"Thật may là không ai bị thương trong vụ tai nạn."}]','[{"phrase":"fortunate to"},{"phrase":"fortunate enough"},{"phrase":"feel fortunate"},{"phrase":"less fortunate"}]',NULL,'/ˈfɔːrtʃənət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/fortu/fortunate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2656,'ngsl-6-11',11,'alright','ổn, không sao; được rồi','adjective','[{"en":"You look pale. Are you feeling alright?","vi":"Trông bạn xanh xao quá. Bạn thấy ổn chứ?"},{"en":"Don''t worry, everything will be alright in the end.","vi":"Đừng lo, cuối cùng mọi chuyện sẽ ổn thôi."},{"en":"Alright, let''s take a short break and meet back here at three.","vi":"Được rồi, chúng ta nghỉ một chút rồi gặp lại ở đây lúc ba giờ."}]','[{"phrase":"feel alright"},{"phrase":"be alright"},{"phrase":"it''s alright"}]','= all right (all right trang trọng hơn)','/ɔːlˈraɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/all_r/all_right_1_us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2657,'ngsl-6-11',12,'lazy','lười biếng; thong thả, nhàn nhã','adjective','[{"en":"My brother is too lazy to clean his own room.","vi":"Em trai tôi lười đến mức không chịu tự dọn phòng của mình."},{"en":"Don''t be lazy; finish your homework before dinner.","vi":"Đừng lười biếng, hãy làm xong bài tập trước bữa tối."},{"en":"We spent a lazy Sunday afternoon reading in the garden.","vi":"Chúng tôi đã có một buổi chiều Chủ nhật thong thả đọc sách trong vườn."}]','[{"phrase":"too lazy to"},{"phrase":"lazy afternoon"},{"phrase":"lazy day"},{"phrase":"feel lazy"}]',NULL,'/ˈleɪzi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/laz/lazy_/lazy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2658,'ngsl-6-11',13,'hello','xin chào; a lô','exclamation','[{"en":"Hello, I''m your new neighbor from the apartment upstairs.","vi":"Xin chào, tôi là hàng xóm mới ở căn hộ tầng trên."},{"en":"When I answered the phone and said hello, nobody replied.","vi":"Khi tôi nhấc máy và nói a lô, không ai trả lời cả."},{"en":"Please say hello to your parents for me.","vi":"Cho tôi gửi lời chào đến bố mẹ bạn nhé."}]','[{"phrase":"say hello"},{"phrase":"say hello to"},{"phrase":"hello again"}]',NULL,'/həˈləʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hel/hello/hello__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2659,'ngsl-6-11',14,'hunger','cơn đói, sự đói; sự khao khát','noun','[{"en":"After the long hike, we were all weak with hunger.","vi":"Sau chuyến đi bộ dài, tất cả chúng tôi đều lả đi vì đói."},{"en":"Drinking water can help you control your hunger between meals.","vi":"Uống nước có thể giúp bạn kiềm chế cơn đói giữa các bữa ăn."},{"en":"She has a real hunger for knowledge and reads every day.","vi":"Cô ấy thực sự khao khát tri thức và đọc sách mỗi ngày."}]','[{"phrase":"weak with hunger"},{"phrase":"hunger for knowledge"},{"phrase":"hunger pangs"}]',NULL,'/ˈhʌŋɡər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hun/hunge/hunger__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2660,'ngsl-6-11',15,'insure','bảo hiểm, mua bảo hiểm','verb','[{"en":"You should insure your car before driving it on the road.","vi":"Bạn nên mua bảo hiểm cho xe trước khi lái nó ra đường."},{"en":"Our house is insured against fire and flood damage.","vi":"Ngôi nhà của chúng tôi được bảo hiểm chống hỏa hoạn và thiệt hại do lũ lụt."},{"en":"The company refused to insure him because of his health problems.","vi":"Công ty đã từ chối bảo hiểm cho anh ấy vì các vấn đề sức khỏe."}]','[{"phrase":"insure against"},{"phrase":"fully insured"},{"phrase":"insure your car"}]','insure (bảo hiểm) ≠ ensure (đảm bảo)','/ɪnˈʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insur/insure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2661,'ngsl-6-11',16,'ashamed','xấu hổ, hổ thẹn','adjective','[{"en":"I was ashamed of the way I spoke to my mother.","vi":"Tôi thấy xấu hổ vì cách mình đã nói chuyện với mẹ."},{"en":"You have nothing to be ashamed of.","vi":"Bạn không có gì phải xấu hổ cả."},{"en":"He felt too ashamed to tell anyone about his mistake.","vi":"Anh ấy xấu hổ đến mức không dám kể với ai về sai lầm của mình."}]','[{"phrase":"ashamed of"},{"phrase":"feel ashamed"},{"phrase":"deeply ashamed"},{"phrase":"ashamed to admit"}]','đi với giới từ of: be ashamed of something','/əˈʃeɪmd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ash/asham/ashamed__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2662,'ngsl-6-11',17,'found','thành lập, sáng lập','verb','[{"en":"My grandfather founded this small bakery fifty years ago.","vi":"Ông tôi đã thành lập tiệm bánh nhỏ này cách đây năm mươi năm."},{"en":"The school was founded in 1920 by a group of teachers.","vi":"Ngôi trường do một nhóm giáo viên thành lập vào năm 1920."},{"en":"They plan to found a charity to help children in poor areas.","vi":"Họ dự định thành lập một tổ chức từ thiện để giúp đỡ trẻ em ở vùng nghèo."}]','[{"phrase":"found a company"},{"phrase":"found a charity"},{"phrase":"founded in"},{"phrase":"newly founded"}]','found – founded – founded; khác với found (quá khứ của find)','/faʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/found__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2663,'ngsl-6-11',18,'blog','blog, nhật ký trên mạng','noun','[{"en":"She writes a travel blog about her trips around Asia.","vi":"Cô ấy viết blog du lịch về những chuyến đi vòng quanh châu Á."},{"en":"I read an interesting blog post about healthy cooking today.","vi":"Hôm nay tôi đọc một bài blog thú vị về nấu ăn lành mạnh."},{"en":"He started a blog to share tips for new parents.","vi":"Anh ấy lập một blog để chia sẻ mẹo cho những người mới làm cha mẹ."}]','[{"phrase":"blog post"},{"phrase":"start a blog"},{"phrase":"write a blog"},{"phrase":"travel blog"}]',NULL,'/blɑːɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/blog_/blog__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2664,'ngsl-6-11',19,'thirst','cơn khát, sự khát; sự khao khát','noun','[{"en":"We were dying of thirst after playing football all afternoon.","vi":"Chúng tôi khát khô cả cổ sau khi đá bóng suốt buổi chiều."},{"en":"On hot days, people often mistake thirst for hunger.","vi":"Vào những ngày nóng, người ta thường nhầm cơn khát thành cơn đói."},{"en":"Many young people have a strong thirst for adventure.","vi":"Nhiều người trẻ có niềm khao khát phiêu lưu mãnh liệt."}]','[{"phrase":"quench your thirst"},{"phrase":"dying of thirst"},{"phrase":"thirst for adventure"}]',NULL,'/θɜːrst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thi/thirs/thirst__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2665,'ngsl-6-07',1,'reflection','hình ảnh phản chiếu; sự suy ngẫm','noun','[{"en":"She could see her reflection in the shop window.","vi":"Cô ấy có thể thấy hình ảnh phản chiếu của mình trên cửa kính cửa hàng."},{"en":"The reflection of the mountains in the lake was beautiful.","vi":"Hình ảnh phản chiếu của những ngọn núi trên mặt hồ thật đẹp."},{"en":"After careful reflection, I decided to accept the job offer.","vi":"Sau khi suy ngẫm kỹ, tôi quyết định nhận lời mời làm việc."}]','[{"phrase":"careful reflection"},{"phrase":"on reflection"},{"phrase":"a moment of reflection"}]',NULL,'/rɪˈflekʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refle/reflection__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2666,'ngsl-6-07',2,'nerve','dây thần kinh; sự can đảm','noun','[{"en":"The accident caused nerve damage in his left hand.","vi":"Vụ tai nạn đã gây tổn thương dây thần kinh ở tay trái của anh ấy."},{"en":"I finally found the nerve to ask for a raise.","vi":"Cuối cùng tôi cũng đủ can đảm để xin tăng lương."},{"en":"She lost her nerve at the last minute and didn''t jump.","vi":"Cô ấy mất hết can đảm vào phút cuối và không nhảy."}]','[{"phrase":"nerve damage"},{"phrase":"lose your nerve"},{"phrase":"have the nerve to"}]','get on someone''s nerves = làm ai phát bực','/nɜːrv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/ner/nerve/nerve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2667,'ngsl-6-07',3,'determination','sự quyết tâm','noun','[{"en":"Her determination to finish the marathon impressed everyone.","vi":"Quyết tâm hoàn thành cuộc chạy marathon của cô ấy khiến mọi người ấn tượng."},{"en":"With hard work and determination, you can learn any language.","vi":"Với sự chăm chỉ và quyết tâm, bạn có thể học bất kỳ ngôn ngữ nào."},{"en":"He showed great determination while recovering from his injury.","vi":"Anh ấy đã thể hiện quyết tâm lớn trong lúc hồi phục sau chấn thương."}]','[{"phrase":"great determination"},{"phrase":"show determination"},{"phrase":"determination to succeed"}]','không đếm được','/dɪˌtɜːrmɪˈneɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/deter/determination__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2668,'ngsl-6-07',4,'altogether','hoàn toàn; tổng cộng','adverb','[{"en":"The meal cost us sixty dollars altogether, including the tip.","vi":"Bữa ăn tốn của chúng tôi tổng cộng sáu mươi đô la, tính cả tiền boa."},{"en":"There were twenty people at the party altogether.","vi":"Có tổng cộng hai mươi người tại bữa tiệc."},{"en":"My grandfather used to smoke, but he''s stopped altogether.","vi":"Ông tôi từng hút thuốc, nhưng giờ ông đã bỏ hẳn."}]','[{"phrase":"stop altogether"},{"phrase":"disappear altogether"},{"phrase":"not altogether"}]','altogether (hoàn toàn) ≠ all together (tất cả cùng nhau)','/ˌɔːltəˈɡeðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/altog/altogether__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2669,'ngsl-6-07',5,'fiction','truyện hư cấu, tiểu thuyết; điều bịa đặt','noun','[{"en":"I prefer reading fiction to reading history books.","vi":"Tôi thích đọc truyện hư cấu hơn đọc sách lịch sử."},{"en":"She has written several works of science fiction.","vi":"Cô ấy đã viết một vài tác phẩm khoa học viễn tưởng."},{"en":"His story about meeting a famous singer was pure fiction.","vi":"Câu chuyện anh ta kể về việc gặp một ca sĩ nổi tiếng hoàn toàn là bịa đặt."}]','[{"phrase":"science fiction"},{"phrase":"a work of fiction"},{"phrase":"pure fiction"}]','không đếm được','/ˈfɪkʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fic/ficti/fiction__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2670,'ngsl-6-07',6,'carpet','tấm thảm','noun','[{"en":"Could you vacuum the carpet before our guests arrive tonight?","vi":"Bạn có thể hút bụi tấm thảm trước khi khách đến tối nay không?"},{"en":"We bought a new carpet for the living room.","vi":"Chúng tôi đã mua một tấm thảm mới cho phòng khách."},{"en":"The cat is sleeping on the carpet near the fireplace.","vi":"Con mèo đang ngủ trên tấm thảm gần lò sưởi."}]','[{"phrase":"vacuum the carpet"},{"phrase":"thick carpet"},{"phrase":"red carpet"}]',NULL,'/ˈkɑːrpɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/carpe/carpet__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2671,'ngsl-6-07',7,'cluster','cụm, chùm; nhóm','noun','[{"en":"A small cluster of houses stood at the foot of the hill.","vi":"Một cụm nhà nhỏ nằm dưới chân đồi."},{"en":"Students gathered in small clusters around the notice board.","vi":"Học sinh tụ tập thành từng nhóm nhỏ quanh bảng thông báo."},{"en":"In our garden, the grapes grow in large clusters every summer.","vi":"Trong vườn nhà chúng tôi, nho mọc thành từng chùm lớn mỗi mùa hè."}]','[{"phrase":"a cluster of"},{"phrase":"small cluster"},{"phrase":"in clusters"}]',NULL,'/ˈklʌstər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clu/clust/cluster__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2672,'ngsl-6-07',8,'confusion','sự nhầm lẫn; sự bối rối','noun','[{"en":"There was some confusion about the time of the meeting.","vi":"Đã có chút nhầm lẫn về giờ họp."},{"en":"To avoid confusion, please write your name on your bag.","vi":"Để tránh nhầm lẫn, hãy viết tên bạn lên túi."},{"en":"She looked at me in confusion when I spoke French.","vi":"Cô ấy nhìn tôi đầy bối rối khi tôi nói tiếng Pháp."}]','[{"phrase":"avoid confusion"},{"phrase":"cause confusion"},{"phrase":"confusion about"}]',NULL,'/kənˈfjuːʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfusion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2673,'ngsl-6-07',9,'hurry','vội vàng, khẩn trương','verb','[{"en":"We need to hurry or we''ll miss the bus.","vi":"Chúng ta phải nhanh lên, không thì sẽ lỡ xe buýt."},{"en":"Hurry up, the movie starts in ten minutes!","vi":"Nhanh lên, phim bắt đầu trong mười phút nữa!"},{"en":"She hurried home when it started to rain.","vi":"Cô ấy vội vã về nhà khi trời bắt đầu mưa."}]','[{"phrase":"hurry up"},{"phrase":"hurry home"},{"phrase":"hurry back"}]','in a hurry = đang vội','/ˈhɜːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hur/hurry/hurry__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2674,'ngsl-6-07',10,'logic','logic; lý lẽ hợp lý','noun','[{"en":"I don''t understand the logic behind this decision.","vi":"Tôi không hiểu logic đằng sau quyết định này."},{"en":"There is no logic in paying more for the same product.","vi":"Chẳng có lý gì khi trả nhiều tiền hơn cho cùng một sản phẩm."},{"en":"His argument sounds good, but the logic is weak.","vi":"Lập luận của anh ấy nghe có vẻ hay, nhưng logic thì yếu."}]','[{"phrase":"the logic behind"},{"phrase":"simple logic"},{"phrase":"follow the logic"}]','không đếm được','/ˈlɑːdʒɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/log/logic/logic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2675,'ngsl-6-07',11,'controversial','gây tranh cãi','adjective','[{"en":"Whether to allow phones in class is a controversial issue.","vi":"Có nên cho phép dùng điện thoại trong lớp hay không là một vấn đề gây tranh cãi."},{"en":"The movie''s ending was quite controversial among fans.","vi":"Cái kết của bộ phim khá gây tranh cãi trong giới người hâm mộ."},{"en":"The referee made a controversial decision in the final minute.","vi":"Trọng tài đã đưa ra một quyết định gây tranh cãi ở phút cuối."}]','[{"phrase":"controversial issue"},{"phrase":"controversial decision"},{"phrase":"highly controversial"}]',NULL,'/ˌkɑːntrəˈvɜːrʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontroversial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2676,'ngsl-6-07',12,'raw','sống, chưa nấu chín; thô, chưa qua chế biến','adjective','[{"en":"You shouldn''t eat raw chicken because it can make you sick.","vi":"Bạn không nên ăn thịt gà sống vì nó có thể làm bạn bị bệnh."},{"en":"I like to add raw carrots to my salad.","vi":"Tôi thích cho cà rốt sống vào món salad."},{"en":"The factory imports raw materials from several countries.","vi":"Nhà máy nhập khẩu nguyên liệu thô từ một vài quốc gia."}]','[{"phrase":"raw materials"},{"phrase":"raw meat"},{"phrase":"raw fish"}]',NULL,'/rɔː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/raw/raw__/raw__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2677,'ngsl-6-07',13,'grammar','ngữ pháp','noun','[{"en":"My English grammar is good, but my pronunciation needs work.","vi":"Ngữ pháp tiếng Anh của tôi tốt, nhưng phát âm thì cần cải thiện."},{"en":"The teacher corrected the grammar mistakes in my essay.","vi":"Giáo viên đã sửa các lỗi ngữ pháp trong bài luận của tôi."},{"en":"Do you have a good grammar book for beginners?","vi":"Bạn có cuốn sách ngữ pháp nào tốt cho người mới bắt đầu không?"}]','[{"phrase":"English grammar"},{"phrase":"grammar mistake"},{"phrase":"grammar book"},{"phrase":"grammar rules"}]','không đếm được','/ˈɡræmər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gramm/grammar__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2678,'ngsl-6-07',14,'revise','sửa lại, điều chỉnh; ôn tập','verb','[{"en":"I revised my essay three times before handing it in.","vi":"Tôi đã sửa lại bài luận ba lần trước khi nộp."},{"en":"The company has revised its prices for next year.","vi":"Công ty đã điều chỉnh giá cho năm tới."},{"en":"I need to revise for my history exam tomorrow.","vi":"Tôi cần ôn bài cho kỳ thi lịch sử ngày mai."}]','[{"phrase":"revise for"},{"phrase":"revise a plan"},{"phrase":"revised version"}]','nghĩa "ôn tập" dùng ở Anh; Mỹ dùng review/study','/rɪˈvaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revis/revise__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2679,'ngsl-6-07',15,'hint','lời gợi ý; chút, dấu hiệu','noun','[{"en":"If you can''t guess the answer, I''ll give you a hint.","vi":"Nếu bạn không đoán ra đáp án, tôi sẽ gợi ý cho bạn."},{"en":"He dropped a hint that he wanted a new bike for his birthday.","vi":"Cậu ấy bóng gió rằng mình muốn có một chiếc xe đạp mới vào dịp sinh nhật."},{"en":"There was a hint of sadness in her voice.","vi":"Trong giọng nói của cô ấy có chút buồn."}]','[{"phrase":"give a hint"},{"phrase":"drop a hint"},{"phrase":"a hint of"}]',NULL,'/hɪnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hin/hint_/hint__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2680,'ngsl-6-07',16,'hook','cái móc; lưỡi câu','noun','[{"en":"Hang your coat on the hook behind the door.","vi":"Hãy treo áo khoác lên cái móc sau cánh cửa."},{"en":"My father put a small worm on the fishing hook.","vi":"Bố tôi móc một con giun nhỏ vào lưỡi câu."},{"en":"There are three hooks by the door for our keys.","vi":"Có ba cái móc cạnh cửa để treo chìa khóa của chúng tôi."}]','[{"phrase":"coat hook"},{"phrase":"fishing hook"},{"phrase":"on a hook"}]','let someone off the hook = tha cho ai','/hʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hoo/hook_/hook__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2681,'ngsl-6-07',17,'bell','cái chuông; tiếng chuông','noun','[{"en":"The school bell rings at seven thirty every morning.","vi":"Chuông trường reo lúc bảy giờ ba mươi mỗi sáng."},{"en":"Someone rang the bell, so I went to open the door.","vi":"Có người bấm chuông nên tôi ra mở cửa."},{"en":"Our cat wears a tiny bell around its neck.","vi":"Con mèo của chúng tôi đeo một cái chuông nhỏ quanh cổ."}]','[{"phrase":"ring the bell"},{"phrase":"school bell"},{"phrase":"the bell rings"}]',NULL,'/bel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/bell_/bell__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2682,'ngsl-6-07',18,'liquid','chất lỏng','noun','[{"en":"The bottle was filled with a clear liquid that smelled like lemons.","vi":"Cái chai chứa đầy một chất lỏng trong suốt có mùi chanh."},{"en":"You can''t bring large bottles of liquid onto the plane.","vi":"Bạn không được mang những chai chất lỏng lớn lên máy bay."},{"en":"Drink plenty of liquids when you have a fever.","vi":"Khi bị sốt, bạn nên uống nhiều chất lỏng."}]','[{"phrase":"clear liquid"},{"phrase":"plenty of liquids"}]',NULL,'/ˈlɪkwɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/liq/liqui/liquid__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2683,'ngsl-6-07',19,'panic','hoảng sợ, hoảng loạn','verb','[{"en":"Don''t panic, we still have plenty of time to catch the train.","vi":"Đừng hoảng, chúng ta vẫn còn nhiều thời gian để kịp chuyến tàu."},{"en":"She panicked when she couldn''t find her passport at the airport.","vi":"Cô ấy hoảng hốt khi không tìm thấy hộ chiếu ở sân bay."},{"en":"People started to panic when the lights suddenly went out.","vi":"Mọi người bắt đầu hoảng loạn khi đèn đột nhiên tắt."}]','[{"phrase":"don''t panic"},{"phrase":"start to panic"},{"phrase":"in a panic"}]','panic – panicked – panicked','/ˈpænɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pan/panic/panic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2684,'ngsl-6-07',20,'uncle','chú, bác, cậu, dượng','noun','[{"en":"My uncle lives on a farm in the countryside.","vi":"Chú tôi sống ở một trang trại dưới quê."},{"en":"We''re visiting my aunt and uncle this weekend.","vi":"Cuối tuần này chúng tôi sẽ đến thăm cô chú tôi."},{"en":"Her uncle taught her how to ride a bike.","vi":"Cậu của cô ấy đã dạy cô ấy đi xe đạp."}]','[{"phrase":"aunt and uncle"},{"phrase":"favorite uncle"}]',NULL,'/ˈʌŋkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unc/uncle/uncle__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2685,'ngsl-6-07',21,'rice','gạo; cơm; lúa','noun','[{"en":"We eat rice with almost every meal at home.","vi":"Ở nhà, chúng tôi ăn cơm gần như mọi bữa."},{"en":"My grandparents grow rice in the fields near their village.","vi":"Ông bà tôi trồng lúa trên những cánh đồng gần làng."},{"en":"Could you buy a bag of rice on your way home?","vi":"Bạn mua giúp một bao gạo trên đường về nhà được không?"}]','[{"phrase":"grow rice"},{"phrase":"a bowl of rice"},{"phrase":"fried rice"},{"phrase":"a bag of rice"}]','không đếm được','/raɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ric/rice_/rice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2686,'ngsl-6-07',22,'slope','con dốc; sườn đồi','noun','[{"en":"We walked slowly up the steep slope to the top.","vi":"Chúng tôi chậm rãi đi bộ lên con dốc đứng để lên tới đỉnh."},{"en":"Their house sits on a gentle slope overlooking the river.","vi":"Ngôi nhà của họ nằm trên một sườn đồi thoai thoải nhìn ra sông."},{"en":"Beginners should practice skiing on the easier slopes first.","vi":"Người mới bắt đầu nên tập trượt tuyết ở những con dốc dễ hơn trước."}]','[{"phrase":"steep slope"},{"phrase":"gentle slope"},{"phrase":"ski slope"}]',NULL,'/sləʊp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/slo/slope/slope__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2687,'ngsl-6-07',23,'happiness','hạnh phúc, niềm vui','noun','[{"en":"Many people believe that money can''t buy happiness.","vi":"Nhiều người tin rằng tiền không mua được hạnh phúc."},{"en":"Her face was full of happiness when she saw her family.","vi":"Gương mặt cô ấy tràn đầy hạnh phúc khi thấy gia đình mình."},{"en":"We wish you both a lifetime of happiness together.","vi":"Chúng tôi chúc hai bạn trọn đời hạnh phúc bên nhau."}]','[{"phrase":"buy happiness"},{"phrase":"true happiness"},{"phrase":"bring happiness"}]','không đếm được','/ˈhæpinəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hap/happi/happiness__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2688,'ngsl-6-07',24,'genuine','thật, chính hãng; chân thành','adjective','[{"en":"Is this bag made of genuine leather?","vi":"Chiếc túi này làm bằng da thật phải không?"},{"en":"She showed genuine interest in my ideas.","vi":"Cô ấy thể hiện sự quan tâm thật lòng đến ý tưởng của tôi."},{"en":"He seems like a genuine person who really cares about others.","vi":"Anh ấy có vẻ là một người chân thành, thật sự quan tâm đến người khác."}]','[{"phrase":"genuine leather"},{"phrase":"genuine interest"},{"phrase":"genuine concern"}]',NULL,'/ˈdʒenjuɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/genui/genuine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2689,'ngsl-6-07',25,'vessel','tàu, thuyền; mạch máu','noun','[{"en":"The fishing vessel returned to port after a week at sea.","vi":"Tàu cá đã quay về cảng sau một tuần lênh đênh trên biển."},{"en":"A large cargo vessel was waiting outside the harbor.","vi":"Một tàu chở hàng lớn đang chờ bên ngoài bến cảng."},{"en":"Exercise helps keep your heart and blood vessels healthy.","vi":"Tập thể dục giúp tim và mạch máu của bạn khỏe mạnh."}]','[{"phrase":"fishing vessel"},{"phrase":"cargo vessel"},{"phrase":"blood vessel"}]',NULL,'/ˈvesl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ves/vesse/vessel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2690,'ngsl-6-07',26,'verb','động từ','noun','[{"en":"In this sentence, \"run\" is used as a verb.","vi":"Trong câu này, \"run\" được dùng như một động từ."},{"en":"Irregular verbs like \"go\" and \"take\" are hard to remember.","vi":"Các động từ bất quy tắc như \"go\" và \"take\" rất khó nhớ."},{"en":"Remember to put the verb in the past tense.","vi":"Nhớ chia động từ ở thì quá khứ nhé."}]','[{"phrase":"irregular verb"},{"phrase":"main verb"},{"phrase":"phrasal verb"}]',NULL,'/vɜːrb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/verb_/verb__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2691,'ngsl-6-07',27,'reckon','cho rằng, nghĩ; ước tính','verb','[{"en":"I reckon it''s going to rain later this afternoon.","vi":"Tôi nghĩ chiều nay trời sẽ mưa."},{"en":"Do you reckon she''ll accept the job offer?","vi":"Bạn có nghĩ là cô ấy sẽ nhận lời mời làm việc không?"},{"en":"The trip is reckoned to take about three hours by car.","vi":"Chuyến đi được ước tính mất khoảng ba tiếng bằng ô tô."}]','[{"phrase":"I reckon"},{"phrase":"I reckon so"}]','thân mật, hay dùng trong văn nói','/ˈrekən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recko/reckon__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2692,'ngsl-6-07',28,'silly','ngớ ngẩn, ngốc nghếch','adjective','[{"en":"Sorry, I know it''s a silly question, but where''s the bathroom?","vi":"Xin lỗi, tôi biết đây là câu hỏi ngớ ngẩn, nhưng nhà vệ sinh ở đâu vậy?"},{"en":"Don''t be silly, you''re always welcome at our house.","vi":"Đừng ngốc thế, bạn lúc nào cũng được chào đón ở nhà chúng tôi."},{"en":"The kids were making silly faces at the camera.","vi":"Bọn trẻ đang làm mặt xấu trước ống kính."}]','[{"phrase":"silly question"},{"phrase":"don''t be silly"},{"phrase":"silly mistake"},{"phrase":"feel silly"}]',NULL,'/ˈsɪli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silly/silly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2693,'ngsl-6-07',29,'transportation','giao thông vận tải; phương tiện đi lại','noun','[{"en":"Public transportation in this city is cheap and reliable.","vi":"Giao thông công cộng ở thành phố này rẻ và đáng tin cậy."},{"en":"The price of the tour includes hotels and transportation.","vi":"Giá tour đã bao gồm khách sạn và phương tiện đi lại."},{"en":"Bicycles are the main form of transportation for many students here.","vi":"Xe đạp là phương tiện đi lại chính của nhiều sinh viên ở đây."}]','[{"phrase":"public transportation"},{"phrase":"means of transportation"},{"phrase":"form of transportation"}]','Mỹ: transportation · Anh: transport; không đếm được','/ˌtrænspərˈteɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transportation__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2694,'ngsl-6-08',1,'harbor','cảng; bến cảng','noun','[{"en":"The fishing boats returned to the harbor before the storm.","vi":"Những chiếc thuyền đánh cá đã quay về cảng trước cơn bão."},{"en":"We walked along the harbor and watched the ships come in.","vi":"Chúng tôi đi dạo dọc bến cảng và ngắm những con tàu cập bến."},{"en":"Our hotel room had a beautiful view of the harbor.","vi":"Phòng khách sạn của chúng tôi có tầm nhìn tuyệt đẹp ra bến cảng."}]','[{"phrase":"in the harbor"},{"phrase":"natural harbor"},{"phrase":"harbor entrance"}]','Anh: harbour · Mỹ: harbor','/ˈhɑrbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2695,'ngsl-6-08',2,'comedy','hài kịch; phim hài','noun','[{"en":"My brother loves watching comedy shows after a long day.","vi":"Anh trai tôi rất thích xem các chương trình hài sau một ngày dài."},{"en":"It''s a romantic comedy, so it has a happy ending.","vi":"Đó là một phim hài lãng mạn nên có kết thúc có hậu."},{"en":"She started her career doing stand-up comedy in small clubs.","vi":"Cô ấy bắt đầu sự nghiệp bằng việc diễn hài độc thoại ở các câu lạc bộ nhỏ."}]','[{"phrase":"romantic comedy"},{"phrase":"stand-up comedy"},{"phrase":"comedy show"}]',NULL,'/ˈkɑːmədi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comed/comedy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2696,'ngsl-6-08',3,'chase','đuổi theo; theo đuổi','verb','[{"en":"The children laughed as they chased after the ball.","vi":"Bọn trẻ cười đùa khi chạy đuổi theo quả bóng."},{"en":"Two police officers chased the thief down the street.","vi":"Hai cảnh sát đuổi theo tên trộm dọc con phố."},{"en":"Don''t spend your whole life chasing money and success.","vi":"Đừng dành cả đời để theo đuổi tiền bạc và thành công."}]','[{"phrase":"chase after"},{"phrase":"chase a dream"},{"phrase":"chase away"}]',NULL,'/tʃeɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chase/chase__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2697,'ngsl-6-08',4,'storage','sự lưu trữ; chỗ chứa; bộ nhớ','noun','[{"en":"We need more storage space for all these boxes.","vi":"Chúng ta cần thêm chỗ chứa đồ cho tất cả những cái hộp này."},{"en":"My phone is almost out of storage, so I deleted some photos.","vi":"Điện thoại của tôi gần hết bộ nhớ nên tôi đã xóa bớt vài bức ảnh."},{"en":"They put their old furniture in storage while they moved.","vi":"Họ gửi đồ nội thất cũ vào kho trong lúc chuyển nhà."}]','[{"phrase":"storage space"},{"phrase":"in storage"},{"phrase":"data storage"}]','không đếm được','/ˈstɔːrɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stora/storage__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2698,'ngsl-6-08',5,'universe','vũ trụ; thế giới','noun','[{"en":"Scientists believe the universe is about fourteen billion years old.","vi":"Các nhà khoa học tin rằng vũ trụ đã khoảng mười bốn tỷ năm tuổi."},{"en":"Do you think we are alone in the universe?","vi":"Bạn có nghĩ chúng ta đơn độc trong vũ trụ không?"},{"en":"The film takes place in a strange universe full of magic.","vi":"Bộ phim diễn ra trong một thế giới kỳ lạ đầy phép thuật."}]','[{"phrase":"in the universe"},{"phrase":"the entire universe"}]',NULL,'/ˈjuːnɪvɜːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unive/universe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2699,'ngsl-6-08',6,'horrible','kinh khủng; tồi tệ','adjective','[{"en":"The food at that restaurant was absolutely horrible.","vi":"Đồ ăn ở nhà hàng đó thật sự kinh khủng."},{"en":"I had a horrible dream last night and couldn''t fall asleep again.","vi":"Đêm qua tôi gặp một giấc mơ kinh khủng và không ngủ lại được."},{"en":"It was horrible of him to laugh at her mistake.","vi":"Anh ta thật tồi tệ khi cười nhạo lỗi sai của cô ấy."}]','[{"phrase":"absolutely horrible"},{"phrase":"horrible feeling"},{"phrase":"horrible weather"}]',NULL,'/ˈhɔːrəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hor/horri/horrible__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2700,'ngsl-6-08',7,'sheep','con cừu','noun','[{"en":"The farmer keeps about two hundred sheep on his land.","vi":"Người nông dân nuôi khoảng hai trăm con cừu trên đất của mình."},{"en":"A few sheep were eating grass on the side of the hill.","vi":"Vài con cừu đang gặm cỏ trên sườn đồi."},{"en":"These sweaters are made from the wool of local sheep.","vi":"Những chiếc áo len này được làm từ lông của cừu địa phương."}]','[{"phrase":"a flock of sheep"},{"phrase":"sheep farm"},{"phrase":"keep sheep"}]','số nhiều vẫn là sheep','/ʃiːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/sheep/sheep__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2701,'ngsl-6-08',8,'lover','người yêu; người mê thích','noun','[{"en":"The two lovers walked hand in hand along the beach.","vi":"Đôi tình nhân nắm tay nhau đi dạo dọc bãi biển."},{"en":"As a coffee lover, I try every new café in town.","vi":"Là người mê cà phê, tôi thử mọi quán cà phê mới trong thành phố."},{"en":"This park is popular with dog lovers on weekends.","vi":"Công viên này được những người yêu chó ưa chuộng vào cuối tuần."}]','[{"phrase":"music lover"},{"phrase":"dog lover"},{"phrase":"nature lover"}]',NULL,'/ˈlʌvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lov/lover/lover__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2702,'ngsl-6-08',9,'rat','chuột cống; con chuột','noun','[{"en":"We saw a huge rat running near the trash cans.","vi":"Chúng tôi thấy một con chuột to chạy gần mấy thùng rác."},{"en":"Rats can carry diseases, so keep your kitchen clean.","vi":"Chuột có thể mang mầm bệnh, vì vậy hãy giữ bếp sạch sẽ."},{"en":"The old house was full of rats and spiders.","vi":"Ngôi nhà cũ đầy chuột và nhện."}]','[{"phrase":"rat poison"},{"phrase":"lab rat"}]','rat (chuột to) ≠ mouse (chuột nhắt)','/ræt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/rat__/rat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2703,'ngsl-6-08',10,'portrait','bức chân dung; sự miêu tả','noun','[{"en":"A portrait of her grandmother hangs above the fireplace.","vi":"Một bức chân dung của bà cô ấy được treo phía trên lò sưởi."},{"en":"The artist spent three months painting the family portrait.","vi":"Họa sĩ đã mất ba tháng để vẽ bức chân dung gia đình."},{"en":"The book gives a clear portrait of life in a small village.","vi":"Cuốn sách đưa ra một bức tranh rõ nét về cuộc sống ở một ngôi làng nhỏ."}]','[{"phrase":"paint a portrait"},{"phrase":"family portrait"},{"phrase":"portrait of"}]',NULL,'/ˈpɔːrtrət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/portr/portrait__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2704,'ngsl-6-08',11,'innocent','vô tội; ngây thơ','adjective','[{"en":"Her lawyer was sure that she was completely innocent.","vi":"Luật sư của cô ấy chắc chắn rằng cô ấy hoàn toàn vô tội."},{"en":"He always believed his son was innocent of the crime.","vi":"Ông ấy luôn tin rằng con trai mình không phạm tội đó."},{"en":"The child looked up at me with big, innocent eyes.","vi":"Đứa trẻ ngước nhìn tôi bằng đôi mắt to tròn ngây thơ."}]','[{"phrase":"innocent of"},{"phrase":"completely innocent"},{"phrase":"innocent eyes"}]',NULL,'/ˈɪnəsnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/innoc/innocent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2705,'ngsl-6-08',12,'substitute','người thay thế; vật thay thế','noun','[{"en":"You can use honey as a substitute for sugar.","vi":"Bạn có thể dùng mật ong để thay cho đường."},{"en":"Our teacher was sick, so a substitute taught the class.","vi":"Cô giáo chúng tôi bị ốm nên có một giáo viên khác dạy thay."},{"en":"The coach brought on a substitute in the second half.","vi":"Huấn luyện viên đã tung một cầu thủ dự bị vào sân trong hiệp hai."}]','[{"phrase":"substitute for"},{"phrase":"substitute teacher"},{"phrase":"no substitute for"}]','cũng là động từ: substitute A for B (dùng A thay B)','/ˈsʌbstɪtuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substitute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2706,'ngsl-6-08',13,'supplement','thực phẩm bổ sung; phần bổ sung','noun','[{"en":"My doctor told me to take a vitamin D supplement.","vi":"Bác sĩ bảo tôi uống thêm viên bổ sung vitamin D."},{"en":"Online lessons are a useful supplement to classes at school.","vi":"Các bài học trực tuyến là phần bổ sung hữu ích cho các lớp học ở trường."},{"en":"Many athletes take protein supplements after training.","vi":"Nhiều vận động viên dùng thực phẩm bổ sung protein sau khi tập luyện."}]','[{"phrase":"dietary supplement"},{"phrase":"vitamin supplement"},{"phrase":"supplement to"}]',NULL,'/ˈsʌplɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supplement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2707,'ngsl-6-08',14,'adjustment','sự điều chỉnh; sự thích nghi','noun','[{"en":"We made a few small adjustments to the plan.","vi":"Chúng tôi đã thực hiện vài điều chỉnh nhỏ cho kế hoạch."},{"en":"Moving to a new country requires a big adjustment.","vi":"Chuyển đến một đất nước mới đòi hỏi phải thích nghi rất nhiều."},{"en":"The mechanic made an adjustment to the brakes on my bike.","vi":"Thợ sửa xe đã điều chỉnh phanh xe đạp của tôi."}]','[{"phrase":"make an adjustment"},{"phrase":"minor adjustment"},{"phrase":"adjustment to"}]',NULL,'/əˈdʒʌstmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjus/adjustment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2708,'ngsl-6-08',15,'reasonably','khá; hợp lý','adverb','[{"en":"The hotel was clean and reasonably priced.","vi":"Khách sạn sạch sẽ và giá cả hợp lý."},{"en":"I speak French reasonably well, but my writing is poor.","vi":"Tôi nói tiếng Pháp khá tốt, nhưng viết thì kém."},{"en":"Please try to act reasonably, even when you feel angry.","vi":"Hãy cố gắng cư xử hợp lý, ngay cả khi bạn đang tức giận."}]','[{"phrase":"reasonably priced"},{"phrase":"reasonably well"},{"phrase":"reasonably good"}]',NULL,'/ˈriːznəbli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reaso/reasonably__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2709,'ngsl-6-08',16,'filter','bộ lọc; cái lọc','noun','[{"en":"Remember to clean the air filter every few months.","vi":"Nhớ vệ sinh bộ lọc không khí vài tháng một lần."},{"en":"She added a filter to the photo before posting it.","vi":"Cô ấy thêm bộ lọc vào bức ảnh trước khi đăng."},{"en":"This water filter removes dirt and makes tap water safe.","vi":"Bộ lọc nước này loại bỏ cặn bẩn và giúp nước máy an toàn."}]','[{"phrase":"water filter"},{"phrase":"air filter"},{"phrase":"coffee filter"}]','cũng là động từ: filter (lọc)','/ˈfɪltər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/filte/filter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2710,'ngsl-6-08',17,'flexible','linh hoạt; dẻo dai','adjective','[{"en":"My job has flexible hours, so I can pick up my kids.","vi":"Công việc của tôi có giờ giấc linh hoạt nên tôi có thể đón con."},{"en":"We''re flexible about the date, so just tell us what suits you.","vi":"Chúng tôi linh hoạt về ngày, nên bạn cứ cho biết ngày nào hợp với bạn."},{"en":"Yoga helps keep your body strong and flexible.","vi":"Yoga giúp cơ thể bạn khỏe mạnh và dẻo dai."}]','[{"phrase":"flexible hours"},{"phrase":"flexible about"},{"phrase":"highly flexible"}]',NULL,'/ˈfleksəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fle/flexi/flexible__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2711,'ngsl-6-08',18,'abstract','trừu tượng','adjective','[{"en":"Love and freedom are abstract ideas that are hard to define.","vi":"Tình yêu và tự do là những khái niệm trừu tượng khó định nghĩa."},{"en":"I don''t really understand abstract art, but I like the colors.","vi":"Tôi không thực sự hiểu nghệ thuật trừu tượng, nhưng tôi thích màu sắc."},{"en":"His explanation was too abstract for the young students.","vi":"Lời giải thích của anh ấy quá trừu tượng đối với các học sinh nhỏ tuổi."}]','[{"phrase":"abstract art"},{"phrase":"abstract idea"},{"phrase":"abstract concept"}]',NULL,'/ˈæbstrækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/abstr/abstract__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2712,'ngsl-6-08',19,'tent','cái lều','noun','[{"en":"Let''s put up the tent before it gets dark.","vi":"Chúng ta dựng lều trước khi trời tối đi."},{"en":"It rained all night, but we stayed dry inside the tent.","vi":"Trời mưa suốt đêm nhưng chúng tôi vẫn khô ráo trong lều."},{"en":"The wedding dinner was held in a large white tent.","vi":"Tiệc cưới được tổ chức trong một chiếc lều trắng lớn."}]','[{"phrase":"put up a tent"},{"phrase":"pitch a tent"},{"phrase":"sleep in a tent"}]',NULL,'/tent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tent_/tent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2713,'ngsl-6-08',20,'precise','chính xác; rõ ràng','adjective','[{"en":"Can you tell me the precise time the train leaves?","vi":"Bạn có thể cho tôi biết chính xác giờ tàu chạy không?"},{"en":"The instructions for the machine were clear and very precise.","vi":"Hướng dẫn sử dụng máy rõ ràng và rất chính xác."},{"en":"To be precise, we have been waiting for forty minutes.","vi":"Nói cho chính xác thì chúng tôi đã chờ bốn mươi phút rồi."}]','[{"phrase":"to be precise"},{"phrase":"precise time"},{"phrase":"precise details"}]',NULL,'/prɪˈsaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preci/precise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2714,'ngsl-6-08',21,'distant','xa; xa cách','adjective','[{"en":"In the distant future, people might live on other planets.","vi":"Trong tương lai xa, con người có thể sống trên các hành tinh khác."},{"en":"She dreams of traveling to distant countries one day.","vi":"Cô ấy mơ một ngày được đi du lịch đến những đất nước xa xôi."},{"en":"After the argument, she seemed cold and distant.","vi":"Sau cuộc cãi vã, cô ấy có vẻ lạnh lùng và xa cách."}]','[{"phrase":"distant future"},{"phrase":"distant relative"},{"phrase":"distant memory"}]',NULL,'/ˈdɪstənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dista/distant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2715,'ngsl-6-08',22,'stranger','người lạ','noun','[{"en":"Parents tell their children not to talk to strangers.","vi":"Cha mẹ dặn con cái không được nói chuyện với người lạ."},{"en":"A kind stranger helped me carry my bags up the stairs.","vi":"Một người lạ tốt bụng đã giúp tôi xách túi lên cầu thang."},{"en":"When I first moved here, everyone was a complete stranger to me.","vi":"Khi tôi mới chuyển đến đây, ai cũng hoàn toàn xa lạ với tôi."}]','[{"phrase":"complete stranger"},{"phrase":"total stranger"},{"phrase":"talk to strangers"}]',NULL,'/ˈstreɪndʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stran/stranger__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2716,'ngsl-6-08',23,'shade','bóng râm; sắc độ','noun','[{"en":"Let''s sit in the shade of that big tree.","vi":"Chúng ta ngồi dưới bóng râm của cái cây to kia đi."},{"en":"It was so hot that the dog lay in the shade all day.","vi":"Trời nóng đến nỗi con chó nằm trong bóng râm cả ngày."},{"en":"I''d like this shirt in a lighter shade of blue.","vi":"Tôi muốn chiếc áo này với màu xanh nhạt hơn."}]','[{"phrase":"in the shade"},{"phrase":"lighter shade"},{"phrase":"provide shade"}]',NULL,'/ʃeɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shade/shade__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2717,'ngsl-6-08',24,'grain','ngũ cốc; hạt','noun','[{"en":"Farmers here grow grains such as wheat and rice.","vi":"Nông dân ở đây trồng các loại ngũ cốc như lúa mì và lúa gạo."},{"en":"There was a grain of sand stuck in my shoe.","vi":"Có một hạt cát bị kẹt trong giày tôi."},{"en":"Brown rice and other whole grains are good for your health.","vi":"Gạo lứt và các loại ngũ cốc nguyên hạt khác tốt cho sức khỏe."}]','[{"phrase":"grain of sand"},{"phrase":"grain of rice"},{"phrase":"whole grain"}]',NULL,'/ɡreɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grain/grain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2718,'ngsl-6-08',25,'situate','đặt vào vị trí; nằm ở','verb','[{"en":"The hotel is situated near the beach and the old town.","vi":"Khách sạn nằm gần bãi biển và khu phố cổ."},{"en":"Our school is situated on a quiet street near the park.","vi":"Trường chúng tôi nằm trên một con phố yên tĩnh gần công viên."},{"en":"The architect situated the kitchen on the sunny side of the house.","vi":"Kiến trúc sư đã đặt nhà bếp ở phía có nắng của ngôi nhà."}]','[{"phrase":"situated in"},{"phrase":"situated near"},{"phrase":"conveniently situated"}]','thường dùng bị động: be situated in/on/near','/ˈsɪtʃueɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/situa/situate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2719,'ngsl-6-08',26,'summarize','tóm tắt','verb','[{"en":"Can you summarize the main points of the meeting?","vi":"Bạn có thể tóm tắt những ý chính của cuộc họp không?"},{"en":"In the last paragraph, summarize what you have learned.","vi":"Ở đoạn cuối, hãy tóm tắt những gì bạn đã học được."},{"en":"She summarized the long report in just a few sentences.","vi":"Cô ấy đã tóm tắt bản báo cáo dài chỉ trong vài câu."}]','[{"phrase":"summarize the main points"},{"phrase":"briefly summarize"},{"phrase":"summarize the findings"}]','Anh: summarise · Mỹ: summarize','/ˈsʌməraɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summa/summarize__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2720,'ngsl-6-08',27,'leap','nhảy; tăng vọt','verb','[{"en":"The children leaped into the pool on the first hot day.","vi":"Bọn trẻ nhảy ùm xuống hồ bơi vào ngày nóng đầu tiên."},{"en":"He leaped out of bed when he heard the alarm.","vi":"Anh ấy bật dậy khỏi giường khi nghe tiếng chuông báo thức."},{"en":"Prices leaped by twenty percent in just one year.","vi":"Giá cả tăng vọt hai mươi phần trăm chỉ trong một năm."}]','[{"phrase":"leap into"},{"phrase":"leap forward"},{"phrase":"leap at the chance"}]','leap – leaped/leapt – leaped/leapt','/liːp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leap_/leap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2721,'ngsl-6-08',28,'snap','gãy tách; cáu gắt; chụp nhanh','verb','[{"en":"The dry branch snapped when he stepped on it.","vi":"Cành cây khô gãy tách khi anh ấy giẫm lên."},{"en":"I''m sorry I snapped at you this morning.","vi":"Xin lỗi vì sáng nay tôi đã cáu gắt với bạn."},{"en":"She snapped a quick photo of the sunset from the train.","vi":"Cô ấy chụp vội một bức ảnh hoàng hôn từ trên tàu."}]','[{"phrase":"snap at"},{"phrase":"snap in half"},{"phrase":"snap a photo"}]',NULL,'/snæp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sna/snap_/snap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2722,'ngsl-6-08',29,'probability','xác suất; khả năng','noun','[{"en":"The probability of rain tomorrow is about seventy percent.","vi":"Xác suất có mưa vào ngày mai là khoảng bảy mươi phần trăm."},{"en":"In all probability, the meeting will be canceled.","vi":"Rất có khả năng cuộc họp sẽ bị hủy."},{"en":"Today we learned how to calculate probability in math class.","vi":"Hôm nay chúng tôi học cách tính xác suất trong giờ toán."}]','[{"phrase":"in all probability"},{"phrase":"high probability"},{"phrase":"probability of"}]',NULL,'/ˌprɑːbəˈbɪləti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proba/probability__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2723,'ngsl-6-09',1,'leather','da thuộc; đồ da','noun','[{"en":"My father bought me a brown leather jacket for my birthday.","vi":"Bố tôi đã mua cho tôi một chiếc áo khoác da màu nâu nhân dịp sinh nhật."},{"en":"These shoes are made of real leather, so they last for years.","vi":"Đôi giày này làm bằng da thật nên dùng được nhiều năm."},{"en":"She keeps her passport in a small leather bag.","vi":"Cô ấy cất hộ chiếu trong một chiếc túi da nhỏ."}]','[{"phrase":"leather jacket"},{"phrase":"real leather"},{"phrase":"leather bag"},{"phrase":"leather shoes"}]','không đếm được','/ˈleðər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leath/leather__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2724,'ngsl-6-09',2,'uncertainty','sự không chắc chắn; sự bấp bênh','noun','[{"en":"There is a lot of uncertainty about the future of the company.","vi":"Tương lai của công ty còn rất nhiều điều không chắc chắn."},{"en":"After losing his job, he lived with months of uncertainty.","vi":"Sau khi mất việc, anh ấy sống trong nhiều tháng bấp bênh."},{"en":"She could hear the uncertainty in her son''s voice.","vi":"Cô ấy nghe ra sự không chắc chắn trong giọng nói của con trai."}]','[{"phrase":"uncertainty about"},{"phrase":"economic uncertainty"},{"phrase":"period of uncertainty"}]',NULL,'/ʌnˈsɜːrtnti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unc/uncer/uncertainty__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2725,'ngsl-6-09',3,'swear','thề; chửi thề','verb','[{"en":"I swear I didn''t tell anyone your secret.","vi":"Tôi thề là tôi không kể bí mật của bạn cho ai cả."},{"en":"He swore that he would never lie to her again.","vi":"Anh ấy thề sẽ không bao giờ nói dối cô ấy nữa."},{"en":"Please don''t swear in front of the children.","vi":"Làm ơn đừng chửi thề trước mặt bọn trẻ."}]','[{"phrase":"I swear"},{"phrase":"swear at someone"},{"phrase":"swear an oath"}]','swear – swore – sworn','/swer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swe/swear/swear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2726,'ngsl-6-09',4,'refugee','người tị nạn','noun','[{"en":"The refugees needed food, water and a safe place to sleep.","vi":"Những người tị nạn cần thức ăn, nước uống và một nơi an toàn để ngủ."},{"en":"Her grandparents came to this country as refugees many years ago.","vi":"Ông bà cô ấy đến đất nước này với tư cách người tị nạn từ nhiều năm trước."},{"en":"Volunteers at the refugee camp teach English to young children.","vi":"Các tình nguyện viên ở trại tị nạn dạy tiếng Anh cho trẻ nhỏ."}]','[{"phrase":"refugee camp"},{"phrase":"refugee children"},{"phrase":"become a refugee"}]',NULL,'/ˌrefjuˈdʒiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refug/refugee__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2727,'ngsl-6-09',5,'shore','bờ (biển, hồ, sông)','noun','[{"en":"We walked along the shore and collected shells.","vi":"Chúng tôi đi dạo dọc bờ biển và nhặt vỏ sò."},{"en":"The boat slowly came back to shore before the storm.","vi":"Con thuyền từ từ quay vào bờ trước khi cơn bão đến."},{"en":"Their small cabin is on the shore of a quiet lake.","vi":"Căn nhà gỗ nhỏ của họ nằm bên bờ một hồ nước yên tĩnh."}]','[{"phrase":"along the shore"},{"phrase":"on the shore"},{"phrase":"swim to shore"}]',NULL,'/ʃɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shore/shore__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2728,'ngsl-6-09',6,'monthly','hằng tháng','adjective','[{"en":"Our monthly rent goes up by fifty dollars next year.","vi":"Tiền thuê nhà hằng tháng của chúng tôi sẽ tăng thêm năm mươi đô vào năm sau."},{"en":"The team has a monthly meeting on the first Friday.","vi":"Nhóm có một cuộc họp hằng tháng vào thứ Sáu đầu tiên của tháng."},{"en":"How much is your monthly phone bill?","vi":"Hóa đơn điện thoại hằng tháng của bạn là bao nhiêu?"}]','[{"phrase":"monthly rent"},{"phrase":"monthly meeting"},{"phrase":"monthly payment"},{"phrase":"monthly salary"}]',NULL,'/ˈmʌnθli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/month/monthly__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2729,'ngsl-6-09',7,'comprise','gồm có; cấu thành, chiếm','verb','[{"en":"The apartment comprises two bedrooms, a kitchen and a small bathroom.","vi":"Căn hộ gồm hai phòng ngủ, một nhà bếp và một phòng tắm nhỏ."},{"en":"Children comprise about a third of the town''s population.","vi":"Trẻ em chiếm khoảng một phần ba dân số của thị trấn."},{"en":"The group mainly comprises students from nearby universities.","vi":"Nhóm này chủ yếu gồm sinh viên từ các trường đại học gần đó."}]','[{"phrase":"mainly comprise"},{"phrase":"be comprised of"}]','comprise + danh từ (không cần "of")','/kəmˈpraɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2730,'ngsl-6-09',8,'stir','khuấy; cựa quậy','verb','[{"en":"Stir the sauce constantly so it doesn''t burn.","vi":"Hãy khuấy nước sốt liên tục để nó không bị khét."},{"en":"She added some sugar and stirred her coffee.","vi":"Cô ấy cho thêm chút đường rồi khuấy cà phê."},{"en":"The baby stirred in his sleep but didn''t wake up.","vi":"Em bé cựa mình trong giấc ngủ nhưng không thức dậy."}]','[{"phrase":"stir constantly"},{"phrase":"stir well"},{"phrase":"stir in"}]','stir – stirred – stirred','/stɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/stir_/stir__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2731,'ngsl-6-09',9,'excitement','sự phấn khích; sự háo hức','noun','[{"en":"The children could hardly sleep because of their excitement about the trip.","vi":"Bọn trẻ gần như không ngủ được vì háo hức về chuyến đi."},{"en":"There was a lot of excitement in the stadium before the final.","vi":"Sân vận động tràn ngập sự phấn khích trước trận chung kết."},{"en":"She jumped up and down with excitement when she heard the news.","vi":"Cô ấy nhảy cẫng lên vì phấn khích khi nghe tin."}]','[{"phrase":"with excitement"},{"phrase":"excitement about"},{"phrase":"great excitement"},{"phrase":"full of excitement"}]',NULL,'/ɪkˈsaɪtmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excit/excitement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2732,'ngsl-6-09',10,'sigh','thở dài','verb','[{"en":"He sighed and closed his laptop after a long day.","vi":"Anh ấy thở dài rồi gập máy tính lại sau một ngày dài."},{"en":"She sighed with relief when her son finally called.","vi":"Cô ấy thở phào nhẹ nhõm khi con trai cuối cùng cũng gọi điện."},{"en":"Why do you keep sighing when I ask about school?","vi":"Sao bạn cứ thở dài mỗi khi tôi hỏi về chuyện trường lớp?"}]','[{"phrase":"sigh with relief"},{"phrase":"sigh deeply"},{"phrase":"sigh heavily"}]',NULL,'/saɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/sigh_/sigh__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2733,'ngsl-6-09',11,'pregnancy','sự mang thai; thai kỳ','noun','[{"en":"She felt tired during the first months of her pregnancy.","vi":"Cô ấy thấy mệt trong những tháng đầu mang thai."},{"en":"Doctors say women should avoid alcohol during pregnancy.","vi":"Bác sĩ cho biết phụ nữ nên tránh rượu bia trong thời gian mang thai."},{"en":"You can buy a pregnancy test at any pharmacy.","vi":"Bạn có thể mua que thử thai ở bất kỳ hiệu thuốc nào."}]','[{"phrase":"during pregnancy"},{"phrase":"pregnancy test"},{"phrase":"early pregnancy"},{"phrase":"healthy pregnancy"}]',NULL,'/ˈpreɡnənsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/pregn/pregnancy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2734,'ngsl-6-09',12,'experimental','thử nghiệm; thể nghiệm','adjective','[{"en":"The new drug is still at an experimental stage.","vi":"Loại thuốc mới vẫn đang ở giai đoạn thử nghiệm."},{"en":"Their band plays experimental music that mixes jazz and rock.","vi":"Ban nhạc của họ chơi nhạc thể nghiệm pha trộn giữa jazz và rock."},{"en":"The school is running an experimental program for young readers.","vi":"Nhà trường đang triển khai một chương trình thử nghiệm dành cho các em nhỏ tập đọc."}]','[{"phrase":"experimental stage"},{"phrase":"experimental music"},{"phrase":"experimental method"}]',NULL,'/ɪkˌsperɪˈmentl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/experimental__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2735,'ngsl-6-09',13,'institutional','thuộc tổ chức, cơ quan; thuộc thể chế','adjective','[{"en":"Most of the company''s shares are held by institutional investors.","vi":"Phần lớn cổ phần của công ty do các nhà đầu tư tổ chức nắm giữ."},{"en":"The problem is institutional, so one person cannot solve it alone.","vi":"Vấn đề nằm ở cơ chế của cả tổ chức, nên một người không thể tự giải quyết được."},{"en":"Our research project could not continue without institutional support.","vi":"Dự án nghiên cứu của chúng tôi không thể tiếp tục nếu thiếu sự hỗ trợ từ cơ quan."}]','[{"phrase":"institutional investors"},{"phrase":"institutional support"},{"phrase":"institutional reform"}]',NULL,'/ˌɪnstɪˈtuːʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insti/institutional__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2736,'ngsl-6-09',14,'slice','lát; miếng','noun','[{"en":"Would you like another slice of cake?","vi":"Bạn có muốn ăn thêm một miếng bánh nữa không?"},{"en":"I usually have two slices of toast for breakfast.","vi":"Bữa sáng tôi thường ăn hai lát bánh mì nướng."},{"en":"Put a thin slice of lemon in each glass.","vi":"Cho một lát chanh mỏng vào mỗi cốc."}]','[{"phrase":"slice of cake"},{"phrase":"slice of bread"},{"phrase":"thin slice"},{"phrase":"slice of pizza"}]',NULL,'/slaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/slice/slice__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2737,'ngsl-6-09',15,'wander','đi lang thang; dạo quanh; lơ đãng','verb','[{"en":"We spent the afternoon wandering around the old town.","vi":"Chúng tôi dành cả buổi chiều dạo quanh khu phố cổ."},{"en":"Don''t let the kids wander off in the crowded market.","vi":"Đừng để bọn trẻ đi lung tung trong khu chợ đông đúc."},{"en":"My mind started to wander during the long meeting.","vi":"Đầu óc tôi bắt đầu lơ đãng trong cuộc họp dài."}]','[{"phrase":"wander around"},{"phrase":"wander off"},{"phrase":"wander the streets"}]','wander (đi lang thang) ≠ wonder (tự hỏi)','/ˈwɑːndər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wan/wande/wander__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2738,'ngsl-6-09',16,'empire','đế chế; đế quốc','noun','[{"en":"The Roman Empire lasted for hundreds of years.","vi":"Đế chế La Mã tồn tại suốt hàng trăm năm."},{"en":"In history class, we learned about the rise and fall of ancient empires.","vi":"Trong giờ lịch sử, chúng tôi học về sự trỗi dậy và sụp đổ của các đế chế cổ đại."},{"en":"She built a business empire from one small bakery.","vi":"Cô ấy đã gây dựng cả một đế chế kinh doanh từ một tiệm bánh nhỏ."}]','[{"phrase":"business empire"},{"phrase":"build an empire"},{"phrase":"ancient empire"}]',NULL,'/ˈempaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empir/empire__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2739,'ngsl-6-09',17,'subsequently','sau đó; về sau','adverb','[{"en":"He started as a waiter and subsequently became the manager of the restaurant.","vi":"Anh ấy khởi đầu là bồi bàn và sau đó trở thành quản lý của nhà hàng."},{"en":"The flight was delayed and subsequently canceled because of fog.","vi":"Chuyến bay bị hoãn rồi sau đó bị hủy vì sương mù."},{"en":"She was injured in the first game and subsequently missed the whole season.","vi":"Cô ấy bị chấn thương ở trận đầu tiên và sau đó phải nghỉ cả mùa giải."}]','[{"phrase":"subsequently became"},{"phrase":"subsequently published"},{"phrase":"subsequently found"}]',NULL,'/ˈsʌbsɪkwəntli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subse/subsequently__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2740,'ngsl-6-09',18,'gentle','nhẹ nhàng; hiền lành','adjective','[{"en":"Be gentle with the puppy; he''s only a few weeks old.","vi":"Hãy nhẹ tay với chú chó con, nó mới được vài tuần tuổi thôi."},{"en":"My grandmother was a kind and gentle woman.","vi":"Bà tôi là một người phụ nữ tốt bụng và hiền lành."},{"en":"A gentle breeze came in through the open window.","vi":"Một làn gió nhẹ thổi vào qua ô cửa sổ đang mở."}]','[{"phrase":"gentle breeze"},{"phrase":"be gentle with"},{"phrase":"gentle voice"},{"phrase":"gentle exercise"}]',NULL,'/ˈdʒentl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gentl/gentle__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2741,'ngsl-6-09',19,'attendance','sự có mặt, sự tham dự; số người tham dự','noun','[{"en":"Good attendance is important if you want to pass this course.","vi":"Đi học đầy đủ rất quan trọng nếu bạn muốn qua môn này."},{"en":"The teacher takes attendance at the start of every class.","vi":"Giáo viên điểm danh vào đầu mỗi buổi học."},{"en":"Attendance at the festival was higher than last year.","vi":"Số người tham dự lễ hội năm nay cao hơn năm ngoái."}]','[{"phrase":"take attendance"},{"phrase":"attendance at"},{"phrase":"good attendance"},{"phrase":"high attendance"}]',NULL,'/əˈtendəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/atten/attendance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2742,'ngsl-6-09',20,'ownership','quyền sở hữu; việc sở hữu','noun','[{"en":"The restaurant has changed ownership three times in five years.","vi":"Nhà hàng này đã đổi chủ ba lần trong năm năm."},{"en":"Home ownership is becoming harder for young people.","vi":"Việc sở hữu nhà ngày càng khó khăn hơn đối với người trẻ."},{"en":"You need these papers to prove ownership of the car.","vi":"Bạn cần những giấy tờ này để chứng minh quyền sở hữu chiếc xe."}]','[{"phrase":"home ownership"},{"phrase":"change ownership"},{"phrase":"proof of ownership"},{"phrase":"private ownership"}]',NULL,'/ˈəʊnərʃɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/own/owner/ownership__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2743,'ngsl-6-09',21,'qualification','bằng cấp, chứng chỉ; trình độ chuyên môn','noun','[{"en":"She has the right qualifications for the teaching job.","vi":"Cô ấy có bằng cấp phù hợp với công việc giảng dạy."},{"en":"He left school at sixteen without any formal qualifications.","vi":"Anh ấy nghỉ học năm mười sáu tuổi mà không có bằng cấp chính thức nào."},{"en":"What qualifications do you need to become a nurse?","vi":"Bạn cần có bằng cấp gì để trở thành y tá?"}]','[{"phrase":"formal qualifications"},{"phrase":"professional qualifications"},{"phrase":"academic qualifications"}]',NULL,'/ˌkwɑːlɪfɪˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/qualification__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2744,'ngsl-6-09',22,'suspend','đình chỉ; tạm ngừng; treo','verb','[{"en":"The student was suspended for three days for fighting.","vi":"Học sinh đó bị đình chỉ học ba ngày vì đánh nhau."},{"en":"Train services were suspended because of the heavy snow.","vi":"Các chuyến tàu bị tạm ngừng vì tuyết rơi dày."},{"en":"A large lamp was suspended from the ceiling above the table.","vi":"Một chiếc đèn lớn được treo từ trần nhà xuống phía trên bàn."}]','[{"phrase":"temporarily suspend"},{"phrase":"be suspended from school"},{"phrase":"suspend service"}]',NULL,'/səˈspend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/suspe/suspend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2745,'ngsl-6-09',23,'functional','tiện dụng, thiết thực; hoạt động được','adjective','[{"en":"The kitchen is small but very functional.","vi":"Căn bếp nhỏ nhưng rất tiện dụng."},{"en":"After the storm, the hospital was still fully functional.","vi":"Sau cơn bão, bệnh viện vẫn hoạt động hoàn toàn bình thường."},{"en":"The building''s functional design makes it easy to move around.","vi":"Thiết kế tiện dụng của tòa nhà giúp việc đi lại bên trong rất dễ dàng."}]','[{"phrase":"fully functional"},{"phrase":"functional design"}]',NULL,'/ˈfʌŋkʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funct/functional__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2746,'ngsl-6-09',24,'voluntary','tự nguyện; tình nguyện','adjective','[{"en":"Taking part in the survey is completely voluntary.","vi":"Việc tham gia khảo sát hoàn toàn là tự nguyện."},{"en":"She does voluntary work at the local hospital on Sundays.","vi":"Cô ấy làm tình nguyện ở bệnh viện địa phương vào các ngày Chủ nhật."},{"en":"The company offered voluntary retirement to its older workers.","vi":"Công ty đưa ra chương trình nghỉ hưu tự nguyện cho những nhân viên lớn tuổi."}]','[{"phrase":"voluntary work"},{"phrase":"completely voluntary"},{"phrase":"voluntary organization"}]',NULL,'/ˈvɑːlənteri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volun/voluntary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2747,'ngsl-6-09',25,'pale','nhợt nhạt, xanh xao; nhạt (màu)','adjective','[{"en":"You look pale; are you feeling all right?","vi":"Trông bạn xanh xao quá, bạn có thấy ổn không?"},{"en":"Her face went pale when she saw the bill.","vi":"Mặt cô ấy tái đi khi nhìn thấy hóa đơn."},{"en":"They painted the bedroom a pale blue color.","vi":"Họ sơn phòng ngủ màu xanh nhạt."}]','[{"phrase":"look pale"},{"phrase":"turn pale"},{"phrase":"go pale"},{"phrase":"pale blue"}]',NULL,'/peɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pal/pale_/pale__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2748,'ngsl-6-09',26,'stain','vết bẩn; vết ố','noun','[{"en":"I can''t get this coffee stain out of my shirt.","vi":"Tôi không tẩy được vết cà phê này trên áo sơ mi."},{"en":"There was a dark stain on the carpet near the sofa.","vi":"Trên thảm gần ghế sofa có một vết bẩn sẫm màu."},{"en":"Wash the tablecloth quickly before the wine stain dries.","vi":"Hãy giặt khăn trải bàn ngay trước khi vết rượu vang khô lại."}]','[{"phrase":"coffee stain"},{"phrase":"dark stain"},{"phrase":"remove a stain"}]',NULL,'/steɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stain/stain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2749,'ngsl-6-09',27,'athlete','vận động viên','noun','[{"en":"Professional athletes train for several hours every day.","vi":"Các vận động viên chuyên nghiệp tập luyện nhiều giờ mỗi ngày."},{"en":"My brother was a talented athlete in high school.","vi":"Anh trai tôi từng là một vận động viên tài năng hồi cấp ba."},{"en":"Athletes from over fifty countries will compete in the games.","vi":"Vận động viên từ hơn năm mươi quốc gia sẽ tranh tài tại đại hội."}]','[{"phrase":"professional athlete"},{"phrase":"talented athlete"},{"phrase":"top athlete"}]',NULL,'/ˈæθliːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ath/athle/athlete__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2750,'ngsl-6-09',28,'organic','hữu cơ','adjective','[{"en":"We buy organic vegetables from a farm near our house.","vi":"Chúng tôi mua rau hữu cơ từ một trang trại gần nhà."},{"en":"Organic food is usually more expensive than regular food.","vi":"Thực phẩm hữu cơ thường đắt hơn thực phẩm thông thường."},{"en":"Fallen leaves are a great source of organic material for your garden.","vi":"Lá rụng là nguồn chất hữu cơ tuyệt vời cho khu vườn của bạn."}]','[{"phrase":"organic food"},{"phrase":"organic vegetables"},{"phrase":"organic farming"},{"phrase":"organic matter"}]',NULL,'/ɔːrˈɡænɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/org/organ/organic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2751,'ngsl-6-09',29,'tongue','lưỡi; tiếng, ngôn ngữ','noun','[{"en":"Be careful, the soup is hot enough to burn your tongue.","vi":"Cẩn thận nhé, súp nóng đến mức có thể làm bỏng lưỡi đấy."},{"en":"The little boy stuck his tongue out at his sister.","vi":"Cậu bé lè lưỡi trêu chị gái."},{"en":"Although she lives abroad, she still speaks her mother tongue at home.","vi":"Dù sống ở nước ngoài, cô ấy vẫn nói tiếng mẹ đẻ khi ở nhà."}]','[{"phrase":"mother tongue"},{"phrase":"stick your tongue out"},{"phrase":"bite your tongue"},{"phrase":"burn your tongue"}]',NULL,'/tʌŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ton/tongu/tongue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2752,'ngsl-6-10',1,'server','máy chủ; người phục vụ','noun','[{"en":"Our web server crashed last night, so nobody could open the site.","vi":"Máy chủ web của chúng tôi bị sập tối qua nên không ai vào được trang web."},{"en":"All our files are stored on a server in another city.","vi":"Tất cả tệp của chúng tôi được lưu trên một máy chủ ở thành phố khác."},{"en":"Our server brought us water before we even ordered.","vi":"Người phục vụ mang nước cho chúng tôi trước cả khi chúng tôi gọi món."}]','[{"phrase":"web server"},{"phrase":"email server"},{"phrase":"server crash"}]',NULL,'/ˈsɜːrvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serve/server__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2753,'ngsl-6-10',2,'structural','thuộc cấu trúc; thuộc kết cấu','adjective','[{"en":"The engineers found serious structural damage after the storm.","vi":"Các kỹ sư phát hiện hư hại nghiêm trọng về kết cấu sau cơn bão."},{"en":"We need to make a few structural changes to the plan.","vi":"Chúng ta cần thực hiện vài thay đổi về cấu trúc trong kế hoạch."},{"en":"Is that wall structural, or can we remove it?","vi":"Bức tường đó có phải tường chịu lực không, hay chúng ta có thể dỡ nó đi?"}]','[{"phrase":"structural damage"},{"phrase":"structural changes"},{"phrase":"structural problems"}]',NULL,'/ˈstrʌktʃərəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/struc/structural__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2754,'ngsl-6-10',3,'website','trang web','noun','[{"en":"You can book tickets on our website.","vi":"Bạn có thể đặt vé trên trang web của chúng tôi."},{"en":"She wants to build a website to sell her paintings.","vi":"Cô ấy muốn làm một trang web để bán tranh của mình."},{"en":"Check the school website for the new timetable.","vi":"Hãy xem trang web của trường để biết thời khóa biểu mới."}]','[{"phrase":"visit a website"},{"phrase":"build a website"},{"phrase":"official website"}]',NULL,'/ˈwebsaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/web/websi/website__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2755,'ngsl-6-10',4,'fool','kẻ ngốc; người khờ dại','noun','[{"en":"I felt like a fool when I realized my mistake.","vi":"Tôi thấy mình như một kẻ ngốc khi nhận ra lỗi của mình."},{"en":"Don''t make a fool of yourself in front of your boss.","vi":"Đừng tự biến mình thành kẻ ngốc trước mặt sếp."},{"en":"Only a fool would drive in this weather.","vi":"Chỉ có kẻ ngốc mới lái xe trong thời tiết thế này."}]','[{"phrase":"make a fool of yourself"},{"phrase":"feel like a fool"},{"phrase":"such a fool"}]',NULL,'/fuːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/fool_/fool__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2756,'ngsl-6-10',5,'alongside','bên cạnh; cùng với','preposition','[{"en":"A small path runs alongside the river.","vi":"Một con đường nhỏ chạy dọc bên cạnh con sông."},{"en":"I love to work alongside people who enjoy their jobs.","vi":"Tôi thích làm việc cùng những người yêu công việc của họ."},{"en":"Children learn English alongside their other school subjects.","vi":"Trẻ em học tiếng Anh cùng với các môn học khác ở trường."}]','[{"phrase":"work alongside"},{"phrase":"alongside each other"},{"phrase":"run alongside"}]',NULL,'/əˌlɔːŋˈsaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alo/along/alongside__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2757,'ngsl-6-10',6,'unite','đoàn kết; hợp nhất; gắn kết','verb','[{"en":"The big match united the whole town for one evening.","vi":"Trận đấu lớn đã gắn kết cả thị trấn trong một buổi tối."},{"en":"People in the area will unite against the plan to close the park.","vi":"Người dân trong khu vực sẽ đoàn kết chống lại kế hoạch đóng cửa công viên."},{"en":"The two clubs decided to unite and share one stadium.","vi":"Hai câu lạc bộ quyết định hợp nhất và dùng chung một sân vận động."}]','[{"phrase":"unite against"},{"phrase":"unite behind"},{"phrase":"unite the country"}]',NULL,'/juˈnaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unite/unite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2758,'ngsl-6-10',7,'gently','nhẹ nhàng; từ tốn','adverb','[{"en":"She gently closed the door so the baby wouldn''t wake up.","vi":"Cô ấy nhẹ nhàng đóng cửa để em bé không thức giấc."},{"en":"Stir gently and let the soup cook for a few minutes.","vi":"Khuấy nhẹ và để súp nấu thêm vài phút."},{"en":"He smiled and spoke gently to the nervous student.","vi":"Anh ấy mỉm cười và nói chuyện từ tốn với cậu học sinh đang lo lắng."}]','[{"phrase":"stir gently"},{"phrase":"speak gently"},{"phrase":"smile gently"}]',NULL,'/ˈdʒentli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gentl/gently__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2759,'ngsl-6-10',8,'compute','tính toán; tính ra','verb','[{"en":"The app computes your daily calorie needs automatically.","vi":"Ứng dụng tự động tính lượng calo bạn cần mỗi ngày."},{"en":"The program can compute the average score for each class.","vi":"Chương trình có thể tính điểm trung bình của từng lớp."},{"en":"We computed the total cost of the trip before booking anything.","vi":"Chúng tôi đã tính tổng chi phí chuyến đi trước khi đặt bất cứ thứ gì."}]','[{"phrase":"compute the average"},{"phrase":"compute the total cost"}]',NULL,'/kəmˈpjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compu/compute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2760,'ngsl-6-10',9,'wipe','lau; chùi; xóa sạch','verb','[{"en":"Please wipe the table after you finish eating.","vi":"Làm ơn lau bàn sau khi ăn xong."},{"en":"He wiped his hands on a towel.","vi":"Anh ấy lau tay vào khăn."},{"en":"Someone wiped all the files from my old laptop.","vi":"Ai đó đã xóa sạch toàn bộ tệp trong chiếc laptop cũ của tôi."}]','[{"phrase":"wipe the table"},{"phrase":"wipe your hands"},{"phrase":"wipe clean"}]',NULL,'/waɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wip/wipe_/wipe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2761,'ngsl-6-10',10,'weird','kỳ lạ; kỳ quặc','adjective','[{"en":"I heard a weird noise coming from the kitchen.","vi":"Tôi nghe thấy một tiếng động lạ phát ra từ nhà bếp."},{"en":"It feels weird to be back at my old school.","vi":"Cảm giác thật lạ khi quay lại ngôi trường cũ."},{"en":"My brother has some weird ideas about food.","vi":"Anh trai tôi có vài ý tưởng kỳ quặc về đồ ăn."}]','[{"phrase":"weird noise"},{"phrase":"feel weird"},{"phrase":"something weird"}]',NULL,'/wɪrd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wei/weird/weird__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2762,'ngsl-6-10',11,'gaze','nhìn chăm chú; nhìn đăm đăm','verb','[{"en":"She gazed out of the window for a long time.","vi":"Cô ấy nhìn đăm đăm ra ngoài cửa sổ rất lâu."},{"en":"We love to lie on the grass and gaze at the stars.","vi":"Chúng tôi thích nằm trên cỏ và ngắm nhìn các vì sao."},{"en":"He gazed at the painting without saying a word.","vi":"Anh ấy chăm chú nhìn bức tranh mà không nói lời nào."}]','[{"phrase":"gaze at"},{"phrase":"gaze out of the window"},{"phrase":"gaze into the distance"}]','gaze at sb/sth','/ɡeɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gaz/gaze_/gaze__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2763,'ngsl-6-10',12,'fade','phai màu; mờ dần; nhỏ dần','verb','[{"en":"My favorite jeans faded after a few washes.","vi":"Chiếc quần jean yêu thích của tôi bị phai màu sau vài lần giặt."},{"en":"The music began to fade away as the car drove off.","vi":"Tiếng nhạc bắt đầu nhỏ dần khi chiếc xe chạy đi."},{"en":"Her smile slowly faded when she saw the bill.","vi":"Nụ cười của cô ấy tắt dần khi nhìn thấy hóa đơn."}]','[{"phrase":"fade away"},{"phrase":"slowly fade"},{"phrase":"memories fade"}]',NULL,'/feɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fad/fade_/fade__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2764,'ngsl-6-10',13,'cough','ho','verb','[{"en":"The smoke made everyone start to cough.","vi":"Khói khiến mọi người bắt đầu ho."},{"en":"My son coughed all night, so neither of us slept.","vi":"Con trai tôi ho cả đêm nên cả hai chúng tôi đều không ngủ được."},{"en":"Cover your mouth when you cough or sneeze.","vi":"Hãy che miệng khi bạn ho hoặc hắt hơi."}]','[{"phrase":"start to cough"},{"phrase":"cough loudly"},{"phrase":"a bad cough"}]',NULL,'/kɔːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/cough/cough__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2765,'ngsl-6-10',14,'hypothesis','giả thuyết','noun','[{"en":"These results support the hypothesis that plants grow faster with music.","vi":"Những kết quả này ủng hộ giả thuyết rằng cây mọc nhanh hơn khi có nhạc."},{"en":"Scientists need more data to test this hypothesis.","vi":"Các nhà khoa học cần thêm dữ liệu để kiểm chứng giả thuyết này."},{"en":"Her hypothesis turned out to be completely wrong.","vi":"Giả thuyết của cô ấy hóa ra hoàn toàn sai."}]','[{"phrase":"support the hypothesis"},{"phrase":"test a hypothesis"},{"phrase":"form a hypothesis"}]','số nhiều: hypotheses','/haɪˈpɑːθəsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hyp/hypot/hypothesis__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2766,'ngsl-6-10',15,'royal','thuộc hoàng gia','adjective','[{"en":"The royal family lived in this palace for centuries.","vi":"Gia đình hoàng gia đã sống trong cung điện này suốt nhiều thế kỷ."},{"en":"We walked around the royal gardens during our trip.","vi":"Chúng tôi đi dạo quanh khu vườn hoàng gia trong chuyến đi."},{"en":"Crowds gathered outside to watch the royal wedding.","vi":"Đám đông tụ tập bên ngoài để xem đám cưới hoàng gia."}]','[{"phrase":"royal family"},{"phrase":"royal palace"},{"phrase":"royal wedding"}]',NULL,'/ˈrɔɪəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roy/royal/royal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2767,'ngsl-6-10',16,'theoretical','thuộc lý thuyết; trên lý thuyết','adjective','[{"en":"The course gives you theoretical knowledge and practical experience.","vi":"Khóa học mang lại cho bạn kiến thức lý thuyết và kinh nghiệm thực tế."},{"en":"For now, the risk is purely theoretical, so don''t worry.","vi":"Hiện giờ, rủi ro đó chỉ là trên lý thuyết, nên đừng lo."},{"en":"She studies theoretical physics at the university.","vi":"Cô ấy học vật lý lý thuyết ở trường đại học."}]','[{"phrase":"theoretical knowledge"},{"phrase":"theoretical physics"},{"phrase":"purely theoretical"}]',NULL,'/ˌθiːəˈretɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theor/theoretical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2768,'ngsl-6-10',17,'curtain','rèm cửa; màn sân khấu','noun','[{"en":"Could you close the curtains because the sun is too bright?","vi":"Bạn kéo rèm lại giúp mình được không, vì nắng chói quá?"},{"en":"She opened the curtains and looked out at the snow.","vi":"Cô ấy kéo rèm ra và nhìn tuyết bên ngoài."},{"en":"The audience clapped loudly when the curtain came down.","vi":"Khán giả vỗ tay rất to khi màn sân khấu hạ xuống."}]','[{"phrase":"close the curtains"},{"phrase":"open the curtains"},{"phrase":"draw the curtains"},{"phrase":"shower curtain"}]',NULL,'/ˈkɜːrtn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curta/curtain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2769,'ngsl-6-10',18,'mayor','thị trưởng','noun','[{"en":"The mayor opened the new library this morning.","vi":"Thị trưởng đã khai trương thư viện mới vào sáng nay."},{"en":"The mayor of our town wants to build more bike lanes.","vi":"Thị trưởng thị trấn chúng tôi muốn xây thêm làn đường dành cho xe đạp."},{"en":"Local students wrote a letter to the mayor about the park.","vi":"Học sinh địa phương đã viết thư gửi thị trưởng về công viên."}]','[{"phrase":"mayor of"},{"phrase":"deputy mayor"},{"phrase":"former mayor"}]',NULL,'/ˈmeɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/may/mayor/mayor__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2770,'ngsl-6-10',19,'darkness','bóng tối','noun','[{"en":"The lights went out and the room was in total darkness.","vi":"Đèn tắt và căn phòng chìm trong bóng tối hoàn toàn."},{"en":"My cat''s eyes shine in the darkness.","vi":"Mắt con mèo nhà tôi sáng lên trong bóng tối."},{"en":"We waited in the darkness for the show to begin.","vi":"Chúng tôi chờ trong bóng tối cho đến khi buổi diễn bắt đầu."}]','[{"phrase":"total darkness"},{"phrase":"in the darkness"},{"phrase":"darkness falls"}]','không đếm được','/ˈdɑːrknəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dar/darkn/darkness__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2771,'ngsl-6-10',20,'aunt','cô; dì; bác gái','noun','[{"en":"My aunt lives in a small village by the sea.","vi":"Dì tôi sống ở một ngôi làng nhỏ ven biển."},{"en":"We''re staying with my aunt and uncle this summer.","vi":"Hè này chúng tôi ở nhà cô chú tôi."},{"en":"Her aunt taught her how to bake bread.","vi":"Dì của cô ấy đã dạy cô ấy cách nướng bánh mì."}]','[{"phrase":"aunt and uncle"},{"phrase":"favorite aunt"},{"phrase":"great-aunt"}]',NULL,'/ænt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aun/aunt_/aunt__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2772,'ngsl-6-10',21,'tournament','giải đấu','noun','[{"en":"Our school won the basketball tournament last month.","vi":"Trường chúng tôi đã vô địch giải bóng rổ tháng trước."},{"en":"Sixteen teams will take part in the tournament.","vi":"Mười sáu đội sẽ tham gia giải đấu."},{"en":"She hurt her knee before the tennis tournament started.","vi":"Cô ấy bị đau đầu gối trước khi giải quần vợt bắt đầu."}]','[{"phrase":"win a tournament"},{"phrase":"tennis tournament"},{"phrase":"chess tournament"}]',NULL,'/ˈtʊrnəmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/tourn/tournament__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2773,'ngsl-6-10',22,'registration','sự đăng ký; việc đăng ký','noun','[{"en":"Registration for the summer course closes on Friday.","vi":"Việc đăng ký khóa học hè sẽ kết thúc vào thứ Sáu."},{"en":"Please bring your ID to the registration desk.","vi":"Vui lòng mang theo giấy tờ tùy thân đến quầy đăng ký."},{"en":"Online registration only takes a few minutes.","vi":"Đăng ký trực tuyến chỉ mất vài phút."}]','[{"phrase":"registration form"},{"phrase":"registration fee"},{"phrase":"online registration"},{"phrase":"registration desk"}]',NULL,'/ˌredʒɪˈstreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regis/registration__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2774,'ngsl-6-10',23,'fragment','mảnh vỡ; đoạn rời rạc','noun','[{"en":"Small fragments of glass were all over the floor.","vi":"Những mảnh kính vỡ nhỏ vương vãi khắp sàn nhà."},{"en":"I only remember fragments of my dream.","vi":"Tôi chỉ nhớ được vài đoạn rời rạc của giấc mơ."},{"en":"She overheard a fragment of their conversation in the hall.","vi":"Cô ấy nghe lỏm được một đoạn trong cuộc trò chuyện của họ ở hành lang."}]','[{"phrase":"fragments of glass"},{"phrase":"small fragments"},{"phrase":"a fragment of"}]',NULL,'/ˈfræɡmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/fragm/fragment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2775,'ngsl-6-10',24,'listener','người nghe; thính giả','noun','[{"en":"My grandmother is a very good listener.","vi":"Bà tôi là người rất biết lắng nghe."},{"en":"The radio show has thousands of listeners every morning.","vi":"Chương trình phát thanh có hàng nghìn thính giả mỗi sáng."},{"en":"Good speakers always keep their listeners interested.","vi":"Người nói giỏi luôn khiến người nghe cảm thấy hứng thú."}]','[{"phrase":"good listener"},{"phrase":"radio listeners"},{"phrase":"regular listener"}]',NULL,'/ˈlɪsənər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lis/liste/listener__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2776,'ngsl-6-10',25,'immigration','sự nhập cư; xuất nhập cảnh','noun','[{"en":"It took us an hour to go through immigration at the airport.","vi":"Chúng tôi mất một tiếng để làm thủ tục nhập cảnh ở sân bay."},{"en":"Please have your passport ready for the immigration officer.","vi":"Vui lòng chuẩn bị sẵn hộ chiếu cho nhân viên xuất nhập cảnh."},{"en":"The city grew quickly because of immigration from nearby countries.","vi":"Thành phố phát triển nhanh nhờ làn sóng nhập cư từ các nước lân cận."}]','[{"phrase":"go through immigration"},{"phrase":"immigration officer"},{"phrase":"immigration control"}]','không đếm được','/ˌɪmɪˈɡreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immig/immigration__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2777,'ngsl-6-10',26,'tender','mềm; dịu dàng; đau (khi chạm vào)','adjective','[{"en":"Cook the meat slowly until it is tender.","vi":"Nấu thịt thật chậm cho đến khi mềm."},{"en":"She gave the child a tender kiss on the forehead.","vi":"Cô ấy hôn dịu dàng lên trán đứa trẻ."},{"en":"My ankle is still tender after I twisted it.","vi":"Mắt cá chân tôi vẫn còn đau sau khi bị trẹo."}]','[{"phrase":"tender kiss"},{"phrase":"tender meat"},{"phrase":"tender smile"}]',NULL,'/ˈtendər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tende/tender__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2778,'ngsl-6-10',27,'density','mật độ; khối lượng riêng','noun','[{"en":"This part of the city has a very high population density.","vi":"Khu vực này của thành phố có mật độ dân số rất cao."},{"en":"Wood floats because it has a lower density than water.","vi":"Gỗ nổi vì có khối lượng riêng nhỏ hơn nước."},{"en":"Low housing density gives this neighborhood a quiet, open feel.","vi":"Mật độ nhà ở thấp mang lại cho khu phố này cảm giác yên tĩnh, thoáng đãng."}]','[{"phrase":"population density"},{"phrase":"high density"},{"phrase":"low density"},{"phrase":"bone density"}]',NULL,'/ˈdensəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/densi/density__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2779,'ngsl-6-10',28,'ugly','xấu xí; khó coi; tồi tệ','adjective','[{"en":"Everyone thinks it''s an ugly building, but I like it.","vi":"Ai cũng nghĩ đó là một tòa nhà xấu xí, nhưng tôi lại thích nó."},{"en":"He wore an ugly sweater to the holiday party.","vi":"Anh ấy mặc một chiếc áo len xấu xí đến bữa tiệc ngày lễ."},{"en":"The argument turned ugly, so I left the room.","vi":"Cuộc cãi vã trở nên tồi tệ, nên tôi rời khỏi phòng."}]','[{"phrase":"ugly building"},{"phrase":"turn ugly"},{"phrase":"ugly scene"}]',NULL,'/ˈʌɡli/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ugl/ugly_/ugly__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2780,'ngsl-6-10',29,'module','học phần; mô-đun','noun','[{"en":"Everyone must take the core module in the first term.","vi":"Ai cũng phải học học phần cốt lõi trong học kỳ đầu tiên."},{"en":"I passed all my modules except the one on statistics.","vi":"Tôi đã qua tất cả các học phần, trừ môn thống kê."},{"en":"The software is built from small modules that are easy to update.","vi":"Phần mềm được xây dựng từ các mô-đun nhỏ, dễ cập nhật."}]','[{"phrase":"core module"},{"phrase":"optional module"},{"phrase":"training module"}]',NULL,'/ˈmɑːdʒuːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/modul/module__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2781,'awl-2-01',1,'achieve','đạt được; giành được','verb','[{"en":"Few new businesses achieve success in their first year.","vi":"Rất ít doanh nghiệp mới đạt được thành công ngay trong năm đầu tiên."},{"en":"The company failed to achieve its sales targets this year.","vi":"Năm nay công ty đã không đạt được các chỉ tiêu doanh số."},{"en":"Students who set clear goals usually achieve better results.","vi":"Những sinh viên đặt ra mục tiêu rõ ràng thường đạt được kết quả tốt hơn."}]','[{"phrase":"achieve success"},{"phrase":"achieve a goal"},{"phrase":"achieve results"},{"phrase":"achieve a target"}]',NULL,'/əˈtʃiːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ach/achie/achieve__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2782,'awl-2-01',2,'acquire','tiếp thu; có được; mua lại','verb','[{"en":"Children acquire language skills very quickly in their early years.","vi":"Trẻ em tiếp thu các kỹ năng ngôn ngữ rất nhanh trong những năm đầu đời."},{"en":"Workers can acquire new skills through short training courses.","vi":"Người lao động có thể có được kỹ năng mới qua các khóa đào tạo ngắn hạn."},{"en":"Last year the firm acquired a smaller rival for two million dollars.","vi":"Năm ngoái, công ty đã mua lại một đối thủ nhỏ hơn với giá hai triệu đô la."}]','[{"phrase":"acquire skills"},{"phrase":"acquire knowledge"},{"phrase":"acquire a company"}]',NULL,'/əˈkwaɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acq/acqui/acquire__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2783,'awl-2-01',3,'administrate','quản lý; điều hành','verb','[{"en":"A small team administrates the scholarship program for the university.","vi":"Một nhóm nhỏ quản lý chương trình học bổng của trường đại học."},{"en":"She was hired to administrate the new research center.","vi":"Cô ấy được tuyển dụng để điều hành trung tâm nghiên cứu mới."},{"en":"Local councils administrate most public services in the region.","vi":"Chính quyền địa phương quản lý hầu hết các dịch vụ công trong khu vực."}]','[{"phrase":"administrate a program"},{"phrase":"administrate funds"}]','Thường dùng administer; danh từ: administration','/æˈdmɪnɪˌstreɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2784,'awl-2-01',4,'affect','ảnh hưởng đến; tác động đến','verb','[{"en":"Rising prices affect low-income families more than anyone else.","vi":"Giá cả tăng ảnh hưởng đến các gia đình thu nhập thấp nhiều hơn ai hết."},{"en":"The storm seriously affected transport across the northern region.","vi":"Cơn bão đã ảnh hưởng nghiêm trọng đến giao thông khắp khu vực phía bắc."},{"en":"Lack of sleep can affect your ability to concentrate.","vi":"Thiếu ngủ có thể ảnh hưởng đến khả năng tập trung của bạn."}]','[{"phrase":"seriously affect"},{"phrase":"directly affect"},{"phrase":"adversely affect"}]','affect (v) ≠ effect (n)','/əˈfekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affec/affect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2785,'awl-2-01',5,'appropriate','phù hợp; thích hợp','adjective','[{"en":"Please wear clothing appropriate for a formal business meeting.","vi":"Vui lòng mặc trang phục phù hợp với một cuộc họp công việc trang trọng."},{"en":"The committee will take appropriate action once the review is complete.","vi":"Ủy ban sẽ có biện pháp thích hợp sau khi việc xem xét hoàn tất."},{"en":"Is this textbook appropriate for first-year students?","vi":"Cuốn giáo trình này có phù hợp với sinh viên năm nhất không?"}]','[{"phrase":"appropriate action"},{"phrase":"appropriate for"},{"phrase":"entirely appropriate"},{"phrase":"appropriate measures"}]','appropriate for + danh từ','/əˈprəʊpriət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/appropriate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2786,'awl-2-01',6,'aspect','khía cạnh; mặt','noun','[{"en":"Cost is only one aspect of the problem we need to consider.","vi":"Chi phí chỉ là một khía cạnh của vấn đề mà chúng ta cần xem xét."},{"en":"The course covers all aspects of running a small business.","vi":"Khóa học bao quát mọi khía cạnh của việc điều hành một doanh nghiệp nhỏ."},{"en":"Researchers studied the social aspects of online learning.","vi":"Các nhà nghiên cứu đã tìm hiểu các khía cạnh xã hội của việc học trực tuyến."}]','[{"phrase":"aspect of"},{"phrase":"all aspects"},{"phrase":"important aspect"},{"phrase":"social aspects"}]',NULL,'/ˈæspekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/asp/aspec/aspect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2787,'awl-2-01',7,'assist','hỗ trợ; giúp đỡ','verb','[{"en":"Two graduate students assisted the professor with the experiment.","vi":"Hai học viên cao học đã hỗ trợ giáo sư thực hiện thí nghiệm."},{"en":"Our staff members are available to assist customers with their questions.","vi":"Nhân viên của chúng tôi luôn sẵn sàng giúp đỡ khách hàng giải đáp thắc mắc."},{"en":"The new software will assist doctors in making faster diagnoses.","vi":"Phần mềm mới sẽ hỗ trợ các bác sĩ chẩn đoán nhanh hơn."}]','[{"phrase":"assist with"},{"phrase":"assist in"},{"phrase":"assist customers"}]','assist sb with sth / in doing sth','/əˈsɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assis/assist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2788,'awl-2-01',8,'category','loại; hạng mục; nhóm','noun','[{"en":"The products are divided into three main categories.","vi":"Các sản phẩm được chia thành ba loại chính."},{"en":"She won an award in the best new writer category.","vi":"Cô ấy đã giành giải ở hạng mục nhà văn mới xuất sắc nhất."},{"en":"Most of the patients in the study fall into this category.","vi":"Phần lớn bệnh nhân trong nghiên cứu thuộc nhóm này."}]','[{"phrase":"fall into a category"},{"phrase":"main category"},{"phrase":"broad category"}]',NULL,'/ˈkætəɡɔːri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cat/categ/category__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2789,'awl-2-01',9,'chapter','chương (sách); giai đoạn','noun','[{"en":"Please read the first two chapters before next week''s seminar.","vi":"Vui lòng đọc hai chương đầu tiên trước buổi thảo luận tuần sau."},{"en":"Chapter three discusses the causes of the economic crisis.","vi":"Chương ba bàn về nguyên nhân của cuộc khủng hoảng kinh tế."},{"en":"Moving abroad opened a new chapter in her career.","vi":"Việc ra nước ngoài đã mở ra một giai đoạn mới trong sự nghiệp của cô ấy."}]','[{"phrase":"the first chapter"},{"phrase":"the final chapter"},{"phrase":"a new chapter"}]',NULL,'/ˈtʃæptər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chapt/chapter__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2790,'awl-2-01',10,'commission','ủy ban; tiền hoa hồng','noun','[{"en":"The government set up a commission to investigate the accident.","vi":"Chính phủ đã thành lập một ủy ban để điều tra vụ tai nạn."},{"en":"Sales staff earn a commission on every car they sell.","vi":"Nhân viên bán hàng được hưởng tiền hoa hồng trên mỗi chiếc xe họ bán."},{"en":"The commission will publish its final report next spring.","vi":"Ủy ban sẽ công bố báo cáo cuối cùng vào mùa xuân năm sau."}]','[{"phrase":"set up a commission"},{"phrase":"independent commission"},{"phrase":"earn commission"},{"phrase":"commission on"}]',NULL,'/kəˈmɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commission__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2791,'awl-2-01',11,'community','cộng đồng','noun','[{"en":"The new library will serve the whole local community.","vi":"Thư viện mới sẽ phục vụ toàn thể cộng đồng địa phương."},{"en":"Members of the scientific community welcomed the new findings.","vi":"Các thành viên trong cộng đồng khoa học đã hoan nghênh những phát hiện mới."},{"en":"Volunteers organized a community event to clean up the park.","vi":"Các tình nguyện viên đã tổ chức một sự kiện cộng đồng để dọn dẹp công viên."}]','[{"phrase":"local community"},{"phrase":"scientific community"},{"phrase":"business community"},{"phrase":"community service"}]',NULL,'/kəˈmjuːnəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/community__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2792,'awl-2-01',12,'complex','phức tạp','adjective','[{"en":"Climate change is a complex problem with no simple solution.","vi":"Biến đổi khí hậu là một vấn đề phức tạp, không có giải pháp đơn giản."},{"en":"The brain is the most complex organ in the human body.","vi":"Não là cơ quan phức tạp nhất trong cơ thể con người."},{"en":"The application rules were too complex for most people to follow.","vi":"Các quy định nộp đơn quá phức tạp khiến hầu hết mọi người khó làm theo."}]','[{"phrase":"complex problem"},{"phrase":"complex issue"},{"phrase":"highly complex"},{"phrase":"complex system"}]',NULL,'/kəmˈpleks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complex__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2793,'awl-2-01',13,'compute','tính toán','verb','[{"en":"The program computes the average score for each class.","vi":"Chương trình tính điểm trung bình cho từng lớp."},{"en":"Researchers computed the total cost of the project.","vi":"Các nhà nghiên cứu đã tính toán tổng chi phí của dự án."},{"en":"It is difficult to compute the exact risk of an earthquake.","vi":"Rất khó để tính toán chính xác nguy cơ xảy ra động đất."}]','[{"phrase":"compute the average"},{"phrase":"compute the total"},{"phrase":"compute the cost"}]',NULL,'/kəmˈpjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compu/compute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2794,'awl-2-01',14,'conclude','kết luận; kết thúc','verb','[{"en":"The study concluded that exercise improves memory in older adults.","vi":"Nghiên cứu kết luận rằng tập thể dục giúp cải thiện trí nhớ ở người lớn tuổi."},{"en":"From the evidence, we can conclude that the plan has failed.","vi":"Từ các bằng chứng, chúng ta có thể kết luận rằng kế hoạch đã thất bại."},{"en":"The conference concluded with a short speech from the director.","vi":"Hội nghị kết thúc bằng một bài phát biểu ngắn của giám đốc."}]','[{"phrase":"conclude that"},{"phrase":"conclude with"},{"phrase":"the report concludes"}]','conclude that + mệnh đề','/kənˈkluːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconclude__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2795,'awl-2-01',15,'conduct','tiến hành; thực hiện','verb','[{"en":"The team conducted a survey of five hundred local businesses.","vi":"Nhóm đã tiến hành khảo sát năm trăm doanh nghiệp địa phương."},{"en":"Scientists are conducting experiments to test the new vaccine.","vi":"Các nhà khoa học đang tiến hành thí nghiệm để kiểm tra vắc-xin mới."},{"en":"All interviews were conducted in English by trained staff.","vi":"Tất cả các cuộc phỏng vấn đều được nhân viên đã qua đào tạo thực hiện bằng tiếng Anh."}]','[{"phrase":"conduct research"},{"phrase":"conduct a survey"},{"phrase":"conduct an experiment"},{"phrase":"conduct an interview"}]',NULL,'/kənˈdʌkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcond/xconduct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2796,'awl-2-01',16,'consequent','là hệ quả; kéo theo','adjective','[{"en":"The factory closed, with a consequent loss of two hundred jobs.","vi":"Nhà máy đóng cửa, kéo theo việc mất đi hai trăm việc làm."},{"en":"Heavy rain and the consequent flooding damaged many homes.","vi":"Mưa lớn cùng trận lũ lụt do nó gây ra đã làm hư hại nhiều ngôi nhà."},{"en":"Rising fuel prices and the consequent increase in costs worried farmers.","vi":"Giá nhiên liệu tăng và chi phí tăng theo đã khiến nông dân lo lắng."}]','[{"phrase":"consequent loss"},{"phrase":"consequent increase"},{"phrase":"consequent upon"}]','Trạng từ: consequently (do đó)','/ˈkɑːnsɪkwent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsequent__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2797,'awl-2-01',17,'construct','xây dựng; dựng nên','verb','[{"en":"The bridge was constructed in less than two years.","vi":"Cây cầu được xây dựng trong vòng chưa đầy hai năm."},{"en":"The city plans to construct a new hospital near the station.","vi":"Thành phố dự định xây dựng một bệnh viện mới gần nhà ga."},{"en":"Students must construct a clear argument supported by evidence.","vi":"Sinh viên phải xây dựng một lập luận rõ ràng có bằng chứng hỗ trợ."}]','[{"phrase":"construct an argument"},{"phrase":"construct a model"},{"phrase":"newly constructed"}]',NULL,'/kənˈstrʌkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstruct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2798,'awl-2-01',18,'consume','tiêu thụ; tiêu tốn','verb','[{"en":"Older cars consume much more fuel than modern ones.","vi":"Xe ô tô đời cũ tiêu thụ nhiều nhiên liệu hơn hẳn so với xe hiện đại."},{"en":"People in cities consume more energy than those in rural areas.","vi":"Người dân thành thị tiêu thụ nhiều năng lượng hơn người dân nông thôn."},{"en":"Writing the final report consumed most of our time.","vi":"Việc viết báo cáo cuối cùng đã tiêu tốn phần lớn thời gian của chúng tôi."}]','[{"phrase":"consume energy"},{"phrase":"consume fuel"},{"phrase":"consume resources"}]',NULL,'/kənˈsuːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsume__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2799,'awl-2-01',19,'credit','tín dụng; tín chỉ; sự ghi nhận công lao','noun','[{"en":"Many small businesses find it hard to get credit from banks.","vi":"Nhiều doanh nghiệp nhỏ gặp khó khăn khi vay tín dụng từ ngân hàng."},{"en":"Students must earn thirty credits to finish the program.","vi":"Sinh viên phải tích lũy ba mươi tín chỉ để hoàn thành chương trình."},{"en":"She deserves credit for the success of the project.","vi":"Cô ấy xứng đáng được ghi nhận công lao trong thành công của dự án."}]','[{"phrase":"deserve credit"},{"phrase":"take credit for"},{"phrase":"earn credits"},{"phrase":"credit card"}]',NULL,'/ˈkredɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/credi/credit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2800,'awl-2-01',20,'culture','văn hóa','noun','[{"en":"Learning a language helps you understand a different culture.","vi":"Học một ngôn ngữ giúp bạn hiểu một nền văn hóa khác."},{"en":"The company has a strong culture of teamwork.","vi":"Công ty có văn hóa làm việc nhóm rất mạnh."},{"en":"Young people are strongly shaped by popular culture and social media.","vi":"Giới trẻ chịu ảnh hưởng mạnh mẽ của văn hóa đại chúng và mạng xã hội."}]','[{"phrase":"popular culture"},{"phrase":"corporate culture"},{"phrase":"local culture"},{"phrase":"culture of"}]',NULL,'/ˈkʌltʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cul/cultu/culture__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2801,'awl-2-01',21,'design','thiết kế','verb','[{"en":"The building was designed to use as little energy as possible.","vi":"Tòa nhà được thiết kế để sử dụng ít năng lượng nhất có thể."},{"en":"Engineers are designing a cheaper battery for electric cars.","vi":"Các kỹ sư đang thiết kế một loại pin rẻ hơn cho xe điện."},{"en":"We designed the survey to be completed in ten minutes.","vi":"Chúng tôi thiết kế bản khảo sát để có thể hoàn thành trong mười phút."}]','[{"phrase":"be designed to"},{"phrase":"specially designed"},{"phrase":"well designed"},{"phrase":"design a system"}]',NULL,'/dɪˈzaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/desig/design__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2802,'awl-2-01',22,'distinct','riêng biệt; khác biệt; rõ rệt','adjective','[{"en":"The study identified three distinct groups of customers.","vi":"Nghiên cứu đã xác định ba nhóm khách hàng riêng biệt."},{"en":"Weather is distinct from climate, although people often confuse them.","vi":"Thời tiết khác biệt với khí hậu, dù mọi người thường nhầm lẫn hai khái niệm này."},{"en":"Speaking two languages gives job seekers a distinct advantage.","vi":"Việc nói được hai thứ tiếng mang lại cho người tìm việc một lợi thế rõ rệt."}]','[{"phrase":"distinct from"},{"phrase":"clearly distinct"},{"phrase":"distinct advantage"}]','distinct from: khác với','/dɪˈstɪŋkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disti/distinct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2803,'awl-2-01',23,'element','yếu tố; thành phần; nguyên tố','noun','[{"en":"Trust is a key element of any successful team.","vi":"Sự tin tưởng là yếu tố then chốt của bất kỳ đội nhóm thành công nào."},{"en":"The plan contains several elements that need further discussion.","vi":"Kế hoạch có một số thành phần cần được thảo luận thêm."},{"en":"Oxygen is the most common element in Earth''s crust.","vi":"Ôxy là nguyên tố phổ biến nhất trong vỏ Trái Đất."}]','[{"phrase":"key element"},{"phrase":"important element"},{"phrase":"element of"},{"phrase":"chemical element"}]',NULL,'/ˈelɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/eleme/element__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2804,'awl-2-01',24,'equate','đánh đồng; tương đương với','verb','[{"en":"Many people equate success with making a lot of money.","vi":"Nhiều người đánh đồng thành công với việc kiếm được nhiều tiền."},{"en":"We should not equate good grades with real understanding.","vi":"Chúng ta không nên đánh đồng điểm cao với sự hiểu biết thực sự."},{"en":"The pay rise equates to about fifty dollars a month.","vi":"Khoản tăng lương này tương đương khoảng năm mươi đô la mỗi tháng."}]','[{"phrase":"equate with"},{"phrase":"equate to"}]','equate A with B: đánh đồng A với B','/ɪˈkweɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equat/equate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2805,'awl-2-01',25,'evaluate','đánh giá','verb','[{"en":"Teachers evaluate students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ."},{"en":"The study aimed to evaluate how well the new drug works.","vi":"Nghiên cứu nhằm đánh giá mức độ hiệu quả của loại thuốc mới."},{"en":"An outside expert was hired to evaluate the project.","vi":"Một chuyên gia bên ngoài đã được thuê để đánh giá dự án."}]','[{"phrase":"evaluate the effectiveness"},{"phrase":"evaluate performance"},{"phrase":"evaluate progress"},{"phrase":"carefully evaluate"}]',NULL,'/ɪˈvæljueɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eva/evalu/evaluate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2806,'awl-2-01',26,'feature','đặc điểm; tính năng','noun','[{"en":"The latest version of the app includes several new features.","vi":"Phiên bản mới nhất của ứng dụng có thêm một số tính năng mới."},{"en":"A key feature of the course is its focus on practical skills.","vi":"Một đặc điểm chính của khóa học là chú trọng vào kỹ năng thực hành."},{"en":"High mountains are a common feature of the region''s landscape.","vi":"Núi cao là một đặc điểm phổ biến của cảnh quan vùng này."}]','[{"phrase":"key feature"},{"phrase":"main feature"},{"phrase":"new features"},{"phrase":"common feature"}]',NULL,'/ˈfiːtʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fea/featu/feature__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2807,'awl-2-01',27,'final','cuối cùng; chung cuộc','adjective','[{"en":"The final decision will be made by the board next month.","vi":"Quyết định cuối cùng sẽ được hội đồng quản trị đưa ra vào tháng sau."},{"en":"Students must submit their final reports by Friday.","vi":"Sinh viên phải nộp báo cáo cuối cùng trước thứ Sáu."},{"en":"The project is now in its final stage.","vi":"Dự án hiện đang ở giai đoạn cuối cùng."}]','[{"phrase":"final decision"},{"phrase":"final stage"},{"phrase":"final result"},{"phrase":"final report"}]',NULL,'/ˈfaɪnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/final/final__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2808,'awl-2-01',28,'focus','tập trung','verb','[{"en":"This paper focuses on the effects of social media on teenagers.","vi":"Bài báo này tập trung vào tác động của mạng xã hội đối với thanh thiếu niên."},{"en":"Our company will focus on growth in Asian markets next year.","vi":"Năm tới, công ty chúng tôi sẽ tập trung vào tăng trưởng ở các thị trường châu Á."},{"en":"It is hard to focus when the office is so noisy.","vi":"Thật khó tập trung khi văn phòng quá ồn ào."}]','[{"phrase":"focus on"},{"phrase":"focus attention on"},{"phrase":"mainly focus"}]','focus on + danh từ / V-ing','/ˈfəʊkəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foc/focus/focus__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2809,'awl-2-01',29,'impact','tác động; ảnh hưởng','noun','[{"en":"The new policy had a major impact on small businesses.","vi":"Chính sách mới đã có tác động lớn đến các doanh nghiệp nhỏ."},{"en":"Scientists are studying the impact of climate change on farming.","vi":"Các nhà khoa học đang nghiên cứu tác động của biến đổi khí hậu đối với nông nghiệp."},{"en":"Online shopping has had a negative impact on local stores.","vi":"Mua sắm trực tuyến đã gây ảnh hưởng tiêu cực đến các cửa hàng địa phương."}]','[{"phrase":"have an impact on"},{"phrase":"major impact"},{"phrase":"negative impact"},{"phrase":"environmental impact"}]','impact on + danh từ','/ˈɪmpækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impac/impact__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2810,'awl-2-01',30,'injure','làm bị thương; gây chấn thương','verb','[{"en":"Three workers were seriously injured in an accident at the factory.","vi":"Ba công nhân đã bị thương nặng trong một vụ tai nạn tại nhà máy."},{"en":"Players who train too hard are more likely to injure themselves.","vi":"Những cầu thủ tập luyện quá sức dễ tự gây chấn thương cho bản thân hơn."},{"en":"She injured her back while lifting heavy boxes at work.","vi":"Cô ấy bị chấn thương lưng khi nâng những thùng hàng nặng ở chỗ làm."}]','[{"phrase":"seriously injured"},{"phrase":"badly injured"},{"phrase":"injure yourself"}]','Danh từ: injury (chấn thương)','/ˈɪndʒər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inj/injur/injure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2811,'awl-2-02',1,'institute','viện; học viện','noun','[{"en":"She works as a researcher at a national institute of health.","vi":"Cô ấy làm nhà nghiên cứu tại một viện y tế quốc gia."},{"en":"The institute publishes a report on air quality every year.","vi":"Viện này công bố báo cáo về chất lượng không khí hằng năm."},{"en":"He studied computer science at an institute of technology in the capital.","vi":"Anh ấy học khoa học máy tính tại một học viện công nghệ ở thủ đô."}]','[{"phrase":"research institute"},{"phrase":"institute of technology"},{"phrase":"national institute"}]',NULL,'/ˈɪnstɪtuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insti/institute__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2812,'awl-2-02',2,'invest','đầu tư','verb','[{"en":"The government plans to invest heavily in renewable energy.","vi":"Chính phủ dự định đầu tư mạnh vào năng lượng tái tạo."},{"en":"Many companies invested billions in new technology last year.","vi":"Năm ngoái, nhiều công ty đã đầu tư hàng tỷ vào công nghệ mới."},{"en":"Schools should invest more time in training their teachers.","vi":"Các trường học nên đầu tư nhiều thời gian hơn vào việc đào tạo giáo viên."}]','[{"phrase":"invest in"},{"phrase":"invest heavily"},{"phrase":"invest money"},{"phrase":"invest time"}]','invest in + danh từ / V-ing','/ɪnˈvest/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/invest__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2813,'awl-2-02',3,'item','món; mặt hàng; mục','noun','[{"en":"Customers can return any item within thirty days of purchase.","vi":"Khách hàng có thể trả lại bất kỳ món hàng nào trong vòng ba mươi ngày kể từ khi mua."},{"en":"The first item on the agenda is the new budget.","vi":"Mục đầu tiên trong chương trình họp là ngân sách mới."},{"en":"Food prices rose sharply, especially for basic items like rice and oil.","vi":"Giá thực phẩm tăng mạnh, đặc biệt là các mặt hàng thiết yếu như gạo và dầu ăn."}]','[{"phrase":"item on the agenda"},{"phrase":"household items"},{"phrase":"individual items"}]',NULL,'/ˈaɪtəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ite/item_/item__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2814,'awl-2-02',4,'journal','tạp chí chuyên ngành; nhật ký','noun','[{"en":"The study was published in a leading medical journal.","vi":"Nghiên cứu này được đăng trên một tạp chí y khoa hàng đầu."},{"en":"Most researchers try to publish their work in peer-reviewed journals.","vi":"Hầu hết các nhà nghiên cứu cố gắng đăng công trình của mình trên các tạp chí có phản biện."},{"en":"Students keep a journal to record what they learn each week.","vi":"Sinh viên viết nhật ký để ghi lại những gì họ học được mỗi tuần."}]','[{"phrase":"academic journal"},{"phrase":"medical journal"},{"phrase":"publish in a journal"},{"phrase":"keep a journal"}]',NULL,'/ˈdʒɜːrnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jou/journ/journal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2815,'awl-2-02',5,'maintain','duy trì; bảo dưỡng; khẳng định','verb','[{"en":"The company has maintained high standards of quality for decades.","vi":"Công ty đã duy trì tiêu chuẩn chất lượng cao trong nhiều thập kỷ."},{"en":"The city spends millions each year to maintain its roads.","vi":"Thành phố chi hàng triệu mỗi năm để bảo dưỡng đường sá."},{"en":"He has always maintained that he did nothing wrong.","vi":"Anh ấy luôn khẳng định rằng mình không làm gì sai."}]','[{"phrase":"maintain standards"},{"phrase":"maintain a balance"},{"phrase":"maintain contact"}]',NULL,'/meɪnˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/maint/maintain__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2816,'awl-2-02',6,'normal','bình thường','adjective','[{"en":"Test results showed that her blood pressure was normal.","vi":"Kết quả xét nghiệm cho thấy huyết áp của cô ấy bình thường."},{"en":"Under normal conditions, the process takes about two weeks.","vi":"Trong điều kiện bình thường, quy trình này mất khoảng hai tuần."},{"en":"It is perfectly normal to feel nervous before a job interview.","vi":"Cảm thấy lo lắng trước buổi phỏng vấn xin việc là hoàn toàn bình thường."}]','[{"phrase":"normal conditions"},{"phrase":"perfectly normal"},{"phrase":"return to normal"}]',NULL,'/ˈnɔːrml/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norma/normal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2817,'awl-2-02',7,'obtain','có được; thu được; xin được','verb','[{"en":"Researchers obtained the data from hospital records.","vi":"Các nhà nghiên cứu thu được dữ liệu từ hồ sơ bệnh viện."},{"en":"Foreign workers must obtain a work permit before starting their jobs.","vi":"Lao động nước ngoài phải xin được giấy phép lao động trước khi bắt đầu làm việc."},{"en":"Similar results were obtained in both experiments.","vi":"Cả hai thí nghiệm đều thu được kết quả tương tự."}]','[{"phrase":"obtain data"},{"phrase":"obtain information"},{"phrase":"obtain permission"},{"phrase":"obtain a permit"}]','trang trọng hơn get','/əbˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obt/obtai/obtain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2818,'awl-2-02',8,'participate','tham gia','verb','[{"en":"More than five hundred students participated in the survey.","vi":"Hơn năm trăm sinh viên đã tham gia cuộc khảo sát."},{"en":"Employees are encouraged to participate actively in team meetings.","vi":"Nhân viên được khuyến khích tích cực tham gia các cuộc họp nhóm."},{"en":"Would you like to participate in our research project?","vi":"Bạn có muốn tham gia dự án nghiên cứu của chúng tôi không?"}]','[{"phrase":"participate in"},{"phrase":"participate actively"},{"phrase":"participate fully"}]','participate in + danh từ / V-ing','/pɑːrˈtɪsɪpeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2819,'awl-2-02',9,'perceive','nhận thấy; coi là; nhìn nhận','verb','[{"en":"Many people perceive science as a difficult subject.","vi":"Nhiều người coi khoa học là một môn học khó."},{"en":"The company is widely perceived as a good place to work.","vi":"Công ty này được nhiều người nhìn nhận là một nơi làm việc tốt."},{"en":"Patients often perceive changes in their symptoms before doctors do.","vi":"Bệnh nhân thường nhận thấy những thay đổi trong triệu chứng của mình trước cả bác sĩ."}]','[{"phrase":"perceive as"},{"phrase":"widely perceived"},{"phrase":"perceived risk"}]','perceive A as B: coi A là B','/pərˈsiːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perce/perceive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2820,'awl-2-02',10,'positive','tích cực; khả quan; dương tính','adjective','[{"en":"The new policy has had a positive effect on staff morale.","vi":"Chính sách mới đã có tác động tích cực đến tinh thần nhân viên."},{"en":"Early results from the trial look very positive.","vi":"Kết quả ban đầu của cuộc thử nghiệm trông rất khả quan."},{"en":"Three members of the team tested positive for flu last week.","vi":"Tuần trước, ba thành viên trong nhóm có kết quả xét nghiệm dương tính với cúm."}]','[{"phrase":"positive effect"},{"phrase":"positive attitude"},{"phrase":"positive feedback"},{"phrase":"test positive"}]',NULL,'/ˈpɑːzətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posit/positive__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2821,'awl-2-02',11,'potential','tiềm năng; tiềm tàng; có thể xảy ra','adjective','[{"en":"The company is trying to attract potential customers through social media.","vi":"Công ty đang cố gắng thu hút khách hàng tiềm năng qua mạng xã hội."},{"en":"Scientists warned about the potential risks of the new drug.","vi":"Các nhà khoa học đã cảnh báo về những rủi ro tiềm tàng của loại thuốc mới."},{"en":"We need to identify potential problems before the project begins.","vi":"Chúng ta cần xác định những vấn đề có thể xảy ra trước khi dự án bắt đầu."}]','[{"phrase":"potential customers"},{"phrase":"potential risks"},{"phrase":"potential benefits"}]','cũng là danh từ: tiềm năng (have potential)','/pəˈtenʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pot/poten/potential__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2822,'awl-2-02',12,'previous','trước; trước đây; trước đó','adjective','[{"en":"Sales this year were higher than in the previous year.","vi":"Doanh số năm nay cao hơn so với năm trước."},{"en":"Unlike previous studies, this research focused on older adults.","vi":"Khác với các nghiên cứu trước đây, nghiên cứu này tập trung vào người cao tuổi."},{"en":"Applicants should have previous experience in customer service.","vi":"Ứng viên cần có kinh nghiệm trước đó trong lĩnh vực chăm sóc khách hàng."}]','[{"phrase":"previous year"},{"phrase":"previous studies"},{"phrase":"previous experience"}]',NULL,'/ˈpriːviəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/previ/previous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2823,'awl-2-02',13,'primary','chính; chủ yếu; tiểu học','adjective','[{"en":"The primary goal of the program is to reduce poverty.","vi":"Mục tiêu chính của chương trình là giảm nghèo."},{"en":"Poor diet is a primary cause of heart disease.","vi":"Chế độ ăn uống kém là một nguyên nhân chủ yếu gây bệnh tim."},{"en":"Most children in the country attend primary school until age eleven.","vi":"Hầu hết trẻ em ở nước này học tiểu học cho đến mười một tuổi."}]','[{"phrase":"primary goal"},{"phrase":"primary cause"},{"phrase":"primary school"},{"phrase":"primary source"}]',NULL,'/ˈpraɪmeri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prima/primary__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2824,'awl-2-02',14,'purchase','mua; mua sắm','verb','[{"en":"Tickets can be purchased online or at the station.","vi":"Vé có thể được mua trực tuyến hoặc tại nhà ga."},{"en":"The university purchased new equipment for its science laboratories.","vi":"Trường đại học đã mua thiết bị mới cho các phòng thí nghiệm khoa học."},{"en":"Many young people cannot afford to purchase a home.","vi":"Nhiều người trẻ không đủ khả năng mua nhà."}]','[{"phrase":"purchase goods"},{"phrase":"purchase equipment"},{"phrase":"purchase online"}]','trang trọng hơn buy; cũng là danh từ: sự mua','/ˈpɜːrtʃəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/purch/purchase__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2825,'awl-2-02',15,'range','loạt; phạm vi; khoảng','noun','[{"en":"The store offers a wide range of products at low prices.","vi":"Cửa hàng cung cấp rất nhiều loại sản phẩm với giá thấp."},{"en":"The report covers a range of topics, from health to education.","vi":"Báo cáo đề cập đến một loạt chủ đề, từ y tế đến giáo dục."},{"en":"Unfortunately, that hotel is outside our price range.","vi":"Tiếc là khách sạn đó nằm ngoài khoảng giá của chúng tôi."}]','[{"phrase":"wide range"},{"phrase":"price range"},{"phrase":"age range"}]','a range of + danh từ số nhiều','/reɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/range/range__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2826,'awl-2-02',16,'region','vùng; khu vực','noun','[{"en":"Coffee is grown mainly in the mountainous regions of the country.","vi":"Cà phê được trồng chủ yếu ở các vùng núi của đất nước."},{"en":"The storm caused serious damage across the whole region.","vi":"Cơn bão gây thiệt hại nghiêm trọng trên toàn khu vực."},{"en":"Which region has the highest rate of unemployment?","vi":"Khu vực nào có tỷ lệ thất nghiệp cao nhất?"}]','[{"phrase":"mountainous region"},{"phrase":"coastal region"},{"phrase":"border region"}]',NULL,'/ˈriːdʒən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regio/region__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2827,'awl-2-02',17,'regulate','điều tiết; quy định; điều chỉnh','verb','[{"en":"The government regulates the prices of electricity and water.","vi":"Chính phủ điều tiết giá điện và nước."},{"en":"New laws will regulate how companies use personal data.","vi":"Các luật mới sẽ quy định cách các công ty sử dụng dữ liệu cá nhân."},{"en":"Sweating helps the body regulate its temperature.","vi":"Đổ mồ hôi giúp cơ thể điều chỉnh nhiệt độ."}]','[{"phrase":"regulate prices"},{"phrase":"regulate temperature"},{"phrase":"strictly regulated"}]',NULL,'/ˈreɡjuleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regulate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2828,'awl-2-02',18,'relevant','liên quan; phù hợp','adjective','[{"en":"Please include only information that is relevant to the question.","vi":"Vui lòng chỉ đưa vào những thông tin liên quan đến câu hỏi."},{"en":"Candidates should have a degree in a relevant field.","vi":"Ứng viên cần có bằng cấp thuộc lĩnh vực liên quan."},{"en":"Are these old theories still relevant today?","vi":"Ngày nay, những lý thuyết cũ này có còn phù hợp không?"}]','[{"phrase":"relevant to"},{"phrase":"relevant information"},{"phrase":"highly relevant"},{"phrase":"relevant experience"}]','relevant to + danh từ','/ˈreləvənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relev/relevant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2829,'awl-2-02',19,'reside','cư trú; sinh sống','verb','[{"en":"Most of the survey participants reside in urban areas.","vi":"Phần lớn người tham gia khảo sát cư trú ở khu vực thành thị."},{"en":"Foreign students residing in the country must register with local authorities.","vi":"Sinh viên nước ngoài cư trú tại quốc gia này phải đăng ký với chính quyền địa phương."},{"en":"She has resided abroad for more than ten years.","vi":"Cô ấy đã sinh sống ở nước ngoài hơn mười năm."}]','[{"phrase":"reside in"},{"phrase":"reside abroad"},{"phrase":"currently reside"}]','trang trọng hơn live; reside in + nơi chốn','/rɪˈzaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resid/reside__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2830,'awl-2-02',20,'resource','tài nguyên; nguồn lực','noun','[{"en":"The country is rich in natural resources such as oil and gas.","vi":"Đất nước này giàu tài nguyên thiên nhiên như dầu mỏ và khí đốt."},{"en":"Small schools often lack the resources to support every student.","vi":"Các trường nhỏ thường thiếu nguồn lực để hỗ trợ mọi học sinh."},{"en":"We should use our limited resources more efficiently.","vi":"Chúng ta nên sử dụng nguồn lực hạn chế của mình hiệu quả hơn."}]','[{"phrase":"natural resources"},{"phrase":"limited resources"},{"phrase":"human resources"},{"phrase":"allocate resources"}]',NULL,'/ˈriːsɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resou/resource__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2831,'awl-2-02',21,'restrict','hạn chế; giới hạn','verb','[{"en":"The new law restricts the sale of alcohol near schools.","vi":"Luật mới hạn chế việc bán rượu bia gần trường học."},{"en":"Access to the laboratory is restricted to authorized staff.","vi":"Quyền vào phòng thí nghiệm chỉ giới hạn cho nhân viên được cấp phép."},{"en":"Doctors advised him to restrict the amount of salt he eats.","vi":"Bác sĩ khuyên anh ấy hạn chế lượng muối ăn vào."}]','[{"phrase":"restrict access"},{"phrase":"severely restrict"},{"phrase":"restricted to"}]','restrict something to: giới hạn trong phạm vi','/rɪˈstrɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restrict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2832,'awl-2-02',22,'secure','an toàn; bảo mật; ổn định','adjective','[{"en":"Customers want to know that their personal data is secure.","vi":"Khách hàng muốn biết rằng dữ liệu cá nhân của họ được bảo mật."},{"en":"Many young graduates struggle to find secure employment.","vi":"Nhiều sinh viên mới tốt nghiệp chật vật để tìm được việc làm ổn định."},{"en":"Keep your passwords in a secure place.","vi":"Hãy cất giữ mật khẩu của bạn ở một nơi an toàn."}]','[{"phrase":"secure place"},{"phrase":"secure employment"},{"phrase":"financially secure"}]','cũng là động từ: giành được (secure funding)','/sɪˈkjʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secur/secure__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2833,'awl-2-02',23,'seek','tìm kiếm; tìm cách','verb','[{"en":"Many graduates seek jobs abroad after finishing their studies.","vi":"Nhiều sinh viên tốt nghiệp tìm việc làm ở nước ngoài sau khi học xong."},{"en":"You should seek advice from a lawyer before signing the contract.","vi":"Bạn nên tìm lời khuyên từ luật sư trước khi ký hợp đồng."},{"en":"The study sought to explain why some students drop out.","vi":"Nghiên cứu này tìm cách lý giải vì sao một số sinh viên bỏ học."}]','[{"phrase":"seek advice"},{"phrase":"seek help"},{"phrase":"seek to"},{"phrase":"seek employment"}]','seek – sought – sought','/siːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/see/seek_/seek__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2834,'awl-2-02',24,'select','chọn; lựa chọn; tuyển chọn','verb','[{"en":"Participants were selected at random from the local population.","vi":"Những người tham gia được chọn ngẫu nhiên từ dân cư địa phương."},{"en":"Only ten students were selected for the scholarship program.","vi":"Chỉ có mười sinh viên được tuyển chọn vào chương trình học bổng."},{"en":"Please select your preferred language from the list below.","vi":"Vui lòng chọn ngôn ngữ bạn muốn từ danh sách bên dưới."}]','[{"phrase":"selected at random"},{"phrase":"carefully selected"},{"phrase":"select from"}]',NULL,'/sɪˈlekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sel/selec/select__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2835,'awl-2-02',25,'site','địa điểm; công trường; trang web','noun','[{"en":"Workers must wear helmets at all times on the construction site.","vi":"Công nhân phải luôn đội mũ bảo hộ tại công trường xây dựng."},{"en":"The city has chosen a site for the new hospital.","vi":"Thành phố đã chọn được địa điểm cho bệnh viện mới."},{"en":"You can download the full report from our site.","vi":"Bạn có thể tải toàn bộ báo cáo từ trang web của chúng tôi."}]','[{"phrase":"construction site"},{"phrase":"historic site"},{"phrase":"on site"}]','site ≠ sight (cảnh, tầm nhìn)','/saɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/site_/site__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2836,'awl-2-02',26,'strategy','chiến lược','noun','[{"en":"The company needs a clear strategy to compete in foreign markets.","vi":"Công ty cần một chiến lược rõ ràng để cạnh tranh ở thị trường nước ngoài."},{"en":"Teachers used different strategies to help weaker students.","vi":"Giáo viên đã áp dụng nhiều chiến lược khác nhau để giúp đỡ học sinh yếu."},{"en":"The government has developed a national strategy for reducing waste.","vi":"Chính phủ đã xây dựng một chiến lược quốc gia nhằm giảm rác thải."}]','[{"phrase":"develop a strategy"},{"phrase":"clear strategy"},{"phrase":"marketing strategy"},{"phrase":"long-term strategy"}]',NULL,'/ˈstrætədʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strat/strategy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2837,'awl-2-02',27,'survey','cuộc khảo sát; cuộc điều tra','noun','[{"en":"A recent survey found that most employees prefer flexible hours.","vi":"Một cuộc khảo sát gần đây cho thấy phần lớn nhân viên thích giờ làm việc linh hoạt."},{"en":"We conducted a survey of two thousand households.","vi":"Chúng tôi đã tiến hành khảo sát hai nghìn hộ gia đình."},{"en":"Please take a few minutes to complete this short survey.","vi":"Vui lòng dành vài phút để hoàn thành bản khảo sát ngắn này."}]','[{"phrase":"conduct a survey"},{"phrase":"recent survey"},{"phrase":"complete a survey"}]',NULL,'/ˈsɜːrveɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surve/survey__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2838,'awl-2-02',28,'text','văn bản; bài đọc; tin nhắn','noun','[{"en":"The full text of the agreement is available online.","vi":"Toàn bộ văn bản thỏa thuận được đăng tải trực tuyến."},{"en":"Students should read the text carefully before answering the questions.","vi":"Học sinh nên đọc kỹ bài đọc trước khi trả lời câu hỏi."},{"en":"I sent her a text to say I would be late.","vi":"Tôi đã nhắn tin cho cô ấy để báo rằng tôi sẽ đến muộn."}]','[{"phrase":"full text"},{"phrase":"send a text"},{"phrase":"text message"}]',NULL,'/tekst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tex/text_/text__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2839,'awl-2-02',29,'tradition','truyền thống','noun','[{"en":"The festival is an important tradition in many Asian countries.","vi":"Lễ hội này là một truyền thống quan trọng ở nhiều nước châu Á."},{"en":"The university has a long tradition of academic excellence.","vi":"Trường đại học này có truyền thống lâu đời về thành tích học thuật xuất sắc."},{"en":"By tradition, the whole family gathers for a big meal at New Year.","vi":"Theo truyền thống, cả gia đình quây quần bên bữa cơm lớn vào dịp năm mới."}]','[{"phrase":"long tradition"},{"phrase":"cultural tradition"},{"phrase":"by tradition"},{"phrase":"follow a tradition"}]',NULL,'/trəˈdɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/tradi/tradition__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2840,'awl-2-02',30,'transfer','chuyển; chuyển giao; điều chuyển','verb','[{"en":"Money can be transferred between accounts in a few seconds.","vi":"Tiền có thể được chuyển giữa các tài khoản chỉ trong vài giây."},{"en":"After two years, she was transferred to the company''s overseas office.","vi":"Sau hai năm, cô ấy được điều chuyển sang văn phòng ở nước ngoài của công ty."},{"en":"The project aims to transfer new farming technology to rural communities.","vi":"Dự án nhằm chuyển giao công nghệ canh tác mới cho các cộng đồng nông thôn."}]','[{"phrase":"transfer money"},{"phrase":"transfer data"},{"phrase":"transfer technology"},{"phrase":"transfer to"}]','transfer – transferred (gấp đôi r)','/trænsˈfɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transfer__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2841,'awl-3-01',1,'alternative','lựa chọn khác; phương án thay thế','noun','[{"en":"Solar power offers a cleaner alternative to coal.","vi":"Năng lượng mặt trời mang lại một lựa chọn sạch hơn thay cho than đá."},{"en":"If the plan fails, we will need an alternative.","vi":"Nếu kế hoạch thất bại, chúng ta sẽ cần một phương án khác."},{"en":"The committee rejected both alternatives proposed by the consultants.","vi":"Ủy ban đã bác bỏ cả hai phương án do các chuyên gia tư vấn đề xuất."}]','[{"phrase":"alternative to"},{"phrase":"viable alternative"},{"phrase":"offer an alternative"}]',NULL,'/ɔːlˈtɜːrnətɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alternative__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2842,'awl-3-01',2,'circumstance','hoàn cảnh; tình huống','noun','[{"en":"Under no circumstances should staff share their passwords.","vi":"Trong bất kỳ hoàn cảnh nào, nhân viên cũng không được chia sẻ mật khẩu."},{"en":"The meeting was postponed due to unforeseen circumstances.","vi":"Cuộc họp bị hoãn do những tình huống không lường trước được."},{"en":"Students in difficult financial circumstances can apply for extra support.","vi":"Sinh viên có hoàn cảnh tài chính khó khăn có thể nộp đơn xin hỗ trợ thêm."}]','[{"phrase":"under no circumstances"},{"phrase":"unforeseen circumstances"},{"phrase":"financial circumstances"}]','thường dùng ở số nhiều: circumstances','/ˈsɜːrkəmstæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cir/circu/circumstance__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2843,'awl-3-01',3,'comment','lời bình luận; nhận xét','noun','[{"en":"Thank you for your helpful comments on my draft.","vi":"Cảm ơn những nhận xét hữu ích của bạn về bản nháp của tôi."},{"en":"The company made no comment on reports of job cuts.","vi":"Công ty không đưa ra bình luận nào về các tin tức cắt giảm việc làm."},{"en":"Several readers left comments below the online article.","vi":"Một số độc giả đã để lại bình luận bên dưới bài báo trực tuyến."}]','[{"phrase":"make a comment"},{"phrase":"comment on"},{"phrase":"no comment"},{"phrase":"leave a comment"}]',NULL,'/ˈkɑːment/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/comment__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2844,'awl-3-01',4,'compensate','bồi thường; bù đắp','verb','[{"en":"The airline agreed to compensate passengers for the delay.","vi":"Hãng hàng không đồng ý bồi thường cho hành khách vì chuyến bay bị trễ."},{"en":"Workers must be compensated for any injuries suffered on the job.","vi":"Người lao động phải được bồi thường cho mọi chấn thương gặp phải khi làm việc."},{"en":"Strong exports helped compensate for weak domestic demand.","vi":"Xuất khẩu mạnh đã giúp bù đắp cho nhu cầu trong nước yếu."}]','[{"phrase":"compensate for"},{"phrase":"fully compensate"},{"phrase":"compensate victims"}]','compensate (sb) for sth','/ˈkɑːmpenseɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/compensate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2845,'awl-3-01',5,'component','thành phần; bộ phận; linh kiện','noun','[{"en":"Trust is a key component of any successful team.","vi":"Sự tin tưởng là một thành phần then chốt của bất kỳ nhóm thành công nào."},{"en":"The factory produces electronic components for mobile phones.","vi":"Nhà máy sản xuất linh kiện điện tử cho điện thoại di động."},{"en":"The course has three components: lectures, seminars and a final project.","vi":"Khóa học có ba thành phần: bài giảng, buổi thảo luận và một dự án cuối kỳ."}]','[{"phrase":"key component"},{"phrase":"essential component"},{"phrase":"electronic components"}]',NULL,'/kəmˈpəʊnənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/component__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2846,'awl-3-01',6,'consent','sự đồng ý; sự cho phép','noun','[{"en":"Researchers must obtain written consent from all participants.","vi":"Các nhà nghiên cứu phải có được sự đồng ý bằng văn bản của tất cả người tham gia."},{"en":"Your data will not be shared without your consent.","vi":"Dữ liệu của bạn sẽ không được chia sẻ khi chưa có sự đồng ý của bạn."},{"en":"Parents must give consent before their children join the study.","vi":"Phụ huynh phải cho phép trước khi con em họ tham gia nghiên cứu."}]','[{"phrase":"give consent"},{"phrase":"written consent"},{"phrase":"informed consent"},{"phrase":"without consent"}]','không đếm được','/kənˈsent/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2847,'awl-3-01',7,'considerable','đáng kể; lớn','adjective','[{"en":"The project has attracted considerable interest from investors.","vi":"Dự án đã thu hút sự quan tâm đáng kể từ các nhà đầu tư."},{"en":"Building the new bridge will take a considerable amount of time.","vi":"Việc xây cây cầu mới sẽ mất một khoảng thời gian đáng kể."},{"en":"There is considerable evidence that exercise improves memory.","vi":"Có khá nhiều bằng chứng cho thấy tập thể dục giúp cải thiện trí nhớ."}]','[{"phrase":"considerable amount"},{"phrase":"considerable interest"},{"phrase":"considerable evidence"},{"phrase":"to a considerable extent"}]','considerable (đáng kể) ≠ considerate (chu đáo)','/kənˈsɪdərəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsiderable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2848,'awl-3-01',8,'constant','liên tục; không đổi','adjective','[{"en":"The samples must be stored at a constant temperature.","vi":"Các mẫu phải được bảo quản ở nhiệt độ không đổi."},{"en":"Small businesses face constant pressure to cut costs.","vi":"Các doanh nghiệp nhỏ liên tục chịu áp lực phải cắt giảm chi phí."},{"en":"Prices remained constant throughout the first half of the year.","vi":"Giá cả giữ nguyên không đổi trong suốt nửa đầu năm."}]','[{"phrase":"constant temperature"},{"phrase":"constant pressure"},{"phrase":"remain constant"},{"phrase":"constant change"}]',NULL,'/ˈkɑːnstənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2849,'awl-3-01',9,'constrain','hạn chế; kìm hãm; ràng buộc','verb','[{"en":"Growth has been constrained by a shortage of skilled workers.","vi":"Tăng trưởng đã bị kìm hãm do thiếu lao động có tay nghề."},{"en":"A small budget constrains what the research team can achieve.","vi":"Ngân sách ít ỏi hạn chế những gì nhóm nghiên cứu có thể đạt được."},{"en":"Many farmers feel constrained by strict environmental rules.","vi":"Nhiều nông dân cảm thấy bị ràng buộc bởi các quy định môi trường nghiêm ngặt."}]','[{"phrase":"constrain growth"},{"phrase":"be constrained by"},{"phrase":"severely constrain"}]',NULL,'/kənˈstreɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstrain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2850,'awl-3-01',10,'contribute','đóng góp; góp phần','verb','[{"en":"Everyone is encouraged to contribute ideas during the meeting.","vi":"Mọi người được khuyến khích đóng góp ý kiến trong cuộc họp."},{"en":"Poor diet can contribute to heart disease.","vi":"Chế độ ăn uống kém có thể góp phần gây ra bệnh tim."},{"en":"Several local companies contributed funds to the new library.","vi":"Một số công ty địa phương đã đóng góp kinh phí cho thư viện mới."}]','[{"phrase":"contribute to"},{"phrase":"contribute significantly"},{"phrase":"contribute funds"}]','contribute to sth','/kənˈtrɪbjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontribute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2851,'awl-3-01',11,'convene','triệu tập; nhóm họp','verb','[{"en":"The director plans to convene a meeting with all department heads.","vi":"Giám đốc dự định triệu tập một cuộc họp với tất cả các trưởng phòng."},{"en":"The board will convene next week to discuss the budget.","vi":"Hội đồng quản trị sẽ nhóm họp vào tuần tới để thảo luận về ngân sách."},{"en":"An emergency meeting was convened after the data breach.","vi":"Một cuộc họp khẩn cấp đã được triệu tập sau vụ rò rỉ dữ liệu."}]','[{"phrase":"convene a meeting"},{"phrase":"convene a conference"},{"phrase":"convene a panel"}]',NULL,'/kənˈviːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvene__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2852,'awl-3-01',12,'coordinate','điều phối; phối hợp','verb','[{"en":"She coordinates volunteer programs across three hospitals.","vi":"Cô ấy điều phối các chương trình tình nguyện tại ba bệnh viện."},{"en":"Emergency services must coordinate their efforts during a flood.","vi":"Các lực lượng cứu hộ phải phối hợp nỗ lực trong lúc xảy ra lũ lụt."},{"en":"Our team will coordinate with the sales department on the launch.","vi":"Nhóm chúng tôi sẽ phối hợp với phòng kinh doanh trong đợt ra mắt sản phẩm."}]','[{"phrase":"coordinate efforts"},{"phrase":"coordinate with"},{"phrase":"coordinate activities"}]',NULL,'/kəʊˈɔːrdɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/coord/coordinate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2853,'awl-3-01',13,'core','cốt lõi; chủ chốt; chính','adjective','[{"en":"Honesty is one of the company''s core values.","vi":"Trung thực là một trong những giá trị cốt lõi của công ty."},{"en":"Math and English are core subjects in most schools.","vi":"Toán và tiếng Anh là các môn học chính ở hầu hết các trường."},{"en":"The firm decided to focus on its core business.","vi":"Công ty quyết định tập trung vào mảng kinh doanh cốt lõi của mình."}]','[{"phrase":"core values"},{"phrase":"core business"},{"phrase":"core subjects"}]',NULL,'/kɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/core_/core__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2854,'awl-3-01',14,'corporate','thuộc doanh nghiệp; của công ty','adjective','[{"en":"More companies now publish reports on corporate social responsibility.","vi":"Ngày càng nhiều công ty công bố báo cáo về trách nhiệm xã hội của doanh nghiệp."},{"en":"The firm has moved its corporate headquarters to the city center.","vi":"Công ty đã chuyển trụ sở chính về trung tâm thành phố."},{"en":"The government lowered the corporate tax rate to attract foreign investment.","vi":"Chính phủ đã hạ mức thuế doanh nghiệp để thu hút đầu tư nước ngoài."}]','[{"phrase":"corporate headquarters"},{"phrase":"corporate culture"},{"phrase":"corporate social responsibility"},{"phrase":"corporate tax"}]',NULL,'/ˈkɔːrpərət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corpo/corporate__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2855,'awl-3-01',15,'correspond','tương ứng; phù hợp; trao đổi thư từ','verb','[{"en":"The numbers on the map correspond to the photos below.","vi":"Các con số trên bản đồ tương ứng với các bức ảnh bên dưới."},{"en":"His account of events does not correspond with the evidence.","vi":"Lời kể của anh ta về sự việc không phù hợp với bằng chứng."},{"en":"The two researchers corresponded by email for several years.","vi":"Hai nhà nghiên cứu đã trao đổi thư từ qua email trong nhiều năm."}]','[{"phrase":"correspond to"},{"phrase":"correspond with"},{"phrase":"correspond closely"}]',NULL,'/ˌkɔːrəˈspɑːnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corre/correspond__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2856,'awl-3-01',16,'criteria','tiêu chí; tiêu chuẩn','noun','[{"en":"Applicants must meet all the criteria listed below.","vi":"Ứng viên phải đáp ứng tất cả các tiêu chí được liệt kê dưới đây."},{"en":"What criteria did the judges use to choose the winner?","vi":"Ban giám khảo đã dùng những tiêu chí nào để chọn người chiến thắng?"},{"en":"The study used strict criteria for selecting participants.","vi":"Nghiên cứu đã áp dụng các tiêu chí nghiêm ngặt để chọn người tham gia."}]','[{"phrase":"meet the criteria"},{"phrase":"strict criteria"},{"phrase":"selection criteria"}]','số nhiều của criterion','/kraɪˈtɪriːə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2857,'awl-3-01',17,'deduce','suy ra; suy luận','verb','[{"en":"From the data, we can deduce that sales peak in December.","vi":"Từ dữ liệu, chúng ta có thể suy ra rằng doanh số đạt đỉnh vào tháng Mười Hai."},{"en":"Doctors deduced the cause of the illness from the patient''s symptoms.","vi":"Các bác sĩ đã suy ra nguyên nhân gây bệnh từ các triệu chứng của bệnh nhân."},{"en":"It is difficult to deduce much from such a small sample.","vi":"Thật khó suy ra được nhiều điều từ một mẫu nhỏ như vậy."}]','[{"phrase":"deduce from"},{"phrase":"deduce that"}]','deduce sth from sth','/dɪˈduːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/ded/deduc/deduce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2858,'awl-3-01',18,'demonstrate','chứng minh; cho thấy; trình diễn','verb','[{"en":"The study demonstrates a clear link between sleep and memory.","vi":"Nghiên cứu cho thấy mối liên hệ rõ ràng giữa giấc ngủ và trí nhớ."},{"en":"The trainer demonstrated how to use the new software.","vi":"Người hướng dẫn đã trình diễn cách sử dụng phần mềm mới."},{"en":"Candidates must demonstrate strong communication skills during the interview.","vi":"Ứng viên phải chứng minh được kỹ năng giao tiếp tốt trong buổi phỏng vấn."}]','[{"phrase":"clearly demonstrate"},{"phrase":"demonstrate how"},{"phrase":"demonstrate skills"}]',NULL,'/ˈdemənstreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dem/demon/demonstrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2859,'awl-3-01',19,'document','tài liệu; văn bản; giấy tờ','noun','[{"en":"Please bring all the necessary documents to the interview.","vi":"Vui lòng mang theo tất cả giấy tờ cần thiết đến buổi phỏng vấn."},{"en":"She saved the document before closing her laptop.","vi":"Cô ấy đã lưu tài liệu trước khi đóng máy tính xách tay."},{"en":"This official document describes the new safety procedures.","vi":"Văn bản chính thức này mô tả các quy trình an toàn mới."}]','[{"phrase":"official document"},{"phrase":"legal document"},{"phrase":"sign a document"}]',NULL,'/ˈdɑːkjumənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doc/docum/document__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2860,'awl-3-01',20,'dominate','thống trị; chiếm ưu thế; chi phối','verb','[{"en":"A few large firms dominate the global smartphone market.","vi":"Một vài công ty lớn thống trị thị trường điện thoại thông minh toàn cầu."},{"en":"Climate change dominated discussions at this year''s conference.","vi":"Biến đổi khí hậu chi phối các cuộc thảo luận tại hội nghị năm nay."},{"en":"Service industries now dominate the economy of most developed countries.","vi":"Ngành dịch vụ hiện chiếm ưu thế trong nền kinh tế của hầu hết các nước phát triển."}]','[{"phrase":"dominate the market"},{"phrase":"dominate the economy"},{"phrase":"dominate the debate"}]',NULL,'/ˈdɑːmɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domin/dominate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2861,'awl-3-01',21,'emphasis','sự nhấn mạnh; sự chú trọng','noun','[{"en":"The new curriculum places greater emphasis on practical skills.","vi":"Chương trình học mới chú trọng hơn vào các kỹ năng thực hành."},{"en":"Many teachers feel there is too much emphasis on exam results.","vi":"Nhiều giáo viên cảm thấy việc chú trọng vào kết quả thi cử là quá mức."},{"en":"The speaker repeated her final point for emphasis.","vi":"Diễn giả đã nhắc lại ý cuối cùng để nhấn mạnh."}]','[{"phrase":"place emphasis on"},{"phrase":"strong emphasis"},{"phrase":"for emphasis"}]','emphasis on sth · động từ: emphasize','/ˈemfəsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empha/emphasis__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2862,'awl-3-01',22,'ensure','đảm bảo','verb','[{"en":"Please ensure that all doors are locked before leaving.","vi":"Vui lòng đảm bảo rằng tất cả các cửa đã được khóa trước khi rời đi."},{"en":"Regular testing ensures the quality of the final product.","vi":"Việc kiểm tra thường xuyên đảm bảo chất lượng của sản phẩm cuối cùng."},{"en":"The new law aims to ensure equal pay for all workers.","vi":"Luật mới nhằm đảm bảo trả lương bình đẳng cho mọi người lao động."}]','[{"phrase":"ensure that"},{"phrase":"ensure quality"},{"phrase":"ensure safety"}]','ensure (đảm bảo) ≠ insure (bảo hiểm)','/ɪnˈʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ens/ensur/ensure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2863,'awl-3-01',23,'exclude','loại trừ; không bao gồm','verb','[{"en":"Patients over 65 were excluded from the study.","vi":"Bệnh nhân trên 65 tuổi đã bị loại khỏi nghiên cứu."},{"en":"The price excludes tax and delivery charges.","vi":"Giá này chưa bao gồm thuế và phí giao hàng."},{"en":"We cannot exclude the possibility of further delays.","vi":"Chúng tôi không thể loại trừ khả năng sẽ còn chậm trễ thêm."}]','[{"phrase":"exclude from"},{"phrase":"exclude the possibility"}]','exclude sb/sth from sth','/ɪkˈskluːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/exclu/exclude__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2864,'awl-3-01',24,'framework','khuôn khổ; khung','noun','[{"en":"The report provides a framework for future research.","vi":"Báo cáo đưa ra một khuôn khổ cho các nghiên cứu trong tương lai."},{"en":"Countries agreed on a legal framework to protect ocean life.","vi":"Các quốc gia đã thống nhất một khung pháp lý để bảo vệ sinh vật biển."},{"en":"Students can use this framework to organize their essays.","vi":"Sinh viên có thể dùng khung này để sắp xếp bố cục bài luận."}]','[{"phrase":"legal framework"},{"phrase":"theoretical framework"},{"phrase":"provide a framework"},{"phrase":"framework for"}]',NULL,'/ˈfreɪmwɜːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/frame/framework__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2865,'awl-3-01',25,'fund','quỹ; kinh phí','noun','[{"en":"The school set up a fund to help students buy books.","vi":"Nhà trường đã lập một quỹ để giúp học sinh mua sách."},{"en":"The project was canceled because of a lack of funds.","vi":"Dự án đã bị hủy do thiếu kinh phí."},{"en":"The charity is raising funds for a new children''s hospital.","vi":"Tổ chức từ thiện đang gây quỹ cho một bệnh viện nhi mới."}]','[{"phrase":"raise funds"},{"phrase":"set up a fund"},{"phrase":"lack of funds"},{"phrase":"public funds"}]','cũng là động từ: fund (tài trợ)','/fʌnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/fund_/fund__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2866,'awl-3-01',26,'illustrate','minh họa; làm rõ','verb','[{"en":"The chart illustrates how prices have changed since 2010.","vi":"Biểu đồ minh họa giá cả đã thay đổi như thế nào kể từ năm 2010."},{"en":"Let me give an example to illustrate this point.","vi":"Để tôi đưa ra một ví dụ để làm rõ điểm này."},{"en":"The book is illustrated with photos taken by local students.","vi":"Cuốn sách được minh họa bằng những bức ảnh do học sinh địa phương chụp."}]','[{"phrase":"illustrate the point"},{"phrase":"clearly illustrate"},{"phrase":"illustrate how"}]',NULL,'/ˈɪləstreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ill/illus/illustrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2867,'awl-3-01',27,'immigrate','nhập cư','verb','[{"en":"Her grandparents immigrated to Canada in the 1960s.","vi":"Ông bà của cô ấy đã nhập cư vào Canada trong những năm 1960."},{"en":"Many skilled workers immigrate to find better job opportunities.","vi":"Nhiều lao động có tay nghề nhập cư để tìm kiếm cơ hội việc làm tốt hơn."},{"en":"Families who immigrate often face challenges with language and housing.","vi":"Những gia đình nhập cư thường gặp khó khăn về ngôn ngữ và nhà ở."}]','[{"phrase":"immigrate to"},{"phrase":"immigrate from"}]','immigrate (nhập cư vào) ≠ emigrate (di cư khỏi)','/ˈɪmɪɡreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immig/immigrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2868,'awl-3-01',28,'imply','ngụ ý; hàm ý','verb','[{"en":"The results imply that the treatment is less effective in older patients.","vi":"Kết quả hàm ý rằng phương pháp điều trị kém hiệu quả hơn ở bệnh nhân lớn tuổi."},{"en":"Are you implying that I made a mistake?","vi":"Có phải bạn đang ngụ ý rằng tôi đã mắc lỗi không?"},{"en":"A rise in prices does not necessarily imply higher profits.","vi":"Giá tăng không nhất thiết hàm ý lợi nhuận cao hơn."}]','[{"phrase":"imply that"},{"phrase":"strongly imply"},{"phrase":"necessarily imply"}]','imply (ngụ ý) ≠ infer (suy ra)','/ɪmˈplaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imply/imply__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2869,'awl-3-01',29,'initial','ban đầu; đầu tiên','adjective','[{"en":"Initial results from the trial look very promising.","vi":"Kết quả ban đầu của cuộc thử nghiệm trông rất khả quan."},{"en":"My initial reaction was surprise, but I soon agreed.","vi":"Phản ứng đầu tiên của tôi là ngạc nhiên, nhưng tôi đã sớm đồng ý."},{"en":"The initial cost is high, but the system saves money later.","vi":"Chi phí ban đầu cao, nhưng về sau hệ thống sẽ giúp tiết kiệm tiền."}]','[{"phrase":"initial results"},{"phrase":"initial stage"},{"phrase":"initial reaction"},{"phrase":"initial cost"}]',NULL,'/ɪˈnɪʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2870,'awl-3-01',30,'instance','trường hợp; ví dụ','noun','[{"en":"Many jobs now require coding skills, for instance in banking and finance.","vi":"Nhiều công việc hiện nay đòi hỏi kỹ năng lập trình, chẳng hạn trong ngành ngân hàng và tài chính."},{"en":"There have been several instances of fraud this year.","vi":"Năm nay đã có một vài trường hợp gian lận."},{"en":"In this instance, the company agreed to refund the full amount.","vi":"Trong trường hợp này, công ty đã đồng ý hoàn lại toàn bộ số tiền."}]','[{"phrase":"for instance"},{"phrase":"in this instance"},{"phrase":"instances of"}]',NULL,'/ˈɪnstəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insta/instance__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2871,'awl-3-02',1,'interact','tương tác; giao tiếp','verb','[{"en":"Children learn social skills by interacting with other children.","vi":"Trẻ em học các kỹ năng xã hội thông qua việc giao tiếp với những đứa trẻ khác."},{"en":"Scientists studied how the two drugs interact in the body.","vi":"Các nhà khoa học đã nghiên cứu cách hai loại thuốc tương tác với nhau trong cơ thể."},{"en":"Online courses give students fewer chances to interact with their teachers.","vi":"Các khóa học trực tuyến mang lại cho sinh viên ít cơ hội giao tiếp với giáo viên hơn."}]','[{"phrase":"interact with"},{"phrase":"interact socially"},{"phrase":"interact closely"}]','interact with + người/vật','/ˌɪntərˈækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interact__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2872,'awl-3-02',2,'justify','biện minh; chứng minh là đúng','verb','[{"en":"Managers must justify any increase in spending to the board.","vi":"Các nhà quản lý phải giải trình mọi khoản chi tiêu tăng thêm trước hội đồng quản trị."},{"en":"The results do not justify such a high level of investment.","vi":"Kết quả này không đủ để chứng minh mức đầu tư cao như vậy là hợp lý."},{"en":"How can the company justify closing a factory that still makes a profit?","vi":"Làm sao công ty có thể biện minh cho việc đóng cửa một nhà máy vẫn đang có lãi?"}]','[{"phrase":"justify a decision"},{"phrase":"justify the cost"},{"phrase":"difficult to justify"}]','justify + V-ing / danh từ','/ˈdʒʌstɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jus/justi/justify__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2873,'awl-3-02',3,'layer','lớp; tầng','noun','[{"en":"A thin layer of dust covered the old documents.","vi":"Một lớp bụi mỏng phủ lên những tài liệu cũ."},{"en":"The ozone layer protects the earth from harmful radiation.","vi":"Tầng ô-dôn bảo vệ trái đất khỏi bức xạ có hại."},{"en":"Each new layer of management made decisions slower.","vi":"Mỗi tầng quản lý mới lại khiến việc ra quyết định chậm hơn."}]','[{"phrase":"a thin layer"},{"phrase":"the ozone layer"},{"phrase":"layer of"},{"phrase":"outer layer"}]',NULL,'/ˈleɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lay/layer/layer__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2874,'awl-3-02',4,'link','liên kết; mối liên hệ; đường dẫn','noun','[{"en":"Researchers found a strong link between smoking and heart disease.","vi":"Các nhà nghiên cứu đã tìm thấy mối liên hệ chặt chẽ giữa hút thuốc và bệnh tim."},{"en":"The new railway provides a direct link between the two cities.","vi":"Tuyến đường sắt mới tạo ra một tuyến kết nối trực tiếp giữa hai thành phố."},{"en":"Please click the link in the email to complete your registration.","vi":"Vui lòng nhấp vào đường dẫn trong email để hoàn tất việc đăng ký."}]','[{"phrase":"link between"},{"phrase":"a strong link"},{"phrase":"a direct link"},{"phrase":"click the link"}]','link between A and B','/lɪŋk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lin/link_/link__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2875,'awl-3-02',5,'locate','xác định vị trí; đặt ở (vị trí)','verb','[{"en":"Engineers were unable to locate the source of the problem.","vi":"Các kỹ sư không thể xác định được nguồn gốc của vấn đề."},{"en":"The company''s head office is located in the city center.","vi":"Trụ sở chính của công ty nằm ở trung tâm thành phố."},{"en":"Many firms choose to locate near universities to attract skilled workers.","vi":"Nhiều công ty chọn đặt trụ sở gần các trường đại học để thu hút lao động có tay nghề."}]','[{"phrase":"be located in"},{"phrase":"locate the source"},{"phrase":"conveniently located"}]','be located in/at/near = nằm ở','/ˈləʊkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/locat/locate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2876,'awl-3-02',6,'maximise','tối đa hóa; tận dụng tối đa','verb','[{"en":"Most businesses aim to maximise profits while keeping costs low.","vi":"Hầu hết các doanh nghiệp đều hướng tới tối đa hóa lợi nhuận trong khi giữ chi phí thấp."},{"en":"The office was redesigned to maximise the use of natural light.","vi":"Văn phòng được thiết kế lại để tận dụng tối đa ánh sáng tự nhiên."},{"en":"Farmers are testing new methods to maximise crop yields.","vi":"Nông dân đang thử nghiệm các phương pháp mới để tối đa hóa năng suất cây trồng."}]','[{"phrase":"maximise profits"},{"phrase":"maximise the use of"},{"phrase":"maximise efficiency"}]','Anh: maximise · Mỹ: maximize',NULL,NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2877,'awl-3-02',7,'minor','nhỏ; không quan trọng; thứ yếu','adjective','[{"en":"The report contains only a few minor errors.","vi":"Bản báo cáo chỉ có một vài lỗi nhỏ."},{"en":"Most patients experienced only minor side effects from the treatment.","vi":"Phần lớn bệnh nhân chỉ gặp những tác dụng phụ nhẹ từ phương pháp điều trị."},{"en":"Price played a minor role in customers'' decisions.","vi":"Giá cả chỉ đóng vai trò thứ yếu trong quyết định của khách hàng."}]','[{"phrase":"minor changes"},{"phrase":"minor problem"},{"phrase":"a minor role"},{"phrase":"minor injuries"}]','minor ≠ major','/ˈmaɪnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minor/minor__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2878,'awl-3-02',8,'negate','vô hiệu hóa; phủ nhận','verb','[{"en":"Rising costs could negate the benefits of the new system.","vi":"Chi phí tăng cao có thể làm mất đi lợi ích của hệ thống mới."},{"en":"One poor decision can negate years of careful planning.","vi":"Một quyết định tồi có thể vô hiệu hóa nhiều năm lên kế hoạch cẩn thận."},{"en":"The new evidence does not negate the earlier findings.","vi":"Bằng chứng mới không phủ nhận những phát hiện trước đó."}]','[{"phrase":"negate the effect"},{"phrase":"negate the benefits"},{"phrase":"negate the need"}]',NULL,'/nɪˈɡeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negat/negate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2879,'awl-3-02',9,'outcome','kết quả; hệ quả','noun','[{"en":"Nobody could predict the outcome of the negotiations.","vi":"Không ai có thể dự đoán kết quả của cuộc đàm phán."},{"en":"Early treatment usually leads to better outcomes for patients.","vi":"Điều trị sớm thường mang lại kết quả tốt hơn cho bệnh nhân."},{"en":"We are still waiting for the outcome of the review.","vi":"Chúng tôi vẫn đang chờ kết quả của đợt xem xét."}]','[{"phrase":"the outcome of"},{"phrase":"a positive outcome"},{"phrase":"predict the outcome"},{"phrase":"learning outcomes"}]',NULL,'/ˈaʊtkʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outco/outcome__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2880,'awl-3-02',10,'partner','đối tác; cộng sự','noun','[{"en":"The firm is looking for a local partner to enter the Asian market.","vi":"Công ty đang tìm một đối tác địa phương để thâm nhập thị trường châu Á."},{"en":"Over the past decade, its neighbor has become the country''s largest trading partner.","vi":"Trong thập kỷ qua, nước láng giềng đã trở thành đối tác thương mại lớn nhất của quốc gia này."},{"en":"Students worked with a partner to complete the experiment.","vi":"Sinh viên làm việc theo cặp với một bạn để hoàn thành thí nghiệm."}]','[{"phrase":"business partner"},{"phrase":"trading partner"},{"phrase":"senior partner"},{"phrase":"partner with"}]',NULL,'/ˈpɑːrtnər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/partn/partner__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2881,'awl-3-02',11,'philosophy','triết học; triết lý; quan điểm','noun','[{"en":"She studied philosophy and economics at university.","vi":"Cô ấy học triết học và kinh tế học ở trường đại học."},{"en":"The company''s philosophy is to put customers first.","vi":"Triết lý của công ty là đặt khách hàng lên hàng đầu."},{"en":"His teaching philosophy focuses on learning through practice.","vi":"Quan điểm giảng dạy của thầy ấy tập trung vào việc học qua thực hành."}]','[{"phrase":"political philosophy"},{"phrase":"moral philosophy"},{"phrase":"business philosophy"},{"phrase":"philosophy of"}]',NULL,'/fəˈlɑːsəfi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phi/philo/philosophy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2882,'awl-3-02',12,'physical','thể chất; vật lý; vật chất','adjective','[{"en":"Regular physical activity reduces the risk of many diseases.","vi":"Hoạt động thể chất thường xuyên giúp giảm nguy cơ mắc nhiều bệnh."},{"en":"The job involves a lot of physical work outdoors.","vi":"Công việc này đòi hỏi nhiều lao động chân tay ngoài trời."},{"en":"Many shoppers now prefer online stores to physical shops.","vi":"Nhiều người mua sắm hiện nay thích cửa hàng trực tuyến hơn cửa hàng thực tế."}]','[{"phrase":"physical activity"},{"phrase":"physical health"},{"phrase":"physical exercise"},{"phrase":"physical environment"}]','physical (thể chất) ≠ physics (môn vật lý)','/ˈfɪzɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phy/physi/physical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2883,'awl-3-02',13,'proportion','tỷ lệ; phần; sự cân đối','noun','[{"en":"A large proportion of students work part-time while studying.","vi":"Một tỷ lệ lớn sinh viên vừa học vừa làm thêm bán thời gian."},{"en":"The proportion of older people in the population is rising.","vi":"Tỷ lệ người cao tuổi trong dân số đang tăng lên."},{"en":"Taxes should be paid in proportion to income.","vi":"Thuế nên được đóng theo tỷ lệ tương ứng với thu nhập."}]','[{"phrase":"a large proportion of"},{"phrase":"the proportion of"},{"phrase":"in proportion to"},{"phrase":"a high proportion"}]','in proportion to = tương xứng với','/prəˈpɔːrʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/proportion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2884,'awl-3-02',14,'publish','xuất bản; công bố; đăng tải','verb','[{"en":"The study was published in a leading medical journal.","vi":"Nghiên cứu này đã được đăng trên một tạp chí y khoa hàng đầu."},{"en":"The government will publish the full report next month.","vi":"Chính phủ sẽ công bố toàn bộ bản báo cáo vào tháng tới."},{"en":"She has published three books on urban planning.","vi":"Bà ấy đã xuất bản ba cuốn sách về quy hoạch đô thị."}]','[{"phrase":"publish a report"},{"phrase":"publish research"},{"phrase":"published in a journal"},{"phrase":"recently published"}]',NULL,'/ˈpʌblɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2885,'awl-3-02',15,'react','phản ứng','verb','[{"en":"How did investors react to the news?","vi":"Các nhà đầu tư đã phản ứng thế nào trước tin tức này?"},{"en":"The market reacted quickly to the rise in interest rates.","vi":"Thị trường đã phản ứng nhanh chóng trước việc tăng lãi suất."},{"en":"This metal reacts with oxygen to form a thin coating.","vi":"Kim loại này phản ứng với oxy để tạo thành một lớp phủ mỏng."}]','[{"phrase":"react to"},{"phrase":"react quickly"},{"phrase":"react with"},{"phrase":"react strongly"}]','react to (sự việc) · react with (chất hóa học)','/riˈækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/react/react__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2886,'awl-3-02',16,'register','đăng ký; ghi danh; sổ đăng ký','verb','[{"en":"All participants must register before the conference begins.","vi":"Tất cả người tham dự phải đăng ký trước khi hội nghị bắt đầu."},{"en":"More than two hundred students registered for the course this year.","vi":"Năm nay có hơn hai trăm sinh viên ghi danh vào khóa học."},{"en":"The organization is officially registered as a charity.","vi":"Tổ chức này được đăng ký chính thức là một tổ chức từ thiện."}]','[{"phrase":"register for"},{"phrase":"register a company"},{"phrase":"officially registered"}]','register for + khóa học/sự kiện','/ˈredʒɪstər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regis/register__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2887,'awl-3-02',17,'rely','dựa vào; phụ thuộc vào; tin cậy','verb','[{"en":"Many small farmers rely on rain to water their crops.","vi":"Nhiều nông dân nhỏ phụ thuộc vào nước mưa để tưới cây trồng."},{"en":"The study relied heavily on data from online surveys.","vi":"Nghiên cứu này dựa rất nhiều vào dữ liệu từ các cuộc khảo sát trực tuyến."},{"en":"You can rely on her to finish the task on time.","vi":"Bạn có thể tin tưởng rằng cô ấy sẽ hoàn thành nhiệm vụ đúng hạn."}]','[{"phrase":"rely on"},{"phrase":"rely heavily on"},{"phrase":"rely on data"}]','rely on/upon + danh từ','/rɪˈlaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/rely_/rely__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2888,'awl-3-02',18,'remove','loại bỏ; gỡ bỏ; di dời','verb','[{"en":"The new law removes barriers to international trade.","vi":"Luật mới gỡ bỏ các rào cản đối với thương mại quốc tế."},{"en":"Workers removed the old equipment from the laboratory.","vi":"Công nhân đã di dời thiết bị cũ ra khỏi phòng thí nghiệm."},{"en":"Incomplete responses were removed from the final analysis.","vi":"Những câu trả lời chưa đầy đủ đã bị loại khỏi phần phân tích cuối cùng."}]','[{"phrase":"remove from"},{"phrase":"remove barriers"},{"phrase":"completely remove"}]','remove A from B','/rɪˈmuːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remov/remove__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2889,'awl-3-02',19,'scheme','kế hoạch; chương trình; âm mưu','noun','[{"en":"The government launched a scheme to help first-time home buyers.","vi":"Chính phủ đã khởi động một chương trình hỗ trợ những người lần đầu mua nhà."},{"en":"Employees can join the company pension scheme after six months.","vi":"Nhân viên có thể tham gia chương trình lương hưu của công ty sau sáu tháng."},{"en":"Police uncovered a scheme to cheat investors out of millions.","vi":"Cảnh sát đã phát hiện một âm mưu lừa đảo các nhà đầu tư hàng triệu đô la."}]','[{"phrase":"pension scheme"},{"phrase":"launch a scheme"},{"phrase":"pilot scheme"},{"phrase":"a scheme to"}]','Anh: scheme thường trung tính · Mỹ: hay mang nghĩa âm mưu','/skiːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/schem/scheme__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2890,'awl-3-02',20,'sequence','trình tự; chuỗi; dãy','noun','[{"en":"The steps must be carried out in the correct sequence.","vi":"Các bước phải được thực hiện theo đúng trình tự."},{"en":"Scientists have mapped the DNA sequence of the virus.","vi":"Các nhà khoa học đã giải mã trình tự ADN của loại virus này."},{"en":"The report describes a sequence of events that led to the crisis.","vi":"Bản báo cáo mô tả chuỗi sự kiện dẫn đến cuộc khủng hoảng."}]','[{"phrase":"a sequence of events"},{"phrase":"in sequence"},{"phrase":"the correct sequence"},{"phrase":"DNA sequence"}]',NULL,'/ˈsiːkwəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/seq/seque/sequence__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2891,'awl-3-02',21,'sex','giới tính','noun','[{"en":"The form asks for your name, age and sex.","vi":"Mẫu đơn yêu cầu điền tên, tuổi và giới tính của bạn."},{"en":"Participants were divided into groups by age and sex.","vi":"Những người tham gia được chia thành các nhóm theo độ tuổi và giới tính."},{"en":"The law bans discrimination on the basis of sex.","vi":"Luật pháp cấm phân biệt đối xử dựa trên giới tính."}]','[{"phrase":"age and sex"},{"phrase":"the opposite sex"},{"phrase":"on the basis of sex"}]','sex (giới tính sinh học) · gender (giới tính xã hội)','/seks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sex/sex__/sex__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2892,'awl-3-02',22,'shift','sự thay đổi; sự chuyển dịch; ca làm việc','noun','[{"en":"There has been a major shift in public attitudes towards recycling.","vi":"Đã có một sự thay đổi lớn trong thái độ của công chúng đối với việc tái chế."},{"en":"The economy is seeing a shift from manufacturing to services.","vi":"Nền kinh tế đang chứng kiến sự chuyển dịch từ sản xuất sang dịch vụ."},{"en":"Nurses at the hospital often work twelve-hour night shifts.","vi":"Các y tá ở bệnh viện thường làm ca đêm kéo dài mười hai tiếng."}]','[{"phrase":"a shift in"},{"phrase":"a major shift"},{"phrase":"shift toward"},{"phrase":"night shift"}]',NULL,'/ʃɪft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/shift/shift__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2893,'awl-3-02',23,'specify','nêu rõ; chỉ định cụ thể','verb','[{"en":"The contract specifies the date by which the work must be finished.","vi":"Hợp đồng nêu rõ ngày mà công việc phải được hoàn thành."},{"en":"Please specify your preferred start date on the application form.","vi":"Vui lòng ghi rõ ngày bắt đầu mong muốn của bạn trong đơn đăng ký."},{"en":"The rules do not specify how the money should be spent.","vi":"Các quy định không nêu rõ số tiền nên được chi tiêu như thế nào."}]','[{"phrase":"clearly specify"},{"phrase":"specify the date"},{"phrase":"unless otherwise specified"}]',NULL,'/ˈspesɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speci/specify__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2894,'awl-3-02',24,'sufficient','đủ; đầy đủ','adjective','[{"en":"There is not sufficient evidence to support this claim.","vi":"Không có đủ bằng chứng để ủng hộ nhận định này."},{"en":"Make sure you allow sufficient time to complete the test.","vi":"Hãy đảm bảo bạn dành đủ thời gian để hoàn thành bài kiểm tra."},{"en":"A small increase in funding will not be sufficient.","vi":"Một khoản tăng ngân sách nhỏ sẽ không đủ."}]','[{"phrase":"sufficient evidence"},{"phrase":"sufficient time"},{"phrase":"sufficient funds"},{"phrase":"sufficient to"}]','sufficient ≠ insufficient (không đủ)','/səˈfɪʃnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suf/suffi/sufficient__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2895,'awl-3-02',25,'task','nhiệm vụ; công việc','noun','[{"en":"Each member of the team was given a specific task.","vi":"Mỗi thành viên trong nhóm được giao một nhiệm vụ cụ thể."},{"en":"Finding enough volunteers proved to be a difficult task.","vi":"Việc tìm đủ tình nguyện viên hóa ra là một nhiệm vụ khó khăn."},{"en":"Computers can now perform many tasks that once required humans.","vi":"Máy tính giờ đây có thể thực hiện nhiều công việc từng cần đến con người."}]','[{"phrase":"perform a task"},{"phrase":"a difficult task"},{"phrase":"complete a task"},{"phrase":"the task of"}]',NULL,'/tæsk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tas/task_/task__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2896,'awl-3-02',26,'technical','kỹ thuật; chuyên môn','adjective','[{"en":"The launch was delayed because of a technical problem.","vi":"Buổi ra mắt bị hoãn vì một sự cố kỹ thuật."},{"en":"Try to avoid technical terms when writing for the general public.","vi":"Hãy cố tránh dùng thuật ngữ chuyên môn khi viết cho công chúng."},{"en":"Our company provides technical support to customers around the clock.","vi":"Công ty chúng tôi cung cấp hỗ trợ kỹ thuật cho khách hàng suốt ngày đêm."}]','[{"phrase":"technical support"},{"phrase":"technical problem"},{"phrase":"technical terms"},{"phrase":"technical skills"}]',NULL,'/ˈteknɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2897,'awl-3-02',27,'technique','kỹ thuật; phương pháp; kỹ năng','noun','[{"en":"The researchers used a new technique to measure brain activity.","vi":"Các nhà nghiên cứu đã dùng một kỹ thuật mới để đo hoạt động của não."},{"en":"Good teachers use a range of techniques to keep students interested.","vi":"Giáo viên giỏi sử dụng nhiều phương pháp khác nhau để giữ hứng thú cho học sinh."},{"en":"Her writing technique improved a lot during the course.","vi":"Kỹ năng viết của cô ấy đã tiến bộ nhiều trong suốt khóa học."}]','[{"phrase":"a new technique"},{"phrase":"use a technique"},{"phrase":"techniques for"},{"phrase":"management techniques"}]','technique (n: kỹ thuật, cách làm) ≠ technical (adj)','/tekˈniːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technique__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2898,'awl-3-02',28,'technology','công nghệ','noun','[{"en":"New technology has changed the way people work.","vi":"Công nghệ mới đã thay đổi cách mọi người làm việc."},{"en":"Schools are spending more on information technology every year.","vi":"Các trường học đang chi tiêu ngày càng nhiều hơn cho công nghệ thông tin mỗi năm."},{"en":"Advances in medical technology have helped people live longer.","vi":"Những tiến bộ trong công nghệ y tế đã giúp con người sống lâu hơn."}]','[{"phrase":"new technology"},{"phrase":"information technology"},{"phrase":"advances in technology"},{"phrase":"modern technology"}]',NULL,'/tekˈnɑːlədʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technology__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2899,'awl-3-02',29,'valid','hợp lệ; có giá trị; có cơ sở','adjective','[{"en":"You need a valid passport to travel abroad.","vi":"Bạn cần một hộ chiếu còn hiệu lực để đi nước ngoài."},{"en":"The ticket is valid for three months from the date of purchase.","vi":"Vé có giá trị trong ba tháng kể từ ngày mua."},{"en":"She raised a valid point about the cost of the project.","vi":"Cô ấy đã nêu ra một ý kiến có cơ sở về chi phí của dự án."}]','[{"phrase":"a valid point"},{"phrase":"valid for"},{"phrase":"a valid passport"},{"phrase":"valid reason"}]','valid ≠ invalid (không hợp lệ)','/ˈvælɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/val/valid/valid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2900,'awl-3-02',30,'volume','khối lượng; thể tích; âm lượng','noun','[{"en":"The volume of online sales has doubled in five years.","vi":"Khối lượng hàng bán trực tuyến đã tăng gấp đôi trong năm năm."},{"en":"Measure the volume of water in each container.","vi":"Hãy đo thể tích nước trong mỗi bình chứa."},{"en":"Could you turn down the volume during the meeting?","vi":"Bạn có thể giảm âm lượng trong lúc họp được không?"}]','[{"phrase":"the volume of"},{"phrase":"traffic volume"},{"phrase":"sales volume"},{"phrase":"turn down the volume"}]',NULL,'/ˈvɑːljəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volum/volume__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2901,'awl-4-01',1,'access','quyền truy cập; sự tiếp cận','noun','[{"en":"Students have free access to the library''s online journals.","vi":"Sinh viên được truy cập miễn phí các tạp chí trực tuyến của thư viện."},{"en":"Many rural communities still lack access to clean water.","vi":"Nhiều cộng đồng nông thôn vẫn chưa được tiếp cận nước sạch."},{"en":"Access to the building is restricted after eight in the evening.","vi":"Việc ra vào tòa nhà bị hạn chế sau tám giờ tối."}]','[{"phrase":"have access to"},{"phrase":"gain access to"},{"phrase":"limited access"}]','access to + danh từ','/ˈækses/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/acces/access__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2902,'awl-4-01',2,'adequate','đủ; thỏa đáng; đạt yêu cầu','adjective','[{"en":"Many schools lack adequate funding for science equipment.","vi":"Nhiều trường học thiếu kinh phí đủ để mua thiết bị khoa học."},{"en":"The hospital could not provide adequate care for all its patients.","vi":"Bệnh viện không thể chăm sóc thỏa đáng cho tất cả bệnh nhân của mình."},{"en":"The report found that safety training at the factory was not adequate.","vi":"Báo cáo cho thấy việc đào tạo an toàn tại nhà máy chưa đạt yêu cầu."}]','[{"phrase":"adequate funding"},{"phrase":"adequate resources"},{"phrase":"adequate care"},{"phrase":"adequate protection"}]',NULL,'/ˈædɪkwət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ade/adequ/adequate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2903,'awl-4-01',3,'annual','hằng năm; thường niên','adjective','[{"en":"The company publishes its annual report every March.","vi":"Công ty công bố báo cáo thường niên vào tháng Ba hằng năm."},{"en":"Average annual rainfall in the region has dropped sharply.","vi":"Lượng mưa trung bình hằng năm ở khu vực này đã giảm mạnh."},{"en":"Hundreds of researchers attended the annual conference in Singapore.","vi":"Hàng trăm nhà nghiên cứu đã tham dự hội nghị thường niên tại Singapore."}]','[{"phrase":"annual report"},{"phrase":"annual meeting"},{"phrase":"annual growth"},{"phrase":"annual income"}]',NULL,'/ˈænjuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annua/annual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2904,'awl-4-01',4,'apparent','rõ ràng; hiển nhiên; có vẻ (bề ngoài)','adjective','[{"en":"It soon became apparent that the project would need more time.","vi":"Chẳng bao lâu sau, rõ ràng là dự án sẽ cần thêm thời gian."},{"en":"The effects of the new policy are already apparent in rural areas.","vi":"Tác động của chính sách mới đã thấy rõ ở các vùng nông thôn."},{"en":"Despite her apparent calm, the manager was worried about the deadline.","vi":"Dù bề ngoài có vẻ bình tĩnh, người quản lý vẫn lo lắng về hạn chót."}]','[{"phrase":"become apparent"},{"phrase":"for no apparent reason"},{"phrase":"readily apparent"}]','it is apparent that + mệnh đề','/əˈpærənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appar/apparent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2905,'awl-4-01',5,'approximate','xấp xỉ; gần đúng','adjective','[{"en":"The approximate cost of the project is two million dollars.","vi":"Chi phí ước tính của dự án là khoảng hai triệu đô la."},{"en":"Can you give me an approximate number of participants?","vi":"Bạn có thể cho tôi biết số người tham gia xấp xỉ không?"},{"en":"These figures are only approximate and may change next month.","vi":"Những số liệu này chỉ là gần đúng và có thể thay đổi vào tháng sau."}]','[{"phrase":"approximate cost"},{"phrase":"approximate number"},{"phrase":"approximate value"}]','approximately (adv): khoảng, xấp xỉ','/əˈprɑːksɪmət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/approximate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2906,'awl-4-01',6,'attitude','thái độ; quan điểm','noun','[{"en":"Public attitudes toward recycling have changed a lot in recent years.","vi":"Quan điểm của công chúng về việc tái chế đã thay đổi nhiều trong những năm gần đây."},{"en":"Employers value workers with a positive attitude and good communication skills.","vi":"Nhà tuyển dụng đánh giá cao người lao động có thái độ tích cực và kỹ năng giao tiếp tốt."},{"en":"The survey measured students'' attitudes toward learning a foreign language.","vi":"Cuộc khảo sát đo lường thái độ của học sinh đối với việc học ngoại ngữ."}]','[{"phrase":"positive attitude"},{"phrase":"attitude toward"},{"phrase":"public attitudes"},{"phrase":"change attitudes"}]','attitude to/toward + danh từ / V-ing','/ˈætɪtuːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attit/attitude__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2907,'awl-4-01',7,'attribute','quy cho; cho là do','verb','[{"en":"Researchers attribute the rise in temperatures to human activity.","vi":"Các nhà nghiên cứu cho rằng nhiệt độ tăng là do hoạt động của con người."},{"en":"The company attributed its strong profits to lower production costs.","vi":"Công ty cho rằng lợi nhuận cao là nhờ chi phí sản xuất thấp hơn."},{"en":"Much of the drop in crime can be attributed to better street lighting.","vi":"Phần lớn sự sụt giảm tội phạm có thể là nhờ đèn đường được cải thiện."}]','[{"phrase":"attribute something to"},{"phrase":"be attributed to"},{"phrase":"largely attributed to"}]','attribute A to B: cho rằng A là do B · (n) attribute: thuộc tính','/əˈtrɪbjuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attri/attribute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2908,'awl-4-01',8,'civil','dân sự; dân dụng; (thuộc) công dân','adjective','[{"en":"Civil servants will receive a small pay rise next year.","vi":"Công chức sẽ được tăng lương một chút vào năm tới."},{"en":"Many universities offer degrees in civil engineering.","vi":"Nhiều trường đại học đào tạo bằng cấp ngành kỹ thuật xây dựng dân dụng."},{"en":"The case was settled in a civil court rather than a criminal one.","vi":"Vụ việc được giải quyết tại tòa dân sự thay vì tòa hình sự."}]','[{"phrase":"civil servant"},{"phrase":"civil engineering"},{"phrase":"civil society"},{"phrase":"civil law"}]',NULL,'/ˈsɪvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/civ/civil/civil__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2909,'awl-4-01',9,'code','bộ quy tắc; mã','noun','[{"en":"All employees must follow the company''s code of conduct.","vi":"Tất cả nhân viên phải tuân thủ bộ quy tắc ứng xử của công ty."},{"en":"Enter the security code that was sent to your phone.","vi":"Hãy nhập mã bảo mật đã được gửi đến điện thoại của bạn."},{"en":"The engineers spent several weeks rewriting the code for the app.","vi":"Các kỹ sư đã mất vài tuần để viết lại mã cho ứng dụng."}]','[{"phrase":"code of conduct"},{"phrase":"security code"},{"phrase":"write code"},{"phrase":"dress code"}]',NULL,'/kəʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cod/code_/code__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2910,'awl-4-01',10,'commit','cam kết; phạm (tội, lỗi)','verb','[{"en":"The government has committed to reducing carbon emissions by 2030.","vi":"Chính phủ đã cam kết giảm lượng khí thải carbon trước năm 2030."},{"en":"Both companies are committed to improving working conditions.","vi":"Cả hai công ty đều cam kết cải thiện điều kiện làm việc."},{"en":"Most crimes are committed by a small number of offenders.","vi":"Phần lớn tội phạm là do một số ít người phạm tội gây ra."}]','[{"phrase":"commit to"},{"phrase":"be committed to"},{"phrase":"commit a crime"},{"phrase":"commit an error"}]','commit – committed – committed · commit to + V-ing','/kəˈmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2911,'awl-4-01',11,'communicate','giao tiếp; truyền đạt','verb','[{"en":"Good managers communicate clearly and regularly with their teams.","vi":"Người quản lý giỏi giao tiếp rõ ràng và thường xuyên với nhóm của mình."},{"en":"The findings were communicated to the public through a short video.","vi":"Kết quả nghiên cứu được truyền đạt tới công chúng qua một video ngắn."},{"en":"Many patients find it hard to communicate their symptoms to doctors.","vi":"Nhiều bệnh nhân thấy khó diễn đạt các triệu chứng của mình với bác sĩ."}]','[{"phrase":"communicate with"},{"phrase":"communicate effectively"},{"phrase":"communicate clearly"},{"phrase":"communicate information"}]','communicate with somebody','/kəˈmjuːnɪkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/communicate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2912,'awl-4-01',12,'concentrate','tập trung','verb','[{"en":"It is difficult to concentrate in a noisy office.","vi":"Thật khó tập trung trong một văn phòng ồn ào."},{"en":"The company decided to concentrate on its core products.","vi":"Công ty quyết định tập trung vào các sản phẩm cốt lõi của mình."},{"en":"Most of the country''s population is concentrated along the coast.","vi":"Phần lớn dân số của đất nước tập trung dọc theo bờ biển."}]','[{"phrase":"concentrate on"},{"phrase":"concentrate efforts"},{"phrase":"highly concentrated"}]','concentrate on + danh từ / V-ing','/ˈkɑːnsntreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcentrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2913,'awl-4-01',13,'confer','hội ý; trao, ban (bằng cấp, quyền)','verb','[{"en":"The judges conferred briefly before announcing their decision.","vi":"Các thẩm phán hội ý nhanh trước khi công bố quyết định."},{"en":"The university conferred honorary degrees on three scientists.","vi":"Trường đại học đã trao bằng danh dự cho ba nhà khoa học."},{"en":"Membership confers certain rights, such as voting at annual meetings.","vi":"Tư cách thành viên mang lại một số quyền nhất định, như biểu quyết tại các cuộc họp thường niên."}]','[{"phrase":"confer with"},{"phrase":"confer a degree on"},{"phrase":"confer an advantage"}]','confer – conferred · confer with sb (hội ý) / confer sth on sb (trao)','/kənˈfɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2914,'awl-4-01',14,'contrast','sự tương phản; sự đối lập','noun','[{"en":"Sales in Europe fell; in contrast, sales in Asia rose by ten percent.","vi":"Doanh số ở châu Âu giảm; ngược lại, doanh số ở châu Á tăng mười phần trăm."},{"en":"There is a sharp contrast between rich and poor neighborhoods in the city.","vi":"Có sự tương phản rõ rệt giữa các khu dân cư giàu và nghèo trong thành phố."},{"en":"The study draws a contrast between urban and rural schools.","vi":"Nghiên cứu chỉ ra sự đối lập giữa trường học ở thành thị và nông thôn."}]','[{"phrase":"in contrast"},{"phrase":"by contrast"},{"phrase":"sharp contrast"},{"phrase":"draw a contrast"}]','contrast between A and B','/ˈkɑːntræst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrast__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2915,'awl-4-01',15,'cycle','chu kỳ; vòng tuần hoàn','noun','[{"en":"The economy goes through a cycle of growth and decline.","vi":"Nền kinh tế trải qua một chu kỳ tăng trưởng và suy thoái."},{"en":"The children learned about the life cycle of a butterfly.","vi":"Bọn trẻ đã học về vòng đời của loài bướm."},{"en":"The water cycle plays a key role in shaping the climate.","vi":"Vòng tuần hoàn của nước đóng vai trò then chốt trong việc hình thành khí hậu."}]','[{"phrase":"life cycle"},{"phrase":"water cycle"},{"phrase":"business cycle"},{"phrase":"economic cycle"}]',NULL,'/ˈsaɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cyc/cycle/cycle__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2916,'awl-4-01',16,'debate','cuộc tranh luận; sự tranh cãi','noun','[{"en":"There is a growing debate about the use of AI in schools.","vi":"Ngày càng có nhiều tranh luận về việc sử dụng AI trong trường học."},{"en":"After a long debate, the committee approved the new budget.","vi":"Sau một cuộc tranh luận dài, ủy ban đã thông qua ngân sách mới."},{"en":"The causes of the crisis remain a subject of debate among economists.","vi":"Nguyên nhân của cuộc khủng hoảng vẫn là chủ đề tranh cãi giữa các nhà kinh tế học."}]','[{"phrase":"public debate"},{"phrase":"heated debate"},{"phrase":"debate about"},{"phrase":"subject of debate"}]',NULL,'/dɪˈbeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deb/debat/debate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2917,'awl-4-01',17,'despite','mặc dù; bất chấp','preposition','[{"en":"Despite the rain, thousands of people attended the festival.","vi":"Mặc dù trời mưa, hàng nghìn người vẫn đến dự lễ hội."},{"en":"The project was a success despite its limited budget.","vi":"Dự án đã thành công mặc dù ngân sách hạn hẹp."},{"en":"Despite rising costs, the company kept its prices unchanged.","vi":"Bất chấp chi phí tăng, công ty vẫn giữ nguyên giá bán."}]','[{"phrase":"despite the fact that"},{"phrase":"despite efforts"},{"phrase":"despite concerns"}]','despite + danh từ / V-ing (không nói "despite of")','/dɪˈspaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/despi/despite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2918,'awl-4-01',18,'dimension','khía cạnh; kích thước; chiều','noun','[{"en":"The report examines the social dimension of climate change.","vi":"Báo cáo xem xét khía cạnh xã hội của biến đổi khí hậu."},{"en":"Please measure the dimensions of the room before ordering furniture.","vi":"Vui lòng đo kích thước căn phòng trước khi đặt mua đồ nội thất."},{"en":"The discovery added a new dimension to our understanding of the disease.","vi":"Phát hiện này mở ra một khía cạnh mới trong hiểu biết của chúng ta về căn bệnh."}]','[{"phrase":"new dimension"},{"phrase":"social dimension"},{"phrase":"add a new dimension"}]',NULL,'/daɪˈmenʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dim/dimen/dimension__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2919,'awl-4-01',19,'domestic','trong nước; nội địa; (thuộc) gia đình','adjective','[{"en":"Domestic demand for electric cars rose sharply last year.","vi":"Nhu cầu trong nước đối với ô tô điện đã tăng mạnh vào năm ngoái."},{"en":"The airline plans to add more domestic flights this summer.","vi":"Hãng hàng không dự định bổ sung thêm các chuyến bay nội địa vào mùa hè này."},{"en":"In many countries, women still do most of the domestic work.","vi":"Ở nhiều quốc gia, phụ nữ vẫn đảm nhận phần lớn công việc gia đình."}]','[{"phrase":"domestic market"},{"phrase":"domestic flights"},{"phrase":"domestic demand"},{"phrase":"gross domestic product"}]',NULL,'/dəˈmestɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domes/domestic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2920,'awl-4-01',20,'emerge','nổi lên; xuất hiện; lộ ra','verb','[{"en":"New evidence has emerged that the drug may cause side effects.","vi":"Bằng chứng mới đã lộ ra rằng loại thuốc này có thể gây tác dụng phụ."},{"en":"Several key themes emerged from the interviews.","vi":"Một số chủ đề chính đã xuất hiện từ các cuộc phỏng vấn."},{"en":"Online shopping emerged as a major trend during the last decade.","vi":"Mua sắm trực tuyến đã nổi lên như một xu hướng lớn trong thập kỷ qua."}]','[{"phrase":"emerge from"},{"phrase":"emerge as"},{"phrase":"begin to emerge"}]',NULL,'/ɪˈmɜːrdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eme/emerg/emerge__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2921,'awl-4-01',21,'error','lỗi; sai sót','noun','[{"en":"The report contained several errors in its calculations.","vi":"Báo cáo có một vài sai sót trong các phép tính."},{"en":"A simple human error caused the whole system to shut down.","vi":"Một lỗi đơn giản do con người đã khiến toàn bộ hệ thống ngừng hoạt động."},{"en":"Please check your answers carefully to avoid spelling errors.","vi":"Hãy kiểm tra kỹ câu trả lời để tránh lỗi chính tả."}]','[{"phrase":"human error"},{"phrase":"make an error"},{"phrase":"spelling error"},{"phrase":"margin of error"}]',NULL,'/ˈerər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/err/error/error__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2922,'awl-4-01',22,'ethnic','(thuộc) dân tộc; sắc tộc','adjective','[{"en":"Vietnam is home to fifty-four officially recognized ethnic groups.","vi":"Việt Nam có năm mươi tư dân tộc được công nhận chính thức."},{"en":"The city''s restaurants reflect its rich ethnic diversity.","vi":"Các nhà hàng của thành phố phản ánh sự đa dạng sắc tộc phong phú nơi đây."},{"en":"The study included participants from a wide range of ethnic backgrounds.","vi":"Nghiên cứu có những người tham gia đến từ nhiều nguồn gốc dân tộc khác nhau."}]','[{"phrase":"ethnic group"},{"phrase":"ethnic minority"},{"phrase":"ethnic background"},{"phrase":"ethnic diversity"}]',NULL,'/ˈeθnɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eth/ethni/ethnic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2923,'awl-4-01',23,'goal','mục tiêu','noun','[{"en":"Our main goal is to cut waste by half.","vi":"Mục tiêu chính của chúng tôi là giảm một nửa lượng rác thải."},{"en":"The team achieved all of its goals for the year.","vi":"Nhóm đã đạt được tất cả mục tiêu đề ra trong năm."},{"en":"Setting clear goals helps students stay motivated.","vi":"Đặt mục tiêu rõ ràng giúp học sinh duy trì động lực."}]','[{"phrase":"achieve a goal"},{"phrase":"set a goal"},{"phrase":"main goal"},{"phrase":"long-term goal"}]',NULL,'/ɡəʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/goa/goal_/goal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2924,'awl-4-01',24,'grant','khoản tài trợ; trợ cấp','noun','[{"en":"The research team received a large grant from the government.","vi":"Nhóm nghiên cứu đã nhận được một khoản tài trợ lớn từ chính phủ."},{"en":"She applied for a grant to study marine biology abroad.","vi":"Cô ấy đã xin trợ cấp để đi du học ngành sinh học biển."},{"en":"Small businesses can use the grant to buy new equipment.","vi":"Các doanh nghiệp nhỏ có thể dùng khoản tài trợ để mua thiết bị mới."}]','[{"phrase":"research grant"},{"phrase":"apply for a grant"},{"phrase":"receive a grant"},{"phrase":"government grant"}]','(v) grant: cấp, cho phép','/ɡrænt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grant/grant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2925,'awl-4-01',25,'hence','do đó; vì vậy','adverb','[{"en":"The data was incomplete, hence the need for further research.","vi":"Dữ liệu chưa đầy đủ, do đó cần phải nghiên cứu thêm."},{"en":"Fuel prices rose sharply; hence, demand for smaller cars increased.","vi":"Giá nhiên liệu tăng mạnh; vì vậy, nhu cầu về xe cỡ nhỏ tăng lên."},{"en":"The material is light and strong, and hence ideal for aircraft.","vi":"Vật liệu này nhẹ và bền, do đó rất lý tưởng cho máy bay."}]','[{"phrase":"hence the need"},{"phrase":"hence the name"},{"phrase":"and hence"}]','hence + danh từ (không cần động từ): hence the need','/hens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hen/hence/hence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2926,'awl-4-01',26,'hypothesis','giả thuyết','noun','[{"en":"The results support the hypothesis that sleep improves memory.","vi":"Kết quả ủng hộ giả thuyết rằng giấc ngủ giúp cải thiện trí nhớ."},{"en":"The scientists designed an experiment to test their hypothesis.","vi":"Các nhà khoa học đã thiết kế một thí nghiệm để kiểm chứng giả thuyết của họ."},{"en":"Earlier studies failed to confirm this hypothesis.","vi":"Các nghiên cứu trước đây đã không xác nhận được giả thuyết này."}]','[{"phrase":"test a hypothesis"},{"phrase":"support the hypothesis"},{"phrase":"confirm a hypothesis"},{"phrase":"working hypothesis"}]','số nhiều: hypotheses','/haɪˈpɑːθəsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hyp/hypot/hypothesis__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2927,'awl-4-01',27,'implement','thực hiện; triển khai; thi hành','verb','[{"en":"The school will implement the new curriculum next year.","vi":"Nhà trường sẽ triển khai chương trình giảng dạy mới vào năm tới."},{"en":"Many of the report''s recommendations have never been implemented.","vi":"Nhiều khuyến nghị trong báo cáo chưa bao giờ được thực hiện."},{"en":"Implementing these changes will require both time and money.","vi":"Việc thực hiện những thay đổi này sẽ cần cả thời gian lẫn tiền bạc."}]','[{"phrase":"implement a policy"},{"phrase":"implement changes"},{"phrase":"fully implement"},{"phrase":"implement recommendations"}]',NULL,'/ˈɪmplɪment/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/imple/implement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2928,'awl-4-01',28,'implicate','cho thấy có liên quan; làm liên lụy','verb','[{"en":"Several genes have been implicated in the development of the disease.","vi":"Một số gen được cho là có liên quan đến sự phát triển của căn bệnh này."},{"en":"Poor diet is often implicated in heart problems.","vi":"Chế độ ăn uống kém thường được cho là có liên quan đến các bệnh về tim."},{"en":"The investigation implicated two senior managers in the fraud.","vi":"Cuộc điều tra cho thấy hai quản lý cấp cao có dính líu đến vụ gian lận."}]','[{"phrase":"be implicated in"},{"phrase":"implicate somebody in"},{"phrase":"strongly implicated"}]','implicate sb/sth in sth · thường dùng bị động: be implicated in','/ˈɪmplɪkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impli/implicate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2929,'awl-4-01',29,'impose','áp đặt; áp (thuế, lệnh cấm)','verb','[{"en":"The government plans to impose a new tax on sugary drinks.","vi":"Chính phủ dự định áp một loại thuế mới đối với đồ uống có đường."},{"en":"The city imposed strict limits on water use during the drought.","vi":"Thành phố đã áp đặt giới hạn nghiêm ngặt về sử dụng nước trong đợt hạn hán."},{"en":"Parents should not impose their own career choices on their children.","vi":"Cha mẹ không nên áp đặt lựa chọn nghề nghiệp của mình lên con cái."}]','[{"phrase":"impose a tax"},{"phrase":"impose restrictions"},{"phrase":"impose limits"},{"phrase":"impose on"}]','impose sth on sb/sth','/ɪmˈpəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impos/impose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2930,'awl-4-01',30,'integrate','hội nhập; tích hợp; kết hợp','verb','[{"en":"The new software integrates easily with our existing systems.","vi":"Phần mềm mới dễ dàng tích hợp với các hệ thống hiện có của chúng tôi."},{"en":"Schools are trying to integrate technology into every subject.","vi":"Các trường học đang cố gắng kết hợp công nghệ vào mọi môn học."},{"en":"Language classes help immigrants integrate into their new communities.","vi":"Các lớp học ngôn ngữ giúp người nhập cư hòa nhập vào cộng đồng mới."}]','[{"phrase":"integrate into"},{"phrase":"integrate with"},{"phrase":"fully integrated"},{"phrase":"integrate technology"}]','integrate A into/with B','/ˈɪntɪɡreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2931,'awl-4-02',1,'internal','nội bộ; bên trong','adjective','[{"en":"The company launched an internal investigation into the missing funds.","vi":"Công ty đã mở một cuộc điều tra nội bộ về khoản tiền bị thất thoát."},{"en":"Staff can find the new policy on the internal website.","vi":"Nhân viên có thể xem chính sách mới trên trang web nội bộ."},{"en":"The internal structure of the cell can be seen under a microscope.","vi":"Có thể quan sát cấu trúc bên trong của tế bào dưới kính hiển vi."}]','[{"phrase":"internal investigation"},{"phrase":"internal structure"},{"phrase":"internal communication"}]','trái nghĩa: external (bên ngoài)','/ɪnˈtɜːrnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/internal__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2932,'awl-4-02',2,'investigate','điều tra; nghiên cứu','verb','[{"en":"Officials are still investigating the cause of the fire.","vi":"Các quan chức vẫn đang điều tra nguyên nhân vụ cháy."},{"en":"This study investigates the effects of sleep on memory.","vi":"Nghiên cứu này tìm hiểu tác động của giấc ngủ đối với trí nhớ."},{"en":"The manager promised to investigate every complaint from customers.","vi":"Người quản lý hứa sẽ điều tra mọi khiếu nại của khách hàng."}]','[{"phrase":"investigate the cause"},{"phrase":"investigate the effects of"},{"phrase":"fully investigate"},{"phrase":"investigate a complaint"}]',NULL,'/ɪnˈvestɪɡeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/investigate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2933,'awl-4-02',3,'job','công việc; việc làm; nhiệm vụ','noun','[{"en":"She got a job at a research institute after graduating.","vi":"Cô ấy có được việc làm tại một viện nghiên cứu sau khi tốt nghiệp."},{"en":"Thousands of jobs were lost when the factory closed.","vi":"Hàng nghìn việc làm đã mất đi khi nhà máy đóng cửa."},{"en":"It is the manager''s job to make sure deadlines are met.","vi":"Nhiệm vụ của người quản lý là đảm bảo các thời hạn được đáp ứng."}]','[{"phrase":"get a job"},{"phrase":"lose a job"},{"phrase":"full-time job"},{"phrase":"job market"}]',NULL,'/dʒɑːb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/job/job__/job__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2934,'awl-4-02',4,'label','nhãn; nhãn mác','noun','[{"en":"Always read the label before taking any medicine.","vi":"Hãy luôn đọc nhãn trước khi uống bất kỳ loại thuốc nào."},{"en":"Food labels must list all the ingredients in the product.","vi":"Nhãn thực phẩm phải liệt kê tất cả các thành phần trong sản phẩm."},{"en":"Each sample was stored in a tube with a clear label.","vi":"Mỗi mẫu được bảo quản trong một ống nghiệm có dán nhãn rõ ràng."}]','[{"phrase":"read the label"},{"phrase":"food label"},{"phrase":"warning label"}]','động từ: label = dán nhãn; gán cho cái mác','/ˈleɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/label/label__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2935,'awl-4-02',5,'mechanism','cơ chế; bộ máy','noun','[{"en":"Scientists still do not fully understand the mechanism behind the disease.","vi":"Các nhà khoa học vẫn chưa hiểu đầy đủ cơ chế gây ra căn bệnh này."},{"en":"The city needs a better mechanism for handling public complaints.","vi":"Thành phố cần một cơ chế tốt hơn để xử lý khiếu nại của người dân."},{"en":"Sweating is the body''s natural mechanism for cooling down.","vi":"Đổ mồ hôi là cơ chế tự nhiên giúp cơ thể hạ nhiệt."}]','[{"phrase":"mechanism for"},{"phrase":"underlying mechanism"},{"phrase":"control mechanism"}]',NULL,'/ˈmekənɪzəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mec/mecha/mechanism__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2936,'awl-4-02',6,'obvious','rõ ràng; hiển nhiên','adjective','[{"en":"The most obvious solution is not always the best one.","vi":"Giải pháp rõ ràng nhất không phải lúc nào cũng là giải pháp tốt nhất."},{"en":"It was obvious that the plan would need more funding.","vi":"Rõ ràng là kế hoạch này sẽ cần thêm kinh phí."},{"en":"For obvious reasons, the results cannot be shared yet.","vi":"Vì những lý do hiển nhiên, kết quả chưa thể được công bố."}]','[{"phrase":"obvious reason"},{"phrase":"obvious choice"},{"phrase":"it is obvious that"},{"phrase":"fairly obvious"}]',NULL,'/ˈɑːbviəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obv/obvio/obvious__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2937,'awl-4-02',7,'occupy','chiếm; sử dụng (nơi chốn); giữ (vị trí)','verb','[{"en":"Forests occupy nearly a third of the country''s land area.","vi":"Rừng chiếm gần một phần ba diện tích đất của cả nước."},{"en":"The building is currently occupied by two small companies.","vi":"Tòa nhà hiện đang được hai công ty nhỏ sử dụng."},{"en":"Women still occupy few senior positions in the industry.","vi":"Phụ nữ vẫn giữ rất ít vị trí cấp cao trong ngành này."}]','[{"phrase":"occupy a position"},{"phrase":"occupy space"},{"phrase":"be occupied by"}]',NULL,'/ˈɑːkjupaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occup/occupy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2938,'awl-4-02',8,'option','lựa chọn; phương án','noun','[{"en":"Renting is often the only option for young workers in big cities.","vi":"Thuê nhà thường là lựa chọn duy nhất của người lao động trẻ ở các thành phố lớn."},{"en":"The committee discussed several options for reducing costs.","vi":"Ủy ban đã thảo luận một số phương án nhằm cắt giảm chi phí."},{"en":"Students have the option of taking the course online.","vi":"Sinh viên có thể lựa chọn học khóa này trực tuyến."}]','[{"phrase":"the only option"},{"phrase":"have the option of"},{"phrase":"consider the options"},{"phrase":"option for"}]',NULL,'/ˈɑːpʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opt/optio/option__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2939,'awl-4-02',9,'output','sản lượng; đầu ra','noun','[{"en":"Industrial output rose by three percent last year.","vi":"Sản lượng công nghiệp đã tăng ba phần trăm vào năm ngoái."},{"en":"The factory managed to double its output within two years.","vi":"Nhà máy đã tăng gấp đôi sản lượng trong vòng hai năm."},{"en":"The program displays the output as a simple table.","vi":"Chương trình hiển thị dữ liệu đầu ra dưới dạng một bảng đơn giản."}]','[{"phrase":"industrial output"},{"phrase":"increase output"},{"phrase":"total output"},{"phrase":"economic output"}]','thường không đếm được; trái nghĩa: input (đầu vào)','/ˈaʊtpʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/out/outpu/output__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2940,'awl-4-02',10,'overall','tổng thể; chung; toàn bộ','adjective','[{"en":"The overall cost of the project was lower than expected.","vi":"Tổng chi phí của dự án thấp hơn dự kiến."},{"en":"Our overall impression of the new system was positive.","vi":"Ấn tượng chung của chúng tôi về hệ thống mới là tích cực."},{"en":"Her overall performance this year has been excellent.","vi":"Kết quả làm việc tổng thể của cô ấy trong năm nay rất xuất sắc."}]','[{"phrase":"overall cost"},{"phrase":"overall performance"},{"phrase":"overall impression"},{"phrase":"overall effect"}]','trạng từ: overall = nhìn chung','/ˌəʊvərˈɔːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overa/overall__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2941,'awl-4-02',11,'parallel','song song; tương đồng','adjective','[{"en":"The new road runs parallel to the river for several kilometers.","vi":"Con đường mới chạy song song với dòng sông suốt vài ki-lô-mét."},{"en":"Parallel studies were carried out in three different countries.","vi":"Các nghiên cứu song song đã được tiến hành tại ba quốc gia khác nhau."},{"en":"The two countries followed parallel paths of economic development.","vi":"Hai quốc gia đã đi theo những con đường phát triển kinh tế tương đồng."}]','[{"phrase":"parallel to"},{"phrase":"run parallel"},{"phrase":"parallel lines"}]','parallel to + danh từ','/ˈpærəlel/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/paral/parallel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2942,'awl-4-02',12,'parameter','tham số; giới hạn','noun','[{"en":"The research must stay within the parameters set by the ethics committee.","vi":"Nghiên cứu phải nằm trong các giới hạn do hội đồng đạo đức đặt ra."},{"en":"You can change the parameters of the model to test different scenarios.","vi":"Bạn có thể thay đổi các tham số của mô hình để thử nghiệm những tình huống khác nhau."},{"en":"Temperature is an important parameter in this experiment.","vi":"Nhiệt độ là một tham số quan trọng trong thí nghiệm này."}]','[{"phrase":"within the parameters"},{"phrase":"set parameters"},{"phrase":"key parameter"}]','thường dùng ở số nhiều: parameters','/pəˈræmɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/param/parameter__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2943,'awl-4-02',13,'phase','giai đoạn','noun','[{"en":"The first phase of the project will be finished in March.","vi":"Giai đoạn đầu của dự án sẽ hoàn thành vào tháng Ba."},{"en":"The new drug is now in the final phase of testing.","vi":"Loại thuốc mới hiện đang ở giai đoạn thử nghiệm cuối cùng."},{"en":"Relations between the two firms have entered a new phase.","vi":"Quan hệ giữa hai công ty đã bước sang một giai đoạn mới."}]','[{"phrase":"first phase"},{"phrase":"final phase"},{"phrase":"enter a new phase"},{"phrase":"phase of"}]',NULL,'/feɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pha/phase/phase__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2944,'awl-4-02',14,'predict','dự đoán; dự báo','verb','[{"en":"Experts predict that prices will rise again next year.","vi":"Các chuyên gia dự đoán giá cả sẽ lại tăng vào năm tới."},{"en":"It is difficult to predict how customers will react.","vi":"Thật khó để dự đoán khách hàng sẽ phản ứng thế nào."},{"en":"The model accurately predicted the amount of rainfall last month.","vi":"Mô hình đã dự báo chính xác lượng mưa trong tháng trước."}]','[{"phrase":"accurately predict"},{"phrase":"difficult to predict"},{"phrase":"predict the future"},{"phrase":"predict that"}]',NULL,'/prɪˈdɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/predi/predict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2945,'awl-4-02',15,'principal','chính; chủ yếu','adjective','[{"en":"The principal aim of this study is to measure stress levels.","vi":"Mục tiêu chính của nghiên cứu này là đo mức độ căng thẳng."},{"en":"Tourism is the principal source of income for the island.","vi":"Du lịch là nguồn thu nhập chủ yếu của hòn đảo."},{"en":"Rising costs were the principal reason for the delay.","vi":"Chi phí tăng là lý do chính dẫn đến sự chậm trễ."}]','[{"phrase":"principal aim"},{"phrase":"principal source"},{"phrase":"principal reason"}]','principal (chính) ≠ principle (nguyên tắc); danh từ: hiệu trưởng','/ˈprɪnsəpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2946,'awl-4-02',16,'prior','trước; có từ trước','adjective','[{"en":"No prior experience is required for this position.","vi":"Vị trí này không yêu cầu kinh nghiệm từ trước."},{"en":"Participants signed a consent form prior to the interview.","vi":"Những người tham gia đã ký giấy đồng ý trước buổi phỏng vấn."},{"en":"Please give us prior notice if you plan to cancel.","vi":"Vui lòng báo trước cho chúng tôi nếu bạn định hủy."}]','[{"phrase":"prior experience"},{"phrase":"prior knowledge"},{"phrase":"prior notice"},{"phrase":"prior to"}]','prior to = before (trang trọng)','/ˈpraɪər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/prior__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2947,'awl-4-02',17,'professional','chuyên nghiệp; (thuộc) nghề nghiệp','adjective','[{"en":"You should get professional advice before signing the contract.","vi":"Bạn nên nhờ chuyên gia tư vấn trước khi ký hợp đồng."},{"en":"The course supports teachers in their professional development.","vi":"Khóa học hỗ trợ giáo viên trong việc phát triển nghề nghiệp."},{"en":"The hotel staff were friendly and very professional.","vi":"Nhân viên khách sạn thân thiện và rất chuyên nghiệp."}]','[{"phrase":"professional advice"},{"phrase":"professional development"},{"phrase":"highly professional"},{"phrase":"professional training"}]','danh từ: professional = người chuyên nghiệp','/prəˈfeʃənl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/professional__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2948,'awl-4-02',18,'project','dự án; đề án','noun','[{"en":"The research project is funded by the university.","vi":"Dự án nghiên cứu này được trường đại học tài trợ."},{"en":"She is managing a large construction project in the city center.","vi":"Cô ấy đang quản lý một dự án xây dựng lớn ở trung tâm thành phố."},{"en":"Students must complete a group project by the end of term.","vi":"Sinh viên phải hoàn thành một đề án nhóm trước cuối học kỳ."}]','[{"phrase":"research project"},{"phrase":"manage a project"},{"phrase":"group project"},{"phrase":"project manager"}]','động từ project /prəˈdʒekt/ = dự kiến, chiếu','/ˈprɑːdʒekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proje/project__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2949,'awl-4-02',19,'promote','thúc đẩy; quảng bá; thăng chức','verb','[{"en":"Lower interest rates can help promote economic growth.","vi":"Lãi suất thấp hơn có thể giúp thúc đẩy tăng trưởng kinh tế."},{"en":"The company hired an agency to promote its new product.","vi":"Công ty đã thuê một đơn vị để quảng bá sản phẩm mới."},{"en":"He was promoted to senior manager after three years.","vi":"Anh ấy được thăng chức lên quản lý cấp cao sau ba năm."}]','[{"phrase":"promote growth"},{"phrase":"promote a product"},{"phrase":"be promoted to"},{"phrase":"actively promote"}]',NULL,'/prəˈməʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/promo/promote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2950,'awl-4-02',20,'regime','chế độ; cơ chế quản lý','noun','[{"en":"The country introduced a stricter tax regime last year.","vi":"Quốc gia này đã áp dụng một chế độ thuế chặt chẽ hơn vào năm ngoái."},{"en":"Athletes follow a strict training regime before major competitions.","vi":"Các vận động viên tuân theo chế độ luyện tập nghiêm ngặt trước các giải đấu lớn."},{"en":"The new regulatory regime will affect thousands of small banks.","vi":"Cơ chế quản lý mới sẽ ảnh hưởng đến hàng nghìn ngân hàng nhỏ."}]','[{"phrase":"tax regime"},{"phrase":"training regime"},{"phrase":"regulatory regime"},{"phrase":"strict regime"}]','cũng chỉ chính quyền, thường mang nghĩa tiêu cực','/reɪˈʒiːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regim/regime__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2951,'awl-4-02',21,'resolve','giải quyết; quyết định','verb','[{"en":"The two companies resolved their dispute without going to court.","vi":"Hai công ty đã giải quyết tranh chấp mà không cần ra tòa."},{"en":"We are working hard to resolve the problem as quickly as possible.","vi":"Chúng tôi đang nỗ lực giải quyết vấn đề nhanh nhất có thể."},{"en":"The committee resolved to review the policy next year.","vi":"Ủy ban đã quyết định xem xét lại chính sách vào năm sau."}]','[{"phrase":"resolve a dispute"},{"phrase":"resolve a problem"},{"phrase":"resolve an issue"},{"phrase":"resolve to do"}]',NULL,'/rɪˈzɑːlv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resol/resolve__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2952,'awl-4-02',22,'retain','giữ lại; duy trì','verb','[{"en":"The company offers higher pay to retain skilled workers.","vi":"Công ty trả lương cao hơn để giữ chân lao động có tay nghề."},{"en":"The old town has retained much of its original character.","vi":"Khu phố cổ vẫn giữ được phần lớn nét đặc trưng ban đầu."},{"en":"Some students retain information better when they study in short sessions.","vi":"Một số sinh viên ghi nhớ thông tin tốt hơn khi học theo từng buổi ngắn."}]','[{"phrase":"retain staff"},{"phrase":"retain information"},{"phrase":"retain control"},{"phrase":"retain customers"}]',NULL,'/rɪˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ret/retai/retain__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2953,'awl-4-02',23,'series','loạt; chuỗi; bộ (phim)','noun','[{"en":"The researchers conducted a series of experiments on young mice.","vi":"Các nhà nghiên cứu đã tiến hành một loạt thí nghiệm trên chuột non."},{"en":"A series of meetings will be held to discuss the proposal.","vi":"Một chuỗi cuộc họp sẽ được tổ chức để thảo luận về đề xuất."},{"en":"The television series explores the history of modern science.","vi":"Bộ phim truyền hình này tìm hiểu lịch sử của khoa học hiện đại."}]','[{"phrase":"a series of"},{"phrase":"series of experiments"},{"phrase":"television series"},{"phrase":"time series"}]','số ít và số nhiều đều là series','/ˈsɪriːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serie/series__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2954,'awl-4-02',24,'statistic','số liệu thống kê','noun','[{"en":"Official statistics show that unemployment fell last month.","vi":"Số liệu thống kê chính thức cho thấy tỷ lệ thất nghiệp đã giảm trong tháng trước."},{"en":"One worrying statistic is that few students finish the course.","vi":"Một số liệu đáng lo ngại là rất ít sinh viên hoàn thành khóa học."},{"en":"The report includes statistics on housing costs in major cities.","vi":"Báo cáo có kèm số liệu thống kê về chi phí nhà ở tại các thành phố lớn."}]','[{"phrase":"official statistics"},{"phrase":"statistics show"},{"phrase":"latest statistics"}]','statistics (không đếm được) = môn thống kê học','/stəˈtɪstɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stati/statistic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2955,'awl-4-02',25,'status','địa vị; tình trạng; vị thế','noun','[{"en":"Doctors enjoy high social status in many countries.","vi":"Ở nhiều quốc gia, bác sĩ có địa vị xã hội cao."},{"en":"You can check the status of your application online.","vi":"Bạn có thể kiểm tra tình trạng hồ sơ của mình trực tuyến."},{"en":"The city''s status as a financial center attracts foreign investors.","vi":"Vị thế trung tâm tài chính của thành phố thu hút các nhà đầu tư nước ngoài."}]','[{"phrase":"social status"},{"phrase":"legal status"},{"phrase":"status as"},{"phrase":"check the status"}]',NULL,'/ˈsteɪtəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/statu/status__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2956,'awl-4-02',26,'stress','căng thẳng; áp lực; sự nhấn mạnh','noun','[{"en":"Long working hours can lead to high levels of stress.","vi":"Làm việc nhiều giờ có thể dẫn đến mức độ căng thẳng cao."},{"en":"Many students suffer from stress during exam periods.","vi":"Nhiều sinh viên bị áp lực trong mùa thi."},{"en":"The report places great stress on the need for training.","vi":"Báo cáo đặc biệt nhấn mạnh sự cần thiết của việc đào tạo."}]','[{"phrase":"suffer from stress"},{"phrase":"levels of stress"},{"phrase":"under stress"},{"phrase":"place stress on"}]','động từ: stress = nhấn mạnh; không đếm được (nghĩa căng thẳng)','/stres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stres/stress__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2957,'awl-4-02',27,'subsequent','tiếp theo; sau đó','adjective','[{"en":"Subsequent research has confirmed the findings of the original study.","vi":"Các nghiên cứu sau đó đã xác nhận kết quả của nghiên cứu ban đầu."},{"en":"The first meeting went well, but subsequent talks were less successful.","vi":"Cuộc họp đầu tiên diễn ra tốt đẹp, nhưng các cuộc đàm phán tiếp theo kém thành công hơn."},{"en":"Prices rose sharply in the months subsequent to the announcement.","vi":"Giá cả tăng mạnh trong những tháng sau thông báo."}]','[{"phrase":"subsequent research"},{"phrase":"in subsequent years"},{"phrase":"subsequent to"}]','subsequent to = after (trang trọng)','/ˈsʌbsɪkwənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subse/subsequent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2958,'awl-4-02',28,'sum','khoản tiền; tổng','noun','[{"en":"The government spent a huge sum of money on new roads.","vi":"Chính phủ đã chi một khoản tiền khổng lồ cho các con đường mới."},{"en":"The company agreed to pay a large sum to settle the case.","vi":"Công ty đồng ý trả một khoản tiền lớn để dàn xếp vụ kiện."},{"en":"The sum of the angles in a triangle is always 180 degrees.","vi":"Tổng các góc trong một tam giác luôn bằng 180 độ."}]','[{"phrase":"sum of money"},{"phrase":"large sum"},{"phrase":"lump sum"},{"phrase":"the sum of"}]',NULL,'/sʌm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/sum__/sum__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2959,'awl-4-02',29,'summary','bản tóm tắt','noun','[{"en":"Please write a brief summary of the article.","vi":"Hãy viết một bản tóm tắt ngắn gọn về bài báo."},{"en":"The report begins with a summary of the main findings.","vi":"Báo cáo mở đầu bằng phần tóm tắt các kết quả chính."},{"en":"In summary, the new policy has produced mixed results.","vi":"Tóm lại, chính sách mới đã mang lại kết quả trái chiều."}]','[{"phrase":"brief summary"},{"phrase":"summary of"},{"phrase":"in summary"},{"phrase":"executive summary"}]',NULL,'/ˈsʌməri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summa/summary__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2960,'awl-4-02',30,'undertake','tiến hành; đảm nhận; cam kết','verb','[{"en":"The university undertook a major study of student health.","vi":"Trường đại học đã tiến hành một nghiên cứu lớn về sức khỏe sinh viên."},{"en":"She agreed to undertake the role of project leader.","vi":"Cô ấy đồng ý đảm nhận vai trò trưởng dự án."},{"en":"The contractor undertook to finish the work by June.","vi":"Nhà thầu cam kết hoàn thành công việc trước tháng Sáu."}]','[{"phrase":"undertake research"},{"phrase":"undertake a study"},{"phrase":"undertake a task"},{"phrase":"undertake to do"}]','undertake – undertook – undertaken','/ˌʌndərˈteɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undertake__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2961,'awl-5-01',1,'academy','học viện; viện hàn lâm','noun','[{"en":"She trained as a pilot at a military academy for four years.","vi":"Cô ấy được đào tạo làm phi công tại một học viện quân sự trong bốn năm."},{"en":"He was accepted into the police academy after finishing college.","vi":"Anh ấy được nhận vào học viện cảnh sát sau khi học xong đại học."},{"en":"The country''s science academy has published a new report on water safety.","vi":"Viện hàn lâm khoa học của nước này vừa công bố một báo cáo mới về an toàn nguồn nước."}]','[{"phrase":"military academy"},{"phrase":"police academy"},{"phrase":"academy of sciences"}]',NULL,'/əˈkædəmi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aca/acade/academy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2962,'awl-5-01',2,'adjust','điều chỉnh; thích nghi','verb','[{"en":"The company adjusted its prices to reflect higher fuel costs.","vi":"Công ty đã điều chỉnh giá để phản ánh chi phí nhiên liệu tăng cao."},{"en":"It took the new students several weeks to adjust to university life.","vi":"Các sinh viên mới phải mất vài tuần để thích nghi với cuộc sống đại học."},{"en":"All figures have been adjusted for inflation to allow fair comparisons.","vi":"Tất cả số liệu đã được điều chỉnh theo lạm phát để có thể so sánh công bằng."}]','[{"phrase":"adjust to"},{"phrase":"adjust for inflation"},{"phrase":"adjust accordingly"}]','adjust to + danh từ / V-ing: thích nghi với','/əˈdʒʌst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjus/adjust__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2963,'awl-5-01',3,'alter','thay đổi; sửa đổi','verb','[{"en":"The new evidence does not alter our main conclusions.","vi":"Bằng chứng mới không làm thay đổi các kết luận chính của chúng tôi."},{"en":"Rising temperatures could significantly alter the habitats of many species.","vi":"Nhiệt độ tăng có thể làm thay đổi đáng kể môi trường sống của nhiều loài."},{"en":"The plans were altered after residents raised concerns about traffic.","vi":"Kế hoạch đã được sửa đổi sau khi người dân bày tỏ lo ngại về giao thông."}]','[{"phrase":"significantly alter"},{"phrase":"radically alter"},{"phrase":"alter the situation"}]',NULL,'/ˈɔːltər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alter__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2964,'awl-5-01',4,'amend','sửa đổi; bổ sung','verb','[{"en":"Please amend the contract before sending it to the client.","vi":"Vui lòng sửa đổi hợp đồng trước khi gửi cho khách hàng."},{"en":"Lawmakers voted to amend the law on data protection.","vi":"Các nhà lập pháp đã bỏ phiếu sửa đổi luật về bảo vệ dữ liệu."},{"en":"The company rules were amended to allow staff to work from home.","vi":"Nội quy công ty đã được sửa đổi để cho phép nhân viên làm việc tại nhà."}]','[{"phrase":"amend the law"},{"phrase":"amend the contract"},{"phrase":"amended version"}]',NULL,'/əˈmend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ame/amend/amend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2965,'awl-5-01',5,'aware','nhận thức được; biết','adjective','[{"en":"Many patients are not aware of the risks of the treatment.","vi":"Nhiều bệnh nhân không nhận thức được những rủi ro của phương pháp điều trị."},{"en":"We only became aware of the problem after customers complained.","vi":"Chúng tôi chỉ biết đến vấn đề sau khi khách hàng phàn nàn."},{"en":"Staff should be aware that the building will close early on Friday.","vi":"Nhân viên cần biết rằng tòa nhà sẽ đóng cửa sớm vào thứ Sáu."}]','[{"phrase":"aware of"},{"phrase":"become aware"},{"phrase":"fully aware"},{"phrase":"well aware"}]','aware of + danh từ / aware that + mệnh đề','/əˈwer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/aware/aware__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2966,'awl-5-01',6,'capacity','sức chứa; công suất; năng lực','noun','[{"en":"The stadium has a capacity of about forty thousand people.","vi":"Sân vận động có sức chứa khoảng bốn mươi nghìn người."},{"en":"The factory is now running at full capacity.","vi":"Nhà máy hiện đang hoạt động hết công suất."},{"en":"Some children have a greater capacity for learning languages than others.","vi":"Một số trẻ có năng lực học ngôn ngữ lớn hơn những trẻ khác."}]','[{"phrase":"full capacity"},{"phrase":"production capacity"},{"phrase":"seating capacity"},{"phrase":"capacity for"}]',NULL,'/kəˈpæsəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capac/capacity__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2967,'awl-5-01',7,'challenge','thách thức; thử thách','noun','[{"en":"Climate change is one of the biggest challenges facing the world today.","vi":"Biến đổi khí hậu là một trong những thách thức lớn nhất mà thế giới đang đối mặt hiện nay."},{"en":"The new manager faces the challenge of reducing costs without cutting jobs.","vi":"Người quản lý mới phải đối mặt với thách thức giảm chi phí mà không cắt giảm việc làm."},{"en":"Learning to write academic essays was a real challenge for her.","vi":"Học viết bài luận học thuật là một thử thách thực sự đối với cô ấy."}]','[{"phrase":"face a challenge"},{"phrase":"major challenge"},{"phrase":"meet the challenge"},{"phrase":"pose a challenge"}]',NULL,'/ˈtʃælɪndʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chall/challenge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2968,'awl-5-01',8,'clause','điều khoản; mệnh đề','noun','[{"en":"The contract includes a clause that protects the company from losses.","vi":"Hợp đồng có một điều khoản bảo vệ công ty khỏi thua lỗ."},{"en":"Both sides agreed to remove the disputed clause from the agreement.","vi":"Cả hai bên đồng ý loại bỏ điều khoản đang tranh chấp khỏi thỏa thuận."},{"en":"In this sentence, the second clause explains the reason for the delay.","vi":"Trong câu này, mệnh đề thứ hai giải thích lý do của sự chậm trễ."}]','[{"phrase":"clause in the contract"},{"phrase":"include a clause"},{"phrase":"relative clause"}]',NULL,'/klɔːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/claus/clause__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2969,'awl-5-01',9,'compound','hợp chất; từ ghép','noun','[{"en":"Researchers found several harmful compounds in the drinking water.","vi":"Các nhà nghiên cứu đã phát hiện một số hợp chất độc hại trong nước uống."},{"en":"Water is a compound of hydrogen and oxygen.","vi":"Nước là hợp chất của hydro và oxy."},{"en":"In English, many compounds are formed by joining two shorter words.","vi":"Trong tiếng Anh, nhiều từ ghép được tạo thành bằng cách ghép hai từ ngắn hơn."}]','[{"phrase":"chemical compound"},{"phrase":"organic compound"},{"phrase":"compound of"}]',NULL,'/ˈkɑːmpaʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/compound__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2970,'awl-5-01',10,'conflict','xung đột; mâu thuẫn','noun','[{"en":"Managers need clear strategies for resolving conflicts between team members.","vi":"Các nhà quản lý cần có chiến lược rõ ràng để giải quyết xung đột giữa các thành viên trong nhóm."},{"en":"There is a clear conflict between the two sets of results.","vi":"Có sự mâu thuẫn rõ ràng giữa hai bộ kết quả."},{"en":"Board members must declare any conflict of interest before the vote.","vi":"Các thành viên hội đồng quản trị phải khai báo mọi xung đột lợi ích trước khi bỏ phiếu."}]','[{"phrase":"resolve a conflict"},{"phrase":"conflict of interest"},{"phrase":"conflict between"},{"phrase":"in conflict with"}]',NULL,'/ˈkɑːnflɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconflict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2971,'awl-5-01',11,'consult','hỏi ý kiến; tham khảo','verb','[{"en":"You should consult a doctor before starting any new exercise program.","vi":"Bạn nên hỏi ý kiến bác sĩ trước khi bắt đầu bất kỳ chương trình tập luyện mới nào."},{"en":"The city council consulted local residents before approving the new park.","vi":"Hội đồng thành phố đã hỏi ý kiến người dân địa phương trước khi phê duyệt công viên mới."},{"en":"Students are encouraged to consult a range of sources for their essays.","vi":"Sinh viên được khuyến khích tham khảo nhiều nguồn tài liệu khác nhau cho bài luận."}]','[{"phrase":"consult a doctor"},{"phrase":"consult a lawyer"},{"phrase":"consult with"}]','consult + người: hỏi ý kiến · consult + tài liệu: tra cứu, tham khảo','/kənˈsʌlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsult__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2972,'awl-5-01',12,'contact','sự liên lạc; sự tiếp xúc; người quen','noun','[{"en":"The research team stays in regular contact with local hospitals.","vi":"Nhóm nghiên cứu thường xuyên giữ liên lạc với các bệnh viện địa phương."},{"en":"The virus spreads through close contact with infected animals.","vi":"Vi-rút lây lan qua tiếp xúc gần với động vật bị nhiễm bệnh."},{"en":"She has many useful contacts in the publishing industry.","vi":"Cô ấy có nhiều người quen hữu ích trong ngành xuất bản."}]','[{"phrase":"in contact with"},{"phrase":"close contact"},{"phrase":"make contact"},{"phrase":"business contacts"}]',NULL,'/ˈkɑːntækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontact__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2973,'awl-5-01',13,'decline','giảm sút; từ chối','verb','[{"en":"The number of students taking foreign languages has declined sharply.","vi":"Số lượng sinh viên học ngoại ngữ đã giảm mạnh."},{"en":"Sales continued to decline during the second half of the year.","vi":"Doanh số tiếp tục giảm trong nửa cuối năm."},{"en":"The company declined to comment on reports of job cuts.","vi":"Công ty từ chối bình luận về các thông tin cắt giảm việc làm."}]','[{"phrase":"decline sharply"},{"phrase":"decline steadily"},{"phrase":"decline to comment"}]','decline to + V: từ chối làm gì (lịch sự, trang trọng)','/dɪˈklaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decli/decline__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2974,'awl-5-01',14,'discrete','riêng biệt; rời rạc','adjective','[{"en":"The course is divided into six discrete units.","vi":"Khóa học được chia thành sáu học phần riêng biệt."},{"en":"The project can be broken down into several discrete tasks.","vi":"Dự án có thể được chia nhỏ thành nhiều nhiệm vụ riêng biệt."},{"en":"Unlike height, the number of children in a family is a discrete variable.","vi":"Khác với chiều cao, số con trong một gia đình là biến rời rạc."}]','[{"phrase":"discrete units"},{"phrase":"discrete categories"},{"phrase":"discrete variable"}]','discrete (riêng biệt) ≠ discreet (kín đáo)','/dɪˈskriːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discr/discrete__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2975,'awl-5-01',15,'draft','bản nháp; bản dự thảo','noun','[{"en":"I sent my supervisor the first draft of my thesis yesterday.","vi":"Hôm qua tôi đã gửi bản nháp đầu tiên của luận văn cho người hướng dẫn."},{"en":"A draft of the new policy will be shared with staff next week.","vi":"Bản dự thảo chính sách mới sẽ được gửi cho nhân viên vào tuần tới."},{"en":"The final draft included several changes suggested by the reviewers.","vi":"Bản thảo cuối cùng có một số thay đổi do những người phản biện đề xuất."}]','[{"phrase":"first draft"},{"phrase":"final draft"},{"phrase":"rough draft"},{"phrase":"draft of"}]',NULL,'/dræft/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/draft/draft__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2976,'awl-5-01',16,'enable','cho phép; giúp có thể','verb','[{"en":"The new software enables researchers to process data much faster.","vi":"Phần mềm mới giúp các nhà nghiên cứu xử lý dữ liệu nhanh hơn nhiều."},{"en":"Online courses enable people to study while working full-time.","vi":"Các khóa học trực tuyến cho phép mọi người vừa học vừa làm việc toàn thời gian."},{"en":"The grant will enable the school to build a new science lab.","vi":"Khoản tài trợ sẽ giúp nhà trường có thể xây một phòng thí nghiệm khoa học mới."}]','[{"phrase":"enable people to"},{"phrase":"enable users to"},{"phrase":"enable someone to do something"}]','enable + tân ngữ + to V','/ɪˈneɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ena/enabl/enable__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2977,'awl-5-01',17,'energy','năng lượng; sức lực','noun','[{"en":"Many countries are investing heavily in renewable energy.","vi":"Nhiều quốc gia đang đầu tư mạnh vào năng lượng tái tạo."},{"en":"New buildings must meet strict standards for energy efficiency.","vi":"Các tòa nhà mới phải đáp ứng tiêu chuẩn nghiêm ngặt về hiệu quả năng lượng."},{"en":"After a long day of meetings, I had no energy left.","vi":"Sau một ngày dài họp hành, tôi không còn chút sức lực nào."}]','[{"phrase":"renewable energy"},{"phrase":"energy efficiency"},{"phrase":"energy consumption"},{"phrase":"solar energy"}]',NULL,'/ˈenərdʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ene/energ/energy__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2978,'awl-5-01',18,'enforce','thực thi; buộc tuân theo','verb','[{"en":"Police officers are responsible for enforcing the law.","vi":"Cảnh sát chịu trách nhiệm thực thi pháp luật."},{"en":"The school strictly enforces its rules on mobile phone use.","vi":"Nhà trường thực thi nghiêm ngặt các quy định về việc sử dụng điện thoại di động."},{"en":"The new safety regulations will be enforced from next January.","vi":"Các quy định an toàn mới sẽ được áp dụng bắt buộc từ tháng Một năm sau."}]','[{"phrase":"enforce the law"},{"phrase":"strictly enforce"},{"phrase":"enforce rules"},{"phrase":"enforce regulations"}]',NULL,'/ɪnˈfɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enf/enfor/enforce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2979,'awl-5-01',19,'entity','thực thể; pháp nhân','noun','[{"en":"The two companies will continue to operate as separate legal entities.","vi":"Hai công ty sẽ tiếp tục hoạt động như những pháp nhân riêng biệt."},{"en":"In the database, each customer is stored as a separate entity.","vi":"Trong cơ sở dữ liệu, mỗi khách hàng được lưu dưới dạng một thực thể riêng."},{"en":"The university and its research institute are now a single entity.","vi":"Trường đại học và viện nghiên cứu của trường nay đã trở thành một thực thể duy nhất."}]','[{"phrase":"legal entity"},{"phrase":"separate entity"},{"phrase":"single entity"},{"phrase":"business entity"}]',NULL,'/ˈentəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ent/entit/entity__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2980,'awl-5-01',20,'equivalent','tương đương; vật tương đương','adjective','[{"en":"Applicants need a bachelor''s degree or an equivalent qualification.","vi":"Ứng viên cần có bằng cử nhân hoặc bằng cấp tương đương."},{"en":"The fine is equivalent to three months'' salary.","vi":"Khoản tiền phạt tương đương với ba tháng lương."},{"en":"There is no exact equivalent of this word in Vietnamese.","vi":"Từ này không có từ tương đương chính xác trong tiếng Việt."}]','[{"phrase":"equivalent to"},{"phrase":"roughly equivalent"},{"phrase":"exact equivalent"}]','equivalent to (tính từ) · equivalent of (danh từ)','/ɪˈkwɪvələnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equiv/equivalent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2981,'awl-5-01',21,'evolve','tiến hóa; phát triển dần','verb','[{"en":"Scientists believe that birds evolved from small dinosaurs.","vi":"Các nhà khoa học tin rằng chim đã tiến hóa từ những loài khủng long nhỏ."},{"en":"The company has evolved from a small shop into a global business.","vi":"Công ty đã phát triển từ một cửa hàng nhỏ thành một doanh nghiệp toàn cầu."},{"en":"Teaching methods continue to evolve as technology changes.","vi":"Các phương pháp giảng dạy tiếp tục phát triển khi công nghệ thay đổi."}]','[{"phrase":"evolve from"},{"phrase":"evolve into"},{"phrase":"continue to evolve"},{"phrase":"rapidly evolving"}]',NULL,'/ɪˈvɑːlv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/evo/evolv/evolve__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2982,'awl-5-01',22,'expand','mở rộng; giãn nở','verb','[{"en":"The company plans to expand into Asian markets next year.","vi":"Công ty dự định mở rộng sang các thị trường châu Á vào năm tới."},{"en":"The university has expanded its online programs to reach more students.","vi":"Trường đại học đã mở rộng các chương trình trực tuyến để tiếp cận nhiều sinh viên hơn."},{"en":"Most metals expand slightly when they are heated.","vi":"Hầu hết kim loại giãn nở nhẹ khi bị nung nóng."}]','[{"phrase":"expand into"},{"phrase":"expand rapidly"},{"phrase":"expand services"}]',NULL,'/ɪkˈspænd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expan/expand__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2983,'awl-5-01',23,'expose','cho tiếp xúc; phơi bày','verb','[{"en":"Studying abroad exposes students to new ideas and cultures.","vi":"Du học giúp sinh viên tiếp xúc với những ý tưởng và nền văn hóa mới."},{"en":"Workers who are exposed to loud noise may suffer hearing loss.","vi":"Những công nhân tiếp xúc với tiếng ồn lớn có thể bị suy giảm thính lực."},{"en":"The investigation exposed serious weaknesses in the company''s safety system.","vi":"Cuộc điều tra đã phơi bày những điểm yếu nghiêm trọng trong hệ thống an toàn của công ty."}]','[{"phrase":"exposed to"},{"phrase":"expose the truth"},{"phrase":"expose weaknesses"}]','expose sb/sth to sth: để ai/cái gì tiếp xúc với','/ɪkˈspəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expos/expose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2984,'awl-5-01',24,'external','bên ngoài','adjective','[{"en":"The report was reviewed by two external experts.","vi":"Báo cáo đã được hai chuyên gia bên ngoài thẩm định."},{"en":"Small businesses are often hit hardest by external factors like rising costs.","vi":"Các doanh nghiệp nhỏ thường bị ảnh hưởng nặng nề nhất bởi các yếu tố bên ngoài như chi phí tăng."},{"en":"This cream is for external use only.","vi":"Loại kem này chỉ dùng ngoài da."}]','[{"phrase":"external factors"},{"phrase":"external examiner"},{"phrase":"external use"},{"phrase":"external pressure"}]','external ≠ internal (bên trong)','/ɪkˈstɜːrnl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exter/external__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2985,'awl-5-01',25,'facilitate','tạo điều kiện thuận lợi; điều phối','verb','[{"en":"Good lighting and quiet spaces can facilitate learning.","vi":"Ánh sáng tốt và không gian yên tĩnh có thể tạo điều kiện thuận lợi cho việc học."},{"en":"The new bridge will facilitate trade between the two regions.","vi":"Cây cầu mới sẽ tạo thuận lợi cho giao thương giữa hai vùng."},{"en":"An experienced teacher facilitated the group discussion.","vi":"Một giáo viên giàu kinh nghiệm đã điều phối buổi thảo luận nhóm."}]','[{"phrase":"facilitate learning"},{"phrase":"facilitate communication"},{"phrase":"facilitate trade"},{"phrase":"facilitate a discussion"}]',NULL,'/fəˈsɪlɪteɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facil/facilitate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2986,'awl-5-01',26,'fundamental','cơ bản; căn bản','adjective','[{"en":"There is a fundamental difference between these two approaches.","vi":"Có một sự khác biệt cơ bản giữa hai cách tiếp cận này."},{"en":"Access to clean water is a fundamental human right.","vi":"Được tiếp cận nước sạch là một quyền cơ bản của con người."},{"en":"The company needs to make fundamental changes to the way it operates.","vi":"Công ty cần thực hiện những thay đổi căn bản trong cách vận hành."}]','[{"phrase":"fundamental difference"},{"phrase":"fundamental change"},{"phrase":"fundamental right"},{"phrase":"fundamental principle"}]',NULL,'/ˌfʌndəˈmentl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funda/fundamental__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2987,'awl-5-01',27,'generate','tạo ra; sản sinh','verb','[{"en":"Tourism generates about a third of the region''s income.","vi":"Du lịch tạo ra khoảng một phần ba thu nhập của khu vực."},{"en":"Wind turbines generate electricity without producing harmful emissions.","vi":"Tua-bin gió sản sinh điện năng mà không thải ra khí độc hại."},{"en":"The proposal has generated a lot of interest among investors.","vi":"Đề xuất này đã tạo ra nhiều sự quan tâm trong giới đầu tư."}]','[{"phrase":"generate income"},{"phrase":"generate electricity"},{"phrase":"generate interest"},{"phrase":"generate revenue"}]',NULL,'/ˈdʒenəreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2988,'awl-5-01',28,'generation','thế hệ; sự sản xuất','noun','[{"en":"Young people of this generation spend much of their time online.","vi":"Người trẻ thuộc thế hệ này dành phần lớn thời gian trên mạng."},{"en":"The family business has been passed down through three generations.","vi":"Công việc kinh doanh của gia đình đã được truyền qua ba thế hệ."},{"en":"Coal is still widely used for electricity generation in many countries.","vi":"Than vẫn được sử dụng rộng rãi để sản xuất điện ở nhiều quốc gia."}]','[{"phrase":"younger generation"},{"phrase":"future generations"},{"phrase":"next generation"},{"phrase":"electricity generation"}]',NULL,'/ˌdʒenəˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2989,'awl-5-01',29,'image','hình ảnh; hình tượng','noun','[{"en":"The company is trying to improve its public image after a difficult year.","vi":"Công ty đang cố gắng cải thiện hình ảnh trước công chúng sau một năm khó khăn."},{"en":"Satellite images show that the forest has shrunk significantly.","vi":"Ảnh vệ tinh cho thấy khu rừng đã bị thu hẹp đáng kể."},{"en":"Advertising often presents an unrealistic image of family life.","vi":"Quảng cáo thường đưa ra một hình ảnh thiếu thực tế về cuộc sống gia đình."}]','[{"phrase":"public image"},{"phrase":"satellite image"},{"phrase":"positive image"},{"phrase":"image of"}]',NULL,'/ˈɪmɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/image/image__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2990,'awl-5-01',30,'liberal','cởi mở; phóng khoáng; rộng rãi','adjective','[{"en":"She has fairly liberal views on how children should be raised.","vi":"Bà ấy có quan điểm khá cởi mở về cách nuôi dạy con cái."},{"en":"The company has a liberal policy on working from home.","vi":"Công ty có chính sách cởi mở về việc làm việc tại nhà."},{"en":"Students are encouraged to make liberal use of the library''s resources.","vi":"Sinh viên được khuyến khích sử dụng rộng rãi các tài nguyên của thư viện."}]','[{"phrase":"liberal views"},{"phrase":"liberal attitude"},{"phrase":"liberal use of"},{"phrase":"liberal arts"}]',NULL,'/ˈlɪbərəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lib/liber/liberal__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2991,'awl-6-02',1,'incidence','tỷ lệ mắc; mức độ xảy ra','noun','[{"en":"The incidence of heart disease is higher among older men.","vi":"Tỷ lệ mắc bệnh tim cao hơn ở nam giới lớn tuổi."},{"en":"Researchers recorded a sharp rise in the incidence of childhood asthma.","vi":"Các nhà nghiên cứu ghi nhận tỷ lệ mắc hen suyễn ở trẻ em tăng mạnh."},{"en":"Better street lighting has reduced the incidence of crime in the area.","vi":"Đèn đường tốt hơn đã làm giảm mức độ xảy ra tội phạm trong khu vực."}]','[{"phrase":"high incidence"},{"phrase":"incidence of disease"},{"phrase":"increase in the incidence"},{"phrase":"reduce the incidence"}]','incidence of + danh từ','/ˈɪnsɪdəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incid/incidence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2992,'awl-6-02',2,'incorporate','kết hợp; đưa vào; sáp nhập','verb','[{"en":"The new design incorporates feedback from hundreds of users.","vi":"Thiết kế mới kết hợp ý kiến phản hồi từ hàng trăm người dùng."},{"en":"Teachers are encouraged to incorporate technology into their lessons.","vi":"Giáo viên được khuyến khích đưa công nghệ vào bài giảng của mình."},{"en":"Several small firms were incorporated into the larger company last year.","vi":"Năm ngoái, một số công ty nhỏ đã được sáp nhập vào công ty lớn hơn."}]','[{"phrase":"incorporate into"},{"phrase":"incorporate ideas"},{"phrase":"incorporate changes"},{"phrase":"fully incorporate"}]','incorporate A into B','/ɪnˈkɔːrpəreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incor/incorporate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2993,'awl-6-02',3,'index','chỉ số; mục lục tra cứu','noun','[{"en":"The consumer price index rose by two percent last month.","vi":"Chỉ số giá tiêu dùng đã tăng hai phần trăm vào tháng trước."},{"en":"You can find the topic quickly by checking the index at the back.","vi":"Bạn có thể tìm chủ đề nhanh chóng bằng cách xem mục lục tra cứu ở cuối sách."},{"en":"Body mass index is a common measure of healthy weight.","vi":"Chỉ số khối cơ thể là một thước đo phổ biến về cân nặng khỏe mạnh."}]','[{"phrase":"price index"},{"phrase":"stock market index"},{"phrase":"body mass index"},{"phrase":"index of"}]','Số nhiều: indexes hoặc indices','/ˈɪndeks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/index/index__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2994,'awl-6-02',4,'inhibit','ức chế; kìm hãm; cản trở','verb','[{"en":"High interest rates may inhibit economic growth.","vi":"Lãi suất cao có thể kìm hãm tăng trưởng kinh tế."},{"en":"This drug inhibits the growth of cancer cells in the laboratory.","vi":"Loại thuốc này ức chế sự phát triển của tế bào ung thư trong phòng thí nghiệm."},{"en":"Fear of making mistakes can inhibit students from speaking in class.","vi":"Nỗi sợ mắc lỗi có thể cản trở học sinh phát biểu trong lớp."}]','[{"phrase":"inhibit growth"},{"phrase":"inhibit the development"},{"phrase":"inhibit someone from doing"}]','inhibit sb from doing sth','/ɪnˈhɪbɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inh/inhib/inhibit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2995,'awl-6-02',5,'initiate','bắt đầu; khởi xướng','verb','[{"en":"The government initiated a program to improve rural schools.","vi":"Chính phủ đã khởi xướng một chương trình nhằm cải thiện các trường học ở nông thôn."},{"en":"Only a manager can initiate the payment process.","vi":"Chỉ người quản lý mới có thể bắt đầu quy trình thanh toán."},{"en":"The company has initiated legal action against its former supplier.","vi":"Công ty đã bắt đầu khởi kiện nhà cung cấp cũ của mình."}]','[{"phrase":"initiate a program"},{"phrase":"initiate legal action"},{"phrase":"initiate change"},{"phrase":"initiate a process"}]',NULL,'/ɪˈnɪʃieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ini/initi/initiate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2996,'awl-6-02',6,'input','ý kiến đóng góp; dữ liệu đầu vào','noun','[{"en":"We would welcome your input on the draft proposal.","vi":"Chúng tôi rất mong nhận được ý kiến đóng góp của bạn về bản dự thảo đề xuất."},{"en":"The final plan was shaped by input from local residents.","vi":"Kế hoạch cuối cùng được hình thành dựa trên ý kiến đóng góp của người dân địa phương."},{"en":"The program checks every input before saving it to the database.","vi":"Chương trình kiểm tra mọi dữ liệu đầu vào trước khi lưu vào cơ sở dữ liệu."}]','[{"phrase":"input from"},{"phrase":"input into"},{"phrase":"provide input"},{"phrase":"valuable input"}]','Nghĩa ''ý kiến đóng góp'' thường không đếm được','/ˈɪnpʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inp/input/input__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2997,'awl-6-02',7,'instruct','chỉ thị; hướng dẫn; dạy','verb','[{"en":"Staff were instructed to leave the building immediately.","vi":"Nhân viên được chỉ thị rời khỏi tòa nhà ngay lập tức."},{"en":"The nurse instructed patients on how to take the medicine.","vi":"Y tá hướng dẫn bệnh nhân cách uống thuốc."},{"en":"Volunteers instruct children in basic swimming skills every summer.","vi":"Mỗi mùa hè, các tình nguyện viên dạy trẻ em những kỹ năng bơi cơ bản."}]','[{"phrase":"instruct someone to do"},{"phrase":"instruct someone in"},{"phrase":"clearly instruct"}]','instruct sb to do sth','/ɪnˈstrʌkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/instr/instruct__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2998,'awl-6-02',8,'intelligent','thông minh','adjective','[{"en":"She is a highly intelligent student with a talent for mathematics.","vi":"Cô ấy là một học sinh rất thông minh và có năng khiếu toán học."},{"en":"Scientists are building intelligent systems that can learn from data.","vi":"Các nhà khoa học đang xây dựng những hệ thống thông minh có thể học từ dữ liệu."},{"en":"Dolphins are considered some of the most intelligent animals on Earth.","vi":"Cá heo được xem là một trong những loài động vật thông minh nhất trên Trái Đất."}]','[{"phrase":"highly intelligent"},{"phrase":"intelligent system"},{"phrase":"intelligent design"},{"phrase":"intelligent life"}]',NULL,'/ɪnˈtelɪdʒənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intel/intelligent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(2999,'awl-6-02',9,'interval','khoảng thời gian; khoảng cách','noun','[{"en":"Buses leave the station at regular intervals throughout the day.","vi":"Xe buýt rời bến theo những khoảng thời gian đều đặn suốt cả ngày."},{"en":"Blood samples were taken at intervals of four hours.","vi":"Mẫu máu được lấy cách nhau bốn giờ một lần."},{"en":"There was a short interval between the two experiments.","vi":"Có một khoảng thời gian ngắn giữa hai thí nghiệm."}]','[{"phrase":"at regular intervals"},{"phrase":"at intervals of"},{"phrase":"short interval"},{"phrase":"time interval"}]',NULL,'/ˈɪntərvl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/interval__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3000,'awl-6-02',10,'lecture','bài giảng; bài diễn thuyết','noun','[{"en":"The professor gave a lecture on climate change and food security.","vi":"Giáo sư đã có một bài giảng về biến đổi khí hậu và an ninh lương thực."},{"en":"Students who miss a lecture can watch the recording online.","vi":"Sinh viên nào bỏ lỡ bài giảng có thể xem bản ghi trên mạng."},{"en":"Over three hundred people attended her public lecture last night.","vi":"Hơn ba trăm người đã tham dự buổi diễn thuyết công khai của bà tối qua."}]','[{"phrase":"give a lecture"},{"phrase":"attend a lecture"},{"phrase":"lecture on"},{"phrase":"public lecture"}]','lecture on + chủ đề','/ˈlektʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lec/lectu/lecture__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3001,'awl-6-02',11,'migrate','di cư; chuyển đổi (dữ liệu, hệ thống)','verb','[{"en":"Many young people migrate to cities in search of work.","vi":"Nhiều người trẻ di cư lên thành phố để tìm việc làm."},{"en":"These birds migrate south thousands of kilometers every winter.","vi":"Mỗi mùa đông, những loài chim này di cư hàng nghìn ki-lô-mét về phía nam."},{"en":"The company plans to migrate all its data to a new system.","vi":"Công ty dự định chuyển đổi toàn bộ dữ liệu sang một hệ thống mới."}]','[{"phrase":"migrate to"},{"phrase":"migrate from"},{"phrase":"migrate south"},{"phrase":"migrate data"}]',NULL,'/ˈmaɪɡreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mig/migra/migrate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3002,'awl-6-02',12,'minimum','mức tối thiểu','noun','[{"en":"Applicants need a minimum of three years'' experience.","vi":"Ứng viên cần tối thiểu ba năm kinh nghiệm."},{"en":"We should keep costs to a minimum during the first year.","vi":"Chúng ta nên giữ chi phí ở mức tối thiểu trong năm đầu tiên."},{"en":"Temperatures fell to a minimum of five degrees overnight.","vi":"Nhiệt độ giảm xuống mức thấp nhất là năm độ trong đêm."}]','[{"phrase":"a minimum of"},{"phrase":"keep to a minimum"},{"phrase":"bare minimum"},{"phrase":"minimum wage"}]','Cũng dùng như tính từ: minimum wage (lương tối thiểu)','/ˈmɪnɪməm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minim/minimum__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3003,'awl-6-02',13,'ministry','bộ (cơ quan chính phủ)','noun','[{"en":"The Ministry of Education announced changes to the national exam.","vi":"Bộ Giáo dục đã công bố những thay đổi đối với kỳ thi quốc gia."},{"en":"According to the health ministry, the number of cases is falling.","vi":"Theo Bộ Y tế, số ca bệnh đang giảm."},{"en":"She worked for the finance ministry for more than ten years.","vi":"Bà đã làm việc cho Bộ Tài chính hơn mười năm."}]','[{"phrase":"Ministry of Education"},{"phrase":"health ministry"},{"phrase":"ministry official"},{"phrase":"government ministry"}]',NULL,'/ˈmɪnɪstri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minis/ministry__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3004,'awl-6-02',14,'motive','động cơ; lý do','noun','[{"en":"Police are still trying to establish a motive for the attack.","vi":"Cảnh sát vẫn đang cố xác định động cơ của vụ tấn công."},{"en":"Profit is not the only motive for starting a business.","vi":"Lợi nhuận không phải là động cơ duy nhất để khởi nghiệp."},{"en":"Some people questioned the motives behind the sudden price cut.","vi":"Một số người đặt câu hỏi về động cơ đằng sau việc giảm giá đột ngột."}]','[{"phrase":"motive for"},{"phrase":"profit motive"},{"phrase":"motive behind"},{"phrase":"hidden motive"}]','motive for + danh từ / V-ing','/ˈməʊtɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mot/motiv/motive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3005,'awl-6-02',15,'neutral','trung lập; trung tính','adjective','[{"en":"Journalists should try to remain neutral when reporting the news.","vi":"Nhà báo nên cố gắng giữ thái độ trung lập khi đưa tin."},{"en":"The talks were held in a neutral country.","vi":"Các cuộc đàm phán được tổ chức tại một quốc gia trung lập."},{"en":"Pure water has a neutral pH of seven.","vi":"Nước tinh khiết có độ pH trung tính là bảy."}]','[{"phrase":"remain neutral"},{"phrase":"neutral country"},{"phrase":"politically neutral"},{"phrase":"neutral position"}]',NULL,'/ˈnuːtrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neu/neutr/neutral__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3006,'awl-6-02',16,'nevertheless','tuy nhiên; dù vậy','adverb','[{"en":"The study was small; nevertheless, its results were very useful.","vi":"Nghiên cứu có quy mô nhỏ; tuy nhiên, kết quả của nó rất hữu ích."},{"en":"The task was difficult, but they completed it on time nevertheless.","vi":"Nhiệm vụ rất khó, dù vậy họ vẫn hoàn thành đúng hạn."},{"en":"Although prices have risen sharply, demand nevertheless remains strong.","vi":"Mặc dù giá đã tăng mạnh, nhu cầu vẫn cao."}]','[{"phrase":"but nevertheless"},{"phrase":"nevertheless remain"}]','Trang trọng hơn however; thường đứng sau dấu chấm phẩy','/ˌnevərðəˈles/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nev/never/nevertheless__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3007,'awl-6-02',17,'overseas','ở nước ngoài; (thuộc) nước ngoài','adjective','[{"en":"The university has seen a rise in overseas students this year.","vi":"Năm nay trường đại học có số lượng sinh viên nước ngoài tăng lên."},{"en":"Many firms are looking for new overseas markets.","vi":"Nhiều công ty đang tìm kiếm các thị trường mới ở nước ngoài."},{"en":"After graduating, he spent two years working overseas.","vi":"Sau khi tốt nghiệp, anh ấy đã làm việc ở nước ngoài hai năm."}]','[{"phrase":"overseas students"},{"phrase":"overseas markets"},{"phrase":"work overseas"},{"phrase":"overseas investment"}]','Cũng là trạng từ: live/work overseas','/ˌəʊvərˈsiːz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overs/overseas__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3008,'awl-6-02',18,'precede','đi trước; diễn ra trước','verb','[{"en":"A short discussion of the proposal preceded the final vote.","vi":"Trước cuộc bỏ phiếu cuối cùng là một cuộc thảo luận ngắn về đề xuất."},{"en":"The economic crisis was preceded by years of rapid growth.","vi":"Trước cuộc khủng hoảng kinh tế là nhiều năm tăng trưởng nhanh."},{"en":"In English, adjectives usually precede the nouns they describe.","vi":"Trong tiếng Anh, tính từ thường đứng trước danh từ mà nó bổ nghĩa."}]','[{"phrase":"immediately precede"},{"phrase":"be preceded by"},{"phrase":"the preceding year"}]','precede ≠ proceed (tiếp tục)','/prɪˈsiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prece/precede__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3009,'awl-6-02',19,'presume','cho rằng; giả định','verb','[{"en":"I presume the meeting will start at nine as usual.","vi":"Tôi cho rằng cuộc họp sẽ bắt đầu lúc chín giờ như thường lệ."},{"en":"In law, a person is presumed innocent until proven guilty.","vi":"Theo luật, một người được giả định là vô tội cho đến khi bị chứng minh có tội."},{"en":"The researchers presumed that all participants had answered honestly.","vi":"Các nhà nghiên cứu giả định rằng tất cả người tham gia đều trả lời trung thực."}]','[{"phrase":"presume that"},{"phrase":"presumed innocent"},{"phrase":"reasonably presume"}]',NULL,'/prɪˈzuːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/presu/presume__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3010,'awl-6-02',20,'rational','hợp lý; lý trí','adjective','[{"en":"There must be a rational explanation for these strange results.","vi":"Chắc chắn phải có một lời giải thích hợp lý cho những kết quả kỳ lạ này."},{"en":"Economists often assume that consumers make rational decisions.","vi":"Các nhà kinh tế học thường giả định rằng người tiêu dùng đưa ra quyết định lý trí."},{"en":"It is hard to stay rational when you are under pressure.","vi":"Thật khó giữ được lý trí khi bạn đang chịu áp lực."}]','[{"phrase":"rational decision"},{"phrase":"rational explanation"},{"phrase":"rational choice"},{"phrase":"perfectly rational"}]',NULL,'/ˈræʃnəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/ratio/rational__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3011,'awl-6-02',21,'recover','hồi phục; lấy lại; thu hồi','verb','[{"en":"It took her several months to recover from the operation.","vi":"Cô ấy mất vài tháng để hồi phục sau ca phẫu thuật."},{"en":"The economy is slowly recovering after two difficult years.","vi":"Nền kinh tế đang dần hồi phục sau hai năm khó khăn."},{"en":"Engineers managed to recover most of the lost files.","vi":"Các kỹ sư đã khôi phục được phần lớn các tệp bị mất."}]','[{"phrase":"recover from"},{"phrase":"fully recover"},{"phrase":"recover costs"},{"phrase":"slowly recover"}]','recover from + bệnh / khó khăn','/rɪˈkʌvər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recov/recover__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3012,'awl-6-02',22,'reveal','tiết lộ; cho thấy','verb','[{"en":"The survey revealed that most workers want flexible hours.","vi":"Cuộc khảo sát cho thấy phần lớn người lao động muốn có giờ làm linh hoạt."},{"en":"The company refused to reveal the cost of the project.","vi":"Công ty từ chối tiết lộ chi phí của dự án."},{"en":"Blood tests revealed high levels of sugar in several patients.","vi":"Xét nghiệm máu cho thấy lượng đường cao ở một số bệnh nhân."}]','[{"phrase":"reveal that"},{"phrase":"study reveals"},{"phrase":"reveal details"},{"phrase":"reveal the truth"}]',NULL,'/rɪˈviːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revea/reveal__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3013,'awl-6-02',23,'scope','phạm vi; cơ hội (để làm gì)','noun','[{"en":"This question is beyond the scope of our study.","vi":"Câu hỏi này nằm ngoài phạm vi nghiên cứu của chúng tôi."},{"en":"The team agreed to expand the scope of the project.","vi":"Nhóm đã đồng ý mở rộng phạm vi của dự án."},{"en":"There is still plenty of scope for improvement in the service.","vi":"Dịch vụ vẫn còn nhiều cơ hội để cải thiện."}]','[{"phrase":"beyond the scope of"},{"phrase":"scope of the project"},{"phrase":"scope for improvement"},{"phrase":"broaden the scope"}]','scope for + danh từ (cơ hội cho)','/skəʊp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sco/scope/scope__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3014,'awl-6-02',24,'subsidy','tiền trợ cấp; khoản trợ giá','noun','[{"en":"Farmers receive a government subsidy to grow certain crops.","vi":"Nông dân nhận được trợ cấp của chính phủ để trồng một số loại cây nhất định."},{"en":"Fuel subsidies cost the country billions of dollars each year.","vi":"Các khoản trợ giá nhiên liệu tiêu tốn của đất nước hàng tỷ đô la mỗi năm."},{"en":"Without housing subsidies, many families could not afford rent.","vi":"Nếu không có trợ cấp nhà ở, nhiều gia đình sẽ không đủ tiền thuê nhà."}]','[{"phrase":"government subsidy"},{"phrase":"fuel subsidies"},{"phrase":"receive a subsidy"},{"phrase":"cut subsidies"}]',NULL,'/ˈsʌbsədi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subsi/subsidy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3015,'awl-6-02',25,'tape','băng dính; băng ghi âm/ghi hình','noun','[{"en":"She sealed the box with a strip of tape.","vi":"Cô ấy dán kín chiếc hộp bằng một miếng băng dính."},{"en":"All the interviews were recorded on tape for later analysis.","vi":"Tất cả các cuộc phỏng vấn đều được ghi âm lại để phân tích sau."},{"en":"Police examined security tapes from the night of the robbery.","vi":"Cảnh sát đã xem xét băng ghi hình an ninh từ đêm xảy ra vụ cướp."}]','[{"phrase":"on tape"},{"phrase":"adhesive tape"},{"phrase":"tape recording"},{"phrase":"masking tape"}]','red tape = thủ tục hành chính rườm rà','/teɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tap/tape_/tape__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3016,'awl-6-02',26,'trace','truy tìm; lần ra nguồn gốc','verb','[{"en":"Scientists traced the outbreak to a contaminated water supply.","vi":"Các nhà khoa học đã lần ra nguồn gốc dịch bệnh là do nguồn nước bị ô nhiễm."},{"en":"The police are still trying to trace the missing documents.","vi":"Cảnh sát vẫn đang cố truy tìm những tài liệu bị mất."},{"en":"The custom can be traced back to the sixteenth century.","vi":"Phong tục này có thể được truy nguồn gốc về thế kỷ mười sáu."}]','[{"phrase":"trace back to"},{"phrase":"trace the source"},{"phrase":"trace the history of"}]','Cũng là danh từ: dấu vết (without trace)','/treɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trace/trace__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3017,'awl-6-02',27,'transform','biến đổi; làm thay đổi hoàn toàn','verb','[{"en":"The internet has transformed the way people shop.","vi":"Internet đã làm thay đổi hoàn toàn cách mọi người mua sắm."},{"en":"The old factory was transformed into a modern art center.","vi":"Nhà máy cũ đã được biến thành một trung tâm nghệ thuật hiện đại."},{"en":"During photosynthesis, plants transform light energy into chemical energy.","vi":"Trong quá trình quang hợp, thực vật biến đổi quang năng thành hóa năng."}]','[{"phrase":"transform into"},{"phrase":"completely transform"},{"phrase":"transform the way"},{"phrase":"radically transform"}]','transform A into B','/trænsˈfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3018,'awl-6-02',28,'transport','giao thông vận tải; sự vận chuyển','noun','[{"en":"The city plans to invest more in public transport.","vi":"Thành phố dự định đầu tư nhiều hơn vào giao thông công cộng."},{"en":"Rising fuel prices have increased the cost of transport.","vi":"Giá nhiên liệu tăng đã làm tăng chi phí vận chuyển."},{"en":"Rail transport produces less pollution than road transport.","vi":"Vận tải đường sắt gây ô nhiễm ít hơn vận tải đường bộ."}]','[{"phrase":"public transport"},{"phrase":"means of transport"},{"phrase":"transport costs"},{"phrase":"road transport"}]','Anh: public transport · Mỹ: public transportation; không đếm được','/ˈtrænspɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transport__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3019,'awl-6-02',29,'underlie','là cơ sở của; là nguyên nhân sâu xa của','verb','[{"en":"Poverty underlies many of the health problems in the region.","vi":"Nghèo đói là nguyên nhân sâu xa của nhiều vấn đề sức khỏe trong khu vực."},{"en":"The same basic principles underlie all of these theories.","vi":"Cùng những nguyên tắc cơ bản là cơ sở của tất cả các lý thuyết này."},{"en":"Researchers want to understand the processes that underlie memory loss.","vi":"Các nhà nghiên cứu muốn hiểu những quá trình là nguyên nhân gây mất trí nhớ."}]','[{"phrase":"principles underlie"},{"phrase":"factors underlie"}]','underlie – underlay – underlain; thường gặp: underlying (cơ bản, tiềm ẩn)','/ˌʌndərˈlaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/underlie__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3020,'awl-6-02',30,'utilise','sử dụng; tận dụng','verb','[{"en":"The hospital needs to utilise its resources more efficiently.","vi":"Bệnh viện cần sử dụng nguồn lực của mình hiệu quả hơn."},{"en":"Farmers are utilising new technology to save water.","vi":"Nông dân đang tận dụng công nghệ mới để tiết kiệm nước."},{"en":"Much of the available land is still not fully utilised.","vi":"Phần lớn diện tích đất sẵn có vẫn chưa được tận dụng hết."}]','[{"phrase":"utilise resources"},{"phrase":"fully utilise"},{"phrase":"effectively utilise"},{"phrase":"utilise technology"}]','Anh: utilise · Mỹ: utilize',NULL,NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3021,'awl-5-02',1,'licence','giấy phép; bằng lái','noun','[{"en":"Foreign banks must obtain a licence before operating in the country.","vi":"Ngân hàng nước ngoài phải có giấy phép trước khi hoạt động tại quốc gia này."},{"en":"The company lost its licence after failing a safety inspection.","vi":"Công ty bị tước giấy phép sau khi không đạt đợt kiểm tra an toàn."},{"en":"She passed her test and got her driving licence last month.","vi":"Cô ấy đã thi đỗ và nhận bằng lái xe vào tháng trước."}]','[{"phrase":"obtain a licence"},{"phrase":"apply for a licence"},{"phrase":"driving licence"}]','Anh: licence (n) · Mỹ: license','/ˈlaɪsns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lic/licen/licence__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3022,'awl-5-02',2,'logic','logic; lập luận; lý lẽ','noun','[{"en":"I don''t understand the logic behind the new policy.","vi":"Tôi không hiểu lập luận đằng sau chính sách mới."},{"en":"Her argument was based on simple logic and clear evidence.","vi":"Lý lẽ của cô ấy dựa trên logic đơn giản và bằng chứng rõ ràng."},{"en":"Students study formal logic in their first year of philosophy.","vi":"Sinh viên học logic hình thức trong năm đầu ngành triết học."}]','[{"phrase":"logic behind"},{"phrase":"formal logic"},{"phrase":"simple logic"}]','không đếm được','/ˈlɑːdʒɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/log/logic/logic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3023,'awl-5-02',3,'margin','lề; cách biệt; biên lợi nhuận','noun','[{"en":"Please leave a wide margin on the left side of the page.","vi":"Vui lòng chừa lề rộng ở bên trái trang giấy."},{"en":"The proposal was approved by a narrow margin of three votes.","vi":"Đề xuất được thông qua với cách biệt sít sao là ba phiếu."},{"en":"Rising costs have reduced profit margins across the industry.","vi":"Chi phí tăng đã làm giảm biên lợi nhuận trên toàn ngành."}]','[{"phrase":"profit margin"},{"phrase":"narrow margin"},{"phrase":"margin of error"}]',NULL,'/ˈmɑːrdʒɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mar/margi/margin__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3024,'awl-5-02',4,'medical','(thuộc) y tế; y khoa','adjective','[{"en":"The clinic provides free medical care to local families.","vi":"Phòng khám cung cấp dịch vụ chăm sóc y tế miễn phí cho các gia đình địa phương."},{"en":"She is in her third year at medical school.","vi":"Cô ấy đang học năm thứ ba trường y."},{"en":"New medical research suggests that regular exercise improves memory.","vi":"Nghiên cứu y khoa mới cho thấy tập thể dục thường xuyên giúp cải thiện trí nhớ."}]','[{"phrase":"medical care"},{"phrase":"medical research"},{"phrase":"medical school"},{"phrase":"medical treatment"}]',NULL,'/ˈmedɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/medic/medical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3025,'awl-5-02',5,'mental','(thuộc) tinh thần; trí tuệ; trí óc','adjective','[{"en":"Regular exercise is good for both physical and mental health.","vi":"Tập thể dục thường xuyên tốt cho cả sức khỏe thể chất lẫn tinh thần."},{"en":"The study measured how stress affects children''s mental development.","vi":"Nghiên cứu đã đo lường mức độ ảnh hưởng của căng thẳng đến sự phát triển trí tuệ của trẻ em."},{"en":"Solving puzzles is a good mental exercise for older adults.","vi":"Giải câu đố là một cách rèn luyện trí óc tốt cho người cao tuổi."}]','[{"phrase":"mental health"},{"phrase":"mental development"},{"phrase":"physical and mental"}]',NULL,'/ˈmentl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/men/menta/mental__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3026,'awl-5-02',6,'modify','sửa đổi; điều chỉnh; biến đổi','verb','[{"en":"The engineers modified the design to reduce the car''s weight.","vi":"Các kỹ sư đã điều chỉnh thiết kế để giảm trọng lượng của chiếc xe."},{"en":"We may need to modify our plans if the budget is cut.","vi":"Chúng ta có thể cần sửa đổi kế hoạch nếu ngân sách bị cắt giảm."},{"en":"Scientists have genetically modified the plant to resist disease.","vi":"Các nhà khoa học đã biến đổi gen của loại cây này để nó kháng bệnh."}]','[{"phrase":"modify the design"},{"phrase":"slightly modify"},{"phrase":"genetically modified"}]',NULL,'/ˈmɑːdɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/modif/modify__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3027,'awl-5-02',7,'monitor','theo dõi; giám sát','verb','[{"en":"Nurses monitor patients closely during the first night after surgery.","vi":"Y tá theo dõi sát bệnh nhân trong đêm đầu tiên sau phẫu thuật."},{"en":"The government is monitoring air quality in major cities.","vi":"Chính phủ đang giám sát chất lượng không khí ở các thành phố lớn."},{"en":"Managers should monitor progress regularly to keep the project on schedule.","vi":"Các nhà quản lý nên thường xuyên theo dõi tiến độ để dự án đúng kế hoạch."}]','[{"phrase":"monitor progress"},{"phrase":"closely monitor"},{"phrase":"monitor the situation"}]','cũng là danh từ: màn hình','/ˈmɑːnɪtər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/monit/monitor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3028,'awl-5-02',8,'network','mạng lưới; mạng (máy tính)','noun','[{"en":"The city is building a new network of bike lanes.","vi":"Thành phố đang xây dựng một mạng lưới làn đường xe đạp mới."},{"en":"All the office computers are connected to the same network.","vi":"Tất cả máy tính trong văn phòng đều được kết nối vào cùng một mạng."},{"en":"Attending conferences helps young researchers build a professional network.","vi":"Tham dự hội thảo giúp các nhà nghiên cứu trẻ xây dựng mạng lưới quan hệ nghề nghiệp."}]','[{"phrase":"network of"},{"phrase":"computer network"},{"phrase":"professional network"},{"phrase":"transport network"}]',NULL,'/ˈnetwɜːrk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/net/netwo/network__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3029,'awl-5-02',9,'notion','khái niệm; quan niệm','noun','[{"en":"The study challenges the notion that older workers are less productive.","vi":"Nghiên cứu này thách thức quan niệm rằng người lao động lớn tuổi làm việc kém năng suất hơn."},{"en":"Many students have only a vague notion of how interest rates work.","vi":"Nhiều sinh viên chỉ có khái niệm mơ hồ về cách lãi suất vận hành."},{"en":"The notion of fairness varies from one culture to another.","vi":"Khái niệm công bằng khác nhau giữa các nền văn hóa."}]','[{"phrase":"the notion that"},{"phrase":"notion of"},{"phrase":"challenge the notion"},{"phrase":"vague notion"}]',NULL,'/ˈnəʊʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notio/notion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3030,'awl-5-02',10,'objective','mục tiêu; mục đích','noun','[{"en":"The main objective of the project is to reduce energy costs.","vi":"Mục tiêu chính của dự án là giảm chi phí năng lượng."},{"en":"Each lesson begins with a clear list of learning objectives.","vi":"Mỗi bài học bắt đầu bằng một danh sách rõ ràng các mục tiêu học tập."},{"en":"The company achieved all of its objectives for the year.","vi":"Công ty đã đạt được tất cả các mục tiêu đề ra cho năm nay."}]','[{"phrase":"main objective"},{"phrase":"achieve an objective"},{"phrase":"learning objectives"}]','cũng là tính từ: khách quan','/əbˈdʒektɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obj/objec/objective__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3031,'awl-5-02',11,'orient','định hướng; hướng (vào)','verb','[{"en":"The new course is oriented toward students who plan to work abroad.","vi":"Khóa học mới hướng tới những sinh viên dự định làm việc ở nước ngoài."},{"en":"Most of the firm''s products are oriented to the export market.","vi":"Phần lớn sản phẩm của công ty hướng tới thị trường xuất khẩu."},{"en":"The government wants to orient the economy toward services and technology.","vi":"Chính phủ muốn định hướng nền kinh tế sang dịch vụ và công nghệ."}]','[{"phrase":"oriented toward"},{"phrase":"orient yourself"},{"phrase":"market-oriented"}]','thường dùng bị động: be oriented to/toward · Anh còn dùng: orientate','/ˈɔːrient/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/orien/orient__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3032,'awl-5-02',12,'perspective','góc nhìn; quan điểm','noun','[{"en":"The book tells the story of migration from a child''s perspective.","vi":"Cuốn sách kể câu chuyện di cư từ góc nhìn của một đứa trẻ."},{"en":"Living abroad gave me a completely different perspective on my own culture.","vi":"Sống ở nước ngoài cho tôi một góc nhìn hoàn toàn khác về văn hóa của chính mình."},{"en":"From an economic perspective, the plan makes a lot of sense.","vi":"Xét từ quan điểm kinh tế, kế hoạch này rất hợp lý."}]','[{"phrase":"different perspective"},{"phrase":"perspective on"},{"phrase":"from an economic perspective"}]','perspective on + danh từ','/pərˈspektɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persp/perspective__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3033,'awl-5-02',13,'precise','chính xác; cụ thể','adjective','[{"en":"Scientific instruments must give precise measurements under all conditions.","vi":"Các thiết bị khoa học phải cho kết quả đo chính xác trong mọi điều kiện."},{"en":"The precise cause of the delay is still unclear.","vi":"Nguyên nhân chính xác của sự chậm trễ vẫn chưa rõ."},{"en":"Could you be more precise about what the client wants?","vi":"Bạn có thể nói cụ thể hơn về việc khách hàng muốn gì không?"}]','[{"phrase":"precise measurement"},{"phrase":"precise details"},{"phrase":"to be precise"}]',NULL,'/prɪˈsaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preci/precise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3034,'awl-5-02',14,'prime','chính; hàng đầu; đắc địa','adjective','[{"en":"Cost is the prime concern for most small businesses.","vi":"Chi phí là mối quan tâm hàng đầu của hầu hết các doanh nghiệp nhỏ."},{"en":"The hotel is in a prime location near the city center.","vi":"Khách sạn nằm ở vị trí đắc địa gần trung tâm thành phố."},{"en":"Poor diet is a prime example of a health risk people can control.","vi":"Chế độ ăn uống kém là ví dụ điển hình về một rủi ro sức khỏe mà con người có thể kiểm soát."}]','[{"phrase":"prime example"},{"phrase":"prime location"},{"phrase":"prime concern"}]',NULL,'/praɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prime/prime__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3035,'awl-5-02',15,'psychology','tâm lý học; tâm lý','noun','[{"en":"She has a degree in psychology and works in a hospital.","vi":"Cô ấy có bằng tâm lý học và làm việc tại một bệnh viện."},{"en":"Understanding customer psychology is essential for successful marketing.","vi":"Hiểu tâm lý khách hàng là điều thiết yếu để tiếp thị thành công."},{"en":"Child psychology studies how children think, feel and learn.","vi":"Tâm lý học trẻ em nghiên cứu cách trẻ suy nghĩ, cảm nhận và học hỏi."}]','[{"phrase":"child psychology"},{"phrase":"degree in psychology"},{"phrase":"social psychology"}]',NULL,'/saɪˈkɑːlədʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/psy/psych/psychology__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3036,'awl-5-02',16,'pursue','theo đuổi; tiếp tục (thực hiện)','verb','[{"en":"After graduating, he decided to pursue a career in law.","vi":"Sau khi tốt nghiệp, anh ấy quyết định theo đuổi sự nghiệp trong ngành luật."},{"en":"Many students go abroad to pursue further studies.","vi":"Nhiều sinh viên ra nước ngoài để tiếp tục học lên cao."},{"en":"The committee agreed not to pursue the matter any further.","vi":"Ủy ban nhất trí không tiếp tục theo đuổi vấn đề này nữa."}]','[{"phrase":"pursue a career"},{"phrase":"pursue a goal"},{"phrase":"pursue the matter"}]',NULL,'/pərˈsuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/pursu/pursue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3037,'awl-5-02',17,'ratio','tỷ lệ; tỷ số','noun','[{"en":"The ratio of students to teachers in the school is twenty to one.","vi":"Tỷ lệ học sinh trên giáo viên ở trường này là hai mươi trên một."},{"en":"The gender ratio in engineering courses is slowly becoming more balanced.","vi":"Tỷ lệ giới tính trong các khóa học kỹ thuật đang dần cân bằng hơn."},{"en":"Mix the flour and water in a ratio of two to one.","vi":"Trộn bột và nước theo tỷ lệ hai phần bột, một phần nước."}]','[{"phrase":"the ratio of"},{"phrase":"in a ratio of"},{"phrase":"gender ratio"}]','ratio of A to B = tỷ lệ A trên B','/ˈreɪʃiəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/ratio/ratio__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3038,'awl-5-02',18,'reject','từ chối; bác bỏ','verb','[{"en":"The board rejected the proposal because it was too expensive.","vi":"Hội đồng quản trị đã bác bỏ đề xuất vì nó quá tốn kém."},{"en":"Her first article was rejected by three journals.","vi":"Bài báo đầu tiên của cô ấy đã bị ba tạp chí từ chối."},{"en":"Scientists rejected the theory after new evidence was found.","vi":"Các nhà khoa học đã bác bỏ lý thuyết đó sau khi tìm ra bằng chứng mới."}]','[{"phrase":"reject a proposal"},{"phrase":"reject an application"},{"phrase":"flatly reject"}]',NULL,'/rɪˈdʒekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rej/rejec/reject__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3039,'awl-5-02',19,'revenue','doanh thu; nguồn thu','noun','[{"en":"The company''s revenue rose by twelve percent last year.","vi":"Doanh thu của công ty đã tăng mười hai phần trăm vào năm ngoái."},{"en":"Tourism is the country''s main source of revenue.","vi":"Du lịch là nguồn thu chính của đất nước."},{"en":"The government expects tax revenues to increase next year.","vi":"Chính phủ dự kiến nguồn thu thuế sẽ tăng vào năm tới."}]','[{"phrase":"tax revenue"},{"phrase":"source of revenue"},{"phrase":"generate revenue"}]',NULL,'/ˈrevənuː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/reven/revenue__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3040,'awl-5-02',20,'stable','ổn định; vững chắc','adjective','[{"en":"Prices have remained stable for the past six months.","vi":"Giá cả vẫn ổn định trong sáu tháng qua."},{"en":"Investors prefer countries with a stable economy.","vi":"Các nhà đầu tư ưa chuộng những quốc gia có nền kinh tế ổn định."},{"en":"Make sure the ladder is stable before you climb it.","vi":"Hãy chắc chắn rằng cái thang đã đứng vững trước khi bạn trèo lên."}]','[{"phrase":"remain stable"},{"phrase":"stable economy"},{"phrase":"stable job"}]',NULL,'/ˈsteɪbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stabl/stable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3041,'awl-5-02',21,'style','phong cách; kiểu; lối (viết)','noun','[{"en":"Every manager has a different leadership style.","vi":"Mỗi nhà quản lý có một phong cách lãnh đạo khác nhau."},{"en":"The building was designed in a traditional Japanese style.","vi":"Tòa nhà được thiết kế theo kiểu truyền thống Nhật Bản."},{"en":"His writing style is clear, simple and easy to follow.","vi":"Lối viết của anh ấy rõ ràng, đơn giản và dễ hiểu."}]','[{"phrase":"leadership style"},{"phrase":"writing style"},{"phrase":"learning style"}]',NULL,'/staɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sty/style/style__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3042,'awl-5-02',22,'substitute','thay thế','verb','[{"en":"You can substitute olive oil for butter in this recipe.","vi":"Bạn có thể dùng dầu ô liu thay cho bơ trong công thức này."},{"en":"Many factories have substituted machines for human workers.","vi":"Nhiều nhà máy đã thay thế công nhân bằng máy móc."},{"en":"Online classes cannot fully substitute for face-to-face teaching.","vi":"Các lớp học trực tuyến không thể thay thế hoàn toàn việc giảng dạy trực tiếp."}]','[{"phrase":"substitute for"},{"phrase":"substitute one thing for another"}]','substitute A for B = dùng A thay cho B · cũng là danh từ: vật/người thay thế','/ˈsʌbstɪtuːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substitute__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3043,'awl-5-02',23,'sustain','duy trì; chịu (thiệt hại)','verb','[{"en":"The company cannot sustain such rapid growth for long.","vi":"Công ty không thể duy trì tốc độ tăng trưởng nhanh như vậy lâu dài."},{"en":"The region''s economy is sustained mainly by fishing and tourism.","vi":"Nền kinh tế của khu vực được duy trì chủ yếu nhờ đánh bắt cá và du lịch."},{"en":"Several buildings sustained serious damage during the storm.","vi":"Nhiều tòa nhà bị thiệt hại nghiêm trọng trong cơn bão."}]','[{"phrase":"sustain growth"},{"phrase":"sustain damage"},{"phrase":"sustain interest"}]',NULL,'/səˈsteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/susta/sustain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3044,'awl-5-02',24,'symbol','biểu tượng; ký hiệu','noun','[{"en":"The old bridge has become a symbol of the city.","vi":"Cây cầu cũ đã trở thành biểu tượng của thành phố."},{"en":"In chemistry, the symbol for gold is Au.","vi":"Trong hóa học, ký hiệu của vàng là Au."},{"en":"For many families, owning a car is a symbol of success.","vi":"Với nhiều gia đình, sở hữu ô tô là biểu tượng của sự thành công."}]','[{"phrase":"symbol of"},{"phrase":"status symbol"},{"phrase":"chemical symbol"}]',NULL,'/ˈsɪmbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sym/symbo/symbol__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3045,'awl-5-02',25,'target','mục tiêu; chỉ tiêu; đối tượng','noun','[{"en":"The factory failed to meet its production target this year.","vi":"Nhà máy đã không đạt chỉ tiêu sản xuất trong năm nay."},{"en":"Young adults are the main target of the advertising campaign.","vi":"Người trẻ tuổi là đối tượng chính của chiến dịch quảng cáo."},{"en":"The government has set a target of cutting emissions by half.","vi":"Chính phủ đã đặt mục tiêu cắt giảm một nửa lượng khí thải."}]','[{"phrase":"meet a target"},{"phrase":"set a target"},{"phrase":"sales target"},{"phrase":"target audience"}]',NULL,'/ˈtɑːrɡɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tar/targe/target__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3046,'awl-5-02',26,'transit','sự vận chuyển; quá cảnh; giao thông công cộng','noun','[{"en":"Some of the goods were damaged in transit.","vi":"Một số hàng hóa đã bị hư hỏng trong quá trình vận chuyển."},{"en":"Passengers in transit do not need a visa at this airport.","vi":"Hành khách quá cảnh không cần thị thực tại sân bay này."},{"en":"The city plans to invest heavily in public transit.","vi":"Thành phố dự định đầu tư mạnh vào giao thông công cộng."}]','[{"phrase":"in transit"},{"phrase":"public transit"},{"phrase":"transit visa"}]','public transit (Mỹ) = public transport (Anh)','/ˈtrænzɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transit__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3047,'awl-5-02',27,'trend','xu hướng; khuynh hướng','noun','[{"en":"There is a growing trend toward working from home.","vi":"Xu hướng làm việc tại nhà đang ngày càng gia tăng."},{"en":"Economists study long-term trends in employment and wages.","vi":"Các nhà kinh tế học nghiên cứu xu hướng dài hạn về việc làm và tiền lương."},{"en":"If this trend continues, prices will double within ten years.","vi":"Nếu xu hướng này tiếp diễn, giá cả sẽ tăng gấp đôi trong vòng mười năm."}]','[{"phrase":"growing trend"},{"phrase":"long-term trend"},{"phrase":"trend toward"},{"phrase":"current trend"}]',NULL,'/trend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tre/trend/trend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3048,'awl-5-02',28,'version','phiên bản; bản','noun','[{"en":"Please download the latest version of the software.","vi":"Vui lòng tải phiên bản mới nhất của phần mềm."},{"en":"The final version of the report is due on Friday.","vi":"Bản cuối cùng của báo cáo phải nộp vào thứ Sáu."},{"en":"The English version of the book will be published next year.","vi":"Bản tiếng Anh của cuốn sách sẽ được xuất bản vào năm sau."}]','[{"phrase":"latest version"},{"phrase":"final version"},{"phrase":"updated version"},{"phrase":"English version"}]',NULL,'/ˈvɜːrʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/versi/version__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3049,'awl-5-02',29,'welfare','phúc lợi; an sinh','noun','[{"en":"The new law aims to improve the welfare of factory workers.","vi":"Luật mới nhằm cải thiện phúc lợi cho công nhân nhà máy."},{"en":"Spending on social welfare has increased sharply this decade.","vi":"Chi tiêu cho phúc lợi xã hội đã tăng mạnh trong thập kỷ này."},{"en":"Animal welfare groups are calling for better conditions on farms.","vi":"Các tổ chức bảo vệ phúc lợi động vật đang kêu gọi cải thiện điều kiện ở các trang trại."}]','[{"phrase":"social welfare"},{"phrase":"animal welfare"},{"phrase":"welfare of"},{"phrase":"welfare system"}]','không đếm được','/ˈwelfer/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/welfa/welfare__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3050,'awl-5-02',30,'whereas','trong khi; còn','conjunction','[{"en":"Some students prefer group work, whereas others learn better alone.","vi":"Một số sinh viên thích làm việc nhóm, trong khi những người khác học tốt hơn khi học một mình."},{"en":"Rents have risen sharply, whereas wages have barely changed.","vi":"Tiền thuê nhà tăng mạnh, trong khi tiền lương hầu như không thay đổi."},{"en":"Whereas the old system was slow, the new one processes orders instantly.","vi":"Hệ thống cũ chạy chậm, còn hệ thống mới xử lý đơn hàng ngay lập tức."}]','[{"phrase":"whereas others"},{"phrase":"whereas in the past"}]','dùng để đối chiếu hai mệnh đề trái ngược','/ˌwerˈæz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/whereas__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3051,'awl-6-01',1,'abstract','trừu tượng','adjective','[{"en":"Young children often find abstract concepts like time hard to understand.","vi":"Trẻ nhỏ thường thấy khó hiểu những khái niệm trừu tượng như thời gian."},{"en":"The lecture was too abstract for most first-year students.","vi":"Bài giảng quá trừu tượng đối với hầu hết sinh viên năm nhất."},{"en":"Try to give concrete examples instead of abstract explanations.","vi":"Hãy cố gắng đưa ra ví dụ cụ thể thay vì những lời giải thích trừu tượng."}]','[{"phrase":"abstract concept"},{"phrase":"abstract idea"},{"phrase":"abstract art"}]','abstract ≠ concrete (cụ thể); danh từ abstract = bản tóm tắt (bài báo khoa học)','/ˈæbstrækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/abstr/abstract__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3052,'awl-6-01',2,'accurate','chính xác','adjective','[{"en":"Accurate data is essential for making good policy decisions.","vi":"Dữ liệu chính xác là yếu tố thiết yếu để đưa ra các quyết định chính sách đúng đắn."},{"en":"The weather forecast was not very accurate this week.","vi":"Dự báo thời tiết tuần này không chính xác lắm."},{"en":"Is this a fairly accurate description of what happened at the meeting?","vi":"Đây có phải là mô tả khá chính xác về những gì đã diễn ra trong cuộc họp không?"}]','[{"phrase":"accurate information"},{"phrase":"accurate data"},{"phrase":"accurate description"},{"phrase":"highly accurate"}]',NULL,'/ˈækjərət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accur/accurate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3053,'awl-6-01',3,'acknowledge','thừa nhận; ghi nhận; xác nhận (đã nhận)','verb','[{"en":"The company finally acknowledged that the product had a serious fault.","vi":"Công ty cuối cùng đã thừa nhận rằng sản phẩm có lỗi nghiêm trọng."},{"en":"The report acknowledges the contribution of local volunteers.","vi":"Báo cáo ghi nhận sự đóng góp của các tình nguyện viên địa phương."},{"en":"Please acknowledge receipt of this email by Friday.","vi":"Vui lòng xác nhận đã nhận được email này trước thứ Sáu."}]','[{"phrase":"acknowledge receipt"},{"phrase":"widely acknowledged"},{"phrase":"acknowledge the need"},{"phrase":"acknowledge the contribution"}]','acknowledge + that / V-ing','/əkˈnɑːlɪdʒ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ack/ackno/acknowledge__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3054,'awl-6-01',4,'aggregate','tổng; tổng hợp','adjective','[{"en":"Aggregate demand fell sharply during the economic crisis.","vi":"Tổng cầu giảm mạnh trong cuộc khủng hoảng kinh tế."},{"en":"The study only reports aggregate data, not individual results.","vi":"Nghiên cứu chỉ báo cáo dữ liệu tổng hợp, không báo cáo kết quả của từng cá nhân."},{"en":"Our team finished first with an aggregate score of 245 points.","vi":"Đội chúng tôi về nhất với tổng điểm là 245."}]','[{"phrase":"aggregate demand"},{"phrase":"aggregate data"},{"phrase":"aggregate score"}]',NULL,'/ˈæɡrɪɡət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/agg/aggre/aggregate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3055,'awl-6-01',5,'allocate','phân bổ; cấp; dành (cho)','verb','[{"en":"The government allocated extra funds to rural hospitals this year.","vi":"Năm nay chính phủ đã phân bổ thêm kinh phí cho các bệnh viện ở nông thôn."},{"en":"Each student will be allocated a room in student housing.","vi":"Mỗi sinh viên sẽ được cấp một phòng trong khu nhà ở sinh viên."},{"en":"We need to allocate more time to testing before the launch.","vi":"Chúng ta cần dành thêm thời gian cho việc kiểm thử trước khi ra mắt."}]','[{"phrase":"allocate resources"},{"phrase":"allocate funds"},{"phrase":"allocate time"}]','allocate sth to sb/sth','/ˈæləkeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/all/alloc/allocate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3056,'awl-6-01',6,'assign','giao (việc); phân công; chỉ định','verb','[{"en":"The manager assigned the new project to two experienced engineers.","vi":"Người quản lý đã giao dự án mới cho hai kỹ sư giàu kinh nghiệm."},{"en":"Patients were randomly assigned to one of three groups.","vi":"Các bệnh nhân được phân ngẫu nhiên vào một trong ba nhóm."},{"en":"Each student is assigned a tutor in their first week.","vi":"Mỗi sinh viên được chỉ định một người hướng dẫn trong tuần đầu tiên."}]','[{"phrase":"assign a task"},{"phrase":"assign responsibility"},{"phrase":"randomly assigned"}]','assign sth to sb / assign sb sth','/əˈsaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assig/assign__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3057,'awl-6-01',7,'attach','đính kèm; gắn','verb','[{"en":"I have attached a copy of the report to this email.","vi":"Tôi đã đính kèm một bản sao báo cáo vào email này."},{"en":"Sensors were attached to the patients'' wrists to monitor their sleep.","vi":"Các cảm biến được gắn vào cổ tay bệnh nhân để theo dõi giấc ngủ."},{"en":"Please attach a recent photo to your application form.","vi":"Vui lòng đính kèm một ảnh gần đây vào đơn đăng ký của bạn."}]','[{"phrase":"attach a file"},{"phrase":"attach a photo"},{"phrase":"attached to"}]','attach sth to sth','/əˈtætʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attac/attach__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3058,'awl-6-01',8,'author','tác giả','noun','[{"en":"The author of the study works at a university in Canada.","vi":"Tác giả của nghiên cứu làm việc tại một trường đại học ở Canada."},{"en":"Many authors now publish their books online.","vi":"Ngày nay nhiều tác giả xuất bản sách của họ trên mạng."},{"en":"According to the authors, the results need further testing.","vi":"Theo các tác giả, kết quả cần được kiểm chứng thêm."}]','[{"phrase":"author of"},{"phrase":"lead author"},{"phrase":"best-selling author"}]',NULL,'/ˈɔːθər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autho/author__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3059,'awl-6-01',9,'bond','mối gắn bó; liên kết; trái phiếu','noun','[{"en":"Working through hard times together can create a strong bond between colleagues.","vi":"Cùng nhau vượt qua giai đoạn khó khăn có thể tạo nên sự gắn bó bền chặt giữa các đồng nghiệp."},{"en":"Energy is released when new chemical bonds form.","vi":"Năng lượng được giải phóng khi các liên kết hóa học mới hình thành."},{"en":"Investors moved their money from stocks into government bonds.","vi":"Các nhà đầu tư chuyển tiền từ cổ phiếu sang trái phiếu chính phủ."}]','[{"phrase":"strong bond"},{"phrase":"chemical bond"},{"phrase":"government bonds"},{"phrase":"bond between"}]',NULL,'/bɑːnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bon/bond_/bond__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3060,'awl-6-01',10,'brief','ngắn gọn; ngắn ngủi','adjective','[{"en":"Please keep your answers brief and to the point.","vi":"Vui lòng trả lời ngắn gọn và đúng trọng tâm."},{"en":"After a brief introduction, the speaker moved on to the main findings.","vi":"Sau phần giới thiệu ngắn gọn, diễn giả chuyển sang những phát hiện chính."},{"en":"She made a brief visit to the factory last month.","vi":"Tháng trước cô ấy đã có một chuyến thăm ngắn đến nhà máy."}]','[{"phrase":"brief introduction"},{"phrase":"brief summary"},{"phrase":"brief visit"},{"phrase":"keep it brief"}]',NULL,'/briːf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brief/brief__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3061,'awl-6-01',11,'capable','có khả năng; có năng lực','adjective','[{"en":"The new system is capable of processing thousands of orders per hour.","vi":"Hệ thống mới có khả năng xử lý hàng nghìn đơn hàng mỗi giờ."},{"en":"She is a highly capable manager with years of experience.","vi":"Cô ấy là một nhà quản lý rất có năng lực với nhiều năm kinh nghiệm."},{"en":"Few animals are capable of recognizing themselves in a mirror.","vi":"Rất ít loài động vật có khả năng nhận ra chính mình trong gương."}]','[{"phrase":"capable of"},{"phrase":"highly capable"},{"phrase":"perfectly capable"}]','capable of + V-ing / danh từ','/ˈkeɪpəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capab/capable__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3062,'awl-6-01',12,'cite','trích dẫn; viện dẫn, nêu ra','verb','[{"en":"Always cite your sources at the end of an essay.","vi":"Hãy luôn trích dẫn nguồn tài liệu ở cuối bài luận."},{"en":"The paper is widely cited by researchers in the field.","vi":"Bài báo này được các nhà nghiên cứu trong ngành trích dẫn rộng rãi."},{"en":"Many workers cited low pay as their main reason for leaving.","vi":"Nhiều người lao động nêu mức lương thấp là lý do chính khiến họ nghỉ việc."}]','[{"phrase":"cite a source"},{"phrase":"widely cited"},{"phrase":"frequently cited"},{"phrase":"cite an example"}]','cite sth as sth','/saɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/cite_/cite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3063,'awl-6-01',13,'cooperate','hợp tác; phối hợp','verb','[{"en":"The two universities have agreed to cooperate on climate research.","vi":"Hai trường đại học đã đồng ý hợp tác trong nghiên cứu khí hậu."},{"en":"Several witnesses refused to cooperate with the police investigation.","vi":"Một số nhân chứng từ chối hợp tác với cuộc điều tra của cảnh sát."},{"en":"Departments must cooperate closely to finish the project on time.","vi":"Các phòng ban phải phối hợp chặt chẽ để hoàn thành dự án đúng hạn."}]','[{"phrase":"cooperate with"},{"phrase":"cooperate closely"},{"phrase":"cooperate fully"},{"phrase":"agree to cooperate"}]','cooperate with sb on sth','/kəʊˈɑːpəreɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coo/coope/cooperate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3064,'awl-6-01',14,'discriminate','phân biệt đối xử; phân biệt','verb','[{"en":"It is illegal to discriminate against workers on the basis of age.","vi":"Phân biệt đối xử với người lao động dựa trên tuổi tác là bất hợp pháp."},{"en":"Some employers still discriminate against women with young children.","vi":"Một số nhà tuyển dụng vẫn phân biệt đối xử với phụ nữ có con nhỏ."},{"en":"Babies can discriminate between different sounds from a very early age.","vi":"Trẻ sơ sinh có thể phân biệt các âm thanh khác nhau từ rất sớm."}]','[{"phrase":"discriminate against"},{"phrase":"discriminate between"},{"phrase":"unfairly discriminate"}]','discriminate against (phân biệt đối xử) ≠ discriminate between (phân biệt)','/dɪˈskrɪmɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/discr/discriminate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3065,'awl-6-01',15,'display','trưng bày; hiển thị; biểu lộ','verb','[{"en":"The museum displays tools used by farmers thousands of years ago.","vi":"Bảo tàng trưng bày những công cụ mà người nông dân sử dụng từ hàng nghìn năm trước."},{"en":"The screen at the station displays information about train delays.","vi":"Màn hình ở nhà ga hiển thị thông tin về các chuyến tàu bị trễ."},{"en":"Several patients displayed signs of stress during the test.","vi":"Một số bệnh nhân biểu lộ dấu hiệu căng thẳng trong quá trình kiểm tra."}]','[{"phrase":"display information"},{"phrase":"display signs of"},{"phrase":"proudly display"}]',NULL,'/dɪˈspleɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/displ/display__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3066,'awl-6-01',16,'diverse','đa dạng','adjective','[{"en":"The city has one of the most diverse populations in the country.","vi":"Thành phố này có dân cư thuộc hàng đa dạng nhất cả nước."},{"en":"Our team includes people from diverse backgrounds.","vi":"Đội của chúng tôi gồm những người có xuất thân đa dạng."},{"en":"Tropical forests are home to a highly diverse range of plants.","vi":"Rừng nhiệt đới là nơi sinh sống của vô số loài thực vật vô cùng đa dạng."}]','[{"phrase":"diverse backgrounds"},{"phrase":"diverse range"},{"phrase":"culturally diverse"},{"phrase":"diverse population"}]',NULL,'/daɪˈvɜːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/diver/diverse__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3067,'awl-6-01',17,'domain','lĩnh vực; phạm vi; tên miền','noun','[{"en":"Artificial intelligence is now used in almost every domain of science.","vi":"Trí tuệ nhân tạo hiện được sử dụng trong hầu hết mọi lĩnh vực khoa học."},{"en":"Many historical documents are now in the public domain.","vi":"Nhiều tài liệu lịch sử hiện nay đã thuộc phạm vi công cộng."},{"en":"The company registered a new domain name for its online store.","vi":"Công ty đã đăng ký một tên miền mới cho cửa hàng trực tuyến của mình."}]','[{"phrase":"public domain"},{"phrase":"domain name"},{"phrase":"domain of"}]','in the public domain = thuộc phạm vi công cộng (không còn bản quyền)','/dəʊˈmeɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domai/domain__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3068,'awl-6-01',18,'edit','biên tập; chỉnh sửa','verb','[{"en":"She edits a monthly journal on environmental science.","vi":"Bà ấy biên tập một tạp chí hằng tháng về khoa học môi trường."},{"en":"Please edit your essay carefully before you submit it.","vi":"Hãy chỉnh sửa bài luận cẩn thận trước khi nộp."},{"en":"The interview was heavily edited before it was broadcast.","vi":"Cuộc phỏng vấn đã bị cắt chỉnh nhiều trước khi được phát sóng."}]','[{"phrase":"edit a book"},{"phrase":"edit a document"},{"phrase":"heavily edited"}]',NULL,'/ˈedɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/edit_/edit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3069,'awl-6-01',19,'enhance','nâng cao; tăng cường','verb','[{"en":"The new software will enhance the quality of online lessons.","vi":"Phần mềm mới sẽ nâng cao chất lượng các bài học trực tuyến."},{"en":"Regular exercise can enhance memory and concentration.","vi":"Tập thể dục thường xuyên có thể tăng cường trí nhớ và khả năng tập trung."},{"en":"The company hopes the award will enhance its reputation abroad.","vi":"Công ty hy vọng giải thưởng sẽ nâng cao danh tiếng của mình ở nước ngoài."}]','[{"phrase":"enhance the quality"},{"phrase":"enhance performance"},{"phrase":"greatly enhance"}]',NULL,'/ɪnˈhæns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enh/enhan/enhance__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3070,'awl-6-01',20,'estate','bất động sản; điền trang; tài sản (để lại)','noun','[{"en":"Real estate prices in the capital rose by ten percent last year.","vi":"Giá bất động sản ở thủ đô đã tăng mười phần trăm vào năm ngoái."},{"en":"The family owned a large estate in the countryside.","vi":"Gia đình đó từng sở hữu một điền trang lớn ở vùng nông thôn."},{"en":"He left his entire estate to a local charity.","vi":"Ông ấy để lại toàn bộ tài sản cho một tổ chức từ thiện địa phương."}]','[{"phrase":"real estate"},{"phrase":"estate agent"},{"phrase":"large estate"}]','real estate = bất động sản; estate agent (Anh) = người môi giới nhà đất','/ɪˈsteɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estat/estate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3071,'awl-6-01',21,'exceed','vượt quá; vượt','verb','[{"en":"Sales this year have exceeded our expectations by a wide margin.","vi":"Doanh số năm nay đã vượt xa kỳ vọng của chúng tôi."},{"en":"Drivers who exceed the speed limit will be fined.","vi":"Những tài xế vượt quá tốc độ cho phép sẽ bị phạt."},{"en":"The cost of the project must not exceed two million dollars.","vi":"Chi phí của dự án không được vượt quá hai triệu đô la."}]','[{"phrase":"exceed expectations"},{"phrase":"exceed the speed limit"},{"phrase":"far exceed"}]',NULL,'/ɪkˈsiːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excee/exceed__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3072,'awl-6-01',22,'expert','chuyên gia','noun','[{"en":"Experts predict that housing prices will continue to rise next year.","vi":"Các chuyên gia dự đoán giá nhà sẽ tiếp tục tăng trong năm tới."},{"en":"We asked an expert in tax law to review the contract.","vi":"Chúng tôi đã nhờ một chuyên gia về luật thuế xem xét hợp đồng."},{"en":"She is a leading expert on climate change.","vi":"Bà ấy là một chuyên gia hàng đầu về biến đổi khí hậu."}]','[{"phrase":"leading expert"},{"phrase":"expert on"},{"phrase":"expert in"},{"phrase":"independent expert"}]','expert on/in sth','/ˈekspɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/expert__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3073,'awl-6-01',23,'explicit','rõ ràng; tường minh','adjective','[{"en":"The instructions were explicit: no phones are allowed during the exam.","vi":"Hướng dẫn rất rõ ràng: không được dùng điện thoại trong giờ thi."},{"en":"The contract makes no explicit reference to overtime pay.","vi":"Hợp đồng không đề cập rõ ràng đến tiền làm thêm giờ."},{"en":"Teachers should make the learning goals explicit at the start of each lesson.","vi":"Giáo viên nên nêu rõ mục tiêu học tập ngay từ đầu mỗi bài học."}]','[{"phrase":"explicit reference"},{"phrase":"explicit instructions"},{"phrase":"make explicit"}]','explicit (rõ ràng) ≠ implicit (ngầm)','/ɪkˈsplɪsɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expli/explicit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3074,'awl-6-01',24,'federal','(thuộc) liên bang','adjective','[{"en":"The project received funding from the federal government.","vi":"Dự án đã nhận được tài trợ từ chính phủ liên bang."},{"en":"Federal law requires employers to keep accurate records of working hours.","vi":"Luật liên bang yêu cầu người sử dụng lao động lưu giữ hồ sơ giờ làm việc chính xác."},{"en":"Germany and Australia both have a federal system of government.","vi":"Cả Đức và Úc đều có hệ thống chính quyền liên bang."}]','[{"phrase":"federal government"},{"phrase":"federal law"},{"phrase":"federal agency"},{"phrase":"federal funding"}]',NULL,'/ˈfedərəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fed/feder/federal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3075,'awl-6-01',25,'fee','phí; lệ phí; học phí','noun','[{"en":"University fees have risen sharply over the past decade.","vi":"Học phí đại học đã tăng mạnh trong mười năm qua."},{"en":"There is a small fee for late registration.","vi":"Đăng ký muộn sẽ phải trả một khoản phí nhỏ."},{"en":"The lawyer charges a fixed fee for each consultation.","vi":"Luật sư tính một khoản phí cố định cho mỗi buổi tư vấn."}]','[{"phrase":"pay a fee"},{"phrase":"charge a fee"},{"phrase":"tuition fees"},{"phrase":"fixed fee"}]',NULL,'/fiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/fee__/fee__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3076,'awl-6-01',26,'flexible','linh hoạt; mềm dẻo, dễ uốn','adjective','[{"en":"Many parents look for jobs with flexible working hours.","vi":"Nhiều bậc cha mẹ tìm những công việc có giờ làm việc linh hoạt."},{"en":"Our plans are flexible, so we can change the date if needed.","vi":"Kế hoạch của chúng tôi khá linh hoạt nên có thể đổi ngày nếu cần."},{"en":"The tube is made of a light, flexible plastic.","vi":"Chiếc ống được làm bằng loại nhựa nhẹ và dẻo."}]','[{"phrase":"flexible working hours"},{"phrase":"flexible approach"},{"phrase":"highly flexible"}]',NULL,'/ˈfleksəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fle/flexi/flexible__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3077,'awl-6-01',27,'furthermore','hơn nữa; ngoài ra','adverb','[{"en":"The plan is expensive; furthermore, there is little evidence that it works.","vi":"Kế hoạch này tốn kém; hơn nữa, có rất ít bằng chứng cho thấy nó hiệu quả."},{"en":"Furthermore, it is unclear who will pay for the new system.","vi":"Ngoài ra, vẫn chưa rõ ai sẽ chi trả cho hệ thống mới."},{"en":"The new route is shorter and furthermore avoids the city center.","vi":"Tuyến đường mới ngắn hơn và hơn nữa còn tránh được trung tâm thành phố."}]','[{"phrase":"and furthermore"},{"phrase":"furthermore, it is"}]','Dùng trong văn viết trang trọng, thường đứng đầu câu','/ˌfɜːrðərˈmɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fur/furth/furthermore__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3078,'awl-6-01',28,'gender','giới tính; giới','noun','[{"en":"Participants in the study were grouped by age and gender.","vi":"Những người tham gia nghiên cứu được phân nhóm theo độ tuổi và giới tính."},{"en":"The company is working to close the gender pay gap.","vi":"Công ty đang nỗ lực thu hẹp khoảng cách lương giữa các giới."},{"en":"The survey found no significant gender differences in reading habits.","vi":"Cuộc khảo sát không tìm thấy khác biệt đáng kể nào giữa các giới về thói quen đọc."}]','[{"phrase":"gender equality"},{"phrase":"gender differences"},{"phrase":"gender pay gap"}]',NULL,'/ˈdʒendər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gende/gender__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3079,'awl-6-01',29,'ignorant','thiếu hiểu biết; không biết','adjective','[{"en":"Many consumers are ignorant of their legal rights.","vi":"Nhiều người tiêu dùng không biết về các quyền hợp pháp của mình."},{"en":"I felt completely ignorant during the discussion about tax law.","vi":"Tôi cảm thấy mình hoàn toàn thiếu hiểu biết trong cuộc thảo luận về luật thuế."},{"en":"The survey shows that the public remains largely ignorant about the new policy.","vi":"Khảo sát cho thấy phần lớn công chúng vẫn không biết gì về chính sách mới."}]','[{"phrase":"ignorant of"},{"phrase":"ignorant about"},{"phrase":"completely ignorant"},{"phrase":"largely ignorant"}]','ignorant of/about sth; ignorant (adj) ≠ ignore (v: phớt lờ)','/ˈɪɡnərənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ign/ignor/ignorant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3080,'awl-6-01',30,'incentive','động lực; sự khuyến khích; ưu đãi','noun','[{"en":"The government offers tax incentives to companies that invest in clean energy.","vi":"Chính phủ đưa ra các ưu đãi thuế cho những công ty đầu tư vào năng lượng sạch."},{"en":"Workers have little incentive to stay late without extra pay.","vi":"Người lao động có rất ít động lực ở lại làm muộn nếu không được trả thêm tiền."},{"en":"Free meals were offered as an incentive to attend the training.","vi":"Bữa ăn miễn phí được đưa ra như một sự khuyến khích để tham gia buổi tập huấn."}]','[{"phrase":"tax incentive"},{"phrase":"financial incentive"},{"phrase":"incentive to"},{"phrase":"provide an incentive"}]','incentive to do sth / incentive for sb','/ɪnˈsentɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incen/incentive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3081,'awl-7-01',1,'adapt','thích nghi; điều chỉnh cho phù hợp','verb','[{"en":"Many species have adapted to life in extremely cold climates.","vi":"Nhiều loài đã thích nghi với cuộc sống ở vùng khí hậu cực lạnh."},{"en":"Teachers often adapt their lessons for students with different needs.","vi":"Giáo viên thường điều chỉnh bài giảng cho phù hợp với học sinh có nhu cầu khác nhau."},{"en":"It took the new staff several weeks to adapt to the system.","vi":"Nhân viên mới mất vài tuần để thích nghi với hệ thống."}]','[{"phrase":"adapt to"},{"phrase":"adapt quickly"},{"phrase":"adapt to change"}]','adapt to sth · adapt (thích nghi) ≠ adopt (áp dụng; nhận nuôi)','/əˈdæpt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ada/adapt/adapt__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3082,'awl-7-01',2,'adult','người lớn; người trưởng thành','noun','[{"en":"The course is designed for adults who want to return to education.","vi":"Khóa học được thiết kế cho những người lớn muốn quay lại việc học."},{"en":"Children under twelve must be accompanied by an adult.","vi":"Trẻ em dưới mười hai tuổi phải có người lớn đi kèm."},{"en":"The study followed a group of young adults for ten years.","vi":"Nghiên cứu đã theo dõi một nhóm thanh niên trong mười năm."}]','[{"phrase":"young adult"},{"phrase":"adult education"},{"phrase":"adult population"}]',NULL,'/əˈdʌlt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adu/adult/adult__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3083,'awl-7-01',3,'advocate','ủng hộ; chủ trương; vận động cho','verb','[{"en":"Many doctors advocate regular exercise as a way to reduce stress.","vi":"Nhiều bác sĩ ủng hộ việc tập thể dục thường xuyên như một cách giảm căng thẳng."},{"en":"The report advocates stronger rules on air pollution.","vi":"Bản báo cáo chủ trương siết chặt các quy định về ô nhiễm không khí."},{"en":"She has advocated for equal pay throughout her career.","vi":"Bà ấy đã vận động cho việc trả lương bình đẳng trong suốt sự nghiệp."}]','[{"phrase":"strongly advocate"},{"phrase":"advocate for"},{"phrase":"advocate the use of"}]','Cũng là danh từ: người ủng hộ; luật sư biện hộ','/ˈædvəkət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adv/advoc/advocate__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3084,'awl-7-01',4,'aid','viện trợ; sự trợ giúp','noun','[{"en":"The country receives millions of dollars in foreign aid each year.","vi":"Quốc gia này nhận hàng triệu đô la viện trợ nước ngoài mỗi năm."},{"en":"Students from low-income families can apply for financial aid.","vi":"Sinh viên từ các gia đình thu nhập thấp có thể xin hỗ trợ tài chính."},{"en":"She learned the new language with the aid of an online course.","vi":"Cô ấy học ngôn ngữ mới với sự trợ giúp của một khóa học trực tuyến."}]','[{"phrase":"foreign aid"},{"phrase":"financial aid"},{"phrase":"with the aid of"},{"phrase":"first aid"}]',NULL,'/eɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aid/aid__/aid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3085,'awl-7-01',5,'channel','kênh; kênh truyền hình','noun','[{"en":"Customers can contact the company through several channels, including email and live chat.","vi":"Khách hàng có thể liên hệ với công ty qua nhiều kênh, bao gồm email và trò chuyện trực tuyến."},{"en":"Complaints should be made through the proper channels.","vi":"Các khiếu nại cần được gửi qua đúng kênh quy định."},{"en":"The documentary will be shown on a public television channel next month.","vi":"Bộ phim tài liệu sẽ được chiếu trên một kênh truyền hình công cộng vào tháng tới."}]','[{"phrase":"channels of communication"},{"phrase":"through the proper channels"},{"phrase":"television channel"}]',NULL,'/ˈtʃænl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chann/channel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3086,'awl-7-01',6,'chemical','hóa chất','noun','[{"en":"The factory was fined for releasing chemicals into the river.","vi":"Nhà máy bị phạt vì xả hóa chất ra sông."},{"en":"Farmers are using fewer harmful chemicals to protect their crops.","vi":"Nông dân đang sử dụng ít hóa chất độc hại hơn để bảo vệ cây trồng."},{"en":"Always store household chemicals out of the reach of children.","vi":"Luôn cất giữ các hóa chất gia dụng ngoài tầm với của trẻ em."}]','[{"phrase":"toxic chemicals"},{"phrase":"harmful chemicals"},{"phrase":"household chemicals"}]','Tính từ chemical: (thuộc) hóa học, vd chemical reaction','/ˈkemɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/chemi/chemical__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3087,'awl-7-01',7,'classic','kinh điển; điển hình','adjective','[{"en":"This is a classic example of how markets respond to fear.","vi":"Đây là một ví dụ điển hình về cách thị trường phản ứng trước nỗi sợ hãi."},{"en":"The book remains a classic study of urban poverty.","vi":"Cuốn sách vẫn là một nghiên cứu kinh điển về tình trạng nghèo đói ở đô thị."},{"en":"Headaches and tiredness are classic symptoms of dehydration.","vi":"Đau đầu và mệt mỏi là những triệu chứng điển hình của tình trạng mất nước."}]','[{"phrase":"classic example"},{"phrase":"classic case"},{"phrase":"classic symptoms"}]','classic (kinh điển, điển hình) ≠ classical (cổ điển)','/ˈklæsɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/class/classic__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3088,'awl-7-01',8,'comprehensive','toàn diện; bao quát; đầy đủ','adjective','[{"en":"The authors provide a comprehensive review of research on sleep.","vi":"Các tác giả đưa ra một bài tổng quan toàn diện các nghiên cứu về giấc ngủ."},{"en":"All new employees receive comprehensive training during their first month.","vi":"Tất cả nhân viên mới đều được đào tạo đầy đủ trong tháng đầu tiên."},{"en":"We still lack a comprehensive plan for dealing with climate change.","vi":"Chúng ta vẫn chưa có một kế hoạch toàn diện để ứng phó với biến đổi khí hậu."}]','[{"phrase":"comprehensive review"},{"phrase":"comprehensive study"},{"phrase":"comprehensive plan"}]','comprehensive (toàn diện) ≠ comprehensible (dễ hiểu)','/ˌkɑːmprɪˈhensɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprehensive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3089,'awl-7-01',9,'comprise','bao gồm; chiếm, cấu thành','verb','[{"en":"The committee comprises twelve members from different departments.","vi":"Ủy ban gồm mười hai thành viên đến từ các phòng ban khác nhau."},{"en":"Women now comprise the majority of university students in many countries.","vi":"Ở nhiều nước, nữ giới hiện chiếm đa số sinh viên đại học."},{"en":"The survey comprised thirty questions about working conditions.","vi":"Bản khảo sát gồm ba mươi câu hỏi về điều kiện làm việc."}]','[{"phrase":"comprise the majority of"},{"phrase":"be comprised of"}]','comprise + tân ngữ (không nói ''comprise of''); bị động: be comprised of','/kəmˈpraɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3090,'awl-7-01',10,'confirm','xác nhận; khẳng định','verb','[{"en":"Please confirm your attendance at the meeting by Friday afternoon.","vi":"Vui lòng xác nhận việc bạn tham dự cuộc họp trước chiều thứ Sáu."},{"en":"The results confirm that the new drug is safe for adults.","vi":"Kết quả khẳng định rằng loại thuốc mới an toàn cho người lớn."},{"en":"Officials have not yet confirmed how many jobs will be cut.","vi":"Các quan chức vẫn chưa xác nhận sẽ có bao nhiêu việc làm bị cắt giảm."}]','[{"phrase":"confirm that"},{"phrase":"officially confirm"},{"phrase":"confirm a booking"}]',NULL,'/kənˈfɜːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfirm__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3091,'awl-7-01',11,'contrary','trái ngược; ngược lại','adjective','[{"en":"Contrary to popular belief, most bats are not blind.","vi":"Trái với niềm tin phổ biến, phần lớn loài dơi không bị mù."},{"en":"The evidence was contrary to what the researchers had expected.","vi":"Bằng chứng trái ngược với những gì các nhà nghiên cứu đã dự đoán."},{"en":"The policy did not reduce costs; on the contrary, it increased them.","vi":"Chính sách này không giảm được chi phí; ngược lại, nó còn làm chi phí tăng lên."}]','[{"phrase":"contrary to popular belief"},{"phrase":"on the contrary"},{"phrase":"contrary to expectations"}]','contrary to + N: trái với · on the contrary: ngược lại','/ˈkɑːntreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontrary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3092,'awl-7-01',12,'convert','chuyển đổi; biến đổi; cải tạo','verb','[{"en":"Plants convert energy from sunlight into sugar that they can store.","vi":"Thực vật biến đổi năng lượng từ ánh sáng mặt trời thành đường để dự trữ."},{"en":"The old factory has been converted into student apartments.","vi":"Nhà máy cũ đã được cải tạo thành căn hộ cho sinh viên."},{"en":"You can easily convert the file to a PDF before sending it.","vi":"Bạn có thể dễ dàng chuyển tệp sang định dạng PDF trước khi gửi."}]','[{"phrase":"convert into"},{"phrase":"convert energy"},{"phrase":"convert currency"}]','convert A into/to B','/kənˈvɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvert__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3093,'awl-7-01',13,'couple','cặp vợ chồng; cặp đôi; một vài','noun','[{"en":"The study followed two hundred married couples over five years.","vi":"Nghiên cứu đã theo dõi hai trăm cặp vợ chồng trong năm năm."},{"en":"More young couples are choosing to delay having children.","vi":"Ngày càng nhiều cặp đôi trẻ chọn trì hoãn việc sinh con."},{"en":"The results should be available in a couple of weeks.","vi":"Kết quả sẽ có sau vài tuần nữa."}]','[{"phrase":"married couple"},{"phrase":"young couple"},{"phrase":"a couple of"}]',NULL,'/ˈkʌpl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/coupl/couple__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3094,'awl-7-01',14,'decade','thập kỷ; mười năm','noun','[{"en":"Global temperatures have risen steadily over the past three decades.","vi":"Nhiệt độ toàn cầu đã tăng đều đặn trong ba thập kỷ qua."},{"en":"The company has grown rapidly over the last decade.","vi":"Công ty đã phát triển nhanh chóng trong thập kỷ vừa qua."},{"en":"It may take decades to repair the damage to the forest.","vi":"Có thể phải mất hàng chục năm để khắc phục thiệt hại đối với khu rừng."}]','[{"phrase":"past decade"},{"phrase":"over the last decade"},{"phrase":"for decades"}]',NULL,'/ˈdekeɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decad/decade__us_4.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3095,'awl-7-01',15,'definite','rõ ràng, rõ rệt; chắc chắn, dứt khoát','adjective','[{"en":"We need a definite answer before we can sign the contract.","vi":"Chúng tôi cần một câu trả lời dứt khoát trước khi có thể ký hợp đồng."},{"en":"There has been a definite improvement in the students'' writing this term.","vi":"Kỹ năng viết của học sinh đã tiến bộ rõ rệt trong học kỳ này."},{"en":"Nothing is definite yet, but the meeting will probably be on Monday.","vi":"Vẫn chưa có gì chắc chắn, nhưng cuộc họp có lẽ sẽ diễn ra vào thứ Hai."}]','[{"phrase":"definite answer"},{"phrase":"definite improvement"},{"phrase":"definite plans"}]','definite (rõ ràng) ≠ definitive (cuối cùng, có tính quyết định)','/ˈdefɪnət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/definite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3096,'awl-7-01',16,'deny','phủ nhận; từ chối, không cho','verb','[{"en":"The company denied that its products were unsafe.","vi":"Công ty phủ nhận việc sản phẩm của họ không an toàn."},{"en":"The manager strongly denied the claims made in the report.","vi":"Người quản lý kiên quyết phủ nhận những cáo buộc trong bản báo cáo."},{"en":"Students without an ID card were denied access to the library.","vi":"Sinh viên không có thẻ đã bị từ chối cho vào thư viện."}]','[{"phrase":"strongly deny"},{"phrase":"deny access to"},{"phrase":"deny a claim"}]','deny + V-ing / that … · deny – denied – denied','/dɪˈnaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/deny_/deny__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3097,'awl-7-01',17,'differentiate','phân biệt; tạo sự khác biệt','verb','[{"en":"Young children cannot always differentiate between fact and fiction.","vi":"Trẻ nhỏ không phải lúc nào cũng phân biệt được giữa sự thật và hư cấu."},{"en":"The test helps doctors differentiate one type of infection from another.","vi":"Xét nghiệm giúp bác sĩ phân biệt loại nhiễm trùng này với loại khác."},{"en":"Small firms need clear ways to differentiate themselves from larger competitors.","vi":"Các công ty nhỏ cần có cách rõ ràng để tạo sự khác biệt so với các đối thủ lớn hơn."}]','[{"phrase":"differentiate between"},{"phrase":"differentiate from"},{"phrase":"clearly differentiate"}]','differentiate between A and B / A from B','/ˌdɪfəˈrenʃieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffe/differentiate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3098,'awl-7-01',18,'dispose','vứt bỏ; xử lý','verb','[{"en":"Hospitals must safely dispose of used needles.","vi":"Bệnh viện phải xử lý an toàn kim tiêm đã qua sử dụng."},{"en":"The city is running out of places to dispose of waste.","vi":"Thành phố đang cạn dần nơi để xử lý rác thải."},{"en":"Please dispose of old batteries at a recycling center.","vi":"Vui lòng bỏ pin cũ tại trung tâm tái chế."}]','[{"phrase":"dispose of waste"},{"phrase":"safely dispose of"}]','Luôn dùng dispose of + N','/dɪˈspəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dispo/dispose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3099,'awl-7-01',19,'dynamic','năng động; luôn vận động, biến đổi','adjective','[{"en":"She is a dynamic leader who inspires her team.","vi":"Cô ấy là một nhà lãnh đạo năng động, truyền cảm hứng cho cả nhóm."},{"en":"The city has one of the most dynamic economies in the region.","vi":"Thành phố này có một trong những nền kinh tế năng động nhất khu vực."},{"en":"Learning a language is a dynamic process that continues throughout life.","vi":"Học ngôn ngữ là một quá trình luôn vận động và kéo dài suốt đời."}]','[{"phrase":"dynamic leader"},{"phrase":"dynamic economy"},{"phrase":"dynamic process"}]','dynamics (n): sự tương tác, động lực, vd group dynamics','/daɪˈnæmɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dyn/dynam/dynamic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3100,'awl-7-01',20,'eliminate','loại bỏ; loại trừ; loại khỏi cuộc thi','verb','[{"en":"The new system will eliminate the need for paper forms.","vi":"Hệ thống mới sẽ loại bỏ nhu cầu sử dụng biểu mẫu giấy."},{"en":"Doctors were able to eliminate several possible causes of the pain.","vi":"Các bác sĩ đã loại trừ được một số nguyên nhân có thể gây ra cơn đau."},{"en":"Our team was eliminated in the first round of the competition.","vi":"Đội chúng tôi đã bị loại ngay từ vòng đầu của cuộc thi."}]','[{"phrase":"eliminate the need for"},{"phrase":"completely eliminate"},{"phrase":"eliminate poverty"}]',NULL,'/ɪˈlɪmɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eli/elimi/eliminate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3101,'awl-7-01',21,'empirical','thực nghiệm; dựa trên quan sát','adjective','[{"en":"There is little empirical evidence to support this theory.","vi":"Có rất ít bằng chứng thực nghiệm ủng hộ lý thuyết này."},{"en":"The paper combines theory with a detailed empirical study of local markets.","vi":"Bài báo kết hợp lý thuyết với một nghiên cứu thực nghiệm chi tiết về các thị trường địa phương."},{"en":"Their conclusions are based on empirical data collected over ten years.","vi":"Kết luận của họ dựa trên dữ liệu thực nghiệm được thu thập trong mười năm."}]','[{"phrase":"empirical evidence"},{"phrase":"empirical study"},{"phrase":"empirical data"},{"phrase":"empirical research"}]',NULL,'/ɪmˈpɪrɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empir/empirical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3102,'awl-7-01',22,'equip','trang bị','verb','[{"en":"All classrooms are equipped with projectors and fast internet.","vi":"Tất cả phòng học đều được trang bị máy chiếu và internet tốc độ cao."},{"en":"The course aims to equip students with practical research skills.","vi":"Khóa học nhằm trang bị cho sinh viên các kỹ năng nghiên cứu thực tế."},{"en":"It will cost a lot of money to fully equip the new hospital.","vi":"Sẽ tốn rất nhiều tiền để trang bị đầy đủ cho bệnh viện mới."}]','[{"phrase":"equipped with"},{"phrase":"equip students with"},{"phrase":"fully equip"},{"phrase":"well equipped"}]','equip – equipped – equipped · equip sb/sth with sth','/ɪˈkwɪp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/equ/equip/equip__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3103,'awl-7-01',23,'extract','chiết xuất; trích xuất; khai thác','verb','[{"en":"Oil is extracted from the seeds and used in cooking.","vi":"Dầu được chiết xuất từ hạt và dùng để nấu ăn."},{"en":"The software can extract information from thousands of scanned documents.","vi":"Phần mềm có thể trích xuất thông tin từ hàng nghìn tài liệu đã quét."},{"en":"Mining companies extract large amounts of copper from the region every year.","vi":"Các công ty khai khoáng khai thác một lượng lớn đồng từ khu vực này mỗi năm."}]','[{"phrase":"extract information"},{"phrase":"extract oil"},{"phrase":"extract data"}]','Danh từ extract: đoạn trích; tinh chất','/ˈekstrækt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/extra/extract__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3104,'awl-7-01',24,'file','tệp; hồ sơ','noun','[{"en":"Save the file before you close the program.","vi":"Hãy lưu tệp trước khi đóng chương trình."},{"en":"Doctors keep a file on every patient they treat.","vi":"Bác sĩ lưu hồ sơ về mỗi bệnh nhân mà họ điều trị."},{"en":"Please attach the file to your email and send it to the manager.","vi":"Vui lòng đính kèm tệp vào email và gửi cho người quản lý."}]','[{"phrase":"save the file"},{"phrase":"attach the file"},{"phrase":"keep a file on"}]','Động từ file: nộp (đơn), lưu trữ, vd file a complaint','/faɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/file_/file__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3105,'awl-7-01',25,'finite','hữu hạn; có giới hạn','adjective','[{"en":"Earth has a finite supply of oil and gas.","vi":"Trái Đất có nguồn cung dầu mỏ và khí đốt hữu hạn."},{"en":"We have finite resources, so we must choose our priorities carefully.","vi":"Chúng ta có nguồn lực hữu hạn, vì vậy phải lựa chọn ưu tiên một cách cẩn thận."},{"en":"There is only a finite number of places on the course.","vi":"Khóa học chỉ có một số lượng chỗ có hạn."}]','[{"phrase":"finite resources"},{"phrase":"finite number"},{"phrase":"finite supply"}]','Trái nghĩa: infinite (vô hạn)','/ˈfaɪnaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finit/finite__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3106,'awl-7-01',26,'foundation','nền tảng; cơ sở; quỹ','noun','[{"en":"Good communication is the foundation of a successful team.","vi":"Giao tiếp tốt là nền tảng của một đội nhóm thành công."},{"en":"The first year provides a solid foundation in mathematics and statistics.","vi":"Năm đầu tiên cung cấp nền tảng vững chắc về toán học và thống kê."},{"en":"A local foundation offers scholarships to students from poor families.","vi":"Một quỹ địa phương cấp học bổng cho sinh viên từ các gia đình nghèo."}]','[{"phrase":"solid foundation"},{"phrase":"lay the foundation for"},{"phrase":"charitable foundation"}]',NULL,'/faʊnˈdeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/foundation__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3107,'awl-7-01',27,'globe','địa cầu; thế giới; quả địa cầu','noun','[{"en":"The company has offices in over forty countries across the globe.","vi":"Công ty có văn phòng tại hơn bốn mươi quốc gia trên khắp thế giới."},{"en":"Scientists from around the globe shared their findings at the conference.","vi":"Các nhà khoa học từ khắp nơi trên thế giới đã chia sẻ phát hiện của họ tại hội nghị."},{"en":"The teacher used a globe to show where each country is.","vi":"Giáo viên dùng quả địa cầu để chỉ vị trí của từng quốc gia."}]','[{"phrase":"across the globe"},{"phrase":"around the globe"},{"phrase":"all over the globe"}]','Tính từ global: toàn cầu','/ɡləʊb/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/glo/globe/globe__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3108,'awl-7-01',28,'grade','điểm số; lớp; loại, cấp','noun','[{"en":"She got the highest grade in the class on the final exam.","vi":"Cô ấy đạt điểm cao nhất lớp trong kỳ thi cuối kỳ."},{"en":"My son is in the fifth grade at a local school.","vi":"Con trai tôi đang học lớp năm ở một trường gần nhà."},{"en":"The factory only uses high-grade steel in its products.","vi":"Nhà máy chỉ sử dụng thép chất lượng cao cho sản phẩm của mình."}]','[{"phrase":"good grades"},{"phrase":"in the fifth grade"},{"phrase":"high-grade"}]','Mỹ: grade = lớp (fifth grade) · Anh: year','/ɡreɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grade/grade__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3109,'awl-7-01',29,'guarantee','đảm bảo; bảo hành','verb','[{"en":"A university degree no longer guarantees a well-paid job.","vi":"Bằng đại học không còn đảm bảo một công việc lương cao."},{"en":"We cannot guarantee that the results will be the same next year.","vi":"Chúng tôi không thể đảm bảo rằng kết quả năm sau sẽ giống như vậy."},{"en":"All our laptops are guaranteed for two years.","vi":"Tất cả máy tính xách tay của chúng tôi đều được bảo hành hai năm."}]','[{"phrase":"guarantee success"},{"phrase":"cannot guarantee"},{"phrase":"guaranteed for"}]','Cũng là danh từ: sự bảo đảm; giấy bảo hành','/ˌɡærənˈtiː/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gua/guara/guarantee__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3110,'awl-7-01',30,'hierarchy','hệ thống cấp bậc; thứ bậc','noun','[{"en":"She quickly rose through the corporate hierarchy.","vi":"Cô ấy nhanh chóng thăng tiến trong hệ thống cấp bậc của công ty."},{"en":"Many traditional organizations have a strict hierarchy of managers and workers.","vi":"Nhiều tổ chức truyền thống có hệ thống cấp bậc chặt chẽ giữa quản lý và nhân viên."},{"en":"The model places basic needs such as food at the bottom of the hierarchy.","vi":"Mô hình này đặt các nhu cầu cơ bản như thức ăn ở tầng thấp nhất của hệ thống thứ bậc."}]','[{"phrase":"strict hierarchy"},{"phrase":"social hierarchy"},{"phrase":"corporate hierarchy"}]',NULL,'/ˈhaɪərɑːrki/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hie/hiera/hierarchy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3111,'awl-7-02',1,'identical','giống hệt; y hệt','adjective','[{"en":"The two samples were identical in size and chemical composition.","vi":"Hai mẫu giống hệt nhau về kích thước và thành phần hóa học."},{"en":"Both groups received identical instructions before the test began.","vi":"Cả hai nhóm đều nhận được hướng dẫn giống hệt nhau trước khi bài kiểm tra bắt đầu."},{"en":"Her results were almost identical to those of the earlier study.","vi":"Kết quả của cô ấy gần như giống hệt kết quả của nghiên cứu trước đó."}]','[{"phrase":"almost identical"},{"phrase":"identical to"},{"phrase":"virtually identical"},{"phrase":"identical twins"}]','identical to sth','/aɪˈdentɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ident/identical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3112,'awl-7-02',2,'ideology','hệ tư tưởng; ý thức hệ','noun','[{"en":"The book examines how ideology shapes the way people see the world.","vi":"Cuốn sách xem xét cách hệ tư tưởng định hình cách con người nhìn nhận thế giới."},{"en":"Researchers should not let personal ideology influence their findings.","vi":"Các nhà nghiên cứu không nên để hệ tư tưởng cá nhân chi phối kết quả nghiên cứu."},{"en":"Every society has a dominant ideology that few people openly question.","vi":"Mỗi xã hội đều có một hệ tư tưởng chủ đạo mà ít người công khai đặt câu hỏi."}]','[{"phrase":"dominant ideology"},{"phrase":"political ideology"},{"phrase":"ideology of"}]',NULL,'/ˌaɪdiˈɑːlədʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ide/ideol/ideology__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3113,'awl-7-02',3,'infer','suy ra; suy luận','verb','[{"en":"From these results, we can infer that the drug is safe for adults.","vi":"Từ những kết quả này, chúng ta có thể suy ra rằng thuốc an toàn cho người lớn."},{"en":"Readers must infer the writer''s opinion from the tone of the article.","vi":"Người đọc phải suy ra quan điểm của tác giả từ giọng điệu của bài báo."},{"en":"Scientists inferred the age of the rocks from the fossils found inside.","vi":"Các nhà khoa học đã suy ra tuổi của những tảng đá từ các hóa thạch tìm thấy bên trong."}]','[{"phrase":"infer from"},{"phrase":"infer that"},{"phrase":"reasonably infer"}]','infer sth from sth · infer – inferred – inferred','/ɪnˈfɜːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infer/infer__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3114,'awl-7-02',4,'innovate','đổi mới; cải tiến','verb','[{"en":"Companies that fail to innovate often lose customers to their competitors.","vi":"Những công ty không đổi mới thường mất khách hàng vào tay đối thủ cạnh tranh."},{"en":"Small firms can often innovate faster than large organizations.","vi":"Các công ty nhỏ thường có thể đổi mới nhanh hơn các tổ chức lớn."},{"en":"Farmers in the region are innovating to cope with less rainfall.","vi":"Nông dân trong vùng đang đổi mới cách làm để thích ứng với lượng mưa ít hơn."}]','[{"phrase":"fail to innovate"},{"phrase":"ability to innovate"},{"phrase":"continue to innovate"}]',NULL,'/ˈɪnəveɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/innov/innovate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3115,'awl-7-02',5,'insert','chèn; đưa vào, cho vào','verb','[{"en":"Please insert a short summary at the beginning of the report.","vi":"Vui lòng chèn một bản tóm tắt ngắn vào đầu báo cáo."},{"en":"Insert your card into the machine and enter your code.","vi":"Hãy cho thẻ của bạn vào máy và nhập mã."},{"en":"The doctor carefully inserted a thin tube into the patient''s arm.","vi":"Bác sĩ cẩn thận đưa một ống nhỏ vào cánh tay bệnh nhân."}]','[{"phrase":"insert into"},{"phrase":"insert a card"},{"phrase":"insert a clause"}]','insert sth into sth','/ɪnˈsɜːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inser/insert__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3116,'awl-7-02',6,'intervene','can thiệp; xen vào','verb','[{"en":"The central bank intervened to stop the currency from falling further.","vi":"Ngân hàng trung ương đã can thiệp để ngăn đồng tiền tiếp tục mất giá."},{"en":"Teachers should intervene early when a child is having trouble reading.","vi":"Giáo viên nên can thiệp sớm khi một đứa trẻ gặp khó khăn trong việc đọc."},{"en":"The manager had to intervene in a dispute between two staff members.","vi":"Người quản lý đã phải can thiệp vào một cuộc tranh chấp giữa hai nhân viên."}]','[{"phrase":"intervene in"},{"phrase":"intervene early"},{"phrase":"decide to intervene"}]','intervene in sth','/ˌɪntərˈviːn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/intervene__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3117,'awl-7-02',7,'isolate','cô lập; cách ly; tách riêng','verb','[{"en":"Patients with the virus were isolated from others in the hospital.","vi":"Những bệnh nhân nhiễm virus đã được cách ly khỏi những người khác trong bệnh viện."},{"en":"Scientists managed to isolate the gene responsible for the disease.","vi":"Các nhà khoa học đã tách được gen gây ra căn bệnh này."},{"en":"Working from home can isolate employees from their colleagues.","vi":"Làm việc tại nhà có thể khiến nhân viên bị cô lập khỏi đồng nghiệp."}]','[{"phrase":"isolate from"},{"phrase":"isolate a gene"},{"phrase":"become isolated"}]','isolate sb/sth from sb/sth','/ˈaɪsəleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/iso/isola/isolate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3118,'awl-7-02',8,'media','truyền thông; phương tiện truyền thông','noun','[{"en":"The study received a lot of attention in the media.","vi":"Nghiên cứu này nhận được nhiều sự chú ý trên truyền thông."},{"en":"Social media has changed the way young people get news.","vi":"Mạng xã hội đã thay đổi cách giới trẻ tiếp nhận tin tức."},{"en":"The company refused to comment when contacted by the media.","vi":"Công ty đã từ chối bình luận khi được giới truyền thông liên hệ."}]','[{"phrase":"social media"},{"phrase":"mass media"},{"phrase":"media coverage"},{"phrase":"news media"}]','số nhiều của medium; thường đi với động từ số ít','/ˈmiːdiə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/media/media__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3119,'awl-7-02',9,'mode','phương thức; chế độ','noun','[{"en":"Buses remain the most common mode of transport in the city.","vi":"Xe buýt vẫn là phương thức di chuyển phổ biến nhất trong thành phố."},{"en":"Switch the camera to night mode before taking the photo.","vi":"Hãy chuyển máy ảnh sang chế độ ban đêm trước khi chụp ảnh."},{"en":"Many universities moved to an online mode of teaching during the crisis.","vi":"Nhiều trường đại học đã chuyển sang phương thức giảng dạy trực tuyến trong thời kỳ khủng hoảng."}]','[{"phrase":"mode of transport"},{"phrase":"mode of communication"},{"phrase":"mode of delivery"}]',NULL,'/məʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/mode_/mode__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3120,'awl-7-02',10,'paradigm','mô hình; hệ hình','noun','[{"en":"The discovery led to a paradigm shift in modern physics.","vi":"Phát hiện này đã dẫn đến một sự chuyển đổi mô hình trong vật lý hiện đại."},{"en":"The new theory challenged the dominant paradigm in economics.","vi":"Lý thuyết mới đã thách thức hệ hình thống trị trong kinh tế học."},{"en":"Online learning is not simply a new tool but a new paradigm.","vi":"Học trực tuyến không chỉ đơn giản là một công cụ mới mà là một mô hình mới."}]','[{"phrase":"paradigm shift"},{"phrase":"dominant paradigm"},{"phrase":"new paradigm"}]',NULL,'/ˈpærədaɪm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parad/paradigm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3121,'awl-7-02',11,'phenomenon','hiện tượng','noun','[{"en":"Global warming is a phenomenon that affects every part of the planet.","vi":"Nóng lên toàn cầu là một hiện tượng ảnh hưởng đến mọi nơi trên hành tinh."},{"en":"Scientists still cannot fully explain this natural phenomenon.","vi":"Các nhà khoa học vẫn chưa thể giải thích đầy đủ hiện tượng tự nhiên này."},{"en":"Similar phenomena have been observed in several other large cities.","vi":"Những hiện tượng tương tự đã được ghi nhận ở một số thành phố lớn khác."}]','[{"phrase":"natural phenomenon"},{"phrase":"social phenomenon"},{"phrase":"explain a phenomenon"}]','số nhiều: phenomena','/fəˈnɑːmɪnən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phe/pheno/phenomenon__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3122,'awl-7-02',12,'priority','sự ưu tiên; điều ưu tiên','noun','[{"en":"Patient safety must always be our top priority.","vi":"An toàn của bệnh nhân phải luôn là ưu tiên hàng đầu của chúng ta."},{"en":"The government has made education reform a priority this year.","vi":"Chính phủ đã đặt cải cách giáo dục làm ưu tiên trong năm nay."},{"en":"Families with young children are given priority for housing.","vi":"Các gia đình có con nhỏ được ưu tiên về nhà ở."}]','[{"phrase":"top priority"},{"phrase":"high priority"},{"phrase":"give priority to"},{"phrase":"set priorities"}]',NULL,'/praɪˈɔːrəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prior/priority__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3123,'awl-7-02',13,'prohibit','cấm','verb','[{"en":"The law prohibits companies from selling personal data without consent.","vi":"Luật cấm các công ty bán dữ liệu cá nhân khi không có sự đồng ý."},{"en":"Smoking is strictly prohibited inside the building.","vi":"Hút thuốc bị nghiêm cấm bên trong tòa nhà."},{"en":"Many schools now prohibit the use of phones during lessons.","vi":"Nhiều trường học hiện nay cấm sử dụng điện thoại trong giờ học."}]','[{"phrase":"strictly prohibited"},{"phrase":"prohibit the use of"},{"phrase":"prohibit sb from doing sth"}]','prohibit sb from doing sth','/prəˈhɪbɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prohi/prohibit__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3124,'awl-7-02',14,'publication','sự xuất bản, công bố; ấn phẩm','noun','[{"en":"The article was accepted for publication in a leading medical journal.","vi":"Bài báo đã được chấp nhận để đăng trên một tạp chí y khoa hàng đầu."},{"en":"The report has been delayed, and publication is now expected next month.","vi":"Báo cáo đã bị hoãn, và việc công bố hiện được dự kiến vào tháng tới."},{"en":"The library keeps copies of all the university''s official publications.","vi":"Thư viện lưu giữ bản sao của tất cả các ấn phẩm chính thức của trường đại học."}]','[{"phrase":"accepted for publication"},{"phrase":"publication date"},{"phrase":"scientific publication"}]',NULL,'/ˌpʌblɪˈkeɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pub/publi/publication__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3125,'awl-7-02',15,'quote','trích dẫn; báo giá','verb','[{"en":"The author quotes several experts to support her main argument.","vi":"Tác giả trích dẫn một số chuyên gia để củng cố lập luận chính của mình."},{"en":"Students must use quotation marks when they quote directly from a source.","vi":"Sinh viên phải dùng dấu ngoặc kép khi trích dẫn trực tiếp từ một nguồn."},{"en":"The builder quoted us a price of two thousand dollars for the repairs.","vi":"Người thợ xây đã báo giá cho chúng tôi hai nghìn đô la cho việc sửa chữa."}]','[{"phrase":"quote from"},{"phrase":"quote directly"},{"phrase":"quote a price"},{"phrase":"widely quoted"}]',NULL,'/kwəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/quo/quote/quote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3126,'awl-7-02',16,'release','công bố, phát hành; giải phóng, thả ra','verb','[{"en":"The ministry will release the full report next week.","vi":"Bộ sẽ công bố toàn bộ báo cáo vào tuần tới."},{"en":"The company released a new version of its software on Monday.","vi":"Công ty đã phát hành phiên bản mới của phần mềm vào thứ Hai."},{"en":"Burning coal releases large amounts of carbon dioxide into the air.","vi":"Việc đốt than giải phóng một lượng lớn khí carbon dioxide vào không khí."}]','[{"phrase":"release a report"},{"phrase":"release figures"},{"phrase":"release energy"}]',NULL,'/rɪˈliːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relea/release__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3127,'awl-7-02',17,'reverse','đảo ngược; lật ngược','verb','[{"en":"The court reversed the earlier decision after reviewing new evidence.","vi":"Tòa án đã lật ngược quyết định trước đó sau khi xem xét bằng chứng mới."},{"en":"It may take decades to reverse the damage to the forest.","vi":"Có thể phải mất hàng chục năm mới đảo ngược được những tổn hại đối với khu rừng."},{"en":"If we reverse the order of the questions, do the answers change?","vi":"Nếu chúng ta đảo ngược thứ tự các câu hỏi, câu trả lời có thay đổi không?"}]','[{"phrase":"reverse a decision"},{"phrase":"reverse the trend"},{"phrase":"reverse the order"}]',NULL,'/rɪˈvɜːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/rever/reverse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3128,'awl-7-02',18,'simulate','mô phỏng','verb','[{"en":"The software simulates how the virus spreads through a population.","vi":"Phần mềm mô phỏng cách virus lây lan trong cộng đồng dân cư."},{"en":"Pilots train in machines that simulate real flight conditions.","vi":"Phi công được huấn luyện trong các thiết bị mô phỏng điều kiện bay thực tế."},{"en":"We simulated a power failure to test the backup system.","vi":"Chúng tôi đã mô phỏng một sự cố mất điện để kiểm tra hệ thống dự phòng."}]','[{"phrase":"simulate conditions"},{"phrase":"simulate the effects of"}]',NULL,'/ˈsɪmjuleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sim/simul/simulate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3129,'awl-7-02',19,'sole','duy nhất; độc quyền','adjective','[{"en":"Tourism is the sole source of income for many families on the island.","vi":"Du lịch là nguồn thu nhập duy nhất của nhiều gia đình trên đảo."},{"en":"The publisher has sole rights to the book in Asia.","vi":"Nhà xuất bản nắm độc quyền đối với cuốn sách tại châu Á."},{"en":"The sole purpose of the meeting was to agree on a budget.","vi":"Mục đích duy nhất của cuộc họp là thống nhất ngân sách."}]','[{"phrase":"sole purpose"},{"phrase":"sole source"},{"phrase":"sole responsibility"},{"phrase":"sole owner"}]',NULL,'/səʊl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/sole_/sole__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3130,'awl-7-02',20,'somewhat','hơi; phần nào','adverb','[{"en":"The results were somewhat different from what we had expected.","vi":"Kết quả hơi khác so với những gì chúng tôi đã dự đoán."},{"en":"Prices have fallen somewhat since the start of the year.","vi":"Giá cả đã giảm phần nào kể từ đầu năm."},{"en":"I found the second half of the lecture somewhat confusing.","vi":"Tôi thấy nửa sau của bài giảng hơi khó hiểu."}]','[{"phrase":"somewhat different"},{"phrase":"somewhat surprising"},{"phrase":"somewhat similar"}]',NULL,'/ˈsʌmwʌt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/somew/somewhat__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3131,'awl-7-02',21,'submit','nộp; đệ trình','verb','[{"en":"All assignments must be submitted online by Friday at noon.","vi":"Tất cả bài tập phải được nộp trực tuyến trước trưa thứ Sáu."},{"en":"The committee submitted its final report to the board last month.","vi":"Ủy ban đã đệ trình báo cáo cuối cùng lên hội đồng quản trị vào tháng trước."},{"en":"Have you submitted your application for the scholarship yet?","vi":"Bạn đã nộp hồ sơ xin học bổng chưa?"}]','[{"phrase":"submit an application"},{"phrase":"submit a report"},{"phrase":"submit to"}]','submit – submitted – submitted','/səbˈmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/submi/submit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3132,'awl-7-02',22,'successor','người kế nhiệm; người/vật kế tiếp','noun','[{"en":"The director will retire next year, but no successor has been chosen.","vi":"Giám đốc sẽ nghỉ hưu vào năm sau, nhưng vẫn chưa chọn được người kế nhiệm."},{"en":"The board appointed her as successor to the chief executive.","vi":"Hội đồng quản trị đã bổ nhiệm bà ấy làm người kế nhiệm tổng giám đốc."},{"en":"The new phone is a worthy successor to last year''s model.","vi":"Chiếc điện thoại mới là sản phẩm kế tiếp xứng đáng của mẫu năm ngoái."}]','[{"phrase":"successor to"},{"phrase":"worthy successor"},{"phrase":"natural successor"},{"phrase":"name a successor"}]','successor to sb/sth','/səkˈsesər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/successor__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3133,'awl-7-02',23,'survive','sống sót; tồn tại','verb','[{"en":"Only a few small businesses survived the economic crisis.","vi":"Chỉ một vài doanh nghiệp nhỏ tồn tại được qua cuộc khủng hoảng kinh tế."},{"en":"These plants can survive for months without much water.","vi":"Những loài cây này có thể sống sót hàng tháng mà không cần nhiều nước."},{"en":"Very few documents from that period have survived.","vi":"Rất ít tài liệu từ thời kỳ đó còn tồn tại đến nay."}]','[{"phrase":"survive a crisis"},{"phrase":"manage to survive"},{"phrase":"struggle to survive"}]',NULL,'/sərˈvaɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/survi/survive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3134,'awl-7-02',24,'thesis','luận văn, luận án; luận điểm','noun','[{"en":"She is writing her master''s thesis on climate policy.","vi":"Cô ấy đang viết luận văn thạc sĩ về chính sách khí hậu."},{"en":"He spent four years working on his doctoral thesis.","vi":"Anh ấy đã dành bốn năm để thực hiện luận án tiến sĩ của mình."},{"en":"The central thesis of the book is that cities drive economic growth.","vi":"Luận điểm trung tâm của cuốn sách là các thành phố thúc đẩy tăng trưởng kinh tế."}]','[{"phrase":"master''s thesis"},{"phrase":"doctoral thesis"},{"phrase":"central thesis"}]','số nhiều: theses','/ˈθiːsɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/thesi/thesis__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3135,'awl-7-02',25,'topic','chủ đề; đề tài','noun','[{"en":"Climate change is a popular topic for student research projects.","vi":"Biến đổi khí hậu là một đề tài phổ biến cho các dự án nghiên cứu của sinh viên."},{"en":"Let''s move on to the next topic on the agenda.","vi":"Chúng ta hãy chuyển sang chủ đề tiếp theo trong chương trình họp."},{"en":"Mental health has become a major topic of discussion in schools.","vi":"Sức khỏe tinh thần đã trở thành một chủ đề thảo luận lớn trong các trường học."}]','[{"phrase":"topic of discussion"},{"phrase":"main topic"},{"phrase":"choose a topic"},{"phrase":"research topic"}]',NULL,'/ˈtɑːpɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/top/topic/topic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3136,'awl-7-02',26,'transmit','truyền; lây truyền','verb','[{"en":"Satellites transmit signals back to stations on Earth.","vi":"Các vệ tinh truyền tín hiệu trở lại các trạm trên Trái Đất."},{"en":"The virus is transmitted mainly through close contact with infected people.","vi":"Virus lây truyền chủ yếu qua tiếp xúc gần với người bị nhiễm."},{"en":"Parents often transmit their values to their children without realizing it.","vi":"Cha mẹ thường truyền lại các giá trị của mình cho con cái mà không nhận ra."}]','[{"phrase":"transmit a signal"},{"phrase":"transmit data"},{"phrase":"transmit a disease"}]','transmit – transmitted – transmitted','/trænzˈmɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transmit__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3137,'awl-7-02',27,'ultimate','cuối cùng; cơ bản, sâu xa','adjective','[{"en":"Our ultimate goal is to make the service free for all students.","vi":"Mục tiêu cuối cùng của chúng tôi là cung cấp dịch vụ miễn phí cho tất cả sinh viên."},{"en":"The ultimate decision rests with the board of directors.","vi":"Quyết định cuối cùng thuộc về hội đồng quản trị."},{"en":"The ultimate cause of the problem was poor communication between teams.","vi":"Nguyên nhân sâu xa của vấn đề là sự giao tiếp kém giữa các nhóm."}]','[{"phrase":"ultimate goal"},{"phrase":"ultimate aim"},{"phrase":"ultimate responsibility"}]',NULL,'/ˈʌltɪmət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ult/ultim/ultimate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3138,'awl-7-02',28,'unique','duy nhất, riêng biệt; độc đáo','adjective','[{"en":"Each participant was given a unique identification number.","vi":"Mỗi người tham gia được cấp một mã số nhận dạng riêng."},{"en":"The island is home to many plants that are unique to the region.","vi":"Hòn đảo là nơi sinh sống của nhiều loài thực vật chỉ có ở khu vực này."},{"en":"The museum offers visitors a unique opportunity to see ancient writing.","vi":"Bảo tàng mang đến cho du khách một cơ hội có một không hai để xem chữ viết cổ."}]','[{"phrase":"unique to"},{"phrase":"unique opportunity"},{"phrase":"unique feature"}]','unique to sth','/juˈniːk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/uniqu/unique__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3139,'awl-7-02',29,'visible','có thể nhìn thấy; rõ ràng','adjective','[{"en":"The mountains are clearly visible from the roof of the building.","vi":"Có thể nhìn thấy rõ những ngọn núi từ nóc tòa nhà."},{"en":"Some stars are not visible to the naked eye.","vi":"Một số ngôi sao không thể nhìn thấy bằng mắt thường."},{"en":"The effects of the new policy are already visible in the data.","vi":"Tác động của chính sách mới đã thể hiện rõ trong số liệu."}]','[{"phrase":"clearly visible"},{"phrase":"visible to the naked eye"},{"phrase":"highly visible"},{"phrase":"visible from"}]',NULL,'/ˈvɪzəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visib/visible__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3140,'awl-7-02',30,'voluntary','tự nguyện; tình nguyện','adjective','[{"en":"Taking part in the survey is completely voluntary.","vi":"Việc tham gia khảo sát là hoàn toàn tự nguyện."},{"en":"She does voluntary work at a local hospital on weekends.","vi":"Cô ấy làm công việc tình nguyện tại một bệnh viện địa phương vào cuối tuần."},{"en":"Many firms have signed a voluntary agreement to cut plastic waste.","vi":"Nhiều công ty đã ký một thỏa thuận tự nguyện nhằm cắt giảm rác thải nhựa."}]','[{"phrase":"voluntary work"},{"phrase":"on a voluntary basis"},{"phrase":"completely voluntary"}]',NULL,'/ˈvɑːlənteri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volun/voluntary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3141,'awl-8-01',1,'abandon','từ bỏ; bỏ rơi; bỏ lại','verb','[{"en":"The company abandoned the project after costs rose sharply.","vi":"Công ty đã từ bỏ dự án sau khi chi phí tăng mạnh."},{"en":"Many farmers were forced to abandon their land during the drought.","vi":"Nhiều nông dân buộc phải bỏ lại đất đai của mình trong đợt hạn hán."},{"en":"Researchers should not abandon a theory simply because one test failed.","vi":"Các nhà nghiên cứu không nên từ bỏ một lý thuyết chỉ vì một thử nghiệm thất bại."}]','[{"phrase":"abandon a plan"},{"phrase":"abandon a project"},{"phrase":"abandon an attempt"}]',NULL,'/əˈbændən/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aba/aband/abandon__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3142,'awl-8-01',2,'accompany','đi kèm; đi cùng','verb','[{"en":"Children under twelve must be accompanied by an adult.","vi":"Trẻ em dưới mười hai tuổi phải có người lớn đi cùng."},{"en":"Each chart is accompanied by a short explanation of the data.","vi":"Mỗi biểu đồ đều đi kèm một lời giải thích ngắn về dữ liệu."},{"en":"Rapid economic growth is often accompanied by rising prices.","vi":"Tăng trưởng kinh tế nhanh thường đi kèm với giá cả tăng."}]','[{"phrase":"be accompanied by"},{"phrase":"accompanying text"},{"phrase":"accompanied by an adult"}]','thường dùng bị động: be accompanied by','/əˈkʌmpəni/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accompany__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3143,'awl-8-01',3,'accumulate','tích lũy; tích tụ','verb','[{"en":"Over ten years, the family accumulated enough savings to buy a house.","vi":"Trong mười năm, gia đình đó đã tích lũy đủ tiền tiết kiệm để mua nhà."},{"en":"Dust and dirt accumulate quickly inside the machine.","vi":"Bụi bẩn tích tụ rất nhanh bên trong máy."},{"en":"Scientists have accumulated strong evidence that the climate is changing.","vi":"Các nhà khoa học đã tích lũy được bằng chứng rõ ràng rằng khí hậu đang thay đổi."}]','[{"phrase":"accumulate wealth"},{"phrase":"accumulate evidence"},{"phrase":"accumulate data"}]',NULL,'/əˈkjuːmjəleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accum/accumulate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3144,'awl-8-01',4,'ambiguous','mơ hồ; không rõ ràng; nước đôi','adjective','[{"en":"The wording of the contract is ambiguous and needs to be revised.","vi":"Cách diễn đạt trong hợp đồng không rõ ràng và cần được sửa lại."},{"en":"Some survey questions were ambiguous, so participants interpreted them differently.","vi":"Một số câu hỏi khảo sát mơ hồ nên người tham gia hiểu chúng theo những cách khác nhau."},{"en":"The results of the study remain ambiguous.","vi":"Kết quả của nghiên cứu vẫn còn chưa rõ ràng."}]','[{"phrase":"ambiguous language"},{"phrase":"highly ambiguous"},{"phrase":"ambiguous results"}]',NULL,'/æmˈbɪɡjuəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/amb/ambig/ambiguous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3145,'awl-8-01',5,'append','thêm vào cuối; đính kèm','verb','[{"en":"A full list of references is appended to the report.","vi":"Danh sách đầy đủ tài liệu tham khảo được đính kèm ở cuối báo cáo."},{"en":"A short summary is appended at the end of each chapter.","vi":"Một bản tóm tắt ngắn được thêm vào cuối mỗi chương."},{"en":"The program appends new data to the end of the file.","vi":"Chương trình thêm dữ liệu mới vào cuối tệp."}]','[{"phrase":"append to"},{"phrase":"append a note"}]','append something to something','/əˈpend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appen/append__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3146,'awl-8-01',6,'appreciate','đánh giá cao; cảm kích; hiểu rõ','verb','[{"en":"We really appreciate your help with the conference.","vi":"Chúng tôi thực sự cảm kích sự giúp đỡ của bạn cho hội nghị."},{"en":"Managers failed to appreciate how serious the problem was.","vi":"Các nhà quản lý đã không hiểu rõ vấn đề nghiêm trọng đến mức nào."},{"en":"Her colleagues greatly appreciated her careful approach to research.","vi":"Các đồng nghiệp đánh giá rất cao cách làm nghiên cứu cẩn thận của cô ấy."}]','[{"phrase":"greatly appreciate"},{"phrase":"really appreciate"},{"phrase":"fully appreciate"}]',NULL,'/əˈpriːʃieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appre/appreciate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3147,'awl-8-01',7,'arbitrary','tùy tiện; tùy ý; độc đoán','adjective','[{"en":"The choice of sample size seemed arbitrary to the reviewers.","vi":"Việc chọn cỡ mẫu có vẻ tùy tiện đối với những người phản biện."},{"en":"Workers complained about arbitrary decisions made by their managers.","vi":"Công nhân phàn nàn về những quyết định độc đoán của quản lý."},{"en":"The boundary between the two categories is somewhat arbitrary.","vi":"Ranh giới giữa hai nhóm này phần nào mang tính tùy ý."}]','[{"phrase":"arbitrary decision"},{"phrase":"arbitrary rules"},{"phrase":"somewhat arbitrary"}]',NULL,'/ˈɑːrbɪtreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arb/arbit/arbitrary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3148,'awl-8-01',8,'automate','tự động hóa','verb','[{"en":"The bank has automated most of its customer services.","vi":"Ngân hàng đã tự động hóa phần lớn các dịch vụ khách hàng."},{"en":"Many factory jobs could be automated within the next decade.","vi":"Nhiều công việc trong nhà máy có thể được tự động hóa trong thập kỷ tới."},{"en":"We use software to automate the process of checking invoices.","vi":"Chúng tôi dùng phần mềm để tự động hóa quy trình kiểm tra hóa đơn."}]','[{"phrase":"automate a process"},{"phrase":"automate tasks"},{"phrase":"fully automated"}]',NULL,'/ˈɔːtəmeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autom/automate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3149,'awl-8-01',9,'bias','thành kiến; thiên vị; sai lệch','noun','[{"en":"The study was criticized for its bias toward urban schools.","vi":"Nghiên cứu bị chỉ trích vì thiên vị các trường học ở thành thị."},{"en":"Researchers took steps to reduce bias in the sample.","vi":"Các nhà nghiên cứu đã thực hiện các bước để giảm sai lệch trong mẫu."},{"en":"Employers must avoid gender bias when hiring new staff.","vi":"Nhà tuyển dụng phải tránh thành kiến giới tính khi tuyển nhân viên mới."}]','[{"phrase":"gender bias"},{"phrase":"bias against"},{"phrase":"reduce bias"},{"phrase":"political bias"}]','bias against/toward(s) somebody','/ˈbaɪəs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bia/bias_/bias__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3150,'awl-8-01',10,'chart','biểu đồ; bảng','noun','[{"en":"The chart shows how prices changed over the past five years.","vi":"Biểu đồ cho thấy giá cả đã thay đổi như thế nào trong năm năm qua."},{"en":"Students were asked to present their results in a bar chart.","vi":"Sinh viên được yêu cầu trình bày kết quả dưới dạng biểu đồ cột."},{"en":"Nurses record each patient''s temperature on a chart.","vi":"Y tá ghi nhiệt độ của từng bệnh nhân vào một bảng theo dõi."}]','[{"phrase":"bar chart"},{"phrase":"pie chart"},{"phrase":"the chart shows"}]',NULL,'/tʃɑːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chart/chart__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3151,'awl-8-01',11,'clarify','làm rõ; giải thích rõ','verb','[{"en":"Could you clarify what you mean by that term?","vi":"Bạn có thể làm rõ ý bạn muốn nói với thuật ngữ đó không?"},{"en":"The new guidelines clarify the rules for working from home.","vi":"Hướng dẫn mới làm rõ các quy định về làm việc tại nhà."},{"en":"The manager called a meeting to clarify the team''s responsibilities.","vi":"Người quản lý đã triệu tập một cuộc họp để làm rõ trách nhiệm của nhóm."}]','[{"phrase":"clarify the situation"},{"phrase":"clarify the meaning"},{"phrase":"help clarify"},{"phrase":"further clarify"}]',NULL,'/ˈklærəfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cla/clari/clarify__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3152,'awl-8-01',12,'commodity','hàng hóa; mặt hàng','noun','[{"en":"Oil is one of the most traded commodities in the world.","vi":"Dầu mỏ là một trong những mặt hàng được giao dịch nhiều nhất thế giới."},{"en":"Commodity prices fell sharply during the global recession.","vi":"Giá hàng hóa giảm mạnh trong thời kỳ suy thoái toàn cầu."},{"en":"In many cities, clean water has become a valuable commodity.","vi":"Ở nhiều thành phố, nước sạch đã trở thành một thứ hàng hóa quý giá."}]','[{"phrase":"commodity prices"},{"phrase":"valuable commodity"},{"phrase":"commodity markets"}]',NULL,'/kəˈmɑːdəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commo/commodity__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3153,'awl-8-01',13,'complement','bổ sung; làm hoàn thiện','verb','[{"en":"Online lessons are designed to complement classroom teaching.","vi":"Các bài học trực tuyến được thiết kế để bổ sung cho việc dạy trên lớp."},{"en":"The two studies complement each other well.","vi":"Hai nghiên cứu này bổ sung cho nhau rất tốt."},{"en":"Her technical skills complement his experience in management.","vi":"Kỹ năng chuyên môn của cô ấy bổ sung cho kinh nghiệm quản lý của anh ấy."}]','[{"phrase":"complement each other"},{"phrase":"perfectly complement"}]','complement (bổ sung) ≠ compliment (khen ngợi)','/ˈkɑːmplɪment/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3154,'awl-8-01',14,'conform','tuân theo; phù hợp với','verb','[{"en":"All products must conform to national safety standards.","vi":"Mọi sản phẩm phải tuân theo tiêu chuẩn an toàn quốc gia."},{"en":"Teenagers often feel pressure to conform to their friends'' behavior.","vi":"Thanh thiếu niên thường cảm thấy áp lực phải làm theo hành vi của bạn bè."},{"en":"The results did not conform to our original expectations.","vi":"Kết quả không phù hợp với kỳ vọng ban đầu của chúng tôi."}]','[{"phrase":"conform to standards"},{"phrase":"conform to rules"},{"phrase":"pressure to conform"}]','conform to/with something','/kənˈfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3155,'awl-8-01',15,'contemporary','đương đại; hiện đại; cùng thời','adjective','[{"en":"The museum has a large collection of contemporary art.","vi":"Bảo tàng có một bộ sưu tập lớn về nghệ thuật đương đại."},{"en":"The course examines key issues in contemporary society.","vi":"Khóa học xem xét những vấn đề then chốt trong xã hội hiện đại."},{"en":"Contemporary reports describe the flood as the worst in a century.","vi":"Các bản tường thuật cùng thời mô tả trận lụt là tồi tệ nhất trong một thế kỷ."}]','[{"phrase":"contemporary art"},{"phrase":"contemporary society"},{"phrase":"contemporary music"}]',NULL,'/kənˈtempəreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontemporary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3156,'awl-8-01',16,'contradict','mâu thuẫn với; phủ nhận; cãi lại','verb','[{"en":"These findings contradict the results of earlier studies.","vi":"Những phát hiện này mâu thuẫn với kết quả của các nghiên cứu trước đó."},{"en":"His statement to the police contradicted what he had told reporters.","vi":"Lời khai của anh ta với cảnh sát mâu thuẫn với những gì anh ta đã nói với phóng viên."},{"en":"She felt uncomfortable contradicting her manager in front of clients.","vi":"Cô ấy cảm thấy không thoải mái khi cãi lại quản lý trước mặt khách hàng."}]','[{"phrase":"contradict the evidence"},{"phrase":"contradict each other"},{"phrase":"directly contradict"}]',NULL,'/ˌkɑːntrəˈdɪkt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontradict__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3157,'awl-8-01',17,'crucial','cốt yếu; then chốt; quyết định','adjective','[{"en":"Early diagnosis is crucial for successful treatment.","vi":"Chẩn đoán sớm là yếu tố then chốt để điều trị thành công."},{"en":"Teachers play a crucial role in shaping students'' attitudes.","vi":"Giáo viên đóng vai trò quyết định trong việc hình thành thái độ của học sinh."},{"en":"It is crucial that everyone follows the safety procedures.","vi":"Điều cốt yếu là mọi người phải tuân thủ quy trình an toàn."}]','[{"phrase":"crucial role"},{"phrase":"absolutely crucial"},{"phrase":"crucial for"},{"phrase":"crucial factor"}]',NULL,'/ˈkruːʃl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cru/cruci/crucial__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3158,'awl-8-01',18,'currency','tiền tệ; đơn vị tiền tệ','noun','[{"en":"Tourists can exchange foreign currency at the airport.","vi":"Khách du lịch có thể đổi ngoại tệ tại sân bay."},{"en":"The country''s currency lost a third of its value last year.","vi":"Đồng tiền của quốc gia này đã mất một phần ba giá trị vào năm ngoái."},{"en":"Several countries in the region share a single currency.","vi":"Một số quốc gia trong khu vực dùng chung một đơn vị tiền tệ."}]','[{"phrase":"foreign currency"},{"phrase":"single currency"},{"phrase":"currency exchange"},{"phrase":"local currency"}]',NULL,'/ˈkɜːrənsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curre/currency__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3159,'awl-8-01',19,'denote','biểu thị; chỉ; ký hiệu cho','verb','[{"en":"In the table, an asterisk denotes a significant result.","vi":"Trong bảng, dấu sao biểu thị một kết quả có ý nghĩa thống kê."},{"en":"The letter x is often used to denote an unknown number.","vi":"Chữ x thường được dùng để ký hiệu cho một số chưa biết."},{"en":"Red areas on the map denote regions with heavy rainfall.","vi":"Các vùng màu đỏ trên bản đồ chỉ những khu vực có lượng mưa lớn."}]','[{"phrase":"used to denote"},{"phrase":"denoted by"}]',NULL,'/dɪˈnəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/denot/denote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3160,'awl-8-01',20,'detect','phát hiện; dò ra','verb','[{"en":"The test can detect the disease at a very early stage.","vi":"Xét nghiệm này có thể phát hiện bệnh ở giai đoạn rất sớm."},{"en":"Sensors detected small amounts of gas in the building.","vi":"Cảm biến đã phát hiện một lượng nhỏ khí ga trong tòa nhà."},{"en":"The software is designed to detect errors in financial records.","vi":"Phần mềm được thiết kế để phát hiện lỗi trong hồ sơ tài chính."}]','[{"phrase":"detect changes"},{"phrase":"detect errors"},{"phrase":"difficult to detect"},{"phrase":"easily detected"}]',NULL,'/dɪˈtekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/detec/detect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3161,'awl-8-01',21,'deviate','lệch khỏi; đi chệch','verb','[{"en":"The pilot had to deviate from the planned route because of a storm.","vi":"Phi công phải bay lệch khỏi lộ trình dự kiến vì có bão."},{"en":"Staff should not deviate from the agreed procedures without permission.","vi":"Nhân viên không được làm khác quy trình đã thống nhất khi chưa được phép."},{"en":"The actual costs deviated significantly from the original estimate.","vi":"Chi phí thực tế chênh lệch đáng kể so với ước tính ban đầu."}]','[{"phrase":"deviate from"},{"phrase":"deviate significantly"},{"phrase":"deviate from the plan"}]','deviate from something','/ˈdiːvieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devia/deviate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3162,'awl-8-01',22,'displace','buộc phải rời bỏ nơi ở; thay thế; chiếm chỗ','verb','[{"en":"The floods displaced thousands of families in the region.","vi":"Lũ lụt đã khiến hàng nghìn gia đình trong vùng phải rời bỏ nơi ở."},{"en":"In many offices, email has displaced traditional letters.","vi":"Ở nhiều văn phòng, email đã thay thế thư từ truyền thống."},{"en":"Some workers fear that new technology will displace them.","vi":"Một số công nhân lo sợ rằng công nghệ mới sẽ thay thế họ."}]','[{"phrase":"displaced people"},{"phrase":"displaced persons"},{"phrase":"be displaced by"}]',NULL,'/dɪsˈpleɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/displ/displace__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3163,'awl-8-01',23,'drama','kịch; phim truyền hình; sự kịch tính','noun','[{"en":"She studied drama at university before becoming a teacher.","vi":"Cô ấy học kịch ở trường đại học trước khi trở thành giáo viên."},{"en":"The new television drama follows the lives of hospital staff.","vi":"Bộ phim truyền hình mới kể về cuộc sống của các nhân viên bệnh viện."},{"en":"The rescue was full of drama and lasted several hours.","vi":"Cuộc giải cứu đầy kịch tính và kéo dài nhiều giờ."}]','[{"phrase":"television drama"},{"phrase":"historical drama"},{"phrase":"drama school"}]',NULL,'/ˈdrɑːmə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dra/drama/drama__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3164,'awl-8-01',24,'eventual','cuối cùng; sau cùng','adjective','[{"en":"Poor management led to the eventual collapse of the company.","vi":"Việc quản lý kém đã dẫn đến sự sụp đổ cuối cùng của công ty."},{"en":"Nobody could have predicted the eventual outcome of the election.","vi":"Không ai có thể đoán trước kết quả cuối cùng của cuộc bầu cử."},{"en":"The eventual winner of the competition was a small local firm.","vi":"Người thắng cuộc sau cùng của cuộc thi là một công ty nhỏ ở địa phương."}]','[{"phrase":"eventual outcome"},{"phrase":"eventual winner"},{"phrase":"eventual success"}]','trạng từ: eventually (cuối cùng)','/ɪˈventʃuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/event/eventual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3165,'awl-8-01',25,'exhibit','trưng bày; thể hiện; biểu hiện','verb','[{"en":"Her paintings will be exhibited at the city gallery next month.","vi":"Các bức tranh của cô ấy sẽ được trưng bày tại phòng tranh thành phố vào tháng tới."},{"en":"Patients exhibited clear signs of improvement after two weeks.","vi":"Bệnh nhân có những dấu hiệu cải thiện rõ rệt sau hai tuần."},{"en":"Some children exhibit behavior problems when they start school.","vi":"Một số trẻ có biểu hiện các vấn đề về hành vi khi bắt đầu đi học."}]','[{"phrase":"exhibit signs"},{"phrase":"exhibit symptoms"},{"phrase":"exhibit behavior"}]',NULL,'/ɪɡˈzɪbɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exh/exhib/exhibit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3166,'awl-8-01',26,'exploit','khai thác; tận dụng; bóc lột','verb','[{"en":"The country has not yet fully exploited its natural resources.","vi":"Đất nước này chưa khai thác hết tài nguyên thiên nhiên của mình."},{"en":"Small businesses can exploit new technology to reach more customers.","vi":"Các doanh nghiệp nhỏ có thể tận dụng công nghệ mới để tiếp cận nhiều khách hàng hơn."},{"en":"Some employers exploit workers by paying them very low wages.","vi":"Một số chủ lao động bóc lột công nhân bằng cách trả lương rất thấp."}]','[{"phrase":"exploit resources"},{"phrase":"fully exploit"},{"phrase":"exploit workers"},{"phrase":"exploit an opportunity"}]',NULL,'/ɪkˈsplɔɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/explo/exploit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3167,'awl-8-01',27,'fluctuate','dao động; biến động; lên xuống thất thường','verb','[{"en":"Oil prices fluctuated widely throughout the year.","vi":"Giá dầu biến động mạnh trong suốt cả năm."},{"en":"Temperatures in the desert fluctuate between day and night.","vi":"Nhiệt độ ở sa mạc dao động giữa ban ngày và ban đêm."},{"en":"The number of students tends to fluctuate from one term to the next.","vi":"Số lượng sinh viên thường lên xuống thất thường giữa các học kỳ."}]','[{"phrase":"fluctuate widely"},{"phrase":"prices fluctuate"},{"phrase":"fluctuate between"}]',NULL,'/ˈflʌktʃueɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flu/fluct/fluctuate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3168,'awl-8-01',28,'guideline','hướng dẫn; nguyên tắc chỉ đạo','noun','[{"en":"The government has issued new guidelines on food safety.","vi":"Chính phủ đã ban hành hướng dẫn mới về an toàn thực phẩm."},{"en":"Authors must follow the journal''s guidelines when submitting articles.","vi":"Tác giả phải tuân theo hướng dẫn của tạp chí khi gửi bài."},{"en":"These guidelines apply to all staff working with patient data.","vi":"Các nguyên tắc này áp dụng cho mọi nhân viên làm việc với dữ liệu bệnh nhân."}]','[{"phrase":"follow guidelines"},{"phrase":"issue guidelines"},{"phrase":"clear guidelines"},{"phrase":"guidelines on"}]','thường dùng số nhiều: guidelines','/ˈɡaɪdlaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gui/guide/guideline__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3169,'awl-8-01',29,'highlight','nhấn mạnh; làm nổi bật','verb','[{"en":"The report highlights the need for better public transport.","vi":"Báo cáo nhấn mạnh sự cần thiết của giao thông công cộng tốt hơn."},{"en":"This case highlights the risks of storing data online.","vi":"Trường hợp này làm nổi bật những rủi ro của việc lưu trữ dữ liệu trực tuyến."},{"en":"At the conference, speakers highlighted the importance of early education.","vi":"Tại hội nghị, các diễn giả đã nhấn mạnh tầm quan trọng của giáo dục sớm."}]','[{"phrase":"highlight the need"},{"phrase":"highlight the importance"},{"phrase":"highlight the problem"}]',NULL,'/ˈhaɪlaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/highl/highlight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3170,'awl-8-01',30,'implicit','ngầm; ẩn ý; tuyệt đối','adjective','[{"en":"There was an implicit agreement that nobody would discuss the matter.","vi":"Có một thỏa thuận ngầm rằng không ai được bàn về vấn đề này."},{"en":"The criticism was implicit in her comments about the report.","vi":"Lời phê bình ẩn chứa trong nhận xét của cô ấy về bản báo cáo."},{"en":"Patients usually have implicit trust in their doctors.","vi":"Bệnh nhân thường tin tưởng tuyệt đối vào bác sĩ của mình."}]','[{"phrase":"implicit assumption"},{"phrase":"implicit in"},{"phrase":"implicit trust"}]','implicit (ngầm) ≠ explicit (rõ ràng)','/ɪmˈplɪsɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impli/implicit__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3171,'awl-9-02',1,'mature','trưởng thành; chín chắn','adjective','[{"en":"Students in the program tend to be more mature than typical undergraduates.","vi":"Sinh viên trong chương trình này thường chín chắn hơn sinh viên đại học thông thường."},{"en":"These fish take about three years to become fully mature.","vi":"Loài cá này mất khoảng ba năm để trưởng thành hoàn toàn."},{"en":"She handled the difficult situation in a calm and mature way.","vi":"Cô ấy xử lý tình huống khó khăn một cách bình tĩnh và chín chắn."}]','[{"phrase":"fully mature"},{"phrase":"mature adult"},{"phrase":"mature market"}]',NULL,'/məˈtʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mat/matur/mature__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3172,'awl-9-02',2,'mediate','hòa giải; làm trung gian','verb','[{"en":"A neutral expert was brought in to mediate between the two companies.","vi":"Một chuyên gia trung lập đã được mời đến để làm trung gian giữa hai công ty."},{"en":"The union asked an outside group to mediate the dispute over wages.","vi":"Công đoàn đề nghị một tổ chức bên ngoài hòa giải tranh chấp về tiền lương."},{"en":"Managers are often expected to mediate conflicts within their teams.","vi":"Các nhà quản lý thường được kỳ vọng sẽ hòa giải xung đột trong nhóm của mình."}]','[{"phrase":"mediate a dispute"},{"phrase":"mediate between"},{"phrase":"mediate conflicts"}]',NULL,'/ˈmiːdieɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/media/mediate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3173,'awl-9-02',3,'medium','phương tiện (truyền tải); môi trường (nuôi cấy)','noun','[{"en":"Television remains a powerful medium for reaching older audiences.","vi":"Truyền hình vẫn là một phương tiện mạnh mẽ để tiếp cận khán giả lớn tuổi."},{"en":"English is the main medium of instruction at the university.","vi":"Tiếng Anh là ngôn ngữ giảng dạy chính tại trường đại học."},{"en":"The bacteria were grown in a liquid medium for 48 hours.","vi":"Vi khuẩn được nuôi cấy trong môi trường lỏng suốt 48 giờ."}]','[{"phrase":"medium of instruction"},{"phrase":"medium of communication"},{"phrase":"growth medium"}]','Số nhiều: media (phương tiện) hoặc mediums','/ˈmiːdiəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/med/mediu/medium__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3174,'awl-9-02',4,'military','(thuộc) quân sự; quân đội','adjective','[{"en":"The old military base has been turned into a public park.","vi":"Căn cứ quân sự cũ đã được chuyển đổi thành một công viên công cộng."},{"en":"Satellite navigation was first developed for military purposes.","vi":"Hệ thống định vị vệ tinh ban đầu được phát triển cho mục đích quân sự."},{"en":"After finishing school, he spent four years in military service.","vi":"Sau khi học xong, anh ấy đã phục vụ bốn năm trong quân đội."}]','[{"phrase":"military base"},{"phrase":"military service"},{"phrase":"military purposes"}]',NULL,'/ˈmɪləteri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mil/milit/military__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3175,'awl-9-02',5,'minimal','tối thiểu; rất ít','adjective','[{"en":"The new software requires minimal training for most staff.","vi":"Phần mềm mới chỉ cần đào tạo tối thiểu đối với hầu hết nhân viên."},{"en":"Damage to the building was minimal after the storm.","vi":"Sau cơn bão, tòa nhà chỉ bị thiệt hại rất ít."},{"en":"We aim to complete the project at minimal cost.","vi":"Chúng tôi đặt mục tiêu hoàn thành dự án với chi phí tối thiểu."}]','[{"phrase":"minimal cost"},{"phrase":"minimal effort"},{"phrase":"minimal impact"}]',NULL,'/ˈmɪnɪml/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minim/minimal__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3176,'awl-9-02',6,'mutual','lẫn nhau; chung','adjective','[{"en":"Good working relationships are built on mutual respect.","vi":"Các mối quan hệ công việc tốt được xây dựng trên sự tôn trọng lẫn nhau."},{"en":"The agreement is of mutual benefit to both universities.","vi":"Thỏa thuận này mang lại lợi ích chung cho cả hai trường đại học."},{"en":"They were introduced by a mutual friend at a conference.","vi":"Họ được một người bạn chung giới thiệu tại một hội nghị."}]','[{"phrase":"mutual respect"},{"phrase":"mutual benefit"},{"phrase":"mutual friend"},{"phrase":"mutual understanding"}]',NULL,'/ˈmjuːtʃuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mut/mutua/mutual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3177,'awl-9-02',7,'norm','chuẩn mực; điều bình thường, phổ biến','noun','[{"en":"Working from home has become the norm in many industries.","vi":"Làm việc tại nhà đã trở thành điều bình thường trong nhiều ngành."},{"en":"Social norms influence how people behave in public spaces.","vi":"Các chuẩn mực xã hội ảnh hưởng đến cách mọi người cư xử ở nơi công cộng."},{"en":"In this region, small family farms are still the norm.","vi":"Ở khu vực này, trang trại gia đình nhỏ vẫn là điều phổ biến."}]','[{"phrase":"social norms"},{"phrase":"become the norm"},{"phrase":"cultural norms"}]',NULL,'/nɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norm_/norm__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3178,'awl-9-02',8,'overlap','chồng chéo; trùng nhau (một phần)','verb','[{"en":"The two research projects overlap in several important areas.","vi":"Hai dự án nghiên cứu này chồng chéo nhau ở một số lĩnh vực quan trọng."},{"en":"My meeting overlaps with the training session, so I cannot attend both.","vi":"Cuộc họp của tôi trùng giờ với buổi đào tạo nên tôi không thể tham dự cả hai."},{"en":"The responsibilities of the two departments overlapped, which caused confusion.","vi":"Trách nhiệm của hai phòng ban bị chồng chéo, gây ra sự nhầm lẫn."}]','[{"phrase":"overlap with"},{"phrase":"overlap considerably"},{"phrase":"partially overlap"}]',NULL,'/ˌəʊvərˈlæp/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overl/overlap__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3179,'awl-9-02',9,'passive','thụ động; (ngữ pháp) bị động','adjective','[{"en":"Students learn less when they remain passive during lectures.","vi":"Sinh viên học được ít hơn khi họ thụ động trong các giờ giảng."},{"en":"Scientific reports often use the passive voice.","vi":"Các báo cáo khoa học thường dùng thể bị động."},{"en":"Instead of taking a passive role, she questioned every decision.","vi":"Thay vì đóng vai trò thụ động, cô ấy đặt câu hỏi về mọi quyết định."}]','[{"phrase":"passive voice"},{"phrase":"passive role"},{"phrase":"passive learning"}]',NULL,'/ˈpæsɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pas/passi/passive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3180,'awl-9-02',10,'portion','phần; khẩu phần','noun','[{"en":"A large portion of the budget is spent on salaries.","vi":"Một phần lớn ngân sách được chi cho tiền lương."},{"en":"Only a small portion of the population owns a car.","vi":"Chỉ một phần nhỏ dân số sở hữu ô tô."},{"en":"Restaurants have been criticized for serving very large portions.","vi":"Các nhà hàng bị chỉ trích vì phục vụ những khẩu phần quá lớn."}]','[{"phrase":"a large portion of"},{"phrase":"a small portion of"},{"phrase":"portion size"}]',NULL,'/ˈpɔːrʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/porti/portion__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3181,'awl-9-02',11,'preliminary','sơ bộ; ban đầu','adjective','[{"en":"Preliminary results suggest that the new drug is safe.","vi":"Kết quả sơ bộ cho thấy loại thuốc mới là an toàn."},{"en":"The committee held a preliminary meeting to discuss the plan.","vi":"Ủy ban đã tổ chức một cuộc họp sơ bộ để thảo luận kế hoạch."},{"en":"These findings are only preliminary and need further testing.","vi":"Những phát hiện này chỉ mang tính sơ bộ và cần được kiểm chứng thêm."}]','[{"phrase":"preliminary results"},{"phrase":"preliminary findings"},{"phrase":"preliminary study"}]',NULL,'/prɪˈlɪmɪneri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preli/preliminary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3182,'awl-9-02',12,'protocol','quy trình; giao thức','noun','[{"en":"All staff must follow the safety protocol when handling chemicals.","vi":"Mọi nhân viên phải tuân theo quy trình an toàn khi xử lý hóa chất."},{"en":"The study protocol was approved by the ethics committee.","vi":"Quy trình nghiên cứu đã được hội đồng đạo đức phê duyệt."},{"en":"Computers use a common protocol to exchange data over the internet.","vi":"Các máy tính sử dụng một giao thức chung để trao đổi dữ liệu qua internet."}]','[{"phrase":"follow protocol"},{"phrase":"safety protocol"},{"phrase":"study protocol"}]',NULL,'/ˈprəʊtəkɑːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proto/protocol__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3183,'awl-9-02',13,'qualitative','định tính','adjective','[{"en":"The researchers used qualitative methods such as interviews and group discussions.","vi":"Các nhà nghiên cứu sử dụng phương pháp định tính như phỏng vấn và thảo luận nhóm."},{"en":"Qualitative data can explain why customers made certain choices.","vi":"Dữ liệu định tính có thể giải thích vì sao khách hàng đưa ra những lựa chọn nhất định."},{"en":"Her thesis combines qualitative and quantitative research.","vi":"Luận văn của cô ấy kết hợp nghiên cứu định tính và định lượng."}]','[{"phrase":"qualitative research"},{"phrase":"qualitative data"},{"phrase":"qualitative analysis"}]','qualitative (định tính) ≠ quantitative (định lượng)','/ˈkwɑːlɪteɪtɪv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/qualitative__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3184,'awl-9-02',14,'refine','tinh chỉnh; cải tiến; tinh chế','verb','[{"en":"We further refined the survey questions after the first trial.","vi":"Chúng tôi đã tinh chỉnh thêm các câu hỏi khảo sát sau lần thử nghiệm đầu tiên."},{"en":"The company continues to refine its manufacturing process.","vi":"Công ty tiếp tục cải tiến quy trình sản xuất của mình."},{"en":"Crude oil must be refined before it can be used as fuel.","vi":"Dầu thô phải được tinh chế trước khi có thể dùng làm nhiên liệu."}]','[{"phrase":"further refine"},{"phrase":"refine a process"},{"phrase":"refine a technique"}]',NULL,'/rɪˈfaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refin/refine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3185,'awl-9-02',15,'relax','nới lỏng (quy định); thư giãn','verb','[{"en":"The city relaxed the rules on parking during the holiday season.","vi":"Thành phố đã nới lỏng quy định về đỗ xe trong mùa lễ."},{"en":"Many employees find it hard to relax after work.","vi":"Nhiều nhân viên cảm thấy khó thư giãn sau giờ làm việc."},{"en":"Banks relaxed lending standards before the financial crisis.","vi":"Các ngân hàng đã nới lỏng tiêu chuẩn cho vay trước cuộc khủng hoảng tài chính."}]','[{"phrase":"relax the rules"},{"phrase":"relax restrictions"},{"phrase":"relax standards"}]',NULL,'/rɪˈlæks/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relax/relax__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3186,'awl-9-02',16,'restrain','kiềm chế; hạn chế','verb','[{"en":"The central bank raised interest rates to restrain inflation.","vi":"Ngân hàng trung ương đã tăng lãi suất để kiềm chế lạm phát."},{"en":"She had to restrain herself from interrupting the speaker.","vi":"Cô ấy phải kiềm chế bản thân để không ngắt lời người phát biểu."},{"en":"New rules aim to restrain the growth of public spending.","vi":"Các quy định mới nhằm hạn chế sự gia tăng chi tiêu công."}]','[{"phrase":"restrain inflation"},{"phrase":"restrain yourself"},{"phrase":"restrain spending"}]','restrain sb from doing sth','/rɪˈstreɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/restr/restrain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3187,'awl-9-02',17,'revolution','cuộc cách mạng; vòng quay','noun','[{"en":"The Industrial Revolution changed the way goods were produced.","vi":"Cuộc Cách mạng Công nghiệp đã thay đổi cách thức sản xuất hàng hóa."},{"en":"Smartphones started a revolution in how people access information.","vi":"Điện thoại thông minh đã khởi đầu một cuộc cách mạng trong cách con người tiếp cận thông tin."},{"en":"The wheel makes one complete revolution every two seconds.","vi":"Bánh xe quay trọn một vòng sau mỗi hai giây."}]','[{"phrase":"industrial revolution"},{"phrase":"digital revolution"},{"phrase":"technological revolution"}]',NULL,'/ˌrevəˈluːʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revol/revolution__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3188,'awl-9-02',18,'rigid','cứng nhắc; cứng','adjective','[{"en":"The company''s rigid rules left little room for new ideas.","vi":"Những quy định cứng nhắc của công ty hầu như không chừa chỗ cho ý tưởng mới."},{"en":"Critics say the school system is too rigid for creative students.","vi":"Những người phê bình cho rằng hệ thống trường học quá cứng nhắc đối với học sinh sáng tạo."},{"en":"The box is made of rigid plastic to protect the equipment.","vi":"Chiếc hộp được làm bằng nhựa cứng để bảo vệ thiết bị."}]','[{"phrase":"rigid rules"},{"phrase":"rigid structure"},{"phrase":"rigid plastic"}]',NULL,'/ˈrɪdʒɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rig/rigid/rigid__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3189,'awl-9-02',19,'route','tuyến đường; con đường (để đạt được điều gì)','noun','[{"en":"The new bus route connects the airport with the city center.","vi":"Tuyến xe buýt mới nối sân bay với trung tâm thành phố."},{"en":"Shipping companies are looking for cheaper routes to Europe.","vi":"Các công ty vận tải biển đang tìm các tuyến đường rẻ hơn đến châu Âu."},{"en":"For many young people, education is the main route to a better job.","vi":"Với nhiều người trẻ, giáo dục là con đường chính để có công việc tốt hơn."}]','[{"phrase":"bus route"},{"phrase":"trade route"},{"phrase":"route to"}]',NULL,'/ruːt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/route/route__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3190,'awl-9-02',20,'scenario','kịch bản; tình huống (giả định)','noun','[{"en":"In the worst-case scenario, the project could be delayed by a year.","vi":"Trong kịch bản xấu nhất, dự án có thể bị chậm một năm."},{"en":"Economists modeled several scenarios for future energy prices.","vi":"Các nhà kinh tế đã xây dựng mô hình cho một số kịch bản về giá năng lượng trong tương lai."},{"en":"Trainees practice responding to emergency scenarios in a safe setting.","vi":"Học viên thực hành xử lý các tình huống khẩn cấp trong một môi trường an toàn."}]','[{"phrase":"worst-case scenario"},{"phrase":"likely scenario"},{"phrase":"possible scenario"}]',NULL,'/səˈnæriəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sce/scena/scenario__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3191,'awl-9-02',21,'sphere','lĩnh vực; phạm vi; hình cầu','noun','[{"en":"Cooperation between the two countries now extends to the sphere of education.","vi":"Sự hợp tác giữa hai nước nay đã mở rộng sang lĩnh vực giáo dục."},{"en":"Each manager has a clear sphere of responsibility within the firm.","vi":"Mỗi quản lý có một phạm vi trách nhiệm rõ ràng trong công ty."},{"en":"The Earth is not a perfect sphere but is slightly flattened at the poles.","vi":"Trái Đất không phải là một hình cầu hoàn hảo mà hơi dẹt ở hai cực."}]','[{"phrase":"public sphere"},{"phrase":"sphere of influence"},{"phrase":"perfect sphere"}]',NULL,'/sfɪr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sph/spher/sphere__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3192,'awl-9-02',22,'subordinate','cấp dưới; thuộc cấp','noun','[{"en":"A good manager listens carefully to the concerns of subordinates.","vi":"Một nhà quản lý giỏi lắng nghe kỹ những lo ngại của cấp dưới."},{"en":"She was criticized for blaming her subordinates for the mistake.","vi":"Cô ấy bị chỉ trích vì đổ lỗi cho cấp dưới về sai sót đó."},{"en":"The survey asked employees how they communicate with superiors and subordinates.","vi":"Cuộc khảo sát hỏi nhân viên về cách họ giao tiếp với cấp trên và cấp dưới."}]','[{"phrase":"superiors and subordinates"},{"phrase":"immediate subordinate"}]','Cũng là tính từ: thứ yếu, phụ thuộc (subordinate to)','/səˈbɔːrdɪnət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subor/subordinate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3193,'awl-9-02',23,'supplement','phần bổ sung; thực phẩm bổ sung','noun','[{"en":"Doctors may recommend a vitamin D supplement during the winter.","vi":"Bác sĩ có thể khuyên dùng thực phẩm bổ sung vitamin D vào mùa đông."},{"en":"The online course is a supplement to classroom teaching, not a replacement.","vi":"Khóa học trực tuyến là phần bổ sung cho việc giảng dạy trên lớp, chứ không thay thế nó."},{"en":"Many older adults take dietary supplements without asking a doctor.","vi":"Nhiều người lớn tuổi dùng thực phẩm bổ sung mà không hỏi ý kiến bác sĩ."}]','[{"phrase":"dietary supplement"},{"phrase":"vitamin supplement"},{"phrase":"supplement to"}]',NULL,'/ˈsʌplɪmənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supplement__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3194,'awl-9-02',24,'suspend','tạm ngừng; đình chỉ','verb','[{"en":"The factory suspended production for a week after the fire.","vi":"Nhà máy đã tạm ngừng sản xuất một tuần sau vụ hỏa hoạn."},{"en":"Two players were suspended for breaking team rules.","vi":"Hai cầu thủ bị đình chỉ vì vi phạm nội quy của đội."},{"en":"The airline has suspended all flights to the region until further notice.","vi":"Hãng hàng không đã tạm ngừng mọi chuyến bay đến khu vực này cho đến khi có thông báo mới."}]','[{"phrase":"suspend production"},{"phrase":"suspend flights"},{"phrase":"temporarily suspend"}]',NULL,'/səˈspend/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/suspe/suspend__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3195,'awl-9-02',25,'team','nhóm; đội','noun','[{"en":"Our research team includes experts from five different countries.","vi":"Nhóm nghiên cứu của chúng tôi gồm các chuyên gia đến từ năm quốc gia khác nhau."},{"en":"She was asked to lead a small team of software engineers.","vi":"Cô ấy được giao dẫn dắt một nhóm nhỏ các kỹ sư phần mềm."},{"en":"The national team trained hard for the tournament.","vi":"Đội tuyển quốc gia đã tập luyện chăm chỉ cho giải đấu."}]','[{"phrase":"research team"},{"phrase":"lead a team"},{"phrase":"team member"},{"phrase":"national team"}]',NULL,'/tiːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/team_/team__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3196,'awl-9-02',26,'temporary','tạm thời','adjective','[{"en":"The company hired temporary staff during the busy season.","vi":"Công ty đã thuê nhân viên tạm thời trong mùa cao điểm."},{"en":"Classes will be held in a temporary building until repairs are finished.","vi":"Các lớp học sẽ được tổ chức trong một tòa nhà tạm cho đến khi sửa chữa xong."},{"en":"Experts believe the drop in prices is only temporary.","vi":"Các chuyên gia cho rằng việc giá giảm chỉ là tạm thời."}]','[{"phrase":"temporary staff"},{"phrase":"temporary job"},{"phrase":"temporary solution"}]',NULL,'/ˈtempəreri/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tem/tempo/temporary__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3197,'awl-9-02',27,'trigger','gây ra; kích hoạt','verb','[{"en":"The announcement triggered a sharp fall in share prices.","vi":"Thông báo đó đã gây ra sự sụt giảm mạnh của giá cổ phiếu."},{"en":"Certain foods can trigger allergic reactions in children.","vi":"Một số loại thực phẩm có thể gây ra phản ứng dị ứng ở trẻ em."},{"en":"Opening the door without a code will trigger an alarm.","vi":"Mở cửa mà không nhập mã sẽ kích hoạt chuông báo động."}]','[{"phrase":"trigger a reaction"},{"phrase":"trigger an alarm"},{"phrase":"trigger a debate"}]',NULL,'/ˈtrɪɡər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tri/trigg/trigger__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3198,'awl-9-02',28,'unify','thống nhất; hợp nhất','verb','[{"en":"The new system unifies customer records from all branches.","vi":"Hệ thống mới hợp nhất hồ sơ khách hàng từ tất cả các chi nhánh."},{"en":"The coach''s main task was to unify a divided team.","vi":"Nhiệm vụ chính của huấn luyện viên là thống nhất lại một đội đang chia rẽ."},{"en":"Scientists have long attempted to unify these two theories.","vi":"Các nhà khoa học từ lâu đã cố gắng thống nhất hai lý thuyết này."}]','[{"phrase":"attempt to unify"},{"phrase":"unify the country"},{"phrase":"help unify"}]',NULL,'/ˈjuːnɪfaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unify/unify__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3199,'awl-9-02',29,'violate','vi phạm','verb','[{"en":"The company was fined for violating environmental laws.","vi":"Công ty bị phạt vì vi phạm luật môi trường."},{"en":"Sharing patient records without consent violates privacy rules.","vi":"Chia sẻ hồ sơ bệnh nhân khi chưa được đồng ý là vi phạm quy định về quyền riêng tư."},{"en":"Researchers must not violate the terms of their agreement.","vi":"Các nhà nghiên cứu không được vi phạm các điều khoản trong thỏa thuận của họ."}]','[{"phrase":"violate the law"},{"phrase":"violate the terms"},{"phrase":"violate rules"}]',NULL,'/ˈvaɪəleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vio/viola/violate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3200,'awl-9-02',30,'vision','tầm nhìn; thị lực','noun','[{"en":"The new director has a clear vision for the university''s future.","vi":"Giám đốc mới có tầm nhìn rõ ràng cho tương lai của trường đại học."},{"en":"Regular eye tests can detect problems with vision early.","vi":"Khám mắt định kỳ có thể phát hiện sớm các vấn đề về thị lực."},{"en":"The company''s vision is to make clean energy affordable for everyone.","vi":"Tầm nhìn của công ty là giúp mọi người đều có thể chi trả cho năng lượng sạch."}]','[{"phrase":"clear vision"},{"phrase":"vision for the future"},{"phrase":"poor vision"}]',NULL,'/ˈvɪʒn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visio/vision__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3201,'awl-10-01',1,'adjacent','liền kề; kế bên','adjective','[{"en":"The new laboratory will be built on land adjacent to the hospital.","vi":"Phòng thí nghiệm mới sẽ được xây trên khu đất liền kề bệnh viện."},{"en":"Cells in adjacent areas of the tissue showed similar damage.","vi":"Các tế bào ở những vùng liền kề của mô cho thấy tổn thương tương tự."},{"en":"Two adjacent countries signed an agreement to share water resources.","vi":"Hai quốc gia kế bên nhau đã ký thỏa thuận chia sẻ nguồn nước."}]','[{"phrase":"adjacent to"},{"phrase":"adjacent areas"},{"phrase":"adjacent land"}]','adjacent to + danh từ','/əˈdʒeɪsnt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjac/adjacent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3202,'awl-10-01',2,'albeit','mặc dù; dù là','conjunction','[{"en":"The economy is growing, albeit slowly, according to the latest figures.","vi":"Theo số liệu mới nhất, nền kinh tế đang tăng trưởng, dù là chậm."},{"en":"The treatment was effective, albeit only for a small number of patients.","vi":"Phương pháp điều trị có hiệu quả, mặc dù chỉ với một số ít bệnh nhân."},{"en":"Prices rose again last month, albeit at a lower rate.","vi":"Giá cả lại tăng trong tháng trước, dù là với tốc độ thấp hơn."}]','[{"phrase":"albeit slowly"},{"phrase":"albeit briefly"},{"phrase":"albeit at a lower rate"}]','Trang trọng; thường theo sau là tính từ, trạng từ hoặc cụm giới từ','/ˌɔːlˈbiːɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alb/albei/albeit__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3203,'awl-10-01',3,'assemble','lắp ráp; tập hợp','verb','[{"en":"The cars are assembled in a factory outside the capital.","vi":"Những chiếc ô tô được lắp ráp tại một nhà máy ở ngoại ô thủ đô."},{"en":"Workers can assemble the device in less than ten minutes.","vi":"Công nhân có thể lắp ráp thiết bị này trong chưa đầy mười phút."},{"en":"The university assembled a team of experts to study the problem.","vi":"Trường đại học đã tập hợp một nhóm chuyên gia để nghiên cứu vấn đề này."}]','[{"phrase":"assemble a team"},{"phrase":"assemble evidence"},{"phrase":"assemble parts"}]',NULL,'/əˈsembl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assem/assemble__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3204,'awl-10-01',4,'collapse','sụp đổ; đổ sập; ngã quỵ','verb','[{"en":"Several old buildings collapsed during the earthquake last night.","vi":"Nhiều tòa nhà cũ đã đổ sập trong trận động đất tối qua."},{"en":"The company collapsed completely after years of poor management.","vi":"Công ty đã sụp đổ hoàn toàn sau nhiều năm quản lý yếu kém."},{"en":"One runner collapsed near the finish line and was taken to the hospital.","vi":"Một vận động viên đã ngã quỵ gần vạch đích và được đưa đến bệnh viện."}]','[{"phrase":"collapse completely"},{"phrase":"nearly collapse"},{"phrase":"the roof collapsed"}]',NULL,'/kəˈlæps/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colla/collapse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3205,'awl-10-01',5,'colleague','đồng nghiệp','noun','[{"en":"She discussed the proposal with her colleagues before the meeting.","vi":"Cô ấy đã thảo luận đề xuất với các đồng nghiệp trước cuộc họp."},{"en":"My colleague and I published a paper on climate change last year.","vi":"Tôi và đồng nghiệp đã công bố một bài báo về biến đổi khí hậu năm ngoái."},{"en":"A former colleague recommended him for the position.","vi":"Một đồng nghiệp cũ đã giới thiệu anh ấy vào vị trí này."}]','[{"phrase":"former colleague"},{"phrase":"close colleague"},{"phrase":"senior colleague"}]',NULL,'/ˈkɑːliːɡ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/colleague__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3206,'awl-10-01',6,'compile','biên soạn; tổng hợp','verb','[{"en":"The report was compiled from interviews with over two hundred teachers.","vi":"Báo cáo được biên soạn từ các cuộc phỏng vấn với hơn hai trăm giáo viên."},{"en":"We need to compile a list of suppliers for the new project.","vi":"Chúng ta cần lập một danh sách nhà cung cấp cho dự án mới."},{"en":"These figures were compiled by the national statistics office.","vi":"Những số liệu này do cơ quan thống kê quốc gia tổng hợp."}]','[{"phrase":"compile a list"},{"phrase":"compile a report"},{"phrase":"compile data"},{"phrase":"compile statistics"}]',NULL,'/kəmˈpaɪl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compi/compile__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3207,'awl-10-01',7,'conceive','nghĩ ra; hình dung','verb','[{"en":"The project was originally conceived as a small local study.","vi":"Dự án ban đầu được nghĩ ra như một nghiên cứu nhỏ ở địa phương."},{"en":"It is hard to conceive of a world without the internet.","vi":"Thật khó để hình dung một thế giới không có internet."},{"en":"Engineers conceived a cheaper way to store solar energy.","vi":"Các kỹ sư đã nghĩ ra một cách rẻ hơn để lưu trữ năng lượng mặt trời."}]','[{"phrase":"conceive of"},{"phrase":"originally conceived"},{"phrase":"conceive an idea"},{"phrase":"conceive a plan"}]','conceive of sth: hình dung điều gì','/kənˈsiːv/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconceive__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3208,'awl-10-01',8,'convince','thuyết phục; làm cho tin','verb','[{"en":"The results convinced the committee to continue funding the research.","vi":"Kết quả đã thuyết phục hội đồng tiếp tục tài trợ cho nghiên cứu."},{"en":"I am not fully convinced that this method will work.","vi":"Tôi không hoàn toàn tin rằng phương pháp này sẽ hiệu quả."},{"en":"She tried to convince investors that the plan was realistic.","vi":"Cô ấy đã cố thuyết phục các nhà đầu tư rằng kế hoạch này khả thi."}]','[{"phrase":"fully convinced"},{"phrase":"convince somebody to"},{"phrase":"convince somebody that"}]','convince sb to do sth / convince sb that ...','/kənˈvɪns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvince__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3209,'awl-10-01',9,'depress','làm giảm (giá, nhu cầu); làm chán nản','verb','[{"en":"Higher interest rates could depress demand for new homes.","vi":"Lãi suất cao hơn có thể làm giảm nhu cầu mua nhà mới."},{"en":"Cheap imports have depressed prices for local farmers.","vi":"Hàng nhập khẩu giá rẻ đã làm giảm giá bán của nông dân trong nước."},{"en":"Months without work had begun to depress him.","vi":"Nhiều tháng không có việc làm đã bắt đầu khiến anh ấy chán nản."}]','[{"phrase":"depress prices"},{"phrase":"depress demand"},{"phrase":"depress wages"}]',NULL,'/dɪˈpres/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dep/depre/depress__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3210,'awl-10-01',10,'encounter','gặp phải; bắt gặp','verb','[{"en":"The team encountered several problems during the first stage of testing.","vi":"Nhóm đã gặp phải một số vấn đề trong giai đoạn thử nghiệm đầu tiên."},{"en":"Students often encounter difficulties when writing their first research paper.","vi":"Sinh viên thường gặp khó khăn khi viết bài nghiên cứu đầu tiên."},{"en":"This species is rarely encountered outside the tropical forest.","vi":"Loài này hiếm khi được bắt gặp bên ngoài rừng nhiệt đới."}]','[{"phrase":"encounter problems"},{"phrase":"encounter difficulties"},{"phrase":"encounter resistance"}]',NULL,'/ɪnˈkaʊntər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enc/encou/encounter__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3211,'awl-10-01',11,'enormous','to lớn; khổng lồ','adjective','[{"en":"The new policy has had an enormous impact on small businesses.","vi":"Chính sách mới đã có tác động to lớn đến các doanh nghiệp nhỏ."},{"en":"Building the bridge required an enormous amount of money.","vi":"Việc xây cây cầu đòi hỏi một khoản tiền khổng lồ."},{"en":"There are enormous differences in income between rural and urban areas.","vi":"Có sự chênh lệch rất lớn về thu nhập giữa nông thôn và thành thị."}]','[{"phrase":"enormous amount"},{"phrase":"enormous impact"},{"phrase":"enormous pressure"}]',NULL,'/ɪˈnɔːrməs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eno/enorm/enormous__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3212,'awl-10-01',12,'forthcoming','sắp tới; sẵn có (được cung cấp)','adjective','[{"en":"Full details will be published in the forthcoming report.","vi":"Thông tin chi tiết sẽ được công bố trong báo cáo sắp tới."},{"en":"The results will be discussed at the forthcoming conference in May.","vi":"Kết quả sẽ được thảo luận tại hội nghị sắp tới vào tháng Năm."},{"en":"Despite repeated requests, no further information was forthcoming from the ministry.","vi":"Dù đã yêu cầu nhiều lần, bộ vẫn không cung cấp thêm thông tin nào."}]','[{"phrase":"forthcoming report"},{"phrase":"forthcoming conference"},{"phrase":"forthcoming book"}]','be forthcoming: được cung cấp, sẵn có','/ˌfɔːrθˈkʌmɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forth/forthcoming__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3213,'awl-10-01',13,'incline','có xu hướng; nghiêng về','verb','[{"en":"Many managers are inclined to hire people they already know.","vi":"Nhiều nhà quản lý có xu hướng tuyển những người họ đã quen biết."},{"en":"I''m inclined to agree with the reviewers on this point.","vi":"Tôi nghiêng về việc đồng ý với các nhà phản biện ở điểm này."},{"en":"Rising costs may incline some firms to move production overseas.","vi":"Chi phí tăng có thể khiến một số công ty có xu hướng chuyển sản xuất ra nước ngoài."}]','[{"phrase":"inclined to agree"},{"phrase":"inclined to believe"},{"phrase":"be inclined to"}]','Thường dùng bị động: be inclined to do sth','/ɪnˈklaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incli/incline__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3214,'awl-10-01',14,'integrity','sự chính trực; tính toàn vẹn','noun','[{"en":"Copying another student''s work is a serious breach of academic integrity.","vi":"Sao chép bài của sinh viên khác là vi phạm nghiêm trọng liêm chính học thuật."},{"en":"The auditor was widely respected for her honesty and integrity.","vi":"Kiểm toán viên ấy được nhiều người kính trọng vì sự trung thực và chính trực."},{"en":"Engineers checked the structural integrity of the bridge after the flood.","vi":"Các kỹ sư đã kiểm tra độ toàn vẹn kết cấu của cây cầu sau trận lũ."}]','[{"phrase":"academic integrity"},{"phrase":"structural integrity"},{"phrase":"data integrity"},{"phrase":"personal integrity"}]','Không đếm được','/ɪnˈteɡrəti/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integrity__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3215,'awl-10-01',15,'intrinsic','nội tại; vốn có','adjective','[{"en":"The old painting has little intrinsic value, but the family treasures it.","vi":"Bức tranh cũ có ít giá trị nội tại, nhưng gia đình rất trân quý nó."},{"en":"Students with strong intrinsic motivation tend to learn more effectively.","vi":"Những sinh viên có động lực nội tại mạnh thường học hiệu quả hơn."},{"en":"Risk is intrinsic to starting any new business.","vi":"Rủi ro là điều vốn có khi bắt đầu bất kỳ công việc kinh doanh mới nào."}]','[{"phrase":"intrinsic value"},{"phrase":"intrinsic motivation"},{"phrase":"intrinsic to"}]','intrinsic to sth: vốn có ở điều gì','/ɪnˈtrɪnzɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/intri/intrinsic__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3216,'awl-10-01',16,'invoke','viện dẫn; áp dụng (luật, điều khoản)','verb','[{"en":"The company invoked a clause in the contract to cancel the deal.","vi":"Công ty đã áp dụng một điều khoản trong hợp đồng để hủy thỏa thuận."},{"en":"The author invokes several earlier studies to support her argument.","vi":"Tác giả viện dẫn một số nghiên cứu trước đây để củng cố lập luận của mình."},{"en":"Judges sometimes invoke the principle of fairness in difficult cases.","vi":"Các thẩm phán đôi khi viện dẫn nguyên tắc công bằng trong những vụ việc khó."}]','[{"phrase":"invoke a clause"},{"phrase":"invoke the principle"},{"phrase":"invoke a right"}]',NULL,'/ɪnˈvəʊk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invok/invoke__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3217,'awl-10-01',17,'levy','đánh (thuế); thu (phí, tiền phạt)','verb','[{"en":"The city plans to levy a small tax on hotel rooms.","vi":"Thành phố dự định đánh một khoản thuế nhỏ lên phòng khách sạn."},{"en":"A heavy fine was levied on the company for polluting the river.","vi":"Công ty bị phạt một khoản tiền lớn vì gây ô nhiễm dòng sông."},{"en":"Many countries levy higher taxes on tobacco and alcohol.","vi":"Nhiều quốc gia đánh thuế cao hơn đối với thuốc lá và rượu bia."}]','[{"phrase":"levy a tax"},{"phrase":"levy a fine"},{"phrase":"levy taxes on"}]','levy sth on sb/sth; cũng là danh từ: khoản thuế','/ˈlevi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lev/levy_/levy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3218,'awl-10-01',18,'likewise','tương tự; cũng vậy','adverb','[{"en":"Rents rose sharply in the capital and likewise increased in smaller cities.","vi":"Giá thuê nhà tăng mạnh ở thủ đô và tương tự cũng tăng ở các thành phố nhỏ hơn."},{"en":"The first group followed the new rules, and the others did likewise.","vi":"Nhóm đầu tiên tuân theo quy định mới, và các nhóm khác cũng làm như vậy."},{"en":"Teachers should respect their students, and likewise students should respect teachers.","vi":"Giáo viên nên tôn trọng học sinh, và tương tự, học sinh cũng nên tôn trọng giáo viên."}]','[{"phrase":"do likewise"},{"phrase":"and likewise"}]',NULL,'/ˈlaɪkwaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lik/likew/likewise__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3219,'awl-10-01',19,'nonetheless','tuy nhiên; dù vậy','adverb','[{"en":"The sample was small, but the results are nonetheless important.","vi":"Mẫu nghiên cứu nhỏ, nhưng dù vậy kết quả vẫn quan trọng."},{"en":"The task was difficult; nonetheless, they completed it on time.","vi":"Nhiệm vụ rất khó; tuy nhiên, họ vẫn hoàn thành đúng hạn."},{"en":"The plan is risky but nonetheless worth trying.","vi":"Kế hoạch này rủi ro nhưng dù vậy vẫn đáng để thử."}]','[{"phrase":"but nonetheless"},{"phrase":"nonetheless important"}]',NULL,'/ˌnʌnðəˈles/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/non/nonet/nonetheless__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3220,'awl-10-01',20,'notwithstanding','mặc dù; bất chấp','preposition','[{"en":"Notwithstanding the difficulties, the team finished the project on time.","vi":"Mặc dù gặp nhiều khó khăn, nhóm vẫn hoàn thành dự án đúng hạn."},{"en":"The new rules apply to all staff, notwithstanding any earlier agreement.","vi":"Quy định mới áp dụng cho toàn bộ nhân viên, bất chấp mọi thỏa thuận trước đó."},{"en":"Economic problems notwithstanding, the region continues to attract foreign investors.","vi":"Bất chấp những khó khăn kinh tế, khu vực này vẫn tiếp tục thu hút nhà đầu tư nước ngoài."}]','[{"phrase":"notwithstanding the difficulties"},{"phrase":"notwithstanding the fact that"}]','Rất trang trọng; có thể đứng sau danh từ','/ˌnɑːtwɪθˈstændɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/not/notwi/notwithstanding__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3221,'awl-10-01',21,'odd','kỳ lạ; (số) lẻ','adjective','[{"en":"It seems odd that nobody noticed the error earlier.","vi":"Thật lạ là không ai phát hiện ra lỗi này sớm hơn."},{"en":"Each participant with an odd number joined the first group.","vi":"Mỗi người tham gia mang số lẻ được xếp vào nhóm thứ nhất."},{"en":"There was something odd about the results of the second test.","vi":"Có điều gì đó kỳ lạ trong kết quả của lần kiểm tra thứ hai."}]','[{"phrase":"odd number"},{"phrase":"seem odd"},{"phrase":"something odd"}]','odd number (số lẻ) ≠ even number (số chẵn)','/ɑːd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/odd/odd__/odd__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3222,'awl-10-01',22,'ongoing','đang diễn ra; liên tục','adjective','[{"en":"The investigation into the accident is still ongoing.","vi":"Cuộc điều tra về vụ tai nạn vẫn đang diễn ra."},{"en":"Ongoing research suggests the drug may help older patients.","vi":"Nghiên cứu đang được tiến hành cho thấy loại thuốc này có thể giúp ích cho bệnh nhân lớn tuổi."},{"en":"New staff receive ongoing training throughout their first year.","vi":"Nhân viên mới được đào tạo liên tục trong suốt năm đầu tiên."}]','[{"phrase":"ongoing research"},{"phrase":"ongoing training"},{"phrase":"ongoing support"},{"phrase":"ongoing process"}]',NULL,'/ˈɑːnɡəʊɪŋ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ong/ongoi/ongoing__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3223,'awl-10-01',23,'panel','ban, hội đồng (chuyên gia); tấm','noun','[{"en":"A panel of experts will review all the applications.","vi":"Một hội đồng chuyên gia sẽ xem xét tất cả các hồ sơ."},{"en":"The panel discussion focused on the future of online education.","vi":"Buổi thảo luận chuyên đề tập trung vào tương lai của giáo dục trực tuyến."},{"en":"The school uses solar panels to produce most of its electricity.","vi":"Ngôi trường sử dụng tấm pin mặt trời để tạo ra phần lớn lượng điện."}]','[{"phrase":"panel of experts"},{"phrase":"panel discussion"},{"phrase":"solar panel"},{"phrase":"expert panel"}]',NULL,'/ˈpænl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pan/panel/panel__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3224,'awl-10-01',24,'persist','vẫn tiếp diễn; kéo dài; kiên trì','verb','[{"en":"If the symptoms persist, patients should see a doctor.","vi":"Nếu các triệu chứng kéo dài, bệnh nhân nên đi khám bác sĩ."},{"en":"Inequality between regions has persisted for several decades.","vi":"Sự bất bình đẳng giữa các vùng đã tiếp diễn trong nhiều thập kỷ."},{"en":"She persisted with her research despite a lack of funding.","vi":"Cô ấy vẫn kiên trì với nghiên cứu của mình dù thiếu kinh phí."}]','[{"phrase":"symptoms persist"},{"phrase":"persist with"},{"phrase":"persist in"},{"phrase":"problems persist"}]','persist in/with sth','/pərˈsɪst/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persi/persist__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3225,'awl-10-01',25,'pose','gây ra (mối đe dọa, rủi ro); đặt ra (câu hỏi)','verb','[{"en":"Rising sea levels pose a serious threat to coastal cities.","vi":"Mực nước biển dâng cao gây ra mối đe dọa nghiêm trọng cho các thành phố ven biển."},{"en":"Poor storage conditions may pose a risk to public health.","vi":"Điều kiện bảo quản kém có thể gây rủi ro cho sức khỏe cộng đồng."},{"en":"The report poses important questions about data privacy.","vi":"Báo cáo đặt ra những câu hỏi quan trọng về quyền riêng tư dữ liệu."}]','[{"phrase":"pose a threat"},{"phrase":"pose a risk"},{"phrase":"pose a challenge"},{"phrase":"pose a question"}]',NULL,'/pəʊz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/pose_/pose__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3226,'awl-10-01',26,'reluctance','sự miễn cưỡng; sự ngần ngại','noun','[{"en":"Many firms show reluctance to invest during uncertain times.","vi":"Nhiều công ty tỏ ra ngần ngại đầu tư trong thời kỳ bất ổn."},{"en":"Her reluctance to share the data slowed down the project.","vi":"Sự miễn cưỡng chia sẻ dữ liệu của cô ấy đã làm chậm dự án."},{"en":"Despite his initial reluctance, he agreed to lead the team.","vi":"Dù ban đầu còn ngần ngại, anh ấy đã đồng ý dẫn dắt nhóm."}]','[{"phrase":"reluctance to"},{"phrase":"initial reluctance"},{"phrase":"show reluctance"}]','reluctance to do sth','/rɪˈlʌktəns/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/reluc/reluctance__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3227,'awl-10-01',27,'so-called','cái gọi là; được gọi là','adjective','[{"en":"The so-called experts failed to predict the financial crisis.","vi":"Những người được gọi là chuyên gia đã không dự đoán được cuộc khủng hoảng tài chính."},{"en":"Many so-called healthy snacks actually contain a lot of sugar.","vi":"Nhiều loại đồ ăn vặt được gọi là lành mạnh thực ra chứa rất nhiều đường."},{"en":"These gases contribute to the so-called greenhouse effect.","vi":"Những khí này góp phần gây ra cái gọi là hiệu ứng nhà kính."}]','[{"phrase":"the so-called"},{"phrase":"so-called experts"}]','Thường mang ý hoài nghi, mỉa mai','/ˌsəʊ ˈkɔːld/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/so_/so_ca/so_called_1_us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3228,'awl-10-01',28,'straightforward','đơn giản, dễ hiểu; thẳng thắn','adjective','[{"en":"The online application process is fairly straightforward and quick.","vi":"Quy trình nộp hồ sơ trực tuyến khá đơn giản và nhanh chóng."},{"en":"There is no straightforward answer to this question.","vi":"Không có câu trả lời đơn giản cho câu hỏi này."},{"en":"She was very straightforward with us about her mistakes.","vi":"Cô ấy rất thẳng thắn với chúng tôi về những sai lầm của mình."}]','[{"phrase":"fairly straightforward"},{"phrase":"relatively straightforward"},{"phrase":"straightforward answer"},{"phrase":"straightforward process"}]',NULL,'/ˌstreɪtˈfɔːrwərd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strai/straightforward__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3229,'awl-10-01',29,'undergo','trải qua','verb','[{"en":"The city has undergone major changes over the past decade.","vi":"Thành phố đã trải qua nhiều thay đổi lớn trong thập kỷ qua."},{"en":"All new drugs must undergo testing before they can be sold.","vi":"Mọi loại thuốc mới đều phải trải qua kiểm nghiệm trước khi được bán."},{"en":"He underwent surgery on his knee last month.","vi":"Anh ấy đã phẫu thuật đầu gối vào tháng trước."}]','[{"phrase":"undergo surgery"},{"phrase":"undergo changes"},{"phrase":"undergo treatment"},{"phrase":"undergo testing"}]','undergo – underwent – undergone','/ˌʌndərˈɡəʊ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/und/under/undergo__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3230,'awl-10-01',30,'whereby','theo đó; nhờ đó','adverb','[{"en":"The company introduced a system whereby staff can work from home.","vi":"Công ty đã áp dụng một hệ thống theo đó nhân viên có thể làm việc tại nhà."},{"en":"Both sides signed an agreement whereby they would share the costs.","vi":"Hai bên đã ký một thỏa thuận, theo đó họ sẽ cùng chia sẻ chi phí."},{"en":"Photosynthesis is the process whereby plants turn sunlight into energy.","vi":"Quang hợp là quá trình nhờ đó thực vật biến ánh sáng mặt trời thành năng lượng."}]','[{"phrase":"a system whereby"},{"phrase":"an agreement whereby"},{"phrase":"a process whereby"}]','Trang trọng; = by which','/werˈbaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/whereby__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3231,'awl-8-02',1,'induce','gây ra; khiến, thúc đẩy (ai làm gì)','verb','[{"en":"This medicine can induce drowsiness in some patients.","vi":"Loại thuốc này có thể gây buồn ngủ ở một số bệnh nhân."},{"en":"Higher wages may induce more workers to move to the city.","vi":"Mức lương cao hơn có thể khiến nhiều lao động chuyển đến thành phố hơn."},{"en":"Long-term stress can induce changes in the immune system.","vi":"Căng thẳng kéo dài có thể gây ra những thay đổi trong hệ miễn dịch."}]','[{"phrase":"induce sleep"},{"phrase":"induce somebody to do something"},{"phrase":"stress-induced"}]',NULL,'/ɪnˈduːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/induc/induce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3232,'awl-8-02',2,'inevitable','không thể tránh khỏi; tất yếu','adjective','[{"en":"Some job losses are inevitable when factories introduce new technology.","vi":"Khi các nhà máy áp dụng công nghệ mới, việc mất một số việc làm là không thể tránh khỏi."},{"en":"It was inevitable that prices would rise after the fuel shortage.","vi":"Giá cả tăng lên sau đợt thiếu hụt nhiên liệu là điều tất yếu."},{"en":"Delays are almost inevitable in a project of this size.","vi":"Chậm trễ gần như là không thể tránh khỏi trong một dự án quy mô như thế này."}]','[{"phrase":"almost inevitable"},{"phrase":"inevitable consequence"},{"phrase":"it is inevitable that"}]',NULL,'/ɪnˈevɪtəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ine/inevi/inevitable__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3233,'awl-8-02',3,'infrastructure','cơ sở hạ tầng','noun','[{"en":"The government plans to invest heavily in transport infrastructure.","vi":"Chính phủ dự định đầu tư mạnh vào cơ sở hạ tầng giao thông."},{"en":"Many rural areas still lack basic infrastructure such as clean water.","vi":"Nhiều vùng nông thôn vẫn thiếu cơ sở hạ tầng cơ bản như nước sạch."},{"en":"Poor infrastructure makes it difficult for companies to move goods quickly.","vi":"Cơ sở hạ tầng yếu kém khiến các công ty khó vận chuyển hàng hóa nhanh chóng."}]','[{"phrase":"transport infrastructure"},{"phrase":"basic infrastructure"},{"phrase":"invest in infrastructure"}]',NULL,'/ˈɪnfrəstrʌktʃər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infra/infrastructure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3234,'awl-8-02',4,'inspect','kiểm tra; thanh tra','verb','[{"en":"Officials inspect the factory every six months for safety problems.","vi":"Cán bộ thanh tra kiểm tra nhà máy sáu tháng một lần để phát hiện các vấn đề an toàn."},{"en":"The engineer carefully inspected the bridge for signs of damage.","vi":"Kỹ sư đã kiểm tra kỹ cây cầu để tìm dấu hiệu hư hỏng."},{"en":"All food products must be inspected before they leave the warehouse.","vi":"Tất cả sản phẩm thực phẩm phải được kiểm tra trước khi rời kho."}]','[{"phrase":"carefully inspect"},{"phrase":"inspect for damage"},{"phrase":"inspect the premises"}]',NULL,'/ɪnˈspekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/inspe/inspect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3235,'awl-8-02',5,'intense','mạnh mẽ, dữ dội; gay gắt, căng thẳng','adjective','[{"en":"The company faces intense competition from cheaper foreign producers.","vi":"Công ty phải đối mặt với sự cạnh tranh gay gắt từ các nhà sản xuất nước ngoài có giá rẻ hơn."},{"en":"Kitchen staff must cope with intense heat throughout the day.","vi":"Nhân viên bếp phải chịu đựng cái nóng dữ dội suốt cả ngày."},{"en":"The proposal led to an intense debate among committee members.","vi":"Đề xuất này đã dẫn đến một cuộc tranh luận gay gắt giữa các thành viên hội đồng."}]','[{"phrase":"intense competition"},{"phrase":"intense pressure"},{"phrase":"intense debate"},{"phrase":"intense heat"}]',NULL,'/ɪnˈtens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intense__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3236,'awl-8-02',6,'manipulate','thao túng; xử lý, điều khiển (khéo léo)','verb','[{"en":"Some advertisements try to manipulate people into buying things they don’t need.","vi":"Một số quảng cáo tìm cách thao túng mọi người để họ mua những thứ không cần thiết."},{"en":"The researchers were accused of manipulating data to support their theory.","vi":"Các nhà nghiên cứu bị cáo buộc đã thao túng dữ liệu để củng cố lý thuyết của mình."},{"en":"Students learn how to manipulate images using computer software.","vi":"Sinh viên học cách xử lý hình ảnh bằng phần mềm máy tính."}]','[{"phrase":"manipulate data"},{"phrase":"manipulate public opinion"},{"phrase":"manipulate somebody into"}]',NULL,'/məˈnɪpjuleɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manip/manipulate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3237,'awl-8-02',7,'minimise','giảm thiểu; giảm đến mức thấp nhất','verb','[{"en":"We must take steps to minimise the risk of infection.","vi":"Chúng ta phải có biện pháp để giảm thiểu nguy cơ lây nhiễm."},{"en":"The new design minimises energy use without reducing performance.","vi":"Thiết kế mới giảm thiểu mức tiêu thụ năng lượng mà không làm giảm hiệu suất."},{"en":"Careful planning helped minimise disruption to local residents during construction.","vi":"Việc lên kế hoạch cẩn thận đã giúp giảm thiểu sự xáo trộn đối với cư dân địa phương trong quá trình xây dựng."}]','[{"phrase":"minimise the risk"},{"phrase":"minimise costs"},{"phrase":"minimise the impact"},{"phrase":"minimise disruption"}]','Anh: minimise · Mỹ: minimize',NULL,NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3238,'awl-8-02',8,'nuclear','(thuộc) hạt nhân','adjective','[{"en":"The country produces about a third of its electricity from nuclear power.","vi":"Quốc gia này sản xuất khoảng một phần ba lượng điện từ năng lượng hạt nhân."},{"en":"Engineers regularly check the safety systems at the nuclear power station.","vi":"Các kỹ sư thường xuyên kiểm tra hệ thống an toàn tại nhà máy điện hạt nhân."},{"en":"The storage of nuclear waste remains a serious environmental problem.","vi":"Việc lưu trữ chất thải hạt nhân vẫn là một vấn đề môi trường nghiêm trọng."}]','[{"phrase":"nuclear power"},{"phrase":"nuclear energy"},{"phrase":"nuclear waste"},{"phrase":"nuclear power station"}]',NULL,'/ˈnuːkliər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nuc/nucle/nuclear__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3239,'awl-8-02',9,'offset','bù đắp; bù trừ','verb','[{"en":"Strong sales in Asia helped offset losses in the European market.","vi":"Doanh số cao ở châu Á đã giúp bù đắp khoản lỗ tại thị trường châu Âu."},{"en":"The rise in costs was partly offset by lower taxes.","vi":"Việc chi phí tăng đã được bù đắp một phần nhờ thuế thấp hơn."},{"en":"Some companies plant trees to offset their carbon emissions.","vi":"Một số công ty trồng cây để bù đắp lượng khí thải carbon của họ."}]','[{"phrase":"offset the cost"},{"phrase":"partly offset"},{"phrase":"offset losses"},{"phrase":"offset carbon emissions"}]','offset – offset – offset','/ˈɔːfset/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offse/offset__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3240,'awl-8-02',10,'paragraph','đoạn văn','noun','[{"en":"Each paragraph in your essay should focus on one main idea.","vi":"Mỗi đoạn văn trong bài luận của bạn nên tập trung vào một ý chính."},{"en":"The author explains her method in the second paragraph of the introduction.","vi":"Tác giả giải thích phương pháp của mình ở đoạn thứ hai của phần mở đầu."},{"en":"Please add a short paragraph summarizing the main findings.","vi":"Vui lòng thêm một đoạn văn ngắn tóm tắt các phát hiện chính."}]','[{"phrase":"opening paragraph"},{"phrase":"final paragraph"},{"phrase":"a short paragraph"},{"phrase":"previous paragraph"}]',NULL,'/ˈpærəɡræf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parag/paragraph__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3241,'awl-8-02',11,'plus','cộng; cộng thêm, cùng với','preposition','[{"en":"The ticket costs forty dollars, plus a small booking fee.","vi":"Vé có giá bốn mươi đô la, cộng thêm một khoản phí đặt chỗ nhỏ."},{"en":"Applicants need a degree plus two years of relevant work experience.","vi":"Ứng viên cần có bằng đại học cùng với hai năm kinh nghiệm làm việc liên quan."},{"en":"You will have to repay the loan plus interest within five years.","vi":"Bạn sẽ phải trả khoản vay cộng tiền lãi trong vòng năm năm."}]','[{"phrase":"plus tax"},{"phrase":"plus interest"},{"phrase":"plus or minus"}]',NULL,'/plʌs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/plu/plus_/plus__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3242,'awl-8-02',12,'practitioner','người hành nghề (y, luật…); người làm thực tiễn','noun','[{"en":"Medical practitioners must renew their licenses every five years.","vi":"Người hành nghề y phải gia hạn giấy phép năm năm một lần."},{"en":"The workshop brings together researchers and practitioners from across the industry.","vi":"Hội thảo quy tụ các nhà nghiên cứu và những người làm thực tiễn từ khắp ngành."},{"en":"Patients should see a general practitioner before visiting a specialist.","vi":"Bệnh nhân nên khám bác sĩ đa khoa trước khi đến gặp bác sĩ chuyên khoa."}]','[{"phrase":"medical practitioner"},{"phrase":"general practitioner"},{"phrase":"legal practitioner"},{"phrase":"health practitioner"}]',NULL,'/prækˈtɪʃənər/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pra/pract/practitioner__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3243,'awl-8-02',13,'predominant','chiếm ưu thế; chủ yếu','adjective','[{"en":"English is the predominant language of international scientific journals.","vi":"Tiếng Anh là ngôn ngữ chiếm ưu thế trong các tạp chí khoa học quốc tế."},{"en":"Farming remains the predominant source of income in the region.","vi":"Nông nghiệp vẫn là nguồn thu nhập chủ yếu trong khu vực."},{"en":"Anxiety was the predominant feeling among staff after the merger was announced.","vi":"Lo lắng là tâm trạng chủ yếu của nhân viên sau khi việc sáp nhập được công bố."}]','[{"phrase":"predominant role"},{"phrase":"predominant feature"},{"phrase":"predominant language"}]',NULL,'/prɪˈdɑːmɪnənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/predo/predominant__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3244,'awl-8-02',14,'prospect','triển vọng; khả năng (xảy ra)','noun','[{"en":"Graduates with engineering degrees have excellent job prospects.","vi":"Sinh viên tốt nghiệp ngành kỹ thuật có triển vọng việc làm rất tốt."},{"en":"There is little prospect of an agreement before the end of the year.","vi":"Có rất ít khả năng đạt được thỏa thuận trước cuối năm."},{"en":"The prospect of higher interest rates worries many small business owners.","vi":"Khả năng lãi suất tăng khiến nhiều chủ doanh nghiệp nhỏ lo lắng."}]','[{"phrase":"job prospects"},{"phrase":"career prospects"},{"phrase":"long-term prospects"},{"phrase":"little prospect of"}]',NULL,'/ˈprɑːspekt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prosp/prospect__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3245,'awl-8-02',15,'radical','căn bản, triệt để; cấp tiến','adjective','[{"en":"The industry needs radical changes to reduce its carbon emissions.","vi":"Ngành công nghiệp này cần những thay đổi căn bản để giảm lượng khí thải carbon."},{"en":"The report proposes a radical reform of the tax system.","vi":"Báo cáo đề xuất một cuộc cải cách triệt để hệ thống thuế."},{"en":"At the time, his ideas about education were considered radical.","vi":"Vào thời điểm đó, những ý tưởng của ông về giáo dục bị coi là cấp tiến."}]','[{"phrase":"radical change"},{"phrase":"radical reform"},{"phrase":"radical ideas"},{"phrase":"radical approach"}]',NULL,'/ˈrædɪkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rad/radic/radical__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3246,'awl-8-02',16,'random','ngẫu nhiên','adjective','[{"en":"The researchers selected a random sample of 500 households.","vi":"Các nhà nghiên cứu đã chọn một mẫu ngẫu nhiên gồm 500 hộ gia đình."},{"en":"Security staff carry out random checks on bags at the entrance.","vi":"Nhân viên an ninh tiến hành kiểm tra túi xách ngẫu nhiên tại lối vào."},{"en":"The winners will be chosen at random from all the entries.","vi":"Người thắng cuộc sẽ được chọn ngẫu nhiên từ tất cả các bài dự thi."}]','[{"phrase":"random sample"},{"phrase":"at random"},{"phrase":"random checks"},{"phrase":"random selection"}]',NULL,'/ˈrændəm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ran/rando/random__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3247,'awl-8-02',17,'reinforce','củng cố, tăng cường; gia cố','verb','[{"en":"The study’s findings reinforce the importance of early education.","vi":"Những phát hiện của nghiên cứu càng củng cố tầm quan trọng của giáo dục sớm."},{"en":"Regular practice helps reinforce what students have learned in class.","vi":"Luyện tập thường xuyên giúp củng cố những gì học sinh đã học trên lớp."},{"en":"Engineers reinforced the walls with steel to protect against earthquakes.","vi":"Các kỹ sư đã gia cố tường bằng thép để chống động đất."}]','[{"phrase":"reinforce the idea"},{"phrase":"reinforce the message"},{"phrase":"reinforced concrete"}]',NULL,'/ˌriːɪnˈfɔːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rei/reinf/reinforce__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3248,'awl-8-02',18,'restore','khôi phục; phục hồi, trùng tu','verb','[{"en":"Engineers worked through the night to restore power to the city.","vi":"Các kỹ sư đã làm việc suốt đêm để khôi phục điện cho thành phố."},{"en":"The old theater has been carefully restored to its original condition.","vi":"Nhà hát cũ đã được trùng tu cẩn thận, trở lại nguyên trạng ban đầu."},{"en":"The new management team hopes to restore confidence among investors.","vi":"Ban quản lý mới hy vọng khôi phục niềm tin của các nhà đầu tư."}]','[{"phrase":"restore confidence"},{"phrase":"restore order"},{"phrase":"restore power"},{"phrase":"fully restored"}]',NULL,'/rɪˈstɔːr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resto/restore__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3249,'awl-8-02',19,'revise','sửa đổi; điều chỉnh','verb','[{"en":"The bank has revised its growth forecast for next year.","vi":"Ngân hàng đã điều chỉnh dự báo tăng trưởng cho năm tới."},{"en":"Please revise your essay and submit it again by Friday.","vi":"Vui lòng sửa lại bài luận và nộp lại trước thứ Sáu."},{"en":"The company revised its safety rules after the accident.","vi":"Công ty đã sửa đổi các quy định an toàn sau vụ tai nạn."}]','[{"phrase":"revise a forecast"},{"phrase":"revise estimates"},{"phrase":"revised edition"},{"phrase":"revised version"}]',NULL,'/rɪˈvaɪz/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revis/revise__us_3.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3250,'awl-8-02',20,'schedule','lịch trình, thời gian biểu; kế hoạch (tiến độ)','noun','[{"en":"The project is running two weeks behind schedule.","vi":"Dự án đang chậm hai tuần so với kế hoạch."},{"en":"Check the train schedule before you leave the office.","vi":"Hãy xem lịch tàu chạy trước khi bạn rời văn phòng."},{"en":"Doctors often work a demanding schedule with very long shifts.","vi":"Các bác sĩ thường làm việc theo lịch trình khắt khe với những ca trực rất dài."}]','[{"phrase":"behind schedule"},{"phrase":"on schedule"},{"phrase":"busy schedule"},{"phrase":"tight schedule"}]',NULL,'/ˈskedʒuːl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sch/sched/schedule__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3251,'awl-8-02',21,'tense','căng thẳng','adjective','[{"en":"Relations between management and the union have been tense for months.","vi":"Quan hệ giữa ban quản lý và công đoàn đã căng thẳng suốt nhiều tháng."},{"en":"The meeting was tense because nobody could agree on the budget.","vi":"Cuộc họp diễn ra căng thẳng vì không ai thống nhất được về ngân sách."},{"en":"Many students feel tense before important exams.","vi":"Nhiều sinh viên cảm thấy căng thẳng trước những kỳ thi quan trọng."}]','[{"phrase":"tense atmosphere"},{"phrase":"tense situation"},{"phrase":"feel tense"}]','tense (n): thì (ngữ pháp)','/tens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tense/tense__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3252,'awl-8-02',22,'terminate','chấm dứt; kết thúc','verb','[{"en":"The company terminated the contract after repeated delays.","vi":"Công ty đã chấm dứt hợp đồng sau nhiều lần chậm trễ."},{"en":"Either party may terminate the agreement with thirty days’ notice.","vi":"Bất kỳ bên nào cũng có thể chấm dứt thỏa thuận nếu báo trước ba mươi ngày."},{"en":"This train terminates at the central station.","vi":"Chuyến tàu này kết thúc hành trình tại ga trung tâm."}]','[{"phrase":"terminate a contract"},{"phrase":"terminate an agreement"},{"phrase":"terminate employment"}]',NULL,'/ˈtɜːrmɪneɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ter/termi/terminate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3253,'awl-8-02',23,'theme','chủ đề','noun','[{"en":"Climate change was the main theme of this year’s conference.","vi":"Biến đổi khí hậu là chủ đề chính của hội nghị năm nay."},{"en":"Several common themes emerged from the interviews with teachers.","vi":"Một số chủ đề chung đã nổi lên từ các cuộc phỏng vấn giáo viên."},{"en":"The novel explores themes of loss and identity.","vi":"Cuốn tiểu thuyết khai thác các chủ đề về mất mát và bản sắc."}]','[{"phrase":"main theme"},{"phrase":"central theme"},{"phrase":"common theme"},{"phrase":"recurring theme"}]',NULL,'/θiːm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theme/theme__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3254,'awl-8-02',24,'thereby','do đó, nhờ đó; bằng cách đó','adverb','[{"en":"The company cut its prices, thereby attracting many new customers.","vi":"Công ty đã giảm giá, nhờ đó thu hút được nhiều khách hàng mới."},{"en":"Trees absorb carbon dioxide, thereby reducing the effects of climate change.","vi":"Cây xanh hấp thụ khí carbon dioxide, qua đó làm giảm tác động của biến đổi khí hậu."},{"en":"The new system saves time and thereby lowers operating costs.","vi":"Hệ thống mới tiết kiệm thời gian và do đó giảm chi phí vận hành."}]','[{"phrase":"thereby reducing"},{"phrase":"thereby increasing"},{"phrase":"thereby allowing"}]',NULL,'/ˌðerˈbaɪ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/there/thereby__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3255,'awl-8-02',25,'uniform','đồng nhất, đồng đều; thống nhất','adjective','[{"en":"The rules should be applied in a uniform way across all departments.","vi":"Các quy định cần được áp dụng một cách thống nhất ở tất cả các phòng ban."},{"en":"The samples were heated to a uniform temperature of 80 degrees.","vi":"Các mẫu được nung nóng đồng đều ở nhiệt độ 80 độ."},{"en":"Economic growth has not been uniform across the country.","vi":"Tăng trưởng kinh tế không đồng đều trên cả nước."}]','[{"phrase":"uniform standards"},{"phrase":"uniform rate"},{"phrase":"uniform temperature"},{"phrase":"uniform distribution"}]','uniform (n): đồng phục','/ˈjuːnɪfɔːrm/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unifo/uniform__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3256,'awl-8-02',26,'vehicle','xe, phương tiện (giao thông); phương tiện (truyền tải)','noun','[{"en":"Electric vehicles are becoming cheaper and more popular.","vi":"Xe điện ngày càng rẻ hơn và phổ biến hơn."},{"en":"Police stopped several vehicles on the main road this morning.","vi":"Sáng nay cảnh sát đã dừng một số phương tiện trên đường chính."},{"en":"Social media has become a powerful vehicle for marketing new products.","vi":"Mạng xã hội đã trở thành một phương tiện hữu hiệu để quảng bá sản phẩm mới."}]','[{"phrase":"electric vehicle"},{"phrase":"motor vehicle"},{"phrase":"commercial vehicle"},{"phrase":"vehicle for"}]',NULL,'/ˈviːəkl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/veh/vehic/vehicle__us_5.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3257,'awl-8-02',27,'via','qua, thông qua; đi qua (nơi nào)','preposition','[{"en":"Participants can complete the survey via email or by phone.","vi":"Người tham gia có thể hoàn thành khảo sát qua email hoặc qua điện thoại."},{"en":"The goods are shipped to Europe via a port in the south.","vi":"Hàng hóa được vận chuyển sang châu Âu qua một cảng ở phía nam."},{"en":"The lecture will be broadcast live via the university website.","vi":"Bài giảng sẽ được phát trực tiếp qua trang web của trường đại học."}]','[{"phrase":"via email"},{"phrase":"via the internet"},{"phrase":"via satellite"}]',NULL,'/ˈvaɪə/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/via/via__/via__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3258,'awl-8-02',28,'virtual','ảo, trực tuyến; gần như, hầu như','adjective','[{"en":"Many companies now hold virtual meetings instead of sending staff abroad.","vi":"Nhiều công ty hiện tổ chức các cuộc họp trực tuyến thay vì cử nhân viên ra nước ngoài."},{"en":"Students can explore the museum through a virtual tour.","vi":"Học sinh có thể khám phá bảo tàng qua một chuyến tham quan ảo."},{"en":"The strike brought the city’s transport system to a virtual standstill.","vi":"Cuộc đình công đã khiến hệ thống giao thông của thành phố gần như tê liệt."}]','[{"phrase":"virtual reality"},{"phrase":"virtual meeting"},{"phrase":"virtual tour"},{"phrase":"virtual standstill"}]',NULL,'/ˈvɜːrtʃuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vir/virtu/virtual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3259,'awl-8-02',29,'visual','(thuộc) thị giác; trực quan, bằng hình ảnh','adjective','[{"en":"Charts and other visual aids make presentations easier to follow.","vi":"Biểu đồ và các phương tiện trực quan khác giúp bài thuyết trình dễ theo dõi hơn."},{"en":"The study measured changes in patients’ visual memory over time.","vi":"Nghiên cứu đã đo những thay đổi về trí nhớ thị giác của bệnh nhân theo thời gian."},{"en":"The website’s visual design was updated to attract younger users.","vi":"Thiết kế hình ảnh của trang web đã được cập nhật để thu hút người dùng trẻ hơn."}]','[{"phrase":"visual aids"},{"phrase":"visual arts"},{"phrase":"visual effects"},{"phrase":"visual impairment"}]',NULL,'/ˈvɪʒuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visua/visual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3260,'awl-8-02',30,'widespread','phổ biến, lan rộng; trên diện rộng','adjective','[{"en":"Smartphone use is now widespread among older adults.","vi":"Việc sử dụng điện thoại thông minh hiện đã phổ biến ở người lớn tuổi."},{"en":"Heavy rain caused widespread flooding across the region.","vi":"Mưa lớn đã gây ngập lụt trên diện rộng khắp khu vực."},{"en":"The new policy has received widespread support from teachers.","vi":"Chính sách mới đã nhận được sự ủng hộ rộng rãi từ giáo viên."}]','[{"phrase":"widespread support"},{"phrase":"widespread use"},{"phrase":"widespread concern"}]',NULL,'/ˈwaɪdspred/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wid/wides/widespread__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3261,'awl-9-01',1,'accommodate','chứa được; đáp ứng; bố trí chỗ ở','verb','[{"en":"The new lecture hall can accommodate up to five hundred students.","vi":"Giảng đường mới có thể chứa tới năm trăm sinh viên."},{"en":"We try to accommodate the needs of students with disabilities.","vi":"Chúng tôi cố gắng đáp ứng nhu cầu của sinh viên khuyết tật."},{"en":"Visiting researchers are accommodated in apartments near the campus.","vi":"Các nhà nghiên cứu thỉnh giảng được bố trí ở trong các căn hộ gần trường."}]','[{"phrase":"accommodate the needs of"},{"phrase":"accommodate changes"},{"phrase":"easily accommodate"}]',NULL,'/əˈkɑːmədeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accom/accommodate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3262,'awl-9-01',2,'analogy','sự so sánh tương đồng; phép loại suy','noun','[{"en":"The teacher used a simple analogy to explain how the heart works.","vi":"Giáo viên dùng một phép so sánh đơn giản để giải thích cách tim hoạt động."},{"en":"Some economists draw an analogy between the two financial crises.","vi":"Một số nhà kinh tế học so sánh tương đồng giữa hai cuộc khủng hoảng tài chính."},{"en":"By analogy, a computer''s memory is often compared to a library.","vi":"Theo phép loại suy, bộ nhớ máy tính thường được ví như một thư viện."}]','[{"phrase":"draw an analogy"},{"phrase":"a useful analogy"},{"phrase":"by analogy"},{"phrase":"analogy between"}]','draw an analogy between A and B: so sánh A với B','/əˈnælədʒi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ana/analo/analogy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3263,'awl-9-01',3,'anticipate','dự đoán; lường trước','verb','[{"en":"Few experts anticipated such a sharp rise in energy prices.","vi":"Rất ít chuyên gia dự đoán được giá năng lượng sẽ tăng mạnh như vậy."},{"en":"Good managers anticipate problems before they become serious.","vi":"Những nhà quản lý giỏi lường trước vấn đề trước khi chúng trở nên nghiêm trọng."},{"en":"The project took much longer than we had anticipated.","vi":"Dự án mất nhiều thời gian hơn nhiều so với chúng tôi đã dự tính."}]','[{"phrase":"anticipate problems"},{"phrase":"anticipate demand"},{"phrase":"than anticipated"},{"phrase":"widely anticipated"}]','anticipate + V-ing (không dùng to V)','/ænˈtɪsɪpeɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ant/antic/anticipate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3264,'awl-9-01',4,'assure','cam đoan; đảm bảo với ai; trấn an','verb','[{"en":"The manager assured staff that no jobs would be lost.","vi":"Người quản lý cam đoan với nhân viên rằng sẽ không ai bị mất việc."},{"en":"I can assure you that your data will be kept private.","vi":"Tôi có thể đảm bảo với bạn rằng dữ liệu của bạn sẽ được giữ bí mật."},{"en":"Officials assured residents that the tap water was safe to drink.","vi":"Giới chức trấn an người dân rằng nước máy an toàn để uống."}]','[{"phrase":"assure somebody that"},{"phrase":"I can assure you"},{"phrase":"rest assured"}]','assure (cam đoan với ai) ≠ ensure (đảm bảo điều gì xảy ra)','/əˈʃʊr/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assur/assure__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3265,'awl-9-01',5,'attain','đạt được; giành được','verb','[{"en":"Only a third of the students attained the required grade.","vi":"Chỉ một phần ba số sinh viên đạt được điểm yêu cầu."},{"en":"The company has attained its goal of cutting emissions by half.","vi":"Công ty đã đạt được mục tiêu cắt giảm một nửa lượng khí thải."},{"en":"Women in the region are now attaining higher levels of education.","vi":"Phụ nữ trong khu vực hiện đang đạt tới trình độ học vấn cao hơn."}]','[{"phrase":"attain a goal"},{"phrase":"attain a level"},{"phrase":"attain a standard"}]',NULL,'/əˈteɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attai/attain__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3266,'awl-9-01',6,'behalf','thay mặt; nhân danh','noun','[{"en":"She accepted the award on behalf of the whole research team.","vi":"Cô ấy thay mặt cả nhóm nghiên cứu nhận giải thưởng."},{"en":"Lawyers acting on behalf of the workers have filed a complaint.","vi":"Các luật sư đại diện cho người lao động đã nộp đơn khiếu nại."},{"en":"I would like to thank you all on behalf of the university.","vi":"Tôi xin thay mặt nhà trường cảm ơn tất cả các bạn."}]','[{"phrase":"on behalf of"},{"phrase":"act on behalf of"},{"phrase":"on somebody''s behalf"}]','Hầu như chỉ dùng trong cụm on behalf of / on somebody''s behalf','/bɪˈhæf/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/beh/behal/behalf__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3267,'awl-9-01',7,'bulk','phần lớn; khối lượng lớn','noun','[{"en":"The bulk of the funding comes from government grants.","vi":"Phần lớn kinh phí đến từ các khoản tài trợ của chính phủ."},{"en":"Students spend the bulk of their time on independent study.","vi":"Sinh viên dành phần lớn thời gian cho việc tự học."},{"en":"Restaurants usually save money by buying rice and oil in bulk.","vi":"Các nhà hàng thường tiết kiệm tiền bằng cách mua gạo và dầu với số lượng lớn."}]','[{"phrase":"the bulk of"},{"phrase":"buy in bulk"},{"phrase":"bulk purchase"}]','the bulk of + danh từ: phần lớn của…','/bʌlk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bul/bulk_/bulk__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3268,'awl-9-01',8,'cease','ngừng; chấm dứt','verb','[{"en":"The factory ceased production after the company went bankrupt.","vi":"Nhà máy ngừng sản xuất sau khi công ty phá sản."},{"en":"Fighting in the border area ceased early this morning.","vi":"Giao tranh ở khu vực biên giới đã chấm dứt vào sáng sớm nay."},{"en":"The progress of modern medicine never ceases to amaze me.","vi":"Sự tiến bộ của y học hiện đại không bao giờ thôi khiến tôi kinh ngạc."}]','[{"phrase":"cease production"},{"phrase":"cease operations"},{"phrase":"cease to exist"},{"phrase":"never cease to amaze"}]','Trang trọng hơn stop; cease to V hoặc cease + V-ing','/siːs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cea/cease/cease__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3269,'awl-9-01',9,'coherent','mạch lạc; chặt chẽ; nhất quán','adjective','[{"en":"A good essay presents a clear and coherent argument.","vi":"Một bài luận hay trình bày lập luận rõ ràng và chặt chẽ."},{"en":"The government still lacks a coherent strategy for reducing poverty.","vi":"Chính phủ vẫn thiếu một chiến lược nhất quán để giảm nghèo."},{"en":"After the accident, he was too confused to give a coherent answer.","vi":"Sau tai nạn, anh ấy quá bối rối nên không thể trả lời mạch lạc."}]','[{"phrase":"coherent argument"},{"phrase":"coherent strategy"},{"phrase":"coherent policy"},{"phrase":"coherent whole"}]',NULL,'/kəʊˈhɪrənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coh/coher/coherent__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3270,'awl-9-01',10,'coincide','xảy ra cùng lúc; trùng với; trùng khớp','verb','[{"en":"The book''s release was timed to coincide with the conference.","vi":"Việc phát hành cuốn sách được sắp xếp trùng với thời điểm diễn ra hội nghị."},{"en":"The rise in crime coincided with a sharp increase in unemployment.","vi":"Tình trạng tội phạm gia tăng xảy ra cùng lúc với tỷ lệ thất nghiệp tăng mạnh."},{"en":"Their views on the issue do not always coincide.","vi":"Quan điểm của họ về vấn đề này không phải lúc nào cũng trùng khớp."}]','[{"phrase":"coincide with"},{"phrase":"timed to coincide with"},{"phrase":"views coincide"}]','coincide with something','/ˌkəʊɪnˈsaɪd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coi/coinc/coincide__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3271,'awl-9-01',11,'commence','bắt đầu; khởi công','verb','[{"en":"Construction of the new hospital will commence next spring.","vi":"Việc xây dựng bệnh viện mới sẽ khởi công vào mùa xuân tới."},{"en":"The trial commenced two weeks after the investigation ended.","vi":"Phiên tòa bắt đầu hai tuần sau khi cuộc điều tra kết thúc."},{"en":"Students must register before classes commence in September.","vi":"Sinh viên phải đăng ký trước khi các lớp học bắt đầu vào tháng Chín."}]','[{"phrase":"commence work"},{"phrase":"commence operations"},{"phrase":"commence construction"}]','Trang trọng hơn begin / start','/kəˈmens/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comme/commence__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3272,'awl-9-01',12,'compatible','tương thích; phù hợp; hợp nhau','adjective','[{"en":"Make sure the software is compatible with your operating system.","vi":"Hãy đảm bảo phần mềm tương thích với hệ điều hành của bạn."},{"en":"Economic growth must be compatible with protecting the environment.","vi":"Tăng trưởng kinh tế phải phù hợp với việc bảo vệ môi trường."},{"en":"The two colleagues were never really compatible as a team.","vi":"Hai đồng nghiệp đó chưa bao giờ thực sự hợp nhau khi làm việc nhóm."}]','[{"phrase":"compatible with"},{"phrase":"fully compatible"},{"phrase":"compatible software"}]','compatible with; trái nghĩa: incompatible','/kəmˈpætəbl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compa/compatible__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3273,'awl-9-01',13,'concurrent','đồng thời; diễn ra cùng lúc','adjective','[{"en":"The conference offers several concurrent sessions each afternoon.","vi":"Hội nghị tổ chức nhiều phiên họp diễn ra đồng thời vào mỗi buổi chiều."},{"en":"Patients with concurrent illnesses often need more complex treatment.","vi":"Bệnh nhân mắc nhiều bệnh cùng lúc thường cần điều trị phức tạp hơn."},{"en":"The study was concurrent with a wider survey of local schools.","vi":"Nghiên cứu này diễn ra đồng thời với một khảo sát rộng hơn ở các trường địa phương."}]','[{"phrase":"concurrent sessions"},{"phrase":"concurrent with"},{"phrase":"concurrent use"}]','Trạng từ concurrently: một cách đồng thời','/kənˈkɜːrənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcurrent__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3274,'awl-9-01',14,'confine','giới hạn; hạn chế; nhốt','verb','[{"en":"Please confine your comments to the topic under discussion.","vi":"Vui lòng giới hạn ý kiến của bạn trong chủ đề đang thảo luận."},{"en":"The problem is by no means confined to large cities.","vi":"Vấn đề này hoàn toàn không chỉ giới hạn ở các thành phố lớn."},{"en":"The animals were confined in small cages for most of the day.","vi":"Những con vật bị nhốt trong các lồng nhỏ gần như cả ngày."}]','[{"phrase":"confine something to"},{"phrase":"be confined to"},{"phrase":"confined space"}]','confine something to something; be confined to','/kənˈfaɪn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfine__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3275,'awl-9-01',15,'controversy','cuộc tranh cãi; sự tranh luận','noun','[{"en":"The new tax caused a great deal of controversy among business owners.","vi":"Loại thuế mới gây ra rất nhiều tranh cãi trong giới chủ doanh nghiệp."},{"en":"There is still controversy over the safety of the drug.","vi":"Vẫn còn tranh cãi về mức độ an toàn của loại thuốc này."},{"en":"The study sparked a controversy that lasted for several years.","vi":"Nghiên cứu đó đã làm dấy lên một cuộc tranh cãi kéo dài nhiều năm."}]','[{"phrase":"cause controversy"},{"phrase":"spark controversy"},{"phrase":"controversy over"},{"phrase":"considerable controversy"}]','controversy over / about something','/ˈkɑːntrəvɜːrsi/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontroversy__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3276,'awl-9-01',16,'converse','điều ngược lại','noun','[{"en":"Wealthy people tend to live longer, but the converse is also true.","vi":"Người giàu thường sống lâu hơn, nhưng điều ngược lại cũng đúng."},{"en":"Some students work better alone; for others the converse applies.","vi":"Một số sinh viên làm việc một mình tốt hơn; với những người khác thì ngược lại."},{"en":"The data supported neither his claim nor the converse of it.","vi":"Dữ liệu không ủng hộ nhận định của ông ấy, cũng không ủng hộ điều ngược lại."}]','[{"phrase":"the converse is true"},{"phrase":"the converse applies"},{"phrase":"the converse of"}]','Thường dùng: the converse; converse (v) còn nghĩa là trò chuyện','/kənˈvɜːrs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconverse__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3277,'awl-9-01',17,'device','thiết bị; dụng cụ; biện pháp, thủ pháp','noun','[{"en":"Please switch off all electronic devices during the exam.","vi":"Vui lòng tắt tất cả thiết bị điện tử trong khi làm bài thi."},{"en":"The hospital uses a new device to monitor patients'' heart rates.","vi":"Bệnh viện sử dụng một thiết bị mới để theo dõi nhịp tim của bệnh nhân."},{"en":"Repetition is a common device in political speeches.","vi":"Sự lặp lại là một thủ pháp thường gặp trong các bài diễn văn chính trị."}]','[{"phrase":"electronic device"},{"phrase":"mobile device"},{"phrase":"medical device"},{"phrase":"literary device"}]','device (n) ≠ devise (v: nghĩ ra, sáng chế)','/dɪˈvaɪs/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devic/device__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3278,'awl-9-01',18,'devote','dành (thời gian, công sức); cống hiến','verb','[{"en":"She has devoted her career to studying climate change.","vi":"Cô ấy đã cống hiến cả sự nghiệp cho việc nghiên cứu biến đổi khí hậu."},{"en":"The report devotes an entire chapter to health care costs.","vi":"Báo cáo dành trọn một chương cho chi phí chăm sóc sức khỏe."},{"en":"Teachers should devote more time to helping weaker students.","vi":"Giáo viên nên dành nhiều thời gian hơn để giúp đỡ các học sinh yếu."}]','[{"phrase":"devote time to"},{"phrase":"devote attention to"},{"phrase":"devote resources to"},{"phrase":"devote yourself to"}]','devote something to + danh từ / V-ing','/dɪˈvəʊt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devot/devote__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3279,'awl-9-01',19,'diminish','giảm bớt; suy giảm; làm giảm','verb','[{"en":"The risk of infection diminishes as the patient''s immune system recovers.","vi":"Nguy cơ nhiễm trùng giảm dần khi hệ miễn dịch của bệnh nhân hồi phục."},{"en":"Rising prices have diminished the value of their savings.","vi":"Giá cả tăng cao đã làm giảm giá trị khoản tiết kiệm của họ."},{"en":"Public interest in the story diminished after a few weeks.","vi":"Sự quan tâm của công chúng đối với câu chuyện giảm đi sau vài tuần."}]','[{"phrase":"diminish the value"},{"phrase":"diminish over time"},{"phrase":"greatly diminish"},{"phrase":"diminishing returns"}]',NULL,'/dɪˈmɪnɪʃ/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dim/dimin/diminish__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3280,'awl-9-01',20,'distort','bóp méo; xuyên tạc; làm biến dạng','verb','[{"en":"The newspaper was accused of distorting the facts.","vi":"Tờ báo bị cáo buộc xuyên tạc sự thật."},{"en":"A few extreme values can distort the results of a small study.","vi":"Một vài giá trị cực đoan có thể làm sai lệch kết quả của một nghiên cứu nhỏ."},{"en":"Heat rising from the road distorted the image of the cars ahead.","vi":"Hơi nóng bốc lên từ mặt đường làm biến dạng hình ảnh những chiếc xe phía trước."}]','[{"phrase":"distort the truth"},{"phrase":"distort the facts"},{"phrase":"distort the results"},{"phrase":"seriously distort"}]',NULL,'/dɪˈstɔːrt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disto/distort__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3281,'awl-9-01',21,'duration','thời lượng; khoảng thời gian kéo dài','noun','[{"en":"The average duration of the treatment is six months.","vi":"Thời gian điều trị trung bình là sáu tháng."},{"en":"Phones must stay switched off for the duration of the exam.","vi":"Điện thoại phải tắt trong suốt thời gian làm bài thi."},{"en":"Researchers recorded the duration of each conversation in minutes.","vi":"Các nhà nghiên cứu ghi lại thời lượng của mỗi cuộc trò chuyện tính bằng phút."}]','[{"phrase":"for the duration of"},{"phrase":"average duration"},{"phrase":"short duration"},{"phrase":"duration of the course"}]',NULL,'/duˈreɪʃn/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dur/durat/duration__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3282,'awl-9-01',22,'erode','xói mòn; làm suy giảm dần','verb','[{"en":"Strong waves have eroded large parts of the coastline.","vi":"Những con sóng mạnh đã làm xói mòn nhiều đoạn bờ biển."},{"en":"High inflation is steadily eroding people''s purchasing power.","vi":"Lạm phát cao đang dần làm suy giảm sức mua của người dân."},{"en":"Repeated scandals have eroded public trust in the banking system.","vi":"Những vụ bê bối liên tiếp đã làm xói mòn lòng tin của công chúng vào hệ thống ngân hàng."}]','[{"phrase":"erode confidence"},{"phrase":"erode trust"},{"phrase":"gradually erode"},{"phrase":"erode the coastline"}]',NULL,'/ɪˈrəʊd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ero/erode/erode__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3283,'awl-9-01',23,'ethic','đạo đức; nguyên tắc đạo đức','noun','[{"en":"Employers value graduates with a strong work ethic.","vi":"Nhà tuyển dụng đánh giá cao những sinh viên tốt nghiệp có tinh thần làm việc nghiêm túc."},{"en":"All researchers here must follow a strict code of ethics.","vi":"Tất cả các nhà nghiên cứu ở đây phải tuân theo một bộ quy tắc đạo đức nghiêm ngặt."},{"en":"The course examines the ethics of using animals in medical research.","vi":"Khóa học xem xét vấn đề đạo đức của việc dùng động vật trong nghiên cứu y học."}]','[{"phrase":"work ethic"},{"phrase":"code of ethics"},{"phrase":"professional ethics"},{"phrase":"medical ethics"}]','Thường dùng số nhiều: ethics (đạo đức học; quy tắc đạo đức)','/ˈeθɪk/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eth/ethic/ethic__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3284,'awl-9-01',24,'format','định dạng; hình thức trình bày','noun','[{"en":"Please submit your assignment in PDF format.","vi":"Vui lòng nộp bài tập ở định dạng PDF."},{"en":"The exam will follow the same format as last year.","vi":"Bài thi sẽ theo hình thức giống như năm ngoái."},{"en":"Many journals now publish articles in both print and digital formats.","vi":"Nhiều tạp chí hiện nay xuất bản bài báo ở cả dạng in và dạng số."}]','[{"phrase":"file format"},{"phrase":"digital format"},{"phrase":"in a format"},{"phrase":"change the format"}]',NULL,'/ˈfɔːrmæt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/forma/format__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3285,'awl-9-01',25,'found','thành lập; sáng lập; dựa trên','verb','[{"en":"The university was founded in 1850 by a group of doctors.","vi":"Trường đại học được một nhóm bác sĩ thành lập vào năm 1850."},{"en":"She left her job to found a small software company.","vi":"Cô ấy nghỉ việc để sáng lập một công ty phần mềm nhỏ."},{"en":"Their theory is founded on decades of careful observation.","vi":"Lý thuyết của họ dựa trên hàng chục năm quan sát cẩn thận."}]','[{"phrase":"found a company"},{"phrase":"founded in"},{"phrase":"be founded on"},{"phrase":"newly founded"}]','found – founded – founded (khác find – found – found)','/faʊnd/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fou/found/found__us_2.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3286,'awl-9-01',26,'inherent','vốn có; cố hữu; bẩm sinh','adjective','[{"en":"Every investment in the stock market carries some inherent risk.","vi":"Mọi khoản đầu tư vào thị trường chứng khoán đều mang rủi ro vốn có."},{"en":"The study discusses problems inherent in using online surveys.","vi":"Nghiên cứu bàn về những vấn đề cố hữu khi sử dụng khảo sát trực tuyến."},{"en":"Some psychologists argue that the ability to learn language is inherent.","vi":"Một số nhà tâm lý học cho rằng khả năng học ngôn ngữ là bẩm sinh."}]','[{"phrase":"inherent risk"},{"phrase":"inherent in"},{"phrase":"inherent weakness"},{"phrase":"inherent problem"}]','inherent in something','/ɪnˈherənt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inh/inher/inherent__us_2_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3287,'awl-9-01',27,'insight','sự hiểu biết sâu sắc; cái nhìn sâu sắc','noun','[{"en":"The interviews gave us valuable insight into how customers make decisions.","vi":"Các cuộc phỏng vấn cho chúng tôi hiểu biết sâu sắc về cách khách hàng ra quyết định."},{"en":"Her book offers new insights into the causes of poverty.","vi":"Cuốn sách của cô ấy đưa ra những góc nhìn sâu sắc mới về nguyên nhân của nghèo đói."},{"en":"Working abroad gave him real insight into other cultures.","vi":"Làm việc ở nước ngoài giúp anh ấy thực sự hiểu sâu về các nền văn hóa khác."}]','[{"phrase":"insight into"},{"phrase":"gain insight"},{"phrase":"provide insight"},{"phrase":"valuable insight"}]','insight into something','/ˈɪnsaɪt/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insig/insight__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3288,'awl-9-01',28,'integral','không thể thiếu; thiết yếu; gắn liền','adjective','[{"en":"Practical training is an integral part of the nursing course.","vi":"Thực hành là một phần không thể thiếu của khóa học điều dưỡng."},{"en":"Local farmers played an integral role in the success of the project.","vi":"Nông dân địa phương đóng vai trò thiết yếu trong thành công của dự án."},{"en":"Music has always been integral to the country''s culture.","vi":"Âm nhạc luôn gắn liền với văn hóa của đất nước này."}]','[{"phrase":"integral part"},{"phrase":"integral role"},{"phrase":"integral to"},{"phrase":"integral component"}]','integral to something','/ˈɪntɪɡrəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/integ/integral__us_1_rr.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3289,'awl-9-01',29,'intermediate','trung cấp; trung gian','adjective','[{"en":"This course is designed for students at an intermediate level.","vi":"Khóa học này được thiết kế cho học viên ở trình độ trung cấp."},{"en":"The chemical passes through several intermediate stages before it becomes stable.","vi":"Hóa chất này trải qua nhiều giai đoạn trung gian trước khi trở nên ổn định."},{"en":"Many small factories produce intermediate goods for larger manufacturers.","vi":"Nhiều nhà máy nhỏ sản xuất hàng hóa trung gian cho các nhà sản xuất lớn hơn."}]','[{"phrase":"intermediate level"},{"phrase":"intermediate stage"},{"phrase":"intermediate goods"}]',NULL,'/ˌɪntərˈmiːdiət/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/intermediate__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3290,'awl-9-01',30,'manual','sách hướng dẫn; sổ tay hướng dẫn','noun','[{"en":"Read the user manual carefully before using the new equipment.","vi":"Hãy đọc kỹ sách hướng dẫn sử dụng trước khi dùng thiết bị mới."},{"en":"The company gives every new employee a training manual.","vi":"Công ty phát cho mỗi nhân viên mới một cuốn sổ tay hướng dẫn đào tạo."},{"en":"The manual explains step by step how to install the software.","vi":"Sách hướng dẫn giải thích từng bước cách cài đặt phần mềm."}]','[{"phrase":"user manual"},{"phrase":"training manual"},{"phrase":"instruction manual"},{"phrase":"consult the manual"}]','manual (adj): thủ công, chân tay — manual labour','/ˈmænjuəl/','https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manua/manual__us_1.mp3',NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3291,'colloc-1-01',1,'abstract concept','khái niệm trừu tượng','adj + n','[{"en":"Students often struggle to grasp an abstract concept without concrete examples.","vi":"Sinh viên thường khó nắm bắt một khái niệm trừu tượng nếu thiếu ví dụ cụ thể."},{"en":"The lecturer explained the abstract concept using a simple diagram.","vi":"Giảng viên giải thích khái niệm trừu tượng bằng một sơ đồ đơn giản."},{"en":"Philosophy deals with abstract concepts such as justice and freedom.","vi":"Triết học bàn về những khái niệm trừu tượng như công lý và tự do."}]','[]',NULL,'/ˈæbstrækt ˈkɑːnsept/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3292,'colloc-1-01',2,'academic achievement','thành tích học tập','adj + n','[{"en":"Her academic achievement earned her a full scholarship abroad.","vi":"Thành tích học tập của cô ấy giúp giành được học bổng toàn phần ở nước ngoài."},{"en":"The school celebrates academic achievement at an annual ceremony.","vi":"Nhà trường vinh danh thành tích học tập trong lễ trao thưởng thường niên."},{"en":"Parental support strongly influences a child''s academic achievement.","vi":"Sự hỗ trợ của cha mẹ ảnh hưởng mạnh đến thành tích học tập của trẻ."}]','[]',NULL,'/ˌækəˈdemɪk əˈtʃiːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3293,'colloc-1-01',3,'academic career','sự nghiệp học thuật','adj + n','[{"en":"He devoted his entire academic career to medieval history.","vi":"Ông dành trọn sự nghiệp học thuật cho lịch sử trung cổ."},{"en":"Publishing papers is essential for a successful academic career.","vi":"Công bố bài báo là điều thiết yếu cho một sự nghiệp học thuật thành công."},{"en":"She began her academic career as a junior lecturer.","vi":"Cô bắt đầu sự nghiệp học thuật với vị trí giảng viên tập sự."}]','[]',NULL,'/ˌækəˈdemɪk kəˈrɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3294,'colloc-1-01',4,'academic circles','giới học thuật','adj + n','[{"en":"His theory is widely respected in academic circles.","vi":"Lý thuyết của ông được giới học thuật rất kính trọng."},{"en":"The discovery sparked heated debate in academic circles.","vi":"Phát hiện này làm dấy lên tranh luận sôi nổi trong giới học thuật."},{"en":"Such ideas rarely reach beyond academic circles.","vi":"Những ý tưởng như vậy hiếm khi vượt ra ngoài giới học thuật."}]','[]',NULL,'/ˌækəˈdemɪk ˈsɜːrkəlz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3295,'colloc-1-01',5,'academic community','cộng đồng học thuật','adj + n','[{"en":"The academic community welcomed the new research findings.","vi":"Cộng đồng học thuật hoan nghênh các phát hiện nghiên cứu mới."},{"en":"Online journals connect the global academic community.","vi":"Các tạp chí trực tuyến kết nối cộng đồng học thuật toàn cầu."},{"en":"Plagiarism damages trust within the academic community.","vi":"Đạo văn làm tổn hại lòng tin trong cộng đồng học thuật."}]','[]',NULL,'/ˌækəˈdemɪk kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3296,'colloc-1-01',6,'academic debate','tranh luận học thuật','adj + n','[{"en":"The topic remains the subject of intense academic debate.","vi":"Chủ đề này vẫn là tâm điểm của những tranh luận học thuật gay gắt."},{"en":"Her paper contributed fresh ideas to the academic debate.","vi":"Bài viết của cô đóng góp những ý tưởng mới cho cuộc tranh luận học thuật."},{"en":"Academic debate helps refine competing theories.","vi":"Tranh luận học thuật giúp hoàn thiện các lý thuyết đối lập."}]','[]',NULL,'/ˌækəˈdemɪk dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3297,'colloc-1-01',7,'academic discipline','ngành học, bộ môn học thuật','adj + n','[{"en":"Economics is a well-established academic discipline.","vi":"Kinh tế học là một ngành học đã được khẳng định."},{"en":"Each academic discipline has its own research methods.","vi":"Mỗi ngành học có phương pháp nghiên cứu riêng."},{"en":"The course draws on several academic disciplines.","vi":"Khóa học vận dụng kiến thức từ nhiều ngành học khác nhau."}]','[]',NULL,'/ˌækəˈdemɪk ˈdɪsəplɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3298,'colloc-1-01',8,'academic discourse','diễn ngôn học thuật','adj + n','[{"en":"Academic discourse requires precise and formal language.","vi":"Diễn ngôn học thuật đòi hỏi ngôn ngữ chính xác và trang trọng."},{"en":"Students must learn the conventions of academic discourse.","vi":"Sinh viên phải nắm các quy ước của diễn ngôn học thuật."},{"en":"Citations are a key feature of academic discourse.","vi":"Trích dẫn là một đặc trưng quan trọng của diễn ngôn học thuật."}]','[]',NULL,'/ˌækəˈdemɪk ˈdɪskɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3299,'colloc-1-01',9,'academic institution','cơ sở, tổ chức học thuật','adj + n','[{"en":"The university is a leading academic institution in the region.","vi":"Trường đại học này là một cơ sở học thuật hàng đầu trong khu vực."},{"en":"Academic institutions rely on funding for research.","vi":"Các cơ sở học thuật dựa vào nguồn tài trợ để nghiên cứu."},{"en":"She works at a prestigious academic institution.","vi":"Cô làm việc tại một tổ chức học thuật danh tiếng."}]','[]',NULL,'/ˌækəˈdemɪk ˌɪnstɪˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3300,'colloc-1-01',10,'academic journal','tạp chí học thuật','adj + n','[{"en":"Her study appeared in a respected academic journal.","vi":"Nghiên cứu của cô được đăng trên một tạp chí học thuật uy tín."},{"en":"Peer review ensures the quality of academic journals.","vi":"Bình duyệt đảm bảo chất lượng của các tạp chí học thuật."},{"en":"Access to academic journals is often expensive.","vi":"Việc truy cập các tạp chí học thuật thường tốn kém."}]','[]',NULL,'/ˌækəˈdemɪk ˈdʒɜːrnəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3301,'colloc-1-01',11,'academic life','đời sống học thuật','adj + n','[{"en":"Academic life involves both teaching and research.","vi":"Đời sống học thuật bao gồm cả giảng dạy lẫn nghiên cứu."},{"en":"He enjoys the intellectual freedom of academic life.","vi":"Ông tận hưởng sự tự do trí tuệ của đời sống học thuật."},{"en":"Balancing academic life and family can be difficult.","vi":"Cân bằng giữa đời sống học thuật và gia đình có thể rất khó."}]','[]',NULL,'/ˌækəˈdemɪk laɪf/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3302,'colloc-1-01',12,'academic performance','kết quả, thành tích học tập','adj + n','[{"en":"Lack of sleep can harm a student''s academic performance.","vi":"Thiếu ngủ có thể ảnh hưởng xấu đến kết quả học tập của sinh viên."},{"en":"The program aims to improve academic performance.","vi":"Chương trình nhằm cải thiện thành tích học tập."},{"en":"Teachers monitor academic performance throughout the year.","vi":"Giáo viên theo dõi kết quả học tập suốt cả năm."}]','[]',NULL,'/ˌækəˈdemɪk pərˈfɔːrməns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3303,'colloc-1-01',13,'academic research','nghiên cứu học thuật','adj + n','[{"en":"Academic research often takes years to complete.","vi":"Nghiên cứu học thuật thường mất nhiều năm để hoàn thành."},{"en":"The grant will fund academic research on climate change.","vi":"Khoản tài trợ sẽ cấp kinh phí cho nghiên cứu học thuật về biến đổi khí hậu."},{"en":"Academic research must follow strict ethical guidelines.","vi":"Nghiên cứu học thuật phải tuân theo các nguyên tắc đạo đức nghiêm ngặt."}]','[]',NULL,'/ˌækəˈdemɪk ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3304,'colloc-1-01',14,'academic skills','kỹ năng học thuật','adj + n','[{"en":"The workshop helps students develop essential academic skills.","vi":"Buổi tập huấn giúp sinh viên phát triển các kỹ năng học thuật thiết yếu."},{"en":"Note-taking is an important academic skill.","vi":"Ghi chép là một kỹ năng học thuật quan trọng."},{"en":"Strong academic skills improve exam results.","vi":"Kỹ năng học thuật vững vàng giúp cải thiện kết quả thi."}]','[]',NULL,'/ˌækəˈdemɪk skɪlz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3305,'colloc-1-01',15,'academic study','việc học, nghiên cứu học thuật','adj + n','[{"en":"Years of academic study prepared her for the role.","vi":"Nhiều năm học tập học thuật đã chuẩn bị cho cô đảm nhận vị trí này."},{"en":"The library is a quiet place for academic study.","vi":"Thư viện là nơi yên tĩnh để học tập."},{"en":"Academic study requires discipline and patience.","vi":"Việc học học thuật đòi hỏi tính kỷ luật và kiên nhẫn."}]','[]',NULL,'/ˌækəˈdemɪk ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3306,'colloc-1-01',16,'academic success','thành công trong học tập','adj + n','[{"en":"Motivation is a key factor in academic success.","vi":"Động lực là yếu tố then chốt cho thành công trong học tập."},{"en":"The school credits its methods for students'' academic success.","vi":"Nhà trường cho rằng phương pháp của mình tạo nên thành công học tập của học sinh."},{"en":"Academic success often opens career opportunities.","vi":"Thành công trong học tập thường mở ra cơ hội nghề nghiệp."}]','[]',NULL,'/ˌækəˈdemɪk səkˈses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3307,'colloc-1-01',17,'academic work','công việc, bài vở học thuật','adj + n','[{"en":"She submitted her academic work before the deadline.","vi":"Cô nộp bài vở học thuật trước hạn chót."},{"en":"His academic work has been cited many times.","vi":"Công trình học thuật của ông được trích dẫn nhiều lần."},{"en":"Good time management improves academic work.","vi":"Quản lý thời gian tốt giúp nâng cao chất lượng bài vở học thuật."}]','[]',NULL,'/ˌækəˈdemɪk wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3308,'colloc-1-01',18,'academic world','thế giới, giới học thuật','adj + n','[{"en":"The academic world can be highly competitive.","vi":"Giới học thuật có thể rất cạnh tranh."},{"en":"Her ideas made an impact on the academic world.","vi":"Những ý tưởng của cô tạo dấu ấn trong giới học thuật."},{"en":"He felt at home in the academic world.","vi":"Ông cảm thấy thoải mái trong thế giới học thuật."}]','[]',NULL,'/ˌækəˈdemɪk wɜːrld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3309,'colloc-1-01',19,'academic writing','viết học thuật','adj + n','[{"en":"Academic writing should be clear and well-structured.","vi":"Văn viết học thuật cần rõ ràng và có cấu trúc chặt chẽ."},{"en":"Students take a course in academic writing.","vi":"Sinh viên tham gia một khóa học về viết học thuật."},{"en":"Academic writing avoids slang and contractions.","vi":"Văn viết học thuật tránh tiếng lóng và dạng viết tắt."}]','[]',NULL,'/ˌækəˈdemɪk ˈraɪtɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3310,'colloc-1-01',20,'academic year','năm học','adj + n','[{"en":"The academic year begins in early September.","vi":"Năm học bắt đầu vào đầu tháng Chín."},{"en":"Exams are held at the end of the academic year.","vi":"Các kỳ thi diễn ra vào cuối năm học."},{"en":"She studied abroad for one academic year.","vi":"Cô đi du học trong một năm học."}]','[]',NULL,'/ˌækəˈdemɪk jɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3311,'colloc-1-01',21,'accept responsibility','nhận trách nhiệm','v + n','[{"en":"The manager agreed to accept responsibility for the error.","vi":"Người quản lý đồng ý nhận trách nhiệm về sai sót này."},{"en":"Leaders must accept responsibility for their decisions.","vi":"Người lãnh đạo phải nhận trách nhiệm cho các quyết định của mình."},{"en":"She refused to accept responsibility for the delay.","vi":"Cô từ chối nhận trách nhiệm về sự chậm trễ."}]','[]',NULL,'/əkˈsept rɪˌspɑːnsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3312,'colloc-1-01',22,'acceptable behavior','hành vi chấp nhận được','adj + n','[{"en":"The school sets clear rules for acceptable behavior.","vi":"Nhà trường đặt ra quy định rõ ràng về hành vi chấp nhận được."},{"en":"Honesty is considered acceptable behavior in any workplace.","vi":"Trung thực được xem là hành vi chấp nhận được ở mọi nơi làm việc."},{"en":"What counts as acceptable behavior varies between cultures.","vi":"Hành vi được coi là chấp nhận được khác nhau giữa các nền văn hóa."}]','[]',NULL,'/əkˈseptəbəl bɪˈheɪvjər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3313,'colloc-1-01',23,'accurate assessment','đánh giá chính xác','adj + n','[{"en":"Teachers need data for an accurate assessment of progress.","vi":"Giáo viên cần dữ liệu để đánh giá chính xác sự tiến bộ."},{"en":"An accurate assessment of risk is vital for planning.","vi":"Đánh giá rủi ro chính xác là rất quan trọng cho việc lập kế hoạch."},{"en":"The report gives an accurate assessment of the situation.","vi":"Báo cáo đưa ra một đánh giá chính xác về tình hình."}]','[]',NULL,'/ˈækjərət əˈsesmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3314,'colloc-1-01',24,'accurate description','mô tả chính xác','adj + n','[{"en":"The witness gave an accurate description of the event.","vi":"Nhân chứng đưa ra một mô tả chính xác về sự việc."},{"en":"An accurate description helps readers picture the scene.","vi":"Mô tả chính xác giúp người đọc hình dung khung cảnh."},{"en":"Scientists aim for an accurate description of nature.","vi":"Các nhà khoa học hướng tới việc mô tả chính xác tự nhiên."}]','[]',NULL,'/ˈækjərət dɪˈskrɪpʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3315,'colloc-1-01',25,'accurate information','thông tin chính xác','adj + n','[{"en":"Decisions should be based on accurate information.","vi":"Các quyết định nên dựa trên thông tin chính xác."},{"en":"The website provides accurate information about the course.","vi":"Trang web cung cấp thông tin chính xác về khóa học."},{"en":"Spreading accurate information reduces public confusion.","vi":"Lan truyền thông tin chính xác giúp giảm bối rối trong công chúng."}]','[]',NULL,'/ˈækjərət ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3316,'colloc-1-01',26,'accurate measurement','phép đo chính xác','adj + n','[{"en":"Accurate measurement is essential in scientific experiments.","vi":"Phép đo chính xác là thiết yếu trong các thí nghiệm khoa học."},{"en":"The tool allows accurate measurement of temperature.","vi":"Thiết bị cho phép đo nhiệt độ một cách chính xác."},{"en":"Small errors prevent accurate measurement of distance.","vi":"Những sai số nhỏ khiến việc đo khoảng cách thiếu chính xác."}]','[]',NULL,'/ˈækjərət ˈmeʒərmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3317,'colloc-1-01',27,'accurate picture','bức tranh, hình dung chính xác','adj + n','[{"en":"The survey gives an accurate picture of public opinion.","vi":"Cuộc khảo sát cho thấy một bức tranh chính xác về dư luận."},{"en":"These figures paint an accurate picture of the economy.","vi":"Những số liệu này phác họa một bức tranh chính xác về nền kinh tế."},{"en":"We need more data for an accurate picture.","vi":"Chúng ta cần thêm dữ liệu để có hình dung chính xác."}]','[]',NULL,'/ˈækjərət ˈpɪktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3318,'colloc-1-01',28,'accurate record','hồ sơ, bản ghi chính xác','adj + n','[{"en":"The clinic keeps an accurate record of every patient.","vi":"Phòng khám lưu giữ hồ sơ chính xác của từng bệnh nhân."},{"en":"Accurate records help track spending over time.","vi":"Hồ sơ chính xác giúp theo dõi chi tiêu theo thời gian."},{"en":"Historians rely on accurate records of past events.","vi":"Các nhà sử học dựa vào những bản ghi chính xác về sự kiện quá khứ."}]','[]',NULL,'/ˈækjərət ˈrekərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3319,'colloc-1-01',29,'achieve a goal','đạt được mục tiêu','v + n','[{"en":"Hard work helped her achieve her goal of graduating early.","vi":"Sự chăm chỉ giúp cô đạt được mục tiêu tốt nghiệp sớm."},{"en":"The team worked together to achieve a common goal.","vi":"Cả nhóm cùng nhau làm việc để đạt được một mục tiêu chung."},{"en":"Setting small steps makes it easier to achieve a goal.","vi":"Chia thành các bước nhỏ giúp đạt được mục tiêu dễ hơn."}]','[]',NULL,'/əˈtʃiːv ə ɡoʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3320,'colloc-1-01',30,'achieve an objective','đạt được mục tiêu (cụ thể)','v + n','[{"en":"The project must achieve its objective within budget.","vi":"Dự án phải đạt được mục tiêu trong khuôn khổ ngân sách."},{"en":"Clear planning helps a company achieve its objective.","vi":"Lập kế hoạch rõ ràng giúp công ty đạt được mục tiêu."},{"en":"They failed to achieve the objective on time.","vi":"Họ không đạt được mục tiêu đúng hạn."}]','[]',NULL,'/əˈtʃiːv ən əbˈdʒektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3321,'colloc-1-01',31,'achieve an outcome','đạt được kết quả','v + n','[{"en":"The new method helped achieve a better outcome.","vi":"Phương pháp mới giúp đạt được kết quả tốt hơn."},{"en":"Careful treatment can achieve a positive outcome.","vi":"Điều trị cẩn thận có thể đạt được kết quả tích cực."},{"en":"Both sides worked to achieve a fair outcome.","vi":"Cả hai bên nỗ lực để đạt được một kết quả công bằng."}]','[]',NULL,'/əˈtʃiːv ən ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3322,'colloc-1-01',32,'acquire knowledge','thu nhận, tích lũy kiến thức','v + n','[{"en":"Students acquire knowledge through reading and practice.","vi":"Sinh viên thu nhận kiến thức qua việc đọc và thực hành."},{"en":"Travel helps people acquire knowledge of other cultures.","vi":"Du lịch giúp con người thu nhận kiến thức về các nền văn hóa khác."},{"en":"We acquire knowledge gradually over many years.","vi":"Chúng ta tích lũy kiến thức dần dần qua nhiều năm."}]','[]',NULL,'/əˈkwaɪər ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3323,'colloc-1-01',33,'active involvement','sự tham gia tích cực','adj + n','[{"en":"Her active involvement in the project improved its outcome.","vi":"Sự tham gia tích cực của cô vào dự án đã cải thiện kết quả."},{"en":"The course rewards active involvement in class discussions.","vi":"Khóa học khuyến khích sự tham gia tích cực vào các buổi thảo luận trên lớp."},{"en":"Active involvement from parents supports student learning.","vi":"Sự tham gia tích cực của phụ huynh hỗ trợ việc học của học sinh."}]','[]',NULL,'/ˈæktɪv ɪnˈvɑːlvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3324,'colloc-1-01',34,'active participant','người tham gia tích cực','adj + n','[{"en":"She was an active participant in the debate.","vi":"Cô là một người tham gia tích cực trong cuộc tranh luận."},{"en":"Every active participant received a certificate.","vi":"Mỗi người tham gia tích cực đều nhận được giấy chứng nhận."},{"en":"He became an active participant in community projects.","vi":"Anh trở thành người tham gia tích cực trong các dự án cộng đồng."}]','[]',NULL,'/ˈæktɪv pɑːrˈtɪsəpənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3325,'colloc-1-01',35,'active participation','sự tham gia tích cực','adj + n','[{"en":"The class encourages active participation from everyone.","vi":"Lớp học khuyến khích sự tham gia tích cực từ mọi người."},{"en":"Active participation improves language learning.","vi":"Sự tham gia tích cực giúp cải thiện việc học ngôn ngữ."},{"en":"Grades partly depend on active participation.","vi":"Điểm số một phần phụ thuộc vào sự tham gia tích cực."}]','[]',NULL,'/ˈæktɪv pɑːrˌtɪsəˈpeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3326,'colloc-1-01',36,'active role','vai trò tích cực, chủ động','adj + n','[{"en":"Teachers play an active role in students'' development.","vi":"Giáo viên giữ vai trò tích cực trong sự phát triển của học sinh."},{"en":"She took an active role in organizing the event.","vi":"Cô đảm nhận vai trò chủ động trong việc tổ chức sự kiện."},{"en":"Citizens can play an active role in local politics.","vi":"Người dân có thể đóng vai trò tích cực trong chính trị địa phương."}]','[]',NULL,'/ˈæktɪv roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3327,'colloc-1-01',37,'actively involved','tham gia tích cực, chủ động','adv + vpp','[{"en":"Parents who are actively involved help their children succeed.","vi":"Phụ huynh tham gia tích cực sẽ giúp con cái thành công."},{"en":"She is actively involved in several research projects.","vi":"Cô tham gia tích cực vào nhiều dự án nghiên cứu."},{"en":"Students should be actively involved in their own learning.","vi":"Học sinh nên chủ động tham gia vào việc học của chính mình."}]','[]',NULL,'/ˈæktɪvli ɪnˈvɑːlvd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3328,'colloc-1-01',38,'acutely aware','ý thức rõ rệt, sâu sắc','adv + adj','[{"en":"She is acutely aware of the risks involved.","vi":"Cô ý thức rõ rệt về những rủi ro liên quan."},{"en":"The company is acutely aware of customer needs.","vi":"Công ty nhận thức sâu sắc về nhu cầu của khách hàng."},{"en":"He became acutely aware of his own mistakes.","vi":"Anh trở nên ý thức sâu sắc về những lỗi của bản thân."}]','[]',NULL,'/əˈkjuːtli əˈwer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3329,'colloc-1-01',39,'add information','bổ sung thông tin','v + n','[{"en":"Please add information about your previous experience.","vi":"Vui lòng bổ sung thông tin về kinh nghiệm trước đây của bạn."},{"en":"The editor asked her to add information to the report.","vi":"Biên tập viên yêu cầu cô bổ sung thông tin vào báo cáo."},{"en":"You can add information to the form at any time.","vi":"Bạn có thể bổ sung thông tin vào biểu mẫu bất cứ lúc nào."}]','[]',NULL,'/æd ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3330,'colloc-1-01',40,'additional cost','chi phí phát sinh, chi phí thêm','adj + n','[{"en":"Shipping may involve an additional cost.","vi":"Việc vận chuyển có thể phát sinh thêm chi phí."},{"en":"There is no additional cost for this service.","vi":"Dịch vụ này không có chi phí phát sinh."},{"en":"The repair came at a significant additional cost.","vi":"Việc sửa chữa tốn một khoản chi phí phát sinh đáng kể."}]','[]',NULL,'/əˈdɪʃənəl kɔːst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3331,'colloc-1-01',41,'additional information','thông tin bổ sung','adj + n','[{"en":"Please contact us for additional information.","vi":"Vui lòng liên hệ với chúng tôi để biết thêm thông tin."},{"en":"The appendix provides additional information on the method.","vi":"Phần phụ lục cung cấp thông tin bổ sung về phương pháp."},{"en":"She requested additional information before deciding.","vi":"Cô yêu cầu thông tin bổ sung trước khi quyết định."}]','[]',NULL,'/əˈdɪʃənəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3332,'colloc-1-01',42,'additional problem','vấn đề phát sinh thêm','adj + n','[{"en":"The delay created an additional problem for the team.","vi":"Sự chậm trễ tạo ra một vấn đề phát sinh thêm cho nhóm."},{"en":"Bad weather added an additional problem to the trip.","vi":"Thời tiết xấu làm phát sinh thêm một vấn đề cho chuyến đi."},{"en":"We solved one issue but faced an additional problem.","vi":"Chúng tôi giải quyết được một việc nhưng lại gặp thêm một vấn đề."}]','[]',NULL,'/əˈdɪʃənəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3333,'colloc-1-01',43,'additional resources','nguồn lực bổ sung, tài nguyên thêm','adj + n','[{"en":"The school requested additional resources for the lab.","vi":"Nhà trường đề nghị cấp thêm nguồn lực cho phòng thí nghiệm."},{"en":"Additional resources are needed to finish the project.","vi":"Cần thêm nguồn lực để hoàn thành dự án."},{"en":"Teachers shared additional resources with the students.","vi":"Giáo viên chia sẻ thêm tài nguyên cho học sinh."}]','[]',NULL,'/əˈdɪʃənəl ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3334,'colloc-1-01',44,'additional support','hỗ trợ thêm','adj + n','[{"en":"Struggling students receive additional support after class.","vi":"Học sinh gặp khó khăn được hỗ trợ thêm sau giờ học."},{"en":"The government promised additional support for farmers.","vi":"Chính phủ cam kết hỗ trợ thêm cho nông dân."},{"en":"She needed additional support to meet the deadline.","vi":"Cô cần được hỗ trợ thêm để kịp hạn chót."}]','[]',NULL,'/əˈdɪʃənəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3335,'colloc-1-01',45,'address an issue','giải quyết vấn đề','v + n','[{"en":"The meeting was held to address the issue of safety.","vi":"Cuộc họp được tổ chức để giải quyết vấn đề an toàn."},{"en":"We must address this issue before it gets worse.","vi":"Chúng ta phải giải quyết vấn đề này trước khi nó tệ hơn."},{"en":"The policy fails to address the real issue.","vi":"Chính sách này không giải quyết được vấn đề cốt lõi."}]','[]',NULL,'/əˈdres ən ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3336,'colloc-1-01',46,'administrative practices','thông lệ, quy trình hành chính','adj + n','[{"en":"The company reviewed its administrative practices.","vi":"Công ty rà soát lại các quy trình hành chính của mình."},{"en":"Poor administrative practices slowed the whole process.","vi":"Quy trình hành chính kém làm chậm toàn bộ tiến trình."},{"en":"New software improved their administrative practices.","vi":"Phần mềm mới cải thiện các thông lệ hành chính của họ."}]','[]',NULL,'/ədˈmɪnəstreɪtɪv ˈpræktɪsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3337,'colloc-1-01',47,'adopt a procedure','áp dụng quy trình','v + n','[{"en":"The hospital decided to adopt a new procedure.","vi":"Bệnh viện quyết định áp dụng một quy trình mới."},{"en":"Staff were trained to adopt the safety procedure.","vi":"Nhân viên được đào tạo để áp dụng quy trình an toàn."},{"en":"Many firms adopt the same procedure for hiring.","vi":"Nhiều công ty áp dụng cùng một quy trình tuyển dụng."}]','[]',NULL,'/əˈdɑːpt ə prəˈsiːdʒər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3338,'colloc-1-01',48,'adopt an approach','áp dụng cách tiếp cận','v + n','[{"en":"Researchers decided to adopt a different approach.","vi":"Các nhà nghiên cứu quyết định áp dụng một cách tiếp cận khác."},{"en":"The teacher adopts a flexible approach to learning.","vi":"Giáo viên áp dụng một cách tiếp cận linh hoạt cho việc học."},{"en":"We should adopt a more practical approach.","vi":"Chúng ta nên áp dụng một cách tiếp cận thực tế hơn."}]','[]',NULL,'/əˈdɑːpt ən əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3339,'colloc-1-01',49,'advanced economy','nền kinh tế phát triển','adj + n','[{"en":"Japan is often cited as an advanced economy.","vi":"Nhật Bản thường được xem là một nền kinh tế phát triển."},{"en":"An advanced economy depends on skilled workers.","vi":"Một nền kinh tế phát triển phụ thuộc vào lao động lành nghề."},{"en":"Advanced economies invest heavily in technology.","vi":"Các nền kinh tế phát triển đầu tư mạnh vào công nghệ."}]','[]',NULL,'/ədˈvænst ɪˈkɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3340,'colloc-1-01',50,'advanced technology','công nghệ tiên tiến','adj + n','[{"en":"The factory uses advanced technology to cut waste.","vi":"Nhà máy sử dụng công nghệ tiên tiến để giảm lãng phí."},{"en":"Advanced technology has transformed modern medicine.","vi":"Công nghệ tiên tiến đã thay đổi nền y học hiện đại."},{"en":"The country exports advanced technology worldwide.","vi":"Quốc gia này xuất khẩu công nghệ tiên tiến ra toàn thế giới."}]','[]',NULL,'/ədˈvænst tekˈnɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3341,'colloc-1-01',51,'adverse effect','tác động bất lợi','adj + n','[{"en":"The drug may have an adverse effect on the liver.","vi":"Loại thuốc này có thể gây tác động bất lợi lên gan."},{"en":"Pollution has an adverse effect on public health.","vi":"Ô nhiễm gây tác động bất lợi đến sức khỏe cộng đồng."},{"en":"Stress can have an adverse effect on sleep.","vi":"Căng thẳng có thể gây tác động bất lợi đến giấc ngủ."}]','[]',NULL,'/ædˈvɜːrs ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3342,'colloc-1-01',52,'adverse reaction','phản ứng bất lợi','adj + n','[{"en":"Some patients had an adverse reaction to the vaccine.","vi":"Một số bệnh nhân có phản ứng bất lợi với vắc-xin."},{"en":"Report any adverse reaction to your doctor immediately.","vi":"Hãy báo ngay cho bác sĩ về bất kỳ phản ứng bất lợi nào."},{"en":"The new policy provoked an adverse reaction from staff.","vi":"Chính sách mới gây ra phản ứng bất lợi từ nhân viên."}]','[]',NULL,'/ædˈvɜːrs riˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3343,'colloc-1-01',53,'adversely affect','ảnh hưởng xấu, ảnh hưởng bất lợi','adv + v','[{"en":"Noise can adversely affect concentration.","vi":"Tiếng ồn có thể ảnh hưởng xấu đến sự tập trung."},{"en":"The drought adversely affected this year''s harvest.","vi":"Hạn hán ảnh hưởng bất lợi đến vụ mùa năm nay."},{"en":"High fees may adversely affect enrollment.","vi":"Học phí cao có thể ảnh hưởng xấu đến số lượng nhập học."}]','[]',NULL,'/ædˈvɜːrsli əˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3344,'colloc-1-01',54,'affect the outcome','ảnh hưởng đến kết quả','v + n','[{"en":"Many factors can affect the outcome of the experiment.","vi":"Nhiều yếu tố có thể ảnh hưởng đến kết quả của thí nghiệm."},{"en":"Weather may affect the outcome of the match.","vi":"Thời tiết có thể ảnh hưởng đến kết quả trận đấu."},{"en":"Bias can seriously affect the outcome of a study.","vi":"Sự thiên lệch có thể ảnh hưởng nghiêm trọng đến kết quả nghiên cứu."}]','[]',NULL,'/əˈfekt ði ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3345,'colloc-1-01',55,'affect the development of','ảnh hưởng đến sự phát triển','v + n','[{"en":"Early nutrition can affect a child''s development.","vi":"Dinh dưỡng sớm có thể ảnh hưởng đến sự phát triển của trẻ."},{"en":"Government policy may affect economic development.","vi":"Chính sách của chính phủ có thể ảnh hưởng đến sự phát triển kinh tế."},{"en":"Stress can affect the development of the brain.","vi":"Căng thẳng có thể ảnh hưởng đến sự phát triển của não bộ."}]','[]',NULL,'/əˈfekt ðə dɪˈveləpmənt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3346,'colloc-1-01',56,'allocate resources','phân bổ nguồn lực','v + n','[{"en":"Managers must allocate resources wisely.","vi":"Người quản lý phải phân bổ nguồn lực một cách khôn ngoan."},{"en":"The government allocates resources to public health.","vi":"Chính phủ phân bổ nguồn lực cho y tế công cộng."},{"en":"We need to allocate resources to the most urgent tasks.","vi":"Chúng ta cần phân bổ nguồn lực cho những nhiệm vụ cấp bách nhất."}]','[]',NULL,'/ˈæləkeɪt ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3347,'colloc-1-01',57,'allow access to','cho phép truy cập, cho phép tiếp cận','v + n','[{"en":"The pass will allow access to all areas.","vi":"Thẻ này sẽ cho phép truy cập vào mọi khu vực."},{"en":"The library allows access to rare manuscripts.","vi":"Thư viện cho phép tiếp cận các bản thảo quý hiếm."},{"en":"The system does not allow access without a password.","vi":"Hệ thống không cho phép truy cập nếu không có mật khẩu."}]','[]',NULL,'/əˈlaʊ ˈækses tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3348,'colloc-1-01',58,'almost identical','gần như giống hệt','adv + adj','[{"en":"The two samples were almost identical.","vi":"Hai mẫu vật gần như giống hệt nhau."},{"en":"Their results were almost identical to ours.","vi":"Kết quả của họ gần như giống hệt của chúng tôi."},{"en":"The twins look almost identical.","vi":"Cặp song sinh trông gần như giống hệt nhau."}]','[]',NULL,'/ˈɔːlmoʊst aɪˈdentɪkəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3349,'colloc-1-01',59,'alternative approach','cách tiếp cận khác','adj + n','[{"en":"When one method fails, try an alternative approach.","vi":"Khi một phương pháp thất bại, hãy thử một cách tiếp cận khác."},{"en":"The team proposed an alternative approach to the problem.","vi":"Nhóm đề xuất một cách tiếp cận khác cho vấn đề."},{"en":"An alternative approach might save both time and money.","vi":"Một cách tiếp cận khác có thể tiết kiệm cả thời gian lẫn tiền bạc."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3350,'colloc-1-01',60,'alternative explanation','lời giải thích khác','adj + n','[{"en":"Scientists offered an alternative explanation for the data.","vi":"Các nhà khoa học đưa ra một lời giải thích khác cho dữ liệu."},{"en":"There may be an alternative explanation for his behavior.","vi":"Có thể có một lời giải thích khác cho hành vi của anh ta."},{"en":"She rejected the alternative explanation as unlikely.","vi":"Cô bác bỏ lời giải thích khác vì cho rằng khó xảy ra."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv ˌekspləˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3351,'colloc-1-01',61,'alternative form','hình thức khác, dạng thay thế','adj + n','[{"en":"Solar power is an alternative form of energy.","vi":"Năng lượng mặt trời là một dạng năng lượng thay thế."},{"en":"The essay can be submitted in an alternative form.","vi":"Bài luận có thể được nộp dưới một hình thức khác."},{"en":"Sign language is an alternative form of communication.","vi":"Ngôn ngữ ký hiệu là một hình thức giao tiếp khác."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv fɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3352,'colloc-1-01',62,'alternative interpretation','cách diễn giải khác','adj + n','[{"en":"The poem allows for an alternative interpretation.","vi":"Bài thơ cho phép một cách diễn giải khác."},{"en":"He proposed an alternative interpretation of the results.","vi":"Ông đề xuất một cách diễn giải khác về kết quả."},{"en":"An alternative interpretation challenges the old theory.","vi":"Một cách diễn giải khác thách thức lý thuyết cũ."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv ɪnˌtɜːrprəˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3353,'colloc-1-01',63,'alternative means','phương tiện khác, cách thức khác','adj + n','[{"en":"Cycling is an alternative means of transport.","vi":"Đạp xe là một phương tiện di chuyển khác."},{"en":"They sought alternative means of funding the project.","vi":"Họ tìm những cách thức khác để tài trợ cho dự án."},{"en":"Email offers an alternative means of contact.","vi":"Email cung cấp một phương tiện liên lạc khác."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv miːnz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3354,'colloc-1-01',64,'alternative method','phương pháp khác','adj + n','[{"en":"Researchers tested an alternative method of analysis.","vi":"Các nhà nghiên cứu thử một phương pháp phân tích khác."},{"en":"An alternative method produced faster results.","vi":"Một phương pháp khác cho kết quả nhanh hơn."},{"en":"She prefers the alternative method of teaching.","vi":"Cô thích phương pháp giảng dạy khác hơn."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3355,'colloc-1-01',65,'alternative model','mô hình khác','adj + n','[{"en":"Economists proposed an alternative model of growth.","vi":"Các nhà kinh tế đề xuất một mô hình tăng trưởng khác."},{"en":"The study tests an alternative model of behavior.","vi":"Nghiên cứu kiểm tra một mô hình hành vi khác."},{"en":"An alternative model better explains the findings.","vi":"Một mô hình khác giải thích các phát hiện tốt hơn."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv ˈmɑːdəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3356,'colloc-1-01',66,'alternative solution','giải pháp khác','adj + n','[{"en":"If this fails, we need an alternative solution.","vi":"Nếu cách này thất bại, ta cần một giải pháp khác."},{"en":"Engineers searched for an alternative solution.","vi":"Các kỹ sư tìm kiếm một giải pháp khác."},{"en":"The committee rejected the alternative solution.","vi":"Ủy ban bác bỏ giải pháp khác."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv səˈluːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3357,'colloc-1-01',67,'alternative source','nguồn khác, nguồn thay thế','adj + n','[{"en":"Wind is an alternative source of energy.","vi":"Gió là một nguồn năng lượng khác."},{"en":"Journalists confirmed it with an alternative source.","vi":"Các nhà báo xác nhận điều đó qua một nguồn khác."},{"en":"We must find an alternative source of funding.","vi":"Chúng ta phải tìm một nguồn tài trợ khác."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3358,'colloc-1-01',68,'alternative strategy','chiến lược khác','adj + n','[{"en":"The company adopted an alternative strategy to grow.","vi":"Công ty áp dụng một chiến lược khác để phát triển."},{"en":"An alternative strategy reduced their losses.","vi":"Một chiến lược khác giúp giảm thiệt hại của họ."},{"en":"Coaches prepared an alternative strategy for the final.","vi":"Các huấn luyện viên chuẩn bị một chiến lược khác cho trận chung kết."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv ˈstrætədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3359,'colloc-1-01',69,'alternative view','quan điểm khác','adj + n','[{"en":"She presented an alternative view of the issue.","vi":"Cô trình bày một quan điểm khác về vấn đề."},{"en":"The article offers an alternative view of history.","vi":"Bài báo đưa ra một quan điểm khác về lịch sử."},{"en":"It is healthy to consider an alternative view.","vi":"Việc xem xét một quan điểm khác là điều lành mạnh."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv vjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3360,'colloc-1-01',70,'alternative way','cách khác','adj + n','[{"en":"There must be an alternative way to solve this.","vi":"Hẳn phải có một cách khác để giải quyết việc này."},{"en":"She found an alternative way to reach the office.","vi":"Cô tìm được một cách khác để đến văn phòng."},{"en":"Technology offers an alternative way of learning.","vi":"Công nghệ mang đến một cách học khác."}]','[]',NULL,'/ɔːlˈtɜːrnətɪv weɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3361,'colloc-1-01',71,'ample evidence','bằng chứng dồi dào, đầy đủ','adj + n','[{"en":"There is ample evidence to support the theory.","vi":"Có bằng chứng dồi dào để ủng hộ lý thuyết này."},{"en":"The study provides ample evidence of the trend.","vi":"Nghiên cứu cung cấp bằng chứng đầy đủ về xu hướng này."},{"en":"Ample evidence shows that exercise improves health.","vi":"Bằng chứng dồi dào cho thấy tập thể dục cải thiện sức khỏe."}]','[]',NULL,'/ˈæmpəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3362,'colloc-1-01',72,'analytical approach','cách tiếp cận phân tích','adj + n','[{"en":"An analytical approach helps break down complex problems.","vi":"Cách tiếp cận phân tích giúp chia nhỏ các vấn đề phức tạp."},{"en":"She takes an analytical approach to research.","vi":"Cô áp dụng cách tiếp cận phân tích trong nghiên cứu."},{"en":"The job requires a careful, analytical approach.","vi":"Công việc đòi hỏi một cách tiếp cận phân tích cẩn thận."}]','[]',NULL,'/ˌænəˈlɪtɪkəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3363,'colloc-1-01',73,'analytical tool','công cụ phân tích','adj + n','[{"en":"Statistics is a powerful analytical tool.","vi":"Thống kê là một công cụ phân tích mạnh mẽ."},{"en":"The software is a useful analytical tool for data.","vi":"Phần mềm là một công cụ phân tích dữ liệu hữu ích."},{"en":"Researchers developed a new analytical tool.","vi":"Các nhà nghiên cứu phát triển một công cụ phân tích mới."}]','[]',NULL,'/ˌænəˈlɪtɪkəl tuːl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3364,'colloc-1-01',74,'anecdotal evidence','bằng chứng giai thoại, truyền miệng','adj + n','[{"en":"Anecdotal evidence is not enough to prove the claim.","vi":"Bằng chứng giai thoại không đủ để chứng minh khẳng định này."},{"en":"He relied on anecdotal evidence rather than data.","vi":"Anh ta dựa vào bằng chứng truyền miệng thay vì dữ liệu."},{"en":"Anecdotal evidence suggests the method works.","vi":"Bằng chứng giai thoại cho thấy phương pháp này có hiệu quả."}]','[]',NULL,'/ˌænɪkˈdoʊtəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3365,'colloc-1-01',75,'annual conference','hội nghị thường niên','adj + n','[{"en":"The annual conference attracts experts from many countries.","vi":"Hội nghị thường niên thu hút chuyên gia từ nhiều quốc gia."},{"en":"She presented her findings at the annual conference.","vi":"Cô trình bày các phát hiện tại hội nghị thường niên."},{"en":"The annual conference will be held online this year.","vi":"Hội nghị thường niên năm nay sẽ được tổ chức trực tuyến."}]','[]',NULL,'/ˈænjuəl ˈkɑːnfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3366,'colloc-1-01',76,'annual meeting','cuộc họp thường niên','adj + n','[{"en":"Shareholders gather for the annual meeting.","vi":"Các cổ đông tụ họp trong cuộc họp thường niên."},{"en":"The annual meeting reviews the year''s progress.","vi":"Cuộc họp thường niên đánh giá tiến độ của cả năm."},{"en":"Decisions are made at the annual meeting.","vi":"Các quyết định được đưa ra tại cuộc họp thường niên."}]','[]',NULL,'/ˈænjuəl ˈmiːtɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3367,'colloc-1-01',77,'annual rate','tỷ lệ hằng năm, lãi suất hằng năm','adj + n','[{"en":"The loan has an annual rate of five percent.","vi":"Khoản vay có lãi suất hằng năm là năm phần trăm."},{"en":"Inflation reached an annual rate of three percent.","vi":"Lạm phát đạt tỷ lệ hằng năm là ba phần trăm."},{"en":"The annual rate of growth slowed last year.","vi":"Tỷ lệ tăng trưởng hằng năm chậm lại vào năm ngoái."}]','[]',NULL,'/ˈænjuəl reɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3368,'colloc-1-01',78,'annual report','báo cáo thường niên','adj + n','[{"en":"The company published its annual report online.","vi":"Công ty công bố báo cáo thường niên trực tuyến."},{"en":"The annual report shows a rise in profits.","vi":"Báo cáo thường niên cho thấy lợi nhuận tăng."},{"en":"Investors study the annual report carefully.","vi":"Các nhà đầu tư nghiên cứu kỹ báo cáo thường niên."}]','[]',NULL,'/ˈænjuəl rɪˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3369,'colloc-1-01',79,'annual review','đánh giá thường niên','adj + n','[{"en":"Employees receive feedback during the annual review.","vi":"Nhân viên nhận phản hồi trong kỳ đánh giá thường niên."},{"en":"The annual review highlighted several achievements.","vi":"Bản đánh giá thường niên nêu bật nhiều thành tựu."},{"en":"Her salary increased after the annual review.","vi":"Lương của cô tăng sau kỳ đánh giá thường niên."}]','[]',NULL,'/ˈænjuəl rɪˈvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3370,'colloc-1-01',80,'apply equally','áp dụng như nhau, áp dụng bình đẳng','v + adv','[{"en":"The rules apply equally to all students.","vi":"Các quy định áp dụng như nhau cho mọi học sinh."},{"en":"This principle applies equally in both cases.","vi":"Nguyên tắc này áp dụng như nhau trong cả hai trường hợp."},{"en":"The law should apply equally to everyone.","vi":"Luật pháp nên áp dụng bình đẳng cho tất cả mọi người."}]','[]',NULL,'/əˈplaɪ ˈiːkwəli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3371,'colloc-1-01',81,'apply a method','áp dụng phương pháp','v + n','[{"en":"Researchers apply a scientific method to the study.","vi":"Các nhà nghiên cứu áp dụng phương pháp khoa học cho nghiên cứu."},{"en":"You can apply this method to similar problems.","vi":"Bạn có thể áp dụng phương pháp này cho các vấn đề tương tự."},{"en":"She applied a new method to analyze the results.","vi":"Cô áp dụng một phương pháp mới để phân tích kết quả."}]','[]',NULL,'/əˈplaɪ ə ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3372,'colloc-1-01',82,'apply the theory','áp dụng lý thuyết','v + n','[{"en":"Students learn to apply theory to real situations.","vi":"Sinh viên học cách áp dụng lý thuyết vào tình huống thực tế."},{"en":"It is hard to apply theory without practice.","vi":"Khó áp dụng lý thuyết nếu thiếu thực hành."},{"en":"Engineers apply theory to design safer bridges.","vi":"Các kỹ sư áp dụng lý thuyết để thiết kế những cây cầu an toàn hơn."}]','[]',NULL,'/əˈplaɪ ðə ˈθɪri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3373,'colloc-1-01',83,'appropriate action','hành động phù hợp','adj + n','[{"en":"The committee took appropriate action to resolve the dispute quickly.","vi":"Ủy ban đã có hành động phù hợp để giải quyết tranh chấp nhanh chóng."},{"en":"Managers must decide on appropriate action when problems arise.","vi":"Người quản lý phải quyết định hành động phù hợp khi vấn đề phát sinh."},{"en":"Failing to take appropriate action can worsen the situation.","vi":"Không có hành động phù hợp có thể khiến tình hình tồi tệ hơn."}]','[]',NULL,'/əˈproʊpriət ˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3374,'colloc-1-01',84,'appropriate behavior','hành vi phù hợp','adj + n','[{"en":"Teachers model appropriate behavior for young children in class.","vi":"Giáo viên làm gương về hành vi phù hợp cho trẻ nhỏ trong lớp."},{"en":"The handbook defines appropriate behavior in the workplace clearly.","vi":"Cẩm nang quy định rõ hành vi phù hợp tại nơi làm việc."},{"en":"Students learn appropriate behavior through consistent rules and feedback.","vi":"Học sinh học hành vi phù hợp qua các quy tắc và phản hồi nhất quán."}]','[]',NULL,'/əˈproʊpriət bɪˈheɪvjər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3375,'colloc-1-01',85,'appropriate conditions','điều kiện phù hợp','adj + n','[{"en":"Plants grow well only under appropriate conditions of light.","vi":"Cây chỉ phát triển tốt trong điều kiện ánh sáng phù hợp."},{"en":"Researchers created appropriate conditions for the experiment to succeed.","vi":"Các nhà nghiên cứu tạo điều kiện phù hợp để thí nghiệm thành công."},{"en":"Appropriate conditions are essential for storing sensitive chemical samples.","vi":"Điều kiện phù hợp rất cần thiết để bảo quản mẫu hóa chất nhạy cảm."}]','[]',NULL,'/əˈproʊpriət kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3376,'colloc-1-01',86,'appropriate data','dữ liệu phù hợp','adj + n','[{"en":"Selecting appropriate data is the first step in any analysis.","vi":"Chọn dữ liệu phù hợp là bước đầu tiên trong mọi phân tích."},{"en":"Without appropriate data, the conclusions remain weak and unreliable.","vi":"Nếu thiếu dữ liệu phù hợp, kết luận sẽ yếu và không đáng tin."},{"en":"The team gathered appropriate data from several reliable sources.","vi":"Nhóm đã thu thập dữ liệu phù hợp từ nhiều nguồn đáng tin cậy."}]','[]',NULL,'/əˈproʊpriət ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3377,'colloc-1-01',87,'appropriate form','hình thức phù hợp','adj + n','[{"en":"Choose the appropriate form to present your research findings clearly.","vi":"Hãy chọn hình thức phù hợp để trình bày rõ kết quả nghiên cứu."},{"en":"Data should be stored in an appropriate form for analysis.","vi":"Dữ liệu nên được lưu ở hình thức phù hợp để phân tích."},{"en":"The instructor explained the appropriate form for citing sources.","vi":"Giảng viên giải thích hình thức phù hợp để trích dẫn nguồn."}]','[]',NULL,'/əˈproʊpriət fɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3378,'colloc-1-01',88,'appropriate language','ngôn ngữ phù hợp','adj + n','[{"en":"Academic essays require appropriate language and a formal tone.","vi":"Bài luận học thuật đòi hỏi ngôn ngữ phù hợp và giọng văn trang trọng."},{"en":"Using appropriate language helps readers understand complex ideas easily.","vi":"Dùng ngôn ngữ phù hợp giúp người đọc hiểu ý phức tạp dễ dàng."},{"en":"The teacher praised her appropriate language during the formal presentation.","vi":"Giáo viên khen ngôn ngữ phù hợp của cô trong bài thuyết trình trang trọng."}]','[]',NULL,'/əˈproʊpriət ˈlæŋɡwɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3379,'colloc-1-01',89,'appropriate level','mức độ phù hợp','adj + n','[{"en":"The course is taught at an appropriate level for beginners.","vi":"Khóa học được dạy ở mức độ phù hợp cho người mới bắt đầu."},{"en":"Maintaining an appropriate level of difficulty keeps students motivated.","vi":"Giữ mức độ khó phù hợp giúp học sinh duy trì động lực."},{"en":"Managers set tasks at an appropriate level for each employee.","vi":"Quản lý giao việc ở mức độ phù hợp với từng nhân viên."}]','[]',NULL,'/əˈproʊpriət ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3380,'colloc-1-01',90,'appropriate point','thời điểm phù hợp','adj + n','[{"en":"Raise your questions at an appropriate point during the lecture.","vi":"Hãy nêu câu hỏi vào thời điểm phù hợp trong buổi giảng."},{"en":"The author introduces the theory at an appropriate point.","vi":"Tác giả giới thiệu lý thuyết vào thời điểm phù hợp."},{"en":"Stopping the discussion at an appropriate point avoids confusion.","vi":"Dừng thảo luận vào thời điểm phù hợp giúp tránh nhầm lẫn."}]','[]',NULL,'/əˈproʊpriət pɔɪnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3381,'colloc-1-01',91,'appropriate response','phản ứng phù hợp','adj + n','[{"en":"An appropriate response to criticism is to listen calmly.","vi":"Một phản ứng phù hợp với lời chỉ trích là lắng nghe bình tĩnh."},{"en":"The government''s appropriate response reduced public panic during the crisis.","vi":"Phản ứng phù hợp của chính phủ đã giảm hoảng loạn trong khủng hoảng."},{"en":"Choosing an appropriate response requires understanding the whole situation.","vi":"Chọn phản ứng phù hợp đòi hỏi hiểu rõ toàn bộ tình huống."}]','[]',NULL,'/əˈproʊpriət rɪˈspɑːns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3382,'colloc-1-01',92,'appropriate skills','kỹ năng phù hợp','adj + n','[{"en":"Employers look for candidates with the appropriate skills and experience.","vi":"Nhà tuyển dụng tìm ứng viên có kỹ năng phù hợp và kinh nghiệm."},{"en":"The program develops appropriate skills for the modern workplace.","vi":"Chương trình phát triển kỹ năng phù hợp cho nơi làm việc hiện đại."},{"en":"Without appropriate skills, completing the task becomes very difficult.","vi":"Nếu thiếu kỹ năng phù hợp, việc hoàn thành nhiệm vụ trở nên rất khó."}]','[]',NULL,'/əˈproʊpriət skɪlz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3383,'colloc-1-01',93,'appropriate treatment','phương pháp điều trị phù hợp','adj + n','[{"en":"Doctors recommend appropriate treatment based on each patient''s condition.","vi":"Bác sĩ đề xuất điều trị phù hợp dựa trên tình trạng từng bệnh nhân."},{"en":"Early diagnosis allows for more appropriate treatment of the disease.","vi":"Chẩn đoán sớm cho phép điều trị bệnh phù hợp hơn."},{"en":"The study compared appropriate treatment options for chronic pain.","vi":"Nghiên cứu so sánh các phương pháp điều trị phù hợp cho cơn đau mãn tính."}]','[]',NULL,'/əˈproʊpriət ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3384,'colloc-1-01',94,'appropriate way','cách thức phù hợp','adj + n','[{"en":"There is an appropriate way to address senior colleagues formally.","vi":"Có một cách thức phù hợp để xưng hô trang trọng với đồng nghiệp lớn tuổi."},{"en":"The manual describes the appropriate way to handle equipment.","vi":"Sổ tay mô tả cách thức phù hợp để vận hành thiết bị."},{"en":"Finding the appropriate way to explain results helps readers.","vi":"Tìm cách thức phù hợp để giải thích kết quả giúp ích cho người đọc."}]','[]',NULL,'/əˈproʊpriət weɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3385,'colloc-1-01',95,'armed conflict','xung đột vũ trang','adj + n','[{"en":"Millions of people were displaced by the long armed conflict.","vi":"Hàng triệu người phải di tản vì xung đột vũ trang kéo dài."},{"en":"The treaty aimed to end decades of armed conflict.","vi":"Hiệp ước nhằm chấm dứt hàng chục năm xung đột vũ trang."},{"en":"Researchers study how armed conflict affects civilian populations and economies.","vi":"Các nhà nghiên cứu tìm hiểu xung đột vũ trang ảnh hưởng dân thường và kinh tế thế nào."}]','[]',NULL,'/ɑːrmd ˈkɑːnflɪkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3386,'colloc-1-01',96,'artificial intelligence','trí tuệ nhân tạo','adj + n','[{"en":"Artificial intelligence is transforming how businesses analyze large datasets.","vi":"Trí tuệ nhân tạo đang thay đổi cách doanh nghiệp phân tích dữ liệu lớn."},{"en":"The university offers a new course on artificial intelligence.","vi":"Trường đại học mở một khóa học mới về trí tuệ nhân tạo."},{"en":"Many jobs may change as artificial intelligence becomes more advanced.","vi":"Nhiều công việc có thể thay đổi khi trí tuệ nhân tạo tiến bộ hơn."}]','[]',NULL,'/ˌɑːrtɪˈfɪʃəl ɪnˈtelɪdʒəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3387,'colloc-1-01',97,'assess the impact of','đánh giá tác động của','v + n','[{"en":"Scientists assess the impact of climate change on coastal cities.","vi":"Các nhà khoa học đánh giá tác động của biến đổi khí hậu lên thành phố ven biển."},{"en":"The report tries to assess the impact of new policies.","vi":"Báo cáo cố gắng đánh giá tác động của các chính sách mới."},{"en":"We must assess the impact of advertising on consumer choices.","vi":"Chúng ta phải đánh giá tác động của quảng cáo lên lựa chọn người tiêu dùng."}]','[]',NULL,'/əˈses ði ˈɪmpækt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3388,'colloc-1-01',98,'assessment process','quá trình đánh giá','n + n','[{"en":"The assessment process includes written tests and practical exercises.","vi":"Quá trình đánh giá gồm bài kiểm tra viết và bài thực hành."},{"en":"A fair assessment process ensures all students are treated equally.","vi":"Quá trình đánh giá công bằng đảm bảo mọi học sinh được đối xử như nhau."},{"en":"Teachers explained each stage of the assessment process clearly.","vi":"Giáo viên giải thích rõ từng giai đoạn của quá trình đánh giá."}]','[]',NULL,'/əˈsesmənt ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3389,'colloc-1-01',99,'associated factors','các yếu tố liên quan','adj + n','[{"en":"The study identified several associated factors that influence student performance.","vi":"Nghiên cứu xác định một số yếu tố liên quan ảnh hưởng đến thành tích học sinh."},{"en":"Researchers examined associated factors linked to high blood pressure.","vi":"Các nhà nghiên cứu khảo sát yếu tố liên quan đến huyết áp cao."},{"en":"Understanding associated factors helps doctors prevent the disease early.","vi":"Hiểu các yếu tố liên quan giúp bác sĩ phòng bệnh sớm."}]','[]',NULL,'/əˈsoʊsieɪtɪd ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3390,'colloc-1-01',100,'assume responsibility','đảm nhận trách nhiệm','v + n','[{"en":"New managers must assume responsibility for their team''s results.","vi":"Quản lý mới phải đảm nhận trách nhiệm về kết quả của nhóm mình."},{"en":"She agreed to assume responsibility for the entire research project.","vi":"Cô đồng ý đảm nhận trách nhiệm cho toàn bộ dự án nghiên cứu."},{"en":"Citizens should assume responsibility for protecting their local environment.","vi":"Người dân nên đảm nhận trách nhiệm bảo vệ môi trường địa phương."}]','[]',NULL,'/əˈsuːm rɪˌspɑːnsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3391,'colloc-1-01',101,'assume the role of','đảm nhận vai trò','v + n','[{"en":"She will assume the role of department head next month.","vi":"Cô sẽ đảm nhận vai trò trưởng phòng vào tháng tới."},{"en":"In the experiment, students assume the role of observers.","vi":"Trong thí nghiệm, học sinh đảm nhận vai trò người quan sát."},{"en":"Older siblings often assume the role of caregivers at home.","vi":"Anh chị lớn thường đảm nhận vai trò người chăm sóc ở nhà."}]','[]',NULL,'/əˈsuːm ðə roʊl əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3392,'colloc-1-01',102,'atomic energy','năng lượng nguyên tử','adj + n','[{"en":"Atomic energy can generate large amounts of electricity efficiently.","vi":"Năng lượng nguyên tử có thể tạo ra lượng điện lớn một cách hiệu quả."},{"en":"The agency monitors the peaceful use of atomic energy worldwide.","vi":"Cơ quan này giám sát việc sử dụng hòa bình năng lượng nguyên tử toàn cầu."},{"en":"Debates about atomic energy focus on safety and waste.","vi":"Các tranh luận về năng lượng nguyên tử tập trung vào an toàn và chất thải."}]','[]',NULL,'/əˈtɑːmɪk ˈenərdʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3393,'colloc-1-01',103,'attend a conference','tham dự một hội nghị','v + n','[{"en":"She will attend a conference on renewable energy next week.","vi":"Cô sẽ tham dự một hội nghị về năng lượng tái tạo vào tuần tới."},{"en":"Many researchers travel abroad to attend a conference each year.","vi":"Nhiều nhà nghiên cứu ra nước ngoài để tham dự một hội nghị mỗi năm."},{"en":"Students were encouraged to attend a conference and present posters.","vi":"Sinh viên được khuyến khích tham dự một hội nghị và trình bày áp phích."}]','[]',NULL,'/əˈtend ə ˈkɑːnfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3394,'colloc-1-01',104,'available data','dữ liệu sẵn có','adj + n','[{"en":"The conclusion is based on all the available data so far.","vi":"Kết luận dựa trên toàn bộ dữ liệu sẵn có cho đến nay."},{"en":"Limited available data made the analysis quite challenging for researchers.","vi":"Dữ liệu sẵn có hạn chế khiến việc phân tích khá khó với các nhà nghiên cứu."},{"en":"They reviewed available data before designing the new survey.","vi":"Họ xem lại dữ liệu sẵn có trước khi thiết kế khảo sát mới."}]','[]',NULL,'/əˈveɪləbəl ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3395,'colloc-1-01',105,'available evidence','bằng chứng sẵn có','adj + n','[{"en":"The available evidence strongly supports the researcher''s main hypothesis.","vi":"Bằng chứng sẵn có ủng hộ mạnh mẽ giả thuyết chính của nhà nghiên cứu."},{"en":"Based on available evidence, the court reached a fair decision.","vi":"Dựa trên bằng chứng sẵn có, tòa án đã đưa ra phán quyết công bằng."},{"en":"Scientists must weigh all available evidence before drawing conclusions.","vi":"Các nhà khoa học phải cân nhắc mọi bằng chứng sẵn có trước khi kết luận."}]','[]',NULL,'/əˈveɪləbəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3396,'colloc-1-01',106,'available information','thông tin sẵn có','adj + n','[{"en":"Make your decision using all the available information you have.","vi":"Hãy đưa ra quyết định bằng mọi thông tin sẵn có mà bạn có."},{"en":"The website gathers available information about local public transport services.","vi":"Trang web tập hợp thông tin sẵn có về dịch vụ giao thông công cộng địa phương."},{"en":"With little available information, predicting the outcome proved difficult.","vi":"Với ít thông tin sẵn có, việc dự đoán kết quả trở nên khó khăn."}]','[]',NULL,'/əˈveɪləbəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3397,'colloc-1-01',107,'available resources','nguồn lực sẵn có','adj + n','[{"en":"The team completed the project using only available resources efficiently.","vi":"Nhóm hoàn thành dự án chỉ bằng nguồn lực sẵn có một cách hiệu quả."},{"en":"Schools must make the best use of available resources.","vi":"Trường học phải tận dụng tốt nhất nguồn lực sẵn có."},{"en":"Limited available resources forced the charity to set priorities.","vi":"Nguồn lực sẵn có hạn chế buộc tổ chức từ thiện phải đặt ưu tiên."}]','[]',NULL,'/əˈveɪləbəl ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3398,'colloc-1-01',108,'average score','điểm trung bình','adj + n','[{"en":"The class achieved an average score above the national level.","vi":"Lớp đạt điểm trung bình cao hơn mức của cả nước."},{"en":"Her average score improved steadily throughout the entire semester.","vi":"Điểm trung bình của cô cải thiện đều đặn suốt cả học kỳ."},{"en":"The report compares the average score of different age groups.","vi":"Báo cáo so sánh điểm trung bình của các nhóm tuổi khác nhau."}]','[]',NULL,'/ˈævərɪdʒ skɔːr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3399,'colloc-1-01',109,'background knowledge','kiến thức nền','n + n','[{"en":"Strong background knowledge helps students understand difficult academic texts.","vi":"Kiến thức nền vững giúp học sinh hiểu các văn bản học thuật khó."},{"en":"The lecture assumes some background knowledge of basic economics.","vi":"Bài giảng giả định người học có kiến thức nền về kinh tế cơ bản."},{"en":"Readers with little background knowledge may find the article confusing.","vi":"Người đọc thiếu kiến thức nền có thể thấy bài viết khó hiểu."}]','[]',NULL,'/ˈbækɡraʊnd ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3400,'colloc-1-01',110,'basic assumption','giả định cơ bản','adj + n','[{"en":"The model rests on a basic assumption about human behavior.","vi":"Mô hình dựa trên một giả định cơ bản về hành vi con người."},{"en":"If the basic assumption is wrong, the whole theory fails.","vi":"Nếu giả định cơ bản sai, toàn bộ lý thuyết sẽ thất bại."},{"en":"Economists often question the basic assumption that people act rationally.","vi":"Các nhà kinh tế thường nghi ngờ giả định cơ bản rằng con người hành động hợp lý."}]','[]',NULL,'/ˈbeɪsɪk əˈsʌmpʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3401,'colloc-1-01',111,'basic component','thành phần cơ bản','adj + n','[{"en":"Water is a basic component of every living cell.","vi":"Nước là một thành phần cơ bản của mọi tế bào sống."},{"en":"Trust is a basic component of any healthy relationship.","vi":"Sự tin tưởng là một thành phần cơ bản của mọi mối quan hệ lành mạnh."},{"en":"The course covers each basic component of computer hardware.","vi":"Khóa học giới thiệu từng thành phần cơ bản của phần cứng máy tính."}]','[]',NULL,'/ˈbeɪsɪk kəmˈpoʊnənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3402,'colloc-1-01',112,'basic concept','khái niệm cơ bản','adj + n','[{"en":"Students must grasp the basic concept before moving to applications.","vi":"Học sinh phải nắm khái niệm cơ bản trước khi học các ứng dụng."},{"en":"The first chapter introduces the basic concept of supply.","vi":"Chương đầu giới thiệu khái niệm cơ bản về cung."},{"en":"A clear example explains the basic concept very effectively.","vi":"Một ví dụ rõ ràng giải thích khái niệm cơ bản rất hiệu quả."}]','[]',NULL,'/ˈbeɪsɪk ˈkɑːnsept/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3403,'colloc-1-01',113,'basic element','yếu tố cơ bản','adj + n','[{"en":"Color is a basic element of effective visual design.","vi":"Màu sắc là một yếu tố cơ bản của thiết kế hình ảnh hiệu quả."},{"en":"Communication is a basic element of successful teamwork everywhere.","vi":"Giao tiếp là một yếu tố cơ bản của làm việc nhóm thành công khắp nơi."},{"en":"The teacher explained each basic element of the writing process.","vi":"Giáo viên giải thích từng yếu tố cơ bản của quá trình viết."}]','[]',NULL,'/ˈbeɪsɪk ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3404,'colloc-1-01',114,'basic function','chức năng cơ bản','adj + n','[{"en":"The basic function of the heart is to pump blood.","vi":"Chức năng cơ bản của tim là bơm máu."},{"en":"Every government has the basic function of protecting its citizens.","vi":"Mọi chính phủ đều có chức năng cơ bản là bảo vệ công dân."},{"en":"The manual describes the basic function of each button.","vi":"Sổ tay mô tả chức năng cơ bản của từng nút."}]','[]',NULL,'/ˈbeɪsɪk ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3405,'colloc-1-01',115,'basic information','thông tin cơ bản','adj + n','[{"en":"Please provide some basic information about your previous work experience.","vi":"Vui lòng cung cấp một số thông tin cơ bản về kinh nghiệm làm việc trước đây."},{"en":"The form collects basic information such as name and address.","vi":"Mẫu đơn thu thập thông tin cơ bản như tên và địa chỉ."},{"en":"The leaflet gives basic information about the new health service.","vi":"Tờ rơi cung cấp thông tin cơ bản về dịch vụ y tế mới."}]','[]',NULL,'/ˈbeɪsɪk ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3406,'colloc-1-01',116,'basic premise','tiền đề cơ bản','adj + n','[{"en":"The basic premise of the argument is that education matters.","vi":"Tiền đề cơ bản của lập luận là giáo dục có vai trò quan trọng."},{"en":"Critics challenged the basic premise behind the entire study.","vi":"Các nhà phê bình thách thức tiền đề cơ bản đằng sau toàn bộ nghiên cứu."},{"en":"Her essay clearly states its basic premise in the introduction.","vi":"Bài luận của cô nêu rõ tiền đề cơ bản ngay ở phần mở đầu."}]','[]',NULL,'/ˈbeɪsɪk ˈpremɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3407,'colloc-1-01',117,'basic principle','nguyên tắc cơ bản','adj + n','[{"en":"Fairness is a basic principle of any good legal system.","vi":"Công bằng là một nguyên tắc cơ bản của mọi hệ thống pháp luật tốt."},{"en":"The lecture explains the basic principle of supply and demand.","vi":"Bài giảng giải thích nguyên tắc cơ bản về cung và cầu."},{"en":"Engineers apply this basic principle when designing safe bridges.","vi":"Kỹ sư áp dụng nguyên tắc cơ bản này khi thiết kế cầu an toàn."}]','[]',NULL,'/ˈbeɪsɪk ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3408,'colloc-1-01',118,'basic research','nghiên cứu cơ bản','adj + n','[{"en":"Basic research often leads to unexpected and valuable practical applications.","vi":"Nghiên cứu cơ bản thường dẫn đến những ứng dụng thực tế bất ngờ và giá trị."},{"en":"The government increased funding for basic research in biology.","vi":"Chính phủ tăng kinh phí cho nghiên cứu cơ bản trong sinh học."},{"en":"Without basic research, technological progress would slow down considerably.","vi":"Nếu thiếu nghiên cứu cơ bản, tiến bộ công nghệ sẽ chậm lại đáng kể."}]','[]',NULL,'/ˈbeɪsɪk ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3409,'colloc-1-01',119,'basic structure','cấu trúc cơ bản','adj + n','[{"en":"The basic structure of an essay includes introduction and conclusion.","vi":"Cấu trúc cơ bản của một bài luận gồm mở bài và kết bài."},{"en":"Scientists studied the basic structure of the protein molecule.","vi":"Các nhà khoa học nghiên cứu cấu trúc cơ bản của phân tử protein."},{"en":"Understanding the basic structure helps readers follow the argument.","vi":"Hiểu cấu trúc cơ bản giúp người đọc theo dõi lập luận."}]','[]',NULL,'/ˈbeɪsɪk ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3410,'colloc-1-01',120,'basic technique','kỹ thuật cơ bản','adj + n','[{"en":"Students learn the basic technique before attempting advanced experiments.","vi":"Học sinh học kỹ thuật cơ bản trước khi thử các thí nghiệm nâng cao."},{"en":"This basic technique is used widely in modern photography.","vi":"Kỹ thuật cơ bản này được dùng rộng rãi trong nhiếp ảnh hiện đại."},{"en":"The coach demonstrated the basic technique to the new players.","vi":"Huấn luyện viên minh họa kỹ thuật cơ bản cho các cầu thủ mới."}]','[]',NULL,'/ˈbeɪsɪk tekˈniːk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3411,'colloc-1-01',121,'bear resemblance to','có nét giống với','v + n','[{"en":"The new design bears resemblance to an older famous model.","vi":"Thiết kế mới có nét giống với một mẫu nổi tiếng cũ hơn."},{"en":"Her painting bears resemblance to the works of impressionist masters.","vi":"Bức tranh của cô có nét giống với tác phẩm của các bậc thầy trường phái ấn tượng."},{"en":"These two languages bear resemblance to each other in grammar.","vi":"Hai ngôn ngữ này có nét giống nhau về ngữ pháp."}]','[]',NULL,'/ber rɪˈzembləns tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3412,'colloc-1-01',122,'become apparent','trở nên rõ ràng','v + adj','[{"en":"The problems with the plan soon became apparent to everyone.","vi":"Những vấn đề của kế hoạch nhanh chóng trở nên rõ ràng với mọi người."},{"en":"It became apparent that the data had been recorded incorrectly.","vi":"Rõ ràng là dữ liệu đã được ghi chép sai."},{"en":"The benefits of exercise become apparent after a few weeks.","vi":"Lợi ích của tập thể dục trở nên rõ ràng sau vài tuần."}]','[]',NULL,'/bɪˈkʌm əˈpærənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3413,'colloc-1-01',123,'become available','trở nên sẵn có','v + adj','[{"en":"New scholarships will become available to students next academic year.","vi":"Học bổng mới sẽ trở nên sẵn có cho sinh viên vào năm học tới."},{"en":"As more data become available, the model grows more accurate.","vi":"Khi có thêm dữ liệu sẵn có, mô hình trở nên chính xác hơn."},{"en":"The medicine became available after years of careful testing.","vi":"Loại thuốc trở nên sẵn có sau nhiều năm thử nghiệm kỹ lưỡng."}]','[]',NULL,'/bɪˈkʌm əˈveɪləbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3414,'colloc-1-01',124,'become aware','trở nên ý thức được','v + adj','[{"en":"People are becoming aware of the dangers of plastic waste.","vi":"Mọi người đang trở nên ý thức được mối nguy của rác thải nhựa."},{"en":"Students gradually become aware of their own learning habits.","vi":"Học sinh dần trở nên ý thức được thói quen học tập của mình."},{"en":"She became aware that the experiment had a serious flaw.","vi":"Cô nhận ra rằng thí nghiệm có một lỗi nghiêm trọng."}]','[]',NULL,'/bɪˈkʌm əˈwer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3415,'colloc-1-01',125,'become blurred','trở nên mờ nhạt','v + adj','[{"en":"The line between work and home has become blurred recently.","vi":"Ranh giới giữa công việc và gia đình gần đây đã trở nên mờ nhạt."},{"en":"Distinctions between the two categories often become blurred over time.","vi":"Sự phân biệt giữa hai loại thường trở nên mờ nhạt theo thời gian."},{"en":"Old memories become blurred as the years go by.","vi":"Những ký ức cũ trở nên mờ nhạt khi năm tháng trôi qua."}]','[]',NULL,'/bɪˈkʌm blɜːrd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3416,'colloc-1-01',126,'become established','trở nên vững chắc','v + adj','[{"en":"The new theory took years to become established in science.","vi":"Lý thuyết mới mất nhiều năm để trở nên vững chắc trong khoa học."},{"en":"Once habits become established, they are hard to change.","vi":"Một khi thói quen trở nên vững chắc, chúng rất khó thay đổi."},{"en":"The company became established as a leader in renewable energy.","vi":"Công ty đã trở nên vững chắc với vị thế dẫn đầu về năng lượng tái tạo."}]','[]',NULL,'/bɪˈkʌm ɪˈstæblɪʃt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3417,'colloc-1-01',127,'become evident','trở nên rõ rệt','v + adj','[{"en":"It became evident that further research would be necessary soon.","vi":"Rõ rệt là cần phải có thêm nghiên cứu trong thời gian tới."},{"en":"The effects of the policy became evident within a year.","vi":"Tác động của chính sách trở nên rõ rệt chỉ trong một năm."},{"en":"Her talent became evident during the first few rehearsals.","vi":"Tài năng của cô trở nên rõ rệt trong vài buổi tập đầu tiên."}]','[]',NULL,'/bɪˈkʌm ˈevɪdənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3418,'colloc-1-01',128,'become independent','trở nên độc lập','v + adj','[{"en":"Many countries became independent during the twentieth century.","vi":"Nhiều quốc gia đã trở nên độc lập trong thế kỷ hai mươi."},{"en":"University helps young people become independent and self-reliant adults.","vi":"Đại học giúp người trẻ trở nên độc lập và tự lập."},{"en":"Children gradually become independent as they grow older.","vi":"Trẻ em dần trở nên độc lập khi lớn lên."}]','[]',NULL,'/bɪˈkʌm ˌɪndɪˈpendənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3419,'colloc-1-01',129,'become involved with','trở nên gắn bó với','v + adj','[{"en":"She became involved with several community projects during college.","vi":"Cô trở nên gắn bó với nhiều dự án cộng đồng trong thời đại học."},{"en":"Students are encouraged to become involved with campus organizations.","vi":"Sinh viên được khuyến khích tham gia gắn bó với các tổ chức trong trường."},{"en":"He became involved with the research team after graduation.","vi":"Anh trở nên gắn bó với nhóm nghiên cứu sau khi tốt nghiệp."}]','[]',NULL,'/bɪˈkʌm ɪnˈvɑːlvd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3420,'colloc-1-01',130,'become obvious','trở nên hiển nhiên','v + adj','[{"en":"The mistake became obvious as soon as we checked again.","vi":"Lỗi sai trở nên hiển nhiên ngay khi chúng tôi kiểm tra lại."},{"en":"It became obvious that the original plan would not work.","vi":"Rõ ràng là kế hoạch ban đầu sẽ không hiệu quả."},{"en":"The reasons for the failure became obvious after the analysis.","vi":"Lý do thất bại trở nên hiển nhiên sau khi phân tích."}]','[]',NULL,'/bɪˈkʌm ˈɑːbviəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3421,'colloc-1-01',131,'become visible','trở nên rõ thấy','v + adj','[{"en":"Tiny cracks become visible only under a powerful microscope.","vi":"Những vết nứt nhỏ chỉ trở nên rõ thấy dưới kính hiển vi mạnh."},{"en":"The stars become visible once the city lights fade.","vi":"Các ngôi sao trở nên rõ thấy khi ánh đèn thành phố mờ đi."},{"en":"Social problems become visible during times of economic crisis.","vi":"Các vấn đề xã hội trở nên rõ thấy trong thời kỳ khủng hoảng kinh tế."}]','[]',NULL,'/bɪˈkʌm ˈvɪzəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3422,'colloc-1-01',132,'become widespread','trở nên phổ biến rộng rãi','v + adj','[{"en":"Mobile phones became widespread within a single decade worldwide.","vi":"Điện thoại di động trở nên phổ biến rộng rãi chỉ trong một thập kỷ."},{"en":"The practice became widespread after the new law passed.","vi":"Thực hành này trở nên phổ biến rộng rãi sau khi luật mới được thông qua."},{"en":"Once the idea became widespread, attitudes slowly began changing.","vi":"Khi ý tưởng trở nên phổ biến rộng rãi, thái độ dần bắt đầu thay đổi."}]','[]',NULL,'/bɪˈkʌm ˈwaɪdˈspred/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3423,'colloc-1-01',133,'become a source of','trở thành nguồn gốc của','v + n','[{"en":"The river became a source of fresh water for the village.","vi":"Con sông trở thành nguồn nước ngọt cho ngôi làng."},{"en":"Social media can become a source of stress for teenagers.","vi":"Mạng xã hội có thể trở thành nguồn gây căng thẳng cho thanh thiếu niên."},{"en":"Tourism has become a source of income for the region.","vi":"Du lịch đã trở thành nguồn thu nhập cho cả vùng."}]','[]',NULL,'/bɪˈkʌm ə sɔːrs əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3424,'colloc-1-01',134,'become the focus of','trở thành trọng tâm của','v + n','[{"en":"Climate change has become the focus of recent global discussions.","vi":"Biến đổi khí hậu đã trở thành trọng tâm của các thảo luận toàn cầu gần đây."},{"en":"The young scientist became the focus of considerable media attention.","vi":"Nhà khoa học trẻ trở thành trọng tâm của nhiều sự chú ý từ truyền thông."},{"en":"Education became the focus of the government''s new reform program.","vi":"Giáo dục trở thành trọng tâm của chương trình cải cách mới của chính phủ."}]','[]',NULL,'/bɪˈkʌm ðə ˈfoʊkəs əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3425,'colloc-1-01',135,'begin a process','bắt đầu một quá trình','v + n','[{"en":"The company will begin a process of major internal reform.","vi":"Công ty sẽ bắt đầu một quá trình cải tổ nội bộ lớn."},{"en":"Researchers begin a process of testing before publishing any results.","vi":"Các nhà nghiên cứu bắt đầu một quá trình thử nghiệm trước khi công bố kết quả."},{"en":"The two nations agreed to begin a process of negotiation.","vi":"Hai quốc gia đồng ý bắt đầu một quá trình đàm phán."}]','[]',NULL,'/bɪˈɡɪn ə ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3426,'colloc-1-01',136,'behave differently','hành xử khác nhau','v + adv','[{"en":"Children often behave differently when their parents are watching.","vi":"Trẻ em thường hành xử khác đi khi có bố mẹ quan sát."},{"en":"These materials behave differently under high temperature and pressure.","vi":"Các vật liệu này phản ứng khác nhau dưới nhiệt độ và áp suất cao."},{"en":"People may behave differently in unfamiliar social situations.","vi":"Mọi người có thể hành xử khác nhau trong tình huống xã hội lạ lẫm."}]','[]',NULL,'/bɪˈheɪv ˈdɪfrəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3427,'colloc-1-01',137,'beneficial effect','tác động có lợi','adj + n','[{"en":"Regular exercise has a beneficial effect on mental health.","vi":"Tập thể dục đều đặn có tác động có lợi đối với sức khỏe tinh thần."},{"en":"The new policy had a beneficial effect on small businesses.","vi":"Chính sách mới có tác động có lợi đối với các doanh nghiệp nhỏ."},{"en":"Sleep has a beneficial effect on memory and concentration.","vi":"Giấc ngủ có tác động có lợi đối với trí nhớ và sự tập trung."}]','[]',NULL,'/ˌbenɪˈfɪʃəl ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3428,'colloc-1-01',138,'best described as','được mô tả chính xác nhất là','adv + vpp','[{"en":"The novel is best described as a thoughtful social commentary.","vi":"Cuốn tiểu thuyết được mô tả chính xác nhất là một bình luận xã hội sâu sắc."},{"en":"His leadership style is best described as calm and inclusive.","vi":"Phong cách lãnh đạo của anh được mô tả chính xác nhất là điềm tĩnh và bao dung."},{"en":"The region''s climate is best described as warm and humid.","vi":"Khí hậu của vùng này được mô tả chính xác nhất là ấm và ẩm."}]','[]',NULL,'/best dɪˈskraɪbd æz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3429,'colloc-1-01',139,'binary opposition','đối lập nhị phân','adj + n','[{"en":"The essay explores the binary opposition between nature and culture.","vi":"Bài luận khám phá sự đối lập nhị phân giữa tự nhiên và văn hóa."},{"en":"Many myths are structured around a clear binary opposition.","vi":"Nhiều thần thoại được cấu trúc quanh một đối lập nhị phân rõ ràng."},{"en":"Critics question whether this binary opposition truly reflects reality.","vi":"Các nhà phê bình nghi ngờ liệu đối lập nhị phân này có phản ánh đúng thực tế."}]','[]',NULL,'/ˈbaɪnəri ˌɑːpəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3430,'colloc-1-01',140,'binary system','hệ nhị phân','adj + n','[{"en":"Computers store information using a simple binary system of digits.","vi":"Máy tính lưu thông tin bằng một hệ nhị phân đơn giản gồm các chữ số."},{"en":"The binary system uses only the digits zero and one.","vi":"Hệ nhị phân chỉ dùng hai chữ số là không và một."},{"en":"Students learn to convert numbers into the binary system.","vi":"Học sinh học cách chuyển đổi số sang hệ nhị phân."}]','[]',NULL,'/ˈbaɪnəri ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3431,'colloc-1-01',141,'biological evolution','tiến hóa sinh học','adj + n','[{"en":"Biological evolution explains how species change over many generations.","vi":"Tiến hóa sinh học giải thích cách các loài thay đổi qua nhiều thế hệ."},{"en":"The lecture covered the basic mechanisms of biological evolution.","vi":"Bài giảng trình bày các cơ chế cơ bản của tiến hóa sinh học."},{"en":"Fossils provide strong evidence for biological evolution over time.","vi":"Hóa thạch cung cấp bằng chứng mạnh mẽ cho tiến hóa sinh học theo thời gian."}]','[]',NULL,'/ˌbaɪəˈlɑːdʒɪkəl ˌevəˈluːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3432,'colloc-1-01',142,'biological science','khoa học sinh học','adj + n','[{"en":"Biological science has made remarkable progress in recent decades.","vi":"Khoa học sinh học đã đạt nhiều tiến bộ đáng kể trong những thập kỷ gần đây."},{"en":"She decided to major in biological science at university.","vi":"Cô quyết định học chuyên ngành khoa học sinh học ở đại học."},{"en":"Advances in biological science improve medicine and agriculture worldwide.","vi":"Tiến bộ trong khoa học sinh học cải thiện y học và nông nghiệp toàn cầu."}]','[]',NULL,'/ˌbaɪəˈlɑːdʒɪkəl ˈsaɪəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3433,'colloc-1-01',143,'biological sex','giới tính sinh học','adj + n','[{"en":"The study examined health differences related to biological sex.","vi":"Nghiên cứu khảo sát khác biệt về sức khỏe liên quan đến giới tính sinh học."},{"en":"Researchers distinguish biological sex from socially constructed gender roles.","vi":"Các nhà nghiên cứu phân biệt giới tính sinh học với vai trò giới do xã hội tạo nên."},{"en":"Some medical conditions are linked closely to biological sex.","vi":"Một số bệnh lý liên quan chặt chẽ đến giới tính sinh học."}]','[]',NULL,'/ˌbaɪəˈlɑːdʒɪkəl seks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3434,'colloc-1-01',144,'brief account','bản tường thuật ngắn gọn','adj + n','[{"en":"The article gives a brief account of the region''s history.","vi":"Bài viết đưa ra một bản tường thuật ngắn gọn về lịch sử của vùng."},{"en":"She wrote a brief account of the meeting for colleagues.","vi":"Cô viết một bản tường thuật ngắn gọn về cuộc họp cho đồng nghiệp."},{"en":"Please provide a brief account of what happened yesterday.","vi":"Vui lòng cung cấp một bản tường thuật ngắn gọn về việc xảy ra hôm qua."}]','[]',NULL,'/briːf əˈkaʊnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3435,'colloc-1-01',145,'brief description','mô tả ngắn gọn','adj + n','[{"en":"Each chapter begins with a brief description of its goals.","vi":"Mỗi chương bắt đầu với một mô tả ngắn gọn về mục tiêu của nó."},{"en":"The catalog includes a brief description of every product available.","vi":"Bản danh mục có một mô tả ngắn gọn về mọi sản phẩm hiện có."},{"en":"Write a brief description of yourself for the application form.","vi":"Hãy viết một mô tả ngắn gọn về bản thân cho mẫu đơn xin việc."}]','[]',NULL,'/briːf dɪˈskrɪpʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3436,'colloc-1-01',146,'brief discussion','cuộc thảo luận ngắn gọn','adj + n','[{"en":"After a brief discussion, the committee reached a final decision.","vi":"Sau một cuộc thảo luận ngắn gọn, ủy ban đã đi đến quyết định cuối cùng."},{"en":"The section ends with a brief discussion of future research.","vi":"Phần này kết thúc bằng một cuộc thảo luận ngắn gọn về nghiên cứu tương lai."},{"en":"We had a brief discussion about the changes before lunch.","vi":"Chúng tôi có một cuộc thảo luận ngắn gọn về các thay đổi trước bữa trưa."}]','[]',NULL,'/briːf dɪˈskʌʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3437,'colloc-1-01',147,'brief history','lịch sử tóm lược','adj + n','[{"en":"The book offers a brief history of modern computing technology.","vi":"Cuốn sách đưa ra một lịch sử tóm lược về công nghệ máy tính hiện đại."},{"en":"The lecture opened with a brief history of the company.","vi":"Bài giảng mở đầu bằng một lịch sử tóm lược về công ty."},{"en":"She gave a brief history of the town''s growth.","vi":"Cô trình bày một lịch sử tóm lược về sự phát triển của thị trấn."}]','[]',NULL,'/briːf ˈhɪstəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3438,'colloc-1-01',148,'brief introduction','phần giới thiệu ngắn gọn','adj + n','[{"en":"The speaker gave a brief introduction before starting the lecture.","vi":"Diễn giả có phần giới thiệu ngắn gọn trước khi bắt đầu bài giảng."},{"en":"This chapter provides a brief introduction to economic theory.","vi":"Chương này cung cấp một phần giới thiệu ngắn gọn về lý thuyết kinh tế."},{"en":"After a brief introduction, the workshop moved to practical tasks.","vi":"Sau phần giới thiệu ngắn gọn, buổi học chuyển sang các bài tập thực hành."}]','[]',NULL,'/briːf ˌɪntrəˈdʌkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3439,'colloc-1-01',149,'brief overview','cái nhìn tổng quan ngắn gọn','adj + n','[{"en":"The report begins with a brief overview of the findings.","vi":"Báo cáo mở đầu bằng một cái nhìn tổng quan ngắn gọn về các phát hiện."},{"en":"Let me give you a brief overview of today''s agenda.","vi":"Hãy để tôi đưa ra một cái nhìn tổng quan ngắn gọn về chương trình hôm nay."},{"en":"A brief overview helps new readers grasp the main ideas.","vi":"Một cái nhìn tổng quan ngắn gọn giúp người đọc mới nắm các ý chính."}]','[]',NULL,'/briːf ˈoʊvərˌvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3440,'colloc-1-01',150,'brief period','khoảng thời gian ngắn','adj + n','[{"en":"For a brief period, the factory stopped production entirely.","vi":"Trong một khoảng thời gian ngắn, nhà máy ngừng sản xuất hoàn toàn."},{"en":"She lived abroad for a brief period after graduation.","vi":"Cô sống ở nước ngoài trong một khoảng thời gian ngắn sau khi tốt nghiệp."},{"en":"Prices rose sharply during a brief period of shortage.","vi":"Giá tăng mạnh trong một khoảng thời gian ngắn khan hiếm."}]','[]',NULL,'/briːf ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3441,'colloc-2-01',1,'brief review','bản tổng quan ngắn gọn','adj + n','[{"en":"The paper opens with a brief review of earlier studies.","vi":"Bài báo mở đầu bằng một bản tổng quan ngắn gọn về các nghiên cứu trước."},{"en":"She wrote a brief review of the new economics textbook.","vi":"Cô viết một bản tổng quan ngắn gọn về cuốn giáo trình kinh tế mới."},{"en":"A brief review of the literature reveals several research gaps.","vi":"Một bản tổng quan ngắn gọn về tài liệu cho thấy vài khoảng trống nghiên cứu."}]','[]',NULL,'/briːf rɪˈvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3442,'colloc-2-01',2,'brief summary','bản tóm tắt ngắn gọn','adj + n','[{"en":"Please write a brief summary of the article''s main points.","vi":"Vui lòng viết một bản tóm tắt ngắn gọn về các ý chính của bài."},{"en":"The conclusion provides a brief summary of all the results.","vi":"Phần kết luận đưa ra một bản tóm tắt ngắn gọn về toàn bộ kết quả."},{"en":"He gave a brief summary before the meeting ended.","vi":"Anh đưa ra một bản tóm tắt ngắn gọn trước khi cuộc họp kết thúc."}]','[]',NULL,'/briːf ˈsʌməri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3443,'colloc-2-01',3,'brief time','thời gian ngắn ngủi','adj + n','[{"en":"In a brief time, the small startup grew enormously.","vi":"Trong một thời gian ngắn ngủi, công ty khởi nghiệp nhỏ đã lớn mạnh đáng kể."},{"en":"They achieved remarkable results in a surprisingly brief time.","vi":"Họ đạt được kết quả đáng kể trong một thời gian ngắn ngủi đáng ngạc nhiên."},{"en":"For a brief time, the two teams worked together closely.","vi":"Trong một thời gian ngắn ngủi, hai nhóm đã hợp tác chặt chẽ."}]','[]',NULL,'/briːf taɪm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3444,'colloc-2-01',4,'briefly describe','mô tả ngắn gọn','adv + v','[{"en":"Please briefly describe your previous experience in the field.","vi":"Vui lòng mô tả ngắn gọn kinh nghiệm trước đây của bạn trong lĩnh vực này."},{"en":"The author briefly describes the method used in the experiment.","vi":"Tác giả mô tả ngắn gọn phương pháp được dùng trong thí nghiệm."},{"en":"Can you briefly describe how the new system works?","vi":"Bạn có thể mô tả ngắn gọn cách hệ thống mới hoạt động không?"}]','[]',NULL,'/ˈbriːfli dɪˈskraɪb/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3445,'colloc-2-01',5,'briefly discuss','thảo luận ngắn gọn','adv + v','[{"en":"The essay will briefly discuss the causes of urban poverty.","vi":"Bài luận sẽ thảo luận ngắn gọn về nguyên nhân của nghèo đô thị."},{"en":"Let us briefly discuss the limitations of this approach.","vi":"Hãy thảo luận ngắn gọn về những hạn chế của cách tiếp cận này."},{"en":"The teacher asked students to briefly discuss the reading.","vi":"Giáo viên yêu cầu học sinh thảo luận ngắn gọn về bài đọc."}]','[]',NULL,'/ˈbriːfli dɪˈskʌs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3446,'colloc-2-01',6,'broad agreement','sự đồng thuận rộng rãi','adj + n','[{"en":"There is broad agreement that pollution harms public health.","vi":"Có sự đồng thuận rộng rãi rằng ô nhiễm gây hại cho sức khỏe cộng đồng."},{"en":"The delegates reached broad agreement on the main proposals.","vi":"Các đại biểu đạt được sự đồng thuận rộng rãi về các đề xuất chính."},{"en":"Despite some debate, broad agreement emerged among the experts.","vi":"Dù còn tranh luận, sự đồng thuận rộng rãi đã hình thành giữa các chuyên gia."}]','[]',NULL,'/brɔːd əˈɡriːmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3447,'colloc-2-01',7,'broad category','phạm trù rộng','adj + n','[{"en":"The survey divides respondents into a few broad categories.","vi":"Khảo sát chia người trả lời thành một vài phạm trù rộng."},{"en":"These problems fall within a broad category of social issues.","vi":"Những vấn đề này thuộc một phạm trù rộng về các vấn đề xã hội."},{"en":"Each broad category includes several more specific subgroups.","vi":"Mỗi phạm trù rộng bao gồm vài nhóm nhỏ cụ thể hơn."}]','[]',NULL,'/brɔːd ˈkætəɡɔːri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3448,'colloc-2-01',8,'broad definition','định nghĩa rộng','adj + n','[{"en":"The author uses a broad definition of the term culture.","vi":"Tác giả dùng một định nghĩa rộng cho thuật ngữ văn hóa."},{"en":"A broad definition allows the concept to cover many cases.","vi":"Một định nghĩa rộng cho phép khái niệm bao quát nhiều trường hợp."},{"en":"Critics argue that the broad definition is too vague.","vi":"Các nhà phê bình cho rằng định nghĩa rộng này quá mơ hồ."}]','[]',NULL,'/brɔːd ˌdefɪˈnɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3449,'colloc-2-01',9,'broad range of','phạm vi rộng','adj + n','[{"en":"The university offers a broad range of courses for students.","vi":"Trường đại học cung cấp một phạm vi rộng các khóa học cho sinh viên."},{"en":"The study covers a broad range of social and economic topics.","vi":"Nghiên cứu bao quát một phạm vi rộng các chủ đề xã hội và kinh tế."},{"en":"Her work appeals to a broad range of readers.","vi":"Tác phẩm của cô thu hút một phạm vi rộng độc giả."}]','[]',NULL,'/brɔːd reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3450,'colloc-2-01',10,'broad spectrum','phổ rộng','adj + n','[{"en":"The conference attracted a broad spectrum of industry professionals.","vi":"Hội nghị thu hút một phổ rộng các chuyên gia trong ngành."},{"en":"This medicine treats a broad spectrum of bacterial infections.","vi":"Loại thuốc này điều trị một phổ rộng các bệnh nhiễm khuẩn."},{"en":"Their policies appeal to a broad spectrum of voters.","vi":"Các chính sách của họ thu hút một phổ rộng cử tri."}]','[]',NULL,'/brɔːd ˈspektrəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3451,'colloc-2-01',11,'broader context','bối cảnh rộng hơn','adj + n','[{"en":"We must understand the event within its broader context.","vi":"Chúng ta phải hiểu sự kiện trong bối cảnh rộng hơn của nó."},{"en":"The author places the issue in a broader historical context.","vi":"Tác giả đặt vấn đề trong một bối cảnh lịch sử rộng hơn."},{"en":"Viewing data in a broader context reveals important patterns.","vi":"Nhìn dữ liệu trong bối cảnh rộng hơn làm lộ ra các quy luật quan trọng."}]','[]',NULL,'/ˈbrɔːdər ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3452,'colloc-2-01',12,'broadly defined','được định nghĩa một cách rộng rãi','adv + vpp','[{"en":"Health, broadly defined, includes physical, mental, and social wellbeing.","vi":"Sức khỏe, được định nghĩa rộng rãi, gồm thể chất, tinh thần và xã hội."},{"en":"The term, broadly defined, covers many different research areas.","vi":"Thuật ngữ này, được định nghĩa rộng rãi, bao quát nhiều lĩnh vực nghiên cứu."},{"en":"Culture is broadly defined as shared values and practices.","vi":"Văn hóa được định nghĩa rộng rãi là các giá trị và thực hành chung."}]','[]',NULL,'/ˈbrɔːdli dɪˈfaɪnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3453,'colloc-2-01',13,'broadly similar','tương tự về cơ bản','adv + adj','[{"en":"The two regions have broadly similar climates and economies.","vi":"Hai vùng có khí hậu và nền kinh tế tương tự về cơ bản."},{"en":"Results from both experiments were broadly similar overall.","vi":"Kết quả từ cả hai thí nghiệm về cơ bản là tương tự nhau."},{"en":"Although different in detail, the plans are broadly similar.","vi":"Dù khác nhau ở chi tiết, các kế hoạch về cơ bản là tương tự."}]','[]',NULL,'/ˈbrɔːdli ˈsɪmələr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3454,'colloc-2-01',14,'business sector','khu vực doanh nghiệp','n + n','[{"en":"The business sector plays a major role in the economy.","vi":"Khu vực doanh nghiệp đóng vai trò quan trọng trong nền kinh tế."},{"en":"Government policies strongly affect the entire business sector nationwide.","vi":"Các chính sách của chính phủ ảnh hưởng mạnh đến toàn bộ khu vực doanh nghiệp."},{"en":"New technology is reshaping the global business sector rapidly.","vi":"Công nghệ mới đang định hình lại khu vực doanh nghiệp toàn cầu nhanh chóng."}]','[]',NULL,'/ˈbɪznəs ˈsektər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3455,'colloc-2-01',15,'business transaction','giao dịch kinh doanh','n + n','[{"en":"Every business transaction should be recorded carefully for accounting.","vi":"Mỗi giao dịch kinh doanh nên được ghi chép cẩn thận cho kế toán."},{"en":"Online platforms make each business transaction faster and easier.","vi":"Các nền tảng trực tuyến giúp mỗi giao dịch kinh doanh nhanh và dễ hơn."},{"en":"Trust is essential in any successful business transaction between partners.","vi":"Niềm tin là điều thiết yếu trong mọi giao dịch kinh doanh thành công giữa các đối tác."}]','[]',NULL,'/ˈbɪznəs trænˈzækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3456,'colloc-2-01',16,'capitalist country','nước tư bản chủ nghĩa','adj + n','[{"en":"In a capitalist country, private businesses drive most economic growth.","vi":"Ở một nước tư bản, các doanh nghiệp tư nhân thúc đẩy phần lớn tăng trưởng kinh tế."},{"en":"The author compares living standards across several capitalist countries.","vi":"Tác giả so sánh mức sống giữa nhiều nước tư bản khác nhau."},{"en":"Many capitalist countries rely heavily on free-market competition.","vi":"Nhiều nước tư bản phụ thuộc nhiều vào cạnh tranh thị trường tự do."}]','[]',NULL,'/ˈkæpɪtəlɪst ˈkʌntri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3457,'colloc-2-01',17,'capitalist economy','nền kinh tế tư bản','adj + n','[{"en":"A capitalist economy lets supply and demand set most prices.","vi":"Một nền kinh tế tư bản để cung và cầu quyết định phần lớn giá cả."},{"en":"The lecture explained how a capitalist economy distributes resources.","vi":"Bài giảng giải thích cách nền kinh tế tư bản phân bổ nguồn lực."},{"en":"Inequality often grows quickly within an unregulated capitalist economy.","vi":"Bất bình đẳng thường tăng nhanh trong nền kinh tế tư bản thiếu kiểm soát."}]','[]',NULL,'/ˈkæpɪtəlɪst ɪˈkɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3458,'colloc-2-01',18,'capitalist society','xã hội tư bản','adj + n','[{"en":"In a capitalist society, success is often measured by wealth.","vi":"Trong xã hội tư bản, thành công thường được đo bằng của cải."},{"en":"The essay critiques class divisions found in capitalist society.","vi":"Bài luận phê phán sự phân chia giai cấp trong xã hội tư bản."},{"en":"Capitalist society rewards individual ambition more than collective effort.","vi":"Xã hội tư bản tưởng thưởng tham vọng cá nhân hơn nỗ lực tập thể."}]','[]',NULL,'/ˈkæpɪtəlɪst səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3459,'colloc-2-01',19,'capitalist system','hệ thống tư bản','adj + n','[{"en":"The capitalist system depends on private ownership and open markets.","vi":"Hệ thống tư bản dựa trên sở hữu tư nhân và thị trường mở."},{"en":"Critics argue the capitalist system concentrates power among the wealthy.","vi":"Người phê phán cho rằng hệ thống tư bản tập trung quyền lực vào người giàu."},{"en":"Reforms aim to soften the harsher effects of the capitalist system.","vi":"Các cải cách nhằm làm dịu những tác động khắc nghiệt của hệ thống tư bản."}]','[]',NULL,'/ˈkæpɪtəlɪst ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3460,'colloc-2-01',20,'capitalist world','thế giới tư bản','adj + n','[{"en":"Global trade ties most nations into one capitalist world.","vi":"Thương mại toàn cầu gắn hầu hết các quốc gia vào một thế giới tư bản."},{"en":"In the capitalist world, competition shapes nearly every industry.","vi":"Trong thế giới tư bản, cạnh tranh định hình gần như mọi ngành công nghiệp."},{"en":"The book traces how the capitalist world expanded after colonialism.","vi":"Cuốn sách lần theo cách thế giới tư bản mở rộng sau thời thuộc địa."}]','[]',NULL,'/ˈkæpɪtəlɪst wɜːrld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3461,'colloc-2-01',21,'career development','sự phát triển nghề nghiệp','n + n','[{"en":"The company invests in the career development of every employee.","vi":"Công ty đầu tư vào sự phát triển nghề nghiệp của từng nhân viên."},{"en":"Mentoring plays a key role in long-term career development.","vi":"Việc cố vấn đóng vai trò quan trọng trong phát triển nghề nghiệp lâu dài."},{"en":"Students attended a workshop focused on career development skills.","vi":"Sinh viên tham gia hội thảo tập trung vào kỹ năng phát triển nghề nghiệp."}]','[]',NULL,'/kəˈrɪr dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3462,'colloc-2-01',22,'career opportunity','cơ hội nghề nghiệp','n + n','[{"en":"Graduating abroad opened up a major career opportunity for her.","vi":"Tốt nghiệp ở nước ngoài đã mở ra một cơ hội nghề nghiệp lớn cho cô."},{"en":"The fair connected students with new career opportunities each year.","vi":"Hội chợ kết nối sinh viên với những cơ hội nghề nghiệp mới mỗi năm."},{"en":"He turned down a promising career opportunity to study further.","vi":"Anh từ chối một cơ hội nghề nghiệp hứa hẹn để học cao hơn."}]','[]',NULL,'/kəˈrɪr ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3463,'colloc-2-01',23,'careful analysis','sự phân tích cẩn thận','adj + n','[{"en":"Careful analysis of the data revealed an unexpected trend.","vi":"Sự phân tích cẩn thận dữ liệu đã cho thấy một xu hướng bất ngờ."},{"en":"The report draws its conclusions from careful analysis of records.","vi":"Báo cáo rút ra kết luận từ sự phân tích cẩn thận các hồ sơ."},{"en":"Only careful analysis can separate correlation from genuine causation.","vi":"Chỉ phân tích cẩn thận mới tách được tương quan khỏi nhân quả thực sự."}]','[]',NULL,'/ˈkerfəl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3464,'colloc-2-01',24,'careful attention','sự chú ý cẩn thận','adj + n','[{"en":"The experiment requires careful attention to every measurement.","vi":"Thí nghiệm đòi hỏi sự chú ý cẩn thận đến từng phép đo."},{"en":"She paid careful attention to the instructions before starting.","vi":"Cô chú ý cẩn thận đến hướng dẫn trước khi bắt đầu."},{"en":"Editing demands careful attention to grammar and tone.","vi":"Việc biên tập đòi hỏi sự chú ý cẩn thận đến ngữ pháp và giọng văn."}]','[]',NULL,'/ˈkerfəl əˈtenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3465,'colloc-2-01',25,'careful consideration','sự cân nhắc kỹ lưỡng','adj + n','[{"en":"The proposal deserves careful consideration before any decision is made.","vi":"Đề xuất xứng đáng được cân nhắc kỹ lưỡng trước khi đưa ra quyết định nào."},{"en":"After careful consideration, the committee approved the new policy.","vi":"Sau khi cân nhắc kỹ lưỡng, ủy ban đã phê duyệt chính sách mới."},{"en":"These risks warrant careful consideration by the whole research team.","vi":"Những rủi ro này đáng được cả nhóm nghiên cứu cân nhắc kỹ lưỡng."}]','[]',NULL,'/ˈkerfəl kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3466,'colloc-2-01',26,'careful thought','sự suy nghĩ thấu đáo','adj + n','[{"en":"The design clearly reflects careful thought about user needs.","vi":"Thiết kế rõ ràng phản ánh sự suy nghĩ thấu đáo về nhu cầu người dùng."},{"en":"Such a complex question demands careful thought, not quick answers.","vi":"Một câu hỏi phức tạp như vậy đòi hỏi suy nghĩ thấu đáo, không phải trả lời vội."},{"en":"After careful thought, she changed the structure of her essay.","vi":"Sau khi suy nghĩ thấu đáo, cô đã thay đổi cấu trúc bài luận."}]','[]',NULL,'/ˈkerfəl θɔːt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3467,'colloc-2-01',27,'carefully controlled','được kiểm soát cẩn thận','adv + vpp','[{"en":"The temperature was carefully controlled throughout the entire experiment.","vi":"Nhiệt độ được kiểm soát cẩn thận trong suốt toàn bộ thí nghiệm."},{"en":"Results are reliable because conditions were carefully controlled.","vi":"Kết quả đáng tin cậy vì các điều kiện được kiểm soát cẩn thận."},{"en":"In a carefully controlled trial, each variable is monitored closely.","vi":"Trong một thử nghiệm được kiểm soát cẩn thận, mỗi biến số được theo dõi sát."}]','[]',NULL,'/ˈkerfəli kənˈtroʊld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3468,'colloc-2-01',28,'carefully selected','được chọn lựa kỹ càng','adv + vpp','[{"en":"The participants were carefully selected to match the study criteria.","vi":"Những người tham gia được chọn lựa kỹ càng để phù hợp tiêu chí nghiên cứu."},{"en":"Each quotation in the book was carefully selected for relevance.","vi":"Mỗi trích dẫn trong sách đều được chọn lựa kỹ càng cho phù hợp."},{"en":"A carefully selected sample helps reduce bias in the findings.","vi":"Một mẫu được chọn lựa kỹ càng giúp giảm thiên lệch trong kết quả."}]','[]',NULL,'/ˈkerfəli sɪˈlektɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3469,'colloc-2-01',29,'carry information','truyền tải thông tin','v + n','[{"en":"Nerve cells carry information from the body to the brain.","vi":"Các tế bào thần kinh truyền tải thông tin từ cơ thể đến não."},{"en":"Fiber-optic cables carry information across continents in milliseconds.","vi":"Cáp quang truyền tải thông tin qua các châu lục chỉ trong vài mili giây."},{"en":"Genes carry information that determines an organism''s traits.","vi":"Gen mang thông tin quyết định các đặc điểm của một sinh vật."}]','[]',NULL,'/ˈkæri ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3470,'colloc-2-01',30,'carry out research of','tiến hành nghiên cứu về','v + n','[{"en":"The team will carry out research of marine ecosystems next summer.","vi":"Nhóm sẽ tiến hành nghiên cứu về hệ sinh thái biển vào mùa hè tới."},{"en":"Scientists carry out research of new materials in this lab.","vi":"Các nhà khoa học tiến hành nghiên cứu về vật liệu mới trong phòng thí nghiệm này."},{"en":"She received a grant to carry out research of rural education.","vi":"Cô nhận được tài trợ để tiến hành nghiên cứu về giáo dục nông thôn."}]','[]',NULL,'/ˈkæri aʊt ˈriːsɜːrtʃ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3471,'colloc-2-01',31,'carry out the task','thực hiện nhiệm vụ','v + n','[{"en":"The students worked together to carry out the task efficiently.","vi":"Các sinh viên cùng nhau thực hiện nhiệm vụ một cách hiệu quả."},{"en":"He needed clear instructions before he could carry out the task.","vi":"Anh cần hướng dẫn rõ ràng trước khi có thể thực hiện nhiệm vụ."},{"en":"The robot was programmed to carry out the task automatically.","vi":"Robot được lập trình để thực hiện nhiệm vụ một cách tự động."}]','[]',NULL,'/ˈkæri aʊt ðə tæsk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3472,'colloc-2-01',32,'cast doubt on','gây nghi ngờ về','v + n','[{"en":"New evidence cast doubt on the original conclusions of the study.","vi":"Bằng chứng mới đã gây nghi ngờ về các kết luận ban đầu của nghiên cứu."},{"en":"Critics cast doubt on the reliability of the survey results.","vi":"Người phê phán gây nghi ngờ về độ tin cậy của kết quả khảo sát."},{"en":"The contradiction casts doubt on his entire argument.","vi":"Sự mâu thuẫn này gây nghi ngờ về toàn bộ lập luận của anh."}]','[]',NULL,'/kæst daʊt ɑːn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3473,'colloc-2-01',33,'causal link','mối liên hệ nhân quả','adj + n','[{"en":"Researchers found a causal link between smoking and lung disease.","vi":"Các nhà nghiên cứu tìm thấy mối liên hệ nhân quả giữa hút thuốc và bệnh phổi."},{"en":"Correlation alone does not prove a true causal link.","vi":"Chỉ riêng tương quan không chứng minh được mối liên hệ nhân quả thực sự."},{"en":"The study failed to establish any clear causal link.","vi":"Nghiên cứu không thiết lập được mối liên hệ nhân quả rõ ràng nào."}]','[]',NULL,'/ˈkɔːzəl lɪŋk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3474,'colloc-2-01',34,'causal relation','quan hệ nhân quả','adj + n','[{"en":"Philosophers have long debated the nature of causal relation.","vi":"Các nhà triết học từ lâu đã tranh luận về bản chất của quan hệ nhân quả."},{"en":"The data suggest a causal relation between income and health.","vi":"Dữ liệu gợi ý một quan hệ nhân quả giữa thu nhập và sức khỏe."},{"en":"Establishing a causal relation requires controlled experiments.","vi":"Thiết lập một quan hệ nhân quả đòi hỏi các thí nghiệm có kiểm soát."}]','[]',NULL,'/ˈkɔːzəl rɪˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3475,'colloc-2-01',35,'causal relationship','mối quan hệ nhân quả','adj + n','[{"en":"The experiment confirmed a causal relationship between diet and weight.","vi":"Thí nghiệm xác nhận một mối quan hệ nhân quả giữa chế độ ăn và cân nặng."},{"en":"It is hard to prove a causal relationship in social science.","vi":"Rất khó chứng minh một mối quan hệ nhân quả trong khoa học xã hội."},{"en":"They tested whether a causal relationship existed between the two factors.","vi":"Họ kiểm tra xem có mối quan hệ nhân quả giữa hai yếu tố hay không."}]','[]',NULL,'/ˈkɔːzəl rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3476,'colloc-2-01',36,'cause consequences','gây ra hậu quả','v + n','[{"en":"Careless decisions can cause consequences that last for years.","vi":"Những quyết định cẩu thả có thể gây ra hậu quả kéo dài nhiều năm."},{"en":"Pollution causes consequences far beyond the local area.","vi":"Ô nhiễm gây ra hậu quả vượt xa khu vực địa phương."},{"en":"Ignoring the warnings may cause serious consequences later.","vi":"Bỏ qua những cảnh báo có thể gây ra hậu quả nghiêm trọng về sau."}]','[]',NULL,'/kɔːz ˈkɑːnsɪkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3477,'colloc-2-01',37,'cause stress','gây căng thẳng','v + n','[{"en":"Tight deadlines often cause stress for many students.","vi":"Những hạn chót gấp gáp thường gây căng thẳng cho nhiều sinh viên."},{"en":"Financial pressure can cause stress that affects physical health.","vi":"Áp lực tài chính có thể gây căng thẳng ảnh hưởng đến sức khỏe thể chất."},{"en":"Loud, crowded environments tend to cause stress over time.","vi":"Môi trường ồn ào, đông đúc có xu hướng gây căng thẳng theo thời gian."}]','[]',NULL,'/kɔːz stres/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3478,'colloc-2-01',38,'central authority','cơ quan trung ương','adj + n','[{"en":"A strong central authority coordinated the country''s emergency response.","vi":"Một cơ quan trung ương mạnh đã điều phối ứng phó khẩn cấp của cả nước."},{"en":"Without a central authority, the regions made conflicting decisions.","vi":"Không có cơ quan trung ương, các vùng đưa ra những quyết định mâu thuẫn."},{"en":"The central authority sets standards that local offices must follow.","vi":"Cơ quan trung ương đặt ra các tiêu chuẩn mà văn phòng địa phương phải tuân theo."}]','[]',NULL,'/ˈsentrəl əˈθɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3479,'colloc-2-01',39,'central concept','khái niệm trung tâm','adj + n','[{"en":"Supply and demand is a central concept in economics.","vi":"Cung và cầu là một khái niệm trung tâm trong kinh tế học."},{"en":"The lecture introduced the central concept of natural selection.","vi":"Bài giảng giới thiệu khái niệm trung tâm về chọn lọc tự nhiên."},{"en":"Understanding this central concept makes the rest of the theory clearer.","vi":"Hiểu khái niệm trung tâm này khiến phần còn lại của lý thuyết rõ ràng hơn."}]','[]',NULL,'/ˈsentrəl ˈkɑːnsept/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3480,'colloc-2-01',40,'central concern','mối quan tâm chính','adj + n','[{"en":"Student safety is a central concern for the whole university.","vi":"An toàn của sinh viên là mối quan tâm chính của toàn trường đại học."},{"en":"Fairness remained the central concern throughout the policy debate.","vi":"Sự công bằng vẫn là mối quan tâm chính trong suốt cuộc tranh luận chính sách."},{"en":"Data privacy has become a central concern in modern research.","vi":"Quyền riêng tư dữ liệu đã trở thành mối quan tâm chính trong nghiên cứu hiện đại."}]','[]',NULL,'/ˈsentrəl kənˈsɜːrn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3481,'colloc-2-01',41,'central control','sự kiểm soát tập trung','adj + n','[{"en":"The system relies on central control to keep operations consistent.","vi":"Hệ thống dựa vào sự kiểm soát tập trung để giữ hoạt động nhất quán."},{"en":"Too much central control can slow down local decision-making.","vi":"Sự kiểm soát tập trung quá mức có thể làm chậm việc ra quyết định địa phương."},{"en":"The reform reduced central control and gave regions more freedom.","vi":"Cuộc cải cách giảm sự kiểm soát tập trung và cho các vùng nhiều tự do hơn."}]','[]',NULL,'/ˈsentrəl kənˈtroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3482,'colloc-2-01',42,'central core','lõi trung tâm','adj + n','[{"en":"Honesty forms the central core of his entire argument.","vi":"Sự trung thực tạo thành lõi trung tâm của toàn bộ lập luận của anh."},{"en":"The central core of the planet remains extremely hot.","vi":"Lõi trung tâm của hành tinh vẫn còn cực kỳ nóng."},{"en":"These principles make up the central core of the curriculum.","vi":"Những nguyên tắc này tạo nên lõi trung tâm của chương trình học."}]','[]',NULL,'/ˈsentrəl kɔːr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3483,'colloc-2-01',43,'central feature','đặc điểm trung tâm','adj + n','[{"en":"Repetition is a central feature of the author''s writing style.","vi":"Sự lặp lại là một đặc điểm trung tâm trong phong cách viết của tác giả."},{"en":"Collaboration became the central feature of the new program.","vi":"Sự hợp tác trở thành đặc điểm trung tâm của chương trình mới."},{"en":"Open courtyards are a central feature of traditional architecture.","vi":"Sân trong rộng mở là một đặc điểm trung tâm của kiến trúc truyền thống."}]','[]',NULL,'/ˈsentrəl ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3484,'colloc-2-01',44,'central focus','trọng tâm chính','adj + n','[{"en":"Climate change is the central focus of this year''s conference.","vi":"Biến đổi khí hậu là trọng tâm chính của hội nghị năm nay."},{"en":"The central focus of her thesis is childhood language development.","vi":"Trọng tâm chính của luận văn cô là sự phát triển ngôn ngữ ở trẻ em."},{"en":"Student wellbeing should be the central focus of any school.","vi":"Sự khỏe mạnh của học sinh nên là trọng tâm chính của mọi trường học."}]','[]',NULL,'/ˈsentrəl ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3485,'colloc-2-01',45,'central government','chính quyền trung ương','adj + n','[{"en":"The central government allocated extra funding to rural schools.","vi":"Chính quyền trung ương phân bổ thêm ngân sách cho các trường nông thôn."},{"en":"Local councils often clash with the central government over budgets.","vi":"Hội đồng địa phương thường xung đột với chính quyền trung ương về ngân sách."},{"en":"The central government sets national policies on education and health.","vi":"Chính quyền trung ương đặt ra chính sách quốc gia về giáo dục và y tế."}]','[]',NULL,'/ˈsentrəl ˈɡʌvərnmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3486,'colloc-2-01',46,'central importance','tầm quan trọng cốt lõi','adj + n','[{"en":"Clean water is of central importance to public health.","vi":"Nước sạch có tầm quan trọng cốt lõi đối với sức khỏe cộng đồng."},{"en":"The author stresses the central importance of historical context.","vi":"Tác giả nhấn mạnh tầm quan trọng cốt lõi của bối cảnh lịch sử."},{"en":"Trust is of central importance in any working relationship.","vi":"Sự tin tưởng có tầm quan trọng cốt lõi trong bất kỳ mối quan hệ làm việc nào."}]','[]',NULL,'/ˈsentrəl ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3487,'colloc-2-01',47,'central issue','vấn đề trung tâm','adj + n','[{"en":"The central issue of the debate was access to healthcare.","vi":"Vấn đề trung tâm của cuộc tranh luận là khả năng tiếp cận y tế."},{"en":"Funding remains the central issue facing the research department.","vi":"Ngân sách vẫn là vấn đề trung tâm mà khoa nghiên cứu đối mặt."},{"en":"We must address the central issue before discussing minor details.","vi":"Chúng ta phải giải quyết vấn đề trung tâm trước khi bàn các chi tiết nhỏ."}]','[]',NULL,'/ˈsentrəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3488,'colloc-2-01',48,'central part','phần trung tâm','adj + n','[{"en":"Fieldwork forms the central part of this geography course.","vi":"Thực địa tạo thành phần trung tâm của khóa học địa lý này."},{"en":"The market sits in the central part of the old city.","vi":"Khu chợ nằm ở phần trung tâm của thành phố cổ."},{"en":"Reflection is a central part of effective learning.","vi":"Sự suy ngẫm là một phần trung tâm của việc học hiệu quả."}]','[]',NULL,'/ˈsentrəl pɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3489,'colloc-2-01',49,'central point','luận điểm trung tâm','adj + n','[{"en":"The central point of her argument is often overlooked.","vi":"Luận điểm trung tâm trong lập luận của cô thường bị bỏ qua."},{"en":"Let me restate the central point so it stays clear.","vi":"Để mình nhắc lại luận điểm trung tâm để nó luôn rõ ràng."},{"en":"Every paragraph should support the essay''s central point.","vi":"Mỗi đoạn văn nên hỗ trợ cho luận điểm trung tâm của bài luận."}]','[]',NULL,'/ˈsentrəl pɔɪnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3490,'colloc-2-01',50,'central position','vị trí trung tâm','adj + n','[{"en":"The theory holds a central position in modern psychology.","vi":"Lý thuyết này giữ một vị trí trung tâm trong tâm lý học hiện đại."},{"en":"Her central position in the team gave her real influence.","vi":"Vị trí trung tâm của cô trong nhóm mang lại cho cô ảnh hưởng thực sự."},{"en":"The city''s central position made it a key trading hub.","vi":"Vị trí trung tâm của thành phố khiến nó thành một trung tâm thương mại quan trọng."}]','[]',NULL,'/ˈsentrəl pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3491,'colloc-2-01',51,'central problem','vấn đề cốt lõi','adj + n','[{"en":"The central problem is a lack of reliable, recent data.","vi":"Vấn đề cốt lõi là thiếu dữ liệu đáng tin cậy và mới."},{"en":"Her paper identifies the central problem facing urban planners.","vi":"Bài viết của cô xác định vấn đề cốt lõi mà các nhà quy hoạch đô thị gặp phải."},{"en":"Solving the central problem will resolve many smaller difficulties.","vi":"Giải quyết vấn đề cốt lõi sẽ tháo gỡ nhiều khó khăn nhỏ hơn."}]','[]',NULL,'/ˈsentrəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3492,'colloc-2-01',52,'central question','câu hỏi trung tâm','adj + n','[{"en":"The central question of the study concerns memory and aging.","vi":"Câu hỏi trung tâm của nghiên cứu liên quan đến trí nhớ và lão hóa."},{"en":"A clear central question keeps the research focused.","vi":"Một câu hỏi trung tâm rõ ràng giữ cho nghiên cứu tập trung."},{"en":"The seminar revolved around one central question about justice.","vi":"Buổi hội thảo xoay quanh một câu hỏi trung tâm về công lý."}]','[]',NULL,'/ˈsentrəl ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3493,'colloc-2-01',53,'central role','vai trò trung tâm','adj + n','[{"en":"Technology plays a central role in modern education.","vi":"Công nghệ đóng một vai trò trung tâm trong giáo dục hiện đại."},{"en":"She played a central role in organizing the conference.","vi":"Cô đóng vai trò trung tâm trong việc tổ chức hội nghị."},{"en":"Trust plays a central role in successful teamwork.","vi":"Sự tin tưởng đóng vai trò trung tâm trong làm việc nhóm thành công."}]','[]',NULL,'/ˈsentrəl roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3494,'colloc-2-01',54,'central tenet','nguyên lý cốt lõi','adj + n','[{"en":"Equality is a central tenet of democratic society.","vi":"Bình đẳng là một nguyên lý cốt lõi của xã hội dân chủ."},{"en":"The central tenet of his philosophy is personal responsibility.","vi":"Nguyên lý cốt lõi trong triết lý của ông là trách nhiệm cá nhân."},{"en":"Respect for evidence is a central tenet of science.","vi":"Tôn trọng bằng chứng là một nguyên lý cốt lõi của khoa học."}]','[]',NULL,'/ˈsentrəl ˈtenət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3495,'colloc-2-01',55,'central theme','chủ đề trung tâm','adj + n','[{"en":"Identity is the central theme of the entire novel.","vi":"Bản sắc là chủ đề trung tâm của toàn bộ cuốn tiểu thuyết."},{"en":"The central theme of the lecture was sustainable development.","vi":"Chủ đề trung tâm của bài giảng là phát triển bền vững."},{"en":"Loss runs as a central theme through her poetry.","vi":"Mất mát là chủ đề trung tâm xuyên suốt thơ của cô."}]','[]',NULL,'/ˈsentrəl θiːm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3496,'colloc-2-01',56,'central aspect','khía cạnh trung tâm','adj + n','[{"en":"Communication is a central aspect of effective leadership.","vi":"Giao tiếp là một khía cạnh trung tâm của khả năng lãnh đạo hiệu quả."},{"en":"The central aspect of the design is its flexibility.","vi":"Khía cạnh trung tâm của thiết kế là tính linh hoạt của nó."},{"en":"Motivation remains a central aspect of student success.","vi":"Động lực vẫn là một khía cạnh trung tâm của thành công học tập."}]','[]',NULL,'/ˈsentrəl ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3497,'colloc-2-01',57,'central assumptions','giả định cốt lõi','adj + n','[{"en":"The model rests on several central assumptions about human behavior.","vi":"Mô hình dựa trên một số giả định cốt lõi về hành vi con người."},{"en":"Critics questioned the central assumptions behind the forecast.","vi":"Người phê phán nghi ngờ những giả định cốt lõi đằng sau dự báo."},{"en":"If the central assumptions are wrong, the conclusions collapse.","vi":"Nếu các giả định cốt lõi sai, các kết luận sẽ sụp đổ."}]','[]',NULL,'/ˈsentrəl əˈsʌmpʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3498,'colloc-2-01',58,'central characteristics','đặc trưng cốt lõi','adj + n','[{"en":"The report lists the central characteristics of a healthy ecosystem.","vi":"Báo cáo liệt kê các đặc trưng cốt lõi của một hệ sinh thái khỏe mạnh."},{"en":"Flexibility and curiosity are central characteristics of good researchers.","vi":"Linh hoạt và tò mò là những đặc trưng cốt lõi của nhà nghiên cứu giỏi."},{"en":"These central characteristics distinguish one species from another.","vi":"Những đặc trưng cốt lõi này phân biệt loài này với loài khác."}]','[]',NULL,'/ˈsentrəl ˌkærəktəˈrɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3499,'colloc-2-01',59,'central circumstances','hoàn cảnh cốt lõi','adj + n','[{"en":"The court examined the central circumstances surrounding the dispute.","vi":"Tòa án xem xét các hoàn cảnh cốt lõi xoay quanh vụ tranh chấp."},{"en":"Understanding the central circumstances helps explain the decision.","vi":"Hiểu các hoàn cảnh cốt lõi giúp giải thích quyết định đó."},{"en":"Her analysis focuses on the central circumstances of the conflict.","vi":"Phân tích của cô tập trung vào các hoàn cảnh cốt lõi của cuộc xung đột."}]','[]',NULL,'/ˈsentrəl ˈsɜːrkəmstænsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3500,'colloc-2-01',60,'change constantly','thay đổi liên tục','v + adv','[{"en":"Market prices change constantly in response to global events.","vi":"Giá thị trường thay đổi liên tục để phản ứng với các sự kiện toàn cầu."},{"en":"Languages change constantly as new words enter everyday use.","vi":"Ngôn ngữ thay đổi liên tục khi những từ mới đi vào sử dụng hàng ngày."},{"en":"Weather patterns change constantly, making forecasts difficult.","vi":"Các kiểu thời tiết thay đổi liên tục, khiến việc dự báo trở nên khó khăn."}]','[]',NULL,'/tʃeɪndʒ ˈkɑːnstəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3501,'colloc-2-01',61,'change dramatically','thay đổi mạnh mẽ','v + adv','[{"en":"Attitudes toward technology have changed dramatically over a decade.","vi":"Thái độ đối với công nghệ đã thay đổi mạnh mẽ trong một thập kỷ."},{"en":"The landscape can change dramatically after a single flood.","vi":"Cảnh quan có thể thay đổi mạnh mẽ chỉ sau một trận lũ."},{"en":"Her writing style changed dramatically between the two novels.","vi":"Phong cách viết của cô thay đổi mạnh mẽ giữa hai cuốn tiểu thuyết."}]','[]',NULL,'/tʃeɪndʒ drəˈmætɪkli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3502,'colloc-2-01',62,'change rapidly','thay đổi nhanh chóng','v + adv','[{"en":"Digital technology continues to change rapidly every year.","vi":"Công nghệ số tiếp tục thay đổi nhanh chóng mỗi năm."},{"en":"Consumer habits can change rapidly during an economic crisis.","vi":"Thói quen tiêu dùng có thể thay đổi nhanh chóng trong khủng hoảng kinh tế."},{"en":"Cities change rapidly when populations grow without planning.","vi":"Các thành phố thay đổi nhanh chóng khi dân số tăng mà thiếu quy hoạch."}]','[]',NULL,'/tʃeɪndʒ ˈræpɪdli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3503,'colloc-2-01',63,'change an attitude','thay đổi thái độ','v + n','[{"en":"A single experience can change an attitude that lasted for years.","vi":"Một trải nghiệm duy nhất có thể thay đổi thái độ đã tồn tại nhiều năm."},{"en":"Good teachers know how to change an attitude through encouragement.","vi":"Giáo viên giỏi biết cách thay đổi thái độ thông qua sự khích lệ."},{"en":"Campaigns try to change an attitude toward recycling.","vi":"Các chiến dịch cố gắng thay đổi thái độ đối với việc tái chế."}]','[]',NULL,'/tʃeɪndʒ ən ˈætɪtuːd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3504,'colloc-2-01',64,'changing attitudes','những thái độ đang thay đổi','adj + n','[{"en":"The survey tracks changing attitudes toward remote work.","vi":"Cuộc khảo sát theo dõi những thái độ đang thay đổi về làm việc từ xa."},{"en":"Changing attitudes about diet have reshaped the food industry.","vi":"Những thái độ đang thay đổi về ăn uống đã định hình lại ngành thực phẩm."},{"en":"Advertisers must respond to changing attitudes among young consumers.","vi":"Nhà quảng cáo phải đáp ứng những thái độ đang thay đổi của người tiêu dùng trẻ."}]','[]',NULL,'/ˈtʃeɪndʒɪŋ ˈætɪtuːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3505,'colloc-2-01',65,'changing circumstances','hoàn cảnh thay đổi','adj + n','[{"en":"Successful businesses adapt quickly to changing circumstances.","vi":"Doanh nghiệp thành công thích nghi nhanh với hoàn cảnh thay đổi."},{"en":"The plan was flexible enough to handle changing circumstances.","vi":"Kế hoạch đủ linh hoạt để ứng phó với hoàn cảnh thay đổi."},{"en":"Leaders must make decisions under constantly changing circumstances.","vi":"Người lãnh đạo phải ra quyết định trong hoàn cảnh thay đổi liên tục."}]','[]',NULL,'/ˈtʃeɪndʒɪŋ ˈsɜːrkəmstænsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3506,'colloc-2-01',66,'changing nature','bản chất thay đổi','adj + n','[{"en":"The book explores the changing nature of modern families.","vi":"Cuốn sách khám phá bản chất thay đổi của gia đình hiện đại."},{"en":"Researchers study the changing nature of work in a digital age.","vi":"Các nhà nghiên cứu nghiên cứu bản chất thay đổi của công việc trong thời đại số."},{"en":"We must understand the changing nature of global trade.","vi":"Chúng ta phải hiểu bản chất thay đổi của thương mại toàn cầu."}]','[]',NULL,'/ˈtʃeɪndʒɪŋ ˈneɪtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3507,'colloc-2-01',67,'changing needs','nhu cầu thay đổi','adj + n','[{"en":"The curriculum is updated to meet students'' changing needs.","vi":"Chương trình học được cập nhật để đáp ứng nhu cầu thay đổi của sinh viên."},{"en":"Hospitals must adapt services to the changing needs of patients.","vi":"Bệnh viện phải điều chỉnh dịch vụ theo nhu cầu thay đổi của bệnh nhân."},{"en":"Good design anticipates the changing needs of its users.","vi":"Thiết kế tốt dự đoán được nhu cầu thay đổi của người dùng."}]','[]',NULL,'/ˈtʃeɪndʒɪŋ niːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3508,'colloc-2-01',68,'changing pattern','khuôn mẫu thay đổi','adj + n','[{"en":"The data show a changing pattern of migration across the region.","vi":"Dữ liệu cho thấy một khuôn mẫu di cư đang thay đổi trong khu vực."},{"en":"Scientists noticed a changing pattern in seasonal rainfall.","vi":"Các nhà khoa học nhận thấy một khuôn mẫu thay đổi trong lượng mưa theo mùa."},{"en":"The changing pattern of consumption reflects new lifestyles.","vi":"Khuôn mẫu tiêu dùng đang thay đổi phản ánh những lối sống mới."}]','[]',NULL,'/ˈtʃeɪndʒɪŋ ˈpætərn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3509,'colloc-2-01',69,'changing world','thế giới đang thay đổi','adj + n','[{"en":"Education must prepare young people for a changing world.","vi":"Giáo dục phải chuẩn bị cho người trẻ bước vào một thế giới đang thay đổi."},{"en":"Businesses that ignore a changing world rarely survive long.","vi":"Doanh nghiệp bỏ qua một thế giới đang thay đổi hiếm khi tồn tại lâu."},{"en":"In a rapidly changing world, lifelong learning is essential.","vi":"Trong một thế giới thay đổi nhanh, học tập suốt đời là điều thiết yếu."}]','[]',NULL,'/ˈtʃeɪndʒɪŋ wɜːrld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3510,'colloc-2-01',70,'characteristic feature','đặc điểm đặc trưng','adj + n','[{"en":"Steep roofs are a characteristic feature of alpine houses.","vi":"Mái dốc là một đặc điểm đặc trưng của những ngôi nhà vùng núi cao."},{"en":"Irony is a characteristic feature of the writer''s later work.","vi":"Sự châm biếm là một đặc điểm đặc trưng trong tác phẩm sau này của nhà văn."},{"en":"A characteristic feature of the disease is sudden fatigue.","vi":"Một đặc điểm đặc trưng của căn bệnh là sự mệt mỏi đột ngột."}]','[]',NULL,'/ˌkærəktəˈrɪstɪk ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3511,'colloc-2-01',71,'chemical reaction','phản ứng hóa học','adj + n','[{"en":"Mixing the two liquids triggered a violent chemical reaction.","vi":"Trộn hai chất lỏng đã kích hoạt một phản ứng hóa học dữ dội."},{"en":"Heat often speeds up the rate of a chemical reaction.","vi":"Nhiệt thường làm tăng tốc độ của một phản ứng hóa học."},{"en":"Photosynthesis is a chemical reaction that produces oxygen.","vi":"Quang hợp là một phản ứng hóa học tạo ra oxy."}]','[]',NULL,'/ˈkemɪkəl riˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3512,'colloc-2-01',72,'civil case','vụ án dân sự','adj + n','[{"en":"A civil case usually involves disputes over money or property.","vi":"Một vụ án dân sự thường liên quan đến tranh chấp về tiền hoặc tài sản."},{"en":"Unlike criminal trials, a civil case rarely leads to prison.","vi":"Khác với án hình sự, một vụ án dân sự hiếm khi dẫn đến tù giam."},{"en":"The lawyer specialized in complex civil cases for businesses.","vi":"Luật sư chuyên về các vụ án dân sự phức tạp cho doanh nghiệp."}]','[]',NULL,'/ˈsɪvəl keɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3513,'colloc-2-01',73,'civil society','xã hội dân sự','adj + n','[{"en":"A strong civil society helps hold governments accountable.","vi":"Một xã hội dân sự mạnh giúp buộc chính phủ phải có trách nhiệm."},{"en":"Charities and unions are important parts of civil society.","vi":"Các tổ chức từ thiện và công đoàn là phần quan trọng của xã hội dân sự."},{"en":"The essay examines the role of civil society in reform.","vi":"Bài luận xem xét vai trò của xã hội dân sự trong cải cách."}]','[]',NULL,'/ˈsɪvəl səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3514,'colloc-2-01',74,'class consciousness','ý thức giai cấp','n + n','[{"en":"Marx argued that class consciousness drives social change.","vi":"Marx lập luận rằng ý thức giai cấp thúc đẩy thay đổi xã hội."},{"en":"The strike reflected a growing sense of class consciousness.","vi":"Cuộc đình công phản ánh một ý thức giai cấp ngày càng tăng."},{"en":"The novel explores class consciousness among factory workers.","vi":"Cuốn tiểu thuyết khám phá ý thức giai cấp trong giới công nhân nhà máy."}]','[]',NULL,'/klæs ˈkɑːnʃəsnəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3515,'colloc-2-01',75,'classic example','ví dụ điển hình','adj + n','[{"en":"This experiment is a classic example of scientific method.","vi":"Thí nghiệm này là một ví dụ điển hình về phương pháp khoa học."},{"en":"Her speech offers a classic example of persuasive writing.","vi":"Bài phát biểu của cô là một ví dụ điển hình về văn thuyết phục."},{"en":"The case is a classic example of how markets fail.","vi":"Vụ việc là một ví dụ điển hình về cách thị trường thất bại."}]','[]',NULL,'/ˈklæsɪk ɪɡˈzæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3516,'colloc-2-01',76,'classic study','nghiên cứu kinh điển','adj + n','[{"en":"The lecture referred to a classic study on human memory.","vi":"Bài giảng nhắc đến một nghiên cứu kinh điển về trí nhớ con người."},{"en":"This classic study still shapes how psychologists view obedience.","vi":"Nghiên cứu kinh điển này vẫn định hình cách nhà tâm lý nhìn nhận sự phục tùng."},{"en":"Many textbooks cite this classic study as foundational.","vi":"Nhiều sách giáo khoa trích dẫn nghiên cứu kinh điển này như nền tảng."}]','[]',NULL,'/ˈklæsɪk ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3517,'colloc-2-01',77,'classic text','văn bản kinh điển','adj + n','[{"en":"Students are required to read this classic text on ethics.","vi":"Sinh viên được yêu cầu đọc văn bản kinh điển này về đạo đức học."},{"en":"The classic text remains relevant to debates today.","vi":"Văn bản kinh điển này vẫn còn phù hợp với các tranh luận ngày nay."},{"en":"Every law student encounters this classic text early on.","vi":"Mọi sinh viên luật đều tiếp xúc văn bản kinh điển này từ sớm."}]','[]',NULL,'/ˈklæsɪk tekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3518,'colloc-2-01',78,'classic work','tác phẩm kinh điển','adj + n','[{"en":"This classic work influenced generations of economists.","vi":"Tác phẩm kinh điển này đã ảnh hưởng đến nhiều thế hệ nhà kinh tế."},{"en":"The professor recommended a classic work on political theory.","vi":"Giáo sư giới thiệu một tác phẩm kinh điển về lý thuyết chính trị."},{"en":"Few classic works are read as widely as this one.","vi":"Ít tác phẩm kinh điển nào được đọc rộng rãi như cuốn này."}]','[]',NULL,'/ˈklæsɪk wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3519,'colloc-2-01',79,'classical theory','lý thuyết cổ điển','adj + n','[{"en":"Classical theory assumes that markets always reach equilibrium.","vi":"Lý thuyết cổ điển giả định rằng thị trường luôn đạt đến cân bằng."},{"en":"Modern research often challenges aspects of classical theory.","vi":"Nghiên cứu hiện đại thường thách thức nhiều khía cạnh của lý thuyết cổ điển."},{"en":"The course compares classical theory with newer approaches.","vi":"Khóa học so sánh lý thuyết cổ điển với các cách tiếp cận mới hơn."}]','[]',NULL,'/ˈklæsɪkəl ˈθɪri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3520,'colloc-2-01',80,'clear boundary','ranh giới rõ ràng','adj + n','[{"en":"There is no clear boundary between the two disciplines.","vi":"Không có ranh giới rõ ràng giữa hai ngành học này."},{"en":"The fence marks a clear boundary between the properties.","vi":"Hàng rào đánh dấu một ranh giới rõ ràng giữa các khu đất."},{"en":"Good managers set a clear boundary between work and rest.","vi":"Người quản lý giỏi đặt ranh giới rõ ràng giữa công việc và nghỉ ngơi."}]','[]',NULL,'/klɪr ˈbaʊndri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3521,'colloc-2-01',81,'clear distinction','sự phân biệt rõ ràng','adj + n','[{"en":"The author draws a clear distinction between fact and opinion.","vi":"Tác giả phân biệt rõ ràng giữa sự thật và ý kiến."},{"en":"There is a clear distinction between weather and climate.","vi":"Có một sự phân biệt rõ ràng giữa thời tiết và khí hậu."},{"en":"We must make a clear distinction between cause and effect.","vi":"Chúng ta phải phân biệt rõ ràng giữa nguyên nhân và kết quả."}]','[]',NULL,'/klɪr dɪˈstɪŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3522,'colloc-2-01',82,'clear evidence','bằng chứng rõ ràng','adj + n','[{"en":"The study provides clear evidence of rising sea levels.","vi":"Nghiên cứu cung cấp bằng chứng rõ ràng về mực nước biển dâng."},{"en":"There is clear evidence that exercise improves mental health.","vi":"Có bằng chứng rõ ràng rằng tập thể dục cải thiện sức khỏe tinh thần."},{"en":"Without clear evidence, the claim remains unconvincing.","vi":"Không có bằng chứng rõ ràng, lời tuyên bố vẫn thiếu thuyết phục."}]','[]',NULL,'/klɪr ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3523,'colloc-2-01',83,'clear focus','trọng tâm rõ ràng','adj + n','[{"en":"A good essay needs a clear focus from the start.","vi":"Một bài luận hay cần có trọng tâm rõ ràng ngay từ đầu."},{"en":"The project succeeded because the team kept a clear focus.","vi":"Dự án thành công vì cả nhóm giữ được một trọng tâm rõ ràng."},{"en":"Without a clear focus, the research became scattered.","vi":"Không có trọng tâm rõ ràng, nghiên cứu trở nên rời rạc."}]','[]',NULL,'/klɪr ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3524,'colloc-2-01',84,'clear indication','dấu hiệu rõ ràng','adj + n','[{"en":"Rising temperatures are a clear indication of climate change.","vi":"Nhiệt độ tăng là một dấu hiệu rõ ràng của biến đổi khí hậu."},{"en":"Her quick reply was a clear indication of her interest.","vi":"Câu trả lời nhanh của cô là một dấu hiệu rõ ràng về sự quan tâm."},{"en":"The data give a clear indication of improving performance.","vi":"Dữ liệu đưa ra một dấu hiệu rõ ràng về hiệu suất đang cải thiện."}]','[]',NULL,'/klɪr ˌɪndɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3525,'colloc-2-01',85,'clear relationship','mối liên hệ rõ ràng','adj + n','[{"en":"There is a clear relationship between sleep and learning.","vi":"Có một mối liên hệ rõ ràng giữa giấc ngủ và việc học."},{"en":"The graph shows a clear relationship between price and demand.","vi":"Biểu đồ cho thấy mối liên hệ rõ ràng giữa giá cả và nhu cầu."},{"en":"Researchers found a clear relationship between diet and energy.","vi":"Các nhà nghiên cứu tìm thấy mối liên hệ rõ ràng giữa chế độ ăn và năng lượng."}]','[]',NULL,'/klɪr rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3526,'colloc-2-01',86,'clear statement','tuyên bố rõ ràng','adj + n','[{"en":"The report opens with a clear statement of its aims.","vi":"Báo cáo mở đầu bằng một tuyên bố rõ ràng về mục tiêu của nó."},{"en":"A clear statement of the problem helps the reader follow.","vi":"Một tuyên bố rõ ràng về vấn đề giúp người đọc dễ theo dõi."},{"en":"The policy needs a clear statement about who is responsible.","vi":"Chính sách cần một tuyên bố rõ ràng về việc ai chịu trách nhiệm."}]','[]',NULL,'/klɪr ˈsteɪtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3527,'colloc-2-01',87,'clear structure','cấu trúc rõ ràng','adj + n','[{"en":"A clear structure makes any argument easier to follow.","vi":"Một cấu trúc rõ ràng khiến mọi lập luận dễ theo dõi hơn."},{"en":"The essay lacked a clear structure, so ideas felt disconnected.","vi":"Bài luận thiếu cấu trúc rõ ràng, nên các ý tưởng có vẻ rời rạc."},{"en":"Good presentations rely on a clear structure and strong examples.","vi":"Bài thuyết trình tốt dựa vào cấu trúc rõ ràng và ví dụ mạnh."}]','[]',NULL,'/klɪr ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3528,'colloc-2-01',88,'clearly defined','được xác định rõ ràng','adv + vpp','[{"en":"Each team member had a clearly defined role in the project.","vi":"Mỗi thành viên trong nhóm có một vai trò được xác định rõ ràng."},{"en":"The goals must be clearly defined before work begins.","vi":"Các mục tiêu phải được xác định rõ ràng trước khi bắt đầu làm việc."},{"en":"A clearly defined hypothesis guides the entire experiment.","vi":"Một giả thuyết được xác định rõ ràng dẫn dắt toàn bộ thí nghiệm."}]','[]',NULL,'/ˈklɪrli dɪˈfaɪnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3529,'colloc-2-01',89,'clearly demonstrated','được chứng minh rõ ràng','adv + vpp','[{"en":"The benefits of the method were clearly demonstrated in trials.","vi":"Lợi ích của phương pháp đã được chứng minh rõ ràng trong các thử nghiệm."},{"en":"She clearly demonstrated the link between the two variables.","vi":"Cô đã chứng minh rõ ràng mối liên hệ giữa hai biến số."},{"en":"The results clearly demonstrated the value of early intervention.","vi":"Kết quả đã chứng minh rõ ràng giá trị của việc can thiệp sớm."}]','[]',NULL,'/ˈklɪrli ˈdemənstreɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3530,'colloc-2-01',90,'clearly established','được thiết lập rõ ràng','adv + vpp','[{"en":"The link between smoking and cancer is clearly established.","vi":"Mối liên hệ giữa hút thuốc và ung thư đã được thiết lập rõ ràng."},{"en":"Once the rules are clearly established, disputes become rare.","vi":"Một khi các quy tắc được thiết lập rõ ràng, tranh chấp trở nên hiếm."},{"en":"The procedure follows a clearly established set of guidelines.","vi":"Quy trình tuân theo một bộ hướng dẫn được thiết lập rõ ràng."}]','[]',NULL,'/ˈklɪrli ɪˈstæblɪʃt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3531,'colloc-2-01',91,'clearly evident','rõ ràng hiển nhiên','adv + adj','[{"en":"Her talent was clearly evident from her very first essay.","vi":"Tài năng của cô rõ ràng hiển nhiên ngay từ bài luận đầu tiên."},{"en":"The effects of the drought were clearly evident across the fields.","vi":"Tác động của hạn hán rõ ràng hiển nhiên trên khắp các cánh đồng."},{"en":"It is clearly evident that more research is needed here.","vi":"Rõ ràng hiển nhiên rằng cần thêm nghiên cứu ở lĩnh vực này."}]','[]',NULL,'/ˈklɪrli ˈevɪdənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3532,'colloc-2-01',92,'clearly identified','được xác định rõ ràng','adv + vpp','[{"en":"Each risk must be clearly identified before the project starts.","vi":"Mỗi rủi ro phải được xác định rõ ràng trước khi dự án bắt đầu."},{"en":"The main causes of failure were clearly identified in the report.","vi":"Những nguyên nhân chính của thất bại được xác định rõ ràng trong báo cáo."},{"en":"Sources should be clearly identified to avoid plagiarism.","vi":"Nguồn tài liệu nên được xác định rõ ràng để tránh đạo văn."}]','[]',NULL,'/ˈklɪrli aɪˈdentɪfaɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3533,'colloc-2-01',93,'clearly important','rõ ràng quan trọng','adv + adj','[{"en":"Sleep is clearly important for memory and concentration.","vi":"Giấc ngủ rõ ràng quan trọng đối với trí nhớ và sự tập trung."},{"en":"It is clearly important to verify sources before citing them.","vi":"Rõ ràng quan trọng là phải kiểm chứng nguồn trước khi trích dẫn."},{"en":"Funding is clearly important, but leadership matters too.","vi":"Ngân sách rõ ràng quan trọng, nhưng sự lãnh đạo cũng quan trọng."}]','[]',NULL,'/ˈklɪrli ɪmˈpɔːrtənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3534,'colloc-2-01',94,'clearly related to','rõ ràng liên quan đến','adv + vpp','[{"en":"These symptoms are clearly related to a lack of sleep.","vi":"Những triệu chứng này rõ ràng liên quan đến việc thiếu ngủ."},{"en":"Her thesis is clearly related to earlier work in the field.","vi":"Luận văn của cô rõ ràng liên quan đến các công trình trước trong lĩnh vực."},{"en":"The rise in cases is clearly related to crowded conditions.","vi":"Sự gia tăng số ca rõ ràng liên quan đến điều kiện đông đúc."}]','[]',NULL,'/ˈklɪrli rɪˈleɪtɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3535,'colloc-2-01',95,'clearly understand','hiểu rõ ràng','adv + v','[{"en":"Students must clearly understand the rules before the exam.","vi":"Sinh viên phải hiểu rõ ràng các quy tắc trước kỳ thi."},{"en":"I want to clearly understand your argument before responding.","vi":"Mình muốn hiểu rõ ràng lập luận của bạn trước khi phản hồi."},{"en":"Few people clearly understand how the algorithm actually works.","vi":"Ít người hiểu rõ ràng thuật toán thực sự hoạt động như thế nào."}]','[]',NULL,'/ˈklɪrli ˌʌndərˈstænd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3536,'colloc-2-01',96,'clearly visible','rõ ràng có thể thấy','adv + adj','[{"en":"The mountains were clearly visible on that bright morning.","vi":"Những ngọn núi rõ ràng có thể thấy trong buổi sáng quang đãng đó."},{"en":"The trend is clearly visible in the latest set of graphs.","vi":"Xu hướng rõ ràng có thể thấy trong bộ biểu đồ mới nhất."},{"en":"Safety signs should be clearly visible at every entrance.","vi":"Biển báo an toàn nên rõ ràng có thể thấy ở mọi lối vào."}]','[]',NULL,'/ˈklɪrli ˈvɪzəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3537,'colloc-2-01',97,'climate change','biến đổi khí hậu','n + n','[{"en":"Climate change is one of the greatest challenges of our time.","vi":"Biến đổi khí hậu là một trong những thách thức lớn nhất thời đại."},{"en":"Scientists warn that climate change is accelerating worldwide.","vi":"Các nhà khoa học cảnh báo biến đổi khí hậu đang tăng tốc trên toàn cầu."},{"en":"Reducing emissions is essential to slowing climate change.","vi":"Giảm phát thải là điều thiết yếu để làm chậm biến đổi khí hậu."}]','[]',NULL,'/ˈklaɪmət tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3538,'colloc-2-01',98,'climatic conditions','điều kiện khí hậu','adj + n','[{"en":"Crops vary depending on local climatic conditions.","vi":"Cây trồng thay đổi tùy theo điều kiện khí hậu địa phương."},{"en":"Harsh climatic conditions limit which species can survive.","vi":"Điều kiện khí hậu khắc nghiệt hạn chế những loài có thể sống sót."},{"en":"The study compares plant growth under different climatic conditions.","vi":"Nghiên cứu so sánh sự phát triển của cây trong các điều kiện khí hậu khác nhau."}]','[]',NULL,'/klaɪˈmætɪk kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3539,'colloc-2-01',99,'close contact','sự tiếp xúc gần','adj + n','[{"en":"The disease spreads through close contact between infected people.","vi":"Bệnh lây lan qua sự tiếp xúc gần giữa những người bị nhiễm."},{"en":"She kept in close contact with her former colleagues.","vi":"Cô ấy giữ liên lạc thường xuyên với các đồng nghiệp cũ."},{"en":"Researchers maintain close contact with the communities they study.","vi":"Các nhà nghiên cứu duy trì sự tiếp xúc gần với cộng đồng họ nghiên cứu."}]','[]',NULL,'/kloʊs ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3540,'colloc-2-01',100,'close proximity','khoảng cách rất gần','adj + n','[{"en":"The two buildings stand in close proximity to each other.","vi":"Hai tòa nhà nằm rất gần nhau."},{"en":"Living in close proximity to factories can affect health.","vi":"Sống gần các nhà máy có thể ảnh hưởng đến sức khỏe."},{"en":"The study examined animals living in close proximity to humans.","vi":"Nghiên cứu xem xét các loài vật sống rất gần con người."}]','[]',NULL,'/kloʊs prɑːkˈsɪməti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3541,'colloc-2-01',101,'close relationship','mối quan hệ thân thiết','adj + n','[{"en":"There is a close relationship between diet and overall health.","vi":"Có một mối quan hệ chặt chẽ giữa chế độ ăn và sức khỏe."},{"en":"She built a close relationship with her academic supervisor.","vi":"Cô ấy xây dựng mối quan hệ thân thiết với người hướng dẫn."},{"en":"The data show a close relationship between income and education.","vi":"Dữ liệu cho thấy mối quan hệ chặt chẽ giữa thu nhập và học vấn."}]','[]',NULL,'/kloʊs rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3542,'colloc-2-01',102,'close scrutiny','sự xem xét kỹ lưỡng','adj + n','[{"en":"The proposal came under close scrutiny from the committee.","vi":"Đề xuất bị ủy ban xem xét kỹ lưỡng."},{"en":"These results deserve close scrutiny before any conclusions are drawn.","vi":"Những kết quả này cần được xem xét kỹ trước khi kết luận."},{"en":"Public spending is subject to close scrutiny by auditors.","vi":"Chi tiêu công chịu sự xem xét kỹ lưỡng từ các kiểm toán viên."}]','[]',NULL,'/kloʊs ˈskruːtəni/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3543,'colloc-2-01',103,'closely allied to','gắn bó chặt chẽ với','adv + vpp','[{"en":"Linguistics is closely allied to psychology in many respects.","vi":"Ngôn ngữ học gắn bó chặt chẽ với tâm lý học ở nhiều khía cạnh."},{"en":"This theory is closely allied to earlier philosophical ideas.","vi":"Lý thuyết này gắn bó chặt chẽ với các tư tưởng triết học trước đó."},{"en":"The firm is closely allied to several major research institutions.","vi":"Công ty gắn bó chặt chẽ với nhiều viện nghiên cứu lớn."}]','[]',NULL,'/ˈkloʊsli əˈlaɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3544,'colloc-2-01',104,'closely associated with','gắn liền chặt chẽ với','adv + vpp','[{"en":"Smoking is closely associated with several serious diseases.","vi":"Hút thuốc gắn liền chặt chẽ với nhiều căn bệnh nghiêm trọng."},{"en":"His name is closely associated with the civil rights movement.","vi":"Tên ông gắn liền chặt chẽ với phong trào dân quyền."},{"en":"Poverty is closely associated with poor educational outcomes.","vi":"Nghèo đói gắn liền chặt chẽ với kết quả học tập kém."}]','[]',NULL,'/ˈkloʊsli əˈsoʊsieɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3545,'colloc-2-01',105,'closely connected to','liên kết chặt chẽ với','adv + vpp','[{"en":"Economic growth is closely connected to political stability.","vi":"Tăng trưởng kinh tế liên kết chặt chẽ với ổn định chính trị."},{"en":"These two problems are closely connected to one another.","vi":"Hai vấn đề này liên kết chặt chẽ với nhau."},{"en":"Her research is closely connected to current environmental debates.","vi":"Nghiên cứu của cô liên kết chặt chẽ với các tranh luận môi trường hiện nay."}]','[]',NULL,'/ˈkloʊsli kəˈnektɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3546,'colloc-2-01',106,'closely linked to','liên hệ mật thiết với','adv + vpp','[{"en":"Mental health is closely linked to physical wellbeing.","vi":"Sức khỏe tinh thần liên hệ mật thiết với sức khỏe thể chất."},{"en":"Unemployment is closely linked to rising crime rates.","vi":"Thất nghiệp liên hệ mật thiết với tỉ lệ tội phạm tăng."},{"en":"The decline is closely linked to changes in consumer behaviour.","vi":"Sự suy giảm liên hệ mật thiết với thay đổi trong hành vi tiêu dùng."}]','[]',NULL,'/ˈkloʊsli lɪŋkt tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3547,'colloc-2-01',107,'closely related to','có liên quan mật thiết với','adv + vpp','[{"en":"This species is closely related to the domestic cat.","vi":"Loài này có liên quan mật thiết với mèo nhà."},{"en":"The two questions are closely related to each other.","vi":"Hai câu hỏi có liên quan mật thiết với nhau."},{"en":"Job satisfaction is closely related to employee productivity.","vi":"Sự hài lòng trong công việc liên quan mật thiết với năng suất."}]','[]',NULL,'/ˈkloʊsli rɪˈleɪtɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3548,'colloc-2-01',108,'closely resemble','rất giống với','adv + v','[{"en":"The fake documents closely resemble the genuine originals.","vi":"Các tài liệu giả rất giống bản gốc thật."},{"en":"Her early paintings closely resemble those of her teacher.","vi":"Các bức tranh ban đầu của cô rất giống tranh của thầy."},{"en":"The model''s predictions closely resemble the observed data.","vi":"Dự đoán của mô hình rất giống với dữ liệu quan sát được."}]','[]',NULL,'/ˈkloʊsli rɪˈzembəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3549,'colloc-2-01',109,'closely tied','gắn kết chặt chẽ','adv + vpp','[{"en":"Their success is closely tied to government funding.","vi":"Thành công của họ gắn kết chặt chẽ với nguồn tài trợ chính phủ."},{"en":"National identity is closely tied to shared language and history.","vi":"Bản sắc dân tộc gắn kết chặt chẽ với ngôn ngữ và lịch sử chung."},{"en":"Wages are closely tied to overall company performance.","vi":"Tiền lương gắn kết chặt chẽ với hiệu quả chung của công ty."}]','[]',NULL,'/ˈkloʊsli taɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3550,'colloc-2-01',110,'closer examination','sự xem xét kỹ hơn','adj + n','[{"en":"Closer examination of the data revealed several errors.","vi":"Việc xem xét kỹ hơn dữ liệu đã phát hiện nhiều sai sót."},{"en":"The argument falls apart under closer examination.","vi":"Lập luận sụp đổ khi được xem xét kỹ hơn."},{"en":"Closer examination shows the two cases differ significantly.","vi":"Xem xét kỹ hơn cho thấy hai trường hợp khác nhau đáng kể."}]','[]',NULL,'/ˈkloʊsər ɪɡˌzæmɪˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3551,'colloc-2-01',111,'closer inspection','sự kiểm tra kỹ hơn','adj + n','[{"en":"On closer inspection, the painting turned out to be a copy.","vi":"Khi kiểm tra kỹ hơn, bức tranh hóa ra là bản sao."},{"en":"Closer inspection of the results raised new questions.","vi":"Việc kiểm tra kỹ hơn các kết quả làm nảy sinh câu hỏi mới."},{"en":"The flaw became obvious only on closer inspection.","vi":"Lỗi chỉ trở nên rõ ràng khi kiểm tra kỹ hơn."}]','[]',NULL,'/ˈkloʊsər ɪnˈspekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3552,'colloc-2-01',112,'closer look','cái nhìn cận cảnh hơn','adj + n','[{"en":"Let us take a closer look at the underlying causes.","vi":"Chúng ta hãy nhìn kỹ hơn vào các nguyên nhân sâu xa."},{"en":"A closer look reveals important differences between the groups.","vi":"Một cái nhìn kỹ hơn cho thấy những khác biệt quan trọng giữa các nhóm."},{"en":"This chapter takes a closer look at urban migration.","vi":"Chương này xem xét kỹ hơn hiện tượng di cư đô thị."}]','[]',NULL,'/ˈkloʊsər lʊk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3553,'colloc-2-01',113,'cognitive ability','khả năng nhận thức','adj + n','[{"en":"Sleep deprivation can reduce a person''s cognitive ability.","vi":"Thiếu ngủ có thể làm giảm khả năng nhận thức của một người."},{"en":"The tests measure several aspects of cognitive ability.","vi":"Các bài kiểm tra đo lường nhiều khía cạnh của khả năng nhận thức."},{"en":"Cognitive ability tends to decline gradually with age.","vi":"Khả năng nhận thức có xu hướng giảm dần theo tuổi tác."}]','[]',NULL,'/ˈkɑːɡnətɪv əˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3554,'colloc-2-01',114,'cognitive development','sự phát triển nhận thức','adj + n','[{"en":"Early childhood is crucial for cognitive development.","vi":"Tuổi thơ ấu rất quan trọng đối với sự phát triển nhận thức."},{"en":"Play supports cognitive development in young children.","vi":"Vui chơi hỗ trợ sự phát triển nhận thức ở trẻ nhỏ."},{"en":"The study tracked cognitive development over several years.","vi":"Nghiên cứu theo dõi sự phát triển nhận thức trong nhiều năm."}]','[]',NULL,'/ˈkɑːɡnətɪv dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3555,'colloc-2-01',115,'cognitive skills','kỹ năng nhận thức','adj + n','[{"en":"Reading regularly helps children develop cognitive skills.","vi":"Đọc sách thường xuyên giúp trẻ phát triển kỹ năng nhận thức."},{"en":"The program aims to strengthen students'' cognitive skills.","vi":"Chương trình nhằm tăng cường kỹ năng nhận thức của học sinh."},{"en":"Problem solving relies on a range of cognitive skills.","vi":"Giải quyết vấn đề dựa vào nhiều kỹ năng nhận thức khác nhau."}]','[]',NULL,'/ˈkɑːɡnətɪv skɪlz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3556,'colloc-2-01',116,'collaborative learning','học tập hợp tác','adj + n','[{"en":"Collaborative learning encourages students to share ideas freely.","vi":"Học tập hợp tác khuyến khích học sinh chia sẻ ý tưởng tự do."},{"en":"The teacher organized the class around collaborative learning tasks.","vi":"Giáo viên tổ chức lớp học quanh các nhiệm vụ học tập hợp tác."},{"en":"Research suggests collaborative learning improves long-term retention.","vi":"Nghiên cứu cho thấy học tập hợp tác cải thiện khả năng ghi nhớ lâu dài."}]','[]',NULL,'/kəˈlæbərətɪv ˈlɜːrnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3557,'colloc-2-01',117,'collect data','thu thập dữ liệu','v + n','[{"en":"Researchers collect data through surveys and interviews.","vi":"Các nhà nghiên cứu thu thập dữ liệu qua khảo sát và phỏng vấn."},{"en":"We need to collect data before drawing any conclusions.","vi":"Chúng ta cần thu thập dữ liệu trước khi đưa ra kết luận."},{"en":"The sensors collect data on temperature every hour.","vi":"Các cảm biến thu thập dữ liệu về nhiệt độ mỗi giờ."}]','[]',NULL,'/kəˈlekt ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3558,'colloc-2-01',118,'collect information','thu thập thông tin','v + n','[{"en":"The team collects information from a wide range of sources.","vi":"Nhóm thu thập thông tin từ nhiều nguồn khác nhau."},{"en":"Companies collect information about their customers'' preferences.","vi":"Các công ty thu thập thông tin về sở thích của khách hàng."},{"en":"We collect information carefully to ensure accurate results.","vi":"Chúng tôi thu thập thông tin cẩn thận để đảm bảo kết quả chính xác."}]','[]',NULL,'/kəˈlekt ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3559,'colloc-2-01',119,'collective action','hành động tập thể','adj + n','[{"en":"Collective action is often needed to tackle climate change.","vi":"Hành động tập thể thường cần thiết để giải quyết biến đổi khí hậu."},{"en":"The workers organized collective action to demand fair pay.","vi":"Công nhân tổ chức hành động tập thể để đòi mức lương công bằng."},{"en":"Collective action can achieve what individuals cannot alone.","vi":"Hành động tập thể có thể đạt được điều mà cá nhân không thể."}]','[]',NULL,'/kəˈlektɪv ˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3560,'colloc-2-01',120,'collective identity','bản sắc tập thể','adj + n','[{"en":"Shared traditions help build a strong collective identity.","vi":"Truyền thống chung giúp xây dựng bản sắc tập thể mạnh mẽ."},{"en":"The festival reinforces the community''s collective identity.","vi":"Lễ hội củng cố bản sắc tập thể của cộng đồng."},{"en":"Migration can challenge a nation''s sense of collective identity.","vi":"Di cư có thể thách thức cảm thức về bản sắc tập thể của một quốc gia."}]','[]',NULL,'/kəˈlektɪv aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3561,'colloc-2-01',121,'collective memory','ký ức tập thể','adj + n','[{"en":"The war remains part of the nation''s collective memory.","vi":"Cuộc chiến vẫn là một phần ký ức tập thể của dân tộc."},{"en":"Monuments help preserve a society''s collective memory.","vi":"Các đài tưởng niệm giúp lưu giữ ký ức tập thể của xã hội."},{"en":"Stories passed down shape our collective memory of the past.","vi":"Những câu chuyện truyền lại định hình ký ức tập thể về quá khứ."}]','[]',NULL,'/kəˈlektɪv ˈmeməri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3562,'colloc-2-01',122,'combined effect','tác động tổng hợp','adj + n','[{"en":"The combined effect of heat and drought damaged the crops.","vi":"Tác động tổng hợp của nắng nóng và hạn hán đã làm hỏng mùa màng."},{"en":"Researchers studied the combined effect of diet and exercise.","vi":"Các nhà nghiên cứu nghiên cứu tác động tổng hợp của ăn uống và tập luyện."},{"en":"The combined effect of these factors is difficult to predict.","vi":"Tác động tổng hợp của các yếu tố này rất khó dự đoán."}]','[]',NULL,'/kəmˈbaɪnd ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3563,'colloc-2-01',123,'come into conflict with','xảy ra xung đột với','v + n','[{"en":"New regulations often come into conflict with existing laws.","vi":"Các quy định mới thường xung đột với luật hiện hành."},{"en":"His personal beliefs came into conflict with company policy.","vi":"Niềm tin cá nhân của anh xung đột với chính sách công ty."},{"en":"Economic goals can come into conflict with environmental ones.","vi":"Các mục tiêu kinh tế có thể xung đột với mục tiêu môi trường."}]','[]',NULL,'/kʌm ˈɪntə ˈkɑːnflɪkt wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3564,'colloc-2-01',124,'come into contact with','tiếp xúc với','v + n','[{"en":"Workers may come into contact with hazardous chemicals.","vi":"Công nhân có thể tiếp xúc với hóa chất nguy hiểm."},{"en":"Children come into contact with many germs at school.","vi":"Trẻ em tiếp xúc với nhiều vi khuẩn ở trường."},{"en":"The two cultures first came into contact through trade.","vi":"Hai nền văn hóa lần đầu tiếp xúc thông qua thương mại."}]','[]',NULL,'/kʌm ˈɪntə ˈkɑːntækt wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3565,'colloc-2-01',125,'commercial activity','hoạt động thương mại','adj + n','[{"en":"The new port boosted commercial activity in the region.","vi":"Cảng mới thúc đẩy hoạt động thương mại trong khu vực."},{"en":"Commercial activity slowed during the economic downturn.","vi":"Hoạt động thương mại chậm lại trong thời kỳ suy thoái kinh tế."},{"en":"Strict rules govern commercial activity near the reserve.","vi":"Các quy định nghiêm ngặt điều chỉnh hoạt động thương mại gần khu bảo tồn."}]','[]',NULL,'/kəˈmɜːrʃəl ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3566,'colloc-2-01',126,'commercial transaction','giao dịch thương mại','adj + n','[{"en":"Every commercial transaction is recorded for accounting purposes.","vi":"Mọi giao dịch thương mại đều được ghi lại để phục vụ kế toán."},{"en":"Online platforms now handle millions of commercial transactions daily.","vi":"Các nền tảng trực tuyến nay xử lý hàng triệu giao dịch thương mại mỗi ngày."},{"en":"The contract governs the terms of each commercial transaction.","vi":"Hợp đồng quy định các điều khoản của mỗi giao dịch thương mại."}]','[]',NULL,'/kəˈmɜːrʃəl trænˈzækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3567,'colloc-2-01',127,'commit a crime','phạm tội','v + n','[{"en":"Anyone who commits a crime should face legal consequences.","vi":"Bất kỳ ai phạm tội đều phải đối mặt với hậu quả pháp lý."},{"en":"Poverty does not force people to commit a crime.","vi":"Nghèo đói không buộc người ta phải phạm tội."},{"en":"He was accused of committing a serious crime abroad.","vi":"Anh ta bị cáo buộc phạm một tội nghiêm trọng ở nước ngoài."}]','[]',NULL,'/kəˈmɪt ə kraɪm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3568,'colloc-2-01',128,'commit an offence','vi phạm pháp luật','v + n','[{"en":"Drivers who commit an offence may lose their licence.","vi":"Tài xế vi phạm có thể bị tước bằng lái."},{"en":"The law clearly states what it means to commit an offence.","vi":"Luật nêu rõ thế nào là vi phạm pháp luật."},{"en":"Companies that commit an offence can be heavily fined.","vi":"Các công ty vi phạm có thể bị phạt nặng."}]','[]',NULL,'/kəˈmɪt ən əˈfens/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3569,'colloc-2-01',129,'common ancestor','tổ tiên chung','adj + n','[{"en":"Humans and apes share a distant common ancestor.","vi":"Con người và vượn có chung một tổ tiên xa xưa."},{"en":"These languages descend from a single common ancestor.","vi":"Các ngôn ngữ này đều bắt nguồn từ một tổ tiên chung."},{"en":"Fossils help scientists trace the common ancestor of mammals.","vi":"Hóa thạch giúp các nhà khoa học truy tìm tổ tiên chung của loài có vú."}]','[]',NULL,'/ˈkɑːmən ˈænsestər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3570,'colloc-2-01',130,'common approach','cách tiếp cận phổ biến','adj + n','[{"en":"A common approach is to divide the task into stages.","vi":"Một cách tiếp cận phổ biến là chia nhiệm vụ thành các giai đoạn."},{"en":"The teams agreed on a common approach to the problem.","vi":"Các nhóm đồng ý về một cách tiếp cận chung cho vấn đề."},{"en":"This common approach has both strengths and clear limitations.","vi":"Cách tiếp cận phổ biến này có cả điểm mạnh lẫn hạn chế rõ ràng."}]','[]',NULL,'/ˈkɑːmən əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3571,'colloc-2-01',131,'common assumption','giả định phổ biến','adj + n','[{"en":"A common assumption is that money guarantees happiness.","vi":"Một giả định phổ biến là tiền bạc đảm bảo hạnh phúc."},{"en":"The study challenges a common assumption about ageing.","vi":"Nghiên cứu thách thức một giả định phổ biến về sự lão hóa."},{"en":"This common assumption is not supported by the evidence.","vi":"Giả định phổ biến này không được bằng chứng ủng hộ."}]','[]',NULL,'/ˈkɑːmən əˈsʌmpʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3572,'colloc-2-01',132,'common characteristic','đặc điểm chung','adj + n','[{"en":"Patience is a common characteristic among successful researchers.","vi":"Sự kiên nhẫn là đặc điểm chung của các nhà nghiên cứu thành công."},{"en":"The groups share several common characteristics worth examining.","vi":"Các nhóm có chung nhiều đặc điểm đáng để xem xét."},{"en":"A common characteristic of these regions is high rainfall.","vi":"Một đặc điểm chung của các vùng này là lượng mưa cao."}]','[]',NULL,'/ˈkɑːmən ˌkerəktəˈrɪstɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3573,'colloc-2-01',133,'common culture','nền văn hóa chung','adj + n','[{"en":"A common culture helps bind diverse communities together.","vi":"Một nền văn hóa chung giúp gắn kết các cộng đồng đa dạng."},{"en":"Language is central to maintaining a common culture.","vi":"Ngôn ngữ là yếu tố cốt lõi để duy trì một nền văn hóa chung."},{"en":"Globalization is creating a more common culture worldwide.","vi":"Toàn cầu hóa đang tạo ra một nền văn hóa chung hơn trên thế giới."}]','[]',NULL,'/ˈkɑːmən ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3574,'colloc-2-01',134,'common error','lỗi phổ biến','adj + n','[{"en":"Confusing the two terms is a common error among beginners.","vi":"Nhầm lẫn hai thuật ngữ là lỗi phổ biến ở người mới học."},{"en":"The guide lists common errors and how to avoid them.","vi":"Cẩm nang liệt kê các lỗi phổ biến và cách tránh chúng."},{"en":"Skipping the review step is a surprisingly common error.","vi":"Bỏ qua bước rà soát là một lỗi phổ biến đáng ngạc nhiên."}]','[]',NULL,'/ˈkɑːmən ˈerər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3575,'colloc-2-01',135,'common feature','đặc trưng chung','adj + n','[{"en":"Open spaces are a common feature of modern offices.","vi":"Không gian mở là đặc trưng chung của các văn phòng hiện đại."},{"en":"Repetition is a common feature of traditional folk songs.","vi":"Sự lặp lại là đặc trưng chung của các bài dân ca truyền thống."},{"en":"Strict deadlines are a common feature of this industry.","vi":"Hạn chót nghiêm ngặt là đặc trưng chung của ngành này."}]','[]',NULL,'/ˈkɑːmən ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3576,'colloc-2-01',136,'common goal','mục tiêu chung','adj + n','[{"en":"The team worked together toward a common goal.","vi":"Cả nhóm cùng làm việc hướng tới một mục tiêu chung."},{"en":"Reducing emissions is a common goal of many nations.","vi":"Giảm phát thải là mục tiêu chung của nhiều quốc gia."},{"en":"A common goal helps members stay motivated and focused.","vi":"Một mục tiêu chung giúp các thành viên duy trì động lực và tập trung."}]','[]',NULL,'/ˈkɑːmən ɡoʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3577,'colloc-2-01',137,'common method','phương pháp phổ biến','adj + n','[{"en":"Interviewing is a common method of gathering qualitative data.","vi":"Phỏng vấn là phương pháp phổ biến để thu thập dữ liệu định tính."},{"en":"A common method for storing food is freezing.","vi":"Một phương pháp phổ biến để bảo quản thực phẩm là đông lạnh."},{"en":"The authors compare several common methods of analysis.","vi":"Các tác giả so sánh một số phương pháp phân tích phổ biến."}]','[]',NULL,'/ˈkɑːmən ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3578,'colloc-2-01',138,'common source','nguồn chung','adj + n','[{"en":"Contaminated water is a common source of illness.","vi":"Nước bị ô nhiễm là một nguồn gây bệnh phổ biến."},{"en":"Misunderstanding is a common source of workplace conflict.","vi":"Hiểu lầm là nguồn gốc phổ biến của xung đột nơi làm việc."},{"en":"The two texts appear to share a common source.","vi":"Hai văn bản dường như có chung một nguồn gốc."}]','[]',NULL,'/ˈkɑːmən sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3579,'colloc-2-01',139,'common theme','chủ đề chung','adj + n','[{"en":"Loss is a common theme throughout the author''s novels.","vi":"Mất mát là chủ đề chung xuyên suốt các tiểu thuyết của tác giả."},{"en":"A common theme emerged from the interview responses.","vi":"Một chủ đề chung đã xuất hiện từ các câu trả lời phỏng vấn."},{"en":"Identity is a common theme in postcolonial literature.","vi":"Bản sắc là chủ đề chung trong văn học hậu thuộc địa."}]','[]',NULL,'/ˈkɑːmən θiːm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3580,'colloc-2-01',140,'common usage','cách dùng thông dụng','adj + n','[{"en":"The word has shifted in meaning through common usage.","vi":"Từ này đã thay đổi nghĩa qua cách dùng thông dụng."},{"en":"Dictionaries record changes in common usage over time.","vi":"Từ điển ghi lại những thay đổi trong cách dùng thông dụng theo thời gian."},{"en":"This phrase has entered common usage among young people.","vi":"Cụm từ này đã trở nên thông dụng trong giới trẻ."}]','[]',NULL,'/ˈkɑːmən ˈjuːsɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3581,'colloc-2-01',141,'commonly accepted','được chấp nhận rộng rãi','adv + vpp','[{"en":"It is commonly accepted that exercise benefits mental health.","vi":"Người ta thường chấp nhận rằng tập thể dục tốt cho sức khỏe tinh thần."},{"en":"The theory is now commonly accepted within the field.","vi":"Lý thuyết này hiện được chấp nhận rộng rãi trong lĩnh vực."},{"en":"These standards are commonly accepted across the industry.","vi":"Các tiêu chuẩn này được chấp nhận rộng rãi trong toàn ngành."}]','[]',NULL,'/ˈkɑːmənli əkˈseptɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3582,'colloc-2-01',142,'commonly associated with','thường gắn liền với','adv + vpp','[{"en":"Stress is commonly associated with high blood pressure.","vi":"Căng thẳng thường gắn liền với huyết áp cao."},{"en":"This style is commonly associated with the Renaissance period.","vi":"Phong cách này thường gắn liền với thời kỳ Phục hưng."},{"en":"Such symptoms are commonly associated with vitamin deficiency.","vi":"Những triệu chứng như vậy thường gắn liền với thiếu vitamin."}]','[]',NULL,'/ˈkɑːmənli əˈsoʊsieɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3583,'colloc-2-01',143,'commonly called','thường được gọi là','adv + vpp','[{"en":"The condition is commonly called the common cold.","vi":"Tình trạng này thường được gọi là cảm lạnh thông thường."},{"en":"This region is commonly called the breadbasket of the country.","vi":"Vùng này thường được gọi là vựa lúa của đất nước."},{"en":"The device is commonly called a smartphone today.","vi":"Thiết bị này ngày nay thường được gọi là điện thoại thông minh."}]','[]',NULL,'/ˈkɑːmənli kɔːld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3584,'colloc-2-01',144,'commonly encountered','thường gặp','adv + vpp','[{"en":"These problems are commonly encountered by new students.","vi":"Những vấn đề này thường gặp ở sinh viên mới."},{"en":"This species is commonly encountered in coastal areas.","vi":"Loài này thường gặp ở các vùng ven biển."},{"en":"The error is commonly encountered when running old software.","vi":"Lỗi này thường gặp khi chạy phần mềm cũ."}]','[]',NULL,'/ˈkɑːmənli ɪnˈkaʊntərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3585,'colloc-2-01',145,'commonly found in','thường thấy trong','adv + vpp','[{"en":"This mineral is commonly found in volcanic rocks.","vi":"Khoáng chất này thường thấy trong đá núi lửa."},{"en":"Such errors are commonly found in early drafts.","vi":"Những lỗi như vậy thường thấy trong các bản nháp đầu tiên."},{"en":"Iron is commonly found in green leafy vegetables.","vi":"Sắt thường thấy trong các loại rau lá xanh."}]','[]',NULL,'/ˈkɑːmənli faʊnd ɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3586,'colloc-2-01',146,'commonly known as','thường được biết đến là','adv + vpp','[{"en":"The disease is commonly known as whooping cough.","vi":"Căn bệnh này thường được biết đến là ho gà."},{"en":"The plant is commonly known as the snake plant.","vi":"Loại cây này thường được biết đến là cây lưỡi hổ."},{"en":"The era is commonly known as the Industrial Revolution.","vi":"Thời kỳ này thường được biết đến là Cách mạng Công nghiệp."}]','[]',NULL,'/ˈkɑːmənli noʊn æz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3587,'colloc-2-01',147,'commonly referred to as','thường được gọi là','adv + vpp','[{"en":"The phenomenon is commonly referred to as global warming.","vi":"Hiện tượng này thường được gọi là sự nóng lên toàn cầu."},{"en":"These cells are commonly referred to as stem cells.","vi":"Những tế bào này thường được gọi là tế bào gốc."},{"en":"The model is commonly referred to as a feedback loop.","vi":"Mô hình này thường được gọi là vòng phản hồi."}]','[]',NULL,'/ˈkɑːmənli rɪˈfɜːrd tə æz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3588,'colloc-2-01',148,'commonly used','được sử dụng phổ biến','adv + vpp','[{"en":"This method is commonly used in social science research.","vi":"Phương pháp này được sử dụng phổ biến trong nghiên cứu khoa học xã hội."},{"en":"The term is commonly used in everyday conversation.","vi":"Thuật ngữ này được sử dụng phổ biến trong giao tiếp hằng ngày."},{"en":"These tools are commonly used by professional designers.","vi":"Những công cụ này được các nhà thiết kế chuyên nghiệp sử dụng phổ biến."}]','[]',NULL,'/ˈkɑːmənli juːzd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3589,'colloc-2-01',149,'communicate effectively','giao tiếp hiệu quả','v + adv','[{"en":"Good leaders must communicate effectively with their teams.","vi":"Những nhà lãnh đạo giỏi phải giao tiếp hiệu quả với nhóm của mình."},{"en":"The course teaches students to communicate effectively in writing.","vi":"Khóa học dạy sinh viên giao tiếp hiệu quả qua văn bản."},{"en":"Doctors need to communicate effectively with anxious patients.","vi":"Bác sĩ cần giao tiếp hiệu quả với những bệnh nhân lo lắng."}]','[]',NULL,'/kəˈmjuːnɪkeɪt ɪˈfektɪvli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3590,'colloc-2-01',150,'comparative analysis','phân tích so sánh','adj + n','[{"en":"The report offers a comparative analysis of three economies.","vi":"Báo cáo đưa ra một phân tích so sánh giữa ba nền kinh tế."},{"en":"A comparative analysis reveals key differences in policy.","vi":"Phân tích so sánh cho thấy những khác biệt then chốt về chính sách."},{"en":"She conducted a comparative analysis of two teaching methods.","vi":"Cô tiến hành phân tích so sánh hai phương pháp giảng dạy."}]','[]',NULL,'/kəmˈpærətɪv əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3591,'colloc-3-01',1,'comparative research','nghiên cứu so sánh','adj + n','[{"en":"Comparative research helps identify patterns across different cultures.","vi":"Nghiên cứu so sánh giúp nhận ra các khuôn mẫu giữa các nền văn hóa."},{"en":"Her comparative research focused on education systems in Asia.","vi":"Nghiên cứu so sánh của cô tập trung vào các hệ thống giáo dục ở châu Á."},{"en":"Comparative research requires careful selection of comparable cases.","vi":"Nghiên cứu so sánh đòi hỏi lựa chọn cẩn thận các trường hợp tương đương."}]','[]',NULL,'/kəmˈpærətɪv ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3592,'colloc-3-01',2,'comparative study','công trình so sánh','adj + n','[{"en":"The team published a comparative study of urban transport.","vi":"Nhóm đã công bố một công trình so sánh về giao thông đô thị."},{"en":"This comparative study examines healthcare in five countries.","vi":"Công trình so sánh này xem xét hệ thống y tế ở năm quốc gia."},{"en":"A comparative study can highlight strengths of each approach.","vi":"Một công trình so sánh có thể làm nổi bật điểm mạnh của từng cách tiếp cận."}]','[]',NULL,'/kəmˈpærətɪv ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3593,'colloc-3-01',3,'compelling argument','lập luận thuyết phục','adj + n','[{"en":"She made a compelling argument for reforming the system.","vi":"Cô đưa ra một lập luận thuyết phục để cải cách hệ thống."},{"en":"The essay presents a compelling argument supported by data.","vi":"Bài luận trình bày một lập luận thuyết phục được dữ liệu hỗ trợ."},{"en":"His compelling argument changed many people''s minds.","vi":"Lập luận thuyết phục của ông đã thay đổi suy nghĩ của nhiều người."}]','[]',NULL,'/kəmˈpelɪŋ ˈɑːrɡjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3594,'colloc-3-01',4,'compelling evidence','bằng chứng thuyết phục','adj + n','[{"en":"The study provides compelling evidence of climate change.","vi":"Nghiên cứu cung cấp bằng chứng thuyết phục về biến đổi khí hậu."},{"en":"There is compelling evidence linking smoking to cancer.","vi":"Có bằng chứng thuyết phục liên hệ hút thuốc với ung thư."},{"en":"Without compelling evidence, the claim cannot be accepted.","vi":"Không có bằng chứng thuyết phục, tuyên bố không thể được chấp nhận."}]','[]',NULL,'/kəmˈpelɪŋ ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3595,'colloc-3-01',5,'compelling reason','lý do thuyết phục','adj + n','[{"en":"There is a compelling reason to revise the current policy.","vi":"Có một lý do thuyết phục để sửa đổi chính sách hiện tại."},{"en":"She gave no compelling reason for missing the deadline.","vi":"Cô không đưa ra lý do thuyết phục nào cho việc trễ hạn."},{"en":"Investors need a compelling reason to fund the project.","vi":"Các nhà đầu tư cần một lý do thuyết phục để tài trợ dự án."}]','[]',NULL,'/kəmˈpelɪŋ ˈriːzən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3596,'colloc-3-01',6,'competitive market','thị trường cạnh tranh','adj + n','[{"en":"In a competitive market, prices tend to stay low.","vi":"Trong một thị trường cạnh tranh, giá cả có xu hướng thấp."},{"en":"Small firms struggle to survive in a competitive market.","vi":"Các công ty nhỏ khó tồn tại trong thị trường cạnh tranh."},{"en":"Innovation is essential to thrive in a competitive market.","vi":"Đổi mới là thiết yếu để phát triển trong thị trường cạnh tranh."}]','[]',NULL,'/kəmˈpetətɪv ˈmɑːrkɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3597,'colloc-3-01',7,'competitive pressure','áp lực cạnh tranh','adj + n','[{"en":"Competitive pressure forced the company to lower its prices.","vi":"Áp lực cạnh tranh buộc công ty phải hạ giá."},{"en":"Firms face growing competitive pressure from overseas rivals.","vi":"Các công ty đối mặt với áp lực cạnh tranh ngày càng tăng từ đối thủ nước ngoài."},{"en":"Competitive pressure often drives rapid technological change.","vi":"Áp lực cạnh tranh thường thúc đẩy thay đổi công nghệ nhanh chóng."}]','[]',NULL,'/kəmˈpetətɪv ˈpreʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3598,'colloc-3-01',8,'complete a task','hoàn thành nhiệm vụ','v + n','[{"en":"Students must complete a task before moving to the next.","vi":"Học sinh phải hoàn thành nhiệm vụ trước khi chuyển sang phần tiếp."},{"en":"It took the team two weeks to complete the task.","vi":"Nhóm mất hai tuần để hoàn thành nhiệm vụ."},{"en":"Clear instructions help workers complete a task efficiently.","vi":"Hướng dẫn rõ ràng giúp công nhân hoàn thành nhiệm vụ hiệu quả."}]','[]',NULL,'/kəmˈpliːt ə tæsk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3599,'colloc-3-01',9,'complex area','lĩnh vực phức tạp','adj + n','[{"en":"Tax law is a complex area that requires expert advice.","vi":"Luật thuế là một lĩnh vực phức tạp đòi hỏi tư vấn chuyên môn."},{"en":"This complex area of research is still poorly understood.","vi":"Lĩnh vực nghiên cứu phức tạp này vẫn chưa được hiểu rõ."},{"en":"Ethics in medicine remains a deeply complex area.","vi":"Đạo đức trong y học vẫn là một lĩnh vực hết sức phức tạp."}]','[]',NULL,'/ˈkɑːmpleks ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3600,'colloc-3-01',10,'complex interaction','tương tác phức tạp','adj + n','[{"en":"Behaviour results from a complex interaction of many factors.","vi":"Hành vi nảy sinh từ sự tương tác phức tạp của nhiều yếu tố."},{"en":"The model captures the complex interaction between species.","vi":"Mô hình nắm bắt sự tương tác phức tạp giữa các loài."},{"en":"Climate involves a complex interaction of ocean and atmosphere.","vi":"Khí hậu liên quan đến tương tác phức tạp giữa đại dương và khí quyển."}]','[]',NULL,'/ˈkɑːmpleks ˌɪntərˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3601,'colloc-3-01',11,'complex issue','vấn đề phức tạp','adj + n','[{"en":"Immigration is a complex issue with no simple solution.","vi":"Nhập cư là một vấn đề phức tạp không có lời giải đơn giản."},{"en":"The report addresses the complex issue of inequality.","vi":"Báo cáo đề cập đến vấn đề phức tạp về bất bình đẳng."},{"en":"Resolving this complex issue requires cooperation from everyone.","vi":"Giải quyết vấn đề phức tạp này cần sự hợp tác từ mọi người."}]','[]',NULL,'/ˈkɑːmpleks ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3602,'colloc-3-01',12,'complex pattern','mô hình phức tạp','adj + n','[{"en":"The data reveal a complex pattern of seasonal change.","vi":"Dữ liệu cho thấy một mô hình thay đổi theo mùa phức tạp."},{"en":"Migration follows a complex pattern shaped by many forces.","vi":"Di cư diễn ra theo mô hình phức tạp do nhiều yếu tố tạo nên."},{"en":"Researchers uncovered a complex pattern in the genetic data.","vi":"Các nhà nghiên cứu phát hiện một mô hình phức tạp trong dữ liệu di truyền."}]','[]',NULL,'/ˈkɑːmpleks ˈpætərn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3603,'colloc-3-01',13,'complex problem','bài toán phức tạp','adj + n','[{"en":"Climate change is a complex problem facing every nation.","vi":"Biến đổi khí hậu là một bài toán phức tạp với mọi quốc gia."},{"en":"Breaking a complex problem into steps makes it manageable.","vi":"Chia một bài toán phức tạp thành các bước giúp dễ xử lý hơn."},{"en":"The engineers solved a complex problem with a simple design.","vi":"Các kỹ sư giải một bài toán phức tạp bằng một thiết kế đơn giản."}]','[]',NULL,'/ˈkɑːmpleks ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3604,'colloc-3-01',14,'complex process','quá trình phức tạp','adj + n','[{"en":"Learning a language is a long and complex process.","vi":"Học một ngôn ngữ là một quá trình lâu dài và phức tạp."},{"en":"Digestion is a complex process involving several organs.","vi":"Tiêu hóa là một quá trình phức tạp liên quan đến nhiều cơ quan."},{"en":"The complex process of approval can take many months.","vi":"Quá trình phê duyệt phức tạp có thể mất nhiều tháng."}]','[]',NULL,'/ˈkɑːmpleks ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3605,'colloc-3-01',15,'complex question','câu hỏi phức tạp','adj + n','[{"en":"This is a complex question that deserves careful thought.","vi":"Đây là một câu hỏi phức tạp xứng đáng được suy nghĩ kỹ."},{"en":"The essay tackles the complex question of free will.","vi":"Bài luận giải quyết câu hỏi phức tạp về ý chí tự do."},{"en":"There is no easy answer to such a complex question.","vi":"Không có câu trả lời dễ dàng cho một câu hỏi phức tạp như vậy."}]','[]',NULL,'/ˈkɑːmpleks ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3606,'colloc-3-01',16,'complex relationship','mối quan hệ phức tạp','adj + n','[{"en":"There is a complex relationship between stress and illness.","vi":"Có một mối quan hệ phức tạp giữa căng thẳng và bệnh tật."},{"en":"The novel explores the complex relationship between the brothers.","vi":"Cuốn tiểu thuyết khám phá mối quan hệ phức tạp giữa hai anh em."},{"en":"Economics studies the complex relationship between supply and demand.","vi":"Kinh tế học nghiên cứu mối quan hệ phức tạp giữa cung và cầu."}]','[]',NULL,'/ˈkɑːmpleks rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3607,'colloc-3-01',17,'complex set','tập hợp phức tạp','adj + n','[{"en":"The rules form a complex set of legal obligations.","vi":"Các quy tắc tạo thành một tập hợp phức tạp các nghĩa vụ pháp lý."},{"en":"A complex set of factors shapes consumer behaviour.","vi":"Một tập hợp phức tạp các yếu tố định hình hành vi tiêu dùng."},{"en":"Pilots must follow a complex set of safety procedures.","vi":"Phi công phải tuân theo một tập hợp phức tạp các quy trình an toàn."}]','[]',NULL,'/ˈkɑːmpleks set/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3608,'colloc-3-01',18,'complex situation','tình huống phức tạp','adj + n','[{"en":"Managers must stay calm in a complex situation.","vi":"Các nhà quản lý phải bình tĩnh trong một tình huống phức tạp."},{"en":"The diplomat handled the complex situation with great skill.","vi":"Nhà ngoại giao xử lý tình huống phức tạp với kỹ năng tuyệt vời."},{"en":"This complex situation has no obvious right answer.","vi":"Tình huống phức tạp này không có câu trả lời đúng rõ ràng."}]','[]',NULL,'/ˈkɑːmpleks ˌsɪtʃuˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3609,'colloc-3-01',19,'complex structure','cấu trúc phức tạp','adj + n','[{"en":"The brain has an extremely complex structure.","vi":"Não bộ có một cấu trúc cực kỳ phức tạp."},{"en":"The molecule''s complex structure makes it hard to synthesize.","vi":"Cấu trúc phức tạp của phân tử khiến nó khó tổng hợp."},{"en":"The poem has a complex structure with shifting rhythms.","vi":"Bài thơ có một cấu trúc phức tạp với nhịp điệu biến đổi."}]','[]',NULL,'/ˈkɑːmpleks ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3610,'colloc-3-01',20,'complex system','hệ thống phức tạp','adj + n','[{"en":"The economy is a complex system with many moving parts.","vi":"Nền kinh tế là một hệ thống phức tạp với nhiều bộ phận vận động."},{"en":"Ecosystems are complex systems that respond to small changes.","vi":"Hệ sinh thái là những hệ thống phức tạp phản ứng với thay đổi nhỏ."},{"en":"Managing a complex system requires constant monitoring.","vi":"Quản lý một hệ thống phức tạp đòi hỏi giám sát liên tục."}]','[]',NULL,'/ˈkɑːmpleks ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3611,'colloc-3-01',21,'comprehensive account','bản tường thuật toàn diện','adj + n','[{"en":"The book offers a comprehensive account of the revolution.","vi":"Cuốn sách đưa ra một bản tường thuật toàn diện về cuộc cách mạng."},{"en":"She gave a comprehensive account of the experiment''s results.","vi":"Cô trình bày một bản tường thuật toàn diện về kết quả thí nghiệm."},{"en":"No single source provides a comprehensive account of events.","vi":"Không nguồn nào đưa ra bản tường thuật toàn diện về các sự kiện."}]','[]',NULL,'/ˌkɑːmprɪˈhensɪv əˈkaʊnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3612,'colloc-3-01',22,'comprehensive approach','cách tiếp cận toàn diện','adj + n','[{"en":"Tackling poverty requires a comprehensive approach.","vi":"Giải quyết nghèo đói đòi hỏi một cách tiếp cận toàn diện."},{"en":"The school adopted a comprehensive approach to student welfare.","vi":"Trường áp dụng cách tiếp cận toàn diện đối với phúc lợi học sinh."},{"en":"A comprehensive approach considers economic and social factors together.","vi":"Cách tiếp cận toàn diện xem xét cả yếu tố kinh tế và xã hội."}]','[]',NULL,'/ˌkɑːmprɪˈhensɪv əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3613,'colloc-3-01',23,'comprehensive overview','cái nhìn tổng quan toàn diện','adj + n','[{"en":"The first chapter gives a comprehensive overview of the field.","vi":"Chương đầu đưa ra cái nhìn tổng quan toàn diện về lĩnh vực này."},{"en":"Her lecture provided a comprehensive overview of recent research.","vi":"Bài giảng của cô cung cấp cái nhìn toàn diện về nghiên cứu gần đây."},{"en":"This guide offers a comprehensive overview for new employees.","vi":"Cẩm nang này cung cấp cái nhìn tổng quan toàn diện cho nhân viên mới."}]','[]',NULL,'/ˌkɑːmprɪˈhensɪv ˈoʊvərvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3614,'colloc-3-01',24,'comprehensive review','đánh giá toàn diện','adj + n','[{"en":"The committee conducted a comprehensive review of the policy.","vi":"Ủy ban tiến hành một cuộc đánh giá toàn diện về chính sách."},{"en":"The article provides a comprehensive review of the literature.","vi":"Bài viết cung cấp một đánh giá toàn diện về tài liệu nghiên cứu."},{"en":"A comprehensive review revealed several gaps in the system.","vi":"Một cuộc đánh giá toàn diện đã phát hiện nhiều lỗ hổng trong hệ thống."}]','[]',NULL,'/ˌkɑːmprɪˈhensɪv rɪˈvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3615,'colloc-3-01',25,'comprehensive system','hệ thống toàn diện','adj + n','[{"en":"The country built a comprehensive system of public healthcare.","vi":"Quốc gia này xây dựng một hệ thống y tế công toàn diện."},{"en":"A comprehensive system of checks prevents most errors.","vi":"Một hệ thống kiểm tra toàn diện ngăn chặn hầu hết sai sót."},{"en":"They developed a comprehensive system for tracking shipments.","vi":"Họ phát triển một hệ thống toàn diện để theo dõi các lô hàng."}]','[]',NULL,'/ˌkɑːmprɪˈhensɪv ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3616,'colloc-3-01',26,'conceptual framework','khung khái niệm','adj + n','[{"en":"The study is built on a clear conceptual framework.","vi":"Nghiên cứu được xây dựng trên một khung khái niệm rõ ràng."},{"en":"A solid conceptual framework guides the entire investigation.","vi":"Một khung khái niệm vững chắc định hướng toàn bộ cuộc điều tra."},{"en":"The authors propose a new conceptual framework for analysis.","vi":"Các tác giả đề xuất một khung khái niệm mới để phân tích."}]','[]',NULL,'/kənˈseptʃuəl ˈfreɪmwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3617,'colloc-3-01',27,'concerted effort','nỗ lực phối hợp','adj + n','[{"en":"A concerted effort is needed to reduce plastic waste.","vi":"Cần một nỗ lực phối hợp để giảm rác thải nhựa."},{"en":"Through a concerted effort, the team met the deadline.","vi":"Bằng một nỗ lực phối hợp, nhóm đã kịp hạn chót."},{"en":"Governments made a concerted effort to control the disease.","vi":"Các chính phủ đã nỗ lực phối hợp để kiểm soát dịch bệnh."}]','[]',NULL,'/kənˈsɜːrtɪd ˈefərt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3618,'colloc-3-01',28,'concluding remarks','lời nhận xét kết luận','adj + n','[{"en":"In her concluding remarks, she summarized the main findings.","vi":"Trong lời nhận xét kết luận, cô tóm tắt các phát hiện chính."},{"en":"The author''s concluding remarks point toward future research.","vi":"Lời nhận xét kết luận của tác giả hướng tới nghiên cứu tương lai."},{"en":"His concluding remarks were brief but memorable.","vi":"Lời nhận xét kết luận của ông ngắn gọn nhưng đáng nhớ."}]','[]',NULL,'/kənˈkluːdɪŋ rɪˈmɑːrks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3619,'colloc-3-01',29,'concluding section','phần kết luận','adj + n','[{"en":"The concluding section restates the paper''s central argument.","vi":"Phần kết luận nêu lại lập luận trung tâm của bài viết."},{"en":"In the concluding section, the author suggests further study.","vi":"Trong phần kết luận, tác giả gợi ý nghiên cứu thêm."},{"en":"The concluding section ties together the earlier chapters.","vi":"Phần kết luận liên kết các chương trước đó với nhau."}]','[]',NULL,'/kənˈkluːdɪŋ ˈsekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3620,'colloc-3-01',30,'concluding probability','xác suất kết luận','adj + n','[{"en":"The analysis yields a concluding probability for each outcome.","vi":"Phân tích đưa ra một xác suất kết luận cho mỗi kết quả."},{"en":"Researchers reported the concluding probability of the event.","vi":"Các nhà nghiên cứu báo cáo xác suất kết luận của sự kiện."},{"en":"A high concluding probability strengthens confidence in the model.","vi":"Xác suất kết luận cao làm tăng độ tin cậy vào mô hình."}]','[]',NULL,'/kənˈkluːdɪŋ ˌprɑːbəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3621,'colloc-3-01',31,'conduct research','tiến hành nghiên cứu','v + n','[{"en":"The university encourages students to conduct original research.","vi":"Trường đại học khuyến khích sinh viên tiến hành nghiên cứu độc lập."},{"en":"They conduct research on renewable energy sources.","vi":"Họ tiến hành nghiên cứu về các nguồn năng lượng tái tạo."},{"en":"Scientists conduct research to test their hypotheses carefully.","vi":"Các nhà khoa học tiến hành nghiên cứu để kiểm tra giả thuyết cẩn thận."}]','[]',NULL,'/kənˈdʌkt ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3622,'colloc-3-01',32,'conduct a study','tiến hành một nghiên cứu','v + n','[{"en":"Researchers will conduct a study on sleep and memory next year.","vi":"Các nhà nghiên cứu sẽ tiến hành một nghiên cứu về giấc ngủ và trí nhớ vào năm tới."},{"en":"We decided to conduct a study comparing two teaching methods.","vi":"Chúng tôi quyết định tiến hành một nghiên cứu so sánh hai phương pháp giảng dạy."},{"en":"The team conducted a study to measure customer satisfaction levels.","vi":"Nhóm đã tiến hành một nghiên cứu để đo mức độ hài lòng của khách hàng."}]','[]',NULL,'/kənˈdʌkt ə ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3623,'colloc-3-01',33,'conduct a survey','thực hiện một cuộc khảo sát','v + n','[{"en":"The university conducted a survey to learn about student needs.","vi":"Trường đại học đã thực hiện một cuộc khảo sát để tìm hiểu nhu cầu của sinh viên."},{"en":"We plan to conduct a survey among local small business owners.","vi":"Chúng tôi dự định thực hiện một cuộc khảo sát với các chủ doanh nghiệp nhỏ trong vùng."},{"en":"Before launching, the company conducted a survey of potential users.","vi":"Trước khi ra mắt, công ty đã thực hiện một cuộc khảo sát người dùng tiềm năng."}]','[]',NULL,'/kənˈdʌkt ə ˈsɜːrveɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3624,'colloc-3-01',34,'conduct an analysis','thực hiện một phân tích','v + n','[{"en":"The analysts conducted an analysis of last quarter''s sales data.","vi":"Các chuyên viên đã thực hiện một phân tích về dữ liệu bán hàng quý trước."},{"en":"We need to conduct an analysis before making any final decision.","vi":"Chúng ta cần thực hiện một phân tích trước khi đưa ra quyết định cuối cùng."},{"en":"She conducted an analysis to identify the main causes of failure.","vi":"Cô đã thực hiện một phân tích để xác định các nguyên nhân chính gây thất bại."}]','[]',NULL,'/kənˈdʌkt ən əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3625,'colloc-3-01',35,'conduct an interview','tiến hành một cuộc phỏng vấn','v + n','[{"en":"The journalist conducted an interview with the city''s new mayor.","vi":"Nhà báo đã tiến hành một cuộc phỏng vấn với thị trưởng mới của thành phố."},{"en":"Researchers conducted an interview with each participant separately.","vi":"Các nhà nghiên cứu đã tiến hành một cuộc phỏng vấn riêng với từng người tham gia."},{"en":"We will conduct an interview to understand their daily routines.","vi":"Chúng tôi sẽ tiến hành một cuộc phỏng vấn để hiểu thói quen hằng ngày của họ."}]','[]',NULL,'/kənˈdʌkt ən ˈɪntərvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3626,'colloc-3-01',36,'conflict resolution','giải quyết xung đột','n + n','[{"en":"Good managers need strong conflict resolution skills at work.","vi":"Người quản lý giỏi cần có kỹ năng giải quyết xung đột tốt trong công việc."},{"en":"The course teaches conflict resolution through real-life case studies.","vi":"Khóa học dạy giải quyết xung đột qua các tình huống thực tế."},{"en":"Conflict resolution often requires patience and careful listening.","vi":"Giải quyết xung đột thường đòi hỏi sự kiên nhẫn và lắng nghe cẩn thận."}]','[]',NULL,'/ˈkɑːnflɪkt ˌrezəˈluːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3627,'colloc-3-01',37,'conflicting interests','những lợi ích xung đột nhau','adj + n','[{"en":"The two departments have conflicting interests over the new budget.","vi":"Hai phòng ban có những lợi ích xung đột nhau về ngân sách mới."},{"en":"Negotiators must balance conflicting interests to reach an agreement.","vi":"Các nhà đàm phán phải cân bằng những lợi ích xung đột để đạt thỏa thuận."},{"en":"Conflicting interests among shareholders delayed the final decision.","vi":"Những lợi ích xung đột giữa các cổ đông đã trì hoãn quyết định cuối cùng."}]','[]',NULL,'/kənˈflɪktɪŋ ˈɪntrəsts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3628,'colloc-3-01',38,'consider appropriate','cho là phù hợp','v + adj','[{"en":"Teachers may use whatever methods they consider appropriate for the class.","vi":"Giáo viên có thể dùng bất kỳ phương pháp nào họ cho là phù hợp với lớp."},{"en":"The committee will take any action it considers appropriate.","vi":"Ủy ban sẽ thực hiện bất kỳ hành động nào họ cho là phù hợp."},{"en":"Please dress in a way you consider appropriate for the interview.","vi":"Hãy ăn mặc theo cách mà bạn cho là phù hợp cho buổi phỏng vấn."}]','[]',NULL,'/kənˈsɪdər əˈproʊpriət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3629,'colloc-3-01',39,'consider relevant','cho là có liên quan','v + adj','[{"en":"Include only the details you consider relevant to your argument.","vi":"Chỉ đưa vào những chi tiết mà bạn cho là có liên quan đến luận điểm."},{"en":"The judge will examine any evidence she considers relevant to the case.","vi":"Thẩm phán sẽ xem xét bất kỳ bằng chứng nào bà cho là có liên quan đến vụ án."},{"en":"Readers may skip sections they do not consider relevant.","vi":"Người đọc có thể bỏ qua các phần họ không cho là có liên quan."}]','[]',NULL,'/kənˈsɪdər ˈreləvənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3630,'colloc-3-01',40,'consider a possibility','xem xét một khả năng','v + n','[{"en":"We should consider a possibility that no one has examined yet.","vi":"Chúng ta nên xem xét một khả năng mà chưa ai khảo sát đến."},{"en":"The board agreed to consider a possibility of merging the two teams.","vi":"Hội đồng đồng ý xem xét một khả năng sáp nhập hai nhóm."},{"en":"Scientists must consider a possibility before rejecting any theory.","vi":"Các nhà khoa học phải xem xét một khả năng trước khi bác bỏ lý thuyết nào."}]','[]',NULL,'/kənˈsɪdər ə ˌpɑːsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3631,'colloc-3-01',41,'consider an aspect','xem xét một khía cạnh','v + n','[{"en":"The essay fails to consider an aspect central to the debate.","vi":"Bài luận không xem xét một khía cạnh trung tâm của cuộc tranh luận."},{"en":"Let us consider an aspect of the problem we often overlook.","vi":"Hãy xem xét một khía cạnh của vấn đề mà chúng ta thường bỏ qua."},{"en":"Good planners consider an aspect of cost at every stage.","vi":"Người lập kế hoạch giỏi xem xét một khía cạnh chi phí ở mọi giai đoạn."}]','[]',NULL,'/kənˈsɪdər ən ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3632,'colloc-3-01',42,'consider an issue','xem xét một vấn đề','v + n','[{"en":"The council will consider an issue raised by local residents.","vi":"Hội đồng sẽ xem xét một vấn đề do người dân địa phương nêu ra."},{"en":"We must consider an issue from several different points of view.","vi":"Chúng ta phải xem xét một vấn đề từ nhiều góc nhìn khác nhau."},{"en":"The chapter helps readers consider an issue more deeply.","vi":"Chương này giúp người đọc xem xét một vấn đề sâu sắc hơn."}]','[]',NULL,'/kənˈsɪdər ən ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3633,'colloc-3-01',43,'consider the impact of','cân nhắc tác động của','v + n','[{"en":"Planners must consider the impact of the new road on traffic.","vi":"Người quy hoạch phải cân nhắc tác động của con đường mới đến giao thông."},{"en":"The report asks us to consider the impact of climate change.","vi":"Báo cáo yêu cầu chúng ta cân nhắc tác động của biến đổi khí hậu."},{"en":"We should consider the impact of these cuts on poorer families.","vi":"Chúng ta nên cân nhắc tác động của những khoản cắt giảm này lên các gia đình nghèo."}]','[]',NULL,'/kənˈsɪdər ði ˈɪmpækt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3634,'colloc-3-01',44,'consider the implications','cân nhắc những hệ quả','v + n','[{"en":"Before voting, members should consider the implications of the proposal.","vi":"Trước khi bỏ phiếu, các thành viên nên cân nhắc những hệ quả của đề xuất."},{"en":"The author asks readers to consider the implications for future policy.","vi":"Tác giả yêu cầu người đọc cân nhắc những hệ quả đối với chính sách tương lai."},{"en":"We failed to consider the implications of releasing the data early.","vi":"Chúng tôi đã không cân nhắc những hệ quả của việc công bố dữ liệu sớm."}]','[]',NULL,'/kənˈsɪdər ði ˌɪmplɪˈkeɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3635,'colloc-3-01',45,'consider the role of','xem xét vai trò của','v + n','[{"en":"The lecture asks us to consider the role of luck in success.","vi":"Bài giảng yêu cầu chúng ta xem xét vai trò của may mắn trong thành công."},{"en":"We must consider the role of teachers in shaping young minds.","vi":"Chúng ta phải xem xét vai trò của giáo viên trong việc định hình tư duy trẻ."},{"en":"Historians consider the role of trade in building early cities.","vi":"Các nhà sử học xem xét vai trò của thương mại trong việc xây dựng các thành phố cổ."}]','[]',NULL,'/kənˈsɪdər ðə roʊl əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3636,'colloc-3-01',46,'considerable amount of','một lượng đáng kể','adj + n','[{"en":"The project required a considerable amount of time and money.","vi":"Dự án đòi hỏi một lượng đáng kể thời gian và tiền bạc."},{"en":"She spent a considerable amount of effort on the final report.","vi":"Cô đã bỏ ra một lượng đáng kể công sức cho bản báo cáo cuối cùng."},{"en":"A considerable amount of data was lost during the system failure.","vi":"Một lượng đáng kể dữ liệu đã bị mất trong sự cố hệ thống."}]','[]',NULL,'/kənˈsɪdərəbəl əˈmaʊnt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3637,'colloc-3-01',47,'considerable attention','sự chú ý đáng kể','adj + n','[{"en":"The new theory has attracted considerable attention from scientists.","vi":"Lý thuyết mới đã thu hút sự chú ý đáng kể từ các nhà khoa học."},{"en":"This issue deserves considerable attention in future research.","vi":"Vấn đề này xứng đáng nhận được sự chú ý đáng kể trong nghiên cứu sau này."},{"en":"The film received considerable attention after the awards ceremony.","vi":"Bộ phim nhận được sự chú ý đáng kể sau lễ trao giải."}]','[]',NULL,'/kənˈsɪdərəbəl əˈtenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3638,'colloc-3-01',48,'considerable debate','cuộc tranh luận đáng kể','adj + n','[{"en":"There is considerable debate about the causes of the decline.","vi":"Có một cuộc tranh luận đáng kể về nguyên nhân của sự suy giảm."},{"en":"The proposal sparked considerable debate among local officials.","vi":"Đề xuất đã làm dấy lên cuộc tranh luận đáng kể giữa các quan chức địa phương."},{"en":"Considerable debate surrounds the best way to teach reading.","vi":"Cuộc tranh luận đáng kể xoay quanh cách tốt nhất để dạy đọc."}]','[]',NULL,'/kənˈsɪdərəbəl dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3639,'colloc-3-01',49,'considerable degree of','một mức độ đáng kể của','adj + n','[{"en":"The task demands a considerable degree of skill and patience.","vi":"Nhiệm vụ đòi hỏi một mức độ đáng kể về kỹ năng và sự kiên nhẫn."},{"en":"Workers enjoy a considerable degree of freedom in this company.","vi":"Nhân viên được hưởng một mức độ tự do đáng kể trong công ty này."},{"en":"The results show a considerable degree of variation between groups.","vi":"Kết quả cho thấy một mức độ khác biệt đáng kể giữa các nhóm."}]','[]',NULL,'/kənˈsɪdərəbəl dɪˈɡriː əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3640,'colloc-3-01',50,'considerable detail','sự chi tiết đáng kể','adj + n','[{"en":"The author describes each method in considerable detail.","vi":"Tác giả mô tả từng phương pháp với sự chi tiết đáng kể."},{"en":"The report covers the budget in considerable detail.","vi":"Báo cáo trình bày ngân sách với sự chi tiết đáng kể."},{"en":"She explained the procedure in considerable detail for beginners.","vi":"Cô đã giải thích quy trình rất chi tiết cho người mới bắt đầu."}]','[]',NULL,'/kənˈsɪdərəbəl ˈdiːteɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3641,'colloc-3-01',51,'considerable effort','công sức đáng kể','adj + n','[{"en":"It took considerable effort to finish the thesis on time.","vi":"Phải mất công sức đáng kể mới hoàn thành luận văn đúng hạn."},{"en":"The team put considerable effort into improving the website.","vi":"Nhóm đã bỏ công sức đáng kể để cải thiện trang web."},{"en":"Considerable effort is needed to change such old habits.","vi":"Cần công sức đáng kể để thay đổi những thói quen cũ như vậy."}]','[]',NULL,'/kənˈsɪdərəbəl ˈefərt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3642,'colloc-3-01',52,'considerable evidence','bằng chứng đáng kể','adj + n','[{"en":"There is considerable evidence linking exercise to better health.","vi":"Có bằng chứng đáng kể liên hệ tập thể dục với sức khỏe tốt hơn."},{"en":"Considerable evidence suggests the policy reduced crime rates.","vi":"Bằng chứng đáng kể cho thấy chính sách đã làm giảm tỷ lệ tội phạm."},{"en":"The study collected considerable evidence over five long years.","vi":"Nghiên cứu đã thu thập bằng chứng đáng kể trong suốt năm năm dài."}]','[]',NULL,'/kənˈsɪdərəbəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3643,'colloc-3-01',53,'considerable extent','mức độ đáng kể','adj + n','[{"en":"To a considerable extent, the project''s success depended on funding.","vi":"Ở một mức độ đáng kể, thành công của dự án phụ thuộc vào nguồn vốn."},{"en":"Her work shaped the field to a considerable extent.","vi":"Công trình của bà đã định hình lĩnh vực ở một mức độ đáng kể."},{"en":"The outcome reflects the local culture to a considerable extent.","vi":"Kết quả phản ánh văn hóa địa phương ở một mức độ đáng kể."}]','[]',NULL,'/kənˈsɪdərəbəl ɪkˈstent/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3644,'colloc-3-01',54,'considerable importance','tầm quan trọng đáng kể','adj + n','[{"en":"These findings are of considerable importance to medical research.","vi":"Những phát hiện này có tầm quan trọng đáng kể đối với nghiên cứu y học."},{"en":"The treaty held considerable importance for both countries.","vi":"Hiệp ước có tầm quan trọng đáng kể đối với cả hai quốc gia."},{"en":"Early education is of considerable importance for later success.","vi":"Giáo dục sớm có tầm quan trọng đáng kể đối với thành công về sau."}]','[]',NULL,'/kənˈsɪdərəbəl ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3645,'colloc-3-01',55,'considerable influence','ảnh hưởng đáng kể','adj + n','[{"en":"The teacher had a considerable influence on my career choices.","vi":"Người thầy đã có ảnh hưởng đáng kể đến lựa chọn nghề nghiệp của tôi."},{"en":"Media exerts considerable influence over public opinion today.","vi":"Truyền thông tạo ảnh hưởng đáng kể lên dư luận ngày nay."},{"en":"Her writing exerted considerable influence on later philosophers.","vi":"Trước tác của bà có ảnh hưởng đáng kể đến các triết gia về sau."}]','[]',NULL,'/kənˈsɪdərəbəl ˈɪnfluəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3646,'colloc-3-01',56,'considerable interest','sự quan tâm đáng kể','adj + n','[{"en":"The discovery generated considerable interest among biologists.","vi":"Phát hiện đã tạo ra sự quan tâm đáng kể trong giới sinh học."},{"en":"There is considerable interest in renewable energy these days.","vi":"Hiện nay có sự quan tâm đáng kể đến năng lượng tái tạo."},{"en":"The lecture attracted considerable interest from local students.","vi":"Buổi giảng đã thu hút sự quan tâm đáng kể từ sinh viên địa phương."}]','[]',NULL,'/kənˈsɪdərəbəl ˈɪntrəst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3647,'colloc-3-01',57,'considerable research','nghiên cứu đáng kể','adj + n','[{"en":"Considerable research has examined how children learn languages.","vi":"Đã có nghiên cứu đáng kể khảo sát cách trẻ em học ngôn ngữ."},{"en":"The claim is supported by considerable research over decades.","vi":"Khẳng định này được hỗ trợ bởi nghiên cứu đáng kể qua nhiều thập kỷ."},{"en":"Considerable research is still needed to confirm these results.","vi":"Vẫn cần nghiên cứu đáng kể để xác nhận những kết quả này."}]','[]',NULL,'/kənˈsɪdərəbəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3648,'colloc-3-01',58,'considerable support','sự ủng hộ đáng kể','adj + n','[{"en":"The plan received considerable support from local community groups.","vi":"Kế hoạch nhận được sự ủng hộ đáng kể từ các nhóm cộng đồng địa phương."},{"en":"There is considerable support for reforming the exam system.","vi":"Có sự ủng hộ đáng kể cho việc cải cách hệ thống thi cử."},{"en":"Considerable support exists for protecting the old forest.","vi":"Tồn tại sự ủng hộ đáng kể cho việc bảo vệ khu rừng cổ."}]','[]',NULL,'/kənˈsɪdərəbəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3649,'colloc-3-01',59,'considerable variation','sự khác biệt đáng kể','adj + n','[{"en":"There is considerable variation in rainfall across the region.","vi":"Có sự khác biệt đáng kể về lượng mưa trên khắp khu vực."},{"en":"The data showed considerable variation between the two samples.","vi":"Dữ liệu cho thấy sự khác biệt đáng kể giữa hai mẫu."},{"en":"Prices reveal considerable variation from one city to another.","vi":"Giá cả cho thấy sự khác biệt đáng kể giữa thành phố này với thành phố khác."}]','[]',NULL,'/kənˈsɪdərəbəl ˌveriˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3650,'colloc-3-01',60,'consistent pattern','khuôn mẫu nhất quán','adj + n','[{"en":"The survey revealed a consistent pattern of late payments.","vi":"Cuộc khảo sát cho thấy một khuôn mẫu nhất quán về việc trả tiền muộn."},{"en":"Researchers found a consistent pattern across all five studies.","vi":"Các nhà nghiên cứu tìm thấy một khuôn mẫu nhất quán qua cả năm nghiên cứu."},{"en":"A consistent pattern of growth appeared over the last decade.","vi":"Một khuôn mẫu tăng trưởng nhất quán xuất hiện trong thập kỷ qua."}]','[]',NULL,'/kənˈsɪstənt ˈpætərn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3651,'colloc-3-01',61,'consistent results','kết quả nhất quán','adj + n','[{"en":"The experiment produced consistent results across many trials.","vi":"Thí nghiệm đã cho ra kết quả nhất quán qua nhiều lần thử."},{"en":"Consistent results give us confidence in the new method.","vi":"Kết quả nhất quán giúp chúng ta tự tin vào phương pháp mới."},{"en":"Both teams reported consistent results despite different conditions.","vi":"Cả hai nhóm đều báo cáo kết quả nhất quán dù điều kiện khác nhau."}]','[]',NULL,'/kənˈsɪstənt rɪˈzʌlts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3652,'colloc-3-01',62,'constant rate','tốc độ không đổi','adj + n','[{"en":"The chemical reaction proceeded at a constant rate throughout.","vi":"Phản ứng hóa học diễn ra với tốc độ không đổi suốt quá trình."},{"en":"The population grew at a constant rate for several years.","vi":"Dân số tăng với tốc độ không đổi trong vài năm."},{"en":"Water flowed from the tank at a constant rate.","vi":"Nước chảy ra khỏi bể với tốc độ không đổi."}]','[]',NULL,'/ˈkɑːnstənt reɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3653,'colloc-3-01',63,'constituent elements','các thành phần cấu thành','adj + n','[{"en":"Scientists studied the constituent elements of the unknown rock.","vi":"Các nhà khoa học đã nghiên cứu các thành phần cấu thành của loại đá lạ."},{"en":"The essay breaks the argument into its constituent elements.","vi":"Bài luận chia luận điểm thành các thành phần cấu thành của nó."},{"en":"Understanding the constituent elements helps explain the whole system.","vi":"Hiểu các thành phần cấu thành giúp giải thích toàn bộ hệ thống."}]','[]',NULL,'/kənˈstɪtʃuənt ˈeləmənts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3654,'colloc-3-01',64,'constituent parts','các bộ phận cấu thành','adj + n','[{"en":"Engineers examined the machine''s constituent parts one by one.","vi":"Các kỹ sư đã kiểm tra các bộ phận cấu thành của máy từng cái một."},{"en":"We can analyze the theory by separating its constituent parts.","vi":"Ta có thể phân tích lý thuyết bằng cách tách các bộ phận cấu thành của nó."},{"en":"The model shows how the constituent parts fit together.","vi":"Mô hình cho thấy các bộ phận cấu thành ghép với nhau như thế nào."}]','[]',NULL,'/kənˈstɪtʃuənt pɑːrts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3655,'colloc-3-01',65,'contain information','chứa thông tin','v + n','[{"en":"The report contains information about every department''s spending.","vi":"Báo cáo chứa thông tin về chi tiêu của từng phòng ban."},{"en":"This file contains information that should remain confidential.","vi":"Tệp này chứa thông tin cần được giữ bí mật."},{"en":"The website contains information for both students and parents.","vi":"Trang web chứa thông tin cho cả sinh viên lẫn phụ huynh."}]','[]',NULL,'/kənˈteɪn ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3656,'colloc-3-01',66,'contain an element','chứa một yếu tố','v + n','[{"en":"Most successful stories contain an element of surprise.","vi":"Hầu hết câu chuyện thành công đều chứa một yếu tố bất ngờ."},{"en":"The plan contains an element of risk we cannot ignore.","vi":"Kế hoạch chứa một yếu tố rủi ro mà ta không thể bỏ qua."},{"en":"Her argument contains an element of truth worth considering.","vi":"Lập luận của cô chứa một yếu tố sự thật đáng để cân nhắc."}]','[]',NULL,'/kənˈteɪn ən ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3657,'colloc-3-01',67,'contemporary debate','cuộc tranh luận đương đại','adj + n','[{"en":"The book engages with contemporary debate on free speech.","vi":"Cuốn sách tham gia vào cuộc tranh luận đương đại về tự do ngôn luận."},{"en":"Privacy is a major theme in contemporary debate about technology.","vi":"Quyền riêng tư là chủ đề lớn trong cuộc tranh luận đương đại về công nghệ."},{"en":"Her research contributes to contemporary debate on inequality.","vi":"Nghiên cứu của bà đóng góp vào cuộc tranh luận đương đại về bất bình đẳng."}]','[]',NULL,'/kənˈtempəreri dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3658,'colloc-3-01',68,'contemporary issue','vấn đề đương đại','adj + n','[{"en":"The class discusses one contemporary issue every week.","vi":"Lớp học thảo luận về một vấn đề đương đại mỗi tuần."},{"en":"Climate change is the defining contemporary issue of our age.","vi":"Biến đổi khí hậu là vấn đề đương đại tiêu biểu của thời đại chúng ta."},{"en":"Students chose a contemporary issue for their final project.","vi":"Sinh viên đã chọn một vấn đề đương đại cho dự án cuối khóa."}]','[]',NULL,'/kənˈtempəreri ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3659,'colloc-3-01',69,'contemporary life','đời sống đương đại','adj + n','[{"en":"Technology has transformed almost every part of contemporary life.","vi":"Công nghệ đã thay đổi gần như mọi mặt của đời sống đương đại."},{"en":"The novel paints a vivid picture of contemporary life.","vi":"Cuốn tiểu thuyết vẽ nên bức tranh sống động về đời sống đương đại."},{"en":"Stress is often described as a feature of contemporary life.","vi":"Căng thẳng thường được mô tả là một đặc điểm của đời sống đương đại."}]','[]',NULL,'/kənˈtempəreri laɪf/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3660,'colloc-3-01',70,'contemporary society','xã hội đương đại','adj + n','[{"en":"Social media plays a central role in contemporary society.","vi":"Mạng xã hội đóng vai trò trung tâm trong xã hội đương đại."},{"en":"The essay examines inequality within contemporary society.","vi":"Bài luận khảo sát sự bất bình đẳng trong xã hội đương đại."},{"en":"Contemporary society faces many challenges around privacy.","vi":"Xã hội đương đại đối mặt với nhiều thách thức về quyền riêng tư."}]','[]',NULL,'/kənˈtempəreri səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3661,'colloc-3-01',71,'contemporary world','thế giới đương đại','adj + n','[{"en":"Global trade connects every corner of the contemporary world.","vi":"Thương mại toàn cầu kết nối mọi ngóc ngách của thế giới đương đại."},{"en":"The contemporary world depends heavily on digital communication.","vi":"Thế giới đương đại phụ thuộc nhiều vào giao tiếp số."},{"en":"Migration is a defining feature of the contemporary world.","vi":"Di cư là một đặc điểm tiêu biểu của thế giới đương đại."}]','[]',NULL,'/kənˈtempəreri wɜːrld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3662,'colloc-3-01',72,'contextual factors','các yếu tố bối cảnh','adj + n','[{"en":"Contextual factors such as culture shape how people respond.","vi":"Các yếu tố bối cảnh như văn hóa định hình cách con người phản ứng."},{"en":"Researchers must account for contextual factors in their analysis.","vi":"Các nhà nghiên cứu phải tính đến các yếu tố bối cảnh trong phân tích."},{"en":"The outcome depends on several contextual factors at the school.","vi":"Kết quả phụ thuộc vào nhiều yếu tố bối cảnh tại trường học."}]','[]',NULL,'/kənˈtekstʃuəl ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3663,'colloc-3-01',73,'continued existence','sự tồn tại tiếp diễn','adj + n','[{"en":"Pollution threatens the continued existence of many species.","vi":"Ô nhiễm đe dọa sự tồn tại tiếp diễn của nhiều loài."},{"en":"Funding is essential for the continued existence of the museum.","vi":"Nguồn vốn rất cần thiết cho sự tồn tại tiếp diễn của bảo tàng."},{"en":"The treaty ensures the continued existence of the small nation.","vi":"Hiệp ước bảo đảm sự tồn tại tiếp diễn của quốc gia nhỏ."}]','[]',NULL,'/kənˈtɪnjuːd ɪɡˈzɪstəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3664,'colloc-3-01',74,'continued growth','sự tăng trưởng liên tục','adj + n','[{"en":"The company expects continued growth in overseas markets.","vi":"Công ty kỳ vọng sự tăng trưởng liên tục ở thị trường nước ngoài."},{"en":"Continued growth depends on investment in new technology.","vi":"Sự tăng trưởng liên tục phụ thuộc vào đầu tư cho công nghệ mới."},{"en":"The city has seen continued growth in its population.","vi":"Thành phố đã chứng kiến sự tăng trưởng liên tục về dân số."}]','[]',NULL,'/kənˈtɪnjuːd ɡroʊθ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3665,'colloc-3-01',75,'continued use','việc tiếp tục sử dụng','adj + n','[{"en":"The continued use of plastic harms the marine environment.","vi":"Việc tiếp tục sử dụng nhựa gây hại cho môi trường biển."},{"en":"Doctors warned against the continued use of the old drug.","vi":"Bác sĩ cảnh báo việc tiếp tục sử dụng loại thuốc cũ."},{"en":"Continued use of the software requires a yearly license.","vi":"Việc tiếp tục sử dụng phần mềm cần có giấy phép hằng năm."}]','[]',NULL,'/kənˈtɪnjuːd juːs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3666,'colloc-3-01',76,'continuous process','quá trình liên tục','adj + n','[{"en":"Learning a language is a continuous process, not a single event.","vi":"Học một ngôn ngữ là quá trình liên tục, không phải một sự kiện đơn lẻ."},{"en":"Quality control is a continuous process throughout production.","vi":"Kiểm soát chất lượng là quá trình liên tục trong suốt sản xuất."},{"en":"Improvement at the factory is treated as a continuous process.","vi":"Việc cải tiến tại nhà máy được xem là một quá trình liên tục."}]','[]',NULL,'/kənˈtɪnjuəs ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3667,'colloc-3-01',77,'contribute significantly','đóng góp đáng kể','v + adv','[{"en":"Volunteers contribute significantly to the success of the festival.","vi":"Các tình nguyện viên đóng góp đáng kể vào thành công của lễ hội."},{"en":"Small businesses contribute significantly to the local economy.","vi":"Các doanh nghiệp nhỏ đóng góp đáng kể vào nền kinh tế địa phương."},{"en":"Her research contributed significantly to our understanding of memory.","vi":"Nghiên cứu của bà đóng góp đáng kể vào hiểu biết của ta về trí nhớ."}]','[]',NULL,'/kənˈtrɪbjuːt sɪɡˈnɪfɪkəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3668,'colloc-3-01',78,'contribute to the development of','góp phần vào sự phát triển của','v + n','[{"en":"Reading widely contributes to the development of strong writing.","vi":"Đọc nhiều góp phần vào sự phát triển của kỹ năng viết tốt."},{"en":"Trade contributed to the development of early coastal towns.","vi":"Thương mại đã góp phần vào sự phát triển của các thị trấn ven biển sơ khai."},{"en":"Good teachers contribute to the development of a child''s confidence.","vi":"Giáo viên giỏi góp phần vào sự phát triển sự tự tin của trẻ."}]','[]',NULL,'/kənˈtrɪbjuːt tə ðə dɪˈveləpmənt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3669,'colloc-3-01',79,'controversial issue','vấn đề gây tranh cãi','adj + n','[{"en":"Immigration remains a controversial issue in many countries.","vi":"Nhập cư vẫn là một vấn đề gây tranh cãi ở nhiều quốc gia."},{"en":"The debate focused on a controversial issue in education policy.","vi":"Cuộc tranh luận tập trung vào một vấn đề gây tranh cãi trong chính sách giáo dục."},{"en":"Writing about a controversial issue requires careful, balanced evidence.","vi":"Viết về vấn đề gây tranh cãi đòi hỏi bằng chứng cẩn thận, cân bằng."}]','[]',NULL,'/ˌkɑːntrəˈvɜːrʃəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3670,'colloc-3-01',80,'conventional view','quan điểm thông thường','adj + n','[{"en":"The study challenges the conventional view of how memory works.","vi":"Nghiên cứu thách thức quan điểm thông thường về cách trí nhớ hoạt động."},{"en":"The conventional view assumes that growth always benefits everyone.","vi":"Quan điểm thông thường cho rằng tăng trưởng luôn có lợi cho mọi người."},{"en":"Her findings cast doubt on the conventional view of leadership.","vi":"Phát hiện của bà gieo nghi ngờ về quan điểm thông thường về lãnh đạo."}]','[]',NULL,'/kənˈvenʃənəl vjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3671,'colloc-3-01',81,'conventional wisdom','lối nghĩ thông thường','adj + n','[{"en":"Conventional wisdom says that practice always leads to perfection.","vi":"Lối nghĩ thông thường cho rằng luyện tập luôn dẫn đến hoàn hảo."},{"en":"The author questions conventional wisdom about healthy eating.","vi":"Tác giả đặt câu hỏi về lối nghĩ thông thường liên quan đến ăn uống lành mạnh."},{"en":"New data overturned the conventional wisdom on the subject.","vi":"Dữ liệu mới đã lật đổ lối nghĩ thông thường về chủ đề này."}]','[]',NULL,'/kənˈvenʃənəl ˈwɪzdəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3672,'colloc-3-01',82,'convey information','truyền tải thông tin','v + n','[{"en":"Clear graphs convey information faster than long paragraphs.","vi":"Biểu đồ rõ ràng truyền tải thông tin nhanh hơn những đoạn văn dài."},{"en":"The signs convey information to drivers who do not stop.","vi":"Các biển báo truyền tải thông tin cho tài xế không dừng lại."},{"en":"A good summary should convey information accurately and briefly.","vi":"Một bản tóm tắt tốt cần truyền tải thông tin chính xác và ngắn gọn."}]','[]',NULL,'/kənˈveɪ ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3673,'colloc-3-01',83,'convey meaning','truyền đạt ý nghĩa','v + n','[{"en":"Gestures can convey meaning even when words are not used.","vi":"Cử chỉ có thể truyền đạt ý nghĩa ngay cả khi không dùng từ ngữ."},{"en":"A skilled translator must convey meaning, not just words.","vi":"Một dịch giả giỏi phải truyền đạt ý nghĩa, không chỉ chuyển từ ngữ."},{"en":"Colors in the painting convey meaning about the artist''s mood.","vi":"Màu sắc trong bức tranh truyền đạt ý nghĩa về tâm trạng của họa sĩ."}]','[]',NULL,'/kənˈveɪ ˈmiːnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3674,'colloc-3-01',84,'convey a message','truyền tải một thông điệp','v + n','[{"en":"The advertisement tries to convey a message about saving water.","vi":"Mẩu quảng cáo cố truyền tải một thông điệp về tiết kiệm nước."},{"en":"Speakers must convey a message clearly to a large audience.","vi":"Người nói phải truyền tải một thông điệp rõ ràng đến đông khán giả."},{"en":"The film conveys a message about kindness and forgiveness.","vi":"Bộ phim truyền tải một thông điệp về lòng tốt và sự tha thứ."}]','[]',NULL,'/kənˈveɪ ə ˈmesɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3675,'colloc-3-01',85,'convincing evidence','bằng chứng thuyết phục','adj + n','[{"en":"The lawyer presented convincing evidence to support her claim.","vi":"Luật sư đã đưa ra bằng chứng thuyết phục để củng cố lập luận của mình."},{"en":"There is convincing evidence that exercise improves mental health.","vi":"Có bằng chứng thuyết phục rằng tập thể dục cải thiện sức khỏe tinh thần."},{"en":"Without convincing evidence, the theory will not be accepted.","vi":"Không có bằng chứng thuyết phục, lý thuyết sẽ không được chấp nhận."}]','[]',NULL,'/kənˈvɪnsɪŋ ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3676,'colloc-3-01',86,'coping strategy','chiến lược ứng phó','adj + n','[{"en":"Deep breathing is a simple coping strategy for stress.","vi":"Hít thở sâu là một chiến lược ứng phó đơn giản với căng thẳng."},{"en":"The counselor taught students a useful coping strategy for exams.","vi":"Chuyên viên tư vấn đã dạy sinh viên một chiến lược ứng phó hữu ích cho kỳ thi."},{"en":"Everyone needs a healthy coping strategy during difficult times.","vi":"Ai cũng cần một chiến lược ứng phó lành mạnh trong những lúc khó khăn."}]','[]',NULL,'/ˈkoʊpɪŋ ˈstrætədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3677,'colloc-3-01',87,'core area','lĩnh vực cốt lõi','adj + n','[{"en":"Mathematics is a core area of study in this program.","vi":"Toán học là một lĩnh vực cốt lõi trong chương trình này."},{"en":"The company decided to focus on its core area of expertise.","vi":"Công ty quyết định tập trung vào lĩnh vực chuyên môn cốt lõi của mình."},{"en":"Customer service remains a core area for the whole team.","vi":"Dịch vụ khách hàng vẫn là lĩnh vực cốt lõi của cả nhóm."}]','[]',NULL,'/kɔːr ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3678,'colloc-3-01',88,'core element','yếu tố cốt lõi','adj + n','[{"en":"Trust is a core element of any lasting friendship.","vi":"Niềm tin là yếu tố cốt lõi của bất kỳ tình bạn lâu bền nào."},{"en":"Feedback is a core element of the new training program.","vi":"Phản hồi là một yếu tố cốt lõi của chương trình đào tạo mới."},{"en":"Safety is treated as a core element of the design.","vi":"An toàn được xem là một yếu tố cốt lõi của thiết kế."}]','[]',NULL,'/kɔːr ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3679,'colloc-3-01',89,'core issue','vấn đề cốt lõi','adj + n','[{"en":"The core issue is whether the plan can be funded.","vi":"Vấn đề cốt lõi là liệu kế hoạch có thể được cấp vốn hay không."},{"en":"Let us return to the core issue of the discussion.","vi":"Hãy quay lại vấn đề cốt lõi của cuộc thảo luận."},{"en":"Fairness is the core issue behind the workers'' complaints.","vi":"Công bằng là vấn đề cốt lõi đằng sau những lời phàn nàn của công nhân."}]','[]',NULL,'/kɔːr ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3680,'colloc-3-01',90,'core skills','kỹ năng cốt lõi','adj + n','[{"en":"Reading and writing are core skills for academic success.","vi":"Đọc và viết là những kỹ năng cốt lõi cho thành công học thuật."},{"en":"The course aims to build core skills in problem solving.","vi":"Khóa học nhằm xây dựng kỹ năng cốt lõi trong giải quyết vấn đề."},{"en":"Employers expect graduates to have strong core skills.","vi":"Nhà tuyển dụng kỳ vọng sinh viên tốt nghiệp có kỹ năng cốt lõi vững."}]','[]',NULL,'/kɔːr skɪlz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3681,'colloc-3-01',91,'core value','giá trị cốt lõi','adj + n','[{"en":"Honesty is a core value the company expects from everyone.","vi":"Trung thực là một giá trị cốt lõi mà công ty kỳ vọng ở mọi người."},{"en":"Respect for others remains a core value at this school.","vi":"Tôn trọng người khác vẫn là một giá trị cốt lõi tại trường này."},{"en":"The charity built its work around one clear core value.","vi":"Tổ chức từ thiện xây dựng công việc quanh một giá trị cốt lõi rõ ràng."}]','[]',NULL,'/kɔːr ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3682,'colloc-3-01',92,'correct interpretation','cách diễn giải đúng','adj + n','[{"en":"Finding the correct interpretation of the data took several weeks.","vi":"Tìm ra cách diễn giải đúng của dữ liệu mất vài tuần."},{"en":"Scholars still argue about the correct interpretation of the text.","vi":"Các học giả vẫn tranh luận về cách diễn giải đúng của văn bản."},{"en":"A correct interpretation depends on understanding the full context.","vi":"Cách diễn giải đúng phụ thuộc vào việc hiểu toàn bộ bối cảnh."}]','[]',NULL,'/kəˈrekt ɪnˌtɜːrprɪˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3683,'colloc-3-01',93,'correct an error','sửa một lỗi','v + n','[{"en":"The editor took an hour to correct an error in the report.","vi":"Biên tập viên mất một giờ để sửa một lỗi trong báo cáo."},{"en":"Always read your work again to correct an error early.","vi":"Hãy luôn đọc lại bài để sửa một lỗi từ sớm."},{"en":"The team rushed to correct an error before the deadline.","vi":"Nhóm đã vội vã sửa một lỗi trước hạn chót."}]','[]',NULL,'/kəˈrekt ən ˈerər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3684,'colloc-3-01',94,'counter argument','lập luận phản bác','adj + n','[{"en":"A strong essay should address the main counter argument honestly.","vi":"Một bài luận mạnh nên giải quyết lập luận phản bác chính một cách trung thực."},{"en":"She offered a clear counter argument during the class debate.","vi":"Cô đã đưa ra một lập luận phản bác rõ ràng trong buổi tranh luận trên lớp."},{"en":"The counter argument focuses on the cost of the new policy.","vi":"Lập luận phản bác tập trung vào chi phí của chính sách mới."}]','[]',NULL,'/ˈkaʊntər ˈɑːrɡjumənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3685,'colloc-3-01',95,'cover a range of','bao quát một loạt','v + n','[{"en":"The textbook covers a range of topics in modern history.","vi":"Sách giáo khoa bao quát một loạt chủ đề trong lịch sử hiện đại."},{"en":"The survey covers a range of questions about daily habits.","vi":"Cuộc khảo sát bao quát một loạt câu hỏi về thói quen hằng ngày."},{"en":"Our service covers a range of needs for small businesses.","vi":"Dịch vụ của chúng tôi bao quát một loạt nhu cầu cho doanh nghiệp nhỏ."}]','[]',NULL,'/ˈkʌvər ə reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3686,'colloc-3-01',96,'cover a topic','đề cập một chủ đề','v + n','[{"en":"Each lecture will cover a topic in greater depth.","vi":"Mỗi bài giảng sẽ đề cập một chủ đề một cách sâu hơn."},{"en":"The article covers a topic that few writers have explored.","vi":"Bài báo đề cập một chủ đề mà ít cây bút đã khám phá."},{"en":"We did not have time to cover a topic on grammar.","vi":"Chúng tôi không có thời gian để đề cập một chủ đề về ngữ pháp."}]','[]',NULL,'/ˈkʌvər ə ˈtɑːpɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3687,'colloc-3-01',97,'cover an area','bao phủ một khu vực','v + n','[{"en":"The new network will cover an area of fifty square miles.","vi":"Mạng lưới mới sẽ bao phủ một khu vực rộng năm mươi dặm vuông."},{"en":"The flood covered an area larger than the whole city.","vi":"Trận lụt đã bao phủ một khu vực lớn hơn cả thành phố."},{"en":"Patrols cover an area along the entire northern border.","vi":"Các đội tuần tra bao phủ một khu vực dọc toàn bộ biên giới phía bắc."}]','[]',NULL,'/ˈkʌvər ən ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3688,'colloc-3-01',98,'create conditions','tạo điều kiện','v + n','[{"en":"Good policies create conditions that help businesses grow.","vi":"Chính sách tốt tạo điều kiện giúp doanh nghiệp phát triển."},{"en":"Teachers try to create conditions where students feel safe.","vi":"Giáo viên cố tạo điều kiện để học sinh cảm thấy an toàn."},{"en":"Heavy rain created conditions ideal for the spreading disease.","vi":"Mưa lớn đã tạo điều kiện lý tưởng cho dịch bệnh lan rộng."}]','[]',NULL,'/kriˈeɪt kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3689,'colloc-3-01',99,'create opportunities','tạo cơ hội','v + n','[{"en":"New technology can create opportunities for young entrepreneurs.","vi":"Công nghệ mới có thể tạo cơ hội cho các doanh nhân trẻ."},{"en":"The program aims to create opportunities for rural students.","vi":"Chương trình nhằm tạo cơ hội cho sinh viên vùng nông thôn."},{"en":"Travel often creates opportunities to learn new languages.","vi":"Du lịch thường tạo cơ hội để học các ngôn ngữ mới."}]','[]',NULL,'/kriˈeɪt ˌɑːpərˈtuːnətiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3690,'colloc-3-01',100,'create problems','gây ra vấn đề','v + n','[{"en":"Rushing the project may create problems we cannot fix later.","vi":"Vội vàng làm dự án có thể gây ra vấn đề ta không sửa được về sau."},{"en":"Poor planning often creates problems for the whole team.","vi":"Lập kế hoạch kém thường gây ra vấn đề cho cả nhóm."},{"en":"Too much traffic creates problems for people living downtown.","vi":"Quá nhiều xe cộ gây ra vấn đề cho người sống ở trung tâm."}]','[]',NULL,'/kriˈeɪt ˈprɑːbləmz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3691,'colloc-3-01',101,'create an environment','tạo ra một môi trường','v + n','[{"en":"Good leaders create an environment where everyone can contribute.","vi":"Người lãnh đạo giỏi tạo ra một môi trường để mọi người đều đóng góp được."},{"en":"The school tries to create an environment of mutual respect.","vi":"Trường học cố tạo ra một môi trường tôn trọng lẫn nhau."},{"en":"Soft lighting helps create an environment that feels calm.","vi":"Ánh sáng dịu giúp tạo ra một môi trường mang lại cảm giác yên bình."}]','[]',NULL,'/kriˈeɪt ən ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3692,'colloc-3-01',102,'create an impression','tạo ấn tượng','v + n','[{"en":"A neat resume helps create an impression of professionalism.","vi":"Một bản lý lịch gọn gàng giúp tạo ấn tượng về sự chuyên nghiệp."},{"en":"The opening scene creates an impression of quiet tension.","vi":"Cảnh mở đầu tạo ấn tượng về sự căng thẳng lặng lẽ."},{"en":"Try to create an impression of confidence during the interview.","vi":"Hãy cố tạo ấn tượng về sự tự tin trong buổi phỏng vấn."}]','[]',NULL,'/kriˈeɪt ən ɪmˈpreʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3693,'colloc-3-01',103,'create an opportunity','tạo ra một cơ hội','v + n','[{"en":"The merger could create an opportunity to enter new markets.","vi":"Việc sáp nhập có thể tạo ra một cơ hội để thâm nhập thị trường mới."},{"en":"Volunteering created an opportunity for her to meet experts.","vi":"Làm tình nguyện đã tạo ra một cơ hội để cô gặp gỡ các chuyên gia."},{"en":"A short delay created an opportunity to review the plan.","vi":"Một chút chậm trễ đã tạo ra một cơ hội để xem lại kế hoạch."}]','[]',NULL,'/kriˈeɪt ən ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3694,'colloc-3-01',104,'creative process','quá trình sáng tạo','adj + n','[{"en":"Writing a novel is a long and demanding creative process.","vi":"Viết một cuốn tiểu thuyết là một quá trình sáng tạo dài và đòi hỏi nhiều."},{"en":"The artist described her creative process in great detail.","vi":"Người nghệ sĩ đã mô tả quá trình sáng tạo của mình rất chi tiết."},{"en":"Mistakes are a natural part of any creative process.","vi":"Sai lầm là một phần tự nhiên của bất kỳ quá trình sáng tạo nào."}]','[]',NULL,'/kriˈeɪtɪv ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3695,'colloc-3-01',105,'creative thinking','tư duy sáng tạo','adj + n','[{"en":"The workshop encourages creative thinking through group activities.","vi":"Buổi hội thảo khuyến khích tư duy sáng tạo qua các hoạt động nhóm."},{"en":"Creative thinking helps students solve problems in new ways.","vi":"Tư duy sáng tạo giúp học sinh giải quyết vấn đề theo cách mới."},{"en":"Employers increasingly value creative thinking over rote memory.","vi":"Nhà tuyển dụng ngày càng coi trọng tư duy sáng tạo hơn học thuộc lòng."}]','[]',NULL,'/kriˈeɪtɪv ˈθɪŋkɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3696,'colloc-3-01',106,'creative work','tác phẩm sáng tạo','adj + n','[{"en":"The exhibition displays creative work by local young artists.","vi":"Triển lãm trưng bày tác phẩm sáng tạo của các nghệ sĩ trẻ địa phương."},{"en":"Copyright law protects creative work from being copied freely.","vi":"Luật bản quyền bảo vệ tác phẩm sáng tạo khỏi bị sao chép tùy ý."},{"en":"She devotes her evenings to creative work after office hours.","vi":"Cô dành các buổi tối cho công việc sáng tạo sau giờ làm việc."}]','[]',NULL,'/kriˈeɪtɪv wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3697,'colloc-3-01',107,'criminal offence','hành vi phạm tội','adj + n','[{"en":"Driving without a license is a serious criminal offence.","vi":"Lái xe không có bằng là một hành vi phạm tội nghiêm trọng."},{"en":"The new law makes online fraud a criminal offence.","vi":"Luật mới biến gian lận trực tuyến thành một hành vi phạm tội."},{"en":"He was charged with a criminal offence last month.","vi":"Anh ta bị buộc tội với một hành vi phạm tội vào tháng trước."}]','[]',NULL,'/ˈkrɪmɪnəl əˈfens/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3698,'colloc-3-01',108,'critical analysis','phân tích phản biện','adj + n','[{"en":"The essay offers a critical analysis of the author''s main claims.","vi":"Bài luận đưa ra một phân tích phản biện về các luận điểm chính của tác giả."},{"en":"Students must provide critical analysis, not just a summary.","vi":"Sinh viên phải đưa ra phân tích phản biện, chứ không chỉ tóm tắt."},{"en":"Her critical analysis revealed serious flaws in the study.","vi":"Phân tích phản biện của cô đã làm lộ những lỗ hổng nghiêm trọng trong nghiên cứu."}]','[]',NULL,'/ˈkrɪtɪkəl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3699,'colloc-3-01',109,'critical approach','cách tiếp cận phản biện','adj + n','[{"en":"The course teaches a critical approach to reading the news.","vi":"Khóa học dạy một cách tiếp cận phản biện khi đọc tin tức."},{"en":"A critical approach asks who benefits from each decision.","vi":"Cách tiếp cận phản biện đặt câu hỏi ai được lợi từ mỗi quyết định."},{"en":"She brought a critical approach to every source she used.","vi":"Cô áp dụng cách tiếp cận phản biện với mọi nguồn cô dùng."}]','[]',NULL,'/ˈkrɪtɪkəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3700,'colloc-3-01',110,'critical attention','sự chú ý phê bình','adj + n','[{"en":"The novel received critical attention soon after its release.","vi":"Cuốn tiểu thuyết nhận được sự chú ý phê bình ngay sau khi ra mắt."},{"en":"Her early films drew little critical attention at the time.","vi":"Những bộ phim đầu của bà ít được giới phê bình chú ý vào lúc đó."},{"en":"This topic deserves more critical attention from scholars.","vi":"Chủ đề này xứng đáng được giới học giả chú ý phê bình nhiều hơn."}]','[]',NULL,'/ˈkrɪtɪkəl əˈtenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3701,'colloc-3-01',111,'critical essay','bài luận phản biện','adj + n','[{"en":"Students wrote a critical essay on the poem''s central theme.","vi":"Sinh viên viết một bài luận phản biện về chủ đề trung tâm của bài thơ."},{"en":"A good critical essay supports every claim with clear evidence.","vi":"Một bài luận phản biện tốt hỗ trợ mọi luận điểm bằng bằng chứng rõ ràng."},{"en":"The professor praised her critical essay for its balanced argument.","vi":"Giáo sư khen bài luận phản biện của cô vì lập luận cân bằng."}]','[]',NULL,'/ˈkrɪtɪkəl ˈeseɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3702,'colloc-3-01',112,'critical evaluation','đánh giá phản biện','adj + n','[{"en":"The report includes a critical evaluation of the proposed plan.","vi":"Báo cáo bao gồm một đánh giá phản biện về kế hoạch được đề xuất."},{"en":"Critical evaluation of sources is a key research skill.","vi":"Đánh giá phản biện các nguồn là một kỹ năng nghiên cứu quan trọng."},{"en":"Her critical evaluation showed where the method could improve.","vi":"Đánh giá phản biện của cô chỉ ra nơi phương pháp có thể cải thiện."}]','[]',NULL,'/ˈkrɪtɪkəl ɪˌvæljuˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3703,'colloc-3-01',113,'critical examination','sự xem xét phản biện','adj + n','[{"en":"The book offers a critical examination of modern economic theory.","vi":"Cuốn sách đưa ra sự xem xét phản biện về lý thuyết kinh tế hiện đại."},{"en":"A critical examination of the data raised several new questions.","vi":"Sự xem xét phản biện đối với dữ liệu đã đặt ra nhiều câu hỏi mới."},{"en":"The chapter calls for a critical examination of old assumptions.","vi":"Chương này kêu gọi sự xem xét phản biện đối với các giả định cũ."}]','[]',NULL,'/ˈkrɪtɪkəl ɪɡˌzæmɪˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3704,'colloc-3-01',114,'critical factor','yếu tố then chốt','adj + n','[{"en":"Timing was a critical factor in the company''s early success.","vi":"Thời điểm là một yếu tố then chốt trong thành công sớm của công ty."},{"en":"Cost is often the critical factor when choosing a supplier.","vi":"Chi phí thường là yếu tố then chốt khi chọn nhà cung cấp."},{"en":"Motivation is a critical factor in long-term language learning.","vi":"Động lực là một yếu tố then chốt trong việc học ngôn ngữ lâu dài."}]','[]',NULL,'/ˈkrɪtɪkəl ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3705,'colloc-3-01',115,'critical importance','tầm quan trọng then chốt','adj + n','[{"en":"The study highlights the critical importance of early intervention.","vi":"Nghiên cứu nhấn mạnh tầm quan trọng then chốt của can thiệp sớm."},{"en":"Clean water is of critical importance to public health.","vi":"Nước sạch có tầm quan trọng then chốt đối với sức khỏe cộng đồng."},{"en":"Teachers stress the critical importance of regular practice.","vi":"Giáo viên nhấn mạnh tầm quan trọng then chốt của việc luyện tập đều đặn."}]','[]',NULL,'/ˈkrɪtɪkəl ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3706,'colloc-3-01',116,'critical inquiry','sự tìm hiểu phản biện','adj + n','[{"en":"The seminar encourages critical inquiry into historical sources.","vi":"Buổi hội thảo khuyến khích sự tìm hiểu phản biện về các nguồn lịch sử."},{"en":"Critical inquiry helps students question accepted assumptions.","vi":"Sự tìm hiểu phản biện giúp sinh viên chất vấn những giả định đã được chấp nhận."},{"en":"Her essay demonstrates careful critical inquiry and clear reasoning.","vi":"Bài luận của cô thể hiện sự tìm hiểu phản biện cẩn thận và lập luận rõ ràng."}]','[]',NULL,'/ˈkrɪtɪkəl ɪnˈkwaɪri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3707,'colloc-3-01',117,'critical introduction','phần dẫn nhập phân tích','adj + n','[{"en":"The book opens with a critical introduction to the topic.","vi":"Cuốn sách mở đầu bằng phần dẫn nhập phân tích về chủ đề."},{"en":"She wrote a critical introduction explaining the author''s main ideas.","vi":"Cô viết một phần dẫn nhập phân tích giải thích các ý chính của tác giả."},{"en":"A good critical introduction sets the context for later chapters.","vi":"Một phần dẫn nhập phân tích tốt định khung bối cảnh cho các chương sau."}]','[]',NULL,'/ˈkrɪtɪkəl ˌɪntrəˈdʌkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3708,'colloc-3-01',118,'critical issue','vấn đề trọng yếu','adj + n','[{"en":"Climate change remains a critical issue for future generations.","vi":"Biến đổi khí hậu vẫn là một vấn đề trọng yếu cho các thế hệ tương lai."},{"en":"The committee discussed several critical issues facing the school.","vi":"Ủy ban đã thảo luận nhiều vấn đề trọng yếu mà trường đang đối mặt."},{"en":"Data privacy has become a critical issue in modern society.","vi":"Quyền riêng tư dữ liệu đã trở thành một vấn đề trọng yếu trong xã hội hiện đại."}]','[]',NULL,'/ˈkrɪtɪkəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3709,'colloc-3-01',119,'critical perspective','góc nhìn phản biện','adj + n','[{"en":"The author adopts a critical perspective on modern technology.","vi":"Tác giả áp dụng một góc nhìn phản biện về công nghệ hiện đại."},{"en":"Reading widely gives students a richer critical perspective.","vi":"Đọc rộng mang lại cho sinh viên một góc nhìn phản biện phong phú hơn."},{"en":"A critical perspective helps us evaluate competing arguments.","vi":"Một góc nhìn phản biện giúp ta đánh giá các lập luận đối lập."}]','[]',NULL,'/ˈkrɪtɪkəl pərˈspektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3710,'colloc-3-01',120,'critical point','điểm mấu chốt','adj + n','[{"en":"The negotiations reached a critical point late at night.","vi":"Các cuộc đàm phán đã đến điểm mấu chốt vào đêm khuya."},{"en":"She made a critical point about the study''s limitations.","vi":"Cô đã nêu một điểm mấu chốt về những hạn chế của nghiên cứu."},{"en":"At this critical point, every decision carries serious consequences.","vi":"Tại điểm mấu chốt này, mọi quyết định đều mang hậu quả nghiêm trọng."}]','[]',NULL,'/ˈkrɪtɪkəl pɔɪnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3711,'colloc-3-01',121,'critical reflection','sự suy ngẫm phản biện','adj + n','[{"en":"The course requires critical reflection on your own learning.","vi":"Khóa học yêu cầu sự suy ngẫm phản biện về việc học của chính bạn."},{"en":"Critical reflection allows teachers to improve their practice.","vi":"Sự suy ngẫm phản biện cho phép giáo viên cải thiện phương pháp của mình."},{"en":"He kept a journal for daily critical reflection on events.","vi":"Anh giữ một cuốn nhật ký để suy ngẫm phản biện hằng ngày về các sự kiện."}]','[]',NULL,'/ˈkrɪtɪkəl rɪˈflekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3712,'colloc-3-01',122,'critical review','bài đánh giá phản biện','adj + n','[{"en":"She published a critical review of the new theory.","vi":"Cô đã công bố một bài đánh giá phản biện về lý thuyết mới."},{"en":"The assignment asks for a critical review of two articles.","vi":"Bài tập yêu cầu một bài đánh giá phản biện về hai bài báo."},{"en":"A critical review weighs both the strengths and weaknesses.","vi":"Một bài đánh giá phản biện cân nhắc cả điểm mạnh lẫn điểm yếu."}]','[]',NULL,'/ˈkrɪtɪkəl rɪˈvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3713,'colloc-3-01',123,'critical role','vai trò then chốt','adj + n','[{"en":"Sleep plays a critical role in memory consolidation.","vi":"Giấc ngủ đóng vai trò then chốt trong việc củng cố trí nhớ."},{"en":"Teachers play a critical role in shaping young minds.","vi":"Giáo viên đóng vai trò then chốt trong việc định hình tâm trí trẻ."},{"en":"Technology now plays a critical role in modern education.","vi":"Công nghệ giờ đây đóng vai trò then chốt trong giáo dục hiện đại."}]','[]',NULL,'/ˈkrɪtɪkəl roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3714,'colloc-3-01',124,'critical scrutiny','sự xem xét kỹ lưỡng','adj + n','[{"en":"The proposal came under critical scrutiny from the board.","vi":"Đề xuất chịu sự xem xét kỹ lưỡng từ hội đồng."},{"en":"His claims did not survive close critical scrutiny.","vi":"Các tuyên bố của anh không trụ vững trước sự xem xét kỹ lưỡng."},{"en":"Every source deserves critical scrutiny before being cited.","vi":"Mọi nguồn đều đáng được xem xét kỹ lưỡng trước khi trích dẫn."}]','[]',NULL,'/ˈkrɪtɪkəl ˈskruːtəni/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3715,'colloc-3-01',125,'critical theory','lý thuyết phản biện','adj + n','[{"en":"The lecture introduced students to critical theory and its origins.","vi":"Bài giảng giới thiệu cho sinh viên về lý thuyết phản biện và nguồn gốc của nó."},{"en":"Critical theory examines power relations within society.","vi":"Lý thuyết phản biện xem xét các quan hệ quyền lực trong xã hội."},{"en":"She applied critical theory to analyze the famous novel.","vi":"Cô áp dụng lý thuyết phản biện để phân tích cuốn tiểu thuyết nổi tiếng."}]','[]',NULL,'/ˈkrɪtɪkəl ˈθɪri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3716,'colloc-3-01',126,'critical thinking','tư duy phản biện','adj + n','[{"en":"The program aims to develop students'' critical thinking skills.","vi":"Chương trình nhằm phát triển kỹ năng tư duy phản biện của sinh viên."},{"en":"Critical thinking helps you spot weak arguments quickly.","vi":"Tư duy phản biện giúp bạn nhận ra các lập luận yếu một cách nhanh chóng."},{"en":"Employers value critical thinking as much as technical knowledge.","vi":"Nhà tuyển dụng coi trọng tư duy phản biện ngang với kiến thức chuyên môn."}]','[]',NULL,'/ˈkrɪtɪkəl ˈθɪŋkɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3717,'colloc-3-01',127,'critical writing','lối viết phân tích','adj + n','[{"en":"Academic essays require critical writing rather than mere description.","vi":"Bài luận học thuật đòi hỏi lối viết phân tích chứ không chỉ mô tả."},{"en":"The workshop teaches the basics of critical writing.","vi":"Buổi hội thảo dạy những điều cơ bản của lối viết phân tích."},{"en":"Good critical writing supports each claim with clear evidence.","vi":"Lối viết phân tích tốt chứng minh mỗi luận điểm bằng bằng chứng rõ ràng."}]','[]',NULL,'/ˈkrɪtɪkəl ˈraɪtɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3718,'colloc-3-01',128,'critically evaluate','đánh giá một cách phản biện','adv + v','[{"en":"Students must critically evaluate the evidence before drawing conclusions.","vi":"Sinh viên phải đánh giá bằng chứng một cách phản biện trước khi kết luận."},{"en":"The essay asks you to critically evaluate two opposing theories.","vi":"Bài luận yêu cầu bạn đánh giá một cách phản biện hai lý thuyết đối lập."},{"en":"Readers should critically evaluate claims found on social media.","vi":"Người đọc nên đánh giá một cách phản biện những tuyên bố trên mạng xã hội."}]','[]',NULL,'/ˈkrɪtɪkli ɪˈvæljueɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3719,'colloc-3-01',129,'crucial difference','khác biệt mấu chốt','adj + n','[{"en":"There is a crucial difference between knowing and understanding.","vi":"Có một khác biệt mấu chốt giữa biết và hiểu."},{"en":"Timing made a crucial difference to the final outcome.","vi":"Thời điểm tạo nên khác biệt mấu chốt cho kết quả cuối cùng."},{"en":"The study reveals a crucial difference between the two groups.","vi":"Nghiên cứu cho thấy một khác biệt mấu chốt giữa hai nhóm."}]','[]',NULL,'/ˈkruːʃəl ˈdɪfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3720,'colloc-3-01',130,'crucial factor','yếu tố then chốt','adj + n','[{"en":"Motivation is a crucial factor in academic success.","vi":"Động lực là yếu tố then chốt trong thành công học tập."},{"en":"Cost was the crucial factor in their final decision.","vi":"Chi phí là yếu tố then chốt trong quyết định cuối cùng của họ."},{"en":"Weather is a crucial factor affecting crop yields.","vi":"Thời tiết là yếu tố then chốt ảnh hưởng đến năng suất cây trồng."}]','[]',NULL,'/ˈkruːʃəl ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3721,'colloc-3-01',131,'crucial importance','tầm quan trọng thiết yếu','adj + n','[{"en":"Trust is of crucial importance in any working relationship.","vi":"Niềm tin có tầm quan trọng thiết yếu trong bất kỳ mối quan hệ làm việc nào."},{"en":"The report stresses the crucial importance of accurate data.","vi":"Báo cáo nhấn mạnh tầm quan trọng thiết yếu của dữ liệu chính xác."},{"en":"Early diagnosis is of crucial importance for treatment.","vi":"Chẩn đoán sớm có tầm quan trọng thiết yếu cho việc điều trị."}]','[]',NULL,'/ˈkruːʃəl ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3722,'colloc-3-01',132,'crucial part','phần thiết yếu','adj + n','[{"en":"Revision is a crucial part of preparing for exams.","vi":"Ôn tập là phần thiết yếu trong việc chuẩn bị cho kỳ thi."},{"en":"Feedback forms a crucial part of the learning process.","vi":"Phản hồi tạo nên phần thiết yếu của quá trình học tập."},{"en":"Trade has always been a crucial part of the economy.","vi":"Thương mại luôn là phần thiết yếu của nền kinh tế."}]','[]',NULL,'/ˈkruːʃəl pɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3723,'colloc-3-01',133,'crucial point','điểm thiết yếu','adj + n','[{"en":"She raised a crucial point that nobody had considered.","vi":"Cô nêu một điểm thiết yếu mà chưa ai cân nhắc."},{"en":"The lecture reached a crucial point about ethical limits.","vi":"Bài giảng đến một điểm thiết yếu về các giới hạn đạo đức."},{"en":"Understanding this crucial point clarifies the whole argument.","vi":"Hiểu điểm thiết yếu này làm sáng tỏ toàn bộ lập luận."}]','[]',NULL,'/ˈkruːʃəl pɔɪnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3724,'colloc-3-01',134,'crucial question','câu hỏi mấu chốt','adj + n','[{"en":"The crucial question is whether the method actually works.","vi":"Câu hỏi mấu chốt là liệu phương pháp có thực sự hiệu quả hay không."},{"en":"Her thesis addresses a crucial question in economics.","vi":"Luận án của cô giải quyết một câu hỏi mấu chốt trong kinh tế học."},{"en":"We still face the crucial question of how to fund it.","vi":"Chúng ta vẫn đối mặt câu hỏi mấu chốt là làm sao tài trợ cho nó."}]','[]',NULL,'/ˈkruːʃəl ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3725,'colloc-3-01',135,'crucial role','vai trò thiết yếu','adj + n','[{"en":"Parents play a crucial role in a child''s development.","vi":"Cha mẹ đóng vai trò thiết yếu trong sự phát triển của trẻ."},{"en":"Bees play a crucial role in pollinating many crops.","vi":"Ong đóng vai trò thiết yếu trong việc thụ phấn cho nhiều cây trồng."},{"en":"The internet plays a crucial role in spreading information.","vi":"Internet đóng vai trò thiết yếu trong việc lan truyền thông tin."}]','[]',NULL,'/ˈkruːʃəl roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3726,'colloc-3-01',136,'cultural activity','hoạt động văn hóa','adj + n','[{"en":"The festival offers a wide range of cultural activities.","vi":"Lễ hội mang đến nhiều hoạt động văn hóa đa dạng."},{"en":"Students join cultural activities to learn about other countries.","vi":"Sinh viên tham gia các hoạt động văn hóa để tìm hiểu về các nước khác."},{"en":"Music and dance are popular cultural activities in the region.","vi":"Âm nhạc và khiêu vũ là những hoạt động văn hóa phổ biến trong vùng."}]','[]',NULL,'/ˈkʌltʃərəl ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3727,'colloc-3-01',137,'cultural aspect','khía cạnh văn hóa','adj + n','[{"en":"The course explores the cultural aspects of language learning.","vi":"Khóa học khám phá các khía cạnh văn hóa của việc học ngôn ngữ."},{"en":"Travelers should respect the cultural aspects of each country.","vi":"Du khách nên tôn trọng các khía cạnh văn hóa của mỗi quốc gia."},{"en":"Her research focuses on the cultural aspects of food.","vi":"Nghiên cứu của cô tập trung vào các khía cạnh văn hóa của ẩm thực."}]','[]',NULL,'/ˈkʌltʃərəl ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3728,'colloc-3-01',138,'cultural attitudes','thái độ văn hóa','adj + n','[{"en":"Cultural attitudes toward work vary greatly between nations.","vi":"Thái độ văn hóa đối với công việc khác nhau rất nhiều giữa các quốc gia."},{"en":"The survey examined cultural attitudes about marriage and family.","vi":"Cuộc khảo sát xem xét thái độ văn hóa về hôn nhân và gia đình."},{"en":"Changing cultural attitudes have shaped modern parenting.","vi":"Thái độ văn hóa thay đổi đã định hình cách nuôi dạy con hiện đại."}]','[]',NULL,'/ˈkʌltʃərəl ˈætɪtuːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3729,'colloc-3-01',139,'cultural background','nền tảng văn hóa','adj + n','[{"en":"Students come from a variety of cultural backgrounds.","vi":"Sinh viên đến từ nhiều nền tảng văn hóa khác nhau."},{"en":"Her cultural background shaped how she viewed the issue.","vi":"Nền tảng văn hóa của cô định hình cách cô nhìn nhận vấn đề."},{"en":"Teachers should respect each student''s cultural background.","vi":"Giáo viên nên tôn trọng nền tảng văn hóa của mỗi học sinh."}]','[]',NULL,'/ˈkʌltʃərəl ˈbækɡraʊnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3730,'colloc-3-01',140,'cultural boundary','ranh giới văn hóa','adj + n','[{"en":"Music often crosses cultural boundaries with surprising ease.","vi":"Âm nhạc thường vượt qua ranh giới văn hóa một cách dễ dàng đáng ngạc nhiên."},{"en":"Globalization has blurred many traditional cultural boundaries.","vi":"Toàn cầu hóa đã làm mờ nhiều ranh giới văn hóa truyền thống."},{"en":"The project aims to break down cultural boundaries between groups.","vi":"Dự án nhằm phá vỡ các ranh giới văn hóa giữa các nhóm."}]','[]',NULL,'/ˈkʌltʃərəl ˈbaʊndəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3731,'colloc-3-01',141,'cultural change','sự thay đổi văn hóa','adj + n','[{"en":"Technology has driven rapid cultural change in recent decades.","vi":"Công nghệ đã thúc đẩy sự thay đổi văn hóa nhanh chóng trong các thập kỷ gần đây."},{"en":"Cultural change often happens slowly across generations.","vi":"Sự thay đổi văn hóa thường diễn ra chậm qua nhiều thế hệ."},{"en":"Immigration can be a powerful source of cultural change.","vi":"Di cư có thể là nguồn mạnh mẽ của sự thay đổi văn hóa."}]','[]',NULL,'/ˈkʌltʃərəl tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3732,'colloc-3-01',142,'cultural context','bối cảnh văn hóa','adj + n','[{"en":"Words can mean different things in another cultural context.","vi":"Từ ngữ có thể mang nghĩa khác trong một bối cảnh văn hóa khác."},{"en":"Understanding the cultural context helps interpret the poem.","vi":"Hiểu bối cảnh văn hóa giúp diễn giải bài thơ."},{"en":"Every artwork should be studied within its cultural context.","vi":"Mọi tác phẩm nghệ thuật nên được nghiên cứu trong bối cảnh văn hóa của nó."}]','[]',NULL,'/ˈkʌltʃərəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3733,'colloc-3-01',143,'cultural differences','những khác biệt văn hóa','adj + n','[{"en":"Cultural differences can cause misunderstandings in the workplace.","vi":"Những khác biệt văn hóa có thể gây hiểu lầm tại nơi làm việc."},{"en":"Travel teaches us to appreciate cultural differences.","vi":"Du lịch dạy chúng ta trân trọng những khác biệt văn hóa."},{"en":"The training program addresses cultural differences among staff.","vi":"Chương trình đào tạo giải quyết những khác biệt văn hóa giữa nhân viên."}]','[]',NULL,'/ˈkʌltʃərəl ˈdɪfərənsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3734,'colloc-3-01',144,'cultural dimension','chiều kích văn hóa','adj + n','[{"en":"The author ignores the cultural dimension of the conflict.","vi":"Tác giả bỏ qua chiều kích văn hóa của cuộc xung đột."},{"en":"Marketing must consider the cultural dimension of each market.","vi":"Tiếp thị phải xét đến chiều kích văn hóa của mỗi thị trường."},{"en":"Her study adds a cultural dimension to economic analysis.","vi":"Nghiên cứu của cô bổ sung chiều kích văn hóa vào phân tích kinh tế."}]','[]',NULL,'/ˈkʌltʃərəl daɪˈmenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3735,'colloc-3-01',145,'cultural diversity','sự đa dạng văn hóa','adj + n','[{"en":"The city is celebrated for its rich cultural diversity.","vi":"Thành phố được ca ngợi vì sự đa dạng văn hóa phong phú của nó."},{"en":"Schools benefit greatly from cultural diversity in the classroom.","vi":"Trường học hưởng lợi rất nhiều từ sự đa dạng văn hóa trong lớp."},{"en":"Cultural diversity encourages creativity and new ideas.","vi":"Sự đa dạng văn hóa khuyến khích sự sáng tạo và những ý tưởng mới."}]','[]',NULL,'/ˈkʌltʃərəl daɪˈvɜːrsəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3736,'colloc-3-01',146,'cultural factors','các yếu tố văn hóa','adj + n','[{"en":"Cultural factors strongly influence consumer behavior.","vi":"Các yếu tố văn hóa ảnh hưởng mạnh đến hành vi người tiêu dùng."},{"en":"The study controlled for cultural factors affecting health.","vi":"Nghiên cứu đã kiểm soát các yếu tố văn hóa ảnh hưởng đến sức khỏe."},{"en":"Cultural factors help explain differences in eating habits.","vi":"Các yếu tố văn hóa giúp giải thích khác biệt trong thói quen ăn uống."}]','[]',NULL,'/ˈkʌltʃərəl ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3737,'colloc-3-01',147,'cultural heritage','di sản văn hóa','adj + n','[{"en":"The temple is part of the nation''s cultural heritage.","vi":"Ngôi đền là một phần của di sản văn hóa quốc gia."},{"en":"Museums work hard to preserve our cultural heritage.","vi":"Các bảo tàng nỗ lực để bảo tồn di sản văn hóa của chúng ta."},{"en":"Local festivals keep cultural heritage alive for younger people.","vi":"Các lễ hội địa phương giữ cho di sản văn hóa sống động với người trẻ."}]','[]',NULL,'/ˈkʌltʃərəl ˈherɪtɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3738,'colloc-3-01',148,'cultural history','lịch sử văn hóa','adj + n','[{"en":"The lecture traced the cultural history of the region.","vi":"Bài giảng lần theo lịch sử văn hóa của vùng này."},{"en":"Her book explores the cultural history of coffee.","vi":"Cuốn sách của cô khám phá lịch sử văn hóa của cà phê."},{"en":"Understanding cultural history enriches our view of art.","vi":"Hiểu lịch sử văn hóa làm phong phú cách ta nhìn nghệ thuật."}]','[]',NULL,'/ˈkʌltʃərəl ˈhɪstəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3739,'colloc-3-01',149,'cultural identity','bản sắc văn hóa','adj + n','[{"en":"Language is closely tied to a person''s cultural identity.","vi":"Ngôn ngữ gắn chặt với bản sắc văn hóa của một người."},{"en":"Young immigrants often struggle to maintain their cultural identity.","vi":"Người nhập cư trẻ thường vật lộn để giữ gìn bản sắc văn hóa của mình."},{"en":"Traditional clothing expresses a strong cultural identity.","vi":"Trang phục truyền thống thể hiện một bản sắc văn hóa mạnh mẽ."}]','[]',NULL,'/ˈkʌltʃərəl aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3740,'colloc-3-01',150,'cultural influence','ảnh hưởng văn hóa','adj + n','[{"en":"Foreign films have a strong cultural influence on teenagers.","vi":"Phim nước ngoài có ảnh hưởng văn hóa mạnh đến thanh thiếu niên."},{"en":"The region shows clear cultural influence from its neighbors.","vi":"Vùng này cho thấy ảnh hưởng văn hóa rõ rệt từ các nước láng giềng."},{"en":"Cuisine often reflects the cultural influence of past traders.","vi":"Ẩm thực thường phản ánh ảnh hưởng văn hóa của các thương nhân xưa."}]','[]',NULL,'/ˈkʌltʃərəl ˈɪnfluəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3741,'colloc-4-01',1,'cultural institution','thiết chế văn hóa','adj + n','[{"en":"Libraries are important cultural institutions in every community.","vi":"Thư viện là những thiết chế văn hóa quan trọng trong mọi cộng đồng."},{"en":"The government funds several major cultural institutions.","vi":"Chính phủ tài trợ cho một số thiết chế văn hóa lớn."},{"en":"Museums serve as cultural institutions that educate the public.","vi":"Bảo tàng đóng vai trò thiết chế văn hóa giáo dục công chúng."}]','[]',NULL,'/ˈkʌltʃərəl ˌɪnstɪˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3742,'colloc-4-01',2,'cultural issue','vấn đề văn hóa','adj + n','[{"en":"The film raises important cultural issues about identity.","vi":"Bộ phim nêu lên những vấn đề văn hóa quan trọng về bản sắc."},{"en":"Managers must handle cultural issues in international teams.","vi":"Nhà quản lý phải xử lý các vấn đề văn hóa trong đội ngũ quốc tế."},{"en":"Language barriers are a common cultural issue for newcomers.","vi":"Rào cản ngôn ngữ là một vấn đề văn hóa phổ biến với người mới đến."}]','[]',NULL,'/ˈkʌltʃərəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3743,'colloc-4-01',3,'cultural life','đời sống văn hóa','adj + n','[{"en":"The city has a rich and vibrant cultural life.","vi":"Thành phố có một đời sống văn hóa phong phú và sôi động."},{"en":"Theaters and galleries enrich the cultural life of the town.","vi":"Nhà hát và phòng tranh làm phong phú đời sống văn hóa của thị trấn."},{"en":"Students contribute to campus cultural life through clubs.","vi":"Sinh viên đóng góp vào đời sống văn hóa của trường qua các câu lạc bộ."}]','[]',NULL,'/ˈkʌltʃərəl laɪf/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3744,'colloc-4-01',4,'cultural norm','chuẩn mực văn hóa','adj + n','[{"en":"Cultural norms determine how people greet one another.","vi":"Chuẩn mực văn hóa quyết định cách người ta chào hỏi nhau."},{"en":"Visitors should learn the local cultural norms before arriving.","vi":"Khách nên tìm hiểu chuẩn mực văn hóa địa phương trước khi đến."},{"en":"Breaking a cultural norm can cause unintended offense.","vi":"Vi phạm một chuẩn mực văn hóa có thể gây xúc phạm ngoài ý muốn."}]','[]',NULL,'/ˈkʌltʃərəl nɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3745,'colloc-4-01',5,'cultural perspective','góc nhìn văn hóa','adj + n','[{"en":"From a cultural perspective, the gift carries deep meaning.","vi":"Từ góc nhìn văn hóa, món quà mang ý nghĩa sâu sắc."},{"en":"The book offers a fresh cultural perspective on history.","vi":"Cuốn sách mang đến một góc nhìn văn hóa mới mẻ về lịch sử."},{"en":"Adopting a cultural perspective helps explain unusual customs.","vi":"Áp dụng góc nhìn văn hóa giúp giải thích các phong tục khác lạ."}]','[]',NULL,'/ˈkʌltʃərəl pərˈspektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3746,'colloc-4-01',6,'cultural phenomenon','hiện tượng văn hóa','adj + n','[{"en":"The song became a global cultural phenomenon overnight.","vi":"Bài hát trở thành một hiện tượng văn hóa toàn cầu chỉ sau một đêm."},{"en":"Social media is a cultural phenomenon worth studying closely.","vi":"Mạng xã hội là một hiện tượng văn hóa đáng nghiên cứu kỹ."},{"en":"Researchers analyzed the cultural phenomenon of viral videos.","vi":"Các nhà nghiên cứu phân tích hiện tượng văn hóa của video lan truyền."}]','[]',NULL,'/ˈkʌltʃərəl fəˈnɑːmənɑːn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3747,'colloc-4-01',7,'cultural practice','tập quán văn hóa','adj + n','[{"en":"Sharing meals is a common cultural practice in the village.","vi":"Cùng nhau dùng bữa là một tập quán văn hóa phổ biến ở làng."},{"en":"Some cultural practices are passed down for many centuries.","vi":"Một số tập quán văn hóa được truyền lại qua nhiều thế kỷ."},{"en":"The documentary records the cultural practices of the tribe.","vi":"Phim tài liệu ghi lại các tập quán văn hóa của bộ tộc."}]','[]',NULL,'/ˈkʌltʃərəl ˈpræktɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3748,'colloc-4-01',8,'cultural significance','ý nghĩa văn hóa','adj + n','[{"en":"The festival has great cultural significance for the community.","vi":"Lễ hội có ý nghĩa văn hóa lớn đối với cộng đồng."},{"en":"Scholars debate the cultural significance of the ancient site.","vi":"Các học giả tranh luận về ý nghĩa văn hóa của di chỉ cổ."},{"en":"The painting holds cultural significance beyond its beauty.","vi":"Bức tranh mang ý nghĩa văn hóa vượt xa vẻ đẹp của nó."}]','[]',NULL,'/ˈkʌltʃərəl sɪɡˈnɪfɪkəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3749,'colloc-4-01',9,'cultural theory','lý thuyết văn hóa','adj + n','[{"en":"The module introduces key ideas in cultural theory.","vi":"Học phần giới thiệu những ý tưởng chính trong lý thuyết văn hóa."},{"en":"Cultural theory examines how meaning is produced in society.","vi":"Lý thuyết văn hóa xem xét cách ý nghĩa được tạo ra trong xã hội."},{"en":"She drew on cultural theory to interpret the advertisement.","vi":"Cô vận dụng lý thuyết văn hóa để diễn giải mẩu quảng cáo."}]','[]',NULL,'/ˈkʌltʃərəl ˈθɪri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3750,'colloc-4-01',10,'cultural tradition','truyền thống văn hóa','adj + n','[{"en":"The family keeps many old cultural traditions alive.","vi":"Gia đình giữ gìn nhiều truyền thống văn hóa cũ."},{"en":"Cultural traditions help younger generations understand their roots.","vi":"Truyền thống văn hóa giúp thế hệ trẻ hiểu về cội nguồn của mình."},{"en":"Each region celebrates its own unique cultural traditions.","vi":"Mỗi vùng tôn vinh những truyền thống văn hóa độc đáo riêng."}]','[]',NULL,'/ˈkʌltʃərəl trəˈdɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3751,'colloc-4-01',11,'cultural values','giá trị văn hóa','adj + n','[{"en":"Cultural values shape how people define success.","vi":"Giá trị văn hóa định hình cách con người định nghĩa thành công."},{"en":"The school teaches respect for different cultural values.","vi":"Nhà trường dạy tôn trọng các giá trị văn hóa khác nhau."},{"en":"Advertising often reflects the cultural values of its audience.","vi":"Quảng cáo thường phản ánh giá trị văn hóa của khán giả."}]','[]',NULL,'/ˈkʌltʃərəl ˈvæljuːz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3752,'colloc-4-01',12,'culturally specific','mang tính đặc thù văn hóa','adv + adj','[{"en":"Some gestures are culturally specific and easily misread.","vi":"Một số cử chỉ mang tính đặc thù văn hóa và dễ bị hiểu sai."},{"en":"Humor is often culturally specific and hard to translate.","vi":"Sự hài hước thường mang tính đặc thù văn hóa và khó dịch."},{"en":"These rituals are culturally specific to that small region.","vi":"Những nghi lễ này mang tính đặc thù văn hóa của vùng nhỏ đó."}]','[]',NULL,'/ˈkʌltʃərəli spəˈsɪfɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3753,'colloc-4-01',13,'current climate','bối cảnh hiện tại','adj + n','[{"en":"In the current climate, many companies are cutting costs.","vi":"Trong bối cảnh hiện tại, nhiều công ty đang cắt giảm chi phí."},{"en":"The current economic climate makes investment risky.","vi":"Bối cảnh kinh tế hiện tại khiến việc đầu tư rủi ro."},{"en":"Researchers worry about the current political climate.","vi":"Các nhà nghiên cứu lo ngại về bối cảnh chính trị hiện tại."}]','[]',NULL,'/ˈkɜːrənt ˈklaɪmət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3754,'colloc-4-01',14,'current issue','vấn đề thời sự','adj + n','[{"en":"The seminar focuses on current issues in public health.","vi":"Buổi hội thảo tập trung vào các vấn đề thời sự trong y tế công cộng."},{"en":"Newspapers help students stay aware of current issues.","vi":"Báo chí giúp sinh viên nắm bắt các vấn đề thời sự."},{"en":"Climate change is one of the most pressing current issues.","vi":"Biến đổi khí hậu là một trong những vấn đề thời sự cấp bách nhất."}]','[]',NULL,'/ˈkɜːrənt ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3755,'colloc-4-01',15,'current policy','chính sách hiện hành','adj + n','[{"en":"The report criticizes the current policy on immigration.","vi":"Báo cáo chỉ trích chính sách hiện hành về nhập cư."},{"en":"Current policy does little to reduce traffic congestion.","vi":"Chính sách hiện hành làm rất ít để giảm ùn tắc giao thông."},{"en":"Experts recommend reviewing the current policy soon.","vi":"Các chuyên gia khuyến nghị sớm xem xét lại chính sách hiện hành."}]','[]',NULL,'/ˈkɜːrənt ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3756,'colloc-4-01',16,'current research','nghiên cứu hiện nay','adj + n','[{"en":"Current research suggests that exercise improves memory.","vi":"Nghiên cứu hiện nay cho thấy tập thể dục cải thiện trí nhớ."},{"en":"She reviewed the current research before writing her thesis.","vi":"Cô đã xem lại nghiên cứu hiện nay trước khi viết luận án."},{"en":"Current research focuses on renewable energy technologies.","vi":"Nghiên cứu hiện nay tập trung vào các công nghệ năng lượng tái tạo."}]','[]',NULL,'/ˈkɜːrənt ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3757,'colloc-4-01',17,'current status','tình trạng hiện tại','adj + n','[{"en":"The report describes the current status of the project.","vi":"Báo cáo mô tả tình trạng hiện tại của dự án."},{"en":"Please update me on the current status of the application.","vi":"Hãy cập nhật cho tôi về tình trạng hiện tại của đơn đăng ký."},{"en":"Scientists monitor the current status of endangered species.","vi":"Các nhà khoa học theo dõi tình trạng hiện tại của các loài nguy cấp."}]','[]',NULL,'/ˈkɜːrənt ˈstætəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3758,'colloc-4-01',18,'current technology','công nghệ hiện tại','adj + n','[{"en":"Current technology allows doctors to diagnose diseases earlier.","vi":"Công nghệ hiện tại cho phép bác sĩ chẩn đoán bệnh sớm hơn."},{"en":"The factory relies heavily on current technology to compete.","vi":"Nhà máy phụ thuộc nhiều vào công nghệ hiện tại để cạnh tranh."},{"en":"Current technology cannot yet solve this difficult problem.","vi":"Công nghệ hiện tại vẫn chưa thể giải quyết vấn đề khó này."}]','[]',NULL,'/ˈkɜːrənt tekˈnɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3759,'colloc-4-01',19,'current trend','xu hướng hiện nay','adj + n','[{"en":"The current trend is toward remote and flexible work.","vi":"Xu hướng hiện nay là làm việc từ xa và linh hoạt."},{"en":"Designers must keep up with the current trends.","vi":"Nhà thiết kế phải theo kịp các xu hướng hiện nay."},{"en":"The current trend in education favors active learning.","vi":"Xu hướng hiện nay trong giáo dục ưu tiên học tập chủ động."}]','[]',NULL,'/ˈkɜːrənt trend/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3760,'colloc-4-01',20,'currently available','hiện đang có sẵn','adv + adj','[{"en":"Several scholarships are currently available to new students.","vi":"Một số học bổng hiện đang có sẵn cho sinh viên mới."},{"en":"The treatment is not currently available in this country.","vi":"Phương pháp điều trị này hiện chưa có sẵn ở nước này."},{"en":"Only limited data is currently available on the topic.","vi":"Chỉ có lượng dữ liệu hạn chế hiện đang có sẵn về chủ đề này."}]','[]',NULL,'/ˈkɜːrəntli əˈveɪləbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3761,'colloc-4-01',21,'daily living','sinh hoạt hằng ngày','adj + n','[{"en":"The illness affects many tasks of daily living.","vi":"Căn bệnh ảnh hưởng đến nhiều việc trong sinh hoạt hằng ngày."},{"en":"Technology has changed the patterns of daily living.","vi":"Công nghệ đã thay đổi các nếp sinh hoạt hằng ngày."},{"en":"Therapists help patients regain skills for daily living.","vi":"Chuyên viên trị liệu giúp bệnh nhân lấy lại kỹ năng sinh hoạt hằng ngày."}]','[]',NULL,'/ˈdeɪli ˈlɪvɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3762,'colloc-4-01',22,'data gathering','việc thu thập dữ liệu','n + n','[{"en":"Data gathering took several months before analysis began.","vi":"Việc thu thập dữ liệu mất vài tháng trước khi bắt đầu phân tích."},{"en":"Surveys are a common method of data gathering.","vi":"Khảo sát là một phương pháp phổ biến để thu thập dữ liệu."},{"en":"Careful data gathering ensures more reliable results.","vi":"Việc thu thập dữ liệu cẩn thận đảm bảo kết quả đáng tin cậy hơn."}]','[]',NULL,'/ˈdeɪtə ˈɡæðərɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3763,'colloc-4-01',23,'data set','tập dữ liệu','n + n','[{"en":"The researchers analyzed a large data set of responses.","vi":"Các nhà nghiên cứu phân tích một tập dữ liệu lớn gồm các phản hồi."},{"en":"This data set contains information from over a thousand patients.","vi":"Tập dữ liệu này chứa thông tin từ hơn một nghìn bệnh nhân."},{"en":"Cleaning the data set removed many incomplete records.","vi":"Việc làm sạch tập dữ liệu đã loại bỏ nhiều bản ghi không đầy đủ."}]','[]',NULL,'/ˈdeɪtə set/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3764,'colloc-4-01',24,'deal with an issue','giải quyết một vấn đề','v + n','[{"en":"The committee met to deal with an issue about funding.","vi":"Ủy ban họp để giải quyết một vấn đề về tài trợ."},{"en":"Managers must learn to deal with an issue calmly.","vi":"Nhà quản lý phải học cách giải quyết một vấn đề một cách bình tĩnh."},{"en":"The essay explains how to deal with an issue systematically.","vi":"Bài luận giải thích cách giải quyết một vấn đề một cách có hệ thống."}]','[]',NULL,'/diːl wɪð ən ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3765,'colloc-4-01',25,'deem appropriate','cho là phù hợp','v + adj','[{"en":"Teachers may use whatever methods they deem appropriate.","vi":"Giáo viên có thể dùng bất kỳ phương pháp nào họ cho là phù hợp."},{"en":"The committee will take action as it deems appropriate.","vi":"Ủy ban sẽ hành động theo cách mà họ cho là phù hợp."},{"en":"You may cite any sources you deem appropriate.","vi":"Bạn có thể trích dẫn bất kỳ nguồn nào bạn cho là phù hợp."}]','[]',NULL,'/diːm əˈproʊpriət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3766,'colloc-4-01',26,'deem necessary','cho là cần thiết','v + adj','[{"en":"The doctor will order any tests she deems necessary.","vi":"Bác sĩ sẽ chỉ định bất kỳ xét nghiệm nào cô cho là cần thiết."},{"en":"Staff may take steps they deem necessary for safety.","vi":"Nhân viên có thể thực hiện các bước họ cho là cần thiết vì an toàn."},{"en":"The board approved the spending it deemed necessary.","vi":"Hội đồng đã phê duyệt khoản chi mà họ cho là cần thiết."}]','[]',NULL,'/diːm ˈnesəseri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3767,'colloc-4-01',27,'deep understanding of','sự hiểu biết sâu sắc về','adj + n','[{"en":"The course gives a deep understanding of human behavior.","vi":"Khóa học mang lại sự hiểu biết sâu sắc về hành vi con người."},{"en":"She has a deep understanding of historical events.","vi":"Cô có một sự hiểu biết sâu sắc về các sự kiện lịch sử."},{"en":"Good teaching builds a deep understanding of core concepts.","vi":"Việc dạy tốt xây dựng sự hiểu biết sâu sắc về các khái niệm cốt lõi."}]','[]',NULL,'/diːp ˌʌndərˈstændɪŋ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3768,'colloc-4-01',28,'deeper level','tầng sâu hơn','adj + n','[{"en":"The novel works on a deeper level than it first appears.","vi":"Cuốn tiểu thuyết hoạt động ở một tầng sâu hơn so với vẻ ngoài."},{"en":"We need to analyze the problem at a deeper level.","vi":"Chúng ta cần phân tích vấn đề ở một tầng sâu hơn."},{"en":"On a deeper level, the poem questions human freedom.","vi":"Ở tầng sâu hơn, bài thơ chất vấn về tự do của con người."}]','[]',NULL,'/ˈdiːpər ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3769,'colloc-4-01',29,'deeply embedded','ăn sâu, gắn chặt','adv + vpp','[{"en":"These beliefs are deeply embedded in the local culture.","vi":"Những niềm tin này ăn sâu trong văn hóa địa phương."},{"en":"Corruption was deeply embedded in the old system.","vi":"Tham nhũng đã ăn sâu trong hệ thống cũ."},{"en":"Such habits become deeply embedded over many years.","vi":"Những thói quen như vậy trở nên ăn sâu qua nhiều năm."}]','[]',NULL,'/ˈdiːpli ɪmˈbedɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3770,'colloc-4-01',30,'deeply rooted','bắt rễ sâu','adv + vpp','[{"en":"Their traditions are deeply rooted in ancient history.","vi":"Truyền thống của họ bắt rễ sâu trong lịch sử cổ xưa."},{"en":"The conflict is deeply rooted in economic inequality.","vi":"Cuộc xung đột bắt rễ sâu trong bất bình đẳng kinh tế."},{"en":"Prejudice can be deeply rooted and hard to change.","vi":"Định kiến có thể bắt rễ sâu và khó thay đổi."}]','[]',NULL,'/ˈdiːpli ˈruːtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3771,'colloc-4-01',31,'defining characteristic','đặc điểm nhận diện','adj + n','[{"en":"Curiosity is a defining characteristic of good scientists.","vi":"Tính tò mò là đặc điểm nhận diện của những nhà khoa học giỏi."},{"en":"The defining characteristic of mammals is their fur.","vi":"Đặc điểm nhận diện của động vật có vú là bộ lông của chúng."},{"en":"Flexibility became the defining characteristic of the new design.","vi":"Tính linh hoạt trở thành đặc điểm nhận diện của thiết kế mới."}]','[]',NULL,'/dɪˈfaɪnɪŋ ˌkærəktəˈrɪstɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3772,'colloc-4-01',32,'defining concept','khái niệm cốt lõi','adj + n','[{"en":"Freedom is a defining concept in modern political thought.","vi":"Tự do là một khái niệm cốt lõi trong tư tưởng chính trị hiện đại."},{"en":"The lecture explained the defining concept of the theory.","vi":"Bài giảng giải thích khái niệm cốt lõi của lý thuyết."},{"en":"Sustainability has become a defining concept in design.","vi":"Tính bền vững đã trở thành một khái niệm cốt lõi trong thiết kế."}]','[]',NULL,'/dɪˈfaɪnɪŋ ˈkɑːnsept/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3773,'colloc-4-01',33,'defining feature','đặc trưng nổi bật','adj + n','[{"en":"Strong rhythm is a defining feature of this music.","vi":"Nhịp điệu mạnh mẽ là đặc trưng nổi bật của loại nhạc này."},{"en":"The defining feature of the building is its glass roof.","vi":"Đặc trưng nổi bật của tòa nhà là mái kính của nó."},{"en":"Openness is the defining feature of their company culture.","vi":"Sự cởi mở là đặc trưng nổi bật của văn hóa công ty họ."}]','[]',NULL,'/dɪˈfaɪnɪŋ ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3774,'colloc-4-01',34,'deliberate attempt','nỗ lực có chủ đích','adj + n','[{"en":"The policy was a deliberate attempt to reduce poverty.","vi":"Chính sách này là một nỗ lực có chủ đích nhằm giảm nghèo."},{"en":"His remarks seemed a deliberate attempt to provoke debate.","vi":"Những lời của anh có vẻ là nỗ lực có chủ đích để khơi mào tranh luận."},{"en":"The redesign was a deliberate attempt to improve safety.","vi":"Việc thiết kế lại là một nỗ lực có chủ đích để cải thiện an toàn."}]','[]',NULL,'/dɪˈlɪbərət əˈtempt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3775,'colloc-4-01',35,'democratic institution','thiết chế dân chủ','adj + n','[{"en":"Free elections are a key democratic institution.","vi":"Bầu cử tự do là một thiết chế dân chủ then chốt."},{"en":"Strong democratic institutions protect citizens'' rights.","vi":"Các thiết chế dân chủ vững mạnh bảo vệ quyền của công dân."},{"en":"The reforms aimed to strengthen democratic institutions.","vi":"Các cải cách nhằm củng cố các thiết chế dân chủ."}]','[]',NULL,'/ˌdeməˈkrætɪk ˌɪnstɪˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3776,'colloc-4-01',36,'democratic process','tiến trình dân chủ','adj + n','[{"en":"Voting is a fundamental part of the democratic process.","vi":"Bỏ phiếu là một phần cơ bản của tiến trình dân chủ."},{"en":"Citizens take part in the democratic process through elections.","vi":"Công dân tham gia tiến trình dân chủ thông qua bầu cử."},{"en":"A free press supports a healthy democratic process.","vi":"Báo chí tự do hỗ trợ một tiến trình dân chủ lành mạnh."}]','[]',NULL,'/ˌdeməˈkrætɪk ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3777,'colloc-4-01',37,'democratic society','xã hội dân chủ','adj + n','[{"en":"Free speech is essential in a democratic society.","vi":"Tự do ngôn luận là điều thiết yếu trong một xã hội dân chủ."},{"en":"A democratic society depends on informed and active citizens.","vi":"Một xã hội dân chủ phụ thuộc vào công dân hiểu biết và năng động."},{"en":"Education plays a vital role in any democratic society.","vi":"Giáo dục đóng vai trò sống còn trong bất kỳ xã hội dân chủ nào."}]','[]',NULL,'/ˌdeməˈkrætɪk səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3778,'colloc-4-01',38,'democratic state','nhà nước dân chủ','adj + n','[{"en":"A democratic state guarantees basic rights to its people.","vi":"Một nhà nước dân chủ bảo đảm các quyền cơ bản cho người dân."},{"en":"The country became a democratic state after the reforms.","vi":"Đất nước trở thành một nhà nước dân chủ sau các cuộc cải cách."},{"en":"In a democratic state, leaders are chosen by the people.","vi":"Trong một nhà nước dân chủ, lãnh đạo do người dân lựa chọn."}]','[]',NULL,'/ˌdeməˈkrætɪk steɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3779,'colloc-4-01',39,'demographic change','thay đổi nhân khẩu học','adj + n','[{"en":"Demographic change is reshaping the country''s labor market.","vi":"Thay đổi nhân khẩu học đang định hình lại thị trường lao động của đất nước."},{"en":"An aging population is a major demographic change.","vi":"Dân số già hóa là một thay đổi nhân khẩu học lớn."},{"en":"Planners must prepare for rapid demographic change.","vi":"Các nhà hoạch định phải chuẩn bị cho thay đổi nhân khẩu học nhanh chóng."}]','[]',NULL,'/ˌdeməˈɡræfɪk tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3780,'colloc-4-01',40,'demographic characteristics','đặc điểm nhân khẩu học','adj + n','[{"en":"The survey recorded the demographic characteristics of each respondent.","vi":"Cuộc khảo sát ghi lại đặc điểm nhân khẩu học của từng người trả lời."},{"en":"Demographic characteristics include age, gender, and income.","vi":"Đặc điểm nhân khẩu học bao gồm tuổi, giới tính và thu nhập."},{"en":"Marketers study demographic characteristics to target customers.","vi":"Người làm tiếp thị nghiên cứu đặc điểm nhân khẩu học để nhắm khách hàng."}]','[]',NULL,'/ˌdeməˈɡræfɪk ˌkærəktəˈrɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3781,'colloc-4-01',41,'demographic factor','yếu tố nhân khẩu học','adj + n','[{"en":"Age is an important demographic factor in voting behavior.","vi":"Tuổi tác là một yếu tố nhân khẩu học quan trọng trong hành vi bỏ phiếu."},{"en":"The study controlled for several demographic factors.","vi":"Nghiên cứu đã kiểm soát một số yếu tố nhân khẩu học."},{"en":"Income is a demographic factor linked to health outcomes.","vi":"Thu nhập là một yếu tố nhân khẩu học liên quan đến kết quả sức khỏe."}]','[]',NULL,'/ˌdeməˈɡræfɪk ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3782,'colloc-4-01',42,'demonstrate competence','thể hiện năng lực','v + n','[{"en":"Candidates must demonstrate competence in basic mathematics.","vi":"Ứng viên phải thể hiện năng lực trong toán học cơ bản."},{"en":"The exam allows students to demonstrate competence in writing.","vi":"Kỳ thi cho phép sinh viên thể hiện năng lực viết."},{"en":"New nurses demonstrate competence before working alone.","vi":"Y tá mới thể hiện năng lực trước khi làm việc độc lập."}]','[]',NULL,'/ˈdemənstreɪt ˈkɑːmpətəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3783,'colloc-4-01',43,'densely populated','đông dân cư','adv + vpp','[{"en":"The city is one of the most densely populated in the world.","vi":"Thành phố này là một trong những nơi đông dân cư nhất thế giới."},{"en":"Densely populated areas often struggle with housing shortages.","vi":"Các khu vực đông dân cư thường gặp khó khăn với việc thiếu nhà ở."},{"en":"Disease spreads faster in densely populated regions.","vi":"Dịch bệnh lây lan nhanh hơn ở các vùng đông dân cư."}]','[]',NULL,'/ˈdensli ˈpɑːpjuleɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3784,'colloc-4-01',44,'deny access to','từ chối quyền tiếp cận','v + n','[{"en":"The system can deny access to unauthorized users.","vi":"Hệ thống có thể từ chối quyền tiếp cận với người dùng trái phép."},{"en":"Officials cannot deny access to public records without cause.","vi":"Quan chức không thể từ chối quyền tiếp cận hồ sơ công nếu không có lý do."},{"en":"The policy may deny access to certain restricted areas.","vi":"Chính sách có thể từ chối quyền tiếp cận vào một số khu vực hạn chế."}]','[]',NULL,'/dɪˈnaɪ ˈækses tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3785,'colloc-4-01',45,'dependent variable','biến phụ thuộc','adj + n','[{"en":"In this experiment, reaction time is the dependent variable.","vi":"Trong thí nghiệm này, thời gian phản ứng là biến phụ thuộc."},{"en":"Researchers measure the dependent variable after each trial.","vi":"Các nhà nghiên cứu đo biến phụ thuộc sau mỗi lần thử."},{"en":"The dependent variable changes as the input is adjusted.","vi":"Biến phụ thuộc thay đổi khi đầu vào được điều chỉnh."}]','[]',NULL,'/dɪˈpendənt ˈveriəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3786,'colloc-4-01',46,'describe a method','mô tả một phương pháp','v + n','[{"en":"The paper describes a method for measuring air quality.","vi":"Bài báo mô tả một phương pháp để đo chất lượng không khí."},{"en":"Please describe a method you used to collect the data.","vi":"Hãy mô tả một phương pháp bạn đã dùng để thu thập dữ liệu."},{"en":"The chapter describes a method for training new staff.","vi":"Chương này mô tả một phương pháp để đào tạo nhân viên mới."}]','[]',NULL,'/dɪˈskraɪb ə ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3787,'colloc-4-01',47,'describe a process','mô tả một quá trình','v + n','[{"en":"The diagram helps describe a process step by step.","vi":"Sơ đồ giúp mô tả một quá trình theo từng bước."},{"en":"Students learn to describe a process clearly in writing.","vi":"Sinh viên học cách mô tả một quá trình rõ ràng bằng văn bản."},{"en":"The video describes a process for recycling plastic.","vi":"Video mô tả một quá trình tái chế nhựa."}]','[]',NULL,'/dɪˈskraɪb ə ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3788,'colloc-4-01',48,'describe a procedure','mô tả một quy trình','v + n','[{"en":"The manual describes a procedure for installing the software safely.","vi":"Sách hướng dẫn mô tả quy trình cài đặt phần mềm một cách an toàn."},{"en":"She clearly describes a procedure that any nurse can follow.","vi":"Cô ấy mô tả rõ ràng một quy trình mà bất kỳ y tá nào cũng làm theo được."},{"en":"The paper describes a procedure used to collect the samples.","vi":"Bài báo mô tả quy trình được dùng để thu thập mẫu."}]','[]',NULL,'/dɪˈskraɪb ə prəˈsiːdʒər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3789,'colloc-4-01',49,'descriptive statistics','thống kê mô tả','adj + n','[{"en":"We used descriptive statistics to summarize the survey results.","vi":"Chúng tôi dùng thống kê mô tả để tóm tắt kết quả khảo sát."},{"en":"Descriptive statistics show the average score for each group.","vi":"Thống kê mô tả cho thấy điểm trung bình của từng nhóm."},{"en":"The report begins with descriptive statistics before deeper analysis.","vi":"Báo cáo bắt đầu bằng thống kê mô tả trước khi phân tích sâu hơn."}]','[]',NULL,'/dɪˈskrɪptɪv stəˈtɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3790,'colloc-4-01',50,'desired outcome','kết quả mong muốn','adj + n','[{"en":"The new policy did not produce the desired outcome.","vi":"Chính sách mới đã không tạo ra kết quả mong muốn."},{"en":"Careful planning helps you reach the desired outcome faster.","vi":"Lập kế hoạch kỹ giúp bạn đạt kết quả mong muốn nhanh hơn."},{"en":"Teachers adjust their methods to achieve the desired outcome.","vi":"Giáo viên điều chỉnh phương pháp để đạt được kết quả mong muốn."}]','[]',NULL,'/dɪˈzaɪərd ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3791,'colloc-4-01',51,'detailed analysis','phân tích chi tiết','adj + n','[{"en":"The thesis provides a detailed analysis of consumer behavior.","vi":"Luận văn đưa ra phân tích chi tiết về hành vi người tiêu dùng."},{"en":"A detailed analysis revealed several errors in the data.","vi":"Phân tích chi tiết đã phát hiện nhiều lỗi trong dữ liệu."},{"en":"Investors expect a detailed analysis before making decisions.","vi":"Nhà đầu tư cần phân tích chi tiết trước khi ra quyết định."}]','[]',NULL,'/ˈdiːteɪld əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3792,'colloc-4-01',52,'detailed examination','sự khảo sát chi tiết','adj + n','[{"en":"The book offers a detailed examination of ancient trade routes.","vi":"Cuốn sách khảo sát chi tiết các tuyến đường thương mại cổ đại."},{"en":"A detailed examination of the evidence supports her claim.","vi":"Việc khảo sát chi tiết bằng chứng ủng hộ lập luận của cô ấy."},{"en":"The doctor recommended a detailed examination of the samples.","vi":"Bác sĩ đề nghị khảo sát chi tiết các mẫu."}]','[]',NULL,'/ˈdiːteɪld ɪɡˌzæməˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3793,'colloc-4-01',53,'detailed information','thông tin chi tiết','adj + n','[{"en":"The website provides detailed information about each course.","vi":"Trang web cung cấp thông tin chi tiết về từng khóa học."},{"en":"Please send detailed information about the conference schedule.","vi":"Vui lòng gửi thông tin chi tiết về lịch hội nghị."},{"en":"Detailed information on the labels helps shoppers choose wisely.","vi":"Thông tin chi tiết trên nhãn giúp người mua chọn lựa khôn ngoan."}]','[]',NULL,'/ˈdiːteɪld ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3794,'colloc-4-01',54,'detailed study','nghiên cứu chi tiết','adj + n','[{"en":"They conducted a detailed study of local water quality.","vi":"Họ tiến hành một nghiên cứu chi tiết về chất lượng nước địa phương."},{"en":"A detailed study of the region took several years.","vi":"Một nghiên cứu chi tiết về khu vực này mất vài năm."},{"en":"The detailed study confirmed earlier findings about migration.","vi":"Nghiên cứu chi tiết đã xác nhận các phát hiện trước về di cư."}]','[]',NULL,'/ˈdiːteɪld ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3795,'colloc-4-01',55,'develop a method','phát triển một phương pháp','v + n','[{"en":"Researchers worked together to develop a method for testing.","vi":"Các nhà nghiên cứu hợp tác để phát triển một phương pháp kiểm tra."},{"en":"The team hopes to develop a method that saves time.","vi":"Nhóm hy vọng phát triển một phương pháp tiết kiệm thời gian."},{"en":"Scientists develop a method before running large experiments.","vi":"Các nhà khoa học phát triển một phương pháp trước khi làm thí nghiệm lớn."}]','[]',NULL,'/dɪˈveləp ə ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3796,'colloc-4-01',56,'develop a strategy','xây dựng một chiến lược','v + n','[{"en":"The company needs to develop a strategy for new markets.","vi":"Công ty cần xây dựng một chiến lược cho các thị trường mới."},{"en":"Students learn to develop a strategy before starting an essay.","vi":"Sinh viên học cách xây dựng một chiến lược trước khi viết tiểu luận."},{"en":"Managers develop a strategy to reduce costs each year.","vi":"Các quản lý xây dựng một chiến lược cắt giảm chi phí mỗi năm."}]','[]',NULL,'/dɪˈveləp ə ˈstrætədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3797,'colloc-4-01',57,'develop a technique','phát triển một kỹ thuật','v + n','[{"en":"The lab worked hard to develop a technique for imaging cells.","vi":"Phòng thí nghiệm nỗ lực phát triển một kỹ thuật chụp ảnh tế bào."},{"en":"Artists often develop a technique that becomes their signature.","vi":"Nghệ sĩ thường phát triển một kỹ thuật trở thành dấu ấn riêng."},{"en":"They aim to develop a technique cheaper than current ones.","vi":"Họ muốn phát triển một kỹ thuật rẻ hơn các kỹ thuật hiện có."}]','[]',NULL,'/dɪˈveləp ə tekˈniːk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3798,'colloc-4-01',58,'develop a theory','xây dựng một lý thuyết','v + n','[{"en":"Darwin spent years working to develop a theory of evolution.","vi":"Darwin mất nhiều năm để xây dựng một lý thuyết về tiến hóa."},{"en":"Economists develop a theory to explain how prices change.","vi":"Các nhà kinh tế xây dựng một lý thuyết giải thích giá cả thay đổi."},{"en":"She used the data to develop a theory about learning.","vi":"Cô ấy dùng dữ liệu để xây dựng một lý thuyết về việc học."}]','[]',NULL,'/dɪˈveləp ə ˈθiːəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3799,'colloc-4-01',59,'develop an approach','phát triển một cách tiếp cận','v + n','[{"en":"The school tried to develop an approach suited to young learners.","vi":"Trường cố gắng phát triển một cách tiếp cận phù hợp với học sinh nhỏ."},{"en":"We must develop an approach that respects local traditions.","vi":"Chúng ta phải phát triển một cách tiếp cận tôn trọng truyền thống địa phương."},{"en":"Therapists develop an approach tailored to each patient.","vi":"Nhà trị liệu phát triển một cách tiếp cận riêng cho từng bệnh nhân."}]','[]',NULL,'/dɪˈveləp ən əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3800,'colloc-4-01',60,'develop an argument','triển khai một lập luận','v + n','[{"en":"A good essay should develop an argument step by step.","vi":"Một bài luận hay nên triển khai một lập luận theo từng bước."},{"en":"She uses evidence to develop an argument for reform.","vi":"Cô ấy dùng bằng chứng để triển khai một lập luận cho cải cách."},{"en":"Lawyers develop an argument carefully before going to court.","vi":"Luật sư triển khai một lập luận cẩn thận trước khi ra tòa."}]','[]',NULL,'/dɪˈveləp ən ˈɑːrɡjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3801,'colloc-4-01',61,'developmental process','quá trình phát triển','adj + n','[{"en":"Language learning is a slow developmental process in children.","vi":"Việc học ngôn ngữ là một quá trình phát triển chậm ở trẻ em."},{"en":"The book explains each step of the developmental process.","vi":"Cuốn sách giải thích từng bước của quá trình phát triển."},{"en":"Stress can interrupt the normal developmental process of cells.","vi":"Căng thẳng có thể làm gián đoạn quá trình phát triển bình thường của tế bào."}]','[]',NULL,'/dɪˌveləpˈmentəl ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3802,'colloc-4-01',62,'developmental stage','giai đoạn phát triển','adj + n','[{"en":"Each developmental stage brings new skills for the child.","vi":"Mỗi giai đoạn phát triển mang lại những kỹ năng mới cho trẻ."},{"en":"The plant reaches a developmental stage where it flowers.","vi":"Cây đạt tới giai đoạn phát triển mà nó nở hoa."},{"en":"Teachers adapt lessons to the pupil''s developmental stage.","vi":"Giáo viên điều chỉnh bài học theo giai đoạn phát triển của học sinh."}]','[]',NULL,'/dɪˌveləpˈmentəl steɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3803,'colloc-4-01',63,'diagnostic test','bài kiểm tra chẩn đoán','adj + n','[{"en":"The doctor ordered a diagnostic test to confirm the illness.","vi":"Bác sĩ chỉ định một bài kiểm tra chẩn đoán để xác nhận bệnh."},{"en":"Students take a diagnostic test at the start of the course.","vi":"Sinh viên làm một bài kiểm tra chẩn đoán đầu khóa học."},{"en":"A simple diagnostic test can detect the problem early.","vi":"Một bài kiểm tra chẩn đoán đơn giản có thể phát hiện sớm vấn đề."}]','[]',NULL,'/ˌdaɪəɡˈnɑːstɪk test/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3804,'colloc-4-01',64,'differ considerably','khác nhau đáng kể','v + adv','[{"en":"Prices differ considerably between the two cities.","vi":"Giá cả khác nhau đáng kể giữa hai thành phố."},{"en":"Opinions on the matter differ considerably among experts.","vi":"Quan điểm về vấn đề này khác nhau đáng kể giữa các chuyên gia."},{"en":"The results differ considerably from those of earlier studies.","vi":"Kết quả khác nhau đáng kể so với các nghiên cứu trước."}]','[]',NULL,'/ˈdɪfər kənˈsɪdərəbli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3805,'colloc-4-01',65,'differ significantly','khác nhau rõ rệt','v + adv','[{"en":"The two groups differ significantly in their test scores.","vi":"Hai nhóm khác nhau rõ rệt về điểm kiểm tra."},{"en":"Climate patterns differ significantly from region to region.","vi":"Kiểu khí hậu khác nhau rõ rệt giữa các vùng."},{"en":"Male and female responses did not differ significantly.","vi":"Phản hồi của nam và nữ không khác nhau rõ rệt."}]','[]',NULL,'/ˈdɪfər sɪɡˈnɪfɪkəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3806,'colloc-4-01',66,'differ widely','khác nhau rất nhiều','v + adv','[{"en":"Customs differ widely from one country to another.","vi":"Phong tục khác nhau rất nhiều giữa các quốc gia."},{"en":"Estimates of the cost differ widely among analysts.","vi":"Các ước tính về chi phí khác nhau rất nhiều giữa các nhà phân tích."},{"en":"Teaching styles differ widely across the schools surveyed.","vi":"Phong cách giảng dạy khác nhau rất nhiều giữa các trường được khảo sát."}]','[]',NULL,'/ˈdɪfər ˈwaɪdli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3807,'colloc-4-01',67,'digital information','thông tin số','adj + n','[{"en":"Libraries now store vast amounts of digital information.","vi":"Các thư viện hiện lưu trữ lượng lớn thông tin số."},{"en":"Protecting digital information is a key concern for companies.","vi":"Bảo vệ thông tin số là mối quan tâm chính của các công ty."},{"en":"Digital information can be shared across the world instantly.","vi":"Thông tin số có thể được chia sẻ khắp thế giới ngay lập tức."}]','[]',NULL,'/ˈdɪdʒətəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3808,'colloc-4-01',68,'digital media','phương tiện truyền thông số','adj + n','[{"en":"Young people spend many hours using digital media daily.","vi":"Người trẻ dành nhiều giờ mỗi ngày để dùng truyền thông số."},{"en":"Digital media have changed how news reaches the public.","vi":"Truyền thông số đã thay đổi cách tin tức đến với công chúng."},{"en":"The course explores the impact of digital media on society.","vi":"Khóa học tìm hiểu tác động của truyền thông số lên xã hội."}]','[]',NULL,'/ˈdɪdʒətəl ˈmiːdiə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3809,'colloc-4-01',69,'digital technology','công nghệ số','adj + n','[{"en":"Digital technology has transformed the way we communicate.","vi":"Công nghệ số đã thay đổi cách chúng ta giao tiếp."},{"en":"Schools invest in digital technology to support learning.","vi":"Các trường đầu tư vào công nghệ số để hỗ trợ việc học."},{"en":"Many jobs now require basic digital technology skills.","vi":"Nhiều công việc hiện đòi hỏi kỹ năng công nghệ số cơ bản."}]','[]',NULL,'/ˈdɪdʒətəl tekˈnɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3810,'colloc-4-01',70,'direct access','quyền truy cập trực tiếp','adj + n','[{"en":"Members enjoy direct access to the research database.","vi":"Thành viên được quyền truy cập trực tiếp vào cơ sở dữ liệu nghiên cứu."},{"en":"The app gives users direct access to their account details.","vi":"Ứng dụng cho người dùng truy cập trực tiếp thông tin tài khoản."},{"en":"Patients now have direct access to their medical records.","vi":"Bệnh nhân giờ có quyền truy cập trực tiếp hồ sơ y tế của mình."}]','[]',NULL,'/dɪˈrekt ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3811,'colloc-4-01',71,'direct communication','giao tiếp trực tiếp','adj + n','[{"en":"Direct communication between teams prevents misunderstandings.","vi":"Giao tiếp trực tiếp giữa các nhóm ngăn ngừa hiểu lầm."},{"en":"The manager values direct communication with her staff.","vi":"Người quản lý coi trọng giao tiếp trực tiếp với nhân viên."},{"en":"Direct communication is often faster than long email chains.","vi":"Giao tiếp trực tiếp thường nhanh hơn những chuỗi email dài."}]','[]',NULL,'/dɪˈrekt kəˌmjuːnɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3812,'colloc-4-01',72,'direct consequences','hậu quả trực tiếp','adj + n','[{"en":"Pollution has direct consequences for public health.","vi":"Ô nhiễm có những hậu quả trực tiếp đối với sức khỏe cộng đồng."},{"en":"The policy had direct consequences for small businesses.","vi":"Chính sách đó đã gây hậu quả trực tiếp cho các doanh nghiệp nhỏ."},{"en":"Cutting funding had direct consequences for the program.","vi":"Việc cắt kinh phí gây hậu quả trực tiếp cho chương trình."}]','[]',NULL,'/dɪˈrekt ˈkɑːnsəkwensəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3813,'colloc-4-01',73,'direct contact','tiếp xúc trực tiếp','adj + n','[{"en":"The disease spreads through direct contact with the skin.","vi":"Bệnh lây lan qua tiếp xúc trực tiếp với da."},{"en":"Sales staff keep direct contact with their main clients.","vi":"Nhân viên bán hàng giữ tiếp xúc trực tiếp với khách hàng chính."},{"en":"Avoid direct contact between the chemical and your eyes.","vi":"Tránh để hóa chất tiếp xúc trực tiếp với mắt bạn."}]','[]',NULL,'/dɪˈrekt ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3814,'colloc-4-01',74,'direct evidence','bằng chứng trực tiếp','adj + n','[{"en":"There is direct evidence linking smoking to lung cancer.","vi":"Có bằng chứng trực tiếp liên hệ hút thuốc với ung thư phổi."},{"en":"The study found direct evidence of climate change effects.","vi":"Nghiên cứu tìm thấy bằng chứng trực tiếp về tác động biến đổi khí hậu."},{"en":"Without direct evidence, the theory remains unproven.","vi":"Nếu thiếu bằng chứng trực tiếp, lý thuyết vẫn chưa được chứng minh."}]','[]',NULL,'/dɪˈrekt ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3815,'colloc-4-01',75,'direct impact','tác động trực tiếp','adj + n','[{"en":"The new tax had a direct impact on household spending.","vi":"Thuế mới có tác động trực tiếp đến chi tiêu hộ gia đình."},{"en":"Sleep has a direct impact on a student''s performance.","vi":"Giấc ngủ có tác động trực tiếp đến kết quả của học sinh."},{"en":"The drought had a direct impact on local farmers.","vi":"Hạn hán có tác động trực tiếp đến nông dân địa phương."}]','[]',NULL,'/dɪˈrekt ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3816,'colloc-4-01',76,'direct involvement','sự tham gia trực tiếp','adj + n','[{"en":"The project succeeded thanks to direct involvement from staff.","vi":"Dự án thành công nhờ sự tham gia trực tiếp của nhân viên."},{"en":"Her direct involvement made the campaign far more effective.","vi":"Sự tham gia trực tiếp của cô ấy khiến chiến dịch hiệu quả hơn nhiều."},{"en":"The report questions the company''s direct involvement in the deal.","vi":"Báo cáo đặt nghi vấn về sự tham gia trực tiếp của công ty vào thương vụ."}]','[]',NULL,'/dɪˈrekt ɪnˈvɑːlvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3817,'colloc-4-01',77,'direct link','mối liên hệ trực tiếp','adj + n','[{"en":"Scientists found a direct link between diet and heart disease.","vi":"Các nhà khoa học tìm thấy mối liên hệ trực tiếp giữa ăn uống và bệnh tim."},{"en":"There is a direct link between exercise and better mood.","vi":"Có mối liên hệ trực tiếp giữa tập thể dục và tâm trạng tốt hơn."},{"en":"The data show a direct link between income and education.","vi":"Dữ liệu cho thấy mối liên hệ trực tiếp giữa thu nhập và học vấn."}]','[]',NULL,'/dɪˈrekt lɪŋk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3818,'colloc-4-01',78,'direct observation','quan sát trực tiếp','adj + n','[{"en":"The findings are based on direct observation of animal behavior.","vi":"Các phát hiện dựa trên quan sát trực tiếp hành vi động vật."},{"en":"Direct observation gives richer data than surveys alone.","vi":"Quan sát trực tiếp cho dữ liệu phong phú hơn so với chỉ khảo sát."},{"en":"Through direct observation, she recorded how children played.","vi":"Qua quan sát trực tiếp, cô ấy ghi lại cách trẻ em chơi."}]','[]',NULL,'/dɪˈrekt ˌɑːbzərˈveɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3819,'colloc-4-01',79,'direct relationship','mối quan hệ trực tiếp','adj + n','[{"en":"There is a direct relationship between price and demand.","vi":"Có mối quan hệ trực tiếp giữa giá cả và nhu cầu."},{"en":"The graph shows a direct relationship between the variables.","vi":"Biểu đồ cho thấy mối quan hệ trực tiếp giữa các biến số."},{"en":"Researchers noted a direct relationship between stress and sleep.","vi":"Các nhà nghiên cứu ghi nhận mối quan hệ trực tiếp giữa căng thẳng và giấc ngủ."}]','[]',NULL,'/dɪˈrekt rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3820,'colloc-4-01',80,'direct role','vai trò trực tiếp','adj + n','[{"en":"She played a direct role in shaping the new policy.","vi":"Cô ấy đóng vai trò trực tiếp trong việc định hình chính sách mới."},{"en":"Sunlight plays a direct role in plant growth.","vi":"Ánh nắng đóng vai trò trực tiếp trong sự phát triển của cây."},{"en":"The committee has a direct role in approving the budget.","vi":"Ủy ban có vai trò trực tiếp trong việc phê duyệt ngân sách."}]','[]',NULL,'/dɪˈrekt roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3821,'colloc-4-01',81,'directly affect','ảnh hưởng trực tiếp','adv + v','[{"en":"Interest rates directly affect the cost of borrowing money.","vi":"Lãi suất ảnh hưởng trực tiếp đến chi phí vay tiền."},{"en":"Diet and sleep directly affect how well students learn.","vi":"Ăn uống và giấc ngủ ảnh hưởng trực tiếp đến việc học của học sinh."},{"en":"Weather conditions directly affect crop yields each season.","vi":"Điều kiện thời tiết ảnh hưởng trực tiếp đến năng suất mùa màng."}]','[]',NULL,'/dɪˈrektli əˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3822,'colloc-4-01',82,'directly affected','bị ảnh hưởng trực tiếp','adv + vpp','[{"en":"Coastal towns were directly affected by the rising sea levels.","vi":"Các thị trấn ven biển bị ảnh hưởng trực tiếp bởi mực nước biển dâng."},{"en":"Workers directly affected by the closure received support.","vi":"Những công nhân bị ảnh hưởng trực tiếp bởi việc đóng cửa đã được hỗ trợ."},{"en":"Families directly affected by the flood need urgent help.","vi":"Các gia đình bị ảnh hưởng trực tiếp bởi lũ lụt cần giúp đỡ khẩn cấp."}]','[]',NULL,'/dɪˈrektli əˈfektɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3823,'colloc-4-01',83,'directly connected to','kết nối trực tiếp với','adv + vpp','[{"en":"The printer is directly connected to the main computer.","vi":"Máy in được kết nối trực tiếp với máy tính chính."},{"en":"Air quality is directly connected to public health outcomes.","vi":"Chất lượng không khí kết nối trực tiếp với sức khỏe cộng đồng."},{"en":"These two ideas are directly connected to each other.","vi":"Hai ý tưởng này kết nối trực tiếp với nhau."}]','[]',NULL,'/dɪˈrektli kəˈnektɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3824,'colloc-4-01',84,'directly involved in','trực tiếp tham gia vào','adv + vpp','[{"en":"She was directly involved in planning the conference.","vi":"Cô ấy trực tiếp tham gia vào việc lên kế hoạch hội nghị."},{"en":"Students directly involved in the project learned the most.","vi":"Những sinh viên trực tiếp tham gia vào dự án học được nhiều nhất."},{"en":"He was directly involved in the negotiations last year.","vi":"Ông ấy trực tiếp tham gia vào các cuộc đàm phán năm ngoái."}]','[]',NULL,'/dɪˈrektli ɪnˈvɑːlvd ɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3825,'colloc-4-01',85,'directly linked to','liên hệ trực tiếp với','adv + vpp','[{"en":"Poor diet is directly linked to many chronic diseases.","vi":"Ăn uống kém liên hệ trực tiếp với nhiều bệnh mãn tính."},{"en":"The rise in sales is directly linked to the advertising.","vi":"Doanh số tăng liên hệ trực tiếp với việc quảng cáo."},{"en":"Their success is directly linked to careful planning.","vi":"Thành công của họ liên hệ trực tiếp với việc lập kế hoạch kỹ lưỡng."}]','[]',NULL,'/dɪˈrektli lɪŋkt tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3826,'colloc-4-01',86,'directly proportional to','tỷ lệ thuận trực tiếp với','adv + adj','[{"en":"The force is directly proportional to the mass of the object.","vi":"Lực tỷ lệ thuận trực tiếp với khối lượng của vật."},{"en":"Pressure is directly proportional to temperature in this case.","vi":"Áp suất tỷ lệ thuận trực tiếp với nhiệt độ trong trường hợp này."},{"en":"Profit was directly proportional to the number of sales.","vi":"Lợi nhuận tỷ lệ thuận trực tiếp với số lượng bán ra."}]','[]',NULL,'/dɪˈrektli prəˈpɔːrʃənəl tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3827,'colloc-4-01',87,'directly related to','liên quan trực tiếp đến','adv + vpp','[{"en":"His complaint was directly related to the new schedule.","vi":"Khiếu nại của anh ấy liên quan trực tiếp đến lịch trình mới."},{"en":"The questions are directly related to the course content.","vi":"Các câu hỏi liên quan trực tiếp đến nội dung khóa học."},{"en":"Health problems here are directly related to air pollution.","vi":"Các vấn đề sức khỏe ở đây liên quan trực tiếp đến ô nhiễm không khí."}]','[]',NULL,'/dɪˈrektli rɪˈleɪtɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3828,'colloc-4-01',88,'directly relevant to','liên quan thiết thực đến','adv + adj','[{"en":"These findings are directly relevant to current policy debates.","vi":"Những phát hiện này liên quan thiết thực đến các tranh luận chính sách hiện nay."},{"en":"Choose examples that are directly relevant to your topic.","vi":"Hãy chọn ví dụ liên quan thiết thực đến chủ đề của bạn."},{"en":"The training was directly relevant to her daily work.","vi":"Khóa đào tạo liên quan thiết thực đến công việc hằng ngày của cô ấy."}]','[]',NULL,'/dɪˈrektli ˈreləvənt tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3829,'colloc-4-01',89,'directly responsible for','chịu trách nhiệm trực tiếp về','adv + adj','[{"en":"The manager is directly responsible for the team''s budget.","vi":"Người quản lý chịu trách nhiệm trực tiếp về ngân sách của nhóm."},{"en":"Smoking is directly responsible for many early deaths.","vi":"Hút thuốc chịu trách nhiệm trực tiếp cho nhiều ca tử vong sớm."},{"en":"She is directly responsible for training new employees.","vi":"Cô ấy chịu trách nhiệm trực tiếp về việc đào tạo nhân viên mới."}]','[]',NULL,'/dɪˈrektli rɪˈspɑːnsəbəl fər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3830,'colloc-4-01',90,'disclose information','tiết lộ thông tin','v + n','[{"en":"Companies must disclose information about their finances.","vi":"Các công ty phải tiết lộ thông tin về tài chính của mình."},{"en":"Doctors cannot disclose information without the patient''s consent.","vi":"Bác sĩ không thể tiết lộ thông tin khi chưa có sự đồng ý của bệnh nhân."},{"en":"The report refused to disclose information about its sources.","vi":"Báo cáo từ chối tiết lộ thông tin về nguồn của nó."}]','[]',NULL,'/dɪsˈkloʊz ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3831,'colloc-4-01',91,'discuss a topic','thảo luận một chủ đề','v + n','[{"en":"The class will discuss a topic chosen by the students.","vi":"Lớp học sẽ thảo luận một chủ đề do sinh viên chọn."},{"en":"We meet weekly to discuss a topic from the reading.","vi":"Chúng tôi gặp nhau hằng tuần để thảo luận một chủ đề trong bài đọc."},{"en":"It is hard to discuss a topic without enough background.","vi":"Thật khó để thảo luận một chủ đề khi thiếu kiến thức nền."}]','[]',NULL,'/dɪˈskʌs ə ˈtɑːpɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3832,'colloc-4-01',92,'discuss an issue','thảo luận một vấn đề','v + n','[{"en":"The committee met to discuss an issue raised by parents.","vi":"Ủy ban họp để thảo luận một vấn đề do phụ huynh nêu ra."},{"en":"It helps to discuss an issue calmly before deciding.","vi":"Thảo luận một vấn đề một cách bình tĩnh trước khi quyết định sẽ hữu ích."},{"en":"Leaders gathered to discuss an issue affecting the whole region.","vi":"Các lãnh đạo tụ họp để thảo luận một vấn đề ảnh hưởng cả khu vực."}]','[]',NULL,'/dɪˈskʌs ən ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3833,'colloc-4-01',93,'disposable income','thu nhập khả dụng','adj + n','[{"en":"Families with higher disposable income tend to travel more.","vi":"Các gia đình có thu nhập khả dụng cao hơn thường đi du lịch nhiều hơn."},{"en":"Rising prices have reduced people''s disposable income.","vi":"Giá cả tăng đã làm giảm thu nhập khả dụng của người dân."},{"en":"Young workers often spend much of their disposable income.","vi":"Người lao động trẻ thường tiêu phần lớn thu nhập khả dụng của họ."}]','[]',NULL,'/dɪˈspoʊzəbəl ˈɪnkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3834,'colloc-4-01',94,'distinct group','nhóm riêng biệt','adj + n','[{"en":"The study divided the patients into three distinct groups.","vi":"Nghiên cứu chia bệnh nhân thành ba nhóm riêng biệt."},{"en":"Each distinct group followed its own set of rules.","vi":"Mỗi nhóm riêng biệt tuân theo bộ quy tắc riêng của mình."},{"en":"The data revealed a distinct group of frequent users.","vi":"Dữ liệu cho thấy một nhóm riêng biệt gồm người dùng thường xuyên."}]','[]',NULL,'/dɪˈstɪŋkt ɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3835,'colloc-4-01',95,'distinct type','loại riêng biệt','adj + n','[{"en":"Researchers identified two distinct types of cells.","vi":"Các nhà nghiên cứu xác định được hai loại tế bào riêng biệt."},{"en":"Each distinct type of soil supports different plants.","vi":"Mỗi loại đất riêng biệt thích hợp với những cây khác nhau."},{"en":"The museum displays a distinct type of ancient pottery.","vi":"Bảo tàng trưng bày một loại gốm cổ riêng biệt."}]','[]',NULL,'/dɪˈstɪŋkt taɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3836,'colloc-4-01',96,'distinctive feature','đặc điểm nổi bật','adj + n','[{"en":"The bright colors are a distinctive feature of this bird.","vi":"Màu sắc sặc sỡ là đặc điểm nổi bật của loài chim này."},{"en":"Strong arches are a distinctive feature of the architecture.","vi":"Các vòm lớn là đặc điểm nổi bật của lối kiến trúc này."},{"en":"Her clear writing style is a distinctive feature of her work.","vi":"Lối viết rõ ràng là đặc điểm nổi bật trong tác phẩm của cô ấy."}]','[]',NULL,'/dɪˈstɪŋktɪv ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3837,'colloc-4-01',97,'distinguishing feature','đặc điểm phân biệt','adj + n','[{"en":"The long tail is the distinguishing feature of this species.","vi":"Cái đuôi dài là đặc điểm phân biệt của loài này."},{"en":"Price is the main distinguishing feature between the two models.","vi":"Giá cả là đặc điểm phân biệt chính giữa hai mẫu xe."},{"en":"A distinguishing feature of the report is its clear charts.","vi":"Một đặc điểm phân biệt của báo cáo là các biểu đồ rõ ràng."}]','[]',NULL,'/dɪˈstɪŋɡwɪʃɪŋ ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3838,'colloc-4-01',98,'diverse background','xuất thân đa dạng','adj + n','[{"en":"The students come from a diverse background of cultures.","vi":"Các sinh viên đến từ nhiều nền văn hóa với xuất thân đa dạng."},{"en":"Her diverse background helps her understand many viewpoints.","vi":"Xuất thân đa dạng giúp cô ấy hiểu nhiều quan điểm khác nhau."},{"en":"Employers value staff with a diverse background and skills.","vi":"Nhà tuyển dụng coi trọng nhân viên có xuất thân và kỹ năng đa dạng."}]','[]',NULL,'/dɪˈvɜːrs ˈbækɡraʊnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3839,'colloc-4-01',99,'diverse group','nhóm đa dạng','adj + n','[{"en":"The class is a diverse group of learners from many countries.","vi":"Lớp học là một nhóm đa dạng gồm người học từ nhiều quốc gia."},{"en":"A diverse group often produces more creative ideas.","vi":"Một nhóm đa dạng thường tạo ra nhiều ý tưởng sáng tạo hơn."},{"en":"The panel included a diverse group of experts and citizens.","vi":"Hội đồng gồm một nhóm đa dạng các chuyên gia và người dân."}]','[]',NULL,'/dɪˈvɜːrs ɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3840,'colloc-4-01',100,'diverse range of','loạt đa dạng các','adj + n','[{"en":"The shop sells a diverse range of organic products.","vi":"Cửa hàng bán một loạt đa dạng các sản phẩm hữu cơ."},{"en":"The course covers a diverse range of historical topics.","vi":"Khóa học bao quát một loạt đa dạng các chủ đề lịch sử."},{"en":"Volunteers came from a diverse range of professions.","vi":"Các tình nguyện viên đến từ một loạt đa dạng các nghề nghiệp."}]','[]',NULL,'/dɪˈvɜːrs reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3841,'colloc-4-01',101,'dividing line','ranh giới phân chia','adj + n','[{"en":"The river forms a natural dividing line between the regions.","vi":"Con sông tạo thành ranh giới phân chia tự nhiên giữa các vùng."},{"en":"There is a thin dividing line between humor and rudeness.","vi":"Có một ranh giới phân chia mong manh giữa hài hước và thô lỗ."},{"en":"Age is not a clear dividing line for these opinions.","vi":"Tuổi tác không phải ranh giới phân chia rõ ràng cho những quan điểm này."}]','[]',NULL,'/dɪˈvaɪdɪŋ laɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3842,'colloc-4-01',102,'documentary evidence','bằng chứng tài liệu','adj + n','[{"en":"The historian relied on documentary evidence from old letters.","vi":"Nhà sử học dựa vào bằng chứng tài liệu từ những lá thư cũ."},{"en":"Documentary evidence supported the claims made in court.","vi":"Bằng chứng tài liệu ủng hộ các tuyên bố đưa ra tại tòa."},{"en":"Without documentary evidence, the story is hard to verify.","vi":"Nếu thiếu bằng chứng tài liệu, câu chuyện rất khó kiểm chứng."}]','[]',NULL,'/ˌdɑːkjəˈmentəri ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3843,'colloc-4-01',103,'domestic market','thị trường nội địa','adj + n','[{"en":"The company focuses mainly on the domestic market.","vi":"Công ty tập trung chủ yếu vào thị trường nội địa."},{"en":"Cheap imports have hurt the domestic market for textiles.","vi":"Hàng nhập rẻ đã gây tổn hại cho thị trường dệt may nội địa."},{"en":"Strong demand in the domestic market boosted local jobs.","vi":"Nhu cầu mạnh ở thị trường nội địa thúc đẩy việc làm địa phương."}]','[]',NULL,'/dəˈmestɪk ˈmɑːrkɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3844,'colloc-4-01',104,'domestic sphere','phạm vi gia đình','adj + n','[{"en":"In the past, women were largely confined to the domestic sphere.","vi":"Trong quá khứ, phụ nữ phần lớn bị giới hạn trong phạm vi gia đình."},{"en":"The book studies work done within the domestic sphere.","vi":"Cuốn sách nghiên cứu công việc trong phạm vi gia đình."},{"en":"Modern roles blur the line around the domestic sphere.","vi":"Các vai trò hiện đại làm mờ ranh giới của phạm vi gia đình."}]','[]',NULL,'/dəˈmestɪk sfɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3845,'colloc-4-01',105,'domestic violence','bạo lực gia đình','adj + n','[{"en":"The charity helps victims of domestic violence find safety.","vi":"Tổ chức từ thiện giúp nạn nhân bạo lực gia đình tìm nơi an toàn."},{"en":"New laws aim to reduce cases of domestic violence.","vi":"Các luật mới nhằm giảm số vụ bạo lực gia đình."},{"en":"Domestic violence often goes unreported for many years.","vi":"Bạo lực gia đình thường không được báo cáo trong nhiều năm."}]','[]',NULL,'/dəˈmestɪk ˈvaɪələns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3846,'colloc-4-01',106,'dominant culture','văn hóa chủ đạo','adj + n','[{"en":"Immigrants often adapt to the dominant culture over time.","vi":"Người nhập cư thường thích nghi với văn hóa chủ đạo theo thời gian."},{"en":"The dominant culture shapes what is shown in the media.","vi":"Văn hóa chủ đạo định hình những gì được thể hiện trên truyền thông."},{"en":"Smaller traditions can be lost within a dominant culture.","vi":"Các truyền thống nhỏ có thể bị mai một trong một văn hóa chủ đạo."}]','[]',NULL,'/ˈdɑːmɪnənt ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3847,'colloc-4-01',107,'dominant discourse','diễn ngôn chủ đạo','adj + n','[{"en":"The essay challenges the dominant discourse on poverty.","vi":"Bài luận thách thức diễn ngôn chủ đạo về đói nghèo."},{"en":"Media often reinforce the dominant discourse of a society.","vi":"Truyền thông thường củng cố diễn ngôn chủ đạo của một xã hội."},{"en":"Scholars question the dominant discourse around success.","vi":"Các học giả đặt nghi vấn về diễn ngôn chủ đạo quanh sự thành công."}]','[]',NULL,'/ˈdɑːmɪnənt ˈdɪskɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3848,'colloc-4-01',108,'dominant form','hình thức chủ đạo','adj + n','[{"en":"Television was once the dominant form of entertainment.","vi":"Truyền hình từng là hình thức giải trí chủ đạo."},{"en":"Email remains the dominant form of business communication.","vi":"Email vẫn là hình thức giao tiếp chủ đạo trong kinh doanh."},{"en":"Cash is no longer the dominant form of payment here.","vi":"Tiền mặt không còn là hình thức thanh toán chủ đạo ở đây."}]','[]',NULL,'/ˈdɑːmɪnənt fɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3849,'colloc-4-01',109,'dominant group','nhóm thống trị','adj + n','[{"en":"The dominant group often controls access to resources.","vi":"Nhóm thống trị thường kiểm soát quyền tiếp cận tài nguyên."},{"en":"Policies sometimes favor the dominant group in society.","vi":"Các chính sách đôi khi ưu ái nhóm thống trị trong xã hội."},{"en":"Members of the dominant group rarely notice their advantages.","vi":"Các thành viên của nhóm thống trị hiếm khi nhận ra lợi thế của mình."}]','[]',NULL,'/ˈdɑːmɪnənt ɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3850,'colloc-4-01',110,'dominant ideology','hệ tư tưởng chủ đạo','adj + n','[{"en":"The dominant ideology of the era praised free trade.","vi":"Hệ tư tưởng chủ đạo của thời kỳ đó ca ngợi tự do thương mại."},{"en":"Schools can quietly pass on the dominant ideology.","vi":"Trường học có thể âm thầm truyền tải hệ tư tưởng chủ đạo."},{"en":"Artists sometimes resist the dominant ideology of their time.","vi":"Nghệ sĩ đôi khi chống lại hệ tư tưởng chủ đạo của thời đại mình."}]','[]',NULL,'/ˈdɑːmɪnənt ˌaɪdiˈɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3851,'colloc-4-01',111,'dominant paradigm','mô hình chủ đạo','adj + n','[{"en":"The dominant paradigm in physics shifted after Einstein.","vi":"Mô hình chủ đạo trong vật lý đã thay đổi sau Einstein."},{"en":"Her research questions the dominant paradigm in economics.","vi":"Nghiên cứu của cô ấy đặt nghi vấn về mô hình chủ đạo trong kinh tế học."},{"en":"A new dominant paradigm can take decades to take hold.","vi":"Một mô hình chủ đạo mới có thể mất hàng thập kỷ để được chấp nhận."}]','[]',NULL,'/ˈdɑːmɪnənt ˈpærədaɪm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3852,'colloc-4-01',112,'dominant position','vị thế thống trị','adj + n','[{"en":"The firm holds a dominant position in the software market.","vi":"Công ty giữ vị thế thống trị trên thị trường phần mềm."},{"en":"Their dominant position allowed them to set high prices.","vi":"Vị thế thống trị cho phép họ đặt giá cao."},{"en":"A dominant position in trade gave the city great wealth.","vi":"Vị thế thống trị trong thương mại mang lại cho thành phố sự giàu có lớn."}]','[]',NULL,'/ˈdɑːmɪnənt pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3853,'colloc-4-01',113,'dominant role','vai trò chủ đạo','adj + n','[{"en":"Oil plays a dominant role in the country''s economy.","vi":"Dầu mỏ đóng vai trò chủ đạo trong nền kinh tế của đất nước."},{"en":"She took a dominant role in leading the discussion.","vi":"Cô ấy đảm nhận vai trò chủ đạo trong việc dẫn dắt thảo luận."},{"en":"Technology now has a dominant role in modern education.","vi":"Công nghệ giờ đây đóng vai trò chủ đạo trong giáo dục hiện đại."}]','[]',NULL,'/ˈdɑːmɪnənt roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3854,'colloc-4-01',114,'dramatic change','sự thay đổi mạnh mẽ','adj + n','[{"en":"The city has seen a dramatic change over the past decade.","vi":"Thành phố đã chứng kiến sự thay đổi mạnh mẽ trong thập kỷ qua."},{"en":"New technology brought a dramatic change to farming.","vi":"Công nghệ mới mang lại sự thay đổi mạnh mẽ cho ngành nông nghiệp."},{"en":"There was a dramatic change in attitudes after the campaign.","vi":"Đã có một sự thay đổi mạnh mẽ trong thái độ sau chiến dịch."}]','[]',NULL,'/drəˈmætɪk tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3855,'colloc-4-01',115,'dramatic effect','tác động mạnh mẽ','adj + n','[{"en":"The new law had a dramatic effect on small businesses.","vi":"Luật mới có tác động mạnh mẽ đến các doanh nghiệp nhỏ."},{"en":"Good lighting can have a dramatic effect on a photo.","vi":"Ánh sáng tốt có thể tạo tác động mạnh mẽ lên một bức ảnh."},{"en":"Exercise had a dramatic effect on her overall health.","vi":"Tập thể dục có tác động mạnh mẽ đến sức khỏe tổng thể của cô ấy."}]','[]',NULL,'/drəˈmætɪk ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3856,'colloc-4-01',116,'dramatic increase','sự gia tăng mạnh mẽ','adj + n','[{"en":"There was a dramatic increase in online sales last year.","vi":"Đã có sự gia tăng mạnh mẽ về doanh số trực tuyến năm ngoái."},{"en":"The report shows a dramatic increase in energy prices.","vi":"Báo cáo cho thấy sự gia tăng mạnh mẽ về giá năng lượng."},{"en":"A dramatic increase in users strained the company''s servers.","vi":"Sự gia tăng mạnh mẽ về người dùng gây áp lực lên máy chủ của công ty."}]','[]',NULL,'/drəˈmætɪk ˈɪnkriːs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3857,'colloc-4-01',117,'draw attention to','thu hút sự chú ý đến','v + n','[{"en":"The campaign aims to draw attention to climate change.","vi":"Chiến dịch nhằm thu hút sự chú ý đến biến đổi khí hậu."},{"en":"She used bright colors to draw attention to the poster.","vi":"Cô ấy dùng màu sắc tươi sáng để thu hút sự chú ý đến tấm áp phích."},{"en":"The author wants to draw attention to a forgotten issue.","vi":"Tác giả muốn thu hút sự chú ý đến một vấn đề bị lãng quên."}]','[]',NULL,'/drɔː əˈtenʃən tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3858,'colloc-4-01',118,'draw a conclusion','rút ra một kết luận','v + n','[{"en":"It is too early to draw a conclusion from this data.","vi":"Còn quá sớm để rút ra một kết luận từ dữ liệu này."},{"en":"Readers can draw a conclusion based on the evidence given.","vi":"Người đọc có thể rút ra một kết luận dựa trên bằng chứng đã nêu."},{"en":"Scientists draw a conclusion only after repeated testing.","vi":"Các nhà khoa học chỉ rút ra một kết luận sau nhiều lần kiểm tra."}]','[]',NULL,'/drɔː ə kənˈkluːʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3859,'colloc-4-01',119,'draw a distinction','phân biệt rõ ràng','v + n','[{"en":"The author draws a distinction between belief and knowledge.","vi":"Tác giả phân biệt rõ ràng giữa niềm tin và kiến thức."},{"en":"We must draw a distinction between cause and correlation.","vi":"Chúng ta phải phân biệt rõ ràng giữa nguyên nhân và mối tương quan."},{"en":"It helps to draw a distinction between needs and wants.","vi":"Việc phân biệt rõ ràng giữa nhu cầu và mong muốn rất hữu ích."}]','[]',NULL,'/drɔː ə dɪˈstɪŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3860,'colloc-4-01',120,'draw a line','vạch ra ranh giới','v + n','[{"en":"It is hard to draw a line between work and rest.","vi":"Thật khó để vạch ra ranh giới giữa công việc và nghỉ ngơi."},{"en":"Parents should draw a line on screen time for children.","vi":"Cha mẹ nên vạch ra ranh giới về thời gian dùng màn hình cho trẻ."},{"en":"The law draws a line between free speech and harm.","vi":"Luật pháp vạch ra ranh giới giữa tự do ngôn luận và gây hại."}]','[]',NULL,'/drɔː ə laɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3861,'colloc-4-01',121,'driving force','động lực chính','adj + n','[{"en":"Innovation is the driving force behind the company''s success.","vi":"Đổi mới là động lực chính đằng sau thành công của công ty."},{"en":"Curiosity was the driving force in her research career.","vi":"Sự tò mò là động lực chính trong sự nghiệp nghiên cứu của cô ấy."},{"en":"Trade became the driving force of the region''s growth.","vi":"Thương mại trở thành động lực chính cho sự tăng trưởng của khu vực."}]','[]',NULL,'/ˈdraɪvɪŋ fɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3862,'colloc-4-01',122,'due process','trình tự pháp lý đúng đắn','adj + n','[{"en":"Every citizen is entitled to due process under the law.","vi":"Mỗi công dân đều có quyền được hưởng trình tự pháp lý đúng đắn."},{"en":"The court ensured due process before reaching a verdict.","vi":"Tòa án bảo đảm trình tự pháp lý đúng đắn trước khi đưa ra phán quyết."},{"en":"Skipping due process can make a decision unlawful.","vi":"Bỏ qua trình tự pháp lý đúng đắn có thể khiến quyết định trái luật."}]','[]',NULL,'/duː ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3863,'colloc-4-01',123,'dynamic equilibrium','cân bằng động','adj + n','[{"en":"The reaction reaches a dynamic equilibrium after a few minutes.","vi":"Phản ứng đạt tới trạng thái cân bằng động sau vài phút."},{"en":"In dynamic equilibrium, forward and reverse rates are equal.","vi":"Trong cân bằng động, tốc độ thuận và nghịch bằng nhau."},{"en":"Ecosystems often exist in a fragile dynamic equilibrium.","vi":"Các hệ sinh thái thường tồn tại trong một cân bằng động mong manh."}]','[]',NULL,'/daɪˈnæmɪk ˌiːkwəˈlɪbriəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3864,'colloc-4-01',124,'dynamic nature','bản chất năng động','adj + n','[{"en":"The dynamic nature of language makes it hard to fix rules.","vi":"Bản chất năng động của ngôn ngữ khiến việc cố định quy tắc rất khó."},{"en":"Markets change quickly due to their dynamic nature.","vi":"Thị trường thay đổi nhanh do bản chất năng động của nó."},{"en":"The dynamic nature of the field demands constant learning.","vi":"Bản chất năng động của lĩnh vực này đòi hỏi việc học liên tục."}]','[]',NULL,'/daɪˈnæmɪk ˈneɪtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3865,'colloc-4-01',125,'dynamic process','quá trình năng động','adj + n','[{"en":"Learning is a dynamic process that continues throughout life.","vi":"Học tập là một quá trình năng động kéo dài suốt đời."},{"en":"Cell growth is a dynamic process influenced by many factors.","vi":"Sự phát triển của tế bào là quá trình năng động chịu nhiều yếu tố tác động."},{"en":"Culture is a dynamic process, always shifting over time.","vi":"Văn hóa là một quá trình năng động, luôn thay đổi theo thời gian."}]','[]',NULL,'/daɪˈnæmɪk ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3866,'colloc-4-01',126,'dynamic system','hệ thống động','adj + n','[{"en":"The climate is a dynamic system with many feedback loops.","vi":"Khí hậu là một hệ thống động với nhiều vòng phản hồi."},{"en":"Engineers model the bridge as a dynamic system under load.","vi":"Các kỹ sư mô hình hóa cây cầu như một hệ thống động khi chịu tải."},{"en":"A market is a dynamic system shaped by countless decisions.","vi":"Thị trường là một hệ thống động được định hình bởi vô số quyết định."}]','[]',NULL,'/daɪˈnæmɪk ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3867,'colloc-4-01',127,'earlier discussion','phần thảo luận trước đó','adj + n','[{"en":"As noted in the earlier discussion, the data are limited.","vi":"Như đã nêu trong phần thảo luận trước đó, dữ liệu còn hạn chế."},{"en":"This section builds on the earlier discussion of causes.","vi":"Phần này dựa trên phần thảo luận trước đó về các nguyên nhân."},{"en":"The earlier discussion raised several unanswered questions.","vi":"Phần thảo luận trước đó đã nêu ra nhiều câu hỏi chưa được giải đáp."}]','[]',NULL,'/ˈɜːrliər dɪˈskʌʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3868,'colloc-4-01',128,'earlier period','thời kỳ trước đó','adj + n','[{"en":"These customs date back to an earlier period in history.","vi":"Những phong tục này có từ một thời kỳ trước đó trong lịch sử."},{"en":"Wages were much lower during the earlier period studied.","vi":"Tiền lương thấp hơn nhiều trong thời kỳ trước đó được nghiên cứu."},{"en":"Art from the earlier period shows simpler designs.","vi":"Nghệ thuật từ thời kỳ trước đó cho thấy những thiết kế đơn giản hơn."}]','[]',NULL,'/ˈɜːrliər ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3869,'colloc-4-01',129,'earlier research','nghiên cứu trước đó','adj + n','[{"en":"These results confirm the findings of earlier research.","vi":"Những kết quả này xác nhận các phát hiện của nghiên cứu trước đó."},{"en":"Earlier research had ignored the role of social factors.","vi":"Nghiên cứu trước đó đã bỏ qua vai trò của các yếu tố xã hội."},{"en":"Her study builds directly on earlier research in the field.","vi":"Nghiên cứu của cô ấy dựa trực tiếp vào nghiên cứu trước đó trong lĩnh vực này."}]','[]',NULL,'/ˈɜːrliər ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3870,'colloc-4-01',130,'earlier stage','giai đoạn trước đó','adj + n','[{"en":"Problems are easier to fix at an earlier stage.","vi":"Các vấn đề dễ khắc phục hơn ở một giai đoạn trước đó."},{"en":"At an earlier stage, the plan looked very different.","vi":"Ở một giai đoạn trước đó, kế hoạch trông rất khác."},{"en":"Doctors aim to detect the disease at an earlier stage.","vi":"Bác sĩ hướng tới phát hiện bệnh ở một giai đoạn trước đó."}]','[]',NULL,'/ˈɜːrliər steɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3871,'colloc-4-01',131,'earlier study','nghiên cứu trước đó','adj + n','[{"en":"An earlier study reached very different conclusions about the topic.","vi":"Một nghiên cứu trước đó đã đưa ra những kết luận rất khác về chủ đề này."},{"en":"We compared our results with an earlier study from 2010.","vi":"Chúng tôi đã so sánh kết quả với một nghiên cứu trước đó từ năm 2010."},{"en":"The earlier study used a much smaller sample size.","vi":"Nghiên cứu trước đó dùng cỡ mẫu nhỏ hơn nhiều."}]','[]',NULL,'/ˈɜːrliər ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3872,'colloc-4-01',132,'earlier times','thời kỳ trước đây','adj + n','[{"en":"In earlier times, most people lived in rural villages.","vi":"Vào thời kỳ trước đây, hầu hết mọi người sống ở làng quê."},{"en":"Trade was much slower in earlier times than today.","vi":"Việc buôn bán chậm hơn nhiều vào thời kỳ trước đây so với ngày nay."},{"en":"These traditions date back to much earlier times.","vi":"Những truyền thống này có từ những thời kỳ trước đây rất lâu."}]','[]',NULL,'/ˈɜːrliər taɪmz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3873,'colloc-4-01',133,'earlier version','phiên bản trước đó','adj + n','[{"en":"An earlier version of the software lacked this feature.","vi":"Một phiên bản trước đó của phần mềm thiếu tính năng này."},{"en":"The earlier version of the report contained several errors.","vi":"Phiên bản trước đó của báo cáo chứa một số lỗi."},{"en":"Reviewers had read an earlier version of the paper.","vi":"Người bình duyệt đã đọc một phiên bản trước đó của bài báo."}]','[]',NULL,'/ˈɜːrliər ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3874,'colloc-4-01',134,'earlier work','công trình trước đó','adj + n','[{"en":"Her earlier work focused mainly on childhood language development.","vi":"Công trình trước đó của bà tập trung chủ yếu vào sự phát triển ngôn ngữ ở trẻ em."},{"en":"This paper builds directly on the author''s earlier work.","vi":"Bài báo này được xây dựng trực tiếp trên công trình trước đó của tác giả."},{"en":"Earlier work in this field had largely been ignored.","vi":"Các công trình trước đó trong lĩnh vực này phần lớn bị bỏ qua."}]','[]',NULL,'/ˈɜːrliər wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3875,'colloc-4-01',135,'early decades','những thập niên đầu','adj + n','[{"en":"The early decades of the century saw rapid industrial growth.","vi":"Những thập niên đầu của thế kỷ chứng kiến sự tăng trưởng công nghiệp nhanh chóng."},{"en":"Computers were rare during the early decades of the field.","vi":"Máy tính rất hiếm trong những thập niên đầu của lĩnh vực này."},{"en":"In the early decades, the company employed only ten workers.","vi":"Trong những thập niên đầu, công ty chỉ thuê mười nhân công."}]','[]',NULL,'/ˈɜːrli ˈdekeɪdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3876,'colloc-4-01',136,'early study','nghiên cứu ban đầu','adj + n','[{"en":"An early study suggested a link between diet and sleep.","vi":"Một nghiên cứu ban đầu cho thấy mối liên hệ giữa chế độ ăn và giấc ngủ."},{"en":"Each early study relied on rather limited data.","vi":"Mỗi nghiên cứu ban đầu đều dựa trên dữ liệu khá hạn chế."},{"en":"The early study laid the groundwork for later research.","vi":"Nghiên cứu ban đầu đã đặt nền móng cho các nghiên cứu về sau."}]','[]',NULL,'/ˈɜːrli ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3877,'colloc-4-01',137,'easily accessible','dễ tiếp cận','adv + adj','[{"en":"The library makes its archives easily accessible to students.","vi":"Thư viện làm cho kho lưu trữ dễ tiếp cận với sinh viên."},{"en":"Public transport keeps the city center easily accessible.","vi":"Giao thông công cộng giúp trung tâm thành phố dễ tiếp cận."},{"en":"Online resources are easily accessible from any device.","vi":"Tài nguyên trực tuyến dễ tiếp cận từ bất kỳ thiết bị nào."}]','[]',NULL,'/ˈiːzəli əkˈsesəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3878,'colloc-4-01',138,'easily identified','dễ nhận ra','adv + vpp','[{"en":"The error was easily identified during the first review.","vi":"Lỗi này dễ dàng được nhận ra trong lần kiểm tra đầu tiên."},{"en":"These patterns are easily identified in the raw data.","vi":"Những mẫu hình này dễ được nhận ra trong dữ liệu thô."},{"en":"Affected plants can be easily identified by their spots.","vi":"Cây bị ảnh hưởng có thể dễ dàng được nhận ra qua các đốm."}]','[]',NULL,'/ˈiːzəli aɪˈdentɪfaɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3879,'colloc-4-01',139,'easily understood','dễ hiểu','adv + vpp','[{"en":"The instructions were clear and easily understood by everyone.","vi":"Hướng dẫn rõ ràng và mọi người dễ dàng hiểu được."},{"en":"Good charts make complex data easily understood.","vi":"Biểu đồ tốt giúp dữ liệu phức tạp trở nên dễ hiểu."},{"en":"The concept is easily understood once examples are given.","vi":"Khái niệm này dễ hiểu khi đã có ví dụ."}]','[]',NULL,'/ˈiːzəli ˌʌndərˈstʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3880,'colloc-4-01',140,'easy access','sự tiếp cận dễ dàng','adj + n','[{"en":"Students need easy access to reliable academic sources.","vi":"Sinh viên cần sự tiếp cận dễ dàng với các nguồn học thuật đáng tin cậy."},{"en":"The app gives users easy access to their records.","vi":"Ứng dụng cho người dùng sự tiếp cận dễ dàng đến hồ sơ của họ."},{"en":"Easy access to clean water improves community health.","vi":"Sự tiếp cận dễ dàng với nước sạch cải thiện sức khỏe cộng đồng."}]','[]',NULL,'/ˈiːzi ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3881,'colloc-4-01',141,'economic activity','hoạt động kinh tế','adj + n','[{"en":"The pandemic sharply reduced economic activity across the region.","vi":"Đại dịch đã làm giảm mạnh hoạt động kinh tế trên toàn khu vực."},{"en":"Tourism remains the main economic activity on the island.","vi":"Du lịch vẫn là hoạt động kinh tế chính trên đảo."},{"en":"Lower interest rates can boost economic activity quickly.","vi":"Lãi suất thấp hơn có thể thúc đẩy hoạt động kinh tế nhanh chóng."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3882,'colloc-4-01',142,'economic affairs','các vấn đề kinh tế','adj + n','[{"en":"The minister is responsible for the nation''s economic affairs.","vi":"Bộ trưởng chịu trách nhiệm về các vấn đề kinh tế của quốc gia."},{"en":"The committee advises the government on economic affairs.","vi":"Ủy ban tư vấn cho chính phủ về các vấn đề kinh tế."},{"en":"Newspapers devote whole sections to economic affairs.","vi":"Báo chí dành cả những chuyên mục cho các vấn đề kinh tế."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk əˈferz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3883,'colloc-4-01',143,'economic analysis','phân tích kinh tế','adj + n','[{"en":"A careful economic analysis showed the project was unprofitable.","vi":"Một phân tích kinh tế cẩn thận cho thấy dự án không có lãi."},{"en":"The report includes a detailed economic analysis of costs.","vi":"Báo cáo bao gồm một phân tích kinh tế chi tiết về chi phí."},{"en":"Economic analysis helps governments plan future budgets.","vi":"Phân tích kinh tế giúp các chính phủ lập kế hoạch ngân sách tương lai."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3884,'colloc-4-01',144,'economic benefits','lợi ích kinh tế','adj + n','[{"en":"The new factory brought clear economic benefits to the town.","vi":"Nhà máy mới mang lại lợi ích kinh tế rõ rệt cho thị trấn."},{"en":"Researchers measured the economic benefits of better education.","vi":"Các nhà nghiên cứu đo lường lợi ích kinh tế của giáo dục tốt hơn."},{"en":"Renewable energy offers long-term economic benefits.","vi":"Năng lượng tái tạo mang lại lợi ích kinh tế lâu dài."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈbenɪfɪts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3885,'colloc-4-01',145,'economic change','sự thay đổi kinh tế','adj + n','[{"en":"Rapid economic change forced many workers to retrain.","vi":"Sự thay đổi kinh tế nhanh chóng buộc nhiều công nhân phải học lại nghề."},{"en":"The study tracks economic change over three decades.","vi":"Nghiên cứu theo dõi sự thay đổi kinh tế trong ba thập kỷ."},{"en":"Technology often drives deep economic change in society.","vi":"Công nghệ thường thúc đẩy sự thay đổi kinh tế sâu sắc trong xã hội."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3886,'colloc-4-01',146,'economic conditions','điều kiện kinh tế','adj + n','[{"en":"Poor economic conditions made it hard to find work.","vi":"Điều kiện kinh tế kém khiến việc tìm kiếm công việc trở nên khó khăn."},{"en":"Investment decisions depend heavily on current economic conditions.","vi":"Quyết định đầu tư phụ thuộc nhiều vào điều kiện kinh tế hiện tại."},{"en":"Economic conditions improved steadily after the reforms.","vi":"Điều kiện kinh tế cải thiện đều đặn sau các cải cách."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3887,'colloc-4-01',147,'economic consequences','hậu quả kinh tế','adj + n','[{"en":"The war had severe economic consequences for both nations.","vi":"Cuộc chiến gây ra hậu quả kinh tế nghiêm trọng cho cả hai quốc gia."},{"en":"Policymakers must consider the economic consequences of higher taxes.","vi":"Các nhà hoạch định phải cân nhắc hậu quả kinh tế của việc tăng thuế."},{"en":"Climate change carries far-reaching economic consequences.","vi":"Biến đổi khí hậu mang lại những hậu quả kinh tế sâu rộng."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈkɑːnsɪkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3888,'colloc-4-01',148,'economic context','bối cảnh kinh tế','adj + n','[{"en":"These reforms must be understood in their economic context.","vi":"Những cải cách này phải được hiểu trong bối cảnh kinh tế của chúng."},{"en":"The author describes the wider economic context of the period.","vi":"Tác giả mô tả bối cảnh kinh tế rộng lớn hơn của thời kỳ đó."},{"en":"Decisions made sense within the economic context of the time.","vi":"Các quyết định trở nên hợp lý trong bối cảnh kinh tế thời bấy giờ."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3889,'colloc-4-01',149,'economic crisis','khủng hoảng kinh tế','adj + n','[{"en":"The economic crisis left millions of people unemployed.","vi":"Cuộc khủng hoảng kinh tế khiến hàng triệu người thất nghiệp."},{"en":"Governments struggled to respond to the economic crisis.","vi":"Các chính phủ chật vật ứng phó với cuộc khủng hoảng kinh tế."},{"en":"The 2008 economic crisis reshaped global financial regulation.","vi":"Cuộc khủng hoảng kinh tế năm 2008 đã định hình lại quy định tài chính toàn cầu."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈkraɪsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3890,'colloc-4-01',150,'economic exploitation','sự bóc lột kinh tế','adj + n','[{"en":"The book examines the economic exploitation of colonial workers.","vi":"Cuốn sách xem xét sự bóc lột kinh tế đối với công nhân thuộc địa."},{"en":"Weak laws allowed widespread economic exploitation of migrants.","vi":"Luật lệ yếu kém cho phép sự bóc lột kinh tế tràn lan đối với người di cư."},{"en":"Activists campaigned against the economic exploitation of children.","vi":"Các nhà hoạt động vận động chống lại sự bóc lột kinh tế đối với trẻ em."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˌeksplɔɪˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3891,'colloc-5-01',1,'economic factors','các yếu tố kinh tế','adj + n','[{"en":"Several economic factors influenced the family''s decision to move.","vi":"Một số yếu tố kinh tế ảnh hưởng đến quyết định chuyển nhà của gia đình."},{"en":"The study controlled for economic factors such as income.","vi":"Nghiên cứu đã kiểm soát các yếu tố kinh tế như thu nhập."},{"en":"Economic factors alone cannot explain the trend.","vi":"Các yếu tố kinh tế đơn thuần không thể giải thích xu hướng này."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3892,'colloc-5-01',2,'economic forces','các lực lượng kinh tế','adj + n','[{"en":"Powerful economic forces shaped the city''s rapid growth.","vi":"Những lực lượng kinh tế mạnh mẽ định hình sự phát triển nhanh của thành phố."},{"en":"Global economic forces affect small local businesses too.","vi":"Các lực lượng kinh tế toàn cầu cũng tác động đến doanh nghiệp địa phương nhỏ."},{"en":"The decline resulted from forces beyond local control.","vi":"Sự suy giảm bắt nguồn từ những lực lượng nằm ngoài tầm kiểm soát địa phương."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈfɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3893,'colloc-5-01',3,'economic goal','mục tiêu kinh tế','adj + n','[{"en":"Reducing unemployment is the government''s main economic goal.","vi":"Giảm tỷ lệ thất nghiệp là mục tiêu kinh tế chính của chính phủ."},{"en":"The plan balances social and economic goals carefully.","vi":"Kế hoạch cân bằng cẩn thận giữa mục tiêu xã hội và kinh tế."},{"en":"Each economic goal must be measurable and realistic.","vi":"Mỗi mục tiêu kinh tế phải đo lường được và thực tế."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ɡoʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3894,'colloc-5-01',4,'economic growth','tăng trưởng kinh tế','adj + n','[{"en":"Strong economic growth created thousands of new jobs.","vi":"Tăng trưởng kinh tế mạnh mẽ tạo ra hàng nghìn việc làm mới."},{"en":"Education investment supports long-term economic growth.","vi":"Đầu tư vào giáo dục hỗ trợ tăng trưởng kinh tế lâu dài."},{"en":"Economic growth slowed sharply during the recession.","vi":"Tăng trưởng kinh tế chững lại rõ rệt trong thời kỳ suy thoái."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ɡroʊθ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3895,'colloc-5-01',5,'economic inequality','bất bình đẳng kinh tế','adj + n','[{"en":"Economic inequality has widened in many developed countries.","vi":"Bất bình đẳng kinh tế đã gia tăng ở nhiều nước phát triển."},{"en":"The policy aims to reduce growing economic inequality.","vi":"Chính sách nhằm giảm bớt sự bất bình đẳng kinh tế ngày càng tăng."},{"en":"High economic inequality can fuel social unrest.","vi":"Bất bình đẳng kinh tế cao có thể thổi bùng bất ổn xã hội."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˌɪnɪˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3896,'colloc-5-01',6,'economic integration','hội nhập kinh tế','adj + n','[{"en":"Economic integration allowed goods to move freely between countries.","vi":"Hội nhập kinh tế cho phép hàng hóa lưu thông tự do giữa các nước."},{"en":"The treaty promotes deeper economic integration in the region.","vi":"Hiệp ước thúc đẩy hội nhập kinh tế sâu rộng hơn trong khu vực."},{"en":"Economic integration can lower prices for consumers.","vi":"Hội nhập kinh tế có thể giảm giá cho người tiêu dùng."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˌɪntɪˈɡreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3897,'colloc-5-01',7,'economic interests','lợi ích kinh tế','adj + n','[{"en":"The two nations share important economic interests.","vi":"Hai quốc gia chia sẻ những lợi ích kinh tế quan trọng."},{"en":"Critics argue the law protects narrow economic interests.","vi":"Các nhà phê bình cho rằng luật này bảo vệ những lợi ích kinh tế hẹp hòi."},{"en":"Companies often lobby to defend their economic interests.","vi":"Các công ty thường vận động hành lang để bảo vệ lợi ích kinh tế."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈɪntrəsts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3898,'colloc-5-01',8,'economic policy','chính sách kinh tế','adj + n','[{"en":"The new economic policy aims to control inflation.","vi":"Chính sách kinh tế mới nhằm kiểm soát lạm phát."},{"en":"Economists disagreed sharply about the government''s economic policy.","vi":"Các nhà kinh tế bất đồng gay gắt về chính sách kinh tế của chính phủ."},{"en":"Sound economic policy can stabilize a fragile market.","vi":"Chính sách kinh tế hợp lý có thể ổn định một thị trường mong manh."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3899,'colloc-5-01',9,'economic power','sức mạnh kinh tế','adj + n','[{"en":"The country''s economic power grew rapidly after the reforms.","vi":"Sức mạnh kinh tế của quốc gia tăng nhanh sau các cải cách."},{"en":"Large corporations wield enormous economic power today.","vi":"Các tập đoàn lớn nắm giữ sức mạnh kinh tế khổng lồ ngày nay."},{"en":"Economic power often translates into political influence.","vi":"Sức mạnh kinh tế thường chuyển thành ảnh hưởng chính trị."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3900,'colloc-5-01',10,'economic prosperity','sự thịnh vượng kinh tế','adj + n','[{"en":"Stable institutions are essential for lasting economic prosperity.","vi":"Các thể chế ổn định là điều thiết yếu cho sự thịnh vượng kinh tế bền vững."},{"en":"Trade brought a period of remarkable economic prosperity.","vi":"Thương mại mang lại một thời kỳ thịnh vượng kinh tế đáng kể."},{"en":"Many factors contribute to a region''s economic prosperity.","vi":"Nhiều yếu tố góp phần vào sự thịnh vượng kinh tế của một vùng."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk prɑːˈsperəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3901,'colloc-5-01',11,'economic reform','cải cách kinh tế','adj + n','[{"en":"Economic reform opened the country to foreign investment.","vi":"Cải cách kinh tế đã mở cửa đất nước cho đầu tư nước ngoài."},{"en":"The government promised sweeping economic reform after the election.","vi":"Chính phủ hứa hẹn cải cách kinh tế sâu rộng sau bầu cử."},{"en":"Economic reform often faces strong political resistance.","vi":"Cải cách kinh tế thường vấp phải sự phản kháng chính trị mạnh mẽ."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk rɪˈfɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3902,'colloc-5-01',12,'economic relations','quan hệ kinh tế','adj + n','[{"en":"The agreement strengthened economic relations between the two states.","vi":"Hiệp định củng cố quan hệ kinh tế giữa hai quốc gia."},{"en":"Tensions damaged economic relations across the border.","vi":"Căng thẳng làm tổn hại quan hệ kinh tế xuyên biên giới."},{"en":"Trade fairs help build new economic relations.","vi":"Hội chợ thương mại giúp xây dựng quan hệ kinh tế mới."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk rɪˈleɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3903,'colloc-5-01',13,'economic relationships','các mối quan hệ kinh tế','adj + n','[{"en":"Global trade creates complex economic relationships between nations.","vi":"Thương mại toàn cầu tạo ra các mối quan hệ kinh tế phức tạp giữa các nước."},{"en":"The chapter analyzes economic relationships within rural communities.","vi":"Chương này phân tích các mối quan hệ kinh tế trong cộng đồng nông thôn."},{"en":"Trust underpins long-term economic relationships between firms.","vi":"Niềm tin là nền tảng cho các mối quan hệ kinh tế lâu dài giữa các công ty."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk rɪˈleɪʃənʃɪps/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3904,'colloc-5-01',14,'economic resources','nguồn lực kinh tế','adj + n','[{"en":"The region lacks the economic resources to rebuild quickly.","vi":"Khu vực thiếu nguồn lực kinh tế để tái thiết nhanh chóng."},{"en":"Wealthy families can devote more economic resources to education.","vi":"Gia đình giàu có thể dành nhiều nguồn lực kinh tế hơn cho giáo dục."},{"en":"Scarce economic resources must be allocated carefully.","vi":"Nguồn lực kinh tế khan hiếm phải được phân bổ cẩn thận."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3905,'colloc-5-01',15,'economic sector','khu vực kinh tế','adj + n','[{"en":"The service economic sector now employs most urban workers.","vi":"Khu vực kinh tế dịch vụ hiện thuê hầu hết lao động đô thị."},{"en":"Each economic sector responded differently to the new tax.","vi":"Mỗi khu vực kinh tế phản ứng khác nhau với loại thuế mới."},{"en":"The report focuses on the agricultural economic sector.","vi":"Báo cáo tập trung vào khu vực kinh tế nông nghiệp."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈsektər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3906,'colloc-5-01',16,'economic stability','sự ổn định kinh tế','adj + n','[{"en":"Low inflation contributes to long-term economic stability.","vi":"Lạm phát thấp góp phần vào sự ổn định kinh tế lâu dài."},{"en":"Investors prefer countries with strong economic stability.","vi":"Nhà đầu tư ưa chuộng các nước có sự ổn định kinh tế vững chắc."},{"en":"The crisis threatened the region''s fragile economic stability.","vi":"Cuộc khủng hoảng đe dọa sự ổn định kinh tế mong manh của khu vực."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk stəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3907,'colloc-5-01',17,'economic status','địa vị kinh tế','adj + n','[{"en":"A family''s economic status often affects children''s opportunities.","vi":"Địa vị kinh tế của một gia đình thường ảnh hưởng đến cơ hội của con cái."},{"en":"The survey grouped respondents by economic status.","vi":"Cuộc khảo sát phân nhóm người trả lời theo địa vị kinh tế."},{"en":"Education can help people improve their economic status.","vi":"Giáo dục có thể giúp con người cải thiện địa vị kinh tế."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈstætəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3908,'colloc-5-01',18,'economic structure','cấu trúc kinh tế','adj + n','[{"en":"Industrialization transformed the country''s entire economic structure.","vi":"Công nghiệp hóa đã biến đổi toàn bộ cấu trúc kinh tế của đất nước."},{"en":"The economic structure shifted from farming to manufacturing.","vi":"Cấu trúc kinh tế chuyển từ nông nghiệp sang sản xuất."},{"en":"A rigid economic structure can slow needed change.","vi":"Một cấu trúc kinh tế cứng nhắc có thể làm chậm những thay đổi cần thiết."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3909,'colloc-5-01',19,'economic success','thành công kinh tế','adj + n','[{"en":"The firm''s economic success depended on constant innovation.","vi":"Thành công kinh tế của công ty phụ thuộc vào sự đổi mới liên tục."},{"en":"Education is widely seen as a path to economic success.","vi":"Giáo dục được xem rộng rãi là con đường dẫn đến thành công kinh tế."},{"en":"The country''s economic success attracted skilled migrants.","vi":"Thành công kinh tế của đất nước thu hút lao động lành nghề."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk səkˈses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3910,'colloc-5-01',20,'economic system','hệ thống kinh tế','adj + n','[{"en":"A market economic system relies on supply and demand.","vi":"Một hệ thống kinh tế thị trường dựa vào cung và cầu."},{"en":"The reforms gradually changed the entire economic system.","vi":"Các cải cách dần dần thay đổi toàn bộ hệ thống kinh tế."},{"en":"Every economic system distributes resources in its own way.","vi":"Mỗi hệ thống kinh tế phân phối nguồn lực theo cách riêng."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3911,'colloc-5-01',21,'economic theory','lý thuyết kinh tế','adj + n','[{"en":"The professor explained the economic theory behind inflation.","vi":"Giáo sư giải thích lý thuyết kinh tế đằng sau lạm phát."},{"en":"Classical economic theory assumes that people act rationally.","vi":"Lý thuyết kinh tế cổ điển giả định rằng con người hành động một cách lý trí."},{"en":"Real markets rarely behave as economic theory predicts.","vi":"Thị trường thực hiếm khi diễn ra như lý thuyết kinh tế dự đoán."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈθiːəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3912,'colloc-5-01',22,'economic value','giá trị kinh tế','adj + n','[{"en":"Forests have ecological as well as economic value.","vi":"Rừng có giá trị sinh thái cũng như giá trị kinh tế."},{"en":"The study estimated the economic value of clean air.","vi":"Nghiên cứu ước tính giá trị kinh tế của không khí sạch."},{"en":"Skilled labor adds significant economic value to products.","vi":"Lao động lành nghề tạo thêm giá trị kinh tế đáng kể cho sản phẩm."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3913,'colloc-5-01',23,'economic welfare','phúc lợi kinh tế','adj + n','[{"en":"The policy aims to improve the economic welfare of citizens.","vi":"Chính sách nhằm cải thiện phúc lợi kinh tế của người dân."},{"en":"Free trade can raise the economic welfare of a nation.","vi":"Thương mại tự do có thể nâng cao phúc lợi kinh tế của một quốc gia."},{"en":"Economists debate how best to measure economic welfare.","vi":"Các nhà kinh tế tranh luận về cách đo lường phúc lợi kinh tế tốt nhất."}]','[]',NULL,'/ˌiːkəˈnɑːmɪk ˈwelfer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3914,'colloc-5-01',24,'educational institution','cơ sở giáo dục','adj + n','[{"en":"Every educational institution must meet basic safety standards.","vi":"Mọi cơ sở giáo dục đều phải đáp ứng các tiêu chuẩn an toàn cơ bản."},{"en":"The university is the city''s oldest educational institution.","vi":"Trường đại học là cơ sở giáo dục lâu đời nhất của thành phố."},{"en":"Funding for educational institutions was cut last year.","vi":"Ngân sách cho các cơ sở giáo dục bị cắt giảm năm ngoái."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˌɪnstɪˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3915,'colloc-5-01',25,'educational opportunity','cơ hội giáo dục','adj + n','[{"en":"Scholarships give poorer students better educational opportunity.","vi":"Học bổng mang lại cho học sinh nghèo cơ hội giáo dục tốt hơn."},{"en":"The program expands educational opportunity in rural areas.","vi":"Chương trình mở rộng cơ hội giáo dục ở các vùng nông thôn."},{"en":"Equal educational opportunity remains a central policy goal.","vi":"Cơ hội giáo dục bình đẳng vẫn là một mục tiêu chính sách trọng tâm."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3916,'colloc-5-01',26,'educational policy','chính sách giáo dục','adj + n','[{"en":"A new educational policy raised the school leaving age.","vi":"Một chính sách giáo dục mới đã nâng độ tuổi rời trường."},{"en":"Educational policy should respond to changing labor markets.","vi":"Chính sách giáo dục nên thích ứng với thị trường lao động đang thay đổi."},{"en":"Researchers evaluated the impact of recent educational policy.","vi":"Các nhà nghiên cứu đánh giá tác động của chính sách giáo dục gần đây."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3917,'colloc-5-01',27,'educational program','chương trình giáo dục','adj + n','[{"en":"The charity runs an educational program for young refugees.","vi":"Tổ chức từ thiện điều hành một chương trình giáo dục cho người tị nạn trẻ."},{"en":"An effective educational program needs trained, motivated teachers.","vi":"Một chương trình giáo dục hiệu quả cần giáo viên được đào tạo và đầy nhiệt huyết."},{"en":"The educational program improved students'' reading scores.","vi":"Chương trình giáo dục đã cải thiện điểm đọc của học sinh."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˈproʊɡræm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3918,'colloc-5-01',28,'educational provision','việc cung cấp giáo dục','adj + n','[{"en":"Educational provision in remote regions is often inadequate.","vi":"Việc cung cấp giáo dục ở các vùng xa thường không đầy đủ."},{"en":"The council improved educational provision for disabled children.","vi":"Hội đồng cải thiện việc cung cấp giáo dục cho trẻ em khuyết tật."},{"en":"Funding gaps led to uneven educational provision nationwide.","vi":"Thiếu hụt ngân sách dẫn đến việc cung cấp giáo dục không đồng đều trên cả nước."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl prəˈvɪʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3919,'colloc-5-01',29,'educational qualification','bằng cấp giáo dục','adj + n','[{"en":"Many jobs now require a higher educational qualification.","vi":"Nhiều công việc hiện đòi hỏi bằng cấp giáo dục cao hơn."},{"en":"Her educational qualifications opened doors to better careers.","vi":"Bằng cấp giáo dục của cô mở ra cánh cửa cho những nghề nghiệp tốt hơn."},{"en":"Employers verify each applicant''s educational qualifications carefully.","vi":"Nhà tuyển dụng kiểm tra cẩn thận bằng cấp giáo dục của từng ứng viên."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˌkwɑːlɪfɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3920,'colloc-5-01',30,'educational research','nghiên cứu giáo dục','adj + n','[{"en":"Educational research informs how teachers design their lessons.","vi":"Nghiên cứu giáo dục định hướng cách giáo viên thiết kế bài giảng."},{"en":"She published widely in the field of educational research.","vi":"Bà đã công bố nhiều bài trong lĩnh vực nghiên cứu giáo dục."},{"en":"Recent educational research questions traditional grading methods.","vi":"Nghiên cứu giáo dục gần đây đặt câu hỏi về phương pháp chấm điểm truyền thống."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3921,'colloc-5-01',31,'educational setting','môi trường giáo dục','adj + n','[{"en":"The method works well in any educational setting.","vi":"Phương pháp này hoạt động tốt trong bất kỳ môi trường giáo dục nào."},{"en":"Children behave differently across various educational settings.","vi":"Trẻ em cư xử khác nhau trong các môi trường giáo dục khác nhau."},{"en":"Technology is now common in most educational settings.","vi":"Công nghệ hiện phổ biến trong hầu hết các môi trường giáo dục."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˈsetɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3922,'colloc-5-01',32,'educational system','hệ thống giáo dục','adj + n','[{"en":"The country''s educational system ranks among the best globally.","vi":"Hệ thống giáo dục của đất nước thuộc hàng tốt nhất thế giới."},{"en":"Reforming an entire educational system takes many years.","vi":"Cải cách toàn bộ một hệ thống giáo dục mất nhiều năm."},{"en":"The educational system struggles to fund rural schools.","vi":"Hệ thống giáo dục chật vật trong việc tài trợ cho trường học nông thôn."}]','[]',NULL,'/ˌedʒuˈkeɪʃənəl ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3923,'colloc-5-01',33,'effective communication','giao tiếp hiệu quả','adj + n','[{"en":"Effective communication is essential for successful teamwork.","vi":"Giao tiếp hiệu quả là điều thiết yếu cho làm việc nhóm thành công."},{"en":"The course teaches students effective communication skills.","vi":"Khóa học dạy sinh viên các kỹ năng giao tiếp hiệu quả."},{"en":"Misunderstandings arise when effective communication breaks down.","vi":"Hiểu lầm nảy sinh khi giao tiếp hiệu quả bị đổ vỡ."}]','[]',NULL,'/ɪˈfektɪv kəˌmjuːnɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3924,'colloc-5-01',34,'effective implementation','việc triển khai hiệu quả','adj + n','[{"en":"Effective implementation of the plan requires steady funding.","vi":"Việc triển khai hiệu quả kế hoạch đòi hỏi nguồn ngân sách ổn định."},{"en":"Good policy fails without effective implementation on the ground.","vi":"Chính sách tốt sẽ thất bại nếu không có việc triển khai hiệu quả trên thực tế."},{"en":"Training staff is key to effective implementation.","vi":"Đào tạo nhân viên là chìa khóa cho việc triển khai hiệu quả."}]','[]',NULL,'/ɪˈfektɪv ˌɪmplɪmenˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3925,'colloc-5-01',35,'effective intervention','biện pháp can thiệp hiệu quả','adj + n','[{"en":"Early support proved an effective intervention for struggling readers.","vi":"Hỗ trợ sớm tỏ ra là một biện pháp can thiệp hiệu quả cho học sinh đọc kém."},{"en":"The trial tested an effective intervention against childhood obesity.","vi":"Thử nghiệm kiểm tra một biện pháp can thiệp hiệu quả chống béo phì ở trẻ em."},{"en":"An effective intervention can prevent the disease from spreading.","vi":"Một biện pháp can thiệp hiệu quả có thể ngăn bệnh lây lan."}]','[]',NULL,'/ɪˈfektɪv ˌɪntərˈvenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3926,'colloc-5-01',36,'effective management','sự quản lý hiệu quả','adj + n','[{"en":"Effective management of resources reduced the project''s costs.","vi":"Sự quản lý hiệu quả các nguồn lực đã giảm chi phí dự án."},{"en":"The hospital is praised for its effective management.","vi":"Bệnh viện được khen ngợi vì sự quản lý hiệu quả."},{"en":"Effective management requires clear communication and planning.","vi":"Sự quản lý hiệu quả đòi hỏi giao tiếp và lập kế hoạch rõ ràng."}]','[]',NULL,'/ɪˈfektɪv ˈmænɪdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3927,'colloc-5-01',37,'effective method','phương pháp hiệu quả','adj + n','[{"en":"Repetition is an effective method for learning vocabulary.","vi":"Lặp lại là một phương pháp hiệu quả để học từ vựng."},{"en":"The study identified the most effective method of teaching reading.","vi":"Nghiên cứu xác định phương pháp hiệu quả nhất để dạy đọc."},{"en":"Vaccination remains an effective method of disease prevention.","vi":"Tiêm chủng vẫn là một phương pháp hiệu quả để phòng bệnh."}]','[]',NULL,'/ɪˈfektɪv ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3928,'colloc-5-01',38,'effective participation','sự tham gia hiệu quả','adj + n','[{"en":"Effective participation in meetings requires careful preparation.","vi":"Sự tham gia hiệu quả vào các cuộc họp đòi hỏi sự chuẩn bị kỹ lưỡng."},{"en":"The system encourages effective participation by all citizens.","vi":"Hệ thống khuyến khích sự tham gia hiệu quả của mọi công dân."},{"en":"Language barriers can limit effective participation in class.","vi":"Rào cản ngôn ngữ có thể hạn chế sự tham gia hiệu quả trong lớp."}]','[]',NULL,'/ɪˈfektɪv pɑːrˌtɪsɪˈpeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3929,'colloc-5-01',39,'effective policy','chính sách hiệu quả','adj + n','[{"en":"An effective policy needs both funding and public support.","vi":"Một chính sách hiệu quả cần cả ngân sách lẫn sự ủng hộ của công chúng."},{"en":"The government introduced an effective policy to cut emissions.","vi":"Chính phủ đưa ra một chính sách hiệu quả để cắt giảm khí thải."},{"en":"Effective policy depends on accurate, up-to-date data.","vi":"Chính sách hiệu quả phụ thuộc vào dữ liệu chính xác và cập nhật."}]','[]',NULL,'/ɪˈfektɪv ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3930,'colloc-5-01',40,'effective treatment','phương pháp điều trị hiệu quả','adj + n','[{"en":"Doctors are searching for an effective treatment for the virus.","vi":"Các bác sĩ đang tìm kiếm một phương pháp điều trị hiệu quả cho loại virus này."},{"en":"Early diagnosis allows more effective treatment of cancer.","vi":"Chẩn đoán sớm cho phép điều trị ung thư hiệu quả hơn."},{"en":"The new drug offers an effective treatment with few side effects.","vi":"Loại thuốc mới mang lại phương pháp điều trị hiệu quả với ít tác dụng phụ."}]','[]',NULL,'/ɪˈfektɪv ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3931,'colloc-5-01',41,'electronic access','truy cập điện tử','adj + n','[{"en":"The library provides electronic access to thousands of journals.","vi":"Thư viện cung cấp truy cập điện tử đến hàng nghìn tạp chí."},{"en":"Students gain electronic access to course materials online.","vi":"Sinh viên có truy cập điện tử đến tài liệu khóa học trực tuyến."},{"en":"Electronic access lets researchers work from anywhere.","vi":"Truy cập điện tử cho phép nhà nghiên cứu làm việc từ bất cứ đâu."}]','[]',NULL,'/ɪˌlekˈtrɑːnɪk ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3932,'colloc-5-01',42,'electronic communication','giao tiếp điện tử','adj + n','[{"en":"Electronic communication has largely replaced traditional letters.","vi":"Giao tiếp điện tử đã phần lớn thay thế thư từ truyền thống."},{"en":"The company relies on electronic communication between offices.","vi":"Công ty dựa vào giao tiếp điện tử giữa các văn phòng."},{"en":"Electronic communication allows instant contact across continents.","vi":"Giao tiếp điện tử cho phép liên lạc tức thời giữa các châu lục."}]','[]',NULL,'/ɪˌlekˈtrɑːnɪk kəˌmjuːnɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3933,'colloc-5-01',43,'electronic media','phương tiện truyền thông điện tử','adj + n','[{"en":"Young people get most of their news from electronic media.","vi":"Người trẻ tiếp nhận hầu hết tin tức từ phương tiện truyền thông điện tử."},{"en":"Electronic media now shape public opinion more than newspapers.","vi":"Phương tiện truyền thông điện tử định hình dư luận nhiều hơn báo giấy."},{"en":"The study examines advertising in electronic media.","vi":"Nghiên cứu xem xét quảng cáo trên phương tiện truyền thông điện tử."}]','[]',NULL,'/ɪˌlekˈtrɑːnɪk ˈmiːdiə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3934,'colloc-5-01',44,'electronic resources','tài nguyên điện tử','adj + n','[{"en":"The university invests heavily in electronic resources each year.","vi":"Trường đại học đầu tư mạnh vào tài nguyên điện tử mỗi năm."},{"en":"Electronic resources make rare documents widely available.","vi":"Tài nguyên điện tử giúp các tài liệu hiếm có sẵn rộng rãi."},{"en":"Teachers integrate electronic resources into their lessons.","vi":"Giáo viên tích hợp tài nguyên điện tử vào bài giảng."}]','[]',NULL,'/ɪˌlekˈtrɑːnɪk ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3935,'colloc-5-01',45,'electronic version','phiên bản điện tử','adj + n','[{"en":"An electronic version of the book is available online.","vi":"Một phiên bản điện tử của cuốn sách có sẵn trực tuyến."},{"en":"The electronic version includes searchable footnotes and links.","vi":"Phiên bản điện tử bao gồm chú thích và liên kết có thể tìm kiếm."},{"en":"Readers can download the electronic version for free.","vi":"Độc giả có thể tải phiên bản điện tử miễn phí."}]','[]',NULL,'/ɪˌlekˈtrɑːnɪk ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3936,'colloc-5-01',46,'emotional impact','tác động cảm xúc','adj + n','[{"en":"The film had a powerful emotional impact on viewers.","vi":"Bộ phim có tác động cảm xúc mạnh mẽ đến người xem."},{"en":"Researchers studied the emotional impact of long-term illness.","vi":"Các nhà nghiên cứu nghiên cứu tác động cảm xúc của bệnh kéo dài."},{"en":"Losing a job can have a lasting emotional impact.","vi":"Mất việc có thể để lại tác động cảm xúc lâu dài."}]','[]',NULL,'/ɪˈmoʊʃənəl ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3937,'colloc-5-01',47,'emotional intelligence','trí tuệ cảm xúc','adj + n','[{"en":"Good leaders often show high emotional intelligence.","vi":"Những nhà lãnh đạo giỏi thường thể hiện trí tuệ cảm xúc cao."},{"en":"Emotional intelligence helps people manage stress at work.","vi":"Trí tuệ cảm xúc giúp con người kiểm soát căng thẳng trong công việc."},{"en":"Schools increasingly teach emotional intelligence to young children.","vi":"Các trường ngày càng dạy trí tuệ cảm xúc cho trẻ nhỏ."}]','[]',NULL,'/ɪˈmoʊʃənəl ɪnˈtelɪdʒəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3938,'colloc-5-01',48,'emotional reaction','phản ứng cảm xúc','adj + n','[{"en":"The news provoked a strong emotional reaction from the public.","vi":"Tin tức gây ra phản ứng cảm xúc mạnh mẽ từ công chúng."},{"en":"Her emotional reaction surprised everyone in the room.","vi":"Phản ứng cảm xúc của cô khiến mọi người trong phòng bất ngờ."},{"en":"The experiment measured each participant''s emotional reaction.","vi":"Thí nghiệm đo lường phản ứng cảm xúc của từng người tham gia."}]','[]',NULL,'/ɪˈmoʊʃənəl riˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3939,'colloc-5-01',49,'emotional response','phản hồi cảm xúc','adj + n','[{"en":"Music can trigger a deep emotional response in listeners.","vi":"Âm nhạc có thể khơi gợi phản hồi cảm xúc sâu sắc nơi người nghe."},{"en":"Advertisers try to create a positive emotional response.","vi":"Các nhà quảng cáo cố gắng tạo ra phản hồi cảm xúc tích cực."},{"en":"The study recorded children''s emotional responses to images.","vi":"Nghiên cứu ghi lại phản hồi cảm xúc của trẻ em với hình ảnh."}]','[]',NULL,'/ɪˈmoʊʃənəl rɪˈspɑːns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3940,'colloc-5-01',50,'emotional support','hỗ trợ tinh thần','adj + n','[{"en":"Friends provided valuable emotional support during her illness.","vi":"Bạn bè đã mang lại sự hỗ trợ tinh thần quý giá trong lúc cô bị bệnh."},{"en":"The group offers emotional support to grieving families.","vi":"Nhóm cung cấp hỗ trợ tinh thần cho những gia đình đang đau buồn."},{"en":"Children need emotional support as well as material care.","vi":"Trẻ em cần hỗ trợ tinh thần cũng như sự chăm sóc vật chất."}]','[]',NULL,'/ɪˈmoʊʃənəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3941,'colloc-5-01',51,'empirical data','dữ liệu thực nghiệm','adj + n','[{"en":"The theory is now supported by solid empirical data.","vi":"Lý thuyết hiện được hỗ trợ bởi dữ liệu thực nghiệm vững chắc."},{"en":"They collected empirical data from over a thousand patients.","vi":"Họ thu thập dữ liệu thực nghiệm từ hơn một nghìn bệnh nhân."},{"en":"Without empirical data, the claim remains mere speculation.","vi":"Nếu không có dữ liệu thực nghiệm, lập luận chỉ là phỏng đoán."}]','[]',NULL,'/ɪmˈpɪrɪkəl ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3942,'colloc-5-01',52,'empirical evidence','bằng chứng thực nghiệm','adj + n','[{"en":"There is strong empirical evidence linking smoking to cancer.","vi":"Có bằng chứng thực nghiệm mạnh mẽ liên hệ hút thuốc với ung thư."},{"en":"The hypothesis lacks sufficient empirical evidence to be accepted.","vi":"Giả thuyết thiếu bằng chứng thực nghiệm đầy đủ để được chấp nhận."},{"en":"Empirical evidence should guide policy decisions.","vi":"Bằng chứng thực nghiệm nên định hướng các quyết định chính sách."}]','[]',NULL,'/ɪmˈpɪrɪkəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3943,'colloc-5-01',53,'empirical investigation','cuộc điều tra thực nghiệm','adj + n','[{"en":"The claim deserves a careful empirical investigation.","vi":"Lập luận này xứng đáng được điều tra thực nghiệm cẩn thận."},{"en":"Their empirical investigation involved years of fieldwork.","vi":"Cuộc điều tra thực nghiệm của họ kéo dài nhiều năm thực địa."},{"en":"An empirical investigation tested the model against real cases.","vi":"Một cuộc điều tra thực nghiệm đã kiểm chứng mô hình với các trường hợp thực."}]','[]',NULL,'/ɪmˈpɪrɪkəl ɪnˌvestɪˈɡeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3944,'colloc-5-01',54,'empirical research','nghiên cứu thực nghiệm','adj + n','[{"en":"Empirical research is based on observation and experiment.","vi":"Nghiên cứu thực nghiệm dựa trên quan sát và thí nghiệm."},{"en":"Little empirical research exists on this specific question.","vi":"Có rất ít nghiên cứu thực nghiệm về câu hỏi cụ thể này."},{"en":"The journal publishes only rigorous empirical research.","vi":"Tạp chí chỉ công bố các nghiên cứu thực nghiệm chặt chẽ."}]','[]',NULL,'/ɪmˈpɪrɪkəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3945,'colloc-5-01',55,'empirical study','nghiên cứu thực nghiệm','adj + n','[{"en":"The empirical study surveyed five hundred small businesses.","vi":"Nghiên cứu thực nghiệm khảo sát năm trăm doanh nghiệp nhỏ."},{"en":"An empirical study confirmed the predicted relationship.","vi":"Một nghiên cứu thực nghiệm đã xác nhận mối quan hệ được dự đoán."},{"en":"Few empirical studies have tested this assumption directly.","vi":"Rất ít nghiên cứu thực nghiệm đã kiểm chứng giả định này một cách trực tiếp."}]','[]',NULL,'/ɪmˈpɪrɪkəl ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3946,'colloc-5-01',56,'empirical support','sự ủng hộ thực nghiệm','adj + n','[{"en":"The model has gained growing empirical support over time.","vi":"Mô hình ngày càng nhận được sự ủng hộ thực nghiệm theo thời gian."},{"en":"There is little empirical support for that bold claim.","vi":"Có rất ít sự ủng hộ thực nghiệm cho lập luận táo bạo đó."},{"en":"Recent experiments provide strong empirical support for the theory.","vi":"Các thí nghiệm gần đây cung cấp sự ủng hộ thực nghiệm mạnh mẽ cho lý thuyết."}]','[]',NULL,'/ɪmˈpɪrɪkəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3947,'colloc-5-01',57,'empirical work','công trình thực nghiệm','adj + n','[{"en":"Her empirical work focused on classroom behavior.","vi":"Công trình thực nghiệm của bà tập trung vào hành vi trong lớp học."},{"en":"The chapter reviews recent empirical work in the field.","vi":"Chương này điểm lại các công trình thực nghiệm gần đây trong lĩnh vực."},{"en":"More empirical work is needed to settle the debate.","vi":"Cần thêm các công trình thực nghiệm để giải quyết cuộc tranh luận."}]','[]',NULL,'/ɪmˈpɪrɪkəl wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3948,'colloc-5-01',58,'employ a method','sử dụng một phương pháp','v + n','[{"en":"The researchers employ a method that combines surveys and interviews.","vi":"Các nhà nghiên cứu sử dụng một phương pháp kết hợp khảo sát và phỏng vấn."},{"en":"We employ a method designed to reduce measurement error.","vi":"Chúng tôi sử dụng một phương pháp được thiết kế để giảm sai số đo lường."},{"en":"Scientists often employ a method tested in earlier studies.","vi":"Các nhà khoa học thường sử dụng một phương pháp đã được kiểm chứng trong các nghiên cứu trước."}]','[]',NULL,'/ɪmˈplɔɪ ə ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3949,'colloc-5-01',59,'employ a technique','sử dụng một kỹ thuật','v + n','[{"en":"Surgeons employ a technique that minimizes blood loss.","vi":"Các bác sĩ phẫu thuật sử dụng một kỹ thuật giảm thiểu mất máu."},{"en":"The artist employs a technique borrowed from traditional painting.","vi":"Người nghệ sĩ sử dụng một kỹ thuật vay mượn từ hội họa truyền thống."},{"en":"We employ a technique to test the sample for purity.","vi":"Chúng tôi sử dụng một kỹ thuật để kiểm tra độ tinh khiết của mẫu."}]','[]',NULL,'/ɪmˈplɔɪ ə tekˈniːk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3950,'colloc-5-01',60,'employment opportunities','cơ hội việc làm','n + n','[{"en":"The new factory created many employment opportunities locally.","vi":"Nhà máy mới tạo ra nhiều cơ hội việc làm tại địa phương."},{"en":"Better education expands employment opportunities for young people.","vi":"Giáo dục tốt hơn mở rộng cơ hội việc làm cho người trẻ."},{"en":"Rural areas often offer fewer employment opportunities.","vi":"Các vùng nông thôn thường có ít cơ hội việc làm hơn."}]','[]',NULL,'/ɪmˈplɔɪmənt ˌɑːpərˈtuːnətiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3951,'colloc-5-01',61,'encounter difficulties','gặp phải khó khăn','v + n','[{"en":"New students often encounter difficulties adjusting to university life.","vi":"Sinh viên mới thường gặp phải khó khăn khi thích nghi với đời sống đại học."},{"en":"The team encountered difficulties when collecting the data.","vi":"Nhóm gặp phải khó khăn khi thu thập dữ liệu."},{"en":"Migrants frequently encounter difficulties finding stable housing.","vi":"Người di cư thường gặp phải khó khăn trong việc tìm chỗ ở ổn định."}]','[]',NULL,'/ɪnˈkaʊntər ˈdɪfɪkəltiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3952,'colloc-5-01',62,'encounter problems','gặp phải vấn đề','v + n','[{"en":"Engineers encountered problems during the bridge''s construction.","vi":"Các kỹ sư gặp phải vấn đề trong quá trình xây dựng cây cầu."},{"en":"If you encounter problems, contact technical support immediately.","vi":"Nếu bạn gặp phải vấn đề, hãy liên hệ bộ phận hỗ trợ kỹ thuật ngay."},{"en":"Researchers may encounter problems with unreliable equipment.","vi":"Các nhà nghiên cứu có thể gặp phải vấn đề với thiết bị không đáng tin cậy."}]','[]',NULL,'/ɪnˈkaʊntər ˈprɑːbləmz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3953,'colloc-5-01',63,'encourage the development of','thúc đẩy sự phát triển của','v + n','[{"en":"The program aims to encourage the development of critical thinking.","vi":"Chương trình nhằm thúc đẩy sự phát triển của tư duy phản biện."},{"en":"Grants encourage the development of renewable energy technologies.","vi":"Các khoản tài trợ thúc đẩy sự phát triển của công nghệ năng lượng tái tạo."},{"en":"Good teaching can encourage the development of independent learners.","vi":"Dạy tốt có thể thúc đẩy sự phát triển của những người học tự lập."}]','[]',NULL,'/ɪnˈkɜːrɪdʒ ðə dɪˈveləpmənt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3954,'colloc-5-01',64,'engage in an activity','tham gia vào một hoạt động','v + n','[{"en":"Students who engage in an activity tend to remember it better.","vi":"Học sinh tham gia vào một hoạt động thường nhớ nó lâu hơn."},{"en":"We encourage children to engage in an activity that builds confidence.","vi":"Chúng tôi khuyến khích trẻ tham gia một hoạt động giúp xây dựng sự tự tin."},{"en":"Volunteers may engage in an activity outside their usual job duties.","vi":"Tình nguyện viên có thể tham gia một hoạt động ngoài nhiệm vụ thường ngày."}]','[]',NULL,'/ɪnˈɡeɪdʒ ɪn ən ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3955,'colloc-5-01',65,'enhance learning','nâng cao việc học','v + n','[{"en":"Interactive games can enhance learning for young children significantly.","vi":"Trò chơi tương tác có thể nâng cao việc học cho trẻ nhỏ đáng kể."},{"en":"Teachers use technology to enhance learning across all subjects.","vi":"Giáo viên dùng công nghệ để nâng cao việc học ở mọi môn."},{"en":"Regular feedback helps enhance learning and keeps students motivated.","vi":"Phản hồi thường xuyên giúp nâng cao việc học và duy trì động lực."}]','[]',NULL,'/ɪnˈhæns ˈlɜːrnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3956,'colloc-5-01',66,'enhance performance','cải thiện hiệu suất','v + n','[{"en":"Proper training can enhance performance in nearly every sport.","vi":"Tập luyện đúng cách có thể cải thiện hiệu suất ở hầu hết các môn thể thao."},{"en":"The new software was designed to enhance performance under heavy load.","vi":"Phần mềm mới được thiết kế để cải thiện hiệu suất khi tải nặng."},{"en":"Good sleep is known to enhance performance and concentration.","vi":"Ngủ đủ giấc được biết là giúp cải thiện hiệu suất và sự tập trung."}]','[]',NULL,'/ɪnˈhæns pərˈfɔːrməns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3957,'colloc-5-01',67,'enormous amount of','một lượng khổng lồ','adj + n','[{"en":"The project required an enormous amount of time and effort.","vi":"Dự án đòi hỏi một lượng khổng lồ thời gian và công sức."},{"en":"Researchers gathered an enormous amount of data over five years.","vi":"Các nhà nghiên cứu thu thập một lượng dữ liệu khổng lồ trong năm năm."},{"en":"An enormous amount of money was spent on the new stadium.","vi":"Một lượng tiền khổng lồ đã được chi cho sân vận động mới."}]','[]',NULL,'/ɪˈnɔːrməs əˈmaʊnt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3958,'colloc-5-01',68,'enormous impact','tác động to lớn','adj + n','[{"en":"The invention of the internet had an enormous impact on society.","vi":"Sự ra đời của internet đã có tác động to lớn lên xã hội."},{"en":"Her research made an enormous impact on modern medicine.","vi":"Nghiên cứu của cô đã tạo ra tác động to lớn lên y học hiện đại."},{"en":"Climate change is having an enormous impact on coastal cities.","vi":"Biến đổi khí hậu đang gây tác động to lớn lên các thành phố ven biển."}]','[]',NULL,'/ɪˈnɔːrməs ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3959,'colloc-5-01',69,'entire period','toàn bộ thời kỳ','adj + n','[{"en":"She studied abroad for the entire period of her degree.","vi":"Cô học ở nước ngoài suốt toàn bộ thời kỳ học vị của mình."},{"en":"Sales remained steady throughout the entire period of the year.","vi":"Doanh số ổn định suốt toàn bộ thời kỳ trong năm."},{"en":"The museum documents the entire period of the city''s growth.","vi":"Bảo tàng ghi lại toàn bộ thời kỳ phát triển của thành phố."}]','[]',NULL,'/ɪnˈtaɪər ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3960,'colloc-5-01',70,'entire range of','toàn bộ phạm vi','adj + n','[{"en":"The store offers the entire range of products from the brand.","vi":"Cửa hàng cung cấp toàn bộ phạm vi sản phẩm của thương hiệu."},{"en":"Her essay covered the entire range of arguments on the topic.","vi":"Bài luận của cô bao quát toàn bộ phạm vi lập luận về chủ đề này."},{"en":"The course explores the entire range of human emotions.","vi":"Khóa học khám phá toàn bộ phạm vi cảm xúc của con người."}]','[]',NULL,'/ɪnˈtaɪər reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3961,'colloc-5-01',71,'entirely clear','hoàn toàn rõ ràng','adv + adj','[{"en":"It is not entirely clear why the experiment failed.","vi":"Vẫn chưa hoàn toàn rõ ràng tại sao thí nghiệm thất bại."},{"en":"The instructions were not entirely clear to the new students.","vi":"Hướng dẫn không hoàn toàn rõ ràng với các học sinh mới."},{"en":"Her reasons for leaving were never entirely clear to us.","vi":"Lý do cô ra đi chưa bao giờ hoàn toàn rõ ràng với chúng tôi."}]','[]',NULL,'/ɪnˈtaɪərli klɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3962,'colloc-5-01',72,'entirely different','hoàn toàn khác biệt','adv + adj','[{"en":"The two theories lead to entirely different conclusions.","vi":"Hai lý thuyết dẫn đến những kết luận hoàn toàn khác biệt."},{"en":"Life in the countryside is entirely different from the city.","vi":"Cuộc sống ở nông thôn hoàn toàn khác biệt với thành phố."},{"en":"After the trip, she returned with an entirely different outlook.","vi":"Sau chuyến đi, cô trở về với một cái nhìn hoàn toàn khác biệt."}]','[]',NULL,'/ɪnˈtaɪərli ˈdɪfrənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3963,'colloc-5-01',73,'entirely new','hoàn toàn mới','adv + adj','[{"en":"The discovery opened up an entirely new field of study.","vi":"Phát hiện này mở ra một lĩnh vực nghiên cứu hoàn toàn mới."},{"en":"We need an entirely new approach to solve this problem.","vi":"Chúng ta cần một cách tiếp cận hoàn toàn mới để giải quyết vấn đề này."},{"en":"The company launched an entirely new line of products.","vi":"Công ty ra mắt một dòng sản phẩm hoàn toàn mới."}]','[]',NULL,'/ɪnˈtaɪərli nuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3964,'colloc-5-01',74,'environmental changes','những thay đổi môi trường','adj + n','[{"en":"Scientists study how species adapt to environmental changes.","vi":"Các nhà khoa học nghiên cứu cách loài thích nghi với những thay đổi môi trường."},{"en":"Environmental changes over decades have altered local farming.","vi":"Những thay đổi môi trường qua nhiều thập kỷ đã làm thay đổi nông nghiệp địa phương."},{"en":"The report tracks environmental changes in the Arctic region.","vi":"Báo cáo theo dõi những thay đổi môi trường ở vùng Bắc Cực."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˈtʃeɪndʒɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3965,'colloc-5-01',75,'environmental concern','mối quan ngại về môi trường','adj + n','[{"en":"Pollution from factories is a major environmental concern today.","vi":"Ô nhiễm từ nhà máy là một mối quan ngại lớn về môi trường ngày nay."},{"en":"Plastic waste has become a serious environmental concern worldwide.","vi":"Rác thải nhựa đã trở thành mối quan ngại nghiêm trọng về môi trường toàn cầu."},{"en":"The new policy addresses growing environmental concern among citizens.","vi":"Chính sách mới giải quyết mối quan ngại môi trường ngày càng tăng của người dân."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl kənˈsɜːrn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3966,'colloc-5-01',76,'environmental consequences','hậu quả về môi trường','adj + n','[{"en":"Mining can have severe environmental consequences for nearby rivers.","vi":"Khai thác mỏ có thể gây hậu quả môi trường nghiêm trọng cho các con sông gần đó."},{"en":"The study examines the environmental consequences of deforestation.","vi":"Nghiên cứu xem xét hậu quả về môi trường của nạn phá rừng."},{"en":"Few people considered the environmental consequences of the dam.","vi":"Ít người cân nhắc đến hậu quả môi trường của con đập."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˈkɑːnsəkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3967,'colloc-5-01',77,'environmental damage','thiệt hại về môi trường','adj + n','[{"en":"The oil spill caused widespread environmental damage along the coast.","vi":"Vụ tràn dầu gây thiệt hại môi trường trên diện rộng dọc bờ biển."},{"en":"Stricter laws aim to reduce environmental damage from industry.","vi":"Luật nghiêm ngặt hơn nhằm giảm thiệt hại môi trường từ công nghiệp."},{"en":"Reversing environmental damage can take many decades.","vi":"Khắc phục thiệt hại môi trường có thể mất nhiều thập kỷ."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˈdæmɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3968,'colloc-5-01',78,'environmental degradation','sự suy thoái môi trường','adj + n','[{"en":"Rapid urban growth often leads to environmental degradation.","vi":"Đô thị hóa nhanh thường dẫn đến sự suy thoái môi trường."},{"en":"The article links poverty with environmental degradation in rural areas.","vi":"Bài viết liên hệ đói nghèo với sự suy thoái môi trường ở vùng nông thôn."},{"en":"Conservation programs try to slow environmental degradation.","vi":"Các chương trình bảo tồn cố gắng làm chậm sự suy thoái môi trường."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˌdeɡrəˈdeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3969,'colloc-5-01',79,'environmental effects','các tác động môi trường','adj + n','[{"en":"The committee assessed the environmental effects of the highway.","vi":"Ủy ban đánh giá các tác động môi trường của con đường cao tốc."},{"en":"Researchers measured the environmental effects of the chemical.","vi":"Các nhà nghiên cứu đo lường các tác động môi trường của hóa chất."},{"en":"We must understand the environmental effects before building begins.","vi":"Chúng ta phải hiểu các tác động môi trường trước khi khởi công."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ɪˈfekts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3970,'colloc-5-01',80,'environmental factors','các yếu tố môi trường','adj + n','[{"en":"Environmental factors can influence a child''s development greatly.","vi":"Các yếu tố môi trường có thể ảnh hưởng lớn đến sự phát triển của trẻ."},{"en":"The study controlled for environmental factors such as temperature.","vi":"Nghiên cứu kiểm soát các yếu tố môi trường như nhiệt độ."},{"en":"Both genetic and environmental factors shape human behavior.","vi":"Cả yếu tố di truyền và môi trường đều định hình hành vi con người."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3971,'colloc-5-01',81,'environmental impact','tác động môi trường','adj + n','[{"en":"Every new factory must submit an environmental impact report.","vi":"Mỗi nhà máy mới phải nộp báo cáo tác động môi trường."},{"en":"Electric cars have a smaller environmental impact than petrol ones.","vi":"Xe điện có tác động môi trường nhỏ hơn xe chạy xăng."},{"en":"The company aims to lower its environmental impact by half.","vi":"Công ty đặt mục tiêu giảm một nửa tác động môi trường của mình."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3972,'colloc-5-01',82,'environmental issues','các vấn đề môi trường','adj + n','[{"en":"Young people are increasingly aware of environmental issues.","vi":"Giới trẻ ngày càng nhận thức rõ về các vấn đề môi trường."},{"en":"The debate focused on environmental issues facing the city.","vi":"Cuộc tranh luận tập trung vào các vấn đề môi trường mà thành phố đối mặt."},{"en":"Schools now include environmental issues in their curriculum.","vi":"Các trường học giờ đưa các vấn đề môi trường vào chương trình giảng dạy."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˈɪʃuːz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3973,'colloc-5-01',83,'environmental policy','chính sách môi trường','adj + n','[{"en":"The government announced a new environmental policy this week.","vi":"Chính phủ công bố một chính sách môi trường mới trong tuần này."},{"en":"A strong environmental policy can protect natural resources.","vi":"Một chính sách môi trường mạnh mẽ có thể bảo vệ tài nguyên thiên nhiên."},{"en":"Critics argued that the environmental policy did not go far enough.","vi":"Những người chỉ trích cho rằng chính sách môi trường chưa đủ mạnh."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3974,'colloc-5-01',84,'environmental pollution','ô nhiễm môi trường','adj + n','[{"en":"Environmental pollution from traffic harms people''s health daily.","vi":"Ô nhiễm môi trường từ giao thông gây hại cho sức khỏe mỗi ngày."},{"en":"The factory was fined for causing environmental pollution.","vi":"Nhà máy bị phạt vì gây ô nhiễm môi trường."},{"en":"Reducing environmental pollution requires cooperation between nations.","vi":"Giảm ô nhiễm môi trường đòi hỏi sự hợp tác giữa các quốc gia."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl pəˈluːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3975,'colloc-5-01',85,'environmental protection','bảo vệ môi trường','adj + n','[{"en":"Environmental protection has become a global priority in recent years.","vi":"Bảo vệ môi trường đã trở thành ưu tiên toàn cầu trong những năm gần đây."},{"en":"The agency is responsible for environmental protection nationwide.","vi":"Cơ quan này chịu trách nhiệm bảo vệ môi trường trên toàn quốc."},{"en":"Many companies now invest heavily in environmental protection.","vi":"Nhiều công ty hiện đầu tư mạnh vào bảo vệ môi trường."}]','[]',NULL,'/ɪnˌvaɪrənˈmentəl prəˈtekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3976,'colloc-5-01',86,'equal access','quyền tiếp cận bình đẳng','adj + n','[{"en":"The policy guarantees equal access to education for all children.","vi":"Chính sách đảm bảo quyền tiếp cận giáo dục bình đẳng cho mọi trẻ em."},{"en":"Everyone should have equal access to clean drinking water.","vi":"Mọi người nên có quyền tiếp cận bình đẳng với nước uống sạch."},{"en":"The library provides equal access to digital resources for students.","vi":"Thư viện cung cấp quyền tiếp cận bình đẳng tới tài nguyên số cho sinh viên."}]','[]',NULL,'/ˈiːkwəl ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3977,'colloc-5-01',87,'equal opportunity','cơ hội bình đẳng','adj + n','[{"en":"The company promotes equal opportunity for all job applicants.","vi":"Công ty đề cao cơ hội bình đẳng cho mọi ứng viên xin việc."},{"en":"Equal opportunity in employment is protected by national law.","vi":"Cơ hội bình đẳng trong việc làm được luật pháp quốc gia bảo vệ."},{"en":"Schools should give every student an equal opportunity to succeed.","vi":"Trường học nên trao cho mỗi học sinh cơ hội bình đẳng để thành công."}]','[]',NULL,'/ˈiːkwəl ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3978,'colloc-5-01',88,'equal status','địa vị bình đẳng','adj + n','[{"en":"The treaty granted both languages equal status in the region.","vi":"Hiệp ước trao cho cả hai ngôn ngữ địa vị bình đẳng trong khu vực."},{"en":"Women fought for years to gain equal status in society.","vi":"Phụ nữ đấu tranh nhiều năm để giành địa vị bình đẳng trong xã hội."},{"en":"Both partners enjoy equal status within the organization.","vi":"Cả hai đối tác có địa vị bình đẳng trong tổ chức."}]','[]',NULL,'/ˈiːkwəl ˈstætəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3979,'colloc-5-01',89,'equal treatment','sự đối xử bình đẳng','adj + n','[{"en":"All employees deserve equal treatment regardless of their background.","vi":"Mọi nhân viên xứng đáng được đối xử bình đẳng bất kể xuất thân."},{"en":"The law demands equal treatment of men and women at work.","vi":"Luật yêu cầu sự đối xử bình đẳng giữa nam và nữ tại nơi làm việc."},{"en":"Patients expect equal treatment from every hospital in the country.","vi":"Bệnh nhân mong đợi sự đối xử bình đẳng từ mọi bệnh viện trong nước."}]','[]',NULL,'/ˈiːkwəl ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3980,'colloc-5-01',90,'equally important','quan trọng như nhau','adv + adj','[{"en":"Both reading and writing skills are equally important for students.","vi":"Cả kỹ năng đọc và viết đều quan trọng như nhau với học sinh."},{"en":"Diet and exercise are equally important for good health.","vi":"Chế độ ăn và tập luyện đều quan trọng như nhau cho sức khỏe tốt."},{"en":"It is equally important to listen as well as to speak.","vi":"Lắng nghe cũng quan trọng như nhau so với việc nói."}]','[]',NULL,'/ˈiːkwəli ɪmˈpɔːrtənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3981,'colloc-5-01',91,'equally likely','có khả năng ngang nhau','adv + adj','[{"en":"Both outcomes are equally likely when the coin is fair.","vi":"Cả hai kết quả đều có khả năng ngang nhau khi đồng xu công bằng."},{"en":"Men and women are equally likely to choose this career.","vi":"Nam và nữ có khả năng ngang nhau khi chọn nghề này."},{"en":"It is equally likely that either team will win the match.","vi":"Khả năng ngang nhau cho việc đội nào cũng có thể thắng trận đấu."}]','[]',NULL,'/ˈiːkwəli ˈlaɪkli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3982,'colloc-5-01',92,'equally true','cũng đúng như vậy','adv + adj','[{"en":"The rule is equally true for beginners and experts alike.","vi":"Quy tắc này cũng đúng như vậy với cả người mới và chuyên gia."},{"en":"What applies to one country is equally true for another.","vi":"Điều áp dụng cho một quốc gia cũng đúng như vậy với quốc gia khác."},{"en":"This statement is equally true in theory and in practice.","vi":"Phát biểu này cũng đúng như vậy cả trên lý thuyết lẫn thực tế."}]','[]',NULL,'/ˈiːkwəli truː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3983,'colloc-5-01',93,'equally valid','có giá trị ngang nhau','adv + adj','[{"en":"Both interpretations of the poem seem equally valid to me.","vi":"Cả hai cách diễn giải bài thơ với tôi đều có giá trị ngang nhau."},{"en":"Her argument is equally valid despite using different evidence.","vi":"Lập luận của cô có giá trị ngang nhau dù dùng bằng chứng khác."},{"en":"These two methods are equally valid for solving the equation.","vi":"Hai phương pháp này có giá trị ngang nhau để giải phương trình."}]','[]',NULL,'/ˈiːkwəli ˈvælɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3984,'colloc-5-01',94,'essential component','thành phần thiết yếu','adj + n','[{"en":"Trust is an essential component of any healthy relationship.","vi":"Lòng tin là thành phần thiết yếu của mọi mối quan hệ lành mạnh."},{"en":"Water is an essential component of every living cell.","vi":"Nước là thành phần thiết yếu của mọi tế bào sống."},{"en":"Practice is an essential component of learning a language.","vi":"Luyện tập là thành phần thiết yếu của việc học một ngôn ngữ."}]','[]',NULL,'/ɪˈsenʃəl kəmˈpoʊnənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3985,'colloc-5-01',95,'essential element','yếu tố thiết yếu','adj + n','[{"en":"Clear communication is an essential element of good teamwork.","vi":"Giao tiếp rõ ràng là yếu tố thiết yếu của làm việc nhóm tốt."},{"en":"Suspense is an essential element of a gripping novel.","vi":"Sự hồi hộp là yếu tố thiết yếu của một cuốn tiểu thuyết hấp dẫn."},{"en":"Sunlight is an essential element for healthy plant growth.","vi":"Ánh nắng là yếu tố thiết yếu cho sự phát triển khỏe mạnh của cây."}]','[]',NULL,'/ɪˈsenʃəl ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3986,'colloc-5-01',96,'essential feature','đặc điểm thiết yếu','adj + n','[{"en":"Flexibility is an essential feature of the new software design.","vi":"Sự linh hoạt là đặc điểm thiết yếu của thiết kế phần mềm mới."},{"en":"Symmetry is an essential feature of many traditional buildings.","vi":"Sự đối xứng là đặc điểm thiết yếu của nhiều tòa nhà truyền thống."},{"en":"Repetition is an essential feature of effective advertising.","vi":"Sự lặp lại là đặc điểm thiết yếu của quảng cáo hiệu quả."}]','[]',NULL,'/ɪˈsenʃəl ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3987,'colloc-5-01',97,'essential function','chức năng thiết yếu','adj + n','[{"en":"The heart performs an essential function in the human body.","vi":"Tim thực hiện một chức năng thiết yếu trong cơ thể con người."},{"en":"Storing memory is an essential function of the brain.","vi":"Lưu trữ ký ức là chức năng thiết yếu của não bộ."},{"en":"Filtering waste is an essential function of the kidneys.","vi":"Lọc chất thải là chức năng thiết yếu của thận."}]','[]',NULL,'/ɪˈsenʃəl ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3988,'colloc-5-01',98,'essential information','thông tin thiết yếu','adj + n','[{"en":"The first page contains all the essential information you need.","vi":"Trang đầu chứa tất cả thông tin thiết yếu bạn cần."},{"en":"Always read the essential information before signing any contract.","vi":"Hãy luôn đọc thông tin thiết yếu trước khi ký bất kỳ hợp đồng nào."},{"en":"The guide highlights essential information for new travelers.","vi":"Cẩm nang nêu bật thông tin thiết yếu cho khách du lịch mới."}]','[]',NULL,'/ɪˈsenʃəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3989,'colloc-5-01',99,'essential role','vai trò thiết yếu','adj + n','[{"en":"Teachers play an essential role in shaping young minds.","vi":"Giáo viên đóng vai trò thiết yếu trong việc định hình tư duy trẻ."},{"en":"Bees serve an essential role in pollinating crops.","vi":"Ong giữ vai trò thiết yếu trong việc thụ phấn cho cây trồng."},{"en":"Sleep has an essential role in maintaining good health.","vi":"Giấc ngủ có vai trò thiết yếu trong việc duy trì sức khỏe tốt."}]','[]',NULL,'/ɪˈsenʃəl roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3990,'colloc-5-01',100,'establish a relationship','thiết lập một mối quan hệ','v + n','[{"en":"Companies work hard to establish a relationship with new clients.","vi":"Các công ty nỗ lực để thiết lập một mối quan hệ với khách hàng mới."},{"en":"It takes time to establish a relationship built on trust.","vi":"Cần thời gian để thiết lập một mối quan hệ dựa trên lòng tin."},{"en":"The two nations sought to establish a relationship after the war.","vi":"Hai quốc gia tìm cách thiết lập một mối quan hệ sau chiến tranh."}]','[]',NULL,'/ɪˈstæblɪʃ ə rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3991,'colloc-5-01',101,'established order','trật tự đã được thiết lập','adj + n','[{"en":"The revolution challenged the established order of the time.","vi":"Cuộc cách mạng thách thức trật tự đã được thiết lập của thời đó."},{"en":"Many feared that the reforms would upset the established order.","vi":"Nhiều người lo rằng cải cách sẽ phá vỡ trật tự đã được thiết lập."},{"en":"New ideas often clash with the established order in society.","vi":"Ý tưởng mới thường xung đột với trật tự đã được thiết lập trong xã hội."}]','[]',NULL,'/ɪˈstæblɪʃt ˈɔːrdər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3992,'colloc-5-01',102,'established practice','thông lệ đã được thiết lập','adj + n','[{"en":"Reviewing the literature first is established practice in research.","vi":"Đọc tài liệu trước là thông lệ đã được thiết lập trong nghiên cứu."},{"en":"It is established practice to back up data every evening.","vi":"Sao lưu dữ liệu mỗi tối là thông lệ đã được thiết lập."},{"en":"Following the established practice helps avoid common mistakes.","vi":"Tuân theo thông lệ đã được thiết lập giúp tránh các lỗi phổ biến."}]','[]',NULL,'/ɪˈstæblɪʃt ˈpræktɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3993,'colloc-5-01',103,'established principle','nguyên tắc đã được thiết lập','adj + n','[{"en":"Fair trial is an established principle in most legal systems.","vi":"Xét xử công bằng là nguyên tắc đã được thiết lập trong hầu hết hệ thống pháp luật."},{"en":"The theory rests on a well established principle of physics.","vi":"Lý thuyết dựa trên một nguyên tắc vật lý đã được thiết lập vững chắc."},{"en":"Respect for others is an established principle in our school.","vi":"Tôn trọng người khác là nguyên tắc đã được thiết lập ở trường chúng tôi."}]','[]',NULL,'/ɪˈstæblɪʃt ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3994,'colloc-5-01',104,'ethical consideration','cân nhắc về đạo đức','adj + n','[{"en":"Every medical trial must take ethical consideration into account.","vi":"Mọi thử nghiệm y khoa phải tính đến cân nhắc về đạo đức."},{"en":"Ethical consideration guided the researchers throughout the study.","vi":"Cân nhắc về đạo đức dẫn dắt các nhà nghiên cứu suốt cuộc nghiên cứu."},{"en":"The committee discussed ethical consideration before approving funding.","vi":"Ủy ban bàn về cân nhắc đạo đức trước khi phê duyệt tài trợ."}]','[]',NULL,'/ˈeθɪkəl kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3995,'colloc-5-01',105,'ethical dilemma','tình huống tiến thoái lưỡng nan về đạo đức','adj + n','[{"en":"The doctor faced a difficult ethical dilemma over the treatment.","vi":"Bác sĩ đối mặt với một tình huống lưỡng nan về đạo đức trong việc điều trị."},{"en":"Journalists often confront an ethical dilemma when reporting tragedies.","vi":"Nhà báo thường gặp tình huống lưỡng nan về đạo đức khi đưa tin bi kịch."},{"en":"The novel explores an ethical dilemma about loyalty and truth.","vi":"Cuốn tiểu thuyết khám phá tình huống lưỡng nan về đạo đức giữa lòng trung thành và sự thật."}]','[]',NULL,'/ˈeθɪkəl dɪˈlemə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3996,'colloc-5-01',106,'ethical issue','vấn đề đạo đức','adj + n','[{"en":"Cloning raises a serious ethical issue for many scientists.","vi":"Nhân bản đặt ra một vấn đề đạo đức nghiêm trọng với nhiều nhà khoa học."},{"en":"The class debated an ethical issue surrounding artificial intelligence.","vi":"Lớp học tranh luận về một vấn đề đạo đức xoay quanh trí tuệ nhân tạo."},{"en":"Privacy has become a major ethical issue in the digital age.","vi":"Quyền riêng tư đã trở thành vấn đề đạo đức lớn trong thời đại số."}]','[]',NULL,'/ˈeθɪkəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3997,'colloc-5-01',107,'ethical principle','nguyên tắc đạo đức','adj + n','[{"en":"Honesty is a basic ethical principle taught to every child.","vi":"Trung thực là một nguyên tắc đạo đức cơ bản dạy cho mọi đứa trẻ."},{"en":"The profession is guided by a strict ethical principle of care.","vi":"Nghề này được dẫn dắt bởi một nguyên tắc đạo đức nghiêm ngặt về sự chăm sóc."},{"en":"Respecting consent is a key ethical principle in research.","vi":"Tôn trọng sự đồng ý là nguyên tắc đạo đức then chốt trong nghiên cứu."}]','[]',NULL,'/ˈeθɪkəl ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3998,'colloc-5-01',108,'ethical problem','vấn đề đạo đức','adj + n','[{"en":"Using animals in testing poses a real ethical problem.","vi":"Dùng động vật để thử nghiệm đặt ra một vấn đề đạo đức thực sự."},{"en":"The lawyer saw an ethical problem with accepting the case.","vi":"Luật sư nhận ra một vấn đề đạo đức khi nhận vụ án này."},{"en":"Sharing private data creates a clear ethical problem for firms.","vi":"Chia sẻ dữ liệu riêng tư tạo ra một vấn đề đạo đức rõ ràng cho doanh nghiệp."}]','[]',NULL,'/ˈeθɪkəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(3999,'colloc-5-01',109,'ethical question','câu hỏi đạo đức','adj + n','[{"en":"The discovery raises a difficult ethical question for scientists.","vi":"Phát hiện này đặt ra một câu hỏi đạo đức khó cho các nhà khoa học."},{"en":"Whether to tell the truth was a tough ethical question.","vi":"Có nên nói sự thật hay không là một câu hỏi đạo đức khó."},{"en":"The film leaves the audience with a powerful ethical question.","vi":"Bộ phim để lại cho khán giả một câu hỏi đạo đức mạnh mẽ."}]','[]',NULL,'/ˈeθɪkəl ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4000,'colloc-5-01',110,'ethnic community','cộng đồng dân tộc','adj + n','[{"en":"The festival celebrates the traditions of each ethnic community.","vi":"Lễ hội tôn vinh truyền thống của mỗi cộng đồng dân tộc."},{"en":"The city is home to a large ethnic community from Asia.","vi":"Thành phố là nơi sinh sống của một cộng đồng dân tộc lớn từ châu Á."},{"en":"Local schools serve children from every ethnic community nearby.","vi":"Trường học địa phương phục vụ trẻ em từ mọi cộng đồng dân tộc lân cận."}]','[]',NULL,'/ˈeθnɪk kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4001,'colloc-5-01',111,'ethnic differences','sự khác biệt về dân tộc','adj + n','[{"en":"The study examined ethnic differences in eating habits.","vi":"Nghiên cứu xem xét sự khác biệt về dân tộc trong thói quen ăn uống."},{"en":"Respecting ethnic differences strengthens harmony in the workplace.","vi":"Tôn trọng sự khác biệt về dân tộc củng cố sự hòa hợp nơi làm việc."},{"en":"Ethnic differences should be celebrated rather than feared.","vi":"Sự khác biệt về dân tộc nên được tôn vinh thay vì lo ngại."}]','[]',NULL,'/ˈeθnɪk ˈdɪfrənsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4002,'colloc-5-01',112,'ethnic diversity','sự đa dạng dân tộc','adj + n','[{"en":"The city is famous for its rich ethnic diversity.","vi":"Thành phố nổi tiếng với sự đa dạng dân tộc phong phú."},{"en":"Ethnic diversity brings new ideas and cuisines to the region.","vi":"Sự đa dạng dân tộc mang đến ý tưởng và ẩm thực mới cho khu vực."},{"en":"The university values ethnic diversity among its students.","vi":"Trường đại học coi trọng sự đa dạng dân tộc trong sinh viên."}]','[]',NULL,'/ˈeθnɪk daɪˈvɜːrsəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4003,'colloc-5-01',113,'ethnic group','nhóm dân tộc','adj + n','[{"en":"Each ethnic group in the country has its own language.","vi":"Mỗi nhóm dân tộc trong nước có ngôn ngữ riêng."},{"en":"The survey included people from every major ethnic group.","vi":"Cuộc khảo sát bao gồm người từ mọi nhóm dân tộc chính."},{"en":"This ethnic group has lived in the mountains for centuries.","vi":"Nhóm dân tộc này đã sống ở vùng núi trong nhiều thế kỷ."}]','[]',NULL,'/ˈeθnɪk ɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4004,'colloc-5-01',114,'ethnic identity','bản sắc dân tộc','adj + n','[{"en":"Language plays a key role in shaping ethnic identity.","vi":"Ngôn ngữ đóng vai trò then chốt trong việc định hình bản sắc dân tộc."},{"en":"Many people take pride in their ethnic identity and heritage.","vi":"Nhiều người tự hào về bản sắc dân tộc và di sản của mình."},{"en":"Migration can complicate a person''s sense of ethnic identity.","vi":"Di cư có thể làm phức tạp cảm nhận về bản sắc dân tộc của một người."}]','[]',NULL,'/ˈeθnɪk aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4005,'colloc-5-01',115,'ethnic minority','dân tộc thiểu số','adj + n','[{"en":"The government introduced programs to support each ethnic minority.","vi":"Chính phủ giới thiệu các chương trình hỗ trợ mỗi dân tộc thiểu số."},{"en":"Members of the ethnic minority preserve their ancient customs.","vi":"Các thành viên dân tộc thiểu số gìn giữ phong tục cổ xưa của họ."},{"en":"The report studied access to healthcare among ethnic minority groups.","vi":"Báo cáo nghiên cứu việc tiếp cận y tế trong các nhóm dân tộc thiểu số."}]','[]',NULL,'/ˈeθnɪk maɪˈnɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4006,'colloc-5-01',116,'ethnic origin','nguồn gốc dân tộc','adj + n','[{"en":"Job applicants should not be judged by their ethnic origin.","vi":"Ứng viên không nên bị đánh giá dựa trên nguồn gốc dân tộc của họ."},{"en":"The form asks respondents to state their ethnic origin.","vi":"Biểu mẫu yêu cầu người trả lời nêu nguồn gốc dân tộc của mình."},{"en":"People of every ethnic origin are welcome at the event.","vi":"Mọi người thuộc mọi nguồn gốc dân tộc đều được chào đón tại sự kiện."}]','[]',NULL,'/ˈeθnɪk ˈɔːrɪdʒɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4007,'colloc-5-01',117,'ever changing','luôn thay đổi','adv + adj','[{"en":"Technology operates in an ever changing global marketplace.","vi":"Công nghệ vận hành trong một thị trường toàn cầu luôn thay đổi."},{"en":"Fashion trends are ever changing and hard to predict.","vi":"Xu hướng thời trang luôn thay đổi và khó dự đoán."},{"en":"Teachers must adapt to the ever changing needs of students.","vi":"Giáo viên phải thích nghi với nhu cầu luôn thay đổi của học sinh."}]','[]',NULL,'/ˈevər ˈtʃeɪndʒɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4008,'colloc-5-01',118,'ever increasing','không ngừng gia tăng','adv + adj','[{"en":"The company faces ever increasing demand for its products.","vi":"Công ty đối mặt với nhu cầu không ngừng gia tăng đối với sản phẩm."},{"en":"There is an ever increasing amount of data to manage.","vi":"Có một lượng dữ liệu không ngừng gia tăng cần quản lý."},{"en":"Cities struggle with the ever increasing cost of housing.","vi":"Các thành phố vật lộn với chi phí nhà ở không ngừng gia tăng."}]','[]',NULL,'/ˈevər ɪnˈkriːsɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4009,'colloc-5-01',119,'evolutionary process','quá trình tiến hóa','adj + n','[{"en":"The evolutionary process shaped the wings of birds over time.","vi":"Quá trình tiến hóa đã định hình đôi cánh của chim theo thời gian."},{"en":"Language develops through a slow evolutionary process across generations.","vi":"Ngôn ngữ phát triển qua một quá trình tiến hóa chậm qua các thế hệ."},{"en":"Scientists trace the evolutionary process using fossil evidence.","vi":"Các nhà khoa học truy nguyên quá trình tiến hóa bằng bằng chứng hóa thạch."}]','[]',NULL,'/ˌevəˈluːʃəneri ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4010,'colloc-5-01',120,'evolutionary theory','thuyết tiến hóa','adj + n','[{"en":"Evolutionary theory explains how species change over many generations.","vi":"Thuyết tiến hóa giải thích cách các loài thay đổi qua nhiều thế hệ."},{"en":"Darwin''s evolutionary theory transformed the study of biology.","vi":"Thuyết tiến hóa của Darwin đã làm thay đổi việc nghiên cứu sinh học."},{"en":"The professor lectured on evolutionary theory for two hours.","vi":"Giáo sư giảng về thuyết tiến hóa trong hai giờ."}]','[]',NULL,'/ˌevəˈluːʃəneri ˈθɪəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4011,'colloc-5-01',121,'examine the role of','xem xét vai trò của','v + n','[{"en":"This essay will examine the role of women in the revolution.","vi":"Bài luận này sẽ xem xét vai trò của phụ nữ trong cuộc cách mạng."},{"en":"Researchers examine the role of stress in causing illness.","vi":"Các nhà nghiên cứu xem xét vai trò của căng thẳng trong việc gây bệnh."},{"en":"The chapter examines the role of media in shaping opinion.","vi":"Chương này xem xét vai trò của truyền thông trong việc định hình dư luận."}]','[]',NULL,'/ɪɡˈzæmɪn ðə roʊl əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4012,'colloc-5-01',122,'exceptional case','trường hợp ngoại lệ','adj + n','[{"en":"The committee approved the request only as an exceptional case.","vi":"Ủy ban chỉ chấp thuận yêu cầu như một trường hợp ngoại lệ."},{"en":"Refunds are given solely in an exceptional case like illness.","vi":"Hoàn tiền chỉ được thực hiện trong trường hợp ngoại lệ như ốm đau."},{"en":"Her recovery was an exceptional case that surprised the doctors.","vi":"Sự hồi phục của cô là trường hợp ngoại lệ khiến các bác sĩ ngạc nhiên."}]','[]',NULL,'/ɪkˈsepʃənəl keɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4013,'colloc-5-01',123,'exceptional circumstances','hoàn cảnh đặc biệt','adj + n','[{"en":"Late submissions are accepted only under exceptional circumstances.","vi":"Nộp muộn chỉ được chấp nhận trong hoàn cảnh đặc biệt."},{"en":"The law allows exceptions in exceptional circumstances such as war.","vi":"Luật cho phép ngoại lệ trong hoàn cảnh đặc biệt như chiến tranh."},{"en":"Only in exceptional circumstances will the deadline be extended.","vi":"Hạn chót chỉ được gia hạn trong hoàn cảnh đặc biệt."}]','[]',NULL,'/ɪkˈsepʃənəl ˈsɜːrkəmstænsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4014,'colloc-5-01',124,'exercise authority','thực thi quyền lực','v + n','[{"en":"The manager must exercise authority fairly over the whole team.","vi":"Người quản lý phải thực thi quyền lực một cách công bằng với cả nhóm."},{"en":"Judges exercise authority granted to them by the constitution.","vi":"Các thẩm phán thực thi quyền lực được hiến pháp trao cho họ."},{"en":"A good leader knows when to exercise authority and when to listen.","vi":"Một lãnh đạo giỏi biết khi nào nên thực thi quyền lực và khi nào nên lắng nghe."}]','[]',NULL,'/ˈeksərsaɪz əˈθɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4015,'colloc-5-01',125,'existing data','dữ liệu hiện có','adj + n','[{"en":"The researchers analyzed existing data before collecting new samples.","vi":"Các nhà nghiên cứu phân tích dữ liệu hiện có trước khi thu thập mẫu mới."},{"en":"Existing data suggests a strong link between diet and health.","vi":"Dữ liệu hiện có cho thấy mối liên hệ chặt chẽ giữa chế độ ăn và sức khỏe."},{"en":"We reviewed existing data to identify gaps in the literature.","vi":"Chúng tôi rà soát dữ liệu hiện có để tìm lỗ hổng trong tài liệu."}]','[]',NULL,'/ɪɡˈzɪstɪŋ ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4016,'colloc-5-01',126,'existing research','nghiên cứu hiện có','adj + n','[{"en":"Existing research supports the idea that exercise improves mood.","vi":"Nghiên cứu hiện có ủng hộ ý kiến rằng tập thể dục cải thiện tâm trạng."},{"en":"Her thesis builds on existing research in the field.","vi":"Luận văn của cô dựa trên nghiên cứu hiện có trong lĩnh vực này."},{"en":"The author criticized gaps in the existing research on the topic.","vi":"Tác giả phê phán những lỗ hổng trong nghiên cứu hiện có về chủ đề này."}]','[]',NULL,'/ɪɡˈzɪstɪŋ ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4017,'colloc-5-01',127,'existing structure','cấu trúc hiện có','adj + n','[{"en":"The plan adds a new wing to the existing structure.","vi":"Kế hoạch xây thêm một cánh mới vào cấu trúc hiện có."},{"en":"Engineers tested whether the existing structure could bear the load.","vi":"Các kỹ sư kiểm tra xem cấu trúc hiện có có chịu được tải trọng không."},{"en":"Reform should improve, not destroy, the existing structure of government.","vi":"Cải cách nên cải thiện, không phá hủy, cấu trúc hiện có của chính quyền."}]','[]',NULL,'/ɪɡˈzɪstɪŋ ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4018,'colloc-5-01',128,'expand rapidly','mở rộng nhanh chóng','v + adv','[{"en":"The city began to expand rapidly after the railway opened.","vi":"Thành phố bắt đầu mở rộng nhanh chóng sau khi tuyến đường sắt mở."},{"en":"Online businesses can expand rapidly with little upfront cost.","vi":"Doanh nghiệp trực tuyến có thể mở rộng nhanh chóng với chi phí ban đầu thấp."},{"en":"The population continued to expand rapidly throughout the century.","vi":"Dân số tiếp tục mở rộng nhanh chóng suốt thế kỷ."}]','[]',NULL,'/ɪkˈspænd ˈræpɪdli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4019,'colloc-5-01',129,'experience difficulties','gặp khó khăn','v + n','[{"en":"Many students experience difficulties when starting university life.","vi":"Nhiều sinh viên gặp khó khăn khi bắt đầu cuộc sống đại học."},{"en":"Small firms often experience difficulties during an economic downturn.","vi":"Các doanh nghiệp nhỏ thường gặp khó khăn trong thời kỳ suy thoái kinh tế."},{"en":"Travelers may experience difficulties with the local language.","vi":"Du khách có thể gặp khó khăn với ngôn ngữ địa phương."}]','[]',NULL,'/ɪkˈspɪriəns ˈdɪfɪkəltiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4020,'colloc-5-01',130,'experience problems','gặp vấn đề','v + n','[{"en":"Users may experience problems if the software is not updated.","vi":"Người dùng có thể gặp vấn đề nếu phần mềm không được cập nhật."},{"en":"The factory began to experience problems with old machinery.","vi":"Nhà máy bắt đầu gặp vấn đề với máy móc cũ."},{"en":"Patients sometimes experience problems sleeping after the surgery.","vi":"Bệnh nhân đôi khi gặp vấn đề về giấc ngủ sau phẫu thuật."}]','[]',NULL,'/ɪkˈspɪriəns ˈprɑːbləmz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4021,'colloc-5-01',131,'experiential learning','học tập qua trải nghiệm','adj + n','[{"en":"Experiential learning lets students gain skills through real practice.","vi":"Học tập qua trải nghiệm cho phép sinh viên có kỹ năng qua thực hành thực tế."},{"en":"The internship is built around experiential learning in the field.","vi":"Kỳ thực tập được xây dựng quanh việc học tập qua trải nghiệm thực tế."},{"en":"Teachers use experiential learning to make lessons more engaging.","vi":"Giáo viên dùng học tập qua trải nghiệm để bài học hấp dẫn hơn."}]','[]',NULL,'/ɪkˌspɪriˈenʃəl ˈlɜːrnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4022,'colloc-5-01',132,'experimental conditions','điều kiện thí nghiệm','adj + n','[{"en":"The results were the same under different experimental conditions.","vi":"Kết quả vẫn giống nhau dưới các điều kiện thí nghiệm khác nhau."},{"en":"Scientists carefully controlled the experimental conditions in the lab.","vi":"Các nhà khoa học kiểm soát cẩn thận điều kiện thí nghiệm trong phòng lab."},{"en":"Changing the experimental conditions altered the outcome significantly.","vi":"Thay đổi điều kiện thí nghiệm đã làm kết quả thay đổi đáng kể."}]','[]',NULL,'/ɪkˌsperɪˈmentəl kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4023,'colloc-5-01',133,'experimental data','dữ liệu thí nghiệm','adj + n','[{"en":"The team published its experimental data in a leading journal.","vi":"Nhóm đã công bố dữ liệu thí nghiệm của mình trên một tạp chí hàng đầu."},{"en":"Experimental data confirmed the predictions of the new model.","vi":"Dữ liệu thí nghiệm xác nhận các dự đoán của mô hình mới."},{"en":"They compared experimental data with results from earlier studies.","vi":"Họ so sánh dữ liệu thí nghiệm với kết quả từ các nghiên cứu trước."}]','[]',NULL,'/ɪkˌsperɪˈmentəl ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4024,'colloc-5-01',134,'experimental design','thiết kế thí nghiệm','adj + n','[{"en":"A flawed experimental design can lead to misleading conclusions.","vi":"Thiết kế thí nghiệm sai sót có thể dẫn đến kết luận sai lệch."},{"en":"The professor praised the student''s careful experimental design.","vi":"Giáo sư khen ngợi thiết kế thí nghiệm cẩn thận của sinh viên."},{"en":"Good experimental design controls for as many variables as possible.","vi":"Thiết kế thí nghiệm tốt kiểm soát càng nhiều biến càng tốt."}]','[]',NULL,'/ɪkˌsperɪˈmentəl dɪˈzaɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4025,'colloc-5-01',135,'experimental evidence','bằng chứng thực nghiệm','adj + n','[{"en":"There is strong experimental evidence supporting the theory.","vi":"Có bằng chứng thực nghiệm mạnh mẽ ủng hộ lý thuyết này."},{"en":"The claim lacks any solid experimental evidence so far.","vi":"Cho đến nay tuyên bố này thiếu bằng chứng thực nghiệm vững chắc."},{"en":"New experimental evidence challenged the long held assumption.","vi":"Bằng chứng thực nghiệm mới thách thức giả định tồn tại lâu nay."}]','[]',NULL,'/ɪkˌsperɪˈmentəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4026,'colloc-5-01',136,'experimental method','phương pháp thực nghiệm','adj + n','[{"en":"The experimental method allows scientists to test their hypotheses.","vi":"Phương pháp thực nghiệm cho phép các nhà khoa học kiểm chứng giả thuyết."},{"en":"She explained the experimental method clearly in the report.","vi":"Cô giải thích rõ ràng phương pháp thực nghiệm trong báo cáo."},{"en":"Psychology adopted the experimental method from the natural sciences.","vi":"Tâm lý học đã tiếp nhận phương pháp thực nghiệm từ khoa học tự nhiên."}]','[]',NULL,'/ɪkˌsperɪˈmentəl ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4027,'colloc-5-01',137,'experimental research','nghiên cứu thực nghiệm','adj + n','[{"en":"Experimental research often requires a controlled laboratory setting.","vi":"Nghiên cứu thực nghiệm thường đòi hỏi môi trường phòng lab được kiểm soát."},{"en":"Her experimental research focuses on memory and aging.","vi":"Nghiên cứu thực nghiệm của cô tập trung vào trí nhớ và quá trình lão hóa."},{"en":"The grant funds experimental research into renewable energy.","vi":"Khoản tài trợ cấp vốn cho nghiên cứu thực nghiệm về năng lượng tái tạo."}]','[]',NULL,'/ɪkˌsperɪˈmentəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4028,'colloc-5-01',138,'experimental results','kết quả thí nghiệm','adj + n','[{"en":"The experimental results matched the theoretical predictions closely.","vi":"Kết quả thí nghiệm khớp chặt với các dự đoán lý thuyết."},{"en":"Researchers repeated the test to confirm the experimental results.","vi":"Các nhà nghiên cứu lặp lại bài kiểm tra để xác nhận kết quả thí nghiệm."},{"en":"The experimental results were surprising and sparked further study.","vi":"Kết quả thí nghiệm đầy bất ngờ và khơi mào cho nghiên cứu thêm."}]','[]',NULL,'/ɪkˌsperɪˈmentəl rɪˈzʌlts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4029,'colloc-5-01',139,'experimental study','nghiên cứu thí nghiệm','adj + n','[{"en":"The experimental study involved two hundred volunteers over a year.","vi":"Nghiên cứu thí nghiệm có hai trăm tình nguyện viên trong một năm."},{"en":"An experimental study tested the new drug on healthy adults.","vi":"Một nghiên cứu thí nghiệm thử thuốc mới trên những người trưởng thành khỏe mạnh."},{"en":"The experimental study produced clear and reliable findings.","vi":"Nghiên cứu thí nghiệm đã cho ra kết quả rõ ràng và đáng tin cậy."}]','[]',NULL,'/ɪkˌsperɪˈmentəl ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4030,'colloc-5-01',140,'experimental work','công việc thí nghiệm','adj + n','[{"en":"Most of her experimental work was carried out at night.","vi":"Phần lớn công việc thí nghiệm của cô được thực hiện vào ban đêm."},{"en":"The paper combines theory with detailed experimental work.","vi":"Bài báo kết hợp lý thuyết với công việc thí nghiệm chi tiết."},{"en":"Funding cuts delayed the experimental work for several months.","vi":"Việc cắt giảm ngân sách đã làm chậm công việc thí nghiệm vài tháng."}]','[]',NULL,'/ɪkˌsperɪˈmentəl wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4031,'colloc-5-01',141,'expert opinion','ý kiến chuyên gia','n + n','[{"en":"The court relied on expert opinion to reach its verdict.","vi":"Tòa án dựa vào ý kiến chuyên gia để đưa ra phán quyết."},{"en":"Before deciding, the company sought expert opinion on the matter.","vi":"Trước khi quyết định, công ty đã tìm kiếm ý kiến chuyên gia về vấn đề này."},{"en":"Expert opinion is divided on the safety of the new method.","vi":"Ý kiến chuyên gia bị chia rẽ về độ an toàn của phương pháp mới."}]','[]',NULL,'/ˈekspɜːrt əˈpɪnjən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4032,'colloc-5-01',142,'explanatory power','khả năng giải thích','adj + n','[{"en":"A good theory has strong explanatory power across many cases.","vi":"Một lý thuyết tốt có khả năng giải thích mạnh trong nhiều trường hợp."},{"en":"The model''s explanatory power impressed the review committee.","vi":"Khả năng giải thích của mô hình đã gây ấn tượng với hội đồng thẩm định."},{"en":"Critics argued the framework lacked real explanatory power.","vi":"Những người chỉ trích cho rằng khung lý thuyết thiếu khả năng giải thích thực sự."}]','[]',NULL,'/ɪkˈsplænətɔːri ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4033,'colloc-5-01',143,'explore further','khám phá sâu hơn','v + adv','[{"en":"The findings are promising, but we must explore further.","vi":"Những phát hiện này đầy hứa hẹn, nhưng chúng ta phải khám phá sâu hơn."},{"en":"The author invites readers to explore further in later chapters.","vi":"Tác giả mời độc giả khám phá sâu hơn ở các chương sau."},{"en":"Researchers plan to explore further how stress affects memory.","vi":"Các nhà nghiên cứu dự định khám phá sâu hơn cách căng thẳng ảnh hưởng trí nhớ."}]','[]',NULL,'/ɪkˈsplɔːr ˈfɜːrðər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4034,'colloc-5-01',144,'explore an issue','tìm hiểu một vấn đề','v + n','[{"en":"The seminar gave us time to explore an issue in depth.","vi":"Buổi hội thảo cho chúng tôi thời gian để tìm hiểu một vấn đề sâu sắc."},{"en":"Documentaries often explore an issue that the news overlooks.","vi":"Phim tài liệu thường tìm hiểu một vấn đề mà tin tức bỏ qua."},{"en":"Her essay sets out to explore an issue facing modern cities.","vi":"Bài luận của cô nhằm tìm hiểu một vấn đề mà các thành phố hiện đại đối mặt."}]','[]',NULL,'/ɪkˈsplɔːr ən ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4035,'colloc-5-01',145,'extended period','khoảng thời gian kéo dài','adj + n','[{"en":"Sitting for an extended period can harm your back over time.","vi":"Ngồi trong một khoảng thời gian kéo dài có thể hại lưng theo thời gian."},{"en":"The drought lasted for an extended period across the region.","vi":"Đợt hạn hán kéo dài trong một khoảng thời gian dài khắp khu vực."},{"en":"She trained over an extended period before the competition.","vi":"Cô tập luyện trong một khoảng thời gian kéo dài trước cuộc thi."}]','[]',NULL,'/ɪkˈstendɪd ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4036,'colloc-5-01',146,'extensive research','nghiên cứu sâu rộng','adj + n','[{"en":"The book is based on extensive research into local history.","vi":"Cuốn sách dựa trên nghiên cứu sâu rộng về lịch sử địa phương."},{"en":"Extensive research has shown the benefits of regular exercise.","vi":"Nghiên cứu sâu rộng đã chỉ ra lợi ích của việc tập thể dục đều đặn."},{"en":"She conducted extensive research before writing her dissertation.","vi":"Cô tiến hành nghiên cứu sâu rộng trước khi viết luận án của mình."}]','[]',NULL,'/ɪkˈstensɪv ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4037,'colloc-5-01',147,'extensively used','được sử dụng rộng rãi','adv + vpp','[{"en":"This method is extensively used in modern medical research today.","vi":"Phương pháp này được sử dụng rộng rãi trong nghiên cứu y học hiện đại."},{"en":"Solar panels are now extensively used across many rural communities.","vi":"Tấm pin mặt trời nay được sử dụng rộng rãi ở nhiều vùng nông thôn."},{"en":"The software is extensively used by students writing their theses.","vi":"Phần mềm này được sinh viên dùng rộng rãi khi viết luận văn."}]','[]',NULL,'/ɪkˈstensɪvli juːzd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4038,'colloc-5-01',148,'external environment','môi trường bên ngoài','adj + n','[{"en":"Companies must adapt quickly to changes in the external environment.","vi":"Các công ty phải nhanh chóng thích nghi với thay đổi của môi trường bên ngoài."},{"en":"The external environment shapes how organisms behave and survive.","vi":"Môi trường bên ngoài định hình cách sinh vật ứng xử và tồn tại."},{"en":"Analyzing the external environment helps managers plan effective strategies.","vi":"Phân tích môi trường bên ngoài giúp nhà quản lý hoạch định chiến lược hiệu quả."}]','[]',NULL,'/ɪkˈstɜːrnəl ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4039,'colloc-5-01',149,'external factors','các yếu tố bên ngoài','adj + n','[{"en":"External factors such as weather strongly affected the harvest this year.","vi":"Các yếu tố bên ngoài như thời tiết đã ảnh hưởng mạnh đến vụ mùa năm nay."},{"en":"Researchers tried to isolate the external factors influencing the results.","vi":"Các nhà nghiên cứu cố tách riêng các yếu tố bên ngoài tác động đến kết quả."},{"en":"Economic external factors can quickly change a company''s profit margins.","vi":"Các yếu tố kinh tế bên ngoài có thể nhanh chóng thay đổi lợi nhuận công ty."}]','[]',NULL,'/ɪkˈstɜːrnəl ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4040,'colloc-5-01',150,'external forces','các lực bên ngoài','adj + n','[{"en":"External forces caused the bridge to collapse during the storm.","vi":"Các lực bên ngoài khiến cây cầu sụp đổ trong cơn bão."},{"en":"The nation''s politics were shaped by powerful external forces.","vi":"Nền chính trị của quốc gia bị các lực bên ngoài mạnh mẽ định hình."},{"en":"Engineers calculate how external forces act upon a structure.","vi":"Kỹ sư tính toán cách các lực bên ngoài tác động lên một kết cấu."}]','[]',NULL,'/ɪkˈstɜːrnəl ˈfɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4041,'colloc-6-01',1,'external influences','các ảnh hưởng bên ngoài','adj + n','[{"en":"Children''s behavior is shaped by many external influences over time.","vi":"Hành vi của trẻ được hình thành bởi nhiều ảnh hưởng bên ngoài theo thời gian."},{"en":"The study examined external influences on consumer spending habits.","vi":"Nghiên cứu xem xét các ảnh hưởng bên ngoài đến thói quen chi tiêu của người tiêu dùng."},{"en":"Artists often resist external influences to preserve their original style.","vi":"Nghệ sĩ thường chống lại các ảnh hưởng bên ngoài để giữ phong cách riêng."}]','[]',NULL,'/ɪkˈstɜːrnəl ˈɪnfluənsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4042,'colloc-6-01',2,'external source','nguồn bên ngoài','adj + n','[{"en":"The data came from an external source outside the laboratory.","vi":"Dữ liệu đến từ một nguồn bên ngoài phòng thí nghiệm."},{"en":"Always cite any external source you use in your essay.","vi":"Hãy luôn trích dẫn mọi nguồn bên ngoài bạn dùng trong bài luận."},{"en":"The company secured funding from an external source last month.","vi":"Công ty đã huy động vốn từ một nguồn bên ngoài tháng trước."}]','[]',NULL,'/ɪkˈstɜːrnəl sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4043,'colloc-6-01',3,'external threat','mối đe dọa từ bên ngoài','adj + n','[{"en":"The government strengthened defenses against any possible external threat.","vi":"Chính phủ củng cố phòng thủ trước mọi mối đe dọa có thể từ bên ngoài."},{"en":"An external threat often unites people who once disagreed.","vi":"Mối đe dọa từ bên ngoài thường gắn kết những người từng bất đồng."},{"en":"Cybersecurity teams monitor systems for any external threat constantly.","vi":"Đội an ninh mạng liên tục giám sát hệ thống để phát hiện mối đe dọa bên ngoài."}]','[]',NULL,'/ɪkˈstɜːrnəl θret/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4044,'colloc-6-01',4,'external world','thế giới bên ngoài','adj + n','[{"en":"Our senses connect the mind to the external world around us.","vi":"Các giác quan kết nối tâm trí ta với thế giới bên ngoài."},{"en":"Philosophers long debated how we truly know the external world.","vi":"Các triết gia từ lâu tranh luận về cách ta thực sự biết thế giới bên ngoài."},{"en":"Isolated communities sometimes lose contact with the external world.","vi":"Các cộng đồng biệt lập đôi khi mất liên lạc với thế giới bên ngoài."}]','[]',NULL,'/ɪkˈstɜːrnəl wɜːrld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4045,'colloc-6-01',5,'extract data','trích xuất dữ liệu','v + n','[{"en":"Analysts extract data from large surveys to find useful patterns.","vi":"Các nhà phân tích trích xuất dữ liệu từ khảo sát lớn để tìm quy luật."},{"en":"The program can extract data from thousands of files automatically.","vi":"Chương trình có thể tự động trích xuất dữ liệu từ hàng nghìn tệp."},{"en":"Researchers extract data carefully before running statistical tests.","vi":"Các nhà nghiên cứu trích xuất dữ liệu cẩn thận trước khi chạy kiểm định thống kê."}]','[]',NULL,'/ɪkˈstrækt ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4046,'colloc-6-01',6,'extract information','trích xuất thông tin','v + n','[{"en":"Good readers extract information quickly from complex academic texts.","vi":"Người đọc giỏi trích xuất thông tin nhanh từ các văn bản học thuật phức tạp."},{"en":"Detectives extract information from witnesses to reconstruct the events.","vi":"Thám tử khai thác thông tin từ nhân chứng để dựng lại sự việc."},{"en":"The tool helps you extract information from scanned documents easily.","vi":"Công cụ này giúp bạn trích xuất thông tin từ tài liệu quét dễ dàng."}]','[]',NULL,'/ɪkˈstrækt ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4047,'colloc-6-01',7,'extremely complex','cực kỳ phức tạp','adv + adj','[{"en":"The human brain is an extremely complex biological system.","vi":"Bộ não con người là một hệ thống sinh học cực kỳ phức tạp."},{"en":"International trade negotiations are often extremely complex and slow.","vi":"Đàm phán thương mại quốc tế thường cực kỳ phức tạp và chậm chạp."},{"en":"The mathematical proof turned out to be extremely complex.","vi":"Chứng minh toán học hóa ra lại cực kỳ phức tạp."}]','[]',NULL,'/ɪkˈstriːmli kəmˈpleks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4048,'colloc-6-01',8,'extremely powerful','cực kỳ mạnh mẽ','adv + adj','[{"en":"Modern supercomputers are extremely powerful and process huge datasets.","vi":"Siêu máy tính hiện đại cực kỳ mạnh mẽ và xử lý lượng dữ liệu khổng lồ."},{"en":"The speech delivered an extremely powerful message about equality.","vi":"Bài phát biểu truyền tải một thông điệp cực kỳ mạnh mẽ về bình đẳng."},{"en":"Volcanic eruptions release extremely powerful bursts of energy.","vi":"Núi lửa phun trào giải phóng những luồng năng lượng cực kỳ mạnh mẽ."}]','[]',NULL,'/ɪkˈstriːmli ˈpaʊərfəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4049,'colloc-6-01',9,'extremely sensitive','cực kỳ nhạy cảm','adv + adj','[{"en":"The instrument is extremely sensitive to even tiny temperature changes.","vi":"Thiết bị này cực kỳ nhạy cảm với cả những thay đổi nhiệt độ nhỏ nhất."},{"en":"Discussions about religion can be extremely sensitive in some cultures.","vi":"Các cuộc bàn luận về tôn giáo có thể cực kỳ nhạy cảm ở một số nền văn hóa."},{"en":"Newborn babies have extremely sensitive skin that needs gentle care.","vi":"Trẻ sơ sinh có làn da cực kỳ nhạy cảm cần được chăm sóc nhẹ nhàng."}]','[]',NULL,'/ɪkˈstriːmli ˈsensətɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4050,'colloc-6-01',10,'extremely useful','cực kỳ hữu ích','adv + adj','[{"en":"This dictionary app is extremely useful for learning new vocabulary.","vi":"Ứng dụng từ điển này cực kỳ hữu ích để học từ vựng mới."},{"en":"Her feedback was extremely useful when I revised the report.","vi":"Góp ý của cô ấy cực kỳ hữu ích khi tôi sửa lại báo cáo."},{"en":"The map proved extremely useful while exploring the old city.","vi":"Tấm bản đồ tỏ ra cực kỳ hữu ích khi khám phá thành phố cổ."}]','[]',NULL,'/ɪkˈstriːmli ˈjuːsfəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4051,'colloc-6-01',11,'extremely valuable','cực kỳ quý giá','adv + adj','[{"en":"The internship gave me extremely valuable experience for my career.","vi":"Kỳ thực tập đã cho tôi kinh nghiệm cực kỳ quý giá cho sự nghiệp."},{"en":"These ancient manuscripts are extremely valuable to historians.","vi":"Những bản thảo cổ này cực kỳ quý giá đối với các nhà sử học."},{"en":"Clean drinking water is an extremely valuable resource worldwide.","vi":"Nước uống sạch là một nguồn tài nguyên cực kỳ quý giá trên toàn cầu."}]','[]',NULL,'/ɪkˈstriːmli ˈvæljuəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4052,'colloc-6-01',12,'face difficulties','đối mặt với khó khăn','v + n','[{"en":"Many new immigrants face difficulties when learning a foreign language.","vi":"Nhiều người nhập cư mới đối mặt với khó khăn khi học ngoại ngữ."},{"en":"Small businesses often face difficulties during an economic downturn.","vi":"Doanh nghiệp nhỏ thường đối mặt với khó khăn trong thời kỳ suy thoái kinh tế."},{"en":"Students who face difficulties should ask their teachers for help.","vi":"Sinh viên gặp khó khăn nên nhờ giáo viên giúp đỡ."}]','[]',NULL,'/feɪs ˈdɪfɪkəltiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4053,'colloc-6-01',13,'face discrimination','đối mặt với sự phân biệt đối xử','v + n','[{"en":"Minority workers sometimes face discrimination in hiring and promotion.","vi":"Người lao động thiểu số đôi khi đối mặt với phân biệt khi tuyển dụng và thăng chức."},{"en":"Laws were passed so people no longer face discrimination at work.","vi":"Các luật được ban hành để mọi người không còn bị phân biệt đối xử tại nơi làm việc."},{"en":"Many disabled citizens still face discrimination in everyday life.","vi":"Nhiều công dân khuyết tật vẫn đối mặt với sự phân biệt trong cuộc sống hằng ngày."}]','[]',NULL,'/feɪs dɪˌskrɪmɪˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4054,'colloc-6-01',14,'face a challenge','đối mặt với một thử thách','v + n','[{"en":"Every leader must face a challenge with courage and patience.","vi":"Mọi nhà lãnh đạo đều phải đối mặt với một thử thách bằng lòng can đảm và kiên nhẫn."},{"en":"The team will face a challenge adapting to the new system.","vi":"Cả nhóm sẽ đối mặt với một thử thách khi thích nghi với hệ thống mới."},{"en":"Athletes often face a challenge returning after a serious injury.","vi":"Vận động viên thường đối mặt với một thử thách khi trở lại sau chấn thương nặng."}]','[]',NULL,'/feɪs ə ˈtʃælɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4055,'colloc-6-01',15,'face a dilemma','đối mặt với một tình huống tiến thoái lưỡng nan','v + n','[{"en":"Doctors sometimes face a dilemma when patients refuse treatment.","vi":"Bác sĩ đôi khi đối mặt với tình huống khó xử khi bệnh nhân từ chối điều trị."},{"en":"Parents often face a dilemma balancing work and family time.","vi":"Cha mẹ thường đối mặt với tình huống khó xử khi cân bằng công việc và gia đình."},{"en":"The manager will face a dilemma choosing between two strong candidates.","vi":"Người quản lý sẽ rơi vào thế khó khi chọn giữa hai ứng viên xuất sắc."}]','[]',NULL,'/feɪs ə dɪˈlemə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4056,'colloc-6-01',16,'face a problem','đối mặt với một vấn đề','v + n','[{"en":"Engineers had to face a problem with the bridge''s design.","vi":"Các kỹ sư phải đối mặt với một vấn đề trong thiết kế cây cầu."},{"en":"When you face a problem, try breaking it into smaller parts.","vi":"Khi đối mặt với một vấn đề, hãy thử chia nhỏ nó ra."},{"en":"Coastal cities now face a problem caused by rising sea levels.","vi":"Các thành phố ven biển nay đối mặt với một vấn đề do mực nước biển dâng."}]','[]',NULL,'/feɪs ə ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4057,'colloc-6-01',17,'facial expression','biểu cảm khuôn mặt','adj + n','[{"en":"A friendly facial expression can make a strong first impression.","vi":"Một biểu cảm khuôn mặt thân thiện có thể tạo ấn tượng đầu mạnh mẽ."},{"en":"Researchers study how facial expression reveals hidden emotions.","vi":"Các nhà nghiên cứu tìm hiểu cách biểu cảm khuôn mặt bộc lộ cảm xúc giấu kín."},{"en":"Her facial expression showed surprise when she heard the news.","vi":"Biểu cảm khuôn mặt cô ấy lộ vẻ ngạc nhiên khi nghe tin."}]','[]',NULL,'/ˈfeɪʃəl ɪkˈspreʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4058,'colloc-6-01',18,'facilitate the development of','tạo điều kiện cho sự phát triển của','v + n','[{"en":"Good infrastructure helps facilitate the development of rural economies.","vi":"Cơ sở hạ tầng tốt giúp tạo điều kiện cho sự phát triển của kinh tế nông thôn."},{"en":"Reading widely can facilitate the development of critical thinking.","vi":"Đọc rộng có thể tạo điều kiện cho sự phát triển của tư duy phản biện."},{"en":"Government grants facilitate the development of clean energy technology.","vi":"Các khoản trợ cấp của chính phủ thúc đẩy sự phát triển của công nghệ năng lượng sạch."}]','[]',NULL,'/fəˈsɪlɪteɪt ðə dɪˈveləpmənt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4059,'colloc-6-01',19,'factual information','thông tin thực tế, chính xác','adj + n','[{"en":"A good encyclopedia provides reliable factual information on many topics.","vi":"Một cuốn bách khoa tốt cung cấp thông tin thực tế đáng tin về nhiều chủ đề."},{"en":"Journalists must separate factual information from personal opinion.","vi":"Nhà báo phải tách thông tin thực tế khỏi quan điểm cá nhân."},{"en":"The report contains factual information drawn from official records.","vi":"Báo cáo chứa thông tin thực tế lấy từ hồ sơ chính thức."}]','[]',NULL,'/ˈfæktʃuəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4060,'colloc-6-01',20,'fair treatment','sự đối xử công bằng','adj + n','[{"en":"All employees deserve fair treatment regardless of their background.","vi":"Mọi nhân viên đều xứng đáng được đối xử công bằng bất kể xuất thân."},{"en":"The new policy guarantees fair treatment for every customer.","vi":"Chính sách mới bảo đảm sự đối xử công bằng cho mọi khách hàng."},{"en":"Prisoners are entitled to fair treatment under international law.","vi":"Tù nhân được quyền đối xử công bằng theo luật quốc tế."}]','[]',NULL,'/fer ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4061,'colloc-6-01',21,'fairly clear','khá rõ ràng','adv + adj','[{"en":"The instructions were fairly clear, so few students asked questions.","vi":"Hướng dẫn khá rõ ràng nên ít sinh viên đặt câu hỏi."},{"en":"It is fairly clear that the experiment supported the hypothesis.","vi":"Khá rõ ràng rằng thí nghiệm đã ủng hộ giả thuyết."},{"en":"Her explanation made the difficult concept fairly clear to everyone.","vi":"Lời giải thích của cô làm khái niệm khó trở nên khá rõ với mọi người."}]','[]',NULL,'/ˈferli klɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4062,'colloc-6-01',22,'fairly common','khá phổ biến','adv + adj','[{"en":"This kind of error is fairly common among beginning writers.","vi":"Loại lỗi này khá phổ biến ở những người mới tập viết."},{"en":"Mild allergies are fairly common and usually easy to manage.","vi":"Dị ứng nhẹ khá phổ biến và thường dễ kiểm soát."},{"en":"Working from home has become fairly common in recent years.","vi":"Làm việc tại nhà đã trở nên khá phổ biến trong những năm gần đây."}]','[]',NULL,'/ˈferli ˈkɑːmən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4063,'colloc-6-01',23,'fairly obvious','khá rõ ràng, dễ thấy','adv + adj','[{"en":"The reason for the failure was fairly obvious to the team.","vi":"Nguyên nhân thất bại khá rõ ràng đối với cả nhóm."},{"en":"It seems fairly obvious that more practice improves performance.","vi":"Có vẻ khá rõ ràng rằng luyện tập nhiều hơn giúp cải thiện kết quả."},{"en":"The connection between the two events was fairly obvious.","vi":"Mối liên hệ giữa hai sự kiện khá dễ thấy."}]','[]',NULL,'/ˈferli ˈɑːbviəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4064,'colloc-6-01',24,'fairly straightforward','khá đơn giản, dễ hiểu','adv + adj','[{"en":"The assembly process is fairly straightforward if you follow the steps.","vi":"Quá trình lắp ráp khá đơn giản nếu bạn làm theo các bước."},{"en":"The exam questions were fairly straightforward and well organized.","vi":"Các câu hỏi trong bài thi khá đơn giản và được sắp xếp hợp lý."},{"en":"Setting up the account is fairly straightforward for most users.","vi":"Việc thiết lập tài khoản khá đơn giản với đa số người dùng."}]','[]',NULL,'/ˈferli ˌstreɪtˈfɔːrwərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4065,'colloc-6-01',25,'fall into the category of','thuộc vào loại, xếp vào nhóm','v + n','[{"en":"These plants fall into the category of tropical evergreen species.","vi":"Những cây này thuộc vào loại cây thường xanh nhiệt đới."},{"en":"Such expenses fall into the category of long-term investments.","vi":"Những chi phí như vậy được xếp vào nhóm đầu tư dài hạn."},{"en":"Her work seems to fall into the category of modern art.","vi":"Tác phẩm của cô dường như thuộc vào loại nghệ thuật hiện đại."}]','[]',NULL,'/fɔːl ˈɪntə ðə ˈkætəɡɔːri əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4066,'colloc-6-01',26,'far removed from','khác xa, cách xa với','adv + vpp','[{"en":"The theory is far removed from the realities of daily life.","vi":"Lý thuyết này khác xa với thực tế của đời sống hằng ngày."},{"en":"His childhood village felt far removed from the busy capital.","vi":"Ngôi làng thời thơ ấu của anh cách xa thủ đô nhộn nhịp."},{"en":"The final design was far removed from the original sketch.","vi":"Bản thiết kế cuối khác xa với bản phác thảo ban đầu."}]','[]',NULL,'/fɑːr rɪˈmuːvd frəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4067,'colloc-6-01',27,'federal agency','cơ quan liên bang','adj + n','[{"en":"A federal agency was created to oversee national food safety.","vi":"Một cơ quan liên bang được lập ra để giám sát an toàn thực phẩm quốc gia."},{"en":"Each federal agency must report its spending to Congress yearly.","vi":"Mỗi cơ quan liên bang phải báo cáo chi tiêu cho Quốc hội hằng năm."},{"en":"The federal agency investigated the cause of the airplane accident.","vi":"Cơ quan liên bang đã điều tra nguyên nhân vụ tai nạn máy bay."}]','[]',NULL,'/ˈfedərəl ˈeɪdʒənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4068,'colloc-6-01',28,'federal government','chính phủ liên bang','adj + n','[{"en":"The federal government collects taxes to fund national programs.","vi":"Chính phủ liên bang thu thuế để tài trợ cho các chương trình quốc gia."},{"en":"Disaster relief is usually coordinated by the federal government.","vi":"Cứu trợ thảm họa thường do chính phủ liên bang điều phối."},{"en":"The federal government passed new laws to protect the environment.","vi":"Chính phủ liên bang đã thông qua luật mới để bảo vệ môi trường."}]','[]',NULL,'/ˈfedərəl ˈɡʌvərnmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4069,'colloc-6-01',29,'federal state','nhà nước liên bang','adj + n','[{"en":"In a federal state, power is shared between regional governments.","vi":"Trong một nhà nước liên bang, quyền lực được chia sẻ giữa các chính quyền vùng."},{"en":"Germany is a federal state made up of sixteen regions.","vi":"Đức là một nhà nước liên bang gồm mười sáu vùng."},{"en":"A federal state must balance local autonomy with national unity.","vi":"Một nhà nước liên bang phải cân bằng quyền tự trị địa phương với sự thống nhất quốc gia."}]','[]',NULL,'/ˈfedərəl steɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4070,'colloc-6-01',30,'feminist movement','phong trào nữ quyền','adj + n','[{"en":"The feminist movement fought hard for women''s voting rights.","vi":"Phong trào nữ quyền đã đấu tranh mạnh mẽ cho quyền bầu cử của phụ nữ."},{"en":"Historians study how the feminist movement changed workplace laws.","vi":"Các nhà sử học nghiên cứu cách phong trào nữ quyền thay đổi luật lao động."},{"en":"The feminist movement inspired many writers in the twentieth century.","vi":"Phong trào nữ quyền đã truyền cảm hứng cho nhiều nhà văn thế kỷ hai mươi."}]','[]',NULL,'/ˈfemənɪst ˈmuːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4071,'colloc-6-01',31,'field research','nghiên cứu thực địa','n + n','[{"en":"The biologist spent six months doing field research in the rainforest.","vi":"Nhà sinh học dành sáu tháng nghiên cứu thực địa trong rừng mưa."},{"en":"Field research often gives insights that lab studies cannot provide.","vi":"Nghiên cứu thực địa thường mang lại hiểu biết mà nghiên cứu trong phòng không có."},{"en":"Students conducted field research by interviewing local farmers directly.","vi":"Sinh viên thực hiện nghiên cứu thực địa bằng cách phỏng vấn trực tiếp nông dân địa phương."}]','[]',NULL,'/fiːld ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4072,'colloc-6-01',32,'final analysis','phân tích cuối cùng','adj + n','[{"en":"The final analysis confirmed that the treatment was effective.","vi":"Phân tích cuối cùng xác nhận rằng phương pháp điều trị có hiệu quả."},{"en":"In the final analysis, both approaches reached similar conclusions.","vi":"Xét đến cùng, cả hai cách tiếp cận đều đi đến kết luận tương tự."},{"en":"The team presented its final analysis at the research conference.","vi":"Nhóm đã trình bày phân tích cuối cùng tại hội nghị nghiên cứu."}]','[]',NULL,'/ˈfaɪnəl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4073,'colloc-6-01',33,'final answer','câu trả lời cuối cùng','adj + n','[{"en":"Check your calculations carefully before writing the final answer.","vi":"Hãy kiểm tra phép tính cẩn thận trước khi viết câu trả lời cuối cùng."},{"en":"The committee gave its final answer after a long discussion.","vi":"Ủy ban đưa ra câu trả lời cuối cùng sau một cuộc thảo luận dài."},{"en":"She thought carefully and then gave her final answer.","vi":"Cô suy nghĩ kỹ rồi đưa ra câu trả lời cuối cùng."}]','[]',NULL,'/ˈfaɪnəl ˈænsər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4074,'colloc-6-01',34,'final chapter','chương cuối','adj + n','[{"en":"The final chapter summarizes the main arguments of the book.","vi":"Chương cuối tóm tắt các luận điểm chính của cuốn sách."},{"en":"Readers were surprised by the twist in the final chapter.","vi":"Độc giả bất ngờ trước cú lật ở chương cuối."},{"en":"She wrote the final chapter of her thesis last week.","vi":"Cô đã viết chương cuối của luận văn vào tuần trước."}]','[]',NULL,'/ˈfaɪnəl ˈtʃæptər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4075,'colloc-6-01',35,'final decision','quyết định cuối cùng','adj + n','[{"en":"The board will make its final decision at tomorrow''s meeting.","vi":"Hội đồng sẽ đưa ra quyết định cuối cùng trong cuộc họp ngày mai."},{"en":"After much debate, the judge announced the final decision.","vi":"Sau nhiều tranh luận, thẩm phán đã công bố quyết định cuối cùng."},{"en":"The final decision rests with the head of the department.","vi":"Quyết định cuối cùng thuộc về trưởng khoa."}]','[]',NULL,'/ˈfaɪnəl dɪˈsɪʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4076,'colloc-6-01',36,'final outcome','kết quả cuối cùng','adj + n','[{"en":"No one could predict the final outcome of the election.","vi":"Không ai có thể dự đoán kết quả cuối cùng của cuộc bầu cử."},{"en":"The final outcome depended on several unpredictable factors.","vi":"Kết quả cuối cùng phụ thuộc vào vài yếu tố khó lường."},{"en":"Both teams worked hard, but the final outcome was a draw.","vi":"Cả hai đội đều cố gắng, nhưng kết quả cuối cùng là hòa."}]','[]',NULL,'/ˈfaɪnəl ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4077,'colloc-6-01',37,'final phase','giai đoạn cuối','adj + n','[{"en":"The project has now entered its final phase of testing.","vi":"Dự án nay đã bước vào giai đoạn cuối của quá trình thử nghiệm."},{"en":"During the final phase, the team checks every detail carefully.","vi":"Trong giai đoạn cuối, nhóm kiểm tra cẩn thận từng chi tiết."},{"en":"Construction reached its final phase ahead of the deadline.","vi":"Việc xây dựng đã đến giai đoạn cuối trước thời hạn."}]','[]',NULL,'/ˈfaɪnəl feɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4078,'colloc-6-01',38,'final point','điểm cuối cùng, luận điểm cuối','adj + n','[{"en":"As a final point, the author urges readers to take action.","vi":"Như một luận điểm cuối, tác giả kêu gọi độc giả hành động."},{"en":"The speaker saved her strongest argument for the final point.","vi":"Diễn giả dành luận điểm mạnh nhất cho phần cuối cùng."},{"en":"Let me make one final point before we end the discussion.","vi":"Hãy để tôi nêu một điểm cuối cùng trước khi kết thúc thảo luận."}]','[]',NULL,'/ˈfaɪnəl pɔɪnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4079,'colloc-6-01',39,'final position','vị trí cuối cùng','adj + n','[{"en":"The runner secured the final position in the national rankings.","vi":"Vận động viên giành được vị trí cuối cùng trong bảng xếp hạng quốc gia."},{"en":"Scientists measured the final position of the moving object.","vi":"Các nhà khoa học đo vị trí cuối cùng của vật chuyển động."},{"en":"After negotiations, both sides clarified their final position.","vi":"Sau đàm phán, cả hai bên làm rõ lập trường cuối cùng của mình."}]','[]',NULL,'/ˈfaɪnəl pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4080,'colloc-6-01',40,'final product','sản phẩm cuối cùng','adj + n','[{"en":"The final product must pass quality checks before being sold.","vi":"Sản phẩm cuối cùng phải qua kiểm tra chất lượng trước khi được bán."},{"en":"Customers care more about the final product than the process.","vi":"Khách hàng quan tâm đến sản phẩm cuối cùng hơn là quy trình."},{"en":"The team was proud of the final product they created.","vi":"Cả nhóm tự hào về sản phẩm cuối cùng mà họ tạo ra."}]','[]',NULL,'/ˈfaɪnəl ˈprɑːdʌkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4081,'colloc-6-01',41,'final result','kết quả cuối cùng','adj + n','[{"en":"The final result of the experiment matched the team''s predictions.","vi":"Kết quả cuối cùng của thí nghiệm khớp với dự đoán của nhóm."},{"en":"Students waited anxiously for the final result of the exam.","vi":"Sinh viên hồi hộp chờ kết quả cuối cùng của kỳ thi."},{"en":"The final result showed a clear improvement over last year.","vi":"Kết quả cuối cùng cho thấy sự cải thiện rõ rệt so với năm ngoái."}]','[]',NULL,'/ˈfaɪnəl rɪˈzʌlt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4082,'colloc-6-01',42,'final section','phần cuối','adj + n','[{"en":"The final section of the report lists recommendations for managers.","vi":"Phần cuối của báo cáo liệt kê các khuyến nghị cho nhà quản lý."},{"en":"Please read the final section carefully before the exam.","vi":"Hãy đọc kỹ phần cuối trước khi thi."},{"en":"The final section of the test covers grammar and vocabulary.","vi":"Phần cuối của bài kiểm tra bao gồm ngữ pháp và từ vựng."}]','[]',NULL,'/ˈfaɪnəl ˈsekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4083,'colloc-6-01',43,'final stage','giai đoạn cuối','adj + n','[{"en":"The negotiations have now reached their final stage.","vi":"Các cuộc đàm phán nay đã đến giai đoạn cuối."},{"en":"In the final stage, the caterpillar transforms into a butterfly.","vi":"Ở giai đoạn cuối, sâu bướm biến thành con bướm."},{"en":"We are in the final stage of preparing the new course.","vi":"Chúng tôi đang ở giai đoạn cuối của việc chuẩn bị khóa học mới."}]','[]',NULL,'/ˈfaɪnəl steɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4084,'colloc-6-01',44,'final step','bước cuối cùng','adj + n','[{"en":"The final step is to submit your application before the deadline.","vi":"Bước cuối cùng là nộp đơn của bạn trước hạn chót."},{"en":"Cooling the mixture is the final step in the procedure.","vi":"Làm nguội hỗn hợp là bước cuối cùng trong quy trình."},{"en":"After editing, the final step is to publish the article.","vi":"Sau khi biên tập, bước cuối cùng là xuất bản bài viết."}]','[]',NULL,'/ˈfaɪnəl step/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4085,'colloc-6-01',45,'final version','phiên bản cuối cùng','adj + n','[{"en":"Please send me the final version of the document by Friday.","vi":"Vui lòng gửi tôi phiên bản cuối cùng của tài liệu trước thứ Sáu."},{"en":"The final version of the software fixed all major bugs.","vi":"Phiên bản cuối cùng của phần mềm đã sửa mọi lỗi lớn."},{"en":"She revised the essay three times before the final version.","vi":"Cô sửa bài luận ba lần trước khi có phiên bản cuối cùng."}]','[]',NULL,'/ˈfaɪnəl ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4086,'colloc-6-01',46,'financial affairs','công việc, vấn đề tài chính','adj + n','[{"en":"An accountant helps the family manage its financial affairs.","vi":"Một kế toán viên giúp gia đình quản lý các vấn đề tài chính."},{"en":"The company kept its financial affairs strictly confidential.","vi":"Công ty giữ các vấn đề tài chính của mình hoàn toàn bí mật."},{"en":"Good record-keeping makes managing financial affairs much easier.","vi":"Việc lưu hồ sơ tốt khiến quản lý tài chính dễ dàng hơn nhiều."}]','[]',NULL,'/faɪˈnænʃəl əˈferz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4087,'colloc-6-01',47,'financial assistance','hỗ trợ tài chính','adj + n','[{"en":"Many students rely on financial assistance to pay their tuition.","vi":"Nhiều sinh viên dựa vào hỗ trợ tài chính để trả học phí."},{"en":"The charity offers financial assistance to families in need.","vi":"Tổ chức từ thiện cung cấp hỗ trợ tài chính cho các gia đình khó khăn."},{"en":"Governments provided financial assistance after the natural disaster.","vi":"Các chính phủ đã cung cấp hỗ trợ tài chính sau thảm họa thiên nhiên."}]','[]',NULL,'/faɪˈnænʃəl əˈsɪstəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4088,'colloc-6-01',48,'financial institution','tổ chức tài chính','adj + n','[{"en":"A bank is the most common type of financial institution.","vi":"Ngân hàng là loại tổ chức tài chính phổ biến nhất."},{"en":"Every financial institution must follow strict government regulations.","vi":"Mọi tổ chức tài chính phải tuân theo các quy định nghiêm ngặt của chính phủ."},{"en":"The financial institution offered low interest rates to borrowers.","vi":"Tổ chức tài chính này cung cấp lãi suất thấp cho người vay."}]','[]',NULL,'/faɪˈnænʃəl ˌɪnstɪˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4089,'colloc-6-01',49,'financial management','quản lý tài chính','adj + n','[{"en":"Sound financial management is essential for any successful business.","vi":"Quản lý tài chính tốt là điều thiết yếu cho mọi doanh nghiệp thành công."},{"en":"The course teaches basic financial management to young entrepreneurs.","vi":"Khóa học dạy quản lý tài chính cơ bản cho các doanh nhân trẻ."},{"en":"Poor financial management led the company into serious debt.","vi":"Quản lý tài chính kém đã đẩy công ty vào nợ nần nghiêm trọng."}]','[]',NULL,'/faɪˈnænʃəl ˈmænɪdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4090,'colloc-6-01',50,'financial market','thị trường tài chính','adj + n','[{"en":"The financial market reacted strongly to the central bank''s decision.","vi":"Thị trường tài chính phản ứng mạnh với quyết định của ngân hàng trung ương."},{"en":"Investors watch the financial market closely for new opportunities.","vi":"Nhà đầu tư theo dõi sát thị trường tài chính để tìm cơ hội mới."},{"en":"A stable financial market encourages long-term economic growth.","vi":"Một thị trường tài chính ổn định khuyến khích tăng trưởng kinh tế dài hạn."}]','[]',NULL,'/faɪˈnænʃəl ˈmɑːrkɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4091,'colloc-6-01',51,'financial problem','vấn đề tài chính','adj + n','[{"en":"The family faced a serious financial problem after losing work.","vi":"Gia đình đối mặt với một vấn đề tài chính nghiêm trọng sau khi mất việc."},{"en":"Careful budgeting can help you avoid a financial problem.","vi":"Lập ngân sách cẩn thận có thể giúp bạn tránh vấn đề tài chính."},{"en":"The small business solved its financial problem with a loan.","vi":"Doanh nghiệp nhỏ đã giải quyết vấn đề tài chính bằng một khoản vay."}]','[]',NULL,'/faɪˈnænʃəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4092,'colloc-6-01',52,'financial resources','nguồn lực tài chính','adj + n','[{"en":"The school lacks the financial resources to hire more teachers.","vi":"Trường thiếu nguồn lực tài chính để thuê thêm giáo viên."},{"en":"Limited financial resources forced the team to delay the project.","vi":"Nguồn lực tài chính hạn hẹp buộc nhóm phải hoãn dự án."},{"en":"Wealthy nations have greater financial resources for research.","vi":"Các quốc gia giàu có có nhiều nguồn lực tài chính hơn cho nghiên cứu."}]','[]',NULL,'/faɪˈnænʃəl ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4093,'colloc-6-01',53,'financial support','hỗ trợ tài chính','adj + n','[{"en":"The scholarship provides financial support for talented students.","vi":"Học bổng cung cấp hỗ trợ tài chính cho các sinh viên tài năng."},{"en":"Without financial support, the research project would have stopped.","vi":"Nếu không có hỗ trợ tài chính, dự án nghiên cứu đã phải dừng lại."},{"en":"Parents often give financial support to children at university.","vi":"Cha mẹ thường hỗ trợ tài chính cho con khi học đại học."}]','[]',NULL,'/faɪˈnænʃəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4094,'colloc-6-01',54,'find evidence','tìm thấy bằng chứng','v + n','[{"en":"Scientists hope to find evidence of water on distant planets.","vi":"Các nhà khoa học hy vọng tìm thấy bằng chứng về nước trên các hành tinh xa."},{"en":"Investigators worked hard to find evidence of the crime.","vi":"Các điều tra viên nỗ lực tìm bằng chứng về tội ác."},{"en":"Researchers could not find evidence to support the old theory.","vi":"Các nhà nghiên cứu không tìm thấy bằng chứng ủng hộ lý thuyết cũ."}]','[]',NULL,'/faɪnd ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4095,'colloc-6-01',55,'find information','tìm thông tin','v + n','[{"en":"You can find information about the course on the website.","vi":"Bạn có thể tìm thông tin về khóa học trên trang web."},{"en":"Librarians help students find information for their research projects.","vi":"Thủ thư giúp sinh viên tìm thông tin cho các dự án nghiên cứu."},{"en":"It is easy to find information online, but verify the sources.","vi":"Tìm thông tin trực tuyến rất dễ, nhưng hãy kiểm chứng nguồn."}]','[]',NULL,'/faɪnd ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4096,'colloc-6-01',56,'finite number','số lượng hữu hạn','adj + n','[{"en":"There is only a finite number of seats in the lecture hall.","vi":"Chỉ có một số lượng ghế hữu hạn trong giảng đường."},{"en":"The planet holds a finite number of natural resources.","vi":"Hành tinh chỉ chứa một lượng tài nguyên thiên nhiên hữu hạn."},{"en":"A game with a finite number of moves must eventually end.","vi":"Một trò chơi có số nước đi hữu hạn cuối cùng phải kết thúc."}]','[]',NULL,'/ˈfaɪnaɪt ˈnʌmbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4097,'colloc-6-01',57,'firmly established','được thiết lập vững chắc','adv + vpp','[{"en":"The theory is now firmly established in modern physics.","vi":"Lý thuyết này nay đã được thiết lập vững chắc trong vật lý hiện đại."},{"en":"Their reputation became firmly established after years of hard work.","vi":"Danh tiếng của họ trở nên vững chắc sau nhiều năm nỗ lực."},{"en":"The company is firmly established as a leader in technology.","vi":"Công ty đã khẳng định vững chắc vị trí dẫn đầu trong ngành công nghệ."}]','[]',NULL,'/ˈfɜːrmli ɪˈstæblɪʃt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4098,'colloc-6-01',58,'first author','tác giả chính (đứng tên đầu)','adj + n','[{"en":"She was the first author of the highly cited research paper.","vi":"Cô là tác giả chính của bài nghiên cứu được trích dẫn nhiều."},{"en":"The first author usually does most of the project''s work.","vi":"Tác giả đứng đầu thường làm phần lớn công việc của dự án."},{"en":"As first author, he presented the findings at the conference.","vi":"Là tác giả chính, anh đã trình bày các phát hiện tại hội nghị."}]','[]',NULL,'/fɜːrst ˈɔːθər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4099,'colloc-6-01',59,'first contact','lần tiếp xúc đầu tiên','adj + n','[{"en":"The first contact between the two cultures changed history forever.","vi":"Lần tiếp xúc đầu tiên giữa hai nền văn hóa đã thay đổi lịch sử mãi mãi."},{"en":"Make a good impression during your first contact with clients.","vi":"Hãy tạo ấn tượng tốt trong lần tiếp xúc đầu tiên với khách hàng."},{"en":"The receptionist is often the first contact for new visitors.","vi":"Lễ tân thường là người tiếp xúc đầu tiên với khách mới."}]','[]',NULL,'/fɜːrst ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4100,'colloc-6-01',60,'first draft','bản nháp đầu tiên','adj + n','[{"en":"The first draft of an essay is rarely perfect or polished.","vi":"Bản nháp đầu tiên của một bài luận hiếm khi hoàn hảo hay trau chuốt."},{"en":"She finished the first draft of her novel last month.","vi":"Cô đã hoàn thành bản nháp đầu tiên của tiểu thuyết tháng trước."},{"en":"Always revise your first draft before submitting the final paper.","vi":"Hãy luôn sửa bản nháp đầu tiên trước khi nộp bài cuối cùng."}]','[]',NULL,'/fɜːrst dræft/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4101,'colloc-6-01',61,'first encounter','lần gặp gỡ đầu tiên','adj + n','[{"en":"Their first encounter took place at an academic conference abroad.","vi":"Lần gặp gỡ đầu tiên của họ diễn ra tại một hội nghị học thuật ở nước ngoài."},{"en":"My first encounter with classical music was at a school concert.","vi":"Lần đầu tiên tôi tiếp xúc với nhạc cổ điển là tại buổi hòa nhạc trường."},{"en":"The book describes the explorer''s first encounter with the tribe.","vi":"Cuốn sách mô tả lần gặp gỡ đầu tiên của nhà thám hiểm với bộ tộc."}]','[]',NULL,'/fɜːrst ɪnˈkaʊntər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4102,'colloc-6-01',62,'first generation','thế hệ đầu tiên','adj + n','[{"en":"She is the first generation in her family to attend university.","vi":"Cô là thế hệ đầu tiên trong gia đình được học đại học."},{"en":"The first generation of smartphones was bulky and very expensive.","vi":"Thế hệ điện thoại thông minh đầu tiên cồng kềnh và rất đắt."},{"en":"First generation immigrants often work hard to support their children.","vi":"Người nhập cư thế hệ đầu thường làm việc chăm chỉ để nuôi con."}]','[]',NULL,'/fɜːrst ˌdʒenəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4103,'colloc-6-01',63,'first impression','ấn tượng đầu tiên','adj + n','[{"en":"A polite greeting helps create a good first impression.","vi":"Một lời chào lịch sự giúp tạo ấn tượng đầu tiên tốt."},{"en":"First impression often influences how we judge new people.","vi":"Ấn tượng đầu tiên thường ảnh hưởng đến cách ta đánh giá người mới."},{"en":"Her confident speech made a strong first impression on the panel.","vi":"Bài phát biểu tự tin của cô tạo ấn tượng đầu mạnh với ban giám khảo."}]','[]',NULL,'/fɜːrst ɪmˈpreʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4104,'colloc-6-01',64,'first phase','giai đoạn đầu tiên','adj + n','[{"en":"The first phase of the project focuses on collecting data.","vi":"Giai đoạn đầu tiên của dự án tập trung vào thu thập dữ liệu."},{"en":"During the first phase, the team trained all new staff.","vi":"Trong giai đoạn đầu, nhóm đã đào tạo toàn bộ nhân viên mới."},{"en":"The first phase of construction was completed ahead of schedule.","vi":"Giai đoạn đầu tiên của việc xây dựng được hoàn thành trước hạn."}]','[]',NULL,'/fɜːrst feɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4105,'colloc-6-01',65,'first priority','ưu tiên hàng đầu','adj + n','[{"en":"Safety should always be the first priority on any worksite.","vi":"An toàn luôn phải là ưu tiên hàng đầu tại mọi công trường."},{"en":"Her first priority was finishing the report before the deadline.","vi":"Ưu tiên hàng đầu của cô là hoàn thành báo cáo trước hạn chót."},{"en":"Improving education remains the government''s first priority this year.","vi":"Cải thiện giáo dục vẫn là ưu tiên hàng đầu của chính phủ năm nay."}]','[]',NULL,'/fɜːrst praɪˈɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4106,'colloc-6-01',66,'flexible approach','cách tiếp cận linh hoạt','adj + n','[{"en":"A flexible approach allows teachers to meet different students'' needs.","vi":"Cách tiếp cận linh hoạt giúp giáo viên đáp ứng nhu cầu khác nhau của học sinh."},{"en":"The company adopted a flexible approach to remote working.","vi":"Công ty áp dụng cách tiếp cận linh hoạt với việc làm từ xa."},{"en":"Solving complex problems often requires a flexible approach.","vi":"Giải quyết các vấn đề phức tạp thường đòi hỏi cách tiếp cận linh hoạt."}]','[]',NULL,'/ˈfleksəbəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4107,'colloc-6-01',67,'focal point','tâm điểm, điểm trọng tâm','adj + n','[{"en":"The fireplace is the focal point of the entire living room.","vi":"Lò sưởi là tâm điểm của toàn bộ phòng khách."},{"en":"Climate change has become the focal point of recent debates.","vi":"Biến đổi khí hậu đã trở thành tâm điểm của các cuộc tranh luận gần đây."},{"en":"The tower serves as the focal point of the historic city.","vi":"Ngọn tháp là điểm trọng tâm của thành phố cổ."}]','[]',NULL,'/ˈfoʊkəl pɔɪnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4108,'colloc-6-01',68,'focus attention on','tập trung sự chú ý vào','v + n','[{"en":"The campaign aims to focus attention on childhood nutrition.","vi":"Chiến dịch nhằm tập trung sự chú ý vào dinh dưỡng cho trẻ em."},{"en":"Teachers should focus attention on the weakest students first.","vi":"Giáo viên nên tập trung sự chú ý vào những học sinh yếu nhất trước."},{"en":"The report tries to focus attention on rising energy costs.","vi":"Báo cáo cố gắng tập trung sự chú ý vào chi phí năng lượng tăng cao."}]','[]',NULL,'/ˈfoʊkəs əˈtenʃən ɑːn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4109,'colloc-6-01',69,'focus on an aspect','tập trung vào một khía cạnh','v + n','[{"en":"This chapter will focus on an aspect of language learning.","vi":"Chương này sẽ tập trung vào một khía cạnh của việc học ngôn ngữ."},{"en":"The study chose to focus on an aspect of consumer behavior.","vi":"Nghiên cứu chọn tập trung vào một khía cạnh của hành vi người tiêu dùng."},{"en":"Try to focus on an aspect you find genuinely interesting.","vi":"Hãy cố tập trung vào một khía cạnh mà bạn thực sự thấy thú vị."}]','[]',NULL,'/ˈfoʊkəs ɑːn ən ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4110,'colloc-6-01',70,'follow a format','tuân theo một định dạng','v + n','[{"en":"All essays must follow a format set by the department.","vi":"Mọi bài luận phải tuân theo một định dạng do khoa quy định."},{"en":"Scientific reports usually follow a format with clear sections.","vi":"Báo cáo khoa học thường tuân theo một định dạng có các phần rõ ràng."},{"en":"Please follow a format consistent with the official guidelines.","vi":"Hãy tuân theo một định dạng nhất quán với hướng dẫn chính thức."}]','[]',NULL,'/ˈfɑːloʊ ə ˈfɔːrmæt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4111,'colloc-6-01',71,'follow a procedure','tuân theo một quy trình','v + n','[{"en":"Lab workers must follow a procedure to ensure everyone''s safety.","vi":"Nhân viên phòng thí nghiệm phải tuân theo một quy trình để đảm bảo an toàn cho mọi người."},{"en":"Always follow a procedure carefully when handling dangerous chemicals.","vi":"Hãy luôn tuân theo một quy trình cẩn thận khi xử lý hóa chất nguy hiểm."},{"en":"Nurses follow a procedure when preparing patients for surgery.","vi":"Y tá tuân theo một quy trình khi chuẩn bị cho bệnh nhân phẫu thuật."}]','[]',NULL,'/ˈfɑːloʊ ə prəˈsiːdʒər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4112,'colloc-6-01',72,'follow instructions','làm theo hướng dẫn','v + n','[{"en":"Students who follow instructions carefully usually make fewer mistakes.","vi":"Học sinh làm theo hướng dẫn cẩn thận thường mắc ít lỗi hơn."},{"en":"Please follow instructions on the label before taking the medicine.","vi":"Hãy làm theo hướng dẫn trên nhãn trước khi uống thuốc."},{"en":"He failed the test because he did not follow instructions.","vi":"Anh ấy trượt bài kiểm tra vì không làm theo hướng dẫn."}]','[]',NULL,'/ˈfɑːloʊ ɪnˈstrʌkʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4113,'colloc-6-01',73,'following chapter','chương tiếp theo','adj + n','[{"en":"The following chapter explains the method in much greater detail.","vi":"Chương tiếp theo giải thích phương pháp một cách chi tiết hơn nhiều."},{"en":"These ideas will be developed further in the following chapter.","vi":"Những ý tưởng này sẽ được phát triển thêm trong chương tiếp theo."},{"en":"The following chapter presents the results of the survey.","vi":"Chương tiếp theo trình bày kết quả của cuộc khảo sát."}]','[]',NULL,'/ˈfɑːloʊɪŋ ˈtʃæptər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4114,'colloc-6-01',74,'foreign currency','ngoại tệ','adj + n','[{"en":"Travelers should exchange foreign currency before leaving the airport.","vi":"Du khách nên đổi ngoại tệ trước khi rời sân bay."},{"en":"The bank charges a small fee for foreign currency transactions.","vi":"Ngân hàng thu một khoản phí nhỏ cho các giao dịch ngoại tệ."},{"en":"Exports earn the country valuable foreign currency each year.","vi":"Xuất khẩu mang lại cho đất nước nguồn ngoại tệ quý giá mỗi năm."}]','[]',NULL,'/ˈfɔːrən ˈkɜːrənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4115,'colloc-6-01',75,'foreign investment','đầu tư nước ngoài','adj + n','[{"en":"Foreign investment helped the country build new roads and factories.","vi":"Đầu tư nước ngoài đã giúp đất nước xây dựng đường sá và nhà máy mới."},{"en":"The government introduced policies to attract more foreign investment.","vi":"Chính phủ đưa ra chính sách để thu hút thêm đầu tư nước ngoài."},{"en":"Foreign investment can create many jobs in developing economies.","vi":"Đầu tư nước ngoài có thể tạo nhiều việc làm ở các nền kinh tế đang phát triển."}]','[]',NULL,'/ˈfɔːrən ɪnˈvestmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4116,'colloc-6-01',76,'foreign investor','nhà đầu tư nước ngoài','adj + n','[{"en":"A foreign investor bought a large share of the company.","vi":"Một nhà đầu tư nước ngoài đã mua phần lớn cổ phần của công ty."},{"en":"Stable laws make a country attractive to every foreign investor.","vi":"Luật pháp ổn định khiến một quốc gia hấp dẫn với mọi nhà đầu tư nước ngoài."},{"en":"The foreign investor hopes to expand the business across Asia.","vi":"Nhà đầu tư nước ngoài hy vọng mở rộng kinh doanh khắp châu Á."}]','[]',NULL,'/ˈfɔːrən ɪnˈvestər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4117,'colloc-6-01',77,'foreign policy','chính sách đối ngoại','adj + n','[{"en":"The new president promised major changes in foreign policy.","vi":"Tân tổng thống hứa hẹn những thay đổi lớn trong chính sách đối ngoại."},{"en":"Foreign policy decisions can affect trade with many countries.","vi":"Các quyết định về chính sách đối ngoại có thể ảnh hưởng đến thương mại với nhiều nước."},{"en":"Students debated the country''s foreign policy during the seminar.","vi":"Sinh viên tranh luận về chính sách đối ngoại của đất nước trong buổi hội thảo."}]','[]',NULL,'/ˈfɔːrən ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4118,'colloc-6-01',78,'formal structure','cấu trúc chính thức, trang trọng','adj + n','[{"en":"A good essay needs a clear and formal structure throughout.","vi":"Một bài luận tốt cần một cấu trúc rõ ràng và trang trọng xuyên suốt."},{"en":"The organization has a formal structure with several departments.","vi":"Tổ chức có một cấu trúc chính thức gồm nhiều phòng ban."},{"en":"Classical music often follows a strict and formal structure.","vi":"Nhạc cổ điển thường tuân theo một cấu trúc nghiêm ngặt và trang trọng."}]','[]',NULL,'/ˈfɔːrməl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4119,'colloc-6-01',79,'free access','quyền truy cập miễn phí','adj + n','[{"en":"Students enjoy free access to the university''s online library.","vi":"Sinh viên được truy cập miễn phí vào thư viện trực tuyến của trường."},{"en":"The policy guarantees free access to public health services.","vi":"Chính sách bảo đảm quyền truy cập miễn phí vào dịch vụ y tế công."},{"en":"Researchers value free access to peer-reviewed academic journals.","vi":"Các nhà nghiên cứu coi trọng quyền truy cập miễn phí vào tạp chí học thuật."}]','[]',NULL,'/friː ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4120,'colloc-6-01',80,'free movement','sự di chuyển tự do','adj + n','[{"en":"The treaty allows free movement of workers between member states.","vi":"Hiệp ước cho phép lao động di chuyển tự do giữa các nước thành viên."},{"en":"Free movement of goods boosts trade across the region.","vi":"Sự di chuyển tự do của hàng hóa thúc đẩy thương mại trong khu vực."},{"en":"Border controls can restrict the free movement of people.","vi":"Việc kiểm soát biên giới có thể hạn chế sự di chuyển tự do của con người."}]','[]',NULL,'/friː ˈmuːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4121,'colloc-6-01',81,'freely available','có sẵn miễn phí, dễ dàng tiếp cận','adv + adj','[{"en":"The software is freely available for download on the website.","vi":"Phần mềm này có sẵn miễn phí để tải về trên trang web."},{"en":"Much of the data is freely available to other researchers.","vi":"Phần lớn dữ liệu được cung cấp miễn phí cho các nhà nghiên cứu khác."},{"en":"These resources are freely available through the public archive.","vi":"Các tài nguyên này có sẵn miễn phí qua kho lưu trữ công cộng."}]','[]',NULL,'/ˈfriːli əˈveɪləbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4122,'colloc-6-01',82,'frequently cited','được trích dẫn thường xuyên','adv + vpp','[{"en":"This article is frequently cited in studies of language learning.","vi":"Bài báo này được trích dẫn thường xuyên trong các nghiên cứu về học ngôn ngữ."},{"en":"Her work remains frequently cited by scholars in the field.","vi":"Công trình của bà vẫn được các học giả trong ngành trích dẫn thường xuyên."},{"en":"Frequently cited papers tend to shape later research directions.","vi":"Những bài báo được trích dẫn nhiều thường định hình hướng nghiên cứu về sau."}]','[]',NULL,'/ˈfriːkwəntli ˈsaɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4123,'colloc-6-01',83,'frequently found','thường thấy, hay bắt gặp','adv + vpp','[{"en":"This species is frequently found in shallow coastal waters.","vi":"Loài này thường thấy ở vùng nước nông ven biển."},{"en":"Such errors are frequently found in students'' early drafts.","vi":"Những lỗi như vậy thường thấy trong các bản nháp đầu của sinh viên."},{"en":"The compound is frequently found in volcanic rock samples.","vi":"Hợp chất này hay bắt gặp trong các mẫu đá núi lửa."}]','[]',NULL,'/ˈfriːkwəntli faʊnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4124,'colloc-6-01',84,'frequently referred to','thường được nhắc đến, hay được viện dẫn','adv + vpp','[{"en":"This theory is frequently referred to in economics textbooks.","vi":"Lý thuyết này thường được nhắc đến trong các giáo trình kinh tế."},{"en":"The case is frequently referred to during legal seminars.","vi":"Vụ án này hay được viện dẫn trong các buổi hội thảo pháp lý."},{"en":"His model is frequently referred to as a classic example.","vi":"Mô hình của ông thường được nhắc đến như một ví dụ kinh điển."}]','[]',NULL,'/ˈfriːkwəntli rɪˈfɜːrd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4125,'colloc-6-01',85,'frequently used','thường được sử dụng','adv + vpp','[{"en":"This method is frequently used in qualitative research studies.","vi":"Phương pháp này thường được sử dụng trong các nghiên cứu định tính."},{"en":"The term is frequently used by economists to describe inflation.","vi":"Thuật ngữ này thường được các nhà kinh tế dùng để mô tả lạm phát."},{"en":"Frequently used phrases can make essays sound repetitive.","vi":"Những cụm từ được dùng nhiều có thể khiến bài luận nghe lặp lại."}]','[]',NULL,'/ˈfriːkwəntli juːzd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4126,'colloc-6-01',86,'fulfil an obligation','thực hiện một nghĩa vụ','v + n','[{"en":"The company must fulfil an obligation to protect its customers.","vi":"Công ty phải thực hiện nghĩa vụ bảo vệ khách hàng của mình."},{"en":"Citizens fulfil an obligation by paying their taxes on time.","vi":"Công dân thực hiện một nghĩa vụ bằng cách nộp thuế đúng hạn."},{"en":"Failing to fulfil an obligation can lead to legal consequences.","vi":"Không thực hiện nghĩa vụ có thể dẫn đến hậu quả pháp lý."}]','[]',NULL,'/fʊlˈfɪl ən ˌɑːblɪˈɡeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4127,'colloc-6-01',87,'full analysis','sự phân tích đầy đủ, toàn diện','adj + n','[{"en":"A full analysis of the data revealed several unexpected patterns.","vi":"Một phân tích đầy đủ về dữ liệu cho thấy nhiều mô hình bất ngờ."},{"en":"The report includes a full analysis of the survey results.","vi":"Báo cáo bao gồm một phân tích toàn diện về kết quả khảo sát."},{"en":"A full analysis is needed before drawing any firm conclusions.","vi":"Cần một phân tích đầy đủ trước khi rút ra kết luận chắc chắn."}]','[]',NULL,'/fʊl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4128,'colloc-6-01',88,'full employment','toàn dụng lao động (mọi người có việc làm)','adj + n','[{"en":"The government aims to achieve full employment within a decade.","vi":"Chính phủ đặt mục tiêu đạt toàn dụng lao động trong một thập kỷ."},{"en":"Full employment often puts upward pressure on wages.","vi":"Toàn dụng lao động thường tạo áp lực tăng lên tiền lương."},{"en":"Economists debate whether full employment is truly attainable.","vi":"Các nhà kinh tế tranh luận liệu toàn dụng lao động có thực sự đạt được."}]','[]',NULL,'/fʊl ɪmˈplɔɪmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4129,'colloc-6-01',89,'full information','thông tin đầy đủ','adj + n','[{"en":"Patients should receive full information before agreeing to treatment.","vi":"Bệnh nhân nên nhận thông tin đầy đủ trước khi đồng ý điều trị."},{"en":"The website provides full information about admission requirements.","vi":"Trang web cung cấp thông tin đầy đủ về yêu cầu tuyển sinh."},{"en":"Decisions made without full information are often unreliable.","vi":"Quyết định đưa ra mà thiếu thông tin đầy đủ thường không đáng tin."}]','[]',NULL,'/fʊl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4130,'colloc-6-01',90,'full participation','sự tham gia đầy đủ, trọn vẹn','adj + n','[{"en":"The program encourages full participation from every team member.","vi":"Chương trình khuyến khích sự tham gia đầy đủ của từng thành viên."},{"en":"Full participation in class improves students'' speaking confidence.","vi":"Tham gia đầy đủ trong lớp giúp sinh viên tự tin hơn khi nói."},{"en":"Equal access ensures the full participation of disabled citizens.","vi":"Tiếp cận bình đẳng bảo đảm sự tham gia trọn vẹn của người khuyết tật."}]','[]',NULL,'/fʊl pɑːrˌtɪsɪˈpeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4131,'colloc-6-01',91,'full potential','tiềm năng đầy đủ, trọn vẹn','adj + n','[{"en":"Good teaching helps students reach their full potential.","vi":"Việc giảng dạy tốt giúp sinh viên phát huy hết tiềm năng của mình."},{"en":"The technology has not yet realized its full potential.","vi":"Công nghệ này vẫn chưa phát huy hết tiềm năng của nó."},{"en":"Investment is required for the region to achieve full potential.","vi":"Cần đầu tư để khu vực đạt được tiềm năng trọn vẹn của mình."}]','[]',NULL,'/fʊl pəˈtenʃəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4132,'colloc-6-01',92,'full range of','đầy đủ các loại, toàn bộ phạm vi','adj + n','[{"en":"The course covers a full range of research methods.","vi":"Khóa học bao quát đầy đủ các phương pháp nghiên cứu."},{"en":"The clinic offers a full range of medical services.","vi":"Phòng khám cung cấp đầy đủ các loại dịch vụ y tế."},{"en":"Students explore a full range of viewpoints in the seminar.","vi":"Sinh viên khám phá toàn bộ phạm vi quan điểm trong buổi hội thảo."}]','[]',NULL,'/fʊl reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4133,'colloc-6-01',93,'fuller discussion','sự bàn luận sâu rộng hơn','adj + n','[{"en":"A fuller discussion of these issues appears in chapter four.","vi":"Một bàn luận sâu rộng hơn về các vấn đề này nằm ở chương bốn."},{"en":"The topic deserves a fuller discussion than space allows here.","vi":"Chủ đề này đáng được bàn luận sâu hơn so với khuôn khổ ở đây."},{"en":"Reviewers asked for a fuller discussion of the limitations.","vi":"Người phản biện yêu cầu bàn luận đầy đủ hơn về các hạn chế."}]','[]',NULL,'/ˈfʊlər dɪˈskʌʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4134,'colloc-6-01',94,'fully aware','hoàn toàn nhận thức được, ý thức rõ','adv + adj','[{"en":"The researchers were fully aware of the study''s limitations.","vi":"Các nhà nghiên cứu hoàn toàn nhận thức được những hạn chế của nghiên cứu."},{"en":"Participants were fully aware of the risks before joining.","vi":"Người tham gia ý thức rõ về các rủi ro trước khi tham gia."},{"en":"Managers should be fully aware of local labor laws.","vi":"Người quản lý nên hoàn toàn nắm rõ luật lao động địa phương."}]','[]',NULL,'/ˈfʊli əˈwer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4135,'colloc-6-01',95,'fully developed','phát triển hoàn chỉnh, đầy đủ','adv + vpp','[{"en":"The theory is not yet fully developed and needs more testing.","vi":"Lý thuyết này chưa được phát triển hoàn chỉnh và cần kiểm chứng thêm."},{"en":"A fully developed argument requires strong supporting evidence.","vi":"Một lập luận phát triển đầy đủ cần có bằng chứng hỗ trợ vững chắc."},{"en":"The embryo''s organs are not fully developed at this stage.","vi":"Các cơ quan của phôi chưa phát triển hoàn chỉnh ở giai đoạn này."}]','[]',NULL,'/ˈfʊli dɪˈveləpt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4136,'colloc-6-01',96,'fully informed','được thông tin đầy đủ','adv + vpp','[{"en":"Voters must be fully informed before making such decisions.","vi":"Cử tri phải được thông tin đầy đủ trước khi đưa ra quyết định đó."},{"en":"The consent form ensures patients are fully informed.","vi":"Mẫu đồng ý bảo đảm rằng bệnh nhân được thông tin đầy đủ."},{"en":"A fully informed choice depends on access to reliable data.","vi":"Một lựa chọn được thông tin đầy đủ phụ thuộc vào dữ liệu đáng tin cậy."}]','[]',NULL,'/ˈfʊli ɪnˈfɔːrmd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4137,'colloc-6-01',97,'fully integrated','được tích hợp hoàn toàn','adv + vpp','[{"en":"The new software is fully integrated with existing systems.","vi":"Phần mềm mới được tích hợp hoàn toàn với các hệ thống hiện có."},{"en":"Immigrants who are fully integrated tend to find work faster.","vi":"Người nhập cư hòa nhập hoàn toàn thường tìm được việc nhanh hơn."},{"en":"The modules are fully integrated into a single curriculum.","vi":"Các học phần được tích hợp hoàn toàn vào một chương trình duy nhất."}]','[]',NULL,'/ˈfʊli ˈɪntɪˌɡreɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4138,'colloc-6-01',98,'fully realized','được hiện thực hóa trọn vẹn','adv + vpp','[{"en":"The project''s benefits were never fully realized in practice.","vi":"Lợi ích của dự án chưa bao giờ được hiện thực hóa trọn vẹn trên thực tế."},{"en":"Her ambitions were fully realized only after years of work.","vi":"Hoài bão của cô chỉ được hiện thực hóa trọn vẹn sau nhiều năm nỗ lực."},{"en":"The potential of renewable energy is not yet fully realized.","vi":"Tiềm năng của năng lượng tái tạo vẫn chưa được khai thác trọn vẹn."}]','[]',NULL,'/ˈfʊli ˈriːəˌlaɪzd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4139,'colloc-6-01',99,'fully understand','hiểu một cách đầy đủ, thấu hiểu','adv + v','[{"en":"Scientists do not yet fully understand how the disease spreads.","vi":"Các nhà khoa học vẫn chưa hiểu đầy đủ cách bệnh lây lan."},{"en":"To fully understand the results, read the methods section first.","vi":"Để hiểu trọn vẹn kết quả, hãy đọc phần phương pháp trước."},{"en":"Students must fully understand the theory before applying it.","vi":"Sinh viên phải thấu hiểu lý thuyết trước khi áp dụng nó."}]','[]',NULL,'/ˈfʊli ˌʌndərˈstænd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4140,'colloc-6-01',100,'functional requirement','yêu cầu chức năng','adj + n','[{"en":"Each functional requirement must be tested before the launch.","vi":"Mỗi yêu cầu chức năng phải được kiểm thử trước khi ra mắt."},{"en":"The team documented every functional requirement of the system.","vi":"Nhóm đã ghi lại từng yêu cầu chức năng của hệ thống."},{"en":"A missing functional requirement can delay the whole project.","vi":"Thiếu một yêu cầu chức năng có thể làm chậm cả dự án."}]','[]',NULL,'/ˈfʌŋkʃənəl rɪˈkwaɪərmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4141,'colloc-6-01',101,'fundamental aspect','khía cạnh căn bản, cốt lõi','adj + n','[{"en":"Trust is a fundamental aspect of any successful partnership.","vi":"Niềm tin là một khía cạnh căn bản của bất kỳ quan hệ hợp tác nào."},{"en":"The essay overlooks a fundamental aspect of the problem.","vi":"Bài luận bỏ qua một khía cạnh cốt lõi của vấn đề."},{"en":"Memory is a fundamental aspect of human learning.","vi":"Trí nhớ là một khía cạnh căn bản của việc học ở con người."}]','[]',NULL,'/ˌfʌndəˈmentəl ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4142,'colloc-6-01',102,'fundamental assumption','giả định nền tảng','adj + n','[{"en":"The model rests on a fundamental assumption about human behavior.","vi":"Mô hình dựa trên một giả định nền tảng về hành vi con người."},{"en":"Critics challenged the fundamental assumption of the study.","vi":"Giới phê bình đã chất vấn giả định nền tảng của nghiên cứu."},{"en":"Every fundamental assumption should be stated clearly upfront.","vi":"Mỗi giả định nền tảng cần được nêu rõ ràng ngay từ đầu."}]','[]',NULL,'/ˌfʌndəˈmentəl əˈsʌmpʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4143,'colloc-6-01',103,'fundamental change','sự thay đổi căn bản','adj + n','[{"en":"The reform brought a fundamental change to the education system.","vi":"Cuộc cải cách đã mang lại sự thay đổi căn bản cho hệ thống giáo dục."},{"en":"Technology has caused a fundamental change in how we work.","vi":"Công nghệ đã tạo ra một thay đổi căn bản trong cách chúng ta làm việc."},{"en":"Such a fundamental change requires broad public support.","vi":"Một thay đổi căn bản như vậy cần sự ủng hộ rộng rãi của công chúng."}]','[]',NULL,'/ˌfʌndəˈmentəl tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4144,'colloc-6-01',104,'fundamental component','thành phần cốt lõi','adj + n','[{"en":"Feedback is a fundamental component of effective teaching.","vi":"Phản hồi là một thành phần cốt lõi của việc giảng dạy hiệu quả."},{"en":"Water is a fundamental component of every living cell.","vi":"Nước là một thành phần cốt lõi của mọi tế bào sống."},{"en":"Trust forms a fundamental component of stable economies.","vi":"Niềm tin tạo nên một thành phần cốt lõi của nền kinh tế ổn định."}]','[]',NULL,'/ˌfʌndəˈmentəl kəmˈpoʊnənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4145,'colloc-6-01',105,'fundamental difference','sự khác biệt căn bản','adj + n','[{"en":"There is a fundamental difference between the two approaches.","vi":"Có một sự khác biệt căn bản giữa hai cách tiếp cận."},{"en":"The study highlights a fundamental difference in cell structure.","vi":"Nghiên cứu làm nổi bật một khác biệt căn bản trong cấu trúc tế bào."},{"en":"A fundamental difference in values caused the disagreement.","vi":"Một khác biệt căn bản về giá trị đã gây ra sự bất đồng."}]','[]',NULL,'/ˌfʌndəˈmentəl ˈdɪfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4146,'colloc-6-01',106,'fundamental importance','tầm quan trọng căn bản','adj + n','[{"en":"Clean water is of fundamental importance to public health.","vi":"Nước sạch có tầm quan trọng căn bản đối với sức khỏe cộng đồng."},{"en":"These findings are of fundamental importance to the field.","vi":"Những phát hiện này có tầm quan trọng căn bản đối với ngành."},{"en":"Education is of fundamental importance to economic growth.","vi":"Giáo dục có tầm quan trọng căn bản đối với tăng trưởng kinh tế."}]','[]',NULL,'/ˌfʌndəˈmentəl ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4147,'colloc-6-01',107,'fundamental principle','nguyên tắc căn bản','adj + n','[{"en":"Equality before the law is a fundamental principle of democracy.","vi":"Bình đẳng trước pháp luật là một nguyên tắc căn bản của nền dân chủ."},{"en":"The experiment illustrates a fundamental principle of physics.","vi":"Thí nghiệm minh họa một nguyên tắc căn bản của vật lý."},{"en":"Respect for evidence is a fundamental principle of science.","vi":"Tôn trọng bằng chứng là một nguyên tắc căn bản của khoa học."}]','[]',NULL,'/ˌfʌndəˈmentəl ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4148,'colloc-6-01',108,'fundamental problem','vấn đề căn bản, cốt lõi','adj + n','[{"en":"The fundamental problem is a lack of reliable data.","vi":"Vấn đề căn bản là sự thiếu hụt dữ liệu đáng tin cậy."},{"en":"Critics argue the plan ignores the fundamental problem entirely.","vi":"Giới phê bình cho rằng kế hoạch hoàn toàn bỏ qua vấn đề cốt lõi."},{"en":"Solving the fundamental problem requires long-term investment.","vi":"Giải quyết vấn đề căn bản đòi hỏi đầu tư dài hạn."}]','[]',NULL,'/ˌfʌndəˈmentəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4149,'colloc-6-01',109,'fundamental question','câu hỏi căn bản, cốt lõi','adj + n','[{"en":"The study addresses a fundamental question about human memory.","vi":"Nghiên cứu giải quyết một câu hỏi căn bản về trí nhớ con người."},{"en":"A fundamental question remains: who should pay for this?","vi":"Một câu hỏi cốt lõi vẫn còn đó: ai sẽ chi trả cho việc này?"},{"en":"Philosophers have long debated this fundamental question.","vi":"Các triết gia từ lâu đã tranh luận về câu hỏi căn bản này."}]','[]',NULL,'/ˌfʌndəˈmentəl ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4150,'colloc-6-01',110,'fundamentally different','khác nhau về căn bản','adv + adj','[{"en":"The two theories are fundamentally different in their assumptions.","vi":"Hai lý thuyết khác nhau về căn bản trong các giả định của chúng."},{"en":"Online learning is fundamentally different from classroom teaching.","vi":"Học trực tuyến khác về căn bản so với giảng dạy trên lớp."},{"en":"Their conclusions were fundamentally different despite similar data.","vi":"Kết luận của họ khác nhau về căn bản dù dùng dữ liệu tương tự."}]','[]',NULL,'/ˌfʌndəˈmentəli ˈdɪfərənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4151,'colloc-6-01',111,'further analysis','sự phân tích thêm','adj + n','[{"en":"Further analysis is needed to confirm these preliminary results.","vi":"Cần phân tích thêm để xác nhận những kết quả sơ bộ này."},{"en":"Further analysis revealed a strong link between the variables.","vi":"Phân tích thêm cho thấy mối liên hệ chặt chẽ giữa các biến số."},{"en":"The data was set aside for further analysis next year.","vi":"Dữ liệu được giữ lại để phân tích thêm vào năm sau."}]','[]',NULL,'/ˈfɜːrðər əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4152,'colloc-6-01',112,'further consideration','sự cân nhắc thêm','adj + n','[{"en":"The proposal requires further consideration before any approval.","vi":"Đề xuất cần được cân nhắc thêm trước khi được phê duyệt."},{"en":"These factors deserve further consideration in future studies.","vi":"Những yếu tố này đáng được cân nhắc thêm trong các nghiên cứu sau."},{"en":"The committee postponed the decision for further consideration.","vi":"Ủy ban hoãn quyết định để cân nhắc thêm."}]','[]',NULL,'/ˈfɜːrðər kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4153,'colloc-6-01',113,'further development','sự phát triển thêm','adj + n','[{"en":"The prototype needs further development before it can be sold.","vi":"Bản mẫu cần được phát triển thêm trước khi có thể bán ra."},{"en":"Funding was secured for the further development of the vaccine.","vi":"Đã có kinh phí cho việc phát triển thêm loại vắc-xin này."},{"en":"These ideas offer scope for further development in later chapters.","vi":"Những ý tưởng này mở ra hướng phát triển thêm ở các chương sau."}]','[]',NULL,'/ˈfɜːrðər dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4154,'colloc-6-01',114,'further divided into','được chia nhỏ thêm thành','adv + vpp','[{"en":"Each category is further divided into three smaller subgroups.","vi":"Mỗi nhóm được chia nhỏ thêm thành ba phân nhóm nhỏ hơn."},{"en":"The sample was further divided into control and test groups.","vi":"Mẫu được chia nhỏ thêm thành nhóm đối chứng và nhóm thử nghiệm."},{"en":"The chapter is further divided into clearly labeled sections.","vi":"Chương này được chia nhỏ thêm thành các phần được dán nhãn rõ ràng."}]','[]',NULL,'/ˈfɜːrðər dɪˈvaɪdɪd ˈɪntə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4155,'colloc-6-01',115,'further evidence','bằng chứng bổ sung','adj + n','[{"en":"Further evidence is required to support this bold claim.","vi":"Cần bằng chứng bổ sung để hỗ trợ cho khẳng định táo bạo này."},{"en":"Recent fossils provide further evidence for the theory.","vi":"Các hóa thạch gần đây cung cấp bằng chứng bổ sung cho lý thuyết."},{"en":"The trial gathered further evidence of the drug''s safety.","vi":"Cuộc thử nghiệm đã thu thập thêm bằng chứng về độ an toàn của thuốc."}]','[]',NULL,'/ˈfɜːrðər ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4156,'colloc-6-01',116,'further explanation','lời giải thích thêm','adj + n','[{"en":"These terms require further explanation for the general reader.","vi":"Những thuật ngữ này cần được giải thích thêm cho độc giả phổ thông."},{"en":"The teacher offered further explanation after the lecture.","vi":"Giáo viên đưa ra lời giải thích thêm sau bài giảng."},{"en":"No further explanation was given for the sudden change.","vi":"Không có lời giải thích thêm nào cho sự thay đổi đột ngột."}]','[]',NULL,'/ˈfɜːrðər ˌekspləˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4157,'colloc-6-01',117,'further information','thông tin thêm','adj + n','[{"en":"For further information, please contact the admissions office.","vi":"Để biết thêm thông tin, vui lòng liên hệ phòng tuyển sinh."},{"en":"The appendix provides further information about the methodology.","vi":"Phụ lục cung cấp thông tin thêm về phương pháp luận."},{"en":"Further information is available on the project''s website.","vi":"Thông tin thêm có sẵn trên trang web của dự án."}]','[]',NULL,'/ˈfɜːrðər ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4158,'colloc-6-01',118,'further investigation','sự điều tra, tìm hiểu thêm','adj + n','[{"en":"These anomalies warrant further investigation by the research team.","vi":"Những bất thường này cần được nhóm nghiên cứu tìm hiểu thêm."},{"en":"The police are conducting further investigation into the case.","vi":"Cảnh sát đang tiến hành điều tra thêm về vụ việc."},{"en":"Further investigation may reveal the cause of the failure.","vi":"Việc tìm hiểu thêm có thể làm rõ nguyên nhân của sự cố."}]','[]',NULL,'/ˈfɜːrðər ɪnˌvestɪˈɡeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4159,'colloc-6-01',119,'further research','nghiên cứu thêm','adj + n','[{"en":"Further research is needed to confirm the link conclusively.","vi":"Cần nghiên cứu thêm để xác nhận mối liên hệ một cách chắc chắn."},{"en":"The paper suggests several directions for further research.","vi":"Bài báo gợi ý một số hướng cho nghiên cứu thêm."},{"en":"Further research could explore the long-term effects of the drug.","vi":"Nghiên cứu thêm có thể khám phá tác động dài hạn của loại thuốc."}]','[]',NULL,'/ˈfɜːrðər ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4160,'colloc-6-01',120,'further study','sự nghiên cứu, học tập thêm','adj + n','[{"en":"This topic clearly merits further study in future projects.","vi":"Chủ đề này rõ ràng xứng đáng được nghiên cứu thêm trong các dự án sau."},{"en":"Many graduates pursue further study at the master''s level.","vi":"Nhiều sinh viên tốt nghiệp theo học thêm ở bậc thạc sĩ."},{"en":"Further study is required to understand the full effects.","vi":"Cần nghiên cứu thêm để hiểu hết các tác động."}]','[]',NULL,'/ˈfɜːrðər ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4161,'colloc-6-01',121,'future development','sự phát triển trong tương lai','adj + n','[{"en":"The report outlines plans for the future development of the city.","vi":"Báo cáo phác thảo các kế hoạch phát triển thành phố trong tương lai."},{"en":"Investment today supports the future development of the region.","vi":"Đầu tư hôm nay hỗ trợ sự phát triển của khu vực trong tương lai."},{"en":"These findings will guide the future development of the product.","vi":"Những phát hiện này sẽ định hướng phát triển sản phẩm trong tương lai."}]','[]',NULL,'/ˈfjuːtʃər dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4162,'colloc-6-01',122,'future prospects','triển vọng tương lai','adj + n','[{"en":"A degree can greatly improve a graduate''s future prospects.","vi":"Một tấm bằng có thể cải thiện đáng kể triển vọng tương lai của sinh viên."},{"en":"The report assesses the future prospects of the industry.","vi":"Báo cáo đánh giá triển vọng tương lai của ngành công nghiệp."},{"en":"Economic uncertainty has dimmed the country''s future prospects.","vi":"Sự bất ổn kinh tế đã làm lu mờ triển vọng tương lai của đất nước."}]','[]',NULL,'/ˈfjuːtʃər ˈprɑːspekts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4163,'colloc-6-01',123,'future research','nghiên cứu trong tương lai','adj + n','[{"en":"Future research should examine a larger and more diverse sample.","vi":"Nghiên cứu trong tương lai nên xem xét một mẫu lớn và đa dạng hơn."},{"en":"The authors propose several questions for future research.","vi":"Các tác giả đề xuất một số câu hỏi cho nghiên cứu trong tương lai."},{"en":"Future research could test the model in other countries.","vi":"Nghiên cứu trong tương lai có thể kiểm chứng mô hình ở các nước khác."}]','[]',NULL,'/ˈfjuːtʃər ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4164,'colloc-6-01',124,'future study','nghiên cứu sau này','adj + n','[{"en":"A future study might explore the role of motivation here.","vi":"Một nghiên cứu sau này có thể khám phá vai trò của động lực ở đây."},{"en":"The findings provide a foundation for future study of the topic.","vi":"Những phát hiện này tạo nền tảng cho nghiên cứu sau này về chủ đề."},{"en":"Any future study should control for these confounding factors.","vi":"Mọi nghiên cứu sau này nên kiểm soát các yếu tố gây nhiễu này."}]','[]',NULL,'/ˈfjuːtʃər ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4165,'colloc-6-01',125,'gain access to','có được quyền truy cập vào','v + n','[{"en":"Students can gain access to the database with their library card.","vi":"Sinh viên có thể truy cập cơ sở dữ liệu bằng thẻ thư viện của mình."},{"en":"Hackers tried to gain access to the company''s private servers.","vi":"Tin tặc đã cố truy cập vào các máy chủ riêng của công ty."},{"en":"Researchers struggled to gain access to the remote region.","vi":"Các nhà nghiên cứu chật vật để tiếp cận được vùng xa xôi này."}]','[]',NULL,'/ɡeɪn ˈækses tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4166,'colloc-6-01',126,'gain information','thu được thông tin','v + n','[{"en":"Interviews help researchers gain information about people''s habits.","vi":"Phỏng vấn giúp nhà nghiên cứu thu được thông tin về thói quen của mọi người."},{"en":"We gain information about the past by studying old documents.","vi":"Chúng ta thu được thông tin về quá khứ qua việc nghiên cứu tài liệu cũ."},{"en":"Surveys are a quick way to gain information from many people.","vi":"Khảo sát là cách nhanh để thu được thông tin từ nhiều người."}]','[]',NULL,'/ɡeɪn ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4167,'colloc-6-01',127,'gain insight into','có được hiểu biết sâu sắc về','v + n','[{"en":"The study helps us gain insight into consumer decision-making.","vi":"Nghiên cứu giúp ta hiểu sâu hơn về cách người tiêu dùng ra quyết định."},{"en":"Fieldwork allowed her to gain insight into local traditions.","vi":"Công tác thực địa giúp cô hiểu sâu sắc về phong tục địa phương."},{"en":"Interviews gain insight into how patients experience illness.","vi":"Phỏng vấn giúp hiểu sâu về cách bệnh nhân trải nghiệm bệnh tật."}]','[]',NULL,'/ɡeɪn ˈɪnsaɪt ˈɪntə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4168,'colloc-6-01',128,'gather data','thu thập dữ liệu','v + n','[{"en":"The team used surveys to gather data from rural households.","vi":"Nhóm dùng khảo sát để thu thập dữ liệu từ các hộ gia đình nông thôn."},{"en":"Sensors gather data on temperature throughout the day.","vi":"Các cảm biến thu thập dữ liệu về nhiệt độ suốt cả ngày."},{"en":"It took six months to gather data for the study.","vi":"Phải mất sáu tháng để thu thập dữ liệu cho nghiên cứu."}]','[]',NULL,'/ˈɡæðər ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4169,'colloc-6-01',129,'gather information','thu thập thông tin','v + n','[{"en":"Journalists gather information from a wide range of sources.","vi":"Nhà báo thu thập thông tin từ nhiều nguồn khác nhau."},{"en":"The committee will gather information before making a decision.","vi":"Ủy ban sẽ thu thập thông tin trước khi đưa ra quyết định."},{"en":"Online tools make it easier to gather information quickly.","vi":"Các công cụ trực tuyến giúp thu thập thông tin nhanh chóng hơn."}]','[]',NULL,'/ˈɡæðər ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4170,'colloc-6-01',130,'gender equality','bình đẳng giới','n + n','[{"en":"The policy aims to promote gender equality in the workplace.","vi":"Chính sách nhằm thúc đẩy bình đẳng giới tại nơi làm việc."},{"en":"Many countries have made progress toward gender equality.","vi":"Nhiều quốc gia đã đạt tiến bộ trong việc hướng tới bình đẳng giới."},{"en":"Education plays a key role in achieving gender equality.","vi":"Giáo dục đóng vai trò quan trọng trong việc đạt bình đẳng giới."}]','[]',NULL,'/ˈdʒendər ɪˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4171,'colloc-6-01',131,'gender stereotype','định kiến giới','n + n','[{"en":"Advertisements often reinforce a common gender stereotype.","vi":"Quảng cáo thường củng cố một định kiến giới phổ biến."},{"en":"The study examined how a gender stereotype affects career choice.","vi":"Nghiên cứu xem xét cách định kiến giới ảnh hưởng đến lựa chọn nghề nghiệp."},{"en":"Teachers should avoid promoting any gender stereotype in class.","vi":"Giáo viên nên tránh cổ xúy bất kỳ định kiến giới nào trong lớp."}]','[]',NULL,'/ˈdʒendər ˈsteriəˌtaɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4172,'colloc-6-01',132,'general agreement','sự nhất trí chung','adj + n','[{"en":"There is general agreement that the policy needs reform.","vi":"Có sự nhất trí chung rằng chính sách này cần được cải cách."},{"en":"The experts reached general agreement on the main causes.","vi":"Các chuyên gia đã đạt được sự nhất trí chung về các nguyên nhân chính."},{"en":"Despite some debate, general agreement emerged on the goals.","vi":"Dù còn tranh luận, sự nhất trí chung đã hình thành về các mục tiêu."}]','[]',NULL,'/ˈdʒenərəl əˈɡriːmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4173,'colloc-6-01',133,'general approach','cách tiếp cận chung','adj + n','[{"en":"The chapter outlines a general approach to solving the problem.","vi":"Chương này phác thảo một cách tiếp cận chung để giải quyết vấn đề."},{"en":"Their general approach combines theory with practical examples.","vi":"Cách tiếp cận chung của họ kết hợp lý thuyết với ví dụ thực tế."},{"en":"A general approach may not suit every individual case.","vi":"Một cách tiếp cận chung có thể không phù hợp với mọi trường hợp."}]','[]',NULL,'/ˈdʒenərəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4174,'colloc-6-01',134,'general argument','lập luận tổng quát','adj + n','[{"en":"The book''s general argument is that culture shapes economics.","vi":"Lập luận tổng quát của cuốn sách là văn hóa định hình kinh tế."},{"en":"Her general argument holds even when the details differ.","vi":"Lập luận tổng quát của bà vẫn đúng ngay cả khi chi tiết khác nhau."},{"en":"Critics accepted the general argument but questioned the evidence.","vi":"Giới phê bình chấp nhận lập luận tổng quát nhưng nghi ngờ bằng chứng."}]','[]',NULL,'/ˈdʒenərəl ˈɑːrɡjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4175,'colloc-6-01',135,'general aspect','khía cạnh chung','adj + n','[{"en":"The lecture covered a general aspect of climate science.","vi":"Bài giảng đề cập đến một khía cạnh chung của khoa học khí hậu."},{"en":"We start with a general aspect before examining the details.","vi":"Chúng ta bắt đầu với một khía cạnh chung trước khi xem xét chi tiết."},{"en":"This general aspect applies across many different cultures.","vi":"Khía cạnh chung này áp dụng cho nhiều nền văn hóa khác nhau."}]','[]',NULL,'/ˈdʒenərəl ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4176,'colloc-6-01',136,'general category','loại chung, hạng mục chung','adj + n','[{"en":"These responses fall into one broad general category.","vi":"Những phản hồi này thuộc về một loại chung rộng lớn."},{"en":"The survey grouped answers into a few general categories.","vi":"Khảo sát nhóm các câu trả lời vào vài hạng mục chung."},{"en":"Each general category is defined clearly in the methods section.","vi":"Mỗi loại chung được định nghĩa rõ ràng trong phần phương pháp."}]','[]',NULL,'/ˈdʒenərəl ˈkætəˌɡɔːri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4177,'colloc-6-01',137,'general conclusion','kết luận chung','adj + n','[{"en":"The general conclusion is that early intervention works best.","vi":"Kết luận chung là can thiệp sớm mang lại hiệu quả tốt nhất."},{"en":"From these results we can draw a clear general conclusion.","vi":"Từ những kết quả này, ta có thể rút ra một kết luận chung rõ ràng."},{"en":"The general conclusion holds despite a few exceptions.","vi":"Kết luận chung vẫn đúng dù có một vài ngoại lệ."}]','[]',NULL,'/ˈdʒenərəl kənˈkluːʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4178,'colloc-6-01',138,'general consensus','sự đồng thuận chung','adj + n','[{"en":"The general consensus among scientists is that the data is solid.","vi":"Sự đồng thuận chung giữa các nhà khoa học là dữ liệu đáng tin cậy."},{"en":"There is a general consensus that the reform improved schools.","vi":"Có sự đồng thuận chung rằng cải cách đã cải thiện trường học."},{"en":"The committee reached a general consensus after long debate.","vi":"Ủy ban đạt được sự đồng thuận chung sau cuộc tranh luận dài."}]','[]',NULL,'/ˈdʒenərəl kənˈsensəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4179,'colloc-6-01',139,'general definition','định nghĩa chung','adj + n','[{"en":"The author begins with a general definition of culture.","vi":"Tác giả bắt đầu bằng một định nghĩa chung về văn hóa."},{"en":"A general definition helps readers follow the argument.","vi":"Một định nghĩa chung giúp người đọc theo dõi lập luận."},{"en":"We need a general definition before discussing specific cases.","vi":"Ta cần một định nghĩa chung trước khi bàn về các trường hợp cụ thể."}]','[]',NULL,'/ˈdʒenərəl ˌdefɪˈnɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4180,'colloc-6-01',140,'general feature','đặc điểm chung','adj + n','[{"en":"Repetition is a general feature of early childhood learning.","vi":"Sự lặp lại là một đặc điểm chung của việc học ở trẻ nhỏ."},{"en":"The report describes a general feature shared by all the cases.","vi":"Báo cáo mô tả một đặc điểm chung của tất cả các trường hợp."},{"en":"This general feature appears across many language families.","vi":"Đặc điểm chung này xuất hiện ở nhiều ngữ hệ khác nhau."}]','[]',NULL,'/ˈdʒenərəl ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4181,'colloc-6-01',141,'general formula','công thức tổng quát','adj + n','[{"en":"The chapter derives a general formula for the area of a polygon.","vi":"Chương này suy ra một công thức tổng quát cho diện tích đa giác."},{"en":"A general formula lets us solve many similar problems quickly.","vi":"Một công thức tổng quát giúp ta giải nhanh nhiều bài tương tự."},{"en":"From the examples, students develop a general formula themselves.","vi":"Từ các ví dụ, sinh viên tự xây dựng một công thức tổng quát."}]','[]',NULL,'/ˈdʒenərəl ˈfɔːrmjələ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4182,'colloc-6-01',142,'general overview','cái nhìn tổng quan chung','adj + n','[{"en":"The introduction gives a general overview of the topic.","vi":"Phần mở đầu đưa ra cái nhìn tổng quan chung về chủ đề."},{"en":"This section offers a general overview before the detailed analysis.","vi":"Phần này cung cấp cái nhìn tổng quan trước khi phân tích chi tiết."},{"en":"She began the talk with a general overview of the findings.","vi":"Cô bắt đầu bài nói bằng cái nhìn tổng quan về các phát hiện."}]','[]',NULL,'/ˈdʒenərəl ˈoʊvərˌvjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4183,'colloc-6-01',143,'general principle','nguyên tắc chung','adj + n','[{"en":"The same general principle applies to most chemical reactions.","vi":"Cùng một nguyên tắc chung áp dụng cho hầu hết các phản ứng hóa học."},{"en":"As a general principle, claims must be supported by evidence.","vi":"Theo nguyên tắc chung, mọi khẳng định phải có bằng chứng hỗ trợ."},{"en":"Students should grasp the general principle before the details.","vi":"Sinh viên nên nắm nguyên tắc chung trước khi học chi tiết."}]','[]',NULL,'/ˈdʒenərəl ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4184,'colloc-6-01',144,'general statement','phát biểu chung chung','adj + n','[{"en":"Avoid a vague general statement and provide specific evidence.","vi":"Tránh phát biểu chung chung mơ hồ và hãy đưa ra bằng chứng cụ thể."},{"en":"The essay opens with a general statement about modern cities.","vi":"Bài luận mở đầu bằng một phát biểu chung về các thành phố hiện đại."},{"en":"A general statement should be narrowed into a clear thesis.","vi":"Một phát biểu chung nên được thu hẹp thành một luận điểm rõ ràng."}]','[]',NULL,'/ˈdʒenərəl ˈsteɪtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4185,'colloc-6-01',145,'general tendency','xu hướng chung','adj + n','[{"en":"The data shows a general tendency toward higher prices.","vi":"Dữ liệu cho thấy một xu hướng chung là giá tăng cao hơn."},{"en":"There is a general tendency for cities to expand outward.","vi":"Có một xu hướng chung là các thành phố mở rộng ra bên ngoài."},{"en":"The study identified a general tendency among younger voters.","vi":"Nghiên cứu xác định một xu hướng chung ở các cử tri trẻ tuổi."}]','[]',NULL,'/ˈdʒenərəl ˈtendənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4186,'colloc-6-01',146,'general theory','lý thuyết tổng quát','adj + n','[{"en":"Einstein''s general theory transformed our view of gravity.","vi":"Lý thuyết tổng quát của Einstein đã thay đổi quan niệm về trọng lực."},{"en":"The book proposes a general theory of social change.","vi":"Cuốn sách đề xuất một lý thuyết tổng quát về biến đổi xã hội."},{"en":"A general theory must account for a wide range of cases.","vi":"Một lý thuyết tổng quát phải giải thích được nhiều trường hợp khác nhau."}]','[]',NULL,'/ˈdʒenərəl ˈθɪəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4187,'colloc-6-01',147,'general trend','xu thế chung','adj + n','[{"en":"The graph reveals a general trend of rising temperatures.","vi":"Biểu đồ cho thấy một xu thế chung là nhiệt độ ngày càng tăng."},{"en":"Despite yearly variation, the general trend is upward.","vi":"Dù dao động theo năm, xu thế chung vẫn là đi lên."},{"en":"The general trend points to greater use of renewable energy.","vi":"Xu thế chung cho thấy việc sử dụng năng lượng tái tạo nhiều hơn."}]','[]',NULL,'/ˈdʒenərəl trend/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4188,'colloc-6-01',148,'generally accepted','được công nhận rộng rãi','adv + vpp','[{"en":"It is generally accepted that exercise benefits mental health.","vi":"Người ta công nhận rộng rãi rằng tập thể dục có lợi cho sức khỏe tinh thần."},{"en":"These methods are generally accepted in clinical research.","vi":"Những phương pháp này được công nhận rộng rãi trong nghiên cứu lâm sàng."},{"en":"The theory is now generally accepted by most economists.","vi":"Lý thuyết này giờ đây được hầu hết các nhà kinh tế công nhận."}]','[]',NULL,'/ˈdʒenərəli əkˈseptɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4189,'colloc-6-01',149,'generally agree','nhìn chung đồng ý','adv + v','[{"en":"Experts generally agree that the policy reduced pollution.","vi":"Các chuyên gia nhìn chung đồng ý rằng chính sách đã giảm ô nhiễm."},{"en":"Historians generally agree on the main causes of the war.","vi":"Các sử gia nhìn chung đồng ý về các nguyên nhân chính của cuộc chiến."},{"en":"Researchers generally agree that more data is needed.","vi":"Các nhà nghiên cứu nhìn chung đồng ý rằng cần thêm dữ liệu."}]','[]',NULL,'/ˈdʒenərəli əˈɡriː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4190,'colloc-6-01',150,'generally assumed','thường được cho rằng','adv + vpp','[{"en":"It is generally assumed that prices will rise over time.","vi":"Người ta thường cho rằng giá sẽ tăng theo thời gian."},{"en":"It was generally assumed the experiment would fail.","vi":"Người ta thường cho rằng thí nghiệm sẽ thất bại."},{"en":"These assumptions are generally assumed without much evidence.","vi":"Những giả định này thường được cho là đúng mà thiếu bằng chứng."}]','[]',NULL,'/ˈdʒenərəli əˈsuːmd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4191,'colloc-7-01',1,'generally considered','thường được xem là','adv + vpp','[{"en":"This is generally considered the most reliable method available.","vi":"Đây thường được xem là phương pháp đáng tin cậy nhất hiện có."},{"en":"She is generally considered an expert in her field.","vi":"Bà thường được xem là một chuyên gia trong lĩnh vực của mình."},{"en":"The novel is generally considered a masterpiece of the era.","vi":"Cuốn tiểu thuyết thường được xem là một kiệt tác của thời đại."}]','[]',NULL,'/ˈdʒenərəli kənˈsɪdərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4192,'colloc-7-01',2,'generally found','thường thấy, nhìn chung gặp','adv + vpp','[{"en":"These minerals are generally found near volcanic regions.","vi":"Những khoáng chất này thường thấy gần các vùng núi lửa."},{"en":"Such behavior is generally found in highly social animals.","vi":"Hành vi như vậy nhìn chung gặp ở các loài vật có tính xã hội cao."},{"en":"The pattern is generally found across most age groups.","vi":"Mô hình này thường thấy ở hầu hết các nhóm tuổi."}]','[]',NULL,'/ˈdʒenərəli faʊnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4193,'colloc-7-01',3,'generally known as','thường được gọi là','adv + vpp','[{"en":"The condition is generally known as the common cold.","vi":"Tình trạng này thường được gọi là cảm lạnh thông thường."},{"en":"This region is generally known as the country''s industrial heart.","vi":"Vùng này thường được gọi là trái tim công nghiệp của đất nước."},{"en":"The process is generally known as natural selection.","vi":"Quá trình này thường được gọi là chọn lọc tự nhiên."}]','[]',NULL,'/ˈdʒenərəli noʊn əz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4194,'colloc-7-01',4,'genetic variation','sự biến dị di truyền','adj + n','[{"en":"Genetic variation helps a population adapt to changing conditions.","vi":"Sự biến dị di truyền giúp quần thể thích nghi với điều kiện thay đổi."},{"en":"The study measured genetic variation across several populations.","vi":"Nghiên cứu đo lường sự biến dị di truyền giữa nhiều quần thể."},{"en":"Low genetic variation can make a species vulnerable to disease.","vi":"Biến dị di truyền thấp có thể khiến loài dễ tổn thương trước bệnh tật."}]','[]',NULL,'/dʒəˈnetɪk ˌveriˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4195,'colloc-7-01',5,'geographic al area','khu vực địa lý','adj + n','[{"en":"The survey covered a wide geographic al area of the country.","vi":"Cuộc khảo sát bao phủ một khu vực địa lý rộng lớn của đất nước."},{"en":"Rainfall varies greatly from one geographic al area to another.","vi":"Lượng mưa khác nhau rất nhiều giữa các khu vực địa lý."},{"en":"The disease was limited to a small geographic al area.","vi":"Dịch bệnh chỉ giới hạn trong một khu vực địa lý nhỏ."}]','[]',NULL,'/ˌdʒiːəˈɡræfɪkəl ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4196,'colloc-7-01',6,'geographic al distribution','sự phân bố theo địa lý','adj + n','[{"en":"The map shows the geographic al distribution of the species.","vi":"Bản đồ cho thấy sự phân bố theo địa lý của loài này."},{"en":"Researchers studied the geographic al distribution of the disease.","vi":"Các nhà nghiên cứu nghiên cứu sự phân bố theo địa lý của dịch bệnh."},{"en":"The geographic al distribution of wealth remains highly uneven.","vi":"Sự phân bố của cải theo địa lý vẫn rất không đồng đều."}]','[]',NULL,'/ˌdʒiːəˈɡræfɪkəl ˌdɪstrɪˈbjuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4197,'colloc-7-01',7,'geographic al location','vị trí địa lý','adj + n','[{"en":"The city''s geographic al location made it a major trading hub.","vi":"Vị trí địa lý của thành phố biến nó thành một trung tâm thương mại lớn."},{"en":"Climate depends heavily on a region''s geographic al location.","vi":"Khí hậu phụ thuộc nhiều vào vị trí địa lý của một vùng."},{"en":"Its geographic al location gives the port a strategic advantage.","vi":"Vị trí địa lý mang lại cho cảng này một lợi thế chiến lược."}]','[]',NULL,'/ˌdʒiːəˈɡræfɪkəl loʊˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4198,'colloc-7-01',8,'get involved with','tham gia vào, dính líu đến','v + adj','[{"en":"Students are encouraged to get involved with campus activities.","vi":"Sinh viên được khuyến khích tham gia vào các hoạt động trong trường."},{"en":"She wanted to get involved with the local research project.","vi":"Cô muốn tham gia vào dự án nghiên cứu của địa phương."},{"en":"Volunteers get involved with the program to gain experience.","vi":"Các tình nguyện viên tham gia vào chương trình để có kinh nghiệm."}]','[]',NULL,'/ɡet ɪnˈvɑːlvd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4199,'colloc-7-01',9,'give access to','cấp quyền truy cập, cho tiếp cận','v + n','[{"en":"The membership gives access to thousands of academic articles.","vi":"Tư cách thành viên cho phép truy cập hàng nghìn bài báo học thuật."},{"en":"The new bridge gives access to remote mountain villages.","vi":"Cây cầu mới giúp tiếp cận các bản làng vùng núi xa xôi."},{"en":"The pass gives access to all areas of the conference.","vi":"Thẻ vào cổng cho phép tiếp cận mọi khu vực của hội nghị."}]','[]',NULL,'/ɡɪv ˈækses tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4200,'colloc-7-01',10,'give consent','đưa ra sự đồng ý, chấp thuận','v + n','[{"en":"Patients must give consent before any procedure begins.","vi":"Bệnh nhân phải đưa ra sự đồng ý trước khi bắt đầu bất kỳ thủ thuật nào."},{"en":"Participants gave consent after reading the information sheet.","vi":"Người tham gia đã chấp thuận sau khi đọc bản thông tin."},{"en":"Parents must give consent for children to join the study.","vi":"Phụ huynh phải đồng ý để trẻ em tham gia vào nghiên cứu."}]','[]',NULL,'/ɡɪv kənˈsent/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4201,'colloc-7-01',11,'give consideration','cân nhắc, xem xét kỹ','v + n','[{"en":"The committee will give consideration to every proposal before deciding.","vi":"Ủy ban sẽ cân nhắc mọi đề xuất trước khi quyết định."},{"en":"Please give consideration to the safety risks involved here.","vi":"Hãy xem xét kỹ các rủi ro an toàn liên quan ở đây."},{"en":"Researchers must give consideration to ethical issues in their studies.","vi":"Các nhà nghiên cứu phải cân nhắc các vấn đề đạo đức trong nghiên cứu."}]','[]',NULL,'/ɡɪv kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4202,'colloc-7-01',12,'give emphasis','nhấn mạnh, chú trọng','v + n','[{"en":"The teacher gives emphasis to grammar in every writing lesson.","vi":"Giáo viên chú trọng ngữ pháp trong mỗi bài học viết."},{"en":"This report gives emphasis to the long-term economic effects.","vi":"Báo cáo này nhấn mạnh các tác động kinh tế dài hạn."},{"en":"Modern programs give emphasis to practical skills over theory.","vi":"Các chương trình hiện đại chú trọng kỹ năng thực hành hơn lý thuyết."}]','[]',NULL,'/ɡɪv ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4203,'colloc-7-01',13,'give evidence','đưa ra bằng chứng, làm chứng','v + n','[{"en":"The witness agreed to give evidence at the trial tomorrow.","vi":"Nhân chứng đồng ý làm chứng tại phiên tòa ngày mai."},{"en":"These experiments give evidence that the theory is correct.","vi":"Các thí nghiệm này đưa ra bằng chứng rằng lý thuyết là đúng."},{"en":"Students must give evidence to support each claim they make.","vi":"Sinh viên phải đưa ra bằng chứng cho mỗi luận điểm họ nêu."}]','[]',NULL,'/ɡɪv ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4204,'colloc-7-01',14,'give feedback','đưa ra phản hồi, nhận xét','v + n','[{"en":"The tutor will give feedback on your essay by Friday.","vi":"Gia sư sẽ đưa ra phản hồi về bài luận của bạn trước thứ Sáu."},{"en":"Managers should give feedback that is clear and constructive.","vi":"Quản lý nên đưa ra phản hồi rõ ràng và mang tính xây dựng."},{"en":"Peers give feedback to each other during the workshop sessions.","vi":"Các bạn học đưa ra nhận xét cho nhau trong các buổi hội thảo."}]','[]',NULL,'/ɡɪv ˈfiːdbæk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4205,'colloc-7-01',15,'give priority to','ưu tiên cho','v + n','[{"en":"The hospital gives priority to patients with serious conditions.","vi":"Bệnh viện ưu tiên cho những bệnh nhân có tình trạng nghiêm trọng."},{"en":"We should give priority to reducing pollution in cities.","vi":"Chúng ta nên ưu tiên cho việc giảm ô nhiễm ở các thành phố."},{"en":"The policy gives priority to families with low incomes.","vi":"Chính sách ưu tiên cho các gia đình có thu nhập thấp."}]','[]',NULL,'/ɡɪv praɪˈɔːrəti tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4206,'colloc-7-01',16,'give guidance','đưa ra hướng dẫn, chỉ dẫn','v + n','[{"en":"The advisor gives guidance to students choosing their courses.","vi":"Cố vấn đưa ra hướng dẫn cho sinh viên đang chọn môn học."},{"en":"This handbook gives guidance on writing a research proposal.","vi":"Sổ tay này đưa ra hướng dẫn về cách viết đề cương nghiên cứu."},{"en":"Experienced staff give guidance to new employees every week.","vi":"Nhân viên giàu kinh nghiệm chỉ dẫn cho người mới mỗi tuần."}]','[]',NULL,'/ɡɪv ˈɡaɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4207,'colloc-7-01',17,'give information','cung cấp thông tin','v + n','[{"en":"The website gives information about visa rules for travelers.","vi":"Trang web cung cấp thông tin về quy định thị thực cho khách du lịch."},{"en":"Please give information about your previous work experience.","vi":"Vui lòng cung cấp thông tin về kinh nghiệm làm việc trước đây của bạn."},{"en":"The survey gives information on how customers use the product.","vi":"Cuộc khảo sát cung cấp thông tin về cách khách hàng dùng sản phẩm."}]','[]',NULL,'/ɡɪv ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4208,'colloc-7-01',18,'give insight into','giúp hiểu sâu về, cho cái nhìn sâu sắc về','v + n','[{"en":"The interviews give insight into how teenagers use social media.","vi":"Các cuộc phỏng vấn giúp hiểu sâu về cách thanh thiếu niên dùng mạng xã hội."},{"en":"Her diary gives insight into life during the war.","vi":"Nhật ký của cô cho cái nhìn sâu sắc về cuộc sống thời chiến."},{"en":"These results give insight into the causes of the problem.","vi":"Những kết quả này giúp hiểu sâu về nguyên nhân của vấn đề."}]','[]',NULL,'/ɡɪv ˈɪnsaɪt ˈɪntə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4209,'colloc-7-01',19,'give a presentation','thuyết trình, trình bày','v + n','[{"en":"Each student must give a presentation at the end of term.","vi":"Mỗi sinh viên phải thuyết trình vào cuối học kỳ."},{"en":"She will give a presentation on renewable energy next week.","vi":"Cô ấy sẽ thuyết trình về năng lượng tái tạo vào tuần tới."},{"en":"The manager gave a presentation about the new sales strategy.","vi":"Quản lý đã trình bày về chiến lược bán hàng mới."}]','[]',NULL,'/ɡɪv ə ˌprezənˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4210,'colloc-7-01',20,'give an explanation','đưa ra lời giải thích','v + n','[{"en":"The author gives an explanation for the unexpected results.","vi":"Tác giả đưa ra lời giải thích cho những kết quả bất ngờ."},{"en":"Can you give an explanation of how this machine works?","vi":"Bạn có thể giải thích máy này hoạt động thế nào không?"},{"en":"The teacher gave an explanation that everyone could understand.","vi":"Giáo viên đưa ra lời giải thích mà ai cũng có thể hiểu."}]','[]',NULL,'/ɡɪv ən ˌekspləˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4211,'colloc-7-01',21,'give an indication of','cho thấy dấu hiệu về, biểu thị','v + n','[{"en":"The early data gives an indication of future market trends.","vi":"Dữ liệu ban đầu cho thấy dấu hiệu về xu hướng thị trường tương lai."},{"en":"His tone gave an indication of how serious the matter was.","vi":"Giọng điệu của anh biểu thị mức độ nghiêm trọng của vấn đề."},{"en":"These figures give an indication of the company''s overall health.","vi":"Những con số này cho thấy dấu hiệu về tình hình chung của công ty."}]','[]',NULL,'/ɡɪv ən ˌɪndɪˈkeɪʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4212,'colloc-7-01',22,'give an overview of','đưa ra cái nhìn tổng quan về','v + n','[{"en":"The first chapter gives an overview of the whole subject.","vi":"Chương đầu đưa ra cái nhìn tổng quan về toàn bộ chủ đề."},{"en":"She gave an overview of the project before the discussion.","vi":"Cô ấy đưa ra cái nhìn tổng quan về dự án trước khi thảo luận."},{"en":"This article gives an overview of recent climate research.","vi":"Bài viết này đưa ra cái nhìn tổng quan về nghiên cứu khí hậu gần đây."}]','[]',NULL,'/ɡɪv ən ˈoʊvərvjuː əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4213,'colloc-7-01',23,'give somebody an impression','tạo cho ai đó ấn tượng','v + n','[{"en":"The opening scene gives the reader an impression of danger.","vi":"Cảnh mở đầu tạo cho người đọc ấn tượng về sự nguy hiểm."},{"en":"His confident speech gave us an impression of real expertise.","vi":"Bài phát biểu tự tin của anh tạo cho chúng tôi ấn tượng về sự chuyên môn."},{"en":"The bright office gave visitors an impression of success.","vi":"Văn phòng sáng sủa tạo cho khách tham quan ấn tượng về sự thành công."}]','[]',NULL,'/ɡɪv ˈsʌmbɑːdi ən ɪmˈpreʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4214,'colloc-7-01',24,'give somebody treatment','điều trị cho ai đó','v + n','[{"en":"The doctors gave the patient treatment as soon as possible.","vi":"Các bác sĩ điều trị cho bệnh nhân càng sớm càng tốt."},{"en":"Nurses give every child treatment with great care here.","vi":"Các y tá điều trị cho từng đứa trẻ rất cẩn thận ở đây."},{"en":"The clinic gives poorer families treatment at no cost.","vi":"Phòng khám điều trị cho các gia đình nghèo hơn miễn phí."}]','[]',NULL,'/ɡɪv ˈsʌmbɑːdi ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4215,'colloc-7-01',25,'given information','thông tin đã cho, thông tin sẵn có','adj + n','[{"en":"Use the given information to calculate the final answer.","vi":"Hãy dùng thông tin đã cho để tính ra đáp án cuối cùng."},{"en":"The given information was not enough to solve the case.","vi":"Thông tin sẵn có không đủ để giải quyết vụ việc."},{"en":"Students must analyze the given information before answering.","vi":"Sinh viên phải phân tích thông tin đã cho trước khi trả lời."}]','[]',NULL,'/ˈɡɪvən ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4216,'colloc-7-01',26,'given period','khoảng thời gian nhất định','adj + n','[{"en":"The chart shows sales during a given period of time.","vi":"Biểu đồ cho thấy doanh số trong một khoảng thời gian nhất định."},{"en":"Within any given period, prices can rise or fall.","vi":"Trong bất kỳ khoảng thời gian nhất định nào, giá có thể tăng hoặc giảm."},{"en":"We measured rainfall over a given period of six months.","vi":"Chúng tôi đo lượng mưa trong khoảng thời gian sáu tháng nhất định."}]','[]',NULL,'/ˈɡɪvən ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4217,'colloc-7-01',27,'global capitalism','chủ nghĩa tư bản toàn cầu','adj + n','[{"en":"Global capitalism has reshaped how goods are produced worldwide.","vi":"Chủ nghĩa tư bản toàn cầu đã định hình lại cách hàng hóa được sản xuất."},{"en":"Critics argue that global capitalism widens the gap between nations.","vi":"Người phê bình cho rằng chủ nghĩa tư bản toàn cầu nới rộng khoảng cách giữa các quốc gia."},{"en":"The course examines the rise of global capitalism after 1980.","vi":"Khóa học xem xét sự trỗi dậy của chủ nghĩa tư bản toàn cầu sau năm 1980."}]','[]',NULL,'/ˈɡloʊbəl ˈkæpɪtəlɪzəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4218,'colloc-7-01',28,'global context','bối cảnh toàn cầu','adj + n','[{"en":"We must understand this issue within a global context.","vi":"Chúng ta phải hiểu vấn đề này trong bối cảnh toàn cầu."},{"en":"In a global context, education standards vary widely between countries.","vi":"Trong bối cảnh toàn cầu, tiêu chuẩn giáo dục khác nhau nhiều giữa các nước."},{"en":"The author places local events in a broader global context.","vi":"Tác giả đặt các sự kiện địa phương vào bối cảnh toàn cầu rộng hơn."}]','[]',NULL,'/ˈɡloʊbəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4219,'colloc-7-01',29,'global culture','văn hóa toàn cầu','adj + n','[{"en":"The internet has helped create a shared global culture.","vi":"Internet đã giúp tạo nên một nền văn hóa toàn cầu chung."},{"en":"Some fear that global culture is erasing local traditions.","vi":"Một số người lo rằng văn hóa toàn cầu đang xóa bỏ truyền thống địa phương."},{"en":"Music and films spread global culture across many borders.","vi":"Âm nhạc và phim ảnh lan truyền văn hóa toàn cầu qua nhiều biên giới."}]','[]',NULL,'/ˈɡloʊbəl ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4220,'colloc-7-01',30,'global economy','nền kinh tế toàn cầu','adj + n','[{"en":"Rising oil prices affect the entire global economy quickly.","vi":"Giá dầu tăng ảnh hưởng nhanh đến toàn bộ nền kinh tế toàn cầu."},{"en":"The global economy slowed during the recent financial crisis.","vi":"Nền kinh tế toàn cầu chậm lại trong cuộc khủng hoảng tài chính gần đây."},{"en":"Many countries depend on each other in the global economy.","vi":"Nhiều quốc gia phụ thuộc lẫn nhau trong nền kinh tế toàn cầu."}]','[]',NULL,'/ˈɡloʊbəl ɪˈkɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4221,'colloc-7-01',31,'global issue','vấn đề toàn cầu','adj + n','[{"en":"Climate change is a global issue affecting every nation.","vi":"Biến đổi khí hậu là một vấn đề toàn cầu ảnh hưởng đến mọi quốc gia."},{"en":"Poverty remains a serious global issue despite economic growth.","vi":"Nghèo đói vẫn là một vấn đề toàn cầu nghiêm trọng dù kinh tế tăng trưởng."},{"en":"The conference focused on global issues such as disease and hunger.","vi":"Hội nghị tập trung vào các vấn đề toàn cầu như bệnh tật và nạn đói."}]','[]',NULL,'/ˈɡloʊbəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4222,'colloc-7-01',32,'global market','thị trường toàn cầu','adj + n','[{"en":"The company sells its products in the global market today.","vi":"Công ty bán sản phẩm của mình trên thị trường toàn cầu hiện nay."},{"en":"Competition in the global market keeps prices relatively low.","vi":"Sự cạnh tranh trên thị trường toàn cầu giữ giá tương đối thấp."},{"en":"Small firms struggle to enter the global market alone.","vi":"Các doanh nghiệp nhỏ khó tự mình thâm nhập thị trường toàn cầu."}]','[]',NULL,'/ˈɡloʊbəl ˈmɑːrkət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4223,'colloc-7-01',33,'global marketplace','thương trường toàn cầu','adj + n','[{"en":"Companies must innovate to survive in the global marketplace.","vi":"Các công ty phải đổi mới để tồn tại trên thương trường toàn cầu."},{"en":"The internet connects buyers and sellers in the global marketplace.","vi":"Internet kết nối người mua và người bán trên thương trường toàn cầu."},{"en":"Brand reputation matters greatly in the global marketplace.","vi":"Uy tín thương hiệu rất quan trọng trên thương trường toàn cầu."}]','[]',NULL,'/ˈɡloʊbəl ˈmɑːrkətpleɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4224,'colloc-7-01',34,'global media','truyền thông toàn cầu','adj + n','[{"en":"Global media can spread news across the world within seconds.","vi":"Truyền thông toàn cầu có thể lan tin khắp thế giới trong vài giây."},{"en":"Global media shapes how people view distant conflicts.","vi":"Truyền thông toàn cầu định hình cách con người nhìn nhận các xung đột ở xa."},{"en":"A few large firms control much of the global media.","vi":"Vài tập đoàn lớn kiểm soát phần lớn truyền thông toàn cầu."}]','[]',NULL,'/ˈɡloʊbəl ˈmiːdiə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4225,'colloc-7-01',35,'global network','mạng lưới toàn cầu','adj + n','[{"en":"The airline operates a global network of busy routes.","vi":"Hãng hàng không vận hành một mạng lưới đường bay bận rộn toàn cầu."},{"en":"Scientists share data through a global network of laboratories.","vi":"Các nhà khoa học chia sẻ dữ liệu qua một mạng lưới phòng thí nghiệm toàn cầu."},{"en":"A global network of volunteers supports the relief effort.","vi":"Một mạng lưới tình nguyện viên toàn cầu hỗ trợ công tác cứu trợ."}]','[]',NULL,'/ˈɡloʊbəl ˈnetwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4226,'colloc-7-01',36,'global perspective','góc nhìn toàn cầu','adj + n','[{"en":"Studying abroad gave her a truly global perspective.","vi":"Việc du học đã mang lại cho cô ấy một góc nhìn toàn cầu thực sự."},{"en":"A global perspective helps us see problems beyond our borders.","vi":"Góc nhìn toàn cầu giúp chúng ta nhìn vấn đề vượt ra ngoài biên giới."},{"en":"The book adopts a global perspective on economic development.","vi":"Cuốn sách áp dụng góc nhìn toàn cầu về phát triển kinh tế."}]','[]',NULL,'/ˈɡloʊbəl pərˈspektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4227,'colloc-7-01',37,'global shift','sự dịch chuyển toàn cầu','adj + n','[{"en":"There has been a global shift toward renewable energy sources.","vi":"Đã có một sự dịch chuyển toàn cầu hướng tới nguồn năng lượng tái tạo."},{"en":"The report describes a global shift in manufacturing to Asia.","vi":"Báo cáo mô tả sự dịch chuyển toàn cầu của sản xuất sang châu Á."},{"en":"A global shift in attitudes has improved environmental awareness.","vi":"Sự dịch chuyển toàn cầu trong thái độ đã nâng cao ý thức môi trường."}]','[]',NULL,'/ˈɡloʊbəl ʃɪft/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4228,'colloc-7-01',38,'global structure','cấu trúc toàn cầu','adj + n','[{"en":"The global structure of trade has changed over recent decades.","vi":"Cấu trúc toàn cầu của thương mại đã thay đổi trong các thập kỷ gần đây."},{"en":"Researchers study the global structure of financial markets.","vi":"Các nhà nghiên cứu nghiên cứu cấu trúc toàn cầu của thị trường tài chính."},{"en":"A clear global structure helps the organization coordinate work.","vi":"Một cấu trúc toàn cầu rõ ràng giúp tổ chức phối hợp công việc."}]','[]',NULL,'/ˈɡloʊbəl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4229,'colloc-7-01',39,'global trade','thương mại toàn cầu','adj + n','[{"en":"Global trade allows countries to exchange goods they lack.","vi":"Thương mại toàn cầu cho phép các nước trao đổi hàng hóa họ thiếu."},{"en":"The crisis caused a sharp fall in global trade.","vi":"Cuộc khủng hoảng khiến thương mại toàn cầu sụt giảm mạnh."},{"en":"New agreements aim to make global trade fairer for all.","vi":"Các thỏa thuận mới nhằm làm cho thương mại toàn cầu công bằng hơn."}]','[]',NULL,'/ˈɡloʊbəl treɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4230,'colloc-7-01',40,'global village','ngôi làng toàn cầu','adj + n','[{"en":"Technology has turned the world into a global village.","vi":"Công nghệ đã biến thế giới thành một ngôi làng toàn cầu."},{"en":"In the global village, news travels almost instantly everywhere.","vi":"Trong ngôi làng toàn cầu, tin tức lan đi gần như tức thì khắp nơi."},{"en":"The idea of a global village highlights how connected we are.","vi":"Ý tưởng về ngôi làng toàn cầu nhấn mạnh chúng ta kết nối ra sao."}]','[]',NULL,'/ˈɡloʊbəl ˈvɪlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4231,'colloc-7-01',41,'government control','sự kiểm soát của chính phủ','n + n','[{"en":"The industry operated under strict government control for years.","vi":"Ngành công nghiệp này hoạt động dưới sự kiểm soát chặt của chính phủ nhiều năm."},{"en":"Some argue that government control limits business innovation.","vi":"Một số người cho rằng sự kiểm soát của chính phủ hạn chế đổi mới kinh doanh."},{"en":"Prices fell after government control of the market ended.","vi":"Giá giảm sau khi sự kiểm soát thị trường của chính phủ chấm dứt."}]','[]',NULL,'/ˈɡʌvərnmənt kənˈtroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4232,'colloc-7-01',42,'government department','bộ, cơ quan chính phủ','n + n','[{"en":"Each government department manages a different area of policy.","vi":"Mỗi cơ quan chính phủ quản lý một lĩnh vực chính sách khác nhau."},{"en":"She works for the government department in charge of transport.","vi":"Cô ấy làm việc cho bộ chính phủ phụ trách giao thông."},{"en":"The government department published its annual budget yesterday.","vi":"Cơ quan chính phủ đã công bố ngân sách hàng năm hôm qua."}]','[]',NULL,'/ˈɡʌvərnmənt dɪˈpɑːrtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4233,'colloc-7-01',43,'government expenditure','chi tiêu của chính phủ','n + n','[{"en":"Government expenditure on health rose sharply over the decade.","vi":"Chi tiêu của chính phủ cho y tế tăng mạnh trong thập kỷ qua."},{"en":"High government expenditure can lead to a large national debt.","vi":"Chi tiêu cao của chính phủ có thể dẫn đến nợ quốc gia lớn."},{"en":"The report analyzes government expenditure across several countries.","vi":"Báo cáo phân tích chi tiêu của chính phủ ở nhiều quốc gia."}]','[]',NULL,'/ˈɡʌvərnmənt ɪkˈspendɪtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4234,'colloc-7-01',44,'government intervention','sự can thiệp của chính phủ','n + n','[{"en":"Government intervention helped stabilize the banking system.","vi":"Sự can thiệp của chính phủ đã giúp ổn định hệ thống ngân hàng."},{"en":"Economists disagree about how much government intervention is wise.","vi":"Các nhà kinh tế bất đồng về mức độ can thiệp hợp lý của chính phủ."},{"en":"Without government intervention, the crisis might have worsened.","vi":"Nếu không có sự can thiệp của chính phủ, khủng hoảng có thể tệ hơn."}]','[]',NULL,'/ˈɡʌvərnmənt ˌɪntərˈvenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4235,'colloc-7-01',45,'government policy','chính sách của chính phủ','n + n','[{"en":"Government policy on education changed after the election.","vi":"Chính sách giáo dục của chính phủ thay đổi sau cuộc bầu cử."},{"en":"The new government policy aims to reduce air pollution.","vi":"Chính sách mới của chính phủ nhằm giảm ô nhiễm không khí."},{"en":"Critics say government policy ignores the needs of rural areas.","vi":"Người chỉ trích nói chính sách của chính phủ bỏ qua nhu cầu vùng nông thôn."}]','[]',NULL,'/ˈɡʌvərnmənt ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4236,'colloc-7-01',46,'graphical representation','biểu diễn bằng đồ thị','adj + n','[{"en":"A graphical representation makes the trend easier to understand.","vi":"Một biểu diễn bằng đồ thị giúp xu hướng dễ hiểu hơn."},{"en":"The report includes a graphical representation of the survey data.","vi":"Báo cáo gồm một biểu diễn bằng đồ thị của dữ liệu khảo sát."},{"en":"Students created a graphical representation of their results.","vi":"Sinh viên đã tạo một biểu diễn bằng đồ thị cho kết quả của họ."}]','[]',NULL,'/ˈɡræfɪkəl ˌreprɪzenˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4237,'colloc-7-01',47,'great accuracy','độ chính xác cao','adj + n','[{"en":"The new instrument measures temperature with great accuracy.","vi":"Thiết bị mới đo nhiệt độ với độ chính xác cao."},{"en":"She translated the document with great accuracy and care.","vi":"Cô ấy dịch tài liệu với độ chính xác cao và cẩn thận."},{"en":"The model predicts rainfall with surprisingly great accuracy.","vi":"Mô hình dự đoán lượng mưa với độ chính xác cao đáng ngạc nhiên."}]','[]',NULL,'/ɡreɪt ˈækjərəsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4238,'colloc-7-01',48,'great diversity','sự đa dạng lớn','adj + n','[{"en":"The region shows great diversity in its plants and animals.","vi":"Vùng này thể hiện sự đa dạng lớn về thực vật và động vật."},{"en":"There is great diversity of opinion among the experts.","vi":"Có sự đa dạng lớn về quan điểm giữa các chuyên gia."},{"en":"The city is known for the great diversity of its people.","vi":"Thành phố nổi tiếng với sự đa dạng lớn của cư dân."}]','[]',NULL,'/ɡreɪt daɪˈvɜːrsəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4239,'colloc-7-01',49,'great impact','tác động lớn','adj + n','[{"en":"The invention of the internet had a great impact on society.","vi":"Việc phát minh ra internet đã có tác động lớn đến xã hội."},{"en":"Her research has had a great impact on modern medicine.","vi":"Nghiên cứu của cô đã có tác động lớn đến y học hiện đại."},{"en":"Early childhood experiences have a great impact on later life.","vi":"Những trải nghiệm thời thơ ấu có tác động lớn đến cuộc sống về sau."}]','[]',NULL,'/ɡreɪt ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4240,'colloc-7-01',50,'great majority','đại đa số','adj + n','[{"en":"The great majority of students passed the final exam easily.","vi":"Đại đa số sinh viên dễ dàng vượt qua kỳ thi cuối kỳ."},{"en":"In the survey, the great majority supported the new plan.","vi":"Trong cuộc khảo sát, đại đa số ủng hộ kế hoạch mới."},{"en":"The great majority of accidents happen on busy roads.","vi":"Đại đa số tai nạn xảy ra trên những con đường đông đúc."}]','[]',NULL,'/ɡreɪt məˈdʒɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4241,'colloc-7-01',51,'great potential','tiềm năng lớn','adj + n','[{"en":"Solar energy has great potential to power future cities.","vi":"Năng lượng mặt trời có tiềm năng lớn để cung cấp điện cho các thành phố tương lai."},{"en":"The young player shows great potential as a future star.","vi":"Cầu thủ trẻ thể hiện tiềm năng lớn để trở thành ngôi sao tương lai."},{"en":"This region has great potential for tourism and agriculture.","vi":"Vùng này có tiềm năng lớn cho du lịch và nông nghiệp."}]','[]',NULL,'/ɡreɪt pəˈtenʃəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4242,'colloc-7-01',52,'great proportion of','tỷ lệ lớn của','adj + n','[{"en":"A great proportion of the budget goes to staff salaries.","vi":"Một tỷ lệ lớn ngân sách dành cho lương nhân viên."},{"en":"A great proportion of the population lives in coastal cities.","vi":"Một tỷ lệ lớn dân số sống ở các thành phố ven biển."},{"en":"A great proportion of the data was lost in the failure.","vi":"Một tỷ lệ lớn dữ liệu đã bị mất trong sự cố."}]','[]',NULL,'/ɡreɪt prəˈpɔːrʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4243,'colloc-7-01',53,'great range of','nhiều loại, phạm vi rộng của','adj + n','[{"en":"The library offers a great range of books on history.","vi":"Thư viện cung cấp nhiều loại sách về lịch sử."},{"en":"The store sells a great range of products at low prices.","vi":"Cửa hàng bán nhiều loại sản phẩm với giá rẻ."},{"en":"The course covers a great range of topics in biology.","vi":"Khóa học bao quát phạm vi rộng các chủ đề trong sinh học."}]','[]',NULL,'/ɡreɪt reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4244,'colloc-7-01',54,'great significance','tầm quan trọng lớn','adj + n','[{"en":"The discovery is of great significance to medical science.","vi":"Phát hiện này có tầm quan trọng lớn đối với khoa học y tế."},{"en":"The treaty had great significance for peace in the region.","vi":"Hiệp ước có tầm quan trọng lớn đối với hòa bình trong khu vực."},{"en":"These findings hold great significance for future research.","vi":"Những phát hiện này có tầm quan trọng lớn cho nghiên cứu tương lai."}]','[]',NULL,'/ɡreɪt sɪɡˈnɪfɪkəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4245,'colloc-7-01',55,'greater autonomy','quyền tự chủ lớn hơn','adj + n','[{"en":"The reforms gave local councils greater autonomy over budgets.","vi":"Các cải cách trao cho hội đồng địa phương quyền tự chủ lớn hơn về ngân sách."},{"en":"Workers asked for greater autonomy in planning their tasks.","vi":"Người lao động yêu cầu quyền tự chủ lớn hơn trong việc lập kế hoạch công việc."},{"en":"Greater autonomy can improve both motivation and creativity.","vi":"Quyền tự chủ lớn hơn có thể cải thiện cả động lực và sự sáng tạo."}]','[]',NULL,'/ˈɡreɪtər ɔːˈtɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4246,'colloc-7-01',56,'greater awareness','nhận thức cao hơn','adj + n','[{"en":"The campaign created greater awareness of mental health issues.","vi":"Chiến dịch tạo ra nhận thức cao hơn về các vấn đề sức khỏe tâm thần."},{"en":"There is now greater awareness of the dangers of smoking.","vi":"Hiện đã có nhận thức cao hơn về tác hại của hút thuốc."},{"en":"Education leads to greater awareness of environmental problems.","vi":"Giáo dục dẫn đến nhận thức cao hơn về các vấn đề môi trường."}]','[]',NULL,'/ˈɡreɪtər əˈwernəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4247,'colloc-7-01',57,'greater emphasis','sự nhấn mạnh nhiều hơn','adj + n','[{"en":"Schools now place greater emphasis on critical thinking skills.","vi":"Các trường giờ đây nhấn mạnh nhiều hơn vào kỹ năng tư duy phản biện."},{"en":"The company puts greater emphasis on customer satisfaction.","vi":"Công ty đặt sự nhấn mạnh nhiều hơn vào sự hài lòng của khách hàng."},{"en":"We need greater emphasis on prevention rather than treatment.","vi":"Chúng ta cần nhấn mạnh nhiều hơn vào phòng ngừa thay vì điều trị."}]','[]',NULL,'/ˈɡreɪtər ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4248,'colloc-7-01',58,'greater equality','sự bình đẳng lớn hơn','adj + n','[{"en":"The law aims to create greater equality between men and women.","vi":"Luật nhằm tạo sự bình đẳng lớn hơn giữa nam và nữ."},{"en":"Many reforms were introduced to promote greater equality.","vi":"Nhiều cải cách được đưa ra để thúc đẩy sự bình đẳng lớn hơn."},{"en":"Greater equality in education benefits the whole society.","vi":"Sự bình đẳng lớn hơn trong giáo dục mang lại lợi ích cho cả xã hội."}]','[]',NULL,'/ˈɡreɪtər ɪˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4249,'colloc-7-01',59,'greater flexibility','sự linh hoạt cao hơn','adj + n','[{"en":"Remote work offers employees greater flexibility in their schedules.","vi":"Làm việc từ xa mang lại cho nhân viên sự linh hoạt cao hơn về lịch trình."},{"en":"The new system allows greater flexibility in choosing courses.","vi":"Hệ thống mới cho phép sự linh hoạt cao hơn trong việc chọn môn học."},{"en":"Greater flexibility helps companies respond to sudden changes.","vi":"Sự linh hoạt cao hơn giúp công ty ứng phó với thay đổi đột ngột."}]','[]',NULL,'/ˈɡreɪtər ˌfleksəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4250,'colloc-7-01',60,'greater likelihood','khả năng cao hơn','adj + n','[{"en":"Regular exercise brings a greater likelihood of good health.","vi":"Tập thể dục đều đặn mang lại khả năng cao hơn về sức khỏe tốt."},{"en":"Students who read often have a greater likelihood of success.","vi":"Sinh viên đọc nhiều có khả năng thành công cao hơn."},{"en":"Poor diet is linked to a greater likelihood of disease.","vi":"Chế độ ăn kém liên quan đến khả năng mắc bệnh cao hơn."}]','[]',NULL,'/ˈɡreɪtər ˈlaɪklihʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4251,'colloc-7-01',61,'greatly enhance','nâng cao đáng kể','adv + v','[{"en":"Good lighting can greatly enhance the quality of photographs.","vi":"Ánh sáng tốt có thể nâng cao đáng kể chất lượng ảnh chụp."},{"en":"New software will greatly enhance the team''s productivity.","vi":"Phần mềm mới sẽ nâng cao đáng kể năng suất của nhóm."},{"en":"Studying abroad can greatly enhance your career prospects.","vi":"Du học có thể nâng cao đáng kể triển vọng nghề nghiệp của bạn."}]','[]',NULL,'/ˈɡreɪtli ɪnˈhæns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4252,'colloc-7-01',62,'greatly increase','tăng đáng kể','adv + v','[{"en":"Smoking can greatly increase the risk of lung disease.","vi":"Hút thuốc có thể tăng đáng kể nguy cơ mắc bệnh phổi."},{"en":"The new road will greatly increase traffic into the town.","vi":"Con đường mới sẽ làm tăng đáng kể lượng xe vào thị trấn."},{"en":"Advertising can greatly increase sales of a new product.","vi":"Quảng cáo có thể tăng đáng kể doanh số của sản phẩm mới."}]','[]',NULL,'/ˈɡreɪtli ɪnˈkriːs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4253,'colloc-7-01',63,'greatly influenced by','chịu ảnh hưởng lớn bởi','adv + vpp','[{"en":"Her writing was greatly influenced by classical literature.","vi":"Văn của cô chịu ảnh hưởng lớn bởi văn học cổ điển."},{"en":"The artist was greatly influenced by his travels abroad.","vi":"Người nghệ sĩ chịu ảnh hưởng lớn bởi những chuyến đi nước ngoài."},{"en":"Modern science was greatly influenced by ancient Greek thinkers.","vi":"Khoa học hiện đại chịu ảnh hưởng lớn bởi các nhà tư tưởng Hy Lạp cổ."}]','[]',NULL,'/ˈɡreɪtli ˈɪnfluənst baɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4254,'colloc-7-01',64,'greatly reduced','giảm đáng kể','adv + vpp','[{"en":"Pollution was greatly reduced after the new law passed.","vi":"Ô nhiễm đã giảm đáng kể sau khi luật mới được thông qua."},{"en":"The risk of infection is greatly reduced by washing hands.","vi":"Nguy cơ nhiễm trùng giảm đáng kể nhờ rửa tay."},{"en":"Travel time was greatly reduced once the bridge opened.","vi":"Thời gian di chuyển giảm đáng kể khi cây cầu được khánh thành."}]','[]',NULL,'/ˈɡreɪtli rɪˈduːst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4255,'colloc-7-01',65,'grow rapidly','phát triển nhanh chóng','v + adv','[{"en":"The city''s population began to grow rapidly after 1990.","vi":"Dân số thành phố bắt đầu phát triển nhanh chóng sau năm 1990."},{"en":"Online businesses can grow rapidly with the right strategy.","vi":"Các doanh nghiệp trực tuyến có thể phát triển nhanh chóng với chiến lược đúng."},{"en":"Demand for electric cars continues to grow rapidly worldwide.","vi":"Nhu cầu về ô tô điện tiếp tục phát triển nhanh chóng trên toàn cầu."}]','[]',NULL,'/ɡroʊ ˈræpɪdli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4256,'colloc-7-01',66,'growing awareness','nhận thức ngày càng tăng','adj + n','[{"en":"There is growing awareness of the effects of climate change.","vi":"Có nhận thức ngày càng tăng về các tác động của biến đổi khí hậu."},{"en":"Growing awareness of healthy eating has changed shopping habits.","vi":"Nhận thức ngày càng tăng về ăn uống lành mạnh đã thay đổi thói quen mua sắm."},{"en":"The campaign reflects growing awareness of online safety.","vi":"Chiến dịch phản ánh nhận thức ngày càng tăng về an toàn trực tuyến."}]','[]',NULL,'/ˈɡroʊɪŋ əˈwernəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4257,'colloc-7-01',67,'growing trend','xu hướng ngày càng tăng','adj + n','[{"en":"There is a growing trend toward working from home.","vi":"Có một xu hướng ngày càng tăng về làm việc tại nhà."},{"en":"A growing trend among young people is shopping online.","vi":"Một xu hướng ngày càng tăng trong giới trẻ là mua sắm trực tuyến."},{"en":"The report identifies a growing trend in renewable energy use.","vi":"Báo cáo chỉ ra một xu hướng ngày càng tăng về dùng năng lượng tái tạo."}]','[]',NULL,'/ˈɡroʊɪŋ trend/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4258,'colloc-7-01',68,'guiding principle','nguyên tắc chỉ đạo','adj + n','[{"en":"Honesty is the guiding principle of our entire organization.","vi":"Trung thực là nguyên tắc chỉ đạo của toàn bộ tổ chức chúng tôi."},{"en":"Fairness should be the guiding principle behind every decision.","vi":"Công bằng nên là nguyên tắc chỉ đạo đằng sau mỗi quyết định."},{"en":"The guiding principle of the law is to protect citizens.","vi":"Nguyên tắc chỉ đạo của luật là bảo vệ công dân."}]','[]',NULL,'/ˈɡaɪdɪŋ ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4259,'colloc-7-01',69,'hardly surprising','chẳng có gì đáng ngạc nhiên','adv + adj','[{"en":"It is hardly surprising that prices rose after the shortage.","vi":"Chẳng có gì đáng ngạc nhiên khi giá tăng sau tình trạng khan hiếm."},{"en":"Given the rain, the low turnout was hardly surprising.","vi":"Với trời mưa, lượng người tham dự thấp chẳng có gì đáng ngạc nhiên."},{"en":"It is hardly surprising that students prefer shorter lectures.","vi":"Chẳng có gì đáng ngạc nhiên khi sinh viên thích các bài giảng ngắn hơn."}]','[]',NULL,'/ˈhɑːrdli sərˈpraɪzɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4260,'colloc-7-01',70,'have access to','có quyền tiếp cận, được sử dụng','v + n','[{"en":"All students have access to the library''s online resources.","vi":"Tất cả sinh viên đều có quyền tiếp cận tài nguyên trực tuyến của thư viện."},{"en":"Many rural areas still do not have access to clean water.","vi":"Nhiều vùng nông thôn vẫn chưa được sử dụng nước sạch."},{"en":"Only managers have access to the confidential files.","vi":"Chỉ quản lý mới có quyền tiếp cận các hồ sơ mật."}]','[]',NULL,'/hæv ˈækses tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4261,'colloc-7-01',71,'have consequences','gây ra hậu quả','v + n','[{"en":"Every decision we make will have consequences for the future.","vi":"Mỗi quyết định chúng ta đưa ra đều sẽ gây ra hậu quả cho tương lai."},{"en":"Ignoring the warning could have serious consequences for everyone.","vi":"Bỏ qua cảnh báo có thể gây ra hậu quả nghiêm trọng cho mọi người."},{"en":"Poor planning often has consequences that are hard to fix.","vi":"Lập kế hoạch kém thường gây ra hậu quả khó khắc phục."}]','[]',NULL,'/hæv ˈkɑːnsəkwensəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4262,'colloc-7-01',72,'have limitations','có hạn chế','v + n','[{"en":"Every research method has limitations that we should recognize.","vi":"Mọi phương pháp nghiên cứu đều có hạn chế mà ta nên nhận ra."},{"en":"The study has limitations because the sample was quite small.","vi":"Nghiên cứu có hạn chế vì mẫu khá nhỏ."},{"en":"Even the best technology has limitations in extreme conditions.","vi":"Ngay cả công nghệ tốt nhất cũng có hạn chế trong điều kiện khắc nghiệt."}]','[]',NULL,'/hæv ˌlɪmɪˈteɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4263,'colloc-7-01',73,'have potential','có tiềm năng','v + n','[{"en":"This new approach has potential to improve learning outcomes.","vi":"Cách tiếp cận mới này có tiềm năng cải thiện kết quả học tập."},{"en":"The young athlete clearly has potential to compete nationally.","vi":"Vận động viên trẻ rõ ràng có tiềm năng thi đấu cấp quốc gia."},{"en":"Renewable sources have potential to replace fossil fuels.","vi":"Các nguồn tái tạo có tiềm năng thay thế nhiên liệu hóa thạch."}]','[]',NULL,'/hæv pəˈtenʃəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4264,'colloc-7-01',74,'have a strategy','có một chiến lược','v + n','[{"en":"Successful companies always have a clear strategy for growth.","vi":"Các công ty thành công luôn có một chiến lược rõ ràng để phát triển."},{"en":"You should have a strategy before starting the negotiation.","vi":"Bạn nên có một chiến lược trước khi bắt đầu đàm phán."},{"en":"The team needs to have a strategy to handle the crisis.","vi":"Nhóm cần có một chiến lược để xử lý khủng hoảng."}]','[]',NULL,'/hæv ə ˈstrætədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4265,'colloc-7-01',75,'have a tendency to','có xu hướng','v + n','[{"en":"People have a tendency to remember bad news more easily.","vi":"Con người có xu hướng nhớ tin xấu dễ dàng hơn."},{"en":"New drivers have a tendency to brake too suddenly.","vi":"Tài xế mới có xu hướng phanh quá đột ngột."},{"en":"Prices have a tendency to rise during the holiday season.","vi":"Giá cả có xu hướng tăng trong mùa lễ hội."}]','[]',NULL,'/hæv ə ˈtendənsi tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4266,'colloc-7-01',76,'have an obligation','có nghĩa vụ','v + n','[{"en":"Companies have an obligation to protect their customers'' data.","vi":"Các công ty có nghĩa vụ bảo vệ dữ liệu của khách hàng."},{"en":"Citizens have an obligation to obey the laws of the country.","vi":"Công dân có nghĩa vụ tuân thủ pháp luật của đất nước."},{"en":"Teachers have an obligation to treat every student fairly.","vi":"Giáo viên có nghĩa vụ đối xử công bằng với mọi học sinh."}]','[]',NULL,'/hæv ən ˌɑːblɪˈɡeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4267,'colloc-7-01',77,'heated debate','cuộc tranh luận gay gắt','adj + n','[{"en":"The new policy sparked a heated debate among the students.","vi":"Chính sách mới làm dấy lên một cuộc tranh luận gay gắt giữa các sinh viên."},{"en":"There was a heated debate about how to spend the budget.","vi":"Đã có một cuộc tranh luận gay gắt về cách chi tiêu ngân sách."},{"en":"The topic of immigration often leads to heated debate.","vi":"Chủ đề nhập cư thường dẫn đến tranh luận gay gắt."}]','[]',NULL,'/ˈhiːtəd dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4268,'colloc-7-01',78,'heavily influenced by','chịu ảnh hưởng mạnh bởi','adv + vpp','[{"en":"The region''s cuisine is heavily influenced by neighboring countries.","vi":"Ẩm thực của vùng chịu ảnh hưởng mạnh bởi các nước láng giềng."},{"en":"His early music was heavily influenced by local folk songs.","vi":"Âm nhạc thời kỳ đầu của anh chịu ảnh hưởng mạnh bởi dân ca địa phương."},{"en":"Voters were heavily influenced by the candidate''s promises.","vi":"Cử tri chịu ảnh hưởng mạnh bởi những lời hứa của ứng viên."}]','[]',NULL,'/ˈhevɪli ˈɪnfluənst baɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4269,'colloc-7-01',79,'hierarchical structure','cấu trúc thứ bậc','adj + n','[{"en":"The army relies on a strict hierarchical structure of command.","vi":"Quân đội dựa vào một cấu trúc thứ bậc chỉ huy nghiêm ngặt."},{"en":"Many traditional companies still use a hierarchical structure.","vi":"Nhiều công ty truyền thống vẫn dùng cấu trúc thứ bậc."},{"en":"A hierarchical structure can slow down important decisions.","vi":"Cấu trúc thứ bậc có thể làm chậm các quyết định quan trọng."}]','[]',NULL,'/ˌhaɪəˈrɑːrkɪkəl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4270,'colloc-7-01',80,'high concentration','nồng độ cao, sự tập trung cao','adj + n','[{"en":"The water contained a high concentration of harmful chemicals.","vi":"Nước chứa nồng độ cao các hóa chất độc hại."},{"en":"There is a high concentration of factories near the river.","vi":"Có sự tập trung cao các nhà máy gần con sông."},{"en":"A high concentration of salt can damage most plants.","vi":"Nồng độ muối cao có thể gây hại cho hầu hết cây trồng."}]','[]',NULL,'/haɪ ˌkɑːnsənˈtreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4271,'colloc-7-01',81,'high correlation','mối tương quan cao','adj + n','[{"en":"There is a high correlation between exercise and good health.","vi":"Có mối tương quan cao giữa tập luyện và sức khỏe tốt."},{"en":"The study found a high correlation between income and education.","vi":"Nghiên cứu tìm thấy mối tương quan cao giữa thu nhập và học vấn."},{"en":"A high correlation does not always prove a direct cause.","vi":"Mối tương quan cao không phải lúc nào cũng chứng minh nguyên nhân trực tiếp."}]','[]',NULL,'/haɪ ˌkɔːrəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4272,'colloc-7-01',82,'high expectations','kỳ vọng cao','adj + n','[{"en":"Parents often have high expectations for their children''s grades.","vi":"Cha mẹ thường có kỳ vọng cao về điểm số của con cái."},{"en":"The new manager set high expectations for the whole team.","vi":"Quản lý mới đặt kỳ vọng cao cho toàn đội."},{"en":"High expectations can motivate students to work harder.","vi":"Kỳ vọng cao có thể thúc đẩy sinh viên cố gắng hơn."}]','[]',NULL,'/haɪ ˌekspekˈteɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4273,'colloc-7-01',83,'high incidence','tỷ lệ xảy ra cao','adj + n','[{"en":"The region has a high incidence of certain heart diseases.","vi":"Vùng này có tỷ lệ xảy ra cao của một số bệnh tim."},{"en":"Researchers studied the high incidence of accidents on that road.","vi":"Các nhà nghiên cứu nghiên cứu tỷ lệ tai nạn cao trên con đường đó."},{"en":"Poor housing is linked to a high incidence of illness.","vi":"Nhà ở kém liên quan đến tỷ lệ bệnh tật cao."}]','[]',NULL,'/haɪ ˈɪnsɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4274,'colloc-7-01',84,'high intensity','cường độ cao','adj + n','[{"en":"High intensity exercise can burn calories in a short time.","vi":"Bài tập cường độ cao có thể đốt calo trong thời gian ngắn."},{"en":"The storm hit the coast with surprisingly high intensity.","vi":"Cơn bão đổ bộ vào bờ biển với cường độ cao đáng ngạc nhiên."},{"en":"The light''s high intensity made it hard to look directly.","vi":"Cường độ cao của ánh sáng khiến khó nhìn trực tiếp."}]','[]',NULL,'/haɪ ɪnˈtensəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4275,'colloc-7-01',85,'high level','mức độ cao','adj + n','[{"en":"The job requires a high level of skill and patience.","vi":"Công việc đòi hỏi mức độ cao về kỹ năng và sự kiên nhẫn."},{"en":"There is a high level of trust between the two partners.","vi":"Có mức độ tin tưởng cao giữa hai đối tác."},{"en":"Athletes maintain a high level of fitness all year round.","vi":"Các vận động viên duy trì mức độ thể lực cao quanh năm."}]','[]',NULL,'/haɪ ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4276,'colloc-7-01',86,'high order','bậc cao, cấp độ cao','adj + n','[{"en":"The exam tests high order thinking rather than simple memory.","vi":"Kỳ thi kiểm tra tư duy bậc cao chứ không phải trí nhớ đơn giản."},{"en":"Solving the puzzle requires skills of a high order.","vi":"Giải câu đố này đòi hỏi các kỹ năng bậc cao."},{"en":"These tasks develop high order reasoning in young learners.","vi":"Những nhiệm vụ này phát triển lập luận bậc cao ở người học nhỏ tuổi."}]','[]',NULL,'/haɪ ˈɔːrdər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4277,'colloc-7-01',87,'high percentage','tỷ lệ phần trăm cao','adj + n','[{"en":"A high percentage of graduates found work within six months.","vi":"Một tỷ lệ phần trăm cao sinh viên tốt nghiệp tìm được việc trong sáu tháng."},{"en":"The survey showed a high percentage of satisfied customers.","vi":"Khảo sát cho thấy tỷ lệ phần trăm cao khách hàng hài lòng."},{"en":"A high percentage of energy is still wasted in old buildings.","vi":"Một tỷ lệ phần trăm cao năng lượng vẫn bị lãng phí trong tòa nhà cũ."}]','[]',NULL,'/haɪ pərˈsentɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4278,'colloc-7-01',88,'high priority','ưu tiên cao','adj + n','[{"en":"Reducing road accidents is a high priority for the government.","vi":"Giảm tai nạn giao thông là ưu tiên cao của chính phủ."},{"en":"The company gives high priority to customer safety.","vi":"Công ty dành ưu tiên cao cho sự an toàn của khách hàng."},{"en":"Clean water should be a high priority in poor regions.","vi":"Nước sạch nên là ưu tiên cao ở các vùng nghèo."}]','[]',NULL,'/haɪ praɪˈɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4279,'colloc-7-01',89,'high probability','xác suất cao','adj + n','[{"en":"There is a high probability of rain later this afternoon.","vi":"Có xác suất cao trời sẽ mưa vào chiều muộn nay."},{"en":"The model shows a high probability of further price increases.","vi":"Mô hình cho thấy xác suất cao giá sẽ tiếp tục tăng."},{"en":"There is a high probability that the experiment will succeed.","vi":"Có xác suất cao thí nghiệm sẽ thành công."}]','[]',NULL,'/haɪ ˌprɑːbəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4280,'colloc-7-01',90,'high profile','nổi bật, được chú ý nhiều','adj + n','[{"en":"The trial received high profile coverage in the national press.","vi":"Phiên tòa nhận được sự đưa tin nổi bật trên báo chí quốc gia."},{"en":"She took a high profile role in the campaign last year.","vi":"Cô đảm nhận một vai trò nổi bật trong chiến dịch năm ngoái."},{"en":"A high profile event attracted thousands of curious visitors.","vi":"Một sự kiện được chú ý nhiều thu hút hàng ngàn khách tò mò."}]','[]',NULL,'/haɪ ˈproʊfaɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4281,'colloc-7-01',91,'high proportion of','tỷ lệ cao của','adj + n','[{"en":"A high proportion of the workforce is now over fifty.","vi":"Một tỷ lệ cao lực lượng lao động hiện đã trên năm mươi tuổi."},{"en":"A high proportion of students study part time these days.","vi":"Một tỷ lệ cao sinh viên ngày nay học bán thời gian."},{"en":"A high proportion of the income comes from foreign tourists.","vi":"Một tỷ lệ cao thu nhập đến từ khách du lịch nước ngoài."}]','[]',NULL,'/haɪ prəˈpɔːrʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4282,'colloc-7-01',92,'high quality','chất lượng cao','adj + n','[{"en":"The company is known for its high quality products worldwide.","vi":"Công ty nổi tiếng với các sản phẩm chất lượng cao trên toàn cầu."},{"en":"High quality teaching makes a real difference to students.","vi":"Giảng dạy chất lượng cao tạo ra sự khác biệt thực sự cho sinh viên."},{"en":"We use only high quality materials to build these houses.","vi":"Chúng tôi chỉ dùng vật liệu chất lượng cao để xây những ngôi nhà này."}]','[]',NULL,'/haɪ ˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4283,'colloc-7-01',93,'high rate','tỷ lệ cao','adj + n','[{"en":"The country reports a high rate of youth unemployment.","vi":"Quốc gia này ghi nhận tỷ lệ thất nghiệp ở giới trẻ cao."},{"en":"A high rate of recovery suggests the treatment is working.","vi":"Tỷ lệ hồi phục cao cho thấy phương pháp điều trị có hiệu quả."},{"en":"Researchers noted a high rate of participation in the survey.","vi":"Các nhà nghiên cứu ghi nhận tỷ lệ tham gia khảo sát cao."}]','[]',NULL,'/ˈhaɪ ˈreɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4284,'colloc-7-01',94,'high score','điểm số cao','adj + n','[{"en":"Students with a high score on the test received scholarships.","vi":"Những học sinh đạt điểm số cao trong bài kiểm tra nhận học bổng."},{"en":"She achieved a high score despite limited preparation time.","vi":"Cô đạt điểm số cao dù thời gian ôn tập hạn chế."},{"en":"A high score reflects strong understanding of the material.","vi":"Điểm số cao phản ánh sự hiểu biết vững chắc về tài liệu."}]','[]',NULL,'/ˈhaɪ ˈskɔːr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4285,'colloc-7-01',95,'high standard','tiêu chuẩn cao','adj + n','[{"en":"The university maintains a high standard of academic writing.","vi":"Trường đại học duy trì tiêu chuẩn cao về viết học thuật."},{"en":"Employers expect a high standard of work from graduates.","vi":"Nhà tuyển dụng mong đợi tiêu chuẩn cao trong công việc từ sinh viên tốt nghiệp."},{"en":"Setting a high standard early helps students stay motivated.","vi":"Đặt tiêu chuẩn cao từ sớm giúp học sinh duy trì động lực."}]','[]',NULL,'/ˈhaɪ ˈstændərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4286,'colloc-7-01',96,'high status','địa vị cao','adj + n','[{"en":"Certain professions are associated with high status in society.","vi":"Một số nghề nghiệp gắn liền với địa vị cao trong xã hội."},{"en":"People of high status often influence community decisions.","vi":"Những người có địa vị cao thường ảnh hưởng đến quyết định của cộng đồng."},{"en":"The role carries high status but also heavy responsibility.","vi":"Vai trò này mang địa vị cao nhưng cũng nhiều trách nhiệm nặng nề."}]','[]',NULL,'/ˈhaɪ ˈsteɪtəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4287,'colloc-7-01',97,'high turnover','tỷ lệ thay đổi nhân sự cao','adj + n','[{"en":"The company struggles with high turnover among new employees.","vi":"Công ty gặp khó khăn với tỷ lệ thay đổi nhân sự cao ở nhân viên mới."},{"en":"High turnover increases the cost of training and recruitment.","vi":"Tỷ lệ nghỉ việc cao làm tăng chi phí đào tạo và tuyển dụng."},{"en":"Managers investigated why high turnover affected the department.","vi":"Quản lý điều tra lý do tỷ lệ thay nhân sự cao ảnh hưởng đến phòng ban."}]','[]',NULL,'/ˈhaɪ ˈtɜːrnˌoʊvər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4288,'colloc-7-01',98,'high unemployment','tỷ lệ thất nghiệp cao','adj + n','[{"en":"High unemployment can lead to widespread social unrest.","vi":"Tỷ lệ thất nghiệp cao có thể dẫn đến bất ổn xã hội rộng khắp."},{"en":"The region suffered from high unemployment after the factory closed.","vi":"Khu vực này chịu tỷ lệ thất nghiệp cao sau khi nhà máy đóng cửa."},{"en":"Economists linked high unemployment to the falling demand.","vi":"Các nhà kinh tế liên hệ tỷ lệ thất nghiệp cao với nhu cầu giảm sút."}]','[]',NULL,'/ˈhaɪ ˌʌnɪmˈplɔɪmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4289,'colloc-7-01',99,'high value','giá trị cao','adj + n','[{"en":"The museum protects artifacts of very high value.","vi":"Bảo tàng bảo vệ những hiện vật có giá trị rất cao."},{"en":"Employers place high value on communication skills.","vi":"Nhà tuyển dụng đặt giá trị cao vào kỹ năng giao tiếp."},{"en":"High value goods require careful handling during transport.","vi":"Hàng hóa giá trị cao cần được xử lý cẩn thận khi vận chuyển."}]','[]',NULL,'/ˈhaɪ ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4290,'colloc-7-01',100,'high/er frequency','tần suất cao hơn','adj + n','[{"en":"The disease appears with higher frequency in older populations.","vi":"Căn bệnh xuất hiện với tần suất cao hơn ở nhóm dân số lớn tuổi."},{"en":"Words of high frequency are easier for learners to recall.","vi":"Những từ có tần suất cao thì người học dễ nhớ lại hơn."},{"en":"Higher frequency of testing improved long-term retention.","vi":"Tần suất kiểm tra cao hơn giúp cải thiện khả năng ghi nhớ lâu dài."}]','[]',NULL,'/ˈhaɪər ˈfriːkwənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4291,'colloc-7-01',101,'higher degree of','mức độ cao hơn của','adj + n','[{"en":"The new method requires a higher degree of precision.","vi":"Phương pháp mới đòi hỏi mức độ chính xác cao hơn."},{"en":"Senior roles demand a higher degree of responsibility.","vi":"Các vị trí cấp cao đòi hỏi mức độ trách nhiệm cao hơn."},{"en":"Participants showed a higher degree of engagement this year.","vi":"Người tham gia thể hiện mức độ gắn kết cao hơn trong năm nay."}]','[]',NULL,'/ˈhaɪər dɪˈɡriː əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4292,'colloc-7-01',102,'higher education','giáo dục đại học','adj + n','[{"en":"Access to higher education has expanded over recent decades.","vi":"Cơ hội tiếp cận giáo dục đại học đã mở rộng trong các thập kỷ gần đây."},{"en":"Higher education prepares students for specialized careers.","vi":"Giáo dục đại học chuẩn bị cho sinh viên những nghề nghiệp chuyên môn."},{"en":"The cost of higher education remains a concern for families.","vi":"Chi phí giáo dục đại học vẫn là mối lo ngại đối với các gia đình."}]','[]',NULL,'/ˈhaɪər ˌedʒəˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4293,'colloc-7-01',103,'highly charged','đầy căng thẳng (về cảm xúc)','adv + vpp','[{"en":"The debate became highly charged as opinions clashed sharply.","vi":"Cuộc tranh luận trở nên đầy căng thẳng khi các ý kiến xung đột gay gắt."},{"en":"Highly charged topics require sensitive and careful discussion.","vi":"Những chủ đề đầy căng thẳng đòi hỏi sự thảo luận tế nhị và cẩn trọng."},{"en":"The meeting had a highly charged atmosphere from the start.","vi":"Cuộc họp có bầu không khí đầy căng thẳng ngay từ đầu."}]','[]',NULL,'/ˈhaɪli ˈtʃɑːrdʒd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4294,'colloc-7-01',104,'highly competitive','có tính cạnh tranh cao','adv + adj','[{"en":"The job market for graduates is highly competitive today.","vi":"Thị trường việc làm cho sinh viên tốt nghiệp hiện nay có tính cạnh tranh cao."},{"en":"Admission to the program is highly competitive each year.","vi":"Việc tuyển sinh vào chương trình có tính cạnh tranh cao mỗi năm."},{"en":"Firms operate in a highly competitive global environment.","vi":"Các công ty hoạt động trong môi trường toàn cầu cạnh tranh cao."}]','[]',NULL,'/ˈhaɪli kəmˈpetətɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4295,'colloc-7-01',105,'highly complex','rất phức tạp','adv + adj','[{"en":"The human brain is a highly complex biological system.","vi":"Bộ não con người là một hệ thống sinh học rất phức tạp."},{"en":"Climate models deal with highly complex interactions.","vi":"Các mô hình khí hậu xử lý những tương tác rất phức tạp."},{"en":"The legal case involved a highly complex set of rules.","vi":"Vụ kiện liên quan đến một tập hợp quy tắc rất phức tạp."}]','[]',NULL,'/ˈhaɪli kəmˈpleks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4296,'colloc-7-01',106,'highly controversial','gây tranh cãi mạnh mẽ','adv + adj','[{"en":"The proposed policy proved highly controversial among voters.","vi":"Chính sách được đề xuất tỏ ra gây tranh cãi mạnh mẽ trong giới cử tri."},{"en":"His research reached highly controversial conclusions.","vi":"Nghiên cứu của ông đưa ra những kết luận gây tranh cãi mạnh mẽ."},{"en":"The decision remains highly controversial even years later.","vi":"Quyết định này vẫn gây tranh cãi mạnh mẽ ngay cả nhiều năm sau."}]','[]',NULL,'/ˈhaɪli ˌkɑːntrəˈvɜːrʃəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4297,'colloc-7-01',107,'highly correlated with','có tương quan chặt chẽ với','adv + vpp','[{"en":"Income is highly correlated with educational attainment.","vi":"Thu nhập có tương quan chặt chẽ với trình độ học vấn."},{"en":"Sleep quality is highly correlated with daily performance.","vi":"Chất lượng giấc ngủ có tương quan chặt chẽ với hiệu suất hằng ngày."},{"en":"These two variables were highly correlated with each other.","vi":"Hai biến số này có tương quan chặt chẽ với nhau."}]','[]',NULL,'/ˈhaɪli ˈkɔːrəˌleɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4298,'colloc-7-01',108,'highly critical','rất chỉ trích','adv + adj','[{"en":"The report was highly critical of the government''s response.","vi":"Bản báo cáo rất chỉ trích cách phản ứng của chính phủ."},{"en":"Reviewers were highly critical of the study''s methodology.","vi":"Người phản biện rất chỉ trích phương pháp luận của nghiên cứu."},{"en":"She remained highly critical of the plan throughout the meeting.","vi":"Cô vẫn rất chỉ trích kế hoạch trong suốt cuộc họp."}]','[]',NULL,'/ˈhaɪli ˈkrɪtɪkəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4299,'colloc-7-01',109,'highly dependent','phụ thuộc rất nhiều','adv + adj','[{"en":"The economy is highly dependent on foreign investment.","vi":"Nền kinh tế phụ thuộc rất nhiều vào đầu tư nước ngoài."},{"en":"Crop yields are highly dependent on seasonal rainfall.","vi":"Sản lượng mùa màng phụ thuộc rất nhiều vào lượng mưa theo mùa."},{"en":"The outcome is highly dependent on careful planning.","vi":"Kết quả phụ thuộc rất nhiều vào việc lập kế hoạch cẩn thận."}]','[]',NULL,'/ˈhaɪli dɪˈpendənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4300,'colloc-7-01',110,'highly desirable','rất đáng mong muốn','adv + adj','[{"en":"Strong leadership skills are highly desirable in managers.","vi":"Kỹ năng lãnh đạo vững vàng rất đáng mong muốn ở các nhà quản lý."},{"en":"A quiet location makes the apartment highly desirable.","vi":"Vị trí yên tĩnh khiến căn hộ trở nên rất đáng mong muốn."},{"en":"Fluency in two languages is highly desirable for the role.","vi":"Thông thạo hai ngôn ngữ rất đáng mong muốn cho vị trí này."}]','[]',NULL,'/ˈhaɪli dɪˈzaɪərəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4301,'colloc-7-01',111,'highly developed','phát triển cao','adv + vpp','[{"en":"The region has a highly developed transport network.","vi":"Khu vực này có mạng lưới giao thông phát triển cao."},{"en":"Dolphins possess a highly developed sense of hearing.","vi":"Cá heo sở hữu khả năng nghe phát triển cao."},{"en":"Highly developed nations invest heavily in research.","vi":"Các quốc gia phát triển cao đầu tư mạnh vào nghiên cứu."}]','[]',NULL,'/ˈhaɪli dɪˈveləpt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4302,'colloc-7-01',112,'highly educated','có học vấn cao','adv + vpp','[{"en":"The company recruits highly educated specialists each year.","vi":"Công ty tuyển những chuyên gia có học vấn cao mỗi năm."},{"en":"A highly educated workforce drives economic innovation.","vi":"Một lực lượng lao động có học vấn cao thúc đẩy đổi mới kinh tế."},{"en":"Her parents were both highly educated professionals.","vi":"Cha mẹ cô đều là những chuyên gia có học vấn cao."}]','[]',NULL,'/ˈhaɪli ˈedʒəˌkeɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4303,'colloc-7-01',113,'highly effective','rất hiệu quả','adv + adj','[{"en":"The new vaccine proved highly effective in clinical trials.","vi":"Vắc-xin mới tỏ ra rất hiệu quả trong các thử nghiệm lâm sàng."},{"en":"Visual aids are a highly effective teaching tool.","vi":"Tài liệu trực quan là một công cụ giảng dạy rất hiệu quả."},{"en":"The campaign was highly effective at raising awareness.","vi":"Chiến dịch rất hiệu quả trong việc nâng cao nhận thức."}]','[]',NULL,'/ˈhaɪli ɪˈfektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4304,'colloc-7-01',114,'highly efficient','rất hiệu suất','adv + adj','[{"en":"The factory uses a highly efficient production process.","vi":"Nhà máy sử dụng quy trình sản xuất rất hiệu suất."},{"en":"Modern engines are highly efficient at converting fuel.","vi":"Động cơ hiện đại rất hiệu suất trong việc chuyển hóa nhiên liệu."},{"en":"Their highly efficient system reduced waste significantly.","vi":"Hệ thống rất hiệu suất của họ giảm lãng phí đáng kể."}]','[]',NULL,'/ˈhaɪli ɪˈfɪʃənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4305,'colloc-7-01',115,'highly influential','có ảnh hưởng lớn','adv + adj','[{"en":"Her book became highly influential in modern psychology.","vi":"Cuốn sách của bà trở nên có ảnh hưởng lớn trong tâm lý học hiện đại."},{"en":"He was a highly influential figure in the reform movement.","vi":"Ông là một nhân vật có ảnh hưởng lớn trong phong trào cải cách."},{"en":"The theory remains highly influential among economists.","vi":"Lý thuyết này vẫn có ảnh hưởng lớn trong giới kinh tế học."}]','[]',NULL,'/ˈhaɪli ˌɪnfluˈenʃəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4306,'colloc-7-01',116,'highly likely','rất có khả năng','adv + adj','[{"en":"It is highly likely that prices will rise next year.","vi":"Rất có khả năng giá sẽ tăng vào năm tới."},{"en":"Given the data, success seems highly likely now.","vi":"Với dữ liệu này, thành công có vẻ rất có khả năng xảy ra."},{"en":"A delay is highly likely due to the bad weather.","vi":"Sự chậm trễ rất có khả năng xảy ra do thời tiết xấu."}]','[]',NULL,'/ˈhaɪli ˈlaɪkli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4307,'colloc-7-01',117,'highly problematic','rất có vấn đề','adv + adj','[{"en":"The assumption proved highly problematic upon closer inspection.","vi":"Giả định này tỏ ra rất có vấn đề khi xem xét kỹ hơn."},{"en":"Using such small samples is highly problematic for accuracy.","vi":"Việc dùng mẫu nhỏ như vậy rất có vấn đề về độ chính xác."},{"en":"The definition is highly problematic and needs clarification.","vi":"Định nghĩa này rất có vấn đề và cần được làm rõ."}]','[]',NULL,'/ˈhaɪli ˌprɑːbləˈmætɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4308,'colloc-7-01',118,'highly relevant','rất phù hợp, rất liên quan','adv + adj','[{"en":"These findings are highly relevant to current policy debates.","vi":"Những phát hiện này rất liên quan đến các cuộc tranh luận chính sách hiện nay."},{"en":"The course content is highly relevant to my future career.","vi":"Nội dung khóa học rất phù hợp với sự nghiệp tương lai của tôi."},{"en":"His experience is highly relevant to the position offered.","vi":"Kinh nghiệm của anh rất phù hợp với vị trí được chào mời."}]','[]',NULL,'/ˈhaɪli ˈreləvənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4309,'colloc-7-01',119,'highly selective','có tính chọn lọc cao','adv + adj','[{"en":"The school has a highly selective admissions process.","vi":"Trường có quy trình tuyển sinh có tính chọn lọc cao."},{"en":"Editors are highly selective about which articles to publish.","vi":"Biên tập viên có tính chọn lọc cao về việc đăng bài nào."},{"en":"Memory can be highly selective about what it retains.","vi":"Trí nhớ có thể có tính chọn lọc cao về điều nó giữ lại."}]','[]',NULL,'/ˈhaɪli sɪˈlektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4310,'colloc-7-01',120,'highly sensitive','rất nhạy cảm','adv + adj','[{"en":"The instrument is highly sensitive to small temperature changes.","vi":"Thiết bị rất nhạy cảm với những thay đổi nhiệt độ nhỏ."},{"en":"The negotiations involve highly sensitive political issues.","vi":"Cuộc đàm phán liên quan đến những vấn đề chính trị rất nhạy cảm."},{"en":"Personal data is highly sensitive and must be protected.","vi":"Dữ liệu cá nhân rất nhạy cảm và phải được bảo vệ."}]','[]',NULL,'/ˈhaɪli ˈsensətɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4311,'colloc-7-01',121,'highly significant','rất đáng kể, rất ý nghĩa','adv + adj','[{"en":"The difference between groups was statistically highly significant.","vi":"Sự khác biệt giữa các nhóm có ý nghĩa thống kê rất đáng kể."},{"en":"This discovery is highly significant for cancer research.","vi":"Phát hiện này rất ý nghĩa đối với nghiên cứu ung thư."},{"en":"The event marked a highly significant moment in history.","vi":"Sự kiện này đánh dấu một khoảnh khắc rất ý nghĩa trong lịch sử."}]','[]',NULL,'/ˈhaɪli sɪɡˈnɪfɪkənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4312,'colloc-7-01',122,'highly skilled','có tay nghề cao','adv + adj','[{"en":"The hospital employs highly skilled surgeons and nurses.","vi":"Bệnh viện thuê những bác sĩ phẫu thuật và y tá có tay nghề cao."},{"en":"Highly skilled workers are in short supply in this sector.","vi":"Lao động có tay nghề cao đang thiếu hụt trong lĩnh vực này."},{"en":"The task demands a highly skilled and patient team.","vi":"Nhiệm vụ này đòi hỏi một đội ngũ có tay nghề cao và kiên nhẫn."}]','[]',NULL,'/ˈhaɪli ˈskɪld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4313,'colloc-7-01',123,'highly sophisticated','rất tinh vi','adv + adj','[{"en":"The lab uses highly sophisticated equipment for analysis.","vi":"Phòng thí nghiệm dùng thiết bị rất tinh vi để phân tích."},{"en":"Hackers deployed a highly sophisticated attack on the network.","vi":"Tin tặc triển khai một cuộc tấn công rất tinh vi vào mạng."},{"en":"The model relies on highly sophisticated mathematical methods.","vi":"Mô hình dựa trên những phương pháp toán học rất tinh vi."}]','[]',NULL,'/ˈhaɪli səˈfɪstəˌkeɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4314,'colloc-7-01',124,'highly structured','có cấu trúc chặt chẽ','adv + vpp','[{"en":"The program follows a highly structured weekly schedule.","vi":"Chương trình tuân theo một lịch trình hằng tuần có cấu trúc chặt chẽ."},{"en":"Young children often benefit from a highly structured routine.","vi":"Trẻ nhỏ thường hưởng lợi từ một thói quen có cấu trúc chặt chẽ."},{"en":"The interview was highly structured with fixed questions.","vi":"Cuộc phỏng vấn có cấu trúc chặt chẽ với những câu hỏi cố định."}]','[]',NULL,'/ˈhaɪli ˈstrʌktʃərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4315,'colloc-7-01',125,'highly successful','rất thành công','adv + adj','[{"en":"The fundraising campaign was highly successful this year.","vi":"Chiến dịch gây quỹ rất thành công trong năm nay."},{"en":"She built a highly successful career in journalism.","vi":"Cô đã xây dựng một sự nghiệp rất thành công trong báo chí."},{"en":"The treatment has been highly successful in trials.","vi":"Phương pháp điều trị đã rất thành công trong các thử nghiệm."}]','[]',NULL,'/ˈhaɪli səkˈsesfəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4316,'colloc-7-01',126,'highly unlikely','rất khó xảy ra','adv + adj','[{"en":"It is highly unlikely that the experiment will fail.","vi":"Rất khó có khả năng thí nghiệm sẽ thất bại."},{"en":"Such a coincidence is highly unlikely to occur twice.","vi":"Một sự trùng hợp như vậy rất khó xảy ra hai lần."},{"en":"A full recovery by tomorrow seems highly unlikely.","vi":"Việc hồi phục hoàn toàn vào ngày mai có vẻ rất khó xảy ra."}]','[]',NULL,'/ˈhaɪli ʌnˈlaɪkli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4317,'colloc-7-01',127,'highly valued','được coi trọng cao','adv + vpp','[{"en":"Honesty is highly valued in every professional setting.","vi":"Sự trung thực được coi trọng cao trong mọi môi trường nghề nghiệp."},{"en":"Practical experience is highly valued by most employers.","vi":"Kinh nghiệm thực tế được hầu hết nhà tuyển dụng coi trọng cao."},{"en":"Her opinion is highly valued within the research team.","vi":"Ý kiến của cô được coi trọng cao trong nhóm nghiên cứu."}]','[]',NULL,'/ˈhaɪli ˈvæljuːd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4318,'colloc-7-01',128,'highly variable','rất biến thiên','adv + adj','[{"en":"Rainfall in the region is highly variable from year to year.","vi":"Lượng mưa trong khu vực rất biến thiên qua từng năm."},{"en":"Test results were highly variable across the sample.","vi":"Kết quả kiểm tra rất biến thiên trong toàn bộ mẫu."},{"en":"Performance was highly variable depending on the conditions.","vi":"Hiệu suất rất biến thiên tùy thuộc vào điều kiện."}]','[]',NULL,'/ˈhaɪli ˈveriəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4319,'colloc-7-01',129,'historical account','ghi chép lịch sử','adj + n','[{"en":"The book offers a detailed historical account of the war.","vi":"Cuốn sách cung cấp một ghi chép lịch sử chi tiết về cuộc chiến."},{"en":"Her historical account drew on rare archival documents.","vi":"Ghi chép lịch sử của bà dựa trên những tài liệu lưu trữ hiếm."},{"en":"Each historical account reflects the writer''s own perspective.","vi":"Mỗi ghi chép lịch sử phản ánh góc nhìn riêng của người viết."}]','[]',NULL,'/hɪˈstɔːrɪkəl əˈkaʊnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4320,'colloc-7-01',130,'historical analysis','phân tích lịch sử','adj + n','[{"en":"A careful historical analysis reveals long-term economic trends.","vi":"Một phân tích lịch sử cẩn thận cho thấy các xu hướng kinh tế dài hạn."},{"en":"Her thesis combines statistics with historical analysis.","vi":"Luận văn của cô kết hợp thống kê với phân tích lịch sử."},{"en":"Historical analysis helps explain present-day social structures.","vi":"Phân tích lịch sử giúp giải thích các cấu trúc xã hội ngày nay."}]','[]',NULL,'/hɪˈstɔːrɪkəl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4321,'colloc-7-01',131,'historical background','bối cảnh lịch sử','adj + n','[{"en":"The chapter provides the historical background of the conflict.","vi":"Chương này cung cấp bối cảnh lịch sử của cuộc xung đột."},{"en":"Understanding the historical background clarifies the author''s view.","vi":"Hiểu bối cảnh lịch sử giúp làm rõ quan điểm của tác giả."},{"en":"She explained the historical background before the main argument.","vi":"Cô giải thích bối cảnh lịch sử trước khi trình bày lập luận chính."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈbækˌɡraʊnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4322,'colloc-7-01',132,'historical change','sự thay đổi lịch sử','adj + n','[{"en":"The lecture traced major historical change across centuries.","vi":"Bài giảng theo dõi sự thay đổi lịch sử lớn qua nhiều thế kỷ."},{"en":"Technology has driven rapid historical change in society.","vi":"Công nghệ đã thúc đẩy sự thay đổi lịch sử nhanh chóng trong xã hội."},{"en":"Scholars debate the causes of this historical change.","vi":"Các học giả tranh luận về nguyên nhân của sự thay đổi lịch sử này."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈtʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4323,'colloc-7-01',133,'historical circumstances','hoàn cảnh lịch sử','adj + n','[{"en":"The law emerged from very specific historical circumstances.","vi":"Đạo luật ra đời từ những hoàn cảnh lịch sử rất cụ thể."},{"en":"We must judge the decision within its historical circumstances.","vi":"Chúng ta phải đánh giá quyết định trong hoàn cảnh lịch sử của nó."},{"en":"Different historical circumstances shaped each nation''s path.","vi":"Những hoàn cảnh lịch sử khác nhau định hình con đường của mỗi quốc gia."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈsɜːrkəmˌstænsəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4324,'colloc-7-01',134,'historical context','ngữ cảnh lịch sử','adj + n','[{"en":"The poem makes more sense in its historical context.","vi":"Bài thơ trở nên dễ hiểu hơn trong ngữ cảnh lịch sử của nó."},{"en":"Teachers should explain the historical context of each text.","vi":"Giáo viên nên giải thích ngữ cảnh lịch sử của mỗi văn bản."},{"en":"Ignoring the historical context can distort our interpretation.","vi":"Bỏ qua ngữ cảnh lịch sử có thể làm sai lệch cách diễn giải của ta."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4325,'colloc-7-01',135,'historical data','dữ liệu lịch sử','adj + n','[{"en":"Analysts used historical data to forecast future demand.","vi":"Các nhà phân tích dùng dữ liệu lịch sử để dự báo nhu cầu tương lai."},{"en":"The model is trained on decades of historical data.","vi":"Mô hình được huấn luyện trên dữ liệu lịch sử của nhiều thập kỷ."},{"en":"Reliable historical data is essential for accurate predictions.","vi":"Dữ liệu lịch sử đáng tin cậy là thiết yếu cho dự đoán chính xác."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4326,'colloc-7-01',136,'historical development','sự phát triển lịch sử','adj + n','[{"en":"The course traces the historical development of democracy.","vi":"Khóa học theo dõi sự phát triển lịch sử của nền dân chủ."},{"en":"She studied the historical development of modern medicine.","vi":"Cô nghiên cứu sự phát triển lịch sử của y học hiện đại."},{"en":"This map shows the historical development of the city.","vi":"Bản đồ này thể hiện sự phát triển lịch sử của thành phố."}]','[]',NULL,'/hɪˈstɔːrɪkəl dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4327,'colloc-7-01',137,'historical event','sự kiện lịch sử','adj + n','[{"en":"The museum commemorates an important historical event.","vi":"Bảo tàng tưởng niệm một sự kiện lịch sử quan trọng."},{"en":"Each historical event can be interpreted in many ways.","vi":"Mỗi sự kiện lịch sử có thể được diễn giải theo nhiều cách."},{"en":"The novel weaves fiction around a real historical event.","vi":"Cuốn tiểu thuyết đan xen hư cấu quanh một sự kiện lịch sử có thật."}]','[]',NULL,'/hɪˈstɔːrɪkəl ɪˈvent/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4328,'colloc-7-01',138,'historical evidence','bằng chứng lịch sử','adj + n','[{"en":"Strong historical evidence supports the author''s main claim.","vi":"Bằng chứng lịch sử vững chắc ủng hộ luận điểm chính của tác giả."},{"en":"There is little historical evidence for this popular legend.","vi":"Có rất ít bằng chứng lịch sử cho truyền thuyết phổ biến này."},{"en":"Archaeologists gathered historical evidence from the ruins.","vi":"Các nhà khảo cổ thu thập bằng chứng lịch sử từ tàn tích."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈevədəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4329,'colloc-7-01',139,'historical factors','các yếu tố lịch sử','adj + n','[{"en":"Several historical factors explain the region''s poverty.","vi":"Một số yếu tố lịch sử giải thích sự nghèo đói của khu vực."},{"en":"Historical factors continue to shape modern trade patterns.","vi":"Các yếu tố lịch sử tiếp tục định hình các mô hình thương mại hiện đại."},{"en":"The author weighs historical factors against economic ones.","vi":"Tác giả cân nhắc các yếu tố lịch sử so với yếu tố kinh tế."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4330,'colloc-7-01',140,'historical interpretation','cách diễn giải lịch sử','adj + n','[{"en":"Her historical interpretation challenges the traditional view.","vi":"Cách diễn giải lịch sử của bà thách thức quan điểm truyền thống."},{"en":"Every historical interpretation reflects certain assumptions.","vi":"Mọi cách diễn giải lịch sử đều phản ánh những giả định nhất định."},{"en":"The debate centers on competing historical interpretations.","vi":"Cuộc tranh luận xoay quanh những cách diễn giải lịch sử trái ngược."}]','[]',NULL,'/hɪˈstɔːrɪkəl ɪnˌtɜːrprəˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4331,'colloc-7-01',141,'historical knowledge','kiến thức lịch sử','adj + n','[{"en":"Solid historical knowledge helps students analyze sources.","vi":"Kiến thức lịch sử vững chắc giúp học sinh phân tích nguồn tư liệu."},{"en":"The exam tests both historical knowledge and analytical skill.","vi":"Kỳ thi kiểm tra cả kiến thức lịch sử lẫn kỹ năng phân tích."},{"en":"Historical knowledge deepens our understanding of the present.","vi":"Kiến thức lịch sử làm sâu sắc thêm sự hiểu biết của ta về hiện tại."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4332,'colloc-7-01',142,'historical period','giai đoạn lịch sử','adj + n','[{"en":"The exhibition focuses on one specific historical period.","vi":"Triển lãm tập trung vào một giai đoạn lịch sử cụ thể."},{"en":"Art styles vary greatly across each historical period.","vi":"Phong cách nghệ thuật khác nhau rất nhiều qua mỗi giai đoạn lịch sử."},{"en":"She specializes in the historical period after the revolution.","vi":"Bà chuyên về giai đoạn lịch sử sau cuộc cách mạng."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4333,'colloc-7-01',143,'historical perspective','góc nhìn lịch sử','adj + n','[{"en":"A historical perspective helps us understand current conflicts.","vi":"Một góc nhìn lịch sử giúp ta hiểu các xung đột hiện tại."},{"en":"The author writes from a broad historical perspective.","vi":"Tác giả viết từ một góc nhìn lịch sử rộng lớn."},{"en":"From a historical perspective, the policy is not new.","vi":"Xét từ góc nhìn lịch sử, chính sách này không hề mới."}]','[]',NULL,'/hɪˈstɔːrɪkəl pərˈspektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4334,'colloc-7-01',144,'historical reality','thực tế lịch sử','adj + n','[{"en":"The film sometimes departs from historical reality for drama.","vi":"Bộ phim đôi khi rời xa thực tế lịch sử để tạo kịch tính."},{"en":"Myths often blur the line with historical reality.","vi":"Thần thoại thường làm mờ ranh giới với thực tế lịch sử."},{"en":"Historians try to reconstruct historical reality from sources.","vi":"Các sử gia cố tái dựng thực tế lịch sử từ các nguồn tư liệu."}]','[]',NULL,'/hɪˈstɔːrɪkəl riˈæləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4335,'colloc-7-01',145,'historical record','tư liệu lịch sử','adj + n','[{"en":"The historical record contains few details about her life.","vi":"Tư liệu lịch sử chứa rất ít chi tiết về cuộc đời bà."},{"en":"Newspapers form an important part of the historical record.","vi":"Báo chí là một phần quan trọng của tư liệu lịch sử."},{"en":"This document fills a gap in the historical record.","vi":"Tài liệu này lấp đầy một khoảng trống trong tư liệu lịch sử."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈrekərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4336,'colloc-7-01',146,'historical roots','nguồn gốc lịch sử','adj + n','[{"en":"The festival has deep historical roots in the region.","vi":"Lễ hội có nguồn gốc lịch sử sâu xa trong khu vực."},{"en":"The conflict''s historical roots stretch back many centuries.","vi":"Nguồn gốc lịch sử của cuộc xung đột kéo dài nhiều thế kỷ."},{"en":"Understanding its historical roots clarifies the tradition.","vi":"Hiểu nguồn gốc lịch sử giúp làm rõ truyền thống này."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈruːts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4337,'colloc-7-01',147,'historical study','nghiên cứu lịch sử','adj + n','[{"en":"Her historical study examines trade in the medieval era.","vi":"Nghiên cứu lịch sử của bà khảo sát thương mại thời trung cổ."},{"en":"A thorough historical study requires patient archival work.","vi":"Một nghiên cứu lịch sử kỹ lưỡng đòi hỏi việc lưu trữ kiên nhẫn."},{"en":"The historical study won an award for original research.","vi":"Nghiên cứu lịch sử này đã đoạt giải vì tính sáng tạo."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4338,'colloc-7-01',148,'historical writing','lối viết sử, trước tác lịch sử','adj + n','[{"en":"Good historical writing balances evidence with clear narrative.","vi":"Lối viết sử hay cân bằng giữa bằng chứng và lời kể rõ ràng."},{"en":"The course explores changing styles of historical writing.","vi":"Khóa học khám phá những phong cách viết sử đang thay đổi."},{"en":"Her historical writing is admired for its lively prose.","vi":"Trước tác lịch sử của bà được ngưỡng mộ vì văn phong sống động."}]','[]',NULL,'/hɪˈstɔːrɪkəl ˈraɪtɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4339,'colloc-7-01',149,'historically specific','mang tính đặc thù lịch sử','adv + adj','[{"en":"These ideas are historically specific to the modern era.","vi":"Những ý tưởng này mang tính đặc thù lịch sử của thời hiện đại."},{"en":"Such practices are historically specific and not universal.","vi":"Những thực hành như vậy mang tính đặc thù lịch sử, không phổ quát."},{"en":"The author treats gender roles as historically specific.","vi":"Tác giả coi vai trò giới như điều mang tính đặc thù lịch sử."}]','[]',NULL,'/hɪˈstɔːrɪkli spəˈsɪfɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4340,'colloc-7-01',150,'hold a conference','tổ chức một hội nghị','v + n','[{"en":"The university plans to hold a conference on climate policy.","vi":"Trường đại học dự định tổ chức một hội nghị về chính sách khí hậu."},{"en":"They will hold a conference to present the new findings.","vi":"Họ sẽ tổ chức một hội nghị để trình bày các phát hiện mới."},{"en":"The institute holds a conference every spring for researchers.","vi":"Viện tổ chức một hội nghị mỗi mùa xuân cho các nhà nghiên cứu."}]','[]',NULL,'/ˈhoʊld ə ˈkɑːnfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4341,'colloc-8-01',1,'holistic approach','cách tiếp cận toàn diện','adj + n','[{"en":"The clinic takes a holistic approach to patient care.","vi":"Phòng khám áp dụng cách tiếp cận toàn diện trong chăm sóc bệnh nhân."},{"en":"A holistic approach considers both mind and body together.","vi":"Cách tiếp cận toàn diện xem xét cả tâm trí lẫn cơ thể cùng nhau."},{"en":"Teachers favor a holistic approach to student development.","vi":"Giáo viên ưa chuộng cách tiếp cận toàn diện cho sự phát triển của học sinh."}]','[]',NULL,'/hoʊˈlɪstɪk əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4342,'colloc-8-01',2,'homogeneous group','nhóm đồng nhất','adj + n','[{"en":"The study compared a homogeneous group with a diverse one.","vi":"Nghiên cứu so sánh một nhóm đồng nhất với một nhóm đa dạng."},{"en":"Researchers selected a homogeneous group to reduce variation.","vi":"Các nhà nghiên cứu chọn một nhóm đồng nhất để giảm sự biến thiên."},{"en":"No society is truly a homogeneous group of people.","vi":"Không có xã hội nào thực sự là một nhóm người đồng nhất."}]','[]',NULL,'/ˌhoʊməˈdʒiːniəs ˈɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4343,'colloc-8-01',3,'huge amount of','một lượng khổng lồ','adj + n','[{"en":"The project generated a huge amount of useful data.","vi":"Dự án tạo ra một lượng dữ liệu hữu ích khổng lồ."},{"en":"Writing the thesis required a huge amount of effort.","vi":"Viết luận văn đòi hỏi một lượng nỗ lực khổng lồ."},{"en":"A huge amount of waste ends up in the ocean.","vi":"Một lượng rác khổng lồ cuối cùng trôi ra đại dương."}]','[]',NULL,'/ˈhjuːdʒ əˈmaʊnt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4344,'colloc-8-01',4,'human activity','hoạt động của con người','adj + n','[{"en":"Human activity is a major cause of climate change.","vi":"Hoạt động của con người là nguyên nhân chính gây biến đổi khí hậu."},{"en":"Satellites monitor human activity across the planet.","vi":"Vệ tinh theo dõi hoạt động của con người trên khắp hành tinh."},{"en":"Much human activity leaves a lasting mark on nature.","vi":"Nhiều hoạt động của con người để lại dấu ấn lâu dài lên thiên nhiên."}]','[]',NULL,'/ˈhjuːmən ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4345,'colloc-8-01',5,'human behavior','hành vi của con người','adj + n','[{"en":"Psychology seeks to explain patterns of human behavior.","vi":"Tâm lý học tìm cách giải thích các khuôn mẫu hành vi của con người."},{"en":"Economic models often simplify complex human behavior.","vi":"Các mô hình kinh tế thường đơn giản hóa hành vi phức tạp của con người."},{"en":"Culture strongly influences everyday human behavior.","vi":"Văn hóa ảnh hưởng mạnh đến hành vi thường ngày của con người."}]','[]',NULL,'/ˈhjuːmən bɪˈheɪvjər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4346,'colloc-8-01',6,'human interaction','tương tác giữa người với người','adj + n','[{"en":"Technology has changed the nature of human interaction.","vi":"Công nghệ đã thay đổi bản chất của tương tác giữa người với người."},{"en":"Face-to-face human interaction supports emotional well-being.","vi":"Tương tác trực tiếp giữa người với người hỗ trợ sức khỏe tinh thần."},{"en":"The study observed human interaction in public spaces.","vi":"Nghiên cứu quan sát tương tác giữa người với người ở nơi công cộng."}]','[]',NULL,'/ˈhjuːmən ˌɪntərˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4347,'colloc-8-01',7,'human society','xã hội loài người','adj + n','[{"en":"Language is fundamental to the development of human society.","vi":"Ngôn ngữ là nền tảng cho sự phát triển của xã hội loài người."},{"en":"Cooperation has shaped human society throughout history.","vi":"Sự hợp tác đã định hình xã hội loài người suốt chiều dài lịch sử."},{"en":"Technology continues to transform human society rapidly.","vi":"Công nghệ tiếp tục biến đổi xã hội loài người một cách nhanh chóng."}]','[]',NULL,'/ˈhjuːmən səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4348,'colloc-8-01',8,'human species','loài người','adj + n','[{"en":"The human species has spread across nearly every continent.","vi":"Loài người đã lan rộng khắp gần như mọi lục địa."},{"en":"Climate change poses a real threat to the human species.","vi":"Biến đổi khí hậu đặt ra mối đe dọa thực sự cho loài người."},{"en":"The human species evolved over hundreds of thousands of years.","vi":"Loài người tiến hóa qua hàng trăm nghìn năm."}]','[]',NULL,'/ˈhjuːmən ˈspiːʃiːz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4349,'colloc-8-01',9,'ideally suited','rất phù hợp một cách lý tưởng','adv + vpp','[{"en":"Her background makes her ideally suited for the role.","vi":"Nền tảng của cô khiến cô rất phù hợp một cách lý tưởng cho vai trò này."},{"en":"The climate is ideally suited to growing grapes.","vi":"Khí hậu rất lý tưởng để trồng nho."},{"en":"This tool is ideally suited for analyzing large datasets.","vi":"Công cụ này rất phù hợp lý tưởng để phân tích các tập dữ liệu lớn."}]','[]',NULL,'/aɪˈdiːəli ˈsuːtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4350,'colloc-8-01',10,'identify factors','xác định các yếu tố','v + n','[{"en":"The study aims to identify factors that affect performance.","vi":"Nghiên cứu nhằm xác định các yếu tố ảnh hưởng đến hiệu suất."},{"en":"Researchers tried to identify factors behind the decline.","vi":"Các nhà nghiên cứu cố xác định các yếu tố đằng sau sự suy giảm."},{"en":"It is hard to identify factors that act together.","vi":"Thật khó để xác định các yếu tố cùng tác động với nhau."}]','[]',NULL,'/aɪˈdentəˌfaɪ ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4351,'colloc-8-01',11,'identify features','xác định các đặc điểm','v + n','[{"en":"Students learn to identify features of academic texts.","vi":"Học sinh học cách xác định các đặc điểm của văn bản học thuật."},{"en":"The software can identify features in medical images.","vi":"Phần mềm có thể xác định các đặc điểm trong ảnh y khoa."},{"en":"We first identify features common to all the samples.","vi":"Trước tiên chúng tôi xác định các đặc điểm chung của mọi mẫu."}]','[]',NULL,'/aɪˈdentəˌfaɪ ˈfiːtʃərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4352,'colloc-8-01',12,'identify a problem','xác định một vấn đề','v + n','[{"en":"The first step is to identify a problem clearly.","vi":"Bước đầu tiên là xác định một vấn đề một cách rõ ràng."},{"en":"Engineers worked quickly to identify a problem in the system.","vi":"Các kỹ sư làm việc nhanh chóng để xác định một vấn đề trong hệ thống."},{"en":"Good researchers identify a problem worth solving.","vi":"Nhà nghiên cứu giỏi xác định một vấn đề đáng giải quyết."}]','[]',NULL,'/aɪˈdentəˌfaɪ ə ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4353,'colloc-8-01',13,'identify a way','tìm ra một cách','v + n','[{"en":"The team hopes to identify a way to cut costs.","vi":"Nhóm hy vọng tìm ra một cách để cắt giảm chi phí."},{"en":"Scientists must identify a way to test the hypothesis.","vi":"Các nhà khoa học phải tìm ra một cách để kiểm tra giả thuyết."},{"en":"We need to identify a way to engage younger readers.","vi":"Chúng ta cần tìm ra một cách để thu hút độc giả trẻ hơn."}]','[]',NULL,'/aɪˈdentəˌfaɪ ə ˈweɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4354,'colloc-8-01',14,'identify an area','xác định một lĩnh vực','v + n','[{"en":"The review helped identify an area needing more research.","vi":"Bài tổng quan giúp xác định một lĩnh vực cần nghiên cứu thêm."},{"en":"Managers should identify an area for immediate improvement.","vi":"Quản lý nên xác định một lĩnh vực cần cải thiện ngay."},{"en":"She tried to identify an area where she could specialize.","vi":"Cô cố xác định một lĩnh vực mà mình có thể chuyên sâu."}]','[]',NULL,'/aɪˈdentəˌfaɪ ən ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4355,'colloc-8-01',15,'identify an issue','xác định một vấn đề','v + n','[{"en":"The audit helped identify an issue with the accounts.","vi":"Cuộc kiểm toán giúp xác định một vấn đề với các tài khoản."},{"en":"It is important to identify an issue before it grows.","vi":"Điều quan trọng là xác định một vấn đề trước khi nó lớn lên."},{"en":"Teachers can identify an issue early through regular feedback.","vi":"Giáo viên có thể xác định một vấn đề sớm qua phản hồi thường xuyên."}]','[]',NULL,'/aɪˈdentəˌfaɪ ən ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4356,'colloc-8-01',16,'immediate environment','môi trường xung quanh trực tiếp','adj + n','[{"en":"Children learn quickly from their immediate environment.","vi":"Trẻ em học hỏi nhanh từ môi trường xung quanh trực tiếp."},{"en":"The study focused on the cell''s immediate environment.","vi":"Nghiên cứu tập trung vào môi trường trực tiếp quanh tế bào."},{"en":"We adapt our behavior to the immediate environment.","vi":"Chúng ta điều chỉnh hành vi theo môi trường xung quanh trực tiếp."}]','[]',NULL,'/ɪˈmiːdiət ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4357,'colloc-8-01',17,'immediately apparent','rõ ràng ngay lập tức','adv + adj','[{"en":"The cause of the error was not immediately apparent.","vi":"Nguyên nhân của lỗi không rõ ràng ngay lập tức."},{"en":"The benefits became immediately apparent after the change.","vi":"Lợi ích trở nên rõ ràng ngay lập tức sau khi thay đổi."},{"en":"It was immediately apparent that the data was flawed.","vi":"Rõ ràng ngay lập tức rằng dữ liệu có sai sót."}]','[]',NULL,'/ɪˈmiːdiətli əˈpærənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4358,'colloc-8-01',18,'immediately following','ngay sau đó','adv + adj','[{"en":"Sales dropped in the weeks immediately following the news.","vi":"Doanh số giảm trong những tuần ngay sau khi tin tức xuất hiện."},{"en":"The discussion took place immediately following the lecture.","vi":"Cuộc thảo luận diễn ra ngay sau buổi giảng."},{"en":"In the period immediately following the war, prices rose.","vi":"Trong giai đoạn ngay sau chiến tranh, giá cả tăng lên."}]','[]',NULL,'/ɪˈmiːdiətli ˈfɑːloʊɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4359,'colloc-8-01',19,'immediately obvious','hiển nhiên ngay lập tức','adv + adj','[{"en":"The solution was not immediately obvious to the students.","vi":"Giải pháp không hiển nhiên ngay lập tức đối với học sinh."},{"en":"It is immediately obvious that the two graphs differ.","vi":"Hiển nhiên ngay lập tức rằng hai đồ thị này khác nhau."},{"en":"The flaw becomes immediately obvious when tested properly.","vi":"Khiếm khuyết trở nên hiển nhiên ngay khi được kiểm tra đúng cách."}]','[]',NULL,'/ɪˈmiːdiətli ˈɑːbviəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4360,'colloc-8-01',20,'immediately preceding','ngay trước đó','adv + adj','[{"en":"The years immediately preceding the crisis saw rapid growth.","vi":"Những năm ngay trước cuộc khủng hoảng chứng kiến tăng trưởng nhanh."},{"en":"Refer to the paragraph immediately preceding this section.","vi":"Hãy xem đoạn văn ngay trước phần này."},{"en":"Events immediately preceding the vote shaped the outcome.","vi":"Những sự kiện ngay trước cuộc bỏ phiếu đã định hình kết quả."}]','[]',NULL,'/ɪˈmiːdiətli prɪˈsiːdɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4361,'colloc-8-01',21,'imported goods','hàng hóa nhập khẩu','adj + n','[{"en":"Tariffs raised the price of many imported goods.","vi":"Thuế quan làm tăng giá của nhiều hàng hóa nhập khẩu."},{"en":"Consumers increasingly prefer cheaper imported goods.","vi":"Người tiêu dùng ngày càng ưa chuộng hàng nhập khẩu rẻ hơn."},{"en":"The country relies heavily on imported goods and fuel.","vi":"Quốc gia này phụ thuộc nhiều vào hàng hóa và nhiên liệu nhập khẩu."}]','[]',NULL,'/ɪmˈpɔːrtɪd ˈɡʊdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4362,'colloc-8-01',22,'imported products','sản phẩm nhập khẩu','adj + n','[{"en":"Imported products often face strict safety inspections.","vi":"Sản phẩm nhập khẩu thường phải qua kiểm tra an toàn nghiêm ngặt."},{"en":"Local firms struggle to compete with imported products.","vi":"Các công ty trong nước chật vật cạnh tranh với sản phẩm nhập khẩu."},{"en":"Demand for imported products grew steadily last year.","vi":"Nhu cầu về sản phẩm nhập khẩu tăng đều đặn trong năm ngoái."}]','[]',NULL,'/ɪmˈpɔːrtɪd ˈprɑːdʌkts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4363,'colloc-8-01',23,'impose constraints','áp đặt những ràng buộc','v + n','[{"en":"Limited funding can impose constraints on the research design.","vi":"Kinh phí hạn chế có thể áp đặt những ràng buộc lên thiết kế nghiên cứu."},{"en":"New regulations impose constraints on how data is shared.","vi":"Các quy định mới áp đặt những ràng buộc về cách chia sẻ dữ liệu."},{"en":"Time pressure imposes constraints on what we can achieve.","vi":"Áp lực thời gian áp đặt những ràng buộc lên điều ta có thể đạt được."}]','[]',NULL,'/ɪmˈpoʊz kənˈstreɪnts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4364,'colloc-8-01',24,'impose limitations','áp đặt những hạn chế','v + n','[{"en":"The small sample size imposes limitations on the conclusions.","vi":"Cỡ mẫu nhỏ áp đặt những hạn chế lên các kết luận."},{"en":"Budget cuts impose limitations on the program''s scope.","vi":"Việc cắt giảm ngân sách áp đặt những hạn chế lên phạm vi chương trình."},{"en":"Physical laws impose limitations on what engines can do.","vi":"Các định luật vật lý áp đặt những hạn chế lên khả năng của động cơ."}]','[]',NULL,'/ɪmˈpoʊz ˌlɪmɪˈteɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4365,'colloc-8-01',25,'impose restrictions','áp đặt các hạn chế','v + n','[{"en":"The government decided to impose restrictions on water usage.","vi":"Chính phủ quyết định áp đặt các hạn chế về việc dùng nước."},{"en":"Schools may impose restrictions on the use of phones.","vi":"Trường học có thể áp đặt hạn chế về việc dùng điện thoại."},{"en":"Authorities often impose restrictions to protect public health.","vi":"Nhà chức trách thường áp đặt hạn chế để bảo vệ sức khỏe cộng đồng."}]','[]',NULL,'/ɪmˈpoʊz rɪˈstrɪkʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4366,'colloc-8-01',26,'improved performance','hiệu suất được cải thiện','adj + n','[{"en":"The new training led to improved performance across the team.","vi":"Việc đào tạo mới giúp hiệu suất của cả đội được cải thiện."},{"en":"Researchers measured improved performance after the software update.","vi":"Các nhà nghiên cứu đo được hiệu suất cải thiện sau khi cập nhật phần mềm."},{"en":"Students showed improved performance once they studied regularly.","vi":"Học sinh có hiệu suất cải thiện khi học đều đặn hơn."}]','[]',NULL,'/ɪmˈpruːvd pərˈfɔːrməns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4367,'colloc-8-01',27,'increase awareness','nâng cao nhận thức','v + n','[{"en":"The campaign aims to increase awareness of climate change.","vi":"Chiến dịch nhằm nâng cao nhận thức về biến đổi khí hậu."},{"en":"Schools work hard to increase awareness about online safety.","vi":"Các trường nỗ lực nâng cao nhận thức về an toàn trực tuyến."},{"en":"Posters were used to increase awareness among local residents.","vi":"Áp phích được dùng để nâng cao nhận thức cho cư dân địa phương."}]','[]',NULL,'/ɪnˈkriːs əˈwernəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4368,'colloc-8-01',28,'increase dramatically','tăng lên đáng kể','v + adv','[{"en":"House prices increase dramatically when demand outpaces supply.","vi":"Giá nhà tăng đáng kể khi nhu cầu vượt nguồn cung."},{"en":"Sales tend to increase dramatically during the holiday season.","vi":"Doanh số thường tăng đáng kể trong mùa lễ."},{"en":"Pollution levels can increase dramatically in crowded cities.","vi":"Mức ô nhiễm có thể tăng đáng kể ở các thành phố đông đúc."}]','[]',NULL,'/ɪnˈkriːs drəˈmætɪkli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4369,'colloc-8-01',29,'increase likelihood','làm tăng khả năng xảy ra','v + n','[{"en":"Regular exercise can increase the likelihood of better health.","vi":"Tập thể dục đều đặn có thể làm tăng khả năng có sức khỏe tốt."},{"en":"Careful planning will increase the likelihood of project success.","vi":"Lập kế hoạch cẩn thận sẽ làm tăng khả năng thành công của dự án."},{"en":"Poor diet may increase the likelihood of serious illness.","vi":"Chế độ ăn kém có thể làm tăng khả năng mắc bệnh nặng."}]','[]',NULL,'/ɪnˈkriːs ˈlaɪkliˌhʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4370,'colloc-8-01',30,'increased awareness','nhận thức gia tăng','adj + n','[{"en":"Increased awareness of recycling has reduced household waste.","vi":"Nhận thức gia tăng về tái chế đã giảm rác thải sinh hoạt."},{"en":"The study reports increased awareness of mental health issues.","vi":"Nghiên cứu cho thấy nhận thức gia tăng về vấn đề sức khỏe tâm thần."},{"en":"Increased awareness among voters changed the election outcome.","vi":"Nhận thức gia tăng của cử tri đã thay đổi kết quả bầu cử."}]','[]',NULL,'/ɪnˈkriːst əˈwernəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4371,'colloc-8-01',31,'increased competition','sự cạnh tranh gia tăng','adj + n','[{"en":"Increased competition forced companies to lower their prices.","vi":"Sự cạnh tranh gia tăng buộc các công ty hạ giá."},{"en":"Global markets face increased competition from new firms.","vi":"Thị trường toàn cầu đối mặt cạnh tranh gia tăng từ các hãng mới."},{"en":"Increased competition often drives faster innovation.","vi":"Cạnh tranh gia tăng thường thúc đẩy đổi mới nhanh hơn."}]','[]',NULL,'/ɪnˈkriːst ˌkɑːmpəˈtɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4372,'colloc-8-01',32,'increased demand','nhu cầu gia tăng','adj + n','[{"en":"Increased demand for housing pushed rents much higher.","vi":"Nhu cầu gia tăng về nhà ở đẩy tiền thuê lên cao."},{"en":"The factory expanded to meet increased demand for goods.","vi":"Nhà máy mở rộng để đáp ứng nhu cầu gia tăng về hàng hóa."},{"en":"Increased demand for energy strains the national grid.","vi":"Nhu cầu gia tăng về năng lượng gây áp lực lên lưới điện quốc gia."}]','[]',NULL,'/ɪnˈkriːst dɪˈmænd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4373,'colloc-8-01',33,'increased importance','tầm quan trọng gia tăng','adj + n','[{"en":"The increased importance of data has reshaped modern business.","vi":"Tầm quan trọng gia tăng của dữ liệu đã định hình lại kinh doanh hiện đại."},{"en":"Researchers note the increased importance of soft skills.","vi":"Các nhà nghiên cứu lưu ý tầm quan trọng gia tăng của kỹ năng mềm."},{"en":"Climate policy reflects the increased importance of sustainability.","vi":"Chính sách khí hậu phản ánh tầm quan trọng gia tăng của tính bền vững."}]','[]',NULL,'/ɪnˈkriːst ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4374,'colloc-8-01',34,'increased interest','sự quan tâm gia tăng','adj + n','[{"en":"There is increased interest in learning languages online.","vi":"Có sự quan tâm gia tăng đến việc học ngôn ngữ trực tuyến."},{"en":"The museum saw increased interest after the new exhibit opened.","vi":"Bảo tàng có sự quan tâm gia tăng sau khi mở triển lãm mới."},{"en":"Increased interest in healthy food boosted organic sales.","vi":"Sự quan tâm gia tăng đến thực phẩm lành mạnh thúc đẩy doanh số hữu cơ."}]','[]',NULL,'/ɪnˈkriːst ˈɪntrəst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4375,'colloc-8-01',35,'increased level','mức độ gia tăng','adj + n','[{"en":"Doctors observed an increased level of stress among students.","vi":"Bác sĩ ghi nhận mức độ căng thẳng gia tăng ở học sinh."},{"en":"An increased level of activity improves overall fitness.","vi":"Mức độ vận động gia tăng cải thiện thể lực tổng thể."},{"en":"The report shows an increased level of public spending.","vi":"Báo cáo cho thấy mức độ chi tiêu công gia tăng."}]','[]',NULL,'/ɪnˈkriːst ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4376,'colloc-8-01',36,'increased number','số lượng gia tăng','adj + n','[{"en":"An increased number of students enrolled in online courses.","vi":"Số lượng học sinh đăng ký khóa học trực tuyến gia tăng."},{"en":"The city recorded an increased number of cycling commuters.","vi":"Thành phố ghi nhận số lượng người đi xe đạp gia tăng."},{"en":"An increased number of firms now offer remote work.","vi":"Số lượng công ty cung cấp làm việc từ xa hiện đã gia tăng."}]','[]',NULL,'/ɪnˈkriːst ˈnʌmbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4377,'colloc-8-01',37,'increased pressure','áp lực gia tăng','adj + n','[{"en":"Increased pressure at work left many employees exhausted.","vi":"Áp lực gia tăng tại nơi làm việc khiến nhiều nhân viên kiệt sức."},{"en":"Farmers face increased pressure from changing weather patterns.","vi":"Nông dân đối mặt áp lực gia tăng từ thời tiết thay đổi."},{"en":"Increased pressure on resources demands smarter planning.","vi":"Áp lực gia tăng lên tài nguyên đòi hỏi lập kế hoạch thông minh hơn."}]','[]',NULL,'/ɪnˈkriːst ˈpreʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4378,'colloc-8-01',38,'increased production','sản lượng gia tăng','adj + n','[{"en":"Increased production helped the company meet rising demand.","vi":"Sản lượng gia tăng giúp công ty đáp ứng nhu cầu tăng cao."},{"en":"New machines allowed increased production at the plant.","vi":"Máy móc mới cho phép sản lượng gia tăng tại nhà máy."},{"en":"Increased production of solar panels lowered their cost.","vi":"Sản lượng gia tăng của tấm pin mặt trời làm giảm giá thành."}]','[]',NULL,'/ɪnˈkriːst prəˈdʌkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4379,'colloc-8-01',39,'increased productivity','năng suất gia tăng','adj + n','[{"en":"Flexible hours led to increased productivity among staff.","vi":"Giờ làm linh hoạt dẫn đến năng suất gia tăng của nhân viên."},{"en":"Better tools resulted in increased productivity for the team.","vi":"Công cụ tốt hơn mang lại năng suất gia tăng cho cả đội."},{"en":"Training programs are linked to increased productivity overall.","vi":"Các chương trình đào tạo gắn liền với năng suất gia tăng nói chung."}]','[]',NULL,'/ɪnˈkriːst ˌproʊdʌkˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4380,'colloc-8-01',40,'increased risk','nguy cơ gia tăng','adj + n','[{"en":"Smoking is linked to an increased risk of heart disease.","vi":"Hút thuốc gắn liền với nguy cơ gia tăng mắc bệnh tim."},{"en":"Poor diet brings an increased risk of long-term illness.","vi":"Chế độ ăn kém mang lại nguy cơ gia tăng mắc bệnh lâu dài."},{"en":"Climate change creates an increased risk of severe floods.","vi":"Biến đổi khí hậu tạo ra nguy cơ gia tăng về lũ lụt nghiêm trọng."}]','[]',NULL,'/ɪnˈkriːst rɪsk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4381,'colloc-8-01',41,'increasing awareness','nhận thức ngày càng tăng','adj + n','[{"en":"There is increasing awareness of the dangers of plastic.","vi":"Có nhận thức ngày càng tăng về mối nguy của nhựa."},{"en":"Increasing awareness of nutrition has changed eating habits.","vi":"Nhận thức ngày càng tăng về dinh dưỡng đã thay đổi thói quen ăn uống."},{"en":"The media plays a role in increasing awareness of disease.","vi":"Truyền thông góp phần làm nhận thức về bệnh tật ngày càng tăng."}]','[]',NULL,'/ɪnˈkriːsɪŋ əˈwernəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4382,'colloc-8-01',42,'increasing complexity','sự phức tạp ngày càng tăng','adj + n','[{"en":"The increasing complexity of software makes testing harder.","vi":"Sự phức tạp ngày càng tăng của phần mềm khiến kiểm thử khó hơn."},{"en":"Global trade reflects the increasing complexity of economies.","vi":"Thương mại toàn cầu phản ánh sự phức tạp ngày càng tăng của các nền kinh tế."},{"en":"Students struggle with the increasing complexity of the syllabus.","vi":"Học sinh vật lộn với sự phức tạp ngày càng tăng của chương trình học."}]','[]',NULL,'/ɪnˈkriːsɪŋ kəmˈpleksəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4383,'colloc-8-01',43,'increasing demand','nhu cầu ngày càng tăng','adj + n','[{"en":"Increasing demand for electric cars is reshaping the industry.","vi":"Nhu cầu ngày càng tăng về xe điện đang định hình lại ngành."},{"en":"Hospitals face increasing demand for skilled nurses.","vi":"Bệnh viện đối mặt nhu cầu ngày càng tăng về y tá lành nghề."},{"en":"Increasing demand for clean water threatens scarce supplies.","vi":"Nhu cầu ngày càng tăng về nước sạch đe dọa nguồn cung khan hiếm."}]','[]',NULL,'/ɪnˈkriːsɪŋ dɪˈmænd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4384,'colloc-8-01',44,'increasing emphasis','sự nhấn mạnh ngày càng tăng','adj + n','[{"en":"There is increasing emphasis on practical skills in schools.","vi":"Có sự nhấn mạnh ngày càng tăng vào kỹ năng thực hành trong trường học."},{"en":"Companies place increasing emphasis on customer satisfaction.","vi":"Các công ty ngày càng nhấn mạnh vào sự hài lòng của khách hàng."},{"en":"The increasing emphasis on data drives many new policies.","vi":"Sự nhấn mạnh ngày càng tăng vào dữ liệu thúc đẩy nhiều chính sách mới."}]','[]',NULL,'/ɪnˈkriːsɪŋ ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4385,'colloc-8-01',45,'increasing importance','tầm quan trọng ngày càng tăng','adj + n','[{"en":"The increasing importance of English shapes career choices.","vi":"Tầm quan trọng ngày càng tăng của tiếng Anh định hình lựa chọn nghề nghiệp."},{"en":"Educators stress the increasing importance of digital literacy.","vi":"Nhà giáo dục nhấn mạnh tầm quan trọng ngày càng tăng của hiểu biết số."},{"en":"Reports highlight the increasing importance of renewable energy.","vi":"Các báo cáo nêu bật tầm quan trọng ngày càng tăng của năng lượng tái tạo."}]','[]',NULL,'/ɪnˈkriːsɪŋ ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4386,'colloc-8-01',46,'increasing interest','sự quan tâm ngày càng tăng','adj + n','[{"en":"There is increasing interest in studying abroad among teenagers.","vi":"Có sự quan tâm ngày càng tăng đến du học trong giới thanh thiếu niên."},{"en":"Scientists show increasing interest in deep-sea exploration.","vi":"Các nhà khoa học ngày càng quan tâm đến khám phá biển sâu."},{"en":"Increasing interest in vegan food expanded the menu options.","vi":"Sự quan tâm ngày càng tăng đến đồ ăn thuần chay mở rộng thực đơn."}]','[]',NULL,'/ɪnˈkriːsɪŋ ˈɪntrəst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4387,'colloc-8-01',47,'increasing pressure','áp lực ngày càng tăng','adj + n','[{"en":"Teachers face increasing pressure to improve exam results.","vi":"Giáo viên đối mặt áp lực ngày càng tăng để cải thiện kết quả thi."},{"en":"Increasing pressure on the budget forced difficult cuts.","vi":"Áp lực ngày càng tăng lên ngân sách buộc phải cắt giảm khó khăn."},{"en":"Athletes work under increasing pressure to break records.","vi":"Vận động viên làm việc dưới áp lực ngày càng tăng để phá kỷ lục."}]','[]',NULL,'/ɪnˈkriːsɪŋ ˈpreʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4388,'colloc-8-01',48,'increasing proportion of','tỷ lệ ngày càng tăng của','adj + n','[{"en":"An increasing proportion of workers now telecommute from home.","vi":"Một tỷ lệ ngày càng tăng của người lao động nay làm việc từ xa tại nhà."},{"en":"An increasing proportion of energy comes from renewable sources.","vi":"Một tỷ lệ ngày càng tăng của năng lượng đến từ nguồn tái tạo."},{"en":"An increasing proportion of students choose science subjects.","vi":"Một tỷ lệ ngày càng tăng của học sinh chọn các môn khoa học."}]','[]',NULL,'/ɪnˈkriːsɪŋ prəˈpɔːrʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4389,'colloc-8-01',49,'increasing tendency','xu hướng ngày càng tăng','adj + n','[{"en":"There is an increasing tendency to shop entirely online.","vi":"Có một xu hướng ngày càng tăng là mua sắm hoàn toàn trực tuyến."},{"en":"Researchers note an increasing tendency toward remote learning.","vi":"Các nhà nghiên cứu lưu ý xu hướng ngày càng tăng hướng tới học từ xa."},{"en":"An increasing tendency to delay marriage is widely observed.","vi":"Xu hướng ngày càng tăng là trì hoãn kết hôn được ghi nhận rộng rãi."}]','[]',NULL,'/ɪnˈkriːsɪŋ ˈtendənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4390,'colloc-8-01',50,'increasing trend','xu thế ngày càng tăng','adj + n','[{"en":"The data reveals an increasing trend in global temperatures.","vi":"Dữ liệu cho thấy một xu thế ngày càng tăng của nhiệt độ toàn cầu."},{"en":"There is an increasing trend toward plant-based diets.","vi":"Có một xu thế ngày càng tăng hướng tới chế độ ăn từ thực vật."},{"en":"Analysts highlight an increasing trend in online payments.","vi":"Các nhà phân tích nêu bật xu thế ngày càng tăng của thanh toán trực tuyến."}]','[]',NULL,'/ɪnˈkriːsɪŋ trend/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4391,'colloc-8-01',51,'increasingly aware','ngày càng nhận thức rõ','adv + adj','[{"en":"Consumers are increasingly aware of the products they buy.","vi":"Người tiêu dùng ngày càng nhận thức rõ về sản phẩm họ mua."},{"en":"Citizens have become increasingly aware of their legal rights.","vi":"Người dân ngày càng nhận thức rõ về quyền pháp lý của mình."},{"en":"Companies are increasingly aware of their environmental impact.","vi":"Các công ty ngày càng nhận thức rõ về tác động môi trường của họ."}]','[]',NULL,'/ɪnˈkriːsɪŋli əˈwer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4392,'colloc-8-01',52,'increasingly common','ngày càng phổ biến','adv + adj','[{"en":"Remote work has become increasingly common in recent years.","vi":"Làm việc từ xa đã trở nên ngày càng phổ biến trong những năm gần đây."},{"en":"Electric vehicles are increasingly common on city streets.","vi":"Xe điện ngày càng phổ biến trên đường phố thành phố."},{"en":"Online courses are increasingly common at most universities.","vi":"Khóa học trực tuyến ngày càng phổ biến tại hầu hết các trường đại học."}]','[]',NULL,'/ɪnˈkriːsɪŋli ˈkɑːmən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4393,'colloc-8-01',53,'increasingly complex','ngày càng phức tạp','adv + adj','[{"en":"Modern supply chains have grown increasingly complex worldwide.","vi":"Chuỗi cung ứng hiện đại đã trở nên ngày càng phức tạp trên toàn cầu."},{"en":"The legal system can seem increasingly complex to ordinary people.","vi":"Hệ thống pháp luật có thể trở nên ngày càng phức tạp với người thường."},{"en":"Software architecture becomes increasingly complex as it grows.","vi":"Kiến trúc phần mềm trở nên ngày càng phức tạp khi mở rộng."}]','[]',NULL,'/ɪnˈkriːsɪŋli kəmˈpleks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4394,'colloc-8-01',54,'increasingly difficult','ngày càng khó khăn','adv + adj','[{"en":"It is increasingly difficult to find affordable housing nearby.","vi":"Ngày càng khó khăn để tìm nhà ở giá phải chăng gần đây."},{"en":"Saving money becomes increasingly difficult as prices rise.","vi":"Việc tiết kiệm tiền trở nên ngày càng khó khăn khi giá tăng."},{"en":"Maintaining focus is increasingly difficult with constant notifications.","vi":"Việc giữ tập trung ngày càng khó khăn với thông báo liên tục."}]','[]',NULL,'/ɪnˈkriːsɪŋli ˈdɪfɪkəlt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4395,'colloc-8-01',55,'increasingly important','ngày càng quan trọng','adv + adj','[{"en":"Digital skills are increasingly important in the job market.","vi":"Kỹ năng số ngày càng quan trọng trong thị trường lao động."},{"en":"Sustainability has become increasingly important to investors.","vi":"Tính bền vững đã trở nên ngày càng quan trọng với nhà đầu tư."},{"en":"Teamwork is increasingly important in research projects.","vi":"Làm việc nhóm ngày càng quan trọng trong các dự án nghiên cứu."}]','[]',NULL,'/ɪnˈkriːsɪŋli ɪmˈpɔːrtənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4396,'colloc-8-01',56,'increasingly popular','ngày càng được ưa chuộng','adv + adj','[{"en":"Cycling has become increasingly popular among young commuters.","vi":"Đi xe đạp ngày càng được ưa chuộng trong giới đi làm trẻ tuổi."},{"en":"Plant-based meals are increasingly popular in restaurants.","vi":"Bữa ăn từ thực vật ngày càng được ưa chuộng tại nhà hàng."},{"en":"Podcasts are increasingly popular as a way to learn.","vi":"Podcast ngày càng được ưa chuộng như một cách để học."}]','[]',NULL,'/ɪnˈkriːsɪŋli ˈpɑːpjələr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4397,'colloc-8-01',57,'increasingly sophisticated','ngày càng tinh vi','adv + adj','[{"en":"Cyberattacks are becoming increasingly sophisticated each year.","vi":"Các cuộc tấn công mạng ngày càng tinh vi qua từng năm."},{"en":"Marketing tools have grown increasingly sophisticated recently.","vi":"Công cụ tiếp thị đã trở nên ngày càng tinh vi gần đây."},{"en":"Modern robots are increasingly sophisticated and highly precise.","vi":"Robot hiện đại ngày càng tinh vi và rất chính xác."}]','[]',NULL,'/ɪnˈkriːsɪŋli səˈfɪstɪˌkeɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4398,'colloc-8-01',58,'independent state','nhà nước độc lập','adj + n','[{"en":"The colony fought for years to become an independent state.","vi":"Thuộc địa đã đấu tranh nhiều năm để trở thành một nhà nước độc lập."},{"en":"An independent state controls its own foreign policy.","vi":"Một nhà nước độc lập kiểm soát chính sách đối ngoại của mình."},{"en":"The treaty recognized the region as an independent state.","vi":"Hiệp ước công nhận khu vực là một nhà nước độc lập."}]','[]',NULL,'/ˌɪndɪˈpendənt steɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4399,'colloc-8-01',59,'independent variable','biến độc lập','adj + n','[{"en":"In the experiment, temperature was the independent variable.","vi":"Trong thí nghiệm, nhiệt độ là biến độc lập."},{"en":"Researchers change the independent variable to test its effect.","vi":"Các nhà nghiên cứu thay đổi biến độc lập để kiểm tra ảnh hưởng của nó."},{"en":"The independent variable here is the amount of sleep.","vi":"Biến độc lập ở đây là lượng giấc ngủ."}]','[]',NULL,'/ˌɪndɪˈpendənt ˈveriəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4400,'colloc-8-01',60,'indigenous people','người bản địa','adj + n','[{"en":"Indigenous people have lived on this land for centuries.","vi":"Người bản địa đã sống trên vùng đất này nhiều thế kỷ."},{"en":"The museum honors the traditions of indigenous people.","vi":"Bảo tàng tôn vinh truyền thống của người bản địa."},{"en":"Many indigenous people protect ancient forests carefully.","vi":"Nhiều người bản địa bảo vệ những khu rừng cổ một cách cẩn thận."}]','[]',NULL,'/ɪnˈdɪdʒənəs ˈpiːpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4401,'colloc-8-01',61,'indigenous population','dân số bản địa','adj + n','[{"en":"The indigenous population declined sharply after colonization.","vi":"Dân số bản địa giảm mạnh sau quá trình thực dân hóa."},{"en":"Researchers studied the health of the indigenous population.","vi":"Các nhà nghiên cứu nghiên cứu sức khỏe của dân số bản địa."},{"en":"The indigenous population maintains its own distinct language.","vi":"Dân số bản địa duy trì ngôn ngữ riêng biệt của mình."}]','[]',NULL,'/ɪnˈdɪdʒənəs ˌpɑːpjəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4402,'colloc-8-01',62,'individual behavior','hành vi cá nhân','adj + n','[{"en":"Psychologists study how culture shapes individual behavior.","vi":"Nhà tâm lý học nghiên cứu cách văn hóa định hình hành vi cá nhân."},{"en":"Individual behavior can change dramatically under group pressure.","vi":"Hành vi cá nhân có thể thay đổi mạnh dưới áp lực nhóm."},{"en":"The survey measured individual behavior toward saving money.","vi":"Khảo sát đo lường hành vi cá nhân đối với việc tiết kiệm tiền."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl bɪˈheɪvjər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4403,'colloc-8-01',63,'individual case','trường hợp riêng lẻ','adj + n','[{"en":"Each individual case must be reviewed on its own merits.","vi":"Mỗi trường hợp riêng lẻ phải được xem xét theo giá trị của nó."},{"en":"The doctor examined every individual case very carefully.","vi":"Bác sĩ kiểm tra từng trường hợp riêng lẻ rất cẩn thận."},{"en":"Outcomes vary widely from one individual case to another.","vi":"Kết quả thay đổi rất nhiều từ trường hợp riêng lẻ này sang trường hợp khác."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl keɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4404,'colloc-8-01',64,'individual characteristics','đặc điểm cá nhân','adj + n','[{"en":"Teachers should consider the individual characteristics of students.","vi":"Giáo viên nên xem xét đặc điểm cá nhân của học sinh."},{"en":"The study compared individual characteristics across two groups.","vi":"Nghiên cứu so sánh đặc điểm cá nhân giữa hai nhóm."},{"en":"Individual characteristics influence how people respond to stress.","vi":"Đặc điểm cá nhân ảnh hưởng đến cách người ta phản ứng với căng thẳng."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ˌkerəktəˈrɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4405,'colloc-8-01',65,'individual choice','lựa chọn cá nhân','adj + n','[{"en":"Voting is an individual choice protected by the constitution.","vi":"Bỏ phiếu là một lựa chọn cá nhân được hiến pháp bảo vệ."},{"en":"The policy respects individual choice in healthcare decisions.","vi":"Chính sách tôn trọng lựa chọn cá nhân trong các quyết định y tế."},{"en":"Diet is ultimately a matter of individual choice.","vi":"Chế độ ăn rốt cuộc là vấn đề của lựa chọn cá nhân."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl tʃɔɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4406,'colloc-8-01',66,'individual component','thành phần riêng lẻ','adj + n','[{"en":"Engineers tested each individual component before assembly.","vi":"Kỹ sư kiểm tra từng thành phần riêng lẻ trước khi lắp ráp."},{"en":"Every individual component of the engine was replaced.","vi":"Mỗi thành phần riêng lẻ của động cơ đã được thay thế."},{"en":"The report breaks the system into each individual component.","vi":"Báo cáo chia hệ thống thành từng thành phần riêng lẻ."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl kəmˈpoʊnənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4407,'colloc-8-01',67,'individual differences','sự khác biệt cá nhân','adj + n','[{"en":"The study highlights individual differences in learning speed.","vi":"Nghiên cứu nêu bật sự khác biệt cá nhân về tốc độ học."},{"en":"Individual differences make a one-size-fits-all approach unwise.","vi":"Sự khác biệt cá nhân khiến cách tiếp cận chung cho mọi người là không khôn ngoan."},{"en":"Teachers must respect individual differences among their students.","vi":"Giáo viên phải tôn trọng sự khác biệt cá nhân giữa học sinh."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ˈdɪfərənsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4408,'colloc-8-01',68,'individual element','yếu tố riêng lẻ','adj + n','[{"en":"Each individual element of the design serves a clear purpose.","vi":"Mỗi yếu tố riêng lẻ của thiết kế phục vụ một mục đích rõ ràng."},{"en":"Analysts examined every individual element of the contract.","vi":"Các nhà phân tích xem xét từng yếu tố riêng lẻ của hợp đồng."},{"en":"Removing one individual element changed the whole result.","vi":"Loại bỏ một yếu tố riêng lẻ đã thay đổi toàn bộ kết quả."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4409,'colloc-8-01',69,'individual experience','trải nghiệm cá nhân','adj + n','[{"en":"Every learner brings a unique individual experience to class.","vi":"Mỗi người học mang một trải nghiệm cá nhân riêng vào lớp."},{"en":"The book draws on the author''s individual experience abroad.","vi":"Cuốn sách dựa trên trải nghiệm cá nhân của tác giả ở nước ngoài."},{"en":"Individual experience strongly shapes how we view the world.","vi":"Trải nghiệm cá nhân định hình mạnh mẽ cách chúng ta nhìn thế giới."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ɪkˈspɪriəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4410,'colloc-8-01',70,'individual interests','lợi ích cá nhân','adj + n','[{"en":"Good leaders balance individual interests with the common good.","vi":"Lãnh đạo giỏi cân bằng lợi ích cá nhân với lợi ích chung."},{"en":"Sometimes individual interests conflict with team goals.","vi":"Đôi khi lợi ích cá nhân xung đột với mục tiêu của nhóm."},{"en":"The policy tries to protect individual interests fairly.","vi":"Chính sách cố gắng bảo vệ lợi ích cá nhân một cách công bằng."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ˈɪntrəsts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4411,'colloc-8-01',71,'individual item','món đồ riêng lẻ','adj + n','[{"en":"The cashier scanned each individual item at the register.","vi":"Nhân viên thu ngân quét từng món đồ riêng lẻ tại quầy."},{"en":"Every individual item in the collection was carefully labeled.","vi":"Mỗi món đồ riêng lẻ trong bộ sưu tập được dán nhãn cẩn thận."},{"en":"The price of each individual item is listed clearly.","vi":"Giá của từng món đồ riêng lẻ được niêm yết rõ ràng."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ˈaɪtəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4412,'colloc-8-01',72,'individual needs','nhu cầu cá nhân','adj + n','[{"en":"The program is designed around each student''s individual needs.","vi":"Chương trình được thiết kế quanh nhu cầu cá nhân của mỗi học sinh."},{"en":"Good care must respond to the individual needs of patients.","vi":"Chăm sóc tốt phải đáp ứng nhu cầu cá nhân của bệnh nhân."},{"en":"Teachers adapt their lessons to meet individual needs.","vi":"Giáo viên điều chỉnh bài giảng để đáp ứng nhu cầu cá nhân."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl niːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4413,'colloc-8-01',73,'individual response','phản ứng cá nhân','adj + n','[{"en":"The drug''s individual response varies from person to person.","vi":"Phản ứng cá nhân với thuốc thay đổi tùy từng người."},{"en":"Researchers recorded each individual response to the survey.","vi":"Các nhà nghiên cứu ghi lại từng phản ứng cá nhân với khảo sát."},{"en":"Individual response to therapy can be hard to predict.","vi":"Phản ứng cá nhân với liệu pháp có thể khó dự đoán."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl rɪˈspɑːns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4414,'colloc-8-01',74,'individual responsibility','trách nhiệm cá nhân','adj + n','[{"en":"Recycling depends partly on individual responsibility at home.","vi":"Việc tái chế phụ thuộc một phần vào trách nhiệm cá nhân ở nhà."},{"en":"The campaign stresses individual responsibility for public health.","vi":"Chiến dịch nhấn mạnh trách nhiệm cá nhân đối với sức khỏe cộng đồng."},{"en":"Safe driving is a matter of individual responsibility.","vi":"Lái xe an toàn là vấn đề của trách nhiệm cá nhân."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl rɪˌspɑːnsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4415,'colloc-8-01',75,'individual rights','quyền cá nhân','adj + n','[{"en":"The constitution protects the individual rights of citizens.","vi":"Hiến pháp bảo vệ quyền cá nhân của công dân."},{"en":"Courts must balance individual rights against public safety.","vi":"Tòa án phải cân bằng quyền cá nhân với an toàn công cộng."},{"en":"Freedom of speech is a fundamental individual right.","vi":"Tự do ngôn luận là một quyền cá nhân cơ bản."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl raɪts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4416,'colloc-8-01',76,'individual variable','biến số cá nhân','adj + n','[{"en":"The model adjusts for each individual variable in the dataset.","vi":"Mô hình điều chỉnh cho từng biến số cá nhân trong bộ dữ liệu."},{"en":"Analysts tested how each individual variable affects the result.","vi":"Các nhà phân tích kiểm tra cách từng biến số cá nhân ảnh hưởng kết quả."},{"en":"An individual variable may have little impact on its own.","vi":"Một biến số cá nhân có thể ít tác động khi đứng riêng."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ˈveriəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4417,'colloc-8-01',77,'individual variation','sự biến thiên cá nhân','adj + n','[{"en":"There is wide individual variation in how people learn.","vi":"Có sự biến thiên cá nhân lớn về cách người ta học."},{"en":"Individual variation in metabolism affects weight loss results.","vi":"Sự biến thiên cá nhân về trao đổi chất ảnh hưởng kết quả giảm cân."},{"en":"The data showed considerable individual variation in scores.","vi":"Dữ liệu cho thấy sự biến thiên cá nhân đáng kể về điểm số."}]','[]',NULL,'/ˌɪndɪˈvɪdʒuəl ˌveriˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4418,'colloc-8-01',78,'industrial capitalism','chủ nghĩa tư bản công nghiệp','adj + n','[{"en":"Industrial capitalism transformed cities during the nineteenth century.","vi":"Chủ nghĩa tư bản công nghiệp biến đổi các thành phố trong thế kỷ mười chín."},{"en":"Factories were central to the rise of industrial capitalism.","vi":"Nhà máy là trung tâm của sự trỗi dậy của chủ nghĩa tư bản công nghiệp."},{"en":"Historians debate the social cost of industrial capitalism.","vi":"Các sử gia tranh luận về cái giá xã hội của chủ nghĩa tư bản công nghiệp."}]','[]',NULL,'/ɪnˈdʌstriəl ˈkæpɪtəlɪzəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4419,'colloc-8-01',79,'industrial country','quốc gia công nghiệp','adj + n','[{"en":"An industrial country relies heavily on manufacturing for income.","vi":"Một quốc gia công nghiệp phụ thuộc nhiều vào sản xuất để có thu nhập."},{"en":"Pollution remains a serious problem in many industrial countries.","vi":"Ô nhiễm vẫn là vấn đề nghiêm trọng ở nhiều quốc gia công nghiệp."},{"en":"An industrial country usually has a large skilled workforce.","vi":"Một quốc gia công nghiệp thường có lực lượng lao động lành nghề lớn."}]','[]',NULL,'/ɪnˈdʌstriəl ˈkʌntri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4420,'colloc-8-01',80,'industrial development','phát triển công nghiệp','adj + n','[{"en":"Industrial development brought new jobs to the rural region.","vi":"Phát triển công nghiệp mang lại việc làm mới cho vùng nông thôn."},{"en":"Rapid industrial development can harm the local environment.","vi":"Phát triển công nghiệp nhanh có thể gây hại cho môi trường địa phương."},{"en":"The government invested heavily in industrial development.","vi":"Chính phủ đầu tư mạnh vào phát triển công nghiệp."}]','[]',NULL,'/ɪnˈdʌstriəl dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4421,'colloc-8-01',81,'industrial production','sản xuất công nghiệp','adj + n','[{"en":"Industrial production rose sharply after the new factory opened.","vi":"Sản xuất công nghiệp tăng mạnh sau khi nhà máy mới mở."},{"en":"The recession caused industrial production to fall steeply.","vi":"Suy thoái khiến sản xuất công nghiệp giảm mạnh."},{"en":"Automation has greatly increased industrial production efficiency.","vi":"Tự động hóa đã tăng đáng kể hiệu quả sản xuất công nghiệp."}]','[]',NULL,'/ɪnˈdʌstriəl prəˈdʌkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4422,'colloc-8-01',82,'industrial society','xã hội công nghiệp','adj + n','[{"en":"An industrial society depends on machines and steady energy.","vi":"Một xã hội công nghiệp phụ thuộc vào máy móc và năng lượng ổn định."},{"en":"Life in an industrial society changed family structures greatly.","vi":"Cuộc sống trong xã hội công nghiệp thay đổi cấu trúc gia đình rất nhiều."},{"en":"Industrial society created both wealth and new inequalities.","vi":"Xã hội công nghiệp tạo ra cả sự giàu có lẫn bất bình đẳng mới."}]','[]',NULL,'/ɪnˈdʌstriəl səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4423,'colloc-8-01',83,'industrialized country','quốc gia công nghiệp hóa','adj + n','[{"en":"An industrialized country often consumes vast amounts of energy.","vi":"Một quốc gia công nghiệp hóa thường tiêu thụ lượng năng lượng khổng lồ."},{"en":"Many industrialized countries face an aging population.","vi":"Nhiều quốc gia công nghiệp hóa đối mặt với dân số già."},{"en":"An industrialized country generally has advanced infrastructure.","vi":"Một quốc gia công nghiệp hóa nhìn chung có hạ tầng tiên tiến."}]','[]',NULL,'/ɪnˈdʌstriəˌlaɪzd ˈkʌntri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4424,'colloc-8-01',84,'industrialized nation','quốc gia công nghiệp hóa','adj + n','[{"en":"An industrialized nation produces most goods within its borders.","vi":"Một quốc gia công nghiệp hóa sản xuất phần lớn hàng hóa trong biên giới."},{"en":"Industrialized nations contribute heavily to global emissions.","vi":"Các quốc gia công nghiệp hóa đóng góp lớn vào khí thải toàn cầu."},{"en":"An industrialized nation usually offers strong public services.","vi":"Một quốc gia công nghiệp hóa thường cung cấp dịch vụ công mạnh."}]','[]',NULL,'/ɪnˈdʌstriəˌlaɪzd ˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4425,'colloc-8-01',85,'increasingly linked to','ngày càng gắn liền với','adv + vpp','[{"en":"Poor sleep is increasingly linked to long-term health problems.","vi":"Giấc ngủ kém ngày càng gắn liền với các vấn đề sức khỏe lâu dài."},{"en":"Success is increasingly linked to digital skills these days.","vi":"Thành công ngày nay ngày càng gắn liền với kỹ năng số."},{"en":"Rising costs are increasingly linked to global supply issues.","vi":"Chi phí tăng ngày càng gắn liền với vấn đề cung ứng toàn cầu."}]','[]',NULL,'/ɪnˈkriːsɪŋli lɪŋkt tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4426,'colloc-8-01',86,'infinite number','vô số','adj + n','[{"en":"There is an infinite number of points on a line.","vi":"Có vô số điểm trên một đường thẳng."},{"en":"An infinite number of combinations is possible with the code.","vi":"Vô số tổ hợp có thể xảy ra với mã này."},{"en":"The universe may contain an infinite number of stars.","vi":"Vũ trụ có thể chứa vô số ngôi sao."}]','[]',NULL,'/ˈɪnfɪnət ˈnʌmbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4427,'colloc-8-01',87,'information flow','luồng thông tin','n + n','[{"en":"A clear information flow helps teams make better decisions.","vi":"Luồng thông tin rõ ràng giúp các nhóm ra quyết định tốt hơn."},{"en":"The new system improved information flow between departments.","vi":"Hệ thống mới cải thiện luồng thông tin giữa các phòng ban."},{"en":"Poor information flow often leads to costly mistakes.","vi":"Luồng thông tin kém thường dẫn đến những sai lầm tốn kém."}]','[]',NULL,'/ˌɪnfərˈmeɪʃən floʊ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4428,'colloc-8-01',88,'information gathering','việc thu thập thông tin','n + n','[{"en":"Information gathering is the first stage of any research project.","vi":"Việc thu thập thông tin là giai đoạn đầu của mọi dự án nghiên cứu."},{"en":"Careful information gathering reduces the risk of errors.","vi":"Việc thu thập thông tin cẩn thận giảm rủi ro sai sót."},{"en":"Reporters spend much of their time on information gathering.","vi":"Phóng viên dành phần lớn thời gian cho việc thu thập thông tin."}]','[]',NULL,'/ˌɪnfərˈmeɪʃən ˈɡæðərɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4429,'colloc-8-01',89,'information processing','việc xử lý thông tin','n + n','[{"en":"The brain is remarkably fast at information processing.","vi":"Bộ não xử lý thông tin nhanh một cách đáng kinh ngạc."},{"en":"Computers excel at the rapid information processing of numbers.","vi":"Máy tính giỏi trong việc xử lý thông tin số liệu nhanh chóng."},{"en":"Stress can slow down our everyday information processing.","vi":"Căng thẳng có thể làm chậm việc xử lý thông tin hằng ngày của ta."}]','[]',NULL,'/ˌɪnfərˈmeɪʃən ˈprɑːsesɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4430,'colloc-8-01',90,'information retrieval','việc truy xuất thông tin','n + n','[{"en":"Search engines made information retrieval fast and simple.","vi":"Công cụ tìm kiếm khiến việc truy xuất thông tin nhanh và đơn giản."},{"en":"Good indexing improves information retrieval from large databases.","vi":"Lập chỉ mục tốt cải thiện việc truy xuất thông tin từ cơ sở dữ liệu lớn."},{"en":"The library system streamlined information retrieval for students.","vi":"Hệ thống thư viện tinh giản việc truy xuất thông tin cho sinh viên."}]','[]',NULL,'/ˌɪnfərˈmeɪʃən rɪˈtriːvəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4431,'colloc-8-01',91,'information sharing','việc chia sẻ thông tin','n + n','[{"en":"Information sharing between agencies improved the emergency response.","vi":"Việc chia sẻ thông tin giữa các cơ quan cải thiện ứng phó khẩn cấp."},{"en":"Open information sharing builds trust within a team.","vi":"Việc chia sẻ thông tin cởi mở xây dựng niềm tin trong nhóm."},{"en":"Privacy rules can limit information sharing across borders.","vi":"Quy định riêng tư có thể hạn chế việc chia sẻ thông tin xuyên biên giới."}]','[]',NULL,'/ˌɪnfərˈmeɪʃən ˈʃerɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4432,'colloc-8-01',92,'informed consent','sự đồng ý có hiểu biết','adj + n','[{"en":"Doctors must obtain informed consent before any operation.","vi":"Bác sĩ phải có được sự đồng ý có hiểu biết trước mọi ca mổ."},{"en":"Researchers require informed consent from every participant.","vi":"Các nhà nghiên cứu yêu cầu sự đồng ý có hiểu biết từ mỗi người tham gia."},{"en":"Informed consent means the patient understands the risks involved.","vi":"Sự đồng ý có hiểu biết nghĩa là bệnh nhân hiểu các rủi ro liên quan."}]','[]',NULL,'/ɪnˈfɔːrmd kənˈsent/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4433,'colloc-8-01',93,'initial period','giai đoạn ban đầu','adj + n','[{"en":"During the initial period, sales grew slowly but steadily.","vi":"Trong giai đoạn ban đầu, doanh số tăng chậm nhưng đều."},{"en":"The initial period of training is the most demanding.","vi":"Giai đoạn ban đầu của quá trình huấn luyện là khắt khe nhất."},{"en":"After the initial period, the project gained strong momentum.","vi":"Sau giai đoạn ban đầu, dự án có được đà phát triển mạnh."}]','[]',NULL,'/ɪˈnɪʃəl ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4434,'colloc-8-01',94,'initial phase','pha ban đầu','adj + n','[{"en":"The initial phase of the study focused on collecting data.","vi":"Pha ban đầu của nghiên cứu tập trung vào thu thập dữ liệu."},{"en":"Funding was secured during the initial phase of the plan.","vi":"Nguồn vốn được đảm bảo trong pha ban đầu của kế hoạch."},{"en":"The initial phase of construction took almost six months.","vi":"Pha ban đầu của việc xây dựng mất gần sáu tháng."}]','[]',NULL,'/ɪˈnɪʃəl feɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4435,'colloc-8-01',95,'initial position','vị trí ban đầu','adj + n','[{"en":"The runner returned to her initial position before the race.","vi":"Vận động viên trở về vị trí ban đầu của mình trước cuộc đua."},{"en":"We measured the object''s movement from its initial position.","vi":"Chúng tôi đo chuyển động của vật từ vị trí ban đầu của nó."},{"en":"The negotiator softened from his initial position over time.","vi":"Người đàm phán dần nới lỏng từ vị trí ban đầu của mình."}]','[]',NULL,'/ɪˈnɪʃəl pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4436,'colloc-8-01',96,'initial research','nghiên cứu ban đầu','adj + n','[{"en":"Initial research suggested the treatment was both safe and effective.","vi":"Nghiên cứu ban đầu cho thấy phương pháp điều trị vừa an toàn vừa hiệu quả."},{"en":"The team published its initial research findings last spring.","vi":"Nhóm công bố kết quả nghiên cứu ban đầu vào mùa xuân năm ngoái."},{"en":"Initial research often raises more questions than answers.","vi":"Nghiên cứu ban đầu thường đặt ra nhiều câu hỏi hơn là câu trả lời."}]','[]',NULL,'/ɪˈnɪʃəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4437,'colloc-8-01',97,'initial stage','giai đoạn đầu','adj + n','[{"en":"In the initial stage, the disease shows almost no symptoms.","vi":"Ở giai đoạn đầu, căn bệnh hầu như không có triệu chứng."},{"en":"The initial stage of the plan involves gathering feedback.","vi":"Giai đoạn đầu của kế hoạch bao gồm thu thập phản hồi."},{"en":"Mistakes made in the initial stage are costly to fix.","vi":"Sai lầm ở giai đoạn đầu rất tốn kém để sửa chữa."}]','[]',NULL,'/ɪˈnɪʃəl steɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4438,'colloc-8-01',98,'institutional arrangement','sự sắp xếp về thể chế','adj + n','[{"en":"A stable institutional arrangement supports long-term economic growth.","vi":"Một sự sắp xếp thể chế ổn định hỗ trợ tăng trưởng kinh tế dài hạn."},{"en":"The reform changed the institutional arrangement of local government.","vi":"Cuộc cải cách thay đổi sự sắp xếp thể chế của chính quyền địa phương."},{"en":"Researchers compared institutional arrangements across several countries.","vi":"Các nhà nghiên cứu so sánh sự sắp xếp thể chế giữa nhiều quốc gia."}]','[]',NULL,'/ˌɪnstɪˈtuːʃənəl əˈreɪndʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4439,'colloc-8-01',99,'institutional context','bối cảnh thể chế','adj + n','[{"en":"Policies must be understood within their institutional context.","vi":"Các chính sách phải được hiểu trong bối cảnh thể chế của chúng."},{"en":"The institutional context shapes how reforms are carried out.","vi":"Bối cảnh thể chế định hình cách các cải cách được thực hiện."},{"en":"Behavior differs greatly depending on the institutional context.","vi":"Hành vi khác nhau rất nhiều tùy theo bối cảnh thể chế."}]','[]',NULL,'/ˌɪnstɪˈtuːʃənəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4440,'colloc-8-01',100,'institutional framework','khuôn khổ thể chế','adj + n','[{"en":"A strong institutional framework is needed to enforce the new law.","vi":"Cần một khuôn khổ thể chế vững mạnh để thực thi luật mới."},{"en":"The treaty established an institutional framework for cooperation.","vi":"Hiệp ước thiết lập một khuôn khổ thể chế cho hợp tác."},{"en":"Without a clear institutional framework, reforms often fail.","vi":"Thiếu khuôn khổ thể chế rõ ràng, các cải cách thường thất bại."}]','[]',NULL,'/ˌɪnstɪˈtuːʃənəl ˈfreɪmwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4441,'colloc-8-01',101,'institutional structure','cấu trúc thể chế','adj + n','[{"en":"The institutional structure of the university is quite complex.","vi":"Cấu trúc thể chế của trường đại học khá phức tạp."},{"en":"Reforms aim to simplify the existing institutional structure.","vi":"Các cải cách nhằm đơn giản hóa cấu trúc thể chế hiện có."},{"en":"The institutional structure determines how decisions are made.","vi":"Cấu trúc thể chế quyết định cách các quyết định được đưa ra."}]','[]',NULL,'/ˌɪnstɪˈtuːʃənəl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4442,'colloc-8-01',102,'institutional support','sự hỗ trợ từ thể chế','adj + n','[{"en":"The project succeeded thanks to strong institutional support.","vi":"Dự án thành công nhờ sự hỗ trợ thể chế mạnh mẽ."},{"en":"Students benefit from institutional support such as scholarships.","vi":"Sinh viên hưởng lợi từ sự hỗ trợ thể chế như học bổng."},{"en":"Without institutional support, the initiative quickly collapsed.","vi":"Thiếu sự hỗ trợ thể chế, sáng kiến nhanh chóng sụp đổ."}]','[]',NULL,'/ˌɪnstɪˈtuːʃənəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4443,'colloc-8-01',103,'integral part','bộ phận không thể thiếu','adj + n','[{"en":"Music is an integral part of the school''s daily routine.","vi":"Âm nhạc là một bộ phận không thể thiếu trong sinh hoạt hằng ngày của trường."},{"en":"Feedback is an integral part of the learning process.","vi":"Phản hồi là một bộ phận không thể thiếu của quá trình học."},{"en":"Trust is an integral part of any successful partnership.","vi":"Niềm tin là một bộ phận không thể thiếu của mọi quan hệ đối tác thành công."}]','[]',NULL,'/ˈɪntɪɡrəl pɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4444,'colloc-8-01',104,'integrated approach','cách tiếp cận tích hợp','adj + n','[{"en":"An integrated approach combines several methods into one plan.","vi":"Một cách tiếp cận tích hợp kết hợp nhiều phương pháp vào một kế hoạch."},{"en":"The clinic uses an integrated approach to patient care.","vi":"Phòng khám dùng cách tiếp cận tích hợp trong chăm sóc bệnh nhân."},{"en":"An integrated approach to teaching links theory with practice.","vi":"Cách tiếp cận tích hợp trong giảng dạy kết nối lý thuyết với thực hành."}]','[]',NULL,'/ˈɪntɪˌɡreɪtɪd əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4445,'colloc-8-01',105,'integrated system','hệ thống tích hợp','adj + n','[{"en":"The company built an integrated system to manage all orders.","vi":"Công ty xây dựng một hệ thống tích hợp để quản lý mọi đơn hàng."},{"en":"An integrated system connects billing, shipping, and support together.","vi":"Một hệ thống tích hợp kết nối thanh toán, vận chuyển và hỗ trợ với nhau."},{"en":"The hospital introduced an integrated system for patient records.","vi":"Bệnh viện giới thiệu một hệ thống tích hợp cho hồ sơ bệnh nhân."}]','[]',NULL,'/ˈɪntɪˌɡreɪtɪd ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4446,'colloc-8-01',106,'intellectual property','sở hữu trí tuệ','adj + n','[{"en":"Patents protect a company''s valuable intellectual property.","vi":"Bằng sáng chế bảo vệ sở hữu trí tuệ quý giá của công ty."},{"en":"Copying software without permission violates intellectual property rights.","vi":"Sao chép phần mềm không phép vi phạm quyền sở hữu trí tuệ."},{"en":"Universities increasingly value the intellectual property they create.","vi":"Các trường đại học ngày càng coi trọng sở hữu trí tuệ mà họ tạo ra."}]','[]',NULL,'/ˌɪntəˈlektʃuəl ˈprɑːpərti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4447,'colloc-8-01',107,'intellectual work','công việc trí óc','adj + n','[{"en":"Writing a thesis demands sustained intellectual work over many months.","vi":"Viết luận án đòi hỏi công việc trí óc bền bỉ trong nhiều tháng."},{"en":"Universities value intellectual work that pushes the boundaries of knowledge.","vi":"Các trường đại học coi trọng công việc trí óc mở rộng ranh giới tri thức."},{"en":"Good sleep helps the brain handle demanding intellectual work each day.","vi":"Ngủ đủ giúp não xử lý công việc trí óc nặng nhọc mỗi ngày."}]','[]',NULL,'/ˌɪntəˈlektʃuəl ˈwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4448,'colloc-8-01',108,'intensive study','việc học tập chuyên sâu','adj + n','[{"en":"The topic deserves intensive study before any firm conclusions are drawn.","vi":"Chủ đề này xứng đáng được nghiên cứu chuyên sâu trước khi kết luận."},{"en":"Months of intensive study prepared her for the final examination.","vi":"Nhiều tháng học tập chuyên sâu đã chuẩn bị cho cô kỳ thi cuối."},{"en":"Intensive study of the data revealed several unexpected patterns.","vi":"Việc nghiên cứu chuyên sâu dữ liệu đã hé lộ vài mẫu hình bất ngờ."}]','[]',NULL,'/ɪnˈtensɪv ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4449,'colloc-8-01',109,'interested party','bên liên quan, bên có quyền lợi','adj + n','[{"en":"Every interested party was invited to comment on the proposal.","vi":"Mọi bên liên quan đều được mời góp ý cho đề xuất."},{"en":"The court must consider the views of each interested party.","vi":"Tòa án phải xem xét quan điểm của từng bên liên quan."},{"en":"As an interested party, the company joined the public consultation.","vi":"Là một bên có quyền lợi, công ty đã tham gia buổi tham vấn công khai."}]','[]',NULL,'/ˈɪntrəstɪd ˈpɑːrti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4450,'colloc-8-01',110,'internal affairs','công việc nội bộ','adj + n','[{"en":"Many states reject foreign interference in their internal affairs.","vi":"Nhiều quốc gia phản đối sự can thiệp nước ngoài vào công việc nội bộ."},{"en":"The minister handles the country''s internal affairs and security policy.","vi":"Vị bộ trưởng phụ trách công việc nội bộ và chính sách an ninh."},{"en":"Critics said the report meddled in the firm''s internal affairs.","vi":"Giới phê bình nói báo cáo can thiệp vào công việc nội bộ của hãng."}]','[]',NULL,'/ɪnˈtɜːrnəl əˈferz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4451,'colloc-8-01',111,'internal conflict','xung đột nội bộ','adj + n','[{"en":"Years of internal conflict weakened the organization from within.","vi":"Nhiều năm xung đột nội bộ đã làm suy yếu tổ chức từ bên trong."},{"en":"The novel explores the hero''s internal conflict over loyalty.","vi":"Cuốn tiểu thuyết khám phá xung đột nội tâm của người hùng về lòng trung thành."},{"en":"Internal conflict among managers delayed the important decision.","vi":"Xung đột nội bộ giữa các quản lý đã trì hoãn quyết định quan trọng."}]','[]',NULL,'/ɪnˈtɜːrnəl ˈkɑːnflɪkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4452,'colloc-8-01',112,'internal control','kiểm soát nội bộ','adj + n','[{"en":"Strong internal control helps prevent fraud within a company.","vi":"Kiểm soát nội bộ chặt chẽ giúp ngăn chặn gian lận trong công ty."},{"en":"Auditors examine whether internal control systems work effectively.","vi":"Kiểm toán viên kiểm tra xem hệ thống kiểm soát nội bộ có hiệu quả không."},{"en":"Weak internal control allowed the errors to go unnoticed for months.","vi":"Kiểm soát nội bộ yếu khiến các lỗi không bị phát hiện trong nhiều tháng."}]','[]',NULL,'/ɪnˈtɜːrnəl kənˈtroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4453,'colloc-8-01',113,'internal market','thị trường nội địa','adj + n','[{"en":"The reforms aimed to create a single internal market for goods.","vi":"Các cải cách nhằm tạo ra một thị trường nội địa thống nhất cho hàng hóa."},{"en":"Tariffs were removed to strengthen the region''s internal market.","vi":"Thuế quan được bãi bỏ để củng cố thị trường nội địa của khu vực."},{"en":"A growing internal market gives local firms more room to expand.","vi":"Thị trường nội địa đang lớn mạnh cho doanh nghiệp địa phương thêm dư địa mở rộng."}]','[]',NULL,'/ɪnˈtɜːrnəl ˈmɑːrkɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4454,'colloc-8-01',114,'internal organ','nội tạng, cơ quan nội tạng','adj + n','[{"en":"The scan revealed damage to several internal organs.","vi":"Ảnh chụp cho thấy tổn thương ở vài cơ quan nội tạng."},{"en":"Surgeons must work carefully near delicate internal organs.","vi":"Bác sĩ phẫu thuật phải thao tác cẩn thận gần các nội tạng mong manh."},{"en":"The liver is an internal organ that filters toxins from blood.","vi":"Gan là một cơ quan nội tạng lọc độc tố khỏi máu."}]','[]',NULL,'/ɪnˈtɜːrnəl ˈɔːrɡən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4455,'colloc-8-01',115,'internal structure','cấu trúc bên trong','adj + n','[{"en":"Microscopes let scientists study the internal structure of cells.","vi":"Kính hiển vi cho phép nhà khoa học nghiên cứu cấu trúc bên trong tế bào."},{"en":"The essay''s internal structure follows a clear logical order.","vi":"Cấu trúc bên trong của bài luận tuân theo một trật tự logic rõ ràng."},{"en":"Engineers analyzed the internal structure of the damaged bridge.","vi":"Các kỹ sư đã phân tích cấu trúc bên trong của cây cầu hư hỏng."}]','[]',NULL,'/ɪnˈtɜːrnəl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4456,'colloc-8-01',116,'international agreement','thỏa thuận quốc tế','adj + n','[{"en":"A new international agreement set limits on carbon emissions.","vi":"Một thỏa thuận quốc tế mới đặt ra giới hạn cho phát thải carbon."},{"en":"Several nations signed the international agreement on trade.","vi":"Nhiều quốc gia đã ký thỏa thuận quốc tế về thương mại."},{"en":"The international agreement took years of careful negotiation.","vi":"Thỏa thuận quốc tế đó mất nhiều năm đàm phán thận trọng."}]','[]',NULL,'/ˌɪntərˈnæʃənəl əˈɡriːmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4457,'colloc-8-01',117,'international body','tổ chức quốc tế','adj + n','[{"en":"An international body was created to oversee global health.","vi":"Một tổ chức quốc tế được lập ra để giám sát sức khỏe toàn cầu."},{"en":"Disputes are often referred to a neutral international body.","vi":"Tranh chấp thường được chuyển đến một tổ chức quốc tế trung lập."},{"en":"The international body issued guidelines for member states.","vi":"Tổ chức quốc tế đã ban hành hướng dẫn cho các quốc gia thành viên."}]','[]',NULL,'/ˌɪntərˈnæʃənəl ˈbɑːdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4458,'colloc-8-01',118,'international community','cộng đồng quốc tế','adj + n','[{"en":"The international community condemned the violence in strong terms.","vi":"Cộng đồng quốc tế đã lên án mạnh mẽ bạo lực."},{"en":"Climate change requires action from the whole international community.","vi":"Biến đổi khí hậu đòi hỏi hành động từ toàn thể cộng đồng quốc tế."},{"en":"Aid flowed in once the international community recognized the crisis.","vi":"Viện trợ đổ về khi cộng đồng quốc tế thừa nhận cuộc khủng hoảng."}]','[]',NULL,'/ˌɪntərˈnæʃənəl kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4459,'colloc-8-01',119,'international conference','hội nghị quốc tế','adj + n','[{"en":"She presented her findings at an international conference in Paris.","vi":"Cô trình bày kết quả tại một hội nghị quốc tế ở Paris."},{"en":"The international conference brought together experts from many fields.","vi":"Hội nghị quốc tế quy tụ các chuyên gia từ nhiều lĩnh vực."},{"en":"Leaders met at an international conference to discuss trade policy.","vi":"Các lãnh đạo gặp nhau tại hội nghị quốc tế để bàn về chính sách thương mại."}]','[]',NULL,'/ˌɪntərˈnæʃənəl ˈkɑːnfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4460,'colloc-8-01',120,'international context','bối cảnh quốc tế','adj + n','[{"en":"The policy must be understood within a wider international context.","vi":"Chính sách này phải được hiểu trong một bối cảnh quốc tế rộng hơn."},{"en":"Her study places local events in an international context.","vi":"Nghiên cứu của cô đặt các sự kiện địa phương vào bối cảnh quốc tế."},{"en":"In an international context, these standards vary considerably.","vi":"Trong bối cảnh quốc tế, các tiêu chuẩn này khác nhau đáng kể."}]','[]',NULL,'/ˌɪntərˈnæʃənəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4461,'colloc-8-01',121,'international journal','tạp chí quốc tế','adj + n','[{"en":"Her paper appeared in a leading international journal last year.","vi":"Bài báo của cô xuất hiện trên một tạp chí quốc tế hàng đầu năm ngoái."},{"en":"Publishing in an international journal boosts a researcher''s reputation.","vi":"Đăng bài trên tạp chí quốc tế nâng cao danh tiếng của nhà nghiên cứu."},{"en":"The international journal reviews each submission very carefully.","vi":"Tạp chí quốc tế đánh giá rất kỹ từng bài gửi đến."}]','[]',NULL,'/ˌɪntərˈnæʃənəl ˈdʒɜːrnəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4462,'colloc-8-01',122,'international organization','tổ chức quốc tế','adj + n','[{"en":"The international organization coordinates relief efforts after disasters.","vi":"Tổ chức quốc tế điều phối các nỗ lực cứu trợ sau thảm họa."},{"en":"Many countries fund the international organization through annual dues.","vi":"Nhiều nước tài trợ cho tổ chức quốc tế qua phí thường niên."},{"en":"She works for an international organization focused on human rights.","vi":"Cô làm việc cho một tổ chức quốc tế tập trung vào nhân quyền."}]','[]',NULL,'/ˌɪntərˈnæʃənəl ˌɔːrɡənəˈzeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4463,'colloc-8-01',123,'international treaty','hiệp ước quốc tế','adj + n','[{"en":"The international treaty bans the testing of nuclear weapons.","vi":"Hiệp ước quốc tế cấm thử nghiệm vũ khí hạt nhân."},{"en":"Both governments agreed to honor the international treaty fully.","vi":"Cả hai chính phủ đồng ý tuân thủ đầy đủ hiệp ước quốc tế."},{"en":"Ratifying the international treaty required approval from parliament.","vi":"Việc phê chuẩn hiệp ước quốc tế cần sự đồng ý của quốc hội."}]','[]',NULL,'/ˌɪntərˈnæʃənəl ˈtriːti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4464,'colloc-8-01',124,'internet access','khả năng truy cập internet','n + n','[{"en":"Rural schools often lack reliable internet access for students.","vi":"Các trường ở nông thôn thường thiếu internet ổn định cho học sinh."},{"en":"Internet access has become essential for everyday academic work.","vi":"Truy cập internet đã trở nên thiết yếu cho việc học hằng ngày."},{"en":"The library provides free internet access to all members.","vi":"Thư viện cung cấp truy cập internet miễn phí cho mọi thành viên."}]','[]',NULL,'/ˈɪntərnet ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4465,'colloc-8-01',125,'interpersonal relationships','các mối quan hệ giữa người với người','adj + n','[{"en":"Healthy interpersonal relationships support emotional well-being at work.","vi":"Các mối quan hệ lành mạnh giữa người với người hỗ trợ sức khỏe tinh thần ở nơi làm việc."},{"en":"The course examines how culture shapes interpersonal relationships.","vi":"Khóa học xem xét cách văn hóa định hình các mối quan hệ giữa người với người."},{"en":"Strong interpersonal relationships help teams resolve conflict quickly.","vi":"Các mối quan hệ tốt giữa người với người giúp đội nhóm giải quyết xung đột nhanh."}]','[]',NULL,'/ˌɪntərˈpɜːrsənəl rɪˈleɪʃənʃɪps/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4466,'colloc-8-01',126,'interpersonal skills','kỹ năng giao tiếp ứng xử','adj + n','[{"en":"Good interpersonal skills are vital for working in a team.","vi":"Kỹ năng giao tiếp ứng xử tốt rất quan trọng khi làm việc nhóm."},{"en":"Employers increasingly value interpersonal skills over technical knowledge.","vi":"Nhà tuyển dụng ngày càng coi trọng kỹ năng ứng xử hơn kiến thức kỹ thuật."},{"en":"The workshop helps students develop their interpersonal skills.","vi":"Buổi hội thảo giúp sinh viên phát triển kỹ năng giao tiếp ứng xử."}]','[]',NULL,'/ˌɪntərˈpɜːrsənəl skɪlz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4467,'colloc-8-01',127,'interpret data','diễn giải dữ liệu','v + n','[{"en":"Researchers must interpret data carefully before drawing conclusions.","vi":"Nhà nghiên cứu phải diễn giải dữ liệu cẩn thận trước khi kết luận."},{"en":"Students learn to interpret data using statistical software.","vi":"Sinh viên học cách diễn giải dữ liệu bằng phần mềm thống kê."},{"en":"It is easy to interpret data wrongly without proper context.","vi":"Rất dễ diễn giải sai dữ liệu nếu thiếu bối cảnh phù hợp."}]','[]',NULL,'/ɪnˈtɜːrprət ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4468,'colloc-8-01',128,'intimate relationship','mối quan hệ thân mật','adj + n','[{"en":"The study explores how trust develops in an intimate relationship.","vi":"Nghiên cứu khám phá cách lòng tin phát triển trong một mối quan hệ thân mật."},{"en":"An intimate relationship requires honest and open communication.","vi":"Một mối quan hệ thân mật cần sự giao tiếp trung thực và cởi mở."},{"en":"Stress can place strain on even a strong intimate relationship.","vi":"Căng thẳng có thể gây áp lực ngay cả lên một mối quan hệ thân mật vững chắc."}]','[]',NULL,'/ˈɪntəmət rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4469,'colloc-8-01',129,'intimately connected to','gắn bó chặt chẽ với','adv + vpp','[{"en":"Language is intimately connected to the culture that produces it.","vi":"Ngôn ngữ gắn bó chặt chẽ với nền văn hóa đã sản sinh ra nó."},{"en":"Poverty is intimately connected to poor health outcomes worldwide.","vi":"Nghèo đói gắn bó chặt chẽ với các kết quả sức khỏe kém trên toàn cầu."},{"en":"The two theories are intimately connected to one another.","vi":"Hai lý thuyết này gắn bó chặt chẽ với nhau."}]','[]',NULL,'/ˈɪntəmətli kəˈnektɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4470,'colloc-8-01',130,'intrinsic value','giá trị nội tại','adj + n','[{"en":"Philosophers debate whether nature has intrinsic value of its own.","vi":"Các triết gia tranh luận liệu thiên nhiên có giá trị nội tại hay không."},{"en":"Education has an intrinsic value beyond future earning power.","vi":"Giáo dục có một giá trị nội tại vượt ra ngoài khả năng kiếm tiền tương lai."},{"en":"The artwork''s intrinsic value does not depend on its price.","vi":"Giá trị nội tại của tác phẩm nghệ thuật không phụ thuộc vào giá tiền."}]','[]',NULL,'/ɪnˈtrɪnsɪk ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4471,'colloc-8-01',131,'introduce legislation','đưa ra dự luật','v + n','[{"en":"The government plans to introduce legislation on data privacy.","vi":"Chính phủ dự định đưa ra dự luật về quyền riêng tư dữ liệu."},{"en":"Lawmakers introduce legislation hoping to curb pollution.","vi":"Các nhà lập pháp đưa ra dự luật với hy vọng hạn chế ô nhiễm."},{"en":"It took years to introduce legislation protecting workers'' rights.","vi":"Phải mất nhiều năm để đưa ra dự luật bảo vệ quyền của người lao động."}]','[]',NULL,'/ˌɪntrəˈduːs ˌledʒɪsˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4472,'colloc-8-01',132,'introductory chapter','chương mở đầu','adj + n','[{"en":"The introductory chapter outlines the main argument of the book.","vi":"Chương mở đầu phác thảo luận điểm chính của cuốn sách."},{"en":"Read the introductory chapter carefully before the first lecture.","vi":"Hãy đọc kỹ chương mở đầu trước buổi giảng đầu tiên."},{"en":"Her introductory chapter sets out the research questions clearly.","vi":"Chương mở đầu của cô trình bày rõ các câu hỏi nghiên cứu."}]','[]',NULL,'/ˌɪntrəˈdʌktəri ˈtʃæptər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4473,'colloc-8-01',133,'introductory section','phần mở đầu','adj + n','[{"en":"The introductory section explains why the topic matters today.","vi":"Phần mở đầu giải thích vì sao chủ đề này quan trọng hiện nay."},{"en":"Keep the introductory section brief and focused on context.","vi":"Hãy giữ phần mở đầu ngắn gọn và tập trung vào bối cảnh."},{"en":"Reviewers often judge a paper from its introductory section.","vi":"Người phản biện thường đánh giá bài báo qua phần mở đầu."}]','[]',NULL,'/ˌɪntrəˈdʌktəri ˈsekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4474,'colloc-8-01',134,'introductory text','giáo trình nhập môn','adj + n','[{"en":"This introductory text covers the basics of economics clearly.","vi":"Giáo trình nhập môn này trình bày rõ những điều cơ bản của kinh tế học."},{"en":"Beginners should start with an accessible introductory text.","vi":"Người mới nên bắt đầu với một giáo trình nhập môn dễ hiểu."},{"en":"The introductory text includes exercises at the end of each chapter.","vi":"Giáo trình nhập môn có bài tập ở cuối mỗi chương."}]','[]',NULL,'/ˌɪntrəˈdʌktəri ˈtekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4475,'colloc-8-01',135,'keenly aware','ý thức rõ rệt, nhận thức sâu sắc','adv + adj','[{"en":"The author is keenly aware of the limits of her data.","vi":"Tác giả ý thức rõ rệt về những giới hạn trong dữ liệu của mình."},{"en":"Managers must be keenly aware of changing market conditions.","vi":"Các nhà quản lý phải nhận thức sâu sắc về điều kiện thị trường thay đổi."},{"en":"We were keenly aware that time was running short.","vi":"Chúng tôi ý thức rõ rệt rằng thời gian sắp hết."}]','[]',NULL,'/ˈkiːnli əˈwer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4476,'colloc-8-01',136,'key area','lĩnh vực then chốt','adj + n','[{"en":"The report identifies three key areas for future research.","vi":"Báo cáo xác định ba lĩnh vực then chốt cho nghiên cứu tương lai."},{"en":"Healthcare is a key area in which reform is urgently needed.","vi":"Y tế là một lĩnh vực then chốt cần cải cách gấp."},{"en":"The course covers several key areas of modern linguistics.","vi":"Khóa học bao quát vài lĩnh vực then chốt của ngôn ngữ học hiện đại."}]','[]',NULL,'/ˈkiː ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4477,'colloc-8-01',137,'key aspect','khía cạnh then chốt','adj + n','[{"en":"Motivation is a key aspect of successful language learning.","vi":"Động lực là một khía cạnh then chốt của việc học ngôn ngữ thành công."},{"en":"The essay overlooks one key aspect of the original theory.","vi":"Bài luận bỏ qua một khía cạnh then chốt của lý thuyết gốc."},{"en":"Cost remains a key aspect of any practical solution.","vi":"Chi phí vẫn là một khía cạnh then chốt của bất kỳ giải pháp thực tế nào."}]','[]',NULL,'/ˈkiː ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4478,'colloc-8-01',138,'key characteristic','đặc điểm then chốt','adj + n','[{"en":"Flexibility is a key characteristic of a good research design.","vi":"Tính linh hoạt là một đặc điểm then chốt của thiết kế nghiên cứu tốt."},{"en":"The author lists the key characteristics of each social group.","vi":"Tác giả liệt kê các đặc điểm then chốt của từng nhóm xã hội."},{"en":"Transparency is a key characteristic of trustworthy institutions.","vi":"Minh bạch là một đặc điểm then chốt của các thể chế đáng tin."}]','[]',NULL,'/ˈkiː ˌkærəktəˈrɪstɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4479,'colloc-8-01',139,'key component','thành phần then chốt','adj + n','[{"en":"Feedback is a key component of the whole learning process.","vi":"Phản hồi là một thành phần then chốt của toàn bộ quá trình học."},{"en":"Trust is a key component of any lasting partnership.","vi":"Lòng tin là một thành phần then chốt của mọi quan hệ đối tác bền vững."},{"en":"Memory is a key component in the model of cognition.","vi":"Trí nhớ là một thành phần then chốt trong mô hình nhận thức."}]','[]',NULL,'/ˈkiː kəmˈpoʊnənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4480,'colloc-8-01',140,'key concept','khái niệm then chốt','adj + n','[{"en":"The lecture introduced several key concepts in economics.","vi":"Bài giảng giới thiệu vài khái niệm then chốt trong kinh tế học."},{"en":"Students should master this key concept before moving on.","vi":"Sinh viên nên nắm vững khái niệm then chốt này trước khi học tiếp."},{"en":"Identity is a key concept running through the entire course.","vi":"Bản sắc là một khái niệm then chốt xuyên suốt cả khóa học."}]','[]',NULL,'/ˈkiː ˈkɑːnsept/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4481,'colloc-8-01',141,'key element','yếu tố then chốt','adj + n','[{"en":"Clear goals are a key element of effective planning.","vi":"Mục tiêu rõ ràng là một yếu tố then chốt của việc lập kế hoạch hiệu quả."},{"en":"The author treats narrative as a key element of memory.","vi":"Tác giả xem tự sự là một yếu tố then chốt của trí nhớ."},{"en":"Cooperation became a key element in the project''s success.","vi":"Sự hợp tác trở thành một yếu tố then chốt cho thành công của dự án."}]','[]',NULL,'/ˈkiː ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4482,'colloc-8-01',142,'key factor','nhân tố then chốt','adj + n','[{"en":"Cost was a key factor in the committee''s final decision.","vi":"Chi phí là một nhân tố then chốt trong quyết định cuối của hội đồng."},{"en":"Climate is a key factor shaping where crops can grow.","vi":"Khí hậu là một nhân tố then chốt quyết định nơi cây trồng có thể phát triển."},{"en":"Motivation is often the key factor behind student success.","vi":"Động lực thường là nhân tố then chốt đằng sau thành công của sinh viên."}]','[]',NULL,'/ˈkiː ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4483,'colloc-8-01',143,'key feature','đặc trưng then chốt','adj + n','[{"en":"Symmetry is a key feature of the building''s design.","vi":"Tính đối xứng là một đặc trưng then chốt trong thiết kế tòa nhà."},{"en":"The report highlights the key features of the new system.","vi":"Báo cáo nêu bật các đặc trưng then chốt của hệ thống mới."},{"en":"Repetition is a key feature of the poem''s structure.","vi":"Sự lặp lại là một đặc trưng then chốt trong cấu trúc bài thơ."}]','[]',NULL,'/ˈkiː ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4484,'colloc-8-01',144,'key findings','những phát hiện then chốt','adj + n','[{"en":"The abstract summarizes the study''s key findings in a paragraph.","vi":"Phần tóm tắt nêu những phát hiện then chốt của nghiên cứu trong một đoạn."},{"en":"She presented the key findings to the research committee.","vi":"Cô trình bày những phát hiện then chốt cho hội đồng nghiên cứu."},{"en":"The key findings challenge several long-held assumptions.","vi":"Những phát hiện then chốt thách thức vài giả định lâu nay."}]','[]',NULL,'/ˈkiː ˈfaɪndɪŋz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4485,'colloc-8-01',145,'key issue','vấn đề then chốt','adj + n','[{"en":"Funding remains the key issue facing the new program.","vi":"Kinh phí vẫn là vấn đề then chốt mà chương trình mới đối mặt."},{"en":"The debate centered on one key issue: data privacy.","vi":"Cuộc tranh luận xoay quanh một vấn đề then chốt: quyền riêng tư dữ liệu."},{"en":"Fairness is a key issue in any discussion of taxation.","vi":"Công bằng là một vấn đề then chốt trong mọi cuộc bàn về thuế."}]','[]',NULL,'/ˈkiː ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4486,'colloc-8-01',146,'key objective','mục tiêu then chốt','adj + n','[{"en":"Reducing waste is a key objective of the new policy.","vi":"Giảm lãng phí là một mục tiêu then chốt của chính sách mới."},{"en":"The plan lists three key objectives for the coming year.","vi":"Kế hoạch liệt kê ba mục tiêu then chốt cho năm tới."},{"en":"Improving safety remained the project''s key objective throughout.","vi":"Cải thiện an toàn vẫn là mục tiêu then chốt của dự án từ đầu đến cuối."}]','[]',NULL,'/ˈkiː əbˈdʒektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4487,'colloc-8-01',147,'key player','nhân vật chủ chốt','adj + n','[{"en":"The company is a key player in the renewable energy market.","vi":"Công ty là một nhân vật chủ chốt trên thị trường năng lượng tái tạo."},{"en":"She became a key player in the negotiations early on.","vi":"Cô trở thành nhân vật chủ chốt trong các cuộc đàm phán từ sớm."},{"en":"Several key players left the project before it was finished.","vi":"Vài nhân vật chủ chốt đã rời dự án trước khi nó hoàn thành."}]','[]',NULL,'/ˈkiː ˈpleɪər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4488,'colloc-8-01',148,'key policy','chính sách then chốt','adj + n','[{"en":"Education reform was the government''s key policy that year.","vi":"Cải cách giáo dục là chính sách then chốt của chính phủ năm đó."},{"en":"The party announced several key policies before the election.","vi":"Đảng công bố vài chính sách then chốt trước cuộc bầu cử."},{"en":"Critics questioned whether the key policy would actually work.","vi":"Giới phê bình nghi ngờ liệu chính sách then chốt có thực sự hiệu quả."}]','[]',NULL,'/ˈkiː ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4489,'colloc-8-01',149,'key principle','nguyên tắc then chốt','adj + n','[{"en":"Fairness is a key principle underlying the whole legal system.","vi":"Công bằng là một nguyên tắc then chốt làm nền cho cả hệ thống pháp luật."},{"en":"The chapter explains the key principles of sustainable design.","vi":"Chương này giải thích các nguyên tắc then chốt của thiết kế bền vững."},{"en":"Respect for evidence is a key principle of good science.","vi":"Tôn trọng bằng chứng là một nguyên tắc then chốt của khoa học chân chính."}]','[]',NULL,'/ˈkiː ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4490,'colloc-8-01',150,'key role','vai trò then chốt','adj + n','[{"en":"Technology plays a key role in modern medical research.","vi":"Công nghệ đóng vai trò then chốt trong nghiên cứu y học hiện đại."},{"en":"Teachers play a key role in shaping young minds.","vi":"Giáo viên đóng vai trò then chốt trong việc hình thành những trí óc trẻ."},{"en":"She played a key role in organizing the conference.","vi":"Cô đóng vai trò then chốt trong việc tổ chức hội nghị."}]','[]',NULL,'/ˈkiː ˈroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4491,'colloc-9-01',1,'key source','nguồn tư liệu then chốt','adj + n','[{"en":"These letters are a key source for understanding the period.","vi":"Những bức thư này là nguồn tư liệu then chốt để hiểu thời kỳ đó."},{"en":"The census remains a key source of population statistics.","vi":"Cuộc tổng điều tra vẫn là nguồn then chốt cho số liệu dân số."},{"en":"Interviews became a key source of evidence in her study.","vi":"Phỏng vấn trở thành nguồn bằng chứng then chốt trong nghiên cứu của cô."}]','[]',NULL,'/ˈkiː ˈsɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4492,'colloc-9-01',2,'key text','văn bản then chốt','adj + n','[{"en":"This essay is a key text in the history of philosophy.","vi":"Tiểu luận này là một văn bản then chốt trong lịch sử triết học."},{"en":"The reading list includes the key texts of the movement.","vi":"Danh mục đọc gồm các văn bản then chốt của trào lưu đó."},{"en":"Scholars still return to this key text again and again.","vi":"Các học giả vẫn liên tục quay lại văn bản then chốt này."}]','[]',NULL,'/ˈkiː ˈtekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4493,'colloc-9-01',3,'key theme','chủ đề then chốt','adj + n','[{"en":"Loss is a key theme running through the entire novel.","vi":"Mất mát là một chủ đề then chốt xuyên suốt cả cuốn tiểu thuyết."},{"en":"The conference focused on three key themes in education.","vi":"Hội nghị tập trung vào ba chủ đề then chốt trong giáo dục."},{"en":"Identity emerges as a key theme in her later poems.","vi":"Bản sắc nổi lên như một chủ đề then chốt trong các bài thơ sau này của bà."}]','[]',NULL,'/ˈkiː ˈθiːm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4494,'colloc-9-01',4,'key topic','chủ đề then chốt','adj + n','[{"en":"Climate change is a key topic in environmental science courses.","vi":"Biến đổi khí hậu là một chủ đề then chốt trong các môn khoa học môi trường."},{"en":"The seminar will cover several key topics in detail.","vi":"Buổi hội thảo sẽ đề cập chi tiết vài chủ đề then chốt."},{"en":"Inequality has become a key topic in public debate.","vi":"Bất bình đẳng đã trở thành một chủ đề then chốt trong tranh luận công khai."}]','[]',NULL,'/ˈkiː ˈtɑːpɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4495,'colloc-9-01',5,'large majority','đa số áp đảo','adj + n','[{"en":"A large majority of students supported the proposed change.","vi":"Một đa số áp đảo sinh viên ủng hộ thay đổi được đề xuất."},{"en":"The bill passed with a large majority in parliament.","vi":"Dự luật được thông qua với đa số áp đảo trong quốc hội."},{"en":"In the survey, a large majority preferred online classes.","vi":"Trong khảo sát, một đa số áp đảo thích các lớp học trực tuyến."}]','[]',NULL,'/ˈlɑːrdʒ məˈdʒɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4496,'colloc-9-01',6,'large percentage','tỷ lệ phần trăm lớn','adj + n','[{"en":"A large percentage of the budget goes toward research.","vi":"Một tỷ lệ phần trăm lớn của ngân sách dành cho nghiên cứu."},{"en":"A large percentage of respondents reported feeling stressed.","vi":"Một tỷ lệ phần trăm lớn người trả lời cho biết họ thấy căng thẳng."},{"en":"The disease affects a large percentage of the elderly.","vi":"Căn bệnh ảnh hưởng đến một tỷ lệ phần trăm lớn người cao tuổi."}]','[]',NULL,'/ˈlɑːrdʒ pərˈsentɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4497,'colloc-9-01',7,'large portion','phần lớn','adj + n','[{"en":"A large portion of the data was collected during summer.","vi":"Phần lớn dữ liệu đã được thu thập trong mùa hè."},{"en":"She devoted a large portion of the essay to methods.","vi":"Cô dành phần lớn bài luận để nói về phương pháp."},{"en":"A large portion of the population lives near the coast.","vi":"Phần lớn dân số sinh sống gần bờ biển."}]','[]',NULL,'/ˈlɑːrdʒ ˈpɔːrʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4498,'colloc-9-01',8,'large proportion of','một phần lớn của','adj + n','[{"en":"A large proportion of income is spent on housing costs.","vi":"Một phần lớn thu nhập được chi cho chi phí nhà ở."},{"en":"A large proportion of the sample came from rural areas.","vi":"Một phần lớn của mẫu khảo sát đến từ vùng nông thôn."},{"en":"A large proportion of energy is still lost as heat.","vi":"Một phần lớn năng lượng vẫn bị thất thoát dưới dạng nhiệt."}]','[]',NULL,'/ˈlɑːrdʒ prəˈpɔːrʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4499,'colloc-9-01',9,'large quantities of','một lượng lớn','adj + n','[{"en":"The factory releases large quantities of waste into the river.","vi":"Nhà máy thải một lượng lớn chất thải ra sông."},{"en":"Researchers processed large quantities of survey data by computer.","vi":"Các nhà nghiên cứu xử lý một lượng lớn dữ liệu khảo sát bằng máy tính."},{"en":"Large quantities of food are wasted every single day.","vi":"Một lượng lớn thực phẩm bị lãng phí mỗi ngày."}]','[]',NULL,'/ˈlɑːrdʒ ˈkwɑːntətiz əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4500,'colloc-9-01',10,'large range of','phạm vi rộng các','adj + n','[{"en":"The library offers a large range of academic resources.","vi":"Thư viện cung cấp một phạm vi rộng các tài nguyên học thuật."},{"en":"The study covered a large range of age groups.","vi":"Nghiên cứu bao quát một phạm vi rộng các nhóm tuổi."},{"en":"The course explores a large range of historical sources.","vi":"Khóa học khám phá một phạm vi rộng các nguồn sử liệu."}]','[]',NULL,'/ˈlɑːrdʒ ˈreɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4501,'colloc-9-01',11,'largely based on','chủ yếu dựa trên','adv + vpp','[{"en":"Her argument is largely based on earlier field research.","vi":"Lập luận của cô chủ yếu dựa trên nghiên cứu thực địa trước đó."},{"en":"The model is largely based on assumptions about behavior.","vi":"Mô hình này chủ yếu dựa trên các giả định về hành vi."},{"en":"The film is largely based on a true historical event.","vi":"Bộ phim chủ yếu dựa trên một sự kiện lịch sử có thật."}]','[]',NULL,'/ˈlɑːrdʒli ˈbeɪst ɑːn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4502,'colloc-9-01',12,'largely confined to','phần lớn giới hạn trong','adv + vpp','[{"en":"The disease is largely confined to tropical regions.","vi":"Căn bệnh phần lớn giới hạn trong các vùng nhiệt đới."},{"en":"Early debate was largely confined to a few specialists.","vi":"Cuộc tranh luận ban đầu phần lớn giới hạn trong vài chuyên gia."},{"en":"Such practices were largely confined to rural communities.","vi":"Những tập tục như vậy phần lớn giới hạn trong các cộng đồng nông thôn."}]','[]',NULL,'/ˈlɑːrdʒli kənˈfaɪnd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4503,'colloc-9-01',13,'largely determined by','phần lớn được quyết định bởi','adv + vpp','[{"en":"Success is largely determined by effort and preparation.","vi":"Thành công phần lớn được quyết định bởi nỗ lực và sự chuẩn bị."},{"en":"Crop yields are largely determined by rainfall each season.","vi":"Năng suất cây trồng phần lớn được quyết định bởi lượng mưa mỗi mùa."},{"en":"Wages are largely determined by supply and demand.","vi":"Tiền lương phần lớn được quyết định bởi cung và cầu."}]','[]',NULL,'/ˈlɑːrdʒli dɪˈtɜːrmɪnd baɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4504,'colloc-9-01',14,'largely ignored','phần lớn bị phớt lờ','adv + vpp','[{"en":"Her early warnings were largely ignored by the authorities.","vi":"Những cảnh báo sớm của cô phần lớn bị giới chức phớt lờ."},{"en":"The issue was largely ignored until the crisis began.","vi":"Vấn đề này phần lớn bị phớt lờ cho đến khi khủng hoảng bắt đầu."},{"en":"These findings were largely ignored by later researchers.","vi":"Những phát hiện này phần lớn bị các nhà nghiên cứu sau phớt lờ."}]','[]',NULL,'/ˈlɑːrdʒli ɪɡˈnɔːrd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4505,'colloc-9-01',15,'largely responsible for','phần lớn chịu trách nhiệm cho','adv + adj','[{"en":"Human activity is largely responsible for rising temperatures.","vi":"Hoạt động của con người phần lớn chịu trách nhiệm cho nhiệt độ tăng."},{"en":"Poor planning was largely responsible for the project''s delay.","vi":"Việc lập kế hoạch kém phần lớn chịu trách nhiệm cho sự chậm trễ của dự án."},{"en":"She was largely responsible for the program''s early success.","vi":"Cô phần lớn chịu trách nhiệm cho thành công ban đầu của chương trình."}]','[]',NULL,'/ˈlɑːrdʒli rɪˈspɑːnsəbəl fər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4506,'colloc-9-01',16,'later work','công trình về sau','adj + n','[{"en":"His later work shows a clear shift in style.","vi":"Công trình về sau của ông cho thấy một sự thay đổi rõ về phong cách."},{"en":"Her later work builds directly on these early experiments.","vi":"Công trình về sau của cô xây dựng trực tiếp trên những thí nghiệm ban đầu này."},{"en":"Critics often prefer the artist''s later work to her earliest.","vi":"Giới phê bình thường thích công trình về sau của nghệ sĩ hơn các tác phẩm đầu tay."}]','[]',NULL,'/ˈleɪtər ˈwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4507,'colloc-9-01',17,'later writings','các trước tác về sau','adj + n','[{"en":"His later writings reveal a more cautious philosophical view.","vi":"Các trước tác về sau của ông bộc lộ một quan điểm triết học thận trọng hơn."},{"en":"Scholars find new themes in her later writings.","vi":"Các học giả tìm thấy những chủ đề mới trong các trước tác về sau của bà."},{"en":"The later writings address questions the early ones avoided.","vi":"Các trước tác về sau giải quyết những câu hỏi mà tác phẩm đầu tránh né."}]','[]',NULL,'/ˈleɪtər ˈraɪtɪŋz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4508,'colloc-9-01',18,'lead to the conclusion','dẫn đến kết luận','v + n','[{"en":"These results lead to the conclusion that the method works.","vi":"Những kết quả này dẫn đến kết luận rằng phương pháp có hiệu quả."},{"en":"Such evidence may lead to the conclusion that reform is needed.","vi":"Bằng chứng như vậy có thể dẫn đến kết luận rằng cần cải cách."},{"en":"The data lead to the conclusion that costs are rising.","vi":"Dữ liệu dẫn đến kết luận rằng chi phí đang tăng."}]','[]',NULL,'/ˈliːd tə ðə kənˈkluːʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4509,'colloc-9-01',19,'leading role','vai trò dẫn dắt','adj + n','[{"en":"The university played a leading role in the research effort.","vi":"Trường đại học đóng vai trò dẫn dắt trong nỗ lực nghiên cứu."},{"en":"She took a leading role in shaping the new policy.","vi":"Cô đảm nhận vai trò dẫn dắt trong việc định hình chính sách mới."},{"en":"The country has a leading role in regional trade talks.","vi":"Quốc gia này có vai trò dẫn dắt trong các cuộc đàm phán thương mại khu vực."}]','[]',NULL,'/ˈliːdɪŋ ˈroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4510,'colloc-9-01',20,'learning activity','hoạt động học tập','adj + n','[{"en":"Each learning activity is designed to reinforce a key skill.","vi":"Mỗi hoạt động học tập được thiết kế để củng cố một kỹ năng then chốt."},{"en":"Group discussion is a popular learning activity in this class.","vi":"Thảo luận nhóm là một hoạt động học tập phổ biến trong lớp này."},{"en":"Teachers vary learning activities to keep students engaged.","vi":"Giáo viên thay đổi các hoạt động học tập để giữ học sinh hứng thú."}]','[]',NULL,'/ˈlɜːrnɪŋ ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4511,'colloc-9-01',21,'learning difficulties','khó khăn trong học tập','n + n','[{"en":"The school offers extra support for children with learning difficulties.","vi":"Trường cung cấp hỗ trợ thêm cho trẻ có khó khăn trong học tập."},{"en":"Early diagnosis of learning difficulties improves later outcomes.","vi":"Chẩn đoán sớm khó khăn trong học tập giúp cải thiện kết quả về sau."},{"en":"Teachers are trained to recognize common learning difficulties.","vi":"Giáo viên được đào tạo để nhận ra các khó khăn học tập thường gặp."}]','[]',NULL,'/ˈlɜːrnɪŋ ˈdɪfɪkəltiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4512,'colloc-9-01',22,'learning environment','môi trường học tập','n + n','[{"en":"A safe learning environment helps students take more risks.","vi":"Một môi trường học tập an toàn giúp học sinh dám mạo hiểm hơn."},{"en":"Technology has transformed the modern learning environment.","vi":"Công nghệ đã thay đổi môi trường học tập hiện đại."},{"en":"Teachers work hard to create a positive learning environment.","vi":"Giáo viên nỗ lực tạo ra một môi trường học tập tích cực."}]','[]',NULL,'/ˈlɜːrnɪŋ ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4513,'colloc-9-01',23,'learning objective','mục tiêu học tập','n + n','[{"en":"Each lesson begins with a clearly stated learning objective.","vi":"Mỗi bài học bắt đầu với một mục tiêu học tập được nêu rõ."},{"en":"The teacher aligned the activities with the learning objectives.","vi":"Giáo viên đã gắn các hoạt động với mục tiêu học tập."},{"en":"Students should know the learning objectives before they start.","vi":"Học sinh nên biết các mục tiêu học tập trước khi bắt đầu."}]','[]',NULL,'/ˈlɜːrnɪŋ əbˈdʒektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4514,'colloc-9-01',24,'learning outcome','kết quả học tập đầu ra','n + n','[{"en":"The course lists its learning outcomes in the syllabus.","vi":"Khóa học liệt kê các kết quả học tập đầu ra trong đề cương."},{"en":"Assessment should match the stated learning outcomes closely.","vi":"Việc đánh giá nên bám sát các kết quả học tập đầu ra đã nêu."},{"en":"Clear learning outcomes help students measure their progress.","vi":"Kết quả học tập đầu ra rõ ràng giúp học sinh đo lường tiến bộ."}]','[]',NULL,'/ˈlɜːrnɪŋ ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4515,'colloc-9-01',25,'learning process','quá trình học tập','n + n','[{"en":"Mistakes are a natural part of the learning process.","vi":"Sai lầm là một phần tự nhiên của quá trình học tập."},{"en":"Feedback plays a central role in the learning process.","vi":"Phản hồi đóng vai trò trung tâm trong quá trình học tập."},{"en":"The study examines how emotion shapes the learning process.","vi":"Nghiên cứu xem xét cách cảm xúc định hình quá trình học tập."}]','[]',NULL,'/ˈlɜːrnɪŋ ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4516,'colloc-9-01',26,'learning resources','tài nguyên học tập','n + n','[{"en":"The platform offers free learning resources to every student.","vi":"Nền tảng cung cấp tài nguyên học tập miễn phí cho mọi học sinh."},{"en":"Good learning resources can make difficult topics easier.","vi":"Tài nguyên học tập tốt có thể giúp các chủ đề khó trở nên dễ hơn."},{"en":"Teachers create learning resources tailored to their classes.","vi":"Giáo viên tạo ra tài nguyên học tập phù hợp với lớp của mình."}]','[]',NULL,'/ˈlɜːrnɪŋ ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4517,'colloc-9-01',27,'learning strategy','chiến lược học tập','n + n','[{"en":"Spacing out review is an effective learning strategy.","vi":"Giãn cách việc ôn tập là một chiến lược học tập hiệu quả."},{"en":"Students benefit from trying several learning strategies.","vi":"Học sinh hưởng lợi khi thử nhiều chiến lược học tập khác nhau."},{"en":"The teacher explained a simple learning strategy for vocabulary.","vi":"Giáo viên giải thích một chiến lược học tập đơn giản cho từ vựng."}]','[]',NULL,'/ˈlɜːrnɪŋ ˈstrætədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4518,'colloc-9-01',28,'legal action','hành động pháp lý','adj + n','[{"en":"The company threatened legal action against its former partner.","vi":"Công ty đe dọa hành động pháp lý chống lại đối tác cũ."},{"en":"Victims may take legal action to recover their losses.","vi":"Nạn nhân có thể tiến hành hành động pháp lý để đòi lại tổn thất."},{"en":"Legal action was avoided when both sides reached a settlement.","vi":"Hành động pháp lý được tránh khi hai bên đạt được thỏa thuận."}]','[]',NULL,'/ˈliːɡəl ˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4519,'colloc-9-01',29,'legal basis','cơ sở pháp lý','adj + n','[{"en":"The decision lacked any clear legal basis at the time.","vi":"Quyết định khi đó thiếu một cơ sở pháp lý rõ ràng."},{"en":"The treaty provides the legal basis for the new rules.","vi":"Hiệp ước cung cấp cơ sở pháp lý cho các quy định mới."},{"en":"Lawyers questioned the legal basis of the government''s order.","vi":"Các luật sư đặt nghi vấn về cơ sở pháp lý của lệnh chính phủ."}]','[]',NULL,'/ˈliːɡəl ˈbeɪsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4520,'colloc-9-01',30,'legal framework','khung pháp lý','adj + n','[{"en":"A clear legal framework is needed to regulate the industry.","vi":"Cần một khung pháp lý rõ ràng để điều chỉnh ngành công nghiệp này."},{"en":"The new legal framework protects consumers more effectively.","vi":"Khung pháp lý mới bảo vệ người tiêu dùng hiệu quả hơn."},{"en":"Companies must operate within the existing legal framework.","vi":"Các công ty phải hoạt động trong khung pháp lý hiện hành."}]','[]',NULL,'/ˈliːɡəl ˈfreɪmwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4521,'colloc-9-01',31,'legal issue','vấn đề pháp lý','adj + n','[{"en":"The contract raised several complex legal issues for the team.","vi":"Hợp đồng đặt ra vài vấn đề pháp lý phức tạp cho nhóm."},{"en":"Privacy has become a major legal issue in technology.","vi":"Quyền riêng tư đã trở thành một vấn đề pháp lý lớn trong công nghệ."},{"en":"The lawyer advised her on a tricky legal issue.","vi":"Luật sư tư vấn cho cô về một vấn đề pháp lý hóc búa."}]','[]',NULL,'/ˈliːɡəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4522,'colloc-9-01',32,'legal obligation','nghĩa vụ pháp lý','adj + n','[{"en":"Employers have a legal obligation to ensure workplace safety.","vi":"Người sử dụng lao động có nghĩa vụ pháp lý bảo đảm an toàn nơi làm việc."},{"en":"The company met its legal obligations under the contract.","vi":"Công ty đã thực hiện các nghĩa vụ pháp lý theo hợp đồng."},{"en":"Paying taxes is a legal obligation for every citizen.","vi":"Nộp thuế là một nghĩa vụ pháp lý của mọi công dân."}]','[]',NULL,'/ˈliːɡəl ˌɑːblɪˈɡeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4523,'colloc-9-01',33,'legal position','tình trạng pháp lý, lập trường pháp lý','adj + n','[{"en":"The lawyer explained the company''s legal position in detail.","vi":"Luật sư giải thích chi tiết tình trạng pháp lý của công ty."},{"en":"Their legal position weakened once new evidence appeared.","vi":"Lập trường pháp lý của họ yếu đi khi bằng chứng mới xuất hiện."},{"en":"We should clarify our legal position before signing anything.","vi":"Chúng ta nên làm rõ tình trạng pháp lý trước khi ký bất cứ điều gì."}]','[]',NULL,'/ˈliːɡəl pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4524,'colloc-9-01',34,'legal proceedings','thủ tục tố tụng','adj + n','[{"en":"Legal proceedings began after the two firms failed to agree.","vi":"Thủ tục tố tụng bắt đầu sau khi hai công ty không thể thỏa thuận."},{"en":"The legal proceedings could last for several years.","vi":"Thủ tục tố tụng có thể kéo dài nhiều năm."},{"en":"She was advised not to comment during the legal proceedings.","vi":"Cô được khuyên không bình luận trong quá trình tố tụng."}]','[]',NULL,'/ˈliːɡəl prəˈsiːdɪŋz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4525,'colloc-9-01',35,'legal protection','sự bảo vệ pháp lý','adj + n','[{"en":"The law gives strong legal protection to tenants.","vi":"Luật trao sự bảo vệ pháp lý mạnh mẽ cho người thuê nhà."},{"en":"Workers demanded better legal protection against unfair dismissal.","vi":"Người lao động đòi hỏi sự bảo vệ pháp lý tốt hơn trước sa thải bất công."},{"en":"Copyright offers legal protection for original creative work.","vi":"Bản quyền cung cấp sự bảo vệ pháp lý cho sáng tác gốc."}]','[]',NULL,'/ˈliːɡəl prəˈtekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4526,'colloc-9-01',36,'legal requirement','yêu cầu pháp lý','adj + n','[{"en":"Wearing a seatbelt is a legal requirement in most countries.","vi":"Thắt dây an toàn là một yêu cầu pháp lý ở hầu hết các nước."},{"en":"The firm must meet every legal requirement before opening.","vi":"Công ty phải đáp ứng mọi yêu cầu pháp lý trước khi mở cửa."},{"en":"Reporting income is a legal requirement for all businesses.","vi":"Khai báo thu nhập là một yêu cầu pháp lý đối với mọi doanh nghiệp."}]','[]',NULL,'/ˈliːɡəl rɪˈkwaɪrmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4527,'colloc-9-01',37,'legal right','quyền hợp pháp','adj + n','[{"en":"Every citizen has the legal right to a fair trial.","vi":"Mọi công dân đều có quyền hợp pháp được xét xử công bằng."},{"en":"Workers have a legal right to safe working conditions.","vi":"Người lao động có quyền hợp pháp được làm việc trong điều kiện an toàn."},{"en":"The reform extended legal rights to more groups.","vi":"Cuộc cải cách mở rộng quyền hợp pháp cho nhiều nhóm hơn."}]','[]',NULL,'/ˈliːɡəl ˈraɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4528,'colloc-9-01',38,'legal rule','quy tắc pháp lý','adj + n','[{"en":"A clear legal rule helps judges decide similar cases.","vi":"Một quy tắc pháp lý rõ ràng giúp thẩm phán xử các vụ tương tự."},{"en":"The new legal rule applies to all imported goods.","vi":"Quy tắc pháp lý mới áp dụng cho mọi hàng hóa nhập khẩu."},{"en":"Courts sometimes reinterpret an old legal rule over time.","vi":"Tòa án đôi khi diễn giải lại một quy tắc pháp lý cũ theo thời gian."}]','[]',NULL,'/ˈliːɡəl ˈruːl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4529,'colloc-9-01',39,'legal status','tư cách pháp lý','adj + n','[{"en":"The treaty clarifies the legal status of refugees in the country.","vi":"Hiệp ước làm rõ tư cách pháp lý của người tị nạn trong nước."},{"en":"Marriage can change a person''s legal status in many ways.","vi":"Hôn nhân có thể thay đổi tư cách pháp lý của một người theo nhiều cách."},{"en":"Lawyers debated the legal status of the disputed land.","vi":"Các luật sư tranh luận về tư cách pháp lý của khu đất tranh chấp."}]','[]',NULL,'/ˈliːɡəl ˈstætəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4530,'colloc-9-01',40,'legal system','hệ thống pháp luật','adj + n','[{"en":"The country''s legal system protects the rights of every citizen.","vi":"Hệ thống pháp luật của quốc gia bảo vệ quyền của mọi công dân."},{"en":"Reforming the legal system requires careful planning and broad support.","vi":"Cải cách hệ thống pháp luật đòi hỏi kế hoạch kỹ lưỡng và sự ủng hộ rộng rãi."},{"en":"Students compared the legal system of two different nations.","vi":"Sinh viên so sánh hệ thống pháp luật của hai quốc gia khác nhau."}]','[]',NULL,'/ˈliːɡəl ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4531,'colloc-9-01',41,'legislative measures','các biện pháp lập pháp','adj + n','[{"en":"The government introduced legislative measures to reduce air pollution.","vi":"Chính phủ đưa ra các biện pháp lập pháp để giảm ô nhiễm không khí."},{"en":"New legislative measures aim to protect workers from unfair dismissal.","vi":"Các biện pháp lập pháp mới nhằm bảo vệ người lao động khỏi việc sa thải bất công."},{"en":"Effective legislative measures often follow extensive public consultation.","vi":"Các biện pháp lập pháp hiệu quả thường theo sau quá trình tham vấn công chúng rộng rãi."}]','[]',NULL,'/ˈledʒɪsleɪtɪv ˈmeʒərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4532,'colloc-9-01',42,'legislative power','quyền lập pháp','adj + n','[{"en":"The constitution gives legislative power to the elected parliament.","vi":"Hiến pháp trao quyền lập pháp cho nghị viện được bầu."},{"en":"Critics argued that the reform expanded the president''s legislative power.","vi":"Các nhà phê bình cho rằng cải cách đã mở rộng quyền lập pháp của tổng thống."},{"en":"Legislative power should remain separate from the judiciary.","vi":"Quyền lập pháp nên tách biệt khỏi quyền tư pháp."}]','[]',NULL,'/ˈledʒɪsleɪtɪv ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4533,'colloc-9-01',43,'liberal democracy','nền dân chủ tự do','adj + n','[{"en":"A liberal democracy depends on free elections and individual rights.","vi":"Một nền dân chủ tự do phụ thuộc vào bầu cử tự do và quyền cá nhân."},{"en":"The essay examined challenges facing modern liberal democracy.","vi":"Bài luận xem xét những thách thức mà nền dân chủ tự do hiện đại đối mặt."},{"en":"In a liberal democracy, the press operates without state control.","vi":"Trong nền dân chủ tự do, báo chí hoạt động mà không bị nhà nước kiểm soát."}]','[]',NULL,'/ˈlɪbərəl dɪˈmɑːkrəsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4534,'colloc-9-01',44,'lifelong learning','học tập suốt đời','adj + n','[{"en":"Lifelong learning helps people adapt to a changing job market.","vi":"Học tập suốt đời giúp con người thích nghi với thị trường việc làm đang thay đổi."},{"en":"The university promotes lifelong learning through its evening courses.","vi":"Trường đại học thúc đẩy học tập suốt đời qua các khóa học buổi tối."},{"en":"Many employers now value a commitment to lifelong learning.","vi":"Nhiều nhà tuyển dụng giờ đây coi trọng cam kết học tập suốt đời."}]','[]',NULL,'/ˈlaɪflɔːŋ ˈlɜːrnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4535,'colloc-9-01',45,'likely impact','tác động có khả năng xảy ra','adj + n','[{"en":"Researchers assessed the likely impact of the new policy.","vi":"Các nhà nghiên cứu đánh giá tác động có khả năng xảy ra của chính sách mới."},{"en":"The report describes the likely impact of climate change on farming.","vi":"Báo cáo mô tả tác động có khả năng xảy ra của biến đổi khí hậu lên nông nghiệp."},{"en":"Economists disagreed about the likely impact of the tax cut.","vi":"Các nhà kinh tế bất đồng về tác động có khả năng xảy ra của việc giảm thuế."}]','[]',NULL,'/ˈlaɪkli ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4536,'colloc-9-01',46,'likely outcome','kết quả có khả năng xảy ra','adj + n','[{"en":"Analysts predicted the most likely outcome of the election.","vi":"Các nhà phân tích dự đoán kết quả có khả năng xảy ra nhất của cuộc bầu cử."},{"en":"The model calculates the likely outcome of each treatment.","vi":"Mô hình tính toán kết quả có khả năng xảy ra của mỗi phương pháp điều trị."},{"en":"A delayed flight was the likely outcome of the storm.","vi":"Chuyến bay bị hoãn là kết quả có khả năng xảy ra của cơn bão."}]','[]',NULL,'/ˈlaɪkli ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4537,'colloc-9-01',47,'limited access','khả năng tiếp cận hạn chế','adj + n','[{"en":"Rural areas often have limited access to specialist healthcare.","vi":"Các vùng nông thôn thường có khả năng tiếp cận dịch vụ y tế chuyên khoa hạn chế."},{"en":"Students with limited access to computers fall behind quickly.","vi":"Học sinh có khả năng tiếp cận máy tính hạn chế sẽ tụt lại nhanh chóng."},{"en":"The reserve grants visitors limited access during nesting season.","vi":"Khu bảo tồn cho khách tham quan khả năng tiếp cận hạn chế trong mùa làm tổ."}]','[]',NULL,'/ˈlɪmɪtɪd ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4538,'colloc-9-01',48,'limited capacity','năng lực hạn chế','adj + n','[{"en":"The hospital has limited capacity to treat emergency patients.","vi":"Bệnh viện có năng lực hạn chế để điều trị bệnh nhân cấp cứu."},{"en":"Short-term memory has a limited capacity for holding information.","vi":"Trí nhớ ngắn hạn có năng lực hạn chế trong việc lưu giữ thông tin."},{"en":"Small firms have limited capacity to absorb sudden losses.","vi":"Các công ty nhỏ có năng lực hạn chế để hấp thụ thua lỗ bất ngờ."}]','[]',NULL,'/ˈlɪmɪtɪd kəˈpæsəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4539,'colloc-9-01',49,'limited information','thông tin hạn chế','adj + n','[{"en":"Doctors made the decision with only limited information available.","vi":"Các bác sĩ ra quyết định khi chỉ có thông tin hạn chế."},{"en":"The early study provided limited information about the disease.","vi":"Nghiên cứu ban đầu cung cấp thông tin hạn chế về căn bệnh."},{"en":"Investors often act despite limited information about new markets.","vi":"Các nhà đầu tư thường hành động dù chỉ có thông tin hạn chế về thị trường mới."}]','[]',NULL,'/ˈlɪmɪtɪd ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4540,'colloc-9-01',50,'limited opportunity','cơ hội hạn chế','adj + n','[{"en":"Young people in the village had limited opportunity for advancement.","vi":"Người trẻ trong làng có cơ hội thăng tiến hạn chế."},{"en":"The internship offers limited opportunity to gain practical experience.","vi":"Kỳ thực tập cung cấp cơ hội hạn chế để tích lũy kinh nghiệm thực tế."},{"en":"She faced limited opportunity to present her own research.","vi":"Cô gặp cơ hội hạn chế để trình bày nghiên cứu của riêng mình."}]','[]',NULL,'/ˈlɪmɪtɪd ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4541,'colloc-9-01',51,'limited range of','phạm vi hạn chế của','adj + n','[{"en":"The shop stocked only a limited range of imported goods.","vi":"Cửa hàng chỉ trữ một phạm vi hạn chế của hàng nhập khẩu."},{"en":"The survey covered a limited range of social behaviours.","vi":"Cuộc khảo sát bao quát một phạm vi hạn chế của các hành vi xã hội."},{"en":"Early phones supported a limited range of functions.","vi":"Điện thoại đời đầu hỗ trợ một phạm vi hạn chế của các chức năng."}]','[]',NULL,'/ˈlɪmɪtɪd ˈreɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4542,'colloc-9-01',52,'limited resources','nguồn lực hạn chế','adj + n','[{"en":"Charities must achieve their goals with limited resources.","vi":"Các tổ chức từ thiện phải đạt được mục tiêu với nguồn lực hạn chế."},{"en":"The school managed excellent results despite limited resources.","vi":"Trường đạt kết quả xuất sắc dù có nguồn lực hạn chế."},{"en":"Developing nations often compete for limited resources.","vi":"Các quốc gia đang phát triển thường cạnh tranh giành nguồn lực hạn chế."}]','[]',NULL,'/ˈlɪmɪtɪd ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4543,'colloc-9-01',53,'linear relationship','mối quan hệ tuyến tính','adj + n','[{"en":"The graph shows a clear linear relationship between the two variables.","vi":"Đồ thị cho thấy mối quan hệ tuyến tính rõ ràng giữa hai biến số."},{"en":"Researchers found no linear relationship between diet and mood.","vi":"Các nhà nghiên cứu không tìm thấy mối quan hệ tuyến tính giữa chế độ ăn và tâm trạng."},{"en":"A linear relationship makes the data easy to predict.","vi":"Mối quan hệ tuyến tính khiến dữ liệu dễ dự đoán."}]','[]',NULL,'/ˈlɪniər rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4544,'colloc-9-01',54,'literal interpretation','cách diễn giải theo nghĩa đen','adj + n','[{"en":"A literal interpretation of the poem misses its deeper meaning.","vi":"Cách diễn giải theo nghĩa đen của bài thơ bỏ lỡ ý nghĩa sâu xa của nó."},{"en":"Judges sometimes prefer a literal interpretation of the law.","vi":"Đôi khi các thẩm phán ưa thích cách diễn giải luật theo nghĩa đen."},{"en":"His literal interpretation of the instructions caused confusion.","vi":"Cách diễn giải theo nghĩa đen của anh về hướng dẫn đã gây nhầm lẫn."}]','[]',NULL,'/ˈlɪtərəl ɪnˌtɜːrprɪˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4545,'colloc-9-01',55,'literal meaning','nghĩa đen','adj + n','[{"en":"The literal meaning of the phrase differs from its common usage.","vi":"Nghĩa đen của cụm từ khác với cách dùng thông thường của nó."},{"en":"Idioms cannot be understood from their literal meaning alone.","vi":"Không thể hiểu thành ngữ chỉ qua nghĩa đen của chúng."},{"en":"Translators must look beyond the literal meaning of words.","vi":"Người dịch phải nhìn xa hơn nghĩa đen của từ ngữ."}]','[]',NULL,'/ˈlɪtərəl ˈmiːnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4546,'colloc-9-01',56,'literal sense','nghĩa đen','adj + n','[{"en":"In the literal sense, the word simply means to fall.","vi":"Theo nghĩa đen, từ này chỉ đơn giản có nghĩa là rơi."},{"en":"She did not mean the comment in a literal sense.","vi":"Cô không có ý nói nhận xét đó theo nghĩa đen."},{"en":"Taken in its literal sense, the rule seems absurd.","vi":"Hiểu theo nghĩa đen, quy tắc này có vẻ vô lý."}]','[]',NULL,'/ˈlɪtərəl ˈsens/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4547,'colloc-9-01',57,'literary text','văn bản văn học','adj + n','[{"en":"Students analysed the literary text for its hidden symbolism.","vi":"Sinh viên phân tích văn bản văn học để tìm tính biểu tượng ẩn giấu."},{"en":"Each literary text reflects the era in which it was written.","vi":"Mỗi văn bản văn học phản ánh thời đại mà nó được viết ra."},{"en":"The professor compared two literary texts from the same period.","vi":"Giáo sư so sánh hai văn bản văn học từ cùng một thời kỳ."}]','[]',NULL,'/ˈlɪtəreri ˈtekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4548,'colloc-9-01',58,'literary tradition','truyền thống văn học','adj + n','[{"en":"The novel draws heavily on a rich literary tradition.","vi":"Cuốn tiểu thuyết dựa nhiều vào một truyền thống văn học phong phú."},{"en":"Oral storytelling forms part of the region''s literary tradition.","vi":"Kể chuyện truyền miệng là một phần của truyền thống văn học của vùng."},{"en":"Modern writers often challenge an established literary tradition.","vi":"Các nhà văn hiện đại thường thách thức một truyền thống văn học đã được thiết lập."}]','[]',NULL,'/ˈlɪtəreri trəˈdɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4549,'colloc-9-01',59,'little evidence','ít bằng chứng','adj + n','[{"en":"There is little evidence that the treatment actually works.","vi":"Có ít bằng chứng cho thấy phương pháp điều trị thực sự hiệu quả."},{"en":"The study found little evidence of long-term harm.","vi":"Nghiên cứu tìm thấy ít bằng chứng về tác hại lâu dài."},{"en":"Little evidence supports the claim that prices will fall.","vi":"Ít bằng chứng ủng hộ tuyên bố rằng giá sẽ giảm."}]','[]',NULL,'/ˈlɪtəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4550,'colloc-9-01',60,'little impact','ít tác động','adj + n','[{"en":"The new rules had little impact on student behaviour.","vi":"Các quy tắc mới có ít tác động đến hành vi của học sinh."},{"en":"Advertising made little impact on the company''s sales.","vi":"Quảng cáo có ít tác động đến doanh số của công ty."},{"en":"Small donations have little impact on a large deficit.","vi":"Những khoản quyên góp nhỏ có ít tác động đến một khoản thâm hụt lớn."}]','[]',NULL,'/ˈlɪtəl ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4551,'colloc-9-01',61,'little information','ít thông tin','adj + n','[{"en":"The website offers little information about the program''s costs.","vi":"Trang web cung cấp ít thông tin về chi phí của chương trình."},{"en":"We had little information to guide our final decision.","vi":"Chúng tôi có ít thông tin để định hướng quyết định cuối cùng."},{"en":"Little information existed about the species before this study.","vi":"Có ít thông tin về loài này trước nghiên cứu này."}]','[]',NULL,'/ˈlɪtəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4552,'colloc-9-01',62,'little research','ít nghiên cứu','adj + n','[{"en":"Little research has examined the effects of night-shift work.","vi":"Ít nghiên cứu đã xem xét tác động của công việc ca đêm."},{"en":"Surprisingly little research exists on this common illness.","vi":"Đáng ngạc nhiên là có ít nghiên cứu về căn bệnh phổ biến này."},{"en":"There is little research linking the two phenomena directly.","vi":"Có ít nghiên cứu liên kết trực tiếp hai hiện tượng này."}]','[]',NULL,'/ˈlɪtəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4553,'colloc-9-01',63,'little significance','ít ý nghĩa','adj + n','[{"en":"The difference between the groups had little significance statistically.","vi":"Sự khác biệt giữa các nhóm có ít ý nghĩa về mặt thống kê."},{"en":"Critics argued the discovery held little significance for medicine.","vi":"Các nhà phê bình cho rằng phát hiện này có ít ý nghĩa với y học."},{"en":"These minor errors are of little significance to the result.","vi":"Những lỗi nhỏ này có ít ý nghĩa đối với kết quả."}]','[]',NULL,'/ˈlɪtəl sɪɡˈnɪfɪkəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4554,'colloc-9-01',64,'living conditions','điều kiện sống','adj + n','[{"en":"Poor living conditions can lead to serious health problems.","vi":"Điều kiện sống tồi tệ có thể dẫn đến các vấn đề sức khỏe nghiêm trọng."},{"en":"The charity works to improve living conditions in slums.","vi":"Tổ chức từ thiện nỗ lực cải thiện điều kiện sống trong các khu ổ chuột."},{"en":"Better living conditions have raised average life expectancy.","vi":"Điều kiện sống tốt hơn đã nâng cao tuổi thọ trung bình."}]','[]',NULL,'/ˈlɪvɪŋ kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4555,'colloc-9-01',65,'living organism','sinh vật sống','adj + n','[{"en":"Every living organism requires energy to survive and grow.","vi":"Mọi sinh vật sống đều cần năng lượng để tồn tại và phát triển."},{"en":"Bacteria are the smallest living organism visible under a microscope.","vi":"Vi khuẩn là sinh vật sống nhỏ nhất có thể thấy dưới kính hiển vi."},{"en":"Pollution threatens nearly every living organism in the river.","vi":"Ô nhiễm đe dọa gần như mọi sinh vật sống trong dòng sông."}]','[]',NULL,'/ˈlɪvɪŋ ˈɔːrɡənɪzəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4556,'colloc-9-01',66,'living standard','mức sống','adj + n','[{"en":"Rising wages have improved the living standard of many families.","vi":"Lương tăng đã cải thiện mức sống của nhiều gia đình."},{"en":"Economists use income to measure a country''s living standard.","vi":"Các nhà kinh tế dùng thu nhập để đo lường mức sống của một quốc gia."},{"en":"A higher living standard often follows steady economic growth.","vi":"Mức sống cao hơn thường đi kèm với tăng trưởng kinh tế ổn định."}]','[]',NULL,'/ˈlɪvɪŋ ˈstændərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4557,'colloc-9-01',67,'local area','khu vực địa phương','adj + n','[{"en":"The survey gathered opinions from residents in the local area.","vi":"Cuộc khảo sát thu thập ý kiến từ cư dân trong khu vực địa phương."},{"en":"New shops have brought more jobs to the local area.","vi":"Các cửa hàng mới đã mang lại nhiều việc làm hơn cho khu vực địa phương."},{"en":"Volunteers cleaned several parks across the local area.","vi":"Các tình nguyện viên dọn dẹp vài công viên trong khu vực địa phương."}]','[]',NULL,'/ˈloʊkəl ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4558,'colloc-9-01',68,'local authority','chính quyền địa phương','adj + n','[{"en":"The local authority is responsible for collecting household waste.","vi":"Chính quyền địa phương chịu trách nhiệm thu gom rác thải sinh hoạt."},{"en":"Residents petitioned the local authority for safer roads.","vi":"Cư dân kiến nghị chính quyền địa phương về những con đường an toàn hơn."},{"en":"Funding from the local authority supports the public library.","vi":"Kinh phí từ chính quyền địa phương hỗ trợ thư viện công cộng."}]','[]',NULL,'/ˈloʊkəl əˈθɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4559,'colloc-9-01',69,'local circumstances','hoàn cảnh địa phương','adj + n','[{"en":"Policies must be adapted to suit local circumstances.","vi":"Các chính sách phải được điều chỉnh để phù hợp với hoàn cảnh địa phương."},{"en":"What works in one city may fail under different local circumstances.","vi":"Điều hiệu quả ở một thành phố có thể thất bại trong hoàn cảnh địa phương khác."},{"en":"The plan ignored important local circumstances and quickly failed.","vi":"Kế hoạch bỏ qua những hoàn cảnh địa phương quan trọng và nhanh chóng thất bại."}]','[]',NULL,'/ˈloʊkəl ˈsɜːrkəmstænsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4560,'colloc-9-01',70,'local community','cộng đồng địa phương','adj + n','[{"en":"The factory provides many jobs for the local community.","vi":"Nhà máy cung cấp nhiều việc làm cho cộng đồng địa phương."},{"en":"Schools play a central role in the local community.","vi":"Trường học đóng vai trò trung tâm trong cộng đồng địa phương."},{"en":"The festival brings the whole local community together.","vi":"Lễ hội gắn kết cả cộng đồng địa phương lại với nhau."}]','[]',NULL,'/ˈloʊkəl kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4561,'colloc-9-01',71,'local culture','văn hóa địa phương','adj + n','[{"en":"Tourists are encouraged to respect the local culture.","vi":"Du khách được khuyến khích tôn trọng văn hóa địa phương."},{"en":"The museum preserves objects that reflect the local culture.","vi":"Bảo tàng lưu giữ các hiện vật phản ánh văn hóa địa phương."},{"en":"Globalisation sometimes threatens unique forms of local culture.","vi":"Toàn cầu hóa đôi khi đe dọa những hình thức độc đáo của văn hóa địa phương."}]','[]',NULL,'/ˈloʊkəl ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4562,'colloc-9-01',72,'local economy','nền kinh tế địa phương','adj + n','[{"en":"Tourism contributes significantly to the local economy each summer.","vi":"Du lịch đóng góp đáng kể cho nền kinh tế địa phương mỗi mùa hè."},{"en":"Closing the mine would damage the entire local economy.","vi":"Việc đóng cửa mỏ sẽ làm tổn hại cả nền kinh tế địa phương."},{"en":"Small businesses are the backbone of the local economy.","vi":"Các doanh nghiệp nhỏ là xương sống của nền kinh tế địa phương."}]','[]',NULL,'/ˈloʊkəl ɪˈkɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4563,'colloc-9-01',73,'local government','chính quyền địa phương','adj + n','[{"en":"Local government manages schools, roads, and public parks.","vi":"Chính quyền địa phương quản lý trường học, đường sá và công viên công cộng."},{"en":"Citizens elect representatives to their local government every four years.","vi":"Người dân bầu đại biểu vào chính quyền địa phương bốn năm một lần."},{"en":"Budget cuts have reduced services provided by local government.","vi":"Việc cắt giảm ngân sách đã thu hẹp dịch vụ do chính quyền địa phương cung cấp."}]','[]',NULL,'/ˈloʊkəl ˈɡʌvərnmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4564,'colloc-9-01',74,'logical approach','cách tiếp cận hợp lý','adj + n','[{"en":"A logical approach to the problem saves a lot of time.","vi":"Một cách tiếp cận hợp lý cho vấn đề tiết kiệm rất nhiều thời gian."},{"en":"The teacher praised her logical approach to the essay.","vi":"Giáo viên khen ngợi cách tiếp cận hợp lý của cô với bài luận."},{"en":"Engineers favour a logical approach over guesswork.","vi":"Các kỹ sư ưa thích cách tiếp cận hợp lý hơn là phỏng đoán."}]','[]',NULL,'/ˈlɑːdʒɪkəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4565,'colloc-9-01',75,'logical argument','lập luận hợp lý','adj + n','[{"en":"She built a logical argument supported by clear evidence.","vi":"Cô xây dựng một lập luận hợp lý được hỗ trợ bởi bằng chứng rõ ràng."},{"en":"A logical argument should avoid contradictions and gaps.","vi":"Một lập luận hợp lý nên tránh mâu thuẫn và những lỗ hổng."},{"en":"The debate was won through a calm, logical argument.","vi":"Cuộc tranh luận được thắng nhờ một lập luận bình tĩnh và hợp lý."}]','[]',NULL,'/ˈlɑːdʒɪkəl ˈɑːrɡjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4566,'colloc-9-01',76,'logical conclusion','kết luận hợp lý','adj + n','[{"en":"The evidence leads to one clear, logical conclusion.","vi":"Bằng chứng dẫn đến một kết luận hợp lý rõ ràng."},{"en":"Taking the idea to its logical conclusion reveals a flaw.","vi":"Đưa ý tưởng đến kết luận hợp lý của nó cho thấy một sai sót."},{"en":"Readers can draw their own logical conclusion from the data.","vi":"Người đọc có thể tự rút ra kết luận hợp lý từ dữ liệu."}]','[]',NULL,'/ˈlɑːdʒɪkəl kənˈkluːʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4567,'colloc-9-01',77,'long duration','thời gian dài','adj + n','[{"en":"The experiment ran over a long duration to ensure accuracy.","vi":"Thí nghiệm chạy trong một thời gian dài để đảm bảo độ chính xác."},{"en":"Treatments of long duration often raise the cost of care.","vi":"Các liệu trình kéo dài thời gian dài thường làm tăng chi phí chăm sóc."},{"en":"The storm''s long duration caused widespread flooding.","vi":"Thời gian dài của cơn bão đã gây ra lũ lụt trên diện rộng."}]','[]',NULL,'/ˈlɔːŋ duˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4568,'colloc-9-01',78,'long established','đã được thiết lập từ lâu','adv + adj','[{"en":"The company follows a long established tradition of quality.","vi":"Công ty tuân theo một truyền thống chất lượng đã được thiết lập từ lâu."},{"en":"These long established methods are still taught today.","vi":"Những phương pháp đã được thiết lập từ lâu này vẫn được dạy ngày nay."},{"en":"She challenged a long established belief in the field.","vi":"Cô thách thức một niềm tin đã được thiết lập từ lâu trong lĩnh vực này."}]','[]',NULL,'/ˈlɔːŋ ɪˈstæblɪʃt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4569,'colloc-9-01',79,'longitudinal study','nghiên cứu theo chiều dọc','adj + n','[{"en":"A longitudinal study followed the same children for ten years.","vi":"Một nghiên cứu theo chiều dọc theo dõi cùng những đứa trẻ trong mười năm."},{"en":"The longitudinal study revealed gradual changes in health.","vi":"Nghiên cứu theo chiều dọc cho thấy những thay đổi dần dần về sức khỏe."},{"en":"Funding a longitudinal study requires long-term commitment.","vi":"Tài trợ cho một nghiên cứu theo chiều dọc đòi hỏi cam kết lâu dài."}]','[]',NULL,'/ˌlɔːndʒɪˈtuːdɪnəl ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4570,'colloc-9-01',80,'low income','thu nhập thấp','adj + n','[{"en":"Families on a low income struggle to afford housing.","vi":"Các gia đình có thu nhập thấp gặp khó khăn trong việc trang trải nhà ở."},{"en":"The program offers grants to low income students.","vi":"Chương trình cấp học bổng cho sinh viên có thu nhập thấp."},{"en":"Low income often limits access to healthy food.","vi":"Thu nhập thấp thường hạn chế khả năng tiếp cận thực phẩm lành mạnh."}]','[]',NULL,'/ˈloʊ ˈɪnkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4571,'colloc-9-01',81,'low intensity','cường độ thấp','adj + n','[{"en":"Low intensity exercise is recommended for older patients.","vi":"Bài tập cường độ thấp được khuyến nghị cho bệnh nhân lớn tuổi."},{"en":"The conflict remained at low intensity for several years.","vi":"Cuộc xung đột duy trì ở cường độ thấp trong vài năm."},{"en":"Plants near the wall received only low intensity light.","vi":"Cây cối gần tường chỉ nhận được ánh sáng cường độ thấp."}]','[]',NULL,'/ˈloʊ ɪnˈtensəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4572,'colloc-9-01',82,'low level','mức độ thấp','adj + n','[{"en":"Tests detected a low level of pollution in the water.","vi":"Các xét nghiệm phát hiện mức độ ô nhiễm thấp trong nước."},{"en":"Workers reported a low level of job satisfaction.","vi":"Người lao động báo cáo mức độ hài lòng với công việc thấp."},{"en":"A low level of rainfall harmed the year''s harvest.","vi":"Mức độ lượng mưa thấp đã làm hỏng vụ thu hoạch năm đó."}]','[]',NULL,'/ˈloʊ ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4573,'colloc-9-01',83,'low percentage','tỷ lệ phần trăm thấp','adj + n','[{"en":"Only a low percentage of applicants passed the final exam.","vi":"Chỉ một tỷ lệ phần trăm thấp ứng viên vượt qua kỳ thi cuối."},{"en":"A low percentage of voters turned out for the election.","vi":"Một tỷ lệ phần trăm thấp cử tri đi bỏ phiếu trong cuộc bầu cử."},{"en":"The drug helped only a low percentage of patients.","vi":"Loại thuốc chỉ giúp được một tỷ lệ phần trăm thấp bệnh nhân."}]','[]',NULL,'/ˈloʊ pərˈsentɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4574,'colloc-9-01',84,'low priority','mức ưu tiên thấp','adj + n','[{"en":"Road repairs were given low priority in this year''s budget.","vi":"Việc sửa đường được dành mức ưu tiên thấp trong ngân sách năm nay."},{"en":"The task seemed important but was actually low priority.","vi":"Nhiệm vụ có vẻ quan trọng nhưng thực ra là mức ưu tiên thấp."},{"en":"Staff training became a low priority during the crisis.","vi":"Đào tạo nhân viên trở thành mức ưu tiên thấp trong khủng hoảng."}]','[]',NULL,'/ˈloʊ praɪˈɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4575,'colloc-9-01',85,'low probability','xác suất thấp','adj + n','[{"en":"There is a low probability of rain this afternoon.","vi":"Có xác suất thấp xảy ra mưa vào chiều nay."},{"en":"The model assigns a low probability to that outcome.","vi":"Mô hình gán xác suất thấp cho kết quả đó."},{"en":"Despite the low probability, the team prepared for failure.","vi":"Dù xác suất thấp, đội vẫn chuẩn bị cho thất bại."}]','[]',NULL,'/ˈloʊ ˌprɑːbəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4576,'colloc-9-01',86,'low profile','sự kín đáo, ít phô trương','adj + n','[{"en":"The politician kept a low profile during the scandal.","vi":"Chính trị gia giữ thái độ kín đáo trong suốt vụ bê bối."},{"en":"After the controversy, the company maintained a low profile.","vi":"Sau cuộc tranh cãi, công ty duy trì sự kín đáo."},{"en":"She prefers a low profile and avoids public attention.","vi":"Cô thích sự kín đáo và tránh sự chú ý của công chúng."}]','[]',NULL,'/ˈloʊ ˈproʊfaɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4577,'colloc-9-01',87,'low quality','chất lượng thấp','adj + n','[{"en":"Customers complained about the low quality of the materials.","vi":"Khách hàng phàn nàn về chất lượng thấp của vật liệu."},{"en":"Low quality data can ruin an otherwise good study.","vi":"Dữ liệu chất lượng thấp có thể phá hỏng một nghiên cứu vốn tốt."},{"en":"Cheap goods are often of disappointingly low quality.","vi":"Hàng giá rẻ thường có chất lượng thấp đáng thất vọng."}]','[]',NULL,'/ˈloʊ ˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4578,'colloc-9-01',88,'low status','địa vị thấp','adj + n','[{"en":"Manual jobs were once seen as having low status.","vi":"Công việc chân tay từng bị xem là có địa vị thấp."},{"en":"The reform aimed to help workers of low status.","vi":"Cuộc cải cách nhằm giúp đỡ những người lao động có địa vị thấp."},{"en":"Low status within the group limited her influence.","vi":"Địa vị thấp trong nhóm đã hạn chế ảnh hưởng của cô."}]','[]',NULL,'/ˈloʊ ˈstætəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4579,'colloc-9-01',89,'low turnover','tỷ lệ thay đổi nhân sự thấp','adj + n','[{"en":"The firm enjoys low turnover thanks to fair wages.","vi":"Công ty có tỷ lệ thay đổi nhân sự thấp nhờ mức lương công bằng."},{"en":"Low turnover suggests employees are happy in their roles.","vi":"Tỷ lệ thay đổi nhân sự thấp cho thấy nhân viên hài lòng với vai trò của mình."},{"en":"Good management is linked to low turnover among staff.","vi":"Quản lý tốt gắn liền với tỷ lệ thay đổi nhân sự thấp."}]','[]',NULL,'/ˈloʊ ˈtɜːrnoʊvər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4580,'colloc-9-01',90,'low unemployment','tỷ lệ thất nghiệp thấp','adj + n','[{"en":"Low unemployment usually signals a healthy economy.","vi":"Tỷ lệ thất nghiệp thấp thường báo hiệu một nền kinh tế lành mạnh."},{"en":"The region enjoyed low unemployment for several years.","vi":"Khu vực này có tỷ lệ thất nghiệp thấp trong nhiều năm."},{"en":"Low unemployment can push wages gradually higher.","vi":"Tỷ lệ thất nghiệp thấp có thể đẩy lương tăng dần lên."}]','[]',NULL,'/ˈloʊ ˌʌnɪmˈplɔɪmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4581,'colloc-9-01',91,'low/er frequency','tần suất thấp/thấp hơn','adj + n','[{"en":"The disease occurs at a lower frequency in rural areas.","vi":"Căn bệnh xảy ra với tần suất thấp hơn ở vùng nông thôn."},{"en":"Lower frequency sounds travel farther than high ones.","vi":"Âm thanh tần suất thấp hơn truyền đi xa hơn âm thanh cao."},{"en":"Researchers noted a lower frequency of errors after training.","vi":"Các nhà nghiên cứu ghi nhận tần suất lỗi thấp hơn sau khi đào tạo."}]','[]',NULL,'/ˈloʊər ˈfriːkwənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4582,'colloc-9-01',92,'lower class','tầng lớp hạ lưu','adj + n','[{"en":"The novel portrays the hardships of the lower class.","vi":"Cuốn tiểu thuyết khắc họa những khó khăn của tầng lớp hạ lưu."},{"en":"Education was once denied to the lower class.","vi":"Giáo dục từng bị từ chối với tầng lớp hạ lưu."},{"en":"Historians studied how the lower class lived during that era.","vi":"Các nhà sử học nghiên cứu cách tầng lớp hạ lưu sống trong thời đại đó."}]','[]',NULL,'/ˈloʊər ˈklæs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4583,'colloc-9-01',93,'main area','lĩnh vực chính','adj + n','[{"en":"The report focuses on three main areas of concern.","vi":"Báo cáo tập trung vào ba lĩnh vực chính đáng quan tâm."},{"en":"Her main area of research is renewable energy.","vi":"Lĩnh vực nghiên cứu chính của cô là năng lượng tái tạo."},{"en":"The main area of disagreement concerned the budget.","vi":"Lĩnh vực bất đồng chính liên quan đến ngân sách."}]','[]',NULL,'/ˈmeɪn ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4584,'colloc-9-01',94,'main argument','luận điểm chính','adj + n','[{"en":"The main argument of the essay appears in the introduction.","vi":"Luận điểm chính của bài luận xuất hiện ở phần mở đầu."},{"en":"Her main argument rests on solid historical evidence.","vi":"Luận điểm chính của cô dựa trên bằng chứng lịch sử vững chắc."},{"en":"Critics quickly attacked the writer''s main argument.","vi":"Các nhà phê bình nhanh chóng công kích luận điểm chính của tác giả."}]','[]',NULL,'/ˈmeɪn ˈɑːrɡjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4585,'colloc-9-01',95,'main category','loại chính','adj + n','[{"en":"The data fall into three main categories for analysis.","vi":"Dữ liệu được chia thành ba loại chính để phân tích."},{"en":"Each main category contains several smaller subgroups.","vi":"Mỗi loại chính chứa một số nhóm nhỏ hơn."},{"en":"Books here are sorted by their main category first.","vi":"Sách ở đây được sắp xếp theo loại chính trước tiên."}]','[]',NULL,'/ˈmeɪn ˈkætəɡɔːri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4586,'colloc-9-01',96,'main characteristics','những đặc điểm chính','adj + n','[{"en":"The chapter lists the main characteristics of each species.","vi":"Chương này liệt kê những đặc điểm chính của mỗi loài."},{"en":"Students must describe the main characteristics of the period.","vi":"Sinh viên phải mô tả những đặc điểm chính của thời kỳ này."},{"en":"These main characteristics distinguish one group from another.","vi":"Những đặc điểm chính này phân biệt nhóm này với nhóm khác."}]','[]',NULL,'/ˈmeɪn ˌkærəktəˈrɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4587,'colloc-9-01',97,'main component','thành phần chính','adj + n','[{"en":"Water is the main component of the human body.","vi":"Nước là thành phần chính của cơ thể con người."},{"en":"The engine is the main component of the entire system.","vi":"Động cơ là thành phần chính của toàn bộ hệ thống."},{"en":"Reading is the main component of the language course.","vi":"Đọc là thành phần chính của khóa học ngôn ngữ."}]','[]',NULL,'/ˈmeɪn kəmˈpoʊnənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4588,'colloc-9-01',98,'main element','yếu tố chính','adj + n','[{"en":"Trust is the main element of any successful partnership.","vi":"Sự tin tưởng là yếu tố chính của mọi quan hệ đối tác thành công."},{"en":"The plot is the main element that drives the story.","vi":"Cốt truyện là yếu tố chính thúc đẩy câu chuyện."},{"en":"Practice remains the main element of mastering a skill.","vi":"Luyện tập vẫn là yếu tố chính để thành thạo một kỹ năng."}]','[]',NULL,'/ˈmeɪn ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4589,'colloc-9-01',99,'main factor','yếu tố chính','adj + n','[{"en":"Cost was the main factor behind their final decision.","vi":"Chi phí là yếu tố chính đằng sau quyết định cuối cùng của họ."},{"en":"Climate is the main factor affecting crop yields here.","vi":"Khí hậu là yếu tố chính ảnh hưởng đến năng suất cây trồng ở đây."},{"en":"Motivation is the main factor in long-term learning.","vi":"Động lực là yếu tố chính trong việc học lâu dài."}]','[]',NULL,'/ˈmeɪn ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4590,'colloc-9-01',100,'main feature','đặc điểm chính','adj + n','[{"en":"The main feature of the app is its simple design.","vi":"Đặc điểm chính của ứng dụng là thiết kế đơn giản của nó."},{"en":"A large garden is the house''s main feature.","vi":"Một khu vườn rộng là đặc điểm chính của ngôi nhà."},{"en":"The main feature of the region is its volcanic soil.","vi":"Đặc điểm chính của vùng này là đất núi lửa của nó."}]','[]',NULL,'/ˈmeɪn ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4591,'colloc-9-01',101,'main findings','những phát hiện chính','adj + n','[{"en":"The summary presents the main findings of the study.","vi":"Phần tóm tắt trình bày những phát hiện chính của nghiên cứu."},{"en":"Her main findings challenged earlier assumptions in the field.","vi":"Những phát hiện chính của cô thách thức các giả định trước đó trong lĩnh vực này."},{"en":"The main findings were published in a leading journal.","vi":"Những phát hiện chính được công bố trên một tạp chí hàng đầu."}]','[]',NULL,'/ˈmeɪn ˈfaɪndɪŋz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4592,'colloc-9-01',102,'main focus','trọng tâm chính','adj + n','[{"en":"The main focus of the lecture was climate policy.","vi":"Trọng tâm chính của bài giảng là chính sách khí hậu."},{"en":"Customer safety is the company''s main focus this year.","vi":"An toàn của khách hàng là trọng tâm chính của công ty năm nay."},{"en":"Her main focus shifted from theory to practice.","vi":"Trọng tâm chính của cô chuyển từ lý thuyết sang thực hành."}]','[]',NULL,'/ˈmeɪn ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4593,'colloc-9-01',103,'main function','chức năng chính','adj + n','[{"en":"The heart''s main function is to pump blood around the body.","vi":"Chức năng chính của tim là bơm máu khắp cơ thể."},{"en":"The committee''s main function is to review new proposals.","vi":"Chức năng chính của ủy ban là xem xét các đề xuất mới."},{"en":"A dictionary''s main function is to define words clearly.","vi":"Chức năng chính của từ điển là định nghĩa từ ngữ rõ ràng."}]','[]',NULL,'/ˈmeɪn ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4594,'colloc-9-01',104,'main issue','vấn đề chính','adj + n','[{"en":"The main issue discussed was rising housing costs.","vi":"Vấn đề chính được thảo luận là chi phí nhà ở tăng cao."},{"en":"We must address the main issue before moving forward.","vi":"Chúng ta phải giải quyết vấn đề chính trước khi tiến tới."},{"en":"The main issue for many students is a lack of time.","vi":"Vấn đề chính của nhiều sinh viên là thiếu thời gian."}]','[]',NULL,'/ˈmeɪn ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4595,'colloc-9-01',105,'main principle','nguyên tắc chính','adj + n','[{"en":"Fairness is the main principle behind the new rules.","vi":"Công bằng là nguyên tắc chính đằng sau các quy tắc mới."},{"en":"The main principle of the theory is surprisingly simple.","vi":"Nguyên tắc chính của lý thuyết này đơn giản đến bất ngờ."},{"en":"Equality remains the main principle of the organisation.","vi":"Bình đẳng vẫn là nguyên tắc chính của tổ chức."}]','[]',NULL,'/ˈmeɪn ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4596,'colloc-9-01',106,'main source','nguồn chính','adj + n','[{"en":"Tourism is the main source of income for the island.","vi":"Du lịch là nguồn thu nhập chính của hòn đảo."},{"en":"The river is the main source of water for the city.","vi":"Con sông là nguồn nước chính cho thành phố."},{"en":"Books were once the main source of reliable knowledge.","vi":"Sách từng là nguồn kiến thức đáng tin cậy chính."}]','[]',NULL,'/ˈmeɪn ˈsɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4597,'colloc-9-01',107,'main task','nhiệm vụ chính','adj + n','[{"en":"The main task of the editor is to check accuracy.","vi":"Nhiệm vụ chính của biên tập viên là kiểm tra độ chính xác."},{"en":"Their main task was to gather data from the field.","vi":"Nhiệm vụ chính của họ là thu thập dữ liệu từ thực địa."},{"en":"Completing the main task took the team several weeks.","vi":"Hoàn thành nhiệm vụ chính khiến cả đội mất vài tuần."}]','[]',NULL,'/ˈmeɪn ˈtæsk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4598,'colloc-9-01',108,'main theme','chủ đề chính','adj + n','[{"en":"Loss is the main theme running through the entire novel.","vi":"Mất mát là chủ đề chính xuyên suốt cả cuốn tiểu thuyết."},{"en":"The conference''s main theme was sustainable development.","vi":"Chủ đề chính của hội nghị là phát triển bền vững."},{"en":"Identity emerges as the main theme of her poetry.","vi":"Bản sắc nổi lên như chủ đề chính trong thơ của cô."}]','[]',NULL,'/ˈmeɪn ˈθiːm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4599,'colloc-9-01',109,'mainly concerned with','chủ yếu liên quan đến','adv + vpp','[{"en":"The study is mainly concerned with the effects of sleep.","vi":"Nghiên cứu chủ yếu liên quan đến tác động của giấc ngủ."},{"en":"This chapter is mainly concerned with economic theory.","vi":"Chương này chủ yếu liên quan đến lý thuyết kinh tế."},{"en":"Her work is mainly concerned with social inequality.","vi":"Công việc của cô chủ yếu liên quan đến bất bình đẳng xã hội."}]','[]',NULL,'/ˈmeɪnli kənˈsɜːrnd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4600,'colloc-9-01',110,'maintain contact','duy trì liên lạc','v + n','[{"en":"Researchers maintain contact with participants throughout the project.","vi":"Các nhà nghiên cứu duy trì liên lạc với người tham gia suốt dự án."},{"en":"It is hard to maintain contact with old school friends.","vi":"Thật khó để duy trì liên lạc với bạn học cũ."},{"en":"The two offices maintain contact through weekly video calls.","vi":"Hai văn phòng duy trì liên lạc qua các cuộc gọi video hàng tuần."}]','[]',NULL,'/meɪnˈteɪn ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4601,'colloc-9-01',111,'major advantage','lợi thế lớn','adj + n','[{"en":"A major advantage of the method is its low cost.","vi":"Một lợi thế lớn của phương pháp này là chi phí thấp."},{"en":"Speaking two languages is a major advantage when travelling.","vi":"Nói được hai ngôn ngữ là một lợi thế lớn khi đi du lịch."},{"en":"Their early start gave them a major advantage.","vi":"Việc khởi đầu sớm mang lại cho họ một lợi thế lớn."}]','[]',NULL,'/ˈmeɪdʒər ədˈvæntɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4602,'colloc-9-01',112,'major area','lĩnh vực lớn','adj + n','[{"en":"Healthcare is a major area of government spending.","vi":"Y tế là một lĩnh vực lớn trong chi tiêu của chính phủ."},{"en":"Robotics has become a major area of modern research.","vi":"Robot học đã trở thành một lĩnh vực lớn của nghiên cứu hiện đại."},{"en":"The reform targeted a major area of public concern.","vi":"Cuộc cải cách nhắm vào một lĩnh vực lớn mà công chúng quan tâm."}]','[]',NULL,'/ˈmeɪdʒər ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4603,'colloc-9-01',113,'major cause','nguyên nhân chính','adj + n','[{"en":"Smoking is a major cause of lung disease worldwide.","vi":"Hút thuốc là nguyên nhân chính gây bệnh phổi trên toàn thế giới."},{"en":"Deforestation is a major cause of habitat loss.","vi":"Phá rừng là nguyên nhân chính gây mất môi trường sống."},{"en":"Stress is a major cause of poor sleep in adults.","vi":"Căng thẳng là nguyên nhân chính gây mất ngủ ở người lớn."}]','[]',NULL,'/ˈmeɪdʒər ˈkɔːz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4604,'colloc-9-01',114,'major challenge','thách thức lớn','adj + n','[{"en":"Climate change is a major challenge for future generations.","vi":"Biến đổi khí hậu là một thách thức lớn cho các thế hệ tương lai."},{"en":"Funding remained the major challenge facing the project.","vi":"Tài chính vẫn là thách thức lớn mà dự án phải đối mặt."},{"en":"Learning a new language poses a major challenge.","vi":"Học một ngôn ngữ mới đặt ra một thách thức lớn."}]','[]',NULL,'/ˈmeɪdʒər ˈtʃælɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4605,'colloc-9-01',115,'major change','thay đổi lớn','adj + n','[{"en":"The reform brought a major change to the tax system.","vi":"Cuộc cải cách mang lại một thay đổi lớn cho hệ thống thuế."},{"en":"Technology has caused a major change in how we work.","vi":"Công nghệ đã gây ra một thay đổi lớn trong cách chúng ta làm việc."},{"en":"Adapting to a major change takes time and patience.","vi":"Thích nghi với một thay đổi lớn cần thời gian và kiên nhẫn."}]','[]',NULL,'/ˈmeɪdʒər ˈtʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4606,'colloc-9-01',116,'major component','thành phần chính','adj + n','[{"en":"Carbon is a major component of all living things.","vi":"Cacbon là một thành phần chính của mọi sinh vật sống."},{"en":"Tuition is a major component of the total study cost.","vi":"Học phí là một thành phần chính của tổng chi phí học tập."},{"en":"Trust is a major component of effective teamwork.","vi":"Sự tin tưởng là một thành phần chính của làm việc nhóm hiệu quả."}]','[]',NULL,'/ˈmeɪdʒər kəmˈpoʊnənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4607,'colloc-9-01',117,'major concern','mối lo ngại lớn','adj + n','[{"en":"Air pollution is a major concern in large cities.","vi":"Ô nhiễm không khí là một mối lo ngại lớn ở các thành phố lớn."},{"en":"Safety was the parents'' major concern about the trip.","vi":"An toàn là mối lo ngại lớn của phụ huynh về chuyến đi."},{"en":"Rising costs are a major concern for small businesses.","vi":"Chi phí tăng là một mối lo ngại lớn đối với doanh nghiệp nhỏ."}]','[]',NULL,'/ˈmeɪdʒər kənˈsɜːrn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4608,'colloc-9-01',118,'major contribution','đóng góp lớn','adj + n','[{"en":"Her research made a major contribution to modern medicine.","vi":"Nghiên cứu của cô đã có đóng góp lớn cho y học hiện đại."},{"en":"Volunteers made a major contribution to the festival''s success.","vi":"Các tình nguyện viên đã đóng góp lớn vào thành công của lễ hội."},{"en":"The scientist''s major contribution was recognised with an award.","vi":"Đóng góp lớn của nhà khoa học được công nhận bằng một giải thưởng."}]','[]',NULL,'/ˈmeɪdʒər ˌkɑːntrɪˈbjuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4609,'colloc-9-01',119,'major decision','quyết định quan trọng','adj + n','[{"en":"Choosing a career is a major decision for young people.","vi":"Chọn nghề nghiệp là một quyết định quan trọng đối với người trẻ."},{"en":"The board postponed the major decision until next month.","vi":"Hội đồng đã hoãn quyết định quan trọng đến tháng sau."},{"en":"They consulted experts before making such a major decision.","vi":"Họ tham khảo ý kiến chuyên gia trước khi đưa ra quyết định quan trọng như vậy."}]','[]',NULL,'/ˈmeɪdʒər dɪˈsɪʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4610,'colloc-9-01',120,'major difference','sự khác biệt lớn','adj + n','[{"en":"There is a major difference between the two theories.","vi":"Có một sự khác biệt lớn giữa hai lý thuyết."},{"en":"Climate is the major difference between the two regions.","vi":"Khí hậu là sự khác biệt lớn giữa hai vùng."},{"en":"Experience makes a major difference in this kind of work.","vi":"Kinh nghiệm tạo nên sự khác biệt lớn trong loại công việc này."}]','[]',NULL,'/ˈmeɪdʒər ˈdɪfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4611,'colloc-9-01',121,'major factor','yếu tố chính','adj + n','[{"en":"Cost was a major factor in choosing this supplier.","vi":"Chi phí là một yếu tố chính trong việc chọn nhà cung cấp này."},{"en":"Sleep is a major factor affecting students'' overall performance.","vi":"Giấc ngủ là một yếu tố chính ảnh hưởng đến thành tích chung của sinh viên."},{"en":"The study identified pollution as a major factor in disease.","vi":"Nghiên cứu xác định ô nhiễm là một yếu tố chính gây bệnh."}]','[]',NULL,'/ˈmeɪdʒər ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4612,'colloc-9-01',122,'major feature','đặc điểm chính','adj + n','[{"en":"Flexibility is a major feature of this online course.","vi":"Tính linh hoạt là một đặc điểm chính của khóa học trực tuyến này."},{"en":"The report highlights several major features of the new system.","vi":"Báo cáo nêu bật một số đặc điểm chính của hệ thống mới."},{"en":"A major feature of the design is its low energy use.","vi":"Một đặc điểm chính của thiết kế là mức tiêu thụ năng lượng thấp."}]','[]',NULL,'/ˈmeɪdʒər ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4613,'colloc-9-01',123,'major focus','trọng tâm chính','adj + n','[{"en":"Customer satisfaction is a major focus of the company.","vi":"Sự hài lòng của khách hàng là trọng tâm chính của công ty."},{"en":"Reducing waste became a major focus of the research.","vi":"Giảm thiểu rác thải trở thành trọng tâm chính của nghiên cứu."},{"en":"A major focus of the lecture was climate adaptation.","vi":"Một trọng tâm chính của bài giảng là thích ứng với khí hậu."}]','[]',NULL,'/ˈmeɪdʒər ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4614,'colloc-9-01',124,'major impact','tác động lớn','adj + n','[{"en":"The new policy had a major impact on small businesses.","vi":"Chính sách mới đã có tác động lớn đến các doanh nghiệp nhỏ."},{"en":"Technology has a major impact on how we communicate.","vi":"Công nghệ có tác động lớn đến cách chúng ta giao tiếp."},{"en":"Early education can make a major impact on later success.","vi":"Giáo dục sớm có thể tạo ra tác động lớn đến thành công về sau."}]','[]',NULL,'/ˈmeɪdʒər ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4615,'colloc-9-01',125,'major implications','hệ quả lớn','adj + n','[{"en":"The findings have major implications for public health policy.","vi":"Các phát hiện có hệ quả lớn đối với chính sách y tế công cộng."},{"en":"This decision carries major implications for future trade deals.","vi":"Quyết định này mang theo những hệ quả lớn cho các thỏa thuận thương mại tương lai."},{"en":"Rising sea levels have major implications for coastal cities.","vi":"Mực nước biển dâng có hệ quả lớn đối với các thành phố ven biển."}]','[]',NULL,'/ˈmeɪdʒər ˌɪmplɪˈkeɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4616,'colloc-9-01',126,'major influence','ảnh hưởng lớn','adj + n','[{"en":"Her mentor had a major influence on her career choices.","vi":"Người cố vấn của cô đã có ảnh hưởng lớn đến các lựa chọn nghề nghiệp."},{"en":"Culture exerts a major influence on consumer behavior.","vi":"Văn hóa tạo ra ảnh hưởng lớn đến hành vi của người tiêu dùng."},{"en":"Greek philosophy was a major influence on Western thought.","vi":"Triết học Hy Lạp là một ảnh hưởng lớn đối với tư tưởng phương Tây."}]','[]',NULL,'/ˈmeɪdʒər ˈɪnfluəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4617,'colloc-9-01',127,'major issue','vấn đề lớn','adj + n','[{"en":"Traffic congestion remains a major issue in the city.","vi":"Ùn tắc giao thông vẫn là một vấn đề lớn ở thành phố."},{"en":"Data privacy is a major issue for many users today.","vi":"Quyền riêng tư dữ liệu là một vấn đề lớn với nhiều người dùng ngày nay."},{"en":"The meeting addressed a major issue facing the department.","vi":"Cuộc họp đã giải quyết một vấn đề lớn mà phòng ban đang đối mặt."}]','[]',NULL,'/ˈmeɪdʒər ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4618,'colloc-9-01',128,'major part','phần lớn','adj + n','[{"en":"Reading plays a major part in language learning.","vi":"Việc đọc đóng một phần lớn trong việc học ngôn ngữ."},{"en":"Agriculture forms a major part of the local economy.","vi":"Nông nghiệp tạo nên một phần lớn của nền kinh tế địa phương."},{"en":"A major part of the budget goes to research and development.","vi":"Một phần lớn ngân sách dành cho nghiên cứu và phát triển."}]','[]',NULL,'/ˈmeɪdʒər ˈpɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4619,'colloc-9-01',129,'major problem','vấn đề nghiêm trọng','adj + n','[{"en":"Air pollution is a major problem in large cities.","vi":"Ô nhiễm không khí là một vấn đề nghiêm trọng ở các thành phố lớn."},{"en":"The team faced a major problem with the software.","vi":"Nhóm đã gặp một vấn đề nghiêm trọng với phần mềm."},{"en":"Unemployment became a major problem after the crisis.","vi":"Thất nghiệp trở thành một vấn đề nghiêm trọng sau khủng hoảng."}]','[]',NULL,'/ˈmeɪdʒər ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4620,'colloc-9-01',130,'major reason','lý do chính','adj + n','[{"en":"Cost is a major reason students choose online courses.","vi":"Chi phí là một lý do chính khiến sinh viên chọn học trực tuyến."},{"en":"A major reason for the delay was poor planning.","vi":"Một lý do chính cho sự chậm trễ là việc lập kế hoạch kém."},{"en":"Convenience is a major reason people shop online.","vi":"Sự tiện lợi là một lý do chính khiến người ta mua sắm trực tuyến."}]','[]',NULL,'/ˈmeɪdʒər ˈriːzən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4621,'colloc-9-01',131,'major role','vai trò lớn','adj + n','[{"en":"Teachers play a major role in shaping young minds.","vi":"Giáo viên đóng một vai trò lớn trong việc định hình tư duy trẻ."},{"en":"Diet plays a major role in maintaining good health.","vi":"Chế độ ăn đóng một vai trò lớn trong việc duy trì sức khỏe tốt."},{"en":"The internet has a major role in modern education.","vi":"Internet có một vai trò lớn trong giáo dục hiện đại."}]','[]',NULL,'/ˈmeɪdʒər ˈroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4622,'colloc-9-01',132,'major shift','sự thay đổi lớn','adj + n','[{"en":"There has been a major shift toward remote working.","vi":"Đã có một sự thay đổi lớn hướng tới làm việc từ xa."},{"en":"The data shows a major shift in consumer preferences.","vi":"Dữ liệu cho thấy một sự thay đổi lớn trong sở thích người tiêu dùng."},{"en":"A major shift in policy followed the election results.","vi":"Một sự thay đổi lớn về chính sách diễn ra sau kết quả bầu cử."}]','[]',NULL,'/ˈmeɪdʒər ˈʃɪft/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4623,'colloc-9-01',133,'major source','nguồn chính','adj + n','[{"en":"Tourism is a major source of income for the region.","vi":"Du lịch là một nguồn thu nhập chính cho khu vực này."},{"en":"Coal remains a major source of energy in many countries.","vi":"Than đá vẫn là một nguồn năng lượng chính ở nhiều nước."},{"en":"Stress is a major source of health problems among workers.","vi":"Căng thẳng là một nguồn chính gây vấn đề sức khỏe cho người lao động."}]','[]',NULL,'/ˈmeɪdʒər ˈsɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4624,'colloc-9-01',134,'major theme','chủ đề chính','adj + n','[{"en":"Identity is a major theme in the author''s novels.","vi":"Bản sắc là một chủ đề chính trong các tiểu thuyết của tác giả."},{"en":"Sustainability was a major theme at the conference.","vi":"Tính bền vững là một chủ đề chính tại hội nghị."},{"en":"A major theme of the essay is social inequality.","vi":"Một chủ đề chính của bài luận là bất bình đẳng xã hội."}]','[]',NULL,'/ˈmeɪdʒər ˈθiːm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4625,'colloc-9-01',135,'make adjustments','thực hiện điều chỉnh','v + n','[{"en":"We may need to make adjustments to the project plan.","vi":"Chúng ta có thể cần thực hiện điều chỉnh cho kế hoạch dự án."},{"en":"The teacher made adjustments to suit different learning styles.","vi":"Giáo viên đã thực hiện điều chỉnh để phù hợp các phong cách học khác nhau."},{"en":"Companies often make adjustments based on customer feedback.","vi":"Các công ty thường thực hiện điều chỉnh dựa trên phản hồi của khách hàng."}]','[]',NULL,'/ˈmeɪk əˈdʒʌstmənts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4626,'colloc-9-01',136,'make arrangements','sắp xếp, thu xếp','v + n','[{"en":"The office will make arrangements for your accommodation.","vi":"Văn phòng sẽ thu xếp chỗ ở cho bạn."},{"en":"We need to make arrangements for the guest speaker.","vi":"Chúng ta cần sắp xếp cho diễn giả khách mời."},{"en":"She made arrangements to travel before the deadline.","vi":"Cô ấy đã thu xếp để đi lại trước hạn chót."}]','[]',NULL,'/ˈmeɪk əˈreɪndʒmənts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4627,'colloc-9-01',137,'make available','cung cấp, làm cho sẵn có','v + adj','[{"en":"The library makes available many e-books to students.","vi":"Thư viện cung cấp nhiều sách điện tử cho sinh viên."},{"en":"The company made the report available to all employees.","vi":"Công ty đã làm cho báo cáo sẵn có với mọi nhân viên."},{"en":"We should make these resources available online for free.","vi":"Chúng ta nên cung cấp các tài nguyên này trực tuyến miễn phí."}]','[]',NULL,'/ˈmeɪk əˈveɪləbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4628,'colloc-9-01',138,'make aware','làm cho nhận thức được','v + adj','[{"en":"The campaign aims to make people aware of the risks.","vi":"Chiến dịch nhằm làm cho mọi người nhận thức được các rủi ro."},{"en":"Teachers should make students aware of plagiarism rules.","vi":"Giáo viên nên làm cho sinh viên nhận thức được các quy định đạo văn."},{"en":"The article made readers aware of the growing problem.","vi":"Bài báo đã làm cho độc giả nhận thức được vấn đề đang gia tăng."}]','[]',NULL,'/ˈmeɪk əˈwer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4629,'colloc-9-01',139,'make contact','liên hệ, tiếp xúc','v + n','[{"en":"Try to make contact with the supplier before Friday.","vi":"Hãy cố gắng liên hệ với nhà cung cấp trước thứ Sáu."},{"en":"Researchers made contact with several local communities.","vi":"Các nhà nghiên cứu đã tiếp xúc với một số cộng đồng địa phương."},{"en":"It can be hard to make contact with busy officials.","vi":"Có thể khó liên hệ với các quan chức bận rộn."}]','[]',NULL,'/ˈmeɪk ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4630,'colloc-9-01',140,'make a contribution','đóng góp','v + n','[{"en":"Every student can make a contribution to the discussion.","vi":"Mỗi sinh viên đều có thể đóng góp vào cuộc thảo luận."},{"en":"The scientist made a major contribution to the field.","vi":"Nhà khoa học đã có một đóng góp lớn cho lĩnh vực này."},{"en":"Volunteers make a valuable contribution to the community.","vi":"Các tình nguyện viên đóng góp quý giá cho cộng đồng."}]','[]',NULL,'/ˈmeɪk ə ˌkɑːntrɪˈbjuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4631,'colloc-9-01',141,'make explicit','làm cho rõ ràng','v + adj','[{"en":"The author should make the argument explicit in the introduction.","vi":"Tác giả nên làm cho lập luận rõ ràng trong phần mở đầu."},{"en":"Good instructions make every step explicit for the reader.","vi":"Hướng dẫn tốt làm cho mọi bước trở nên rõ ràng với người đọc."},{"en":"The policy makes explicit who is responsible for safety.","vi":"Chính sách làm rõ ràng ai chịu trách nhiệm về an toàn."}]','[]',NULL,'/ˈmeɪk ɪkˈsplɪsɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4632,'colloc-9-01',142,'make policy','hoạch định chính sách','v + n','[{"en":"Governments make policy based on careful research.","vi":"Chính phủ hoạch định chính sách dựa trên nghiên cứu kỹ lưỡng."},{"en":"Those who make policy must consider public opinion.","vi":"Những người hoạch định chính sách phải cân nhắc ý kiến công chúng."},{"en":"Experts help officials make policy on climate change.","vi":"Các chuyên gia giúp quan chức hoạch định chính sách về biến đổi khí hậu."}]','[]',NULL,'/ˈmeɪk ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4633,'colloc-9-01',143,'make provision','có sự chuẩn bị, dự liệu','v + n','[{"en":"The school should make provision for disabled students.","vi":"Nhà trường nên có sự chuẩn bị cho sinh viên khuyết tật."},{"en":"The plan makes provision for future population growth.","vi":"Kế hoạch dự liệu cho sự gia tăng dân số trong tương lai."},{"en":"Governments must make provision for emergency situations.","vi":"Chính phủ phải có sự chuẩn bị cho các tình huống khẩn cấp."}]','[]',NULL,'/ˈmeɪk prəˈvɪʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4634,'colloc-9-01',144,'make visible','làm cho thấy được','v + adj','[{"en":"The chart makes the trend visible at a glance.","vi":"Biểu đồ làm cho xu hướng thấy được chỉ trong nháy mắt."},{"en":"The study makes visible the hidden costs of pollution.","vi":"Nghiên cứu làm cho thấy được những chi phí ẩn của ô nhiễm."},{"en":"Good design makes important data visible to users.","vi":"Thiết kế tốt làm cho dữ liệu quan trọng thấy được với người dùng."}]','[]',NULL,'/ˈmeɪk ˈvɪzəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4635,'colloc-9-01',145,'make a comment','đưa ra nhận xét','v + n','[{"en":"The professor made a comment on my essay structure.","vi":"Giáo sư đã đưa ra nhận xét về cấu trúc bài luận của tôi."},{"en":"Feel free to make a comment during the presentation.","vi":"Bạn cứ thoải mái đưa ra nhận xét trong bài thuyết trình."},{"en":"She made a brief comment before leaving the meeting.","vi":"Cô ấy đã đưa ra một nhận xét ngắn trước khi rời cuộc họp."}]','[]',NULL,'/ˈmeɪk ə ˈkɑːment/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4636,'colloc-9-01',146,'make a distinction','phân biệt','v + n','[{"en":"It is important to make a distinction between cause and effect.","vi":"Điều quan trọng là phân biệt giữa nguyên nhân và hệ quả."},{"en":"The author makes a clear distinction between the two terms.","vi":"Tác giả phân biệt rõ ràng giữa hai thuật ngữ."},{"en":"We should make a distinction between fact and opinion.","vi":"Chúng ta nên phân biệt giữa sự thật và ý kiến."}]','[]',NULL,'/ˈmeɪk ə dɪˈstɪŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4637,'colloc-9-01',147,'make a judgement','đưa ra phán đoán, đánh giá','v + n','[{"en":"Try not to make a judgement before hearing all sides.","vi":"Cố đừng đưa ra phán đoán trước khi nghe hết các bên."},{"en":"The committee must make a judgement based on evidence.","vi":"Hội đồng phải đưa ra đánh giá dựa trên bằng chứng."},{"en":"Readers can make their own judgement about the findings.","vi":"Độc giả có thể tự đưa ra phán đoán về các phát hiện."}]','[]',NULL,'/ˈmeɪk ə ˈdʒʌdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4638,'colloc-9-01',148,'make a living','kiếm sống','v + n','[{"en":"Many artists struggle to make a living from their work.","vi":"Nhiều nghệ sĩ vất vả để kiếm sống bằng nghề của mình."},{"en":"Farmers in the region make a living from rice.","vi":"Nông dân trong vùng kiếm sống bằng nghề trồng lúa."},{"en":"It is hard to make a living as a freelance writer.","vi":"Thật khó để kiếm sống bằng nghề viết tự do."}]','[]',NULL,'/ˈmeɪk ə ˈlɪvɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4639,'colloc-9-01',149,'make a prediction','đưa ra dự đoán','v + n','[{"en":"Scientists make a prediction based on current data.","vi":"Các nhà khoa học đưa ra dự đoán dựa trên dữ liệu hiện tại."},{"en":"It is risky to make a prediction about the economy.","vi":"Thật mạo hiểm khi đưa ra dự đoán về nền kinh tế."},{"en":"The model lets us make a prediction about future trends.","vi":"Mô hình cho phép chúng ta đưa ra dự đoán về xu hướng tương lai."}]','[]',NULL,'/ˈmeɪk ə prɪˈdɪkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4640,'colloc-9-01',150,'make a recommendation','đưa ra khuyến nghị','v + n','[{"en":"The report makes a recommendation to improve safety standards.","vi":"Báo cáo đưa ra khuyến nghị nhằm cải thiện tiêu chuẩn an toàn."},{"en":"The doctor made a recommendation about my diet.","vi":"Bác sĩ đã đưa ra khuyến nghị về chế độ ăn của tôi."},{"en":"Experts make a recommendation after reviewing the evidence.","vi":"Các chuyên gia đưa ra khuyến nghị sau khi xem xét bằng chứng."}]','[]',NULL,'/ˈmeɪk ə ˌrekəmenˈdeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4641,'colloc-10-01',1,'make a statement','đưa ra tuyên bố','v + n','[{"en":"The minister will make a statement about the new law.","vi":"Bộ trưởng sẽ đưa ra tuyên bố về luật mới."},{"en":"She made a strong statement against the proposal.","vi":"Cô ấy đã đưa ra một tuyên bố mạnh mẽ phản đối đề xuất."},{"en":"The company made a statement to reassure its customers.","vi":"Công ty đã đưa ra tuyên bố để trấn an khách hàng."}]','[]',NULL,'/ˈmeɪk ə ˈsteɪtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4642,'colloc-10-01',2,'make a transition','thực hiện sự chuyển đổi','v + n','[{"en":"Many firms make a transition to clean energy slowly.","vi":"Nhiều công ty thực hiện sự chuyển đổi sang năng lượng sạch một cách chậm rãi."},{"en":"Students make a transition from school to university life.","vi":"Sinh viên thực hiện sự chuyển đổi từ trường phổ thông sang đời sống đại học."},{"en":"The country made a transition to a market economy.","vi":"Đất nước đã thực hiện sự chuyển đổi sang nền kinh tế thị trường."}]','[]',NULL,'/ˈmeɪk ə trænˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4643,'colloc-10-01',3,'make an argument','đưa ra lập luận','v + n','[{"en":"The writer makes an argument for stricter regulations.","vi":"Người viết đưa ra lập luận ủng hộ các quy định chặt chẽ hơn."},{"en":"You should support each claim when you make an argument.","vi":"Bạn nên hỗ trợ mỗi luận điểm khi đưa ra lập luận."},{"en":"She made a convincing argument during the debate.","vi":"Cô ấy đã đưa ra một lập luận thuyết phục trong cuộc tranh luận."}]','[]',NULL,'/ˈmeɪk ən ˈɑːrgjumənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4644,'colloc-10-01',4,'make an assessment','đưa ra đánh giá','v + n','[{"en":"The teacher makes an assessment of each student''s progress.","vi":"Giáo viên đưa ra đánh giá về tiến bộ của từng học sinh."},{"en":"Experts made an assessment of the environmental risks.","vi":"Các chuyên gia đã đưa ra đánh giá về các rủi ro môi trường."},{"en":"We need to make an assessment before approving the plan.","vi":"Chúng ta cần đưa ra đánh giá trước khi phê duyệt kế hoạch."}]','[]',NULL,'/ˈmeɪk ən əˈsesmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4645,'colloc-10-01',5,'make an assumption','đưa ra giả định','v + n','[{"en":"Do not make an assumption without checking the facts.","vi":"Đừng đưa ra giả định mà chưa kiểm tra sự thật."},{"en":"The model makes an assumption that prices stay stable.","vi":"Mô hình đưa ra giả định rằng giá cả giữ ổn định."},{"en":"Researchers often make an assumption to simplify analysis.","vi":"Các nhà nghiên cứu thường đưa ra giả định để đơn giản hóa phân tích."}]','[]',NULL,'/ˈmeɪk ən əˈsʌmpʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4646,'colloc-10-01',6,'make an impact','tạo ra ảnh hưởng','v + n','[{"en":"Small changes can make an impact on the environment.","vi":"Những thay đổi nhỏ có thể tạo ra ảnh hưởng đến môi trường."},{"en":"The campaign made an impact on public attitudes.","vi":"Chiến dịch đã tạo ra ảnh hưởng đến thái độ của công chúng."},{"en":"Volunteers hope to make an impact in their community.","vi":"Các tình nguyện viên hy vọng tạo ra ảnh hưởng trong cộng đồng."}]','[]',NULL,'/ˈmeɪk ən ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4647,'colloc-10-01',7,'make an impression','gây ấn tượng','v + n','[{"en":"A strong introduction helps you make an impression on readers.","vi":"Một phần mở đầu mạnh giúp bạn gây ấn tượng với độc giả."},{"en":"The candidate made a good impression during the interview.","vi":"Ứng viên đã gây ấn tượng tốt trong buổi phỏng vấn."},{"en":"Her speech made a lasting impression on the audience.","vi":"Bài phát biểu của cô đã gây ấn tượng lâu dài với khán giả."}]','[]',NULL,'/ˈmeɪk ən ɪmˈpreʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4648,'colloc-10-01',8,'make an observation','đưa ra nhận xét, quan sát','v + n','[{"en":"The scientist made an observation about the cells'' behavior.","vi":"Nhà khoa học đã đưa ra một quan sát về hành vi của các tế bào."},{"en":"Let me make an observation about the survey results.","vi":"Cho tôi đưa ra một nhận xét về kết quả khảo sát."},{"en":"She made a sharp observation during the seminar.","vi":"Cô ấy đã đưa ra một nhận xét sắc sảo trong buổi hội thảo."}]','[]',NULL,'/ˈmeɪk ən ˌɑːbzərˈveɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4649,'colloc-10-01',9,'male dominance','sự thống trị của nam giới','adj + n','[{"en":"The study examines male dominance in senior management.","vi":"Nghiên cứu xem xét sự thống trị của nam giới ở cấp quản lý cao."},{"en":"Male dominance in the field has declined over time.","vi":"Sự thống trị của nam giới trong lĩnh vực này đã giảm theo thời gian."},{"en":"Many professions still show clear male dominance.","vi":"Nhiều ngành nghề vẫn cho thấy sự thống trị rõ rệt của nam giới."}]','[]',NULL,'/ˈmeɪl ˈdɑːmɪnəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4650,'colloc-10-01',10,'manual worker','công nhân lao động chân tay','adj + n','[{"en":"A manual worker often faces a higher risk of injury.","vi":"Công nhân lao động chân tay thường đối mặt nguy cơ chấn thương cao hơn."},{"en":"Wages for manual workers have risen in recent years.","vi":"Lương cho công nhân lao động chân tay đã tăng trong những năm gần đây."},{"en":"The factory employs many skilled manual workers.","vi":"Nhà máy thuê nhiều công nhân lao động chân tay lành nghề."}]','[]',NULL,'/ˈmænjuəl ˈwɜːrkər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4651,'colloc-10-01',11,'manufacturing sector','khu vực sản xuất','adj + n','[{"en":"The manufacturing sector employs millions of workers nationwide.","vi":"Khu vực sản xuất thuê hàng triệu lao động trên toàn quốc."},{"en":"Growth in the manufacturing sector boosted the economy.","vi":"Sự tăng trưởng của khu vực sản xuất đã thúc đẩy nền kinh tế."},{"en":"The manufacturing sector has adopted more automation recently.","vi":"Khu vực sản xuất gần đây đã áp dụng nhiều tự động hóa hơn."}]','[]',NULL,'/ˌmænjəˈfæktʃərɪŋ ˈsektər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4652,'colloc-10-01',12,'marked contrast','sự tương phản rõ rệt','adj + n','[{"en":"There is a marked contrast between the two regions'' incomes.","vi":"Có một sự tương phản rõ rệt giữa thu nhập của hai vùng."},{"en":"The results show a marked contrast with earlier studies.","vi":"Kết quả cho thấy một sự tương phản rõ rệt với các nghiên cứu trước."},{"en":"Her calm tone was in marked contrast to the chaos.","vi":"Giọng điệu bình tĩnh của cô tương phản rõ rệt với sự hỗn loạn."}]','[]',NULL,'/ˈmɑːrkt ˈkɑːntræst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4653,'colloc-10-01',13,'markedly different','khác biệt rõ rệt','adv + adj','[{"en":"The two groups produced markedly different results.","vi":"Hai nhóm đã tạo ra những kết quả khác biệt rõ rệt."},{"en":"Urban life is markedly different from rural life.","vi":"Đời sống đô thị khác biệt rõ rệt so với đời sống nông thôn."},{"en":"Their views on the issue were markedly different.","vi":"Quan điểm của họ về vấn đề này khác biệt rõ rệt."}]','[]',NULL,'/ˈmɑːrkɪdli ˈdɪfərənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4654,'colloc-10-01',14,'maximum duration','thời lượng tối đa','adj + n','[{"en":"The maximum duration of the exam is three hours.","vi":"Thời lượng tối đa của bài thi là ba giờ."},{"en":"The contract sets a maximum duration of two years.","vi":"Hợp đồng đặt ra thời lượng tối đa là hai năm."},{"en":"Each presentation has a maximum duration of ten minutes.","vi":"Mỗi bài thuyết trình có thời lượng tối đa là mười phút."}]','[]',NULL,'/ˈmæksɪməm dʊˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4655,'colloc-10-01',15,'mean score','điểm trung bình','adj + n','[{"en":"The mean score for the class was seventy-five percent.","vi":"Điểm trung bình của lớp là bảy mươi lăm phần trăm."},{"en":"Researchers compared the mean score of both groups.","vi":"Các nhà nghiên cứu so sánh điểm trung bình của cả hai nhóm."},{"en":"The mean score rose after the new teaching method.","vi":"Điểm trung bình tăng sau phương pháp giảng dạy mới."}]','[]',NULL,'/ˈmiːn ˈskɔːr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4656,'colloc-10-01',16,'meaningful way','cách có ý nghĩa','adj + n','[{"en":"The project lets students apply theory in a meaningful way.","vi":"Dự án cho phép sinh viên áp dụng lý thuyết một cách có ý nghĩa."},{"en":"We should present the data in a meaningful way.","vi":"Chúng ta nên trình bày dữ liệu một cách có ý nghĩa."},{"en":"Volunteering connects people in a meaningful way.","vi":"Tình nguyện kết nối mọi người theo một cách có ý nghĩa."}]','[]',NULL,'/ˈmiːnɪŋfəl ˈweɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4657,'colloc-10-01',17,'media coverage','sự đưa tin của truyền thông','n + n','[{"en":"The event received wide media coverage across the country.","vi":"Sự kiện nhận được sự đưa tin rộng rãi của truyền thông khắp cả nước."},{"en":"Media coverage of the scandal lasted several weeks.","vi":"Sự đưa tin của truyền thông về vụ bê bối kéo dài vài tuần."},{"en":"Negative media coverage can damage a company''s reputation.","vi":"Sự đưa tin tiêu cực của truyền thông có thể làm hại danh tiếng công ty."}]','[]',NULL,'/ˈmiːdiə ˈkʌvərɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4658,'colloc-10-01',18,'medical assistance','hỗ trợ y tế','adj + n','[{"en":"The injured hikers needed immediate medical assistance.","vi":"Những người leo núi bị thương cần hỗ trợ y tế ngay lập tức."},{"en":"The charity provides medical assistance to remote villages.","vi":"Tổ chức từ thiện cung cấp hỗ trợ y tế cho các bản làng xa xôi."},{"en":"Travelers should know where to find medical assistance abroad.","vi":"Du khách nên biết tìm hỗ trợ y tế ở đâu khi ở nước ngoài."}]','[]',NULL,'/ˈmedɪkəl əˈsɪstəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4659,'colloc-10-01',19,'medical treatment','điều trị y tế','adj + n','[{"en":"The patient received medical treatment for several months.","vi":"Bệnh nhân đã được điều trị y tế trong vài tháng."},{"en":"Many people cannot afford proper medical treatment.","vi":"Nhiều người không đủ khả năng chi trả cho điều trị y tế đúng cách."},{"en":"Early medical treatment can prevent serious complications.","vi":"Điều trị y tế sớm có thể ngăn ngừa các biến chứng nghiêm trọng."}]','[]',NULL,'/ˈmedɪkəl ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4660,'colloc-10-01',20,'meet criteria','đáp ứng tiêu chí','v + n','[{"en":"Applicants must meet criteria before being accepted.","vi":"Ứng viên phải đáp ứng tiêu chí trước khi được chấp nhận."},{"en":"The proposal failed to meet criteria set by the committee.","vi":"Đề xuất đã không đáp ứng được tiêu chí mà hội đồng đặt ra."},{"en":"Only products that meet criteria receive the safety label.","vi":"Chỉ những sản phẩm đáp ứng tiêu chí mới nhận được nhãn an toàn."}]','[]',NULL,'/ˈmiːt kraɪˈtɪriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4661,'colloc-10-01',21,'meet expectations','đáp ứng kỳ vọng','v + n','[{"en":"The new product failed to meet expectations in sales.","vi":"Sản phẩm mới đã không đáp ứng kỳ vọng về doanh số."},{"en":"The course did not meet the students'' expectations.","vi":"Khóa học đã không đáp ứng kỳ vọng của sinh viên."},{"en":"Their performance exceeded and met all expectations.","vi":"Màn thể hiện của họ đã vượt qua và đáp ứng mọi kỳ vọng."}]','[]',NULL,'/ˈmiːt ˌekspekˈteɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4662,'colloc-10-01',22,'meet a requirement','đáp ứng một yêu cầu','v + n','[{"en":"Students must meet a requirement of forty credits to graduate.","vi":"Sinh viên phải đáp ứng yêu cầu bốn mươi tín chỉ để tốt nghiệp."},{"en":"The design did not meet a key safety requirement.","vi":"Thiết kế đã không đáp ứng một yêu cầu an toàn quan trọng."},{"en":"All candidates must meet a language requirement first.","vi":"Mọi ứng viên trước hết phải đáp ứng một yêu cầu về ngôn ngữ."}]','[]',NULL,'/ˈmiːt ə rɪˈkwaɪərmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4663,'colloc-10-01',23,'meet a target','đạt được chỉ tiêu','v + n','[{"en":"The team worked hard to meet a sales target.","vi":"Cả nhóm đã làm việc chăm chỉ để đạt được chỉ tiêu doanh số."},{"en":"The country aims to meet a target for clean energy.","vi":"Quốc gia này hướng tới đạt được chỉ tiêu về năng lượng sạch."},{"en":"They failed to meet a target set last year.","vi":"Họ đã không đạt được chỉ tiêu đặt ra năm ngoái."}]','[]',NULL,'/ˈmiːt ə ˈtɑːrgɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4664,'colloc-10-01',24,'meet an objective','đạt được mục tiêu','v + n','[{"en":"The program helped the school meet an objective on literacy.","vi":"Chương trình đã giúp nhà trường đạt được mục tiêu về xóa mù chữ."},{"en":"Each task is designed to meet an objective of the course.","vi":"Mỗi nhiệm vụ được thiết kế để đạt được một mục tiêu của khóa học."},{"en":"The company met an important objective ahead of schedule.","vi":"Công ty đã đạt được một mục tiêu quan trọng trước thời hạn."}]','[]',NULL,'/ˈmiːt ən əbˈdʒektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4665,'colloc-10-01',25,'mental health','sức khỏe tâm thần','adj + n','[{"en":"Regular exercise can improve your mental health.","vi":"Tập thể dục đều đặn có thể cải thiện sức khỏe tâm thần của bạn."},{"en":"The university offers mental health support to students.","vi":"Trường đại học cung cấp hỗ trợ sức khỏe tâm thần cho sinh viên."},{"en":"Stress at work can harm long-term mental health.","vi":"Căng thẳng trong công việc có thể làm hại sức khỏe tâm thần lâu dài."}]','[]',NULL,'/ˈmentəl ˈhelθ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4666,'colloc-10-01',26,'mental illness','bệnh tâm thần','adj + n','[{"en":"Many people with mental illness do not seek help.","vi":"Nhiều người mắc bệnh tâm thần không tìm kiếm sự giúp đỡ."},{"en":"The campaign aims to reduce the stigma of mental illness.","vi":"Chiến dịch nhằm giảm sự kỳ thị đối với bệnh tâm thần."},{"en":"Early treatment of mental illness improves recovery rates.","vi":"Điều trị sớm bệnh tâm thần cải thiện tỷ lệ hồi phục."}]','[]',NULL,'/ˈmentəl ˈɪlnəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4667,'colloc-10-01',27,'mental state','trạng thái tâm lý','adj + n','[{"en":"Lack of sleep can affect a person''s mental state.","vi":"Thiếu ngủ có thể ảnh hưởng đến trạng thái tâm lý của một người."},{"en":"The doctor assessed the patient''s mental state carefully.","vi":"Bác sĩ đã đánh giá cẩn thận trạng thái tâm lý của bệnh nhân."},{"en":"His calm mental state helped him handle the crisis.","vi":"Trạng thái tâm lý bình tĩnh đã giúp anh xử lý khủng hoảng."}]','[]',NULL,'/ˈmentəl ˈsteɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4668,'colloc-10-01',28,'methodological approach','cách tiếp cận phương pháp luận','adj + n','[{"en":"The study uses a quantitative methodological approach.","vi":"Nghiên cứu sử dụng cách tiếp cận phương pháp luận định lượng."},{"en":"Their methodological approach differs from earlier research.","vi":"Cách tiếp cận phương pháp luận của họ khác với nghiên cứu trước."},{"en":"A clear methodological approach makes results easier to trust.","vi":"Cách tiếp cận phương pháp luận rõ ràng làm kết quả dễ tin cậy hơn."}]','[]',NULL,'/ˌmeθədəˈlɑːdʒɪkəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4669,'colloc-10-01',29,'methodological issue','vấn đề phương pháp luận','adj + n','[{"en":"The reviewers raised a methodological issue with the sample.","vi":"Các phản biện đã nêu một vấn đề phương pháp luận về mẫu khảo sát."},{"en":"A methodological issue weakened the study''s conclusions.","vi":"Một vấn đề phương pháp luận đã làm suy yếu các kết luận của nghiên cứu."},{"en":"The author discusses each methodological issue in detail.","vi":"Tác giả thảo luận chi tiết từng vấn đề phương pháp luận."}]','[]',NULL,'/ˌmeθədəˈlɑːdʒɪkəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4670,'colloc-10-01',30,'methodological problem','khó khăn về phương pháp luận','adj + n','[{"en":"A serious methodological problem affected the data quality.","vi":"Một khó khăn nghiêm trọng về phương pháp luận đã ảnh hưởng đến chất lượng dữ liệu."},{"en":"The team solved a methodological problem in the survey design.","vi":"Nhóm đã giải quyết một khó khăn về phương pháp luận trong thiết kế khảo sát."},{"en":"Critics pointed to a methodological problem in the analysis.","vi":"Các nhà phê bình chỉ ra một khó khăn về phương pháp luận trong phân tích."}]','[]',NULL,'/ˌmeθədəˈlɑːdʒɪkəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4671,'colloc-10-01',31,'metropolitan area','khu vực đô thị lớn','adj + n','[{"en":"Housing costs are highest in the metropolitan area.","vi":"Chi phí nhà ở cao nhất ở khu vực đô thị lớn."},{"en":"The metropolitan area has grown rapidly over the decade.","vi":"Khu vực đô thị lớn đã phát triển nhanh chóng trong thập kỷ qua."},{"en":"Public transport connects the whole metropolitan area.","vi":"Giao thông công cộng kết nối toàn bộ khu vực đô thị lớn."}]','[]',NULL,'/ˌmetrəˈpɑːlɪtən ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4672,'colloc-10-01',32,'middle income','thu nhập trung bình','adj + n','[{"en":"Many middle income families struggle with rising prices.","vi":"Nhiều gia đình thu nhập trung bình chật vật với giá cả tăng cao."},{"en":"The country has reached middle income status recently.","vi":"Quốc gia này gần đây đã đạt mức thu nhập trung bình."},{"en":"The policy targets middle income households specifically.","vi":"Chính sách nhắm cụ thể vào các hộ gia đình thu nhập trung bình."}]','[]',NULL,'/ˈmɪdəl ˈɪnkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4673,'colloc-10-01',33,'middle management','quản lý cấp trung','adj + n','[{"en":"Middle management connects senior leaders with regular staff.","vi":"Quản lý cấp trung kết nối lãnh đạo cấp cao với nhân viên thường."},{"en":"The company cut several middle management positions.","vi":"Công ty đã cắt giảm một số vị trí quản lý cấp trung."},{"en":"Good middle management improves communication across teams.","vi":"Quản lý cấp trung tốt cải thiện giao tiếp giữa các nhóm."}]','[]',NULL,'/ˈmɪdəl ˈmænɪdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4674,'colloc-10-01',34,'migrant worker','lao động nhập cư','adj + n','[{"en":"Many migrant workers send money home to their families.","vi":"Nhiều lao động nhập cư gửi tiền về cho gia đình họ."},{"en":"The report studies the rights of migrant workers.","vi":"Báo cáo nghiên cứu quyền lợi của lao động nhập cư."},{"en":"Migrant workers often fill jobs that locals avoid.","vi":"Lao động nhập cư thường đảm nhận những công việc mà người địa phương né tránh."}]','[]',NULL,'/ˈmaɪgrənt ˈwɜːrkər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4675,'colloc-10-01',35,'military action','hành động quân sự','adj + n','[{"en":"The government threatened military action against the rebels.","vi":"Chính phủ đã đe dọa hành động quân sự chống lại quân nổi dậy."},{"en":"Many people protested against the military action abroad.","vi":"Nhiều người đã phản đối hành động quân sự ở nước ngoài."},{"en":"Diplomats hoped to avoid further military action.","vi":"Các nhà ngoại giao hy vọng tránh được hành động quân sự thêm nữa."}]','[]',NULL,'/ˈmɪləteri ˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4676,'colloc-10-01',36,'military force','lực lượng quân sự','adj + n','[{"en":"The country used military force to defend its borders.","vi":"Quốc gia này đã dùng lực lượng quân sự để bảo vệ biên giới."},{"en":"The use of military force was widely criticized.","vi":"Việc sử dụng lực lượng quân sự đã bị chỉ trích rộng rãi."},{"en":"Both sides agreed to withdraw their military forces.","vi":"Cả hai bên đã đồng ý rút lực lượng quân sự của mình."}]','[]',NULL,'/ˈmɪləteri ˈfɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4677,'colloc-10-01',37,'military power','sức mạnh quân sự','adj + n','[{"en":"The nation built up its military power over the decade.","vi":"Quốc gia này đã xây dựng sức mạnh quân sự trong suốt thập kỷ."},{"en":"Economic strength often supports military power.","vi":"Sức mạnh kinh tế thường hỗ trợ cho sức mạnh quân sự."},{"en":"Military power alone cannot guarantee lasting peace.","vi":"Riêng sức mạnh quân sự không thể đảm bảo hòa bình lâu dài."}]','[]',NULL,'/ˈmɪləteri ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4678,'colloc-10-01',38,'military service','nghĩa vụ quân sự','adj + n','[{"en":"In some countries, military service is compulsory for young men.","vi":"Ở một số nước, nghĩa vụ quân sự là bắt buộc với nam thanh niên."},{"en":"He completed his military service before attending university.","vi":"Anh ấy đã hoàn thành nghĩa vụ quân sự trước khi vào đại học."},{"en":"Many veterans struggle to adjust after military service.","vi":"Nhiều cựu binh chật vật thích nghi sau nghĩa vụ quân sự."}]','[]',NULL,'/ˈmɪləteri ˈsɜːrvɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4679,'colloc-10-01',39,'minimum level','mức tối thiểu','adj + n','[{"en":"Applicants must reach a minimum level of English.","vi":"Ứng viên phải đạt được mức tối thiểu về tiếng Anh."},{"en":"The law sets a minimum level of safety for workplaces.","vi":"Luật đặt ra một mức tối thiểu về an toàn cho nơi làm việc."},{"en":"Funding was cut to the minimum level this year.","vi":"Kinh phí đã bị cắt xuống mức tối thiểu trong năm nay."}]','[]',NULL,'/ˈmɪnɪməm ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4680,'colloc-10-01',40,'minimum requirement','yêu cầu tối thiểu','adj + n','[{"en":"A high school diploma is the minimum requirement for this job.","vi":"Bằng tốt nghiệp phổ thông là yêu cầu tối thiểu cho công việc này."},{"en":"The course has a minimum requirement of basic math.","vi":"Khóa học có yêu cầu tối thiểu về toán cơ bản."},{"en":"Students who meet the minimum requirement may apply early.","vi":"Sinh viên đáp ứng yêu cầu tối thiểu có thể nộp đơn sớm."}]','[]',NULL,'/ˈmɪnɪməm rɪˈkwaɪərmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4681,'colloc-10-01',41,'minimum standard','tiêu chuẩn tối thiểu','adj + n','[{"en":"The factory must meet a minimum standard of hygiene.","vi":"Nhà máy phải đạt một tiêu chuẩn tối thiểu về vệ sinh."},{"en":"Regulations set a minimum standard for building safety.","vi":"Các quy định đặt ra một tiêu chuẩn tối thiểu về an toàn xây dựng."},{"en":"All products fall below the minimum standard required.","vi":"Mọi sản phẩm đều dưới tiêu chuẩn tối thiểu được yêu cầu."}]','[]',NULL,'/ˈmɪnɪməm ˈstændərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4682,'colloc-10-01',42,'minimum value','giá trị tối thiểu','adj + n','[{"en":"The graph shows the minimum value reached in winter.","vi":"Biểu đồ cho thấy giá trị tối thiểu đạt được vào mùa đông."},{"en":"The function returns a minimum value of zero.","vi":"Hàm số trả về giá trị tối thiểu là không."},{"en":"Temperatures dropped to their minimum value at night.","vi":"Nhiệt độ giảm xuống giá trị tối thiểu vào ban đêm."}]','[]',NULL,'/ˈmɪnɪməm ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4683,'colloc-10-01',43,'minimum wage','lương tối thiểu','adj + n','[{"en":"The government raised the minimum wage this year.","vi":"Chính phủ đã tăng lương tối thiểu trong năm nay."},{"en":"Many workers earn only the minimum wage.","vi":"Nhiều người lao động chỉ kiếm được mức lương tối thiểu."},{"en":"A higher minimum wage can reduce poverty levels.","vi":"Lương tối thiểu cao hơn có thể giảm mức độ nghèo đói."}]','[]',NULL,'/ˈmɪnɪməm ˈweɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4684,'colloc-10-01',44,'minor change','thay đổi nhỏ','adj + n','[{"en":"The editor suggested only a minor change to the draft.","vi":"Biên tập viên chỉ đề xuất một thay đổi nhỏ cho bản thảo."},{"en":"A minor change in diet improved his energy levels.","vi":"Một thay đổi nhỏ trong chế độ ăn đã cải thiện mức năng lượng của anh."},{"en":"We made a minor change to the schedule.","vi":"Chúng tôi đã thực hiện một thay đổi nhỏ trong lịch trình."}]','[]',NULL,'/ˈmaɪnər ˈtʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4685,'colloc-10-01',45,'minor role','vai trò nhỏ','adj + n','[{"en":"Luck played only a minor role in their success.","vi":"May mắn chỉ đóng một vai trò nhỏ trong thành công của họ."},{"en":"She had a minor role in the school play.","vi":"Cô ấy có một vai trò nhỏ trong vở kịch của trường."},{"en":"Diet plays a minor role compared with genetics here.","vi":"Chế độ ăn đóng vai trò nhỏ so với yếu tố di truyền ở đây."}]','[]',NULL,'/ˈmaɪnər ˈroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4686,'colloc-10-01',46,'minority group','nhóm thiểu số','n + n','[{"en":"The policy aims to protect every minority group.","vi":"Chính sách nhằm bảo vệ mọi nhóm thiểu số."},{"en":"Members of the minority group faced discrimination at work.","vi":"Các thành viên của nhóm thiểu số đã đối mặt với phân biệt đối xử tại nơi làm việc."},{"en":"The survey included several ethnic minority groups.","vi":"Cuộc khảo sát bao gồm một số nhóm dân tộc thiểu số."}]','[]',NULL,'/maɪˈnɔːrəti ˈgruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4687,'colloc-10-01',47,'missing data','dữ liệu bị thiếu','adj + n','[{"en":"Missing data made the analysis less reliable.","vi":"Dữ liệu bị thiếu khiến phân tích kém tin cậy hơn."},{"en":"Researchers used a model to handle the missing data.","vi":"Các nhà nghiên cứu đã dùng một mô hình để xử lý dữ liệu bị thiếu."},{"en":"We must explain how missing data was treated.","vi":"Chúng ta phải giải thích cách dữ liệu bị thiếu được xử lý."}]','[]',NULL,'/ˈmɪsɪŋ ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4688,'colloc-10-01',48,'modern culture','văn hóa hiện đại','adj + n','[{"en":"Social media plays a big part in modern culture.","vi":"Mạng xã hội đóng một vai trò lớn trong văn hóa hiện đại."},{"en":"The exhibition explores themes in modern culture.","vi":"Triển lãm khám phá các chủ đề trong văn hóa hiện đại."},{"en":"Modern culture often values speed over patience.","vi":"Văn hóa hiện đại thường coi trọng tốc độ hơn sự kiên nhẫn."}]','[]',NULL,'/ˈmɑːdərn ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4689,'colloc-10-01',49,'modern method','phương pháp hiện đại','adj + n','[{"en":"Farmers adopted modern methods to increase their yields.","vi":"Nông dân đã áp dụng các phương pháp hiện đại để tăng năng suất."},{"en":"The hospital uses modern methods to treat the disease.","vi":"Bệnh viện sử dụng các phương pháp hiện đại để điều trị căn bệnh."},{"en":"Modern methods of teaching focus on active learning.","vi":"Các phương pháp giảng dạy hiện đại tập trung vào học chủ động."}]','[]',NULL,'/ˈmɑːdərn ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4690,'colloc-10-01',50,'modern society','xã hội hiện đại','adj + n','[{"en":"Technology shapes almost every part of modern society.","vi":"Công nghệ định hình hầu như mọi mặt của xã hội hiện đại."},{"en":"Modern society faces challenges like climate change.","vi":"Xã hội hiện đại đối mặt với những thách thức như biến đổi khí hậu."},{"en":"Education is highly valued in modern society.","vi":"Giáo dục được đánh giá cao trong xã hội hiện đại."}]','[]',NULL,'/ˈmɑːdərn səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4691,'colloc-10-01',51,'modern technology','công nghệ hiện đại','adj + n','[{"en":"Modern technology has transformed the way we work.","vi":"Công nghệ hiện đại đã thay đổi cách chúng ta làm việc."},{"en":"Doctors rely on modern technology to diagnose patients.","vi":"Bác sĩ dựa vào công nghệ hiện đại để chẩn đoán bệnh nhân."},{"en":"Modern technology makes long-distance communication easy.","vi":"Công nghệ hiện đại làm cho việc liên lạc đường dài trở nên dễ dàng."}]','[]',NULL,'/ˈmɑːdərn tekˈnɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4692,'colloc-10-01',52,'modified form','dạng đã chỉnh sửa','adj + n','[{"en":"The plant was grown in a genetically modified form.","vi":"Cây trồng được nuôi dưới một dạng biến đổi gen."},{"en":"The team tested a modified form of the original design.","vi":"Nhóm đã thử nghiệm một dạng đã chỉnh sửa của thiết kế gốc."},{"en":"The theory appears here in a slightly modified form.","vi":"Lý thuyết xuất hiện ở đây dưới một dạng được chỉnh sửa đôi chút."}]','[]',NULL,'/ˈmɑːdɪfaɪd ˈfɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4693,'colloc-10-01',53,'modified version','phiên bản đã chỉnh sửa','adj + n','[{"en":"The team released a modified version of the original software.","vi":"Nhóm đã phát hành một phiên bản chỉnh sửa của phần mềm gốc."},{"en":"Researchers tested a modified version of the standard experiment.","vi":"Các nhà nghiên cứu đã thử nghiệm một phiên bản chỉnh sửa của thí nghiệm chuẩn."},{"en":"She presented a modified version of her earlier proposal.","vi":"Cô đã trình bày một phiên bản chỉnh sửa của đề xuất trước đó."}]','[]',NULL,'/ˈmɑːdəfaɪd ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4694,'colloc-10-01',54,'moral dilemma','tình huống khó xử về đạo đức','adj + n','[{"en":"The doctor faced a serious moral dilemma during the emergency.","vi":"Bác sĩ đối mặt với một tình huống khó xử về đạo đức nghiêm trọng."},{"en":"The novel explores a moral dilemma about loyalty and truth.","vi":"Cuốn tiểu thuyết khám phá một tình huống đạo đức khó xử về lòng trung thành và sự thật."},{"en":"Students debated the moral dilemma raised in the case study.","vi":"Sinh viên tranh luận về tình huống đạo đức khó xử nêu trong nghiên cứu tình huống."}]','[]',NULL,'/ˈmɔːrəl dɪˈlemə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4695,'colloc-10-01',55,'moral philosophy','triết học đạo đức','adj + n','[{"en":"She wrote her thesis on a key question in moral philosophy.","vi":"Cô viết luận án về một câu hỏi cốt lõi trong triết học đạo đức."},{"en":"Moral philosophy examines how people should act toward others.","vi":"Triết học đạo đức xem xét con người nên hành xử với người khác ra sao."},{"en":"The course introduces students to classical moral philosophy.","vi":"Khóa học giới thiệu cho sinh viên triết học đạo đức cổ điển."}]','[]',NULL,'/ˈmɔːrəl fəˈlɑːsəfi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4696,'colloc-10-01',56,'moral principle','nguyên tắc đạo đức','adj + n','[{"en":"He refused to compromise his core moral principle for money.","vi":"Anh từ chối thỏa hiệp nguyên tắc đạo đức cốt lõi của mình vì tiền."},{"en":"The constitution rests on a firm moral principle of fairness.","vi":"Hiến pháp dựa trên một nguyên tắc đạo đức vững chắc về sự công bằng."},{"en":"Teachers try to instill a strong moral principle in children.","vi":"Giáo viên cố gắng gieo cho trẻ một nguyên tắc đạo đức vững chắc."}]','[]',NULL,'/ˈmɔːrəl ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4697,'colloc-10-01',57,'multiple identities','nhiều bản sắc khác nhau','adj + n','[{"en":"Many immigrants navigate multiple identities in their daily lives.","vi":"Nhiều người nhập cư cân bằng nhiều bản sắc trong cuộc sống hằng ngày."},{"en":"The study examines how people manage multiple identities online.","vi":"Nghiên cứu xem xét cách con người quản lý nhiều bản sắc trên mạng."},{"en":"Globalization allows individuals to hold multiple identities at once.","vi":"Toàn cầu hóa cho phép cá nhân mang nhiều bản sắc cùng lúc."}]','[]',NULL,'/ˈmʌltəpəl aɪˈdentətiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4698,'colloc-10-01',58,'multiple sources','nhiều nguồn khác nhau','adj + n','[{"en":"Good researchers verify facts using multiple sources of evidence.","vi":"Nhà nghiên cứu giỏi kiểm chứng sự thật bằng nhiều nguồn bằng chứng."},{"en":"The report draws on multiple sources for a balanced view.","vi":"Báo cáo dựa trên nhiều nguồn để có một góc nhìn cân bằng."},{"en":"Funding came from multiple sources, including private donors.","vi":"Kinh phí đến từ nhiều nguồn, bao gồm cả nhà tài trợ tư nhân."}]','[]',NULL,'/ˈmʌltəpəl ˈsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4699,'colloc-10-01',59,'municipal government','chính quyền thành phố','adj + n','[{"en":"The municipal government approved funding for the new park.","vi":"Chính quyền thành phố đã phê duyệt kinh phí cho công viên mới."},{"en":"Local services are usually managed by the municipal government.","vi":"Các dịch vụ địa phương thường do chính quyền thành phố quản lý."},{"en":"Residents petitioned the municipal government for better roads.","vi":"Người dân kiến nghị chính quyền thành phố cải thiện đường sá."}]','[]',NULL,'/mjuːˈnɪsəpəl ˈɡʌvərnmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4700,'colloc-10-01',60,'mutual recognition','sự công nhận lẫn nhau','adj + n','[{"en":"The treaty established mutual recognition of professional qualifications.","vi":"Hiệp ước thiết lập sự công nhận lẫn nhau về bằng cấp nghề nghiệp."},{"en":"Lasting peace requires mutual recognition between the two states.","vi":"Hòa bình bền vững đòi hỏi sự công nhận lẫn nhau giữa hai quốc gia."},{"en":"Mutual recognition of degrees makes student exchange easier.","vi":"Sự công nhận bằng cấp lẫn nhau giúp trao đổi sinh viên dễ hơn."}]','[]',NULL,'/ˈmjuːtʃuəl ˌrekəɡˈnɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4701,'colloc-10-01',61,'mutual support','sự hỗ trợ lẫn nhau','adj + n','[{"en":"The two communities relied on mutual support during the crisis.","vi":"Hai cộng đồng đã dựa vào sự hỗ trợ lẫn nhau trong cơn khủng hoảng."},{"en":"A strong team is built on mutual support and trust.","vi":"Một đội ngũ vững mạnh được xây trên sự hỗ trợ và tin tưởng lẫn nhau."},{"en":"The agreement promotes mutual support between member countries.","vi":"Thỏa thuận thúc đẩy sự hỗ trợ lẫn nhau giữa các nước thành viên."}]','[]',NULL,'/ˈmjuːtʃuəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4702,'colloc-10-01',62,'mutual trust','sự tin tưởng lẫn nhau','adj + n','[{"en":"Successful partnerships depend on a high level of mutual trust.","vi":"Quan hệ đối tác thành công phụ thuộc vào mức độ tin tưởng lẫn nhau cao."},{"en":"Years of cooperation gradually built mutual trust between them.","vi":"Nhiều năm hợp tác dần xây dựng sự tin tưởng lẫn nhau giữa họ."},{"en":"Without mutual trust, the negotiations quickly broke down.","vi":"Thiếu sự tin tưởng lẫn nhau, cuộc đàm phán nhanh chóng đổ vỡ."}]','[]',NULL,'/ˈmjuːtʃuəl trʌst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4703,'colloc-10-01',63,'mutual understanding','sự thấu hiểu lẫn nhau','adj + n','[{"en":"Cultural exchange programs foster mutual understanding between nations.","vi":"Các chương trình giao lưu văn hóa nuôi dưỡng sự thấu hiểu lẫn nhau giữa các nước."},{"en":"Open dialogue is the first step toward mutual understanding.","vi":"Đối thoại cởi mở là bước đầu tiên hướng tới sự thấu hiểu lẫn nhau."},{"en":"They reached a mutual understanding after a long discussion.","vi":"Họ đạt được sự thấu hiểu lẫn nhau sau một cuộc thảo luận dài."}]','[]',NULL,'/ˈmjuːtʃuəl ˌʌndərˈstændɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4704,'colloc-10-01',64,'mutually exclusive','loại trừ lẫn nhau','adv + adj','[{"en":"These two goals are not mutually exclusive; we can pursue both.","vi":"Hai mục tiêu này không loại trừ lẫn nhau; ta có thể theo đuổi cả hai."},{"en":"In statistics, mutually exclusive events cannot occur together.","vi":"Trong thống kê, các sự kiện loại trừ lẫn nhau không thể xảy ra cùng lúc."},{"en":"Profit and sustainability need not be mutually exclusive aims.","vi":"Lợi nhuận và tính bền vững không nhất thiết là các mục tiêu loại trừ nhau."}]','[]',NULL,'/ˈmjuːtʃuəli ɪkˈskluːsɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4705,'colloc-10-01',65,'narrow definition','định nghĩa hẹp','adj + n','[{"en":"A narrow definition of success ignores personal happiness.","vi":"Một định nghĩa hẹp về thành công bỏ qua hạnh phúc cá nhân."},{"en":"The author rejects the narrow definition used in earlier studies.","vi":"Tác giả bác bỏ định nghĩa hẹp được dùng trong các nghiên cứu trước."},{"en":"Using a narrow definition limited the scope of the survey.","vi":"Việc dùng một định nghĩa hẹp đã giới hạn phạm vi của cuộc khảo sát."}]','[]',NULL,'/ˈnæroʊ ˌdefəˈnɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4706,'colloc-10-01',66,'narrow range of','phạm vi hẹp các','adj + n','[{"en":"The study focused on a narrow range of economic indicators.","vi":"Nghiên cứu tập trung vào một phạm vi hẹp các chỉ số kinh tế."},{"en":"The species survives only within a narrow range of temperatures.","vi":"Loài này chỉ sống được trong một phạm vi hẹp các mức nhiệt độ."},{"en":"Critics said the policy addressed a narrow range of problems.","vi":"Giới phê bình nói chính sách chỉ giải quyết một phạm vi hẹp các vấn đề."}]','[]',NULL,'/ˈnæroʊ ˈreɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4707,'colloc-10-01',67,'national average','mức trung bình toàn quốc','adj + n','[{"en":"The region''s unemployment rate is below the national average.","vi":"Tỷ lệ thất nghiệp của vùng này thấp hơn mức trung bình toàn quốc."},{"en":"Test scores at this school exceed the national average.","vi":"Điểm thi tại trường này vượt mức trung bình toàn quốc."},{"en":"House prices here remain close to the national average.","vi":"Giá nhà ở đây vẫn gần mức trung bình toàn quốc."}]','[]',NULL,'/ˈnæʃənəl ˈævərɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4708,'colloc-10-01',68,'national boundary','đường biên giới quốc gia','adj + n','[{"en":"The river forms a natural national boundary between the two states.","vi":"Con sông tạo thành một đường biên giới quốc gia tự nhiên giữa hai bang."},{"en":"Trade often flows across the national boundary without restriction.","vi":"Thương mại thường lưu thông qua biên giới quốc gia mà không bị hạn chế."},{"en":"The treaty redrew the national boundary after the long war.","vi":"Hiệp ước đã vẽ lại đường biên giới quốc gia sau cuộc chiến dài."}]','[]',NULL,'/ˈnæʃənəl ˈbaʊndəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4709,'colloc-10-01',69,'national conference','hội nghị toàn quốc','adj + n','[{"en":"She presented her research at the national conference last spring.","vi":"Cô đã trình bày nghiên cứu của mình tại hội nghị toàn quốc mùa xuân năm ngoái."},{"en":"The national conference brought together experts from every region.","vi":"Hội nghị toàn quốc quy tụ các chuyên gia từ mọi vùng miền."},{"en":"Delegates debated new policies during the national conference.","vi":"Các đại biểu tranh luận về chính sách mới trong hội nghị toàn quốc."}]','[]',NULL,'/ˈnæʃənəl ˈkɑːnfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4710,'colloc-10-01',70,'national culture','văn hóa dân tộc','adj + n','[{"en":"Food and festivals are an essential part of national culture.","vi":"Ẩm thực và lễ hội là một phần thiết yếu của văn hóa dân tộc."},{"en":"Globalization has reshaped many aspects of national culture.","vi":"Toàn cầu hóa đã định hình lại nhiều khía cạnh của văn hóa dân tộc."},{"en":"The museum aims to preserve the country''s national culture.","vi":"Bảo tàng nhằm gìn giữ văn hóa dân tộc của đất nước."}]','[]',NULL,'/ˈnæʃənəl ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4711,'colloc-10-01',71,'national economy','nền kinh tế quốc gia','adj + n','[{"en":"Tourism contributes significantly to the national economy each year.","vi":"Du lịch đóng góp đáng kể cho nền kinh tế quốc gia mỗi năm."},{"en":"The pandemic severely weakened the national economy for months.","vi":"Đại dịch đã làm suy yếu nghiêm trọng nền kinh tế quốc gia trong nhiều tháng."},{"en":"Reforms were designed to strengthen the national economy gradually.","vi":"Các cải cách được thiết kế để dần củng cố nền kinh tế quốc gia."}]','[]',NULL,'/ˈnæʃənəl ɪˈkɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4712,'colloc-10-01',72,'national government','chính phủ quốc gia','adj + n','[{"en":"The national government announced a new education funding plan.","vi":"Chính phủ quốc gia đã công bố một kế hoạch tài trợ giáo dục mới."},{"en":"Local councils often depend on the national government for money.","vi":"Hội đồng địa phương thường phụ thuộc chính phủ quốc gia về kinh phí."},{"en":"The national government set strict targets for cutting emissions.","vi":"Chính phủ quốc gia đặt ra các mục tiêu nghiêm ngặt về cắt giảm khí thải."}]','[]',NULL,'/ˈnæʃənəl ˈɡʌvərnmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4713,'colloc-10-01',73,'national identity','bản sắc dân tộc','adj + n','[{"en":"Language plays a central role in shaping national identity.","vi":"Ngôn ngữ đóng vai trò trung tâm trong việc hình thành bản sắc dân tộc."},{"en":"The flag is a powerful symbol of national identity.","vi":"Lá cờ là một biểu tượng mạnh mẽ của bản sắc dân tộc."},{"en":"Sport can strengthen a shared sense of national identity.","vi":"Thể thao có thể củng cố ý thức chung về bản sắc dân tộc."}]','[]',NULL,'/ˈnæʃənəl aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4714,'colloc-10-01',74,'national income','thu nhập quốc dân','adj + n','[{"en":"Agriculture once accounted for most of the national income.","vi":"Nông nghiệp từng chiếm phần lớn thu nhập quốc dân."},{"en":"Economists measure growth by changes in national income.","vi":"Các nhà kinh tế đo lường tăng trưởng qua thay đổi của thu nhập quốc dân."},{"en":"A rise in national income usually improves living standards.","vi":"Thu nhập quốc dân tăng thường cải thiện mức sống."}]','[]',NULL,'/ˈnæʃənəl ˈɪnkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4715,'colloc-10-01',75,'national institution','thể chế quốc gia','adj + n','[{"en":"The library has become a respected national institution over time.","vi":"Thư viện đã trở thành một thể chế quốc gia được kính trọng theo thời gian."},{"en":"Trust in every national institution has declined in recent years.","vi":"Niềm tin vào mọi thể chế quốc gia đã giảm trong những năm gần đây."},{"en":"The reform strengthened a key national institution responsible for justice.","vi":"Cải cách đã củng cố một thể chế quốc gia quan trọng phụ trách công lý."}]','[]',NULL,'/ˈnæʃənəl ˌɪnstəˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4716,'colloc-10-01',76,'national interest','lợi ích quốc gia','adj + n','[{"en":"The government justified the policy as serving the national interest.","vi":"Chính phủ biện minh chính sách này nhằm phục vụ lợi ích quốc gia."},{"en":"Leaders must weigh personal gain against the national interest.","vi":"Các nhà lãnh đạo phải cân nhắc lợi ích cá nhân với lợi ích quốc gia."},{"en":"Protecting energy supplies is clearly in the national interest.","vi":"Bảo vệ nguồn cung năng lượng rõ ràng phục vụ lợi ích quốc gia."}]','[]',NULL,'/ˈnæʃənəl ˈɪntrəst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4717,'colloc-10-01',77,'national language','ngôn ngữ quốc gia','adj + n','[{"en":"The constitution names two official forms of the national language.","vi":"Hiến pháp ghi nhận hai dạng chính thức của ngôn ngữ quốc gia."},{"en":"Schools are required to teach the national language to all pupils.","vi":"Các trường buộc phải dạy ngôn ngữ quốc gia cho mọi học sinh."},{"en":"Promoting the national language helped unite the diverse population.","vi":"Việc đề cao ngôn ngữ quốc gia đã giúp gắn kết dân cư đa dạng."}]','[]',NULL,'/ˈnæʃənəl ˈlæŋɡwɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4718,'colloc-10-01',78,'national legislation','luật pháp quốc gia','adj + n','[{"en":"New national legislation now limits the use of plastic bags.","vi":"Luật pháp quốc gia mới hiện hạn chế việc sử dụng túi nhựa."},{"en":"Local rules must comply with existing national legislation.","vi":"Quy định địa phương phải tuân thủ luật pháp quốc gia hiện hành."},{"en":"National legislation on data privacy was strengthened last year.","vi":"Luật pháp quốc gia về quyền riêng tư dữ liệu đã được siết chặt năm ngoái."}]','[]',NULL,'/ˈnæʃənəl ˌledʒəsˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4719,'colloc-10-01',79,'national market','thị trường quốc gia','adj + n','[{"en":"The company expanded from local trade into the national market.","vi":"Công ty đã mở rộng từ buôn bán địa phương sang thị trường quốc gia."},{"en":"Imports increased competition across the national market.","vi":"Hàng nhập khẩu làm tăng cạnh tranh trên khắp thị trường quốc gia."},{"en":"A single national market makes pricing more consistent everywhere.","vi":"Một thị trường quốc gia thống nhất giúp giá cả nhất quán hơn ở mọi nơi."}]','[]',NULL,'/ˈnæʃənəl ˈmɑːrkɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4720,'colloc-10-01',80,'national media','truyền thông quốc gia','adj + n','[{"en":"The scandal was widely covered by the national media.","vi":"Vụ bê bối đã được truyền thông quốc gia đưa tin rộng rãi."},{"en":"The national media shapes how citizens view current events.","vi":"Truyền thông quốc gia định hình cách công dân nhìn nhận sự kiện hiện tại."},{"en":"Her discovery soon attracted attention from the national media.","vi":"Phát hiện của cô sớm thu hút sự chú ý của truyền thông quốc gia."}]','[]',NULL,'/ˈnæʃənəl ˈmiːdiə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4721,'colloc-10-01',81,'national movement','phong trào dân tộc','adj + n','[{"en":"The protest grew into a powerful national movement for change.","vi":"Cuộc biểu tình đã phát triển thành một phong trào dân tộc mạnh mẽ đòi thay đổi."},{"en":"Historians studied how the national movement gained popular support.","vi":"Các nhà sử học nghiên cứu cách phong trào dân tộc giành được sự ủng hộ rộng rãi."},{"en":"Young activists led the national movement toward independence.","vi":"Các nhà hoạt động trẻ dẫn dắt phong trào dân tộc hướng tới độc lập."}]','[]',NULL,'/ˈnæʃənəl ˈmuːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4722,'colloc-10-01',82,'national policy','chính sách quốc gia','adj + n','[{"en":"The government introduced a new national policy on renewable energy.","vi":"Chính phủ đã ban hành một chính sách quốc gia mới về năng lượng tái tạo."},{"en":"Critics argued the national policy ignored rural communities.","vi":"Giới phê bình cho rằng chính sách quốc gia đã bỏ quên các cộng đồng nông thôn."},{"en":"A clear national policy helped coordinate the regional efforts.","vi":"Một chính sách quốc gia rõ ràng đã giúp phối hợp các nỗ lực ở các vùng."}]','[]',NULL,'/ˈnæʃənəl ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4723,'colloc-10-01',83,'national press','báo chí quốc gia','adj + n','[{"en":"The story made the front page of the national press.","vi":"Câu chuyện đã lên trang nhất của báo chí quốc gia."},{"en":"The national press criticized the minister''s recent decision.","vi":"Báo chí quốc gia đã chỉ trích quyết định gần đây của bộ trưởng."},{"en":"Local issues rarely reach the pages of the national press.","vi":"Các vấn đề địa phương hiếm khi lên được trang báo chí quốc gia."}]','[]',NULL,'/ˈnæʃənəl pres/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4724,'colloc-10-01',84,'national security','an ninh quốc gia','adj + n','[{"en":"The leak posed a serious threat to national security.","vi":"Vụ rò rỉ đã gây ra một mối đe dọa nghiêm trọng cho an ninh quốc gia."},{"en":"Officials cited national security to justify the new restrictions.","vi":"Các quan chức viện dẫn an ninh quốc gia để biện minh cho các hạn chế mới."},{"en":"Cyberattacks have become a major national security concern.","vi":"Các cuộc tấn công mạng đã trở thành mối lo lớn về an ninh quốc gia."}]','[]',NULL,'/ˈnæʃənəl sɪˈkjʊrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4725,'colloc-10-01',85,'national survey','cuộc khảo sát toàn quốc','adj + n','[{"en":"A recent national survey revealed rising levels of student stress.","vi":"Một cuộc khảo sát toàn quốc gần đây cho thấy mức độ căng thẳng của sinh viên gia tăng."},{"en":"The national survey collected responses from thousands of households.","vi":"Cuộc khảo sát toàn quốc đã thu thập câu trả lời từ hàng nghìn hộ gia đình."},{"en":"Results of the national survey will guide future health policy.","vi":"Kết quả của cuộc khảo sát toàn quốc sẽ định hướng chính sách y tế tương lai."}]','[]',NULL,'/ˈnæʃənəl ˈsɜːrveɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4726,'colloc-10-01',86,'native speaker','người bản ngữ','adj + n','[{"en":"Practicing with a native speaker improved her pronunciation quickly.","vi":"Luyện tập với một người bản ngữ đã cải thiện phát âm của cô nhanh chóng."},{"en":"A native speaker often notices subtle errors that textbooks miss.","vi":"Người bản ngữ thường nhận ra những lỗi tinh tế mà sách giáo khoa bỏ sót."},{"en":"The school hired a native speaker to lead conversation classes.","vi":"Trường đã thuê một người bản ngữ để dẫn dắt các lớp hội thoại."}]','[]',NULL,'/ˈneɪtɪv ˈspiːkər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4727,'colloc-10-01',87,'natural conditions','điều kiện tự nhiên','adj + n','[{"en":"These plants thrive only under specific natural conditions.","vi":"Những cây này chỉ phát triển tốt trong điều kiện tự nhiên cụ thể."},{"en":"Researchers observed the animals in their natural conditions.","vi":"Các nhà nghiên cứu quan sát các con vật trong điều kiện tự nhiên của chúng."},{"en":"The experiment tried to replicate the natural conditions of the lake.","vi":"Thí nghiệm cố tái tạo điều kiện tự nhiên của hồ nước."}]','[]',NULL,'/ˈnætʃərəl kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4728,'colloc-10-01',88,'natural disaster','thảm họa thiên nhiên','adj + n','[{"en":"The flood was the worst natural disaster in the region''s history.","vi":"Trận lụt là thảm họa thiên nhiên tồi tệ nhất trong lịch sử của vùng."},{"en":"Governments must prepare communities for any natural disaster.","vi":"Các chính phủ phải chuẩn bị cho cộng đồng trước mọi thảm họa thiên nhiên."},{"en":"Aid arrived slowly after the devastating natural disaster.","vi":"Viện trợ đến chậm sau thảm họa thiên nhiên tàn khốc."}]','[]',NULL,'/ˈnætʃərəl dɪˈzæstər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4729,'colloc-10-01',89,'natural environment','môi trường tự nhiên','adj + n','[{"en":"Industrial waste continues to damage the natural environment.","vi":"Chất thải công nghiệp tiếp tục hủy hoại môi trường tự nhiên."},{"en":"The park protects the natural environment for future generations.","vi":"Công viên bảo vệ môi trường tự nhiên cho các thế hệ tương lai."},{"en":"Studying animals in their natural environment yields better data.","vi":"Nghiên cứu động vật trong môi trường tự nhiên cho dữ liệu tốt hơn."}]','[]',NULL,'/ˈnætʃərəl ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4730,'colloc-10-01',90,'natural history','lịch sử tự nhiên','adj + n','[{"en":"The museum''s natural history collection attracts many young visitors.","vi":"Bộ sưu tập lịch sử tự nhiên của bảo tàng thu hút nhiều khách trẻ tuổi."},{"en":"Darwin''s voyage greatly advanced the study of natural history.","vi":"Chuyến đi của Darwin đã thúc đẩy mạnh việc nghiên cứu lịch sử tự nhiên."},{"en":"She wrote a popular book on the natural history of birds.","vi":"Cô đã viết một cuốn sách phổ biến về lịch sử tự nhiên của các loài chim."}]','[]',NULL,'/ˈnætʃərəl ˈhɪstəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4731,'colloc-10-01',91,'natural language','ngôn ngữ tự nhiên','adj + n','[{"en":"Computers still struggle to fully understand natural language.","vi":"Máy tính vẫn gặp khó khăn trong việc hiểu trọn vẹn ngôn ngữ tự nhiên."},{"en":"The app uses natural language to answer everyday questions.","vi":"Ứng dụng dùng ngôn ngữ tự nhiên để trả lời các câu hỏi hằng ngày."},{"en":"Natural language processing has improved rapidly in recent years.","vi":"Xử lý ngôn ngữ tự nhiên đã tiến bộ nhanh chóng trong những năm gần đây."}]','[]',NULL,'/ˈnætʃərəl ˈlæŋɡwɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4732,'colloc-10-01',92,'natural law','luật tự nhiên','adj + n','[{"en":"Philosophers debated whether natural law applies to all people.","vi":"Các triết gia tranh luận liệu luật tự nhiên có áp dụng cho mọi người không."},{"en":"The idea of natural law shaped early human rights theory.","vi":"Ý niệm về luật tự nhiên đã định hình lý thuyết nhân quyền sơ khai."},{"en":"He argued that justice should be grounded in natural law.","vi":"Ông lập luận rằng công lý nên được đặt trên nền tảng luật tự nhiên."}]','[]',NULL,'/ˈnætʃərəl lɔː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4733,'colloc-10-01',93,'natural order','trật tự tự nhiên','adj + n','[{"en":"Ancient thinkers believed everything followed a fixed natural order.","vi":"Các nhà tư tưởng cổ đại tin rằng mọi thứ tuân theo một trật tự tự nhiên cố định."},{"en":"The film questions whether technology disrupts the natural order.","vi":"Bộ phim đặt câu hỏi liệu công nghệ có phá vỡ trật tự tự nhiên không."},{"en":"Predators and prey maintain a delicate natural order.","vi":"Kẻ săn mồi và con mồi duy trì một trật tự tự nhiên mong manh."}]','[]',NULL,'/ˈnætʃərəl ˈɔːrdər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4734,'colloc-10-01',94,'natural philosophy','triết học tự nhiên','adj + n','[{"en":"Before modern science, physics was called natural philosophy.","vi":"Trước khoa học hiện đại, vật lý được gọi là triết học tự nhiên."},{"en":"Newton''s work transformed the field of natural philosophy.","vi":"Công trình của Newton đã biến đổi lĩnh vực triết học tự nhiên."},{"en":"The lecture traced the roots of natural philosophy in Greece.","vi":"Bài giảng đã truy nguồn gốc của triết học tự nhiên ở Hy Lạp."}]','[]',NULL,'/ˈnætʃərəl fəˈlɑːsəfi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4735,'colloc-10-01',95,'natural process','quá trình tự nhiên','adj + n','[{"en":"Decay is a natural process that recycles nutrients in soil.","vi":"Phân hủy là một quá trình tự nhiên tái chế dưỡng chất trong đất."},{"en":"Aging is a natural process that affects every living thing.","vi":"Lão hóa là một quá trình tự nhiên ảnh hưởng đến mọi sinh vật."},{"en":"The river changes course through a slow natural process.","vi":"Dòng sông đổi dòng qua một quá trình tự nhiên chậm rãi."}]','[]',NULL,'/ˈnætʃərəl ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4736,'colloc-10-01',96,'natural resources','tài nguyên thiên nhiên','adj + n','[{"en":"The country is rich in natural resources such as oil and gas.","vi":"Đất nước này giàu tài nguyên thiên nhiên như dầu mỏ và khí đốt."},{"en":"Overuse of natural resources threatens long-term sustainability.","vi":"Việc khai thác quá mức tài nguyên thiên nhiên đe dọa tính bền vững lâu dài."},{"en":"The treaty aims to manage shared natural resources fairly.","vi":"Hiệp ước nhằm quản lý công bằng các tài nguyên thiên nhiên chung."}]','[]',NULL,'/ˈnætʃərəl ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4737,'colloc-10-01',97,'natural right','quyền tự nhiên','adj + n','[{"en":"Many thinkers regard freedom as a basic natural right.","vi":"Nhiều nhà tư tưởng coi tự do là một quyền tự nhiên căn bản."},{"en":"The declaration was based on the idea of natural right.","vi":"Bản tuyên ngôn dựa trên ý niệm về quyền tự nhiên."},{"en":"He argued that property is not an absolute natural right.","vi":"Ông lập luận rằng tài sản không phải là một quyền tự nhiên tuyệt đối."}]','[]',NULL,'/ˈnætʃərəl raɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4738,'colloc-10-01',98,'natural science','khoa học tự nhiên','adj + n','[{"en":"She decided to major in a natural science at university.","vi":"Cô đã quyết định chọn ngành chính là một môn khoa học tự nhiên ở đại học."},{"en":"Natural science relies heavily on observation and experiment.","vi":"Khoa học tự nhiên phụ thuộc nhiều vào quan sát và thí nghiệm."},{"en":"The grant supports research across several natural science fields.","vi":"Khoản tài trợ hỗ trợ nghiên cứu trên nhiều lĩnh vực khoa học tự nhiên."}]','[]',NULL,'/ˈnætʃərəl ˈsaɪəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4739,'colloc-10-01',99,'natural tendency','khuynh hướng tự nhiên','adj + n','[{"en":"People have a natural tendency to trust familiar faces.","vi":"Con người có một khuynh hướng tự nhiên là tin những gương mặt quen thuộc."},{"en":"The market shows a natural tendency to correct over time.","vi":"Thị trường cho thấy một khuynh hướng tự nhiên là tự điều chỉnh theo thời gian."},{"en":"Children display a natural tendency to imitate adults.","vi":"Trẻ em thể hiện một khuynh hướng tự nhiên là bắt chước người lớn."}]','[]',NULL,'/ˈnætʃərəl ˈtendənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4740,'colloc-10-01',100,'natural world','thế giới tự nhiên','adj + n','[{"en":"Her photographs capture the beauty of the natural world.","vi":"Những bức ảnh của cô ghi lại vẻ đẹp của thế giới tự nhiên."},{"en":"Science helps us understand patterns in the natural world.","vi":"Khoa học giúp chúng ta hiểu các quy luật trong thế giới tự nhiên."},{"en":"Children should spend more time exploring the natural world.","vi":"Trẻ em nên dành nhiều thời gian hơn để khám phá thế giới tự nhiên."}]','[]',NULL,'/ˈnætʃərəl wɜːrld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4741,'colloc-10-01',101,'naturally occurring','xuất hiện tự nhiên','adv + adj','[{"en":"Vitamin D is a naturally occurring substance in sunlight.","vi":"Vitamin D là một chất xuất hiện tự nhiên trong ánh nắng mặt trời."},{"en":"The study focused on naturally occurring chemicals in plants.","vi":"Nghiên cứu tập trung vào các hóa chất xuất hiện tự nhiên trong thực vật."},{"en":"Some naturally occurring minerals are mined for industrial use.","vi":"Một số khoáng chất xuất hiện tự nhiên được khai thác cho mục đích công nghiệp."}]','[]',NULL,'/ˈnætʃərəli əˈkɜːrɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4742,'colloc-10-01',102,'necessary information','thông tin cần thiết','adj + n','[{"en":"Please gather all the necessary information before the meeting.","vi":"Vui lòng thu thập tất cả thông tin cần thiết trước cuộc họp."},{"en":"The form requests only the necessary information from applicants.","vi":"Biểu mẫu chỉ yêu cầu thông tin cần thiết từ người nộp đơn."},{"en":"Without the necessary information, we cannot make a decision.","vi":"Thiếu thông tin cần thiết, chúng ta không thể đưa ra quyết định."}]','[]',NULL,'/ˈnesəseri ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4743,'colloc-10-01',103,'negative aspect','khía cạnh tiêu cực','adj + n','[{"en":"The essay discusses one negative aspect of social media use.","vi":"Bài luận bàn về một khía cạnh tiêu cực của việc dùng mạng xã hội."},{"en":"Every technology has a negative aspect worth considering.","vi":"Mọi công nghệ đều có một khía cạnh tiêu cực đáng cân nhắc."},{"en":"She acknowledged the negative aspect of working long hours.","vi":"Cô thừa nhận khía cạnh tiêu cực của việc làm việc nhiều giờ."}]','[]',NULL,'/ˈneɡətɪv ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4744,'colloc-10-01',104,'negative attitude','thái độ tiêu cực','adj + n','[{"en":"His negative attitude discouraged the rest of the team.","vi":"Thái độ tiêu cực của anh đã làm nản lòng cả đội."},{"en":"The survey measured students'' negative attitude toward exams.","vi":"Cuộc khảo sát đo lường thái độ tiêu cực của sinh viên với kỳ thi."},{"en":"A negative attitude can make small problems seem huge.","vi":"Thái độ tiêu cực có thể khiến vấn đề nhỏ trở nên to lớn."}]','[]',NULL,'/ˈneɡətɪv ˈætətuːd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4745,'colloc-10-01',105,'negative connotation','hàm ý tiêu cực','adj + n','[{"en":"The word \"cheap\" often carries a negative connotation.","vi":"Từ \"rẻ tiền\" thường mang một hàm ý tiêu cực."},{"en":"Writers should avoid terms with a strong negative connotation.","vi":"Người viết nên tránh những từ có hàm ý tiêu cực mạnh."},{"en":"In some cultures the label has a negative connotation.","vi":"Ở một số nền văn hóa, nhãn này mang hàm ý tiêu cực."}]','[]',NULL,'/ˈneɡətɪv ˌkɑːnəˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4746,'colloc-10-01',106,'negative consequences','hậu quả tiêu cực','adj + n','[{"en":"The policy had several negative consequences for small businesses.","vi":"Chính sách đã gây ra nhiều hậu quả tiêu cực cho doanh nghiệp nhỏ."},{"en":"Skipping sleep regularly leads to serious negative consequences.","vi":"Thường xuyên thiếu ngủ dẫn đến những hậu quả tiêu cực nghiêm trọng."},{"en":"Researchers warned about the negative consequences of pollution.","vi":"Các nhà nghiên cứu cảnh báo về hậu quả tiêu cực của ô nhiễm."}]','[]',NULL,'/ˈneɡətɪv ˈkɑːnsəkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4747,'colloc-10-01',107,'negative correlation','mối tương quan nghịch','adj + n','[{"en":"The data showed a negative correlation between stress and sleep.","vi":"Dữ liệu cho thấy mối tương quan nghịch giữa căng thẳng và giấc ngủ."},{"en":"There is a clear negative correlation between price and demand.","vi":"Có một mối tương quan nghịch rõ ràng giữa giá cả và nhu cầu."},{"en":"A negative correlation means one variable rises as another falls.","vi":"Mối tương quan nghịch nghĩa là một biến tăng khi biến kia giảm."}]','[]',NULL,'/ˈneɡətɪv ˌkɔːrəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4748,'colloc-10-01',108,'negative effect','tác động tiêu cực','adj + n','[{"en":"Excessive screen time can have a negative effect on sleep.","vi":"Thời gian dùng màn hình quá mức có thể gây tác động tiêu cực đến giấc ngủ."},{"en":"The drought had a negative effect on this year''s harvest.","vi":"Hạn hán đã gây tác động tiêu cực đến vụ mùa năm nay."},{"en":"Noise pollution has a negative effect on concentration.","vi":"Ô nhiễm tiếng ồn có tác động tiêu cực đến sự tập trung."}]','[]',NULL,'/ˈneɡətɪv ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4749,'colloc-10-01',109,'negative feedback','phản hồi tiêu cực','adj + n','[{"en":"She handled the negative feedback calmly and improved her work.","vi":"Cô đón nhận phản hồi tiêu cực một cách bình tĩnh và cải thiện công việc."},{"en":"Constructive negative feedback can help students grow faster.","vi":"Phản hồi tiêu cực mang tính xây dựng có thể giúp sinh viên tiến bộ nhanh hơn."},{"en":"The product received negative feedback from early reviewers.","vi":"Sản phẩm nhận phản hồi tiêu cực từ những người đánh giá ban đầu."}]','[]',NULL,'/ˈneɡətɪv ˈfiːdbæk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4750,'colloc-10-01',110,'negative impact','ảnh hưởng tiêu cực','adj + n','[{"en":"Tourism can have a negative impact on fragile ecosystems.","vi":"Du lịch có thể gây ảnh hưởng tiêu cực đến các hệ sinh thái mong manh."},{"en":"The new tax had a negative impact on consumer spending.","vi":"Thuế mới đã gây ảnh hưởng tiêu cực đến chi tiêu của người tiêu dùng."},{"en":"Researchers measured the negative impact of stress on health.","vi":"Các nhà nghiên cứu đo lường ảnh hưởng tiêu cực của căng thẳng đến sức khỏe."}]','[]',NULL,'/ˈneɡətɪv ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4751,'colloc-10-01',111,'negative outcome','kết quả tiêu cực','adj + n','[{"en":"Poor planning often leads to a negative outcome for projects.","vi":"Lập kế hoạch kém thường dẫn đến một kết quả tiêu cực cho các dự án."},{"en":"The trial produced a surprisingly negative outcome for patients.","vi":"Thử nghiệm đã cho một kết quả tiêu cực đáng ngạc nhiên với bệnh nhân."},{"en":"We must prepare for any negative outcome of the negotiations.","vi":"Chúng ta phải chuẩn bị cho bất kỳ kết quả tiêu cực nào của cuộc đàm phán."}]','[]',NULL,'/ˈneɡətɪv ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4752,'colloc-10-01',112,'negative side','mặt tiêu cực','adj + n','[{"en":"Every opportunity has a negative side worth weighing carefully.","vi":"Mọi cơ hội đều có một mặt tiêu cực đáng cân nhắc kỹ."},{"en":"The article highlights the negative side of rapid urban growth.","vi":"Bài viết làm nổi bật mặt tiêu cực của tăng trưởng đô thị nhanh."},{"en":"On the negative side, the plan is extremely expensive.","vi":"Về mặt tiêu cực, kế hoạch này cực kỳ tốn kém."}]','[]',NULL,'/ˈneɡətɪv saɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4753,'colloc-10-01',113,'negative stereotype','định kiến tiêu cực','adj + n','[{"en":"The campaign aims to challenge a common negative stereotype.","vi":"Chiến dịch nhằm thách thức một định kiến tiêu cực phổ biến."},{"en":"Media often reinforces a negative stereotype about teenagers.","vi":"Truyền thông thường củng cố một định kiến tiêu cực về thanh thiếu niên."},{"en":"Education can help break down each negative stereotype slowly.","vi":"Giáo dục có thể giúp dần phá bỏ từng định kiến tiêu cực."}]','[]',NULL,'/ˈneɡətɪv ˈsteriətaɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4754,'colloc-10-01',114,'negative value','giá trị âm','adj + n','[{"en":"A negative value in the equation indicates a loss.","vi":"Một giá trị âm trong phương trình cho thấy một khoản lỗ."},{"en":"The sensor returned a negative value due to a calibration error.","vi":"Cảm biến trả về một giá trị âm do lỗi hiệu chuẩn."},{"en":"Temperatures fell to a negative value overnight.","vi":"Nhiệt độ đã giảm xuống một giá trị âm qua đêm."}]','[]',NULL,'/ˈneɡətɪv ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4755,'colloc-10-01',115,'negative view','cái nhìn tiêu cực','adj + n','[{"en":"The author takes a negative view of unregulated markets.","vi":"Tác giả có một cái nhìn tiêu cực về các thị trường không được quản lý."},{"en":"Many residents hold a negative view of the proposed development.","vi":"Nhiều cư dân có cái nhìn tiêu cực về dự án phát triển được đề xuất."},{"en":"Her negative view of the plan changed after the presentation.","vi":"Cái nhìn tiêu cực của cô về kế hoạch đã thay đổi sau buổi thuyết trình."}]','[]',NULL,'/ˈneɡətɪv vjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4756,'colloc-10-01',116,'negatively correlated with','tương quan nghịch với','adv + vpp','[{"en":"Anxiety levels were negatively correlated with exam performance.","vi":"Mức độ lo âu có tương quan nghịch với kết quả thi."},{"en":"Income is often negatively correlated with reported stress.","vi":"Thu nhập thường có tương quan nghịch với mức căng thẳng được ghi nhận."},{"en":"Screen time was negatively correlated with hours of sleep.","vi":"Thời gian dùng màn hình có tương quan nghịch với số giờ ngủ."}]','[]',NULL,'/ˈneɡətɪvli ˈkɔːrəleɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4757,'colloc-10-01',117,'new initiative','sáng kiến mới','adj + n','[{"en":"The school launched a new initiative to reduce food waste.","vi":"Nhà trường đã khởi động một sáng kiến mới để giảm lãng phí thực phẩm."},{"en":"The new initiative encourages employees to share fresh ideas.","vi":"Sáng kiến mới khuyến khích nhân viên chia sẻ những ý tưởng mới mẻ."},{"en":"Funding was secured for a new initiative on clean energy.","vi":"Kinh phí đã được bảo đảm cho một sáng kiến mới về năng lượng sạch."}]','[]',NULL,'/nuː ɪˈnɪʃətɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4758,'colloc-10-01',118,'new insight','hiểu biết sâu sắc mới','adj + n','[{"en":"The experiment offered a new insight into how memory works.","vi":"Thí nghiệm đã mang lại một hiểu biết sâu sắc mới về cách trí nhớ hoạt động."},{"en":"Her interviews provided a new insight into rural poverty.","vi":"Các cuộc phỏng vấn của cô đã cho một góc nhìn sâu sắc mới về nghèo đói nông thôn."},{"en":"The data gave researchers a new insight into climate change.","vi":"Dữ liệu đã cho các nhà nghiên cứu một hiểu biết mới về biến đổi khí hậu."}]','[]',NULL,'/nuː ˈɪnsaɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4759,'colloc-10-01',119,'new perspective','góc nhìn mới','adj + n','[{"en":"Traveling abroad gave her a completely new perspective on life.","vi":"Đi du lịch nước ngoài đã cho cô một góc nhìn hoàn toàn mới về cuộc sống."},{"en":"The book offers a new perspective on a familiar problem.","vi":"Cuốn sách mang đến một góc nhìn mới về một vấn đề quen thuộc."},{"en":"Hearing other students brought a new perspective to the debate.","vi":"Lắng nghe các sinh viên khác đã mang một góc nhìn mới vào cuộc tranh luận."}]','[]',NULL,'/nuː pərˈspektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4760,'colloc-10-01',120,'newly acquired','vừa mới có được','adv + vpp','[{"en":"She used her newly acquired skills to redesign the website.","vi":"Cô đã dùng những kỹ năng vừa mới có được để thiết kế lại trang web."},{"en":"The museum displayed its newly acquired ancient artifacts.","vi":"Bảo tàng đã trưng bày các cổ vật vừa mới có được."},{"en":"He applied his newly acquired knowledge during the internship.","vi":"Anh áp dụng kiến thức vừa mới có được trong kỳ thực tập."}]','[]',NULL,'/ˈnuːli əˈkwaɪərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4761,'colloc-10-01',121,'newly created','vừa mới được tạo ra','adv + vpp','[{"en":"The newly created department will oversee online learning.","vi":"Phòng ban vừa mới được tạo ra sẽ giám sát việc học trực tuyến."},{"en":"She was appointed to a newly created leadership position.","vi":"Cô được bổ nhiệm vào một vị trí lãnh đạo vừa mới được tạo ra."},{"en":"The newly created fund supports young local entrepreneurs.","vi":"Quỹ vừa mới được tạo ra hỗ trợ các doanh nhân địa phương trẻ tuổi."}]','[]',NULL,'/ˈnuːli kriˈeɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4762,'colloc-10-01',122,'newly discovered','vừa mới được phát hiện','adv + vpp','[{"en":"Scientists named the newly discovered species after its habitat.","vi":"Các nhà khoa học đặt tên loài vừa mới được phát hiện theo môi trường sống của nó."},{"en":"The newly discovered manuscript changed how we read the poem.","vi":"Bản thảo vừa mới được phát hiện đã thay đổi cách chúng ta đọc bài thơ."},{"en":"A newly discovered planet may have conditions suited to life.","vi":"Một hành tinh vừa mới được phát hiện có thể có điều kiện phù hợp cho sự sống."}]','[]',NULL,'/ˈnuːli dɪˈskʌvərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4763,'colloc-10-01',123,'newly emerging','vừa mới nổi lên','adv + adj','[{"en":"The report examines several newly emerging digital technologies.","vi":"Báo cáo xem xét một số công nghệ số vừa mới nổi lên."},{"en":"Investors are watching the newly emerging green energy sector.","vi":"Các nhà đầu tư đang theo dõi ngành năng lượng xanh vừa mới nổi lên."},{"en":"Newly emerging markets offer both risks and opportunities.","vi":"Các thị trường vừa mới nổi lên mang lại cả rủi ro lẫn cơ hội."}]','[]',NULL,'/ˈnuːli ɪˈmɜːrdʒɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4764,'colloc-10-01',124,'newly established','vừa mới được thành lập','adv + adj','[{"en":"The newly established institute focuses on climate research.","vi":"Viện vừa mới được thành lập tập trung vào nghiên cứu khí hậu."},{"en":"A newly established committee will review the proposals.","vi":"Một ủy ban vừa mới được thành lập sẽ xem xét các đề xuất."},{"en":"The newly established company hired dozens of graduates.","vi":"Công ty vừa mới được thành lập đã tuyển hàng chục sinh viên tốt nghiệp."}]','[]',NULL,'/ˈnuːli ɪˈstæblɪʃt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4765,'colloc-10-01',125,'newly formed','vừa mới được hình thành','adv + vpp','[{"en":"The newly formed alliance promised closer economic cooperation.","vi":"Liên minh vừa mới được hình thành đã hứa hẹn hợp tác kinh tế chặt chẽ hơn."},{"en":"A newly formed group of volunteers cleaned up the riverbank.","vi":"Một nhóm tình nguyện viên vừa mới được hình thành đã dọn sạch bờ sông."},{"en":"Stars are born within newly formed clouds of cosmic gas.","vi":"Các ngôi sao ra đời bên trong những đám khí vũ trụ vừa mới được hình thành."}]','[]',NULL,'/ˈnuːli fɔːrmd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4766,'colloc-10-01',126,'next decade','thập kỷ tới','adj + n','[{"en":"Experts predict major changes in transport over the next decade.","vi":"Các chuyên gia dự đoán những thay đổi lớn về giao thông trong thập kỷ tới."},{"en":"The company plans to double its workforce in the next decade.","vi":"Công ty dự định tăng gấp đôi lực lượng lao động trong thập kỷ tới."},{"en":"Renewable energy should dominate the market within the next decade.","vi":"Năng lượng tái tạo sẽ chiếm lĩnh thị trường trong thập kỷ tới."}]','[]',NULL,'/nekst ˈdekeɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4767,'colloc-10-01',127,'next generation','thế hệ tiếp theo','adj + n','[{"en":"We must protect the environment for the next generation.","vi":"Chúng ta phải bảo vệ môi trường cho thế hệ tiếp theo."},{"en":"The school inspires the next generation of young scientists.","vi":"Ngôi trường truyền cảm hứng cho thế hệ nhà khoa học trẻ tiếp theo."},{"en":"These devices represent the next generation of mobile technology.","vi":"Những thiết bị này đại diện cho thế hệ công nghệ di động tiếp theo."}]','[]',NULL,'/nekst ˌdʒenəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4768,'colloc-10-01',128,'next phase','giai đoạn tiếp theo','adj + n','[{"en":"The project will enter its next phase early next year.","vi":"Dự án sẽ bước vào giai đoạn tiếp theo vào đầu năm sau."},{"en":"The next phase of research focuses on long-term effects.","vi":"Giai đoạn nghiên cứu tiếp theo tập trung vào các tác động lâu dài."},{"en":"Funding will determine whether the next phase goes ahead.","vi":"Kinh phí sẽ quyết định liệu giai đoạn tiếp theo có được tiến hành không."}]','[]',NULL,'/nekst feɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4769,'colloc-10-01',129,'normal conditions','điều kiện bình thường','adj + n','[{"en":"Under normal conditions, the machine runs without any problems.","vi":"Trong điều kiện bình thường, máy chạy mà không có vấn đề gì."},{"en":"The reaction proceeds slowly under normal conditions.","vi":"Phản ứng diễn ra chậm trong điều kiện bình thường."},{"en":"Service usually resumes within hours under normal conditions.","vi":"Dịch vụ thường được khôi phục trong vài giờ ở điều kiện bình thường."}]','[]',NULL,'/ˈnɔːrməl kənˈdɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4770,'colloc-10-01',130,'normal development','sự phát triển bình thường','adj + n','[{"en":"Good nutrition is essential for a child''s normal development.","vi":"Dinh dưỡng tốt là điều thiết yếu cho sự phát triển bình thường của trẻ."},{"en":"The study tracks the normal development of language in infants.","vi":"Nghiên cứu theo dõi sự phát triển bình thường của ngôn ngữ ở trẻ sơ sinh."},{"en":"Stress can interfere with the normal development of the brain.","vi":"Căng thẳng có thể cản trở sự phát triển bình thường của não bộ."}]','[]',NULL,'/ˈnɔːrməl dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4771,'colloc-10-01',131,'normal distribution','phân phối chuẩn','adj + n','[{"en":"The test scores followed a clear normal distribution.","vi":"Điểm thi tuân theo một phân phối chuẩn rõ ràng."},{"en":"A normal distribution is symmetric around its mean value.","vi":"Phân phối chuẩn đối xứng quanh giá trị trung bình của nó."},{"en":"Many statistical methods assume an underlying normal distribution.","vi":"Nhiều phương pháp thống kê giả định một phân phối chuẩn cơ bản."}]','[]',NULL,'/ˈnɔːrməl ˌdɪstrəˈbjuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4772,'colloc-10-01',132,'normal practice','thông lệ thường thấy','adj + n','[{"en":"It is normal practice to cite all of your sources.","vi":"Việc trích dẫn mọi nguồn của bạn là một thông lệ thường thấy."},{"en":"Reviewing the budget monthly is normal practice in this firm.","vi":"Rà soát ngân sách hằng tháng là thông lệ thường thấy ở công ty này."},{"en":"It became normal practice to back up files every night.","vi":"Việc sao lưu tệp mỗi đêm đã trở thành thông lệ thường thấy."}]','[]',NULL,'/ˈnɔːrməl ˈpræktɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4773,'colloc-10-01',133,'notable exception','ngoại lệ đáng chú ý','adj + n','[{"en":"Most students passed, with one notable exception in the group.","vi":"Hầu hết sinh viên đều đậu, với một ngoại lệ đáng chú ý trong nhóm."},{"en":"Prices rose everywhere, with food being a notable exception.","vi":"Giá cả tăng ở khắp nơi, với thực phẩm là một ngoại lệ đáng chú ý."},{"en":"Few authors of that era, with one notable exception, survive today.","vi":"Ít tác giả thời đó, trừ một ngoại lệ đáng chú ý, còn được biết đến ngày nay."}]','[]',NULL,'/ˈnoʊtəbəl ɪkˈsepʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4774,'colloc-10-01',134,'nuclear energy','năng lượng hạt nhân','adj + n','[{"en":"Some countries rely heavily on nuclear energy for electricity.","vi":"Một số quốc gia phụ thuộc nhiều vào năng lượng hạt nhân để sản xuất điện."},{"en":"Debates about nuclear energy focus on safety and waste.","vi":"Các cuộc tranh luận về năng lượng hạt nhân tập trung vào an toàn và chất thải."},{"en":"Nuclear energy produces very low carbon emissions overall.","vi":"Năng lượng hạt nhân tạo ra lượng khí thải carbon rất thấp về tổng thể."}]','[]',NULL,'/ˈnuːkliər ˈenərdʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4775,'colloc-10-01',135,'nuclear family','gia đình hạt nhân (cha mẹ và con cái)','adj + n','[{"en":"The nuclear family has become less common in modern societies.","vi":"Gia đình hạt nhân đã trở nên ít phổ biến hơn trong xã hội hiện đại."},{"en":"Her research compares the nuclear family across different cultures.","vi":"Nghiên cứu của cô so sánh gia đình hạt nhân giữa các nền văn hóa khác nhau."},{"en":"Many policies were designed around the traditional nuclear family.","vi":"Nhiều chính sách được thiết kế xoay quanh gia đình hạt nhân truyền thống."}]','[]',NULL,'/ˈnuːkliər ˈfæməli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4776,'colloc-10-01',136,'nuclear power','năng lượng hạt nhân','adj + n','[{"en":"Several countries rely on nuclear power for their electricity.","vi":"Một số quốc gia dựa vào năng lượng hạt nhân để cung cấp điện."},{"en":"The debate over nuclear power remains highly controversial today.","vi":"Cuộc tranh luận về năng lượng hạt nhân vẫn rất gây tranh cãi ngày nay."},{"en":"Nuclear power produces large amounts of energy without burning fuel.","vi":"Năng lượng hạt nhân tạo ra lượng năng lượng lớn mà không đốt nhiên liệu."}]','[]',NULL,'/ˈnuːkliər ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4777,'colloc-10-01',137,'nuclear war','chiến tranh hạt nhân','adj + n','[{"en":"The threat of nuclear war shaped global politics for decades.","vi":"Mối đe dọa chiến tranh hạt nhân đã định hình chính trị toàn cầu suốt nhiều thập kỷ."},{"en":"Many leaders have worked to reduce the risk of nuclear war.","vi":"Nhiều nhà lãnh đạo đã nỗ lực giảm nguy cơ chiến tranh hạt nhân."},{"en":"A nuclear war would have catastrophic consequences for the planet.","vi":"Một cuộc chiến tranh hạt nhân sẽ gây hậu quả thảm khốc cho hành tinh."}]','[]',NULL,'/ˈnuːkliər wɔːr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4778,'colloc-10-01',138,'nuclear weapon','vũ khí hạt nhân','adj + n','[{"en":"International treaties aim to limit the spread of nuclear weapons.","vi":"Các hiệp ước quốc tế nhằm hạn chế sự phổ biến của vũ khí hạt nhân."},{"en":"Building a nuclear weapon requires highly enriched radioactive material.","vi":"Chế tạo một vũ khí hạt nhân đòi hỏi vật liệu phóng xạ được làm giàu cao."},{"en":"The country agreed to dismantle its nuclear weapons program.","vi":"Quốc gia này đồng ý dỡ bỏ chương trình vũ khí hạt nhân của mình."}]','[]',NULL,'/ˈnuːkliər ˈwepən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4779,'colloc-10-01',139,'numerical data','dữ liệu dạng số','adj + n','[{"en":"The study relies on numerical data collected from many sources.","vi":"Nghiên cứu dựa vào dữ liệu dạng số được thu thập từ nhiều nguồn."},{"en":"Researchers analyzed the numerical data using statistical software.","vi":"Các nhà nghiên cứu phân tích dữ liệu dạng số bằng phần mềm thống kê."},{"en":"Numerical data can be displayed clearly in charts and tables.","vi":"Dữ liệu dạng số có thể được trình bày rõ ràng trong biểu đồ và bảng."}]','[]',NULL,'/nuːˈmerɪkəl ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4780,'colloc-10-01',140,'numerical value','giá trị bằng số','adj + n','[{"en":"Each variable was assigned a specific numerical value in the model.","vi":"Mỗi biến số được gán một giá trị bằng số cụ thể trong mô hình."},{"en":"The numerical value of the result depends on the measurement units.","vi":"Giá trị bằng số của kết quả phụ thuộc vào đơn vị đo lường."},{"en":"Converting the data into numerical values made comparison much easier.","vi":"Việc chuyển dữ liệu thành các giá trị bằng số giúp so sánh dễ hơn nhiều."}]','[]',NULL,'/nuːˈmerɪkəl ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4781,'colloc-10-01',141,'numerous studies','nhiều nghiên cứu','adj + n','[{"en":"Numerous studies have confirmed the link between diet and health.","vi":"Nhiều nghiên cứu đã xác nhận mối liên hệ giữa chế độ ăn và sức khỏe."},{"en":"Her conclusion is supported by numerous studies across the field.","vi":"Kết luận của cô được hỗ trợ bởi nhiều nghiên cứu trong lĩnh vực này."},{"en":"Numerous studies suggest that sleep improves memory and learning.","vi":"Nhiều nghiên cứu cho thấy giấc ngủ cải thiện trí nhớ và việc học."}]','[]',NULL,'/ˈnuːmərəs ˈstʌdiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4782,'colloc-10-01',142,'objective criteria','tiêu chí khách quan','adj + n','[{"en":"Applicants are evaluated using clear and objective criteria.","vi":"Các ứng viên được đánh giá bằng tiêu chí rõ ràng và khách quan."},{"en":"Objective criteria help reduce bias in the selection process.","vi":"Tiêu chí khách quan giúp giảm thiên kiến trong quá trình tuyển chọn."},{"en":"The committee agreed on objective criteria before reviewing the cases.","vi":"Hội đồng thống nhất các tiêu chí khách quan trước khi xem xét các hồ sơ."}]','[]',NULL,'/əbˈdʒektɪv kraɪˈtɪriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4783,'colloc-10-01',143,'objective reality','thực tại khách quan','adj + n','[{"en":"Philosophers debate whether we can truly know objective reality.","vi":"Các triết gia tranh luận liệu ta có thể thực sự biết thực tại khách quan."},{"en":"Science aims to describe objective reality independent of opinion.","vi":"Khoa học nhằm mô tả thực tại khách quan độc lập với quan điểm cá nhân."},{"en":"Our perceptions sometimes differ from objective reality itself.","vi":"Nhận thức của chúng ta đôi khi khác với chính thực tại khách quan."}]','[]',NULL,'/əbˈdʒektɪv riˈæləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4784,'colloc-10-01',144,'obtain data','thu thập dữ liệu','v + n','[{"en":"Researchers obtained data through surveys and direct observation.","vi":"Các nhà nghiên cứu thu thập dữ liệu qua khảo sát và quan sát trực tiếp."},{"en":"It was difficult to obtain reliable data from remote regions.","vi":"Rất khó để thu thập dữ liệu đáng tin cậy từ các vùng xa xôi."},{"en":"The team obtained data on weather patterns over several years.","vi":"Nhóm đã thu thập dữ liệu về các kiểu thời tiết trong nhiều năm."}]','[]',NULL,'/əbˈteɪn ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4785,'colloc-10-01',145,'obtain information','thu thập thông tin','v + n','[{"en":"Students learned how to obtain information from reliable sources.","vi":"Sinh viên học cách thu thập thông tin từ các nguồn đáng tin cậy."},{"en":"The journalist struggled to obtain information about the closed case.","vi":"Nhà báo gặp khó khăn khi thu thập thông tin về vụ án đã khép lại."},{"en":"You can obtain information about the course on the website.","vi":"Bạn có thể thu thập thông tin về khóa học trên trang web."}]','[]',NULL,'/əbˈteɪn ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4786,'colloc-10-01',146,'obtain a result','đạt được một kết quả','v + n','[{"en":"The scientists repeated the experiment to obtain a reliable result.","vi":"Các nhà khoa học lặp lại thí nghiệm để đạt được một kết quả đáng tin cậy."},{"en":"We obtained a result that closely matched our initial prediction.","vi":"Chúng tôi đạt được một kết quả khớp chặt với dự đoán ban đầu."},{"en":"To obtain a clear result, they controlled every variable carefully.","vi":"Để đạt được một kết quả rõ ràng, họ kiểm soát cẩn thận mọi biến số."}]','[]',NULL,'/əbˈteɪn ə rɪˈzʌlt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4787,'colloc-10-01',147,'obvious difference','sự khác biệt rõ ràng','adj + n','[{"en":"There is an obvious difference between the two writing styles.","vi":"Có một sự khác biệt rõ ràng giữa hai phong cách viết."},{"en":"The results showed an obvious difference between the test groups.","vi":"Kết quả cho thấy một sự khác biệt rõ ràng giữa các nhóm thử nghiệm."},{"en":"Despite the obvious difference, both methods reached similar conclusions.","vi":"Bất chấp sự khác biệt rõ ràng, cả hai phương pháp đều đi đến kết luận tương tự."}]','[]',NULL,'/ˈɑːbviəs ˈdɪfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4788,'colloc-10-01',148,'obvious example','ví dụ rõ ràng','adj + n','[{"en":"Social media is an obvious example of rapid technological change.","vi":"Mạng xã hội là một ví dụ rõ ràng về sự thay đổi công nghệ nhanh chóng."},{"en":"The author gives an obvious example to illustrate her point.","vi":"Tác giả đưa ra một ví dụ rõ ràng để minh họa cho luận điểm của mình."},{"en":"An obvious example of this trend can be seen in cities.","vi":"Một ví dụ rõ ràng cho xu hướng này có thể thấy ở các thành phố."}]','[]',NULL,'/ˈɑːbviəs ɪɡˈzæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4789,'colloc-10-01',149,'obvious point','điểm hiển nhiên','adj + n','[{"en":"She made the obvious point that more funding was needed.","vi":"Cô nêu ra điểm hiển nhiên rằng cần thêm kinh phí."},{"en":"It may seem an obvious point, but it deserves emphasis.","vi":"Điều này có vẻ là một điểm hiển nhiên, nhưng nó đáng được nhấn mạnh."},{"en":"The lecturer began with an obvious point before deeper analysis.","vi":"Giảng viên bắt đầu bằng một điểm hiển nhiên trước khi phân tích sâu hơn."}]','[]',NULL,'/ˈɑːbviəs pɔɪnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4790,'colloc-10-01',150,'obvious reason','lý do hiển nhiên','adj + n','[{"en":"For obvious reasons, the names of participants were kept private.","vi":"Vì những lý do hiển nhiên, tên của những người tham gia được giữ kín."},{"en":"There is no obvious reason why the experiment failed.","vi":"Không có lý do hiển nhiên nào giải thích vì sao thí nghiệm thất bại."},{"en":"She left the meeting early for an obvious reason.","vi":"Cô rời cuộc họp sớm vì một lý do hiển nhiên."}]','[]',NULL,'/ˈɑːbviəs ˈriːzən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4791,'colloc-11-01',1,'occur frequently','xảy ra thường xuyên','v + adv','[{"en":"Such errors occur frequently when data is entered by hand.","vi":"Những lỗi như vậy xảy ra thường xuyên khi dữ liệu được nhập bằng tay."},{"en":"Earthquakes occur frequently along this active fault line.","vi":"Động đất xảy ra thường xuyên dọc theo đường đứt gãy hoạt động này."},{"en":"These misunderstandings occur frequently in cross-cultural communication.","vi":"Những hiểu lầm này xảy ra thường xuyên trong giao tiếp đa văn hóa."}]','[]',NULL,'/əˈkɜːr ˈfriːkwəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4792,'colloc-11-01',2,'occur naturally','xảy ra một cách tự nhiên','v + adv','[{"en":"These minerals occur naturally in the surrounding rock formations.","vi":"Những khoáng chất này xuất hiện tự nhiên trong các thành tạo đá xung quanh."},{"en":"Some chemical reactions occur naturally without any human intervention.","vi":"Một số phản ứng hóa học xảy ra tự nhiên mà không cần con người can thiệp."},{"en":"Variation occurs naturally within every large population of organisms.","vi":"Sự biến dị xảy ra tự nhiên trong mọi quần thể sinh vật lớn."}]','[]',NULL,'/əˈkɜːr ˈnætʃərəli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4793,'colloc-11-01',3,'offer insight into','đem lại hiểu biết sâu sắc về','v + n','[{"en":"The interviews offer insight into how patients experience treatment.","vi":"Các cuộc phỏng vấn đem lại hiểu biết sâu sắc về cách bệnh nhân trải nghiệm điều trị."},{"en":"Her diary offers insight into daily life during the war.","vi":"Nhật ký của cô đem lại hiểu biết sâu sắc về đời sống thường ngày trong chiến tranh."},{"en":"These findings offer insight into the causes of climate change.","vi":"Những phát hiện này đem lại hiểu biết sâu sắc về nguyên nhân biến đổi khí hậu."}]','[]',NULL,'/ˈɔːfər ˈɪnsaɪt ˈɪntuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4794,'colloc-11-01',4,'offer an opportunity','mang lại một cơ hội','v + n','[{"en":"The program offers an opportunity to study abroad for a year.","vi":"Chương trình mang lại một cơ hội du học một năm."},{"en":"This crisis also offers an opportunity to rethink old policies.","vi":"Cuộc khủng hoảng này cũng mang lại một cơ hội để xem lại các chính sách cũ."},{"en":"Volunteering offers an opportunity to gain valuable practical experience.","vi":"Tình nguyện mang lại một cơ hội để có được kinh nghiệm thực tế quý báu."}]','[]',NULL,'/ˈɔːfər ən ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4795,'colloc-11-01',5,'official statistics','số liệu thống kê chính thức','adj + n','[{"en":"According to official statistics, unemployment fell over the past year.","vi":"Theo số liệu thống kê chính thức, thất nghiệp đã giảm trong năm qua."},{"en":"Official statistics often underestimate the size of the informal economy.","vi":"Số liệu thống kê chính thức thường đánh giá thấp quy mô kinh tế phi chính thức."},{"en":"The report compares official statistics from several different countries.","vi":"Báo cáo so sánh số liệu thống kê chính thức từ nhiều quốc gia khác nhau."}]','[]',NULL,'/əˈfɪʃəl stəˈtɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4796,'colloc-11-01',6,'once established','một khi đã được thiết lập','adv + vpp','[{"en":"Once established, these habits are very difficult to change.","vi":"Một khi đã được hình thành, những thói quen này rất khó thay đổi."},{"en":"Once established, the new system reduced waiting times significantly.","vi":"Một khi đã được thiết lập, hệ thống mới giảm đáng kể thời gian chờ."},{"en":"Once established, a reputation can shape how others perceive you.","vi":"Một khi đã được tạo dựng, danh tiếng có thể định hình cách người khác nhìn bạn."}]','[]',NULL,'/wʌns ɪˈstæblɪʃt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4797,'colloc-11-01',7,'ongoing debate','cuộc tranh luận đang diễn ra','adj + n','[{"en":"There is an ongoing debate about the best teaching methods.","vi":"Đang có một cuộc tranh luận về phương pháp giảng dạy tốt nhất."},{"en":"The paper contributes to the ongoing debate over privacy rights.","vi":"Bài viết đóng góp vào cuộc tranh luận đang diễn ra về quyền riêng tư."},{"en":"This question lies at the heart of an ongoing debate.","vi":"Câu hỏi này nằm ở trung tâm của một cuộc tranh luận đang diễn ra."}]','[]',NULL,'/ˈɑːnˌɡoʊɪŋ dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4798,'colloc-11-01',8,'ongoing process','quá trình đang diễn ra liên tục','adj + n','[{"en":"Learning a language is an ongoing process that never fully ends.","vi":"Học một ngôn ngữ là một quá trình liên tục không bao giờ thực sự kết thúc."},{"en":"Reform is an ongoing process rather than a single event.","vi":"Cải cách là một quá trình liên tục chứ không phải một sự kiện đơn lẻ."},{"en":"Maintaining trust within a team is an ongoing process.","vi":"Duy trì sự tin tưởng trong một đội nhóm là một quá trình liên tục."}]','[]',NULL,'/ˈɑːnˌɡoʊɪŋ ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4799,'colloc-11-01',9,'online access','quyền truy cập trực tuyến','adj + n','[{"en":"Students are given online access to the full library catalog.","vi":"Sinh viên được cấp quyền truy cập trực tuyến vào toàn bộ danh mục thư viện."},{"en":"Online access to medical records improves communication between doctors.","vi":"Truy cập trực tuyến vào hồ sơ y tế cải thiện giao tiếp giữa các bác sĩ."},{"en":"Limited online access remains a barrier in many rural areas.","vi":"Truy cập trực tuyến hạn chế vẫn là rào cản ở nhiều vùng nông thôn."}]','[]',NULL,'/ˈɑːnˌlaɪn ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4800,'colloc-11-01',10,'online database','cơ sở dữ liệu trực tuyến','adj + n','[{"en":"The articles were retrieved from a large online database.","vi":"Các bài báo được lấy từ một cơ sở dữ liệu trực tuyến lớn."},{"en":"An online database lets researchers search thousands of records quickly.","vi":"Một cơ sở dữ liệu trực tuyến cho phép nhà nghiên cứu tìm hàng nghìn bản ghi nhanh chóng."},{"en":"The university maintains an online database of past dissertations.","vi":"Trường đại học duy trì một cơ sở dữ liệu trực tuyến về các luận án trước đây."}]','[]',NULL,'/ˈɑːnˌlaɪn ˈdeɪtəˌbeɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4801,'colloc-11-01',11,'online journal','tạp chí trực tuyến','adj + n','[{"en":"Her study was published in a respected online journal.","vi":"Nghiên cứu của cô được công bố trên một tạp chí trực tuyến uy tín."},{"en":"Many online journals make their articles freely available to readers.","vi":"Nhiều tạp chí trực tuyến cho phép độc giả tiếp cận miễn phí các bài báo."},{"en":"An online journal can reach a global audience almost instantly.","vi":"Một tạp chí trực tuyến có thể tiếp cận độc giả toàn cầu gần như ngay lập tức."}]','[]',NULL,'/ˈɑːnˌlaɪn ˈdʒɜːrnəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4802,'colloc-11-01',12,'online version','phiên bản trực tuyến','adj + n','[{"en":"The online version of the book includes interactive exercises.","vi":"Phiên bản trực tuyến của cuốn sách có các bài tập tương tác."},{"en":"Readers can access the online version free of charge.","vi":"Độc giả có thể truy cập phiên bản trực tuyến miễn phí."},{"en":"The online version is updated more often than the print edition.","vi":"Phiên bản trực tuyến được cập nhật thường xuyên hơn bản in."}]','[]',NULL,'/ˈɑːnˌlaɪn ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4803,'colloc-11-01',13,'open access','truy cập mở (miễn phí)','adj + n','[{"en":"Open access allows anyone to read research without paying fees.","vi":"Truy cập mở cho phép bất kỳ ai đọc nghiên cứu mà không phải trả phí."},{"en":"The journal moved to an open access model last year.","vi":"Tạp chí đã chuyển sang mô hình truy cập mở vào năm ngoái."},{"en":"Open access publishing has changed how scientists share their work.","vi":"Xuất bản theo hình thức truy cập mở đã thay đổi cách các nhà khoa học chia sẻ công trình."}]','[]',NULL,'/ˈoʊpən ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4804,'colloc-11-01',14,'opening chapter','chương mở đầu','adj + n','[{"en":"The opening chapter introduces the main characters and setting.","vi":"Chương mở đầu giới thiệu các nhân vật chính và bối cảnh."},{"en":"Her opening chapter clearly outlines the aims of the thesis.","vi":"Chương mở đầu của cô nêu rõ các mục tiêu của luận án."},{"en":"A strong opening chapter often determines whether readers continue.","vi":"Một chương mở đầu mạnh mẽ thường quyết định liệu độc giả có đọc tiếp hay không."}]','[]',NULL,'/ˈoʊpənɪŋ ˈtʃæptər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4805,'colloc-11-01',15,'opening section','phần mở đầu','adj + n','[{"en":"The opening section explains the background to the study.","vi":"Phần mở đầu giải thích bối cảnh của nghiên cứu."},{"en":"In the opening section, the author states her main argument.","vi":"Trong phần mở đầu, tác giả nêu ra luận điểm chính của mình."},{"en":"The opening section should capture the reader''s attention immediately.","vi":"Phần mở đầu nên thu hút sự chú ý của độc giả ngay lập tức."}]','[]',NULL,'/ˈoʊpənɪŋ ˈsekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4806,'colloc-11-01',16,'opinion leader','người dẫn dắt dư luận','n + n','[{"en":"Opinion leaders strongly influence how communities respond to new ideas.","vi":"Những người dẫn dắt dư luận ảnh hưởng mạnh đến cách cộng đồng phản ứng với ý tưởng mới."},{"en":"Marketers often target opinion leaders to spread their messages.","vi":"Các nhà tiếp thị thường nhắm đến người dẫn dắt dư luận để lan tỏa thông điệp."},{"en":"An opinion leader can shape public attitudes within a group.","vi":"Một người dẫn dắt dư luận có thể định hình thái độ chung trong một nhóm."}]','[]',NULL,'/əˈpɪnjən ˈliːdər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4807,'colloc-11-01',17,'optimal solution','giải pháp tối ưu','adj + n','[{"en":"The algorithm searches for the optimal solution among many options.","vi":"Thuật toán tìm kiếm giải pháp tối ưu trong số nhiều phương án."},{"en":"Finding the optimal solution required balancing cost against speed.","vi":"Tìm ra giải pháp tối ưu đòi hỏi cân bằng giữa chi phí và tốc độ."},{"en":"There is rarely a single optimal solution to complex problems.","vi":"Hiếm khi có một giải pháp tối ưu duy nhất cho các vấn đề phức tạp."}]','[]',NULL,'/ˈɑːptɪməl səˈluːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4808,'colloc-11-01',18,'oral history','lịch sử truyền miệng','adj + n','[{"en":"Oral history preserves the memories of people who lived events.","vi":"Lịch sử truyền miệng lưu giữ ký ức của những người đã trải qua sự kiện."},{"en":"She recorded oral history from elders in the village.","vi":"Cô ghi lại lịch sử truyền miệng từ những người cao tuổi trong làng."},{"en":"Oral history offers perspectives often missing from written records.","vi":"Lịch sử truyền miệng mang đến những góc nhìn mà tài liệu viết thường thiếu."}]','[]',NULL,'/ˈɔːrəl ˈhɪstəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4809,'colloc-11-01',19,'oral presentation','bài thuyết trình nói','adj + n','[{"en":"Each student must give an oral presentation at the end.","vi":"Mỗi sinh viên phải thực hiện một bài thuyết trình nói vào cuối kỳ."},{"en":"Her oral presentation clearly summarized the results of the project.","vi":"Bài thuyết trình nói của cô tóm tắt rõ ràng kết quả của dự án."},{"en":"Good preparation makes an oral presentation far more convincing.","vi":"Chuẩn bị tốt khiến một bài thuyết trình nói thuyết phục hơn nhiều."}]','[]',NULL,'/ˈɔːrəl ˌprezənˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4810,'colloc-11-01',20,'organizing principle','nguyên tắc tổ chức (sắp xếp)','adj + n','[{"en":"Chronology serves as the main organizing principle of the book.","vi":"Trình tự thời gian đóng vai trò là nguyên tắc tổ chức chính của cuốn sách."},{"en":"The essay lacks a clear organizing principle to guide readers.","vi":"Bài luận thiếu một nguyên tắc tổ chức rõ ràng để dẫn dắt độc giả."},{"en":"Equality became the central organizing principle of the movement.","vi":"Bình đẳng trở thành nguyên tắc tổ chức trung tâm của phong trào."}]','[]',NULL,'/ˈɔːrɡəˌnaɪzɪŋ ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4811,'colloc-11-01',21,'organizational structure','cơ cấu tổ chức','adj + n','[{"en":"The company changed its organizational structure to improve efficiency.","vi":"Công ty thay đổi cơ cấu tổ chức để cải thiện hiệu quả."},{"en":"A flat organizational structure can speed up decision making.","vi":"Một cơ cấu tổ chức phẳng có thể tăng tốc việc ra quyết định."},{"en":"The report analyzes the organizational structure of large hospitals.","vi":"Báo cáo phân tích cơ cấu tổ chức của các bệnh viện lớn."}]','[]',NULL,'/ˌɔːrɡənɪˈzeɪʃənəl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4812,'colloc-11-01',22,'original author','tác giả gốc','adj + n','[{"en":"The translation stays faithful to the original author''s intentions.","vi":"Bản dịch giữ trung thành với ý định của tác giả gốc."},{"en":"We could not identify the original author of the manuscript.","vi":"Chúng tôi không thể xác định tác giả gốc của bản thảo."},{"en":"The original author published the theory more than a century ago.","vi":"Tác giả gốc đã công bố lý thuyết này hơn một thế kỷ trước."}]','[]',NULL,'/əˈrɪdʒənəl ˈɔːθər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4813,'colloc-11-01',23,'original context','bối cảnh ban đầu','adj + n','[{"en":"The quotation loses meaning when removed from its original context.","vi":"Câu trích dẫn mất ý nghĩa khi bị tách khỏi bối cảnh ban đầu."},{"en":"Understanding the original context helps explain the author''s choices.","vi":"Hiểu bối cảnh ban đầu giúp giải thích các lựa chọn của tác giả."},{"en":"The artifact was studied within its original cultural context.","vi":"Hiện vật được nghiên cứu trong bối cảnh văn hóa ban đầu của nó."}]','[]',NULL,'/əˈrɪdʒənəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4814,'colloc-11-01',24,'original data','dữ liệu gốc','adj + n','[{"en":"Researchers should always preserve the original data for verification.","vi":"Các nhà nghiên cứu nên luôn lưu giữ dữ liệu gốc để kiểm chứng."},{"en":"The original data was lost when the hard drive failed.","vi":"Dữ liệu gốc bị mất khi ổ cứng hỏng."},{"en":"Other scholars can reanalyze the original data to test the findings.","vi":"Các học giả khác có thể phân tích lại dữ liệu gốc để kiểm tra kết quả."}]','[]',NULL,'/əˈrɪdʒənəl ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4815,'colloc-11-01',25,'original intent','ý định ban đầu','adj + n','[{"en":"Judges sometimes debate the original intent of the lawmakers.","vi":"Các thẩm phán đôi khi tranh luận về ý định ban đầu của các nhà lập pháp."},{"en":"The reform drifted far from its original intent over time.","vi":"Cuộc cải cách dần đi xa khỏi ý định ban đầu theo thời gian."},{"en":"She explained the original intent behind the controversial policy.","vi":"Cô giải thích ý định ban đầu đằng sau chính sách gây tranh cãi."}]','[]',NULL,'/əˈrɪdʒənəl ɪnˈtent/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4816,'colloc-11-01',26,'original meaning','nghĩa gốc','adj + n','[{"en":"Over centuries, the word lost much of its original meaning.","vi":"Qua nhiều thế kỷ, từ này đã mất phần lớn nghĩa gốc."},{"en":"Scholars try to recover the original meaning of the ancient text.","vi":"Các học giả cố gắng khôi phục nghĩa gốc của văn bản cổ."},{"en":"A careful translation preserves the original meaning of the poem.","vi":"Một bản dịch cẩn thận giữ được nghĩa gốc của bài thơ."}]','[]',NULL,'/əˈrɪdʒənəl ˈmiːnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4817,'colloc-11-01',27,'original model','mô hình ban đầu','adj + n','[{"en":"The new theory builds directly on the original model.","vi":"Lý thuyết mới được xây dựng trực tiếp dựa trên mô hình ban đầu."},{"en":"Researchers revised the original model after new data appeared.","vi":"Các nhà nghiên cứu sửa đổi mô hình ban đầu sau khi có dữ liệu mới."},{"en":"The original model failed to account for several key variables.","vi":"Mô hình ban đầu không tính đến một số biến số quan trọng."}]','[]',NULL,'/əˈrɪdʒənəl ˈmɑːdəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4818,'colloc-11-01',28,'original position','vị trí ban đầu','adj + n','[{"en":"After the debate, she returned to her original position.","vi":"Sau cuộc tranh luận, cô quay lại với lập trường ban đầu của mình."},{"en":"The springs push the lever back to its original position.","vi":"Các lò xo đẩy đòn bẩy trở về vị trí ban đầu của nó."},{"en":"He defended his original position despite strong opposition.","vi":"Anh bảo vệ lập trường ban đầu của mình bất chấp sự phản đối mạnh mẽ."}]','[]',NULL,'/əˈrɪdʒənəl pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4819,'colloc-11-01',29,'original research','nghiên cứu nguyên bản (tự thực hiện)','adj + n','[{"en":"A doctoral thesis must contain genuine original research.","vi":"Một luận án tiến sĩ phải chứa đựng nghiên cứu nguyên bản thực sự."},{"en":"The journal only publishes original research, not literature reviews.","vi":"Tạp chí chỉ công bố nghiên cứu nguyên bản, không đăng tổng quan tài liệu."},{"en":"Her original research challenged several long-held assumptions.","vi":"Nghiên cứu nguyên bản của cô thách thức nhiều giả định lâu đời."}]','[]',NULL,'/əˈrɪdʒənəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4820,'colloc-11-01',30,'original source','nguồn gốc (nguồn nguyên bản)','adj + n','[{"en":"Always check the original source before citing a statistic.","vi":"Luôn kiểm tra nguồn gốc trước khi trích dẫn một con số thống kê."},{"en":"The claim could not be traced to its original source.","vi":"Khẳng định này không thể truy ngược về nguồn gốc của nó."},{"en":"Quoting the original source strengthens the credibility of your essay.","vi":"Trích dẫn nguồn gốc làm tăng độ tin cậy cho bài luận của bạn."}]','[]',NULL,'/əˈrɪdʒənəl sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4821,'colloc-11-01',31,'original text','văn bản gốc','adj + n','[{"en":"The translator stayed close to the original text throughout.","vi":"Người dịch bám sát văn bản gốc trong suốt quá trình."},{"en":"Comparing versions reveals small changes from the original text.","vi":"So sánh các phiên bản cho thấy những thay đổi nhỏ so với văn bản gốc."},{"en":"Students were asked to read the original text, not a summary.","vi":"Sinh viên được yêu cầu đọc văn bản gốc, không phải bản tóm tắt."}]','[]',NULL,'/əˈrɪdʒənəl tekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4822,'colloc-11-01',32,'original version','phiên bản gốc','adj + n','[{"en":"The original version of the film was much longer.","vi":"Phiên bản gốc của bộ phim dài hơn nhiều."},{"en":"Many readers still prefer the original version of the novel.","vi":"Nhiều độc giả vẫn thích phiên bản gốc của cuốn tiểu thuyết hơn."},{"en":"The original version contained errors that were later corrected.","vi":"Phiên bản gốc chứa những lỗi sau này đã được sửa."}]','[]',NULL,'/əˈrɪdʒənəl ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4823,'colloc-11-01',33,'original work','tác phẩm nguyên bản','adj + n','[{"en":"The exhibition features original works by several famous painters.","vi":"Triển lãm trưng bày các tác phẩm nguyên bản của vài họa sĩ nổi tiếng."},{"en":"Plagiarism means presenting someone else''s ideas as original work.","vi":"Đạo văn nghĩa là trình bày ý tưởng của người khác như tác phẩm nguyên bản."},{"en":"Her dissertation was praised as a piece of original work.","vi":"Luận án của cô được khen ngợi là một công trình nguyên bản."}]','[]',NULL,'/əˈrɪdʒənəl wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4824,'colloc-11-01',34,'originally developed','được phát triển ban đầu','adv + vpp','[{"en":"The technology was originally developed for military purposes.","vi":"Công nghệ này ban đầu được phát triển cho mục đích quân sự."},{"en":"This method was originally developed by a small research team.","vi":"Phương pháp này ban đầu được phát triển bởi một nhóm nghiên cứu nhỏ."},{"en":"The drug was originally developed to treat a different disease.","vi":"Loại thuốc này ban đầu được phát triển để điều trị một căn bệnh khác."}]','[]',NULL,'/əˈrɪdʒənəli dɪˈveləpt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4825,'colloc-11-01',35,'originally intended','vốn được dự định ban đầu','adv + vpp','[{"en":"The building was originally intended to be a library.","vi":"Tòa nhà vốn được dự định ban đầu làm một thư viện."},{"en":"The funds were originally intended for emergency relief programs.","vi":"Khoản tiền vốn được dự định ban đầu cho các chương trình cứu trợ khẩn cấp."},{"en":"The policy reached groups it was not originally intended to help.","vi":"Chính sách tiếp cận những nhóm mà ban đầu nó không dự định giúp đỡ."}]','[]',NULL,'/əˈrɪdʒənəli ɪnˈtendɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4826,'colloc-11-01',36,'overall aim','mục tiêu tổng thể','adj + n','[{"en":"The overall aim of the project is to reduce poverty.","vi":"Mục tiêu tổng thể của dự án là giảm nghèo."},{"en":"Each task supports the overall aim of the research.","vi":"Mỗi nhiệm vụ đều hỗ trợ cho mục tiêu tổng thể của nghiên cứu."},{"en":"She kept the overall aim in mind throughout the study.","vi":"Cô luôn ghi nhớ mục tiêu tổng thể trong suốt quá trình nghiên cứu."}]','[]',NULL,'/ˌoʊvərˈɔːl eɪm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4827,'colloc-11-01',37,'overall effect','tác động tổng thể','adj + n','[{"en":"The overall effect of the policy was hard to measure.","vi":"Tác động tổng thể của chính sách rất khó đo lường."},{"en":"These small changes had a significant overall effect on costs.","vi":"Những thay đổi nhỏ này có tác động tổng thể đáng kể lên chi phí."},{"en":"The overall effect of the design was calm and welcoming.","vi":"Hiệu ứng tổng thể của thiết kế tạo cảm giác bình yên và thân thiện."}]','[]',NULL,'/ˌoʊvərˈɔːl ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4828,'colloc-11-01',38,'overall level','mức độ tổng thể','adj + n','[{"en":"The overall level of satisfaction rose after the changes.","vi":"Mức độ hài lòng tổng thể tăng lên sau những thay đổi."},{"en":"Researchers measured the overall level of pollution in the river.","vi":"Các nhà nghiên cứu đo mức độ ô nhiễm tổng thể của con sông."},{"en":"The overall level of skill in the group was impressive.","vi":"Trình độ kỹ năng tổng thể của nhóm rất ấn tượng."}]','[]',NULL,'/ˌoʊvərˈɔːl ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4829,'colloc-11-01',39,'overall performance','hiệu suất tổng thể','adj + n','[{"en":"The new method improved the overall performance of the system.","vi":"Phương pháp mới cải thiện hiệu suất tổng thể của hệ thống."},{"en":"Her overall performance this year exceeded everyone''s expectations.","vi":"Thành tích tổng thể của cô năm nay vượt mọi kỳ vọng."},{"en":"Sleep and diet both affect a student''s overall performance.","vi":"Giấc ngủ và chế độ ăn đều ảnh hưởng đến thành tích tổng thể của sinh viên."}]','[]',NULL,'/ˌoʊvərˈɔːl pərˈfɔːrməns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4830,'colloc-11-01',40,'overall picture','bức tranh toàn cảnh','adj + n','[{"en":"Combining the studies gives us a clearer overall picture.","vi":"Kết hợp các nghiên cứu cho ta một bức tranh toàn cảnh rõ ràng hơn."},{"en":"A single statistic rarely shows the overall picture accurately.","vi":"Một con số thống kê đơn lẻ hiếm khi phản ánh chính xác bức tranh toàn cảnh."},{"en":"The summary helps readers grasp the overall picture quickly.","vi":"Phần tóm tắt giúp độc giả nắm bắt bức tranh toàn cảnh nhanh chóng."}]','[]',NULL,'/ˌoʊvərˈɔːl ˈpɪktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4831,'colloc-11-01',41,'overall rate','tỷ lệ tổng thể','adj + n','[{"en":"The overall rate of unemployment fell slightly last quarter.","vi":"Tỷ lệ thất nghiệp tổng thể giảm nhẹ trong quý trước."},{"en":"Vaccination raised the overall rate of immunity in the population.","vi":"Tiêm chủng nâng tỷ lệ miễn dịch tổng thể trong dân số."},{"en":"Despite local spikes, the overall rate remained fairly stable.","vi":"Dù có những đợt tăng cục bộ, tỷ lệ tổng thể vẫn khá ổn định."}]','[]',NULL,'/ˌoʊvərˈɔːl reɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4832,'colloc-11-01',42,'overall structure','cấu trúc tổng thể','adj + n','[{"en":"The essay''s overall structure guides the reader through the argument.","vi":"Cấu trúc tổng thể của bài luận dẫn dắt độc giả qua lập luận."},{"en":"Understanding the overall structure helps you follow the lecture.","vi":"Hiểu cấu trúc tổng thể giúp bạn theo dõi bài giảng."},{"en":"The overall structure of the molecule determines its function.","vi":"Cấu trúc tổng thể của phân tử quyết định chức năng của nó."}]','[]',NULL,'/ˌoʊvərˈɔːl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4833,'colloc-11-01',43,'overwhelming majority','đại đa số áp đảo','adj + n','[{"en":"The overwhelming majority of respondents supported the new plan.","vi":"Đại đa số áp đảo người được hỏi ủng hộ kế hoạch mới."},{"en":"An overwhelming majority of scientists agree on this conclusion.","vi":"Đại đa số áp đảo các nhà khoa học đồng ý với kết luận này."},{"en":"The motion passed with an overwhelming majority of votes.","vi":"Đề xuất được thông qua với đa số phiếu áp đảo."}]','[]',NULL,'/ˌoʊvərˈwelmɪŋ məˈdʒɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4834,'colloc-11-01',44,'paid employment','công việc được trả lương','adj + n','[{"en":"Many students balance paid employment with their university studies.","vi":"Nhiều sinh viên cân bằng công việc được trả lương với việc học đại học."},{"en":"Access to paid employment greatly improves financial independence.","vi":"Tiếp cận công việc được trả lương cải thiện đáng kể sự độc lập tài chính."},{"en":"The study examined barriers to paid employment for disabled people.","vi":"Nghiên cứu xem xét những rào cản đối với công việc được trả lương cho người khuyết tật."}]','[]',NULL,'/peɪd ɪmˈplɔɪmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4835,'colloc-11-01',45,'paramount importance','tầm quan trọng tối cao','adj + n','[{"en":"Patient safety is of paramount importance in every hospital.","vi":"An toàn của bệnh nhân có tầm quan trọng tối cao trong mọi bệnh viện."},{"en":"Accuracy is of paramount importance when reporting scientific data.","vi":"Tính chính xác có tầm quan trọng tối cao khi báo cáo dữ liệu khoa học."},{"en":"For this mission, clear communication is of paramount importance.","vi":"Đối với nhiệm vụ này, giao tiếp rõ ràng có tầm quan trọng tối cao."}]','[]',NULL,'/ˈpærəˌmaʊnt ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4836,'colloc-11-01',46,'particular area','lĩnh vực cụ thể','adj + n','[{"en":"She specializes in a particular area of molecular biology.","vi":"Cô chuyên về một lĩnh vực cụ thể của sinh học phân tử."},{"en":"The report focuses on one particular area of public policy.","vi":"Báo cáo tập trung vào một lĩnh vực cụ thể của chính sách công."},{"en":"This particular area of the brain controls language processing.","vi":"Vùng cụ thể này của não điều khiển việc xử lý ngôn ngữ."}]','[]',NULL,'/pərˈtɪkjələr ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4837,'colloc-11-01',47,'particular aspect','khía cạnh cụ thể','adj + n','[{"en":"The chapter explores one particular aspect of human memory.","vi":"Chương này khám phá một khía cạnh cụ thể của trí nhớ con người."},{"en":"Each interview focused on a particular aspect of their work.","vi":"Mỗi cuộc phỏng vấn tập trung vào một khía cạnh cụ thể trong công việc của họ."},{"en":"This particular aspect of the theory remains poorly understood.","vi":"Khía cạnh cụ thể này của lý thuyết vẫn còn ít được hiểu rõ."}]','[]',NULL,'/pərˈtɪkjələr ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4838,'colloc-11-01',48,'particular emphasis','sự nhấn mạnh đặc biệt','adj + n','[{"en":"The course places particular emphasis on practical laboratory skills.","vi":"Khóa học đặc biệt nhấn mạnh vào các kỹ năng thực hành trong phòng thí nghiệm."},{"en":"She gave particular emphasis to ethical issues in her lecture.","vi":"Cô đặc biệt nhấn mạnh các vấn đề đạo đức trong bài giảng của mình."},{"en":"The policy puts particular emphasis on early childhood education.","vi":"Chính sách này đặc biệt nhấn mạnh vào giáo dục mầm non."}]','[]',NULL,'/pərˈtɪkjələr ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4839,'colloc-11-01',49,'particular feature','đặc điểm cụ thể','adj + n','[{"en":"One particular feature of the design attracted the most attention.","vi":"Một đặc điểm cụ thể của thiết kế thu hút sự chú ý nhiều nhất."},{"en":"This particular feature distinguishes the species from its relatives.","vi":"Đặc điểm cụ thể này phân biệt loài này với các loài họ hàng."},{"en":"The author highlights a particular feature of the local dialect.","vi":"Tác giả làm nổi bật một đặc điểm cụ thể của phương ngữ địa phương."}]','[]',NULL,'/pərˈtɪkjələr ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4840,'colloc-11-01',50,'particular focus','trọng tâm cụ thể','adj + n','[{"en":"The study has a particular focus on young first-time voters.","vi":"Nghiên cứu có trọng tâm cụ thể là những cử tri trẻ lần đầu đi bầu."},{"en":"Her work places particular focus on sustainable urban transport.","vi":"Công việc của cô đặt trọng tâm cụ thể vào giao thông đô thị bền vững."},{"en":"This chapter gives particular focus to the economic consequences.","vi":"Chương này dành trọng tâm cụ thể cho các hệ quả kinh tế."}]','[]',NULL,'/pərˈtɪkjələr ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4841,'colloc-11-01',51,'particular individual','một cá nhân cụ thể','adj + n','[{"en":"The policy was not designed to target any particular individual.","vi":"Chính sách không được thiết kế để nhắm vào bất kỳ cá nhân cụ thể nào."},{"en":"Responsibility cannot always be traced to one particular individual.","vi":"Trách nhiệm không phải lúc nào cũng truy về một cá nhân cụ thể."},{"en":"The case study follows one particular individual over ten years.","vi":"Nghiên cứu trường hợp theo dõi một cá nhân cụ thể trong mười năm."}]','[]',NULL,'/pərˈtɪkjələr ˌɪndɪˈvɪdʒuəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4842,'colloc-11-01',52,'particular meaning','ý nghĩa cụ thể','adj + n','[{"en":"The word carries a particular meaning in legal contexts.","vi":"Từ này mang một ý nghĩa cụ thể trong ngữ cảnh pháp lý."},{"en":"This symbol had a particular meaning for the ancient community.","vi":"Biểu tượng này có một ý nghĩa cụ thể đối với cộng đồng cổ xưa."},{"en":"Each color in the diagram conveys a particular meaning.","vi":"Mỗi màu trong sơ đồ truyền tải một ý nghĩa cụ thể."}]','[]',NULL,'/pərˈtɪkjələr ˈmiːnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4843,'colloc-11-01',53,'particularly acute','đặc biệt nghiêm trọng (gay gắt)','adv + adj','[{"en":"The housing shortage is particularly acute in large cities.","vi":"Tình trạng thiếu nhà ở đặc biệt nghiêm trọng tại các thành phố lớn."},{"en":"Water scarcity becomes particularly acute during the dry season.","vi":"Tình trạng khan hiếm nước trở nên đặc biệt nghiêm trọng vào mùa khô."},{"en":"The problem is particularly acute among low-income families.","vi":"Vấn đề này đặc biệt nghiêm trọng ở các gia đình thu nhập thấp."}]','[]',NULL,'/pərˈtɪkjələrli əˈkjuːt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4844,'colloc-11-01',54,'particularly apparent','đặc biệt rõ ràng','adv + adj','[{"en":"The difference is particularly apparent in the youngest age group.","vi":"Sự khác biệt đặc biệt rõ ràng ở nhóm tuổi nhỏ nhất."},{"en":"This trend becomes particularly apparent when data is graphed.","vi":"Xu hướng này trở nên đặc biệt rõ ràng khi dữ liệu được vẽ biểu đồ."},{"en":"The effect was particularly apparent after the second treatment.","vi":"Hiệu ứng đặc biệt rõ ràng sau lần điều trị thứ hai."}]','[]',NULL,'/pərˈtɪkjələrli əˈpærənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4845,'colloc-11-01',55,'particularly appropriate','đặc biệt phù hợp','adv + adj','[{"en":"This method is particularly appropriate for small data sets.","vi":"Phương pháp này đặc biệt phù hợp với các tập dữ liệu nhỏ."},{"en":"The example seems particularly appropriate for beginning students.","vi":"Ví dụ này có vẻ đặc biệt phù hợp với sinh viên mới bắt đầu."},{"en":"Her tone was particularly appropriate for such a sensitive topic.","vi":"Giọng điệu của cô đặc biệt phù hợp với một chủ đề nhạy cảm như vậy."}]','[]',NULL,'/pərˈtɪkjələrli əˈproʊpriət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4846,'colloc-11-01',56,'particularly concerned with','đặc biệt quan tâm đến','adv + vpp','[{"en":"The author is particularly concerned with questions of social justice.","vi":"Tác giả đặc biệt quan tâm đến các vấn đề công bằng xã hội."},{"en":"This branch of study is particularly concerned with human behavior.","vi":"Nhánh nghiên cứu này đặc biệt quan tâm đến hành vi con người."},{"en":"Regulators are particularly concerned with protecting consumer privacy.","vi":"Các cơ quan quản lý đặc biệt quan tâm đến việc bảo vệ quyền riêng tư người tiêu dùng."}]','[]',NULL,'/pərˈtɪkjələrli kənˈsɜːrnd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4847,'colloc-11-01',57,'particularly effective','đặc biệt hiệu quả','adv + adj','[{"en":"Visual aids are particularly effective when explaining complex ideas.","vi":"Phương tiện trực quan đặc biệt hiệu quả khi giải thích các ý tưởng phức tạp."},{"en":"The new treatment proved particularly effective in older patients.","vi":"Phương pháp điều trị mới tỏ ra đặc biệt hiệu quả ở bệnh nhân lớn tuổi."},{"en":"This strategy is particularly effective at reducing student anxiety.","vi":"Chiến lược này đặc biệt hiệu quả trong việc giảm lo âu cho sinh viên."}]','[]',NULL,'/pərˈtɪkjələrli ɪˈfektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4848,'colloc-11-01',58,'particularly evident','đặc biệt rõ nét','adv + adj','[{"en":"This pattern is particularly evident in urban populations.","vi":"Khuôn mẫu này đặc biệt rõ nét ở các quần thể đô thị."},{"en":"Her influence is particularly evident in later literary works.","vi":"Ảnh hưởng của cô đặc biệt rõ nét trong các tác phẩm văn học về sau."},{"en":"The improvement was particularly evident during the final tests.","vi":"Sự cải thiện đặc biệt rõ nét trong các bài kiểm tra cuối cùng."}]','[]',NULL,'/pərˈtɪkjələrli ˈevɪdənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4849,'colloc-11-01',59,'particularly influential','đặc biệt có ảnh hưởng','adv + adj','[{"en":"Her early essays were particularly influential among young scholars.","vi":"Những bài luận đầu tay của cô đặc biệt có ảnh hưởng với các học giả trẻ."},{"en":"This theory proved particularly influential in modern economics.","vi":"Lý thuyết này tỏ ra đặc biệt có ảnh hưởng trong kinh tế học hiện đại."},{"en":"One book was particularly influential in shaping public opinion.","vi":"Một cuốn sách đặc biệt có ảnh hưởng trong việc định hình dư luận."}]','[]',NULL,'/pərˈtɪkjələrli ˌɪnfluˈenʃəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4850,'colloc-11-01',60,'particularly relevant','đặc biệt liên quan (thích đáng)','adv + adj','[{"en":"These findings are particularly relevant to current health policy.","vi":"Những phát hiện này đặc biệt liên quan đến chính sách y tế hiện hành."},{"en":"The example felt particularly relevant to the students'' own lives.","vi":"Ví dụ này cảm thấy đặc biệt liên quan đến cuộc sống của chính các sinh viên."},{"en":"This argument is particularly relevant in the digital age.","vi":"Lập luận này đặc biệt thích đáng trong thời đại số."}]','[]',NULL,'/pərˈtɪkjələrli ˈreləvənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4851,'colloc-11-01',61,'particularly sensitive','đặc biệt nhạy cảm','adv + adj','[{"en":"The interview touched on a particularly sensitive personal topic.","vi":"Cuộc phỏng vấn chạm đến một chủ đề cá nhân đặc biệt nhạy cảm."},{"en":"Young children are particularly sensitive to changes in routine.","vi":"Trẻ nhỏ đặc biệt nhạy cảm với những thay đổi trong thói quen."},{"en":"This instrument is particularly sensitive to small temperature shifts.","vi":"Thiết bị này đặc biệt nhạy cảm với những thay đổi nhiệt độ nhỏ."}]','[]',NULL,'/pərˈtɪkjələrli ˈsensətɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4852,'colloc-11-01',62,'particularly significant','đặc biệt quan trọng (đáng kể)','adv + adj','[{"en":"This discovery was particularly significant for cancer research.","vi":"Phát hiện này đặc biệt quan trọng đối với nghiên cứu ung thư."},{"en":"The difference between the groups was particularly significant.","vi":"Sự khác biệt giữa các nhóm là đặc biệt đáng kể."},{"en":"Her contribution was particularly significant in that field.","vi":"Đóng góp của cô đặc biệt quan trọng trong lĩnh vực đó."}]','[]',NULL,'/pərˈtɪkjələrli sɪɡˈnɪfɪkənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4853,'colloc-11-01',63,'particularly striking','đặc biệt nổi bật (ấn tượng)','adv + adj','[{"en":"One result was particularly striking and surprised the whole team.","vi":"Một kết quả đặc biệt nổi bật và khiến cả nhóm bất ngờ."},{"en":"The contrast between the two regions is particularly striking.","vi":"Sự tương phản giữa hai khu vực đặc biệt nổi bật."},{"en":"Her use of color is particularly striking in these paintings.","vi":"Cách cô dùng màu sắc đặc biệt ấn tượng trong những bức tranh này."}]','[]',NULL,'/pərˈtɪkjələrli ˈstraɪkɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4854,'colloc-11-01',64,'particularly successful','đặc biệt thành công','adv + adj','[{"en":"The campaign was particularly successful among younger audiences.","vi":"Chiến dịch đặc biệt thành công với đối tượng khán giả trẻ."},{"en":"This approach has been particularly successful in rural schools.","vi":"Cách tiếp cận này đặc biệt thành công ở các trường nông thôn."},{"en":"Her first novel was particularly successful with critics.","vi":"Cuốn tiểu thuyết đầu tay của cô đặc biệt thành công với giới phê bình."}]','[]',NULL,'/pərˈtɪkjələrli səkˈsesfəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4855,'colloc-11-01',65,'particularly suited to','đặc biệt phù hợp với','adv + vpp','[{"en":"This software is particularly suited to large-scale data analysis.","vi":"Phần mềm này đặc biệt phù hợp với phân tích dữ liệu quy mô lớn."},{"en":"The plant is particularly suited to hot and dry climates.","vi":"Loài cây này đặc biệt phù hợp với khí hậu nóng và khô."},{"en":"Her skills are particularly suited to collaborative research projects.","vi":"Kỹ năng của cô đặc biệt phù hợp với các dự án nghiên cứu hợp tác."}]','[]',NULL,'/pərˈtɪkjələrli ˈsuːtɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4856,'colloc-11-01',66,'particularly useful','đặc biệt hữu ích','adv + adj','[{"en":"This guide is particularly useful for first-year students.","vi":"Cuốn cẩm nang này đặc biệt hữu ích cho sinh viên năm nhất."},{"en":"The technique is particularly useful when time is limited.","vi":"Kỹ thuật này đặc biệt hữu ích khi thời gian hạn chế."},{"en":"Such maps are particularly useful for planning field research.","vi":"Những bản đồ như vậy đặc biệt hữu ích cho việc lập kế hoạch nghiên cứu thực địa."}]','[]',NULL,'/pərˈtɪkjələrli ˈjuːsfəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4857,'colloc-11-01',67,'particularly valuable','đặc biệt giá trị','adv + adj','[{"en":"This dataset is particularly valuable for studying long-term climate trends.","vi":"Bộ dữ liệu này đặc biệt giá trị cho việc nghiên cứu xu hướng khí hậu dài hạn."},{"en":"Her feedback was particularly valuable during the early drafting stage.","vi":"Phản hồi của cô đặc biệt giá trị trong giai đoạn viết nháp ban đầu."},{"en":"Such firsthand accounts are particularly valuable to historians.","vi":"Những lời kể trực tiếp như vậy đặc biệt giá trị đối với các nhà sử học."}]','[]',NULL,'/pərˈtɪkjələrli ˈvæljəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4858,'colloc-11-01',68,'partly responsible for','một phần chịu trách nhiệm về','adv + adj','[{"en":"Poor management was partly responsible for the project''s failure.","vi":"Quản lý kém một phần chịu trách nhiệm về sự thất bại của dự án."},{"en":"The new policy is partly responsible for the recent decline.","vi":"Chính sách mới một phần chịu trách nhiệm về sự suy giảm gần đây."},{"en":"Genetics may be partly responsible for these behavioral differences.","vi":"Di truyền có thể một phần chịu trách nhiệm về những khác biệt hành vi này."}]','[]',NULL,'/ˈpɑːrtli rɪˈspɑːnsəbəl fər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4859,'colloc-11-01',69,'party leader','lãnh đạo đảng','n + n','[{"en":"The party leader announced a major shift in policy yesterday.","vi":"Lãnh đạo đảng đã công bố một thay đổi lớn về chính sách hôm qua."},{"en":"Members voted to elect a new party leader this spring.","vi":"Các thành viên đã bỏ phiếu bầu lãnh đạo đảng mới vào mùa xuân này."},{"en":"Critics accused the party leader of ignoring grassroots concerns.","vi":"Các nhà phê bình cáo buộc lãnh đạo đảng phớt lờ mối lo của cơ sở."}]','[]',NULL,'/ˈpɑːrti ˈliːdər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4860,'colloc-11-01',70,'past research','nghiên cứu trước đây','adj + n','[{"en":"Past research has shown a clear link between diet and health.","vi":"Nghiên cứu trước đây đã chỉ ra mối liên hệ rõ ràng giữa chế độ ăn và sức khỏe."},{"en":"Our study builds on past research into bilingual education.","vi":"Nghiên cứu của chúng tôi dựa trên các nghiên cứu trước đây về giáo dục song ngữ."},{"en":"Past research largely ignored the role of social factors.","vi":"Nghiên cứu trước đây phần lớn bỏ qua vai trò của các yếu tố xã hội."}]','[]',NULL,'/pæst ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4861,'colloc-11-01',71,'peace treaty','hiệp ước hòa bình','n + n','[{"en":"The two nations finally signed a peace treaty after years of war.","vi":"Hai quốc gia cuối cùng đã ký hiệp ước hòa bình sau nhiều năm chiến tranh."},{"en":"Historians still debate the terms of that peace treaty.","vi":"Các nhà sử học vẫn còn tranh luận về các điều khoản của hiệp ước hòa bình đó."},{"en":"The peace treaty redrew the borders across the region.","vi":"Hiệp ước hòa bình đã vẽ lại biên giới trên khắp khu vực."}]','[]',NULL,'/piːs ˈtriːti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4862,'colloc-11-01',72,'perceived importance','tầm quan trọng được nhận thức','adj + n','[{"en":"The perceived importance of the issue influenced voter behavior.","vi":"Tầm quan trọng được nhận thức của vấn đề đã ảnh hưởng đến hành vi cử tri."},{"en":"Researchers measured the perceived importance of each factor.","vi":"Các nhà nghiên cứu đo lường tầm quan trọng được nhận thức của từng yếu tố."},{"en":"Its perceived importance grew as media coverage increased.","vi":"Tầm quan trọng được nhận thức của nó tăng lên khi truyền thông đưa tin nhiều hơn."}]','[]',NULL,'/pərˈsiːvd ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4863,'colloc-11-01',73,'perceived need','nhu cầu được nhận thức','adj + n','[{"en":"The perceived need for reform drove the new legislation forward.","vi":"Nhu cầu cải cách được nhận thức đã thúc đẩy đạo luật mới tiến triển."},{"en":"Marketing often creates a perceived need for new products.","vi":"Tiếp thị thường tạo ra nhu cầu được nhận thức đối với sản phẩm mới."},{"en":"A perceived need for security shaped these community decisions.","vi":"Nhu cầu an ninh được nhận thức đã định hình những quyết định cộng đồng này."}]','[]',NULL,'/pərˈsiːvd niːd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4864,'colloc-11-01',74,'perceived threat','mối đe dọa được nhận thức','adj + n','[{"en":"A perceived threat can trigger strong emotional reactions in people.","vi":"Một mối đe dọa được nhận thức có thể kích hoạt phản ứng cảm xúc mạnh ở con người."},{"en":"The perceived threat of competition pushed the firm to innovate.","vi":"Mối đe dọa cạnh tranh được nhận thức đã thúc đẩy công ty đổi mới."},{"en":"Policies often respond to a perceived threat rather than a real one.","vi":"Chính sách thường phản ứng với mối đe dọa được nhận thức hơn là mối đe dọa thực."}]','[]',NULL,'/pərˈsiːvd θret/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4865,'colloc-11-01',75,'perform a function','thực hiện một chức năng','v + n','[{"en":"Each organ in the body performs a vital function.","vi":"Mỗi cơ quan trong cơ thể thực hiện một chức năng thiết yếu."},{"en":"These cells perform a function essential to the immune system.","vi":"Những tế bào này thực hiện một chức năng thiết yếu đối với hệ miễn dịch."},{"en":"The software can perform a complex function with a single click.","vi":"Phần mềm có thể thực hiện một chức năng phức tạp chỉ với một cú nhấp."}]','[]',NULL,'/pərˈfɔːrm ə ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4866,'colloc-11-01',76,'perform a study','tiến hành một nghiên cứu','v + n','[{"en":"Scientists performed a study to test the new vaccine''s safety.","vi":"Các nhà khoa học đã tiến hành một nghiên cứu để kiểm tra độ an toàn của vắc-xin mới."},{"en":"The team performed a study on sleep and academic performance.","vi":"Nhóm đã tiến hành một nghiên cứu về giấc ngủ và kết quả học tập."},{"en":"We performed a study involving over two thousand participants.","vi":"Chúng tôi đã tiến hành một nghiên cứu với hơn hai nghìn người tham gia."}]','[]',NULL,'/pərˈfɔːrm ə ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4867,'colloc-11-01',77,'perform a task','thực hiện một nhiệm vụ','v + n','[{"en":"Participants were asked to perform a simple memory task.","vi":"Người tham gia được yêu cầu thực hiện một nhiệm vụ ghi nhớ đơn giản."},{"en":"Robots can perform a repetitive task far faster than humans.","vi":"Robot có thể thực hiện một nhiệm vụ lặp lại nhanh hơn nhiều so với con người."},{"en":"Stress can affect how well we perform a difficult task.","vi":"Căng thẳng có thể ảnh hưởng đến việc ta thực hiện một nhiệm vụ khó tốt đến đâu."}]','[]',NULL,'/pərˈfɔːrm ə tæsk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4868,'colloc-11-01',78,'personal choice','lựa chọn cá nhân','adj + n','[{"en":"Whether to attend the ceremony is ultimately a personal choice.","vi":"Có dự buổi lễ hay không rốt cuộc là một lựa chọn cá nhân."},{"en":"The study respects each participant''s personal choice about treatment.","vi":"Nghiên cứu tôn trọng lựa chọn cá nhân của mỗi người tham gia về việc điều trị."},{"en":"Diet is often framed as a personal choice rather than policy.","vi":"Chế độ ăn thường được xem là lựa chọn cá nhân hơn là vấn đề chính sách."}]','[]',NULL,'/ˈpɜːrsənəl tʃɔɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4869,'colloc-11-01',79,'personal circumstances','hoàn cảnh cá nhân','adj + n','[{"en":"Students may defer enrollment due to difficult personal circumstances.","vi":"Sinh viên có thể hoãn nhập học vì hoàn cảnh cá nhân khó khăn."},{"en":"The court considered her personal circumstances before sentencing.","vi":"Tòa án đã xem xét hoàn cảnh cá nhân của cô trước khi tuyên án."},{"en":"Each application is assessed against the applicant''s personal circumstances.","vi":"Mỗi hồ sơ được đánh giá dựa trên hoàn cảnh cá nhân của người nộp đơn."}]','[]',NULL,'/ˈpɜːrsənəl ˈsɜːrkəmstænsəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4870,'colloc-11-01',80,'personal communication','trao đổi cá nhân','adj + n','[{"en":"The author cited a personal communication from a leading expert.","vi":"Tác giả đã trích dẫn một trao đổi cá nhân từ một chuyên gia hàng đầu."},{"en":"Details were confirmed through personal communication with the researcher.","vi":"Các chi tiết được xác nhận qua trao đổi cá nhân với nhà nghiên cứu."},{"en":"In academic writing, personal communication is cited carefully.","vi":"Trong văn viết học thuật, trao đổi cá nhân được trích dẫn một cách cẩn thận."}]','[]',NULL,'/ˈpɜːrsənəl kəˌmjuːnɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4871,'colloc-11-01',81,'personal contact','tiếp xúc cá nhân','adj + n','[{"en":"Personal contact with mentors often shapes a student''s career path.","vi":"Tiếp xúc cá nhân với người hướng dẫn thường định hình con đường sự nghiệp của sinh viên."},{"en":"Online learning can reduce personal contact between classmates.","vi":"Học trực tuyến có thể làm giảm tiếp xúc cá nhân giữa các bạn cùng lớp."},{"en":"She built her network through years of personal contact.","vi":"Cô xây dựng mạng lưới của mình qua nhiều năm tiếp xúc cá nhân."}]','[]',NULL,'/ˈpɜːrsənəl ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4872,'colloc-11-01',82,'personal control','khả năng tự kiểm soát','adj + n','[{"en":"A sense of personal control reduces stress in difficult situations.","vi":"Cảm giác tự kiểm soát giúp giảm căng thẳng trong các tình huống khó khăn."},{"en":"The program aims to increase patients'' personal control over recovery.","vi":"Chương trình nhằm tăng khả năng tự kiểm soát của bệnh nhân đối với việc hồi phục."},{"en":"People with greater personal control tend to feel more satisfied.","vi":"Những người có khả năng tự kiểm soát cao hơn thường cảm thấy hài lòng hơn."}]','[]',NULL,'/ˈpɜːrsənəl kənˈtroʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4873,'colloc-11-01',83,'personal experience','trải nghiệm cá nhân','adj + n','[{"en":"She drew on personal experience to illustrate her main argument.","vi":"Cô dựa vào trải nghiệm cá nhân để minh họa cho luận điểm chính của mình."},{"en":"Personal experience alone is rarely enough to prove a theory.","vi":"Riêng trải nghiệm cá nhân hiếm khi đủ để chứng minh một lý thuyết."},{"en":"The interviews captured each nurse''s personal experience of the crisis.","vi":"Các cuộc phỏng vấn ghi lại trải nghiệm cá nhân của mỗi y tá về cuộc khủng hoảng."}]','[]',NULL,'/ˈpɜːrsənəl ɪkˈspɪriəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4874,'colloc-11-01',84,'personal information','thông tin cá nhân','adj + n','[{"en":"The website collects personal information without clear consent.","vi":"Trang web thu thập thông tin cá nhân mà không có sự đồng ý rõ ràng."},{"en":"Researchers must protect the personal information of all participants.","vi":"Các nhà nghiên cứu phải bảo vệ thông tin cá nhân của mọi người tham gia."},{"en":"New laws restrict how companies share personal information online.","vi":"Luật mới hạn chế cách các công ty chia sẻ thông tin cá nhân trên mạng."}]','[]',NULL,'/ˈpɜːrsənəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4875,'colloc-11-01',85,'personal interest','sở thích cá nhân','adj + n','[{"en":"His personal interest in astronomy led him to study physics.","vi":"Sở thích cá nhân về thiên văn đã đưa anh đến với việc học vật lý."},{"en":"The topic reflects the writer''s deep personal interest in history.","vi":"Chủ đề phản ánh sở thích cá nhân sâu sắc của tác giả về lịch sử."},{"en":"Students perform better when they have a personal interest in the subject.","vi":"Sinh viên học tốt hơn khi có sở thích cá nhân với môn học."}]','[]',NULL,'/ˈpɜːrsənəl ˈɪntrəst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4876,'colloc-11-01',86,'personal knowledge','hiểu biết cá nhân','adj + n','[{"en":"The witness spoke from personal knowledge of the events.","vi":"Nhân chứng nói dựa trên hiểu biết cá nhân về các sự kiện."},{"en":"Personal knowledge of the region helped the team plan the survey.","vi":"Hiểu biết cá nhân về khu vực đã giúp nhóm lên kế hoạch khảo sát."},{"en":"Scientists must distinguish personal knowledge from verified evidence.","vi":"Các nhà khoa học phải phân biệt hiểu biết cá nhân với bằng chứng đã được kiểm chứng."}]','[]',NULL,'/ˈpɜːrsənəl ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4877,'colloc-11-01',87,'personal quality','phẩm chất cá nhân','adj + n','[{"en":"Patience is a personal quality valued highly in teaching.","vi":"Kiên nhẫn là một phẩm chất cá nhân được đánh giá cao trong giảng dạy."},{"en":"Employers assess each candidate''s personal qualities during interviews.","vi":"Nhà tuyển dụng đánh giá phẩm chất cá nhân của từng ứng viên trong các cuộc phỏng vấn."},{"en":"Leadership depends on personal qualities as much as on skills.","vi":"Khả năng lãnh đạo phụ thuộc vào phẩm chất cá nhân nhiều như vào kỹ năng."}]','[]',NULL,'/ˈpɜːrsənəl ˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4878,'colloc-11-01',88,'personal relationship','mối quan hệ cá nhân','adj + n','[{"en":"A strong personal relationship with clients improves long-term trust.","vi":"Một mối quan hệ cá nhân vững chắc với khách hàng cải thiện niềm tin lâu dài."},{"en":"The study explored how personal relationships affect job satisfaction.","vi":"Nghiên cứu khám phá cách các mối quan hệ cá nhân ảnh hưởng đến sự hài lòng công việc."},{"en":"Maintaining a personal relationship across distance can be challenging.","vi":"Duy trì một mối quan hệ cá nhân qua khoảng cách có thể đầy thử thách."}]','[]',NULL,'/ˈpɜːrsənəl rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4879,'colloc-11-01',89,'personal responsibility','trách nhiệm cá nhân','adj + n','[{"en":"The campaign encourages personal responsibility for the environment.","vi":"Chiến dịch khuyến khích trách nhiệm cá nhân đối với môi trường."},{"en":"He accepted full personal responsibility for the mistake.","vi":"Anh đã chấp nhận hoàn toàn trách nhiệm cá nhân về sai lầm đó."},{"en":"Good health partly depends on a sense of personal responsibility.","vi":"Sức khỏe tốt một phần phụ thuộc vào ý thức trách nhiệm cá nhân."}]','[]',NULL,'/ˈpɜːrsənəl rɪˌspɑːnsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4880,'colloc-11-01',90,'personal safety','an toàn cá nhân','adj + n','[{"en":"The training covered personal safety in remote fieldwork settings.","vi":"Khóa đào tạo bao gồm an toàn cá nhân trong môi trường khảo sát thực địa xa xôi."},{"en":"Many residents worry about personal safety after dark.","vi":"Nhiều cư dân lo lắng về an toàn cá nhân sau khi trời tối."},{"en":"Workers received clear guidelines on personal safety procedures.","vi":"Người lao động nhận được hướng dẫn rõ ràng về các quy trình an toàn cá nhân."}]','[]',NULL,'/ˈpɜːrsənəl ˈseɪfti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4881,'colloc-11-01',91,'personal space','không gian riêng tư','adj + n','[{"en":"Crowded trains can make passengers feel they lack personal space.","vi":"Tàu đông đúc có thể khiến hành khách cảm thấy thiếu không gian riêng tư."},{"en":"Notions of personal space vary widely across different cultures.","vi":"Quan niệm về không gian riêng tư khác nhau rất nhiều giữa các nền văn hóa."},{"en":"Respecting personal space is important during one-on-one interviews.","vi":"Tôn trọng không gian riêng tư là điều quan trọng trong các cuộc phỏng vấn riêng."}]','[]',NULL,'/ˈpɜːrsənəl speɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4882,'colloc-11-01',92,'physical activity','hoạt động thể chất','adj + n','[{"en":"Regular physical activity lowers the risk of heart disease.","vi":"Hoạt động thể chất đều đặn làm giảm nguy cơ mắc bệnh tim."},{"en":"The study linked daily physical activity to better mood.","vi":"Nghiên cứu liên hệ hoạt động thể chất hằng ngày với tâm trạng tốt hơn."},{"en":"Schools should provide more time for physical activity.","vi":"Các trường học nên dành nhiều thời gian hơn cho hoạt động thể chất."}]','[]',NULL,'/ˈfɪzɪkəl ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4883,'colloc-11-01',93,'physical appearance','ngoại hình','adj + n','[{"en":"First impressions often rely too heavily on physical appearance.","vi":"Ấn tượng đầu tiên thường phụ thuộc quá nhiều vào ngoại hình."},{"en":"The study examined how physical appearance affects hiring decisions.","vi":"Nghiên cứu xem xét ngoại hình ảnh hưởng thế nào đến quyết định tuyển dụng."},{"en":"Media pressure about physical appearance can harm young people.","vi":"Áp lực từ truyền thông về ngoại hình có thể gây hại cho người trẻ."}]','[]',NULL,'/ˈfɪzɪkəl əˈpɪrəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4884,'colloc-11-01',94,'physical characteristics','đặc điểm thể chất','adj + n','[{"en":"Scientists recorded the physical characteristics of each specimen.","vi":"Các nhà khoa học đã ghi lại đặc điểm thể chất của từng mẫu vật."},{"en":"Soil''s physical characteristics affect how well crops grow.","vi":"Đặc điểm thể chất của đất ảnh hưởng đến mức độ phát triển của cây trồng."},{"en":"The two species differ in several key physical characteristics.","vi":"Hai loài khác nhau ở một vài đặc điểm thể chất quan trọng."}]','[]',NULL,'/ˈfɪzɪkəl ˌkærəktəˈrɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4885,'colloc-11-01',95,'physical contact','tiếp xúc cơ thể','adj + n','[{"en":"Some sports involve frequent physical contact between players.","vi":"Một số môn thể thao có nhiều tiếp xúc cơ thể giữa các cầu thủ."},{"en":"Norms about physical contact differ greatly across cultures.","vi":"Các chuẩn mực về tiếp xúc cơ thể khác nhau rất nhiều giữa các nền văn hóa."},{"en":"The disease spreads mainly through direct physical contact.","vi":"Căn bệnh lây lan chủ yếu qua tiếp xúc cơ thể trực tiếp."}]','[]',NULL,'/ˈfɪzɪkəl ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4886,'colloc-11-01',96,'physical development','sự phát triển thể chất','adj + n','[{"en":"Good nutrition supports healthy physical development in children.","vi":"Dinh dưỡng tốt hỗ trợ sự phát triển thể chất khỏe mạnh ở trẻ em."},{"en":"The study tracked physical development from birth to adolescence.","vi":"Nghiên cứu theo dõi sự phát triển thể chất từ khi sinh đến tuổi thiếu niên."},{"en":"Play is essential for both physical and cognitive development.","vi":"Vui chơi là thiết yếu cho cả sự phát triển thể chất lẫn nhận thức."}]','[]',NULL,'/ˈfɪzɪkəl dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4887,'colloc-11-01',97,'physical environment','môi trường vật chất','adj + n','[{"en":"The physical environment of a classroom can affect concentration.","vi":"Môi trường vật chất của lớp học có thể ảnh hưởng đến sự tập trung."},{"en":"Urban planning shapes the physical environment we live in.","vi":"Quy hoạch đô thị định hình môi trường vật chất mà chúng ta sống trong đó."},{"en":"Animals adapt their behavior to the surrounding physical environment.","vi":"Động vật thích nghi hành vi với môi trường vật chất xung quanh."}]','[]',NULL,'/ˈfɪzɪkəl ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4888,'colloc-11-01',98,'physical features','đặc trưng vật lý','adj + n','[{"en":"The map highlights the main physical features of the landscape.","vi":"Bản đồ làm nổi bật các đặc trưng vật lý chính của cảnh quan."},{"en":"Geographers study the physical features that shape river systems.","vi":"Các nhà địa lý nghiên cứu những đặc trưng vật lý định hình hệ thống sông."},{"en":"Distinct physical features make the region easy to identify.","vi":"Những đặc trưng vật lý riêng biệt khiến khu vực dễ nhận ra."}]','[]',NULL,'/ˈfɪzɪkəl ˈfiːtʃərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4889,'colloc-11-01',99,'physical health','sức khỏe thể chất','adj + n','[{"en":"Sleep has a strong impact on overall physical health.","vi":"Giấc ngủ có tác động mạnh đến sức khỏe thể chất tổng thể."},{"en":"The program improves both physical health and mental wellbeing.","vi":"Chương trình cải thiện cả sức khỏe thể chất lẫn tinh thần."},{"en":"Poor diet over time damages long-term physical health.","vi":"Chế độ ăn kém theo thời gian gây hại cho sức khỏe thể chất lâu dài."}]','[]',NULL,'/ˈfɪzɪkəl helθ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4890,'colloc-11-01',100,'physical needs','nhu cầu thể chất','adj + n','[{"en":"Good care addresses both the physical needs and emotional needs.","vi":"Sự chăm sóc tốt đáp ứng cả nhu cầu thể chất lẫn nhu cầu cảm xúc."},{"en":"Infants depend entirely on adults to meet their physical needs.","vi":"Trẻ sơ sinh hoàn toàn phụ thuộc vào người lớn để đáp ứng nhu cầu thể chất."},{"en":"Shelter design must consider the physical needs of residents.","vi":"Thiết kế nơi trú ẩn phải xem xét nhu cầu thể chất của cư dân."}]','[]',NULL,'/ˈfɪzɪkəl niːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4891,'colloc-11-01',101,'physical presence','sự hiện diện trực tiếp','adj + n','[{"en":"The teacher''s physical presence helped keep students focused.","vi":"Sự hiện diện trực tiếp của giáo viên giúp học sinh tập trung."},{"en":"Remote work reduces the need for physical presence in offices.","vi":"Làm việc từ xa giảm nhu cầu hiện diện trực tiếp tại văn phòng."},{"en":"A strong physical presence can reassure people during emergencies.","vi":"Một sự hiện diện trực tiếp mạnh mẽ có thể trấn an mọi người khi khẩn cấp."}]','[]',NULL,'/ˈfɪzɪkəl ˈprezəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4892,'colloc-11-01',102,'physical properties','tính chất vật lý','adj + n','[{"en":"The experiment measured the physical properties of the new material.","vi":"Thí nghiệm đo lường tính chất vật lý của vật liệu mới."},{"en":"Temperature changes alter the physical properties of metals.","vi":"Sự thay đổi nhiệt độ làm thay đổi tính chất vật lý của kim loại."},{"en":"Engineers test physical properties before approving any design.","vi":"Các kỹ sư kiểm tra tính chất vật lý trước khi phê duyệt bất kỳ thiết kế nào."}]','[]',NULL,'/ˈfɪzɪkəl ˈprɑːpərtiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4893,'colloc-11-01',103,'physical proximity','khoảng cách gần về vật lý','adj + n','[{"en":"Physical proximity often increases the chance of friendship forming.","vi":"Khoảng cách gần về vật lý thường làm tăng khả năng hình thành tình bạn."},{"en":"The study found physical proximity boosted team collaboration.","vi":"Nghiên cứu phát hiện khoảng cách gần về vật lý thúc đẩy hợp tác nhóm."},{"en":"Online tools reduce the importance of physical proximity at work.","vi":"Công cụ trực tuyến làm giảm tầm quan trọng của khoảng cách gần về vật lý trong công việc."}]','[]',NULL,'/ˈfɪzɪkəl prɑːkˈsɪməti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4894,'colloc-11-01',104,'physical science','khoa học tự nhiên','adj + n','[{"en":"She specialized in physical science before turning to engineering.","vi":"Cô chuyên về khoa học tự nhiên trước khi chuyển sang kỹ thuật."},{"en":"The curriculum balances physical science with social studies.","vi":"Chương trình học cân bằng giữa khoa học tự nhiên và khoa học xã hội."},{"en":"Advances in physical science have transformed modern medicine.","vi":"Những tiến bộ trong khoa học tự nhiên đã biến đổi y học hiện đại."}]','[]',NULL,'/ˈfɪzɪkəl ˈsaɪəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4895,'colloc-11-01',105,'physical space','không gian vật lý','adj + n','[{"en":"The library lacks enough physical space for group study.","vi":"Thư viện thiếu không gian vật lý đủ cho việc học nhóm."},{"en":"Digital archives store records without taking up physical space.","vi":"Kho lưu trữ số lưu giữ hồ sơ mà không chiếm không gian vật lý."},{"en":"The design maximizes physical space in small apartments.","vi":"Thiết kế tận dụng tối đa không gian vật lý trong các căn hộ nhỏ."}]','[]',NULL,'/ˈfɪzɪkəl speɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4896,'colloc-11-01',106,'physical symptom','triệu chứng thể chất','adj + n','[{"en":"Anxiety can produce a physical symptom such as a racing heart.","vi":"Lo âu có thể gây ra triệu chứng thể chất như tim đập nhanh."},{"en":"Doctors look for any physical symptom that signals infection.","vi":"Bác sĩ tìm kiếm bất kỳ triệu chứng thể chất nào báo hiệu nhiễm trùng."},{"en":"Stress often shows up first as a physical symptom.","vi":"Căng thẳng thường biểu hiện đầu tiên dưới dạng một triệu chứng thể chất."}]','[]',NULL,'/ˈfɪzɪkəl ˈsɪmptəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4897,'colloc-11-01',107,'physical world','thế giới vật chất','adj + n','[{"en":"Science seeks to explain how the physical world works.","vi":"Khoa học tìm cách giải thích cách thế giới vật chất vận hành."},{"en":"Virtual reality blurs the line with the physical world.","vi":"Thực tế ảo làm mờ ranh giới với thế giới vật chất."},{"en":"Children learn about the physical world through play and exploration.","vi":"Trẻ em học về thế giới vật chất thông qua vui chơi và khám phá."}]','[]',NULL,'/ˈfɪzɪkəl wɜːrld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4898,'colloc-11-01',108,'pilot study','nghiên cứu thí điểm','n + n','[{"en":"A pilot study tested the survey before the full rollout.","vi":"Một nghiên cứu thí điểm đã kiểm tra bảng khảo sát trước khi triển khai đầy đủ."},{"en":"Results from the pilot study guided the final research design.","vi":"Kết quả từ nghiên cứu thí điểm đã định hướng thiết kế nghiên cứu cuối cùng."},{"en":"The pilot study involved only thirty volunteers.","vi":"Nghiên cứu thí điểm chỉ có ba mươi tình nguyện viên tham gia."}]','[]',NULL,'/ˈpaɪlət ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4899,'colloc-11-01',109,'pioneering work','công trình tiên phong','adj + n','[{"en":"Her pioneering work transformed how we understand genetics.","vi":"Công trình tiên phong của bà đã thay đổi cách chúng ta hiểu về di truyền."},{"en":"The award honored decades of pioneering work in robotics.","vi":"Giải thưởng vinh danh nhiều thập kỷ công trình tiên phong trong lĩnh vực robot."},{"en":"Pioneering work in this field often goes unrecognized for years.","vi":"Công trình tiên phong trong lĩnh vực này thường không được công nhận trong nhiều năm."}]','[]',NULL,'/ˌpaɪəˈnɪrɪŋ wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4900,'colloc-11-01',110,'pivotal role','vai trò then chốt','adj + n','[{"en":"Education plays a pivotal role in reducing inequality.","vi":"Giáo dục đóng vai trò then chốt trong việc giảm bất bình đẳng."},{"en":"She played a pivotal role in negotiating the agreement.","vi":"Cô đã đóng vai trò then chốt trong việc đàm phán thỏa thuận."},{"en":"Technology has a pivotal role in modern healthcare delivery.","vi":"Công nghệ giữ vai trò then chốt trong việc cung cấp dịch vụ y tế hiện đại."}]','[]',NULL,'/ˈpɪvətəl roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4901,'colloc-11-01',111,'place emphasis','đặt sự nhấn mạnh','v + n','[{"en":"The course places emphasis on practical skills over theory.","vi":"Khóa học đặt sự nhấn mạnh vào kỹ năng thực hành hơn là lý thuyết."},{"en":"Researchers place emphasis on reproducible and transparent methods.","vi":"Các nhà nghiên cứu đặt sự nhấn mạnh vào phương pháp minh bạch và có thể tái lập."},{"en":"The report places emphasis on the needs of rural communities.","vi":"Báo cáo đặt sự nhấn mạnh vào nhu cầu của các cộng đồng nông thôn."}]','[]',NULL,'/pleɪs ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4902,'colloc-11-01',112,'planning stage','giai đoạn lập kế hoạch','n + n','[{"en":"The project is still in its early planning stage.","vi":"Dự án vẫn còn trong giai đoạn lập kế hoạch ban đầu."},{"en":"Stakeholders were consulted during the planning stage of the program.","vi":"Các bên liên quan được tham vấn trong giai đoạn lập kế hoạch của chương trình."},{"en":"Many problems can be avoided at the planning stage.","vi":"Nhiều vấn đề có thể được tránh ngay từ giai đoạn lập kế hoạch."}]','[]',NULL,'/ˈplænɪŋ steɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4903,'colloc-11-01',113,'plausible explanation','lời giải thích hợp lý','adj + n','[{"en":"The theory offers a plausible explanation for the unusual results.","vi":"Lý thuyết đưa ra một lời giải thích hợp lý cho những kết quả bất thường."},{"en":"No plausible explanation has yet been found for the anomaly.","vi":"Vẫn chưa tìm ra lời giải thích hợp lý nào cho điều bất thường này."},{"en":"A plausible explanation must fit all the available evidence.","vi":"Một lời giải thích hợp lý phải phù hợp với mọi bằng chứng hiện có."}]','[]',NULL,'/ˈplɔːzəbəl ˌekspləˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4904,'colloc-11-01',114,'play a role in','đóng vai trò trong','v + n','[{"en":"Genes play a role in determining a person''s risk of disease.","vi":"Gen đóng vai trò trong việc xác định nguy cơ mắc bệnh của một người."},{"en":"Social media plays a role in shaping public opinion today.","vi":"Mạng xã hội đóng vai trò trong việc định hình dư luận ngày nay."},{"en":"Climate change plays a role in the spread of certain diseases.","vi":"Biến đổi khí hậu đóng vai trò trong sự lan rộng của một số bệnh."}]','[]',NULL,'/pleɪ ə roʊl ɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4905,'colloc-11-01',115,'political activism','hoạt động chính trị tích cực','adj + n','[{"en":"Student political activism grew sharply during the 1960s.","vi":"Hoạt động chính trị tích cực của sinh viên tăng mạnh trong những năm 1960."},{"en":"Online platforms have changed the nature of political activism.","vi":"Các nền tảng trực tuyến đã thay đổi bản chất của hoạt động chính trị tích cực."},{"en":"Her political activism focused on environmental justice.","vi":"Hoạt động chính trị tích cực của bà tập trung vào công lý môi trường."}]','[]',NULL,'/pəˈlɪtɪkəl ˈæktɪvɪzəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4906,'colloc-11-01',116,'political activity','hoạt động chính trị','adj + n','[{"en":"The law restricts political activity by certain public officials.","vi":"Luật hạn chế hoạt động chính trị của một số quan chức nhà nước."},{"en":"Voter turnout is one measure of political activity.","vi":"Tỷ lệ cử tri đi bầu là một thước đo của hoạt động chính trị."},{"en":"Economic hardship often increases political activity among citizens.","vi":"Khó khăn kinh tế thường làm gia tăng hoạt động chính trị trong dân chúng."}]','[]',NULL,'/pəˈlɪtɪkəl ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4907,'colloc-11-01',117,'political agenda','chương trình nghị sự chính trị','adj + n','[{"en":"Education reform sits high on the government''s political agenda.","vi":"Cải cách giáo dục nằm ở vị trí cao trong chương trình nghị sự chính trị của chính phủ."},{"en":"Critics argued the report served a hidden political agenda.","vi":"Các nhà phê bình cho rằng báo cáo phục vụ một chương trình nghị sự chính trị ẩn giấu."},{"en":"Each party tried to set the national political agenda.","vi":"Mỗi đảng đều cố gắng định hình chương trình nghị sự chính trị quốc gia."}]','[]',NULL,'/pəˈlɪtɪkəl əˈdʒendə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4908,'colloc-11-01',118,'political arena','vũ đài chính trị','adj + n','[{"en":"She entered the political arena after a long legal career.","vi":"Bà bước vào vũ đài chính trị sau một sự nghiệp pháp lý dài."},{"en":"Women remain underrepresented in the political arena.","vi":"Phụ nữ vẫn còn ít được đại diện trên vũ đài chính trị."},{"en":"The scandal reshaped the entire political arena overnight.","vi":"Vụ bê bối đã định hình lại toàn bộ vũ đài chính trị chỉ sau một đêm."}]','[]',NULL,'/pəˈlɪtɪkəl əˈriːnə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4909,'colloc-11-01',119,'political authority','quyền lực chính trị','adj + n','[{"en":"The constitution defines the limits of political authority.","vi":"Hiến pháp xác định giới hạn của quyền lực chính trị."},{"en":"Local councils were granted greater political authority.","vi":"Các hội đồng địa phương được trao quyền lực chính trị lớn hơn."},{"en":"Religious leaders once held significant political authority.","vi":"Các lãnh đạo tôn giáo từng nắm giữ quyền lực chính trị đáng kể."}]','[]',NULL,'/pəˈlɪtɪkəl əˈθɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4910,'colloc-11-01',120,'political circumstances','hoàn cảnh chính trị','adj + n','[{"en":"The reform succeeded due to favorable political circumstances.","vi":"Cuộc cải cách thành công nhờ hoàn cảnh chính trị thuận lợi."},{"en":"Changing political circumstances forced the policy to be revised.","vi":"Hoàn cảnh chính trị thay đổi buộc chính sách phải được sửa đổi."},{"en":"Historians stress the political circumstances of the era.","vi":"Các nhà sử học nhấn mạnh hoàn cảnh chính trị của thời đại đó."}]','[]',NULL,'/pəˈlɪtɪkəl ˈsɜːrkəmstænsəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4911,'colloc-11-01',121,'political climate','bầu không khí chính trị','adj + n','[{"en":"The tense political climate discouraged open public debate.","vi":"Bầu không khí chính trị căng thẳng đã cản trở tranh luận công khai."},{"en":"Investors are wary because of the uncertain political climate.","vi":"Các nhà đầu tư thận trọng vì bầu không khí chính trị bất ổn."},{"en":"The reform reflects the changing political climate of the decade.","vi":"Cuộc cải cách phản ánh bầu không khí chính trị đang thay đổi của thập kỷ."}]','[]',NULL,'/pəˈlɪtɪkəl ˈklaɪmət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4912,'colloc-11-01',122,'political conflict','xung đột chính trị','adj + n','[{"en":"Years of political conflict left the country deeply divided.","vi":"Nhiều năm xung đột chính trị đã khiến đất nước bị chia rẽ sâu sắc."},{"en":"The treaty aimed to resolve longstanding political conflict.","vi":"Hiệp ước nhằm giải quyết xung đột chính trị kéo dài."},{"en":"Economic inequality often fuels political conflict.","vi":"Bất bình đẳng kinh tế thường thổi bùng xung đột chính trị."}]','[]',NULL,'/pəˈlɪtɪkəl ˈkɑːnflɪkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4913,'colloc-11-01',123,'political consciousness','ý thức chính trị','adj + n','[{"en":"The movement raised the political consciousness of young voters.","vi":"Phong trào đã nâng cao ý thức chính trị của các cử tri trẻ."},{"en":"Education can deepen a citizen''s political consciousness.","vi":"Giáo dục có thể làm sâu sắc thêm ý thức chính trị của công dân."},{"en":"Rising political consciousness fueled demands for reform.","vi":"Ý thức chính trị gia tăng đã thúc đẩy các đòi hỏi cải cách."}]','[]',NULL,'/pəˈlɪtɪkəl ˈkɑːnʃəsnəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4914,'colloc-11-01',124,'political consensus','sự đồng thuận chính trị','adj + n','[{"en":"Reaching a political consensus on the budget proved difficult.","vi":"Đạt được sự đồng thuận chính trị về ngân sách tỏ ra khó khăn."},{"en":"There is broad political consensus that healthcare needs reform.","vi":"Có sự đồng thuận chính trị rộng rãi rằng y tế cần được cải cách."},{"en":"The fragile political consensus collapsed within months.","vi":"Sự đồng thuận chính trị mong manh đã sụp đổ chỉ trong vài tháng."}]','[]',NULL,'/pəˈlɪtɪkəl kənˈsensəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4915,'colloc-11-01',125,'political consequences','hệ quả chính trị','adj + n','[{"en":"The decision had serious political consequences for the leadership.","vi":"Quyết định này gây ra những hệ quả chính trị nghiêm trọng cho ban lãnh đạo."},{"en":"Economic crises often carry far-reaching political consequences.","vi":"Khủng hoảng kinh tế thường kéo theo những hệ quả chính trị sâu rộng."},{"en":"Analysts warned about the political consequences of inaction.","vi":"Các nhà phân tích cảnh báo về hệ quả chính trị của việc không hành động."}]','[]',NULL,'/pəˈlɪtɪkəl ˈkɑːnsəkwensəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4916,'colloc-11-01',126,'political consideration','yếu tố cân nhắc chính trị','adj + n','[{"en":"Political considerations often shape how budgets are allocated.","vi":"Các yếu tố cân nhắc chính trị thường định hình cách phân bổ ngân sách."},{"en":"The minister insisted no political consideration influenced the ruling.","vi":"Bộ trưởng khẳng định không có yếu tố cân nhắc chính trị nào ảnh hưởng đến phán quyết."},{"en":"Scientific advice should outweigh short-term political considerations.","vi":"Lời khuyên khoa học nên được coi trọng hơn các yếu tố cân nhắc chính trị ngắn hạn."}]','[]',NULL,'/pəˈlɪtɪkəl kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4917,'colloc-11-01',127,'political context','bối cảnh chính trị','adj + n','[{"en":"The novel can only be understood in its political context.","vi":"Cuốn tiểu thuyết chỉ có thể được hiểu trong bối cảnh chính trị của nó."},{"en":"Researchers examined the policy within its broader political context.","vi":"Các nhà nghiên cứu xem xét chính sách trong bối cảnh chính trị rộng hơn."},{"en":"The political context of the war shaped its outcome.","vi":"Bối cảnh chính trị của cuộc chiến đã định hình kết cục của nó."}]','[]',NULL,'/pəˈlɪtɪkəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4918,'colloc-11-01',128,'political culture','văn hóa chính trị','adj + n','[{"en":"A nation''s political culture shapes how citizens engage with power.","vi":"Văn hóa chính trị của một quốc gia định hình cách công dân tham gia vào quyền lực."},{"en":"The book compares political culture across several democracies.","vi":"Cuốn sách so sánh văn hóa chính trị giữa nhiều nền dân chủ."},{"en":"Distrust of authority is rooted in the local political culture.","vi":"Sự ngờ vực chính quyền bắt nguồn từ văn hóa chính trị địa phương."}]','[]',NULL,'/pəˈlɪtɪkəl ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4919,'colloc-11-01',129,'political debate','tranh luận chính trị','adj + n','[{"en":"Immigration remains at the center of political debate.","vi":"Vấn đề nhập cư vẫn là trung tâm của tranh luận chính trị."},{"en":"The reform sparked intense political debate across the country.","vi":"Cuộc cải cách đã châm ngòi cho tranh luận chính trị gay gắt trên cả nước."},{"en":"Television transformed the style of modern political debate.","vi":"Truyền hình đã biến đổi phong cách của tranh luận chính trị hiện đại."}]','[]',NULL,'/pəˈlɪtɪkəl dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4920,'colloc-11-01',130,'political dimension','khía cạnh chính trị','adj + n','[{"en":"The crisis has an economic and a political dimension.","vi":"Cuộc khủng hoảng có cả khía cạnh kinh tế lẫn khía cạnh chính trị."},{"en":"Scholars often overlook the political dimension of religious change.","vi":"Các học giả thường bỏ qua khía cạnh chính trị của sự thay đổi tôn giáo."},{"en":"Every major reform carries a political dimension.","vi":"Mọi cuộc cải cách lớn đều mang một khía cạnh chính trị."}]','[]',NULL,'/pəˈlɪtɪkəl dɪˈmenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4921,'colloc-11-01',131,'political economy','kinh tế chính trị','adj + n','[{"en":"The course introduces the basics of political economy.","vi":"Khóa học giới thiệu những kiến thức cơ bản về kinh tế chính trị."},{"en":"Her thesis analyzed the political economy of global trade.","vi":"Luận án của cô phân tích kinh tế chính trị của thương mại toàn cầu."},{"en":"Political economy examines how power and markets interact.","vi":"Kinh tế chính trị nghiên cứu cách quyền lực và thị trường tương tác."}]','[]',NULL,'/pəˈlɪtɪkəl ɪˈkɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4922,'colloc-11-01',132,'political environment','môi trường chính trị','adj + n','[{"en":"A stable political environment encourages foreign investment.","vi":"Một môi trường chính trị ổn định khuyến khích đầu tư nước ngoài."},{"en":"The reforms reshaped the country''s political environment.","vi":"Các cuộc cải cách đã định hình lại môi trường chính trị của đất nước."},{"en":"Businesses must adapt to a shifting political environment.","vi":"Các doanh nghiệp phải thích nghi với môi trường chính trị đang thay đổi."}]','[]',NULL,'/pəˈlɪtɪkəl ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4923,'colloc-11-01',133,'political factors','các yếu tố chính trị','adj + n','[{"en":"Political factors strongly influenced where the funds were spent.","vi":"Các yếu tố chính trị đã ảnh hưởng mạnh đến nơi nguồn quỹ được chi tiêu."},{"en":"The analysis weighed economic and political factors together.","vi":"Bản phân tích cân nhắc cùng lúc các yếu tố kinh tế và chính trị."},{"en":"Political factors often delay important infrastructure projects.","vi":"Các yếu tố chính trị thường làm chậm trễ các dự án hạ tầng quan trọng."}]','[]',NULL,'/pəˈlɪtɪkəl ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4924,'colloc-11-01',134,'political identity','bản sắc chính trị','adj + n','[{"en":"Many young people form their political identity at university.","vi":"Nhiều người trẻ hình thành bản sắc chính trị của mình ở đại học."},{"en":"Region and religion both shape political identity here.","vi":"Cả vùng miền lẫn tôn giáo đều định hình bản sắc chính trị ở đây."},{"en":"The study explored how migration affects political identity.","vi":"Nghiên cứu khám phá cách di cư ảnh hưởng đến bản sắc chính trị."}]','[]',NULL,'/pəˈlɪtɪkəl aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4925,'colloc-11-01',135,'political ideology','hệ tư tưởng chính trị','adj + n','[{"en":"His political ideology shifted noticeably over the decades.","vi":"Hệ tư tưởng chính trị của ông thay đổi rõ rệt qua nhiều thập kỷ."},{"en":"The party''s political ideology centers on individual freedom.","vi":"Hệ tư tưởng chính trị của đảng xoay quanh tự do cá nhân."},{"en":"Media can reinforce a particular political ideology.","vi":"Truyền thông có thể củng cố một hệ tư tưởng chính trị nhất định."}]','[]',NULL,'/pəˈlɪtɪkəl ˌaɪdiˈɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4926,'colloc-11-01',136,'political implications','hàm ý chính trị','adj + n','[{"en":"The discovery has significant political implications for the region.","vi":"Phát hiện này có những hàm ý chính trị quan trọng đối với khu vực."},{"en":"Researchers rarely discuss the political implications of their findings.","vi":"Các nhà nghiên cứu hiếm khi bàn về hàm ý chính trị trong phát hiện của họ."},{"en":"The ruling carries political implications well beyond the courtroom.","vi":"Phán quyết này mang hàm ý chính trị vượt xa khỏi phòng xử án."}]','[]',NULL,'/pəˈlɪtɪkəl ˌɪmplɪˈkeɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4927,'colloc-11-01',137,'political instability','bất ổn chính trị','adj + n','[{"en":"Years of political instability damaged the national economy.","vi":"Nhiều năm bất ổn chính trị đã gây thiệt hại cho nền kinh tế quốc gia."},{"en":"Political instability can quickly drive away foreign investors.","vi":"Bất ổn chính trị có thể nhanh chóng khiến nhà đầu tư nước ngoài rút lui."},{"en":"The region suffers from ongoing political instability.","vi":"Khu vực này chịu đựng tình trạng bất ổn chính trị kéo dài."}]','[]',NULL,'/pəˈlɪtɪkəl ˌɪnstəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4928,'colloc-11-01',138,'political institution','thể chế chính trị','adj + n','[{"en":"Strong political institutions help protect citizens'' rights.","vi":"Các thể chế chính trị vững mạnh giúp bảo vệ quyền của công dân."},{"en":"The reform aimed to modernize outdated political institutions.","vi":"Cuộc cải cách nhằm hiện đại hóa các thể chế chính trị lỗi thời."},{"en":"Trust in political institutions has declined in recent years.","vi":"Niềm tin vào các thể chế chính trị đã suy giảm trong những năm gần đây."}]','[]',NULL,'/pəˈlɪtɪkəl ˌɪnstɪˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4929,'colloc-11-01',139,'political leader','lãnh đạo chính trị','adj + n','[{"en":"A respected political leader can unite a divided nation.","vi":"Một nhà lãnh đạo chính trị được tôn trọng có thể đoàn kết một quốc gia chia rẽ."},{"en":"Several political leaders attended the international summit.","vi":"Một số lãnh đạo chính trị đã tham dự hội nghị thượng đỉnh quốc tế."},{"en":"The political leader faced criticism over the new tax plan.","vi":"Nhà lãnh đạo chính trị đối mặt với chỉ trích về kế hoạch thuế mới."}]','[]',NULL,'/pəˈlɪtɪkəl ˈliːdər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4930,'colloc-11-01',140,'political mobilization','sự huy động chính trị','adj + n','[{"en":"Social media has accelerated political mobilization among youth.","vi":"Mạng xã hội đã thúc đẩy sự huy động chính trị trong giới trẻ."},{"en":"The strike was the result of sustained political mobilization.","vi":"Cuộc đình công là kết quả của sự huy động chính trị bền bỉ."},{"en":"Effective political mobilization requires both organization and trust.","vi":"Sự huy động chính trị hiệu quả đòi hỏi cả tổ chức lẫn niềm tin."}]','[]',NULL,'/pəˈlɪtɪkəl ˌmoʊbələˈzeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4931,'colloc-11-01',141,'political movement','phong trào chính trị','adj + n','[{"en":"The political movement gained millions of supporters within a year.","vi":"Phong trào chính trị đã giành được hàng triệu người ủng hộ trong một năm."},{"en":"Historians traced the origins of the political movement carefully.","vi":"Các nhà sử học đã lần theo nguồn gốc của phong trào chính trị một cách cẩn thận."},{"en":"The political movement demanded greater rights for workers.","vi":"Phong trào chính trị đòi hỏi quyền lợi nhiều hơn cho người lao động."}]','[]',NULL,'/pəˈlɪtɪkəl ˈmuːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4932,'colloc-11-01',142,'political organization','tổ chức chính trị','adj + n','[{"en":"The political organization campaigned for fairer voting laws.","vi":"Tổ chức chính trị đã vận động cho luật bầu cử công bằng hơn."},{"en":"Several political organizations joined forces during the election.","vi":"Một số tổ chức chính trị đã hợp lực trong cuộc bầu cử."},{"en":"Members built the political organization from the ground up.","vi":"Các thành viên đã xây dựng tổ chức chính trị từ con số không."}]','[]',NULL,'/pəˈlɪtɪkəl ˌɔːrɡənəˈzeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4933,'colloc-11-01',143,'political participation','sự tham gia chính trị','adj + n','[{"en":"Lower voting ages may increase youth political participation.","vi":"Hạ tuổi bầu cử có thể làm tăng sự tham gia chính trị của giới trẻ."},{"en":"The study measured political participation across income groups.","vi":"Nghiên cứu đo lường sự tham gia chính trị giữa các nhóm thu nhập."},{"en":"Education tends to boost political participation among citizens.","vi":"Giáo dục có xu hướng thúc đẩy sự tham gia chính trị của công dân."}]','[]',NULL,'/pəˈlɪtɪkəl pɑːrˌtɪsəˈpeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4934,'colloc-11-01',144,'political party','đảng phái chính trị','adj + n','[{"en":"A new political party emerged ahead of the general election.","vi":"Một đảng phái chính trị mới xuất hiện trước thềm cuộc tổng tuyển cử."},{"en":"Each political party published a detailed economic manifesto.","vi":"Mỗi đảng phái chính trị công bố một cương lĩnh kinh tế chi tiết."},{"en":"Membership in the political party has grown steadily.","vi":"Số thành viên của đảng phái chính trị này đã tăng đều đặn."}]','[]',NULL,'/pəˈlɪtɪkəl ˈpɑːrti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4935,'colloc-11-01',145,'political philosophy','triết học chính trị','adj + n','[{"en":"The lecture introduced students to classical political philosophy.","vi":"Bài giảng giới thiệu cho sinh viên về triết học chính trị cổ điển."},{"en":"His political philosophy drew heavily on Enlightenment thinkers.","vi":"Triết học chính trị của ông chịu ảnh hưởng lớn từ các nhà tư tưởng Khai sáng."},{"en":"Debates in political philosophy still shape modern law.","vi":"Những tranh luận trong triết học chính trị vẫn định hình luật pháp hiện đại."}]','[]',NULL,'/pəˈlɪtɪkəl fəˈlɑːsəfi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4936,'colloc-11-01',146,'political reality','thực tế chính trị','adj + n','[{"en":"Ideal policies must adjust to the political reality on the ground.","vi":"Các chính sách lý tưởng phải điều chỉnh theo thực tế chính trị tại chỗ."},{"en":"The political reality made sweeping reform almost impossible.","vi":"Thực tế chính trị khiến cải cách toàn diện gần như bất khả thi."},{"en":"Leaders cannot ignore the harsh political reality they face.","vi":"Các nhà lãnh đạo không thể phớt lờ thực tế chính trị khắc nghiệt họ đối mặt."}]','[]',NULL,'/pəˈlɪtɪkəl riˈæləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4937,'colloc-11-01',147,'political reform','cải cách chính trị','adj + n','[{"en":"Public pressure finally led to genuine political reform.","vi":"Áp lực từ công chúng cuối cùng đã dẫn đến cải cách chính trị thực sự."},{"en":"The movement demanded sweeping political reform and accountability.","vi":"Phong trào đòi hỏi cải cách chính trị toàn diện và trách nhiệm giải trình."},{"en":"Political reform often happens slowly and unevenly.","vi":"Cải cách chính trị thường diễn ra chậm chạp và không đồng đều."}]','[]',NULL,'/pəˈlɪtɪkəl rɪˈfɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4938,'colloc-11-01',148,'political representation','sự đại diện chính trị','adj + n','[{"en":"Minorities have long fought for fair political representation.","vi":"Các nhóm thiểu số từ lâu đã đấu tranh cho sự đại diện chính trị công bằng."},{"en":"Quotas were introduced to improve women''s political representation.","vi":"Hạn ngạch được áp dụng để cải thiện sự đại diện chính trị của phụ nữ."},{"en":"Rural areas often lack adequate political representation.","vi":"Các vùng nông thôn thường thiếu sự đại diện chính trị đầy đủ."}]','[]',NULL,'/pəˈlɪtɪkəl ˌreprɪzenˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4939,'colloc-11-01',149,'political significance','tầm quan trọng về chính trị','adj + n','[{"en":"The treaty had enormous political significance for the region.","vi":"Hiệp ước có ý nghĩa chính trị to lớn đối với khu vực."},{"en":"Historians still debate the political significance of that speech.","vi":"Các nhà sử học vẫn tranh luận về tầm quan trọng chính trị của bài phát biểu đó."},{"en":"Few people grasped the political significance of the new law.","vi":"Ít người hiểu được ý nghĩa chính trị của đạo luật mới."}]','[]',NULL,'/pəˈlɪtɪkəl sɪɡˈnɪfɪkəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4940,'colloc-11-01',150,'political spectrum','phổ chính trị (các khuynh hướng chính trị)','adj + n','[{"en":"Voters across the political spectrum supported the reform.","vi":"Cử tri thuộc mọi khuynh hướng chính trị đều ủng hộ cải cách."},{"en":"Her views sit at the far end of the political spectrum.","vi":"Quan điểm của cô nằm ở cực xa của phổ chính trị."},{"en":"The debate attracted parties from across the political spectrum.","vi":"Cuộc tranh luận thu hút các đảng từ khắp phổ chính trị."}]','[]',NULL,'/pəˈlɪtɪkəl ˈspektrəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4941,'colloc-12-01',1,'political stability','sự ổn định về chính trị','adj + n','[{"en":"Foreign investors value the country''s long-term political stability.","vi":"Nhà đầu tư nước ngoài coi trọng sự ổn định chính trị lâu dài của đất nước."},{"en":"Economic growth often depends on political stability.","vi":"Tăng trưởng kinh tế thường phụ thuộc vào sự ổn định chính trị."},{"en":"The coup destroyed decades of hard-won political stability.","vi":"Cuộc đảo chính phá hủy hàng thập kỷ ổn định chính trị khó khăn lắm mới có."}]','[]',NULL,'/pəˈlɪtɪkəl stəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4942,'colloc-12-01',2,'political status','địa vị chính trị','adj + n','[{"en":"The region''s political status remains a sensitive issue.","vi":"Địa vị chính trị của khu vực vẫn là vấn đề nhạy cảm."},{"en":"Citizens demanded a change in their political status.","vi":"Người dân đòi thay đổi địa vị chính trị của họ."},{"en":"The treaty clarified the territory''s political status.","vi":"Hiệp ước làm rõ địa vị chính trị của vùng lãnh thổ."}]','[]',NULL,'/pəˈlɪtɪkəl ˈstætəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4943,'colloc-12-01',3,'political structure','cơ cấu chính trị','adj + n','[{"en":"The book analyzes the political structure of ancient Rome.","vi":"Cuốn sách phân tích cơ cấu chính trị của La Mã cổ đại."},{"en":"A weak political structure left the nation vulnerable.","vi":"Một cơ cấu chính trị yếu khiến quốc gia dễ bị tổn thương."},{"en":"Reformers tried to redesign the entire political structure.","vi":"Những nhà cải cách cố thiết kế lại toàn bộ cơ cấu chính trị."}]','[]',NULL,'/pəˈlɪtɪkəl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4944,'colloc-12-01',4,'politically correct','đúng chuẩn mực chính trị xã hội','adv + adj','[{"en":"He chose politically correct language to avoid offending anyone.","vi":"Anh chọn ngôn từ đúng mực để tránh xúc phạm bất kỳ ai."},{"en":"Some critics say the campaign was too politically correct.","vi":"Một số người chỉ trích cho rằng chiến dịch quá khuôn phép về chính trị xã hội."},{"en":"The textbook was revised to be more politically correct.","vi":"Cuốn giáo trình được sửa lại cho đúng chuẩn mực hơn."}]','[]',NULL,'/pəˈlɪtɪkli kəˈrekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4945,'colloc-12-01',5,'politically motivated','có động cơ chính trị','adv + vpp','[{"en":"Critics claimed the arrests were politically motivated.","vi":"Những người chỉ trích cho rằng các vụ bắt giữ có động cơ chính trị."},{"en":"The lawsuit looked politically motivated rather than legal.","vi":"Vụ kiện trông có động cơ chính trị hơn là pháp lý."},{"en":"Analysts described the decision as politically motivated.","vi":"Các nhà phân tích mô tả quyết định này là có động cơ chính trị."}]','[]',NULL,'/pəˈlɪtɪkli ˈmoʊtɪveɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4946,'colloc-12-01',6,'poorly understood','chưa được hiểu rõ','adv + vpp','[{"en":"The disease remains poorly understood despite years of research.","vi":"Căn bệnh vẫn chưa được hiểu rõ dù đã nghiên cứu nhiều năm."},{"en":"These chemical reactions are still poorly understood.","vi":"Những phản ứng hóa học này vẫn chưa được hiểu rõ."},{"en":"The long-term effects are poorly understood by scientists.","vi":"Các tác động lâu dài vẫn chưa được giới khoa học hiểu rõ."}]','[]',NULL,'/ˈpʊrli ˌʌndərˈstʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4947,'colloc-12-01',7,'popular culture','văn hóa đại chúng','adj + n','[{"en":"The film reflects many themes from popular culture.","vi":"Bộ phim phản ánh nhiều chủ đề từ văn hóa đại chúng."},{"en":"Social media has reshaped modern popular culture.","vi":"Mạng xã hội đã định hình lại văn hóa đại chúng hiện đại."},{"en":"The course examines how popular culture influences young people.","vi":"Khóa học xem xét cách văn hóa đại chúng ảnh hưởng giới trẻ."}]','[]',NULL,'/ˈpɑːpjələr ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4948,'colloc-12-01',8,'popular media','truyền thông đại chúng','adj + n','[{"en":"Popular media often simplifies complex scientific ideas.","vi":"Truyền thông đại chúng thường đơn giản hóa các ý tưởng khoa học phức tạp."},{"en":"The story spread quickly through popular media.","vi":"Câu chuyện lan nhanh qua truyền thông đại chúng."},{"en":"Popular media shapes how the public sees the issue.","vi":"Truyền thông đại chúng định hình cách công chúng nhìn nhận vấn đề."}]','[]',NULL,'/ˈpɑːpjələr ˈmiːdiə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4949,'colloc-12-01',9,'pose a challenge','đặt ra một thách thức','v + n','[{"en":"Climate change will pose a challenge for future generations.","vi":"Biến đổi khí hậu sẽ đặt ra thách thức cho các thế hệ tương lai."},{"en":"Rapid growth can pose a challenge to small companies.","vi":"Tăng trưởng nhanh có thể đặt ra thách thức cho các công ty nhỏ."},{"en":"New regulations pose a challenge for many manufacturers.","vi":"Các quy định mới đặt ra thách thức cho nhiều nhà sản xuất."}]','[]',NULL,'/poʊz ə ˈtʃælɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4950,'colloc-12-01',10,'pose a problem','gây ra một vấn đề','v + n','[{"en":"Heavy traffic poses a problem for emergency services.","vi":"Giao thông đông đúc gây ra vấn đề cho các dịch vụ khẩn cấp."},{"en":"Missing data can pose a problem for the analysis.","vi":"Dữ liệu thiếu có thể gây ra vấn đề cho việc phân tích."},{"en":"Rising costs pose a problem for the whole industry.","vi":"Chi phí tăng gây ra vấn đề cho cả ngành."}]','[]',NULL,'/poʊz ə ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4951,'colloc-12-01',11,'pose a question','đặt ra một câu hỏi','v + n','[{"en":"These results pose a question about the original theory.","vi":"Những kết quả này đặt ra câu hỏi về lý thuyết ban đầu."},{"en":"The teacher posed a question that puzzled the students.","vi":"Giáo viên đặt ra một câu hỏi khiến học sinh bối rối."},{"en":"The findings pose a question worth further investigation.","vi":"Phát hiện này đặt ra câu hỏi đáng được nghiên cứu thêm."}]','[]',NULL,'/poʊz ə ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4952,'colloc-12-01',12,'pose a threat to','đặt ra mối đe dọa đối với','v + n','[{"en":"Pollution can pose a threat to public health.","vi":"Ô nhiễm có thể đặt ra mối đe dọa đối với sức khỏe cộng đồng."},{"en":"Invasive species pose a threat to local ecosystems.","vi":"Các loài xâm lấn đặt ra mối đe dọa đối với hệ sinh thái địa phương."},{"en":"Cyberattacks pose a threat to national security.","vi":"Các cuộc tấn công mạng đặt ra mối đe dọa đối với an ninh quốc gia."}]','[]',NULL,'/poʊz ə θret tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4953,'colloc-12-01',13,'positive action','hành động tích cực','adj + n','[{"en":"The government took positive action to reduce unemployment.","vi":"Chính phủ đã có hành động tích cực để giảm thất nghiệp."},{"en":"Positive action is needed to protect endangered species.","vi":"Cần có hành động tích cực để bảo vệ các loài nguy cấp."},{"en":"The campaign encouraged positive action on recycling.","vi":"Chiến dịch khuyến khích hành động tích cực về tái chế."}]','[]',NULL,'/ˈpɑːzətɪv ˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4954,'colloc-12-01',14,'positive aspect','khía cạnh tích cực','adj + n','[{"en":"The report highlights the positive aspect of remote work.","vi":"Báo cáo nhấn mạnh khía cạnh tích cực của làm việc từ xa."},{"en":"One positive aspect of the change was lower costs.","vi":"Một khía cạnh tích cực của sự thay đổi là chi phí thấp hơn."},{"en":"Students discussed the positive aspect of online learning.","vi":"Học sinh thảo luận về khía cạnh tích cực của học trực tuyến."}]','[]',NULL,'/ˈpɑːzətɪv ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4955,'colloc-12-01',15,'positive attitude','thái độ tích cực','adj + n','[{"en":"A positive attitude helps students cope with difficult exams.","vi":"Thái độ tích cực giúp học sinh đối phó với các kỳ thi khó."},{"en":"Employers value a positive attitude toward teamwork.","vi":"Nhà tuyển dụng coi trọng thái độ tích cực với làm việc nhóm."},{"en":"She kept a positive attitude despite many setbacks.","vi":"Cô giữ thái độ tích cực dù gặp nhiều trở ngại."}]','[]',NULL,'/ˈpɑːzətɪv ˈætɪtuːd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4956,'colloc-12-01',16,'positive connotation','hàm ý tích cực','adj + n','[{"en":"The word carries a strong positive connotation in English.","vi":"Từ này mang một hàm ý tích cực mạnh trong tiếng Anh."},{"en":"Marketers prefer terms with a positive connotation.","vi":"Người làm tiếp thị thích các từ có hàm ý tích cực."},{"en":"Unlike its synonym, this word has a positive connotation.","vi":"Khác với từ đồng nghĩa, từ này có hàm ý tích cực."}]','[]',NULL,'/ˈpɑːzətɪv ˌkɑːnəˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4957,'colloc-12-01',17,'positive correlation','mối tương quan thuận','adj + n','[{"en":"The study found a positive correlation between exercise and mood.","vi":"Nghiên cứu tìm thấy mối tương quan thuận giữa tập luyện và tâm trạng."},{"en":"There is a positive correlation between income and education.","vi":"Có một mối tương quan thuận giữa thu nhập và trình độ học vấn."},{"en":"Researchers reported a positive correlation in the data.","vi":"Các nhà nghiên cứu báo cáo một mối tương quan thuận trong dữ liệu."}]','[]',NULL,'/ˈpɑːzətɪv ˌkɔːrəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4958,'colloc-12-01',18,'positive discrimination','phân biệt đối xử tích cực (ưu tiên nhóm yếu thế)','adj + n','[{"en":"Some universities use positive discrimination to widen access.","vi":"Một số trường đại học dùng ưu tiên tích cực để mở rộng cơ hội."},{"en":"Positive discrimination remains a controversial policy choice.","vi":"Phân biệt đối xử tích cực vẫn là một lựa chọn chính sách gây tranh cãi."},{"en":"Critics argue positive discrimination can create new inequalities.","vi":"Người chỉ trích cho rằng ưu tiên tích cực có thể tạo bất bình đẳng mới."}]','[]',NULL,'/ˈpɑːzətɪv dɪˌskrɪmɪˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4959,'colloc-12-01',19,'positive effect','tác động tích cực','adj + n','[{"en":"Regular sleep has a positive effect on memory.","vi":"Ngủ đều đặn có tác động tích cực đến trí nhớ."},{"en":"The new policy had a positive effect on attendance.","vi":"Chính sách mới có tác động tích cực đến tỷ lệ đi học."},{"en":"Reading widely has a positive effect on writing skills.","vi":"Đọc nhiều có tác động tích cực đến kỹ năng viết."}]','[]',NULL,'/ˈpɑːzətɪv ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4960,'colloc-12-01',20,'positive feature','đặc điểm tích cực','adj + n','[{"en":"A positive feature of the design is its simplicity.","vi":"Một đặc điểm tích cực của thiết kế là sự đơn giản."},{"en":"The most positive feature of the app is its speed.","vi":"Đặc điểm tích cực nhất của ứng dụng là tốc độ."},{"en":"Flexibility is a positive feature of the new system.","vi":"Tính linh hoạt là một đặc điểm tích cực của hệ thống mới."}]','[]',NULL,'/ˈpɑːzətɪv ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4961,'colloc-12-01',21,'positive feedback','phản hồi tích cực','adj + n','[{"en":"The teacher gave positive feedback on the student''s essay.","vi":"Giáo viên đưa ra phản hồi tích cực về bài luận của học sinh."},{"en":"Customers left positive feedback about the service.","vi":"Khách hàng để lại phản hồi tích cực về dịch vụ."},{"en":"Positive feedback encourages learners to keep practicing.","vi":"Phản hồi tích cực khuyến khích người học tiếp tục luyện tập."}]','[]',NULL,'/ˈpɑːzətɪv ˈfiːdbæk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4962,'colloc-12-01',22,'positive image','hình ảnh tích cực','adj + n','[{"en":"The company worked hard to build a positive image.","vi":"Công ty nỗ lực xây dựng một hình ảnh tích cực."},{"en":"Advertising aims to create a positive image of the brand.","vi":"Quảng cáo nhằm tạo một hình ảnh tích cực về thương hiệu."},{"en":"The city promotes a positive image to attract tourists.","vi":"Thành phố quảng bá một hình ảnh tích cực để thu hút du khách."}]','[]',NULL,'/ˈpɑːzətɪv ˈɪmɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4963,'colloc-12-01',23,'positive impact','ảnh hưởng tích cực','adj + n','[{"en":"Volunteering can have a positive impact on the community.","vi":"Tình nguyện có thể có ảnh hưởng tích cực đến cộng đồng."},{"en":"The program had a positive impact on student grades.","vi":"Chương trình có ảnh hưởng tích cực đến điểm số của học sinh."},{"en":"Clean energy has a positive impact on the environment.","vi":"Năng lượng sạch có ảnh hưởng tích cực đến môi trường."}]','[]',NULL,'/ˈpɑːzətɪv ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4964,'colloc-12-01',24,'positive influence','ảnh hưởng tích cực (sự tác động tốt)','adj + n','[{"en":"A good mentor can be a positive influence on young people.","vi":"Một người cố vấn tốt có thể là ảnh hưởng tích cực với giới trẻ."},{"en":"Her teacher had a lasting positive influence on her career.","vi":"Giáo viên của cô có ảnh hưởng tích cực lâu dài đến sự nghiệp."},{"en":"Reading widely had a positive influence on his thinking.","vi":"Đọc nhiều có ảnh hưởng tích cực đến tư duy của anh."}]','[]',NULL,'/ˈpɑːzətɪv ˈɪnfluəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4965,'colloc-12-01',25,'positive outcome','kết quả tích cực','adj + n','[{"en":"Early treatment increases the chance of a positive outcome.","vi":"Điều trị sớm tăng cơ hội có một kết quả tích cực."},{"en":"The negotiations led to a positive outcome for both sides.","vi":"Các cuộc đàm phán dẫn đến kết quả tích cực cho cả hai bên."},{"en":"Researchers hoped for a positive outcome from the trial.","vi":"Các nhà nghiên cứu hy vọng có kết quả tích cực từ thử nghiệm."}]','[]',NULL,'/ˈpɑːzətɪv ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4966,'colloc-12-01',26,'positive relationship','mối quan hệ tích cực (tương quan thuận)','adj + n','[{"en":"The data show a positive relationship between study time and grades.","vi":"Dữ liệu cho thấy mối quan hệ thuận giữa thời gian học và điểm số."},{"en":"Teachers build a positive relationship with their students.","vi":"Giáo viên xây dựng mối quan hệ tích cực với học sinh."},{"en":"A positive relationship with clients improves business results.","vi":"Mối quan hệ tích cực với khách hàng cải thiện kết quả kinh doanh."}]','[]',NULL,'/ˈpɑːzətɪv rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4967,'colloc-12-01',27,'positive result','kết quả tích cực','adj + n','[{"en":"The experiment produced a clear positive result.","vi":"Thí nghiệm tạo ra một kết quả tích cực rõ ràng."},{"en":"A positive result confirmed the team''s hypothesis.","vi":"Một kết quả tích cực xác nhận giả thuyết của nhóm."},{"en":"The treatment showed a positive result within weeks.","vi":"Phương pháp điều trị cho kết quả tích cực trong vài tuần."}]','[]',NULL,'/ˈpɑːzətɪv rɪˈzʌlt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4968,'colloc-12-01',28,'positive value','giá trị dương (giá trị tích cực)','adj + n','[{"en":"The function returns a positive value for all valid inputs.","vi":"Hàm trả về một giá trị dương cho mọi đầu vào hợp lệ."},{"en":"A positive value indicates growth over the period.","vi":"Một giá trị dương cho thấy sự tăng trưởng trong giai đoạn đó."},{"en":"Education holds a positive value in every society.","vi":"Giáo dục mang một giá trị tích cực trong mọi xã hội."}]','[]',NULL,'/ˈpɑːzətɪv ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4969,'colloc-12-01',29,'positive view','quan điểm tích cực','adj + n','[{"en":"Most respondents held a positive view of the changes.","vi":"Hầu hết người trả lời có quan điểm tích cực về những thay đổi."},{"en":"She maintained a positive view despite the criticism.","vi":"Cô giữ một quan điểm tích cực dù bị chỉ trích."},{"en":"The author takes a positive view of technological progress.","vi":"Tác giả có quan điểm tích cực về tiến bộ công nghệ."}]','[]',NULL,'/ˈpɑːzətɪv vjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4970,'colloc-12-01',30,'positively associated with','có liên hệ thuận với','adv + vpp','[{"en":"Higher income is positively associated with better health.","vi":"Thu nhập cao hơn có liên hệ thuận với sức khỏe tốt hơn."},{"en":"Sleep quality was positively associated with concentration.","vi":"Chất lượng giấc ngủ có liên hệ thuận với khả năng tập trung."},{"en":"Reading habits are positively associated with vocabulary size.","vi":"Thói quen đọc có liên hệ thuận với vốn từ vựng."}]','[]',NULL,'/ˈpɑːzətɪvli əˈsoʊʃieɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4971,'colloc-12-01',31,'positively correlated with','tương quan thuận với','adv + vpp','[{"en":"Test scores were positively correlated with study hours.","vi":"Điểm thi tương quan thuận với số giờ học."},{"en":"Temperature is positively correlated with ice-cream sales.","vi":"Nhiệt độ tương quan thuận với doanh số kem."},{"en":"Job satisfaction was positively correlated with productivity.","vi":"Sự hài lòng công việc tương quan thuận với năng suất."}]','[]',NULL,'/ˈpɑːzətɪvli ˈkɔːrəleɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4972,'colloc-12-01',32,'possible consequences','những hậu quả có thể xảy ra','adj + n','[{"en":"The report outlines the possible consequences of inaction.","vi":"Báo cáo nêu ra những hậu quả có thể xảy ra nếu không hành động."},{"en":"Students must consider the possible consequences of their choices.","vi":"Học sinh phải cân nhắc những hậu quả có thể xảy ra từ lựa chọn của mình."},{"en":"Scientists warned about the possible consequences of warming.","vi":"Các nhà khoa học cảnh báo về những hậu quả có thể xảy ra của sự ấm lên."}]','[]',NULL,'/ˈpɑːsəbəl ˈkɑːnsəkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4973,'colloc-12-01',33,'possible explanation','một cách giải thích khả dĩ','adj + n','[{"en":"One possible explanation is a flaw in the method.","vi":"Một cách giải thích khả dĩ là sai sót trong phương pháp."},{"en":"The author offers a possible explanation for the results.","vi":"Tác giả đưa ra một cách giải thích khả dĩ cho các kết quả."},{"en":"Several possible explanations remain to be tested.","vi":"Vẫn còn vài cách giải thích khả dĩ cần được kiểm chứng."}]','[]',NULL,'/ˈpɑːsəbəl ˌekspləˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4974,'colloc-12-01',34,'possible outcome','kết quả có thể xảy ra','adj + n','[{"en":"The model predicts every possible outcome of the experiment.","vi":"Mô hình dự đoán mọi kết quả có thể xảy ra của thí nghiệm."},{"en":"We must prepare for the worst possible outcome.","vi":"Chúng ta phải chuẩn bị cho kết quả tệ nhất có thể xảy ra."},{"en":"Each possible outcome was carefully analyzed.","vi":"Mỗi kết quả có thể xảy ra đều được phân tích kỹ lưỡng."}]','[]',NULL,'/ˈpɑːsəbəl ˈaʊtkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4975,'colloc-12-01',35,'possible source','nguồn gốc có thể có','adj + n','[{"en":"The team investigated every possible source of the error.","vi":"Nhóm điều tra mọi nguồn gốc có thể có của sai sót."},{"en":"Contaminated water is a possible source of the disease.","vi":"Nước ô nhiễm là một nguồn gốc có thể có của căn bệnh."},{"en":"Researchers identified a possible source of funding.","vi":"Các nhà nghiên cứu xác định một nguồn tài trợ có thể có."}]','[]',NULL,'/ˈpɑːsəbəl sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4976,'colloc-12-01',36,'potential benefits','những lợi ích tiềm năng','adj + n','[{"en":"The study examines the potential benefits of meditation.","vi":"Nghiên cứu xem xét những lợi ích tiềm năng của thiền."},{"en":"Investors weighed the potential benefits against the risks.","vi":"Nhà đầu tư cân nhắc những lợi ích tiềm năng so với rủi ro."},{"en":"The report highlights the potential benefits of the new policy.","vi":"Báo cáo nhấn mạnh những lợi ích tiềm năng của chính sách mới."}]','[]',NULL,'/pəˈtenʃəl ˈbenɪfɪts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4977,'colloc-12-01',37,'potential conflict','xung đột tiềm ẩn','adj + n','[{"en":"The manager spotted a potential conflict between the teams.","vi":"Người quản lý phát hiện một xung đột tiềm ẩn giữa các nhóm."},{"en":"Clear rules help avoid potential conflict over resources.","vi":"Quy định rõ ràng giúp tránh xung đột tiềm ẩn về nguồn lực."},{"en":"The treaty was designed to reduce potential conflict.","vi":"Hiệp ước được thiết kế để giảm xung đột tiềm ẩn."}]','[]',NULL,'/pəˈtenʃəl ˈkɑːnflɪkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4978,'colloc-12-01',38,'potential customer','khách hàng tiềm năng','adj + n','[{"en":"The advertisement targets every potential customer in the city.","vi":"Quảng cáo nhắm đến mọi khách hàng tiềm năng trong thành phố."},{"en":"A friendly website attracts each potential customer quickly.","vi":"Một trang web thân thiện thu hút mỗi khách hàng tiềm năng nhanh chóng."},{"en":"Sales staff follow up with every potential customer.","vi":"Nhân viên bán hàng theo dõi mọi khách hàng tiềm năng."}]','[]',NULL,'/pəˈtenʃəl ˈkʌstəmər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4979,'colloc-12-01',39,'potential harm','tác hại tiềm ẩn','adj + n','[{"en":"The study warns of potential harm from excessive screen time.","vi":"Nghiên cứu cảnh báo về tác hại tiềm ẩn từ việc dùng màn hình quá nhiều."},{"en":"Doctors weigh the potential harm of each treatment.","vi":"Bác sĩ cân nhắc tác hại tiềm ẩn của mỗi phương pháp điều trị."},{"en":"Regulators assess the potential harm of new chemicals.","vi":"Cơ quan quản lý đánh giá tác hại tiềm ẩn của các hóa chất mới."}]','[]',NULL,'/pəˈtenʃəl hɑːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4980,'colloc-12-01',40,'potential impact','tác động tiềm tàng','adj + n','[{"en":"Researchers studied the potential impact of rising sea levels.","vi":"Các nhà nghiên cứu nghiên cứu tác động tiềm tàng của mực nước biển dâng."},{"en":"The report assesses the potential impact of the merger.","vi":"Báo cáo đánh giá tác động tiềm tàng của vụ sáp nhập."},{"en":"Planners considered the potential impact on local traffic.","vi":"Các nhà quy hoạch xem xét tác động tiềm tàng đến giao thông địa phương."}]','[]',NULL,'/pəˈtenʃəl ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4981,'colloc-12-01',41,'potential problem','vấn đề tiềm ẩn','adj + n','[{"en":"The engineer identified a potential problem with the design.","vi":"Kỹ sư xác định một vấn đề tiềm ẩn trong thiết kế."},{"en":"Early testing helps reveal any potential problem.","vi":"Kiểm thử sớm giúp phát hiện bất kỳ vấn đề tiềm ẩn nào."},{"en":"Managers discussed every potential problem before launch.","vi":"Các nhà quản lý thảo luận mọi vấn đề tiềm ẩn trước khi ra mắt."}]','[]',NULL,'/pəˈtenʃəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4982,'colloc-12-01',42,'potential risk','rủi ro tiềm ẩn','adj + n','[{"en":"The label warns users of any potential risk.","vi":"Nhãn cảnh báo người dùng về bất kỳ rủi ro tiềm ẩn nào."},{"en":"Investors must understand the potential risk involved.","vi":"Nhà đầu tư phải hiểu rủi ro tiềm ẩn liên quan."},{"en":"The team reduced the potential risk through careful planning.","vi":"Nhóm giảm rủi ro tiềm ẩn nhờ lập kế hoạch cẩn thận."}]','[]',NULL,'/pəˈtenʃəl rɪsk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4983,'colloc-12-01',43,'potential source','nguồn tiềm năng','adj + n','[{"en":"Solar energy is a potential source of clean power.","vi":"Năng lượng mặt trời là một nguồn tiềm năng cho điện sạch."},{"en":"Bias is a potential source of error in surveys.","vi":"Thiên kiến là một nguồn tiềm năng gây sai số trong khảo sát."},{"en":"The lake is a potential source of drinking water.","vi":"Hồ là một nguồn tiềm năng cung cấp nước uống."}]','[]',NULL,'/pəˈtenʃəl sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4984,'colloc-12-01',44,'potential value','giá trị tiềm năng','adj + n','[{"en":"Investors recognized the potential value of the technology.","vi":"Nhà đầu tư nhận ra giá trị tiềm năng của công nghệ này."},{"en":"The land has great potential value for development.","vi":"Khu đất có giá trị tiềm năng lớn cho phát triển."},{"en":"The study underestimates the potential value of the data.","vi":"Nghiên cứu đánh giá thấp giá trị tiềm năng của dữ liệu."}]','[]',NULL,'/pəˈtenʃəl ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4985,'colloc-12-01',45,'potentially dangerous','có thể nguy hiểm','adv + adj','[{"en":"The chemical is potentially dangerous if mishandled.","vi":"Hóa chất này có thể nguy hiểm nếu xử lý sai cách."},{"en":"Driving while tired is potentially dangerous.","vi":"Lái xe khi mệt mỏi có thể nguy hiểm."},{"en":"The study identified a potentially dangerous side effect.","vi":"Nghiên cứu xác định một tác dụng phụ có thể nguy hiểm."}]','[]',NULL,'/pəˈtenʃəli ˈdeɪndʒərəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4986,'colloc-12-01',46,'powerful force','một lực lượng mạnh mẽ','adj + n','[{"en":"Education is a powerful force for social change.","vi":"Giáo dục là một lực lượng mạnh mẽ thúc đẩy thay đổi xã hội."},{"en":"Gravity is a powerful force shaping the universe.","vi":"Trọng lực là một lực mạnh mẽ định hình vũ trụ."},{"en":"Public opinion became a powerful force in the debate.","vi":"Dư luận trở thành một lực lượng mạnh mẽ trong cuộc tranh luận."}]','[]',NULL,'/ˈpaʊərfəl fɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4987,'colloc-12-01',47,'powerful group','một nhóm có quyền lực','adj + n','[{"en":"A powerful group of investors controlled the company.","vi":"Một nhóm nhà đầu tư có quyền lực kiểm soát công ty."},{"en":"The reform threatened several powerful groups in society.","vi":"Cuộc cải cách đe dọa vài nhóm có quyền lực trong xã hội."},{"en":"A powerful group lobbied against the new tax.","vi":"Một nhóm có quyền lực vận động chống lại loại thuế mới."}]','[]',NULL,'/ˈpaʊərfəl ɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4988,'colloc-12-01',48,'powerful influence','ảnh hưởng mạnh mẽ','adj + n','[{"en":"The media has a powerful influence on public opinion.","vi":"Truyền thông có ảnh hưởng mạnh mẽ đến dư luận."},{"en":"His writing had a powerful influence on later authors.","vi":"Tác phẩm của ông có ảnh hưởng mạnh mẽ đến các tác giả sau này."},{"en":"Parents exert a powerful influence on their children.","vi":"Cha mẹ có ảnh hưởng mạnh mẽ đến con cái."}]','[]',NULL,'/ˈpaʊərfəl ˈɪnfluəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4989,'colloc-12-01',49,'powerful tool','một công cụ mạnh mẽ','adj + n','[{"en":"Statistics is a powerful tool for understanding data.","vi":"Thống kê là một công cụ mạnh mẽ để hiểu dữ liệu."},{"en":"The internet is a powerful tool for learning.","vi":"Internet là một công cụ mạnh mẽ cho việc học."},{"en":"Language is a powerful tool for shaping ideas.","vi":"Ngôn ngữ là một công cụ mạnh mẽ để định hình ý tưởng."}]','[]',NULL,'/ˈpaʊərfəl tuːl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4990,'colloc-12-01',50,'practical consideration','yếu tố thực tiễn cần cân nhắc','adj + n','[{"en":"Cost is an important practical consideration in the plan.","vi":"Chi phí là một yếu tố thực tiễn quan trọng cần cân nhắc trong kế hoạch."},{"en":"Practical considerations limited the scope of the study.","vi":"Những yếu tố thực tiễn đã giới hạn phạm vi của nghiên cứu."},{"en":"We balanced ideals against practical considerations.","vi":"Chúng tôi cân bằng giữa lý tưởng và các yếu tố thực tiễn."}]','[]',NULL,'/ˈpræktɪkəl kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4991,'colloc-12-01',51,'practical difficulties','những khó khăn thực tế','adj + n','[{"en":"The project faced many practical difficulties at first.","vi":"Dự án gặp nhiều khó khăn thực tế lúc ban đầu."},{"en":"Practical difficulties delayed the start of the trial.","vi":"Những khó khăn thực tế làm chậm việc bắt đầu thử nghiệm."},{"en":"Researchers described the practical difficulties of fieldwork.","vi":"Các nhà nghiên cứu mô tả những khó khăn thực tế của công việc thực địa."}]','[]',NULL,'/ˈpræktɪkəl ˈdɪfɪkəltiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4992,'colloc-12-01',52,'practical issue','vấn đề thực tế','adj + n','[{"en":"The meeting focused on one practical issue at a time.","vi":"Cuộc họp tập trung vào một vấn đề thực tế tại mỗi thời điểm."},{"en":"Funding is a practical issue every charity must face.","vi":"Tài trợ là một vấn đề thực tế mà mọi tổ chức từ thiện phải đối mặt."},{"en":"The committee resolved several practical issues quickly.","vi":"Ủy ban giải quyết nhanh chóng vài vấn đề thực tế."}]','[]',NULL,'/ˈpræktɪkəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4993,'colloc-12-01',53,'practical significance','ý nghĩa thực tiễn','adj + n','[{"en":"The findings have real practical significance for teachers.","vi":"Phát hiện này có ý nghĩa thực tiễn thật sự đối với giáo viên."},{"en":"The author explains the practical significance of the theory.","vi":"Tác giả giải thích ý nghĩa thực tiễn của lý thuyết."},{"en":"A small effect may still have practical significance.","vi":"Một hiệu ứng nhỏ vẫn có thể có ý nghĩa thực tiễn."}]','[]',NULL,'/ˈpræktɪkəl sɪɡˈnɪfɪkəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4994,'colloc-12-01',54,'preceding chapter','chương trước đó','adj + n','[{"en":"As noted in the preceding chapter, the data were limited.","vi":"Như đã nêu trong chương trước đó, dữ liệu còn hạn chế."},{"en":"The preceding chapter introduced the main theoretical framework.","vi":"Chương trước đó đã giới thiệu khung lý thuyết chính."},{"en":"This section builds on the preceding chapter''s argument.","vi":"Phần này dựa trên lập luận của chương trước đó."}]','[]',NULL,'/prɪˈsiːdɪŋ ˈtʃæptər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4995,'colloc-12-01',55,'preceding discussion','phần thảo luận trước đó','adj + n','[{"en":"The preceding discussion raised several important questions.","vi":"Phần thảo luận trước đó đã nêu ra vài câu hỏi quan trọng."},{"en":"These conclusions follow from the preceding discussion.","vi":"Những kết luận này rút ra từ phần thảo luận trước đó."},{"en":"The preceding discussion clarified the key terms.","vi":"Phần thảo luận trước đó đã làm rõ các thuật ngữ chính."}]','[]',NULL,'/prɪˈsiːdɪŋ dɪˈskʌʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4996,'colloc-12-01',56,'preceding section','phần trước đó','adj + n','[{"en":"The preceding section described the research methods.","vi":"Phần trước đó đã mô tả các phương pháp nghiên cứu."},{"en":"As shown in the preceding section, the results vary.","vi":"Như đã thấy ở phần trước đó, các kết quả có sự khác biệt."},{"en":"This argument extends ideas from the preceding section.","vi":"Lập luận này mở rộng các ý tưởng từ phần trước đó."}]','[]',NULL,'/prɪˈsiːdɪŋ ˈsekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4997,'colloc-12-01',57,'precise definition','định nghĩa chính xác','adj + n','[{"en":"The term lacks a precise definition in the literature.","vi":"Thuật ngữ này thiếu một định nghĩa chính xác trong tài liệu."},{"en":"A precise definition helps avoid misunderstanding.","vi":"Một định nghĩa chính xác giúp tránh hiểu lầm."},{"en":"Scientists agreed on a precise definition of the unit.","vi":"Các nhà khoa học đã thống nhất một định nghĩa chính xác cho đơn vị."}]','[]',NULL,'/prɪˈsaɪs ˌdefɪˈnɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4998,'colloc-12-01',58,'precise nature','bản chất cụ thể','adj + n','[{"en":"The precise nature of the link is still unclear.","vi":"Bản chất cụ thể của mối liên hệ vẫn chưa rõ ràng."},{"en":"Researchers debated the precise nature of the disorder.","vi":"Các nhà nghiên cứu tranh luận về bản chất cụ thể của chứng rối loạn."},{"en":"We need more data to understand its precise nature.","vi":"Chúng ta cần thêm dữ liệu để hiểu bản chất cụ thể của nó."}]','[]',NULL,'/prɪˈsaɪs ˈneɪtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(4999,'colloc-12-01',59,'predictive power','khả năng dự đoán','adj + n','[{"en":"The model has strong predictive power for short-term trends.","vi":"Mô hình có khả năng dự đoán mạnh đối với các xu hướng ngắn hạn."},{"en":"Adding variables improved the model''s predictive power.","vi":"Việc thêm biến số đã cải thiện khả năng dự đoán của mô hình."},{"en":"The theory''s predictive power impressed the researchers.","vi":"Khả năng dự đoán của lý thuyết gây ấn tượng với các nhà nghiên cứu."}]','[]',NULL,'/prɪˈdɪktɪv ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5000,'colloc-12-01',60,'preferential treatment','sự đối xử ưu ái','adj + n','[{"en":"Employees complained about preferential treatment for managers.","vi":"Nhân viên phàn nàn về sự đối xử ưu ái dành cho quản lý."},{"en":"The policy bans preferential treatment based on connections.","vi":"Chính sách cấm sự đối xử ưu ái dựa trên quan hệ."},{"en":"Some customers receive preferential treatment for loyalty.","vi":"Một số khách hàng nhận được sự đối xử ưu ái vì lòng trung thành."}]','[]',NULL,'/ˌprefəˈrenʃəl ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5001,'colloc-12-01',61,'preliminary data','dữ liệu sơ bộ','adj + n','[{"en":"The preliminary data suggest a promising trend.","vi":"Dữ liệu sơ bộ cho thấy một xu hướng đầy hứa hẹn."},{"en":"Researchers shared preliminary data at the conference.","vi":"Các nhà nghiên cứu chia sẻ dữ liệu sơ bộ tại hội nghị."},{"en":"Preliminary data must be confirmed by larger studies.","vi":"Dữ liệu sơ bộ cần được xác nhận bằng các nghiên cứu lớn hơn."}]','[]',NULL,'/prɪˈlɪmɪneri ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5002,'colloc-12-01',62,'preliminary findings','những phát hiện sơ bộ','adj + n','[{"en":"Preliminary findings indicate a need for further research.","vi":"Những phát hiện sơ bộ cho thấy cần nghiên cứu thêm."},{"en":"The team presented preliminary findings to the committee.","vi":"Nhóm trình bày những phát hiện sơ bộ cho ủy ban."},{"en":"These preliminary findings should be treated with caution.","vi":"Những phát hiện sơ bộ này nên được xem xét thận trọng."}]','[]',NULL,'/prɪˈlɪmɪneri ˈfaɪndɪŋz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5003,'colloc-12-01',63,'preliminary result','kết quả sơ bộ','adj + n','[{"en":"The preliminary result looks promising but needs confirmation.","vi":"Kết quả sơ bộ trông hứa hẹn nhưng cần được xác nhận."},{"en":"Each preliminary result was reviewed by two experts.","vi":"Mỗi kết quả sơ bộ đều được hai chuyên gia xem xét."},{"en":"The preliminary result supported the team''s hypothesis.","vi":"Kết quả sơ bộ ủng hộ giả thuyết của nhóm."}]','[]',NULL,'/prɪˈlɪmɪneri rɪˈzʌlt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5004,'colloc-12-01',64,'premature death','cái chết yểu (tử vong sớm)','adj + n','[{"en":"Smoking is a leading cause of premature death.","vi":"Hút thuốc là một nguyên nhân hàng đầu gây tử vong sớm."},{"en":"The study links air pollution to premature death.","vi":"Nghiên cứu liên kết ô nhiễm không khí với tử vong sớm."},{"en":"Better healthcare can prevent many premature deaths.","vi":"Chăm sóc y tế tốt hơn có thể ngăn nhiều ca tử vong sớm."}]','[]',NULL,'/ˌpriːməˈtʃʊr deθ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5005,'colloc-12-01',65,'present context','bối cảnh hiện tại','adj + n','[{"en":"In the present context, the old theory no longer applies.","vi":"Trong bối cảnh hiện tại, lý thuyết cũ không còn áp dụng được."},{"en":"The present context demands a new approach to teaching.","vi":"Bối cảnh hiện tại đòi hỏi một cách tiếp cận mới trong giảng dạy."},{"en":"These rules make sense only in the present context.","vi":"Những quy tắc này chỉ hợp lý trong bối cảnh hiện tại."}]','[]',NULL,'/ˈpreznt ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5006,'colloc-12-01',66,'present data','trình bày dữ liệu','v + n','[{"en":"The authors present data from three separate experiments.","vi":"Các tác giả trình bày dữ liệu từ ba thí nghiệm riêng biệt."},{"en":"Researchers must present data clearly and honestly.","vi":"Các nhà nghiên cứu phải trình bày dữ liệu rõ ràng và trung thực."},{"en":"She used charts to present data to the audience.","vi":"Cô dùng biểu đồ để trình bày dữ liệu cho khán giả."}]','[]',NULL,'/prɪˈzent ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5007,'colloc-12-01',67,'present difficulties','gây ra khó khăn','v + n','[{"en":"Translating poetry can present difficulties for any scholar.","vi":"Dịch thơ có thể gây ra khó khăn cho bất kỳ học giả nào."},{"en":"Limited funding present difficulties for many new projects.","vi":"Nguồn tài trợ hạn chế gây ra khó khăn cho nhiều dự án mới."},{"en":"Remote locations present difficulties for data collection.","vi":"Các địa điểm xa xôi gây ra khó khăn cho việc thu thập dữ liệu."}]','[]',NULL,'/prɪˈzent ˈdɪfɪkəltiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5008,'colloc-12-01',68,'present evidence','đưa ra bằng chứng','v + n','[{"en":"The lawyer will present evidence to support the claim.","vi":"Luật sư sẽ đưa ra bằng chứng để hỗ trợ cho lập luận."},{"en":"The authors present evidence from several recent studies.","vi":"Các tác giả đưa ra bằng chứng từ vài nghiên cứu gần đây."},{"en":"Scientists present evidence that the climate is changing.","vi":"Các nhà khoa học đưa ra bằng chứng rằng khí hậu đang thay đổi."}]','[]',NULL,'/prɪˈzent ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5009,'colloc-12-01',69,'present a challenge','đặt ra một thách thức','v + n','[{"en":"Large classes present a challenge for individual attention.","vi":"Lớp học đông đặt ra một thách thức cho việc quan tâm từng học sinh."},{"en":"New technology can present a challenge for older workers.","vi":"Công nghệ mới có thể đặt ra một thách thức cho người lao động lớn tuổi."},{"en":"The disease continues to present a challenge to doctors.","vi":"Căn bệnh tiếp tục đặt ra một thách thức cho các bác sĩ."}]','[]',NULL,'/prɪˈzent ə ˈtʃælɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5010,'colloc-12-01',70,'present a summary','trình bày một bản tóm tắt','v + n','[{"en":"The final chapter present a summary of the main findings.","vi":"Chương cuối trình bày một bản tóm tắt các phát hiện chính."},{"en":"She will present a summary of the report tomorrow.","vi":"Cô sẽ trình bày một bản tóm tắt của báo cáo vào ngày mai."},{"en":"Speakers present a summary before the detailed analysis.","vi":"Diễn giả trình bày một bản tóm tắt trước khi phân tích chi tiết."}]','[]',NULL,'/prɪˈzent ə ˈsʌməri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5011,'colloc-12-01',71,'present an argument','trình bày một lập luận','v + n','[{"en":"The essay must present an argument supported by evidence.","vi":"Bài luận phải trình bày một lập luận được hỗ trợ bằng bằng chứng."},{"en":"He clearly present an argument for stricter regulation.","vi":"Anh trình bày rõ ràng một lập luận ủng hộ quy định chặt chẽ hơn."},{"en":"Students learn to present an argument logically.","vi":"Học sinh học cách trình bày một lập luận một cách logic."}]','[]',NULL,'/prɪˈzent ən ˈɑːrɡjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5012,'colloc-12-01',72,'presidential election','cuộc bầu cử tổng thống','adj + n','[{"en":"The presidential election attracted record voter turnout.","vi":"Cuộc bầu cử tổng thống thu hút số cử tri đi bầu kỷ lục."},{"en":"Analysts studied the results of the presidential election.","vi":"Các nhà phân tích nghiên cứu kết quả của cuộc bầu cử tổng thống."},{"en":"The presidential election dominated the news for months.","vi":"Cuộc bầu cử tổng thống chiếm sóng tin tức suốt nhiều tháng."}]','[]',NULL,'/ˌprezɪˈdenʃəl ɪˈlekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5013,'colloc-12-01',73,'previous chapter','chương trước','adj + n','[{"en":"The previous chapter explained the research design.","vi":"Chương trước đã giải thích thiết kế nghiên cứu."},{"en":"This argument was introduced in the previous chapter.","vi":"Lập luận này đã được giới thiệu ở chương trước."},{"en":"Readers should review the previous chapter first.","vi":"Người đọc nên xem lại chương trước trước tiên."}]','[]',NULL,'/ˈpriːviəs ˈtʃæptər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5014,'colloc-12-01',74,'previous decade','thập kỷ trước','adj + n','[{"en":"Unemployment fell sharply over the previous decade.","vi":"Tỷ lệ thất nghiệp giảm mạnh trong thập kỷ trước."},{"en":"The previous decade saw rapid growth in technology.","vi":"Thập kỷ trước chứng kiến sự phát triển nhanh của công nghệ."},{"en":"Prices rose steadily throughout the previous decade.","vi":"Giá cả tăng đều đặn suốt thập kỷ trước."}]','[]',NULL,'/ˈpriːviəs ˈdekeɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5015,'colloc-12-01',75,'previous discussion','phần thảo luận trước','adj + n','[{"en":"The previous discussion focused on theoretical models.","vi":"Phần thảo luận trước tập trung vào các mô hình lý thuyết."},{"en":"This point builds on our previous discussion.","vi":"Điểm này dựa trên phần thảo luận trước của chúng ta."},{"en":"As the previous discussion showed, opinions differ widely.","vi":"Như phần thảo luận trước cho thấy, các ý kiến rất khác nhau."}]','[]',NULL,'/ˈpriːviəs dɪˈskʌʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5016,'colloc-12-01',76,'previous experience','kinh nghiệm trước đây','adj + n','[{"en":"Previous experience in teaching helped her get the job.","vi":"Kinh nghiệm giảng dạy trước đây giúp cô có được công việc."},{"en":"The role requires previous experience in marketing.","vi":"Vị trí này yêu cầu kinh nghiệm trước đây trong lĩnh vực tiếp thị."},{"en":"His previous experience made the transition easier.","vi":"Kinh nghiệm trước đây của anh giúp quá trình chuyển đổi dễ dàng hơn."}]','[]',NULL,'/ˈpriːviəs ɪkˈspɪriəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5017,'colloc-12-01',77,'previous generation','thế hệ trước','adj + n','[{"en":"The previous generation faced very different challenges.","vi":"Thế hệ trước đã đối mặt với những thách thức rất khác."},{"en":"Young people often reject the values of the previous generation.","vi":"Người trẻ thường bác bỏ các giá trị của thế hệ trước."},{"en":"This device is far faster than the previous generation.","vi":"Thiết bị này nhanh hơn nhiều so với thế hệ trước."}]','[]',NULL,'/ˈpriːviəs ˌdʒenəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5018,'colloc-12-01',78,'previous knowledge','kiến thức đã có từ trước','adj + n','[{"en":"The course assumes no previous knowledge of statistics.","vi":"Khóa học không đòi hỏi kiến thức trước về thống kê."},{"en":"Learners connect new ideas to their previous knowledge.","vi":"Người học kết nối ý tưởng mới với kiến thức đã có từ trước."},{"en":"Previous knowledge of the topic made the reading easier.","vi":"Kiến thức có từ trước về chủ đề khiến việc đọc dễ hơn."}]','[]',NULL,'/ˈpriːviəs ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5019,'colloc-12-01',79,'previous paragraph','đoạn văn trước','adj + n','[{"en":"The previous paragraph introduced the central claim.","vi":"Đoạn văn trước đã giới thiệu luận điểm trung tâm."},{"en":"This idea was mentioned in the previous paragraph.","vi":"Ý tưởng này đã được nhắc đến ở đoạn văn trước."},{"en":"The example supports the point made in the previous paragraph.","vi":"Ví dụ hỗ trợ cho luận điểm nêu ở đoạn văn trước."}]','[]',NULL,'/ˈpriːviəs ˈpærəɡræf/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5020,'colloc-12-01',80,'previous part','phần trước','adj + n','[{"en":"The previous part of the report covered the survey results.","vi":"Phần trước của báo cáo đã đề cập đến kết quả khảo sát."},{"en":"This section continues from the previous part.","vi":"Phần này nối tiếp từ phần trước."},{"en":"Refer to the previous part for the full definitions.","vi":"Hãy tham khảo phần trước để xem đầy đủ các định nghĩa."}]','[]',NULL,'/ˈpriːviəs pɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5021,'colloc-12-01',81,'previous research','nghiên cứu trước đây','adj + n','[{"en":"Previous research suggests a strong link between diet and mood.","vi":"Các nghiên cứu trước đây cho thấy mối liên hệ chặt chẽ giữa chế độ ăn và tâm trạng."},{"en":"Our findings build directly on previous research in this field.","vi":"Phát hiện của chúng tôi dựa trực tiếp vào nghiên cứu trước đây trong lĩnh vực này."},{"en":"Previous research had largely ignored younger age groups.","vi":"Nghiên cứu trước đây phần lớn đã bỏ qua các nhóm tuổi trẻ hơn."}]','[]',NULL,'/ˈpriːviəs rɪˈsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5022,'colloc-12-01',82,'previous section','phần trước đó','adj + n','[{"en":"As noted in the previous section, the method has clear limits.","vi":"Như đã nêu ở phần trước, phương pháp này có những hạn chế rõ ràng."},{"en":"The previous section described the data collection process in detail.","vi":"Phần trước đã mô tả chi tiết quá trình thu thập dữ liệu."},{"en":"We now extend the model introduced in the previous section.","vi":"Bây giờ chúng tôi mở rộng mô hình đã giới thiệu ở phần trước."}]','[]',NULL,'/ˈpriːviəs ˈsekʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5023,'colloc-12-01',83,'previous study','nghiên cứu trước','adj + n','[{"en":"A previous study reported similar results among older patients.","vi":"Một nghiên cứu trước đã báo cáo kết quả tương tự ở bệnh nhân lớn tuổi."},{"en":"This finding contradicts a previous study from the same lab.","vi":"Phát hiện này mâu thuẫn với một nghiên cứu trước từ cùng phòng thí nghiệm."},{"en":"Unlike the previous study, we used a larger sample size.","vi":"Khác với nghiên cứu trước, chúng tôi dùng cỡ mẫu lớn hơn."}]','[]',NULL,'/ˈpriːviəs ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5024,'colloc-12-01',84,'previous work','công trình trước đây','adj + n','[{"en":"Our approach combines ideas from several lines of previous work.","vi":"Cách tiếp cận của chúng tôi kết hợp ý tưởng từ nhiều công trình trước đây."},{"en":"Previous work in this area focused mainly on urban populations.","vi":"Công trình trước đây trong lĩnh vực này chủ yếu tập trung vào dân cư thành thị."},{"en":"She summarized her previous work before presenting new results.","vi":"Cô tóm tắt các công trình trước đây trước khi trình bày kết quả mới."}]','[]',NULL,'/ˈpriːviəs wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5025,'colloc-12-01',85,'previously described','đã được mô tả trước đó','adv + vpp','[{"en":"The samples were prepared using a previously described protocol.","vi":"Các mẫu được chuẩn bị theo quy trình đã mô tả trước đó."},{"en":"We applied the previously described technique to a new dataset.","vi":"Chúng tôi áp dụng kỹ thuật đã mô tả trước đó cho một tập dữ liệu mới."},{"en":"These symptoms match the condition previously described in the literature.","vi":"Các triệu chứng này khớp với tình trạng đã được mô tả trước đó trong tài liệu."}]','[]',NULL,'/ˈpriːviəsli dɪˈskraɪbd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5026,'colloc-12-01',86,'previously discussed','đã được thảo luận trước đó','adv + vpp','[{"en":"The factors previously discussed all contribute to higher costs.","vi":"Các yếu tố đã thảo luận trước đó đều góp phần làm tăng chi phí."},{"en":"As previously discussed, the policy affects rural areas most.","vi":"Như đã thảo luận trước đó, chính sách này ảnh hưởng nhiều nhất đến nông thôn."},{"en":"This section revisits a problem previously discussed in chapter two.","vi":"Phần này xem lại một vấn đề đã thảo luận trước đó ở chương hai."}]','[]',NULL,'/ˈpriːviəsli dɪˈskʌst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5027,'colloc-12-01',87,'previously known','đã được biết đến trước đó','adv + vpp','[{"en":"The species was previously known only from a single region.","vi":"Loài này trước đó chỉ được biết đến ở một vùng duy nhất."},{"en":"This gene was not previously known to affect growth.","vi":"Gen này trước đó chưa được biết là ảnh hưởng đến sự tăng trưởng."},{"en":"The site was previously known by a different local name.","vi":"Địa điểm này trước đó được biết đến bằng một tên địa phương khác."}]','[]',NULL,'/ˈpriːviəsli noʊn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5028,'colloc-12-01',88,'previously mentioned','đã được nhắc đến trước đó','adv + vpp','[{"en":"The previously mentioned limitations apply to this analysis too.","vi":"Các hạn chế đã nhắc đến trước đó cũng áp dụng cho phân tích này."},{"en":"As previously mentioned, the survey covered three countries.","vi":"Như đã nhắc đến trước đó, khảo sát bao gồm ba quốc gia."},{"en":"We now return to the previously mentioned example for clarity.","vi":"Bây giờ chúng tôi quay lại ví dụ đã nhắc đến trước đó cho rõ ràng."}]','[]',NULL,'/ˈpriːviəsli ˈmenʃənd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5029,'colloc-12-01',89,'previously thought','vốn được cho là trước đây','adv + vpp','[{"en":"The disease spreads faster than previously thought.","vi":"Căn bệnh lây lan nhanh hơn so với những gì người ta từng nghĩ."},{"en":"These ruins are older than previously thought by historians.","vi":"Những tàn tích này cổ hơn so với điều các nhà sử học từng nghĩ."},{"en":"The two effects are more closely linked than previously thought.","vi":"Hai tác động này liên kết chặt chẽ hơn so với điều từng được cho là."}]','[]',NULL,'/ˈpriːviəsli θɔːt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5030,'colloc-12-01',90,'primarily concerned with','chủ yếu quan tâm đến','adv + vpp','[{"en":"This chapter is primarily concerned with economic policy and trade.","vi":"Chương này chủ yếu quan tâm đến chính sách kinh tế và thương mại."},{"en":"The study was primarily concerned with how children learn language.","vi":"Nghiên cứu chủ yếu quan tâm đến cách trẻ em học ngôn ngữ."},{"en":"Early researchers were primarily concerned with measuring physical traits.","vi":"Các nhà nghiên cứu thời kỳ đầu chủ yếu quan tâm đến việc đo lường đặc điểm thể chất."}]','[]',NULL,'/praɪˈmerəli kənˈsɜːrnd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5031,'colloc-12-01',91,'primarily responsible for','chịu trách nhiệm chính cho','adv + adj','[{"en":"These cells are primarily responsible for the immune response.","vi":"Các tế bào này chịu trách nhiệm chính cho phản ứng miễn dịch."},{"en":"Local councils are primarily responsible for waste collection services.","vi":"Hội đồng địa phương chịu trách nhiệm chính cho dịch vụ thu gom rác."},{"en":"One enzyme is primarily responsible for breaking down the toxin.","vi":"Một enzyme chịu trách nhiệm chính cho việc phân hủy độc tố."}]','[]',NULL,'/praɪˈmerəli rɪˈspɑːnsəbəl fər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5032,'colloc-12-01',92,'primary aim','mục tiêu chính','adj + n','[{"en":"The primary aim of this study is to reduce error rates.","vi":"Mục tiêu chính của nghiên cứu này là giảm tỷ lệ lỗi."},{"en":"Our primary aim was to improve access for rural patients.","vi":"Mục tiêu chính của chúng tôi là cải thiện khả năng tiếp cận cho bệnh nhân nông thôn."},{"en":"The program''s primary aim is helping students develop critical thinking.","vi":"Mục tiêu chính của chương trình là giúp học sinh phát triển tư duy phản biện."}]','[]',NULL,'/ˈpraɪmeri eɪm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5033,'colloc-12-01',93,'primary care','chăm sóc sức khỏe ban đầu','adj + n','[{"en":"Most patients first seek help through primary care services.","vi":"Hầu hết bệnh nhân tìm kiếm sự hỗ trợ đầu tiên qua dịch vụ chăm sóc sức khỏe ban đầu."},{"en":"Investing in primary care reduces pressure on hospitals.","vi":"Đầu tư vào chăm sóc sức khỏe ban đầu giúp giảm áp lực cho bệnh viện."},{"en":"Primary care doctors often manage chronic conditions over time.","vi":"Bác sĩ chăm sóc ban đầu thường quản lý các bệnh mãn tính theo thời gian."}]','[]',NULL,'/ˈpraɪmeri ker/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5034,'colloc-12-01',94,'primary concern','mối quan tâm hàng đầu','adj + n','[{"en":"Safety remains the primary concern for everyone on the team.","vi":"An toàn vẫn là mối quan tâm hàng đầu của mọi người trong nhóm."},{"en":"Rising costs are a primary concern for many small businesses.","vi":"Chi phí tăng là mối quan tâm hàng đầu của nhiều doanh nghiệp nhỏ."},{"en":"The primary concern of parents was their children''s education.","vi":"Mối quan tâm hàng đầu của phụ huynh là việc học của con cái."}]','[]',NULL,'/ˈpraɪmeri kənˈsɜːrn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5035,'colloc-12-01',95,'primary data','dữ liệu sơ cấp','adj + n','[{"en":"We collected primary data through interviews and field surveys.","vi":"Chúng tôi thu thập dữ liệu sơ cấp qua phỏng vấn và khảo sát thực địa."},{"en":"Primary data offers fresh insight that existing records cannot.","vi":"Dữ liệu sơ cấp mang lại hiểu biết mới mà hồ sơ có sẵn không có."},{"en":"The thesis relies on primary data gathered over two years.","vi":"Luận án dựa vào dữ liệu sơ cấp thu thập trong hai năm."}]','[]',NULL,'/ˈpraɪmeri ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5036,'colloc-12-01',96,'primary education','giáo dục tiểu học','adj + n','[{"en":"Free primary education is a basic right in many countries.","vi":"Giáo dục tiểu học miễn phí là quyền cơ bản ở nhiều quốc gia."},{"en":"Quality primary education lays the foundation for later learning.","vi":"Giáo dục tiểu học chất lượng đặt nền tảng cho việc học sau này."},{"en":"The reform aims to expand primary education in remote villages.","vi":"Cuộc cải cách nhằm mở rộng giáo dục tiểu học ở các làng xa xôi."}]','[]',NULL,'/ˈpraɪmeri ˌedʒəˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5037,'colloc-12-01',97,'primary focus','trọng tâm chính','adj + n','[{"en":"The primary focus of the report is renewable energy growth.","vi":"Trọng tâm chính của báo cáo là sự tăng trưởng năng lượng tái tạo."},{"en":"Customer satisfaction has become the company''s primary focus this year.","vi":"Sự hài lòng của khách hàng đã trở thành trọng tâm chính của công ty năm nay."},{"en":"Her primary focus during the project was data quality.","vi":"Trọng tâm chính của cô trong dự án là chất lượng dữ liệu."}]','[]',NULL,'/ˈpraɪmeri ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5038,'colloc-12-01',98,'primary function','chức năng chính','adj + n','[{"en":"The heart''s primary function is to pump blood around the body.","vi":"Chức năng chính của tim là bơm máu đi khắp cơ thể."},{"en":"The primary function of the device is to monitor temperature.","vi":"Chức năng chính của thiết bị là theo dõi nhiệt độ."},{"en":"A library''s primary function is to provide access to knowledge.","vi":"Chức năng chính của thư viện là cung cấp khả năng tiếp cận tri thức."}]','[]',NULL,'/ˈpraɪmeri ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5039,'colloc-12-01',99,'primary objective','mục tiêu chính','adj + n','[{"en":"The primary objective is to lower unemployment in the region.","vi":"Mục tiêu chính là giảm tỷ lệ thất nghiệp trong khu vực."},{"en":"Reducing waste was the primary objective of the new plan.","vi":"Giảm rác thải là mục tiêu chính của kế hoạch mới."},{"en":"Each team set a clear primary objective for the quarter.","vi":"Mỗi nhóm đặt ra một mục tiêu chính rõ ràng cho quý."}]','[]',NULL,'/ˈpraɪmeri əbˈdʒektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5040,'colloc-12-01',100,'primary purpose','mục đích chính','adj + n','[{"en":"The primary purpose of the survey was to gather opinions.","vi":"Mục đích chính của khảo sát là thu thập ý kiến."},{"en":"Its primary purpose is to protect users from online fraud.","vi":"Mục đích chính của nó là bảo vệ người dùng khỏi lừa đảo trực tuyến."},{"en":"The fund''s primary purpose is supporting research in medicine.","vi":"Mục đích chính của quỹ là hỗ trợ nghiên cứu y học."}]','[]',NULL,'/ˈpraɪmeri ˈpɜːrpəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5041,'colloc-12-01',101,'primary reason','lý do chính','adj + n','[{"en":"Cost was the primary reason for delaying the project.","vi":"Chi phí là lý do chính khiến dự án bị trì hoãn."},{"en":"The primary reason for the change is improved efficiency.","vi":"Lý do chính cho sự thay đổi là cải thiện hiệu quả."},{"en":"Poor weather was the primary reason for the low turnout.","vi":"Thời tiết xấu là lý do chính cho lượng người tham dự thấp."}]','[]',NULL,'/ˈpraɪmeri ˈriːzən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5042,'colloc-12-01',102,'primary research','nghiên cứu sơ cấp','adj + n','[{"en":"The essay combines primary research with published statistics.","vi":"Bài luận kết hợp nghiên cứu sơ cấp với số liệu thống kê đã công bố."},{"en":"Conducting primary research requires careful planning and ethical approval.","vi":"Tiến hành nghiên cứu sơ cấp đòi hỏi lập kế hoạch kỹ lưỡng và phê duyệt đạo đức."},{"en":"Students learn primary research methods such as interviews and observation.","vi":"Sinh viên học các phương pháp nghiên cứu sơ cấp như phỏng vấn và quan sát."}]','[]',NULL,'/ˈpraɪmeri rɪˈsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5043,'colloc-12-01',103,'primary responsibility','trách nhiệm chính','adj + n','[{"en":"Her primary responsibility is managing the research budget carefully.","vi":"Trách nhiệm chính của cô là quản lý ngân sách nghiên cứu cẩn thận."},{"en":"Schools bear primary responsibility for keeping students safe.","vi":"Trường học gánh trách nhiệm chính trong việc giữ an toàn cho học sinh."},{"en":"The minister''s primary responsibility is overseeing public health policy.","vi":"Trách nhiệm chính của bộ trưởng là giám sát chính sách y tế công cộng."}]','[]',NULL,'/ˈpraɪmeri rɪˌspɑːnsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5044,'colloc-12-01',104,'primary source','nguồn sơ cấp','adj + n','[{"en":"Letters and diaries serve as a valuable primary source.","vi":"Thư từ và nhật ký là nguồn sơ cấp quý giá."},{"en":"Historians prefer a primary source to a later commentary.","vi":"Các nhà sử học thích nguồn sơ cấp hơn là bình luận về sau."},{"en":"The interview became the primary source for her dissertation.","vi":"Cuộc phỏng vấn trở thành nguồn sơ cấp cho luận văn của cô."}]','[]',NULL,'/ˈpraɪmeri sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5045,'colloc-12-01',105,'primary task','nhiệm vụ chính','adj + n','[{"en":"The primary task of the committee is reviewing applications.","vi":"Nhiệm vụ chính của ủy ban là xem xét các đơn đăng ký."},{"en":"His primary task was to translate the documents accurately.","vi":"Nhiệm vụ chính của anh là dịch các tài liệu một cách chính xác."},{"en":"Our primary task this week is testing the new software.","vi":"Nhiệm vụ chính của chúng tôi tuần này là kiểm thử phần mềm mới."}]','[]',NULL,'/ˈpraɪmeri tæsk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5046,'colloc-12-01',106,'prime example','ví dụ điển hình','adj + n','[{"en":"This city is a prime example of rapid urban growth.","vi":"Thành phố này là ví dụ điển hình của sự phát triển đô thị nhanh chóng."},{"en":"Her speech offered a prime example of persuasive writing.","vi":"Bài phát biểu của cô là ví dụ điển hình của lối viết thuyết phục."},{"en":"The reform is a prime example of successful public policy.","vi":"Cuộc cải cách là ví dụ điển hình của chính sách công thành công."}]','[]',NULL,'/praɪm ɪɡˈzæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5047,'colloc-12-01',107,'prime time','khung giờ vàng','adj + n','[{"en":"The debate was broadcast during prime time on national television.","vi":"Cuộc tranh luận được phát sóng vào khung giờ vàng trên truyền hình quốc gia."},{"en":"Advertising during prime time costs far more than late slots.","vi":"Quảng cáo vào khung giờ vàng tốn kém hơn nhiều so với khung giờ khuya."},{"en":"The popular show dominates prime time every weekday evening.","vi":"Chương trình nổi tiếng thống trị khung giờ vàng mỗi tối ngày thường."}]','[]',NULL,'/praɪm taɪm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5048,'colloc-12-01',108,'principal source','nguồn chủ yếu','adj + n','[{"en":"Coal was once the principal source of energy worldwide.","vi":"Than đá từng là nguồn năng lượng chủ yếu trên toàn thế giới."},{"en":"Tourism is the principal source of income for the island.","vi":"Du lịch là nguồn thu nhập chủ yếu của hòn đảo."},{"en":"Newspapers remain a principal source of local news for many.","vi":"Báo chí vẫn là nguồn tin tức địa phương chủ yếu với nhiều người."}]','[]',NULL,'/ˈprɪnsəpəl sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5049,'colloc-12-01',109,'prior experience','kinh nghiệm trước đó','adj + n','[{"en":"No prior experience is needed to join the workshop.","vi":"Không cần kinh nghiệm trước đó để tham gia hội thảo."},{"en":"Her prior experience in nursing helped during the crisis.","vi":"Kinh nghiệm điều dưỡng trước đó của cô đã giúp ích trong khủng hoảng."},{"en":"Applicants with prior experience are given strong preference.","vi":"Ứng viên có kinh nghiệm trước đó được ưu tiên rõ rệt."}]','[]',NULL,'/ˈpraɪər ɪkˈspɪriəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5050,'colloc-12-01',110,'prior knowledge','kiến thức nền có sẵn','adj + n','[{"en":"Learners connect new ideas to their prior knowledge.","vi":"Người học kết nối ý tưởng mới với kiến thức nền có sẵn của mình."},{"en":"The test assumes some prior knowledge of basic statistics.","vi":"Bài kiểm tra giả định có sẵn một số kiến thức cơ bản về thống kê."},{"en":"Teachers should assess students'' prior knowledge before each unit.","vi":"Giáo viên nên đánh giá kiến thức nền của học sinh trước mỗi bài."}]','[]',NULL,'/ˈpraɪər ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5051,'colloc-12-01',111,'private individual','cá nhân riêng lẻ','adj + n','[{"en":"A private individual donated the land to the city.","vi":"Một cá nhân riêng lẻ đã hiến tặng mảnh đất cho thành phố."},{"en":"The law protects a private individual''s personal data online.","vi":"Luật bảo vệ dữ liệu cá nhân của một cá nhân riêng lẻ trên mạng."},{"en":"Such loans are rarely available to a private individual.","vi":"Những khoản vay như vậy hiếm khi dành cho một cá nhân riêng lẻ."}]','[]',NULL,'/ˈpraɪvət ˌɪndɪˈvɪdʒuəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5052,'colloc-12-01',112,'private investment','đầu tư tư nhân','adj + n','[{"en":"Private investment in clean energy rose sharply last year.","vi":"Đầu tư tư nhân vào năng lượng sạch tăng mạnh năm ngoái."},{"en":"The government hopes to attract more private investment in transport.","vi":"Chính phủ hy vọng thu hút thêm đầu tư tư nhân vào giao thông."},{"en":"Private investment often complements public funding for large projects.","vi":"Đầu tư tư nhân thường bổ sung cho nguồn vốn công cho các dự án lớn."}]','[]',NULL,'/ˈpraɪvət ɪnˈvestmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5053,'colloc-12-01',113,'private sector','khu vực tư nhân','adj + n','[{"en":"Many graduates prefer jobs in the private sector.","vi":"Nhiều sinh viên tốt nghiệp thích công việc trong khu vực tư nhân."},{"en":"The private sector now delivers many former public services.","vi":"Khu vực tư nhân hiện cung cấp nhiều dịch vụ công trước đây."},{"en":"Wages in the private sector vary widely across industries.","vi":"Tiền lương trong khu vực tư nhân chênh lệch lớn giữa các ngành."}]','[]',NULL,'/ˈpraɪvət ˈsektər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5054,'colloc-12-01',114,'private sphere','lĩnh vực riêng tư','adj + n','[{"en":"These decisions belong to the private sphere, not the state.","vi":"Những quyết định này thuộc lĩnh vực riêng tư, không phải của nhà nước."},{"en":"Historically, women were confined to the private sphere of home.","vi":"Trong lịch sử, phụ nữ bị giới hạn trong lĩnh vực riêng tư của gia đình."},{"en":"The book explores how technology invades the private sphere.","vi":"Cuốn sách khám phá cách công nghệ xâm phạm lĩnh vực riêng tư."}]','[]',NULL,'/ˈpraɪvət sfɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5055,'colloc-12-01',115,'privileged position','vị thế đặc quyền','adj + n','[{"en":"Wealthy families often enjoy a privileged position in society.","vi":"Các gia đình giàu có thường có vị thế đặc quyền trong xã hội."},{"en":"The bank holds a privileged position in the local economy.","vi":"Ngân hàng giữ vị thế đặc quyền trong nền kinh tế địa phương."},{"en":"Editors occupy a privileged position in shaping public opinion.","vi":"Các biên tập viên chiếm vị thế đặc quyền trong việc định hình dư luận."}]','[]',NULL,'/ˈprɪvəlɪdʒd pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5056,'colloc-12-01',116,'problem area','lĩnh vực có vấn đề','n + n','[{"en":"The audit identified several problem areas in the system.","vi":"Cuộc kiểm toán đã xác định một số lĩnh vực có vấn đề trong hệ thống."},{"en":"Traffic congestion is a major problem area for the city.","vi":"Tắc nghẽn giao thông là một lĩnh vực có vấn đề lớn của thành phố."},{"en":"The teacher focused revision on each student''s main problem areas.","vi":"Giáo viên tập trung ôn tập vào các lĩnh vực có vấn đề chính của từng học sinh."}]','[]',NULL,'/ˈprɑːbləm ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5057,'colloc-12-01',117,'process data','xử lý dữ liệu','v + n','[{"en":"The software can process data from thousands of sensors instantly.","vi":"Phần mềm có thể xử lý dữ liệu từ hàng nghìn cảm biến ngay lập tức."},{"en":"Analysts process data carefully before drawing any conclusions.","vi":"Các nhà phân tích xử lý dữ liệu cẩn thận trước khi rút ra kết luận."},{"en":"Companies must process data fairly under privacy law.","vi":"Các công ty phải xử lý dữ liệu một cách công bằng theo luật bảo mật."}]','[]',NULL,'/ˈprɑːses ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5058,'colloc-12-01',118,'process information','xử lý thông tin','v + n','[{"en":"The brain can process information remarkably quickly.","vi":"Não bộ có thể xử lý thông tin nhanh một cách đáng kinh ngạc."},{"en":"Children process information differently from adults in many tasks.","vi":"Trẻ em xử lý thông tin khác với người lớn trong nhiều nhiệm vụ."},{"en":"The system helps users process information from multiple sources.","vi":"Hệ thống giúp người dùng xử lý thông tin từ nhiều nguồn."}]','[]',NULL,'/ˈprɑːses ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5059,'colloc-12-01',119,'professional activity','hoạt động nghề nghiệp','adj + n','[{"en":"Teaching is the main professional activity recorded in her file.","vi":"Giảng dạy là hoạt động nghề nghiệp chính được ghi trong hồ sơ của cô."},{"en":"Conferences are an important professional activity for researchers.","vi":"Hội nghị là một hoạt động nghề nghiệp quan trọng đối với nhà nghiên cứu."},{"en":"The survey tracked the professional activity of recent graduates.","vi":"Khảo sát theo dõi hoạt động nghề nghiệp của sinh viên mới tốt nghiệp."}]','[]',NULL,'/prəˈfeʃənəl ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5060,'colloc-12-01',120,'professional body','tổ chức nghề nghiệp','adj + n','[{"en":"The professional body sets ethical standards for all members.","vi":"Tổ chức nghề nghiệp đặt ra các tiêu chuẩn đạo đức cho mọi thành viên."},{"en":"Engineers must register with the relevant professional body.","vi":"Các kỹ sư phải đăng ký với tổ chức nghề nghiệp liên quan."},{"en":"A professional body can revoke a member''s license for misconduct.","vi":"Tổ chức nghề nghiệp có thể thu hồi giấy phép của thành viên vì vi phạm."}]','[]',NULL,'/prəˈfeʃənəl ˈbɑːdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5061,'colloc-12-01',121,'professional colleague','đồng nghiệp','adj + n','[{"en":"She discussed the diagnosis with a professional colleague first.","vi":"Cô thảo luận chẩn đoán với một đồng nghiệp trước."},{"en":"Sharing ideas with a professional colleague improves your own work.","vi":"Chia sẻ ý tưởng với đồng nghiệp giúp cải thiện công việc của bạn."},{"en":"He praised a professional colleague for the careful analysis.","vi":"Anh khen ngợi một đồng nghiệp vì sự phân tích cẩn thận."}]','[]',NULL,'/prəˈfeʃənəl ˈkɑːliːɡ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5062,'colloc-12-01',122,'professional development','phát triển nghề nghiệp','adj + n','[{"en":"The school funds ongoing professional development for its teachers.","vi":"Trường tài trợ cho việc phát triển nghề nghiệp liên tục cho giáo viên."},{"en":"Professional development helps staff keep up with new methods.","vi":"Phát triển nghề nghiệp giúp nhân viên theo kịp các phương pháp mới."},{"en":"She attends workshops as part of her professional development.","vi":"Cô tham dự các hội thảo như một phần của việc phát triển nghề nghiệp."}]','[]',NULL,'/prəˈfeʃənəl dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5063,'colloc-12-01',123,'professional experience','kinh nghiệm nghề nghiệp','adj + n','[{"en":"Years of professional experience shaped his teaching style.","vi":"Nhiều năm kinh nghiệm nghề nghiệp đã định hình phong cách giảng dạy của ông."},{"en":"The internship gives students valuable professional experience early.","vi":"Kỳ thực tập mang lại cho sinh viên kinh nghiệm nghề nghiệp quý giá từ sớm."},{"en":"Employers value relevant professional experience over formal qualifications.","vi":"Nhà tuyển dụng coi trọng kinh nghiệm nghề nghiệp liên quan hơn bằng cấp chính thức."}]','[]',NULL,'/prəˈfeʃənəl ɪkˈspɪriəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5064,'colloc-12-01',124,'professional knowledge','kiến thức chuyên môn','adj + n','[{"en":"Doctors must constantly update their professional knowledge.","vi":"Bác sĩ phải liên tục cập nhật kiến thức chuyên môn của mình."},{"en":"Her deep professional knowledge made the report highly reliable.","vi":"Kiến thức chuyên môn sâu rộng của cô khiến báo cáo rất đáng tin cậy."},{"en":"The course builds professional knowledge through real case studies.","vi":"Khóa học xây dựng kiến thức chuyên môn qua các tình huống thực tế."}]','[]',NULL,'/prəˈfeʃənəl ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5065,'colloc-12-01',125,'professional practice','hành nghề chuyên môn','adj + n','[{"en":"Ethics guidelines shape everyday professional practice in medicine.","vi":"Hướng dẫn đạo đức định hình việc hành nghề chuyên môn hằng ngày trong y khoa."},{"en":"Reflection is central to improving one''s professional practice.","vi":"Sự tự suy ngẫm là cốt lõi để cải thiện việc hành nghề chuyên môn."},{"en":"The course connects academic theory with real professional practice.","vi":"Khóa học kết nối lý thuyết học thuật với việc hành nghề chuyên môn thực tế."}]','[]',NULL,'/prəˈfeʃənəl ˈpræktɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5066,'colloc-12-01',126,'professional qualification','chứng chỉ hành nghề','adj + n','[{"en":"The role requires a recognized professional qualification in accounting.","vi":"Vị trí này đòi hỏi một chứng chỉ hành nghề được công nhận về kế toán."},{"en":"She earned her professional qualification after three years of study.","vi":"Cô đạt được chứng chỉ hành nghề sau ba năm học tập."},{"en":"Some professional qualifications must be renewed every few years.","vi":"Một số chứng chỉ hành nghề phải được gia hạn vài năm một lần."}]','[]',NULL,'/prəˈfeʃənəl ˌkwɑːləfəˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5067,'colloc-12-01',127,'professional staff','đội ngũ nhân viên chuyên môn','adj + n','[{"en":"The clinic employs highly trained professional staff around the clock.","vi":"Phòng khám có đội ngũ nhân viên chuyên môn được đào tạo bài bản suốt ngày đêm."},{"en":"Professional staff handle inquiries that volunteers cannot answer.","vi":"Nhân viên chuyên môn xử lý các thắc mắc mà tình nguyện viên không thể trả lời."},{"en":"The university expanded its professional staff to support research.","vi":"Trường đại học mở rộng đội ngũ nhân viên chuyên môn để hỗ trợ nghiên cứu."}]','[]',NULL,'/prəˈfeʃənəl stæf/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5068,'colloc-12-01',128,'professional standard','chuẩn mực nghề nghiệp','adj + n','[{"en":"All work must meet a high professional standard.","vi":"Mọi công việc phải đáp ứng chuẩn mực nghề nghiệp cao."},{"en":"Breaching the professional standard can lead to disciplinary action.","vi":"Vi phạm chuẩn mực nghề nghiệp có thể dẫn đến biện pháp kỷ luật."},{"en":"The association reviews its professional standards every five years.","vi":"Hiệp hội xem xét lại các chuẩn mực nghề nghiệp của mình năm năm một lần."}]','[]',NULL,'/prəˈfeʃənəl ˈstændərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5069,'colloc-12-01',129,'professional status','địa vị nghề nghiệp','adj + n','[{"en":"Gaining professional status often requires passing a formal exam.","vi":"Đạt được địa vị nghề nghiệp thường đòi hỏi phải vượt qua kỳ thi chính thức."},{"en":"The reform raised the professional status of nurses nationwide.","vi":"Cuộc cải cách nâng cao địa vị nghề nghiệp của y tá trên toàn quốc."},{"en":"Teachers fought hard to protect their professional status.","vi":"Giáo viên đấu tranh mạnh mẽ để bảo vệ địa vị nghề nghiệp của mình."}]','[]',NULL,'/prəˈfeʃənəl ˈsteɪtəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5070,'colloc-12-01',130,'professional support','hỗ trợ chuyên môn','adj + n','[{"en":"Patients receive professional support throughout their recovery.","vi":"Bệnh nhân nhận được hỗ trợ chuyên môn trong suốt quá trình hồi phục."},{"en":"New teachers benefit from professional support during their first year.","vi":"Giáo viên mới hưởng lợi từ hỗ trợ chuyên môn trong năm đầu tiên."},{"en":"The charity offers professional support to families in crisis.","vi":"Tổ chức từ thiện cung cấp hỗ trợ chuyên môn cho các gia đình gặp khủng hoảng."}]','[]',NULL,'/prəˈfeʃənəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5071,'colloc-12-01',131,'professional training','đào tạo chuyên môn','adj + n','[{"en":"The program offers professional training for future social workers.","vi":"Chương trình cung cấp đào tạo chuyên môn cho nhân viên xã hội tương lai."},{"en":"Without proper professional training, errors become far more likely.","vi":"Nếu không có đào tạo chuyên môn phù hợp, sai sót dễ xảy ra hơn nhiều."},{"en":"She completed her professional training at a leading hospital.","vi":"Cô hoàn thành đào tạo chuyên môn tại một bệnh viện hàng đầu."}]','[]',NULL,'/prəˈfeʃənəl ˈtreɪnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5072,'colloc-12-01',132,'professional work','công việc chuyên môn','adj + n','[{"en":"Her professional work spans both teaching and clinical research.","vi":"Công việc chuyên môn của cô trải dài cả giảng dạy lẫn nghiên cứu lâm sàng."},{"en":"He balances professional work with caring for his family.","vi":"Anh cân bằng công việc chuyên môn với việc chăm sóc gia đình."},{"en":"The exhibition displays professional work by emerging architects.","vi":"Triển lãm trưng bày công việc chuyên môn của các kiến trúc sư mới nổi."}]','[]',NULL,'/prəˈfeʃənəl wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5073,'colloc-12-01',133,'profound effect','ảnh hưởng sâu sắc','adj + n','[{"en":"The new policy had a profound effect on rural communities.","vi":"Chính sách mới có ảnh hưởng sâu sắc đến các cộng đồng nông thôn."},{"en":"Early childhood experiences have a profound effect on development.","vi":"Trải nghiệm thời thơ ấu có ảnh hưởng sâu sắc đến sự phát triển."},{"en":"Her mentor''s advice had a profound effect on her career.","vi":"Lời khuyên của người cố vấn có ảnh hưởng sâu sắc đến sự nghiệp của cô."}]','[]',NULL,'/prəˈfaʊnd ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5074,'colloc-12-01',134,'profound impact','tác động sâu sắc','adj + n','[{"en":"The internet has had a profound impact on daily life.","vi":"Internet đã có tác động sâu sắc đến cuộc sống hằng ngày."},{"en":"Climate change is expected to have a profound impact globally.","vi":"Biến đổi khí hậu được dự đoán sẽ có tác động sâu sắc trên toàn cầu."},{"en":"The reform had a profound impact on how schools operate.","vi":"Cuộc cải cách có tác động sâu sắc đến cách các trường vận hành."}]','[]',NULL,'/prəˈfaʊnd ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5075,'colloc-12-01',135,'prominent feature','đặc điểm nổi bật','adj + n','[{"en":"The tower is a prominent feature of the city skyline.","vi":"Tòa tháp là đặc điểm nổi bật của đường chân trời thành phố."},{"en":"Repetition is a prominent feature of the poet''s style.","vi":"Sự lặp lại là đặc điểm nổi bật trong phong cách của nhà thơ."},{"en":"Strong color contrast is a prominent feature of her paintings.","vi":"Sự tương phản màu mạnh mẽ là đặc điểm nổi bật trong tranh của cô."}]','[]',NULL,'/ˈprɑːmɪnənt ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5076,'colloc-12-01',136,'prominent member','thành viên nổi bật','adj + n','[{"en":"She was a prominent member of the research committee.","vi":"Bà là một thành viên nổi bật của ủy ban nghiên cứu."},{"en":"He became a prominent member of the local business community.","vi":"Ông trở thành một thành viên nổi bật của cộng đồng doanh nghiệp địa phương."},{"en":"Several prominent members of the party opposed the new bill.","vi":"Một số thành viên nổi bật của đảng phản đối dự luật mới."}]','[]',NULL,'/ˈprɑːmɪnənt ˈmembər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5077,'colloc-12-01',137,'prominent role','vai trò nổi bật','adj + n','[{"en":"Women played a prominent role in the social movement.","vi":"Phụ nữ đóng vai trò nổi bật trong phong trào xã hội."},{"en":"Technology now plays a prominent role in modern teaching.","vi":"Công nghệ ngày nay đóng vai trò nổi bật trong giảng dạy hiện đại."},{"en":"The charity took a prominent role in the relief effort.","vi":"Tổ chức từ thiện đóng vai trò nổi bật trong nỗ lực cứu trợ."}]','[]',NULL,'/ˈprɑːmɪnənt roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5078,'colloc-12-01',138,'promote equality','thúc đẩy bình đẳng','v + n','[{"en":"The new law aims to promote equality in the workplace.","vi":"Luật mới nhằm thúc đẩy bình đẳng tại nơi làm việc."},{"en":"Schools can promote equality by treating all students fairly.","vi":"Trường học có thể thúc đẩy bình đẳng bằng cách đối xử công bằng với mọi học sinh."},{"en":"The campaign was designed to promote equality between the sexes.","vi":"Chiến dịch được thiết kế để thúc đẩy bình đẳng giữa hai giới."}]','[]',NULL,'/prəˈmoʊt ɪˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5079,'colloc-12-01',139,'promote the development of','thúc đẩy sự phát triển của','v + n','[{"en":"These programs promote the development of critical thinking skills.","vi":"Các chương trình này thúc đẩy sự phát triển của kỹ năng tư duy phản biện."},{"en":"Funding helps promote the development of renewable energy sources.","vi":"Nguồn vốn giúp thúc đẩy sự phát triển của các nguồn năng lượng tái tạo."},{"en":"Good nutrition can promote the development of healthy children.","vi":"Dinh dưỡng tốt có thể thúc đẩy sự phát triển của trẻ em khỏe mạnh."}]','[]',NULL,'/prəˈmoʊt ðə dɪˈveləpmənt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5080,'colloc-12-01',140,'properly understood','được hiểu đúng đắn','adv + vpp','[{"en":"When properly understood, the theory explains many observations.","vi":"Khi được hiểu đúng đắn, lý thuyết này giải thích nhiều quan sát."},{"en":"The risks must be properly understood before any decision.","vi":"Các rủi ro phải được hiểu đúng đắn trước khi đưa ra quyết định nào."},{"en":"Properly understood, the data point to a clear trend.","vi":"Nếu được hiểu đúng đắn, dữ liệu chỉ ra một xu hướng rõ ràng."}]','[]',NULL,'/ˈprɑːpərli ˌʌndərˈstʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5081,'colloc-12-01',141,'proposed legislation','dự thảo luật','adj + n','[{"en":"The proposed legislation would tighten rules on data privacy.","vi":"Dự thảo luật sẽ siết chặt các quy định về quyền riêng tư dữ liệu."},{"en":"Critics argue the proposed legislation could harm small businesses.","vi":"Các nhà phê bình cho rằng dự thảo luật có thể gây hại cho doanh nghiệp nhỏ."},{"en":"The committee will review the proposed legislation next week.","vi":"Ủy ban sẽ xem xét dự thảo luật vào tuần tới."}]','[]',NULL,'/prəˈpoʊzd ˌledʒɪsˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5082,'colloc-12-01',142,'prove successful','tỏ ra thành công','v + adj','[{"en":"The new strategy is likely to prove successful over time.","vi":"Chiến lược mới có khả năng tỏ ra thành công theo thời gian."},{"en":"If the trial proves successful, the drug will be approved.","vi":"Nếu thử nghiệm tỏ ra thành công, loại thuốc sẽ được phê duyệt."},{"en":"The pilot scheme proved successful and was quickly expanded.","vi":"Chương trình thí điểm tỏ ra thành công và nhanh chóng được mở rộng."}]','[]',NULL,'/pruːv səkˈsesfəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5083,'colloc-12-01',143,'prove useful','tỏ ra hữu ích','v + adj','[{"en":"These notes may prove useful when you revise later.","vi":"Những ghi chú này có thể tỏ ra hữu ích khi bạn ôn lại sau."},{"en":"The model proved useful for predicting seasonal demand.","vi":"Mô hình tỏ ra hữu ích trong việc dự đoán nhu cầu theo mùa."},{"en":"Her language skills proved useful during the field study.","vi":"Kỹ năng ngôn ngữ của cô tỏ ra hữu ích trong chuyến nghiên cứu thực địa."}]','[]',NULL,'/pruːv ˈjuːsfəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5084,'colloc-12-01',144,'provide access to','cung cấp quyền truy cập đến','v + n','[{"en":"The library aims to provide access to digital archives.","vi":"Thư viện hướng tới cung cấp quyền truy cập đến kho lưu trữ số."},{"en":"The program provides access to clean water in rural areas.","vi":"Chương trình cung cấp khả năng tiếp cận nước sạch ở vùng nông thôn."},{"en":"Scholarships provide access to higher education for low-income students.","vi":"Học bổng cung cấp cơ hội tiếp cận giáo dục đại học cho sinh viên thu nhập thấp."}]','[]',NULL,'/prəˈvaɪd ˈækses tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5085,'colloc-12-01',145,'provide assistance','cung cấp sự hỗ trợ','v + n','[{"en":"Volunteers provide assistance to families affected by the flood.","vi":"Tình nguyện viên cung cấp sự hỗ trợ cho các gia đình bị ảnh hưởng bởi lũ."},{"en":"The office provides assistance to students with disabilities.","vi":"Văn phòng cung cấp sự hỗ trợ cho sinh viên khuyết tật."},{"en":"International agencies provide assistance during humanitarian crises.","vi":"Các cơ quan quốc tế cung cấp sự hỗ trợ trong khủng hoảng nhân đạo."}]','[]',NULL,'/prəˈvaɪd əˈsɪstəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5086,'colloc-12-01',146,'provide care','cung cấp sự chăm sóc','v + n','[{"en":"Nurses provide care for patients throughout the night.","vi":"Y tá cung cấp sự chăm sóc cho bệnh nhân suốt đêm."},{"en":"The charity provides care for elderly people living alone.","vi":"Tổ chức từ thiện cung cấp sự chăm sóc cho người già sống một mình."},{"en":"Family members often provide care without any formal training.","vi":"Các thành viên gia đình thường cung cấp sự chăm sóc mà không được đào tạo chính thức."}]','[]',NULL,'/prəˈvaɪd ker/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5087,'colloc-12-01',147,'provide context','cung cấp bối cảnh','v + n','[{"en":"The introduction provides context for the entire argument.","vi":"Phần mở đầu cung cấp bối cảnh cho toàn bộ lập luận."},{"en":"Historical examples provide context for current political debates.","vi":"Các ví dụ lịch sử cung cấp bối cảnh cho các cuộc tranh luận chính trị hiện nay."},{"en":"A short summary can provide context for new readers.","vi":"Một bản tóm tắt ngắn có thể cung cấp bối cảnh cho độc giả mới."}]','[]',NULL,'/prəˈvaɪd ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5088,'colloc-12-01',148,'provide coverage','cung cấp sự bao phủ','v + n','[{"en":"The policy provides coverage for both accidents and illness.","vi":"Chính sách cung cấp sự bảo hiểm cho cả tai nạn lẫn bệnh tật."},{"en":"New towers provide coverage to previously unconnected rural areas.","vi":"Các cột phát sóng mới cung cấp sự phủ sóng cho vùng nông thôn trước đây chưa kết nối."},{"en":"The network struggles to provide coverage in mountainous regions.","vi":"Mạng lưới gặp khó khăn trong việc cung cấp phủ sóng ở vùng núi."}]','[]',NULL,'/prəˈvaɪd ˈkʌvərɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5089,'colloc-12-01',149,'provide data','cung cấp dữ liệu','v + n','[{"en":"The sensors provide data on temperature and humidity continuously.","vi":"Các cảm biến cung cấp dữ liệu về nhiệt độ và độ ẩm liên tục."},{"en":"Participants agreed to provide data for the long-term study.","vi":"Người tham gia đồng ý cung cấp dữ liệu cho nghiên cứu dài hạn."},{"en":"The census provides data used by planners and researchers.","vi":"Cuộc điều tra dân số cung cấp dữ liệu cho các nhà quy hoạch và nghiên cứu."}]','[]',NULL,'/prəˈvaɪd ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5090,'colloc-12-01',150,'provide details','cung cấp chi tiết','v + n','[{"en":"Please provide details of your previous work experience.","vi":"Vui lòng cung cấp chi tiết về kinh nghiệm làm việc trước đây của bạn."},{"en":"The report fails to provide details about the methodology.","vi":"Báo cáo không cung cấp chi tiết về phương pháp luận."},{"en":"The website provides details on opening hours and fees.","vi":"Trang web cung cấp chi tiết về giờ mở cửa và phí."}]','[]',NULL,'/prəˈvaɪd ˈdiːteɪlz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5091,'colloc-13-01',1,'provide evidence','cung cấp bằng chứng','v + n','[{"en":"The study provides evidence that exercise improves memory.","vi":"Nghiên cứu cung cấp bằng chứng rằng tập thể dục cải thiện trí nhớ."},{"en":"You must provide evidence to support every claim you make.","vi":"Bạn phải cung cấp bằng chứng để hỗ trợ cho mọi khẳng định của mình."},{"en":"Fossils provide evidence of life from millions of years ago.","vi":"Hóa thạch cung cấp bằng chứng về sự sống từ hàng triệu năm trước."}]','[]',NULL,'/prəˈvaɪd ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5092,'colloc-13-01',2,'provide feedback','đưa ra phản hồi','v + n','[{"en":"The tutor will provide feedback on your draft next week.","vi":"Người hướng dẫn sẽ đưa ra phản hồi về bản nháp của bạn tuần tới."},{"en":"Managers should provide feedback that is specific and constructive.","vi":"Quản lý nên đưa ra phản hồi cụ thể và mang tính xây dựng."},{"en":"Students are encouraged to provide feedback on the course.","vi":"Sinh viên được khuyến khích đưa ra phản hồi về khóa học."}]','[]',NULL,'/prəˈvaɪd ˈfiːdbæk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5093,'colloc-13-01',3,'provide guidance','đưa ra sự hướng dẫn','v + n','[{"en":"The handbook provides guidance for new staff members.","vi":"Cuốn sổ tay đưa ra sự hướng dẫn cho các nhân viên mới."},{"en":"Mentors provide guidance to students throughout their final year.","vi":"Người cố vấn đưa ra sự hướng dẫn cho sinh viên suốt năm cuối."},{"en":"The agency provides guidance on applying for research grants.","vi":"Cơ quan đưa ra sự hướng dẫn về việc xin tài trợ nghiên cứu."}]','[]',NULL,'/prəˈvaɪd ˈɡaɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5094,'colloc-13-01',4,'provide information','cung cấp thông tin','v + n','[{"en":"The leaflet provides information about local health services.","vi":"Tờ rơi cung cấp thông tin về các dịch vụ y tế địa phương."},{"en":"Witnesses agreed to provide information to the investigators.","vi":"Các nhân chứng đồng ý cung cấp thông tin cho các điều tra viên."},{"en":"The website provides information on visa requirements for travelers.","vi":"Trang web cung cấp thông tin về yêu cầu thị thực cho khách du lịch."}]','[]',NULL,'/prəˈvaɪd ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5095,'colloc-13-01',5,'provide insight into','mang lại hiểu biết sâu về','v + n','[{"en":"The interviews provide insight into how patients cope daily.","vi":"Các cuộc phỏng vấn mang lại hiểu biết sâu về cách bệnh nhân xoay xở hằng ngày."},{"en":"These letters provide insight into life during the war.","vi":"Những lá thư này mang lại hiểu biết sâu về cuộc sống thời chiến."},{"en":"The data provide insight into changing consumer habits.","vi":"Dữ liệu mang lại hiểu biết sâu về thói quen tiêu dùng đang thay đổi."}]','[]',NULL,'/prəˈvaɪd ˈɪnsaɪt ˈɪntə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5096,'colloc-13-01',6,'provide material','cung cấp tài liệu','v + n','[{"en":"The archive provides material for students researching local history.","vi":"Kho lưu trữ cung cấp tài liệu cho sinh viên nghiên cứu lịch sử địa phương."},{"en":"These case studies provide material for classroom discussion.","vi":"Các tình huống nghiên cứu này cung cấp tài liệu cho thảo luận trên lớp."},{"en":"The publisher will provide material for the new textbook.","vi":"Nhà xuất bản sẽ cung cấp tài liệu cho cuốn giáo trình mới."}]','[]',NULL,'/prəˈvaɪd məˈtɪriəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5097,'colloc-13-01',7,'provide resources','cung cấp nguồn lực','v + n','[{"en":"The government provides resources for schools in poorer regions.","vi":"Chính phủ cung cấp nguồn lực cho các trường ở vùng nghèo hơn."},{"en":"The platform provides resources for teachers planning online lessons.","vi":"Nền tảng cung cấp nguồn lực cho giáo viên lên kế hoạch bài học trực tuyến."},{"en":"Donors provide resources that keep the clinic running.","vi":"Các nhà tài trợ cung cấp nguồn lực giúp phòng khám duy trì hoạt động."}]','[]',NULL,'/prəˈvaɪd ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5098,'colloc-13-01',8,'provide support','cung cấp sự hỗ trợ','v + n','[{"en":"The university provides support for students facing financial hardship.","vi":"Trường đại học cung cấp sự hỗ trợ cho sinh viên gặp khó khăn tài chính."},{"en":"Counselors provide support to anyone struggling with stress.","vi":"Cố vấn cung cấp sự hỗ trợ cho bất kỳ ai đang vật lộn với căng thẳng."},{"en":"Family and friends provide support during difficult times.","vi":"Gia đình và bạn bè cung cấp sự hỗ trợ trong những lúc khó khăn."}]','[]',NULL,'/prəˈvaɪd səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5099,'colloc-13-01',9,'provide a benefit','mang lại lợi ích','v + n','[{"en":"Regular exercise can provide a benefit to mental health.","vi":"Tập thể dục đều đặn có thể mang lại lợi ích cho sức khỏe tinh thần."},{"en":"The new system provides a benefit to both staff and customers.","vi":"Hệ thống mới mang lại lợi ích cho cả nhân viên lẫn khách hàng."},{"en":"Even small changes can provide a benefit over time.","vi":"Ngay cả những thay đổi nhỏ cũng có thể mang lại lợi ích theo thời gian."}]','[]',NULL,'/prəˈvaɪd ə ˈbenɪfɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5100,'colloc-13-01',10,'provide a clue','đưa ra một manh mối','v + n','[{"en":"The fingerprints provided a clue to the suspect''s identity.","vi":"Dấu vân tay đưa ra một manh mối về danh tính nghi phạm."},{"en":"Word choice can provide a clue to the author''s attitude.","vi":"Cách chọn từ có thể đưa ra một manh mối về thái độ của tác giả."},{"en":"These ancient tools provide a clue about early human life.","vi":"Những công cụ cổ này đưa ra một manh mối về đời sống con người thuở sơ khai."}]','[]',NULL,'/prəˈvaɪd ə kluː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5101,'colloc-13-01',11,'provide a focus','tạo một trọng tâm','v + n','[{"en":"A clear question provides a focus for the whole essay.","vi":"Một câu hỏi rõ ràng tạo một trọng tâm cho toàn bộ bài luận."},{"en":"The festival provides a focus for community life each summer.","vi":"Lễ hội tạo một trọng tâm cho đời sống cộng đồng mỗi mùa hè."},{"en":"Setting goals provides a focus for the team''s daily work.","vi":"Việc đặt mục tiêu tạo một trọng tâm cho công việc hằng ngày của nhóm."}]','[]',NULL,'/prəˈvaɪd ə ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5102,'colloc-13-01',12,'provide a foundation for','tạo nền tảng cho','v + n','[{"en":"Early reading skills provide a foundation for later learning.","vi":"Kỹ năng đọc sớm tạo nền tảng cho việc học sau này."},{"en":"These findings provide a foundation for further research in the area.","vi":"Những phát hiện này tạo nền tảng cho nghiên cứu sâu hơn trong lĩnh vực này."},{"en":"Trust provides a foundation for any successful working relationship.","vi":"Sự tin tưởng tạo nền tảng cho bất kỳ mối quan hệ làm việc thành công nào."}]','[]',NULL,'/prəˈvaɪd ə faʊnˈdeɪʃən fər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5103,'colloc-13-01',13,'provide a service','cung cấp một dịch vụ','v + n','[{"en":"The hospital aims to provide a service that meets local needs.","vi":"Bệnh viện hướng tới cung cấp một dịch vụ đáp ứng nhu cầu địa phương."},{"en":"Companies must provide a service that customers genuinely value.","vi":"Các công ty phải cung cấp một dịch vụ mà khách hàng thực sự coi trọng."},{"en":"Volunteers provide a service free of charge to the community.","vi":"Tình nguyện viên cung cấp một dịch vụ miễn phí cho cộng đồng."}]','[]',NULL,'/prəˈvaɪd ə ˈsɜːrvəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5104,'colloc-13-01',14,'provide a source','cung cấp một nguồn','v + n','[{"en":"Interviews provide a source of rich qualitative data for analysis.","vi":"Các cuộc phỏng vấn cung cấp một nguồn dữ liệu định tính phong phú để phân tích."},{"en":"These archives provide a source of valuable historical evidence.","vi":"Các kho lưu trữ này cung cấp một nguồn bằng chứng lịch sử quý giá."},{"en":"The river provides a source of water for nearby farms.","vi":"Con sông cung cấp một nguồn nước cho các trang trại gần đó."}]','[]',NULL,'/prəˈvaɪd ə ˈsɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5105,'colloc-13-01',15,'provide a summary','đưa ra một bản tóm tắt','v + n','[{"en":"The abstract should provide a summary of the entire study.","vi":"Phần tóm lược nên đưa ra một bản tóm tắt của toàn bộ nghiên cứu."},{"en":"Please provide a summary of your main findings on this page.","vi":"Vui lòng đưa ra một bản tóm tắt các phát hiện chính ở trang này."},{"en":"The report provides a summary before discussing the details.","vi":"Bản báo cáo đưa ra một bản tóm tắt trước khi thảo luận chi tiết."}]','[]',NULL,'/prəˈvaɪd ə ˈsʌməri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5106,'colloc-13-01',16,'provide an alternative','đưa ra một lựa chọn thay thế','v + n','[{"en":"The author provides an alternative to the standard explanation.","vi":"Tác giả đưa ra một lựa chọn thay thế cho cách giải thích tiêu chuẩn."},{"en":"Solar power provides an alternative to fossil fuels in cities.","vi":"Năng lượng mặt trời đưa ra một lựa chọn thay thế nhiên liệu hóa thạch ở thành phố."},{"en":"This method provides an alternative when resources are limited.","vi":"Phương pháp này đưa ra một lựa chọn thay thế khi nguồn lực hạn chế."}]','[]',NULL,'/prəˈvaɪd ən ɔːlˈtɜːrnətɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5107,'colloc-13-01',17,'provide an example','đưa ra một ví dụ','v + n','[{"en":"The lecturer provided an example to clarify the abstract concept.","vi":"Giảng viên đã đưa ra một ví dụ để làm rõ khái niệm trừu tượng."},{"en":"Can you provide an example that supports your argument here?","vi":"Bạn có thể đưa ra một ví dụ ủng hộ lập luận của mình không?"},{"en":"The textbook provides an example after each new definition.","vi":"Sách giáo khoa đưa ra một ví dụ sau mỗi định nghĩa mới."}]','[]',NULL,'/prəˈvaɪd ən ɪɡˈzæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5108,'colloc-13-01',18,'provide an explanation','đưa ra một lời giải thích','v + n','[{"en":"The study provides an explanation for the unexpected results.","vi":"Nghiên cứu đưa ra một lời giải thích cho những kết quả bất ngờ."},{"en":"Teachers should provide an explanation that students can follow.","vi":"Giáo viên nên đưa ra một lời giải thích mà học sinh có thể theo kịp."},{"en":"He provided an explanation for his absence from the meeting.","vi":"Anh ấy đưa ra một lời giải thích cho việc vắng mặt tại cuộc họp."}]','[]',NULL,'/prəˈvaɪd ən ˌekspləˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5109,'colloc-13-01',19,'provide an illustration','đưa ra một minh họa','v + n','[{"en":"The case study provides an illustration of the theory in practice.","vi":"Nghiên cứu tình huống đưa ra một minh họa cho lý thuyết trong thực tế."},{"en":"This diagram provides an illustration of the whole process clearly.","vi":"Sơ đồ này đưa ra một minh họa rõ ràng về toàn bộ quá trình."},{"en":"The author provides an illustration to make the point concrete.","vi":"Tác giả đưa ra một minh họa để làm cho ý tưởng trở nên cụ thể."}]','[]',NULL,'/prəˈvaɪd ən ˌɪləˈstreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5110,'colloc-13-01',20,'provide an indication of','cho thấy một dấu hiệu về','v + n','[{"en":"These figures provide an indication of the project''s overall success.","vi":"Những con số này cho thấy một dấu hiệu về thành công chung của dự án."},{"en":"Test scores provide an indication of how students are progressing.","vi":"Điểm kiểm tra cho thấy một dấu hiệu về cách học sinh đang tiến bộ."},{"en":"The survey provides an indication of public opinion on the issue.","vi":"Cuộc khảo sát cho thấy một dấu hiệu về ý kiến công chúng về vấn đề này."}]','[]',NULL,'/prəˈvaɪd ən ˌɪndɪˈkeɪʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5111,'colloc-13-01',21,'provide an opportunity','tạo ra một cơ hội','v + n','[{"en":"Internships provide an opportunity to apply classroom knowledge practically.","vi":"Thực tập tạo ra một cơ hội để áp dụng kiến thức trên lớp vào thực tế."},{"en":"The conference provides an opportunity to meet leading researchers.","vi":"Hội nghị tạo ra một cơ hội để gặp gỡ các nhà nghiên cứu hàng đầu."},{"en":"Studying abroad provides an opportunity to learn a new language.","vi":"Du học tạo ra một cơ hội để học một ngôn ngữ mới."}]','[]',NULL,'/prəˈvaɪd ən ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5112,'colloc-13-01',22,'provide an overview of','cung cấp một cái nhìn tổng quan về','v + n','[{"en":"This chapter provides an overview of the major theories involved.","vi":"Chương này cung cấp một cái nhìn tổng quan về các lý thuyết chính liên quan."},{"en":"The introduction provides an overview of the entire research field.","vi":"Phần mở đầu cung cấp một cái nhìn tổng quan về toàn bộ lĩnh vực nghiên cứu."},{"en":"Let me provide an overview of the steps before we begin.","vi":"Hãy để mình cung cấp một cái nhìn tổng quan về các bước trước khi bắt đầu."}]','[]',NULL,'/prəˈvaɪd ən ˈoʊvərvjuː əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5113,'colloc-13-01',23,'public access','quyền tiếp cận công cộng','adj + n','[{"en":"The new law guarantees public access to government records.","vi":"Luật mới đảm bảo quyền tiếp cận công cộng đối với hồ sơ chính phủ."},{"en":"The park offers public access to the riverside walking trails.","vi":"Công viên mở quyền tiếp cận công cộng tới các lối đi bộ ven sông."},{"en":"Researchers fought to ensure public access to the data set.","vi":"Các nhà nghiên cứu đấu tranh để đảm bảo quyền tiếp cận công cộng với tập dữ liệu."}]','[]',NULL,'/ˈpʌblɪk ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5114,'colloc-13-01',24,'public administration','hành chính công','adj + n','[{"en":"She studies public administration and the reform of local government.","vi":"Cô ấy nghiên cứu hành chính công và việc cải cách chính quyền địa phương."},{"en":"Efficient public administration is essential for delivering basic services.","vi":"Hành chính công hiệu quả là điều thiết yếu để cung cấp dịch vụ cơ bản."},{"en":"The course covers public administration in developing countries.","vi":"Khóa học bao quát hành chính công ở các nước đang phát triển."}]','[]',NULL,'/ˈpʌblɪk ədˌmɪnəˈstreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5115,'colloc-13-01',25,'public attitudes','thái độ của công chúng','adj + n','[{"en":"The survey tracked public attitudes toward climate change over time.","vi":"Cuộc khảo sát theo dõi thái độ của công chúng đối với biến đổi khí hậu theo thời gian."},{"en":"Public attitudes to immigration have shifted in recent decades.","vi":"Thái độ của công chúng với nhập cư đã thay đổi trong những thập kỷ gần đây."},{"en":"Media coverage can strongly influence public attitudes on policy.","vi":"Đưa tin trên truyền thông có thể tác động mạnh đến thái độ của công chúng về chính sách."}]','[]',NULL,'/ˈpʌblɪk ˈætətuːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5116,'colloc-13-01',26,'public authority','cơ quan công quyền','adj + n','[{"en":"Each public authority must publish its annual spending report.","vi":"Mỗi cơ quan công quyền phải công bố báo cáo chi tiêu hàng năm."},{"en":"The decision was challenged before the relevant public authority.","vi":"Quyết định này bị khiếu nại trước cơ quan công quyền liên quan."},{"en":"A public authority is accountable to the citizens it serves.","vi":"Một cơ quan công quyền phải chịu trách nhiệm trước những công dân mà nó phục vụ."}]','[]',NULL,'/ˈpʌblɪk əˈθɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5117,'colloc-13-01',27,'public awareness','nhận thức của công chúng','adj + n','[{"en":"The campaign aims to raise public awareness of mental health issues.","vi":"Chiến dịch nhằm nâng cao nhận thức của công chúng về vấn đề sức khỏe tâm thần."},{"en":"Greater public awareness led to changes in recycling habits.","vi":"Nhận thức của công chúng cao hơn dẫn đến thay đổi thói quen tái chế."},{"en":"Schools play a key role in building public awareness early.","vi":"Trường học đóng vai trò quan trọng trong việc xây dựng nhận thức của công chúng từ sớm."}]','[]',NULL,'/ˈpʌblɪk əˈwernəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5118,'colloc-13-01',28,'public debate','cuộc tranh luận công khai','adj + n','[{"en":"The proposal sparked a heated public debate across the nation.","vi":"Đề xuất này đã châm ngòi một cuộc tranh luận công khai sôi nổi trên cả nước."},{"en":"Open public debate is vital for a healthy democracy to thrive.","vi":"Tranh luận công khai cởi mở là thiết yếu để một nền dân chủ lành mạnh phát triển."},{"en":"Scientists joined the public debate about renewable energy policy.","vi":"Các nhà khoa học tham gia cuộc tranh luận công khai về chính sách năng lượng tái tạo."}]','[]',NULL,'/ˈpʌblɪk dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5119,'colloc-13-01',29,'public discourse','diễn ngôn công cộng','adj + n','[{"en":"Social media has transformed the nature of public discourse today.","vi":"Mạng xã hội đã làm thay đổi bản chất của diễn ngôn công cộng ngày nay."},{"en":"The book analyses how language shapes public discourse on race.","vi":"Cuốn sách phân tích cách ngôn ngữ định hình diễn ngôn công cộng về chủng tộc."},{"en":"Politicians often dominate public discourse during election seasons.","vi":"Các chính trị gia thường chi phối diễn ngôn công cộng trong mùa bầu cử."}]','[]',NULL,'/ˈpʌblɪk ˈdɪskɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5120,'colloc-13-01',30,'public display','sự phô bày công khai','adj + n','[{"en":"The artifacts are on public display in the city museum.","vi":"Các hiện vật đang được phô bày công khai tại bảo tàng thành phố."},{"en":"Norms about public display of emotion vary across cultures.","vi":"Các chuẩn mực về sự phô bày cảm xúc công khai khác nhau giữa các nền văn hóa."},{"en":"A public display of support encouraged the protesting workers.","vi":"Sự phô bày ủng hộ công khai đã khích lệ những công nhân biểu tình."}]','[]',NULL,'/ˈpʌblɪk dɪˈspleɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5121,'colloc-13-01',31,'public domain','phạm vi công cộng','adj + n','[{"en":"Once copyright expires, a work enters the public domain freely.","vi":"Khi bản quyền hết hạn, một tác phẩm tự do bước vào phạm vi công cộng."},{"en":"These images are in the public domain and free to reuse.","vi":"Những hình ảnh này thuộc phạm vi công cộng và được tái sử dụng miễn phí."},{"en":"The report placed the findings in the public domain at last.","vi":"Bản báo cáo cuối cùng đã đưa các phát hiện vào phạm vi công cộng."}]','[]',NULL,'/ˈpʌblɪk doʊˈmeɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5122,'colloc-13-01',32,'public expenditure','chi tiêu công','adj + n','[{"en":"The government pledged to reduce public expenditure next year.","vi":"Chính phủ cam kết giảm chi tiêu công vào năm tới."},{"en":"Health and education account for most public expenditure here.","vi":"Y tế và giáo dục chiếm phần lớn chi tiêu công ở đây."},{"en":"Rising public expenditure put pressure on the national budget.","vi":"Chi tiêu công gia tăng tạo áp lực lên ngân sách quốc gia."}]','[]',NULL,'/ˈpʌblɪk ɪkˈspendətʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5123,'colloc-13-01',33,'public funds','ngân quỹ công','adj + n','[{"en":"The project was financed entirely from public funds last year.","vi":"Dự án được tài trợ hoàn toàn từ ngân quỹ công vào năm ngoái."},{"en":"Auditors check how public funds are spent on local services.","vi":"Kiểm toán viên kiểm tra cách ngân quỹ công được chi cho dịch vụ địa phương."},{"en":"Misuse of public funds led to a lengthy formal investigation.","vi":"Việc lạm dụng ngân quỹ công dẫn đến một cuộc điều tra chính thức kéo dài."}]','[]',NULL,'/ˈpʌblɪk fʌndz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5124,'colloc-13-01',34,'public image','hình ảnh trước công chúng','adj + n','[{"en":"The company worked hard to improve its public image after the scandal.","vi":"Công ty nỗ lực cải thiện hình ảnh trước công chúng sau vụ bê bối."},{"en":"A positive public image can attract both talent and investors.","vi":"Một hình ảnh tích cực trước công chúng có thể thu hút cả nhân tài lẫn nhà đầu tư."},{"en":"Politicians carefully manage their public image during campaigns.","vi":"Các chính trị gia cẩn thận quản lý hình ảnh trước công chúng trong các chiến dịch."}]','[]',NULL,'/ˈpʌblɪk ˈɪmɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5125,'colloc-13-01',35,'public institution','thiết chế công','adj + n','[{"en":"A university is a public institution that serves the wider society.","vi":"Trường đại học là một thiết chế công phục vụ cho xã hội rộng lớn hơn."},{"en":"Trust in public institutions has declined in many countries.","vi":"Niềm tin vào các thiết chế công đã suy giảm ở nhiều quốc gia."},{"en":"Every public institution must follow strict transparency rules.","vi":"Mọi thiết chế công đều phải tuân theo các quy tắc minh bạch nghiêm ngặt."}]','[]',NULL,'/ˈpʌblɪk ˌɪnstəˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5126,'colloc-13-01',36,'public perception','cảm nhận của công chúng','adj + n','[{"en":"Media coverage shaped public perception of the new vaccine quickly.","vi":"Đưa tin truyền thông nhanh chóng định hình cảm nhận của công chúng về vắc-xin mới."},{"en":"Public perception of risk often differs from expert assessments.","vi":"Cảm nhận của công chúng về rủi ro thường khác với đánh giá của chuyên gia."},{"en":"The study measured changes in public perception over six months.","vi":"Nghiên cứu đo lường những thay đổi trong cảm nhận của công chúng qua sáu tháng."}]','[]',NULL,'/ˈpʌblɪk pərˈsepʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5127,'colloc-13-01',37,'public policy','chính sách công','adj + n','[{"en":"Researchers hope their findings will inform future public policy.","vi":"Các nhà nghiên cứu hy vọng phát hiện của họ sẽ định hướng chính sách công tương lai."},{"en":"Public policy on housing varies widely between the two cities.","vi":"Chính sách công về nhà ở khác nhau rất nhiều giữa hai thành phố."},{"en":"She advises lawmakers on public policy related to education.","vi":"Cô ấy tư vấn cho các nhà lập pháp về chính sách công liên quan đến giáo dục."}]','[]',NULL,'/ˈpʌblɪk ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5128,'colloc-13-01',38,'public sector','khu vực công','adj + n','[{"en":"Many graduates seek stable employment in the public sector.","vi":"Nhiều sinh viên tốt nghiệp tìm kiếm việc làm ổn định trong khu vực công."},{"en":"Wages in the public sector rose slightly compared to last year.","vi":"Mức lương trong khu vực công tăng nhẹ so với năm ngoái."},{"en":"The reform reshaped how the public sector delivers its services.","vi":"Cuộc cải cách định hình lại cách khu vực công cung cấp dịch vụ."}]','[]',NULL,'/ˈpʌblɪk ˈsektər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5129,'colloc-13-01',39,'public sphere','không gian công cộng','adj + n','[{"en":"Newspapers once dominated debate within the public sphere entirely.","vi":"Báo chí từng chi phối hoàn toàn tranh luận trong không gian công cộng."},{"en":"Women gradually gained a stronger voice in the public sphere.","vi":"Phụ nữ dần có tiếng nói mạnh mẽ hơn trong không gian công cộng."},{"en":"The internet has expanded the public sphere beyond national borders.","vi":"Internet đã mở rộng không gian công cộng vượt ra ngoài biên giới quốc gia."}]','[]',NULL,'/ˈpʌblɪk sfɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5130,'colloc-13-01',40,'public transport','giao thông công cộng','adj + n','[{"en":"Improving public transport could reduce traffic in the city center.","vi":"Cải thiện giao thông công cộng có thể giảm ùn tắc ở trung tâm thành phố."},{"en":"Many residents rely on public transport to reach their workplaces.","vi":"Nhiều cư dân phụ thuộc vào giao thông công cộng để đến nơi làm việc."},{"en":"Cheaper public transport encourages people to leave cars at home.","vi":"Giao thông công cộng rẻ hơn khuyến khích mọi người để xe ở nhà."}]','[]',NULL,'/ˈpʌblɪk ˈtrænspɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5131,'colloc-13-01',41,'public welfare','phúc lợi công cộng','adj + n','[{"en":"The policy was designed to protect public welfare during the crisis.","vi":"Chính sách được thiết kế để bảo vệ phúc lợi công cộng trong khủng hoảng."},{"en":"Governments must balance economic growth with public welfare needs.","vi":"Chính phủ phải cân bằng tăng trưởng kinh tế với nhu cầu phúc lợi công cộng."},{"en":"Critics argued the plan ignored long-term public welfare entirely.","vi":"Những người phê bình cho rằng kế hoạch hoàn toàn bỏ qua phúc lợi công cộng lâu dài."}]','[]',NULL,'/ˈpʌblɪk ˈwelfer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5132,'colloc-13-01',42,'publicly available','công khai cho mọi người','adv + adj','[{"en":"The full data set is now publicly available on the website.","vi":"Toàn bộ tập dữ liệu hiện đã được công khai cho mọi người trên trang web."},{"en":"Researchers prefer sources that are publicly available and verifiable.","vi":"Các nhà nghiên cứu thích những nguồn công khai cho mọi người và có thể kiểm chứng."},{"en":"These reports became publicly available after the new law passed.","vi":"Các báo cáo này trở nên công khai cho mọi người sau khi luật mới được thông qua."}]','[]',NULL,'/ˈpʌblɪkli əˈveɪləbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5133,'colloc-13-01',43,'publish research','công bố nghiên cứu','v + n','[{"en":"Scholars must publish research regularly to advance their careers.","vi":"Các học giả phải công bố nghiên cứu thường xuyên để thăng tiến sự nghiệp."},{"en":"The team plans to publish research on the new treatment soon.","vi":"Nhóm dự định sớm công bố nghiên cứu về phương pháp điều trị mới."},{"en":"Universities encourage staff to publish research in leading journals.","vi":"Các trường đại học khuyến khích nhân viên công bố nghiên cứu trên tạp chí hàng đầu."}]','[]',NULL,'/ˈpʌblɪʃ ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5134,'colloc-13-01',44,'publish a journal','xuất bản một tạp chí','v + n','[{"en":"The society plans to publish a journal on environmental science.","vi":"Hội dự định xuất bản một tạp chí về khoa học môi trường."},{"en":"They publish a journal four times a year for members.","vi":"Họ xuất bản một tạp chí bốn lần mỗi năm cho các thành viên."},{"en":"The department decided to publish a journal entirely online.","vi":"Khoa quyết định xuất bản một tạp chí hoàn toàn trực tuyến."}]','[]',NULL,'/ˈpʌblɪʃ ə ˈdʒɜːrnəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5135,'colloc-13-01',45,'publish a report','công bố một báo cáo','v + n','[{"en":"The agency will publish a report on air quality next month.","vi":"Cơ quan này sẽ công bố một báo cáo về chất lượng không khí vào tháng tới."},{"en":"Researchers publish a report summarizing their findings each year.","vi":"Các nhà nghiên cứu công bố một báo cáo tóm tắt phát hiện của họ mỗi năm."},{"en":"The committee voted to publish a report before the deadline.","vi":"Ủy ban đã bỏ phiếu công bố một báo cáo trước thời hạn."}]','[]',NULL,'/ˈpʌblɪʃ ə rɪˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5136,'colloc-13-01',46,'publish an article','đăng một bài báo','v + n','[{"en":"She hopes to publish an article in a respected academic journal.","vi":"Cô ấy hy vọng đăng một bài báo trên một tạp chí học thuật uy tín."},{"en":"The newspaper agreed to publish an article on local pollution.","vi":"Tờ báo đồng ý đăng một bài báo về ô nhiễm địa phương."},{"en":"It can take months to publish an article after peer review.","vi":"Có thể mất nhiều tháng để đăng một bài báo sau khi bình duyệt."}]','[]',NULL,'/ˈpʌblɪʃ ən ˈɑːrtɪkəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5137,'colloc-13-01',47,'published literature','tài liệu đã xuất bản','adj + n','[{"en":"The review surveyed all published literature on childhood obesity.","vi":"Bài tổng quan khảo sát toàn bộ tài liệu đã xuất bản về béo phì ở trẻ em."},{"en":"Existing published literature offers little guidance on this topic.","vi":"Tài liệu đã xuất bản hiện có cung cấp rất ít hướng dẫn về chủ đề này."},{"en":"She compared her results with the wider published literature carefully.","vi":"Cô ấy cẩn thận so sánh kết quả với tài liệu đã xuất bản rộng hơn."}]','[]',NULL,'/ˈpʌblɪʃt ˈlɪtərətʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5138,'colloc-13-01',48,'published material','tài liệu đã được công bố','adj + n','[{"en":"The course relies heavily on recently published material for reading.","vi":"Khóa học dựa nhiều vào tài liệu đã được công bố gần đây để đọc."},{"en":"Students must cite all published material used in their essays.","vi":"Sinh viên phải trích dẫn mọi tài liệu đã được công bố dùng trong bài luận."},{"en":"The database collects published material from hundreds of sources.","vi":"Cơ sở dữ liệu thu thập tài liệu đã được công bố từ hàng trăm nguồn."}]','[]',NULL,'/ˈpʌblɪʃt məˈtɪriəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5139,'colloc-13-01',49,'published research','nghiên cứu đã công bố','adj + n','[{"en":"Her argument draws on a large body of published research.","vi":"Lập luận của cô dựa trên một khối lượng lớn nghiên cứu đã công bố."},{"en":"Published research on the topic remains surprisingly limited so far.","vi":"Nghiên cứu đã công bố về chủ đề này vẫn còn hạn chế đáng ngạc nhiên."},{"en":"We evaluated published research before designing our own experiment.","vi":"Chúng tôi đánh giá nghiên cứu đã công bố trước khi thiết kế thí nghiệm riêng."}]','[]',NULL,'/ˈpʌblɪʃt ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5140,'colloc-13-01',50,'published work','công trình đã xuất bản','adj + n','[{"en":"His published work has influenced researchers across several disciplines.","vi":"Công trình đã xuất bản của ông đã ảnh hưởng đến nhiều ngành nghiên cứu."},{"en":"The committee assessed each candidate''s published work very closely.","vi":"Ủy ban đánh giá rất kỹ công trình đã xuất bản của từng ứng viên."},{"en":"Most of her published work focuses on language acquisition.","vi":"Phần lớn công trình đã xuất bản của cô tập trung vào việc tiếp thu ngôn ngữ."}]','[]',NULL,'/ˈpʌblɪʃt wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5141,'colloc-13-01',51,'purchasing power','sức mua','adj + n','[{"en":"Rising inflation steadily eroded the purchasing power of households.","vi":"Lạm phát gia tăng làm xói mòn dần sức mua của các hộ gia đình."},{"en":"Higher wages increased the purchasing power of ordinary workers.","vi":"Mức lương cao hơn làm tăng sức mua của những người lao động bình thường."},{"en":"Economists compare purchasing power across countries using special indices.","vi":"Các nhà kinh tế so sánh sức mua giữa các nước bằng những chỉ số đặc biệt."}]','[]',NULL,'/ˈpɜːrtʃəsɪŋ ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5142,'colloc-13-01',52,'qualitative analysis','phân tích định tính','adj + n','[{"en":"The thesis combines qualitative analysis with detailed statistical modeling.","vi":"Luận văn kết hợp phân tích định tính với mô hình thống kê chi tiết."},{"en":"Qualitative analysis of the interviews revealed several recurring themes.","vi":"Phân tích định tính các cuộc phỏng vấn cho thấy vài chủ đề lặp lại."},{"en":"She used qualitative analysis to interpret the open-ended responses.","vi":"Cô ấy dùng phân tích định tính để diễn giải các câu trả lời mở."}]','[]',NULL,'/ˈkwɑːlɪteɪtɪv əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5143,'colloc-13-01',53,'qualitative approach','phương pháp tiếp cận định tính','adj + n','[{"en":"A qualitative approach suits research exploring lived human experience.","vi":"Phương pháp tiếp cận định tính phù hợp với nghiên cứu khám phá trải nghiệm con người."},{"en":"The author adopted a qualitative approach to study classroom behavior.","vi":"Tác giả áp dụng phương pháp tiếp cận định tính để nghiên cứu hành vi trong lớp."},{"en":"A qualitative approach can uncover meanings that numbers often miss.","vi":"Phương pháp tiếp cận định tính có thể khám phá ý nghĩa mà con số thường bỏ sót."}]','[]',NULL,'/ˈkwɑːlɪteɪtɪv əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5144,'colloc-13-01',54,'qualitative data','dữ liệu định tính','adj + n','[{"en":"The interviews generated rich qualitative data for the final report.","vi":"Các cuộc phỏng vấn tạo ra dữ liệu định tính phong phú cho báo cáo cuối."},{"en":"Coding qualitative data carefully takes considerable time and patience.","vi":"Mã hóa dữ liệu định tính cẩn thận đòi hỏi nhiều thời gian và kiên nhẫn."},{"en":"Qualitative data helped explain why the numbers looked so unusual.","vi":"Dữ liệu định tính giúp giải thích vì sao các con số trông bất thường."}]','[]',NULL,'/ˈkwɑːlɪteɪtɪv ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5145,'colloc-13-01',55,'qualitative method','phương pháp định tính','adj + n','[{"en":"She chose a qualitative method to explore students'' personal attitudes.","vi":"Cô ấy chọn một phương pháp định tính để khám phá thái độ cá nhân của học sinh."},{"en":"A qualitative method captures depth that surveys alone cannot reach.","vi":"Một phương pháp định tính nắm bắt chiều sâu mà chỉ khảo sát không thể đạt được."},{"en":"The study mixes a qualitative method with quantitative measurement tools.","vi":"Nghiên cứu kết hợp một phương pháp định tính với các công cụ đo lường định lượng."}]','[]',NULL,'/ˈkwɑːlɪteɪtɪv ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5146,'colloc-13-01',56,'qualitative research','nghiên cứu định tính','adj + n','[{"en":"Qualitative research often relies on interviews, observation, and case studies.","vi":"Nghiên cứu định tính thường dựa vào phỏng vấn, quan sát và nghiên cứu tình huống."},{"en":"Her qualitative research explored how patients cope with chronic illness.","vi":"Nghiên cứu định tính của cô khám phá cách bệnh nhân đối phó với bệnh mãn tính."},{"en":"Good qualitative research demands careful attention to participants'' words.","vi":"Nghiên cứu định tính tốt đòi hỏi chú ý kỹ đến lời nói của người tham gia."}]','[]',NULL,'/ˈkwɑːlɪteɪtɪv ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5147,'colloc-13-01',57,'qualitative study','nghiên cứu định tính','adj + n','[{"en":"The qualitative study followed ten families over an entire year.","vi":"Nghiên cứu định tính theo dõi mười gia đình trong suốt một năm."},{"en":"A qualitative study can reveal unexpected patterns in everyday behavior.","vi":"Một nghiên cứu định tính có thể tiết lộ những khuôn mẫu bất ngờ trong hành vi hàng ngày."},{"en":"They published a qualitative study based on detailed teacher interviews.","vi":"Họ công bố một nghiên cứu định tính dựa trên phỏng vấn giáo viên chi tiết."}]','[]',NULL,'/ˈkwɑːlɪteɪtɪv ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5148,'colloc-13-01',58,'qualitatively different','khác biệt về chất','adv + adj','[{"en":"The two approaches are qualitatively different, not merely a matter of degree.","vi":"Hai cách tiếp cận khác biệt về chất, không chỉ là vấn đề mức độ."},{"en":"Children''s reasoning becomes qualitatively different as they mature.","vi":"Lập luận của trẻ trở nên khác biệt về chất khi chúng trưởng thành."},{"en":"Online learning is qualitatively different from traditional classroom teaching.","vi":"Học trực tuyến khác biệt về chất so với giảng dạy truyền thống trên lớp."}]','[]',NULL,'/ˈkwɑːlɪteɪtɪvli ˈdɪfərənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5149,'colloc-13-01',59,'quantitative analysis','phân tích định lượng','adj + n','[{"en":"Quantitative analysis confirmed a strong link between the two variables.","vi":"Phân tích định lượng xác nhận mối liên hệ chặt chẽ giữa hai biến."},{"en":"The report includes quantitative analysis of national survey results.","vi":"Bản báo cáo bao gồm phân tích định lượng kết quả khảo sát quốc gia."},{"en":"She performed quantitative analysis using specialized statistical software.","vi":"Cô ấy thực hiện phân tích định lượng bằng phần mềm thống kê chuyên dụng."}]','[]',NULL,'/ˈkwɑːntɪteɪtɪv əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5150,'colloc-13-01',60,'quantitative approach','phương pháp tiếp cận định lượng','adj + n','[{"en":"A quantitative approach allows researchers to test hypotheses with numbers.","vi":"Phương pháp tiếp cận định lượng cho phép nhà nghiên cứu kiểm định giả thuyết bằng số liệu."},{"en":"The team favored a quantitative approach to measure clear outcomes.","vi":"Nhóm ưa chuộng phương pháp tiếp cận định lượng để đo lường kết quả rõ ràng."},{"en":"A quantitative approach works best when large samples are available.","vi":"Phương pháp tiếp cận định lượng hiệu quả nhất khi có sẵn mẫu lớn."}]','[]',NULL,'/ˈkwɑːntɪteɪtɪv əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5151,'colloc-13-01',61,'quantitative data','dữ liệu định lượng','adj + n','[{"en":"The researchers collected quantitative data from thousands of survey responses.","vi":"Các nhà nghiên cứu thu thập dữ liệu định lượng từ hàng nghìn phản hồi khảo sát."},{"en":"Quantitative data can be summarized using means and standard deviations.","vi":"Dữ liệu định lượng có thể được tóm tắt bằng giá trị trung bình và độ lệch chuẩn."},{"en":"They analyzed quantitative data to detect trends across several years.","vi":"Họ phân tích dữ liệu định lượng để phát hiện xu hướng qua nhiều năm."}]','[]',NULL,'/ˈkwɑːntɪteɪtɪv ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5152,'colloc-13-01',62,'quantitative method','phương pháp định lượng','adj + n','[{"en":"A quantitative method lets researchers measure relationships between variables precisely.","vi":"Một phương pháp định lượng cho phép nhà nghiên cứu đo chính xác mối quan hệ giữa các biến."},{"en":"The course teaches a quantitative method for analyzing economic data.","vi":"Khóa học dạy một phương pháp định lượng để phân tích dữ liệu kinh tế."},{"en":"Many social scientists combine a quantitative method with interviews.","vi":"Nhiều nhà khoa học xã hội kết hợp một phương pháp định lượng với phỏng vấn."}]','[]',NULL,'/ˈkwɑːntɪteɪtɪv ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5153,'colloc-13-01',63,'quantitative research','nghiên cứu định lượng','adj + n','[{"en":"Quantitative research relies on numerical data and statistical testing methods.","vi":"Nghiên cứu định lượng dựa vào dữ liệu số và các phương pháp kiểm định thống kê."},{"en":"His quantitative research measured the effect of class size on grades.","vi":"Nghiên cứu định lượng của ông đo lường tác động của sĩ số lớp đến điểm số."},{"en":"Quantitative research can reveal patterns across very large populations.","vi":"Nghiên cứu định lượng có thể tiết lộ các khuôn mẫu trên những quần thể rất lớn."}]','[]',NULL,'/ˈkwɑːntɪteɪtɪv ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5154,'colloc-13-01',64,'quantitative result','kết quả định lượng','adj + n','[{"en":"The quantitative result showed a significant rise in test scores.","vi":"Kết quả định lượng cho thấy sự gia tăng đáng kể về điểm kiểm tra."},{"en":"Each quantitative result was checked against the original raw data.","vi":"Mỗi kết quả định lượng được đối chiếu với dữ liệu thô ban đầu."},{"en":"They interpreted the quantitative result alongside qualitative feedback carefully.","vi":"Họ diễn giải kết quả định lượng cùng với phản hồi định tính một cách cẩn thận."}]','[]',NULL,'/ˈkwɑːntɪteɪtɪv rɪˈzʌlt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5155,'colloc-13-01',65,'quantitative study','nghiên cứu định lượng','adj + n','[{"en":"The quantitative study surveyed five hundred students across three universities.","vi":"Nghiên cứu định lượng khảo sát năm trăm sinh viên ở ba trường đại học."},{"en":"A large quantitative study can produce more generalizable conclusions overall.","vi":"Một nghiên cứu định lượng lớn có thể tạo ra kết luận khái quát hơn."},{"en":"They designed a quantitative study to test the proposed hypothesis.","vi":"Họ thiết kế một nghiên cứu định lượng để kiểm định giả thuyết được đề xuất."}]','[]',NULL,'/ˈkwɑːntɪteɪtɪv ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5156,'colloc-13-01',66,'racial differences','sự khác biệt chủng tộc','adj + n','[{"en":"The study examined racial differences in access to quality healthcare.","vi":"Nghiên cứu xem xét sự khác biệt chủng tộc trong việc tiếp cận chăm sóc y tế chất lượng."},{"en":"Researchers found persistent racial differences in average household income.","vi":"Các nhà nghiên cứu phát hiện sự khác biệt chủng tộc dai dẳng về thu nhập hộ gia đình."},{"en":"Racial differences in test scores often reflect unequal opportunities.","vi":"Sự khác biệt chủng tộc về điểm kiểm tra thường phản ánh cơ hội bất bình đẳng."}]','[]',NULL,'/ˈreɪʃəl ˈdɪfərənsəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5157,'colloc-13-01',67,'racial discrimination','phân biệt chủng tộc','adj + n','[{"en":"The new law explicitly prohibits racial discrimination in the workplace.","vi":"Luật mới cấm rõ ràng phân biệt chủng tộc tại nơi làm việc."},{"en":"Many activists devoted their lives to fighting racial discrimination.","vi":"Nhiều nhà hoạt động cống hiến cả đời để chống lại phân biệt chủng tộc."},{"en":"The report documented widespread racial discrimination in housing markets.","vi":"Bản báo cáo ghi nhận phân biệt chủng tộc lan rộng trong thị trường nhà ở."}]','[]',NULL,'/ˈreɪʃəl dɪˌskrɪmɪˈneɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5158,'colloc-13-01',68,'racial equality','bình đẳng chủng tộc','adj + n','[{"en":"The movement campaigned tirelessly for racial equality and civil rights.","vi":"Phong trào vận động không mệt mỏi cho bình đẳng chủng tộc và quyền công dân."},{"en":"True racial equality requires changes in both law and attitudes.","vi":"Bình đẳng chủng tộc thực sự đòi hỏi thay đổi cả luật pháp lẫn thái độ."},{"en":"Schools play an important part in promoting racial equality early.","vi":"Trường học đóng vai trò quan trọng trong việc thúc đẩy bình đẳng chủng tộc từ sớm."}]','[]',NULL,'/ˈreɪʃəl ɪˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5159,'colloc-13-01',69,'racial group','nhóm chủng tộc','adj + n','[{"en":"The survey compared health outcomes between several major racial groups.","vi":"Cuộc khảo sát so sánh kết quả sức khỏe giữa vài nhóm chủng tộc lớn."},{"en":"Each racial group faced distinct barriers in the labor market.","vi":"Mỗi nhóm chủng tộc đối mặt với những rào cản riêng trên thị trường lao động."},{"en":"Census data tracks the size of every racial group nationally.","vi":"Dữ liệu điều tra dân số theo dõi quy mô của từng nhóm chủng tộc trên toàn quốc."}]','[]',NULL,'/ˈreɪʃəl ɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5160,'colloc-13-01',70,'racial stereotype','định kiến chủng tộc','adj + n','[{"en":"The film challenges a common racial stereotype found in older media.","vi":"Bộ phim thách thức một định kiến chủng tộc phổ biến trong truyền thông cũ."},{"en":"Repeated exposure to a racial stereotype can shape young minds.","vi":"Tiếp xúc lặp lại với một định kiến chủng tộc có thể định hình tâm trí trẻ."},{"en":"Educators work hard to dismantle every harmful racial stereotype.","vi":"Các nhà giáo dục nỗ lực để xóa bỏ mọi định kiến chủng tộc gây hại."}]','[]',NULL,'/ˈreɪʃəl ˈsteriətaɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5161,'colloc-13-01',71,'radical change','sự thay đổi triệt để','adj + n','[{"en":"The reform brought radical change to the entire education system.","vi":"Cuộc cải cách mang lại sự thay đổi triệt để cho toàn bộ hệ thống giáo dục."},{"en":"Technology has driven radical change in how people communicate daily.","vi":"Công nghệ đã thúc đẩy sự thay đổi triệt để trong cách con người giao tiếp hàng ngày."},{"en":"Such radical change often meets strong resistance from established groups.","vi":"Sự thay đổi triệt để như vậy thường gặp phải sự phản kháng mạnh từ các nhóm cố hữu."}]','[]',NULL,'/ˈrædɪkəl tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5162,'colloc-13-01',72,'radical critique','sự phê phán triệt để','adj + n','[{"en":"The book offers a radical critique of mainstream economic theory.","vi":"Cuốn sách đưa ra một sự phê phán triệt để đối với lý thuyết kinh tế chủ đạo."},{"en":"Her essay presents a radical critique of modern consumer culture.","vi":"Bài luận của cô trình bày một sự phê phán triệt để văn hóa tiêu dùng hiện đại."},{"en":"A radical critique questions assumptions that others simply take for granted.","vi":"Một sự phê phán triệt để chất vấn những giả định mà người khác mặc nhiên chấp nhận."}]','[]',NULL,'/ˈrædɪkəl krɪˈtiːk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5163,'colloc-13-01',73,'radical differences','những khác biệt căn bản','adj + n','[{"en":"The two cultures show radical differences in their family structures.","vi":"Hai nền văn hóa cho thấy những khác biệt căn bản trong cấu trúc gia đình."},{"en":"There are radical differences between the two theories of learning.","vi":"Có những khác biệt căn bản giữa hai lý thuyết về việc học."},{"en":"Researchers noted radical differences in how the species adapt.","vi":"Các nhà nghiên cứu ghi nhận những khác biệt căn bản trong cách các loài thích nghi."}]','[]',NULL,'/ˈrædɪkəl ˈdɪfərənsəz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5164,'colloc-13-01',74,'radical transformation','sự chuyển đổi triệt để','adj + n','[{"en":"The internet caused a radical transformation of global communication.","vi":"Internet đã gây ra sự chuyển đổi triệt để trong giao tiếp toàn cầu."},{"en":"The factory underwent radical transformation after adopting new technology.","vi":"Nhà máy trải qua sự chuyển đổi triệt để sau khi áp dụng công nghệ mới."},{"en":"Climate goals demand a radical transformation of the energy sector.","vi":"Các mục tiêu khí hậu đòi hỏi sự chuyển đổi triệt để của ngành năng lượng."}]','[]',NULL,'/ˈrædɪkəl ˌtrænsfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5165,'colloc-13-01',75,'radically different','khác biệt hoàn toàn','adv + adj','[{"en":"The two authors reach radically different conclusions from similar data.","vi":"Hai tác giả đi đến những kết luận khác biệt hoàn toàn từ dữ liệu tương tự."},{"en":"Life in the city is radically different from rural village life.","vi":"Cuộc sống ở thành phố khác biệt hoàn toàn so với đời sống làng quê."},{"en":"Their new strategy is radically different from anything tried before.","vi":"Chiến lược mới của họ khác biệt hoàn toàn so với mọi thứ từng thử trước đây."}]','[]',NULL,'/ˈrædɪkli ˈdɪfərənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5166,'colloc-13-01',76,'raise awareness','nâng cao nhận thức','v + n','[{"en":"The charity works to raise awareness of homelessness in the city.","vi":"Tổ chức từ thiện hoạt động để nâng cao nhận thức về tình trạng vô gia cư trong thành phố."},{"en":"Posters and talks helped raise awareness of online safety risks.","vi":"Áp phích và buổi nói chuyện đã giúp nâng cao nhận thức về rủi ro an toàn trực tuyến."},{"en":"Schools raise awareness of healthy eating through practical cooking classes.","vi":"Trường học nâng cao nhận thức về ăn uống lành mạnh qua các lớp nấu ăn thực hành."}]','[]',NULL,'/reɪz əˈwernəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5167,'colloc-13-01',77,'raise a question','đặt ra một câu hỏi','v + n','[{"en":"These findings raise a question about the validity of earlier studies.","vi":"Những phát hiện này đặt ra một câu hỏi về tính hợp lệ của các nghiên cứu trước."},{"en":"The student raised a question that the lecturer had not expected.","vi":"Sinh viên đặt ra một câu hỏi mà giảng viên không lường trước."},{"en":"The new policy raises a question about who actually benefits.","vi":"Chính sách mới đặt ra một câu hỏi về việc ai thực sự được hưởng lợi."}]','[]',NULL,'/reɪz ə ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5168,'colloc-13-01',78,'raise an issue','nêu lên một vấn đề','v + n','[{"en":"She raised an issue about funding during the committee meeting.","vi":"Cô ấy nêu lên một vấn đề về kinh phí trong cuộc họp ủy ban."},{"en":"The report raises an issue that policymakers can no longer ignore.","vi":"Bản báo cáo nêu lên một vấn đề mà các nhà hoạch định không thể bỏ qua nữa."},{"en":"Feel free to raise an issue if anything seems unclear to you.","vi":"Hãy thoải mái nêu lên một vấn đề nếu điều gì đó còn chưa rõ với bạn."}]','[]',NULL,'/reɪz ən ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5169,'colloc-13-01',79,'random error','sai số ngẫu nhiên','adj + n','[{"en":"Repeated measurements help reduce the effect of random error.","vi":"Đo lường lặp lại giúp giảm tác động của sai số ngẫu nhiên."},{"en":"Random error scatters results without favoring any particular direction.","vi":"Sai số ngẫu nhiên làm kết quả phân tán mà không thiên về hướng cụ thể nào."},{"en":"The analysis distinguished random error from a clear systematic bias.","vi":"Phân tích phân biệt sai số ngẫu nhiên với một thiên lệch hệ thống rõ ràng."}]','[]',NULL,'/ˈrændəm ˈerər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5170,'colloc-13-01',80,'random sample','mẫu ngẫu nhiên','adj + n','[{"en":"The researchers drew a random sample from the national population.","vi":"Các nhà nghiên cứu lấy một mẫu ngẫu nhiên từ dân số quốc gia."},{"en":"A truly random sample reduces bias and improves generalizability.","vi":"Một mẫu ngẫu nhiên thực sự làm giảm thiên lệch và tăng khả năng khái quát."},{"en":"They surveyed a random sample of two thousand registered voters.","vi":"Họ khảo sát một mẫu ngẫu nhiên gồm hai nghìn cử tri đã đăng ký."}]','[]',NULL,'/ˈrændəm ˈsæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5171,'colloc-13-01',81,'random variable','biến ngẫu nhiên','adj + n','[{"en":"In statistics, a random variable assigns numbers to possible outcomes.","vi":"Trong thống kê, một biến ngẫu nhiên gán số cho các kết quả có thể."},{"en":"The model treats waiting time as a continuous random variable.","vi":"Mô hình coi thời gian chờ là một biến ngẫu nhiên liên tục."},{"en":"Each random variable in the equation follows a known distribution.","vi":"Mỗi biến ngẫu nhiên trong phương trình tuân theo một phân phối đã biết."}]','[]',NULL,'/ˈrændəm ˈveriəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5172,'colloc-13-01',82,'randomly assigned to','được phân ngẫu nhiên vào','adv + vpp','[{"en":"Participants were randomly assigned to either the control or treatment group.","vi":"Người tham gia được phân ngẫu nhiên vào nhóm đối chứng hoặc nhóm điều trị."},{"en":"Students were randomly assigned to classes of different sizes.","vi":"Học sinh được phân ngẫu nhiên vào các lớp có quy mô khác nhau."},{"en":"Each patient was randomly assigned to one of three conditions.","vi":"Mỗi bệnh nhân được phân ngẫu nhiên vào một trong ba điều kiện."}]','[]',NULL,'/ˈrændəmli əˈsaɪnd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5173,'colloc-13-01',83,'randomly chosen','được chọn ngẫu nhiên','adv + vpp','[{"en":"The names were randomly chosen from a list of all members.","vi":"Các tên được chọn ngẫu nhiên từ danh sách toàn bộ thành viên."},{"en":"A randomly chosen subset was tested to verify the procedure.","vi":"Một tập con được chọn ngẫu nhiên đã được kiểm tra để xác minh quy trình."},{"en":"Participants were randomly chosen to avoid any selection bias.","vi":"Người tham gia được chọn ngẫu nhiên để tránh bất kỳ thiên lệch lựa chọn nào."}]','[]',NULL,'/ˈrændəmli ˈtʃoʊzən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5174,'colloc-13-01',84,'randomly selected','được tuyển chọn ngẫu nhiên','adv + vpp','[{"en":"Households were randomly selected to take part in the survey.","vi":"Các hộ gia đình được tuyển chọn ngẫu nhiên để tham gia khảo sát."},{"en":"The sample was randomly selected from official school registers.","vi":"Mẫu được tuyển chọn ngẫu nhiên từ sổ đăng ký chính thức của trường."},{"en":"Reviewers were randomly selected to ensure a fair evaluation process.","vi":"Người đánh giá được tuyển chọn ngẫu nhiên để đảm bảo quá trình đánh giá công bằng."}]','[]',NULL,'/ˈrændəmli sɪˈlektɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5175,'colloc-13-01',85,'rapid expansion','sự mở rộng nhanh chóng','adj + n','[{"en":"The company''s rapid expansion created hundreds of new jobs overnight.","vi":"Sự mở rộng nhanh chóng của công ty tạo ra hàng trăm việc làm mới trong một đêm."},{"en":"Rapid expansion of cities has strained local water supplies.","vi":"Sự mở rộng nhanh chóng của các thành phố đã gây áp lực lên nguồn nước địa phương."},{"en":"The rapid expansion of online shopping reshaped traditional retail.","vi":"Sự mở rộng nhanh chóng của mua sắm trực tuyến đã định hình lại bán lẻ truyền thống."}]','[]',NULL,'/ˈræpɪd ɪkˈspænʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5176,'colloc-13-01',86,'rapidly changing','đang thay đổi nhanh chóng','adv + adj','[{"en":"Workers must adapt to a rapidly changing technological environment.","vi":"Người lao động phải thích nghi với môi trường công nghệ đang thay đổi nhanh chóng."},{"en":"The course prepares students for a rapidly changing job market.","vi":"Khóa học chuẩn bị cho sinh viên một thị trường việc làm đang thay đổi nhanh chóng."},{"en":"Climate scientists study the rapidly changing conditions in the Arctic.","vi":"Các nhà khoa học khí hậu nghiên cứu điều kiện đang thay đổi nhanh chóng ở Bắc Cực."}]','[]',NULL,'/ˈræpɪdli ˈtʃeɪndʒɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5177,'colloc-13-01',87,'rapidly growing','đang phát triển nhanh chóng','adv + adj','[{"en":"Renewable energy is a rapidly growing part of the economy.","vi":"Năng lượng tái tạo là một phần đang phát triển nhanh chóng của nền kinh tế."},{"en":"The city has a rapidly growing population of young professionals.","vi":"Thành phố có dân số chuyên gia trẻ đang phát triển nhanh chóng."},{"en":"Researchers track the rapidly growing demand for clean drinking water.","vi":"Các nhà nghiên cứu theo dõi nhu cầu đang phát triển nhanh chóng về nước uống sạch."}]','[]',NULL,'/ˈræpɪdli ˈɡroʊɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5178,'colloc-13-01',88,'raw data','dữ liệu thô','adj + n','[{"en":"The researchers stored all raw data before beginning any analysis.","vi":"Các nhà nghiên cứu lưu trữ toàn bộ dữ liệu thô trước khi bắt đầu phân tích."},{"en":"Raw data must be cleaned carefully to remove obvious errors.","vi":"Dữ liệu thô phải được làm sạch cẩn thận để loại bỏ các lỗi rõ ràng."},{"en":"Other scientists may request the raw data to verify the results.","vi":"Các nhà khoa học khác có thể yêu cầu dữ liệu thô để xác minh kết quả."}]','[]',NULL,'/rɔː ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5179,'colloc-13-01',89,'reach a consensus','đạt được sự đồng thuận','v + n','[{"en":"After long discussion, the committee finally reached a consensus.","vi":"Sau cuộc thảo luận dài, ủy ban cuối cùng đạt được sự đồng thuận."},{"en":"Scientists have yet to reach a consensus on the exact cause.","vi":"Các nhà khoa học vẫn chưa đạt được sự đồng thuận về nguyên nhân chính xác."},{"en":"The group worked patiently to reach a consensus everyone accepted.","vi":"Cả nhóm kiên nhẫn làm việc để đạt được sự đồng thuận mà mọi người chấp nhận."}]','[]',NULL,'/riːtʃ ə kənˈsensəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5180,'colloc-13-01',90,'reach a peak','đạt đến đỉnh điểm','v + n','[{"en":"Sales reached a peak in December before falling sharply afterward.","vi":"Doanh số đạt đến đỉnh điểm vào tháng Mười Hai trước khi giảm mạnh sau đó."},{"en":"Unemployment reached a peak during the worst of the recession.","vi":"Tỷ lệ thất nghiệp đạt đến đỉnh điểm trong giai đoạn suy thoái tồi tệ nhất."},{"en":"The temperature reaches a peak in the early afternoon each day.","vi":"Nhiệt độ đạt đến đỉnh điểm vào đầu giờ chiều mỗi ngày."}]','[]',NULL,'/riːtʃ ə piːk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5181,'colloc-13-01',91,'reach an agreement','đạt được một thỏa thuận','v + n','[{"en":"The two sides finally reached an agreement after weeks of talks.","vi":"Hai bên cuối cùng đạt được một thỏa thuận sau nhiều tuần đàm phán."},{"en":"Negotiators hope to reach an agreement before the strike begins.","vi":"Các nhà đàm phán hy vọng đạt được một thỏa thuận trước khi đình công bắt đầu."},{"en":"It took considerable compromise to reach an agreement on the budget.","vi":"Phải nhượng bộ đáng kể mới đạt được một thỏa thuận về ngân sách."}]','[]',NULL,'/riːtʃ ən əˈɡriːmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5182,'colloc-13-01',92,'readily accessible','dễ dàng tiếp cận','adv + adj','[{"en":"The library makes most of its resources readily accessible online.","vi":"Thư viện làm cho hầu hết tài nguyên của mình dễ dàng tiếp cận trực tuyến."},{"en":"Good design keeps emergency exits readily accessible to everyone.","vi":"Thiết kế tốt giữ cho các lối thoát hiểm dễ dàng tiếp cận với mọi người."},{"en":"These records are readily accessible to any registered researcher.","vi":"Những hồ sơ này dễ dàng tiếp cận với bất kỳ nhà nghiên cứu đã đăng ký nào."}]','[]',NULL,'/ˈredəli əkˈsesəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5183,'colloc-13-01',93,'readily available','sẵn có dễ dàng','adv + adj','[{"en":"Fresh produce is readily available at the local farmers'' market.","vi":"Nông sản tươi sẵn có dễ dàng tại chợ nông sản địa phương."},{"en":"Detailed statistics are now readily available to the public online.","vi":"Số liệu chi tiết hiện đã sẵn có dễ dàng cho công chúng trên mạng."},{"en":"Clean water is not always readily available in remote villages.","vi":"Nước sạch không phải lúc nào cũng sẵn có dễ dàng ở các làng xa xôi."}]','[]',NULL,'/ˈredəli əˈveɪləbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5184,'colloc-13-01',94,'readily understood','dễ dàng được hiểu','adv + vpp','[{"en":"The instructions were clear and readily understood by every participant.","vi":"Hướng dẫn rõ ràng và dễ dàng được hiểu bởi mọi người tham gia."},{"en":"Simple diagrams make complex ideas more readily understood.","vi":"Sơ đồ đơn giản làm cho các ý tưởng phức tạp dễ dàng được hiểu hơn."},{"en":"Her argument was readily understood despite the technical subject.","vi":"Lập luận của cô dễ dàng được hiểu dù chủ đề mang tính kỹ thuật."}]','[]',NULL,'/ˈredəli ˌʌndərˈstʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5185,'colloc-13-01',95,'ready access','khả năng tiếp cận dễ dàng','adj + n','[{"en":"Students need ready access to reliable academic sources online.","vi":"Sinh viên cần tiếp cận dễ dàng các nguồn học thuật đáng tin cậy trực tuyến."},{"en":"The clinic gives patients ready access to qualified doctors.","vi":"Phòng khám giúp bệnh nhân tiếp cận dễ dàng với bác sĩ có chuyên môn."},{"en":"Ready access to data helped the team finish faster.","vi":"Việc tiếp cận dữ liệu dễ dàng giúp nhóm hoàn thành nhanh hơn."}]','[]',NULL,'/ˈredi ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5186,'colloc-13-01',96,'real issue','vấn đề thực sự','adj + n','[{"en":"The real issue here is a lack of funding.","vi":"Vấn đề thực sự ở đây là thiếu kinh phí."},{"en":"We must address the real issue, not just the symptoms.","vi":"Chúng ta phải giải quyết vấn đề thực sự, không chỉ các triệu chứng."},{"en":"Her essay finally identified the real issue behind the conflict.","vi":"Bài luận của cô cuối cùng đã chỉ ra vấn đề thực sự đằng sau xung đột."}]','[]',NULL,'/ˈriːəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5187,'colloc-13-01',97,'receive feedback','nhận phản hồi','v + n','[{"en":"Students receive feedback on their essays within one week.","vi":"Sinh viên nhận phản hồi về bài luận của mình trong vòng một tuần."},{"en":"It helps to receive feedback from several different readers.","vi":"Việc nhận phản hồi từ nhiều người đọc khác nhau rất hữu ích."},{"en":"Employees who receive feedback regularly tend to improve quickly.","vi":"Những nhân viên thường xuyên nhận phản hồi có xu hướng tiến bộ nhanh."}]','[]',NULL,'/rɪˈsiːv ˈfiːdbæk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5188,'colloc-13-01',98,'receive information','nhận thông tin','v + n','[{"en":"Patients receive information about treatment options before deciding.","vi":"Bệnh nhân nhận thông tin về các lựa chọn điều trị trước khi quyết định."},{"en":"We receive information from the database in real time.","vi":"Chúng tôi nhận thông tin từ cơ sở dữ liệu theo thời gian thực."},{"en":"Travellers receive information about delays through a mobile app.","vi":"Hành khách nhận thông tin về sự chậm trễ qua một ứng dụng di động."}]','[]',NULL,'/rɪˈsiːv ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5189,'colloc-13-01',99,'receive treatment','được điều trị','v + n','[{"en":"Many patients receive treatment at home rather than in hospital.","vi":"Nhiều bệnh nhân được điều trị tại nhà thay vì trong bệnh viện."},{"en":"Children who receive treatment early often recover completely.","vi":"Trẻ em được điều trị sớm thường hồi phục hoàn toàn."},{"en":"The study tracked how quickly people receive treatment after injury.","vi":"Nghiên cứu theo dõi việc người ta được điều trị nhanh ra sao sau chấn thương."}]','[]',NULL,'/rɪˈsiːv ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5190,'colloc-13-01',100,'recent decades','những thập kỷ gần đây','adj + n','[{"en":"In recent decades, technology has transformed how we communicate.","vi":"Trong những thập kỷ gần đây, công nghệ đã thay đổi cách chúng ta giao tiếp."},{"en":"Global temperatures have risen sharply over recent decades.","vi":"Nhiệt độ toàn cầu đã tăng mạnh trong những thập kỷ gần đây."},{"en":"Recent decades have seen rapid growth in online education.","vi":"Những thập kỷ gần đây chứng kiến sự tăng trưởng nhanh của giáo dục trực tuyến."}]','[]',NULL,'/ˈriːsənt ˈdekeɪdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5191,'colloc-13-01',101,'recent evidence','bằng chứng gần đây','adj + n','[{"en":"Recent evidence suggests sleep strongly affects academic performance.","vi":"Bằng chứng gần đây cho thấy giấc ngủ ảnh hưởng mạnh đến kết quả học tập."},{"en":"The author cites recent evidence to support her main claim.","vi":"Tác giả trích dẫn bằng chứng gần đây để củng cố luận điểm chính của mình."},{"en":"Recent evidence challenges several long-held assumptions in the field.","vi":"Bằng chứng gần đây thách thức nhiều giả định lâu nay trong lĩnh vực này."}]','[]',NULL,'/ˈriːsənt ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5192,'colloc-13-01',102,'recent research','nghiên cứu gần đây','adj + n','[{"en":"Recent research has shown that exercise improves memory and focus.","vi":"Nghiên cứu gần đây cho thấy tập thể dục cải thiện trí nhớ và sự tập trung."},{"en":"Her thesis builds on recent research in cognitive science.","vi":"Luận văn của cô dựa trên nghiên cứu gần đây trong khoa học nhận thức."},{"en":"Recent research challenges the idea that talent is fixed.","vi":"Nghiên cứu gần đây bác bỏ quan niệm cho rằng tài năng là cố định."}]','[]',NULL,'/ˈriːsənt ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5193,'colloc-13-01',103,'recent study','nghiên cứu gần đây','adj + n','[{"en":"A recent study found that short breaks boost productivity.","vi":"Một nghiên cứu gần đây phát hiện rằng nghỉ ngắn giúp tăng năng suất."},{"en":"The recent study surveyed over two thousand university students.","vi":"Nghiên cứu gần đây đã khảo sát hơn hai nghìn sinh viên đại học."},{"en":"According to a recent study, diet affects mood significantly.","vi":"Theo một nghiên cứu gần đây, chế độ ăn ảnh hưởng đáng kể đến tâm trạng."}]','[]',NULL,'/ˈriːsənt ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5194,'colloc-13-01',104,'recent survey','cuộc khảo sát gần đây','adj + n','[{"en":"A recent survey revealed that most students prefer online lectures.","vi":"Một cuộc khảo sát gần đây cho thấy hầu hết sinh viên thích bài giảng trực tuyến."},{"en":"The recent survey collected responses from five hundred employees.","vi":"Cuộc khảo sát gần đây thu thập câu trả lời từ năm trăm nhân viên."},{"en":"Results from the recent survey appear in the appendix.","vi":"Kết quả của cuộc khảo sát gần đây nằm trong phần phụ lục."}]','[]',NULL,'/ˈriːsənt ˈsɜːrveɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5195,'colloc-13-01',105,'reciprocal relationship','mối quan hệ tương hỗ','adj + n','[{"en":"Trust and honesty form a reciprocal relationship between partners.","vi":"Niềm tin và sự trung thực tạo nên một mối quan hệ tương hỗ giữa các đối tác."},{"en":"The study describes a reciprocal relationship between reading and writing.","vi":"Nghiên cứu mô tả một mối quan hệ tương hỗ giữa việc đọc và viết."},{"en":"Predators and prey share a reciprocal relationship within the ecosystem.","vi":"Động vật săn mồi và con mồi có một mối quan hệ tương hỗ trong hệ sinh thái."}]','[]',NULL,'/rɪˈsɪprəkəl rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5196,'colloc-13-01',106,'record data','ghi lại dữ liệu','v + n','[{"en":"Researchers record data carefully to avoid measurement errors.","vi":"Các nhà nghiên cứu ghi lại dữ liệu cẩn thận để tránh sai số đo lường."},{"en":"Sensors record data continuously throughout the entire experiment.","vi":"Các cảm biến ghi lại dữ liệu liên tục trong suốt thí nghiệm."},{"en":"Please record data in the spreadsheet after each trial.","vi":"Vui lòng ghi lại dữ liệu vào bảng tính sau mỗi lần thử."}]','[]',NULL,'/rɪˈkɔːrd ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5197,'colloc-13-01',107,'recurrent theme','chủ đề lặp lại','adj + n','[{"en":"Isolation is a recurrent theme throughout the author''s novels.","vi":"Sự cô lập là một chủ đề lặp lại xuyên suốt các tiểu thuyết của tác giả."},{"en":"Inequality emerged as a recurrent theme in the interviews.","vi":"Bất bình đẳng nổi lên như một chủ đề lặp lại trong các cuộc phỏng vấn."},{"en":"Hope is a recurrent theme in her early poetry.","vi":"Hy vọng là một chủ đề lặp lại trong thơ thời kỳ đầu của bà."}]','[]',NULL,'/rɪˈkɜːrənt ˈθiːm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5198,'colloc-13-01',108,'reduce emissions','giảm khí thải','v + n','[{"en":"Governments are under pressure to reduce emissions from transport.","vi":"Các chính phủ chịu áp lực phải giảm khí thải từ giao thông."},{"en":"Switching to renewable energy can significantly reduce emissions.","vi":"Chuyển sang năng lượng tái tạo có thể giảm khí thải đáng kể."},{"en":"The company pledged to reduce emissions by half within ten years.","vi":"Công ty cam kết giảm khí thải một nửa trong vòng mười năm."}]','[]',NULL,'/rɪˈduːs ɪˈmɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5199,'colloc-13-01',109,'reduce stress','giảm căng thẳng','v + n','[{"en":"Regular exercise can help students reduce stress before exams.","vi":"Tập thể dục đều đặn có thể giúp sinh viên giảm căng thẳng trước kỳ thi."},{"en":"Deep breathing is a simple way to reduce stress quickly.","vi":"Hít thở sâu là một cách đơn giản để giảm căng thẳng nhanh chóng."},{"en":"Flexible working hours may reduce stress among employees.","vi":"Giờ làm việc linh hoạt có thể giảm căng thẳng cho nhân viên."}]','[]',NULL,'/rɪˈduːs ˈstres/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5200,'colloc-13-01',110,'reduce the likelihood','giảm khả năng xảy ra','v + n','[{"en":"Careful planning can reduce the likelihood of serious mistakes.","vi":"Lập kế hoạch cẩn thận có thể giảm khả năng xảy ra sai sót nghiêm trọng."},{"en":"Vaccination greatly reduces the likelihood of severe illness.","vi":"Tiêm vắc-xin giảm đáng kể khả năng mắc bệnh nặng."},{"en":"Better lighting can reduce the likelihood of accidents at night.","vi":"Chiếu sáng tốt hơn có thể giảm khả năng xảy ra tai nạn vào ban đêm."}]','[]',NULL,'/rɪˈduːs ðə ˈlaɪklihʊd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5201,'colloc-13-01',111,'reflective practice','thực hành phản tư','adj + n','[{"en":"Reflective practice helps teachers learn from their daily experiences.","vi":"Thực hành phản tư giúp giáo viên học hỏi từ trải nghiệm hằng ngày."},{"en":"Nurses use reflective practice to improve patient care over time.","vi":"Y tá dùng thực hành phản tư để cải thiện việc chăm sóc bệnh nhân theo thời gian."},{"en":"The course encourages reflective practice through regular journal writing.","vi":"Khóa học khuyến khích thực hành phản tư qua việc viết nhật ký thường xuyên."}]','[]',NULL,'/rɪˈflektɪv ˈpræktɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5202,'colloc-13-01',112,'reflective question','câu hỏi gợi suy ngẫm','adj + n','[{"en":"The tutor ended each lesson with a reflective question.","vi":"Người hướng dẫn kết thúc mỗi buổi học bằng một câu hỏi gợi suy ngẫm."},{"en":"A good reflective question encourages learners to examine their assumptions.","vi":"Một câu hỏi gợi suy ngẫm tốt khuyến khích người học xem xét lại các giả định."},{"en":"She wrote a reflective question at the top of each page.","vi":"Cô viết một câu hỏi gợi suy ngẫm ở đầu mỗi trang."}]','[]',NULL,'/rɪˈflektɪv ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5203,'colloc-13-01',113,'regional development','phát triển vùng','adj + n','[{"en":"The policy aims to support regional development in rural areas.","vi":"Chính sách này nhằm hỗ trợ phát triển vùng ở các khu vực nông thôn."},{"en":"Investment in roads often drives regional development.","vi":"Đầu tư vào đường sá thường thúc đẩy phát triển vùng."},{"en":"The report compares regional development across several countries.","vi":"Báo cáo so sánh sự phát triển vùng giữa nhiều quốc gia."}]','[]',NULL,'/ˈriːdʒənəl dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5204,'colloc-13-01',114,'regional differences','sự khác biệt giữa các vùng','adj + n','[{"en":"The survey revealed clear regional differences in eating habits.","vi":"Cuộc khảo sát cho thấy rõ sự khác biệt giữa các vùng về thói quen ăn uống."},{"en":"Regional differences in income affect access to healthcare.","vi":"Sự khác biệt thu nhập giữa các vùng ảnh hưởng đến việc tiếp cận y tế."},{"en":"Researchers noted strong regional differences in language use.","vi":"Các nhà nghiên cứu ghi nhận sự khác biệt rõ giữa các vùng trong cách dùng ngôn ngữ."}]','[]',NULL,'/ˈriːdʒənəl ˈdɪfərənsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5205,'colloc-13-01',115,'regional variation','sự biến thiên theo vùng','adj + n','[{"en":"There is considerable regional variation in rainfall across the country.","vi":"Có sự biến thiên theo vùng đáng kể về lượng mưa trên cả nước."},{"en":"The map illustrates regional variation in average house prices.","vi":"Bản đồ minh họa sự biến thiên theo vùng về giá nhà trung bình."},{"en":"Regional variation in accent makes the language richer.","vi":"Sự biến thiên theo vùng trong giọng nói khiến ngôn ngữ phong phú hơn."}]','[]',NULL,'/ˈriːdʒənəl ˌveriˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5206,'colloc-13-01',116,'regulatory agency','cơ quan quản lý','adj + n','[{"en":"A national regulatory agency oversees safety standards in the industry.","vi":"Một cơ quan quản lý quốc gia giám sát các tiêu chuẩn an toàn trong ngành."},{"en":"The regulatory agency fined the company for breaking the rules.","vi":"Cơ quan quản lý đã phạt công ty vì vi phạm các quy định."},{"en":"Drug approval requires review by an independent regulatory agency.","vi":"Việc phê duyệt thuốc cần được một cơ quan quản lý độc lập xem xét."}]','[]',NULL,'/ˈreɡjələtɔːri ˈeɪdʒənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5207,'colloc-13-01',117,'regulatory framework','khung pháp lý quản lý','adj + n','[{"en":"A clear regulatory framework helps new businesses operate safely.","vi":"Một khung pháp lý quản lý rõ ràng giúp các doanh nghiệp mới hoạt động an toàn."},{"en":"The regulatory framework was updated to address online privacy.","vi":"Khung pháp lý quản lý đã được cập nhật để giải quyết quyền riêng tư trực tuyến."},{"en":"Weak regulatory frameworks can allow harmful practices to continue.","vi":"Khung pháp lý quản lý yếu kém có thể để các hành vi gây hại tiếp diễn."}]','[]',NULL,'/ˈreɡjələtɔːri ˈfreɪmwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5208,'colloc-13-01',118,'related activity','hoạt động liên quan','adj + n','[{"en":"The textbook includes a related activity at the end of each chapter.","vi":"Sách giáo khoa có một hoạt động liên quan ở cuối mỗi chương."},{"en":"Reading and any related activity can improve vocabulary together.","vi":"Việc đọc và bất kỳ hoạt động liên quan nào đều có thể cùng cải thiện từ vựng."},{"en":"Each lesson is paired with a related activity for practice.","vi":"Mỗi bài học đi kèm một hoạt động liên quan để luyện tập."}]','[]',NULL,'/rɪˈleɪtɪd ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5209,'colloc-13-01',119,'related area','lĩnh vực liên quan','adj + n','[{"en":"Her degree opened doors in engineering and several related areas.","vi":"Bằng cấp của cô mở ra cơ hội trong kỹ thuật và một số lĩnh vực liên quan."},{"en":"The paper reviews findings from psychology and related areas.","vi":"Bài báo điểm lại các phát hiện từ tâm lý học và những lĩnh vực liên quan."},{"en":"Researchers in this related area face similar methodological challenges.","vi":"Các nhà nghiên cứu trong lĩnh vực liên quan này gặp những thách thức phương pháp tương tự."}]','[]',NULL,'/rɪˈleɪtɪd ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5210,'colloc-13-01',120,'related aspect','khía cạnh liên quan','adj + n','[{"en":"The chapter explores one related aspect of climate policy in detail.","vi":"Chương này khám phá chi tiết một khía cạnh liên quan của chính sách khí hậu."},{"en":"We will now turn to a closely related aspect of the problem.","vi":"Bây giờ chúng ta sẽ chuyển sang một khía cạnh liên quan chặt chẽ của vấn đề."},{"en":"Each related aspect deserves separate attention in the analysis.","vi":"Mỗi khía cạnh liên quan đều xứng đáng được chú ý riêng trong phân tích."}]','[]',NULL,'/rɪˈleɪtɪd ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5211,'colloc-13-01',121,'related factor','yếu tố liên quan','adj + n','[{"en":"Income is one related factor that influences educational outcomes.","vi":"Thu nhập là một yếu tố liên quan ảnh hưởng đến kết quả giáo dục."},{"en":"The study controlled for every related factor it could identify.","vi":"Nghiên cứu đã kiểm soát mọi yếu tố liên quan mà nó có thể xác định."},{"en":"Stress and sleep are two closely related factors here.","vi":"Căng thẳng và giấc ngủ là hai yếu tố liên quan chặt chẽ ở đây."}]','[]',NULL,'/rɪˈleɪtɪd ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5212,'colloc-13-01',122,'related information','thông tin liên quan','adj + n','[{"en":"The website groups all related information on a single page.","vi":"Trang web nhóm tất cả thông tin liên quan vào một trang duy nhất."},{"en":"Please attach any related information to support your application.","vi":"Vui lòng đính kèm bất kỳ thông tin liên quan nào để hỗ trợ đơn của bạn."},{"en":"The footnotes point readers toward related information elsewhere.","vi":"Các chú thích chỉ dẫn người đọc đến thông tin liên quan ở nơi khác."}]','[]',NULL,'/rɪˈleɪtɪd ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5213,'colloc-13-01',123,'related issue','vấn đề liên quan','adj + n','[{"en":"Privacy is a related issue that the report also addresses.","vi":"Quyền riêng tư là một vấn đề liên quan mà báo cáo cũng đề cập."},{"en":"Before concluding, the author raises one final related issue.","vi":"Trước khi kết luận, tác giả nêu ra một vấn đề liên quan cuối cùng."},{"en":"We should not ignore this closely related issue.","vi":"Chúng ta không nên bỏ qua vấn đề liên quan chặt chẽ này."}]','[]',NULL,'/rɪˈleɪtɪd ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5214,'colloc-13-01',124,'related problem','vấn đề liên quan','adj + n','[{"en":"Traffic and pollution are a closely related problem in cities.","vi":"Giao thông và ô nhiễm là một vấn đề liên quan chặt chẽ ở các thành phố."},{"en":"Solving one issue often reveals another related problem.","vi":"Giải quyết một vấn đề thường làm lộ ra một vấn đề liên quan khác."},{"en":"The next section discusses a related problem in detail.","vi":"Phần tiếp theo thảo luận chi tiết một vấn đề liên quan."}]','[]',NULL,'/rɪˈleɪtɪd ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5215,'colloc-13-01',125,'related question','câu hỏi liên quan','adj + n','[{"en":"This leads us to a related question about funding.","vi":"Điều này dẫn chúng ta đến một câu hỏi liên quan về kinh phí."},{"en":"The interview ended with a related question about future plans.","vi":"Cuộc phỏng vấn kết thúc bằng một câu hỏi liên quan về kế hoạch tương lai."},{"en":"A related question concerns who should pay for repairs.","vi":"Một câu hỏi liên quan là ai nên trả tiền sửa chữa."}]','[]',NULL,'/rɪˈleɪtɪd ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5216,'colloc-13-01',126,'related topic','chủ đề liên quan','adj + n','[{"en":"The seminar covered migration and one related topic afterwards.","vi":"Buổi hội thảo bàn về di cư và sau đó một chủ đề liên quan."},{"en":"Students may choose any related topic for their final essay.","vi":"Sinh viên có thể chọn bất kỳ chủ đề liên quan nào cho bài luận cuối kỳ."},{"en":"The lecture briefly touched on a related topic at the end.","vi":"Bài giảng đề cập ngắn gọn một chủ đề liên quan ở phần cuối."}]','[]',NULL,'/rɪˈleɪtɪd ˈtɑːpɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5217,'colloc-13-01',127,'relative autonomy','quyền tự chủ tương đối','adj + n','[{"en":"Local councils enjoy relative autonomy in managing their budgets.","vi":"Các hội đồng địa phương có quyền tự chủ tương đối trong việc quản lý ngân sách."},{"en":"The article examines the relative autonomy of universities from the state.","vi":"Bài báo xem xét quyền tự chủ tương đối của các trường đại học với nhà nước."},{"en":"Teachers value the relative autonomy they have in the classroom.","vi":"Giáo viên coi trọng quyền tự chủ tương đối họ có trong lớp học."}]','[]',NULL,'/ˈrelətɪv ɔːˈtɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5218,'colloc-13-01',128,'relative merits','ưu điểm tương đối','adj + n','[{"en":"The essay weighs the relative merits of two teaching methods.","vi":"Bài luận cân nhắc ưu điểm tương đối của hai phương pháp giảng dạy."},{"en":"We debated the relative merits of each proposed solution.","vi":"Chúng tôi tranh luận về ưu điểm tương đối của mỗi giải pháp được đề xuất."},{"en":"Consider the relative merits before choosing a research design.","vi":"Hãy cân nhắc ưu điểm tương đối trước khi chọn một thiết kế nghiên cứu."}]','[]',NULL,'/ˈrelətɪv ˈmerɪts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5219,'colloc-13-01',129,'relative status','vị thế tương đối','adj + n','[{"en":"The study compares the relative status of men and women.","vi":"Nghiên cứu so sánh vị thế tương đối của nam giới và nữ giới."},{"en":"Income often shapes a family''s relative status in society.","vi":"Thu nhập thường định hình vị thế tương đối của một gia đình trong xã hội."},{"en":"Language can signal the relative status of the speakers.","vi":"Ngôn ngữ có thể báo hiệu vị thế tương đối của người nói."}]','[]',NULL,'/ˈrelətɪv ˈsteɪtəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5220,'colloc-13-01',130,'relatively common','tương đối phổ biến','adv + adj','[{"en":"This condition is relatively common among older adults.","vi":"Tình trạng này tương đối phổ biến ở người lớn tuổi."},{"en":"Spelling errors are relatively common in early drafts.","vi":"Lỗi chính tả tương đối phổ biến trong các bản nháp đầu tiên."},{"en":"Such mistakes are relatively common but easy to correct.","vi":"Những lỗi như vậy tương đối phổ biến nhưng dễ sửa."}]','[]',NULL,'/ˈrelətɪvli ˈkɑːmən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5221,'colloc-13-01',131,'relatively constant','tương đối ổn định','adv + adj','[{"en":"The temperature stayed relatively constant throughout the experiment.","vi":"Nhiệt độ duy trì tương đối ổn định trong suốt thí nghiệm."},{"en":"Prices have remained relatively constant over the past year.","vi":"Giá cả vẫn tương đối ổn định trong năm qua."},{"en":"Population size was relatively constant across the whole period.","vi":"Quy mô dân số tương đối ổn định trong suốt giai đoạn này."}]','[]',NULL,'/ˈrelətɪvli ˈkɑːnstənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5222,'colloc-13-01',132,'relatively few','tương đối ít','adv + adj','[{"en":"Relatively few students chose to study the optional module.","vi":"Tương đối ít sinh viên chọn học học phần tự chọn."},{"en":"There are relatively few studies on this rare disease.","vi":"Có tương đối ít nghiên cứu về căn bệnh hiếm gặp này."},{"en":"Relatively few people attended the early morning lecture.","vi":"Tương đối ít người tham dự bài giảng buổi sáng sớm."}]','[]',NULL,'/ˈrelətɪvli ˈfjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5223,'colloc-13-01',133,'relatively high','tương đối cao','adv + adj','[{"en":"Unemployment remained relatively high in the region last year.","vi":"Tỷ lệ thất nghiệp vẫn tương đối cao ở khu vực này năm ngoái."},{"en":"The cost of living here is relatively high for students.","vi":"Chi phí sinh hoạt ở đây tương đối cao đối với sinh viên."},{"en":"The course has a relatively high pass rate this term.","vi":"Khóa học có tỷ lệ đậu tương đối cao trong học kỳ này."}]','[]',NULL,'/ˈrelətɪvli ˈhaɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5224,'colloc-13-01',134,'relatively little','tương đối ít','adv + adj','[{"en":"Relatively little research exists on this particular topic.","vi":"Có tương đối ít nghiên cứu về chủ đề cụ thể này."},{"en":"The project required relatively little funding to complete.","vi":"Dự án cần tương đối ít kinh phí để hoàn thành."},{"en":"We know relatively little about how the system fails.","vi":"Chúng ta biết tương đối ít về cách hệ thống bị lỗi."}]','[]',NULL,'/ˈrelətɪvli ˈlɪtəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5225,'colloc-13-01',135,'relatively low','tương đối thấp','adv + adj','[{"en":"The risk of infection is relatively low in this group.","vi":"Nguy cơ nhiễm trùng tương đối thấp ở nhóm này."},{"en":"Wages in the sector remain relatively low despite demand.","vi":"Lương trong ngành vẫn tương đối thấp dù nhu cầu cao."},{"en":"The error rate was relatively low throughout the test.","vi":"Tỷ lệ lỗi tương đối thấp trong suốt bài kiểm tra."}]','[]',NULL,'/ˈrelətɪvli ˈloʊ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5226,'colloc-13-01',136,'relatively minor','tương đối nhỏ','adv + adj','[{"en":"The damage was relatively minor and quickly repaired.","vi":"Thiệt hại tương đối nhỏ và được sửa chữa nhanh chóng."},{"en":"These are relatively minor errors that do not affect the results.","vi":"Đây là những lỗi tương đối nhỏ không ảnh hưởng đến kết quả."},{"en":"Compared to the benefits, the costs seem relatively minor.","vi":"So với lợi ích, chi phí có vẻ tương đối nhỏ."}]','[]',NULL,'/ˈrelətɪvli ˈmaɪnər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5227,'colloc-13-01',137,'relatively rare','tương đối hiếm','adv + adj','[{"en":"Such severe reactions are relatively rare among patients.","vi":"Những phản ứng nghiêm trọng như vậy tương đối hiếm ở bệnh nhân."},{"en":"This species has become relatively rare in the wild.","vi":"Loài này đã trở nên tương đối hiếm trong tự nhiên."},{"en":"Genuine breakthroughs are relatively rare in this field.","vi":"Những bước đột phá thực sự tương đối hiếm trong lĩnh vực này."}]','[]',NULL,'/ˈrelətɪvli ˈrer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5228,'colloc-13-01',138,'relatively recent','tương đối gần đây','adv + adj','[{"en":"Online learning is a relatively recent development in education.","vi":"Học trực tuyến là một sự phát triển tương đối gần đây trong giáo dục."},{"en":"The practice has a relatively recent history in this country.","vi":"Thông lệ này có một lịch sử tương đối gần đây ở đất nước này."},{"en":"This theory is relatively recent and still being tested.","vi":"Lý thuyết này tương đối gần đây và vẫn đang được kiểm chứng."}]','[]',NULL,'/ˈrelətɪvli ˈriːsənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5229,'colloc-13-01',139,'relatively simple','tương đối đơn giản','adv + adj','[{"en":"The procedure is relatively simple and takes only minutes.","vi":"Quy trình tương đối đơn giản và chỉ mất vài phút."},{"en":"She explained the idea in relatively simple terms.","vi":"Cô giải thích ý tưởng bằng những lời lẽ tương đối đơn giản."},{"en":"The first task is relatively simple compared to the rest.","vi":"Nhiệm vụ đầu tiên tương đối đơn giản so với phần còn lại."}]','[]',NULL,'/ˈrelətɪvli ˈsɪmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5230,'colloc-13-01',140,'relatively stable','tương đối ổn định','adv + adj','[{"en":"The economy has remained relatively stable in recent months.","vi":"Nền kinh tế vẫn tương đối ổn định trong những tháng gần đây."},{"en":"Their results were relatively stable across all conditions.","vi":"Kết quả của họ tương đối ổn định trong mọi điều kiện."},{"en":"Prices stayed relatively stable despite the disruption.","vi":"Giá cả vẫn tương đối ổn định bất chấp sự gián đoạn."}]','[]',NULL,'/ˈrelətɪvli ˈsteɪbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5231,'colloc-13-01',141,'relatively straightforward','tương đối dễ hiểu','adv + adj','[{"en":"The instructions were relatively straightforward and easy to follow.","vi":"Hướng dẫn tương đối dễ hiểu và dễ làm theo."},{"en":"The first stage of the analysis is relatively straightforward.","vi":"Giai đoạn đầu của phân tích tương đối dễ hiểu."},{"en":"Setting up the equipment proved relatively straightforward.","vi":"Việc lắp đặt thiết bị hóa ra tương đối dễ dàng."}]','[]',NULL,'/ˈrelətɪvli ˌstreɪtˈfɔːrwərd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5232,'colloc-13-01',142,'relevant data','dữ liệu liên quan','adj + n','[{"en":"The researcher gathered all relevant data before drawing conclusions.","vi":"Nhà nghiên cứu thu thập tất cả dữ liệu liên quan trước khi đưa ra kết luận."},{"en":"Only relevant data should be included in the final report.","vi":"Chỉ những dữ liệu liên quan mới nên được đưa vào báo cáo cuối cùng."},{"en":"The team struggled to find relevant data on rural areas.","vi":"Nhóm gặp khó khăn trong việc tìm dữ liệu liên quan về khu vực nông thôn."}]','[]',NULL,'/ˈreləvənt ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5233,'colloc-13-01',143,'relevant factors','các yếu tố liên quan','adj + n','[{"en":"The model accounts for all relevant factors affecting growth.","vi":"Mô hình tính đến tất cả các yếu tố liên quan ảnh hưởng đến tăng trưởng."},{"en":"Before deciding, managers weigh several relevant factors carefully.","vi":"Trước khi quyết định, các quản lý cân nhắc cẩn thận một số yếu tố liên quan."},{"en":"Climate and soil are two relevant factors in farming.","vi":"Khí hậu và đất là hai yếu tố liên quan trong canh tác."}]','[]',NULL,'/ˈreləvənt ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5234,'colloc-13-01',144,'relevant information','thông tin liên quan','adj + n','[{"en":"Please highlight the relevant information in each source.","vi":"Vui lòng làm nổi bật thông tin liên quan trong mỗi nguồn."},{"en":"Good readers quickly identify the relevant information in a text.","vi":"Người đọc giỏi nhanh chóng nhận ra thông tin liên quan trong một văn bản."},{"en":"The form asks applicants to provide all relevant information.","vi":"Mẫu đơn yêu cầu người nộp cung cấp tất cả thông tin liên quan."}]','[]',NULL,'/ˈreləvənt ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5235,'colloc-13-01',145,'relevant issue','vấn đề liên quan','adj + n','[{"en":"The debate raised every relevant issue surrounding the policy.","vi":"Cuộc tranh luận đã nêu ra mọi vấn đề liên quan xoay quanh chính sách."},{"en":"Cost is the most relevant issue for many families.","vi":"Chi phí là vấn đề liên quan nhất đối với nhiều gia đình."},{"en":"The committee focused only on the most relevant issue.","vi":"Ủy ban chỉ tập trung vào vấn đề liên quan nhất."}]','[]',NULL,'/ˈreləvənt ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5236,'colloc-13-01',146,'relevant literature','tài liệu liên quan','adj + n','[{"en":"The thesis reviews all relevant literature on the subject.","vi":"Luận văn điểm lại tất cả tài liệu liên quan về chủ đề này."},{"en":"She spent weeks reading the relevant literature before writing.","vi":"Cô dành nhiều tuần đọc tài liệu liên quan trước khi viết."},{"en":"Citing relevant literature strengthens the credibility of your argument.","vi":"Trích dẫn tài liệu liên quan giúp lập luận của bạn đáng tin hơn."}]','[]',NULL,'/ˈreləvənt ˈlɪtərətʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5237,'colloc-13-01',147,'relevant material','tài liệu liên quan','adj + n','[{"en":"The lecturer posts all relevant material on the course website.","vi":"Giảng viên đăng tất cả tài liệu liên quan trên trang web của khóa học."},{"en":"Students should bring relevant material to each tutorial.","vi":"Sinh viên nên mang tài liệu liên quan đến mỗi buổi hướng dẫn."},{"en":"She organised the relevant material into clear folders.","vi":"Cô sắp xếp tài liệu liên quan vào các thư mục rõ ràng."}]','[]',NULL,'/ˈreləvənt məˈtɪriəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5238,'colloc-13-01',148,'reliable data','dữ liệu đáng tin cậy','adj + n','[{"en":"Sound conclusions depend on reliable data from careful measurement.","vi":"Kết luận đúng đắn phụ thuộc vào dữ liệu đáng tin cậy từ việc đo lường cẩn thận."},{"en":"Without reliable data, the model cannot make accurate predictions.","vi":"Nếu không có dữ liệu đáng tin cậy, mô hình không thể dự đoán chính xác."},{"en":"Collecting reliable data took the team several months.","vi":"Việc thu thập dữ liệu đáng tin cậy mất của nhóm vài tháng."}]','[]',NULL,'/rɪˈlaɪəbəl ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5239,'colloc-13-01',149,'reliable information','thông tin đáng tin cậy','adj + n','[{"en":"Always check several sources to get reliable information.","vi":"Luôn kiểm tra nhiều nguồn để có được thông tin đáng tin cậy."},{"en":"The library provides reliable information for academic research.","vi":"Thư viện cung cấp thông tin đáng tin cậy cho nghiên cứu học thuật."},{"en":"Reliable information is hard to find during a crisis.","vi":"Thông tin đáng tin cậy rất khó tìm trong một cuộc khủng hoảng."}]','[]',NULL,'/rɪˈlaɪəbəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5240,'colloc-13-01',150,'religious belief','niềm tin tôn giáo','adj + n','[{"en":"The law protects each citizen''s religious belief and practice.","vi":"Luật bảo vệ niềm tin và việc thực hành tôn giáo của mỗi công dân."},{"en":"Religious belief shaped the architecture of these ancient temples.","vi":"Niềm tin tôn giáo đã định hình kiến trúc của những ngôi đền cổ này."},{"en":"The survey explored how religious belief affects daily choices.","vi":"Cuộc khảo sát tìm hiểu niềm tin tôn giáo ảnh hưởng đến lựa chọn hằng ngày ra sao."}]','[]',NULL,'/rɪˈlɪdʒəs bɪˈliːf/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5241,'colloc-14-01',1,'religious faith','đức tin tôn giáo','adj + n','[{"en":"Her religious faith gave her strength during difficult times.","vi":"Đức tin tôn giáo đã cho cô sức mạnh trong những lúc khó khăn."},{"en":"The novel examines the role of religious faith in family life.","vi":"Cuốn tiểu thuyết xem xét vai trò của đức tin tôn giáo trong đời sống gia đình."},{"en":"Many traditions are rooted in deep religious faith.","vi":"Nhiều truyền thống bắt nguồn từ đức tin tôn giáo sâu sắc."}]','[]',NULL,'/rɪˈlɪdʒəs ˈfeɪθ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5242,'colloc-14-01',2,'religious freedom','tự do tôn giáo','adj + n','[{"en":"The constitution guarantees religious freedom for all citizens.","vi":"Hiến pháp bảo đảm tự do tôn giáo cho mọi công dân."},{"en":"Religious freedom allows people to worship as they choose.","vi":"Tự do tôn giáo cho phép mọi người thờ phụng theo lựa chọn của mình."},{"en":"The essay traces the history of religious freedom in Europe.","vi":"Bài luận lần theo lịch sử tự do tôn giáo ở châu Âu."}]','[]',NULL,'/rɪˈlɪdʒəs ˈfriːdəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5243,'colloc-14-01',3,'religious group','nhóm tôn giáo','adj + n','[{"en":"Each religious group celebrates its own important festivals.","vi":"Mỗi nhóm tôn giáo tổ chức những lễ hội quan trọng của riêng mình."},{"en":"The study surveyed members of several different religious groups.","vi":"Nghiên cứu khảo sát thành viên của nhiều nhóm tôn giáo khác nhau."},{"en":"The city is home to many small religious groups.","vi":"Thành phố là nơi cư trú của nhiều nhóm tôn giáo nhỏ."}]','[]',NULL,'/rɪˈlɪdʒəs ˈɡruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5244,'colloc-14-01',4,'religious identity','bản sắc tôn giáo','adj + n','[{"en":"Food and dress often express a person''s religious identity.","vi":"Thức ăn và trang phục thường thể hiện bản sắc tôn giáo của một người."},{"en":"Migration can reshape a community''s religious identity over time.","vi":"Di cư có thể định hình lại bản sắc tôn giáo của một cộng đồng theo thời gian."},{"en":"The paper explores how schools influence religious identity.","vi":"Bài báo khám phá cách trường học ảnh hưởng đến bản sắc tôn giáo."}]','[]',NULL,'/rɪˈlɪdʒəs aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5245,'colloc-14-01',5,'religious movement','phong trào tôn giáo','adj + n','[{"en":"The historian studied a religious movement from the nineteenth century.","vi":"Nhà sử học nghiên cứu một phong trào tôn giáo từ thế kỷ mười chín."},{"en":"This religious movement quickly spread across several countries.","vi":"Phong trào tôn giáo này nhanh chóng lan rộng qua nhiều quốc gia."},{"en":"A new religious movement emerged among young people in the city.","vi":"Một phong trào tôn giáo mới nổi lên trong giới trẻ ở thành phố."}]','[]',NULL,'/rɪˈlɪdʒəs ˈmuːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5246,'colloc-14-01',6,'religious practice','thực hành tôn giáo','adj + n','[{"en":"Daily prayer is a common religious practice in many cultures.","vi":"Cầu nguyện hằng ngày là một thực hành tôn giáo phổ biến ở nhiều nền văn hóa."},{"en":"Religious practice can vary widely even within one community.","vi":"Thực hành tôn giáo có thể khác nhau rất nhiều ngay trong một cộng đồng."},{"en":"The author links religious practice to community well-being.","vi":"Tác giả gắn thực hành tôn giáo với sự an lành của cộng đồng."}]','[]',NULL,'/rɪˈlɪdʒəs ˈpræktɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5247,'colloc-14-01',7,'rely heavily on','phụ thuộc nhiều vào','v + adv','[{"en":"Many farmers rely heavily on rainfall for their crops.","vi":"Nhiều nông dân phụ thuộc nhiều vào lượng mưa cho mùa màng của họ."},{"en":"The argument relies heavily on a single, outdated source.","vi":"Lập luận phụ thuộc nhiều vào một nguồn duy nhất đã lỗi thời."},{"en":"Modern cities rely heavily on a steady supply of energy.","vi":"Các thành phố hiện đại phụ thuộc nhiều vào nguồn cung năng lượng ổn định."}]','[]',NULL,'/rɪˈlaɪ ˈhevɪli ɑːn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5248,'colloc-14-01',8,'remain constant','giữ nguyên không đổi','v + adj','[{"en":"The pressure must remain constant for the reaction to work.","vi":"Áp suất phải giữ nguyên không đổi để phản ứng diễn ra."},{"en":"If demand remains constant, prices are unlikely to change.","vi":"Nếu nhu cầu giữ nguyên không đổi, giá khó có khả năng thay đổi."},{"en":"The team kept the temperature remaining constant throughout.","vi":"Nhóm giữ cho nhiệt độ không đổi trong suốt quá trình."}]','[]',NULL,'/rɪˈmeɪn ˈkɑːnstənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5249,'colloc-14-01',9,'remain stable','vẫn ổn định','v + adj','[{"en":"House prices are expected to remain stable next year.","vi":"Giá nhà được dự đoán sẽ vẫn ổn định vào năm tới."},{"en":"His blood pressure remained stable after the treatment.","vi":"Huyết áp của anh vẫn ổn định sau khi điều trị."},{"en":"The population is likely to remain stable for a decade.","vi":"Dân số có khả năng vẫn ổn định trong một thập kỷ."}]','[]',NULL,'/rɪˈmeɪn ˈsteɪbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5250,'colloc-14-01',10,'remain unchanged','vẫn không thay đổi','v + adj','[{"en":"The basic rules of the game remain unchanged today.","vi":"Các quy tắc cơ bản của trò chơi vẫn không thay đổi đến nay."},{"en":"Despite the reforms, working conditions remained unchanged.","vi":"Dù có cải cách, điều kiện làm việc vẫn không thay đổi."},{"en":"If the policy remains unchanged, the problem will continue.","vi":"Nếu chính sách vẫn không thay đổi, vấn đề sẽ tiếp diễn."}]','[]',NULL,'/rɪˈmeɪn ʌnˈtʃeɪndʒd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5251,'colloc-14-01',11,'remain unclear','vẫn chưa rõ ràng','v + adj','[{"en":"The cause of the disease remains unclear to scientists.","vi":"Nguyên nhân của căn bệnh vẫn chưa rõ ràng với các nhà khoa học."},{"en":"It remains unclear whether the policy actually reduced crime.","vi":"Vẫn chưa rõ liệu chính sách có thực sự giảm tội phạm hay không."},{"en":"The author admits the results remain unclear and need further study.","vi":"Tác giả thừa nhận kết quả vẫn chưa rõ ràng và cần nghiên cứu thêm."}]','[]',NULL,'/rɪˈmeɪn ʌnˈklɪr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5252,'colloc-14-01',12,'remarkably similar','giống nhau một cách đáng kinh ngạc','adv + adj','[{"en":"The two studies reached remarkably similar conclusions.","vi":"Hai nghiên cứu đi đến những kết luận giống nhau một cách đáng kinh ngạc."},{"en":"Their handwriting was remarkably similar despite the distance.","vi":"Chữ viết của họ giống nhau một cách đáng kinh ngạc dù cách xa nhau."},{"en":"The two languages have remarkably similar grammar structures.","vi":"Hai ngôn ngữ có cấu trúc ngữ pháp giống nhau một cách đáng kinh ngạc."}]','[]',NULL,'/rɪˈmɑːrkəbli ˈsɪmələr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5253,'colloc-14-01',13,'renewable energy','năng lượng tái tạo','adj + n','[{"en":"Many countries are investing heavily in renewable energy.","vi":"Nhiều quốc gia đang đầu tư mạnh vào năng lượng tái tạo."},{"en":"Solar and wind are the most common renewable energy sources.","vi":"Mặt trời và gió là những nguồn năng lượng tái tạo phổ biến nhất."},{"en":"Renewable energy could replace much of our fossil fuel use.","vi":"Năng lượng tái tạo có thể thay thế phần lớn việc dùng nhiên liệu hóa thạch."}]','[]',NULL,'/rɪˈnuːəbəl ˈenərdʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5254,'colloc-14-01',14,'renewed interest','sự quan tâm trở lại','adj + n','[{"en":"The discovery sparked renewed interest in ancient farming methods.","vi":"Khám phá này khơi dậy sự quan tâm trở lại về các phương pháp canh tác cổ."},{"en":"There is renewed interest in studying local dialects.","vi":"Có sự quan tâm trở lại đối với việc nghiên cứu các phương ngữ địa phương."},{"en":"The film led to renewed interest in the author''s work.","vi":"Bộ phim dẫn đến sự quan tâm trở lại với tác phẩm của nhà văn."}]','[]',NULL,'/rɪˈnuːd ˈɪntrəst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5255,'colloc-14-01',15,'report data','báo cáo dữ liệu','v + n','[{"en":"Researchers must report data honestly, even when results disappoint.","vi":"Các nhà nghiên cứu phải báo cáo dữ liệu trung thực, ngay cả khi kết quả gây thất vọng."},{"en":"The article reports data collected over three full years.","vi":"Bài báo báo cáo dữ liệu thu thập trong suốt ba năm."},{"en":"Please report data clearly using tables and figures.","vi":"Vui lòng báo cáo dữ liệu rõ ràng bằng bảng và biểu đồ."}]','[]',NULL,'/rɪˈpɔːrt ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5256,'colloc-14-01',16,'report findings','báo cáo kết quả nghiên cứu','v + n','[{"en":"The committee will report findings to the board next week.","vi":"Ủy ban sẽ báo cáo kết quả nghiên cứu lên hội đồng vào tuần tới."},{"en":"Scientists report findings in peer-reviewed academic journals.","vi":"Các nhà khoa học báo cáo kết quả nghiên cứu trên các tạp chí học thuật được bình duyệt."},{"en":"The team will report findings at the international conference.","vi":"Nhóm sẽ báo cáo kết quả nghiên cứu tại hội nghị quốc tế."}]','[]',NULL,'/rɪˈpɔːrt ˈfaɪndɪŋz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5257,'colloc-14-01',17,'representative government','chính phủ đại diện','adj + n','[{"en":"Free elections are essential to representative government.","vi":"Bầu cử tự do là yếu tố thiết yếu của chính phủ đại diện."},{"en":"The essay traces the rise of representative government in Europe.","vi":"Bài luận lần theo sự trỗi dậy của chính phủ đại diện ở châu Âu."},{"en":"Representative government depends on citizens trusting their leaders.","vi":"Chính phủ đại diện phụ thuộc vào việc công dân tin tưởng các lãnh đạo của mình."}]','[]',NULL,'/ˌreprɪˈzentətɪv ˈɡʌvərnmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5258,'colloc-14-01',18,'require consideration','cần được xem xét','v + n','[{"en":"These ethical questions require careful consideration before any decision.","vi":"Những câu hỏi đạo đức này cần được xem xét cẩn thận trước mọi quyết định."},{"en":"The proposal will require consideration by the whole committee.","vi":"Đề xuất sẽ cần được toàn bộ ủy ban xem xét."},{"en":"Several factors require consideration when designing the experiment.","vi":"Một số yếu tố cần được xem xét khi thiết kế thí nghiệm."}]','[]',NULL,'/rɪˈkwaɪər kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5259,'colloc-14-01',19,'require knowledge','đòi hỏi kiến thức','v + n','[{"en":"These tasks require knowledge of basic statistics and coding.","vi":"Những nhiệm vụ này đòi hỏi kiến thức về thống kê cơ bản và lập trình."},{"en":"The job requires knowledge of at least two foreign languages.","vi":"Công việc đòi hỏi kiến thức về ít nhất hai ngoại ngữ."},{"en":"Interpreting the results requires knowledge of the local context.","vi":"Việc diễn giải kết quả đòi hỏi kiến thức về bối cảnh địa phương."}]','[]',NULL,'/rɪˈkwaɪər ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5260,'colloc-14-01',20,'require resources','đòi hỏi nguồn lực','v + n','[{"en":"Large projects require resources that small teams rarely have.","vi":"Các dự án lớn đòi hỏi nguồn lực mà những nhóm nhỏ hiếm khi có."},{"en":"Training new staff requires resources and a lot of time.","vi":"Đào tạo nhân viên mới đòi hỏi nguồn lực và rất nhiều thời gian."},{"en":"Such reforms require resources that the government cannot easily find.","vi":"Những cải cách như vậy đòi hỏi nguồn lực mà chính phủ khó tìm được."}]','[]',NULL,'/rɪˈkwaɪər ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5261,'colloc-14-01',21,'research effort','nỗ lực nghiên cứu','n + n','[{"en":"The vaccine resulted from a huge international research effort.","vi":"Vắc-xin là kết quả của một nỗ lực nghiên cứu quốc tế khổng lồ."},{"en":"Much research effort has gone into understanding the disease.","vi":"Nhiều nỗ lực nghiên cứu đã được dành để hiểu căn bệnh này."},{"en":"The university coordinates research effort across several departments.","vi":"Trường đại học điều phối nỗ lực nghiên cứu giữa nhiều khoa."}]','[]',NULL,'/ˈriːsɜːrtʃ ˈefərt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5262,'colloc-14-01',22,'research evidence','bằng chứng nghiên cứu','n + n','[{"en":"Strong research evidence supports the benefits of early reading.","vi":"Bằng chứng nghiên cứu vững chắc ủng hộ lợi ích của việc đọc sớm."},{"en":"Policy should be based on solid research evidence, not opinion.","vi":"Chính sách nên dựa trên bằng chứng nghiên cứu vững chắc, không phải ý kiến."},{"en":"The author reviews research evidence from the past ten years.","vi":"Tác giả điểm lại bằng chứng nghiên cứu trong mười năm qua."}]','[]',NULL,'/ˈriːsɜːrtʃ ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5263,'colloc-14-01',23,'research findings','kết quả nghiên cứu','n + n','[{"en":"The research findings were published in a leading journal.","vi":"Kết quả nghiên cứu được công bố trên một tạp chí hàng đầu."},{"en":"These research findings could change how teachers plan lessons.","vi":"Những kết quả nghiên cứu này có thể thay đổi cách giáo viên soạn bài."},{"en":"The author summarises the main research findings in chapter five.","vi":"Tác giả tóm tắt các kết quả nghiên cứu chính trong chương năm."}]','[]',NULL,'/ˈriːsɜːrtʃ ˈfaɪndɪŋz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5264,'colloc-14-01',24,'research methodology','phương pháp nghiên cứu','n + n','[{"en":"The chapter explains the research methodology used in the study.","vi":"Chương này giải thích phương pháp nghiên cứu được dùng trong nghiên cứu."},{"en":"A clear research methodology makes results easier to replicate.","vi":"Một phương pháp nghiên cứu rõ ràng giúp kết quả dễ tái lập hơn."},{"en":"Reviewers criticised the weak research methodology of the paper.","vi":"Người bình duyệt chỉ trích phương pháp nghiên cứu yếu của bài báo."}]','[]',NULL,'/ˈriːsɜːrtʃ ˌmeθəˈdɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5265,'colloc-14-01',25,'research purposes','mục đích nghiên cứu','n + n','[{"en":"The data may be used only for research purposes.","vi":"Dữ liệu chỉ có thể được dùng cho mục đích nghiên cứu."},{"en":"Volunteers agreed to share their records for research purposes.","vi":"Các tình nguyện viên đồng ý chia sẻ hồ sơ của họ cho mục đích nghiên cứu."},{"en":"The samples were collected purely for research purposes.","vi":"Các mẫu được thu thập hoàn toàn cho mục đích nghiên cứu."}]','[]',NULL,'/ˈriːsɜːrtʃ ˈpɜːrpəsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5266,'colloc-14-01',26,'research topic','đề tài nghiên cứu','n + n','[{"en":"Choosing a good research topic is the hardest first step.","vi":"Chọn một đề tài nghiên cứu tốt là bước đầu tiên khó nhất."},{"en":"Her research topic focuses on bilingual children in cities.","vi":"Đề tài nghiên cứu của cô tập trung vào trẻ song ngữ ở thành phố."},{"en":"The supervisor helped him narrow down his research topic.","vi":"Người hướng dẫn giúp anh thu hẹp đề tài nghiên cứu của mình."}]','[]',NULL,'/ˈriːsɜːrtʃ ˈtɑːpɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5267,'colloc-14-01',27,'resolve a conflict','giải quyết một xung đột','v + n','[{"en":"The mediator helped both sides resolve a conflict peacefully.","vi":"Người hòa giải đã giúp hai bên giải quyết xung đột một cách ôn hòa."},{"en":"Good leaders know how to resolve a conflict quickly.","vi":"Lãnh đạo giỏi biết cách giải quyết xung đột một cách nhanh chóng."},{"en":"Diplomacy aims to resolve a conflict without using force.","vi":"Ngoại giao nhằm giải quyết xung đột mà không dùng vũ lực."}]','[]',NULL,'/rɪˈzɑːlv ə ˈkɑːnflɪkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5268,'colloc-14-01',28,'resolve a dispute','giải quyết một tranh chấp','v + n','[{"en":"The court was asked to resolve a dispute over land.","vi":"Tòa án được yêu cầu giải quyết một tranh chấp về đất đai."},{"en":"They hired a lawyer to resolve a dispute between partners.","vi":"Họ thuê luật sư để giải quyết tranh chấp giữa các đối tác."},{"en":"Negotiation often helps resolve a dispute more cheaply than litigation.","vi":"Thương lượng thường giúp giải quyết tranh chấp rẻ hơn so với kiện tụng."}]','[]',NULL,'/rɪˈzɑːlv ə dɪˈspjuːt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5269,'colloc-14-01',29,'respond appropriately','phản ứng một cách phù hợp','v + adv','[{"en":"Nurses are trained to respond appropriately in emergency situations.","vi":"Y tá được đào tạo để phản ứng phù hợp trong các tình huống khẩn cấp."},{"en":"Students must learn to respond appropriately to difficult questions.","vi":"Học sinh phải học cách phản ứng phù hợp với những câu hỏi khó."},{"en":"The system fails when staff cannot respond appropriately to feedback.","vi":"Hệ thống thất bại khi nhân viên không thể phản ứng phù hợp với phản hồi."}]','[]',NULL,'/rɪˈspɑːnd əˈproʊpriətli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5270,'colloc-14-01',30,'review a study','xem xét, đánh giá một nghiên cứu','v + n','[{"en":"Experts were asked to review a study before its publication.","vi":"Các chuyên gia được yêu cầu đánh giá một nghiên cứu trước khi xuất bản."},{"en":"She had to review a study on climate change for class.","vi":"Cô ấy phải đánh giá một nghiên cứu về biến đổi khí hậu cho lớp học."},{"en":"Peer reviewers carefully review a study to ensure its quality.","vi":"Người phản biện cẩn thận đánh giá một nghiên cứu để đảm bảo chất lượng."}]','[]',NULL,'/rɪˈvjuː ə ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5271,'colloc-14-01',31,'revised edition','ấn bản sửa đổi','adj + n','[{"en":"The revised edition of the textbook includes several new chapters.","vi":"Ấn bản sửa đổi của giáo trình bao gồm vài chương mới."},{"en":"Students were told to buy the revised edition this year.","vi":"Sinh viên được yêu cầu mua ấn bản sửa đổi năm nay."},{"en":"The revised edition corrects many errors found in earlier printings.","vi":"Ấn bản sửa đổi sửa nhiều lỗi tìm thấy trong các bản in trước."}]','[]',NULL,'/rɪˈvaɪzd ɪˈdɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5272,'colloc-14-01',32,'revised version','phiên bản sửa đổi','adj + n','[{"en":"She submitted a revised version of her essay after feedback.","vi":"Cô ấy nộp một phiên bản sửa đổi của bài luận sau khi nhận phản hồi."},{"en":"The revised version of the policy addresses earlier concerns.","vi":"Phiên bản sửa đổi của chính sách giải quyết những lo ngại trước đó."},{"en":"Please read the revised version before the meeting tomorrow.","vi":"Hãy đọc phiên bản sửa đổi trước cuộc họp ngày mai."}]','[]',NULL,'/rɪˈvaɪzd ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5273,'colloc-14-01',33,'rich source','nguồn dồi dào, phong phú','adj + n','[{"en":"Old newspapers are a rich source of historical information.","vi":"Những tờ báo cũ là một nguồn thông tin lịch sử phong phú."},{"en":"Vegetables are a rich source of vitamins and fiber.","vi":"Rau củ là một nguồn dồi dào vitamin và chất xơ."},{"en":"Interviews provided a rich source of data for the study.","vi":"Các cuộc phỏng vấn cung cấp một nguồn dữ liệu phong phú cho nghiên cứu."}]','[]',NULL,'/rɪtʃ sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5274,'colloc-14-01',34,'rising cost','chi phí tăng cao','adj + n','[{"en":"The rising cost of housing worries many young families.","vi":"Chi phí nhà ở tăng cao khiến nhiều gia đình trẻ lo lắng."},{"en":"Universities struggle with the rising cost of research equipment.","vi":"Các trường đại học chật vật với chi phí thiết bị nghiên cứu tăng cao."},{"en":"The rising cost of fuel affected the whole economy.","vi":"Chi phí nhiên liệu tăng cao ảnh hưởng đến toàn bộ nền kinh tế."}]','[]',NULL,'/ˈraɪzɪŋ kɔːst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5275,'colloc-14-01',35,'risk assessment','việc đánh giá rủi ro','n + n','[{"en":"A careful risk assessment was completed before the project began.","vi":"Một bản đánh giá rủi ro kỹ lưỡng đã hoàn thành trước khi dự án bắt đầu."},{"en":"Banks use risk assessment to decide whether to grant loans.","vi":"Ngân hàng dùng việc đánh giá rủi ro để quyết định cho vay hay không."},{"en":"The risk assessment identified several potential safety hazards.","vi":"Việc đánh giá rủi ro đã xác định một số nguy cơ an toàn tiềm ẩn."}]','[]',NULL,'/rɪsk əˈsesmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5276,'colloc-14-01',36,'roughly equal','gần như bằng nhau','adv + adj','[{"en":"The two groups were roughly equal in size and ability.","vi":"Hai nhóm gần như bằng nhau về quy mô và năng lực."},{"en":"Both candidates received a roughly equal share of votes.","vi":"Cả hai ứng viên nhận được số phiếu gần như bằng nhau."},{"en":"The costs and benefits turned out to be roughly equal.","vi":"Chi phí và lợi ích hóa ra gần như bằng nhau."}]','[]',NULL,'/ˈrʌfli ˈiːkwəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5277,'colloc-14-01',37,'roughly equivalent','gần như tương đương','adj + n','[{"en":"One mile is roughly equivalent to one point six kilometers.","vi":"Một dặm gần như tương đương với một phẩy sáu kilômét."},{"en":"His salary is roughly equivalent to the national average.","vi":"Lương của anh ấy gần như tương đương mức trung bình toàn quốc."},{"en":"The two degrees are roughly equivalent in academic value.","vi":"Hai tấm bằng gần như tương đương về giá trị học thuật."}]','[]',NULL,'/ˈrʌfli ɪˈkwɪvələnt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5278,'colloc-14-01',38,'ruling class','giai cấp thống trị','adj + n','[{"en":"The ruling class held most of the country''s wealth.","vi":"Giai cấp thống trị nắm giữ phần lớn của cải của đất nước."},{"en":"Historians study how the ruling class maintained its power.","vi":"Các nhà sử học nghiên cứu cách giai cấp thống trị duy trì quyền lực."},{"en":"The revolution aimed to overthrow the old ruling class.","vi":"Cuộc cách mạng nhằm lật đổ giai cấp thống trị cũ."}]','[]',NULL,'/ˈruːlɪŋ klæs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5279,'colloc-14-01',39,'ruling party','đảng cầm quyền','adj + n','[{"en":"The ruling party announced new economic reforms this week.","vi":"Đảng cầm quyền công bố các cải cách kinh tế mới trong tuần này."},{"en":"Voters seemed dissatisfied with the ruling party''s recent policies.","vi":"Cử tri có vẻ không hài lòng với các chính sách gần đây của đảng cầm quyền."},{"en":"The ruling party won a comfortable majority in parliament.","vi":"Đảng cầm quyền giành đa số ghế thoải mái trong quốc hội."}]','[]',NULL,'/ˈruːlɪŋ ˈpɑːrti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5280,'colloc-14-01',40,'rural area','khu vực nông thôn','adj + n','[{"en":"Many people in the rural area lack access to hospitals.","vi":"Nhiều người ở khu vực nông thôn thiếu khả năng tiếp cận bệnh viện."},{"en":"Internet connections remain slow in this remote rural area.","vi":"Kết nối internet vẫn còn chậm ở khu vực nông thôn xa xôi này."},{"en":"Young people often leave the rural area to find work.","vi":"Người trẻ thường rời khu vực nông thôn để tìm việc làm."}]','[]',NULL,'/ˈrʊrəl ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5281,'colloc-14-01',41,'rural community','cộng đồng nông thôn','adj + n','[{"en":"The rural community depends heavily on farming for income.","vi":"Cộng đồng nông thôn phụ thuộc nhiều vào nông nghiệp để kiếm thu nhập."},{"en":"New roads connected the rural community to nearby towns.","vi":"Những con đường mới nối cộng đồng nông thôn với các thị trấn gần đó."},{"en":"Researchers studied health needs in a small rural community.","vi":"Các nhà nghiên cứu khảo sát nhu cầu sức khỏe ở một cộng đồng nông thôn nhỏ."}]','[]',NULL,'/ˈrʊrəl kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5282,'colloc-14-01',42,'rural economy','kinh tế nông thôn','adj + n','[{"en":"The rural economy suffered after the factory closed down.","vi":"Kinh tế nông thôn bị ảnh hưởng sau khi nhà máy đóng cửa."},{"en":"Tourism has helped diversify the local rural economy.","vi":"Du lịch đã giúp đa dạng hóa nền kinh tế nông thôn địa phương."},{"en":"Government grants aim to strengthen the struggling rural economy.","vi":"Các khoản tài trợ của chính phủ nhằm củng cố nền kinh tế nông thôn đang khó khăn."}]','[]',NULL,'/ˈrʊrəl ɪˈkɑːnəmi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5283,'colloc-14-01',43,'rural population','dân số nông thôn','adj + n','[{"en":"The rural population has declined steadily over recent decades.","vi":"Dân số nông thôn đã giảm đều trong những thập kỷ gần đây."},{"en":"Most of the rural population works in agriculture.","vi":"Phần lớn dân số nông thôn làm việc trong lĩnh vực nông nghiệp."},{"en":"Health services struggle to reach the scattered rural population.","vi":"Các dịch vụ y tế khó tiếp cận được dân số nông thôn rải rác."}]','[]',NULL,'/ˈrʊrəl ˌpɑːpjəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5284,'colloc-14-01',44,'rural society','xã hội nông thôn','adj + n','[{"en":"Traditional values remain strong in this rural society.","vi":"Các giá trị truyền thống vẫn còn mạnh mẽ trong xã hội nông thôn này."},{"en":"Industrialization gradually transformed the old rural society.","vi":"Công nghiệp hóa dần dần biến đổi xã hội nông thôn cũ."},{"en":"Family ties play a central role in rural society.","vi":"Mối quan hệ gia đình đóng vai trò trung tâm trong xã hội nông thôn."}]','[]',NULL,'/ˈrʊrəl səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5285,'colloc-14-01',45,'safe sex','tình dục an toàn','adj + n','[{"en":"Health campaigns encourage young people to practice safe sex.","vi":"Các chiến dịch sức khỏe khuyến khích người trẻ thực hành tình dục an toàn."},{"en":"Teachers discussed safe sex during the health education class.","vi":"Giáo viên thảo luận về tình dục an toàn trong giờ giáo dục sức khỏe."},{"en":"Practicing safe sex helps prevent the spread of disease.","vi":"Thực hành tình dục an toàn giúp ngăn ngừa lây lan bệnh tật."}]','[]',NULL,'/seɪf seks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5286,'colloc-14-01',46,'salient characteristic','đặc điểm nổi bật','adj + n','[{"en":"Honesty is a salient characteristic of his leadership style.","vi":"Sự trung thực là một đặc điểm nổi bật trong phong cách lãnh đạo của anh ấy."},{"en":"The author describes the salient characteristic of each species.","vi":"Tác giả mô tả đặc điểm nổi bật của mỗi loài."},{"en":"Curiosity is a salient characteristic of successful researchers.","vi":"Tính tò mò là một đặc điểm nổi bật của các nhà nghiên cứu thành công."}]','[]',NULL,'/ˈseɪliənt ˌkerəktəˈrɪstɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5287,'colloc-14-01',47,'salient feature','đặc trưng nổi bật','adj + n','[{"en":"The report highlights the salient feature of each proposal.","vi":"Báo cáo nhấn mạnh đặc trưng nổi bật của mỗi đề xuất."},{"en":"A salient feature of the design is its simplicity.","vi":"Một đặc trưng nổi bật của thiết kế là sự đơn giản của nó."},{"en":"Students should identify the salient feature of the painting.","vi":"Học sinh nên xác định đặc trưng nổi bật của bức tranh."}]','[]',NULL,'/ˈseɪliənt ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5288,'colloc-14-01',48,'scarce resources','nguồn lực khan hiếm','adj + n','[{"en":"Managers must allocate scarce resources as efficiently as possible.","vi":"Người quản lý phải phân bổ các nguồn lực khan hiếm hiệu quả nhất có thể."},{"en":"Wars often break out over scarce resources like water.","vi":"Chiến tranh thường nổ ra vì các nguồn lực khan hiếm như nước."},{"en":"Economics studies how people use scarce resources wisely.","vi":"Kinh tế học nghiên cứu cách con người sử dụng nguồn lực khan hiếm một cách khôn ngoan."}]','[]',NULL,'/skers ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5289,'colloc-14-01',49,'schematic representation','biểu diễn dạng sơ đồ','adj + n','[{"en":"The diagram offers a schematic representation of the process.","vi":"Sơ đồ cung cấp một biểu diễn dạng sơ đồ của quá trình."},{"en":"A schematic representation helps readers grasp complex relationships quickly.","vi":"Biểu diễn dạng sơ đồ giúp người đọc nắm bắt các mối quan hệ phức tạp nhanh chóng."},{"en":"The textbook includes a schematic representation of the human heart.","vi":"Giáo trình có một biểu diễn dạng sơ đồ của tim người."}]','[]',NULL,'/skɪˈmætɪk ˌreprɪzenˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5290,'colloc-14-01',50,'scholarly journal','tạp chí học thuật','adj + n','[{"en":"Her article appeared in a respected scholarly journal last year.","vi":"Bài viết của cô ấy xuất hiện trên một tạp chí học thuật uy tín năm ngoái."},{"en":"A scholarly journal usually requires peer review before publication.","vi":"Một tạp chí học thuật thường yêu cầu phản biện trước khi xuất bản."},{"en":"Students should cite a scholarly journal rather than a blog.","vi":"Sinh viên nên trích dẫn tạp chí học thuật thay vì một blog."}]','[]',NULL,'/ˈskɑːlərli ˈdʒɜːrnəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5291,'colloc-14-01',51,'scholarly literature','tài liệu học thuật','adj + n','[{"en":"The thesis reviews recent scholarly literature on the topic.","vi":"Luận văn tổng quan tài liệu học thuật gần đây về chủ đề này."},{"en":"Much scholarly literature supports this particular interpretation.","vi":"Nhiều tài liệu học thuật ủng hộ cách diễn giải cụ thể này."},{"en":"Searching scholarly literature is the first step in research.","vi":"Tìm kiếm tài liệu học thuật là bước đầu tiên trong nghiên cứu."}]','[]',NULL,'/ˈskɑːlərli ˈlɪtərətʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5292,'colloc-14-01',52,'scholarly research','nghiên cứu học thuật','adj + n','[{"en":"Years of scholarly research went into writing this book.","vi":"Nhiều năm nghiên cứu học thuật đã được dành để viết cuốn sách này."},{"en":"Scholarly research must follow strict ethical and methodological standards.","vi":"Nghiên cứu học thuật phải tuân theo các chuẩn mực đạo đức và phương pháp nghiêm ngặt."},{"en":"The library supports scholarly research with extensive online databases.","vi":"Thư viện hỗ trợ nghiên cứu học thuật bằng các cơ sở dữ liệu trực tuyến phong phú."}]','[]',NULL,'/ˈskɑːlərli ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5293,'colloc-14-01',53,'scholarly work','công trình học thuật','adj + n','[{"en":"Her scholarly work has influenced many younger researchers.","vi":"Công trình học thuật của bà đã ảnh hưởng đến nhiều nhà nghiên cứu trẻ hơn."},{"en":"This scholarly work is widely cited across several disciplines.","vi":"Công trình học thuật này được trích dẫn rộng rãi trong nhiều ngành."},{"en":"Producing serious scholarly work requires patience and discipline.","vi":"Tạo ra công trình học thuật nghiêm túc đòi hỏi sự kiên nhẫn và kỷ luật."}]','[]',NULL,'/ˈskɑːlərli wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5294,'colloc-14-01',54,'scientific community','cộng đồng khoa học','adj + n','[{"en":"The discovery surprised much of the scientific community.","vi":"Phát hiện này khiến phần lớn cộng đồng khoa học ngạc nhiên."},{"en":"The scientific community generally accepts the theory of evolution.","vi":"Cộng đồng khoa học nhìn chung chấp nhận thuyết tiến hóa."},{"en":"Her findings were quickly shared with the scientific community.","vi":"Các phát hiện của cô ấy nhanh chóng được chia sẻ với cộng đồng khoa học."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5295,'colloc-14-01',55,'scientific discourse','diễn ngôn khoa học','adj + n','[{"en":"Scientific discourse relies on clear evidence and logical argument.","vi":"Diễn ngôn khoa học dựa trên bằng chứng rõ ràng và lập luận logic."},{"en":"The journal contributes to ongoing scientific discourse about the climate.","vi":"Tạp chí đóng góp vào diễn ngôn khoa học đang diễn ra về khí hậu."},{"en":"Precise terminology is essential in formal scientific discourse.","vi":"Thuật ngữ chính xác là điều thiết yếu trong diễn ngôn khoa học chính thức."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk ˈdɪskɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5296,'colloc-14-01',56,'scientific evidence','bằng chứng khoa học','adj + n','[{"en":"There is strong scientific evidence linking smoking to cancer.","vi":"Có bằng chứng khoa học mạnh mẽ liên kết hút thuốc với ung thư."},{"en":"Policy decisions should be based on solid scientific evidence.","vi":"Các quyết định chính sách nên dựa trên bằng chứng khoa học vững chắc."},{"en":"The claim lacks any reliable scientific evidence to support it.","vi":"Khẳng định này thiếu bất kỳ bằng chứng khoa học đáng tin cậy nào để hỗ trợ."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5297,'colloc-14-01',57,'scientific investigation','cuộc điều tra khoa học','adj + n','[{"en":"A careful scientific investigation revealed the cause of the outbreak.","vi":"Một cuộc điều tra khoa học kỹ lưỡng đã làm rõ nguyên nhân của đợt bùng phát."},{"en":"Scientific investigation begins with a clear, testable question.","vi":"Điều tra khoa học bắt đầu bằng một câu hỏi rõ ràng, có thể kiểm chứng."},{"en":"The accident prompted a thorough scientific investigation by experts.","vi":"Vụ tai nạn đã thúc đẩy một cuộc điều tra khoa học kỹ lưỡng bởi các chuyên gia."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk ɪnˌvestɪˈɡeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5298,'colloc-14-01',58,'scientific method','phương pháp khoa học','adj + n','[{"en":"The scientific method involves observation, hypothesis, and careful testing.","vi":"Phương pháp khoa học bao gồm quan sát, giả thuyết và kiểm chứng cẩn thận."},{"en":"Students learn the scientific method early in their education.","vi":"Học sinh học phương pháp khoa học sớm trong quá trình học tập."},{"en":"Applying the scientific method reduces bias in research results.","vi":"Áp dụng phương pháp khoa học làm giảm thiên kiến trong kết quả nghiên cứu."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5299,'colloc-14-01',59,'scientific objectivity','tính khách quan khoa học','adj + n','[{"en":"Scientific objectivity requires researchers to set aside personal beliefs.","vi":"Tính khách quan khoa học đòi hỏi nhà nghiên cứu gạt bỏ niềm tin cá nhân."},{"en":"Critics questioned the scientific objectivity of the funded study.","vi":"Các nhà phê bình nghi ngờ tính khách quan khoa học của nghiên cứu được tài trợ."},{"en":"Maintaining scientific objectivity is difficult when emotions run high.","vi":"Duy trì tính khách quan khoa học rất khó khi cảm xúc dâng cao."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk ˌɑːbdʒekˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5300,'colloc-14-01',60,'scientific research','nghiên cứu khoa học','adj + n','[{"en":"The government invests heavily in scientific research each year.","vi":"Chính phủ đầu tư mạnh vào nghiên cứu khoa học mỗi năm."},{"en":"Scientific research often takes years to produce useful results.","vi":"Nghiên cứu khoa học thường mất nhiều năm để tạo ra kết quả hữu ích."},{"en":"New technology has greatly accelerated modern scientific research.","vi":"Công nghệ mới đã đẩy nhanh đáng kể nghiên cứu khoa học hiện đại."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5301,'colloc-14-01',61,'scientific theory','lý thuyết khoa học','adj + n','[{"en":"A scientific theory must be supported by repeated experiments.","vi":"Một lý thuyết khoa học phải được hỗ trợ bởi các thí nghiệm lặp lại."},{"en":"The professor explained the scientific theory behind black holes.","vi":"Giáo sư giải thích lý thuyết khoa học đằng sau hố đen."},{"en":"New evidence can sometimes overturn an accepted scientific theory.","vi":"Bằng chứng mới đôi khi có thể lật đổ một lý thuyết khoa học đã được chấp nhận."}]','[]',NULL,'/ˌsaɪənˈtɪfɪk ˈθiːəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5302,'colloc-14-01',62,'secondary data','dữ liệu thứ cấp','adj + n','[{"en":"The study used secondary data collected by another team.","vi":"Nghiên cứu sử dụng dữ liệu thứ cấp do một nhóm khác thu thập."},{"en":"Analyzing secondary data saved the researchers considerable time.","vi":"Phân tích dữ liệu thứ cấp giúp các nhà nghiên cứu tiết kiệm nhiều thời gian."},{"en":"Secondary data may not perfectly match a new research question.","vi":"Dữ liệu thứ cấp có thể không hoàn toàn phù hợp với câu hỏi nghiên cứu mới."}]','[]',NULL,'/ˈsekənderi ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5303,'colloc-14-01',63,'secondary education','giáo dục trung học','adj + n','[{"en":"Most students complete secondary education before entering university.","vi":"Hầu hết học sinh hoàn thành giáo dục trung học trước khi vào đại học."},{"en":"The reform improved the quality of secondary education nationwide.","vi":"Cuộc cải cách đã nâng cao chất lượng giáo dục trung học trên cả nước."},{"en":"Access to secondary education remains limited in some regions.","vi":"Khả năng tiếp cận giáo dục trung học vẫn còn hạn chế ở một số vùng."}]','[]',NULL,'/ˈsekənderi ˌedʒəˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5304,'colloc-14-01',64,'secondary source','nguồn thứ cấp','adj + n','[{"en":"A textbook is considered a secondary source, not original research.","vi":"Sách giáo khoa được coi là nguồn thứ cấp, không phải nghiên cứu gốc."},{"en":"Historians compare a secondary source with original documents carefully.","vi":"Các nhà sử học so sánh nguồn thứ cấp với tài liệu gốc một cách cẩn thận."},{"en":"Relying only on a secondary source can introduce errors.","vi":"Chỉ dựa vào một nguồn thứ cấp có thể gây ra sai sót."}]','[]',NULL,'/ˈsekənderi sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5305,'colloc-14-01',65,'security policy','chính sách an ninh','n + n','[{"en":"The company updated its security policy after the data breach.","vi":"Công ty đã cập nhật chính sách an ninh sau vụ rò rỉ dữ liệu."},{"en":"A clear security policy protects both staff and customers.","vi":"Một chính sách an ninh rõ ràng bảo vệ cả nhân viên lẫn khách hàng."},{"en":"The government debated changes to its national security policy.","vi":"Chính phủ tranh luận về những thay đổi trong chính sách an ninh quốc gia."}]','[]',NULL,'/sɪˈkjʊrəti ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5306,'colloc-14-01',66,'seek help','tìm kiếm sự giúp đỡ','v + n','[{"en":"Students are encouraged to seek help when they struggle.","vi":"Học sinh được khuyến khích tìm kiếm sự giúp đỡ khi gặp khó khăn."},{"en":"Many people hesitate to seek help for mental health.","vi":"Nhiều người ngần ngại tìm kiếm sự giúp đỡ cho sức khỏe tâm thần."},{"en":"If symptoms worsen, you should seek help immediately.","vi":"Nếu triệu chứng trở nặng, bạn nên tìm kiếm sự giúp đỡ ngay lập tức."}]','[]',NULL,'/siːk help/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5307,'colloc-14-01',67,'seek information','tìm kiếm thông tin','v + n','[{"en":"Patients increasingly seek information about treatments online.","vi":"Bệnh nhân ngày càng tìm kiếm thông tin về phương pháp điều trị trên mạng."},{"en":"Reporters seek information from multiple sources before publishing.","vi":"Phóng viên tìm kiếm thông tin từ nhiều nguồn trước khi đăng bài."},{"en":"Consumers seek information before making expensive purchasing decisions.","vi":"Người tiêu dùng tìm kiếm thông tin trước khi đưa ra quyết định mua sắm đắt đỏ."}]','[]',NULL,'/siːk ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5308,'colloc-14-01',68,'seem appropriate','có vẻ phù hợp','v + adj','[{"en":"This method does not seem appropriate for such young children.","vi":"Phương pháp này có vẻ không phù hợp với trẻ nhỏ như vậy."},{"en":"A formal tone would seem appropriate for this report.","vi":"Một giọng điệu trang trọng có vẻ phù hợp cho báo cáo này."},{"en":"Choose whatever measures seem appropriate to the situation.","vi":"Hãy chọn bất kỳ biện pháp nào có vẻ phù hợp với tình huống."}]','[]',NULL,'/siːm əˈproʊpriət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5309,'colloc-14-01',69,'seem obvious','có vẻ hiển nhiên','v + adj','[{"en":"The answer may seem obvious, but it is actually complex.","vi":"Câu trả lời có vẻ hiển nhiên, nhưng thực ra lại phức tạp."},{"en":"Some solutions seem obvious only after careful analysis.","vi":"Một số giải pháp chỉ có vẻ hiển nhiên sau khi phân tích kỹ lưỡng."},{"en":"What seems obvious to experts can confuse beginners completely.","vi":"Điều có vẻ hiển nhiên với chuyên gia có thể làm người mới hoàn toàn bối rối."}]','[]',NULL,'/siːm ˈɑːbviəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5310,'colloc-14-01',70,'seem plausible','có vẻ hợp lý','v + adj','[{"en":"His explanation does seem plausible given the available evidence.","vi":"Lời giải thích của anh ấy có vẻ hợp lý dựa trên bằng chứng hiện có."},{"en":"Several theories seem plausible, so further research is needed.","vi":"Một số lý thuyết có vẻ hợp lý, vì vậy cần nghiên cứu thêm."},{"en":"The argument may seem plausible but lacks solid support.","vi":"Lập luận có vẻ hợp lý nhưng thiếu sự hỗ trợ vững chắc."}]','[]',NULL,'/siːm ˈplɔːzəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5311,'colloc-14-01',71,'seem unlikely','có vẻ khó xảy ra','v + adj','[{"en":"A quick recovery now seems unlikely given the circumstances.","vi":"Một sự hồi phục nhanh chóng giờ đây có vẻ khó xảy ra trong hoàn cảnh này."},{"en":"It seems unlikely that the project will finish on time.","vi":"Có vẻ khó xảy ra việc dự án sẽ hoàn thành đúng hạn."},{"en":"Such an extreme outcome seems unlikely under normal conditions.","vi":"Một kết quả cực đoan như vậy có vẻ khó xảy ra trong điều kiện bình thường."}]','[]',NULL,'/siːm ʌnˈlaɪkli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5312,'colloc-14-01',72,'seminal study','nghiên cứu mang tính nền tảng','adj + n','[{"en":"This seminal study shaped the entire field for decades.","vi":"Nghiên cứu nền tảng này đã định hình cả lĩnh vực trong nhiều thập kỷ."},{"en":"Researchers still cite that seminal study in their papers.","vi":"Các nhà nghiên cứu vẫn trích dẫn nghiên cứu nền tảng đó trong bài viết của họ."},{"en":"Her seminal study introduced a completely new methodology.","vi":"Nghiên cứu nền tảng của bà đã giới thiệu một phương pháp hoàn toàn mới."}]','[]',NULL,'/ˈseminəl ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5313,'colloc-14-01',73,'seminal work','công trình mang tính nền tảng','adj + n','[{"en":"Darwin''s seminal work transformed how we understand life.","vi":"Công trình nền tảng của Darwin đã thay đổi cách chúng ta hiểu về sự sống."},{"en":"The seminal work remains essential reading for new students.","vi":"Công trình nền tảng này vẫn là tài liệu đọc thiết yếu cho sinh viên mới."},{"en":"Many later theories build upon that seminal work.","vi":"Nhiều lý thuyết về sau được xây dựng dựa trên công trình nền tảng đó."}]','[]',NULL,'/ˈseminəl wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5314,'colloc-14-01',74,'senior management','ban quản lý cấp cao','adj + n','[{"en":"Senior management approved the new strategy after long discussions.","vi":"Ban quản lý cấp cao đã phê duyệt chiến lược mới sau các cuộc thảo luận dài."},{"en":"The report goes directly to senior management each quarter.","vi":"Báo cáo được gửi thẳng đến ban quản lý cấp cao mỗi quý."},{"en":"Senior management is responsible for setting the company''s direction.","vi":"Ban quản lý cấp cao chịu trách nhiệm định hướng cho công ty."}]','[]',NULL,'/ˈsiːnjər ˈmænɪdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5315,'colloc-14-01',75,'separate entity','thực thể riêng biệt','adj + n','[{"en":"Legally, the company is a separate entity from its owners.","vi":"Về mặt pháp lý, công ty là một thực thể riêng biệt với chủ sở hữu."},{"en":"Each subsidiary operates as a separate entity with its own budget.","vi":"Mỗi công ty con hoạt động như một thực thể riêng biệt với ngân sách riêng."},{"en":"The mind and body are sometimes treated as separate entities.","vi":"Tâm trí và cơ thể đôi khi được xem như những thực thể riêng biệt."}]','[]',NULL,'/ˈsepərət ˈentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5316,'colloc-14-01',76,'serious challenge','thách thức nghiêm trọng','adj + n','[{"en":"Climate change poses a serious challenge to future generations.","vi":"Biến đổi khí hậu đặt ra một thách thức nghiêm trọng cho các thế hệ tương lai."},{"en":"Funding cuts present a serious challenge for the hospital.","vi":"Việc cắt giảm ngân sách là một thách thức nghiêm trọng cho bệnh viện."},{"en":"The new policy faced a serious challenge in court.","vi":"Chính sách mới đối mặt với một thách thức nghiêm trọng tại tòa án."}]','[]',NULL,'/ˈsɪriəs ˈtʃælɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5317,'colloc-14-01',77,'serious consequences','hậu quả nghiêm trọng','adj + n','[{"en":"Ignoring safety rules can lead to serious consequences.","vi":"Phớt lờ các quy tắc an toàn có thể dẫn đến hậu quả nghiêm trọng."},{"en":"The decision had serious consequences for the local economy.","vi":"Quyết định này gây ra hậu quả nghiêm trọng cho nền kinh tế địa phương."},{"en":"Failing to act now may bring serious consequences later.","vi":"Không hành động ngay bây giờ có thể mang lại hậu quả nghiêm trọng về sau."}]','[]',NULL,'/ˈsɪriəs ˈkɑːnsəkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5318,'colloc-14-01',78,'serious offence','tội nghiêm trọng','adj + n','[{"en":"Fraud is a serious offence punishable by imprisonment.","vi":"Gian lận là một tội nghiêm trọng có thể bị phạt tù."},{"en":"Cheating in exams is treated as a serious offence.","vi":"Gian lận trong thi cử được xem là một tội nghiêm trọng."},{"en":"He was charged with a serious offence against public safety.","vi":"Anh ta bị buộc tội một tội nghiêm trọng chống lại an toàn công cộng."}]','[]',NULL,'/ˈsɪriəs əˈfens/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5319,'colloc-14-01',79,'serve a function','phục vụ một chức năng','v + n','[{"en":"Even small details serve a function in the overall design.","vi":"Ngay cả chi tiết nhỏ cũng phục vụ một chức năng trong tổng thể thiết kế."},{"en":"Rituals serve a function in holding communities together.","vi":"Các nghi lễ phục vụ một chức năng trong việc gắn kết cộng đồng."},{"en":"Each part of the cell serves a specific function.","vi":"Mỗi phần của tế bào phục vụ một chức năng cụ thể."}]','[]',NULL,'/sɜːrv ə ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5320,'colloc-14-01',80,'service sector','khu vực dịch vụ','n + n','[{"en":"The service sector now employs most of the workforce.","vi":"Khu vực dịch vụ hiện sử dụng phần lớn lực lượng lao động."},{"en":"Tourism is a major part of the country''s service sector.","vi":"Du lịch là một phần lớn của khu vực dịch vụ của đất nước."},{"en":"Automation is gradually changing jobs in the service sector.","vi":"Tự động hóa đang dần thay đổi các công việc trong khu vực dịch vụ."}]','[]',NULL,'/ˈsɜːrvɪs ˈsektər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5321,'colloc-14-01',81,'set a goal','đặt ra một mục tiêu','v + n','[{"en":"It helps to set a goal before starting any project.","vi":"Việc đặt ra một mục tiêu trước khi bắt đầu dự án rất hữu ích."},{"en":"The coach asked each player to set a personal goal.","vi":"Huấn luyện viên yêu cầu mỗi cầu thủ đặt ra một mục tiêu cá nhân."},{"en":"Companies set a goal to reduce emissions by half.","vi":"Các công ty đặt ra mục tiêu giảm một nửa lượng khí thải."}]','[]',NULL,'/set ə ɡoʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5322,'colloc-14-01',82,'set a target','đặt ra một chỉ tiêu','v + n','[{"en":"The government set a target to plant a million trees.","vi":"Chính phủ đặt ra chỉ tiêu trồng một triệu cây xanh."},{"en":"Managers set a target for monthly sales each quarter.","vi":"Người quản lý đặt ra chỉ tiêu doanh số hàng tháng mỗi quý."},{"en":"It is wise to set a target that is realistic.","vi":"Đặt ra một chỉ tiêu thực tế là điều khôn ngoan."}]','[]',NULL,'/set ə ˈtɑːrɡət/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5323,'colloc-14-01',83,'set an objective','đặt ra một mục tiêu','v + n','[{"en":"Teachers set an objective for every lesson they plan.","vi":"Giáo viên đặt ra một mục tiêu cho mỗi bài học họ chuẩn bị."},{"en":"The team set an objective to launch the product early.","vi":"Nhóm đặt ra mục tiêu ra mắt sản phẩm sớm."},{"en":"Before research, you should set an objective clearly.","vi":"Trước khi nghiên cứu, bạn nên đặt ra một mục tiêu rõ ràng."}]','[]',NULL,'/set ən əbˈdʒektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5324,'colloc-14-01',84,'set the agenda','định ra chương trình nghị sự','v + n','[{"en":"The chairperson will set the agenda for tomorrow''s meeting.","vi":"Chủ tọa sẽ định ra chương trình nghị sự cho cuộc họp ngày mai."},{"en":"Powerful media outlets often set the agenda for public debate.","vi":"Các hãng truyền thông lớn thường định ra chương trình nghị sự cho tranh luận công chúng."},{"en":"Activists tried to set the agenda on environmental issues.","vi":"Các nhà hoạt động cố gắng định ra chương trình nghị sự về các vấn đề môi trường."}]','[]',NULL,'/set ði əˈdʒendə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5325,'colloc-14-01',85,'set the parameters','thiết lập các thông số','v + n','[{"en":"The professor set the parameters for the final assignment clearly.","vi":"Giáo sư thiết lập rõ ràng các thông số cho bài tập cuối kỳ."},{"en":"We must set the parameters before running the experiment.","vi":"Chúng ta phải thiết lập các thông số trước khi tiến hành thí nghiệm."},{"en":"The contract sets the parameters within which both parties operate.","vi":"Hợp đồng thiết lập các thông số mà cả hai bên hoạt động trong đó."}]','[]',NULL,'/set ðə pəˈræmətərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5326,'colloc-14-01',86,'severely affect','ảnh hưởng nghiêm trọng','adv + v','[{"en":"The drought severely affected crops across the entire region.","vi":"Hạn hán đã ảnh hưởng nghiêm trọng đến mùa màng trên toàn khu vực."},{"en":"Pollution can severely affect the health of local residents.","vi":"Ô nhiễm có thể ảnh hưởng nghiêm trọng đến sức khỏe của cư dân địa phương."},{"en":"The strike severely affected public transport for several days.","vi":"Cuộc đình công đã ảnh hưởng nghiêm trọng đến giao thông công cộng trong vài ngày."}]','[]',NULL,'/səˈvɪrli əˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5327,'colloc-14-01',87,'sexual abuse','lạm dụng tình dục','adj + n','[{"en":"The charity supports survivors of childhood sexual abuse.","vi":"Tổ chức từ thiện hỗ trợ những người sống sót sau lạm dụng tình dục thời thơ ấu."},{"en":"Schools must report any suspected case of sexual abuse.","vi":"Trường học phải báo cáo bất kỳ trường hợp nghi ngờ lạm dụng tình dục nào."},{"en":"New laws aim to prevent sexual abuse and protect victims.","vi":"Luật mới nhằm ngăn chặn lạm dụng tình dục và bảo vệ nạn nhân."}]','[]',NULL,'/ˈsekʃuəl əˈbjuːs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5328,'colloc-14-01',88,'sexual act','hành vi tình dục','adj + n','[{"en":"The law clearly defines what counts as a sexual act.","vi":"Luật pháp định nghĩa rõ ràng điều gì được coi là một hành vi tình dục."},{"en":"Consent must be present for any sexual act to be legal.","vi":"Phải có sự đồng thuận thì một hành vi tình dục mới hợp pháp."},{"en":"Researchers studied attitudes toward depicting a sexual act in media.","vi":"Các nhà nghiên cứu khảo sát thái độ đối với việc mô tả hành vi tình dục trên truyền thông."}]','[]',NULL,'/ˈsekʃuəl ækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5329,'colloc-14-01',89,'sexual behavior','hành vi tình dục','adj + n','[{"en":"The survey examined the sexual behavior of young adults.","vi":"Cuộc khảo sát xem xét hành vi tình dục của thanh niên."},{"en":"Culture strongly influences attitudes toward sexual behavior.","vi":"Văn hóa ảnh hưởng mạnh đến thái độ đối với hành vi tình dục."},{"en":"Education can promote safer and more responsible sexual behavior.","vi":"Giáo dục có thể thúc đẩy hành vi tình dục an toàn và có trách nhiệm hơn."}]','[]',NULL,'/ˈsekʃuəl bɪˈheɪvjər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5330,'colloc-14-01',90,'sexual contact','tiếp xúc tình dục','adj + n','[{"en":"Some infections spread mainly through sexual contact.","vi":"Một số bệnh nhiễm trùng lây lan chủ yếu qua tiếp xúc tình dục."},{"en":"The study tracked rates of unprotected sexual contact.","vi":"Nghiên cứu theo dõi tỷ lệ tiếp xúc tình dục không được bảo vệ."},{"en":"Health classes explain how sexual contact can transmit disease.","vi":"Các lớp sức khỏe giải thích cách tiếp xúc tình dục có thể truyền bệnh."}]','[]',NULL,'/ˈsekʃuəl ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5331,'colloc-14-01',91,'sexual difference','sự khác biệt giới tính','adj + n','[{"en":"The book explores how culture interprets sexual difference.","vi":"Cuốn sách khám phá cách văn hóa diễn giải sự khác biệt giới tính."},{"en":"Biologists describe the sexual difference between the two species.","vi":"Các nhà sinh học mô tả sự khác biệt giới tính giữa hai loài."},{"en":"Feminist theory often questions assumptions about sexual difference.","vi":"Lý thuyết nữ quyền thường chất vấn các giả định về sự khác biệt giới tính."}]','[]',NULL,'/ˈsekʃuəl ˈdɪfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5332,'colloc-14-01',92,'sexual exploitation','bóc lột tình dục','adj + n','[{"en":"The organization fights against the sexual exploitation of children.","vi":"Tổ chức đấu tranh chống lại nạn bóc lột tình dục trẻ em."},{"en":"Trafficking often leads to forced labor and sexual exploitation.","vi":"Buôn người thường dẫn đến lao động cưỡng bức và bóc lột tình dục."},{"en":"Stronger laws are needed to prevent sexual exploitation online.","vi":"Cần có luật mạnh hơn để ngăn chặn bóc lột tình dục trên mạng."}]','[]',NULL,'/ˈsekʃuəl ˌeksplɔɪˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5333,'colloc-14-01',93,'sexual identity','bản dạng giới tính','adj + n','[{"en":"Many teenagers explore their sexual identity during adolescence.","vi":"Nhiều thiếu niên khám phá bản dạng giới tính của mình trong tuổi vị thành niên."},{"en":"The film portrays a young woman''s struggle with sexual identity.","vi":"Bộ phim khắc họa cuộc đấu tranh của một cô gái với bản dạng giới tính."},{"en":"Society is slowly becoming more accepting of diverse sexual identity.","vi":"Xã hội đang dần trở nên cởi mở hơn với bản dạng giới tính đa dạng."}]','[]',NULL,'/ˈsekʃuəl aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5334,'colloc-14-01',94,'sexual intercourse','quan hệ tình dục','adj + n','[{"en":"The study examined attitudes toward sexual intercourse among teenagers.","vi":"Nghiên cứu xem xét thái độ đối với quan hệ tình dục ở thanh thiếu niên."},{"en":"Doctors advised waiting before resuming sexual intercourse after surgery.","vi":"Bác sĩ khuyên nên chờ trước khi quan hệ tình dục trở lại sau phẫu thuật."},{"en":"Some diseases are transmitted through unprotected sexual intercourse.","vi":"Một số bệnh lây truyền qua quan hệ tình dục không được bảo vệ."}]','[]',NULL,'/ˈsekʃuəl ˈɪntərkɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5335,'colloc-14-01',95,'sexual orientation','khuynh hướng tính dục','adj + n','[{"en":"The law protects employees from discrimination based on sexual orientation.","vi":"Luật bảo vệ nhân viên khỏi phân biệt đối xử dựa trên khuynh hướng tính dục."},{"en":"People should not be judged by their sexual orientation.","vi":"Người ta không nên bị đánh giá qua khuynh hướng tính dục của họ."},{"en":"The survey asked participants about their sexual orientation anonymously.","vi":"Cuộc khảo sát hỏi người tham gia về khuynh hướng tính dục một cách ẩn danh."}]','[]',NULL,'/ˈsekʃuəl ˌɔːriənˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5336,'colloc-14-01',96,'sexual violence','bạo lực tình dục','adj + n','[{"en":"Survivors of sexual violence often need long-term support.","vi":"Những người sống sót sau bạo lực tình dục thường cần hỗ trợ lâu dài."},{"en":"The campaign raises awareness about sexual violence on campus.","vi":"Chiến dịch nâng cao nhận thức về bạo lực tình dục trong khuôn viên trường."},{"en":"Conflict zones often see high rates of sexual violence.","vi":"Các vùng xung đột thường có tỷ lệ bạo lực tình dục cao."}]','[]',NULL,'/ˈsekʃuəl ˈvaɪələns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5337,'colloc-14-01',97,'share information','chia sẻ thông tin','v + n','[{"en":"The two agencies agreed to share information about the threat.","vi":"Hai cơ quan đồng ý chia sẻ thông tin về mối đe dọa."},{"en":"Researchers should share information openly to advance science.","vi":"Các nhà nghiên cứu nên chia sẻ thông tin một cách cởi mở để thúc đẩy khoa học."},{"en":"Employees are reminded not to share information with competitors.","vi":"Nhân viên được nhắc nhở không chia sẻ thông tin với đối thủ cạnh tranh."}]','[]',NULL,'/ʃer ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5338,'colloc-14-01',98,'shared experience','trải nghiệm chung','adj + n','[{"en":"A shared experience can quickly bring strangers closer together.","vi":"Một trải nghiệm chung có thể nhanh chóng gắn kết những người xa lạ."},{"en":"The trip became a meaningful shared experience for the class.","vi":"Chuyến đi trở thành một trải nghiệm chung ý nghĩa cho cả lớp."},{"en":"Language often grows out of shared experience within a community.","vi":"Ngôn ngữ thường nảy sinh từ trải nghiệm chung trong một cộng đồng."}]','[]',NULL,'/ʃerd ɪkˈspɪriəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5339,'colloc-14-01',99,'shared meaning','ý nghĩa chung','adj + n','[{"en":"Communication depends on a shared meaning between speakers.","vi":"Giao tiếp phụ thuộc vào ý nghĩa chung giữa những người nói."},{"en":"Symbols carry a shared meaning understood across the culture.","vi":"Các biểu tượng mang ý nghĩa chung được hiểu trong cả nền văn hóa."},{"en":"Teams work better when they build a shared meaning of success.","vi":"Các nhóm làm việc tốt hơn khi họ xây dựng ý nghĩa chung về thành công."}]','[]',NULL,'/ʃerd ˈmiːnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5340,'colloc-14-01',100,'shared values','các giá trị chung','adj + n','[{"en":"Strong communities are usually built on shared values.","vi":"Các cộng đồng vững mạnh thường được xây dựng trên các giá trị chung."},{"en":"The partners discovered they had many shared values in common.","vi":"Các đối tác phát hiện họ có nhiều giá trị chung."},{"en":"Shared values help an organization stay united under pressure.","vi":"Các giá trị chung giúp một tổ chức đoàn kết dưới áp lực."}]','[]',NULL,'/ʃerd ˈvæljuːz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5341,'colloc-14-01',101,'sharp contrast','sự tương phản rõ rệt','adj + n','[{"en":"There is a sharp contrast between rich and poor neighborhoods.","vi":"Có một sự tương phản rõ rệt giữa các khu giàu và nghèo."},{"en":"Her calm tone stood in sharp contrast to the chaos.","vi":"Giọng điệu bình tĩnh của cô tương phản rõ rệt với sự hỗn loạn."},{"en":"The results show a sharp contrast with earlier findings.","vi":"Kết quả cho thấy sự tương phản rõ rệt với các phát hiện trước đây."}]','[]',NULL,'/ʃɑːrp ˈkɑːntræst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5342,'colloc-14-01',102,'sharp distinction','sự phân biệt rạch ròi','adj + n','[{"en":"The author draws a sharp distinction between fact and opinion.","vi":"Tác giả vạch ra một sự phân biệt rạch ròi giữa sự thật và ý kiến."},{"en":"There is no sharp distinction between the two categories.","vi":"Không có sự phân biệt rạch ròi nào giữa hai loại."},{"en":"Philosophers debate whether such a sharp distinction really exists.","vi":"Các nhà triết học tranh luận liệu một sự phân biệt rạch ròi như vậy có thực sự tồn tại."}]','[]',NULL,'/ʃɑːrp dɪˈstɪŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5343,'colloc-14-01',103,'shift emphasis','chuyển trọng tâm','v + n','[{"en":"The new policy shifts emphasis from punishment to prevention.","vi":"Chính sách mới chuyển trọng tâm từ trừng phạt sang phòng ngừa."},{"en":"Schools increasingly shift emphasis toward practical, hands-on learning.","vi":"Các trường học ngày càng chuyển trọng tâm sang học thực hành."},{"en":"The author shifts emphasis to social rather than economic factors.","vi":"Tác giả chuyển trọng tâm sang các yếu tố xã hội thay vì kinh tế."}]','[]',NULL,'/ʃɪft ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5344,'colloc-14-01',104,'short duration','thời gian ngắn','adj + n','[{"en":"The treatment is effective despite its short duration.","vi":"Phương pháp điều trị hiệu quả dù chỉ kéo dài trong thời gian ngắn."},{"en":"Symptoms of short duration usually require no medication.","vi":"Các triệu chứng kéo dài thời gian ngắn thường không cần thuốc."},{"en":"Because of its short duration, the course covered only basics.","vi":"Vì thời gian ngắn, khóa học chỉ bao quát những kiến thức cơ bản."}]','[]',NULL,'/ʃɔːrt dʊˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5345,'colloc-14-01',105,'short period','khoảng thời gian ngắn','adj + n','[{"en":"Prices rose sharply over a remarkably short period.","vi":"Giá cả tăng mạnh trong một khoảng thời gian ngắn đáng kể."},{"en":"In a short period, the company doubled its revenue.","vi":"Trong một khoảng thời gian ngắn, công ty đã tăng gấp đôi doanh thu."},{"en":"The experiment was repeated several times within a short period.","vi":"Thí nghiệm được lặp lại nhiều lần trong một khoảng thời gian ngắn."}]','[]',NULL,'/ʃɔːrt ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5346,'colloc-14-01',106,'show evidence','cho thấy bằng chứng','v + n','[{"en":"The fossils show evidence of life millions of years ago.","vi":"Các hóa thạch cho thấy bằng chứng về sự sống hàng triệu năm trước."},{"en":"Patients began to show evidence of improvement after treatment.","vi":"Bệnh nhân bắt đầu cho thấy bằng chứng cải thiện sau khi điều trị."},{"en":"The data show evidence of a clear upward trend.","vi":"Dữ liệu cho thấy bằng chứng về một xu hướng đi lên rõ ràng."}]','[]',NULL,'/ʃoʊ ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5347,'colloc-14-01',107,'show variation','thể hiện sự biến thiên','v + n','[{"en":"Temperatures show variation between the coast and the mountains.","vi":"Nhiệt độ thể hiện sự biến thiên giữa vùng ven biển và vùng núi."},{"en":"The samples show variation in size, color, and shape.","vi":"Các mẫu thể hiện sự biến thiên về kích thước, màu sắc và hình dạng."},{"en":"Test scores show variation depending on the time of day.","vi":"Điểm kiểm tra thể hiện sự biến thiên tùy theo thời điểm trong ngày."}]','[]',NULL,'/ʃoʊ ˌveriˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5348,'colloc-14-01',108,'show a tendency','thể hiện một xu hướng','v + n','[{"en":"Young children show a tendency to imitate adults around them.","vi":"Trẻ nhỏ thể hiện xu hướng bắt chước người lớn xung quanh."},{"en":"The market shows a tendency to recover after sharp falls.","vi":"Thị trường thể hiện xu hướng phục hồi sau những đợt giảm mạnh."},{"en":"These materials show a tendency to expand when heated.","vi":"Những vật liệu này thể hiện xu hướng giãn nở khi bị nung nóng."}]','[]',NULL,'/ʃoʊ ə ˈtendənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5349,'colloc-14-01',109,'show a trend','thể hiện một xu hướng','v + n','[{"en":"The data show a trend toward higher unemployment in rural areas.","vi":"Dữ liệu thể hiện xu hướng thất nghiệp gia tăng ở nông thôn."},{"en":"These figures show a clear trend over the past decade.","vi":"Những con số này cho thấy một xu hướng rõ ràng trong thập kỷ qua."},{"en":"The graph shows a trend that researchers found surprising.","vi":"Biểu đồ thể hiện một xu hướng mà các nhà nghiên cứu thấy bất ngờ."}]','[]',NULL,'/ʃoʊ ə trend/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5350,'colloc-14-01',110,'sign a treaty','ký một hiệp ước','v + n','[{"en":"The two nations agreed to sign a treaty ending the conflict.","vi":"Hai quốc gia đồng ý ký một hiệp ước chấm dứt xung đột."},{"en":"Leaders gathered in Geneva to sign a treaty on trade.","vi":"Các nhà lãnh đạo họp tại Geneva để ký một hiệp ước thương mại."},{"en":"Many countries refused to sign a treaty limiting their emissions.","vi":"Nhiều nước từ chối ký hiệp ước hạn chế khí thải của họ."}]','[]',NULL,'/saɪn ə ˈtriːti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5351,'colloc-14-01',111,'significant amount of','một lượng đáng kể','adj + n','[{"en":"The study required a significant amount of funding to complete.","vi":"Nghiên cứu này cần một lượng kinh phí đáng kể để hoàn thành."},{"en":"Students spend a significant amount of time on group projects.","vi":"Sinh viên dành một lượng thời gian đáng kể cho dự án nhóm."},{"en":"The factory produces a significant amount of waste each year.","vi":"Nhà máy thải ra một lượng chất thải đáng kể mỗi năm."}]','[]',NULL,'/sɪɡˈnɪfɪkənt əˈmaʊnt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5352,'colloc-14-01',112,'significant change','sự thay đổi đáng kể','adj + n','[{"en":"The new policy brought a significant change to school funding.","vi":"Chính sách mới mang lại sự thay đổi đáng kể cho ngân sách trường học."},{"en":"Researchers observed a significant change in patient behavior.","vi":"Các nhà nghiên cứu nhận thấy sự thay đổi đáng kể trong hành vi bệnh nhân."},{"en":"There has been a significant change in public opinion lately.","vi":"Gần đây đã có một sự thay đổi đáng kể trong dư luận."}]','[]',NULL,'/sɪɡˈnɪfɪkənt tʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5353,'colloc-14-01',113,'significant contribution','đóng góp đáng kể','adj + n','[{"en":"Her research made a significant contribution to modern medicine.","vi":"Nghiên cứu của cô có đóng góp đáng kể cho y học hiện đại."},{"en":"Volunteers made a significant contribution to the relief effort.","vi":"Các tình nguyện viên đã đóng góp đáng kể cho nỗ lực cứu trợ."},{"en":"Small donations together formed a significant contribution overall.","vi":"Những khoản quyên góp nhỏ cộng lại tạo nên đóng góp đáng kể."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˌkɑːntrɪˈbjuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5354,'colloc-14-01',114,'significant correlation','mối tương quan đáng kể','adj + n','[{"en":"Analysis revealed a significant correlation between income and health.","vi":"Phân tích cho thấy mối tương quan đáng kể giữa thu nhập và sức khỏe."},{"en":"The study found no significant correlation between the two variables.","vi":"Nghiên cứu không tìm thấy mối tương quan đáng kể giữa hai biến số."},{"en":"Researchers reported a significant correlation in their final results.","vi":"Các nhà nghiên cứu báo cáo mối tương quan đáng kể trong kết quả cuối."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˌkɔːrəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5355,'colloc-14-01',115,'significant degree of','mức độ đáng kể','adj + n','[{"en":"The task requires a significant degree of skill and patience.","vi":"Công việc đòi hỏi một mức độ kỹ năng và kiên nhẫn đáng kể."},{"en":"There remains a significant degree of uncertainty in the forecast.","vi":"Vẫn còn một mức độ không chắc chắn đáng kể trong dự báo."},{"en":"The plan allows a significant degree of local flexibility.","vi":"Kế hoạch cho phép một mức độ linh hoạt đáng kể ở địa phương."}]','[]',NULL,'/sɪɡˈnɪfɪkənt dɪˈɡriː əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5356,'colloc-14-01',116,'significant development','sự phát triển đáng kể','adj + n','[{"en":"The vaccine was a significant development in public health.","vi":"Vắc-xin là một bước phát triển đáng kể trong y tế công cộng."},{"en":"Recent significant developments have transformed the entire industry.","vi":"Những phát triển đáng kể gần đây đã thay đổi toàn ngành."},{"en":"This represents a significant development in renewable energy technology.","vi":"Đây là một bước phát triển đáng kể trong công nghệ năng lượng tái tạo."}]','[]',NULL,'/sɪɡˈnɪfɪkənt dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5357,'colloc-14-01',117,'significant difference','sự khác biệt đáng kể','adj + n','[{"en":"There was a significant difference between the two test groups.","vi":"Có một sự khác biệt đáng kể giữa hai nhóm thử nghiệm."},{"en":"The results showed no significant difference in performance.","vi":"Kết quả không cho thấy sự khác biệt đáng kể về hiệu suất."},{"en":"A significant difference in price affected consumer choices.","vi":"Một sự khác biệt đáng kể về giá đã ảnh hưởng đến lựa chọn của người tiêu dùng."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈdɪfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5358,'colloc-14-01',118,'significant effect','tác động đáng kể','adj + n','[{"en":"The new law had a significant effect on small businesses.","vi":"Luật mới có tác động đáng kể đến các doanh nghiệp nhỏ."},{"en":"Sleep deprivation has a significant effect on concentration levels.","vi":"Thiếu ngủ có tác động đáng kể đến khả năng tập trung."},{"en":"The treatment produced a significant effect within just two weeks.","vi":"Phương pháp điều trị tạo ra tác động đáng kể chỉ trong hai tuần."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5359,'colloc-14-01',119,'significant factor','yếu tố quan trọng','adj + n','[{"en":"Cost was a significant factor in the company''s final decision.","vi":"Chi phí là một yếu tố quan trọng trong quyết định cuối của công ty."},{"en":"Diet is a significant factor in preventing many diseases.","vi":"Chế độ ăn là một yếu tố quan trọng trong việc phòng bệnh."},{"en":"Location remains a significant factor for many young buyers.","vi":"Vị trí vẫn là một yếu tố quan trọng với nhiều người mua trẻ."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5360,'colloc-14-01',120,'significant feature','đặc điểm nổi bật','adj + n','[{"en":"Symmetry is a significant feature of the building''s design.","vi":"Tính đối xứng là một đặc điểm nổi bật trong thiết kế tòa nhà."},{"en":"One significant feature of the report is its detailed data.","vi":"Một đặc điểm nổi bật của báo cáo là dữ liệu chi tiết."},{"en":"The map highlights every significant feature of the landscape.","vi":"Bản đồ làm nổi bật mọi đặc điểm quan trọng của cảnh quan."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5361,'colloc-14-01',121,'significant figures','chữ số có nghĩa','adj + n','[{"en":"Round your answer to three significant figures for accuracy.","vi":"Làm tròn đáp án đến ba chữ số có nghĩa cho chính xác."},{"en":"The teacher explained how to count significant figures correctly.","vi":"Giáo viên giải thích cách đếm chữ số có nghĩa cho đúng."},{"en":"Reporting too many significant figures can mislead the reader.","vi":"Ghi quá nhiều chữ số có nghĩa có thể gây hiểu lầm cho người đọc."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈfɪɡjərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5362,'colloc-14-01',122,'significant growth','sự tăng trưởng đáng kể','adj + n','[{"en":"The region experienced significant growth in its tech sector.","vi":"Khu vực này có sự tăng trưởng đáng kể trong lĩnh vực công nghệ."},{"en":"Significant growth in demand surprised the entire market.","vi":"Sự tăng trưởng đáng kể về nhu cầu khiến cả thị trường bất ngờ."},{"en":"The company reported significant growth despite the recession.","vi":"Công ty báo cáo tăng trưởng đáng kể dù kinh tế suy thoái."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ɡroʊθ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5363,'colloc-14-01',123,'significant impact','tác động lớn','adj + n','[{"en":"Climate change has a significant impact on global agriculture.","vi":"Biến đổi khí hậu có tác động lớn đến nông nghiệp toàn cầu."},{"en":"Her speech had a significant impact on the audience.","vi":"Bài phát biểu của cô có tác động lớn đến khán giả."},{"en":"The reform made a significant impact on rural communities.","vi":"Cuộc cải cách có tác động lớn đến các cộng đồng nông thôn."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈɪmpækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5364,'colloc-14-01',124,'significant improvement','sự cải thiện đáng kể','adj + n','[{"en":"Patients showed significant improvement after the new treatment.","vi":"Bệnh nhân có sự cải thiện đáng kể sau phương pháp điều trị mới."},{"en":"There was a significant improvement in test scores this year.","vi":"Năm nay điểm kiểm tra có sự cải thiện đáng kể."},{"en":"The upgrade brought a significant improvement in system speed.","vi":"Bản nâng cấp mang lại sự cải thiện đáng kể về tốc độ hệ thống."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ɪmˈpruːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5365,'colloc-14-01',125,'significant increase','sự gia tăng đáng kể','adj + n','[{"en":"The city recorded a significant increase in air pollution.","vi":"Thành phố ghi nhận sự gia tăng đáng kể về ô nhiễm không khí."},{"en":"There was a significant increase in applications this semester.","vi":"Học kỳ này số đơn đăng ký tăng đáng kể."},{"en":"Researchers noted a significant increase in average temperatures.","vi":"Các nhà nghiên cứu ghi nhận sự gia tăng đáng kể về nhiệt độ trung bình."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈɪnkriːs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5366,'colloc-14-01',126,'significant influence','ảnh hưởng đáng kể','adj + n','[{"en":"His mentor had a significant influence on his career.","vi":"Người cố vấn có ảnh hưởng đáng kể đến sự nghiệp của anh."},{"en":"Media has a significant influence on young people''s opinions.","vi":"Truyền thông có ảnh hưởng đáng kể đến quan điểm của giới trẻ."},{"en":"Family background exerts a significant influence on academic success.","vi":"Hoàn cảnh gia đình có ảnh hưởng đáng kể đến thành tích học tập."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈɪnfluəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5367,'colloc-14-01',127,'significant interaction','sự tương tác đáng kể','adj + n','[{"en":"The model revealed a significant interaction between the two factors.","vi":"Mô hình cho thấy sự tương tác đáng kể giữa hai yếu tố."},{"en":"Researchers detected a significant interaction affecting the outcome.","vi":"Các nhà nghiên cứu phát hiện một tương tác đáng kể ảnh hưởng đến kết quả."},{"en":"There was no significant interaction between age and treatment.","vi":"Không có sự tương tác đáng kể giữa tuổi tác và phương pháp điều trị."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˌɪntərˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5368,'colloc-14-01',128,'significant number','một số lượng đáng kể','adj + n','[{"en":"A significant number of students dropped out last year.","vi":"Một số lượng đáng kể sinh viên đã bỏ học năm ngoái."},{"en":"The survey reached a significant number of rural households.","vi":"Cuộc khảo sát tiếp cận một số lượng đáng kể hộ gia đình nông thôn."},{"en":"A significant number of voters supported the new proposal.","vi":"Một số lượng đáng kể cử tri ủng hộ đề xuất mới."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈnʌmbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5369,'colloc-14-01',129,'significant part','một phần đáng kể','adj + n','[{"en":"Tourism forms a significant part of the local economy.","vi":"Du lịch là một phần đáng kể của nền kinh tế địa phương."},{"en":"She spent a significant part of her life abroad.","vi":"Cô đã dành một phần đáng kể cuộc đời ở nước ngoài."},{"en":"A significant part of the budget went to research.","vi":"Một phần đáng kể ngân sách được dùng cho nghiên cứu."}]','[]',NULL,'/sɪɡˈnɪfɪkənt pɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5370,'colloc-14-01',130,'significant portion','một phần đáng kể','adj + n','[{"en":"A significant portion of the forest was destroyed by fire.","vi":"Một phần đáng kể của khu rừng bị lửa thiêu rụi."},{"en":"Wages take up a significant portion of household income.","vi":"Tiền lương chiếm một phần đáng kể trong thu nhập hộ gia đình."},{"en":"A significant portion of the data was lost during transfer.","vi":"Một phần đáng kể dữ liệu bị mất trong quá trình chuyển."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˈpɔːrʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5371,'colloc-14-01',131,'significant proportion of','một tỷ lệ đáng kể','adj + n','[{"en":"A significant proportion of workers commute over an hour daily.","vi":"Một tỷ lệ đáng kể người lao động đi làm hơn một giờ mỗi ngày."},{"en":"A significant proportion of energy is wasted in old buildings.","vi":"Một tỷ lệ đáng kể năng lượng bị lãng phí ở các tòa nhà cũ."},{"en":"A significant proportion of respondents disagreed with the plan.","vi":"Một tỷ lệ đáng kể người trả lời không đồng ý với kế hoạch."}]','[]',NULL,'/sɪɡˈnɪfɪkənt prəˈpɔːrʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5372,'colloc-14-01',132,'significant reduction','sự giảm đáng kể','adj + n','[{"en":"The policy led to a significant reduction in crime rates.","vi":"Chính sách dẫn đến sự giảm đáng kể tỷ lệ tội phạm."},{"en":"Recycling caused a significant reduction in landfill waste.","vi":"Tái chế giúp giảm đáng kể lượng rác chôn lấp."},{"en":"There was a significant reduction in costs after automation.","vi":"Chi phí giảm đáng kể sau khi tự động hóa."}]','[]',NULL,'/sɪɡˈnɪfɪkənt rɪˈdʌkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5373,'colloc-14-01',133,'significant relationship','mối quan hệ đáng kể','adj + n','[{"en":"The study found a significant relationship between sleep and memory.","vi":"Nghiên cứu tìm thấy mối quan hệ đáng kể giữa giấc ngủ và trí nhớ."},{"en":"There is a significant relationship between exercise and mood.","vi":"Có một mối quan hệ đáng kể giữa tập thể dục và tâm trạng."},{"en":"Analysis showed no significant relationship between the variables.","vi":"Phân tích không cho thấy mối quan hệ đáng kể giữa các biến số."}]','[]',NULL,'/sɪɡˈnɪfɪkənt rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5374,'colloc-14-01',134,'significant role','vai trò quan trọng','adj + n','[{"en":"Technology plays a significant role in modern education today.","vi":"Công nghệ đóng vai trò quan trọng trong giáo dục hiện đại."},{"en":"She played a significant role in the project''s success.","vi":"Cô đóng vai trò quan trọng trong thành công của dự án."},{"en":"Diet plays a significant role in overall long-term health.","vi":"Chế độ ăn đóng vai trò quan trọng với sức khỏe lâu dài."}]','[]',NULL,'/sɪɡˈnɪfɪkənt roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5375,'colloc-14-01',135,'significant shift','sự chuyển dịch đáng kể','adj + n','[{"en":"There has been a significant shift toward remote work recently.","vi":"Gần đây đã có sự chuyển dịch đáng kể sang làm việc từ xa."},{"en":"The election marked a significant shift in voter priorities.","vi":"Cuộc bầu cử đánh dấu sự chuyển dịch đáng kể trong ưu tiên của cử tri."},{"en":"A significant shift in climate patterns worried scientists.","vi":"Một sự chuyển dịch đáng kể về khí hậu khiến các nhà khoa học lo ngại."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ʃɪft/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5376,'colloc-14-01',136,'significant variation','sự biến thiên đáng kể','adj + n','[{"en":"There is significant variation in rainfall across the region.","vi":"Có sự biến thiên đáng kể về lượng mưa trên khắp khu vực."},{"en":"The results showed significant variation between the test groups.","vi":"Kết quả cho thấy sự biến thiên đáng kể giữa các nhóm thử nghiệm."},{"en":"Significant variation in prices confused many first-time buyers.","vi":"Sự biến thiên đáng kể về giá khiến nhiều người mua lần đầu bối rối."}]','[]',NULL,'/sɪɡˈnɪfɪkənt ˌveriˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5377,'colloc-14-01',137,'significantly affect','ảnh hưởng đáng kể','adv + v','[{"en":"Pollution can significantly affect the health of nearby residents.","vi":"Ô nhiễm có thể ảnh hưởng đáng kể đến sức khỏe của cư dân lân cận."},{"en":"Rising fuel prices significantly affect transportation costs nationwide.","vi":"Giá nhiên liệu tăng ảnh hưởng đáng kể đến chi phí vận tải cả nước."},{"en":"Sleep quality can significantly affect a student''s daily performance.","vi":"Chất lượng giấc ngủ có thể ảnh hưởng đáng kể đến thành tích hằng ngày."}]','[]',NULL,'/sɪɡˈnɪfɪkəntli əˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5378,'colloc-14-01',138,'significantly correlated with','tương quan đáng kể với','adv + vpp','[{"en":"Income was significantly correlated with access to quality healthcare.","vi":"Thu nhập tương quan đáng kể với khả năng tiếp cận y tế chất lượng."},{"en":"Exam scores were significantly correlated with hours of study.","vi":"Điểm thi tương quan đáng kể với số giờ học."},{"en":"Stress levels were significantly correlated with poor sleep habits.","vi":"Mức độ căng thẳng tương quan đáng kể với thói quen ngủ kém."}]','[]',NULL,'/sɪɡˈnɪfɪkəntli ˈkɔːrəleɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5379,'colloc-14-01',139,'significantly higher','cao hơn đáng kể','adv + adj','[{"en":"Prices were significantly higher in the city than in villages.","vi":"Giá cả ở thành phố cao hơn đáng kể so với ở làng quê."},{"en":"Survival rates were significantly higher among treated patients.","vi":"Tỷ lệ sống sót cao hơn đáng kể ở các bệnh nhân được điều trị."},{"en":"The new model''s efficiency was significantly higher than expected.","vi":"Hiệu suất của mẫu mới cao hơn đáng kể so với dự kiến."}]','[]',NULL,'/sɪɡˈnɪfɪkəntli ˈhaɪər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5380,'colloc-14-01',140,'significantly increase','tăng đáng kể','adv + v','[{"en":"Regular exercise can significantly increase a person''s life expectancy.","vi":"Tập thể dục đều đặn có thể làm tăng đáng kể tuổi thọ."},{"en":"The new method could significantly increase crop yields next season.","vi":"Phương pháp mới có thể tăng đáng kể năng suất mùa vụ tới."},{"en":"Higher tuition fees may significantly increase student debt levels.","vi":"Học phí cao hơn có thể làm tăng đáng kể mức nợ sinh viên."}]','[]',NULL,'/sɪɡˈnɪfɪkəntli ˈɪnkriːs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5381,'colloc-14-01',141,'significantly reduced','giảm đáng kể','adv + vpp','[{"en":"The new policy significantly reduced traffic in the city center.","vi":"Chính sách mới đã giảm đáng kể lượng giao thông ở trung tâm."},{"en":"Vaccination significantly reduced the number of severe cases.","vi":"Tiêm chủng đã giảm đáng kể số ca bệnh nặng."},{"en":"Better insulation significantly reduced the building''s energy use.","vi":"Cách nhiệt tốt hơn đã giảm đáng kể mức tiêu thụ năng lượng của tòa nhà."}]','[]',NULL,'/sɪɡˈnɪfɪkəntli rɪˈduːst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5382,'colloc-14-01',142,'similar approach','cách tiếp cận tương tự','adj + n','[{"en":"Other countries have adopted a similar approach to recycling.","vi":"Các nước khác đã áp dụng cách tiếp cận tương tự với tái chế."},{"en":"Researchers used a similar approach in their earlier study.","vi":"Các nhà nghiên cứu đã dùng cách tiếp cận tương tự trong nghiên cứu trước."},{"en":"A similar approach might solve the company''s current problems.","vi":"Một cách tiếp cận tương tự có thể giải quyết vấn đề hiện tại của công ty."}]','[]',NULL,'/ˈsɪmələr əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5383,'colloc-14-01',143,'similar argument','lập luận tương tự','adj + n','[{"en":"Critics raised a similar argument against the previous proposal.","vi":"Các nhà phê bình đưa ra lập luận tương tự chống lại đề xuất trước."},{"en":"She made a similar argument in her opening statement.","vi":"Cô đưa ra lập luận tương tự trong phần mở đầu."},{"en":"A similar argument appears throughout much of his writing.","vi":"Một lập luận tương tự xuất hiện xuyên suốt nhiều bài viết của ông."}]','[]',NULL,'/ˈsɪmələr ˈɑːrɡjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5384,'colloc-14-01',144,'similar characteristics','đặc điểm tương tự','adj + n','[{"en":"The two species share many similar characteristics in behavior.","vi":"Hai loài này chia sẻ nhiều đặc điểm tương tự trong hành vi."},{"en":"Researchers grouped the samples with similar characteristics together.","vi":"Các nhà nghiên cứu nhóm các mẫu có đặc điểm tương tự lại với nhau."},{"en":"These regions display similar characteristics in their climate patterns.","vi":"Những vùng này thể hiện đặc điểm tương tự về kiểu khí hậu."}]','[]',NULL,'/ˈsɪmələr ˌkærəktəˈrɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5385,'colloc-14-01',145,'similar effect','tác dụng tương tự','adj + n','[{"en":"The two drugs produced a similar effect on blood pressure.","vi":"Hai loại thuốc tạo ra tác dụng tương tự lên huyết áp."},{"en":"A similar effect was observed in the second experiment.","vi":"Một tác dụng tương tự được ghi nhận trong thí nghiệm thứ hai."},{"en":"Both policies had a similar effect on local employment.","vi":"Cả hai chính sách đều có tác dụng tương tự lên việc làm địa phương."}]','[]',NULL,'/ˈsɪmələr ɪˈfekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5386,'colloc-14-01',146,'similar issue','vấn đề tương tự','adj + n','[{"en":"Many other schools face a similar issue with funding.","vi":"Nhiều trường khác cũng đối mặt với vấn đề tương tự về kinh phí."},{"en":"The committee addressed a similar issue at last month''s meeting.","vi":"Ủy ban đã giải quyết một vấn đề tương tự tại cuộc họp tháng trước."},{"en":"A similar issue arose during the early stages of testing.","vi":"Một vấn đề tương tự nảy sinh trong giai đoạn đầu thử nghiệm."}]','[]',NULL,'/ˈsɪmələr ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5387,'colloc-14-01',147,'similar pattern','khuôn mẫu tương tự','adj + n','[{"en":"The data followed a similar pattern across all three years.","vi":"Dữ liệu theo một khuôn mẫu tương tự trong cả ba năm."},{"en":"Researchers noticed a similar pattern in the second sample.","vi":"Các nhà nghiên cứu nhận thấy khuôn mẫu tương tự ở mẫu thứ hai."},{"en":"Migration showed a similar pattern to previous decades.","vi":"Di cư thể hiện một khuôn mẫu tương tự với những thập kỷ trước."}]','[]',NULL,'/ˈsɪmələr ˈpætərn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5388,'colloc-14-01',148,'similar properties','tính chất tương tự','adj + n','[{"en":"These metals have similar properties when heated to high temperatures.","vi":"Những kim loại này có tính chất tương tự khi nung ở nhiệt độ cao."},{"en":"The new material shows similar properties to natural rubber.","vi":"Vật liệu mới thể hiện tính chất tương tự cao su tự nhiên."},{"en":"Both compounds share similar properties in chemical reactions.","vi":"Cả hai hợp chất có tính chất tương tự trong phản ứng hóa học."}]','[]',NULL,'/ˈsɪmələr ˈprɑːpərtiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5389,'colloc-14-01',149,'similar result','kết quả tương tự','adj + n','[{"en":"The second trial produced a similar result to the first.","vi":"Thử nghiệm thứ hai cho kết quả tương tự lần đầu."},{"en":"Other teams reported a similar result in their experiments.","vi":"Các nhóm khác báo cáo kết quả tương tự trong thí nghiệm của họ."},{"en":"We expected a similar result under different conditions.","vi":"Chúng tôi mong đợi một kết quả tương tự trong điều kiện khác."}]','[]',NULL,'/ˈsɪmələr rɪˈzʌlt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5390,'colloc-14-01',150,'similar situation','tình huống tương tự','adj + n','[{"en":"Many families found themselves in a similar situation that year.","vi":"Nhiều gia đình rơi vào tình huống tương tự năm đó."},{"en":"A similar situation occurred during the previous economic crisis.","vi":"Một tình huống tương tự đã xảy ra trong cuộc khủng hoảng kinh tế trước."},{"en":"Imagine a similar situation where resources are very limited.","vi":"Hãy hình dung một tình huống tương tự khi tài nguyên rất hạn chế."}]','[]',NULL,'/ˈsɪmələr ˌsɪtʃuˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5391,'colloc-15-01',1,'simple majority','đa số quá bán','adj + n','[{"en":"The motion passed with a simple majority of votes.","vi":"Kiến nghị được thông qua với đa số quá bán phiếu."},{"en":"Only a simple majority is needed to approve the budget.","vi":"Chỉ cần đa số quá bán để thông qua ngân sách."},{"en":"A simple majority cannot amend the country''s constitution.","vi":"Đa số quá bán không thể sửa đổi hiến pháp của quốc gia."}]','[]',NULL,'/ˈsɪmpəl məˈdʒɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5392,'colloc-15-01',2,'simplified version','phiên bản đơn giản hóa','adj + n','[{"en":"The textbook presents a simplified version of the theory.","vi":"Sách giáo khoa trình bày một phiên bản đơn giản hóa của lý thuyết."},{"en":"Teachers gave students a simplified version of the rules.","vi":"Giáo viên đưa cho học sinh một phiên bản đơn giản hóa của các quy tắc."},{"en":"The app offers a simplified version for new users.","vi":"Ứng dụng cung cấp một phiên bản đơn giản hóa cho người dùng mới."}]','[]',NULL,'/ˈsɪmpləfaɪd ˈvɜːrʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5393,'colloc-15-01',3,'single currency','đồng tiền chung','adj + n','[{"en":"Member states adopted a single currency to ease trade.","vi":"Các nước thành viên áp dụng đồng tiền chung để thuận lợi thương mại."},{"en":"A single currency removed the need for constant exchange.","vi":"Đồng tiền chung loại bỏ nhu cầu đổi tiền liên tục."},{"en":"Critics debated whether a single currency suited every economy.","vi":"Các nhà phê bình tranh luận liệu đồng tiền chung có hợp với mọi nền kinh tế."}]','[]',NULL,'/ˈsɪŋɡəl ˈkɜːrənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5394,'colloc-15-01',4,'single element','một yếu tố đơn lẻ','adj + n','[{"en":"No single element alone explains the experiment''s complex outcome.","vi":"Không một yếu tố đơn lẻ nào giải thích được kết quả phức tạp của thí nghiệm."},{"en":"Changing a single element can alter the whole design.","vi":"Thay đổi một yếu tố đơn lẻ có thể làm thay đổi toàn bộ thiết kế."},{"en":"The diagram highlights each single element of the process.","vi":"Sơ đồ làm nổi bật từng yếu tố đơn lẻ của quá trình."}]','[]',NULL,'/ˈsɪŋɡəl ˈeləmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5395,'colloc-15-01',5,'single entity','một thực thể đơn nhất','adj + n','[{"en":"The merger combined both firms into a single entity.","vi":"Vụ sáp nhập gộp cả hai công ty thành một thực thể đơn nhất."},{"en":"The law treats the group as a single entity legally.","vi":"Luật pháp coi nhóm này như một thực thể đơn nhất về mặt pháp lý."},{"en":"Several departments now operate as a single entity.","vi":"Nhiều phòng ban giờ hoạt động như một thực thể đơn nhất."}]','[]',NULL,'/ˈsɪŋɡəl ˈentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5396,'colloc-15-01',6,'single individual','một cá nhân đơn lẻ','adj + n','[{"en":"No single individual can solve this problem alone.","vi":"Không một cá nhân đơn lẻ nào có thể tự giải quyết vấn đề này."},{"en":"A single individual cannot represent the entire community fairly.","vi":"Một cá nhân đơn lẻ không thể đại diện công bằng cho cả cộng đồng."},{"en":"The decision rested on a single individual''s judgment.","vi":"Quyết định dựa vào phán đoán của một cá nhân đơn lẻ."}]','[]',NULL,'/ˈsɪŋɡəl ˌɪndɪˈvɪdʒuəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5397,'colloc-15-01',7,'single issue','một vấn đề đơn lẻ','adj + n','[{"en":"The campaign focused on a single issue throughout the year.","vi":"Chiến dịch tập trung vào một vấn đề đơn lẻ trong suốt năm."},{"en":"Voters rarely choose based on a single issue alone.","vi":"Cử tri hiếm khi chọn dựa trên một vấn đề đơn lẻ."},{"en":"The debate narrowed down to a single issue eventually.","vi":"Cuộc tranh luận cuối cùng thu hẹp về một vấn đề đơn lẻ."}]','[]',NULL,'/ˈsɪŋɡəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5398,'colloc-15-01',8,'single source','một nguồn duy nhất','adj + n','[{"en":"Relying on a single source weakens any research argument.","vi":"Dựa vào một nguồn duy nhất làm yếu đi mọi lập luận nghiên cứu."},{"en":"The report drew its data from a single source.","vi":"Báo cáo lấy dữ liệu từ một nguồn duy nhất."},{"en":"A single source of income made the family vulnerable.","vi":"Một nguồn thu nhập duy nhất khiến gia đình dễ tổn thương."}]','[]',NULL,'/ˈsɪŋɡəl sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5399,'colloc-15-01',9,'single variable','một biến số đơn lẻ','adj + n','[{"en":"The experiment changed only a single variable at a time.","vi":"Thí nghiệm chỉ thay đổi một biến số đơn lẻ mỗi lần."},{"en":"Isolating a single variable helps clarify the true cause.","vi":"Tách riêng một biến số đơn lẻ giúp làm rõ nguyên nhân thực sự."},{"en":"A single variable cannot explain such a complex result.","vi":"Một biến số đơn lẻ không thể giải thích kết quả phức tạp như vậy."}]','[]',NULL,'/ˈsɪŋɡəl ˈveriəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5400,'colloc-15-01',10,'skilled worker','lao động có tay nghề','adj + n','[{"en":"The factory struggled to recruit enough skilled workers.","vi":"Nhà máy gặp khó khăn trong việc tuyển đủ lao động có tay nghề."},{"en":"A skilled worker can complete the task far more quickly.","vi":"Một lao động có tay nghề có thể hoàn thành công việc nhanh hơn nhiều."},{"en":"The country relies on skilled workers from abroad.","vi":"Đất nước phụ thuộc vào lao động có tay nghề từ nước ngoài."}]','[]',NULL,'/skɪld ˈwɜːrkər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5401,'colloc-15-01',11,'slightly different','hơi khác một chút','adv + adj','[{"en":"Each sample produced a slightly different result in testing.","vi":"Mỗi mẫu cho ra một kết quả hơi khác một chút khi thử nghiệm."},{"en":"The new edition uses a slightly different layout.","vi":"Phiên bản mới dùng bố cục hơi khác một chút."},{"en":"Her conclusion was slightly different from the others.","vi":"Kết luận của cô hơi khác một chút so với những người khác."}]','[]',NULL,'/ˈslaɪtli ˈdɪfərənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5402,'colloc-15-01',12,'slightly higher','cao hơn một chút','adv + adj','[{"en":"Temperatures were slightly higher than the seasonal average.","vi":"Nhiệt độ cao hơn một chút so với mức trung bình mùa."},{"en":"Prices this year are slightly higher than last year.","vi":"Giá năm nay cao hơn một chút so với năm ngoái."},{"en":"The treated group showed a slightly higher recovery rate.","vi":"Nhóm được điều trị có tỷ lệ hồi phục cao hơn một chút."}]','[]',NULL,'/ˈslaɪtli ˈhaɪər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5403,'colloc-15-01',13,'slow process','quá trình chậm chạp','adj + n','[{"en":"Learning a new language is often a slow process.","vi":"Học một ngôn ngữ mới thường là một quá trình chậm chạp."},{"en":"Rebuilding trust after the scandal was a slow process.","vi":"Xây dựng lại niềm tin sau vụ bê bối là một quá trình chậm chạp."},{"en":"Coral reefs recover through a slow process over decades.","vi":"Rạn san hô phục hồi qua một quá trình chậm chạp suốt nhiều thập kỷ."}]','[]',NULL,'/sloʊ ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5404,'colloc-15-01',14,'small fraction','một phần nhỏ','adj + n','[{"en":"Only a small fraction of applicants were finally accepted.","vi":"Chỉ một phần nhỏ ứng viên cuối cùng được nhận."},{"en":"A small fraction of the budget covers maintenance costs.","vi":"Một phần nhỏ ngân sách dùng cho chi phí bảo trì."},{"en":"Wind power supplies only a small fraction of the energy.","vi":"Điện gió chỉ cung cấp một phần nhỏ năng lượng."}]','[]',NULL,'/smɔːl ˈfrækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5405,'colloc-15-01',15,'small minority','một thiểu số nhỏ','adj + n','[{"en":"Only a small minority opposed the proposed changes.","vi":"Chỉ một thiểu số nhỏ phản đối những thay đổi được đề xuất."},{"en":"A small minority of students prefer online classes entirely.","vi":"Một thiểu số nhỏ sinh viên hoàn toàn thích học trực tuyến."},{"en":"The survey showed a small minority remained undecided.","vi":"Khảo sát cho thấy một thiểu số nhỏ vẫn chưa quyết định."}]','[]',NULL,'/smɔːl maɪˈnɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5406,'colloc-15-01',16,'small percentage','một tỷ lệ phần trăm nhỏ','adj + n','[{"en":"Only a small percentage of waste is actually recycled.","vi":"Chỉ một tỷ lệ phần trăm nhỏ rác thải thực sự được tái chế."},{"en":"A small percentage of patients experienced minor side effects.","vi":"Một tỷ lệ phần trăm nhỏ bệnh nhân gặp tác dụng phụ nhẹ."},{"en":"Only a small percentage of voters turned out yesterday.","vi":"Chỉ một tỷ lệ phần trăm nhỏ cử tri đi bầu hôm qua."}]','[]',NULL,'/smɔːl pərˈsentɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5407,'colloc-15-01',17,'small portion','một phần nhỏ','adj + n','[{"en":"Only a small portion of the land is suitable for farming.","vi":"Chỉ một phần nhỏ đất đai phù hợp cho canh tác."},{"en":"She saved a small portion of her salary each month.","vi":"Cô tiết kiệm một phần nhỏ lương mỗi tháng."},{"en":"A small portion of the report focused on safety.","vi":"Một phần nhỏ của báo cáo tập trung vào an toàn."}]','[]',NULL,'/smɔːl ˈpɔːrʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5408,'colloc-15-01',18,'small proportion of','một tỷ lệ nhỏ','adj + n','[{"en":"A small proportion of households still lack internet access.","vi":"Một tỷ lệ nhỏ hộ gia đình vẫn chưa có internet."},{"en":"Only a small proportion of income goes toward savings.","vi":"Chỉ một tỷ lệ nhỏ thu nhập được dùng để tiết kiệm."},{"en":"A small proportion of cases required hospital treatment.","vi":"Một tỷ lệ nhỏ ca bệnh cần điều trị tại bệnh viện."}]','[]',NULL,'/smɔːl prəˈpɔːrʃən əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5409,'colloc-15-01',19,'small quantities of','một lượng nhỏ','adj + n','[{"en":"The recipe uses only small quantities of salt.","vi":"Công thức chỉ dùng một lượng nhỏ muối."},{"en":"Small quantities of the chemical were found in the water.","vi":"Một lượng nhỏ hóa chất được tìm thấy trong nước."},{"en":"Plants absorb small quantities of nutrients through their roots.","vi":"Cây hấp thụ một lượng nhỏ chất dinh dưỡng qua rễ."}]','[]',NULL,'/smɔːl ˈkwɑːntətiz əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5410,'colloc-15-01',20,'social activity','hoạt động xã hội','adj + n','[{"en":"The club organizes a social activity every weekend.","vi":"Câu lạc bộ tổ chức một hoạt động xã hội mỗi cuối tuần."},{"en":"Social activity helps older adults stay mentally healthy.","vi":"Hoạt động xã hội giúp người lớn tuổi giữ sức khỏe tinh thần."},{"en":"Many students value social activity as much as study.","vi":"Nhiều sinh viên coi trọng hoạt động xã hội ngang với học tập."}]','[]',NULL,'/ˈsoʊʃəl ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5411,'colloc-15-01',21,'social aspect','khía cạnh xã hội','adj + n','[{"en":"The study explored the social aspect of online gaming.","vi":"Nghiên cứu khám phá khía cạnh xã hội của trò chơi trực tuyến."},{"en":"Teachers often overlook the social aspect of learning.","vi":"Giáo viên thường bỏ qua khía cạnh xã hội của việc học."},{"en":"The social aspect of the festival attracts many visitors.","vi":"Khía cạnh xã hội của lễ hội thu hút nhiều du khách."}]','[]',NULL,'/ˈsoʊʃəl ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5412,'colloc-15-01',22,'social attitudes','thái độ xã hội','adj + n','[{"en":"Social attitudes toward marriage have changed considerably over time.","vi":"Thái độ xã hội đối với hôn nhân đã thay đổi đáng kể theo thời gian."},{"en":"Education can gradually reshape social attitudes about disability.","vi":"Giáo dục có thể dần định hình lại thái độ xã hội về khuyết tật."},{"en":"The survey measured social attitudes across different age groups.","vi":"Cuộc khảo sát đo lường thái độ xã hội ở các nhóm tuổi khác nhau."}]','[]',NULL,'/ˈsoʊʃəl ˈætətuːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5413,'colloc-15-01',23,'social background','hoàn cảnh xã hội','adj + n','[{"en":"Students come from very different social backgrounds here.","vi":"Học sinh ở đây đến từ những hoàn cảnh xã hội rất khác nhau."},{"en":"Social background can strongly influence a child''s opportunities.","vi":"Hoàn cảnh xã hội có thể ảnh hưởng mạnh đến cơ hội của trẻ."},{"en":"The program supports students regardless of social background.","vi":"Chương trình hỗ trợ học sinh bất kể hoàn cảnh xã hội."}]','[]',NULL,'/ˈsoʊʃəl ˈbækɡraʊnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5414,'colloc-15-01',24,'social behavior','hành vi xã hội','adj + n','[{"en":"Researchers study how culture shapes social behavior in children.","vi":"Các nhà nghiên cứu tìm hiểu cách văn hóa định hình hành vi xã hội ở trẻ."},{"en":"Social behavior often differs greatly between rural and urban areas.","vi":"Hành vi xã hội thường khác nhau nhiều giữa nông thôn và thành thị."},{"en":"The experiment measured changes in social behavior over months.","vi":"Thí nghiệm đo lường thay đổi trong hành vi xã hội qua nhiều tháng."}]','[]',NULL,'/ˈsoʊʃəl bɪˈheɪvjər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5415,'colloc-15-01',25,'social circumstances','hoàn cảnh xã hội','adj + n','[{"en":"Their social circumstances limited access to higher education.","vi":"Hoàn cảnh xã hội của họ hạn chế việc tiếp cận giáo dục đại học."},{"en":"Health outcomes often depend on a person''s social circumstances.","vi":"Kết quả sức khỏe thường phụ thuộc vào hoàn cảnh xã hội của một người."},{"en":"Policies should account for the social circumstances of families.","vi":"Chính sách nên tính đến hoàn cảnh xã hội của các gia đình."}]','[]',NULL,'/ˈsoʊʃəl ˈsɜːrkəmstænsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5416,'colloc-15-01',26,'social conflict','xung đột xã hội','adj + n','[{"en":"Rising inequality can fuel serious social conflict over time.","vi":"Bất bình đẳng gia tăng có thể gây ra xung đột xã hội nghiêm trọng."},{"en":"The region has a long history of social conflict.","vi":"Khu vực này có lịch sử xung đột xã hội lâu dài."},{"en":"Dialogue between groups helped reduce the social conflict.","vi":"Đối thoại giữa các nhóm đã giúp giảm xung đột xã hội."}]','[]',NULL,'/ˈsoʊʃəl ˈkɑːnflɪkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5417,'colloc-15-01',27,'social consequences','hệ quả xã hội','adj + n','[{"en":"Unemployment carries serious social consequences for whole communities.","vi":"Thất nghiệp mang lại hệ quả xã hội nghiêm trọng cho cả cộng đồng."},{"en":"The policy ignored the long-term social consequences of poverty.","vi":"Chính sách đã bỏ qua hệ quả xã hội lâu dài của nghèo đói."},{"en":"New technology often brings unexpected social consequences.","vi":"Công nghệ mới thường mang lại hệ quả xã hội bất ngờ."}]','[]',NULL,'/ˈsoʊʃəl ˈkɑːnsəkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5418,'colloc-15-01',28,'social construct','kiến tạo xã hội','adj + n','[{"en":"Many scholars argue that race is a social construct.","vi":"Nhiều học giả cho rằng chủng tộc là một kiến tạo xã hội."},{"en":"Gender roles are often described as a social construct.","vi":"Vai trò giới thường được mô tả như một kiến tạo xã hội."},{"en":"The idea of beauty is partly a social construct.","vi":"Quan niệm về cái đẹp một phần là kiến tạo xã hội."}]','[]',NULL,'/ˈsoʊʃəl ˈkɑːnstrʌkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5419,'colloc-15-01',29,'social contact','tiếp xúc xã hội','adj + n','[{"en":"Regular social contact improves mental health in elderly people.","vi":"Tiếp xúc xã hội thường xuyên cải thiện sức khỏe tinh thần người già."},{"en":"The lockdown reduced everyday social contact for many people.","vi":"Đợt phong tỏa làm giảm tiếp xúc xã hội hằng ngày của nhiều người."},{"en":"Children develop language skills through frequent social contact.","vi":"Trẻ phát triển kỹ năng ngôn ngữ qua tiếp xúc xã hội thường xuyên."}]','[]',NULL,'/ˈsoʊʃəl ˈkɑːntækt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5420,'colloc-15-01',30,'social context','bối cảnh xã hội','adj + n','[{"en":"Language always carries meaning within its social context.","vi":"Ngôn ngữ luôn mang ý nghĩa trong bối cảnh xã hội của nó."},{"en":"We must understand the social context of the historical event.","vi":"Chúng ta phải hiểu bối cảnh xã hội của sự kiện lịch sử."},{"en":"Behavior changes depending on the surrounding social context.","vi":"Hành vi thay đổi tùy theo bối cảnh xã hội xung quanh."}]','[]',NULL,'/ˈsoʊʃəl ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5421,'colloc-15-01',31,'social democracy','dân chủ xã hội','adj + n','[{"en":"Many Nordic countries are seen as models of social democracy.","vi":"Nhiều nước Bắc Âu được xem là hình mẫu của dân chủ xã hội."},{"en":"Social democracy combines free markets with strong welfare systems.","vi":"Dân chủ xã hội kết hợp thị trường tự do với hệ thống phúc lợi mạnh."},{"en":"The party promoted social democracy throughout its long campaign.","vi":"Đảng cổ vũ dân chủ xã hội trong suốt chiến dịch dài của mình."}]','[]',NULL,'/ˈsoʊʃəl dɪˈmɑːkrəsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5422,'colloc-15-01',32,'social dimension','chiều kích xã hội','adj + n','[{"en":"The project considered the social dimension of urban planning.","vi":"Dự án xem xét chiều kích xã hội của quy hoạch đô thị."},{"en":"Economists sometimes ignore the social dimension of their policies.","vi":"Các nhà kinh tế đôi khi bỏ qua chiều kích xã hội trong chính sách."},{"en":"Health care has an important social dimension beyond medicine.","vi":"Chăm sóc sức khỏe có chiều kích xã hội quan trọng ngoài y học."}]','[]',NULL,'/ˈsoʊʃəl dɪˈmenʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5423,'colloc-15-01',33,'social environment','môi trường xã hội','adj + n','[{"en":"A supportive social environment helps children thrive at school.","vi":"Một môi trường xã hội hỗ trợ giúp trẻ phát triển ở trường."},{"en":"The social environment of a workplace affects employee morale.","vi":"Môi trường xã hội nơi làm việc ảnh hưởng đến tinh thần nhân viên."},{"en":"Habits are shaped strongly by the surrounding social environment.","vi":"Thói quen được định hình mạnh bởi môi trường xã hội xung quanh."}]','[]',NULL,'/ˈsoʊʃəl ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5424,'colloc-15-01',34,'social equality','bình đẳng xã hội','adj + n','[{"en":"The movement fought for greater social equality among citizens.","vi":"Phong trào đấu tranh cho sự bình đẳng xã hội lớn hơn giữa các công dân."},{"en":"Education is often seen as a path to social equality.","vi":"Giáo dục thường được coi là con đường đến bình đẳng xã hội."},{"en":"True social equality requires fair access to opportunity.","vi":"Bình đẳng xã hội thực sự đòi hỏi tiếp cận cơ hội công bằng."}]','[]',NULL,'/ˈsoʊʃəl ɪˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5425,'colloc-15-01',35,'social exclusion','sự loại trừ xã hội','adj + n','[{"en":"Poverty often leads to social exclusion for many families.","vi":"Nghèo đói thường dẫn đến sự loại trừ xã hội đối với nhiều gia đình."},{"en":"The charity works to reduce social exclusion among migrants.","vi":"Tổ chức từ thiện hoạt động nhằm giảm sự loại trừ xã hội ở người di cư."},{"en":"Language barriers can cause lasting social exclusion.","vi":"Rào cản ngôn ngữ có thể gây ra sự loại trừ xã hội dai dẳng."}]','[]',NULL,'/ˈsoʊʃəl ɪkˈskluːʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5426,'colloc-15-01',36,'social expectations','kỳ vọng xã hội','adj + n','[{"en":"Young people often feel pressured by social expectations.","vi":"Người trẻ thường cảm thấy áp lực bởi kỳ vọng xã hội."},{"en":"Social expectations about careers differ across cultures.","vi":"Kỳ vọng xã hội về sự nghiệp khác nhau giữa các nền văn hóa."},{"en":"She struggled to meet her family''s social expectations.","vi":"Cô vất vả để đáp ứng kỳ vọng xã hội của gia đình."}]','[]',NULL,'/ˈsoʊʃəl ˌekspekˈteɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5427,'colloc-15-01',37,'social factors','các yếu tố xã hội','adj + n','[{"en":"Social factors strongly influence a child''s educational outcomes.","vi":"Các yếu tố xã hội ảnh hưởng mạnh đến kết quả học tập của trẻ."},{"en":"Researchers examined the social factors behind rising obesity.","vi":"Các nhà nghiên cứu xem xét các yếu tố xã hội đằng sau béo phì gia tăng."},{"en":"Health depends on biological and social factors together.","vi":"Sức khỏe phụ thuộc vào cả yếu tố sinh học và xã hội."}]','[]',NULL,'/ˈsoʊʃəl ˈfæktərz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5428,'colloc-15-01',38,'social function','chức năng xã hội','adj + n','[{"en":"Festivals serve an important social function in many communities.","vi":"Lễ hội phục vụ một chức năng xã hội quan trọng ở nhiều cộng đồng."},{"en":"Language has a clear social function beyond simple communication.","vi":"Ngôn ngữ có chức năng xã hội rõ ràng ngoài việc giao tiếp đơn thuần."},{"en":"The museum also fulfills a valuable social function locally.","vi":"Bảo tàng cũng thực hiện một chức năng xã hội quý giá tại địa phương."}]','[]',NULL,'/ˈsoʊʃəl ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5429,'colloc-15-01',39,'social identity','bản sắc xã hội','adj + n','[{"en":"Language plays a key role in shaping social identity.","vi":"Ngôn ngữ đóng vai trò then chốt trong việc hình thành bản sắc xã hội."},{"en":"Teenagers often explore their social identity through friendships.","vi":"Thanh thiếu niên thường khám phá bản sắc xã hội qua tình bạn."},{"en":"Migration can deeply affect a person''s social identity.","vi":"Di cư có thể ảnh hưởng sâu sắc đến bản sắc xã hội của một người."}]','[]',NULL,'/ˈsoʊʃəl aɪˈdentəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5430,'colloc-15-01',40,'social implications','hàm ý xã hội','adj + n','[{"en":"The new technology raises serious social implications for privacy.","vi":"Công nghệ mới đặt ra những hàm ý xã hội nghiêm trọng về quyền riêng tư."},{"en":"Scientists discussed the social implications of their discovery.","vi":"Các nhà khoa học thảo luận về hàm ý xã hội của phát hiện của họ."},{"en":"The policy has wide social implications for low-income families.","vi":"Chính sách có hàm ý xã hội sâu rộng đối với các gia đình thu nhập thấp."}]','[]',NULL,'/ˈsoʊʃəl ˌɪmplɪˈkeɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5431,'colloc-15-01',41,'social inequality','sự bất bình đẳng xã hội','adj + n','[{"en":"Rising social inequality often leads to political tension in many countries.","vi":"Bất bình đẳng xã hội gia tăng thường dẫn đến căng thẳng chính trị ở nhiều quốc gia."},{"en":"The report examines how education can reduce social inequality over time.","vi":"Báo cáo xem xét giáo dục có thể giảm bất bình đẳng xã hội theo thời gian như thế nào."},{"en":"Economists debate the main causes of widening social inequality today.","vi":"Các nhà kinh tế tranh luận về những nguyên nhân chính của bất bình đẳng xã hội ngày càng lớn."}]','[]',NULL,'/ˈsoʊʃəl ˌɪnɪˈkwɑːləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5432,'colloc-15-01',42,'social institution','thiết chế xã hội','adj + n','[{"en":"The family is often described as the most basic social institution.","vi":"Gia đình thường được mô tả là thiết chế xã hội cơ bản nhất."},{"en":"Schools function as a social institution that shapes young people''s values.","vi":"Trường học hoạt động như một thiết chế xã hội định hình giá trị của giới trẻ."},{"en":"Religious social institutions have influenced laws throughout human history.","vi":"Các thiết chế xã hội tôn giáo đã ảnh hưởng đến luật pháp suốt lịch sử nhân loại."}]','[]',NULL,'/ˈsoʊʃəl ˌɪnstɪˈtuːʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5433,'colloc-15-01',43,'social integration','sự hòa nhập xã hội','adj + n','[{"en":"Language classes promote social integration among newly arrived immigrants.","vi":"Các lớp học ngôn ngữ thúc đẩy sự hòa nhập xã hội của người nhập cư mới đến."},{"en":"The program supports the social integration of refugees into local communities.","vi":"Chương trình hỗ trợ sự hòa nhập xã hội của người tị nạn vào cộng đồng địa phương."},{"en":"Sports teams can encourage social integration across different cultural groups.","vi":"Các đội thể thao có thể khuyến khích sự hòa nhập xã hội giữa các nhóm văn hóa khác nhau."}]','[]',NULL,'/ˈsoʊʃəl ˌɪntɪˈɡreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5434,'colloc-15-01',44,'social interaction','sự tương tác xã hội','adj + n','[{"en":"Daily social interaction is essential for a child''s emotional development.","vi":"Tương tác xã hội hằng ngày rất cần thiết cho sự phát triển cảm xúc của trẻ."},{"en":"Online platforms have changed the way social interaction takes place.","vi":"Các nền tảng trực tuyến đã thay đổi cách thức diễn ra tương tác xã hội."},{"en":"Researchers observed social interaction patterns within the small group.","vi":"Các nhà nghiên cứu quan sát các mô hình tương tác xã hội trong nhóm nhỏ."}]','[]',NULL,'/ˈsoʊʃəl ˌɪntərˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5435,'colloc-15-01',45,'social isolation','sự cô lập xã hội','adj + n','[{"en":"Long-term social isolation can seriously affect a person''s mental health.","vi":"Cô lập xã hội kéo dài có thể ảnh hưởng nghiêm trọng đến sức khỏe tinh thần."},{"en":"The pandemic increased social isolation among elderly people living alone.","vi":"Đại dịch làm gia tăng sự cô lập xã hội ở người già sống một mình."},{"en":"Community centers help reduce social isolation in rural areas.","vi":"Các trung tâm cộng đồng giúp giảm sự cô lập xã hội ở vùng nông thôn."}]','[]',NULL,'/ˈsoʊʃəl ˌaɪsəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5436,'colloc-15-01',46,'social mobility','sự dịch chuyển tầng lớp xã hội','adj + n','[{"en":"Good education can improve social mobility for children from poor families.","vi":"Giáo dục tốt có thể cải thiện sự dịch chuyển xã hội cho trẻ em nhà nghèo."},{"en":"The study measures social mobility across three different generations.","vi":"Nghiên cứu đo lường sự dịch chuyển xã hội qua ba thế hệ khác nhau."},{"en":"Limited social mobility keeps many people trapped in poverty.","vi":"Sự dịch chuyển xã hội hạn chế khiến nhiều người mắc kẹt trong nghèo đói."}]','[]',NULL,'/ˈsoʊʃəl moʊˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5437,'colloc-15-01',47,'social movement','phong trào xã hội','adj + n','[{"en":"The civil rights social movement transformed laws across the country.","vi":"Phong trào xã hội về dân quyền đã thay đổi luật pháp trên cả nước."},{"en":"A new social movement emerged to demand stronger climate action.","vi":"Một phong trào xã hội mới nổi lên đòi hỏi hành động khí hậu mạnh mẽ hơn."},{"en":"Historians study how each social movement shaped public opinion.","vi":"Các nhà sử học nghiên cứu cách mỗi phong trào xã hội định hình dư luận."}]','[]',NULL,'/ˈsoʊʃəl ˈmuːvmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5438,'colloc-15-01',48,'social norm','chuẩn mực xã hội','adj + n','[{"en":"Greeting strangers politely is a common social norm in many cultures.","vi":"Chào hỏi người lạ một cách lịch sự là chuẩn mực xã hội phổ biến ở nhiều nền văn hóa."},{"en":"Breaking a social norm can lead to disapproval from the community.","vi":"Vi phạm một chuẩn mực xã hội có thể dẫn đến sự phản đối từ cộng đồng."},{"en":"Social norms often change slowly as generations grow up.","vi":"Các chuẩn mực xã hội thường thay đổi chậm khi các thế hệ trưởng thành."}]','[]',NULL,'/ˈsoʊʃəl nɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5439,'colloc-15-01',49,'social organization','tổ chức xã hội','adj + n','[{"en":"Anthropologists study the social organization of small tribal groups.","vi":"Các nhà nhân học nghiên cứu tổ chức xã hội của các nhóm bộ lạc nhỏ."},{"en":"Complex social organization allowed early cities to grow rapidly.","vi":"Tổ chức xã hội phức tạp đã giúp các thành phố cổ phát triển nhanh chóng."},{"en":"The book compares social organization in farming and hunting societies.","vi":"Cuốn sách so sánh tổ chức xã hội ở các xã hội nông nghiệp và săn bắt."}]','[]',NULL,'/ˈsoʊʃəl ˌɔːrɡənəˈzeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5440,'colloc-15-01',50,'social phenomenon','hiện tượng xã hội','adj + n','[{"en":"The rapid spread of memes is an interesting social phenomenon online.","vi":"Sự lan truyền nhanh chóng của meme là một hiện tượng xã hội thú vị trên mạng."},{"en":"Sociologists try to explain this complex social phenomenon scientifically.","vi":"Các nhà xã hội học cố gắng giải thích hiện tượng xã hội phức tạp này một cách khoa học."},{"en":"Urban migration is a global social phenomenon affecting many nations.","vi":"Di cư đô thị là một hiện tượng xã hội toàn cầu ảnh hưởng đến nhiều quốc gia."}]','[]',NULL,'/ˈsoʊʃəl fəˈnɑːmɪnən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5441,'colloc-15-01',51,'social policy','chính sách xã hội','adj + n','[{"en":"The government introduced a new social policy to support working families.","vi":"Chính phủ đưa ra một chính sách xã hội mới để hỗ trợ các gia đình lao động."},{"en":"Effective social policy can reduce poverty and improve public health.","vi":"Chính sách xã hội hiệu quả có thể giảm nghèo và cải thiện sức khỏe cộng đồng."},{"en":"The lecture compared social policy in several European countries.","vi":"Bài giảng so sánh chính sách xã hội ở một số quốc gia châu Âu."}]','[]',NULL,'/ˈsoʊʃəl ˈpɑːləsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5442,'colloc-15-01',52,'social reform','cải cách xã hội','adj + n','[{"en":"The activists campaigned for social reform to improve workers'' rights.","vi":"Các nhà hoạt động vận động cho cải cách xã hội nhằm cải thiện quyền của người lao động."},{"en":"Major social reform often requires support from a broad coalition.","vi":"Cải cách xã hội lớn thường cần sự ủng hộ từ một liên minh rộng rãi."},{"en":"Nineteenth-century social reform led to better factory conditions.","vi":"Cải cách xã hội thế kỷ mười chín đã mang lại điều kiện nhà máy tốt hơn."}]','[]',NULL,'/ˈsoʊʃəl rɪˈfɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5443,'colloc-15-01',53,'social relationship','mối quan hệ xã hội','adj + n','[{"en":"Strong social relationships are linked to greater happiness and longer life.","vi":"Các mối quan hệ xã hội bền chặt gắn liền với hạnh phúc và tuổi thọ cao hơn."},{"en":"Moving to a new city can disrupt established social relationships.","vi":"Chuyển đến thành phố mới có thể làm gián đoạn các mối quan hệ xã hội đã có."},{"en":"The study explores how technology reshapes our social relationships.","vi":"Nghiên cứu khám phá cách công nghệ định hình lại các mối quan hệ xã hội của chúng ta."}]','[]',NULL,'/ˈsoʊʃəl rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5444,'colloc-15-01',54,'social responsibility','trách nhiệm xã hội','adj + n','[{"en":"Many companies now take social responsibility seriously in their decisions.","vi":"Nhiều công ty hiện coi trọng trách nhiệm xã hội trong các quyết định của họ."},{"en":"Teaching social responsibility helps students become engaged citizens.","vi":"Dạy trách nhiệm xã hội giúp học sinh trở thành công dân tích cực."},{"en":"Corporate social responsibility includes protecting the environment.","vi":"Trách nhiệm xã hội của doanh nghiệp bao gồm việc bảo vệ môi trường."}]','[]',NULL,'/ˈsoʊʃəl rɪˌspɑːnsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5445,'colloc-15-01',55,'social setting','bối cảnh xã hội','adj + n','[{"en":"People often behave differently depending on the social setting around them.","vi":"Người ta thường cư xử khác nhau tùy thuộc vào bối cảnh xã hội xung quanh."},{"en":"The experiment was repeated in a more relaxed social setting.","vi":"Thí nghiệm được lặp lại trong một bối cảnh xã hội thoải mái hơn."},{"en":"Language use varies greatly across formal and informal social settings.","vi":"Cách dùng ngôn ngữ thay đổi nhiều giữa các bối cảnh xã hội trang trọng và thân mật."}]','[]',NULL,'/ˈsoʊʃəl ˈsetɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5446,'colloc-15-01',56,'social significance','ý nghĩa xã hội','adj + n','[{"en":"The festival has deep social significance for the local community.","vi":"Lễ hội mang ý nghĩa xã hội sâu sắc đối với cộng đồng địa phương."},{"en":"Historians often debate the social significance of this old ritual.","vi":"Các nhà sử học thường tranh luận về ý nghĩa xã hội của nghi lễ cổ này."},{"en":"The painting is admired for both its beauty and social significance.","vi":"Bức tranh được ngưỡng mộ vì cả vẻ đẹp lẫn ý nghĩa xã hội của nó."}]','[]',NULL,'/ˈsoʊʃəl sɪɡˈnɪfɪkəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5447,'colloc-15-01',57,'social status','địa vị xã hội','adj + n','[{"en":"In some cultures, clothing clearly signals a person''s social status.","vi":"Ở một số nền văn hóa, trang phục thể hiện rõ địa vị xã hội của một người."},{"en":"Education can raise the social status of an entire family.","vi":"Giáo dục có thể nâng cao địa vị xã hội của cả một gia đình."},{"en":"The novel describes how marriage affected a woman''s social status.","vi":"Cuốn tiểu thuyết mô tả cách hôn nhân ảnh hưởng đến địa vị xã hội của người phụ nữ."}]','[]',NULL,'/ˈsoʊʃəl ˈsteɪtəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5448,'colloc-15-01',58,'social structure','cấu trúc xã hội','adj + n','[{"en":"The rigid social structure made it hard for people to advance.","vi":"Cấu trúc xã hội cứng nhắc khiến người ta khó thăng tiến."},{"en":"Industrialization gradually changed the social structure of the country.","vi":"Công nghiệp hóa dần thay đổi cấu trúc xã hội của đất nước."},{"en":"Sociologists analyze the social structure of modern urban communities.","vi":"Các nhà xã hội học phân tích cấu trúc xã hội của các cộng đồng đô thị hiện đại."}]','[]',NULL,'/ˈsoʊʃəl ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5449,'colloc-15-01',59,'social theory','lý thuyết xã hội','adj + n','[{"en":"The course introduces classic social theory from the nineteenth century.","vi":"Khóa học giới thiệu lý thuyết xã hội kinh điển từ thế kỷ mười chín."},{"en":"Modern social theory tries to explain inequality and power relations.","vi":"Lý thuyết xã hội hiện đại cố gắng giải thích bất bình đẳng và quan hệ quyền lực."},{"en":"She applied social theory to understand the recent protests.","vi":"Cô áp dụng lý thuyết xã hội để hiểu các cuộc biểu tình gần đây."}]','[]',NULL,'/ˈsoʊʃəl ˈθɪri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5450,'colloc-15-01',60,'social transformation','sự chuyển biến xã hội','adj + n','[{"en":"The internet triggered a rapid social transformation worldwide.","vi":"Internet đã tạo ra một sự chuyển biến xã hội nhanh chóng trên toàn thế giới."},{"en":"Deep social transformation usually takes several decades to complete.","vi":"Sự chuyển biến xã hội sâu sắc thường mất vài thập kỷ để hoàn thành."},{"en":"The revolution led to a profound social transformation of the nation.","vi":"Cuộc cách mạng dẫn đến một sự chuyển biến xã hội sâu sắc của quốc gia."}]','[]',NULL,'/ˈsoʊʃəl ˌtrænsfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5451,'colloc-15-01',61,'social trend','xu hướng xã hội','adj + n','[{"en":"Marketers study current social trends to predict consumer behavior.","vi":"Các nhà tiếp thị nghiên cứu xu hướng xã hội hiện tại để dự đoán hành vi người tiêu dùng."},{"en":"A clear social trend toward remote work emerged after the pandemic.","vi":"Một xu hướng xã hội rõ rệt hướng tới làm việc từ xa xuất hiện sau đại dịch."},{"en":"The article identifies several social trends shaping family life today.","vi":"Bài báo xác định một số xu hướng xã hội đang định hình đời sống gia đình ngày nay."}]','[]',NULL,'/ˈsoʊʃəl trend/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5452,'colloc-15-01',62,'social welfare','phúc lợi xã hội','adj + n','[{"en":"The country invests heavily in social welfare for its citizens.","vi":"Quốc gia này đầu tư mạnh vào phúc lợi xã hội cho người dân."},{"en":"Social welfare programs provide support to unemployed and disabled people.","vi":"Các chương trình phúc lợi xã hội hỗ trợ người thất nghiệp và người khuyết tật."},{"en":"Debates about social welfare spending often divide political parties.","vi":"Các tranh luận về chi tiêu phúc lợi xã hội thường chia rẽ các đảng phái chính trị."}]','[]',NULL,'/ˈsoʊʃəl ˈwelfer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5453,'colloc-15-01',63,'socially acceptable','được xã hội chấp nhận','adv + adj','[{"en":"What is socially acceptable in one country may offend another.","vi":"Điều được xã hội chấp nhận ở nước này có thể xúc phạm ở nước khác."},{"en":"Over time, attitudes about what is socially acceptable change.","vi":"Theo thời gian, quan niệm về điều được xã hội chấp nhận thay đổi."},{"en":"The advertisement was considered no longer socially acceptable today.","vi":"Quảng cáo đó bị coi là không còn được xã hội chấp nhận ngày nay."}]','[]',NULL,'/ˈsoʊʃəli əkˈseptəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5454,'colloc-15-01',64,'socially constructed','được kiến tạo về mặt xã hội','adv + vpp','[{"en":"Many scholars argue that gender roles are socially constructed.","vi":"Nhiều học giả cho rằng vai trò giới được kiến tạo về mặt xã hội."},{"en":"The idea of beauty is largely socially constructed and changes over time.","vi":"Quan niệm về cái đẹp phần lớn được kiến tạo về mặt xã hội và thay đổi theo thời gian."},{"en":"This theory claims that race is a socially constructed category.","vi":"Lý thuyết này cho rằng chủng tộc là một phạm trù được kiến tạo về mặt xã hội."}]','[]',NULL,'/ˈsoʊʃəli kənˈstrʌktɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5455,'colloc-15-01',65,'socially desirable','được xã hội coi trọng','adv + adj','[{"en":"Survey respondents often give socially desirable rather than honest answers.","vi":"Người trả lời khảo sát thường đưa ra câu trả lời được xã hội coi trọng thay vì trung thực."},{"en":"Generosity is generally seen as a socially desirable trait.","vi":"Sự hào phóng thường được xem là một phẩm chất được xã hội coi trọng."},{"en":"People may exaggerate socially desirable behaviors in interviews.","vi":"Người ta có thể phóng đại các hành vi được xã hội coi trọng trong các cuộc phỏng vấn."}]','[]',NULL,'/ˈsoʊʃəli dɪˈzaɪərəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5456,'colloc-15-01',66,'socially responsible','có trách nhiệm với xã hội','adv + adj','[{"en":"Socially responsible businesses consider their impact on local communities.","vi":"Các doanh nghiệp có trách nhiệm với xã hội cân nhắc tác động đến cộng đồng địa phương."},{"en":"Investors increasingly prefer socially responsible companies and funds.","vi":"Các nhà đầu tư ngày càng ưa chuộng những công ty và quỹ có trách nhiệm với xã hội."},{"en":"The school encourages students to become socially responsible adults.","vi":"Nhà trường khuyến khích học sinh trở thành người lớn có trách nhiệm với xã hội."}]','[]',NULL,'/ˈsoʊʃəli rɪˈspɑːnsəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5457,'colloc-15-01',67,'socioeconomic status','tình trạng kinh tế - xã hội','adj + n','[{"en":"Children''s socioeconomic status often affects their access to good schools.","vi":"Tình trạng kinh tế - xã hội của trẻ thường ảnh hưởng đến việc tiếp cận trường tốt."},{"en":"The study controlled for socioeconomic status when comparing the groups.","vi":"Nghiên cứu đã kiểm soát tình trạng kinh tế - xã hội khi so sánh các nhóm."},{"en":"Higher socioeconomic status is linked with better health outcomes.","vi":"Tình trạng kinh tế - xã hội cao hơn gắn liền với kết quả sức khỏe tốt hơn."}]','[]',NULL,'/ˌsoʊsioʊˌekəˈnɑːmɪk ˈsteɪtəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5458,'colloc-15-01',68,'solar energy','năng lượng mặt trời','adj + n','[{"en":"Solar energy is a clean and renewable source of electricity.","vi":"Năng lượng mặt trời là nguồn điện sạch và có thể tái tạo."},{"en":"Many homes now use solar energy to reduce their power bills.","vi":"Nhiều ngôi nhà hiện dùng năng lượng mặt trời để giảm hóa đơn tiền điện."},{"en":"Governments are investing in solar energy to fight climate change.","vi":"Các chính phủ đang đầu tư vào năng lượng mặt trời để chống biến đổi khí hậu."}]','[]',NULL,'/ˈsoʊlər ˈenərdʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5459,'colloc-15-01',69,'solar panel','tấm pin mặt trời','adj + n','[{"en":"They installed solar panels on the roof to generate electricity.","vi":"Họ lắp đặt các tấm pin mặt trời trên mái nhà để tạo ra điện."},{"en":"A single solar panel can power several household appliances.","vi":"Một tấm pin mặt trời có thể cung cấp điện cho vài thiết bị gia dụng."},{"en":"The cost of each solar panel has dropped sharply in recent years.","vi":"Chi phí của mỗi tấm pin mặt trời đã giảm mạnh trong những năm gần đây."}]','[]',NULL,'/ˈsoʊlər ˈpænəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5460,'colloc-15-01',70,'solar power','điện mặt trời','adj + n','[{"en":"The remote village relies entirely on solar power for its electricity.","vi":"Ngôi làng hẻo lánh hoàn toàn dựa vào điện mặt trời để có điện."},{"en":"Solar power has become much cheaper over the last decade.","vi":"Điện mặt trời đã trở nên rẻ hơn nhiều trong thập kỷ qua."},{"en":"Engineers are improving how solar power is stored at night.","vi":"Các kỹ sư đang cải tiến cách lưu trữ điện mặt trời vào ban đêm."}]','[]',NULL,'/ˈsoʊlər ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5461,'colloc-15-01',71,'solar system','hệ mặt trời','adj + n','[{"en":"Our solar system contains eight planets orbiting the sun.","vi":"Hệ mặt trời của chúng ta có tám hành tinh quay quanh mặt trời."},{"en":"Astronomers are searching for life elsewhere in the solar system.","vi":"Các nhà thiên văn đang tìm kiếm sự sống ở nơi khác trong hệ mặt trời."},{"en":"The lecture explained how the solar system formed billions of years ago.","vi":"Bài giảng giải thích hệ mặt trời hình thành hàng tỷ năm trước như thế nào."}]','[]',NULL,'/ˈsoʊlər ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5462,'colloc-15-01',72,'source material','tư liệu gốc','n + n','[{"en":"The historian gathered source material from several national archives.","vi":"Nhà sử học thu thập tư liệu gốc từ nhiều kho lưu trữ quốc gia."},{"en":"Students must cite all source material used in their essays.","vi":"Sinh viên phải trích dẫn mọi tư liệu gốc được dùng trong bài luận."},{"en":"The documentary draws on rare source material from the war.","vi":"Bộ phim tài liệu dựa trên tư liệu gốc hiếm có từ thời chiến."}]','[]',NULL,'/ˈsɔːrs məˈtɪriəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5463,'colloc-15-01',73,'sovereign state','quốc gia có chủ quyền','adj + n','[{"en":"Each sovereign state has the right to make its own laws.","vi":"Mỗi quốc gia có chủ quyền đều có quyền tự đặt ra luật pháp của mình."},{"en":"The treaty was signed between two independent sovereign states.","vi":"Hiệp ước được ký kết giữa hai quốc gia có chủ quyền độc lập."},{"en":"International law recognizes the borders of every sovereign state.","vi":"Luật quốc tế công nhận biên giới của mọi quốc gia có chủ quyền."}]','[]',NULL,'/ˈsɑːvrɪn steɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5464,'colloc-15-01',74,'sparsely populated','thưa dân','adv + vpp','[{"en":"The northern region is sparsely populated and mostly covered by forest.","vi":"Vùng phía bắc thưa dân và phần lớn được rừng bao phủ."},{"en":"Sparsely populated areas often lack good roads and hospitals.","vi":"Các khu vực thưa dân thường thiếu đường tốt và bệnh viện."},{"en":"Much of the desert remains sparsely populated even today.","vi":"Phần lớn sa mạc vẫn thưa dân cho đến ngày nay."}]','[]',NULL,'/ˈspɑːrsli ˈpɑːpjəleɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5465,'colloc-15-01',75,'special circumstances','hoàn cảnh đặc biệt','adj + n','[{"en":"Extensions are granted only under special circumstances such as illness.","vi":"Gia hạn chỉ được cấp trong những hoàn cảnh đặc biệt như ốm đau."},{"en":"The rule may be waived if special circumstances clearly apply.","vi":"Quy tắc có thể được miễn nếu rõ ràng có hoàn cảnh đặc biệt."},{"en":"Please explain any special circumstances affecting your application.","vi":"Vui lòng giải thích bất kỳ hoàn cảnh đặc biệt nào ảnh hưởng đến đơn của bạn."}]','[]',NULL,'/ˈspeʃəl ˈsɜːrkəmstænsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5466,'colloc-15-01',76,'special emphasis','sự nhấn mạnh đặc biệt','adj + n','[{"en":"The course places special emphasis on practical writing skills.","vi":"Khóa học đặt sự nhấn mạnh đặc biệt vào kỹ năng viết thực hành."},{"en":"She gave special emphasis to safety throughout the training session.","vi":"Cô đặc biệt nhấn mạnh vào an toàn trong suốt buổi huấn luyện."},{"en":"The report puts special emphasis on the needs of rural communities.","vi":"Báo cáo đặc biệt nhấn mạnh đến nhu cầu của các cộng đồng nông thôn."}]','[]',NULL,'/ˈspeʃəl ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5467,'colloc-15-01',77,'special issue','số chuyên đề','adj + n','[{"en":"The journal published a special issue on climate science this year.","vi":"Tạp chí đã xuất bản một số chuyên đề về khoa học khí hậu năm nay."},{"en":"Her article appeared in a special issue devoted to education.","vi":"Bài viết của cô xuất hiện trong một số chuyên đề dành cho giáo dục."},{"en":"The magazine''s special issue sold out within a single week.","vi":"Số chuyên đề của tạp chí đã bán hết chỉ trong một tuần."}]','[]',NULL,'/ˈspeʃəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5468,'colloc-15-01',78,'special relationship','mối quan hệ đặc biệt','adj + n','[{"en":"The two countries have maintained a special relationship for decades.","vi":"Hai quốc gia đã duy trì một mối quan hệ đặc biệt trong nhiều thập kỷ."},{"en":"Teachers can build a special relationship with their youngest students.","vi":"Giáo viên có thể xây dựng một mối quan hệ đặc biệt với những học sinh nhỏ tuổi nhất."},{"en":"The book describes the special relationship between the king and his advisor.","vi":"Cuốn sách mô tả mối quan hệ đặc biệt giữa nhà vua và cố vấn của ông."}]','[]',NULL,'/ˈspeʃəl rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5469,'colloc-15-01',79,'special status','quy chế đặc biệt','adj + n','[{"en":"The historic city was granted special status to protect its buildings.","vi":"Thành phố lịch sử được trao quy chế đặc biệt để bảo vệ các tòa nhà của nó."},{"en":"Refugees may be given special status under international law.","vi":"Người tị nạn có thể được trao quy chế đặc biệt theo luật quốc tế."},{"en":"The region enjoys special status that allows greater self-government.","vi":"Khu vực này có quy chế đặc biệt cho phép quyền tự quản lớn hơn."}]','[]',NULL,'/ˈspeʃəl ˈsteɪtəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5470,'colloc-15-01',80,'specific area','lĩnh vực cụ thể','adj + n','[{"en":"The training focuses on one specific area of clinical practice.","vi":"Khóa đào tạo tập trung vào một lĩnh vực cụ thể của thực hành lâm sàng."},{"en":"Researchers often specialize in a narrow specific area of study.","vi":"Các nhà nghiên cứu thường chuyên sâu vào một lĩnh vực cụ thể hẹp."},{"en":"Please describe the specific area where you need more support.","vi":"Vui lòng mô tả lĩnh vực cụ thể mà bạn cần thêm hỗ trợ."}]','[]',NULL,'/spəˈsɪfɪk ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5471,'colloc-15-01',81,'specific aspect','khía cạnh cụ thể','adj + n','[{"en":"Each chapter examines a different specific aspect of the problem.","vi":"Mỗi chương xem xét một khía cạnh cụ thể khác nhau của vấn đề."},{"en":"The interview focused on one specific aspect of her career.","vi":"Cuộc phỏng vấn tập trung vào một khía cạnh cụ thể trong sự nghiệp của cô."},{"en":"Let us now consider a more specific aspect of the theory.","vi":"Bây giờ chúng ta hãy xem xét một khía cạnh cụ thể hơn của lý thuyết."}]','[]',NULL,'/spəˈsɪfɪk ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5472,'colloc-15-01',82,'specific case','trường hợp cụ thể','adj + n','[{"en":"The lawyer used a specific case to illustrate the legal principle.","vi":"Luật sư dùng một trường hợp cụ thể để minh họa nguyên tắc pháp lý."},{"en":"In this specific case, the usual rules do not apply.","vi":"Trong trường hợp cụ thể này, các quy tắc thông thường không áp dụng."},{"en":"The textbook analyzes a specific case in great detail.","vi":"Sách giáo khoa phân tích một trường hợp cụ thể rất chi tiết."}]','[]',NULL,'/spəˈsɪfɪk keɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5473,'colloc-15-01',83,'specific characteristic','đặc điểm cụ thể','adj + n','[{"en":"Each species has a specific characteristic that helps it survive.","vi":"Mỗi loài có một đặc điểm cụ thể giúp nó tồn tại."},{"en":"The scientist measured one specific characteristic of every sample.","vi":"Nhà khoa học đo một đặc điểm cụ thể của mỗi mẫu vật."},{"en":"This material is chosen for one specific characteristic: its strength.","vi":"Vật liệu này được chọn vì một đặc điểm cụ thể: độ bền của nó."}]','[]',NULL,'/spəˈsɪfɪk ˌkærəktəˈrɪstɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5474,'colloc-15-01',84,'specific context','ngữ cảnh cụ thể','adj + n','[{"en":"The meaning of a word depends on its specific context.","vi":"Nghĩa của một từ phụ thuộc vào ngữ cảnh cụ thể của nó."},{"en":"These findings apply only within a specific context like this one.","vi":"Những phát hiện này chỉ áp dụng trong một ngữ cảnh cụ thể như thế này."},{"en":"Researchers must describe the specific context of their experiment.","vi":"Các nhà nghiên cứu phải mô tả ngữ cảnh cụ thể của thí nghiệm."}]','[]',NULL,'/spəˈsɪfɪk ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5475,'colloc-15-01',85,'specific example','ví dụ cụ thể','adj + n','[{"en":"The teacher gave a specific example to make the idea clearer.","vi":"Giáo viên đưa ra một ví dụ cụ thể để làm rõ ý tưởng hơn."},{"en":"Can you provide a specific example to support your argument?","vi":"Bạn có thể đưa ra một ví dụ cụ thể để hỗ trợ lập luận của mình không?"},{"en":"Each claim in the essay is backed by a specific example.","vi":"Mỗi luận điểm trong bài luận đều được hỗ trợ bằng một ví dụ cụ thể."}]','[]',NULL,'/spəˈsɪfɪk ɪɡˈzæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5476,'colloc-15-01',86,'specific factor','yếu tố cụ thể','adj + n','[{"en":"The study isolated one specific factor causing the rise in sales.","vi":"Nghiên cứu tách riêng một yếu tố cụ thể gây ra sự tăng doanh số."},{"en":"Several specific factors influenced the outcome of the experiment.","vi":"Một số yếu tố cụ thể đã ảnh hưởng đến kết quả của thí nghiệm."},{"en":"It is hard to identify the specific factor behind the failure.","vi":"Thật khó để xác định yếu tố cụ thể đằng sau sự thất bại."}]','[]',NULL,'/spəˈsɪfɪk ˈfæktər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5477,'colloc-15-01',87,'specific feature','tính năng cụ thể','adj + n','[{"en":"Users praised one specific feature of the new mobile application.","vi":"Người dùng khen ngợi một tính năng cụ thể của ứng dụng di động mới."},{"en":"The design includes a specific feature to help disabled customers.","vi":"Thiết kế bao gồm một tính năng cụ thể để hỗ trợ khách hàng khuyết tật."},{"en":"Each model offers a specific feature that the others lack.","vi":"Mỗi mẫu cung cấp một tính năng cụ thể mà các mẫu khác không có."}]','[]',NULL,'/spəˈsɪfɪk ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5478,'colloc-15-01',88,'specific focus','trọng tâm cụ thể','adj + n','[{"en":"The seminar has a specific focus on renewable energy this term.","vi":"Hội thảo có một trọng tâm cụ thể về năng lượng tái tạo trong học kỳ này."},{"en":"Her thesis maintains a specific focus throughout every chapter.","vi":"Luận văn của cô duy trì một trọng tâm cụ thể xuyên suốt mọi chương."},{"en":"The committee asked the team to choose a more specific focus.","vi":"Ủy ban yêu cầu nhóm chọn một trọng tâm cụ thể hơn."}]','[]',NULL,'/spəˈsɪfɪk ˈfoʊkəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5479,'colloc-15-01',89,'specific form','hình thức cụ thể','adj + n','[{"en":"The disease appears in a specific form among older patients.","vi":"Căn bệnh xuất hiện dưới một hình thức cụ thể ở bệnh nhân lớn tuổi."},{"en":"This specific form of art developed in the seventeenth century.","vi":"Hình thức nghệ thuật cụ thể này phát triển vào thế kỷ mười bảy."},{"en":"Each language expresses politeness through a specific form of address.","vi":"Mỗi ngôn ngữ thể hiện sự lịch sự qua một hình thức xưng hô cụ thể."}]','[]',NULL,'/spəˈsɪfɪk fɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5480,'colloc-15-01',90,'specific function','chức năng cụ thể','adj + n','[{"en":"Each part of the cell performs a specific function in the body.","vi":"Mỗi bộ phận của tế bào thực hiện một chức năng cụ thể trong cơ thể."},{"en":"The tool was designed for one specific function in the factory.","vi":"Công cụ này được thiết kế cho một chức năng cụ thể trong nhà máy."},{"en":"Every department in the company has its own specific function.","vi":"Mỗi phòng ban trong công ty có chức năng cụ thể riêng của mình."}]','[]',NULL,'/spəˈsɪfɪk ˈfʌŋkʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5481,'colloc-15-01',91,'specific information','thông tin cụ thể','adj + n','[{"en":"The form asks for specific information about your work history.","vi":"Mẫu đơn yêu cầu thông tin cụ thể về lịch sử làm việc của bạn."},{"en":"Readers can search the website for specific information quickly.","vi":"Người đọc có thể tìm thông tin cụ thể trên trang web một cách nhanh chóng."},{"en":"The report lacks the specific information needed for a decision.","vi":"Báo cáo thiếu thông tin cụ thể cần thiết để đưa ra quyết định."}]','[]',NULL,'/spəˈsɪfɪk ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5482,'colloc-15-01',92,'specific issue','vấn đề cụ thể','adj + n','[{"en":"The meeting was called to discuss one specific issue only.","vi":"Cuộc họp được tổ chức để thảo luận chỉ một vấn đề cụ thể."},{"en":"She raised a specific issue about safety at the construction site.","vi":"Cô nêu ra một vấn đề cụ thể về an toàn tại công trường xây dựng."},{"en":"The committee will address each specific issue in turn.","vi":"Ủy ban sẽ giải quyết từng vấn đề cụ thể một cách lần lượt."}]','[]',NULL,'/spəˈsɪfɪk ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5483,'colloc-15-01',93,'specific knowledge','kiến thức cụ thể','adj + n','[{"en":"The job requires specific knowledge of computer programming languages.","vi":"Công việc đòi hỏi kiến thức cụ thể về các ngôn ngữ lập trình máy tính."},{"en":"Doctors need specific knowledge about each medicine they prescribe.","vi":"Bác sĩ cần kiến thức cụ thể về từng loại thuốc họ kê đơn."},{"en":"Without specific knowledge of the region, the plan could fail.","vi":"Nếu không có kiến thức cụ thể về khu vực, kế hoạch có thể thất bại."}]','[]',NULL,'/spəˈsɪfɪk ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5484,'colloc-15-01',94,'specific meaning','ý nghĩa cụ thể','adj + n','[{"en":"In law, this word carries a very specific meaning.","vi":"Trong luật, từ này mang một ý nghĩa rất cụ thể."},{"en":"Each symbol in the diagram has a specific meaning.","vi":"Mỗi ký hiệu trong sơ đồ đều có một ý nghĩa cụ thể."},{"en":"The author explains the specific meaning of the technical term.","vi":"Tác giả giải thích ý nghĩa cụ thể của thuật ngữ kỹ thuật."}]','[]',NULL,'/spəˈsɪfɪk ˈmiːnɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5485,'colloc-15-01',95,'specific needs','nhu cầu cụ thể','adj + n','[{"en":"The program is tailored to the specific needs of each student.","vi":"Chương trình được điều chỉnh theo nhu cầu cụ thể của mỗi học sinh."},{"en":"Older patients often have specific needs that require special care.","vi":"Bệnh nhân lớn tuổi thường có nhu cầu cụ thể đòi hỏi chăm sóc đặc biệt."},{"en":"The company surveys customers to understand their specific needs.","vi":"Công ty khảo sát khách hàng để hiểu nhu cầu cụ thể của họ."}]','[]',NULL,'/spəˈsɪfɪk niːdz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5486,'colloc-15-01',96,'specific problem','vấn đề cụ thể','adj + n','[{"en":"The research was designed to solve one specific problem.","vi":"Nghiên cứu được thiết kế để giải quyết một vấn đề cụ thể."},{"en":"Please describe the specific problem you encountered with the software.","vi":"Vui lòng mô tả vấn đề cụ thể bạn gặp phải với phần mềm."},{"en":"Each section of the report addresses a specific problem.","vi":"Mỗi phần của báo cáo giải quyết một vấn đề cụ thể."}]','[]',NULL,'/spəˈsɪfɪk ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5487,'colloc-15-01',97,'specific purpose','mục đích cụ thể','adj + n','[{"en":"The fund was created for one specific purpose: student scholarships.","vi":"Quỹ được lập ra cho một mục đích cụ thể: học bổng cho sinh viên."},{"en":"Each tool in the kit serves a specific purpose.","vi":"Mỗi dụng cụ trong bộ đều phục vụ một mục đích cụ thể."},{"en":"The course teaches English for the specific purpose of business.","vi":"Khóa học dạy tiếng Anh cho mục đích cụ thể là kinh doanh."}]','[]',NULL,'/spəˈsɪfɪk ˈpɜːrpəs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5488,'colloc-15-01',98,'specific question','câu hỏi cụ thể','adj + n','[{"en":"The interviewer asked a very specific question about my experience.","vi":"Người phỏng vấn hỏi một câu hỏi rất cụ thể về kinh nghiệm của tôi."},{"en":"Each specific question on the survey targets one behavior.","vi":"Mỗi câu hỏi cụ thể trong khảo sát nhắm vào một hành vi."},{"en":"Students should prepare a specific question for the guest speaker.","vi":"Sinh viên nên chuẩn bị một câu hỏi cụ thể cho diễn giả khách mời."}]','[]',NULL,'/spəˈsɪfɪk ˈkwestʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5489,'colloc-15-01',99,'specific reference','sự đề cập cụ thể','adj + n','[{"en":"The essay makes specific reference to two recent studies.","vi":"Bài luận đề cập cụ thể đến hai nghiên cứu gần đây."},{"en":"His speech contained a specific reference to last year''s report.","vi":"Bài phát biểu của ông có sự đề cập cụ thể đến báo cáo năm ngoái."},{"en":"Please add a specific reference to support each claim.","vi":"Vui lòng thêm một sự đề cập cụ thể để hỗ trợ mỗi luận điểm."}]','[]',NULL,'/spəˈsɪfɪk ˈrefərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5490,'colloc-15-01',100,'specific sense','nghĩa cụ thể','adj + n','[{"en":"The word is used here in a very specific sense.","vi":"Từ này được dùng ở đây theo một nghĩa cụ thể rất rõ ràng."},{"en":"In a specific sense, freedom means the absence of restriction.","vi":"Theo một nghĩa cụ thể, tự do nghĩa là không có sự ràng buộc."},{"en":"The author defines the term in its specific sense early on.","vi":"Tác giả định nghĩa thuật ngữ theo nghĩa cụ thể của nó từ đầu."}]','[]',NULL,'/spəˈsɪfɪk sens/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5491,'colloc-15-01',101,'specific type','loại cụ thể','adj + n','[{"en":"This medicine treats one specific type of infection.","vi":"Loại thuốc này điều trị một loại nhiễm trùng cụ thể."},{"en":"The factory produces a specific type of steel for bridges.","vi":"Nhà máy sản xuất một loại thép cụ thể dùng cho cầu."},{"en":"Researchers studied a specific type of cell under the microscope.","vi":"Các nhà nghiên cứu nghiên cứu một loại tế bào cụ thể dưới kính hiển vi."}]','[]',NULL,'/spəˈsɪfɪk taɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5492,'colloc-15-01',102,'specifically designed to','được thiết kế riêng để','adv + vpp','[{"en":"The software was specifically designed to help blind users read.","vi":"Phần mềm được thiết kế riêng để giúp người khiếm thị đọc."},{"en":"This chair is specifically designed to support the lower back.","vi":"Chiếc ghế này được thiết kế riêng để hỗ trợ phần lưng dưới."},{"en":"The program is specifically designed to train young athletes.","vi":"Chương trình được thiết kế riêng để huấn luyện các vận động viên trẻ."}]','[]',NULL,'/spəˈsɪfɪkli dɪˈzaɪnd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5493,'colloc-15-01',103,'standard approach','cách tiếp cận tiêu chuẩn','adj + n','[{"en":"Doctors followed the standard approach to treating the infection.","vi":"Các bác sĩ tuân theo cách tiếp cận tiêu chuẩn để điều trị nhiễm trùng."},{"en":"The standard approach to this problem may not always work.","vi":"Cách tiếp cận tiêu chuẩn cho vấn đề này không phải lúc nào cũng hiệu quả."},{"en":"Researchers compared a new method with the standard approach.","vi":"Các nhà nghiên cứu so sánh phương pháp mới với cách tiếp cận tiêu chuẩn."}]','[]',NULL,'/ˈstændərd əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5494,'colloc-15-01',104,'standard error','sai số chuẩn','adj + n','[{"en":"The table reports the mean along with its standard error.","vi":"Bảng báo cáo giá trị trung bình cùng với sai số chuẩn của nó."},{"en":"A smaller standard error suggests a more precise estimate.","vi":"Sai số chuẩn nhỏ hơn cho thấy một ước lượng chính xác hơn."},{"en":"Students learned how to calculate the standard error of the mean.","vi":"Sinh viên học cách tính sai số chuẩn của giá trị trung bình."}]','[]',NULL,'/ˈstændərd ˈerər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5495,'colloc-15-01',105,'standard format','định dạng tiêu chuẩn','adj + n','[{"en":"All reports must follow the standard format set by the journal.","vi":"Tất cả báo cáo phải tuân theo định dạng tiêu chuẩn do tạp chí đặt ra."},{"en":"Saving the file in a standard format makes sharing easier.","vi":"Lưu tệp ở định dạng tiêu chuẩn giúp việc chia sẻ dễ dàng hơn."},{"en":"The template provides a standard format for every assignment.","vi":"Mẫu cung cấp một định dạng tiêu chuẩn cho mọi bài tập."}]','[]',NULL,'/ˈstændərd ˈfɔːrmæt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5496,'colloc-15-01',106,'standard method','phương pháp tiêu chuẩn','adj + n','[{"en":"Scientists used the standard method to measure water quality.","vi":"Các nhà khoa học dùng phương pháp tiêu chuẩn để đo chất lượng nước."},{"en":"The new technique is faster than the standard method.","vi":"Kỹ thuật mới nhanh hơn phương pháp tiêu chuẩn."},{"en":"Following a standard method makes the results easy to compare.","vi":"Tuân theo một phương pháp tiêu chuẩn giúp kết quả dễ so sánh."}]','[]',NULL,'/ˈstændərd ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5497,'colloc-15-01',107,'stark contrast','sự tương phản rõ rệt','adj + n','[{"en":"The rich neighborhood stood in stark contrast to the nearby slums.","vi":"Khu phố giàu có tương phản rõ rệt với khu ổ chuột gần đó."},{"en":"Her calm reply was in stark contrast to his angry shouting.","vi":"Câu trả lời bình tĩnh của cô tương phản rõ rệt với tiếng la hét giận dữ của anh."},{"en":"The data shows a stark contrast between the two regions.","vi":"Dữ liệu cho thấy sự tương phản rõ rệt giữa hai khu vực."}]','[]',NULL,'/stɑːrk ˈkɑːntræst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5498,'colloc-15-01',108,'start a process','bắt đầu một quy trình','v + n','[{"en":"The new law will start a process of major political change.","vi":"Luật mới sẽ bắt đầu một quy trình thay đổi chính trị lớn."},{"en":"Click the button to start a process that cannot be undone.","vi":"Nhấn nút để bắt đầu một quy trình không thể hoàn tác."},{"en":"Their meeting helped start a process of reconciliation between rivals.","vi":"Cuộc gặp của họ giúp bắt đầu một quy trình hòa giải giữa các đối thủ."}]','[]',NULL,'/stɑːrt ə ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5499,'colloc-15-01',109,'state explicitly','nêu rõ ràng','v + adv','[{"en":"The contract does not state explicitly who pays for repairs.","vi":"Hợp đồng không nêu rõ ràng ai sẽ trả tiền sửa chữa."},{"en":"The author fails to state explicitly the goal of the study.","vi":"Tác giả không nêu rõ ràng mục tiêu của nghiên cứu."},{"en":"Please state explicitly which option you prefer.","vi":"Vui lòng nêu rõ ràng bạn thích phương án nào."}]','[]',NULL,'/steɪt ɪkˈsplɪsɪtli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5500,'colloc-15-01',110,'state sector','khu vực nhà nước','n + n','[{"en":"Many graduates choose careers in the state sector for job security.","vi":"Nhiều sinh viên tốt nghiệp chọn nghề trong khu vực nhà nước vì sự ổn định."},{"en":"Wages in the state sector are often lower than private firms.","vi":"Tiền lương ở khu vực nhà nước thường thấp hơn các công ty tư nhân."},{"en":"The reform reduced the size of the state sector significantly.","vi":"Cuộc cải cách đã giảm đáng kể quy mô của khu vực nhà nước."}]','[]',NULL,'/steɪt ˈsektər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5501,'colloc-15-01',111,'statistical analysis','phân tích thống kê','adj + n','[{"en":"The researchers performed a statistical analysis of the survey results.","vi":"Các nhà nghiên cứu thực hiện phân tích thống kê các kết quả khảo sát."},{"en":"Statistical analysis revealed a strong link between the two variables.","vi":"Phân tích thống kê cho thấy mối liên hệ chặt chẽ giữa hai biến số."},{"en":"She used software to speed up the statistical analysis.","vi":"Cô dùng phần mềm để tăng tốc độ phân tích thống kê."}]','[]',NULL,'/stəˈtɪstɪkəl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5502,'colloc-15-01',112,'statistical data','dữ liệu thống kê','adj + n','[{"en":"The government collects statistical data on employment every month.","vi":"Chính phủ thu thập dữ liệu thống kê về việc làm hằng tháng."},{"en":"Reliable statistical data is essential for good policy decisions.","vi":"Dữ liệu thống kê đáng tin cậy rất cần thiết cho các quyết định chính sách tốt."},{"en":"The report presents statistical data in clear, simple charts.","vi":"Báo cáo trình bày dữ liệu thống kê bằng các biểu đồ rõ ràng, đơn giản."}]','[]',NULL,'/stəˈtɪstɪkəl ˈdætə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5503,'colloc-15-01',113,'statistical information','thông tin thống kê','adj + n','[{"en":"The website offers detailed statistical information about population growth.","vi":"Trang web cung cấp thông tin thống kê chi tiết về tăng trưởng dân số."},{"en":"Journalists rely on statistical information to support their stories.","vi":"Các nhà báo dựa vào thông tin thống kê để hỗ trợ các bài viết của họ."},{"en":"The agency publishes statistical information once every year.","vi":"Cơ quan này công bố thông tin thống kê mỗi năm một lần."}]','[]',NULL,'/stəˈtɪstɪkəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5504,'colloc-15-01',114,'statistical method','phương pháp thống kê','adj + n','[{"en":"The team applied a modern statistical method to the dataset.","vi":"Nhóm đã áp dụng một phương pháp thống kê hiện đại cho tập dữ liệu."},{"en":"Choosing the right statistical method depends on your research question.","vi":"Việc chọn phương pháp thống kê phù hợp phụ thuộc vào câu hỏi nghiên cứu của bạn."},{"en":"The course teaches each statistical method with practical examples.","vi":"Khóa học dạy từng phương pháp thống kê kèm các ví dụ thực tế."}]','[]',NULL,'/stəˈtɪstɪkəl ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5505,'colloc-15-01',115,'statistical significance','ý nghĩa thống kê','adj + n','[{"en":"The results reached statistical significance at the chosen level.","vi":"Kết quả đạt ý nghĩa thống kê ở mức đã chọn."},{"en":"Without statistical significance, the findings cannot be trusted fully.","vi":"Nếu không có ý nghĩa thống kê, các phát hiện không thể được tin tưởng hoàn toàn."},{"en":"The professor explained how to test for statistical significance.","vi":"Giáo sư giải thích cách kiểm tra ý nghĩa thống kê."}]','[]',NULL,'/stəˈtɪstɪkəl sɪɡˈnɪfɪkəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5506,'colloc-15-01',116,'statistical technique','kỹ thuật thống kê','adj + n','[{"en":"Analysts used an advanced statistical technique to detect the pattern.","vi":"Các nhà phân tích dùng một kỹ thuật thống kê nâng cao để phát hiện mẫu hình."},{"en":"This statistical technique works best with very large samples.","vi":"Kỹ thuật thống kê này hoạt động tốt nhất với các mẫu rất lớn."},{"en":"The workshop introduced several useful statistical techniques.","vi":"Hội thảo giới thiệu một số kỹ thuật thống kê hữu ích."}]','[]',NULL,'/stəˈtɪstɪkəl tekˈniːk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5507,'colloc-15-01',117,'statistical test','kiểm định thống kê','adj + n','[{"en":"They ran a statistical test to compare the two groups.","vi":"Họ chạy một kiểm định thống kê để so sánh hai nhóm."},{"en":"Choosing an appropriate statistical test is a crucial step.","vi":"Chọn một kiểm định thống kê phù hợp là một bước quan trọng."},{"en":"The statistical test confirmed that the difference was real.","vi":"Kiểm định thống kê xác nhận rằng sự khác biệt là thật."}]','[]',NULL,'/stəˈtɪstɪkəl test/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5508,'colloc-15-01',118,'statistically significant','có ý nghĩa thống kê','adv + adj','[{"en":"The difference between the groups was statistically significant.","vi":"Sự khác biệt giữa các nhóm là có ý nghĩa thống kê."},{"en":"A statistically significant result still needs careful interpretation.","vi":"Một kết quả có ý nghĩa thống kê vẫn cần được diễn giải cẩn thận."},{"en":"The trend was clear but not statistically significant.","vi":"Xu hướng rất rõ nhưng không có ý nghĩa thống kê."}]','[]',NULL,'/stəˈtɪstɪkli sɪɡˈnɪfɪkənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5509,'colloc-15-01',119,'store data','lưu trữ dữ liệu','v + n','[{"en":"Companies must store data securely to protect their customers.","vi":"Các công ty phải lưu trữ dữ liệu an toàn để bảo vệ khách hàng."},{"en":"The hospital uses servers to store data about every patient.","vi":"Bệnh viện dùng máy chủ để lưu trữ dữ liệu về mỗi bệnh nhân."},{"en":"Researchers store data in the cloud so it never gets lost.","vi":"Các nhà nghiên cứu lưu trữ dữ liệu trên đám mây để không bao giờ bị mất."}]','[]',NULL,'/stɔːr ˈdætə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5510,'colloc-15-01',120,'store information','lưu trữ thông tin','v + n','[{"en":"The brain can store information for many years.","vi":"Bộ não có thể lưu trữ thông tin trong nhiều năm."},{"en":"We use a database to store information about all our members.","vi":"Chúng tôi dùng cơ sở dữ liệu để lưu trữ thông tin về tất cả thành viên."},{"en":"Libraries store information in both printed and digital forms.","vi":"Các thư viện lưu trữ thông tin ở cả dạng in và dạng kỹ thuật số."}]','[]',NULL,'/stɔːr ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5511,'colloc-15-01',121,'strategic decision','quyết định chiến lược','adj + n','[{"en":"The board made a strategic decision to enter the Asian market.","vi":"Hội đồng quản trị đưa ra một quyết định chiến lược để gia nhập thị trường châu Á."},{"en":"Every strategic decision should be based on careful analysis.","vi":"Mỗi quyết định chiến lược nên dựa trên phân tích cẩn thận."},{"en":"Closing the old factory was a difficult strategic decision.","vi":"Đóng cửa nhà máy cũ là một quyết định chiến lược khó khăn."}]','[]',NULL,'/strəˈtiːdʒɪk dɪˈsɪʒən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5512,'colloc-15-01',122,'strategic importance','tầm quan trọng chiến lược','adj + n','[{"en":"The port has great strategic importance for international trade.","vi":"Cảng có tầm quan trọng chiến lược lớn đối với thương mại quốc tế."},{"en":"Both nations recognized the strategic importance of the region.","vi":"Cả hai quốc gia đều nhận ra tầm quan trọng chiến lược của khu vực."},{"en":"The bridge holds strategic importance during times of conflict.","vi":"Cây cầu có tầm quan trọng chiến lược trong thời kỳ xung đột."}]','[]',NULL,'/strəˈtiːdʒɪk ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5513,'colloc-15-01',123,'strategic management','quản trị chiến lược','adj + n','[{"en":"The company hired consultants to improve its strategic management practices.","vi":"Công ty thuê tư vấn để cải thiện hoạt động quản trị chiến lược."},{"en":"Good strategic management helps firms adapt to changing markets quickly.","vi":"Quản trị chiến lược tốt giúp doanh nghiệp thích ứng nhanh với thị trường."},{"en":"Her thesis examines strategic management in small technology startups.","vi":"Luận văn của cô nghiên cứu quản trị chiến lược tại các startup công nghệ nhỏ."}]','[]',NULL,'/strəˈtiːdʒɪk ˈmænɪdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5514,'colloc-15-01',124,'strategic objective','mục tiêu chiến lược','adj + n','[{"en":"The board defined three strategic objectives for the coming year.","vi":"Hội đồng quản trị xác định ba mục tiêu chiến lược cho năm tới."},{"en":"Every department must align its work with the strategic objectives.","vi":"Mỗi phòng ban phải gắn công việc của mình với các mục tiêu chiến lược."},{"en":"Achieving the strategic objective required significant investment and planning.","vi":"Đạt được mục tiêu chiến lược đòi hỏi đầu tư và lập kế hoạch đáng kể."}]','[]',NULL,'/strəˈtiːdʒɪk əbˈdʒektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5515,'colloc-15-01',125,'strategic planning','lập kế hoạch chiến lược','adj + n','[{"en":"Effective strategic planning prepares organizations for future challenges.","vi":"Lập kế hoạch chiến lược hiệu quả giúp tổ chức sẵn sàng cho thách thức tương lai."},{"en":"The team spent two days on strategic planning for the project.","vi":"Nhóm đã dành hai ngày để lập kế hoạch chiến lược cho dự án."},{"en":"Strategic planning involves setting goals and allocating resources wisely.","vi":"Lập kế hoạch chiến lược bao gồm đặt mục tiêu và phân bổ nguồn lực hợp lý."}]','[]',NULL,'/strəˈtiːdʒɪk ˈplænɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5516,'colloc-15-01',126,'stress level','mức độ căng thẳng','n + n','[{"en":"Students reported higher stress levels during the exam period.","vi":"Sinh viên cho biết mức độ căng thẳng cao hơn trong kỳ thi."},{"en":"Regular exercise can significantly reduce daily stress levels.","vi":"Tập thể dục đều đặn có thể giảm đáng kể mức độ căng thẳng hằng ngày."},{"en":"The survey measured stress levels among full-time hospital nurses.","vi":"Khảo sát đo lường mức độ căng thẳng ở các y tá bệnh viện làm toàn thời gian."}]','[]',NULL,'/ˈstres ˈlevəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5517,'colloc-15-01',127,'striking contrast','sự tương phản rõ rệt','adj + n','[{"en":"There is a striking contrast between the two cities'' economies.","vi":"Có sự tương phản rõ rệt giữa nền kinh tế của hai thành phố."},{"en":"The results stand in striking contrast to earlier findings.","vi":"Kết quả tương phản rõ rệt với những phát hiện trước đây."},{"en":"Her bright painting offered a striking contrast to the gray walls.","vi":"Bức tranh tươi sáng của cô tương phản rõ rệt với những bức tường xám."}]','[]',NULL,'/ˈstraɪkɪŋ ˈkɑːntræst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5518,'colloc-15-01',128,'striking example','ví dụ điển hình nổi bật','adj + n','[{"en":"This case is a striking example of successful urban planning.","vi":"Trường hợp này là một ví dụ nổi bật về quy hoạch đô thị thành công."},{"en":"The author gives a striking example to illustrate her point.","vi":"Tác giả đưa ra một ví dụ nổi bật để minh họa luận điểm của mình."},{"en":"The bridge remains a striking example of modern engineering.","vi":"Cây cầu vẫn là một ví dụ nổi bật về kỹ thuật hiện đại."}]','[]',NULL,'/ˈstraɪkɪŋ ɪɡˈzæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5519,'colloc-15-01',129,'striking feature','đặc điểm nổi bật','adj + n','[{"en":"The most striking feature of the design is its simplicity.","vi":"Đặc điểm nổi bật nhất của thiết kế là sự đơn giản của nó."},{"en":"A striking feature of this region is its rich biodiversity.","vi":"Một đặc điểm nổi bật của vùng này là sự đa dạng sinh học phong phú."},{"en":"The building''s curved roof is its most striking feature.","vi":"Mái cong của tòa nhà là đặc điểm nổi bật nhất của nó."}]','[]',NULL,'/ˈstraɪkɪŋ ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5520,'colloc-15-01',130,'strong bond','mối liên kết bền chặt','adj + n','[{"en":"Shared experiences create a strong bond between team members.","vi":"Trải nghiệm chung tạo nên mối liên kết bền chặt giữa các thành viên."},{"en":"The children formed a strong bond with their new teacher.","vi":"Những đứa trẻ hình thành mối liên kết bền chặt với giáo viên mới."},{"en":"A strong bond between parents and children supports healthy development.","vi":"Mối liên kết bền chặt giữa cha mẹ và con cái hỗ trợ sự phát triển lành mạnh."}]','[]',NULL,'/ˈstrɔːŋ ˈbɑːnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5521,'colloc-15-01',131,'strong correlation','mối tương quan chặt chẽ','adj + n','[{"en":"The study found a strong correlation between exercise and mood.","vi":"Nghiên cứu tìm thấy mối tương quan chặt chẽ giữa vận động và tâm trạng."},{"en":"There is a strong correlation between education and income levels.","vi":"Có mối tương quan chặt chẽ giữa trình độ học vấn và mức thu nhập."},{"en":"Researchers reported a strong correlation between sleep and memory.","vi":"Các nhà nghiên cứu báo cáo mối tương quan chặt chẽ giữa giấc ngủ và trí nhớ."}]','[]',NULL,'/ˈstrɔːŋ ˌkɔːrəˈleɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5522,'colloc-15-01',132,'strong emphasis','sự nhấn mạnh mạnh mẽ','adj + n','[{"en":"The program places strong emphasis on practical, hands-on learning.","vi":"Chương trình đặt sự nhấn mạnh mạnh mẽ vào học tập thực hành."},{"en":"Her lecture put strong emphasis on the importance of evidence.","vi":"Bài giảng của cô nhấn mạnh mạnh mẽ tầm quan trọng của bằng chứng."},{"en":"The school has a strong emphasis on teamwork and respect.","vi":"Trường học nhấn mạnh mạnh mẽ vào tinh thần đồng đội và sự tôn trọng."}]','[]',NULL,'/ˈstrɔːŋ ˈemfəsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5523,'colloc-15-01',133,'strong evidence','bằng chứng thuyết phục','adj + n','[{"en":"The data provide strong evidence for the new theory.","vi":"Dữ liệu cung cấp bằng chứng thuyết phục cho lý thuyết mới."},{"en":"There is strong evidence linking smoking to several diseases.","vi":"Có bằng chứng thuyết phục liên hệ hút thuốc với một số bệnh."},{"en":"Scientists need strong evidence before accepting any bold claim.","vi":"Các nhà khoa học cần bằng chứng thuyết phục trước khi chấp nhận một tuyên bố táo bạo."}]','[]',NULL,'/ˈstrɔːŋ ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5524,'colloc-15-01',134,'strong link','mối liên hệ chặt chẽ','adj + n','[{"en":"Research shows a strong link between diet and overall health.","vi":"Nghiên cứu cho thấy mối liên hệ chặt chẽ giữa chế độ ăn và sức khỏe."},{"en":"There is a strong link between poverty and poor education.","vi":"Có mối liên hệ chặt chẽ giữa nghèo đói và giáo dục kém."},{"en":"The report highlights a strong link between stress and illness.","vi":"Báo cáo nêu bật mối liên hệ chặt chẽ giữa căng thẳng và bệnh tật."}]','[]',NULL,'/ˈstrɔːŋ ˈlɪŋk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5525,'colloc-15-01',135,'strong reaction','phản ứng mạnh mẽ','adj + n','[{"en":"The new policy provoked a strong reaction from local residents.","vi":"Chính sách mới gây ra phản ứng mạnh mẽ từ người dân địa phương."},{"en":"Her speech triggered a strong reaction among the students.","vi":"Bài phát biểu của cô khơi dậy phản ứng mạnh mẽ trong sinh viên."},{"en":"The film received a strong reaction from both critics and audiences.","vi":"Bộ phim nhận được phản ứng mạnh mẽ từ cả giới phê bình lẫn khán giả."}]','[]',NULL,'/ˈstrɔːŋ riˈækʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5526,'colloc-15-01',136,'strong relationship','mối quan hệ bền chặt','adj + n','[{"en":"The company built a strong relationship with its loyal customers.","vi":"Công ty xây dựng mối quan hệ bền chặt với khách hàng trung thành."},{"en":"A strong relationship with mentors helps young researchers grow.","vi":"Mối quan hệ bền chặt với người hướng dẫn giúp nhà nghiên cứu trẻ phát triển."},{"en":"There is a strong relationship between trust and effective teamwork.","vi":"Có mối quan hệ bền chặt giữa sự tin tưởng và làm việc nhóm hiệu quả."}]','[]',NULL,'/ˈstrɔːŋ rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5527,'colloc-15-01',137,'strong tendency','xu hướng rõ rệt','adj + n','[{"en":"There is a strong tendency for prices to rise in winter.","vi":"Có một xu hướng rõ rệt là giá cả tăng vào mùa đông."},{"en":"The data show a strong tendency toward urban migration.","vi":"Dữ liệu cho thấy xu hướng rõ rệt về di cư ra thành thị."},{"en":"Young people show a strong tendency to adopt new technologies.","vi":"Người trẻ thể hiện xu hướng rõ rệt trong việc tiếp nhận công nghệ mới."}]','[]',NULL,'/ˈstrɔːŋ ˈtendənsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5528,'colloc-15-01',138,'strongly agree','hoàn toàn đồng ý','adv + v','[{"en":"Most participants strongly agree that the new rule is fair.","vi":"Phần lớn người tham gia hoàn toàn đồng ý rằng quy định mới là công bằng."},{"en":"I strongly agree with the author''s main argument here.","vi":"Tôi hoàn toàn đồng ý với luận điểm chính của tác giả ở đây."},{"en":"Many teachers strongly agree that smaller classes improve learning.","vi":"Nhiều giáo viên hoàn toàn đồng ý rằng lớp nhỏ giúp cải thiện việc học."}]','[]',NULL,'/ˈstrɔːŋli əˈɡriː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5529,'colloc-15-01',139,'strongly associated with','có liên hệ chặt chẽ với','adv + vpp','[{"en":"High blood pressure is strongly associated with heart disease.","vi":"Huyết áp cao có liên hệ chặt chẽ với bệnh tim."},{"en":"Poverty is strongly associated with limited access to education.","vi":"Nghèo đói có liên hệ chặt chẽ với việc tiếp cận giáo dục hạn chế."},{"en":"These symptoms are strongly associated with prolonged stress.","vi":"Những triệu chứng này có liên hệ chặt chẽ với căng thẳng kéo dài."}]','[]',NULL,'/ˈstrɔːŋli əˈsoʊsieɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5530,'colloc-15-01',140,'strongly correlated with','tương quan chặt chẽ với','adv + vpp','[{"en":"Income is strongly correlated with access to quality healthcare.","vi":"Thu nhập tương quan chặt chẽ với việc tiếp cận chăm sóc y tế chất lượng."},{"en":"Study time is strongly correlated with exam performance.","vi":"Thời gian học tương quan chặt chẽ với kết quả thi."},{"en":"Air pollution is strongly correlated with respiratory problems.","vi":"Ô nhiễm không khí tương quan chặt chẽ với các vấn đề hô hấp."}]','[]',NULL,'/ˈstrɔːŋli ˈkɔːrəleɪtɪd wɪð/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5531,'colloc-15-01',141,'strongly disagree','hoàn toàn không đồng ý','adv + v','[{"en":"Several experts strongly disagree with the proposed reform.","vi":"Một số chuyên gia hoàn toàn không đồng ý với cải cách được đề xuất."},{"en":"I strongly disagree with the conclusion of this report.","vi":"Tôi hoàn toàn không đồng ý với kết luận của báo cáo này."},{"en":"Many residents strongly disagree about building the new highway.","vi":"Nhiều cư dân hoàn toàn không đồng ý về việc xây đường cao tốc mới."}]','[]',NULL,'/ˈstrɔːŋli ˌdɪsəˈɡriː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5532,'colloc-15-01',142,'strongly influenced by','chịu ảnh hưởng mạnh mẽ bởi','adv + vpp','[{"en":"Her early work was strongly influenced by classical philosophy.","vi":"Tác phẩm đầu tay của cô chịu ảnh hưởng mạnh mẽ bởi triết học cổ điển."},{"en":"Consumer choices are strongly influenced by online reviews.","vi":"Lựa chọn của người tiêu dùng chịu ảnh hưởng mạnh mẽ bởi đánh giá trực tuyến."},{"en":"His theory was strongly influenced by recent neuroscience research.","vi":"Lý thuyết của ông chịu ảnh hưởng mạnh mẽ bởi nghiên cứu thần kinh học gần đây."}]','[]',NULL,'/ˈstrɔːŋli ˈɪnfluənst baɪ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5533,'colloc-15-01',143,'strongly linked','gắn liền chặt chẽ','adv + vpp','[{"en":"Obesity is strongly linked to several chronic health conditions.","vi":"Béo phì gắn liền chặt chẽ với một số bệnh mãn tính."},{"en":"Economic growth is strongly linked to political stability.","vi":"Tăng trưởng kinh tế gắn liền chặt chẽ với ổn định chính trị."},{"en":"Sleep quality is strongly linked to overall mental health.","vi":"Chất lượng giấc ngủ gắn liền chặt chẽ với sức khỏe tinh thần."}]','[]',NULL,'/ˈstrɔːŋli ˈlɪŋkt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5534,'colloc-15-01',144,'strongly opposed','phản đối mạnh mẽ','adv + vpp','[{"en":"Local farmers were strongly opposed to the new land tax.","vi":"Nông dân địa phương phản đối mạnh mẽ loại thuế đất mới."},{"en":"Many scientists are strongly opposed to cutting research funding.","vi":"Nhiều nhà khoa học phản đối mạnh mẽ việc cắt giảm ngân sách nghiên cứu."},{"en":"The union remained strongly opposed to the wage freeze.","vi":"Công đoàn vẫn phản đối mạnh mẽ việc đóng băng tiền lương."}]','[]',NULL,'/ˈstrɔːŋli əˈpoʊzd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5535,'colloc-15-01',145,'strongly related to','liên quan chặt chẽ tới','adv + vpp','[{"en":"Job satisfaction is strongly related to employee productivity.","vi":"Sự hài lòng trong công việc liên quan chặt chẽ tới năng suất nhân viên."},{"en":"Reading habits are strongly related to vocabulary growth.","vi":"Thói quen đọc liên quan chặt chẽ tới sự phát triển vốn từ vựng."},{"en":"Diet is strongly related to long-term cardiovascular health.","vi":"Chế độ ăn liên quan chặt chẽ tới sức khỏe tim mạch lâu dài."}]','[]',NULL,'/ˈstrɔːŋli rɪˈleɪtɪd tə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5536,'colloc-15-01',146,'strongly suggest','cho thấy rõ ràng','adv + v','[{"en":"The results strongly suggest that the treatment is effective.","vi":"Kết quả cho thấy rõ ràng rằng phương pháp điều trị có hiệu quả."},{"en":"These findings strongly suggest a need for further research.","vi":"Những phát hiện này cho thấy rõ ràng cần nghiên cứu thêm."},{"en":"The evidence strongly suggests a link between the two events.","vi":"Bằng chứng cho thấy rõ ràng có mối liên hệ giữa hai sự kiện."}]','[]',NULL,'/ˈstrɔːŋli səˈdʒest/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5537,'colloc-15-01',147,'structural adjustment','điều chỉnh cơ cấu','adj + n','[{"en":"The government introduced structural adjustment to stabilize the economy.","vi":"Chính phủ tiến hành điều chỉnh cơ cấu để ổn định nền kinh tế."},{"en":"Structural adjustment programs often affect public spending heavily.","vi":"Các chương trình điều chỉnh cơ cấu thường ảnh hưởng mạnh đến chi tiêu công."},{"en":"The bank required structural adjustment before approving the loan.","vi":"Ngân hàng yêu cầu điều chỉnh cơ cấu trước khi phê duyệt khoản vay."}]','[]',NULL,'/ˈstrʌktʃərəl əˈdʒʌstmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5538,'colloc-15-01',148,'structural change','thay đổi cơ cấu','adj + n','[{"en":"The industry underwent major structural change over the decade.","vi":"Ngành đã trải qua sự thay đổi cơ cấu lớn trong thập kỷ qua."},{"en":"Structural change in the economy created new types of jobs.","vi":"Sự thay đổi cơ cấu trong nền kinh tế tạo ra nhiều loại việc làm mới."},{"en":"The reform aimed at deep structural change within the organization.","vi":"Cuộc cải cách nhắm tới sự thay đổi cơ cấu sâu sắc trong tổ chức."}]','[]',NULL,'/ˈstrʌktʃərəl ˈtʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5539,'colloc-15-01',149,'structural element','yếu tố cấu trúc','adj + n','[{"en":"Engineers checked every structural element of the old bridge.","vi":"Các kỹ sư kiểm tra từng yếu tố cấu trúc của cây cầu cũ."},{"en":"Each structural element must support the building''s total weight.","vi":"Mỗi yếu tố cấu trúc phải chịu được toàn bộ trọng lượng của tòa nhà."},{"en":"The essay analyzes the structural elements of the novel.","vi":"Bài luận phân tích các yếu tố cấu trúc của cuốn tiểu thuyết."}]','[]',NULL,'/ˈstrʌktʃərəl ˈelɪmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5540,'colloc-15-01',150,'structural feature','đặc điểm cấu trúc','adj + n','[{"en":"The study compares structural features of several languages.","vi":"Nghiên cứu so sánh các đặc điểm cấu trúc của một số ngôn ngữ."},{"en":"A key structural feature of the cell is its membrane.","vi":"Một đặc điểm cấu trúc quan trọng của tế bào là màng của nó."},{"en":"The architect preserved the building''s original structural features.","vi":"Kiến trúc sư bảo tồn các đặc điểm cấu trúc nguyên bản của tòa nhà."}]','[]',NULL,'/ˈstrʌktʃərəl ˈfiːtʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5541,'colloc-16-01',1,'structural properties','tính chất cấu trúc','adj + n','[{"en":"Scientists tested the structural properties of the new alloy.","vi":"Các nhà khoa học kiểm tra tính chất cấu trúc của hợp kim mới."},{"en":"The structural properties of wood vary with moisture content.","vi":"Tính chất cấu trúc của gỗ thay đổi theo độ ẩm."},{"en":"Understanding structural properties helps engineers design safer materials.","vi":"Hiểu tính chất cấu trúc giúp kỹ sư thiết kế vật liệu an toàn hơn."}]','[]',NULL,'/ˈstrʌktʃərəl ˈprɑːpərtiz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5542,'colloc-16-01',2,'subject area','lĩnh vực môn học','adj + n','[{"en":"Students may choose electives outside their main subject area.","vi":"Sinh viên có thể chọn môn tự chọn ngoài lĩnh vực môn học chính."},{"en":"The conference covered many subject areas within social science.","vi":"Hội nghị bao quát nhiều lĩnh vực môn học trong khoa học xã hội."},{"en":"Each teacher specializes in a particular subject area.","vi":"Mỗi giáo viên chuyên về một lĩnh vực môn học cụ thể."}]','[]',NULL,'/ˈsʌbdʒɪkt ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5543,'colloc-16-01',3,'subsequent analysis','phân tích tiếp theo','adj + n','[{"en":"Subsequent analysis confirmed the patterns seen in early data.","vi":"Phân tích tiếp theo xác nhận các mẫu hình thấy trong dữ liệu ban đầu."},{"en":"The subsequent analysis revealed several unexpected results.","vi":"Phân tích tiếp theo cho thấy một số kết quả bất ngờ."},{"en":"Subsequent analysis will focus on long-term effects of the policy.","vi":"Phân tích tiếp theo sẽ tập trung vào tác động lâu dài của chính sách."}]','[]',NULL,'/ˈsʌbsɪkwənt əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5544,'colloc-16-01',4,'subsequent chapter','chương tiếp theo','adj + n','[{"en":"These issues are discussed in detail in subsequent chapters.","vi":"Những vấn đề này được bàn chi tiết ở các chương tiếp theo."},{"en":"The subsequent chapter explains the methodology in more depth.","vi":"Chương tiếp theo giải thích phương pháp luận sâu hơn."},{"en":"Each subsequent chapter builds on ideas from the previous one.","vi":"Mỗi chương tiếp theo xây dựng dựa trên ý tưởng của chương trước."}]','[]',NULL,'/ˈsʌbsɪkwənt ˈtʃæptər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5545,'colloc-16-01',5,'subsequent development','diễn biến tiếp theo','adj + n','[{"en":"The treaty shaped the subsequent development of the region.","vi":"Hiệp ước định hình diễn biến tiếp theo của khu vực."},{"en":"Subsequent development of the software fixed many early problems.","vi":"Diễn biến phát triển tiếp theo của phần mềm khắc phục nhiều lỗi ban đầu."},{"en":"Historians trace the subsequent development of the movement.","vi":"Các sử gia theo dõi diễn biến tiếp theo của phong trào."}]','[]',NULL,'/ˈsʌbsɪkwənt dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5546,'colloc-16-01',6,'subsequent study','nghiên cứu tiếp theo','adj + n','[{"en":"A subsequent study confirmed the earlier surprising findings.","vi":"Một nghiên cứu tiếp theo xác nhận các phát hiện gây bất ngờ trước đó."},{"en":"Subsequent studies used larger and more diverse samples.","vi":"Các nghiên cứu tiếp theo dùng mẫu lớn hơn và đa dạng hơn."},{"en":"The authors recommend a subsequent study with a control group.","vi":"Các tác giả đề xuất một nghiên cứu tiếp theo có nhóm đối chứng."}]','[]',NULL,'/ˈsʌbsɪkwənt ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5547,'colloc-16-01',7,'subsequent work','công trình tiếp theo','adj + n','[{"en":"Her subsequent work expanded on these initial conclusions.","vi":"Công trình tiếp theo của cô mở rộng từ những kết luận ban đầu này."},{"en":"Subsequent work in the field built directly on his ideas.","vi":"Công trình tiếp theo trong lĩnh vực này dựa trực tiếp vào ý tưởng của ông."},{"en":"The paper laid a foundation for much subsequent work.","vi":"Bài báo đặt nền móng cho nhiều công trình tiếp theo."}]','[]',NULL,'/ˈsʌbsɪkwənt ˈwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5548,'colloc-16-01',8,'substantial amount of','một lượng đáng kể','adj + n','[{"en":"The project required a substantial amount of time and money.","vi":"Dự án đòi hỏi một lượng đáng kể thời gian và tiền bạc."},{"en":"Researchers collected a substantial amount of survey data.","vi":"Các nhà nghiên cứu thu thập một lượng đáng kể dữ liệu khảo sát."},{"en":"A substantial amount of evidence supports this conclusion.","vi":"Một lượng đáng kể bằng chứng ủng hộ kết luận này."}]','[]',NULL,'/səbˈstænʃəl əˈmaʊnt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5549,'colloc-16-01',9,'substantial difference','sự khác biệt đáng kể','adj + n','[{"en":"There is a substantial difference between the two methods.","vi":"Có một sự khác biệt đáng kể giữa hai phương pháp."},{"en":"The study found a substantial difference in test scores.","vi":"Nghiên cứu tìm thấy sự khác biệt đáng kể về điểm kiểm tra."},{"en":"A substantial difference in income separates the two regions.","vi":"Một sự khác biệt đáng kể về thu nhập chia tách hai khu vực."}]','[]',NULL,'/səbˈstænʃəl ˈdɪfərəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5550,'colloc-16-01',10,'substantial evidence','bằng chứng đáng kể','adj + n','[{"en":"There is substantial evidence supporting the new approach.","vi":"Có bằng chứng đáng kể ủng hộ phương pháp mới."},{"en":"The court found substantial evidence of wrongdoing.","vi":"Tòa án tìm thấy bằng chứng đáng kể về hành vi sai trái."},{"en":"Substantial evidence shows that exercise improves mental health.","vi":"Bằng chứng đáng kể cho thấy tập thể dục cải thiện sức khỏe tinh thần."}]','[]',NULL,'/səbˈstænʃəl ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5551,'colloc-16-01',11,'substantial number','một số lượng đáng kể','adj + n','[{"en":"A substantial number of students passed the difficult exam.","vi":"Một số lượng đáng kể sinh viên đã vượt qua kỳ thi khó."},{"en":"The survey reached a substantial number of households nationwide.","vi":"Khảo sát tiếp cận một số lượng đáng kể hộ gia đình trên toàn quốc."},{"en":"A substantial number of jobs depend on the local factory.","vi":"Một số lượng đáng kể việc làm phụ thuộc vào nhà máy địa phương."}]','[]',NULL,'/səbˈstænʃəl ˈnʌmbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5552,'colloc-16-01',12,'substantial part','một phần đáng kể','adj + n','[{"en":"A substantial part of the budget goes toward research.","vi":"Một phần đáng kể ngân sách được dành cho nghiên cứu."},{"en":"She spent a substantial part of her career studying bees.","vi":"Cô dành một phần đáng kể sự nghiệp để nghiên cứu loài ong."},{"en":"A substantial part of the population lives in rural areas.","vi":"Một phần đáng kể dân số sống ở khu vực nông thôn."}]','[]',NULL,'/səbˈstænʃəl ˈpɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5553,'colloc-16-01',13,'substantially different','khác biệt đáng kể','adv + adj','[{"en":"The two samples produced substantially different results.","vi":"Hai mẫu cho ra những kết quả khác biệt đáng kể."},{"en":"Her conclusions are substantially different from earlier studies.","vi":"Kết luận của cô khác biệt đáng kể so với các nghiên cứu trước."},{"en":"Life in the city is substantially different from rural life.","vi":"Cuộc sống ở thành phố khác biệt đáng kể so với nông thôn."}]','[]',NULL,'/səbˈstænʃəli ˈdɪfərənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5554,'colloc-16-01',14,'successful implementation','việc triển khai thành công','adj + n','[{"en":"Successful implementation of the plan depends on strong leadership.","vi":"Việc triển khai thành công kế hoạch phụ thuộc vào sự lãnh đạo vững mạnh."},{"en":"Training was key to the successful implementation of the system.","vi":"Đào tạo là yếu tố then chốt cho việc triển khai thành công hệ thống."},{"en":"The report describes the successful implementation of the reform.","vi":"Báo cáo mô tả việc triển khai thành công cuộc cải cách."}]','[]',NULL,'/səkˈsesfəl ˌɪmplɪmenˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5555,'colloc-16-01',15,'sufficient condition','điều kiện đủ','adj + n','[{"en":"Hard work alone is not a sufficient condition for success.","vi":"Chỉ chăm chỉ thôi không phải là điều kiện đủ để thành công."},{"en":"The author distinguishes necessary from sufficient conditions.","vi":"Tác giả phân biệt điều kiện cần với điều kiện đủ."},{"en":"Funding is a sufficient condition for starting the project.","vi":"Kinh phí là điều kiện đủ để khởi động dự án."}]','[]',NULL,'/səˈfɪʃənt kənˈdɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5556,'colloc-16-01',16,'sufficient detail','đủ chi tiết','adj + n','[{"en":"The method is described in sufficient detail to be repeated.","vi":"Phương pháp được mô tả đủ chi tiết để có thể lặp lại."},{"en":"Please provide sufficient detail in your project proposal.","vi":"Vui lòng cung cấp đủ chi tiết trong đề xuất dự án của bạn."},{"en":"The report lacks sufficient detail about the data sources.","vi":"Báo cáo thiếu đủ chi tiết về các nguồn dữ liệu."}]','[]',NULL,'/səˈfɪʃənt ˈdiːteɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5557,'colloc-16-01',17,'sufficient evidence','bằng chứng đầy đủ','adj + n','[{"en":"There is not yet sufficient evidence to support the claim.","vi":"Vẫn chưa có đủ bằng chứng để ủng hộ tuyên bố này."},{"en":"The jury found sufficient evidence to reach a verdict.","vi":"Bồi thẩm đoàn tìm thấy đủ bằng chứng để đưa ra phán quyết."},{"en":"Researchers need sufficient evidence before publishing conclusions.","vi":"Các nhà nghiên cứu cần đủ bằng chứng trước khi công bố kết luận."}]','[]',NULL,'/səˈfɪʃənt ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5558,'colloc-16-01',18,'sufficient information','đủ thông tin','adj + n','[{"en":"We did not have sufficient information to make a decision.","vi":"Chúng tôi không có đủ thông tin để đưa ra quyết định."},{"en":"The form must contain sufficient information for verification.","vi":"Biểu mẫu phải chứa đủ thông tin để xác minh."},{"en":"Patients need sufficient information about possible side effects.","vi":"Bệnh nhân cần đủ thông tin về các tác dụng phụ có thể xảy ra."}]','[]',NULL,'/səˈfɪʃənt ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5559,'colloc-16-01',19,'sufficient resources','đủ nguồn lực','adj + n','[{"en":"The school lacks sufficient resources to support every student.","vi":"Trường thiếu đủ nguồn lực để hỗ trợ mọi học sinh."},{"en":"Without sufficient resources, the program cannot expand further.","vi":"Không có đủ nguồn lực, chương trình không thể mở rộng thêm."},{"en":"Managers must ensure teams have sufficient resources to succeed.","vi":"Người quản lý phải đảm bảo các nhóm có đủ nguồn lực để thành công."}]','[]',NULL,'/səˈfɪʃənt ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5560,'colloc-16-01',20,'superior performance','hiệu suất vượt trội','adj + n','[{"en":"The new engine delivers superior performance at lower cost.","vi":"Động cơ mới mang lại hiệu suất vượt trội với chi phí thấp hơn."},{"en":"The study attributes superior performance to better training.","vi":"Nghiên cứu cho rằng hiệu suất vượt trội đến từ việc đào tạo tốt hơn."},{"en":"Her team''s superior performance earned them the top award.","vi":"Hiệu suất vượt trội của nhóm cô giành được giải thưởng cao nhất."}]','[]',NULL,'/suːˈpɪriər pərˈfɔːrməns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5561,'colloc-16-01',21,'support an argument','củng cố một luận điểm','v + n','[{"en":"Use reliable data to support an argument in your essay.","vi":"Dùng dữ liệu đáng tin cậy để củng cố một luận điểm trong bài luận."},{"en":"The author cites several studies to support an argument.","vi":"Tác giả trích dẫn vài nghiên cứu để củng cố một luận điểm."},{"en":"Strong examples help support an argument more convincingly.","vi":"Những ví dụ mạnh giúp củng cố một luận điểm thuyết phục hơn."}]','[]',NULL,'/səˈpɔːrt ən ˈɑːrɡjumənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5562,'colloc-16-01',22,'supporting evidence','bằng chứng hỗ trợ','adj + n','[{"en":"Each claim should be backed by clear supporting evidence.","vi":"Mỗi tuyên bố nên được hậu thuẫn bằng bằng chứng hỗ trợ rõ ràng."},{"en":"The essay presents strong supporting evidence for its thesis.","vi":"Bài luận trình bày bằng chứng hỗ trợ mạnh mẽ cho luận đề của nó."},{"en":"Reviewers asked for more supporting evidence in the paper.","vi":"Người phản biện yêu cầu thêm bằng chứng hỗ trợ trong bài báo."}]','[]',NULL,'/səˈpɔːrtɪŋ ˈevɪdəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5563,'colloc-16-01',23,'survey data','dữ liệu khảo sát','n + n','[{"en":"The researchers analyzed survey data from over a thousand people.","vi":"Các nhà nghiên cứu phân tích dữ liệu khảo sát từ hơn một nghìn người."},{"en":"Survey data revealed clear trends in consumer behavior.","vi":"Dữ liệu khảo sát cho thấy các xu hướng rõ ràng trong hành vi tiêu dùng."},{"en":"We must check the survey data carefully for errors.","vi":"Chúng ta phải kiểm tra dữ liệu khảo sát cẩn thận để tìm lỗi."}]','[]',NULL,'/ˈsɜːrveɪ ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5564,'colloc-16-01',24,'symbiotic relationship','mối quan hệ cộng sinh','adj + n','[{"en":"Bees and flowers share a fascinating symbiotic relationship.","vi":"Ong và hoa có một mối quan hệ cộng sinh thú vị."},{"en":"The two companies developed a symbiotic relationship over time.","vi":"Hai công ty phát triển một mối quan hệ cộng sinh theo thời gian."},{"en":"A symbiotic relationship benefits both species involved.","vi":"Mối quan hệ cộng sinh mang lại lợi ích cho cả hai loài liên quan."}]','[]',NULL,'/ˌsɪmbaɪˈɑːtɪk rɪˈleɪʃənʃɪp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5565,'colloc-16-01',25,'systematic analysis','phân tích có hệ thống','adj + n','[{"en":"A systematic analysis of the data revealed hidden patterns.","vi":"Phân tích có hệ thống dữ liệu cho thấy các mẫu hình tiềm ẩn."},{"en":"The team conducted a systematic analysis of past research.","vi":"Nhóm tiến hành phân tích có hệ thống các nghiên cứu trước."},{"en":"Systematic analysis reduces the risk of biased conclusions.","vi":"Phân tích có hệ thống giảm nguy cơ kết luận thiên lệch."}]','[]',NULL,'/ˌsɪstəˈmætɪk əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5566,'colloc-16-01',26,'systematic approach','phương pháp có hệ thống','adj + n','[{"en":"A systematic approach helps solve complex problems step by step.","vi":"Phương pháp có hệ thống giúp giải quyết vấn đề phức tạp từng bước."},{"en":"The lab follows a systematic approach to testing samples.","vi":"Phòng thí nghiệm theo một phương pháp có hệ thống để kiểm tra mẫu."},{"en":"She recommends a systematic approach to reviewing the literature.","vi":"Cô đề xuất một phương pháp có hệ thống để rà soát tài liệu."}]','[]',NULL,'/ˌsɪstəˈmætɪk əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5567,'colloc-16-01',27,'systematic study','nghiên cứu có hệ thống','adj + n','[{"en":"The book offers a systematic study of urban migration patterns.","vi":"Cuốn sách cung cấp một nghiên cứu có hệ thống về các mẫu di cư đô thị."},{"en":"A systematic study requires careful planning and consistent methods.","vi":"Một nghiên cứu có hệ thống đòi hỏi lập kế hoạch cẩn thận và phương pháp nhất quán."},{"en":"Her systematic study of the language took several years.","vi":"Nghiên cứu có hệ thống của cô về ngôn ngữ kéo dài vài năm."}]','[]',NULL,'/ˌsɪstəˈmætɪk ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5568,'colloc-16-01',28,'tacit knowledge','tri thức ngầm','adj + n','[{"en":"Much expert skill relies on tacit knowledge gained through practice.","vi":"Nhiều kỹ năng chuyên gia dựa vào tri thức ngầm có được qua thực hành."},{"en":"Tacit knowledge is hard to write down or fully explain.","vi":"Tri thức ngầm rất khó viết ra hay giải thích đầy đủ."},{"en":"Experienced workers share tacit knowledge through close mentoring.","vi":"Người lao động giàu kinh nghiệm truyền tri thức ngầm qua việc kèm cặp sát sao."}]','[]',NULL,'/ˈtæsɪt ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5569,'colloc-16-01',29,'take initiative','chủ động hành động','v + n','[{"en":"Good leaders encourage their staff to take initiative.","vi":"Người lãnh đạo giỏi khuyến khích nhân viên chủ động hành động."},{"en":"She decided to take initiative and propose a new plan.","vi":"Cô quyết định chủ động hành động và đề xuất một kế hoạch mới."},{"en":"Students who take initiative often learn more independently.","vi":"Những sinh viên chủ động hành động thường học độc lập hơn."}]','[]',NULL,'/ˈteɪk ɪˈnɪʃətɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5570,'colloc-16-01',30,'take precedence over','được ưu tiên hơn','v + n','[{"en":"Safety must take precedence over speed on any construction site.","vi":"An toàn phải được ưu tiên hơn tốc độ tại mọi công trường xây dựng."},{"en":"Urgent tasks usually take precedence over routine ones.","vi":"Các nhiệm vụ khẩn cấp thường được ưu tiên hơn việc thường ngày."},{"en":"Patient care should take precedence over administrative paperwork.","vi":"Chăm sóc bệnh nhân nên được ưu tiên hơn giấy tờ hành chính."}]','[]',NULL,'/ˈteɪk ˈpresɪdəns ˈoʊvər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5571,'colloc-16-01',31,'take responsibility','chịu trách nhiệm','v + n','[{"en":"Managers must take responsibility for their team''s mistakes.","vi":"Người quản lý phải chịu trách nhiệm về sai lầm của nhóm mình."},{"en":"He was willing to take responsibility for the failed project.","vi":"Anh ấy sẵn sàng chịu trách nhiệm về dự án thất bại."},{"en":"Citizens should take responsibility for protecting the environment.","vi":"Người dân nên chịu trách nhiệm bảo vệ môi trường."}]','[]',NULL,'/ˈteɪk rɪˌspɑːnsəˈbɪləti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5572,'colloc-16-01',32,'take a role in','đóng vai trò trong','v + n','[{"en":"Parents should take a role in their children''s education.","vi":"Cha mẹ nên đóng vai trò trong việc giáo dục con cái."},{"en":"Volunteers take a role in organizing the annual festival.","vi":"Các tình nguyện viên đóng vai trò trong việc tổ chức lễ hội hằng năm."},{"en":"She hopes to take a role in shaping company policy.","vi":"Cô hy vọng được đóng vai trò trong việc định hình chính sách công ty."}]','[]',NULL,'/ˈteɪk ə ˈroʊl ɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5573,'colloc-16-01',33,'take an approach','áp dụng một cách tiếp cận','v + n','[{"en":"The researchers decided to take a different approach this time.","vi":"Các nhà nghiên cứu quyết định áp dụng một cách tiếp cận khác lần này."},{"en":"We should take a more practical approach to the problem.","vi":"Chúng ta nên áp dụng một cách tiếp cận thực tế hơn với vấn đề."},{"en":"Teachers can take an approach suited to each student''s needs.","vi":"Giáo viên có thể áp dụng một cách tiếp cận phù hợp với nhu cầu từng học sinh."}]','[]',NULL,'/ˈteɪk ən əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5574,'colloc-16-01',34,'take into consideration','cân nhắc đến','v + n','[{"en":"We must take into consideration the needs of every student.","vi":"Chúng ta phải cân nhắc đến nhu cầu của mọi học sinh."},{"en":"The plan takes into consideration both cost and safety.","vi":"Kế hoạch cân nhắc đến cả chi phí lẫn an toàn."},{"en":"Judges take into consideration the circumstances of each case.","vi":"Thẩm phán cân nhắc đến hoàn cảnh của từng vụ việc."}]','[]',NULL,'/ˈteɪk ˌɪntə kənˌsɪdəˈreɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5575,'colloc-16-01',35,'take on the role of','đảm nhận vai trò','v + n','[{"en":"She agreed to take on the role of team leader.","vi":"Cô đồng ý đảm nhận vai trò trưởng nhóm."},{"en":"He will take on the role of project coordinator next month.","vi":"Anh ấy sẽ đảm nhận vai trò điều phối dự án vào tháng tới."},{"en":"New graduates often take on the role of junior analyst.","vi":"Sinh viên mới ra trường thường đảm nhận vai trò chuyên viên phân tích cấp dưới."}]','[]',NULL,'/ˈteɪk ˈɑːn ðə ˈroʊl əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5576,'colloc-16-01',36,'take up the role of','tiếp nhận vai trò','v + n','[{"en":"He will take up the role of department head in July.","vi":"Ông sẽ tiếp nhận vai trò trưởng khoa vào tháng Bảy."},{"en":"She was asked to take up the role of mentor.","vi":"Cô được đề nghị tiếp nhận vai trò người hướng dẫn."},{"en":"After retirement, he took up the role of adviser.","vi":"Sau khi nghỉ hưu, ông tiếp nhận vai trò cố vấn."}]','[]',NULL,'/ˈteɪk ˈʌp ðə ˈroʊl əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5577,'colloc-16-01',37,'target audience','đối tượng mục tiêu','n + n','[{"en":"Writers should always consider their target audience first.","vi":"Người viết nên luôn cân nhắc đối tượng mục tiêu trước tiên."},{"en":"The campaign was designed for a young target audience.","vi":"Chiến dịch được thiết kế cho đối tượng mục tiêu là người trẻ."},{"en":"Knowing your target audience improves the impact of a message.","vi":"Hiểu đối tượng mục tiêu giúp tăng tác động của thông điệp."}]','[]',NULL,'/ˈtɑːrɡɪt ˈɔːdiəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5578,'colloc-16-01',38,'teaching strategy','chiến lược giảng dạy','n + n','[{"en":"The teacher adopted a new teaching strategy this semester.","vi":"Giáo viên áp dụng một chiến lược giảng dạy mới trong học kỳ này."},{"en":"An effective teaching strategy keeps students actively engaged.","vi":"Một chiến lược giảng dạy hiệu quả giữ cho học sinh tích cực tham gia."},{"en":"The workshop introduced several teaching strategies for large classes.","vi":"Buổi tập huấn giới thiệu một số chiến lược giảng dạy cho lớp đông."}]','[]',NULL,'/ˈtiːtʃɪŋ ˈstrætədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5579,'colloc-16-01',39,'technical aspect','khía cạnh kỹ thuật','adj + n','[{"en":"The report explains the technical aspects of the new system.","vi":"Báo cáo giải thích các khía cạnh kỹ thuật của hệ thống mới."},{"en":"She struggled with the technical aspects of the software.","vi":"Cô gặp khó khăn với các khía cạnh kỹ thuật của phần mềm."},{"en":"We hired an expert to handle the technical aspects.","vi":"Chúng tôi thuê một chuyên gia để xử lý các khía cạnh kỹ thuật."}]','[]',NULL,'/ˈteknɪkəl ˈæspekt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5580,'colloc-16-01',40,'technical assistance','hỗ trợ kỹ thuật','adj + n','[{"en":"The organization provides technical assistance to developing countries.","vi":"Tổ chức cung cấp hỗ trợ kỹ thuật cho các nước đang phát triển."},{"en":"Customers can request technical assistance by phone or email.","vi":"Khách hàng có thể yêu cầu hỗ trợ kỹ thuật qua điện thoại hoặc email."},{"en":"The project received technical assistance from international experts.","vi":"Dự án nhận được hỗ trợ kỹ thuật từ các chuyên gia quốc tế."}]','[]',NULL,'/ˈteknɪkəl əˈsɪstəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5581,'colloc-16-01',41,'technical detail','chi tiết kỹ thuật','adj + n','[{"en":"The manual covers every technical detail of the machine.","vi":"Sách hướng dẫn bao gồm mọi chi tiết kỹ thuật của máy."},{"en":"She explained the technical details clearly to the audience.","vi":"Cô giải thích các chi tiết kỹ thuật rõ ràng cho khán giả."},{"en":"Don''t get lost in technical details during the presentation.","vi":"Đừng sa vào các chi tiết kỹ thuật trong khi thuyết trình."}]','[]',NULL,'/ˈteknɪkəl ˈdiːteɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5582,'colloc-16-01',42,'technical expertise','chuyên môn kỹ thuật','adj + n','[{"en":"The job requires strong technical expertise in data analysis.","vi":"Công việc đòi hỏi chuyên môn kỹ thuật vững về phân tích dữ liệu."},{"en":"Her technical expertise made her a valuable team member.","vi":"Chuyên môn kỹ thuật khiến cô trở thành thành viên quý giá của nhóm."},{"en":"The company lacked the technical expertise to finish the project.","vi":"Công ty thiếu chuyên môn kỹ thuật để hoàn thành dự án."}]','[]',NULL,'/ˈteknɪkəl ˌekspɜːrˈtiːz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5583,'colloc-16-01',43,'technical issue','vấn đề kỹ thuật','adj + n','[{"en":"A technical issue delayed the start of the online exam.","vi":"Một vấn đề kỹ thuật làm trễ giờ bắt đầu kỳ thi trực tuyến."},{"en":"The team quickly resolved the technical issue with the server.","vi":"Nhóm nhanh chóng khắc phục vấn đề kỹ thuật với máy chủ."},{"en":"We apologize for the technical issues during the broadcast.","vi":"Chúng tôi xin lỗi về các vấn đề kỹ thuật trong buổi phát sóng."}]','[]',NULL,'/ˈteknɪkəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5584,'colloc-16-01',44,'technical knowledge','kiến thức kỹ thuật','adj + n','[{"en":"The course builds technical knowledge in network security.","vi":"Khóa học xây dựng kiến thức kỹ thuật về an ninh mạng."},{"en":"Practical projects deepen students'' technical knowledge.","vi":"Các dự án thực hành làm sâu kiến thức kỹ thuật của sinh viên."},{"en":"He gained valuable technical knowledge during the internship.","vi":"Anh ấy tích lũy kiến thức kỹ thuật quý báu trong kỳ thực tập."}]','[]',NULL,'/ˈteknɪkəl ˈnɑːlɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5585,'colloc-16-01',45,'technical problem','trục trặc kỹ thuật','adj + n','[{"en":"A technical problem caused the website to crash repeatedly.","vi":"Một trục trặc kỹ thuật khiến trang web liên tục bị sập."},{"en":"Engineers worked overnight to fix the technical problem.","vi":"Các kỹ sư làm việc suốt đêm để khắc phục trục trặc kỹ thuật."},{"en":"The flight was delayed because of a minor technical problem.","vi":"Chuyến bay bị hoãn vì một trục trặc kỹ thuật nhỏ."}]','[]',NULL,'/ˈteknɪkəl ˈprɑːbləm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5586,'colloc-16-01',46,'technical skill','kỹ năng kỹ thuật','adj + n','[{"en":"Employers value both technical skills and good communication.","vi":"Nhà tuyển dụng coi trọng cả kỹ năng kỹ thuật lẫn giao tiếp tốt."},{"en":"The training program develops practical technical skills.","vi":"Chương trình đào tạo phát triển các kỹ năng kỹ thuật thực tế."},{"en":"She improved her technical skills through online courses.","vi":"Cô nâng cao kỹ năng kỹ thuật của mình qua các khóa học trực tuyến."}]','[]',NULL,'/ˈteknɪkəl ˈskɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5587,'colloc-16-01',47,'technical support','hỗ trợ kỹ thuật','adj + n','[{"en":"Call technical support if the device stops responding.","vi":"Gọi bộ phận hỗ trợ kỹ thuật nếu thiết bị ngừng phản hồi."},{"en":"The software includes free technical support for one year.","vi":"Phần mềm bao gồm hỗ trợ kỹ thuật miễn phí trong một năm."},{"en":"Their technical support team responds within a few hours.","vi":"Đội hỗ trợ kỹ thuật của họ phản hồi trong vài giờ."}]','[]',NULL,'/ˈteknɪkəl səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5588,'colloc-16-01',48,'technical term','thuật ngữ chuyên môn','adj + n','[{"en":"The author defines each technical term before using it.","vi":"Tác giả định nghĩa từng thuật ngữ chuyên môn trước khi dùng nó."},{"en":"Avoid too many technical terms when writing for general readers.","vi":"Tránh dùng quá nhiều thuật ngữ chuyên môn khi viết cho độc giả phổ thông."},{"en":"The glossary explains all the technical terms in the report.","vi":"Bảng thuật ngữ giải thích mọi thuật ngữ chuyên môn trong báo cáo."}]','[]',NULL,'/ˈteknɪkəl ˈtɜːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5589,'colloc-16-01',49,'technological advances','những tiến bộ công nghệ','adj + n','[{"en":"Recent technological advances have transformed how we communicate.","vi":"Những tiến bộ công nghệ gần đây đã thay đổi cách chúng ta giao tiếp."},{"en":"Technological advances in medicine save millions of lives.","vi":"Những tiến bộ công nghệ trong y học cứu sống hàng triệu người."},{"en":"The industry depends on continuous technological advances.","vi":"Ngành này phụ thuộc vào những tiến bộ công nghệ liên tục."}]','[]',NULL,'/ˌteknəˈlɑːdʒɪkəl ədˈvænsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5590,'colloc-16-01',50,'technological change','sự thay đổi công nghệ','adj + n','[{"en":"Rapid technological change reshaped the global job market.","vi":"Sự thay đổi công nghệ nhanh chóng định hình lại thị trường lao động toàn cầu."},{"en":"Workers must adapt to constant technological change.","vi":"Người lao động phải thích ứng với sự thay đổi công nghệ liên tục."},{"en":"The essay examines how technological change affects daily life.","vi":"Bài luận xem xét sự thay đổi công nghệ ảnh hưởng đến đời sống thường nhật ra sao."}]','[]',NULL,'/ˌteknəˈlɑːdʒɪkəl ˈtʃeɪndʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5591,'colloc-16-01',51,'technological development','sự phát triển công nghệ','adj + n','[{"en":"Technological development drives much of modern economic growth.","vi":"Sự phát triển công nghệ thúc đẩy phần lớn tăng trưởng kinh tế hiện đại."},{"en":"The country invested heavily in technological development.","vi":"Quốc gia này đầu tư mạnh vào sự phát triển công nghệ."},{"en":"Technological development has improved access to education worldwide.","vi":"Sự phát triển công nghệ đã cải thiện việc tiếp cận giáo dục trên toàn cầu."}]','[]',NULL,'/ˌteknəˈlɑːdʒɪkəl dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5592,'colloc-16-01',52,'technological innovation','đổi mới công nghệ','adj + n','[{"en":"Technological innovation gives companies a strong competitive edge.","vi":"Đổi mới công nghệ mang lại cho công ty lợi thế cạnh tranh lớn."},{"en":"The region became a hub for technological innovation.","vi":"Khu vực này trở thành trung tâm đổi mới công nghệ."},{"en":"Government funding supports technological innovation in universities.","vi":"Ngân sách chính phủ hỗ trợ đổi mới công nghệ tại các trường đại học."}]','[]',NULL,'/ˌteknəˈlɑːdʒɪkəl ˌɪnəˈveɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5593,'colloc-16-01',53,'technological progress','tiến bộ công nghệ','adj + n','[{"en":"Technological progress has made information far easier to access.","vi":"Tiến bộ công nghệ đã làm cho việc tiếp cận thông tin dễ dàng hơn nhiều."},{"en":"Some worry that technological progress may replace many jobs.","vi":"Một số người lo rằng tiến bộ công nghệ có thể thay thế nhiều việc làm."},{"en":"Rapid technological progress requires constant learning and adaptation.","vi":"Tiến bộ công nghệ nhanh chóng đòi hỏi học hỏi và thích ứng liên tục."}]','[]',NULL,'/ˌteknəˈlɑːdʒɪkəl ˈprɑːɡres/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5594,'colloc-16-01',54,'test score','điểm kiểm tra','n + n','[{"en":"Her test scores improved steadily throughout the school year.","vi":"Điểm kiểm tra của cô cải thiện đều đặn suốt năm học."},{"en":"The study compared test scores across different teaching methods.","vi":"Nghiên cứu so sánh điểm kiểm tra giữa các phương pháp giảng dạy khác nhau."},{"en":"High test scores do not always reflect deep understanding.","vi":"Điểm kiểm tra cao không phải lúc nào cũng phản ánh sự hiểu sâu."}]','[]',NULL,'/ˈtest ˈskɔːr/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5595,'colloc-16-01',55,'test a theory','kiểm chứng một lý thuyết','v + n','[{"en":"Scientists design experiments to test a theory under controlled conditions.","vi":"Các nhà khoa học thiết kế thí nghiệm để kiểm chứng một lý thuyết trong điều kiện kiểm soát."},{"en":"We collected new data to test a theory about memory.","vi":"Chúng tôi thu thập dữ liệu mới để kiểm chứng một lý thuyết về trí nhớ."},{"en":"Researchers must test a theory before accepting it as fact.","vi":"Các nhà nghiên cứu phải kiểm chứng một lý thuyết trước khi xem nó là sự thật."}]','[]',NULL,'/test ə ˈθiːəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5596,'colloc-16-01',56,'textual analysis','phân tích văn bản','adj + n','[{"en":"Her textual analysis revealed hidden themes in the old manuscript.","vi":"Phân tích văn bản của cô đã hé lộ những chủ đề ẩn trong bản thảo cũ."},{"en":"Careful textual analysis helps students understand the author''s intent.","vi":"Phân tích văn bản kỹ lưỡng giúp sinh viên hiểu ý đồ của tác giả."},{"en":"The course introduces methods of textual analysis for literary criticism.","vi":"Khóa học giới thiệu các phương pháp phân tích văn bản cho phê bình văn học."}]','[]',NULL,'/ˈtekstʃuəl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5597,'colloc-16-01',57,'thematic analysis','phân tích theo chủ đề','adj + n','[{"en":"We used thematic analysis to identify patterns in the interviews.","vi":"Chúng tôi dùng phân tích theo chủ đề để tìm các mẫu trong các cuộc phỏng vấn."},{"en":"Thematic analysis is common in qualitative social science research.","vi":"Phân tích theo chủ đề rất phổ biến trong nghiên cứu khoa học xã hội định tính."},{"en":"The report presents a thematic analysis of student feedback.","vi":"Báo cáo trình bày một phân tích theo chủ đề về phản hồi của sinh viên."}]','[]',NULL,'/θɪˈmætɪk əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5598,'colloc-16-01',58,'theoretical analysis','phân tích lý thuyết','adj + n','[{"en":"The paper offers a detailed theoretical analysis of market behavior.","vi":"Bài báo đưa ra một phân tích lý thuyết chi tiết về hành vi thị trường."},{"en":"Theoretical analysis often precedes any practical experiment in physics.","vi":"Phân tích lý thuyết thường đi trước bất kỳ thí nghiệm thực tế nào trong vật lý."},{"en":"Her theoretical analysis explained why the model sometimes failed.","vi":"Phân tích lý thuyết của cô giải thích vì sao mô hình đôi khi thất bại."}]','[]',NULL,'/ˌθiːəˈretɪkəl əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5599,'colloc-16-01',59,'theoretical approach','cách tiếp cận lý thuyết','adj + n','[{"en":"Each theoretical approach offers a different way of explaining behavior.","vi":"Mỗi cách tiếp cận lý thuyết đưa ra một cách giải thích hành vi khác nhau."},{"en":"The author combines two theoretical approaches in her new study.","vi":"Tác giả kết hợp hai cách tiếp cận lý thuyết trong nghiên cứu mới của mình."},{"en":"Students compared the theoretical approach with the empirical findings.","vi":"Sinh viên so sánh cách tiếp cận lý thuyết với các kết quả thực nghiệm."}]','[]',NULL,'/ˌθiːəˈretɪkəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5600,'colloc-16-01',60,'theoretical basis','cơ sở lý thuyết','adj + n','[{"en":"The study lacks a solid theoretical basis for its claims.","vi":"Nghiên cứu thiếu một cơ sở lý thuyết vững chắc cho các tuyên bố của nó."},{"en":"His argument rests on a clear theoretical basis from psychology.","vi":"Lập luận của anh dựa trên một cơ sở lý thuyết rõ ràng từ tâm lý học."},{"en":"We must establish the theoretical basis before designing the experiment.","vi":"Chúng ta phải thiết lập cơ sở lý thuyết trước khi thiết kế thí nghiệm."}]','[]',NULL,'/ˌθiːəˈretɪkəl ˈbeɪsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5601,'colloc-16-01',61,'theoretical concept','khái niệm lý thuyết','adj + n','[{"en":"The lecture explained an abstract theoretical concept with simple examples.","vi":"Bài giảng giải thích một khái niệm lý thuyết trừu tượng bằng ví dụ đơn giản."},{"en":"Some theoretical concepts are hard to test in real situations.","vi":"Một số khái niệm lý thuyết rất khó kiểm chứng trong tình huống thực tế."},{"en":"She linked the theoretical concept to everyday classroom practice.","vi":"Cô liên hệ khái niệm lý thuyết với thực hành lớp học hằng ngày."}]','[]',NULL,'/ˌθiːəˈretɪkəl ˈkɑːnsept/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5602,'colloc-16-01',62,'theoretical debate','cuộc tranh luận lý thuyết','adj + n','[{"en":"The article reviews a long theoretical debate about human motivation.","vi":"Bài viết điểm lại một cuộc tranh luận lý thuyết lâu dài về động lực con người."},{"en":"Her thesis enters an ongoing theoretical debate in economics.","vi":"Luận văn của cô tham gia một cuộc tranh luận lý thuyết đang diễn ra trong kinh tế học."},{"en":"The theoretical debate has shaped research for several decades.","vi":"Cuộc tranh luận lý thuyết đã định hình nghiên cứu trong nhiều thập kỷ."}]','[]',NULL,'/ˌθiːəˈretɪkəl dɪˈbeɪt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5603,'colloc-16-01',63,'theoretical framework','khung lý thuyết','adj + n','[{"en":"Her dissertation builds on a well-known theoretical framework.","vi":"Luận án của cô dựa trên một khung lý thuyết nổi tiếng."},{"en":"A clear theoretical framework guides the whole research design.","vi":"Một khung lý thuyết rõ ràng định hướng toàn bộ thiết kế nghiên cứu."},{"en":"The authors adapted the theoretical framework for online learning.","vi":"Các tác giả điều chỉnh khung lý thuyết cho việc học trực tuyến."}]','[]',NULL,'/ˌθiːəˈretɪkəl ˈfreɪmwɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5604,'colloc-16-01',64,'theoretical issue','vấn đề lý thuyết','adj + n','[{"en":"The seminar addressed several theoretical issues in modern linguistics.","vi":"Buổi hội thảo bàn về một số vấn đề lý thuyết trong ngôn ngữ học hiện đại."},{"en":"This theoretical issue remains unresolved despite many studies.","vi":"Vấn đề lý thuyết này vẫn chưa được giải quyết dù đã có nhiều nghiên cứu."},{"en":"She separated the practical problems from the theoretical issues.","vi":"Cô tách các vấn đề thực tiễn ra khỏi các vấn đề lý thuyết."}]','[]',NULL,'/ˌθiːəˈretɪkəl ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5605,'colloc-16-01',65,'theoretical model','mô hình lý thuyết','adj + n','[{"en":"The theoretical model predicts how prices respond to demand.","vi":"Mô hình lý thuyết dự đoán giá phản ứng thế nào với nhu cầu."},{"en":"Researchers tested the theoretical model against real-world data.","vi":"Các nhà nghiên cứu kiểm chứng mô hình lý thuyết với dữ liệu thực tế."},{"en":"A simple theoretical model can still capture key relationships.","vi":"Một mô hình lý thuyết đơn giản vẫn có thể nắm bắt các mối quan hệ chính."}]','[]',NULL,'/ˌθiːəˈretɪkəl ˈmɑːdəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5606,'colloc-16-01',66,'theoretical perspective','góc nhìn lý thuyết','adj + n','[{"en":"From a feminist theoretical perspective, the data look quite different.","vi":"Từ một góc nhìn lý thuyết nữ quyền, dữ liệu trông khá khác biệt."},{"en":"Each theoretical perspective highlights certain aspects of the problem.","vi":"Mỗi góc nhìn lý thuyết làm nổi bật những khía cạnh nhất định của vấn đề."},{"en":"She adopted a sociological theoretical perspective in her analysis.","vi":"Cô áp dụng một góc nhìn lý thuyết xã hội học trong phân tích của mình."}]','[]',NULL,'/ˌθiːəˈretɪkəl pərˈspektɪv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5607,'colloc-16-01',67,'theoretical study','nghiên cứu lý thuyết','adj + n','[{"en":"This theoretical study explores how networks grow over time.","vi":"Nghiên cứu lý thuyết này khám phá cách các mạng lưới phát triển theo thời gian."},{"en":"A purely theoretical study may need later experimental support.","vi":"Một nghiên cứu thuần lý thuyết có thể cần sự hỗ trợ thực nghiệm sau này."},{"en":"The journal published a theoretical study on language acquisition.","vi":"Tạp chí đăng một nghiên cứu lý thuyết về việc tiếp thu ngôn ngữ."}]','[]',NULL,'/ˌθiːəˈretɪkəl ˈstʌdi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5608,'colloc-16-01',68,'theoretical understanding','sự hiểu biết về mặt lý thuyết','adj + n','[{"en":"Good theoretical understanding helps engineers solve practical problems.","vi":"Sự hiểu biết lý thuyết tốt giúp kỹ sư giải quyết các vấn đề thực tế."},{"en":"The course deepens students'' theoretical understanding of climate systems.","vi":"Khóa học giúp sinh viên hiểu sâu hơn về mặt lý thuyết các hệ thống khí hậu."},{"en":"Without theoretical understanding, the experiment was hard to interpret.","vi":"Thiếu hiểu biết lý thuyết, thí nghiệm rất khó diễn giải."}]','[]',NULL,'/ˌθiːəˈretɪkəl ˌʌndərˈstændɪŋ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5609,'colloc-16-01',69,'theoretical work','công trình lý thuyết','adj + n','[{"en":"His early theoretical work laid the foundation for later discoveries.","vi":"Công trình lý thuyết đầu tay của ông đặt nền móng cho các khám phá sau này."},{"en":"The lab balances experimental research with serious theoretical work.","vi":"Phòng thí nghiệm cân bằng giữa nghiên cứu thực nghiệm và công trình lý thuyết nghiêm túc."},{"en":"Much theoretical work in this area remains highly abstract.","vi":"Phần lớn công trình lý thuyết trong lĩnh vực này vẫn rất trừu tượng."}]','[]',NULL,'/ˌθiːəˈretɪkəl wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5610,'colloc-16-01',70,'think differently','suy nghĩ khác đi','v + adv','[{"en":"Travel encourages people to think differently about their own culture.","vi":"Việc đi du lịch khuyến khích người ta suy nghĩ khác đi về văn hóa của mình."},{"en":"Good teachers help students think differently about difficult problems.","vi":"Giáo viên giỏi giúp học sinh suy nghĩ khác đi về những vấn đề khó."},{"en":"The two scientists think differently, yet they collaborate well.","vi":"Hai nhà khoa học suy nghĩ khác nhau, nhưng họ hợp tác rất tốt."}]','[]',NULL,'/θɪŋk ˈdɪfrəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5611,'colloc-16-01',71,'thinking process','quá trình tư duy','n + n','[{"en":"The exercise makes students'' thinking process visible to the teacher.","vi":"Bài tập làm cho quá trình tư duy của học sinh hiện rõ với giáo viên."},{"en":"A clear thinking process leads to better decisions under pressure.","vi":"Một quá trình tư duy rõ ràng dẫn đến quyết định tốt hơn khi áp lực."},{"en":"Researchers studied the thinking process behind expert chess moves.","vi":"Các nhà nghiên cứu nghiên cứu quá trình tư duy đằng sau các nước cờ của chuyên gia."}]','[]',NULL,'/ˈθɪŋkɪŋ ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5612,'colloc-16-01',72,'third party','bên thứ ba','adj + n','[{"en":"An independent third party reviewed the contract for both sides.","vi":"Một bên thứ ba độc lập đã xem xét hợp đồng cho cả hai phía."},{"en":"The data were never shared with any third party.","vi":"Dữ liệu chưa bao giờ được chia sẻ với bất kỳ bên thứ ba nào."},{"en":"A neutral third party helped resolve the long dispute.","vi":"Một bên thứ ba trung lập đã giúp giải quyết tranh chấp kéo dài."}]','[]',NULL,'/θɜːrd ˈpɑːrti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5613,'colloc-16-01',73,'thought process','tiến trình suy nghĩ','n + n','[{"en":"Explaining your thought process helps others follow the argument.","vi":"Giải thích tiến trình suy nghĩ của bạn giúp người khác theo dõi lập luận."},{"en":"The interview revealed the candidate''s thought process while solving problems.","vi":"Cuộc phỏng vấn cho thấy tiến trình suy nghĩ của ứng viên khi giải quyết vấn đề."},{"en":"Writing a journal can slow down a racing thought process.","vi":"Viết nhật ký có thể làm chậm lại một tiến trình suy nghĩ dồn dập."}]','[]',NULL,'/θɔːt ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5614,'colloc-16-01',74,'tightly controlled','được kiểm soát chặt chẽ','adv + vpp','[{"en":"The experiment was tightly controlled to reduce outside influences.","vi":"Thí nghiệm được kiểm soát chặt chẽ để giảm các ảnh hưởng bên ngoài."},{"en":"Access to the laboratory remains tightly controlled for safety.","vi":"Việc ra vào phòng thí nghiệm vẫn được kiểm soát chặt chẽ vì an toàn."},{"en":"In tightly controlled conditions, the results were highly consistent.","vi":"Trong điều kiện được kiểm soát chặt chẽ, kết quả rất nhất quán."}]','[]',NULL,'/ˈtaɪtli kənˈtroʊld/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5615,'colloc-16-01',75,'top management','ban lãnh đạo cấp cao','adj + n','[{"en":"Top management approved the new strategy after a long meeting.","vi":"Ban lãnh đạo cấp cao đã phê duyệt chiến lược mới sau cuộc họp dài."},{"en":"Support from top management is essential for any major change.","vi":"Sự ủng hộ từ ban lãnh đạo cấp cao là thiết yếu cho mọi thay đổi lớn."},{"en":"The report goes directly to top management each quarter.","vi":"Báo cáo được gửi thẳng tới ban lãnh đạo cấp cao mỗi quý."}]','[]',NULL,'/tɑːp ˈmænɪdʒmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5616,'colloc-16-01',76,'total income','tổng thu nhập','adj + n','[{"en":"The family''s total income rose after the second job started.","vi":"Tổng thu nhập của gia đình tăng lên sau khi công việc thứ hai bắt đầu."},{"en":"Taxes are calculated based on a household''s total income.","vi":"Thuế được tính dựa trên tổng thu nhập của một hộ gia đình."},{"en":"The report compares total income across different regions.","vi":"Báo cáo so sánh tổng thu nhập giữa các vùng khác nhau."}]','[]',NULL,'/ˈtoʊtəl ˈɪnkʌm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5617,'colloc-16-01',77,'totally different','hoàn toàn khác biệt','adv + adj','[{"en":"The two studies reached totally different conclusions about the issue.","vi":"Hai nghiên cứu đi đến những kết luận hoàn toàn khác biệt về vấn đề này."},{"en":"Life in a small village is totally different from the city.","vi":"Cuộc sống ở làng nhỏ hoàn toàn khác biệt so với thành phố."},{"en":"After the reform, the system worked in a totally different way.","vi":"Sau cải cách, hệ thống vận hành theo một cách hoàn toàn khác biệt."}]','[]',NULL,'/ˈtoʊtəli ˈdɪfrənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5618,'colloc-16-01',78,'traditional approach','cách tiếp cận truyền thống','adj + n','[{"en":"The traditional approach to teaching still works for many learners.","vi":"Cách tiếp cận truyền thống trong giảng dạy vẫn hiệu quả với nhiều người học."},{"en":"Some doctors prefer a traditional approach over newer methods.","vi":"Một số bác sĩ thích cách tiếp cận truyền thống hơn các phương pháp mới."},{"en":"The study challenges the traditional approach to economic planning.","vi":"Nghiên cứu thách thức cách tiếp cận truyền thống trong hoạch định kinh tế."}]','[]',NULL,'/trəˈdɪʃənəl əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5619,'colloc-16-01',79,'traditional culture','văn hóa truyền thống','adj + n','[{"en":"Festivals help younger generations connect with traditional culture.","vi":"Các lễ hội giúp thế hệ trẻ kết nối với văn hóa truyền thống."},{"en":"Globalization sometimes threatens local traditional culture.","vi":"Toàn cầu hóa đôi khi đe dọa văn hóa truyền thống địa phương."},{"en":"The museum preserves objects from the region''s traditional culture.","vi":"Bảo tàng lưu giữ các hiện vật từ văn hóa truyền thống của vùng này."}]','[]',NULL,'/trəˈdɪʃənəl ˈkʌltʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5620,'colloc-16-01',80,'traditional form','hình thức truyền thống','adj + n','[{"en":"This dance is a traditional form passed down for generations.","vi":"Điệu múa này là một hình thức truyền thống được truyền qua nhiều thế hệ."},{"en":"Email replaced more traditional forms of business communication.","vi":"Email đã thay thế những hình thức giao tiếp kinh doanh truyền thống hơn."},{"en":"The artist blends modern styles with a traditional form.","vi":"Người nghệ sĩ pha trộn phong cách hiện đại với một hình thức truyền thống."}]','[]',NULL,'/trəˈdɪʃənəl fɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5621,'colloc-16-01',81,'traditional method','phương pháp truyền thống','adj + n','[{"en":"Farmers here still rely on a traditional method of irrigation.","vi":"Nông dân ở đây vẫn dựa vào một phương pháp tưới tiêu truyền thống."},{"en":"The traditional method takes longer but produces better results.","vi":"Phương pháp truyền thống mất nhiều thời gian hơn nhưng cho kết quả tốt hơn."},{"en":"Researchers compared a new tool with the traditional method.","vi":"Các nhà nghiên cứu so sánh một công cụ mới với phương pháp truyền thống."}]','[]',NULL,'/trəˈdɪʃənəl ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5622,'colloc-16-01',82,'traditional practice','tập quán truyền thống','adj + n','[{"en":"Many traditional practices survive only in remote rural villages.","vi":"Nhiều tập quán truyền thống chỉ còn tồn tại ở các làng quê xa xôi."},{"en":"The community defended its traditional practice against new regulations.","vi":"Cộng đồng bảo vệ tập quán truyền thống của mình trước các quy định mới."},{"en":"Scholars recorded the traditional practice before it disappeared.","vi":"Các học giả đã ghi chép tập quán truyền thống trước khi nó biến mất."}]','[]',NULL,'/trəˈdɪʃənəl ˈpræktɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5623,'colloc-16-01',83,'traditional research','nghiên cứu truyền thống','adj + n','[{"en":"Traditional research relies heavily on surveys and printed sources.","vi":"Nghiên cứu truyền thống dựa nhiều vào khảo sát và nguồn tài liệu in."},{"en":"Digital tools have transformed methods used in traditional research.","vi":"Các công cụ kỹ thuật số đã thay đổi phương pháp dùng trong nghiên cứu truyền thống."},{"en":"The team combined traditional research with large-scale data analysis.","vi":"Nhóm kết hợp nghiên cứu truyền thống với phân tích dữ liệu quy mô lớn."}]','[]',NULL,'/trəˈdɪʃənəl ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5624,'colloc-16-01',84,'traditional society','xã hội truyền thống','adj + n','[{"en":"In traditional society, elders often made the most important decisions.","vi":"Trong xã hội truyền thống, người cao tuổi thường đưa ra những quyết định quan trọng nhất."},{"en":"The book contrasts modern life with traditional society.","vi":"Cuốn sách đối chiếu cuộc sống hiện đại với xã hội truyền thống."},{"en":"Roles in a traditional society were usually fixed by gender.","vi":"Vai trò trong một xã hội truyền thống thường được cố định theo giới tính."}]','[]',NULL,'/trəˈdɪʃənəl səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5625,'colloc-16-01',85,'traditional value','giá trị truyền thống','adj + n','[{"en":"Parents try to pass traditional values on to their children.","vi":"Cha mẹ cố gắng truyền lại các giá trị truyền thống cho con cái."},{"en":"Some traditional values conflict with modern ideas of freedom.","vi":"Một số giá trị truyền thống xung đột với các ý niệm hiện đại về tự do."},{"en":"The community works hard to protect its traditional values.","vi":"Cộng đồng nỗ lực bảo vệ các giá trị truyền thống của mình."}]','[]',NULL,'/trəˈdɪʃənəl ˈvæljuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5626,'colloc-16-01',86,'traditional view','quan điểm truyền thống','adj + n','[{"en":"The traditional view holds that hard work guarantees success.","vi":"Quan điểm truyền thống cho rằng làm việc chăm chỉ bảo đảm thành công."},{"en":"Recent studies challenge the traditional view of memory.","vi":"Các nghiên cứu gần đây thách thức quan điểm truyền thống về trí nhớ."},{"en":"She rejected the traditional view in favor of newer theories.","vi":"Cô bác bỏ quan điểm truyền thống để ủng hộ những lý thuyết mới hơn."}]','[]',NULL,'/trəˈdɪʃənəl vjuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5627,'colloc-16-01',87,'transferable skill','kỹ năng có thể chuyển đổi','adj + n','[{"en":"Communication is a transferable skill valued in almost every job.","vi":"Giao tiếp là một kỹ năng có thể chuyển đổi được coi trọng ở hầu hết mọi công việc."},{"en":"University courses aim to develop students'' transferable skills.","vi":"Các khóa học đại học nhằm phát triển kỹ năng chuyển đổi của sinh viên."},{"en":"Teamwork is a transferable skill useful across many careers.","vi":"Làm việc nhóm là một kỹ năng có thể chuyển đổi hữu ích trong nhiều nghề."}]','[]',NULL,'/trænsˈfɜːrəbəl skɪl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5628,'colloc-16-01',88,'transmit data','truyền dữ liệu','v + n','[{"en":"The new network can transmit data far more quickly than before.","vi":"Mạng mới có thể truyền dữ liệu nhanh hơn nhiều so với trước đây."},{"en":"Sensors transmit data to the central server every minute.","vi":"Các cảm biến truyền dữ liệu về máy chủ trung tâm mỗi phút."},{"en":"Engineers encrypt the signal before they transmit data.","vi":"Các kỹ sư mã hóa tín hiệu trước khi truyền dữ liệu."}]','[]',NULL,'/trænsˈmɪt ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5629,'colloc-16-01',89,'transmit information','truyền thông tin','v + n','[{"en":"Nerve cells transmit information across the body very rapidly.","vi":"Các tế bào thần kinh truyền thông tin khắp cơ thể rất nhanh."},{"en":"Satellites transmit information to receivers around the world.","vi":"Các vệ tinh truyền thông tin tới các máy thu khắp thế giới."},{"en":"Clear diagrams transmit information faster than long paragraphs.","vi":"Sơ đồ rõ ràng truyền thông tin nhanh hơn những đoạn văn dài."}]','[]',NULL,'/trænsˈmɪt ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5630,'colloc-16-01',90,'transport system','hệ thống giao thông','n + n','[{"en":"The city invested heavily in its public transport system.","vi":"Thành phố đầu tư mạnh vào hệ thống giao thông công cộng của mình."},{"en":"An efficient transport system reduces traffic and pollution.","vi":"Một hệ thống giao thông hiệu quả giảm kẹt xe và ô nhiễm."},{"en":"The report compares the transport systems of major cities.","vi":"Báo cáo so sánh hệ thống giao thông của các thành phố lớn."}]','[]',NULL,'/ˈtrænspɔːrt ˈsɪstəm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5631,'colloc-16-01',91,'treat differently','đối xử khác biệt','v + adv','[{"en":"Teachers should not treat differently the children of wealthy parents.","vi":"Giáo viên không nên đối xử khác biệt với con của những phụ huynh giàu có."},{"en":"The study found that doctors treat differently male and female patients.","vi":"Nghiên cứu phát hiện bác sĩ đối xử khác biệt với bệnh nhân nam và nữ."},{"en":"Companies that treat differently their staff often lose trust.","vi":"Những công ty đối xử khác biệt với nhân viên thường đánh mất niềm tin."}]','[]',NULL,'/triːt ˈdɪfrəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5632,'colloc-16-01',92,'treat equally','đối xử bình đẳng','v + adv','[{"en":"The law requires employers to treat equally all their workers.","vi":"Luật yêu cầu chủ lao động đối xử bình đẳng với mọi nhân viên."},{"en":"Good schools treat equally students from every background.","vi":"Những trường học tốt đối xử bình đẳng với học sinh từ mọi hoàn cảnh."},{"en":"The policy aims to treat equally men and women.","vi":"Chính sách này nhằm đối xử bình đẳng giữa nam và nữ."}]','[]',NULL,'/triːt ˈiːkwəli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5633,'colloc-16-01',93,'typical example','ví dụ điển hình','adj + n','[{"en":"This case is a typical example of poor project planning.","vi":"Trường hợp này là một ví dụ điển hình của việc lập kế hoạch dự án kém."},{"en":"The teacher gave a typical example to clarify the rule.","vi":"Giáo viên đưa ra một ví dụ điển hình để làm rõ quy tắc."},{"en":"Her essay offers a typical example of strong academic writing.","vi":"Bài luận của cô là một ví dụ điển hình về văn viết học thuật tốt."}]','[]',NULL,'/ˈtɪpɪkəl ɪɡˈzæmpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5634,'colloc-16-01',94,'ultimate goal','mục tiêu cuối cùng','adj + n','[{"en":"The ultimate goal of the program is to reduce poverty.","vi":"Mục tiêu cuối cùng của chương trình là giảm nghèo."},{"en":"Her ultimate goal was to publish in a leading journal.","vi":"Mục tiêu cuối cùng của cô là đăng bài trên một tạp chí hàng đầu."},{"en":"Every small task should serve the team''s ultimate goal.","vi":"Mỗi nhiệm vụ nhỏ đều nên phục vụ mục tiêu cuối cùng của nhóm."}]','[]',NULL,'/ˈʌltɪmət ɡoʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5635,'colloc-16-01',95,'undergo transformation','trải qua sự biến đổi','adj + n','[{"en":"The old town will undergo transformation over the next decade.","vi":"Khu phố cũ sẽ trải qua sự biến đổi trong thập kỷ tới."},{"en":"Caterpillars undergo transformation before becoming butterflies.","vi":"Sâu bướm trải qua sự biến đổi trước khi thành bướm."},{"en":"The industry must undergo transformation to survive the crisis.","vi":"Ngành công nghiệp phải trải qua sự biến đổi để sống sót qua khủng hoảng."}]','[]',NULL,'/ˌʌndərˈɡoʊ ˌtrænsfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5636,'colloc-16-01',96,'underlying assumption','giả định ngầm','adj + n','[{"en":"The model rests on an underlying assumption about rational behavior.","vi":"Mô hình dựa trên một giả định ngầm về hành vi lý trí."},{"en":"She questioned the underlying assumption behind the whole argument.","vi":"Cô đặt câu hỏi về giả định ngầm đằng sau toàn bộ lập luận."},{"en":"Every method carries underlying assumptions that researchers must state.","vi":"Mỗi phương pháp đều mang những giả định ngầm mà nhà nghiên cứu phải nêu rõ."}]','[]',NULL,'/ˌʌndərˈlaɪɪŋ əˈsʌmpʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5637,'colloc-16-01',97,'underlying cause','nguyên nhân sâu xa','adj + n','[{"en":"Doctors searched for the underlying cause of her fatigue.","vi":"Các bác sĩ tìm kiếm nguyên nhân sâu xa của sự mệt mỏi ở cô."},{"en":"Poverty is often an underlying cause of social conflict.","vi":"Nghèo đói thường là nguyên nhân sâu xa của xung đột xã hội."},{"en":"Treating symptoms ignores the underlying cause of the problem.","vi":"Chữa triệu chứng là bỏ qua nguyên nhân sâu xa của vấn đề."}]','[]',NULL,'/ˌʌndərˈlaɪɪŋ kɔːz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5638,'colloc-16-01',98,'underlying principle','nguyên tắc nền tảng','adj + n','[{"en":"The same underlying principle governs both circuits and pipelines.","vi":"Cùng một nguyên tắc nền tảng chi phối cả mạch điện lẫn đường ống."},{"en":"Fairness is the underlying principle of the whole policy.","vi":"Công bằng là nguyên tắc nền tảng của toàn bộ chính sách."},{"en":"Once you grasp the underlying principle, the rules make sense.","vi":"Khi đã nắm được nguyên tắc nền tảng, các quy tắc trở nên hợp lý."}]','[]',NULL,'/ˌʌndərˈlaɪɪŋ ˈprɪnsəpəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5639,'colloc-16-01',99,'underlying process','tiến trình nền tảng','adj + n','[{"en":"Researchers study the underlying process that drives memory loss.","vi":"Các nhà nghiên cứu nghiên cứu tiến trình nền tảng gây mất trí nhớ."},{"en":"Understanding the underlying process helps engineers fix the fault.","vi":"Hiểu tiến trình nền tảng giúp kỹ sư khắc phục sự cố."},{"en":"The same underlying process shapes growth in many species.","vi":"Cùng một tiến trình nền tảng định hình sự tăng trưởng ở nhiều loài."}]','[]',NULL,'/ˌʌndərˈlaɪɪŋ ˈprɑːses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5640,'colloc-16-01',100,'underlying reason','lý do sâu xa','adj + n','[{"en":"The survey explored the underlying reason for student dropout.","vi":"Cuộc khảo sát tìm hiểu lý do sâu xa khiến sinh viên bỏ học."},{"en":"Low pay is the underlying reason behind the high turnover.","vi":"Lương thấp là lý do sâu xa đằng sau tỷ lệ nghỉ việc cao."},{"en":"She wanted to know the underlying reason for his decision.","vi":"Cô muốn biết lý do sâu xa cho quyết định của anh."}]','[]',NULL,'/ˌʌndərˈlaɪɪŋ ˈriːzən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5641,'colloc-16-01',101,'underlying structure','cấu trúc nền tảng','adj + n','[{"en":"Linguists try to reveal the underlying structure of every language.","vi":"Các nhà ngôn ngữ học cố gắng hé lộ cấu trúc nền tảng của mọi ngôn ngữ."},{"en":"The melody hides a complex underlying structure of harmonies.","vi":"Giai điệu che giấu một cấu trúc nền tảng phức tạp của các hòa âm."},{"en":"Mapping the underlying structure clarified how the data connect.","vi":"Vẽ ra cấu trúc nền tảng đã làm rõ cách dữ liệu liên kết với nhau."}]','[]',NULL,'/ˌʌndərˈlaɪɪŋ ˈstrʌktʃər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5642,'colloc-16-01',102,'undertake research','tiến hành nghiên cứu','v + n','[{"en":"The university encourages students to undertake research early.","vi":"Trường đại học khuyến khích sinh viên tiến hành nghiên cứu từ sớm."},{"en":"Her team undertook research into renewable energy storage.","vi":"Nhóm của cô đã tiến hành nghiên cứu về lưu trữ năng lượng tái tạo."},{"en":"Funding allows the lab to undertake research on rare diseases.","vi":"Nguồn tài trợ cho phép phòng thí nghiệm tiến hành nghiên cứu về bệnh hiếm."}]','[]',NULL,'/ˌʌndərˈteɪk ˈriːsɜːrtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5643,'colloc-16-01',103,'undertake work','đảm nhận công việc','v + n','[{"en":"The contractor agreed to undertake work on the old bridge.","vi":"Nhà thầu đồng ý đảm nhận công việc trên cây cầu cũ."},{"en":"Volunteers undertake work that local councils cannot afford.","vi":"Các tình nguyện viên đảm nhận công việc mà hội đồng địa phương không đủ khả năng chi trả."},{"en":"Few firms will undertake work in such dangerous conditions.","vi":"Ít công ty chịu đảm nhận công việc trong điều kiện nguy hiểm như vậy."}]','[]',NULL,'/ˌʌndərˈteɪk wɜːrk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5644,'colloc-16-01',104,'undertake an activity','thực hiện một hoạt động','v + n','[{"en":"Students must undertake an activity that links theory and practice.","vi":"Sinh viên phải thực hiện một hoạt động gắn kết lý thuyết với thực hành."},{"en":"The class will undertake an activity to test their hypothesis.","vi":"Lớp học sẽ thực hiện một hoạt động để kiểm chứng giả thuyết của mình."},{"en":"Before you undertake an activity, read the safety guidelines.","vi":"Trước khi thực hiện một hoạt động, hãy đọc hướng dẫn an toàn."}]','[]',NULL,'/ˌʌndərˈteɪk ən ækˈtɪvəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5645,'colloc-16-01',105,'unequal power','quyền lực bất bình đẳng','adj + n','[{"en":"Unequal power between the two nations shaped the treaty.","vi":"Quyền lực bất bình đẳng giữa hai quốc gia đã định hình hiệp ước."},{"en":"The essay examines unequal power in the workplace.","vi":"Bài luận xem xét quyền lực bất bình đẳng tại nơi làm việc."},{"en":"Unequal power often makes fair negotiation very difficult.","vi":"Quyền lực bất bình đẳng thường khiến việc thương lượng công bằng rất khó."}]','[]',NULL,'/ʌnˈiːkwəl ˈpaʊər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5646,'colloc-16-01',106,'unfair treatment','sự đối xử bất công','adj + n','[{"en":"Several workers complained about unfair treatment by their manager.","vi":"Một số nhân viên phàn nàn về sự đối xử bất công của quản lý họ."},{"en":"The law protects citizens from unfair treatment by officials.","vi":"Luật bảo vệ công dân khỏi sự đối xử bất công từ giới chức."},{"en":"She filed a complaint after years of unfair treatment.","vi":"Cô nộp đơn khiếu nại sau nhiều năm bị đối xử bất công."}]','[]',NULL,'/ʌnˈfer ˈtriːtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5647,'colloc-16-01',107,'unintended consequences','hậu quả ngoài ý muốn','adj + n','[{"en":"The new tax had several unintended consequences for small businesses.","vi":"Loại thuế mới gây ra vài hậu quả ngoài ý muốn cho doanh nghiệp nhỏ."},{"en":"Good policies sometimes produce serious unintended consequences.","vi":"Những chính sách tốt đôi khi tạo ra hậu quả ngoài ý muốn nghiêm trọng."},{"en":"Engineers test designs to avoid unintended consequences later.","vi":"Các kỹ sư thử nghiệm thiết kế để tránh hậu quả ngoài ý muốn về sau."}]','[]',NULL,'/ˌʌnɪnˈtendɪd ˈkɑːnsɪkwensɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5648,'colloc-16-01',108,'unique individual','cá nhân độc nhất','adj + n','[{"en":"Each student is a unique individual with different strengths.","vi":"Mỗi học sinh là một cá nhân độc nhất với những thế mạnh khác nhau."},{"en":"Good teaching respects every unique individual in the room.","vi":"Việc dạy học tốt tôn trọng từng cá nhân độc nhất trong phòng."},{"en":"The theory treats people as unique individuals, not mere statistics.","vi":"Lý thuyết xem con người là những cá nhân độc nhất, không phải chỉ là con số thống kê."}]','[]',NULL,'/juˈniːk ˌɪndɪˈvɪdʒuəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5649,'colloc-16-01',109,'unique opportunity','cơ hội độc nhất','adj + n','[{"en":"The scholarship gave her a unique opportunity to study abroad.","vi":"Học bổng đã cho cô một cơ hội độc nhất để du học."},{"en":"This project offers a unique opportunity to test the model.","vi":"Dự án này mang lại một cơ hội độc nhất để kiểm chứng mô hình."},{"en":"Few people get such a unique opportunity in their career.","vi":"Ít người có được một cơ hội độc nhất như vậy trong sự nghiệp."}]','[]',NULL,'/juˈniːk ˌɑːpərˈtuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5650,'colloc-16-01',110,'unique position','vị thế độc nhất','adj + n','[{"en":"The company holds a unique position in the local market.","vi":"Công ty giữ một vị thế độc nhất trên thị trường địa phương."},{"en":"Her experience puts her in a unique position to advise.","vi":"Kinh nghiệm đặt cô vào một vị thế độc nhất để tư vấn."},{"en":"The country''s unique position gave it strong trade advantages.","vi":"Vị thế độc nhất của đất nước mang lại lợi thế thương mại lớn."}]','[]',NULL,'/juˈniːk pəˈzɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5651,'colloc-16-01',111,'universally accepted','được chấp nhận rộng rãi','adv + vpp','[{"en":"No single definition of culture is universally accepted.","vi":"Không có một định nghĩa duy nhất nào về văn hóa được chấp nhận rộng rãi."},{"en":"These safety standards are now universally accepted in the industry.","vi":"Những tiêu chuẩn an toàn này nay được chấp nhận rộng rãi trong ngành."},{"en":"The theory became universally accepted after decades of debate.","vi":"Lý thuyết trở nên được chấp nhận rộng rãi sau hàng thập kỷ tranh luận."}]','[]',NULL,'/ˌjuːnɪˈvɜːrsəli əkˈseptɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5652,'colloc-16-01',112,'unlimited access','quyền truy cập không giới hạn','adj + n','[{"en":"Members enjoy unlimited access to the online research library.","vi":"Thành viên được hưởng quyền truy cập không giới hạn vào thư viện nghiên cứu trực tuyến."},{"en":"The subscription gives unlimited access to every back issue.","vi":"Gói đăng ký cho quyền truy cập không giới hạn vào mọi số báo cũ."},{"en":"Students should not have unlimited access to exam answers.","vi":"Sinh viên không nên có quyền truy cập không giới hạn vào đáp án bài thi."}]','[]',NULL,'/ʌnˈlɪmɪtɪd ˈækses/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5653,'colloc-16-01',113,'unskilled worker','lao động phổ thông','adj + n','[{"en":"Many unskilled workers lost their jobs when the factory closed.","vi":"Nhiều lao động phổ thông mất việc khi nhà máy đóng cửa."},{"en":"Automation often replaces unskilled workers first.","vi":"Tự động hóa thường thay thế lao động phổ thông trước tiên."},{"en":"Training programs help unskilled workers find better positions.","vi":"Các chương trình đào tạo giúp lao động phổ thông tìm được vị trí tốt hơn."}]','[]',NULL,'/ʌnˈskɪld ˈwɜːrkər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5654,'colloc-16-01',114,'urban area','khu vực đô thị','adj + n','[{"en":"More people are moving from villages into urban areas.","vi":"Ngày càng nhiều người chuyển từ làng quê ra khu vực đô thị."},{"en":"Air pollution is usually worse in dense urban areas.","vi":"Ô nhiễm không khí thường tệ hơn ở các khu vực đô thị đông đúc."},{"en":"The study compared crime rates in urban and rural areas.","vi":"Nghiên cứu so sánh tỷ lệ tội phạm ở khu vực đô thị và nông thôn."}]','[]',NULL,'/ˈɜːrbən ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5655,'colloc-16-01',115,'urban center','trung tâm đô thị','adj + n','[{"en":"Jobs are concentrated in the country''s largest urban centers.","vi":"Việc làm tập trung ở những trung tâm đô thị lớn nhất của đất nước."},{"en":"The new railway connects several major urban centers.","vi":"Tuyến đường sắt mới nối liền vài trung tâm đô thị lớn."},{"en":"Housing costs rise quickly near busy urban centers.","vi":"Chi phí nhà ở tăng nhanh gần các trung tâm đô thị sầm uất."}]','[]',NULL,'/ˈɜːrbən ˈsentər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5656,'colloc-16-01',116,'urban design','thiết kế đô thị','adj + n','[{"en":"Good urban design makes neighborhoods safer and more walkable.","vi":"Thiết kế đô thị tốt làm cho các khu dân cư an toàn hơn và dễ đi bộ hơn."},{"en":"The course covers principles of sustainable urban design.","vi":"Khóa học bao quát các nguyên tắc thiết kế đô thị bền vững."},{"en":"Poor urban design can increase traffic and isolation.","vi":"Thiết kế đô thị kém có thể làm tăng kẹt xe và sự cô lập."}]','[]',NULL,'/ˈɜːrbən dɪˈzaɪn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5657,'colloc-16-01',117,'urban development','phát triển đô thị','adj + n','[{"en":"Rapid urban development has put pressure on local water supplies.","vi":"Phát triển đô thị nhanh đã gây áp lực lên nguồn nước địa phương."},{"en":"The council approved a plan for sustainable urban development.","vi":"Hội đồng phê duyệt một kế hoạch phát triển đô thị bền vững."},{"en":"Urban development often displaces poorer residents from city centers.","vi":"Phát triển đô thị thường đẩy cư dân nghèo ra khỏi trung tâm thành phố."}]','[]',NULL,'/ˈɜːrbən dɪˈveləpmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5658,'colloc-16-01',118,'urban environment','môi trường đô thị','adj + n','[{"en":"Children in an urban environment face different health risks.","vi":"Trẻ em trong môi trường đô thị đối mặt với những rủi ro sức khỏe khác nhau."},{"en":"Trees and parks improve the quality of an urban environment.","vi":"Cây xanh và công viên cải thiện chất lượng của môi trường đô thị."},{"en":"The study examined stress levels in a crowded urban environment.","vi":"Nghiên cứu xem xét mức độ căng thẳng trong một môi trường đô thị đông đúc."}]','[]',NULL,'/ˈɜːrbən ɪnˈvaɪrənmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5659,'colloc-16-01',119,'use criteria','sử dụng tiêu chí','v + n','[{"en":"Reviewers use criteria to judge each application fairly.","vi":"Người đánh giá sử dụng tiêu chí để chấm mỗi hồ sơ một cách công bằng."},{"en":"The committee will use criteria agreed upon in advance.","vi":"Hội đồng sẽ sử dụng tiêu chí đã được thống nhất từ trước."},{"en":"Teachers use clear criteria when they grade student essays.","vi":"Giáo viên sử dụng tiêu chí rõ ràng khi chấm bài luận của học sinh."}]','[]',NULL,'/juːz kraɪˈtɪriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5660,'colloc-16-01',120,'use effectively','sử dụng hiệu quả','v + adv','[{"en":"Students must learn to use effectively the resources available.","vi":"Sinh viên phải học cách sử dụng hiệu quả những nguồn lực sẵn có."},{"en":"Few managers use effectively the data they collect.","vi":"Ít nhà quản lý sử dụng hiệu quả dữ liệu mà họ thu thập."},{"en":"To use effectively your time, plan each day carefully.","vi":"Để sử dụng hiệu quả thời gian của bạn, hãy lên kế hoạch mỗi ngày cẩn thận."}]','[]',NULL,'/juːz ɪˈfektɪvli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5661,'colloc-16-01',121,'use resources','sử dụng nguồn lực','v + n','[{"en":"Sustainable companies use resources without harming the environment.","vi":"Các công ty bền vững sử dụng nguồn lực mà không gây hại cho môi trường."},{"en":"We must use resources wisely during the budget shortfall.","vi":"Chúng ta phải sử dụng nguồn lực một cách khôn ngoan trong lúc thiếu hụt ngân sách."},{"en":"The project taught students to use resources more efficiently.","vi":"Dự án dạy sinh viên sử dụng nguồn lực hiệu quả hơn."}]','[]',NULL,'/juːz ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5662,'colloc-16-01',122,'use sparingly','sử dụng dè sẻn','v + adv','[{"en":"Writers should use sparingly long and complicated technical terms.","vi":"Người viết nên sử dụng dè sẻn những thuật ngữ kỹ thuật dài và phức tạp."},{"en":"During the drought, families were told to use water sparingly.","vi":"Trong hạn hán, các gia đình được khuyên sử dụng nước dè sẻn."},{"en":"Good designers use bright colors sparingly for emphasis.","vi":"Những nhà thiết kế giỏi sử dụng màu sắc rực rỡ dè sẻn để nhấn mạnh."}]','[]',NULL,'/juːz ˈsperɪŋli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5663,'colloc-16-01',123,'use statistics','sử dụng số liệu thống kê','v + n','[{"en":"Economists use statistics to track changes in the labor market.","vi":"Các nhà kinh tế sử dụng số liệu thống kê để theo dõi thay đổi trên thị trường lao động."},{"en":"The article uses statistics to support its main argument.","vi":"Bài báo sử dụng số liệu thống kê để củng cố lập luận chính của nó."},{"en":"Be careful when you use statistics from unreliable sources.","vi":"Hãy cẩn thận khi bạn sử dụng số liệu thống kê từ những nguồn không đáng tin."}]','[]',NULL,'/juːz stəˈtɪstɪks/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5664,'colloc-16-01',124,'use a format','sử dụng một định dạng','v + n','[{"en":"Please use a format that all team members can open.","vi":"Vui lòng sử dụng một định dạng mà mọi thành viên trong nhóm có thể mở."},{"en":"Academic journals require authors to use a strict format.","vi":"Các tạp chí học thuật yêu cầu tác giả sử dụng một định dạng nghiêm ngặt."},{"en":"The slides use a clear format that aids understanding.","vi":"Các slide sử dụng một định dạng rõ ràng giúp dễ hiểu hơn."}]','[]',NULL,'/juːz ə ˈfɔːrmæt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5665,'colloc-16-01',125,'use a method','sử dụng một phương pháp','v + n','[{"en":"The researchers use a method that reduces measurement errors.","vi":"Các nhà nghiên cứu sử dụng một phương pháp giúp giảm sai số đo lường."},{"en":"We chose to use a method tested in earlier studies.","vi":"Chúng tôi chọn sử dụng một phương pháp đã được kiểm chứng ở các nghiên cứu trước."},{"en":"Teachers often use a method suited to younger learners.","vi":"Giáo viên thường sử dụng một phương pháp phù hợp với người học nhỏ tuổi."}]','[]',NULL,'/juːz ə ˈmeθəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5666,'colloc-16-01',126,'use a methodology','sử dụng một phương pháp luận','v + n','[{"en":"The thesis uses a methodology common in social research.","vi":"Luận văn sử dụng một phương pháp luận phổ biến trong nghiên cứu xã hội."},{"en":"They chose to use a methodology that combines surveys and interviews.","vi":"Họ chọn sử dụng một phương pháp luận kết hợp khảo sát và phỏng vấn."},{"en":"Authors must clearly explain why they use a methodology.","vi":"Tác giả phải giải thích rõ vì sao họ sử dụng một phương pháp luận."}]','[]',NULL,'/juːz ə ˌmeθəˈdɑːlədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5667,'colloc-16-01',127,'use a procedure','sử dụng một quy trình','v + n','[{"en":"The lab uses a procedure designed to keep samples sterile.","vi":"Phòng thí nghiệm sử dụng một quy trình được thiết kế để giữ mẫu vô trùng."},{"en":"We use a procedure that anyone can repeat exactly.","vi":"Chúng tôi sử dụng một quy trình mà bất kỳ ai cũng có thể lặp lại chính xác."},{"en":"Hospitals must use a procedure approved by safety regulators.","vi":"Các bệnh viện phải sử dụng một quy trình được cơ quan an toàn phê duyệt."}]','[]',NULL,'/juːz ə prəˈsiːdʒər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5668,'colloc-16-01',128,'use a source','sử dụng một nguồn','v + n','[{"en":"Always use a source you can cite and verify.","vi":"Hãy luôn sử dụng một nguồn mà bạn có thể trích dẫn và kiểm chứng."},{"en":"Students must not use a source without proper acknowledgment.","vi":"Sinh viên không được sử dụng một nguồn mà không ghi nhận đúng cách."},{"en":"The essay uses a source from a respected academic journal.","vi":"Bài luận sử dụng một nguồn từ một tạp chí học thuật uy tín."}]','[]',NULL,'/juːz ə sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5669,'colloc-16-01',129,'use a strategy','sử dụng một chiến lược','v + n','[{"en":"The company will use a strategy focused on online sales.","vi":"Công ty sẽ sử dụng một chiến lược tập trung vào bán hàng trực tuyến."},{"en":"Good students use a strategy to manage exam stress.","vi":"Học sinh giỏi sử dụng một chiến lược để quản lý căng thẳng khi thi."},{"en":"The coach decided to use a strategy that suits younger players.","vi":"Huấn luyện viên quyết định sử dụng một chiến lược phù hợp với cầu thủ trẻ."}]','[]',NULL,'/juːz ə ˈstrætədʒi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5670,'colloc-16-01',130,'use a technique','sử dụng một kỹ thuật','v + n','[{"en":"Surgeons use a technique that shortens recovery time.","vi":"Bác sĩ phẫu thuật sử dụng một kỹ thuật giúp rút ngắn thời gian hồi phục."},{"en":"The artist uses a technique borrowed from old masters.","vi":"Người nghệ sĩ sử dụng một kỹ thuật học từ các bậc thầy xưa."},{"en":"We use a technique that improves the accuracy of measurements.","vi":"Chúng tôi sử dụng một kỹ thuật giúp cải thiện độ chính xác của phép đo."}]','[]',NULL,'/juːz ə tekˈniːk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5671,'colloc-16-01',131,'use a theory','vận dụng một lý thuyết','v + n','[{"en":"The paper uses a theory developed in cognitive science.","vi":"Bài báo vận dụng một lý thuyết được phát triển trong khoa học nhận thức."},{"en":"She decided to use a theory that explains group behavior.","vi":"Cô quyết định vận dụng một lý thuyết giải thích hành vi nhóm."},{"en":"Good analysts use a theory to interpret their data.","vi":"Những nhà phân tích giỏi vận dụng một lý thuyết để diễn giải dữ liệu của họ."}]','[]',NULL,'/juːz ə ˈθiːəri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5672,'colloc-16-01',132,'use an analysis','sử dụng một phân tích','v + n','[{"en":"The report uses an analysis of ten years of sales data.","vi":"Báo cáo sử dụng một phân tích dữ liệu bán hàng trong mười năm."},{"en":"We use an analysis that compares both groups directly.","vi":"Chúng tôi sử dụng một phân tích so sánh trực tiếp cả hai nhóm."},{"en":"Planners use an analysis of traffic flow to design roads.","vi":"Các nhà quy hoạch sử dụng một phân tích lưu lượng giao thông để thiết kế đường."}]','[]',NULL,'/juːz ən əˈnæləsɪs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5673,'colloc-16-01',133,'use an approach','sử dụng một cách tiếp cận','v + n','[{"en":"The teacher uses an approach that engages every student.","vi":"Giáo viên sử dụng một cách tiếp cận thu hút mọi học sinh."},{"en":"We decided to use an approach based on real examples.","vi":"Chúng tôi quyết định sử dụng một cách tiếp cận dựa trên ví dụ thực tế."},{"en":"Therapists often use an approach tailored to each patient.","vi":"Các nhà trị liệu thường sử dụng một cách tiếp cận riêng cho từng bệnh nhân."}]','[]',NULL,'/juːz ən əˈproʊtʃ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5674,'colloc-16-01',134,'use an definition','sử dụng một định nghĩa','v + n','[{"en":"The study uses an definition of poverty set by the agency.","vi":"Nghiên cứu sử dụng một định nghĩa về nghèo do cơ quan này đặt ra."},{"en":"Researchers must use an definition that others can apply consistently.","vi":"Các nhà nghiên cứu phải sử dụng một định nghĩa mà người khác có thể áp dụng nhất quán."},{"en":"We use an definition broad enough to cover both cases.","vi":"Chúng tôi sử dụng một định nghĩa đủ rộng để bao quát cả hai trường hợp."}]','[]',NULL,'/juːz ən ˌdefɪˈnɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5675,'colloc-16-01',135,'use the concept','vận dụng khái niệm','v + n','[{"en":"The author uses the concept of identity throughout the book.","vi":"Tác giả vận dụng khái niệm bản sắc xuyên suốt cuốn sách."},{"en":"We use the concept to explain why prices vary.","vi":"Chúng tôi vận dụng khái niệm này để giải thích vì sao giá cả biến động."},{"en":"Economists use the concept of supply and demand daily.","vi":"Các nhà kinh tế vận dụng khái niệm cung và cầu hằng ngày."}]','[]',NULL,'/juːz ðə ˈkɑːnsept/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5676,'colloc-16-01',136,'use the data','sử dụng dữ liệu','v + n','[{"en":"Researchers use the data to test their main hypothesis.","vi":"Các nhà nghiên cứu sử dụng dữ liệu để kiểm chứng giả thuyết chính của họ."},{"en":"The company will use the data to improve its service.","vi":"Công ty sẽ sử dụng dữ liệu để cải thiện dịch vụ của mình."},{"en":"We must use the data carefully to avoid wrong conclusions.","vi":"Chúng ta phải sử dụng dữ liệu cẩn thận để tránh kết luận sai."}]','[]',NULL,'/juːz ðə ˈdeɪtə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5677,'colloc-16-01',137,'useful information','thông tin hữu ích','adj + n','[{"en":"The survey gathered useful information about students'' study habits.","vi":"Cuộc khảo sát thu thập thông tin hữu ích về thói quen học tập của sinh viên."},{"en":"This website provides useful information for first-year university applicants.","vi":"Trang web này cung cấp thông tin hữu ích cho thí sinh năm nhất đại học."},{"en":"Interviews can yield useful information that questionnaires often miss.","vi":"Phỏng vấn có thể mang lại thông tin hữu ích mà bảng hỏi thường bỏ sót."}]','[]',NULL,'/ˈjuːsfəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5678,'colloc-16-01',138,'useful material','tài liệu hữu ích','adj + n','[{"en":"The library offers useful material for writing research papers.","vi":"Thư viện cung cấp tài liệu hữu ích để viết bài nghiên cứu."},{"en":"She collected useful material before drafting her thesis introduction.","vi":"Cô ấy thu thập tài liệu hữu ích trước khi viết phần mở đầu luận văn."},{"en":"Teachers shared useful material to help students prepare for exams.","vi":"Giáo viên chia sẻ tài liệu hữu ích giúp học sinh ôn thi."}]','[]',NULL,'/ˈjuːsfəl məˈtɪriəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5679,'colloc-16-01',139,'useful means','phương tiện hữu ích','adj + n','[{"en":"Surveys are a useful means of measuring public opinion accurately.","vi":"Khảo sát là một phương tiện hữu ích để đo lường dư luận chính xác."},{"en":"Email remains a useful means of communication in academic settings.","vi":"Email vẫn là phương tiện liên lạc hữu ích trong môi trường học thuật."},{"en":"Graphs provide a useful means of presenting complex data clearly.","vi":"Biểu đồ là phương tiện hữu ích để trình bày dữ liệu phức tạp rõ ràng."}]','[]',NULL,'/ˈjuːsfəl miːnz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5680,'colloc-16-01',140,'useful source','nguồn hữu ích','adj + n','[{"en":"Academic journals are a useful source of reliable evidence.","vi":"Tạp chí học thuật là nguồn hữu ích cung cấp bằng chứng đáng tin cậy."},{"en":"The internet can be a useful source if used critically.","vi":"Internet có thể là nguồn hữu ích nếu được dùng một cách phê phán."},{"en":"Government reports proved a useful source for the analysis.","vi":"Các báo cáo của chính phủ là nguồn hữu ích cho phần phân tích."}]','[]',NULL,'/ˈjuːsfəl sɔːrs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5681,'colloc-16-01',141,'useful summary','bản tóm tắt hữu ích','adj + n','[{"en":"The chapter ends with a useful summary of key points.","vi":"Chương sách kết thúc bằng một bản tóm tắt hữu ích các ý chính."},{"en":"She wrote a useful summary to revise before the test.","vi":"Cô ấy viết một bản tóm tắt hữu ích để ôn tập trước bài kiểm tra."},{"en":"A useful summary helps readers grasp the article quickly.","vi":"Một bản tóm tắt hữu ích giúp người đọc nắm bài viết nhanh chóng."}]','[]',NULL,'/ˈjuːsfəl ˈsʌməri/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5682,'colloc-16-01',142,'useful tool','công cụ hữu ích','adj + n','[{"en":"Spreadsheets are a useful tool for organizing research data.","vi":"Bảng tính là công cụ hữu ích để sắp xếp dữ liệu nghiên cứu."},{"en":"Mind maps can be a useful tool when planning essays.","vi":"Sơ đồ tư duy có thể là công cụ hữu ích khi lên dàn ý bài luận."},{"en":"Statistical software is a useful tool for analyzing large datasets.","vi":"Phần mềm thống kê là công cụ hữu ích để phân tích tập dữ liệu lớn."}]','[]',NULL,'/ˈjuːsfəl tuːl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5683,'colloc-16-01',143,'valid argument','lập luận hợp lý','adj + n','[{"en":"She presented a valid argument supported by strong evidence.","vi":"Cô ấy đưa ra một lập luận hợp lý được hỗ trợ bằng bằng chứng vững chắc."},{"en":"A valid argument must follow logically from its premises.","vi":"Một lập luận hợp lý phải suy ra logic từ các tiền đề của nó."},{"en":"The essay builds a valid argument against unrestricted social media.","vi":"Bài luận xây dựng một lập luận hợp lý chống lại mạng xã hội không giới hạn."}]','[]',NULL,'/ˈvælɪd ˈɑːrgjəmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5684,'colloc-16-01',144,'valuable information','thông tin quý giá','adj + n','[{"en":"The experiment produced valuable information about the chemical reaction.","vi":"Thí nghiệm tạo ra thông tin quý giá về phản ứng hóa học."},{"en":"Patients provided valuable information that improved the treatment plan.","vi":"Bệnh nhân cung cấp thông tin quý giá giúp cải thiện phác đồ điều trị."},{"en":"Field notes often contain valuable information for later analysis.","vi":"Ghi chép thực địa thường chứa thông tin quý giá cho phân tích sau này."}]','[]',NULL,'/ˈvæljəbəl ˌɪnfərˈmeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5685,'colloc-16-01',145,'valuable resources','nguồn lực quý giá','adj + n','[{"en":"The project wasted valuable resources on poorly planned activities.","vi":"Dự án lãng phí nguồn lực quý giá vào những hoạt động lập kế hoạch kém."},{"en":"Forests are valuable resources that must be protected carefully.","vi":"Rừng là nguồn lực quý giá cần được bảo vệ cẩn thận."},{"en":"Libraries offer valuable resources for independent academic research.","vi":"Thư viện cung cấp nguồn lực quý giá cho nghiên cứu học thuật độc lập."}]','[]',NULL,'/ˈvæljəbəl ˈriːsɔːrsɪz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5686,'colloc-16-01',146,'various aspects','nhiều khía cạnh khác nhau','adj + n','[{"en":"The course examines various aspects of modern economic theory.","vi":"Khóa học xem xét nhiều khía cạnh khác nhau của lý thuyết kinh tế hiện đại."},{"en":"Her study explored various aspects of childhood language development.","vi":"Nghiên cứu của cô khám phá nhiều khía cạnh của sự phát triển ngôn ngữ trẻ em."},{"en":"We discussed various aspects of the problem before deciding.","vi":"Chúng tôi thảo luận nhiều khía cạnh của vấn đề trước khi quyết định."}]','[]',NULL,'/ˈveriəs ˈæspekts/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5687,'colloc-16-01',147,'vary considerably','thay đổi đáng kể','v + adv','[{"en":"Prices vary considerably depending on the season and location.","vi":"Giá cả thay đổi đáng kể tùy theo mùa và địa điểm."},{"en":"Test results vary considerably between the two student groups.","vi":"Kết quả kiểm tra thay đổi đáng kể giữa hai nhóm sinh viên."},{"en":"Opinions on the policy vary considerably across different regions.","vi":"Ý kiến về chính sách thay đổi đáng kể giữa các khu vực khác nhau."}]','[]',NULL,'/ˈveri kənˈsɪdərəbli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5688,'colloc-16-01',148,'vary greatly','thay đổi rất nhiều','v + adv','[{"en":"Living costs vary greatly from one city to another.","vi":"Chi phí sinh hoạt thay đổi rất nhiều từ thành phố này sang thành phố khác."},{"en":"Students'' learning styles vary greatly within a single classroom.","vi":"Phong cách học của học sinh thay đổi rất nhiều trong cùng một lớp."},{"en":"The quality of online courses can vary greatly nowadays.","vi":"Chất lượng các khóa học trực tuyến ngày nay có thể thay đổi rất nhiều."}]','[]',NULL,'/ˈveri ˈgreɪtli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5689,'colloc-16-01',149,'vary significantly','thay đổi rõ rệt','v + adv','[{"en":"Wages vary significantly across industries and levels of experience.","vi":"Tiền lương thay đổi rõ rệt giữa các ngành và mức kinh nghiệm."},{"en":"The findings vary significantly depending on the research method used.","vi":"Kết quả thay đổi rõ rệt tùy thuộc vào phương pháp nghiên cứu được dùng."},{"en":"Temperatures vary significantly between the coastal and inland areas.","vi":"Nhiệt độ thay đổi rõ rệt giữa khu vực ven biển và nội địa."}]','[]',NULL,'/ˈveri sɪgˈnɪfɪkəntli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5690,'colloc-16-01',150,'vary widely','thay đổi rất khác nhau','v + adv','[{"en":"Cultural attitudes toward time vary widely around the world.","vi":"Quan niệm văn hóa về thời gian thay đổi rất khác nhau trên thế giới."},{"en":"Estimates of the population vary widely among different sources.","vi":"Ước tính dân số thay đổi rất khác nhau giữa các nguồn."},{"en":"The prices of textbooks vary widely between online retailers.","vi":"Giá sách giáo khoa thay đổi rất khác nhau giữa các nhà bán lẻ trực tuyến."}]','[]',NULL,'/ˈveri ˈwaɪdli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5691,'colloc-17-01',1,'varying degree','mức độ khác nhau','adj + n','[{"en":"Students showed a varying degree of interest in the topic.","vi":"Học sinh thể hiện mức độ quan tâm khác nhau đối với chủ đề."},{"en":"The reforms succeeded to a varying degree across different schools.","vi":"Các cải cách thành công ở mức độ khác nhau giữa các trường."},{"en":"Participants experienced stress to a varying degree during the study.","vi":"Người tham gia trải qua căng thẳng ở mức độ khác nhau trong nghiên cứu."}]','[]',NULL,'/ˈveriɪŋ dɪˈgriː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5692,'colloc-17-01',2,'vast amount of','một lượng khổng lồ','adj + n','[{"en":"Modern science generates a vast amount of data daily.","vi":"Khoa học hiện đại tạo ra một lượng dữ liệu khổng lồ mỗi ngày."},{"en":"Writing a thesis requires a vast amount of careful reading.","vi":"Viết luận văn đòi hỏi một lượng đọc kỹ lưỡng khổng lồ."},{"en":"The project consumed a vast amount of time and money.","vi":"Dự án tiêu tốn một lượng thời gian và tiền bạc khổng lồ."}]','[]',NULL,'/væst əˈmaʊnt əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5693,'colloc-17-01',3,'vast area','khu vực rộng lớn','adj + n','[{"en":"The fire destroyed a vast area of ancient forest.","vi":"Đám cháy phá hủy một khu vực rừng cổ rộng lớn."},{"en":"Satellites can monitor a vast area of the ocean simultaneously.","vi":"Vệ tinh có thể giám sát một khu vực đại dương rộng lớn cùng lúc."},{"en":"The survey covered a vast area of rural farmland.","vi":"Cuộc khảo sát bao phủ một khu vực đất nông nghiệp rộng lớn."}]','[]',NULL,'/væst ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5694,'colloc-17-01',4,'vast array of','một loạt phong phú','adj + n','[{"en":"The museum displays a vast array of historical artifacts.","vi":"Bảo tàng trưng bày một loạt phong phú các hiện vật lịch sử."},{"en":"Students can choose from a vast array of elective courses.","vi":"Sinh viên có thể chọn từ một loạt phong phú các môn tự chọn."},{"en":"The library houses a vast array of academic publications.","vi":"Thư viện lưu giữ một loạt phong phú các ấn phẩm học thuật."}]','[]',NULL,'/væst əˈreɪ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5695,'colloc-17-01',5,'vast majority','đại đa số','adj + n','[{"en":"The vast majority of students passed the final examination.","vi":"Đại đa số sinh viên đã đậu kỳ thi cuối kỳ."},{"en":"A vast majority of respondents supported the new policy.","vi":"Đại đa số người được hỏi ủng hộ chính sách mới."},{"en":"The vast majority of cases were resolved within a week.","vi":"Đại đa số các trường hợp được giải quyết trong một tuần."}]','[]',NULL,'/væst məˈdʒɔːrəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5696,'colloc-17-01',6,'vast number','số lượng khổng lồ','adj + n','[{"en":"A vast number of species remain undiscovered in the rainforest.","vi":"Một số lượng khổng lồ các loài vẫn chưa được phát hiện trong rừng nhiệt đới."},{"en":"The campaign reached a vast number of young voters.","vi":"Chiến dịch tiếp cận được một số lượng khổng lồ cử tri trẻ."},{"en":"Researchers analyzed a vast number of documents for the study.","vi":"Các nhà nghiên cứu phân tích một số lượng khổng lồ tài liệu cho nghiên cứu."}]','[]',NULL,'/væst ˈnʌmbər/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5697,'colloc-17-01',7,'vast quantities of','lượng lớn khổng lồ','adj + n','[{"en":"Factories release vast quantities of waste into the rivers.","vi":"Các nhà máy thải lượng lớn khổng lồ chất thải ra sông."},{"en":"The country imports vast quantities of oil each year.","vi":"Quốc gia nhập khẩu lượng lớn khổng lồ dầu mỗi năm."},{"en":"Vast quantities of data are stored in modern cloud systems.","vi":"Lượng lớn khổng lồ dữ liệu được lưu trữ trong các hệ thống đám mây hiện đại."}]','[]',NULL,'/væst ˈkwɑːntətiz əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5698,'colloc-17-01',8,'vast range of','phạm vi rộng lớn','adj + n','[{"en":"The conference covered a vast range of scientific topics.","vi":"Hội nghị bao quát một phạm vi rộng lớn các chủ đề khoa học."},{"en":"This platform offers a vast range of online learning tools.","vi":"Nền tảng này cung cấp một phạm vi rộng lớn các công cụ học trực tuyến."},{"en":"Her research addresses a vast range of social issues.","vi":"Nghiên cứu của cô đề cập đến một phạm vi rộng lớn các vấn đề xã hội."}]','[]',NULL,'/væst reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5699,'colloc-17-01',9,'verbal communication','giao tiếp bằng lời','adj + n','[{"en":"Effective verbal communication is essential in clinical practice.","vi":"Giao tiếp bằng lời hiệu quả là điều thiết yếu trong thực hành lâm sàng."},{"en":"The course aims to improve students'' verbal communication skills.","vi":"Khóa học nhằm cải thiện kỹ năng giao tiếp bằng lời của sinh viên."},{"en":"Verbal communication often conveys emotion more directly than text.","vi":"Giao tiếp bằng lời thường truyền tải cảm xúc trực tiếp hơn văn bản."}]','[]',NULL,'/ˈvɜːrbəl kəˌmjuːnɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5700,'colloc-17-01',10,'verbal language','ngôn ngữ nói','adj + n','[{"en":"Children acquire verbal language naturally through daily interaction.","vi":"Trẻ em tiếp thu ngôn ngữ nói một cách tự nhiên qua tương tác hằng ngày."},{"en":"Verbal language and gestures together shape how meaning is understood.","vi":"Ngôn ngữ nói và cử chỉ cùng định hình cách hiểu ý nghĩa."},{"en":"The study compared verbal language across several cultural groups.","vi":"Nghiên cứu so sánh ngôn ngữ nói giữa nhiều nhóm văn hóa."}]','[]',NULL,'/ˈvɜːrbəl ˈlæŋgwɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5701,'colloc-17-01',11,'vested interest','lợi ích cá nhân gắn liền','adj + n','[{"en":"Companies have a vested interest in shaping public opinion.","vi":"Các công ty có lợi ích cá nhân gắn liền trong việc định hình dư luận."},{"en":"Politicians with a vested interest may resist genuine reform.","vi":"Các chính trị gia có lợi ích cá nhân gắn liền có thể chống lại cải cách thực sự."},{"en":"Researchers must declare any vested interest in their findings.","vi":"Nhà nghiên cứu phải khai báo mọi lợi ích cá nhân gắn liền với kết quả."}]','[]',NULL,'/ˈvestɪd ˈɪntrəst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5702,'colloc-17-01',12,'virtual community','cộng đồng ảo','adj + n','[{"en":"Online forums help create a strong virtual community of learners.","vi":"Các diễn đàn trực tuyến giúp tạo ra một cộng đồng ảo người học vững mạnh."},{"en":"A virtual community can offer support across great distances.","vi":"Một cộng đồng ảo có thể hỗ trợ lẫn nhau dù cách xa về khoảng cách."},{"en":"The study examined how a virtual community shapes its members'' identity.","vi":"Nghiên cứu xem xét cách một cộng đồng ảo định hình bản sắc của thành viên."}]','[]',NULL,'/ˈvɜːrtʃuəl kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5703,'colloc-17-01',13,'virtually impossible','gần như không thể','adv + adj','[{"en":"It is virtually impossible to predict the stock market precisely.","vi":"Gần như không thể dự đoán thị trường chứng khoán một cách chính xác."},{"en":"Without funding, completing the project was virtually impossible.","vi":"Không có kinh phí, việc hoàn thành dự án là gần như không thể."},{"en":"Reaching total agreement among all experts is virtually impossible.","vi":"Đạt được sự đồng thuận hoàn toàn giữa các chuyên gia là gần như không thể."}]','[]',NULL,'/ˈvɜːrtʃuəli ɪmˈpɑːsəbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5704,'colloc-17-01',14,'visual image','hình ảnh trực quan','adj + n','[{"en":"A strong visual image can make an argument more memorable.","vi":"Một hình ảnh trực quan mạnh có thể khiến lập luận đáng nhớ hơn."},{"en":"The advertisement relied on a single striking visual image.","vi":"Quảng cáo dựa vào một hình ảnh trực quan ấn tượng duy nhất."},{"en":"Our memory often stores a visual image more easily than words.","vi":"Trí nhớ của chúng ta thường lưu hình ảnh trực quan dễ hơn từ ngữ."}]','[]',NULL,'/ˈvɪʒuəl ˈɪmɪdʒ/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5705,'colloc-17-01',15,'visual media','phương tiện truyền thông hình ảnh','adj + n','[{"en":"Visual media now shape how young people understand world events.","vi":"Phương tiện truyền thông hình ảnh nay định hình cách giới trẻ hiểu các sự kiện thế giới."},{"en":"The lecture explored the growing influence of visual media.","vi":"Bài giảng khám phá ảnh hưởng ngày càng lớn của truyền thông hình ảnh."},{"en":"Teachers increasingly use visual media to engage their students.","vi":"Giáo viên ngày càng dùng truyền thông hình ảnh để thu hút học sinh."}]','[]',NULL,'/ˈvɪʒuəl ˈmiːdiə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5706,'colloc-17-01',16,'visual perception','tri giác thị giác','adj + n','[{"en":"Visual perception allows us to interpret depth and distance accurately.","vi":"Tri giác thị giác cho phép ta diễn giải độ sâu và khoảng cách chính xác."},{"en":"The experiment tested how lighting affects visual perception.","vi":"Thí nghiệm kiểm tra cách ánh sáng ảnh hưởng đến tri giác thị giác."},{"en":"Studies of visual perception reveal how the brain processes images.","vi":"Các nghiên cứu về tri giác thị giác cho thấy cách não xử lý hình ảnh."}]','[]',NULL,'/ˈvɪʒuəl pərˈsepʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5707,'colloc-17-01',17,'visual representation','biểu diễn trực quan','adj + n','[{"en":"A graph offers a clear visual representation of the trend.","vi":"Biểu đồ cung cấp một biểu diễn trực quan rõ ràng về xu hướng."},{"en":"The map provides a visual representation of population density.","vi":"Bản đồ cung cấp một biểu diễn trực quan về mật độ dân số."},{"en":"Diagrams give students a useful visual representation of the process.","vi":"Sơ đồ cho học sinh một biểu diễn trực quan hữu ích về quy trình."}]','[]',NULL,'/ˈvɪʒuəl ˌreprɪzenˈteɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5708,'colloc-17-01',18,'vital importance','tầm quan trọng sống còn','adj + n','[{"en":"Clean water is of vital importance to public health.","vi":"Nước sạch có tầm quan trọng sống còn đối với sức khỏe cộng đồng."},{"en":"Early diagnosis is of vital importance in treating cancer.","vi":"Chẩn đoán sớm có tầm quan trọng sống còn trong điều trị ung thư."},{"en":"Teamwork is of vital importance to the project''s success.","vi":"Làm việc nhóm có tầm quan trọng sống còn đối với thành công của dự án."}]','[]',NULL,'/ˈvaɪtəl ɪmˈpɔːrtəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5709,'colloc-17-01',19,'vital part','phần thiết yếu','adj + n','[{"en":"Feedback is a vital part of the learning process.","vi":"Phản hồi là một phần thiết yếu của quá trình học tập."},{"en":"Sleep forms a vital part of a healthy lifestyle.","vi":"Giấc ngủ là một phần thiết yếu của lối sống lành mạnh."},{"en":"Reading widely is a vital part of academic preparation.","vi":"Đọc rộng là một phần thiết yếu của việc chuẩn bị học thuật."}]','[]',NULL,'/ˈvaɪtəl pɑːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5710,'colloc-17-01',20,'vital role','vai trò thiết yếu','adj + n','[{"en":"Teachers play a vital role in shaping young minds.","vi":"Giáo viên đóng vai trò thiết yếu trong việc hình thành tư duy trẻ."},{"en":"Bees play a vital role in pollinating food crops.","vi":"Ong đóng vai trò thiết yếu trong việc thụ phấn cho cây lương thực."},{"en":"Technology plays a vital role in modern medical research.","vi":"Công nghệ đóng vai trò thiết yếu trong nghiên cứu y học hiện đại."}]','[]',NULL,'/ˈvaɪtəl roʊl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5711,'colloc-17-01',21,'vulnerable group','nhóm dễ bị tổn thương','adj + n','[{"en":"The policy aims to protect vulnerable groups during economic crises.","vi":"Chính sách nhằm bảo vệ các nhóm dễ bị tổn thương trong khủng hoảng kinh tế."},{"en":"Elderly people are often a particularly vulnerable group.","vi":"Người cao tuổi thường là một nhóm đặc biệt dễ bị tổn thương."},{"en":"Researchers focused on vulnerable groups affected by the disaster.","vi":"Các nhà nghiên cứu tập trung vào các nhóm dễ bị tổn thương bởi thảm họa."}]','[]',NULL,'/ˈvʌlnərəbəl gruːp/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5712,'colloc-17-01',22,'welfare reform','cải cách phúc lợi','n + n','[{"en":"The government introduced welfare reform to reduce dependency on benefits.","vi":"Chính phủ đưa ra cải cách phúc lợi để giảm sự phụ thuộc vào trợ cấp."},{"en":"Critics argued that welfare reform harmed the poorest families.","vi":"Các nhà phê bình cho rằng cải cách phúc lợi làm tổn hại các gia đình nghèo nhất."},{"en":"Welfare reform remains a controversial topic among policymakers.","vi":"Cải cách phúc lợi vẫn là chủ đề gây tranh cãi giữa các nhà hoạch định chính sách."}]','[]',NULL,'/ˈwelfer rɪˈfɔːrm/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5713,'colloc-17-01',23,'well aware','nhận thức rõ','adv + adj','[{"en":"The author is well aware of the study''s limitations.","vi":"Tác giả nhận thức rõ những hạn chế của nghiên cứu."},{"en":"Students should be well aware of the deadline requirements.","vi":"Sinh viên nên nhận thức rõ các yêu cầu về thời hạn nộp bài."},{"en":"Managers were well aware of the risks before deciding.","vi":"Các quản lý đã nhận thức rõ các rủi ro trước khi quyết định."}]','[]',NULL,'/wel əˈwer/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5714,'colloc-17-01',24,'well designed','được thiết kế tốt','adv + vpp','[{"en":"A well designed experiment controls for unwanted variables.","vi":"Một thí nghiệm được thiết kế tốt kiểm soát các biến không mong muốn."},{"en":"The well designed survey produced clear and reliable results.","vi":"Cuộc khảo sát được thiết kế tốt cho ra kết quả rõ ràng và đáng tin cậy."},{"en":"Well designed buildings make efficient use of natural light.","vi":"Các tòa nhà được thiết kế tốt tận dụng hiệu quả ánh sáng tự nhiên."}]','[]',NULL,'/wel dɪˈzaɪnd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5715,'colloc-17-01',25,'well documented','được ghi chép đầy đủ','adv + vpp','[{"en":"The effects of smoking are well documented in medical literature.","vi":"Tác hại của hút thuốc đã được ghi chép đầy đủ trong tài liệu y học."},{"en":"Her claims are well documented with reliable primary sources.","vi":"Các khẳng định của cô được ghi chép đầy đủ bằng nguồn sơ cấp đáng tin cậy."},{"en":"This phenomenon is well documented across several earlier studies.","vi":"Hiện tượng này được ghi chép đầy đủ trong nhiều nghiên cứu trước đó."}]','[]',NULL,'/wel ˈdɑːkjəmentɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5716,'colloc-17-01',26,'well educated','có học thức cao','adv + vpp','[{"en":"A well educated workforce is essential for economic growth.","vi":"Một lực lượng lao động có học thức cao là thiết yếu cho tăng trưởng kinh tế."},{"en":"Well educated citizens tend to participate more in politics.","vi":"Công dân có học thức cao thường tham gia chính trị nhiều hơn."},{"en":"The company prefers candidates who are well educated and adaptable.","vi":"Công ty ưu tiên ứng viên có học thức cao và dễ thích nghi."}]','[]',NULL,'/wel ˈedʒəkeɪtɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5717,'colloc-17-01',27,'well established','đã được khẳng định vững chắc','adv + vpp','[{"en":"The link between diet and health is well established.","vi":"Mối liên hệ giữa chế độ ăn và sức khỏe đã được khẳng định vững chắc."},{"en":"She joined a well established research team at the university.","vi":"Cô gia nhập một nhóm nghiên cứu đã được khẳng định vững chắc ở trường đại học."},{"en":"This theory is well established and widely taught today.","vi":"Lý thuyết này đã được khẳng định vững chắc và được giảng dạy rộng rãi ngày nay."}]','[]',NULL,'/wel ɪˈstæblɪʃt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5718,'colloc-17-01',28,'well received','được đón nhận tốt','adv + vpp','[{"en":"Her presentation was well received by the entire committee.","vi":"Bài thuyết trình của cô được toàn bộ hội đồng đón nhận tốt."},{"en":"The new policy was well received among local residents.","vi":"Chính sách mới được người dân địa phương đón nhận tốt."},{"en":"The book was well received by critics and readers alike.","vi":"Cuốn sách được cả giới phê bình lẫn độc giả đón nhận tốt."}]','[]',NULL,'/wel rɪˈsiːvd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5719,'colloc-17-01',29,'western democracy','nền dân chủ phương Tây','adj + n','[{"en":"Western democracy relies on free elections and a free press.","vi":"Nền dân chủ phương Tây dựa vào bầu cử tự do và báo chí tự do."},{"en":"The essay compares western democracy with other political systems.","vi":"Bài luận so sánh nền dân chủ phương Tây với các hệ thống chính trị khác."},{"en":"Many scholars debate the future of western democracy today.","vi":"Nhiều học giả tranh luận về tương lai của nền dân chủ phương Tây hiện nay."}]','[]',NULL,'/ˈwestərn dɪˈmɑːkrəsi/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5720,'colloc-17-01',30,'western society','xã hội phương Tây','adj + n','[{"en":"Individualism is a strong value in western society.","vi":"Chủ nghĩa cá nhân là một giá trị mạnh trong xã hội phương Tây."},{"en":"Western society has changed rapidly with new technology.","vi":"Xã hội phương Tây đã thay đổi nhanh chóng với công nghệ mới."},{"en":"The study examines aging populations across western society.","vi":"Nghiên cứu xem xét tình trạng dân số già hóa trong xã hội phương Tây."}]','[]',NULL,'/ˈwestərn səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5721,'colloc-17-01',31,'western tradition','truyền thống phương Tây','adj + n','[{"en":"The course traces the western tradition of philosophical thought.","vi":"Khóa học truy nguyên truyền thống tư tưởng triết học phương Tây."},{"en":"This artwork blends eastern and western tradition beautifully.","vi":"Tác phẩm này kết hợp truyền thống phương Đông và phương Tây một cách đẹp đẽ."},{"en":"Western tradition has deeply shaped modern legal systems.","vi":"Truyền thống phương Tây đã định hình sâu sắc các hệ thống pháp luật hiện đại."}]','[]',NULL,'/ˈwestərn trəˈdɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5722,'colloc-17-01',32,'whole area','toàn bộ lĩnh vực','adj + n','[{"en":"The whole area of cognitive science has grown rapidly.","vi":"Toàn bộ lĩnh vực khoa học nhận thức đã phát triển nhanh chóng."},{"en":"Her research opened up a whole area of inquiry.","vi":"Nghiên cứu của cô mở ra toàn bộ một lĩnh vực tìm hiểu mới."},{"en":"The flood damaged the whole area surrounding the river.","vi":"Lũ lụt làm hư hại toàn bộ khu vực xung quanh con sông."}]','[]',NULL,'/hoʊl ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5723,'colloc-17-01',33,'whole period','toàn bộ giai đoạn','adj + n','[{"en":"Sales remained stable throughout the whole period of study.","vi":"Doanh số ổn định suốt toàn bộ giai đoạn nghiên cứu."},{"en":"The data were collected over the whole period of treatment.","vi":"Dữ liệu được thu thập trong toàn bộ giai đoạn điều trị."},{"en":"Temperatures rose gradually during the whole period observed.","vi":"Nhiệt độ tăng dần trong toàn bộ giai đoạn được quan sát."}]','[]',NULL,'/hoʊl ˈpɪriəd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5724,'colloc-17-01',34,'whole range of','toàn bộ phạm vi','adj + n','[{"en":"The program offers a whole range of support services.","vi":"Chương trình cung cấp toàn bộ một phạm vi các dịch vụ hỗ trợ."},{"en":"Climate change affects a whole range of natural systems.","vi":"Biến đổi khí hậu ảnh hưởng đến toàn bộ một phạm vi các hệ thống tự nhiên."},{"en":"Her job involves a whole range of administrative tasks.","vi":"Công việc của cô bao gồm toàn bộ một phạm vi các nhiệm vụ hành chính."}]','[]',NULL,'/hoʊl reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5725,'colloc-17-01',35,'wide area','khu vực rộng','adj + n','[{"en":"The new network covers a wide area of the city.","vi":"Mạng lưới mới bao phủ một khu vực rộng của thành phố."},{"en":"Pollution from the factory spread over a wide area.","vi":"Ô nhiễm từ nhà máy lan rộng trên một khu vực rộng."},{"en":"The drought affected a wide area of farmland this year.","vi":"Hạn hán ảnh hưởng đến một khu vực rộng đất nông nghiệp năm nay."}]','[]',NULL,'/waɪd ˈeriə/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5726,'colloc-17-01',36,'wide array of','một loạt đa dạng','adj + n','[{"en":"The festival featured a wide array of cultural performances.","vi":"Lễ hội có một loạt đa dạng các tiết mục văn hóa."},{"en":"Students explored a wide array of career options at the fair.","vi":"Sinh viên khám phá một loạt đa dạng lựa chọn nghề nghiệp tại hội chợ."},{"en":"The report addresses a wide array of environmental concerns.","vi":"Báo cáo đề cập một loạt đa dạng các mối quan ngại về môi trường."}]','[]',NULL,'/waɪd əˈreɪ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5727,'colloc-17-01',37,'wide range of','phạm vi rộng','adj + n','[{"en":"The library holds books on a wide range of subjects.","vi":"Thư viện có sách về một phạm vi rộng các môn học."},{"en":"The survey gathered views from a wide range of people.","vi":"Cuộc khảo sát thu thập quan điểm từ một phạm vi rộng người dân."},{"en":"Her work draws on a wide range of academic disciplines.","vi":"Công trình của cô dựa trên một phạm vi rộng các ngành học thuật."}]','[]',NULL,'/waɪd reɪndʒ əv/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5728,'colloc-17-01',38,'wide variation','sự dao động rộng','adj + n','[{"en":"There is wide variation in income across the region.","vi":"Có sự dao động rộng về thu nhập trên khắp khu vực."},{"en":"The study found wide variation in students'' test scores.","vi":"Nghiên cứu phát hiện sự dao động rộng trong điểm thi của học sinh."},{"en":"Wide variation in rainfall makes farming difficult to plan.","vi":"Sự dao động rộng về lượng mưa khiến việc canh tác khó lên kế hoạch."}]','[]',NULL,'/waɪd ˌveriˈeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5729,'colloc-17-01',39,'widely accepted','được chấp nhận rộng rãi','adv + vpp','[{"en":"This theory is now widely accepted within the scientific community.","vi":"Lý thuyết này nay được chấp nhận rộng rãi trong cộng đồng khoa học."},{"en":"It is widely accepted that exercise improves mental health.","vi":"Người ta chấp nhận rộng rãi rằng tập thể dục cải thiện sức khỏe tinh thần."},{"en":"The method became widely accepted after repeated successful trials.","vi":"Phương pháp này được chấp nhận rộng rãi sau nhiều thử nghiệm thành công."}]','[]',NULL,'/ˈwaɪdli əkˈseptɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5730,'colloc-17-01',40,'widely adopted','được áp dụng rộng rãi','adv + vpp','[{"en":"The new standard was widely adopted across the industry.","vi":"Tiêu chuẩn mới được áp dụng rộng rãi trong toàn ngành."},{"en":"Renewable technologies are being widely adopted in many countries.","vi":"Công nghệ tái tạo đang được áp dụng rộng rãi ở nhiều quốc gia."},{"en":"The teaching approach was widely adopted in primary schools.","vi":"Phương pháp giảng dạy được áp dụng rộng rãi ở các trường tiểu học."}]','[]',NULL,'/ˈwaɪdli əˈdɑːptɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5731,'colloc-17-01',41,'widely available','có sẵn rộng rãi','adv + adj','[{"en":"Vaccines are now widely available in most rural areas.","vi":"Vắc-xin nay có sẵn rộng rãi ở hầu hết các vùng nông thôn."},{"en":"Online courses have made education more widely available.","vi":"Các khóa học trực tuyến đã làm cho giáo dục có sẵn rộng rãi hơn."},{"en":"Such data is widely available through government websites.","vi":"Dữ liệu như vậy có sẵn rộng rãi qua các trang web chính phủ."}]','[]',NULL,'/ˈwaɪdli əˈveɪləbəl/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5732,'colloc-17-01',42,'widely believed','được tin tưởng rộng rãi','adv + vpp','[{"en":"It is widely believed that early intervention improves outcomes.","vi":"Người ta tin tưởng rộng rãi rằng can thiệp sớm cải thiện kết quả."},{"en":"This myth was widely believed for many centuries.","vi":"Lầm tưởng này được tin tưởng rộng rãi trong nhiều thế kỷ."},{"en":"It is widely believed that the policy will reduce unemployment.","vi":"Người ta tin tưởng rộng rãi rằng chính sách sẽ giảm thất nghiệp."}]','[]',NULL,'/ˈwaɪdli bɪˈliːvd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5733,'colloc-17-01',43,'widely different','khác nhau rõ rệt','adv + adj','[{"en":"The two studies reached widely different conclusions about the cause.","vi":"Hai nghiên cứu đi đến những kết luận khác nhau rõ rệt về nguyên nhân."},{"en":"Participants came from widely different social backgrounds.","vi":"Người tham gia đến từ những hoàn cảnh xã hội khác nhau rõ rệt."},{"en":"Their views on the issue were widely different from ours.","vi":"Quan điểm của họ về vấn đề khác nhau rõ rệt so với chúng tôi."}]','[]',NULL,'/ˈwaɪdli ˈdɪfərənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5734,'colloc-17-01',44,'widely discussed','được bàn luận rộng rãi','adv + vpp','[{"en":"The topic of climate change is widely discussed in classrooms.","vi":"Chủ đề biến đổi khí hậu được bàn luận rộng rãi trong lớp học."},{"en":"Her findings were widely discussed at the annual conference.","vi":"Phát hiện của cô được bàn luận rộng rãi tại hội nghị thường niên."},{"en":"This issue has been widely discussed in recent newspapers.","vi":"Vấn đề này đã được bàn luận rộng rãi trên báo chí gần đây."}]','[]',NULL,'/ˈwaɪdli dɪˈskʌst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5735,'colloc-17-01',45,'widely dispersed','phân tán rộng','adv + vpp','[{"en":"The population is widely dispersed across remote mountain villages.","vi":"Dân cư phân tán rộng khắp các ngôi làng miền núi xa xôi."},{"en":"Seeds are widely dispersed by wind and passing animals.","vi":"Hạt giống được phân tán rộng nhờ gió và động vật đi qua."},{"en":"The research samples were widely dispersed throughout the country.","vi":"Các mẫu nghiên cứu được phân tán rộng khắp cả nước."}]','[]',NULL,'/ˈwaɪdli dɪˈspɜːrst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5736,'colloc-17-01',46,'widely distributed','được phân bố rộng rãi','adv + vpp','[{"en":"This species is widely distributed across temperate regions.","vi":"Loài này được phân bố rộng rãi khắp các vùng ôn đới."},{"en":"The survey forms were widely distributed among the students.","vi":"Các phiếu khảo sát được phân bố rộng rãi giữa các sinh viên."},{"en":"Wealth is not widely distributed across the whole population.","vi":"Của cải không được phân bố rộng rãi trên toàn bộ dân số."}]','[]',NULL,'/ˈwaɪdli dɪˈstrɪbjutɪd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5737,'colloc-17-01',47,'widely known','được biết đến rộng rãi','adv + vpp','[{"en":"The scientist is widely known for her work on genetics.","vi":"Nhà khoa học được biết đến rộng rãi nhờ công trình về di truyền học."},{"en":"It is widely known that smoking causes serious illness.","vi":"Người ta biết đến rộng rãi rằng hút thuốc gây bệnh nghiêm trọng."},{"en":"This city is widely known for its historic architecture.","vi":"Thành phố này được biết đến rộng rãi nhờ kiến trúc lịch sử."}]','[]',NULL,'/ˈwaɪdli noʊn/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5738,'colloc-17-01',48,'widely read','được đọc rộng rãi','adv + vpp','[{"en":"Her novel became widely read across several generations.","vi":"Tiểu thuyết của bà trở nên được đọc rộng rãi qua nhiều thế hệ."},{"en":"The journal is widely read by researchers in the field.","vi":"Tạp chí được đọc rộng rãi bởi các nhà nghiên cứu trong lĩnh vực."},{"en":"This newspaper remains widely read despite the rise of online media.","vi":"Tờ báo này vẫn được đọc rộng rãi dù truyền thông trực tuyến phát triển."}]','[]',NULL,'/ˈwaɪdli red/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5739,'colloc-17-01',49,'widely recognized','được công nhận rộng rãi','adv + vpp','[{"en":"The brand is widely recognized for its high quality.","vi":"Thương hiệu được công nhận rộng rãi về chất lượng cao."},{"en":"It is widely recognized that education reduces poverty over time.","vi":"Người ta công nhận rộng rãi rằng giáo dục giảm nghèo theo thời gian."},{"en":"Her contribution to the field is widely recognized today.","vi":"Đóng góp của cô cho lĩnh vực này được công nhận rộng rãi ngày nay."}]','[]',NULL,'/ˈwaɪdli ˈrekəgnaɪzd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5740,'colloc-17-01',50,'widely regarded as','được xem rộng rãi là','adv + vpp','[{"en":"She is widely regarded as the leading expert in linguistics.","vi":"Cô được xem rộng rãi là chuyên gia hàng đầu về ngôn ngữ học."},{"en":"This book is widely regarded as a classic in its field.","vi":"Cuốn sách này được xem rộng rãi là tác phẩm kinh điển trong lĩnh vực."},{"en":"The reform is widely regarded as a major political success.","vi":"Cuộc cải cách được xem rộng rãi là một thành công chính trị lớn."}]','[]',NULL,'/ˈwaɪdli rɪˈgɑːrdɪd æz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5741,'colloc-17-01',51,'widely shared','được chia sẻ rộng rãi','adv + vpp','[{"en":"The post was widely shared across many social media platforms.","vi":"Bài đăng được chia sẻ rộng rãi trên nhiều nền tảng mạng xã hội."},{"en":"This concern is widely shared among parents and teachers.","vi":"Mối lo ngại này được chia sẻ rộng rãi giữa phụ huynh và giáo viên."},{"en":"The belief in fairness is widely shared across cultures.","vi":"Niềm tin vào sự công bằng được chia sẻ rộng rãi giữa các nền văn hóa."}]','[]',NULL,'/ˈwaɪdli ʃerd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5742,'colloc-17-01',52,'widely used','được sử dụng rộng rãi','adv + vpp','[{"en":"This software is widely used in academic data analysis.","vi":"Phần mềm này được sử dụng rộng rãi trong phân tích dữ liệu học thuật."},{"en":"English is widely used as a language of international research.","vi":"Tiếng Anh được sử dụng rộng rãi như ngôn ngữ của nghiên cứu quốc tế."},{"en":"The method is widely used because it is simple and reliable.","vi":"Phương pháp được sử dụng rộng rãi vì nó đơn giản và đáng tin cậy."}]','[]',NULL,'/ˈwaɪdli juːzd/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5743,'colloc-17-01',53,'wider audience','đối tượng khán giả rộng hơn','adj + n','[{"en":"Publishing online helps research reach a wider audience.","vi":"Xuất bản trực tuyến giúp nghiên cứu tiếp cận đối tượng khán giả rộng hơn."},{"en":"The author simplified the text to attract a wider audience.","vi":"Tác giả đơn giản hóa văn bản để thu hút đối tượng khán giả rộng hơn."},{"en":"Social media allows ideas to spread to a wider audience.","vi":"Mạng xã hội cho phép ý tưởng lan tới đối tượng khán giả rộng hơn."}]','[]',NULL,'/ˈwaɪdər ˈɔːdiəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5744,'colloc-17-01',54,'wider community','cộng đồng rộng lớn hơn','adj + n','[{"en":"The university shares its research with the wider community.","vi":"Trường đại học chia sẻ nghiên cứu với cộng đồng rộng lớn hơn."},{"en":"Volunteering builds stronger links with the wider community.","vi":"Hoạt động tình nguyện xây dựng liên kết bền chặt hơn với cộng đồng rộng lớn hơn."},{"en":"The project aims to benefit the wider community as well.","vi":"Dự án cũng nhằm mang lại lợi ích cho cộng đồng rộng lớn hơn."}]','[]',NULL,'/ˈwaɪdər kəˈmjuːnəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5745,'colloc-17-01',55,'wider context','bối cảnh rộng hơn','adj + n','[{"en":"The essay places the war in its wider context.","vi":"Bài luận đặt cuộc chiến trong bối cảnh rộng hơn của nó."},{"en":"Understanding the wider context helps interpret the findings correctly.","vi":"Hiểu bối cảnh rộng hơn giúp diễn giải kết quả một cách chính xác."},{"en":"We must consider the wider context of these economic changes.","vi":"Chúng ta phải xem xét bối cảnh rộng hơn của những thay đổi kinh tế này."}]','[]',NULL,'/ˈwaɪdər ˈkɑːntekst/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5746,'colloc-17-01',56,'wider implications','những hệ quả rộng hơn','adj + n','[{"en":"The study explores the wider implications of climate policy.","vi":"Nghiên cứu khám phá những hệ quả rộng hơn của chính sách khí hậu."},{"en":"These results have wider implications for public health planning.","vi":"Những kết quả này có hệ quả rộng hơn đối với việc lập kế hoạch y tế công cộng."},{"en":"We should not ignore the wider implications of this decision.","vi":"Chúng ta không nên bỏ qua những hệ quả rộng hơn của quyết định này."}]','[]',NULL,'/ˈwaɪdər ˌɪmplɪˈkeɪʃənz/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5747,'colloc-17-01',57,'wider issue','vấn đề rộng hơn','adj + n','[{"en":"This complaint points to a wider issue within the system.","vi":"Lời phàn nàn này chỉ ra một vấn đề rộng hơn trong hệ thống."},{"en":"The debate reflects a wider issue about social inequality.","vi":"Cuộc tranh luận phản ánh một vấn đề rộng hơn về bất bình đẳng xã hội."},{"en":"Her paper connects local data to a wider issue.","vi":"Bài viết của cô kết nối dữ liệu địa phương với một vấn đề rộng hơn."}]','[]',NULL,'/ˈwaɪdər ˈɪʃuː/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5748,'colloc-17-01',58,'wider public','công chúng rộng rãi hơn','adj + n','[{"en":"Scientists must explain their findings to the wider public.","vi":"Các nhà khoa học phải giải thích phát hiện của mình cho công chúng rộng rãi hơn."},{"en":"The campaign aimed to raise awareness among the wider public.","vi":"Chiến dịch nhằm nâng cao nhận thức trong công chúng rộng rãi hơn."},{"en":"The exhibition made the artworks accessible to the wider public.","vi":"Cuộc triển lãm giúp các tác phẩm dễ tiếp cận với công chúng rộng rãi hơn."}]','[]',NULL,'/ˈwaɪdər ˈpʌblɪk/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5749,'colloc-17-01',59,'wider society','xã hội rộng lớn hơn','adj + n','[{"en":"Schools prepare young people to contribute to wider society.","vi":"Trường học chuẩn bị cho người trẻ đóng góp cho xã hội rộng lớn hơn."},{"en":"The reform had positive effects on wider society overall.","vi":"Cuộc cải cách có tác động tích cực đến xã hội rộng lớn hơn nói chung."},{"en":"Such attitudes can spread quickly throughout wider society.","vi":"Những thái độ như vậy có thể lan nhanh khắp xã hội rộng lớn hơn."}]','[]',NULL,'/ˈwaɪdər səˈsaɪəti/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5750,'colloc-17-01',60,'widespread acceptance','sự chấp nhận rộng khắp','adj + n','[{"en":"The new theory gained widespread acceptance among researchers.","vi":"Lý thuyết mới giành được sự chấp nhận rộng khắp giữa các nhà nghiên cứu."},{"en":"Widespread acceptance of recycling took several decades to achieve.","vi":"Sự chấp nhận rộng khắp về tái chế phải mất vài thập kỷ mới đạt được."},{"en":"The idea has not yet won widespread acceptance in practice.","vi":"Ý tưởng này vẫn chưa giành được sự chấp nhận rộng khắp trong thực tế."}]','[]',NULL,'/ˈwaɪdspred əkˈseptəns/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5751,'colloc-17-01',61,'widespread belief','niềm tin phổ biến rộng rãi','adj + n','[{"en":"There is a widespread belief that money brings happiness.","vi":"Có một niềm tin phổ biến rộng rãi rằng tiền mang lại hạnh phúc."},{"en":"The study challenged the widespread belief about memory loss.","vi":"Nghiên cứu thách thức niềm tin phổ biến rộng rãi về mất trí nhớ."},{"en":"A widespread belief in fairness underpins many legal systems.","vi":"Một niềm tin phổ biến rộng rãi vào công bằng làm nền cho nhiều hệ thống pháp luật."}]','[]',NULL,'/ˈwaɪdspred bɪˈliːf/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5752,'colloc-17-01',62,'widespread support','sự ủng hộ rộng khắp','adj + n','[{"en":"The proposal received widespread support from local residents.","vi":"Đề xuất nhận được sự ủng hộ rộng khắp từ người dân địa phương."},{"en":"Widespread support helped the charity expand its programs quickly.","vi":"Sự ủng hộ rộng khắp giúp tổ chức từ thiện mở rộng chương trình nhanh chóng."},{"en":"The candidate enjoyed widespread support among younger voters.","vi":"Ứng cử viên nhận được sự ủng hộ rộng khắp trong cử tri trẻ."}]','[]',NULL,'/ˈwaɪdspred səˈpɔːrt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5753,'colloc-17-01',63,'widespread use','việc sử dụng rộng khắp','adj + n','[{"en":"The widespread use of smartphones has changed daily communication.","vi":"Việc sử dụng rộng khắp điện thoại thông minh đã thay đổi giao tiếp hằng ngày."},{"en":"Researchers warned against the widespread use of antibiotics.","vi":"Các nhà nghiên cứu cảnh báo về việc sử dụng rộng khắp kháng sinh."},{"en":"The widespread use of plastic creates serious environmental problems.","vi":"Việc sử dụng rộng khắp nhựa gây ra các vấn đề môi trường nghiêm trọng."}]','[]',NULL,'/ˈwaɪdspred juːs/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5754,'colloc-17-01',64,'work effectively','làm việc hiệu quả','v + adv','[{"en":"Students learn to work effectively in small collaborative groups.","vi":"Sinh viên học cách làm việc hiệu quả trong các nhóm hợp tác nhỏ."},{"en":"The team worked effectively despite the tight deadline.","vi":"Nhóm đã làm việc hiệu quả bất chấp thời hạn gấp rút."},{"en":"Good communication helps colleagues work effectively together.","vi":"Giao tiếp tốt giúp các đồng nghiệp làm việc hiệu quả cùng nhau."}]','[]',NULL,'/wɜːrk ɪˈfektɪvli/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5755,'colloc-17-01',65,'written comment','nhận xét bằng văn bản','adj + n','[{"en":"The teacher gave detailed written comments on each essay.","vi":"Giáo viên đưa ra nhận xét bằng văn bản chi tiết cho từng bài luận."},{"en":"Students valued the written comments more than the grades.","vi":"Sinh viên coi trọng nhận xét bằng văn bản hơn cả điểm số."},{"en":"Reviewers provided helpful written comments on the draft paper.","vi":"Người phản biện cung cấp nhận xét bằng văn bản hữu ích cho bản thảo."}]','[]',NULL,'/ˈrɪtən ˈkɑːment/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5756,'colloc-17-01',66,'written communication','giao tiếp bằng văn bản','adj + n','[{"en":"Clear written communication is essential in professional workplaces.","vi":"Giao tiếp bằng văn bản rõ ràng là điều thiết yếu ở nơi làm việc chuyên nghiệp."},{"en":"The course develops students'' written communication skills steadily.","vi":"Khóa học phát triển kỹ năng giao tiếp bằng văn bản của sinh viên một cách đều đặn."},{"en":"Email has become a dominant form of written communication.","vi":"Email đã trở thành một hình thức giao tiếp bằng văn bản phổ biến."}]','[]',NULL,'/ˈrɪtən kəˌmjuːnɪˈkeɪʃən/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5757,'colloc-17-01',67,'written statement','tuyên bố bằng văn bản','adj + n','[{"en":"The witness provided a written statement to the police.","vi":"Nhân chứng cung cấp một tuyên bố bằng văn bản cho cảnh sát."},{"en":"The company issued a written statement explaining its decision.","vi":"Công ty ra một tuyên bố bằng văn bản giải thích quyết định của mình."},{"en":"Applicants must submit a written statement of their goals.","vi":"Ứng viên phải nộp một tuyên bố bằng văn bản về mục tiêu của họ."}]','[]',NULL,'/ˈrɪtən ˈsteɪtmənt/',NULL,NULL,NULL);
INSERT INTO "preset_deck_cards" ("id","deck_code","position","english","vietnamese","part_of_speech","examples","collocations","notes","ipa","audio_src","image_url","image_attribution") VALUES(5758,'colloc-17-01',68,'younger generation','thế hệ trẻ hơn','adj + n','[{"en":"The younger generation increasingly relies on digital technology.","vi":"Thế hệ trẻ hơn ngày càng phụ thuộc vào công nghệ số."},{"en":"Traditional values are slowly changing within the younger generation.","vi":"Các giá trị truyền thống đang dần thay đổi trong thế hệ trẻ hơn."},{"en":"The younger generation tends to value flexible working arrangements.","vi":"Thế hệ trẻ hơn có xu hướng coi trọng các thỏa thuận làm việc linh hoạt."}]','[]',NULL,'/ˈjʌŋgər ˌdʒenəˈreɪʃən/',NULL,NULL,NULL);
